function _isLocked(address account, uint256 amount) internal view returns(bool) {
    return _lockAmounts[account] != 0 &&
        _lockTimes[account] > block.timestamp &&
        (
            balanceOf(account) <= _lockAmounts[account] ||
            balanceOf(account).sub(_lockAmounts[account]) < amount
        );
}

function setLock(address account, uint256 releaseTime, uint256 amount) onlyOwner public {
    require(block.timestamp < releaseTime, "ERC20 : Current time is greater than release time");
    require(amount != 0, "ERC20: Amount error");
    _lockTimes[account] = releaseTime;
    _lockAmounts[account] = amount;
    emit LockChanged(account, releaseTime, amount);
}

function executeTransaction(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
)
public
payable
returns(bytes memory)
{
    require(msg.sender == admin, "Timelock::executeTransaction: Call must come from admin.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    if (admin_initialized) {
        require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
        require(getBlockTimestamp() >= eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
        require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Timelock::executeTransaction: Transaction is stale.");
        queuedTransactions[txHash] = false;
    }
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call.value(value)(callData);
    require(success, "Timelock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function queueTransaction(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
)
public
returns(bytes32)
{
    require(msg.sender == admin, "Timelock::queueTransaction: Call must come from admin.");
    require(eta >= getBlockTimestamp().add(delay), "Timelock::queueTransaction: Estimated execution block must satisfy delay.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

function completeProposal(uint64 proposalID, address[] calldata stakers) external active pendingProposal(proposalID) noReentrancy {
    ProposalMetadata storage meta = proposals[proposalID];
    uint256 requirement;
    if ((meta.pType == ProposalType.Fund) || (meta.pType == ProposalType.MelodyRemoval)) {
        requirement = _stake.totalStaked().div(2).add(1);
    } else if (meta.pType == ProposalType.MelodyAddition) {
        requirement = _stake.totalStaked().div(3).mul(2).add(1);
    } else if ((meta.pType == ProposalType.StakeUpgrade) || (meta.pType == ProposalType.DAOUpgrade)) {
        requirement = _stake.totalStaked().div(5).mul(4).add(1);
    } else {
        require(false);
    }
    uint256 votes = 0;
    for (uint i = 0; i < stakers.length; i++) {
        if (_stake.lastClaim(stakers[i]) == block.timestamp) {
            continue;
        }
        require(meta.stakers[stakers[i]]);
        require(!used[proposalID][stakers[i]]);
        used[proposalID][stakers[i]] = true;
        votes = votes.add(_stake.staked(stakers[i]));
    }
    require(votes >= requirement);
    meta.completed = true;
    emit ProposalPassed(proposalID);
    if (meta.pType == ProposalType.Fund) {
        FundProposal memory proposal = _fundProposals[proposalID];
        require(_SEED.transfer(proposal.destination, proposal.amount));
    } else if (meta.pType == ProposalType.MelodyAddition) {
        _stake.addMelody(_melodyAdditionProposals[proposalID].melody);
    } else if (meta.pType == ProposalType.MelodyRemoval) {
        _stake.removeMelody(_melodyRemovalProposals[proposalID].melody);
    } else if (meta.pType == ProposalType.StakeUpgrade) {
        StakeUpgradeProposal memory proposal = _stakeUpgradeProposals[proposalID];
        for (uint i = 0; i < proposal.owned.length; i++) {
            _stake.upgrade(proposal.owned[i], proposal.newStake);
        }
        _stake.addMelody(address(proposal.newStake));
        _stake = ISeedStake(proposal.newStake);
    } else if (meta.pType == ProposalType.DAOUpgrade) {
        _upgrade = _daoUpgradeProposals[proposalID].newDAO;
        _stake.transferOwnership(_upgrade);
        forwardSEED();
    } else {
        require(false);
    }
}

function withdrawProposal(uint64 proposalID) external active pendingProposal(proposalID) {
    require(proposals[proposalID].creator == msg.sender);
    proposals[proposalID].completed = true;
    emit ProposalRemoved(proposalID);
}

function proposeMelodyAddition(address melody, string calldata info) external returns(uint64) {
    uint64 proposalID = _createNewProposal(ProposalType.MelodyAddition);
    _melodyAdditionProposals[proposalID] = MelodyAdditionProposal(melody, info);
    emit MelodyAdditionProposed(proposalID, melody);
    return proposalID;
}

function _createNewProposal(ProposalType pType) internal active returns(uint64) {
    require(_SEED.transferFrom(msg.sender, address(this), PROPOSAL_FEE));
    _nextProposalID += 1;
    emit NewProposal(_nextProposalID);
    ProposalMetadata storage meta = proposals[_nextProposalID];
    meta.pType = pType;
    meta.creator = msg.sender;
    meta.submitted = block.timestamp;
    meta.stakers[msg.sender] = true;
    emit ProposalVoteAdded(_nextProposalID, msg.sender);
    return _nextProposalID;
}

function proposeDAOUpgrade(address newDAO, string calldata info) external returns(uint64) {
    uint64 proposalID = _createNewProposal(ProposalType.DAOUpgrade);
    _daoUpgradeProposals[proposalID] = DAOUpgradeProposal(newDAO, info);
    emit DAOUpgradeProposed(proposalID, newDAO);
    return proposalID;
}

function proposeStakeUpgrade(address newStake, address[] calldata owned, string calldata info) external returns(uint64) {
    uint64 proposalID = _createNewProposal(ProposalType.StakeUpgrade);
    for (uint i = 0; i < owned.length; i++) {
        if (owned[i] == address(_SEED)) {
            break;
        }
        require(i != owned.length - 1);
    }
    _stakeUpgradeProposals[proposalID] = StakeUpgradeProposal(newStake, owned, info);
    emit StakeUpgradeProposed(proposalID, newStake);
    return proposalID;
}

function proposeMelodyRemoval(address melody, string calldata info) external returns(uint64) {
    uint64 proposalID = _createNewProposal(ProposalType.MelodyRemoval);
    _melodyRemovalProposals[proposalID] = MelodyRemovalProposal(melody, info);
    emit MelodyRemovalProposed(proposalID, melody);
    return proposalID;
}

function proposeFund(address destination, uint256 amount, string calldata info) external returns(uint64) {
    uint64 proposalID = _createNewProposal(ProposalType.Fund);
    _fundProposals[proposalID] = FundProposal(destination, amount, info);
    emit FundProposed(proposalID, destination, amount);
    return proposalID;
}

function unstakeTokens() public {
    uint balance = stakingBalance[msg.sender];
    require(balance > 0, "staking balance cannot be 0");
    aufToken.transfer(msg.sender, balance);
    stakingBalance[msg.sender] = 0;
    isStaking[msg.sender] = false;
}

function stakeTokens(uint _amount) public {
    require(_amount > 0, "amount cannot be 0");
    aufToken.transferFrom(msg.sender, address(this), _amount);
    stakingBalance[msg.sender] = stakingBalance[msg.sender] + _amount;
    if (!hasStaked[msg.sender]) {
        stakers.push(msg.sender);
    }
    isStaking[msg.sender] = true;
    hasStaked[msg.sender] = true;
}

function _normalRedeem(uint256 coinAmount, address receiver)
internal
notClosed
{
    require(!esm.isRedeemPaused(), "Redeem paused");
    address staker = msg.sender;
    require(coins[staker] > 0, "No collateral");
    require(coinAmount > 0, "The quantity is less than zero");
    require(coinAmount <= coins[staker], "input amount overflow");
    accuredToken(staker);
    uint256 tokenAmount = getInputToken(coinAmount);
    uint256 feeRate = params.feeRate();
    uint256 fee = tokenAmount.mul(feeRate).div(1000);
    uint256 move = tokenAmount.sub(fee);
    sFee = sFee.add(fee);
    token.transfer(blackhole, fee);
    coin.burn(staker, coinAmount);
    token.transfer(receiver, move);
    coins[staker] = coins[staker].sub(coinAmount);
    tokens[staker] = tokens[staker].sub(tokenAmount);
    totalCoin = totalCoin.sub(coinAmount);
    totalToken = totalToken.sub(tokenAmount);
    emit RedeemEvent(tokenAmount, move, fee, coinAmount);
}

function stake(uint256 coinAmount) external notClosed {
    require(!esm.isStakePaused(), "Stake paused");
    require(coinAmount > 0, "The quantity is less than the minimum");
    require(orcl.val() > 0, "Oracle price not initialized.");
    require(params.isNormal(orcl.val()), "Oin's price is too low.");
    address from = msg.sender;
    if (coins[from] == 0) {
        require(
            coinAmount >= params.minMint(),
            "First make coin must grater than 100."
        );
    }
    accuredToken(from);
    uint256 tokenAmount = getInputToken(coinAmount);
    token.transferFrom(from, address(this), tokenAmount);
    coin.mint(from, coinAmount);
    totalCoin = totalCoin.add(coinAmount);
    totalToken = totalToken.add(tokenAmount);
    coins[from] = coins[from].add(coinAmount);
    tokens[from] = tokens[from].add(tokenAmount);
    emit StakeEvent(tokenAmount, coinAmount);
}

function claimToken(address holder) public {
    accuredToken(holder);
    StakerState storage stakerState = stakerStates[holder];
    uint256 value = stakerState.reward.min(reward);
    require(value > 0, "The reward of address is zero.");
    token.transfer(holder, value);
    reward = reward.sub(value);
    stakerState.index = rewardState.index;
    stakerState.reward = stakerState.reward.sub(value);
    emit ClaimToken(holder, value);
}

function extractReward(address account, uint256 amount) external onlyOwner {
    require(amount <= reward, "withdraw overflow.");
    token.transfer(account, amount);
    reward = reward.sub(amount);
    emit ExtractReward(account, amount);
}

function _abnormalRedeem(uint256 coinAmount, address receiver) internal {
    require(esm.isClosed(), "System not Closed yet.");
    address from = msg.sender;
    require(coinAmount > 0, "The quantity is less than zero");
    require(coin.balanceOf(from) > 0, "The coin no balance.");
    require(coinAmount <= coin.balanceOf(from), "Coin balance exceed");
    uint256 tokenAmount = getInputToken(coinAmount);
    coin.burn(from, coinAmount);
    token.transfer(receiver, tokenAmount);
    totalCoin = totalCoin.sub(coinAmount);
    totalToken = totalToken.sub(tokenAmount);
    emit RedeemEvent(tokenAmount, tokenAmount, 0, coinAmount);
}

function injectReward(uint256 amount) external onlyOwner {
    token.transferFrom(msg.sender, address(this), amount);
    reward = reward.add(amount);
    emit InjectReward(amount);
}

function deposit() public payable {
    uint256 currentDay = _getCurrentDay();
    uint256 len = logsContractFeeDays[msg.sender].length;
    if (len == 0) {
        logsContractFeeDays[msg.sender].push(currentDay);
        logsContractFeeAmounts[msg.sender].push(msg.value);
    } else {
        uint256 lastIndex = logsContractFeeDays[msg.sender].length.sub(1);
        uint256 lastDay = logsContractFeeDays[msg.sender][lastIndex];
        if (lastDay == currentDay) {
            logsContractFeeAmounts[msg
                    .sender][lastIndex] = logsContractFeeAmounts[msg
                    .sender][lastIndex]
                .add(msg.value);
        } else {
            logsContractFeeDays[msg.sender].push(currentDay);
            logsContractFeeAmounts[msg.sender].push(msg.value);
        }
    }
    uint256 toSuperAdmin = msg.value.mul(superAdminFeeNumerator).div(
        superAdminFeeDenominator
    );
    logsSumFeeAmount = logsSumFeeAmount.add(msg.value);
    superAdmin.transfer(toSuperAdmin);
}

function _find(
    uint256[] memory _Days,
    uint256[] memory _Units,
    uint256 day
) internal pure returns(uint256, uint256) {
    uint256 left = 0;
    uint256 right = _Days.length.sub(1);
    uint256 middle = right.add(left).div(2);
    while (_Days[middle] != day && left < right) {
        if (_Days[middle] > day) {
            right = middle.sub(1);
        } else if (_Days[middle] < day) {
            left = middle.add(1);
        }
        middle = right.add(left).div(2);
    }
    if (_Days[middle] != day) {
        return (day, 0);
    } else {
        return (day, _Units[middle]);
    }
}

function _get(
    uint256[] memory _Days,
    uint256[] memory _Units,
    uint256 day
) internal pure returns(uint256, uint256) {
    uint256 len = _Days.length;
    if (len == 0) {
        return (day, 0);
    }
    if (day < _Days[0]) {
        return (day, 0);
    }
    uint256 lastIndex = len.sub(1);
    uint256 lastDay = _Days[lastIndex];
    if (day == lastDay) {
        return (day, _Units[lastIndex]);
    }
    return _find(_Days, _Units, day);
}

function getTokenPrice(address token, uint256 day) external view returns(uint256) {
    require(_tokenExists(token), 'invalid token');
    require(day >= tokenDayStart[token], '1: invalid day');
    require(day <= dayLastRecordedPricesFor, '2: invalid day');
    return tokenDayPrice[token][day];
}

function _getRoundBeforeTimestamp(address token, uint256 timestamp) internal view returns(uint64) {
    uint64 left = tokenRoundLatest[token];
    (uint80 roundId, , , , ) = priceFeeds[token].latestRoundData();
    (, uint64 right) = _getPhaseIdRoundId(roundId);
    uint64 middle = (right + left) / 2;
    while (left <= right) {
        roundId = _makeCombinedId(oraclePhase[token], middle);
        (, , , uint256 roundTimestamp, ) = priceFeeds[token].getRoundData(roundId);
        if (roundTimestamp == timestamp) {
            return middle - 1;
        } else if (roundTimestamp < timestamp) {
            left = middle + 1;
        } else {
            right = middle - 1;
        }
        middle = (right + left) / 2;
    }
    return middle;
}

function upToDate() external view returns(bool) {
    return dayLastRecordedPricesFor == _getCurrentDay().sub(1);
}

function getTokenPrices(uint256 day) external view returns(uint256[] memory) {
    require(day <= dayLastRecordedPricesFor, 'invalid day');
    uint256[] memory prices = new uint256[](tokens.length);
    for (uint256 i = 0; i < tokens.length; i++) {
        address token = tokens[i];
        prices[i] = tokenDayPrice[token][day];
    }
    return prices;
}

function recordTokenPrices() public {
    require(_getCurrentDay() > dayLastRecordedPricesFor.add(1), 'already recorded');
    dayLastRecordedPricesFor = dayLastRecordedPricesFor.add(1);
    for (uint256 i = 0; i < tokens.length; i++) {
        (uint80 roundId, , , , ) = priceFeeds[tokens[i]].latestRoundData();
        (uint16 phase, ) = _getPhaseIdRoundId(roundId);
        if (oraclePhase[tokens[i]] != phase) {
            oraclePhase[tokens[i]] = phase;
            _cacheToken(tokens[i], _dayToTimestamp(dayLastRecordedPricesFor));
        }
        tokenDayPrice[tokens[i]][dayLastRecordedPricesFor] = _getDayClosingPrice(tokens[i], dayLastRecordedPricesFor);
    }
    emit TokenPricesRecorded(dayLastRecordedPricesFor);
}

function state(uint256 proposalId) public view returns(ProposalState) {
    require(proposalCount >= proposalId && proposalId > 0, 'sbGovernor::state: invalid proposal id');
    Proposal storage proposal = proposals[proposalId];
    if (proposal.canceled) {
        return ProposalState.Canceled;
    } else if (block.number <= proposal.startBlock) {
        return ProposalState.Pending;
    } else if (block.number <= proposal.endBlock) {
        return ProposalState.Active;
    } else if (proposal.forVotes <= proposal.againstVotes || proposal.forVotes < quorumVotes()) {
        return ProposalState.Defeated;
    } else if (proposal.eta == 0) {
        return ProposalState.Succeeded;
    } else if (proposal.executed) {
        return ProposalState.Executed;
    } else if (block.timestamp >= add256(proposal.eta, sbTimelock.GRACE_PERIOD())) {
        return ProposalState.Expired;
    } else {
        return ProposalState.Queued;
    }
}

function cancel(uint256 proposalId) public {
    ProposalState state = state(proposalId);
    require(state != ProposalState.Executed, 'sbGovernor::cancel: cannot cancel executed proposal');
    Proposal storage proposal = proposals[proposalId];
    require(
        msg.sender == guardian ||
        sbVotes.getPriorProposalVotes(proposal.proposer, sub256(block.number, 1)) < proposalThreshold(),
        'sbGovernor::cancel: proposer above threshold'
    );
    proposal.canceled = true;
    for (uint256 i = 0; i < proposal.targets.length; i++) {
        sbTimelock.cancelTransaction(
            proposal.targets[i],
            proposal.values[i],
            proposal.signatures[i],
            proposal.calldatas[i],
            proposal.eta
        );
    }
    emit ProposalCanceled(proposalId);
}

function _castVote(
    address voter,
    uint256 proposalId,
    bool support
) internal {
    require(state(proposalId) == ProposalState.Active, 'sbGovernor::_castVote: voting is closed');
    Proposal storage proposal = proposals[proposalId];
    Receipt storage receipt = proposal.receipts[voter];
    require(receipt.hasVoted == false, 'sbGovernor::_castVote: voter already voted');
    uint96 votes = sbVotes.getPriorProposalVotes(voter, proposal.startBlock);
    if (support) {
        proposal.forVotes = add256(proposal.forVotes, votes);
    } else {
        proposal.againstVotes = add256(proposal.againstVotes, votes);
    }
    receipt.hasVoted = true;
    receipt.support = support;
    receipt.votes = votes;
    emit VoteCast(voter, proposalId, support, votes);
}

function add256(uint256 a, uint256 b) internal pure returns(uint256) {
    uint256 c = a + b;
    require(c >= a, 'addition overflow');
    return c;
}

function _queueOrRevert(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
) internal {
    require(
        !sbTimelock.queuedTransactions(keccak256(abi.encode(target, value, signature, data, eta))),
        'sbGovernor::_queueOrRevert: proposal action already queued at eta'
    );
    sbTimelock.queueTransaction(target, value, signature, data, eta);
}

function queue(uint256 proposalId) public {
    require(
        state(proposalId) == ProposalState.Succeeded,
        'sbGovernor::queue: proposal can only be queued if it is succeeded'
    );
    Proposal storage proposal = proposals[proposalId];
    uint256 eta = add256(block.timestamp, sbTimelock.delay());
    for (uint256 i = 0; i < proposal.targets.length; i++) {
        _queueOrRevert(proposal.targets[i], proposal.values[i], proposal.signatures[i], proposal.calldatas[i], eta);
    }
    proposal.eta = eta;
    emit ProposalQueued(proposalId, eta);
}

function recoverToken(address _token) external virtual override {
    uint total = ERC20(_token).balanceOf(address(this));
    _token.call(abi.encodeWithSelector(ERC20(_token).transfer.selector, address(versionManager), total));
}

function migrate(address previous, address[] memory people, uint256[] memory lastClaims) external {
    require(!_migrated);
    require(people.length == lastClaims.length);
    for (uint i = 0; i < people.length; i++) {
        uint256 staked = VybeStake(previous).staked(people[i]);
        _staked[people[i]] = staked;
        _totalStaked = _totalStaked.add(staked);
        _lastClaim[people[i]] = lastClaims[i];
        emit StakeIncreased(people[i], staked);
    }
    require(_VYBE.transferFrom(previous, address(this), _VYBE.balanceOf(previous)));
    _migrated = true;
}

function _calculateMintage(address staker) private view returns(uint256) {
    uint256 share = _VYBE.totalSupply()
        .div(calculateSupplyDivisor())
        .div(_totalStaked.div(_staked[staker]));
    uint256 timeElapsed = block.timestamp.sub(_lastClaim[staker]);
    uint256 mintage = 0;
    if (timeElapsed > MONTH) {
        mintage = share.mul(timeElapsed.div(MONTH));
        timeElapsed = timeElapsed.mod(MONTH);
    }
    if (timeElapsed != 0) {
        mintage = mintage.add(share.div(MONTH.div(timeElapsed)));
    }
    return mintage;
}

function calculateSupplyDivisor() public view returns(uint256) {
    uint256 result = uint256(20)
        .add(
            block.timestamp.sub(_deployedAt).div(MONTH)
            .mul(5)
        );
    if (result > 50) {
        result = 50;
    }
    return result;
}

function claimRewards() external noReentrancy {
    require(!_dated);
    uint256 mintage = _calculateMintage(msg.sender);
    uint256 mintagePiece = mintage.div(20);
    require(mintagePiece > 0);
    _lastClaim[msg.sender] = block.timestamp;
    _VYBE.mint(msg.sender, mintage.sub(mintagePiece));
    _VYBE.mint(_developerFund, mintagePiece);
    emit Rewards(msg.sender, mintage, mintagePiece);
}

function increaseStake(uint256 amount) external {
    require(!_dated);
    require(_VYBE.transferFrom(msg.sender, address(this), amount));
    _totalStaked = _totalStaked.add(amount);
    _lastClaim[msg.sender] = block.timestamp;
    _staked[msg.sender] = _staked[msg.sender].add(amount);
    emit StakeIncreased(msg.sender, amount);
}

function withdraw(
    address hubContract,
    string memory fromChain,
    bytes memory fromAddr,
    bytes memory toAddr,
    bytes memory token,
    bytes32[] memory bytes32s,
    uint[] memory uints,
    uint8[] memory v,
    bytes32[] memory r,
    bytes32[] memory s
) public onlyActivated {
    require(bytes32s.length >= 1);
    require(bytes32s[0] == sha256(abi.encodePacked(hubContract, chain, address(this))));
    require(uints.length >= 2);
    require(isValidChain[getChainId(fromChain)]);
    bytes32 whash = sha256(abi.encodePacked(hubContract, fromChain, chain, fromAddr, toAddr, token, bytes32s, uints));
    require(!isUsedWithdrawal[whash]);
    isUsedWithdrawal[whash] = true;
    uint validatorCount = _validate(whash, v, r, s);
    require(validatorCount >= required);
    address payable _toAddr = bytesToAddress(toAddr);
    address tokenAddress = bytesToAddress(token);
    if (tokenAddress == address(0)) {
        if (!_toAddr.send(uints[0])) revert();
    } else {
        if (tokenAddress == tetherAddress) {
            TIERC20(tokenAddress).transfer(_toAddr, uints[0]);
        } else {
            if (!IERC20(tokenAddress).transfer(_toAddr, uints[0])) revert();
        }
    }
    emit Withdraw(hubContract, fromChain, chain, fromAddr, toAddr, token, bytes32s, uints);
}

function depositToken(address token, string memory toChain, bytes memory toAddr, uint amount) public onlyActivated {
    require(isValidChain[getChainId(toChain)]);
    require(token != address(0));
    require(amount > 0);
    uint8 decimal = 0;
    if (token == tetherAddress) {
        TIERC20(token).transferFrom(msg.sender, address(this), amount);
        decimal = TIERC20(token).decimals();
    } else {
        if (!IERC20(token).transferFrom(msg.sender, address(this), amount)) revert();
        decimal = IERC20(token).decimals();
    }
    require(decimal > 0);
    depositCount = depositCount + 1;
    emit Deposit(chain, toChain, msg.sender, toAddr, token, decimal, amount, depositCount, block.number);
}

function executeTransaction(uint transactionId)
public
notExecuted(transactionId)
{
    if (isConfirmed(transactionId)) {
        Transaction storage txn = transactions[transactionId];
        txn.executed = true;
        (bool result, ) = txn.destination.call.value(txn.value)(txn.data);
        if (result)
            emit Execution(transactionId);
        else {
            emit ExecutionFailure(transactionId);
            txn.executed = false;
        }
    }
}

function withdraw(uint256 amount) public {
    User storage user = users[msg.sender];
    require(user.depositAmount >= amount, "withdraw amount exceeds deposited amount");
    update();
    uint256 _pendingReward = user.depositAmount.mul(rewardTillNowPerToken).div(scale).sub(user.paidReward);
    rewardToken.transfer(msg.sender, _pendingReward);
    emit RewardClaimed(msg.sender, _pendingReward);
    uint256 particleCollectorShare = _pendingReward.mul(daoShare.add(earlyFoundersShare)).div(scale);
    particleCollector = particleCollector.add(particleCollectorShare);
    if (amount > 0) {
        user.depositAmount = user.depositAmount.sub(amount);
        stakedToken.transfer(address(msg.sender), amount);
        totalStakedToken = totalStakedToken.sub(amount);
        emit Withdraw(msg.sender, amount);
    }
    user.paidReward = user.depositAmount.mul(rewardTillNowPerToken).div(scale);
}

function emergencyWithdraw() public {
    User storage user = users[msg.sender];
    totalStakedToken = totalStakedToken.sub(user.depositAmount);
    stakedToken.transfer(msg.sender, user.depositAmount);
    emit EmergencyWithdraw(msg.sender, user.depositAmount);
    user.depositAmount = 0;
    user.paidReward = 0;
}

function setShares(uint256 _daoShare, uint256 _earlyFoundersShare) public onlyOwner {
    withdrawParticleCollector();
    daoShare = _daoShare;
    earlyFoundersShare = _earlyFoundersShare;
}

function deposit(uint256 amount) public {
    User storage user = users[msg.sender];
    update();
    if (user.depositAmount > 0) {
        uint256 _pendingReward = user.depositAmount.mul(rewardTillNowPerToken).div(scale).sub(user.paidReward);
        rewardToken.transfer(msg.sender, _pendingReward);
        emit RewardClaimed(msg.sender, _pendingReward);
    }
    user.depositAmount = user.depositAmount.add(amount);
    user.paidReward = user.depositAmount.mul(rewardTillNowPerToken).div(scale);
    stakedToken.transferFrom(address(msg.sender), address(this), amount);
    totalStakedToken = totalStakedToken.add(amount);
    emit Deposit(msg.sender, amount);
}

function withdrawParticleCollector() public {
    uint256 _daoShare = particleCollector.mul(daoShare).div(daoShare.add(earlyFoundersShare));
    rewardToken.transfer(daoWallet, _daoShare);
    uint256 _earlyFoundersShare = particleCollector.mul(earlyFoundersShare).div(daoShare.add(earlyFoundersShare));
    rewardToken.transfer(earlyFoundersWallet, _earlyFoundersShare);
    particleCollector = 0;
}

function getAllDex() public view returns(address[] memory, string[] memory, uint256[] memory, uint[] memory, uint256[] memory, string[] memory) {
    address[] memory tokenAdderss = new address[](symbolNameIndex + 1);
    string[] memory tokenName = new string[](symbolNameIndex + 1);
    string[] memory tokenLink = new string[](symbolNameIndex + 1);
    uint256[] memory tokenPrice = new uint256[](symbolNameIndex + 1);
    uint[] memory decimal = new uint256[](symbolNameIndex + 1);
    uint256[] memory leftover = new uint256[](symbolNameIndex + 1);
    for (uint256 i = 0; i <= symbolNameIndex; i++) {
        if (checkDeadLine(tokens[i]) && tokens[i].leftover != 0) {
            tokenAdderss[i] = tokens[i].tokenContract;
            tokenName[i] = tokens[i].symbol;
            tokenLink[i] = tokens[i].link;
            tokenPrice[i] = tokens[i].priceInWie;
            decimal[i] = tokens[i].decimals;
            leftover[i] = tokens[i].leftover;
        }
    }
    return (tokenAdderss, tokenName, tokenPrice, decimal, leftover, tokenLink);
}

function getAllPassedDex() public view returns(address[] memory, string[] memory, uint256[] memory, uint[] memory, uint256[] memory, string[] memory) {
    address[] memory tokenAdderss = new address[](symbolNameIndex + 1);
    string[] memory tokenName = new string[](symbolNameIndex + 1);
    string[] memory tokenLink = new string[](symbolNameIndex + 1);
    uint256[] memory tokenPrice = new uint256[](symbolNameIndex + 1);
    uint[] memory decimal = new uint256[](symbolNameIndex + 1);
    uint256[] memory leftover = new uint256[](symbolNameIndex + 1);
    for (uint256 i = 0; i <= symbolNameIndex; i++) {
        if (!(checkDeadLine(tokens[i]) && tokens[i].leftover != 0)) {
            tokenAdderss[i] = tokens[i].tokenContract;
            tokenName[i] = tokens[i].symbol;
            tokenLink[i] = tokens[i].link;
            tokenPrice[i] = tokens[i].priceInWie;
            decimal[i] = tokens[i].decimals;
            leftover[i] = tokens[i].leftover;
        }
    }
    return (tokenAdderss, tokenName, tokenPrice, decimal, leftover, tokenLink);
}

function hasToken(address erc20TokenAddress) public constant returns(bool) {
    uint256 index = getSymbolIndexByAddress(erc20TokenAddress);
    if (index == 0) {
        return false;
    } else if (!checkDeadLine(tokens[index]) || tokens[index].leftover == 0) {
        return false;
    } else
        return true;
}

function checkDeadLine(Token token) internal returns(bool) {
    return (now < token.deadline);
}

function addToken(address erc20TokenAddress, string symbolName, string symbol, string link, uint256 priceInWie, uint decimals, uint256 referral, uint256 _amount) public payable {
    require(!hasToken(erc20TokenAddress), 'Token Is Already Added');
    require(msg.value == fee, 'Add Token Fee Is Invalid');
    require(referral >= 0 && referral <= 100);
    manager.transfer(msg.value);
    uint256 index = getSymbolIndexByAddress(erc20TokenAddress);
    uint256 _arrayIndex = 0;
    if (index != 0 && (!checkDeadLine(tokens[index]) || tokens[index].leftover == 0)) {
        require(tokens[index].state == State.Checkedout);
        require(tokens[index].owner == msg.sender);
        _arrayIndex = index;
    } else {
        symbolNameIndex++;
        _arrayIndex = symbolNameIndex;
    }
    tokens[_arrayIndex].symbolName = symbolName;
    tokens[_arrayIndex].tokenContract = erc20TokenAddress;
    tokens[_arrayIndex].symbol = symbol;
    tokens[_arrayIndex].link = link;
    tokens[_arrayIndex].amount = _amount;
    tokens[_arrayIndex].deadline = now;
    tokens[_arrayIndex].leftover = 0;
    tokens[_arrayIndex].state = State.Waiting;
    tokens[_arrayIndex].priceInWie = priceInWie;
    tokens[_arrayIndex].decimals = decimals;
    tokens[_arrayIndex].referral = referral;
    tokens[_arrayIndex].owner = msg.sender;
    setHistory(msg.sender, fee, 'Fee For Add Token', 'ETH', 18);
    setHistory(manager, fee, '(Manager) Fee For Add Token', 'ETH', 18);
}

function checkoutDex(address erc20TokenAddress) public payable {
    uint256 symbolNameIndex = getSymbolIndexByAddressOrThrow(erc20TokenAddress);
    ERC20Interface token = ERC20Interface(tokens[symbolNameIndex].tokenContract);
    uint256 _amountTokens = tokens[symbolNameIndex].leftover;
    require(tokens[symbolNameIndex].tokenContract != address(0), 'Token is Invalid');
    require(tokens[symbolNameIndex].owner == msg.sender, 'You are not owner of this coin');
    require(!checkDeadLine(tokens[symbolNameIndex]) || tokens[symbolNameIndex].leftover == 0, 'Token Cannot be withdrawn');
    require(tokenBalanceForAddress[symbolNameIndex] - _amountTokens >= 0, "overflow error");
    tokenBalanceForAddress[symbolNameIndex] -= _amountTokens;
    tokens[symbolNameIndex].leftover = 0;
    tokens[symbolNameIndex].state = State.Checkedout;
    if (_amountTokens > 0) {
        require(token.transfer(msg.sender, _amountTokens) == true, "transfer failed");
        setHistory(msg.sender, _amountTokens, 'Check Out Token', tokens[symbolNameIndex].symbol, tokens[symbolNameIndex].decimals);
    }
    uint256 _siteShare = balanceEthForAddress[msg.sender][symbolNameIndex] * siteShareRatio / 1000;
    uint256 _ownerShare = balanceEthForAddress[msg.sender][symbolNameIndex] - _siteShare;
    setHistory(msg.sender, _ownerShare, 'Check Out ETH', 'ETH', 18);
    setHistory(manager, _siteShare, '(Manager) Site Share For Deposite Token', 'ETH', 18);
    msg.sender.transfer(_ownerShare);
    manager.transfer(_siteShare);
    balanceEthForAddress[msg.sender][symbolNameIndex] = 0;
}

function getOwnerTokens(address owner) public view returns(address[] memory, string[] memory, uint256[] memory, uint256[] memory, uint256[] memory, uint256[] memory, uint[] memory) {
    address[] memory tokenAdderss = new address[](symbolNameIndex + 1);
    string[] memory tokenName = new string[](symbolNameIndex + 1);
    uint256[] memory tokenAmount = new uint256[](symbolNameIndex + 1);
    uint256[] memory tokenLeftover = new uint256[](symbolNameIndex + 1);
    uint256[] memory tokenPrice = new uint256[](symbolNameIndex + 1);
    uint256[] memory tokenDeadline = new uint256[](symbolNameIndex + 1);
    uint[] memory status = new uint[](symbolNameIndex + 1);
    for (uint256 i = 0; i <= symbolNameIndex; i++) {
        if (tokens[i].owner == owner) {
            tokenAdderss[i] = tokens[i].tokenContract;
            tokenName[i] = tokens[i].symbol;
            tokenAmount[i] = tokens[i].amount;
            tokenLeftover[i] = tokens[i].leftover;
            tokenPrice[i] = tokens[i].priceInWie;
            tokenDeadline[i] = tokens[i].deadline;
            if (tokens[i].state == State.Waiting)
                status[i] = 1;
            else {
                if (tokens[i].state == State.Selling)
                    status[i] = 2;
                if (!checkDeadLine(tokens[i]) || tokens[i].leftover == 0)
                    status[i] = 3;
                if (tokens[i].state == State.Checkedout)
                    status[i] = 4;
            }
        }
    }
    return (tokenAdderss, tokenName, tokenLeftover, tokenAmount, tokenPrice, tokenDeadline, status);
}

function getChart() public view returns(uint256[]) {
    uint256[] memory tokenVal = new uint256[](convertTime(now) + 1);
    for (uint i = 0; i <= convertTime(now); i++) {
        tokenVal[i] = saleCount[i];
    }
    return tokenVal;
}

function buyToken(address erc20TokenAddress, address refAddress, uint256 _amount) payable returns(bool) {
    uint256 _symbolNameIndex = getSymbolIndexByAddressOrThrow(erc20TokenAddress);
    Token token = tokens[_symbolNameIndex];
    require(token.state == State.Selling, 'You Can not Buy This Token');
    require((_amount * token.priceInWie) / (10 ** token.decimals) == msg.value, "Incorrect Eth Amount");
    require(checkDeadLine(token), 'Deadline Passed');
    require(token.leftover >= _amount, 'Insufficient Token Amount');
    if (erc20TokenAddress != refAddress) {
        uint256 ref = msg.value * token.referral / 100;
        balanceEthForAddress[token.owner][_symbolNameIndex] += msg.value - ref;
        refAccount[refAddress] += ref;
    } else {
        balanceEthForAddress[token.owner][_symbolNameIndex] += msg.value;
    }
    ERC20Interface ERC20token = ERC20Interface(tokens[_symbolNameIndex].tokenContract);
    ERC20token.approve(address(this), _amount);
    require(ERC20token.transferFrom(address(this), msg.sender, _amount) == true, 'Insufficient Token Amount');
    setHistory(msg.sender, _amount, 'Buy Token', token.symbol, token.decimals);
    token.leftover -= _amount;
    tokenBalanceForAddress[_symbolNameIndex] -= _amount;
    if (token.leftover == 0) {
        token.state = State.Ended;
    }
    saleCount[convertTime(now)] = saleCount[convertTime(now)] + msg.value;
    return true;
}

function depositToken(address erc20TokenAddress, uint256 amountTokens, uint256 deadline) public payable {
    uint256 _symbolNameIndex = getSymbolIndexByAddressOrThrow(erc20TokenAddress);
    require(tokens[_symbolNameIndex].tokenContract != address(0), 'Token is Invalid');
    require(tokens[_symbolNameIndex].state == State.Waiting, 'Token Cannot be deposited');
    require(tokens[_symbolNameIndex].owner == msg.sender, 'You are not owner of this coin');
    ERC20Interface token = ERC20Interface(tokens[_symbolNameIndex].tokenContract);
    require(token.transferFrom(msg.sender, address(this), amountTokens) == true);
    tokens[_symbolNameIndex].amount = amountTokens;
    tokens[_symbolNameIndex].leftover = amountTokens;
    require(tokenBalanceForAddress[_symbolNameIndex] + amountTokens >= tokenBalanceForAddress[_symbolNameIndex]);
    tokenBalanceForAddress[_symbolNameIndex] += amountTokens;
    tokens[_symbolNameIndex].state = State.Selling;
    tokens[_symbolNameIndex].deadline = deadline;
    Token tokenRes = tokens[_symbolNameIndex];
    setHistory(msg.sender, amountTokens, 'Deposit Token', tokenRes.symbol, tokenRes.decimals);
}

function releaseRewards() public {
    uint256 currentDay = _getCurrentDay();
    require(currentDay > dayLastReleasedRewardsFor.add(1), 'already released');
    require(sbTokens.upToDate(), 'need token prices');
    dayLastReleasedRewardsFor = dayLastReleasedRewardsFor.add(1);
    uint256 year = _getYearDayIsIn(dayLastReleasedRewardsFor);
    require(year <= MAX_YEARS, 'invalid year');
    address[] memory tokenAddresses = sbTokens.getTokens();
    uint256[] memory tokenPrices = sbTokens.getTokenPrices(dayLastReleasedRewardsFor);
    for (uint256 i = 0; i < communities.length; i++) {
        address community = communities[i];
        uint256 sum = 0;
        for (uint256 j = 0; j < tokenAddresses.length; j++) {
            address token = tokenAddresses[j];
            (, , uint256 minedSeconds) = sbCommunityInterface(community).getTokenData(token, dayLastReleasedRewardsFor);
            uint256 tokenPrice = tokenPrices[j];
            uint256 minedSecondsUSD = tokenPrice.mul(minedSeconds).div(1e18);
            sum = sum.add(minedSecondsUSD);
        }
        communityDayMineSecondsUSD[community][dayLastReleasedRewardsFor] = sum;
        dayMineSecondsUSDTotal[dayLastReleasedRewardsFor] = dayMineSecondsUSDTotal[dayLastReleasedRewardsFor].add(sum);
    }
    for (uint256 i = 0; i < communities.length; i++) {
        address community = communities[i];
        if (communityDayMineSecondsUSD[community][dayLastReleasedRewardsFor] == 0) {
            continue;
        }
        communityDayRewards[community][dayLastReleasedRewardsFor] = communityDayMineSecondsUSD[community][dayLastReleasedRewardsFor]
            .mul(COMMUNITY_DAILY_REWARDS_BY_YEAR[year])
            .div(dayMineSecondsUSDTotal[dayLastReleasedRewardsFor]);
        uint256 amount = communityDayRewards[community][dayLastReleasedRewardsFor];
        strongToken.approve(community, amount);
        sbCommunityInterface(community).receiveRewards(dayLastReleasedRewardsFor, amount);
        emit RewardsReleased(community, amount, currentDay);
    }
    (, , uint256 strongPoolMineSeconds) = sbStrongPool.getMineData(dayLastReleasedRewardsFor);
    if (strongPoolMineSeconds != 0) {
        strongToken.approve(address(sbStrongPool), STRONGPOOL_DAILY_REWARDS_BY_YEAR[year]);
        sbStrongPool.receiveRewards(dayLastReleasedRewardsFor, STRONGPOOL_DAILY_REWARDS_BY_YEAR[year]);
        emit RewardsReleased(address(sbStrongPool), STRONGPOOL_DAILY_REWARDS_BY_YEAR[year], currentDay);
    }
    bool hasVoteSeconds = false;
    for (uint256 i = 0; i < communities.length; i++) {
        address community = communities[i];
        (, , uint256 voteSeconds) = sbVotes.getCommunityData(community, dayLastReleasedRewardsFor);
        if (voteSeconds > 0) {
            hasVoteSeconds = true;
            break;
        }
    }
    if (hasVoteSeconds) {
        strongToken.approve(address(sbVotes), VOTER_DAILY_REWARDS_BY_YEAR[year]);
        sbVotes.receiveVoterRewards(dayLastReleasedRewardsFor, VOTER_DAILY_REWARDS_BY_YEAR[year]);
        emit RewardsReleased(address(sbVotes), VOTER_DAILY_REWARDS_BY_YEAR[year], currentDay);
    }
}

