}

function claimStakingRewardsLocally(address addr) private returns(uint256 guardianRewards, uint256 delegatorRewards) {
    updateDelegatorStakingRewards(addr);
    guardianRewards = guardiansStakingRewards[addr].balance;
    guardiansStakingRewards[addr].balance = 0;
    delegatorRewards = delegatorsStakingRewards[addr].balance;
    delegatorsStakingRewards[addr].balance = 0;
    uint256 total = delegatorRewards.add(guardianRewards);
    StakingRewardsState memory _stakingRewardsState = stakingRewardsState;
    uint256 _stakingRewardsWithdrawnFromWallet = stakingRewardsWithdrawnFromWallet;
    if (total > _stakingRewardsWithdrawnFromWallet) {
        uint256 allocated = _stakingRewardsState.unclaimedStakingRewards.sub(_stakingRewardsWithdrawnFromWallet);
        stakingRewardsWallet.withdraw(allocated);
        _stakingRewardsWithdrawnFromWallet = _stakingRewardsWithdrawnFromWallet.add(allocated);
    }
    stakingRewardsWithdrawnFromWallet = _stakingRewardsWithdrawnFromWallet.sub(total);
    stakingRewardsState.unclaimedStakingRewards = _stakingRewardsState.unclaimedStakingRewards.sub(total);
}

function claimStakingRewards(address addr) external override onlyWhenActive {
    (uint256 guardianRewards, uint256 delegatorRewards) = claimStakingRewardsLocally(addr);
    uint96 claimedGuardianRewards = guardiansStakingRewards[addr].claimed.add(guardianRewards);
    guardiansStakingRewards[addr].claimed = claimedGuardianRewards;
    uint96 claimedDelegatorRewards = delegatorsStakingRewards[addr].claimed.add(delegatorRewards);
    delegatorsStakingRewards[addr].claimed = claimedDelegatorRewards;
    uint256 total = delegatorRewards.add(guardianRewards);
    require(erc20.approve(address(stakingContract), total), "claimStakingRewards: approve failed");
    address[] memory addrs = new address[](1);
    addrs[0] = addr;
    uint256[] memory amounts = new uint256[](1);
    amounts[0] = total;
    stakingContract.distributeRewards(total, addrs, amounts);
    emit StakingRewardsClaimed(addr, delegatorRewards, guardianRewards, claimedDelegatorRewards, claimedGuardianRewards);
}

function who(uint surf, bytes32 askCoin, bytes32 ownCoin, uint256 ask2own, uint256 value) public view returns(uint found) {
    uint pos = offerRef < surf ? 1 : offerRef - surf + 1;
    for (uint i = pos; i <= offerRef; i++) {
        Market memory mi = markets[i];
        if (mi.askCoin == askCoin && mi.ownCoin == ownCoin && mi.value > value && mi.ask2own >= ask2own && (mi.time == 0 || mi.time >= now)) return (i);
    }
}

function post(bytes32 askCoin, bytes32 ownCoin, uint256 ask2own, uint256 value, uint time) public returns(bool success) {
    require(time == 0 || time > now, "#time");
    require(value > 0 && ask2own > 0, "#values");
    move(ownCoin, msg.sender, address(this), value);
    Market memory mi;
    mi.askCoin = askCoin;
    mi.ownCoin = ownCoin;
    mi.ask2own = ask2own;
    mi.maker = msg.sender;
    mi.value = value;
    mi.time = time;
    markets[++offerRef] = mi;
    emit Sell(offerRef, mi.askCoin, mi.ownCoin, mi.ask2own, mi.maker);
    return true;
}

function unpost(uint refno) public returns(bool success) {
    Market storage mi = markets[refno];
    require(mi.value > 0, "#data");
    require(mi.maker == msg.sender, "#user");
    require(mi.time == 0 || mi.time < now, "#time");
    move(mi.ownCoin, address(this), mi.maker, mi.value);
    mi.value = 0;
    return true;
}

function take(uint refno, address taker, uint256 fitValue)
internal returns(uint256) {
    Market storage mi = markets[refno];
    require(mi.value > 0 && mi.ask2own > 0, "#data");
    require(mi.time == 0 || mi.time >= now, "#time");
    uint256 askValue = PPT * mi.value / mi.ask2own;
    uint256 ownValue = fitValue * mi.ask2own / PPT;
    if (askValue > fitValue) askValue = fitValue;
    if (ownValue > mi.value) ownValue = mi.value;
    move(mi.askCoin, taker, mi.maker, askValue);
    move(mi.ownCoin, address(this), taker, ownValue);
    deduct(mi, ownValue);
    return askValue;
}

function withdraw(string memory coinSymbol, uint256 value) public returns(bool success) {
    bytes32 coin = tocoin(coinSymbol);
    uint256 crate = coinPrices[coin];
    uint256 erate = coinPrices[ETHEREUM];
    require(crate > 0, "#token");
    require(erate > 0, "#ether");
    require(value > 0, "#value");
    burn(coin, msg.sender, value);
    mint(SYMBOL, PROJECT, value);
    msg.sender.transfer(value * crate / erate);
    emit Withdraw(coinSymbol, msg.sender, value);
    return true;
}

function giveVault(
    address _wallet,
    bytes32 _loanId
)
external
onlyWalletFeature(_wallet)
onlyNewVersion
onlyWhenUnlocked(_wallet)
{
    verifyLoanOwner(_wallet, _loanId);
    cdpManager.give(uint256(_loanId), msg.sender);
    clearLoanOwner(_wallet, _loanId);
}

function openVault(
    address _wallet,
    address _collateral,
    uint256 _collateralAmount,
    uint256 _debtAmount
)
internal
returns(uint256 _cdpId)
{
    if (_collateral == ETH_TOKEN) {
        _collateral = address(wethToken);
    }
    bytes32 ilk = makerRegistry.getIlk(_collateral);
    _cdpId = uint256(loanIds[_wallet][ilk]);
    if (_cdpId == 0) {
        _cdpId = cdpManager.open(ilk, address(this));
        loanIds[_wallet][ilk] = bytes32(_cdpId);
    }
    joinCollateral(_wallet, _cdpId, _collateralAmount, ilk);
    if (_debtAmount > 0) {
        drawAndExitDebt(_wallet, _cdpId, _debtAmount, _collateralAmount, ilk);
    }
}

function isCommitteeVoteUnreadyThresholdReached(address[] memory committee, uint256[] memory weights, bool[] memory certification, address subject) private returns(bool) {
    Settings memory _settings = settings;
    uint256 totalCommitteeStake = 0;
    uint256 totalVoteUnreadyStake = 0;
    uint256 totalCertifiedStake = 0;
    uint256 totalCertifiedVoteUnreadyStake = 0;
    address member;
    uint256 memberStake;
    bool isSubjectCertified;
    for (uint i = 0; i < committee.length; i++) {
        member = committee[i];
        memberStake = weights[i];
        if (member == subject && certification[i]) {
            isSubjectCertified = true;
        }
        totalCommitteeStake = totalCommitteeStake.add(memberStake);
        if (certification[i]) {
            totalCertifiedStake = totalCertifiedStake.add(memberStake);
        }
        (bool valid, uint256 expiration) = getVoteUnreadyVote(member, subject);
        if (valid) {
            totalVoteUnreadyStake = totalVoteUnreadyStake.add(memberStake);
            if (certification[i]) {
                totalCertifiedVoteUnreadyStake = totalCertifiedVoteUnreadyStake.add(memberStake);
            }
        } else if (expiration != 0) {
            delete voteUnreadyVotes[member][subject];
        }
    }
    return (
        totalCommitteeStake > 0 &&
        totalVoteUnreadyStake.mul(PERCENT_MILLIE_BASE) >= uint256(_settings.voteUnreadyPercentMilleThreshold).mul(totalCommitteeStake)
    ) || (
        isSubjectCertified &&
        totalCertifiedStake > 0 &&
        totalCertifiedVoteUnreadyStake.mul(PERCENT_MILLIE_BASE) >= uint256(_settings.voteUnreadyPercentMilleThreshold).mul(totalCertifiedStake)
    );
}

function getVoteUnreadyStatus(address subject) external override view returns(address[] memory committee, uint256[] memory weights, bool[] memory certification, bool[] memory votes, bool subjectInCommittee, bool subjectInCertifiedCommittee) {
    (committee, weights, certification) = committeeContract.getCommittee();
    votes = new bool[](committee.length);
    for (uint i = 0; i < committee.length; i++) {
        address memberAddr = committee[i];
        if (block.timestamp < voteUnreadyVotes[memberAddr][subject]) {
            votes[i] = true;
        }
        if (memberAddr == subject) {
            subjectInCommittee = true;
            subjectInCertifiedCommittee = certification[i];
        }
    }
}

function getVoteUnreadyVote(address voter, address subject) public override view returns(bool valid, uint256 expiration) {
    expiration = voteUnreadyVotes[voter][subject];
    valid = expiration != 0 && block.timestamp < expiration;
}

function voteUnready(address subject, uint voteExpiration) external override onlyWhenActive {
    require(voteExpiration >= block.timestamp, "vote expiration time must not be in the past");
    address voter = guardianRegistrationContract.resolveGuardianAddress(msg.sender);
    voteUnreadyVotes[voter][subject] = voteExpiration;
    emit VoteUnreadyCasted(voter, subject, voteExpiration);
    (address[] memory generalCommittee, uint256[] memory generalWeights, bool[] memory certification) = committeeContract.getCommittee();
    bool votedUnready = isCommitteeVoteUnreadyThresholdReached(generalCommittee, generalWeights, certification, subject);
    if (votedUnready) {
        clearCommitteeUnreadyVotes(generalCommittee, subject);
        emit GuardianVotedUnready(subject);
        emit GuardianStatusUpdated(subject, false, false);
        committeeContract.removeMember(subject);
    }
}

function voteOut(address subject) external override onlyWhenActive {
    Settings memory _settings = settings;
    address voter = msg.sender;
    address prevSubject = voteOutVotes[voter];
    voteOutVotes[voter] = subject;
    emit VoteOutCasted(voter, subject);
    uint256 voterStake = delegationsContract.getDelegatedStake(voter);
    if (prevSubject == address(0)) {
        votersStake[voter] = voterStake;
    }
    if (subject == address(0)) {
        delete votersStake[voter];
    }
    uint totalStake = delegationsContract.getTotalDelegatedStake();
    if (prevSubject != address(0) && prevSubject != subject) {
        applyVoteOutVotesFor(prevSubject, 0, voterStake, totalStake, _settings);
    }
    if (subject != address(0)) {
        uint voteStakeAdded = prevSubject != subject ? voterStake : 0;
        applyVoteOutVotesFor(subject, voteStakeAdded, 0, totalStake, _settings); 
    }
}

function applyVoteOutVotesFor(address subject, uint256 voteOutStakeAdded, uint256 voteOutStakeRemoved, uint256 totalGovernanceStake, Settings memory _settings) private {
    if (isVotedOut(subject)) {
        return;
    }
    uint256 accumulated = accumulatedStakesForVoteOut[subject].
    sub(voteOutStakeRemoved).
    add(voteOutStakeAdded);
    bool shouldBeVotedOut = totalGovernanceStake > 0 && accumulated.mul(PERCENT_MILLIE_BASE) >= uint256(_settings.voteOutPercentMilleThreshold).mul(totalGovernanceStake);
    if (shouldBeVotedOut) {
        votedOutGuardians[subject] = true;
        emit GuardianVotedOut(subject);
        emit GuardianStatusUpdated(subject, false, false);
        committeeContract.removeMember(subject);
    }
    accumulatedStakesForVoteOut[subject] = accumulated;
}

function getVoterDayLastClaimedFor(address voter)
public
view
returns(uint256)
{
    if (voterDayLastClaimedFor[voter] == 0) {
        uint256 firstDayVoted = _getVoterFirstDay(voter);
        if (firstDayVoted == 0) {
            return 0;
        }
        return firstDayVoted.sub(1);
    }
    return voterDayLastClaimedFor[voter];
}

function getServicePoolData(address servicePool, uint256 dayNumber)
external
view
returns(
    uint256,
    uint256,
    uint256
)
{
