function _find(
    uint256[] memory _Days,
    uint256[] memory _Units,
    uint256 day
) internal pure returns(uint256, uint256) {
    uint256 left = 0;
    uint256 right = _Days.length.sub(1);
    uint256 middle = right.add(left).div(2);
    while (left < right) {
        if (_Days[middle] == day) {
            return (day, _Units[middle]);
        } else if (_Days[middle] > day) {
            if (middle > 0 && _Days[middle.sub(1)] < day) {
                return (day, _Units[middle.sub(1)]);
            }
            if (middle == 0) {
                return (day, 0);
            }
            right = middle.sub(1);
        } else if (_Days[middle] < day) {
            if (
                middle < _Days.length.sub(1) && _Days[middle.add(1)] > day
            ) {
                return (day, _Units[middle]);
            }
            left = middle.add(1);
        }
        middle = right.add(left).div(2);
    }
    if (_Days[middle] != day) {
        return (day, 0);
    } else {
        return (day, _Units[middle]);
    }
}

function _checkBurnAndTransfer(address from, uint256[] memory objectIds, uint256[] memory amounts) private {
    require(msg.sender == _source, "Unauthorized Action");
    require(block.number >= _startBlock, "Redeem Period still not started");
    for (uint256 i = 0; i < objectIds.length; i++) {
        require(objectIds[i] == _legendaryCard, "Wrong Card!");
        _redeemed += amounts[i];
        payable(from).transfer(_singleReward * amounts[i]);
    }
    IEthItem(_source).burnBatch(objectIds, amounts);
}

function _calculateMintage(address staker) private view returns(uint256) {
    uint256 share = _SEED.totalSupply()
        .div(calculateSupplyDivisor())
        .div(_totalStaked.div(_staked[staker]));
    uint256 timeElapsed = block.timestamp.sub(_lastClaim[staker]);
    uint256 mintage = 0;
    if (timeElapsed > MONTH) {
        mintage = share.mul(timeElapsed.div(MONTH));
        timeElapsed = timeElapsed.mod(MONTH);
    }
    if (timeElapsed != 0) {
        mintage = mintage.add(share.div(MONTH.div(timeElapsed)));
    }
    return mintage;
}

function claimRewards() external noReentrancy {
    require(!_dated);
    uint256 mintage = _calculateMintage(msg.sender);
    uint256 mintagePiece = mintage.div(20);
    require(mintagePiece > 0);
    _lastClaim[msg.sender] = block.timestamp;
    _SEED.mint(msg.sender, mintage.sub(mintagePiece));
    _SEED.mint(_developerFund, mintagePiece);
    emit Rewards(msg.sender, mintage, mintagePiece);
}

function migrate(address previous, address[] memory people, uint256[] memory lastClaims) external {
    require(!_migrated);
    require(people.length == lastClaims.length);
    for (uint i = 0; i < people.length; i++) {
        uint256 staked = SeedStake(previous).staked(people[i]);
        _staked[people[i]] = staked;
        _totalStaked = _totalStaked.add(staked);
        _lastClaim[people[i]] = lastClaims[i];
        emit StakeIncreased(people[i], staked);
    }
    require(_SEED.transferFrom(previous, address(this), _SEED.balanceOf(previous)));
    _migrated = true;
}

function increaseStake(uint256 amount) external {
    require(!_dated);
    require(_SEED.transferFrom(msg.sender, address(this), amount));
    _totalStaked = _totalStaked.add(amount);
    _lastClaim[msg.sender] = block.timestamp;
    _staked[msg.sender] = _staked[msg.sender].add(amount);
    emit StakeIncreased(msg.sender, amount);
}

function releasePressure(address _address) internal {
    uint256 amount = myPressure(_address);
    if (amount < balanceOf(UNIv2)) {
        require(_totalSupply.sub(amount) >= _initialSupply.div(1000), "There is less than 0.1% of the Maximum Supply remaining, unfortunately, kabooming is over");
        sellPressure[_address] = 0;
        addToSteam(_address, amount);
        ERC20._burn(UNIv2, amount);
        _UPSBurned = _UPSBurned.add(amount);
        emit BurnedFromLiquidityPool(_address, amount);
        _generateSteamFromUPSBurn(_address);
        emit SteamGenerated(_address, amount);
        txCount[_address] = 0;
    } else if (amount > 0) {
        sellPressure[_address] = sellPressure[_address].div(2);
    }
    IUNIv2(UNIv2).sync();
}

function withdrawEther(uint amount, address sendTo) external onlyAdmin {
    sendTo.transfer(amount);
    EtherWithdraw(amount, sendTo);
}

function doTrade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
internal
returns(bool)
{
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS)
            require(msg.value == srcAmount);
        else
            require(msg.value == 0);
    }
    uint destAmount = getDestQty(srcToken, destToken, srcAmount, conversionRate);
    require(destAmount > 0);
    ERC20 token;
    int tradeAmount;
    if (srcToken == ETH_TOKEN_ADDRESS) {
        tradeAmount = int(destAmount);
        token = destToken;
    } else {
        tradeAmount = -1 * int(srcAmount);
        token = srcToken;
    }
    conversionRatesContract.recordImbalance(
        token,
        tradeAmount,
        0,
        block.number
    );
    if (srcToken != ETH_TOKEN_ADDRESS) {
        require(srcToken.transferFrom(msg.sender, tokenWallet[srcToken], srcAmount));
    }
    if (destToken == ETH_TOKEN_ADDRESS) {
        destAddress.transfer(destAmount);
    } else {
        require(destToken.transferFrom(tokenWallet[destToken], destAddress, destAmount));
    }
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, destAmount, destAddress);
    return true;
}

function withdraw(ERC20 token, uint amount, address destination) public onlyOperator returns(bool) {
    require(approvedWithdrawAddresses[keccak256(token, destination)]);
    if (token == ETH_TOKEN_ADDRESS) {
        destination.transfer(amount);
    } else {
        require(token.transferFrom(tokenWallet[token], destination, amount));
    }
    WithdrawFunds(token, amount, destination);
    return true;
}

function approveWithdrawAddress(ERC20 token, address addr, bool approve) public onlyAdmin {
    approvedWithdrawAddresses[keccak256(token, addr)] = approve;
    WithdrawAddressApproved(token, addr, approve);
    setDecimals(token);
    if ((tokenWallet[token] == address(0x0)) && (token != ETH_TOKEN_ADDRESS)) {
        tokenWallet[token] = this; 
        require(token.approve(this, 2 ** 255));
    }
}

function stake(uint256 amount) external {
    require(amount > 0, "Staking amount must be more than zero");
    require(IPEPE(_RarePepeV2).transferFrom(_msgSender(), address(this), amount), "It has failed to transfer tokens from staker to contract.");
    if (_stakedAmount[_msgSender()] == 0) {
        _stakers.push(_msgSender());
    }
    uint256 burnedAmount = amount.ceil(100).mul(100).div(4000);
    uint256 realStakedAmount = amount.sub(burnedAmount);
    _totalStakedAmount = _totalStakedAmount.add(realStakedAmount);
    _stakedAmount[_msgSender()] = _stakedAmount[_msgSender()].add(realStakedAmount);
    emit Staked(_msgSender(), realStakedAmount);
}

function unstake(uint256 amount) public {
    require(_stakedAmount[_msgSender()] > 0, "No running stake.");
    require(amount > 0, "Unstaking amount must be more than zero.");
    require(_stakedAmount[_msgSender()] >= amount, "Staked amount must be ustaking amount or more.");
    require(IPEPE(_RarePepeV2).transfer(_msgSender(), amount), "It has failed to transfer tokens from contract to staker.");
    _totalStakedAmount = _totalStakedAmount.sub(amount);
    _stakedAmount[_msgSender()] = _stakedAmount[_msgSender()].sub(amount);
    if (_stakedAmount[_msgSender()] == 0) {
        for (uint256 i = 0; i < _stakers.length; i++) {
            if (_stakers[i] == _msgSender()) {
                _stakers[i] = _stakers[_stakers.length.sub(1)];
                _stakers.pop();
                break;
            }
        }
    }
    emit Unstaked(_msgSender(), amount);
}

function _getRewardsDue(
    uint256 upToDay,
    address miner,
    uint256 dayLastClaimedFor
) internal view returns(uint256) {
    address[] memory tokens = sbTokens.getTokens();
    uint256 rewards;
    for (
        uint256 day = dayLastClaimedFor.add(1);
        day <= upToDay.sub(delayDays);
        day++
    ) {
        uint256 communityDayMineSecondsUSD = sbController
            .getCommunityDayMineSecondsUSD(address(this), day);
        if (communityDayMineSecondsUSD == 0) {
            continue;
        }
        uint256 minerDayMineSecondsUSD = 0;
        uint256[] memory tokenPrices = sbTokens.getTokenPrices(day);
        for (uint256 i = 0; i < tokens.length; i++) {
            address token = tokens[i];
            (, , uint256 minerMineSeconds) = _getMinerTokenData(
                miner,
                token,
                day
            );
            uint256 amount = minerMineSeconds.mul(tokenPrices[i]).div(1e18);
            minerDayMineSecondsUSD = minerDayMineSecondsUSD.add(amount);
        }
        uint256 communityDayRewards = sbController
            .getCommunityDayRewards(address(this), day)
            .sub(dayServiceRewards[day]);
        uint256 amount = communityDayRewards
            .mul(minerDayMineSecondsUSD)
            .div(communityDayMineSecondsUSD);
        rewards = rewards.add(amount);
    }
    return rewards;
}

function getRewardsDueAll(address miner) public view returns(uint256) {
    require(delayDays > 0, "zero");
    uint256 currentDay = _getCurrentDay();
    uint256 dayLastClaimedFor = minerDayLastClaimedFor[miner] == 0
        ?
        sbController.getStartDay().sub(1)
        :
        minerDayLastClaimedFor[miner];
    if (!(currentDay > dayLastClaimedFor.add(delayDays))) {
        return 0;
    }
    require(sbTokens.upToDate(), "need token prices");
    require(sbController.upToDate(), "need rewards released");
    return _getRewardsDue(currentDay, miner, dayLastClaimedFor);
}

