function delegateFrom(address from, address to) private {
    require(to != address(0), "cannot delegate to a zero address");
    DelegateFromVars memory vars;
    StakeOwnerData memory delegatorData = getStakeOwnerData(from);
    if (delegatorData.stake == 0 && uncappedDelegatedStake[from] == 0) {
        stakeOwnersData[from].delegation = to;
        emit Delegated(from, to);
        return;
    }
    address prevDelegate = delegatorData.delegation;
    vars.prevDelegateStatusBefore = getDelegateStatus(prevDelegate);
    vars.newDelegateStatusBefore = getDelegateStatus(to);
    stakingRewardsContract.delegationWillChange(prevDelegate, vars.prevDelegateStatusBefore.delegatedStake, from, delegatorData.stake, to, vars.newDelegateStatusBefore.delegatedStake);
    stakeOwnersData[from].delegation = to;
    uint256 delegatorStake = delegatorData.stake;
    uncappedDelegatedStake[prevDelegate] = vars.prevDelegateStatusBefore.uncappedDelegatedStake.sub(delegatorStake);
    uncappedDelegatedStake[to] = vars.newDelegateStatusBefore.uncappedDelegatedStake.add(delegatorStake);
    vars.prevDelegateStatusAfter = getDelegateStatus(prevDelegate);
    vars.newDelegateStatusAfter = getDelegateStatus(to);
    uint256 _totalDelegatedStake = totalDelegatedStake.sub(
        vars.prevDelegateStatusBefore.delegatedStake
    ).add(
        vars.prevDelegateStatusAfter.delegatedStake
    ).sub(
        vars.newDelegateStatusBefore.delegatedStake
    ).add(
        vars.newDelegateStatusAfter.delegatedStake
    );
    totalDelegatedStake = _totalDelegatedStake;
    emit Delegated(from, to);
    IElections _electionsContract = electionsContract;
    if (vars.prevDelegateStatusBefore.delegatedStake != vars.prevDelegateStatusAfter.delegatedStake) {
        _electionsContract.delegatedStakeChange(
            prevDelegate,
            vars.prevDelegateStatusAfter.selfDelegatedStake,
            vars.prevDelegateStatusAfter.delegatedStake,
            _totalDelegatedStake
        );
        emit DelegatedStakeChanged(
            prevDelegate,
            vars.prevDelegateStatusAfter.selfDelegatedStake,
            vars.prevDelegateStatusAfter.delegatedStake,
            from,
            0
        );
    }
    if (vars.newDelegateStatusBefore.delegatedStake != vars.newDelegateStatusAfter.delegatedStake) {
        _electionsContract.delegatedStakeChange(
            to,
            vars.newDelegateStatusAfter.selfDelegatedStake,
            vars.newDelegateStatusAfter.delegatedStake,
            _totalDelegatedStake
        );
        emit DelegatedStakeChanged(
            to,
            vars.newDelegateStatusAfter.selfDelegatedStake,
            vars.newDelegateStatusAfter.delegatedStake,
            from,
            delegatorStake
        );
    }
}

function _stakeChange(address _stakeOwner, uint256 _updatedStake) private {
    StakeOwnerData memory stakeOwnerDataBefore = getStakeOwnerData(_stakeOwner);
    DelegateStatus memory delegateStatusBefore = getDelegateStatus(stakeOwnerDataBefore.delegation);
    uint256 prevUncappedStake = delegateStatusBefore.uncappedDelegatedStake;
    uint256 newUncappedStake = prevUncappedStake.sub(stakeOwnerDataBefore.stake).add(_updatedStake);
    stakingRewardsContract.delegationWillChange(stakeOwnerDataBefore.delegation, delegateStatusBefore.delegatedStake, _stakeOwner, stakeOwnerDataBefore.stake, stakeOwnerDataBefore.delegation, delegateStatusBefore.delegatedStake);
    uncappedDelegatedStake[stakeOwnerDataBefore.delegation] = newUncappedStake;
    require(uint256(uint96(_updatedStake)) == _updatedStake, "Delegations::updatedStakes value too big (>96 bits)");
    stakeOwnersData[_stakeOwner].stake = uint96(_updatedStake);
    uint256 _totalDelegatedStake = totalDelegatedStake;
    if (delegateStatusBefore.isSelfDelegating) {
        _totalDelegatedStake = _totalDelegatedStake.sub(stakeOwnerDataBefore.stake).add(_updatedStake);
        totalDelegatedStake = _totalDelegatedStake;
    }
    DelegateStatus memory delegateStatusAfter = getDelegateStatus(stakeOwnerDataBefore.delegation);
    electionsContract.delegatedStakeChange(
        stakeOwnerDataBefore.delegation,
        delegateStatusAfter.selfDelegatedStake,
        delegateStatusAfter.delegatedStake,
        _totalDelegatedStake
    );
    if (_updatedStake != stakeOwnerDataBefore.stake) {
        emit DelegatedStakeChanged(
            stakeOwnerDataBefore.delegation,
            delegateStatusAfter.selfDelegatedStake,
            delegateStatusAfter.delegatedStake,
            _stakeOwner,
            _updatedStake
        );
    }
}

function state(uint256 proposalId) public view returns(uint256) {
    require(
        proposalCount >= proposalId && proposalId > 0,
        "invalid proposal id"
    );
    if (proposalCanceled[proposalId]) {
        return possibleProposalStatesMapping["Canceled"];
    } else if (block.number <= proposalStartBlock[proposalId]) {
        return possibleProposalStatesMapping["Pending"];
    } else if (block.number <= proposalEndBlock[proposalId]) {
        return possibleProposalStatesMapping["Active"];
    } else if (
        proposalForVotes[proposalId] <= proposalAgainstVotes[proposalId] ||
        proposalForVotes[proposalId] < quorumVotesInWei
    ) {
        return possibleProposalStatesMapping["Defeated"];
    } else if (proposalEta[proposalId] == 0) {
        return possibleProposalStatesMapping["Succeeded"];
    } else if (proposalExecuted[proposalId]) {
        return possibleProposalStatesMapping["Executed"];
    } else if (
        block.timestamp >= proposalEta[proposalId].add(gracePeriodInSeconds)
    ) {
        return possibleProposalStatesMapping["Expired"];
    } else {
        return possibleProposalStatesMapping["Queued"];
    }
}

function _queueOrRevert(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
) internal {
    require(
        !queuedTransactions[keccak256(
            abi.encode(target, value, signature, data, eta)
        )],
        "already queued at eta"
    );
    _queueTransaction(target, value, signature, data, eta);
}

function _executeTransaction(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
) internal returns(bytes memory) {
    bytes32 txHash = keccak256(
        abi.encode(target, value, signature, data, eta)
    );
    require(queuedTransactions[txHash], "not queued");
    require(block.timestamp >= eta, "not past eta");
    require(block.timestamp <= eta.add(gracePeriodInSeconds), "stale");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(
            bytes4(keccak256(bytes(signature))),
            data
        );
    }
    (bool success, bytes memory returnData) = target.call {
        value: value
    }(
        callData
    );
    require(success, "execution reverted");
    emit ExecutedTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function _queueTransaction(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
) internal returns(bytes32) {
    require(
        eta >= block.timestamp.add(queuePeriodInSeconds),
        "not satisfy queue period"
    );
    bytes32 txHash = keccak256(
        abi.encode(target, value, signature, data, eta)
    );
    queuedTransactions[txHash] = true;
    emit QueuedTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

function claimRewards() external noReentrancy {
    uint256 mintage = _calculateMintage(msg.sender);
    uint256 mintagePiece = mintage.div(20);
    require(mintagePiece > 0);
    _lastClaim[msg.sender] = block.timestamp;
    _VYBE.mint(msg.sender, mintage.sub(mintagePiece));
    _VYBE.mint(_developerFund, mintagePiece);
    emit Rewards(msg.sender, mintage, mintagePiece);
}

function increaseStake(uint256 amount) external {
    require(_VYBE.transferFrom(msg.sender, address(this), amount));
    _totalStaked = _totalStaked.add(amount);
    if (_staked[msg.sender] == 0) {
        _lastClaim[msg.sender] = block.timestamp;
    }
    _staked[msg.sender] = _staked[msg.sender].add(amount);
}

function stake(uint256 amount) public {
    require(amount > 0, "Staking amount must be more than zero");
    require(IUniswapV2Pair(_UniswapV2Pair).transferFrom(_msgSender(), address(this), uint(amount)), "It has failed to transfer tokens from staker to contract.");
    if (_stakedAmount[_msgSender()] == 0) {
        _stakers.push(_msgSender());
    }
    _totalStakedAmount = _totalStakedAmount.add(amount);
    _stakedAmount[_msgSender()] = _stakedAmount[_msgSender()].add(amount);
    emit Staked(_msgSender(), amount);
}

function unstake(uint256 amount) public {
    require(IUniswapV2Pair(_UniswapV2Pair).transfer(_msgSender(), uint(amount)), "It has failed to transfer tokens from contract to staker.");
    _totalStakedAmount = _totalStakedAmount.sub(amount);
    _stakedAmount[_msgSender()] = _stakedAmount[_msgSender()].sub(amount);
    if (_stakedAmount[_msgSender()] == 0) {
        for (uint256 i = 0; i < _stakers.length; i++) {
            if (_stakers[i] == _msgSender()) {
                _stakers[i] = _stakers[_stakers.length.sub(1)];
                _stakers.pop();
                break;
            }
        }
    }
    emit Unstaked(_msgSender(), amount);
}

function _calculateMintage(address staker) private view returns(uint256) {
    uint256 share = _VYBE.totalSupply().div(20).div(_totalStaked.div(_staked[staker]));
    uint256 timeElapsed = block.timestamp.sub(_lastClaim[staker]);
    uint256 mintage = 0;
    if (timeElapsed > MONTH) {
        mintage = share.mul(timeElapsed.div(MONTH));
        timeElapsed = timeElapsed.mod(MONTH);
    }
    if (timeElapsed != 0) {
        mintage = mintage.add(share.div(MONTH.div(timeElapsed)));
    }
    return mintage;
}

function release() public returns(bool) {
    require(block.timestamp >= _released, "TokenTimelock: current time is before release time");
    uint256 value = _adminBalances[msg.sender];
    require(value > 0, "TokenTimelock: no tokens to release");
    _balances[msg.sender] = _balances[msg.sender].add(value);
    emit Transfer(contractOwner, msg.sender, value);
    return true;
}

function sendLockedToken(address beneficiary, uint256 value) public isOwner {
    require(_released > block.timestamp, "TokenTimelock: release time is before current time");
    require(value <= _balances[msg.sender]);
    _balances[msg.sender] = _balances[msg.sender].sub(value);
    _adminBalances[beneficiary] = value;
}

function queueTransaction(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
) public returns(bytes32) {
    require(msg.sender == admin, 'sbTimelock::queueTransaction: Call must come from admin.');
    require(
        eta >= getBlockTimestamp().add(delay),
        'sbTimelock::queueTransaction: Estimated execution block must satisfy delay.'
    );
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

function executeTransaction(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
) public payable returns(bytes memory) {
    require(msg.sender == admin, 'sbTimelock::executeTransaction: Call must come from admin.');
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "sbTimelock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "sbTimelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), 'sbTimelock::executeTransaction: Transaction is stale.');
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call {
        value: value
    }(callData);
    require(success, 'sbTimelock::executeTransaction: Transaction execution reverted.');
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function addMember(address addr, uint256 weight, bool isCertified) external override onlyElectionsContract onlyWhenActive returns(bool memberAdded) {
    MemberStatus memory status = membersStatus[addr];
    if (status.inCommittee) {
        return false;
    }
    (bool qualified, uint entryPos) = qualifiesToEnterCommittee(addr, weight, maxCommitteeSize);
    if (!qualified) {
        return false;
    }
    memberAdded = true;
    CommitteeStats memory _committeeStats = committeeStats;
    stakingRewardsContract.committeeMembershipWillChange(addr, weight, _committeeStats.totalWeight, false, true);
    feesAndBootstrapRewardsContract.committeeMembershipWillChange(addr, false, isCertified, isCertified, _committeeStats.generalCommitteeSize, _committeeStats.certifiedCommitteeSize);
    _committeeStats.generalCommitteeSize++;
    if (isCertified) _committeeStats.certifiedCommitteeSize++;
    _committeeStats.totalWeight = uint96(_committeeStats.totalWeight.add(weight));
    CommitteeMember memory newMember = CommitteeMember({
        addr: addr,
        weightAndCertifiedBit: packWeightCertification(weight, isCertified)
    });
    if (entryPos < committee.length) {
        CommitteeMember memory removed = committee[entryPos];
        unpackWeightCertification(removed.weightAndCertifiedBit);
        _committeeStats = removeMemberAtPos(entryPos, false, _committeeStats);
        committee[entryPos] = newMember;
    } else {
        committee.push(newMember);
    }
    status.inCommittee = true;
    status.pos = uint32(entryPos);
    membersStatus[addr] = status;
    committeeStats = _committeeStats;
    emit CommitteeChange(addr, weight, isCertified, true);
}

function memberCertificationChange(address addr, bool isCertified) external override onlyElectionsContract onlyWhenActive {
    MemberStatus memory status = membersStatus[addr];
    if (!status.inCommittee) {
        return;
    }
    CommitteeMember memory member = committee[status.pos];
    (uint weight, bool prevCertification) = getWeightCertification(member);
    CommitteeStats memory _committeeStats = committeeStats;
    feesAndBootstrapRewardsContract.committeeMembershipWillChange(addr, true, prevCertification, isCertified, _committeeStats.generalCommitteeSize, _committeeStats.certifiedCommitteeSize);
    committeeStats.certifiedCommitteeSize = _committeeStats.certifiedCommitteeSize - (prevCertification ? 1 : 0) + (isCertified ? 1 : 0);
    committee[status.pos].weightAndCertifiedBit = packWeightCertification(weight, isCertified);
    emit CommitteeChange(addr, weight, isCertified, true);
}

function removeMemberAtPos(uint pos, bool clearFromList, CommitteeStats memory _committeeStats) private returns(CommitteeStats memory newCommitteeStats) {
    CommitteeMember memory member = committee[pos];
    (uint weight, bool certification) = getWeightCertification(member);
    stakingRewardsContract.committeeMembershipWillChange(member.addr, weight, _committeeStats.totalWeight, true, false);
    feesAndBootstrapRewardsContract.committeeMembershipWillChange(member.addr, true, certification, certification, _committeeStats.generalCommitteeSize, _committeeStats.certifiedCommitteeSize);
    delete membersStatus[member.addr];
    _committeeStats.generalCommitteeSize--;
    if (certification) _committeeStats.certifiedCommitteeSize--;
    _committeeStats.totalWeight = uint96(_committeeStats.totalWeight.sub(weight));
    emit CommitteeChange(member.addr, weight, certification, false);
    if (clearFromList) {
        uint committeeLength = committee.length;
        if (pos < committeeLength - 1) {
            CommitteeMember memory last = committee[committeeLength - 1];
            committee[pos] = last;
            membersStatus[last.addr].pos = uint32(pos);
        }
        committee.pop();
    }
    return _committeeStats;
}

