}

function _getRewardsDue(
    uint256 upToDay,
    address miner,
    uint256 dayLastClaimedFor
) internal view returns(uint256) {
    uint256 rewards;
    for (uint256 day = dayLastClaimedFor.add(1); day <= upToDay.sub(7); day++) {
        (, , uint256 minerMineSecondsForDay) = _getMinerMineData(miner, day);
        (, , uint256 mineSecondsForDay) = _getMineData(day);
        if (mineSecondsForDay == 0) {
            continue;
        }
        uint256 strongPoolDayRewards = dayRewards[day];
        uint256 amount = strongPoolDayRewards.mul(minerMineSecondsForDay).div(mineSecondsForDay);
        rewards = rewards.add(amount);
    }
    return rewards;
}

function receiveRewards(uint256 day, uint256 amount) external {
    require(amount > 0, 'zero');
    require(
        msg.sender == address(sbController),
        'not sbController'
    );
    strongToken.transferFrom(address(sbController), address(this), amount);
    dayRewards[day] = dayRewards[day].add(amount);
    emit RewardsReceived(day, amount);
}

function voteCheck(uint voterId, uint tournamentId, uint roundId) internal view {
    require(roundId > 0, 'Tournament not started yet');
    require(identity.ownerOf(voterId) == msg.sender, 'Must own identity to vote with it');
    require(roundId > identities[voterId].lastRoundVoted[tournamentId], 'Can only vote one time per round');
    require(tournaments[tournamentId].minimumRank <= identities[voterId].rank, 'Insufficient rank to participate in this tournament');
}

function resolveRound(uint tournamentId, uint roundId, uint winningOption) public {
    Tournament storage tournament = tournaments[tournamentId];
    require(msg.sender == tournament.winnerOracle, 'Only winner oracle can call this');
    uint currentRoundId = getCurrentRoundId(tournamentId);
    Round storage round = tournament.rounds[roundId];
    require(roundAlreadyResolved(tournamentId, roundId) == false, 'Round already resolved');
    require(currentRoundId > roundId + 1, 'Too early to resolve');
    round.roundId = roundId;
    round.winningOption = winningOption;
    emit RoundResolved(tournamentId, roundId, winningOption);
}

function updateAccount(uint voterId, uint tournamentId, uint roundId) public {
    IdMetadata storage id = identities[voterId];
    Tournament storage tournament = tournaments[tournamentId];
    bool roundResolved = roundAlreadyResolved(tournamentId, roundId);
    bool shouldSync = isSynced(voterId, tournamentId, roundId) == false;
    if (shouldSync && roundResolved) {
        syncMap[voterId][tournamentId][roundId] = true; 
        (uint voiceCreditBonus, uint tokenBonus) = getRoundBonus(voterId, tournamentId, roundId);
        tournament.voiceCredits[voterId] = getVoiceCredits(tournamentId, voterId).plus(voiceCreditBonus);
        tokensWon[voterId] = tokensWon[voterId].plus(tokenBonus);
        id.cumulativeBonus = id.cumulativeBonus.plus(voiceCreditBonus);
        emit AccountSynced(tournamentId, voterId);
    }
}

function getCurrentRoundId(uint tournamentId) public view returns(uint) {
    Tournament storage tournament = tournaments[tournamentId];
    uint startTime = tournament.startTime;
    uint roundLengthSeconds = tournament.roundLengthSeconds;
    if (block.timestamp >= startTime) {
        return 1 + ((block.timestamp - startTime) / roundLengthSeconds);
    } else {
        return 0;
    }
}

function roundAlreadyResolved(uint tournamentId, uint roundId) public view returns(bool) {
    return tournaments[tournamentId].rounds[roundId].winningOption > 0;
}

function setProtocolVersion(string calldata deploymentSubset, uint256 nextVersion, uint256 fromTimestamp) external override onlyFunctionalManager {
    require(deploymentSubsets[deploymentSubset].exists, "deployment subset does not exist");
    require(fromTimestamp > now, "a protocol update can only be scheduled for the future");
    (bool prevUpgradeExecuted, uint256 currentVersion) = checkPrevUpgrades(deploymentSubset);
    require(nextVersion >= currentVersion, "protocol version must be greater or equal to current version");
    deploymentSubsets[deploymentSubset].nextVersion = nextVersion;
    deploymentSubsets[deploymentSubset].fromTimestamp = fromTimestamp;
    if (prevUpgradeExecuted) {
        deploymentSubsets[deploymentSubset].currentVersion = currentVersion;
    }
    emit ProtocolVersionChanged(deploymentSubset, currentVersion, nextVersion, fromTimestamp);
}

function checkPrevUpgrades(string memory deploymentSubset) private view returns(bool prevUpgradeExecuted, uint256 currentVersion) {
    prevUpgradeExecuted = deploymentSubsets[deploymentSubset].fromTimestamp <= now;
    currentVersion = prevUpgradeExecuted ? deploymentSubsets[deploymentSubset].nextVersion :
        deploymentSubsets[deploymentSubset].currentVersion;
}

function setHostClaimsRent(bytes32 rsvid) external onlyHost(rsvid)
{
    Reservation storage thisreservation = Reservations[rsvid];
    require(thisreservation.rstatus == reservationstatus.ACTIVATED, "Reservation must be ACTIVATED");
    uint reservationstart21Hrs = mathlib.add(thisreservation.reservationstart, secondsin21hrs);
    require(now >= reservationstart21Hrs, "Host can only claim the rent 21 Hrs after reservation start");
    uint rsvbalance = thisreservation.advancepayment;
    thisreservation.advancepayment = 0;
    thisreservation.rstatus = reservationstatus.COMPLETED;
    daiToken.transfer(thisreservation.host, rsvbalance);
    emit ReservationStatusEvent(rsvid, thisreservation.rstatus, thisreservation.advancepayment, now);
}

function createnewReservation(address host, uint reservationstart, uint reservationend, uint dailyprice, uint advancepayment, bytes8 rstartformat, bytes8 rendformat) external
{
    require(factorycontractactive, "Factory Contract should be Active");
    require(reservationid < maxuint, "Maximum reservationid reached");
    require(msg.sender != host, "Host and Guest can not be same");
    require(dailyprice > 0, "Daily Price should be > 0");
    require(now < mathlib.add(reservationstart, secondsin21hrs), "Too late to start this reservation");
    uint lengthofstay = mathlib.calculatereservationdays(reservationstart, reservationend);
    require(lengthofstay > 0, "Length of Stay should be > 0");
    uint totalreservationamount = mathlib.mul(dailyprice, lengthofstay);
    uint minadvpayment = lengthofstay > 5 ? mathlib.mul(dailyprice, 2) : dailyprice;
    require(advancepayment >= minadvpayment && advancepayment <= totalreservationamount, "Advance Payment should be >= minadvpayment and <= reservation amount ");
    require(daiToken.allowance(msg.sender, address(this)) >= mathlib.add(advancepayment, reservationfee), "daiToken allowance exceeded");
    bytes32 rsvid = keccak256(abi.encodePacked(reservationid));
    Reservations[rsvid] = Reservation(msg.sender, host, reservationstart, reservationend, dailyprice, advancepayment, reservationstatus.ACTIVATED);
    reservationid = mathlib.add(reservationid, 1);
    daiToken.transferFrom(msg.sender, address(this), advancepayment);
    daiToken.transferFrom(msg.sender, manager, reservationfee);
    emit NewReservationEvent(rsvid, msg.sender, host, reservationstart, reservationend, dailyprice, advancepayment, rstartformat, rendformat, now);
}

function setGuestCancelReservation(bytes32 rsvid) external onlyGuest(rsvid)
{
    Reservation storage thisreservation = Reservations[rsvid];
    require(thisreservation.rstatus == reservationstatus.ACTIVATED, "Reservation must be ACTIVATED");
    uint reservationstart21Hrs = mathlib.add(thisreservation.reservationstart, secondsin21hrs);
    require(now < reservationstart21Hrs, "Guest can only cancel upto 21 Hrs after reservation start");
    uint lengthofstay = mathlib.calculatereservationdays(thisreservation.reservationstart, thisreservation.reservationend);
    uint cancellationperiod = lengthofstay > 5 ? 5 : 3;
    uint rsvbalance = thisreservation.advancepayment;
    thisreservation.advancepayment = 0;
    thisreservation.rstatus = reservationstatus.CANCELLED;
    if (now < mathlib.sub(thisreservation.reservationstart, mathlib.mul(cancellationperiod, secondsinday)))
    {
        daiToken.transfer(thisreservation.guest, rsvbalance);
    } else
    {
        uint cancellationfee = lengthofstay > 5 ? mathlib.mul(thisreservation.dailyprice, 2) : thisreservation.dailyprice;
        uint guestdue = mathlib.sub(rsvbalance, cancellationfee);
        daiToken.transfer(thisreservation.host, cancellationfee);
        if (guestdue > 0)
        {
            daiToken.transfer(thisreservation.guest, guestdue);
        }
    }
    emit ReservationStatusEvent(rsvid, thisreservation.rstatus, thisreservation.advancepayment, now);
}

function setHostRefundsPartRent(bytes32 rsvid, uint refundamount) external onlyHost(rsvid)
{
    Reservation storage thisreservation = Reservations[rsvid];
    require(thisreservation.rstatus == reservationstatus.ACTIVATED, "Reservation has to be ACTIVATED");
    uint reservationstart21Hrs = mathlib.add(thisreservation.reservationstart, secondsin21hrs);
    require(now >= reservationstart21Hrs, "Host can refund part of contract balance 21 Hrs after Reservation Start");
    uint rsvbalance = thisreservation.advancepayment;
    require(refundamount > 0 && refundamount <= rsvbalance, "Refund amount should be > 0 && <= rsvbalance");
    uint hostdue = mathlib.sub(rsvbalance, refundamount);
    thisreservation.advancepayment = 0;
    thisreservation.rstatus = reservationstatus.COMPLETED;
    daiToken.transfer(thisreservation.guest, refundamount);
    if (hostdue > 0)
    {
        daiToken.transfer(thisreservation.host, hostdue);
    }
    emit ReservationStatusEvent(rsvid, thisreservation.rstatus, thisreservation.advancepayment, now);
}

function setHostCancelsReservation(bytes32 rsvid) external onlyHost(rsvid)
{
    Reservation storage thisreservation = Reservations[rsvid];
    require(thisreservation.rstatus == reservationstatus.ACTIVATED, "Reservation must be ACTIVATED");
    uint reservationstart21Hrs = mathlib.add(thisreservation.reservationstart, secondsin21hrs);
    require(now < reservationstart21Hrs, "Reservation Can be CANCELLED upto 21 Hrs after reservation start");
    uint rsvbalance = thisreservation.advancepayment;
    thisreservation.advancepayment = 0;
    thisreservation.rstatus = reservationstatus.CANCELLED;
    daiToken.transfer(thisreservation.guest, rsvbalance);
    emit ReservationStatusEvent(rsvid, thisreservation.rstatus, thisreservation.advancepayment, now);
}

function mine(uint256 amount) public payable {
    require(amount > 0, "zero");
    if (whitelistActive) {
        require(whitelist[msg.sender], "invalid miner");
        require(amount <= whitelistAmount[msg.sender], "1: too much");
    }
    uint256 currentDay = _getCurrentDay();
    (, uint256 tokens, ) = _getMinerMineData(msg.sender, currentDay);
    require(tokens <= whitelistAmount[msg.sender], "2: too much");
    (uint256 numerator, uint256 denominator) = sbController
        .getValuePoolMiningFee(address(this));
    uint256 fee = amount.mul(numerator).div(denominator);
    require(msg.value == fee, "invalid fee");
    sbEthFeePool.deposit {
        value: msg.value
    }();
    token.transferFrom(msg.sender, address(this), amount);
    _update(
        minerMineDays[msg.sender],
        minerMineAmounts[msg.sender],
        minerMineMineSeconds[msg.sender],
        amount,
        true,
        currentDay
    );
    _update(
        mineDays,
        mineAmounts,
        mineMineSeconds,
        amount,
        true,
        currentDay
    );
}

function removeFromWhitelist(address miner) public {
    require(msg.sender == superAdmin, "not admin");
    require(whitelist[miner], "invalid miner");
    whitelist[miner] = false;
    whitelistAmount[miner] = 0;
    uint256 currentDay = _getCurrentDay();
    (, uint256 amount, ) = _getMinerMineData(miner, currentDay);
    if (amount != 0) {
        _update(
            minerMineDays[miner],
            minerMineAmounts[miner],
            minerMineMineSeconds[miner],
            amount,
            false,
            currentDay
        );
        _update(
            mineDays,
            mineAmounts,
            mineMineSeconds,
            amount,
            false,
            currentDay
        );
        token.transfer(miner, amount);
    }
}

function destroyChildren(uint256 value) internal {
    uint256 tail = s_tail;
    for (uint256 i = tail + 1; i <= tail + value; i++) {
        mk_contract_address(this, i).call();
    }
    s_tail = tail + value;
}

function freeFromUpTo(address from, uint256 value) public returns(uint256 freed) {
    address spender = msg.sender;
    uint256 from_balance = s_balances[from];
    if (value > from_balance) {
        value = from_balance;
    }
    mapping(address => uint256) from_allowances = s_allowances[from];
    uint256 spender_allowance = from_allowances[spender];
    if (value > spender_allowance) {
        value = spender_allowance;
    }
    destroyChildren(value);
    s_balances[from] = from_balance - value;
    from_allowances[spender] = spender_allowance - value;
    return value;
}

function freeFrom(address from, uint256 value) public returns(bool success) {
    address spender = msg.sender;
    uint256 from_balance = s_balances[from];
    if (value > from_balance) {
        return false;
    }
    mapping(address => uint256) from_allowances = s_allowances[from];
    uint256 spender_allowance = from_allowances[spender];
    if (value > spender_allowance) {
        return false;
    }
    destroyChildren(value);
    s_balances[from] = from_balance - value;
    from_allowances[spender] = spender_allowance - value;
    return true;
}

function free(uint256 value) public returns(bool success) {
    uint256 from_balance = s_balances[msg.sender];
    if (value > from_balance) {
        return false;
    }
    destroyChildren(value);
    s_balances[msg.sender] = from_balance - value;
    return true;
}

function freeUpTo(uint256 value) public returns(uint256 freed) {
    uint256 from_balance = s_balances[msg.sender];
    if (value > from_balance) {
        value = from_balance;
    }
    destroyChildren(value);
    s_balances[msg.sender] = from_balance - value;
    return value;
}

function submitClaim(
    bytes32 blockHeader,
    bytes32 seedHash,
    bytes32 target,
    uint blockNumber,
    uint blockPayment,
    address payable miningPoolAddress,
    address mevProducerAddress,
    uint8 v,
    bytes32 r,
    bytes32 s,
    uint blockNonce,
    bytes32 mixDigest
) public {
    require(msg.sender == blockSubmissionsOperator[miningPoolAddress] || msg.sender == miningPoolAddress);
    bytes32 hash = keccak256(abi.encodePacked(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress));
    if (claimedBlockNonce[hash] == 0 && blockNonce < FLAG_BLOCK_NONCE_LIMIT) {
        if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash)), v, r, s) == mevProducerAddress) {
            require(depositedEther[mevProducerAddress] >= blockPayment);
            claimedBlockNonce[hash] = FLAG_BLOCK_NONCE_LIMIT + blockNonce;
            claimedBlockMixDigest[hash] = mixDigest;
            depositedEther[mevProducerAddress] -= blockPayment;
            miningPoolAddress.transfer(blockPayment);
            emit BlockClaimed(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress, mevProducerAddress, blockNonce, mixDigest);
        }
    }
}

function withdrawUpTo(uint etherAmount) external {
    require(depositedEther[msg.sender] > 0);
    require(block.timestamp > timestampOfPossibleExit[msg.sender]);
    if (depositedEther[msg.sender] < etherAmount)
        etherAmount = depositedEther[msg.sender];
    depositedEther[msg.sender] -= etherAmount;
    msg.sender.transfer(etherAmount);
    emit Withdraw(msg.sender, etherAmount);
}

function remainingDurationForWorkClaim(
    bytes32 blockHeader,
    bytes32 seedHash,
    bytes32 target,
    uint blockNumber,
    uint blockPayment,
    address miningPoolAddress,
    address mevProducerAddress,
    uint8 v,
    bytes32 r,
    bytes32 s
) public view returns(uint) {
    bytes32 hash = keccak256(abi.encodePacked(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress));
    if (claimedBlockNonce[hash] != 0) return 0;
    if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash)), v, r, s) != mevProducerAddress) return 0;
    if (depositedEther[mevProducerAddress] < blockPayment) return 0;
    if (block.timestamp >= timestampOfPossibleExit[mevProducerAddress]) return 0;
    return timestampOfPossibleExit[mevProducerAddress] - block.timestamp;
}

function multiSigWithdrawal(address to, uint amount) public onlyBenefeciary returns(bool success) {
    if (reqTime == 0 && reqAmount == 0) {
        reqTime = now.add(3600);
        reqAmount = amount;
        reqAddress = msg.sender;
        reqTo = to;
    } else {
        if (msg.sender != reqAddress && to == reqTo && amount == reqAmount && now < reqTime) {
            to.transfer(amount);
        }
        reqTime = 0;
        reqAmount = 0;
        reqAddress = address(0);
        reqTo = address(0);
    }
    return true;
}

function() payable public {
    emit Funds(msg.sender, msg.value);
    ben3.transfer(msg.value.mul(3).div(100));
    contractBalance = address(this).balance;
}

function unfreezeTeamTokens(address unFreezeAddress) public onlyOwner returns(bool success) {
    require(balances[FreezeAddress] > 0);
    require(now >= FreezeTokensReleaseTime);
    balances[FreezeAddress] = balances[FreezeAddress].sub(FreezeTokens);
    balances[unFreezeAddress] = balances[unFreezeAddress].add(FreezeTokens);
    emit Transfer(FreezeAddress, unFreezeAddress, FreezeTokens);
    return true;
}

function voteOnProposal(bool voteFor) external
proposalPending()
onlyVoters()
notVoted() {
    require((block.timestamp - currentProposal.timestamp) <= proposalLife);
    if (voteFor) {
        currentProposal.yay.push(msg.sender);
        if (currentProposal.yay.length >= votingThreshold) {
            _doProposal();
            proposalInProgress = false;
            return;
        }
    } else {
        currentProposal.nay.push(msg.sender);
        if (currentProposal.nay.length >= votingThreshold) {
            proposalInProgress = false;
            cooldownStart = block.timestamp;
            return;
        }
    }
}

function _doProposal() internal {
    if (currentProposal.methodId == 0) HorseyToken(tokenAddress).setRenamingCosts(currentProposal.parameter);
    if (currentProposal.methodId == 1) HorseyExchange(exchangeAddress).setMarketFees(currentProposal.parameter);
    if (currentProposal.methodId == 2) HorseyToken(tokenAddress).addLegitDevAddress(address(currentProposal.parameter));
    if (currentProposal.methodId == 3) HorseyToken(tokenAddress).addHorseIndex(bytes32(currentProposal.parameter));
    if (currentProposal.methodId == 4) {
        if (currentProposal.parameter == 0) {
            HorseyExchange(exchangeAddress).unpause();
            HorseyToken(tokenAddress).unpause();
        } else {
            HorseyExchange(exchangeAddress).pause();
            HorseyToken(tokenAddress).pause();
        }
    }
    if (currentProposal.methodId == 5) HorseyToken(tokenAddress).setClaimingCosts(currentProposal.parameter);
    if (currentProposal.methodId == 8) {
        HorseyToken(tokenAddress).setCarrotsMultiplier(uint8(currentProposal.parameter));
    }
    if (currentProposal.methodId == 9) {
        HorseyToken(tokenAddress).setRarityMultiplier(uint8(currentProposal.parameter));
    }
    emit ProposalPassed(currentProposal.methodId, currentProposal.parameter, currentProposal.proposer);
}

function feed(uint256 tokenId) external
whenNotPaused()
onlyOwnerOf(tokenId)
carrotsMeetLevel(tokenId)
noFeedingInProgress() {
    pendingFeedings[msg.sender] = FeedingData(block.number, tokenId);
    uint8 feedingCounter;
    (, , feedingCounter, ) = stables.horseys(tokenId);
    stables.storeCarrotsCredit(msg.sender, stables.carrot_credits(msg.sender) - uint32(feedingCounter));
    emit Feeding(tokenId);
}

function depositToExchange(uint256 tokenId, uint256 price) external
whenNotPaused()
isTokenOwner(tokenId)
nonZeroPrice(price)
tokenAvailable() {
