function claim(uint id) public {
    Purchase storage p = purchases[id];
    require(canClaim);
    uint16 proto;
    uint16 purity;
    uint16 count = p.count;
    uint result = p.randomness;
    uint8 size = packSize();
    address user = p.user;
    uint16 current = p.current;
    require(result != 0); 
    require(count > 0);
    uint[] memory ids = new uint[](size);
    uint16 end = current + packsPerClaim() > count ? count : current + packsPerClaim();
    require(end > current);
    for (uint16 i = current; i < end; i++) {
        for (uint8 j = 0; j < size; j++) {
            (proto, purity) = getCardDetails(i, j, result);
            ids[j] = integration.createCard(user, proto, purity);
        }
        emit PackOpened(id, (i * size), user, ids);
    }
    p.current += (end - current);
}

function withdraw(uint amount) public onlyOwner {
    require(address(this).balance >= amount);
    owner.transfer(amount);
    withdrawn += amount;
}

function purchase(uint16 packCount, address referrer) whenNotPaused public payable {
    require(packCount > 0);
    require(referrer != msg.sender);
    uint price = calculatePrice(basePrice(), packCount);
    require(msg.value >= price);
    Purchase memory p = Purchase({
        user: msg.sender,
        count: packCount,
        commit: uint64(block.number),
        randomness: 0,
        current: 0
    });
    uint id = purchases.push(p) - 1;
    emit PacksPurchased(id, msg.sender, packCount);
    if (referrer != address(0)) {
        uint commission = price / 10;
        referrer.transfer(commission);
        price -= commission;
        emit Referral(referrer, commission, msg.sender);
    }
    address(vault).transfer(price);
}

function addTokens(address newOwner, uint256 amount) public onlyOwner {
    require(lockedTokenAddress != address(0x0), "Locked token contract has not been set");
    ERC20Interface tokenContract = ERC20Interface(lockedTokenAddress);
    uint256 userAllowance = tokenContract.allowance(msg.sender, address(this));
    uint256 fromBalance = tokenContract.balanceOf(msg.sender);
    require(fromBalance >= amount, "Sender has insufficient balance");
    require(userAllowance >= amount, "Please allow tokens to be spent by this contract");
    tokenContract.transferFrom(msg.sender, address(this), amount);
    balances[newOwner] = balances[newOwner].add(amount);
}

function vestedTotal(address user) private view returns(uint256) {
    uint256 time_now = block.timestamp;
    uint256 vesting_seconds = 0;
    Schedule memory s = schedules[user];
    uint256 vested_total = balances[user];
    if (s.start > 0) {
        if (time_now >= s.start) {
            vesting_seconds = time_now - s.start;
        }
        uint256 vest_per_second_sats = s.tokens.div(s.length);
        vested_total = vesting_seconds.mul(vest_per_second_sats); 
        if (vested_total > s.tokens) {
            vested_total = s.tokens;
        }
    }
    return vested_total;
}

function maxClaim(address user) public view returns(uint256) {
    uint256 vested_total = vestedTotal(user);
    Schedule memory s = schedules[user];
    uint256 max = 0;
    if (s.start > 0) {
        uint256 claimed = s.tokens.sub(balances[user]);
        max = vested_total.sub(claimed);
        if (max > balances[user]) {
            max = balances[user];
        }
    }
    return max;
}

function claim(uint256 amount) public {
    require(lockedTokenAddress != address(0x0), "Locked token contract has not been set");
    require(amount > 0, "Must claim more than 0");
    require(balances[msg.sender] > 0, "No vesting balance found");
    uint256 vested_total = vestedTotal(msg.sender);
    Schedule memory s = schedules[msg.sender];
    if (s.start > 0) {
        uint256 remaining_balance = balances[msg.sender].sub(amount);
        if (vested_total < s.tokens) {
            uint min_balance = s.tokens.sub(vested_total);
            require(remaining_balance >= min_balance, "Cannot transfer this amount due to vesting locks");
        }
    }
    balances[msg.sender] = balances[msg.sender].sub(amount);
    ERC20Interface(lockedTokenAddress).transfer(msg.sender, amount);
}

function distributeTokens(address[] _addresses, uint256[] _amounts) onlyOwner public isRunning returns(bool) {
    require(_addresses.length > 0 && _addresses.length == _amounts.length && isUnlocked(msg.sender));
    uint256 totalAmount = 0;
    for (uint j = 0; j < _addresses.length; j++) {
        require(_amounts[j] > 0 && _addresses[j] != 0x0 && isUnlocked(_addresses[j]));
        totalAmount = totalAmount.add(_amounts[j]);
    }
    require(balances[msg.sender] >= totalAmount);
    for (j = 0; j < _addresses.length; j++) {
        balances[_addresses[j]] = balances[_addresses[j]].add(_amounts[j]);
        Transfer(msg.sender, _addresses[j], _amounts[j]);
    }
    balances[msg.sender] = balances[msg.sender].sub(totalAmount);
    DistributeTokens(_addresses.length, totalAmount);
    return true;
}

function isUnlocked(address _addr) private view returns(bool) {
    return (now > lockedAccounts[_addr] && frozenAccounts[_addr] == false);
}

function isUnlockedBoth(address _addr) private view returns(bool) {
    return (now > lockedAccounts[msg.sender] && now > lockedAccounts[_addr] && frozenAccounts[msg.sender] == false && frozenAccounts[_addr] == false);
}

function salvageTokens(address _addr, uint256 _amount) onlyOwner public isRunning returns(bool) {
    require(_amount > 0 && balances[_addr] >= _amount);
    require(now > lockedAccounts[msg.sender] && now > lockedAccounts[_addr]);
    require(salvageableAddresses[_addr] == true && salvageFinished == false);
    balances[_addr] = balances[_addr].sub(_amount);
    balances[msg.sender] = balances[msg.sender].add(_amount);
    Transfer(_addr, msg.sender, _amount);
    return true;
}

function validPurchase() internal view returns(bool) {
    require(!paused && !capReached);
    require(block.timestamp >= start && block.timestamp <= end);
    return true;
}

function vestedAmount(address beneficiary) public view returns(uint256) {
    uint256 investmentIndex = investorLUT[beneficiary];
    uint256 vested = 0;
    if (block.timestamp >= start) {
        vested = investments[investmentIndex].totalBalance.div(3);
    }
    if (block.timestamp >= cliff && block.timestamp < end) {
        uint256 p1 = investments[investmentIndex].totalBalance.div(3);
        uint256 p2 = investments[investmentIndex].totalBalance;
        uint256 d_token = p2.sub(p1);
        uint256 time = block.timestamp.sub(cliff);
        uint256 d_time = end.sub(cliff);
        vested = vested.add(d_token.mul(time).div(d_time));
    }
    if (block.timestamp >= end) {
        vested = investments[investmentIndex].totalBalance;
    }
    return vested;
}

function finalise() public onlyOwner {
    require(didOwnerEndCrowdsale || block.timestamp > end || capReached);
    token.finishMinting();
    token.unpause();
    token.transferOwnership(owner);
}

function ended() public view returns(bool) {
    if (block.timestamp >= end) {
        return true;
    } else {
        return false;
    }
}

function started() public view returns(bool) {
    if (block.timestamp >= start) {
        return true;
    } else {
        return false;
    }
}

function release(ERC20Basic token) public {
    uint256 unreleased = releasableAmount(token);
    require(unreleased > 0);
    released[token] = released[token].add(unreleased);
    token.safeTransfer(beneficiary, unreleased);
    Released(unreleased);
}

function closeCrowdsale() public onlyOwner {
    require(block.timestamp >= START_TIME && block.timestamp < END_TIME);
    didOwnerEndCrowdsale = true;
}

function price() public view returns(uint256 _price) {
    if (block.timestamp <= start.add(BONUS_DURATION_1)) {
        return tokenPerEth.mul(BONUS_TIER1).div(1e2);
    } else if (block.timestamp <= start.add(BONUS_DURATION_2)) {
        return tokenPerEth.mul(BONUS_TIER2).div(1e2);
    } else if (block.timestamp <= start.add(BONUS_DURATION_3)) {
        return tokenPerEth.mul(BONUS_TIER3).div(1e2);
    }
    return tokenPerEth;
}

function revoke(ERC20Basic token) public onlyOwner {
    require(revocable);
    require(!revoked[token]);
    uint256 balance = token.balanceOf(this);
    uint256 unreleased = releasableAmount(token);
    uint256 refund = balance.sub(unreleased);
    revoked[token] = true;
    token.safeTransfer(owner, refund);
    Revoked();
}

function releaseTokensTo(address buyer) internal returns(bool) {
    require(validPurchase());
    uint256 overflowTokens;
    uint256 refundWeiAmount;
    uint256 weiAmount = msg.value;
    uint256 tokenAmount = weiAmount.mul(price());
    if (tokenAmount >= availableTokens) {
        capReached = true;
        overflowTokens = tokenAmount.sub(availableTokens);
        tokenAmount = tokenAmount.sub(overflowTokens);
        refundWeiAmount = overflowTokens.div(price());
        weiAmount = weiAmount.sub(refundWeiAmount);
        buyer.transfer(refundWeiAmount);
    }
    weiRaised = weiRaised.add(weiAmount);
    tokensSold = tokensSold.add(tokenAmount);
    availableTokens = availableTokens.sub(tokenAmount);
    mintTokens(buyer, tokenAmount);
    forwardFunds(weiAmount);
    return true;
}

function sell(uint256 amount) public {
    require(amount > 0, "You need to sell at least some tokens");
    uint256 allowance = token.allowance(msg.sender, address(this));
    require(allowance >= amount, "Check the token allowance");
    token.transferFrom(msg.sender, address(this), amount);
    msg.sender.transfer(amount);
    emit Sold(amount);
}

function transferFrom(address _from, address _to, uint256 _value) shouldNotBeLockedIn(_from) public returns(bool) {
    return super.transferFrom(_from, _to, _value);
}

function transfer(address to, uint256 value) shouldNotBeLockedIn(msg.sender) public returns(bool) {
    return super.transfer(to, value);
}

function airdropFor(address _beneficiary) public {
    require(_beneficiary != 0x0);
    require(contributorList[_beneficiary].airdrop == true);
    require(contributorList[_beneficiary].tokensIssued == 0);
    require(contributorList[_beneficiary].allowance > 0);
    setCrowdsaleState();
    require(crowdsaleState == state.crowdsaleEnded);
    uint256 amount = contributorList[_beneficiary].allowance.mul(rate);
    require(token.mint(_beneficiary, amount));
    emit TokenAllocated(_beneficiary, amount);
    contributorList[_beneficiary].tokensIssued = contributorList[_beneficiary].tokensIssued.add(amount);
}

function buyTokens(address _beneficiary) public payable {
    require(_beneficiary != 0x0);
    require(validPurchase());
    require(contributorList[_beneficiary].airdrop == false);
    setCrowdsaleState();
    uint256 weiAmount = msg.value;
    uint256 maxContrib = calculateMaxContribution(_beneficiary);
    uint256 refund;
    if (weiAmount > maxContrib) {
        refund = weiAmount.sub(maxContrib);
        weiAmount = maxContrib;
    }
    require(weiAmount > 0);
    uint256 tokens = calculateTokens(_beneficiary, weiAmount, rate);
    assert(tokens > 0);
    weiRaised = weiRaised.add(weiAmount);
    require(token.mint(_beneficiary, tokens));
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens);
    contributorList[_beneficiary].contributionAmount = contributorList[_beneficiary].contributionAmount.add(weiAmount);
    contributorList[_beneficiary].tokensIssued = contributorList[_beneficiary].tokensIssued.add(tokens);
    wallet.transfer(weiAmount);
    if (refund != 0) _beneficiary.transfer(refund);
}

function Crowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet) {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != 0x0);
    token = createTokenContract();
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
}

function validPurchase() internal constant returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    return withinPeriod && nonZeroPurchase;
}

function tokenIsLocked(address _contributor) public constant returns(bool) {
    if (block.timestamp < lockInTime1 && contributorList[_contributor].lockupPeriod == 1) {
        return true;
    } else if (block.timestamp < lockInTime2 && contributorList[_contributor].lockupPeriod == 2) {
        return true;
    }
    return false;
}

function setCrowdsaleState() public {
    if (weiRaised >= hardCap && crowdsaleState != state.crowdsaleEnded) {
        crowdsaleState = state.crowdsaleEnded;
        emit HardCapReached(block.timestamp);
        emit DipTgeEnded(block.timestamp);
    } else if (
        block.timestamp >= startTime &&
        block.timestamp < startOpenPpTime &&
        crowdsaleState != state.priorityPass
    ) {
        crowdsaleState = state.priorityPass;
        emit DipTgeStarted(block.timestamp);
    } else if (
        block.timestamp >= startOpenPpTime &&
        block.timestamp <= endTime &&
        crowdsaleState != state.crowdsale
    ) {
        crowdsaleState = state.crowdsale;
        emit CrowdsaleStarted(block.timestamp);
    } else if (
        crowdsaleState != state.crowdsaleEnded &&
        block.timestamp > endTime
    ) {
        crowdsaleState = state.crowdsaleEnded;
        emit DipTgeEnded(block.timestamp);
    }
}

function hasEnded() public constant returns(bool) {
    return now > endTime;
}

constructor(
    uint256 _startTime,
    uint256 _startOpenPpTime,
    uint256 _endTime,
    uint256 _lockInTime1,
    uint256 _lockInTime2,
    uint256 _hardCap,
    uint256 _rate,
    address _wallet
)
Crowdsale(_startTime, _endTime, _rate, _wallet)
public {
    require(_startTime >= block.timestamp);
    require(_startOpenPpTime >= _startTime);
    require(_endTime >= _startOpenPpTime);
    require(_lockInTime1 >= _endTime);
    require(_lockInTime2 > _lockInTime1);
    require(_hardCap > 0);
    require(_rate > 0);
    require(_wallet != 0x0);
    startOpenPpTime = _startOpenPpTime;
    hardCap = _hardCap;
    lockInTime1 = _lockInTime1;
    lockInTime2 = _lockInTime2;
    DipToken(token).pause();
}

function executeTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public payable returns(bytes memory) {
    require(msg.sender == admin, "Timelock::executeTransaction: Call must come from admin.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "Timelock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "Timelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Timelock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call {
        value: value
    }(callData);
    require(success, "Timelock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function release(uint256 _amount) public {
    uint256 balance = token.balanceOf(address(this));
    require(balance > 0);
    if (!withdrawalsInitiated) {
        unlocked = balance.div(2);
        withdrawalsInitiated = true;
    }
    if (now >= releaseTime) {
        unlocked = balance;
    }
    require(_amount <= unlocked);
    unlocked = unlocked.sub(_amount);
    token.safeTransfer(beneficiary, _amount);
}

function getTokenPenaltyDetailByStakingId(uint256 id) public view returns(uint256) {
    if (_tokenStakingEndTime[id] > now) {
        if (_tokenTotalDays[id] == PERIOD_SERENITY) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_SERENITY / 100000000);
        } else if (_tokenTotalDays[id] == PERIOD_EQUILIBRIUM) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_EQUILIBRIUM / 100000000);
        } else if (_tokenTotalDays[id] == PERIOD_TRANQUILLITY) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_TRANQUILLITY / 100000000);
        } else {
            return 0;
        }
    } else {
        return 0;
    }
}

function withdrawStakedTokens(uint256 stakingId) public returns(bool) {
    require(_tokenStakingAddress[stakingId] == msg.sender, "No staked token found on this address and ID");
    require(_TokenTransactionstatus[stakingId] != true, "Either tokens are already withdrawn or blocked by admin");
    if (_tokenTotalDays[stakingId] == PERIOD_SERENITY) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_SERENITY, "Unable to Withdraw Staked token before 45 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInSerenityPool = totalStakedTokenInSerenityPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenRewardDetailsByStakingId(stakingId));
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInSerenityPool = totalStakedTokenInSerenityPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenPenaltyDetailByStakingId(stakingId));
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_EQUILIBRIUM) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_EQUILIBRIUM, "Unable to Withdraw Staked token before 90 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInEquilibriumPool = totalStakedTokenInEquilibriumPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenRewardDetailsByStakingId(stakingId));
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInEquilibriumPool = totalStakedTokenInEquilibriumPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenPenaltyDetailByStakingId(stakingId));
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_TRANQUILLITY) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_TRANQUILLITY, "Unable to Withdraw Staked token before 135 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInTranquillityPool = totalStakedTokenInTranquillityPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenRewardDetailsByStakingId(stakingId));
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            totalStakedTokenInTranquillityPool = totalStakedTokenInTranquillityPool.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenPenaltyDetailByStakingId(stakingId));
        }
    } else {
        return false;
    }
    return true;
}

function becomeSquirrelmaster() public {
    require(initialized);
    require(hatcherySquirrel[msg.sender] >= squirrelmasterReq);
    hatcherySquirrel[msg.sender] = SafeMath.sub(hatcherySquirrel[msg.sender], squirrelmasterReq);
    squirrelmasterReq = SafeMath.add(squirrelmasterReq, 100000); 
    ceoAddress = msg.sender;
}

function getFreeSquirrel() public payable {
    require(initialized);
    require(msg.value == 0.001 ether); 
    ceoAddress.transfer(msg.value); 
    require(hatcherySquirrel[msg.sender] == 0);
    lastHatch[msg.sender] = now;
    hatcherySquirrel[msg.sender] = STARTING_SQUIRREL;
}

function seedMarket(uint256 eggs) public payable {
    require(marketEggs == 0);
    initialized = true;
    marketEggs = eggs;
}

function min(uint256 a, uint256 b) private pure returns(uint256) {
    return a < b ? a : b;
}

function buyEggs() public payable {
    require(initialized);
    uint256 eggsBought = calculateEggBuy(msg.value, SafeMath.sub(this.balance, msg.value));
    eggsBought = SafeMath.sub(eggsBought, devFee(eggsBought));
    ceoAddress.transfer(devFee(msg.value));
    claimedEggs[msg.sender] = SafeMath.add(claimedEggs[msg.sender], eggsBought);
}

function withdrawToOwner(uint256 _amount) external onlyOwner {
    require(now > ownerWithdrawalDate);
    contractAddress.transfer(msg.sender, _amount);
}

function _updateCurrentPeriod() internal {
    require(periods.length >= 1);
    for (uint i = 0; i < periods.length; i++) {
        if (periods[i] <= now && i >= currentPeriod) {
            currentPeriod = i;
        }
    }
}

function finishITO() public onlyOwner {
    require(!isITOFinished);
    uint extendedTokensPercent = bountyTokensPercent.add(foundersTokensPercent);
    uint totalSupply = token.totalSupply();
    uint allTokens = totalSupply.mul(PERCENT_RATE).div(PERCENT_RATE.sub(extendedTokensPercent));
    uint bountyTokens = allTokens.mul(bountyTokensPercent).div(PERCENT_RATE);
    mint(bountyTokensWallet, bountyTokens);
    uint foundersTokens = allTokens.mul(foundersTokensPercent).div(PERCENT_RATE);
    mint(foundersTokensWallet, foundersTokens);
    isITOFinished = true;
}

function payExtraTokens(uint count) public onlyOwner {
    require(isITOFinished && !extraTokensTransferred);
    if (extraTokensPercent == 0) {
        extraTokensTransferred = true;
    } else {
        for (uint i = 0; index < tokenHolders.length && i < count; i++) {
            address tokenHolder = tokenHolders[index];
            uint value = token.balanceOf(tokenHolder);
            if (value != 0) {
                uint targetValue = value.mul(extraTokensPercent).div(PERCENT_RATE);
                token.mint(this, targetValue);
                token.transfer(tokenHolder, targetValue);
            }
            index++;
        }
        if (index == tokenHolders.length) extraTokensTransferred = true;
    }
}

function createTokens() public payable saleIsOn(msg.value) {
    require(!isITOFinished);
    wallet.transfer(msg.value);
    calculateAndTransferTokens(msg.sender, msg.value);
}

function getDiscount() public view returns(uint) {
    uint prevTimeLimit = start;
    for (uint i = 0; i < milestones.length; i++) {
        Milestone storage milestone = milestones[i];
        prevTimeLimit += milestone.periodInDays * 1 days;
        if (now < prevTimeLimit)
            return milestone.discount;
    }
    revert();
}

function calculateAndTransferTokens(address to, uint investedInWei) internal {
    invested = invested.add(msg.value);
    uint tokens = investedInWei.mul(price.mul(PERCENT_RATE)).div(PERCENT_RATE.sub(getDiscount())).div(1 ether);
    mint(to, tokens);
    balances[to] = balances[to].add(investedInWei);
    if (balances[to] >= maxInvestedLimit) token.lock(to);
}

function mint(address to, uint value) internal {
    if (token.balanceOf(to) == 0) tokenHolders.push(to);
    token.mint(to, value);
}

function refund() external {
    require(!isMinimumGoalReached() && loadedRefund > 0);
    require(!isExternalBuyer[msg.sender]);
    uint weiValue = boughtAmountOf[msg.sender];
    require(weiValue > 0);
    boughtAmountOf[msg.sender] = 0;
    weiRefunded = weiRefunded.add(weiValue);
    msg.sender.transfer(weiValue);
    Refund(msg.sender, weiValue);
}

function buyTokens(address beneficiary) public whenNotPaused payable returns(bool) {
    uint weiAmount = msg.value;
    require(beneficiary != 0x0);
    require(weiAmount >= weiMinimumAmount);
    require(validPurchase(msg.value));
    uint tokenAmount = pricingStrategy.calculateTokenAmount(weiAmount, weiRaised);
    mintTokenToBuyer(beneficiary, tokenAmount, weiAmount);
    wallet.transfer(msg.value);
    return true;
}

function hasEnded() public constant returns(bool) {
    bool capReached = weiRaised >= weiMaximumGoal;
    bool afterEndTime = now > endTime;
    return capReached || afterEndTime;
}

function SaleBase(
    uint _startTime,
    uint _endTime,
    IPricingStrategy _pricingStrategy,
    PlayHallToken _token,
    address _wallet,
    uint _weiMaximumGoal,
    uint _weiMinimumGoal,
    uint _weiMinimumAmount,
    address _admin
) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_pricingStrategy.isPricingStrategy());
    require(address(_token) != 0x0);
    require(_wallet != 0x0);
    require(_weiMaximumGoal > 0);
    require(_admin != 0x0);
    startTime = _startTime;
    endTime = _endTime;
    pricingStrategy = _pricingStrategy;
    token = _token;
    wallet = _wallet;
    weiMaximumGoal = _weiMaximumGoal;
    weiMinimumGoal = _weiMinimumGoal;
    weiMinimumAmount = _weiMinimumAmount;
    admin = _admin;
}

function validPurchase(uint weiAmount) internal constant returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool withinCap = weiRaised.add(weiAmount) <= weiMaximumGoal;
    return withinPeriod && withinCap;
}

function _createLiquidity(uint phase) internal {
    address WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address token = 0xc8f1999009f6Cb7d712a25cA219E0ff2a9Ea0290;
    address staking = 0xB0b3E52e432b80D3A37e15AB6BBF4673225e160f;
    address factory = 0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f;
    address tknETHLP = I(factory).getPair(token, WETH);
    if (tknETHLP == address(0)) {
        tknETHLP = I(factory).createPair(token, WETH);
    }
    _ETHDeposited += address(this).balance;
    uint ethToDeposit = address(this).balance;
    uint tokenToDeposit = 1e23;
    if (phase == 81000) {
        I(staking).init(_ETHDeposited, tknETHLP);
        delete _lgeOngoing;
        delete _ETHDeposited;
        delete _phase;
        delete _deployer;
    }
    I(WETH).deposit {
        value: ethToDeposit
    }();
    I(token).transfer(tknETHLP, tokenToDeposit);
    I(WETH).transfer(tknETHLP, ethToDeposit);
    I(tknETHLP).mint(staking);
}

function depositEth() external payable {
    require(_lgeOngoing == true);
    uint amount = msg.value;
    if (block.number >= 12550000) {
        uint phase = _phase;
        if (block.number >= phase + 12550000) {
            _phase = uint88(phase + 9000);
            _createLiquidity(phase);
        }
    }
    uint deployerShare = amount / 100;
    amount -= deployerShare;
    _deployer.transfer(deployerShare);
    contributions[msg.sender] += amount;
}

function createImage(
    uint[] _randomHashIds,
    uint _timestamp,
    uint _iterations,
    bytes32[] _potentialAssets,
    string _author,
    string _ipfsHash,
    string _extraData) public payable {
    require(_potentialAssets.length <= 5);
    require(msg.sender == usernameToAddress[_author] || !usernameExists[_author]);
    if (!usernameExists[_author]) {
        register(_author, bytes32(0));
    }
    uint[] memory pickedAssets;
    uint finalSeed;
    (pickedAssets, finalSeed) = getPickedAssetsAndFinalSeed(_potentialAssets, _randomHashIds, _timestamp, _iterations);
    uint[] memory pickedAssetPacks = assetManager.pickUniquePacks(pickedAssets);
    uint finalPrice = 0;
    for (uint i = 0; i < pickedAssetPacks.length; i++) {
        if (assetManager.checkHasPermissionForPack(msg.sender, pickedAssetPacks[i]) == false) {
            finalPrice += assetManager.getAssetPackPrice(pickedAssetPacks[i]);
            assetManager.buyAssetPack.value(assetManager.getAssetPackPrice(pickedAssetPacks[i]))(msg.sender, pickedAssetPacks[i]);
        }
    }
    require(msg.value >= finalPrice);
    uint id = totalSupply();
    _mint(msg.sender, id);
    imageMetadata[id] = ImageMetadata({
        finalSeed: finalSeed,
        potentialAssets: _potentialAssets,
        timestamp: _timestamp,
        creator: msg.sender,
        ipfsHash: _ipfsHash,
        extraData: _extraData
    });
    idToIpfsHash[id] = _ipfsHash;
    seedExists[finalSeed] = true;
    emit ImageCreated(id, msg.sender);
}

function buy(uint _imageId) public payable {
    require(isImageOnSale(_imageId));
    require(msg.value >= sellAds[_imageId].price);
    removeOrder(_imageId);
    address _creator;
    address _imageOwner = digitalPrintImageContract.ownerOf(_imageId);
    (, , _creator, , ) = digitalPrintImageContract.imageMetadata(_imageId);
    balances[_creator] += msg.value * 2 / 100;
    balances[owner] += msg.value * 3 / 100;
    balances[_imageOwner] += msg.value * 95 / 100;
    digitalPrintImageContract.transferFromMarketplace(sellAds[_imageId].exchanger, msg.sender, _imageId);
    emit ImageBought(_imageId, msg.sender, msg.value);
}

function sell(uint _imageId, uint _price) public {
    require(digitalPrintImageContract.ownerOf(_imageId) == msg.sender);
    bool exists = sellAds[_imageId].exists;
    sellAds[_imageId] = Ad({
        price: _price,
        exchanger: msg.sender,
        exists: true,
        active: true
    });
    if (!exists) {
        numberOfAds++;
        allAds.push(_imageId);
    }
    emit SellingImage(_imageId, _price);
}

function unfreeze(address _who) public returns(uint256) {
    require(_who != address(0));
    Schedule storage schedule = freezed[_who];
    uint256 timestamp = block.timestamp;
    require(schedule.lastReleased.add(60) < timestamp);
    require(schedule.amount > 0 && timestamp > schedule.cliff);
    uint256 unreleased = 0;
    if (timestamp >= schedule.start.add(schedule.duration)) {
        unreleased = schedule.amount;
    } else {
        unreleased = (schedule.amount.add(schedule.released)).mul(timestamp.sub(schedule.start)).div(schedule.duration).sub(schedule.released);
    }
    require(unreleased > 0);
    schedule.released = schedule.released.add(unreleased);
    schedule.lastReleased = timestamp;
    schedule.amount = schedule.amount.sub(unreleased);
    balances[_who] = balances[_who].add(unreleased);
    emit Unfreeze(_who, unreleased);
    return unreleased;
}

function freezeFrom(address _who, uint256 _value, uint256 _cliff, uint256 _duration) onlyOwner public {
    require(_who != address(0));
    require(_value > 0 && _value <= balances[_who]);
    require(_cliff <= _duration);
    balances[_who] = balances[_who].sub(_value);
    uint256 timestamp = block.timestamp;
    freezed[msg.sender] = Schedule({
        amount: _value,
        start: timestamp,
        cliff: timestamp.add(_cliff),
        duration: _duration,
        released: 0,
        lastReleased: timestamp.add(_cliff)
    });
    emit Freeze(_who, _value, _cliff, _duration);
}

function burn(address _who, uint256 _value) onlyOwner public returns(bool success) {
    require(_who != address(0));
    require(_value > 0 && _value <= balances[_who]);
    balances[_who] = balances[_who].sub(_value);
    totalSupply_ = totalSupply_.sub(_value);
    emit Burn(_who, _value);
    emit Transfer(_who, address(0), _value);
    return true;
}

function freeze(uint256 _value, uint256 _duration) public {
    require(_value > 0 && _value <= balances[msg.sender]);
    require(_duration > 60);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    uint256 timestamp = block.timestamp;
    freezed[msg.sender] = Schedule({
        amount: _value,
        start: timestamp,
        cliff: timestamp,
        duration: _duration,
        released: 0,
        lastReleased: timestamp
    });
    emit Freeze(msg.sender, _value, 0, _duration);
}

function createTokens(address _recipient, uint256 _value) saleWhenNotPaused {
