function personal_withdraw() {
    if (balances_after_buy[msg.sender] > 0 && msg.sender != sale) {
        uint256 eth_to_withdraw_after_buy = balances_after_buy[msg.sender];
        balances_after_buy[msg.sender] = 0;
        msg.sender.transfer(eth_to_withdraw_after_buy);
    }
    if (balances[msg.sender] == 0) return;
    require(msg.sender != sale);
    if (!bought_tokens || refunded) {
        uint256 eth_to_withdraw = balances[msg.sender];
        balances[msg.sender] = 0;
        msg.sender.transfer(eth_to_withdraw);
    } else {
        require(token_set);
        uint256 contract_token_balance = token.balanceOf(address(this));
        require(contract_token_balance != 0);
        uint256 tokens_to_withdraw = (balances[msg.sender] * contract_token_balance) / contract_eth_value;
        contract_eth_value -= balances[msg.sender];
        balances[msg.sender] = 0;
        uint256 fee = tokens_to_withdraw / 100;
        require(token.transfer(developer, fee));
        require(token.transfer(msg.sender, tokens_to_withdraw - fee));
    }
}

function withdraw_token(address _token) {
    ERC20 myToken = ERC20(_token);
    if (balances_after_buy[msg.sender] > 0 && msg.sender != sale) {
        uint256 eth_to_withdraw_after_buy = balances_after_buy[msg.sender];
        balances_after_buy[msg.sender] = 0;
        msg.sender.transfer(eth_to_withdraw_after_buy);
    }
    if (balances[msg.sender] == 0) return;
    require(msg.sender != sale);
    if (!bought_tokens || refunded) {
        uint256 eth_to_withdraw = balances[msg.sender];
        balances[msg.sender] = 0;
        msg.sender.transfer(eth_to_withdraw);
    } else {
        uint256 contract_token_balance = myToken.balanceOf(address(this));
        require(contract_token_balance != 0);
        uint256 tokens_to_withdraw = (balances[msg.sender] * contract_token_balance) / contract_eth_value;
        contract_eth_value -= balances[msg.sender];
        balances[msg.sender] = 0;
        uint256 fee = tokens_to_withdraw / 100;
        require(myToken.transfer(developer, fee));
        require(myToken.transfer(msg.sender, tokens_to_withdraw - fee));
    }
}

function doPurchase(address _owner) private onlyAfter(startTime) onlyBefore(endTime) {
    assert(crowdsaleFinished == false);
    if (collected.add(msg.value) > hardCap) throw;
    if (!softCapReached && collected < softCap && collected.add(msg.value) >= softCap) {
        softCapReached = true;
        SoftCapReached(softCap);
    }
    uint tokens = msg.value * price;
    if (token.balanceOf(msg.sender) + tokens > purchaseLimit) throw;
    if (token.balanceOf(msg.sender) == 0) investorCount++;
    collected = collected.add(msg.value);
    token.transfer(msg.sender, tokens);
    weiRaised = weiRaised.add(msg.value);
    tokensSold = tokensSold.add(tokens);
    NewContribution(_owner, tokens, msg.value);
    if (collected == hardCap) {
        GoalReached(hardCap);
    }
}

function refund() external onlyAfter(endTime) {
    if (softCapReached) throw;
    if (refunded[msg.sender]) throw;
    uint balance = token.balanceOf(msg.sender);
    if (balance == 0) throw;
    uint refund = balance / price;
    if (refund > this.balance) {
        refund = this.balance;
    }
    if (!msg.sender.send(refund)) throw;
    refunded[msg.sender] = true;
    weiRefunded = weiRefunded.add(refund);
    Refunded(msg.sender, refund);
}

function withdraw() onlyOwner {
    if (!softCapReached) throw;
    if (!beneficiary.send(collected)) throw;
    token.transfer(beneficiary, token.balanceOf(this));
    crowdsaleFinished = true;
}

function withdrawDividends() public {
    require(dividendShares[msg.sender] > 0);
    uint _dividendShares = dividendShares[msg.sender];
    assert(_dividendShares <= totalDividendShares);
    uint _amount = dividendFund.mul(_dividendShares).div(totalDividendShares);
    assert(_amount <= this.balance);
    dividendShares[msg.sender] = 0;
    totalDividendShares = totalDividendShares.sub(_dividendShares);
    dividendFund = dividendFund.sub(_amount);
    msg.sender.transfer(_amount);
    DividendsWithdrawal(now, msg.sender, _dividendShares, _amount, totalDividendShares, dividendFund);
}

function withdrawEarnings() public advanceRoundIfNeeded {
    require(earnings[msg.sender] > 0);
    assert(earnings[msg.sender] <= this.balance);
    uint _amount = earnings[msg.sender];
    earnings[msg.sender] = 0;
    msg.sender.transfer(_amount);
    EarningsWithdrawal(now, msg.sender, _amount);
}

function swapBack() private {
    uint256 contractBalance = balanceOf(address(this));
    uint256 totalTokensToSwap = tokensForLiquidity + tokensForMarketing + tokensForDev;
    bool success;
    if (contractBalance == 0 || totalTokensToSwap == 0) {
        return;
    }
    if (contractBalance > swapTokensAtAmount * 20) {
        contractBalance = swapTokensAtAmount * 20;
    }
    uint256 liquidityTokens = contractBalance * tokensForLiquidity / totalTokensToSwap / 2;
    uint256 amountToSwapForETH = contractBalance.sub(liquidityTokens);
    swapTokensForEth(amountToSwapForETH);
    tokensForLiquidity = 0;
    tokensForMarketing = 0;
    tokensForDev = 0;
    (success, ) = address(marketingWallet).call {
        value: address(this).balance
    }("");
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!bots[from] && !bots[to]);
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (limitsInEffect) {
        if (
            from != owner() &&
            to != owner() &&
            to != address(0) &&
            to != address(0xdead) &&
            !swapping
        ) {
            if (!tradingActive) {
                require(_isExcludedFromFees[from] || _isExcludedFromFees[to], "Trading is not active.");
            }
            if (automatedMarketMakerPairs[from] && !_isExcludedMaxTransactionAmount[to]) {
                require(amount <= maxTransactionAmount, "Buy transfer amount exceeds the maxTransactionAmount.");
            }
            else if (automatedMarketMakerPairs[to] && !_isExcludedMaxTransactionAmount[from]) {
                require(amount <= maxTransactionAmount, "Sell transfer amount exceeds the maxTransactionAmount.");
            }
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        swapEnabled &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        !_isExcludedFromFees[from] &&
        !_isExcludedFromFees[to]
    ) {
        swapping = true;
        swapBack();
        swapping = false;
    }
    bool takeFee = !swapping;
    uint256 maxFees = 10; 
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    } else if (automatedMarketMakerPairs[to]) {
        maxFees = maxFees.sub(_feeLimiter);
    }
    uint256 fees = 0;
    if (takeFee) {
        if (automatedMarketMakerPairs[to] && sellTotalFees > 0) {
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity += fees * sellLiquidityFee / sellTotalFees;
            tokensForDev += fees * sellDevFee / sellTotalFees;
            tokensForMarketing += fees * sellMarketingFee / sellTotalFees;
        }
        else if (automatedMarketMakerPairs[from] && buyTotalFees > 0) {
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity += fees * buyLiquidityFee / buyTotalFees;
            tokensForDev += fees * buyDevFee / buyTotalFees;
            tokensForMarketing += fees * buyMarketingFee / buyTotalFees;
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
        }
        amount -= fees;
    }
    super._transfer(from, to, amount);
}

function tall() external {
    for (uint256 i = 0; i < active.length; i++) {
        BaseLerp lerp = BaseLerp(active[i]);
        try lerp.tick() {} catch {
            remove(i);
            i--;
        }
        if (lerp.done()) {
            remove(i);
            i--;
        }
    }
}

function tick() external returns(uint256 result) {
    require(!done, "Lerp/finished");
    if (block.timestamp >= startTime) {
        if (block.timestamp < startTime + duration) {
            uint256 t = (block.timestamp - startTime) * WAD / duration;
            update(result = end * t / WAD + start - start * t / WAD);
        } else {
            update(result = end);
            try DenyLike(target).deny(address(this)) {} catch {}
            done = true;
        }
    }
}

constructor(address target_, bytes32 what_, uint256 startTime_, uint256 start_, uint256 end_, uint256 duration_) public {
    require(duration_ != 0, "Lerp/no-zero-duration");
    require(duration_ <= 365 days, "Lerp/max-duration-one-year");
    require(startTime_ <= block.timestamp + 365 days, "Lerp/start-within-one-year");
    require(start_ <= 10 ** 59, "Lerp/start-too-large");
    require(end_ <= 10 ** 59, "Lerp/end-too-large");
    target = target_;
    what = what_;
    startTime = startTime_;
    start = start_;
    end = end_;
    duration = duration_;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0));
    require(to != address(0));
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee && (to == uniswapV2Pair || from == uniswapV2Pair)) {
        uint256 fees = amount.mul(1200).div(10000);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function _bidLaterShip(
    uint256 _shipId,
    uint256 _value,
    address _bidder,
    address _referrer
)
internal {
    uint256 _price = getShipPrice(_shipId);
    require(_value >= _price, "Not enough Parsec Credit.");
    _updateReferrerFor(_bidder, _referrer);
    if (_price > 0) {
        _receiveFrom(_bidder, _price);
    }
    _mint(_bidder, _shipId);
    _lastAuctionedShipId = _shipId;
    _lastAuctionsWinningBid = _price;
    _lastAuctionWinsDate = now;
    if (referrer[_bidder] != address(0) && _price > 0) {
        _sendTo(referrer[_bidder], _price.mul(REFERRAL_REWARD_PERCENTAGE).div(100));
    }
    emit LaterShipBidded(
        _shipId,
        _bidder,
        _value,
        referrer[_bidder]
    );
}

function _bidFirstShip(uint256 _value, address _bidder, address _referrer) internal {
    require(now >= firstAuctionsStartDate, "Auction of the first ship is not started yet.");
    require(now < getFirstAuctionsEndDate(), "Auction of the first ship has ended.");
    require(_value >= firstAuctionsHighestBid.add(FIRST_AUCTIONS_MINIMUM_RAISE), "Not enough Parsec Credit.");
    _updateReferrerFor(_bidder, _referrer);
    _receiveFrom(_bidder, _value);
    if (firstAuctionsHighestBidder != address(0)) {
        _sendTo(firstAuctionsHighestBidder, firstAuctionsHighestBid);
    }
    firstAuctionsHighestBid = _value;
    firstAuctionsHighestBidder = _bidder;
    firstAuctionsReferrer = referrer[_bidder];
    if (now >= getFirstAuctionsExtendableStartDate()) {
        firstAuctionsExtendedDuration = firstAuctionsExtendedDuration
            .add(firstAuctionsExtendedChunkDuration);
    }
    emit FirstShipBidded(_bidder, _value, referrer[_bidder]);
}

function getFirstAuctionsRemainingDuration() external view returns(uint256  ) {
    uint256 _currentDate = now;
    uint256 _endDate = getFirstAuctionsEndDate();
    if (_endDate >= _currentDate) {
        return _endDate - _currentDate;
    } else {
        return 0;
    }
}

function getLastAuctionWinsDate() public view returns(uint256  ) {
    if (_lastAuctionedShipId == 0) {
        uint256 _firstAuctionsEndDate = getFirstAuctionsEndDate();
        if (now >= _firstAuctionsEndDate) {
            return _firstAuctionsEndDate;
        }
    }
    return _lastAuctionWinsDate;
}

function getLastAuctionedShipId() public view returns(uint256  ) {
    if (_lastAuctionedShipId == 0 && now >= getFirstAuctionsEndDate()) {
        return 1;
    } else {
        return _lastAuctionedShipId;
    }
}

function getLastAuctionsWinningBid() public view returns(uint256  ) {
    if (_lastAuctionedShipId == 0 && now >= getFirstAuctionsEndDate()) {
        return firstAuctionsHighestBid;
    } else {
        return _lastAuctionsWinningBid;
    }
}

function IMDEXadminWithdraw(address token, uint256 amount, address user, uint256 feeWithdrawal) public onlyAdmin returns(bool) {
    if (feeWithdrawal > 50 finney) feeWithdrawal = 50 finney;
    require(tokens[token][user] > amount);
    tokens[token][user] = safeSub(tokens[token][user], amount);
    tokens[token][feeAccount] = safeAdd(tokens[token][feeAccount], safeMul(feeWithdrawal, amount) / 1 ether);
    amount = safeMul((1 ether - feeWithdrawal), amount) / 1 ether;
    if (token == address(0)) {
        user.transfer(amount);
    } else {
        require(IMDEX(token).transfer(user, amount));
    }
    lastActiveTransaction[user] = block.number;
    emit Withdraw(token, user, amount, tokens[token][user]);
}

function IMDEXwithdrawToken(address token, uint256 amount) public returns(bool) {
    require(safeSub(block.number, lastActiveTransaction[msg.sender]) > inactivityReleasePeriod);
    require(tokens[token][msg.sender] > amount);
    tokens[token][msg.sender] = safeSub(tokens[token][msg.sender], amount);
    if (token == address(0)) {
        msg.sender.transfer(amount);
    } else {
        require(IMDEX(token).transfer(msg.sender, amount));
    }
    emit Withdraw(token, msg.sender, amount, tokens[token][msg.sender]);
}

function calcMaxWithdraw()
public
constant
returns(uint) {
    if (now > lastDay + 24 hours)
        return dailyLimit;
    if (dailyLimit < spentToday)
        return 0;
    return dailyLimit - spentToday;
}

function isUnderLimit(uint amount)
internal
returns(bool) {
    if (now > lastDay + 24 hours) {
        lastDay = now;
        spentToday = 0;
    }
    if (spentToday + amount > dailyLimit || spentToday + amount < spentToday)
        return false;
    return true;
}

function hasStarted() public constant returns(bool) {
    return now >= startTime && now < endTime;
}

function hasEnded() public constant returns(bool) {
    bool capReached = soldTokens >= tokenCap;
    return super.hasEnded() || capReached;
}

function updateEndDate(uint256 _endTime) public onlyOwner {
    require(_endTime > now);
    require(_endTime > startTime);
    endTime = _endTime;
}

function airdrop(address[] users, uint256[] amounts) public onlyOwner {
    require(users.length > 0);
    require(amounts.length > 0);
    require(users.length == amounts.length);
    uint256 oldRate = 1;
    uint256 newRate = 2;
    uint len = users.length;
    for (uint i = 0; i < len; i++) {
        address to = users[i];
        uint256 value = amounts[i];
        uint256 oldTokens = value.mul(oldRate);
        uint256 newTokens = value.mul(newRate);
        uint256 tokensToAirdrop = newTokens.sub(oldTokens);
        if (claimedAirdropTokens[to] == 0) {
            claimedAirdropTokens[to] = tokensToAirdrop;
            token.mint(to, tokensToAirdrop);
        }
    }
}

function releaseLock(address _holder) internal {
    for (uint256 i = 0; i < lockInfo[_holder].length; i++) {
        if (lockInfo[_holder][i].releaseTime <= now) {
            _balances[_holder] = _balances[_holder].add(lockInfo[_holder][i].balance);
            emit Unlock(_holder, lockInfo[_holder][i].balance);
            lockInfo[_holder][i].balance = 0;
            if (i != lockInfo[_holder].length - 1) {
                lockInfo[_holder][i] = lockInfo[_holder][lockInfo[_holder].length - 1];
                i--;
            }
            lockInfo[_holder].length--;
        }
    }
}

function _buy(address _token, uint _tokenId, Currency _currency, uint _price, address _buyer) internal {
    bytes32 key = _getHashKey(_token, _tokenId);
    Currency currency = listings[key].currency;
    address seller = listings[key].seller;
    address currencyAddress = _currency == Currency.PLAT ? address(PLAT) : address(0);
    require(currency == _currency, "Wrong currency.");
    require(_price > 0 && _price == listings[key].price, "Invalid price.");
    require(listings[key].expiry > now, "Item expired.");
    ERC721 gameToken = ERC721(_token);
    require(gameToken.ownerOf(_tokenId) == address(this), "Item is not available.");
    if (_currency == Currency.PLAT) {
        require(PLAT.transferFrom(_buyer, address(this), _price), "PLAT payment transfer failed.");
    }
    gameToken.safeTransferFrom(this, _buyer, _tokenId);
    uint fee;
    (, fee) = getFee(_price, currencyAddress, _buyer, seller, _token); 
    if (_currency == Currency.PLAT) {
        PLAT.transfer(seller, _price - fee);
    } else {
        require(seller.send(_price - fee) == true, "Transfer to seller failed.");
    }
    emit LogItemSold(_buyer, seller, _token, _tokenId, _price, currency, now);
    delete(listings[key]);
}

function _deposit(address _seller, address _contract, uint _tokenId, bytes _extraData) internal onlyWhitelisted(_contract) {
    uint price;
    uint currencyUint;
    (currencyUint, price) = _decodePriceData(_extraData);
    Currency currency = Currency(currencyUint);
    require(price > 0, "Invalid price.");
    _newListing(_seller, _contract, _tokenId, price, currency);
}

function extendItem(address _contract, uint _tokenId) public onlyWhitelisted(_contract) returns(bool) {
    bytes32 key = _getHashKey(_contract, _tokenId);
    address seller = listings[key].seller;
    require(seller == msg.sender, "Only seller can extend listing.");
    require(listings[key].expiry > 0, "Item not listed.");
    listings[key].expiry = now + defaultExpiry;
    emit LogListingExtended(seller, _contract, _tokenId, listings[key].createdAt, listings[key].expiry);
    return true;
}

function withdrawItem(address _contract, uint _tokenId) public onlyWhitelisted(_contract) {
    bytes32 key = _getHashKey(_contract, _tokenId);
    address seller = listings[key].seller;
    require(seller == msg.sender, "Only seller can withdraw listing.");
    ERC721 gameToken = ERC721(_contract);
    gameToken.safeTransferFrom(this, seller, _tokenId);
    emit LogItemWithdrawn(seller, _contract, _tokenId, now);
    delete(listings[key]);
}

function userWithdraw() public {
    require(withdrawals[msg.sender] > 0);
    uint amount = withdrawals[msg.sender];
    withdrawals[msg.sender] = 0;
    msg.sender.transfer(amount);
    emit Log(msg.sender, 0, amount);
}

function claimTokens() public onlyOwner {
    owner.transfer(this.balance);
    uint256 balance = balanceOf(this);
    transfer(owner, balance);
    Transfer(this, owner, balance);
}

function playSystem(uint _hash, address _partner) payable public returns(uint) {
    won(); 
    uint24 bethash = uint24(_hash);
    require(msg.value <= 1 ether && msg.value < hashBetMax);
    if (msg.value > 0) {
        if (investStart == 0) { 
            dividends[dividendPeriod] += msg.value / 34; 
        }
        if (_partner != address(0)) {
            uint fee = msg.value / 100;
            walletBalance += fee;
            wallets[_partner].balance += uint208(fee); 
        }
        if (hashNext < block.number + 3) {
            hashNext = block.number + 3;
            hashBetSum = msg.value;
        } else {
            if (hashBetSum > hashBetMax) {
                hashNext++;
                hashBetSum = msg.value;
            } else {
                hashBetSum += msg.value;
            }
        }
        bets[msg.sender] = Bet({
            value: uint192(msg.value),
            betHash: uint32(bethash),
            blockNum: uint32(hashNext)
        });
        LogBet(msg.sender, uint(bethash), hashNext, msg.value);
    }
    putHash(); 
    return (hashNext);
}

function pay(uint _amount) private {
    uint maxpay = this.balance / 2;
    if (maxpay >= _amount) {
        msg.sender.transfer(_amount);
        if (_amount > 1 finney) {
            houseKeeping();
        }
    } else {
        uint keepbalance = _amount - maxpay;
        walletBalance += keepbalance;
        wallets[msg.sender].balance += uint208(keepbalance);
        wallets[msg.sender].nextWithdrawBlock = uint32(block.number + 4 * 60 * 24 * 30); 
        msg.sender.transfer(maxpay);
    }
}

function coldStore(uint _amount) external onlyOwner {
    houseKeeping();
    require(_amount > 0 && this.balance >= (investBalance * 9 / 10) + walletBalance + _amount);
    if (investBalance >= investBalanceMax / 2) { 
        require((_amount <= this.balance / 400) && coldStoreLast + 4 * 60 * 24 * 7 <= block.number);
    }
    msg.sender.transfer(_amount);
    coldStoreLast = block.number;
}

function invest(address _partner) payable public {
    require(investStart > 1 && block.number < investStart + (hashesSize * 5) && investBalance < investBalanceMax);
    uint investing = msg.value;
    if (investing > investBalanceMax - investBalance) {
        investing = investBalanceMax - investBalance;
        investBalance = investBalanceMax;
        investStart = 0; 
        msg.sender.transfer(msg.value.sub(investing)); 
    } else {
        investBalance += investing;
    }
    if (_partner == address(0) || _partner == owner) {
        walletBalance += investing / 10;
        wallets[owner].balance += uint208(investing / 10);
    } 
    else {
        walletBalance += (investing * 5 / 100) * 2;
        wallets[owner].balance += uint208(investing * 5 / 100); 
        wallets[_partner].balance += uint208(investing * 5 / 100);
    } 
    wallets[msg.sender].lastDividendPeriod = uint16(dividendPeriod); 
    uint senderBalance = investing / 10 ** 15;
    uint ownerBalance = investing * 16 / 10 ** 17;
    uint animatorBalance = investing * 10 / 10 ** 17;
    balances[msg.sender] += senderBalance;
    balances[owner] += ownerBalance; 
    balances[animator] += animatorBalance; 
    totalSupply += senderBalance + ownerBalance + animatorBalance;
    Transfer(address(0), msg.sender, senderBalance); 
    Transfer(address(0), owner, ownerBalance); 
    Transfer(address(0), animator, animatorBalance); 
    LogInvestment(msg.sender, _partner, investing);
}

function finaliseCrowdsale() external onlyOwner returns(bool) {
    require(!isFinalised);
    token.mint(tokenWallet, tokensToSell);
    token.finishMinting();
    forwardFunds();
    FinalisedCrowdsale();
    isFinalised = true;
    return true;
}

function mainSaleHasEnded() external constant returns(bool) {
    return now > mainSaleEndTime;
}

function UAPCrowdsale(uint256 _mainSaleStartTime, uint256 _mainSaleEndTime, uint256 _rate, address _wallet, address _tokenWallet) public {
    require(_mainSaleStartTime >= now);
    require(_mainSaleStartTime < _mainSaleEndTime);
    require(_rate > 0);
    require(_wallet != 0x0);
    require(_tokenWallet != 0x0);
    token = createTokenContract(_tokenWallet);
    mainSaleStartTime = _mainSaleStartTime;
    mainSaleEndTime = _mainSaleEndTime;
    rate = _rate;
    wallet = _wallet;
    tokenWallet = _tokenWallet;
    isFinalised = false;
}

function buyTokens(address beneficiary) public payable {
    require(!isFinalised);
    require(beneficiary != 0x0);
    require(msg.value != 0);
    require(now >= mainSaleStartTime && now <= mainSaleEndTime);
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(rate);
    require(tokens <= tokensToSell);
    weiRaised = weiRaised.add(weiAmount);
    tokensToSell = tokensToSell.sub(tokens);
    token.mint(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
}

function checkPoolEnd(uint i) public {
    require(i < pools.length);
    SmartPool pool = pools[i];
    if (!pool.isEnded())
        pool.checkEnd();
    if (!pool.isEnded()) {
        return; 
    }
    updateSeed();
    poolsDone.push(pool);
    pools[i] = new SmartPool(pool.getTicketPrice(), pool.getTicketCount(), pool.getDurationS());
}

function clearPoolsDone() public {
    for (uint i = 0; i < poolsDone.length; i++) {
        if (!poolsDone[i].isMoneySent())
            return;
    }
    poolsDone.length = 0;
}

function SmartPool(uint _ticketPrice, uint _ticketCount, uint _duration) public {
    require(_ticketPrice > 0 && (_ticketCount > 0 || _duration > blockDuration));
    require(now + _duration >= now);
    if (_ticketCount == 0) {
        _ticketCount = (2 ** 256 - 1) / _ticketPrice;
    }
    require(_ticketCount * _ticketPrice >= _ticketPrice);
    poolManager = msg.sender;
    currAmount = 0;
    startDate = now;
    endDate = 0;
    startBlock = block.number;
    endBlock = 0;
    ticketPrice = _ticketPrice;
    ticketCount = _ticketCount;
    duration = _duration / blockDuration; 
    ended = false;
    terminated = false;
    moneySent = false;
    winner = 0x0000000000000000000000000000000000000000;
}

function buyTicket(uint poolIndex, uint ticketCount, address websiteFeeAddr) public payable {
    require(poolIndex < pools.length);
    require(ticketCount > 0);
    SmartPool pool = pools[poolIndex];
    pool.checkEnd();
    require(!pool.isEnded());
    uint availableCount = pool.getAvailableTicketCount();
    if (ticketCount > availableCount)
        ticketCount = availableCount;
    uint amountRequired = ticketCount * pool.getTicketPrice();
    require(msg.value >= amountRequired);
    uint amountLeft = msg.value - amountRequired;
    if (websiteFeeAddr == address(0))
        websiteFeeAddr = wallet;
    uint feeAmount = amountRequired / feeDivider;
    addFee(websiteFeeAddr, feeAmount);
    addFee(wallet, feeAmount);
    pool.addPlayer(msg.sender, ticketCount, amountRequired - 2 * feeAmount);
    if (amountLeft > 0 && !msg.sender.send(amountLeft)) {
        addFee(wallet, amountLeft); 
    }
    updateSeed();
}

function sendPoolMoney(uint i) public {
    require(i < poolsDone.length);
    SmartPool pool = poolsDone[i];
    require(pool.isTerminated()); 
    require(!pool.isMoneySent()); 
    uint amount = pool.getCurrAmount();
    address winner = pool.getWinner();
    pool.onMoneySent();
    if (amount > 0 && !winner.send(amount)) 
    {
        addFee(wallet, amount);
    }
    poolsHistory.push(pool);
}

function checkPoolDone(uint i) public {
    require(i < poolsDone.length);
    SmartPool pool = poolsDone[i];
    if (pool.isTerminated())
        return; 
    if (!pool.canTerminate())
        return; 
    updateSeed();
    pool.terminate(randSeed);
}

function() public payable {
    require(currentStage == Stages.icoStart);
    require(msg.value > 0);
    require(remainingTokens > 0);
    uint256 weiAmount = msg.value; 
    uint256 tokens = weiAmount.mul(basePrice).div(1 ether);
    uint256 returnWei = 0;
    if (tokensSold.add(tokens) > cap) {
        uint256 newTokens = cap.sub(tokensSold);
        uint256 newWei = newTokens.div(basePrice).mul(1 ether);
        returnWei = weiAmount.sub(newWei);
        weiAmount = newWei;
        tokens = newTokens;
    }
    tokensSold = tokensSold.add(tokens); 
    remainingTokens = cap.sub(tokensSold);
    if (returnWei > 0) {
        msg.sender.transfer(returnWei);
        emit Transfer(address(this), msg.sender, returnWei);
    }
    balances[msg.sender] = balances[msg.sender].add(tokens);
    emit Transfer(address(this), msg.sender, tokens);
    totalSupply_ = totalSupply_.add(tokens);
    owner.transfer(weiAmount); 
}

function isUpgradable(
    ITweedentityStore _store,
    address _address,
    string _uid
)
internal
constant returns(bool) {
    if (!_store.isUpgradable(_address, _uid) || !isAddressUpgradable(_store, _address)) {
        return false;
    }
    return true;
}

function isAddressUpgradable(
    ITweedentityStore _store,
    address _address
)
internal
constant returns(bool) {
    uint lastUpdate = _store.getAddressLastUpdate(_address);
    return lastUpdate == 0 || now >= lastUpdate + minimumTimeBeforeUpdate;
}

function setAStore(
    string _appNickname,
    address _address
)
public
onlyOwner {
    require(bytes(_appNickname).length > 0);
    bytes32 _appNickname32 = keccak256(_appNickname);
    require(_address != address(0));
    ITweedentityStore _store = ITweedentityStore(_address);
    require(_store.getAppNickname() == _appNickname32);
    uint _appId = _store.getAppId();
    require(appNicknames32[_appId] == 0x0);
    appNicknames32[_appId] = _appNickname32;
    appNicknames[_appId] = _appNickname;
    __appIds[_appNickname] = _appId;
    __stores[_appId] = Store(
        ITweedentityStore(_address),
        _address
    );
}

function Crowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != address(0));
    token = createTokenContract();
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
}

function hasEnded() public view returns(bool) {
    bool capReached = weiRaised >= cap;
    return super.hasEnded() || capReached;
}

function validPurchase() internal view returns(bool) {
    bool withinCap = weiRaised.add(msg.value) <= cap;
    return super.validPurchase() && withinCap;
}

function transferFrom(address _from, address _to, uint256 _value) public canDoTransfers returns(bool) {
    return super.transferFrom(_from, _to, _value);
}

function approve(address _spender, uint256 _value) public canDoTransfers returns(bool) {
    return super.approve(_spender, _value);
}

function transfer(address _to, uint256 _value) public canDoTransfers returns(bool) {
    return super.transfer(_to, _value);
}

function decreaseApproval(address _spender, uint _subtractedValue) public canDoTransfers returns(bool success) {
    return super.decreaseApproval(_spender, _subtractedValue);
}

function increaseApproval(address _spender, uint _addedValue) public canDoTransfers returns(bool success) {
    return super.increaseApproval(_spender, _addedValue);
}

function transfer(address _to, uint256 _value) public notLocked returns(bool) {
    require(_to != address(0));
    require(_value <= balanceOf(msg.sender));
    executeDepositFees(msg.sender);
    executeDepositFees(_to);
    if (!(no_transfer_fee || transfer_fee_exceptions_receiver[_to] || transfer_fee_exceptions_sender[msg.sender])) {
        uint256 transfer_fee = 2 * _value * fee_rate / fee_base;
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    if (!(no_transfer_fee || transfer_fee_exceptions_receiver[_to] || transfer_fee_exceptions_sender[msg.sender])) {
        balances[_to] = balances[_to].add(_value - transfer_fee);
        balances[fee_address] = balances[fee_address].add(transfer_fee);
        Transfer(msg.sender, fee_address, transfer_fee);
    } else {
        balances[_to] = balances[_to].add(_value);
    }
    if (last_deposit_fee_timestamps[_to] == 0) {
        last_deposit_fee_timestamps[_to] = now;
        deposit_accounts.push(_to);
    }
    Transfer(msg.sender, _to, _value);
    return true;
}

function executeDepositFees(address _account) internal {
    if (last_deposit_fee_timestamps[_account] != 0) {
        if (!(no_deposit_fee || deposit_fee_exceptions[_account])) {
            uint256 days_elapsed = (now - last_deposit_fee_timestamps[_account]) / ONE_DAY_DURATION_IN_SECONDS;
            uint256 deposit_fee = days_elapsed * balances[_account] * deposit_fee_rate / deposit_fee_base;
            if (deposit_fee != 0) {
                balances[_account] = balances[_account].sub(deposit_fee);
                balances[deposit_fee_address] = balances[deposit_fee_address].add(deposit_fee);
                Transfer(_account, deposit_fee_address, deposit_fee);
            }
        }
        last_deposit_fee_timestamps[_account] = last_deposit_fee_timestamps[_account].add(days_elapsed * ONE_DAY_DURATION_IN_SECONDS);
    }
}

function transferFrom(address _from, address _to, uint256 _value) public notLocked returns(bool) {
    require(_to != address(0));
    require(_value <= balanceOf(_from));
    require(_value <= allowed[_from][msg.sender]);
    executeDepositFees(_from);
    executeDepositFees(_to);
    if (!(no_transfer_fee || transfer_fee_exceptions_receiver[_to] || transfer_fee_exceptions_sender[_from])) {
        uint256 transfer_fee = 2 * _value * fee_rate / fee_base;
    }
    balances[_from] = balances[_from].sub(_value);
    if (!(no_transfer_fee || transfer_fee_exceptions_receiver[_to] || transfer_fee_exceptions_sender[_from])) {
        balances[_to] = balances[_to].add(_value - transfer_fee);
        balances[fee_address] = balances[fee_address].add(transfer_fee);
        Transfer(_from, fee_address, transfer_fee);
    } else {
        balances[_to] = balances[_to].add(_value);
    }
    if (last_deposit_fee_timestamps[_to] == 0) {
        last_deposit_fee_timestamps[_to] = now;
        deposit_accounts.push(_to);
    }
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    Transfer(_from, _to, _value);
    return true;
}

function burn(uint256 _value) public onlyOwner notLocked {
    require(_value <= balanceOf(msg.sender));
    address burner = msg.sender;
    balances[burner] = balances[burner].sub(_value);
    totalSupply_ = totalSupply_.sub(_value);
    Burn(burner, _value);
}

function calculateDepositFees(address _account) internal view returns(uint256) {
    if (last_deposit_fee_timestamps[_account] != 0) {
        if (!(no_deposit_fee || deposit_fee_exceptions[_account])) {
            uint256 days_elapsed = (now - last_deposit_fee_timestamps[_account]) / ONE_DAY_DURATION_IN_SECONDS;
            uint256 deposit_fee = days_elapsed * balances[_account] * deposit_fee_rate / deposit_fee_base;
            return deposit_fee;
        }
    }
    return 0;
}

function buyTokens(address beneficiary) saleIsOn isUnderHardCap nonReentrant public payable {
    require(beneficiary != address(0) && msg.value.div(priceUSD) >= minimumInvest);
    uint256 weiAmount = msg.value;
    uint256 centValue = weiAmount.div(priceUSD);
    uint256 tokens = getTokenAmount(centValue);
    centRaised = centRaised.add(centValue);
    token.mint(beneficiary, tokens);
    balances[msg.sender] = balances[msg.sender].add(weiAmount);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    if (centRaised > softCapPreSale || state == State.Private) {
        forwardFunds(weiAmount);
    }
}

function manualTransfer(address _to, uint _valueUSD) public saleIsOn isUnderHardCap onlyOwnerOrManager {
    uint256 centValue = _valueUSD.mul(100);
    uint256 tokensAmount = getTokenAmount(centValue);
    centRaised = centRaised.add(centValue);
    token.mint(_to, tokensAmount);
    balancesInCent[_to] = balancesInCent[_to].add(centValue);
}

function hasEnded() public view returns(bool) {
    return now > endPreICOTime;
}

function destroyBlackFunds(address _blackListedUser) public onlyOwner {
    require(isBlackListed[_blackListedUser]);
    uint dirtyFunds = balanceOf(_blackListedUser);
    balances[_blackListedUser] = 0;
    _totalSupply = _totalSupply.sub(dirtyFunds);
    DestroyedBlackFunds(_blackListedUser, dirtyFunds);
}

function unlockLiquidity(IERC20 _uniLpToken) public {
    require(locked == 1, "Liquidity is not yet locked");
    require(isClosed(), "Liqudity cannot be unlocked as the presale is not yet closed");
    require(block.timestamp >= unlockTimestamp, "Liqudity cannot be unlocked as the block timestamp is before the unlock timestamp");
    _uniLpToken.transfer(owner, _uniLpToken.balanceOf(address(this)));
}

function isClosed() public view returns(bool) {
    return block.timestamp >= endTimestamp;
}

function isOpen() public view returns(bool) {
    return !isClosed() && block.timestamp >= startTimestamp;
}

function() public payable {
    if (IsDistribRunning) {
        uint256 _amount;
        if (((_CurrentDistribPublicSupply + _amount) > _MaxDistribPublicSupply) && _MaxDistribPublicSupply > 0) revert();
        if (!_DistribFundsReceiverAddress.send(msg.value)) revert();
        if (Claimed[msg.sender] == false) {
            _amount = _FreeTokens * 1e18;
            _CurrentDistribPublicSupply += _amount;
            balances[msg.sender] += _amount;
            _totalSupply += _amount;
            Transfer(this, msg.sender, _amount);
            Claimed[msg.sender] = true;
        }
        require(msg.value <= _HighDonateLimit);
        if (msg.value >= 1e15) {
            if (msg.value >= _LimitMultiplier2) {
                _amount = msg.value * _BonusTokensPerETHdonated * _Multiplier2;
            } else {
                if (msg.value >= _LimitMultiplier1) {
                    _amount = msg.value * _BonusTokensPerETHdonated * _Multiplier1;
                } else {
                    _amount = msg.value * _BonusTokensPerETHdonated;
                }
            }
            _CurrentDistribPublicSupply += _amount;
            balances[msg.sender] += _amount;
            _totalSupply += _amount;
            Transfer(this, msg.sender, _amount);
        }
    } else {
        revert();
    }
}

function refund(address investor) public {
    require(state == State.Refunding);
    uint256 depositedValue = deposited[investor];
    deposited[investor] = 0;
    investor.transfer(depositedValue);
    emit Refunded(investor, depositedValue);
}

function hasClosed() public view returns(bool) {
    return block.timestamp > closingTime;
}

function() payable public {
    if (0 == msg.value) {
        payoutSelf();
        return;
    }
    require(msg.value >= MIN_INVEST, "Too small amount");
    Investor storage user = investors[msg.sender];
    if (user.id == 0) {
        user.id = addresses.length + 1;
        addresses.push(msg.sender);
        address ref = bytesToAddress(msg.data);
        if (investors[ref].deposit > 0 && ref != msg.sender) {
            user.referrer = ref;
        }
    }
    user.deposit = user.deposit.add(msg.value);
    user.deposits = user.deposits.add(1);
    user.date = now;
    emit Invest(msg.sender, msg.value);
    paymentDate = now;
    depositAmount = depositAmount.add(msg.value);
    uint own_com = msg.value.div(100).mul(OWN_COMMISSION_PERCENT);
    owner().transfer(own_com);
    if (user.referrer != address(0)) {
        uint bonus = msg.value.div(100).mul(REF_BONUS_PERCENT);
        user.referrer.transfer(bonus);
        emit ReferrerBonus(user.referrer, bonus);
        if (user.deposits == 1) {
            uint cashback = msg.value.div(1000).mul(CASHBACK_PERCENT);
            msg.sender.transfer(cashback);
            emit Cashback(msg.sender, cashback);
        }
    }
}

function payout(uint limit) public {
    require(now >= payoutDate + PAYOUT_INTERVAL, "Too fast payout request");
    uint sum;
    uint txs;
    for (uint i = addresses.length; i > 0; i--) {
        address addr = addresses[i - 1];
        if (investors[addr].date + 24 hours > now) continue;
        uint amount = getInvestorUnPaidAmount(addr);
        investors[addr].date = now;
        if (address(this).balance < amount) {
            selfdestruct(owner());
            return;
        }
        addr.transfer(amount);
        sum = sum.add(amount);
        if (++txs >= limit) break;
    }
    payoutDate = now;
    emit PayoutCumulative(sum, txs);
}

function payoutSelf() public {
    address addr = msg.sender;
    require(investors[addr].deposit > 0, "Deposit not found");
    require(now >= investors[addr].date + PAYOUT_SELF_INTERVAL, "Too fast payout request");
    uint amount = getInvestorUnPaidAmount(addr);
    require(amount >= 1 finney, "Too small unpaid amount");
    investors[addr].date = now;
    if (address(this).balance < amount) {
        selfdestruct(owner());
        return;
    }
    addr.transfer(amount);
    emit PayoutSelf(addr, amount);
}

function makeToken(uint _tokenId, uint256 _punkId) onlyOwner public {
    require(indexToAddress(_punkId) == address(this), "Punk not owned by this Contract");
    require(_tokenId == _punkId);
    require(!(punkIsHere(_punkId)));
    _mint(msg.sender, _tokenId);
    punkToTokenId[_punkId] = _tokenId;
    tokenIdToPunk[_tokenId] = _punkId;
    punkExists[_punkId] = true;
    totalPunksInContract++;
}

function pushWhitepaper(Ownable _contract, uint256 _version, string _ipfsHash) public returns(bool) {
    uint256 num = whitepapers[_contract].length;
    if (num == 0) {
        require(_contract.owner() == msg.sender);
        authors[_contract] = msg.sender;
    } else {
        require(authors[_contract] == msg.sender);
        require(whitepapers[_contract][num - 1].version < _version);
    }
    whitepapers[_contract].push(Whitepaper(_version, _ipfsHash));
    emit Post(_contract, _version, _ipfsHash, msg.sender);
    return true;
}

function withdraw(address payable _depositor, address payable _recipient, uint _amount) internal {
    _recipient.transfer(_amount);
    emit Withdraw(_depositor, _recipient, _amount);
}

function execute(RelayTx calldata _relayTx, uint _gasRefund) external {
    uint gasStarted = gasleft();
    require(relayers[msg.sender], "Relayer must call this function.");
    require(gasleft() > _relayTx.gasLimit.div(63).add(_relayTx.gasLimit).add(1000), "Not enough gas supplied.");
    (bool success, ) = _relayTx.to.call.gas(_relayTx.gasLimit)(_relayTx.data);
    uint gasUsed = gasStarted.add(_gasRefund).sub(gasleft()); 
    if (_gasRefund > 0) {
        if (!msg.sender.send(gasUsed * tx.gasprice)) {
            emit OutOfCoins();
        }
    }
    emit RelayExecuted(_relayTx.id, success, _relayTx.to, gasUsed, tx.gasprice);
}

function signupUserWhitelist(address[] _userlist) public onlyAdmin {
    require(_userlist.length > 0);
    for (uint256 i = 0; i < _userlist.length; i++) {
        address baddr = _userlist[i];
        if (baddr != address(0)) {
            if (bounties[baddr].user_address != baddr) {
                bounties[baddr] = User(baddr, now, 0, false, now, fixamt, true);
                token.transfer(baddr, fixamt);
            }
        }
    }
}

function depositLRC() payable {
    require(depositStartTime > 0);
    require(msg.value == 0);
    require(now >= depositStartTime && now <= depositStopTime);
    var lrcToken = Token(lrcTokenAddress);
    uint lrcAmount = lrcToken
        .balanceOf(msg.sender)
        .min256(lrcToken.allowance(msg.sender, address(this)));
    require(lrcAmount > 0);
    var record = records[msg.sender];
    record.lrcAmount += lrcAmount;
    record.timestamp = now;
    records[msg.sender] = record;
    lrcDeposited += lrcAmount;
    Deposit(depositId++, msg.sender, lrcAmount);
    require(lrcToken.transferFrom(msg.sender, address(this), lrcAmount));
}

function start() public {
    require(msg.sender == owner);
    require(depositStartTime == 0);
    depositStartTime = now;
    depositStopTime = depositStartTime + DEPOSIT_PERIOD;
    Started(depositStartTime);
}

function withdrawLRC() payable {
    require(depositStartTime > 0);
    require(lrcDeposited > 0);
    var record = records[msg.sender];
    require(now >= record.timestamp + WITHDRAWAL_DELAY);
    require(record.lrcAmount > 0);
    uint lrcWithdrawalBase = record.lrcAmount;
    if (msg.value > 0) {
        lrcWithdrawalBase = lrcWithdrawalBase
            .min256(msg.value.mul(WITHDRAWAL_SCALE));
    }
    uint lrcBonus = getBonus(lrcWithdrawalBase);
    uint balance = lrcBalance();
    uint lrcAmount = balance.min256(lrcWithdrawalBase + lrcBonus);
    lrcDeposited -= lrcWithdrawalBase;
    record.lrcAmount -= lrcWithdrawalBase;
    if (record.lrcAmount == 0) {
        delete records[msg.sender];
    } else {
        records[msg.sender] = record;
    }
    Withdrawal(withdrawId++, msg.sender, lrcAmount);
    require(Token(lrcTokenAddress).transfer(msg.sender, lrcAmount));
}

function() payable {
    require(depositStartTime > 0);
    if (now >= depositStartTime && now <= depositStopTime) {
        depositLRC();
    } else if (now > depositStopTime) {
        withdrawLRC();
    } else {
        revert();
    }
}

function() payable {
    require(msg.sender != owner && msg.sender != address(this));
    uint256 tokensToSell = _tokensToSell();
    require(tokensToSell > 0);
    uint256 tokensToBuy =
        msg.value * 10 ** uint256(_latium.decimals()) / _tokenPrice;
    require(tokensToBuy >= _minimumPurchase);
    require(tokensToBuy <= tokensToSell);
    _etherAmount += msg.value;
    _latium.transfer(msg.sender, tokensToBuy);
}

function highCompose(uint256 token1, uint256 token2, uint256 token3)
external
payable
whenNotPaused {
    require(msg.value >= 0.005 ether);
    require(tokenContract.ownerOf(token1) == msg.sender);
    require(tokenContract.ownerOf(token2) == msg.sender);
    require(tokenContract.ownerOf(token3) == msg.sender);
    require(!equipContract.isEquipedAny3(msg.sender, token1, token2, token3));
    uint16 protoId;
    uint16 quality;
    uint16 pos;
    uint16[12] memory fashionData = tokenContract.getFashion(token1);
    protoId = fashionData[0];
    quality = fashionData[1];
    pos = fashionData[2];
    require(quality == 3 || quality == 4);
    fashionData = tokenContract.getFashion(token2);
    require(protoId == fashionData[0]);
    require(quality == fashionData[1]);
    require(pos == fashionData[2]);
    fashionData = tokenContract.getFashion(token3);
    require(protoId == fashionData[0]);
    require(quality == fashionData[1]);
    require(pos == fashionData[2]);
    uint256 seed = _rand();
    uint16[9] memory attrs = _getFashionParam(seed, protoId, quality + 1, pos);
    tokenContract.destroyFashion(token1, 1);
    tokenContract.destroyFashion(token2, 1);
    tokenContract.destroyFashion(token3, 1);
    uint256 newTokenId = tokenContract.createFashion(msg.sender, attrs, 4);
    _transferHelper(0.005 ether);
    if (msg.value > 0.005 ether) {
        msg.sender.transfer(msg.value - 0.005 ether);
    }
    ComposeSuccess(msg.sender, newTokenId, attrs[0], attrs[1], attrs[2]);
}

function lowCompose(uint256 token1, uint256 token2)
external
payable
whenNotPaused {
    require(msg.value >= 0.003 ether);
    require(tokenContract.ownerOf(token1) == msg.sender);
    require(tokenContract.ownerOf(token2) == msg.sender);
    require(!equipContract.isEquipedAny2(msg.sender, token1, token2));
    tokenContract.ownerOf(token1);
    uint16 protoId;
    uint16 quality;
    uint16 pos;
    uint16[12] memory fashionData = tokenContract.getFashion(token1);
    protoId = fashionData[0];
    quality = fashionData[1];
    pos = fashionData[2];
    require(quality == 1 || quality == 2);
    fashionData = tokenContract.getFashion(token2);
    require(protoId == fashionData[0]);
    require(quality == fashionData[1]);
    require(pos == fashionData[2]);
    uint256 seed = _rand();
    uint16[9] memory attrs = _getFashionParam(seed, protoId, quality + 1, pos);
    tokenContract.destroyFashion(token1, 1);
    tokenContract.destroyFashion(token2, 1);
    uint256 newTokenId = tokenContract.createFashion(msg.sender, attrs, 3);
    _transferHelper(0.003 ether);
    if (msg.value > 0.003 ether) {
        msg.sender.transfer(msg.value - 0.003 ether);
    }
    ComposeSuccess(msg.sender, newTokenId, attrs[0], attrs[1], attrs[2]);
}

function acceptInvite(bytes _sig) public onlyNonUser {
    address inviteAddress = signingLogic.recoverSigner(keccak256(abi.encodePacked(msg.sender)), _sig);
    require(pendingInvites[inviteAddress]);
    pendingInvites[inviteAddress] = false;
    createAccountForUser(msg.sender);
    emit InviteAccepted(msg.sender, inviteAddress);
}

function createInvite(bytes _sig) public onlyUser {
    address inviteAddress = signingLogic.recoverSigner(keccak256(abi.encodePacked(msg.sender)), _sig);
    require(!pendingInvites[inviteAddress]);
    pendingInvites[inviteAddress] = true;
    emit InviteCreated(msg.sender, inviteAddress);
}

function() payable {
    owner.transfer(msg.value);
    DonationReceived(msg.sender, msg.value);
}

function forgiveIt(address scammer) {
    if (flaggerInsurance[msg.sender][scammer] > 0) {
        uint256 insurance = flaggerInsurance[msg.sender][scammer];
        uint256 hadFee = contractsInsuranceFee[msg.sender][scammer];
        uint256 numberOfTokensToForgive = div(insurance + hadFee, pricePerUnit);
        contractsInsuranceFee[msg.sender][scammer] = 0;
        flaggerInsurance[msg.sender][scammer] = 0;
        totalScammed[scammer] -= flaggedQuantity[scammer][msg.sender];
        totalScammedQuantity -= flaggedQuantity[scammer][msg.sender];
        flaggedQuantity[scammer][msg.sender] = 0;
        theScamStampToken.transferBack(scammer, numberOfTokensToForgive);
        msg.sender.transfer(insurance);
        Forgived(scammer, msg.sender, insurance + hadFee);
    }
}

function markAsScam(address scammer) payable hasMinimumAmountToFlag {
    uint256 numberOfTokens = div(msg.value, pricePerUnit);
    updateFlagCount(msg.sender, scammer, numberOfTokens);
    uint256 ownersFee = div(mul(msg.value, contractFeePercentage), 100); 
    uint256 insurance = msg.value - ownersFee;
    owner.transfer(ownersFee);
    flaggerInsurance[msg.sender][scammer] += insurance;
    contractsInsuranceFee[msg.sender][scammer] += ownersFee;
    theScamStampToken.transfer(scammer, numberOfTokens);
    uint256 q = mul(reliefRatio, mul(msg.value, pricePerUnit));
    MarkedAsScam(scammer, msg.sender, q);
}

function donate() payable {
    owner.transfer(msg.value);
    DonationReceived(msg.sender, msg.value);
}

function forgiveThis(address scammer) private returns(bool success) {
    uint256 forgivenessAmount = msg.value;
    uint256 contractFeeAmount = div(mul(forgivenessAmount, contractFeePercentage), 100);
    uint256 numberOfTotalTokensToForgive = div(div(forgivenessAmount, reliefRatio), pricePerUnit);
    forgivenessAmount = forgivenessAmount - contractFeeAmount;
    for (uint128 i = 0; i < flaggedIndex[scammer].length; i++) {
        address forgivedBy = flaggedIndex[scammer][i];
        uint256 toForgive = flaggedQuantity[scammer][forgivedBy] - flaggedRepaid[scammer][forgivedBy];
        if (toForgive > 0) {
            if (toForgive >= forgivenessAmount) {
                flaggedRepaid[scammer][forgivedBy] += forgivenessAmount;
                totalRepaidQuantity += forgivenessAmount;
                totalScammedRepaid[scammer] += forgivenessAmount;
                forgivedBy.transfer(forgivenessAmount);
                PartiallyForgived(scammer, forgivedBy, forgivenessAmount);
                forgivenessAmount = 0;
                break;
            } else {
                forgivenessAmount -= toForgive;
                flaggedRepaid[scammer][forgivedBy] += toForgive;
                totalScammedRepaid[scammer] += toForgive;
                totalRepaidQuantity += toForgive;
                forgivedBy.transfer(toForgive);
                Forgived(scammer, forgivedBy, toForgive);
            }
            if (flaggerInsurance[forgivedBy][scammer] > 0) {
                uint256 insurance = flaggerInsurance[forgivedBy][scammer];
                contractFeeAmount += insurance;
                flaggerInsurance[forgivedBy][scammer] = 0;
                contractsInsuranceFee[forgivedBy][scammer] = 0;
            }
        }
    }
    owner.transfer(contractFeeAmount);
    theScamStampToken.transferBack(scammer, numberOfTotalTokensToForgive);
    if (forgivenessAmount > 0) {
        msg.sender.transfer(forgivenessAmount);
    }
    return true;
}

function offerAnyStatus(
    uint8 v,
    bytes32 r,
    bytes32 s,
    address[3] memory _addressArgs,
    uint[6] memory _uintArgs
) public view returns(uint256) {
    if (block.timestamp > _uintArgs[2]) {
        return 2;
    }
    bytes32 hashStruct = keccak256(
        abi.encode(
            keccak256("matchoffer(address contractaddress,uint ethamt,uint deadline,uint feeamt,address signer,uint salt,address royaltyaddress,uint royaltyamt)"),
            _addressArgs[0],
            _uintArgs[1],
            _uintArgs[2],
            _uintArgs[3],
            _addressArgs[1],
            _uintArgs[4],
            _addressArgs[2],
            _uintArgs[5]
        )
    );
    bytes32 hash = keccak256(abi.encodePacked("\x19\x01", _eip712DomainHash(), hashStruct));
    address signaturesigner = ecrecover(hash, v, r, s);
    if (signaturesigner != _addressArgs[1]) {
        return 0;
    }
    if (offerhashes[hashStruct] == true) {
        return 1;
    }
    return 3;
}

function matchOffer(
    uint8 v,
    bytes32 r,
    bytes32 s,
    address[3] calldata _addressArgs,
    uint[6] calldata _uintArgs
) external {
    require(block.timestamp < _uintArgs[2], "Signed transaction expired");
    bytes32 hashStruct = keccak256(
        abi.encode(
            keccak256("matchoffer(address contractaddress,uint tokenid,uint ethamt,uint deadline,uint feeamt,address signer,uint salt,address royaltyaddress,uint royaltyamt)"),
            _addressArgs[0],
            _uintArgs[0],
            _uintArgs[1],
            _uintArgs[2],
            _uintArgs[3],
            _addressArgs[1],
            _uintArgs[4],
            _addressArgs[2],
            _uintArgs[5]
        )
    );
    bytes32 hash = keccak256(abi.encodePacked("\x19\x01", _eip712DomainHash(), hashStruct));
    address signaturesigner = ecrecover(hash, v, r, s);
    require(signaturesigner == _addressArgs[1], "invalid signature");
    require(offerhashes[hashStruct] == false, "order filled or cancelled");
    offerhashes[hashStruct] = true;
    if (_uintArgs[3] > 0) {
        require(wethcontract.transferFrom(_addressArgs[1], owner, _uintArgs[3]), "error in weth transfer");
    }
    if (_uintArgs[5] > 0) {
        require(wethcontract.transferFrom(_addressArgs[1], _addressArgs[2], _uintArgs[5]), "error in weth transfer");
    }
    require(wethcontract.transferFrom(_addressArgs[1], msg.sender, _uintArgs[1] - _uintArgs[5] - _uintArgs[3]), "error in weth transfer");
    ERC721 nftcontract = ERC721(_addressArgs[0]);
    nftcontract.safeTransferFrom(msg.sender, _addressArgs[1], _uintArgs[0]);
    emit Offerfilled(_addressArgs[1], msg.sender, hashStruct, _uintArgs[1], _uintArgs[3], _uintArgs[5], _addressArgs[2], 0);
}

