) external payable {
    require(block.timestamp < _uintArgs[2], "Signed transaction expired");
    bytes32 hashStruct = keccak256(
        abi.encode(
            keccak256("matchorder(address contractaddress,uint tokenid,uint ethamt,uint deadline,uint feeamt,address signer,uint salt,address royaltyaddress,uint royaltyamt)"),
            _addressArgs[0],
            _uintArgs[0],
            _uintArgs[1],
            _uintArgs[2],
            _uintArgs[3],
            _addressArgs[1],
            _uintArgs[4],
            _addressArgs[2],
            _uintArgs[5]
        )
    );
    bytes32 hash = keccak256(abi.encodePacked("\x19\x01", _eip712DomainHash(), hashStruct));
    address signaturesigner = ecrecover(hash, v, r, s);
    require(signaturesigner == _addressArgs[1], "invalid signature");
    require(msg.value == _uintArgs[1], "wrong eth amt");
    require(orderhashes[hashStruct] == false, "order filled or cancelled");
    orderhashes[hashStruct] = true; 
    ERC721 nftcontract = ERC721(_addressArgs[0]);
    nftcontract.safeTransferFrom(_addressArgs[1], msg.sender, _uintArgs[0]); 
    if (_uintArgs[3] > 0) {
        owner.transfer(_uintArgs[3]); 
    }
    if (_uintArgs[5] > 0) { 
        payable(_addressArgs[2]).transfer(_uintArgs[5]); 
    }
    payable(_addressArgs[1]).transfer(msg.value - _uintArgs[3] - _uintArgs[5]); 
    emit Orderfilled(_addressArgs[1], msg.sender, hashStruct, _uintArgs[1], _addressArgs[3], _uintArgs[3], _uintArgs[5], _addressArgs[2]);
}

function finalize() onlyOwner public {
    require(!isFinalized);
    require(hasClosed());
    finalization();
    emit Finalized();
    isFinalized = true;
}

constructor(
    uint256 _openingTime,
    uint256 _closingTime,
    uint256 _rate,
    address _wallet,
    PBCToken _tokenAddress
)
public
Crowdsale(_rate, _wallet, _tokenAddress) {
    require(_openingTime >= block.timestamp);
    require(_closingTime >= _openingTime);
    openingTime = _openingTime;
    closingTime = _closingTime;
}

function transferFrom(
    address sender,
    address recipient,
    uint256 amount
) public override returns(bool) {
    _transfer(sender, recipient, amount);
    _approve(
        sender,
        _msgSender(),
        _allowances[sender][_msgSender()].sub(
            amount,
            "ERC20: transfer amount exceeds allowance"
        )
    );
    return true;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (from != owner() && to != owner()) {
        if (cooldownEnabled) {
            if (
                from != address(this) &&
                to != address(this) &&
                from != address(uniswapV2Router) &&
                to != address(uniswapV2Router)
            ) {
                require(
                    _msgSender() == address(uniswapV2Router) ||
                    _msgSender() == uniswapV2Pair,
                    "ERR: Uniswap only"
                );
            }
        }
        require(amount <= _maxTxAmount);
        require(!bots[from] && !bots[to]);
        if (
            from == uniswapV2Pair &&
            to != address(uniswapV2Router) &&
            !_isExcludedFromFee[to] &&
            cooldownEnabled
        ) {
            require(cooldown[to] < block.timestamp);
            cooldown[to] = block.timestamp + (60 seconds);
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function openTrading() external onlyOwner() {
    require(!tradingOpen, "trading is already open");
    IUniswapV2Router02 _uniswapV2Router =
        IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory())
        .createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(
        address(this),
        balanceOf(address(this)),
        0,
        0,
        owner(),
        block.timestamp
    );
    swapEnabled = true;
    cooldownEnabled = false;
    _maxTxAmount = 5000000000 * 10 ** 9;
    tradingOpen = true;
    IERC20(uniswapV2Pair).approve(
        address(uniswapV2Router),
        type(uint256).max
    );
}

function getMinLockedAmount(address _addr) view public returns(uint256 locked) {
    uint256 i;
    uint256 a;
    uint256 t;
    uint256 lockSum = 0;
    TokenLockState storage lockState = lockingStates[_addr];
    if (lockState.latestReleaseTime < now) {
        return 0;
    }
    for (i = 0; i < lockState.tokenLocks.length; i++) {
        a = lockState.tokenLocks[i].amount;
        t = lockState.tokenLocks[i].time;
        if (t > now) {
            lockSum = lockSum.add(a);
        }
    }
    return lockSum;
}

function addTokenLockDate(address _addr, uint256 _value, uint256 _release_time) onlyOwnerOrAdmin public {
    require(_addr != address(0));
    require(_value > 0);
    require(_release_time > now);
    TokenLockState storage lockState = lockingStates[_addr]; 
    if (_release_time > lockState.latestReleaseTime) {
        lockState.latestReleaseTime = _release_time;
    }
    lockState.tokenLocks.push(TokenLockInfo(_value, _release_time));
    emit AddTokenLockDate(_addr, _release_time, _value);
}

function lockSend(address to, uint amount, address token, uint32 unlockTime) public override beforeUnlockTime(unlockTime) {
    require(amount != 0, "LockSend: LOCKED_AMOUNT_SHOULD_BE_NONZERO");
    bytes32 key = _getLockedSendKey(msg.sender, to, token, unlockTime);
    _safeTransferToMe(token, msg.sender, amount);
    lockSendInfos[key] = lockSendInfos[key].add(amount);
    emit Locksend(msg.sender, to, token, amount, unlockTime);
}

function transfer(address _toAddress, uint _amountOfTokens) onlyBagholders public returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) {
        withdraw();
    }
    uint _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function withdraw() onlyStronghands public {
    address _customerAddress = msg.sender;
    uint _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    owner.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function ClaimTokens() external {
    require(saleEnd > 0 && block.timestamp > saleEnd + 30 days, "Presale tokens are available to withdraw 30 days after presale ends");
    uint256 toClaim = users[msg.sender].tokens;
    require(toClaim > 0, "nothing to be claimed");
    users[msg.sender].tokens = 0;
    require(IERC20(TOKEN).transfer(msg.sender, toClaim), "Error sending tokens");
}

function endSale() external onlyOwner {
    require(saleEnd == 0, "Presale is already ended");
    saleEnd = block.timestamp;
}

function getUnSoldTokens(uint256 amount) external onlyOwner {
    require(block.timestamp > saleEnd, "Wait for Presale to end");
    require(IERC20(TOKEN).transfer(msg.sender, amount), "Error sending tokens");
}

function claimPresale(uint256 claimAmount) external onlyOwner {
    owner.transfer(claimAmount);
    presaleClaimed = presaleClaimed.add(claimAmount);
}

function withdraw(address payable _payee, uint256 _payment) public onlyPrimary {
    require(_payment > 0 && address(this).balance >= _payment, "Insufficient funds in the charity vault");
    _payee.transfer(_payment);
    emit LogDonationWithdrawn(_payment, _payee);
}

function buyTokens(address beneficiary) payable validPurchase {
    assert(checkPeriod());
    uint256 ethAmount = msg.value;
    if (preSaleStarted && !preSaleEnded) {
        priceRate = 2000;
    }
    if (SaleStarted && !SaleEnded) {
        if (now >= startICOTimestamp && now <= step1End) {
            priceRate = step1Price;
        } else if (now > step1End && now <= step2End) {
            priceRate = step2Price;
        } else if (now > step2End && now <= step3End) {
            priceRate = step3Price;
        } else {
            priceRate = minPriceRate;
        }
    }
    uint256 tokenAmount = ethAmount.mul(priceRate);
    tokenAmount = tokenAmount.div(1e10);
    ethRaised = ethRaised.add(ethAmount);
    mint(beneficiary, tokenAmount);
    TokenPurchase(msg.sender, beneficiary, ethAmount, tokenAmount);
    wallet.transfer(msg.value);
    if (preSaleStarted && !preSaleEnded && ethRaised >= ethGoal) {
        preSaleEnded = true;
        preSaleGoalReached = true;
    }
}

function checkPeriod() returns(bool) {
    bool within = false;
    if (now > startPreICOTimestamp && now < endPreICOTimestamp && !preSaleGoalReached) { 
        preSaleStarted = true;
        preSaleEnded = false;
        SaleStarted = false;
        SaleEnded = false;
        within = true;
    } else if (now > startICOTimestamp && now < endICOTimestamp) { 
        SaleStarted = true;
        SaleEnded = false;
        preSaleEnded = true;
        within = true;
    } else if (now > endICOTimestamp) { 
        preSaleEnded = true;
        SaleEnded = true;
    } else if (now < startPreICOTimestamp) { 
        preSaleStarted = false;
        preSaleEnded = false;
        SaleStarted = false;
        SaleEnded = false;
    } else { 
        preSaleStarted = true;
        preSaleEnded = true;
        SaleStarted = false;
        SaleEnded = false;
    }
    return within;
}

function finalize() onlyOwner {
    require(now > endICOTimestamp && SaleEnded && !isFinalized);
    uint256 tokensLeft = (totalSupply * 30) / 70; 
    Bounty(wallet, tokensLeft);
    mint(wallet, tokensLeft);
    isFinalized = true;
}

function isWithinTokenAllocLimit(uint256 _tokens) view internal returns(bool) {
    return (isWithinSaleTimeLimit() && isWithinSaleLimit(_tokens));
}

function validPurchase() internal constant returns(bool) {
    bool withinCap = weiRaised.add(msg.value) <= hardCap;
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    return (withinPeriod && nonZeroPurchase) && withinCap && isWithinSaleTimeLimit();
}

function hasEnded() public constant returns(bool) {
    bool capReached = weiRaised >= hardCap;
    return (endTime != 0 && now > endTime) || capReached;
}

function hasStarted() public constant returns(bool) {
    return (startTime != 0 && now > startTime);
}

function isWithinSaleTimeLimit() internal view returns(bool) {
    return now <= limitDateSale;
}

function finalize() onlyOwner public {
    require(!isFinalized);
    finalization();
    emit BrickFinalized();
    isFinalized = true;
}

function refundMoney(address _address) onlyOwner public {
    uint amount = contributorList[_address].contributionAmount;
    if (amount > 0 && _address.send(amount)) { 
        contributorList[_address].contributionAmount = 0;
        contributorList[_address].tokensIssued = 0;
        contributorList[_address].contributionAmountViewOnly = 0;
        contributorList[_address].tokensIssuedViewOnly = 0;
    }
}

function release(address _contributerAddress) internal {
    if (contributorList[_contributerAddress].tokensIssued > 0) {
        if (token.mint(_contributerAddress, contributorList[_contributerAddress].tokensIssued)) { 
            contributorList[_contributerAddress].tokensIssued = 0;
            contributorList[_contributerAddress].contributionAmount = 0;
        } else { 
            tokenSendFailures.push(_contributerAddress);
        }
    }
}

function splitTokens() internal {
    token.mint(techDevelopmentEthWallet, ((totalTokens * 3).div(100))); 
    tokensIssuedTillNow = tokensIssuedTillNow + ((totalTokens * 3).div(100));
    token.mint(operationsEthWallet, ((totalTokens * 7).div(100))); 
    tokensIssuedTillNow = tokensIssuedTillNow + ((totalTokens * 7).div(100));
}

function buyPhaseTokens(address beneficiary) public payable {
    require(beneficiary != address(0));
    require(validPurchase());
    if (isKYCRequiredToReceiveFunds) {
        require(KycContractInterface(kycAddress).isAddressVerified(msg.sender));
    }
    uint256 weiAmount = msg.value;
    uint256 tokens = computeTokens(weiAmount); 
    require(isWithinTokenAllocLimit(tokens));
    if (int(pvtTokens - tokensIssuedTillNow) > 0) { 
        require(int(tokens) < (int(pvtTokens - tokensIssuedTillNow)));
        buyTokens(tokens, weiAmount, beneficiary);
    } else if (int(preSaleTokens + pvtTokens - tokensIssuedTillNow) > 0) { 
        require(int(tokens) < (int(preSaleTokens + pvtTokens - tokensIssuedTillNow)));
        buyTokens(tokens, weiAmount, beneficiary);
    } else if (int(ico1Tokens + preSaleTokens + pvtTokens - tokensIssuedTillNow) > 0) { 
        require(int(tokens) < (int(ico1Tokens + preSaleTokens + pvtTokens - tokensIssuedTillNow)));
        buyTokens(tokens, weiAmount, beneficiary);
    } else if (int(ico2Tokens + ico1Tokens + preSaleTokens + pvtTokens - (tokensIssuedTillNow)) > 0) { 
        require(int(tokens) < (int(ico2Tokens + ico1Tokens + preSaleTokens + pvtTokens - (tokensIssuedTillNow))));
        buyTokens(tokens, weiAmount, beneficiary);
    } else if (!ico3Ended && (int(tokensForCrowdSale - (tokensIssuedTillNow)) > 0)) { 
        require(int(tokens) < (int(tokensForCrowdSale - (tokensIssuedTillNow))));
        buyTokens(tokens, weiAmount, beneficiary);
    }
}

function deposit() private {
    uint256 amount = arpToken
        .balanceOf(msg.sender)
        .min256(arpToken.allowance(msg.sender, address(this)));
    require(amount > 0);
    Record storage record = records[msg.sender];
    record.amount = record.amount.add(amount);
    record.timestamp = now;
    records[msg.sender] = record;
    arpDeposited = arpDeposited.add(amount);
    uint256 bonus = amount.div(BONUS_SCALE);
    if (bonus > 0) {
        arpToken.safeTransferFrom(owner, msg.sender, bonus);
    }
    arpToken.safeTransferFrom(msg.sender, address(this), amount);
    emit Deposit(depositId++, msg.sender, amount, bonus);
}

function withdraw() private {
    require(arpDeposited > 0);
    Record storage record = records[msg.sender];
    require(record.amount > 0);
    require(now >= record.timestamp.add(WITHDRAWAL_DELAY));
    uint256 amount = record.amount;
    delete records[msg.sender];
    arpDeposited = arpDeposited.sub(amount);
    arpToken.safeTransfer(msg.sender, amount);
    emit Withdrawal(withdrawId++, msg.sender, amount);
}

function drain() public {
    require(msg.sender == owner);
    require(now >= depositStartTime.add(DRAIN_DELAY));
    uint256 balance = arpToken.balanceOf(address(this));
    require(balance > 0);
    arpToken.safeTransfer(owner, balance);
    emit Drained(balance);
}

function() public {
    if (now >= depositStartTime && now < depositStopTime) {
        deposit();
    } else if (now > depositStopTime) {
        withdraw();
    } else {
        revert();
    }
}

function sellVoucher_new(uint256 claimAmount, uint256 maximumSharesToBurn) public {
    (uint256 shares, uint256 _withdrawPoolShare) = _sellVoucher(claimAmount, maximumSharesToBurn);
    uint256 unbondNonce = unbondNonces[msg.sender].add(1);
    DelegatorUnbond memory unbond = DelegatorUnbond({
        shares: _withdrawPoolShare,
        withdrawEpoch: stakeManager.epoch()
    });
    unbonds_new[msg.sender][unbondNonce] = unbond;
    unbondNonces[msg.sender] = unbondNonce;
    _getOrCacheEventsHub().logShareBurnedWithId(validatorId, msg.sender, claimAmount, shares, unbondNonce);
    stakingLogger.logStakeUpdate(validatorId);
}

function migrateOut(address user, uint256 amount) external onlyOwner {
    _withdrawAndTransferReward(user);
    (uint256 totalStaked, uint256 rate) = getTotalStake(user);
    require(totalStaked >= amount, "Migrating too much");
    uint256 precision = _getRatePrecision();
    uint256 shares = amount.mul(precision).div(rate);
    _burn(user, shares);
    stakeManager.updateValidatorState(validatorId, -int256(amount));
    activeAmount = activeAmount.sub(amount);
    stakingLogger.logShareBurned(validatorId, user, amount, shares);
    stakingLogger.logStakeUpdate(validatorId);
    stakingLogger.logDelegatorUnstaked(validatorId, user, amount);
}

function _buyShares(
    uint256 _amount,
    uint256 _minSharesToMint,
    address user
) private onlyWhenUnlocked returns(uint256) {
    require(delegation, "Delegation is disabled");
    uint256 rate = exchangeRate();
    uint256 precision = _getRatePrecision();
    uint256 shares = _amount.mul(precision).div(rate);
    require(shares >= _minSharesToMint, "Too much slippage");
    require(unbonds[user].shares == 0, "Ongoing exit");
    _mint(user, shares);
    _amount = rate.mul(shares).div(precision);
    stakeManager.updateValidatorState(validatorId, int256(_amount));
    activeAmount = activeAmount.add(_amount);
    StakingInfo logger = stakingLogger;
    logger.logShareMinted(validatorId, user, _amount, shares);
    logger.logStakeUpdate(validatorId);
    return _amount;
}

function sellVoucher(uint256 claimAmount, uint256 maximumSharesToBurn) public {
    (uint256 shares, uint256 _withdrawPoolShare) = _sellVoucher(claimAmount, maximumSharesToBurn);
    DelegatorUnbond memory unbond = unbonds[msg.sender];
    unbond.shares = unbond.shares.add(_withdrawPoolShare);
    unbond.withdrawEpoch = stakeManager.epoch();
    unbonds[msg.sender] = unbond;
    StakingInfo logger = stakingLogger;
    logger.logShareBurned(validatorId, msg.sender, claimAmount, shares);
    logger.logStakeUpdate(validatorId);
}

function _sellVoucher(uint256 claimAmount, uint256 maximumSharesToBurn) private returns(uint256, uint256) {
    (uint256 totalStaked, uint256 rate) = getTotalStake(msg.sender);
    require(totalStaked != 0 && totalStaked >= claimAmount, "Too much requested");
    uint256 precision = _getRatePrecision();
    uint256 shares = claimAmount.mul(precision).div(rate);
    require(shares <= maximumSharesToBurn, "too much slippage");
    _withdrawAndTransferReward(msg.sender);
    _burn(msg.sender, shares);
    stakeManager.updateValidatorState(validatorId, -int256(claimAmount));
    activeAmount = activeAmount.sub(claimAmount);
    uint256 _withdrawPoolShare = claimAmount.mul(precision).div(withdrawExchangeRate());
    withdrawPool = withdrawPool.add(claimAmount);
    withdrawShares = withdrawShares.add(_withdrawPoolShare);
    return (shares, _withdrawPoolShare);
}

function slash(
    uint256 validatorStake,
    uint256 delegatedAmount,
    uint256 totalAmountToSlash
) external onlyOwner returns(uint256) {
    uint256 _withdrawPool = withdrawPool;
    uint256 delegationAmount = delegatedAmount.add(_withdrawPool);
    if (delegationAmount == 0) {
        return 0;
    }
    uint256 _amountToSlash = delegationAmount.mul(totalAmountToSlash).div(validatorStake.add(delegationAmount));
    uint256 _amountToSlashWithdrawalPool = _withdrawPool.mul(_amountToSlash).div(delegationAmount);
    uint256 stakeSlashed = _amountToSlash.sub(_amountToSlashWithdrawalPool);
    stakeManager.decreaseValidatorDelegatedAmount(validatorId, stakeSlashed);
    activeAmount = activeAmount.sub(stakeSlashed);
    withdrawPool = withdrawPool.sub(_amountToSlashWithdrawalPool);
    return _amountToSlash;
}

function _withdrawReward(address user) private returns(uint256) {
    uint256 _rewardPerShare = _calculateRewardPerShareWithRewards(
        stakeManager.withdrawDelegatorsReward(validatorId)
    );
    uint256 liquidRewards = _calculateReward(user, _rewardPerShare);
    rewardPerShare = _rewardPerShare;
    initalRewardPerShare[user] = _rewardPerShare;
    return liquidRewards;
}

function migrateIn(address user, uint256 amount) external onlyOwner {
    _withdrawAndTransferReward(user);
    _buyShares(amount, 0, user);
}

function restake() public returns(uint256, uint256) {
    address user = msg.sender;
    uint256 liquidReward = _withdrawReward(user);
    uint256 amountRestaked;
    require(liquidReward >= minAmount, "Too small rewards to restake");
    if (liquidReward != 0) {
        amountRestaked = _buyShares(liquidReward, 0, user);
        if (liquidReward > amountRestaked) {
            require(
                stakeManager.transferFunds(validatorId, liquidReward - amountRestaked, user),
                "Insufficent rewards"
            );
            stakingLogger.logDelegatorClaimRewards(validatorId, user, liquidReward - amountRestaked);
        }
        (uint256 totalStaked, ) = getTotalStake(user);
        stakingLogger.logDelegatorRestaked(validatorId, user, totalStaked);
    }
    return (amountRestaked, liquidReward);
}

function buyVoucher(uint256 _amount, uint256 _minSharesToMint) public returns(uint256 amountToDeposit) {
    _withdrawAndTransferReward(msg.sender);
    amountToDeposit = _buyShares(_amount, _minSharesToMint, msg.sender);
    require(stakeManager.delegationDeposit(validatorId, amountToDeposit, msg.sender), "deposit failed");
    return amountToDeposit;
}

function unstakeClaimTokens() public {
    DelegatorUnbond memory unbond = unbonds[msg.sender];
    uint256 amount = _unstakeClaimTokens(unbond);
    delete unbonds[msg.sender];
    stakingLogger.logDelegatorUnstaked(validatorId, msg.sender, amount);
}

function _transfer(
    address from,
    address to,
    uint256 value
) internal {
    _withdrawAndTransferReward(to);
    _withdrawAndTransferReward(from);
    super._transfer(from, to, value);
}

function unstakeClaimTokens_new(uint256 unbondNonce) public {
    DelegatorUnbond memory unbond = unbonds_new[msg.sender][unbondNonce];
    uint256 amount = _unstakeClaimTokens(unbond);
    delete unbonds_new[msg.sender][unbondNonce];
    _getOrCacheEventsHub().logDelegatorUnstakedWithId(validatorId, msg.sender, amount, unbondNonce);
}

function redeemForBuyoutFailed(uint256 _proposalId, address submitter)
external
override
returns(
    uint256 shardPoolId,
    uint256 shardTokenAmount,
    uint256 wantTokenAmount
) {
    require(msg.sender == market, "UNAUTHORIZED");
    Proposal memory p = proposals[_proposalId];
    require(submitter == p.submitter, "UNAUTHORIZED");
    require(
        p.isFailedConfirmed && !p.isSubmitterWithDraw && !p.passed,
        "WRONG STATE"
    );
    shardPoolId = p.shardPoolId;
    shardTokenAmount = p.shardAmount;
    wantTokenAmount = p.wantTokenAmount;
    proposals[_proposalId].isSubmitterWithDraw = true;
}

function voteResultConfirm(uint256 _shardPoolId)
external
override
returns(
    uint256 proposalId,
    bool result,
    address submitter,
    uint256 shardAmount,
    uint256 wantTokenAmount
) {
    require(msg.sender == market, "UNAUTHORIZED");
    proposalId = proposalIds[_shardPoolId];
    require(
        block.timestamp > proposals[proposalId].voteDeadline,
        "NOT READY"
    );
    uint256 votesRejected =
        proposals[proposalId].voteTotal.sub(
            proposals[proposalId].votesReceived
        );
    uint256 rejectNeed = max.sub(passNeeded);
    if (
        votesRejected <= allVotes[proposalId].mul(rejectNeed).div(max) &&
        !IMarketRegulator(regulator).IsInBlackList(_shardPoolId)
    ) {
        proposals[proposalId].passed = true;
        result = true;
        submitter = proposals[proposalId].submitter;
        shardAmount = proposals[proposalId].shardAmount;
        wantTokenAmount = proposals[proposalId].wantTokenAmount;
    } else {
        proposals[proposalId].passed = false;
        proposals[proposalId].isFailedConfirmed = true;
        result = false;
    }
}

function vote(
    uint256 _shardPoolId,
    bool isAgree,
    address shard,
    address voter
) external override returns(uint256 proposalId, uint256 balance) {
    require(msg.sender == market, "UNAUTHORIZED");
    proposalId = proposalIds[_shardPoolId];
    require(
        block.timestamp <= proposals[proposalId].voteDeadline,
        "EXPIRED"
    );
    uint256 blockHeight = proposals[proposalId].blockHeight;
    balance = IShardToken(shard).getPriorVotes(voter, blockHeight);
    require(balance > 0, "INSUFFICIENT VOTERIGHT");
    require(!voted[proposalId][voter], "AlREADY VOTED");
    voted[proposalId][voter] = true;
    if (isAgree) {
        proposals[proposalId].votesReceived = proposals[proposalId]
            .votesReceived
            .add(balance);
        proposals[proposalId].voteTotal = proposals[proposalId]
            .voteTotal
            .add(balance);
    } else {
        proposals[proposalId].voteTotal = proposals[proposalId]
            .voteTotal
            .add(balance);
    }
}

function transfer(address to, uint256 value) returns(bool) {
    if (safeSub(balances[msg.sender], value) < shouldHadBalance(msg.sender)) throw;
    uint256 senderBalance = balances[msg.sender];
    if (senderBalance >= value && value > 0) {
        senderBalance = safeSub(senderBalance, value);
        balances[msg.sender] = senderBalance;
        balances[to] = safeAdd(balances[to], value);
        Transfer(msg.sender, to, value);
        return true;
    } else {
        throw;
    }
}

function approve(address spender, uint256 value) returns(bool) {
    if (safeSub(balances[msg.sender], value) < shouldHadBalance(msg.sender)) throw;
    allowed[msg.sender][spender] = value;
    Approval(msg.sender, spender, value);
    return true;
}

function shouldHadBalance(address who) constant returns(uint256) {
    if (isPool(who)) return 0;
    address apAddress = getAssetPoolAddress(who);
    uint256 baseAmount = getBaseAmount(who);
    if ((apAddress == address(0)) || (baseAmount == 0)) return 0;
    AssetPool ap = AssetPool(apAddress);
    uint startLockTime = ap.getStartLockTime();
    uint stopLockTime = ap.getStopLockTime();
    if (block.timestamp > stopLockTime) {
        return 0;
    }
    if (ap.getBaseLockPercent() == 0) {
        return 0;
    }
    uint256 baseLockAmount = safeDiv(safeMul(baseAmount, ap.getBaseLockPercent()), 100);
    if (block.timestamp < startLockTime) {
        return baseLockAmount;
    }
    if (ap.getLinearRelease() == 0) {
        if (block.timestamp < stopLockTime) {
            return baseLockAmount;
        } else {
            return 0;
        }
    }
    if (block.timestamp < startLockTime + perMonthSecond) {
        return baseLockAmount;
    }
    uint lockMonth = safeDiv(safeSub(stopLockTime, startLockTime), perMonthSecond);
    if (lockMonth <= 0) {
        if (block.timestamp >= stopLockTime) {
            return 0;
        } else {
            return baseLockAmount;
        }
    }
    uint256 monthUnlockAmount = safeDiv(baseLockAmount, lockMonth);
    uint hadPassMonth = safeDiv(safeSub(block.timestamp, startLockTime), perMonthSecond);
    return safeSub(baseLockAmount, safeMul(hadPassMonth, monthUnlockAmount));
}

function transferFrom(address from, address to, uint256 value) returns(bool) {
    if (balances[from] >= value &&
        allowed[from][msg.sender] >= value &&
        safeAdd(balances[to], value) > balances[to]) {
        balances[to] = safeAdd(balances[to], value);
        balances[from] = safeSub(balances[from], value);
        allowed[from][msg.sender] = safeSub(allowed[from][msg.sender], value);
        Transfer(from, to, value);
        return true;
    } else {
        throw;
    }
}

