function currentMilestone(uint start) public view returns(uint) {
    uint previousDate = start;
    for (uint i = 0; i < milestones.length; i++) {
        if (now >= previousDate && now < previousDate + milestones[i].period * 1 days) {
            return i;
        }
        previousDate = previousDate.add(milestones[i].period * 1 days);
    }
    revert();
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 5 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 15 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 10 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 5000e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

function refund(address _participantAddress) public {
    Swap memory swap = swaps[msg.sender][_participantAddress];
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) < now);
    msg.sender.transfer(swap.balance);
    Reputation(ratingContractAddress).change(_participantAddress, -1);
    clean(msg.sender, _participantAddress);
    Refund();
}

function abort(address _ownerAddress) public {
    require(swaps[_ownerAddress][msg.sender].balance == uint256(0));
    require(participantSigns[_ownerAddress][msg.sender] != uint(0));
    require(participantSigns[_ownerAddress][msg.sender].add(SafeTime) < now);
    Reputation(ratingContractAddress).change(_ownerAddress, -1);
    clean(_ownerAddress, msg.sender);
    Abort();
}

function createSwap(bytes20 _secretHash, address _participantAddress) public payable {
    require(msg.value > 0);
    require(participantSigns[msg.sender][_participantAddress].add(SafeTime) > now);
    require(swaps[msg.sender][_participantAddress].balance == uint256(0));
    swaps[msg.sender][_participantAddress] = Swap(
        bytes32(0),
        _secretHash,
        now,
        msg.value
    );
    CreateSwap(now);
}

function withdraw(bytes32 _secret, address _ownerAddress) public {
    Swap memory swap = swaps[_ownerAddress][msg.sender];
    require(swap.secretHash == ripemd160(_secret));
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) > now);
    Reputation(ratingContractAddress).change(msg.sender, 1);
    msg.sender.transfer(swap.balance);
    swaps[_ownerAddress][msg.sender].balance = 0;
    swaps[_ownerAddress][msg.sender].secret = _secret;
    Withdraw();
}

function close(address _participantAddress) public {
    require(swaps[msg.sender][_participantAddress].balance == 0);
    Reputation(ratingContractAddress).change(msg.sender, 1);
    clean(msg.sender, _participantAddress);
    Close();
}

function findFreeReferrer(address _userAddress) public view returns(address) {
    if (users[_userAddress].referral.length < REFERRALS_LIMIT) {
        return _userAddress;
    }
    address[] memory referrals = new address[](254);
    referrals[0] = users[_userAddress].referral[0];
    referrals[1] = users[_userAddress].referral[1];
    referrals[2] = users[_userAddress].referral[2];
    referrals[3] = users[_userAddress].referral[3];
    referrals[4] = users[_userAddress].referral[4];
    address referrer;
    for (uint256 i = 0; i < 1048576; i++) {
        if (users[referrals[i]].referral.length < REFERRALS_LIMIT) {
            referrer = referrals[i];
            break;
        }
        if (i >= 8191) {
            continue;
        }
        referrals[((i.add(1).mul(5))).add(i.add(0))] = users[referrals[i]].referral[0];
        referrals[((i.add(1).mul(5))).add(i.add(1))] = users[referrals[i]].referral[1];
        referrals[((i.add(1).mul(5))).add(i.add(2))] = users[referrals[i]].referral[2];
        referrals[((i.add(1).mul(5))).add(i.add(3))] = users[referrals[i]].referral[3];
        referrals[((i.add(1).mul(5))).add(i.add(4))] = users[referrals[i]].referral[4];
    }
    require(referrer != address(0), 'Referrer not found');
    return referrer;
}

function transferLevelPayment(address _userUpline, uint256 _levelForIncentive) internal {
    uint256 etherValue = msg.value;
    address uplineAddress = _userUpline;
    uint256 uplineLevel = users[uplineAddress].currentLevel;
    uint256 uplineUserLevelExpiry = users[uplineAddress].levelExpiresAt;
    uint256 uplineUID = users[uplineAddress].id;
    uint256 amountSentAsIncetives = 0;
    uint256 count = 1;
    while (uplineUID > 0 && count <= 7) {
        address payable receiver = payable(uplineAddress);
        if (count == 1) {
            uint256 uplineIncentive = (etherValue.mul(LEVEL_INCENTIVE[_levelForIncentive].directNumerator)).div(percentageDenominator);
            if (now <= uplineUserLevelExpiry && users[uplineAddress].isExist) {
                receiver.transfer(uplineIncentive);
                users[uplineAddress].totalEarningEth = users[uplineAddress].totalEarningEth.add(uplineIncentive);
            } else {
                users[uplineAddress].isExist = false;
                (ownerAddress1).transfer(uplineIncentive.div(2));
                (ownerAddress2).transfer(uplineIncentive.div(2));
            }
            amountSentAsIncetives = amountSentAsIncetives.add(uplineIncentive);
        } else {
            uint256 uplineIncentive = (etherValue.mul(LEVEL_INCENTIVE[_levelForIncentive].inDirectNumerator)).div(percentageDenominator);
            if (now <= uplineUserLevelExpiry && users[uplineAddress].isExist) {
                receiver.transfer(uplineIncentive);
                users[uplineAddress].totalEarningEth = users[uplineAddress].totalEarningEth.add(uplineIncentive);
            } else {
                users[uplineAddress].isExist = false;
                (ownerAddress1).transfer(uplineIncentive.div(2));
                (ownerAddress2).transfer(uplineIncentive.div(2));
            }
            amountSentAsIncetives = amountSentAsIncetives.add(uplineIncentive);
        }
        uint256 uplineReferrerId = users[uplineAddress].referrerID;
        uplineAddress = userAddresses[uplineReferrerId];
        uplineLevel = users[uplineAddress].currentLevel;
        uplineUID = users[uplineAddress].id;
        count++;
    }
    uint256 remAmount = msg.value.sub(amountSentAsIncetives);
    transferToOwner(remAmount);
}

function registerUser(uint256 _referrerUniqueID) public payable userNotRegistered() validReferrerID(_referrerUniqueID) {
    require(msg.value > 0, "ether value is 0");
    uint256 referrerUniqueID = _referrerUniqueID;
    if (users[userAddresses[referrerUniqueID]].referral.length >= REFERRALS_LIMIT) {
        referrerUniqueID = users[findFreeReferrer(userAddresses[referrerUniqueID])].id;
    }
    last_uid = last_uid + 1;
    users[msg.sender] = UserStruct({
        isExist: true,
        id: last_uid,
        referrerID: referrerUniqueID,
        currentLevel: 1,
        totalEarningEth: 0,
        referral: new address[](0),
        levelExpiresAt: now.add(PERIOD_LENGTH)
    });
    userAddresses[last_uid] = msg.sender;
    users[userAddresses[referrerUniqueID]].referral.push(msg.sender);
    uint256 tokenAmount = getTokenAmountByLevel(1);
    require(ETRM.transferFrom(owner, msg.sender, tokenAmount), "token transfer failed");
    address userUpline = userAddresses[referrerUniqueID];
    transferLevelPayment(userUpline, 1);
    emit RegisterUserEvent(msg.sender, userAddresses[referrerUniqueID], now);
}

function buyLevel(uint256 _level) public payable userRegistered() validLevel(_level) {
    require(msg.value > 0, "ether value is 0");
    uint256 userCurrentLevel = users[msg.sender].currentLevel;
    require((_level == userCurrentLevel.add(1)) || (userCurrentLevel == 7 && _level == 7), "Invalid level upgrade value");
    users[msg.sender].levelExpiresAt = now.add(PERIOD_LENGTH);
    users[msg.sender].currentLevel = _level;
    uint256 tokenAmount = getTokenAmountByLevel(_level);
    require(ETRM.transferFrom(owner, msg.sender, tokenAmount), "token transfer failed");
    address userUpline = userAddresses[users[msg.sender].referrerID];
    transferLevelPayment(userUpline, _level);
    emit BuyLevelEvent(msg.sender, _level, now);
}

function open(uint a, uint256 t) external onlyOwner {
    ERC20 token = ERC20(tk); 
    require(token.transferFrom(msg.sender, address(this), a), "transfer failed"); 
    sta = block.timestamp; 
    end = block.timestamp + t; 
    total = a; 
}

function collect() external onlyOwner {
    require(end != 0, "ITCO not opened yet"); 
    require(block.timestamp > end, "ITCO not ended yet"); 
    require(msg.sender.send(address(this).balance), "transfer failed"); 
    ERC20 token = ERC20(tk); 
    uint256 balance = token.balanceOf(address(this)); 
    require(token.transfer(msg.sender, balance), "transfer failed"); 
}

fallback() external payable { 
    require(sta > 0, "IBCO not opened yet"); 
    require(block.timestamp < end, "IBCO has ended"); 
    uint256 price;
    if (totalDeps >= t5) { 
        price = p6; 
    } else if (totalDeps >= t4) { 
        price = p5;
    } else if (totalDeps >= t3) { 
        price = p4;
    } else if (totalDeps >= t2) { 
        price = p3;
    } else if (totalDeps >= t1) { 
        price = p2;
    } else { 
        price = p1;
    }
    require(msg.value > price, "insufficent payment for one token"); 
    uint256 tTS = (msg.value.div(price)); 
    tTS = tTS.mul(base); 
    ERC20 token = ERC20(tk); 
    uint256 balance = token.balanceOf(address(this)); 
    require(balance >= tTS, "insufficent balance left in itco"); 
    totalDeps = totalDeps.add(msg.value); 
    require(token.transfer(msg.sender, tTS), "transfer failed"); 
}

function _registerLockedDeposits(bytes32 _userKey, uint _amount, uint _lockupDate) internal {
    if (_lockupDate <= now) {
        return;
    }
    LockedDeposits storage _lockedDeposits = user2lockedDeposits[_userKey];
    uint _lockedBalance = _lockedDeposits.date2deposit[_lockupDate];
    if (_lockedBalance == 0) {
        uint _lockedDepositsCounter = _lockedDeposits.counter.add(1);
        _lockedDeposits.counter = _lockedDepositsCounter;
        _lockedDeposits.index2Date[_lockedDepositsCounter] = _lockupDate;
    }
    _lockedDeposits.date2deposit[_lockupDate] = _lockedBalance.add(_amount);
}

function _makeWithdrawForPeriod(bytes32 _userKey, uint _value) internal {
    uint _userBalance = getUserBalance(_userKey);
    uint _lockedBalance = _syncLockedDepositsAmount(_userKey);
    require(_userBalance.sub(_lockedBalance) >= _value);
    uint _periodsCount = periodsCount;
    Period storage _transferPeriod = periods[_periodsCount];
    _transferPeriod.user2bmcDays[_userKey] = _getBmcDaysAmountForUser(_userKey, now, _periodsCount);
    uint _totalBmcDeposit = _getTotalBmcDaysAmount(now, _periodsCount);
    _transferPeriod.totalBmcDays = _totalBmcDeposit;
    _transferPeriod.bmcDaysPerDay = _transferPeriod.bmcDaysPerDay.sub(_value);
    uint _updatedTransferCount = _transferPeriod.transfersCount.add(1);
    _transferPeriod.transfer2date[_updatedTransferCount] = now;
    _transferPeriod.user2lastTransferIdx[_userKey] = _updatedTransferCount;
    _transferPeriod.user2balance[_userKey] = _userBalance.sub(_value);
    _transferPeriod.transfersCount = _updatedTransferCount;
}

function distributeBonuses(uint _amount) public onlyDistributionSource returns(uint) {
    ERC20Interface _bonusToken = ERC20Interface(bonusToken);
    if (_bonusToken.allowance(msg.sender, address(this)) < _amount) {
        return _emitError(PROFITEROLE_ERROR_INSUFFICIENT_DISTRIBUTION_BALANCE);
    }
    if (!_bonusToken.transferFrom(msg.sender, wallet, _amount)) {
        return _emitError(PROFITEROLE_ERROR_TRANSFER_ERROR);
    }
    if (firstDepositDate == 0) {
        firstDepositDate = now;
    }
    uint _lastDepositDate = lastDepositDate;
    if (_lastDepositDate != 0) {
        distributionDeposits[_lastDepositDate].nextDepositDate = now;
    }
    lastDepositDate = now;
    distributionDeposits[now] = Deposit(_amount, _amount, 0);
    Treasury(treasury).addDistributionPeriod();
    DepositPendingAdded(_amount, msg.sender, now);
    return OK;
}

function getSharesPercentForPeriod(bytes32 _userKey, uint _date) public view returns(uint) {
    uint _periodIdx = periodDate2periodIdx[_date];
    if (_date != 0 && _periodIdx == 0) {
        return 0;
    }
    if (_date == 0) {
        _date = now;
        _periodIdx = periodsCount;
    }
    uint _bmcDays = _getBmcDaysAmountForUser(_userKey, _date, _periodIdx);
    uint _totalBmcDeposit = _getTotalBmcDaysAmount(_date, _periodIdx);
    return _totalBmcDeposit != 0 ? _bmcDays * PERCENT_PRECISION / _totalBmcDeposit : 0;
}

function _withdrawBonuses(bytes32 _userKey, uint _value) private returns(uint) {
    uint _startDate = _getCalculationStartDate(_userKey);
    uint _lastWithdrawDate = _startDate;
    Treasury _treasury = Treasury(treasury);
    for (
        uint _endDate = lastDepositDate; _startDate <= _endDate && _startDate != 0 && _value > 0; _startDate = distributionDeposits[_startDate].nextDepositDate
    ) {
        uint _balanceToWithdraw = _withdrawBonusesFromDeposit(_userKey, _startDate, _value, _treasury);
        _value = _value.sub(_balanceToWithdraw);
    }
    if (_lastWithdrawDate != _startDate) {
        bonusBalances[_userKey].lastWithdrawDate = _lastWithdrawDate;
    }
    if (_value > 0) {
        revert();
    }
    return OK;
}

function getTotalDepositsAmountLeft() public view returns(uint _amount) {
    uint _lastDepositDate = lastDepositDate;
    for (
        uint _startDate = firstDepositDate; _startDate <= _lastDepositDate || _startDate != 0; _startDate = distributionDeposits[_startDate].nextDepositDate
    ) {
        _amount = _amount.add(distributionDeposits[_startDate].left);
    }
}

function _syncLockedDepositsAmount(bytes32 _userKey) internal returns(uint _lockedSum) {
    LockedDeposits storage _lockedDeposits = user2lockedDeposits[_userKey];
    uint _lockedDepositsCounter = _lockedDeposits.counter;
    for (uint _idx = 1; _idx <= _lockedDepositsCounter; ++_idx) {
        uint _lockDate = _lockedDeposits.index2Date[_idx];
        if (_lockDate <= now) {
            _lockedDeposits.index2Date[_idx] = _lockedDeposits.index2Date[_lockedDepositsCounter];
            delete _lockedDeposits.index2Date[_lockedDepositsCounter];
            delete _lockedDeposits.date2deposit[_lockDate];
            _lockedDepositsCounter = _lockedDepositsCounter.sub(1);
            continue;
        }
        _lockedSum = _lockedSum.add(_lockedDeposits.date2deposit[_lockDate]);
    }
    _lockedDeposits.counter = _lockedDepositsCounter;
}

function _withdrawBonusesFromDeposit(bytes32 _userKey, uint _periodDate, uint _value, Treasury _treasury) private returns(uint) {
    Deposit storage _pendingDeposit = distributionDeposits[_periodDate];
    Balance storage _userBalance = _pendingDeposit.leftToWithdraw[_userKey];
    uint _balanceToWithdraw;
    if (_userBalance.initialized) {
        _balanceToWithdraw = _userBalance.left;
    } else {
        uint _sharesPercent = _treasury.getSharesPercentForPeriod(_userKey, _periodDate);
        _balanceToWithdraw = _pendingDeposit.balance.mul(_sharesPercent).div(PERCENT_PRECISION);
        _userBalance.initialized = true;
    }
    if (_balanceToWithdraw > _value) {
        _userBalance.left = _balanceToWithdraw - _value;
        _balanceToWithdraw = _value;
    } else {
        delete _userBalance.left;
    }
    _pendingDeposit.left = _pendingDeposit.left.sub(_balanceToWithdraw);
    return _balanceToWithdraw;
}

function getTotalBonusesAmountAvailable(bytes32 _userKey) public view returns(uint _sum) {
    uint _startDate = _getCalculationStartDate(_userKey);
    Treasury _treasury = Treasury(treasury);
    for (
        uint _endDate = lastDepositDate; _startDate <= _endDate && _startDate != 0; _startDate = distributionDeposits[_startDate].nextDepositDate
    ) {
        Deposit storage _pendingDeposit = distributionDeposits[_startDate];
        Balance storage _userBalance = _pendingDeposit.leftToWithdraw[_userKey];
        if (_userBalance.initialized) {
            _sum = _sum.add(_userBalance.left);
        } else {
            uint _sharesPercent = _treasury.getSharesPercentForPeriod(_userKey, _startDate);
            _sum = _sum.add(_pendingDeposit.balance.mul(_sharesPercent).div(PERCENT_PRECISION));
        }
    }
}

function getLockedUserDeposits(bytes32 _userKey) public view returns(uint[] _lockupDates, uint[] _deposits) {
    LockedDeposits storage _lockedDeposits = user2lockedDeposits[_userKey];
    uint _lockedDepositsCounter = _lockedDeposits.counter;
    _lockupDates = new uint[](_lockedDepositsCounter);
    _deposits = new uint[](_lockedDepositsCounter);
    uint _pointer = 0;
    for (uint _idx = 1; _idx < _lockedDepositsCounter; ++_idx) {
        uint _lockDate = _lockedDeposits.index2Date[_idx];
        if (_lockDate > now) {
            _lockupDates[_pointer] = _lockDate;
            _deposits[_pointer] = _lockedDeposits.date2deposit[_lockDate];
            ++_pointer;
        }
    }
}

