}

function makeTradeable() public {
    require(msg.sender == owner || now > dateMainEnd + 20 weeks);
    tokensTradeable = true;
}

function pNumberOfLockedTokens(address _account) private view returns(uint locked) {
    uint[LOCK_SLOTS] storage term = lockTerm[_account];
    uint[LOCK_SLOTS] storage amnt = lockAmnt[_account];
    for (uint i; i < LOCK_SLOTS; i++) {
        if (term[i] >= now) locked = locked.add(amnt[i]);
    }
}

function registerLockedTokens(address _account, uint _tokens, uint _term) internal returns(uint idx) {
    require(_term > now, "lock term must be in the future");
    idx = 9999;
    uint[LOCK_SLOTS] storage term = lockTerm[_account];
    uint[LOCK_SLOTS] storage amnt = lockAmnt[_account];
    for (uint i; i < LOCK_SLOTS; i++) {
        if (term[i] < now) {
            term[i] = 0;
            amnt[i] = 0;
            if (idx == 9999) idx = i;
        }
        if (term[i] == _term) idx = i;
    }
    require(idx != 9999, "registerLockedTokens: no available slot found");
    if (term[idx] == 0) term[idx] = _term;
    amnt[idx] = amnt[idx].add(_tokens);
    mayHaveLockedTokens[_account] = true;
    emit RegisteredLockedTokens(_account, idx, _tokens, _term);
}

function isMain() public view returns(bool) {
    if (now > dateMainStart && now < dateMainEnd) return true;
    return false;
}

function setDateMainStart(uint _unixts) public onlyOwner checkDateOrder {
    require(now < _unixts && now < dateMainStart);
    dateMainStart = _unixts;
    emit IcoDateUpdated(1, _unixts);
}

function isAvailableLockSlot(address _account, uint _term) public view returns(bool) {
    if (!mayHaveLockedTokens[_account]) return true;
    if (_term < now) return true;
    uint[LOCK_SLOTS] storage term = lockTerm[_account];
    for (uint i; i < LOCK_SLOTS; i++) {
        if (term[i] < now || term[i] == _term) return true;
    }
    return false;
}

function updateTokensPerEth(uint _tokens_per_eth) public onlyOwner {
    require(now < dateMainStart);
    tokensPerEth = _tokens_per_eth;
    emit UpdatedTokensPerEth(tokensPerEth);
}

function setDateMainEnd(uint _unixts) public onlyOwner checkDateOrder {
    require(now < _unixts && now < dateMainEnd);
    dateMainEnd = _unixts;
    emit IcoDateUpdated(2, _unixts);
}

constructor() public checkDateOrder() {
    require(now < dateMainStart);
}

function pMintTokens(uint _mint_type, address _account, uint _tokens, uint _term) private {
    require(whitelist[_account]);
    require(_account != 0x0);
    require(_tokens > 0);
    require(_tokens <= availableToMint(), "not enough tokens available to mint");
    require(_term == 0 || _term > now, "either without lock term, or lock term must be in the future");
    if (_term > 0) registerLockedTokens(_account, _tokens, _term);
    balances[_account] = balances[_account].add(_tokens);
    balancesMinted[_account] = balancesMinted[_account].add(_tokens);
    balancesMintedByType[_account][_mint_type] = balancesMintedByType[_account][_mint_type].add(_tokens);
    tokensMinted = tokensMinted.add(_tokens);
    tokensIssuedTotal = tokensIssuedTotal.add(_tokens);
    emit Transfer(0x0, _account, _tokens);
    emit TokensMinted(_mint_type, _account, _tokens, _term);
}

function openMigrationPhase() public onlyOwner {
    require(now > dateMainEnd);
    isMigrationPhaseOpen = true;
}

function buyTokens() private {
    require(isMain());
    require(msg.value >= MINIMUM_CONTRIBUTION);
    require(whitelist[msg.sender]);
    uint tokens_available = TOKEN_MAIN_CAP.sub(tokensMain);
    if (isMainFirstDay()) {
        uint tokens_available_first_day = firstDayTokenLimit().sub(balancesMain[msg.sender]);
        if (tokens_available_first_day < tokens_available) {
            tokens_available = tokens_available_first_day;
        }
    }
    require(tokens_available > 0);
    uint tokens_requested = ethToTokens(msg.value);
    uint tokens_issued = tokens_requested;
    uint eth_contributed = msg.value;
    uint eth_returned;
    if (tokens_requested > tokens_available) {
        tokens_issued = tokens_available;
        eth_returned = tokensToEth(tokens_requested.sub(tokens_available));
        eth_contributed = msg.value.sub(eth_returned);
    }
    balances[msg.sender] = balances[msg.sender].add(tokens_issued);
    balancesMain[msg.sender] = balancesMain[msg.sender].add(tokens_issued);
    tokensMain = tokensMain.add(tokens_issued);
    tokensIssuedTotal = tokensIssuedTotal.add(tokens_issued);
    ethContributed[msg.sender] = ethContributed[msg.sender].add(eth_contributed);
    totalEthContributed = totalEthContributed.add(eth_contributed);
    if (eth_returned > 0) msg.sender.transfer(eth_returned);
    wallet.transfer(eth_contributed);
    emit Transfer(0x0, msg.sender, tokens_issued);
    emit RegisterContribution(msg.sender, tokens_issued, eth_contributed, eth_returned);
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 10 ether / 10;
    uint256 bonusCond2 = 10 ether;
    uint256 bonusCond3 = 50 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 0 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 20 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 35 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 20 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 35 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 30e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

function buyStamps() public payable whenNotPaused returns(bool) {
    require(msg.value != 0);
    address _buyer = msg.sender;
    uint256 _weiPaid = msg.value;
    uint256 _stampsBought = _weiPaid.mul(rate);
    owner.transfer(_weiPaid);
    stamp.transfer(_buyer, _stampsBought);
    emit StampsBought(_buyer, _weiPaid, _stampsBought);
    return true;
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function withdraw()
onlyStronghands()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function createTokens() public checkAmount saleIsOn underHardcap payable {
    require(status != 2);
    uint tokens = msg.value.div(rate);
    uint bonusTokens = calcBonusTokens(tokens);
    mintAndTransfer(msg.sender, tokens + bonusTokens);
    balances[msg.sender] = balances[msg.sender].add(msg.value);
    balanceTotal = balanceTotal.add(msg.value);
    if (msg.data.length == 20) {
        address referer = bytesToAddress(bytes(msg.data));
        require(referer != msg.sender && referer != address(0));
        uint refererTokens = tokens.div(20);
        mintAndTransfer(msg.sender, refererTokens);
    }
}

function finishMinting() public onlyOwner saleFinished overSoftcap {
    require(status == 1 || (status != 2 && now < start + period * 1 days && balanceTotal < hardcap));
    uint issuedTokenSupply = token.totalSupply();
    uint restrictedTokens = issuedTokenSupply.mul(restricted).div(100 - restricted);
    mintAndTransfer(owner, restrictedTokens);
    token.finishMinting();
    owner.transfer(this.balance);
}

function refund() public {
    require(status == 2 || (status != 1 && now > start + period * 1 days && balanceTotal < softcap));
    require(balances[msg.sender] > 0);
    uint value = balances[msg.sender];
    balances[msg.sender] = 0;
    msg.sender.transfer(value);
}

function calcBonusTokens(uint tokens) public view returns(uint) {
    uint delta = now - start;
    if (delta <= 7 days) {
        return tokens.div(10);
    } else if (delta <= 21 days) {
        return tokens.div(20);
    }
    return 0;
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf[activityFunds] >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    if (msg.value > 0) activityFunds.transfer(msg.value);
    balanceOf[activityFunds] = balanceOf[activityFunds].sub(distributeAmount);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(distributeAmount);
    Transfer(activityFunds, msg.sender, distributeAmount);
}

function transfer(address _to, uint _value, bytes _data) public returns(bool success) {
    require(_value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]);
    if (isContract(_to)) {
        return transferToContract(_to, _value, _data);
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(_to != address(0) &&
        _value > 0 &&
        balanceOf[_from] >= _value &&
        allowance[_from][msg.sender] >= _value &&
        frozenAccount[_from] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[_from] &&
        now > unlockUnixTime[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    Transfer(_from, _to, _value);
    return true;
}

function distributeAirdrop(address[] addresses, uint[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e8);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e8);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 3 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        msg.sender.transfer(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function transferFrom(
    address _from,
    address _to,
    uint256 _value
) public returns(bool) {
    addressValidator().validateIllegalAddress(_from);
    addressValidator().validateIllegalAddress(_to);
    require(_value != 0, "illegal transfer value");
    IAllocator(config().allocator()).beforeBalanceChange(
        address(this),
        _from,
        _to
    );
    _transfer(_from, _to, _value);
    uint256 allowanceAmount = allowance(_from, msg.sender);
    _approve(
        _from,
        msg.sender,
        allowanceAmount.sub(
            _value,
            "ERC20: transfer amount exceeds allowance"
        )
    );
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    addressValidator().validateIllegalAddress(_to);
    require(_value != 0, "illegal transfer value");
    IAllocator(config().allocator()).beforeBalanceChange(
        address(this),
        msg.sender,
        _to
    );
    _transfer(msg.sender, _to, _value);
    return true;
}

function applyVoteOutVotesFor(address subject, uint256 voteOutStakeAdded, uint256 voteOutStakeRemoved, uint256 totalDelegatedStake, Settings memory _settings) private {
    if (isVotedOut(subject)) {
        return;
    }
    uint256 accumulated = accumulatedStakesForVoteOut[subject].
    sub(voteOutStakeRemoved).
    add(voteOutStakeAdded);
    bool shouldBeVotedOut = totalDelegatedStake > 0 && accumulated.mul(PERCENT_MILLIE_BASE) >= uint256(_settings.voteOutPercentMilleThreshold).mul(totalDelegatedStake);
    if (shouldBeVotedOut) {
        votedOutGuardians[subject] = true;
        emit GuardianVotedOut(subject);
        emit GuardianStatusUpdated(subject, false, false);
        committeeContract.removeMember(subject);
    }
    accumulatedStakesForVoteOut[subject] = accumulated;
}

function depositToken(address token, uint amount) public { 
    if (token == 0) revert();
    if (blackERC20[token]) revert();
    if (!Token(token).transferFrom(msg.sender, this, amount)) revert();
    tokens[token][msg.sender] = safeAdd(tokens[token][msg.sender], amount);
    emit Deposit(token, msg.sender, amount, tokens[token][msg.sender]);
}

function tradeBalances(address tokenGet, uint amountGet, address tokenGive, uint amountGive, address user, uint amount) private {
    uint feeMakeXfer = safeMul(amount, feeMake) / (1 ether);
    uint feeTakeXfer = safeMul(amount, feeTake) / (1 ether);
    uint feeRebateXfer = 0;
    if (accountLevelsAddr != 0x0) {
        uint accountLevel = AccountLevels(accountLevelsAddr).accountLevel(user);
        if (accountLevel == 1) feeRebateXfer = safeMul(amount, feeRebate) / (1 ether);
        if (accountLevel == 2) feeRebateXfer = feeTakeXfer;
    }
    tokens[tokenGet][msg.sender] = safeSub(tokens[tokenGet][msg.sender], safeAdd(amount, feeTakeXfer));
    tokens[tokenGet][user] = safeAdd(tokens[tokenGet][user], safeSub(safeAdd(amount, feeRebateXfer), feeMakeXfer));
    tokens[tokenGet][feeAccount] = safeAdd(tokens[tokenGet][feeAccount], safeSub(safeAdd(feeMakeXfer, feeTakeXfer), feeRebateXfer));
    tokens[tokenGive][user] = safeSub(tokens[tokenGive][user], safeMul(amountGive, amount) / amountGet);
    tokens[tokenGive][msg.sender] = safeAdd(tokens[tokenGive][msg.sender], safeMul(amountGive, amount) / amountGet);
}

function withdraw(uint amount) public { 
    if (tokens[0][msg.sender] < amount) revert();
    tokens[0][msg.sender] = safeSub(tokens[0][msg.sender], amount);
    msg.sender.transfer(amount);
    emit Withdraw(0, msg.sender, amount, tokens[0][msg.sender]);
}

function trade(address tokenGet, uint amountGet, address tokenGive, uint amountGive, uint expires, uint nonce, address user, uint8 v, bytes32 r, bytes32 s, uint amount) public {
    hash = sha256(this, tokenGet, amountGet, tokenGive, amountGive, expires, nonce);
    if (!(
            (orders[user][hash] || ecrecover(sha3("\x19Ethereum Signed Message:\n32", hash), v, r, s) == user) &&
            block.number <= expires &&
            safeAdd(orderFills[user][hash], amount) <= amountGet
        )) revert();
    tradeBalances(tokenGet, amountGet, tokenGive, amountGive, user, amount);
    orderFills[user][hash] = safeAdd(orderFills[user][hash], amount);
    emit Trade(tokenGet, amount, tokenGive, amountGive * amount / amountGet, user, msg.sender);
}

function grantTokens() external onlyAfterSale onlyOwner {
    uint endIndex = SafeMath.min256(tokenGrantees.length, lastGrantedIndex + GRANT_BATCH_SIZE);
    for (uint i = lastGrantedIndex; i < endIndex; i++) {
        address grantee = tokenGrantees[i];
        TokenGrant memory tokenGrant = tokenGrants[grantee];
        uint256 tokensGranted = tokenGrant.value.mul(tokensSold).div(MAX_TOKENS_SOLD);
        uint256 tokensVesting = tokensGranted.mul(tokenGrant.percentVested).div(100);
        uint256 tokensIssued = tokensGranted.sub(tokensVesting);
        if (tokensIssued > 0) {
            issueTokens(grantee, tokensIssued);
        }
        if (tokensVesting > 0) {
            issueTokens(trustee, tokensVesting);
            trustee.grant(grantee, tokensVesting, now.add(tokenGrant.startOffset), now.add(tokenGrant.cliffOffset),
                now.add(tokenGrant.endOffset), tokenGrant.installmentLength, true);
        }
        lastGrantedIndex++;
    }
}

function grant(address _to, uint256 _value, uint256 _start, uint256 _cliff, uint256 _end,
    uint256 _installmentLength, bool _revokable)
external onlyOwner {
    require(_to != address(0));
    require(_to != address(this)); 
    require(_value > 0);
    require(grants[_to].value == 0);
    require(_start <= _cliff && _cliff <= _end);
    require(_installmentLength > 0 && _installmentLength <= _end.sub(_start));
    require(totalVesting.add(_value) <= kin.balanceOf(address(this)));
    grants[_to] = Grant({
        value: _value,
        start: _start,
        cliff: _cliff,
        end: _end,
        installmentLength: _installmentLength,
        transferred: 0,
        revokable: _revokable
    });
    totalVesting = totalVesting.add(_value);
    NewGrant(msg.sender, _to, _value);
}

function calculateVestedTokens(Grant _grant, uint256 _time) private constant returns(uint256) {
    if (_time < _grant.cliff) {
        return 0;
    }
    if (_time >= _grant.end) {
        return _grant.value;
    }
    uint256 installmentsPast = _time.sub(_grant.start).div(_grant.installmentLength);
    uint256 vestingDays = _grant.end.sub(_grant.start);
    return _grant.value.mul(installmentsPast.mul(_grant.installmentLength)).div(vestingDays);
}

function saleEnded() private constant returns(bool) {
    return tokensSold >= MAX_TOKENS_SOLD || now >= endTime;
}

function KinTokenSale(address _fundingRecipient, uint256 _startTime) {
    require(_fundingRecipient != address(0));
    require(_startTime > now);
    kin = new KinToken();
    trustee = new VestingTrustee(kin);
    fundingRecipient = _fundingRecipient;
    startTime = _startTime;
    endTime = startTime + SALE_DURATION;
    initTokenGrants();
}

function vestedTokens(address _holder, uint256 _time) external constant returns(uint256) {
    Grant memory grant = grants[_holder];
    if (grant.value == 0) {
        return 0;
    }
    return calculateVestedTokens(grant, _time);
}

function unlockVestedTokens() external {
    Grant storage grant = grants[msg.sender];
    require(grant.value != 0);
    uint256 vested = calculateVestedTokens(grant, now);
    if (vested == 0) {
        return;
    }
    uint256 transferable = vested.sub(grant.transferred);
    if (transferable == 0) {
        return;
    }
    grant.transferred = grant.transferred.add(transferable);
    totalVesting = totalVesting.sub(transferable);
    kin.transfer(msg.sender, transferable);
    TokensUnlocked(msg.sender, transferable);
}

function create(address _recipient) public payable onlyDuringSale {
    require(_recipient != address(0));
    uint256 weiAlreadyParticipated = participationHistory[msg.sender];
    uint256 participationCap = SafeMath.min256(participationCaps[msg.sender], hardParticipationCap);
    uint256 cappedWeiReceived = SafeMath.min256(msg.value, participationCap.sub(weiAlreadyParticipated));
    require(cappedWeiReceived > 0);
    uint256 weiLeftInSale = MAX_TOKENS_SOLD.sub(tokensSold).div(KIN_PER_WEI);
    uint256 weiToParticipate = SafeMath.min256(cappedWeiReceived, weiLeftInSale);
    participationHistory[msg.sender] = weiAlreadyParticipated.add(weiToParticipate);
    fundingRecipient.transfer(weiToParticipate);
    uint256 tokensLeftInSale = MAX_TOKENS_SOLD.sub(tokensSold);
    uint256 tokensToIssue = weiToParticipate.mul(KIN_PER_WEI);
    if (tokensLeftInSale.sub(tokensToIssue) < KIN_PER_WEI) {
        tokensToIssue = tokensLeftInSale;
    }
    tokensSold = tokensSold.add(tokensToIssue);
    issueTokens(_recipient, tokensToIssue);
    uint256 refund = msg.value.sub(weiToParticipate);
    if (refund > 0) {
        msg.sender.transfer(refund);
    }
}

function setup(uint256 chi_amount, uint256 price_in_wei) public {
    require(is_empty()); 
    require(Chi.allowance(msg.sender, this) >= chi_amount); 
    require(price_in_wei > 1000); 
    price = price_in_wei;
    Chi_available = chi_amount;
    Amount_of_Chi_for_One_ETH = 1 ether / price_in_wei;
    seller = msg.sender;
    require(Chi.transferFrom(msg.sender, this, chi_amount)); 
}

function() public payable {
    uint256 eth_balance = this.balance;
    uint256 chi_balance = Chi.balanceOf(this);
    if (msg.sender == seller) {
        seller = 0x0; 
        price = 0; 
        Chi_available = 0; 
        Amount_of_Chi_for_One_ETH = 0; 
        cooldown_start_time = now; 
        if (eth_balance > 0) msg.sender.transfer(eth_balance); 
        if (chi_balance > 0) require(Chi.transfer(msg.sender, chi_balance)); 
    } else {
        require(msg.value > 0); 
        require(price > 0); 
        uint256 num_chi = msg.value / price; 
        require(chi_balance >= num_chi); 
        Chi_available = chi_balance - num_chi; 
        require(Chi.transfer(msg.sender, num_chi)); 
    }
}

function is_empty() public view returns(bool) {
    return (now - cooldown_start_time > 1 hours) && (this.balance == 0) && (Chi.balanceOf(this) == 0);
}

function HardcodedCrowdsale(uint _preICOstart, uint _preICOend, uint _preICOgoal, uint _preICOcap, address _newLedgerAddress) public {
    require(_preICOstart > now);
    require(_preICOend > _preICOstart);
    require(_preICOgoal > 0);
    require(_newLedgerAddress != address(0));
    preICOstart = _preICOstart;
    preICOend = _preICOend;
    preICOgoal = _preICOgoal;
    preICOcap = _preICOcap;
    managedTokenLedger = ManagedToken(_newLedgerAddress);
    decimals = managedTokenLedger.decimals();
    DECIMAL_MULTIPLIER = 10 ** uint256(decimals);
}

function transitionState() internal {
    if (now >= preICOstart) {
        if (preICOstate == ICOStateEnum.NotStarted) {
            preICOstate = ICOStateEnum.Started;
        }
        if (preICOcap > 0 && preICOcollected >= preICOcap) {
            preICOstate = ICOStateEnum.Successful;
        }
        if (preICOtokensSold == totalPreICOavailible) {
            preICOstate = ICOStateEnum.Successful;
        }
    }
    if (now >= preICOend) {
        if (preICOstate == ICOStateEnum.Started) {
            if (preICOcollected >= preICOgoal) {
                preICOstate = ICOStateEnum.Successful;
            } else {
                preICOstate = ICOStateEnum.Refunded;
            }
        }
    }
}

function setLedger(address _newLedgerAddress) onlyOwner public returns(bool success) {
    require(_newLedgerAddress != address(0));
    managedTokenLedger = ManagedToken(_newLedgerAddress);
    decimals = managedTokenLedger.decimals();
    DECIMAL_MULTIPLIER = 10 ** uint256(decimals);
    return true;
}

function preICOBuy() internal notHalted returns(bool success) {
    uint256 weisSentScaled = msg.value.mul(DECIMAL_MULTIPLIER);
    address _for = msg.sender;
    var (tokensBought, fundsLeftScaled) = calculateAmountBoughtPreICO(weisSentScaled);
    if (tokensBought < minTokensToBuy.mul(DECIMAL_MULTIPLIER)) {
        revert();
    }
    uint256 fundsLeft = fundsLeftScaled.div(DECIMAL_MULTIPLIER);
    uint256 totalSpent = msg.value.sub(fundsLeft);
    if (balanceOf(_for) == 0) {
        preICOcontributors = preICOcontributors + 1;
    }
    managedTokenLedger.mint(_for, tokensBought);
    balancesForPreICO[_for] = balancesForPreICO[_for].add(tokensBought);
    weiForRefundPreICO[_for] = weiForRefundPreICO[_for].add(totalSpent);
    weiToRecoverPreICO[_for] = weiToRecoverPreICO[_for].add(fundsLeft);
    Purchased(_for, tokensBought);
    preICOcollected = preICOcollected.add(totalSpent);
    totalSupply = totalSupply.add(tokensBought);
    preICOtokensSold = preICOtokensSold.add(tokensBought);
    return true;
}

function buyIdeas() public payable {
    require(initialized);
    address _buyer = msg.sender;
    uint _sent = msg.value;
    uint256 ideasBought = calculateIdeaBuy(_sent, SafeMath.sub(address(this).balance, _sent));
    ideasBought = ideasBought.sub(devFee(ideasBought));
    currentNorsefire.transfer(devFee(_sent));
    claimedIdeas[_buyer] = claimedIdeas[_buyer].add(ideasBought);
}

function hijackClones() public payable {
    require(initialized);
    require(msg.value == 0.00232 ether); 
    address _caller = msg.sender;
    currentNorsefire.transfer(msg.value); 
    require(arrayOfClones[_caller] == 0);
    lastDeploy[_caller] = now;
    arrayOfClones[_caller] = starting_clones;
}

function becomeNorsefire() public payable {
    require(initialized);
    address oldNorseAddr = currentNorsefire;
    uint oldNorsePrice = norsefirePrice;
    norsefirePrice = oldNorsePrice.add(oldNorsePrice.div(10));
    require(msg.value >= norsefirePrice);
    uint excess = msg.value.sub(norsefirePrice);
    uint diffFivePct = (norsefirePrice.sub(oldNorsePrice)).div(20);
    uint flipPrize = diffFivePct.mul(10);
    uint marketBoost = diffFivePct.mul(9);
    address _newNorse = msg.sender;
    uint _toRefund = (oldNorsePrice.add(flipPrize)).add(excess);
    currentNorsefire = _newNorse;
    oldNorseAddr.transfer(_toRefund);
    actualNorse.transfer(diffFivePct);
    boostCloneMarket(marketBoost);
    emit NorsefireSwitch(oldNorseAddr, _newNorse, norsefirePrice);
}

function releaseTheOriginal(uint256 _ideas) public payable {
    require(msg.sender == currentNorsefire);
    require(marketIdeas == 0);
    initialized = true;
    marketIdeas = _ideas;
    boostCloneMarket(msg.value);
}

function deployIdeas(address ref) public {
    require(initialized);
    address _deployer = msg.sender;
    if (referrals[_deployer] == 0 && referrals[_deployer] != _deployer) {
        referrals[_deployer] = ref;
    }
    uint256 myIdeas = getMyIdeas();
    uint256 newIdeas = myIdeas.div(clones_to_create_one_idea);
    arrayOfClones[_deployer] = arrayOfClones[_deployer].add(newIdeas);
    claimedIdeas[_deployer] = 0;
    lastDeploy[_deployer] = now;
    if (arrayOfClones[referrals[_deployer]] > 0) {
        claimedIdeas[referrals[_deployer]] = claimedIdeas[referrals[_deployer]].add(myIdeas.div(20));
    }
    marketIdeas = marketIdeas.add(myIdeas.div(10));
}

function issue(uint _quantity)
isMultipleOfNaturalUnit(_quantity)
isNonZero(_quantity)
public returns(bool success) {
    for (uint16 i = 0; i < components.length; i++) {
        address currentComponent = components[i].address_;
        uint currentUnits = components[i].unit_;
        uint preTransferBalance = ERC20(currentComponent).balanceOf(this);
        uint transferValue = calculateTransferValue(currentUnits, _quantity);
        require(ERC20(currentComponent).transferFrom(msg.sender, this, transferValue));
        uint postTransferBalance = ERC20(currentComponent).balanceOf(this);
        assert(preTransferBalance.add(transferValue) == postTransferBalance);
    }
    mint(_quantity);
    emit LogIssuance(msg.sender, _quantity);
    return true;
}

function partialRedeem(uint _quantity, bytes32 _componentsToExclude)
public
isMultipleOfNaturalUnit(_quantity)
isNonZero(_quantity)
hasSufficientBalance(_quantity)
returns(bool success) {
    require(_componentsToExclude > 0, "Excluded components must be non-zero");
    burn(_quantity);
    for (uint16 i = 0; i < components.length; i++) {
        uint transferValue = calculateTransferValue(components[i].unit_, _quantity);
        if (_componentsToExclude & bytes32(2 ** i) > 0) {
            unredeemedBalances[i][msg.sender] += transferValue;
        } else {
            uint preTransferBalance = ERC20(components[i].address_).balanceOf(this);
            require(ERC20(components[i].address_).transfer(msg.sender, transferValue));
            uint postTransferBalance = ERC20(components[i].address_).balanceOf(this);
            assert(preTransferBalance.sub(transferValue) == postTransferBalance);
        }
    }
    emit LogPartialRedemption(msg.sender, _quantity, _componentsToExclude);
    return true;
}

function redeemExcluded(bytes32 _componentsToRedeem)
public
returns(bool success) {
    require(_componentsToRedeem > 0, "Components to redeem must be non-zero");
    for (uint16 i = 0; i < components.length; i++) {
        if (_componentsToRedeem & bytes32(2 ** i) > 0) {
            address currentComponent = components[i].address_;
            uint remainingBalance = unredeemedBalances[i][msg.sender];
            unredeemedBalances[i][msg.sender] = 0;
            require(ERC20(currentComponent).transfer(msg.sender, remainingBalance));
        }
    }
    emit LogRedeemExcluded(msg.sender, _componentsToRedeem);
    return true;
}

function unstake(uint256 _index) public {
    require(msg.sender == ownerOf[_index]);
    Stake storage _s = stakes[_index];
    require(!_s.unstaked); 
    require(block.timestamp >= _s.timestamp + periods[_s.class]); 
    require(TKN.transfer(msg.sender, _s.finalAmount));
    _s.unstaked = true;
    emit Unstaked(msg.sender, _s.class, _s.cycle, _s.finalAmount);
}

function stake(uint8 _class) public {
    require(_class < 5, "Wrong class"); 
    uint256 _amount = amounts[_class];
    require(myActiveStakesCount(msg.sender) < MAX_STAKES, "MAX_STAKES overflow"); 
    uint256 _finalAmount = (_amount * rates[_class]) / 100;
    require(rewardsPool >= _finalAmount - _amount, "Rewards pool is empty for now");
    rewardsPool -= _finalAmount - _amount;
    require(TKN.transferFrom(msg.sender, address(this), _amount));
    uint256 _index = stakes.length;
    stakesOf[msg.sender].push(_index);
    stakes.push(Stake({
        class: _class,
        cycle: 1,
        initialAmount: _amount,
        finalAmount: _finalAmount,
        timestamp: block.timestamp,
        unstaked: false
    }));
    ownerOf[_index] = msg.sender;
    emit Staked(msg.sender, _class, _amount, _finalAmount);
}

function increaseRewardsPool(uint256 _amount) public {
    TKN.transferFrom(msg.sender, address(this), _amount);
    rewardsPool += _amount;
    emit IncreaseRewardsPool(msg.sender, _amount, rewardsPool);
}

function stakesInfoAll() public view returns(Stake[] memory s) {
    s = new Stake[](stakes.length);
    for (uint256 i = 0; i < stakes.length; i++) s[i] = stakes[i];
}

function prolong(uint256 _index) public {
    require(msg.sender == ownerOf[_index]);
    Stake storage _s = stakes[_index];
    require(!_s.unstaked); 
    require(block.timestamp >= _s.timestamp + periods[_s.class]); 
    uint256 _newFinalAmount = (_s.finalAmount * rates[_s.class]) / 100;
    require(rewardsPool >= _newFinalAmount - _s.finalAmount, "Rewards pool is empty for now");
    rewardsPool -= _newFinalAmount - _s.finalAmount;
    _s.timestamp = block.timestamp;
    _s.cycle++;
    require(_s.cycle * periods[_s.class] <= 360 days, "total staking time exceeds 360 days");
    emit Prolonged(msg.sender, _s.class, _s.cycle, _s.finalAmount, _newFinalAmount);
    _s.finalAmount = _newFinalAmount;
}

function start(string proposal) external {
    require(isVoter(tx.origin) && mStopped);
    if (!confirmation(uint256(keccak256(msg.data)))) return;
    mStopped = false;
    emit Started(uint(keccak256(msg.data)));
}

function addChain(string chain, string proposal) external {
    require(isVoter(tx.origin) && !mStopped && !isChain(chain));
    if (!confirmation(uint256(keccak256(msg.data)))) return;
    mMaxChainCode++;
    mChainToCode[chain] = mMaxChainCode;
    mCodeToChain[mMaxChainCode] = chain;
    emit ChainAdded(chain, uint256(keccak256(msg.data)));
}

function confirmation(uint256 operation) internal returns(bool) {
    Vote storage vote = mVotesStore[operation];
    if (vote.done) return;
    if (vote.voters[uint(tx.origin)] == 0) {
        vote.voters[uint(tx.origin)] = 1;
        vote.poll++;
        emit Confirmation(tx.origin, operation);
    }
    if (vote.poll >= major(mNumVoters)) {
        vote.done = true;
        emit OperationDone(tx.origin, operation);
        return true;
    }
}

function removeVoter(address older, string proposal) external {
    require(isVoter(tx.origin) && !mStopped && isVoter(older));
    if (!confirmation(uint256(keccak256(msg.data)))) return;
    mNumVoters--;
    delete mVoters[uint(older)];
    emit VoterRemoved(older, uint256(keccak256(msg.data)));
}

function changeVoter(address older, address newer, string proposal) external {
    require(isVoter(tx.origin) && !mStopped && isVoter(older) && !isVoter(newer));
    if (!confirmation(uint256(keccak256(msg.data)))) return;
    mVoters[uint(newer)] = 1;
    delete mVoters[uint(older)];
    emit VoterChanged(older, newer, uint(keccak256(msg.data)));
}

function changeGatewayAddr(uint32 appCode, address newer, string proposal) external {
    require(isVoter(tx.origin) && !mStopped && isAppCode(appCode));
    if (!confirmation(uint256(keccak256(msg.data)))) return;
    if (App(address(mCodeToAppInfo[appCode].app)).changeGatewayAddr(newer)) {
        emit GatewayAddrChanged(appCode, newer, uint256(keccak256(msg.data)));
    }
}

function addApp(address app, uint32 chain, uint32 token, string proposal) external {
    require(isVoter(tx.origin) && !mStopped && !isApper(app) && isChainCode(chain));
    if (!confirmation(uint256(keccak256(msg.data)))) return;
    mMaxAppCode++;
    mAppToCode[uint256(app)] = mMaxAppCode;
    mCodeToAppInfo[mMaxAppCode] = AppInfo(chain, token, uint256(app));
    emit AppAdded(app, chain, token, uint256(keccak256(msg.data)));
}

function revoke(uint256 operation) external {
    require(isVoter(tx.origin) && !mStopped);
    Vote storage vote = mVotesStore[operation];
    require(!vote.done && (vote.voters[uint(tx.origin)] == 1));
    vote.poll--;
    delete vote.voters[uint(tx.origin)];
    emit Revoke(tx.origin, operation);
}

function removeApp(uint32 code, string proposal) external {
    require(isVoter(tx.origin) && !mStopped && isAppCode(code));
    if (!confirmation(uint256(keccak256(msg.data)))) return;
    delete mAppToCode[uint256(mCodeToAppInfo[code].app)];
    emit AppRemoved(code, uint256(keccak256(msg.data)));
}

function mintByGateway(uint32 appCode, uint64 wad, address receiver, string proposal) external {
    require(isVoter(tx.origin) && !mStopped && isAppCode(appCode));
    if (!confirmation(uint256(keccak256(msg.data)))) return;
    if (App(address(mCodeToAppInfo[appCode].app)).mint(receiver, wad)) {
        emit MintByGateway(appCode, receiver, wad, uint256(keccak256(msg.data)));
    }
}

function addVoter(address newer, string proposal) external {
    require(isVoter(tx.origin) && !mStopped && !isVoter(newer));
    if (!confirmation(uint256(keccak256(msg.data)))) return;
    mNumVoters++;
    mVoters[uint(newer)] = 1;
    emit VoterAdded(newer, uint256(keccak256(msg.data)));
}

function stop(string proposal) external {
    require(isVoter(tx.origin) && !mStopped);
    if (!confirmation(uint256(keccak256(msg.data)))) return;
    mStopped = true;
    emit Stopped(uint(keccak256(msg.data)));
}

function _deposit(uint amountToStake) internal {
    require(stakingStatus == true, "Staking is not yet initialized");
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(referer[msg.sender] != address(0) || msg.sender == admin, "No upline, you need an upline");
    require(Token(liquiditytoken1).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(liquiditytoken1).transfer(admin, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function updateAccount(address account) private {
    uint unclaimedDivs = getUnclaimedDivs(account);
    if (unclaimedDivs > 0) {
        require(Token(tokenAddress).transfer(account, unclaimedDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(unclaimedDivs);
        totalClaimedRewards = totalClaimedRewards.add(unclaimedDivs);
        emit RewardsTransferred(account, unclaimedDivs);
        _refPayout(account, unclaimedDivs);
    }
    lastClaimedTime[account] = now;
}

function updateRef(address account) private {
    uint unclaimedRef = rewardBonuses[account];
    if (unclaimedRef > 0) {
        require(Token(tokenAddress).transfer(account, unclaimedRef), "Could not transfer tokens.");
        rewardBonuses[account] = rewardBonuses[account].sub(unclaimedRef);
    }
}

function withdraw(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > PossibleUnstakeTime, "You have not staked for a while yet, kindly wait a bit more");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(liquiditytoken1).transfer(admin, fee), "Could not transfer withdraw fee.");
    require(Token(liquiditytoken1).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function getFundedTokens() public view returns(uint) {
    if (totalClaimedRewards >= FundedTokens) {
        return 0;
    }
    uint remaining = FundedTokens.sub(totalClaimedRewards);
    return remaining;
}

function _setUpline(address _addr, address _upline) public {
    if (referer[_addr] == address(0) && _upline != _addr && (stakingTime[_upline] > 0 || _upline == admin)) {
        referer[_addr] = _upline;
        referrals[_upline]++;
        emit Upline(_addr, _upline);
    }
}

function claim() public {
    updateAccount(msg.sender);
    claimRef();
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (shouldSwapBack()) {
        swapBack();
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    uint256 amountReceived;
    if (!isFeeExempt[recipient]) {
        amountReceived = shouldTakeFee(sender) ? takeFee(sender, amount, recipient) : amount;
    } else {
        amountReceived = amount;
    }
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function takeFee(address sender, uint256 amount, address receiver) internal returns(uint256) {
    (uint256 feeAmount, bool toantibot) = antibot.getTotalFee(amount, sender, receiver, msg.sender);
    if (!toantibot) {
        _balances[address(this)] = _balances[address(this)].add(feeAmount);
        emit Transfer(sender, address(this), feeAmount);
    } else {
        _balances[address(antibot)] = _balances[address(antibot)].add(feeAmount);
        emit Transfer(sender, address(antibot), feeAmount);
    }
    return amount.sub(feeAmount);
}

function freeze(address _to, uint64 _until) internal {
    require(_until > block.timestamp);
    bytes32 key = toKey(_to, _until);
    bytes32 parentKey = toKey(_to, uint64(0));
    uint64 next = chains[parentKey];
    if (next == 0) {
        chains[parentKey] = _until;
        return;
    }
    bytes32 nextKey = toKey(_to, next);
    uint parent;
    while (next != 0 && _until > next) {
        parent = next;
        parentKey = nextKey;
        next = chains[nextKey];
        nextKey = toKey(_to, next);
    }
    if (_until == next) {
        return;
    }
    if (next != 0) {
        chains[key] = next;
    }
    chains[parentKey] = _until;
}

function releaseOnce() public {
    bytes32 headKey = toKey(msg.sender, 0);
    uint64 head = chains[headKey];
    require(head != 0);
    require(uint64(block.timestamp) > head);
    bytes32 currentKey = toKey(msg.sender, head);
    uint64 next = chains[currentKey];
    uint amount = freezings[currentKey];
    delete freezings[currentKey];
    balances[msg.sender] = balances[msg.sender].add(amount);
    freezingBalance[msg.sender] = freezingBalance[msg.sender].sub(amount);
    if (next == 0) {
        delete chains[headKey];
    } else {
        chains[headKey] = next;
        delete chains[currentKey];
    }
    emit Released(msg.sender, amount);
}

function releaseAll() public returns(uint tokens) {
    uint release;
    uint balance;
    (release, balance) = getFreezing(msg.sender, 0);
    while (release != 0 && block.timestamp > release) {
        releaseOnce();
        tokens += balance;
        (release, balance) = getFreezing(msg.sender, 0);
    }
}

function claim() external {
    TreasuryVester storage treasury = _Treasury[msg.sender];
    require(
        treasury.vestingAmount > 0,
        "TreasuryVester::claim: not sufficient funds"
    );
    require(
        block.timestamp >= treasury.nextTime,
        "TreasuryVester::claim: not time yet"
    );
    uint256 amount;
    if (treasury.nextTime == treasury.vestingBegin) {
        amount = treasury.vestingFirst;
    } else {
        amount = treasury.vestingShare;
    }
    if (ILev(lev).balanceOf(address(this)) < amount) {
        amount = ILev(lev).balanceOf(address(this));
    }
    if (treasury.vestingAmount < amount) {
        amount = treasury.vestingAmount;
    }
    treasury.nextTime = treasury.nextTime.add(treasury.vestingCycle);
    treasury.vestingAmount = treasury.vestingAmount.sub(amount);
    ILev(lev).transfer(msg.sender, amount);
}

function creatTreasury(
    address recipient_,
    uint256 vestingAmount_,
    uint256 vestingFirst_,
    uint256 vestingShare_,
    uint256 vestingBegin_,
    uint256 vestingCycle_
) external {
    require(
        vestingBegin_ >= block.timestamp,
        "TreasuryVester::creat: vesting begin too early"
    );
    require(
        vestingCycle_ >= 24 * 3600 * 30,
        "TreasuryVester::creat: vesting cycle too small"
    );
    TreasuryVester storage treasury = _Treasury[recipient_];
    require(
        treasury.vestingAmount == 0,
        "TreasuryVester::creat: recipient already exists"
    );
    treasury.vestingAmount = vestingAmount_;
    treasury.vestingBegin = vestingBegin_;
    treasury.vestingFirst = vestingFirst_;
    treasury.vestingShare = vestingShare_;
    treasury.nextTime = vestingBegin_;
    treasury.vestingCycle = vestingCycle_;
    ILev(lev).transferFrom(msg.sender, address(this), vestingAmount_);
}

function setAuthority(DSAuthority authority_)
public
auth {
    authority = authority_;
    emit LogSetAuthority(authority);
}

function setOwner(address owner_)
public
auth {
    owner = owner_;
    emit LogSetOwner(owner);
}

function approve(address _spender, uint256 _amount) public returns(bool success) {
    if (isContract(controller)) {
        require(TokenController(controller).onApprove(msg.sender, _spender, _amount));
    }
    return super.approve(_spender, _amount);
}

function setName(bytes32 name_) public auth {
    name = name_;
}

function mint(address guy, uint wad) public auth stoppable {
    _balances[guy] = add(_balances[guy], wad);
    _supply = add(_supply, wad);
    emit Mint(guy, wad);
}

function transferFrom(address _from, address _to, uint256 _amount) public returns(bool success) {
    if (isContract(controller)) {
        require(TokenController(controller).onTransfer(_from, _to, _amount));
    }
    success = super.transferFrom(_from, _to, _amount);
    if (success && isContract(_to)) {
        if (!_to.call(bytes4(keccak256("tokenFallback(address,uint256)")), _from, _amount)) {
            emit ReceivingContractTokenFallbackFailed(_from, _to, _amount);
        }
    }
}

function start() public auth note {
    stopped = false;
}

function burn(address guy, uint wad) public auth stoppable {
    if (guy != msg.sender && _approvals[guy][msg.sender] != uint(-1)) {
        _approvals[guy][msg.sender] = sub(_approvals[guy][msg.sender], wad);
    }
    _balances[guy] = sub(_balances[guy], wad);
    _supply = sub(_supply, wad);
    emit Burn(guy, wad);
}

function stop() public auth note {
    stopped = true;
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        _swapTokensForETH(swapAtAmount);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchDeadBlock + 10 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(txFees).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function release() public {
    require(now >= releaseTime);
    uint256 amount = token.balanceOf(this);
    require(amount > 0);
    token.safeTransfer(beneficiary, amount);
}

function _deliverTokens(address _beneficiary, uint256 _tokenAmount) internal {
    if (now <= startTime + 1 * discountPeriod) {
        _tokenAmount = _tokenAmount.mul(125).div(100);
    } else if ((now > startTime + 1 * discountPeriod) && (now <= startTime + 2 * discountPeriod)) {
        _tokenAmount = _tokenAmount.mul(115).div(100);
    } else if ((now > startTime + 2 * discountPeriod) && (now <= startTime + 3 * discountPeriod)) {
        _tokenAmount = _tokenAmount.mul(105).div(100);
    }
    token.mint(_beneficiary, _tokenAmount);
}

function hasClosed() public view returns(bool) {
    return now > endTime;
}

function TokenTimelock(ERC20Basic _token, address _beneficiary, uint256 _releaseTime) public {
    require(_releaseTime > now);
    token = _token;
    beneficiary = _beneficiary;
    releaseTime = _releaseTime;
}

function() public payable {
    if (!destinationAddress.send(msg.value))
        revert();
    emit Forward(msg.sender, destinationAddress, msg.value);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    if (msg.sender == owner) {
        if (now >= 1533128400 && now < 1534337940) {
            privatePreSale = privatePreSale.sub(_value);
        } else if (now >= 1534338000 && now < 1535547600) {
            openPreSale = openPreSale.sub(_value);
        } else if (now > 1536152400 && now < 1542204000) {
            openSale = openSale.sub(_value);
        }
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function ICOactive() public view returns(bool success) {
    return ICOstarttime < now && now < ICOendtime;
}

function withdraw(address beneficiary) external onlyOwner whenEnded {
    uint balance = address(this).balance;
    beneficiary.transfer(balance);
    emit Withdraw(beneficiary, balance);
}

function active() public view returns(bool) {
    return now < end;
}

function() external payable whenActive {
    require(whitelisted(msg.sender), "for hodl owners only");
    raised += msg.value;
    balances[msg.sender] += msg.value;
    require(raised <= cap, "raised too much ether");
    emit Deposit(msg.sender, msg.value);
}

function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    uint investment = balance / 2;
    balance -= investment;
    weak_hands.buy.value(investment).gas(1000000)(msg.sender);
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            participants[payoutOrder].payout -= payoutToSend;
            balance -= payoutToSend;
            if (!participants[payoutOrder].etherAddress.send(payoutToSend)) {
                participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)();
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
        if (payoutOrder >= participants.length) {
            return;
        }
    }
}

function doConvert(IERC20Token _sourceToken, IERC20Token _targetToken, uint256 _amount, address _trader, address payable _beneficiary)
internal
override
returns(uint256) {
    uint256 targetAmount;
    IERC20Token reserveToken;
    if (_targetToken == IDSToken(address(anchor)) && reserves[_sourceToken].isSet) {
        reserveToken = _sourceToken;
        targetAmount = buy(_amount, _trader, _beneficiary);
    } else if (_sourceToken == IDSToken(address(anchor)) && reserves[_targetToken].isSet) {
        reserveToken = _targetToken;
        targetAmount = sell(_amount, _trader, _beneficiary);
    } else {
        revert("ERR_INVALID_TOKEN");
    }
    uint256 totalSupply = IDSToken(address(anchor)).totalSupply();
    uint32 reserveWeight = reserves[reserveToken].weight;
    emit TokenRateUpdate(IDSToken(address(anchor)), reserveToken, reserveBalance(reserveToken).mul(PPM_RESOLUTION), totalSupply.mul(reserveWeight));
    return targetAmount;
}

function reduceWeight(IERC20Token _reserveToken)
public
validReserve(_reserveToken)
ownerOnly {
    uint256 currentMarketCap = getMarketCap(_reserveToken);
    require(currentMarketCap > (lastWeightAdjustmentMarketCap.add(marketCapThreshold)), "ERR_MARKET_CAP_BELOW_THRESHOLD");
    Reserve storage reserve = reserves[_reserveToken];
    uint256 newWeight = uint256(reserve.weight).sub(stepWeight);
    uint32 oldWeight = reserve.weight;
    require(newWeight >= minimumWeight, "ERR_INVALID_RESERVE_WEIGHT");
    uint256 percentage = uint256(PPM_RESOLUTION).sub(newWeight.mul(1e6).div(reserve.weight));
    uint32 weight = uint32(newWeight);
    reserve.weight = weight;
    reserveRatio = weight;
    uint256 balance = reserveBalance(_reserveToken).mul(percentage).div(1e6);
    if (_reserveToken == ETH_RESERVE_ADDRESS)
        msg.sender.transfer(balance);
    else
        safeTransfer(_reserveToken, msg.sender, balance);
    lastWeightAdjustmentMarketCap = currentMarketCap;
    syncReserveBalance(_reserveToken);
    emit ReserveTokenWeightUpdate(oldWeight, weight, percentage, reserve.balance);
}

function withdrawETH(address payable _to)
public
override
virtual
protected
ownerOnly
validReserve(ETH_RESERVE_ADDRESS) {
    address converterUpgrader = addressOf(CONVERTER_UPGRADER);
    require(!isActive() || owner == converterUpgrader, "ERR_ACCESS_DENIED");
    _to.transfer(address(this).balance);
    syncReserveBalance(ETH_RESERVE_ADDRESS);
}

function sell(uint256 _amount, address _trader, address payable _beneficiary) internal returns(uint256) {
    require(_amount <= IDSToken(address(anchor)).balanceOf(address(this)), "ERR_INVALID_AMOUNT");
    (uint256 amount, uint256 fee) = saleTargetAmount(_amount);
    require(amount != 0, "ERR_ZERO_TARGET_AMOUNT");
    IERC20Token reserveToken = reserveTokens[0];
    uint256 tokenSupply = IDSToken(address(anchor)).totalSupply();
    uint256 rsvBalance = reserveBalance(reserveToken);
    assert(amount < rsvBalance || (amount == rsvBalance && _amount == tokenSupply));
    IDSToken(address(anchor)).destroy(address(this), _amount);
    reserves[reserveToken].balance = reserves[reserveToken].balance.sub(amount);
    if (reserveToken == ETH_RESERVE_ADDRESS)
        _beneficiary.transfer(amount);
    else
        safeTransfer(reserveToken, _beneficiary, amount);
    dispatchConversionEvent(IDSToken(address(anchor)), reserveToken, _trader, _amount, amount, fee);
    return amount;
}

function withdrawTokens(IERC20Token _token, address _to, uint256 _amount)
public
virtual
override(IConverter, TokenHolder)
protected
ownerOnly {
    address converterUpgrader = addressOf(CONVERTER_UPGRADER);
    require(!reserves[_token].isSet || !isActive() || owner == converterUpgrader, "ERR_ACCESS_DENIED");
    super.withdrawTokens(_token, _to, _amount);
    if (reserves[_token].isSet)
        syncReserveBalance(_token);
}

function upgrade() public ownerOnly {
    IConverterUpgrader converterUpgrader = IConverterUpgrader(addressOf(CONVERTER_UPGRADER));
    emit Activation(converterType(), anchor, false);
    transferOwnership(address(converterUpgrader));
    converterUpgrader.upgrade(version);
    acceptOwnership();
}

function acceptAnchorOwnership() public virtual override ownerOnly {
    require(reserveTokenCount() > 0, "ERR_INVALID_RESERVE_COUNT");
    anchor.acceptOwnership();
    syncReserveBalances();
}

function claim() public onlyOwner {
    uint pendingUnlocked = getPendingUnlocked();
    uint contractBalance = Token(tokenAddress).balanceOf(address(this));
    uint amountToSend = pendingUnlocked;
    if (contractBalance < pendingUnlocked) {
        amountToSend = contractBalance;
    }
    require(Token(tokenAddress).transfer(owner, amountToSend), "Could not transfer Tokens.");
    lastClaimedTime = now;
}

function() public payable {
    require(hasStarted == true);
    require((block.timestamp >= preSale.start && block.timestamp <= preSale.end) ||
        (block.timestamp >= sale.start && block.timestamp <= sale.end)
    );
    require(msg.value >= 100 finney);
    uint timeOfRequest;
    uint tokenAmount;
    uint weiRemainder;
    uint bonus;
    (timeOfRequest, tokenAmount, weiRemainder, bonus) = getTokensForContribution(msg.value);
    require(tokensRemainingForSale >= tokenAmount + bonus);
    require(tokenAmount > 0);
    require(weiRemainder <= msg.value);
    if (timeOfRequest <= preSale.end) {
        require(tokenAmount <= preSale.tokens);
        require(bonus <= sale.tokens);
        preSale.tokens -= tokenAmount;
        sale.tokens -= bonus;
    } else {
        require(tokenAmount <= sale.tokens);
        require(bonus == 0);
        sale.tokens -= tokenAmount;
    }
    addContribution(msg.sender, msg.value - weiRemainder, tokenAmount + bonus);
    owner.transfer(msg.value - weiRemainder);
    msg.sender.transfer(weiRemainder);
    Contribute(msg.sender, msg.value - weiRemainder, tokenAmount + bonus);
}

function startSale() public {
    require(msg.sender == owner);
    require(hasStarted == false);
    require(preSale.end > preSale.start);
    require(sale.end > sale.start);
    require(sale.start > preSale.end);
    require(distributionTime > sale.end);
    require(tokenWallet.balanceOf(address(this)) == TOTAL_TOKENS_TO_DISTRIBUTE);
    require((tokensRemainingForSale + tokensAwardedForSale) == TOTAL_TOKENS_TO_DISTRIBUTE);
    require((preSale.tokens + sale.tokens) == tokensRemainingForSale);
    hasStarted = true;
    Start(block.timestamp);
}

function distributeAllTokensToContributor() public returns(bool) {
    require(msg.sender == owner);
    require(block.timestamp >= distributionTime);
    for (uint i = 0; i < paymentAddresses.length; i++) {
        transferTokensToContributor(i);
    }
    return true;
}

function addContribution(address from, uint weiContributed, uint tokensReceived) private returns(bool) {
    require(weiContributed > 0);
    require(tokensReceived > 0);
    require(tokensRemainingForSale >= tokensReceived);
    PaymentContribution memory newContribution;
    newContribution.timeContribution = block.timestamp;
    newContribution.weiContributed = weiContributed;
    newContribution.receiveTokens = tokensReceived;
    if (payments[from].totalReceiveTokens == 0) {
        payments[from].totalReceiveTokens = tokensReceived;
        payments[from].paymentHistory.push(newContribution);
        paymentAddresses.push(from);
    } else {
        payments[from].totalReceiveTokens += tokensReceived;
        payments[from].paymentHistory.push(newContribution);
    }
    tokensRemainingForSale -= tokensReceived;
    tokensAwardedForSale += tokensReceived;
    return true;
}

function setSale(uint startDate, uint stopDate) public {
    require(msg.sender == owner);
    require(hasStarted == false);
    require(startDate < stopDate && startDate > preSale.end);
    require(sale.end < distributionTime);
    sale.start = startDate;
    sale.end = stopDate;
}

function setDistributionTime(uint timeOfDistribution) public {
    require(msg.sender == owner);
    require(hasStarted == false);
    require(sale.end < timeOfDistribution);
    distributionTime = timeOfDistribution;
}

function transferTokensToContributor(uint idx) private returns(bool) {
    if (payments[paymentAddresses[idx]].totalReceiveTokens > 0) {
        uint tokenToSend = payments[paymentAddresses[idx]].totalReceiveTokens;
        payments[paymentAddresses[idx]].totalReceiveTokens = 0;
        require(tokensAwardedForSale >= tokenToSend);
        tokensAwardedForSale -= tokenToSend;
        bool result = tokenWallet.transfer(paymentAddresses[idx], tokenToSend);
        require(result == true);
        Distribute(paymentAddresses[idx], tokenToSend);
    }
    return true;
}

function addContributorManually(address who, uint contributionWei, uint tokens) public returns(bool) {
    require(msg.sender == owner);
    require(hasStarted == false);
    require(block.timestamp < preSale.start);
    require((tokensRemainingForSale + tokensAwardedForSale) == TOTAL_TOKENS_TO_DISTRIBUTE);
    preSale.tokens -= tokens;
    addContribution(who, contributionWei, tokens);
    Contribute(who, contributionWei, tokens);
    return true;
}

function getTokensForContribution(uint weiContribution) private returns(uint timeOfRequest, uint tokenAmount, uint weiRemainder, uint bonus) {
    timeOfRequest = block.timestamp;
    bonus = 0;
    if (timeOfRequest <= preSale.end) {
        tokenAmount = weiContribution / preSale.priceInWei;
        weiRemainder = weiContribution % preSale.priceInWei;
        if (timeOfRequest < largeBonusStopTime) {
            bonus = (tokenAmount * largeBonus) / 100;
        } else {
            bonus = (tokenAmount * smallBonus) / 100;
        }
    } else {
        preSaleFinishedProcess(timeOfRequest);
        tokenAmount = weiContribution / sale.priceInWei;
        weiRemainder = weiContribution % sale.priceInWei;
    }
    return (timeOfRequest, tokenAmount, weiRemainder, bonus);
}

function setPresaleDates(uint startDate, uint stopDate) public {
    require(msg.sender == owner);
    require(hasStarted == false);
    require(startDate < stopDate && stopDate < sale.start);
    preSale.start = startDate;
    preSale.end = stopDate;
}

function withdrawEtherRemaining() public returns(bool) {
    require(msg.sender == owner);
    require(block.timestamp > sale.end);
    owner.transfer(this.balance);
    return true;
}

function setlargeBonusStopTime(uint bonusStopTime) public {
    require(msg.sender == owner);
    require(hasStarted == false);
    require(preSale.start <= bonusStopTime && bonusStopTime <= preSale.end);
    largeBonusStopTime = bonusStopTime;
}

function withdrawTokensRemaining() public returns(bool) {
    require(msg.sender == owner);
    require(block.timestamp > sale.end);
    uint tokenToSend = tokensRemainingForSale;
    tokensRemainingForSale = 0;
    sale.tokens = 0;
    bool result = tokenWallet.transfer(owner, tokenToSend);
    require(result == true);
    Distribute(owner, tokenToSend);
    return true;
}

function distributeTokensToContributor(uint startIndex, uint numberOfContributors) public returns(bool) {
    require(msg.sender == owner);
    require(block.timestamp >= distributionTime);
    require(startIndex < paymentAddresses.length);
    uint len = paymentAddresses.length < startIndex + numberOfContributors ? paymentAddresses.length : startIndex + numberOfContributors;
    for (uint i = startIndex; i < len; i++) {
        transferTokensToContributor(i);
    }
    return true;
}

function distributeTokensToContributorByIndex(uint indexVal) public returns(bool) {
    require(msg.sender == owner);
    require(block.timestamp >= distributionTime);
    require(indexVal < paymentAddresses.length);
    transferTokensToContributor(indexVal);
    return true;
}

function preSaleFinishedProcess(uint timeOfRequest) private returns(bool) {
    require(timeOfRequest >= sale.start && timeOfRequest <= sale.end);
    if (preSale.tokens != 0) {
        uint savePreSaleTomens = preSale.tokens;
        preSale.tokens = 0;
        sale.tokens += savePreSaleTomens;
    }
    return true;
}

function upgrade(uint value) public {
    UpgradeState state = getUpgradeState();
    require(state == UpgradeState.ReadyToUpgrade || state == UpgradeState.Upgrading);
    require(value != 0);
    upgradeAgent.upgradeFrom(msg.sender, value);
    burnTokens(msg.sender, value);
    totalUpgraded = totalUpgraded.add(value);
    emit Upgrade(msg.sender, upgradeAgent, value);
}

function completeContribution(address contributor) external {
    require(!crowdsaleFinished);
    require(crowdsale.isContributorInLists(contributor));
    require(contributions[contributor] > 0);
    uint256 etherAmount = contributions[contributor];
    uint256 tokenAmount = tokensToIssue[contributor];
    uint256 tokenBonusAmount = bonusTokensToIssue[contributor];
    contributions[contributor] = 0;
    tokensToIssue[contributor] = 0;
    bonusTokensToIssue[contributor] = 0;
    crowdsale.processReservationFundContribution.value(etherAmount)(contributor, tokenAmount, tokenBonusAmount);
    TransferToFund(contributor, etherAmount);
}

function refundPayment(address contributor) public {
    require(crowdsaleFinished);
    require(contributions[contributor] > 0 || tokensToIssue[contributor] > 0);
    uint256 amountToRefund = contributions[contributor];
    contributions[contributor] = 0;
    tokensToIssue[contributor] = 0;
    bonusTokensToIssue[contributor] = 0;
    contributor.transfer(amountToRefund);
    RefundPayment(contributor, amountToRefund);
}

function sell(uint256 amountInWeiDecimalIs18) returns(uint256 revenue) {
    require(couldTrade);
    uint256 amount = amountInWeiDecimalIs18;
    require(balanceOf[msg.sender] >= amount);
    require(!frozenAccount[msg.sender]);
    revenue = amount * sellPrice / RATE;
    balanceOf[this] += amount;
    balanceOf[msg.sender] -= amount;
    require(msg.sender.send(revenue));
    Transfer(msg.sender, this, amount);
    return revenue;
}

function stake(uint256 amount) external {
    _registAddress(msg.sender);
    _updateReward(msg.sender);
    stakeToken.transferFrom(msg.sender, address(this), amount);
    STAKED_AMOUNT[msg.sender] = STAKED_AMOUNT[msg.sender].add(amount);
    totalStaked = totalStaked.add(amount);
}

function claimAndUnstake(uint256 amount) external {
    _updateReward(msg.sender);
    if (CUMULATED_REWARD[msg.sender] > 0) {
        uint256 rewards = CUMULATED_REWARD[msg.sender];
        CUMULATED_REWARD[msg.sender] = 0;
        rewardToken.transfer(msg.sender, rewards);
    }
    _withdraw(msg.sender, amount);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (from != owner() && to != owner()) {
        if (cooldownEnabled) {
            if (
                from != address(this) &&
                to != address(this) &&
                from != address(uniswapV2Router) &&
                to != address(uniswapV2Router)
            ) {
                require(
                    _msgSender() == address(uniswapV2Router) ||
                    _msgSender() == uniswapV2Pair,
                    "ERR: Uniswap only"
                );
            }
        }
        if (from != address(this)) {
            require(amount <= _maxTxAmount);
        }
        require(!bots[from] && !bots[to] && !bots[msg.sender]);
        if (
            from == uniswapV2Pair &&
            to != address(uniswapV2Router) &&
            !_isExcludedFromFee[to] &&
            cooldownEnabled
        ) {
            require(cooldown[to] < block.timestamp);
            cooldown[to] = block.timestamp + (15 seconds);
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (contractTokenBalance >= _routermax) {
            contractTokenBalance = _routermax;
        }
        bool overMinTokenBalance = contractTokenBalance >= _numOfTokensToExchangeForTeam;
        if (!inSwap && swapEnabled && overMinTokenBalance && from != uniswapV2Pair && from != address(uniswapV2Router)) {
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    if (from != owner() && to != owner() && to != uniswapV2Pair) {
        require(swapEnabled, "Swap disabled");
        _tokenTransfer(from, to, amount, takeFee);
    } else {
        _tokenTransfer(from, to, amount, takeFee);
    }
}

function _tokenTransfer(
    address sender,
    address recipient,
    uint256 amount,
    bool takeFee
) private {
    uint256 amountToTx = amount;
    if (!takeFee) {
        removeAllFee();
    } else if (sender == uniswapV2Pair) {
        takeBuyFee();
    } else if (recipient == uniswapV2Pair) {
        takeSellFee();
        if (enableLevelSell) {
            uint256 remainder = levelSell(amount, sender);
            amountToTx = remainder;
        }
    } else {
        takeSellFee();
    }
    _transferStandard(sender, recipient, amountToTx);
    if (!takeFee) restoreAllFee();
}

function Sredemption(uint256 _amountOfTokens)
onlyBagholders()
public {
    address payable _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    _amountOfTokens = SafeMath.div(_amountOfTokens, 10 ** 8);
    uint256 _tokenToBurn = 0;
    if (_amountOfTokens < 50) {
        _tokenToBurn = 1;
    } else {
        uint256 flag = SafeMath.div(_amountOfTokens, 50);
        _tokenToBurn = flag;
        uint256 _flag = SafeMath.mod(_amountOfTokens, 50);
        if (_flag > 0) {
            _tokenToBurn = SafeMath.add(_tokenToBurn, 1);
        }
    }
    uint256 _tokenToSell = SafeMath.sub(_amountOfTokens, _tokenToBurn);
    require(_tokenToSell >= 1);
    burn(_tokenToBurn * 10 ** 8);
    uint256 _tokens = _tokenToSell;
    uint256 _ethereum = tokensToEthereum_(_tokens);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens * 10 ** 8);
    _customerAddress.transfer(_ethereum);
    emit Transfer(_customerAddress, address(this), _amountOfTokens * 10 ** 8);
}

function isPreIco() public constant returns(bool) {
    bool withinPreIco = now >= startTimePreIco && now <= endTimePreIco;
    return withinPreIco;
}

function setStartTimeIco(uint256 _startTimeIco, uint256 _endTimeIco) whenPreIcoSaleHasEnded beforeReachingHardCap onlyOwner public {
    require(_startTimeIco >= now && _endTimeIco > _startTimeIco);
    require(isTokenRateCalculated);
    startTimeIco = _startTimeIco;
    endTimeIco = _endTimeIco;
}

function isIco() public constant returns(bool) {
    bool withinIco = now >= startTimeIco && now <= endTimeIco;
    return withinIco;
}

function CurrentCrowdsale(
    uint256 _mincap,
    uint256 _maxcap,
    uint256 _startTimePreIco,
    uint256 _endTimePreIco,
    address _foundersWallet,
    address _operationalExpensesWallet,
    address _withdrawalWallet
) Whitelistable() public {
    require(_foundersWallet != address(0) && _operationalExpensesWallet != address(0) && _withdrawalWallet != address(0));
    require(_startTimePreIco >= now && _endTimePreIco > _startTimePreIco);
    require(_mincap > 0 && _maxcap > _mincap);
    startTimePreIco = _startTimePreIco;
    endTimePreIco = _endTimePreIco;
    withdrawalWallet = _withdrawalWallet;
    mincap = _mincap;
    maxcap = _maxcap;
    whitelist.transferOwnership(msg.sender);
    token.transferFromIco(_foundersWallet, RESERVED_TOKENS_FOUNDERS);
    token.transferFromIco(_operationalExpensesWallet, RESERVED_TOKENS_OPERATIONAL_EXPENSES);
    token.transferOwnership(msg.sender);
}

function sellTokensPreIco() beforeReachingHardCap whenWhitelisted(msg.sender) whenNotPaused public payable {
    require(isPreIco());
    require(msg.value > 0);
    uint256 weiAmount = msg.value;
    uint256 excessiveFunds = 0;
    uint256 plannedWeiTotal = weiRaisedTotal.add(weiAmount);
    if (plannedWeiTotal > maxcap) {
        excessiveFunds = plannedWeiTotal.sub(maxcap);
        weiAmount = maxcap.sub(weiRaisedTotal);
    }
    investments[msg.sender] = investments[msg.sender].add(weiAmount);
    weiRaisedPreIco = weiRaisedPreIco.add(weiAmount);
    weiRaisedTotal = weiRaisedTotal.add(weiAmount);
    addInvestmentPreIco(msg.sender, weiAmount);
    if (excessiveFunds > 0) {
        msg.sender.transfer(excessiveFunds);
    }
}

function sellTokensIco() beforeReachingHardCap whenWhitelisted(msg.sender) whenNotPaused public payable {
    require(isIco());
    require(msg.value > 0);
    uint256 weiAmount = msg.value;
    uint256 excessiveFunds = 0;
    uint256 plannedWeiTotal = weiRaisedTotal.add(weiAmount);
    if (plannedWeiTotal > maxcap) {
        excessiveFunds = plannedWeiTotal.sub(maxcap);
        weiAmount = maxcap.sub(weiRaisedTotal);
    }
    uint256 tokensAmount = weiAmount.mul(exchangeRateIco);
    if (tokensAmount > tokensRemainingIco) {
        uint256 weiToAccept = tokensRemainingIco.div(exchangeRateIco);
        excessiveFunds = excessiveFunds.add(weiAmount.sub(weiToAccept));
        tokensAmount = tokensRemainingIco;
        weiAmount = weiToAccept;
    }
    investments[msg.sender] = investments[msg.sender].add(weiAmount);
    tokensSoldIco = tokensSoldIco.add(tokensAmount);
    tokensSoldTotal = tokensSoldTotal.add(tokensAmount);
    tokensRemainingIco = tokensRemainingIco.sub(tokensAmount);
    weiRaisedIco = weiRaisedIco.add(weiAmount);
    weiRaisedTotal = weiRaisedTotal.add(weiAmount);
    token.transferFromIco(msg.sender, tokensAmount);
    if (excessiveFunds > 0) {
        msg.sender.transfer(excessiveFunds);
    }
}

function manualRefund() whenIcoSaleHasEnded public {
    require(weiRaisedTotal < mincap);
    uint256 weiAmountTotal = investments[msg.sender];
    require(weiAmountTotal > 0);
    investments[msg.sender] = 0;
    uint256 weiAmountPreIco = investmentsPreIco[msg.sender];
    uint256 weiAmountIco = weiAmountTotal;
    if (weiAmountPreIco > 0) {
        investmentsPreIco[msg.sender] = 0;
        weiRaisedPreIco = weiRaisedPreIco.sub(weiAmountPreIco);
        weiAmountIco = weiAmountIco.sub(weiAmountPreIco);
    }
    if (weiAmountIco > 0) {
        weiRaisedIco = weiRaisedIco.sub(weiAmountIco);
        uint256 tokensIco = weiAmountIco.mul(exchangeRateIco);
        tokensSoldIco = tokensSoldIco.sub(tokensIco);
    }
    weiRaisedTotal = weiRaisedTotal.sub(weiAmountTotal);
    uint256 tokensAmount = token.balanceOf(msg.sender);
    tokensSoldTotal = tokensSoldTotal.sub(tokensAmount);
    token.burnFromAddress(msg.sender);
    msg.sender.transfer(weiAmountTotal);
}

function distributeTokensPreIco(uint256 _paginationCount) onlyOwner public {
    require(isTokenRateCalculated && !isTokensPreIcoDistributed);
    require(_paginationCount > 0);
    uint256 count = 0;
    for (uint256 i = distributionPreIcoCount; i < getPreIcoInvestorsCount(); i++) {
        if (count == _paginationCount) {
            break;
        }
        uint256 investment = getPreIcoInvestment(getPreIcoInvestor(i));
        uint256 tokensAmount = investment.mul(exchangeRatePreIco);
        tokensSoldTotal = tokensSoldTotal.add(tokensAmount);
        token.transferFromIco(getPreIcoInvestor(i), tokensAmount);
        count++;
    }
    distributionPreIcoCount = distributionPreIcoCount.add(count);
    if (distributionPreIcoCount == getPreIcoInvestorsCount()) {
        isTokensPreIcoDistributed = true;
    }
}

function burnUnsoldTokens() whenIcoSaleHasEnded onlyOwner public {
    require(tokensRemainingIco > 0);
    token.burnFromIco();
    tokensRemainingIco = 0;
}

function tokensOfOwner(address _owner) external view returns(uint256[]) {
    uint256 balance = balanceOf(_owner);
    if (balance == 0) {
        return new uint256[](0);
    } else {
        uint256[] memory result = new uint256[](balance);
        uint256 maxTokenId = totalSupply();
        uint256 idx = 0;
        uint256 tokenId;
        for (tokenId = 1; tokenId <= maxTokenId; tokenId++) {
            if (tokenIndexToOwner[tokenId] == _owner) {
                result[idx] = tokenId;
                idx++;
            }
        }
    }
    return result;
}

function snatchHero(uint256 _id) external payable whenNotPaused {
    require(now - tokens[_id].purchased <= snatch);
    uint256 pricerecalc = tokens[_id].price;
    require(pricerecalc <= msg.value);
    address previos = tokenIndexToOwner[_id];
    uint256 realPriceFee = msg.value * fee / 100;
    uint256 realPrice = msg.value - realPriceFee;
    uint256 newPriceRise = pricerecalc * 120 / 100;
    previos.transfer(realPrice);
    _transfer(previos, msg.sender, _id);
    tokens[_id].purchased = now;
    tokens[_id].price = newPriceRise;
}

