function() public payable isTgrLive isNotFrozenOnly noAnyReentrancy {
    require(whitelist.whitelist(msg.sender)); 
    require(tgrAmountCollected < tgrSettingsAmount); 
    require(msg.value >= tgrSettingsMinimalContribution);
    uint stage = block.number.sub(tgrStartBlock).div(tgrSettingsBlocksPerStage);
    require(stage < tgrSettingsMaxStages); 
    uint etherToRefund = 0;
    uint etherContributed = msg.value;
    uint currentPartContributor = tgrSettingsPartContributor.add(stage.mul(tgrSettingsPartContributorIncreasePerStage));
    uint allStakes = currentPartContributor.add(tgrSettingsPartProject).add(tgrSettingsPartFounders);
    uint remainsToContribute = (tgrSettingsAmount.sub(tgrAmountCollected)).mul(allStakes).div(tgrSettingsPartProject);
    if ((tgrSettingsAmount.sub(tgrAmountCollected)).mul(allStakes) % tgrSettingsPartProject != 0) {
        remainsToContribute = remainsToContribute + allStakes;
    }
    if (remainsToContribute < msg.value) {
        etherToRefund = msg.value.sub(remainsToContribute);
        etherContributed = remainsToContribute;
    }
    uint tokensProject = etherContributed.mul(tgrSettingsPartProject).div(allStakes);
    uint tokensFounders = etherContributed.mul(tgrSettingsPartFounders).div(allStakes);
    uint tokensContributor = etherContributed.sub(tokensProject).sub(tokensFounders);
    tgrAmountCollected = tgrAmountCollected.add(tokensProject);
    tgrContributedAmount = tgrContributedAmount.add(etherContributed);
    _mint(tokensProject, tokensFounders, tokensContributor);
    msg.sender.transfer(etherToRefund);
}

function burn(uint _amount) public isNotFrozenOnly noAnyReentrancy returns(bool _success) {
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    balances[burnAddress] = balances[burnAddress].add(_amount);
    totalSupply = totalSupply.sub(_amount);
    msg.sender.transfer(_amount);
    emit Transfer(msg.sender, burnAddress, _amount);
    emit Burn(burnAddress, _amount);
    return true;
}

function isInStage1() view public returns(bool) {
    return now <= bonusClosingTime0 && now >= openingTime;
}

constructor(uint256 _openingTime, uint256 _closingTime) public {
    require(_openingTime >= block.timestamp);
    require(_closingTime >= _openingTime);
    openingTime = _openingTime;
    closingTime = _closingTime;
}

function isInStage2() view public returns(bool) {
    return now <= bonusClosingTime1 && now > bonusClosingTime0;
}

function hasStarted() view public returns(bool) {
    return now >= openingTime;
}

function _addBonus(uint256 _tokenAmount) internal view returns(uint256) {
    if (bonusClosingTime0 >= now) {
        _tokenAmount = _tokenAmount.mul(100 + bonusRateInPercent0).div(100);
    } else if (bonusClosingTime1 >= now) {
        _tokenAmount = _tokenAmount.mul(100 + bonusRateInPercent1).div(100);
    }
    require(_tokenAmount <= token.balanceOf(address(this)));
    return _tokenAmount;
}

function setExchangeRateETHToUSD(uint256 _rate, uint256 _decimals) onlyOwner public {
    require(uint256(strayToken.decimals()).add(2) >= _decimals.add(18));
    exchangeRateETHToUSD = _rate;
    decimalsETHToUSD = _decimals;
    rate = _rate.mul(exchangeRateUSDToToken);
    if (uint256(strayToken.decimals()) >= _decimals.add(18)) {
        rate = rate.mul(10 ** (uint256(strayToken.decimals()).sub(18).sub(_decimals)));
    } else {
        rate = rate.div(10 ** (_decimals.add(18).sub(uint256(strayToken.decimals()))));
    }
    mininumContributeWei = mininumPurchaseTokenQuantity.div(rate);
    if (mininumContributeWei * rate < mininumPurchaseTokenQuantity)
        mininumContributeWei += 1;
    emit RateUpdated(rate, mininumContributeWei);
}

function permit(
    address holder,
    address spender,
    uint256 nonce,
    uint256 expiry,
    bool allowed,
    uint8 v,
    bytes32 r,
    bytes32 s
) external {
    bytes32 digest =
        keccak256(abi.encodePacked(
            "\x19\x01",
            DOMAIN_SEPARATOR,
            keccak256(abi.encode(PERMIT_TYPEHASH,
                holder,
                spender,
                nonce,
                expiry,
                allowed))
        ));
    require(holder != address(0), "Coin/invalid-address-0");
    require(holder == ecrecover(digest, v, r, s), "Coin/invalid-permit");
    require(expiry == 0 || now <= expiry, "Coin/permit-expired");
    require(nonce == nonces[holder]++, "Coin/invalid-nonce");
    uint256 wad = allowed ? uint256(-1) : 0;
    allowance[holder][spender] = wad;
    emit Approval(holder, spender, wad);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    last_useVersion = "Ver 1";
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    uint256 LockhasTime = Locked_list[sender].releaseTime;
    uint256 LockhasMax = Locked_list[sender].lockedTokencnt;
    if (block.timestamp < LockhasTime) {
        uint256 OK1 = _balances[sender].sub(LockhasMax, "ERC20: the amount to unlock is bigger then locked token count");
        require(OK1 >= amount, "Your Wallet has time lock");
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function end() public {
    require(!ended, "end already called");
    require(lastBidTime != 0, "no bids");
    require(block.timestamp >= lastBidTime.add(bidLength) || block.timestamp >= startBidTime.add(auctionLength), "Auction live");
    IERC1155(token).safeTransferFrom(address(this), winning, id, 1, new bytes(0x0));
    uint256 balance = address(this).balance;
    uint256 hausFee = balance.div(20).mul(3);
    haus.transfer(hausFee);
    seller.transfer(address(this).balance);
    ended = true;
    emit Won(winning, lastBid);
}

function bid() public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= startBidTime, "Auction not started");
    require(block.timestamp < startBidTime.add(auctionLength), "Auction ended");
    require(msg.value >= lastBid.mul(105).div(100), "Bid too small");
    if (lastBidTime != 0) {
        require(block.timestamp < lastBidTime.add(bidLength), "Auction ended");
        winning.transfer(lastBid);
    }
    lastBid = msg.value;
    winning = msg.sender;
    lastBidTime = block.timestamp;
    emit Bid(msg.sender, msg.value);
}

function pull() public {
    require(!ended, "end already called");
    require(lastBidTime == 0, "There were bids");
    require(block.timestamp >= startBidTime.add(auctionLength), "Auction live");
    IERC1155(token).safeTransferFrom(address(this), seller, id, 1, new bytes(0x0));
    ended = true;
}

function live() external view returns(bool) {
    if (block.timestamp < lastBidTime.add(bidLength) && block.timestamp < startBidTime.add(auctionLength)) {
        return true;
    }
    return false;
}

function checkCooldown(address _allower, address _allowee) external constant returns(uint256 remaining) {
    if (cooldown[_allower][_allowee] > now) {
        return (cooldown[_allower][_allowee] - now);
    } else {
        return 0;
    }
}

function transferFrom(address _from, address _to, uint256 _value) external requireThaw userNotPlaying(_to) {
    require(cooldown[_from][_to] <= now);
    var _allowance = allowed[_from][_to];
    if (_from == selfAddress) {
        monthlyLimit[_to] = safeSub(monthlyLimit[_to], _value);
    }
    balances[_to] = balances[_to] + _value;
    balances[_from] = safeSub(balances[_from], _value);
    allowed[_from][_to] = safeSub(_allowance, _value);
    addUser(_to);
    Transfer(_from, _to, _value);
}

function splitProfits() external {
    require(splitInService);
    uint i;
    if (!isFrozen) {
        require(now >= relativeDateSave);
        assetFreeze();
        require(balances[selfAddress] > 30000000000000);
        relativeDateSave = now + 30 days;
        currentProfits = ((balances[selfAddress] - 30000000000000) / 10) * 7;
        amountInCirculation = safeSub(300000000000000, balances[selfAddress]);
        currentIteration = 0;
        actualProfitSplit = 0;
    } else {
        for (i = currentIteration; i < users.length; i++) {
            monthlyLimit[users[i]] = 5000000000000;
            if (msg.gas < 240000) {
                currentIteration = i;
                break;
            }
            if (allowed[selfAddress][users[i]] == 0) {
                checkSplitEnd(i);
                continue;
            } else if ((balances[users[i]] / allowed[selfAddress][users[i]]) < 19) {
                checkSplitEnd(i);
                continue;
            }
            actualProfitSplit += (balances[users[i]] * currentProfits) / amountInCirculation;
            balances[users[i]] += (balances[users[i]] * currentProfits) / amountInCirculation;
            checkSplitEnd(i);
            Transfer(selfAddress, users[i], (balances[users[i]] / amountInCirculation) * currentProfits);
        }
    }
}

function ICOSplit() external isAdmin oneTime {
    uint i;
    if (!isFrozen) {
        require((relativeDateSave - now) >= (relativeDateSave - 150 days));
        assetFreeze();
        require(balances[selfAddress] > 50000000000000);
        currentProfits = ((balances[selfAddress] - 50000000000000) / 10) * 7;
        amountInCirculation = safeSub(300000000000000, balances[selfAddress]);
        currentIteration = 0;
        actualProfitSplit = 0;
    } else {
        for (i = currentIteration; i < users.length; i++) {
            if (msg.gas < 240000) {
                currentIteration = i;
                break;
            }
            actualProfitSplit += (balances[users[i]] * currentProfits) / amountInCirculation;
            balances[users[i]] += (balances[users[i]] * currentProfits) / amountInCirculation;
            if (i == users.length - 1) {
                assetThaw();
                balances[selfAddress] = balances[selfAddress] - actualProfitSplit;
                hasICORun = true;
            }
            Transfer(selfAddress, users[i], (balances[users[i]] / amountInCirculation) * currentProfits);
        }
    }
}

