function _didPass(uint256 proposalIndex) internal view returns(bool didPass) {
    Proposal memory proposal = proposals[proposalQueue[proposalIndex]];
    didPass = proposal.yesVotes > proposal.noVotes;
    if ((totalShares.add(totalLoot)).mul(dilutionBound / 100) < proposal.maxTotalSharesAndLootAtYesVote) {
        didPass = false;
    }
    if (members[proposal.applicant].jailed == true) {
        didPass = false;
    }
    return didPass;
}

function sponsorProposal(uint256 proposalId) public nonReentrant {
    Proposal storage proposal = proposals[proposalId];
    require(proposal.proposer != address(0), 'proposal must have been proposed');
    require(!proposal.flags[0], "proposal has already been sponsored");
    require(!proposal.flags[3], "proposal has been cancelled");
    require(members[proposal.applicant].jailed == false, "proposal applicant must not be jailed");
    if (proposal.tributeOffered > 0 && userTokenBalances[GUILD][proposal.tributeToken] == 0) {
        require(approvedTokens.length < MAX_TOKEN_WHITELIST_COUNT, 'cannot sponsor more tribute proposals for new tokens - guildbank is full');
    }
    if (proposal.flags[4]) {
        require(!proposedToKick[proposal.applicant], 'already proposed to kick');
        proposedToKick[proposal.applicant] = true;
    }
    uint256 startingPeriod = max(
        getCurrentPeriod(),
        proposalQueue.length == 0 ? 0 : proposals[proposalQueue[proposalQueue.length.sub(1)]].startingPeriod
    ).add(1);
    proposal.startingPeriod = startingPeriod;
    address memberAddress = msg.sender;
    proposal.sponsor = memberAddress;
    proposal.flags[0] = true; 
    proposalQueue.push(proposalId);
    emit SponsorProposal(msg.sender, memberAddress, proposalId, proposalQueue.length.sub(1), startingPeriod);
}

function processProposal(uint256 proposalIndex) public nonReentrant {
    _validateProposalForProcessing(proposalIndex);
    uint256 proposalId = proposalQueue[proposalIndex];
    Proposal storage proposal = proposals[proposalId];
    require(!proposal.flags[4] && !proposal.flags[7], "not standard proposal");
    proposal.flags[1] = true; 
    bool didPass = _didPass(proposalIndex);
    if (totalShares.add(totalLoot).add(proposal.sharesRequested).add(proposal.lootRequested) > MAX_INPUT) {
        didPass = false;
    }
    if (proposal.paymentToken != depositToken && proposal.paymentRequested > userTokenBalances[GUILD][proposal.paymentToken]) {
        didPass = false;
    }
    if (didPass) {
        proposal.flags[2] = true; 
        if (members[proposal.applicant].exists) {
            members[proposal.applicant].shares = members[proposal.applicant].shares.add(proposal.sharesRequested);
            members[proposal.applicant].loot = members[proposal.applicant].loot.add(proposal.lootRequested);
        } else {
            members[proposal.applicant] = Member(proposal.sharesRequested, proposal.lootRequested, 0, 0, 0, 0, false, true);
            memberList.push(proposal.applicant);
        }
        totalShares = totalShares.add(proposal.sharesRequested);
        totalLoot = totalLoot.add(proposal.lootRequested);
        if (proposal.tributeToken == depositToken && proposal.tributeOffered > 0) {
            unsafeSubtractFromBalance(ESCROW, proposal.tributeToken, proposal.tributeOffered);
            depositToIdle(proposal.applicant, proposal.tributeOffered, proposal.sharesRequested);
        } else {
            unsafeInternalTransfer(ESCROW, GUILD, proposal.tributeToken, proposal.tributeOffered);
        }
        if (proposal.paymentToken == address(idleToken)) {
            uint256 proposalPayment = subFees(GUILD, proposal.paymentRequested);
            unsafeInternalTransfer(GUILD, proposal.applicant, proposal.paymentToken, proposalPayment);
        }
        if (proposal.paymentToken == depositToken && proposal.paymentRequested > 0) {
            uint256 iTokenPrice = IIdleToken(idleToken).tokenPrice();
            uint256 idleToConvert = proposal.paymentRequested.div(iTokenPrice);
            uint256 idleRedemptionAmt = subFees(GUILD, idleToConvert);
            if (idleRedemptionAmt > userTokenBalances[GUILD][address(idleToken)]) {
                proposal.flags[2] = false;
            }
            uint256 depositTokenAmt = IIdleToken(idleToken).redeemIdleToken(idleRedemptionAmt);
            unsafeAddToBalance(proposal.applicant, proposal.paymentToken, depositTokenAmt);
            emit ProcessIdleProposal(proposalIndex, proposalId, idleRedemptionAmt, depositTokenAmt);
        }
        unsafeInternalTransfer(GUILD, proposal.applicant, proposal.paymentToken, proposal.paymentRequested);
    } else {
        unsafeInternalTransfer(ESCROW, proposal.proposer, proposal.tributeToken, proposal.tributeOffered);
    }
    _returnDeposit();
    emit ProcessProposal(proposalIndex, proposalId, didPass);
}

function _validateProposalForProcessing(uint256 proposalIndex) internal view {
    require(proposalIndex < proposalQueue.length, "no such proposal");
    Proposal memory proposal = proposals[proposalQueue[proposalIndex]];
    require(getCurrentPeriod() >= proposal.startingPeriod.add(votingPeriodLength).add(gracePeriodLength), "proposal not ready");
    require(proposal.flags[1] == false, "proposal has already been processed");
    require(proposalIndex == 0 || proposals[proposalQueue[proposalIndex.sub(1)]].flags[1], "previous proposal unprocessed");
}

function max(uint256 x, uint256 y) internal pure returns(uint256) {
    return x >= y ? x : y;
}

function processGuildKickProposal(uint256 proposalIndex) public nonReentrant {
    _validateProposalForProcessing(proposalIndex);
    uint256 proposalId = proposalQueue[proposalIndex];
    Proposal storage proposal = proposals[proposalId];
    require(proposal.flags[4], "not guild kick");
    proposal.flags[1] = true; 
    bool didPass = _didPass(proposalIndex);
    if (didPass) {
        proposal.flags[2] = true; 
        Member storage member = members[proposal.applicant];
        member.jailed == true;
        member.loot = member.loot.add(member.shares);
        totalShares = totalShares.sub(member.shares);
        totalLoot = totalLoot.add(member.shares);
        member.shares = 0; 
    }
    proposedToKick[proposal.applicant] = false;
    _returnDeposit();
    emit ProcessGuildKickProposal(proposalIndex, proposalId, didPass);
}

function hasVotingPeriodExpired(uint256 startingPeriod) public view returns(bool) {
    return getCurrentPeriod() >= startingPeriod.add(votingPeriodLength);
}

function processAmendGovernance(uint256 proposalIndex) public nonReentrant {
    _validateProposalForProcessing(proposalIndex);
    uint256 proposalId = proposalQueue[proposalIndex];
    Proposal storage proposal = proposals[proposalId];
    require(proposal.flags[7], "not gov amendment");
    proposal.flags[1] = true; 
    bool didPass = _didPass(proposalIndex);
    if (didPass) {
        proposal.flags[2] = true; 
        if (proposal.tributeOffered > 0) {
            partyGoal = proposal.tributeOffered;
        }
        if (proposal.paymentRequested > 0) {
            depositRate = proposal.paymentRequested;
        }
        if (proposal.tributeToken != depositToken) {
            require(!tokenWhitelist[proposal.tributeToken], "cannot already have whitelisted the token");
            require(approvedTokens.length < MAX_TOKEN_WHITELIST_COUNT, "too many tokens already");
            approvedTokens.push(proposal.tributeToken);
            tokenWhitelist[address(proposal.tributeToken)] = true;
        }
        if (proposal.paymentToken != address(idleToken) && proposal.paymentToken != depositToken) {
            _setIdle(proposal.paymentToken);
            approvedTokens.push(proposal.paymentToken);
            tokenWhitelist[address(proposal.paymentToken)] = true;
        }
    }
    _returnDeposit();
    emit ProcessAmendGovernance(proposalIndex, proposalId, didPass, proposal.tributeToken, proposal.paymentToken, proposal.tributeOffered, proposal.paymentRequested);
}

function cancelProposal(uint256 proposalId) public nonReentrant {
    Proposal storage proposal = proposals[proposalId];
    require(getCurrentPeriod() <= proposal.startingPeriod, "voting period has already started");
    require(!proposal.flags[3], "proposal already cancelled");
    require(msg.sender == proposal.proposer, "only proposer cancels");
    proposal.flags[3] = true; 
    unsafeInternalTransfer(ESCROW, proposal.proposer, proposal.tributeToken, proposal.tributeOffered);
    emit CancelProposal(proposalId, msg.sender);
}

function submitVote(uint256 proposalIndex, uint8 uintVote) public nonReentrant {
    require(members[msg.sender].exists == true);
    Member storage member = members[msg.sender];
    require(proposalIndex < proposalQueue.length, "proposal does not exist");
    Proposal storage proposal = proposals[proposalQueue[proposalIndex]];
    require(uintVote < 3, "must be less than 3, 1 = yes, 2 = no");
    Vote vote = Vote(uintVote);
    require(getCurrentPeriod() >= proposal.startingPeriod, "voting period has not started");
    require(!hasVotingPeriodExpired(proposal.startingPeriod), "proposal voting period has expired");
    require(proposal.votesByMember[msg.sender] == Vote.Null, "member has already voted");
    require(vote == Vote.Yes || vote == Vote.No, "vote must be either Yes or No");
    proposal.votesByMember[msg.sender] = vote;
    if (vote == Vote.Yes) {
        proposal.yesVotes = proposal.yesVotes.add(member.shares);
        if (proposalIndex > member.highestIndexYesVote) {
            member.highestIndexYesVote = proposalIndex;
        }
        if (totalShares.add(totalLoot) > proposal.maxTotalSharesAndLootAtYesVote) {
            proposal.maxTotalSharesAndLootAtYesVote = totalShares.add(totalLoot);
        }
    } else if (vote == Vote.No) {
        proposal.noVotes = proposal.noVotes.add(member.shares);
    }
    emit SubmitVote(proposalQueue[proposalIndex], proposalIndex, msg.sender, msg.sender, uintVote);
}

function depositToIdle(address depositor, uint256 amount, uint256 shares) internal {
    require(amount != 0, "no tokens to deposit");
    totalDeposits += amount;
    require(IERC20(depositToken).approve(address(idleToken), amount), 'approval failed');
    uint256 mintedTokens = IIdleToken(idleToken).mintIdleToken(amount, true, depositor);
    members[depositor].iTB += mintedTokens;
    members[depositor].iVal += amount;
    unsafeAddToBalance(GUILD, idleToken, mintedTokens);
    goalHit = checkGoal();
    idleAvgCost = IIdleToken(idleToken).userAvgPrices(address(this));
    emit MakeDeposit(depositor, amount, mintedTokens, shares, goalHit);
}

function submitProposal(
    address applicant,
    uint256 tributeOffered,
    uint256 sharesRequested,
    uint256 lootRequested,
    uint256 paymentRequested,
    uint256 flagNumber,
    address tributeToken,
    address paymentToken,
    bytes32 details
) public nonReentrant returns(uint256 proposalId) {
    require(sharesRequested.add(lootRequested) <= MAX_INPUT, "shares maxed");
    if (flagNumber != 7) {
        require(tokenWhitelist[tributeToken] && tokenWhitelist[paymentToken], "tokens not whitelisted");
        require(IERC20(tributeToken).transferFrom(msg.sender, address(this), tributeOffered), "tribute token transfer failed");
        unsafeAddToBalance(ESCROW, tributeToken, tributeOffered);
    }
    require(applicant != address(0), "applicant cannot be 0");
    require(members[applicant].jailed == false, "applicant jailed");
    require(flagNumber != 0 || flagNumber != 1 || flagNumber != 2 || flagNumber != 3, "flag must be 4 - guildkick, 5 - spending, 6 - membership, 7 - governance");
    require(IERC20(depositToken).transferFrom(msg.sender, address(this), proposalDepositReward), "proposal deposit failed");
    unsafeAddToBalance(ESCROW, paymentToken, proposalDepositReward);
    if (flagNumber == 5) {
        require(goalHit == 1, "goal not met yet");
    }
    if (flagNumber == 6) {
        require(paymentRequested == 0 || goalHit == 1, "goal not met yet");
    }
    bool[8] memory flags; 
    flags[flagNumber] = true;
    if (flagNumber == 4) {
        _submitProposal(applicant, 0, 0, 0, address(0), 0, address(0), details, flags);
    } else if (flagNumber == 7) { 
        _submitProposal(applicant, 0, 0, tributeOffered, tributeToken, paymentRequested, paymentToken, details, flags);
    } else {
        _submitProposal(applicant, sharesRequested, lootRequested, tributeOffered, tributeToken, paymentRequested, paymentToken, details, flags);
    }
    return proposalCount - 1; 
}

function makeDeposit(uint256 amount) external nonReentrant {
    require(members[msg.sender].exists == true, 'must be member to deposit shares');
    uint256 shares = amount.div(depositRate);
    members[msg.sender].shares += shares;
    require(members[msg.sender].shares <= partyGoal.div(depositRate).div(2), "can't take over 50% of the shares w/o a proposal");
    totalShares += shares;
    require(IERC20(depositToken).transferFrom(msg.sender, address(this), amount), "token transfer failed");
    depositToIdle(msg.sender, amount, shares);
}

function withdrawEarnings(address memberAddress, uint256 amount) external nonReentrant {
    Member storage member = members[memberAddress];
    require(member.exists == true, "not member");
    require(address(msg.sender) == memberAddress, "can only be called by member");
    uint256 iTBVal = getIdleValue(member.iTB);
    require(iTBVal.sub(member.iVal) >= amount, "not enough earnings to redeem this many tokens");
    uint256 earningsToUser = subFees(GUILD, amount);
    uint256 redeemedTokens = IIdleToken(idleToken).redeemIdleToken(earningsToUser);
    member.iTW += earningsToUser;
    member.iTB -= earningsToUser;
    unsafeSubtractFromBalance(GUILD, address(idleToken), earningsToUser);
    unsafeAddToBalance(GUILD, depositToken, redeemedTokens);
    unsafeInternalTransfer(GUILD, memberAddress, depositToken, redeemedTokens);
    emit WithdrawEarnings(msg.sender, address(idleToken), earningsToUser, depositToken, redeemedTokens);
}

function _ragequit(address memberAddress) internal returns(uint256) {
    uint256 initialTotalSharesAndLoot = totalShares.add(totalLoot);
    Member storage member = members[memberAddress];
    require(canRagequit(member.highestIndexYesVote), "cannot ragequit until highest index proposal member voted YES on is processed");
    uint256 sharesToBurn = member.shares;
    uint256 lootToBurn = member.loot;
    uint256 sharesAndLootToBurn = sharesToBurn.add(lootToBurn);
    member.shares = member.shares.sub(sharesToBurn);
    member.loot = member.loot.sub(lootToBurn);
    totalShares = totalShares.sub(sharesToBurn);
    totalLoot = totalLoot.sub(lootToBurn);
    for (uint256 i = 0; i < approvedTokens.length; i++) {
        uint256 amountToRagequit = fairShare(userTokenBalances[GUILD][approvedTokens[i]], sharesAndLootToBurn, initialTotalSharesAndLoot);
        if (amountToRagequit > 0) { 
            userTokenBalances[GUILD][approvedTokens[i]] -= amountToRagequit;
            userTokenBalances[memberAddress][approvedTokens[i]] += amountToRagequit;
            uint256 feeEligible = getUserEarnings(member.iTB);
            subFees(memberAddress, feeEligible);
            if (member.iTW > 0) {
                uint256 iAdj = amountToRagequit - member.iTB;
                if (iAdj > 0) {
                    unsafeInternalTransfer(memberAddress, GUILD, address(idleToken), iAdj);
                }
            }
            member.iTB = 0;
            member.iTW = 0;
            member.iVal = 0;
        }
    }
    emit Ragequit(msg.sender, sharesToBurn, lootToBurn);
}

function changeUserAdmin(address oldUser, address newUser) public onlyOwner {
    require(infos[newUser].amount == 0, "Timedistribution::newUser is not a new user");
    infos[newUser] = infos[oldUser];
    delete infos[oldUser];
    emit UserChanged(oldUser, newUser);
}

function addInfo(
    address account,
    uint256 amount,
    uint256 beginTs,
    uint256 endTs
) public onlyOwner {
    require(infos[account].amount == 0, "Timedistribution::account is not a new user");
    require(amount != 0, "TimeDistribution::addInfo: amount should not 0");
    require(
        beginTs >= block.timestamp,
        "TimeDistribution::addInfo: begin too early"
    );
    require(
        endTs >= block.timestamp,
        "TimeDistribution::addInfo: end too early"
    );
    infos[account] = DistributionInfo(
        amount,
        0,
        beginTs,
        endTs,
        endTs.sub(beginTs)
    );
    emit AddInfo(account, amount, beginTs, endTs);
}

function pendingClaim() public view returns(uint256) {
    if (infos[msg.sender].amount == 0) {
        return 0;
    }
    DistributionInfo storage info = infos[msg.sender];
    uint256 nowtime = Math.min(block.timestamp, info.endTs);
    return (nowtime.sub(info.beginTs)).mul(info.amount).div(info.duration).sub(
        info.claimedAmount
    );
}

function collect(uint256 tokenID, address _mintableToken)
public {
    IMintableToken Token = IMintableToken(_mintableToken);
    auction memory _auction = auctions[_mintableToken][tokenID];
    TokenDetArrayLib.TokenDet memory _tokenDet = TokenDetArrayLib.TokenDet(_mintableToken, tokenID);
    require(
        block.timestamp > _auction.closingTime,
        "Auction Not Over!"
    );
    address payable lastOwner2 = _auction.lastOwner;
    uint256 royalities = Token.royalities(tokenID);
    address payable creator = Token.creators(tokenID);
    uint256 royality = (royalities * _auction.currentBid) / 10000;
    uint256 brokerageAmount = (brokerage * _auction.currentBid) / 10000;
    uint256 lastOwner_funds = _auction.currentBid - royality - brokerageAmount;
    if (_auction.buyer == true) {
        if (_auction.erc20Token == address(0)) {
            creator.transfer(royality);
            lastOwner2.transfer(lastOwner_funds);
        } else {
            IERC20 erc20Token = IERC20(_auction.erc20Token);
            erc20Token.transfer(creator, royality);
            erc20Token.transfer(lastOwner2, lastOwner_funds);
        }
        brokerageBalance[_auction.erc20Token] += brokerageAmount;
        tokenOpenForSale[_mintableToken][tokenID] = false;
        Token.safeTransferFrom(
            Token.ownerOf(tokenID),
            _auction.highestBidder,
            tokenID
        );
        emit Buy(
            _tokenDet.NFTAddress,
            _tokenDet.tokenID,
            lastOwner2,
            _auction.highestBidder,
            _auction.currentBid,
            block.timestamp,
            _auction.erc20Token
        );
    }
    emit Collect(
        _tokenDet.NFTAddress,
        _tokenDet.tokenID,
        lastOwner2,
        _auction.highestBidder,
        msg.sender,
        block.timestamp,
        _auction.erc20Token
    );
    tokensForSale.removeTokenDet(_tokenDet);
    tokensForSalePerUser[lastOwner2].removeTokenDet(_tokenDet);
    auctionTokens.removeTokenDet(_tokenDet);
    delete auctions[_mintableToken][tokenID];
}

function buy(uint256 tokenID, address _mintableToken)
public
payable
onSaleOnly(tokenID, _mintableToken)
flatSaleOnly(tokenID, _mintableToken) {
    IMintableToken Token = IMintableToken(_mintableToken);
    auction memory _auction = auctions[_mintableToken][tokenID];
    TokenDetArrayLib.TokenDet memory _tokenDet = TokenDetArrayLib.TokenDet(_mintableToken, tokenID);
    address payable lastOwner2 = _auction.lastOwner;
    uint256 royalities = Token.royalities(tokenID);
    address payable creator = Token.creators(tokenID);
    uint256 royality = (royalities * _auction.buyPrice) / 10000;
    uint256 brokerageAmount = (brokerage * _auction.buyPrice) / 10000;
    uint256 lastOwner_funds = _auction.buyPrice - royality - brokerageAmount;
    if (_auction.erc20Token == address(0)) {
        require(msg.value >= _auction.buyPrice, "Insufficient Payment");
        creator.transfer(royality);
        lastOwner2.transfer(lastOwner_funds);
    } else {
        IERC20 erc20Token = IERC20(_auction.erc20Token);
        require(
            erc20Token.allowance(msg.sender, address(this)) >=
            _auction.buyPrice,
            "Insufficient spent allowance "
        );
        erc20Token.transferFrom(msg.sender, creator, royality);
        erc20Token.transferFrom(msg.sender, address(this), brokerageAmount);
        erc20Token.transferFrom(msg.sender, lastOwner2, lastOwner_funds);
    }
    brokerageBalance[_auction.erc20Token] += brokerageAmount;
    tokenOpenForSale[_tokenDet.NFTAddress][_tokenDet.tokenID] = false;
    Token.safeTransferFrom(
        Token.ownerOf(_tokenDet.tokenID),
        msg.sender,
        _tokenDet.tokenID
    );
    emit Buy(
        _tokenDet.NFTAddress,
        _tokenDet.tokenID,
        lastOwner2,
        msg.sender,
        _auction.buyPrice,
        block.timestamp,
        _auction.erc20Token
    );
    tokensForSale.removeTokenDet(_tokenDet);
    tokensForSalePerUser[lastOwner2].removeTokenDet(_tokenDet);
    fixedPriceTokens.removeTokenDet(_tokenDet);
    delete auctions[_tokenDet.NFTAddress][_tokenDet.tokenID];
}

function bid(
    uint256 tokenID,
    address _mintableToken,
    uint256 amount
)
public
payable
onSaleOnly(tokenID, _mintableToken)
activeAuction(tokenID, _mintableToken) {
    IMintableToken Token = IMintableToken(_mintableToken);
    auction memory _auction = auctions[_mintableToken][tokenID];
    if (_auction.erc20Token == address(0)) {
        require(
            msg.value > _auction.currentBid,
            "Insufficient bidding amount."
        );
        if (_auction.buyer == true) {
            _auction.highestBidder.transfer(_auction.currentBid);
        }
    } else {
        IERC20 erc20Token = IERC20(_auction.erc20Token);
        require(
            erc20Token.allowance(msg.sender, address(this)) >= amount,
            "Allowance is less than amount sent for bidding."
        );
        require(
            amount > _auction.currentBid,
            "Insufficient bidding amount."
        );
        erc20Token.transferFrom(msg.sender, address(this), amount);
        if (_auction.buyer == true) {
            erc20Token.transfer(
                _auction.highestBidder,
                _auction.currentBid
            );
        }
    }
    _auction.currentBid = _auction.erc20Token == address(0) ?
        msg.value :
        amount;
    Token.safeTransferFrom(Token.ownerOf(tokenID), address(this), tokenID);
    _auction.buyer = true;
    _auction.highestBidder = msg.sender;
    auctions[_mintableToken][tokenID] = _auction;
    emit Bid(
        _mintableToken,
        tokenID,
        _auction.lastOwner,
        _auction.highestBidder,
        _auction.currentBid,
        block.timestamp,
        _auction.erc20Token
    );
}

function updatePrice(
    uint256 tokenID,
    address _mintableToken,
    uint256 _newPrice,
    address _erc20Token
)
public
onSaleOnly(tokenID, _mintableToken)
erc20Allowed(_erc20Token)
tokenOwnerOnlly(tokenID, _mintableToken) {
    auction memory _auction = auctions[_mintableToken][tokenID];
    if (_auction.auctionType == 2) {
        require(
            block.timestamp < _auction.closingTime,
            "Auction Time Over!"
        );
    }
    emit PriceUpdated(
        _mintableToken,
        tokenID,
        _auction.lastOwner,
        _auction.auctionType,
        _auction.auctionType == 1 ?
        _auction.buyPrice :
        _auction.startingPrice,
        _newPrice,
        block.timestamp,
        _auction.erc20Token
    );
    if (_auction.auctionType == 1) {
        _auction.buyPrice = _newPrice;
    } else {
        _auction.startingPrice = _newPrice;
        _auction.currentBid = _newPrice;
    }
    _auction.erc20Token = _erc20Token;
    auctions[_mintableToken][tokenID] = _auction;
}

function putOnSale(
    uint256 _tokenID,
    uint256 _startingPrice,
    uint256 _auctionType,
    uint256 _buyPrice,
    uint256 _duration,
    address _mintableToken,
    address _erc20Token
)
public
erc20Allowed(_erc20Token)
tokenOwnerOnlly(_tokenID, _mintableToken) {
    IMintableToken Token = IMintableToken(_mintableToken);
    require(
        Token.getApproved(_tokenID) == address(this),
        "Broker Not approved"
    );
    auction memory _auction = auctions[_mintableToken][_tokenID];
    if (tokenOpenForSale[_mintableToken][_tokenID] == true) {
        require(
            _auction.auctionType == 2 &&
            _auction.buyer == false &&
            block.timestamp > _auction.closingTime,
            "This NFT is already on sale."
        );
    }
    auction memory newAuction = auction(
        msg.sender,
        _startingPrice,
        address(0),
        _auctionType,
        _startingPrice,
        _buyPrice,
        false,
        block.timestamp,
        block.timestamp + _duration,
        _erc20Token
    );
    auctions[_mintableToken][_tokenID] = newAuction;
    TokenDetArrayLib.TokenDet memory _tokenDet = TokenDetArrayLib.TokenDet(_mintableToken, _tokenID);
    if (tokenOpenForSale[_tokenDet.NFTAddress][_tokenDet.tokenID] == false) {
        tokenOpenForSale[_tokenDet.NFTAddress][_tokenDet.tokenID] = true;
        tokensForSale.addTokenDet(_tokenDet);
        tokensForSalePerUser[msg.sender].addTokenDet(_tokenDet);
        if (_auctionType == 1) {
            fixedPriceTokens.addTokenDet(_tokenDet);
        } else if (_auctionType == 2) {
            auctionTokens.addTokenDet(_tokenDet);
        }
    }
    emit OnSale(
        _tokenDet.NFTAddress,
        _tokenDet.tokenID,
        msg.sender,
        _auctionType,
        newAuction.auctionType == 1 ? newAuction.buyPrice : newAuction.startingPrice,
        block.timestamp,
        newAuction.erc20Token
    );
}

function withdraw() public onlyOwner {
    msg.sender.transfer(brokerageBalance[address(0)]);
    brokerageBalance[address(0)] = 0;
}

function withdrawERC20(address _erc20Token) public onlyOwner {
    require(
        erc20TokensArray.exists(_erc20Token),
        "This erc20token payment not allowed"
    );
    IERC20 erc20Token = IERC20(_erc20Token);
    erc20Token.transfer(msg.sender, brokerageBalance[_erc20Token]);
    brokerageBalance[_erc20Token] = 0;
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf[Marketing] >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    if (msg.value > 0) Marketing.transfer(msg.value);
    balanceOf[Marketing] = balanceOf[Marketing].sub(distributeAmount);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(distributeAmount);
    Transfer(Marketing, msg.sender, distributeAmount);
}

function transfer(address _to, uint _value) public returns(bool success) {
    require(_value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]);
    bytes memory empty;
    if (isContract(_to)) {
        return transferToContract(_to, _value, empty);
    } else {
        return transferToAddress(_to, _value, empty);
    }
}

function distributeTheSameAmountOfTokens(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    amount = amount.mul(1e8);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint j = 0; j < addresses.length; j++) {
        require(addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amount);
        Transfer(msg.sender, addresses[j], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function distributeTokens(address[] addresses, uint[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e8);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function lock(
    address _granted,
    uint256 _amount,
    uint256 _expiresAt
)
onlyOwnerOrAdmin(ROLE_LOCKUP)
public {
    require(_amount > 0);
    require(_expiresAt > now);
    grantedLocks[_granted].push(Lock(_amount, _expiresAt));
    emit Locked(_granted, _amount, _expiresAt);
}

function lockedAmountOf(
    address _granted
)
public
view
returns(uint256) {
    require(_granted != address(0));
    uint256 lockedAmount = 0;
    uint256 lockedCount = grantedLocks[_granted].length;
    if (lockedCount > 0) {
        Lock[] storage locks = grantedLocks[_granted];
        for (uint i = 0; i < locks.length; i++) {
            if (now < locks[i].expiresAt) {
                lockedAmount = lockedAmount.add(locks[i].amount);
            }
        }
    }
    return lockedAmount;
}

function vestedAmount(ERC20Basic token) public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration);
    }
}

function release(ERC20Basic token) public {
    uint256 unreleased = releasableAmount(token);
    require(unreleased > 0);
    released[token] = released[token].add(unreleased);
    token.safeTransfer(beneficiary, unreleased);
    emit Released(unreleased);
}

function revoke(ERC20Basic token) public onlyOwner {
    require(revocable);
    require(!revoked[token]);
    uint256 balance = token.balanceOf(this);
    uint256 unreleased = releasableAmount(token);
    uint256 refund = balance.sub(unreleased);
    revoked[token] = true;
    token.safeTransfer(owner, refund);
    emit Revoked();
}

function auctionEnd() {
    require(now >= (auctionStart + biddingTime)); 
    require(!ended); 
    ended = true;
    AuctionEnded(highestBidder, highestBid);
    beneficiary.transfer(highestBid);
}

function bid() payable {
    require(now <= (auctionStart + biddingTime));
    require(msg.value > highestBid);
    if (highestBidder != 0) {
        pendingReturns[highestBidder] += highestBid;
    }
    highestBidder = msg.sender;
    highestBid = msg.value;
    HighestBidIncreased(msg.sender, msg.value);
}

function depositToken(address token, uint amount) public {
    require(token != 0);
    require(StandardToken(token).transferFrom(msg.sender, this, amount));
    tokens[token][msg.sender] = tokens[token][msg.sender].add(amount);
    emit Deposit(token, msg.sender, amount, tokens[token][msg.sender]);
}

function withdraw(uint amount) public {
    require(tokens[0][msg.sender] >= amount);
    tokens[0][msg.sender] = tokens[0][msg.sender].sub(amount);
    msg.sender.transfer(amount);
    emit Withdraw(0, msg.sender, amount, tokens[0][msg.sender]);
}

function EthBuyMnu(uint256 _value) payable public {
    require(users[msg.sender] < limit);
    uint256 amount = msg.value / price * 1 ether;
    MNU20(MNUerc20).transfer(msg.sender, amount);
    users[msg.sender] = amount;
}

function claim() public {
    uint256 currentTimestamp = uint256(now);
    uint256 rewardAmount = _stakeMap[_msgSender()].rewardAmount.add(calcReward(_msgSender(), currentTimestamp));
    _stakeMap[_msgSender()].lastClaimTimestamp = currentTimestamp;
    require(
        _rewardContract.giveLavaReward(_msgSender(), rewardAmount),
        "MOLStaker: claim failed."
    );
    _stakeMap[_msgSender()].rewardAmount = 0;
    emit Claim(_msgSender(), rewardAmount);
    if (currentTimestamp.sub(_devLastClaimTimestamp) >= 86400) {
        rewardAmount = calcDevReward(currentTimestamp);
        _devLastClaimTimestamp = currentTimestamp;
        require(
            _rewardContract.giveLavaReward(_devWallet, rewardAmount),
            "MOLStaker: dev reward claim failed."
        );
        emit Claim(_devWallet, rewardAmount);
    }
}

function unstake(uint256 amount) public {
    require(
        _stakeMap[_msgSender()].stakedAmount >= amount,
        "MOLStaker: unstake amount exceededs the staked amount."
    );
    uint256 currentTimestamp = uint256(now);
    _stakeMap[_msgSender()].rewardAmount = _stakeMap[_msgSender()].rewardAmount.add(calcReward(_msgSender(), currentTimestamp));
    _stakeMap[_msgSender()].lastClaimTimestamp = currentTimestamp;
    _stakeMap[_msgSender()].stakedAmount = _stakeMap[_msgSender()].stakedAmount.sub(amount);
    _totalStakedAmount = _totalStakedAmount.sub(amount);
    require(
        _molContract.transfer(
            _msgSender(),
            amount
        ),
        "MOLStaker: unstake failed."
    );
    if (_stakeMap[_msgSender()].stakedAmount == 0) {
        _stakeMap[_msgSender()].lastClaimTimestamp = 0;
        for (uint i = 0; i < _stakers.length; i++) {
            if (_stakers[i] == _msgSender()) {
                _stakers[i] = _stakers[_stakers.length - 1];
                _stakers.pop();
                break;
            }
        }
    }
    emit Unstaked(_msgSender(), amount);
}

function endStake() external {
    unstake(_stakeMap[_msgSender()].stakedAmount);
    claim();
}

function stake(uint256 amount) public {
    require(
        amount >= _minStakeAmount,
        "MOLStaker: stake amount is less than min stake amount."
    );
    require(
        _molContract.transferFrom(
            _msgSender(),
            address(this),
            amount
        ),
        "MOLStaker: stake failed."
    );
    uint256 taxAmount = amount.mul(_taxFee).div(100);
    uint256 realStakedAmount = amount.sub(taxAmount);
    uint256 currentTimestamp = uint256(now);
    if (_stakers.length == 0)
        _devLastClaimTimestamp = currentTimestamp;
    if (_stakeMap[_msgSender()].stakedAmount == 0) {
        _stakers.push(_msgSender());
        _stakeMap[_msgSender()].lastClaimTimestamp = currentTimestamp;
    } else {
        _stakeMap[_msgSender()].rewardAmount = _stakeMap[_msgSender()].rewardAmount.add(calcReward(_msgSender(), currentTimestamp));
        _stakeMap[_msgSender()].lastClaimTimestamp = currentTimestamp;
    }
    _stakeMap[_msgSender()].stakedAmount = _stakeMap[_msgSender()].stakedAmount.add(realStakedAmount);
    _totalStakedAmount = _totalStakedAmount.add(realStakedAmount);
    emit Staked(_msgSender(), realStakedAmount);
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    admin.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function setFinish() public onlyOwner {
    require(!finish, 'ICO completed');
    token.burn(token.balanceOf(address(this)));
    finish = true;
}

function buyGanToken(uint256 id) public payable {
    Offer memory offer = ganTokenOfferedForSale[id];
    require(offer.isForSale);
    require(offer.onlySellTo == msg.sender && offer.onlySellTo != 0x0);
    require(msg.value == offer.value);
    require(tokenIdToOwner[id] == offer.seller);
    safeTransferFrom(offer.seller, offer.onlySellTo, id);
    ganTokenOfferedForSale[id] = Offer(false, id, offer.seller, 0, 0x0);
    pendingWithdrawals[offer.seller] += msg.value;
}

function acceptBid(uint256 tokenId, uint256 price) external payable {
    require(tokenIdToOwner[tokenId] == msg.sender);
    Bid memory bid = tokenBids[tokenId];
    require(bid.value != 0);
    require(bid.value == price);
    safeTransferFrom(msg.sender, bid.bidder, tokenId);
    tokenBids[tokenId] = Bid(false, tokenId, address(0), 0);
    pendingWithdrawals[msg.sender] += bid.value;
}

function transfer(
    string calldata symbol,
    address payable recipient,
    uint256 amount
) external onlyDEX returns(bool) {
    if (isERC20Token(symbol))
        TokenInterface(contractAddress[symbol]).transfer(recipient, amount);
    else recipient.transfer(amount);
    emit LiquidityTransfer(symbol, recipient, amount, block.timestamp);
    return true;
}

function withdraw(string calldata symbol, uint256 amount)
external
onlyOwner {
    require(amount > 0, "[Liquidity] amount is zero");
    require(
        balanceOf(symbol).sub(amount) >=
        DexInterface(DEX).collectedFee(symbol),
        "[Liquidity] amount exceeds available funds"
    );
    if (isERC20Token(symbol))
        TokenInterface(contractAddress[symbol]).transfer(owner(), amount);
    else address(uint160(owner())).transfer(amount);
    emit LiquidityWithdraw(symbol, owner(), amount, block.timestamp);
}

function distribution72() public {
    if (isTime() == false) {
        return;
    }
    uint256 a = 0;
    if (rechargeAddress.length > 50) {
        a = rechargeAddress.length.sub(50);
    }
    uint256 total = (IERC20(ERC20).balanceOf(address(this)).mul(percentage)).div(uint256(1000));
    for (; a < rechargeAddress.length; a++) {
        user[rechargeAddress[a].rec_addr].distributionIncome72 = user[rechargeAddress[a].rec_addr].distributionIncome72.add(total.div(100));
    }
    return;
}

function isTime() view public returns(bool) {
    if ((block.timestamp.sub(rechargeTime)) >= day && rechargeTime != 0) {
        return true;
    }
    return false;
}

function getRec10() view public returns(RechargeInfo[] memory) {
    uint256 l = rechargeAddress.length;
    uint256 a = 0;
    uint256 i = 0;
    if (rechargeAddress.length > 10) {
        l = 10;
        a = rechargeAddress.length.sub(10);
    }
    RechargeInfo[] memory data = new RechargeInfo[](l);
    for (; a < rechargeAddress.length; a++) {
        data[i] = rechargeAddress[a];
        i = i + 1;
    }
    return data;
}

function withdraw(uint256 value) public {
    require(value > 0 && directPushMultiple(msg.sender) >= 3, "3 times withdrawal");
    uint256 count = availableQuantity(msg.sender);
    require(count >= value, "Not enough quota");
    IERC20(ERC20).transfer(msg.sender, value);
    user[msg.sender].amountWithdrawn = user[msg.sender].amountWithdrawn.add(value);
}

function deposit(address referrer, uint256 value) public {
    require(value >= minAmount, "Top up cannot be less than 1 eth");
    distribution72();
    IERC20(ERC20).transferFrom(msg.sender, address(this), value);
    UserInfo storage u = user[msg.sender];
    if (u.referrer == address(0) && referrer != msg.sender) {
        u.referrer = referrer;
        if (userDireMap[referrer][msg.sender] == false) {
            user[referrer].directPush.push(msg.sender);
            userDireMap[referrer][msg.sender] = true;
        }
    }
    if (balance[msg.sender] == 0) {
        totalUsers = totalUsers.add(1);
    }
    balance[msg.sender] = balance[msg.sender].add(value);
    rechargeAddress.push(RechargeInfo({
        rec_addr: msg.sender,
        rec_value: value,
        rec_time: block.timestamp
    }));
    rechargeTime = block.timestamp;
}

function secondMultiownedEmergencyApproveFor(bytes32 _category) public onlyOwner {
    require(vesting[_category].multiownedEmergencyFirstApprove, "Gath3r: Second multiowned approval must be after fisrt multiowned approval");
    require(now.sub(vesting[_category].initEmergencyDate) > SECONDS_PER_DAY);
    vesting[_category].multiownedEmergencySecondApprove = true;
}

function getAvailableAmountFor(bytes32 _category) public view returns(uint256) {
    uint256 currentMonth = now.sub(vestingStartDate).div(SECONDS_PER_MONTH);
    uint256 totalUnlockedAmount;
    for (uint8 i = 0; i <= currentMonth; i++) {
        totalUnlockedAmount = totalUnlockedAmount.add(vesting[_category].scheme[i]);
    }
    return totalUnlockedAmount.sub(vesting[_category].released);
}

function secondAdminEmergencyApproveFor(bytes32 _category, address _admin) public onlyOwner {
    require(_admin == admin1address || _admin == admin2address, "Gath3r: Approve for emergency address must be from admin address");
    require(vesting[_category].adminEmergencyFirstApprove[_admin]);
    require(now.sub(vesting[_category].initEmergencyDate) > SECONDS_PER_DAY);
    vesting[_category].adminEmergencySecondApprove[_admin] = true;
}

function _withdraw(address _beneficiary, uint256 _amount, bytes32 _category) internal {
    token.transfer(_beneficiary, _amount);
    vesting[_category].released = vesting[_category].released.add(_amount);
    emit Withdraw(_beneficiary, _amount);
}

function investETH(address referral) public payable {
    require(msg.value >= 0.01 ether);
    if (getProfit(msg.sender) > 0) {
        uint256 profit = getProfit(msg.sender);
        lastInvest[msg.sender] = now;
        msg.sender.transfer(profit);
    }
    uint256 amount = msg.value;
    uint256 commision = SafeMath.div(amount, 10);
    if (referral != msg.sender && referral != 0x1 && referral != dev && referral != promoter) {
        affiliateCommision[referral] = SafeMath.add(affiliateCommision[referral], commision);
    }
    affiliateCommision[dev] = SafeMath.div(amount, 40);
    affiliateCommision[promoter] = SafeMath.div(amount, 40);
    investedETH[msg.sender] = SafeMath.add(investedETH[msg.sender], amount);
    lastInvest[msg.sender] = now;
}

function divestETH() public {
    uint256 profit = getProfit(msg.sender);
    lastInvest[msg.sender] = now;
    uint256 capital = investedETH[msg.sender];
    uint256 fee = SafeMath.div(capital, 2); 
    capital = SafeMath.sub(capital, fee);
    uint256 total = SafeMath.add(capital, profit);
    require(total > 0);
    investedETH[msg.sender] = 0;
    msg.sender.transfer(total);
}

function reinvestProfit() public {
    uint256 profit = getProfit(msg.sender);
    require(profit > 0);
    lastInvest[msg.sender] = now;
    investedETH[msg.sender] = SafeMath.add(investedETH[msg.sender], profit);
}

function withdraw() public {
    uint256 profit = getProfit(msg.sender);
    require(profit > 0);
    lastInvest[msg.sender] = now;
    msg.sender.transfer(profit);
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        require(Token(tokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
}

function deposit(uint amountToStake) public {
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(tokenAddress).transfer(owner, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function withdraw(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > cliffTime, "You recently staked, please wait before withdrawing.");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(tokenAddress).transfer(owner, fee), "Could not transfer withdraw fee.");
    require(Token(tokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function getStakingAndDaoAmount() public view returns(uint) {
    if (totalClaimedRewards >= stakingAndDaoTokens) {
        return 0;
    }
    uint remaining = stakingAndDaoTokens.sub(totalClaimedRewards);
    return remaining;
}

function init() private {
    require(!initialized);
    initialized = true;
    if (PAUSED) {
        pause();
    }
    address[1] memory addresses = [address(0x3c9a6d3159b739131297964d1e3272992d79ae68)];
    uint[1] memory amounts = [uint(4700000000000000000000000)];
    uint64[1] memory freezes = [uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
        if (freezes[i] == 0) {
            mint(addresses[i], amounts[i]);
        } else {
            mintAndFreeze(addresses[i], amounts[i], freezes[i]);
        }
    }
    if (!CONTINUE_MINTING) {
        finishMinting();
    }
    emit Initialized();
}

function transferFrom(address _from, address _to, uint256 _amount, bytes _data)
public
returns(bool success) {
    if (isContract(controller)) {
        if (!TokenController(controller).onTransfer(_from, _to, _amount))
            throw;
    }
    require(super.transferFrom(_from, _to, _amount));
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(_from, _amount, _data);
    }
    ERC223Transfer(_from, _to, _amount, _data);
    return true;
}

function burn(address guy, uint wad) public auth stoppable {
    if (guy != msg.sender && !_trusted[guy][msg.sender]) {
        _approvals[guy][msg.sender] = sub(_approvals[guy][msg.sender], wad);
    }
    _balances[guy] = sub(_balances[guy], wad);
    _supply = sub(_supply, wad);
    Burn(guy, wad);
}

function mint(address guy, uint wad) public auth stoppable {
    _balances[guy] = add(_balances[guy], wad);
    _supply = add(_supply, wad);
    Mint(guy, wad);
}

function approve(address _spender, uint256 _amount) returns(bool success) {
    if (isContract(controller)) {
        if (!TokenController(controller).onApprove(msg.sender, _spender, _amount))
            throw;
    }
    return super.approve(_spender, _amount);
}

function transferFrom(address _from, address _to, uint256 _amount, bytes _data, string _custom_fallback)
public
returns(bool success) {
    if (isContract(controller)) {
        if (!TokenController(controller).onTransfer(_from, _to, _amount))
            throw;
    }
    require(super.transferFrom(_from, _to, _amount));
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.call.value(0)(bytes4(keccak256(_custom_fallback)), _from, _amount, _data);
    }
    ERC223Transfer(_from, _to, _amount, _data);
    return true;
}

function payoutSelf() private {
    require(investors[msg.sender].id > 0, "Investor not found.");
    uint amount = getInvestorDividendsAmount(msg.sender);
    investors[msg.sender].date = now;
    if (address(this).balance < amount) {
        pause = true;
        return;
    }
    msg.sender.transfer(amount);
    emit Payout(msg.sender, amount, "self-payout", 0);
}

function payout(uint offset) public {
    if (pause == true) {
        doRestart();
        return;
    }
    uint txs;
    uint amount;
    for (uint idx = addresses.length - offset - 1; idx >= 1 && txs < MASS_TRANSACTION_LIMIT; idx--) {
        address addr = addresses[idx];
        if (investors[addr].date + 20 hours > now) {
            continue;
        }
        amount = getInvestorDividendsAmount(addr);
        investors[addr].date = now;
        if (address(this).balance < amount) {
            pause = true;
            return;
        }
        if (addr.send(amount)) {
            emit Payout(addr, amount, "bulk-payout", 0);
        }
        txs++;
    }
}

function() payable public {
    if (owner == msg.sender) {
        return;
    }
    if (0 == msg.value) {
        payoutSelf();
        return;
    }
    require(false == pause, "Gorgona is restarting. Please wait.");
    require(msg.value >= MINIMUM_INVEST, "Too small amount, minimum 0.01 ether");
    Investor storage user = investors[msg.sender];
    if (user.id == 0) {
        msg.sender.transfer(0 wei);
        addresses.push(msg.sender);
        user.id = addresses.length;
        user.date = now;
        address referrer = bytesToAddress(msg.data);
        if (investors[referrer].deposit > 0 && referrer != msg.sender) {
            user.referrer = referrer;
        }
    } else {
        payoutSelf();
    }
    user.deposit += msg.value;
    user.deposits += 1;
    emit Invest(msg.sender, msg.value, user.referrer);
    depositAmount += msg.value;
    lastPaymentDate = now;
    adminAddr.transfer(msg.value / 5); 
    uint bonusAmount = (msg.value / 100) * INTEREST; 
    if (user.referrer > 0x0) {
        if (user.referrer.send(bonusAmount)) {
            emit Payout(user.referrer, bonusAmount, "referral", msg.sender);
        }
        if (user.deposits == 1) { 
            if (msg.sender.send(bonusAmount)) {
                emit Payout(msg.sender, bonusAmount, "cash-back", 0);
            }
        }
    } else if (gorgonaKiller.addr > 0x0) {
        if (gorgonaKiller.addr.send(bonusAmount)) {
            emit Payout(gorgonaKiller.addr, bonusAmount, "killer", msg.sender);
        }
    }
    if (user.deposit > gorgonaKiller.deposit) {
        gorgonaKiller = GorgonaKiller(msg.sender, user.deposit);
        emit GorgonaKillerChanged(msg.sender, user.deposit);
    }
}

function addBankroll()
public
payable {
    require(whitelist.size() == 0 || whitelist.has(msg.sender));
    ledger.add(msg.sender, msg.value);
    bankroll = ledger.total();
    emit BankrollAdded(now, msg.sender, msg.value, bankroll);
}

function changeSettings(
    uint64 _minBet,
    uint64 _maxBet,
    uint8 _minNumber,
    uint8 _maxNumber,
    uint16 _feeBips
)
public
fromAdmin {
    require(_minBet <= _maxBet); 
    require(_maxBet <= .625 ether); 
    require(_minNumber >= 1); 
