function roll(uint8 _number)
public
payable
returns(bool _success) {
    if (!_validateBetOrRefund(_number)) return;
    User memory _prevUser = users[msg.sender];
    if (_prevUser.r_block == uint32(block.number)) {
        _errorAndRefund("Only one bet per block allowed.", msg.value, _number);
        return false;
    }
    Stats memory _stats = stats;
    User memory _newUser = User({
        id: _prevUser.id == 0 ? _stats.numUsers + 1 : _prevUser.id,
        r_id: _stats.numRolls + 1,
        r_block: uint32(block.number),
        r_number: _number,
        r_payout: computePayout(msg.value, _number)
    });
    users[msg.sender] = _newUser;
    if (_prevUser.r_block != 0) _finalizePreviousRoll(_prevUser, _stats);
    _stats.numUsers = _prevUser.id == 0 ? _stats.numUsers + 1 : _stats.numUsers;
    _stats.numRolls = stats.numRolls + 1;
    _stats.totalWagered = stats.totalWagered + uint96(msg.value);
    stats = _stats;
    emit RollWagered(now, _newUser.r_id, msg.sender, msg.value, _newUser.r_number, _newUser.r_payout);
    return true;
}

function removeBankroll(uint _amount, string _callbackFn)
public
returns(uint _recalled) {
    address _bankroller = msg.sender;
    uint _collateral = getCollateral();
    uint _balance = address(this).balance;
    uint _available = _balance > _collateral ? _balance - _collateral : 0;
    if (_amount > _available) _amount = _available;
    _amount = ledger.subtract(_bankroller, _amount);
    bankroll = ledger.total();
    if (_amount == 0) return;
    bytes4 _sig = bytes4(keccak256(_callbackFn));
    require(_bankroller.call.value(_amount)(_sig));
    emit BankrollRemoved(now, _bankroller, _amount, bankroll);
    return _amount;
}

function payoutPreviousRoll()
public
returns(bool _success) {
    User memory _prevUser = users[msg.sender];
    if (_prevUser.r_block == uint32(block.number)) {
        emit PayoutError(now, "Cannot payout roll on the same block");
        return false;
    }
    if (_prevUser.r_block == 0) {
        emit PayoutError(now, "No roll to pay out.");
        return false;
    }
    User storage _user = users[msg.sender];
    _user.r_id = 0;
    _user.r_block = 0;
    _user.r_number = 0;
    _user.r_payout = 0;
    Stats memory _stats = stats;
    _finalizePreviousRoll(_prevUser, _stats);
    stats.totalWon = _stats.totalWon;
    return true;
}

function lend(address _to, ERC20 _token, uint256 _amount, address _target, bytes _data) public payable {
    inLendingMode += 1;
    super.lend(_to, _token, _amount, _target, _data);
    inLendingMode -= 1;
}

function approveAndCall(address _to, uint256 _value, bytes _data) public payable returns(bool) {
    sendersStack_.push(msg.sender);
    approve(_to, _value);
    require(caller_.makeCall.value(msg.value)(_to, _data));
    sendersStack_.length -= 1;
    return true;
}

function bundle(address _beneficiary, uint256 _amount) public {
    require(totalSupply_ != 0, "This method can be used with non zero total supply only");
    uint256[] memory tokenAmounts = new uint256[](tokens.length);
    for (uint i = 0; i < tokens.length; i++) {
        tokenAmounts[i] = tokens[i].balanceOf(this).mul(_amount).div(totalSupply_);
    }
    _bundle(_beneficiary, _amount, tokenAmounts);
}

function _bundle(address _beneficiary, uint256 _amount, uint256[] _tokenAmounts) internal whenNotPaused {
    require(tokens.length == _tokenAmounts.length, "Lenghts of tokens and _tokenAmounts array should be equal");
    for (uint i = 0; i < tokens.length; i++) {
        uint256 prevBalance = tokens[i].balanceOf(this);
        tokens[i].transferFrom(msg.sender, this, _tokenAmounts[i]); 
        require(tokens[i].balanceOf(this) == prevBalance.add(_tokenAmounts[i]), "Invalid token behavior");
    }
    totalSupply_ = totalSupply_.add(_amount);
    balances[_beneficiary] = balances[_beneficiary].add(_amount);
    emit Bundle(msg.sender, _beneficiary, _amount);
    emit Transfer(0, _beneficiary, _amount);
}

function operatorRegister(uint tBTCBalance, uint lnBalance, uint linearFee, uint constantFee, string memory publicUrl) public {
    require(operators[msg.sender].exists == false, "Operator has already been registered before");
    operators[msg.sender] = Operator(publicUrl, tBTCBalance, lnBalance, true, linearFee, constantFee);
    if (tBTCBalance > 0) {
        tBTContract.transferFrom(msg.sender, address(this), tBTCBalance);
    }
    operatorList.push(msg.sender);
}

function claimTBTCPayment(bytes32 paymentHash, bytes memory preimage) public {
    LN2TBTCSwap storage swap = lnSwaps[msg.sender][paymentHash];
    require(swap.tBTCAmount > 0, "Swap doesn't exist or has already been finalized");
    require(swap.tBTCLockTimestamp != 0, "tBTC tokens have not been locked for this swap");
    require(sha256(preimage) == paymentHash, "Preimage doesn't match the payment hash");
    uint tBTCAmount = swap.tBTCAmount;
    swap.tBTCAmount = 0;
    tBTContract.transfer(msg.sender, tBTCAmount);
    msg.sender.transfer(securityDepositAmount); 
    Operator storage op = operators[swap.provider];
    op.lnBalance += addFees(tBTCAmount / tBTCDenominator, op.linearFee, op.constantFee); 
    emit LN2TBTCPreimageRevealed(msg.sender, paymentHash, swap.provider, preimage);
}

function createLN2TBTCSwap(bytes32 paymentHash, address providerAddress, uint tBTCAmount) payable public {
    require(lnSwaps[msg.sender][paymentHash].startTimestamp == 0, "Swap already exists");
    require(msg.value == securityDepositAmount, "ETH security deposit provided isn't the right amount (should be 1 ETH)");
    require(tBTCAmount > 0, "The amount requested cannot be zero (why swap something for nothing?)");
    lnSwaps[msg.sender][paymentHash] = LN2TBTCSwap(providerAddress, tBTCAmount, now, 0);
    emit LN2TBTCSwapCreated(msg.sender, paymentHash, providerAddress, tBTCAmount);
}

function revertLN2TBTCSwap(bytes32 paymentHash) public {
    LN2TBTCSwap storage swap = lnSwaps[msg.sender][paymentHash];
    require(swap.tBTCAmount > 0, "Swap doesn't exist or has already been finalized");
    require((swap.startTimestamp + timeoutPeriod) < now, "Swap hasn't timed out yet");
    require(swap.tBTCLockTimestamp == 0, "Operator has locked the tBTC tokens before the timeout");
    swap.tBTCAmount = 0;
    msg.sender.transfer(securityDepositAmount); 
}

function operatorLockTBTCForLN2TBTCSwap(address userAddress, bytes32 paymentHash) public {
    LN2TBTCSwap storage swap = lnSwaps[userAddress][paymentHash];
    require(swap.provider == msg.sender, "Swap doesn't use this provider or doesn't exist at all");
    require(swap.tBTCAmount > 0, "Swap has already been finalized");
    require(swap.tBTCLockTimestamp == 0, "tBTC tokens have already been locked before for this swap");
    Operator storage op = operators[msg.sender];
    require(op.tBTCBalance >= swap.tBTCAmount, "Operator doesn't have enough funds to conduct the swap");
    op.tBTCBalance -= swap.tBTCAmount;
    swap.tBTCLockTimestamp = now;
    emit LN2TBTCOperatorLockedTBTC(userAddress, paymentHash);
}

function operatorRevertLN2TBTCSwap(address userAddress, bytes32 paymentHash) public {
    LN2TBTCSwap storage swap = lnSwaps[userAddress][paymentHash];
    require(swap.provider == msg.sender, "Swap doesn't use this provider or doesn't exist at all");
    require(swap.tBTCAmount > 0, "Swap has already been finalized");
    require(swap.tBTCLockTimestamp != 0, "tBTC tokens have not been locked for this swap");
    require((swap.tBTCLockTimestamp + timeoutPeriod) < now, "Swap hasn't timed out yet");
    operators[msg.sender].tBTCBalance += swap.tBTCAmount;
    swap.tBTCAmount = 0;
    msg.sender.transfer(securityDepositAmount); 
}

function revertTBTC2LNSwap(bytes32 paymentHash) public {
    TBTC2LNSwap storage swap = tbtcSwaps[msg.sender][paymentHash];
    require(swap.timeoutTimestamp != 0, "Swap doesn't exist");
    require(swap.tBTCAmount > 0, "Swap has already been finalized");
    require(swap.timeoutTimestamp < now, "Swap hasn't timed out yet");
    uint tBTCAmount = swap.tBTCAmount;
    swap.tBTCAmount = 0;
    tBTContract.transfer(msg.sender, tBTCAmount);
}

function hasEnoughQuota(
    address wallet,
    uint requiredAmount
)
public
view
returns(bool) {
    return availableQuota(wallet) >= requiredAmount;
}

function pendingQuota(address wallet)
public
view
returns(
    uint _pendingQuota,
    uint _pendingUntil
) {
    Quota storage q = quotas[wallet];
    if (q.pendingUntil > 0 && q.pendingUntil > block.timestamp) {
        _pendingQuota = q.pendingQuota > 0 ? q.pendingQuota : defaultQuota;
        _pendingUntil = q.pendingUntil;
    }
}

function spentQuota(address wallet)
public
view
returns(uint) {
    Quota storage q = quotas[wallet];
    uint timeSinceLastSpent = block.timestamp.sub(q.spentTimestamp);
    if (timeSinceLastSpent < 1 days) {
        return uint(q.spentAmount).sub(timeSinceLastSpent.mul(q.spentAmount) / 1 days);
    } else {
        return 0;
    }
}

function currentQuota(address wallet)
public
view
returns(uint) {
    Quota storage q = quotas[wallet];
    uint value = q.pendingUntil <= block.timestamp ?
        q.pendingQuota : q.currentQuota;
    return value == 0 ? defaultQuota : value;
}

function availableQuota(address wallet)
public
view
returns(uint) {
    uint quota = currentQuota(wallet);
    uint spent = spentQuota(wallet);
    return quota > spent ? quota - spent : 0;
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(msg.value != 0);
    prepareContinuousPurchase();
    uint256 tokens = processPurchase(beneficiary);
    checkContinuousPurchase(tokens);
}

function start() onlyOwner {
    require(!started);
    uint256 finalSupply = token.totalSupply();
    uint256 annualIssuance = finalSupply.mul(INFLATION).div(100);
    issuance = annualIssuance.mul(BUCKET_SIZE).div(1 years);
    started = true;
}

function finalize() onlyOwner {
    require(!isFinalized);
    require(hasEnded());
    finalization();
    Finalized();
    isFinalized = true;
}

function prepareContinuousPurchase() internal {
    uint256 timestamp = block.timestamp;
    uint256 bucket = timestamp - (timestamp % BUCKET_SIZE);
    if (bucket > lastBucket) {
        lastBucket = bucket;
        bucketAmount = 0;
    }
}

function requireBallotOpen(DB storage db) internal view {
    uint64 _n = uint64(now);
    uint64 startTs;
    uint64 endTs;
    (, startTs, endTs) = BPackedUtils.unpackAll(db.packed);
    require(_n >= startTs && _n < endTs, "!b-open");
    require(db.deprecated == false, "b-deprecated");
}

function requireBallotClosed(DB storage db) internal view {
    require(now > BPackedUtils.packedToEndTime(db.packed), "!b-closed");
}

function init(DB storage db, bytes32 _specHash, uint256 _packed, IxIface ix, address ballotOwner, bytes16 extraData) external {
    require(db.specHash == bytes32(0), "b-exists");
    db.index = ix;
    db.ballotOwner = ballotOwner;
    uint64 startTs;
    uint64 endTs;
    uint16 sb;
    (sb, startTs, endTs) = BPackedUtils.unpackAll(_packed);
    bool _testing = isTesting(sb);
    if (_testing) {
        emit TestingEnabled();
    } else {
        require(endTs > now, "bad-end-time");
        require(sb & 0x1ff2 == 0, "bad-sb");
        bool okaySubmissionBits = 1 == (isEthNoEnc(sb) ? 1 : 0) + (isEthWithEnc(sb) ? 1 : 0);
        require(okaySubmissionBits, "!valid-sb");
        startTs = startTs > now ? startTs : uint64(now);
    }
    require(_specHash != bytes32(0), "null-specHash");
    db.specHash = _specHash;
    db.packed = BPackedUtils.pack(sb, startTs, endTs);
    db.creationTs = now;
    if (extraData != bytes16(0)) {
        db.extraData = extraData;
    }
    emit CreatedBallot(db.specHash, startTs, endTs, sb);
}

function() external payable {
    address sender = msg.sender;
    uint256 amount = 0;
    if (invested[sender] != 0) {
        amount = invested[sender] * interest / 100 * (now - timeInvest[sender]) / 1 days;
        if (msg.value == 0) {
            if (amount >= address(this).balance) {
                amount = (address(this).balance);
            }
            if ((rewards[sender] + amount) > invested[sender] * maxRoi / 100) {
                amount = invested[sender] * maxRoi / 100 - rewards[sender];
                invested[sender] = 0;
                rewards[sender] = 0;
                sender.transfer(amount);
                return;
            } else {
                sender.transfer(amount);
                rewards[sender] += amount;
                amount = 0;
            }
        }
    }
    timeInvest[sender] = now;
    invested[sender] += (msg.value + amount);
    if (msg.value != 0) {
        WhaleAddr.transfer(msg.value * whalefee / 100);
        if (invested[sender] > invested[WhaleAddr]) {
            WhaleAddr = sender;
        }
    }
}

function buyTokens()
public
payable {
    uint256 tokens;
    uint256 balance = xcertKyc.balanceOf(msg.sender);
    require(balance > 0);
    if (isInTimeRange(startTimePresale, startTimeSaleWithBonus)) {
        uint256 tokenId = xcertKyc.tokenOfOwnerByIndex(msg.sender, balance.sub(1));
        uint256 kycLevel = uint(xcertKyc.tokenDataValue(tokenId, 0));
        require(kycLevel > 1);
        require(msg.value >= minimumPresaleWeiDeposit);
        tokens = getTokenAmount(msg.value, bonusPresale);
        require(tokens <= preSaleZxcCap);
    } else if (isInTimeRange(startTimeSaleWithBonus, startTimeSaleNoBonus)) {
        tokens = getTokenAmount(msg.value, bonusSale);
    } else if (isInTimeRange(startTimeSaleNoBonus, endTime)) {
        tokens = getTokenAmount(msg.value, uint256(0));
    } else {
        revert("Purchase outside of token sale time windows");
    }
    require(zxcSold.add(tokens) <= crowdSaleZxcSupply);
    zxcSold = zxcSold.add(tokens);
    wallet.transfer(msg.value);
    require(token.transferFrom(token.owner(), msg.sender, tokens));
    emit TokenPurchase(msg.sender, msg.sender, msg.value, tokens);
}

function hasEnded()
external
view
returns(bool) {
    bool capReached = zxcSold >= crowdSaleZxcSupply;
    bool endTimeReached = now >= endTime;
    return capReached || endTimeReached;
}

constructor(
    address _walletAddress,
    address _tokenAddress,
    address _xcertKycAddress,
    uint256 _startTimePresale, 
    uint256 _startTimeSaleWithBonus, 
    uint256 _startTimeSaleNoBonus, 
    uint256 _endTime, 
    uint256 _rate, 
    uint256 _presaleZxcCap, 
    uint256 _crowdSaleZxcSupply, 
    uint256 _bonusPresale, 
    uint256 _bonusSale, 
    uint256 _minimumPresaleWeiDeposit 
)
public {
    require(_walletAddress != address(0));
    require(_tokenAddress != address(0));
    require(_xcertKycAddress != address(0));
    require(_tokenAddress != _walletAddress);
    require(_tokenAddress != _xcertKycAddress);
    require(_xcertKycAddress != _walletAddress);
    token = Zxc(_tokenAddress);
    xcertKyc = Xcert(_xcertKycAddress);
    uint8 _tokenDecimals = token.decimals();
    require(_tokenDecimals == 18); 
    wallet = _walletAddress;
    require(_bonusPresale > 0 && _bonusPresale <= 100);
    require(_bonusSale > 0 && _bonusSale <= 100);
    bonusPresale = _bonusPresale;
    bonusSale = _bonusSale;
    require(_startTimePresale >= now);
    require(_startTimeSaleWithBonus > _startTimePresale);
    require(_startTimeSaleNoBonus > _startTimeSaleWithBonus);
    startTimePresale = _startTimePresale;
    startTimeSaleWithBonus = _startTimeSaleWithBonus;
    startTimeSaleNoBonus = _startTimeSaleNoBonus;
    endTime = _endTime;
    require(_rate > 0);
    rate = _rate;
    require(_crowdSaleZxcSupply > 0);
    require(token.totalSupply() >= _crowdSaleZxcSupply);
    crowdSaleZxcSupply = _crowdSaleZxcSupply;
    require(_presaleZxcCap > 0 && _presaleZxcCap <= _crowdSaleZxcSupply);
    preSaleZxcCap = _presaleZxcCap;
    zxcSold = 0;
    require(_minimumPresaleWeiDeposit > 0);
    minimumPresaleWeiDeposit = _minimumPresaleWeiDeposit;
}

function isInTimeRange(
    uint256 _startTime,
    uint256 _endTime
)
internal
view
returns(bool) {
    if (now >= _startTime && now < _endTime) {
        return true;
    } else {
        return false;
    }
}

function isLocked(address _address) constant returns(bool) {
    return now >= lockExpiration ? false : locked[_address];
}

function investInternal(address receiver) private {
    require(!finalized);
    require(startsAt <= now && endsAt > now);
    require(tokensSold <= MAX_GOAL_EBC);
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    uint tokensAmount = msg.value * TokenPerETH;
    investedAmountOf[receiver] += msg.value;
    tokenAmountOf[receiver] += tokensAmount;
    tokensSold += tokensAmount;
    weiRaised += msg.value;
    Invested(receiver, msg.value, tokensAmount);
    token.mintToken(receiver, tokensAmount);
}

function setEndsAt(uint time) onlyOwner {
    require(!finalized);
    require(time >= now);
    endsAt = time;
    EndsAtChanged(endsAt);
}

function finalize(address receiver) public onlyOwner {
    require(endsAt < now);
    finalized = true;
    token.releaseTokenTransfer();
    receiver.transfer(this.balance);
}

function procureTokens(address _beneficiary) public payable {
    uint256 tokens;
    uint256 weiAmount = msg.value;
    address _this = this;
    require(now >= startICO);
    require(_beneficiary != address(0));
    tokens = weiAmount.mul(rateICO);
    checkHardCap(tokens);
    wallet.transfer(_this.balance);
    token.mint(_beneficiary, tokens);
    emit TokenProcurement(msg.sender, _beneficiary, weiAmount, tokens);
}

function transfer_gold(address to, uint256 gold) public {
    require(gold_balances[msg.sender] >= gold, 'Insufficient gold');
    gold_balances[msg.sender] -= gold;
    gold_balances[to] += gold;
    emit Gold_Transferred(msg.sender, to, gold);
}

function buy_units_with_gold(uint8 tile_x, uint8 tile_y, uint8 unit_count) public {
    require(!get_season_ended(), 'Season has ended');
    require(tile_owner[tile_x][tile_y] == address(msg.sender), 'Sender isnt owner');
    require(get_gold(msg.sender) >= (unit_gold_price * unit_count), 'Insufficient gold');
    require(tile_development_level[tile_x][tile_y] > 0, 'Tile isnt colonized');
    require(unit_count <= max_units, 'Buying too many units');
    require(units_on_tile[tile_x][tile_y] + unit_count <= max_units, 'Sum over max units');
    require(units_on_tile[tile_x][tile_y] + unit_count > units_on_tile[tile_x][tile_y], 'Units zero or overflow');
    last_GPH_update_time[msg.sender] = block.timestamp;
    gold_balances[msg.sender] = get_gold(msg.sender) - unit_gold_price * unit_count;
    units_on_tile[tile_x][tile_y] += unit_count;
    emit New_Population(tile_x, tile_y, units_on_tile[tile_x][tile_y]);
}

function market_buy(uint8 x, uint8 y) public payable {
    require(!get_season_ended(), 'Season has ended');
    require(market_price[x][y] != 0, 'Land not for sale');
    require(msg.value == market_price[x][y], 'Invalid purchase price');
    address payable seller = tile_owner[x][y];
    market_price[x][y] = 0;
    if (get_tile(x, y) > victory_threshold) {
        victory_tiles_owned[msg.sender]++; 
        victory_tiles_owned[seller]--; 
    }
    tile_owner[x][y] = msg.sender;
    seller.transfer(msg.value);
    emit Market_Bought(x, y, msg.sender);
}

function doInvest(address from, uint256 investment, address newReferrer) public payable {
    require(isProxy[msg.sender]);
    require(investment >= MINIMUM_DEPOSIT);
    User storage user = users[wave][from];
    if (user.firstTime == 0) {
        user.firstTime = now;
        user.lastPayment = now;
        emit InvestorAdded(from);
    }
    if (user.referrer == address(0) &&
        msg.data.length == 20 &&
        user.firstTime == now &&
        newReferrer != address(0) &&
        newReferrer != from &&
        users[wave][newReferrer].firstTime > 0
    ) {
        user.referrer = newReferrer;
        emit ReferrerAdded(from, newReferrer);
    }
    if (user.referrer != address(0)) {
        uint256 refAmount = investment.mul(referralPercents).div(ONE_HUNDRED_PERCENTS);
        users[wave][user.referrer].referralAmount = users[wave][user.referrer].referralAmount.add(investment);
        user.referrer.transfer(refAmount);
    }
    investment = investment.add(getDividends(from));
    totalInvest = totalInvest.add(investment);
    user.deposits.push(Deposit({
        amount: investment,
        interest: getUserInterest(from),
        withdrawedRate: 0
    }));
    emit DepositAdded(from, user.deposits.length, investment);
    uint256 marketingAndTeamFee = msg.value.mul(MARKETING_AND_TEAM_FEE).div(ONE_HUNDRED_PERCENTS);
    marketingAndTechnicalSupport.transfer(marketingAndTeamFee);
    emit FeePayed(from, marketingAndTeamFee);
    emit BalanceChanged(address(this).balance);
}

function withdrawDividends(address from) public {
    require(isProxy[msg.sender]);
    uint256 dividendsSum = getDividends(from);
    require(dividendsSum > 0);
    if (address(this).balance <= dividendsSum) {
        wave = wave.add(1);
        totalInvest = 0;
        dividendsSum = address(this).balance;
        emit NewWave();
    }
    from.transfer(dividendsSum);
    emit UserDividendPayed(from, dividendsSum);
    emit BalanceChanged(address(this).balance);
}

function dividendsSumForUser(address wallet) external view returns(uint256 dividendsSum) {
    User memory user = users[wave][wallet];
    for (uint i = 0; i < user.deposits.length; i++) {
        uint256 withdrawAmount = user.deposits[i].amount.mul(dividendRate(wallet, i)).div(ONE_HUNDRED_PERCENTS);
        dividendsSum = dividendsSum.add(withdrawAmount);
    }
    dividendsSum = dividendsSum.add(user.referBonus);
    dividendsSum = min(dividendsSum, address(this).balance);
}

function getUserInterest(address wallet) public view returns(uint256) {
    User memory user = users[wave][wallet];
    if (user.referralAmount < 1 ether) {
        if (user.referrer == address(0)) return DAILY_INTEREST[0];
        return DAILY_INTEREST[1];
    } else if (user.referralAmount < 10 ether) {
        return DAILY_INTEREST[2];
    } else if (user.referralAmount < 20 ether) {
        return DAILY_INTEREST[3];
    } else {
        return DAILY_INTEREST[4];
    }
}

function min(uint256 a, uint256 b) internal pure returns(uint256) {
    if (a < b) return a;
    return b;
}

function depositForUser(address wallet) external view returns(uint256 sum) {
    User memory user = users[wave][wallet];
    for (uint i = 0; i < user.deposits.length; i++) {
        sum = sum.add(user.deposits[i].amount);
    }
}

function resetContribution() external {
    require(msg.sender == lottery.owner());
    contribution = 0;
}

function release(ERC20 token) public {
    uint256 unreleased = releasableAmount(token);
    require(unreleased > 0);
    released[token] = released[token].add(unreleased);
    token.safeTransfer(beneficiary, unreleased);
    emit Released(unreleased);
}

function vestedAmount(ERC20 token) public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[token]) {
        return totalBalance;
    } else {
        uint256 gap = 3600;
        uint256 start_gap = block.timestamp.sub(start).div(gap).mul(gap);
        return totalBalance.mul(start_gap).div(duration);
    }
}

function revoke(ERC20 token) public onlyOwner {
    require(revocable);
    require(!revoked[token]);
    uint256 balance = token.balanceOf(this);
    uint256 unreleased = releasableAmount(token);
    uint256 refund = balance.sub(unreleased);
    revoked[token] = true;
    token.safeTransfer(owner, refund);
    emit Revoked();
}

function deploy(uint256 index, bytes data) public whenNotPaused {
    address mtkn = _deployers[index].deploy(data);
    _multitokens.push(mtkn);
    emit NewMultitoken(mtkn);
}

function setDeployer(uint256 index, AbstractDeployer deployer) public onlyOwner whenNotPaused {
    require(deployer.owner() == address(this), "setDeployer: first set MultiTokenNetwork as owner");
    emit NewDeployer(index, _deployers[index], deployer);
    _deployers[index] = deployer;
}

function() public payable {
    require(now >= startDate && now <= endDate && totalSupply_ >= startCrowdsale && totalSupply_ < endCrowdsalel);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 4000000;
    } else {
        tokens = msg.value * 10000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    totalSupply_ = safeAdd(totalSupply_, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function unlockBySender() public {
    UserVestingInfo storage _userVestingInfo = UserVesting[msg.sender];
    require(_userVestingInfo.totalAmount > 0, "The user has no lock record");
    uint256 unlockAmount = 0;
    if (blockTimestamp() > endDate) {
        require(_userVestingInfo.totalAmount > _userVestingInfo.unlockAmount, "The user has no unlocked quota");
        unlockAmount = _userVestingInfo.totalAmount.sub(_userVestingInfo.unlockAmount);
    } else {
        uint256 unlockTimes = getUnlockTimes();
        require(unlockTimes > _userVestingInfo.lastUnlockTime, "The user has no lock record");
        unlockAmount = unlockTimes.sub(_userVestingInfo.lastUnlockTime).mul(_userVestingInfo.secondUnlock);
        _userVestingInfo.lastUnlockTime = unlockTimes;
    }
    _safeTransfer(msg.sender, unlockAmount);
    _userVestingInfo.unlockAmount = _userVestingInfo.unlockAmount.add(unlockAmount);
    emit UnlockBySenderEvent(msg.sender, unlockAmount);
}

function _safeTransfer(address _unlockAddress, uint256 _unlockToken) private {
    require(balanceOf() >= _unlockToken, "Insufficient available balance for transfer");
    token.transfer(_unlockAddress, _unlockToken);
}

function addUserVestingInfo(address _address, uint256 _totalAmount) public {
    require(msgSender == msg.sender, "You do not have permission to operate");
    require(_address != address(0), "The lock address cannot be a black hole address");
    UserVestingInfo storage _userVestingInfo = UserVesting[_address];
    require(_totalAmount > 0, "Lock up amount cannot be 0");
    require(_userVestingInfo.totalAmount == 0, "Lock has been added");
    _userVestingInfo.totalAmount = _totalAmount.mul(10 ** tokenDecimals);
    _userVestingInfo.firstAmount = _userVestingInfo.totalAmount.mul(125).div(1000); 
    _userVestingInfo.secondUnlock = _userVestingInfo.totalAmount.sub(_userVestingInfo.firstAmount).div(maxUnlockTimes);
    unlockAmountTotal = unlockAmountTotal.add(_userVestingInfo.totalAmount);
}

function getUnlockTimes() public virtual view returns(uint256) {
    if (blockTimestamp() > startDate) {
        return blockTimestamp().sub(startDate);
    } else {
        return 0;
    }
}

function unlockFirstBySender() public {
    UserVestingInfo storage _userVestingInfo = UserVesting[msg.sender];
    require(_userVestingInfo.totalAmount > 0, "The user has no lock record");
    require(_userVestingInfo.firstAmount > 0, "The user has unlocked the first token");
    require(_userVestingInfo.totalAmount > _userVestingInfo.unlockAmount, "The user has unlocked the first token");
    require(blockTimestamp() > startDate, "It's not time to lock and unlock");
    _safeTransfer(msg.sender, _userVestingInfo.firstAmount);
    _userVestingInfo.unlockAmount = _userVestingInfo.unlockAmount.add(_userVestingInfo.firstAmount);
    emit FirstBySenderEvent(msg.sender, _userVestingInfo.firstAmount);
    _userVestingInfo.firstAmount = 0;
}

function() public payable onlyPositiveSend {
    participants.push(Participant(msg.sender, (msg.value * multiplier) / 100));
    uint balance = msg.value;
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        participants[payoutOrder].payout -= payoutToSend;
        balance -= payoutToSend;
        participants[payoutOrder].etherAddress.transfer(payoutToSend);
        if (balance > 0) {
            payoutOrder += 1;
        }
    }
}

function getBonusByDate() view returns(uint256) {
    if (block.timestamp < 1514764800) return 0;
    if (block.timestamp < 1521158400) return 40;
    if (block.timestamp < 1523836800) return 30;
    if (block.timestamp < 1523923200) return 25;
    if (block.timestamp < 1524441600) return 20;
    if (block.timestamp < 1525046400) return 10;
    if (block.timestamp < 1525651200) return 5;
    return 0;
}

function openOrder(uint64 _settlementID, bytes _signature, bytes32 _orderID) external {
    require(orders[_orderID].state == OrderState.Undefined, "invalid order status");
    address trader = msg.sender;
    require(settlementRegistry.settlementRegistration(_settlementID), "settlement not registered");
    BrokerVerifier brokerVerifier = settlementRegistry.brokerVerifierContract(_settlementID);
    require(brokerVerifier.verifyOpenSignature(trader, _signature, _orderID), "invalid broker signature");
    orders[_orderID] = Order({
        state: OrderState.Open,
        trader: trader,
        confirmer: 0x0,
        settlementID: _settlementID,
        priority: orderbook.length + 1,
        blockNumber: block.number,
        matchedOrder: 0x0
    });
    orderbook.push(_orderID);
}

function cancelOrder(bytes32 _orderID) external {
    require(orders[_orderID].state == OrderState.Open, "invalid order state");
    address brokerVerifier = address(settlementRegistry.brokerVerifierContract(orders[_orderID].settlementID));
    require(msg.sender == orders[_orderID].trader || msg.sender == brokerVerifier, "not authorized");
    orders[_orderID].state = OrderState.Canceled;
    orders[_orderID].blockNumber = block.number;
}

function submitChallenge(bytes32 _buyID, bytes32 _sellID) external {
    require(!challengeSubmitted[_buyID][_sellID], "already challenged");
    require(orderSubmitted[_buyID], "details unavailable");
    require(orderSubmitted[_sellID], "details unavailable");
    require(trustedOrderbook.orderMatch(_buyID) == _sellID, "unconfirmed orders");
    bool mismatchedDetails = !SettlementUtils.verifyMatchDetails(orderDetails[_buyID], orderDetails[_sellID]);
    bool nondistinctTrader = trustedOrderbook.orderTrader(_buyID) == trustedOrderbook.orderTrader(_sellID);
    require(mismatchedDetails || nondistinctTrader, "invalid challenge");
    address confirmer = trustedOrderbook.orderConfirmer(_buyID);
    challengeSubmitted[_buyID][_sellID] = true;
    challengeSubmitted[_sellID][_buyID] = true;
    trustedDarknodeRegistry.slash(confirmer, challengers[_buyID], challengers[_sellID]);
}

function slash(address _prover, address _challenger1, address _challenger2)
external
onlySlasher {
    uint256 penalty = store.darknodeBond(_prover) / 2;
    uint256 reward = penalty / 4;
    store.updateDarknodeBond(_prover, penalty);
    if (isDeregisterable(_prover)) {
        store.updateDarknodeDeregisteredAt(_prover, currentEpoch.blocknumber + minimumEpochInterval);
        numDarknodesNextEpoch -= 1;
        emit LogDarknodeDeregistered(_prover);
    }
    ren.transfer(store.darknodeOwner(_challenger1), reward);
    ren.transfer(store.darknodeOwner(_challenger2), reward);
}

function register(address _darknodeID, bytes _publicKey, uint256 _bond) external onlyRefunded(_darknodeID) {
    require(_bond >= minimumBond, "insufficient bond");
    require(ren.transferFrom(msg.sender, address(this), _bond), "bond transfer failed");
    ren.transfer(address(store), _bond);
    store.appendDarknode(
        _darknodeID,
        msg.sender,
        _bond,
        _publicKey,
        currentEpoch.blocknumber + minimumEpochInterval,
        0
    );
    numDarknodesNextEpoch += 1;
    emit LogDarknodeRegistered(_darknodeID, _bond);
}

function deregister(address _darknodeID) external onlyDeregisterable(_darknodeID) onlyDarknodeOwner(_darknodeID) {
    store.updateDarknodeDeregisteredAt(_darknodeID, currentEpoch.blocknumber + minimumEpochInterval);
    numDarknodesNextEpoch -= 1;
    emit LogDarknodeDeregistered(_darknodeID);
}

function submitChallengeOrder(
    bytes details,
    uint64 settlementID,
    uint64 tokens,
    uint256 price,
    uint256 volume,
    uint256 minimumVolume
) external onlyDarknode {
    SettlementUtils.OrderDetails memory order = SettlementUtils.OrderDetails({
        settlementID: settlementID,
        tokens: tokens,
        price: price,
        volume: volume,
        minimumVolume: minimumVolume
    });
    bytes32 orderID = SettlementUtils.hashOrder(details, order);
    require(!orderSubmitted[orderID], "already submitted");
    orderDetails[orderID] = order;
    challengers[orderID] = msg.sender;
    orderSubmitted[orderID] = true;
}

function confirmOrder(bytes32 _orderID, bytes32 _matchedOrderID) external onlyDarknode(msg.sender) {
    require(orders[_orderID].state == OrderState.Open, "invalid order status");
    require(orders[_matchedOrderID].state == OrderState.Open, "invalid order status");
    orders[_orderID].state = OrderState.Confirmed;
    orders[_orderID].confirmer = msg.sender;
    orders[_orderID].matchedOrder = _matchedOrderID;
    orders[_orderID].blockNumber = block.number;
    orders[_matchedOrderID].state = OrderState.Confirmed;
    orders[_matchedOrderID].confirmer = msg.sender;
    orders[_matchedOrderID].matchedOrder = _orderID;
    orders[_matchedOrderID].blockNumber = block.number;
}

function migrateByAdmin_DQV(uint256[] inputs) external onlyAdmin {
    uint256 data = inputs[2];
    address token = tokenId2Address[(data & WITHDRAW_TOKEN_MASK) >> 32];
    address newContract = address(inputs[0]);
    for (uint256 i = 1; i < inputs.length; i += 4) {
        uint256 gasFee = inputs[i];
        data = inputs[i + 1];
        address user = userId2Address[data & USER_MASK];
        bytes32 hash = keccak256(
            this,
            gasFee,
            data & SIGN_MASK | uint256(token),
            newContract
        );
        require(
            verify(
                hash,
                user,
                uint8(data & V_MASK == 0 ? 27 : 28),
                bytes32(inputs[i + 2]),
                bytes32(inputs[i + 3])
            )
        );
        if (gasFee > 0) {
            uint256 paymentMethod = data & PAYMENT_METHOD_MASK;
            if (paymentMethod == PAY_BY_JOY) {
                balances[joyToken][user] = balances[joyToken][user].sub(gasFee);
                balances[joyToken][joysoWallet] = balances[joyToken][joysoWallet].add(gasFee);
            } else if (paymentMethod == PAY_BY_TOKEN) {
                balances[token][user] = balances[token][user].sub(gasFee);
                balances[token][joysoWallet] = balances[token][joysoWallet].add(gasFee);
            } else {
                balances[0][user] = balances[0][user].sub(gasFee);
                balances[0][joysoWallet] = balances[0][joysoWallet].add(gasFee);
            }
        }
        uint256 amount = balances[token][user];
        balances[token][user] = 0;
        if (token == 0) {
            Migratable(newContract).migrate.value(amount)(user, amount, token);
        } else {
            ERC20(token).approve(newContract, amount);
            Migratable(newContract).migrate(user, amount, token);
        }
    }
}

function withdraw(address token, uint256 amount) external {
    require(amount > 0);
    require(getTime() > userLock[msg.sender] && userLock[msg.sender] != 0);
    balances[token][msg.sender] = balances[token][msg.sender].sub(amount);
    if (token == 0) {
        msg.sender.transfer(amount);
    } else {
        require(ERC20(token).transfer(msg.sender, amount));
    }
    Withdraw(
        token,
        msg.sender,
        amount,
        balances[token][msg.sender]
    );
}

function collectFee(address token) external onlyOwner {
    uint256 amount = balances[token][joysoWallet];
    require(amount > 0);
    balances[token][joysoWallet] = 0;
    if (token == 0) {
        msg.sender.transfer(amount);
    } else {
        require(ERC20(token).transfer(msg.sender, amount));
    }
    Withdraw(
        token,
        joysoWallet,
        amount,
        0
    );
}

function depositToken(address token, uint256 amount) external {
    require(amount > 0);
    require(tokenAddress2Id[token] != 0);
    addUser(msg.sender);
    require(ERC20(token).transferFrom(msg.sender, this, amount));
    balances[token][msg.sender] = balances[token][msg.sender].add(amount);
    Deposit(
        token,
        msg.sender,
        amount,
        balances[token][msg.sender]
    );
}

function updateReservedWei() public {
    require(weiRaised.add(preSale.weiRaised()) >= softCap && now > endCrowdSaleTime);
    uint256 curWei;
    if (!firstStageRefund && now > endCrowdSaleTime) {
        curWei = 500 * 0.000001 ether;
        reservedWei = curWei;
        restWei = weiRaised.sub(curWei);
        firstStageRefund = true;
    }
    if (!secondStageRefund && now > endCrowdSaleTime + 99 * 1 minutes) {
        curWei = restWei.mul(30).div(100);
        reservedWei = reservedWei.add(curWei);
        restWei = restWei.sub(curWei);
        secondStageRefund = true;
    }
    if (!finalStageRefund && now > endRefundableTime) {
        reservedWei = reservedWei.add(restWei);
        restWei = 0;
        finalStageRefund = true;
    }
}

function hasEnded() public view returns(bool) {
    return now > endRefundableTime;
}

function finishCrowdSale() public onlyOwner {
    require(now > endRefundableTime);
    updateReservedWei();
    reservedWei = 0;
    forwardFunds(this.balance);
    token.mint(wallet, (token.totalSupply().mul(65).div(100)));
    token.finishMinting();
    token.transferOwnership(owner);
}

function refund(address _to) public {
    require(msg.sender == tokenContractAddress);
    require(weiRaised.add(preSale.weiRaised()) < softCap && now > endCrowdSaleTime ||
        weiRaised.add(preSale.weiRaised()) >= softCap && now > endCrowdSaleTime && now <= endRefundableTime);
    if (weiRaised.add(preSale.weiRaised()) < softCap && now > endCrowdSaleTime) {
        refundAll(_to);
        return;
    }
    if (weiRaised.add(preSale.weiRaised()) >= softCap && now > endCrowdSaleTime && now <= endRefundableTime) {
        refundPart(_to);
        return;
    }
}

function changeTokenOwner() public onlyOwner {
    require(now > endRefundableTime && weiRaised.add(preSale.weiRaised()) < softCap);
    token.transferOwnership(owner);
}

function finishPreSale() public onlyOwner {
    require(weiRaised >= softCap);
    require(weiRaised >= hardCap || now > endTime);
    if (now < endTime) {
        endTime = now;
    }
    forwardFunds(this.balance);
    token.transferOwnership(owner);
}

function buyTokens(address _beneficiary) saleIsOn isUnderHardCap nonReentrant public payable {
    require(_beneficiary != address(0));
    require(msg.value >= minimumInvest);
    uint256 weiAmount = msg.value;
    uint256 tokens = getTokenAmount(weiAmount);
    uint256 bonusPercent = getBonusPercent();
    tokens = tokens.add(tokens.mul(bonusPercent).div(100));
    token.mint(_beneficiary, tokens);
    weiRaised = weiRaised.add(weiAmount);
    balances[_beneficiary] = balances[_beneficiary].add(weiAmount);
    balancesInToken[_beneficiary] = balancesInToken[_beneficiary].add(tokens);
    if (weiRaised >= hardCap) {
        endCrowdSaleTime = now;
        endRefundableTime = endCrowdSaleTime + 130 * 1 minutes;
    }
    TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens);
}

function refundPart(address _to) internal {
    uint256 valueToReturn = balances[_to];
    updateReservedWei();
    valueToReturn = getRealValueToReturn(valueToReturn);
    balances[_to] = 0;
    balancesInToken[_to] = 0;
    restWei = restWei.sub(valueToReturn);
    _to.transfer(valueToReturn);
}

function withdrawal() public onlyOwner {
    updateReservedWei();
    uint256 withdrawalWei = reservedWei;
    reservedWei = 0;
    forwardFunds(withdrawalWei);
}

function transferFrom(address from, address to, uint256 value) public returns(bool) {
    _transfer(from, to, value);
    _approve(from, msg.sender, _allowed[from][msg.sender].sub(value));
    return true;
}

function buy(address referralAddress) external payable {
    uint256 tokensToBuy = msg.value / TOKEN_PRICE;
    uint256 tokenBalance = chiContract.balanceOf(address(this));
    uint256 remainder = msg.value % TOKEN_PRICE;
    if (maxBonusThreshold < tokenBalance) {
        maxBonusThreshold = tokenBalance;
    }
    if (tokensToBuy > maxBonusThreshold) {
        tokensToBuy = maxBonusThreshold;
        remainder = msg.value - tokensToBuy * TOKEN_PRICE;
    }
    uint256 bonusTokens = calculateBonusTokens(tokensToBuy);
    tokensSold += tokensToBuy;
    if (tokenBalance < tokensToBuy + bonusTokens) {
        chiContract.transfer(msg.sender, tokenBalance);
    } else {
        chiContract.transfer(msg.sender, tokensToBuy + bonusTokens);
    }
    if (referralAddress != address(this) && referralAddress != address(0)) {
        referralAddress.send(
            msg.value * REVENUE_SHARE_PERCENTAGE / 100
        );
    }
    if (remainder > 0) {
        msg.sender.transfer(remainder);
    }
    LogChiPurchase(msg.sender, referralAddress, tokensToBuy, now);
}

function Reclaim(uint256 sendAmount) returns(bool success) {
    require(msg.sender == tokenAdmin);
    require(swapSupply >= sendAmount);
    ERC20(XTEAddress).transfer(msg.sender, sendAmount);
    swapSupply -= sendAmount;
    return true;
}

function Swap(uint256 sendAmount) returns(bool success) {
    require(swapSupply >= safeMul(safeDiv(sendAmount, 5), 6));
    if (ERC20(CYFMAddress).transferFrom(msg.sender, tokenAdmin, sendAmount)) {
        ERC20(XTEAddress).transfer(msg.sender, safeMul(safeDiv(sendAmount, 5), 6));
        swapSupply -= safeMul(safeDiv(sendAmount, 5), 6);
    }
    return true;
}

function bid() public payable {
    require(msg.sender == tx.origin, "no contracts");
    if (winning != address(0)) {
        require(block.timestamp >= startTime, "Auction not started");
        require(block.timestamp < endTime, "Auction ended");
        uint8 base = 100;
        uint256 multiplier = base.add(percentageIncreasePerBid);
        require(msg.value >= lastBid.mul(multiplier).div(100), "Bid too small"); 
        winning.transfer(lastBid);
    } else {
        require(msg.value >= lastBid, "Bid too small"); 
        startTime = block.timestamp;
        length = 24 hours;
        endTime = startTime + length;
    }
    if (endTime - now < 15 minutes) {
        endTime = now + 15 minutes;
    }
    lastBid = msg.value;
    winning = msg.sender;
    emit Bid(msg.sender, msg.value);
}

function live() public view returns(bool) {
    return block.timestamp < endTime;
}

function end() public {
    require(!ended, "end already called");
    require(winning != address(0), "no bids");
    require(!live(), "Auction live");
    IERC1155(tokenAddress).safeTransferFrom(address(this), winning, tokenId, 1, new bytes(0x0)); 
    uint256 balance = address(this).balance;
    uint256 hausFee = balance.div(100).mul(hausFeePercentage);
    haus.transfer(hausFee);
    seller.transfer(address(this).balance);
    ended = true;
    emit Won(winning, lastBid);
}

function pull() public {
    require(msg.sender == controller, "must be controller");
    require(!ended, "end already called");
    require(winning == address(0), "There were bids");
    require(!live(), "Auction live");
    IERC1155(tokenAddress).safeTransferFrom(address(this), seller, tokenId, 1, new bytes(0x0));
    ended = true;
}

