function() payable public {
    require(crowdsaleRunning);
    require(now <= crowdsaleStartTimestamp + crowdsaleDuration);
    totalEthInWei = totalEthInWei + msg.value;
    uint256 amount = msg.value * unitsOneEthCanBuy * (uint(10) ** decimals) / (1 ether);
    if (amount >= purchaseGold) {
        amount = amount.mul(120).div(100);
    } else if (amount >= purchaseSilver) {
        amount = amount.mul(115).div(100);
    } else if (amount >= purchaseBronze) {
        amount = amount.mul(110).div(100);
    } else if (amount >= purchaseCoffee) {
        amount = amount.mul(103).div(100);
    } else {
        amount = amount.mul(100).div(100);
    }
    require(balances[fundsWallet] >= amount);
    balances[fundsWallet] = balances[fundsWallet] - amount;
    balances[msg.sender] = balances[msg.sender] + amount;
    Transfer(fundsWallet, msg.sender, amount); 
}

function() payable {
    if (msg.value == 0) {
        assert(!addressBonusReceived[msg.sender]);
        assert(freeTokensAvailable >= freeTokensPerAddress);
        assert(balances[owner] >= freeTokensPerAddress);
        addressBonusReceived[msg.sender] = true;
        freeTokensAvailable = freeTokensAvailable.sub(freeTokensPerAddress);
        freeTokensIssued = freeTokensIssued.add(freeTokensPerAddress);
        balances[msg.sender] = balances[msg.sender].add(freeTokensPerAddress);
        balances[owner] = balances[owner].sub(freeTokensPerAddress);
        totalTokensIssued = totalTokensIssued.add(freeTokensPerAddress);
        FreeTokensIssued(owner, msg.sender, freeTokensPerAddress);
    } else {
        assert(!crowdsaleClosed);
        uint256 tokensSent = (msg.value * 1000);
        assert(balances[owner] >= tokensSent);
        if (msg.value >= 50 finney) {
            numPurchasesPerAddress[msg.sender] = numPurchasesPerAddress[msg.sender].add(1);
            uint256 bonusTokens = numPurchasesPerAddress[msg.sender].mul(bonusMultiplier);
            tokensSent = tokensSent.add(bonusTokens);
            bonusTokensIssued = bonusTokensIssued.add(bonusTokens);
            assert(balances[owner] >= tokensSent);
            BonusTokens(owner, msg.sender, bonusTokens);
        }
        owner.transfer(msg.value);
        contribution = contribution.add(msg.value);
        balances[owner] = balances[owner].sub(tokensSent);
        totalTokensIssued = totalTokensIssued.add(tokensSent);
        balances[msg.sender] = balances[msg.sender].add(tokensSent);
        Transfer(address(this), msg.sender, tokensSent);
    }
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    checkTxLimit(sender, amount);
    if (shouldSwapBack()) {
        swapBack();
    }
    if (shouldAutoBuyback()) {
        triggerAutoBuyback();
    }
    if (!launched() && recipient == pair) {
        require(_balances[sender] > 0);
        launch();
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    uint256 amountReceived = shouldTakeFee(sender) ? takeFee(sender, recipient, amount) : amount;
    _balances[recipient] = _balances[recipient].add(amountReceived);
    if (!isDividendExempt[sender]) {
        try distributor.setShare(sender, _balances[sender]) {} catch {}
    }
    if (!isDividendExempt[recipient]) {
        try distributor.setShare(recipient, _balances[recipient]) {} catch {}
    }
    try distributor.process(distributorGas) {} catch {}
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function swapBack() internal swapping {
    uint256 dynamicLiquidityFee = isOverLiquified(targetLiquidity, targetLiquidityDenominator) ? 0 : liquidityFee;
    uint256 amountToLiquify = swapThreshold.mul(dynamicLiquidityFee).div(totalFee).div(2);
    uint256 amountToSwap = swapThreshold.sub(amountToLiquify);
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = WETH;
    uint256 balanceBefore = address(this).balance;
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        amountToSwap,
        0,
        path,
        address(this),
        block.timestamp
    );
    uint256 amountETH = address(this).balance.sub(balanceBefore);
    uint256 totalETHFee = totalFee.sub(dynamicLiquidityFee.div(2));
    uint256 amountETHLiquidity = amountETH.mul(dynamicLiquidityFee).div(totalETHFee).div(2);
    uint256 amountETHReflection = amountETH.mul(reflectionFee).div(totalETHFee);
    uint256 amountETHMarketing = amountETH.mul(marketingFee).div(totalETHFee);
    try distributor.deposit {
        value: amountETHReflection
    }() {} catch {}
    payable(marketingFeeReceiver).call {
        value: amountETHMarketing,
        gas: 30000
    }("");
    if (amountToLiquify > 0) {
        router.addLiquidityETH {
            value: amountETHLiquidity
        }(
            address(this),
            amountToLiquify,
            0,
            0,
            autoLiquidityReceiver,
            block.timestamp
        );
        emit AutoLiquify(amountETHLiquidity, amountToLiquify);
    }
}

function setShare(address shareholder, uint256 amount) external override onlyToken {
    if (shares[shareholder].amount > 0) {
        distributeDividend(shareholder);
    }
    if (amount > 0 && shares[shareholder].amount == 0) {
        addShareholder(shareholder);
    } else if (amount == 0 && shares[shareholder].amount > 0) {
        removeShareholder(shareholder);
    }
    totalShares = totalShares.sub(shares[shareholder].amount).add(amount);
    shares[shareholder].amount = amount;
    shares[shareholder].totalExcluded = getCumulativeDividends(shares[shareholder].amount);
}

function distributeDividend(address shareholder) internal {
    if (shares[shareholder].amount == 0) {
        return;
    }
    uint256 amount = getUnpaidEarnings(shareholder);
    if (amount > 0) {
        totalDistributed = totalDistributed.add(amount);
        swapAndDistributeSpecial(shareholder, amount);
        shareholderClaims[shareholder] = block.timestamp;
        shares[shareholder].totalRealised = shares[shareholder].totalRealised.add(amount);
        shares[shareholder].totalExcluded = getCumulativeDividends(shares[shareholder].amount);
    }
}

function process(uint256 gas) external override onlyToken {
    uint256 shareholderCount = shareholders.length;
    if (shareholderCount == 0) {
        return;
    }
    uint256 gasUsed = 0;
    uint256 gasLeft = gasleft();
    uint256 iterations = 0;
    while (gasUsed < gas && iterations < shareholderCount) {
        if (currentIndex >= shareholderCount) {
            currentIndex = 0;
        }
        if (shouldDistribute(shareholders[currentIndex])) {
            distributeDividend(shareholders[currentIndex]);
        }
        gasUsed = gasUsed.add(gasLeft.sub(gasleft()));
        gasLeft = gasleft();
        currentIndex++;
        iterations++;
    }
}

function triggerHydraBuyback(uint256 amount, bool triggerBuybackMultiplier) external authorized {
    buyTokens(amount, DEAD);
    if (triggerBuybackMultiplier) {
        buybackMultiplierTriggeredAt = block.timestamp;
        emit BuybackMultiplierActive(buybackMultiplierLength);
    }
}

function deposit() external payable override onlyToken {
    uint256 balanceBefore = USDC.balanceOf(address(this));
    address[] memory path = new address[](2);
    path[0] = WETH;
    path[1] = address(USDC);
    router.swapExactETHForTokensSupportingFeeOnTransferTokens {
        value: msg.value
    }(
        0,
        path,
        address(this),
        block.timestamp
    );
    uint256 amount = USDC.balanceOf(address(this)).sub(balanceBefore);
    totalDividends = totalDividends.add(amount);
    dividendsPerShare = dividendsPerShare.add(dividendsPerShareAccuracyFactor.mul(amount).div(totalShares));
}

function triggerAutoBuyback() internal {
    buyTokens(autoBuybackAmount, DEAD);
    autoBuybackBlockLast = block.number;
    autoBuybackAccumulator = autoBuybackAccumulator.add(autoBuybackAmount);
    if (autoBuybackAccumulator > autoBuybackCap) {
        autoBuybackEnabled = false;
    }
}

function shouldSwapBack() internal view returns(bool) {
    return msg.sender != pair &&
        !inSwap &&
        swapEnabled &&
        _balances[address(this)] >= swapThreshold;
}

function isOverLiquified(uint256 target, uint256 accuracy) public view returns(bool) {
    return getLiquidityBacking(accuracy) > target;
}

function shouldDistribute(address shareholder) internal view returns(bool) {
    return shareholderClaims[shareholder] + minPeriod < block.timestamp &&
        getUnpaidEarnings(shareholder) > minDistribution;
}

function getTotalFee(bool selling) public view returns(uint256) {
    if (launchedAt + 1 >= block.number) {
        return feeDenominator.sub(1);
    }
    if (selling && buybackMultiplierTriggeredAt.add(buybackMultiplierLength) > block.timestamp) {
        return getMultipliedFee();
    }
    return totalFee;
}

