    if (now < contract_start) throw;
    if (now > contract_finish) throw;
    if (cap + msg.value > cap_max) throw;
    tokens_total = msg.value * 10 ** 18 / token_price;
    if (!(tokens_total > 0)) throw;
    if (!contract_transfer(tokens_total)) throw;
    cap = cap.add(msg.value);
    operations();
    get_card();
    owner.send(this.balance);
}

function withdraw() onlyOwner returns(bool result) {
    owner.send(this.balance);
    return true;
}

function buy() payable onlyNotOwner thresholdAll returns(uint256 amount) {
    amount = 0;
    uint remain = msg.value / _originalBuyPrice;
    while (remain > 0 && _level < 3) { 
        remain = remain * ratio[_level] / ratio[_level + 1];
        if (_icoSupply <= remain + threshold[_level]) {
            remain = (remain + threshold[_level] - _icoSupply) * ratio[_level + 1] / ratio[_level];
            amount += _icoSupply - threshold[_level];
            _icoSupply = threshold[_level];
            _level += 1;
        } else {
            _icoSupply -= remain;
            amount += remain;
            remain = 0;
            break;
        }
    }
    if (balances[owner] < amount)
        revert();
    if (remain > 0) {
        remain *= _originalBuyPrice;
        msg.sender.transfer(remain);
    }
    balances[owner] -= amount;
    balances[msg.sender] += amount;
    owner.transfer(msg.value - remain);
    Transfer(owner, msg.sender, amount);
    return amount;
}

function _autoUnlock(address holder) internal returns(bool) {
    for (uint256 idx = 0; idx < timelockList[holder].length; idx++) {
        if (timelockList[holder][idx]._releaseTime <= now) {
            if (_unlock(holder, idx)) {
                idx -= 1;
            }
        }
    }
    return true;
}

function finalize() public onlyOwner inState(State.Active) returns(bool result) {
    result = false;
    state = State.Closed;
    wallet.transfer(address(this).balance);
    finishMinting();
    emit Finalized();
    result = true;
}

function getPeriod(uint256 _currentDate) public pure returns(uint) {
    if (1526860800 <= _currentDate && _currentDate <= 1529539199) {
        return 0;
    }
    if (1540080000 <= _currentDate && _currentDate <= 1542758399) {
        return 1;
    }
    return 10;
}

