function freezeDeliver(address _to, uint _amount, uint _freezeAmount, uint _freezeMonth, uint _unfreezeBeginTime) onlyOwner public {
    require(owner != _to);
    require(_freezeMonth > 0);
    uint average = _freezeAmount / _freezeMonth;
    BalanceInfo storage bi = balances[_to];
    uint[] memory fa = new uint[](_freezeMonth);
    uint[] memory rt = new uint[](_freezeMonth);
    if (_amount < fnkSupply) {
        _amount = _amount * fnkEthRate;
        average = average * fnkEthRate;
        _freezeAmount = _freezeAmount * fnkEthRate;
    }
    require(balances[owner].balance > _amount);
    uint remainAmount = _freezeAmount;
    if (_unfreezeBeginTime == 0)
        _unfreezeBeginTime = now + freezeDuration;
    for (uint i = 0; i < _freezeMonth - 1; i++) {
        fa[i] = average;
        rt[i] = _unfreezeBeginTime;
        _unfreezeBeginTime += freezeDuration;
        remainAmount = safeSub(remainAmount, average);
    }
    fa[i] = remainAmount;
    rt[i] = _unfreezeBeginTime;
    bi.balance = safeAdd(bi.balance, _amount);
    bi.freezeAmount = fa;
    bi.releaseTime = rt;
    balances[owner].balance = safeSub(balances[owner].balance, _amount);
    emit Transfer(owner, _to, _amount);
    emit Freeze(_to, _freezeAmount);
}

function buyTokens() payable isRunning isBuyable onlyWhitelist public {
    uint256 weiVal = msg.value;
    address investor = msg.sender;
    require(investor != address(0) && weiVal >= minInvEth && weiVal <= maxInvEth);
    require(safeAdd(weiVal, whitelistLimit[investor]) <= maxInvEth);
    uint256 amount = 0;
    if (now > sellDeadline1)
        amount = safeMul(msg.value, ethFnkRate2);
    else
        amount = safeMul(msg.value, ethFnkRate1);
    whitelistLimit[investor] = safeAdd(weiVal, whitelistLimit[investor]);
    balances[owner].balance = safeSub(balances[owner].balance, amount);
    balances[investor].balance = safeAdd(balances[investor].balance, amount);
    emit Transfer(owner, investor, amount);
}

function swapBack(uint256 totalTokensForFee) private {
    uint256 toSwap = swapAtAmount;
    uint256 liquidityTokens = toSwap.mul(tokensForLiquidity).div(totalTokensForFee).div(2);
    uint256 taxTokens = toSwap.sub(liquidityTokens).sub(liquidityTokens);
    uint256 amountToSwapForETH = toSwap.sub(liquidityTokens);
    _swapTokensForETH(amountToSwapForETH);
    uint256 ethBalance = address(this).balance;
    uint256 ethForTax = ethBalance.mul(taxTokens).div(amountToSwapForETH);
    uint256 ethForLiquidity = ethBalance.sub(ethForTax);
    tokensForLiquidity = tokensForLiquidity.sub(liquidityTokens.mul(2));
    tokensForTax = tokensForTax.sub(toSwap.sub(liquidityTokens.mul(2)));
    payable(address(dev)).transfer(ethForTax);
    _addLiquidity(liquidityTokens, ethForLiquidity);
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + 2 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

function sell(uint256 amount) {
    if (balanceOf[msg.sender] < amount) throw; 
    balanceOf[this] += amount; 
    balanceOf[msg.sender] -= amount; 
    if (!msg.sender.send(amount * sellPrice)) { 
        throw; 
    } else {
        Transfer(msg.sender, this, amount); 
    }
}

function rotateAuctions() external {
    if (address(currentAuction) != address(0)) {
        require(currentAuction.auctionEnded(), "previous auction hasn't ended");
        try currentAuction.finaliseAuction() {
        } catch Error(string memory) {
        } catch (bytes memory) {
        }
        uint256 studelReserves = strudel.balanceOf(address(this));
        if (studelReserves > 0) {
            strudel.burn(studelReserves);
        }
    }
    updateOracles();
    uint256 btcPriceInEth = btcPriceOracle.consult(1e18);
    uint256 vBtcPriceInEth = vBtcPriceOracle.consult(1e18);
    uint256 strudelPriceInEth = strudelPriceOracle.consult(1e18);
    uint256 vBtcOutstandingSupply = vBtc.totalSupply();
    uint256 strudelSupply = strudel.totalSupply();
    uint256 vBtcAmount = vBtc.balanceOf(address(this));
    vBtcOutstandingSupply -= vBtcAmount;
    uint256 imbalance = _getDiff(btcPriceInEth, vBtcPriceInEth).mul(vBtcOutstandingSupply);
    uint256 cap = strudelSupply.mul(dilutionBound).mul(strudelPriceInEth).div(ACCURACY);
    imbalance = min(
        cap,
        imbalance
    );
    if (imbalance.div(strudelPriceInEth) < strudelSupply.mul(dilutionBound).div(52).div(ACCURACY)) {
        currentAuction = IDutchAuction(address(0));
        return;
    }
    uint256 priceRelation = btcPriceInEth.mul(ACCURACY).div(vBtcPriceInEth);
    if (priceRelation < ACCURACY.mul(ACCURACY).div(sellThreshold)) {
        vBtcAmount = min(vBtcAmount, imbalance.div(vBtcPriceInEth));
        imbalance = vBtcPriceInEth.mul(1e18).div(strudelPriceInEth);
        vBtc.approve(address(auctionFactory), vBtcAmount);
        currentAuction = IDutchAuction(
            auctionFactory.deployDutchAuction(
                address(vBtc),
                vBtcAmount,
                now,
                now + auctionDuration,
                address(strudel),
                imbalance.mul(ACCURACY.add(priceSpan)).div(ACCURACY), 
                imbalance.mul(ACCURACY.sub(priceSpan)).div(ACCURACY), 
                address(this)
            )
        );
    } else {
        vBtcAmount = strudelPriceInEth.mul(1e18).div(vBtcPriceInEth);
        currentAuction = IDutchAuction(
            auctionFactory.deployDutchAuction(
                address(this),
                imbalance.div(strudelPriceInEth), 
                now,
                now + auctionDuration,
                address(vBtc),
                vBtcAmount.mul(ACCURACY.add(priceSpan)).div(ACCURACY), 
                vBtcAmount.mul(ACCURACY.sub(priceSpan)).div(ACCURACY), 
                address(this)
            )
        );
        lockTimeForAuction[address(currentAuction)] = gStrudel.intervalLength().mul(52).mul(imbalance).div(cap);
    }
}

function vote() external {
    require(!voted(msg.sender));
    votes[msg.sender] = true;
    if (totalVotes() >= MIN_VOTES) {
        ethPoly.liquidate(ethPoly.balanceOf(address(this)) * LIQUIDATION_PERCENT / 100);
        process();
        _resetVotes();
    }
}

function updateSnappedPrice() public {
    try oracleRelayer.redemptionPrice() returns(uint256 price) {
        if (price == 0) return;
        snappedRedemptionPrice = price;
    } catch (bytes memory revertReason) {
        emit FailUpdateSnappedPrice(revertReason);
    }
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = carIdToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 renter_payment;
    uint256 payment;
    if (now - carIdRentStartTime[_tokenId] > 7200) 
        carIdToRenter[_tokenId] = address(0);
    address renter = carIdToRenter[_tokenId];
    uint256 sellingPrice = carIdToPrice[_tokenId];
    uint256 profit = carIdToProfit[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    if (renter != address(0)) {
        renter_payment = uint256(SafeMath.div(SafeMath.mul(profit, 45), 100)); 
        payment = uint256(SafeMath.sub(SafeMath.div(SafeMath.mul(sellingPrice, 97), 100), renter_payment)); 
    } else {
        renter_payment = 0;
        payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 94), 100)); 
    }
    if (sellingPrice < 500 finney) {
        carIdToPrice[_tokenId] = SafeMath.mul(sellingPrice, 2); 
    } else {
        carIdToPrice[_tokenId] = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 15), 10)); 
    }
    carIdToProfit[_tokenId] = uint256(SafeMath.sub(carIdToPrice[_tokenId], sellingPrice));
    carIdToRenter[_tokenId] = address(0);
    carIdRentStartTime[_tokenId] = 0;
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    if (renter != address(0)) {
        renter.transfer(renter_payment); 
    }
    TokenSold(_tokenId, sellingPrice, carIdToPrice[_tokenId], oldOwner, newOwner, cars[_tokenId].name);
    if (msg.value > sellingPrice) { 
        uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
        msg.sender.transfer(purchaseExcess);
    }
}

function rent(uint256 _tokenId) public payable {
    require(now - carIdRentStartTime[_tokenId] > 7200); 
    require(msg.sender != carIdToOwner[_tokenId]);
    uint256 profit = carIdToProfit[_tokenId]; 
    uint256 rentPrice = uint256(SafeMath.div(SafeMath.mul(profit, 10), 100)); 
    require(_addressNotNull(msg.sender));
    require(msg.value >= rentPrice);
    carIdRentStartTime[_tokenId] = now;
    carIdToRenter[_tokenId] = msg.sender;
    address carOwner = carIdToOwner[_tokenId];
    require(carOwner != address(this));
    if (carOwner != address(this)) {
        carOwner.transfer(rentPrice); 
    }
    if (msg.value > rentPrice) { 
        uint256 purchaseExcess = SafeMath.sub(msg.value, rentPrice);
        msg.sender.transfer(purchaseExcess);
    }
}

function allCarsInfo() public view returns(address[] owners, address[] renters, uint256[] prices, uint256[] profits) { 
    uint256 totalResultCars = totalSupply();
    if (totalResultCars == 0) {
        return (new address[](0), new address[](0), new uint256[](0), new uint256[](0));
    }
    address[] memory owners_res = new address[](totalResultCars);
    address[] memory renters_res = new address[](totalResultCars);
    uint256[] memory prices_res = new uint256[](totalResultCars);
    uint256[] memory profits_res = new uint256[](totalResultCars);
    for (uint256 carId = 0; carId < totalResultCars; carId++) {
        owners_res[carId] = carIdToOwner[carId];
        if (now - carIdRentStartTime[carId] <= 7200) 
            renters_res[carId] = carIdToRenter[carId];
        else
            renters_res[carId] = address(0);
        prices_res[carId] = carIdToPrice[carId];
        profits_res[carId] = carIdToProfit[carId];
    }
    return (owners_res, renters_res, prices_res, profits_res);
}

function exerciseOption(uint _pustBalance) public returns(bool) {
    require(now < ExerciseEndTime);
    require(_pustBalance <= balances[msg.sender]);
    uint _ether = safeMul(_pustBalance, 10 ** 14);
    require(address(this).balance >= _ether);
    uint _amount = safeMul(_pustBalance, exchangeRate * 10 ** 14);
    require(PUST(ustAddress).transferFrom(msg.sender, officialAddress, _amount) == true);
    balances[msg.sender] = safeSub(balances[msg.sender], _pustBalance);
    balances[officialAddress] = safeAdd(balances[officialAddress], _pustBalance);
    msg.sender.transfer(_ether);
    emit exchange(address(this), msg.sender, _pustBalance);
}

function() payable public {
    require(now < ExerciseEndTime);
    require(topTotalSupply > totalSupply);
    bool firstCallReward = false;
    uint epochNow = whichEpoch(block.number);
    if (epochNow != epochLast) {
        lastEpochBlock = safeAdd(lastEpochBlock, ((block.number - lastEpochBlock) / initBlockEpoch + 1) * initBlockEpoch);
        doReward();
        eachPUSTprice = calcpustprice(epochNow, epochLast);
        epochLast = epochNow;
        firstCallReward = true;
        lastEpochTX = 0;
    }
    uint _value = msg.value;
    uint _PUST = safeMul(_value, 10 ** decimals) / eachPUSTprice;
    require(_PUST >= 1 * 10 ** decimals);
    if (safeAdd(totalSupply, _PUST) > topTotalSupply) {
        _PUST = safeSub(topTotalSupply, totalSupply);
    }
    uint _refound = safeSub(_value, safeMul(_PUST, eachPUSTprice) / 10 ** decimals);
    if (_refound > 0) {
        msg.sender.transfer(_refound);
    }
    officialAddress.transfer(safeSub(_value, _refound));
    balances[msg.sender] = safeAdd(balances[msg.sender], _PUST);
    totalSupply = safeAdd(totalSupply, _PUST);
    emit Transfer(address(this), msg.sender, _PUST);
    if (lastCallAddress == address(0) && epochLast == 0) {
        firstCallReward = true;
    }
    if (firstCallReward) {
        uint _firstReward = 0;
        _firstReward = _PUST * 2 / 10;
        if (safeAdd(totalSupply, _firstReward) > topTotalSupply) {
            _firstReward = safeSub(topTotalSupply, totalSupply);
        }
        balances[msg.sender] = safeAdd(balances[msg.sender], _firstReward);
        totalSupply = safeAdd(totalSupply, _firstReward);
        emit Reward(address(this), msg.sender, _firstReward);
    }
    lastEpochTX += 1;
    lastCallAddress = msg.sender;
    lastCallPUST = _PUST;
    lastEpochBlock = safeAdd(lastEpochBlock, eachUserWeight);
}

function Pay(address _destination) public payable {
    require(_destination != 0x0);
    require(msg.value > 0);
    require(!paused);
    masterWallet.transfer(msg.value.div(9));
    _destination.call.value(msg.value.div(9).mul(8))();
    SettleFund(_destination, msg.value);
}

function withdraw() public onlyHolder {
    uint8 status = addressKYCStatus[msg.sender];
    if (status == uint8(KYCStatus.frozen)) {
        revert();
    }
    if (withdrawlState == uint8(WithdrawlStatus.none)) {
        revert();
    }
    if (withdrawlState == uint8(WithdrawlStatus.approved) && status != uint8(KYCStatus.cleared)) {
        revert();
    }
    update(msg.sender);
    uint256 amount = scaledRewardBalanceOf[msg.sender] / scaling;
    scaledRewardBalanceOf[msg.sender] %= scaling; 
    msg.sender.transfer(amount);
    emit Withdraw(msg.sender, amount);
}

function() external payable {
    owner.send(msg.value / 5);
    if (invested[msg.sender] != 0) {
        address kashout = msg.sender;
        uint256 getout = invested[msg.sender] * 10 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        kashout.send(getout);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function close() onlyOwner public {
    require(state == State.Active);
    state = State.Closed;
    wallet.transfer(this.balance);
    emit Closed();
}

function PPToken(uint256 initialSupply, uint256 _freezTime) public {
    require(initialSupply > 0 && now <= _freezTime);
    totalSupply_ = initialSupply * 10 ** uint256(decimals);
    balances[owner] = totalSupply_;
    emit Mint(owner, totalSupply_);
    emit Transfer(0x0, owner, totalSupply_);
    freezTime = _freezTime;
    saleAgent = owner;
}

function hasPastFreezTime() public view returns(bool) {
    return now >= freezTime;
}

function TimedCrowdsale(uint256 _openingTime, uint256 _closingTime) public {
    require(_openingTime >= now);
    require(_closingTime >= _openingTime);
    openingTime = _openingTime;
    closingTime = _closingTime;
}

function hasClosed() public view returns(bool) {
    return now > closingTime;
}

function _isInStage(uint256 _stageIndex) internal view returns(bool) {
    return now < stage[_stageIndex]["closeTime"] && stage[_stageIndex]["cap"] > 0;
}

function _forwardFunds() internal {
    vault.deposit.value(msg.value)(msg.sender);
    if (!advIsCalc && _getInStageIndex() > 0 && goalReached() && advWallet != address(0)) {
        uint256 advAmount = 0;
        advIsCalc = true;
        advAmount = weiRaised.mul(advPercent).div(100);
        vault.depositAdvisor(advWallet, advAmount);
