function withDrawTokens(uint _planId, uint _depositId, uint _amount) public {
    require(whitelistAddresses[msg.sender] == true, "Only whitelisted user allowed to withdraw");
    require(islocked[msg.sender][_planId][_depositId] == false, "User account must be unlocked by owner to withdraw");
    uint balance = stakingPlan[msg.sender][_planId][_depositId];
    require(balance > 0, "Staking balance cannot be 0");
    require(_amount > 0, "Withdraw balance cannot be 0");
    require(_amount <= balance, "Withdraw balance cannot be greater than invested");
    kiiaToken.transfer(msg.sender, _amount);
    stakingPlan[msg.sender][_planId][_depositId] = 0;
    isStaking[msg.sender][_planId][_depositId] = false;
}

function depositTokens(uint _planId, uint _depositId, uint _amount) public {
    require(_amount > 0, "Amount cannot be 0");
    require(_depositId > 0, "Deposit ID cannot be 0");
    require(_planId > 0, "Plan id cannot be 0");
    require(whitelistAddresses[msg.sender] == true, "Only whitelisted user allowed to deposit");
    kiiaToken.transferFrom(msg.sender, address(this), _amount);
    stakingPlan[msg.sender][_planId][_depositId] = _amount;
    if (!hasStaked[msg.sender]) {
        stakers.push(msg.sender);
    }
    isStaking[msg.sender][_planId][_depositId] = true;
    hasStaked[msg.sender] = true;
    islocked[msg.sender][_planId][_depositId] = true;
}

function startSale(uint256 saleStart, uint256 saleStop) onlyOwner returns(bool success) {
