function ve_balance_at(address account, uint timestamp) public view returns(uint) {
    uint _epoch = ve(_veibff).user_point_epoch(account);
    uint _balance_at = 0;
    for (uint i = _epoch; i > 0; i--) {
        ve.Point memory _point = ve(_veibff).user_point_history(account, i);
        if (_point.ts <= timestamp) {
            int128 _bias = _point.bias - (_point.slope * int128(int(timestamp - _point.ts)));
            if (_bias > 0) {
                _balance_at = uint(int(_bias));
            }
            break;
        }
    }
    return _balance_at;
}

function _purchase(address user, uint16 packCount, address referrer) internal {
    require(packCount > 0);
    require(referrer != user);
    uint price = calculatePrice(basePrice(), packCount);
    require(msg.value >= price);
    Purchase memory p = Purchase({
        user: user,
        count: packCount,
        commit: uint64(block.number),
        randomness: 0,
        current: 0
    });
    uint id = purchases.push(p) - 1;
    emit PacksPurchased(id, user, packCount);
    if (referrer != address(0)) {
        uint commission = price / 10;
        referrer.transfer(commission);
        price -= commission;
        emit Referral(referrer, commission, user);
    }
    address(vault).transfer(price);
}

function claimMultiple(address pack, uint purchaseID) public returns(uint16, address) {
    require(isPriorPack(pack));
    uint length = getCardCount();
    PresalePackFour(pack).claim(purchaseID);
    uint lengthAfter = getCardCount();
    require(lengthAfter > length);
    uint16 cardDifference = uint16(lengthAfter - length);
    require(cardDifference % 5 == 0);
    uint16 packCount = cardDifference / 5;
    uint16 extra = packCount * multiplier;
    address lastCardOwner = old.ownerOf(lengthAfter - 1);
    Purchase memory p = Purchase({
        user: lastCardOwner,
        count: extra,
        commit: uint64(block.number),
        randomness: 0,
        current: 0
    });
    uint id = purchases.push(p) - 1;
    emit PacksPurchased(id, lastCardOwner, extra);
    pheonix.claimPheonix(lastCardOwner);
    emit Status(length, lengthAfter);
    if (packCount <= packLimit) {
        for (uint i = 0; i < cardDifference; i++) {
            migration.migrate(lengthAfter - 1 - i);
        }
    }
    return (extra, lastCardOwner);
}

function claim(uint id) public {
    Purchase storage p = purchases[id];
    require(canClaim);
    uint16 proto;
    uint16 purity;
    uint16 count = p.count;
    uint result = p.randomness;
    uint8 size = packSize();
    address user = p.user;
    uint16 current = p.current;
    require(result != 0); 
    require(count > 0);
    uint[] memory ids = new uint[](size);
    uint16 end = current + packsPerClaim() > count ? count : current + packsPerClaim();
    require(end > current);
    for (uint16 i = current; i < end; i++) {
        for (uint8 j = 0; j < size; j++) {
            (proto, purity) = getCardDetails(i, j, result);
            ids[j] = migration.createCard(user, proto, purity);
        }
        emit PackOpened(id, (i * size), user, ids);
    }
    p.current += (end - current);
}

function claim() canMint public payable returns(bool) {
    uint256 currentTime = now;
    require(validPurchaseTime(currentTime));
    require(msg.value >= priceClaim);
    address beneficiar = msg.sender;
    require(beneficiar != address(0));
    require(!mintingFinished);
    uint256 amount = calcAmount(beneficiar);
    require(amount <= balances[owner]);
    balances[beneficiar] = balances[beneficiar].add(amount);
    balances[owner] = balances[owner].sub(amount);
    tokenAllocated = tokenAllocated.add(amount);
    owner.transfer(msg.value);
    emit Mint(beneficiar, amount);
    emit Transfer(owner, beneficiar, amount);
    return true;
}

function validPurchaseTime(uint256 _currentTime) canMint public view returns(bool) {
    uint256 dayTime = _currentTime % 1 days;
    if (startTimeDay <= dayTime && dayTime <= endTimeDay) {
        return true;
    }
    return false;
}

function withdrawVested(address _withdrawTo) returns(uint amountWithdrawn) {
    require(msg.sender == LIFE_CHANGE_VESTING_WALLET);
    require(vestingAmount > 0);
    uint _elapsed = now.sub(vestingStart);
    uint _rate = vestingAmount.div(vestingDuration);
    uint _unlocked = _rate.mul(_elapsed);
    if (_unlocked > vestingAmount) {
        _unlocked = vestingAmount;
    }
    if (_unlocked <= vestingPaid) {
        amountWithdrawn = 0;
        return;
    }
    amountWithdrawn = _unlocked.sub(vestingPaid);
    vestingPaid = vestingPaid.add(amountWithdrawn);
    ledger.transfer(LIFE_CHANGE_VESTING_WALLET, _withdrawTo, amountWithdrawn);
    token.controllerTransfer(LIFE_CHANGE_VESTING_WALLET, _withdrawTo, amountWithdrawn);
}

function init() onlyOwner {
    require(!initialized);
    mintWithEvent(REWARDS_WALLET, 9 * (10 ** (9 + DECIMALS))); 
    mintWithEvent(CROWDSALE_WALLET, 900 * (10 ** (6 + DECIMALS))); 
    mintWithEvent(LIFE_CHANGE_WALLET, 100 * (10 ** (6 + DECIMALS))); 
    initialized = true;
}

function saleToken(address payable from, address payable admin, uint256 tokenId, uint256 amount, address token, uint256 _type, uint256 NOFToken) public payable {
    _saleToken(from, admin, tokenId, amount);
    if (_type == 721) {
        NFTBANK721 tok = NFTBANK721(token);
        if (checkOrder[tokenId][from] == true) {
            delete order_place[from][tokenId];
            checkOrder[tokenId][from] = false;
        }
        tok.tokenTransfer(from, msg.sender, tokenId);
        balances[tokenId][from] = balances[tokenId][from] - NOFToken;
        balances[tokenId][msg.sender] = NOFToken;
    } else {
        NFTBANK1155 tok = NFTBANK1155(token);
        tok.safeTransferFrom(from, msg.sender, tokenId, NOFToken);
        balances[tokenId][from] = balances[tokenId][from] - NOFToken;
        balances[tokenId][msg.sender] = balances[tokenId][msg.sender] + NOFToken;
        if (checkOrder[tokenId][from] == true) {
            if (balances[tokenId][from] == 0) {
                delete order_place[from][tokenId];
                checkOrder[tokenId][from] = false;
            }
        }
    }
}

function acceptBId(address bittoken, address from, address admin, uint256 amount, uint256 tokenId, address token, uint256 _type, uint256 NOFToken) public {
    _acceptBId(bittoken, from, admin, amount, tokenId);
    if (_type == 721) {
        NFTBANK721 tok = NFTBANK721(token);
        if (checkOrder[tokenId][msg.sender] == true) {
            delete order_place[msg.sender][tokenId];
            checkOrder[tokenId][msg.sender] = false;
        }
        tok.tokenTransfer(msg.sender, from, tokenId);
        balances[tokenId][msg.sender] = balances[tokenId][msg.sender] - NOFToken;
        balances[tokenId][from] = NOFToken;
    } else {
        NFTBANK1155 tok = NFTBANK1155(token);
        tok.safeTransferFrom(msg.sender, from, tokenId, NOFToken);
        balances[tokenId][from] = balances[tokenId][from] + NOFToken;
        balances[tokenId][msg.sender] = balances[tokenId][msg.sender] - NOFToken;
        if (checkOrder[tokenId][msg.sender] == true) {
            if (balances[tokenId][msg.sender] == 0) {
                delete order_place[msg.sender][tokenId];
                checkOrder[tokenId][msg.sender] = false;
            }
        }
    }
}

function mint(address token, string memory tokenuri, uint256 value, uint256 tokenId, uint256 royal, uint256 _type, uint256 supply) public {
    require(_creator[tokenId] == address(0), "Token Already Minted");
    if (_type == 721) {
        NFTBANK721 tok = NFTBANK721(token);
        _creator[tokenId] = msg.sender;
        _royal[tokenId] = royal;
        tok._mint(msg.sender, tokenId, tokenuri);
        balances[tokenId][msg.sender] = supply;
        if (value != 0) {
            _orderPlace(msg.sender, tokenId, value);
        }
    } else {
        NFTBANK1155 tok = NFTBANK1155(token);
        tok.mint(msg.sender, tokenId, supply, tokenuri);
        _creator[tokenId] = msg.sender;
        _royal[tokenId] = royal;
        balances[tokenId][msg.sender] = supply;
        if (value != 0) {
            _orderPlace(msg.sender, tokenId, value);
        }
    }
    tokenCount++;
}

function burn(address admin, uint256 tokenId, address token, uint256 _type, uint256 NOFToken) public {
    require(balances[tokenId][msg.sender] >= NOFToken || msg.sender == admin, "Your Not a Token Owner or insuficient Token Balance");
    if (_type == 721) {
        NFTBANK721 tok = NFTBANK721(token);
        tok._burn(tokenId, msg.sender, admin);
        balances[tokenId][msg.sender] = balances[tokenId][msg.sender].sub(NOFToken);
        if (checkOrder[tokenId][msg.sender] == true) {
            delete order_place[msg.sender][tokenId];
            checkOrder[tokenId][msg.sender] = false;
        }
        delete _creator[tokenId];
        delete _royal[tokenId];
    } else {
        NFTBANK1155 tok = NFTBANK1155(token);
        tok.burn(msg.sender, admin, tokenId, NOFToken);
        balances[tokenId][msg.sender] = balances[tokenId][msg.sender].sub(NOFToken);
        if (balances[tokenId][msg.sender] == NOFToken) {
            if (checkOrder[tokenId][msg.sender] == true) {
                delete order_place[msg.sender][tokenId];
                checkOrder[tokenId][msg.sender] = false;
            }
        }
    }
    tokenCount--;
}

function releaseOnce() public {
    bytes32 headKey = toKey(msg.sender, 0);
    uint64 head = chains[headKey];
    require(head != 0);
    require(uint64(block.timestamp) > head);
    bytes32 currentKey = toKey(msg.sender, head);
    uint64 next = chains[currentKey];
    uint amount = freezings[currentKey];
    delete freezings[currentKey];
    balances[msg.sender] = balances[msg.sender].add(amount);
    freezingBalance[msg.sender] = freezingBalance[msg.sender].sub(amount);
    if (next == 0) {
        delete chains[headKey];
    } else {
        chains[headKey] = next;
        delete chains[currentKey];
    }
    Released(msg.sender, amount);
}

