    require(FactoryOwner[_FactoryID] == msg.sender);
    require(balances[msg.sender] >= _tokens && _tokens > 0);
    FactoryPrice[_FactoryID] = FactoryPrice[_FactoryID] + _tokens * eftTOethRATE;
