}

function getCurrentPhaseIndex() view public returns(uint256) {
    for (uint i = 0; i < phases.length; i++) {
        if (phases[i].startDate <= now && now <= phases[i].endDate) {
            return i;
        }
    }
    revert();
}

function() public payable {
