function useChainlinkWithENS(address _ens, bytes32 _node)
internal {
    ens = ENSInterface(_ens);
    ensNode = _node;
    bytes32 linkSubnode = keccak256(abi.encodePacked(ensNode, ENS_TOKEN_SUBNAME));
    ENSResolver resolver = ENSResolver(ens.resolver(linkSubnode));
    setChainlinkToken(resolver.addr(linkSubnode));
    updateChainlinkOracleWithENS();
}

function updateChainlinkOracleWithENS()
internal {
    bytes32 oracleSubnode = keccak256(abi.encodePacked(ensNode, ENS_ORACLE_SUBNAME));
    ENSResolver resolver = ENSResolver(ens.resolver(oracleSubnode));
    setChainlinkOracle(resolver.addr(oracleSubnode));
}

function requestRateUpdate()
external
ensureAuthorizedRequester() {
    Chainlink.Request memory request;
    bytes32 requestId;
    uint256 oraclePayment = paymentAmount;
    for (uint i = 0; i < oracles.length; i++) {
        request = buildChainlinkRequest(jobIds[i], this, this.chainlinkCallback.selector);
        requestId = sendChainlinkRequestTo(oracles[i], request, oraclePayment);
        requestAnswers[requestId] = answerCounter;
    }
    answers[answerCounter].minimumResponses = minimumResponses;
    answers[answerCounter].maxResponses = uint128(oracles.length);
    answerCounter = answerCounter.add(1);
    emit NewRound(answerCounter, msg.sender);
}

function sendChainlinkRequestTo(address _oracle, Chainlink.Request memory _req, uint256 _payment)
internal
returns(bytes32 requestId) {
    requestId = keccak256(abi.encodePacked(this, requests));
    _req.nonce = requests;
    pendingRequests[requestId] = _oracle;
    emit ChainlinkRequested(requestId);
    require(link.transferAndCall(_oracle, _payment, encodeRequest(_req)), "unable to transferAndCall to oracle");
    requests += 1;
    return requestId;
}

function distribute(uint256 _percent)
public
isHuman() {
    require(_percent > 0 && _percent < 100, "please pick a percent between 1 and 99");
    address _pusher = msg.sender;
    uint256 _bal = address(this).balance;
    uint256 _mnPayout;
    uint256 _compressedData;
    if (
        pushers_[_pusher].tracker <= pusherTracker_.sub(100) && 
        pushers_[_pusher].time.add(1 hours) < now 
    ) {
        pushers_[_pusher].tracker = pusherTracker_;
        pusherTracker_++;
        if (H4Dcontract_.balanceOf(_pusher) >= H4Dcontract_.stakingRequirement())
            _mnPayout = (_bal / 10) / 3;
        uint256 _stop = (_bal.mul(100 - _percent)) / 100;
        H4Dcontract_.buy.value(_bal)(_pusher);
        H4Dcontract_.sell(H4Dcontract_.balanceOf(address(this)));
        uint256 _tracker = H4Dcontract_.dividendsOf(address(this));
        while (_tracker >= _stop) {
            H4Dcontract_.reinvest();
            H4Dcontract_.sell(H4Dcontract_.balanceOf(address(this)));
            _tracker = (_tracker.mul(81)) / 100;
        }
        H4Dcontract_.withdraw();
    } else {
        _compressedData = _compressedData.insert(1, 47, 47);
    }
    pushers_[_pusher].time = now;
    _compressedData = _compressedData.insert(now, 0, 14);
    _compressedData = _compressedData.insert(pushers_[_pusher].tracker, 15, 29);
    _compressedData = _compressedData.insert(pusherTracker_, 30, 44);
    _compressedData = _compressedData.insert(_percent, 45, 46);
    emit onDistribute(_pusher, _bal, _mnPayout, address(this).balance, _compressedData);
}

function AdvertisementPayout(uint advId) public {
    require(msg.sender == wallet);
    require(token.balanceOf(wallet) >= advertisementList[advId].amountToBePaid);
    require(advertisementList[advId].advertisementId == advId);
    require(advertisementList[advId].isUnlocked == true);
    require(advertisementList[advId].amountToBePaid > 0);
    uint j = 0;
    voters = advertisementVoterList[advertisementList[advId].advertisementId];
    localIntAsPerNeed = voteAdvertismentPayoutSchemeObj.voterPercentage;
    uint voterPayout = advertisementList[advId].amountToBePaid.mul(localIntAsPerNeed);
    voterPayout = voterPayout.div(100);
    uint perVoterPayout = voterPayout.div(voters.length);
    localIntAsPerNeed = voteAdvertismentPayoutSchemeObj.systemPercentage;
    uint systemPayout = advertisementList[advId].amountToBePaid.mul(localIntAsPerNeed);
    systemPayout = systemPayout.div(100);
    for (j = 0; j < voters.length; j++) {
        token.mint(wallet, voters[j].publicKey, perVoterPayout);
        voters[j].amountEarned = voters[j].amountEarned.add(perVoterPayout);
        advertisementList[advId].amountToBePaid = advertisementList[advId].amountToBePaid.sub(perVoterPayout);
    }
    advertisementList[advId].amountToBePaid = advertisementList[advId].amountToBePaid.sub(systemPayout);
    require(advertisementList[advId].amountToBePaid == 0);
}

function uploadAdvertisement(uint adId, string advLink, address advertiserAddress, uint uploadTokenAmount) public {
    require(msg.sender == wallet);
    token.mint(advertiserAddress, wallet, uploadTokenAmount * 10 ** 18); 
    advertisement = Advertisement({
        advertiser: advertiserAddress,
        advertisementId: adId,
        advertisementLink: advLink,
        amountToBePaid: uploadTokenAmount * 10 ** 18,
        isUnlocked: false
    });
    advertisementList[adId] = advertisement;
}

