function useSingleItem(uint _tokenId, uint _target, uint _param) isActive requireAdventureHandler public {
    if (_tokenId == 0 || tokenOwner[_tokenId] != msg.sender) revert();
    Item storage item = items[_tokenId];
    EtheremonAdventureHandler handler = EtheremonAdventureHandler(adventureHandler);
    handler.handleSingleItem(msg.sender, item.classId, item.value, _target, _param);
    _burn(msg.sender, _tokenId);
}

function useMultipleItem(uint _token1, uint _token2, uint _token3, uint _target, uint _param) isActive requireAdventureHandler public {
    if (_token1 > 0 && tokenOwner[_token1] != msg.sender) revert();
    if (_token2 > 0 && tokenOwner[_token2] != msg.sender) revert();
    if (_token3 > 0 && tokenOwner[_token3] != msg.sender) revert();
    Item storage item1 = items[_token1];
    Item storage item2 = items[_token2];
    Item storage item3 = items[_token3];
    EtheremonAdventureHandler handler = EtheremonAdventureHandler(adventureHandler);
    handler.handleMultipleItems(msg.sender, item1.classId, item2.classId, item3.classId, _target, _param);
    if (_token1 > 0) _burn(msg.sender, _token1);
    if (_token2 > 0) _burn(msg.sender, _token2);
    if (_token3 > 0) _burn(msg.sender, _token3);
}

function _calculateNonVestedTokens(
    uint256 tokens,
    uint256 time,
    uint256 start,
    uint256 cliff,
    uint256 vested
)
private
pure
returns(uint256) {
    if (time >= vested) {
        return 0;
    }
    if (time < cliff) {
        return tokens;
    }
    uint256 vestedTokens = tokens.mul(time.sub(start)) / vested.sub(start);
    return tokens.sub(vestedTokens);
}

function revokeVesting(address _holder, uint256 _vestingId)
external
authP(REVOKE_VESTINGS_ROLE, arr(_holder))
vestingExists(_holder, _vestingId) {
    TokenVesting storage v = vestings[_holder][_vestingId];
    require(v.revokable, ERROR_VESTING_NOT_REVOKABLE);
    uint256 nonVested = _calculateNonVestedTokens(
        v.amount,
        getTimestamp(),
        v.start,
        v.cliff,
        v.vesting
    );
    delete vestings[_holder][_vestingId];
    require(token.transferFrom(_holder, address(this), nonVested), ERROR_REVOKE_TRANSFER_FROM_REVERTED);
    emit RevokeVesting(_holder, _vestingId, nonVested);
}

function transferToVault(address _token) public {
    require(allowRecoverability(_token), ERROR_DISALLOWED);
    address vault = getRecoveryVault();
    require(isContract(vault), ERROR_VAULT_NOT_CONTRACT);
    uint256 balance;
    if (_token == ETH) {
        balance = address(this).balance;
        vault.transfer(balance);
    } else {
        ERC20 token = ERC20(_token);
        balance = token.staticBalanceOf(this);
        require(token.safeTransfer(vault, balance), ERROR_TOKEN_TRANSFER_FAILED);
    }
    emit RecoverToVault(vault, _token, balance);
}

function initialize(
    MiniMeToken _token,
    bool _transferable,
    uint256 _maxAccountToken
)
external
onlyInit {
    initialized();
    require(_token.controller() == address(this), ERROR_TOKEN_CONTROLLER);
    token = _token;
    maxAccountTokens = _maxAccountToken == 0 ? uint256(-1) : _maxAccountToken;
    if (token.transfersEnabled() != _transferable) {
        token.enableTransfers(_transferable);
    }
}

function assignVested(
    address _receiver,
    uint256 _amount,
    uint64 _start,
    uint64 _cliff,
    uint64 _vested,
    bool _revokable
)
external
authP(ASSIGN_ROLE, arr(_receiver, _amount))
returns(uint256) {
    require(_receiver != address(this), ERROR_VESTING_TO_TM);
    require(vestingsLengths[_receiver] < MAX_VESTINGS_PER_ADDRESS, ERROR_TOO_MANY_VESTINGS);
    require(_start <= _cliff && _cliff <= _vested, ERROR_WRONG_CLIFF_DATE);
    uint256 vestingId = vestingsLengths[_receiver]++;
    vestings[_receiver][vestingId] = TokenVesting(
        _amount,
        _start,
        _cliff,
        _vested,
        _revokable
    );
    _assign(_receiver, _amount);
    emit NewVesting(_receiver, vestingId, _amount);
    return vestingId;
}

function buyTicketsFor(address _beneficiary) public payable {
    require(_beneficiary != 0x0);
    require(msg.value >= PRICE);
    uint256 change = msg.value % PRICE;
    uint256 numberOfTickets = msg.value.sub(change).div(PRICE);
    ticket.mint(_beneficiary, numberOfTickets);
    addParticipant(_beneficiary, numberOfTickets);
    msg.sender.transfer(change);
}

function awardPrizes() private {
    uint256 winnerIndex = uint256(block.blockhash(block.number - 1)) % SIZE;
    uint256 jackpotNumber = uint256(block.blockhash(block.number - 1)) % JACKPOT_CHANCE;
    if (winnerIndex == jackpotNumber) {
        distributeJackpot(winnerIndex);
    }
    for (uint8 i = 0; i < prizes.length; i++) {
        participants[gameNumber][winnerIndex % SIZE].transfer(prizes[i]); 
        PrizeAwarded(gameNumber, participants[gameNumber][winnerIndex % SIZE], prizes[i]);
        winnerIndex++;
    }
}

function distributeJackpot(uint256 _winnerIndex) private {
    uint256 amount = jackpotAmount;
    jackpotAmount = 0; 
    participants[gameNumber][_winnerIndex].transfer(amount);
    JackpotAwarded(gameNumber, participants[gameNumber][_winnerIndex], amount);
}

function addParticipant(address _participant, uint256 _numberOfTickets) private {
    for (uint256 i = 0; i < _numberOfTickets; i++) {
        participants[gameNumber][counter % SIZE] = _participant;
        ParticipantAdded(_participant, gameNumber, counter % SIZE);
        if (++counter % SIZE == 0) {
            awardPrizes();
            distributeRemaining();
            increaseGame();
        }
    }
}

function refundGameAfterLongInactivity() public {
    require(block.number.sub(gameStartedAt) >= INACTIVITY);
    require(counter % SIZE != 0); 
    uint256 _size = counter % SIZE; 
    counter -= _size;
    for (uint8 i = 0; i < _size; i++) {
        participants[gameNumber][i].transfer(PRICE);
    }
    GameRefunded(gameNumber);
    increaseGame();
}

function createTokens() saleIsOn payable {
    multisig.transfer(msg.value);
    uint tokens = rate.mul(msg.value).div(1 ether);
    uint bonusTokens = 0;
    if (now < start + (period * 1 days).div(4)) {
        bonusTokens = tokens.div(5);
    } else if (now >= start + (period * 1 days).div(4) && now < start + (period * 1 days).div(4).mul(2)) {
        bonusTokens = tokens.div(10);
    } else if (now >= start + (period * 1 days).div(4).mul(2) && now < start + (period * 1 days).div(4).mul(3)) {
        bonusTokens = tokens.div(20);
    } else if (now >= start + (period * 1 days).div(4).mul(3) && now < start + (period * 1 days).div(4).mul(4)) {
        bonusTokens = tokens.div(50);
    }
    uint tokensWithBonus = tokens.add(bonusTokens);
    token.transfer(msg.sender, tokensWithBonus);
    uint restrictedTokens = tokens.mul(restrictedPercent).div(100 - restrictedPercent);
    token.transfer(restricted, restrictedTokens);
}

function release() onlyOwner public {
    uint toRelease = calculateVestedAmount().sub(released);
    uint left = token.balanceOf(this);
    if (left < toRelease) {
        toRelease = left;
    }
    require(toRelease > 0, "nothing to release");
    released = released.add(toRelease);
    require(token.transfer(msg.sender, toRelease));
    emit Released(toRelease);
}

function() payable afterDeadline {
    uint weiAmount = msg.value;
    if (weiAmount == 0) {
        throw;
    }
    if (investors[msg.sender] != weiAmount) {
        throw;
    }
    uint tokenAmount = weiAmount.mul(tokenExchangeRate);
    if (!notaryToken.transferFrom(owner, msg.sender, tokenAmount)) {
        throw;
    } else {
        distributed = distributed.add(tokenAmount);
        transferred = transferred.add(weiAmount);
    }
    if (!multisigWallet.send(weiAmount)) throw;
    Invested(msg.sender, weiAmount, tokenAmount);
}

function setEndsAt(uint time) public onlyOwner {
    if (now > time) {
        throw; 
    }
    deadline = time;
    EndsAtChanged(deadline);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (
        overMinTokenBalance &&
        !inSwapAndLiquify &&
        from != uniswapV2Pair &&
        swapAndLiquifyEnabled
    ) {
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    bool isTransferBuy = from == uniswapV2Pair;
    bool isTransferSell = to == uniswapV2Pair;
    if (!isTransferBuy && !isTransferSell) takeFee = false;
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee();
}

