    require(token.transferFrom(msg.sender, address(recipientAddress), uint256(amount) * 10 ** 18), 'Transfer ERROR');
    balances[msg.sender] = SafeMath.add(balances[msg.sender], uint256(amount) * 10 ** 18);
}

function kill() {
    if (msg.sender == creator && now >= unlockTime)
        selfdestruct(creator);
}

function transferToContract(address _to, uint _value, bytes _data) private returns(bool success) {
    if (msg.sender == _to) return mint();
    if (balanceOf(msg.sender) < _value) revert();
    balances[msg.sender] = balanceOf(msg.sender).sub(_value);
    balances[_to] = balanceOf(_to).add(_value);
    ContractReceiver reciever = ContractReceiver(_to);
    reciever.tokenFallback(msg.sender, _value, _data);
    if (transferIns[msg.sender].length > 0) delete transferIns[msg.sender];
    uint64 _now = uint64(now);
    transferIns[msg.sender].push(transferInStruct(uint128(balances[msg.sender]), _now));
    transferIns[_to].push(transferInStruct(uint128(_value), _now));
    Transfer(msg.sender, _to, _value);
    ERC223Transfer(msg.sender, _to, _value, _data);
    return true;
}

function getCoinAge(address _address, uint _now) internal view returns(uint _coinAge) {
    if (transferIns[_address].length <= 0) return 0;
    for (uint i = 0; i < transferIns[_address].length; i++) {
        if (_now < uint(transferIns[_address][i].time).add(stakeMinAge)) continue;
        uint nCoinSeconds = _now.sub(uint(transferIns[_address][i].time));
        if (nCoinSeconds > stakeMaxAge) nCoinSeconds = stakeMaxAge;
        _coinAge = _coinAge.add(uint(transferIns[_address][i].amount) * nCoinSeconds.div(1 days));
    }
}

function annualInterest() public view returns(uint interest) {
    uint _now = now;
    interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)).div(365 days) == 0) {
        interest = (770 * maxMintProofOfStake).div(100);
    } else if ((_now.sub(stakeStartTime)).div(365 days) == 1) {
        interest = (435 * maxMintProofOfStake).div(100);
    }
}

function getProofOfStakeReward(address _address) internal view returns(uint) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint _now = now;
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    uint interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime)).div(365 days) == 0) {
        interest = (770 * maxMintProofOfStake).div(100);
    } else if ((_now.sub(stakeStartTime)).div(365 days) == 1) {
        interest = (435 * maxMintProofOfStake).div(100);
    }
    uint offset = 10 ** uint(decimals);
    return (_coinAge * interest).div(365 * offset);
}

function forgiveThis(address scammer) private returns(bool success) {
    uint256 forgivenessAmount = msg.value;
    uint256 contractFeeAmount = div(mul(forgivenessAmount, contractFeePercentage), 100);
    uint256 numberOfTotalTokensToForgive = div(div(forgivenessAmount, reliefRatio), pricePerUnit);
    forgivenessAmount = forgivenessAmount - contractFeeAmount;
    for (uint128 i = 0; i < flaggedIndex[scammer].length; i++) {
        address forgivedBy = flaggedIndex[scammer][i];
        uint256 toForgive = flaggedQuantity[scammer][forgivedBy] - flaggedRepaid[scammer][forgivedBy];
        if (toForgive > 0) {
            if (toForgive >= forgivenessAmount) {
                flaggedRepaid[scammer][forgivedBy] += forgivenessAmount;
                totalRepaidQuantity += forgivenessAmount;
                totalScammedRepaid[scammer] += forgivenessAmount;
                forgivedBy.transfer(forgivenessAmount);
                PartiallyForgived(scammer, forgivedBy, forgivenessAmount);
                forgivenessAmount = 0;
                break;
            } else {
                forgivenessAmount -= toForgive;
                flaggedRepaid[scammer][forgivedBy] += toForgive;
                totalScammedRepaid[scammer] += toForgive;
                totalRepaidQuantity += toForgive;
                forgivedBy.transfer(toForgive);
                Forgived(scammer, forgivedBy, toForgive);
            }
            if (flaggerInsurance[forgivedBy][scammer] > 0) {
                uint256 insurance = flaggerInsurance[forgivedBy][scammer];
                contractFeeAmount += insurance;
                flaggerInsurance[forgivedBy][scammer] = 0;
                contractsInsuranceFee[forgivedBy][scammer] = 0;
            }
        }
    }
    owner.transfer(contractFeeAmount);
    theScamSealToken.transferBack(scammer, numberOfTotalTokensToForgive);
    if (forgivenessAmount > 0) {
        msg.sender.transfer(forgivenessAmount);
    }
    return true;
}

function forgiveIt(address scammer) {
    if (flaggerInsurance[msg.sender][scammer] > 0) {
        uint256 insurance = flaggerInsurance[msg.sender][scammer];
        uint256 hadFee = contractsInsuranceFee[msg.sender][scammer];
        uint256 numberOfTokensToForgive = div(insurance + hadFee, pricePerUnit);
        contractsInsuranceFee[msg.sender][scammer] = 0;
        flaggerInsurance[msg.sender][scammer] = 0;
        totalScammed[scammer] -= flaggedQuantity[scammer][msg.sender];
        totalScammedQuantity -= flaggedQuantity[scammer][msg.sender];
        flaggedQuantity[scammer][msg.sender] = 0;
        theScamSealToken.transferBack(scammer, numberOfTokensToForgive);
        msg.sender.transfer(insurance);
        Forgived(scammer, msg.sender, insurance + hadFee);
    }
}

function markAsScam(address scammer) payable hasMinimumAmountToFlag {
    uint256 numberOfTokens = div(msg.value, pricePerUnit);
    updateFlagCount(msg.sender, scammer, numberOfTokens);
    uint256 ownersFee = div(mul(msg.value, contractFeePercentage), 100); 
    uint256 insurance = msg.value - ownersFee;
    owner.transfer(ownersFee);
    flaggerInsurance[msg.sender][scammer] += insurance;
    contractsInsuranceFee[msg.sender][scammer] += ownersFee;
    theScamSealToken.transfer(scammer, numberOfTokens);
    uint256 q = mul(reliefRatio, mul(msg.value, pricePerUnit));
    MarkedAsScam(scammer, msg.sender, q);
}

function getLockedAmount_contributors(address _contributor)
public
constant
returns(uint256) {
    uint256 countdownDate = contributors_countdownDate[_contributor];
    uint256 lockedAmt = contributors_locked[_contributor];
    if (now <= countdownDate + 1 hours) {
        return lockedAmt;
    }
    if (now <= countdownDate + 2 hours) {
        return lockedAmt.mul(7).div(8);
    }
    if (now <= countdownDate + 3 hours) {
        return lockedAmt.mul(6).div(8);
    }
    if (now <= countdownDate + 4 hours) {
        return lockedAmt.mul(5).div(8);
    }
    if (now <= countdownDate + 5 hours) {
        return lockedAmt.mul(4).div(8);
    }
    if (now <= countdownDate + 6 hours) {
        return lockedAmt.mul(3).div(8);
    }
    if (now <= countdownDate + 7 hours) {
        return lockedAmt.mul(2).div(8);
    }
    if (now <= countdownDate + 8 hours) {
        return lockedAmt.mul(1).div(8);
    }
    return 0;
}

function getLockedAmount_investors(address _investor)
public
constant
returns(uint256) {
    uint256 delieveryDate = investors_deliveryDate[_investor];
    uint256 lockedAmt = investors_locked[_investor];
    if (now <= delieveryDate) {
        return lockedAmt;
    }
    if (now <= delieveryDate + 1 hours) {
        return lockedAmt.mul(2).div(3);
    }
    if (now <= delieveryDate + 2 hours) {
        return lockedAmt.mul(1).div(3);
    }
    return 0;
}

function daily_Income() public returns(bool) {
    uint256 d;
    user memory obj = users[msg.sender];
    uint256 t = obj.total_Days;
    uint256 p = obj.total_Amount;
    require(obj.expirePeriod == false, "your seesion has expired");
    uint256 time = now - obj.creationTime;
    uint256 daysCount = time.div(86400);
    users[msg.sender].total_Days += daysCount;
    t += daysCount;
    require(isInvested[msg.sender] == true);
    uint256 c = (invested[msg.sender].mul(1)).div(100);
    d = c.mul(daysCount);
    users[msg.sender].total_Amount += d;
    p += d;
    if (t >= 401 || p >= invested[msg.sender].mul(4)) {
        session = session_Expire();
        return true;
    } else {
        users[msg.sender].earning += d;
        if (obj.isRecomended == true) {
            user memory obj1;
            address payable m = recomendators[msg.sender];
            obj1 = users[m];
            if (obj1.expirePeriod == false) {
                users[m].earning += d;
                users[m].total_Amount += d;
                users[m].ref_Income += d;
            }
            if (obj1.isRecomended == true) {
                uint256 f = (d.mul(10)).div(100);
                uint256 depth = 1;
                down_Income(m, depth, f);
            }
        }
        if (daysCount > 0) {
            users[msg.sender].creationTime = now;
        }
    }
    return true;
}

function Reinvest() public payable reinvest returns(bool) {
    require(users[msg.sender].expirePeriod == true, "your session should be new");
    require(isInvested[msg.sender] == false); 
    invested[msg.sender] = msg.value;
    isInvested[msg.sender] = true;
    users[msg.sender].creationTime = now;
    users[msg.sender].expirePeriod = false;
    users[msg.sender].visit += 1;
    users[msg.sender].total_Withdraw = 0;
    return true;
}

function reffer(uint256 _refference) public payable onlyFirst(_refference) returns(bool) {
    require(msg.value == 0.25 ether, "you are new one ans start with 0.25 ether");
    require(users[msg.sender].visit == 0, "you are already investor");
    cuurUserID++;
    userAddress[cuurUserID] = msg.sender;
    isInvested[msg.sender] = true;
    invested[msg.sender] = msg.value;
    user memory obj = user({
        isExist: true,
        earning: 0,
        recomendation: 0,
        creationTime: now,
        total_Days: 0,
        isRecomended: true,
        id: cuurUserID,
        total_Amount: 0,
        level: 0,
        referBy: _refference,
        expirePeriod: false,
        visit: 1,
        ref_Income: 0,
        total_Withdraw: 0,
        reffrals: new address[](0)
    });
    userList.push(obj);
    users[msg.sender] = obj;
    commission = (msg.value.mul(10)).div(100);
    Creators(commission);
    address payable a = userAddress[_refference];
    recomendators[msg.sender] = a;
    users[a].reffrals.push(msg.sender);
    users[a].recomendation += 1;
    if (users[a].level < 1) {
        users[a].level = 1;
    }
    emit Recommend(msg.sender, a, _refference);
    return true;
}

function withDraw(uint256 _value) public payable returns(string memory) {
    address payable r = msg.sender;
    user memory obj = users[r];
    require(obj.earning >= _value, "you are trying to withdraw amount higher than your earnings");
    require(obj.earning > 0, "your earning is 0");
    require(address(this).balance > _value, "contract has less amount");
    require(obj.total_Withdraw < invested[msg.sender].mul(4), "you are already withdraw all amount");
    if (obj.earning.add(obj.total_Withdraw) > invested[msg.sender].mul(4)) {
        uint256 h = obj.earning;
        uint256 x = (invested[msg.sender].mul(4)).sub(obj.total_Withdraw);
        uint256 a = obj.earning.sub(x);
        h = h.sub(a);
        r.transfer(h);
        users[msg.sender].earning = 0;
        users[msg.sender].total_Withdraw = obj.total_Withdraw.add(h);
        session = session_Expire();
        return "you have WithDraw all your profit";
    } else {
        users[msg.sender].total_Withdraw = obj.total_Withdraw.add(_value);
        users[msg.sender].earning = obj.earning.sub(_value);
        r.transfer(_value);
        return "you have succesfully WithDrawl your money";
    }
}

