function claimMultiple(address pack, uint purchaseID) public returns(uint16, address) {
    require(isPriorPack(pack));
    uint length = getCardCount();
    PresalePackThree(pack).claim(purchaseID);
    uint lengthAfter = getCardCount();
    require(lengthAfter > length);
    uint16 cardDifference = uint16(lengthAfter - length);
    require(cardDifference % 5 == 0);
    uint16 packCount = cardDifference / 5;
    uint16 extra = packCount * multiplier;
    address lastCardOwner = old.ownerOf(lengthAfter - 1);
    Purchase memory p = Purchase({
        user: lastCardOwner,
        count: extra,
        commit: uint64(block.number),
        randomness: 0,
        current: 0
    });
    uint id = purchases.push(p) - 1;
    emit PacksPurchased(id, lastCardOwner, extra);
    pheonix.claimPheonix(lastCardOwner);
    emit Status(length, lengthAfter);
    if (packCount <= packLimit) {
        for (uint i = 0; i < cardDifference; i++) {
            migration.migrate(lengthAfter - 1 - i);
        }
    }
    return (extra, lastCardOwner);
}

function settle(bytes32 channelId) public {
    require(canSettle(channelId));
    PaymentChannel storage channel = channels[channelId];
    channel.sender.transfer(channel.value);
    delete channels[channelId];
    DidSettle(channelId);
}

function claim(bytes32 channelId, uint256 payment, bytes signature) public {
    require(canClaim(channelId, payment, msg.sender, signature));
    PaymentChannel memory channel = channels[channelId];
    if (payment >= channel.value) {
        channel.receiver.transfer(channel.value);
    } else {
        channel.receiver.transfer(payment);
        channel.sender.transfer(channel.value.sub(payment));
    }
    delete channels[channelId];
    DidClaim(channelId);
}

function mintPredefinedTokens() external onlyOwner {
    require(!mintingFinished);
    require(weiRaised > 0);
    for (uint i = 0; i < beneficiaries.length; i++) {
        if (beneficiaries[i] != address(0) && token.balanceOf(beneficiaries[i]) == 0) {
            token.mint(beneficiaries[i], beneficiaryAmounts[i]);
        }
    }
    mintingFinished = true;
}

function validPurchase() internal view returns(bool) {
    bool withinCap = weiRaised.add(msg.value) <= cap;
    return withinCap && super.validPurchase();
}

function Crowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet, MintableToken _token) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != address(0));
    require(_token != address(0));
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
    token = _token;
}

function setCap(uint256 _cap) external onlyOwner {
    require(weiRaised == 0 && now <= startTime);
    require(_cap > 0);
    cap = _cap;
}

function setRate(uint256 _rate) external onlyOwner {
    require(weiRaised == 0 && now <= startTime);
    require(_rate > 0);
    rate = _rate;
}

function hasEnded() public view returns(bool) {
    bool capReached = weiRaised >= cap;
    return capReached || super.hasEnded();
}

function sendAwardToLastWinner() public isEnded {
    address(winnerList[winnerList.length - 1]).transfer(award);
    delete winnerList[winnerList.length - 1];
    winnerList.length--;
    if (winnerList.length == 0) {
        address add = address(officialAddress);
        address(add).transfer(address(this).balance);
    }
}

function() external payable isAct {
    require(raiseOption >= 0);
    uint256 buyNum = msg.value / 10000 * raiseOption;
    require(buyNum <= balanceOf[management]);
    balanceOf[management] -= buyNum;
    balanceOf[msg.sender] += buyNum;
    management.transfer(msg.value);
    emit SendEth(management, msg.value);
    emit Transfer(management, msg.sender, buyNum);
}

function unlockTokens(address _who)
public {
    uint phase = currentPhase();
    uint tokens = accounts[_who].tokensPerPhase;
    uint nextPhase = accounts[_who].nextPhase;
    if (tokens > 0 && phase > nextPhase) {
        accounts[_who].balance += tokens * (phase - nextPhase);
        accounts[_who].nextPhase = phase;
    }
}

function currentPhase()
public
constant
returns(uint) {
    require(phaseStart > 0);
    uint p = (now - phaseStart) / PHASE_DURATION;
    return p > UNLOCK_PHASES ? UNLOCK_PHASES : p;
}

function allocateLiquid(address _who, uint _value)
only_admin
when_allocatable_liquid(_value)
public {
    tokens.mint(_who, _value);
    liquidAllocatable -= _value;
    Allocated(_who, _value, true);
}

function allocateLocked(address _who, uint _value)
only_admin
when_allocatable_locked(_value)
public {
    tokens.mintLocked(_who, _value);
    lockedAllocatable -= _value;
    Allocated(_who, _value, false);
}

function specialPurchase()
only_before_period
is_under_cap_with(msg.value)
payable
public {
    uint256 bought = buyinReturn(msg.sender) * msg.value;
    require(bought > 0); 
    tokens.mint(msg.sender, bought);
    TREASURY.transfer(msg.value);
    saleRevenue += msg.value;
