function buyTokens() public payable {
    require(!isFinished);
    require(startTime > 0);
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(1000000).div(rate);
    require(tokens >= minimumSupply * 10 ** 18);
    require(tokensMinted.add(tokens) <= HARD_CAP_TOKENS);
    weiRaised = weiRaised.add(weiAmount);
    token.mint(msg.sender, tokens);
    tokensMinted = tokensMinted.add(tokens);
    TokenPurchase(msg.sender, weiAmount, weiAmount.div(10 ** 18), tokens, tokens.div(10 ** 18), tokensMinted.div(10 ** 18));
    owner.transfer(msg.value);
    if (tokensMinted == HARD_CAP_TOKENS) {
        isFinished = true;
        endTime = now;
        saleStatus = "Hardcap reached!";
    }
}

function issueTokens(address _to, uint _amount) public onlyOwner {
    require(!isFinished);
    uint amount = _amount * 10 ** 18;
    require(tokensMinted.add(amount) <= HARD_CAP_TOKENS);
    token.mint(_to, amount);
    tokensMinted = tokensMinted.add(amount);
    TokenIssue(_to, amount, amount.div(10 ** 18), tokensMinted.div(10 ** 18));
    if (tokensMinted == HARD_CAP_TOKENS) {
        isFinished = true;
        endTime = now;
        saleStatus = "Hardcap reached!";
    }
}

function createAuction(
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration,
    address _seller
)
public
canBeStoredWith128Bits(_startingPrice)
canBeStoredWith128Bits(_endingPrice)
canBeStoredWith64Bits(_duration) {
    require(msg.sender == address(nonFungibleContract));
    _escrow(_seller, _tokenId);
    Auction memory auction = Auction(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint64(now)
    );
    _addAuction(_tokenId, auction);
    if (listener != address(0)) {
        listener.auctionCreated(_tokenId, _seller, uint128(_startingPrice), uint128(_endingPrice), uint64(_duration));
    }
}

function setListener(address _listener) public {
    require(listener == address(0));
    SaleClockAuctionListener candidateContract = SaleClockAuctionListener(_listener);
    require(candidateContract.implementsSaleClockAuctionListener());
    listener = candidateContract;
}

function batchBid(uint256[] _tokenIds) public payable whenNotPaused {
    uint256 totalPrice = 0;
    for (uint32 i = 0; i < _tokenIds.length; i++) {
        uint256 _tokenId = _tokenIds[i];
        Auction storage auction = tokenIdToAuction[_tokenId];
        totalPrice += _currentPrice(auction);
    }
    require(msg.value >= totalPrice);
    for (i = 0; i < _tokenIds.length; i++) {
        _tokenId = _tokenIds[i];
        auction = tokenIdToAuction[_tokenId];
        address seller = auction.seller;
        uint256 bid = _currentPrice(auction);
        uint256 price = _bid(_tokenId, bid);
        _transfer(msg.sender, _tokenId);
        if (listener != address(0)) {
            listener.auctionSuccessful(_tokenId, uint128(price), seller, msg.sender);
        }
    }
}

function _bid(uint256 _tokenId, uint256 _bidAmount)
internal
returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    uint256 price = _currentPrice(auction);
    require(_bidAmount >= price);
    address seller = auction.seller;
    _removeAuction(_tokenId);
    if (price > 0) {
        uint256 auctioneerCut = _computeCut(price);
        uint256 sellerProceeds = price - auctioneerCut;
        seller.transfer(sellerProceeds);
        emit AuctionSettled(_tokenId, price, sellerProceeds, seller, msg.sender);
    }
    emit AuctionSuccessful(_tokenId, price, msg.sender);
    return price;
}

function cancelAuction(uint256 _tokenId)
public {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    address seller = auction.seller;
    require(msg.sender == seller);
    _cancelAuction(_tokenId, seller);
}

function _computeCurrentPrice(
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration,
    uint256 _secondsPassed
)
internal
pure
returns(uint256) {
    if (_secondsPassed >= _duration) {
        return _endingPrice;
    } else {
        int256 totalPriceChange = int256(_endingPrice) - int256(_startingPrice);
        int256 currentPriceChange = totalPriceChange * int256(_secondsPassed) / int256(_duration);
        int256 currentPrice = int256(_startingPrice) + currentPriceChange;
        return uint256(currentPrice);
    }
}

function getAuction(uint256 _tokenId)
public
view
returns
    (
        address seller,
        uint256 startingPrice,
        uint256 endingPrice,
        uint256 currentPrice,
        uint256 duration,
        uint256 startedAt
    ) {
        Auction storage auction = tokenIdToAuction[_tokenId];
        require(_isOnAuction(auction));
        uint256 price = _currentPrice(auction);
        return (
            auction.seller,
            auction.startingPrice,
            auction.endingPrice,
            price,
            auction.duration,
            auction.startedAt
        );
    }

function _currentPrice(Auction storage _auction)
internal
view
returns(uint256) {
    uint256 secondsPassed = 0;
    if (now > _auction.startedAt) {
        secondsPassed = now - _auction.startedAt;
    }
    return _computeCurrentPrice(
        _auction.startingPrice,
        _auction.endingPrice,
        _auction.duration,
        secondsPassed
    );
}

function cancelAuctionWhenPaused(uint256 _tokenId)
whenPaused
onlyOwner
public {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    _cancelAuction(_tokenId, auction.seller);
}

function getCurrentPrice(uint256 _tokenId)
public
view
returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    return _currentPrice(auction);
}

function crowdsaleActive(DirectCrowdsaleStorage storage self) public view returns(bool) {
    return (now >= self.startTime && now <= self.endTime);
}

function init(DirectCrowdsaleStorage storage self,
    address _owner,
    uint256[] _saleData,
    uint256 _endTime,
    uint8 _percentBurn,
    CrowdsaleToken _token)
public {
    require(self.owner == 0);
    require(_saleData.length > 0);
    require((_saleData.length % 2) == 0); 
    require(_saleData[0] > (now + 2 hours));
    require(_endTime > _saleData[0]);
    require(_owner > 0);
    require(_percentBurn <= 100);
    self.owner = _owner;
    self.startTime = _saleData[0];
    self.endTime = _endTime;
    self.token = _token;
    self.percentBurn = _percentBurn;
    uint256 _tempTime;
    for (uint256 i = 0; i < _saleData.length; i += 2) {
        require(_saleData[i] > _tempTime);
        require(_saleData[i + 1] > 0);
        self.milestoneTimes.push(_saleData[i]);
        self.tokenPrice[_saleData[i]] = _saleData[i + 1];
        _tempTime = _saleData[i];
    }
    self.tokensPerEth = _saleData[1];
}

function receivePurchase(DirectCrowdsaleStorage storage self, uint256 _amount)
public
returns(bool) {
    require(msg.sender != self.owner);
    require(validPurchase(self));
    if ((self.milestoneTimes.length > self.currentMilestone + 1) &&
        (now > self.milestoneTimes[self.currentMilestone + 1])) {
        while ((self.milestoneTimes.length > self.currentMilestone + 1) &&
            (now > self.milestoneTimes[self.currentMilestone + 1])) {
            self.currentMilestone += 1;
        }
        self.tokensPerEth = self.tokenPrice[self.milestoneTimes[self.currentMilestone]];
        emit LogTokenPriceChange(self.tokensPerEth, "Token Price has changed!");
    }
    uint256 _numTokens; 
    uint256 _newBalance; 
    uint256 _weiTokens; 
    uint256 _leftoverWei; 
    uint256 _remainder; 
    bool err;
    (err, _weiTokens) = _amount.times(self.tokensPerEth);
    require(!err);
    _numTokens = _weiTokens / 1000000000000000000;
    _remainder = _weiTokens % 1000000000000000000;
    _remainder = _remainder / self.tokensPerEth;
    _leftoverWei += _remainder;
    _amount = _amount - _remainder;
    self.leftoverWei[msg.sender] += _leftoverWei;
    self.hasContributed[msg.sender] += _amount;
    assert(_numTokens <= self.token.balanceOf(this));
    (err, _newBalance) = self.ownerBalance.plus(_amount);
    require(!err);
    self.ownerBalance = _newBalance; 
    self.withdrawTokensMap[msg.sender] += _numTokens;
    (err, _remainder) = self.withdrawTokensMap[self.owner].minus(_numTokens);
    require(!err);
    self.withdrawTokensMap[self.owner] = _remainder;
    emit LogTokensBought(msg.sender, _numTokens);
    return true;
}

function crowdsaleEnded(DirectCrowdsaleStorage storage self) public view returns(bool) {
    return now > self.endTime;
}

function setTokens(DirectCrowdsaleStorage storage self) public returns(bool) {
    require(msg.sender == self.owner);
    require(!self.tokensSet);
    require(now < self.endTime);
    uint256 _tokenBalance;
    _tokenBalance = self.token.balanceOf(this);
    self.withdrawTokensMap[msg.sender] = _tokenBalance;
    self.startingTokenBalance = _tokenBalance;
    self.tokensSet = true;
    return true;
}

function withdrawOwnerEth(DirectCrowdsaleStorage storage self) public returns(bool) {
    if ((!crowdsaleEnded(self)) && (self.token.balanceOf(this) > 0)) {
        emit LogErrorMsg(0, "Cannot withdraw owner ether until after the sale!");
        return false;
    }
    require(msg.sender == self.owner);
    require(self.ownerBalance > 0);
    uint256 amount = self.ownerBalance;
    self.ownerBalance = 0;
    self.owner.transfer(amount);
    emit LogOwnerEthWithdrawn(msg.sender, amount, "Crowdsale owner has withdrawn all funds!");
    return true;
}

function validPurchase(DirectCrowdsaleStorage storage self) internal returns(bool) {
    bool nonZeroPurchase = msg.value != 0;
    if (crowdsaleActive(self) && nonZeroPurchase) {
        return true;
    } else {
        emit LogErrorMsg(msg.value, "Invalid Purchase! Check start time and amount of ether.");
        return false;
    }
}

function withdrawLeftoverWei(DirectCrowdsaleStorage storage self) public returns(bool) {
    if (self.leftoverWei[msg.sender] == 0) {
        emit LogErrorMsg(0, "Sender has no extra wei to withdraw!");
        return false;
    }
    var total = self.leftoverWei[msg.sender];
    self.leftoverWei[msg.sender] = 0;
    msg.sender.transfer(total);
    emit LogWeiWithdrawn(msg.sender, total);
    return true;
}

function refund() public {
    require(now > freezeEndsAt && balances[msg.sender] > 0);
    address investor = msg.sender;
    uint amount = balances[investor];
    delete balances[investor];
    emit Refunded(investor, amount);
    investor.transfer(amount);
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    return withinPeriod && nonZeroPurchase;
}

function mintPresaleTokens(address _beneficiary, uint256 _amount) public onlyOwner onlyCrowdsaleStage {
    require(_beneficiary != address(0));
    require(_amount > 0);
    require(totalTokensMinted.add(_amount) <= TOKEN_CAP);
    require(now < startTime);
    token.mint(_beneficiary, _amount);
    totalTokensMinted = totalTokensMinted.add(_amount);
    PresaleMinted(_beneficiary, _amount);
}

function buyTokens(address _beneficiary) public payable onlyCrowdsaleStage {
    require(_beneficiary != address(0));
    require(isWhitelisted[msg.sender]);
    require(validPurchase());
    require(msg.value >= rate); 
    uint256 weiAmount = msg.value;
    weiRaised = weiRaised.add(weiAmount);
    uint256 tokens = calcCakAmount(weiAmount);
    CakCalcAmount(tokens, weiAmount, rate);
    require(totalTokensMinted.add(tokens) <= TOKEN_CAP);
    token.mint(_beneficiary, tokens);
    totalTokensMinted = totalTokensMinted.add(tokens);
    TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens);
    uint256 refundAmount = refundLeftOverWei(weiAmount, tokens);
    if (refundAmount > 0) {
        weiRaised = weiRaised.sub(refundAmount);
        msg.sender.transfer(refundAmount);
        RefundAmount(msg.sender, refundAmount);
    }
    forwardEther(refundAmount);
}

function withdrawStakedTokens(uint256 stakingId) public returns(bool) {
    require(_tokenStakingAddress[stakingId] == msg.sender, "No staked token found on this address and ID");
    require(_TokenTransactionstatus[stakingId] != true, "Either tokens are already withdrawn or blocked by admin");
    if (_tokenTotalDays[stakingId] == PERIOD_SILVER) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_SILVER, "Unable to Withdraw Staked token before 15 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _usersTokens[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_GOLD) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_GOLD, "Unable to Withdraw Staked token before 30 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_PLATINUM) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_PLATINUM, "Unable to Withdraw Staked token before 60 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            icliq.transferFrom(address(this), msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        }
    } else {
        return false;
    }
    return true;
}

function getTokenPenaltyDetailByStakingId(uint256 id) public view returns(uint256) {
    if (_tokenStakingEndTime[id] > now) {
        if (_tokenTotalDays[id] == PERIOD_SILVER) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_SILVER / 100000000);
        } else if (_tokenTotalDays[id] == PERIOD_GOLD) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_GOLD / 100000000);
        } else if (_tokenTotalDays[id] == PERIOD_PLATINUM) {
            return (_usersTokens[id] * TOKEN_PENALTY_PERCENT_PLATINUM / 100000000);
        } else {
            return 0;
        }
    } else {
        return 0;
    }
}

