function sell(uint256 amount) public {
    require(now > 1543536000); 
    require(amount > 0);
    require(balances[msg.sender] >= amount);
    uint256 requiredBalance = amount.mul(sellPrice);
    require(this.balance >= requiredBalance); 
    balances[msg.sender] -= amount;
    balances[owner] += amount;
    Transfer(msg.sender, owner, amount);
    msg.sender.transfer(requiredBalance); 
}

function buy() payable public {
    require(now > 1543536000); 
    uint amount = msg.value.div(buyPrice); 
    _transfer(owner, msg.sender, amount); 
}

function Buy(address target, uint256 maxamount, uint256 maxprice) public payable {
    require(SellOrders[target][0] > 0);
    require(SellOrders[target][1] <= maxprice);
    uint256 price = SellOrders[target][1];
    uint256 amount_buyable = (mul(msg.value, uint256(10 ** decimals))) / price;
    if (amount_buyable > SellOrders[target][0]) {
        amount_buyable = SellOrders[target][0];
    }
    if (amount_buyable > maxamount) {
        amount_buyable = maxamount;
    }
    uint256 total_payment = mul(amount_buyable, price) / (uint256(10 ** decimals));
    require(amount_buyable > 0 && total_payment > 0);
    uint256 Fee = mul(total_payment, SellFee) / 10000;
    uint256 Left = total_payment - Fee;
    uint256 Excess = msg.value - total_payment;
    uint256 OldTokensSeller = balanceOf[target];
    uint256 OldTokensBuyer = balanceOf[msg.sender];
    _forceTransfer(target, msg.sender, amount_buyable);
    SellOrders[target][0] = sub(SellOrders[target][0], amount_buyable);
    uint256 _sendTarget = _withdraw(target, OldTokensSeller, false);
    uint256 _sendBuyer = _withdraw(msg.sender, OldTokensBuyer, false);
    target.transfer(add(Left, _sendTarget));
    if (add(Excess, _sendBuyer) > 0) {
        msg.sender.transfer(add(Excess, _sendBuyer));
    }
    if (Fee > 0) {
        owner.transfer(Fee);
    }
    emit SellOrderFilled(msg.sender, target, amount_buyable, price, Left);
}

function transferFrom(address _from, address _to, uint256 _value) public validAddress returns(bool success) {
    require(_from != _to);
    require(sub(balanceOf[_from], SellOrders[_from][0]) >= _value);
    require(balanceOf[_to] + _value >= balanceOf[_to]);
    require(allowance[_from][msg.sender] >= _value);
    uint256 _toBal = balanceOf[_to];
    uint256 _fromBal = balanceOf[_from];
    balanceOf[_to] += _value;
    balanceOf[_from] -= _value;
    allowance[_from][msg.sender] -= _value;
    emit Transfer(_from, _to, _value);
    CancelOrder();
    uint256 _sendFrom = _withdraw(_from, _fromBal, false);
    uint256 _sendTo = _withdraw(_to, _toBal, false);
    _from.transfer(_sendFrom);
    _to.transfer(_sendTo);
    return true;
}

function transfer(address _to, uint256 _value) public validAddress returns(bool success) {
    require(balanceOf[msg.sender] >= _value);
    require(balanceOf[_to] + _value >= balanceOf[_to]);
    require(sub(balanceOf[msg.sender], SellOrders[msg.sender][0]) >= _value);
    require(msg.sender != _to);
    uint256 _toBal = balanceOf[_to];
    uint256 _fromBal = balanceOf[msg.sender];
    balanceOf[msg.sender] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(msg.sender, _to, _value);
    uint256 _sendFrom = _withdraw(msg.sender, _fromBal, false);
    uint256 _sendTo = _withdraw(_to, _toBal, false);
    msg.sender.transfer(_sendFrom);
    _to.transfer(_sendTo);
    return true;
}

function endEvent()
external
onlyOwner
eventNotEnded {
    require(now > endTimeMain); 
    require(endTimeMain > 0); 
    uint256 leftTokens = token.balanceOf(this); 
    if (leftTokens > 0) {
        token.burn(leftTokens); 
    }
    eventEnded = true; 
}

function setPre(
    uint256 _startTimePre,
    uint256 _endTimePre,
    uint256 _minCapPre,
    uint256 _maxCapPre,
    uint256 _ratePre
)
external
onlyOwner
eventNotEnded {
    require(now < _startTimePre); 
    require(_startTimePre < _endTimePre); 
    require(_minCapPre <= _maxCapPre); 
    startTimePre = _startTimePre;
    endTimePre = _endTimePre;
    minCapPre = _minCapPre;
    maxCapPre = _maxCapPre;
    ratePre = _ratePre;
    SetPre(_startTimePre, _endTimePre, _minCapPre, _maxCapPre, _ratePre);
}

function setMain(
    uint256 _startTimeMain,
    uint256 _endTimeMain,
    uint256 _minCapMain,
    uint256 _maxCapMain,
    uint256 _rateMain
)
external
onlyOwner
eventNotEnded {
    require(now < _startTimeMain); 
    require(_startTimeMain < _endTimeMain); 
    require(_minCapMain <= _maxCapMain); 
    require(_startTimeMain > endTimePre); 
    startTimeMain = _startTimeMain;
    endTimeMain = _endTimeMain;
    minCapMain = _minCapMain;
    maxCapMain = _maxCapMain;
    rateMain = _rateMain;
    SetMain(_startTimeMain, _endTimeMain, _minCapMain, _maxCapMain, _rateMain);
}

function joinMain()
public
payable
eventNotEnded {
    require(now >= startTimeMain); 
    require(now <= endTimeMain); 
    require(msg.value >= minCapMain); 
    require(whitelistedAddressMain[msg.sender] == true); 
    uint256 weiValue = msg.value;
    contributedValue[msg.sender] = contributedValue[msg.sender].add(weiValue); 
    require(contributedValue[msg.sender] <= maxCapMain); 
    uint256 tokens = weiValue.mul(rateMain); 
    weiTotal = weiTotal.add(weiValue); 
    token.transfer(msg.sender, tokens); 
    TokenMain(msg.sender, weiValue, tokens); 
    forwardFunds(); 
}

function joinPre()
public
payable
eventNotEnded {
    require(now >= startTimePre); 
    require(now <= endTimePre); 
    require(msg.value >= minCapPre); 
    require(whitelistedAddressPre[msg.sender] == true); 
    uint256 weiValue = msg.value;
    contributedValue[msg.sender] = contributedValue[msg.sender].add(weiValue); 
    require(contributedValue[msg.sender] <= maxCapPre); 
    uint256 tokens = weiValue.mul(ratePre); 
    weiTotal = weiTotal.add(weiValue); 
    token.transfer(msg.sender, tokens); 
    TokenPre(msg.sender, weiValue, tokens); 
    forwardFunds(); 
}

function() external payable {
    if (now <= endTimePre) { 
        joinPre();
    } else if (now <= endTimeMain) { 
        joinMain();
    } else {
        revert();
    }
}

function WithdrawPotShare() public {
    MinerData storage m = miners[msg.sender];
    require(m.unclaimedPot > 0);
    require(m.lastUpdateTime != 0);
    uint256 amntToSend = m.unclaimedPot;
    m.unclaimedPot = 0;
    if (msg.sender.send(amntToSend)) {
        m.unclaimedPot = 0;
    }
}

function WithdrawDevFunds() public {
    require(msg.sender == owner);
    if (owner.send(devFund)) {
        devFund = 0;
    }
}

function UpgradeRigETH(uint8 rigIdx, uint256 count) external payable {
    require(rigIdx < NUMBER_OF_RIG_TYPES);
    require(count > 0);
    require(count <= 256);
    require(rigData[rigIdx].priceInETH > 0);
    MinerData storage m = miners[msg.sender];
    require(rigData[rigIdx].limit >= (m.rigs[rigIdx] + count));
    uint256 price = (rigData[rigIdx].priceInETH).mul(count);
    require(msg.value >= price);
    BuyHandler(msg.value);
    UpdateMoney();
    m.rigs[rigIdx] = m.rigs[rigIdx] + count;
    if (m.rigs[rigIdx] > rigData[rigIdx].limit)
        m.rigs[rigIdx] = rigData[rigIdx].limit;
}

function UpdateMoney() private {
    require(miners[msg.sender].lastUpdateTime != 0);
    require(block.timestamp >= miners[msg.sender].lastUpdateTime);
    MinerData storage m = miners[msg.sender];
    uint256 diff = block.timestamp - m.lastUpdateTime;
    uint256 revenue = GetProductionPerSecond(msg.sender);
    m.lastUpdateTime = block.timestamp;
    if (revenue > 0) {
        revenue *= diff;
        m.money += revenue;
    }
}

function WithdrawICOEarnings() external {
    MinerData storage m = miners[msg.sender];
    require(miners[msg.sender].lastUpdateTime != 0);
    require(miners[msg.sender].lastPotClaimIndex < cycleCount);
    uint256 i = m.lastPotClaimIndex;
    uint256 limit = cycleCount;
    if ((limit - i) > 30) 
        limit = i + 30;
    m.lastPotClaimIndex = limit;
    for (; i < cycleCount; ++i) {
        if (minerICOPerCycle[msg.sender][i] > 0)
            m.unclaimedPot += (honeyPotPerCycle[i] * minerICOPerCycle[msg.sender][i]) / globalICOPerCycle[i];
    }
}

function ReleaseICO() external {
    require(miners[msg.sender].lastUpdateTime != 0);
    require(nextPotDistributionTime <= block.timestamp);
    require(honeyPotAmount > 0);
    require(globalICOPerCycle[cycleCount] > 0);
    nextPotDistributionTime = block.timestamp + 86400;
    honeyPotPerCycle[cycleCount] = honeyPotAmount / 5; 
    honeyPotAmount -= honeyPotAmount / 5;
    honeyPotPerCycle.push(0);
    globalICOPerCycle.push(0);
    cycleCount = cycleCount + 1;
    MinerData storage jakpotWinner = miners[msg.sender];
    jakpotWinner.unclaimedPot += jackPot;
    jackPot = 0;
}

function GetMinerUnclaimedICOShare(address miner) public constant returns(uint256 unclaimedPot) {
    MinerData storage m = miners[miner];
    require(m.lastUpdateTime != 0);
    require(m.lastPotClaimIndex < cycleCount);
    uint256 i = m.lastPotClaimIndex;
    uint256 limit = cycleCount;
    if ((limit - i) > 30) 
        limit = i + 30;
    unclaimedPot = 0;
    for (; i < cycleCount; ++i) {
        if (minerICOPerCycle[msg.sender][i] > 0)
            unclaimedPot += (honeyPotPerCycle[i] * minerICOPerCycle[miner][i]) / globalICOPerCycle[i];
    }
}

function UpgradeRig(uint8 rigIdx, uint16 count) external {
    require(rigIdx < NUMBER_OF_RIG_TYPES);
    require(count > 0);
    require(count <= 256);
    MinerData storage m = miners[msg.sender];
    require(rigData[rigIdx].limit >= (m.rigs[rigIdx] + count));
    UpdateMoney();
    uint256 price = NumericSequence.sumOfN(rigData[rigIdx].basePrice, rigData[rigIdx].pricePerLevel, m.rigs[rigIdx], count);
    require(m.money >= price);
    m.rigs[rigIdx] = m.rigs[rigIdx] + count;
    if (m.rigs[rigIdx] > rigData[rigIdx].limit)
        m.rigs[rigIdx] = rigData[rigIdx].limit;
    m.money -= price;
}

function StartNewMiner() external {
    require(miners[msg.sender].lastUpdateTime == 0);
    miners[msg.sender].lastUpdateTime = block.timestamp;
    miners[msg.sender].money = 0;
    miners[msg.sender].rigs[0] = 1;
    miners[msg.sender].unclaimedPot = 0;
    miners[msg.sender].lastPotClaimIndex = cycleCount;
    pvpMap[msg.sender].immunityTime = block.timestamp + 28800;
    pvpMap[msg.sender].exhaustTime = block.timestamp;
    indexes[topindex] = msg.sender;
    ++topindex;
}

function UpdateMoneyAt(address addr) private {
    require(miners[addr].lastUpdateTime != 0);
    require(block.timestamp >= miners[addr].lastUpdateTime);
    MinerData storage m = miners[addr];
    uint256 diff = block.timestamp - m.lastUpdateTime;
    uint256 revenue = GetProductionPerSecond(addr);
    m.lastUpdateTime = block.timestamp;
    if (revenue > 0) {
        revenue *= diff;
        m.money += revenue;
    }
}

function BuyBooster() external payable {
    require(msg.value >= nextBoosterPrice);
    require(miners[msg.sender].lastUpdateTime != 0);
    for (uint i = 0; i < NUMBER_OF_BOOSTERS; ++i)
        if (boosterHolders[i] == msg.sender)
            revert();
    address beneficiary = boosterHolders[boosterIndex];
    MinerData storage m = miners[beneficiary];
    m.unclaimedPot += (msg.value * 9403) / 10000;
    honeyPotAmount += (msg.value * 597) / 20000;
    devFund += (msg.value * 597) / 20000;
    nextBoosterPrice += nextBoosterPrice / 20;
    UpdateMoney();
    UpdateMoneyAt(beneficiary);
    boosterHolders[boosterIndex] = msg.sender;
    boosterIndex += 1;
    if (boosterIndex >= 5)
        boosterIndex = 0;
}

function BuyTroop(uint256 idx, uint256 count) external payable {
    require(idx < NUMBER_OF_TROOPS);
    require(count > 0);
    require(count <= 1000);
    PVPData storage pvp = pvpMap[msg.sender];
    MinerData storage m = miners[msg.sender];
    uint256 owned = pvp.troops[idx];
    uint256 priceGold = NumericSequence.sumOfN(troopData[idx].priceGold, troopData[idx].priceGold, owned, count);
    uint256 priceETH = (troopData[idx].priceETH).mul(count);
    UpdateMoney();
    require(m.money >= priceGold);
    require(msg.value >= priceETH);
    if (priceGold > 0)
        m.money -= priceGold;
    if (msg.value > 0)
        BuyHandler(msg.value);
    pvp.troops[idx] += count;
}

function Attack(address defenderAddr) external {
    require(msg.sender != defenderAddr);
    require(miners[msg.sender].lastUpdateTime != 0);
    require(miners[defenderAddr].lastUpdateTime != 0);
    PVPData storage attacker = pvpMap[msg.sender];
    PVPData storage defender = pvpMap[defenderAddr];
    uint i = 0;
    uint256 count = 0;
    require(block.timestamp > attacker.exhaustTime);
    require(block.timestamp > defender.immunityTime);
    if (attacker.immunityTime > block.timestamp)
        attacker.immunityTime = block.timestamp - 1;
    attacker.exhaustTime = block.timestamp + 7200;
    uint256 attackpower = 0;
    uint256 defensepower = 0;
    for (i = 0; i < ATTACKER_END_IDX; ++i) {
        attackpower += attacker.troops[i] * troopData[i].attackPower;
        defensepower += defender.troops[i + DEFENDER_START_IDX] * troopData[i + DEFENDER_START_IDX].defensePower;
    }
    if (attackpower > defensepower) {
        if (defender.immunityTime < block.timestamp + 14400)
            defender.immunityTime = block.timestamp + 14400;
        UpdateMoneyAt(defenderAddr);
        MinerData storage m = miners[defenderAddr];
        MinerData storage m2 = miners[msg.sender];
        uint256 moneyStolen = m.money / 2;
        for (i = DEFENDER_START_IDX; i < DEFENDER_END_IDX; ++i) {
            defender.troops[i] = 0;
        }
        for (i = ATTACKER_START_IDX; i < ATTACKER_END_IDX; ++i) {
            if (troopData[i].attackPower > 0) {
                count = attacker.troops[i];
                if ((count * troopData[i].attackPower) > defensepower)
                    count = defensepower / troopData[i].attackPower;
                attacker.troops[i] -= count;
                defensepower -= count * troopData[i].attackPower;
            }
        }
        m.money -= moneyStolen;
        m2.money += moneyStolen;
    } else {
        for (i = ATTACKER_START_IDX; i < ATTACKER_END_IDX; ++i) {
            attacker.troops[i] = 0;
        }
        for (i = DEFENDER_START_IDX; i < DEFENDER_END_IDX; ++i) {
            if (troopData[i].defensePower > 0) {
                count = defender.troops[i];
                if ((count * troopData[i].defensePower) > attackpower)
                    count = attackpower / troopData[i].defensePower;
                defender.troops[i] -= count;
                attackpower -= count * troopData[i].defensePower;
            }
        }
    }
}

function FundICO(uint amount) external {
    require(miners[msg.sender].lastUpdateTime != 0);
    require(amount > 0);
    MinerData storage m = miners[msg.sender];
    UpdateMoney();
    require(m.money >= amount);
    m.money = (m.money).sub(amount);
    globalICOPerCycle[cycleCount] = globalICOPerCycle[cycleCount].add(uint(amount));
    minerICOPerCycle[msg.sender][cycleCount] = minerICOPerCycle[msg.sender][cycleCount].add(uint(amount));
}

function BuyUpgrade(uint256 idx) external payable {
    require(idx < NUMBER_OF_UPGRADES);
    require(msg.value >= boostData[idx].priceInWEI);
    require(miners[msg.sender].hasUpgrade[idx] == 0);
    require(miners[msg.sender].lastUpdateTime != 0);
    BuyHandler(msg.value);
    UpdateMoney();
    miners[msg.sender].hasUpgrade[idx] = 1;
    miners[msg.sender].premamentMineBonusPct += boostData[idx].percentBonus;
}

function Collect(uint _am)
public
payable {
    var acc = Acc[msg.sender];
    if (acc.balance >= MinSum && acc.balance >= _am && now > acc.unlockTime) {
        if (msg.sender.call.value(_am)()) {
            acc.balance -= _am;
            LogFile.AddMessage(msg.sender, _am, "Collect");
        }
    }
}

function Put(uint _unlockTime)
public
payable {
    var acc = Acc[msg.sender];
    acc.balance += msg.value;
    acc.unlockTime = _unlockTime > now ? _unlockTime : now;
    LogFile.AddMessage(msg.sender, msg.value, "Put");
}

function() external payable {
    require(!isFinalized);
    address beneficiary = msg.sender;
    uint256 weiAmount = msg.value;
    require(beneficiary != address(0));
    require(weiAmount != 0);
    uint256 tokens = weiAmount.div(price);
    uint256 selfBalance = balance();
    require(tokens > 0);
    require(tokens <= selfBalance);
    token.transfer(beneficiary, tokens);
    emit TokenPurchase(
        beneficiary,
        weiAmount,
        tokens
    );
    owner.transfer(msg.value);
    weiRaised = weiRaised.add(weiAmount);
}

function finalize() onlyOwner public {
    require(!isFinalized);
    transferBallance();
    emit Finalized();
    isFinalized = true;
}

function approveTransfer(uint256 nonce)
external
onlyValidator
checkIsInvestorApproved(pendingTransactions[nonce].from)
checkIsInvestorApproved(pendingTransactions[nonce].to)
checkIsValueValid(pendingTransactions[nonce].value)
returns(bool) {
    address from = pendingTransactions[nonce].from;
    address spender = pendingTransactions[nonce].spender;
    address to = pendingTransactions[nonce].to;
    uint256 value = pendingTransactions[nonce].value;
    uint256 allowedTransferAmount = allowed[from][spender];
    uint256 pendingAmount = pendingApprovalAmount[from][spender];
    uint256 fee = pendingTransactions[nonce].fee;
    uint256 balanceFrom = balances[from];
    uint256 balanceTo = balances[to];
    delete pendingTransactions[nonce];
    if (from == feeRecipient) {
        fee = 0;
        balanceFrom = balanceFrom.sub(value);
        balanceTo = balanceTo.add(value);
        if (spender != address(0)) {
            allowedTransferAmount = allowedTransferAmount.sub(value);
        }
        pendingAmount = pendingAmount.sub(value);
    } else {
        balanceFrom = balanceFrom.sub(value.add(fee));
        balanceTo = balanceTo.add(value);
        balances[feeRecipient] = balances[feeRecipient].add(fee);
        if (spender != address(0)) {
            allowedTransferAmount = allowedTransferAmount.sub(value).sub(fee);
        }
        pendingAmount = pendingAmount.sub(value).sub(fee);
    }
    emit TransferWithFee(
        from,
        to,
        value,
        fee
    );
    emit Transfer(
        from,
        to,
        value
    );
    balances[from] = balanceFrom;
    balances[to] = balanceTo;
    allowed[from][spender] = allowedTransferAmount;
    pendingApprovalAmount[from][spender] = pendingAmount;
    return true;
}

function approveMint(uint256 nonce)
external
onlyValidator
checkIsInvestorApproved(pendingMints[nonce].to)
returns(bool) {
    weiRaised = weiRaised.add(pendingMints[nonce].weiAmount);
    token.mint(pendingMints[nonce].to, pendingMints[nonce].tokens);
    emit TokenPurchase(
        msg.sender,
        pendingMints[nonce].to,
        pendingMints[nonce].weiAmount,
        pendingMints[nonce].tokens
    );
    forwardFunds(pendingMints[nonce].weiAmount);
    delete pendingMints[nonce];
    return true;
}

function transfer(address _to, uint256 _value)
public
checkIsInvestorApproved(msg.sender)
checkIsInvestorApproved(_to)
checkIsValueValid(_value)
returns(bool) {
    uint256 pendingAmount = pendingApprovalAmount[msg.sender][address(0)];
    if (msg.sender == feeRecipient) {
        require(_value.add(pendingAmount) <= balances[msg.sender]);
        pendingApprovalAmount[msg.sender][address(0)] = pendingAmount.add(_value);
    } else {
        require(_value.add(pendingAmount).add(transferFee) <= balances[msg.sender]);
        pendingApprovalAmount[msg.sender][address(0)] = pendingAmount.add(_value).add(transferFee);
    }
    pendingTransactions[currentNonce] = TransactionStruct(
        msg.sender,
        _to,
        _value,
        transferFee,
        address(0)
    );
    emit RecordedPendingTransaction(msg.sender, _to, _value, transferFee, address(0));
    currentNonce++;
    return true;
}

