function getCurrentSchedule()
public
view
returns(uint) {
    require(now <= schedules[6].endPeriod, "Mintable periods have ended");
    for (uint i = 0; i < INFLATION_SCHEDULES_LENGTH; i++) {
        if (schedules[i].startPeriod <= now && schedules[i].endPeriod >= now) {
            return i;
        }
    }
}

function internalUpdateRates(bytes4[] currencyKeys, uint[] newRates, uint timeSent)
internal
returns(bool) {
    require(currencyKeys.length == newRates.length, "Currency key array length must match rates array length.");
    require(timeSent < (now + ORACLE_FUTURE_LIMIT), "Time is too far into the future");
    for (uint i = 0; i < currencyKeys.length; i++) {
        require(newRates[i] != 0, "Zero is not a valid rate, please call deleteRate instead.");
        require(currencyKeys[i] != "sUSD", "Rate of sUSD cannot be updated, it&#39;s always UNIT.");
        if (timeSent < lastRateUpdateTimes[currencyKeys[i]]) {
            continue;
        }
        newRates[i] = rateOrInverted(currencyKeys[i], newRates[i]);
        rates[currencyKeys[i]] = newRates[i];
        lastRateUpdateTimes[currencyKeys[i]] = timeSent;
    }
    emit RatesUpdated(currencyKeys, newRates);
    updateXDRRate(timeSent);
    if (priceUpdateLock) {
        priceUpdateLock = false;
    }
    return true;
}

function mintableSupply()
public
view
returns(uint) {
    if (!isMintable()) {
        return 0;
    }
    uint index = getCurrentSchedule();
    uint amountPreviousPeriod = _remainingSupplyFromPreviousYear(index);
    ScheduleData memory schedule = schedules[index];
    uint weeksInPeriod = (schedule.endPeriod - schedule.startPeriod).div(mintPeriodDuration);
    uint supplyPerWeek = schedule.totalSupply.divideDecimal(weeksInPeriod);
    uint weeksToMint = lastMintEvent >= schedule.startPeriod ? _numWeeksRoundedDown(now.sub(lastMintEvent)) : _numWeeksRoundedDown(now.sub(schedule.startPeriod));
    uint amountInPeriod = supplyPerWeek.multiplyDecimal(weeksToMint);
    return amountInPeriod.add(amountPreviousPeriod);
}

function anyRateIsStale(bytes4[] currencyKeys)
external
view
returns(bool) {
    uint256 i = 0;
    while (i < currencyKeys.length) {
        if (currencyKeys[i] != "sUSD" && lastRateUpdateTimes[currencyKeys[i]].add(rateStalePeriod) < now) {
            return true;
        }
        i += 1;
    }
    return false;
}

function _remainingSupplyFromPreviousYear(uint currentSchedule)
internal
view
returns(uint) {
    if (currentSchedule == 0 || lastMintEvent > schedules[currentSchedule - 1].endPeriod) {
        return 0;
    }
    uint amountInPeriod = schedules[currentSchedule - 1].totalSupply.sub(schedules[currentSchedule - 1].totalSupplyMinted);
    if (amountInPeriod < 0) {
        return 0;
    }
    return amountInPeriod;
}

function rateIsStale(bytes4 currencyKey)
public
view
returns(bool) {
    if (currencyKey == "sUSD") return false;
    return lastRateUpdateTimes[currencyKey].add(rateStalePeriod) < now;
}

function isMintable()
public
view
returns(bool) {
    bool mintable = false;
    if (now - lastMintEvent > mintPeriodDuration && now <= schedules[6].endPeriod) 
    {
        mintable = true;
    }
    return mintable;
}

function transferToContract(address _to, uint _value, bytes _data) private returns(bool) {
    ContractReceiver receiver = ContractReceiver(_to);
    uint256 price;
    address owner;
    (price, owner) = receiver.doTransfer(msg.sender, bytesToUint(_data));
    if (balanceOf(msg.sender) < price) revert();
    balances[msg.sender] = balanceOf(msg.sender).sub(price);
    balances[owner] = balanceOf(owner).add(price);
    receiver.tokenFallback(msg.sender, price, _data);
    emit Transfer(msg.sender, _to, _value);
    emit Transfer(msg.sender, _to, _value, _data);
    return true;
}

function createCard(
    uint256 pool,
    uint256 supply,
    uint256 points,
    uint256 mintFee,
    uint256 releaseTime,
    address beneficiary,
    uint256 residualsFee,
    bool residualsRequired
) public onlyOwner poolExists(pool) returns(uint256) {
    uint256 tokenId = nfts.create(supply, 0, "", "", beneficiary, residualsFee, residualsRequired);
    require(tokenId > 0, "ERC1155 create did not succeed");
    Card storage c = pools[pool].cards[tokenId];
    c.points = points;
    c.releaseTime = releaseTime;
    c.mintFee = mintFee;
    emit CardAdded(pool, tokenId, points, mintFee, releaseTime);
    return tokenId;
}

function stake(uint256 pool, uint256 amount)
public
override
poolExists(pool)
updateReward(msg.sender, pool)
whenNotPaused() {
    Pool memory p = pools[pool];
    require(block.timestamp >= p.periodStart, "pool not open");
    require(amount.add(balanceOf(msg.sender, pool)) <= p.maxStake, "stake exceeds max");
    super.stake(pool, amount);
    emit Staked(msg.sender, pool, amount);
}

function redeem(uint256 pool, uint256 card)
public
payable
poolExists(pool)
cardExists(pool, card)
updateReward(msg.sender, pool) {
    Pool storage p = pools[pool];
    Card memory c = p.cards[card];
    require(block.timestamp >= c.releaseTime, "card not released");
    require(p.points[msg.sender] >= c.points, "not enough points");
    require(msg.value == c.mintFee, "support our artists, send eth");
    if (c.mintFee > 0) {
        uint256 _controllerShare = msg.value.mul(p.controllerShare).div(1000);
        uint256 _artistRoyalty = msg.value.sub(_controllerShare);
        require(_artistRoyalty.add(_controllerShare) == msg.value, "problem with fee");
        p.feesCollected = p.feesCollected.add(c.mintFee);
        pendingWithdrawals[controller] = pendingWithdrawals[controller].add(_controllerShare);
        pendingWithdrawals[p.artist] = pendingWithdrawals[p.artist].add(_artistRoyalty);
    }
    p.points[msg.sender] = p.points[msg.sender].sub(c.points);
    p.spentPoints = p.spentPoints.add(c.points);
    nfts.mint(msg.sender, card, 1, "");
    emit Redeemed(msg.sender, pool, c.points);
}

function transfer(
    uint256 fromPool,
    uint256 toPool,
    uint256 amount
)
public
override
poolExists(fromPool)
poolExists(toPool)
updateReward(msg.sender, fromPool)
updateReward(msg.sender, toPool)
whenNotPaused() {
    Pool memory toP = pools[toPool];
    require(block.timestamp >= toP.periodStart, "pool not open");
    require(amount.add(balanceOf(msg.sender, toPool)) <= toP.maxStake, "stake exceeds max");
    super.transfer(fromPool, toPool, amount);
    emit Transferred(msg.sender, fromPool, toPool, amount);
}

