function stake(uint256 _pool, uint256 _value) public payable {
    if (_pool == 0) {
        increaseUserStakingBalance(_pool, msg.sender, msg.value);
        TransferHelper.safeTransferETH(admin, msg.value);
        emit Stake(msg.sender, _pool, msg.value);
    } else {
        TransferHelper.safeTransferFrom(pools[_pool].token, msg.sender, address(this), _value);
        TransferHelper.safeTransfer(pools[_pool].token, admin, _value);
        increaseUserStakingBalance(_pool, msg.sender, _value);
        emit Stake(msg.sender, _pool, _value);
    }
    bool isListed;
    for (uint256 i = 0; i < usersList[_pool].length; i++) {
        if (usersList[_pool][i] == msg.sender) isListed = true;
    }
    if (!isListed) {
        usersList[_pool].push(msg.sender);
    }
}

function harvest(uint256 _pool) public {
    uint256 receiveAmount = getUserPendingReward(_pool, msg.sender);
    if (receiveAmount > 0) {
        TransferHelper.safeTransfer(token, msg.sender, receiveAmount);
        emptyUserPendingReward(_pool, msg.sender);
    }
    emit Harvest(msg.sender, _pool, receiveAmount);
}

function processUnstake(uint256 _pool, uint256 _amount) public payable onlyAdmin {
    if (_pool == 0) {
        uint256 tokenBalance = address(this).balance;
        for (uint256 i = 0; i < unstakeRequests[_pool].length; i++) {
            if (unstakeRequests[_pool][i].amount <= tokenBalance && !unstakeRequests[_pool][i].processed) {
                address user = unstakeRequests[_pool][i].user;
                TransferHelper.safeTransferETH(user, unstakeRequests[_pool][i].amount);
                tokenBalance = tokenBalance.sub(unstakeRequests[_pool][i].amount);
                decreaseUserStakedBalance(_pool, user, unstakeRequests[_pool][i].amount);
                setProcessedUnstakeRequest(_pool, i);
            }
        }
        emit UnstakeProcessed(msg.sender, _pool, msg.value);
    } else {
        TransferHelper.safeTransferFrom(pools[_pool].token, getAdmin(), address(this), _amount);
        uint256 tokenBalance = ERC20Helper.getBalance(pools[_pool].token, address(this));
        for (uint256 i = 0; i < unstakeRequests[_pool].length; i++) {
            if (unstakeRequests[_pool][i].amount <= tokenBalance && !unstakeRequests[_pool][i].processed) {
                address user = unstakeRequests[_pool][i].user;
                TransferHelper.safeTransfer(pools[_pool].token, user, unstakeRequests[_pool][i].amount);
                tokenBalance = tokenBalance.sub(unstakeRequests[_pool][i].amount);
                decreaseUserStakedBalance(_pool, user, unstakeRequests[_pool][i].amount);
                setProcessedUnstakeRequest(_pool, i);
            }
        }
        emit UnstakeProcessed(msg.sender, _pool, _amount);
    }
}

function setOffer(uint256 _newOffer) external {
    require(_newOffer <= 10_000, "Offer exceeds 100%.");
    require(_newOffer >= 200, "Minimum offer is 2%.");
    uint256 oldOffer = offers[msg.sender];
    if (_newOffer < oldOffer) {
        uint256 nextEpoch = ESDS.epoch() + 1;
        uint256 nextEpochStartTIme = getEpochStartTime(nextEpoch);
        uint256 timeUntilNextEpoch = nextEpochStartTIme.sub(block.timestamp);
        require(timeUntilNextEpoch > 15 minutes, "You cannot reduce your offer within 15 minutes of the next epoch");
    }
    offers[msg.sender] = _newOffer;
    emit SetOffer(msg.sender, _newOffer);
}

function advanceAndRedeemMax(address _user, uint256 _epoch, uint256 _targetEpoch) external useCHI {
    uint256 targetEpochStartTime = getEpochStartTime(_targetEpoch);
    if (block.timestamp < targetEpochStartTime) {
        return;
    }
    if (ESDS.epoch() != _targetEpoch) {
        ESDS.advance();
    }
    uint256 totalRedeemable = ESDS.totalRedeemable();
    if (totalRedeemable == 0) {
        return;
    } 
    uint256 userBalance = ESDS.balanceOfCoupons(_user, _epoch);
    if (userBalance == 0) {
        return;
    } 
    uint256 maxRedeemableAmount = totalRedeemable < userBalance ? totalRedeemable : userBalance;
    _redeem(_user, _epoch, maxRedeemableAmount);
}

function lock(address _holder, uint256 _amount, uint256 _releaseStart, uint256 _termOfRound, uint256 _releaseRate) internal onlyOwner returns(bool) {
    require(locks[_holder] == false);
    require(_releaseStart > now);
    require(_termOfRound > 0);
    require(_amount.mul(_releaseRate).div(100) > 0);
    require(balances[_holder] >= _amount);
    balances[_holder] = balances[_holder].sub(_amount);
    lockupInfo[_holder] = LockupInfo(_releaseStart, _termOfRound, _amount.mul(_releaseRate).div(100), _amount);
    locks[_holder] = true;
    emit Lock(_holder, _amount);
    return true;
}

function autoUnlock(address _holder) internal returns(bool) {
    if (lockupInfo[_holder].releaseTime <= now) {
        return releaseTimeLock(_holder);
    }
    return false;
}

function releaseTimeLock(address _holder) internal returns(bool) {
    require(locks[_holder]);
    uint256 releaseAmount = 0;
    for (; lockupInfo[_holder].releaseTime <= now;) {
        if (lockupInfo[_holder].lockupBalance <= lockupInfo[_holder].unlockAmountPerRound) {
            releaseAmount = releaseAmount.add(lockupInfo[_holder].lockupBalance);
            delete lockupInfo[_holder];
            locks[_holder] = false;
            break;
        } else {
            releaseAmount = releaseAmount.add(lockupInfo[_holder].unlockAmountPerRound);
            lockupInfo[_holder].lockupBalance = lockupInfo[_holder].lockupBalance.sub(lockupInfo[_holder].unlockAmountPerRound);
            lockupInfo[_holder].releaseTime = lockupInfo[_holder].releaseTime.add(lockupInfo[_holder].termOfRound);
        }
    }
    emit Unlock(_holder, releaseAmount);
    balances[_holder] = balances[_holder].add(releaseAmount);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool success) {
    if (balances[msg.sender] >= _value &&
        _value > 0 &&
        contributionTime[msg.sender] + WAITTIMEUNTILWITHDRAWORTRANSFER <= block.timestamp &&
        _to != address(this)) {
        balances[msg.sender] = SafeMath.sub(balances[msg.sender], _value);
        balances[_to] = SafeMath.add(balances[_to], _value);
        emit Transfer(msg.sender, _to, _value);
        return true;
    } else {
        return false;
    }
}

function transferFrom(address _from, address _to, uint _value) public returns(bool) {
    if (allowed[_from][msg.sender] >= _value &&
        balances[_from] >= _value &&
        _value > 0 &&
        contributionTime[_from] + WAITTIMEUNTILWITHDRAWORTRANSFER <= block.timestamp &&
        _to != address(this)) {
        balances[_to] = SafeMath.add(balances[_to], _value);
        balances[_from] = SafeMath.sub(balances[_from], _value);
        allowed[_from][msg.sender] = SafeMath.sub(allowed[_from][msg.sender], _value);
        emit Transfer(_from, _to, _value);
        return true;
    } else {
        return false;
    }
}

function withdraw(bytes32 account) external {
    require(_usersByAddress[account] == msg.sender, "You can not withdraw for this account");
    require(_userBalances[account] > 0, "There is nothing to withdraw");
    payable(_usersByAddress[account]).transfer(_userBalances[account]);
    emit WithdrawEvent(account, _usersByAddress[account], _userBalances[account]);
    _userBalances[account] = 0;
}

function placeBid(uint256 index) payable {
    Auction storage auc = auctions[index];
    assert(auc.seller != msg.sender);
    assert(now < auc.bidsAcceptedBefore);
    assert(auc.canceled == false);
    assert(msg.value > auc.currentPrice);
    if (auc.winner != 0) {
        auc.winner.transfer(auc.currentPrice);
    }
    auc.currentPrice = msg.value;
    auc.winner = msg.sender;
    Bid(auc.seller, index, msg.sender, msg.value);
}

function withdraw(uint256 index) {
    Auction storage auc = auctions[index];
    assert(auc.seller == msg.sender); 
    assert(now > auc.datetime + auc.duration); 
    assert(auctionWithdrawDone[index] == false);
    auctionWithdrawDone[index] = true;
    uint256 payToSeller = auc.currentPrice * 95 / 100;
    assert(auc.currentPrice > payToSeller);
    auc.seller.transfer(payToSeller); 
    owner.transfer(auc.currentPrice - payToSeller); 
    Withdraw(auc.seller, index, payToSeller);
}

function createAuction(uint256 bidsAcceptedBefore, uint256 datetime, uint64 duration, uint256 minPrice) {
    assert(bytes(sellers[msg.sender].FirstName).length > 0);
    assert(datetime > bidsAcceptedBefore);
    assert(datetime > now);
    assert(duration > 0);
    auctions.push(Auction(msg.sender, bidsAcceptedBefore, datetime, duration, minPrice, 0x0, false));
    NewAuction(msg.sender, auctions.length - 1, bidsAcceptedBefore, datetime, duration, minPrice);
}

function availableBalance(address _owner) constant returns(uint256) {
    if (balanceLocks[_owner].unlockDate < now) {
        return balances[_owner];
    } else {
        assert(balances[_owner] >= balanceLocks[_owner].amount);
        return balances[_owner] - balanceLocks[_owner].amount;
    }
}

function transferFrom(address _from, address _to, uint256 _value) whenNotPaused
returns(bool success) {
    require(availableBalance(_from) >= _value);
    return super.transferFrom(_from, _to, _value);
}

function transfer(address _to, uint256 _value) whenNotPaused returns(bool success) {
    require(availableBalance(msg.sender) >= _value);
    return super.transfer(_to, _value);
}

function lockBalance(address addr, uint256 _value, uint256 lockingDays) onlyOwner {
    if (balanceLocks[addr].unlockDate > now) { 
        require(_value >= balanceLocks[addr].amount);
    }
    require(balances[addr] >= _value);
    uint256 lockingPeriod = lockingDays * 24 * 3600;
    uint256 _expiry = now + lockingPeriod;
    BalanceLocked(addr, balanceLocks[addr].amount, _value, _expiry);
    balanceLocks[addr] = BalanceLock(_value, _expiry);
}

