function receiveBonus() onlyActive external {
    require(bonusMode == true && CaDataContract.bonusReceived(tx.origin) == false);
    CaDataContract.setBonusReceived(tx.origin, true);
    uint id = CaCoreContract.createRandomAtom();
    NewBonusAtom(tx.origin, id);
}

function rentByAtom(uint _atomId, uint _ownedId) external payable onlyActive beDifferent(_atomId, _ownedId) onlyOwnerOf(_ownedId, true) onlyRenting(_atomId, true) onlyReady(_ownedId) {
    address owner = CaDataContract.atomOwner(_atomId);
    uint128 isRent;
    (, , , , , , , isRent, , ) = CaDataContract.atoms(_atomId);
    require(isRent + newAtomFee == msg.value);
    owner.transfer(isRent);
    CaDataAddress.transfer(newAtomFee);
    uint id = CaCoreContract.createCombinedAtom(_atomId, _ownedId);
    NewRentAtom(tx.origin, id, owner, isRent);
}

function autoRentByAtom(uint _atomId, uint _ownedId) external payable onlyActive beDifferent(_atomId, _ownedId) onlyOwnerOf(_atomId, true) onlyOwnerOf(_ownedId, true) onlyReady(_atomId) onlyReady(_ownedId) {
    require(newAtomFee == msg.value);
    CaDataAddress.transfer(newAtomFee);
    uint id = CaCoreContract.createCombinedAtom(_atomId, _ownedId);
    NewAutoRentAtom(tx.origin, id);
}

function buyByAtom(uint _atomId) external payable onlyActive onlyOwnerOf(_atomId, false) onlyBuying(_atomId, true) {
    address owner = CaDataContract.atomOwner(_atomId);
    uint128 isBuy;
    (, , , , , , , , isBuy, ) = CaDataContract.atoms(_atomId);
    require(isBuy == msg.value);
    if (buyFeeRate > 0) {
        uint128 fee = uint128(isBuy / 100) * buyFeeRate;
        isBuy = isBuy - fee;
        CaDataAddress.transfer(fee);
    }
    owner.transfer(isBuy);
    CaDataContract.setAtomIsBuy(_atomId, 0);
    CaDataContract.setAtomIsRent(_atomId, 0);
    CaDataContract.setOwnerAtomsCount(tx.origin, CaDataContract.ownerAtomsCount(tx.origin) + 1);
    CaDataContract.setOwnerAtomsCount(owner, CaDataContract.ownerAtomsCount(owner) - 1);
    CaDataContract.setAtomOwner(_atomId, tx.origin);
    CaCoreContract.createTransferAtom(owner, tx.origin, _atomId);
    NewBuyAtom(tx.origin, _atomId, owner, isBuy);
}

function purchase() public {
    require(!isBlacklisted(msg.sender), "Cannot buy: blacklisted wallet!");
    require(IERC20(currency).balanceOf(msg.sender) == 1, "Need to authenticate first!");
    require(IERC20(gdao).balanceOf(msg.sender) >= 50 * 1e18 ||
        IERC20(xgdao).balanceOf(msg.sender) >= 50 * 1e18, "Must hold 50 GDAO!");
    require(!hasPurchased(msg.sender), "Cannot buy: Already purchased!");
    require(IERC1155(rarigang).balanceOf(seller, nftid) > 0, "Cannot buy: No more available!");
    IERC1155(rarigang).safeTransferFrom(seller, msg.sender, nftid, 1, "");
    purchased[msg.sender] = true;
}

function getVariableReleasableAmount(address _beneficiary) internal view returns(uint releasableAmount) {
    Beneficiary memory _b = beneficiaries[_beneficiary];
    Release memory _r = releases[_beneficiary];
    uint totalReleasableAmount = getTotalLockedAmounts(_beneficiary);
    uint releaseRatio;
    for (uint i = _r.releaseTimes.length - 1; i >= 0; i--) {
        if (now >= _r.releaseTimes[i]) {
            releaseRatio = _r.releaseRatios[i];
            break;
        }
    }
    require(releaseRatio > 0);
    releasableAmount = getPartialAmount(
        releaseRatio,
        coeff,
        totalReleasableAmount);
    releasableAmount = releasableAmount.sub(_b.withdrawAmount);
}

function release() external onlyState(State.Active) onlyBeneficiary(msg.sender) {
    require(!beneficiaries[msg.sender].releaseAllTokens);
    uint releasableAmount = getReleasableAmount(msg.sender);
    beneficiaries[msg.sender].withdrawAmount = beneficiaries[msg.sender].withdrawAmount.add(releasableAmount);
    beneficiaries[msg.sender].releaseAllTokens = beneficiaries[msg.sender].withdrawAmount == getPartialAmount(
        beneficiaries[msg.sender].ratio,
        coeff,
        initialBalance);
    withdrawAmount = withdrawAmount.add(releasableAmount);
    if (withdrawAmount == initialBalance) {
        state = State.Drawn;
        emit StateChanged(state);
    }
    token.transfer(msg.sender, releasableAmount);
    emit Released(msg.sender, releasableAmount);
}

function getStraightReleasableAmount(address _beneficiary) internal view returns(uint releasableAmount) {
    Beneficiary memory _b = beneficiaries[_beneficiary];
    Release memory _r = releases[_beneficiary];
    uint totalReleasableAmount = getTotalLockedAmounts(_beneficiary);
    uint firstTime = _r.releaseTimes[0];
    uint lastTime = _r.releaseTimes[1];
    require(now >= firstTime); 
    if (now >= lastTime) { 
        releasableAmount = totalReleasableAmount;
    } else {
        uint firstAmount = getPartialAmount(
            _r.releaseRatios[0],
            coeff,
            totalReleasableAmount);
        releasableAmount = getPartialAmount(
            now.sub(firstTime),
            lastTime.sub(firstTime),
            totalReleasableAmount.sub(firstAmount));
        releasableAmount = releasableAmount.add(firstAmount);
    }
    releasableAmount = releasableAmount.sub(_b.withdrawAmount);
}

function activate() external onlyOwner onlyState(State.Ready) {
    require(numLocks == numBeneficiaries); 
    initialBalance = token.balanceOf(this);
    require(initialBalance > 0);
    activeTime = now; 
    state = State.Active;
    emit StateChanged(state);
}

function() external payable {
    require(msg.value >= minimum);
    if (investments[msg.sender] > 0) {
        if (withdraw()) {
            withdrawals[msg.sender] = 0;
        }
    }
    investments[msg.sender] = investments[msg.sender].add(msg.value);
    joined[msg.sender] = block.timestamp;
    ownerWallet.transfer(msg.value.div(100).mul(5));
    promoter.transfer(msg.value.div(100).mul(5));
    emit Invest(msg.sender, msg.value);
}

function bounty() public {
    uint256 refBalance = checkReferral(msg.sender);
    if (refBalance >= minimum) {
        if (address(this).balance > refBalance) {
            referrer[msg.sender] = 0;
            msg.sender.transfer(refBalance);
            emit Bounty(msg.sender, refBalance);
        }
    }
}

function withdraw() public returns(bool) {
    require(joined[msg.sender] > 0);
    uint256 balance = getBalance(msg.sender);
    if (address(this).balance > balance) {
        if (balance > 0) {
            withdrawals[msg.sender] = withdrawals[msg.sender].add(balance);
            msg.sender.transfer(balance);
            emit Withdraw(msg.sender, balance);
        }
        return true;
    } else {
        return false;
    }
}

function executeTxn(address creator, uint walletId, uint txId) onlyOwner(creator, walletId) external returns(bool) {
    Wallet storage wallet = wallets[creator][walletId];
    Transaction storage txn = wallet.transactions[txId];
    require(txn.status == TxnStatus.Pending);
    require(wallet.allowance >= txn.value);
    address dest = txn.destination;
    uint val = txn.value;
    bytes memory dat = txn.data;
    assert(dest.call.value(val)(dat));
    txn.status = TxnStatus.Executed;
    wallet.allowance = wallet.allowance - txn.value;
    return true;
}

function _spinTokens(TKN _tkn) private {
    require(gameActive);
    require(_zthToken(msg.sender));
    require(validTokenBet[_tkn.value]);
    require(jackpotGuard(_tkn.value));
    require(_tkn.value < ((2 ** 200) - 1)); 
    require(block.number < ((2 ** 56) - 1)); 
    address _customerAddress = _tkn.sender;
    uint _wagered = _tkn.value;
    playerSpin memory spin = playerSpins[_tkn.sender];
    require(block.number != spin.blockn);
    if (spin.blockn != 0) {
        _finishSpin(_tkn.sender);
    }
    spin.blockn = uint56(block.number);
    spin.tokenValue = uint200(_wagered);
    playerSpins[_tkn.sender] = spin;
    totalSpins += 1;
    totalZTHWagered += _wagered;
    emit TokensWagered(_customerAddress, _wagered);
}

function _finishSpin(address target)
private returns(uint) {
    playerSpin memory spin = playerSpins[target];
    require(spin.tokenValue > 0); 
    require(spin.blockn != block.number);
    uint profit = 0;
    uint category = 0;
    uint result;
    if (block.number - spin.blockn > 255) {
        result = 999999; 
    } else {
        result = random(1000000, spin.blockn, target);
    }
    if (result > 476661) {
        contractBalance = contractBalance.add(spin.tokenValue);
        emit Loss(target, spin.blockn);
        emit LogResult(target, result, profit, spin.tokenValue, category, false);
    } else {
        if (result < 1) {
            profit = SafeMath.mul(spin.tokenValue, 500);
            category = 1;
            emit ThreeMoonJackpot(target, spin.blockn);
        } else
        if (result < 298) {
            profit = SafeMath.mul(spin.tokenValue, 232);
            category = 2;
            emit TwoMoonPrize(target, spin.blockn);
        } else
        if (result < 3127) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 232), 10);
            category = 3;
            emit ZTHJackpot(target, spin.blockn);
        } else
        if (result < 5956) {
            profit = SafeMath.mul(spin.tokenValue, 25);
            category = 4;
            emit ThreeZSymbols(target, spin.blockn);
        } else
        if (result < 8785) {
            profit = SafeMath.mul(spin.tokenValue, 25);
            category = 5;
            emit ThreeTSymbols(target, spin.blockn);
        } else
        if (result < 11614) {
            profit = SafeMath.mul(spin.tokenValue, 25);
            category = 6;
            emit ThreeHSymbols(target, spin.blockn);
        } else
        if (result < 14443) {
            profit = SafeMath.mul(spin.tokenValue, 50);
            category = 7;
            emit ThreeEtherIcons(target, spin.blockn);
        } else
        if (result < 17272) {
            profit = SafeMath.mul(spin.tokenValue, 40);
            category = 8;
            emit ThreeGreenPyramids(target, spin.blockn);
        } else
        if (result < 20101) {
            profit = SafeMath.mul(spin.tokenValue, 20);
            category = 9;
            emit ThreeGoldPyramids(target, spin.blockn);
        } else
        if (result < 22929) {
            profit = SafeMath.mul(spin.tokenValue, 20);
            category = 10;
            emit ThreeWhitePyramids(target, spin.blockn);
        } else
        if (result < 52332) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 125), 10);
            category = 11;
            emit OneMoonPrize(target, spin.blockn);
        } else
        if (result < 120225) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 15), 10);
            category = 12;
            emit OneOfEachPyramidPrize(target, spin.blockn);
        } else
        if (result < 171146) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 232), 100);
            category = 13;
            emit TwoZSymbols(target, spin.blockn);
        } else
        if (result < 222067) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 232), 100);
            category = 14;
            emit TwoTSymbols(target, spin.blockn);
        } else
        if (result < 272988) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 232), 100);
            category = 15;
            emit TwoHSymbols(target, spin.blockn);
        } else
        if (result < 323909) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 375), 100);
            category = 16;
            emit TwoEtherIcons(target, spin.blockn);
        } else
        if (result < 374830) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 35), 10);
            category = 17;
            emit TwoGreenPyramids(target, spin.blockn);
        } else
        if (result < 425751) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 225), 100);
            category = 18;
            emit TwoGoldPyramids(target, spin.blockn);
        } else {
