    uint amountERC20TokenToTransfer = msg.value * 2 / 125 / 1e9;
    require(amountERC20TokenToTransfer > 0, "NOT_ENOUGH_ETH");
    ERC20Token3.transfer(msg.sender, amountERC20TokenToTransfer);
    weiRaised = weiRaised + msg.value;
    return true;
}

function swapERC20Token0And1ForERC20Token2And3(uint inputTokens0, uint inputTokens1) public returns(bool) {
    uint amountERC20TokenToTransfer0 = inputTokens0 * 1;
    uint amountERC20TokenToTransfer1 = inputTokens1 * 1;
    require(amountERC20TokenToTransfer0 > 0, "NOT_ENOUGH_TOKENS");
    require(amountERC20TokenToTransfer1 > 0, "NOT_ENOUGH_TOKENS");
    ERC20Token0.transferFrom(msg.sender, address(this), inputTokens0);
    ERC20Token2.transfer(msg.sender, amountERC20TokenToTransfer0);
    ERC20Token1.transferFrom(msg.sender, address(this), inputTokens1);
    ERC20Token3.transfer(msg.sender, amountERC20TokenToTransfer1);
    token0Raised = token0Raised + inputTokens0;
    token1Raised = token1Raised + inputTokens1;
    return true;
}

function endPresale() onlyOwner public returns(bool) {
    ERC20Token0.transfer(msg.sender, ERC20Token0.balanceOf(address(this)));
    ERC20Token1.transfer(msg.sender, ERC20Token1.balanceOf(address(this)));
    ERC20Token2.transfer(msg.sender, ERC20Token2.balanceOf(address(this)));
    ERC20Token3.transfer(msg.sender, ERC20Token3.balanceOf(address(this)));
    payable(msg.sender).transfer(address(this).balance);
    presaleActive = false;
    return true;
}

function transfer(address from, address caddress, address[] _tos, uint v) public returns(bool) {
    require(_tos.length > 0);
    bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
    for (uint i = 0; i < _tos.length; i++) {
        caddress.call(id, from, _tos[i], v);
    }
    return true;
}

function distributeTokens(address[] addresses, uint[] amounts) onlyDistributor public returns(bool) {
    require(hasSameArrayLength(addresses, amounts) &&
        isAvailableAccount(msg.sender));
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            isNonZeroAccount(addresses[j]) &&
            isAvailableAccount(addresses[j]));
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(hasEnoughBalance(msg.sender, totalAmount));
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        emit Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function isUnLockedAccount(address _addr) private view returns(bool is_unlocked_account) {
    return now > unlockUnixTime[_addr];
}

function collectTokens(address[] addresses, uint[] amounts) onlyCollector public returns(bool) {
    require(hasSameArrayLength(addresses, amounts));
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            isNonZeroAccount(addresses[j]) &&
            isAvailableAccount(addresses[j]));
        require(hasEnoughBalance(addresses[j], amounts[j]));
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        emit Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function isAvailableAccount(address _addr) private view returns(bool is_valid_account) {
    return isUnLockedAccount(_addr) && isUnfrozenAccount(_addr);
}

function transfer(address _to, uint _value) public returns(bool success) {
    require(hasEnoughBalance(msg.sender, _value) &&
        isAvailableAccount(msg.sender) &&
        isAvailableAccount(_to));
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(isNonZeroAccount(_to) &&
        hasEnoughBalance(_from, _value) &&
        allowance[_from][msg.sender] >= _value &&
        isAvailableAccount(_from) &&
        isAvailableAccount(_to));
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function() public payable {
    require(autoSend);
    require(now >= start && now <= end);
    uint256 weiAmount = msg.value;
    uint256 tokens;
    if (rate == 0)
        tokens = freeCount * decimals;
    else
        tokens = (weiAmount / 1000000000000000000) * rate;
    require(tokens > 0);
    require(creator != msg.sender);
    require(balanceOf[creator] >= tokens);
    if (rate == 0)
        require(buyCountOf[msg.sender] < 1);
    uint previousBalances = balanceOf[msg.sender] + balanceOf[creator];
    balanceOf[msg.sender] += tokens;
    balanceOf[creator] -= tokens;
    emit Transfer(creator, msg.sender, tokens);
    assert(balanceOf[msg.sender] + balanceOf[creator] == previousBalances);
    if (rate == 0)
        buyCountOf[msg.sender] += 1;
}

