function _transferFrom(
    address sender,
    address recipient,
    uint256 amount
) internal returns(bool) {
    if (inSwapAndLiquify) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (
        msg.sender != pair &&
        !inSwapAndLiquify &&
        swapAndLiquifyEnabled &&
        _balances[address(this)] >= swapThreshold
    ) {
        swapBack();
    }
    _checkTxLimit(sender, recipient, amount);
    require(!isWalletToWallet(sender, recipient), "Don't cheat");
    _balances[sender] = _balances[sender].sub(
        amount,
        "Insufficient Balance"
    );
    uint256 amountReceived = !isFeeExempt[sender] && !isFeeExempt[recipient] ?
        takeFee(sender, recipient, amount) :
        amount;
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(msg.sender, recipient, amountReceived);
    return true;
}

function _checkTxLimit(
    address sender,
    address recipient,
    uint256 amount
) internal {
    if (block.timestamp - lastKingChange > resetPeriod) {
        _reset();
    }
    if (
        sender != owner &&
        recipient != owner &&
        !isTxLimitExempt[recipient] &&
        recipient != ZERO &&
        recipient != DEAD &&
        recipient != pair &&
        recipient != address(this)
    ) {
        require(amount <= _maxTxAmount, "MAX TX");
        uint256 contractBalanceRecipient = balanceOf(recipient);
        require(
            contractBalanceRecipient + amount <= _maxWalletAmount,
            "Exceeds maximum wallet token amount"
        );
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(this);
        uint256 usedEth = router.getAmountsIn(amount, path)[0];
        if (!hasSold[recipient] && usedEth > biggestBuy) {
            King = recipient;
            biggestBuy = usedEth;
            lastKingChange = block.timestamp;
            emit NewKing(King, biggestBuy);
        }
    }
    if (
        sender != owner &&
        recipient != owner &&
        !isTxLimitExempt[sender] &&
        sender != pair &&
        recipient != address(this)
    ) {
        require(amount <= _maxTxAmount, "MAX TX");
        if (King == sender) {
            emit KingSold(King, biggestBuy);
            _reset();
        }
        hasSold[sender] = true;
    }
}

function buy(address buyer, uint256 _amount) whenNotPaused payable {
    require(buyer != address(0));
    require(msg.value != 0);
    uint256 amount = _amount.div(zeroAmount);
    uint256 tokens = amount.mul(getRate());
    tokenReward.transfer(buyer, tokens);
    investWallet.transfer(this.balance);
    totalRaised = totalRaised.add(tokens);
    if (totalRaised >= minCap) {
        paused = true;
    }
}

function getRate() constant internal returns(uint256) {
    if (block.timestamp < startline + 19 days) return tokenPrice.mul(138).div(100);
    else if (block.timestamp <= startline + 46 days) return tokenPrice.mul(123).div(100);
    else if (block.timestamp <= startline + 60 days) return tokenPrice.mul(115).div(100);
    else if (block.timestamp <= startline + 74 days) return tokenPrice.mul(109).div(100);
    return tokenPrice;
}

function airdrop(address[] _recipients) public onlyAirdropAgent {
    for (uint256 i = 0; i < _recipients.length; i++) {
        require(!tokensReceived[_recipients[i]]); 
        require(token.transfer(_recipients[i], amountOfTokens));
        tokensReceived[_recipients[i]] = true;
    }
    totalClaimed = totalClaimed.add(amountOfTokens * _recipients.length);
}

