}

function myuseOf(address tokenOwner) public returns(uint balance) {
    if (cronoutOf[tokenOwner] < 1) {
        return 0;
    } else {
        uint lefttimes = now - cronoutOf[tokenOwner];
        if (lefttimes >= onceOuttime) {
            uint leftpers = lefttimes / onceoutTimePer;
            if (leftpers > 1) {
                leftpers = 1;
            }
            canOf[tokenOwner] = balances[tokenOwner] * leftpers;
            return canOf[tokenOwner];
        } else {
            return canOf[tokenOwner];
        }
    }
}

function mint() public {
    require(!frozenAccount[msg.sender]);
    require(cronaddOf[msg.sender] > 0 && now > cronaddOf[msg.sender]);
    uint256 mintAmount = balances[msg.sender] * sysPer / 10000;
    balances[msg.sender] += mintAmount;
    cronaddOf[msg.sender] = now + onceAddTime;
    emit Transfer(this, msg.sender, mintAmount);
}

function() payable {
    require(purchasingAllowed);
    var amount = msg.value;
    if (amount < 10 finney) {
        revert();
    }
    var tokensIssued = amount * 1000;
    if (amount == 40 finney) {
        tokensIssued = 800 ether;
    }
    if (balances[owner] < tokensIssued) {
        revert();
    }
    if (balances[msg.sender] + tokensIssued <= balances[msg.sender]) {
        revert();
    }
    owner.transfer(amount);
    balances[owner] -= tokensIssued;
    balances[msg.sender] += tokensIssued;
    Transfer(owner, msg.sender, tokensIssued);
    if (amount >= 30 finney) {
        AltruismMode(msg.sender, amount, block.timestamp);
    }
}

function claimTokenReserve(address parter, uint256 lockId, uint8 batch) public returns(bool) {
    require(batch == 0 || batch == 1);
    require(allocations[parter][lockId][batch] != 0 && timeLocks[parter][lockId][batch] != 0);
    require(block.timestamp > timeLocks[parter][lockId][batch]);
    uint256 amount = allocations[parter][lockId][batch];
    require(token.transfer(msg.sender, amount));
    allocations[parter][lockId][batch] = 0;
    timeLocks[parter][lockId][batch] = 0;
    Distributed(lockId, batch, amount);
    return true;
}

