function buyTokens(address beneficiary) isInWhitelist(beneficiary) whenNotPaused whenNotFinalized public payable returns(bool) {
    require(beneficiary != address(0));
    require(validPurchase());
    require(!hasEnded());
    require(!isContract(msg.sender));
    uint256 weiAmount = msg.value;
    uint256 tokens = getTokenAmount(weiAmount);
    require(tokenRaised.add(tokens) <= capTokens);
    weiRaised = weiRaised.add(weiAmount);
    tokenRaised = tokenRaised.add(tokens);
    require(token.transferFrom(tokenAddress, beneficiary, tokens));
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
    return true;
}

function Presale(uint256 _startTime, address _wallet, address _token, address _whitelist, uint256 _capETH, uint256 _capTokens, uint256 _minimumETH, uint256 _maximumETH) public {
    require(_startTime >= now);
    require(_wallet != address(0));
    require(_token != address(0));
    require(_whitelist != address(0));
    require(_capETH > 0);
    require(_capTokens > 0);
    require(_minimumETH > 0);
    require(_maximumETH > 0);
    startTime = _startTime;
    endTime = _startTime.add(19 weeks);
    wallet = _wallet;
    tokenAddress = _token;
    token = Identify(_token);
    whitelist = Whitelist(_whitelist);
    capWEI = _capETH * (10 ** uint256(18));
    capTokens = _capTokens * (10 ** uint256(6));
    minimumWEI = _minimumETH * (10 ** uint256(18));
    maximumWEI = _maximumETH * (10 ** uint256(18));
}

function hasEnded() public view returns(bool) {
    bool capReached = weiRaised >= capWEI;
    bool capTokensReached = tokenRaised >= capTokens;
    bool ended = now > endTime;
    return (capReached || capTokensReached) || ended;
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    bool underMaximumWEI = msg.value <= maximumWEI;
    bool withinCap = weiRaised.add(msg.value) <= capWEI;
    bool minimumWEIReached;
    if (capWEI.sub(weiRaised) < minimumWEI) {
        minimumWEIReached = true;
    } else {
        minimumWEIReached = msg.value >= minimumWEI;
    }
    return (withinPeriod && nonZeroPurchase) && (withinCap && (minimumWEIReached && underMaximumWEI));
}

function finalize() onlyMultisigWallet whenNotFinalized public returns(bool) {
    require(hasEnded());
    if (!(capWEI == weiRaised)) {
        uint256 remainingTokens = capTokens.sub(tokenRaised);
        require(token.burn(tokenAddress, remainingTokens));
    }
    require(token.transferOwnership(wallet));
    isFinalized = true;
    return true;
}

function vestedAmount() public returns(uint256) {
    currentBalance = token.balanceOf(this);
    totalBalance = currentBalance.add(released[token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration);
    }
}

function initialize() public onlyOwner {
    require(tokensAvailable() == initialTokens); 
    currentBalance = token.balanceOf(this);
    totalBalance = currentBalance.add(released[token]);
    initialized = true;
}

function release() public {
    require(initialized);
    uint256 unreleased = releasableAmount();
    require(unreleased > 0);
    released[token] = released[token].add(unreleased);
    token.safeTransfer(beneficiary, unreleased);
    emit Released(unreleased);
}

function revoke() public onlyOwner {
    require(revocable);
    require(!revoked[token]);
    uint256 balance = token.balanceOf(this);
    uint256 unreleased = releasableAmount();
    uint256 refund = balance.sub(unreleased);
    revoked[token] = true;
    token.safeTransfer(rollback, refund);
    emit Revoked();
}

function withdraw(uint amount) public {
    updateIndex();
    distributeReward(msg.sender);
    require(stakeToken.transfer(msg.sender, amount), "transfer failed");
    userCollateral[msg.sender] = userCollateral[msg.sender].sub(amount);
    totalCollateral = totalCollateral.sub(amount);
    emit Withdraw(msg.sender, amount);
}

function distributeReward(address user) private {
    if (userIndex[user] == 0 && index > 0) {
        userIndex[user] = doubleScale;
    }
    uint indexDelta = index - userIndex[user];
    userIndex[user] = index;
    uint rewardDelta = indexDelta.mul(userCollateral[user]).div(doubleScale);
    userAccrued[user] = userAccrued[user].add(rewardDelta);
    if (rewardToken.balanceOf(address(this)) >= userAccrued[user] && userAccrued[user] > 0) {
        if (rewardToken.transfer(user, userAccrued[user])) {
            userAccrued[user] = 0;
        }
    }
    emit RewardDistributed(user, rewardDelta, index);
}

function deposit(uint amount) public {
    updateIndex();
    distributeReward(msg.sender);
    require(stakeToken.transferFrom(msg.sender, address(this), amount), "transferFrom failed");
    userCollateral[msg.sender] = userCollateral[msg.sender].add(amount);
    totalCollateral = totalCollateral.add(amount);
    emit Deposit(msg.sender, amount);
}

function _oracle() internal {
    if (timestamp < block.timestamp && totalSupply > 0) {
        timestamp = block.timestamp;
        oracle_prev = oracle;
        oracle = price();
        Oracle(timestamp, oracle, oracle_prev);
    }
}

function deposit(uint256 token_amount, uint256 expected_assets) public lock {
    uint256 asset_deposit = calculateAssetIn(token_amount);
    require(asset_deposit > 0, "Hedgehog_Deposit: zero asset deposit");
    require(asset_deposit <= expected_assets, "Hedgehog_Deposit: deposit assets above expected");
    _oracle();
    TransferHelper.safeTransferFrom(asset, msg.sender, address(this), asset_deposit);
    _mint(msg.sender, token_amount);
    Deposit(msg.sender, asset_deposit, token_amount);
}

function get(bytes calldata data) external override returns(bool, uint256) {
    IUniswapV2Pair pair = abi.decode(data, (IUniswapV2Pair));
    uint32 blockTimestamp = uint32(block.timestamp);
    if (pairs[pair].blockTimestampLast == 0) {
        pairs[pair].blockTimestampLast = blockTimestamp;
        pairs[pair].priceCumulativeLast = _get(pair, blockTimestamp);
        return (false, 0);
    }
    uint32 timeElapsed = blockTimestamp - pairs[pair].blockTimestampLast; 
    if (timeElapsed < PERIOD) {
        return (true, pairs[pair].priceAverage);
    }
    uint256 priceCumulative = _get(pair, blockTimestamp);
    pairs[pair].priceAverage = FixedPoint
        .uq112x112(uint224((priceCumulative - pairs[pair].priceCumulativeLast) / timeElapsed))
        .mul(10 ** 18)
        .decode144();
    pairs[pair].blockTimestampLast = blockTimestamp;
    pairs[pair].priceCumulativeLast = priceCumulative;
    return (true, pairs[pair].priceAverage);
}

function peek(bytes calldata data) public view override returns(bool, uint256) {
    IUniswapV2Pair pair = abi.decode(data, (IUniswapV2Pair));
    uint32 blockTimestamp = uint32(block.timestamp);
    if (pairs[pair].blockTimestampLast == 0) {
        return (false, 0);
    }
    uint32 timeElapsed = blockTimestamp - pairs[pair].blockTimestampLast; 
    if (timeElapsed < PERIOD) {
        return (true, pairs[pair].priceAverage);
    }
    uint256 priceCumulative = _get(pair, blockTimestamp);
    uint144 priceAverage =
        FixedPoint.uq112x112(uint224((priceCumulative - pairs[pair].priceCumulativeLast) / timeElapsed)).mul(10 ** 18).decode144();
    return (true, priceAverage);
}

function withdraw()
onlyPeopleWithProfits()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyPeopleWithTokens()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAdminsFriends && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function executeProposal(uint256 _proposalID) internal {
    Proposal memory prop = proposals[_proposalID];
    bytes memory payload = abi.encodePacked(
        proposalTypes[prop.proposalType],
        prop.proposal
    );
    proposals[_proposalID].executed = true;
    (bool success, bytes memory returnData) = prop.destination.call {
        value: prop.value
    }(payload);
    proposals[_proposalID].success = success;
    proposals[_proposalID].returnData = returnData;
    emit ProposalApprovedAndEnforced(
        _proposalID,
        payload,
        success,
        returnData
    );
}

function depositToken(address token, uint amount) {
    require(token != 0);
    require(Token(token).transferFrom(msg.sender, this, amount));
    tokens[token][msg.sender] = safeAdd(tokens[token][msg.sender], amount);
    Deposit(token, msg.sender, amount, tokens[token][msg.sender]);
}

function stake(uint256 _noOfTokens) external {
    require(isStakingPaused == false, "Stake:: Staking is paused");
    require(_noOfTokens > 0, "Stake:: Can not stake Zero Tokens");
    require(_currentBlockTimestamp() > stakingOpenTime, "Stake:: Staking have not started for this pool");
    require(stakingPool > currentPool, "Stake:: Staking Pool is Full");
    require(_noOfTokens <= stakingPool.sub(currentPool), "Stake: Can not stake more than pool size");
    _stake(_noOfTokens);
}

function _stake(uint256 _noOfTokens) internal {
    IERC20(stakeToken).transferFrom(msg.sender, address(this), _noOfTokens);
    StakeHolders[msg.sender].amount = StakeHolders[msg.sender].amount.add(_noOfTokens);
    StakeHolders[msg.sender].isClaimed = false;
    StakeHolders[msg.sender].stakedBlock = block.number;
    StakeHolders[msg.sender].rewards = _calculateRewards(_noOfTokens);
    currentPool = currentPool.add(_noOfTokens);
    if (stakingPool == currentPool) {
        isPoolActive = true;
        stakingEndBlock = _currentBlockNumber().add(stakingDuration.mul(avgETHBlocksPerDay));
    }
    noOfStakes = noOfStakes.add(1);
    allStakeHolders.push(msg.sender);
    emit Staked(msg.sender, _noOfTokens);
}

function _claim() internal {
    uint256 claimedTokens = StakeHolders[msg.sender].amount;
    uint256 claimedRewards = StakeHolders[msg.sender].rewards;
    IERC20(stakeToken).transfer(msg.sender, claimedTokens);
    IERC20(stakeToken).transfer(msg.sender, claimedRewards);
    StakeHolders[msg.sender].isClaimed = true;
    StakeHolders[msg.sender].amount = claimedTokens;
    StakeHolders[msg.sender].rewards = claimedRewards;
    StakeHolders[msg.sender].releaseBlock = _currentBlockNumber();
    StakeHolders[msg.sender].claimedOn = _currentBlockTimestamp();
    updateFullyClaimed();
    emit Claimed(msg.sender, claimedTokens, claimedRewards);
}

function buyin()
public
payable
when_not_halted
when_active
only_eligible(msg.sender) {
    flushEra();
    if (currentBonus > 0) {
        if (now >= beginTime + BONUS_MIN_DURATION 
            &&
            lastNewInterest + BONUS_LATCH <= block.number 
        ) {
            currentBonus--;
        }
        if (now >= beginTime + BONUS_MAX_DURATION) {
            currentBonus = 0;
        }
        if (buyins[msg.sender].received == 0) { 
            lastNewInterest = uint32(block.number);
        }
    }
    uint accounted;
    bool refund;
    uint price;
    (accounted, refund, price) = theDeal(msg.value);
    require(!refund);
    buyins[msg.sender].accounted += uint128(accounted);
    buyins[msg.sender].received += uint128(msg.value);
    totalAccounted += accounted;
    totalReceived += msg.value;
    endTime = calculateEndTime();
    Buyin(msg.sender, accounted, msg.value, price);
    treasury.transfer(msg.value);
}

function theDeal(uint _value)
public
constant
when_active
returns(uint accounted, bool refund, uint price) {
    uint _bonus = bonus(_value);
    price = currentPrice();
    accounted = _value + _bonus;
    uint available = tokensAvailable();
    uint tokens = accounted / price;
    refund = (tokens > available);
}

function tokensAvailable() public constant when_active returns(uint tokens) {
    uint _currentCap = totalAccounted / currentPrice();
    if (_currentCap >= tokenCap) {
        return 0;
    }
    return tokenCap - _currentCap;
}

function isActive() public constant returns(bool) {
    return now >= beginTime && now < endTime;
}

function allFinalised() public constant returns(bool) {
    return now >= endTime && totalAccounted == totalFinalised;
}

function finalise(address _who)
public
when_not_halted
when_ended
only_buyins(_who) {
    if (endPrice == 0) {
        endPrice = totalAccounted / tokenCap;
        Ended(endPrice);
    }
    uint total = buyins[_who].accounted;
    uint tokens = total / endPrice;
    totalFinalised += total;
    delete buyins[_who];
    require(tokenContract.transferFrom(treasury, _who, tokens));
    Finalised(_who, tokens);
    if (totalFinalised == totalAccounted) {
        Retired();
    }
}

function flushEra() private {
    uint currentEra = (now - beginTime) / ERA_PERIOD;
    if (currentEra > eraIndex) {
        Ticked(eraIndex, totalReceived, totalAccounted);
    }
    eraIndex = currentEra;
}

function buyTokens(address beneficiary)
public
payable
whenNotPaused
isWhitelisted(beneficiary) {
    require(beneficiary != address(0));
    require(validPurchase() && tokensSold < crowdsaleCap);
    if (isMinting) {
        require(tokenOnSale.owner() == address(this), "The token owner must be contract address!");
    }
    if (!isWeiAccepted) {
        require(msg.value == 0);
    } else if (msg.value > 0) {
        buyTokensWithWei(beneficiary);
    }
    uint256 starAllocationToTokenSale = starToken.allowance(beneficiary, this);
    if (starAllocationToTokenSale > 0) {
        uint256 tokens = starAllocationToTokenSale.mul(starRate).div(1000);
        if (tokensSold.add(tokens) > crowdsaleCap) {
            tokens = crowdsaleCap.sub(tokensSold);
            starAllocationToTokenSale = tokens.div(starRate).div(1000);
        }
        starRaised = starRaised.add(starAllocationToTokenSale);
        tokensSold = tokensSold.add(tokens);
        sendPurchasedTokens(beneficiary, tokens);
        emit TokenPurchaseWithStar(msg.sender, beneficiary, starAllocationToTokenSale, tokens);
        starToken.transferFrom(beneficiary, wallet, starAllocationToTokenSale);
        wallet.splitStarFunds();
    }
}

function validPurchase() internal view returns(bool) {
    return now >= startTime && now <= endTime;
}

function initCrowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate) public {
    require(
        startTime == 0 && endTime == 0 && rate == 0,
        "Global variables must be empty when initializing crowdsale!"
    );
    require(_startTime >= now, "_startTime must be more than current time!");
    require(_endTime >= _startTime, "_endTime must be more than _startTime!");
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
}

function updateAd(uint256 id) public payable {
    require(msg.value >= adPriceMultiple.mul(adPriceHour));
    require(block.timestamp > purchaseTimestamp.add(purchaseSeconds));
    require(id > 0);
    theInvestor.send(msg.value.div(10));
    lastOwner.send(msg.value.div(2));
    if (msg.value >= adPriceMultiple.mul(adPriceWeek)) {
        purchaseSeconds = 604800; 
    } else if (msg.value >= adPriceMultiple.mul(adPriceDay)) {
        purchaseSeconds = 86400; 
    } else if (msg.value >= adPriceMultiple.mul(adPriceHalfDay)) {
        purchaseSeconds = 43200; 
    } else {
        purchaseSeconds = 3600; 
    }
    dappId = id;
    purchaseTimestamp = block.timestamp;
    lastOwner = msg.sender;
}

function updateInvestor() public payable {
    require(msg.value >= investmentMin);
    theInvestor.send(msg.value.div(100).mul(60));
    investmentMin = investmentMin.mul(2);
    theInvestor = msg.sender;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "To or From address is blacklisted.");
    if (!isTradingEnabled) {
        require(_isExcluded[to] || _isExcluded[from], "Trading is not yet enabled. Be patient!");
    } else if (block.timestamp - startTime < 300 && from == uniswapV2Pair) {
        require(amount <= 10 ** 9 * (10 ** 18), "Over max buy amt.");
    } else if (to == uniswapV2Pair) {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();
        uint[] memory amounts = uniswapV2Router.getAmountsOut(amount, path);
        require(amounts[1] <= maxSellAmt);
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 swapTokens = contractTokenBalance.div(100);
        swapAndLiquify(swapTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (from == uniswapV2Pair) {
            fees = amount.mul(buyFee).div(1000);
        } else if (to == uniswapV2Pair) {
            fees = amount.mul(sellFee).div(1000);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function swapAndLiquify(uint256 tokens) private {
    uint256 half = tokens.div(2);
    uint256 otherHalf = tokens.sub(half);
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(half);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    addLiquidity(otherHalf, newBalance);
}

function isValidOrder(uint256[5] memory tradeValues, address[2] memory tradeAddresses, uint8 v, bytes32[2] memory rs) public view returns(bool) {
    bytes32 orderHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4]));
    if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", orderHash)), v, rs[0], rs[1]) != tradeAddresses[1]) {
        return false;
    }
    if (IERC1155(baeContract).balanceOf(tradeAddresses[1], tradeValues[0]) < tradeValues[1] - orderFills[orderHash]) {
        return false;
    }
    if (tradeValues[3] < block.timestamp) {
        return false;
    }
    return true;
}

function buyArtworkETH(uint256[6] memory tradeValues, address payable[2] memory tradeAddresses, uint8 v, bytes32[2] memory rs) public payable returns(bool success) {
    require(tradeValues[3] > block.timestamp, "Expired");
    require(tradeAddresses[0] == address(0), "Not an ETH Trade");
    bytes32 orderHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4]));
    require(ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", orderHash)), v, rs[0], rs[1]) == tradeAddresses[1], "Invalid Order");
    require(orderFills[orderHash].add(tradeValues[5]) <= tradeValues[1], "Trade amount too high");
    require(msg.value >= tradeValues[2].mul(tradeValues[5]), "Insufficent Balance");
    uint256 amount = (tradeValues[2].mul(tradeValues[5]));
    IERC1155(baeContract).safeTransferFrom(tradeAddresses[1], msg.sender, tradeValues[0], tradeValues[5], "");
    feeAccount.transfer(amount.mul(10).div(1000));
    owner.transfer(amount.mul(fee).div(1000));
    payable(IERC1155(baeContract).creators(tradeValues[0])).transfer(amount.mul(creatorFee).div(1000));
    tradeAddresses[1].transfer(amount.mul(1000 - fee - creatorFee - 10).div(1000));
    msg.sender.transfer(msg.value - amount);
    orderFills[orderHash] = orderFills[orderHash].add(tradeValues[5]);
    emit Trade(tradeValues[0], tradeValues[5], tradeAddresses[0], tradeValues[2].mul(tradeValues[5]), msg.sender, tradeAddresses[1], orderHash);
    return true;
}

function releasableBonus(address _owner) public constant returns(uint256) {
    uint256 releaseTokens = 0;
    if (block.timestamp > (startingTimestamp.add(phase1Duration))) {
        releaseTokens = releaseTokens.add(lockupPhase1[_owner]);
    }
    if (block.timestamp > (startingTimestamp.add(phase2Duration))) {
        releaseTokens = releaseTokens.add(lockupPhase2[_owner]);
    }
    if (block.timestamp > (startingTimestamp.add(phase3Duration))) {
        releaseTokens = releaseTokens.add(lockupPhase3[_owner]);
    }
    if (block.timestamp > (startingTimestamp.add(phase4Duration))) {
        releaseTokens = releaseTokens.add(lockupPhase4[_owner]);
    }
    return releaseTokens;
}

function isValidPurchase(uint256 value, uint256 amount) internal constant returns(bool) {
    bool validTimestamp = startingTimestamp <= block.timestamp && endingTimestamp >= block.timestamp;
    bool validValue = value != 0;
    bool validRate = tokenPriceInEth > 0;
    bool validAmount = tokensForSale.sub(totalTokenSold) >= amount && amount > 0;
    return validTimestamp && validValue && validRate && validAmount && !isClose;
}

function releaseBonus() public {
    uint256 releaseTokens = 0;
    if (block.timestamp > (startingTimestamp.add(phase1Duration))) {
        releaseTokens = releaseTokens.add(lockupPhase1[msg.sender]);
        lockupPhase1[msg.sender] = 0;
    }
    if (block.timestamp > (startingTimestamp.add(phase2Duration))) {
        releaseTokens = releaseTokens.add(lockupPhase2[msg.sender]);
        lockupPhase2[msg.sender] = 0;
    }
    if (block.timestamp > (startingTimestamp.add(phase3Duration))) {
        releaseTokens = releaseTokens.add(lockupPhase3[msg.sender]);
        lockupPhase3[msg.sender] = 0;
    }
    if (block.timestamp > (startingTimestamp.add(phase4Duration))) {
        releaseTokens = releaseTokens.add(lockupPhase4[msg.sender]);
        lockupPhase4[msg.sender] = 0;
    }
    totalLockedBonus = totalLockedBonus.sub(releaseTokens);
    token.transfer(msg.sender, releaseTokens);
}

function close() onlyOwner public {
    uint256 tokens = token.balanceOf(this);
    token.transfer(owner, tokens);
    withdraw();
    isClose = true;
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != address(0));
    uint256 _value = msg.value;
    uint256 tokens = calculate(_value);
    uint256 bonusTokens = calculate(getBonus(_value));
    lockBonus(beneficiary, bonusTokens);
    uint256 _totalTokens = tokens.add(bonusTokens);
    require(isValidPurchase(_value, _totalTokens));
    totalTokenSold = totalTokenSold.add(_totalTokens);
    totalEtherRaised = totalEtherRaised.add(_value);
    etherRaisedPerWallet[msg.sender] = etherRaisedPerWallet[msg.sender].add(_value);
    token.transfer(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, _value, tokens, now);
}

function initialize(uint256 _requiredSignatures, address[] _initialValidators, address _owner)
external
onlyRelevantSender
returns(bool) {
    require(!isInitialized());
    _setOwner(_owner);
    require(_requiredSignatures != 0);
    require(_initialValidators.length >= _requiredSignatures);
    for (uint256 i = 0; i < _initialValidators.length; i++) {
        require(_initialValidators[i] != address(0) && _initialValidators[i] != F_ADDR);
        require(!isValidator(_initialValidators[i]));
        if (i == 0) {
            setNextValidator(F_ADDR, _initialValidators[i]);
            if (_initialValidators.length == 1) {
                setNextValidator(_initialValidators[i], F_ADDR);
            }
        } else if (i == _initialValidators.length - 1) {
            setNextValidator(_initialValidators[i - 1], _initialValidators[i]);
            setNextValidator(_initialValidators[i], F_ADDR);
        } else {
            setNextValidator(_initialValidators[i - 1], _initialValidators[i]);
        }
        emit ValidatorAdded(_initialValidators[i]);
    }
    setValidatorCount(_initialValidators.length);
    uintStorage[REQUIRED_SIGNATURES] = _requiredSignatures;
    uintStorage[DEPLOYED_AT_BLOCK] = block.number;
    setInitialize();
    emit RequiredSignaturesChanged(_requiredSignatures);
    return isInitialized();
}

function createDividendWithCheckpoint(uint256 _maturity, uint256 _expiry, uint256 _checkpointId) payable public onlyOwner {
    require(_expiry > _maturity);
    require(_expiry > now);
    require(msg.value > 0);
    require(_checkpointId <= ISecurityToken(securityToken).currentCheckpointId());
    uint256 dividendIndex = dividends.length;
    uint256 currentSupply = ISecurityToken(securityToken).totalSupplyAt(_checkpointId);
    dividends.push(
        Dividend(
            _checkpointId,
            now,
            _maturity,
            _expiry,
            msg.value,
            0,
            currentSupply,
            false
        )
    );
    emit EtherDividendDeposited(msg.sender, _checkpointId, now, _maturity, _expiry, msg.value, currentSupply, dividendIndex);
}

function _payDividend(address _payee, Dividend storage _dividend, uint256 _dividendIndex) internal {
    uint256 claim = calculateDividend(_dividendIndex, _payee);
    _dividend.claimed[_payee] = true;
    _dividend.claimedAmount = claim.add(_dividend.claimedAmount);
    if (claim > 0) {
        if (_payee.send(claim)) {
            emit EtherDividendClaimed(_payee, _dividendIndex, claim);
        } else {
            _dividend.claimed[_payee] = false;
            emit EtherDividendClaimFailed(_payee, _dividendIndex, claim);
        }
    }
}

function createDividend(uint256 _maturity, uint256 _expiry) payable public onlyOwner {
    require(_expiry > _maturity);
    require(_expiry > now);
    require(msg.value > 0);
    uint256 dividendIndex = dividends.length;
    uint256 checkpointId = ISecurityToken(securityToken).createCheckpoint();
    uint256 currentSupply = ISecurityToken(securityToken).totalSupply();
    dividends.push(
        Dividend(
            checkpointId,
            now,
            _maturity,
            _expiry,
            msg.value,
            0,
            currentSupply,
            false
        )
    );
    emit EtherDividendDeposited(msg.sender, checkpointId, now, _maturity, _expiry, msg.value, currentSupply, dividendIndex);
}

function reclaimDividend(uint256 _dividendIndex) public onlyOwner {
    require(_dividendIndex < dividends.length, "Incorrect dividend index");
    require(now >= dividends[_dividendIndex].expiry, "Dividend expiry is in the future");
    require(!dividends[_dividendIndex].reclaimed, "Dividend already claimed");
    Dividend storage dividend = dividends[_dividendIndex];
    dividend.reclaimed = true;
    uint256 remainingAmount = dividend.amount.sub(dividend.claimedAmount);
    msg.sender.transfer(remainingAmount);
    emit EtherDividendReclaimed(msg.sender, _dividendIndex, remainingAmount);
}

function pullDividendPayment(uint256 _dividendIndex) public validDividendIndex(_dividendIndex) {
    Dividend storage dividend = dividends[_dividendIndex];
    require(!dividend.claimed[msg.sender], "Dividend already reclaimed");
    _payDividend(msg.sender, dividend, _dividendIndex);
}

function getDividendIndex(uint256 _checkpointId) public view returns(uint256[]) {
    uint256 counter = 0;
    for (uint256 i = 0; i < dividends.length; i++) {
        if (dividends[i].checkpointId == _checkpointId) {
            counter++;
        }
    }
    uint256[] memory index = new uint256[](counter);
    counter = 0;
    for (uint256 j = 0; j < dividends.length; j++) {
        if (dividends[j].checkpointId == _checkpointId) {
            index[counter] = j;
            counter++;
        }
    }
    return index;
}

function end_ICO() external onlyOwner atStage(Stages.ICO) {
    require(now > ico_enddate);
    stage = Stages.ENDED;
    icoRunningStatus = false;
    uint256 x = balances[address(this)];
    balances[owner] = (balances[owner]).add(balances[address(this)]);
    balances[address(this)] = 0;
    emit Transfer(address(this), owner, x);
}

function getCurrentTokenPrice() private returns(uint) {
    uint price_tokn;
    bonusCalculationFactor = (block.timestamp.sub(ico_startdate)).div(3600); 
    if (bonusCalculationFactor == 0)
        price_tokn = 70; 
    else if (bonusCalculationFactor >= 1 && bonusCalculationFactor < 24)
        price_tokn = 75; 
    else if (bonusCalculationFactor >= 24 && bonusCalculationFactor < 168)
        price_tokn = 80; 
    else if (bonusCalculationFactor >= 168 && bonusCalculationFactor < 336)
        price_tokn = 90; 
    else if (bonusCalculationFactor >= 336)
        price_tokn = 100; 
    return price_tokn;
}

function() public payable {
    require(stage != Stages.ENDED);
    require(!stopped && msg.sender != owner);
    if (stage == Stages.PREICO && now <= preico_enddate) {
        require((msg.value).mul(priceFactor.mul(100)) >= (pre_minContribution.mul(10 ** 18)));
        y();
    } else if (stage == Stages.ICO && now <= ico_enddate) {
        _price_tokn = getCurrentTokenPrice();
        y();
    } else {
        revert();
    }
}

function purchase(address _reciever) public payable nonReentrant returns(bool) {
    uint256 tokens = calculate(msg.value);
    require(tokens >= minCap, "ValueError");
    require(tokens <= maxCap, "ValueError");
    require(isWhitelisted(_reciever), "Address not verified");
    purchased[_reciever] = SafeMath.add(purchased[_reciever], tokens);
    if (locked) {
        allocated[_reciever] = SafeMath.add(allocated[_reciever], tokens);
        ethWallet.transfer(msg.value);
    } else {
        IERC20(edgexContract).transfer(_reciever, tokens);
        IERC20(edgexContract).transfer(
            organisation,
            SafeMath.div(tokens, 100)
        );
        ethWallet.transfer(msg.value);
    }
    History storage h = history[_reciever];
    h.timestamps.push(block.timestamp);
    h.amounts.push(tokens);
    h.price.push(presalePrice);
    emit Purchase(_reciever, tokens);
    return true;
}

function allocate(uint256 _tokens, address _user, uint256 _method) public onlyGovernor nonReentrant returns(bool) {
    require(_tokens >= minCap, "ValueError");
    require(_tokens <= maxCap, "ValueError");
    if (locked) {
        allocated[_user] = SafeMath.add(allocated[_user], _tokens);
        purchased[_user] = SafeMath.add(purchased[_user], _tokens);
    } else {
        IERC20(edgexContract).transfer(_user, _tokens);
        IERC20(edgexContract).transfer(
            organisation,
            SafeMath.div(_tokens, 100)
        );
    }
    History storage h = history[_user];
    h.timestamps.push(block.timestamp);
    h.amounts.push(_tokens);
    h.price.push(presalePrice);
    h.paymentMethod.push(_method);
    emit Purchase(_user, _tokens);
    return true;
}

function closeAndTransferTokenOwnership() onlyOwner {
    require(now > endTime);
    uint256 toMint = token.totalSupply().mul(15).div(100);
    token.mint(owner, toMint);
    token.transferOwnership(owner);
}

function alchemy(uint256 _tokenAmount) onlyOwner returns(bool) {
    require(token != 0x0);
    uint256 amount = convert2Platinum(_tokenAmount);
    bool reduced = coin.reduce(_tokenAmount);
    require(reduced);
    total = total.add(amount);
    Alchemy(amount, total);
    return true;
}

function buy(string _index, address buyer) onlyOwner returns(bool) {
    require(token != 0x0);
    bytes32 _bindex = ConvertStringByte.stringToBytes32(_index);
    uint256 fee = coin.fee();
    require(storehouse[_bindex].amount > 0);
    Bullion bullion = storehouse[_bindex];
    uint256 tokenPrice = convert2PlatinumToken(bullion.amount);
    uint256 tokenPriceFee = tokenPrice.add(fee);
    bool transfered = coin.transferFrom(buyer, coin.owner(), tokenPriceFee);
    require(transfered);
    bool reduced = coin.reduce(tokenPrice);
    require(reduced);
    for (uint256 index = 0; index < storehouseIndex.length; index++) {
        Bullion _bullion = storehouse[storehouseIndex[index]];
        if (_bullion.index.toSlice().equals(_index.toSlice())) {
            delete storehouseIndex[index];
        }
    }
    delete storehouse[_bindex];
    Buy(_index, buyer, fee, tokenPrice);
    return true;
}

function mint(uint256 _ptAmount) onlyOwner returns(bool) {
    require(token != 0x0);
    uint256 amount = convert2PlatinumToken(_ptAmount);
    bool produced = coin.produce(amount);
    require(produced);
    total = total.sub(_ptAmount);
    Mint(_ptAmount, total);
    return true;
}

function _deliverTokens(address _beneficiary, uint256 _tokenAmount) internal {
