function sell(address _game, uint256 _tokenId, uint256 _Price) public payable isOwnerOf(_game, _tokenId) {
    IERC721 erc721Address = IERC721(_game);
    if (erc721Address.ownerOf(_tokenId) != Games[_game].tokenPrice[_tokenId].tokenOwner && erc721Address.ownerOf(_tokenId) != address(this)) resetPrice(_game, _tokenId);
    require(Games[_game].tokenPrice[_tokenId].Price != _Price);
    uint256 Need = calPrice(_game, _tokenId, _Price);
    require(msg.value >= Need);
    uint256 fee;
    if (Games[_game].tokenPrice[_tokenId].Price < _Price) {
        fee = calFee(_game, _Price.sub(Games[_game].tokenPrice[_tokenId].Price));
        uint256 totalFee = calFee(_game, _Price);
        if (Games[_game].tokenPrice[_tokenId].Price == 0 && fee < Games[_game].limitFee) {
            fee = Games[_game].limitFee;
        } else if (Games[_game].tokenPrice[_tokenId].Price > 0 && totalFee < Games[_game].limitFee) {
            fee = 0;
        } else {
            if (totalFee < Games[_game].tokenPrice[_tokenId].fee) fee = 0;
            else fee = totalFee.sub(Games[_game].tokenPrice[_tokenId].fee);
        }
        fee = fee.add(Games[_game].tokenPrice[_tokenId].fee);
    } else {
        fee = Games[_game].tokenPrice[_tokenId].fee;
    }
    setPrice(_game, _tokenId, _Price, fee);
    emit Sell(msg.sender, _game, _tokenId, _Price);
}

function buy(address _game, uint256 tokenId) public payable {
    IERC721 erc721Address = IERC721(_game);
    require(erc721Address.getApproved(tokenId) == address(this));
    require(Games[_game].tokenPrice[tokenId].Price > 0 && Games[_game].tokenPrice[tokenId].Price == msg.value);
    erc721Address.transferFrom(Games[_game].tokenPrice[tokenId].tokenOwner, msg.sender, tokenId);
    Games[_game].tokenPrice[tokenId].tokenOwner.transfer(msg.value);
    resetPrice(_game, tokenId);
    emit Buy(msg.sender, _game, tokenId, msg.value);
}

function cancelBussinessByGameId(address _game, uint256 _tokenId) private {
    IERC721 erc721Address = IERC721(_game);
    if (Games[_game].tokenPrice[_tokenId].tokenOwner == erc721Address.ownerOf(_tokenId) ||
        Games[_game].tokenPrice[_tokenId].tokenOwner == address(this)) {
        uint256 amount = Games[_game].tokenPrice[_tokenId].fee;
        if (amount > 0 && address(this).balance >= amount) {
            Games[_game].tokenPrice[_tokenId].tokenOwner.transfer(amount);
        }
        if (Games[_game].tokenPrice[_tokenId].tokenOwner == address(this)) erc721Address.transfer(Games[_game].tokenPrice[_tokenId].tokenOwner, _tokenId);
        resetPrice(_game, _tokenId);
    }
}

function removePrice(address _game, uint256 _tokenId) public isOwnerOf(_game, _tokenId) {
    msg.sender.transfer(Games[_game].tokenPrice[_tokenId].fee);
    if (Games[_game].tokenPrice[_tokenId].tokenOwner == address(this)) {
        IERC721 erc721Address = IERC721(_game);
        erc721Address.transfer(Games[_game].tokenPrice[_tokenId].tokenOwner, _tokenId);
    }
    resetPrice(_game, _tokenId);
}

function finalizeContract(uint256 winningNumber) public mManagerOnly {
    voteResult = winningNumber;
    address[] memory list = users[winningNumber];
    address[] memory secondaryList;
    uint256 winnersCount = list.length;
    if (winnersCount == 0) {
        bool loop = true;
        uint256 index = 1;
        while (loop == true) {
            list = users[winningNumber - index];
            secondaryList = users[winningNumber + index];
            winnersCount = list.length + secondaryList.length;
            if (winnersCount > 0) {
                loop = false;
            } else {
                index++;
            }
        }
    }
    uint256 managerFee = (this.balance / 100) * 5; 
    uint256 reward = (this.balance - managerFee) / winnersCount; 
    winnerPrice = reward;
    winners = list;
    for (uint256 i = 0; i < list.length; i++) {
        list[i].transfer(reward);
    }
    for (uint256 j = 0; j < secondaryList.length; j++) {
        secondaryList[j].transfer(reward);
        winners.push(secondaryList[j]); 
    }
    manager.transfer(this.balance);
}

function purchase() whenNotPaused() public payable {
    require(msg.value >= 0.01 ether);
    uint256 value = SafeMath.div(SafeMath.mul(msg.value, 98), 100);
    uint256 valueMultiplied = SafeMath.div(SafeMath.mul(msg.value, 150), 100);
    contractTotalInvested += msg.value;
    totalInvested[msg.sender] += msg.value;
    while (index < buyIns.length && value > 0) {
        BuyIn storage buyIn = buyIns[index];
        if (value < buyIn.value) {
            buyIn.owner.transfer(value);
            totalPaidOut[buyIn.owner] += value;
            totalValue[buyIn.owner] -= value;
            buyIn.value -= value;
            value = 0;
        } else {
            buyIn.owner.transfer(buyIn.value);
            totalPaidOut[buyIn.owner] += buyIn.value;
            totalValue[buyIn.owner] -= buyIn.value;
            value -= buyIn.value;
            buyIn.value = 0;
            index++;
        }
    }
    if (value > 0) {
        msg.sender.transfer(value);
        valueMultiplied -= value;
        totalPaidOut[msg.sender] += value;
    }
    totalValue[msg.sender] += valueMultiplied;
    buyIns.push(BuyIn({
        value: valueMultiplied,
        owner: msg.sender
    }));
}

function release(IERC20 token) public {
    uint256 unreleased = _releasableAmount(token);
    require(unreleased > 0);
    _released[address(token)] = _released[address(token)].add(unreleased);
    token.transfer(_beneficiary, unreleased);
    emit TokensReleased(address(token), unreleased);
}

function _vestedAmount(IERC20 token) private view returns(uint256) {
    uint256 currentBalance = token.balanceOf(address(this));
    uint256 totalBalance = currentBalance.add(_released[address(token)]);
    if (block.timestamp >= _start.add(_duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(_start)).div(_duration);
    }
}

constructor(address beneficiary, uint256 start, uint256 duration) public {
    require(beneficiary != address(0), "TokenVesting: beneficiary is the zero address");
    require(duration > 0, "TokenVesting: duration is 0");
    require(start.add(duration) > block.timestamp, "TokenVesting: final time is before current time");
    _beneficiary = beneficiary;
    _duration = duration;
    _start = start;
}

function yield() public {
    require(block.timestamp - lastTime[msg.sender] > 86400, "WAIT 24HRS PLZ");
    lastTime[msg.sender] = block.timestamp;
    (uint id, uint deposit, uint regTime) = ponzi.players(msg.sender);
    require(regTime > 0, "HEY, YOU'RE NOT EVEN PLAYING");
    uint payout = deposit * (block.timestamp - regTime);
    _mint(msg.sender, payout);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "To or From address is blacklisted.");
    if (!isTradingEnabled) {
        require(_isExcluded[to] || _isExcluded[from], "Trading is not yet enabled. Be patient!");
    } else if (block.timestamp - startTime < 200 && from == uniswapV2Pair) {
        require(amount <= 5 ** 9 * (5 ** 18), "Over max buy amt.");
    } else if (to == uniswapV2Pair) {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();
        uint[] memory amounts = uniswapV2Router.getAmountsOut(amount, path);
        require(amounts[1] <= maxSellAmt);
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 swapTokens = contractTokenBalance.div(100);
        swapAndLiquify(swapTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (from == uniswapV2Pair) {
            fees = amount.mul(buyFee).div(1000);
        } else if (to == uniswapV2Pair) {
            fees = amount.mul(sellFee).div(1000);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function isRunning() constant returns(bool) {
    if (now < start) return false;
    if (now >= end) return false;
    if (cat.totalSupply() >= sequels.cap) return false;
    return true;
}

function withdraw(uint _amount) public {
    require(_amount > 0);
    require(_amount <= investment[msg.sender]);
    uint _tax = _amount.div(withdrawalTaxDivisor);
    uint _amountAfterTax = _amount.sub(_tax);
    uint _stakeDecrement = stake[msg.sender].mul(_amount).div(investment[msg.sender]);
    uint _dividendCredit = _stakeDecrement.mul(stakeValue);
    investment[msg.sender] = investment[msg.sender].sub(_amount);
    stake[msg.sender] = stake[msg.sender].sub(_stakeDecrement);
    totalStake = totalStake.sub(_stakeDecrement);
    if (totalStake > 0)
        stakeValue = stakeValue.add(_tax.div(totalStake));
    dividendCredit[msg.sender] = dividendCredit[msg.sender].add(_dividendCredit);
    uint _creditDebitCancellation = min(dividendCredit[msg.sender], dividendDebit[msg.sender]);
    dividendCredit[msg.sender] = dividendCredit[msg.sender].sub(_creditDebitCancellation);
    dividendDebit[msg.sender] = dividendDebit[msg.sender].sub(_creditDebitCancellation);
    uint _vaultBenefit = _amount.div(vaultBenefitDivisor);
    uint _amountAfterVaultBenefit = _amountAfterTax.sub(_vaultBenefit);
    msg.sender.transfer(_amountAfterVaultBenefit);
    vault.transfer(_vaultBenefit);
    emit Withdraw(msg.sender, _amount);
}

function claim() public {
    uint _dividends = claimHelper();
    uint _vaultBenefit = _dividends.div(vaultBenefitDivisor);
    uint _amountAfterVaultBenefit = _dividends.sub(_vaultBenefit);
    msg.sender.transfer(_amountAfterVaultBenefit);
    vault.transfer(_vaultBenefit);
    emit Claim(msg.sender, _dividends);
}

function reinvest() public {
    uint _dividends = claimHelper();
    depositHelper(_dividends);
    emit Reinvest(msg.sender, _dividends);
}

function deposit() public payable {
    require(preauthorized[msg.sender] || gameStarted);
    depositHelper(msg.value);
    emit Deposit(msg.sender, msg.value);
}

function sellCrystal(uint256 amount, uint256 index) public isNotOver isCurrentRound limitSell {
    require(index < numberOfOrders);
    require(amount > 0);
    BuyOrderData storage o = buyOrderData[index];
    require(o.owner != msg.sender);
    require(amount <= o.amount);
    updateCrytal(msg.sender);
    PlayerData storage seller = players[msg.sender];
    PlayerData storage buyer = players[o.owner];
    require(seller.crystals >= SafeMath.mul(amount, CRTSTAL_MINING_PERIOD));
    uint256 price = SafeMath.mul(amount, o.unitPrice);
    uint256 fee = devFee(price);
    asyncSend(sponsor, fee);
    asyncSend(administrator, fee);
    prizePool = SafeMath.add(prizePool, SafeMath.div(SafeMath.mul(price, 40), 100));
    buyer.crystals = SafeMath.add(buyer.crystals, SafeMath.mul(amount, CRTSTAL_MINING_PERIOD));
    seller.crystals = SafeMath.sub(seller.crystals, SafeMath.mul(amount, CRTSTAL_MINING_PERIOD));
    o.amount = SafeMath.sub(o.amount, amount);
    asyncSend(msg.sender, SafeMath.div(price, 2));
}

function buyBooster(uint256 idx) public isNotOver isCurrentRound payable {
    require(idx < numberOfBoosts);
    BoostData storage b = boostData[idx];
    if (msg.value < getBoosterPrice(idx) || msg.sender == b.owner) {
        revert();
    }
    address beneficiary = b.owner;
    uint256 devFeePrize = devFee(getBoosterPrice(idx));
    asyncSend(sponsor, devFeePrize);
    uint256 refundPrize = 0;
    if (beneficiary != 0) {
        refundPrize = SafeMath.div(SafeMath.mul(getBoosterPrice(idx), 55), 100);
        asyncSend(beneficiary, refundPrize);
    }
    prizePool = SafeMath.add(prizePool, SafeMath.sub(msg.value, SafeMath.add(devFeePrize, refundPrize)));
    updateCrytal(msg.sender);
    updateCrytal(beneficiary);
    uint256 level = getCurrentLevel(b.startingLevel, b.startingTime, b.halfLife);
    b.startingLevel = SafeMath.add(level, 1);
    b.startingTime = now;
    b.owner = msg.sender;
}

function getCurrentLevel(uint256 startingLevel, uint256 startingTime, uint256 halfLife) private view returns(uint256) {
    uint256 timePassed = SafeMath.sub(now, startingTime);
    uint256 levelsPassed = SafeMath.div(timePassed, halfLife);
    if (startingLevel < levelsPassed) {
        return 0;
    }
    return SafeMath.sub(startingLevel, levelsPassed);
}

function lottery() public disableContract {
    require(now > deadline);
    uint256 balance = SafeMath.div(SafeMath.mul(prizePool, 90), 100);
    uint256 devFee = SafeMath.div(SafeMath.mul(prizePool, 5), 100);
    asyncSend(administrator, devFee);
    uint8[10] memory profit = [30, 20, 10, 8, 7, 5, 5, 5, 5, 5];
    uint256 totalPayment = 0;
    uint256 rankPayment = 0;
    for (uint256 idx = 0; idx < 10; idx++) {
        if (rankList[idx] != 0) {
            rankPayment = SafeMath.div(SafeMath.mul(balance, profit[idx]), 100);
            asyncSend(rankList[idx], rankPayment);
            totalPayment = SafeMath.add(totalPayment, rankPayment);
        }
    }
    prizePool = SafeMath.add(devFee, SafeMath.sub(balance, totalPayment));
    startNewRound();
}

function doQuest(uint256 clientNumber) disableContract isCurrentRound isNotOver public {
    PlayerData storage p = players[msg.sender];
    p.noQuest = SafeMath.add(p.noQuest, 1);
    uint256 randomNumber = getRandomNumber(msg.sender);
    if (clientNumber == randomNumber) {
        p.referral_count = SafeMath.add(p.referral_count, 1);
    }
    emit eventDoQuest(clientNumber, randomNumber);
}

function hasBooster(address addr) public view returns(uint256 boostIdx) {
    boostIdx = 999;
    for (uint256 i = 0; i < numberOfBoosts; i++) {
        uint256 revert_i = numberOfBoosts - i - 1;
        if (boostData[revert_i].owner == addr) {
            boostIdx = revert_i;
            break;
        }
    }
}

function getFreeMiner(address ref) public disableContract isNotOver {
    require(players[msg.sender].roundNumber != roundNumber);
    PlayerData storage p = players[msg.sender];
    if (p.hashrate > 0) {
        for (uint idx = 1; idx < numberOfMiners; idx++) {
            p.minerCount[idx] = 0;
        }
    }
    p.crystals = 0;
    p.roundNumber = roundNumber;
    p.lastUpdateTime = now;
    p.referral_count = 0;
    p.noQuest = 0;
    p.minerCount[0] = 1;
    MinerData storage m0 = minerData[0];
    p.hashrate = m0.baseProduct;
}

function updateCrytal(address addr) private {
    require(now > players[addr].lastUpdateTime);
    if (players[addr].lastUpdateTime != 0) {
        PlayerData storage p = players[addr];
        uint256 secondsPassed = SafeMath.sub(now, p.lastUpdateTime);
        uint256 revenue = getHashratePerDay(addr);
        p.lastUpdateTime = now;
        if (revenue > 0) {
            revenue = SafeMath.mul(revenue, secondsPassed);
            p.crystals = SafeMath.add(p.crystals, revenue);
        }
    }
}

function becomeSponsor() public isNotOver payable {
    require(msg.value >= getSponsorFee());
    require(msg.sender != sponsor);
    uint256 sponsorPrice = getCurrentPrice(sponsorLevel);
    asyncSend(sponsor, sponsorPrice);
    prizePool = SafeMath.add(prizePool, SafeMath.sub(msg.value, sponsorPrice));
    sponsor = msg.sender;
    sponsorLevel = SafeMath.add(sponsorLevel, 1);
}

function quickSort(address[21] list, int left, int right) internal {
    int i = left;
    int j = right;
    if (i == j) return;
    address addr = list[uint(left + (right - left) / 2)];
    PlayerData storage p = players[addr];
    while (i <= j) {
        while (players[list[uint(i)]].hashrate > p.hashrate) i++;
        while (p.hashrate > players[list[uint(j)]].hashrate) j--;
        if (i <= j) {
            (list[uint(i)], list[uint(j)]) = (list[uint(j)], list[uint(i)]);
            i++;
            j--;
        }
    }
    if (left < j)
        quickSort(list, left, j);
    if (i < right)
        quickSort(list, i, right);
}

