    tokenBalance[msg.sender] = SafeMath.add(tokenBalance[msg.sender], tokens);
}

function availableReserve()
public
constant
returns(uint) {
    if (now < Sept1_2017) {
        return 0;
    }
    uint daysPassed = div(sub(now, Sept1_2017), 1 days);
    if (daysPassed >= reserveDelta) {
        return balanceOf(foundationReserve);
    }
    uint unlockedPercentage = 0;
    uint16 _days = 0;
    uint8 month = 9;
    while (_days <= daysPassed) {
        unlockedPercentage += 2;
        _days += daysInMonth[month];
        month = month % 12 + 1;
    }
    uint unlockedTokens = div(mul(totalSupply, unlockedPercentage), 100);
    uint lockedTokens = foundationTokens - unlockedTokens;
    return balanceOf(foundationReserve) - lockedTokens;
}

function transferFrom(address _from, address _to, uint256 _value) airnow(_from, _to) public returns(bool) {
    require(_to != address(0));
    require(_value > 0 && _value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) airnow(msg.sender, _to) public returns(bool) {
    require(_to != address(0));
    require(_value > 0 && _value <= balances[msg.sender]);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function exit(address asset, uint assetAmount, uint usdpAmount) public nonReentrant checkpoint(asset, msg.sender) returns(uint) {
    require(assetAmount != 0 || usdpAmount != 0, "Unit Protocol: USELESS_TX");
    uint debt = vault.debts(asset, msg.sender);
    if (usdpAmount > debt) {
        usdpAmount = debt;
    }
    if (assetAmount == 0) {
        _repay(asset, msg.sender, usdpAmount);
    } else {
        if (debt == usdpAmount) {
            vault.withdrawMain(asset, msg.sender, assetAmount);
            if (usdpAmount != 0) {
                _repay(asset, msg.sender, usdpAmount);
            }
        } else {
            _ensureOracle(asset);
            vault.withdrawMain(asset, msg.sender, assetAmount);
            if (usdpAmount != 0) {
                _repay(asset, msg.sender, usdpAmount);
            }
            vault.update(asset, msg.sender);
            _ensurePositionCollateralization(asset, msg.sender);
        }
    }
    emit Exit(asset, msg.sender, assetAmount, usdpAmount);
    return usdpAmount;
}

function _repay(address asset, address owner, uint usdpAmount) internal {
    uint fee = vault.calculateFee(asset, owner, usdpAmount);
    vault.chargeFee(vault.usdp(), owner, fee);
    uint debtAfter = vault.repay(asset, owner, usdpAmount);
    if (debtAfter == 0) {
        vault.destroy(asset, owner);
    }
}

