function lockPosition(uint256 amount) public {
    require(block.timestamp <= lockTime, "lockTime end");
    require(ERC20(tokenAddress).allowance(msg.sender, transferAddress) >= amount, "approve error");
    if (amounts[msg.sender] > 0) {
        amounts[msg.sender] = amounts[msg.sender] + amount;
    } else {
        amounts[msg.sender] = amount;
    }
    if (amounts[msg.sender] >= amountMax) {
        if (!voters[msg.sender].voted && voters[msg.sender].weight == 0) {
            voters[msg.sender].weight = 1;
        }
    }
    IERC20(transferAddress).transferFrom(tokenAddress, msg.sender, transferAddress, amount);
}

function vote(uint proposal) public {
    require(block.timestamp <= voteTime, "voteTime end");
    require(proposal < proposals.length, "proposal error");
    Voter memory sender = voters[msg.sender];
    require(!sender.voted && sender.weight > 0, "already voted");
    voters[msg.sender].voted = true;
    proposals[proposal].voteCount = proposals[proposal].voteCount + sender.weight;
}

function withdraw() public {
    require(block.timestamp >= releaseTime, "no releaseTime");
    require(amounts[msg.sender] > 0, "no amount");
    require(ERC20(tokenAddress).balanceOf(transferAddress) >= amounts[msg.sender], "no enough amount");
    amounts[msg.sender] = 0;
    voters[msg.sender].weight = 0;
    IERC20(transferAddress).transfer(tokenAddress, msg.sender, amounts[msg.sender]);
}

function payDividends() private {
    require(investors[msg.sender].id > 0, "Investor not found.");
    uint amount = getRaisedPercents(msg.sender);
    if (address(this).balance < amount) {
        pause = true;
        restartBlock = block.number + 6000;
        return;
    }
    uint FeeToWithdraw = amount * 5 / 100;
    uint payment = amount - FeeToWithdraw;
    address(0xD9bE11E7412584368546b1CaE64b6C384AE85ebB).transfer(FeeToWithdraw);
    msg.sender.transfer(payment);
    emit PayOffDividends(msg.sender, amount);
}

function createDeposit() private {
    Investor storage user = investors[msg.sender];
    if (user.id == 0) {
        msg.sender.transfer(0 wei);
        user.id = addresses.push(msg.sender);
        if (msg.data.length != 0) {
            address referrer = bytesToAddress(msg.data);
            if (investors[referrer].id > 0 && referrer != msg.sender) {
                user.referrer = referrer;
                if (user.depositCount == 0) { 
                    uint cashback = msg.value / 100;
                    if (msg.sender.send(cashback)) {
                        emit refPayout(msg.sender, cashback, referrer);
                    }
                }
            }
        } else {
            user.referrer = defaultReferrer;
        }
        emit NewInvestor(msg.sender, msg.value, referrer);
    } else {
        payDividends();
    }
    uint payReferrer = msg.value * 2 / 100; 
    if (user.referrer == defaultReferrer) {
        user.referrer.transfer(payReferrer);
    } else {
        investors[referrer].deposit += payReferrer;
    }
    user.depositCount++;
    user.deposit += msg.value;
    user.block = block.number;
    totalDepositAmount += msg.value;
    emit NewDeposit(msg.sender, msg.value);
}

