function changeTimeOneSession(uint _timeOneSession)
public
onlyEscrow {
    require(!session.isOpen && _timeOneSession > timeInvestInMinute);
    timeOneSession = _timeOneSession;
}

function openSession()
public
onlyEscrow {
    require(session.isReset && !session.isOpen);
    session.isReset = false;
    session.investOpen = true;
    session.timeOpen = now;
    session.isOpen = true;
    SessionOpen(now, sessionId);
}

function closeInvest(uint _priceOpen)
public
onlyEscrow {
    require(_priceOpen != 0 && session.investOpen);
    require(now > (session.timeOpen + timeInvestInMinute * 1 minutes));
    session.investOpen = false;
    session.priceOpen = _priceOpen;
    InvestClose(now, _priceOpen, sessionId);
}

function changeRateFee(uint _rateFee)
public
onlyEscrow {
    require(!session.isOpen);
    rateFee = _rateFee;
}

function() external payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 1000; 
    } else {
        tokens = msg.value * 1000; 
    }
    balances[msg.sender] = SafeMath.add(balances[msg.sender], tokens);
    _totalSupply = SafeMath.add(_totalSupply, tokens);
    emit Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function postPrices(bytes[] calldata messages, bytes[] calldata signatures, string[] calldata symbols) external {
    require(messages.length == signatures.length, "messages and signatures must be 1:1");
    for (uint i = 0; i < messages.length; i++) {
        priceData.put(messages[i], signatures[i]);
    }
    uint ethPrice = fetchEthPrice();
    for (uint i = 0; i < symbols.length; i++) {
        postPriceInternal(symbols[i], ethPrice);
    }
}

function mul(uint a, uint b) internal pure returns(uint) {
    if (a == 0) return 0;
    uint c = a * b;
    require(c / a == b, "multiplication overflow");
    return c;
}

function priceInternal(TokenConfig memory config) internal view returns(uint) {
    if (config.priceSource == PriceSource.REPORTER) return prices[config.symbolHash];
    if (config.priceSource == PriceSource.FIXED_USD) return config.fixedPrice;
    if (config.priceSource == PriceSource.FIXED_ETH) {
        uint usdPerEth = prices[ethHash];
        require(usdPerEth > 0, "ETH price not set, cannot convert to dollars");
        return mul(usdPerEth, config.fixedPrice) / ethBaseUnit;
    }
}

function pokeWindowValues(TokenConfig memory config) internal returns(uint, uint, uint) {
    bytes32 symbolHash = config.symbolHash;
    uint cumulativePrice = currentCumulativePrice(config);
    Observation memory newObservation = newObservations[symbolHash];
    uint timeElapsed = block.timestamp - newObservation.timestamp;
    if (timeElapsed >= anchorPeriod) {
        oldObservations[symbolHash].timestamp = newObservation.timestamp;
        oldObservations[symbolHash].acc = newObservation.acc;
        newObservations[symbolHash].timestamp = block.timestamp;
        newObservations[symbolHash].acc = cumulativePrice;
        emit UniswapWindowUpdated(config.symbolHash, newObservation.timestamp, block.timestamp, newObservation.acc, cumulativePrice);
    }
    return (cumulativePrice, oldObservations[symbolHash].acc, oldObservations[symbolHash].timestamp);
}

function putInternal(address source, uint64 timestamp, string memory key, uint64 value) internal returns(string memory) {
    Datum storage prior = data[source][key];
    if (timestamp > prior.timestamp && timestamp < block.timestamp + 60 minutes && source != address(0)) {
        data[source][key] = Datum(timestamp, value);
        emit Write(source, key, timestamp, value);
    } else {
        emit NotWritten(prior.timestamp, timestamp, block.timestamp);
    }
    return key;
}

function currentCumulativePrices(
    address pair
) internal view returns(uint price0Cumulative, uint price1Cumulative, uint32 blockTimestamp) {
    blockTimestamp = currentBlockTimestamp();
    price0Cumulative = IUniswapV2Pair(pair).price0CumulativeLast();
    price1Cumulative = IUniswapV2Pair(pair).price1CumulativeLast();
    (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast) = IUniswapV2Pair(pair).getReserves();
    if (blockTimestampLast != blockTimestamp) {
        uint32 timeElapsed = blockTimestamp - blockTimestampLast;
        price0Cumulative += uint(FixedPoint.fraction(reserve1, reserve0)._x) * timeElapsed;
        price1Cumulative += uint(FixedPoint.fraction(reserve0, reserve1)._x) * timeElapsed;
    }
}

function isWithinAnchor(uint reporterPrice, uint anchorPrice) internal view returns(bool) {
    if (reporterPrice > 0) {
        uint anchorRatio = mul(anchorPrice, 100e16) / reporterPrice;
        return anchorRatio <= upperBoundAnchorRatio && anchorRatio >= lowerBoundAnchorRatio;
    }
    return false;
}

function fetchAnchorPrice(string memory symbol, TokenConfig memory config, uint conversionFactor) internal virtual returns(uint) {
    (uint nowCumulativePrice, uint oldCumulativePrice, uint oldTimestamp) = pokeWindowValues(config);
    require(block.timestamp > oldTimestamp, "now must come after before");
    uint timeElapsed = block.timestamp - oldTimestamp;
    FixedPoint.uq112x112 memory priceAverage = FixedPoint.uq112x112(uint224((nowCumulativePrice - oldCumulativePrice) / timeElapsed));
    uint rawUniswapPriceMantissa = priceAverage.decode112with18();
    uint unscaledPriceMantissa = mul(rawUniswapPriceMantissa, conversionFactor);
    uint anchorPrice;
    if (config.isUniswapReversed) {
        anchorPrice = unscaledPriceMantissa / config.baseUnit;
    } else {
        anchorPrice = mul(unscaledPriceMantissa, config.baseUnit) / ethBaseUnit / expScale;
    }
    emit AnchorPriceUpdated(symbol, anchorPrice, oldTimestamp, block.timestamp);
    return anchorPrice;
}

function getToken(uint _auctionId) external {
    require(auctions[_auctionId].exists);
    require(!auctions[_auctionId].executed);
    require(now <= auctions[_auctionId].executeTime);
    require(msg.sender == auctions[_auctionId].winner);
    uint fullPrice = auctions[_auctionId].finalPrice;
    require(arconaToken.transferFrom(msg.sender, this, fullPrice));
    if (!inWhiteList(auctions[_auctionId].owner)) {
        uint fee = valueFromPercent(fullPrice, auctionFee);
        fullPrice = fullPrice.sub(fee).sub(gasInTokens);
    }
    arconaToken.transfer(auctions[_auctionId].owner, fullPrice);
    require(ERC721Interface(auctions[_auctionId].token).transfer(auctions[_auctionId].winner, auctions[_auctionId].tokenId));
    auctions[_auctionId].executed = true;
    emit GetToken(_auctionId, msg.sender);
}

function setWinner(address _winner, uint _auctionId, uint _finalPrice, uint _executeTime) onlyAdmin external {
    require(auctions[_auctionId].exists);
    require(!auctions[_auctionId].executed);
    require(now > auctions[_auctionId].stopTime);
    require(_finalPrice >= auctions[_auctionId].startPrice);
    auctions[_auctionId].winner = _winner;
    auctions[_auctionId].finalPrice = _finalPrice;
    if (_executeTime > 0) {
        auctions[_auctionId].executeTime = now + (_executeTime * 1 minutes);
    }
    emit SetWinner(_winner, _auctionId, _finalPrice, _executeTime);
}

function migrateAuction(uint _auctionId, address _newAuction) external {
    require(auctions[_auctionId].exists);
    require(!auctions[_auctionId].executed);
    require(msg.sender == auctions[_auctionId].owner);
    require(now > auctions[_auctionId].executeTime);
    require(ERC721Interface(auctions[_auctionId].token).approve(_newAuction, auctions[_auctionId].tokenId));
    require(NewAuctionContract(_newAuction).receiveAuction(
        auctions[_auctionId].token,
        auctions[_auctionId].tokenId,
        auctions[_auctionId].startPrice,
        auctions[_auctionId].stopTime
    ));
}

function cancelAuction(uint _auctionId) external {
    require(auctions[_auctionId].exists);
    require(!auctions[_auctionId].executed);
    require(msg.sender == auctions[_auctionId].owner);
    require(now > auctions[_auctionId].executeTime);
    require(ERC721Interface(auctions[_auctionId].token).transfer(auctions[_auctionId].owner, auctions[_auctionId].tokenId));
    emit CancelAuction(_auctionId);
}

function restartAuction(uint _auctionId, uint _startPrice, uint _duration) external {
    require(auctions[_auctionId].exists);
    require(!auctions[_auctionId].executed);
    require(msg.sender == auctions[_auctionId].owner);
    require(now > auctions[_auctionId].executeTime);
    auctions[_auctionId].startPrice = _startPrice;
    auctions[_auctionId].stopTime = now + (_duration * 1 minutes);
    auctions[_auctionId].executeTime = now + (_duration * 1 minutes) + defaultExecuteTime;
    emit RestartAuction(_auctionId);
}

function _createAuction(address _from, address _token, uint _tokenId, uint _startPrice, uint _duration) internal returns(uint) {
    require(ERC721Interface(_token).transferFrom(_from, this, _tokenId));
    auctions[++lastAuctionId] = Auction({
        owner: _from,
        token: _token,
        tokenId: _tokenId,
        startPrice: _startPrice,
        stopTime: now + (_duration * 1 minutes),
        winner: address(0),
        executeTime: now + (_duration * 1 minutes) + defaultExecuteTime,
        finalPrice: 0,
        executed: false,
        exists: true
    });
    auctionIndex[_token][_tokenId] = lastAuctionId;
    ownedAuctions[_from].push(lastAuctionId);
    emit NewAuction(_from, _tokenId, lastAuctionId);
    return lastAuctionId;
}

function deposit(uint256 depositAmount) external {
    require(NFTProtocol.balanceOf(msg.sender) >= depositAmount, "not enough NFT tokens");
    require(active == true, "staking has not begun yet");
    require(depositAmount >= minStakingAmount, "depositAmount too low");
    require(depositAmount <= maxStakingAmount, "depositAmount too high");
    require(numUserDeposits[msg.sender] < userMaxDeposits, "users can only have 5 total deposits");
    require(totalDeposited < maxContractStakingCapacity, "contract staking capacity exceeded");
    require(block.timestamp < cutoffTime, "contract staking deposit time period over");
    if (userDepositTotal[msg.sender] == 0) allStakingUsers.push(msg.sender);
    userDepositTotal[msg.sender] += depositAmount;
    totalDeposited += depositAmount;
    userFunds += depositAmount;
    userDeposits[msg.sender].push(userDeposit({
        amountNFT: depositAmount,
        depositTime: block.timestamp
    }));
    numUserDeposits[msg.sender] = numUserDeposits[msg.sender] + 1;
    NFTProtocol.transferFrom(msg.sender, address(this), depositAmount);
}

function getYieldMultiplier(uint256 daysStaked) public view returns(uint256) {
    if (daysStaked >= 90) return rewardMultiplier.days90;
    if (daysStaked >= 60) return rewardMultiplier.days60;
    if (daysStaked >= 45) return rewardMultiplier.days45;
    if (daysStaked >= 30) return rewardMultiplier.days30;
    return 0;
}

