function buyPriceAt(uint256 at) constant returns(uint256) {
    if (at < STARTDATE) {
        return 0;
    } else if (at < (STARTDATE + 9 days)) {
        return 2700;
    } else if (at < (STARTDATE + 18 days)) {
        return 2400;
    } else if (at < (STARTDATE + 27 days)) {
        return 2050;
    } else if (at <= ENDDATE) {
        return 1500;
    } else {
        return 0;
    }
}

