function bonusInfo() constant returns(uint, uint) {
    if (now <= bonus1Ends) {
        return (100, (bonus1Ends - now));
    } else if (now <= bonus2Ends) {
        return (50, (bonus2Ends - now));
    } else if (now <= bonus3Ends) {
        return (25, (bonus3Ends - now));
    } else {
        return (0, 0);
    }
}

