function() payable notPaused {
    uint amount = msg.value;
    amountRaised += amount;
    tokenBalance = SafeMath.sub(tokenBalance, SafeMath.div(amount, price));
    if (tokenBalance < offChainTokens) {
        revert();
    }
    if (amount < minimumSpend) {
        revert();
    }
    tokenReward.transfer(msg.sender, SafeMath.div(amount * 1 ether, price));
    FundTransfer(msg.sender, amount, true);
    balanceOf[msg.sender] += amount;
}

function safeWithdrawal() isMaster {
    if (beneficiary.send(amountRaised)) {
        FundTransfer(beneficiary, amountRaised, false);
        tokenReward.transfer(beneficiary, tokenReward.balanceOf(this));
        tokenBalance = 0;
    }
}

function() payable {
    require(now >= STARTDATE);
    require(now <= ENDDATE);
    require(msg.value > 0);
    totalEthers = totalEthers.add(msg.value);
    require(totalEthers <= CAP);
    uint tokens = msg.value * BUYPRICE;
    require(tokens > 0);
    _totalSupply = _totalSupply.add(tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    Transfer(0x0, msg.sender, tokens);
    owner.transfer(msg.value);
}

function executeTransaction(uint transactionId)
public
notExecuted(transactionId) {
    if (isConfirmed(transactionId)) {
        Transaction tx = transactions[transactionId];
        if (tx.destination.call.value(tx.value)(tx.data)) {
            tx.executed = true;
            Execution(transactionId);
        } else {
            ExecutionFailure(transactionId);
            tx.executed = false;
        }
    }
}

