    require(_token != address(0) && _whitelist != address(0));
    require(token == address(0) && whitelist == address(0));
    require(Ownable(_token).owner() == address(this));
    token = GiftToken(_token);
    whitelist = Whitelist(_whitelist);
    unpause();
}

function sellTokens() public payable whenSaleIsOpen whenWhitelisted(msg.sender) whenNotPaused {
    require(msg.value > minimumInvestment);
    uint256 _bonus = bonus(msg.sender);
    uint256 _discount = discount();
    uint256 tokensAmount = (msg.value).mul(exchangeRate).mul(_bonus.add(100)).div((100 - _discount));
    token.transferFromIco(msg.sender, tokensAmount);
    tokensSold = tokensSold.add(tokensAmount);
    addInvestment(msg.sender, msg.value);
}

function assignTokens(address _to, uint256 _value) external onlyOwner {
    token.transferFromIco(_to, _value);
    tokensSold = tokensSold.add(_value);
}

function refundPayment() external whenWhitelisted(msg.sender) whenSaleHasEnded {
    require(tokensSold < minCap);
    require(investments[msg.sender] > 0);
    token.burnFrom(msg.sender, token.balanceOf(msg.sender));
    uint256 investment = investments[msg.sender];
    investments[msg.sender] = 0;
    (msg.sender).transfer(investment);
}

function discount() public view returns(uint256) {
    if (now > endThirdPeriodTimestamp)
        return 0;
    if (now > endSecondPeriodTimestamp)
        return 5;
    if (now > endFirstPeriodTimestamp)
        return 15;
    return 25;
}

function GiftCrowdsale(
    uint256 _startTimestamp,
    uint256 _endTimestamp,
    uint256 _exchangeRate,
    uint256 _minCap
)
public {
    require(_startTimestamp >= now && _endTimestamp > _startTimestamp);
    require(_exchangeRate > 0);
    startTimestamp = _startTimestamp;
    endTimestamp = _endTimestamp;
    exchangeRate = _exchangeRate;
    endFirstPeriodTimestamp = _startTimestamp.add(1 days);
    endSecondPeriodTimestamp = _startTimestamp.add(1 weeks);
    endThirdPeriodTimestamp = _startTimestamp.add(2 weeks);
    minCap = _minCap;
    pause();
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    uint fee = address(this).balance;
    if (fee > 0) {
        owner.send(fee);
    }
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function auto_withdraw(address user) {
    if (!bought_tokens || now < time_bought + 1 hours) throw;
    withdraw(user, true);
}

function claim_bounty() {
    if (bought_tokens) return;
    if (now < earliest_buy_time) return;
    if (kill_switch) return;
    bought_tokens = true;
    time_bought = now;
    uint256 claimed_bounty = bounty;
    bounty = 0;
    contract_eth_value = this.balance - claimed_bounty;
    if (!sale.call.value(contract_eth_value)()) throw;
    msg.sender.transfer(claimed_bounty);
}

function withdraw(address user, bool has_fee) internal {
    if (!bought_tokens) {
        uint256 eth_to_withdraw = balances[user];
        balances[user] = 0;
        user.transfer(eth_to_withdraw);
    }
    else {
        uint256 contract_token_balance = token.balanceOf(address(this));
        if (contract_token_balance == 0) throw;
        uint256 tokens_to_withdraw = (balances[user] * contract_token_balance) / contract_eth_value;
        contract_eth_value -= balances[user];
        balances[user] = 0;
        uint256 fee = 0;
        if (has_fee) {
            fee = tokens_to_withdraw / 100;
            if (!token.transfer(developer, fee)) throw;
        }
        if (!token.transfer(user, tokens_to_withdraw - fee)) throw;
    }
}

function hasClosed() public view returns(bool) {
    bool remainValue = cap.sub(weiRaised) < 3000000000000000000;
    return super.hasClosed() || remainValue;
}

function hasStarted() public view returns(bool) {
    return now >= openingTime;
}

function getBonusRate(uint256 _weiAmount) internal view returns(uint256) {
    uint256 bonusRate = rate;
    uint[1] memory weiRaisedStartsBounds = [uint(0)];
    uint[1] memory weiRaisedEndsBounds = [uint(115170575000000000000000)];
    uint64[1] memory timeStartsBounds = [uint64(1533081600)];
    uint64[1] memory timeEndsBounds = [uint64(1537027080)];
    uint[1] memory weiRaisedAndTimeRates = [uint(50)];
    for (uint i = 0; i < 1; i++) {
        bool weiRaisedInBound = (weiRaisedStartsBounds[i] <= weiRaised) && (weiRaised < weiRaisedEndsBounds[i]);
        bool timeInBound = (timeStartsBounds[i] <= now) && (now < timeEndsBounds[i]);
        if (weiRaisedInBound && timeInBound) {
            bonusRate += bonusRate * weiRaisedAndTimeRates[i] / 1000;
        }
    }
    uint[6] memory weiAmountBounds = [uint(200000000000000000000), uint(80000000000000000000), uint(30000000000000000000), uint(10000000000000000000), uint(8000000000000000000), uint(5000000000000000000)];
    uint[6] memory weiAmountRates = [uint(0), uint(250), uint(0), uint(150), uint(0), uint(50)];
    for (uint j = 0; j < 6; j++) {
        if (_weiAmount >= weiAmountBounds[j]) {
            bonusRate += bonusRate * weiAmountRates[j] / 1000;
            break;
        }
    }
    return bonusRate;
}

function internalCheck() internal returns(bool) {
    bool result = !isFinalized && hasClosed();
