function executeSignatures(bytes message, bytes signatures) external {
    Message.hasEnoughValidSignatures(message, signatures, validatorContract(), false);
    address recipient;
    uint256 amount;
    bytes32 txHash;
    address contractAddress;
    (recipient, amount, txHash, contractAddress) = Message.parseMessage(message);
    if (withinExecutionLimit(amount)) {
        require(contractAddress == address(this));
        require(!relayedMessages(txHash));
        setRelayedMessages(txHash, true);
        require(onExecuteMessage(recipient, amount, txHash));
        emit RelayedMessage(recipient, amount, txHash);
    } else {
        onFailedMessage(recipient, amount, txHash);
    }
}

function getRate() constant returns(uint8) {
    if (now < START) return 166; 
    else if (now <= START + 6 days) return 162; 
    else if (now <= START + 13 days) return 156; 
    else if (now <= START + 20 days) return 150; 
    else if (now <= START + 27 days) return 144; 
    else if (now <= START + 34 days) return 138; 
    else if (now <= START + 41 days) return 132; 
    else if (now <= START + 48 days) return 126; 
    return 120; 
}

