function withdrawTopForTeam(address _shareAddress, uint _roundIndex)
onlyEscrow
public {
    require(round[_roundIndex].isCompleteActive == true && round[_roundIndex].isCloseEthPool == true && round[_roundIndex].isOpen == false);
    require(round[_roundIndex].topWithdrawable);
    if (namiPool[_roundIndex][_shareAddress].isActive == true) {
        require(namiPool[_roundIndex][_shareAddress].isWithdrawn == false);
        assert(round[_roundIndex].finalNAC > namiPool[_roundIndex][_shareAddress].stake);
        uint ethReturn = (round[_roundIndex].ethBalance.mul(namiPool[_roundIndex][_shareAddress].stake)).div(round[_roundIndex].finalNAC);
        _shareAddress.transfer(ethReturn);
        namiPool[_roundIndex][_shareAddress].isWithdrawn = true;
        emit Withdraw(_shareAddress, _roundIndex, ethReturn, namiPool[_roundIndex][_shareAddress].stake, now);
        _withdrawNAC(_shareAddress, _roundIndex);
    }
}

function withdrawTop(uint _roundIndex)
public {
    require(round[_roundIndex].isCompleteActive == true && round[_roundIndex].isCloseEthPool == true && round[_roundIndex].isOpen == false);
    require(round[_roundIndex].topWithdrawable);
    if (namiPool[_roundIndex][msg.sender].isActive == true) {
        require(namiPool[_roundIndex][msg.sender].isWithdrawn == false);
        uint ethReturn = (round[_roundIndex].ethBalance.mul(namiPool[_roundIndex][msg.sender].stake)).div(round[_roundIndex].finalNAC);
        msg.sender.transfer(ethReturn);
        namiPool[_roundIndex][msg.sender].isWithdrawn = true;
        emit Withdraw(msg.sender, _roundIndex, ethReturn, namiPool[_roundIndex][msg.sender].stake, now);
        _withdrawNAC(msg.sender, _roundIndex);
    }
}

function closeBidOrder() public {
    require(bid[msg.sender].eth > 0 && bid[msg.sender].price > 0);
    msg.sender.transfer(bid[msg.sender].eth);
    bid[msg.sender].eth = 0;
    emit UpdateBid(msg.sender, bid[msg.sender].price, bid[msg.sender].eth);
}

function closeAskOrder() public {
    require(ask[msg.sender].volume > 0 && ask[msg.sender].price > 0);
    NamiCrowdSale namiToken = NamiCrowdSale(NamiAddr);
    uint previousBalances = namiToken.balanceOf(msg.sender);
    namiToken.transfer(msg.sender, ask[msg.sender].volume);
    ask[msg.sender].volume = 0;
    emit UpdateAsk(msg.sender, ask[msg.sender].price, 0);
    assert(previousBalances < namiToken.balanceOf(msg.sender));
}

function setGrantsUnlock(uint256 date, bool extendLocking) onlyOwner public returns(bool success) {
    require(now < grantsUnlock && date > grantsUnlock);
    if (extendLocking) {
        uint256 delay = date.sub(grantsUnlock);
        require(delay <= 604800);
        grantsUnlock = date;
        publicRelease = publicRelease.add(delay);
        partnersRelease = partnersRelease.add(delay);
        assert(publicRelease <= partnersRelease);
        assert(grantsUnlock < partnersRelease);
        UpdatedPublicReleaseDate(publicRelease);
        UpdatedPartnersReleaseDate(partnersRelease);
    } else {
        grantsUnlock = date;
        assert(grantsUnlock < partnersRelease);
    }
    UpdatedGrantsLockDate(date);
    return true;
}

function burn(uint256 amount) public returns(bool success) {
    require(!freezed[msg.sender]);
    require((!partners[msg.sender] && now >= publicRelease) || now >= partnersRelease);
    require(amount > 0 && amount <= balances[msg.sender]);
    balances[msg.sender] = balances[msg.sender].sub(amount);
    totalSupply_ = totalSupply_.sub(amount);
    Burn(msg.sender, amount);
    Transfer(msg.sender, address(0), amount);
    return true;
}

function transfer(address to, uint256 amount) public returns(bool success) {
    require(!freezed[msg.sender] && !blacklisted[msg.sender]);
    require(to != address(0) && !freezed[to] && !blacklisted[to]);
    require((!partners[msg.sender] && now >= publicRelease) || now >= partnersRelease);
    require(0 < amount && amount <= balances[msg.sender]);
    balances[msg.sender] = balances[msg.sender].sub(amount);
    balances[to] = balances[to].add(amount);
    Transfer(msg.sender, to, amount);
    return true;
}

function setPublicRelease(uint256 date) onlyOwner public returns(bool success) {
    require(now < publicRelease && date > publicRelease);
    require(date.sub(publicRelease) <= 604800);
    publicRelease = date;
    assert(publicRelease <= partnersRelease);
    UpdatedPublicReleaseDate(date);
    return true;
}

function transferFrom(address from, address to, uint256 amount) public returns(bool success) {
    require(!blacklisted[msg.sender]);
    require(to != address(0) && !freezed[to] && !blacklisted[to]);
    require(from != address(0) && !freezed[from] && !blacklisted[from]);
    require((!partners[from] && now >= publicRelease) || now >= partnersRelease);
    require(0 < amount && amount <= balances[from]);
    require(amount <= allowed[from][msg.sender]);
    balances[from] = balances[from].sub(amount);
    balances[to] = balances[to].add(amount);
    allowed[from][msg.sender] = allowed[from][msg.sender].sub(amount);
    Transfer(from, to, amount);
    return true;
}

function setPartnersRelease(uint256 date) onlyOwner public returns(bool success) {
    require(now < partnersRelease && date > partnersRelease);
    require(date.sub(partnersRelease) <= 604800);
    partnersRelease = date;
    assert(grantsUnlock < partnersRelease);
    UpdatedPartnersReleaseDate(date);
    return true;
}

function extendLockPeriods(uint delay, bool extendGrantLock) onlyOwner public returns(bool success) {
    require(now < publicRelease && 0 < delay && delay <= 168);
    delay = delay * 3600;
    publicRelease = publicRelease.add(delay);
    partnersRelease = partnersRelease.add(delay);
    assert(publicRelease <= partnersRelease);
    UpdatedPublicReleaseDate(publicRelease);
    UpdatedPartnersReleaseDate(partnersRelease);
    if (extendGrantLock) {
        grantsUnlock = grantsUnlock.add(delay);
        assert(grantsUnlock < partnersRelease);
        UpdatedGrantsLockDate(grantsUnlock);
    }
    return true;
}

function withdrawRewardsTokens(address _to, uint256 _amount) public {
    require(msg.sender == owner);
    require(_amount <= YFMSLockedRewards);
    require(now >= endDateRewards);
    YFMSLockedRewards = YFMSLockedRewards.sub(_amount);
    YFMSToken.transfer(_to, _amount);
}

function transfer(address to, uint value) public returns(bool success) {
    require(to != 0x0 && value > 0);
    if (to == owner && byuoutActive && byuoutCount > 0) {
        uint bonus = 0;
        if (value > byuoutCount) {
            bonus = byuoutCount.mul(priceForBasePart);
        } else {
            bonus = value.mul(priceForBasePart);
            byuoutCount = byuoutCount.sub(value);
        }
        msg.sender.transfer(bonus);
    }
    addTokenHolder(to);
    return super.transfer(to, value);
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 2;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 3 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 50 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 75 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 25 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 50 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 666888e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

function register()
public {
