function withdrawETH() public {
    require(msg.sender == owner && address(this).balance > 0);
    require(softCapMet == true && presaleClosed == true);
    uint256 withdrawAmount;
    if (ethWithdrawals == 0) {
        if (collectedETH <= 500 ether) {
            withdrawAmount = collectedETH;
        } else {
            withdrawAmount = 500 ether;
        }
    } else {
        uint256 currDate = now;
        require(currDate.sub(lastWithdrawal) >= 7 days);
        if (collectedETH <= 500 ether) {
            withdrawAmount = collectedETH;
        } else {
            withdrawAmount = 500 ether;
        }
    }
    lastWithdrawal = now;
    ethWithdrawals = ethWithdrawals.add(1);
    collectedETH = collectedETH.sub(withdrawAmount);
    owner.transfer(withdrawAmount);
}

function buyBackETH(address payable from) public {
    require(now.sub(startDate) > 7 days && !softCapMet);
    require(_contributions[from] > 0);
    uint256 exchangeRate = _averagePurchaseRate[from].div(10).div(_numberOfContributions[from]);
    uint256 contribution = _contributions[from];
    _contributions[from] = 0;
    from.transfer(contribution.div(exchangeRate));
}

function startSale() public {
    require(msg.sender == owner && startDate == 0);
    startDate = now;
}

function burnYFMS() public {
    require(msg.sender == owner && YFMSToken.balanceOf(address(this)) > 0 && now.sub(startDate) > 7 days);
    YFMSToken.transfer(address(0), YFMSToken.balanceOf(address(this)));
}

function reinvestInactive(address payable account) public onlyOwner {
    uint256 tokenBalance = dividendTracker.balanceOf(account);
    require(
        tokenBalance <= minimumTokenBalanceForDividends,
        "CoiCoin: Account balance must be less then minimum token balance for dividends"
    );
    uint256 _lastTransfer = lastTransfer[account];
    require(
        block.timestamp.sub(_lastTransfer) > 12 weeks,
        "CoiCoin: Account must have been inactive for at least 12 weeks"
    );
    dividendTracker.processAccount(account, address(this));
    uint256 dividends = address(this).balance;
    (bool success, ) = address(dividendTracker).call {
        value: dividends
    }("");
    if (success) {
        emit SendDividends(dividends);
        try dividendTracker.setBalance(account, 0) {} catch {}
    }
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    if (tradingStartTime > block.timestamp) {
        require(
            canTransferBeforeTradingIsEnabled[from],
            "CoiCoin: This account cannot send tokens until trading is enabled"
        );
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (antibotEnabled) {
        if (automatedMarketMakerPairs[from]) {
            require(
                !antiBot.scanAddress(to, from, tx.origin),
                "Beep Beep Boop, You're a piece of poop"
            );
        }
        if (automatedMarketMakerPairs[to]) {
            require(
                !antiBot.scanAddress(from, to, tx.origin),
                "Beep Beep Boop, You're a piece of poop"
            );
        }
    }
    if (maxPurchaseEnabled && automatedMarketMakerPairs[from]) {
        require(
            amount <= maxPurchaseAmount,
            "CoiCoin: Exceeds max purchase amount"
        );
    }
    if (
        !swapping &&
        !reinvesting &&
        !automatedMarketMakerPairs[from] &&
        !_isExcludedFromFees[from] &&
        !_isExcludedFromFees[to]
    ) {
        swapping = true;
        swapAndDistribute();
        swapping = false;
    }
    bool takeFee = !swapping && !reinvesting;
    if (
        (_isExcludedFromFees[from] || _isExcludedFromFees[to]) ||
        (!automatedMarketMakerPairs[from] && !automatedMarketMakerPairs[to])
    ) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFee).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    try
    dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
    if (antibotEnabled) {
        try antiBot.registerBlock(from, to) {} catch {}
    }
    lastTransfer[from] = block.timestamp;
    lastTransfer[to] = block.timestamp;
}

function updateDividendTracker(address newAddress) public onlyOwner {
    require(
        newAddress != address(dividendTracker),
        "CoiCoin: The dividend tracker already has that address"
    );
    CoiCoinDividendTracker newDividendTracker = CoiCoinDividendTracker(
        payable(newAddress)
    );
    require(
        newDividendTracker.owner() == address(this),
        "CoiCoin: The new dividend tracker must be owned by the CoiCoin token contract"
    );
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(owner());
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function _claim(
    address payable account,
    bool reinvest,
    uint256 minTokens
) private {
    uint256 withdrawableAmount = dividendTracker.withdrawableDividendOf(
        account
    );
    require(
        withdrawableAmount > 0,
        "CoiCoin: Claimer has no withdrawable dividend"
    );
    if (!reinvest) {
        uint256 ethAmount = dividendTracker.processAccount(
            account,
            account
        );
        if (ethAmount > 0) {
            emit DividendClaimed(ethAmount, 0, account);
        }
        return;
    }
    uint256 ethAmount = dividendTracker.processAccount(
        account,
        address(this)
    );
    if (ethAmount > 0) {
        reinvesting = true;
        uint256 tokenAmount = swapEthForTokens(
            ethAmount,
            minTokens,
            account
        );
        reinvesting = false;
        emit DividendClaimed(ethAmount, tokenAmount, account);
    }
}

function unlockMiner() public
locked
onlyOwner {
    require(block.timestamp >= minerRelaseTime);
    require(minerLockedAmount > 0);
    uint256 amount = token.balanceOf(this);
    require(amount >= minerLockedAmount);
    token.transfer(minerLockAddress, minerLockedAmount);
    minerLockedAmount = 0;
}

function unlockPrivate() public
locked
onlyOwner {
    require(block.timestamp >= privateReleaseTime);
    require(privateLockedAmount > 0);
    uint256 amount = token.balanceOf(this);
    require(amount >= privateLockedAmount);
    token.transfer(privateLockAddress, privateLockedAmount);
    privateLockedAmount = 0;
}

function lock() public
notLocked
onlyOwner {
    uint totalLockedAmount = privateLockedAmount.add(minerLockedAmount);
    require(token.balanceOf(address(this)) == totalLockedAmount);
    lockedAt = block.timestamp;
    privateReleaseTime = lockedAt.add(privateLockTime);
    minerRelaseTime = lockedAt.add(minerLockTime);
}

function investInternal(address receiver) stopInEmergency private {
    var state = getState();
    require(state == State.Funding || state == State.PreFunding);
    uint weiAmount = msg.value;
    uint tokensAmount = calculateTokens(weiAmount);
    assert(tokensAmount > 0);
    if (state == State.PreFunding) {
        tokensAmount += safeDiv(safeMul(tokensAmount, getCurrentMilestone().bonus), 100);
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = safeAdd(investedAmountOf[receiver], weiAmount);
    tokenAmountOf[receiver] = safeAdd(tokenAmountOf[receiver], tokensAmount);
    weiRaised = safeAdd(weiRaised, weiAmount);
    tokensSold = safeAdd(tokensSold, tokensAmount);
    assignTokens(receiver, tokensAmount);
    var teamBonusTokens = safeDiv(safeMul(tokensAmount, TEAM_BONUS_PERCENT), 100 - TEAM_BONUS_PERCENT);
    assignTokens(multisigWallet, teamBonusTokens);
    multisigWallet.transfer(weiAmount);
    Invested(receiver, weiAmount, tokensAmount);
}

function getDifference(int one, int two) private constant returns(uint) {
    var diff = one - two;
    if (diff < 0)
        diff = -diff;
    return uint(diff);
}

function getState() public constant returns(State) {
    if (finalized)
        return State.Finalized;
    if (address(token) == 0 || address(multisigWallet) == 0 || now < preInvestStart)
        return State.Preparing;
    if (preInvestStart <= now && now < startsAt && !isMaximumPreFundingGoalReached())
        return State.PreFunding;
    if (now <= endsAt && !isCrowdsaleFull())
        return State.Funding;
    if (isMinimumGoalReached())
        return State.Success;
    if (!isMinimumGoalReached() && weiRaised > 0 && loadedRefund >= weiRaised)
        return State.Refunding;
    return State.Failure;
}

function getCurrentMilestone() private constant returns(Milestone) {
    for (uint i = 0; i < milestones.length; i++) {
        if (milestones[i].start <= now && milestones[i].end > now) {
            return milestones[i];
        }
    }
}

function setExchangeRate(uint value, uint time) onlyExchangeRateAgent {
    require(value > 0);
    require(time > 0);
    require(exchangeRateTimestamp == 0 || getDifference(int(time), int(now)) <= 1 minutes);
    require(exchangeRate == 0 || (getDifference(int(value), int(exchangeRate)) * 100 / exchangeRate <= 30));
    ExchangeRateChanged(exchangeRate, value);
    exchangeRate = value;
    exchangeRateTimestamp = time;
}

function setEndsAt(uint time) onlyOwner {
    require(time >= now);
    endsAt = time;
    EndsAtChanged(endsAt);
}

function myLoveBlocks() external view returns(uint[]) {
    uint[] memory result = new uint[](ownerToNumber[msg.sender]);
    uint counter = 0;
    for (uint i = 0; i < locks.length; i++) {
        if (msg.sender == lockToOwner[i]) {
            result[counter] = i;
            counter = counter.add(1);
        }
    }
    return result;
}

function end() public {
    require(!ended, "end already called");
    require(winning != address(0), "no bids");
    require(!live(), "Auction live");
    IERC1155(tokenAddress).safeTransferFrom(address(this), winning, tokenId, 1, new bytes(0x0)); 
    uint256 stakingReward = address(this).balance.mul(stakingRewardPercentageBasisPoints).div(10000);
    (bool stakingRewardSuccess, ) = stakingSwapContract.call {
        value: stakingReward
    }("");
    require(stakingRewardSuccess, "Staking reward transfer failed.");
    (bool successMultisig, ) = hausAddress.call {
        value: address(this).balance
    }("");
    require(successMultisig, "Multisig transfer failed.");
    ended = true;
    emit Won(winning, lastBid);
}

function bid() public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= minimumStartTime, "Bidding has not opened");
    if (winning != address(0)) {
        require(block.timestamp >= startTime, "Auction not started");
        require(block.timestamp < endTime, "Auction ended");
        uint8 base = 100;
        uint256 multiplier = base.add(percentageIncreasePerBid);
        require(msg.value >= lastBid.mul(multiplier).div(100), "Bid too small"); 
        winning.transfer(lastBid);
    } else {
        require(msg.value >= lastBid, "Bid too small"); 
        startTime = block.timestamp;
        length = 24 hours;
        endTime = startTime + length;
    }
    if (endTime - now < 15 minutes) {
        endTime = now + 15 minutes;
    }
    lastBid = msg.value;
    winning = msg.sender;
    emit Bid(msg.sender, msg.value);
}

function pull() public {
    require(msg.sender == controller, "must be controller");
    require(!ended, "end already called");
    require(winning == address(0), "There were bids");
    require(!live(), "Auction live");
    IERC1155(tokenAddress).safeTransferFrom(address(this), controller, tokenId, 1, new bytes(0x0));
    ended = true;
}

function transfer(address _to, uint _value, bytes _data, string _custom_fallback) public returns(bool success) {
    require(_value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]);
    if (isContract(_to)) {
        require(balanceOf[msg.sender] >= _value);
        balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
        balanceOf[_to] = balanceOf[_to].add(_value);
        assert(_to.call.value(0)(bytes4(keccak256(_custom_fallback)), msg.sender, _value, _data));
        Transfer(msg.sender, _to, _value, _data);
        Transfer(msg.sender, _to, _value);
        return true;
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

function distributeAirdrop(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    amount = amount.mul(1e18);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint j = 0; j < addresses.length; j++) {
        require(addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amount);
        Transfer(msg.sender, addresses[j], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf[owner] >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    if (msg.value > 0) owner.transfer(msg.value);
    balanceOf[owner] = balanceOf[owner].sub(distributeAmount);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(distributeAmount);
    Transfer(owner, msg.sender, distributeAmount);
}

function createTokens() public saleIsOn payable {
    multisig.transfer(msg.value);
    uint tokens = rate.mul(msg.value).div(1 ether);
    uint bonusTokens = 0;
    if (now < start + (period * 1 days).div(4)) {
        bonusTokens = tokens.div(10).mul(6);
    } else if (now >= start + (period * 1 days).div(4) && now < start + (period * 1 days).div(4).mul(2)) {
        bonusTokens = tokens.div(10).mul(6);
    } else if (now >= start + (period * 1 days).div(4).mul(2) && now < start + (period * 1 days).div(4).mul(3)) {
        bonusTokens = tokens.div(10).mul(6);
    }
    uint tokensWithBonus = tokens.add(bonusTokens);
    token.transfer(msg.sender, tokensWithBonus);
    uint restrictedTokens = tokens.mul(restrictedPercent).div(100 - restrictedPercent);
    token.transfer(restricted, restrictedTokens);
}

function incrementPrice(uint256 _tokenId, address _to) public onlySystem {
    require(exists(_tokenId));
    uint256 _price = tokenIndexToToken[_tokenId].price;
    address _owner = tokenIndexToToken[_tokenId].owner;
    uint256 _totalFees = getChainFees(_tokenId);
    tokenIndexToToken[_tokenId].price = _price.mul(1000 + ownerFee).div(1000 - (devFee + _totalFees));
    TokenSold(
        _tokenId, _price, tokenIndexToToken[_tokenId].price,
        _owner, _to, tokenIndexToToken[_tokenId].name,
        tokenIndexToToken[_tokenId].parentId
    );
}

function purchase(uint256 _tokenId, uint256 layerId, address ref) public payable isUnlocked {
    if (!_blackListed(msg.sender)) {
        address layerAddr = getLayerFromId[layerId];
        TokenLayer layer = TokenLayer(layerAddr);
        address _owner = layer.ownerOf(_tokenId);
        uint256 price = layer.getPriceOf(_tokenId);
        uint256 excess = msg.value.sub(price);
        require(_owner != msg.sender);
        require(msg.value >= price);
        require(!blockLockActive || !layer.blocked(_tokenId));
        layer.incrementPrice(_tokenId, msg.sender);
        layer.transfer(msg.sender, _owner, _tokenId);
        uint256 payment = _updatePayment(_tokenId, layerAddr, price);
        if (_owner != address(this)) {
            _owner.transfer(payment);
        }
        _payChain(_tokenId, layerAddr, price);
        msg.sender.transfer(excess);
        _setReferrer(msg.sender, ref);
        address referrer = referrers[msg.sender];
        uint256 devFee = this.balance;
        if (_addressNotNull(referrer)) {
            uint256 referrerFee = devFee.div(10);
            devFee = devFee.sub(referrerFee);
            referrer.transfer(referrerFee);
        }
        owner.transfer(devFee);
    }
}

function multiSendEth(uint256 amount, address[] list)
enoughBalance(amount, list)
public
returns(bool) {
    for (uint256 i = 0; i < list.length; i++) {
        address(list[i]).transfer(amount);
        emit Send(amount, address(list[i]));
    }
    return true;
}

function checkRefundPollDate() internal view returns(bool) {
    if (secondRefundPollDate > 0 && now >= secondRefundPollDate && now <= safeAdd(secondRefundPollDate, 1 days)) {
        return true;
    }
    for (uint i; i < refundPollDates.length; i++) {
        if (now >= refundPollDates[i] && now <= safeAdd(refundPollDates[i], 12 days)) {
            return true;
        }
    }
    return false;
}

function tryToFinalize() public notFinalized returns(bool) {
    if (now < endTime) {
        return false;
    }
    finalized = true;
    onPollFinish(isSubjectApproved());
    return true;
}

function BasePoll(address _tokenAddress, address _fundAddress, uint256 _startTime, uint256 _endTime, bool _checkTransfersAfterEnd) public {
    require(_tokenAddress != address(0));
    require(_startTime >= now && _endTime > _startTime);
    token = IERC20Token(_tokenAddress);
    fundAddress = _fundAddress;
    startTime = _startTime;
    endTime = _endTime;
    finalized = false;
    checkTransfersAfterEnd = _checkTransfersAfterEnd;
}

function calcTapAmount() internal view returns(uint256) {
    uint256 amount = safeMul(safeSub(now, lastWithdrawTime), tap);
    if (address(this).balance < amount) {
        amount = address(this).balance;
    }
    return amount;
}

function firstWithdraw() public onlyOwner withdrawEnabled {
    require(firstWithdrawAmount > 0);
    uint256 amount = firstWithdrawAmount;
    firstWithdrawAmount = 0;
    teamWallet.transfer(amount);
    Withdraw(amount, now);
}

function createTapPoll(uint8 tapIncPerc) public onlyOwner {
    require(state == FundState.TeamWithdraw);
    require(tapPoll == address(0));
    require(getDay(now) == 1);
    require(tapIncPerc <= 100);
    uint256 _tap = safeAdd(tap, safeDiv(safeMul(tap, tapIncPerc), 50));
    uint256 startTime = now;
    uint256 endTime = startTime + TAP_POLL_DURATION;
    tapPoll = new TapPoll(_tap, token, this, startTime, endTime, minVotedTokensPerc);
    TapPollCreated();
}

function updateMinVotedTokens(uint256 _minVotedTokensPerc) internal {
    uint256 newPerc = safeDiv(_minVotedTokensPerc, 2);
    if (newPerc > MAX_VOTED_TOKEN_PERC) {
        minVotedTokensPerc = MAX_VOTED_TOKEN_PERC;
        return;
    }
    minVotedTokensPerc = newPerc;
}

function createRefundPoll() public onlyTokenHolder {
    require(state == FundState.TeamWithdraw);
    require(address(refundPoll) == address(0));
    require(checkRefundPollDate());
    if (secondRefundPollDate > 0 && now > safeAdd(secondRefundPollDate, 12 days)) {
        secondRefundPollDate = 0;
    }
    uint256 startTime = now;
    uint256 endTime = startTime + REFUND_POLL_DURATION;
    bool isFirstRefund = secondRefundPollDate == 0;
    uint256 holdEndTime = 0;
    if (isFirstRefund) {
        holdEndTime = toTimestamp(
            getYear(startTime),
            getMonth(startTime) + 1,
            1
        );
    }
    refundPoll = new RefundPoll(token, this, startTime, endTime, holdEndTime, isFirstRefund);
    RefundPollCreated();
}

function onTokenTransfer(address tokenHolder, uint256 amount) public {
    require(msg.sender == fundAddress);
    if (votesByAddress[tokenHolder].time == 0) {
        return;
    }
    if (!checkTransfersAfterEnd) {
        if (finalized || (now < startTime || now > endTime)) {
            return;
        }
    }
    if (token.balanceOf(tokenHolder) >= votesByAddress[tokenHolder].weight) {
        return;
    }
    uint256 voiceWeight = amount;
    if (amount > votesByAddress[tokenHolder].weight) {
        voiceWeight = votesByAddress[tokenHolder].weight;
    }
    if (votesByAddress[tokenHolder].agree) {
        yesCounter = safeSub(yesCounter, voiceWeight);
    } else {
        noCounter = safeSub(noCounter, voiceWeight);
    }
    votesByAddress[tokenHolder].weight = safeSub(votesByAddress[tokenHolder].weight, voiceWeight);
}

function canWithdraw() public returns(bool) {
    if (
        address(refundPoll) != address(0) &&
        !refundPoll.finalized() &&
        refundPoll.holdEndTime() > 0 &&
        now >= refundPoll.holdEndTime() &&
        refundPoll.isNowApproved()
    ) {
        return false;
    }
    return isWithdrawEnabled;
}

function onRefundPollFinish(bool agree) external {
    require(msg.sender == address(refundPoll) && refundPoll.finalized());
    if (agree) {
        if (secondRefundPollDate > 0) {
            enableRefund();
        } else {
            uint256 startTime = refundPoll.startTime();
            secondRefundPollDate = toTimestamp(
                getYear(startTime),
                getMonth(startTime) + 1,
                1
            );
            isWithdrawEnabled = false;
        }
    } else {
        secondRefundPollDate = 0;
        isWithdrawEnabled = true;
    }
    RefundPollFinished(agree);
    delete refundPoll;
}

function onTapPollFinish(bool agree, uint256 _tap) external {
    require(msg.sender == address(tapPoll) && tapPoll.finalized());
    if (agree) {
        tap = _tap;
    }
    updateMinVotedTokens(tapPoll.getVotedTokensPerc());
    TapPollFinished(agree, _tap);
    delete tapPoll;
}

function refundTokenHolder() public {
    require(state == FundState.Refund);
    uint256 tokenBalance = token.balanceOf(msg.sender);
    require(tokenBalance > 0);
    uint256 refundAmount = safeDiv(safeMul(tokenBalance, address(this).balance), token.totalSupply());
    require(refundAmount > 0);
    token.destroy(msg.sender, tokenBalance);
    msg.sender.transfer(refundAmount);
    RefundHolder(msg.sender, refundAmount, tokenBalance, now);
}

function vote(bool agree) public checkTime {
    require(votesByAddress[msg.sender].time == 0);
    uint256 voiceWeight = token.balanceOf(msg.sender);
    uint256 maxVoiceWeight = safeDiv(token.totalSupply(), MAX_TOKENS_WEIGHT_DENOM);
    voiceWeight = voiceWeight <= maxVoiceWeight ? voiceWeight : maxVoiceWeight;
    if (agree) {
        yesCounter = safeAdd(yesCounter, voiceWeight);
    } else {
        noCounter = safeAdd(noCounter, voiceWeight);
    }
    votesByAddress[msg.sender].time = now;
    votesByAddress[msg.sender].weight = voiceWeight;
    votesByAddress[msg.sender].agree = agree;
    totalVoted = safeAdd(totalVoted, 1);
}

function onCrowdsaleEnd() external onlyCrowdsale {
    state = FundState.TeamWithdraw;
    ISimpleCrowdsale crowdsale = ISimpleCrowdsale(crowdsaleAddress);
    firstWithdrawAmount = safeDiv(crowdsale.getSoftCap(), 2);
    lastWithdrawTime = now;
    tap = INITIAL_TAP;
    crowdsaleEndDate = now;
}

function refundCrowdsaleContributor() external {
    require(state == FundState.CrowdsaleRefund);
    require(contributions[msg.sender] > 0);
    uint256 refundAmount = contributions[msg.sender];
    contributions[msg.sender] = 0;
    token.destroy(msg.sender, token.balanceOf(msg.sender));
    msg.sender.transfer(refundAmount);
    RefundContributor(msg.sender, refundAmount, now);
}

function withdraw() public onlyOwner withdrawEnabled {
    require(state == FundState.TeamWithdraw);
    uint256 amount = calcTapAmount();
    lastWithdrawTime = now;
    teamWallet.transfer(amount);
    Withdraw(amount, now);
}

function withdraw(uint _instId) external onlyInstanceOwner(_instId) instanceExists(_instId) whenNotPaused {
    HodlInstance storage curInst = instances[_instId];
    require(now >= curInst.endTime);
    require(curInst.hasBeenWithdrawn == false);
    curInst.hasBeenWithdrawn = true;
    curInst.instOwner.transfer(curInst.hodlAmount);
    HodlWithdrawn(_instId, msg.sender, curInst.hodlAmount);
}

function createNewHodl(uint _endTime) external payable blockCatEntryPoint limitTransactionValue whenNotPaused returns(uint currentId) {
    require(_endTime >= now);
    require((_endTime - now) <= maximumHodlDuration);
    require(msg.value > 0);
    currentId = instanceId;
    address instanceOwner = msg.sender;
    uint hodlAmount = msg.value;
    uint endTime = _endTime;
    HodlInstance storage curInst = instances[currentId];
    curInst.instId = currentId;
    curInst.instOwner = instanceOwner;
    curInst.hasBeenWithdrawn = false;
    curInst.hodlAmount = hodlAmount;
    curInst.endTime = endTime;
    HodlCreated(currentId, instanceOwner, hodlAmount, endTime);
    instanceId++;
}

function collect()
external
onlyOwner {
    require(block.timestamp > vestStart + vestPeriod + 60 days, "TOO_EARLY");
    uint amount = ERC20(lrcAddress).balanceOf(address(this));
    require(ERC20(lrcAddress).transfer(msg.sender, amount), "transfer failed");
}

function vested(address recipient)
public
view
returns(uint) {
    if (block.timestamp.sub(vestStart) < vestPeriod) {
        return records[recipient].rewarded.mul(block.timestamp.sub(vestStart)) / vestPeriod;
    } else {
        return records[recipient].rewarded;
    }
}

function updateRecipient(address oldRecipient, address newRecipient)
external {
    require(canChangeAddressFor(oldRecipient), "UNAUTHORIZED");
    require(newRecipient != address(0), "INVALID_ADDRESS");
    require(records[newRecipient].rewarded == 0, "INVALID_NEW_RECIPIENT");
    Record storage r = records[oldRecipient];
    require(r.rewarded > 0, "INVALID_OLD_RECIPIENT");
    records[newRecipient] = r;
    delete records[oldRecipient];
    emit MemberAddressChanged(oldRecipient, newRecipient);
}

function _withdraw(address recipient)
internal {
    uint amount = withdrawable(recipient);
    require(amount > 0, "INVALID_AMOUNT");
    Record storage r = records[recipient];
    r.lastWithdrawTime = block.timestamp;
    r.withdrawn = r.withdrawn.add(amount);
    require(ERC20(lrcAddress).transfer(recipient, amount), "transfer failed");
    emit Withdrawal(msg.sender, recipient, amount);
}

function contribute() external payable {
    require(msg.value > 0);
    require(isFunding);
    require(block.number <= endBlock);
    uint256 amount = msg.value * exchangeRate;
    uint256 total = totalMinted + amount;
    require(total <= maxMintable);
    totalMinted += total;
    ETHWallet.transfer(msg.value);
    Token.mintToken(msg.sender, amount);
    emit Contribution(msg.sender, amount);
}

function() payable public {
    require(msg.value > 0);
    require(isFunding);
    require(block.number <= endBlock);
    uint256 amount = msg.value * exchangeRate;
    uint256 total = totalMinted + amount;
    require(total <= maxMintable);
    totalMinted += total;
    ETHWallet.transfer(msg.value);
    Token.mintToken(msg.sender, amount);
    emit Contribution(msg.sender, amount);
}

function exchange(
    Order calldata order,
    Sig calldata sig,
    uint buyerFee,
    Sig calldata buyerFeeSig,
    uint amount,
    address buyer
) payable external {
    validateOrderSig(order, sig);
    validateBuyerFeeSig(order, buyerFee, buyerFeeSig);
    uint paying = order.buying.mul(amount).div(order.selling);
    verifyOpenAndModifyOrderState(order.key, order.selling, amount);
    require(order.key.sellAsset.assetType != AssetType.ETH, "ETH is not supported on sell side");
    if (order.key.buyAsset.assetType == AssetType.ETH) {
        validateEthTransfer(paying, buyerFee);
    }
    FeeSide feeSide = getFeeSide(order.key.sellAsset.assetType, order.key.buyAsset.assetType);
    if (buyer == address(0x0)) {
        buyer = msg.sender;
    }
    transferWithFeesPossibility(order.key.sellAsset, amount, order.key.owner, buyer, feeSide == FeeSide.SELL, buyerFee, order.sellerFee, order.key.buyAsset);
    transferWithFeesPossibility(order.key.buyAsset, paying, msg.sender, order.key.owner, feeSide == FeeSide.BUY, order.sellerFee, buyerFee, order.key.sellAsset);
    emitBuy(order, amount, buyer);
}

function doPurchase() payable {
    require(now >= startPreICO);
    require(msg.value >= 100000000000000);
    uint sum = msg.value;
    uint rest = 0;
    uint tokensAmount = 0;
    if (now >= startPreICO && now < startICO) {
        require(PreICOHardcap > tokensSold);
        tokensAmount = sum.mul(tokenDec).div(PreICOPrice);
        if (tokensAmount.add(tokensSold) > PreICOHardcap) {
            tokensAmount = PreICOHardcap.sub(tokensSold);
            rest = sum.sub(tokensAmount.mul(PreICOPrice).div(tokenDec));
        }
    } else if (now >= startICO && now < startProICO) {
        require(ICOHardcap > tokensSold);
        tokensAmount = sum.mul(tokenDec).div(ICOPrice);
        if (tokensAmount.add(tokensSold) > ICOHardcap) {
            tokensAmount = ICOHardcap.sub(tokensSold);
            rest = sum.sub(tokensAmount.mul(ICOPrice).div(tokenDec));
        }
    } else {
        require(ProICOHardcap > tokensSold);
        tokensAmount = sum.mul(tokenDec).div(ProICOPrice);
        if (tokensAmount.add(tokensSold) > ProICOHardcap) {
            tokensAmount = ProICOHardcap.sub(tokensSold);
            rest = sum.sub(tokensAmount.mul(ProICOPrice).div(tokenDec));
        }
    }
    tokensSold = tokensSold.add(tokensAmount);
    if (givenBonus < bonusAmount && tokensAmount >= 500 * tokenDec) {
        uint bonus = 0;
        if (tokensAmount >= 500 * tokenDec && tokensAmount < 1000 * tokenDec) {
            bonus = 20 * tokenDec;
        } else if (tokensAmount >= 1000 * tokenDec && tokensAmount < 5000 * tokenDec) {
            bonus = 100 * tokenDec;
        } else if (tokensAmount >= 5000 * tokenDec && tokensAmount < 10000 * tokenDec) {
            bonus = 600 * tokenDec;
        } else if (tokensAmount >= 10000 * tokenDec) {
            bonus = 1500 * tokenDec;
        }
        bonus = (bonus < (bonusAmount - givenBonus)) ? bonus : (bonusAmount - givenBonus);
        givenBonus = givenBonus.add(bonus);
        tokensAmount = tokensAmount.add(bonus);
    }
    require(tokenBalance() > tokensAmount);
    require(token.transfer(msg.sender, tokensAmount));
    if (rest == 0) {
        multisig.transfer(msg.value);
    } else {
        multisig.transfer(msg.value.sub(rest));
        msg.sender.transfer(rest);
    }
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 5 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 15 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 10 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 1e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

