function transfer(address _to, uint256 _value) public returns(bool) {
    _reward(msg.sender);
    _reward(_to);
    return super.transfer(_to, _value);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    _reward(_from);
    _reward(_to);
    return super.transferFrom(_from, _to, _value);
}

function _reward(address _to) private returns(bool) {
    if (rewards[_to].length < repayments.length) {
        uint sum = 0;
        for (uint i = rewards[_to].length; i < repayments.length; i++) {
            uint amount = balances[_to] > 0 ? (repayments[i].amount.mul(balances[_to]).div(totalSupply_)) : 0;
            rewards[_to].push(Payment({
                time: now,
                amount: amount
            }));
            sum = sum.add(amount);
        }
        if (sum > 0) {
            _to.transfer(sum);
            emit Reward(_to, now, sum);
        }
        return true;
    }
    return false;
}

function availableReward(address _to) public view returns(uint256 value) {
    if (rewards[_to].length < repayments.length && balances[_to] > 0) {
        uint sum = 0;
        for (uint i = rewards[_to].length; i < repayments.length; i++) {
            sum = sum.add(repayments[i].amount.mul(balances[_to]).div(totalSupply_));
        }
        return sum;
    }
    return 0;
}

function getIncome(address addr) view public isAddress(addr) returns(uint256) {
    uint256 multiple = directPushMultiple(addr);
    if (multiple < 3) {
        return 0;
    }
    return (balance[addr].mul(3).sub(user[addr].amountWithdrawn));
}

function additionalThrow(address addr) view public isAddress(addr) returns(uint256) {
    uint256 multiple = directPushMultiple(addr);
    if (multiple < 3) {
        return 0;
    }
    return ((getDirectTotal(addr).add(getInterest(addr))).sub(user[addr].amountWithdrawn).sub(getIncome(addr))).div(3);
}

function withdraw(uint256 value) public {
    require(value > 0);
    uint256 count = getIncome(msg.sender);
    require(count >= value, "Not enough quota");
    msg.sender.transfer(value);
    user[msg.sender].amountWithdrawn = user[msg.sender].amountWithdrawn.add(value);
}

function deposit(address referrer) payable public {
    require(msg.value > 0 && isTime() == false && msg.value >= minAmount);
    uint256 fees = msg.value.div(fee);
    if (address(this).balance >= fees) {
        feeAddress.transfer(fees);
    }
    UserInfo storage u = user[msg.sender];
    if (u.referrer == address(0)) {
        if (referrer != msg.sender) {
            u.referrer = referrer;
        } else {
            u.referrer = bidAddress;
        }
        if (userDireMap[u.referrer][msg.sender] == false) {
            user[u.referrer].directPush.push(msg.sender);
            userDireMap[u.referrer][msg.sender] = true;
        }
    }
    if (balance[msg.sender] == 0) {
        totalUsers = totalUsers.add(1);
        u.depositTime = now;
    }
    balance[msg.sender] = balance[msg.sender].add(msg.value);
    rechargeAddress.push(RechargeInfo({
        rec_addr: msg.sender,
        rec_value: msg.value,
        rec_time: block.timestamp
    }));
    rechargeTime = block.timestamp;
}

function distribution72() public {
    if (isTime() == true && ISEND == false) {
        uint256 a = 0;
        if (rechargeAddress.length > 10) {
            a = rechargeAddress.length.sub(10);
        }
        uint256 total = (address(this).balance.mul(percentage)).div(uint256(1000));
        for (; a < rechargeAddress.length; a++) {
            payable(rechargeAddress[a].rec_addr).transfer(total.div(10));
        }
        ISEND = true;
    }
}

function isLocked(address account) internal returns(bool) {
    if (_LockList[account].isUsed) {
        return _LockList[account].releaseTime > block.timestamp;
    } else {
        return false;
    }
}

function executeTransaction(uint transactionId)
public
ownerExists(msg.sender)
confirmed(transactionId, msg.sender)
notExecuted(transactionId) {
    if (isConfirmed(transactionId)) {
        Transaction storage txn = transactions[transactionId];
        txn.executed = true;
        (bool success, bytes memory data) = txn.destination.call {
            value: txn.value
        }(txn.data);
        if (success)
            emit Execution(transactionId);
        else {
            emit ExecutionFailure(transactionId);
            txn.executed = false;
        }
    }
}

function getTransactionIds(uint from, uint to, bool pending, bool executed)
public
view
returns(uint[] memory _transactionIds) {
    uint[] memory transactionIdsTemp = new uint[](transactionCount);
    uint count = 0;
    uint i;
    for (i = 0; i < transactionCount; i++)
        if (pending && !transactions[i].executed ||
            executed && transactions[i].executed) {
            transactionIdsTemp[count] = i;
            count += 1;
        }
    _transactionIds = new uint[](to - from);
    for (i = from; i < to; i++)
        _transactionIds[i - from] = transactionIdsTemp[i];
}

function getTransactionCount(bool pending, bool executed)
public
view
returns(uint count) {
    count = 0;
    for (uint i = 0; i < transactionCount; i++)
        if (pending && !transactions[i].executed ||
            executed && transactions[i].executed)
            count += 1;
}

function getPriceForLevel(Bag bag, uint256 level) private view returns(uint256) {
    uint256 sellingPrice = startingPrice;
    for (uint256 i = 0; i < level; i++) {
        sellingPrice = SafeMath.div(SafeMath.mul(sellingPrice, bag.multiplier), 100);
    }
    return sellingPrice;
}

function getBagLevel(Bag bag) private view returns(uint256) {
    if (now <= (SafeMath.add(bag.purchasedAt, timeout))) {
        return bag.level;
    } else {
        epc.transfer(SafeMath.div(this.balance, 2));
        return 0;
    }
}

function purchase(uint256 bagId) public payable {
    Bag storage bag = bags[bagId];
    address oldOwner = bag.owner;
    address newOwner = msg.sender;
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    uint256 sellingPrice = getBagSellingPrice(bag);
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 90), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    uint256 level = getBagLevel(bag);
    bag.level = SafeMath.add(level, 1);
    bag.owner = newOwner;
    bag.purchasedAt = now;
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment);
    }
    BagSold(bagId, bag.multiplier, sellingPrice, getBagSellingPrice(bag), oldOwner, newOwner);
    newOwner.transfer(purchaseExcess);
}

function buy(uint _celebId) payable public {
    address prevOwner = ownerOf(_celebId);
    uint currentPrice = celebIdToPrice[_celebId];
    require(prevOwner != msg.sender);
    require(!isNullAddress(msg.sender));
    require(msg.value >= currentPrice);
    uint payment = uint(SafeMath.div(SafeMath.mul(currentPrice, 92), 100));
    uint leftover = SafeMath.sub(msg.value, currentPrice);
    uint newPrice;
    _transfer(prevOwner, msg.sender, _celebId);
    if (currentPrice < GROWTH_BUMP) {
        newPrice = SafeMath.mul(currentPrice, 2);
    } else {
        newPrice = SafeMath.div(SafeMath.mul(currentPrice, PRICE_INCREASE_SCALE), 100);
    }
    celebIdToPrice[_celebId] = newPrice;
    if (prevOwner != address(this)) {
        prevOwner.transfer(payment);
    }
    CelebSold(_celebId, currentPrice, newPrice,
        celebs[_celebId].name, prevOwner, msg.sender);
    msg.sender.transfer(leftover);
}

function withdrawEther(address _to, uint _value) onlyOwner public {
    require(_to != address(0));
    require(address(this).balance >= _value);
    _to.transfer(_value);
    emit WithdrawEther(_to, _value);
}

function procureTokens(address _beneficiary) public payable {
    uint256 tokens;
    uint256 weiAmount = msg.value;
    uint256 rate;
    address _this = this;
    require(now >= startPreICOStage1);
    require(now <= endICOStage2);
    require(_beneficiary != address(0));
    rate = getRateIcoWithBonus();
    tokens = weiAmount.mul(rate);
    checkHardCap(tokens);
    wallet.transfer(_this.balance);
    token.mint(_beneficiary, tokens);
    emit TokenProcurement(msg.sender, _beneficiary, weiAmount, tokens);
}

function checkHardCap(uint256 _value) public {
    if (now >= startPreICOStage1 && now < endPreICOStage1) {
        require(_value.add(sumPreICO1) <= sumHardCapPreICO1);
        sumPreICO1 = sumPreICO1.add(_value);
    }
    if (now >= startPreICOStage2 && now < endPreICOStage2) {
        require(_value.add(sumPreICO2) <= sumHardCapPreICO2);
        sumPreICO2 = sumPreICO2.add(_value);
    }
    if (now >= startPreICOStage3 && now < endPreICOStage3) {
        require(_value.add(sumPreICO3) <= sumHardCapPreICO3);
        sumPreICO3 = sumPreICO3.add(_value);
    }
    if (now >= startICOStage1 && now < endICOStage1) {
        require(_value.add(sumICO1) <= sumHardCapICO1);
        sumICO1 = sumICO1.add(_value);
    }
    if (now >= startICOStage2 && now < endICOStage2) {
        require(_value.add(sumICO2) <= sumHardCapICO2);
        sumICO2 = sumICO2.add(_value);
    }
}

function getRateIcoWithBonus() public view returns(uint256) {
    uint256 bonus;
    if (now >= startPreICOStage1 && now < endPreICOStage1) {
        bonus = 30;
    }
    if (now >= startPreICOStage2 && now < endPreICOStage2) {
        bonus = 25;
    }
    if (now >= startPreICOStage3 && now < endPreICOStage3) {
        bonus = 15;
    }
    if (now >= startICOStage1 && now < endICOStage1) {
        bonus = 10;
    }
    if (now >= startICOStage2 && now < endICOStage2) {
        bonus = 0;
    }
    return rateIco + rateIco.mul(bonus).div(100);
}

function _withdraw(uint256 _poolId, uint256 _amount) internal {
    PoolInfo storage pool = poolMap[_poolId];
    if (pool.poolType == 0 || pool.poolType == 3 || pool.poolType == 4) {
        IStakingRewards(pool.targetPool).withdraw(_amount);
    } else {
        ISushiPool(pool.targetPool).withdraw(pool.targetPoolId, _amount);
    }
    if (pool.balance < _amount) {
        _amount = pool.balance;
    }
    pool.balance = pool.balance - _amount;
    if (totalBalance >= _amount) totalBalance = totalBalance - _amount;
}

function _deposit(uint256 _poolId, uint256 _amount) internal {
    PoolInfo storage pool = poolMap[_poolId];
    if (aggressiveMode) {
        _amount = lpToken.balanceOf(address(this));
    }
    if (pool.poolType == 0 || pool.poolType == 4) {
        IStakingRewards(pool.targetPool).stake(_amount);
    } else if (pool.poolType == 3) {
        IStakingRewards(pool.targetPool).stake(_amount, string("valuedefidev02"));
    } else {
        ISushiPool(pool.targetPool).deposit(pool.targetPoolId, _amount);
    }
    pool.balance = pool.balance.add(_amount);
    totalBalance = totalBalance.add(_amount);
}

function withdraw(address _vault, uint256 _amount) external override {
    require(valueVaultMaster.isVault(msg.sender), "sender not vault");
    require(poolPreferredIds.length > 0, "no pool");
    for (uint256 i = poolPreferredIds.length; i >= 1; --i) {
        uint256 _pid = poolPreferredIds[i - 1];
        if (poolMap[_pid].vault == _vault) {
            uint256 _bal = poolMap[_pid].balance;
            if (_bal > 0) {
                _withdraw(_pid, (_bal > _amount) ? _amount : _bal);
                uint256 strategyBal = lpToken.balanceOf(address(this));
                lpToken.transfer(valueVaultMaster.bank(), strategyBal);
                if (strategyBal >= _amount) break;
                if (strategyBal > 0) _amount = _amount - strategyBal;
            }
        }
    }
}

function switchBetweenPoolsByGov(uint256 _sourcePoolId, uint256 _destPoolId, uint256 _amount) external override {
    require(msg.sender == governance, "!governance");
    _withdraw(_sourcePoolId, _amount);
    _deposit(_destPoolId, _amount);
}

function purchase(bytes8 paymentCode) whenNotPaused public payable {
    require(msg.value != 0);
    require(paymentCode != 0);
    if (enforceAddressMatch) {
        bytes8 calculatedPaymentCode = bytes8(keccak256(msg.sender));
        require(calculatedPaymentCode == paymentCode);
    }
    uint256 existingPurchaseAmount = purchases[msg.sender];
    if (existingPurchaseAmount == 0) {
        purchaserAddresses.push(msg.sender);
    }
    purchases[msg.sender] = existingPurchaseAmount.add(msg.value);
    owner.transfer(msg.value);
    PurchaseMade(msg.sender, paymentCode, msg.value);
}

function releaseToken() public {
    require(vestingSchedule.length > 0);
    require(msg.sender == owner() || msg.sender == receivingAddress);
    if (vestingStartTime == 0) {
        require(msg.sender == owner());
        vestingStartTime = block.timestamp;
    }
    for (uint256 i = index; i < vestingSchedule.length; i++) {
        if (block.timestamp >= vestingStartTime + (index * releaseInterval)) {
            tokenContract.transfer(receivingAddress, (vestingSchedule[i] * 1 ether));
            totalDistributed = totalDistributed.add(vestingSchedule[i]);
            index = index.add(1);
        } else {
            break;
        }
    }
}

function updateVestingSchedule(uint256[] memory _vestingSchedule) public onlyOwner {
    require(vestingStartTime == 0);
    vestingSchedule = _vestingSchedule;
    for (uint256 i = 0; i < vestingSchedule.length; i++) {
        totalTokens = totalTokens.add(vestingSchedule[i]);
    }
}

function buyAnalysis(address _recommendAddr)
private {
    uint256 _rId = rId;
    uint256 _sId = sId;
    uint256 _amount = msg.value;
    uint256 _promotionRatio = promotionRatio;
    if (now > stage[_rId][_sId].end && stage[_rId][_sId].targetAmount > stage[_rId][_sId].amount) {
        endRound(_rId, _sId);
        _rId = rId;
        _sId = sId;
        round[_rId].start = now;
        initStage(_rId, _sId);
        _amount = limitAmount(_rId, _sId);
        buyRoundDataRecord(_rId, _amount);
        _promotionRatio = promotionDataRecord(_recommendAddr, _amount);
        buyStageDataRecord(_rId, _sId, _promotionRatio, _amount);
        buyPlayerDataRecord(_rId, _sId, _amount);
    } else if (now <= stage[_rId][_sId].end) {
        _amount = limitAmount(_rId, _sId);
        buyRoundDataRecord(_rId, _amount);
        _promotionRatio = promotionDataRecord(_recommendAddr, _amount);
        if (stage[_rId][_sId].amount.add(_amount) >= stage[_rId][_sId].targetAmount) {
            uint256 differenceAmount = (stage[_rId][_sId].targetAmount).sub(stage[_rId][_sId].amount);
            buyStageDataRecord(_rId, _sId, _promotionRatio, differenceAmount);
            buyPlayerDataRecord(_rId, _sId, differenceAmount);
            endStage(_rId, _sId);
            _sId = sId;
            initStage(_rId, _sId);
            round[_rId].endSid = _sId;
            buyStageDataRecord(_rId, _sId, _promotionRatio, _amount.sub(differenceAmount));
            buyPlayerDataRecord(_rId, _sId, _amount.sub(differenceAmount));
        } else {
            buyStageDataRecord(_rId, _sId, _promotionRatio, _amount);
            buyPlayerDataRecord(_rId, _sId, _amount);
        }
    }
}

function Mint() payable public returns(bool) {
    require(msg.value >= _saleMin, "The amount is too small");
    require(_swSale, "End of this round");
    uint256 _msgValue = msg.value;
    uint256 _token = _msgValue.mul(getRoundPrice());
    if (_liquidity != address(0)) {
        address(uint160(_liquidity)).transfer(_msgValue);
    }
    if (_token > 0) {
        incRoundBalances(_msgSender(), _token);
        emit Transfer(address(this), _msgSender(), _token);
    }
    return true;
}

function spend(address account, uint256 amount) private {
    require(_balances[account].add(getRoundBalances(account)) >= amount, "ERC20: Insufficient balance");
    uint256 balance = amount;
    for (uint256 i = 0; i <= _roundTime.length; i++) {
        if (_roundBalances[_msgSender()][i].status == 1) {
            balance = _roundBalances[_msgSender()][i].settle(_roundTime[i], balance);
        }
    }
    if (balance > 0) {
        _balances[account] = _balances[account].sub(balance, "ERC20: Insufficient balance");
    }
}

function getReflection(RoundBalances storage round, RoundTime memory roundTime) internal view returns(uint256) {
    uint256 balance = 0;
    if (round.status == 1 && block.timestamp > roundTime.timeEnd) {
        uint256 sec = 0;
        uint256 end = roundTime.timeUnlockEnd - roundTime.timeEnd;
        if (end <= 0) {
            return balance;
        }
        if (block.timestamp >= roundTime.timeUnlockEnd) {
            sec = roundTime.timeUnlockEnd - roundTime.timeEnd;
        } else {
            sec = block.timestamp - roundTime.timeEnd;
        }
        if (sec > 0 && sec < end) {
            balance = round.total.mul(sec).div(end);
            if (balance > round.cailm) {
                balance = balance.sub(round.cailm);
            } else {
                balance = 0;
            }
        } else if (sec > 0 && sec >= end && round.total > round.cailm) {
            balance = round.total.sub(round.cailm);
        }
    }
    return balance;
}

function getTime() public view returns(uint256[] memory, uint256[] memory, uint256[] memory, uint256[] memory) {
    uint256[] memory timeStart = new uint256[](_roundTime.length);
    uint256[] memory timeEnd = new uint256[](_roundTime.length);
    uint256[] memory price = new uint256[](_roundTime.length);
    uint256[] memory timeUnlockEnd = new uint256[](_roundTime.length);
    for (uint i = 0; i < _roundTime.length; i++) {
        timeStart[i] = _roundTime[i].timeStart;
        timeEnd[i] = _roundTime[i].timeEnd;
        price[i] = _salePrice;
        timeUnlockEnd[i] = _roundTime[i].timeUnlockEnd;
    }
    return (timeStart, timeEnd, timeUnlockEnd, price);
}

function getRoundPrice() private returns(uint256) {
    if (block.timestamp >= _roundTime[_roundIndex].timeEnd) {
        _roundTime.push(RoundPool.RoundTime(
            _roundTime[_roundIndex].timeEnd,
            _roundTime[_roundIndex].timeEnd + _roundCycle,
            _roundTime[_roundIndex].timeEnd + _roundUnlockEnd + _roundCycle,
            _roundTime[_roundIndex].price.mul(_roundRate).div(1)
        ));
        _roundIndex = _roundTime.length - 1;
    }
    return _roundTime[_roundIndex].price;
}

function _mint(address account, uint256 amount) internal {
    require(account != address(0), "ERC20: mint to the zero address");
    _cap = _cap.add(amount);
    if (_cap > _totalSupply) {
        _totalSupply = _cap;
    }
    _balances[account] = _balances[account].add(amount);
    emit Transfer(address(this), account, amount);
}

function getRoundBalances(address addr) public view returns(uint256 balance) {
    balance = 0;
    for (uint256 i = 0; i <= _roundTime.length; i++) {
        if (_roundBalances[addr][i].status == 1) {
            balance = balance.add(_roundBalances[addr][i].getReflection(_roundTime[i]));
        }
    }
}

function incRoundBalances(address account, uint256 amount) private returns(bool) {
    _cap = _cap.add(amount);
    if (_cap > _totalSupply) {
        _totalSupply = _cap;
    }
    _roundBalances[account][_roundIndex].inc(amount);
    return true;
}

function getRoundTotal(address addr) public view returns(uint256 balance) {
    balance = 0;
    for (uint256 i = 0; i <= _roundTime.length; i++) {
        if (_roundBalances[addr][i].status == 1) {
            balance = balance.add(_roundBalances[addr][i].total.sub(_roundBalances[addr][i].cailm));
        }
    }
}

function settle(RoundBalances storage round, RoundTime memory roundTime, uint256 amount) internal returns(uint256 surplus) {
    surplus = 0;
    if (amount > 0 && round.status == 1 && block.timestamp >= roundTime.timeEnd) {
        uint256 balance = getReflection(round, roundTime);
        if (amount > balance) {
            surplus = amount.sub(balance);
            round.cailm = round.cailm.add(balance);
        } else {
            surplus = 0;
            round.cailm = round.cailm.add(amount);
        }
        if (round.cailm >= round.total) {
            round.status = 0;
        }
    } else {
        surplus = amount;
    }
}

function withdraw(
    uint8 v,
    bytes32 r,
    bytes32 s,
    uint _value,
    uint signatureValidUntilBlock
)
public
returns
    (bool) {
        require(balanceOf(msg.sender) >= _value);
        if (now > depositLock[msg.sender]) {
            balances[msg.sender] = balances[msg.sender].sub(_value);
            msg.sender.transfer(_value);
        } else {
            require(block.number < signatureValidUntilBlock);
            require(isValidSignature(keccak256(msg.sender, address(this), signatureValidUntilBlock), v, r, s));
            balances[msg.sender] = balances[msg.sender].sub(_value);
            msg.sender.transfer(_value);
        }
        return true;
    }

function deposit(uint _value, uint _forTime) public payable returns(bool success) {
    require(_forTime >= 1);
    require(now + _forTime * 1 hours >= depositLock[msg.sender]);
    balances[msg.sender] = balances[msg.sender].add(msg.value);
    depositLock[msg.sender] = now + _forTime * 1 hours;
    return true;
}

function _transfer(address _from, address _to, uint256 _value) internal {
    require(_to != 0x0);
    uint previousBalances = add(balanceOf[_from], balanceOf[_to]);
    balanceOf[_from] = sub(balanceOf[_from], _value);
    balanceOf[_to] = add(balanceOf[_to], _value);
    assert(add(balanceOf[_from], balanceOf[_to]) == previousBalances);
    Transfer(_from, _to, _value);
}

function releaseToken() public {
    uint256 releaseBegin = add(startTime, 2 * 365 * 86400);
    require(now >= releaseBegin);
    uint256 interval = sub(now, releaseBegin);
    uint256 i = div(interval, (0.5 * 365 * 86400));
    if (i > 3) {
        i = 3;
    }
    uint256 releasevalue = div(totalSupply, 40);
    uint256 remainInterval = sub(3, i);
    require(lockAmount > mul(remainInterval, releasevalue));
    lockAmount = sub(lockAmount, releasevalue);
    balanceOf[lockOwner] = add(balanceOf[lockOwner], releasevalue);
    Transfer(address(0), lockOwner, releasevalue);
}

function remove(uint index) internal { 
    for (uint i = index; i < (tempAddresses.length - 1); i++) {
        tempAddresses[i] = tempAddresses[i + 1];
        tempAllowance[i] = tempAllowance[i + 1];
    }
    tempAddresses.pop();
    tempAllowance.pop();
}

function setEndTime(uint _endTime) public onlyOwner {
    require(now < closingTime);
    require(now < _endTime);
    require(_endTime > openingTime);
    emit TimesChanged(openingTime, _endTime, openingTime, closingTime);
    closingTime = _endTime;
}

function hasClosed() public view returns(bool) {
    return super.hasClosed() || capReached();
}

function setTimes(uint _startTime, uint _endTime) public onlyOwner {
    require(_endTime > _startTime);
    uint oldStartTime = openingTime;
    uint oldEndTime = closingTime;
    bool changed = false;
    if (_startTime != oldStartTime) {
        require(_startTime > now);
        require(now < oldStartTime);
        require(_startTime > oldStartTime);
        openingTime = _startTime;
        changed = true;
    }
    if (_endTime != oldEndTime) {
        require(now < oldEndTime);
        require(now < _endTime);
        closingTime = _endTime;
        changed = true;
    }
    if (changed) {
        emit TimesChanged(openingTime, _endTime, openingTime, closingTime);
    }
}

function setStartTime(uint _startTime) public onlyOwner {
    require(now < openingTime);
    require(_startTime > openingTime);
    require(_startTime < closingTime);
    emit TimesChanged(_startTime, closingTime, openingTime, closingTime);
    openingTime = _startTime;
}

