function withdraw(uint256 _amount) onlyOwner {
    var (unlockedTokens, excessTokens) = canBeWithdrawn();
    uint256 totalAmount = unlockedTokens + excessTokens;
    require(totalAmount > 0);
    if (_amount == 0) {
        _amount = totalAmount;
    }
    require(totalAmount >= _amount);
    uint256 unlockedToWithdraw =
        _amount > unlockedTokens ?
        unlockedTokens :
        _amount;
    if (unlockedToWithdraw > 0) {
        uint8 i = 0;
        while (unlockedToWithdraw > 0 && i < _timestamps.length) {
            if (now >= _timestamps[i]) {
                uint256 amountToReduce =
                    unlockedToWithdraw > _releaseTiers[_timestamps[i]] ?
                    _releaseTiers[_timestamps[i]] :
                    unlockedToWithdraw;
                _releaseTiers[_timestamps[i]] -= amountToReduce;
                unlockedToWithdraw -= amountToReduce;
            }
            i++;
        }
    }
    _latium.transfer(msg.sender, _amount);
}

function canBeWithdrawn() constant returns(uint256 unlockedTokens, uint256 excessTokens) {
    unlockedTokens = 0;
    excessTokens = 0;
    uint256 tiersBalance = 0;
    for (uint8 i = 0; i < _timestamps.length; i++) {
        tiersBalance += _releaseTiers[_timestamps[i]];
        if (now >= _timestamps[i]) {
            unlockedTokens += _releaseTiers[_timestamps[i]];
        }
    }
    uint256 balance = latiumBalance();
    if (unlockedTokens > balance) {
        unlockedTokens = balance;
    } else if (balance > tiersBalance) {
        excessTokens = (balance - tiersBalance);
    }
}

function lockedTokens() constant returns(uint256 locked) {
    locked = 0;
    uint256 unlocked = 0;
    for (uint8 i = 0; i < _timestamps.length; i++) {
        if (now >= _timestamps[i]) {
            unlocked += _releaseTiers[_timestamps[i]];
        } else {
            locked += _releaseTiers[_timestamps[i]];
        }
    }
    uint256 balance = latiumBalance();
    if (unlocked > balance) {
        locked = 0;
    } else {
        balance -= unlocked;
        if (balance < locked) {
            locked = balance;
        }
    }
}

function crowdsaleRunning() constant public returns(bool) {
    return (now > startTimestamp) && (now <= endTimestamp) && (availableSupply > 0) && !finalized;
}

function finalizeCrowdsale() public {
    require((now > endTimestamp) || (availableSupply == 0) || (msg.sender == owner));
    finalized = dfs.finishMinting();
    dfs.transferOwnership(owner);
}

function PayJackpot() public {
    if (block.timestamp > Timer && Jackpot != address(0x0)) {
        uint256 pay = (SafeMath.div(SafeMath.mul(JackpotAmount, JackpotPay), 100));
        referralBalance_[Jackpot] += pay;
        Jackpot = address(0x0);
        JackpotAmount = SafeMath.sub(JackpotAmount, (uint256)(pay));
    }
}

function purchaseTokens(uint256 _incomingEthereum, address _referredBy)
internal
antiEarlyWhale(_incomingEthereum)
returns(uint256) {
    if (block.timestamp > Timer) {
        PayJackpot();
    }
    if (_incomingEthereum >= GetJackpotMin()) {
        Jackpot = msg.sender;
        Timer = block.timestamp + JackpotTimer;
    }
    uint256 _undividedDividends = SafeMath.div(_incomingEthereum, dividendFee_);
    uint256 _referralBonus = SafeMath.div(_undividedDividends, 3);
    if ((_referredBy != 0x0000000000000000000000000000000000000000 && _referredBy != msg.sender && tokenBalanceLedger_[_referredBy] >= stakingRequirement)) {
    } else {
        _referralBonus = 0;
    }
    uint256 _jackpotAmount = SafeMath.div(SafeMath.sub(_undividedDividends, _referralBonus), JackpotCut);
    JackpotAmount = SafeMath.add(JackpotAmount, _jackpotAmount);
    uint256 _dividends = SafeMath.sub(SafeMath.sub(_undividedDividends, _referralBonus), _jackpotAmount);
    uint256 _taxedEthereum = SafeMath.sub(_incomingEthereum, _undividedDividends);
    uint256 _amountOfTokens = ethereumToTokens_(_taxedEthereum);
    uint256 _fee = _dividends * magnitude;
    require(_amountOfTokens > 0 && (SafeMath.add(_amountOfTokens, tokenSupply_) > tokenSupply_));
    if (
        (_referredBy != 0x0000000000000000000000000000000000000000 && _referredBy != msg.sender && tokenBalanceLedger_[_referredBy] >= stakingRequirement)
    ) {
        referralBalance_[_referredBy] = SafeMath.add(referralBalance_[_referredBy], _referralBonus);
    }
    if (tokenSupply_ > 0) {
        tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
        profitPerShare_ += (_dividends * magnitude / (tokenSupply_));
        _fee = _fee - (_fee - (_amountOfTokens * (_dividends * magnitude / (tokenSupply_))));
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    tokenBalanceLedger_[msg.sender] = SafeMath.add(tokenBalanceLedger_[msg.sender], _amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens) - _fee);
    payoutsTo_[msg.sender] += _updatedPayouts;
    onTokenPurchase(msg.sender, _incomingEthereum, _amountOfTokens, _referredBy);
    return _amountOfTokens;
}

