function updatePrice(uint256 tokenID, address _mintableToken, uint256 _newPrice) public {
    MintableToken Token = MintableToken(_mintableToken);
    require(
        Token.ownerOf(tokenID) == msg.sender,
        "You must be owner and Token should not have any bid"
    );
    require(
        tokenOpenForSale[_mintableToken][tokenID] == true,
        "Token Must be on sale to change price"
    );
    if (auctions[_mintableToken][tokenID].auctionType == 2) {
        require(
            block.timestamp < auctions[_mintableToken][tokenID].closingTime,
            "Auction Time Over!"
        );
    }
    emit PriceUpdated(
        _mintableToken,
        tokenID,
        auctions[_mintableToken][tokenID].lastOwner,
        auctions[_mintableToken][tokenID].auctionType,
        auctions[_mintableToken][tokenID].auctionType == 1 ? auctions[_mintableToken][tokenID].buyPrice : auctions[_mintableToken][tokenID].startingPrice,
        _newPrice,
        block.timestamp
    );
    if (auctions[_mintableToken][tokenID].auctionType == 1) {
        auctions[_mintableToken][tokenID].buyPrice = _newPrice;
    } else {
        auctions[_mintableToken][tokenID].startingPrice = _newPrice;
        auctions[_mintableToken][tokenID].currentBid = _newPrice;
    }
}

function putOnSale(
    uint256 _tokenID,
    uint256 _startingPrice,
    uint256 _auctionType,
    uint256 _buyPrice,
    uint256 _duration,
    address _mintableToken
) public {
    MintableToken Token = MintableToken(_mintableToken);
    require(Token.ownerOf(_tokenID) == msg.sender, "Permission Denied");
    require(
        Token.getApproved(_tokenID) == address(this),
        "Broker Not approved"
    );
    if (tokenOpenForSale[_mintableToken][_tokenID] == true) {
        require(
            auctions[_mintableToken][_tokenID].auctionType == 2 &&
            auctions[_mintableToken][_tokenID].buyer == false &&
            block.timestamp > auctions[_mintableToken][_tokenID].closingTime,
            "This NFT is already on sale."
        );
    }
    auction memory newAuction = auction(
        msg.sender,
        _startingPrice,
        address(0),
        _auctionType,
        _startingPrice,
        _buyPrice,
        false,
        block.timestamp,
        block.timestamp + _duration
    );
    auctions[_mintableToken][_tokenID] = newAuction;
    if (tokenOpenForSale[_mintableToken][_tokenID] == false) {
        tokenOpenForSale[_mintableToken][_tokenID] = true;
        tokensForSale.addTokenDet(_mintableToken, _tokenID);
        tokensForSalePerUser[msg.sender].addTokenDet(_mintableToken, _tokenID);
        if (_auctionType == 1) {
            fixedPriceTokens.addTokenDet(_mintableToken, _tokenID);
        } else if (_auctionType == 2) {
            auctionTokens.addTokenDet(_mintableToken, _tokenID);
        }
    }
    emit OnSale(
        _mintableToken,
        _tokenID,
        msg.sender,
        _auctionType,
        _auctionType == 1 ? _buyPrice : _startingPrice,
        block.timestamp
    );
}

function decide() internal {
    uint256 quorumPercent = getQuorumPercent();
    uint256 quorum = quorumPercent.mul(tokenContract.totalSupply()).div(100);
    uint256 soFarVoted = yesVoteSum.add(noVoteSum);
    if (soFarVoted >= quorum) {
        uint256 percentYes = (100 * yesVoteSum).div(soFarVoted);
        if (percentYes >= initialQuorumPercent) {
            proxyVotingContract.proxyIncreaseWithdrawalChunk();
            FinishBallot(now);
            isVotingActive = false;
        } else {
            isVotingActive = false;
            FinishBallot(now);
        }
    }
}

function processVote(bool isYes) internal {
    require(isVotingActive);
    require(!votesByAddress[msg.sender]);
    votersLength = votersLength.add(1);
    uint256 voteWeight = tokenContract.balanceOf(msg.sender);
    if (isYes) {
        yesVoteSum = yesVoteSum.add(voteWeight);
    } else {
        noVoteSum = noVoteSum.add(voteWeight);
    }
    require(getTime().sub(tokenContract.lastMovement(msg.sender)) > 7 days);
    uint256 quorumPercent = getQuorumPercent();
    if (quorumPercent == 0) {
        isVotingActive = false;
    } else {
        decide();
    }
    votesByAddress[msg.sender] = true;
}

function getQuorumPercent() public constant returns(uint256) {
    require(isVotingActive);
    uint256 weeksNumber = getTime().sub(ballotStarted).div(1 weeks);
    if (weeksNumber == 0) {
        return initialQuorumPercent;
    }
    if (initialQuorumPercent < weeksNumber * 10) {
        return 0;
    } else {
        return initialQuorumPercent.sub(weeksNumber * 10);
    }
}

function isReadyToFinalize() internal returns(bool) {
    return (
        (weiRaised >= convertUsdToEther(saleCapUsd)) ||
        (getCurrentState() == State.MainSaleDone)
    );
}

function buyTokens() public payable {
    require(token != address(0));
    address recipient = msg.sender;
    State state = getCurrentState();
    uint256 weiToBuy = msg.value;
    require(
        (state == State.MainSale) &&
        (weiToBuy > 0)
    );
    weiToBuy = min(weiToBuy, getWeiAllowedFromAddress(recipient));
    require(weiToBuy > 0);
    weiToBuy = min(weiToBuy, convertUsdToEther(saleCapUsd).sub(weiRaised));
    require(weiToBuy > 0);
    uint256 tokenAmount = getTokenAmountForEther(weiToBuy);
    require(tokenAmount > 0);
    uint256 weiToReturn = msg.value.sub(weiToBuy);
    weiRaised = weiRaised.add(weiToBuy);
    raisedByAddress[recipient] = raisedByAddress[recipient].add(weiToBuy);
    if (weiToReturn > 0) {
        recipient.transfer(weiToReturn);
        ChangeReturn(recipient, weiToReturn);
    }
    forwardFunds(weiToBuy);
    require(token.mint(recipient, tokenAmount));
    TokenPurchase(recipient, weiToBuy, tokenAmount);
}

