function getStateForTime(uint256 unixTime) internal returns(State) {
    if (isFinalized) {
        return State.Finalized;
    }
    if (unixTime < saleStartDate) {
        return State.BeforeMainSale;
    }
    if (unixTime < saleEndDate) {
