function emergencyUnstake(
    uint256 stakeId,
    address userAddress,
    address[] memory rewardtokens,
    uint256[] memory amount
) external onlyOwner {
    (
        address[] memory referrerAddress,
        address[] memory tokenAddress,
        bool[] memory activeStatus, ,
        uint256[] memory stakedAmount,
    ) = (u2.viewStakingDetails(userAddress));
    bool isAlreadyUnstaked = u2Proxy.unstakeStatus(userAddress, stakeId);
    if (
        u2UnstakeStatus[userAddress][stakeId] == false &&
        activeStatus[stakeId] == true &&
        isAlreadyUnstaked == false
    ) u2UnstakeStatus[userAddress][stakeId] = true;
    else revert("EMERGENCY: Unstaked Already");
    safeTransfer(tokenAddress[stakeId]);
    require(
        IERC20(tokenAddress[stakeId]).balanceOf(address(this)) >=
        stakedAmount[stakeId],
        "EMERGENCY : Insufficient Balance"
    );
    u2UpgradeTotalUnStaking[
        tokenAddress[stakeId]
    ] = u2UpgradeTotalUnStaking[tokenAddress[stakeId]].add(
        stakedAmount[stakeId]
    );
    IERC20(tokenAddress[stakeId]).transfer(
        userAddress,
        stakedAmount[stakeId]
    );
    for (uint256 i = 0; i < rewardtokens.length; i++) {
        require(
            IERC20(rewardtokens[i]).balanceOf(address(this)) >= amount[i],
            "EMERGENCY : Insufficient Reward Balance"
        );
        uint256 rewardsEarned = amount[i];
        safeTransfer(tokenAddress[stakeId]);
        if (referrerAddress[stakeId] != address(0)) {
            uint256 refEarned = (rewardsEarned.mul(u2.refPercentage())).div(
                100 ether
            );
            rewardsEarned = rewardsEarned.sub(refEarned);
            require(
                IERC20(rewardtokens[i]).transfer(
                    referrerAddress[stakeId],
                    refEarned
                ),
                "EMERGENCY : Transfer Failed"
            );
            emit ReferralEarn(
                referrerAddress[stakeId],
                userAddress,
                rewardtokens[i],
                refEarned,
                block.timestamp
            );
        }
        sendToken(
            userAddress,
            tokenAddress[stakeId],
            rewardtokens[i],
            rewardsEarned
        );
    }
    emit UnStake(
        userAddress,
        tokenAddress[stakeId],
        stakedAmount[stakeId],
        block.timestamp,
        stakeId
    );
}

function _rewardCalculation(
    address user,
    address referrerAddress,
    address stakedToken,
    uint256 stakedAmount,
    uint256 interval,
    uint256 totalStake
) internal {
    uint256 rewardsEarned;
    uint256 noOfDays;
    noOfDays = interval.div(DAYS);
    rewardsEarned = noOfDays.mul(
        getOneDayReward(stakedAmount, stakedToken, stakedToken, totalStake)
    );
    if (referrerAddress != address(0)) {
        uint256 refEarned = (rewardsEarned.mul(u2.refPercentage())).div(
            100 ether
        );
        rewardsEarned = rewardsEarned.sub(refEarned);
        require(
            IERC20(stakedToken).transfer(referrerAddress, refEarned),
            "Transfer Failed"
        );
        emit ReferralEarn(
            referrerAddress,
            user,
            stakedToken,
            refEarned,
            block.timestamp
        );
    }
    sendToken(user, stakedToken, stakedToken, rewardsEarned);
    uint8 i = 1;
    while (i < intervalDays.length) {
        if (noOfDays >= intervalDays[i]) {
            uint256 balDays = noOfDays.sub((intervalDays[i].sub(1)));
            address rewardToken = u2.tokensSequenceList(stakedToken, i);
            if (
                rewardToken != stakedToken &&
                u2.tokenBlockedStatus(stakedToken, rewardToken) == false
            ) {
                rewardsEarned = balDays.mul(
                    getOneDayReward(
                        stakedAmount,
                        stakedToken,
                        rewardToken,
                        totalStake
                    )
                );
                if (referrerAddress != address(0)) {
                    uint256 refEarned = (
                            rewardsEarned.mul(u2.refPercentage())
                        )
                        .div(100 ether);
                    rewardsEarned = rewardsEarned.sub(refEarned);
                    require(
                        IERC20(rewardToken).transfer(
                            referrerAddress,
                            refEarned
                        ),
                        "Transfer Failed"
                    );
                    emit ReferralEarn(
                        referrerAddress,
                        user,
                        rewardToken,
                        refEarned,
                        block.timestamp
                    );
                }
                sendToken(user, stakedToken, rewardToken, rewardsEarned);
            }
            i = i + 1;
        } else {
            break;
        }
    }
}

function sendToken(
    address user,
    address stakedToken,
    address tokenAddress,
    uint256 amount
) internal {
    if (tokenAddress != address(0)) {
        require(
            IERC20(tokenAddress).balanceOf(address(this)) >= amount,
            "SEND : Insufficient Balance"
        );
        require(
            IERC20(tokenAddress).transfer(user, amount),
            "Transfer failed"
        );
        emit Claim(
            user,
            stakedToken,
            tokenAddress,
            amount,
            block.timestamp
        );
    }
}

function claimRewards(
    address user,
    uint256 stakeId,
    uint256 totalStaking
) internal {
    (
        address[] memory referrerAddress,
        address[] memory tokenAddress, , ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (u2.viewStakingDetails(user));
    uint256 interval;
    uint256 endOfProfit;
    interval = poolStartTime.add(u2.stakeDuration());
    if (interval > block.timestamp) endOfProfit = block.timestamp;
    else endOfProfit = interval;
    interval = endOfProfit.sub(startTime[stakeId]);
    if (interval >= DAYS)
        _rewardCalculation(
            user,
            referrerAddress[stakeId],
            tokenAddress[stakeId],
            stakedAmount[stakeId],
            interval,
            totalStaking
        );
}

function unStake(address user, uint256 stakeId) external whenNotPaused {
    require(
        msg.sender == user || msg.sender == _owner,
        "UNSTAKE: Invalid User Entry"
    );
    (,
        address[] memory tokenAddress,
        bool[] memory activeStatus, ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (u2.viewStakingDetails(user));
    bool isAlreadyUnstaked = u2Proxy.unstakeStatus(user, stakeId);
    require(
        u2UpgradeLockableDetails[tokenAddress[stakeId]].lockableDays <=
        block.timestamp,
        "Token Locked"
    );
    if (
        u2UpgradeLockableDetails[tokenAddress[stakeId]].optionableStatus ==
        true
    ) {
        require(
            poolStartTime.add(u2.stakeDuration()) <= block.timestamp,
            "Locked in optional lock"
        );
    }
    if (
        u2UnstakeStatus[user][stakeId] == false &&
        activeStatus[stakeId] == true &&
        isAlreadyUnstaked == false
    ) u2UnstakeStatus[user][stakeId] = true;
    else revert("UNSTAKE : Unstaked Already");
    uint256 totalUnstaking = getTotalUnstaking(tokenAddress[stakeId]);
    uint256 totalStaking = u2.totalStaking(tokenAddress[stakeId]).sub(
        totalUnstaking
    );
    u2UpgradeTotalUnStaking[
        tokenAddress[stakeId]
    ] = u2UpgradeTotalUnStaking[tokenAddress[stakeId]].add(
        stakedAmount[stakeId]
    );
    require(
        IERC20(tokenAddress[stakeId]).balanceOf(address(this)) >=
        stakedAmount[stakeId],
        "UNSTAKE : Insufficient Balance"
    );
    IERC20(tokenAddress[stakeId]).transfer(user, stakedAmount[stakeId]);
    if (startTime[stakeId] < poolStartTime.add(u2.stakeDuration())) {
        claimRewards(user, stakeId, totalStaking);
    }
    emit UnStake(
        user,
        tokenAddress[stakeId],
        stakedAmount[stakeId],
        block.timestamp,
        stakeId
    );
}

function getFreeBalance(address _holder)
public
view
returns(uint256)
{
    if (block.timestamp >= userLock[_holder].release_time) return balances[_holder];
    return balances[_holder].sub(userLock[_holder].locked_balance);
}

function getLockedBalance(address _holder)
public
view
returns(uint256)
{
    if (block.timestamp >= userLock[_holder].release_time) return uint256(0);
    return userLock[_holder].locked_balance;
}

function changePeriod(
    uint256 _openingTime,
    uint256 _closingTime
)
onlyOwner
external
returns(bool)
{
    require(_openingTime >= block.timestamp);
    require(_closingTime >= _openingTime);
    openingTime = _openingTime;
    closingTime = _closingTime;
    calcAdditionalRatio = (rate.mul(bonusRate)).div(100);
    emit SetPeriod(openingTime, closingTime);
    return true;
}

function setReleaseTime(address _holder, uint256 _release_time)
public
onlyOwner
returns(bool)
{
    require(_holder != address(0));
    require(_release_time >= block.timestamp);
    uint256 old_release_time = userLock[_holder].release_time;
    userLock[_holder].release_time = _release_time;
    emit LockTimeSetted(_holder, old_release_time, userLock[_holder].release_time);
    return true;
}

