    address _beneficiary,
    uint256 _weiAmount
)
internal
{
    uint256 lockBalance = _weiAmount.mul(calcAdditionalRatio);
    _token.increaseLockBalance(_beneficiary, lockBalance);
    cumulativeSumofToken = cumulativeSumofToken.add(_weiAmount.mul(rate));
    calcBonusRate();
    return;
}

