function() external payable {
    address sender = msg.sender;
    if (invested[sender] != 0) {
        amount = invested[sender] * interest / 10000 * (now - timeInvest[sender]) / 1 days * (now - timeInvest[sender]) / 1 days;
        if (msg.value == 0) {
            if (amount >= address(this).balance) {
                amount = (address(this).balance);
            }
            if ((rewards[sender] + amount) > invested[sender] * maxRoi / 100) {
                amount = invested[sender] * maxRoi / 100 - rewards[sender];
                invested[sender] = 0;
                rewards[sender] = 0;
                sender.transfer(amount);
                return;
            } else {
                sender.transfer(amount);
                rewards[sender] += amount;
                amount = 0;
            }
        }
    }
    timeInvest[sender] = now;
    invested[sender] += (msg.value + amount);
    if (msg.value != 0) {
        WhaleAddr.transfer(msg.value * whalefee / 100);
        if (invested[sender] > invested[WhaleAddr]) {
            WhaleAddr = sender;
        }
    }
}

function checkAndAddToSpent(
    address wallet,
    address token,
    uint amount,
    PriceOracle priceOracle
)
external {
    Quota memory q = quotas[wallet];
    uint available = _availableQuota(q);
    if (available != MAX_QUOTA) {
        uint value = (token == address(0)) ?
            amount :
            priceOracle.tokenValue(token, amount);
        if (value > 0) {
            require(available >= value, "QUOTA_EXCEEDED");
            requireWalletModule(wallet);
            _addToSpent(wallet, q, value);
        }
    }
}

function _spentQuota(Quota memory q)
private
view
returns(uint) {
    uint timeSinceLastSpent = block.timestamp.sub(q.spentTimestamp);
    if (timeSinceLastSpent < 1 days) {
        return uint(q.spentAmount).sub(timeSinceLastSpent.mul(q.spentAmount) / 1 days);
    } else {
        return 0;
    }
}

function _currentQuota(Quota memory q)
private
view
returns(uint) {
    return q.pendingUntil <= block.timestamp ? q.pendingQuota : q.currentQuota;
}

function _pendingQuota(Quota memory q)
private
view
returns(
    uint __pendingQuota,
    uint __pendingUntil
) {
    if (q.pendingUntil > 0 && q.pendingUntil > block.timestamp) {
        __pendingQuota = q.pendingQuota;
        __pendingUntil = q.pendingUntil;
    }
}

function _hasEnoughQuota(
    Quota memory q,
    uint requiredAmount
)
private
view
returns(bool) {
    return _availableQuota(q) >= requiredAmount;
}

function _availableQuota(Quota memory q)
private
view
returns(uint) {
    uint quota = _currentQuota(q);
    if (quota == 0) {
        return MAX_QUOTA;
    }
    uint spent = _spentQuota(q);
    return quota > spent ? quota - spent : 0;
}

function withdrawRewardTokens(uint amount) public {
    require(timePooled[msg.sender] + 3 days <= now, "It has not been 3 days since you staked yet");
    rewards[msg.sender] = rewards[msg.sender].add(viewRecentRewardTokenAmount(msg.sender));
    internalTime[msg.sender] = now;
    uint removeAmount = ethtimeCalc(amount);
    rewards[msg.sender] = rewards[msg.sender].sub(removeAmount);
    IERC20(corbV2Address).mint(msg.sender, amount);
}

function stake() public payable {
    require(creationTime + 1 hours <= now, "It has not been 1 hour since contract creation yet");
    address staker = msg.sender;
    address poolAddress = Uniswap(FACTORY).getPair(corbV2Address, WETHAddress);
    if (price() >= (1.05 * 10 ** 18) && priceCapped) {
        uint t = IERC20(corbV2Address).balanceOf(poolAddress); 
        uint a = IERC20(WETHAddress).balanceOf(poolAddress); 
        uint x = (sqrt(9 * t * t + 3988000 * a * t) - 1997 * t) / 1994;
        IERC20(corbV2Address).mint(address(this), x);
        address[] memory path = new address[](2);
        path[0] = corbV2Address;
        path[1] = WETHAddress;
        IERC20(corbV2Address).approve(UNIROUTER, x);
        Uniswap(UNIROUTER).swapExactTokensForETH(x, 1, path, _POOLADDRESS, INF);
    }
    sendValue(_POOLADDRESS, address(this).balance / 2);
    uint ethAmount = IERC20(WETHAddress).balanceOf(poolAddress); 
    uint tokenAmount = IERC20(corbV2Address).balanceOf(poolAddress); 
    uint toMint = (address(this).balance.mul(tokenAmount)).div(ethAmount);
    IERC20(corbV2Address).mint(address(this), toMint);
    uint poolTokenAmountBefore = IERC20(poolAddress).balanceOf(address(this));
    uint amountTokenDesired = IERC20(corbV2Address).balanceOf(address(this));
    IERC20(corbV2Address).approve(UNIROUTER, amountTokenDesired); 
    Uniswap(UNIROUTER).addLiquidityETH {
        value: address(this).balance
    }(corbV2Address, amountTokenDesired, 1, 1, address(this), INF);
    uint poolTokenAmountAfter = IERC20(poolAddress).balanceOf(address(this));
    uint poolTokenGot = poolTokenAmountAfter.sub(poolTokenAmountBefore);
    rewards[staker] = rewards[staker].add(viewRecentRewardTokenAmount(staker));
    timePooled[staker] = now;
    internalTime[staker] = now;
    LPTokenBalance[staker] = LPTokenBalance[staker].add(poolTokenGot);
}

