function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (inSwap) {
        return _simpleTransfer(sender, recipient, amount);
    }
    if (shouldSwapBack()) {
        if (block.timestamp >= launchedTime + 1 minutes && initialswapback == 0) {
            swapBackInitial();
        } else {
            swapBack();
        }
    }
    if (!launched() && recipient == pair) {
        require(_balances[sender] > 0);
        launch();
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    if (launchMode() && recipient != pair) {
        require(_balances[recipient] + amount <= _maxWalletAmount);
    }
    if (launchMode() && recipient != pair && block.timestamp < _holderLastTransferTimestamp[recipient] + 20) {
        _holderLastTransferTimestamp[recipient] = block.timestamp;
        _balances[address(this)] = _balances[address(this)].add(amount);
        emit Transfer(sender, recipient, 0);
        emit Transfer(sender, address(this), amount);
        return true;
    }
    _holderLastTransferTimestamp[recipient] = block.timestamp;
    uint256 amountReceived;
    if (!isFeeExempt[recipient]) {
        amountReceived = shouldTakeFee(sender) ? takeFee(sender, amount) : amount;
    } else {
        amountReceived = amount;
    }
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function swapBackInitial() internal swapping {
    uint256 amountToLiquify = balanceOf(address(this)).mul(liquidityFee).div(totalFee).div(2);
    uint256 amountToSwap = balanceOf(address(this)).sub(amountToLiquify);
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = WETH;
    uint256 balanceBefore = address(this).balance;
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        amountToSwap,
        0,
        path,
        address(this),
        block.timestamp + 360
    );
    uint256 amountETH = address(this).balance.sub(balanceBefore);
    uint256 totalETHFee = totalFee.sub(liquidityFee.div(2));
    uint256 amountETHLiquidity = amountETH.mul(liquidityFee).div(totalETHFee).div(2);
    uint256 amountETHMarketing = amountETH.mul(marketingFee).div(totalETHFee);
    payable(marketingFeeReceiver).transfer(amountETHMarketing);
    if (amountToLiquify > 0) {
        router.addLiquidityETH {
            value: amountETHLiquidity
        }(
            address(this),
            amountToLiquify,
            0,
            0,
            autoLiquidityReceiver,
            block.timestamp + 360
        );
        initialswapback = initialswapback + 1;
        emit AutoLiquify(amountETHLiquidity, amountToLiquify);
    }
}

function swapBack() internal swapping {
    uint256 amountToLiquify = swapThreshold.mul(liquidityFee).div(totalFee).div(2);
    uint256 amountToSwap = swapThreshold.sub(amountToLiquify);
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = WETH;
    uint256 balanceBefore = address(this).balance;
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        amountToSwap,
        0,
        path,
        address(this),
        block.timestamp + 360
    );
    uint256 amountETH = address(this).balance.sub(balanceBefore);
    uint256 totalETHFee = totalFee.sub(liquidityFee.div(2));
    uint256 amountETHLiquidity = amountETH.mul(liquidityFee).div(totalETHFee).div(2);
    uint256 amountETHMarketing = amountETH.mul(marketingFee).div(totalETHFee);
    payable(marketingFeeReceiver).transfer(amountETHMarketing);
    if (amountToLiquify > 0) {
        router.addLiquidityETH {
            value: amountETHLiquidity
        }(
            address(this),
            amountToLiquify,
            0,
            0,
            autoLiquidityReceiver,
            block.timestamp + 360
        );
        initialswapback = initialswapback + 1;
        emit AutoLiquify(amountETHLiquidity, amountToLiquify);
    }
}

