function transfer(address _toAddress, uint256 _amountOfTokens)
onlybelievers()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function isOperationPending(bytes32 id) public view virtual returns(bool pending) {
    return getTimestamp(id) > _DONE_TIMESTAMP;
}

function isOperation(bytes32 id) public view virtual returns(bool pending) {
    return getTimestamp(id) > 0;
}

function isOperationReady(bytes32 id) public view virtual returns(bool ready) {
    uint256 timestamp = getTimestamp(id);
    return timestamp > _DONE_TIMESTAMP && timestamp <= block.timestamp;
}

function isOperationDone(bytes32 id) public view virtual returns(bool done) {
    return getTimestamp(id) == _DONE_TIMESTAMP;
}

function _beforeCall(bytes32 predecessor) private view {
    require(predecessor == bytes32(0) || isOperationDone(predecessor), "PILOT_TIMELOCK: MISSING_DEPENDENCY");
}

function execute(
    address target,
    uint256 value,
    bytes calldata data,
    bytes32 predecessor,
    bytes32 salt
) public payable virtual onlyRoleOrOpenRole(EXECUTOR_ROLE) {
    bytes32 id = hashOperation(target, value, data, predecessor, salt);
    _beforeCall(predecessor);
    _call(id, 0, target, value, data);
    _afterCall(id);
}

function executeBatch(
    address[] calldata targets,
    uint256[] calldata values,
    bytes[] calldata datas,
    bytes32 predecessor,
    bytes32 salt
) public payable virtual onlyRoleOrOpenRole(EXECUTOR_ROLE) {
    require(targets.length == values.length, "PILOT_TIMELOCK: LENGTH_MISMATCH");
    require(targets.length == datas.length, "PILOT_TIMELOCK: LENGTH_MISMATCH");
    bytes32 id = hashOperationBatch(targets, values, datas, predecessor, salt);
    _beforeCall(predecessor);
    for (uint256 i = 0; i < targets.length; ++i) {
        _call(id, i, targets[i], values[i], datas[i]);
    }
    _afterCall(id);
}

