function transferFrom(address _from, address _to, uint256 _value) stopInEmergency onlyPayloadSize(3) returns(bool ok) {
    require(!isOwner(_from) && _from != numerai); 
    require(balanceOf[_from] >= _value);
    require(allowance[_from][msg.sender] >= _value);
    balanceOf[_from] = safeSubtract(balanceOf[_from], _value);
    allowance[_from][msg.sender] = safeSubtract(allowance[_from][msg.sender], _value);
    balanceOf[_to] = safeAdd(balanceOf[_to], _value);
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) stopInEmergency onlyPayloadSize(2) returns(bool ok) {
    require(balanceOf[msg.sender] >= _value);
    balanceOf[msg.sender] = safeSubtract(balanceOf[msg.sender], _value);
    balanceOf[_to] = safeAdd(balanceOf[_to], _value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function calculateVestedTokens(
    uint256 tokens,
    uint256 time,
    uint256 start,
    uint256 cliff,
    uint256 vesting) constant returns(uint256) {
    if (time < cliff) return 0;
    if (time >= vesting) return tokens;
    uint256 vestedTokens = SafeMath.div(
        SafeMath.mul(
            tokens,
            SafeMath.sub(time, start)
        ),
        SafeMath.sub(vesting, start)
    );
    return vestedTokens;
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 12000000;
    } else {
        tokens = msg.value * 10000000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function claimTokens() whenNotPaused external {
    require(total_lock_amount[msg.sender] != 0, "User does not have lock record");
    require(total_lock_amount[msg.sender].sub(user_released[msg.sender]) > 0, "all token has been claimed");
    uint256 periods = block.timestamp.sub(start_time).div(1 days);
    uint256 total_release_amount = release_per_period[msg.sender].mul(periods);
    if (total_release_amount >= total_lock_amount[msg.sender]) {
        total_release_amount = total_lock_amount[msg.sender];
    }
    uint256 release_amount = total_release_amount.sub(user_released[msg.sender]);
    user_released[msg.sender] = total_release_amount;
    require(dpr.balanceOf(address(this)) >= release_amount, "MerkleClaim: Balance not enough");
    require(dpr.transfer(msg.sender, release_amount), "MerkleClaim: Transfer Failed");
    emit claim(msg.sender, release_amount);
}

function bid(uint256 _tokenId)
external
payable {
    address seller = tokenIdToAuction[_tokenId].seller;
    uint256 price = _bid(_tokenId, msg.value);
    _transfer(msg.sender, _tokenId);
    if (seller == address(nonFungibleContract)) {
        lastGen0SalePrices[gen0SaleCount % 5] = price;
        gen0SaleCount++;
    }
}

function createAuction(
    uint256 _tokenId,
    uint256 _price,
    address _seller
)
external
canBeStoredWith128Bits(_price) {
    require(msg.sender == address(nonFungibleContract));
    _escrow(_seller, _tokenId);
    Auction memory auction = Auction(
        _seller,
        uint128(_price),
        uint64(now)
    );
    _addAuction(_tokenId, auction);
}

function getCurrentPrice(uint256 _tokenId)
external
view
returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    return _currentPrice(auction);
}

function cancelAuction(uint256 _tokenId, address _seller)
external {
    require(msg.sender == address(nonFungibleContract));
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    address seller = auction.seller;
    require(_seller == seller);
    _cancelAuction(_tokenId, seller);
}

function getAuction(uint256 _tokenId)
external
view
returns
    (
        address seller,
        uint256 price,
        uint256 startedAt
    ) {
        Auction storage auction = tokenIdToAuction[_tokenId];
        require(_isOnAuction(auction));
        return (
            auction.seller,
            auction.price,
            auction.startedAt
        );
    }

function cancelAuctionWhenPaused(uint256 _tokenId)
external
whenPaused
onlyOwner {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    _cancelAuction(_tokenId, auction.seller);
}

function _bid(uint256 _tokenId, uint256 _bidAmount)
internal
returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    uint256 price = _currentPrice(auction);
    require(_bidAmount >= price);
    address seller = auction.seller;
    _removeAuction(_tokenId);
    if (price > 0) {
        uint256 auctioneerCut = _computeCut(price);
        uint256 sellerProceeds = price.sub(auctioneerCut);
        seller.transfer(sellerProceeds);
    }
    uint256 bidExcess = _bidAmount - price;
    msg.sender.transfer(bidExcess);
    emit AuctionSuccessful(_tokenId, price, msg.sender);
    return price;
}

