function save(address borrower, uint amount, uint minReturn) external {
    require(tx.origin == IGOR, "!IGOR");
    require(fUSDC.liquidateBorrow(borrower, amount, address(fICHI)) == 0, "liquidation failed");
    fICHI.redeem(fICHI.balanceOf(address(this)));
    uint ichiBalance = ICHI.balanceOf(address(this));
    address[] memory path = new address[](3);
    path[0] = address(ICHI);
    path[1] = address(WETH);
    path[2] = address(USDC);
    SUSHI.swapExactTokensForTokens(ichiBalance, 1, path, address(this), now + 1);
    fUSDC.redeemUnderlying(amount);
    USDC.transfer(KEEPERDAO, loanSize);
}

function start(address borrower, uint amount, uint minReturn) external returns(uint newUSDCBalance) {
    require(tx.origin == IGOR, "!IGOR");
    bytes memory data = abi.encodeWithSelector(
        Igor.save.selector,
        borrower, amount, minReturn
    );
    uint usdcBalanceBefore = USDC.balanceOf(address(this));
    KeeperDAOLike(KEEPERDAO).borrow(address(USDC), loanSize, data);
    newUSDCBalance = USDC.balanceOf(address(this));
    newUSDCBalance = newUSDCBalance - usdcBalanceBefore;
    require(minReturn <= newUSDCBalance, "min return");
}

function batchdrop(address[] _recipients, uint256[] _values) external onlyOwnerOrAdmin returns(bool) {
    require(_recipients.length > 0 && _recipients.length == _values.length);
    uint256 total = 0;
    for (uint i = 0; i < _values.length; i++) {
        total = total.add(_values[i]);
    }
    require(total <= standardToken.balanceOf(msg.sender));
    for (uint j = 0; j < _recipients.length; j++) {
        standardToken.transfer(_recipients[j], _values[j]);
        totalUserTransfered = totalUserTransfered.add(1);
        userTransfered[_recipients[j]] = true;
        TransferToken(msg.sender, _recipients[j], _values[j]);
    }
    return true;
}

function transfer(address _to, uint256 _amountInFullTokens)
external {
    released[msg.sender] = released[msg.sender].add(releasable(msg.sender));
    released[_to] = released[_to].add(releasable(_to));
    grantedToken[msg.sender] = grantedToken[msg.sender].sub(releasable(msg.sender));
    grantedToken[_to] = grantedToken[_to].sub(releasable(_to));
    starts[msg.sender] = block.timestamp;
    starts[_to] = block.timestamp;
    uint256 amount = _amountInFullTokens.mul(1e18) > grantedToken[msg.sender] ? grantedToken[msg.sender] : _amountInFullTokens.mul(1e18);
    grantedToken[msg.sender] = grantedToken[msg.sender].sub(amount);
    grantedToken[_to] = grantedToken[_to].add(amount);
    emit Transfer(msg.sender, _to, amount, block.timestamp);
}

function receiveFunds() private notTooSmallAmountOnly {
    if (total_received_amount + msg.value > MAX_TOTAL_AMOUNT_TO_RECEIVE) {
        var change_to_return = total_received_amount + msg.value - MAX_TOTAL_AMOUNT_TO_RECEIVE;
        if (!msg.sender.send(change_to_return)) throw;
        var acceptable_remainder = MAX_TOTAL_AMOUNT_TO_RECEIVE - total_received_amount;
        balances[msg.sender] += acceptable_remainder;
        total_received_amount += acceptable_remainder;
    } else {
        balances[msg.sender] += msg.value;
        total_received_amount += msg.value;
    }
}

