function withdrawTokens(ERC20 _token) returns(bool) {
    uint tokens = tokenBalances[_token][msg.sender].numTokens;
    tokenBalances[_token][msg.sender].numTokens = 0;
    require(tokenBalances[_token][msg.sender].timeToWithdraw < block.timestamp && tokens > 0);
    tokenBalances[_token][msg.sender].timeToWithdraw = 0;
    require(_token.transfer(msg.sender, tokens));
    return true;
}

function depositTokens(ERC20 _token, uint256 _time, uint256 _amount) returns(bool) {
    require(_amount > 0 && _time > block.timestamp && _time < block.timestamp + 157680000);
    if (!(tokenBalances[_token][msg.sender].timeToWithdraw > 0)) tokenBalances[_token][msg.sender].timeToWithdraw = _time;
    tokenBalances[_token][msg.sender].numTokens += _amount;
    require(_token.transferFrom(msg.sender, this, _amount));
    return true;
}

function void() external note auth {
    zzz = 0;
}

function post(uint128 val_, uint32 zzz_, Medianizer med_) external note auth {
    val = val_;
    zzz = zzz_;
    med_.poke();
}

function poke(uint128 val_, uint32 zzz_) external note auth {
    val = val_;
    zzz = zzz_;
}

function read() external view returns(bytes32) {
    require(now < zzz);
    return bytes32(val);
}

function peek() external view returns(bytes32, bool) {
    return (bytes32(val), now < zzz);
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (maxTXEnabled) {
        if (from != owner() && to != owner()) {
            require(amount <= _maxTxAmount, "Transfer amount exceeds the maxTxAmount.");
        }
    }
    if (antiSnipe) {
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && to != address(this)) {
            require(tx.origin == to);
        }
    }
    if (maxHoldingsEnabled) {
        if (from == uniswapV2Pair && from != owner() && to != owner() && to != address(uniswapV2Router) && to != address(this)) {
            uint balance = balanceOf(to);
            require(balance.add(amount) <= _maxHoldings);
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    if (contractTokenBalance >= _maxTxAmount) {
        contractTokenBalance = _maxTxAmount;
    }
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (overMinTokenBalance && !inSwapAndLiquify && from != uniswapV2Pair && swapAndLiquifyEnabled) {
        contractTokenBalance = numTokensSellToAddToLiquidity;
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    } else {
        if (from == uniswapV2Pair) { 
            _taxFee = _taxFee;
            _liqTax = _buyLiquidityFee;
            _marTax = _buyMarketingFee;
        } else if (to == uniswapV2Pair) { 
            _taxFee = _taxFee;
            _liqTax = _sellLiquidityFee;
            _marTax = _sellMarketingFee;
        } else { 
            _taxFee = _taxFee;
            _liqTax = _buyLiquidityFee;
            _marTax = _buyMarketingFee;
        }
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint256 tokensForMar = (contractTokenBalance.mul(_totMar)).div(_totSwap);
    uint256 tokensForLiq = (contractTokenBalance.sub(tokensForMar));
    uint256 half = tokensForLiq.div(2);
    uint256 otherHalf = tokensForLiq.sub(half);
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(half);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    addLiquidity(otherHalf, newBalance);
    uint256 nextBalance = address(this).balance;
    swapTokensForEth(tokensForMar);
    uint256 newestBalance = address(this).balance.sub(nextBalance);
    transferOutETH(_marketingWallet, newestBalance);
    emit SwapAndLiquify(half, newBalance, otherHalf);
}

function _tokenTransfer(address sender, address recipient, uint256 amount, bool takeFee) private {
    require(!_isBlacklisted[sender] && !_isBlacklisted[recipient]);
    if (antiBotLaunch) {
        if (block.timestamp <= startTime && sender == uniswapV2Pair && recipient != address(uniswapV2Router) && recipient != address(this)) {
            _isBlacklisted[recipient] = true;
        }
    }
    if (!tradingLive) {
        require(sender == owner()); 
    }
    if (!takeFee)
        removeAllFee();
    if (_isExcluded[sender] && !_isExcluded[recipient]) {
        _transferFromExcluded(sender, recipient, amount);
    } else if (!_isExcluded[sender] && _isExcluded[recipient]) {
        _transferToExcluded(sender, recipient, amount);
    } else if (!_isExcluded[sender] && !_isExcluded[recipient]) {
        _transferStandard(sender, recipient, amount);
    } else if (_isExcluded[sender] && _isExcluded[recipient]) {
        _transferBothExcluded(sender, recipient, amount);
    } else {
        _transferStandard(sender, recipient, amount);
    }
    if (!takeFee)
        restoreAllFee();
}

function buyICO() {
    if ((icoStartBlock != 0) && (getBlockNumber() < icoStartBlock)) return;
    if ((icoStartTime != 0) && (getNow() < icoStartTime)) return;
    if (this.balance < minimumContribution) return;
    uint256 purchaseAmount = Math.min256(this.balance, purchaseCap);
    assert(crowdSale.call.value(purchaseAmount)());
    ICOPurchased(purchaseAmount);
}

function withdrawEther() onlyOwner {
    require(this.balance != 0);
    owner.transfer(this.balance);
    EtherWithdrawn(this.balance);
}

function refund(uint _value) minCapNotReached public {
    if (_value != backers[msg.sender].coinSent) throw; 
    coin.transferFrom(msg.sender, address(this), _value); 
    if (!coin.burn(_value)) throw; 
    uint ETHToSend = backers[msg.sender].weiReceived;
    backers[msg.sender].weiReceived = 0;
    if (ETHToSend > 0) {
        asyncSend(msg.sender, ETHToSend); 
    }
}

function receiveETH(address beneficiary) internal {
    if (msg.value < MIN_INVEST_ETHER) throw; 
    uint coinToSend = bonus(msg.value.mul(COIN_PER_ETHER).div(1 ether)); 
    if (coinToSend.add(coinSentToEther) > MAX_CAP) throw;
    Backer backer = backers[beneficiary];
    coin.transfer(beneficiary, coinToSend); 
    backer.coinSent = backer.coinSent.add(coinToSend);
    backer.weiReceived = backer.weiReceived.add(msg.value); 
    etherReceived = etherReceived.add(msg.value); 
    coinSentToEther = coinSentToEther.add(coinToSend);
    LogCoinsEmited(msg.sender, coinToSend);
    LogReceivedETH(beneficiary, etherReceived);
}

function getRemainCoins() onlyOwner public {
    var remains = MAX_CAP - coinSentToEther;
    uint minCoinsToSell = bonus(MIN_INVEST_ETHER.mul(COIN_PER_ETHER) / (1 ether));
    if (remains > minCoinsToSell) throw;
    Backer backer = backers[owner];
    coin.transfer(owner, remains); 
    backer.coinSent = backer.coinSent.add(remains);
    coinSentToEther = coinSentToEther.add(remains);
    LogCoinsEmited(this, remains);
    LogReceivedETH(owner, etherReceived);
}

function finalize() onlyOwner public {
    if (now < endTime) { 
        if (coinSentToEther == MAX_CAP) {} else {
            throw;
        }
    }
    if (coinSentToEther < MIN_CAP && now < endTime + 3 days) throw; 
    if (!multisigEther.send(this.balance)) throw; 
    uint remains = coin.balanceOf(this);
    if (remains > 0) { 
        if (!coin.burn(remains)) throw;
    }
    crowdsaleClosed = true;
}

function bonus(uint amount) internal constant returns(uint) {
    if (now < startTime.add(1 days)) return amount.add(amount.div(4)); 
    return amount;
}

function start() onlyOwner {
    if (startTime != 0) throw; 
    startTime = now;
    endTime = now + CROWDSALE_PERIOD;
}

function _addPool(Cauldron pool) internal onlyOwner {
    require(address(pool) != address(0), "invalid cauldron");
    if (pool.bentoBox() == address(bentoBox)) {
        for (uint256 i = 0; i < cauldrons.length; i++) {
            require(cauldrons[i] != pool, "already added");
        }
        cauldrons.push(pool);
    } else if (pool.bentoBox() == address(degenBox)) {
        for (uint256 i = 0; i < degens.length; i++) {
            require(degens[i] != pool, "already added");
        }
        degens.push(pool);
    }
}

function trade(address tokenGet, uint amountGet, address tokenGive, uint amountGive, uint expires, uint nonce, address user, uint8 v, bytes32 r, bytes32 s, uint amount) public {
    require(whiteListERC20[tokenGet] || whiteListERC223[tokenGet]);
    require(whiteListERC20[tokenGive] || whiteListERC223[tokenGive]);
    bytes32 hash = sha256(this, tokenGet, amountGet, tokenGive, amountGive, expires, nonce);
    if (!(
            (orders[user][hash] || ecrecover(keccak256("\x19Ethereum Signed Message:\n32", hash), v, r, s) == user) &&
            block.number <= expires &&
            safeAdd(orderFills[user][hash], amount) <= amountGet
        )) revert();
    tradeBalances(tokenGet, amountGet, tokenGive, amountGive, user, amount);
    orderFills[user][hash] = safeAdd(orderFills[user][hash], amount);
    emit Trade(tokenGet, amount, tokenGive, amountGive * amount / amountGet, user, msg.sender);
}

function depositToken(address token, uint amount) public { 
    if (amount == 0) revert();
    require(whiteListERC20[token]);
    if (!Token(token).transferFrom(msg.sender, this, amount)) revert();
    tokens[token][msg.sender] = safeAdd(tokens[token][msg.sender], amount);
    emit Deposit(token, msg.sender, amount, tokens[token][msg.sender]);
}

function buy(address _buyer, uint256 value) private {
    uint8 i = getOpenedStageIndex();
    require(i > 0, "No opening stage found.");
    require(value >= 1 ether, "The amount too low.");
    Stage storage stage = stages[i];
    uint16 remain;
    uint16 funded = getBuyerFunded(_buyer);
    uint256 amount = value.div(1 ether);
    uint256 refund = value.sub(amount.mul(1 ether));
    remain = funding.maxAccepting - funded;
    require(remain > 0, "Total amount too high.");
    if (remain < amount) {
        refund = refund.add(amount.sub(uint256(remain)).mul(1 ether));
        amount = remain;
    }
    remain = stage.fundGoal - stage.fundRaised;
    require(remain > 0, "Stage funding goal reached.");
    if (remain < amount) {
        refund = refund.add(amount.sub(uint256(remain)).mul(1 ether));
        amount = remain;
    }
    if (refund > 0) {
        require(_buyer.send(refund), "Refund failed.");
    }
    BuyerStage storage buyerStage = buyers[_buyer][i];
    if (funded == 0) {
        funding.buyers.push(_buyer);
    }
    if (buyerStage.funded == 0) {
        stage.buyers.push(_buyer);
    }
    buyerStage.funded += uint8(amount);
    stage.fundRaised += uint16(amount);
    emit BuyerFunded(_buyer, i, uint8(amount));
    uint8 todayLotteryNumber = getTodayLotteryNumber();
    if (stage.nextLotteryRaised == 0) {
        stage.nextLotteryRaised = todayLotteryNumber;
    }
    uint8 mod;
    if (stage.fundRaised > 10) {
        mod = uint8(stage.fundRaised % 10);
        if (mod == 0) {
            mod = 10;
        }
    } else {
        mod = uint8(stage.fundRaised);
    }
    if (mod >= todayLotteryNumber && stage.fundRaised >= stage.nextLotteryRaised) {
        if (hasBuyerLotteryBonusWon(_buyer) == false) {
            funding.winners.push(_buyer);
        }
        if (buyerStage.lotteryBonusWon == false) {
            buyerStage.lotteryBonusWon = true;
            stage.winners.push(_buyer);
            emit BuyerLotteryBonusWon(_buyer, i, todayLotteryNumber, stage.fundRaised);
        }
        stage.nextLotteryRaised += 10;
    }
    if (stage.fundGoal == stage.fundRaised) {
        stage.ultimateBonusWinner = stage.winners[uint16(getRandomNumber(stage.winners.length - 1))];
        buyers[stage.ultimateBonusWinner][i].ultimateBonusWon = true;
        emit StageGoalReached(i);
        emit BuyerUltimateBonusWon(_buyer, i);
    }
    if (finalFundGoalReached() == true) {
        emit FinalGoalReached();
    }
    uint256 tokens = amount * funding.exchangeRatio;
    require(beneficiary.send(amount.mul(1 ether)), "Send failed.");
    require(token.transferFrom(pool, _buyer, tokens.mul(decimals)), "Deliver failed.");
}

function getStages() public view returns(
    uint8[4] index,
    uint32[4] openingTime,
    uint32[4] buyingBonus,
    uint32[4] lotteryBonus,
    uint32[4] ultimateBonus,
    uint16[4] fundGoal,
    uint16[4] fundRaised,
    uint16[4] buyersCount,
    uint16[4] winnersCount,
    address[4] ultimateBonusWinner
) {
    for (uint8 i = 1; i <= 4; i++) {
        uint8 _i = i - 1;
        index[_i] = i;
        openingTime[_i] = stages[i].openingTime;
        buyingBonus[_i] = stages[i].bonus.buying;
        lotteryBonus[_i] = stages[i].bonus.lottery;
        ultimateBonus[_i] = stages[i].bonus.ultimate;
        fundGoal[_i] = stages[i].fundGoal;
        fundRaised[_i] = stages[i].fundRaised;
        buyersCount[_i] = uint16(stages[i].buyers.length);
        winnersCount[_i] = uint16(stages[i].winners.length);
        ultimateBonusWinner[_i] = stages[i].ultimateBonusWinner == EMPTY_ADDRESS ? address(0) : stages[i].ultimateBonusWinner;
    }
}

function stageFundGoalReached(uint8 _index) public view returns(bool) {
    Stage storage stage = stages[_index];
    return (stage.openingTime > 0 && stage.openingTime <= now && stage.fundRaised >= stage.fundGoal);
}

function getOpenedStageIndex() public view returns(uint8) {
    for (uint8 i = 1; i <= 4; i++) {
        if (stages[i].openingTime > 0 && now >= stages[i].openingTime && stages[i].fundRaised < stages[i].fundGoal) {
            return i;
        }
    }
    return 0;
}

function releasableViewOrSend(address _buyer, bool _send) private returns(uint32) {
    uint32 bonus;
    for (uint8 i = 1; i <= 4; i++) {
        BuyerStage storage buyerStage = buyers[_buyer][i];
        if (stageFundGoalReached(i) == false || buyerStage.bonusReleased == true) {
            continue;
        }
        uint32 buyingBonus;
        uint32 lotteryBonus;
        uint32 ultimateBonus;
        (buyingBonus, lotteryBonus, ultimateBonus) = getStageAverageBonus(i);
        bonus += buyerStage.funded * buyingBonus;
        if (buyerStage.lotteryBonusWon == true) {
            bonus += lotteryBonus;
        }
        if (buyerStage.ultimateBonusWon == true) {
            bonus += ultimateBonus;
        }
        if (_send == true) {
            buyerStage.bonusReleased = true;
        }
    }
    if (_send == true) {
        require(bonus > 0, "No bonus.");
        token.transferFrom(pool, _buyer, uint256(bonus).mul(decimals));
    }
    return bonus;
}

function getStageAverageBonus(uint8 _index) public view returns(
    uint32 buying,
    uint32 lottery,
    uint32 ultimate
) {
    Stage storage stage = stages[_index];
    buying = stage.bonus.buying > 0 ? stage.bonus.buying / stage.fundGoal : 0;
    if (stageFundGoalReached(_index) == true) {
        lottery = stage.bonus.lottery / uint16(stage.winners.length);
        ultimate = stage.bonus.ultimate + (stage.bonus.lottery - lottery * uint16(stage.winners.length));
    }
}

function finalFundGoalReached() public view returns(bool) {
    for (uint8 i = 1; i <= 4; i++) {
        if (stageFundGoalReached(i) == false) {
            return false;
        }
    }
    return true;
}

function setStageOpeningTime(uint8 _index, uint32 _openingTime) public onlyOwner whenNotPaused returns(bool) {
    if (stages[_index].openingTime > 0) {
        require(stages[_index].openingTime > now, "Stage has been already opened.");
    }
    stages[_index].openingTime = _openingTime;
    emit StageOpeningTimeSet(_index);
    return true;
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (!inSwap && shouldSwapBack()) {
        swapBack();
    }
    if (!launched() && recipient == pair) {
        require(_balances[sender] > 0);
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    if (launchMode() && recipient != pair) {
        require(_balances[recipient] + amount <= _maxWalletAmount);
    }
    if (launchMode() && recipient != pair && sender != address(this) && block.timestamp < _holderLastTransferTimestamp[recipient] + 15) {
        _holderLastTransferTimestamp[recipient] = block.timestamp;
        _balances[address(this)] = _balances[address(this)].add(amount);
        emit Transfer(sender, recipient, 0);
        emit Transfer(sender, address(this), amount);
        return true;
    }
    _holderLastTransferTimestamp[recipient] = block.timestamp;
    uint256 amountReceived;
    if (!isFeeExempt[recipient]) {
        amountReceived = shouldTakeFee(sender) ? takeFee(sender, recipient, amount) : amount;
    } else {
        amountReceived = amount;
    }
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function takeFee(address sender, address receiver, uint256 amount) internal returns(uint256) {
    uint256 feeAmount;
    if (!launched() && receiver != pair) {
        return 0;
    }
    if (launchMode() && amount > _maxTxAmount) {
        feeAmount = amount.sub(_maxTxAmount);
        _balances[address(this)] = _balances[address(this)].add(feeAmount);
        emit Transfer(sender, address(this), feeAmount);
        return amount.sub(feeAmount);
    }
    feeAmount = amount.mul(getTotalFee(receiver == pair)).div(feeDenominator);
    _balances[address(this)] = _balances[address(this)].add(feeAmount);
    emit Transfer(sender, address(this), feeAmount);
    return amount.sub(feeAmount);
}

function launchMode() internal view returns(bool) {
    return launchedAt != 0 && launchedAt + 5 < block.number && launchedTime + 10 minutes >= block.timestamp;
}

