}

function updateShield(
    uint256 _newEthValue
)
external
payable {
    ShieldStats memory stats = shieldStats[msg.sender];
    require(stats.lastUpdate > 0, "Only arShields may access this function.");
    uint256 owed = getShieldOwed(msg.sender);
    uint256 unpaid = owed <= msg.value ?
        0 :
        owed - msg.value;
    totalEthValue = totalEthValue -
        uint256(stats.ethValue) +
        _newEthValue;
    checkpoint();
    shieldStats[msg.sender] = ShieldStats(
        uint128(cumCost),
        uint128(_newEthValue),
        uint128(block.timestamp),
        uint128(unpaid)
    );
}

function disburseClaim(
    address payable _shield,
    uint256 _amount
)
external
onlyGov {
    require(shieldStats[_shield].lastUpdate > 0 && IarShield(_shield).locked(), "Shield is not authorized to use this contract or shield is not locked.");
    _shield.transfer(_amount);
}

function checkCoverage(
    uint256 _newEthValue
)
public
view
returns(
    bool allowed
) {
    uint256 desired = (totalEthValue +
            _newEthValue -
            uint256(shieldStats[msg.sender].ethValue)) *
        coverPct /
        DENOMINATOR;
    allowed = ArmorCore.availableCover(protocol, desired) == desired;
}

function purchase(uint256 _stockId, uint256 _shareId) public payable {
    require(_stockId < stocks.length && _shareId < shares.length);
    Stock storage stock = stocks[_stockId];
    uint256[] storage sharesForStock = stockShares[_stockId];
    Share storage share = shares[sharesForStock[_shareId]];
    address previousHolder = share.holder;
    uint256 currentPrice = getPurchasePrice(
        share.purchasePrice,
        stock.priceIncrease
    );
    require(msg.value >= currentPrice);
    if (msg.value > currentPrice) {
        msg.sender.transfer(SafeMath.sub(msg.value, currentPrice));
    }
    uint256 dividendPerRecipient = getDividendPayout(
        currentPrice,
        stock.dividendAmount,
        sharesForStock.length - 1
    );
    uint256 previousHolderShare = SafeMath.sub(
        currentPrice,
        SafeMath.mul(dividendPerRecipient, sharesForStock.length - 1)
    );
    uint256 fee = SafeMath.div(previousHolderShare, 40);
    owner.transfer(fee);
    previousHolder.transfer(SafeMath.sub(previousHolderShare, fee));
    for (uint8 i = 0; i < sharesForStock.length; i++) {
        if (i != _shareId) {
            shares[sharesForStock[i]].holder.transfer(dividendPerRecipient);
            stock.dividendsPaid = SafeMath.add(stock.dividendsPaid, dividendPerRecipient);
            DividendPaid(
                shares[sharesForStock[i]].holder,
                dividendPerRecipient
            );
        }
    }
    ShareSold(
        _stockId,
        _shareId,
        share.purchasePrice,
        currentPrice,
        share.holder,
        msg.sender
    );
    share.holder = msg.sender;
    share.purchasePrice = currentPrice;
    stock.lastAction = block.timestamp;
}

function getCurrentPrice(
    uint256 _stockId,
    uint256 _shareId
) public view returns(uint256 currentPrice) {
    require(_stockId < stocks.length && _shareId < shares.length);
    currentPrice = SafeMath.div(
        SafeMath.mul(stocks[_stockId].priceIncrease, shares[_shareId].purchasePrice),
        100
    );
}

function buyTokens(address _beneficiary) internal whenNotPaused {
    uint256 weiAmount = msg.value;
    uint256 tokenAmount = getTokenAmount(weiAmount);
    preValidateChecks(_beneficiary, weiAmount, tokenAmount);
    tokensIssued = tokensIssued.add(tokenAmount);
    weiRaised = weiRaised.add(weiAmount);
    TOKEN.transferFrom(TOKEN_WALLET, _beneficiary, tokenAmount);
    FUNDS_WALLET.transfer(msg.value);
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokenAmount);
}

function preValidateChecks(address _beneficiary, uint256 _weiAmount, uint256 _tokenAmount) internal view {
    require(_beneficiary != address(0));
    require(_weiAmount != 0);
    require(now >= START_DATE);
    require(!closed);
    validateWhitelisted(_beneficiary);
    require(_tokenAmount >= MIN_TOKEN_INVEST);
    require(tokensIssued.add(_tokenAmount) <= MAX_TOKENS);
}

