function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e6);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function distributeAirdrop(address[] addresses, uint[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e6);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function withdraw() public returns(bool) {
    require(pendingReturns[msg.sender] > 0, "Nothing left for you");
    uint amount = pendingReturns[msg.sender];
    pendingReturns[msg.sender] = 0;
    msg.sender.transfer(amount);
    if (msg.sender == top) {
        loser = top;
        loserbid = topbid;
        top = 0;
        topbid = 0;
    }
    return true;
}

function callDefaultAction()
public
onlyPayerOrRecipient()
inState(State.Committed) {
    require(defaultAction != DefaultAction.None);
    require(now >= defaultTriggerTime);
    if (defaultAction == DefaultAction.Burn) {
        internalBurn(this.balance);
    } else if (defaultAction == DefaultAction.Release) {
        internalRelease(this.balance);
    }
    DefaultActionCalled();
}

function internalBurn(uint amount)
private
inState(State.Committed) {
    burnAddress.transfer(amount);
    amountBurned += amount;
    FundsBurned(amount);
    if (this.balance == 0) {
        state = State.Expended;
        Expended();
    }
}

function internalRelease(uint amount)
private
inState(State.Committed) {
    recipient.transfer(amount);
    amountReleased += amount;
    FundsReleased(amount);
    if (this.balance == 0) {
        state = State.Expended;
        Expended();
    }
}

function isLocked() view public returns(bool) {
    return (now < unlocktime && !manualUnlock);
}

function checkAvailableTokens(address _recipient) public view returns(uint256) {
    require(buyers[_recipient]);
    uint256 _availableTokens = 0;
    if (now >= step1) {
        _availableTokens = _availableTokens.add(allocations1[_recipient]);
    }
    if (now >= step2) {
        _availableTokens = _availableTokens.add(allocations2[_recipient]);
    }
    if (now >= step3) {
        _availableTokens = _availableTokens.add(allocations3[_recipient]);
    }
    return _availableTokens;
}

function distributeTokens(address _recipient) public {
    require(now >= step1);
    require(buyers[_recipient]);
    bool _lastWithdraw = false;
    uint256 _availableTokens = 0;
    if (now >= step1 && now >= step2 && now >= step3) {
        _availableTokens = _availableTokens.add(allocations3[_recipient]);
        _availableTokens = _availableTokens.add(allocations2[_recipient]);
        _availableTokens = _availableTokens.add(allocations1[_recipient]);
        allocations3[_recipient] = 0;
        allocations2[_recipient] = 0;
        allocations1[_recipient] = 0;
        _lastWithdraw = true;
    } else if (now >= step1 && now >= step2) {
        _availableTokens = _availableTokens.add(allocations2[_recipient]);
        _availableTokens = _availableTokens.add(allocations1[_recipient]);
        allocations2[_recipient] = 0;
        allocations1[_recipient] = 0;
    } else if (now >= step1) {
        _availableTokens = allocations1[_recipient];
        allocations1[_recipient] = 0;
    }
    require(_availableTokens > 0);
    require(token.balanceOf(this) >= _availableTokens);
    require(token.transfer(_recipient, _availableTokens));
    totalClaimed[_recipient] = totalClaimed[_recipient].add(_availableTokens);
    grandTotalClaimed = grandTotalClaimed.add(_availableTokens);
    emit LogTokenClaimed(_recipient, _availableTokens, allocationsTotal[_recipient], grandTotalClaimed);
    if (_lastWithdraw) {
        buyersReceived[_recipient] = true;
    }
}

constructor(uint256 _step1, uint256 _step2, uint256 _step3, ERC20 _token) public {
    require(_token != address(0));
    require(_step1 >= now);
    require(_step2 >= _step1);
    require(_step3 >= _step2);
    step1 = _step1;
    step2 = _step2;
    step3 = _step3;
    token = _token;
}

function finishICO(address _team, address _foundation, address _bounty) external onlyOwner {
    uint issuedTokenSupply = token.totalSupply();
    uint bountyTokens = issuedTokenSupply.mul(bountyPercent).div(100);
    uint foundationTokens = issuedTokenSupply.mul(foundationPercent).div(100);
    uint teamTokens = issuedTokenSupply.mul(teamPercent).div(100);
    bounty = _bounty;
    foundation = _foundation;
    team = _team;
    token.mint(bounty, bountyTokens);
    token.mint(foundation, foundationTokens);
    token.mint(team, teamTokens);
    token.finishMinting();
}

function createTokens() public payable {
    uint tokens = 0;
    uint bonusTokens = 0;
    if (now > PresaleStart && now < PresaleStart + PresalePeriod) {
        tokens = rate.mul(msg.value);
        bonusTokens = tokens.div(4);
    } else if (now > CrowdsaleStart && now < CrowdsaleStart + CrowdsalePeriod) {
        tokens = rate.mul(msg.value);
        if (now < CrowdsaleStart + CrowdsalePeriod / 4) {
            bonusTokens = tokens.mul(15).div(100);
        } else if (now >= CrowdsaleStart + CrowdsalePeriod / 4 && now < CrowdsaleStart + CrowdsalePeriod / 2) {
            bonusTokens = tokens.div(10);
        } else if (now >= CrowdsaleStart + CrowdsalePeriod / 2 && now < CrowdsaleStart + CrowdsalePeriod * 3 / 4) {
            bonusTokens = tokens.div(20);
        }
    }
    tokens += bonusTokens;
    if (tokens > 0) {
        token.mint(msg.sender, tokens);
    }
}

