function levelUp(uint256 _id,
    uint16 _attackLevelUp,
    uint16 _defenseLevelUp,
    uint16 _hpLevelUp,
    uint16 _speedLevelUp,
    uint16 _criticalRateLevelUp,
    uint16 _flexiGemsLevelUp) external payable whenNotPaused onlyOwnerOf(_id) {
    require(
        _attackLevelUp >= 0 &&
        _defenseLevelUp >= 0 &&
        _hpLevelUp >= 0 &&
        _speedLevelUp >= 0 &&
        _criticalRateLevelUp >= 0 &&
        _flexiGemsLevelUp >= 0, "level up attributes must be more than 0"
    ); 
    require(msg.value == upgradeFee, "fee must be equals to upgrade price"); 
    Card storage card = cards[_id];
    require(card.currentExp == card.expToNextLevel, "exp is not max yet for level up"); 
    require(card.level < 65535, "card level maximum has reached"); 
    require((card.criticalRate + (_criticalRateLevelUp * gemCriticalRateConversion)) <= 7000, "critical rate max of 70 has reached"); 
    uint totalInputGems = _attackLevelUp + _defenseLevelUp + _hpLevelUp;
    totalInputGems += _speedLevelUp + _criticalRateLevelUp + _flexiGemsLevelUp;
    uint16 numOfSpecials = 0;
    if ((card.level > 1) && (card.attack == 1) && (card.defense == 1) && (card.hp == 3) && (card.speed == 1) && (card.criticalRate == 25) && (card.flexiGems == 1)) {
        numOfSpecials = (card.level + 1) / 5; 
        uint totalGems = (numOfSpecials * upgradeGemsSpecial) + (((card.level) - numOfSpecials) * upgradeGems);
        require(totalInputGems == totalGems, "upgrade gems not used up"); 
    } else {
        if (((card.level + 1) % 5) == 0) { 
            require(totalInputGems == upgradeGemsSpecial, "upgrade gems not used up"); 
            numOfSpecials = 1;
        } else {
            require(totalInputGems == upgradeGems, "upgrade gems not used up"); 
        }
    }
    totalDeveloperCut = totalDeveloperCut.add(upgradeFee);
    _upgradeLevel(_id, _attackLevelUp, _defenseLevelUp, _hpLevelUp, _speedLevelUp, _criticalRateLevelUp, _flexiGemsLevelUp, numOfSpecials);
    emit LevelUp(_id);
}

function _transferFees(uint256 _challengerCardId, uint[] stats, uint256 developerFee) private returns(uint256 totalGained) {
    totalDeveloperCut = totalDeveloperCut.add(developerFee);
    uint256 remainFee = msg.value.sub(developerFee); 
    totalGained = 0;
    if (stats[7] == 1) { 
        rankTokens[stats[10]] = rankTokens[stats[10]].add(remainFee);
        totalRankTokens = totalRankTokens.add(remainFee);
    } else { 
        address challengerAddress = hogsmashToken.ownerOf(_challengerCardId); 
        if (stats[7] == 0) { 
            if (stats[9] > stats[10]) { 
                if (rankTokens[stats[10]] > 0) {
                    totalGained = totalGained.add(rankTokens[stats[10]]);
                    totalRankTokens = totalRankTokens.sub(rankTokens[stats[10]]);
                    rankTokens[stats[10]] = 0;
                }
                if (rankTokens[stats[9]] > 0) {
                    totalGained = totalGained.add(rankTokens[stats[9]]);
                    totalRankTokens = totalRankTokens.sub(rankTokens[stats[9]]);
                    rankTokens[stats[9]] = 0;
                }
            } else { 
                if (stats[9] < 50) { 
                    if ((stats[10] < 150) && (rankTokens[stats[10]] > 0)) { 
                        totalGained = totalGained.add(rankTokens[stats[10]]);
                        totalRankTokens = totalRankTokens.sub(rankTokens[stats[10]]);
                        rankTokens[stats[10]] = 0;
                    }
                    if ((stats[10] < 150) && (rankTokens[stats[9]] > 0)) { 
                        totalGained = totalGained.add(rankTokens[stats[9]]);
                        totalRankTokens = totalRankTokens.sub(rankTokens[stats[9]]);
                        rankTokens[stats[9]] = 0;
                    }
                }
            }
            challengerAddress.transfer(totalGained.add(remainFee)); 
        } else { 
            challengerAddress.transfer(remainFee); 
        }
    }
}

function generateInitialCard(uint16 _cardLevel) external whenNotPaused onlyOwner returns(uint256) {
    require(address(marketplace) != address(0), "marketplace not set"); 
    require(_cardLevel <= 20, "maximum level cannot exceed 20"); 
    hogsmashToken.setApprovalForAllByContract(msg.sender, marketplace, true); 
    return _createCard(msg.sender, _cardLevel); 
}

function _createCard(address _to, uint16 _initLevel) private returns(uint256) {
    require(_to != address(0), "cannot create card for unknown address"); 
    currentElement += 1;
    if (currentElement == 4) {
        currentElement = 8;
    }
    if (currentElement == 10) {
        currentElement = 1;
    }
    uint256 tempExpLevel = _initLevel;
    if (tempExpLevel > expToNextLevelArr.length) {
        tempExpLevel = expToNextLevelArr.length; 
    }
    uint32 tempCurrentExp = 0;
    if (_initLevel > 1) { 
        tempCurrentExp = expToNextLevelArr[tempExpLevel];
    }
    uint256 tokenId = hogsmashToken.mint(_to);
    Card memory _card = Card({
        element: currentElement, 
        level: _initLevel, 
        attack: 1, 
        defense: 1, 
        hp: 3, 
        speed: 1, 
        criticalRate: 25, 
        flexiGems: 1, 
        currentExp: tempCurrentExp, 
        expToNextLevel: expToNextLevelArr[tempExpLevel], 
        cardHash: generateHash(),
        createdDatetime: uint64(now),
        rank: tokenId 
    });
    cards[tokenId] = _card;
    ranking.push(tokenId); 
    emit CardCreated(msg.sender, tokenId);
    return tokenId;
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + 3 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            sellLiquidityFee = defaultSellLiquidityFee;
            sellTxFee = defaultSellTxFee;
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            if (cooldownEnabled) {
                require(cooldown[to] < block.timestamp);
                cooldown[to] = block.timestamp + (30 seconds);
            }
            if (useBuyMap && _buyMap[to] == 0) {
                _buyMap[to] = block.timestamp;
            }
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

function tokensale(address recipient) public payable {
    require(recipient != 0x0);
    if (now < pre_endTime) {
        ico_stage = STAGE_PRE_ICO;
    } else {
        ico_stage = STAGE_MAIN_ICO;
    }
    if (fundRaised >= _presaleSupply) {
        ico_stage = STAGE_MAIN_ICO;
    }
    uint256 weiAmount = msg.value;
    uint tokens = weiAmount.mul(getPrice());
    require(_icoSupply >= tokens);
    balances[token_addr] = balances[token_addr].sub(tokens);
    balances[recipient] = balances[recipient].add(tokens);
    _icoSupply = _icoSupply.sub(tokens);
    fundRaised = fundRaised.add(tokens);
    TokenPurchase(msg.sender, recipient, weiAmount, tokens);
    if (tokens == 0) {
        recipient.transfer(msg.value);
    } else {
        eth_addr.transfer(msg.value);
    }
}

function refundWhenNotClosed(address contributor) public onlyOwner whenNotPaused returns(uint256 weiRefunded) {
    require(state != State.Closed);
    uint256 depositedValue = deposited[contributor];
    deposited[contributor] = 0;
    uint256 refundFees = depositedValue.div(100);
    uint256 refundValue = depositedValue.sub(refundFees);
    if (refundFees > 0)
        wallet.transfer(refundFees);
    if (refundValue > 0)
        contributor.transfer(refundValue);
    Refunded(contributor, depositedValue);
    return depositedValue;
}

function myRefund(address investor) public onlyOwner whenNotPaused returns(uint256 refunedValue) {
    require(state == State.Refunding);
    uint256 depositedValue = deposited[investor];
    deposited[investor] = 0;
    investor.transfer(depositedValue);
    Refunded(investor, depositedValue);
    return depositedValue;
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    affWallet.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function createListing(address tokenContractAddress, uint256 price, uint256 allowance, uint256 dateEnds, uint256 salt) external {
    require(price > 0, "price less than zero");
    require(allowance > 0, "allowance less than zero");
    require(dateEnds > 0, "dateEnds less than zero");
    require(getBalance(tokenContractAddress, msg.sender) >= allowance, "balance less than allowance");
    bytes32 listingId = getHashInternal(tokenContractAddress, price, allowance, dateEnds, salt);
    Listing memory listing = Listing(msg.sender, tokenContractAddress, price, allowance, now, dateEnds);
    listings[listingId] = listing;
    emit ListingCreated(listingId, tokenContractAddress, price, allowance, now, dateEnds, msg.sender);
}

function buyListing(bytes32 listingId, uint256 amount) external payable {
    Listing storage listing = listings[listingId];
    address seller = listing.seller;
    address contractAddress = listing.tokenContractAddress;
    uint256 price = listing.price;
    uint256 decimals = getDecimals(listing.tokenContractAddress);
    uint256 factor = 10 ** decimals;
    uint256 sale;
    if (decimals > 0) {
        sale = price.mul(amount).div(factor);
    } else {
        sale = price.mul(amount);
    }
    uint256 allowance = listing.allowance;
    require(now <= listing.dateEnds);
    require(allowance - sold[listingId] >= amount);
    require(getBalance(contractAddress, seller) >= amount);
    require(getAllowance(contractAddress, seller, this) >= amount);
    require(msg.value == sale);
    DetailedERC20 tokenContract = DetailedERC20(contractAddress);
    require(tokenContract.transferFrom(seller, msg.sender, amount));
    if (ownerPercentage > 0) {
        seller.transfer(sale - (sale.mul(ownerPercentage).div(10000)));
    } else {
        seller.transfer(sale);
    }
    sold[listingId] = sold[listingId].add(amount);
    emit ListingBought(listingId, contractAddress, price, amount, now, msg.sender);
}

function cancelListing(bytes32 listingId) external {
    Listing storage listing = listings[listingId];
    require(msg.sender == listing.seller);
    delete listings[listingId];
    emit ListingCancelled(listingId, now);
}

function claimTeamToken() external {
    require(msg.sender == TEAM_ACCOUNT);
    require(now >= icoEndTime.add(TEAM_CAN_CLAIM_AFTER));
    require(teamReserve[20] > 0);
    uint claimableTime = icoEndTime.add(TEAM_CAN_CLAIM_AFTER);
    uint totalClaimable;
    for (uint i = 0; i < 21; i++) {
        if (teamReserve[i] > 0) {
            if (claimableTime.add(i.mul(CLAIM_STAGE)) < now) {
                totalClaimable = totalClaimable.add(teamReserve[i]);
                teamReserve[i] = 0;
            } else {
                break;
            }
        }
    }
    if (totalClaimable > 0) {
        mint(TEAM_ACCOUNT, totalClaimable);
    }
}

