}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    uint256 tmpRestrictedDate;
    if (restrictedTokens[msg.sender] > 0) {
        require((now < tmpRestrictedDate && _value <= (balances[msg.sender] - restrictedTokens[msg.sender])) || now >= tmpRestrictedDate); 
    }
    if (balances[_to] == 0) addAddress(_to);
    super.transferFrom(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    uint256 tmpRestrictedDate;
    if (restrictedTokens[msg.sender] > 0) {
        require((now < tmpRestrictedDate && _value <= (balances[msg.sender].sub(restrictedTokens[msg.sender]))) || now >= tmpRestrictedDate); 
    }
    if (balances[_to] == 0) addAddress(_to);
    _transfer(_to, _value);
    return true;
}

function updateStages() internal onlyInState(StatusList.Running) {
    if (now <= endPrivateICO && now > startPrivateICO) {
        stage = StagesList.PrivateICO;
        return;
    } 
    if (now <= endPreICO && now > startPreICO) {
        stage = StagesList.PreICO;
        return;
    } 
    if (now <= endICO_w1 && now > startICO_w1) {
        stage = StagesList.ICO_w1;
        return;
    } 
    if (now <= endICO_w2 && now > startICO_w2) {
        stage = StagesList.ICO_w2;
        return;
    } 
    stage = StagesList.N_A;
}

function underLimit(uint256 _value) internal returns(bool) {
    if (today() > lastDay_[msg.sender]) {
        spentToday_[msg.sender] = 0;
        lastDay_[msg.sender] = today();
    }
    if (spentToday_[msg.sender] + _value >= spentToday_[msg.sender] && spentToday_[msg.sender] + _value <= dailyLimit_) {
        spentToday_[msg.sender] += _value;
        return true;
    }
    return false;
}

