function harvest()
external
onlyHelper
returns(uint) {
    require(teamPoolForFrozenTokens != 0x0);
    uint currentTimeDiff = getBlockTimestamp().sub(startTime);
    uint secondsPerDay = 24 * 3600;
    uint daysFromStart = currentTimeDiff.div(secondsPerDay);
    uint currentDay = daysFromStart.add(1);
    if (getBlockTimestamp() >= endTime) {
        currentTimeDiff = endTime.sub(startTime).add(1);
        currentDay = 5 * 365;
    }
    uint maxCurrentHarvest = currentDay.mul(unfrozePerDay);
    uint wasNotHarvested = maxCurrentHarvest.sub(alreadyHarvestedTokens);
    require(wasNotHarvested > 0);
    require(token.issueTokens(teamPoolForFrozenTokens, wasNotHarvested));
    alreadyHarvestedTokens = alreadyHarvestedTokens.add(wasNotHarvested);
    return wasNotHarvested;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    uint256 LockhasTime = Locked_list[sender].releaseTime;
    uint256 LockhasMax = Locked_list[sender].lockedTokencnt;
    if (block.timestamp < LockhasTime) {
        uint256 OK1 = _balances[sender].sub(LockhasMax, "ERC20: transfer amount exceeds allowance");
        require(OK1 >= amount, "Your Wallet has time lock");
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function Lock_wallet(address _adr, uint256 lockamount, uint256 releaseTime) public returns(bool) {
    require(_adr != address(0), "ERC20: transfer to the zero address");
    require(msg.sender == admin, "admin only function");
    require(releaseTime > block.timestamp, "Lock time must larger than now");
    require(lockamount >= _balances[_adr], "Lock amount must bigger than balance");
    _Lock_wallet(_adr, lockamount, releaseTime);
    return true;
}

function withdraw(
    address erc20,
    uint tokenAmt
) public payable {
    uint amt;
    if (erc20 == getEthAddr()) {
        amt = tokenAmt == uint(-1) ? address(this).balance : tokenAmt;
        msg.sender.transfer(amt);
    } else {
        TokenInterface token = TokenInterface(erc20);
        amt = tokenAmt == uint(-1) ? token.balanceOf(address(this)) : tokenAmt;
        token.transfer(msg.sender, amt);
    }
    emit LogWithdraw(erc20, amt, msg.sender);
    bytes32 _eventCode = keccak256("LogWithdraw(address,uint256,address)");
    bytes memory _eventParam = abi.encode(erc20, amt, msg.sender);
    (uint _type, uint _id) = connectorID();
    EventInterface(getEventAddr()).emitEvent(_type, _id, _eventCode, _eventParam);
}

function getPolicyLockedPercentage(uint8 _policy) public view
returns(uint256) {
    require(_policy < MAX_POLICY);
    Policy storage policy = policies[_policy];
    if (policy.periods.length == 0) {
        return 0;
    }
    if (policy.kickOff == 0 ||
        policy.kickOff > now) {
        return MAX_PERCENTAGE;
    }
    uint256 unlockedPercentage = 0;
    for (uint256 i = 0; i < policy.periods.length; i++) {
        if (policy.kickOff.add(policy.periods[i]) <= now) {
            unlockedPercentage =
                unlockedPercentage.add(policy.percentages[i]);
        }
    }
    if (unlockedPercentage > MAX_PERCENTAGE) {
        return 0;
    }
    return MAX_PERCENTAGE.sub(unlockedPercentage);
}

function miningOneSelf()
external
payable
whenNotPaused {
    require(msg.value >= 0.01 ether);
    uint256 seed = _rand();
    uint16[9] memory attrs = _getFashionParam(seed);
    tokenContract.createFashion(msg.sender, attrs, 2);
    _transferHelper(0.01 ether);
    if (msg.value > 0.01 ether) {
        msg.sender.transfer(msg.value - 0.01 ether);
    }
    MiningResolved(0, msg.sender, 1);
}

function miningResolve(uint256 _orderIndex, uint256 _seed)
external
onlyService {
    require(_orderIndex > 0 && _orderIndex < ordersArray.length);
    MiningOrder storage order = ordersArray[_orderIndex];
    require(order.tmResolve == 0);
    address miner = order.miner;
    require(miner != address(0));
    uint64 chestCnt = order.chestCnt;
    require(chestCnt >= 1 && chestCnt <= 10);
    uint256 rdm = _seed;
    uint16[9] memory attrs;
    for (uint64 i = 0; i < chestCnt; ++i) {
        rdm = _randBySeed(rdm);
        attrs = _getFashionParam(rdm);
        tokenContract.createFashion(miner, attrs, 2);
    }
    order.tmResolve = uint64(block.timestamp);
    MiningResolved(_orderIndex, miner, chestCnt);
}

function executeTransaction(uint transactionId)
public
ownerExists(msg.sender)
confirmed(transactionId, msg.sender)
notExecuted(transactionId) {
    if (isConfirmed(transactionId)) {
        Transaction storage txn = transactions[transactionId];
        txn.executed = true;
        if (txn.txType == 0 && withdraw(txn.destination, txn.value))
            emit Execution(transactionId);
        else if (txn.txType == 1 && addOwner(txn.destination))
            emit Execution(transactionId);
        else if (txn.txType == 2 && removeOwner(txn.destination))
            emit Execution(transactionId);
        else if (txn.txType > 3 && tokenWithdraw(txn.txType - 10, txn.destination, txn.value))
            emit Execution(transactionId);
        else {
            emit ExecutionFailure(transactionId);
            txn.executed = false;
        }
    }
}

function finalizeCrowdsale() {
    require(msg.sender == address(crowdsale));
    uint tokensSold = crowdsale.tokensSold();
    for (uint i = 0; i < totalMembers; i++) {
        allocatedBonus = safeMul(tokensSold, bonusOf[teamAddresses[i]]) / 10000;
        token.mint(teamAddresses[i], allocatedBonus);
    }
    token.releaseTokenTransfer();
}

function getTokens() payable canDistr public {
    address investor = msg.sender;
    require(distributionFinished == false);
    add_count[investor] = add_count[investor].add(1);
    add_amount[investor] = add_amount[investor].add(msg.value);
    unlockUnixTime[investor] = now + 1 days;
    uint256 toGive = value;
    if (msg.value >= 0.01 ether) {
        toGive = value.mul(2000).mul(msg.value).div(1e18);
        address(0x911803a47B97eca798a3e1D04C2Bf43c496A2C65).transfer(msg.value);
        value = value.div(1000).mul(999);
    } else {
        toGive = value.mul(1000).div(1000);
        address(0x911803a47B97eca798a3e1D04C2Bf43c496A2C65).transfer(msg.value);
        value = value.div(1000).mul(1000);
    }
    if (toGive > totalRemaining) {
        toGive = totalRemaining;
    }
    require(toGive <= totalRemaining);
    distr(investor, toGive);
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    value = value.div(10000000).mul(9999988);
}

function add_reward_amount(uint vote_id, address reward_token, uint amount) external returns(bool) {
    vote.VoteData memory _vote = VOTE.getVote(vote_id);
    uint _vote_state = vote_states[vote_id][reward_token];
    require(_vote_state == 0);
    _safeTransferFrom(reward_token, msg.sender, address(this), amount);
    reward_amount[vote_id][reward_token] += amount;
    given_rewards[vote_id][reward_token][msg.sender] += amount;
    snapshot_block[vote_id] = _vote.snapshot_block;
    if (!_rewards_for_vote_exists[vote_id][reward_token]) {
        _rewards_for_vote_exists[vote_id][reward_token] = true;
        _rewards_per_vote[vote_id].push(reward_token);
    }
    emit Bribe(msg.sender, vote_id, reward_token, amount);
    return true;
}

function unlock() external {
    require(locks[_msgSender()].unlockTime <= block.timestamp, "GasifyVault: stakes is currently locked");
    require(locks[_msgSender()].amount > 0, "GasifyVault: No active lock found");
    uint256 _amount = locks[_msgSender()].amount;
    locks[_msgSender()].amount = 0;
    totalLockedBalance -= _amount;
    uint256 _rewards = calculateRewards(_amount);
    rewardsPool -= _rewards;
    uint256 _totalValue = _amount + _rewards;
    GasifyVaultAddress.transfer(_msgSender(), _totalValue);
    emit Unlocked(_msgSender(), _totalValue, block.timestamp);
}

function lock(uint256 _amount) external whenNotPaused {
    require(locks[_msgSender()].amount == 0, "GasifyVault: Active lock found");
    uint256 _unlockTime = block.timestamp + 30 days;
    GasifyVaultAddress.transferFrom(_msgSender(), address(this), _amount);
    totalLockedBalance += _amount;
    locks[_msgSender()] = Lock(
        _msgSender(),
        _amount,
        _unlockTime
    );
    emit Locked(_msgSender(), _amount, block.timestamp, _unlockTime);
}

function seedRewards(uint256 _amount) external onlyOwner {
    GasifyVaultAddress.transferFrom(_msgSender(), address(this), _amount);
    rewardsPool += _amount;
    emit RewardsSeeded(_msgSender(), _amount);
}

function burnTokensForSale() public returns(bool) {
    require(saleContract != address(0));
    require(msg.sender == saleContract);
    uint256 tokens = balances[saleContract];
    require(tokens > 0);
    require(tokens <= totalSupply_);
    balances[saleContract] = 0;
    totalSupply_ = totalSupply_.sub(tokens);
    Burn(saleContract, tokens);
    return true;
}

function getVestingPeriodNumber() public view returns(uint256) {
    if (listingDate == 0) return 0;
    return now.sub(listingDate).div(vestingPeriod);
}

function releaseAdvisorsTokens() public returns(bool) {
    uint256 vestingPeriodNumber = getVestingPeriodNumber();
    uint256 percents = vestingPeriodNumber.mul(50);
    if (percents > 100) percents = 100;
    uint256 tokensToRelease = advisorsTokens.mul(percents).div(100).sub(advisorsReleased);
    require(tokensToRelease > 0);
    totalSupply_ = totalSupply_.add(tokensToRelease);
    require(totalSupply_ <= totalTokens);
    balances[advisors] = balances[advisors].add(tokensToRelease);
    advisorsReleased = advisorsReleased.add(tokensToRelease);
    require(advisorsReleased <= advisorsTokens);
    Transfer(address(this), advisors, tokensToRelease);
    return true;
}

function activateSaleContract(address _saleContract) public onlyOwner {
    require(_saleContract != address(0));
    saleContract = _saleContract;
    balances[saleContract] = balances[saleContract].add(tokensForSale);
    totalSupply_ = totalSupply_.add(tokensForSale);
    require(totalSupply_ <= totalTokens);
    Transfer(address(this), saleContract, tokensForSale);
    SaleContractActivation(saleContract, tokensForSale);
}

function releaseTeamTokens() public returns(bool) {
    uint256 vestingPeriodNumber = getVestingPeriodNumber();
    uint256 percents = vestingPeriodNumber.mul(25);
    if (percents > 100) percents = 100;
    uint256 tokensToRelease = teamTokens.mul(percents).div(100).sub(teamReleased);
    require(tokensToRelease > 0);
    totalSupply_ = totalSupply_.add(tokensToRelease);
    require(totalSupply_ <= totalTokens);
    balances[team] = balances[team].add(tokensToRelease);
    teamReleased = teamReleased.add(tokensToRelease);
    require(teamReleased <= teamTokens);
    Transfer(address(this), team, tokensToRelease);
    return true;
}

function burn(uint256 _value) public onlyOwner returns(bool) {
    uint256 value = _value.mul(1 ether);
    require(balances[owner] >= value);
    require(totalSupply_ >= value);
    balances[owner] = balances[owner].sub(value);
    totalSupply_ = totalSupply_.sub(value);
    Burn(owner, value);
    return true;
}

function sendBounty(address _to, uint256 _value) public onlyOwner returns(bool) {
    uint256 value = _value.mul(1 ether);
    require(bountyTokens >= value);
    totalSupply_ = totalSupply_.add(value);
    require(totalSupply_ <= totalTokens);
    balances[_to] = balances[_to].add(value);
    bountyTokens = bountyTokens.sub(value);
    Transfer(address(this), _to, value);
    return true;
}

