function sendFounders() onlyOwner public {
    require(limitFounders < totalSupply / 20);
    if (timeFounders == 0x0 || timeFounders < now) {
        _transfer(owner, FOUNDERS_POOL_ADDR, totalSupply / 100);
        timeFounders = now + 365 days;
        limitFounders += totalSupply / 100;
    }
}

function sendIncentive() onlyOwner public {
    require(limitIncentive < totalSupply / 2);
    if (timeIncentive < now) {
        if (timeIncentive == 0x0) {
            _transfer(owner, INCENTIVE_POOL_ADDR, totalSupply / 10);
            limitIncentive += totalSupply / 10;
        } else {
            _transfer(owner, INCENTIVE_POOL_ADDR, totalSupply / 20);
            limitIncentive += totalSupply / 20;
        }
        timeIncentive = now + 365 days;
    }
}

function stake(uint256 amount) public {
    require(canStake, "function is disabled");
    require(amount > 0, "You cannot stake zero tokens");
    if (isStaking[msg.sender] == true) {
        parkedYeild[msg.sender] += calculateYieldTotal(msg.sender);
    }
    cosmicToken.transferFrom(msg.sender, address(this), amount);
    stakingBalance[msg.sender] += amount;
    ownBalance += amount;
    stakeStartTime[msg.sender] = block.timestamp;
    yeildStartTime[msg.sender] = block.timestamp;
    isStaking[msg.sender] = true;
    emit StakeEvent(msg.sender, amount, block.timestamp, State.stake);
}

function reInvestRewards() public {
    require(canReinvest, "function is disabled");
    uint256 toReinvest = calculateYieldTotal(msg.sender);
    if (parkedYeild[msg.sender] != 0) {
        toReinvest += parkedYeild[msg.sender];
        parkedYeild[msg.sender] = 0;
    }
    require(toReinvest > 0, "Nothing to reinvest");
    stakingBalance[msg.sender] += toReinvest;
    ownBalance += toReinvest;
    stakeStartTime[msg.sender] = block.timestamp;
    yeildStartTime[msg.sender] = block.timestamp;
    isStaking[msg.sender] = true;
    emit StakeEvent(msg.sender, toReinvest, block.timestamp, State.reinvest);
}

function withdrawYield() public {
    require(canYeild, "function is disabled");
    uint256 toTransfer = calculateYieldTotal(msg.sender);
    if (parkedYeild[msg.sender] != 0) {
        toTransfer += parkedYeild[msg.sender];
        parkedYeild[msg.sender] = 0;
    }
    require(toTransfer > 0, "Nothing to yeild");
    require((cosmicToken.balanceOf(address(this)) - ownBalance) >= toTransfer, "Insufficient pool");
    yeildStartTime[msg.sender] = block.timestamp;
    cosmicToken.transfer(msg.sender, toTransfer);
    emit StakeEvent(msg.sender, toTransfer, block.timestamp, State.yeildwithdraw);
}

function unstake(uint256 amount) public {
    require(canUnstake, "function is disabled");
    require((stakeStartTime[msg.sender] + lockTime) < block.timestamp, "cannot unstake untill your time completes");
    require(
        isStaking[msg.sender] = true &&
        stakingBalance[msg.sender] >= amount,
        "Nothing to unstake"
    );
    stakeStartTime[msg.sender] = block.timestamp;
    yeildStartTime[msg.sender] = block.timestamp;
    stakingBalance[msg.sender] -= amount;
    cosmicToken.transfer(msg.sender, amount);
    parkedYeild[msg.sender] += calculateYieldTotal(msg.sender);
    ownBalance -= amount;
    if (stakingBalance[msg.sender] == 0) {
        isStaking[msg.sender] = false;
    }
    emit StakeEvent(msg.sender, amount, block.timestamp, State.unstake);
}

function createTokens() isUnderHardCap saleIsOn payable {
    eth_addr.transfer(msg.value);
    uint tokens = rate.mul(msg.value).div(1 ether);
    uint bonusTokens = 0;
    if (now < start_ico + (period * 1 days).div(3)) {
        bonusTokens = tokens.div(5);
    } else {
        bonusTokens = 0;
    }
    tokens += bonusTokens;
    token.mint(msg.sender, tokens);
}

function buyTokens(address beneficiary) saleIsOn isUnderHardCap nonReentrant public payable {
    require(beneficiary != address(0) && msg.value != 0);
    uint256 weiAmount = msg.value;
    uint256 centValue = weiAmount.div(priceUSD);
    uint256 tokens = getTokenAmount(centValue);
    centRaised = centRaised.add(centValue);
    token.mint(beneficiary, tokens);
    balances[msg.sender] = balances[msg.sender].add(weiAmount);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds(weiAmount);
}

function manualTransfer(address _to, uint _valueUSD) public saleIsOn isUnderHardCap onlyOwnerOrManager {
    uint256 centValue = _valueUSD * 100;
    uint256 tokensAmount = getTokenAmount(centValue);
    centRaised = centRaised.add(centValue);
    token.mint(_to, tokensAmount);
    balancesInCent[_to] = balancesInCent[_to].add(centValue);
}

function getTokenAmount(uint256 _value) public view returns(uint256) {
    require(_value >= minimum);
    uint256 buy_time = now;
    uint256 numerator = 0;
    for (uint256 i = 0; i < discount_period.length; i++) {
        if (buy_time <= discount_period[i]) {
            numerator = discount[i];
            break;
        }
    }
    if (numerator == 0) {
        numerator = 100;
    }
    return _value.mul(rate).mul(numerator).div(100).div(wei_to_token);
}

function start() external onlyOwner returns(bool) {
    require(start_time == 0);
    uint256 time_point = now;
    start_time = time_point;
    end_time = time_point + period;
    for (uint256 i = 0; i < discount_period.length; i++) {
        time_point = time_point.add(discount_period[i]);
        discount_period[i] = time_point;
    }
    issuable = true;
    LogStarted(start_time);
    return true;
}

function canIssue(uint256 tokens) internal returns(bool) {
    if (start_time == 0 || end_time <= now) {
        issuable = false;
        return false;
    }
    if (token_issued.add(tokens) > balances[owner]) {
        issuable = false;
        return false;
    }
    return true;
}

function setDiscount(uint256[] _period, uint256[] _discount)
external
onlyVault
validArray(_period)
validArray(_discount)
returns(bool) {
    discount_period = _period;
    discount = _discount;
    period = 0;
    for (uint256 i = 0; i < discount_period.length; i++) {
        period = period.add(discount_period[i]);
    }
    if (start_time != 0) {
        uint256 time_point = now;
        start_time = time_point;
        end_time = time_point + period;
        uint256 tmp_time = time_point;
        for (i = 0; i < discount_period.length; i++) {
            tmp_time = tmp_time.add(discount_period[i]);
            discount_period[i] = tmp_time;
        }
    }
    LogDiscountSet(_period, _discount, time_point);
    return true;
}

function unfreezeAllAndClaim() public {
    unfreeze(users[msg.sender].balance);
    claimInternal();
}

function sendReward(address userAddress,
    uint256 stakeEarned, uint256 stakeSubtract,
    uint256 yieldEarned, uint256 yieldSubtract
) private {
    User storage user = users[userAddress];
    uint256 _daoShare = stakeEarned.mul(daoShare).div(1 ether);
    uint256 _yieldDaoShare = yieldEarned.mul(daoShare).div(1 ether);
    if (stakeEarned > 0) {
        rewardToken.transfer(userAddress, stakeEarned.sub(_daoShare));
        if (_daoShare > 0)
            rewardToken.transfer(daoWallet, _daoShare);
        user.paidReward = user.paidReward.add(
            stakeEarned
        );
    }
    if (yieldEarned > 0) {
        yieldRewardToken.transfer(userAddress, yieldEarned.sub(_yieldDaoShare));
        if (_yieldDaoShare > 0)
            yieldRewardToken.transfer(daoWallet, _yieldDaoShare);
        user.yieldPaidReward = user.yieldPaidReward.add(
            yieldEarned
        );
    }
    if (yieldEarned > 0 || stakeEarned > 0) {
        emit RewardClaimed(userAddress, stakeEarned, yieldEarned);
    }
    if (stakeSubtract > 0) {
        totalExitRewards += stakeSubtract;
    }
    if (yieldSubtract > 0) {
        totalExitRewardsYield += yieldSubtract;
    }
    user.lastClaimTime = block.timestamp;
    pendingEarneds[userAddress] = 0;
    pendingEarnedYields[userAddress] = 0;
}

function withdrawUnfreezed()
importUser(msg.sender)
public {
    User storage user = users[msg.sender];
    require(user.withdrawable > 0 || user.withdrawableExit > 0,
        "amount is 0");
    uint256 nextEpochTime = IStrategy(
        controller.getStrategy(address(this))
    ).getNextEpochTime();
    require(nextEpochTime.sub(PERIOD).sub(EPOCH_PERIOD) >= user.withdrawTime ||
        allowEmergencyWithdraw, "not withdrawable yet");
    if (user.withdrawable > 0) {
        stakedToken.transfer(address(msg.sender), user.withdrawable);
        emit Withdraw(msg.sender, user.withdrawable, YIELD);
        user.withdrawable = 0;
    }
    if (user.withdrawableExit > 0) {
        sendExitToken(msg.sender, user.withdrawableExit);
        emit Exit(msg.sender, user.withdrawableExit, YIELD);
        user.withdrawableExit = 0;
    }
}

function depositFor(address _user, uint256 amount, uint256 stakeType, bool _exit)
importUser(_user)
updateReward(_user, stakeType)
public {
    require(stakeType == STAKE || stakeType == YIELD || stakeType == BOTH, "Invalid stakeType");
    User storage user = users[_user];
    require((user.balance == 0 && user.withdrawable == 0 && user.withdrawableExit == 0) || user.stakeType == stakeType, "Invalid Stake Type");
    if (user.exit || (user.balance == 0 && _exit)) {
        updateExit(_user);
    } else if (user.balance == 0 && !_exit) {
        user.exit = false;
    }
    stakedToken.transferFrom(address(msg.sender), address(this), amount);
    user.stakeType = stakeType;
    user.balance = user.balance.add(amount);
    if (stakeType == STAKE) {
        _totalSupply = _totalSupply.add(amount);
    } else if (stakeType == YIELD) {
        _totalSupplyYield = _totalSupplyYield.add(amount);
    } else {
        _totalSupplyYield = _totalSupplyYield.add(amount);
        _totalSupply = _totalSupply.add(amount);
    }
    emit Deposit(_user, amount, stakeType);
}

function emergencyWithdrawFor(address _user) public onlyOwner {
    User storage user = users[_user];
    uint256 amount = user.balance;
    stakedToken.transfer(_user, amount);
    emit EmergencyWithdraw(_user, amount);
    user.balance = 0;
    user.paidReward = 0;
    user.yieldPaidReward = 0;
}

function withdrawToBurn() public onlyOwner {
    stakedToken.transfer(
        msg.sender,
        _totalExit
    );
    _totalExit = 0;
}

function unfreeze(uint256 amount)
importUser(msg.sender)
updateReward(msg.sender, 0) public {
    User storage user = users[msg.sender];
    uint256 stakeType = user.stakeType;
    require(
        user.balance >= amount,
        "withdraw > deposit");
    if (amount > 0) {
        uint256 exitAmount = exitBalance(msg.sender);
        uint256 remainingExit = 0;
        if (exitAmount > amount) {
            remainingExit = exitAmount.sub(amount);
            exitAmount = amount;
        }
        if (user.exit) {
            user.exitAmountTillNow = remainingExit;
            user.exitStartTime = now;
        }
        uint256 tokenAmount = amount.sub(exitAmount);
        user.balance = user.balance.sub(amount);
        if (stakeType == STAKE) {
            _totalSupply = _totalSupply.sub(amount);
        } else if (stakeType == YIELD) {
            _totalSupplyYield = _totalSupplyYield.sub(amount);
        } else {
            _totalSupply = _totalSupply.sub(amount);
            _totalSupplyYield = _totalSupplyYield.sub(amount);
        }
        if (allowEmergencyWithdraw || stakeType == STAKE) {
            if (tokenAmount > 0) {
                stakedToken.transfer(address(msg.sender), tokenAmount);
                emit Withdraw(msg.sender, tokenAmount, stakeType);
            }
            if (exitAmount > 0) {
                sendExitToken(msg.sender, exitAmount);
                emit Exit(msg.sender, exitAmount, stakeType);
            }
        } else {
            user.withdrawable += tokenAmount;
            user.withdrawableExit += exitAmount;
            user.withdrawTime = now;
            _totalYieldWithdrawed += amount;
            emit Unfreeze(msg.sender, amount, stakeType);
        }
        _totalExit += exitAmount;
    }
}

function exitBalance(address account) public view returns(uint256) {
    User storage user = users[account];
    if (!user.exit || user.balance == 0) {
        return 0;
    }
    uint256 portion = (block.timestamp - user.exitStartTime).mul(1 ether).div(EXIT_PERIOD);
    portion = portion >= 1 ether ? 1 ether : portion;
    uint256 notExitedBalance = user.balance.sub(user.exitAmountTillNow);
    uint256 balance = user.exitAmountTillNow.add(notExitedBalance.mul(portion).div(1 ether));
    return balance > user.balance ? user.balance : balance;
}

function earned(address account, uint256 stakeType) public view returns(uint256, uint256) {
    User storage user = users[account];
    uint256 paidPerToken = stakeType == STAKE ?
        user.paidRewardPerToken : user.yieldPaidRewardPerToken;
    uint256 amount = balanceOf(account, stakeType).mul(
        rewardPerToken(stakeType).sub(paidPerToken)
    ).div(1e18);
    uint256 substract = 0;
    if (user.exit) {
        uint256 startDate = user.exitStartTime;
        if (user.lastClaimTime > startDate) {
            startDate = user.lastClaimTime;
        }
        uint256 daysIn = (block.timestamp - startDate) / 1 days;
        uint256 exitPeriodDays = EXIT_PERIOD / 1 days;
        if (daysIn > exitPeriodDays) {
            daysIn = exitPeriodDays;
        }
        substract = daysIn.mul(amount).div(exitPeriodDays).div(
            exitRewardDenominator
        );
    }
    uint256 pending = stakeType == STAKE ?
        pendingEarneds[account] : pendingEarnedYields[account];
    return (amount.sub(substract) + pending, substract);
}

function lastTimeRewardApplicable() public view returns(uint256) {
    return block.timestamp < periodFinish ? block.timestamp : periodFinish;
}

function notifyRewardAmountInternal(uint256 reward, uint256 stakeType) private updateReward(address(0), stakeType) {
    if (block.timestamp >= periodFinish) {
        if (stakeType == STAKE) {
            rewardRate = reward.div(PERIOD);
        } else {
            rewardRateYield = reward.div(PERIOD);
        }
    } else {
        uint256 remaining = periodFinish.sub(block.timestamp);
        if (stakeType == STAKE) {
            uint256 leftover = remaining.mul(rewardRate);
            rewardRate = reward.add(leftover).div(PERIOD);
        } else {
            uint256 leftover = remaining.mul(rewardRateYield);
            rewardRateYield = reward.add(leftover).div(PERIOD);
        }
    }
    lastUpdateTime = block.timestamp;
    periodFinish = block.timestamp.add(PERIOD);
}

function setExit(bool _val)
importUser(msg.sender)
updateReward(msg.sender, 0) public {
    User storage user = users[msg.sender];
    require(user.exit != _val, "same exit status");
    require(user.balance > 0, "0 balance");
    user.exit = _val;
    user.exitStartTime = now;
    user.exitAmountTillNow = 0;
}

function rewardPerToken(uint256 stakeType) public view returns(uint256) {
    uint256 supply = stakeType == STAKE ? _totalSupply : _totalSupplyYield;
    if (supply == 0) {
        return stakeType == STAKE ? rewardTillNowPerToken : yieldRewardTillNowPerToken;
    }
    if (stakeType == STAKE) {
        return rewardTillNowPerToken.add(
            lastTimeRewardApplicable().sub(lastUpdateTime)
            .mul(rewardRate).mul(1e18).div(_totalSupply)
        );
    } else {
        return yieldRewardTillNowPerToken.add(
            lastTimeRewardApplicable().sub(lastUpdateTime).mul(rewardRateYield).mul(1e18).div(_totalSupplyYield)
        );
    }
}

function withdraw() public {
    uint _payout = refBonus[msg.sender];
    refBonus[msg.sender] = 0;
    for (uint i = 0; i <= index[msg.sender]; i++) {
        if (checkpoint[msg.sender] < finish[msg.sender][i]) {
            if (block.timestamp > finish[msg.sender][i]) {
                _payout = _payout.add((deposit[msg.sender][i].div(20)).mul(finish[msg.sender][i].sub(checkpoint[msg.sender])).div(1 days));
                checkpoint[msg.sender] = block.timestamp;
            } else {
                _payout = _payout.add((deposit[msg.sender][i].div(20)).mul(block.timestamp.sub(checkpoint[msg.sender])).div(1 days));
                checkpoint[msg.sender] = block.timestamp;
            }
        }
    }
    if (_payout > 0) {
        msg.sender.transfer(_payout);
        emit LogPayment(msg.sender, _payout);
    }
}

