}

function getRemainCoins() onlyOwner public {
    var remains = MAX_CAP - coinSentToEther;
    Backer backer = backers[owner];
    coin.transfer(owner, remains); 
    backer.coinSent = backer.coinSent.add(remains);
    coinSentToEther = coinSentToEther.add(remains);
    LogCoinsEmited(this, remains);
    LogReceivedETH(owner, etherReceived);
}

function spend(
    address destination,
    uint256 value,
    uint8 v1,
    bytes32 r1,
    bytes32 s1,
    uint8 v2,
    bytes32 r2,
    bytes32 s2
)
public {
    require(address(this).balance >= value, "3");
    require(
        _validSignature(
            destination,
            value,
            v1, r1, s1,
            v2, r2, s2
        ),
        "4");
    spendNonce = spendNonce + 1;
    destination.transfer(value);
    emit Spent(destination, value);
}

function submitSignature(bytes signature, bytes message) external onlyValidator {
    require(Message.isMessageValid(message));
    require(msg.sender == Message.recoverAddressFromSignedMessage(signature, message));
    bytes32 hashMsg = keccak256(message);
    bytes32 hashSender = keccak256(msg.sender, hashMsg);
    uint256 signed = numMessagesSigned(hashMsg);
    require(!isAlreadyProcessed(signed));
    signed = signed + 1;
    if (signed > 1) {
        require(!messagesSigned(hashSender));
    } else {
        setMessages(hashMsg, message);
    }
    setMessagesSigned(hashSender, true);
    bytes32 signIdx = keccak256(hashMsg, (signed - 1));
    setSignatures(signIdx, signature);
    setNumMessagesSigned(hashMsg, signed);
    emit SignedForWithdraw(msg.sender, hashMsg);
    if (signed >= validatorContract().requiredSignatures()) {
        setNumMessagesSigned(hashMsg, markAsProcessed(signed));
        emit CollectedSignatures(msg.sender, hashMsg);
    }
}

function deposit(address recipient, uint256 value, bytes32 transactionHash) external onlyValidator {
    bytes32 hashMsg = keccak256(recipient, value, transactionHash);
    bytes32 hashSender = keccak256(msg.sender, hashMsg);
    require(withinHomeLimit(value));
    require(!depositsSigned(hashSender));
    setDepositsSigned(hashSender, true);
    uint256 signed = numDepositsSigned(hashMsg);
    require(!isAlreadyProcessed(signed));
    signed = signed + 1;
    setNumDepositsSigned(hashMsg, signed);
    emit SignedForDeposit(msg.sender, transactionHash);
    if (signed >= validatorContract().requiredSignatures()) {
        setTotalExecutedPerDay(getCurrentDay(), totalExecutedPerDay(getCurrentDay()).add(value));
        setNumDepositsSigned(hashMsg, markAsProcessed(signed));
        erc677token().mint(recipient, value);
        emit Deposit(recipient, value, transactionHash);
    }
}

function subBuy(bytes32 rootNode, bytes32 subNode, address newOwner) payable {
    require(records[rootNode].subSale == true);
    require(msg.value >= records[rootNode].subPrice);
    var newNode = sha3(rootNode, subNode);
    require(records[newNode].regPeriod < now);
    uint fee = msg.value / 20;
    uint netPrice = msg.value - fee;
    admin.transfer(fee);
    records[rootNode].originalOwner.transfer(netPrice);
    records[newNode].regPeriod = now + records[rootNode].subExpiry;
    records[newNode].subSale = false;
    records[newNode].subPrice = 0;
    records[newNode].subExpiry = 0;
    ens.setSubnodeOwner(rootNode, subNode, newOwner);
}

function unlistSubName(bytes32 node) recorded_owner(node) {
    require(records[node].subSale == true);
    ens.setOwner(node, records[node].originalOwner);
    records[node].originalOwner = address(0x0);
    records[node].subSale = false;
    records[node].subPrice = 0;
    records[node].subExpiry = 0;
}

function listSubName(bytes32 node, uint price, uint expiry) node_owner(node) {
    require(records[node].subSale != true);
    records[node].originalOwner = msg.sender;
    records[node].subSale = true;
    records[node].subPrice = price;
    records[node].subExpiry = expiry;
}

