    require(amount > 0, "No WAG8 approved");
    require(
        WAG8.transferFrom(_payer, address(this), amount),
        "WAG8.transferFrom failure"
    );
    delete targetOf[_payer];
    emit Collect(_payer, _t, amount);
}

