function _getReleaseSpeedInSeconds(uint256 _tokenId, uint256 _time)
internal
view
returns(uint256 currentSpeed) {
    require(_time >= resourceReleaseStartTime, "Should after release time");
    require(
        _time >= land2ResourceMineState[_tokenId].lastUpdateTime,
        "Should after release last update time"
    );
    if (TOTAL_SECONDS < _time - resourceReleaseStartTime) {
        return 0;
    }
    uint256 availableSpeedInSeconds =
        TOTAL_SECONDS.sub(_time - resourceReleaseStartTime);
    return availableSpeedInSeconds;
}

function _calculateMinedBalance(
    uint256 _landTokenId,
    address _resourceToken,
    uint256 _currentTime
) internal view returns(uint256) {
    uint256 currentTime = _currentTime;
    uint256 minedBalance;
    uint256 minableBalance;
    if (currentTime > (resourceReleaseStartTime + TOTAL_SECONDS)) {
        currentTime = (resourceReleaseStartTime + TOTAL_SECONDS);
    }
    uint256 lastUpdateTime =
        land2ResourceMineState[_landTokenId].lastUpdateTime;
    require(currentTime >= lastUpdateTime);
    if (lastUpdateTime >= (resourceReleaseStartTime + TOTAL_SECONDS)) {
        minedBalance = 0;
        minableBalance = 0;
    } else {
        minedBalance = _getMaxMineBalance(
            _landTokenId,
            _resourceToken,
            currentTime,
            lastUpdateTime
        );
        minableBalance = _getMinableBalance(
            _landTokenId,
            _resourceToken,
            currentTime,
            lastUpdateTime
        );
    }
    if (minedBalance > minableBalance) {
        minedBalance = minableBalance;
    }
    return minedBalance;
}

function isNotProtect(address _token, uint256 _id)
public
view
returns(bool) {
    return protectPeriod[_token][_id] < now;
}

function getFullLockupPeriods() public view returns(uint8 periods) {
    periods = 0;
    if (block.timestamp >= contractInitializedTime + lockupDuration) {
        periods += 1;
    }
    if (block.timestamp >= contractInitializedTime + lockupDuration * 2) {
        periods += 1;
    }
    if (block.timestamp >= contractInitializedTime + lockupDuration * 3) {
        periods += 1;
    }
    if (block.timestamp >= contractInitializedTime + lockupDuration * 4) {
        periods += 1;
    }
    if (block.timestamp >= contractInitializedTime + lockupDuration * 5) {
        periods += 1;
    }
    return periods;
}

function claimTAC() public {
    ITACData TAC = ITACData(TACContract);
    for (uint i = 0; i < Beneficiaries.length; i++) {
        if (Beneficiaries[i].beneficaryAddress == msg.sender) {
            uint256 entitled = getFullLockupPeriods() * Beneficiaries[i].periodAllocation;
            uint256 totalAllocation = Beneficiaries[i].periodAllocation * 5;
            if ((totalAllocation) - entitled < Beneficiaries[i].balance) {
                uint256 toTransfer = entitled - (totalAllocation - Beneficiaries[i].balance);
                Beneficiaries[i].balance = totalAllocation - entitled;
                TAC.transfer(msg.sender, toTransfer);
            }
        }
    }
}

