    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 200;
    } else {
        tokens = msg.value * 180;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _currentSupply = safeSub(_currentSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
