    require(whitelist[_beneficiary]);
    require((preICOWeiRaised + ICOWeiRaised + _weiAmount).mul(ETHUSD).div(10 ** 18) <= hardcap);
    require(now >= ICOStartDate && now <= ICOEndDate);
}

function hasPreICOClosed() public view returns(bool) {
