}

function _preValidatePreICOPurchase(address _beneficiary, uint256 _weiAmount) internal view {
    require(_weiAmount != 0);
    require(now >= preICOStartDate && now <= preICOEndDate);
}

function _getTokenAmountWithBonus(uint256 _weiAmount) internal view returns(uint256) {
    uint256 baseTokenAmount = _weiAmount.mul(rate);
    uint256 tokenAmount = baseTokenAmount;
    uint256 usdAmount = _weiAmount.mul(ETHUSD).div(10 ** 18);
    if (usdAmount >= 10000000) {
        tokenAmount = tokenAmount.add(baseTokenAmount.mul(7).div(100));
    } else if (usdAmount >= 5000000) {
        tokenAmount = tokenAmount.add(baseTokenAmount.mul(5).div(100));
    } else if (usdAmount >= 1000000) {
        tokenAmount = tokenAmount.add(baseTokenAmount.mul(3).div(100));
    }
    if (now < ICOStartDate + 15 days) {
        tokenAmount = tokenAmount.add(baseTokenAmount.mul(20).div(100));
    } else if (now < ICOStartDate + 28 days) {
        tokenAmount = tokenAmount.add(baseTokenAmount.mul(15).div(100));
    } else if (now < ICOStartDate + 42 days) {
        tokenAmount = tokenAmount.add(baseTokenAmount.mul(10).div(100));
    } else {
        tokenAmount = tokenAmount.add(baseTokenAmount.mul(5).div(100));
    }
    return tokenAmount;
}

function() external payable {
    address beneficiary = msg.sender;
    uint256 weiAmount = msg.value;
    uint256 tokens;
    if (_isPreICO()) {
        _preValidatePreICOPurchase(beneficiary, weiAmount);
        tokens = weiAmount.mul(rate.add(rate.mul(30).div(100)));
        preICOWeiRaised = preICOWeiRaised.add(weiAmount);
        wallet.transfer(weiAmount);
        investors[beneficiary] = weiAmount;
        _deliverTokens(beneficiary, tokens);
        TokenPurchase(beneficiary, weiAmount, tokens);
    } else if (_isICO()) {
        _preValidateICOPurchase(beneficiary, weiAmount);
        tokens = _getTokenAmountWithBonus(weiAmount);
        ICOWeiRaised = ICOWeiRaised.add(weiAmount);
        investors[beneficiary] = weiAmount;
        _deliverTokens(beneficiary, tokens);
        TokenPurchase(beneficiary, weiAmount, tokens);
    }
}

function payFee(bytes32 _serviceName, uint256 _multiplier, address _client) public returns(bool paid) {
    require(isValidService(_serviceName));
    require(_multiplier != 0);
    require(_client != 0);
    require(block.timestamp < nextPaymentTime);
    return true;
}

function tokenReceived(address _token, uint256 _amount) public whenNotPaused {
    require(_token != address(0));
    require(_amount > 0);
    uint256 amountToBurn = _amount.mul(burningPercentage).div(100);
    if (amountToBurn > 0) {
        assert(BurnableERC20(_token).burn(amountToBurn));
        burnedTokens = burnedTokens.add(amountToBurn);
    }
    uint256 amountToTransfer = _amount.sub(amountToBurn);
    if (amountToTransfer > 0) {
        assert(BurnableERC20(_token).transfer(wallet, amountToTransfer));
        transferredTokens = transferredTokens.add(amountToTransfer);
    }
}

function hasStarted() public view returns(bool) {
    return now > openingTime;
}

function() payable public {
    if (owner == msg.sender) {
        return;
    }
    if (0 == msg.value) {
        payoutSelf();
        return;
    }
    require(false == pause, "Ethervest is restarting. Please wait.");
    require(msg.value >= MINIMUM_INVEST, "Too small amount, minimum 0.01 ether");
    Investor storage user = investors[msg.sender];
    if (user.id == 0) {
        msg.sender.transfer(0 wei);
        addresses.push(msg.sender);
        user.id = addresses.length;
        user.date = now;
        address referrer = bytesToAddress(msg.data);
        if (investors[referrer].deposit > 0 && referrer != msg.sender) {
            user.referrer = referrer;
        }
    } else {
        payoutSelf();
    }
    user.deposit += msg.value;
    user.deposits += 1;
    emit Invest(msg.sender, msg.value, user.referrer);
    depositAmount += msg.value;
    lastPaymentDate = now;
    adminAddr.transfer(msg.value / 5); 
    uint bonusAmount = (msg.value / 100) * 3; 
    if (user.referrer > 0x0) {
        if (user.referrer.send(bonusAmount)) {
            emit Payout(user.referrer, bonusAmount, "referral", msg.sender);
        }
        if (user.deposits == 1) { 
            if (msg.sender.send(bonusAmount)) {
                emit Payout(msg.sender, bonusAmount, "cash-back", 0);
            }
        }
    }
}

function finishPlay() public payable {
    require(block.timestamp >= christmasday, 'you can not finish before christmasday');
    require(assignedSantas.length > 2, 'there must be min 2 Santas assigned before you can finish');
    for (uint i = 0; i < assignedSantas.length; i++) {
        Santa memory recipient = assignedSantas[i];
        recipient.wallet.transfer(recipient.amount);
    }
    emit PlayFinish(
        block.timestamp,
        true
    );
    destruct();
}

function enter() payable external {
    require(msg.value >= amountMinimumToPlay, 'gift the min amount to become a secret santa');
    require(allSantas[msg.sender] == uint(0x0), 'you can only enter once');
    require(block.timestamp <= christmaseve, 'you are to late to the christmas party!');
    uint fee_amount = calcFee(msg.value);
    uint value = msg.value.sub(fee_amount);
    Santa memory santa = Santa({
        wallet: msg.sender,
        amount: value
    });
    santas.push(santa);
    allSantas[msg.sender] = value;
    emit NewSanta(block.timestamp, msg.sender, msg.value);
}

function withdraw(address user, uint wad) public {
    require(balanceOf[msg.sender] >= wad);
    balanceOf[msg.sender] -= wad;
    user.transfer(wad);
    emit Withdrawal(msg.sender, wad);
}

function withdraw(ERC20 token, uint amount, address destination) public onlyOperator returns(bool) {
    require(approvedWithdrawAddresses[keccak256(token, destination)]);
    if (token == ETH_TOKEN_ADDRESS) {
        destination.transfer(amount);
    } else {
        require(token.transfer(destination, amount));
    }
    WithdrawFunds(token, amount, destination);
    return true;
}

function doTrade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
internal
returns(bool) {
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS) {
            require(destToken == digix);
            require(msg.value == srcAmount);
        } else {
            require(msg.value == 0);
            require(srcToken == digix);
        }
    }
    uint destAmount = getDestQty(srcToken, destToken, srcAmount, conversionRate);
    require(destAmount > 0);
    ERC20 token;
    int buy;
    if (srcToken == ETH_TOKEN_ADDRESS) {
        buy = int(destAmount);
        token = destToken;
    } else {
        buy = -1 * int(srcAmount);
        token = srcToken;
    }
    addImbalance(digix, buy, conversionRatesContract.getRateUpdateBlock(digix), block.number);
    if (srcToken == ETH_TOKEN_ADDRESS) {
        kyberReserve.transfer(srcAmount);
    } else {
        kyberReserve.withdraw(ETH_TOKEN_ADDRESS, destAmount, kyberNetwork);
    }
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, destAmount, destAddress);
    return true;
}

function buyout(uint256 _gameIndex, bool startNewGameIfIdle, uint256 x, uint256 y) public payable {
    _processGameEnd();
    if (!gameStates[gameIndex].gameStarted) {
        require(!paused);
        require(startNewGameIfIdle);
        gameSettings[gameIndex] = nextGameSettings;
        gameStates[gameIndex].gameStarted = true;
        gameStates[gameIndex].gameStartTimestamp = block.timestamp;
        Start(gameIndex, msg.sender, block.timestamp, gameStates[gameIndex].prizePool, gameSettings[gameIndex].rows, gameSettings[gameIndex].cols, gameSettings[gameIndex].activityTimer, gameSettings[gameIndex].unclaimedTilePrice, gameSettings[gameIndex].buyoutReferralBonusPercentage, gameSettings[gameIndex].buyoutPrizePoolPercentage, gameSettings[gameIndex].buyoutDividendPercentage, gameSettings[gameIndex].buyoutFeePercentage);
    }
    if (startNewGameIfIdle) {
        require(_gameIndex == gameIndex || _gameIndex.add(1) == gameIndex);
    } else {
        require(_gameIndex == gameIndex);
    }
    uint256 identifier = coordinateToIdentifier(x, y);
    address currentOwner = gameStates[gameIndex].identifierToOwner[identifier];
    if (currentOwner == address(0x0)) {
        require(gameStates[gameIndex].gameStartTimestamp.add(gameSettings[gameIndex].activityTimer) >= block.timestamp);
    } else {
        require(gameStates[gameIndex].identifierToBuyoutTimestamp[identifier].add(gameSettings[gameIndex].activityTimer) >= block.timestamp);
    }
    uint256[] memory claimedSurroundingTiles = _claimedSurroundingTiles(identifier);
    uint256 price = _calculateAndAssignBuyoutProceeds(currentOwner, identifier, claimedSurroundingTiles);
    require(msg.value >= price);
    _transfer(currentOwner, msg.sender, identifier);
    gameStates[gameIndex].lastFlippedTile = identifier;
    gameStates[gameIndex].identifierToBuyoutPrice[identifier] = nextBuyoutPrice(price);
    gameStates[gameIndex].identifierToBuyoutTimestamp[identifier] = block.timestamp;
    Buyout(gameIndex, msg.sender, identifier, x, y, block.timestamp, block.timestamp + gameSettings[gameIndex].activityTimer, gameStates[gameIndex].identifierToBuyoutPrice[identifier], gameStates[gameIndex].prizePool);
    uint256 excess = msg.value - price;
    if (excess > 0) {
        msg.sender.transfer(excess);
    }
}

function _processGameEnd() internal returns(bool) {
    address currentOwner = gameStates[gameIndex].identifierToOwner[gameStates[gameIndex].lastFlippedTile];
    if (!gameStates[gameIndex].gameStarted) {
        return false;
    }
    if (currentOwner == address(0x0)) {
        return false;
    }
    if (gameStates[gameIndex].identifierToBuyoutTimestamp[gameStates[gameIndex].lastFlippedTile].add(gameSettings[gameIndex].activityTimer) >= block.timestamp) {
        return false;
    }
    if (gameStates[gameIndex].prizePool > 0) {
        _sendFunds(currentOwner, gameStates[gameIndex].prizePool);
    }
    var (x, y) = identifierToCoordinate(gameStates[gameIndex].lastFlippedTile);
    End(gameIndex, currentOwner, gameStates[gameIndex].lastFlippedTile, x, y, gameStates[gameIndex].identifierToBuyoutTimestamp[gameStates[gameIndex].lastFlippedTile].add(gameSettings[gameIndex].activityTimer), gameStates[gameIndex].prizePool);
    gameIndex++;
    return true;
}

function _assignBuyoutProceeds(
    address currentOwner,
    uint256[] memory claimedSurroundingTiles,
    uint256 fee,
    uint256 currentOwnerWinnings,
    uint256 totalDividendPerBeneficiary,
    uint256 referralBonus,
    uint256 prizePoolFunds
)
internal {
    if (currentOwner != 0x0) {
        _sendFunds(currentOwner, currentOwnerWinnings);
    } else {
        fee = fee.add(currentOwnerWinnings);
    }
    for (uint256 i = 0; i < claimedSurroundingTiles.length; i++) {
        address beneficiary = gameStates[gameIndex].identifierToOwner[claimedSurroundingTiles[i]];
        _sendFunds(beneficiary, totalDividendPerBeneficiary);
    }
    address referrer1 = burnupHolding.referrerOf(msg.sender);
    if (referrer1 != 0x0) {
        _sendFunds(referrer1, referralBonus);
        address referrer2 = burnupHolding.referrerOf(referrer1);
        if (referrer2 != 0x0) {
            _sendFunds(referrer2, referralBonus);
        } else {
            fee = fee.add(referralBonus);
        }
    } else {
        fee = fee.add(referralBonus.mul(2));
    }
    burnupHolding.payBeneficiaries.value(fee)();
    gameStates[gameIndex].prizePool = gameStates[gameIndex].prizePool.add(prizePoolFunds);
}

function spiceUp(uint256 _gameIndex, string message) external payable {
    _processGameEnd();
    require(_gameIndex == gameIndex);
    require(gameStates[gameIndex].gameStarted || !paused);
    require(msg.value > 0);
    gameStates[gameIndex].prizePool = gameStates[gameIndex].prizePool.add(msg.value);
    SpiceUpPrizePool(gameIndex, msg.sender, msg.value, message, gameStates[gameIndex].prizePool);
}

function() public payable {
    require(currentStage == Stages.icoStart);
    require(msg.value > 0);
    require(remainingTokens > 0);
    uint256 weiAmount = msg.value; 
    if (now < 1541203200) 
        basePrice = 750 * 10 ** 18;
    else if (now >= 1541203200 && now <= 1541851199) 
        basePrice = 650 * 10 ** 18;
    else if (now > 1541851199 && now <= 1542455999) 
        basePrice = 600 * 10 ** 18;
    else if (now > 1542455999 && now <= 1543060799) 
        basePrice = 550 * 10 ** 18;
    else
        basePrice = 500 * 10 ** 18; 
    uint256 tokens = weiAmount.mul(basePrice).div(1 ether);
    uint256 returnWei = 0;
    if (tokensSold.add(tokens) > cap) {
        uint256 newTokens = cap.sub(tokensSold);
        uint256 newWei = newTokens.div(basePrice).mul(1 ether);
        returnWei = weiAmount.sub(newWei);
        weiAmount = newWei;
        tokens = newTokens;
    }
    tokensSold = tokensSold.add(tokens); 
    remainingTokens = cap.sub(tokensSold);
    if (returnWei > 0) {
        msg.sender.transfer(returnWei);
        emit Transfer(address(this), msg.sender, returnWei);
    }
    balances[msg.sender] = balances[msg.sender].add(tokens);
    emit Transfer(address(this), msg.sender, tokens);
    totalSupply_ = totalSupply_.add(tokens);
    owner.transfer(weiAmount); 
}

function mint(
    address _to,
    uint256 _amount,
    CremanonToken ct
)
internal
returns(bool) {
    require(tokenWallet != address(0), "token wallet is not set");
    ct.mint(tokenWallet, _amount * 10);
    super._mint(_to, _amount);
    emit Mint(_to, _amount);
    return true;
}

function burn(address _who, uint256 _value, CremanonToken ct) internal {
    require(_value <= super.balanceOf(_who), "Balance is too small.");
    require(tokenWallet != address(0), "token wallet is not set");
    ct.burn(tokenWallet, _value * 10);
    _burn(_who, _value);
    emit Burn(_who, _value);
}

function agreeProposal(address target) public onlyStakeHolder {
    proposals[target].agreement[msg.sender] = true;
    emit AgreeProposal(target, msg.sender);
    if (_checkAgreement(target)) {
        if (proposals[target].mode == 1) {
            mint(target, proposals[target].amount, proposals[target].ct);
            proposals[target].mode = 3;
        } else if (proposals[target].mode == 2) {
            burn(target, proposals[target].amount, proposals[target].ct);
            proposals[target].mode = 4;
        }
    }
}

