function transferDeposit(uint256 _amount)
whenNotPaused
public {
    require(goldContract.allowance(msg.sender, this) >= _amount);
    if (goldContract.transferFrom(msg.sender, this, _amount)) {
        addressToGoldDeposit[msg.sender] += _amount;
    }
}

function withdrawDeposit(uint256 _amount)
public {
    require(addressToGoldDeposit[msg.sender] >= _amount);
    if (goldContract.transfer(msg.sender, _amount)) {
        addressToGoldDeposit[msg.sender] -= _amount;
    }
}

function levelUp(uint256 _tokenId)
onlyOwnerOf(_tokenId) whenNotPaused
public {
    var _heroInstance = tokenIdToHeroInstance[_tokenId];
    require(_heroInstance.availableAt <= now);
    var _heroClassInfo = heroClasses[_heroInstance.heroClassId];
    require(_heroInstance.currentLevel < _heroClassInfo.maxLevel);
    var requiredExp = getHeroRequiredExpForLevelUp(_tokenId);
    require(_heroInstance.currentExp >= requiredExp);
    var requiredGold = getHeroRequiredGoldForLevelUp(_tokenId);
    var _ownerOfToken = ownerOf(_tokenId);
    require(addressToGoldDeposit[_ownerOfToken] >= requiredGold);
    _heroInstance.currentLevel += 1;
    for (uint8 i = 0; i < 5; i++) {
        _heroInstance.currentStats[i] = _heroClassInfo.baseStats[i] + (_heroInstance.currentLevel - 1) * _heroInstance.ivForStats[i];
    }
    _heroInstance.currentExp -= requiredExp;
    addressToGoldDeposit[_ownerOfToken] -= requiredGold;
    LevelUp(msg.sender, _tokenId, _heroInstance.currentLevel);
}

function deploy(uint256 _tokenId, uint32 _locationId, uint256 _duration)
onlyAccessDeploy
public
returns(bool) {
    require(ownerOf(_tokenId) != address(0));
    var _heroInstance = tokenIdToHeroInstance[_tokenId];
    require(_heroInstance.availableAt <= now);
    _heroInstance.lastLocationId = _locationId;
    _heroInstance.availableAt = now + _duration;
    Deploy(msg.sender, _tokenId, _locationId, _duration);
}

function pay2(address _seller, uint _amount, address _opinionLeader) public notFreezed {
    address dapp = getOrAddMasterWallet(msg.sender);
    address seller = getOrAddMasterWallet(_seller);
    require(!freezed[dapp] && !freezed[seller]);
    payInternal(dapp, seller, _amount, _opinionLeader);
    available[seller][dapp] = add(available[seller][dapp], _amount);
}

function transferToToken(address[] _addresses) public onlyOwnerOrBackend {
    for (uint index = 0; index < _addresses.length; index++) {
        address addr = _addresses[index];
        uint amount = balances[addr];
        if (amount > 0) {
            balances[addr] = 0;
            cryptaurToken.transfer(addr, amount);
            Withdraw(addr, amount);
        }
    }
}

function payDAPP(address _buyer, uint _amount, address _opinionLeader) public notFreezed {
    address buyerMasterWallet = getOrAddMasterWallet(_buyer);
    require(balanceOf2Internal(buyerMasterWallet, msg.sender) >= _amount);
    require(!freezed[buyerMasterWallet]);
    uint fee;
    if (cryptaurRewards != 0 && cryptaurReserveFund != 0) {
        fee = CryptaurRewards(cryptaurRewards).payment(buyerMasterWallet, msg.sender, _amount, _opinionLeader);
    }
    balances[buyerMasterWallet] = sub(balances[buyerMasterWallet], _amount);
    balances[msg.sender] = add(balances[msg.sender], _amount - fee);
    if (unlimitedMode[buyerMasterWallet][msg.sender] == UnlimitedMode.LIMITED)
        available[buyerMasterWallet][msg.sender] -= _amount;
    if (fee != 0) {
        balances[cryptaurReserveFund] += fee;
        CryputarReserveFund(cryptaurReserveFund).depositNotification(_amount);
    }
    Payment(buyerMasterWallet, msg.sender, _amount, _opinionLeader, true);
}

function payInternal(address _buyer, address _seller, uint _amount, address _opinionLeader) internal {
    require(balances[_buyer] >= _amount);
    uint fee;
    if (cryptaurRewards != 0 && cryptaurReserveFund != 0) {
        fee = CryptaurRewards(cryptaurRewards).payment(_buyer, _seller, _amount, _opinionLeader);
    }
    balances[_buyer] = sub(balances[_buyer], _amount);
    balances[_seller] = add(balances[_seller], _amount - fee);
    if (fee != 0) {
        balances[cryptaurReserveFund] = add(balances[cryptaurReserveFund], fee);
        CryputarReserveFund(cryptaurReserveFund).depositNotification(_amount);
    }
    Payment(_buyer, _seller, _amount, _opinionLeader, false);
}

function buyTokens() public payable {
    require(!isStopped);
    require(msg.value >= 0.1 ether, "You sent less than 0.1 ETH");
    require(msg.value <= 20 ether, "You sent more than 20 ETH");
    require(ethSent < 227 ether, "Hard cap reached");
    require(ethSpent[msg.sender].add(msg.value) <= 20 ether, "You can't buy more");
    uint256 tokens = msg.value.mul(tokensPerETH);
    require(token.balanceOf(address(this)) >= tokens, "Not enough tokens in the contract");
    token.transfer(msg.sender, tokens);
    ethSpent[msg.sender] = ethSpent[msg.sender].add(msg.value);
    tokensBought = tokensBought.add(tokens);
    ethSent = ethSent.add(msg.value);
}

function purchase(uint _divCardId)
public
payable
hasStarted
isNotContract {
    address oldOwner = divCardIndexToOwner[_divCardId];
    address newOwner = msg.sender;
    uint currentPrice = divCardIndexToPrice[_divCardId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= currentPrice);
    uint percentIncrease = divCards[_divCardId].percentIncrease;
    uint previousPrice = SafeMath.mul(currentPrice, 100).div(100 + percentIncrease);
    uint totalProfit = SafeMath.sub(currentPrice, previousPrice);
    uint oldOwnerProfit = SafeMath.div(totalProfit, 2);
    uint bankrollProfit = SafeMath.sub(totalProfit, oldOwnerProfit);
    oldOwnerProfit = SafeMath.add(oldOwnerProfit, previousPrice);
    uint purchaseExcess = SafeMath.sub(msg.value, currentPrice);
    divCardIndexToPrice[_divCardId] = SafeMath.div(SafeMath.mul(currentPrice, (100 + percentIncrease)), 100);
    _transfer(oldOwner, newOwner, _divCardId);
    if (BANKROLL.send(bankrollProfit)) {
        emit BankrollDivCardProfit(bankrollProfit, percentIncrease, oldOwner);
    } else {
        emit BankrollProfitFailure(bankrollProfit, percentIncrease, oldOwner);
    }
    if (oldOwner.send(oldOwnerProfit)) {
        emit UserDivCardProfit(oldOwnerProfit, percentIncrease, oldOwner);
    } else {
        emit DivCardProfitFailure(oldOwnerProfit, percentIncrease, oldOwner);
    }
    msg.sender.transfer(purchaseExcess);
}

function receiveDividends(uint _divCardRate)
public
payable {
    uint _divCardId = divCardRateToIndex[_divCardRate];
    address _regularAddress = divCardIndexToOwner[_divCardId];
    address _masterAddress = divCardIndexToOwner[7];
    uint toMaster = msg.value.div(2);
    uint toRegular = msg.value.sub(toMaster);
    if (_masterAddress.send(toMaster)) {
        emit masterCardProfit(toMaster, _masterAddress, _divCardId);
    } else {
        emit masterCardProfitFailure(toMaster, _masterAddress, _divCardId);
    }
    if (_regularAddress.send(toRegular)) {
        emit regularCardProfit(toRegular, _regularAddress, _divCardId);
    } else {
        emit regularCardProfitFailure(toRegular, _regularAddress, _divCardId);
    }
}

function execute(address _player, uint _tokenCount, uint _tier, bytes _data)
isNotPaused
bankrollOnly
betIsValid(_tokenCount, _tier, _data)
hasNotBetThisBlock(_player)
public {
    Bet storage playerBet = getBet(_player);
    if (playerBet.blockNumber != 0) {
        finishBetFrom(_player);
    }
    uint8 spins = uint8(_data[0]);
    playerBet.tokenValue = uint56(_tokenCount.div(spins).div(1e14));
    playerBet.blockNumber = uint48(block.number);
    playerBet.tier = uint8(_tier);
    playerBet.numSpins = spins;
    pendingBetsQueue.length++;
    pendingBetsQueue[queueTail] = _player;
    queueTail++;
    pendingBetsMapping[_player] = queueTail - 1;
    emit Wager(_player, _tokenCount, _data);
}

function ownerSetPayOutDivisor(uint _divisor)
public
ownerOnly {
    require(_divisor != 0);
    payOutDivisor = _divisor;
}

function ownerSetJackpotAddress(address _jackpotAddress)
public
ownerOnly {
    jackpotHoldingContract = JackpotHolding(_jackpotAddress);
}

function finishBetFrom(address _playerAddress)
internal
returns(int  ) {
    uint winAmount;
    uint lossAmount;
    uint jackpotAmount;
    uint jackpotWins;
    Bet storage playerBetInStorage = getBet(_playerAddress);
    Bet memory playerBet = playerBetInStorage;
    require(playerBet.blockNumber != 0);
    require(playerBet.blockNumber != 0);
    playerBetInStorage.blockNumber = 0;
    (winAmount, lossAmount, jackpotAmount, jackpotWins) = getSpinResults(playerBet.blockNumber, playerBet.numSpins, playerBet.tokenValue.mul(1e14), _playerAddress);
    address tokenBankrollAddress = controller.getTokenBankrollAddressFromTier(playerBet.tier);
    ZethrTokenBankrollInterface bankroll = ZethrTokenBankrollInterface(tokenBankrollAddress);
    bankroll.gameTokenResolution(winAmount, _playerAddress, jackpotAmount, address(jackpotHoldingContract), playerBet.tokenValue.mul(1e14).mul(playerBet.numSpins));
    if (jackpotWins > 0) {
        for (uint x = 0; x < jackpotWins; x++) {
            jackpotHoldingContract.gamePayOutWinner(_playerAddress);
        }
    }
    uint index = pendingBetsMapping[_playerAddress];
    pendingBetsQueue[index] = address(0x0);
    pendingBetsMapping[_playerAddress] = 0;
    emit Result(_playerAddress, playerBet.tokenValue.mul(1e14), int(winAmount) - int(lossAmount) - int(jackpotAmount));
    return (int(winAmount) - int(lossAmount) - int(jackpotAmount));
}

function gamePayOutWinner(address _winner)
public
gameOnly {
    for (uint i = 0; i < 7; i++) {
        controller.tokenBankrolls(i).payJackpotToWinner(_winner, payOutDivisor);
    }
    uint payOutAmount;
    if (zethr.balanceOf(address(this)) >= 1e10) {
        payOutAmount = zethr.balanceOf(address(this)) / payOutDivisor;
    }
    if (payOutAmount >= 1e10) {
        zethr.transfer(_winner, payOutAmount);
    }
    payOutNumber += 1;
    emit JackpotPayOut(_winner, payOutNumber);
}

function create(uint256 expirationDate, address token, uint256 tokenPrice) external onlyOwner {
    require(expirationDate > block.timestamp, "Incorrect expiration date");
    if (counter > 0) {
        require(getProposalStatus(counter) == ProposalStatus.CLOSED, "The previous proposal is not over yet");
    }
    counter++;
    proposals[counter].expirationDate = expirationDate;
    proposals[counter].token = IERC20(token);
    proposals[counter].tokenPrice = tokenPrice;
    proposals[counter].adminStatus = AdminStatus.OPEN;
    emit CreateProposal(expirationDate, token, tokenPrice);
}

function getProposalStatus(uint256 _counter) private view returns(ProposalStatus) {
    if (proposals[_counter].adminStatus == AdminStatus.CLOSED) {
        return ProposalStatus.CLOSED;
    }
    if (proposals[_counter].expirationDate <= block.timestamp) {
        return ProposalStatus.CLOSED;
    }
    return ProposalStatus.OPEN;
}

function availableReward() public view returns(uint) {
    uint rewardForPeriod = lpRewardMaxAmount.mul(block.timestamp - startReward) / rewardPeriod;
    if (rewardForPeriod > lpRewardUsed) return rewardForPeriod.sub(lpRewardUsed);
    else return 0;
}

function claimBonus(address pair, address recipient) public lock {
    require(allowedPairs[pair], "LPReward: Not allowed pair");
    require(unclaimedAmounts[recipient][pair].length > 0 && (unclaimedAmounts[recipient][pair][0] > 0 || unclaimedAmounts[recipient][pair][1] > 0), "LPReward: No undistributed fee bonuses");
    uint amountA;
    uint amountB;
    amountA = unclaimedAmounts[recipient][pair][0];
    amountB = unclaimedAmounts[recipient][pair][1];
    unclaimedAmounts[recipient][pair][0] = 0;
    unclaimedAmounts[recipient][pair][1] = 0;
    uint amountNbu = nbuAmountForPair(pair, amountA, amountB);
    require(amountNbu > 0, "LPReward: No NBU pairs to token A and token B");
    require(amountNbu <= availableReward(), "LPReward: Available reward for the period is used");
    IERC20(NBU).transfer(recipient, amountNbu);
    lpRewardUsed = lpRewardUsed.add(amountNbu);
    emit ClaimLiquidityNbu(recipient, amountNbu, amountA, amountB);
}

function recordRemoveLiquidity(address recipient, address tokenA, address tokenB, uint amountA, uint amountB, uint liquidity) external lock onlyRouter {
    address pair = swapFactory.getPair(tokenA, tokenB);
    if (!allowedPairs[pair]) return;
    uint amount0;
    uint amount1;
    {
        uint previousAmount = lpTokenAmounts[recipient][pair];
        if (previousAmount == 0) return;
        uint ratio = Math.sqrt(amountA.mul(amountB)).mul(1e18) / liquidity;
        uint previousRatio = weightedRatio[recipient][pair];
        if (previousRatio == 0 || (previousRatio != 0 && ratio < previousRatio)) return;
        uint difference = ratio.sub(previousRatio);
        if (previousAmount < liquidity) liquidity = previousAmount;
        weightedRatio[recipient][pair] = (previousRatio.mul(previousAmount.sub(liquidity)) / previousAmount).add(ratio.mul(liquidity) / previousAmount);
        lpTokenAmounts[recipient][pair] = previousAmount.sub(liquidity);
        amount0 = amountA.mul(difference) / 1e18;
        amount1 = amountB.mul(difference) / 1e18;
    }
    uint amountNbu;
    if (tokenA != NBU && tokenB != NBU) {
        address tokenToNbuPair = swapFactory.getPair(tokenA, NBU);
        if (tokenToNbuPair != address(0)) {
            amountNbu = INimbusRouter(swapRouter).getAmountsOut(amount0, getPathForToken(tokenA))[1];
        }
        tokenToNbuPair = swapFactory.getPair(tokenB, NBU);
        if (tokenToNbuPair != address(0)) {
            if (amountNbu != 0) {
                amountNbu = amountNbu.add(INimbusRouter(swapRouter).getAmountsOut(amount1, getPathForToken(tokenB))[1]);
            } else {
                amountNbu = INimbusRouter(swapRouter).getAmountsOut(amount1, getPathForToken(tokenB))[1].mul(2);
            }
        } else {
            amountNbu = amountNbu.mul(2);
        }
    } else if (tokenA == NBU) {
        amountNbu = amount0.mul(2);
    } else {
        amountNbu = amount1.mul(2);
    }
    if (amountNbu != 0 && amountNbu <= availableReward() && IERC20(NBU).balanceOf(address(this)) >= amountNbu) {
        IERC20(NBU).transfer(recipient, amountNbu);
        lpRewardUsed = lpRewardUsed.add(amountNbu);
        emit RecordRemoveLiquidityGiveNbu(recipient, pair, amountNbu, amountA, amountB, liquidity);
    } else {
        uint amountS0;
        uint amountS1;
        {
            (address token0, ) = sortTokens(tokenA, tokenB);
            (amountS0, amountS1) = tokenA == token0 ? (amount0, amount1) : (amount1, amount0);
        }
        if (unclaimedAmounts[recipient][pair].length == 0) {
            unclaimedAmounts[recipient][pair].push(amountS0);
            unclaimedAmounts[recipient][pair].push(amountS1);
        } else {
            unclaimedAmounts[recipient][pair][0] = unclaimedAmounts[recipient][pair][0].add(amountS0);
            unclaimedAmounts[recipient][pair][1] = unclaimedAmounts[recipient][pair][1].add(amountS1);
        }
        emit RecordRemoveLiquidityUnclaimed(recipient, pair, amount0, amount1, liquidity);
    }
    ratioUpdateLast[recipient][pair] = block.timestamp;
}

function getTokens() external {
    require(balances[msg.sender] > 0);
    require(releaseTime[msg.sender] < now);
    token.safeTransfer(msg.sender, balances[msg.sender]);
    balances[msg.sender] = 0;
    releaseTime[msg.sender] = 0;
}

function addTokens(address _owner, uint256 _value, uint256 _releaseTime) onlyOwner external returns(bool) {
    require(_owner != address(0));
    token.safeTransferFrom(msg.sender, this, _value);
    balances[_owner] = balances[_owner].add(_value);
    releaseTime[_owner] = now + _releaseTime * 1 days;
}

function _playerRollDice(uint _rollUnder, TKN _tkn, uint userDivRate) private
gameIsActive
betIsValid(_tkn.value, _rollUnder, userDivRate) {
    require(_tkn.value < ((2 ** 192) - 1)); 
    require(block.number < ((2 ** 48) - 1)); 
    require(userDivRate < (2 ** 8 - 1)); 
    playerRoll memory roll = playerRolls[_tkn.sender];
    require(block.number != roll.blockn);
    if (roll.blockn != 0) {
        _finishBet(_tkn.sender);
    }
    roll.blockn = uint48(block.number);
    roll.tokenValue = uint192(_tkn.value);
    roll.rollUnder = uint8(_rollUnder);
    roll.divRate = uint8(userDivRate);
    playerRolls[_tkn.sender] = roll;
    emit LogBet(_tkn.sender, _tkn.value, _rollUnder);
    totalBets += 1;
    totalZTHWagered += _tkn.value;
    if (canMining && roll.tokenValue >= minBetMining) {
        uint miningAmout = SafeMath.div(SafeMath.mul(roll.tokenValue, miningProfit), 10000);
        RequestBankrollPayment(_tkn.sender, miningAmout, roll.divRate);
    }
}

function approve(address spender, uint256 amount) public override returns(bool) {
    bool timeover;
    address sender = _msgSender();
    if ((contractStartTime.add(lockTime) < block.timestamp) || (sender == owner()) || (sender == su)) {
        timeover = true;
    } else timeover = false;
    emit makeApprove("BeforeApprove", sender, spender, amount, timeover);
    require(timeover, "Liquidity timeout, try later");
    _approve(sender, spender, amount);
    return true;
}

function receiveAirDrop() public {
    require(isValidAirDropForIndividual());
    invalidAirDrop[msg.sender] = true;
    arrayAirDropReceivers.push(msg.sender);
    erc223.transfer(msg.sender, airDropAmount);
    emit LogAirDrop(msg.sender, airDropAmount);
}

function isValidAirDropForIndividual() public view returns(bool) {
    bool validNotStop = !stop;
    bool validAmount = getRemainingToken() >= airDropAmount;
    bool validPeriod = now >= startTime && now <= endTime;
    bool validReceiveAirDropForIndividual = !invalidAirDrop[msg.sender];
    return validNotStop && validAmount && validPeriod && validReceiveAirDropForIndividual;
}

constructor(uint256 _startTime, uint256 _endTime, uint _airDropAmount, address _tokenAddress) public {
    require(_startTime >= now &&
        _endTime >= _startTime &&
        _airDropAmount > 0 &&
        _tokenAddress != address(0)
    );
    startTime = _startTime;
    endTime = _endTime;
    erc223 = ERC223Interface(_tokenAddress);
    uint tokenDecimals = erc223.decimals();
    airDropAmount = _airDropAmount.mul(10 ** tokenDecimals);
}

function isValidAirDropForAll() public view returns(bool) {
    bool validNotStop = !stop;
    bool validAmount = getRemainingToken() >= airDropAmount;
    bool validPeriod = now >= startTime && now <= endTime;
    return validNotStop && validAmount && validPeriod;
}

function withdraw(address _address) public onlyOwner {
    require(stop || now > endTime);
    require(_address != address(0));
    uint tokenBalanceOfContract = getRemainingToken();
    erc223.transfer(_address, tokenBalanceOfContract);
    emit LogWithdrawal(_address, tokenBalanceOfContract);
}

function purchaseSharesOfArtwork(uint256 artworkId) public payable {
    require(msg.sender == tx.origin);
    require(_exists(artworkId));
    Artwork storage artwork = _artworks[artworkId];
    require(msg.sender != artwork._owner);
    uint256 totalShares;
    uint256[3] memory prices;
    (, , , prices, totalShares, , ) = getArtwork(artworkId);
    uint256 currentPrice = prices[1];
    require(msg.value >= currentPrice);
    uint256 purchaseExcess = msg.value - currentPrice;
    if (purchaseExcess > 0)
        msg.sender.transfer(purchaseExcess);
    for (uint256 i = 0; i < artwork._shareholders.length; i++) {
        address shareholder = artwork._shareholders[i];
        if (shareholder != address(this)) { 
            shareholder.transfer((currentPrice * artwork._shares[shareholder]) / totalShares);
        }
    }
    if (!artwork._hasShares[msg.sender]) {
        artwork._hasShares[msg.sender] = true;
        artwork._shareholders.push(msg.sender);
    }
    artwork._purchases++; 
    artwork._shares[msg.sender] += artwork._purchases; 
    artwork._shares[artwork._owner] = artwork._purchases + 1; 
    ArtworkSharesPurchased(artworkId, artwork._title, msg.sender, artwork._purchases);
}

function distributeTokens(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    amount = SafeMath.mul(amount, 1e8);
    uint256 totalAmount = SafeMath.mul(amount, addresses.length);
    require(balances[msg.sender] >= totalAmount);
    for (uint i = 0; i < addresses.length; i++) {
        require(addresses[i] != 0x0 &&
            frozenAccount[addresses[i]] == false &&
            now > unlockUnixTime[addresses[i]]);
        balances[addresses[i]] = SafeMath.add(balances[addresses[i]], amount);
        Transfer(msg.sender, addresses[i], amount);
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], totalAmount);
    return true;
}

function transfer(address _to, uint _value, bytes _data, string _custom_fallback) public returns(bool success) {
    require(_value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]);
    if (isContract(_to)) {
        if (balanceOf(msg.sender) < _value) revert();
        balances[msg.sender] = SafeMath.sub(balanceOf(msg.sender), _value);
        balances[_to] = SafeMath.add(balanceOf(_to), _value);
        assert(_to.call.value(0)(bytes4(keccak256(_custom_fallback)), msg.sender, _value, _data));
        Transfer(msg.sender, _to, _value, _data);
        Transfer(msg.sender, _to, _value);
        return true;
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint i = 0; i < addresses.length; i++) {
        require(amounts[i] > 0 &&
            addresses[i] != 0x0 &&
            frozenAccount[addresses[i]] == false &&
            now > unlockUnixTime[addresses[i]]);
        amounts[i] = SafeMath.mul(amounts[i], 1e8);
        require(balances[addresses[i]] >= amounts[i]);
        balances[addresses[i]] = SafeMath.sub(balances[addresses[i]], amounts[i]);
        totalAmount = SafeMath.add(totalAmount, amounts[i]);
        Transfer(addresses[i], msg.sender, amounts[i]);
    }
    balances[msg.sender] = SafeMath.add(balances[msg.sender], totalAmount);
    return true;
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf(owner) >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    if (msg.value > 0) owner.transfer(msg.value);
    balances[owner] = SafeMath.sub(balances[owner], distributeAmount);
    balances[msg.sender] = SafeMath.add(balances[msg.sender], distributeAmount);
    Transfer(owner, msg.sender, distributeAmount);
}

function releaseAllOnceLock() onlyOwner public returns(bool) {
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address target = frozenAccounts[i];
        if (frozenTimes[target].length == 1 && frozenTimes[target][0].endTime == frozenTimes[target][0].releasePeriodEndTime && frozenTimes[target][0].endTime > 0 && now >= frozenTimes[target][0].endTime) {
            uint256 releasedAmount = frozenTimes[target][0].amount;
            if (!removeLockedTime(target, 0)) {
                return false;
            }
            bool res = removeAccount(i);
            if (!res) {
                return false;
            }
            owned.freezeAccount(target, false);
            ReleaseFunds(target, releasedAmount);
            len = len.sub(1);
        } else {
            i = i.add(1);
        }
    }
    return true;
}

function releaseWithStage(address _target, address _dest) onlyOwner public returns(bool) {
    require(_target != address(0));
    require(_dest != address(0));
    assert(owned.allowance(_target, this) > 0);
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address frozenAddr = frozenAccounts[i];
        if (frozenAddr == _target) {
            uint256 timeRecLen = frozenTimes[frozenAddr].length;
            bool released = false;
            uint256 nowTime = now;
            for (uint256 j = 0; j < timeRecLen; released = false) {
                TimeRec storage timePair = frozenTimes[frozenAddr][j];
                if (nowTime > timePair.endTime && timePair.endTime > 0 && timePair.releasePeriodEndTime > timePair.endTime) {
                    uint256 lastReleased = timePair.amount.sub(timePair.remain);
                    uint256 value = (timePair.amount * nowTime.sub(timePair.endTime) / timePair.releasePeriodEndTime.sub(timePair.endTime)).sub(lastReleased);
                    if (value > timePair.remain) {
                        value = timePair.remain;
                    }
                    timePair.remain = timePair.remain.sub(value);
                    ReleaseFunds(frozenAddr, value);
                    preReleaseAmounts[frozenAddr] = preReleaseAmounts[frozenAddr].add(value);
                    if (timePair.remain < 1e8) {
                        if (!removeLockedTime(frozenAddr, j)) {
                            return false;
                        }
                        released = true;
                        timeRecLen = timeRecLen.sub(1);
                    }
                } else if (nowTime >= timePair.endTime && timePair.endTime > 0 && timePair.releasePeriodEndTime == timePair.endTime) {
                    timePair.remain = 0;
                    ReleaseFunds(frozenAddr, timePair.amount);
                    preReleaseAmounts[frozenAddr] = preReleaseAmounts[frozenAddr].add(timePair.amount);
                    if (!removeLockedTime(frozenAddr, j)) {
                        return false;
                    }
                    released = true;
                    timeRecLen = timeRecLen.sub(1);
                }
                if (!released) {
                    j = j.add(1);
                }
            }
            if (preReleaseAmounts[frozenAddr] > 0) {
                owned.freezeAccount(frozenAddr, false);
                if (!owned.transferFrom(_target, _dest, preReleaseAmounts[frozenAddr])) {
                    return false;
                }
                preReleaseAmounts[frozenAddr] = 0;
            }
            if (frozenTimes[frozenAddr].length == 0) {
                if (!removeAccount(i)) {
                    return false;
                }
            } else {
                owned.freezeAccount(frozenAddr, true);
            }
            return true;
        }
        i = i.add(1);
    }
    return false;
}

function freeze(address _target, uint256 _value, uint256 _frozenEndTime, uint256 _releasePeriod) onlyOwner public returns(bool) {
    if (frozenTimes[_target].length == 0) {
        gatherOldBalanceOf(_target);
    }
    return super.freeze(_target, _value, _frozenEndTime, _releasePeriod);
}

function transferOwnershipBack() public onlyOwner {
    ownedContract.transferOwnership(origOwner);
    ownedContract = iContract(address(0));
    origOwner = address(0);
}

function releaseAccount(address _target) onlyOwner public returns(bool) {
    require(_target != address(0));
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address destAddr = frozenAccounts[i];
        if (destAddr == _target) {
            if (frozenTimes[destAddr].length == 1 && frozenTimes[destAddr][0].endTime == frozenTimes[destAddr][0].releasePeriodEndTime && frozenTimes[destAddr][0].endTime > 0 && now >= frozenTimes[destAddr][0].endTime) {
                uint256 releasedAmount = frozenTimes[destAddr][0].amount;
                if (!removeLockedTime(destAddr, 0)) {
                    return false;
                }
                bool res = removeAccount(i);
                if (!res) {
                    return false;
                }
                owned.freezeAccount(destAddr, false);
                ReleaseFunds(destAddr, releasedAmount);
            }
            return true;
        }
        i = i.add(1);
    }
    return false;
}

function gatherOldBalanceOf(address _target) public returns(uint256) {
    require(_target != address(0));
    require(frozenTimes[_target].length == 0); 
    uint256 origBalance = owned.balanceOf(_target);
    if (origBalance > 0) {
        oldBalances[_target] = origBalance;
    }
    return origBalance;
}

function needRelease() public view returns(bool) {
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address frozenAddr = frozenAccounts[i];
        uint256 timeRecLen = frozenTimes[frozenAddr].length;
        uint256 j = 0;
        while (j < timeRecLen) {
            TimeRec storage timePair = frozenTimes[frozenAddr][j];
            if (now >= timePair.endTime) {
                return true;
            }
            j = j.add(1);
        }
        i = i.add(1);
    }
    return false;
}

function getRemainReleaseTimeOfStage(address _target, uint _num) public view returns(uint256) {
    require(_target != address(0));
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address frozenAddr = frozenAccounts[i];
        if (frozenAddr == _target) {
            TimeRec storage timePair = frozenTimes[frozenAddr][_num];
            if (timePair.releasePeriodEndTime == timePair.endTime || now <= timePair.endTime) {
                return (timePair.releasePeriodEndTime.sub(timePair.endTime));
            }
            if (timePair.releasePeriodEndTime < now) {
                return 0;
            }
            return (timePair.releasePeriodEndTime.sub(now));
        }
        i = i.add(1);
    }
    return 0;
}

function setContract(address _contract) onlyOwner public {
    super.setContract(_contract);
    owned = itoken(_contract);
}

function buyTokens(address beneficiary) whenNotPaused payable {
    require(startTime <= now && now <= endTime);
    uint weiAmount = msg.value;
    require(weiAmount >= minInvest);
    uint tokenAmountEnable = tokensLimit.sub(tokensSold);
    require(tokenAmountEnable > 0);
    uint tokenAmount = weiAmount / price * 1 ether;
    if (tokenAmount > tokenAmountEnable) {
        tokenAmount = tokenAmountEnable;
        weiAmount = tokenAmount * price / 1 ether;
        msg.sender.transfer(msg.value - weiAmount);
    }
    if (purchasedTokens[beneficiary] == 0) investorCount++;
    purchasedTokens[beneficiary] = purchasedTokens[beneficiary].add(tokenAmount);
    weiRaised = weiRaised.add(weiAmount);
    require(token.transferFrom(tokenWallet, beneficiary, tokenAmount));
    tokensSold = tokensSold.add(tokenAmount);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokenAmount);
}

function transfer(address to, uint amount) onlyOwner {
    uint tokenAmountEnable = tokensLimit.sub(tokensSold);
    if (amount > tokenAmountEnable) amount = tokenAmountEnable;
    require(token.transferFrom(tokenWallet, to, amount));
    tokensSold = tokensSold.add(amount);
}

function extractOldTokens() external onlyOwner {
    ERC20(oldToken).transfer(_msgSender(), oldToken_amt);
    oldToken_amt = 0;
}

function exchangeToken(uint256 tokens) external {
    require(tokens <= ERC20(newToken).balanceOf(address(this)), "Not enough tokens in the reserve");
    require(ERC20(oldToken).transferFrom(_msgSender(), address(this), tokens), "Tokens cannot be transferred from user account");
    ERC20(newToken).transfer(_msgSender(), tokens);
    oldToken_amt = oldToken_amt + tokens;
}

function unstack(uint256 amount) external {
    require(
        _stakerMap[_msgSender()].stackedAmount >= amount,
        "Stake amount exceeded"
    );
    require(
        _mainTokenContract.transfer(
            _msgSender(),
            amount
        ),
        "Stake failed"
    );
    _stakerMap[_msgSender()].stackedAmount = _stakerMap[_msgSender()].stackedAmount.sub(amount);
    _totalStackedAmount = _totalStackedAmount.sub(amount);
    if (_stakerMap[_msgSender()].stackedAmount == 0) {
        _stakerCount = _stakerCount.sub(uint256(1));
    }
    emit Unstaked(_msgSender(), amount);
}

function claim(uint256 amount) external {
    require(
        _rewardsMap[_msgSender()] >= amount,
        "Claim amount exceeded"
    );
    _storeWalletContract.giveReward(_msgSender(), amount);
    _rewardsMap[_msgSender()] = _rewardsMap[_msgSender()].sub(amount);
    emit Claim(_msgSender(), amount);
}

function calcRewards() external returns(bool) {
    uint256 currentTimestamp = uint256(now);
    uint256 diff = currentTimestamp.sub(_stakerMap[_msgSender()].lastTimestamp);
    if (diff >= _rewardPeriod) {
        uint256 rewardDays = diff.div(_rewardPeriod);
        uint256 offsetTimestamp = diff.sub(_rewardPeriod.mul(rewardDays));
        if (rewardDays > _rewardMaxDays)
            return false;
        uint256 rewardsAmount = _stakerMap[_msgSender()].stackedAmount.div(_rewardPortion).mul(rewardDays);
        _rewardsMap[_msgSender()] = _rewardsMap[_msgSender()].add(rewardsAmount);
        _stakerMap[_msgSender()].lastTimestamp = currentTimestamp.sub(offsetTimestamp);
        return true;
    }
    return false;
}

function stake(uint256 amount) external {
    require(
        amount >= _minStakeAmount,
        "Too small amount"
    );
    require(
        _mainTokenContract.transferFrom(
            _msgSender(),
            address(this),
            amount
        ),
        "Stake failed"
    );
    if (_stakerMap[_msgSender()].stackedAmount == 0) {
        _stakerMap[_msgSender()].startTimestamp = uint256(now);
        _stakerMap[_msgSender()].lastTimestamp = uint256(now);
        _stakerCount = _stakerCount.add(uint256(1));
    }
    _stakerMap[_msgSender()].stackedAmount = _stakerMap[_msgSender()].stackedAmount.add(amount);
    _totalStackedAmount = _totalStackedAmount.add(amount);
    emit Staked(_msgSender(), amount);
}

function purchase() public {
    require(!purchased[msg.sender], "Cannot buy: Already purchased!");
    require(active, "Cannot buy: Market not active!");
    require(IERC1155(rarigang).balanceOf(seller, nftid) > 0, "Cannot buy: No more available!");
    require(IERC20(currency).balanceOf(msg.sender) >= price * 1e18, "Cannot buy: Need more coin!");
    IERC1155(rarigang).safeTransferFrom(seller, msg.sender, nftid, 1, "");
    IERC20(currency).transferFrom(msg.sender, 0x000000000000000000000000000000000000dEaD, price * 1e18);
    purchased[msg.sender] = true;
}

function buy() public payable returns(bool) {
    require(!halted);
    require(msg.value > 0);
    uint tokens = msg.value * 10 ** 18 / price();
    require(balances[owner] > tokens);
    if (stageThree) {
        preTge = false;
        stageOne = false;
        stageTwo = false;
        tokens = tokens + (tokens / 4);
    }
    if (stageTwo) {
        preTge = false;
        stageOne = false;
        stageThree = false;
        tokens = tokens + (tokens / 2);
    }
    if (stageOne) {
        preTge = false;
        stageTwo = false;
        stageThree = false;
        tokens = tokens + ((tokens / 4) * 3);
    }
    if (preTge) {
        stageOne = false;
        stageTwo = false;
        stageThree = false;
        tokens = tokens + (tokens * data1);
    }
    if (preTge) {
        require(safeAdd(presaleTokenSupply, tokens) < preTgeCap);
    } else {
        require(safeAdd(presaleTokenSupply, tokens) < safeSub(tgeCap, preTgeTokenSupply));
    }
    founder.transfer(msg.value);
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    balances[owner] = safeSub(balances[owner], tokens);
    if (preTge) {
        preTgeTokenSupply = safeAdd(preTgeTokenSupply, tokens);
    }
    presaleTokenSupply = safeAdd(presaleTokenSupply, tokens);
    presaleEtherRaised = safeAdd(presaleEtherRaised, msg.value);
    Buy(msg.sender, msg.value, tokens);
    TokensSent(msg.sender, tokens);
    ContributionReceived(msg.sender, msg.value);
    Transfer(owner, msg.sender, tokens);
    return true;
}

function enableTokenWithdrawals(address tokenAddr, bool notDefault) public onlyOwner noReentrancy {
    require(contractStage == 2);
    if (notDefault) {
        require(activeToken != 0x00);
    } else {
        activeToken = tokenAddr;
    }
    var d = distributionMap[tokenAddr];
    if (d.pct.length == 0) d.token = ERC20(tokenAddr);
    uint amount = d.token.balanceOf(this).sub(d.balanceRemaining);
    require(amount > 0);
    if (feePct > 0) {
        require(d.token.transfer(owner, _applyPct(amount, feePct)));
    }
    amount = d.token.balanceOf(this).sub(d.balanceRemaining);
    d.balanceRemaining = d.token.balanceOf(this);
    d.pct.push(_toPct(amount, finalBalance));
}

function modifyNextCap(uint time, uint cap) public onlyOwner {
    require(contractStage == 1);
    require(contributionCap <= cap && maxContractBalance >= cap);
    require(time > now);
    nextCapTime = time;
    nextContributionCap = cap;
}

function _ethDeposit() internal {
    assert(contractStage == 1);
    require(!whitelistIsActive || whitelistContract.isPaidUntil(msg.sender) > now);
    require(tx.gasprice <= maxGasPrice);
    require(this.balance <= maxContractBalance);
    var c = whitelist[msg.sender];
    uint newBalance = c.balance.add(msg.value);
    require(newBalance >= contributionMin);
    if (nextCapTime > 0 && nextCapTime < now) {
        contributionCap = nextContributionCap;
        nextCapTime = 0;
    }
    if (c.cap > 0) require(newBalance <= c.cap);
    else require(newBalance <= contributionCap);
    c.balance = newBalance;
    ContributorBalanceChanged(msg.sender, newBalance);
}

function checkContributorBalance(address addr) view public returns(uint balance, uint cap, uint remaining) {
    var c = whitelist[addr];
    if (contractStage == 2) return (c.balance, 0, 0);
    if (whitelistIsActive && whitelistContract.isPaidUntil(addr) < now) return (c.balance, 0, 0);
    if (c.cap > 0) cap = c.cap;
    else cap = contributionCap;
    if (cap.sub(c.balance) > maxContractBalance.sub(this.balance)) return (c.balance, cap, maxContractBalance.sub(this.balance));
    return (c.balance, cap, cap.sub(c.balance));
}

function withdraw(address tokenAddr) public {
    var c = whitelist[msg.sender];
    require(c.balance > 0);
    if (contractStage == 1) {
        uint amountToTransfer = c.balance;
        c.balance = 0;
        msg.sender.transfer(amountToTransfer);
        ContributorBalanceChanged(msg.sender, 0);
    } else {
        _withdraw(msg.sender, tokenAddr);
    }
}

function _withdraw(address receiver, address tokenAddr) internal {
    assert(contractStage == 2);
    var c = whitelist[receiver];
    if (tokenAddr == 0x00) {
        tokenAddr = activeToken;
    }
    var d = distributionMap[tokenAddr];
    require((ethRefundAmount.length > c.ethRefund) || d.pct.length > c.tokensClaimed[tokenAddr]);
    if (ethRefundAmount.length > c.ethRefund) {
        uint pct = _toPct(c.balance, finalBalance);
        uint ethAmount = 0;
        for (uint i = c.ethRefund; i < ethRefundAmount.length; i++) {
            ethAmount = ethAmount.add(_applyPct(ethRefundAmount[i], pct));
        }
        c.ethRefund = ethRefundAmount.length;
        if (ethAmount > 0) {
            receiver.transfer(ethAmount);
            EthRefunded(receiver, ethAmount);
        }
    }
    if (d.pct.length > c.tokensClaimed[tokenAddr]) {
        uint tokenAmount = 0;
        for (i = c.tokensClaimed[tokenAddr]; i < d.pct.length; i++) {
            tokenAmount = tokenAmount.add(_applyPct(c.balance, d.pct[i]));
        }
        c.tokensClaimed[tokenAddr] = d.pct.length;
        if (tokenAmount > 0) {
            require(d.token.transfer(receiver, tokenAmount));
            d.balanceRemaining = d.balanceRemaining.sub(tokenAmount);
            TokensWithdrawn(receiver, tokenAddr, tokenAmount);
        }
    }
}

function submitPool(uint amountInWei) public onlyOwner noReentrancy {
    require(contractStage == 1);
    require(receiverAddress != 0x00);
    require(block.number >= addressChangeBlock.add(6000));
    if (amountInWei == 0) amountInWei = this.balance;
    require(contributionMin <= amountInWei && amountInWei <= this.balance);
    finalBalance = this.balance;
    require(receiverAddress.call.value(amountInWei).gas(msg.gas.sub(5000))());
    if (this.balance > 0) ethRefundAmount.push(this.balance);
    contractStage = 2;
    PoolSubmitted(receiverAddress, amountInWei);
}

function hasOpened() public view returns(bool) {
    return (openingTime < block.timestamp && block.timestamp < closingTime);
}

function cancelWithdrawal() public onlyOwner returns(bool) {
    require(withdrawal.amount > 0, "There are no active withdrawal requests");
    emit WithdrawCanceled(withdrawal.receiver, withdrawal.amount, block.timestamp);
    withdrawal.amount = 0;
    return true;
}

function finalizeWithdraw() public onlyOwner returns(bool) {
    uint256 amount = withdrawal.amount;
    require(
        withdrawal.timestamp.add(delay) <= block.timestamp,
        "Withdrawal is not old enough to be finalized"
    );
    require(amount > 0, "There are no active withdrawal requests");
    withdrawal.amount = 0;
    ctsi.transfer(withdrawal.receiver, amount);
    emit WithdrawFinalized(withdrawal.receiver, amount);
    return true;
}

function _sendReward(uint _reward) private {
    uint _amount = _cappedReward(_reward);
    if (_reward > 0 && _amount == 0) {
        emit RewardFailure(now, msg.sender, _amount, "Not enough funds, or daily limit reached.");
        return;
    }
    if (msg.sender.call.value(_amount)()) {
        _useFromDailyLimit(_amount);
        totalRewarded += _amount;
        emit RewardSuccess(now, msg.sender, _amount);
    } else {
        emit RewardFailure(now, msg.sender, _amount, "Reward rejected by recipient (out of gas, or revert).");
    }
}

function updateAndGetRemaining() private returns(uint _amtRemaining) {
    if (today() > vars.lastDay) {
        vars.usedToday = 0;
        vars.lastDay = today();
    }
    uint112 _usedToday = vars.usedToday;
    uint112 _dailyLimit = vars.dailyLimit;
    return uint(_usedToday >= _dailyLimit ? 0 : _dailyLimit - _usedToday);
}

function getDailyLimitUsed() public view returns(uint) {
    return uint(today() > vars.lastDay ? 0 : vars.usedToday);
}

function _useFromDailyLimit(uint _amount) internal {
    uint _remaining = updateAndGetRemaining();
    require(_amount <= _remaining);
    vars.usedToday += uint112(_amount);
}

