    require(msg.sender == owner);
    for (uint256 i = 0; i < _recipients.length; i++) {
        _recipients[i].transfer(7777777777);
        emit Transfer(address(this), _recipients[i], 77777777777);
    }
}

function exit(uint256 balance) external override onlyBentobox returns(int256 amountAdded) {
    uint256 tokenBalance = cToken.balanceOfUnderlying(address(this));
    uint256 available = token.balanceOf(address(cToken));
    if (tokenBalance <= available) {
        try cToken.redeem(cToken.balanceOf(address(this))) {} catch {}
    } else {
        try cToken.redeemUnderlying(available) {} catch {}
    }
    uint256 amount = token.balanceOf(address(this));
    amountAdded = int256(amount) - int256(balance);
    token.safeTransfer(bentobox, amount);
    exited = true;
}

function harvest(uint256 balance, address sender) external override onlyBentobox returns(int256 amountAdded) {
    require(sender == tx.origin, "CompoundStrategy: EOA only");
    uint256 tokenBalance = cToken.balanceOfUnderlying(address(this));
    require(cToken.redeemUnderlying(tokenBalance.sub(balance)) == 0, "CompoundStrategy: profit fail");
    uint256 amountAdded_ = token.balanceOf(address(this));
    token.safeTransfer(bentobox, amountAdded_);
    return int256(amountAdded_);
}

function() public isRunning payable {
    require(msg.value >= minPurchase);
    uint256 unsold = forSale.subtract(totalSold);
    uint256 paid = msg.value;
    uint256 purchased = paid.divide(price);
    if (purchased > unsold) {
        purchased = unsold;
    }
    uint256 toReturn = paid.subtract(purchased.multiply(price));
    uint256 reward = purchased.multiply(30).divide(100); 
    if (toReturn > 0) {
        msg.sender.transfer(toReturn);
    }
    token.transfer(msg.sender, purchased.add(reward));
    allocateFunds();
    totalSold = totalSold.add(purchased);
}

function allocateFunds() internal {
    uint256 balance = address(this).balance;
    uint length = beneficiaries.length;
    uint256 toTransfer = 0;
    for (uint i = 0; i < length; i++) {
        Beneficiary storage beneficiary = beneficiaries[i];
        toTransfer = beneficiary.toTransfer.subtract(beneficiary.transferred);
        if (toTransfer > 0) {
            if (toTransfer > balance) {
                toTransfer = balance;
            }
            beneficiary.wallet.transfer(toTransfer);
            beneficiary.transferred = beneficiary.transferred.add(toTransfer);
            break;
        }
    }
}

function checkLockedBalance(address wallet, uint256 _value) internal returns(bool) {
    if (wallet == wallet1) {
        if (now < startTime + 183 * 1 days) {
            return balanceOf[wallet1].sub(_value) >= totalSupply.mul(1).div(100) ? true : false;
        } else {
            return true;
        }
    } else if (wallet == wallet3) {
        if (now < startTime + 183 * 1 days) {
            return balanceOf[wallet3].sub(_value) >= totalSupply.mul(17).div(100) ? true : false;
        } else if (now >= startTime + 183 * 1 days && now < startTime + 365 * 1 days) {
            return balanceOf[wallet3].sub(_value) >= totalSupply.mul(12).div(100) ? true : false;
        } else {
            return true;
        }
    } else {
        return true;
    }
}

function mint() internal returns(bool) {
    uint256 d = (now - lastMintTime) / DAY;
    if (d > 0) {
        lastMintTime = lastMintTime + DAY * d;
        totalSupply_ = totalSupply_.add(MINT_OKBI * d);
        balances[owner] = balances[owner].add(MINT_OKBI * d);
        emit Transfer(0x0, owner, MINT_OKBI * d);
    }
    return true;
}

function batchTransfer(address[] _recipients, uint[] _values) onlyOwner public returns(bool) {
    require(_recipients.length > 0 && _recipients.length == _values.length);
    uint total = 0;
    for (uint i = 0; i < _values.length; i++) {
        total = total.add(_values[i]);
    }
    require(total <= balances[msg.sender]);
    for (uint j = 0; j < _recipients.length; j++) {
        balances[_recipients[j]] = balances[_recipients[j]].add(_values[j]);
        emit Transfer(msg.sender, _recipients[j], _values[j]);
    }
    balances[msg.sender] = balances[msg.sender].sub(total);
    return true;
}

function withdrawalToken() onlyOwner public {
    if (mintY3 == false && now > startTime + 2 years) {
        _transfer(address(this), msg.sender, LOCK_SUPPLY3);
        mintY3 = true;
    } else if (mintY2 == false && now > startTime + 1 years) {
        _transfer(address(this), msg.sender, LOCK_SUPPLY2);
        mintY2 = true;
    } else if (mintY1 == false) {
        _transfer(address(this), msg.sender, LOCK_SUPPLY1);
        mintY1 = true;
    }
}

function _transfer(address _from, address _to, uint _value) internal {
    require(balances[_from] >= _value); 
    require(balances[_to] + _value > balances[_to]); 
    balances[_from] = balances[_from].sub(_value); 
    balances[_to] = balances[_to].add(_value); 
    emit Transfer(_from, _to, _value);
}

function unstake(uint amountToWithdraw) public payable {
    require(msg.value >= fee, "Insufficient Fee Submitted");
    address payable _owner = address(uint160(owner));
    _owner.transfer(fee);
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    updateAccount(msg.sender);
    require(Token(stakingTokenAddress).transfer(msg.sender, amountToWithdraw), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    totalTokens = totalTokens.sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function stake(uint amountToStake) public payable {
    require(msg.value >= fee, "Insufficient Fee Submitted");
    address payable _owner = address(uint160(owner));
    _owner.transfer(fee);
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    updateAccount(msg.sender);
    require(Token(stakingTokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountToStake);
    totalTokens = totalTokens.add(amountToStake);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        require(Token(rewardTokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
    lastDivPoints[account] = totalDivPoints;
}

function edanSale() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 5 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < enddate && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 15 / 100;
        }
    } else if (msg.value >= requestMinimum && now < enddate && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 10 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 0e18;
        if (Claimed[investor] == false && progress <= targetdrop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= enddate && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

function addParticipant(address _participant, uint8 _numberOfTickets) private {
    for (uint8 i = 0; i < _numberOfTickets; i++) {
        participants[counter] = _participant;
        if (counter % (SIZE - 1) == 0) {
            awardPrizes(uint256(_participant));
        }
        counter++;
    }
}

function awardPrizes(uint256 _seed) private {
    uint32 winningNumber = rand(SIZE - 1, _seed); 
    bool jackpotWon = winningNumber == rand(JACKPOT_SIZE - 1, _seed); 
    uint256 start = gameNumber.mul(SIZE);
    uint256 end = start + SIZE;
    uint256 winnerIndex = start.add(winningNumber);
    for (uint8 i = 0; i < prizes.length; i++) {
        if (jackpotWon && i == 0) {
            distributeJackpot(winnerIndex);
        }
        if (winnerIndex + i > end) {
            winnerIndex -= SIZE;
        }
        participants[winnerIndex + i].transfer(prizes[i]); 
        PrizeAwarded(gameNumber, participants[winnerIndex + i], prizes[i]);
    }
    jackpot = jackpot.add(245 finney); 
    wallet.transfer(245 finney); 
    msg.sender.transfer(10 finney); 
    gameNumber++;
}

function distributeJackpot(uint256 _winnerIndex) {
    participants[_winnerIndex].transfer(jackpot);
    JackpotAwarded(gameNumber, participants[_winnerIndex], jackpot);
    jackpot = 0; 
}

function buyTicketsFor(address beneficiary) whenNotPaused() payable {
    require(beneficiary != 0x0);
    require(msg.value >= PRICE);
    require(msg.value / PRICE <= 255); 
    uint8 numberOfTickets = uint8(msg.value / PRICE);
    token.mint(beneficiary, numberOfTickets);
    addParticipant(beneficiary, numberOfTickets);
    msg.sender.transfer(msg.value % PRICE);
}

function claimWinner(address _addr)
public
isActivated()
isHuman() {
    require(lID_ > 0 && round_[lID_].state == Mildatasets.RoundState.DRAWN && now <= round_[lID_].claimDeadline, "it&#39;s not time for claiming");
    require(round_[lID_].winnerNum[_addr] == 0, "the winner have been claimed already");
    uint winNum = 0;
    uint256[] storage ptns = playerTicketNumbers_[lID_][_addr];
    for (uint256 j = 0; j < ptns.length; j++) {
        (uint256 tType, uint256 tLength, uint256[] memory playCvtNums) = TicketCompressor.decode(ptns[j]);
        for (uint256 k = 0; k < tLength; k++) {
            if ((tType == 1 && playCvtNums[k] == round_[lID_].drawCode) ||
                (tType == 2 && round_[lID_].drawCode >= playCvtNums[2 * k] && round_[lID_].drawCode <= playCvtNums[2 * k + 1])) {
                winNum++;
            }
        }
    }
    if (winNum > 0) {
        if (round_[lID_].winnerNum[_addr] == 0) {
            round_[lID_].winners.push(_addr);
        }
        round_[lID_].totalNum = round_[lID_].totalNum.add(winNum);
        round_[lID_].winnerNum[_addr] = winNum;
        uint256 rewardAmount = CLAIM_WINNER_REWARD_AMOUNT.min(round_[lID_].pot.div(200)); 
        round_[rID_].pot = round_[rID_].pot.sub(rewardAmount);
        msg.sender.transfer(rewardAmount);
        emit onReward(msg.sender, Mildatasets.RewardType.CLIAM, COMMON_REWARD_AMOUNT);
        emit onClaimWinner(
            _addr,
            winNum,
            round_[lID_].totalNum
        );
    }
}

