    uint256 bonusRate = rate;
    uint[1] memory weiRaisedStartsBounds = [uint(0)];
    uint[1] memory weiRaisedEndsBounds = [uint(668804397617956939991)];
    uint64[1] memory timeStartsBounds = [uint64(1601640000)];
    uint64[1] memory timeEndsBounds = [uint64(1601812795)];
    uint[1] memory weiRaisedAndTimeRates = [uint(124)];
    for (uint i = 0; i < 1; i++) {
        bool weiRaisedInBound = (weiRaisedStartsBounds[i] <= weiRaised) && (weiRaised < weiRaisedEndsBounds[i]);
        bool timeInBound = (timeStartsBounds[i] <= now) && (now < timeEndsBounds[i]);
