        uint totalCovfefes = totalSupply();
        uint resultIndex = 0;
        uint covfefeId;
        for (covfefeId = 0; covfefeId <= totalCovfefes; covfefeId++) {
            if (covfefeIndexToOwner[covfefeId] == _owner) {
                result[resultIndex] = covfefeId;
                resultIndex++;
