}

function allocate() public notLocked notAllocated onlyOwner {
    require(token.balanceOf(address(this)) == totalAllocation);
    allocations[teamReserveWallet] = teamReserveAllocation;
    allocations[firstReserveWallet] = firstReserveAllocation;
    Allocated(teamReserveWallet, teamReserveAllocation);
    Allocated(firstReserveWallet, firstReserveAllocation);
    lock();
}

function teamVestingStage() public view onlyTeamReserve returns(uint256) {
    uint256 vestingMonths = teamTimeLock.div(teamVestingStages);
    uint256 stage = (block.timestamp).sub(firstTime).div(vestingMonths);
    if (stage > teamVestingStages) {
        stage = teamVestingStages;
    }
    return stage;
}

function claimTeamReserve() onlyTeamReserve locked public {
    uint256 vestingStage = teamVestingStage();
    uint256 totalUnlocked = vestingStage.mul(allocations[teamReserveWallet]).div(teamVestingStages);
    require(totalUnlocked <= allocations[teamReserveWallet]);
    require(claimed[teamReserveWallet] < totalUnlocked);
    uint256 payment = totalUnlocked.sub(claimed[teamReserveWallet]);
    claimed[teamReserveWallet] = totalUnlocked;
    require(token.transfer(AWD, payment));
    Distributed(AWD, payment);
}

function claimTokenReserve() onlyTokenReserve locked public {
    address reserveWallet = msg.sender;
    require(block.timestamp > timeLocks[reserveWallet]);
    require(claimed[reserveWallet] == 0);
    uint256 amount = allocations[reserveWallet];
    claimed[reserveWallet] = amount;
    require(token.transfer(CEO, amount.mul(CEO_SHARE).div(DIV)));
    require(token.transfer(COO, amount.mul(COO_SHARE).div(DIV)));
    require(token.transfer(CTO, amount.mul(CTO_SHARE).div(DIV)));
    require(token.transfer(CMO, amount.mul(CMO_SHARE).div(DIV)));
    require(token.transfer(CPO, amount.mul(CPO_SHARE).div(DIV)));
    require(token.transfer(CEO_TEAM, amount.mul(CEO_TEAM_SHARE).div(DIV)));
    require(token.transfer(AWD, amount.mul(AWD_SHARE).div(DIV)));
    Distributed(CEO, amount.mul(CEO_SHARE).div(DIV));
    Distributed(COO, amount.mul(COO_SHARE).div(DIV));
    Distributed(CTO, amount.mul(CTO_SHARE).div(DIV));
    Distributed(CMO, amount.mul(CMO_SHARE).div(DIV));
    Distributed(CPO, amount.mul(CPO_SHARE).div(DIV));
    Distributed(CEO_TEAM, amount.mul(CEO_TEAM_SHARE).div(DIV));
    Distributed(AWD, amount.mul(AWD_SHARE).div(DIV));
}

function canCollect() public view onlyReserveWallets returns(bool) {
    return block.timestamp > timeLocks[msg.sender] && claimed[msg.sender] == 0;
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(isCrowdsalePaused == false);
    require(validPurchase());
    require(isWithinContributionRange());
    require(TOKENS_SOLD < maxTokensToSaleInClosedPreSale);
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(ratePerWei);
    uint256 bonus = determineBonus(tokens);
    tokens = tokens.add(bonus);
    weiRaised = weiRaised.add(weiAmount);
    token.transfer(beneficiary, tokens);
    emit TokenPurchase(owner, beneficiary, weiAmount, tokens);
    TOKENS_SOLD = TOKENS_SOLD.add(tokens);
    forwardFunds();
}

function manualTokenTransfer(address receiver, uint value) public onlyOwner {
    value = value * 10 ** 18;
    token.transfer(receiver, value);
    TOKENS_SOLD = TOKENS_SOLD.add(value);
}

constructor(uint256 _startTime, address _wallet, address _tokenAddress) public {
    require(_wallet != 0x0);
    require(_startTime >= now);
    startTime = _startTime;
    endTime = startTime + totalDurationInDays;
    require(endTime >= startTime);
    owner = _wallet;
    maxTokensToSaleInClosedPreSale = 60000000 * 10 ** 18;
    bonusInPreSalePhase1 = 50;
    bonusInPreSalePhase2 = 40;
    token = TokenInterface(_tokenAddress);
}

function determineBonus(uint tokens) internal view returns(uint256 bonus) {
    uint256 timeElapsed = now - startTime;
    uint256 timeElapsedInDays = timeElapsed.div(1 days);
    if (timeElapsedInDays < 15) {
        bonus = tokens.mul(bonusInPreSalePhase1);
        bonus = bonus.div(100);
        require(TOKENS_SOLD.add(tokens.add(bonus)) <= maxTokensToSaleInClosedPreSale);
    }
    else if (timeElapsedInDays >= 15 && timeElapsedInDays < 31) {
        bonus = tokens.mul(bonusInPreSalePhase2);
        bonus = bonus.div(100);
        require(TOKENS_SOLD.add(tokens.add(bonus)) <= maxTokensToSaleInClosedPreSale);
    } else {
        bonus = 0;
    }
}

function isWithinContributionRange() internal constant returns(bool) {
    uint timePassed = now.sub(startTime);
    timePassed = timePassed.div(1 days);
    if (timePassed < 15)
        require(msg.value >= minimumContributionPresalePhase1);
    else if (timePassed >= 15 && timePassed < 31)
        require(msg.value >= minimumContributionPresalePhase2);
    else
        revert(); 
    return true;
}

function() public payable atStage(Stages.ICO) {
    require(!stopped && msg.sender != owner && now <= enddate);
    no_of_tokens = safeMul(msg.value, _price_tokn);
    transferTokens(msg.sender, no_of_tokens);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 1500;
    } else {
        tokens = msg.value * 1000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function emergencyWithdraw(uint256 id) public onlyOwner {
    AuctionInfo storage auction = auctionsById[id];
    require(auction.beneficiary != address(0), "DRFAuction::create: auction does not exist");
    require(now >= auction.auctionEnd, "DRFAuction::emergencyWithdraw: the auction has not ended");
    require(!auction.auctionEnded, "DRFAuction::emergencyWithdraw: auction ended and item sent");
    _emergencyWithdraw(auction.highestBidder, id);
    emit Withdrawn(auction.highestBidder, id, auction.highestBid);
}

function withdraw(uint256 id) public nonReentrant {
    AuctionInfo storage auction = auctionsById[id];
    uint256 amount = balanceOf(msg.sender, id);
    require(auction.beneficiary != address(0), "DRFAuction::withdraw: auction does not exist");
    require(amount > 0, "DRFAuction::withdraw: cannot withdraw 0");
    require(
        auction.highestBidder != msg.sender,
        "DRFAuction::withdraw: you are the highest bidder and cannot withdraw"
    );
    super.withdraw(id);
    emit Withdrawn(msg.sender, id, amount);
}

function ended(uint256 id) public view returns(bool) {
    return now >= auctionsById[id].auctionEnd;
}

function create(
    uint256 id,
    address beneficiaryAddress,
    uint256 fee,
    uint256 start,
    uint256 duration,
    uint256 extension 
) public onlyOwner {
    AuctionInfo storage auction = auctionsById[id];
    require(auction.beneficiary == address(0), "DRFAuction::create: auction already created");
    auction.beneficiary = beneficiaryAddress;
    auction.fee = fee;
    auction.auctionStart = start;
    auction.auctionEnd = start.add(duration * 1 days);
    auction.originalAuctionEnd = start.add(duration * 1 days);
    auction.extension = extension * 60;
    auctions.push(id);
    uint256 tokenId = IERC1155(drfLtdAddress).create(1, 1, "", "");
    require(tokenId > 0, "DRFAuction::create: ERC1155 create did not succeed");
    auction.nft = tokenId;
}

function bid(uint256 id, uint256 amount) public nonReentrant {
    AuctionInfo storage auction = auctionsById[id];
    require(auction.beneficiary != address(0), "DRFAuction::bid: auction does not exist");
    require(now >= auction.auctionStart, "DRFAuction::bid: auction has not started");
    require(now <= auction.auctionEnd, "DRFAuction::bid: auction has ended");
    uint256 newAmount = amount.add(balanceOf(msg.sender, id));
    require(newAmount > auction.highestBid, "DRFAuction::bid: bid is less than highest bid");
    auction.highestBidder = msg.sender;
    auction.highestBid = newAmount;
    if (auction.extension > 0 && auction.auctionEnd.sub(now) <= auction.extension) {
        auction.auctionEnd = now.add(auction.extension);
    }
    super.bid(id, amount);
    emit BidPlaced(msg.sender, id, amount);
}

function end(uint256 id) public nonReentrant {
    AuctionInfo storage auction = auctionsById[id];
    require(auction.beneficiary != address(0), "DRFAuction::end: auction does not exist");
    require(now >= auction.auctionEnd, "DRFAuction::end: the auction has not ended");
    require(!auction.auctionEnded, "DRFAuction::end: auction already ended");
    auction.auctionEnded = true;
    _end(id, auction.highestBidder, auction.beneficiary, runner, auction.fee, auction.highestBid);
    IERC1155(drfLtdAddress).safeTransferFrom(address(this), auction.highestBidder, auction.nft, 1, "");
    emit Ended(auction.highestBidder, id, auction.highestBid);
}

