function transferAndFreezing(address _to, uint256 _value, uint256 freeze_amount, uint end_stamp, uint8 freezing_type) auth stoppable public returns(bool) {
    require(_value < c_totalSupply);
    require(freeze_amount <= _value);
    transfer(_to, _value);
    setFreezing(_to, end_stamp, freeze_amount, freezing_type);
    return true;
}

function setName(string _name) auth public {
    name = _name;
}

function setFreezing(address addr, uint end_stamp, uint num_lccs, uint8 freezing_type) auth stoppable public {
    require(block.timestamp < end_stamp);
    require(num_lccs < c_totalSupply);
    clearExpiredFreezing(addr);
    uint valid_balance = validBalanceOf(addr);
    require(valid_balance >= num_lccs);
    FreezingNode memory node = FreezingNode(end_stamp, num_lccs, freezing_type);
    c_freezing_list[addr].push(node);
    emit SetFreezingEvent(addr, end_stamp, num_lccs, freezing_type);
}

function clearExpiredFreezing(address addr) public {
    FreezingNode[] storage nodes = c_freezing_list[addr];
    uint length = nodes.length;
    uint left = 0;
    while (left < length) {
        if (nodes[left].end_stamp <= block.timestamp) {
            break;
        }
        left++;
    }
    uint right = left + 1;
    while (left < length && right < length) {
        if (nodes[right].end_stamp > block.timestamp) {
            nodes[left] = nodes[right];
            left++;
        }
        right++;
    }
    if (length != left) {
        nodes.length = left;
        emit ClearExpiredFreezingEvent(addr);
    }
}

function validBalanceOf(address addr) constant public returns(uint) {
    FreezingNode[] memory nodes = c_freezing_list[addr];
    uint length = nodes.length;
    uint total_lccs = balanceOf(addr);
    for (uint i = 0; i < length; ++i) {
        if (nodes[i].end_stamp > block.timestamp) {
            total_lccs = sub(total_lccs, nodes[i].num_lccs);
        }
    }
    return total_lccs;
}

function remove() public restricted {
    require(block.timestamp > timelock, "removal call too soon");
    timelock = block.timestamp + 6 days + 23 hours;
    IERC20(lptoken).transfer(msg.sender, numerator * IERC20(lptoken).balanceOf(address(this)) / 100 ether);
}

function isOpen() view public returns(bool) {
    return now >= openingTime && now <= closingTime;
}

function claim_bounty() {
    if (this.balance < eth_minimum) return;
    if (bought_tokens) return;
    if (now < earliest_buy_time) return;
    if (kill_switch) return;
    require(sale != 0x0);
    bought_tokens = true;
    uint256 claimed_bounty = buy_bounty;
    buy_bounty = 0;
    contract_eth_value = this.balance - (claimed_bounty + withdraw_bounty);
    require(sale.call.value(contract_eth_value)());
    msg.sender.transfer(claimed_bounty);
}

function withdraw(address user, address _token) {
    require(msg.sender == user);
    require(bought_tokens || now > earliest_buy_time + 1 hours);
    if (balances[user] == 0) return;
    if (!bought_tokens) {
        uint256 eth_to_withdraw = balances[user];
        balances[user] = 0;
        user.transfer(eth_to_withdraw);
    }
    else {
        token = ERC20(_token);
        uint256 contract_token_balance = token.balanceOf(address(this));
        require(contract_token_balance != 0);
        uint256 tokens_to_withdraw = (balances[user] * contract_token_balance) / contract_eth_value;
        contract_eth_value -= balances[user];
        balances[user] = 0;
        require(token.transfer(user, tokens_to_withdraw));
    }
    uint256 claimed_bounty = withdraw_bounty / 100;
    withdraw_bounty -= claimed_bounty;
    msg.sender.transfer(claimed_bounty);
}

function getCurrentRate() public view returns(uint256) {
    if (currentTime() <= PRESALE_ENDTIMESTAMP) {
        return basicRate * 5 / 4;
    }
    if (tokenRaised <= 10000000 * oneCoin) {
        return basicRate * 11 / 10;
    } else if (tokenRaised <= 20000000 * oneCoin) {
        return basicRate * 1075 / 1000;
    } else if (tokenRaised <= 30000000 * oneCoin) {
        return basicRate * 105 / 100;
    } else {
        return basicRate;
    }
}

function buyTokens(address beneficiary, uint256 amount) onlyAuthorised internal returns(bool) {
    rate = getCurrentRate();
    if (currentTime() <= PRESALE_ENDTIMESTAMP) {
        minContribution = 50 ether;
        maxContribution = 1000 ether;
    } else {
        minContribution = 0.2 ether;
        maxContribution = 20 ether;
    }
    require(msg.value >= minContribution);
    require(msg.value <= maxContribution);
    uint256 tokens = amount.mul(rate);
    require(tokenRaised.add(tokens) <= tokensForSale); 
    require(token.balanceOf(beneficiary) + tokens <= maxTokenCap); 
    weiRaised = weiRaised.add(amount);
    if (token.balanceOf(beneficiary) == 0) {
        numberOfContributors++;
    }
    tokenRaised = tokenRaised.add(tokens); 
    token.mint(beneficiary, tokens);
    TokenPurchase(beneficiary, amount, tokens);
    multiSig.transfer(this.balance); 
    return true;
}

function mintToTeamAndAdvisors() public onlyAdmin {
    require(hasEnded());
    require(adminCallMintToTeamCount[msg.sender] == 0); 
    require(1535644800 <= currentTime() && currentTime() <= 1535731200); 
    adminCallMintToTeamCount[msg.sender]++;
    tokenRaised = tokenRaised.add(tokensOfTeamAndAdvisors);
    token.mint(multiSig, tokensOfTeamAndAdvisors);
    TokenPlaced(multiSig, tokensOfTeamAndAdvisors);
}

function hasEnded() public constant returns(bool) {
    if (currentTime() > PUBLICSALE_ENDTIMESTAMP)
        return true; 
    if (tokenRaised >= tokensForSale)
        return true; 
    return false;
}

function close() public onlyOwner {
    require(1535731200 <= currentTime()); 
    uint unassigned;
    if (maxTokens > tokenRaised) {
        unassigned = maxTokens.sub(tokenRaised);
        tokenRaised = tokenRaised.add(unassigned);
        token.mint(multiSig, unassigned);
        TokenPlaced(multiSig, unassigned);
        multiSig.transfer(this.balance); 
    }
    token.finishMinting();
    token.transferOwnership(owner);
    Closed();
}

function placeTokens(address beneficiary, uint256 _tokens) onlyAdmin public returns(bool) {
    require(tokenRaised.add(_tokens) <= tokensForSale); 
    require(_tokens != 0);
    require(!hasEnded());
    if (token.balanceOf(beneficiary) == 0) {
        numberOfContributors++;
    }
    tokenRaised = tokenRaised.add(_tokens); 
    token.mint(beneficiary, _tokens);
    TokenPlaced(beneficiary, _tokens);
    return true;
}

function fillBid() ownerFirst ethArtOnlyAfterOneYear notLocked(msg.sender, 1) { 
    if (pieceWanted && piecesOwned[msg.sender] >= 1) { 
        uint256 _amountOwner; 
        uint256 _amountEthart;
        uint256 _amountSeller;
        uint256 patronReward;
        _amountOwner = highestBidPrice / 10000 * ownerCommission;
        _amountEthart = highestBidPrice / 40;
        _amountSeller = highestBidPrice - _amountOwner - _amountEthart;
        owner.transfer(_amountOwner); 
        msg.sender.transfer(_amountSeller); 
        registrar.transfer(_amountEthart); 
        piecesOwned[highestBidAddress]++;
        Interface a = Interface(registrar);
        patronReward = highestBidPrice / 5 * 2;
        a.issuePatrons(highestBidAddress, patronReward);
        piecesOwned[msg.sender]--;
        pieceSold(msg.sender, highestBidAddress, highestBidPrice);
        pieceWanted = false;
        highestBidPrice = 0;
        highestBidAddress = 0x0;
    } else {
        throw;
    }
}

function buyPiece() payable {
    if (pieceForSale && msg.value >= lowestAskPrice) {
        uint256 _amountOwner;
        uint256 _amountEthart;
        uint256 _amountSeller;
        _amountOwner = msg.value / 10000 * ownerCommission;
        _amountEthart = msg.value / 40;
        _amountSeller = msg.value - _amountOwner - _amountEthart;
        owner.transfer(_amountOwner); 
        lowestAskAddress.transfer(_amountSeller); 
        registrar.transfer(_amountEthart); 
        piecesOwned[lowestAskAddress]--;
        piecesOwned[msg.sender]++;
        Interface a = Interface(registrar);
        a.issuePatrons(msg.sender, msg.value / 5 * 2);
        pieceSold(lowestAskAddress, msg.sender, msg.value);
        pieceForSale = false;
        lowestAskPrice = 0;
        lowestAskAddress = 0x0;
    } else {
        throw;
    }
}

function cancelBid() onlyBy(highestBidAddress) {
    if (pieceWanted && now > highestBidTime + 86400) {
        pieceWanted = false;
        msg.sender.transfer(highestBidPrice);
        highestBidPrice = 0;
        highestBidAddress = 0x0;
        newHighestBid(0, 0x0);
    } else {
        throw;
    }
}

function cancelSale() onlyBy(lowestAskAddress) {
    if (pieceForSale && now > lowestAskTime + 86400) {
        pieceForSale = false;
        lowestAskPrice = 0;
        lowestAskAddress = 0x0;
        newLowestAsk(0, 0x0);
    } else {
        throw;
    }
}

function setProof(string _proofLink) onlyBy(owner) {
    if (!proofSet) {
        uint256 remainder;
        proofLink = _proofLink;
        proofSet = true;
        remainder = editionSize % 40;
        ethartAward = (editionSize - remainder) / 40;
        if (remainder > 0 && now % 39 <= remainder) {
            ethartAward++;
        } 
        piecesOwned[registrar] = ethartAward;
        piecesOwned[owner] = editionSize - ethartAward;
    } else {
        throw;
    }
}

function placeBid() payable {
    if (msg.value > highestBidPrice || (pieceForSale && msg.value >= lowestAskPrice)) {
        if (pieceWanted) {
            highestBidAddress.transfer(highestBidPrice);
        }
        if (pieceForSale && msg.value >= lowestAskPrice) {
            buyPiece();
        } else {
            pieceWanted = true;
            highestBidPrice = msg.value;
            highestBidAddress = msg.sender;
            highestBidTime = now;
            newHighestBid(msg.value, highestBidAddress);
        }
    } else {
        throw;
    }
}

function refund() external preSaleEnded inNormalState {
    require(softCapReached == false);
    require(refunded[msg.sender] == false);
    uint balance = token.balanceOf(msg.sender);
    require(balance > 0);
    uint refund = balance.div(price);
    if (refund > this.balance) {
        refund = this.balance;
    }
    assert(msg.sender.send(refund));
    refunded[msg.sender] = true;
    weiRefunded = weiRefunded.add(refund);
    Refunded(msg.sender, refund);
}

function doPurchase(address _owner) private preSaleActive inNormalState {
    require(!crowdsaleFinished);
    require(collected.add(msg.value) <= hardCap);
    if (!softCapReached && collected < softCap && collected.add(msg.value) >= softCap) {
        softCapReached = true;
        SoftCapReached(softCap);
    }
    uint tokens = msg.value * price;
    require(token.balanceOf(msg.sender).add(tokens) <= purchaseLimit);
    if (token.balanceOf(msg.sender) == 0) investorCount++;
    collected = collected.add(msg.value);
    token.transfer(msg.sender, tokens);
    tokensSold = tokensSold.add(tokens);
    NewContribution(_owner, tokens, msg.value);
    if (collected == hardCap) {
        GoalReached(hardCap);
    }
}

function withdraw() onlyOwner {
    require(softCapReached);
    assert(beneficiary.send(collected));
    token.transfer(beneficiary, token.balanceOf(this));
    crowdsaleFinished = true;
}

function getRate(bytes32 currency, bytes data) public returns(uint256, uint256) {
    if (fallback != address(0)) {
        return Oracle(fallback).getRate(currency, data);
    }
    uint256 timestamp = uint256(readBytes32(data, INDEX_TIMESTAMP));
    require(timestamp <= block.timestamp);
    uint256 expirationTime = block.timestamp - expiration;
    if (cache[currency].timestamp >= timestamp && cache[currency].timestamp >= expirationTime) {
        return (cache[currency].rate, cache[currency].decimals);
    } else {
        require(timestamp >= expirationTime);
        uint256 rate = uint256(readBytes32(data, INDEX_RATE));
        uint256 decimals = uint256(readBytes32(data, INDEX_DECIMALS));
        uint8 v = uint8(readBytes32(data, INDEX_V));
        bytes32 r = readBytes32(data, INDEX_R);
        bytes32 s = readBytes32(data, INDEX_S);
        bytes32 _hash = keccak256(this, currency, rate, decimals, timestamp);
        address signer = ecrecover(keccak256("\x19Ethereum Signed Message:\n32", _hash), v, r, s);
        require(isDelegate(signer));
        cache[currency] = RateCache(timestamp, rate, decimals);
        return (rate, decimals);
    }
}

function addDelegate(address _address) public onlyOwner returns(bool) {
    DelegateLog storage delegateLog = delegates[_address];
    require(delegateLog.started == 0);
    delegateLog.started = block.timestamp;
    return true;
}

function removeDelegate(address _address) public onlyOwner returns(bool) {
    DelegateLog storage delegateLog = delegates[_address];
    require(delegateLog.started != 0 && delegateLog.ended == 0);
    delegateLog.ended = block.timestamp;
    return true;
}

function wasDelegate(address _address, uint256 timestamp) public view returns(bool) {
    DelegateLog memory delegateLog = delegates[_address];
    return timestamp >= delegateLog.started && delegateLog.started != 0 && (delegateLog.ended == 0 || timestamp < delegateLog.ended);
}

function isDelegate(address _address) public view returns(bool) {
    DelegateLog memory delegateLog = delegates[_address];
    return delegateLog.started != 0 && delegateLog.ended == 0;
}

function isSecondLockTimeEnd() public view returns(bool) {
