function settleBet(bytes32 reveal, bytes32 blockHash) external {
    bytes32 commit = keccak256(abi.encodePacked(reveal));
    Bet storage bet = bets[commit];
    uint amount = bet.amount;
    uint placeBlockNumber = bet.placeBlockNumber;
    uint8 roll = bet.roll;
    bool lessThan = bet.lessThan;
    bool isInvited = bet.isInvited;
    address player = bet.player;
    require(amount != 0);
    require(block.number > placeBlockNumber);
    require(block.number <= placeBlockNumber + BET_EXPIRATION_BLOCKS);
    require(blockhash(placeBlockNumber) == blockHash);
    bet.amount = 0;
    bytes32 entropy = keccak256(abi.encodePacked(reveal, blockhash(placeBlockNumber)));
    uint dice = uint(entropy) % 100 + 1;
    uint diceWinAmount = getDiceWinAmount(amount, roll, lessThan, isInvited);
    maxPendingPayouts = maxPendingPayouts.sub(diceWinAmount);
    uint diceWin = 0;
    if ((lessThan && dice <= roll) || (!lessThan && dice >= roll)) { 
        diceWin = amount.add(diceWinAmount);
        safeSendFunds(player, diceWin);
    }
    emit LogResult(commit, player, roll, lessThan, dice, amount, diceWin, diceWin == 0 ? 1 : 2, now);
}

function getVisibleType(List storage ds, uint256 ansHash) internal view returns(uint256) {
    Data storage d = ds.map[ansHash];
    if (d.ownerIds.contains(msg.sender)) {
        return VISABLE_OWNER;
    } else if (d.answer.length == d.aCount) {
        return VISABLE_FINAL;
    } else if (ds.buyer[ansHash].contains(msg.sender)) {
        return VISABLE_BUYED;
    } else if ((now - d.replyAt) > HIDE_TIME && ds.sellPriceMap[ansHash] == 0) {
        return VISABLE_ALL;
    }
    return VISABLE_NONE;
}

function countByGrand(List storage ds) internal view returns(uint256) {
    if (ds.size == 0) return 0;
    uint256 count = 0;
    uint256 _lastAt = now;
    uint256 lastIdx = ds.size - 1;
    Data memory d = get(ds, lastIdx - count);
    while ((_lastAt - d.replyAt) <= GRAND_TOTAL_TIME) {
        count++;
        _lastAt = d.replyAt;
        if (count > lastIdx) return count;
        d = get(ds, lastIdx - count);
    }
    return count;
}

function getWinReply(Data storage d) internal view returns(PlayerReply.Data storage) {
    PlayerReply.Data storage pr = d.replys.getWin();
    if (pr.isWined()) return pr;
    if (d.replayCount > 0 && getOverTimeLeft(d) == 0) return d.replys.getLastReply();
    return pr;
}

function getOverTimeLeft(Data storage d) internal view returns(uint256) {
    if (d.replayCount == 0) return 0;
    uint256 time = (d.replayCount * d.plusAwardTime) + d.initAwardTime;
    uint256 spendT = (now - d.firstReplayAt);
    if (time < spendT) return 0;
    return time - spendT;
}

function buy(address recipient) payable {
    if (recipient == 0x0) throw;
    if (msg.value < MIN_ETHER) throw;
    if (_saleState == TokenSaleState.Frozen) throw;
    if ((_saleState == TokenSaleState.Initial || _saleState == TokenSaleState.Presale) && presaleSupply >= presaleAllocation) throw;
    if ((_saleState == TokenSaleState.Initial || _saleState == TokenSaleState.Presale) && presaleEtherRaised >= etherCap) throw;
    updateTokenSaleState();
    uint tokens = mul(msg.value, price());
    if (tokens <= 0) throw;
    balances[recipient] = add(balances[recipient], tokens);
    totalTokens = add(totalTokens, tokens);
    if (_saleState == TokenSaleState.Initial || _saleState == TokenSaleState.Presale) {
        presaleEtherRaised = add(presaleEtherRaised, msg.value);
        presaleSupply = add(presaleSupply, tokens);
    }
    founder.transfer(msg.value);
    Transfer(0, recipient, tokens);
    Buy(recipient, msg.value, tokens);
}

function deposit(uint256 amount) public returns(uint256) { 
    require(ERC20Token(BOMB_CONTRACT).transferFrom(address(msg.sender), address(this), amount), "TransferFailed");
    uint256 tokensToBurn = findOnePercent(amount);
    uint256 actual = amount.sub(tokensToBurn);
    balanceOf[msg.sender] += actual;
    _totalSupply += actual;
    emit Deposit(msg.sender, amount);
    emit Transfer(address(this), address(msg.sender), actual);
    return actual;
}

receive() external payable {
    require(presaleStarted, "Presale not started");
    require(!presaleEnded, "Presale ended");
    require(block.timestamp < presaleEnd, "Presale time's up");
    uint256 amount = msg.value + balances[msg.sender];
    require(amount >= minPerUser, "Below buy-in");
    require(amount <= maxPerUser, "Over buy-in");
    balances[msg.sender] = amount;
    if (collected() >= presaleLimit) {
        presaleEnded = true;
    }
}

function refundGameAfterLongInactivity() {
    require(block.number.sub(gameStarted) >= INACTIVITY);
    require(counter % SIZE != 0); 
    for (uint8 i = 0; i < counter % SIZE; i++) { 
        participants[gameNumber][i].transfer(PRICE);
    }
    counter -= counter % SIZE;
    GameRefunded(gameNumber);
    increaseGame();
}

function awardPrizes() private {
    uint256 winnerIndex = rand(SIZE);
    bool jackpotWon = winnerIndex == rand(JACKPOT_SIZE);
    for (uint8 i = 0; i < prizes.length; i++) {
        if (jackpotWon && i == 0) {
            distributeJackpot(winnerIndex);
        }
        participants[gameNumber][winnerIndex % SIZE].transfer(prizes[i]); 
        PrizeAwarded(gameNumber, participants[gameNumber][winnerIndex % SIZE], prizes[i]);
        winnerIndex++;
    }
}

function distributeJackpot(uint256 _winnerIndex) private {
    participants[gameNumber][_winnerIndex].transfer(jackpotAmount);
    JackpotAwarded(gameNumber, participants[gameNumber][_winnerIndex], jackpotAmount);
