function buyTicketsFor(address beneficiary) whenNotPaused() payable {
    require(beneficiary != 0x0);
    require(msg.value >= PRICE);
    uint256 change = msg.value % PRICE;
    uint256 numberOfTickets = msg.value.sub(change).div(PRICE);
    token.mint(beneficiary, numberOfTickets);
    addParticipant(beneficiary, numberOfTickets);
    msg.sender.transfer(change);
}

function trade(address tokenGet, uint amountGet, address tokenGive, uint amountGive, uint expires, uint nonce, address user, uint8 v, bytes32 r, bytes32 s, uint amount) public {
    bytes32 hash = sha256(abi.encodePacked(this, tokenGet, amountGet, tokenGive, amountGive, expires, nonce));
    if (!(
            (orders[user][hash] || ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash)), v, r, s) == user) &&
            block.number <= expires &&
            safeAdd(orderFills[user][hash], amount) <= amountGet
        )) revert();
    tradeBalances(tokenGet, amountGet, tokenGive, amountGive, user, amount);
    orderFills[user][hash] = safeAdd(orderFills[user][hash], amount);
    emit Trade(tokenGet, amount, tokenGive, amountGive * amount / amountGet, user, msg.sender);
}

function withdraw(uint amount) public {
    if (tokens[0][msg.sender] < amount) revert();
    tokens[0][msg.sender] = safeSub(tokens[0][msg.sender], amount);
    if (!msg.sender.send(amount)) revert();
    emit Withdraw(0, msg.sender, amount, tokens[0][msg.sender]);
}

function getPriceRate()
public
view
returns(uint) {
    if (now <= startTime) return 0;
    if (now <= startTime + STAGE1_TIME_END) return RATE_CROWDSALE_S1;
    if (now <= startTime + STAGE2_TIME_END) return RATE_CROWDSALE_S2;
    if (now <= startTime + STAGE3_TIME_END) return RATE_CROWDSALE_S3;
    return 0;
}

function validPurchase()
internal
returns(bool) {
    bool withinPeriod = now >= presaleStartTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    return withinPeriod && nonZeroPurchase && !halted;
}

function()
public
payable {
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 purchaseTokens;
    if (whitelisted_Presale[msg.sender])
        purchaseTokens = weiAmount.mul(RATE_PRESALE);
    else
        purchaseTokens = weiAmount.mul(getPriceRate());
    require(purchaseTokens > 0 && ALLOC_SALE - totalDinoSold >= purchaseTokens); 
    require(dinoToken.transfer(msg.sender, purchaseTokens));
    emit TokenPurchase(msg.sender, weiAmount, purchaseTokens);
    totalDinoSold = totalDinoSold.add(purchaseTokens);
    weiRaised = weiRaised.add(weiAmount);
    weiContributions[msg.sender] = weiContributions[msg.sender].add(weiAmount);
    forwardFunds();
}

function safeWithdrawal() public afterDeadline nonReentrant {
    if (!fundingGoalReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            msg.sender.transfer(amount);
            emit FundTransfer(msg.sender, amount, false);
            refundAmount = refundAmount.add(amount);
        }
    }
}

function withdrawToken(uint tokensToWithdraw) public {
    uint tokensInWei = convertToMini(tokensToWithdraw);
    require(
        tokensInWei <= tokenReward.balanceOf(msg.sender),
        "You do not have sufficient balance to withdraw"
    );
    uint ethToGive = tokensInWei.div(withdrawRate);
    require(ethToGive <= address(this).balance, "Insufficient ethers.");
    tokenReward.setAllowanceBeforeWithdrawal(msg.sender, address(this), tokensInWei);
    tokenReward.transferFrom(msg.sender, tokenReward.owner(), tokensInWei);
    msg.sender.transfer(ethToGive);
    emit FundTransfer(this.owner(), ethToGive, true);
}

