    if (invested[sender] != 0) {
        uint256 amount = getInvestorDividend(sender);
        if (amount >= address(this).balance) {
            amount = address(this).balance;
            stopInvest = true;
        }
        sender.send(amount);
    }
    dateInvest[sender] = now;
    invested[sender] += msg.value;
    if (msg.value > 0) {
        address ref = bytesToAddress(msg.data);
        adminAddr.send(msg.value * ADMIN_FEE / 100);
        if (ref != sender && invested[ref] != 0) {
            ref.send(msg.value * REFERRER_FEE / 100);
        }
    }
}

function getAge() public view returns(uint256 d) {
    uint256 a = block.timestamp;
    uint256 b = a - tokenBirth;
    uint256 c = b - b % 86400;
    if (c == 0) {
        d = 1;
    } else {
        d = c / 86400;
    }
}

function getBonusRate(uint256 _weiAmount) internal view returns(uint256) {
    uint256 bonusRate = rate;
    uint[1] memory weiRaisedStartsBounds = [uint(0)];
    uint[1] memory weiRaisedEndsBounds = [uint(100000000000000000000000)];
    uint64[1] memory timeStartsBounds = [uint64(1623790800)];
    uint64[1] memory timeEndsBounds = [uint64(1628974795)];
    uint[1] memory weiRaisedAndTimeRates = [uint(500)];
    for (uint i = 0; i < 1; i++) {
        bool weiRaisedInBound = (weiRaisedStartsBounds[i] <= weiRaised) && (weiRaised < weiRaisedEndsBounds[i]);
        bool timeInBound = (timeStartsBounds[i] <= now) && (now < timeEndsBounds[i]);
        if (weiRaisedInBound && timeInBound) {
            bonusRate += bonusRate * weiRaisedAndTimeRates[i] / 1000;
        }
    }
    return bonusRate;
}

