    uint[5] memory amounts = [uint(1000000000000000000000000), uint(1000000000000000000000000), uint(1000000000000000000000000), uint(1000000000000000000000000), uint(1000000000000000000000000)];
    uint64[5] memory freezes = [uint64(0), uint64(0), uint64(0), uint64(0), uint64(0)];
