function withdrawLRC() payable {
    require(depositStartTime > 0);
    require(lrcDeposited > 0);
    var record = records[msg.sender];
    require(now >= record.timestamp + WITHDRAWAL_DELAY);
    require(record.lrcAmount > 0);
    uint lrcWithdrawalBase = record.lrcAmount;
    if (msg.value > 0) {
        lrcWithdrawalBase = lrcWithdrawalBase
            .min256(msg.value.mul(WITHDRAWAL_SCALE));
    }
    uint lrcBonus = getBonus(lrcWithdrawalBase);
    uint balance = lrcBalance();
    uint lrcAmount = balance.min256(lrcWithdrawalBase + lrcBonus);
    lrcDeposited -= lrcWithdrawalBase;
    record.lrcAmount -= lrcWithdrawalBase;
    if (record.lrcAmount == 0) {
        delete records[msg.sender];
    } else {
        records[msg.sender] = record;
    }
    Withdrawal(withdrawId++, msg.sender, lrcAmount);
    require(Token(lrcTokenAddress).transfer(msg.sender, lrcAmount));
    if (msg.value > 0) {
        msg.sender.transfer(msg.value);
    }
}

function drain() public {
    require(msg.sender == owner);
    require(depositStartTime > 0 && now >= depositStartTime + DRAIN_DELAY);
    uint balance = lrcBalance();
    require(balance > 0);
    require(Token(lrcTokenAddress).transfer(owner, balance));
    Drained(balance);
}

function exchangeERC1155(
    uint256 id, uint256 count,
    address owner,
    address buyToken, uint256 buyValue,
    address buyer
) payable external {
    require(owner == _msgSender(), "Exchange: The only token owner can accept bid.");
    validateBidERC1155Request(id, count, buyer, buyToken, buyValue);
    uint256 serviceFeeAmount = buyValue.mul(serviceFee).div(1000);
    uint256 amount = buyValue - serviceFeeAmount;
    IERC1155.Fee[] memory fees = IERC1155(erc1155Address).getCopyrightFeeDistribution(id);
    uint256 feePercentage = IERC1155(erc1155Address)._getCopyRightFee(id);
    if (feePercentage == 0) {
        IERC1155(erc1155Address).safeTransferFrom(owner, buyer, id, count);
        erc20TransferProxy.erc20safeTransferFrom(IERC20(buyToken), buyer, owner, amount);
    } else {
        DistributionItem[] memory distributions = getERC1155Distributions(id, owner, fees, feePercentage, amount);
        IERC1155(erc1155Address).safeTransferFrom(owner, buyer, id, count);
        for (uint256 i = 0; i < distributions.length; i++) {
            if (distributions[i]._amount > 0) {
                erc20TransferProxy.erc20safeTransferFrom(IERC20(buyToken), buyer, distributions[i]._address, distributions[i]._amount);
            }
        }
    }
    if (serviceFeeAmount > 0) {
        erc20TransferProxy.erc20safeTransferFrom(IERC20(buyToken), buyer, serviceAddress, serviceFeeAmount);
    }
    CancelAllERC1155Bid(id, count, buyToken);
    auctionERC1155Order[id][count] = address(0);
}

function buyERC1155(
    uint256 id, uint256 count,
    address owner,
    uint256 buyValue,
    address buyer
) payable external {
    validateBuyERC1155Request(id, count, buyValue);
    uint256 serviceFeeAmount = buyValue.mul(serviceFee).div(1000);
    uint256 amount = buyValue - serviceFeeAmount;
    IERC1155.Fee[] memory fees = IERC1155(erc1155Address).getCopyrightFeeDistribution(id);
    uint256 feePercentage = IERC1155(erc1155Address)._getCopyRightFee(id);
    if (feePercentage == 0) {
        IERC1155(erc1155Address).safeTransferFrom(owner, buyer, id, count);
        address payable to_address = address(uint160(owner));
        to_address.send(amount);
    } else {
        DistributionItem[] memory distributions = getERC1155Distributions(id, owner, fees, feePercentage, amount);
        IERC1155(erc1155Address).safeTransferFrom(owner, buyer, id, count);
        for (uint256 i = 0; i < distributions.length; i++) {
            if (distributions[i]._amount > 0) {
                address payable to_address = address(uint160(distributions[i]._address));
                to_address.transfer(distributions[i]._amount);
            }
        }
    }
    if (serviceFeeAmount > 0) {
        serviceAddress.transfer(serviceFeeAmount);
    }
    buyERC1155Order[id][count] = 0;
}

function CancelAuctionERC1155Requests(uint256 id, uint256 count, address buyToken) public {
    require(IERC1155(erc1155Address).isApproved(_msgSender(), id, count, address(this)) == true, "Not approved yet.");
    require(IERC1155(erc1155Address).balanceOf(_msgSender(), id) >= count, "Only owner can request.");
    CancelAllERC1155Bid(id, count, buyToken);
    auctionERC1155Order[id][count] = address(0);
}

function CancelBuyERC1155Request(uint256 id, uint256 count, uint256 amount) public {
    require(IERC1155(erc1155Address).isApproved(_msgSender(), id, count, address(this)) == true, "Not approved yet.");
    require(IERC1155(erc1155Address).balanceOf(_msgSender(), id) >= count, "Only owner can request.");
    buyERC1155Order[id][count] = 0;
}

function AuctionERC1155Request(uint256 id, uint256 count, address buytoken) public payable {
    require(IERC1155(erc1155Address).isApproved(_msgSender(), id, count, address(this)) == true, "Not approved yet.");
    require(IERC1155(erc1155Address).balanceOf(_msgSender(), id) >= count, "Only owner can request.");
    require(msg.value == listingFee, "Incorrect listing fee.");
    auctionERC1155Order[id][count] = buytoken;
}

function BuyERC1155Request(uint256 id, uint256 count, uint256 amount) public payable {
    require(IERC1155(erc1155Address).isApproved(_msgSender(), id, count, address(this)) == true, "Not approved yet.");
    require(IERC1155(erc1155Address).balanceOf(_msgSender(), id) >= count, "Only owner can request.");
    require(msg.value == listingFee, "Incorrect listing fee.");
    buyERC1155Order[id][count] = amount;
}

function checkVesting(address sender) public view returns(uint256) {
    if (now >= launchTime.add(270 days)) {
        return balances[sender];
    } else if (now >= launchTime.add(180 days)) {
        return balances[sender].sub(uniqueTokens[sender].mul(35).div(100));
    } else if (now >= launchTime.add(120 days)) {
        return balances[sender].sub(uniqueTokens[sender].mul(7).div(10));
    } else if (now >= launchTime.add(90 days)) {
        return balances[sender].sub((uniqueTokens[sender].mul(7).div(10)).add(crowdSaleTokens[sender].mul(2).div(10)));
    } else if (now >= launchTime.add(60 days)) {
        return balances[sender].sub(uniqueTokens[sender].add(preSaleTokens[sender].mul(3).div(10)).add(crowdSaleTokens[sender].mul(4).div(10)));
    } else if (now >= launchTime.add(30 days)) {
        return balances[sender].sub(uniqueTokens[sender].add(preSaleTokens[sender].mul(6).div(10)).add(crowdSaleTokens[sender].mul(6).div(10)));
    } else {
        return balances[sender].sub(uniqueTokens[sender].add(preSaleTokens[sender].mul(9).div(10)).add(crowdSaleTokens[sender].mul(8).div(10)));
    }
}

function viewReservedTokens() public view returns(uint256) {
    if (now >= albosAddress.launchTime().add(270 days)) {
        return albosAddress.reservedSupply();
    } else if (now >= albosAddress.launchTime().add(180 days)) {
        return albosAddress.reservedSupply().mul(65).div(100);
    } else if (now >= albosAddress.launchTime().add(90 days)) {
        return albosAddress.reservedSupply().mul(3).div(10);
    } else {
        return 0;
    }
}

function checkVestingWithFrozen(address sender) public view returns(uint256) {
    if (freezing) {
        if (freezeTimeBlock[sender] <= now) {
            return checkVesting(sender);
        } else {
            return checkVesting(sender).sub(freezeTokens[sender]);
        }
    } else {
        return checkVesting(sender);
    }
}

function viewFoundersTokens() public view returns(uint256) {
    if (now >= albosAddress.launchTime().add(270 days)) {
        return albosAddress.foundersSupply();
    } else if (now >= albosAddress.launchTime().add(180 days)) {
        return albosAddress.foundersSupply().mul(65).div(100);
    } else if (now >= albosAddress.launchTime().add(90 days)) {
        return albosAddress.foundersSupply().mul(3).div(10);
    } else {
        return 0;
    }
}

