function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (from != owner() && to != owner() && !_isExcludedFromFee[from] && !_isExcludedFromFee[to]) {
        require(tradeAllowed);
        require(!_isBlacklisted[from] && !_isBlacklisted[to]);
        if (_cooldownEnabled) {
            if (!cooldown[msg.sender].exists) {
                cooldown[msg.sender] = User(0, 0, true);
            }
        }
        if (from == uniswapV2Pair && to != address(uniswapV2Router)) {
            if (limitTX) {
                require(amount <= _maxTxAmount);
            }
            if (_cooldownEnabled) {
                if (buyLimitEnd > block.timestamp) {
                    require(amount <= _maxBuyAmount);
                    require(cooldown[to].buy < block.timestamp, "Your buy cooldown has not expired.");
                    cooldown[to].buy = block.timestamp + (120 seconds);
                }
                cooldown[to].sell = block.timestamp + (300 seconds);
            }
            uint contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                swapETHfortargetToken(address(this).balance);
            }
        }
        if (to == address(uniswapV2Pair) || to == address(uniswapV2Router)) {
            if (doubleFeeEnable) {
                doubleFee();
            }
            if (_cooldownEnabled) {
                require(cooldown[from].sell < block.timestamp, "Your sell cooldown has not expired.");
            }
            uint contractTokenBalance = balanceOf(address(this));
            if (!inSwap && from != uniswapV2Pair && swapEnabled) {
                if (limitTX) {
                    require(amount <= balanceOf(uniswapV2Pair).mul(3).div(100) && amount <= _maxTxAmount);
                }
                uint initialETHBalance = address(this).balance;
                swapTokensForEth(contractTokenBalance);
                uint newETHBalance = address(this).balance;
                uint ethToDistribute = newETHBalance.sub(initialETHBalance);
                if (ethToDistribute > 0) {
                    distributeETH(ethToDistribute);
                }
            }
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to] || !feeEnabled) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee;
}

function addLiquidity() external onlyOwner() {
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    swapEnabled = true;
    liquidityAdded = true;
    feeEnabled = true;
    limitTX = true;
    _maxTxAmount = 1000000000000000 * 10 ** 9;
    _maxBuyAmount = 300000000000000 * 10 ** 9;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint256).max);
}

function isCampaignValid(bytes32 bidId) public view returns(bool) {
    uint startDate = advertisementStorage.getCampaignStartDateById(bidId);
    uint endDate = advertisementStorage.getCampaignEndDateById(bidId);
    bool valid = advertisementStorage.getCampaignValidById(bidId);
    uint nowInMilliseconds = now * 1000;
    return valid && startDate < nowInMilliseconds && endDate > nowInMilliseconds;
}

function upgradeStorage(address addrAdverStorage) public onlyOwner {
    for (uint i = 0; i < bidIdList.length; i++) {
        cancelCampaign(bidIdList[i]);
    }
    delete bidIdList;
    advertisementFinance.reset();
    advertisementFinance.setAdsStorageAddress(addrAdverStorage);
    advertisementStorage = AdvertisementStorage(addrAdverStorage);
}

function setAdsContractAddress(address _addrAdvert) external onlyOwner {
    if (advertisementContract != 0x0) {
        Advertisement adsContract = Advertisement(advertisementContract);
        address adsStorage = adsContract.getAdvertisementStorageAddress();
        require(adsStorage == advStorageContract);
    }
    advertisementContract = _addrAdvert;
}

function upgradeFinance(address addrAdverFinance) public onlyOwner {
    AdvertisementFinance newAdvFinance = AdvertisementFinance(addrAdverFinance);
    Map storage devBalance;
    for (uint i = 0; i < bidIdList.length; i++) {
        address dev = advertisementStorage.getCampaignOwnerById(bidIdList[i]);
        if (devBalance.balance[dev] == 0) {
            devBalance.devs.push(dev);
        }
        devBalance.balance[dev] += advertisementStorage.getCampaignBudgetById(bidIdList[i]);
    }
    for (i = 0; i < devBalance.devs.length; i++) {
        advertisementFinance.pay(devBalance.devs[i], address(newAdvFinance), devBalance.balance[devBalance.devs[i]]);
        newAdvFinance.increaseBalance(devBalance.devs[i], devBalance.balance[devBalance.devs[i]]);
    }
    uint256 oldBalance = appc.balances(address(advertisementFinance));
    require(oldBalance == 0);
    advertisementFinance = newAdvFinance;
}

function withdraw(address _developer, uint256 _value) public onlyOwnerOrAds {
    require(balanceDevelopers[_developer] >= _value);
    appc.transfer(_developer, _value);
    balanceDevelopers[_developer] -= _value;
}

function setAdsStorageAddress(address _addrStorage) external onlyOwnerOrAds {
    reset();
    advStorageContract = _addrStorage;
}

function registerPoA(
    string packageName, bytes32 bidId,
    uint64[] timestampList, uint64[] nonces,
    address appstore, address oem,
    string walletName, bytes2 countryCode) external {
    if (!isCampaignValid(bidId)) {
        emit Error(
            "registerPoA", "Registering a Proof of attention to a invalid campaign");
        return;
    }
    if (timestampList.length != expectedPoALength) {
        emit Error("registerPoA", "Proof-of-attention should have exactly 12 proofs");
        return;
    }
    if (timestampList.length != nonces.length) {
        emit Error(
            "registerPoA", "Nounce list and timestamp list must have same length");
        return;
    }
    for (uint i = 0; i < timestampList.length - 1; i++) {
        uint timestampDiff = (timestampList[i + 1] - timestampList[i]);
        if ((timestampDiff / 1000) != 10) {
            emit Error(
                "registerPoA", "Timestamps should be spaced exactly 10 secounds");
            return;
        }
    }
    if (userAttributions[msg.sender][bidId]) {
        emit Error(
            "registerPoA", "User already registered a proof of attention for this campaign");
        return;
    }
    userAttributions[msg.sender][bidId] = true;
    payFromCampaign(bidId, appstore, oem);
    emit PoARegistered(bidId, packageName, timestampList, nonces, walletName, countryCode);
}

function pay(address _developer, address _destination, uint256 _value)
public onlyAds {
    appc.transfer(_destination, _value);
    balanceDevelopers[_developer] -= _value;
}

function bet(uint256[] _timestamps, address _referral) payable public {
    require(msg.value >= costPerTicket.mul(_timestamps.length));
    require(!announced);
    if (now < expireDate) {
        for (i = 0; i < _timestamps.length; i++) {
            timestampList.push(_timestamps[i]);
            mirrors[_timestamps[i]].push(msg.sender);
            betHistory[msg.sender].push(_timestamps[i]);
            averageTimestamp = averageTimestamp.mul(countBet) + _timestamps[i];
            averageTimestamp = averageTimestamp.div(countBet + 1);
            countBet++;
            playerBets[msg.sender]++;
        }
        if (isPlayer[msg.sender] != true) {
            countPlayer++;
            isPlayer[msg.sender] = true;
            referral[msg.sender] = _referral;
            countReferral[_referral] += 1;
        }
        if (playerBets[msg.sender] > playerBets[leader] && msg.sender != leader) {
            if (msg.sender != leader_2) {
                leader_3 = leader_2;
            }
            leader_2 = leader;
            leader = msg.sender;
        } else if (playerBets[msg.sender] > playerBets[leader_2] && msg.sender != leader_2 && msg.sender != leader) {
            leader_3 = leader_2;
            leader_2 = msg.sender;
        } else if (playerBets[msg.sender] > playerBets[leader_3] && msg.sender != leader_2 && msg.sender != leader && msg.sender != leader_3) {
            leader_3 = msg.sender;
        }
        rewardPool = rewardPool.add(msg.value);
        owner.transfer(msg.value.mul(12).div(100)); 
        emit Bet(_timestamps.length, msg.sender);
    } else {
        if (!locked) {
            locked = true;
        }
        owner.transfer(msg.value);
    }
    if (startDate.add(countWeek.mul(604800)) < now) {
        countWeek++;
        if (costPerTicket < maxCost) {
            costPerTicket = costPerTicket.add(2500000000000000);
        }
    }
}

function confirm() public {
    require(announced == true);
    require(confirmed == false);
    require(isPlayer[msg.sender] == true);
    require(hasConfirmed[msg.sender] != true);
    countConfirmed += 1;
    hasConfirmed[msg.sender] = true;
    msg.sender.transfer(confirmreward);
    emit Confirm(msg.sender);
    emit Payreward(msg.sender, confirmreward);
    if (countConfirmed >= numOfConfirmationNeeded) {
        confirmed = true;
    }
}

function payWinners() public {
    require(confirmed);
    require(!gameOver);
    share = rewardPool.div(2);
    share = share.div(countWinners);
    for (i = 0; i < countWinners; i++) {
        mirrors[winnerTimestamp][i].transfer(share.mul(9).div(10));
        referral[mirrors[winnerTimestamp][i]].transfer(share.mul(1).div(10));
        emit Payreward(mirrors[winnerTimestamp][i], share);
    }
    share = rewardPool.div(4);
    share = share.div(countSecondWinners);
    for (i = 0; i < countSecondWinners; i++) {
        mirrors[secondWinnerTimestamp][i].transfer(share.mul(9).div(10));
        referral[mirrors[secondWinnerTimestamp][i]].transfer(share.mul(1).div(10));
        emit Payreward(mirrors[secondWinnerTimestamp][i], share);
    }
    gameOver = true;
}

function payLeaderAndDev() public {
    require(locked || announced);
    require(!developmentPaid);
    owner.transfer(init_fund.mul(12).div(100));
    leader.transfer(rewardPool.mul(4).div(100));
    leader_2.transfer(rewardPool.mul(25).div(1000));
    leader_3.transfer(rewardPool.mul(15).div(1000));
    developmentPaid = true;
}

function burn(uint256 _amount, bytes _userData) public {
    require(_amount > 0);
    require(balanceOf[msg.sender] >= _amount);
    requireMultiple(_amount);
    callSender(msg.sender, msg.sender, 0x0, _amount, _userData, "");
    totalSupply = totalSupply.sub(_amount);
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(_amount);
    emit Burned(msg.sender, msg.sender, _amount, _userData, "");
    emit Transfer(msg.sender, 0x0, _amount);
}

function initialize(address _owner, address _token, address _familyOwner, address _personalOwner) public {
    require(!initialized);
    token = JaroCoinToken(_token);
    sleepContract = createJaroSleep(_token, 34560e18); 
    familyContract = createPersonalTime(_token, 21600e18); 
    personalContract = createPersonalTime(_token, 12960e18); 
    familyContract.transferOwnership(_familyOwner);
    personalContract.transferOwnership(_personalOwner);
    rate = 100000e10;
    conversionRate = 17e10;
    satoshiRaised = 0;
    setOwner(_owner);
    initialized = true;
}

function startSale(uint256 _startTime) public onlyOwner {
    require(!isActive);
    require(_startTime > getNow());
    require(saleStartTime == 0 || _startTime.sub(saleStartTime) > 30 days); 
    sleepContract.burnTokens();
    uint256 sleepTokens = token.balanceOf(address(sleepContract));
    familyContract.burnTokens();
    uint256 familyTokens = token.balanceOf(familyContract).add(familyContract.debt());
    personalContract.burnTokens();
    uint256 personalTokens = token.balanceOf(personalContract).add(personalContract.debt());
    uint256 missingSleep = MAX_AMOUNT.div(100).mul(40).sub(sleepTokens); 
    uint256 missingFamily = MAX_AMOUNT.div(100).mul(25).sub(familyTokens); 
    uint256 missingPersonal = MAX_AMOUNT.div(100).mul(15).sub(personalTokens); 
    mint(address(sleepContract), missingSleep);
    mint(address(familyContract), missingFamily);
    mint(address(personalContract), missingPersonal);
    tokensToMint = MAX_AMOUNT.sub(token.totalSupply());
    saleStartTime = _startTime;
    isActive = true;
    emit SaleActivated(_startTime, tokensToMint);
}

function doSend(
    address _from,
    address _to,
    uint256 _amount,
    bytes _userData,
    address _operator,
    bytes _operatorData,
    bool _preventLocking
)
private {
    requireMultiple(_amount);
    callSender(_operator, _from, _to, _amount, _userData, _operatorData);
    require(_to != 0x0); 
    require(balanceOf[_from] >= _amount); 
    balanceOf[_from] = balanceOf[_from].sub(_amount);
    balanceOf[_to] = balanceOf[_to].add(_amount);
    callRecipient(_operator, _from, _to, _amount, _userData, _operatorData, _preventLocking);
    emit Sent(_operator, _from, _to, _amount, _userData, _operatorData);
    emit Transfer(_from, _to, _amount);
}

function appendContribution(address _beneficiary, uint256 _tokens) internal returns(uint256) {
    if (_tokens >= tokensToMint) {
        mint(_beneficiary, tokensToMint);
        uint256 excededTokens = _tokens.sub(tokensToMint);
        _closeSale(); 
        return excededTokens;
    }
    tokensToMint = tokensToMint.sub(_tokens);
    mint(_beneficiary, _tokens);
    return 0;
}

function _buyTokens(address _beneficiary, uint256 _value, uint8 _bonus) internal {
    require(_beneficiary != address(0));
    require(_value > 0);
    uint256 weiAmount = _value;
    uint256 satoshiAmount = weiAmount.div(conversionRate);
    uint256 tokens = satoshiAmount.mul(rate).mul(100 + _bonus).div(100);
    uint256 excess = appendContribution(_beneficiary, tokens);
    uint256 refund = (excess > 0 ? excess.mul(100).div(100 + _bonus).mul(conversionRate).div(rate) : 0);
    weiAmount = weiAmount.sub(refund);
    satoshiRaised = satoshiRaised.add(satoshiAmount);
    if (refund > 0) {
        msg.sender.transfer(refund);
    }
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens.sub(excess));
    WALLET.transfer(weiAmount);
}

function burnTokens() public returns(uint256) {
    uint256 sec = getNow().sub(lastBurn);
    uint256 tokensToBurn = 0;
    if (sec >= 1 days) {
        uint256 d = sec.div(86400);
        tokensToBurn = d.mul(dailyTime);
        if (protect >= tokensToBurn) {
            protect = protect.sub(tokensToBurn);
        } else {
            token.burn(tokensToBurn.sub(protect), "");
            protect = 0;
        }
        lastBurn = lastBurn.add(d.mul(86400));
    }
    return tokensToBurn;
}

function coupon(uint256 _timeStamp, uint8 _bonus, uint8 v, bytes32 r, bytes32 s) external canMint payable {
    require(_timeStamp >= getNow());
    bytes memory prefix = "\x19Ethereum Signed Message:\n32";
    bytes32 hash = keccak256(prefix, keccak256(_timeStamp, _bonus));
    address signer = ecrecover(hash, v, r, s);
    require(signer == owner);
    _buyTokens(msg.sender, msg.value, _bonus);
}

function burnTokens() public returns(uint256) {
    uint256 sec = getNow().sub(lastBurn);
    uint256 tokensToBurn = 0;
    if (sec >= 1 days) {
        uint256 d = sec.div(86400);
        tokensToBurn = d.mul(dailyTime);
        token.burn(tokensToBurn, "");
        lastBurn = lastBurn.add(d.mul(86400));
    }
    return tokensToBurn;
}

function deposit() public nonReentrant payable {
    uint256 value = msg.value;
    uint256 final_value = value.mul(tax).div(1000);
    uint256 totalTax = (value - final_value);
    uint256 adminPart = totalTax.mul(Oogwaytax).div(1000);
    uint256 Dev_value = totalTax.mul(Devtax).div(1000);
    uint256 Market_value = totalTax.mul(Markettax).div(1000);
    uint256 burn_value = totalTax.mul(Burntax).div(1000);
    balanceOf[Dev] += Dev_value;
    balanceOf[Market] += Market_value;
    adminVal += (totalTax);
    balanceOf[Oogway] += adminPart;
    IWETH(WETH).deposit {
        value: burn_value
    }();
    swap(WETH, SHINJA, IERC20(WETH).balanceOf(address(this)), 1, address(0));
    balanceOf[msg.sender] += final_value;
    emit Deposit(msg.sender, value);
}

function withdraw(uint256 wad) public nonReentrant {
    require(balanceOf[msg.sender] >= wad, "ERROR: Insufficient BALANCE");
    uint256 final_value = wad.mul(tax).div(1000); 
    uint256 totalTax = (wad - final_value); 
    uint256 adminPart = totalTax.mul(Oogwaytax).div(1000);
    uint256 Dev_value = totalTax.mul(Devtax).div(1000);
    uint256 Market_value = totalTax.mul(Markettax).div(1000);
    balanceOf[Dev] += Dev_value;
    balanceOf[Market] += Market_value;
    adminVal += totalTax;
    balanceOf[Oogway] += adminPart;
    balanceOf[msg.sender] -= wad;
    payable(msg.sender).transfer(final_value);
    emit Withdrawal(msg.sender, wad);
}

