function transfer(address _to, uint256 _value) public returns(bool) {
    bool transferResult;
    uint256 lockQuantity;
    uint256 lockTotalQuantity;
    uint lockPeriod;
    require(FreezedWallet[msg.sender] == false);
    require(FreezedWallet[_to] == false);
    if (lockStatus[msg.sender] == false) {
        transferResult = _transfer(msg.sender, _to, _value);
        if (transferResult == true) {
            unlockQuantity[msg.sender] = unlockQuantity[msg.sender].sub(_value);
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    } else {
        for (uint i = 0; i < tokenLockInfo[msg.sender].length; i++) {
            lockQuantity = tokenLockInfo[msg.sender][i].lockQuantity;
            lockPeriod = tokenLockInfo[msg.sender][i].lockPeriod;
            if (lockPeriod <= now && lockQuantity != 0) {
                unlockQuantity[msg.sender] = unlockQuantity[msg.sender].add(lockQuantity);
                tokenLockInfo[msg.sender][i].lockQuantity = 0;
                lockQuantity = tokenLockInfo[msg.sender][i].lockQuantity;
            }
            lockTotalQuantity = lockTotalQuantity.add(lockQuantity);
        }
        if (lockTotalQuantity == 0)
            lockStatus[msg.sender] = false;
        require(_value <= unlockQuantity[msg.sender]);
        transferResult = _transfer(msg.sender, _to, _value);
        if (transferResult == true) {
            unlockQuantity[msg.sender] = unlockQuantity[msg.sender].sub(_value);
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    }
    return transferResult;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    bool transferResult;
    uint256 lockQuantity;
    uint256 lockTotalQuantity;
    uint lockPeriod;
    require(FreezedWallet[_from] == false);
    require(FreezedWallet[_to] == false);
    if (lockStatus[_from] == false) {
        transferResult = _transferFrom(_from, _to, _value);
        if (transferResult == true) {
            unlockQuantity[_from] = unlockQuantity[_from].sub(_value);
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    } else {
        for (uint i = 0; i < tokenLockInfo[_from].length; i++) {
            lockQuantity = tokenLockInfo[_from][i].lockQuantity;
            lockPeriod = tokenLockInfo[_from][i].lockPeriod;
            if (lockPeriod <= now && lockQuantity != 0) {
                unlockQuantity[_from] = unlockQuantity[_from].add(lockQuantity);
                tokenLockInfo[_from][i].lockQuantity = 0;
                lockQuantity = tokenLockInfo[_from][i].lockQuantity;
            }
            lockTotalQuantity = lockTotalQuantity.add(lockQuantity);
        }
        if (lockTotalQuantity == 0)
            lockStatus[_from] = false;
        require(_value <= unlockQuantity[_from]);
        transferResult = _transferFrom(_from, _to, _value);
        if (transferResult == true) {
            unlockQuantity[_from] = unlockQuantity[_from].sub(_value);
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    }
    return transferResult;
}

function reclaimInternal(address contributor) internal {
    uint UCASHtoSend;
    uint penalty;
    (UCASHtoSend, penalty) = ifClaimedNow(contributor);
    transferUCASH(contributor, UCASHtoSend);
    if (!loanMatured(contributor)) {
        BountyPool += Loans[contributor].bounty;
    }
    BountyPool += penalty;
    BountyPool -= Loans[contributor].recirculated;
    uint currentArrayIndex = Loans[contributor].arrayIndex;
    address replacingLoan = ListofLoans[ListofLoans.length - 1];
    Loans[replacingLoan].arrayIndex = currentArrayIndex;
    ListofLoans[currentArrayIndex] = replacingLoan;
    delete Loans[contributor];
    ListofLoans.length--;
    CalculateStageValue();
}

function recirculateLateFees(uint iterations) public {
    if (recirculationIndex >= ListofLoans.length) {
        recirculationIndex = 0;
    }
    uint i = recirculationIndex;
    uint j;
    if (i + iterations > ListofLoans.length) {
        j = ListofLoans.length;
    } else {
        j = i + iterations;
    }
    for (i; i < j; i++) {
        address contributor = ListofLoans[i];
        if (isLateBy(contributor) >= 600) {
            reclaimInternal(contributor); 
            i--;
            j--; 
        } else if (loanMatured(contributor)) {
            uint amountToRecirculate = getLateFee(contributor) - Loans[contributor].recirculated;
            Loans[contributor].recirculated += amountToRecirculate;
            BountyPool += amountToRecirculate;
        }
    }
    recirculationIndex = j;
}

function killswitch() public onlyOwner returns(bool) {
    uint i;
    while (i++ < 500 && ListofLoans.length > 0) {
        address contributor = ListofLoans[ListofLoans.length - 1];
        Loan memory memLoan = Loans[contributor];
        ERC20(UCASHAddress).transfer(contributor, memLoan.totalContribution - memLoan.recirculated);
        ListofLoans.length--;
    }
    if (ListofLoans.length == 0) {
        ERC20(UCASHAddress).transfer(owner, contractBalance());
        selfdestruct(address(this));
    } else {
        return false;
    }
}

function contributeInternal(address contributor, uint contribution) internal returns(bool) {
    if (loanMatured(contributor) || contribution == specialReclaimValue) {
        reclaimInternal(contributor);
    }
    Loan memory memLoan = Loans[contributor];
    if (memLoan.start == 0) {
        memLoan.start = now;
        memLoan.contractTime = periods * period;
        memLoan.arrayIndex = ListofLoans.length;
        ListofLoans.push(contributor);
    }
    uint timeElapsed = now - memLoan.start;
    uint rollBackTime = timeElapsed * contribution / (memLoan.totalContribution + contribution);
    uint Bounty;
    uint amountMemory = contribution;
    while (amountMemory > RemainingInStage) {
        Bounty += RemainingInStage * StageValue / StageAmount;
        amountMemory -= RemainingInStage;
        BountyPool -= RemainingInStage * StageValue / StageAmount;
        CalculateStageValue();
        RemainingInStage = StageAmount;
    }
    Bounty += amountMemory * StageValue / StageAmount;
    RemainingInStage -= amountMemory;
    BountyPool -= amountMemory * StageValue / StageAmount;
    memLoan.totalContribution += contribution;
    memLoan.bounty += Bounty;
    memLoan.start += rollBackTime;
    Loans[contributor] = memLoan;
    emit Contribution(contributor, contribution, Bounty, memLoan.start + memLoan.contractTime);
}

function loanMatured(address contributor) private view returns(bool) {
    if (Loans[contributor].start == 0) {
        return false;
    }
    if ((now > (Loans[contributor].start + Loans[contributor].contractTime))) {
        return true;
    } else {
        return false;
    }
}

function getLateFee(address contributor) public view returns(uint) {
    require(loanMatured(contributor));
    Loan memory memLoan = Loans[contributor];
    uint totalReward = memLoan.totalContribution + memLoan.bounty;
    uint endDate = memLoan.start + memLoan.contractTime;
    uint periodsLateBy = (now - endDate) / period;
    uint totalPenalty;
    uint periodPenalty;
    if (periodsLateBy >= 2000) {
        totalPenalty = totalReward;
    } else if (periodsLateBy <= 10) {
        return (0);
    } else {
        uint i;
        while (i++ < uint(periodsLateBy - 10)) {
            periodPenalty = totalReward * 21 / 1000;
            totalPenalty += periodPenalty; 
            totalReward -= periodPenalty;
        }
    }
    return (totalPenalty);
}

function isLateBy(address contributor) public view returns(uint) {
    if (Loans[contributor].start == 0) {
        return 0;
    }
    uint endDate = Loans[contributor].start + Loans[contributor].contractTime;
    if (now < endDate) {
        return 0;
    } else {
        return (now - endDate) / period;
    }
}

function secondsLeft(address contributor) public view returns(uint) {
    if (loanMatured(contributor)) {
        return 0;
    } else if (Loans[contributor].start == 0) {
        return 0;
    } else {
        return (Loans[contributor].start + Loans[contributor].contractTime - now);
    }
}

function ifClaimedNow(address contributor) public view returns(uint, uint) {
    Loan memory memLoan = Loans[contributor];
    if (memLoan.start == 0) {
        return (0, 0);
    }
    uint CancellationFee; 
    uint penalty;
    if (!loanMatured(contributor)) {
        if ((now - memLoan.start) <= 3 days) {
            CancellationFee = 0;
        } else {
            uint elapsedPeriods = (now - memLoan.start) / (period);
            CancellationFee = 210000 * (periods - elapsedPeriods) / periods;
        }
        penalty = (memLoan.totalContribution * CancellationFee) / 1000000;
        memLoan.bounty = 0;
    } else {
        penalty = getLateFee(contributor);
    }
    uint UCASHtoSend = memLoan.totalContribution + memLoan.bounty - penalty;
    return (UCASHtoSend, penalty);
}

function removeFunds(uint _amount) onlyOwner public {
    BountyPool -= _amount;
    transferUCASH(owner, _amount);
    CalculateStageValue();
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        _swapTokensForETH(swapAtAmount);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + 2 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(txFees).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function takeOwnership(string calldata _name) external payable {
    require(msg.value == cost, "Rich: Insufficient paid value"); 
    require(msg.sender != currentOwner, "Rich: Cannot be current owner"); 
    currentOwner.transfer(msg.value); 
    richest = _name; 
    currentOwner = msg.sender; 
    cost = cost * 3 / 2; 
    emit NewRichest(msg.sender, cost);
}

function addReward(uint256 rewardAmount)
external
_hasAllowance(msg.sender, rewardAmount)
returns(bool) {
    require(rewardAmount > 0, "Reward must be positive");
    address from = msg.sender;
    if (!_payMe(from, rewardAmount)) {
        return false;
    }
    totalReward = totalReward.add(rewardAmount);
    rewardBalance = rewardBalance.add(rewardAmount);
    return true;
}

function _stake(address from, uint256 amount) private returns(bool) {
    if (!_payMe(from, amount)) {
        return false;
    }
    hasStaked[from] = true;
    bool stakerEligibility;
    if (amount >= eligibilityAmount) {
        stakerEligibility = true;
    }
    deposits[from] = Deposits(
        amount,
        block.timestamp,
        index,
        false,
        stakerEligibility
    );
    emit Staked(tokenAddress, from, amount);
    stakedBalance = stakedBalance.add(amount);
    stakedTotal = stakedTotal.add(amount);
    return true;
}

function _emergencyWithdraw(address from) private returns(bool) {
    uint256 amount = deposits[from].depositAmount;
    stakedBalance = stakedBalance.sub(amount);
    deposits[from].paid = true;
    hasStaked[from] = false; 
    if (deposits[from].eligible) {
        deposits[from].eligible = false;
    }
    bool principalPaid = _payDirect(from, amount);
    require(principalPaid, "Error paying");
    emit PaidOut(tokenAddress, from, amount, 0);
    return true;
}

function withdraw() external returns(bool) {
    address from = msg.sender;
    require(hasStaked[from], "No stakes found for user");
    require(!deposits[from].paid, "Already paid out");
    return (_withdraw(from));
}

function _withdraw(address from) private returns(bool) {
    uint256 payOut = _calculate(from);
    uint256 amount = deposits[from].depositAmount;
    uint256 reward = payOut.sub(amount);
    require(reward <= rewardBalance, "Not enough rewards");
    stakedBalance = stakedBalance.sub(amount);
    rewardBalance = rewardBalance.sub(reward);
    deposits[from].paid = true;
    hasStaked[from] = false;
    if (deposits[from].eligible) {
        deposits[from].eligible = false;
    }
    if (_payDirect(from, payOut)) {
        emit PaidOut(tokenAddress, from, amount, reward);
        return true;
    }
    return false;
}

function _calculate(address from) private view returns(uint256) {
    if (!hasStaked[from]) return 0;
    (uint256 amount, uint256 depositTime, uint64 userIndex) = (
        deposits[from].depositAmount,
        deposits[from].depositTime,
        deposits[from].userIndex
    );
    uint256 time;
    uint256 interest;
    for (uint64 i = userIndex; i < index; i++) {
        time = rates[i + 1].timeStamp.sub(depositTime);
        interest = (
            amount.mul(rates[i].newInterestRate).mul(time).div(315360000000)
        );
        amount = amount.add(interest);
        depositTime = rates[i + 1].timeStamp;
    }
    time = block.timestamp.sub(depositTime);
    interest = (amount.mul(rate).mul(time).div(315360000000));
    amount = amount.add(interest);
    return amount;
}

function emergencyWithdraw() external returns(bool) {
    address from = msg.sender;
    require(hasStaked[from], "No stakes found for user");
    require(!deposits[from].paid, "Already paid out");
    return (_emergencyWithdraw(from));
}

function withdrawUnlock() public {
    uint unlock;
    uint i = 0;
    while (i != lockInfo[msg.sender].length) {
        if (block.timestamp >= lockInfo[msg.sender][i].unlockTime) {
            unlock = unlock.add(lockInfo[msg.sender][i].amount);
            lockInfo[msg.sender][i] = lockInfo[msg.sender][lockInfo[msg.sender].length.sub(1)];
            lockInfo[msg.sender].pop();
        } else {
            i++;
        }
    }
    if (unlock > 0) {
        totalPledgeBOR = totalPledgeBOR.sub(unlock);
        borERC20().transfer(msg.sender, unlock);
        emit WithdrawUnlockSuccess(
            msg.sender,
            unlock
        );
    }
}

function userLockAmount() public view returns(uint256, uint256) {
    uint lock;
    uint unlock;
    for (uint i = 0; i < lockInfo[msg.sender].length; i++) {
        if (block.timestamp >= lockInfo[msg.sender][i].unlockTime) {
            unlock = unlock.add(lockInfo[msg.sender][i].amount);
        } else {
            lock = lock.add(lockInfo[msg.sender][i].amount);
        }
    }
    return (lock, unlock);
}

function RandomWinner() private {
    if (players.length < MaxPlayers) revert();
    uint256 fee = SafeMath.div(address(this).balance, 100);
    lastWinner = players[random() % players.length];
    lastWinner.transfer(address(this).balance - fee);
    owner.transfer(fee);
    delete players;
    jackpot = 0;
    completedGames++;
}

