function BuyBSTtokens() payable {
    require(!(msg.value == 0) &&
        (isCrowdSaleSetup) &&
        (block.number >= fundingStartBlock) &&
        (block.number <= fundingEndBlock) &&
        (tokensRemaining > 0));
    uint256 rewardTransferAmount = 0;
    setPrice();
    amountRaisedInWei = safeAdd(amountRaisedInWei, msg.value);
    rewardTransferAmount = safeDiv(safeMul(msg.value, tokensPerEthPrice), 10000000000000000);
    tokensRemaining = safeSub(tokensRemaining, safeDiv(rewardTransferAmount, 100));
    tokenReward.transfer(msg.sender, rewardTransferAmount);
    fundValue[msg.sender] = safeAdd(fundValue[msg.sender], msg.value);
    Transfer(this, msg.sender, msg.value);
    Buy(msg.sender, msg.value, rewardTransferAmount);
}

function getRateAt(uint256 at) constant returns(uint256) {
    if (at < startDate) {
        return 0;
    } else if (at < (startDate + 7 days)) {
        return 840;
    } else if (at < (startDate + 37 days)) {
        return 770;
    } else if (at <= endDate) {
        return 700;
    } else {
        return 0;
    }
}

function initialize(address _wallet, uint256 _start, uint256 _end,
    uint256 _saleCap, uint256 _totalSupply)
onlyOwner uninitialized {
    require(_start >= getCurrentTimestamp());
    require(_start < _end);
    require(_wallet != 0x0);
    require(_totalSupply > _saleCap);
    startDate = _start;
    endDate = _end;
    saleCap = _saleCap;
    wallet = _wallet;
    totalSupply = _totalSupply;
    balances[wallet] = _totalSupply.sub(saleCap);
    balances[0xb1] = saleCap;
}

function saleActive() public constant returns(bool) {
    return (getCurrentTimestamp() >= startDate &&
        getCurrentTimestamp() < endDate && supply() > 0);
}

