function validPurchase(uint256 tokens) internal view returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool withinCap = soldTokens.add(tokens) <= hardCap;
    bool withinTotalSupply = soldTokens.add(tokens) <= totalTokenSupply;
    bool nonZeroPurchase = msg.value != 0;
    return withinPeriod && nonZeroPurchase && withinCap && withinTotalSupply;
}

function finalization() internal {
    uint256 restrictedTokens = soldTokens.div(100).mul(restrictedPercent);
    token.mint(this, restrictedTokens);
    token.kycVerify(this);
    Y1_lockedTokenReleaseTime = now + 1 years;
    Y1_lockedTokenAmount = restrictedTokens.div(2);
    Y2_lockedTokenReleaseTime = now + 2 years;
    Y2_lockedTokenAmount = restrictedTokens.div(2);
    token.finishMinting();
    token.transferOwnership(owner);
}

function poke() external stoppable {
    require(pass(), "UNIV2LPOracle/not-passed");
    (uint val, uint32 ts) = seek();
    require(val != 0, "UNIV2LPOracle/invalid-price");
    cur = nxt;
    nxt = Feed(uint128(val), 1);
    zzz = ts;
    emit Value(cur.val, nxt.val);
}

function build(address _src, bytes32 _wat, address _orb0, address _orb1) public returns(address orcl) {
    address tok0 = UniswapV2PairLike(_src).token0();
    address tok1 = UniswapV2PairLike(_src).token1();
    orcl = address(new UNIV2LPOracle(_src, _wat, _orb0, _orb1));
    UNIV2LPOracle(orcl).rely(msg.sender);
    isOracle[orcl] = true;
    emit Created(msg.sender, orcl, _wat, tok0, tok1, _orb0, _orb1);
}

function seek() internal returns(uint128 quote, uint32 ts) {
    UniswapV2PairLike(src).sync();
    (uint112 res0, uint112 res1, uint32 _ts) = UniswapV2PairLike(src).getReserves();
    require(res0 > 0 && res1 > 0, "UNIV2LPOracle/invalid-reserves");
    ts = _ts;
    require(ts == block.timestamp);
    if (dec0 != uint8(18)) res0 = uint112(res0 * 10 ** sub(18, dec0));
    if (dec1 != uint8(18)) res1 = uint112(res1 * 10 ** sub(18, dec1));
    uint256 k = mul(res0, res1);
    uint256 val0 = OracleLike(orb0).read(); 
    uint256 val1 = OracleLike(orb1).read(); 
    require(val0 != 0, "UNIV2LPOracle/invalid-oracle-0-price");
    require(val1 != 0, "UNIV2LPOracle/invalid-oracle-1-price");
    uint256 bal0 =
        sqrt(
            wmul(
                k,
                wdiv(
                    val1,
                    val0
                )
            )
        );
    uint256 bal1 = wdiv(k, bal0) / WAD;
    uint256 supply = ERC20Like(src).totalSupply();
    require(supply > 0, "UNIV2LPOracle/invalid-lp-token-supply");
    quote = uint128(
        wdiv(
            add(
                wmul(bal0, val0), 
                wmul(bal1, val1) 
            ),
            supply 
        )
    );
}

function pass() public view returns(bool ok) {
    return block.timestamp >= add(zzz, hop);
}

function _playerRollDice(uint _rollUnder, TKN _tkn) private
gameIsActive
betIsValid(_tkn.value, _rollUnder) {
    require(_tkn.value < ((2 ** 200) - 1)); 
    require(block.number < ((2 ** 48) - 1)); 
    require(_zthToken(msg.sender));
    playerRoll memory roll = playerRolls[_tkn.sender];
    require(block.number != roll.blockn);
    if (roll.blockn != 0) {
        _finishBet(false, _tkn.sender);
    }
    roll.blockn = uint48(block.number);
    roll.tokenValue = uint200(_tkn.value);
    roll.rollUnder = uint8(_rollUnder);
    playerRolls[_tkn.sender] = roll;
    emit LogBet(_tkn.sender, _tkn.value, _rollUnder);
    totalBets += 1;
    totalZTHWagered += _tkn.value;
}

