function purchaseTokens() public payable {
    require(now >= crowdsaleStart);
    require(now <= crowdsaleEnd);
    require(msg.value >= 1000 finney);
    uint256 tokens = 0;
    tokens = msg.value.mul(exchangeRate);
    uint256 unsoldTokens = balances[saleWallet];
    require(unsoldTokens >= tokens);
    balances[saleWallet] -= tokens;
    balances[msg.sender] += tokens;
    emit Transfer(saleWallet, msg.sender, tokens);
    etherAddress.transfer(msg.value.mul(90).div(100));
    teamWallet.transfer(msg.value.mul(10).div(100));
}

function getBonusPercentage() public constant returns(uint256) {
    uint256 finalBonus;
    uint256 iterativeTimestamp;
    uint256 iterativeBonus;
    for (uint256 i = 0; i < bonuses.length; i++) {
        if (i % 2 == 0) {
            iterativeTimestamp = bonuses[i];
        } else {
            iterativeBonus = bonuses[i];
            if (block.timestamp >= iterativeTimestamp) {
                finalBonus = iterativeBonus;
            }
        }
    }
    return finalBonus;
}

function complete(uint256 _sanity, uint256 _value) ifCreator external {
    require(_sanity == 101010101);
    require(progress == 0 || progress == 1);
    require(block.timestamp >= finish);
    require(this.balance >= _value);
    progress = 2;
    reserves = safeAdd(reserves, _value);
    Completed(tokens, value, _value);
    SaleCallbackInterface(marketplace).handleSaleCompletionCallback.value(_value)(tokens);
}

function buy(address _recipient) public payable {
    require(_recipient != address(0x0));
    require(msg.value >= 10 ** 17);
    require(active);
    require(progress == 0 || progress == 1);
    require(block.timestamp >= start);
    require(block.timestamp < finish);
    require((!restricted) || whitelist[msg.sender]);
    require((!restricted) || whitelist[_recipient]);
    uint256 baseTokens = safeMul(msg.value, pricer);
    uint256 totalTokens = safeAdd(baseTokens, safeDiv(safeMul(baseTokens, getBonusPercentage()), 100));
    require(safeAdd(tokens, totalTokens) <= size);
    if (!participants[_recipient]) {
        participants[_recipient] = true;
        participantIndex.push(_recipient);
    }
    participantTokens[_recipient] = safeAdd(participantTokens[_recipient], totalTokens);
    participantValues[_recipient] = safeAdd(participantValues[_recipient], msg.value);
    tokens = safeAdd(tokens, totalTokens);
    value = safeAdd(value, msg.value);
    Bought(msg.sender, _recipient, totalTokens, msg.value);
}

function claim() external {
    require(progress == 2);
    require(block.timestamp >= release);
    require(participantTokens[msg.sender] > 0);
    require(!participantClaims[msg.sender]);
    participantClaims[msg.sender] = true;
    Claimed(msg.sender, participantTokens[msg.sender]);
    SaleCallbackInterface(marketplace).handleSaleClaimCallback(msg.sender, participantTokens[msg.sender]);
}

function certify(uint256 _sanity) ifCreator external {
    require(_sanity == 101011111);
    require(progress == 0);
    require(block.timestamp >= start);
    progress = 1;
    Certified(tokens, value);
}

function userVoteFor(address _user, uint256 _team, uint256 _amount) internal {
    Vote storage _v = votes[_team];
    uint256 voteVal = _amount.sub(_amount.mul(voteCut).div(100));
    if (voteVal < _amount) {
        owner.transfer(_amount.sub(voteVal));
    }
    if (_v.amounts[_user] == 0) {
        _v.users.push(_user);
    }
    pool = pool.add(voteVal);
    _v.totalAmount = _v.totalAmount.add(voteVal);
    _v.amounts[_user] = _v.amounts[_user].add(voteVal);
    _v.weightedTotalAmount = _v.weightedTotalAmount.add(voteVal.mul(voteWeight));
    _v.weightedAmounts[_user] = _v.weightedAmounts[_user].add(voteVal.mul(voteWeight));
    emit VoteSuccessful(_user, _team, _amount);
}

function() public payable {
    require(icoProceeding);
    require(raisedEthAmt < fundingEthGoal);
    require(msg.value >= 0.1 ether); 
    if (enableWhiteList) {
        require(whiteListMge.isRegistered(msg.sender));
    }
    uint amount = msg.value; 
    uint remainToGoal = fundingEthGoal - raisedEthAmt;
    uint returnAmt = 0; 
    if (remainToGoal < amount) {
        returnAmt = msg.value.sub(remainToGoal);
        amount = remainToGoal;
    }
    uint tokenCount = amount.mul(pricePerEther);
    if (tokenReward.transferSoldToken(address(this), msg.sender, tokenCount)) {
        raisedEthAmt = raisedEthAmt.add(amount);
        totalSoldTokenCount = totalSoldTokenCount.add(tokenCount);
        funderEthAmt[msg.sender] = funderEthAmt[msg.sender].add(amount);
        emit FundTransfer(msg.sender, amount, true);
        if (returnAmt > 0) {
            msg.sender.transfer(returnAmt);
            icoProceeding = false; 
            emit ReturnExcessAmount(msg.sender, returnAmt);
        }
    }
}

function checkGoalReached() public {
    require(msg.sender == owner);
    if (raisedEthAmt >= fundingEthGoal) {
        safeWithdrawal();
    }
    icoProceeding = false;
}

function safeWithdrawal() public {
    require(msg.sender == owner);
    beneficiary.transfer(address(this).balance);
    emit FundTransfer(beneficiary, address(this).balance, false);
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = computeTokenWithBonus(weiAmount, beneficiary);
    token.mint(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    weiRaised = weiRaised.add(weiAmount);
    numberOfPurchasers = numberOfPurchasers + 1;
    sxpNumber = sxpNumber.add(tokens);
    forwardFunds();
}

function Crowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != 0x0);
    token = createTokenContract();
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = totIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = totIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 92), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        totIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 92);
    } else if (sellingPrice < secondStepLimit) {
        totIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 92);
    } else {
        totIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 92);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, totIndexToPrice[_tokenId], oldOwner, newOwner, tots[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

function finalize() public inState(State.Success) stopInEmergency {
    require(msg.sender == deployAgent || msg.sender == team);
    require(!finalized);
    finalized = true;
    uint feeAmount = (this.balance * ETHERFUNDME_FEE) / 100;
    uint teamAmount = this.balance - feeAmount;
    Withdraw(team, teamAmount);
    team.transfer(teamAmount);
    Withdraw(feeReceiver, feeAmount);
    feeReceiver.transfer(feeAmount);
}

function invest() public payable stopInEmergency {
    require(getState() == State.Funding);
    require(msg.value > 0);
    uint weiAmount = msg.value;
    address investor = msg.sender;
    if (investedAmountOf[investor] == 0) {
        investorCount++;
    }
    uint onlineFeeAmount = (weiAmount * ETHERFUNDME_ONLINE_FEE) / 100;
    Withdraw(feeReceiver, onlineFeeAmount);
    feeReceiver.transfer(onlineFeeAmount);
    uint investedAmount = weiAmount - onlineFeeAmount;
    investedAmountOf[investor] += investedAmount;
    Invested(investor, investedAmount);
}

function getState() public constant returns(State) {
    if (finalized)
        return State.Finalized;
    if (startsAt > now)
        return State.Preparing;
    if (now >= startsAt && now < endsAt)
        return State.Funding;
    if (isGoalReached())
        return State.Success;
    if (!isGoalReached() && this.balance > 0)
        return State.Refunding;
    return State.Failure;
}

function bid() payable public {
    require(msg.value == 5000000000000000);
    if (endTime == 0) {
        endTime = (now + addTime);
    }
    if (endTime != 0 && endTime > now) {
        addTime -= (10 seconds);
        endTime = (now + addTime);
        latestBidder = msg.sender;
        Bid(latestBidder, endTime, addTime, this.balance);
    }
    if (addTime == 0 || endTime <= now) {
        latestWinner = latestBidder;
        addTime = (2 hours);
        endTime = (now + addTime);
        latestBidder = msg.sender;
        Bid(latestBidder, endTime, addTime, ((this.balance / 20) * 17) + 5000000000000000);
        owner.transfer((this.balance / 20) * 1);
        latestWinner.transfer(((this.balance - 5000000000000000) / 10) * 8);
    }
}

function vote(address tokenAddress, uint256 tokenId, address payable creator) public payable {
    require(block.number < _surveyEndBlock, "Survey ended!");
    require(_allowedVotingAmounts[msg.value] > 0, "Vote must be 0.004, 0.03, 0.1 or 0.3 ethers");
    require(_allowedTokenAddresses[tokenAddress], "Unallowed Token Address!");
    require(IERC721(tokenAddress).ownerOf(tokenId) != address(0), "Owner is nobody, maybe wrong tokenId?");
    if (_votes[tokenAddress][tokenId] == 0) {
        emit FirstVote(tokenAddress, tokenId);
    }
    _votes[tokenAddress][tokenId] = _votes[tokenAddress][tokenId] + _allowedVotingAmounts[msg.value];
    _ethers[tokenAddress][tokenId] = _ethers[tokenAddress][tokenId] + msg.value;
    creator.transfer(msg.value);
    emit Vote(msg.sender, tokenAddress, tokenId, creator, _allowedVotingAmounts[msg.value], msg.value);
}

function cashout(address winner, uint256 amount) public {
    uint256 dealerBankroll = bankrolls[msg.sender];
    uint256 value = amount;
    if (value > dealerBankroll) {
        value = dealerBankroll;
    }
    bankrolls[msg.sender] -= value;
    winner.transfer(value);
    emit Cashout(msg.sender, winner, value);
    dealerBankroll = bankrolls[msg.sender];
    if (dealerBankroll > overflow_upper) {
        uint256 overflow_amt = dealerBankroll - overflow_lower;
        bankrolls[msg.sender] -= overflow_amt;
        value = overflow_amt;
        if (msg.sender != pitboss) {
            value = overflow_amt * dealer_cut / 100;
            pitboss.transfer(overflow_amt - value);
        }
        address beneficiary = msg.sender;
        address sender_beneficiary = beneficiaries[msg.sender];
        if (sender_beneficiary > 0) {
            beneficiary = sender_beneficiary;
        }
        beneficiary.transfer(value);
        emit Overflow(msg.sender, value);
    }
}

function() public payable {
    require(fundingEnabled && (tokenPrice > 0) && (msg.value >= tokenPrice));
    totalCollected += msg.value;
    vaultAddress.transfer(msg.value);
    uint tokens = msg.value / tokenPrice;
    require((msg.sender != 0) && (msg.sender != address(this)));
    uint previousBalanceFrom = balances[this];
    require(previousBalanceFrom >= tokens);
    balances[this] = previousBalanceFrom - tokens;
    uint previousBalanceTo = balances[msg.sender];
    require(previousBalanceTo + tokens >= previousBalanceTo); 
    balances[msg.sender] = previousBalanceTo + tokens;
    emit Transfer(this, msg.sender, tokens);
    return;
}

function currentTier() private view returns(uint8 _tier) {
    uint256 currentTime = now;
    uint256 nextTierStartTime = mintingStartTime;
    while (nextTierStartTime < currentTime) {
        nextTierStartTime = nextTierStartTime.add(mintingThreshold);
        _tier++;
    }
    return _tier;
}

function getTierForLastMiniting() private view returns(uint8 _tier) {
    uint256 nextTierStartTime = mintingStartTime;
    while (nextTierStartTime < lastMintingTime) {
        nextTierStartTime = nextTierStartTime.add(mintingThreshold);
        _tier++;
    }
    return _tier;
}

function _fillOrder(uint64 buyTokenId, uint64 sellTokenId) private returns(bool success) {
    Order storage buy = buyTokenOrders[buyTokenId];
    Order storage sell = sellTokenOrders[sellTokenId];
    if (buy.amount == 0 || sell.amount == 0) {
        return false; 
    }
    require(buy.price >= sell.price, "buy price must be >= sell price");
    uint32 price = buyTokenId > sellTokenId ? sell.price : buy.price;
    uint publishedRate;
    (publishedRate, ) = rates.rates(augmintToken.peggedSymbol());
    uint sellWei = sell.amount.mul(uint(price)).mul(E12).roundedDiv(publishedRate);
    uint tradedWei;
    uint tradedTokens;
    if (sellWei <= buy.amount) {
        tradedWei = sellWei;
        tradedTokens = sell.amount;
    } else {
        tradedWei = buy.amount;
        tradedTokens = buy.amount.mul(publishedRate).roundedDiv(uint(price).mul(E12));
    }
    buy.amount = buy.amount.sub(tradedWei);
    if (buy.amount == 0) {
        _removeBuyOrder(buy);
    }
    sell.amount = sell.amount.sub(tradedTokens);
    if (sell.amount == 0) {
        _removeSellOrder(sell);
    }
    augmintToken.transferWithNarrative(buy.maker, tradedTokens, "Buy token order fill");
    sell.maker.transfer(tradedWei);
    emit OrderFill(buy.maker, sell.maker, buyTokenId,
        sellTokenId, publishedRate, price, tradedWei, tradedTokens);
    return true;
}

