function borrow(
    address asset,
    address user,
    uint amount
)
external
hasVaultAccess
notLiquidating(asset, user)
returns(uint) {
    require(vaultParameters.isOracleTypeEnabled(oracleType[asset][user], asset), "Unit Protocol: WRONG_ORACLE_TYPE");
    update(asset, user);
    debts[asset][user] = debts[asset][user].add(amount);
