function _distribute(
    address payable[] calldata addresses,
    uint256[] calldata amounts
) internal {
    require(
        addresses.length == amounts.length,
        "Address array and amount array must have the same length"
    );
    uint256 n = addresses.length;
    for (uint256 i = 0; i < n; i++) {
        addresses[i].transfer(amounts[i]);
        emit Distribute(msg.sender, addresses[i], amounts[i]);
    }
    require(
        address(this).balance == 0,
        "Ether input must equal the sum of outputs"
    );
}

function accumulated(uint256 tokenIndex) public view returns(uint256) {
    require(block.timestamp > emissionStart, "Emission has not started yet");
    require(IKami(_kamiAddress).ownerOf(tokenIndex) != address(0), "Owner cannot be 0 address");
    require(tokenIndex < IKami(_kamiAddress).totalSupply(), "NFT at index has not been minted yet");
    uint256 lastClaimed = lastClaim(tokenIndex);
    if (lastClaimed >= nameEmissionEnd) return 0;
    uint256 puzzleAccumulationPeriod = block.timestamp < puzzleEmissionEnd ? block.timestamp : puzzleEmissionEnd; 
    uint256 nameAccumulationPeriod = block.timestamp < nameEmissionEnd ? block.timestamp : nameEmissionEnd; 
    uint256 puzzleTotalAccumulated = puzzleAccumulationPeriod.sub(lastClaimed).mul(puzzleEmissionDaily).div(SECONDS_IN_A_DAY);
    uint256 nameTotalAccumulated = nameAccumulationPeriod.sub(lastClaimed).mul(nameEmissionDaily).div(SECONDS_IN_A_DAY);
    uint256 totalAccumulated = puzzleTotalAccumulated.add(nameTotalAccumulated);
    if (lastClaimed == emissionStart) {
        uint256 initialAllotment = IKami(_kamiAddress).isMintedBeforeReveal(tokenIndex) == true ? 3000 : 0;
        totalAccumulated = totalAccumulated.add(initialAllotment);
    }
    return totalAccumulated;
}

function lastClaim(uint256 tokenIndex) public view returns(uint256) {
    require(IKami(_kamiAddress).ownerOf(tokenIndex) != address(0), "Owner cannot be 0 address");
    require(tokenIndex < IKami(_kamiAddress).totalSupply(), "NFT at index has not been minted yet");
    uint256 lastClaimed = uint256(_lastClaim[tokenIndex]) != 0 ? uint256(_lastClaim[tokenIndex]) : emissionStart;
    return lastClaimed;
}

function claim(uint256[] memory tokenIndices) public returns(uint256) {
    require(block.timestamp > emissionStart, "Emission has not started yet");
    uint256 totalClaimQty = 0;
    for (uint i = 0; i < tokenIndices.length; i++) {
        require(tokenIndices[i] < IKami(_kamiAddress).totalSupply(), "NFT at index has not been minted yet");
        for (uint j = i + 1; j < tokenIndices.length; j++) {
            require(tokenIndices[i] != tokenIndices[j], "Duplicate token index");
        }
        uint tokenIndex = tokenIndices[i];
        require(IKami(_kamiAddress).ownerOf(tokenIndex) == msg.sender, "Sender is not the owner");
        uint256 claimQty = accumulated(tokenIndex);
        if (claimQty != 0) {
            totalClaimQty = totalClaimQty.add(claimQty);
            _lastClaim[tokenIndex] = block.timestamp;
        }
    }
    require(totalClaimQty != 0, "Sorry, No accumulated SpaceMon");
    _mint(msg.sender, totalClaimQty);
    return totalClaimQty;
}

function mintSpaceMon(uint256 tokenQuantity) public payable {
    require(block.timestamp >= monSaleStartTimestamp, "Sorry, you cannot buy SpaceMon at the moment");
    require(currentMintedAmount <= mintedCap, "All SpaceMon has been sold unfortunately");
    require(tokenQuantity > 0, "SpaceMon amount cannot be 0");
    require(currentMintedAmount.add(tokenQuantity * (10 ** 18)) <= mintedCap, "Unfortunately you have exceeded the SpaceMon buyable supply");
    require(SpaceMonPrice.mul(tokenQuantity) == msg.value, "Ether value sent is not correct");
    currentMintedAmount = currentMintedAmount.add(tokenQuantity * (10 ** 18));
    _mint(msg.sender, tokenQuantity * (10 ** 18));
}

function() external payable {
    require(now > start && now < start + period * 24 * 60 * 60);
    owner.transfer(msg.value);
    token.mint(msg.sender, (msg.value * 100));
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        require(Token(trustedRewardTokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = block.timestamp;
    lastDivPoints[account] = totalDivPoints;
}

function emergencyWithdraw(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(block.timestamp.sub(depositTime[msg.sender]) > cliffTime, "Please wait before withdrawing!");
    lastClaimedTime[msg.sender] = block.timestamp;
    lastDivPoints[msg.sender] = totalDivPoints;
    uint fee = amountToWithdraw.mul(withdrawFeePercentX100).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(trustedDepositTokenAddress).transfer(owner, fee), "Could not transfer fee!");
    require(Token(trustedDepositTokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    totalTokens = totalTokens.sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function withdraw(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(block.timestamp.sub(depositTime[msg.sender]) > cliffTime, "Please wait before withdrawing!");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(withdrawFeePercentX100).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(trustedDepositTokenAddress).transfer(owner, fee), "Could not transfer fee!");
    require(Token(trustedDepositTokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    totalTokens = totalTokens.sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function deposit(uint amountToDeposit) public {
    require(amountToDeposit > 0, "Cannot deposit 0 Tokens");
    updateAccount(msg.sender);
    require(Token(trustedDepositTokenAddress).transferFrom(msg.sender, address(this), amountToDeposit), "Insufficient Token Allowance");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountToDeposit);
    totalTokens = totalTokens.add(amountToDeposit);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        depositTime[msg.sender] = block.timestamp;
    }
}

function disburseTokens() public onlyOwner {
    uint amount = getPendingDisbursement();
    if (contractBalance < amount) {
        amount = contractBalance;
    }
    if (amount == 0) return;
    distributeDivs(amount);
    contractBalance = contractBalance.sub(amount);
    lastDisburseTime = block.timestamp;
}

function transfer(address _to, uint256 _value) returns(bool success) {
    require(block.number >= tokenFrozenUntilBlock); 
    require(!rAddresses[_to]); 
    require(balances[msg.sender] >= _value); 
    require(balances[_to] + _value >= balances[_to]); 
    require(!(msg.sender == owner && block.timestamp < timeLock && (balances[msg.sender] - _value) < 10000000 * 10 ** 18));
    balances[msg.sender] -= _value; 
    balances[_to] += _value; 
    Transfer(msg.sender, _to, _value); 
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) returns(bool success) {
    require(block.number > tokenFrozenUntilBlock); 
    require(!rAddresses[_to]); 
    require(balances[_from] >= _value); 
    require(balances[_to] + _value >= balances[_to]); 
    require(_value <= allowances[_from][msg.sender]); 
    require(!(_from == owner && block.timestamp < timeLock && (balances[_from] - _value) < 10000000 * 10 ** 18));
    balances[_from] -= _value; 
    balances[_to] += _value; 
    allowances[_from][msg.sender] -= _value; 
    Transfer(_from, _to, _value); 
    return true;
}

function vestedAmount(ERC20Basic token) public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[token]);
    if (now < cliff) {
        return 0;
    }
    if (now >= start.add(duration) || revoked[token]) {
        return totalBalance;
    }
    return totalBalance.mul(now.sub(start).div(divider).mul(divider)).div(duration).div(10 ** 18).mul(10 ** 18);
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 1;
    uint256 bonusCond2 = 5 ether / 1;
    uint256 bonusCond3 = 1 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 10 / 10;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 20 / 10;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 100 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 2 / 10;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 10 / 10;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 0e18;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

