}

function requireTrade(address from) public view {
    require(!readOnly, "Read only mode engaged");
    uint256 i = 0;
    address current = addressLinkedList[0];
    while (current != 0) {
        if (current == from) {
            uint256 timestamp = freezeUntil[current];
            require(timestamp < block.timestamp, "Trades from your account are temporarily not possible. This is due to ICO rules.");
            break;
        }
        current = addressLinkedList[current];
        i++;
    }
}

function getCurrentRate() public view returns(uint256) {
    if (now <= openingTime.add(14 days)) return rate.add(rate / 5); 
    if (now > openingTime.add(14 days) && now <= openingTime.add(28 days)) return rate.add(rate * 3 / 20); 
    if (now > openingTime.add(28 days) && now <= openingTime.add(42 days)) return rate.add(rate / 10); 
}

function doPurchase(address _sender) private stopInEmergency {
    require(tokensSelling != 0);
    require(msg.value >= 0.01 * 1 ether);
    uint tokens = msg.value * 1 ether / tokenPrice;
    require(token.balanceOf(_sender).add(tokens) <= purchaseLimit);
    tokensSelling = tokensSelling.sub(tokens);
    tokensSoldTotal = tokensSoldTotal.add(tokens);
    if (token.balanceOf(_sender) == 0) investorCount++;
    weiRaisedTotal = weiRaisedTotal.add(msg.value);
    token.transfer(_sender, tokens);
    beneficiary.transfer(msg.value);
    NewContribution(_sender, tokens, msg.value);
}

function finishPhase() onlyOwner {
    require(tokensSelling != 0);
    token.transfer(beneficiary, tokensSelling);
    tokensSelling = 0;
}

function startPhase(
    uint256 _tokens,
    uint256 _price,
    uint256 _limit
) onlyOwner {
    require(tokensSelling == 0);
    require(_tokens <= token.balanceOf(this));
    tokensSelling = _tokens * 1 ether;
    tokenPrice = _price;
    purchaseLimit = _limit * 1 ether;
}

function take(address _token) public auth {
    uint256 _moar;
    address payable[] memory _folks = folks;
    if (_token == address(0)) {
        _moar = sub(address(this).balance, total[_token]);
    } else {
        _moar = sub(IERC20(_token).balanceOf(address(this)), total[_token]);
    }
    if (_moar > 0) {
        total[_token] = add(total[_token], _moar);
        for (uint256 i = 0; i < _folks.length; i++) {
            balance[_folks[i]][_token] = add(
                balance[_folks[i]][_token],
                mul(_moar, bps[i]) / THOUSAND
            );
        }
    }
    for (uint256 i = 0; i < _folks.length; i++) {
        comp(_folks[i]);
    }
    send(_token);
    emit Push();
}

