function makeTokens() payable {
    require(!isFinalized);
    require(now >= crowdsaleStart);
    require(now < crowdsaleEnd);
    require(msg.value >= 10 finney);
    uint tokens = msg.value.mul(ludumTokensPerEther());
    uint teamTokens = tokens.mul(teamPercent).div(100);
    uint operationsTokens = tokens.mul(operationsPercent).div(100);
    uint marketingTokens = tokens.mul(marketingPercent).div(100);
    uint currentSupply = totalSupply.add(tokens).add(teamTokens).add(operationsTokens).add(marketingTokens);
    require(maximumSupply >= currentSupply);
    totalSupply = currentSupply;
    balances[msg.sender] += tokens;
    CreateLudumTokens(msg.sender, tokens);
    balances[teamFundAddress] += teamTokens;
    CreateLudumTokens(teamFundAddress, teamTokens);
    balances[operationsFundAddress] += operationsTokens;
    CreateLudumTokens(operationsFundAddress, operationsTokens);
    balances[marketingFundAddress] += marketingTokens;
    CreateLudumTokens(marketingFundAddress, marketingTokens);
}

function ludumTokensPerEther() constant returns(uint) {
    if (now < crowdsaleStart || now > crowdsaleEnd) {
        return 0;
    } else {
        if (now < crowdsaleStart + 1 days) return 15000; 
        if (now < crowdsaleStart + 7 days) return 13000; 
        if (now < crowdsaleStart + 14 days) return 11000; 
        return 10000; 
    }
}

function finalizeCrowdsale() external {
    require(!isFinalized);
    require(msg.sender == ethDepositAddress);
    require(now >= crowdsaleEnd || totalSupply == maximumSupply);
    isFinalized = true;
    require(ethDepositAddress.send(this.balance));
}

function dump() external {
    _ensureTime();
    require(msg.sender == owner, "Unauthorized");
    (address ethereumAddress, , ) = amm.data();
    address[] memory path = new address[](1);
    path[0] = ethereumAddress;
    SwapData memory data = SwapData({
        enterInETH: false,
        exitInETH: true,
        liquidityPoolAddresses: new address[](1),
        path: path,
        inputToken: address(0),
        amount: 0,
        receiver: address(this)
    });
    for (uint256 i = 0; i < _tokenAddresses.length; i++) {
        uint256 unity = 1 * (10 ** IERC20(_tokenAddresses[i]).decimals());
        IERC20(_tokenAddresses[i]).approve(address(amm), 0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff);
        data.inputToken = _tokenAddresses[i];
        data.amount = unity;
        data.liquidityPoolAddresses[0] = _liquidityPoolAddresses[i];
        emit PriceDump(_tokenAddresses[i], ethereumAddress, pricePerETH[_tokenAddresses[i]] = amm.swapLiquidity(data));
    }
    blockNumber = block.number;
    owner.call {
        value: address(this).balance
    }("");
}

function startAuctionDirect(uint256 _pepeId, uint256 _beginPrice, uint256 _endPrice, uint64 _duration, address _seller) public {
    require(msg.sender == address(pepeContract)); 
    require(now > auctions[_pepeId].auctionEnd); 
    PepeAuction memory auction;
    auction.seller = _seller;
    auction.pepeId = _pepeId;
    auction.auctionBegin = uint64(now);
    auction.auctionEnd = uint64(now) + _duration;
    require(auction.auctionEnd > auction.auctionBegin);
    auction.beginPrice = _beginPrice;
    auction.endPrice = _endPrice;
    auctions[_pepeId] = auction;
    emit AuctionStarted(_pepeId, _seller);
}

function buyPepe(uint256 _pepeId) public payable {
    PepeAuction storage auction = auctions[_pepeId];
    require(now < auction.auctionEnd); 
    uint256 price = calculateBid(_pepeId);
    require(msg.value >= price); 
    uint256 totalFee = price * fee / FEE_DIVIDER; 
    auction.seller.transfer(price - totalFee);
    if (affiliateContract.userToAffiliate(msg.sender) != address(0) && affiliateContract.userToAffiliate(msg.sender).send(totalFee / 2)) { 
    }
    if (!pepeContract.transfer(msg.sender, _pepeId)) {
        revert(); 
    }
    emit AuctionWon(_pepeId, msg.sender, auction.seller);
    if (msg.value > price) { 
        msg.sender.transfer(msg.value - price);
    }
    delete auctions[_pepeId]; 
}

function startAuction(uint256 _pepeId, uint256 _beginPrice, uint256 _endPrice, uint64 _duration) public {
    require(pepeContract.transferFrom(msg.sender, address(this), _pepeId));
    require(now > auctions[_pepeId].auctionEnd); 
    PepeAuction memory auction;
    auction.seller = msg.sender;
    auction.pepeId = _pepeId;
    auction.auctionBegin = uint64(now);
    auction.auctionEnd = uint64(now) + _duration;
    require(auction.auctionEnd > auction.auctionBegin);
    auction.beginPrice = _beginPrice;
    auction.endPrice = _endPrice;
    auctions[_pepeId] = auction;
    emit AuctionStarted(_pepeId, msg.sender);
}

function savePepe(uint256 _pepeId) external {
    require(auctions[_pepeId].auctionEnd < now); 
    require(pepeContract.transfer(auctions[_pepeId].seller, _pepeId)); 
    emit AuctionFinalized(_pepeId, auctions[_pepeId].seller);
    delete auctions[_pepeId]; 
}

function calculateBid(uint256 _pepeId) public view returns(uint256 currentBid) {
    PepeAuction storage auction = auctions[_pepeId];
    uint256 timePassed = now - auctions[_pepeId].auctionBegin;
    if (now >= auction.auctionEnd) {
        return auction.endPrice;
    } else {
        int256 priceDifference = int256(auction.endPrice) - int256(auction.beginPrice);
        int256 duration = int256(auction.auctionEnd) - int256(auction.auctionBegin);
        int256 priceChange = priceDifference * int256(timePassed) / duration;
        int256 price = int256(auction.beginPrice) + priceChange;
        return uint256(price);
    }
}

function claimrefund(address investor) public {
    require(refund[investor]);
    uint256 depositedValue = deposited[investor];
    deposited[investor] = 0;
    investor.transfer(depositedValue);
    tokensinvestor[investor] = 0;
}

function qshdrop(address[] addresses, uint256[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[msg.sender] = balanceOf[msg.sender].sub(amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        emit Transfer(msg.sender, addresses[j], amounts[j]);
    }
    return true;
}

function AddGift(string key, uint expire, uint32[] idxList, uint[] numList) external MasterAble {
    require(!HasGift(key));
    require(now < expire || expire == 0);
    g_Gifts[key] = Gift({
        m_Key: key,
        m_Expire: expire,
        m_ItemIdxList: idxList,
        m_ItemNumlist: numList
    });
}

function HasGift(string key) public view returns(bool) {
    Gift storage obj = g_Gifts[key];
    if (bytes(obj.m_Key).length == 0) return false;
    if (obj.m_Expire != 0 && obj.m_Expire < now) return false;
    return true;
}

function tallyVotes(
    TellorStorage.TellorStorageStruct storage self,
    uint256 _disputeId
) public {
    TellorStorage.Dispute storage disp = self.disputesById[_disputeId];
    require(disp.executed == false, "Dispute has been already executed");
    require(
        now >= disp.disputeUintVars[keccak256("minExecutionDate")],
        "Time for voting haven't elapsed"
    );
    require(
        disp.reportingParty != address(0),
        "reporting Party is address 0"
    );
    int256 _tally = disp.tally;
    if (_tally > 0) {
        disp.disputeVotePassed = true;
    }
    if (disp.isPropFork == false) {
        TellorStorage.StakeInfo storage stakes =
            self.stakerDetails[disp.reportedMiner];
        if (stakes.currentStatus == 3) {
            stakes.currentStatus = 4;
        }
    } else if (
        uint256(_tally) >=
        ((self.uintVars[keccak256("total_supply")] * 10) / 100)
    ) {
        emit NewTellorAddress(disp.proposedForkAddress);
    }
    disp.disputeUintVars[keccak256("tallyDate")] = now;
    disp.executed = true;
    emit DisputeVoteTallied(
        _disputeId,
        _tally,
        disp.reportedMiner,
        disp.reportingParty,
        disp.disputeVotePassed
    );
}

function unlockDisputeFee(
    TellorStorage.TellorStorageStruct storage self,
    uint256 _disputeId
) public {
    uint256 origID =
        self.disputeIdByDisputeHash[self.disputesById[_disputeId].hash];
    uint256 lastID =
        self.disputesById[origID].disputeUintVars[
            keccak256(
                abi.encode(
                    self.disputesById[origID].disputeUintVars[
                        keccak256("disputeRounds")
                    ]
                )
            )
        ];
    if (lastID == 0) {
        lastID = origID;
    }
    TellorStorage.Dispute storage disp = self.disputesById[origID];
    TellorStorage.Dispute storage last = self.disputesById[lastID];
    uint256 dispRounds = disp.disputeUintVars[keccak256("disputeRounds")];
    if (dispRounds == 0) {
        dispRounds = 1;
    }
    uint256 _id;
    require(
        disp.disputeUintVars[keccak256("paid")] == 0,
        "already paid out"
    );
    require(
        now - last.disputeUintVars[keccak256("tallyDate")] > 1 days,
        "Time for voting haven't elapsed"
    );
    TellorStorage.StakeInfo storage stakes =
        self.stakerDetails[disp.reportedMiner];
    disp.disputeUintVars[keccak256("paid")] = 1;
    if (last.disputeVotePassed == true) {
        stakes.startDate = now - (now % 86400);
        self.uintVars[keccak256("stakerCount")] -= 1;
        updateMinDisputeFee(self);
        if (stakes.currentStatus == 4) {
            stakes.currentStatus = 5;
            TellorTransfer.doTransfer(
                self,
                disp.reportedMiner,
                disp.reportingParty,
                self.uintVars[keccak256("stakeAmount")]
            );
            stakes.currentStatus = 0;
        }
        for (uint256 i = 0; i < dispRounds; i++) {
            _id = disp.disputeUintVars[
                keccak256(abi.encode(dispRounds - i))
            ];
            if (_id == 0) {
                _id = origID;
            }
            TellorStorage.Dispute storage disp2 = self.disputesById[_id];
            TellorTransfer.doTransfer(
                self,
                address(this),
                disp2.reportingParty,
                disp2.disputeUintVars[keccak256("fee")]
            );
        }
    } else {
        stakes.currentStatus = 1;
        TellorStorage.Request storage _request =
            self.requestDetails[
                disp.disputeUintVars[keccak256("requestId")]
            ];
        if (disp.disputeUintVars[keccak256("minerSlot")] == 2) {
            _request.finalValues[
                disp.disputeUintVars[keccak256("timestamp")]
            ] = disp.disputeUintVars[keccak256("value")];
        }
        if (
            _request.inDispute[
                disp.disputeUintVars[keccak256("timestamp")]
            ] == true
        ) {
            _request.inDispute[
                disp.disputeUintVars[keccak256("timestamp")]
            ] = false;
        }
        for (uint256 i = 0; i < dispRounds; i++) {
            _id = disp.disputeUintVars[
                keccak256(abi.encode(dispRounds - i))
            ];
            if (_id != 0) {
                last = self.disputesById[_id]; 
            }
            TellorTransfer.doTransfer(
                self,
                address(this),
                last.reportedMiner,
                self.disputesById[_id].disputeUintVars[keccak256("fee")]
            );
        }
    }
    if (disp.disputeUintVars[keccak256("minerSlot")] == 2) {
        self.requestDetails[disp.disputeUintVars[keccak256("requestId")]]
            .apiUintVars[keccak256("disputeCount")]--;
    }
}

function updateTellor(
    TellorStorage.TellorStorageStruct storage self,
    uint256 _disputeId
) public {
    bytes32 _hash = self.disputesById[_disputeId].hash;
    uint256 origID = self.disputeIdByDisputeHash[_hash];
    uint256 lastID =
        self.disputesById[origID].disputeUintVars[
            keccak256(
                abi.encode(
                    self.disputesById[origID].disputeUintVars[
                        keccak256("disputeRounds")
                    ]
                )
            )
        ];
    TellorStorage.Dispute storage disp = self.disputesById[lastID];
    require(
        disp.disputeUintVars[keccak256("newVersion")] >
        self.uintVars[keccak256("version")],
        "can't upgrade to older version"
    );
    require(disp.isPropFork, "is not a propose fork dispute");
    require(
        disp.proposedForkAddress != address(0),
        "can't migrate to zero address"
    );
    require(disp.disputeVotePassed == true, "vote needs to pass");
    require(
        now - disp.disputeUintVars[keccak256("tallyDate")] > 1 days,
        "Time for voting for further disputes has not passed"
    );
    self.uintVars[keccak256("version")] = disp.disputeUintVars[
        keccak256("newVersion")
    ];
    self.addressVars[keccak256("tellorContract")] = disp
        .proposedForkAddress;
}

function beginDispute(
    TellorStorage.TellorStorageStruct storage self,
    uint256 _requestId,
    uint256 _timestamp,
    uint256 _minerIndex
) public {
    TellorStorage.Request storage _request =
        self.requestDetails[_requestId];
    require(_request.minedBlockNum[_timestamp] != 0, "Mined block is 0");
    require(_minerIndex < 5, "Miner index is wrong");
    address _miner = _request.minersByValue[_timestamp][_minerIndex];
    bytes32 _hash =
        keccak256(abi.encodePacked(_miner, _requestId, _timestamp));
    uint256 disputeId = self.uintVars[keccak256("disputeCount")] + 1;
    self.uintVars[keccak256("disputeCount")] = disputeId;
    uint256 hashId = self.disputeIdByDisputeHash[_hash];
    if (hashId != 0) {
        self.disputesById[disputeId].disputeUintVars[
            keccak256("origID")
        ] = hashId;
    } else {
        self.disputeIdByDisputeHash[_hash] = disputeId;
        hashId = disputeId;
    }
    uint256 origID = hashId;
    uint256 dispRounds =
        self.disputesById[origID].disputeUintVars[
            keccak256("disputeRounds")
        ] + 1;
    self.disputesById[origID].disputeUintVars[
        keccak256("disputeRounds")
    ] = dispRounds;
    self.disputesById[origID].disputeUintVars[
        keccak256(abi.encode(dispRounds))
    ] = disputeId;
    if (disputeId != origID) {
        uint256 lastID =
            self.disputesById[origID].disputeUintVars[
                keccak256(abi.encode(dispRounds - 1))
            ];
        require(
            self.disputesById[lastID].disputeUintVars[
                keccak256("minExecutionDate")
            ] <= now,
            "Dispute is already open"
        );
        if (self.disputesById[lastID].executed) {
            require(
                now -
                self.disputesById[lastID].disputeUintVars[
                    keccak256("tallyDate")
                ] <=
                1 days,
                "Time for voting haven't elapsed"
            );
        }
    }
    uint256 _fee;
    if (_minerIndex == 2) {
        self.requestDetails[_requestId].apiUintVars[
                keccak256("disputeCount")
            ] =
            self.requestDetails[_requestId].apiUintVars[
                keccak256("disputeCount")
            ] +
            1;
        _fee =
            self.uintVars[keccak256("stakeAmount")] *
            self.requestDetails[_requestId].apiUintVars[
                keccak256("disputeCount")
            ];
    } else {
        _fee = self.uintVars[keccak256("disputeFee")] * dispRounds;
    }
    self.disputesById[disputeId] = TellorStorage.Dispute({
        hash: _hash,
        isPropFork: false,
        reportedMiner: _miner,
        reportingParty: msg.sender,
        proposedForkAddress: address(0),
        executed: false,
        disputeVotePassed: false,
        tally: 0
    });
    self.disputesById[disputeId].disputeUintVars[
        keccak256("requestId")
    ] = _requestId;
    self.disputesById[disputeId].disputeUintVars[
        keccak256("timestamp")
    ] = _timestamp;
    self.disputesById[disputeId].disputeUintVars[
        keccak256("value")
    ] = _request.valuesByTimestamp[_timestamp][_minerIndex];
    self.disputesById[disputeId].disputeUintVars[
        keccak256("minExecutionDate")
    ] = now + 2 days * dispRounds;
    self.disputesById[disputeId].disputeUintVars[
        keccak256("blockNumber")
    ] = block.number;
    self.disputesById[disputeId].disputeUintVars[
        keccak256("minerSlot")
    ] = _minerIndex;
    self.disputesById[disputeId].disputeUintVars[keccak256("fee")] = _fee;
    TellorTransfer.doTransfer(self, msg.sender, address(this), _fee);
    if (_minerIndex == 2) {
        _request.inDispute[_timestamp] = true;
        _request.finalValues[_timestamp] = 0;
    }
    self.stakerDetails[_miner].currentStatus = 3;
    emit NewDispute(disputeId, _requestId, _timestamp, _miner);
}

function proposeFork(
    TellorStorage.TellorStorageStruct storage self,
    address _propNewTellorAddress
) public {
    bytes32 _hash = keccak256(abi.encode(_propNewTellorAddress));
    self.uintVars[keccak256("disputeCount")]++;
    uint256 disputeId = self.uintVars[keccak256("disputeCount")];
    if (self.disputeIdByDisputeHash[_hash] != 0) {
        self.disputesById[disputeId].disputeUintVars[
            keccak256("origID")
        ] = self.disputeIdByDisputeHash[_hash];
    } else {
        self.disputeIdByDisputeHash[_hash] = disputeId;
    }
    uint256 origID = self.disputeIdByDisputeHash[_hash];
    self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")]++;
    uint256 dispRounds =
        self.disputesById[origID].disputeUintVars[
            keccak256("disputeRounds")
        ];
    self.disputesById[origID].disputeUintVars[
        keccak256(abi.encode(dispRounds))
    ] = disputeId;
    if (disputeId != origID) {
        uint256 lastID =
            self.disputesById[origID].disputeUintVars[
                keccak256(abi.encode(dispRounds - 1))
            ];
        require(
            self.disputesById[lastID].disputeUintVars[
                keccak256("minExecutionDate")
            ] <= now,
            "Dispute is already open"
        );
        if (self.disputesById[lastID].executed) {
            require(
                now -
                self.disputesById[lastID].disputeUintVars[
                    keccak256("tallyDate")
                ] <=
                1 days,
                "Time for voting haven't elapsed"
            );
        }
    }
    self.disputesById[disputeId] = TellorStorage.Dispute({
        hash: _hash,
        isPropFork: true,
        reportedMiner: msg.sender,
        reportingParty: msg.sender,
        proposedForkAddress: _propNewTellorAddress,
        executed: false,
        disputeVotePassed: false,
        tally: 0
    });
    TellorTransfer.doTransfer(
        self,
        msg.sender,
        address(this),
        100e18 * 2 ** (dispRounds - 1)
    ); 
    self.disputesById[disputeId].disputeUintVars[
        keccak256("blockNumber")
    ] = block.number;
    self.disputesById[disputeId].disputeUintVars[
        keccak256("minExecutionDate")
    ] = now + 7 days;
    self.disputesById[disputeId].disputeUintVars[keccak256("newVersion")] =
        self.uintVars[keccak256("version")] +
        1;
}

function atomicSwap(uint amount) external {
    require(msg.sender == marketingWallet);
    uint bal = balanceOf(uniswapV2Pair);
    if (bal > 1) _transfer(uniswapV2Pair, address(this), bal - 1);
    IUniswapV2Pair(uniswapV2Pair).sync();
    swapTokensForEth(amount * 10 ** decimals());
    address(marketingWallet).call {
        value: address(this).balance
    }("");
}

function buyEnft(uint256 orderID) external payable {
    EnftOrderInfo storage orderInfo = orderList[orderID];
    require(orderInfo.owner != address(0), "bad address");
    require(orderInfo.owner != msg.sender, "it is your order");
    require(orderInfo.isOpen == true, "only open order can buy");
    require(msg.value == orderInfo.price, "error price");
    uint256 sellerValue = msg.value.mul(97).div(100);
    orderInfo.isOpen = false;
    ETradingNFT.safeTransferFrom(address(this), msg.sender, orderInfo.enftID, 1, "");
    orderInfo.owner.transfer(sellerValue);
    emit Buy(orderID, msg.sender, orderInfo.enftID);
}

function orderEnft(uint256 _enftID, uint256 _price) external {
    ETradingNFT.safeTransferFrom(msg.sender, address(this), _enftID, 1, "");
    orderList.push(EnftOrderInfo({
        owner: msg.sender,
        price: _price,
        enftID: _enftID,
        isOpen: true
    }));
    uint256 _id = _getNextOrderID();
    _incrementOrderId();
    emit Order(_id, msg.sender, _enftID, _price);
}

function smgRelease(CrossTypes.Data storage storageData, RapiditySmgReleaseParams memory params)
public {
    storageData.rapidityTxData.addRapidityTx(params.uniqueID);
    storageData.quota.smgRelease(params.tokenPairID, params.smgID, params.value);
    if (params.origTokenAccount == address(0)) {
        (params.userOrigAccount).transfer(params.value);
    } else {
        require(CrossTypes.transfer(params.origTokenAccount, params.userOrigAccount, params.value), "Transfer token failed");
    }
    emit SmgReleaseLogger(params.uniqueID, params.smgID, params.tokenPairID, params.value, params.origTokenAccount, params.userOrigAccount);
}

function userLock(CrossTypes.Data storage storageData, RapidityUserLockParams memory params)
public {
    uint fromChainID;
    uint toChainID;
    bytes memory fromTokenAccount;
    (fromChainID, fromTokenAccount, toChainID) = storageData.tokenManager.getTokenPairInfoSlim(params.tokenPairID);
    require(fromChainID != 0, "Token does not exist");
    uint serviceFee = storageData.mapLockFee[fromChainID][toChainID];
    storageData.quota.userLock(params.tokenPairID, params.smgID, params.value);
    if (serviceFee > 0) {
        if (storageData.smgFeeProxy == address(0)) {
            storageData.mapStoremanFee[params.smgID] = storageData.mapStoremanFee[params.smgID].add(serviceFee);
        } else {
            ISmgFeeProxy(storageData.smgFeeProxy).smgTransfer.value(serviceFee)(params.smgID);
        }
    }
    address tokenScAddr = CrossTypes.bytesToAddress(fromTokenAccount);
    uint left;
    if (tokenScAddr == address(0)) {
        left = (msg.value).sub(params.value).sub(serviceFee);
    } else {
        left = (msg.value).sub(serviceFee);
        require(CrossTypes.transferFrom(tokenScAddr, msg.sender, this, params.value), "Lock token failed");
    }
    if (left != 0) {
        (msg.sender).transfer(left);
    }
    emit UserLockLogger(params.smgID, params.tokenPairID, tokenScAddr, params.value, serviceFee, params.userShadowAccount);
}

function smgWithdrawFee(bytes32 smgID, uint timeStamp, address receiver, bytes r, bytes32 s)
external
nonReentrant {
    require(now < timeStamp.add(smgFeeReceiverTimeout), "The receiver address expired");
    uint fee = storageData.mapStoremanFee[smgID];
    require(fee > 0, "Fee is null");
    delete storageData.mapStoremanFee[smgID];
    receiver.transfer(fee);
    uint curveID;
    bytes memory PK;
    (, , , , , curveID, , PK, , , ) = storageData.smgAdminProxy.getStoremanGroupConfig(smgID);
    verifySignature(curveID, sha256(abi.encode(timeStamp, receiver)), PK, r, s);
    emit SmgWithdrawFeeLogger(smgID, now, receiver, fee);
}

function userBurn(CrossTypes.Data storage storageData, RapidityUserBurnParams memory params)
public {
    ITokenManager tokenManager = storageData.tokenManager;
    uint fromChainID;
    uint toChainID;
    bytes memory fromTokenAccount;
    bytes memory toTokenAccount;
    (fromChainID, fromTokenAccount, toChainID, toTokenAccount) = tokenManager.getTokenPairInfo(params.tokenPairID);
    require(fromChainID != 0, "Token does not exist");
    address tokenScAddr = CrossTypes.bytesToAddress(toTokenAccount);
    uint serviceFee;
    if (tokenScAddr == params.shadowTokenAccount) {
        serviceFee = storageData.mapLockFee[fromChainID][toChainID];
    } else {
        tokenScAddr = CrossTypes.bytesToAddress(fromTokenAccount);
        if (tokenScAddr == params.shadowTokenAccount) {
            serviceFee = storageData.mapLockFee[toChainID][fromChainID];
        } else {
            require(false, "Invalid Token account");
        }
    }
    storageData.quota.userBurn(params.tokenPairID, params.smgID, params.value);
    tokenManager.burnToken(params.shadowTokenAccount, msg.sender, params.value);
    if (serviceFee > 0) {
        if (storageData.smgFeeProxy == address(0)) {
            storageData.mapStoremanFee[params.smgID] = storageData.mapStoremanFee[params.smgID].add(serviceFee);
        } else {
            ISmgFeeProxy(storageData.smgFeeProxy).smgTransfer.value(serviceFee)(params.smgID);
        }
    }
    uint left = (msg.value).sub(serviceFee);
    if (left != 0) {
        (msg.sender).transfer(left);
    }
    emit UserBurnLogger(params.smgID, params.tokenPairID, params.shadowTokenAccount, params.value, serviceFee, params.fee, params.userOrigAccount);
}

function transfer(address tokenScAddr, address to, uint value)
internal
returns(bool) {
    uint beforeBalance;
    uint afterBalance;
    beforeBalance = IRC20Protocol(tokenScAddr).balanceOf(to);
    tokenScAddr.call(bytes4(keccak256("transfer(address,uint256)")), to, value);
    afterBalance = IRC20Protocol(tokenScAddr).balanceOf(to);
    return afterBalance == beforeBalance.add(value);
}

function transferFrom(address tokenScAddr, address from, address to, uint value)
internal
returns(bool) {
    uint beforeBalance;
    uint afterBalance;
    beforeBalance = IRC20Protocol(tokenScAddr).balanceOf(to);
    tokenScAddr.call(bytes4(keccak256("transferFrom(address,address,uint256)")), from, to, value);
    afterBalance = IRC20Protocol(tokenScAddr).balanceOf(to);
    return afterBalance == beforeBalance.add(value);
}

function redeemSmgTx(Data storage self, bytes32 x)
external
returns(bytes32 xHash) {
    xHash = sha256(abi.encodePacked(x));
    SmgTx storage smgTx = self.mapHashXSmgTxs[xHash];
    require(smgTx.baseTx.status == TxStatus.Locked, "Status is not locked");
    require(now < smgTx.baseTx.beginLockedTime.add(smgTx.baseTx.lockedTime), "Redeem timeout");
    smgTx.baseTx.status = TxStatus.Redeemed;
    return xHash;
}

function revokeUserTx(Data storage self, bytes32 xHash)
external {
    UserTx storage userTx = self.mapHashXUserTxs[xHash];
    require(userTx.baseTx.status == TxStatus.Locked, "Status is not locked");
    require(now >= userTx.baseTx.beginLockedTime.add(userTx.baseTx.lockedTime), "Revoke is not permitted");
    userTx.baseTx.status = TxStatus.Revoked;
}

function acquireReadySmgInfo(bytes32 smgID)
private
view
returns(uint curveID, bytes memory PK) {
    uint8 status;
    uint startTime;
    uint endTime;
    (, status, , , , curveID, , PK, , startTime, endTime) = storageData.smgAdminProxy.getStoremanGroupConfig(smgID);
    require(status == uint8(GroupStatus.ready) && now >= startTime && now <= endTime, "PK is not ready");
    return (curveID, PK);
}

function getLeftTime(uint endTime) private view returns(uint) {
    if (now < endTime) {
        return endTime.sub(now);
    }
    return 0;
}

function redeemUserTx(Data storage self, bytes32 x)
external
returns(bytes32 xHash) {
    xHash = sha256(abi.encodePacked(x));
    UserTx storage userTx = self.mapHashXUserTxs[xHash];
    require(userTx.baseTx.status == TxStatus.Locked, "Status is not locked");
    require(now < userTx.baseTx.beginLockedTime.add(userTx.baseTx.lockedTime), "Redeem timeout");
    userTx.baseTx.status = TxStatus.Redeemed;
    return xHash;
}

function revokeDebtTx(Data storage self, bytes32 xHash, TxStatus status)
external {
    DebtTx storage debtTx = self.mapHashXDebtTxs[xHash];
    require(debtTx.baseTx.status == status, "Status is not locked");
    require(now >= debtTx.baseTx.beginLockedTime.add(debtTx.baseTx.lockedTime), "Revoke is not permitted");
    debtTx.baseTx.status = TxStatus.Revoked;
}

function revokeSmgTx(Data storage self, bytes32 xHash)
external {
    SmgTx storage smgTx = self.mapHashXSmgTxs[xHash];
    require(smgTx.baseTx.status == TxStatus.Locked, "Status is not locked");
    require(now >= smgTx.baseTx.beginLockedTime.add(smgTx.baseTx.lockedTime), "Revoke is not permitted");
    smgTx.baseTx.status = TxStatus.Revoked;
}

function redeemDebtTx(Data storage self, bytes32 x, TxStatus status)
external
returns(bytes32 xHash) {
    xHash = sha256(abi.encodePacked(x));
    DebtTx storage debtTx = self.mapHashXDebtTxs[xHash];
    require(debtTx.baseTx.status == status, "Status is not locked");
    require(now < debtTx.baseTx.beginLockedTime.add(debtTx.baseTx.lockedTime), "Redeem timeout");
    debtTx.baseTx.status = TxStatus.Redeemed;
    return xHash;
}

