function mine() external nonReentrant {
    uint256 _blockNum = external_to_internal_block_number(current_external_block());
    require(!base_contract.checkMiningAttempt(_blockNum, this));
    uint256 total_attempt = 0;
    uint8 total_ejected = 0;
    for (uint8 i = 0; i < total_users; i++) {
        address user_address = active_users[i];
        if (user_address > 0) {
            user memory u = users[user_address];
            if (u.end_block <= mined_blocks) {
                if (total_ejected < 10) {
                    delete active_users[i];
                    slots.push(i);
                    delete users[active_users[i]];
                    total_ejected = total_ejected + 1;
                }
            } else {
                total_attempt = total_attempt + u.proportional_contribution;
            }
        }
    }
    if (total_attempt > 0) {
        attempts[_blockNum] = total_attempt;
        base_contract.mine.value(total_attempt)();
        mined_blocks = mined_blocks + 1;
    }
}

function() payable {
    require(msg.value >= calculate_minimum_contribution());
    user storage current_user = users[msg.sender];
    if (current_user.start_block > 0) {
        if (current_user.end_block > mined_blocks) {
            uint256 periods_left = current_user.end_block - mined_blocks;
            uint256 amount_remaining = current_user.proportional_contribution * periods_left;
            amount_remaining = amount_remaining + msg.value;
            amount_remaining = amount_remaining / contract_period;
            current_user.proportional_contribution = amount_remaining;
        } else {
            current_user.proportional_contribution = msg.value / contract_period;
        }
        do_redemption();
    } else {
        current_user.proportional_contribution = msg.value / contract_period;
        allocate_slot(msg.sender);
    }
    current_user.start_block = mined_blocks;
    current_user.end_block = mined_blocks + contract_period;
}

function claim(uint256 _blockNumber, address forCreditTo)
nonReentrant
external returns(bool) {
    require(base_contract.checkWinning(_blockNumber));
    uint256 initial_balance = base_contract.balanceOf(this);
    base_contract.claim(_blockNumber, this);
    uint256 balance = base_contract.balanceOf(this);
    uint256 total_attempt = attempts[_blockNumber];
    distribute_reward(total_attempt, balance - initial_balance);
    claimed_blocks = claimed_blocks + 1;
}

function do_redemption() internal {
    uint256 balance = balances[msg.sender];
    if (balance > 0) {
        uint256 owner_cut = (balance / 100) * pool_percentage;
        uint256 remainder = balance - owner_cut;
        if (owner_cut > 0) {
            base_contract.transfer(owner, owner_cut);
        }
        base_contract.transfer(msg.sender, remainder);
        balances[msg.sender] = 0;
    }
}

function _getTokenAmount(uint256 _weiAmount) internal view returns(uint256) {
    if (now < privateSaleCloseTime) {
        return _weiAmount.mul(privateSaleRate);
    }
    if (now < preSaleCloseTime) {
        return _weiAmount.mul(preSaleRate);
    }
    return _weiAmount.mul(rate);
}

function isCrowdsaleOpen() public view returns(bool) {
    return now >= openingTime && now <= closingTime;
}

function finalize() onlyOwner public {
    require(!isFinalized, "Crowdsale already finalised");
    finalization();
    emit Finalized();
    isFinalized = true;
}

function() isWhitelisted acceptingPayments payable public {
    uint256 _contribution = msg.value;
    require(_contribution >= minContribution);
    require(_contribution <= maxContribution);
    require(msg.sender != address(0));
    amountPaid[msg.sender] += _contribution;
    amountRaised = amountRaised.add(_contribution);
    if (amountRaised > saleLimit) {
        uint256 _refundAmount = amountRaised.sub(saleLimit);
        msg.sender.transfer(_refundAmount);
        _contribution = _contribution.sub(_refundAmount);
        _refundAmount = 0;
        amountRaised = saleLimit;
        isAcceptingPayments = false;
    }
    wallet.transfer(_contribution);
}

function epoch(uint256 ETHPerToken) public onlyOwnerOrOperator {
    uint256 balance = pendingBalance();
    harvest(balance.mul(ETHPerToken));
    lastEpochTime = block.timestamp;
    lastBalance = lastBalance.add(balance);
    uint256 currentWithdrawd = vault.totalYieldWithdrawed();
    uint256 withdrawAmountToken = currentWithdrawd.sub(lastYieldWithdrawed);
    if (withdrawAmountToken > 0) {
        lastYieldWithdrawed = currentWithdrawd;
        uint256 ethWithdrawed = withdrawAmountToken.mul(
            ETHPerToken
        );
        withdrawFromYearn(ethWithdrawed);
    }
}

function completeOrderBySafePeriod() public onlyDeveloper {
    require(now >= safeLastDate);
    developerWallet.transfer(this.balance);
}

function orderNotAccepted() public onlyCustomer {
    require(now >= orderLastDate);
    safeLastDate += SAFE_PERIOD;
}

function unlock() public onlyOwner {
    if (lockAddresses[privateSell1Address] && now >= privateSell1LockEndTime)
        lockAddresses[privateSell1Address] = false;
    if (lockAddresses[privateSell2Address] && now >= privateSell2LockEndTime)
        lockAddresses[privateSell2Address] = false;
    if (lockAddresses[team1Address] && now >= team1LockEndTime)
        lockAddresses[team1Address] = false;
    if (lockAddresses[team2Address] && now >= team2LockEndTime)
        lockAddresses[team2Address] = false;
    if (lockAddresses[team3Address] && now >= team3LockEndTime)
        lockAddresses[team3Address] = false;
    if (lockAddresses[team4Address] && now >= team4LockEndTime)
        lockAddresses[team4Address] = false;
}

function mintTokens(address holder, uint256 amount) external {
    assert(msg.sender == ico_contract);
    assert(now < endDateICO);
    _balances[holder] = add(_balances[holder], amount);
    _supply = add(_supply, amount);
    Transfer(address(0x0), holder, amount);
}

function getRate() public constant returns(uint256 rate) {
    if (now < FIRST_ROUND) {
        return (FIRST_ROUND_RATE);
    } else if (now < SECOND_ROUND) {
        return (SECOND_ROUND_RATE);
    } else {
        return (FINAL_ROUND_RATE);
    }
}

function finishSale() onlyOwner public {
    if (this.balance > 0) {
        FundAddress.transfer(this.balance);
    }
    transferOVISBookedTokens();
    transferRewardPool();
    transferOPSPool();
    CurrentState = ICOState.Finished;
    SaleFinished();
}

function contribute() private {
    uint256 _jointAmount = 0;
    uint256 _jointBonusAmount = 0;
    uint256 _jointTransferAmount = 0;
    uint256 _bonusRate = 0;
    uint256 _ethAmount = msg.value;
    if (msg.value.mul(JOINT_PER_ETH) > AVAILABLE_JOINTTOKENS) {
        _ethAmount = AVAILABLE_JOINTTOKENS.div(JOINT_PER_ETH);
    } else {
        _ethAmount = msg.value;
    }
    _bonusRate = PriceStrategy.getRate();
    _jointAmount = (_ethAmount.mul(JOINT_PER_ETH));
    _jointBonusAmount = _ethAmount.mul(JOINT_PER_ETH).mul(_bonusRate).div(100);
    _jointTransferAmount = _jointAmount.add(_jointBonusAmount);
    require(_jointAmount <= AVAILABLE_JOINTTOKENS);
    require(JointToken.transfer(msg.sender, _jointTransferAmount));
    require(OPSToken.transfer(msg.sender, _jointTransferAmount));
    if (msg.value > _ethAmount) {
        msg.sender.transfer(msg.value.sub(_ethAmount));
        CurrentState = ICOState.Stopped;
        SoldOutandSaleStopped();
    }
    AVAILABLE_JOINTTOKENS = AVAILABLE_JOINTTOKENS.sub(_jointAmount);
    ICOSALE_JOINTTOKENS = ICOSALE_JOINTTOKENS.add(_jointAmount);
    ICOSALE_BONUSJOINTTOKENS = ICOSALE_BONUSJOINTTOKENS.add(_jointBonusAmount);
    TOTAL_CONTRIBUTOR_COUNT = TOTAL_CONTRIBUTOR_COUNT.add(1);
    Contribution(msg.sender, _ethAmount, _jointTransferAmount);
}

function getFund(uint256 _amount) onlyOwner public {
    require(_amount <= this.balance);
    FundAddress.transfer(_amount);
    Funded(FundAddress, _amount);
}

function startSale() onlyOwner public {
    require(CurrentState == ICOState.NotStarted);
    require(JointToken.balanceOf(address(this)) > 0);
    require(OPSToken.balanceOf(address(this)) > 0);
    CurrentState = ICOState.Started;
    transferPresaleTokens();
    transferTokenOPSPlatformTokens();
    SaleStarted();
}

function revoke() saleFailed public {
    uint256 investedValue = invested[msg.sender];
    require(investedValue > 0);
    invested[msg.sender] = 0;
    msg.sender.transfer(investedValue);
    emit Revoke(msg.sender, investedValue);
}

function finish()
onlyOwner
saleCompletedSuccessfully
public {
    uint256 freeEthers = address(this).balance * 40 / 100;
    uint256 vestedEthers = address(this).balance - freeEthers;
    address(0xd1B10607921C78D9a00529294C4b99f1bd250E1c).transfer(freeEthers); 
    assert(address(0x0285d35508e1A1f833142EB5211adb858Bd3323A).call.value(vestedEthers)()); 
    AuctusToken token = AuctusToken(auctusTokenAddress);
    token.setTokenSaleFinished();
    if (remainingTokens > 0) {
        token.burn(remainingTokens);
        remainingTokens = 0;
    }
}

function()
payable
openSale
public {
    uint256 weiToInvest;
    uint256 weiRemaining;
    (weiToInvest, weiRemaining) = getValueToInvest();
    require(weiToInvest > 0);
    uint256 tokensToReceive = weiToInvest.mul(basicPricePerEth);
    remainingTokens = remainingTokens.sub(tokensToReceive);
    weiRaised = weiRaised.add(weiToInvest);
    invested[msg.sender] = invested[msg.sender].add(weiToInvest);
    if (weiRemaining > 0) {
        msg.sender.transfer(weiRemaining);
    }
    assert(AuctusToken(auctusTokenAddress).transfer(msg.sender, tokensToReceive));
    emit Buy(msg.sender, tokensToReceive);
}

function setTokenSaleDistribution(uint256 totalAmount) private {
    uint256 auctusCoreTeam = totalAmount * 20 / 100;
    uint256 bounty = totalAmount * 2 / 100;
    uint256 reserveForFuture = totalAmount * 18 / 100;
    uint256 partnershipsAdvisoryFree = totalAmount * 18 / 1000;
    uint256 partnershipsAdvisoryVested = totalAmount * 72 / 1000;
    uint256 privateSales = 2970000000000000000000000;
    uint256 preSale = 2397307557007329968290000;
    transferTokens(auctusCoreTeam, bounty, reserveForFuture, preSale, partnershipsAdvisoryVested, partnershipsAdvisoryFree, privateSales);
    remainingTokens = totalAmount - auctusCoreTeam - bounty - reserveForFuture - preSale - partnershipsAdvisoryVested - partnershipsAdvisoryFree - privateSales;
    saleWasSet = true;
}

function setSoftCap(uint256 minimumCap) onlyOwner public {
    require(now < startTime);
    softCap = minimumCap;
}

function setEndSaleTime(uint256 endSaleTime) onlyOwner public {
    require(now < endTime);
    endTime = endSaleTime;
}

function lift(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > PossibleUnstakeTime, "You have not staked for a while yet, kindly wait a bit more");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(liquiditytoken1).transfer(admin, fee), "Could not transfer withdraw fee.");
    require(Token(liquiditytoken1).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function place(uint amountToStake) public {
    require(stakingStatus == true, "Staking is not yet initialized");
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(liquiditytoken1).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(liquiditytoken1).transfer(admin, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function mint(address to, uint256 tokensAmount) public onlyMinter canMint nonZeroAddress(to) returns(bool) {
    hookOperator.onMint(to, tokensAmount);
    totalSupply = totalSupply.add(tokensAmount);
    balances[to] = balances[to].add(tokensAmount);
    emit Mint(to, tokensAmount);
    emit Transfer(address(0), to, tokensAmount);
    return true;
}

function burn(uint tokensAmount) public {
    hookOperator.onBurn(tokensAmount);
    super.burn(tokensAmount);
}

function transfer(address to, uint tokensAmount) public nonZeroAddress(to) returns(bool) {
    hookOperator.onTransfer(msg.sender, to, tokensAmount);
    return super.transfer(to, tokensAmount);
}

function transferFrom(address from, address to, uint tokensAmount) public nonZeroAddress(from) nonZeroAddress(to) returns(bool) {
    hookOperator.onTransfer(from, to, tokensAmount);
    return super.transferFrom(from, to, tokensAmount);
}

function transferOverBalanceFunds(address from, address to, uint rate) external payable onlyRefunder nonZeroAddress(from) nonZeroAddress(to) returns(bool) {
    require(!hookOperator.isOverBalanceLimitHolder(from));
    uint256 oracleRate = aiurExchangeOracle.rate();
    require(rate <= oracleRate.add(oracleRate.div(MIN_REFUND_RATE_DELIMITER)));
    uint256 fromBalance = balanceOf(from);
    uint256 maxTokensBalance = totalSupply.mul(hookOperator.getBalancePercentageLimit()).div(100);
    require(fromBalance > maxTokensBalance);
    uint256 tokensToTake = fromBalance.sub(maxTokensBalance);
    uint256 weiToRefund = aiurExchangeOracle.convertTokensAmountInWeiAtRate(tokensToTake, rate);
    require(hookOperator.isInBalanceLimit(to, tokensToTake));
    require(msg.value == weiToRefund);
    transferDirectly(from, to, tokensToTake);
    from.transfer(msg.value);
    emit LogTransferOverFunds(from, to, weiToRefund, tokensToTake);
    return true;
}

function createTokens() public isUnderHardCap saleIsOn payable {
    uint tokens = rate.mul(msg.value).div(1 ether);
    uint bonusTokens = 0;
    if (now < start + (period * 1 days).div(4)) {
        bonusTokens = tokens.div(2);
    } else if (now >= start + (period * 1 days).div(4) && now < start + (period * 1 days).div(4).mul(2)) {
        bonusTokens = tokens.div(4);
    } else if (now >= start + (period * 1 days).div(4).mul(2) && now < start + (period * 1 days).div(4).mul(3)) {
        bonusTokens = tokens.div(10);
    }
    tokens += bonusTokens;
    token.mint(msg.sender, tokens);
    balances[msg.sender] = balances[msg.sender].add(msg.value);
}

function refund() public {
    address onMultisig = this;
    require(onMultisig.balance < softcap && now > start + period * 1 days);
    uint value = balances[msg.sender];
    balances[msg.sender] = 0;
    msg.sender.transfer(value);
}

function finalize() onlyOwner public {
    require(!isFinalized);
    require(hasEnded());
    finalization();
    emit Finalized();
    isFinalized = true;
}

function buyTokens(address beneficiary, uint weiAmount) internal whenNotPaused {
    require(contributions[beneficiary].add(weiAmount) < currentCap());
    require(whiteListed.whiteList(beneficiary));
    require((weiAmount > MIN_CONTRIBUTION) || (weiAmount == SALE_CAP.sub(MIN_CONTRIBUTION)));
    weiRaised = weiRaised.add(weiAmount);
    uint tokens = weiAmount.mul(getRateAndCheckCap());
    if (contributions[beneficiary] == 0) {
        numContributors++;
    }
    tokensRaised = tokensRaised.add(tokens);
    contributions[beneficiary] = contributions[beneficiary].add(weiAmount);
    token.mint(beneficiary, tokens);
    emit TokenPurchase(beneficiary, weiAmount, tokens);
    forwardFunds();
}

constructor(WhiteListed _whiteListed) public {
    require(now < SALE_START);
    require(_whiteListed != address(0));
    whiteListed = _whiteListed;
    token = new REDTToken(owner);
    token.mint(MULTISIG_TKN, RESERVE_AMOUNT);
    initCaps();
}

function currentCap() public view returns(uint) {
    for (uint i = 0; i < capz.length; i++) {
        if (now < SALE_START + capz[i].time * 1 hours)
            return (capz[i].amount * 1 ether);
    }
    return capDefault;
}

function hasEnded() public view returns(bool) {
    return ((now > SALE_END) || (tokensRaised >= SALE_CAP));
}

function getRateAndCheckCap() public view returns(uint) {
    require(now > SALE_START);
    if ((now < SALE0_END) && (tokensRaised < SALE0_CAP))
        return SALE0_RATE;
    if ((now < SALE1_END) && (tokensRaised < SALE1_CAP))
        return SALE1_RATE;
    if ((now < SALE2_END) && (tokensRaised < SALE2_CAP))
        return SALE2_RATE;
    revert();
}

function placeTokens(address beneficiary, uint256 numtokens)
public
ownerOrMinter {
    require(now < SALE_START);
    tokensRaised = tokensRaised.add(numtokens);
    token.mint(beneficiary, numtokens);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends() > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens / 1e18);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _amountOfTokens / 1e18);
    Transfer(_customerAddress, _toAddress, _amountOfTokens);
    return true;
}

function withdraw()
hasDividends()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends();
    payoutsTo_[_customerAddress] += (int256)(_dividends);
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function purchaseTokens(uint256 _incomingEthereum)
internal
returns(uint256) {
    require(!locked_);
    require(_incomingEthereum >= 1e17);
    address _customerAddress = msg.sender;
    uint256 _amountOfTokens = _incomingEthereum * 20;
    require(_amountOfTokens > 0 && (SafeMath.add(_amountOfTokens, tokenSupply_) > tokenSupply_));
    require(SafeMath.add(tokenSupply_, _amountOfTokens) < maxTokens);
    if (tokenSupply_ > 0) {
        tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    if (tokenSupply_ > maxTokens) locked_ = true;
    tokenBalanceLedger_[_customerAddress] = SafeMath.add(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens / 1e18));
    payoutsTo_[_customerAddress] += _updatedPayouts;
    companyAccount_.transfer(_incomingEthereum);
    onTokenPurchase(_customerAddress, _incomingEthereum, _amountOfTokens);
    return _amountOfTokens;
}

function deposit(address payable vault, address asset, uint amount, string memory memo) public payable {
    uint safeAmount;
    if (asset == address(0)) {
        safeAmount = msg.value;
        vault.call {
            value: safeAmount
        }("");
    } else if (asset == RUNE) {
        safeAmount = amount;
        iRUNE(RUNE).transferTo(address(this), amount);
        iERC20(RUNE).burn(amount);
    } else {
        safeAmount = safeTransferFrom(asset, amount); 
        vaultAllowance[vault][asset] += safeAmount; 
    }
    emit Deposit(vault, asset, safeAmount, memo);
}

function transferOut(address payable to, address asset, uint amount, string memory memo) public payable {
    uint safeAmount;
    if (asset == address(0)) {
        safeAmount = msg.value;
        to.call {
            value: msg.value
        }(""); 
    } else {
        vaultAllowance[msg.sender][asset] -= amount; 
        asset.call(abi.encodeWithSelector(0xa9059cbb, to, amount));
        safeAmount = amount;
    }
    emit TransferOut(msg.sender, to, asset, safeAmount, memo);
}

function returnVaultAssets(address router, address payable asgard, Coin[] memory coins, string memory memo) public payable {
    if (router == address(this)) {
        for (uint i = 0; i < coins.length; i++) {
            _adjustAllowances(asgard, coins[i].asset, coins[i].amount);
        }
        emit VaultTransfer(msg.sender, asgard, coins, memo); 
    } else {
        for (uint i = 0; i < coins.length; i++) {
            _routerDeposit(router, asgard, coins[i].asset, coins[i].amount, memo);
        }
    }
    asgard.call {
        value: msg.value
    }(""); 
}

function buy(uint256 _itemId, uint256 _sellPrice, string _name, string _ownerName, string _ownerWords, string _ownerImg, string _ownerNation) payable public returns(bool _result) {
    require(_checkItemId(_itemId));
    require(ownerOf(_itemId) != msg.sender);
    require(msg.sender != address(0));
    require(_sellPrice == 0 || _sellPrice.sub(priceInit) >= 0);
    require(msg.value.sub(sellPriceOf(_itemId)) >= 0);
    require(msg.value.mul(2).sub(_sellPrice) >= 0);
    if (_sellPrice == 0)
        _sellPrice = calculateNextPrice(msg.value);
    if (tokenExists(_itemId) == false)
        newItem(_itemId, _name, priceInit);
    address oldOwner = ownerOf(_itemId);
    address newOwner = msg.sender;
    if (oldOwner != address(0)) {
        if (msg.value > priceOf(_itemId)) {
            uint256 tradeCut;
            tradeCut = msg.value.sub(priceOf(_itemId));
            tradeCut = tradeCut.mul(10).div(100);
            oldOwner.transfer(msg.value.sub(tradeCut));
        } else
            oldOwner.transfer(msg.value);
    }
    priceOfItem[_itemId] = msg.value;
    sellPriceOfItem[_itemId] = _sellPrice;
    OwnerInfo memory oi = OwnerInfo(_ownerName, _ownerWords, _ownerImg, _ownerNation);
    ownerInfoOfItem[_itemId] = oi;
    _transfer(oldOwner, newOwner, _itemId);
    emit Bought(_itemId, newOwner, msg.value);
    emit Sold(_itemId, oldOwner, msg.value);
    owner().transfer(address(this).balance);
    return true;
}

function transfer(address _to, uint256 _value, bytes _data, string _custom_fallback) public returns(bool success) {
    require(_to != address(0));
    require(_to != address(this));
    require(_value <= balances[msg.sender]);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    if (isContract(_to)) {
        _to.call.value(0)(bytes4(keccak256(_custom_fallback)), msg.sender, _value, _data);
    }
    Transfer(msg.sender, _to, _value, _data);
    return true;
}

function withdraw() public {
    assert(msg.sender.call.value(balances[msg.sender])());
    balances[msg.sender] = 0;
}

function() payable {
    require(block.timestamp >= start && block.timestamp <= deadline && amountRaised < (6000 ether));
    uint amount = msg.value;
    balanceOf[msg.sender] += amount;
    amountRaised += amount;
    FundTransfer(msg.sender, amount, true);
    if (beneficiary.send(amount)) {
        FundTransfer(beneficiary, amount, false);
    }
}

function send(address[] _addresses, uint256[] _values) external onlyOwner {
    require(_addresses.length == _values.length);
    uint i;
    uint s;
    for (i = 0; i < _values.length; i++) {
        s += _values[i];
    }
    require(s <= this.balance);
    for (i = 0; i < _addresses.length; i++) {
        _addresses[i].transfer(_values[i]);
        Transfer(_addresses[i], _values[i]);
    }
}

function initSale(
    address _companyWallet,
    address _teamWallet,
    address _advisorWallet,
    address _reserveWallet
) public onlyOwner {
    require(!initiated);
    require(_companyWallet != 0x0);
    require(_teamWallet != 0x0);
    require(_advisorWallet != 0x0);
    require(_reserveWallet != 0x0);
    companyWallet = _companyWallet;
    teamWallet = _teamWallet;
    advisorWallet = _advisorWallet;
    reserveWallet = _reserveWallet;
    _deliverTokens(companyWallet, companyTokens.div(2)); 
    companyTimeLock = new TokenTimelock(token, companyWallet, uint64(1559339940)); 
    _deliverTokens(address(companyTimeLock), companyTokens.div(2));
    teamTimeLock = new TokenTimelock(token, teamWallet, uint64(1577833140)); 
    _deliverTokens(address(teamTimeLock), teamTokens);
    _deliverTokens(advisorWallet, advisorTokens);
    _deliverTokens(reserveWallet, reserveTokens);
    initiated = true;
}

function started() public view returns(bool) {
    return now >= openingTime;
}

function ended() public view returns(bool) {
    return hasClosed() || capReached();
}

function transfer(address to, uint256 tokens)
public
returns(bool success) {
    require(now >= transferrableTime);
    require(to != address(this));
    require(balances[msg.sender] >= tokens);
    balances[msg.sender] = balances[msg.sender].sub(tokens);
    balances[to] = balances[to].add(tokens);
    Transfer(msg.sender, to, tokens);
    return true;
}

function releaseVestedTokens(uint256 vestingPeriod) public {
    require(now >= transferrableTime.add(vestingPeriod));
    require(vestingMap[vestingPeriod].length > 0);
    require(vestingMap[vestingPeriod][0].balance > 0);
    var v = vestingMap[vestingPeriod];
    for (uint8 i = 0; i < v.length; i++) {
        balances[v[i].addr] = balances[v[i].addr].add(v[i].balance);
        _circulatingSupply = _circulatingSupply.add(v[i].balance);
        _vestedSupply = _vestedSupply.sub(v[i].balance);
        VestedTokensReleased(v[i].addr, v[i].balance);
        Transfer(0x00, v[i].addr, v[i].balance);
        v[i].balance = 0;
    }
}

function approve(address spender, uint256 tokens)
public
returns(bool success) {
    require(now >= transferrableTime);
    require(spender != address(this));
    allowed[msg.sender][spender] = tokens;
    Approval(msg.sender, spender, tokens);
    return true;
}

function transferFrom(
    address from,
    address to,
    uint256 tokens
) public returns(bool success) {
    require(now >= transferrableTime);
    require(to != address(this));
    require(allowed[from][msg.sender] >= tokens);
    balances[from] = balances[from].sub(tokens);
    allowed[from][msg.sender] = allowed[from][msg.sender].sub(tokens);
    balances[to] = balances[to].add(tokens);
    Transfer(from, to, tokens);
    return true;
}

function _setBidState(uint _hashBid, StatusName _newStatus) internal returns(bool) {
    require(bidStatuses[_hashBid].status != StatusName.CANCELED, "Bid status is CANCELLED, no more changes allowed");
    if (bidStatuses[_hashBid].status == StatusName.FUNDED && _newStatus == StatusName.NEW) {
        revert('Status change not allowed: from FUNDED to NEW');
    }
    bidStatuses[_hashBid].status = _newStatus;
    bidStatuses[_hashBid].userStatusUpdate = msg.sender;
    bidStatuses[_hashBid].timeUpdate = now;
    emit BidStateChanged(_hashBid, _newStatus);
    return true;
}

function _writeBid(address _user, uint _hashBid, StatusName _newStatus) internal returns(bool) {
    if (bidStatuses[_hashBid].timeUpdate != 0) { 
        if (bidStatuses[_hashBid].status == _newStatus) { 
            return true;
        } else {
            bool isBidOwner = false;
            for (uint i = 0; i < userBids[_user].bids.length; i++) {
                if (userBids[_user].bids[i] == _hashBid) {
                    isBidOwner = true;
                }
            }
            if (!isBidOwner) {
                return false;
            } else {
                return _setBidState(_hashBid, _newStatus);
            }
        }
    }
    if (userBids[_user].timeInit == 0) { 
        users.push(_user);
        userBids[_user].timeInit = now;
    }
    userBids[_user].bids.push(_hashBid);
    BidStatus memory bidStatus;
    bidStatus.status = _newStatus;
    bidStatus.user = _user;
    bidStatus.userStatusUpdate = msg.sender;
    bidStatus.timeUpdate = now;
    bidStatuses[_hashBid] = bidStatus;
    emit BidUpdated(_hashBid, uint8(_newStatus));
    return true;
}

function closeCrowdsale() onlyOwner public {
    require(!crowdsaleClosed);
    beneficiary.transfer(this.balance);
    token.mint(beneficiary, token.totalSupply().div(100).mul(65));
    token.finishMinting();
    token.transferOwnership(beneficiary);
    crowdsaleClosed = true;
    CrowdsaleClose();
}

function purchase() whenNotPaused payable public {
    require(!crowdsaleClosed);
    require(msg.value >= 0.001 ether);
    Step memory step = steps[currentStep];
    require(step.purchase);
    require(step.tokensSold < step.tokensForSale);
    require(token.balanceOf(msg.sender) < 500000 ether);
    uint sum = msg.value;
    uint amount = sum.mul(1 ether).div(step.priceTokenWei);
    uint retSum = 0;
    uint retAmount;
    if (step.tokensSold.add(amount) > step.tokensForSale) {
        retAmount = step.tokensSold.add(amount).sub(step.tokensForSale);
        retSum = retAmount.mul(step.priceTokenWei).div(1 ether);
        amount = amount.sub(retAmount);
        sum = sum.sub(retSum);
    }
    if (token.balanceOf(msg.sender).add(amount) > 500000 ether) {
        retAmount = token.balanceOf(msg.sender).add(amount).sub(500000 ether);
        retSum = retAmount.mul(step.priceTokenWei).div(1 ether);
        amount = amount.sub(retAmount);
        sum = sum.sub(retSum);
    }
    steps[currentStep].tokensSold = step.tokensSold.add(amount);
    steps[currentStep].collectedWei = step.collectedWei.add(sum);
    purchaseBalances[msg.sender] = purchaseBalances[msg.sender].add(sum);
    token.mint(msg.sender, amount);
    if (retSum > 0) {
        msg.sender.transfer(retSum);
    }
    Purchase(msg.sender, amount, sum);
}

function sell(uint256 _value) whenNotPaused public {
    require(!crowdsaleClosed);
    require(canSell[msg.sender] >= _value);
    require(token.balanceOf(msg.sender) >= _value);
    Step memory step = steps[currentStep];
    require(step.sale);
    canSell[msg.sender] = canSell[msg.sender].sub(_value);
    token.burnOwner(msg.sender, _value);
    uint sum = _value.mul(step.priceTokenWei).div(1 ether);
    msg.sender.transfer(sum);
    Sell(msg.sender, _value, sum);
}

function refund() public {
    require(crowdsaleRefund);
    require(purchaseBalances[msg.sender] > 0);
    uint sum = purchaseBalances[msg.sender];
    purchaseBalances[msg.sender] = 0;
    refundedWei = refundedWei.add(sum);
    msg.sender.transfer(sum);
    Refund(msg.sender, sum);
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (!_isExcludedFromFee[to] && !_isExcludedFromFee[from]) {
        if (from == uniswapV2Pair && to != address(uniswapV2Router)) {
            require(tradeAllowed);
            require(cooldown[to] < block.timestamp);
            uint walletBalance = balanceOf(address(to));
            require(amount.add(walletBalance) <= _tTotal.div(20));
            require(amount <= _maxTxAmount);
            cooldown[to] = block.timestamp + (30 seconds);
            _teamFee = 6;
            _reflection = 2;
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            require(cooldown[from] < block.timestamp);
            require(amount <= balanceOf(uniswapV2Pair).mul(5).div(100));
            uint initialBalance = address(this).balance;
            swapTokensForEth(contractTokenBalance);
            uint newBalance = address(this).balance;
            uint distributeETHBalance = newBalance.sub(initialBalance);
            if (distributeETHBalance > 0) {
                sendETHToFee(distributeETHBalance);
            }
            _reflection = 2;
            _teamFee = 14;
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee;
}

