function updateAccount(address account) public returns(uint new_balance) {
    require(frozen == false);
    require(round <= 9);
    require(bitmask_check(account, 1024) == false); 
    if (epoch > 1 && accounts[account].lastEpoch < epoch) {
        uint entire = accounts[account].balance / 100000000; 
        if ((accounts[account].balance - entire * 100000000) > 0) {
            emit Transfer(account, address(0), (accounts[account].balance - entire * 100000000));
        }
        accounts[account].balance = entire * 100000000;
        accounts[account].lastEpoch = epoch;
        accounts[account].lastRound = round;
        return accounts[account].balance;
    }
    if (round > accounts[account].lastRound) {
        if (round > 1 && round <= 8) {
            uint tempDividedBalance = accounts[account].balance / current_mul();
            uint newFixedBalance = tempDividedBalance * current_mul();
            uint lastActiveDigit = tempDividedBalance % 10;
            uint diff = accounts[account].balance - newFixedBalance;
            if (diff > 0) {
                accounts[account].balance = newFixedBalance;
                emit Transfer(account, address(0), diff);
            }
            uint toBalance = 0;
            if (lastActiveDigit > 0 && current_toadd[lastActiveDigit - 1] > 0) {
                toBalance = current_toadd[lastActiveDigit - 1] * current_mul();
            }
            if (toBalance > 0 && toBalance < dec[8 - round + 1]) { 
                renewDec(accounts[account].balance, accounts[account].balance.add(toBalance));
                emit Transfer(address(0), account, toBalance);
                accounts[account].balance = accounts[account].balance.add(toBalance);
                dec[8 - round + 1] = dec[8 - round + 1].sub(toBalance);
                _totalSupply = _totalSupply.add(toBalance);
            }
            accounts[account].lastRound = round;
            if (accounts[account].lastEpoch != epoch) {
                accounts[account].lastEpoch = epoch;
            }
            return accounts[account].balance;
        } else {
            if (round == 9) { 
                uint newBalance = fix_amount(accounts[account].balance);
                uint _diff = accounts[account].balance.sub(newBalance);
                if (_diff > 0) {
                    renewDec(accounts[account].balance, newBalance);
                    accounts[account].balance = newBalance;
                    emit Transfer(account, address(0), _diff);
                }
                accounts[account].lastRound = round;
                if (accounts[account].lastEpoch != epoch) {
                    accounts[account].lastEpoch = epoch;
                }
                return accounts[account].balance;
            }
        }
    }
}

function finalize() onlyOwner public {
    if (now < endTime) { 
        if (coinSentToEther == MAX_CAP) {} else {
            throw;
        }
    }
    if (coinSentToEther < MIN_CAP && now < endTime + 15 days) throw; 
    if (!multisigEther.send(this.balance)) throw; 
    uint remains = coin.balanceOf(this);
    if (remains > 0) { 
        if (!coin.burn(remains)) throw;
    }
    crowdsaleClosed = true;
}

function bonus(uint amount) internal constant returns(uint) {
    if (now < startTime.add(2 days)) return amount.add(amount.div(5)); 
    return amount;
}

function refund() external onlyAfter(endTime) stopInEmergency { 
    if (!crowdsaleFinished) revert();
    if (softCapReached) revert();
    if (refunded[msg.sender]) revert();
    uint256 balance = token.balanceOf(msg.sender);
    if (balance == 0) revert();
    uint256 to_refund = balance.mul(1 ether).div(price);
    if (to_refund > this.balance) {
        to_refund = this.balance; 
    }
    msg.sender.transfer(to_refund); 
    refunded[msg.sender] = true;
    weiRefunded = weiRefunded.add(to_refund);
    Refunded(msg.sender, to_refund);
}

function doPurchase(address _buyer, uint256 _amount) private onlyAfter(startTime) onlyBefore(endTime) stopInEmergency {
    if (crowdsaleFinished) revert();
    if (collected.add(_amount) > hardCap) revert();
    if ((!softCapReached) && (collected < softCap) && (collected.add(_amount) >= softCap)) {
        softCapReached = true;
        SoftCapReached(softCap);
    }
    uint256 tokens = _amount.mul(price).div(1 ether); 
    if (tokens == 0) revert();
    if (token.balanceOf(_buyer) == 0) investorCount++;
    collected = collected.add(_amount);
    token.transfer(_buyer, tokens);
    weiRaised = weiRaised.add(_amount);
    tokensSold = tokensSold.add(tokens);
    NewContribution(_buyer, tokens, _amount);
    if (collected == hardCap) {
        GoalReached(hardCap);
    }
}

function withdraw() onlyOwner {
    if (!softCapReached) revert();
    beneficiary.transfer(collected);
    token.transfer(beneficiary, token.balanceOf(this));
    crowdsaleFinished = true;
}

function extend(uint256 _duration) onlyOwner {
    endTime = endTime + _duration * 1 hours;
    duration = duration + _duration;
    if ((startTime + 4500 hours) < endTime) revert();
    CrowdsaleExtended(endTime);
}

function start(
    uint256 _hardCap,
    uint256 _softCap,
    uint256 _duration,
    uint256 _price) onlyOwner {
    if (startTime > 0) revert();
    hardCap = _hardCap * 1 ether;
    softCap = _softCap * 1 ether;
    price = _price;
    startTime = now;
    endTime = startTime + _duration * 1 hours;
    duration = _duration;
    CrowdsaleStarted(now, softCap, hardCap, price);
}

