    daiTkn.transferFrom(msg.sender, address(this), daiWipe); 
    MakerCDP loanMaster = MakerCDP(cdpAddr);
    loanMaster.wipe(bytes32(cdpNum), daiWipe); 
    uint mkrCharged = contractMKR - mkrTkn.balanceOf(address(this)); 
