    remainingTokens = remainingTokens.sub(tokenAmount);
    soldTokens = soldTokens.add(tokenAmount);
    emit BuyRC(msg.sender, msg.data, msg.value, tokenAmount, oneTokenInFiatWei);
}

function started() public view returns(bool) {
