function getOrderStateHelper(uint256 _nowDayIndex, uint256 _oID)
internal
view
returns(uint) {
    PopoDatasets.Order memory _order = oID_Order_[_oID];
    if (
        _order.hasWithdrawn
    ) {
        return (
            3
        );
    } else {
        if (
            _nowDayIndex < _order.createDayIndex ||
            _nowDayIndex > _order.createDayIndex.add(5)
        ) {
            return (
                2
            );
        } else {
            return (
                1
            );
        }
    }
}

function accrued(uint256 _time, uint48 _bgn, uint48 _fin, uint128 _tot) internal pure returns(uint256 amt) {
    if (_time < _bgn) {
        amt = 0;
    } else if (_time >= _fin) {
        amt = _tot;
    } else {
        amt = mul(_tot, sub(_time, _bgn)) / sub(_fin, _bgn); 
    }
}

function unpaid(uint256 _id) external view returns(uint256 amt) {
    Award memory _award = awards[_id];
    require(_award.usr != address(0), "DssVest/invalid-award");
    amt = unpaid(block.timestamp, _award.bgn, _award.clf, _award.fin, _award.tot, _award.rxd);
}

function getPendingDivs(address _holder) public view returns(uint256) {
    if (!holders.contains(_holder)) return 0;
    if (depositedTokens[_holder] == 0) return 0;
    uint256 timeDiff = now.sub(lastClaimedTime[_holder]);
    uint256 stakedAmount = depositedTokens[_holder];
    if (now > farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(2010797).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    } else if (now <= farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(rewardRate).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    }
}

function buyTokensCrowdsale(address receiver) internal  {
    uint256 weiAmount = msg.value;
    uint256 tokenAmount = 0;
    if (getState() == State.PreFunding) {
        if (weiAmount < PRESALE_ETH_IN_WEI_ACCEPTED_MIN) revert();
        if ((PRESALE_ETH_IN_WEI_FUND_MAX > 0) && ((presale_eth_fund.add(weiAmount)) > PRESALE_ETH_IN_WEI_FUND_MAX)) revert();
        tokenAmount = calculateTokenPresale(weiAmount, token_decimals);
        presale_eth_fund = presale_eth_fund.add(weiAmount);
    } else if ((getState() == State.Funding) || (getState() == State.Success)) {
        if (weiAmount < CROWDSALE_ETH_IN_WEI_ACCEPTED_MIN) revert();
        tokenAmount = calculateTokenCrowsale(weiAmount, token_decimals);
    } else {
        revert();
    }
    if (tokenAmount == 0) {
        revert();
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = investedAmountOf[receiver].add(weiAmount);
    tokenAmountOf[receiver] = tokenAmountOf[receiver].add(tokenAmount);
    crowdsale_eth_fund = crowdsale_eth_fund.add(weiAmount);
    tokensSold = tokensSold.add(tokenAmount);
    token.mint(receiver, tokenAmount);
    if (!multisigWallet.send(weiAmount)) revert();
    Invested(receiver, weiAmount, tokenAmount);
}

function doFinalize() public inState(State.Success) onlyOwner stopInEmergency {
    if (finalized) {
        revert();
    }
    createTeamTokenByPercentage();
    token.finishMinting();
    finalized = true;
    Finalized();
}

function hasEnded() public constant returns(bool) {
    return now > endsAt;
}

function setEndsAt(uint time) onlyOwner public {
    if (now > time) {
        revert();
    }
    endsAt = time;
    EndsAtChanged(endsAt);
}

function getState() public constant returns(State) {
    if (finalized) return State.Finalized;
    else if (now < startsAt) return State.PreFunding;
    else if (now <= endsAt && !isMinimumGoalReached()) return State.Funding;
    else if (isMinimumGoalReached()) return State.Success;
    else if (!isMinimumGoalReached() && crowdsale_eth_fund > 0 && loadedRefund >= crowdsale_eth_fund) return State.Refunding;
    else return State.Failure;
}

function redeemPreSale(address _address) public returns(bool) {
    if (!redeemed[_address]) {
        uint256 value = AuctusPreSale(auctusPreSaleAddress).getTokenAmount(_address);
        if (value > 0) {
            redeemed[_address] = true;
            escrowedTokens = escrowedTokens.sub(value);
            assert(AuctusToken(auctusTokenAddress).transfer(_address, value));
            emit Redeem(_address, value);
            return true;
        }
    }
    return false;
}

function adminPurchase(
    uint256 _amountToken,
    uint256 _usdPurchase,
    uint256 _pricePurchase
) public onlyGovernor returns(bool) {
    SaleInfo storage i = info[totalSaleContracts];
    require(
        i.totalPurchased <= i.allocated,
        "Sold Out"
    );
    require(
        block.timestamp < i.end,
        "Purchase Ended"
    );
    Sale storage s = sale[msg.sender][Math.add(totalPurchases[msg.sender], 1)];
    s.usdPurchase = _usdPurchase;
    s.amountPurchased = _amountToken;
    s.pricePurchase = _pricePurchase;
    s.timestamp = block.timestamp;
    s.saleId = totalSaleContracts;
    i.totalPurchased = Math.add(i.totalPurchased, _amountToken);
    totalPurchases[msg.sender] = Math.add(totalPurchases[msg.sender], 1);
    return true;
}

function purchaseWithEth() public payable nonReentrant returns(bool) {
    SaleInfo storage i = info[totalSaleContracts];
    require(
        i.totalPurchased <= i.allocated,
        "Sold Out"
    );
    require(
        block.timestamp < i.end,
        "Purchase Ended"
    );
    require(isWhitelisted(msg.sender), "Address not verified");
    (
        uint256 _amountToken,
        uint256 _pricePurchase,
        uint256 _usdPurchase
    ) = resolverEther(msg.value);
    Sale storage s = sale[msg.sender][Math.add(totalPurchases[msg.sender], 1)];
    s.usdPurchase = _usdPurchase;
    s.amountPurchased = _amountToken;
    s.pricePurchase = _pricePurchase;
    s.timestamp = block.timestamp;
