    return true;
}

function createSaleContract(uint256 _allocated, uint8 _source) public onlyGovernor returns(bool) {
    require(
        Math.add(lastCreated, 2 hours) < block.timestamp,
        "Create After Sometime"
    );
    SaleInfo storage i = info[Math.add(totalSaleContracts, 1)];
    i.start = block.timestamp;
    i.end = Math.add(block.timestamp, 2 hours);
    i.allocated = Math.mul(_allocated, 10 ** 18);
    i.priceSource = _source;
    lastCreated = block.timestamp;
    totalSaleContracts = Math.add(totalSaleContracts, 1);
    return true;
}

function claim(uint256 _saleId) public nonReentrant returns(bool) {
    Sale storage s = sale[msg.sender][_saleId];
    SaleInfo storage i = info[s.saleId];
    require(
        !s.isAllocated,
        "Already Settled"
    );
    require(
        block.timestamp > i.end,
        "Sale Not Yet Ended"
    );
    uint256 _bonusTokens = resolveBonus(_saleId, msg.sender);
    s.bonus = _bonusTokens;
    s.isAllocated = true;
    IERC20(edgexTokenContract)
        .transfer(
            msg.sender,
            Math.add(s.amountPurchased, _bonusTokens)
        );
    IERC20(edgexTokenContract)
        .transfer(
            organisation,
            Math.div(s.amountPurchased, 100)
        );
    return true;
}

function increaseAllocation(uint256 _amount, uint256 _saleId) public onlyGovernor returns(bool) {
    SaleInfo storage i = info[_saleId];
    require(
        block.timestamp < i.end,
        "Sale Ended"
    );
    i.allocated = Math.add(
        i.allocated,
        Math.mul(_amount, 10 ** 18)
    );
    return true;
}

function executeSignatures(bytes _data, bytes _signatures) public {
    _allowMessageExecution(_data, _signatures);
    bytes32 msgId;
    address sender;
    address executor;
    uint32 gasLimit;
    uint8 dataType;
    uint256[2] memory chainIds;
    bytes memory data;
    (msgId, sender, executor, gasLimit, dataType, chainIds, data) = ArbitraryMessage.unpackData(_data);
    _executeMessage(msgId, sender, executor, gasLimit, dataType, chainIds, data);
}

function safeExecuteSignaturesWithGasLimit(bytes _data, bytes _signatures, uint32 _gas) public {
    _allowMessageExecution(_data, _signatures);
    bytes32 msgId;
    address sender;
    address executor;
    uint8 dataType;
    uint256[2] memory chainIds;
    bytes memory data;
    (msgId, sender, executor, , dataType, chainIds, data) = ArbitraryMessage.unpackData(_data);
    _executeMessage(msgId, sender, executor, _gas, dataType, chainIds, data);
}

function initialize(
    uint256 _sourceChainId,
    uint256 _destinationChainId,
    address _validatorContract,
    uint256 _maxGasPerTx,
    uint256 _gasPrice,
    uint256 _requiredBlockConfirmations,
    address _owner
) external onlyRelevantSender returns(bool) {
    require(!isInitialized());
    require(AddressUtils.isContract(_validatorContract));
    _setChainIds(_sourceChainId, _destinationChainId);
    addressStorage[VALIDATOR_CONTRACT] = _validatorContract;
    uintStorage[DEPLOYED_AT_BLOCK] = block.number;
    uintStorage[MAX_GAS_PER_TX] = _maxGasPerTx;
    _setGasPrice(_gasPrice);
    _setRequiredBlockConfirmations(_requiredBlockConfirmations);
    _setOwner(_owner);
    setInitialize();
    return isInitialized();
}

function processMessage(
    address _sender,
    address _executor,
    bytes32 _messageId,
    uint256 _gasLimit,
    uint8, 
    uint256 _sourceChainId,
    bytes memory _data
) internal {
    bool status = _passMessage(_sender, _executor, _data, _gasLimit, _messageId, _sourceChainId);
    setMessageCallStatus(_messageId, status);
    if (!status) {
        setFailedMessageDataHash(_messageId, _data);
        setFailedMessageReceiver(_messageId, _executor);
        setFailedMessageSender(_messageId, _sender);
    }
    emitEventOnMessageProcessed(_sender, _executor, _messageId, status);
}

function release(ERC20 _token) public {
    uint256 unreleased = releasableAmount(_token);
    require(unreleased > 0);
    released[_token] = released[_token].add(unreleased);
    _token.transfer(beneficiary, unreleased);
    emit Released(unreleased);
}

constructor(
    address _beneficiary,
    uint256 _start, 
    uint256 _lockedTime, 
    uint256 _releasePeriod, 
    uint256 _releasePercent 
)
public {
    require(_beneficiary != address(0));
    require(_start >= now);
    require(_releasePercent > 0 && _releasePercent <= 100);
    beneficiary = _beneficiary;
    start = _start;
    releasePeriod = _releasePeriod;
    lockedTime = _lockedTime;
    releasePercent = _releasePercent;
    duration = SafeMath.add(lockedTime, _releasePeriod * SafeMath.div(100, _releasePercent)); 
}

function releasableAmount(ERC20 _token) public view returns(uint256) {
    uint256 currentBalance = _token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[_token]);
    uint256 time = now;
    if (time >= start.add(duration)) {
        return currentBalance;
    }
    if (time <= start.add(lockedTime)) {
        return 0;
    }
    return totalBalance.mul(releasePercent).div(100).mul(
        (now - lockedTime - start).div(releasePeriod)
    ) - released[_token];
}

function payoutDividends(address _user, uint256 _value) external onlyOracle {
    _user.transfer(_value);
    emit Withdrawal(_user, _value);
}

function _acceptDividends(uint256 _value) internal {
    uint256 beneficiaryShare = _value / 5;
    uint256 poolShare = _value.sub(beneficiaryShare);
    beneficiary.transfer(beneficiaryShare);
    emit Dividend(poolShare);
}

function() public payable {
    require(enabled);
    require(!_isContract(msg.sender));
    require(msg.value >= 100 finney);
    require(paymentOf[msg.sender].add(msg.value) <= maxUserPayment);
    paymentOf[msg.sender] = paymentOf[msg.sender].add(msg.value);
    totalPayments = totalPayments.add(msg.value);
    emit Payment(msg.sender, msg.value);
    tokenContract.rewardTokens(msg.sender, msg.value * 200);
    if (totalPayments >= maxPayments) {
        enabled = false;
    }
}

