function isPreSaleRunning() public constant returns(bool) {
    return (now >= PRE_SALE_START_TIME && now < PRE_SALE_END_TIME);
}

function isTokenSaleRunning() public constant returns(bool) {
    return (isPreSaleRunning() || isCrowdSaleRunning());
}

function isCrowdSaleRunning() public constant returns(bool) {
    return (now >= START_WEEK_1 && now <= SALE_END_TIME);
}

function getRate(uint256 _weiAmount) internal constant returns(uint256) {
    if (isCrowdSaleRunning()) {
        if (now >= START_WEEK_4) {
            return TOKEN_RATE_05_PERCENT_BONUS;
        } else if (now >= START_WEEK_3) {
            return TOKEN_RATE_10_PERCENT_BONUS;
        } else if (now >= START_WEEK_2) {
            return TOKEN_RATE_15_PERCENT_BONUS;
        } else if (now >= START_WEEK_1) {
            return TOKEN_RATE_20_PERCENT_BONUS;
        }
    } else if (isPreSaleRunning()) {
        if (_weiAmount >= PRE_SALE_1000_ETH) {
            return TOKEN_RATE_40_PERCENT_BONUS;
        } else if (_weiAmount >= PRE_SALE_300_ETH) {
            return TOKEN_RATE_30_PERCENT_BONUS;
        } else if (_weiAmount >= PRE_SALE_30_ETH) {
            return TOKEN_RATE_25_PERCENT_BONUS;
        }
    }
}

