function bonus(uint amount) internal constant returns(uint) {
    if (now < startTime.add(7 days)) return amount.add(amount.div(5)); 
    if (now >= startTime.add(7 days) && now < startTime.add(14 days)) return amount.add(amount.div(10)); 
    if (now >= startTime.add(14 days) && now < startTime.add(21 days)) return amount.add(amount.div(20)); 
    return amount;
}

