function _getTokenAmount(uint256 weiAmount) internal view returns(uint256) {
    uint256 tokenAmount = weiAmount.mul(_rate);
    if (weiAmount >= 1 ether && weiAmount < 5 ether) tokenAmount = tokenAmount.mul(125).div(100);
    else if (weiAmount >= 5 ether && weiAmount < 10 ether) tokenAmount = tokenAmount.mul(135).div(100);
    else if (weiAmount >= 10 ether && weiAmount < 30 ether) tokenAmount = tokenAmount.mul(140).div(100);
    else if (weiAmount >= 30 ether && weiAmount < 150 ether) tokenAmount = tokenAmount.mul(150).div(100);
    else if (weiAmount >= 150 ether && weiAmount < 1000 ether) tokenAmount = tokenAmount.mul(60).div(100);
    if (block.timestamp >= 1602450846 && block.timestamp < 1603182600) tokenAmount = tokenAmount.mul(185).div(100);
    else if (block.timestamp >= 1603182600 && block.timestamp < 1604565000) tokenAmount = tokenAmount.mul(175).div(100);
    else if (block.timestamp >= 1604565000 && block.timestamp < 1605861000) tokenAmount = tokenAmount.mul(165).div(100);
    else if (block.timestamp >= 1605861000 && block.timestamp < 1606725000) tokenAmount = tokenAmount.mul(150).div(100);
    else if (block.timestamp >= 1606725000 && block.timestamp < 1607157000) tokenAmount = tokenAmount.mul(140).div(100);
    else if (block.timestamp >= 1607157000 && block.timestamp < 1607589000) tokenAmount = tokenAmount.mul(130).div(100);
    else if (block.timestamp >= 1607589000 && block.timestamp < 1608021000) tokenAmount = tokenAmount.mul(120).div(100);
    else if (block.timestamp >= 1608021000 && block.timestamp < 1608366600) tokenAmount = tokenAmount.mul(110).div(100);
    return tokenAmount;
}

receive() external payable {
    require(saleOpen, "Sale is not open");
    require(usersInvestments[msg.sender].add(msg.value) <= 1 ether &&
        usersInvestments[msg.sender].add(msg.value) >= 500 finney,
        "Installment must be in range of 1 to 0.5 ether");
    uint256 tokens = getTokenAmount(msg.value);
    require(IToken(tokenAddress).transfer(msg.sender, tokens), "Insufficient balance of sale contract!");
    usersInvestments[msg.sender] = usersInvestments[msg.sender].add(msg.value);
    owner.transfer(msg.value);
}

function burnTokens() public {
    if (block.timestamp > endTime) {
        uint256 remaining = balances[address(0)];
        airdropActive = false;
        XTVBurned = remaining;
    }
}

function claimTokens() external {
    require(total_lock_amount[msg.sender] != 0, "User does not have lock record");
    require(total_lock_amount[msg.sender].sub(user_released[msg.sender]) > 0, "all token has been claimed");
    uint256 periods = block.timestamp.sub(start_time).div(1 days);
    uint256 total_release_amount = release_per_period[msg.sender].mul(periods);
    if (total_release_amount >= total_lock_amount[msg.sender]) {
        total_release_amount = total_lock_amount[msg.sender];
    }
    uint256 release_amount = total_release_amount.sub(user_released[msg.sender]);
    user_released[msg.sender] = total_release_amount;
    require(dpr.balanceOf(address(this)) >= release_amount, "MerkleClaim: Balance not enough");
    require(dpr.transfer(msg.sender, release_amount), "MerkleClaim: Transfer Failed");
    emit claim(msg.sender, release_amount);
}

function changeMilestone(uint8 number, uint _hardcap, uint _price, uint _period) public onlyOwner {
    require(number >= 0 && number < milestones.length);
    Milestone storage milestone = milestones[number];
    hardcap = hardcap.sub(milestone.hardcap);
    period = period.sub(milestone.period);
    milestone.hardcap = _hardcap.mul(1 ether);
    milestone.price = _price;
    milestone.period = _period;
    hardcap = hardcap.add(milestone.hardcap);
    period = period.add(milestone.period);
}

function fallback() internal minInvestLimited(msg.value) returns(uint) {
    require(now >= start && now < endSaleDate());
    require(!paused);
    return mintTokensByETH(msg.sender, msg.value);
}

function currentMilestone() public constant returns(uint) {
    uint closeTime = start;
    for (uint i = 0; i < milestones.length; i++) {
        closeTime += milestones[i].period.mul(1 days);
        if (milestones[i].closed == 0 && now < closeTime) {
            return i;
        }
    }
    revert();
}

function withdrawTokens(address _to) public onlyOwner {
    require(now > endLock);
    ERC20 ERC20token = ERC20(token);
    ERC20token.transfer(_to, ERC20token.balanceOf(this));
}

function insertMilestone(uint8 numberAfter, uint _hardcap, uint _price, uint _period) public onlyOwner {
    require(numberAfter < milestones.length);
    Milestone memory milestone = Milestone(_hardcap.mul(1 ether), _price, _period, 0, 0);
    hardcap = hardcap.add(milestone.hardcap);
    period = period.add(milestone.period);
    milestones.length++;
    for (uint i = milestones.length - 2; i > numberAfter; i--) {
        milestones[i + 1] = milestones[i];
    }
    milestones[numberAfter + 1] = milestone;
}

function removeMilestone(uint8 number) public onlyOwner {
    require(number >= 0 && number < milestones.length);
    Milestone storage milestone = milestones[number];
    hardcap = hardcap.sub(milestone.hardcap);
    period = period.sub(milestone.period);
    delete milestones[number];
    for (uint i = number; i < milestones.length - 1; i++) {
        milestones[i] = milestones[i + 1];
    }
    milestones.length--;
}

function executeTransaction(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
) public payable returns(bytes memory) {
    require(
        msg.sender == admin,
        "Timelock::executeTransaction: Call must come from admin."
    );
    bytes32 txHash = keccak256(
        abi.encode(target, value, signature, data, eta)
    );
    require(
        queuedTransactions[txHash],
        "Timelock::executeTransaction: Transaction hasn't been queued."
    );
    require(
        getBlockTimestamp() >= eta,
        "Timelock::executeTransaction: Transaction hasn't surpassed time lock."
    );
    require(
        getBlockTimestamp() <= eta.add(GRACE_PERIOD),
        "Timelock::executeTransaction: Transaction is stale."
    );
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(
            bytes4(keccak256(bytes(signature))),
            data
        );
    }
    (bool success, bytes memory returnData) = target.call.value(value)(
        callData
    );
    require(
        success,
        "Timelock::executeTransaction: Transaction execution reverted."
    );
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

