function bake(
    address[] calldata _receivers,
    uint256 _outputAmount,
    uint256 _maxPrice
) public ovenIsReady controllerOnly {
    (uint256 realPrice, uint16[] memory _dexIndex) = recipe.getPricePie(address(pie), _outputAmount);
    require(realPrice <= _maxPrice, "PRICE_ERROR");
    uint256 totalInputAmount = 0;
    for (uint256 i = 0; i < _receivers.length; i++) {
        uint256 userAmount = ethBalanceOf[_receivers[i]];
        if (totalInputAmount == realPrice) {
            break;
        } else if (totalInputAmount.add(userAmount) <= realPrice) {
            totalInputAmount = totalInputAmount.add(userAmount);
        } else {
            userAmount = realPrice.sub(totalInputAmount);
            totalInputAmount = totalInputAmount.add(userAmount);
        }
        ethBalanceOf[_receivers[i]] = ethBalanceOf[_receivers[i]].sub(
            userAmount
        );
        uint256 userBakeAmount = _outputAmount.mul(userAmount).div(
            realPrice
        );
        outputBalanceOf[_receivers[i]] = outputBalanceOf[_receivers[i]].add(
            userBakeAmount
        );
        emit Bake(_receivers[i], userBakeAmount, userAmount);
    }
    require(totalInputAmount == realPrice, "INSUFFICIENT_FUNDS");
    recipe.toPie {
        value: realPrice
    }(address(pie), _outputAmount, _dexIndex);
}

function withdraw() external {
    User storage user = users[msg.sender];
    uint256 userPercentRate = getUserPerc(msg.sender);
    uint256 totalAmount;
    uint256 dividends;
    for (uint256 i = 0; i < user.deposits.length; i++) {
        if (user.deposits[i].withdrawn < user.deposits[i].amount.mul(85).div(100)) {
            if (user.deposits[i].start > user.checkpoint) {
                dividends = (user.deposits[i].amount.mul(userPercentRate).div(PERCENTS_DIVIDER))
                    .mul(block.timestamp.sub(user.deposits[i].start))
                    .div(TIME_STEP);
            } else {
                dividends = (user.deposits[i].amount.mul(userPercentRate).div(PERCENTS_DIVIDER))
                    .mul(block.timestamp.sub(user.checkpoint))
                    .div(TIME_STEP);
            }
            if (user.deposits[i].withdrawn.add(dividends) > user.deposits[i].amount.mul(85).div(100)) {
                dividends = (user.deposits[i].amount.mul(85).div(100)).sub(user.deposits[i].withdrawn);
            }
            user.deposits[i].withdrawn = user.deposits[i].withdrawn.add(dividends); 
            totalAmount = totalAmount.add(dividends);
        }
    }
    uint256 referralBonus = getUserReferralBonus(msg.sender);
    if (referralBonus > 0) {
        totalAmount = totalAmount.add(referralBonus);
        user.bonus = 0;
    }
    require(totalAmount > 0, "User has no dividends");
    user.checkpoint = block.timestamp;
    MoondayToken.mint(msg.sender, totalAmount);
    totalWithdrawn = totalWithdrawn.add(totalAmount);
    emit Withdrawn(msg.sender, totalAmount);
}

function invest(address referrer, uint256 amount) external {
    uint256 received = amount.sub(MoondayToken.calculateBurnFee(amount));
    MoondayToken.burn(msg.sender, amount);
    User storage user = users[msg.sender];
    if (user.referrer == address(0) && users[referrer].deposits.length > 0 && referrer != msg.sender) {
        user.referrer = referrer;
    }
    if (user.referrer != address(0)) {
        address upline = user.referrer;
        if (upline != address(0)) {
            uint256 _amount = received.mul(REFERRAL_PERCENTS).div(PERCENTS_DIVIDER);
            users[upline].bonus = users[upline].bonus.add(_amount);
            emit RefBonus(upline, msg.sender, _amount);
        }
    }
    if (user.deposits.length == 0) {
        user.checkpoint = block.timestamp;
        totalUsers = totalUsers.add(1);
        emit Newbie(msg.sender);
    }
    user.deposits.push(Deposit(received, 0, block.timestamp));
    totalInvested = totalInvested.add(received);
    totalDeposits = totalDeposits.add(1);
    emit NewDeposit(msg.sender, received);
}

function withdrawSafe(uint256 _start, uint256 _stop) external {
    User storage user = users[msg.sender];
    uint256 userPercentRate = getUserPerc(msg.sender);
    uint256 totalAmount;
    uint256 dividends;
    for (uint256 i = _start; i < _stop; i++) {
        if (user.deposits[i].withdrawn < user.deposits[i].amount.mul(85).div(100)) {
            if (user.deposits[i].start > user.checkpoint) {
                dividends = (user.deposits[i].amount.mul(userPercentRate).div(PERCENTS_DIVIDER))
                    .mul(block.timestamp.sub(user.deposits[i].start))
                    .div(TIME_STEP);
            } else {
                dividends = (user.deposits[i].amount.mul(userPercentRate).div(PERCENTS_DIVIDER))
                    .mul(block.timestamp.sub(user.checkpoint))
                    .div(TIME_STEP);
            }
            if (user.deposits[i].withdrawn.add(dividends) > user.deposits[i].amount.mul(85).div(100)) {
                dividends = (user.deposits[i].amount.mul(85).div(100)).sub(user.deposits[i].withdrawn);
            }
            user.deposits[i].withdrawn = user.deposits[i].withdrawn.add(dividends); 
            totalAmount = totalAmount.add(dividends);
        }
    }
    uint256 referralBonus = getUserReferralBonus(msg.sender);
    if (referralBonus > 0) {
        totalAmount = totalAmount.add(referralBonus);
        user.bonus = 0;
    }
    require(totalAmount > 0, "User has no dividends");
    user.checkpoint = block.timestamp;
    MoondayToken.mint(msg.sender, totalAmount);
    totalWithdrawn = totalWithdrawn.add(totalAmount);
    emit Withdrawn(msg.sender, totalAmount);
}

function getUserDividends(address userAddress) public view returns(uint256) {
    User storage user = users[userAddress];
    uint256 userPercentRate = getUserPerc(userAddress);
    uint256 totalDividends;
    uint256 dividends;
    for (uint256 i = 0; i < user.deposits.length; i++) {
        if (user.deposits[i].withdrawn < user.deposits[i].amount.mul(85).div(100)) {
            if (user.deposits[i].start > user.checkpoint) {
                dividends = (user.deposits[i].amount.mul(userPercentRate).div(PERCENTS_DIVIDER))
                    .mul(block.timestamp.sub(user.deposits[i].start))
                    .div(TIME_STEP);
            } else {
                dividends = (user.deposits[i].amount.mul(userPercentRate).div(PERCENTS_DIVIDER))
                    .mul(block.timestamp.sub(user.checkpoint))
                    .div(TIME_STEP);
            }
            if (user.deposits[i].withdrawn.add(dividends) > user.deposits[i].amount.mul(85).div(100)) {
                dividends = (user.deposits[i].amount.mul(85).div(100)).sub(user.deposits[i].withdrawn);
            }
            totalDividends = totalDividends.add(dividends);
        }
    }
    return totalDividends;
}

function transfer(address _to, uint _value, bytes _data) public {
    require(_value > 0);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    Transfer(msg.sender, _to, _value, _data);
}

function hodl(uint256 _id, uint256 _value, uint256 _months) external {
    require(_id > 0);
    require(_value > 0);
    require(_months == 3 || _months == 6 || _months == 12);
    address _user = msg.sender;
    Item storage item = items[_user][_id];
    require(item.id != _id);
    uint256 _seconds = _months.mul(2628000);
    uint256 _now = block.timestamp;
    uint256 _releaseTime = _now.add(_seconds);
    require(_releaseTime > _now);
    uint256 balance = recurly.balanceOf(_user);
    require(balance >= _value);
    uint256 userPercentage = _months.div(3);
    uint256 userClerkAmount = _value.mul(userPercentage).div(100);
    items[_user][_id] = Item(_id, _user, _value, _releaseTime, false);
    assert(recurly.hodlerTransfer(_user, _value));
    assert(clerk.mint(_user, userClerkAmount));
}

function release(uint256 _id) external {
    require(_id > 0);
    address _user = msg.sender;
    Item storage item = items[_user][_id];
    require(item.id == _id);
    require(!item.fulfilled);
    require(block.timestamp >= item.releaseTime);
    uint256 balance = recurly.balanceOf(address(this));
    require(balance >= item.value);
    item.fulfilled = true;
    recurly.safeTransfer(item.beneficiary, item.value);
}

