function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if ((contract_deployed + 30 days) < block.timestamp) {
        __liquidityFee = 0;
        __prev_liquidityFee = 0;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (
        overMinTokenBalance &&
        !inSwapAndLiquify &&
        from != uniswapV2Pair &&
        swapAndLiquifyEnabled
    ) {
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    bool isTransferBuy = from == uniswapV2Pair;
    bool isTransferSell = to == uniswapV2Pair;
    if (!isTransferBuy && !isTransferSell) takeFee = false;
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee();
}

function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint256 liquidityPart = 0;
    if (_pendingLiquidityFees < contractTokenBalance) liquidityPart = _pendingLiquidityFees;
    uint256 distributionPart = contractTokenBalance.sub(liquidityPart);
    uint256 liquidityHalfPart = liquidityPart.div(2);
    uint256 liquidityHalfTokenPart = liquidityPart.sub(liquidityHalfPart);
    uint256 totalETHSwap = liquidityHalfPart.add(distributionPart);
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(totalETHSwap);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    uint256 liquidityBalance = liquidityHalfPart.mul(newBalance).div(totalETHSwap);
    if (liquidityHalfTokenPart > 0 && liquidityBalance > 0) addLiquidity(liquidityHalfTokenPart, liquidityBalance);
    emit SwapAndLiquify(liquidityHalfPart, liquidityBalance, liquidityHalfPart);
    newBalance = address(this).balance;
    payDistribution(newBalance);
    _pendingLiquidityFees = 0;
}

function processSeason(uint32 _season) public onlyCOO {
    uint64 fightTime = matchTime[_season];
    require(now >= fightTime && fightTime > 0);
    uint sumFund = 0;
    uint sumSeed = 0;
    (sumFund, sumSeed) = _getFightData(_season);
    if (sumFund == 0) {
        finished[_season] = 110;
        doLogFighter(_season, 0, 0);
        emit SeasonNone(_season);
        emit LogMatch(_season, sumFund, fightTime, sumSeed, 0, 0, 0, false);
    } else {
        uint8 champion = _localFight(_season, uint32(sumSeed));
        uint percentile = safeDiv(sumFund, 100);
        uint devCut = percentile * 4; 
        uint partnerCut = percentile * 5; 
        uint fighterCut = percentile * 1; 
        uint bonusWinner = percentile * 80; 
        _bonusToPartners(partnerCut);
        _bonusToFighters(_season, champion, fighterCut);
        bool isRefound = _bonusToBettor(_season, champion, bonusWinner);
        _addMoney(cfoAddress, devCut);
        uint key = _season * 1000 + champion;
        Fighter storage soldier = soldiers[key];
        doLogFighter(_season, key, fighterCut);
        emit SeasonWinner(_season, champion);
        emit LogMatch(_season, sumFund, fightTime, sumSeed, key, soldier.hometown, soldier.tokenID, isRefound);
    }
    clearTheSeason(_season);
}

function betOn(
    uint32 _season,
    uint32 _index,
    uint _seed,
    address _invitor)
payable external returns(bool) {
    require(isNormalUser(msg.sender));
    require(matchTime[_season] > 0);
    require(now < matchTime[_season] - 300); 
    require(msg.value >= 1 finney && msg.value < 99999 ether);
    Betting memory tmp = Betting({
        account: msg.sender,
        season: _season,
        index: _index,
        seed: _seed,
        invitor: _invitor,
        amount: msg.value
    });
    uint key = _season * 1000 + _index;
    betOnFighter[key] = safeAdd(betOnFighter[key], msg.value);
    Betting[] storage items = allBittings[key];
    items.push(tmp);
    Fighter storage soldier = soldiers[key];
    emit Betted(_season, _index, msg.sender, msg.value);
    emit LogBet(_season, msg.sender, msg.value, _seed, key, soldier.hometown, soldier.tokenID);
}

function buyTokens(address beneficiary) nonZeroEth tokenIsDeployed onlyPublic nonZeroAddress(beneficiary) payable returns(bool) {
    if (auth[beneficiary] < msg.value) {
        revert();
    }
    auth[beneficiary] = auth[beneficiary].sub(msg.value);
    if (getState() == State.PreSale) {
        if (buyPreSaleTokens(beneficiary)) {
            return true;
        }
        revert();
    } else {
        require(now < crowdfundEndTime && isCrowdFundActive);
        fundTransfer(msg.value);
        uint256 amount = getNoOfTokens(exchangeRate, msg.value);
        if (token.transfer(beneficiary, amount)) {
            token.changeTotalSupply(amount);
            totalWeiRaised = totalWeiRaised.add(msg.value);
            TokenPurchase(beneficiary, msg.value, amount);
            return true;
        }
        revert();
    }
}

