function depositTokens(address from, address token, uint256 tokens) public returns(bool success) {
    ERC20Interface(token).transferFrom(from, this, tokens);
    balances[token][from] = balances[token][from].add(tokens);
    Deposit(token, from, tokens, balances[token][from]);
    return true;
}

function placeBet(uint8 start, uint8 end) public payable returns(bool) {
    if (msg.value < minBetAmount) {
        return false;
    }
    if (msg.value > maxBetAmount) {
        return false;
    }
    uint8 counter = end - start + 1;
    if (counter > 7) {
        return false;
    }
    if (counter < 1) {
        return false;
    }
    uint gameId = games.length;
    games.length++;
    numberOfGames++;
    GameRoll(msg.sender, gameId, start, end, msg.value);
    games[gameId].id = gameId;
    games[gameId].player = msg.sender;
    games[gameId].amount = msg.value;
    games[gameId].start = start;
    games[gameId].end = end;
    games[gameId].hash = getBlockHash(pointer);
    games[gameId].number = getNumber(games[gameId].hash);
    pointer = games[gameId].number;
    if ((games[gameId].number >= start) && (games[gameId].number <= end)) {
        games[gameId].win = true;
        uint dec = msg.value / 10;
        uint parts = 10 - counter;
        games[gameId].prize = msg.value + dec * parts;
    } else {
        games[gameId].prize = 1;
    }
    msg.sender.transfer(games[gameId].prize);
    notify(
        msg.sender,
        gameId,
        start,
        end,
        games[gameId].number,
        msg.value,
        games[gameId].prize,
        games[gameId].win
    );
    return true;
}

function() external payable {
    if (invested[msg.sender] != 0 && block.number > atBlock[msg.sender]) {
        uint256 amount = invested[msg.sender] * 5 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        if (amount > this.balance) amount = this.balance;
        msg.sender.transfer(amount);
    } else {
        investors.push(msg.sender);
    }
    invested[msg.sender] += msg.value;
    atBlock[msg.sender] = block.number
        * investorsCount++;
}

