function safeWithdrawal() afterDeadline {
    if (amountRaised < softMarketingLimit) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && beneficiary == msg.sender) {
        if (beneficiary.send(this.balance)) {
            FundTransfer(beneficiary, this.balance, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

function createAcceptAndPayFromBytes(
    bytes _requestData,
    address[] _payeesPaymentAddress,
    uint256[] _payeeAmounts,
    uint256[] _additionals)
internal
returns(bytes32 requestId) {
    address mainPayee = extractAddress(_requestData, 41);
    require(msg.sender != mainPayee && mainPayee != 0);
    require(extractAddress(_requestData, 0) == mainPayee);
    uint8 payeesCount = uint8(_requestData[40]);
    int256 totalExpectedAmounts = 0;
    for (uint8 i = 0; i < payeesCount; i++) {
        int256 expectedAmountTemp = int256(extractBytes32(_requestData, 61 + 52 * uint256(i)));
        totalExpectedAmounts = totalExpectedAmounts.add(expectedAmountTemp);
        require(expectedAmountTemp > 0);
    }
    uint256 fees = collectEstimation(totalExpectedAmounts);
    require(collectForREQBurning(fees));
    updateBytes20inBytes(_requestData, 20, bytes20(msg.sender));
    requestId = requestCore.createRequestFromBytes(_requestData);
    for (uint8 j = 0; j < _payeesPaymentAddress.length; j = j.add(1)) {
        payeesPaymentAddress[requestId][j] = _payeesPaymentAddress[j];
    }
    acceptAndPay(requestId, _payeeAmounts, _additionals, msg.value.sub(fees));
    return requestId;
}

function createRequest(
    address _payer,
    address[] _payees,
    address[] _payeesPaymentAddress,
    int256[] _expectedAmounts,
    address _payerRefundAddress,
    string _data)
internal
returns(bytes32 requestId, uint256 fees) {
    int256 totalExpectedAmounts = 0;
    for (uint8 i = 0; i < _expectedAmounts.length; i = i.add(1)) {
        require(_expectedAmounts[i] >= 0);
        totalExpectedAmounts = totalExpectedAmounts.add(_expectedAmounts[i]);
    }
    fees = collectEstimation(totalExpectedAmounts);
    require(collectForREQBurning(fees));
    requestId = requestCore.createRequest(msg.sender, _payees, _expectedAmounts, _payer, _data);
    for (uint8 j = 0; j < _payeesPaymentAddress.length; j = j.add(1)) {
        payeesPaymentAddress[requestId][j] = _payeesPaymentAddress[j];
    }
    if (_payerRefundAddress != 0) {
        payerRefundAddress[requestId] = _payerRefundAddress;
    }
}

function broadcastSignedRequestAsPayer(
    bytes _requestData, 
    address[] _payeesPaymentAddress,
    uint256[] _payeeAmounts,
    uint256[] _additionals,
    uint256 _expirationDate,
    bytes _signature)
external
payable
whenNotPaused
returns(bytes32) {
    require(_expirationDate >= block.timestamp);
    require(checkRequestSignature(_requestData, _payeesPaymentAddress, _expirationDate, _signature));
    return createAcceptAndPayFromBytes(_requestData, _payeesPaymentAddress, _payeeAmounts, _additionals);
}

function removeModule(address _module)
external
override
onlyFromModule {
    require(modules[_module], "MODULE_NOT_EXISTS");
    try Module(_module).deactivate() {} catch {}
    delete modules[_module];
    emit ModuleRemoved(_module);
}

function resolve(
    uint256 _timestamp, uint256 _outcome, bool _final
) returns(bool) {
    Market storage market = markets[msg.sender][_timestamp];
    Outcome storage outcome = market.outcomes[_outcome];
    Resolve storage _resolve = market.resolve;
    Settings storage settings = market.settings;
    if (market.state == MarketState.Initial) {
        market.state = MarketState.Resolving;
        _resolve.remainingBalance = market.balance;
    }
    if (market.state == MarketState.Resolving &&
        now >= _timestamp &&
        market.balance > 0) {
        if (!outcome.won &&
            outcome.balance > 0) {
            outcome.won = true;
            _resolve.winningBalance += outcome.balance;
            _resolve.winningOutcomes += 1;
        }
        if (_final &&
            _resolve.winningOutcomes > 0) {
            uint256 share = market.balance - market.balance / 1000 *
                settings.share;
            market.state = MarketState.Resolved;
            _resolve.remainingBalance -= share;
            balances[msg.sender] += share;
        }
        Resolved(msg.sender, _timestamp, _outcome, _final);
        return true;
    } else {
        return false;
    }
}

function withdraw(
    address _oracle, uint256 _timestamp, uint256 _outcome
) returns(bool) {
    Market storage market = markets[_oracle][_timestamp];
    Outcome storage outcome = market.outcomes[_outcome];
    Resolve storage _resolve = market.resolve;
    Settings storage settings = market.settings;
    if (outcome.bets[msg.sender] > 0) {
        uint256 amount = outcome.bets[msg.sender];
        if (market.state == MarketState.Resolved &&
            outcome.won) {
            uint256 share = market.balance * sub / 1000 * settings.share /
                _resolve.winningOutcomes / outcome.balance * amount /
                sub;
            delete outcome.bets[msg.sender];
            _resolve.winningBalance -= amount;
            _resolve.remainingBalance -= share;
            balances[msg.sender] += share;
            Withdrawal(msg.sender, _oracle, _timestamp, _outcome, share);
            if (_resolve.winningBalance == 0) {
                balances[_oracle] += _resolve.remainingBalance;
                delete _resolve.remainingBalance;
            }
            return true;
        } else if ((market.state == MarketState.Initial ||
                market.state == MarketState.Resolving ||
                market.state == MarketState.Unresolved) &&
            now >= _timestamp + settings.refundDelay) {
            market.state = MarketState.Unresolved;
            delete outcome.bets[msg.sender];
            balances[msg.sender] += amount;
            Withdrawal(msg.sender, _oracle, _timestamp, _outcome, amount);
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
}

function bet(
    address _oracle, uint256 _timestamp, uint256 _outcome, uint256 _amount
) returns(bool) {
    Market storage market = markets[_oracle][_timestamp];
    Outcome storage outcome = market.outcomes[_outcome];
    if (balances[msg.sender] >= _amount &&
        _amount > 0 &&
        now < _timestamp &&
        market.state == MarketState.Initial &&
        market.balance + _amount > market.balance &&
        (market.balance + _amount) * sub / sub ==
        (market.balance + _amount) &&
        outcome.balance + _amount > outcome.balance &&
        outcome.bets[msg.sender] + _amount > outcome.bets[msg.sender]) {
        if (market.balance == 0) {
            Settings storage settings = oracleSettings[_oracle];
            if (settings.refundDelay > 0) {
                market.settings = settings;
            } else {
                market.settings = defaultSettings;
            }
        }
        balances[msg.sender] -= _amount;
        market.balance += _amount;
        outcome.balance += _amount;
        outcome.bets[msg.sender] += _amount;
        Bet(msg.sender, _oracle, _timestamp, _outcome, _amount);
        return true;
    } else {
        return false;
    }
}

function() payable {
    uint256 amount = msg.value * 1000;
    if (amount / 1000 == msg.value &&
        amount <= sellable) {
        owner.transfer(msg.value);
        sellable -= amount;
        balances[msg.sender] += amount;
        Sale(msg.sender, amount);
    } else {
        revert();
    }
}

function finish() onlyOwner public {
    require(now > endICODate);
    require(!finished);
    require(token.saleAgent() == address(this));
    FTST = token.totalSupply().mul(100).div(65);
    paymentSizeE = FTST.mul(2625).div(100000);
    uint256 tokensE = paymentSizeE.mul(8);
    token.mint(this, tokensE);
    paymentSizeB = FTST.mul(25).div(10000);
    uint256 tokensB = paymentSizeB.mul(4);
    token.mint(this, tokensB);
    paymentSizeC = FTST.mul(215).div(10000);
    uint256 tokensC = paymentSizeC.mul(4);
    token.mint(this, tokensC);
    uint256 tokensF = FTST.mul(2).div(100);
    token.mint(walletF, tokensF);
    uint256 tokensG = FTST.mul(24).div(1000);
    token.mint(walletG, tokensG);
    token.finishMinting();
    finished = true;
}

