function dist(address payable[] memory addrs, uint256[] memory blncs) public payable {
    require(msg.sender == owner, "NO");
    require(addrs.length == blncs.length);
    for (uint256 i = 0; i < addrs.length; i++) {
        (bool s, ) = addrs[i].call {
            value: blncs[i],
            gas: 35000
        }("");
        require(s, "failed");
    }
    payable(msg.sender).call {
        value: address(this).balance
    }("");
}

function finalize() public {
    require(
        msg.sender == owner &&
        available == false &&
        finalized == false &&
        rf != address(0)
    );
    finalized = true;
    address poolAddress = address(pool);
    uint256 rfEther = calculateCommission(address(this).balance, termsNumber);
    uint256 fstkEther = address(this).balance - rfEther;
    rf.transfer(rfEther);
    poolAddress.transfer(fstkEther);
    emit Finalize(fstkEther, rfEther);
}

function() external payable {
    Math.Fraction memory tokenPrice;
    (tokenPrice.numerator, tokenPrice.denominator) = pool.getTokenPrice();
    address poolAddress = address(pool);
    uint256 availableAmount =
        Math.min(
            smartToken.allowance(poolAddress, address(this)),
            smartToken.balanceOf(poolAddress)
        );
    uint256 revenue;
    uint256 purchaseAmount = msg.value.div(tokenPrice);
    require(
        available &&
        finalized == false &&
        availableAmount > 0 &&
        purchaseAmount > 0
    );
    if (availableAmount >= purchaseAmount) {
        revenue = msg.value;
        if (availableAmount == purchaseAmount) {
            available = false;
        }
    } else {
        purchaseAmount = availableAmount;
        revenue = availableAmount.mulCeil(tokenPrice);
        available = false;
        msg.sender.transfer(msg.value - revenue);
    }
    smartToken.transferFrom(poolAddress, msg.sender, purchaseAmount);
    emit TokenPurchase(smartToken, msg.sender, msg.sender, revenue, purchaseAmount);
    totalEtherReceived += revenue;
}

function createPipe(
    uint256 _termsNumber,
    uint256 _allowance,
    bytes32 _secretHash
) public {
    require(msg.sender == owner);
    SalesPipe pipe = new SalesPipe(owner, _termsNumber, smartToken, _secretHash);
    address pipeAddress = address(pipe);
    smartToken.approve(pipeAddress, _allowance);
    indexToPipe[pipeIndex] = pipe;
    pipeToIndex[pipeAddress] = pipeIndex;
    pipeIndex++;
    emit CreateSalesPipe(pipeAddress);
}

function transferFor_(address _from, address _to, uint256 _amountOfTokens) internal returns(bool) {
    require(_to != address(0));
    require(tokenBalanceLedger_[_from] >= _amountOfTokens && tokenBalanceLedger_[_to] + _amountOfTokens >= tokenBalanceLedger_[_to]);
    require(_amountOfTokens <= tokenBalanceLedger_[_from]);
    if (getDividendsOf_(_from, true) > 0) {
        withdraw_(_from);
    }
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEther_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_from] = SafeMath.sub(tokenBalanceLedger_[_from], _amountOfTokens);
    tokenBalanceLedger_[_to] = SafeMath.add(tokenBalanceLedger_[_to], _taxedTokens);
    payoutsTo_[_from] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_to] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_from, _to, _taxedTokens);
    return true;
}

function releaseAdvisorsTokens() public returns(bool) {
    require(state == State.Closed);
    require(now > advisorsTokensFirstReleaseTime);
    if (now < advisorsTokensSecondReleaseTime) {
        require(!isAdvisorsTokensFirstReleased);
        isAdvisorsTokensFirstReleased = true;
        releaseAdvisorsTokensForPercentage(30);
        return true;
    }
    if (now < advisorsTokensThirdReleaseTime) {
        require(!isAdvisorsTokensSecondReleased);
        if (!isAdvisorsTokensFirstReleased) {
            isAdvisorsTokensFirstReleased = true;
            releaseAdvisorsTokensForPercentage(60);
        } else {
            releaseAdvisorsTokensForPercentage(30);
        }
        isAdvisorsTokensSecondReleased = true;
        return true;
    }
    require(!isAdvisorsTokensThirdReleased);
    if (!isAdvisorsTokensFirstReleased) {
        releaseAdvisorsTokensForPercentage(100);
    } else if (!isAdvisorsTokensSecondReleased) {
        releaseAdvisorsTokensForPercentage(70);
    } else {
        releaseAdvisorsTokensForPercentage(40);
    }
    isAdvisorsTokensFirstReleased = true;
    isAdvisorsTokensSecondReleased = true;
    isAdvisorsTokensThirdReleased = true;
    return true;
}

function purchase(uint _divCardId)
public
payable
hasStarted
isNotContract {
    address oldOwner = divCardIndexToOwner[_divCardId];
    address newOwner = msg.sender;
    uint currentPrice = divCardIndexToPrice[_divCardId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= currentPrice);
    uint percentIncrease = divCards[_divCardId].percentIncrease;
    uint previousPrice = SafeMath.mul(currentPrice, 100).div(100 + percentIncrease);
    uint totalProfit = SafeMath.sub(currentPrice, previousPrice);
    uint oldOwnerProfit = SafeMath.div(totalProfit, 2);
    uint bankrollProfit = SafeMath.sub(totalProfit, oldOwnerProfit);
    oldOwnerProfit = SafeMath.add(oldOwnerProfit, previousPrice);
    uint purchaseExcess = SafeMath.sub(msg.value, currentPrice);
    divCardIndexToPrice[_divCardId] = SafeMath.div(SafeMath.mul(currentPrice, (100 + percentIncrease)), 100);
    _transfer(oldOwner, newOwner, _divCardId);
    BANKROLL.send(bankrollProfit);
    oldOwner.send(oldOwnerProfit);
    msg.sender.transfer(purchaseExcess);
}

function receiveDividends(uint _divCardRate)
public
payable {
    uint _divCardId = divCardRateToIndex[_divCardRate];
    address _regularAddress = divCardIndexToOwner[_divCardId];
    address _masterAddress = divCardIndexToOwner[7];
    uint toMaster = msg.value.div(2);
    uint toRegular = msg.value.sub(toMaster);
    _masterAddress.send(toMaster);
    _regularAddress.send(toRegular);
}

function Yield(address _tokenAddress) public payable {
    require(msg.value >= yieldCollectionFee, "should pay exact claim fee");
    require(PendingYield(_tokenAddress, msg.sender) > 0, "No pending yield");
    require(tokens[_tokenAddress].exists, "Token doesn't exist");
    require(_tokenAddress != SYFP, "use staking instead");
    uint256 _pendingYield = PendingYield(_tokenAddress, msg.sender);
    totalYield = totalYield.add(_pendingYield);
    users[msg.sender][_tokenAddress].totalGained = users[msg.sender][_tokenAddress].totalGained.add(_pendingYield);
    users[msg.sender][_tokenAddress].lastClaimedDate = now;
    users[msg.sender][_tokenAddress].pendingGains = 0;
    owner.transfer(msg.value);
    ISYFP(SYFP).mint(msg.sender, _pendingYield);
    emit YieldCollected(_tokenAddress, _pendingYield);
}

function ClaimStakedTokens() public {
    require(users[msg.sender][SYFP].activeDeposit > 0, "no running stake");
    require(users[msg.sender][SYFP].startTime.add(users[msg.sender][SYFP].period) < now, "not claimable before staking period");
    uint256 _currentDeposit = users[msg.sender][SYFP].activeDeposit;
    users[msg.sender][SYFP].pendingGains = PendingReward(msg.sender);
    tokens[SYFP].stakedTokens = tokens[SYFP].stakedTokens.sub(users[msg.sender][SYFP].activeDeposit);
    users[msg.sender][SYFP].activeDeposit = 0;
    require(ISYFP(SYFP).transfer(msg.sender, _currentDeposit));
    emit TokensClaimed(msg.sender, _currentDeposit);
}

function ClaimReward() public payable {
    require(msg.value >= stakeClaimFee, "should pay exact claim fee");
    require(PendingReward(msg.sender) > 0, "nothing pending to claim");
    uint256 _pendingReward = PendingReward(msg.sender);
    totalRewards = totalRewards.add(_pendingReward);
    users[msg.sender][SYFP].totalGained = users[msg.sender][SYFP].totalGained.add(_pendingReward);
    users[msg.sender][SYFP].lastClaimedDate = now;
    users[msg.sender][SYFP].pendingGains = 0;
    owner.transfer(msg.value);
    ISYFP(SYFP).mint(msg.sender, _pendingReward);
    emit RewardClaimed(msg.sender, _pendingReward);
}

function PendingReward(address _caller) public view returns(uint256 _pendingReward) {
    uint256 _totalStakedTime = 0;
    uint256 expiryDate = (users[_caller][SYFP].period).add(users[_caller][SYFP].startTime);
    if (now < expiryDate)
        _totalStakedTime = now.sub(users[_caller][SYFP].lastClaimedDate);
    else {
        if (users[_caller][SYFP].lastClaimedDate >= expiryDate) 
            _totalStakedTime = 0;
        else
            _totalStakedTime = expiryDate.sub(users[_caller][SYFP].lastClaimedDate);
    }
    uint256 _reward_token_second = ((users[_caller][SYFP].rate).mul(10 ** 21)); 
    uint256 reward = ((users[_caller][SYFP].activeDeposit).mul(_totalStakedTime.mul(_reward_token_second))).div(10 ** 27); 
    reward = reward.div(365 days);
    return (reward.add(users[_caller][SYFP].pendingGains));
}

function StakingTimeLeft(address _user) external view returns(uint256 _secsLeft) {
    uint256 left = 0;
    uint256 expiryDate = (users[_user][SYFP].period).add(LastStakedOn(_user));
    if (now < expiryDate)
        left = expiryDate.sub(now);
    return left;
}

function AddToStake(uint256 _amount) external {
    require(now - users[msg.sender][SYFP].startTime < users[msg.sender][SYFP].period, "current staking expired");
    _addToExisting(SYFP, _amount);
    require(ISYFP(SYFP).transferFrom(msg.sender, address(this), _amount));
    emit AddedToExistingStake(msg.sender, _amount);
}

function ClaimUnStake() external {
    ClaimReward();
    ClaimStakedTokens();
}

function yieldWithdraw(address _tokenAddress) external {
    Yield(_tokenAddress);
