}

function internalBuyTokens(address sender, address beneficiary, uint256 tokenDeskBonus) internal {
    require(beneficiary != address(0));
    require(sender != address(0));
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 nowTime = getNow();
    while (currentStage < stages.length && stages[currentStage].till < nowTime) {
        uint256 nextStage = currentStage.add(1);
        stages[nextStage].cap = stages[nextStage].cap.add(stages[currentStage].cap);
        stages[currentStage].cap = 0;
        currentStage = nextStage;
    }
    uint256 tokens = calculateTokens(weiAmount, tokenDeskBonus);
    uint256 excess = appendContribution(beneficiary, tokens);
    uint256 refund = (excess > 0 ? excess.mul(weiAmount).div(tokens) : 0);
    weiAmount = weiAmount.sub(refund);
    weiRaised = weiRaised.add(weiAmount);
    if (refund > 0) { 
        sender.transfer(refund);
    }
    TokenPurchase(sender, beneficiary, weiAmount, tokens.sub(excess));
    if (goalReached() && vault.state() == EscrowVault.State.Active) {
        vault.setGoalReached();
    }
    vault.deposit.value(weiAmount)(sender);
}

function setIcoEndTime(uint256 _endTime) public onlyOwner {
    require(_endTime > START_TIME && _endTime > getNow());
    icoEndTime = _endTime;
}

function finalize() public onlyOwner {
    require(!isFinalized);
    require(getNow() > icoEndTime || token.totalSupply() == ICO_TOKENS);
    if (goalReached()) {
        if (vault.state() != EscrowVault.State.Closed) {
            vault.close();
        }
        uint256 totalSupply = token.totalSupply();
        teamTimelock = new TokenTimelock(token, TEAM_WALLET, getNow().add(TEAM_TOKENS_LOCK_PERIOD));
        token.mint(teamTimelock, uint256(TEAM_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        companyTimelock = new TokenTimelock(token, COMPANY_WALLET, getNow().add(COMPANY_TOKENS_LOCK_PERIOD));
        token.mint(companyTimelock, uint256(COMPANY_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        token.mint(TOURNAMENT_WALLET, uint256(TOURNAMENT_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        token.mint(BOUNTY_WALLET, uint256(BOUNTY_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        token.mint(ADVISORS_WALLET, uint256(ADVISORS_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        token.finishMinting();
        token.transferOwnership(token);
    } else {
        vault.enableRefunds();
    }
    Finalized();
    isFinalized = true;
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = getNow() >= START_TIME && getNow() <= icoEndTime;
    bool nonZeroPurchase = msg.value != 0;
    bool canMint = token.totalSupply() < ICO_TOKENS;
    bool validStage = (currentStage < stages.length);
    return withinPeriod && nonZeroPurchase && canMint && validStage;
}

function remainingReward() public onlyOwner {
    require(now > HOLDING_START);
    require(tosToken.balanceOf(this) > totalLockAmount);
    tosToken.safeTransfer(owner, tosToken.balanceOf(this).sub(totalLockAmount));
}

function release() public {
    uint256 num = now.sub(RELEASE_START).div(RELEASE_INTERVAL);
    uint256 releaseAmount = 0;
    if (num >= releasePercentages.length.sub(1)) {
        releaseAmount = lockBalanceOf[msg.sender];
        released[msg.sender] = 100;
    } else {
        releaseAmount = amountsRecords[msg.sender].mul(releasePercentages[num].sub(released[msg.sender])).div(100);
        released[msg.sender] = releasePercentages[num];
    }
    require(releaseAmount > 0);
    tosToken.safeTransfer(msg.sender, releaseAmount);
    lockBalanceOf[msg.sender] = lockBalanceOf[msg.sender].sub(releaseAmount);
    totalLockAmount = totalLockAmount.sub(releaseAmount);
}

function lock(uint256 lockAmount) public {
    require(lockAmount >= 100000 * 10 ** 18); 
    require(now <= HOLDING_START);
    uint256 reward = lockAmount.mul(20).div(100);
    require(reward <= (tosToken.balanceOf(this).sub(totalLockAmount)));
    tosToken.safeTransferFrom(msg.sender, this, lockAmount);
    lockBalanceOf[msg.sender] = lockBalanceOf[msg.sender].add(lockAmount).add(reward);
    amountsRecords[msg.sender] = lockBalanceOf[msg.sender];
    totalLockAmount = totalLockAmount.add(lockAmount).add(reward);
}

function isAllowedTx(address sender, uint256 amount) private returns(bool isAllowed) {
    if (timelock[sender] > block.timestamp) {
        return isBalanceFree(sender, amount);
    } else {
        if (frozenBalances[sender] > 0) frozenBalances[sender] = 0;
        return true;
    }
}

function fundFailed() public constant returns(bool) {
    return !__abortFuse ||
        (now > END_DATE && etherRaised < MIN_ETH_FUND);
}

function fundSucceeded() public constant returns(bool) {
    return !fundFailed() &&
        etherRaised >= MIN_ETH_FUND;
}

function proxyPurchase(address _addr)
payable
noReentry
returns(bool) {
    require(!fundFailed());
    require(!icoSuccessful);
    require(now <= END_DATE);
    require(msg.value > 0);
    if (!kycAddresses[_addr]) {
        require(now >= START_DATE);
        require((etherContributed[_addr].add(msg.value)) <= KYC_ETH_LMT);
    }
    uint tokens = ethToTokens(msg.value);
    xfer(fundWallet, _addr, tokens);
    etherContributed[_addr] = etherContributed[_addr].add(msg.value);
    etherRaised = etherRaised.add(msg.value);
    require(etherRaised <= MAX_ETH_FUND);
    return true;
}

function deposit(uint dad) public {
    uint balanceBefore = whackdContract.balanceOf(address(this));
    whackdContract.transferFrom(msg.sender, address(this), dad);
    uint balanceChange = whackdContract.balanceOf(address(this)) - balanceBefore;
    require((dad / 2) <= balanceChange && balanceChange <= dad, "saved you from getting WHACKD. retry.");
    balanceOf[msg.sender] += balanceChange;
    emit Deposit(msg.sender, balanceChange);
}

function softWithdrawRewardFor(address forAddress)
external
returns(uint) {
    uint value = calcReward(forAddress);
    rewardAtTimeOfWithdraw[forAddress] = totalReward;
    owed[forAddress] += value;
    return value;
}

function withdrawReward()
public
returns(uint) {
    uint value = calcReward(msg.sender) + owed[msg.sender];
    rewardAtTimeOfWithdraw[msg.sender] = totalReward;
    owed[msg.sender] = 0;
    if (value > 0 && !msg.sender.send(value)) {
        revert();
    }
    return value;
}

function buyback() public {
    (uint8 stage, , ) = getStage(sold);
    require(stage > 0, "buyback doesn&#39;t work on stage 0");
    uint256 approved = token.allowance(msg.sender, this);
    uint256 inCirculation = token.totalSupply().sub(token.balanceOf(this));
    uint256 value = approved.mul(address(this).balance).div(inCirculation);
    token.burnFrom(msg.sender, approved);
    msg.sender.transfer(value);
    emit Buyback(msg.sender, approved, value);
}

function getTokensForStage(uint256 _sold, uint256 _weiAmount) public view returns(uint256 tokens, uint256 left) {
    (uint8 stage, uint256 limit, uint256 rate) = getStage(_sold);
    if (stage == 4) {
        return (0, _weiAmount);
    }
    if (stage == 0 && now > END) {
        revert("Sale is refundable, unable to buy");
    }
    tokens = _weiAmount.mul(rate);
    left = 0;
    (uint8 newStage, , ) = getStage(_sold.add(tokens));
    if (newStage != stage) {
        tokens = limit.sub(_sold);
        uint256 weiSpent = (tokens.add(rate).sub(1)).div(rate);
        left = _weiAmount.sub(weiSpent);
    }
}

function isRefundable() public view returns(bool) {
    (uint8 stage, , ) = getStage(sold);
    return now > END && stage == 0;
}

function withdrawBalance()
external
onlyOwner {
    uint256 balance = address(this).balance;
    msg.sender.transfer(balance);
    emit Withdraw(balance);
}

function contribute() public payable {
    require(hasStarted == true);
    var (tokenAmount, weiRemainder) = getTokensForContribution(msg.value);
    require(tokenAmount > 0);
    require(weiRemainder <= msg.value);
    uint tokensRemaining = getTokensRemaining();
    require(tokensRemaining >= tokenAmount);
    if (!tokenWallet.transfer(msg.sender, tokenAmount)) {
        revert();
    }
    msg.sender.transfer(weiRemainder);
    uint actualContribution = msg.value - weiRemainder;
    Contribution(msg.sender, actualContribution, tokenAmount);
}

function startSale() {
    require(msg.sender == owner);
    require(hasStarted == false);
    if (!tokenWallet.transferFrom(owner, this, sale.tokenToDistibute)) {
        revert();
    } else {
        Transfer(this, sale.tokenToDistibute);
    }
    require(tokenWallet.balanceOf(this) >= sale.tokenToDistibute);
    hasStarted = true;
    Start(block.timestamp);
}

function getTokensForContribution(uint weiContribution) public constant
returns(uint tokenAmount, uint weiRemainder) {
    uint256 bonus = 0;
    uint crowdsaleEnd = sale.end;
    require(block.timestamp <= crowdsaleEnd);
    uint periodPriceInWei = sale.priceInWei;
    tokenAmount = weiContribution / periodPriceInWei;
    if (block.timestamp < 1521234001) {
        bonus = tokenAmount * 20 / 100;
    } else if (block.timestamp < 1521925201) {
        bonus = tokenAmount * 15 / 100;
    } else {
        bonus = tokenAmount * 10 / 100;
    }
    tokenAmount = tokenAmount + bonus;
    weiRemainder = weiContribution % periodPriceInWei;
}

function withdrawTokensRemaining() public
returns(bool) {
    require(msg.sender == owner);
    uint crowdsaleEnd = sale.end;
    require(block.timestamp > crowdsaleEnd);
    uint tokensRemaining = getTokensRemaining();
    return tokenWallet.transfer(owner, tokensRemaining);
}

function changeTokenForSale(uint newAmount) public {
    require(msg.sender == owner);
    require(hasStarted == false);
    require(tokenWallet.totalSupply() >= newAmount);
    require(tokenWallet.balanceOf(owner) >= newAmount);
    sale.tokenToDistibute = newAmount;
}

function escapeFunds(address _token, uint _amount) external onlyEscapeHatchCallerOrOwner {
    if (_token == 0) {
        escapeHatchDestination.transfer(_amount);
    } else {
        ERC20 token = ERC20(_token);
        require(token.transfer(escapeHatchDestination, _amount));
    }
    emit EscapeFundsCalled(_token, _amount);
}

function escapeHatch(address _token) public onlyEscapeHatchCallerOrOwner {
    require(escapeBlacklist[_token] == false);
    uint256 balance;
    if (_token == 0x0) {
        balance = this.balance;
        escapeHatchDestination.transfer(balance);
        EscapeHatchCalled(_token, balance);
        return;
    }
    ERC20 token = ERC20(_token);
    balance = token.balanceOf(this);
    require(token.transfer(escapeHatchDestination, balance));
    EscapeHatchCalled(_token, balance);
}

function disburseAuthorizedPayment(uint _idPayment) disbursementsAllowed public {
    require(_idPayment < authorizedPayments.length);
    Payment storage p = authorizedPayments[_idPayment];
    require(allowedSpenders[p.spender]);
    require(_getTime() >= p.earliestPayTime);
    require(!p.canceled);
    require(!p.paid);
    p.paid = true; 
    if (p.token == 0) {
        p.recipient.transfer(p.amount);
    } else {
        require(ERC20(p.token).transfer(p.recipient, p.amount));
    }
    emit PaymentExecuted(_idPayment, p.recipient, p.amount, p.token);
}

function cancelPayment(uint _idPayment) onlyOwner external {
    require(_idPayment < authorizedPayments.length);
    Payment storage p = authorizedPayments[_idPayment];
    require(!p.canceled);
    require(!p.paid);
    p.canceled = true;
    emit PaymentCanceled(_idPayment);
}

function disburseAuthorizedPayment(uint _idPayment) disbursementsAllowed public {
    require(_idPayment < authorizedPayments.length);
    Payment storage p = authorizedPayments[_idPayment];
    require(securityGuardLastCheckin >= p.earliestPayTime - timeLock + 30 minutes);
    super.disburseAuthorizedPayment(_idPayment);
}

function delayPayment(uint _idPayment, uint _delay) onlySecurityGuard external {
    require(_idPayment < authorizedPayments.length);
    require(_delay <= 10 ** 18);
    Payment storage p = authorizedPayments[_idPayment];
    require(p.securityGuardDelay + _delay <= maxSecurityGuardDelay);
    require(!p.paid);
    require(!p.canceled);
    p.securityGuardDelay += _delay;
    p.earliestPayTime += _delay;
}

function GetDayReward() external {
    (bool bCanSignIn, uint expire, uint todayNo) = CanSignIn();
    require(bCanSignIn);
    g_SignInDay[msg.sender] = todayNo;
    if (expire == 0) {
        g_Main.GainTempStuff(msg.sender, SGININ_REWARD_TEMPSTUFF, SGININ_REWARD_FREEDAY);
    }
    g_Main.GainStuff(msg.sender, SGININ_REWARD_STUFF, SGININ_REWARD_NUM);
}

function CanSignIn() internal view returns(bool bCanSignIn, uint expire, uint dayNo) {
    dayNo = GetDayCount(now);
    expire = g_Main.GetTempStuffExpire(msg.sender, SGININ_REWARD_TEMPSTUFF);
    if (g_SignInDay[msg.sender] >= dayNo) return;
    if (expire > 0 && expire < now) return;
    bCanSignIn = true;
}

function() external payable {
    uint256 tokensThatWillBeMintedAfterPurchase = msg.value.mul(rate);
    if ((stage == CrowdsaleStage.PreICO) && (token.totalSupply() + tokensThatWillBeMintedAfterPurchase > totalTokensForSaleDuringPreICO)) {
        msg.sender.transfer(msg.value); 
        EthRefunded("PreICO Limit Hit");
        return;
    }
    buyTokens(msg.sender);
    if (stage == CrowdsaleStage.PreICO) {
        totalWeiRaisedDuringPreICO = totalWeiRaisedDuringPreICO.add(msg.value);
    }
}

function forwardFunds() internal {
    if (stage == CrowdsaleStage.PreICO) {
        wallet.transfer(msg.value);
        EthTransferred("forwarding funds to wallet");
    } else if (stage == CrowdsaleStage.ICO) {
        EthTransferred("forwarding funds to refundable vault");
        super.forwardFunds();
    }
}

function finish(address _teamFund, address _ecosystemFund, address _bountyFund) public onlyOwner {
    require(!isFinalized);
    uint256 alreadyMinted = token.totalSupply();
    require(alreadyMinted < maxTokens);
    uint256 unsoldTokens = totalTokensForSale - alreadyMinted;
    if (unsoldTokens > 0) {
        tokensForEcosystem = tokensForEcosystem + unsoldTokens;
    }
    token.mint(_teamFund, tokensForTeam);
    token.mint(_ecosystemFund, tokensForEcosystem);
    token.mint(_bountyFund, tokensForBounty);
    finalize();
}

receive() external payable {
    require(saleOpen, "Sale is not open");
    require(userContribution[msg.sender].add(msg.value) >= 0.5 ether && userContribution[msg.sender].add(msg.value) <= 2 ether, "Min 0.5 ETH and Max 2 ETH per address");
    uint256 tokens = getTokenAmount(msg.value);
    require(IToken(tokenAddress).transfer(msg.sender, tokens), "Insufficient balance of sale contract!");
    userContribution[msg.sender] = userContribution[msg.sender].add(msg.value);
}

