function buyCore(uint256 _pID, S3Ddatasets.EventReturns memory _eventData_)
private {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now > round_[_rID].strt + rndGap_ && (_now <= round_[_rID].end || (_now > round_[_rID].end && round_[_rID].plyr == 0))) {
        core(_rID, _pID, msg.value, _eventData_);
    } else {
        if (_now > round_[_rID].end && round_[_rID].ended == false) {
            round_[_rID].ended = true;
            _eventData_ = endRound(_eventData_);
            _eventData_.compressedData = _eventData_.compressedData + (_now * 1000000000000000000);
            _eventData_.compressedIDs = _eventData_.compressedIDs + _pID;
            emit S3Devents.onBuyAndDistribute(
                msg.sender,
                msg.value,
                _eventData_.compressedData,
                _eventData_.compressedIDs,
                _eventData_.winnerAddr,
                _eventData_.amountWon,
                _eventData_.newPot,
                _eventData_.genAmount
            );
        }
        plyr_[_pID].gen = plyr_[_pID].gen.add(msg.value);
    }
}

function withdraw()
isActivated()
isHuman()
public {
    uint256 _rID = rID_;
    uint256 _now = now;
    uint256 _pID = pIDxAddr_[msg.sender];
    uint256 _eth;
    if (_now > round_[_rID].end && round_[_rID].ended == false && round_[_rID].plyr != 0) {
        S3Ddatasets.EventReturns memory _eventData_;
        round_[_rID].ended = true;
        _eventData_ = endRound(_eventData_);
        _eth = withdrawEarnings(_pID);
        if (_eth > 0)
            plyr_[_pID].addr.transfer(_eth);
        _eventData_.compressedData = _eventData_.compressedData + (_now * 1000000000000000000);
        _eventData_.compressedIDs = _eventData_.compressedIDs + _pID;
        emit S3Devents.onWithdrawAndDistribute(
            msg.sender,
            _eth,
            _eventData_.compressedData,
            _eventData_.compressedIDs,
            _eventData_.winnerAddr,
            _eventData_.amountWon,
            _eventData_.newPot,
            _eventData_.genAmount
        );
    } else {
        _eth = withdrawEarnings(_pID);
        if (_eth > 0)
            plyr_[_pID].addr.transfer(_eth);
        emit S3Devents.onWithdraw(_pID, msg.sender, _eth, _now);
    }
}

function updateTimer(uint256 _keys, uint256 _rID)
private {
    uint256 _now = now;
    uint256 _newTime;
    if (_now > round_[_rID].end && round_[_rID].plyr == 0)
        _newTime = (((_keys) / (1000000000000000000)).mul(rndInc_)).add(_now);
    else
        _newTime = (((_keys) / (1000000000000000000)).mul(rndInc_)).add(round_[_rID].end);
    if (_newTime < (rndMax_).add(_now))
        round_[_rID].end = _newTime;
    else
        round_[_rID].end = rndMax_.add(_now);
}

function core(uint256 _rID, uint256 _pID, uint256 _eth, S3Ddatasets.EventReturns memory _eventData_)
private {
    if (plyrRnds_[_pID][_rID].keys == 0)
        _eventData_ = managePlayer(_pID, _eventData_);
    if (_eth > 1000000000) {
        uint256 _keys = (round_[_rID].eth).keysRec(_eth);
        if (_keys >= 1000000000000000000) {
            updateTimer(_keys, _rID);
            if (round_[_rID].plyr != _pID)
                round_[_rID].plyr = _pID;
            _eventData_.compressedData = _eventData_.compressedData + 100;
        }
        plyrRnds_[_pID][_rID].keys = _keys.add(plyrRnds_[_pID][_rID].keys);
        plyrRnds_[_pID][_rID].eth = _eth.add(plyrRnds_[_pID][_rID].eth);
        round_[_rID].keys = _keys.add(round_[_rID].keys);
        round_[_rID].eth = _eth.add(round_[_rID].eth);
        _eventData_ = distributeExternal(_eth, _eventData_);
        _eventData_ = distributeInternal(_rID, _pID, _eth, _keys, _eventData_);
        endTx(_pID, _eth, _keys, _eventData_);
    }
}

function endRound(S3Ddatasets.EventReturns memory _eventData_)
private
returns(S3Ddatasets.EventReturns) {
    uint256 _rID = rID_;
    uint256 _winPID = round_[_rID].plyr;
    uint256 _pot = round_[_rID].pot;
    uint256 _win = (_pot.mul(90)) / 100;
    uint256 _com = (_pot / 20);
    uint256 _res = ((_pot.sub(_win)).sub(_com)).sub(_com);
    plyr_[_winPID].win = _win.add(plyr_[_winPID].win);
    if (_com > 0) {
        developer.transfer(_com);
        operator.transfer(_com);
    }
    _eventData_.compressedData = _eventData_.compressedData + (round_[_rID].end * 1000000);
    _eventData_.compressedIDs = _eventData_.compressedIDs + (_winPID * 100000000000000000000000000);
    _eventData_.winnerAddr = plyr_[_winPID].addr;
    _eventData_.amountWon = _win;
    _eventData_.genAmount = 0;
    _eventData_.newPot = _res;
    rID_++;
    _rID++;
    round_[_rID].strt = now;
    round_[_rID].end = now.add(rndInit_).add(rndGap_);
    round_[_rID].pot = _res;
    return (_eventData_);
}

function third_release(uint256 balance) private atStage(Stages.thirdRelease) {
    require(now > thirdRelease);
    uint256 amountToTransfer = balance.div(2);
    ERC20Token.transfer(beneficiary, amountToTransfer); 
    nextStage();
}

function claim() external {
    require(msg.sender == beneficiary);
    require(block.number > fundingEndBlock);
    uint256 balance = ERC20Token.balanceOf(this);
    fourth_release(balance);
    third_release(balance);
    second_release(balance);
    first_release(balance);
    init_claim(balance);
}

function second_release(uint256 balance) private atStage(Stages.secondRelease) {
    require(now > secondRelease);
    uint256 amountToTransfer = balance.div(3);
    ERC20Token.transfer(beneficiary, amountToTransfer); 
    nextStage();
}

function init_claim(uint256 balance) private atStage(Stages.initClaim) {
    firstRelease = now + 26 weeks; 
    secondRelease = firstRelease + 26 weeks;
    thirdRelease = secondRelease + 26 weeks;
    fourthRelease = thirdRelease + 26 weeks;
    uint256 amountToTransfer = balance.mul(52).div(100);
    ERC20Token.transfer(beneficiary, amountToTransfer); 
    nextStage();
}

function first_release(uint256 balance) private atStage(Stages.firstRelease) {
    require(now > firstRelease);
    uint256 amountToTransfer = balance.div(4);
    ERC20Token.transfer(beneficiary, amountToTransfer); 
    nextStage();
}

function fourth_release(uint256 balance) private atStage(Stages.fourthRelease) {
