function _createLiquidity() internal {
    genesisBlock = block.number;
    address WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address token = 0xEd7C1848FA90E6CDA4faAC7F61752857461af284;
    address staking = 0x93bF14C7Cf7250b09D78D4EadFD79FCA01BAd9F8;
    address factory = 0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f;
    address tknETHLP = I(factory).getPair(token, WETH);
    if (tknETHLP == address(0)) {
        tknETHLP = I(factory).createPair(token, WETH);
    }
    uint ETHDeposited = address(this).balance;
    I(WETH).deposit {
        value: ETHDeposited
    }();
    I(token).transfer(tknETHLP, 1e24);
    I(WETH).transfer(tknETHLP, ETHDeposited);
    I(tknETHLP).mint(staking);
    I(staking).genesis(ETHDeposited, tknETHLP, block.number);
    delete _staking;
    delete _lgeOngoing;
    delete _deployer;
    delete _hardcap;
    delete _oracle;
}

function launchMode() internal view returns(bool) {
    return launchedAt != 0 && launchedAt + 1 < block.number && launchedTime + 1 minutes >= block.timestamp;
}

function release(address payable account) public {
    require(_shares[account] > 0);
    uint256 totalReceived = address(this).balance.add(_totalReleased);
    uint256 payment = totalReceived.mul(_shares[account]).div(_totalShares).sub(_released[account]);
    require(payment != 0);
    _released[account] = _released[account].add(payment);
    _totalReleased = _totalReleased.add(payment);
    account.transfer(payment);
    emit PaymentReleased(account, payment);
}

function withdraw(address payable payee) public onlyPrimary {
    uint256 payment = _deposits[payee];
    _deposits[payee] = 0;
    payee.transfer(payment);
    emit Withdrawn(payee, payment);
}

function withdraw(address _toAddress, uint256 amount) external onlyOwner {
    require(_toAddress != address(0));
    _toAddress.transfer(amount);
    Withdraw(_toAddress, amount);
}

function removeByIdx(uint256[] array, uint256 idx) public pure returns(uint256[] memory) {
    uint256[] memory ans = copy(array, array.length - 1);
    while ((idx + 1) < array.length) {
        ans[idx] = array[idx + 1];
        idx++;
    }
    return ans;
}

