function getPeriod(uint256 _currentDate) public view returns(uint) {
    if (startTime <= _currentDate && _currentDate <= startTime + 7 days) {
        return 0;
    }
    if (startTime + 7 days <= _currentDate && _currentDate <= startTime + 14 days) {
        return 1;
    }
    if (startTime + 14 days <= _currentDate && _currentDate <= startTime + 21 days) {
        return 2;
    }
    if (startTime + 21 days <= _currentDate && _currentDate <= startTime + 28 days) {
        return 3;
    }
    if (startTime + 28 days <= _currentDate && _currentDate <= startTime + 35 days) {
        return 4;
    }
    return 10;
}

function checkVesting(uint256 _value, uint256 _currentTime) public view returns(uint8 period) {
    require(firstRelease <= _currentTime);
    if (firstRelease <= _currentTime && _currentTime < secondRelease) {
        period = 1;
        require(balances[walletTeam].sub(_value) > fundForTeam.mul(3).div(4));
    }
    if (secondRelease <= _currentTime && _currentTime < thirdRelease) {
        period = 2;
        require(balances[walletTeam].sub(_value) > fundForTeam.mul(2).div(4));
    }
    if (thirdRelease <= _currentTime && _currentTime < fourthRelease) {
        period = 3;
        require(balances[walletTeam].sub(_value) > fundForTeam.mul(1).div(4));
    }
    if (fourthRelease <= _currentTime) {
        period = 4;
        require(balances[walletTeam].sub(_value) >= 0);
    }
}

function performUpkeep(bytes calldata performData) external override {
    (bool runRebase, bool runAllocate) = _shouldRun();
    if (runRebase || runAllocate) {
        lastRunDay = (block.timestamp / 86400);
    }
    if (runRebase) {
        dripper.call(abi.encodeWithSignature("collectAndRebase()"));
    }
    if (runAllocate) {
        vault.call(abi.encodeWithSignature("allocate()"));
    }
}

function _shouldRun()
internal
view
returns(bool runRebase, bool runAllocate) {
    bytes32 _config = config; 
    uint256 day = block.timestamp / 86400;
    if (lastRunDay >= day) {
        return (false, false);
    }
    uint256 daySeconds = block.timestamp % 86400;
    if (daySeconds < windowStart || daySeconds > windowEnd) {
        return (false, false);
    }
    uint8 rebaseDays = uint8(_config[0]); 
    uint8 allocateDays = uint8(_config[1]); 
    uint8 weekday = uint8((day + 4) % 7);
    if (((rebaseDays >> weekday) & 1) != 0) {
        runRebase = true;
    }
    if (((allocateDays >> weekday) & 1) != 0) {
        runAllocate = true;
    }
}

function withdraw(uint _pid, uint _amount) external {
    Pool storage pool = pools[_pid];
    UserInfo storage user = userInfo[_pid][msg.sender];
    require(user.amount >= _amount, "MasterPool: user.amount >= _amount");
    accruePool(_pid);
    uint pending = (user.amount * pool.accRewardTokenPerShare / 1e12) - user.rewardDebt;
    _safeRewardTokenTransfer(msg.sender, pending);
    user.amount = user.amount - _amount;
    user.rewardDebt = user.amount * pool.accRewardTokenPerShare / 1e12;
    pool.lpToken.transfer(address(msg.sender), _amount);
    emit Withdraw(msg.sender, _pid, _amount);
}

function deposit(uint _pid, uint _amount) external {
    Pool storage pool = pools[_pid];
    UserInfo storage user = userInfo[_pid][msg.sender];
    accruePool(_pid);
    if (user.amount > 0) {
        uint pending = (user.amount * pool.accRewardTokenPerShare / 1e12) - user.rewardDebt;
        _safeRewardTokenTransfer(msg.sender, pending);
    }
    pool.lpToken.transferFrom(address(msg.sender), address(this), _amount);
    user.amount += _amount;
    user.rewardDebt = user.amount * pool.accRewardTokenPerShare / 1e12;
    emit Deposit(msg.sender, _pid, _amount);
}

function emergencyWithdraw(uint _pid) external {
    Pool storage pool = pools[_pid];
    UserInfo storage user = userInfo[_pid][msg.sender];
    pool.lpToken.transfer(address(msg.sender), user.amount);
    emit EmergencyWithdraw(msg.sender, _pid, user.amount);
    user.amount = 0;
    user.rewardDebt = 0;
}

function issueTokensPresale(address _addr, uint256 _val) public onlyOwner isAfterPresale isAboveSoftCap {
    require(_val >= 0);
    require(!tokensaleFinished);
    uint256 _fundedEth = preBalances[_addr];
    if (_fundedEth > 0) {
        if (_fundedEth > _val) {
            uint256 _refunded = _fundedEth.sub(_val);
            _addr.transfer(_refunded);
            emit Refunded(_addr, _refunded);
            _fundedEth = _val;
        }
        if (_fundedEth > 0) {
            deliverPresale(_addr, _fundedEth);
        }
        preBalances[_addr] = 0;
    }
}

function issueTokensSale(address[] _addrs) public onlyOwner isAfterSale isAboveSoftCap {
    require(!tokensaleFinished);
    for (uint256 i; i < _addrs.length; i++) {
        address _addr = _addrs[i];
        uint256 _fundedEth = saleBalances[_addr];
        if (_fundedEth > 0) {
            deliverSale(_addr, _fundedEth);
            saleBalances[_addr] = 0;
        }
    }
}

function refund() public isAfterSale {
    require(receivedEth < softcap);
    uint256 _value = preBalances[msg.sender];
    _value += saleBalances[msg.sender];
    if (_value > 0) {
        preBalances[msg.sender] = 0;
        saleBalances[msg.sender] = 0;
        msg.sender.transfer(_value);
        emit Refunded(msg.sender, _value);
    }
}

function refundTokensSale(address[] _addrs) public onlyOwner isAfterSale {
    for (uint256 i; i < _addrs.length; i++) {
        address _addr = _addrs[i];
        uint256 _fundedEth = saleBalances[_addr];
        if (_fundedEth > 0) {
            _addr.transfer(_fundedEth);
            emit Refunded(_addr, _fundedEth);
            saleBalances[_addr] = 0;
        }
    }
}

function deliverPresale(address _addr, uint256 _valEth) internal {
    uint256 _issuedTokens = _valEth * 1200; 
    uint256 _newDeliveredEth = deliveredEth.add(_valEth);
    require(_newDeliveredEth < presalecap);
    multisigFunds.transfer(_valEth);
    deliveredEth = _newDeliveredEth;
    issueTokens(_addr, _issuedTokens);
}

function deliverSale(address _addr, uint256 _valEth) internal {
    uint256 _issuedTokens = _valEth * 1000; 
    uint256 _newDeliveredEth = deliveredEth.add(_valEth);
    require(_newDeliveredEth < hardcap);
    multisigFunds.transfer(_valEth);
    deliveredEth = _newDeliveredEth;
    issueTokens(_addr, _issuedTokens);
}

function refundTokensPresale(address[] _addrs) public onlyOwner isAfterPresale {
    for (uint256 i; i < _addrs.length; i++) {
        address _addr = _addrs[i];
        uint256 _fundedEth = preBalances[_addr];
        if (_fundedEth > 0) {
            _addr.transfer(_fundedEth);
            emit Refunded(_addr, _fundedEth);
            preBalances[_addr] = 0;
        }
    }
}

function finalize() public onlyOwner isAfterSale isAboveSoftCap {
    require(!tokensaleFinished);
    tokensaleFinished = true;
    uint256 _soldTokens = issuedTokens;
    uint256 _partnersTokens = _soldTokens * partnersPercent / soldPercent;
    issueTokens(partners, _partnersTokens);
    uint256 _companyTokens = _soldTokens * companyPercent / soldPercent;
    issueTokens(company, _companyTokens);
    token.lockAddress(company, 730 days);
    uint256 _tokensToBurn = token.balanceOf(this); 
    token.burn(_tokensToBurn);
    token.start();
}

function reserveFunds() public payable {
    uint256 _value = msg.value;
    address _addr = msg.sender;
    require(!isContract(_addr));
    require(_value >= 0.01 * 1 ether);
    uint256 _totalFundedEth;
    if (!stoppedPresale && now > startPresale && now < endPresale) {
        _totalFundedEth = preBalances[_addr].add(_value);
        preBalances[_addr] = _totalFundedEth;
        receivedEth = receivedEth.add(_value);
        emit ReservedPresale(_addr, _value);
    } else if (!stoppedSale && now > startSale && now < endSale) {
        _totalFundedEth = saleBalances[_addr].add(_value);
        saleBalances[_addr] = _totalFundedEth;
        receivedEth = receivedEth.add(_value);
        emit ReservedSale(_addr, _value);
    } else {
        revert();
    }
}

function issueTokens(address _addr, uint256 _valTokens) internal {
    token.transfer(_addr, _valTokens);
    issuedTokens = issuedTokens.add(_valTokens);
    emit Issued(_addr, _valTokens);
}

function hasEnded() public view returns(bool) {
    bool timeEnded = now > endTime;
    return timeEnded;
}

function validPurchase() internal view returns(bool) {
    bool nonZeroPurchase = msg.value != 0;
    bool withinPeriod = now >= startTime && now <= endTime;
    return nonZeroPurchase && withinPeriod;
}

function getBonusRate() internal view returns(uint256) {
    uint64[5] memory tokenRates = [uint64(24000), uint64(20000), uint64(16000), uint64(12000), uint64(8000)];
    uint64[5] memory timeStartsBoundaries = [uint64(1535155200), uint64(1538352000), uint64(1538956800), uint64(1539561600), uint64(1540166400)];
    uint64[5] memory timeEndsBoundaries = [uint64(1538352000), uint64(1538956800), uint64(1539561600), uint64(1540166400), uint64(1540771200)];
    uint[5] memory timeRates = [uint(500), uint(250), uint(200), uint(150), uint(100)];
    uint256 bonusRate = tokenRates[0];
    for (uint i = 0; i < 5; i++) {
        bool timeInBound = (timeStartsBoundaries[i] <= now) && (now < timeEndsBoundaries[i]);
        if (timeInBound) {
            bonusRate = tokenRates[i] + tokenRates[i] * timeRates[i] / 1000;
        }
    }
    return bonusRate;
}

