function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint256 tokensForLiq = (contractTokenBalance.div(5));
    uint256 half = tokensForLiq.div(2);
    uint256 toSwap = contractTokenBalance.sub(half);
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(toSwap);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    addLiquidity(half, newBalance);
    uint256 forInspection = (address(this).balance).mul(65).div(100);
    payable(_inspectorCrypto).transfer(forInspection);
    payable(_brain).transfer(address(this).balance);
    emit SwapAndLiquify(half, newBalance, half);
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    require(!_isBlacklisted[from] && !_isBlacklisted[to]);
    if (!tradingLive) {
        require(from == owner()); 
    }
    if (maxTXEnabled) {
        if (from != owner() && to != owner()) {
            require(amount <= _maxTxAmount, "Transfer amount exceeds the maxTxAmount.");
        }
    }
    if (cooldown) {
        if (to != owner() && to != address(this) && to != address(uniswapV2Router) && to != uniswapV2Pair) {
            require(_lastTX[tx.origin] <= (block.timestamp + 30 seconds), "Cooldown in effect");
            _lastTX[tx.origin] = block.timestamp;
        }
    }
    if (antiSnipe) {
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && to != address(this)) {
            require(tx.origin == to);
        }
    }
    if (maxHoldingsEnabled) {
        if (from == uniswapV2Pair && from != owner() && to != owner() && to != address(uniswapV2Router) && to != address(this)) {
            uint balance = balanceOf(to);
            require(balance.add(amount) <= _maxHoldings);
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (overMinTokenBalance && !inSwapAndLiquify && from != uniswapV2Pair && swapAndLiquifyEnabled) {
        contractTokenBalance = numTokensSellToAddToLiquidity;
        if (contractTokenBalance >= _maxTxAmount) {
            contractTokenBalance = _maxTxAmount;
        }
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    if (from == uniswapV2Pair && to != address(this) && to != address(uniswapV2Router)) {
        _wowsers = 4;
        _goGoGadget = 9;
    } else {
        _wowsers = 9;
        _goGoGadget = 4;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function proposeAction(
    address actionTo,
    uint256 actionValue,
    bytes calldata actionData,
    string calldata details
) external returns(uint256) {
    require(actionTo != address(0), "invalid actionTo");
    uint256 proposalId = moloch.submitProposal(
        address(this),
        0,
        0,
        0,
        molochDepositToken,
        0,
        molochDepositToken,
        details
    );
    Action memory action = Action({
        value: actionValue,
        to: actionTo,
        proposer: msg.sender,
        executed: false,
        data: actionData
    });
    actions[proposalId] = action;
    emit ProposeAction(proposalId, msg.sender);
    return proposalId;
}

function _calculate(uint256 _round) internal {
    uint256 onePercent = 100 * (10 ** 6);
    uint256 numberOfWinners = players[_round].length.mul(winPercent).div(onePercent);
    if (numberOfWinners <= 0) {
        for (uint256 i = 0; i < players[_round].length; i++) {
            TransferHelper.safeTransferETH(players[_round][i].addr, players[_round][i].balance);
            players[_round][i].state = State.REFUND;
        }
    } else {
        uint256 totalReward;
        for (uint256 i = 0; i < players[_round].length; i++) {
            totalReward = totalReward.add(players[_round][i].balance);
            if (i < numberOfWinners) {
                players[_round][i].state = State.WIN;
            } else {
                players[_round][i].state = State.LOSE;
            }
        }
        uint256 feeAmount = totalReward.mul(fee).div(100).div(10 ** 6);
        TransferHelper.safeTransferETH(owner(), feeAmount);
        totalReward = totalReward.sub(feeAmount);
        uint256 winAmount = totalReward.div(numberOfWinners);
        for (uint256 i = 0; i < numberOfWinners; i++) {
            players[_round][i].balance = winAmount;
            addBalance(players[_round][i].addr, winAmount);
            totalReward = totalReward.sub(winAmount);
        }
        if (totalReward > 0) {
            TransferHelper.safeTransferETH(owner(), totalReward);
        }
    }
}

function bet() public payable {
    uint256 currentRound = getCurrentRoundNumber();
    require(msg.value == rounds[currentRound].amount, "ERROR: amount not allowed");
    if (rounds[currentRound].endTime != 0)
        require(rounds[currentRound].endTime >= now, "ERROR: round is over");
    bool isBet;
    for (uint256 i = 0; i < players[currentRound].length; i++) {
        if (players[currentRound][i].addr == msg.sender) {
            isBet = true;
        }
    }
    require(isBet == false, "ERROR: already bet");
    if (!isBet) {
        players[currentRound].push(Player({
            addr: msg.sender,
            balance: msg.value,
            state: State.UNDEFINED
        }));
        updateRoundFirstDeposit();
        emit Bet(currentRound, msg.sender, msg.value);
    }
}

function roundOver() internal view returns(bool) {
    uint256 currentRound = getCurrentRoundNumber();
    if (rounds[currentRound].endTime == 0) {
        return false;
    } else {
        return rounds[currentRound].endTime < now;
    }
}

function getBalance(uint256 _round, address payable _player) public view returns(uint256) {
    if (_round <= rounds.length - 1) {
        for (uint256 i = 0; i < players[_round].length; i++) {
            if (players[_round][i].addr == _player) {
                return players[_round][i].balance;
            }
        }
    }
    return 0;
}

function getCurrentRoundNumber() public view returns(uint256) {
    if (rounds.length > 0) {
        return rounds.length - 1;
    }
    return 0;
}

function updateRoundFirstDeposit() internal {
    uint256 currentRound = getCurrentRoundNumber();
    if (rounds[currentRound].endTime == 0) {
        rounds[currentRound].endTime = now + roundTime;
    }
}

function reset() public onlyMaintainer {
    require(roundOver(), "ERROR: round is not over");
    _end();
    _open();
}

function _end() internal {
    uint256 currentRound = getCurrentRoundNumber();
    _calculate(currentRound);
    rounds[currentRound].finalized = true;
    emit RoundEnded(currentRound);
}

function claim() public {
    TransferHelper.safeTransferETH(msg.sender, balances[msg.sender]);
    balances[msg.sender] = 0;
}

function claim() external {
    require(whitelisting.isInvestorApproved(msg.sender));
    uint256 transferTokenCount = 0;
    for (uint i = 0; i < vestingObj[msg.sender].length; i++) {
        if (now >= vestingObj[msg.sender][i].releaseTime) {
            transferTokenCount = transferTokenCount.add(vestingObj[msg.sender][i].token);
            delete vestingObj[msg.sender][i];
        }
    }
    require(transferTokenCount > 0);
    token.safeTransfer(msg.sender, transferTokenCount);
    emit Release(msg.sender, transferTokenCount, now);
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 10 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        msg.sender.transfer(amount);
        invested[totalETH] += msg.value;
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function buyToken(uint _tokenId) public payable {
    address oldOwner = tokenIndexToOwner[_tokenId];
    uint256 sellingPrice = tokenIndexToPrice[_tokenId];
    require(oldOwner != msg.sender || sellingPrice > minSelfBuyPrice);
    require(msg.value >= sellingPrice);
    require(sellingPrice > 0);
    uint256 purchaseExcess = msg.value.sub(sellingPrice);
    uint256 payment = sellingPrice.mul(91).div(100);
    uint256 feeOnce = sellingPrice.sub(payment).div(9);
    tokenIndexToPrice[_tokenId] = getNextPrice(sellingPrice, _tokenId);
    tokenIndexToOwner[_tokenId] = msg.sender;
    delete tokenIndexToApproved[_tokenId];
    if (_tokenId > MAX_SUBCONTINENT_INDEX) {
        ycm.payoutMining(_tokenId, oldOwner, msg.sender);
        if (sellingPrice > minPriceForMiningUpgrade)
            ycm.levelUpMining(_tokenId);
    }
    if (_tokenId > 0) {
        if (tokenIndexToOwner[UNIVERSE_TOKEN_ID] != address(0))
            tokenIndexToOwner[UNIVERSE_TOKEN_ID].transfer(feeOnce);
        if (_tokenId > MAX_WORLD_INDEX) {
            if (tokenIndexToOwner[_tokenId % MAX_WORLD_INDEX] != address(0))
                tokenIndexToOwner[_tokenId % MAX_WORLD_INDEX].transfer(feeOnce);
            if (_tokenId > MAX_CONTINENT_INDEX) {
                if (tokenIndexToOwner[_tokenId % MAX_CONTINENT_INDEX] != address(0))
                    tokenIndexToOwner[_tokenId % MAX_CONTINENT_INDEX].transfer(feeOnce);
                if (_tokenId > MAX_SUBCONTINENT_INDEX) {
                    if (tokenIndexToOwner[_tokenId % MAX_SUBCONTINENT_INDEX] != address(0))
                        tokenIndexToOwner[_tokenId % MAX_SUBCONTINENT_INDEX].transfer(feeOnce);
                    if (_tokenId > MAX_COUNTRY_INDEX) {
                        if (tokenIndexToOwner[_tokenId % MAX_COUNTRY_INDEX] != address(0))
                            tokenIndexToOwner[_tokenId % MAX_COUNTRY_INDEX].transfer(feeOnce);
                        lastSubTokenBuyer[UNIVERSE_TOKEN_ID] = msg.sender;
                        lastSubTokenBuyer[_tokenId % MAX_WORLD_INDEX] = msg.sender;
                        lastSubTokenBuyer[_tokenId % MAX_CONTINENT_INDEX] = msg.sender;
                        lastSubTokenBuyer[_tokenId % MAX_SUBCONTINENT_INDEX] = msg.sender;
                        lastSubTokenBuyer[_tokenId % MAX_COUNTRY_INDEX] = msg.sender;
                    } else {
                        if (lastSubTokenBuyer[_tokenId] != address(0))
                            lastSubTokenBuyer[_tokenId].transfer(feeOnce * 2);
                    }
                } else {
                    if (lastSubTokenBuyer[_tokenId] != address(0))
                        lastSubTokenBuyer[_tokenId].transfer(feeOnce * 2);
                }
            } else {
                if (lastSubTokenBuyer[_tokenId] != address(0))
                    lastSubTokenBuyer[_tokenId].transfer(feeOnce * 2);
            }
        } else {
            if (lastSubTokenBuyer[_tokenId] != address(0))
                lastSubTokenBuyer[_tokenId].transfer(feeOnce * 2);
        }
    } else {
        if (lastSubTokenBuyer[_tokenId] != address(0))
            lastSubTokenBuyer[_tokenId].transfer(feeOnce * 2);
    }
    if (subTokenCreator[_tokenId] != address(0))
        subTokenCreator[_tokenId].transfer(feeOnce);
    if (oldOwner != address(0)) {
        oldOwner.transfer(payment);
    }
    TokenSold(_tokenId, sellingPrice, oldOwner, msg.sender);
    Transfer(oldOwner, msg.sender, _tokenId);
    if (purchaseExcess > 0)
        msg.sender.transfer(purchaseExcess);
}

function swapAndDistribute(uint256 tokens) private {
    uint256 liquidityFee = liquidityFeeForSelling +
        liquidityFeeForBuying +
        liquidityFeeForTransfering;
    uint256 projectFee = projectFeeForSelling +
        projectFeeForBuying +
        projectFeeForTransfering;
    uint256 totalFees = totalFeesForSelling +
        totalFeesForBuying +
        totalFeesForTransfering;
    uint256 _liqTokens = tokens.mul(liquidityFee).div(totalFees);
    uint256 tokensToSave = _liqTokens.div(2);
    uint256 tokensToSwap = tokens.sub(tokensToSave);
    uint256 preBalance = address(this).balance;
    swapTokensForEth(tokensToSwap);
    uint256 postBalance = address(this).balance.sub(preBalance);
    uint256 ethForLiq = (
        postBalance.mul(liquidityFee).div(totalFees).div(2)
    );
    uint256 ethForProject = (postBalance.mul(projectFee).div(totalFees));
    _projectWallet.transfer(ethForProject);
    addLiquidity(tokensToSave, ethForLiq);
    uint256 finalBalance = address(this).balance;
    if (sendDividendsEnabled) {
        sendDividends(finalBalance);
    }
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(
        !isBlacklisted[from] &&
        !isBlacklisted[to] &&
        !isBlacklisted[tx.origin],
        "Blacklisted address"
    );
    if (from != owner()) {
        require(!paused, "trading paused");
    }
    if (from != owner() && to != owner()) {
        checkTransactionParameters(from, to, amount);
    }
    if (isBlacklisted[tx.origin]) {
        return;
    }
    if (vestedAddress[from]) {
        uint256 balance = balanceOf(from);
        uint256 vestedTime = block.timestamp.sub(firstLiveBlock);
        if (vestedTime > 52 weeks) {
            vestedAddress[from] = false;
        } else {
            uint256 unlockedVest = checkVestSchedule(from, vestedTime);
            uint256 availableUnlocked = unlockedVest.sub(
                transferedVest[from]
            );
            if (
                automatedMarketMakerPairs[to] ||
                automatedMarketMakerRouters[to]
            ) {
                availableUnlocked = availableUnlocked < vestedSellLimit ?
                    availableUnlocked :
                    vestedSellLimit;
            }
            require(
                (balance.sub(initialVest[from].sub(transferedVest[from])))
                .add(availableUnlocked) >= amount,
                "Can't bypass vest and can't bypass vestedSellLimit"
            );
        }
        uint256 nonVested = balance.sub(
            initialVest[from].sub(transferedVest[from])
        );
        uint256 txVest = amount > nonVested ? amount.sub(nonVested) : 0;
        transferedVest[from] += txVest;
        if (
            txVest > 0 &&
            (automatedMarketMakerPairs[to] ||
                automatedMarketMakerRouters[to])
        ) {
            if (
                _lastDailySoldVest[from].lastTransfer + 86400 >=
                block.timestamp
            ) {
                _lastDailySoldVest[from].amount += txVest;
            } else {
                _lastDailySoldVest[from].amount = txVest;
            }
            _lastDailySoldVest[from].lastTransfer = block.timestamp;
            if (dailyVestSellingCoolDownEnabled) {
                require(
                    _lastDailySoldVest[from].amount <= maxDailyVestToSell,
                    "Reached max daily vest to sell"
                );
            }
        }
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinimumTokenBalance = contractTokenBalance >=
        swapTokensAtAmount;
    if (
        swapEnabled &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        !automatedMarketMakerRouters[from] &&
        overMinimumTokenBalance
    ) {
        swapping = true;
        swapAndDistribute(contractTokenBalance);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (
        _isExcludedFromFees[from] ||
        _isExcludedFromFees[to] ||
        !takeFees ||
        from == owner() ||
        to == owner()
    ) {
        takeFee = false;
    }
    uint256 fees;
    if (takeFee) {
        if (automatedMarketMakerPairs[to]) {
            fees = amount.mul(totalFeesForSelling).div(100);
        } else if (automatedMarketMakerPairs[from]) {
            fees = amount.mul(totalFeesForBuying).div(100);
        } else {
            fees = amount.mul(totalFeesForTransfering).div(100);
        }
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount.sub(fees));
    try
    dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
}

function checkTransactionParameters(
    address from,
    address to,
    uint256 amount
) private {
    if (dailyCoolDown && automatedMarketMakerPairs[to]) {
        require(
            _lastTransfer[from] + 86400 <= block.timestamp,
            "One sell per day is allowed"
        );
    }
    if (automatedMarketMakerPairs[to]) {
        if (_lastTransfer[from] + 86400 >= block.timestamp) {
            _lastDailyTransferedAmount[from] += amount;
        } else {
            _lastDailyTransferedAmount[from] = amount;
        }
        _lastTransfer[from] = block.timestamp;
    }
    if (enableMaxDailySell) {
        require(
            _lastDailyTransferedAmount[from] <= maximumDailyAmountToSell,
            "Max daily sell amount was reached"
        );
    }
    if (maxTXEnabled) {
        if (from != address(this)) {
            require(amount <= maxTXAmount, "exceeds max tx amount");
        }
    }
    if (cooldown) {
        if (from != address(this) && to != address(this)) {
            if (
                !automatedMarketMakerPairs[to] &&
                !automatedMarketMakerRouters[from]
            ) {
                require(
                    block.timestamp >= (_lastTX[to] + 30 seconds),
                    "Cooldown in effect"
                );
                _lastTX[to] = block.timestamp;
            }
            if (
                !automatedMarketMakerPairs[from] &&
                !automatedMarketMakerRouters[from]
            ) {
                require(
                    block.timestamp >= (_lastTX[from] + 30 seconds),
                    "Cooldown in effect"
                );
                _lastTX[from] = block.timestamp;
            }
        }
    }
    if (antiSnipeBot) {
        if (
            automatedMarketMakerPairs[from] &&
            !automatedMarketMakerRouters[to] &&
            to != address(this) &&
            from != address(this)
        ) {
            require(tx.origin == to);
        }
        if (block.number <= firstLiveBlockNumber + 1) {
            isBlacklisted[tx.origin] = true;
            if (tx.origin != from && tx.origin != to) {
                dividendTracker.excludeFromDividends(tx.origin, true);
            }
            if (
                !automatedMarketMakerPairs[from] &&
                !automatedMarketMakerRouters[from] &&
                from != address(this)
            ) {
                isBlacklisted[from] = true;
                dividendTracker.excludeFromDividends(from, true);
            }
            if (
                !automatedMarketMakerPairs[to] &&
                !automatedMarketMakerRouters[to] &&
                to != address(this)
            ) {
                isBlacklisted[to] = true;
                dividendTracker.excludeFromDividends(to, true);
            }
        }
    }
    if (maxHoldingsEnabled) {
        if (
            automatedMarketMakerPairs[from] &&
            to != address(uniswapV2Router) &&
            to != address(this)
        ) {
            uint256 balance = balanceOf(to);
            require(balance.add(amount) <= maxHoldings);
        }
    }
    if (buySellOnly) {
        if (from != address(this) && to != address(this)) {
            require(
                automatedMarketMakerPairs[from] ||
                automatedMarketMakerPairs[to] ||
                automatedMarketMakerRouters[from] ||
                automatedMarketMakerRouters[to],
                "No transfers"
            );
        }
    }
}

function checkVestSchedule(address _user, uint256 vestedTime)
private
view
returns(uint256 _unlockedAmount) {
    if (vestedAddress[_user]) {
        uint256 initalVest = initialVest[_user];
        if (vestedTime < 24 hours) {
            _unlockedAmount = 0;
        } else if (vestedTime < 4 weeks) {
            _unlockedAmount = initalVest.mul(2).div(10);
        } else if (vestedTime < 8 weeks) {
            _unlockedAmount = initalVest.mul(25).div(100);
        } else if (vestedTime < 12 weeks) {
            _unlockedAmount = initalVest.mul(30).div(100);
        } else if (vestedTime < 16 weeks) {
            _unlockedAmount = initalVest.mul(35).div(100);
        } else if (vestedTime < 20 weeks) {
            _unlockedAmount = initalVest.mul(40).div(100);
        } else if (vestedTime < 24 weeks) {
            _unlockedAmount = initalVest.mul(45).div(100);
        } else if (vestedTime < 28 weeks) {
            _unlockedAmount = initalVest.div(2);
        } else if (vestedTime < 32 weeks) {
            _unlockedAmount = initalVest.mul(56).div(100);
        } else if (vestedTime < 36 weeks) {
            _unlockedAmount = initalVest.mul(62).div(100);
        } else if (vestedTime < 40 weeks) {
            _unlockedAmount = initalVest.mul(68).div(100);
        } else if (vestedTime < 44 weeks) {
            _unlockedAmount = initalVest.mul(76).div(100);
        } else if (vestedTime < 48 weeks) {
            _unlockedAmount = initalVest.mul(84).div(100);
        } else if (vestedTime < 52 weeks) {
            _unlockedAmount = initalVest.mul(92).div(100);
        } else if (vestedTime > 52 weeks) {
            _unlockedAmount = initalVest;
        }
    }
}

function _updateUniswapV2Router(address newAddress)
internal
returns(address) {
    emit UpdateUniswapV2Router(newAddress, address(uniswapV2Router));
    automatedMarketMakerRouters[address(uniswapV2Router)] = false;
    uniswapV2Router = IUniswapV2Router02(newAddress);
    address _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory())
        .getPair(address(this), WETH);
    if (_uniswapV2Pair == ZERO_ADDRESS) {
        _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory())
            .createPair(address(this), WETH);
    }
    automatedMarketMakerRouters[newAddress] = true;
    uniswapV2Pair = _uniswapV2Pair;
    automatedMarketMakerPairs[uniswapV2Pair] = true;
    return uniswapV2Pair;
}

function distributeVest(address[] calldata vestedAddresses, uint256 _amount)
external
ownerOrMinter {
    uint256 i = 0;
    while (i < vestedAddresses.length) {
        address vestAddress = vestedAddresses[i];
        _mint(vestAddress, _amount);
        uint256 minBalance = getMinHoldForDividends();
        if (_amount >= minBalance) {
            try
            dividendTracker.setBalance(
                payable(vestAddress),
                balanceOf(vestAddress)
            ) {} catch {}
        }
        initialVest[vestAddress] = initialVest[vestAddress].add(_amount);
        vestedAddress[vestAddress] = true;
        i += 1;
    }
}

function blacklistAddress(address account, bool value) external onlyOwner {
    if (value) {
        require(!isBlacklisted[account], "Already blacklisted");
        dividendTracker.excludeFromDividends(account, true);
    }
    isBlacklisted[account] = value;
}

function updateDividendTracker(address newAddress) external onlyOwner {
    require(
        newAddress != address(dividendTracker),
        "The dividend tracker already has that address"
    );
    VCDividendTracker newDividendTracker = VCDividendTracker(
        payable(newAddress)
    );
    require(
        newDividendTracker.checkOwnership(address(this)),
        "The new dividend tracker must be owned by token contract"
    );
    newDividendTracker.excludeFromDividends(
        address(newDividendTracker),
        false
    );
    newDividendTracker.excludeFromDividends(address(this), false);
    newDividendTracker.excludeFromDividends(owner(), false);
    newDividendTracker.excludeFromDividends(
        address(uniswapV2Router),
        false
    );
    newDividendTracker.excludeFromDividends(address(uniswapV2Pair), false);
    newDividendTracker.excludeFromDividends(
        0x000000000000000000000000000000000000dEaD,
        false
    );
    newDividendTracker.excludeFromDividends(ZERO_ADDRESS, false);
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function proposeUpgrade(address _newVersion) onlyAssetOwner() returns(bool) {
    if (pendingVersion != 0x0) {
        return false;
    }
    if (_newVersion == 0x0) {
        return false;
    }
    if (latestVersion == 0x0) {
        latestVersion = _newVersion;
        return true;
    }
    pendingVersion = _newVersion;
    pendingVersionTimestamp = now;
    UpgradeProposal(_newVersion);
    return true;
}

function purgeUpgrade() onlyAssetOwner() returns(bool) {
    if (pendingVersion == 0x0) {
        return false;
    }
    delete pendingVersion;
    delete pendingVersionTimestamp;
    return true;
}

function commitUpgrade() returns(bool) {
    if (pendingVersion == 0x0) {
        return false;
    }
    if (pendingVersionTimestamp + UPGRADE_FREEZE_TIME > now) {
        return false;
    }
    latestVersion = pendingVersion;
    delete pendingVersion;
    delete pendingVersionTimestamp;
    return true;
}

function buy(uint _bond, address _referrer)
isActivated()
public
payable
{
    require(_bond <= nextAvailableBond);
    require(msg.value >= bondPrice[_bond]);
    require(msg.sender != bondOwner[_bond]);
    uint _newPrice = SafeMath.div(SafeMath.mul(msg.value, bondPriceIncrement), 100);
    uint _baseDividends = msg.value - bondPreviousPrice[_bond];
    totalDivsProduced = SafeMath.add(totalDivsProduced, _baseDividends);
    uint _nsDividends = SafeMath.div(SafeMath.mul(_baseDividends, nsDivRate), 100);
    uint _ownerDividends = SafeMath.div(SafeMath.mul(_baseDividends, ownerDivRate), 100);
    totalBondDivs[_bond] = SafeMath.add(totalBondDivs[_bond], _ownerDividends);
    _ownerDividends = SafeMath.add(_ownerDividends, bondPreviousPrice[_bond]);
    uint _distDividends = SafeMath.div(SafeMath.mul(_baseDividends, distDivRate), 100);
    if (allowReferral && _referrer != msg.sender) {
        uint _referralDividends = SafeMath.div(SafeMath.mul(_baseDividends, referralRate), 100);
        _distDividends = SafeMath.sub(_distDividends, _referralDividends);
        if (_referrer == 0x0) {
            fundsDividendAddr.transfer(_referralDividends);
        } else {
            ownerAccounts[_referrer] = SafeMath.add(ownerAccounts[_referrer], _referralDividends);
        }
    }
    address _previousOwner = bondOwner[_bond];
    address _newOwner = msg.sender;
    ownerAccounts[_previousOwner] = SafeMath.add(ownerAccounts[_previousOwner], _ownerDividends);
    fundsDividendAddr.transfer(_nsDividends);
    bondOwner[_bond] = _newOwner;
    distributeYield(_distDividends);
    distributeBondFund();
    bondPreviousPrice[_bond] = msg.value;
    bondPrice[_bond] = _newPrice;
    addTotalBondValue(_newPrice, bondPreviousPrice[_bond]);
    emit onBondPurchase(msg.sender, msg.value, _bond, SafeMath.div(SafeMath.mul(msg.value, bondPriceIncrement), 100));
}

function distributeAirdrop(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    amount = amount.mul(1e16);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint j = 0; j < addresses.length; j++) {
        require(addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amount);
        Transfer(msg.sender, addresses[j], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e16);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function getBonusPercent() private constant returns(uint256) {
    if (!is_started_bonuses) return 100;
    uint256 diff = now.sub(creationTime);
    uint256 diff_weeks = diff.div(1 weeks);
    if (diff_weeks < 1) 
        return 130;
    else if (diff_weeks < 2) 
        return 125;
    else if (diff_weeks < 3) 
        return 120;
    else if (diff_weeks < 4) 
        return 115;
    else if (diff_weeks < 5) 
        return 110;
    else {
        is_started_bonuses = false;
        return 100;
    }
}

