function refund() {
    if (msg.sender == owner) {
        while (this.balance > ante) {
            gamblers[player_count].transfer(ante);
            player_count -= 1;
        }
        gamblers[1].transfer(this.balance);
    }
}

function() payable {
    if (msg.value != ante) throw; 
    player_count += 1;
    gamblers[player_count] = msg.sender;
    if (player_count == required_number_players) {
        bet_blocknumber = block.number;
    }
    if (player_count == required_number_players) {
        if (block.number == bet_blocknumber) {
            random = uint(block.blockhash(block.number)) % required_number_players + 1;
            gamblers[random].transfer(ante * required_number_players * winner_percentage / 100);
            0xBdf8fF4648bF66c03160F572f67722cf9793cE6b.transfer((ante * required_number_players - ante * required_number_players * winner_percentage / 100) / 2);
            0xA7aa3509d62B9f8B6ee02EA0cFd3738873D3ee4C.transfer((ante * required_number_players - ante * required_number_players * winner_percentage / 100) / 2);
            next_round_players = player_count - required_number_players;
            while (player_count > required_number_players) {
                gamblers[player_count - required_number_players] = gamblers[player_count];
                player_count -= 1;
            }
            player_count = next_round_players;
        } else throw;
    }
}

function buyTokens(address beneficiary) public payable whenNotPaused {
    require(beneficiary != address(0));
    validPurchase();
    uint256 weiAmount = msg.value;
    uint256 tokens = getTokenAmount(weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    tokensSold = tokensSold.add(tokens);
    deposited[msg.sender] = deposited[msg.sender].add(weiAmount);
    updateRoundLimits(tokens);
    uint256 lockedFor = assignTokens(beneficiary, tokens);
    emit TokenPurchase(msg.sender, beneficiary, weiAmount, tokens, lockedFor);
    forwardFunds();
}

function unlockedBalance(address _owner) public view returns(uint256 amount) {
    for (uint256 i = 0; i < ledger[_owner].releaseTime.length; i++) {
        uint256 time = ledger[_owner].releaseTime[i];
        if (now >= time) amount += ledger[_owner].balance[time];
    }
}

function releaseEQUITokens(bytes32 hash, uint8 v, bytes32 r, bytes32 s) public whenNotPaused {
    require(balances[msg.sender] > 0);
    uint256 amount = 0;
    for (uint8 i = 0; i < ledger[msg.sender].releaseTime.length; i++) {
        uint256 time = ledger[msg.sender].releaseTime[i];
        if (now >= time && ledger[msg.sender].balance[time] > 0) {
            amount = ledger[msg.sender].balance[time];
            ledger[msg.sender].balance[time] = 0;
            continue;
        }
    }
    if (amount <= 0 || balances[msg.sender] < amount) {
        revert();
    }
    if (isKYCRequired) {
        require(isWhitelistedAddress(hash, v, r, s));
        balances[msg.sender] = balances[msg.sender].sub(amount);
        if (!token.transferFrom(tokenWallet, msg.sender, amount)) {
            revert();
        }
        emit TokenReleased(msg.sender, amount);
    } else {
        balances[msg.sender] = balances[msg.sender].sub(amount);
        if (!token.transferFrom(tokenWallet, msg.sender, amount)) {
            revert();
        }
        emit TokenReleased(msg.sender, amount);
    }
}

