function _transfer(address _from, address _to, uint256 _value) internal {
    require(_to != address(0), "ARTI: Transfer to the zero address");
    require(balances[_from] >= _value, "ARTI: Transfer Balance is insufficient.");
    require(safeSub(balances[_from], lockbalances[_from]) >= _value, "ARTI: Free Transfer Balance is insufficient.");
    if (!freeLock[_from]) {
        require(!LockTransfer, "ARTI: Lock transfer.");
        require(!frozenSend[_from], "ARTI: This address is locked to send.");
        require(!frozenReceive[_to], "ARTI: This address is locked to receive.");
        if (holdStart[_from] > 0) {
            require(block.timestamp < holdStart[_from], "ARTI: This address is locked at now.");
        }
        if (holdEnd[_from] > 0) {
            require(block.timestamp > holdEnd[_from], "ARTI: This address is locked at now.");
        }
    }
    balances[_from] = safeSub(balances[_from], _value);
    balances[_to] = safeAdd(balances[_to], _value);
    emit Transfer(_from, _to, _value);
}

function openCdp(uint256 _leverage, uint256 _leverageSizeInAttoeth, uint256 _allowedFeeInAttoeth, uint256 _affiliateFeeInAttoeth, address _affiliateAddress) public payable returns(bytes32 _cdpId) {
    require(_leverage >= 100 && _leverage <= 300);
    uint256 _lockedInCdpInAttoeth = _leverageSizeInAttoeth.mul(_leverage).div(100);
    uint256 _loanInAttoeth = _lockedInCdpInAttoeth.sub(_leverageSizeInAttoeth);
    uint256 _providerFeeInAttoeth = _loanInAttoeth.mul18(providerFeePerEth);
    require(_providerFeeInAttoeth <= _allowedFeeInAttoeth);
    uint256 _drawInAttodai = _loanInAttoeth.mul18(uint256(maker.pip().read()));
    uint256 _pethLockedInCdp = _lockedInCdpInAttoeth.div27(maker.per());
    weth.deposit.value(_leverageSizeInAttoeth)();
    _cdpId = maker.open();
    maker.join(_pethLockedInCdp);
    maker.lock(_cdpId, _pethLockedInCdp);
    maker.draw(_cdpId, _drawInAttodai);
    uint256 _wethBoughtInAttoweth = oasis.sellAllAmount(dai, _drawInAttodai, weth, 0);
    uint256 _refundDue = msg.value.add(_wethBoughtInAttoweth).sub(_lockedInCdpInAttoeth).sub(_providerFeeInAttoeth).sub(_affiliateFeeInAttoeth);
    if (_loanInAttoeth > _wethBoughtInAttoweth) {
        weth.deposit.value(_loanInAttoeth - _wethBoughtInAttoweth)();
    }
    if (_providerFeeInAttoeth != 0) {
        asyncSend(owner, _providerFeeInAttoeth);
    }
    if (_affiliateFeeInAttoeth != 0) {
        asyncSend(_affiliateAddress, _affiliateFeeInAttoeth);
    }
    emit NewCup(msg.sender, _cdpId);
    maker.give(_cdpId, msg.sender);
    if (_refundDue > 0) {
        require(msg.sender.call.value(_refundDue)());
    }
}

function distribute(uint up1RefCode, uint up2RefCode, uint up3RefCode) internal {
    uint v1;
    uint v2;
    uint v3;
    uint w1;
    uint w2;
    v1 = msg.value.mul(40 ether).div(100 ether);
    v2 = msg.value.mul(30 ether).div(100 ether);
    v3 = msg.value.mul(20 ether).div(100 ether);
    w1 = msg.value.mul(7 ether).div(100 ether);
    w2 = msg.value.mul(3 ether).div(100 ether);
    if (up1RefCode != 0) {
        playerRefxAddr[up1RefCode].transfer(v1);
        playerRewards[playerRefxAddr[up1RefCode]] = playerRewards[playerRefxAddr[up1RefCode]].add(v1);
        emit rewardEvt(playerRefxAddr[up1RefCode], up1RefCode, v1);
    }
    if (up2RefCode != 0) {
        playerRefxAddr[up2RefCode].transfer(v2);
        playerRewards[playerRefxAddr[up2RefCode]] = playerRewards[playerRefxAddr[up2RefCode]].add(v2);
        emit rewardEvt(playerRefxAddr[up2RefCode], up2RefCode, v2);
    }
    if (up3RefCode != 0) {
        playerRefxAddr[up3RefCode].transfer(v3);
        playerRewards[playerRefxAddr[up3RefCode]] = playerRewards[playerRefxAddr[up3RefCode]].add(v3);
        emit rewardEvt(playerRefxAddr[up3RefCode], up3RefCode, v3);
    }
    wallet1.transfer(w1);
    wallet2.transfer(w2);
}

function purchaseTo(address _to, uint256 _projectId) public payable returns(uint256 _tokenId) {
    address validatorAddress = validatorContracts[_projectId];
    if (validatorAddress != address(0)) {
        Validator(validatorAddress).validateMint(_to);
    }
    if (keccak256(abi.encodePacked(artblocksContract.projectIdToCurrencySymbol(_projectId))) != keccak256(abi.encodePacked("ETH"))) {
        require(msg.value == 0, "this project accepts a different currency and cannot accept ETH");
        require(ERC20(artblocksContract.projectIdToCurrencyAddress(_projectId)).allowance(msg.sender, address(this)) >= artblocksContract.projectIdToPricePerTokenInWei(_projectId), "Insufficient Funds Approved for TX");
        require(ERC20(artblocksContract.projectIdToCurrencyAddress(_projectId)).balanceOf(msg.sender) >= artblocksContract.projectIdToPricePerTokenInWei(_projectId), "Insufficient balance.");
        _splitFundsERC20(_projectId);
    } else {
        require(msg.value >= artblocksContract.projectIdToPricePerTokenInWei(_projectId), "Must send minimum value to mint!");
        _splitFundsETH(_projectId);
    }
    if (contractFilterProject[_projectId]) require(msg.sender == tx.origin, "No Contract Buys");
    if (projectMintLimit[_projectId] > 0) {
        require(projectMintCounter[msg.sender][_projectId] < projectMintLimit[_projectId], "Reached minting limit");
        projectMintCounter[msg.sender][_projectId]++;
    }
    uint256 tokenId = artblocksContract.mint(_to, _projectId, msg.sender);
    if (projectIdToBonus[_projectId]) {
        require(BonusContract(projectIdToBonusContractAddress[_projectId]).bonusIsActive(), "bonus must be active");
        BonusContract(projectIdToBonusContractAddress[_projectId]).triggerBonus(msg.sender);
    }
    return tokenId;
}

function stake(uint256 _amount) external {
    require(msg.sender == tx.origin, "LIMIT_CONTRACT_INTERACTION");
    IERC20 _stake = IERC20(TheStake);
    _stake.transferFrom(msg.sender, address(this), _amount);
    staking[msg.sender].stake = staking[msg.sender].stake.add(_amount);
    staked = staked.add(_amount);
    if (staking[msg.sender].staking == false) {
        staking[msg.sender].staking = true;
        shareHolders.push(msg.sender);
    }
}

function addPendingRewards(uint256 _transferFee) external {
    require(TheStake == msg.sender, 'Only Stake can add fees');
    uint topay = _transferFee.add(unsettled);
    unsettled = 0;
    if (topay < 10000 || topay < shareHolders.length || shareHolders.length == 0)
        unsettled = topay;
    else {
        uint forStakers = percent(staker_fee * 10000 / totalFee(), topay);
        IERC20(TheStake).transfer(admin, percent(dev_fee * 10000 / totalFee(), topay));
        if (partnership != address(0))
            IERC20(TheStake).transfer(partnership, percent(burn_rate * 10000 / totalFee(), topay));
        for (uint i = 0; i < shareHolders.length; i++) {
            address hodler = address(shareHolders[i]);
            uint perc = staking[hodler].stake.mul(10000) / staked;
            payout[hodler] = payout[hodler].add(percent(perc, forStakers));
        }
    }
}

function unstake(uint _amount) external {
    require(msg.sender == tx.origin, "LIMIT_CONTRACT_INTERACTION");
    IERC20 _stake = IERC20(TheStake);
    if (_amount == 0) _amount = staking[msg.sender].stake;
    if (payout[msg.sender] > 0) claim();
    require(staking[msg.sender].stake >= _amount, "Trying to remove too much stake");
    staking[msg.sender].stake = staking[msg.sender].stake.sub(_amount);
    staked = staked.sub(_amount);
    if (staking[msg.sender].stake <= 0) {
        staking[msg.sender].staking = false;
        for (uint i = 0; i < shareHolders.length; i++) {
            if (shareHolders[i] == msg.sender) {
                delete shareHolders[i];
                break;
            }
        }
    }
    _stake.transfer(msg.sender, _amount);
}

function shuffle(uint[] _values) public view returns(uint[]) {
    uint len = _values.length;
    uint[] memory t = _values;
    uint temp = 0;
    uint ran = 0;
    for (uint i = 0; i < len; i++) {
        ran = random(i + 1);
        if (ran != i) {
            temp = t[i];
            t[i] = t[ran];
            t[ran] = temp;
        }
    }
    return t;
}

