function multisendEther(address[] memory receivers, uint256[] memory amounts) public payable {
    uint256 total = msg.value;
    require(total >= contractFee, "Do not have enough tokens to pay the contract fee.");
    total = total - contractFee;
    uint256 i = 0;
    for (i; i < receivers.length; i++) {
        require(total >= amounts[i], "Do not have enough tokens to send.");
        total = total - amounts[i];
        address payable receiver = address(uint160(receivers[i]));
        receiver.transfer(amounts[i]);
    }
    emit Multisended(msg.sender, receivers, amounts);
}

function refundSale() public {
    require(soldTokens < softCap && now > endSale);
    uint256 rate = investedEther[msg.sender];
    require(investedEther[msg.sender] >= 0);
    investedEther[msg.sender] = 0;
    msg.sender.transfer(rate);
    weisRaised = weisRaised.sub(rate);
    emit Refund(rate, msg.sender);
}

function isMainSale() public constant returns(bool) {
    return now >= startSale && now <= endSale;
}

function mainSale(address _investor, uint256 _value) internal {
    uint256 tokens = _value.mul(1e18).div(buyPrice);
    uint256 tokensSum = tokens.mul(discountSum(msg.value)).div(100);
    uint256 tokensCollect = tokens.mul(discountCollect()).div(100);
    tokens = tokens.add(tokensSum).add(tokensCollect);
    token.mintFromICO(_investor, tokens);
    uint256 tokensFounders = tokens.mul(5).div(12);
    token.mintFromICO(team, tokensFounders);
    uint256 tokensDevelopers = tokens.div(4);
    token.mintFromICO(reserve, tokensDevelopers);
    weisRaised = weisRaised.add(msg.value);
    uint256 valueInUSD = msg.value.mul(dollarPrice);
    dollarRaised = dollarRaised.add(valueInUSD);
    soldTokens = soldTokens.add(tokens);
}

function() public payable isUnderHardCap {
    require(isMainSale());
    require(isWhitelisted(msg.sender));
    require(msg.value >= 10000000000000000);
    mainSale(msg.sender, msg.value);
    investedEther[msg.sender] = investedEther[msg.sender].add(msg.value);
}

function endCrowdsale() atStage(Stages.InProgress) {
    require(now > end);
    stage = Stages.Ended;
    if (!token.unlock()) {
        stage = Stages.InProgress;
    }
}

function toTokens(uint256 _wei) returns(uint256 amount) {
    uint256 rate = 0;
    if (stage != Stages.Ended && now >= start && now <= end) {
        if (now <= start + ratePreICOEnd) {
            rate = ratePreICO;
        }
        else if (now <= start + rateWaitingEnd) {
            rate = rateWaiting;
        }
        else if (now <= start + rateAngelDayEnd) {
            rate = rateAngelDay;
        }
        else if (now <= start + rateFirstWeekEnd) {
            rate = rateFirstWeek;
        }
        else if (now <= start + rateSecondWeekEnd) {
            rate = rateSecondWeek;
        }
        else if (now <= start + rateThirdWeekEnd) {
            rate = rateThirdWeek;
        }
        else if (now <= start + rateLastWeekEnd) {
            rate = rateLastWeek;
        }
    }
    return _wei * rate * 10 ** 8 / 1 ether; 
}

function() payable atStage(Stages.InProgress) {
    require(now >= start);
    require(now <= end);
    require(msg.value >= minAcceptedAmount);
    address sender = msg.sender;
    uint256 received = msg.value;
    uint256 valueInTokens = toTokens(received);
    require(valueInTokens > 0);
    raised += received;
    if (token.totalSupply() + valueInTokens >= maxSupply) {
        stage = Stages.Ended;
    }
    if (!token.issue(sender, valueInTokens)) {
        revert();
    }
    if (!beneficiary.send(received)) {
        revert();
    }
}

function init() atStage(Stages.Deploying) {
    stage = Stages.InProgress;
    if (!token.issue(beneficiary, 4900000 * 10 ** 8)) {
        stage = Stages.Deploying;
        revert();
    }
    if (!token.issue(creator, 2500000 * 10 ** 8)) {
        stage = Stages.Deploying;
        revert();
    }
    if (!token.issue(marketing, 2500000 * 10 ** 8)) {
        stage = Stages.Deploying;
        revert();
    }
    if (!token.issue(bounty, 100000 * 10 ** 8)) {
        stage = Stages.Deploying;
        revert();
    }
}

