    uint256 ValueLeft = DoDev(MyItem.Price);
    uint256 Excess = sub(msg.value, MyItem.Price);
    if (Excess > 0) {
        msg.sender.transfer(Excess); 
    }
    address target = MyItem.Owner;
    if (target == 0x0) {
        target = owner;
