    target.transfer(ValueLeft);
    MyItem.Price = mul(MyItem.Price, (uint256(PriceIncrease) + uint256(10000))) / 10000; 
    MyItem.Owner = msg.sender;
    emit ItemBought(msg.sender, id, MyItem.Price);
}

