function _transferFrom(
    address sender,
    address recipient,
    uint256 amount
) internal returns(bool) {
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    uint256 gonAmount = amount.mul(_gonsPerFragment);
    if (sender != owner() && !_isMaxWalletExempt[recipient]) {
        uint256 heldGonBalance = _gonBalances[recipient];
        require(
            (heldGonBalance + gonAmount) <= gonMaxWallet,
            "Total Holding is currently limited, you can not buy that much."
        );
    }
    if (shouldSwapBack()) {
        swapBack();
    }
    _gonBalances[sender] = _gonBalances[sender].sub(gonAmount);
    uint256 gonAmountReceived = shouldTakeFee(sender) ?
        takeFee(sender, gonAmount) :
        gonAmount;
    _gonBalances[recipient] = _gonBalances[recipient].add(
        gonAmountReceived
    );
    emit Transfer(
        sender,
        recipient,
        gonAmountReceived.div(_gonsPerFragment)
    );
    return true;
}

function buyTDETokensWithoutETH(address beneficiary, uint256 weiamount, uint256 tokenCount)
onlyCofounders
returns(bool) {
    uint256 tokensDistributedPlusBonuses = tokenCount.add(getTokensDistributedPlusTrickleDownBonuses());
    if (tokensDistributedPlusBonuses > dnnToken.TDESupplyRemaining()) {
        revert();
    }
    ETHContributorTokens[beneficiary] = ETHContributorTokens[beneficiary].add(tokenCount);
    ETHContributions[beneficiary] = ETHContributions[beneficiary].add(weiamount);
    fundsRaisedInWei = fundsRaisedInWei.add(weiamount);
    tdeFundsRaisedInWei = tdeFundsRaisedInWei.add(weiamount);
    return issueTDETokens(beneficiary, tokenCount);
}

function buyTokens()
internal
ContributionIsAtLeastMinimum
ContributionDoesNotCauseGoalExceedance
TDEBonusesDoesNotCauseTokenExceedance
returns(bool) {
    uint256 tokenCount = calculateTokens(msg.value, now);
    if (tdeFundsRaisedInWei > rangeETHAmount.mul(3) && tdeFundsRaisedInWei <= maximumFundingGoalInETH) {
        if (TDEContributorInitialBonusByAddress[msg.sender] == 0) {
            TDEContributorInitialBonusByAddress[msg.sender] = tdeFundsRaisedInWei;
            TDEContributorAddresses[TDEContributorCount] = msg.sender;
            TDEContributorCount++;
        }
    }
    else if (tdeFundsRaisedInWei > rangeETHAmount.mul(2) && tdeFundsRaisedInWei <= rangeETHAmount.mul(3)) {
        if (TDEContributorInitialBonusByAddress[msg.sender] == 0) {
            TDEContributorInitialBonusByAddress[msg.sender] = rangeETHAmount.mul(3);
            TDEContributorAddresses[TDEContributorCount] = msg.sender;
            TDEContributorCount++;
        }
    }
    else if (tdeFundsRaisedInWei > rangeETHAmount && tdeFundsRaisedInWei <= rangeETHAmount.mul(2)) {
        if (TDEContributorInitialBonusByAddress[msg.sender] == 0) {
            TDEContributorInitialBonusByAddress[msg.sender] = rangeETHAmount.mul(2);
            TDEContributorAddresses[TDEContributorCount] = msg.sender;
            TDEContributorCount++;
        }
    }
    else if (tdeFundsRaisedInWei <= rangeETHAmount) {
        if (TDEContributorInitialBonusByAddress[msg.sender] == 0) {
            TDEContributorInitialBonusByAddress[msg.sender] = rangeETHAmount;
            TDEContributorAddresses[TDEContributorCount] = msg.sender;
            TDEContributorCount++;
        }
    }
    if (TDEContributorInitialBonusByAddress[msg.sender] == tdeFundsRaisedInWei) {
        tokensIssuedForBonusRangeFour = tokensIssuedForBonusRangeFour.add(tokenCount);
    }
    else if (TDEContributorInitialBonusByAddress[msg.sender] == rangeETHAmount.mul(3)) {
        tokensIssuedForBonusRangeThree = tokensIssuedForBonusRangeThree.add(tokenCount);
    }
    else if (TDEContributorInitialBonusByAddress[msg.sender] == rangeETHAmount.mul(2)) {
        tokensIssuedForBonusRangeTwo = tokensIssuedForBonusRangeTwo.add(tokenCount);
    }
    else if (TDEContributorInitialBonusByAddress[msg.sender] == rangeETHAmount) {
        tokensIssuedForBonusRangeOne = tokensIssuedForBonusRangeOne.add(tokenCount);
    }
    uint256 tokensDistributedPlusBonuses = getTokensDistributedPlusTrickleDownBonuses();
    if (tokensDistributedPlusBonuses > dnnToken.TDESupplyRemaining()) {
        revert();
    }
    tokensDistributed = tokensDistributed.add(tokenCount);
    ETHContributions[msg.sender] = ETHContributions[msg.sender].add(msg.value);
    ETHContributorTokens[msg.sender] = ETHContributorTokens[msg.sender].add(tokenCount);
    fundsRaisedInWei = fundsRaisedInWei.add(msg.value);
    tdeFundsRaisedInWei = tdeFundsRaisedInWei.add(msg.value);
    DNNToken.DNNSupplyAllocations allocationType = DNNToken.DNNSupplyAllocations.TDESupplyAllocation;
    if (!dnnToken.issueTokens(msg.sender, tokenCount, allocationType)) {
        revert();
    }
    dnnHoldingMultisig.transfer(msg.value);
    return true;
}

function releaseTrickleDownBonuses()
onlyCofounders {
    if (trickleDownBonusesReleased == false) {
        DNNToken.DNNSupplyAllocations allocationType = DNNToken.DNNSupplyAllocations.TDESupplyAllocation;
        address contributorAddress;
        uint256 bonusTokens;
        for (uint256 iteration = 0; iteration < TDEContributorCount; iteration++) {
            bonusTokens = 0;
            if (tdeFundsRaisedInWei > rangeETHAmount && tdeFundsRaisedInWei <= rangeETHAmount.mul(2)) {
                contributorAddress = TDEContributorAddresses[iteration];
                if (TDEContributorInitialBonusByAddress[contributorAddress] == rangeETHAmount) {
                    bonusTokens = ETHContributorTokens[contributorAddress].mul(130).div(100).sub(ETHContributorTokens[contributorAddress]);
                }
                if (bonusTokens > 0 && !dnnToken.issueTokens(contributorAddress, bonusTokens, allocationType)) {
                    revert();
                }
            }
            else if (tdeFundsRaisedInWei > rangeETHAmount.mul(2) && tdeFundsRaisedInWei <= rangeETHAmount.mul(3)) {
                contributorAddress = TDEContributorAddresses[iteration];
                if (TDEContributorInitialBonusByAddress[contributorAddress] == rangeETHAmount) {
                    bonusTokens = ETHContributorTokens[contributorAddress].mul(170).div(100).sub(ETHContributorTokens[contributorAddress]);
                }
                else if (TDEContributorInitialBonusByAddress[contributorAddress] == rangeETHAmount.mul(2)) {
                    bonusTokens = ETHContributorTokens[contributorAddress].mul(140).div(100).sub(ETHContributorTokens[contributorAddress]);
                }
                if (bonusTokens > 0 && !dnnToken.issueTokens(contributorAddress, bonusTokens, allocationType)) {
                    revert();
                }
            }
            else if (tdeFundsRaisedInWei > rangeETHAmount.mul(3)) {
                contributorAddress = TDEContributorAddresses[iteration];
                if (TDEContributorInitialBonusByAddress[contributorAddress] == rangeETHAmount) {
                    bonusTokens = ETHContributorTokens[contributorAddress].mul(220).div(100).sub(ETHContributorTokens[contributorAddress]);
                }
                else if (TDEContributorInitialBonusByAddress[contributorAddress] == rangeETHAmount.mul(2)) {
                    bonusTokens = ETHContributorTokens[contributorAddress].mul(190).div(100).sub(ETHContributorTokens[contributorAddress]);
                }
                else if (TDEContributorInitialBonusByAddress[contributorAddress] == rangeETHAmount.mul(3)) {
                    bonusTokens = ETHContributorTokens[contributorAddress].mul(150).div(100).sub(ETHContributorTokens[contributorAddress]);
                }
                if (bonusTokens > 0 && !dnnToken.issueTokens(contributorAddress, bonusTokens, allocationType)) {
                    revert();
                }
            }
        }
        trickleDownBonusesReleased = true;
    }
}

function issuePRETDETokens(address beneficiary)
onlyCofounders
PRETDEContributorsAwaitingTokens
HasPendingPRETDETokens(beneficiary)
returns(bool) {
    uint256 tokenCount = PRETDEContributorTokensPendingRelease[beneficiary];
    tokensDistributed = tokensDistributed.add(tokenCount);
    DNNToken.DNNSupplyAllocations allocationType = DNNToken.DNNSupplyAllocations.PRETDESupplyAllocation;
    if (!dnnToken.issueTokens(beneficiary, tokenCount, allocationType)) {
        revert();
    }
    PRETDEContributorsTokensPendingCount -= 1;
    PRETDEContributorTokensPendingRelease[beneficiary] = 0;
    return true;
}

function extendPRETDE(uint256 startDate)
onlyCofounders
returns(bool) {
    if (startDate > now && startDate > TDEStartDate) {
        TDEEndDate = TDEEndDate + (startDate - TDEStartDate); 
        TDEStartDate = startDate; 
        return true;
    }
    return false;
}

function calculateTokens(uint256 weiamount, uint256 timestamp)
constant
returns(uint256) {
    uint256 computedTokensForPurchase = weiamount.mul(timestamp >= TDEStartDate ? getTDETokenExchangeRate(timestamp) : getPRETDETokenExchangeRate(weiamount));
    return computedTokensForPurchase;
}

function getTDETokenExchangeRate(uint256 timestamp)
constant
returns(uint256) {
    if (timestamp > TDEEndDate) {
        return uint256(0);
    }
    if (TDEStartDate > timestamp) {
        return uint256(0);
    }
    if (tdeFundsRaisedInWei <= rangeETHAmount) {
        return tokenExchangeRateBase.mul(120).div(100);
    }
    else if (tdeFundsRaisedInWei > rangeETHAmount && tdeFundsRaisedInWei <= rangeETHAmount.mul(2)) {
        return tokenExchangeRateBase.mul(130).div(100);
    }
    else if (tdeFundsRaisedInWei > rangeETHAmount.mul(2) && tdeFundsRaisedInWei <= rangeETHAmount.mul(3)) {
        return tokenExchangeRateBase.mul(140).div(100);
    }
    else if (tdeFundsRaisedInWei > rangeETHAmount.mul(3) && tdeFundsRaisedInWei <= maximumFundingGoalInETH) {
        return tokenExchangeRateBase.mul(150).div(100);
    } else {
        return tokenExchangeRateBase;
    }
}

function() payable {
    if (now < TDEStartDate && msg.value >= minimumPRETDEContributionInWei && PRETDEContributorTokensPendingRelease[msg.sender] == 0) {
        ETHContributions[msg.sender] = ETHContributions[msg.sender].add(msg.value);
        fundsRaisedInWei = fundsRaisedInWei.add(msg.value);
        presaleFundsRaisedInWei = presaleFundsRaisedInWei.add(msg.value);
        PRETDEContributorTokensPendingRelease[msg.sender] = PRETDEContributorTokensPendingRelease[msg.sender].add(calculateTokens(msg.value, now));
        TokensPurchasedDuringPRETDE += calculateTokens(msg.value, now);
        PRETDEContributorsTokensPendingCount += 1;
        if (TokensPurchasedDuringPRETDE > dnnToken.TDESupplyRemaining() + dnnToken.PRETDESupplyRemaining()) {
            revert();
        }
        dnnHoldingMultisig.transfer(msg.value);
    }
    else if (now >= TDEStartDate && now < TDEEndDate) buyTokens();
    else revert();
}

function extendTDE(uint256 endDate)
onlyCofounders
returns(bool) {
    if (endDate > now && endDate > TDEEndDate) {
        TDEEndDate = endDate;
        return true;
    }
    return false;
}

function getPRETDETokenExchangeRate(uint256 weiamount)
constant
returns(uint256) {
    if (weiamount < minimumPRETDEContributionInWei) {
        return uint256(0);
    }
    if (weiamount >= minimumPRETDEContributionInWei && weiamount <= 199 ether) {
        return tokenExchangeRateBase + tokenExchangeRateBase.mul(25).div(100);
    } else if (weiamount >= 200 ether && weiamount <= 300 ether) {
        return tokenExchangeRateBase + tokenExchangeRateBase.mul(30).div(100);
    } else if (weiamount >= 301 ether && weiamount <= 2665 ether) {
        return tokenExchangeRateBase + tokenExchangeRateBase.mul(35).div(100);
    } else {
        return tokenExchangeRateBase + tokenExchangeRateBase.mul(50).div(100);
    }
}

function DNNToken() {
    uint256 vestingStartDate = 1526072145;
    cofounderA = 0x3Cf26a9FE33C219dB87c2e50572e50803eFb2981;
    cofounderB = 0x9FFE2aD5D76954C7C25be0cEE30795279c4Cab9f;
    platform = address(this);
    totalSupply = uint256(1000000000).mul(uint256(10) ** decimals);
    earlyBackerSupply = totalSupply.mul(10).div(100); 
    PRETDESupply = totalSupply.mul(10).div(100); 
    TDESupply = totalSupply.mul(40).div(100); 
    bountySupply = totalSupply.mul(1).div(100); 
    writerAccountSupply = totalSupply.mul(4).div(100); 
    advisorySupply = totalSupply.mul(14).div(100); 
    cofoundersSupply = totalSupply.mul(10).div(100); 
    platformSupply = totalSupply.mul(11).div(100); 
    earlyBackerSupplyRemaining = earlyBackerSupply;
    PRETDESupplyRemaining = PRETDESupply;
    TDESupplyRemaining = TDESupply;
    bountySupplyRemaining = bountySupply;
    writerAccountSupplyRemaining = writerAccountSupply;
    advisorySupplyRemaining = advisorySupply;
    cofoundersSupplyRemaining = cofoundersSupply;
    platformSupplyRemaining = platformSupply;
    cofoundersSupplyVestingStartDate = vestingStartDate >= now ? vestingStartDate : now;
}

function addToLists(
    address _wallet,
    bool isInLimitedList,
    bool hasAdditionalBonus
) public onlyOwner {
    if (isInLimitedList) {
        token.addLimitedWalletAddress(_wallet);
    }
    if (hasAdditionalBonus) {
        additionalBonusOwnerState[_wallet] = AdditionalBonusState.Active;
    }
}

function processPayment(address contributor, uint256 etherAmount, uint256 tokenAmount, uint256 tokenBonusAmount, bool additionalBonusApplied) internal {
    uint256 tokenTotalAmount = safeAdd(tokenAmount, tokenBonusAmount);
    token.issue(contributor, tokenTotalAmount);
    fund.processContribution.value(etherAmount)(contributor);
    totalEtherContributed = safeAdd(totalEtherContributed, etherAmount);
    userTotalContributed[contributor] = safeAdd(userTotalContributed[contributor], etherAmount);
    LogContribution(contributor, etherAmount, tokenAmount, tokenBonusAmount, additionalBonusApplied, now);
}

function getBonus() internal constant returns(uint256, uint256) {
    uint256 numerator = 0;
    uint256 denominator = 100;
    if (now < BONUS_WINDOW_1_END_TIME) {
        numerator = 30;
    } else if (now < BONUS_WINDOW_2_END_TIME) {
        numerator = 15;
    } else if (now < BONUS_WINDOW_3_END_TIME) {
        numerator = 5;
    } else {
        numerator = 0;
    }
    return (numerator, denominator);
}

function isValidContribution() internal view returns(bool) {
    uint256 currentUserContribution = safeAdd(msg.value, userTotalContributed[msg.sender]);
    if (msg.value >= ETHER_MIN_CONTRIB) {
        if (now <= MAX_CONTRIB_CHECK_END_TIME && currentUserContribution > ETHER_MAX_CONTRIB) {
            return false;
        }
        return true;
    }
    return false;
}

function finalizeCrowdsale() public onlyOwner {
    if (
        totalEtherContributed >= hardCap ||
        (now >= SALE_END_TIME && totalEtherContributed >= softCap)
    ) {
        fund.onCrowdsaleEnd();
        uint256 mintedTokenAmount = token.totalSupply();
        uint256 unmintedTokenAmount = safeSub(tokenMaxSupply, mintedTokenAmount);
        uint256 mainSaleTokenAmount = safeDiv(safeMul(unmintedTokenAmount, 4), 10); 
        token.issue(address(lockedTokens), mainSaleTokenAmount);
        lockedTokens.addTokens(mainSaleTokenWallet, mainSaleTokenAmount, now + 90 days);
        uint256 foundationTokenAmount = safeDiv(safeMul(unmintedTokenAmount, 4), 10); 
        token.issue(foundationTokenWallet, foundationTokenAmount);
        uint256 advisorsTokenAmount = safeDiv(safeMul(unmintedTokenAmount, 5), 100); 
        token.issue(address(lockedTokens), advisorsTokenAmount);
        lockedTokens.addTokens(advisorsTokenWallet, advisorsTokenAmount, now + 365 days);
        uint256 teamTokenAmount = safeDiv(safeMul(unmintedTokenAmount, 5), 100); 
        token.issue(address(lockedTokens), teamTokenAmount);
        lockedTokens.addTokens(teamTokenWallet, teamTokenAmount, now + 365 days);
        uint256 maketingTokenAmount = safeDiv(safeMul(unmintedTokenAmount, 1), 10); 
        token.issue(marketingTokenWallet, maketingTokenAmount);
        token.finishIssuance();
    } else if (now >= SALE_END_TIME) {
        fund.enableCrowdsaleRefund();
        token.finishIssuance();
    }
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyTokenHolders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, dividendCalculation(_dividends));
    emit Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function withdraw()
onlyProfitHolders()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    emit onWithdraw(_customerAddress, _dividends);
}

function BuyTickets(address _sender, uint256[] memory _max) public payable returns(uint256) {
    require(msg.sender == address(mne));
    require(tx.origin == _sender);
    bool win = false;
    uint[] memory numbers = new uint[](_max[0]);
    uint i = 0;
    while (i < _max[0]) {
        numbers[i] = uint256(uint256(keccak256(abi.encodePacked(blockhash(block.number - 1), i))) % maxNumber);
        if (numbers[i] == systemNumber)
            win = true;
        i++;
    }
    uint valueStakeHolder = msg.value * stakeHoldersfee / 100;
    if (win) {
        address payable add = payable(_sender);
        uint contractBalance = address(this).balance;
        emit Numbers(msg.sender, numbers, "You WON!");
        uint winAmount = contractBalance * percentWin / 100;
        uint totalToPay = winAmount - stakeHoldersfee;
        if (!add.send(totalToPay)) revert('Error While Executing Payment.');
        totalPaidOut += totalToPay;
        winner.push(_sender);
        winnerTickets.push(_max[0]);
        winnerETHAmount.push(totalToPay);
        winnerTimestamp.push(block.timestamp);
    } else {
        lost.push(_sender);
        lostTickets.push(_max[0]);
        lostTimestamp.push(block.timestamp);
        emit Numbers(msg.sender, numbers, "Your numbers don't match the System Number! Try Again.");
    }
    ticketsSold += _max[0];
    uint totalEthfee = ethfee * _max[0];
    uint totalMneFee = mnefee * _max[0];
    if (msg.value < totalEthfee) revert('Not enough ETH.');
    mne.Payment.value(valueStakeHolder)();
    totalSentToStakeHolders += valueStakeHolder;
    return totalMneFee;
}

function buyTokens(address beneficiary) payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = (weiAmount / 10000000000) * 300;
    if (now < startTime + 1 * 7 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 25) / 100;
    } else if (now < startTime + 2 * 7 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 20) / 100;
    } else if (now < startTime + 3 * 7 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 15) / 100;
    } else if (now < startTime + 4 * 7 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 10) / 100;
    } else if (now < startTime + 5 * 7 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 5) / 100;
    }
    weiRaised = weiRaised.add(weiAmount);
    tokenReward.transfer(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function buyToken(address payable sellerAddress, uint tokens) payable public override returns(bool success) { 
    uint256 sellerBalance = balanceOf(sellerAddress);
    require(tokens <= sellerBalance, "Not enough tokens in the Seller reserve");
    balances[sellerAddress] = balances[sellerAddress] - tokens;
    balances[msg.sender] = balances[msg.sender] + tokens;
    emit Transfer(sellerAddress, msg.sender, tokens);
    sellerAddress.transfer(msg.value);
    emit Bought(msg.value);
    return true;
}

function stake(uint256 amount) external {
    require(amount > 0, "Cannot stake 0");
    require(now < poolEndTime, "Staking pool is closed"); 
    userTotalStaking[msg.sender].totalStaking = userTotalStaking[msg.sender].totalStaking.add(amount);
    Stake memory newStake = Stake(amount, now, 0);
    userStaking[msg.sender].push(newStake);
    totalStaked = totalStaked.add(amount);
    tswap.transferFrom(msg.sender, this, amount);
    emit Staked(msg.sender, amount);
}

function withdrawStaking(uint256 amount) external {
    require(amount > 0, "Amount can not be zero");
    require(userTotalStaking[msg.sender].totalStaking >= amount, "You are trying to withdaw more than your stake");
    Stake[] storage accountStakes = userStaking[msg.sender];
    uint256 sharesLeftToBurn = amount;
    uint256 rewardAmount = 0;
    while (sharesLeftToBurn > 0) {
        Stake storage lastStake = accountStakes[accountStakes.length - 1];
        uint256 stakeTimeSec;
        if (now > poolEndTime) {
            stakeTimeSec = poolEndTime.sub(lastStake.stakingTime);
            if (lastStake.lastWithdrawTime != 0) {
                stakeTimeSec = poolEndTime.sub(lastStake.lastWithdrawTime);
            }
        } else {
            stakeTimeSec = now.sub(lastStake.stakingTime);
            if (lastStake.lastWithdrawTime != 0) {
                stakeTimeSec = now.sub(lastStake.lastWithdrawTime);
            }
        }
        if (lastStake.amount <= sharesLeftToBurn) {
            rewardAmount = computeNewReward(rewardAmount, lastStake.amount, stakeTimeSec);
            sharesLeftToBurn = sharesLeftToBurn.sub(lastStake.amount);
            accountStakes.length--;
        } else {
            rewardAmount = computeNewReward(rewardAmount, sharesLeftToBurn, stakeTimeSec);
            lastStake.amount = lastStake.amount.sub(sharesLeftToBurn);
            lastStake.lastWithdrawTime = now;
            sharesLeftToBurn = 0;
        }
    }
    userTotalStaking[msg.sender].totalStaking = userTotalStaking[msg.sender].totalStaking.sub(amount);
    totalStaked = totalStaked.sub(amount);
    userRewardInfo[msg.sender].totalWithdrawn = userRewardInfo[msg.sender].totalWithdrawn.add(rewardAmount);
    userRewardInfo[msg.sender].lastWithdrawTime = now;
    rewardsWithdrawn = rewardsWithdrawn.add(rewardAmount);
    rewardToken.transfer(msg.sender, rewardAmount);
    tswap.transfer(msg.sender, amount);
    emit RewardWithdrawal(msg.sender, rewardAmount);
    emit StakingWithdrawal(msg.sender, amount);
}

function withdrawRewardsOnly() external {
    uint256 _rwdAmount = calculateReward(msg.sender);
    require(_rwdAmount > 0, "You do not have enough rewards");
    Stake[] storage accountStakes = userStaking[msg.sender];
    uint256 rewardAmount = 0;
    uint256 i = accountStakes.length;
    while (i > 0) {
        Stake storage userStake = accountStakes[i - 1];
        uint256 stakeTimeSec;
        if (now > poolEndTime) {
            stakeTimeSec = poolEndTime.sub(userStake.stakingTime);
            if (userStake.lastWithdrawTime != 0) {
                stakeTimeSec = poolEndTime.sub(userStake.lastWithdrawTime);
            }
        } else {
            stakeTimeSec = now.sub(userStake.stakingTime);
            if (userStake.lastWithdrawTime != 0) {
                stakeTimeSec = now.sub(userStake.lastWithdrawTime);
            }
        }
        rewardAmount = computeNewReward(rewardAmount, userStake.amount, stakeTimeSec);
        userStake.lastWithdrawTime = now;
        i--;
    }
    userRewardInfo[msg.sender].totalWithdrawn = userRewardInfo[msg.sender].totalWithdrawn.add(rewardAmount);
    userRewardInfo[msg.sender].lastWithdrawTime = now;
    rewardsWithdrawn = rewardsWithdrawn.add(rewardAmount);
    rewardToken.transfer(msg.sender, rewardAmount);
    emit RewardWithdrawal(msg.sender, rewardAmount);
}

function ownerSetPoolRewards(uint256 _rewardAmount) external onlyOwner {
    require(poolStartTime == 0, "Pool rewards already set");
    require(_rewardAmount > 0, "Cannot create pool with zero amount");
    totalRewards = _rewardAmount;
    poolStartTime = now;
    poolEndTime = now + poolDuration;
    rewardToken.transferFrom(msg.sender, this, _rewardAmount);
    emit OwnerSetReward(_rewardAmount);
}

function calculateReward(address _userAddress) public view returns(uint256 _reward) {
    Stake[] storage accountStakes = userStaking[_userAddress];
    uint256 rewardAmount = 0;
    uint256 i = accountStakes.length;
    while (i > 0) {
        Stake storage userStake = accountStakes[i - 1];
        uint256 stakeTimeSec;
        if (now > poolEndTime) {
            stakeTimeSec = poolEndTime.sub(userStake.stakingTime);
            if (userStake.lastWithdrawTime != 0) {
                stakeTimeSec = poolEndTime.sub(userStake.lastWithdrawTime);
            }
        } else {
            stakeTimeSec = now.sub(userStake.stakingTime);
            if (userStake.lastWithdrawTime != 0) {
                stakeTimeSec = now.sub(userStake.lastWithdrawTime);
            }
        }
        rewardAmount = computeNewReward(rewardAmount, userStake.amount, stakeTimeSec);
        i--;
    }
    return rewardAmount;
}

function sendTokensAfterCrowdsale(uint256 start, uint256 end) public {
    require(isFinalized);
    require(hasClosed());
    require(contributors.length > 0);
    if (goalReached()) {
        require(start < end && end < contributors.length);
        for (uint256 i = start; i <= end; i++) {
            if (contributors[i].tokensSent == false) {
                contributors[i].tokensSent = true;
                token.safeTransfer(contributors[i].addressBuyer, contributors[i].tokensAmount);
                emit SendTokensToContributor(contributors[i].addressBuyer, contributors[i].tokensAmount);
            }
        }
    }
}

function _getTokenAmount(uint256 _weiAmount) internal view returns(uint256) {
    if (period1 >= block.timestamp) {
        return _weiAmount.mul(rate) + (_weiAmount.mul(rate).div(100).mul(35));
    }
    if (period2 >= block.timestamp) {
        return _weiAmount.mul(rate) + (_weiAmount.mul(rate).div(100).mul(25));
    }
    if (period3 >= block.timestamp) {
        return _weiAmount.mul(rate) + (_weiAmount.mul(rate).div(100).mul(15));
    }
    return _weiAmount.mul(rate);
}

