function buyTokens(uint8 _tier) internal ValidDestination(msg.sender) CheckPurchase returns(bool _success) {
    if (weiRaised.add(msg.value) > FUNDING_ETH_HARD_CAP) {
        revert();
    }
    uint256 contributionInWei = msg.value;
    if (!checkTierCap(_tier, contributionInWei)) {
        revert();
    }
    uint256 rate = getTierTokens(_tier);
    uint256 tokens = contributionInWei.mul(rate);
    if (msg.sender != poolAddress) {
        if (stage == Stages.PreSale) {
            if (!checkAllowedTier(msg.sender, _tier)) {
                revert();
            }
        }
        if (!checkAllowedContribution(msg.sender, contributionInWei, _tier)) {
            revert();
        }
        if (!this.transferFrom(owner, msg.sender, tokens)) {
            revert();
        }
        if (stage == Stages.PreSale) {
            if (_tier == 0) {
                contributors[msg.sender].contributionInWeiTier1 = contributors[msg.sender].contributionInWeiTier1.add(contributionInWei);
            } else if (_tier == 1) {
                contributors[msg.sender].contributionInWeiTier2 = contributors[msg.sender].contributionInWeiTier2.add(contributionInWei);
            } else if (_tier == 2) {
                contributors[msg.sender].contributionInWeiTier3 = contributors[msg.sender].contributionInWeiTier3.add(contributionInWei);
            }
        } else {
            contributors[msg.sender].contributionInWeiPublicSale = contributors[msg.sender].contributionInWeiPublicSale.add(contributionInWei);
        }
    } else {
        if (!checkPoolAddressTierCap(_tier, contributionInWei)) {
            revert();
        }
        if (!this.transferFrom(owner, msg.sender, tokens)) {
            revert();
        }
        pool[poolAddress][_tier].contributionInWei = pool[poolAddress][_tier].contributionInWei.add(contributionInWei);
    }
    weiRaised = weiRaised.add(contributionInWei);
    tokensSent[_tier] = tokensSent[_tier].add(tokens);
    if (weiRaised >= FUNDING_ETH_HARD_CAP) {
        offeringEnded();
    }
    beneficiaryAddress.transfer(address(this).balance);
    emit TokenPurchase(msg.sender, contributionInWei, tokens);
    return true;
}

function getTierTokens(uint8 _tier) internal view returns(uint256 _tokens) {
    uint256 tokens = RATE_TIER1;
    if (_tier == 1) {
        tokens = RATE_TIER2;
    } else if (_tier == 2) {
        tokens = RATE_TIER3;
    } else if (_tier == 3) {
        if (now <= publicSaleDiscountEndTime) {
            tokens = RATE_PUBLIC_SALE;
        } else {
            tokens = RATE;
        }
    }
    return tokens;
}

function getCurrentTier() public view returns(uint8 _tier) {
    uint8 currentTier = 3; 
    if (stage == Stages.PreSale) {
        if (now <= tierEndTime[0]) {
            currentTier = 0;
        } else if (now <= tierEndTime[1]) {
            currentTier = 1;
        } else if (now <= tierEndTime[2]) {
            currentTier = 2;
        }
    } else {
        if (now > endTime) {
            currentTier = 4; 
        }
    }
    return currentTier;
}

function poolMint(bytes32 poolName_) external nonReentrant expectInitialized returns(uint256) {
    Pool storage pool = poolInfo[poolName_];
    require(msg.sender == pool.pool, 'Permission denied');
    _updateTotalAmount();
    uint256 poolTotal = totalMintAmount.mul(pool.weight).div(TOTAL_WEIGHT);
    uint256 amount = poolTotal.sub(pool.minted);
    if (amount > 0) {
        token.mint(msg.sender, amount);
        pool.minted = pool.minted.add(amount);
    }
    return amount;
}

function initialize(
    address private_,
    address stake_,
    uint256 startTimestamp_
) external requireImpl {
    require(!initialized, 'already initialized');
    require(startTimestamp_ >= block.timestamp, '!startTime');
    poolInfo[ConfigNames.PRIVATE] = Pool(private_, 1000, 0);
    poolInfo[ConfigNames.STAKE] = Pool(stake_, 9000, 0);
    initialized = true;
    startTimestamp = startTimestamp_;
    lastTimestamp = startTimestamp_;
}

function preMint() public view returns(uint256) {
    if (block.timestamp <= startTimestamp) {
        return uint256(0);
    }
    if (block.timestamp <= lastTimestamp) {
        return uint256(0);
    }
    uint256 time = block.timestamp.sub(startTimestamp);
    uint256 max_week_time = MAX_WEEK.mul(weekTimestamp);
    if (time > max_week_time) {
        time = max_week_time;
    }
    if (time >= weekTimestamp) {
        uint256 n = time.div(weekTimestamp);
        uint256 an = a1.sub(n.mul(d));
        uint256 otherTimestamp = time.mod(weekTimestamp);
        uint256 other = an.mul(otherTimestamp).div(weekTimestamp);
        uint256 first = n.mul(a1);
        uint256 last = n.mul(n.sub(1)).mul(d).div(2);
        uint256 sn = first.sub(last);
        return other.add(sn).sub(totalMintAmount);
    } else {
        return a1.mul(time).div(weekTimestamp).sub(totalMintAmount);
    }
}

function finalise() onlyOwner {
    require(totalSupply >= TOKENS_SOFT_CAP || now > END_DATE);
    require(!finalised);
    lockedTokens.addRemainingTokens();
    balances[address(lockedTokens)] = balances[address(lockedTokens)].
    add(lockedTokens.totalSupplyLocked());
    totalSupply = totalSupply.add(lockedTokens.totalSupplyLocked());
    finalised = true;
}

function addRemainingTokens() {
    require(msg.sender == address(tokenContract));
    uint remainingTokens = TOKENS_TOTAL;
    remainingTokens = remainingTokens.sub(tokenContract.totalSupply());
    remainingTokens = remainingTokens.sub(totalSupplyLocked1Y);
    remainingTokens = remainingTokens.sub(totalSupplyLocked2Y);
    add1Y(TRANCHE2_ACCOUNT, remainingTokens);
}

function proxyPayment(address participant) payable {
    require(!finalised);
    require(now >= START_DATE);
    require(now <= END_DATE);
    require(msg.value >= CONTRIBUTIONS_MIN);
    require(CONTRIBUTIONS_MAX == 0 || msg.value < CONTRIBUTIONS_MAX);
    uint tokens = msg.value * tokensPerKEther / 10 ** uint(18 - decimals + 3);
    require(totalSupply + tokens <= TOKENS_HARD_CAP);
    balances[participant] = balances[participant].add(tokens);
    totalSupply = totalSupply.add(tokens);
    Transfer(0x0, participant, tokens);
    TokensBought(participant, msg.value, this.balance, tokens,
        totalSupply, tokensPerKEther);
    kycRequired[participant] = true;
    if (!wallet.send(msg.value)) throw;
}

function unlock1Y() {
    require(now >= LOCKED_1Y_DATE);
    uint amount = balancesLocked1Y[msg.sender];
    require(amount > 0);
    balancesLocked1Y[msg.sender] = 0;
    totalSupplyLocked1Y = totalSupplyLocked1Y.sub(amount);
    if (!tokenContract.transfer(msg.sender, amount)) throw;
}

function unlock2Y() {
    require(now >= LOCKED_2Y_DATE);
    uint amount = balancesLocked2Y[msg.sender];
    require(amount > 0);
    balancesLocked2Y[msg.sender] = 0;
    totalSupplyLocked2Y = totalSupplyLocked2Y.sub(amount);
