function addVestTokenAllocation(address beneficiary, uint256 allocationValue)
external
onlyOwnerOrTokenDistributionContract {
    require(totalTokensLocked[beneficiary] == 0 && beneficiary != address(0)); 
    allocatedTokens = allocatedTokens.add(allocationValue);
    require(allocatedTokens <= golix.balanceOf(this));
    totalTokensLocked[beneficiary] = allocationValue;
}

function release() public {
    uint256 unreleased = releasableAmount();
    require(unreleased > 0);
    releasedTokens[msg.sender] = releasedTokens[msg.sender].add(unreleased);
    golix.safeTransfer(msg.sender, unreleased);
    emit Released(msg.sender, unreleased);
}

function VestTokenAllocation(
    ERC20 _token,
    address _tokenDistribution,
    uint256 _start,
    uint256 _cliff,
    uint256 _duration,
    uint256 _canSelfDestruct
)
public {
    require(_token != address(0) && _cliff != 0);
    require(_cliff <= _duration);
    require(_start > now);
    require(_canSelfDestruct > _duration.add(_start));
    duration = _duration;
    cliff = _start.add(_cliff);
    start = _start;
    golix = ERC20(_token);
    tokenDistribution = _tokenDistribution;
    canSelfDestruct = _canSelfDestruct;
}

function vestedAmount() public view returns(uint256) {
    uint256 totalBalance = totalTokensLocked[msg.sender];
    if (now < cliff) {
        return 0;
    } else if (now >= start.add(duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(now.sub(start)).div(duration);
    }
}

function kill() public onlyOwner {
    require(now >= canSelfDestruct);
    uint256 balance = golix.balanceOf(this);
    if (balance > 0) {
        golix.transfer(msg.sender, balance);
    }
    selfdestruct(owner);
}

function refundUnconfirmed() public {
    require(now > endIcoMainSale);
    require(balances[msg.sender] > 0);
    require(token.GetPermissionsList(msg.sender) == 1);
    uint value = balances[msg.sender];
    balances[msg.sender] = 0;
    msg.sender.transfer(value);
    uint uvalue = unconfirmedSumAddr[msg.sender];
    unconfirmedSumAddr[msg.sender] = 0;
    token.burn(msg.sender, uvalue);
}

function SetPermissionsList(address _address, uint8 _sign) public onlyOwner {
    uint8 sign;
    sign = token.GetPermissionsList(_address);
    token.SetPermissionsList(_address, _sign);
    if (_sign == 0) {
        if (sign != _sign) {
            unconfirmedSum = unconfirmedSum.sub(unconfirmedSumAddr[_address]);
            unconfirmedSumAddr[_address] = 0;
        }
    }
}

function procureTokens(address beneficiary) public payable {
    uint256 tokens;
    uint256 weiAmount = msg.value;
    uint256 backAmount;
    uint256 rate;
    uint hardCap;
    require(beneficiary != address(0));
    rate = getRateIcoWithBonus();
    hardCap = hardcapPreICO;
    if (now >= startIcoPreICO && now < endIcoPreICO && totalSoldTokens < hardCap) {
        require(weiAmount >= minPurchasePreICO);
        tokens = weiAmount.mul(rate);
        if (hardCap.sub(totalSoldTokens) < tokens) {
            tokens = hardCap.sub(totalSoldTokens);
            weiAmount = tokens.div(rate);
            backAmount = msg.value.sub(weiAmount);
        }
    }
    hardCap = hardcapMainSale.add(hardcapPreICO);
    if (now >= startIcoMainSale && now < endIcoMainSale && totalSoldTokens < hardCap) {
        tokens = weiAmount.mul(rate);
        if (hardCap.sub(totalSoldTokens) < tokens) {
            tokens = hardCap.sub(totalSoldTokens);
            weiAmount = tokens.div(rate);
            backAmount = msg.value.sub(weiAmount);
        }
    }
    require(tokens > 0);
    totalSoldTokens = totalSoldTokens.add(tokens);
    balances[msg.sender] = balances[msg.sender].add(weiAmount);
    token.mint(msg.sender, tokens);
    unconfirmedSum = unconfirmedSum.add(tokens);
    unconfirmedSumAddr[msg.sender] = unconfirmedSumAddr[msg.sender].add(tokens);
    token.SetPermissionsList(beneficiary, 1);
    if (backAmount > 0) {
        msg.sender.transfer(backAmount);
    }
    emit TokenProcurement(msg.sender, beneficiary, weiAmount, tokens);
}

function refund() public {
    require(totalSoldTokens.sub(unconfirmedSum) < softcap && now > endIcoMainSale);
    require(balances[msg.sender] > 0);
    uint value = balances[msg.sender];
    balances[msg.sender] = 0;
    msg.sender.transfer(value);
}

function transferEthToMultisig() public onlyOwner {
    address _this = this;
    require(totalSoldTokens.sub(unconfirmedSum) >= softcap && now > endIcoMainSale);
    wallet.transfer(_this.balance);
}

function setStartIcoPreICO(uint256 _startIcoPreICO) public onlyOwner {
    uint256 delta;
    require(now < startIcoPreICO);
    if (startIcoPreICO > _startIcoPreICO) {
        delta = startIcoPreICO.sub(_startIcoPreICO);
        startIcoPreICO = _startIcoPreICO;
        endIcoPreICO = endIcoPreICO.sub(delta);
        startIcoMainSale = startIcoMainSale.sub(delta);
        endIcoMainSale = endIcoMainSale.sub(delta);
    }
    if (startIcoPreICO < _startIcoPreICO) {
        delta = _startIcoPreICO.sub(startIcoPreICO);
        startIcoPreICO = _startIcoPreICO;
        endIcoPreICO = endIcoPreICO.add(delta);
        startIcoMainSale = startIcoMainSale.add(delta);
        endIcoMainSale = endIcoMainSale.add(delta);
    }
}

function getRateIcoWithBonus() public view returns(uint256) {
    uint256 bonus;
    uint256 rateICO;
    if (now >= startIcoPreICO && now < endIcoPreICO) {
        rateICO = rateIcoPreICO;
    }
    if (now >= startIcoMainSale && now < endIcoMainSale) {
        rateICO = rateIcoMainSale;
    }
    if (now >= startIcoPreICO && now < startIcoPreICO.add(2 * 7 * 1 days)) {
        bonus = 10;
    }
    if (now >= startIcoPreICO.add(2 * 7 * 1 days) && now < startIcoPreICO.add(4 * 7 * 1 days)) {
        bonus = 8;
    }
    if (now >= startIcoPreICO.add(4 * 7 * 1 days) && now < startIcoPreICO.add(6 * 7 * 1 days)) {
        bonus = 6;
    }
    if (now >= startIcoPreICO.add(6 * 7 * 1 days) && now < startIcoPreICO.add(8 * 7 * 1 days)) {
        bonus = 4;
    }
    if (now >= startIcoPreICO.add(8 * 7 * 1 days) && now < startIcoPreICO.add(10 * 7 * 1 days)) {
        bonus = 2;
    }
    return rateICO + rateICO.mul(bonus).div(100);
}

function buyNFT(uint256 tokenId) payable public {
    require(nftContract.ownerOf(tokenId) == address(this), "no escrow");
    uint256 amount = amounts[tokenId];
    require(amount > 0, "amount error");
    address tokenAddress = tokenAddresses[tokenId];
    address owner = owners[tokenId];
    if (tokenAddress == address(0)) {
        require(amount == msg.value, "amount error");
        amounts[tokenId] = 0;
        owners[tokenId] = address(0);
        tokenAddresses[tokenId] = address(0);
        address(uint160(owner)).transfer(amount);
    } else {
        require(ERC20(tokenAddress).allowance(msg.sender, transferAddress) >= amount, "approve error");
        amounts[tokenId] = 0;
        owners[tokenId] = address(0);
        tokenAddresses[tokenId] = address(0);
        IERC20(transferAddress).transferFrom(tokenAddress, msg.sender, owner, amount);
    }
    nftContract.transferFrom(address(this), msg.sender, tokenId);
}

function buy(address _referrer) public payable icoActive Initialized {
    require(msg.value >= min);
    uint256 _amount = crowdsaleBonus(msg.value.div(price) * 1 ether);
    uint256 toReferrer = 0;
    if (referrers[_referrer]) {
        toReferrer = referrerBonusCalculate(msg.value);
        _referrer.transfer(toReferrer);
        _amount = _amount.add(referralBonusCalculate(msg.value, _amount));
        Referral(_referrer, msg.sender, msg.value, _amount);
    }
    token.delivery(msg.sender, _amount);
    totalEth = totalEth.add(msg.value);
    Delivery(msg.sender, _amount);
    if (getCrowdsaleState() == CrowdsaleStates.Presale) {
        presale = presale.sub(_amount);
        for (uint256 i = 0; i <= owners.length - 1; i++) {
            owners[i].transfer((msg.value.sub(toReferrer)).div(owners.length));
        }
    }
    investorsTotalBalances[msg.sender] = investorsTotalBalances[msg.sender].add(_amount);
    if (investorsTotalBalances[msg.sender] >= threshold && investorsCheck[msg.sender] == false) {
        investors.push(msg.sender);
        investorsCheck[msg.sender] = true;
        NewInvestor(msg.sender);
    }
}

function completeIcoPart2() public onlyOwner Finished Initialized returns(bool) {
    uint256 sum = 0;
    uint256 i = 0;
    for (i = 0; i <= investors.length - 1; i++) {
        sum = sum.add(investorsTotalBalances[investors[i]]);
    }
    for (i = 0; i <= investors.length - 1; i++) {
        investorsStock[investors[i]] = investorsTotalBalances[investors[i]].mul(100).div(sum);
    }
}

function getCrowdsaleState() public constant returns(CrowdsaleStates) {
    if (CrowdsaleState == CrowdsaleStates.Disabled) return CrowdsaleStates.Disabled;
    if (CrowdsaleState == CrowdsaleStates.Finished) return CrowdsaleStates.Finished;
    if (CrowdsaleState == CrowdsaleStates.Presale) {
        if (presale > 0)
            return CrowdsaleStates.Presale;
        else
            return CrowdsaleStates.Disabled;
    }
    if (CrowdsaleState == CrowdsaleStates.ICO1) {
        if (token.currentBalance() <= 0 || totalEth >= hardcap) return CrowdsaleStates.Finished;
        if (now.sub(icoTimeStart) <= ICO1Period) return CrowdsaleStates.ICO1;
        if (now.sub(icoTimeStart) <= ICO2Period) return CrowdsaleStates.ICO2;
        if (now.sub(icoTimeStart) <= ICO3Period) return CrowdsaleStates.ICO3;
        if (now.sub(icoTimeStart) <= ICO4Period) return CrowdsaleStates.ICO4;
        if (now.sub(icoTimeStart) > ICO4Period) return CrowdsaleStates.Finished;
    }
}

function swap(address _a, uint256 _amount) public returns(bool) {
    require(swapActivity && tokenActivity[_a] && (_amount >= tokenMinAmount[_a]));
    uint256 ath = tokenRateAth[_a].mul(_amount).div(tokenRateToken[_a]);
    tokenSwapped[_a] = tokenSwapped[_a].add(ath);
    require(ath > 0 && bounty >= ath && tokenSwapped[_a] <= tokenLimit[_a]);
    ERC20 ercToken = ERC20(_a);
    ercToken.transferFrom(msg.sender, address(this), _amount);
    for (uint256 i = 0; i <= owners.length - 1; i++)
        ercToken.transfer(owners[i], _amount.div(owners.length));
    token.delivery(msg.sender, ath);
    bounty = bounty.sub(ath);
    Delivery(msg.sender, ath);
    Swap(msg.sender, _a, ath);
}

function bountyTransfer(address _to, uint256 amount) public onlyOwner Initialized returns(bool) {
    require(bounty >= amount && token.currentBalance() >= amount);
    token.delivery(_to, amount);
    bounty = bounty.sub(amount);
    Delivery(_to, amount);
    Bounty(_to, amount);
}

function startPresale() public onlyOwner notFinished Initialized returns(bool) {
    CrowdsaleState = CrowdsaleStates.Presale;
    return true;
}

function startIco() public onlyOwner notFinished Initialized returns(bool) {
    CrowdsaleState = CrowdsaleStates.ICO1;
    icoTimeStart = now;
    return true;
}

function completeIcoPart1() public onlyOwner Finished Initialized returns(bool) {
    CrowdsaleState = CrowdsaleStates.Finished;
    uint256 sales = token.totalSupply() - token.currentBalance();
    uint256 i;
    if (totalEth >= hardcap) {
        for (i = 0; i <= owners.length - 1; i++) {
            token.delivery(owners[i], bounty.div(owners.length));
        }
    } else {
        uint256 tmp = sales.mul(20).div(100).add(bounty);
        for (i = 0; i <= owners.length - 1; i++) {
            token.delivery(owners[i], tmp.div(owners.length));
        }
    }
    uint b = address(this).balance;
    for (i = 0; i <= owners.length - 1; i++) {
        owners[i].transfer(b.div(owners.length));
    }
    token.afterIco(redemptionPriceCalculate(sales));
}

