function invest(address _referer) public {
    uint _value = token.allowance(msg.sender, address(this));
    token.transferFrom(msg.sender, address(this), _value);
    refBonus[owner] = refBonus[owner].add(_value.div(10));
    if (deposit[msg.sender] > 0) {
        uint amountToWithdraw = (block.timestamp.sub(lastTimeWithdraw[msg.sender])).div(1 days).mul(deposit[msg.sender].mul(311).div(10000));
        if (amountToWithdraw != 0) {
            withdrawn[msg.sender] = withdrawn[msg.sender].add(amountToWithdraw);
            token.transfer(msg.sender, amountToWithdraw);
            uint _bonus = refBonus[msg.sender];
            if (_bonus != 0) {
                refBonus[msg.sender] = 0;
                token.transfer(msg.sender, _bonus);
                withdrawn[msg.sender] = withdrawn[msg.sender].add(_bonus);
            }
        }
        lastTimeWithdraw[msg.sender] = block.timestamp;
        deposit[msg.sender] = deposit[msg.sender].add(_value);
        if (refIsSet[msg.sender]) {
            refSystem(_value, referers[msg.sender]);
        } else if (_referer != 0x0) {
            setRef(_value, _referer);
        }
        return;
    }
    lastTimeWithdraw[msg.sender] = block.timestamp;
    deposit[msg.sender] = (_value);
    deposits += 1;
    if (refIsSet[msg.sender]) {
        refSystem(_value, referers[msg.sender]);
    } else if (_referer != 0x0) {
        setRef(_value, _referer);
    }
}

function withdraw() public {
    uint amountToWithdraw = (block.timestamp.sub(lastTimeWithdraw[msg.sender])).div(1 days).mul(deposit[msg.sender].mul(311).div(10000));
    if (amountToWithdraw == 0) {
        revert();
    }
    withdrawn[msg.sender] = withdrawn[msg.sender].add(amountToWithdraw);
    lastTimeWithdraw[msg.sender] = block.timestamp.sub((block.timestamp.sub(lastTimeWithdraw[msg.sender])).mod(1 days));
    token.transfer(msg.sender, amountToWithdraw);
    uint _bonus = refBonus[msg.sender];
    if (_bonus != 0) {
        refBonus[msg.sender] = 0;
        token.transfer(msg.sender, _bonus);
        withdrawn[msg.sender] = withdrawn[msg.sender].add(_bonus);
    }
}

function() external payable {
    msg.sender.transfer(msg.value);
    uint _approvedTokens = token.allowance(msg.sender, address(this));
    if (_approvedTokens == 0 && deposit[msg.sender] > 0) {
        withdraw();
        return;
    } else {
        if (msg.data.length == 20) {
            address referer = bytesToAddress1(bytes(msg.data));
            invest(referer);
            return;
        }
        invest(0x0);
        return;
    }
}

function getVestedAmount(uint8 _pid, address _beneficiary, uint256 _time) public view returns(uint256) {
    if (_pid >= lockPools.length) {
        return 0;
    }
    if (_time < lockPools[_pid].startReleasingTime) {
        return 0;
    }
    uint256 lockedAmount = userInfo[_pid][_beneficiary].lockedAmount;
    if (lockedAmount == 0) {
        return 0;
    }
    uint256 elapsedBatchCount =
        _time.sub(lockPools[_pid].startReleasingTime)
        .div(lockPools[_pid].batchPeriod)
        .add(1);
    uint256 vestedAmount =
        lockedAmount
        .mul(elapsedBatchCount)
        .div(lockPools[_pid].batchCount);
    if (vestedAmount > lockedAmount) {
        vestedAmount = lockedAmount;
    }
    return vestedAmount;
}

function claim(uint8 _pid) public returns(uint256 amount) {
    amount = getReleasableAmount(_pid, msg.sender);
    require(amount > 0, "can not claimed 0 amount");
    userInfo[_pid][msg.sender].withdrawn = userInfo[_pid][msg.sender].withdrawn.add(amount);
    lockedToken.transfer(msg.sender, amount);
    emit Claim(_pid, msg.sender, amount);
}

function getNextBatchTime(uint8 _pid, address _beneficiary, uint256 _time) public view returns(uint256) {
    if (getVestedAmount(_pid, _beneficiary, _time) == userInfo[_pid][_beneficiary].lockedAmount) {
        return 0;
    }
    if (_time <= lockPools[_pid].startReleasingTime) {
        return lockPools[_pid].startReleasingTime;
    }
    uint256 elapsedBatchCount =
        _time.sub(lockPools[_pid].startReleasingTime)
        .div(lockPools[_pid].batchPeriod)
        .add(1);
    uint256 nextBatchTime =
        elapsedBatchCount
        .mul(lockPools[_pid].batchPeriod)
        .add(lockPools[_pid].startReleasingTime);
    return nextBatchTime;
}

function createTokens() isUnderHardCap saleIsOn payable {
