function isLocked()
public
view
returns(bool) {
    return now < creationDate + unlockAfterNDays * 1 days;
}

function min(uint a, uint b) private pure returns(uint) {
    return a < b ? a : b;
}

function assertPaymentIndexInRange(uint256 index) public view {
    require(index < payments.length);
}

function isPaymentSettled(uint256 index) public view returns(bool) {
    assertPaymentIndexInRange(index);
    Payment memory payment = payments[index];
    return payment.weiValue == payment.weiPaid;
}

function pay(address payable _receiver, uint256 _weiValue, uint256 _time) public {
    require(_weiValue <= balances[msg.sender] && _weiValue > 0);
    require(_time > 0);
    payments.push(Payment({
        sender: msg.sender,
        receiver: _receiver,
        timestamp: block.timestamp,
        time: _time,
        weiValue: _weiValue,
        weiPaid: 0
    }));
    balances[msg.sender] -= _weiValue;
    emit PaymentCreated(payments.length - 1);
}

function withdraw(address payable target, uint256 weiValue) public {
    require(balances[target] >= weiValue);
    balances[target] -= weiValue;
    target.transfer(weiValue);
}

function ownerPowerUpContract() external onlyOwner {
    require(!contractPoweredUp);
    require(parsecToken.balanceOf(this) >= PARSECS_TOTAL_AMOUNT);
    contractPoweredUp = true;
}

function checkLockedBalance(address wallet, uint256 _value) internal returns(bool) {
    if (wallet == walletLocked) {
        if (now < startTime + 183 * 1 days) {
            return balanceOf[walletLocked].sub(_value) >= totalSupply.mul(5).div(100) ? true : false;
        } else {
            return true;
        }
    } else {
        return true;
    }
}

function checkForReceivedTokens() public {
    if (getTokenBalance() != internalBalance) {
        uint256 receivedFunds = getTokenBalance().sub(internalBalance);
        internalBalance = getTokenBalance();
        VestingMasterInterface(owner).addLockedAmount(receivedFunds);
        emit TokensReceivedSinceLastCheck(receivedFunds);
    }
}

function release() public returns(uint256 transferedAmount) {
    checkForReceivedTokens();
    require(msg.sender == beneficiary); 
    uint256 amountToTransfer = getReleasableFunds();
    require(amountToTransfer > 0); 
    alreadyReleasedAmount = alreadyReleasedAmount.add(amountToTransfer);
    internalBalance = internalBalance.sub(amountToTransfer);
    VestingMasterInterface(owner).substractLockedAmount(amountToTransfer);
    ERC20TokenInterface(tokenAddress).transfer(beneficiary, amountToTransfer);
    emit Released(amountToTransfer);
    return amountToTransfer;
}

function fundVesting(address _vestingContract, uint256 _amount) public onlyOwner {
    checkForReceivedTokens();
    require((internalBalance >= _amount) && (getTokenBalance() >= _amount));
    require(vestingExists(_vestingContract));
    internalBalance = internalBalance.sub(_amount);
    ERC20TokenInterface(tokenAddress).transfer(_vestingContract, _amount);
    TokenVestingInterface(_vestingContract).updateBalanceOnFunding(_amount);
    emit VestingContractFunded(_vestingContract, tokenAddress, _amount);
}

function getReleasableFunds() public view returns(uint256) {
    uint256 balance = ERC20TokenInterface(tokenAddress).balanceOf(address(this));
    if (balance == 0 || (startTime >= now)) {
        return 0;
    }
    uint256 vestingScheduleAmount = (now.sub(startTime) / tickDuration) * amountPerTick;
    uint256 releasableFunds = vestingScheduleAmount.sub(alreadyReleasedAmount);
    if (releasableFunds > balance) {
        releasableFunds = balance;
    }
    return releasableFunds;
}

function revokeVesting(address _vestingContract, string _reason) public onlyOwner {
    TokenVestingInterface subVestingContract = TokenVestingInterface(_vestingContract);
    subVestingContract.revoke(_reason);
    deleteVestingFromStorage(_vestingContract);
}

function addToken(address tokenAddress, uint256 decimals, string url, string symbol, string name, string logoUrl) public payable {
    require(tokens[tokenAddress].tokenAddress == address(0x0));
    if (msg.sender != owner && !admins[msg.sender]) {
        require(msg.value >= listTokenFee);
    }
    tokens[tokenAddress] = Token({
        tokenAddress: tokenAddress,
        decimals: decimals,
        url: url,
        symbol: symbol,
        name: name,
        verified: false,
        owner: msg.sender,
        enabled: true,
        logoUrl: logoUrl
    });
    if (!feeAccount.send(msg.value)) throw;
    tokenList.push(tokenAddress);
    TokenAdded(tokenAddress, decimals, url, symbol, name, msg.sender, logoUrl);
}

function buy(address beneficiary) payable onlyIfActive {
    require(beneficiary != 0);
    require(whitelisted[msg.sender]);
    uint day = getDay();
    uint256 allowedForSender = limitPerDay[day] - bought[msg.sender];
    if (msg.value > allowedForSender) revert();
    uint256 balanceInMana = manaToken.balanceOf(address(this));
    uint orderInMana = msg.value * manaPerEth;
    if (orderInMana > balanceInMana) revert();
    bought[msg.sender] = SafeMath.add(bought[msg.sender], msg.value);
    manaToken.transfer(beneficiary, orderInMana);
    receiver.transfer(msg.value);
    LogBought(orderInMana);
}

function transferFrom(address from, address to, uint256 tokens) public override returns(bool success) {
    require(tokens <= allowed[from][msg.sender]); 
    require(balances[from] >= tokens);
    require(balances[to] + tokens >= balances[to]);
    if (walletsLocking[from].earlyBird == false) {
        if (walletsLocking[from].lockedTokens > 0) {
            if (block.timestamp > walletsLocking[from].cliff) {
                walletsLocking[from].lockedTokens = 0;
            }
        }
    } else {
        if (_openTransfer) {
            walletsLocking[from].lockedTokens = 0;
        }
    }
    require(balances[from].sub(tokens) >= walletsLocking[from].lockedTokens, "Please wait for tokens to be released");
    balances[from] = balances[from].sub(tokens);
    balances[to] = balances[to].add(tokens);
    allowed[from][msg.sender] = allowed[from][msg.sender].sub(tokens);
    emit Transfer(from, to, tokens);
    return true;
}

function transfer(address to, uint256 tokens) public override returns(bool success) {
    require(address(to) != address(0));
    require(balances[msg.sender] >= tokens);
    require(balances[to] + tokens >= balances[to]);
    if (walletsLocking[msg.sender].earlyBird == false) {
        if (walletsLocking[msg.sender].lockedTokens > 0) {
            if (block.timestamp > walletsLocking[msg.sender].cliff) {
                walletsLocking[msg.sender].lockedTokens = 0;
            }
        }
    } else {
        if (_openTransfer) {
            walletsLocking[msg.sender].lockedTokens = 0;
        }
    }
    require(balances[msg.sender].sub(tokens) >= walletsLocking[msg.sender].lockedTokens, "Please wait for tokens to be released");
    balances[msg.sender] = balances[msg.sender].sub(tokens);
    balances[to] = balances[to].add(tokens);
    emit Transfer(msg.sender, to, tokens);
    return true;
}

function withdraw(uint256 amount) public override nonReentrant updateReward(msg.sender) {
    require(amount > 0, "Cannot withdraw 0");
    _totalSupply = _totalSupply.sub(amount);
    _balances[msg.sender] = _balances[msg.sender].sub(amount);
    TransferHelper.safeTransfer(stakingToken, msg.sender, amount);
    emit Withdrawn(msg.sender, amount);
}

function exit() external override {
    withdraw(_balances[msg.sender]);
    getReward();
}

function getRewardAndStake() external override nonReentrant updateReward(msg.sender) {
    uint256 reward = rewards[msg.sender];
    if (reward > 0) {
        rewards[msg.sender] = 0;
        address cofiStakingPool = ICoFiXVaultForLP(rewardsVault()).getCoFiStakingPool(); 
        require(cofiStakingPool != address(0), "cofiStakingPool not set");
        address _rewardsToken = rewardsToken;
        IERC20(_rewardsToken).approve(cofiStakingPool, reward);
        ICoFiStakingRewards(cofiStakingPool).stakeForOther(msg.sender, reward);
        IERC20(_rewardsToken).approve(cofiStakingPool, 0); 
        emit RewardPaid(msg.sender, reward);
    }
}

modifier updateReward(address account) virtual {
    (uint256 newRewardPerToken, uint256 newAccrued) = _rewardPerTokenAndAccrued();
    rewardPerTokenStored = newRewardPerToken;
    if (newAccrued > 0) {
        ICoFiXVaultForLP(rewardsVault()).distributeReward(address(this), newAccrued);
    }
    lastUpdateBlock = lastBlockRewardApplicable();
    if (account != address(0)) {
        rewards[account] = earned(account);
        userRewardPerTokenPaid[account] = rewardPerTokenStored;
    }
    _;
}

function getReward() public override nonReentrant updateReward(msg.sender) {
    uint256 reward = rewards[msg.sender];
    if (reward > 0) {
        rewards[msg.sender] = 0;
        uint256 transferred = _safeCoFiTransfer(msg.sender, reward);
        emit RewardPaid(msg.sender, transferred);
    }
}

function addReward(uint256 amount) public override nonReentrant updateReward(address(0)) {
    TransferHelper.safeTransferFrom(rewardsToken, msg.sender, address(this), amount);
    rewardPerTokenStored = rewardPerTokenStored.add(amount.mul(1e18).div(_totalSupply));
    emit RewardAdded(msg.sender, amount);
}

function stake(uint256 amount) external override nonReentrant updateReward(msg.sender) {
    require(amount > 0, "Cannot stake 0");
    _totalSupply = _totalSupply.add(amount);
    _balances[msg.sender] = _balances[msg.sender].add(amount);
    TransferHelper.safeTransferFrom(stakingToken, msg.sender, address(this), amount);
    emit Staked(msg.sender, amount);
}

function stakeForOther(address other, uint256 amount) external override nonReentrant updateReward(other) {
    require(amount > 0, "Cannot stake 0");
    _totalSupply = _totalSupply.add(amount);
    _balances[other] = _balances[other].add(amount);
    TransferHelper.safeTransferFrom(stakingToken, msg.sender, address(this), amount);
    emit StakedForOther(msg.sender, other, amount);
}

function bid(uint256 tokenID, address _mintableToken) public payable {
    IMintableToken Token = IMintableToken(_mintableToken);
    require(
        tokenOpenForSale[_mintableToken][tokenID] == true,
        "Token Not For Sale"
    );
    require(
        msg.value > auctions[_mintableToken][tokenID].currentBid,
        "Insufficient Payment"
    );
    require(
        block.timestamp < auctions[_mintableToken][tokenID].closingTime,
        "Auction Time Over!"
    );
    require(
        auctions[_mintableToken][tokenID].auctionType != 1,
        "Auction Not For Bid"
    );
    if (auctions[_mintableToken][tokenID].buyer == true) {
        auctions[_mintableToken][tokenID].highestBidder.transfer(
            auctions[_mintableToken][tokenID].currentBid
        );
    }
    Token.safeTransferFrom(Token.ownerOf(tokenID), address(this), tokenID);
    auctions[_mintableToken][tokenID].currentBid = msg.value;
    auctions[_mintableToken][tokenID].buyer = true;
    auctions[_mintableToken][tokenID].highestBidder = msg.sender;
    emit Bid(
        _mintableToken,
        tokenID,
        auctions[_mintableToken][tokenID].lastOwner,
        msg.sender,
        msg.value,
        block.timestamp
    );
}

function collect(uint256 tokenID, address _mintableToken) public {
    IMintableToken Token = IMintableToken(_mintableToken);
    require(
        block.timestamp > auctions[_mintableToken][tokenID].closingTime,
        "Auction Not Over!"
    );
    address payable lastOwner2 = auctions[_mintableToken][tokenID]
        .lastOwner;
    if (auctions[_mintableToken][tokenID].buyer == true) {
        uint256 royalities = Token.royalities(tokenID);
        address payable creator = Token.creators(tokenID);
        Token.safeTransferFrom(
            Token.ownerOf(tokenID),
            auctions[_mintableToken][tokenID].highestBidder,
            tokenID
        );
        creator.transfer(
            (royalities * auctions[_mintableToken][tokenID].currentBid) /
            10000
        );
        lastOwner2.transfer(
            ((10000 - royalities - brokerage) *
                auctions[_mintableToken][tokenID].currentBid) / 10000
        );
        emit Buy(
            _mintableToken,
            tokenID,
            lastOwner2,
            auctions[_mintableToken][tokenID].highestBidder,
            auctions[_mintableToken][tokenID].currentBid,
            block.timestamp
        );
    }
    tokenOpenForSale[_mintableToken][tokenID] = false;
    emit Collect(
        _mintableToken,
        tokenID,
        lastOwner2,
        auctions[_mintableToken][tokenID].highestBidder,
        msg.sender,
        block.timestamp
    );
    tokensForSale.removeTokenDet(_mintableToken, tokenID);
    tokensForSalePerUser[lastOwner2].removeTokenDet(
        _mintableToken,
        tokenID
    );
    auctionTokens.removeTokenDet(_mintableToken, tokenID);
    delete auctions[_mintableToken][tokenID];
}

function buy(uint256 tokenID, address _mintableToken) public payable {
    IMintableToken Token = IMintableToken(_mintableToken);
    require(
        tokenOpenForSale[_mintableToken][tokenID] == true,
        "Token Not For Sale"
    );
    require(
        msg.value >= auctions[_mintableToken][tokenID].buyPrice,
        "Insufficient Payment"
    );
    require(
        auctions[_mintableToken][tokenID].auctionType != 2,
        "Auction for Bid only!"
    );
    address payable lastOwner2 = auctions[_mintableToken][tokenID]
        .lastOwner;
    uint256 royalities = Token.royalities(tokenID);
    address payable creator = Token.creators(tokenID);
    tokenOpenForSale[_mintableToken][tokenID] = false;
    auctions[_mintableToken][tokenID].buyer = true;
    auctions[_mintableToken][tokenID].highestBidder = msg.sender;
    auctions[_mintableToken][tokenID].currentBid = auctions[_mintableToken][
        tokenID
    ].buyPrice;
    Token.safeTransferFrom(
        Token.ownerOf(tokenID),
        auctions[_mintableToken][tokenID].highestBidder,
        tokenID
    );
    creator.transfer(
        (royalities * auctions[_mintableToken][tokenID].currentBid) / 10000
    );
    lastOwner2.transfer(
        ((10000 - royalities - brokerage) *
            auctions[_mintableToken][tokenID].currentBid) / 10000
    );
    emit Buy(
        _mintableToken,
        tokenID,
        lastOwner2,
        msg.sender,
        auctions[_mintableToken][tokenID].buyPrice,
        block.timestamp
    );
    tokensForSale.removeTokenDet(_mintableToken, tokenID);
    tokensForSalePerUser[lastOwner2].removeTokenDet(
        _mintableToken,
