    );
    fixedPriceTokens.removeTokenDet(_mintableToken, tokenID);
}

function putOnSale(
    uint256 _tokenID,
    uint256 _startingPrice,
    uint256 _auctionType,
    uint256 _buyPrice,
    uint256 _duration,
    address _mintableToken
) public {
    IMintableToken Token = IMintableToken(_mintableToken);
    require(Token.ownerOf(_tokenID) == msg.sender, "Permission Denied");
    require(
        Token.getApproved(_tokenID) == address(this),
        "Broker Not approved"
    );
    if (tokenOpenForSale[_mintableToken][_tokenID] == true) {
        require(
            auctions[_mintableToken][_tokenID].auctionType == 2 &&
            auctions[_mintableToken][_tokenID].buyer == false &&
            block.timestamp >
            auctions[_mintableToken][_tokenID].closingTime,
            "This NFT is already on sale."
        );
    }
    auction memory newAuction = auction(
        msg.sender,
        _startingPrice,
        address(0),
        _auctionType,
        _startingPrice,
        _buyPrice,
        false,
        block.timestamp,
        block.timestamp + _duration
    );
    auctions[_mintableToken][_tokenID] = newAuction;
    if (tokenOpenForSale[_mintableToken][_tokenID] == false) {
        tokenOpenForSale[_mintableToken][_tokenID] = true;
        tokensForSale.addTokenDet(_mintableToken, _tokenID);
        tokensForSalePerUser[msg.sender].addTokenDet(
            _mintableToken,
            _tokenID
        );
        if (_auctionType == 1) {
            fixedPriceTokens.addTokenDet(_mintableToken, _tokenID);
        } else if (_auctionType == 2) {
            auctionTokens.addTokenDet(_mintableToken, _tokenID);
        }
    }
    emit OnSale(
        _mintableToken,
        _tokenID,
        msg.sender,
        _auctionType,
        _auctionType == 1 ? _buyPrice : _startingPrice,
        block.timestamp
    );
}

function updatePrice(
    uint256 tokenID,
    address _mintableToken,
    uint256 _newPrice
) public {
    IMintableToken Token = IMintableToken(_mintableToken);
    require(
        Token.ownerOf(tokenID) == msg.sender,
        "You must be owner and Token should not have any bid"
    );
    require(
        tokenOpenForSale[_mintableToken][tokenID] == true,
        "Token Must be on sale to change price"
    );
    if (auctions[_mintableToken][tokenID].auctionType == 2) {
        require(
            block.timestamp < auctions[_mintableToken][tokenID].closingTime,
            "Auction Time Over!"
        );
    }
    emit PriceUpdated(
        _mintableToken,
        tokenID,
        auctions[_mintableToken][tokenID].lastOwner,
        auctions[_mintableToken][tokenID].auctionType,
        auctions[_mintableToken][tokenID].auctionType == 1 ?
        auctions[_mintableToken][tokenID].buyPrice :
        auctions[_mintableToken][tokenID].startingPrice,
        _newPrice,
        block.timestamp
    );
    if (auctions[_mintableToken][tokenID].auctionType == 1) {
        auctions[_mintableToken][tokenID].buyPrice = _newPrice;
    } else {
        auctions[_mintableToken][tokenID].startingPrice = _newPrice;
        auctions[_mintableToken][tokenID].currentBid = _newPrice;
    }
}

function lockLPToken(address _lpToken, uint256 _amount, uint256 _unlock_date, address payable _referral, bool _fee_in_eth, address payable _withdrawer) external payable nonReentrant {
    require(_unlock_date < 10000000000, 'TIMESTAMP INVALID'); 
    require(_amount > 0, 'INSUFFICIENT');
    IUniswapV2Pair lpair = IUniswapV2Pair(address(_lpToken));
    address factoryPairAddress = uniswapV2Factory.getPair(lpair.token0(), lpair.token1());
    require(factoryPairAddress == address(_lpToken), 'NOT PANCAKE');
    TransferHelper.safeTransferFrom(_lpToken, address(msg.sender), address(this), _amount);
    if (_referral != address(0) && address(gFees.referralToken) != address(0)) {
        require(gFees.referralToken.balanceOf(_referral) >= gFees.referralHold, 'INADEQUATE BALANCE');
    }
    if (!feeWhitelist.contains(msg.sender)) {
        if (_fee_in_eth) { 
            uint256 ethFee = gFees.ethFee;
            if (_referral != address(0)) {
                ethFee = ethFee.mul(1000 - gFees.referralDiscount).div(1000);
            }
            require(msg.value == ethFee, 'FEE NOT MET');
            uint256 devFee = ethFee;
            if (ethFee != 0 && _referral != address(0)) { 
                uint256 referralFee = devFee.mul(gFees.referralPercent).div(1000);
                _referral.transfer(referralFee);
                devFee = devFee.sub(referralFee);
            }
            devaddr.transfer(devFee);
        } else { 
            uint256 burnFee = gFees.secondaryTokenFee;
            if (_referral != address(0)) {
                burnFee = burnFee.mul(1000 - gFees.referralDiscount).div(1000);
            }
            TransferHelper.safeTransferFrom(address(gFees.secondaryFeeToken), address(msg.sender), address(this), burnFee);
            if (gFees.referralPercent != 0 && _referral != address(0)) { 
                uint256 referralFee = burnFee.mul(gFees.referralPercent).div(1000);
                TransferHelper.safeTransfer(address(gFees.secondaryFeeToken), _referral, referralFee);
                burnFee = burnFee.sub(referralFee);
            }
            gFees.secondaryFeeToken.burn(burnFee);
        }
    } else if (msg.value > 0) {
        msg.sender.transfer(msg.value);
    }
    uint256 liquidityFee = _amount.mul(gFees.liquidityFee).div(1000);
    if (!_fee_in_eth && !feeWhitelist.contains(msg.sender)) { 
        liquidityFee = liquidityFee.mul(1000 - gFees.secondaryTokenDiscount).div(1000);
    }
    TransferHelper.safeTransfer(_lpToken, devaddr, liquidityFee);
    uint256 amountLocked = _amount.sub(liquidityFee);
    TokenLock memory token_lock;
    token_lock.lockDate = block.timestamp;
    token_lock.amount = amountLocked;
    token_lock.initialAmount = amountLocked;
    token_lock.unlockDate = _unlock_date;
    token_lock.lockID = tokenLocks[_lpToken].length;
    token_lock.owner = _withdrawer;
    tokenLocks[_lpToken].push(token_lock);
    lockedTokens.add(_lpToken);
    UserInfo storage user = users[_withdrawer];
    user.lockedTokens.add(_lpToken);
    uint256[] storage user_locks = user.locksForToken[_lpToken];
    user_locks.push(token_lock.lockID);
    emit onDeposit(_lpToken, msg.sender, token_lock.amount, token_lock.lockDate, token_lock.unlockDate);
}

