function interest(uint _batchDate) private view returns(uint _interest) {
    uint _age = secToDays(softSub(now, _batchDate)); 
    while (_age >= 106) { 
        _age = _age - 103; 
    }
    if (_age < 3) return 0;
    if (_age > 91) return 0;
    uint _tokenFortnights = _age / fortNight;
    uint _fortnightsFromLast = fortnightsFromLast();
    if (_tokenFortnights > _fortnightsFromLast) _tokenFortnights = _fortnightsFromLast;
    uint yearsNow = secToDays(now - initialDate) / 365; 
    if (yearsNow > 3) yearsNow = 3;
    _interest = 1 ether * yearlyInterest[yearsNow] * _tokenFortnights / 24; 
}

function softSub(uint x, uint y) private pure returns(uint z) {
    z = x - y;
    if (z > x) z = 0;
}

function calculateInterest(address _address) private returns(uint _amount) {
    uint totalAmount = 0; 
    uint tokenCounted; 
    uint intBatch; 
    uint batchInterest; 
    uint batchAmount;
    uint batchDate;
    for (uint i = token.minIndex(_address); i < token.maxIndex(_address); i++) {
        (batchAmount, batchDate) = token.getBatch(_address, i); 
        intBatch = interest(batchDate); 
        batchInterest = batchAmount * intBatch / 1 ether / 100; 
        if (intBatch > 0) tokenCounted += batchAmount; 
        totalAmount += batchInterest; 
        emit Batch(
            batchAmount,
            secToDays(softSub(now, batchDate)),
            batchInterest
        );
    }
    if (tokenCounted >= 150 ether) return totalAmount;
    else return 0;
}

function payInterests() isUnlocked public {
    if (fortnightsFromLast() == 0) { 
        emit Message("0 fortnights passed");
        return;
    }
    uint amountToPay = calculateInterest(msg.sender);
    if (amountToPay == 0) {
        emit Message("There are not 150 tokens with interests to pay");
        return;
    }
    lastFortnightPayed[msg.sender] = now;
    require(token.transferFrom(tokenSpender, msg.sender, amountToPay));
}

function contribute(
    address _contributor,
    uint256 _contributionLimitUnits,
    uint256 _payloadExpiration,
    bytes _sig
)
external
payable
checkAllowed
isWhitelisted(keccak256(
    abi.encodePacked(
        _contributor,
        _contributionLimitUnits,
        _payloadExpiration
    )
), _sig) {
    require(msg.sender == _contributor);
    require(now < _payloadExpiration);
    uint256 weiPerUnitRate = ethPriceFeed.getRate();
    require(weiPerUnitRate != 0);
    uint256 previouslyContributedUnits = unitContributions[_contributor];
    uint256 currentContributionUnits = min256(
        _contributionLimitUnits.sub(previouslyContributedUnits),
        totalSaleCapUnits.sub(totalContributedUnits),
        msg.value.div(weiPerUnitRate)
    );
    require(currentContributionUnits != 0);
    require(currentContributionUnits >= minContributionUnits || previouslyContributedUnits != 0);
    unitContributions[_contributor] = previouslyContributedUnits.add(currentContributionUnits);
    totalContributedUnits = totalContributedUnits.add(currentContributionUnits);
    uint256 currentContributionWei = currentContributionUnits.mul(weiPerUnitRate);
    trustedVault.deposit.value(currentContributionWei)(msg.sender);
    if (totalContributedUnits >= minThresholdUnits &&
        trustedVault.state() != Vault.State.Success) {
        trustedVault.saleSuccessful();
    }
    uint256 excessWei = msg.value.sub(currentContributionWei);
    if (excessWei > 0) {
        msg.sender.transfer(excessWei);
    }
    emit Contribution(
        _contributor,
        msg.sender,
        currentContributionUnits,
        currentContributionWei,
        excessWei,
        weiPerUnitRate
    );
    uint256 tokenAmount = currentContributionUnits.mul(saleTokensPerUnit);
    trustedToken.safeTransfer(_contributor, tokenAmount);
    emit TokensAllocated(_contributor, tokenAmount);
}

function onSaleEnded() internal {
    trustedToken.transferOwnership(owner);
    if (totalContributedUnits == 0) {
        trustedToken.safeTransfer(trustedVault.trustedWallet(), tokensForSale);
    } else if (totalContributedUnits < minThresholdUnits) {
        trustedVault.enableRefunds();
    } else {
        extraTokensPerUnit = tokensForSale.div(totalContributedUnits).sub(saleTokensPerUnit);
        trustedVault.close();
        trustedVault.transferOwnership(owner);
    }
}

function transferFrom(address _from, address _to, uint256 _value)
isAllowed(_from, _to)
public
returns(bool) {
    return super.transferFrom(_from, _to, _value);
}

function transfer(address _to, uint256 _value)
isAllowed(msg.sender, _to)
public
returns(bool) {
    return super.transfer(_to, _value);
}

function setup() external onlyOwner checkAllowed {
    trustedToken.safeTransfer(disbursementHandler, disbursementHandler.totalAmount());
    tokensForSale = trustedToken.balanceOf(this);
    require(tokensForSale >= totalSaleCapUnits);
    saleTokensPerUnit = tokensForSale.div(totalSaleCapUnits);
    goToNextState();
}

function setupDisbursement(
    address _beneficiary,
    uint256 _value,
    uint256 _timestamp
)
external
onlyOwner {
    require(block.timestamp < _timestamp);
    disbursements[_beneficiary].push(Disbursement(_timestamp, _value));
    totalAmount = totalAmount.add(_value);
    emit Setup(_beneficiary, _timestamp, _value);
}

function setEndTime(uint256 _endTime) external onlyOwner checkAllowed {
    require(now < _endTime);
    require(getStateStartTime(SALE_ENDED) == 0);
    setStateStartTime(SALE_ENDED, _endTime);
}

function hasStartTimePassed(bytes32 _stateId) internal returns(bool) {
    return startTime[_stateId] <= block.timestamp;
}

function setStateStartTime(bytes32 _stateId, uint256 _timestamp) internal {
    require(block.timestamp < _timestamp);
    if (startTime[_stateId] == 0) {
        addStartCondition(_stateId, hasStartTimePassed);
    }
    startTime[_stateId] = _timestamp;
    emit StateStartTimeSet(_stateId, _timestamp);
}

constructor(
    uint256 _totalSaleCapUnits, 
    uint256 _minContributionUnits, 
    uint256 _minThresholdUnits, 
    uint256 _maxTokens,
    address _whitelistAdmin,
    address _wallet,
    uint256 _vaultInitialDisburseWei, 
    uint256 _vaultDisbursementWei, 
    uint256 _vaultDisbursementDuration,
    uint256 _startTime,
    string _tokenName,
    string _tokenSymbol,
    uint8 _tokenDecimals,
    EthPriceFeedI _ethPriceFeed
)
Whitelistable(_whitelistAdmin)
public {
    require(_totalSaleCapUnits != 0);
    require(_maxTokens != 0);
    require(_wallet != 0);
    require(_minThresholdUnits <= _totalSaleCapUnits);
    require(_ethPriceFeed != address(0));
    require(now < _startTime);
    totalSaleCapUnits = _totalSaleCapUnits;
    minContributionUnits = _minContributionUnits;
    minThresholdUnits = _minThresholdUnits;
    trustedToken = new Token(
        _maxTokens,
        _tokenName,
        _tokenSymbol,
        _tokenDecimals
    );
    disbursementHandler = new DisbursementHandler(trustedToken);
    ethPriceFeed = _ethPriceFeed;
    trustedToken.setController(this);
    trustedVault = new Vault(
        _wallet,
        _vaultInitialDisburseWei,
        _vaultDisbursementWei, 
        _vaultDisbursementDuration
    );
    setStates(states);
    allowFunction(SETUP, this.setup.selector);
    allowFunction(FREEZE, this.setEndTime.selector);
    allowFunction(SALE_IN_PROGRESS, this.setEndTime.selector);
    allowFunction(SALE_IN_PROGRESS, this.contribute.selector);
    allowFunction(SALE_IN_PROGRESS, this.endSale.selector);
    allowFunction(SALE_ENDED, this.allocateExtraTokens.selector);
    addStartCondition(SALE_ENDED, wasCapReached);
    setStateStartTime(SALE_IN_PROGRESS, _startTime);
    addCallback(SALE_ENDED, onSaleEnded);
}

function withdraw(address _beneficiary, uint256 _index)
external {
    Disbursement[] storage beneficiaryDisbursements = disbursements[_beneficiary];
    require(_index < beneficiaryDisbursements.length);
    Disbursement memory disbursement = beneficiaryDisbursements[_index];
    require(disbursement.timestamp < now && disbursement.value > 0);
    delete beneficiaryDisbursements[_index];
    token.safeTransfer(_beneficiary, disbursement.value);
    emit TokensWithdrawn(_beneficiary, disbursement.value);
}

function takeTaxes(address from, address to, uint256 amount) internal returns(uint256) {
    uint256 currentFee;
    if (from == lpPair) {
        if (balanceOf(to) > 0) {
            require(block.timestamp - buyLog[to] >= buyCoolDown, "Buy cooldown");
        }
        buyLog[to] = block.timestamp;
        currentFee = _buyFee;
    } else if (to == lpPair) {
        currentFee = _sellFee;
    } else {
        currentFee = _transferFee;
    }
    if (_hasLimits(from, to)) {
        if (_liqAddStatus == 0 || _liqAddStatus != 69_420) {
            revert();
        }
    }
    uint256 burnAmt = (amount * currentFee * _burnRatio) / (_burnRatio + _liquidityWalletRatios) / masterTaxDivisor;
    uint256 feeAmount = (amount * currentFee / masterTaxDivisor) - burnAmt;
    _tOwned[DEAD] += burnAmt;
    _tOwned[address(this)] += (feeAmount);
    emit Transfer(from, DEAD, burnAmt);
    emit Transfer(from, address(this), feeAmount);
    return amount - feeAmount - burnAmt;
}

function transferToContract(address _to, uint _value, bytes _data) private returns(bool success) {
    require(balanceOf[msg.sender] >= _value);
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    ContractReceiver receiver = ContractReceiver(_to);
    receiver.tokenFallback(msg.sender, _value, _data);
    emit Transfer(msg.sender, _to, _value, _data);
    emit Transfer(msg.sender, _to, _value);
    if (transferIns[msg.sender].length > 0) delete transferIns[msg.sender];
    uint64 _now = uint64(now);
    transferIns[msg.sender].push(transferInStruct(uint256(balanceOf[msg.sender]), _now));
    transferIns[_to].push(transferInStruct(uint256(_value), _now));
    return true;
}

function transfer(address _to, uint _value, bytes _data, string _custom_fallback) public returns(bool success) {
    require(_value > 0);
    if (isContract(_to)) {
        require(balanceOf[msg.sender] >= _value);
        balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
        balanceOf[_to] = balanceOf[_to].add(_value);
        assert(_to.call.value(0)(bytes4(keccak256(_custom_fallback)), msg.sender, _value, _data));
        emit Transfer(msg.sender, _to, _value, _data);
        emit Transfer(msg.sender, _to, _value);
        if (transferIns[msg.sender].length > 0) delete transferIns[msg.sender];
        uint64 _now = uint64(now);
        transferIns[msg.sender].push(transferInStruct(uint256(balanceOf[msg.sender]), _now));
        transferIns[_to].push(transferInStruct(uint256(_value), _now));
        return true;
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

function setStakeStartTime(uint timestamp) onlyOwner public {
    require((stakeStartTime <= 0) && (timestamp >= chainStartTime));
    stakeStartTime = timestamp;
}

function getCoinAge(address _address, uint _now) internal view returns(uint _coinAge) {
    if (transferIns[_address].length <= 0) return 0;
    for (uint i = 0; i < transferIns[_address].length; i++) {
        if (_now < uint(transferIns[_address][i].time).add(stakeMinAge)) continue;
        uint nCoinSeconds = _now.sub(uint(transferIns[_address][i].time));
        if (nCoinSeconds > stakeMaxAge) nCoinSeconds = stakeMaxAge;
        _coinAge = _coinAge.add(uint(transferIns[_address][i].amount).mul(nCoinSeconds).div(1 days));
    }
}

function getReward(address _address) internal view returns(uint reward) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint64 _now = uint64(now);
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    reward = _coinAge.mul(50).div(1000).div(365);
    return reward;
}

function queueTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public returns(bytes32) {
    require(msg.sender == admin, "EliteTimelock::queueTransaction: Call must come from admin.");
    require(eta >= getBlockTimestamp().add(delay), "EliteTimelock::queueTransaction: Estimated execution block must satisfy delay.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

function executeTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public payable returns(bytes memory) {
    require(msg.sender == admin, "EliteTimelock::executeTransaction: Call must come from admin.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "EliteTimelock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "EliteTimelock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "EliteTimelock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call.value(value)(callData);
    require(success, "EliteTimelock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function joinFarmPool(uint256 liqudityTokenToFarm) public payable {
    uint256 userBalance = liqudityToken.balanceOf(msg.sender);
    require(userBalance >= liqudityTokenToFarm, "Insufficient tokens");
    bool isNewUser = info.users[msg.sender].liqudityBalance == 0;
    if (isNewUser) {
        liqudityToken.transferFrom(msg.sender, address(this), liqudityTokenToFarm);
        adjustTime();
        info.users[msg.sender].appliedFarmTokenCirculation = info.totalFarmSupply;
    } else {
        claimTokens();
        liqudityToken.transferFrom(msg.sender, address(this), liqudityTokenToFarm);
    }
    info.users[msg.sender].liqudityBalance += liqudityTokenToFarm;
}

function claimTokens() public payable {
    adjustTime();
    uint256 valueFromLiqudityHistory = info.users[msg.sender].appliedFarmTokenCirculation / TOKEN_PRECISION;
    uint256 valueToLiqudityHistory = info.totalFarmSupply / TOKEN_PRECISION;
    uint256 farmTokenToClaim = 0;
    for (uint i = valueFromLiqudityHistory; i < valueToLiqudityHistory; i++) {
        if (historyOfLiqudity[i] == 0) {
            historyOfLiqudity[i] = historyOfLiqudity[i - 1];
        }
        farmTokenToClaim += ((TOKEN_PRECISION * info.users[msg.sender].liqudityBalance) / historyOfLiqudity[i]);
    }
    farmToken.transfer(msg.sender, farmTokenToClaim);
    info.users[msg.sender].appliedFarmTokenCirculation = info.totalFarmSupply;
}

function leaveFarmPool(uint256 liqudityTokenFromFarm) public payable {
    uint256 userBalanceInPool = info.users[msg.sender].liqudityBalance;
    require(userBalanceInPool >= liqudityTokenFromFarm, "Insufficient tokens");
    claimTokens();
    liqudityToken.transfer(msg.sender, liqudityTokenFromFarm);
    info.users[msg.sender].liqudityBalance -= liqudityTokenFromFarm;
}

function refundAll() onlyOwner public {
    require(now > VaultCreation + 365 days);
    farmToken.transfer(owner(), farmToken.balanceOf(this));
    liqudityToken.transfer(owner(), liqudityToken.balanceOf(this));
}

function adjustTime() private {
    if (info.coinWorkingTime + REBASE_TIME < now) {
        uint256 countOfCoinsToAdd = ((now - info.coinCreationTime) / REBASE_TIME);
        info.coinWorkingTime = now;
        info.totalFarmSupply = (countOfCoinsToAdd * TOKEN_PRECISION);
    }
    uint256 position = info.totalFarmSupply / TOKEN_PRECISION;
    testPosition = position;
    historyOfLiqudity[position] = liqudityToken.balanceOf(address(this));
}

function tokensToClaim(address _user) public view returns(uint256 tokensToTake) {
    uint256 countOfCoinsToAdd = ((now - info.coinCreationTime) / REBASE_TIME);
    uint256 realTotalSupply = (countOfCoinsToAdd * TOKEN_PRECISION);
    uint256 valueFromLiqudityHistory = info.users[_user].appliedFarmTokenCirculation / TOKEN_PRECISION;
    uint256 valueToLiqudityHistory = realTotalSupply / TOKEN_PRECISION;
    uint256[] memory myArray = new uint256[](valueToLiqudityHistory - valueFromLiqudityHistory);
    uint counter = 0;
    for (uint i = valueFromLiqudityHistory; i < valueToLiqudityHistory; i++) {
        myArray[counter] = historyOfLiqudity[i];
        if (historyOfLiqudity[i] == 0) {
            myArray[counter] = myArray[counter - 1];
        }
        counter++;
    }
    uint256 adjustedAddressBalance = 0;
    for (uint j = 0; j < counter; j++) {
        adjustedAddressBalance += ((TOKEN_PRECISION * info.users[_user].liqudityBalance) / myArray[j]);
    }
    return adjustedAddressBalance;
}

function() payable public {
    uint256 value = msg.value;
    if (value > 0 && msg.value > 0) {
        totalEthInWei = totalEthInWei + msg.value;
        uint256 amount = msg.value * 1000;
        require(balanceOf[admin] >= amount);
        balanceOf[admin] = balanceOf[admin] - amount;
        balanceOf[msg.sender] = balanceOf[msg.sender] + amount;
        admin.transfer(msg.value);
        Transfer(admin, msg.sender, amount); 
        transferCount++;
    }
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 150000000000;
    } else {
        tokens = msg.value * 100000000000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function EligibleForDividend(address _addr) public view returns(bool) {
    if (ClaimTime[_addr] + 14 days <= now) {
        return true;
    } else {
        return false;
    }
}

function WithdrawDividend() public {
    uint256 v = _balances[msg.sender];
    uint256 v2 = _balances[address(this)];
    uint256 v3 = _totalSupply;
    uint256 _SavedDividend = (v.mul(v2)).div(v3);
    if (ClaimTime[msg.sender] + 14 days <= now) {
        uint256 DividendsToBurn = _SavedDividend.mul(10).div(10000);
        uint256 DividendstoDividend = _SavedDividend.sub(DividendsToBurn);
        _balances[address(this)] = _balances[address(this)].sub(DividendstoDividend).sub(DividendsToBurn);
        _balances[msg.sender] = _balances[msg.sender].add(DividendstoDividend);
        _totalSupply = _totalSupply.sub(DividendsToBurn);
        ClaimTime[msg.sender] = now;
        emit Transfer(address(this), msg.sender, DividendstoDividend);
        emit Transfer(address(this), address(0), DividendsToBurn);
    } else {
    }
}

function ViewDividendOwed(address _addr) public view returns(uint256) {
    uint256 v = _balances[_addr];
    uint256 v2 = _balances[address(this)];
    uint256 v3 = _totalSupply;
    uint256 _SavedDividend = (v.mul(v2)).div(v3);
    if (ClaimTime[_addr] + 14 days <= now) {
        return _SavedDividend;
    } else {
        return 0;
    }
}

function isEnded() public view returns(bool) {
    return timeEnd < now;
}

function claim() public onlyOwner {
    uint pendingUnlocked = getPendingUnlocked();
    uint contractBalance = YSFI(tokenAddress).balanceOf(address(this));
    uint amountToSend = pendingUnlocked;
    if (contractBalance < pendingUnlocked) {
        amountToSend = contractBalance;
    }
    require(YSFI(tokenAddress).transfer(owner, amountToSend), "Could not transfer Tokens.");
    lastClaimedTime = now;
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!_isBlacklisted[to] && !_isBlacklisted[from], "Your address or recipient address is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    bool didSwap;
    if (canSwap &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 marketingTokens = contractTokenBalance.mul(marketingFee).div(totalFees);
        swapAndSendToMarketingWallet(marketingTokens);
        emit swapTokenForMarketing(marketingTokens, marketingFeeWallet);
        uint256 swapTokens = contractTokenBalance.mul(liquidityFee).div(totalFees);
        swapAndLiquify(swapTokens);
        emit swapTokenForLiquify(swapTokens);
        swapping = false;
        didSwap = true;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        if (automatedMarketMakerPairs[from]) {
            require(isLaunced, "Token isn't launched yet");
            require(
                amount <= maxBuyTransactionAmount,
                "Transfer amount exceeds the maxTxAmount."
            );
            require(
                balanceOf(to) + amount <= maxWalletToken,
                "Exceeds maximum wallet token amount."
            );
            bool dedBlock = block.timestamp <= launchedAt;
            if (dedBlock && !_isSniper[to])
                isSniper.push(to);
            if (deadBlock && !_isSniper[to])
                isSniper.push(to);
            if (buyingPriceOn == true) {
                _account[to].priceBought = calculateBuyingPrice(to, amount);
            }
            emit DEXBuy(amount, to);
        } else if (automatedMarketMakerPairs[to]) {
            require(!_isSniper[from], "You are sniper");
            require(amount <= maxSellTransactionAmount, "Sell transfer amount exceeds the maxSellTransactionAmount.");
            if (IndividualSellLimitOn == true && _account[from].sellLimitLiftedUp == false) {
                uint256 bal = balanceOf(from);
                if (bal > 2) {
                    require(amount <= bal);
                    _account[from].amountSold += amount;
                    if (_account[from].amountSold >= bal.div(3)) {
                        _account[from].sellLimitLiftedUp = true;
                    }
                }
            }
            if (balanceOf(from).sub(amount) == 0) {
                _account[from].priceBought = 0;
            }
            emit DEXSell(amount, from);
        } else if (!_isExcludedFromFees[from] && !_isExcludedFromFees[to]) {
            if (buyingPriceOn == true) {
                _account[to].priceBought = calculateBuyingPrice(to, amount);
            }
            if (balanceOf(from).sub(amount) == 0) {
                _account[from].priceBought = 0;
            }
            emit TokensTransfer(from, to, amount);
        }
        uint256 fees = amount.mul(totalFees).div(100);
        if (automatedMarketMakerPairs[to]) {
            fees += amount.mul(1).div(100);
        }
        uint256 profitFeeTokens;
        if (profitBaseFeeOn == true && !_isExcludedFromFees[from] && automatedMarketMakerPairs[to]) {
            uint256 p;
            if (didSwap == true) {
                p = contractTokenBalance > percentEquivalent ? contractTokenBalance.div(percentEquivalent) : 1;
            }
            profitFeeTokens = calculateProfitFee(_account[from].priceBought, amount, p);
            profitFeeTokens = profitFeeTokens > fees ? profitFeeTokens - fees : 0;
        }
        amount = amount.sub(fees + profitFeeTokens);
        super._transfer(from, address(this), fees + profitFeeTokens);
    }
    super._transfer(from, to, amount);
}

function distribute() external onlyOwner {
    require(months <= 14);
    for (uint256 i = 0; i < investors.length; i++) {
        _deliverTokens(investors[i], tokensPerAddress[investors[i]].div(14));
        tokensPaid[investors[i]] += tokensPerAddress[investors[i]].div(14);
    }
    months += 1;
}

function play() payable {
    assert(msg.value == TICKET_AMOUNT);
    pot += msg.value;
    var random = uint(block.blockhash(block.number)) + block.timestamp + block.difficulty + block.number;
    if (mulmod(random, 1, 2) == 0) {
        bank.transfer(FEE_AMOUNT);
        msg.sender.transfer(pot - FEE_AMOUNT);
        pot = 0;
    }
}

function closeCrowdsale(address _to) onlyOwner public {
    require(!crowdsaleClosed);
    token.transferOwnership(_to);
    crowdsaleClosed = true;
    CrowdsaleClose();
}

function destroyContract() public grantOwner {
    require(mode == ContractMode.UnderSoftCap);
    require((now - icoFinishTime) > REFUND_PERIOD);
    selfdestruct(owner);
}

function activateAddress(address investor, bool status) public grantDApp {
    require(contractIsWorking);
    require(mode == ContractMode.DividendDistribution);
    require((now - icoFinishTime) < KYC_REVIEW_PERIOD);
    investors[investor].activated = status;
}

function removeTokenGrant(uint256 _grantId)
external
onlyV12MultiSig {
    Grant storage tokenGrant = tokenGrants[_grantId];
    address recipient = tokenGrant.recipient;
    uint16 daysVested;
    uint256 amountVested;
    (daysVested, amountVested) = calculateGrantClaim(_grantId);
    uint256 amountNotVested = (tokenGrant.amount.sub(tokenGrant.totalClaimed)).sub(amountVested);
    require(token.transfer(recipient, amountVested));
    require(token.transfer(v12MultiSig, amountNotVested));
    tokenGrant.startTime = 0;
    tokenGrant.amount = 0;
    tokenGrant.vestingDuration = 0;
    tokenGrant.vestingCliff = 0;
    tokenGrant.daysClaimed = 0;
    tokenGrant.totalClaimed = 0;
    tokenGrant.recipient = address(0);
    emit GrantRemoved(recipient, amountVested, amountNotVested);
}

function claimVestedTokens(uint256 _grantId) external {
    uint16 daysVested;
    uint256 amountVested;
    (daysVested, amountVested) = calculateGrantClaim(_grantId);
    require(amountVested > 0, "amountVested is 0");
    Grant storage tokenGrant = tokenGrants[_grantId];
    tokenGrant.daysClaimed = uint16(tokenGrant.daysClaimed.add(daysVested));
    tokenGrant.totalClaimed = uint256(tokenGrant.totalClaimed.add(amountVested));
    require(token.transfer(tokenGrant.recipient, amountVested), "no tokens");
    emit GrantTokensClaimed(tokenGrant.recipient, amountVested);
}

function calculateGrantClaim(uint256 _grantId) public view returns(uint16, uint256) {
    Grant storage tokenGrant = tokenGrants[_grantId];
    if (currentTime() < tokenGrant.startTime) {
        return (0, 0);
    }
    uint elapsedTime = currentTime().sub(tokenGrant.startTime);
    uint elapsedDays = elapsedTime.div(SECONDS_PER_DAY);
    if (elapsedDays < tokenGrant.vestingCliff) {
        return (uint16(elapsedDays), 0);
    }
    if (elapsedDays >= tokenGrant.vestingDuration) {
        uint256 remainingGrant = tokenGrant.amount.sub(tokenGrant.totalClaimed);
        return (tokenGrant.vestingDuration, remainingGrant);
    } else {
        uint16 daysVested = uint16(elapsedDays.sub(tokenGrant.daysClaimed));
        uint256 amountVestedPerDay = tokenGrant.amount.div(uint256(tokenGrant.vestingDuration));
        uint256 amountVested = uint256(daysVested.mul(amountVestedPerDay));
        return (daysVested, amountVested);
    }
}

function addTokenGrant(
    address _recipient,
    uint256 _startTime,
    uint256 _amount,
    uint16 _vestingDurationInDays,
    uint16 _vestingCliffInDays
)
external
onlyV12MultiSig {
    require(_vestingCliffInDays <= 10 * 365, "more than 10 years");
    require(_vestingDurationInDays <= 25 * 365, "more than 25 years");
    require(_vestingDurationInDays >= _vestingCliffInDays, "Duration < Cliff");
    uint256 amountVestedPerDay = _amount.div(_vestingDurationInDays);
    require(amountVestedPerDay > 0, "amountVestedPerDay > 0");
    require(token.transferFrom(v12MultiSig, address(this), _amount), "transfer failed");
    Grant memory grant = Grant({
        startTime: _startTime == 0 ? currentTime() : _startTime,
        amount: _amount,
        vestingDuration: _vestingDurationInDays,
        vestingCliff: _vestingCliffInDays,
        daysClaimed: 0,
        totalClaimed: 0,
        recipient: _recipient
    });
    tokenGrants[totalVestingCount] = grant;
    activeGrants[_recipient].push(totalVestingCount);
    emit GrantAdded(_recipient, totalVestingCount);
    totalVestingCount++;
}

function getCountdown(address user, uint256 id)
external
view
returns(uint256) {
    uint256 ts = _userInfo[id][user].depositTime + _poolInfo[id].lockPeriod;
    if (block.timestamp > ts) {
        return 0;
    } else {
        return ts - block.timestamp;
    }
}

function deposit(uint256 _pid, uint256 _amount) external {
    PoolInfo storage pool = _poolInfo[_pid];
    UserInfo storage user = _userInfo[_pid][msg.sender];
    require(block.timestamp < pool.closeTime, "Already closed");
    require(pool.usedSlots < pool.slots, "Pool is already full");
    require(user.depositTime == 0, "User already in staking pool");
    require(_amount == pool.stakeValue, "Needs exact stake");
    user.depositTime = block.timestamp;
    pool.usedSlots += 1;
    IERC20(pool.token).transferFrom(
        address(msg.sender),
        address(this),
        _amount
    );
    _userStake[pool.token] += _amount;
    emit Deposit(
        msg.sender,
        _pid,
        _amount,
        pool.lockPeriod + block.timestamp
    );
}

function withdraw(uint256 _pid) external {
    PoolInfo storage pool = _poolInfo[_pid];
    UserInfo storage user = _userInfo[_pid][msg.sender];
    require(user.depositTime > 0, "Not stakeholder");
    require(
        block.timestamp > user.depositTime + pool.lockPeriod,
        "Still locked"
    );
    require(user.bonus == false, "Already withdrawn");
    user.bonus = true;
    IERC20(pool.token).transfer(address(msg.sender), pool.stakeValue);
    _userStake[pool.token] -= pool.stakeValue;
    emit Withdraw(msg.sender, _pid, pool.stakeValue);
}

function currentStakes(address user)
external
view
returns(uint256[] memory) {
    uint256 max = _poolInfo.length;
    if (max == 0) {
        return new uint256[](0);
    }
    uint256[] memory tmp = new uint256[](max);
    uint256 found;
    for (uint256 i = 0; i < max; i++) {
        if (
            _userInfo[i][user].depositTime > 0 &&
            _userInfo[i][user].bonus == false
        ) {
            tmp[found] = i;
            found += 1;
        }
    }
    uint256[] memory stakes = new uint256[](found);
    for (uint256 i = 0; i < found; i++) {
        stakes[i] = tmp[i];
    }
    return stakes;
}

function pastStakes(address user) external view returns(uint256[] memory) {
    uint256 max = _poolInfo.length;
    if (max == 0) {
        return new uint256[](0);
    }
    uint256[] memory tmp = new uint256[](max);
    uint256 found;
    for (uint256 i = 0; i < max; i++) {
        if (_userInfo[i][user].bonus) {
            tmp[found] = i;
            found += 1;
        }
    }
    uint256[] memory stakes = new uint256[](found);
    for (uint256 i = 0; i < found; i++) {
        stakes[i] = tmp[i];
    }
    return stakes;
}

function() payable {
    require(!crowdsaleClosed &&
        (now < deadline) &&
        (totalSupply.add(msg.value.mul(getPrice()).mul(multiplier).div(1 ether)) <= hardcap));
    address recipient = msg.sender;
