function adoptAxies(
    uint256 _beastQuantity,
    uint256 _aquaticQuantity,
    uint256 _plantQuantity,
    address _referrer
)
external
payable
whenInitialized
whenNotPaused {
    require(now <= PRESALE_END_TIMESTAMP);
    require(_beastQuantity <= 3 && _aquaticQuantity <= 3 && _plantQuantity <= 3);
    uint256 _totalAdopted = this.totalAdoptedAxies(CLASS_BEAST, false)
        .add(this.totalAdoptedAxies(CLASS_AQUATIC, false))
        .add(this.totalAdoptedAxies(CLASS_PLANT, false))
        .add(_beastQuantity)
        .add(_aquaticQuantity)
        .add(_plantQuantity);
    require(_totalAdopted <= MAX_TOTAL_ADOPTED_AXIES);
    address _adopter = msg.sender;
    address _actualReferrer = 0x0;
    if (_referrer != _adopter) {
        _actualReferrer = _referrer;
    }
    uint256 _value = msg.value;
    uint256 _price;
    if (_beastQuantity > 0) {
        _price = _adoptSameClassAxies(
            _adopter,
            CLASS_BEAST,
            _beastQuantity,
            _actualReferrer
        );
        require(_value >= _price);
        _value -= _price;
    }
    if (_aquaticQuantity > 0) {
        _price = _adoptSameClassAxies(
            _adopter,
            CLASS_AQUATIC,
            _aquaticQuantity,
            _actualReferrer
        );
        require(_value >= _price);
        _value -= _price;
    }
    if (_plantQuantity > 0) {
        _price = _adoptSameClassAxies(
            _adopter,
            CLASS_PLANT,
            _plantQuantity,
            _actualReferrer
        );
        require(_value >= _price);
        _value -= _price;
    }
    msg.sender.transfer(_value);
    if (_actualReferrer != 0x0) {
        _applyRefCredits(
            _actualReferrer,
            _beastQuantity.add(_aquaticQuantity).add(_plantQuantity)
        );
    }
}

function adoptAxies(
    uint256 beastQuantity,
    uint256 aquaticQuantity,
    uint256 plantQuantity,
    address referrer
)
public
payable
whenNotPaused {
    require(now <= PRESALE_END_TIMESTAMP);
    require(beastQuantity <= 3);
    require(aquaticQuantity <= 3);
    require(plantQuantity <= 3);
    address adopter = msg.sender;
    address actualReferrer = 0x0;
    if (referrer != adopter) {
        actualReferrer = referrer;
    }
    uint256 value = msg.value;
    uint256 price;
    if (beastQuantity > 0) {
        price = _adoptAxies(
            adopter,
            CLASS_BEAST,
            beastQuantity,
            actualReferrer
        );
        require(value >= price);
        value -= price;
    }
    if (aquaticQuantity > 0) {
        price = _adoptAxies(
            adopter,
            CLASS_AQUATIC,
            aquaticQuantity,
            actualReferrer
        );
        require(value >= price);
        value -= price;
    }
    if (plantQuantity > 0) {
        price = _adoptAxies(
            adopter,
            CLASS_PLANT,
            plantQuantity,
            actualReferrer
        );
        require(value >= price);
        value -= price;
    }
    msg.sender.transfer(value);
    if (actualReferrer != 0x0) {
        uint256 numCredit = referralCredits[actualReferrer]
            .add(beastQuantity)
            .add(aquaticQuantity)
            .add(plantQuantity);
        uint256 numReward = numCredit / REF_CREDITS_PER_AXIE;
        if (numReward > 0) {
            referralCredits[actualReferrer] = numCredit % REF_CREDITS_PER_AXIE;
            axiesRewarded[actualReferrer] = axiesRewarded[actualReferrer].add(numReward);
            totalAxiesRewarded = totalAxiesRewarded.add(numReward);
            AxiesRewarded(actualReferrer, numReward);
        } else {
            referralCredits[actualReferrer] = numCredit;
        }
    }
}

function _redeemSameClassAdoptedAxies(
    address _receiver,
    uint8 _class,
    uint256 _quantity
)
private
returns(uint256 _remainingQuantity) {
    _remainingQuantity = this.numAdoptedAxies(_receiver, _class, true).sub(_quantity);
    if (_quantity > 0) {
        _numDeductedAdoptedAxies[_receiver][_class] = _numDeductedAdoptedAxies[_receiver][_class].add(_quantity);
        _totalDeductedAdoptedAxies[_class] = _totalDeductedAdoptedAxies[_class].add(_quantity);
        AdoptedAxiesRedeemed(_receiver, _class, _quantity);
    }
}

function initialize(address _presaleAddress) external onlyOwner whenNotInitialized {
    presaleContract = AxiePresale(_presaleAddress);
    presaleContract.pause();
    priceIncrement[CLASS_BEAST] = presaleContract.priceIncrements(CLASS_BEAST);
    priceIncrement[CLASS_AQUATIC] = presaleContract.priceIncrements(CLASS_AQUATIC);
    priceIncrement[CLASS_PLANT] = presaleContract.priceIncrements(CLASS_PLANT);
    currentPrice[CLASS_BEAST] = presaleContract.currentPrices(CLASS_BEAST);
    currentPrice[CLASS_AQUATIC] = presaleContract.currentPrices(CLASS_AQUATIC);
    currentPrice[CLASS_PLANT] = presaleContract.currentPrices(CLASS_PLANT);
    paused = false;
}

function redeemRewardedAxies(
    address _receiver,
    uint256 _quantity
)
external
onlyRedemptionAddress
whenInitialized
returns(uint256 _remainingQuantity) {
    _remainingQuantity = this.numRewardedAxies(_receiver, true).sub(_quantity);
    if (_quantity > 0) {
        _numDeductedRewardedAxies[_receiver] = _numDeductedRewardedAxies[_receiver].add(_quantity);
        _totalDeductedRewardedAxies = _totalDeductedRewardedAxies.add(_quantity);
        RewardedAxiesRedeemed(_receiver, _quantity);
    }
}

function _applyRefCredits(address _receiver, uint256 _numAppliedCredits) private {
    _numRefCredits[_receiver] = _numRefCredits[_receiver].add(_numAppliedCredits);
    uint256 _numCredits = this.numRefCredits(_receiver, true);
    uint256 _numRewards = _numCredits / REF_CREDITS_PER_AXIE;
    if (_numRewards > 0) {
        _numDeductedRefCredits[_receiver] = _numDeductedRefCredits[_receiver]
            .add(_numRewards.mul(REF_CREDITS_PER_AXIE));
        _numRewardedAxies[_receiver] = _numRewardedAxies[_receiver].add(_numRewards);
        _totalRewardedAxies = _totalRewardedAxies.add(_numRewards);
        AxiesRewarded(_receiver, _numRewards);
    }
}

function endCrowdfund(address companyAddress) onlyOwner public returns(bool) {
    require(isPhase3CrowdsaleActive == true);
    require(now >= endCrowdsalePhase3Date);
    uint256 remaining = token.balanceOf(this);
    require(token.transfer(companyAddress, remaining));
}

function getState() view public returns(State) {
    if (now >= startPrivatesaleDate && isPrivatesaleActive == true) {
        return State.PrivateSale;
    }
    if (now >= startPresaleDate && now <= endPresaleDate) {
        require(isPresaleActive == true);
        return State.PreSale;
    }
    if (now >= startCrowdsalePhase1Date && now <= endCrowdsalePhase1Date) {
        require(isPhase1CrowdsaleActive == true);
        return State.CrowdSalePhase1;
    }
    if (now >= startCrowdsalePhase2Date && now <= endCrowdsalePhase2Date) {
        require(isPhase2CrowdsaleActive == true);
        return State.CrowdSalePhase2;
    }
    if (now >= startCrowdsalePhase3Date && now <= endCrowdsalePhase3Date) {
        require(isPhase3CrowdsaleActive == true);
        return State.CrowdSalePhase3;
    }
    return State.Gap;
}

function buyTokens(address _investorAddress)
public
payable
returns(bool) {
    require(whitelist.checkWhitelist(_investorAddress));
    if ((getState() == State.PreSale) ||
        (getState() == State.CrowdSalePhase1) ||
        (getState() == State.CrowdSalePhase2) ||
        (getState() == State.CrowdSalePhase3) ||
        (getState() == State.PrivateSale)) {
        uint256 amount;
        require(_investorAddress != address(0));
        require(tokenAddress != address(0));
        require(msg.value >= MIN_INVESTMENT);
        amount = getTokenAmount(msg.value);
        require(fundTransfer(msg.value));
        require(token.transfer(_investorAddress, amount));
        ethRaised = ethRaised.add(msg.value);
        soldToken = soldToken.add(amount);
        emit TokenBought(_investorAddress, amount, now);
        return true;
    } else {
        revert();
    }
}

function gameResult() private {
    uint index = getRamdon();
    address lastAddress = addressArray[index];
    uint totalBalace = address(this).balance;
    uint giveToOwn = totalBalace * curConfig.pumpRate / 100;
    uint giveToActor = totalBalace - giveToOwn;
    owner.transfer(giveToOwn);
    lastAddress.transfer(giveToActor);
    emit GameOverEvent(
        gameIndex,
        curConfig.totalSize,
        curConfig.singlePrice,
        curConfig.pumpRate,
        lastAddress,
        now);
}

function addPlayer() public payable {
    require(msg.value == curConfig.singlePrice);
    totalPrice = totalPrice + msg.value;
    addressArray.push(msg.sender);
    emit addPlayerEvent(gameIndex, msg.sender);
    if (addressArray.length >= curConfig.totalSize) {
        gameResult();
        startNewGame();
    }
}

function transfer(address _to, uint _value, bytes _data) public returns(bool success) {
    require(_value > 0 &&
        cannotSend[msg.sender] == false &&
        cannotReceive[_to] == false &&
        now > cannotSendUntil[msg.sender] &&
        now > cannotReceiveUntil[_to]);
    if (isContract(_to)) {
        return transferToContract(_to, _value, _data);
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(_to != address(0) &&
        _value > 0 &&
        balanceOf[_from] >= _value &&
        allowance[_from][msg.sender] >= _value &&
        cannotSend[msg.sender] == false &&
        cannotReceive[_to] == false &&
        now > cannotSendUntil[msg.sender] &&
        now > cannotReceiveUntil[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function transferFromTo(address _from, address _to, uint256 _value, bytes _data) onlyAuthorized public returns(bool) {
    require(_value > 0 &&
        balanceOf[_from] >= _value &&
        cannotSend[_from] == false &&
        cannotReceive[_to] == false &&
        now > cannotSendUntil[_from] &&
        now > cannotReceiveUntil[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    if (isContract(_to)) {
        ContractReceiver receiver = ContractReceiver(_to);
        receiver.tokenFallback(_from, _value, _data);
    }
    emit Transfer(_from, _to, _value, _data);
    emit Transfer(_from, _to, _value);
    return true;
}

function batchTransfer(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        cannotSend[msg.sender] == false &&
        now > cannotSendUntil[msg.sender]);
    amount = amount.mul(1e8);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint i = 0; i < addresses.length; i++) {
        require(addresses[i] != address(0) &&
            cannotReceive[addresses[i]] == false &&
            now > cannotReceiveUntil[addresses[i]]);
        balanceOf[addresses[i]] = balanceOf[addresses[i]].add(amount);
        emit Transfer(msg.sender, addresses[i], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function donate() public {
    assert(donated == false);
    require(msg.sender == owner || msg.sender == charityAddress);
    require(hasExpired());
    assert(!manuallyEnded);
    assert(bids.length > 0);
    uint _amount;
    if (bids.length == 1) {
        _amount = bids[0].amount;
    } else {
        _amount = bids[SafeMath.sub(bids.length, 2)].amount;
    }
    assert(_amount > 0);
    donated = true;
    charityAddress.transfer(_amount);
    Donated(_amount);
}

function reclaim() public {
    address _caller = msg.sender;
    uint _amount = calcAmtReclaimable(_caller);
    require(bids.length >= 2);
    require(!manuallyEnded);
    require(_amount > 0);
    uint _newTotal = SafeMath.sub(addressBalance[_caller], _amount);
    assert(_newTotal >= 0);
    addressBalance[_caller] = _newTotal;
    _caller.transfer(_amount);
    Reclaimed(_caller, _amount);
}

function bid(string _email, string _organisation) public payable {
    address _bidder = msg.sender;
    uint _amount = msg.value;
    uint _id = bids.length;
    require(!hasExpired() && !manuallyEnded);
    require(_bidder != owner && _bidder != charityAddress);
    require(_bidder != address(0));
    require(bytes(_email).length > 0);
    require(bytes(_organisation).length > 0);
    require(_amount >= calcCurrentMinBid());
    bids.push(Bid(true, _id, now, _bidder, _amount, _email, _organisation));
    bidIds.push(_id);
    addressBalance[_bidder] = SafeMath.add(addressBalance[_bidder], _amount);
    BidMade(_id, _bidder, _amount);
}

function calcAmtReclaimable(address _bidder) public view returns(uint) {
    uint _totalAmt = addressBalance[_bidder];
    if (bids.length == 0) {
        return 0;
    }
    if (bids[SafeMath.sub(bids.length, 1)].bidder == _bidder) {
        if (hasExpired()) { 
            uint _secondPrice = bids[SafeMath.sub(bids.length, 2)].amount;
            return SafeMath.sub(_totalAmt, _secondPrice);
        } else { 
            uint _highestPrice = bids[SafeMath.sub(bids.length, 1)].amount;
            return SafeMath.sub(_totalAmt, _highestPrice);
        }
    } else { 
        return _totalAmt;
    }
}

function hasExpired() public view returns(bool) {
    uint _numBids = bids.length;
    if (_numBids == 0) {
        return false;
    } else {
        return now >= this.expiryTimestamp();
    }
}

function expiryTimestamp() public view returns(uint) {
    uint _numBids = bids.length;
    require(_numBids > 0);
    uint _lastBidTimestamp = bids[SafeMath.sub(_numBids, 1)].timestamp;
    if (_numBids <= INITIAL_BIDS) {
        return SafeMath.add(_lastBidTimestamp, EXPIRY_DAYS_BEFORE);
    } else {
        return SafeMath.add(_lastBidTimestamp, EXPIRY_DAYS_AFTER);
    }
}

function calcCurrentMinBid() public view returns(uint) {
    if (bids.length == 0) {
        return MIN_BID;
    } else {
        uint _lastBidId = SafeMath.sub(bids.length, 1);
        uint _lastBidAmt = bids[_lastBidId].amount;
        return SafeMath.add(_lastBidAmt, BID_STEP);
    }
}

function manuallyEndAuction() public onlyOwner {
    require(manuallyEnded == false);
    require(bids.length == 0);
    manuallyEnded = true;
}

function() public payable {
    if (IsDistribRunning) {
        uint256 _amount;
        if (((_CurrentDistribPublicSupply + _amount) > _MaxDistribPublicSupply) && _MaxDistribPublicSupply > 0) revert();
        if (!_DistribFundsReceiverAddress.send(msg.value)) revert();
        if (Claimed[msg.sender] == false) {
            _amount = _FreeQDA * 1e18;
            _CurrentDistribPublicSupply += _amount;
            balances[msg.sender] += _amount;
            _totalSupply += _amount;
            Transfer(this, msg.sender, _amount);
            Claimed[msg.sender] = true;
        }
        if (msg.value >= 9e15) {
            _amount = msg.value * _ExtraTokensPerETHSended * 4;
        } else {
            if (msg.value >= 6e15) {
                _amount = msg.value * _ExtraTokensPerETHSended * 3;
            } else {
                if (msg.value >= 3e15) {
                    _amount = msg.value * _ExtraTokensPerETHSended * 2;
                } else {
                    _amount = msg.value * _ExtraTokensPerETHSended;
                }
            }
        }
        _CurrentDistribPublicSupply += _amount;
        balances[msg.sender] += _amount;
        _totalSupply += _amount;
        Transfer(this, msg.sender, _amount);
    } else {
        revert();
    }
}

