function participate(string referral) public payable {
    require(referralCodes[referral] != 0);
    require(members[msg.sender] == 0);
    require(msg.value == PARTICIPATION_FEE);
    address referrer = referralCodes[referral];
    members[msg.sender] = referrer;
    string memory alphabetHash = hash(msg.sender);
    referralCodes[alphabetHash] = msg.sender;
    for (uint16 i = 0; i < 5; i++) {
        if (referrer == 1) {
            break;
        }
        uint256 amount = SafeMath.div(SafeMath.mul(msg.value, REFERRAL_RATE[i]), 100);
        referrer.transfer(amount);
        referrer = members[referrer];
    }
    memberCount++;
    HasNewMember(memberCount);
}

function enter(uint256 _amount) public {
    require(initialBlock + totalBlocks > block.number, "Staking Period Over");
    bool available = false;
    uint256 usersTokens = lpToken.balanceOf(msg.sender);
    uint256 allowedTokens = lpToken.allowance(msg.sender, address(this));
    uint256 stakeAmount;
    require(usersTokens >= _amount, "Insufficient Balance to Stake");
    require(allowedTokens >= _amount, "Allowed balance is Insufficient");
    lpToken.transferFrom(msg.sender, address(this), _amount);
    _mint(msg.sender, _amount);
    stakes[msg.sender][stakeCount[msg.sender]] = stakeData(
        msg.sender,
        _amount,
        block.number
    );
    stakeCount[msg.sender] += 1;
    for (uint i = 0; i < stakers.length; i++) {
        if (stakers[i] == msg.sender) {
            available = true;
            break;
        } else {
            continue;
        }
    }
    if (!available) {
        stakers.push(msg.sender);
    }
    for (uint256 j = 0; j < stakers.length; j++) {
        for (uint256 i = 0; i < stakeCount[stakers[j]]; i++) {
            stakeAmount += stakes[stakers[j]][i].amount;
        }
    }
    dataLog[block.number] = rate * (block.number - savedPos) * 10 ** 18 / stakeAmount;
    savedPos = block.number;
}

function safeSend(address _address) internal {
    uint valueToSend = pendingReturns[_address];
    assert(valueToSend > 0);
    pendingReturns[_address] = 0;
    if (_address.send(valueToSend) == false) {
        pendingReturns[_address] = valueToSend;
    }
}

function closeGame(
    Game storage _game,
    uint _gameId,
    uint32 _roundId,
    address _userAddress,
    ReasonEnded _reason,
    int _balance
)
internal {
    _game.status = GameStatus.ENDED;
    activeGames = activeGames.sub(1);
