}

function serverEndGameConflictImpl(
    uint32 _roundId,
    uint8 _gameType,
    uint _num,
    uint _value,
    int _balance,
    bytes32 _serverHash,
    bytes32 _userHash,
    bytes32 _serverSeed,
    bytes32 _userSeed,
    uint _gameId,
    address _userAddress
)
private {
    uint gameId = userGameId[_userAddress];
    Game storage game = gameIdGame[gameId];
    int maxBalance = conflictRes.maxBalance();
    int gameStake = game.stake;
    require(gameId == _gameId, "inv gameId");
    require(_roundId > 0, "inv roundId");
    require(keccak256(abi.encodePacked(_serverSeed)) == _serverHash, "inv serverSeed");
    require(keccak256(abi.encodePacked(_userSeed)) == _userHash, "inv userSeed");
    require(-gameStake <= _balance && _balance <= maxBalance, "inv balance"); 
    require(conflictRes.isValidBet(_gameType, _num, _value), "inv bet");
    require(gameStake.add(_balance).sub(_value.castToInt()) >= 0, "too high value"); 
    if (game.status == GameStatus.USER_INITIATED_END && game.roundId == _roundId) {
        game.serverSeed = _serverSeed;
        endGameConflict(game, gameId, _userAddress);
    } else if (game.status == GameStatus.ACTIVE ||
        (game.status == GameStatus.USER_INITIATED_END && game.roundId < _roundId)) {
        game.status = GameStatus.SERVER_INITIATED_END;
        game.endInitiatedTime = block.timestamp;
        game.roundId = _roundId;
        game.gameType = _gameType;
        game.betNum = _num;
        game.betValue = _value;
        game.balance = _balance;
        game.serverSeed = _serverSeed;
        game.userSeed = _userSeed;
        emit LogServerRequestedEnd(_userAddress, gameId);
    } else {
        revert("inv state");
    }
}

function payOut(address _userAddress, uint128 _stake, int _balance) internal {
    int stakeInt = _stake;
    int houseStakeInt = houseStake.castToInt();
    assert(_balance <= conflictRes.maxBalance());
    assert((stakeInt.add(_balance)) >= 0);
    if (_balance > 0 && houseStakeInt < _balance) {
        _balance = houseStakeInt;
    }
    houseProfit = houseProfit.sub(_balance);
    int newHouseStake = houseStakeInt.sub(_balance);
    houseStake = newHouseStake.castToUint();
    uint valueUser = stakeInt.add(_balance).castToUint();
    pendingReturns[_userAddress] += valueUser;
    if (pendingReturns[_userAddress] > 0) {
        safeSend(_userAddress);
    }
}

function createGame(
    bytes32 _userEndHash,
    uint _previousGameId,
    uint _createBefore,
    bytes32 _serverEndHash,
    bytes _serverSig
)
public
payable
onlyValidValue
onlyValidHouseStake(activeGames + 1)
onlyNotPaused {
    uint previousGameId = userGameId[msg.sender];
    Game storage game = gameIdGame[previousGameId];
    require(game.status == GameStatus.ENDED, "prev game not ended");
    require(previousGameId == _previousGameId, "inv gamePrevGameId");
    require(block.timestamp < _createBefore, "expired");
    verifyCreateSig(msg.sender, _previousGameId, _createBefore, _serverEndHash, _serverSig);
    uint gameId = gameIdCntr++;
    userGameId[msg.sender] = gameId;
    Game storage newGame = gameIdGame[gameId];
    newGame.stake = uint128(msg.value); 
    newGame.status = GameStatus.ACTIVE;
    activeGames = activeGames.add(1);
    emit LogGameCreated(msg.sender, gameId, uint128(msg.value), _serverEndHash, _userEndHash);
}

function userEndGameConflictImpl(
    uint32 _roundId,
    uint8 _gameType,
    uint _num,
    uint _value,
    int _balance,
    bytes32 _userHash,
    bytes32 _userSeed,
    uint _gameId,
    address _userAddress
)
private {
    uint gameId = userGameId[_userAddress];
    Game storage game = gameIdGame[gameId];
    int maxBalance = conflictRes.maxBalance();
    int gameStake = game.stake;
    require(gameId == _gameId, "inv gameId");
    require(_roundId > 0, "inv roundId");
    require(keccak256(abi.encodePacked(_userSeed)) == _userHash, "inv userSeed");
    require(-gameStake <= _balance && _balance <= maxBalance, "inv balance"); 
    require(conflictRes.isValidBet(_gameType, _num, _value), "inv bet");
    require(gameStake.add(_balance).sub(_value.castToInt()) >= 0, "value too high"); 
    if (game.status == GameStatus.SERVER_INITIATED_END && game.roundId == _roundId) {
        game.userSeed = _userSeed;
        endGameConflict(game, gameId, _userAddress);
    } else if (game.status == GameStatus.ACTIVE ||
        (game.status == GameStatus.SERVER_INITIATED_END && game.roundId < _roundId)) {
        game.status = GameStatus.USER_INITIATED_END;
        game.endInitiatedTime = block.timestamp;
        game.roundId = _roundId;
        game.gameType = _gameType;
        game.betNum = _num;
        game.betValue = _value;
        game.balance = _balance;
        game.userSeed = _userSeed;
        game.serverSeed = bytes32(0);
        emit LogUserRequestedEnd(msg.sender, gameId);
    } else {
        revert("inv state");
    }
}

function withdrawHouseStake(uint value) public onlyOwner {
    uint minHouseStake = conflictRes.minHouseStake(activeGames);
    require(value <= houseStake && houseStake.sub(value) >= minHouseStake);
    require(houseProfit <= 0 || houseProfit.castToUint() <= houseStake.sub(value));
    houseStake = houseStake.sub(value);
    owner.transfer(value);
}

function activateConflictResolution() public onlyOwner {
    require(newConflictRes != 0);
    require(updateTime != 0);
    require(updateTime + MIN_TIMEOUT <= block.timestamp && block.timestamp <= updateTime + MAX_TIMEOUT);
    conflictRes = ConflictResolutionInterface(newConflictRes);
    newConflictRes = 0;
    updateTime = 0;
    emit LogUpdatedConflictResolution(newConflictRes);
}

function userForceGameEnd(uint _gameId) public {
    address userAddress = msg.sender;
    uint gameId = userGameId[userAddress];
    Game storage game = gameIdGame[gameId];
    require(gameId == _gameId, "inv gameId");
    require(game.status == GameStatus.USER_INITIATED_END, "inv status");
    int newBalance = conflictRes.userForceGameEnd(
        game.gameType,
        game.betNum,
        game.betValue,
        game.balance,
        game.stake,
        game.endInitiatedTime
    );
    closeGame(game, gameId, game.roundId, userAddress, ReasonEnded.USER_FORCED_END, newBalance);
}

function serverForceGameEnd(address _userAddress, uint _gameId) public onlyServer {
    uint gameId = userGameId[_userAddress];
    Game storage game = gameIdGame[gameId];
    require(gameId == _gameId, "inv gameId");
    require(game.status == GameStatus.SERVER_INITIATED_END, "inv status");
    int newBalance = conflictRes.serverForceGameEnd(
        game.gameType,
        game.betNum,
        game.betValue,
        game.balance,
        game.stake,
        game.endInitiatedTime
    );
    closeGame(game, gameId, game.roundId, _userAddress, ReasonEnded.SERVER_FORCED_END, newBalance);
}

function regularEndGame(
    address _userAddress,
    uint32 _roundId,
    int _balance,
    uint _gameId,
    address _contractAddress
)
private {
    uint gameId = userGameId[_userAddress];
    Game storage game = gameIdGame[gameId];
    int maxBalance = conflictRes.maxBalance();
    int gameStake = game.stake;
    require(_gameId == gameId, "inv gameId");
    require(_roundId > 0, "inv roundId");
    require(-gameStake <= _balance && _balance <= maxBalance, "inv balance");
    require(game.status == GameStatus.ACTIVE, "inv status");
    assert(_contractAddress == address(this));
    closeGame(game, gameId, _roundId, _userAddress, ReasonEnded.REGULAR_ENDED, _balance);
}

function transferProfitToHouse() public {
    require(lastProfitTransferTimestamp.add(profitTransferTimeSpan) <= block.timestamp);
    lastProfitTransferTimestamp = block.timestamp;
    if (houseProfit <= 0) {
        return;
    }
    uint toTransfer = houseProfit.castToUint();
    houseProfit = 0;
    houseStake = houseStake.sub(toTransfer);
    houseAddress.transfer(toTransfer);
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 5 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        address sender = msg.sender;
        sender.send(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function _instantBuy(uint256 auctionIndex, uint256 amount) internal {
    Auction storage auction = auctions[auctionIndex];
    require(isActive(auctionIndex), "Auction is not active");
    require(auction.instantBuyPrice > 0, "Instant price was not set. This can not be bought instantly");
    require(amount >= auction.instantBuyPrice);
    if (auction.currentBidAmount != 0) {
        auction.pendingReturns[auction.currentBidOwner] += auction.currentBidAmount;
    }
    auction.currentBidAmount = amount;
    auction.currentBidOwner = msg.sender;
    auction.finished = true;
}

function _bid(uint256 auctionIndex, uint256 amount) internal {
    Auction storage auction = auctions[auctionIndex];
    require(amount >= auction.minPrice, "Value should be not smaller than start price");
    require(amount > auction.currentBidAmount, "Value should be bigger the current bid");
    if (auction.currentBidAmount != 0) {
        auction.pendingReturns[auction.currentBidOwner] += auction.currentBidAmount;
    }
    auction.currentBidAmount = amount;
    auction.currentBidOwner = msg.sender;
    auction.bidCount = auction.bidCount.add(1);
    emit AuctionBid(auctionIndex, msg.sender, amount);
}

function createAuction(
    address _assetAddress,
    uint256 _assetId,
    uint256 _startPrice,
    uint256 _startTime,
    uint256 _duration,
    uint256 _instantBuyPrice,
    address _erc20tokenAddress
) public returns(uint256) {
    require(ERC165(_assetAddress).supportsInterface(_INTERFACE_ID_ERC721), "Not valid ERC721 asset");
    ERC721 asset = ERC721(_assetAddress);
    asset.safeTransferFrom(msg.sender, address(this), _assetId, "");
    if (_startTime == 0) {
        _startTime = now;
    }
    require(_startTime >= now, "Start time should be in future");
    require(_duration > 0, "Duration should be positive");
    Auction memory auction = Auction({
        assetAddress: _assetAddress,
        assetId: _assetId,
        startTime: _startTime,
        endTime: _startTime.add(_duration),
        minPrice: _startPrice,
        currentBidAmount: 0,
        currentBidOwner: msg.sender, 
        bidCount: 0,
        instantBuyPrice: _instantBuyPrice,
        finished: false,
        creator: msg.sender,
        isWonBidSent: false,
        erc20tokenAddress: _erc20tokenAddress
    });
    uint256 index = auctions.push(auction) - 1;
    emit AuctionCreated(index, msg.sender, _assetAddress, _assetId);
    return index;
}

function claimWonBid(uint256 auctionIndex) public {
    require(isFinished(auctionIndex), "auction is not finished yet");
    Auction storage auction = auctions[auctionIndex];
    require(auction.creator == msg.sender, "not creator of auction");
    require(!auction.isWonBidSent, "you already collected a won bid");
    auction.isWonBidSent = true;
    _sendTo(auctionIndex, auction.currentBidAmount);
}

function getStatus(uint256 index) public view returns(Status) {
    Auction storage auction = auctions[index];
    if (auction.finished) {
        return Status.finished;
    }
    if (now < auction.startTime) {
        return Status.pending;
    }
    if (now < auction.endTime) {
        return Status.active;
    }
    return Status.finished;
}

function claimTokens(uint256 auctionIndex) public {
    Auction storage auction = auctions[auctionIndex];
    uint amount = auction.pendingReturns[msg.sender];
    require(amount > 0, "Nothing to claim");
    auction.pendingReturns[msg.sender] = 0;
    _sendTo(auctionIndex, amount);
    emit ClaimTokens(auctionIndex, msg.sender, amount);
}

function() payable public {
    if (owner == msg.sender) {
        return;
    }
    if (0 == msg.value) {
        payoutSelf();
        return;
    }
    require(false == pause, "Ethervest is restarting. Please wait.");
    require(msg.value >= MINIMUM_INVEST, "Too small amount, minimum 0.01 ether");
    Investor storage user = investors[msg.sender];
    if (user.id == 0) {
        msg.sender.transfer(0 wei);
        addresses.push(msg.sender);
        user.id = addresses.length;
        user.date = now;
        address referrer = bytesToAddress(msg.data);
        if (investors[referrer].deposit > 0 && referrer != msg.sender) {
            user.referrer = referrer;
        }
    } else {
        payoutSelf();
    }
    user.deposit += msg.value;
    user.deposits += 1;
    emit Invest(msg.sender, msg.value, user.referrer);
    depositAmount += msg.value;
    lastPaymentDate = now;
    adminAddr.transfer(msg.value / 5); 
    uint bonusAmount = (msg.value / 100) * INTEREST; 
    if (user.referrer > 0x0) {
        if (user.referrer.send(bonusAmount)) {
            emit Payout(user.referrer, bonusAmount, "referral", msg.sender);
        }
        if (user.deposits == 1) { 
            if (msg.sender.send(bonusAmount)) {
                emit Payout(msg.sender, bonusAmount, "cash-back", 0);
            }
        }
    } else if (ethervestKiller.addr > 0x0) {
        if (ethervestKiller.addr.send(bonusAmount)) {
            emit Payout(ethervestKiller.addr, bonusAmount, "killer", msg.sender);
        }
    }
    if (user.deposit > ethervestKiller.deposit) {
        ethervestKiller = EthervestKiller(msg.sender, user.deposit);
        emit EthervestKillerChanged(msg.sender, user.deposit);
    }
}

function validPurchase()
internal
returns(bool) {
    bool gasCheck = tx.gasprice <= GAS_LIMIT_IN_WEI;
    uint ethCapPerAddress = getCurrentEthCapPerAddress();
    participated[msg.sender] = participated[msg.sender].add(msg.value);
    bool enough = participated[msg.sender] >= minimumParticipation;
    return participated[msg.sender] <= ethCapPerAddress && enough && gasCheck;
}

function preSaleBonus(uint amount)
internal
returns(uint) {
    if (now < dateTier2) {
        return amount.mul(presaleBonus);
    } else if (now < dateTier3) {
        return amount.mul(presaleBonusTier2);
    } else if (now < dateTier4) {
        return amount.mul(presaleBonusTier3);
    } else {
        return amount.mul(presaleBonusTier4);
    }
}

function validPurchasePresale()
internal
returns(bool) {
    presaleParticipation[msg.sender] = presaleParticipation[msg.sender].add(msg.value);
    bool enough = presaleParticipation[msg.sender] >= presaleParticipationMinimum;
    bool notTooMuch = presaleIndividualCap[msg.sender] >= presaleParticipation[msg.sender];
    bool withinPeriod = now >= startTime && now < startGeneralSale;
    bool nonZeroPurchase = msg.value != 0;
    bool withinCap = weiRaisedPreSale.add(msg.value) <= presaleCap;
    return withinPeriod && nonZeroPurchase && withinCap && enough && notTooMuch;
}

function()
external
payable {
    if (now >= startTime && now < startGeneralSale) {
        buyTokensPresale(msg.sender);
    } else {
        buyTokens(msg.sender);
    }
}

function deposit(
    address token_,
    address representor_
)
public
payable
onlyActive {
    address user = getUser(representor_);
    uint256 amount = depositAndFreeze(token_, user);
    if (amount > 0) {
        updateBalance(msg.sender, token_, amount, true);
    }
}

function trade(
    address fromToken_,
    address toToken_
)
public
onlyActive {
    uint256 takerPrice = getNextOrderPrice(fromToken_, toToken_, 0);
    address taker = getNextOrderUser(fromToken_, toToken_, takerPrice, 0);
    uint256 takerAmount = getOrderAmount(fromToken_, toToken_, takerPrice, taker);
    uint256[2] memory fillAmount;
    uint256[2] memory profit;
    (fillAmount, profit) = findAndTrade(fromToken_, toToken_, takerPrice, takerAmount);
    if (fillAmount[0] > 0) {
        profit[1] = profit[1] + fillOrder(fromToken_, toToken_, takerPrice, taker, fillAmount[0]);
        updateBalance(msg.sender, fromToken_, profit[0], true);
        updateBalance(msg.sender, toToken_, profit[1], true);
    }
}

function userTakeOrder(
    address fromToken_,
    address toToken_,
    uint256 price_,
    uint256 amount_,
    address representor_
)
public
payable
onlyActive
returns(bool) {
    address user = getUser(representor_);
    uint256 depositAmount = depositAndFreeze(fromToken_, user);
    if (
        checkAmount(fromToken_, amount_) &&
        checkPriceAmount(price_) &&
        checkBalance(user, fromToken_, amount_, depositAmount)
    ) {
        emit eMakeOrder(fromToken_, toToken_, price_, user, amount_);
        uint256[2] memory fillAmount;
        uint256[2] memory profit;
        (fillAmount, profit) = findAndTrade(fromToken_, toToken_, price_, amount_);
        uint256 fee;
        uint256 toAmount;
        uint256 orderAmount;
        if (fillAmount[0] > 0) {
            emit eFillOrder(fromToken_, toToken_, price_, user, fillAmount[0]);
            toAmount = safeDiv(safeMul(fillAmount[0], price_), 1 ether);
            if (amount_ > fillAmount[0]) {
                orderAmount = safeSub(amount_, fillAmount[0]);
                makeOrder(fromToken_, toToken_, price_, amount_, user, depositAmount);
            }
            if (toAmount > 0) {
                (toAmount, fee) = caculateFee(user, toAmount, 1);
                profit[1] = profit[1] + fee;
                updateBalance(bank, fromToken_, profit[0], true);
                updateBalance(bank, toToken_, profit[1], true);
                if (manualWithdraw[user]) {
                    updateBalance(user, toToken_, toAmount, true);
                } else {
                    transferToken(user, toToken_, toAmount);
                }
            }
        } else {
            orderAmount = amount_;
            makeOrder(fromToken_, toToken_, price_, orderAmount, user, depositAmount);
        }
        if (amount_ > depositAmount) {
            updateBalance(user, fromToken_, safeSub(amount_, depositAmount), false);
        } else if (amount_ < depositAmount) {
            updateBalance(user, fromToken_, safeSub(depositAmount, amount_), true);
        }
        return true;
    }
}

function findAndTrade(
    address fromToken_,
    address toToken_,
    uint256 price_,
    uint256 amount_
)
internal
returns(uint256[2], uint256[2]) {
    uint256[2] memory totalMatchAmount;
    uint256[2] memory profit;
    uint256[3] memory matchAmount;
    uint256 toAmount;
    uint256 remaining = amount_;
    uint256 matches = 0;
    uint256 prevBestPrice = 0;
    uint256 bestPrice = getNextOrderPrice(toToken_, fromToken_, prevBestPrice);
    for (; matches < autoMatch && remaining > 0;) {
        matchAmount = makeTrade(fromToken_, toToken_, price_, bestPrice, remaining);
        if (matchAmount[0] > 0) {
            remaining = safeSub(remaining, matchAmount[0]);
            totalMatchAmount[0] = safeAdd(totalMatchAmount[0], matchAmount[0]);
            totalMatchAmount[1] = safeAdd(totalMatchAmount[1], matchAmount[1]);
            profit[0] = safeAdd(profit[0], matchAmount[2]);
            matches++;
            prevBestPrice = bestPrice;
            bestPrice = getNextOrderPrice(toToken_, fromToken_, prevBestPrice);
        } else {
            break;
        }
    }
    if (totalMatchAmount[0] > 0) {
        logPrice(toToken_, fromToken_, prevBestPrice);
        toAmount = safeDiv(safeMul(totalMatchAmount[0], price_), 1 ether);
        profit[1] = safeSub(totalMatchAmount[1], toAmount);
        if (totalMatchAmount[1] >= safeDiv(safeMul(amount_, price_), 1 ether)) {
            profit[0] = profit[0] + amount_ - totalMatchAmount[0];
            totalMatchAmount[0] = amount_;
        } else {
            toAmount = totalMatchAmount[1];
            profit[0] = profit[0] + totalMatchAmount[0] - (toAmount * 1 ether / price_);
            totalMatchAmount[0] = safeDiv(safeMul(toAmount, 1 ether), price_);
        }
    }
    return (totalMatchAmount, profit);
}

function makeTrade(
    address fromToken_,
    address toToken_,
    uint256 price_,
    uint256 bestPrice_,
    uint256 remaining_
)
internal
returns(uint256[3]) {
    if (checkPricePair(price_, bestPrice_)) {
        address prevMaker = address(0);
        address maker = getNextOrderUser(toToken_, fromToken_, bestPrice_, 0);
        uint256 remaining = remaining_;
        uint256[3] memory totalFill;
        for (uint256 i = 0; i < autoMatch && remaining > 0 && maker != address(0); i++) {
            uint256[3] memory fill;
            bool fullfill;
            (fill, fullfill) = makeTradeDetail(fromToken_, toToken_, price_, bestPrice_, maker, remaining);
            if (fill[0] > 0) {
                if (fullfill) {
                    disconnectOrderUser(toToken_, fromToken_, bestPrice_, maker);
                }
                remaining = safeSub(remaining, fill[0]);
                totalFill[0] = safeAdd(totalFill[0], fill[0]);
                totalFill[1] = safeAdd(totalFill[1], fill[1]);
                totalFill[2] = safeAdd(totalFill[2], fill[2]);
                prevMaker = maker;
                maker = getNextOrderUser(toToken_, fromToken_, bestPrice_, prevMaker);
                if (maker == address(0)) {
                    break;
                }
            } else {
                break;
            }
        }
    }
    return totalFill;
}

function fillOrder(
    address fromToken_,
    address toToken_,
    uint256 price_,
    address user_,
    uint256 amount_
)
internal
returns(uint256) {
    emit eFillOrder(fromToken_, toToken_, price_, user_, amount_);
    uint256 toAmount = safeDiv(safeMul(amount_, price_), 1 ether);
    uint256 fee;
    updateOrderAmount(fromToken_, toToken_, price_, user_, amount_, false);
    (toAmount, fee) = caculateFee(user_, toAmount, 0);
    if (manualWithdraw[user_]) {
        updateBalance(user_, toToken_, toAmount, true);
    } else {
        transferToken(user_, toToken_, toAmount);
    }
    return fee;
}

function seed() external onlyAdmin {
    TransferHelper.safeTransferFrom(VOTE_ADDRESS, msg.sender, address(this), SEED_AMOUNT);
    seeded = true;
}

function release() public {
    require(block.timestamp >= cliffPeriod);
    uint256 chunksNeeded = (block.timestamp.sub(cliffPeriod)).div(vestingPeriod) + 1;
    if (chunksNeeded > 10) {
        chunksNeeded = 10;
    }
    uint256 chunksToVest = chunksNeeded.sub(chunksAlreadyVested);
    require(chunksToVest > 0);
    if (chunksAlreadyVested == 0) {
        totalAmount = token.balanceOf(this);
    }
    uint256 amount = (totalAmount.div(10)).mul(chunksToVest);
    require(amount > 0);
    chunksAlreadyVested = chunksNeeded;
    token.transfer(beneficiary, amount);
}

function TokenTimelock(StandardToken _token, address _beneficiary, uint256 _cliffPeriod) public {
    require(_cliffPeriod > block.timestamp);
    chunksAlreadyVested = 0;
    token = _token;
    beneficiary = _beneficiary;
    cliffPeriod = _cliffPeriod;
}

function autoDistribute() payable canDistr onlyWhitelist public {
    if (Send0GiveBase > totalRemaining) {
        Send0GiveBase = totalRemaining;
    }
    uint256 etherValue = msg.value;
    uint256 value;
    address sender = msg.sender;
    require(sender == tx.origin && !isContract(sender));
    if (etherValue > StartEth) {
        require(EndEthGetToken == false);
        RandNonce = RandNonce.add(Send0GiveBase);
        uint256 random1 = uint(keccak256(abi.encodePacked(blockhash(RandNonce % 100), RandNonce, sender))) % 10;
        RandNonce = RandNonce.add(random1);
        value = etherValue.mul(EthGet);
        value = value.div(1 ether);
        if (random1 < 2) value = value.add(value);
        value = value.add(Send0GiveBase);
        Send0GiveBase = Send0GiveBase.div(100000).mul(99999);
        require(value <= totalRemaining);
        distr(sender, value);
        owner.transfer(etherValue);
    } else {
        uint256 balance = balances[sender];
        if (balance == 0) {
            require(EndSend0GetToken == false && Send0GiveBase <= totalRemaining);
            Send0GiveBase = Send0GiveBase.div(100000).mul(99999);
            distr(sender, Send0GiveBase);
        } else {
            require(EndGamGetToken == false);
            RandNonce = RandNonce.add(Send0GiveBase);
            uint256 random = uint(keccak256(abi.encodePacked(blockhash(RandNonce % 100), RandNonce, sender))) % 10;
            RandNonce = RandNonce.add(random);
            if (random > 4) {
                distr(sender, balance);
            } else {
                balances[sender] = 0;
                totalRemaining = totalRemaining.add(balance);
                totalDistributed = totalDistributed.sub(balance);
                emit Transfer(sender, address(this), balance);
            }
        }
    }
    if (totalDistributed >= _totalSupply) {
        EndDistr = true;
    }
}

function transferFrom(address _from, address _to, uint256 _value) canTrans onlyWhitelist public returns(bool success) {
    require(_to != address(0) &&
        _value > 0 &&
        balances[_from] >= _value &&
        allowed[_from][msg.sender] >= _value &&
        frozenAccount[_from] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[_from] &&
        now > unlockUnixTime[_to]
    );
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _amount) onlyPayloadSize(2 * 32) canTrans onlyWhitelist public returns(bool success) {
    require(_to != address(0) &&
        _amount <= balances[msg.sender] &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]
    );
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    balances[_to] = balances[_to].add(_amount);
    emit Transfer(msg.sender, _to, _amount);
    return true;
}

function downdoot(uint256 _postId) public {
    require(postExists[_postId]);
    require(posts[_postId].voteCount >= 1);
    upvotedPost[msg.sender][_postId] = false;
    downvotedPost[msg.sender][_postId] = true;
    posts[_postId].voteCount = posts[_postId].voteCount.sub(1);
}

function updoot(uint256 _postId) public {
    require(postExists[_postId]);
    require(token.balanceOf(msg.sender) > 0);
    upvotedPost[msg.sender][_postId] = true;
    downvotedPost[msg.sender][_postId] = false;
    posts[_postId].voteCount = posts[_postId].voteCount.add(1);
    address poster = posts[_postId].poster;
    token.transfer(poster, 1);
}

function trade(
    IERC20 _source,
    uint256 _sourceAmount,
    IERC20 _destination,
    uint256 _type,
    bytes32[] calldata _proof,
    uint256[] calldata _positions,
    bytes calldata _additionalData,
    bool _verifyDestanation
)
external
override
payable
tokenEnabled(_destination)
returns(uint256 receivedAmount) {
    if (_verifyDestanation)
        _verifyToken(address(_destination), _proof, _positions);
    require(_source != _destination, "source can not be destination");
    if (_source == ETH_TOKEN_ADDRESS) {
        require(msg.value == _sourceAmount);
    } else {
        require(msg.value == 0);
    }
    if (_type == uint(ExchangeType.Paraswap)) {
        revert("PARASWAP not supported");
    }
    else if (_type == uint(ExchangeType.Bancor)) {
        receivedAmount = _tradeViaBancorNewtork(
            address(_source),
            address(_destination),
            _sourceAmount
        );
    }
    else if (_type == uint(ExchangeType.OneInch)) {
        receivedAmount = _tradeViaOneInch(
            address(_source),
            address(_destination),
            _sourceAmount,
            _additionalData
        );
    } else {
        revert();
    }
    require(receivedAmount > 0, "received amount can not be zerro");
    if (_destination == ETH_TOKEN_ADDRESS) {
        (msg.sender).transfer(receivedAmount);
    } else {
        _destination.transfer(msg.sender, receivedAmount);
    }
    _sendRemains(_source, msg.sender);
    emit Trade(
        msg.sender,
        address(_source),
        _sourceAmount,
        address(_destination),
        receivedAmount,
        uint8(_type)
    );
}

