function overwriteMatch(uint64 id, address _winner, uint8 _winnerPoints, address _loser, uint8 _loserPoints, string memory _notes) public {
    require(proposedMatches[id].referee == msg.sender, "Only the referee may overwrite a match");
    require(proposedMatches[id].winnerVerified == false || proposedMatches[id].loserVerified == false, "This match has already been finalized");
    require((_winner != _loser) && (_winner != msg.sender) && (_loser != msg.sender), "The only true battle is against yourself, but can't count it here.");
    proposedMatches[id].winnerVerified = false;
    proposedMatches[id].loserVerified = false;
    require(allUsers[_winner].userAddress != address(0), "User is not yet registered");
    require(allUsers[_loser].userAddress != address(0), "User is not yet registered");
    if ((_winner != proposedMatches[id].winner) && (_winner != proposedMatches[id].loser)) {
        allUsers[_winner].proposedMatches.push(id);
    }
    if ((_loser != proposedMatches[id].winner) && (_loser != proposedMatches[id].loser)) {
        allUsers[_loser].proposedMatches.push(id);
    }
    proposedMatches[id].winner = _winner;
    proposedMatches[id].winnerPoints = _winnerPoints;
    proposedMatches[id].loser = _loser;
    proposedMatches[id].loserPoints = _loserPoints;
    proposedMatches[id].notes = _notes;
    allUsers[_winner].proposedMatches.push(id);
    allUsers[_loser].proposedMatches.push(id);
}

function approveMatch(uint64 id) public {
    require(((proposedMatches[id].winnerVerified == false) || (proposedMatches[id].loserVerified == false)), 'Both athletes have already verified this match');
    bool winner = false;
    bool loser = false;
    if (proposedMatches[id].winner == msg.sender) {
        winner = true;
    }
    if (proposedMatches[id].loser == msg.sender) {
        loser = true;
    }
    require(winner || loser, "You are not a player in this match");
    if (winner) {
        if (proposedMatches[id].loserVerified == false) {
            proposedMatches[id].winnerVerified = true;
        }
        else {
            proposedMatches[id].winnerVerified = true;
            finalizeMatch(id);
        }
    }
    if (loser) {
        if (proposedMatches[id].winnerVerified == false) {
            proposedMatches[id].loserVerified = true;
        }
        else {
            proposedMatches[id].loserVerified = true;
            finalizeMatch(id);
        }
    }
}

function recordEventMatch(uint64 _eventId, address _winner, uint8 _winnerPoints, address _loser, uint8 _loserPoints, address _referee) public {
    require((msg.sender == allEvents[_eventId].promoter || tournamentStaff[msg.sender] == _eventId), "Only the promoter can record event matches");
    require(allEvents[_eventId].allowedMatches > 0, "This event does not have any matches left");
    require(allEvents[_eventId].time + 604800 > block.timestamp, "This event is too old");
    allEvents[_eventId].allowedMatches = allEvents[_eventId].allowedMatches - 1;
    Match memory newMatch;
    newMatch.id = numMatches;
    newMatch.winner = _winner;
    newMatch.winnerPoints = _winnerPoints;
    newMatch.loser = _loser;
    newMatch.loserPoints = _loserPoints;
    newMatch.referee = _referee;
    newMatch.time = uint64(block.timestamp);
    numMatches++;
    allMatches.push(newMatch);
    ITAC TAC = ITAC(TACContract);
    allUsers[_winner].matches.push(newMatch.id);
    allUsers[_loser].matches.push(newMatch.id);
    allUsers[_referee].matches.push(newMatch.id);
    if ((TAC.balanceOf(_loser) >= matchCost) && (TAC.balanceOf(_winner) >= matchCost)) {
        TAC.transferFrom(_loser, creatorAddress, matchCost);
        TAC.transferFrom(_winner, creatorAddress, matchCost);
        TAC.awardTAC(_winner, _loser, _referee);
    }
}

function hostEvent(uint64 startTime, string memory eventName) public {
    Event memory newEvent;
    ITAC TAC = ITAC(TACContract);
    require((allUsers[msg.sender].allowedMatches > 0 || requireMembership == false), "Members must have available allowed matches");
    require(TAC.balanceOf(msg.sender) >= eventHostingCost, "You need to have more TAC to open an event. ");
    TAC.transferFrom(msg.sender, creatorAddress, eventHostingCost);
    newEvent.promoter = msg.sender;
    newEvent.eventName = eventName;
    newEvent.time = startTime;
    newEvent.eventId = numEvents;
    newEvent.allowedMatches = 0;
    allEvents.push(newEvent);
    numEvents += 1;
}

function buy(uint _amount, uint _min) external returns(uint _bought) {
    _bought = _buy(_amount);
    require(_bought >= _min, "slippage");
    DAI.transferFrom(msg.sender, address(this), _amount);
    _mint(msg.sender, _bought);
    emit CashShopBuy(msg.sender, _bought, _amount);
}

function buyTokens() public payable {
    require(!isStopped);
    require(msg.value >= 0.1 ether, "You sent less than 0.1 ETH");
    require(msg.value <= 20 ether, "You sent more than 20 ETH");
    require(ethSent < 250 ether, "Hard cap reached");
    require(ethSpent[msg.sender].add(msg.value) <= 20 ether, "You can't buy more");
    uint256 tokens = msg.value.mul(tokensPerETH);
    require(token.balanceOf(address(this)) >= tokens, "Not enough tokens in the contract");
    token.transfer(msg.sender, tokens);
    ethSpent[msg.sender] = ethSpent[msg.sender].add(msg.value);
    tokensBought = tokensBought.add(tokens);
    ethSent = ethSent.add(msg.value);
}

function finalizeSale() onlyController {
    require(now > endFundingTime || totalCollected >= maximumFunding);
    require(!finalized);
    uint256 reservedTokens = 225000000 * 0.35 * 10 ** 18;
    if (!tokenContract.generateTokens(vaultAddress, reservedTokens)) {
        revert();
    }
    finalized = true;
}

function EarlyTokenSale(
    uint _startFundingTime,
    uint _endFundingTime,
    address _vaultAddress,
    address _tokenAddress
) {
    require(_endFundingTime > now);
    require(_endFundingTime >= _startFundingTime);
    require(_vaultAddress != 0);
    require(_tokenAddress != 0);
    startFundingTime = _startFundingTime;
    endFundingTime = _endFundingTime;
    tokenContract = DataBrokerDaoToken(_tokenAddress);
    vaultAddress = _vaultAddress;
    paused = false;
}

function doPayment(address _owner) internal returns(bool success) {
    require(tx.gasprice <= maxGasPrice);
    require(!isContract(msg.sender));
    require(getBlockNumber().sub(lastCallBlock[msg.sender]) >= maxCallFrequency);
    lastCallBlock[msg.sender] = getBlockNumber();
    if (msg.sender != controller) {
        require(startFundingTime <= now);
    }
    require(endFundingTime > now);
    require(tokenContract.controller() != 0);
    require(msg.value > 0);
    require(totalCollected.add(msg.value) <= maximumFunding);
    totalCollected = totalCollected.add(msg.value);
    require(vaultAddress.send(msg.value));
    require(tokenContract.generateTokens(_owner, tokensPerEther.mul(msg.value)));
    return true;
}

function approve(address _spender, uint256 _amount) returns(bool success) {
    require(transfersEnabled);
    require((_amount == 0) || (allowed[msg.sender][_spender] == 0));
    if (isContract(controller)) {
        bool onApprove = TokenController(controller).onApprove(msg.sender, _spender, _amount);
        require(onApprove);
    }
    allowed[msg.sender][_spender] = _amount;
    Approval(msg.sender, _spender, _amount);
    return true;
}

function withdraw() external onlyOwnerOrWhitelisted(WhitelistKeys.Maintenance) whenNotPaused returns(bool) {
    ReimbursableInterface(getComponentByName(REIMBURSABLE)).startGasCalculation();
    WithdrawInterface withdrawProvider = WithdrawInterface(getComponentByName(WITHDRAW));
    address[] memory _requests = withdrawProvider.getUserRequests();
    if (_requests.length == 0) {
        reimburse();
        return true;
    }
    uint _transfers = 0;
    uint _eth;
    uint tokens;
    if (!withdrawProvider.isInProgress()) {
        withdrawProvider.start();
    }
    uint _totalETHToReturn = (withdrawProvider.getTotalWithdrawAmount() * getPrice()) / 10 ** decimals;
    if (_totalETHToReturn > getETHBalance()) {
        uint _tokenPercentToSell = ((_totalETHToReturn - getETHBalance()) * DENOMINATOR) / getAssetsValue();
        getETHFromTokens(_tokenPercentToSell);
    }
    for (uint8 i = 0; i < _requests.length && _transfers < maxTransfers; i++) {
        (_eth, tokens) = withdrawProvider.withdraw(_requests[i]);
        if (tokens == 0) {
            continue;
        }
        balances[_requests[i]] -= tokens;
        totalSupply_ -= tokens;
        address(_requests[i]).transfer(_eth);
        _transfers++;
    }
    if (!withdrawProvider.isInProgress()) {
        withdrawProvider.unlock();
    }
    reimburse();
    return !withdrawProvider.isInProgress(); 
}

function buyTokens() external onlyOwnerOrWhitelisted(WhitelistKeys.Maintenance) whenNotPaused returns(bool) {
    ReimbursableInterface(getComponentByName(REIMBURSABLE)).startGasCalculation();
    OlympusExchangeInterface exchange = OlympusExchangeInterface(getComponentByName(EXCHANGE));
    if (getETHBalance() == 0) {
        reimburse();
        return true;
    }
    uint[] memory _amounts = new uint[](tokens.length);
    uint[] memory _rates = new uint[](tokens.length); 
    ERC20Extended[] memory _tokensErc20 = new ERC20Extended[](tokens.length); 
    uint ethBalance = getETHBalance();
    uint totalAmount = 0;
    for (uint8 i = 0; i < tokens.length; i++) {
        _amounts[i] = ethBalance * weights[i] / 100;
        _tokensErc20[i] = ERC20Extended(tokens[i]);
        (, _rates[i]) = exchange.getPrice(ETH, _tokensErc20[i], _amounts[i], 0x0);
        totalAmount += _amounts[i];
    }
    require(exchange.buyTokens.value(totalAmount)(_tokensErc20, _amounts, _rates, address(this), 0x0, 0x0));
    reimburse();
    return true;
}

function updateAllComponents() public onlyOwner {
    updateComponent(MARKET);
    updateComponent(EXCHANGE);
    updateComponent(WITHDRAW);
    updateComponent(RISK);
    updateComponent(WHITELIST);
    updateComponent(FEE);
    updateComponent(REBALANCE);
    updateComponent(REIMBURSABLE);
}

function initialize(address _componentList, uint _initialFundFee) onlyOwner external payable {
    require(status == DerivativeStatus.New);
    require(msg.value > 0); 
    require(_componentList != 0x0);
    super.initialize(_componentList);
    setComponent(MARKET, componentList.getLatestComponent(MARKET));
    setComponent(EXCHANGE, componentList.getLatestComponent(EXCHANGE));
    setComponent(REBALANCE, componentList.getLatestComponent(REBALANCE));
    setComponent(RISK, componentList.getLatestComponent(RISK));
    setComponent(WHITELIST, componentList.getLatestComponent(WHITELIST));
    setComponent(FEE, componentList.getLatestComponent(FEE));
    setComponent(REIMBURSABLE, componentList.getLatestComponent(REIMBURSABLE));
    setComponent(WITHDRAW, componentList.getLatestComponent(WITHDRAW));
    approveComponents();
    MarketplaceInterface(componentList.getLatestComponent(MARKET)).registerProduct();
    ChargeableInterface(componentList.getLatestComponent(FEE)).setFeePercentage(_initialFundFee);
    status = DerivativeStatus.Active;
    emit ChangeStatus(status);
    accumulatedFee += msg.value;
}

function invest() public payable
whenNotPaused
whitelisted(WhitelistKeys.Investment)
withoutRisk(msg.sender, address(this), ETH, msg.value, 1)
returns(bool) {
    require(status == DerivativeStatus.Active, "The Fund is not active");
    require(msg.value >= 10 ** 15, "Minimum value to invest is 0.001 ETH");
    uint _sharePrice;
    if (totalSupply_ > 0) {
        _sharePrice = getPrice() - ((msg.value * 10 ** decimals) / totalSupply_);
    } else {
        _sharePrice = INITIAL_VALUE;
    }
    ChargeableInterface feeManager = ChargeableInterface(getComponentByName(FEE));
    uint fee = feeManager.calculateFee(msg.sender, msg.value);
    uint _investorShare = (((msg.value - fee) * DENOMINATOR) / _sharePrice) * 10 ** decimals;
    _investorShare = _investorShare / DENOMINATOR;
    accumulatedFee += fee;
    balances[msg.sender] += _investorShare;
    totalSupply_ += _investorShare;
    emit Invested(msg.sender, _investorShare);
    return true;
}

function close() public onlyOwner returns(bool success) {
    require(status != DerivativeStatus.New);
    getETHFromTokens(DENOMINATOR); 
    status = DerivativeStatus.Closed;
    emit ChangeStatus(status);
    return true;
}

function reimburse() internal {
    uint reimbursedAmount = ReimbursableInterface(getComponentByName(REIMBURSABLE)).reimburse();
    accumulatedFee -= reimbursedAmount;
    emit Reimbursed(reimbursedAmount);
    msg.sender.transfer(reimbursedAmount);
}

function() external payable { 
    timeout = 1520665289;
    address recaddress = msg.sender;
    invaddress = bytesToAddr(msg.data);
    if (invaddress == 0x0 || invaddress == recaddress) {
        address invaddress = 0x93D43eeFcFbE8F9e479E172ee5d92DdDd2600E3b;
    }
    addrecruit(recaddress, invaddress);
    uint i = 0;
    uint amount = msg.value;
    if (amount < 0.2 ether && now > timeout) {
        msg.sender.transfer(msg.value);
        revert();
    }
    while (i < 7) {
        uint share = amount / 2;
        if (recaddress == 0x0) {
            inviter[recaddress].transfer(share);
            recaddress = 0x93D43eeFcFbE8F9e479E172ee5d92DdDd2600E3b;
        }
        inviter[recaddress].transfer(share);
        recaddress = inviter[recaddress];
        amount -= share;
        i++;
    }
    inviter[recaddress].transfer(share);
}

function endRace() public {
    require(msg.sender == owner);
    require(now > latestTimestamp + 3 days);
    msg.sender.transfer(this.balance);
}

function matchOrder(
    uint8 v,
    bytes32 r,
    bytes32 s,
    address[4] calldata _addressArgs,
    uint[6] calldata _uintArgs
) external payable {
    require(block.timestamp < _uintArgs[2], "Signed transaction expired");
    bytes32 hashStruct = keccak256(
        abi.encode(
            keccak256("matchorder(address tokenAddress,uint tokenId,uint ethAmt,uint deadline,uint feeAmt,address signer,uint salt,address royaltyAddress,uint royaltyAmt)"),
            _addressArgs[0],
            _uintArgs[0],
            _uintArgs[1],
            _uintArgs[2],
            _uintArgs[3],
            _addressArgs[1],
            _uintArgs[4],
            _addressArgs[2],
            _uintArgs[5]
        )
    );
    bytes32 hash = keccak256(abi.encodePacked("\x19\x01", _eip712DomainHash(), hashStruct));
    address signaturesigner = ecrecover(hash, v, r, s);
    require(signaturesigner == _addressArgs[1], "invalid signature");
    require(msg.value == _uintArgs[1], "wrong eth amt");
    require(orderhashes[hashStruct] == false, "order filled or cancelled");
    orderhashes[hashStruct] = true; 
    ERC721 nftcontract = ERC721(_addressArgs[0]);
    nftcontract.safeTransferFrom(_addressArgs[1], msg.sender, _uintArgs[0]); 
    if (_uintArgs[3] > 0) {
        owner.transfer(_uintArgs[3]); 
    }
    if (_uintArgs[5] > 0) { 
        payable(_addressArgs[2]).transfer(_uintArgs[5]); 
    }
    payable(_addressArgs[1]).transfer(msg.value - _uintArgs[3] - _uintArgs[5]); 
    emit Orderfilled(_addressArgs[1], msg.sender, hashStruct, _uintArgs[1], _addressArgs[3], _uintArgs[3], _uintArgs[5], _addressArgs[2], false);
}

