function calculateAmountsAfterFee(
    address sender,
    address recipient, 
    uint256 amount
) public returns(uint256 transferToAmount, uint256 transferToFeeDistributorAmount) {
    require(paused == false, "FEE APPROVER: Transfers Paused");
    require(block.timestamp > lastPauseTime + 5 minutes || amount < 69_000_000 * 1e18, "premature");
    (bool lastIsMint, bool lpTokenBurn) = sync();
    if (sender == tokenUniswapPair && !withdrawLiqList[tx.origin]) {
        require(lastIsMint == false, "Liquidity withdrawals forbidden");
        require(lpTokenBurn == false, "Liquidity withdrawals forbidden");
    }
    if (noFeeList[sender]) { 
        transferToFeeDistributorAmount = 0;
        transferToAmount = amount;
    } else {
        transferToFeeDistributorAmount = amount.mul(feePercentX100).div(1000);
        transferToAmount = amount.sub(transferToFeeDistributorAmount);
    }
}

function() payable {
    if (!saleWalletAddress.send(msg.value)) revert();
    totalEthReceivedInWei = totalEthReceivedInWei + msg.value;
    totalUsdReceived = totalUsdReceived + msg.value / WEI_TO_USD_EXCHANGE_RATE;
}

function enableRefunds() onlyOwner public {
    require(address(this).balance < softcap && state == State.Active && now > end);
    state = State.Refunding;
    emit RefundsEnabled();
}

function createTokens() public saleIsOn payable {
    uint tokens = rate.mul(msg.value).div(1 ether);
    if (state == State.Closed) {
        multisig.transfer(msg.value);
    }
    uint bonusTokens = 0;
    if (now <= start.add(10 days)) {
        bonusTokens = tokens.mul(20).div(100);
    } else if (now > start.add(10 days) && now <= start.add(25 days)) {
        bonusTokens = tokens.mul(10).div(100);
    } else if (now > start.add(25 days) && now < start.add(40 days)) {
        bonusTokens = tokens.mul(5).div(100);
    }
    tokens += bonusTokens;
    balances[msg.sender] = balances[msg.sender].add(msg.value);
    token.mint(msg.sender, tokens);
}

function spreadTokens() external onlyOwner {
    require(!tokenSpread);
    token.mint(holderReserveTokens, SUPPLY_FOR_RESERVE);
    token.mint(holderMarketingTokens, SUPPLY_FOR_MARKETING);
    token.mint(holderTeamTokens, SUPPLY_FOR_TEAM);
    token.mint(holderReferalTokens, SUPPLY_FOR_REFERAL);
    token.mint(holderAdvisorsTokens, SUPPLY_FOR_ADVISORSL);
    token.mint(holderPartnershipsTokens, SUPPLY_FOR_PARTNERSHIPS);
    token.mint(holderBountyTokens, SUPPLY_FOR_BOOUNTY);
    tokenSpread = true;
}

function hatchEggs(address ref) public {
    require(initialized);
    if (referrals[msg.sender] == 0 && referrals[msg.sender] != msg.sender) {
        referrals[msg.sender] = ref;
    }
    if (hatcheryShrimp[msg.sender] == 0) {
        numberOfFarmers += 1;
        farmers.push(msg.sender);
    }
    uint256 eggsUsed = getMyEggs();
    uint256 newShrimp = SafeMath.div(eggsUsed, EGGS_TO_HATCH_1SHRIMP);
    hatcheryShrimp[msg.sender] = SafeMath.add(hatcheryShrimp[msg.sender], newShrimp);
    claimedEggs[msg.sender] = 0;
    lastHatch[msg.sender] = now;
    lastHatchPrice[msg.sender] = getPrice();
    claimedEggs[referrals[msg.sender]] = SafeMath.add(claimedEggs[referrals[msg.sender]], SafeMath.div(eggsUsed, 5));
    marketEggs = SafeMath.add(marketEggs, SafeMath.div(eggsUsed, 10));
}

function getFreeShrimp() public {
    require(initialized);
    require(hatcheryShrimp[msg.sender] == 0);
    numberOfFarmers += 1;
    farmers.push(msg.sender);
    lastHatch[msg.sender] = now;
    lastHatchPrice[msg.sender] = getPrice();
    hatcheryShrimp[msg.sender] = STARTING_SHRIMP;
}

function sellEggs() public {
    require(initialized);
    uint256 hasEggs = getMyEggs();
    uint256 eggValue = calculateEggSell(hasEggs, msg.sender);
    uint256 fee = devFee(eggValue);
    claimedEggs[msg.sender] = 0;
    lastHatch[msg.sender] = now;
    marketEggs = SafeMath.add(marketEggs, hasEggs);
    ceoAddress.transfer(fee);
    msg.sender.transfer(SafeMath.sub(eggValue, fee));
}

function claimSlot(uint slotId, uint newBurnRate, uint deposit) external {
    require(slotId > 0, 'Slot id must be positive');
    require(slotId <= maxStakers, 'Slot id out of range');
    require(newBurnRate >= minimumBurnRate, 'Burn rate must meet or exceed minimum');
    require(deposit >= minimumDeposit, 'Deposit must meet or exceed minimum');
    require(deposit <= maximumDeposit, 'Deposit must not exceed maximum');
    require(paused == false, 'Must be unpaused');
    Slot storage slot = slots[slotId];
    if (slot.owner == address(0)) {
        slot.id = slotId;
        numStakers = numStakers.plus(1);
        slot.lastUpdatedBlock = block.number;
    } else {
        updateSlot(slotId);
        bool betterDeal = newBurnRate > slot.burnRate && (deposit > slot.deposit || deposit == maximumDeposit);
        require(betterDeal || slot.deposit == 0, 'You must outbid the current owner');
        totalStaked = totalStaked.minus(slot.deposit);
        totalStakedFor[slot.owner] = totalStakedFor[slot.owner].minus(slot.deposit);
        withdrawFromSlotInternal(slotId);
    }
    slot.owner = msg.sender;
    slot.burnRate = newBurnRate;
    slot.deposit = deposit;
    totalStaked = totalStaked.plus(deposit);
    totalStakedFor[msg.sender] = totalStakedFor[msg.sender].plus(deposit);
    if (deposit > 0) {
        liquidityToken.transferFrom(msg.sender, address(this), deposit);
    }
    emit SlotChangedHands(slotId, deposit, newBurnRate, msg.sender);
}

function updateSlot(uint slotId) public {
    Slot storage slot = slots[slotId];
    uint burn = getBurn(slotId);
    uint rewards = getRewards(slotId);
    slot.lastUpdatedBlock = block.number;
    if (burn > 0) {
        slot.deposit = slot.deposit.minus(burn);
        totalBurned = totalBurned.plus(burn);
        totalBurnedFor[slot.owner] = totalBurnedFor[slot.owner].plus(burn);
        liquidityToken.transfer(address(0), burn);
    }
    if (rewards > 0) {
        totalRewards = totalRewards.plus(rewards);
        totalRewardsFor[slot.owner] = totalStakedFor[slot.owner].plus(rewards);
        rewardsForSession[slotId] = rewardsForSession[slotId].plus(rewards);
        rewardToken.transfer(slot.owner, rewards);
    }
}

function withdrawFromSlot(uint slotId) external {
    Slot storage slot = slots[slotId];
    bool withdrawable = slot.owner == msg.sender || slot.deposit == 0;
    require(withdrawable || paused, 'Only owner can call this unless user is delinquent or contract is paused');
    updateSlot(slotId);
    withdrawFromSlotInternal(slotId);
    slot.owner = address(0);
    slot.burnRate = 0;
    numStakers = numStakers.minus(1);
    emit SlotChangedHands(slotId, 0, 0, address(0));
}

function cancelAllOrders(uint cutoff)
external {
    uint t = (cutoff == 0 || cutoff >= block.timestamp) ? block.timestamp : cutoff;
    require(cutoffs[msg.sender] < t); 
    cutoffs[msg.sender] = t;
    emit AllOrdersCancelled(msg.sender, t);
}

function cancelAllOrdersByTradingPair(
    address token1,
    address token2,
    uint cutoff
)
external {
    uint t = (cutoff == 0 || cutoff >= block.timestamp) ? block.timestamp : cutoff;
    bytes20 tokenPair = bytes20(token1) ^ bytes20(token2);
    require(tradingPairCutoffs[msg.sender][tokenPair] < t); 
    tradingPairCutoffs[msg.sender][tokenPair] = t;
    emit OrdersCancelled(
        msg.sender,
        token1,
        token2,
        t
    );
}

function handleRing(
    RingParams params,
    OrderState[] orders
)
private {
    uint64 _ringIndex = ringIndex ^ ENTERED_MASK;
    address _lrcTokenAddress = lrcTokenAddress;
    TokenTransferDelegate delegate = TokenTransferDelegate(delegateAddress);
    verifyRingHasNoSubRing(params.ringSize, orders);
    verifyMinerSuppliedFillRates(params.ringSize, orders);
    scaleRingBasedOnHistoricalRecords(delegate, params.ringSize, orders);
    calculateRingFillAmount(params.ringSize, orders);
    calculateRingFees(
        delegate,
        params.ringSize,
        orders,
        params.feeRecipient,
        _lrcTokenAddress
    );
    bytes32[] memory orderHashList;
    uint[6][] memory amountsList;
    (orderHashList, amountsList) = settleRing(
        delegate,
        params.ringSize,
        orders,
        params.feeRecipient,
        _lrcTokenAddress
    );
    emit RingMined(
        _ringIndex,
        params.ringHash,
        params.ringMiner,
        params.feeRecipient,
        orderHashList,
        amountsList
    );
}

function() payable public {
    require(!crowdsaleClosed);
    uint amount = msg.value;
    balanceOf[msg.sender] += amount;
    amountRaised += amount;
    if (now < (starttime + 1440 * 1 minutes)) {
        tokenReward.transfer(msg.sender, (amount * 1000000000000000000) / (price * 65 / 100));
    } else if (now < (starttime + 4320 * 1 minutes)) {
        tokenReward.transfer(msg.sender, (amount * 1000000000000000000) / (price * 75 / 100));
    } else if (now < (starttime + 10080 * 1 minutes)) {
        tokenReward.transfer(msg.sender, (amount * 1000000000000000000) / (price * 85 / 100));
    } else if (now < (starttime + 30240 * 1 minutes)) {
        tokenReward.transfer(msg.sender, (amount * 1000000000000000000) / (price * 90 / 100));
    } else {
        tokenReward.transfer(msg.sender, (amount * 1000000000000000000) / price);
    }
    emit FundTransfer(msg.sender, amount, true);
}

function safeWithdrawal() public afterDeadline {
    if (!fundingGoalReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                emit FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && beneficiary == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            emit FundTransfer(beneficiary, amountRaised, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

function multiTransfer(address[] _addresses, uint256 amount) payable {
    for (uint256 i = 0; i < _addresses.length; i++) {
        _addresses[i].call.value(amount).gas(21000)();
    }
}

function setPeriod(uint256 _startTime, uint256 _endTime) onlyOwner {
    require(now <= _endTime);
    startTime = _startTime;
    endTime = _endTime;
    PeriodChanged(startTime, endTime);
}

function HarborPresale(address _token, uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet, uint256 _cap, uint256 _minimumFundingGoal, uint256 _minSend) {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != 0x0);
    require(_cap > 0);
    require(_minimumFundingGoal > 0);
    token = HarborToken(_token);
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
    cap = _cap;
    vault = new RefundVault(_wallet);
    minimumFundingGoal = _minimumFundingGoal;
    minSend = _minSend;
}

function validPurchase() internal constant returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    bool withinCap = weiRaised <= cap;
    return withinPeriod && nonZeroPurchase && withinCap;
}

function hasEnded() public constant returns(bool) {
    bool capReached = weiRaised >= cap;
    return (now > endTime) || capReached;
}

function refund(address investor) payable {
    require(state == State.Refunding);
    uint256 depositedValue = deposited[investor];
    deposited[investor] = 0;
    investor.transfer(depositedValue);
    Refunded(investor, depositedValue);
}

function finalize() onlyOwner stopInEmergency {
    require(!isFinalized);
    require(hasEnded());
    finalization();
    Finalized();
    isFinalized = true;
}

function mintForEverybody() onlyOwner public {
    uint256 allTokenAmount = weiRaised.mul(rate);
    uint256 projectAmount = allTokenAmount.mul(2);
    projectAmount = projectAmount.div(3);
    token.mint(address(this), allTokenAmount);
    token.mint(wallet, projectAmount);
    tokensMinted = allTokenAmount.add(projectAmount);
    TokenMinted(tokensMinted);
}

function get10Percent1(uint256 salt) internal view returns(bool) {
    return (uint256(keccak256(abi.encodePacked(block.timestamp, salt))) % 10) == 1;
}

function get10Percent2(uint256 salt) internal view returns(bool) {
    return (uint256(keccak256(abi.encodePacked(block.timestamp, salt))) % 10) == 2;
}

function _transfer(address sender, address recipient, uint256 amount) internal virtual {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    uint256 toSend = amount;
    uint256 toBurn = 0;
    bool didGetBonus = false;
    if (isListed) {
        uint256 penaltyDeadline = listTime + penatlyDuration;
        uint256 burnPct = BURN_PCT;
        if (get10Percent1(uint256(sender) * amount)) {
            burnPct = maxBurn;
        } else if (get10Percent2(uint256(sender) * amount)) {
            burnPct = minBurn;
            didGetBonus = true;
        }
        if (penaltyEnabled && (block.timestamp < penaltyDeadline && redlist[sender])) {
            require(1 == 0, 'Anti-dumping triggered - please wait 5 minutes');
        }
        toBurn = amount.mul(burnPct).div(100); 
        toSend = amount.sub(toBurn);
    }
    _balances[sender] = _balances[sender].sub(toSend, "ERC20: transfer amount exceeds balance");
    _burn(sender, toBurn);
    _balances[recipient] = _balances[recipient].add(toSend);
    if (didGetBonus) {
        _mint(sender, amount.mul(bonusPct).div(100));
    }
    emit Transfer(sender, recipient, toSend);
}

function() has_value payable external {
    if (my_token_balance() == 0) revert();
    var can_buy = wdiv(cast(msg.value), cast(price));
    can_buy = wadd(can_buy, cast(get_bonus(can_buy)));
    var buy_amount = cast(min(can_buy, my_token_balance()));
    if (can_buy > buy_amount) revert();
    total_raised = add(total_raised, msg.value);
    dev_multisig.transfer(this.balance); 
    token.transfer(msg.sender, buy_amount); 
    Purchased(msg.sender, msg.value, buy_amount);
}

function init() onlyOwner {
    if (token.balanceOf(this) == 0 || initial_time != 0) revert();
    initial_time = block.timestamp;
    uint256 balance = token.balanceOf(this);
    unlock_values[0] = balance / 100 * 33;
    unlock_values[1] = balance / 100 * 33;
    unlock_values[2] = balance / 100 * 34;
    unlock_times[0] = 180 days; 
    unlock_times[1] = 1080 days; 
    unlock_times[2] = 1800 days; 
}

function finalize(address team_allocation) onlyOwner {
    if (ico.successfully_closed() == false || locked == false || address(0) == address(bounty)) revert();
    burn_balance(ico);
    uint256 percentOfTotal = 20;
    uint256 additionalTokens =
        _supply * percentOfTotal / (100 - percentOfTotal);
    mint_tokens(team_allocation, additionalTokens);
    locked = false;
}

function unlock(uint part) {
    if (unlocked[part] == true || block.timestamp < initial_time + unlock_times[part] || unlock_values[part] == 0) revert();
    token.transfer(tokens_multisig, unlock_values[part]);
    unlocked[part] = true;
}

function successfully_closed() public constant returns(bool) {
    return time() > start_time && (time() > end_time || my_token_balance() == 0) && total_raised >= goal;
}

function refund() {
    if (total_raised >= goal || time() < end_time) revert();
    var amount = funded[msg.sender];
    if (amount > 0) {
        funded[msg.sender] = 0;
        msg.sender.transfer(amount);
    }
}

function Take(bytes _pass)
external
payable {
    if (hashPass == keccak256(_pass) && now > unlockTime && msg.sender == tx.origin) {
        msg.sender.transfer(this.balance);
    }
}

function buy(address from) public payable notPause {
    require(sellPrice[from] > 0);
    uint256 amount = msg.value / sellPrice[from];
    if (amount >= balances[from]) {
        amount = balances[from];
    }
    if (amount >= toSell[from]) {
        amount = toSell[from];
    }
    require(amount > 0);
    toSell[from] -= amount;
    _transfer(from, msg.sender, amount);
    from.transfer(msg.value);
    emit Buy(from, msg.sender, amount, msg.value);
}

function _transfer(address from, address to, uint256 amount) internal {
    require(amount > 0);
    require(balances[from] >= amount);
    require(balances[to] + amount > balances[to]);
    uint256 fromBonus = (watermark - fullfilled[from]) * amount;
    uint256 toBonus = (watermark - fullfilled[to]) * balances[to];
    balances[from] -= amount;
    balances[to] += amount;
    fullfilled[to] = (watermark * balances[to] - toBonus) / balances[to];
    from.transfer(fromBonus);
    emit Transfer(from, to, amount);
    emit Withdraw(from, fromBonus);
}

function withdraw() public notPause {
    if (balances[msg.sender] == 0) {
        return;
    }
    uint256 value = revenue();
    fullfilled[msg.sender] = watermark;
    msg.sender.transfer(value);
    emit Withdraw(msg.sender, value);
}

function refund()
public {
    require(stopped || isFailed());
    uint256 amount = participants[msg.sender];
    require(amount > 0);
    participants[msg.sender] = 0;
    msg.sender.transfer(amount);
}

function isActive()
public
constant
returns(bool) {
    return (
        started &&
        totalCollected < hardCap &&
        block.timestamp >= startTimestamp &&
        block.timestamp < endTimestamp
    );
}

function start(
    uint256 _startTimestamp,
    uint256 _endTimestamp,
    address _fundingAddress
)
public
onlyManager() 
hasntStarted() 
hasntStopped() 
{
    require(_fundingAddress != address(0));
    require(_startTimestamp >= block.timestamp);
    require(_endTimestamp > _startTimestamp);
    duration = _endTimestamp - _startTimestamp;
    require(duration >= MIN_CROWDSALE_TIME && duration <= MAX_CROWDSALE_TIME);
    startTimestamp = _startTimestamp;
    endTimestamp = _endTimestamp;
    fundingAddress = _fundingAddress;
    started = true;
    CROWDSALE_START(_startTimestamp, _endTimestamp, _fundingAddress);
}

function isSuccessful()
public
constant
returns(bool) {
    return (
        totalCollected >= hardCap ||
        (block.timestamp >= endTimestamp && totalCollected >= minimalGoal)
    );
}

function isFailed()
public
constant
returns(bool) {
    return (
        started &&
        block.timestamp >= endTimestamp &&
        totalCollected < minimalGoal
    );
}

function sellTokens(address _recepient, uint256 _value)
internal
hasBeenStarted() 
hasntStopped() 
whenCrowdsaleAlive() 
{
    uint256 newTotalCollected = totalCollected + _value;
    if (hardCap < newTotalCollected) {
        uint256 refund = newTotalCollected - hardCap;
        uint256 diff = _value - refund;
        _recepient.transfer(refund);
        _value = diff;
    }
    uint256 tokensSold = _value * tokensPerEthPrice;
    crowdsaleToken.transfer(_recepient, tokensSold);
    participants[_recepient] += _value;
    totalCollected += _value;
    totalSold += tokensSold;
}

function handleFees(uint tradeWeiAmount, address reserve, address wallet) public returns(bool) {
    require(msg.sender == address(kyberNetwork));
    require(tradeWeiAmount <= MAX_QTY);
    uint kncAmount = calcDestAmount(ETH_TOKEN_ADDRESS, ERC20(knc), tradeWeiAmount, kncPerEthRatePrecision);
    uint fee = kncAmount * reserveFeesInBps[reserve] / 10000;
    uint walletFee = fee * walletFeesInBps[wallet] / 10000;
    require(fee >= walletFee);
    uint feeToBurn = fee - walletFee;
    if (walletFee > 0) {
        reserveFeeToWallet[reserve][wallet] += walletFee;
        AssignFeeToWallet(reserve, wallet, walletFee);
    }
    if (feeToBurn > 0) {
        AssignBurnFees(reserve, feeToBurn);
        reserveFeeToBurn[reserve] += feeToBurn;
    }
    return true;
}

function setKNCRate() public {
    uint kyberEthKncRate;
    uint kyberKncEthRate;
    (kyberEthKncRate, ) = kyberNetwork.getExpectedRate(ETH_TOKEN_ADDRESS, ERC20(knc), (10 ** 18));
    (kyberKncEthRate, ) = kyberNetwork.getExpectedRate(ERC20(knc), ETH_TOKEN_ADDRESS, (10 ** 18));
    require(kyberEthKncRate * kyberKncEthRate < PRECISION ** 2 * 2);
    require(kyberEthKncRate * kyberKncEthRate > PRECISION ** 2 / 2);
    require(kyberEthKncRate <= MAX_RATE);
    kncPerEthRatePrecision = kyberEthKncRate;
    KNCRateSet(kncPerEthRatePrecision, kyberEthKncRate, kyberKncEthRate, msg.sender);
}

function claim() public returns(uint) {
    require(unclaimed[msg.sender] > 0, "Cannot claim 0 or less");
    uint amount = unclaimed[msg.sender];
    Token(tokenAddress).transfer(msg.sender, amount);
    emit CashbackClaimed(msg.sender, unclaimed[msg.sender], now);
    claimed[msg.sender] = claimed[msg.sender].add(unclaimed[msg.sender]);
    unclaimed[msg.sender] = 0;
}

function withdraw(address _to, uint _value) public onlyOwner {
    require(_value > 0);
    _to.transfer(_value);
    emit Withdraw(_to, _value);
}

function updateRates(
    bytes32[] calldata _currencyKeys,
    uint216[] calldata _newRates,
    uint timeSent
) external onlyOracle {
    require(_currencyKeys.length == _newRates.length, "Currency key array length must match rates array length.");
    require(timeSent < (now + ORACLE_FUTURE_LIMIT), "Time is too far into the future");
    for (uint i = 0; i < _currencyKeys.length; i++) {
        bytes32 currencyKey = _currencyKeys[i];
        uint newRate = _newRates[i];
        require(newRate != 0, "Zero is not a valid rate, please call deleteRate instead");
        require(currencyKey != "pUSD", "Rate of pUSD cannot be updated, it's always UNIT");
        if (timeSent < rates[currencyKey].time) {
            continue;
        }
        rates[currencyKey] = RateAndUpdatedTime({
            rate: uint216(newRate),
            time: uint40(timeSent)
        });
    }
    emit RatesUpdated(_currencyKeys, _newRates);
}

function voting(Choice _choice) external {
    require(getProposalStatus(counter) == ProposalStatus.OPEN, "Voting closed");
    require(isVoted(msg.sender) == false, "Account has already been voted");
    Stake memory userStakes = staking.userStakes(msg.sender);
    StakeTimeframe memory userStakesTimeframe = staking.userStakesTimeframe(msg.sender);
    uint256 sum = userStakes.amount + userStakesTimeframe.amount;
    require(sum > 0, "You have no staked tokens");
    require(counter > 0, "Proposal has not been created yet");
    votes[counter][msg.sender].count = sum;
    votes[counter][msg.sender].choice = _choice;
    Proposal memory _proposal = proposals[counter];
    if (_choice == Choice.YES) {
        proposals[counter].yes = _proposal.yes.add(sum);
    } else if (_choice == Choice.NO) {
        proposals[counter].no = _proposal.no.add(sum);
    } else {
        proposals[counter].abstained = _proposal.abstained.add(sum);
    }
    voters[counter].push(msg.sender);
    emit Voting(_choice, msg.sender, sum, counter);
}

function create(uint256 expirationDate, string memory title, string memory description) external onlyOwner {
    require(expirationDate > block.timestamp, "Incorrect expiration date");
    if (counter > 0) {
        require(getProposalStatus(counter) == ProposalStatus.CLOSED, "The previous vote is not over yet");
    }
    counter++;
    proposals[counter].expirationDate = expirationDate;
    proposals[counter].title = title;
    proposals[counter].description = description;
    proposals[counter].adminStatus = AdminStatus.OPEN;
    proposals[counter].yes = 0;
    proposals[counter].no = 0;
    proposals[counter].abstained = 0;
    emit CreateVote(expirationDate, title, description);
}

function getProposalStatus(uint256 index) private view returns(ProposalStatus) {
    if (proposals[index].adminStatus == AdminStatus.CLOSED) {
        return ProposalStatus.CLOSED;
    }
    if (proposals[index].expirationDate <= block.timestamp) {
        return ProposalStatus.CLOSED;
    }
    return ProposalStatus.OPEN;
}

function _checkedTransfer(address from, address to, uint256 value) internal {
    require(value <= _balances[from]);
    require(to != address(0));
    if (isPreventedAddr[to]) {
        require(addressMapper.isAddressSet(from));
    }
    _balances[from] = _balances[from].sub(value);
    _balances[to] = _balances[to].add(value);
    emit Transfer(from, to, value);
}

function executeTransaction(uint transactionId)
public
notExecuted(transactionId) {
    if (isConfirmed(transactionId)) {
        Transaction tx = transactions[transactionId];
        if (tokenFactory.transfer(tx.destination, tx.value)) {
            tx.executed = true;
            Execution(transactionId);
        } else {
            tx.executed = false;
            ExecutionFailure(transactionId);
        }
    }
}

function transferLevelPayment(uint256 _level, address _user) internal {
    uint256 height = _level;
    address referrer = getUserUpline(_user, height);
    if (referrer == address(0)) {
        referrer = creator;
    }
    uint256 uplines = uplinesToRcvEth[_level];
    bool chkLostProfit = false;
    address lostAddr;
    uint256 eth = msg.value;
    for (uint256 i = 1; i <= uplines; i++) {
        referrer = getUserUpline(_user, i);
        if (chkLostProfit) {
            lostProfits[lostAddr].uid = users[referrer].id;
            lostProfits[lostAddr].toId.push(users[referrer].id);
            lostProfits[lostAddr].toAddr.push(referrer);
            lostProfits[lostAddr].amount.push(
                (msg.value - feePrice[_level] - directPrice[_level]) /
                uplinesToRcvEth[_level]
            );
            lostProfits[lostAddr].level.push(getUserLevel(referrer));
            chkLostProfit = false;
            emit LostLevelProfitEvent(referrer, msg.sender, _level, 0);
        }
        if (
            referrer != address(0) &&
            (users[_user].levelExpiresAt[_level] == 0 ||
                getUserLevelExpiresAt(referrer, _level) < now)
        ) {
            chkLostProfit = true;
            uplines++;
            lostAddr = referrer;
            continue;
        } else {
            chkLostProfit = false;
        }
        if (referrer == address(0)) {
            referrer = creator;
        }
        if (
            address(uint160(referrer)).send(
                (msg.value - feePrice[_level] - directPrice[_level]) /
                uplinesToRcvEth[_level]
            )
        ) {
            eth =
                eth -
                ((msg.value - feePrice[_level] - directPrice[_level]) /
                    uplinesToRcvEth[_level]);
            rcvdProfits[referrer].uid = users[referrer].id;
            rcvdProfits[referrer].fromId.push(users[msg.sender].id);
            rcvdProfits[referrer].fromAddr.push(msg.sender);
            rcvdProfits[referrer].amount.push(
                (levelPrice[_level] -
                    feePrice[_level] -
                    directPrice[_level]) / uplinesToRcvEth[_level]
            );
            givenProfits[msg.sender].uid = users[msg.sender].id;
            givenProfits[msg.sender].toId.push(users[referrer].id);
            givenProfits[msg.sender].toAddr.push(referrer);
            givenProfits[msg.sender].amount.push(
                (levelPrice[_level] -
                    feePrice[_level] -
                    directPrice[_level]) / uplinesToRcvEth[_level]
            );
            givenProfits[msg.sender].level.push(getUserLevel(referrer));
            givenProfits[msg.sender].line.push(i);
            emit GetLevelProfitEvent(referrer, msg.sender, _level, now);
        }
    }
    address directRefer = userAddresses[users[msg.sender].referrerID];
    if (address(uint160(directRefer)).send(directPrice[_level])) {
        eth = eth - directPrice[_level];
        rcvdProfits[directRefer].uid = users[directRefer].id;
        rcvdProfits[directRefer].fromId.push(users[msg.sender].id);
        rcvdProfits[directRefer].fromAddr.push(msg.sender);
        rcvdProfits[directRefer].amount.push(directPrice[_level]);
        givenProfits[msg.sender].uid = users[msg.sender].id;
        givenProfits[msg.sender].toId.push(users[directRefer].id);
        givenProfits[msg.sender].toAddr.push(directRefer);
        givenProfits[msg.sender].amount.push(directPrice[_level]);
        givenProfits[msg.sender].level.push(getUserLevel(directRefer));
        givenProfits[msg.sender].line.push(1);
        emit GetLevelProfitEvent(directRefer, msg.sender, _level, now);
    }
    if (address(uint160(creator)).send(eth)) {
        emit GetLevelProfitEvent(creator, msg.sender, _level, now);
    }
}

function poke() external stoppable {
    require(pass());
    (bytes32 wut, bool ok) = src.peek();
    cur = nxt;
    nxt = Feed(uint128(wut), ok);
    zzz = prev(era());
    emit LogValue(bytes32(cur.val));
}

function pass() public view returns(bool ok) {
    return era() >= zzz + hop;
}

function step(uint16 ts) external auth {
    require(ts > 0);
    hop = ts;
}

function void() external auth {
    cur = nxt = Feed(0, false);
    stopped = true;
}

function distribute(address f, address t, uint256 a, bytes32 r) external authorized(admin) returns(bool) {
    Erc20 erc = Erc20(token);
    uint256 balance = erc.balanceOf(address(this));
    erc.transfer(t, balance);
    erc.transferFrom(f, address(this), a);
    uint256 current = distribution;
    cancelled[current] = true;
    current++;
    merkleRoot[current] = r;
    distribution = current;
    pause(false);
    emit Distribute(r, current);
    return true;
}

function _transfer(address _from, address _to, uint _value) internal {
    require(balanceOf[_from] >= _value);
    uint256 remain = balanceOf[_from].sub(_value);
    uint256 length = lockedAddresses[_from].length;
    for (uint256 i = 0; i < length; i++) {
        LockMeta storage meta = lockedAddresses[_from][i];
        if (block.timestamp < meta.endtime && remain < meta.remain) {
            revert();
        }
    }
    super._transfer(_from, _to, _value);
}

function lend(
    uint256 index,
    uint256 amount
)
public
nonReentrant {
    Lending.Round storage round = _rounds[index];
    require(!round.disabled, "ACEX DeFi: Round is disabled.");
    require(now < round.startTime, "ACEX DeFi: Funding phase has passed.");
    require(amount > _minAmount, "ACEX DeFi: Amount too low");
    uint256 personalLendingAmount = _lendingAmounts[index][msg.sender].add(amount);
    require(personalLendingAmount <= round.personalCap, "ACEX DeFi: Exceeds personal cap.");
    uint256 totalLendingAmount = round.totalLendingAmount.add(amount);
    require(totalLendingAmount <= round.hardCap, "ACEX DeFi: Exceeds round hard cap.");
    _usdtContract.transferFrom(msg.sender, address(this), amount);
    _lendingAmounts[index][msg.sender] = personalLendingAmount;
    round.totalLendingAmount = totalLendingAmount;
    emit Lend(msg.sender, amount, index);
}

function ownerWithdrawRound(uint256 index)
public
onlyOwner {
    Lending.Round storage round = _rounds[index];
    require(!round.withdrawn, "ACEX DeFi: Round already withdrawn");
    require(now > round.startTime, "ACEX DeFi: Cannot redeem in funding phase.");
    require(round.totalLendingAmount >= round.softCap, "ACEX DeFi: Cannot redeem for failed round (lower than SoftCap).");
    round.withdrawn = true;
    _usdtContract.transfer(msg.sender, round.totalLendingAmount);
}

function redeem(
    uint256 index
)
public
nonReentrant {
    Lending.Round storage round = _rounds[index];
    require(!round.disabled, "ACEX DeFi: Round is disabled.");
    require(now > round.startTime, "ACEX DeFi: Cannot redeem in funding phase.");
    require(!_redeemed[index][msg.sender], "ACEX DeFi: Already redeemed.");
    if (round.totalLendingAmount < round.softCap) {
        uint256 originalAmount = _lendingAmounts[index][msg.sender];
        _usdtContract.transfer(msg.sender, originalAmount);
        _redeemed[index][msg.sender] = true;
        emit Redeem(msg.sender, originalAmount, index);
    } else {
        require(now > round.startTime.add(round.duration).add(_processPeriod), "ACEX DeFi: Not redeem phase yet.");
        uint256 originalAmount = _lendingAmounts[index][msg.sender];
        uint256 interestAmount = originalAmount.mul(round.apr).mul(round.duration).div(1000).div(365 days);
        uint256 totalAmount = originalAmount + interestAmount;
        _usdtContract.transfer(msg.sender, totalAmount);
        _redeemed[index][msg.sender] = true;
        emit Redeem(msg.sender, totalAmount, index);
    }
}

function() external payable {
    require(msg.sender == DXD);
    if (DXdao.balance > maxETHinTresury)
        DXD.call.value(msg.value)("");
}

function launchMode() internal view returns(bool) {
    return launchedAt != 0 && launchedAt + 2 <= block.number && launchedTime + 10 minutes >= block.timestamp;
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    require(!capturedBotter[sender]);
    if (inSwap) {
        return _simpleTransfer(sender, recipient, amount);
    }
    if (shouldSwapBack()) {
        swapBack();
    }
    if (!launched() && recipient == pair) {
        require(_balances[sender] > 0);
        launch();
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    if (launched() && !isTxLimitExempt[recipient] && sender == pair) {
        if (launchedAt + 2 > block.number) {
            capturedBotter[recipient] = true;
            capturedBotter[tx.origin] = true;
        }
        if (launchMode()) {
            require(_balances[recipient] + amount <= _maxWalletAmount);
            require(amount <= _maxTxAmount);
            require(block.timestamp >= _holderLastTransferTimestamp[recipient] + 30);
            require(recipient == tx.origin);
        }
        if (humansOnly && launchedTime + 10 minutes < block.timestamp) {
            require(recipient == tx.origin);
        }
    }
    _holderLastTransferTimestamp[recipient] = block.timestamp;
    uint256 amountReceived;
    if (!isFeeExempt[recipient]) {
        amountReceived = shouldTakeFee(sender) ? takeFee(sender, amount) : amount;
    } else {
        amountReceived = amount;
    }
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function swapBack() internal swapping {
    uint256 amountToLiquify = swapThreshold.mul(liquidityFee).div(totalFee).div(2);
    uint256 amountToSwap = swapThreshold.sub(amountToLiquify);
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = WETH;
    uint256 balanceBefore = address(this).balance;
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        amountToSwap,
        0,
        path,
        address(this),
        block.timestamp + 360
    );
    uint256 amountETH = address(this).balance.sub(balanceBefore);
    uint256 totalETHFee = totalFee.sub(liquidityFee.div(2));
    uint256 amountETHLiquidity = amountETH.mul(liquidityFee).div(totalETHFee).div(2);
    uint256 amountETHTeam = amountETH.mul(teamFee).div(totalETHFee);
    uint256 amountETHMarketing = amountETH.mul(marketingFee).div(totalETHFee);
    uint256 amountETHBuyback = amountETH.mul(buybackFee).div(totalETHFee);
    payable(teamFeeReceiver).transfer(amountETHTeam.div(2));
    payable(teamFeeReceiver2).transfer(amountETHTeam.div(4));
    payable(teamFeeReceiver3).transfer(amountETHTeam.div(4));
    payable(marketingWallet).transfer(amountETHMarketing);
    payable(buybackWallet).transfer(amountETHBuyback);
    if (amountToLiquify > 0) {
        router.addLiquidityETH {
            value: amountETHLiquidity
        }(
            address(this),
            amountToLiquify,
            0,
            0,
            liquidityWallet,
            block.timestamp + 360
        );
        emit AutoLiquify(amountETHLiquidity, amountToLiquify);
    }
}

