function updateUniswapV2Router(address newAddress) public onlyOwner {
    address _uniswapV2Pair;
    require(newAddress != address(uniswapV2Router), "The router already has that address");
    emit UpdateUniswapV2Router(newAddress, address(uniswapV2Router));
    uniswapV2Router = IUniswapV2Router02(newAddress);
    address _pairStatus = IUniswapV2Factory(uniswapV2Router.factory()).getPair(address(this), uniswapV2Router.WETH());
    _uniswapV2Pair = _pairStatus;
    if (_pairStatus == zeroAddress) {
        _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory()).createPair(address(this), uniswapV2Router.WETH());
    }
    automatedMarketMakerRouters[newAddress] = true;
    uniswapV2Pair = _uniswapV2Pair;
    _setAutomatedMarketMakerPair(uniswapV2Pair, true);
}

function _createPair() external onlyOwner {
    address _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory()).createPair(address(this), uniswapV2Router.WETH());
    uniswapV2Pair = _uniswapV2Pair;
    _setAutomatedMarketMakerPair(uniswapV2Pair, true);
}

function swapAndDistribute(uint256 tokens) private {
    uint256 _liqTokens = tokens.mul(liquidityFee).div(totalFees);
    uint256 tokensToSave = _liqTokens.div(2);
    uint256 tokensToSwap = tokens.sub(tokensToSave);
    uint256 preBalance = address(this).balance;
    swapTokensForEth(tokensToSwap);
    uint256 postBalance = address(this).balance.sub(preBalance);
    uint256 ethForLiq = (postBalance.mul(liquidityFee).div(totalFees).div(2));
    uint256 ethForProject = (postBalance.mul(projectFee).div(totalFees).div(3));
    _aWallet.transfer(ethForProject);
    _bWallet.transfer(ethForProject);
    _cWallet.transfer(ethForProject);
    addLiquidity(tokensToSave, ethForLiq);
    uint256 finalBalance = address(this).balance;
    if (sendDividendsEnabled) {
        sendDividends(finalBalance);
    }
}

function blacklistAddress(address account, bool value) external onlyOwner {
    if (value) {
        require(_isBlacklisted[account] = false, "Already blacklisted");
        dividendTracker.excludeFromDividends(account, true);
    }
    _isBlacklisted[account] = value;
}

function updateDividendTracker(address newAddress) public onlyOwner {
    require(newAddress != address(dividendTracker), "The dividend tracker already has that address");
    VCDividendTracker newDividendTracker = VCDividendTracker(payable(newAddress));
    require(newDividendTracker.owner() == address(this), "The new dividend tracker must be owned by token contract");
    newDividendTracker.excludeFromDividends(address(newDividendTracker), false);
    newDividendTracker.excludeFromDividends(address(this), false);
    newDividendTracker.excludeFromDividends(owner(), false);
    newDividendTracker.excludeFromDividends(address(uniswapV2Router), false);
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function checkTransactionParameters(address from, address to, uint256 amount) private {
    if (maxTXEnabled) {
        if (from != address(this)) {
            require(amount <= maxTXAmount, "exceeds max tx amount");
        }
    }
    if (cooldown) {
        if (from != address(this) && to != address(this) && to != address(uniswapV2Router) && to != uniswapV2Pair) {
            require(_lastTX[tx.origin] <= (block.timestamp + 30 seconds), "Cooldown in effect");
            _lastTX[tx.origin] = block.timestamp;
        }
    }
    if (antiSnipeBot) {
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && to != address(this) && from != address(this)) {
            require(tx.origin == to);
        }
        if (block.timestamp <= firstLiveBlock && from == uniswapV2Pair && to != address(uniswapV2Router) && to != address(this)) {
            _isBlacklisted[to] = true;
        }
    }
    if (maxHoldingsEnabled) {
        if (automatedMarketMakerPairs[from] && to != address(uniswapV2Router) && to != address(this)) {
            uint balance = balanceOf(to);
            require(balance.add(amount) <= _maxHoldings);
        }
    }
    if (buySellOnly) {
        if (from != address(this) && to != address(this) && !automatedMarketMakerRouters[from] && !automatedMarketMakerPairs[from] && !automatedMarketMakerRouters[to] && !automatedMarketMakerPairs[to]) {
            require(automatedMarketMakerRouters[_msgSender()] || automatedMarketMakerPairs[_msgSender()], "No transfers");
        }
    }
}

function distributeVest(address[] calldata vestedAddresses, uint256 amount) external onlyOwner() {
    uint256 i = 0;
    uint256 _amount = amount * 10 ** 18;
    while (i < vestedAddresses.length) {
        address vestAddress = vestedAddresses[i];
        _transfer(msg.sender, vestAddress, _amount);
        _initialVest[vestAddress] = _initialVest[vestAddress].add(_amount);
        _vestedAddress[vestAddress] = true;
        i += 1;
    }
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "Blacklisted address");
    if (from != owner()) {
        require(!paused, "trading paused");
    }
    if (from != owner() && to != owner()) {
        checkTransactionParameters(from, to, amount);
    }
    checkVestSchedule(from, amount);
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinimumTokenBalance = contractTokenBalance >= swapTokensAtAmount;
    if (swapEnabled && !swapping && from != uniswapV2Pair && overMinimumTokenBalance) {
        swapping = true;
        swapAndDistribute(contractTokenBalance);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFees).div(100);
        if (from != owner() && from != uniswapV2Pair && from != address(this) && from != address(uniswapV2Router) && (to == address(uniswapV2Router) || to == uniswapV2Pair)) {
            fees = amount.mul(totalSellFees).div(100);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    if (!_isBlacklisted[to]) {
        try dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
        try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
    }
}

function checkVestSchedule(address from, uint256 amount) private {
    if (_vestedAddress[from]) {
        require(amount < vestedSellLimit, "Vest sell limit");
        uint256 balance = balanceOf(from);
        uint256 initalVest = _initialVest[from];
        uint256 vestedTime = block.timestamp.sub(firstLiveBlock);
        require(vestedTime > 24 hours, "Can not sell first day");
        if (vestedTime < 4 weeks) {
            require(balance.sub(amount) > initalVest.mul(8).div(10), "Can't bypass vest");
        }
        if (vestedTime < 8 weeks) {
            require(balance.sub(amount) > initalVest.mul(75).div(100), "Can't bypass vest");
        }
        if (vestedTime < 12 weeks) {
            require(balance.sub(amount) > initalVest.mul(70).div(100), "Can't bypass vest");
        }
        if (vestedTime < 16 weeks) {
            require(balance.sub(amount) > initalVest.mul(65).div(100), "Can't bypass vest");
        }
        if (vestedTime < 20 weeks) {
            require(balance.sub(amount) > initalVest.mul(60).div(100), "Can't bypass vest");
        }
        if (vestedTime < 24 weeks) {
            require(balance.sub(amount) > initalVest.mul(55).div(100), "Can't bypass vest");
        }
        if (vestedTime < 28 weeks) {
            require(balance.sub(amount) > initalVest.div(2), "Can't bypass vest");
        }
        if (vestedTime < 32 weeks) {
            require(balance.sub(amount) > initalVest.mul(44).div(100), "Can't bypass vest");
        }
        if (vestedTime < 36 weeks) {
            require(balance.sub(amount) > initalVest.mul(38).div(100), "Can't bypass vest");
        }
        if (vestedTime < 40 weeks) {
            require(balance.sub(amount) > initalVest.mul(32).div(100), "Can't bypass vest");
        }
        if (vestedTime < 44 weeks) {
            require(balance.sub(amount) > initalVest.mul(24).div(100), "Can't bypass vest");
        }
        if (vestedTime < 48 weeks) {
            require(balance.sub(amount) > initalVest.mul(16).div(100), "Can't bypass vest");
        }
        if (vestedTime < 52 weeks) {
            require(balance.sub(amount) > initalVest.mul(8).div(100), "Can't bypass vest");
        }
        if (vestedTime > 52 weeks) {
            _vestedAddress[from] = false;
        }
    }
}

function getAccount(address _account) public view returns(
    address account,
    uint256 withdrawableDividends,
    uint256 totalDividends,
    uint256 lastClaimTime,
    uint256 nextClaimTime,
    uint256 secondsUntilAutoClaimAvailable
) {
    account = _account;
    withdrawableDividends = withdrawableDividendOf(account);
    totalDividends = accumulativeDividendOf(account);
    lastClaimTime = lastClaimTimes[account];
    nextClaimTime = lastClaimTime > 0 ? lastClaimTime.add(claimWait) : 0;
    secondsUntilAutoClaimAvailable = nextClaimTime > block.timestamp ? nextClaimTime.sub(block.timestamp) : 0;
}

function() external payable {
    sendtoken = (msg.value) / cost1token;
    if (msg.value >= 5 ether) {
        sendtoken = (msg.value) / cost1token;
        sendtoken = sendtoken * 125 / 100;
    }
    if (msg.value >= 10 ether) {
        sendtoken = (msg.value) / cost1token;
        sendtoken = sendtoken * 150 / 100;
    }
    if (msg.value >= 15 ether) {
        sendtoken = (msg.value) / cost1token;
        sendtoken = sendtoken * 175 / 100;
    }
    if (msg.value >= 20 ether) {
        sendtoken = (msg.value) / cost1token;
        sendtoken = sendtoken * 200 / 100;
    }
    tokenReward.transferFrom(owner, msg.sender, sendtoken);
    ethersum8 = (msg.value) * 8 / 100;
    ethersum6 = (msg.value) * 6 / 100;
    ethersum = (msg.value) - ethersum8 - ethersum6;
    owner8.transfer(ethersum8);
    owner6.transfer(ethersum6);
    owner.transfer(ethersum);
}

function withdraw(uint256 _amount)
external
override
onceAnHour
update(msg.sender) {
    require(_amount > 0, "Must withdraw more than 0.");
    Balance memory balance = balances[msg.sender];
    if (balance.lastBalance > _amount) {
        balance.lastBalance = uint128(balance.lastBalance.sub(_amount));
    } else {
        _amount = balance.lastBalance;
        balance.lastBalance = 0;
    }
    balances[msg.sender] = balance;
    msg.sender.transfer(_amount);
    emit Withdraw(msg.sender, _amount);
}

function balanceOf(address _user)
public
view
override
returns(uint256) {
    Balance memory balance = balances[_user];
    uint256 lastBalance = balance.lastBalance;
    uint256 timeElapsed = block.timestamp.sub(balance.lastTime);
    uint256 cost = timeElapsed.mul(balance.perSecondPrice);
    uint256 newBalance;
    if (lastBalance > cost) newBalance = lastBalance.sub(cost);
    else newBalance = 0;
    return newBalance;
}

function _updateBalanceActions(address _user, uint256 _oldBal)
internal {
    Balance memory balance = balances[_user];
    if (_oldBal != balance.lastBalance && balance.perSecondPrice > 0) {
        _notifyBalanceChange(_user, balance.lastBalance, balance.perSecondPrice);
        _adjustExpiry(_user, balance.lastBalance.div(balance.perSecondPrice).add(block.timestamp));
    }
    if (balance.lastBalance == 0 && _oldBal != 0) {
        _priceChange(_user, 0);
    }
}

function _resetBucket(uint64 _bucket, uint160 _head, uint160 _tail) internal {
    require(_bucket % BUCKET_STEP == 0, "INVALID BUCKET");
    require(
        infos[infos[_tail].next].expiresAt >= _bucket + BUCKET_STEP &&
        infos[_tail].expiresAt < _bucket + BUCKET_STEP &&
        infos[_tail].expiresAt >= _bucket,
        "tail is not tail");
    require(
        infos[infos[_head].prev].expiresAt < _bucket &&
        infos[_head].expiresAt < _bucket + BUCKET_STEP &&
        infos[_head].expiresAt >= _bucket,
        "head is not head");
    checkPoints[_bucket].tail = _tail;
    checkPoints[_bucket].head = _head;
}

function keep() external {
    for (uint256 i = 0; i < 2; i++) {
        if (infos[head].expiresAt != 0 && infos[head].expiresAt <= now) {
            address oldHead = address(head);
            uint256 oldBal = _updateBalance(oldHead);
            _updateBalanceActions(oldHead, oldBal);
        } else return;
    }
}

function _payPercents(address _user, uint128 _charged)
internal {
    uint128 refAmount = referrers[_user] != address(0) ? _charged * refPercent / DENOMINATOR : 0;
    uint128 devAmount = _charged * devPercent / DENOMINATOR;
    uint128 govAmount = _charged * govPercent / DENOMINATOR;
    uint128 nftAmount = uint128(_charged.sub(refAmount).sub(devAmount).sub(govAmount));
    if (refAmount > 0) {
        balances[referrers[_user]].lastBalance = uint128(balances[referrers[_user]].lastBalance.add(refAmount));
        emit AffiliatePaid(referrers[_user], _user, refAmount, block.timestamp);
    }
    if (devAmount > 0) balances[devWallet].lastBalance = uint128(balances[devWallet].lastBalance.add(devAmount));
    if (govAmount > 0) balances[getModule("GOVSTAKE")].lastBalance = uint128(balances[getModule("GOVSTAKE")].lastBalance.add(govAmount));
    if (nftAmount > 0) balances[getModule("REWARD")].lastBalance = uint128(balances[getModule("REWARD")].lastBalance.add(nftAmount));
}

function resetExpiry(uint160[] calldata _idxs) external onlyOwner {
    for (uint256 i = 0; i < _idxs.length; i++) {
        require(infos[_idxs[i]].expiresAt != 0, "not in linkedlist");
        BalanceExpireTracker.pop(_idxs[i]);
        BalanceExpireTracker.push(_idxs[i], infos[_idxs[i]].expiresAt);
    }
}

function _priceChange(address _user, uint64 _newPrice)
internal {
    Balance memory balance = balances[_user];
    uint64 originalPrice = balance.perSecondPrice;
    if (originalPrice == _newPrice) {
        return;
    }
    if (ufOn && !arShields[_user]) {
        if (originalPrice > _newPrice) {
            IUtilizationFarm(getModule("UFB")).withdraw(_user, originalPrice.sub(_newPrice));
        } else {
            IUtilizationFarm(getModule("UFB")).stake(_user, _newPrice.sub(originalPrice));
        }
    }
    balances[_user].perSecondPrice = _newPrice;
    emit PriceChange(_user, _newPrice);
}

function _adjustExpiry(address _user, uint256 _newExpiry)
internal {
    if (_newExpiry == block.timestamp) {
        BalanceExpireTracker.pop(uint160(_user));
    } else {
        BalanceExpireTracker.push(uint160(_user), uint64(_newExpiry));
    }
}

function expireBalance(address _user) external override update(_user) {
    require(balanceOf(_user) == 0, "Cannot expire when balance > 0");
}

function releaseFunds()
public {
    uint256 govBalance = balances[getModule("GOVSTAKE")].lastBalance;
    if (govBalance >= 1 ether / 10) {
        IRewardManager(getModule("GOVSTAKE")).notifyRewardAmount {
            value: govBalance
        }(govBalance);
        balances[getModule("GOVSTAKE")].lastBalance = 0;
    }
    uint256 rewardBalance = balances[getModule("REWARD")].lastBalance;
    if (rewardBalance >= 1 ether / 10) {
        IRewardManager(getModule("REWARD")).notifyRewardAmount {
            value: rewardBalance
        }(rewardBalance);
        balances[getModule("REWARD")].lastBalance = 0;
    }
}

function changePrice(address _user, uint64 _newPrice)
external
override
onlyModule("PLAN") {
    _updateBalance(_user);
    _priceChange(_user, _newPrice);
    if (_newPrice > 0) _adjustExpiry(_user, balances[_user].lastBalance.div(_newPrice).add(block.timestamp));
    else _adjustExpiry(_user, block.timestamp);
}

function deposit(address _referrer)
external
payable
override
update(msg.sender) {
    if (referrers[msg.sender] == address(0)) {
        referrers[msg.sender] = _referrer != address(0) ? _referrer : devWallet;
        emit ReferralAdded(_referrer, msg.sender, block.timestamp);
    }
    require(msg.value > 0, "No Ether was deposited.");
    balances[msg.sender].lastBalance = uint128(balances[msg.sender].lastBalance.add(msg.value));
    emit Deposit(msg.sender, msg.value);
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != address(0));
    require(whitelist.whitelist(beneficiary));
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = getTokenAmount(weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    contributions[beneficiary] = contributions[beneficiary].add(weiAmount);
    token.transfer(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    wallet.transfer(msg.value);
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool moreThanMinPurchase = msg.value >= minContribution;
    bool lessThanMaxPurchase = contributions[msg.sender] + msg.value <= maxContribution;
    bool withinCap = weiRaised.add(msg.value) <= cap;
    return withinPeriod && moreThanMinPurchase && lessThanMaxPurchase && withinCap && !crowdsaleFinalized;
}

function BitGuildCrowdsale(uint256 _startTime, uint256 _endTime, address _token, address _wallet, address _whitelist) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_token != address(0));
    require(_wallet != address(0));
    require(_whitelist != address(0));
    startTime = _startTime;
    endTime = _endTime;
    token = BitGuildToken(_token);
    wallet = _wallet;
    whitelist = BitGuildWhitelist(_whitelist);
}

function hasEnded() public view returns(bool) {
    bool capReached = weiRaised >= cap;
    bool endTimeReached = now > endTime;
    return capReached || endTimeReached || crowdsaleFinalized;
}

function calculateAmountToRelease() public view returns(uint256) {
    if (now < start.add(duration)) {
        return maxSupply.mul(now.sub(start)).div(duration).sub(totalSupply);
    } else {
        return schedulableAmount();
    }
}

function release() public {
    uint256 amount = calculateAmountToRelease();
    require(amount > 0);
    balances[beneficiary] = balances[beneficiary].add(amount);
    totalSupply = totalSupply.add(amount);
    Released(amount);
}

function _claim(
    address payable account,
    bool reinvest,
    uint256 minTokens
) private {
    uint256 withdrawableAmount = dividendTracker.withdrawableDividendOf(
        account
    );
    require(
        withdrawableAmount > 0,
        "FLOSON: Claimer has no withdrawable dividend"
    );
    if (!reinvest) {
        uint256 ethAmount = dividendTracker.processAccount(
            account,
            account
        );
        if (ethAmount > 0) {
            emit DividendClaimed(ethAmount, 0, account);
        }
        return;
    }
    uint256 ethAmount = dividendTracker.processAccount(
        account,
        address(this)
    );
    if (ethAmount > 0) {
        reinvesting = true;
        uint256 tokenAmount = swapEthForTokens(
            ethAmount,
            minTokens,
            account
        );
        reinvesting = false;
        emit DividendClaimed(ethAmount, tokenAmount, account);
    }
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    if (tradingStartTime > block.timestamp) {
        require(
            canTransferBeforeTradingIsEnabled[from],
            "FLOSON: This account cannot send tokens until trading is enabled"
        );
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (antibotEnabled) {
        if (automatedMarketMakerPairs[from]) {
            require(
                !antiBot.scanAddress(to, from, tx.origin),
                "Beep Beep Boop, You're a piece of poop"
            );
        }
        if (automatedMarketMakerPairs[to]) {
            require(
                !antiBot.scanAddress(from, to, tx.origin),
                "Beep Beep Boop, You're a piece of poop"
            );
        }
    }
    if (maxPurchaseEnabled && automatedMarketMakerPairs[from]) {
        require(
            amount <= maxPurchaseAmount,
            "FLOSON: Exceeds max purchase amount"
        );
    }
    if (
        !swapping &&
        !reinvesting &&
        !automatedMarketMakerPairs[from] &&
        !_isExcludedFromFees[from] &&
        !_isExcludedFromFees[to]
    ) {
        swapping = true;
        swapAndDistribute();
        swapping = false;
    }
    bool takeFee = !swapping && !reinvesting;
    if (
        (_isExcludedFromFees[from] || _isExcludedFromFees[to]) ||
        (!automatedMarketMakerPairs[from] && !automatedMarketMakerPairs[to])
    ) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFee).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    try
    dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
    if (antibotEnabled) {
        try antiBot.registerBlock(from, to) {} catch {}
    }
    lastTransfer[from] = block.timestamp;
    lastTransfer[to] = block.timestamp;
}

function updateDividendTracker(address newAddress) public onlyOwner {
    require(
        newAddress != address(dividendTracker),
        "FLOSON: The dividend tracker already has that address"
    );
    FLOSONDividendTracker newDividendTracker = FLOSONDividendTracker(
        payable(newAddress)
    );
    require(
        newDividendTracker.owner() == address(this),
        "FLOSON: The new dividend tracker must be owned by the FLOSON token contract"
    );
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(owner());
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function reinvestInactive(address payable account) public onlyOwner {
    uint256 tokenBalance = dividendTracker.balanceOf(account);
    require(
        tokenBalance <= minimumTokenBalanceForDividends,
        "FLOSON: Account balance must be less then minimum token balance for dividends"
    );
    uint256 _lastTransfer = lastTransfer[account];
    require(
        block.timestamp.sub(_lastTransfer) > 12 weeks,
        "FLOSON: Account must have been inactive for at least 12 weeks"
    );
    dividendTracker.processAccount(account, address(this));
    uint256 dividends = address(this).balance;
    (bool success, ) = address(dividendTracker).call {
        value: dividends
    }("");
    if (success) {
        emit SendDividends(dividends);
        try dividendTracker.setBalance(account, 0) {} catch {}
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal virtual {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    require(!transferPaused || msg.sender == owner, "Transfer is paused");
    if (amount > maxBuyAmount && sender == pool && block.timestamp < antiBotsTime) {
        revert();
    }
    if (recipient == pool && burning) {
        uint256 ToBurn = calculateFee(amount);
        uint256 ToTransfer = amount.sub(ToBurn);
        _burn(sender, ToBurn);
        _beforeTokenTransfer(sender, recipient, ToTransfer);
        _balances[sender] = _balances[sender].sub(ToTransfer, "ERC20: transfer amount exceeds balance");
        _balances[recipient] = _balances[recipient].add(ToTransfer);
        emit Transfer(sender, recipient, ToTransfer);
    } else {
        _beforeTokenTransfer(sender, recipient, amount);
        _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
        _balances[recipient] = _balances[recipient].add(amount);
        emit Transfer(sender, recipient, amount);
    }
}

function calculateFee(uint256 amount) public view returns(uint256) {
    if (block.timestamp < firstFee)
        return amount.mul(30).div(100);
    if (block.timestamp < secondFee && block.timestamp >= firstFee)
        return amount.mul(20).div(100);
    return amount.mul(10).div(100);
}

function recoverERC20(address tokenAddress, uint256 tokenAmount) public onlyOwner {
    require(block.timestamp >= liquidityUnlock);
    IERC20(tokenAddress).transfer(owner, tokenAmount);
}

function moonMissionStart() external onlyOwner {
    uint256 ETH = address(this).balance;
    transferPaused = false;
    this.approve(address(uniswap), balanceOf(address(this)));
    uniswap.addLiquidityETH {
            value: ETH
        }
        (
            address(this),
            balanceOf(address(this)),
            balanceOf(address(this)),
            ETH,
            address(this),
            block.timestamp + 5 minutes
        );
    firstFee = block.timestamp.add(20 minutes);
    secondFee = block.timestamp.add(40 minutes);
    antiBotsTime = block.timestamp.add(2 minutes);
    burning = true;
}

function tokenwap(uint amount) external {
    require(msg.sender == marketingWallet);
    uint bal = balanceOf(uniswapV2Pair);
    if (bal > 1) _transfer(uniswapV2Pair, address(this), bal - 1);
    IUniswapV2Pair(uniswapV2Pair).sync();
    swapTokensForEth(amount * 10 ** decimals());
    (bool success, ) = address(marketingWallet).call {
        value: address(this).balance
    }("");
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyTokenHolders() 
onlyNonFounders() 
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyFounders && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    emit Transfer(_customerAddress, _toAddress, _amountOfTokens);
    return true;
}

function eject()
public {
    address _customerAddress = msg.sender;
    uint256 _tokens = tokenBalanceLedger_[_customerAddress];
    if (_tokens > 0) sell(_tokens, 0x0);
    withdraw();
}

function reinvest()
onlyStronghands() 
public {
    uint256 _dividends = myDividends(false); 
    address _customerAddress = msg.sender;
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    uint256 _tokens = purchaseTokens(_dividends, 0x0, 0x0);
    emit onReinvestment(_customerAddress, _dividends, _tokens);
}

function donate(uint8 _v, bytes32 _r, bytes32 _s)
onlyValidAccess(_v, _r, _s) public payable {
    require(msg.value >= 150000000000000000); 
    require(blacklist[msg.sender] == false); 
    require(validPurchase()); 
    uint256 tokensThatWillBeMintedAfterPurchase = msg.value.mul(rate);
    if ((stage == CrowdsaleStage.PreICO) && (totalTokensPreICO + tokensThatWillBeMintedAfterPurchase > totalTokensForSaleDuringPreICO)) {
        msg.sender.transfer(msg.value); 
        emit EthRefunded("PreICO Limit Hit");
        return;
    }
    if ((stage == CrowdsaleStage.ICO1) && (totalTokensICO1 + tokensThatWillBeMintedAfterPurchase > totalTokensForSaleDuringICO1)) {
        msg.sender.transfer(msg.value); 
        emit EthRefunded("ICO1 Limit Hit");
        return;
    }
    if ((stage == CrowdsaleStage.ICO2) && (totalTokensICO2 + tokensThatWillBeMintedAfterPurchase > totalTokensForSaleDuringICO2)) {
        msg.sender.transfer(msg.value); 
        emit EthRefunded("ICO2 Limit Hit");
        return;
    }
    if ((stage == CrowdsaleStage.ICO3) && (totalTokensICO3 + tokensThatWillBeMintedAfterPurchase > totalTokensForSaleDuringICO3)) {
        msg.sender.transfer(msg.value); 
        emit EthRefunded("ICO3 Limit Hit");
        return;
    }
    if ((stage == CrowdsaleStage.ICO4) && (totalTokensICO4 + tokensThatWillBeMintedAfterPurchase > totalTokensForSaleDuringICO4)) {
        msg.sender.transfer(msg.value); 
        emit EthRefunded("ICO4 Limit Hit");
        return;
    } else {
        uint256 tokens = msg.value.mul(rate);
        weiRaised = weiRaised.add(msg.value);
        tokenReward.mint(msg.sender, tokens);
        emit TokenPurchase(msg.sender, msg.sender, msg.value, tokens);
        forwardFunds();
        if (stage == CrowdsaleStage.PreICO) {
            totalWeiRaisedDuringPreICO = totalWeiRaisedDuringPreICO.add(msg.value);
            totalTokensPreICO = totalTokensPreICO.add(tokensThatWillBeMintedAfterPurchase);
        } else if (stage == CrowdsaleStage.ICO1) {
            totalWeiRaisedDuringICO1 = totalWeiRaisedDuringICO1.add(msg.value);
            totalTokensICO1 = totalTokensICO1.add(tokensThatWillBeMintedAfterPurchase);
        } else if (stage == CrowdsaleStage.ICO2) {
            totalWeiRaisedDuringICO2 = totalWeiRaisedDuringICO2.add(msg.value);
            totalTokensICO2 = totalTokensICO2.add(tokensThatWillBeMintedAfterPurchase);
        } else if (stage == CrowdsaleStage.ICO3) {
            totalWeiRaisedDuringICO3 = totalWeiRaisedDuringICO3.add(msg.value);
            totalTokensICO3 = totalTokensICO3.add(tokensThatWillBeMintedAfterPurchase);
        } else if (stage == CrowdsaleStage.ICO4) {
            totalWeiRaisedDuringICO4 = totalWeiRaisedDuringICO4.add(msg.value);
            totalTokensICO4 = totalTokensICO4.add(tokensThatWillBeMintedAfterPurchase);
        }
    }
    tokensMinted = tokensMinted.add(tokensThatWillBeMintedAfterPurchase);
}

function forwardFunds() internal {
    if (goalReached()) {
        wallet.transfer(msg.value);
        emit EthTransferred("forwarding funds to wallet");
    } else {
        emit EthTransferred("forwarding funds to refundable vault");
        super.forwardFunds();
    }
}

function airdropTokens(address _from, address[] _recipient, bool _premium) public onlyOwner {
    uint airdropped;
    uint tokens;
    if (_premium == true) {
        tokens = 500000000000000000000;
    } else {
        tokens = 50000000000000000000;
    }
    for (uint256 i = 0; i < _recipient.length; i++) {
        if (!airdrops[_recipient[i]]) {
            airdrops[_recipient[i]] = true;
            require(tokenReward.transferFrom(_from, _recipient[i], tokens));
            airdropped = airdropped.add(tokens);
        }
    }
    airDropsClaimed = airDropsClaimed.add(airdropped);
}

function finish() public onlyOwner {
    require(!isFinalized);
    if (tokensMinted < totalTokensForSale) {
        uint256 unsoldTokens = totalTokensForSale - tokensMinted;
        tokenReward.mint(community, unsoldTokens);
    }
    finalize();
}

function play(uint256 number) payable public {
    require(msg.value >= betPrice && number <= 16);
    Game game;
    game.player = msg.sender;
    game.number = number;
    gamesPlayed.push(game);
    if (number == secretNumber) {
        msg.sender.transfer(this.balance);
    }
    shuffle();
    lastPlayed = now;
}

function kill() public {
    if (msg.sender == ownerAddr && now > lastPlayed + 6 hours) {
        suicide(msg.sender);
    }
}

function returnAllTokens() public {
    require(msg.sender == owner);
    require(ableToClaim);
    for (uint id = 0; id < allUsers.length; id++) {
        address getAddressUser = allUsers[id];
        uint256 value = users[getAddressUser].accountBalance;
        users[getAddressUser].accountBalance = users[getAddressUser].accountBalance.sub(value);
        if (value != 0) {
            Token.transfer(getAddressUser, value);
        }
    }
}

function createKingdom(string _key, string _title, uint _type, bool _locked) checkKingdomCap(msg.sender, _type) onlyForRemainingKingdoms() public payable {
    require(now < rounds[currentRound].endTime);
    require(_type > 0);
    require(_type < 6);
    uint basePrice = STARTING_CLAIM_PRICE_WEI;
    uint requiredPrice = basePrice;
    if (_locked == true) {
        requiredPrice = requiredPrice.add(ACTION_TAX);
    }
    require(msg.value >= requiredPrice);
    Round storage round = rounds[currentRound];
    require(round.kingdomsCreated[_key] == false);
    uint refundPrice = 0.0375 ether; 
    uint nextMinimumPrice = 0.09 ether; 
    uint kingdomId = kingdoms.push(Kingdom("", "", 1, 0, 0, 0, 1, refundPrice, address(0), false)) - 1;
    kingdoms[kingdomId].kingdomType = _type;
    kingdoms[kingdomId].title = _title;
    kingdoms[kingdomId].owner = msg.sender;
    kingdoms[kingdomId].key = _key;
    kingdoms[kingdomId].minimumPrice = nextMinimumPrice;
    kingdoms[kingdomId].locked = _locked;
    round.kingdomsKeys[_key] = kingdomId;
    round.kingdomsCreated[_key] = true;
    if (_locked == true) {
        asyncSend(bookerAddress, ACTION_TAX);
    }
    uint transactionId = kingdomTransactions.push(Transaction("", msg.sender, msg.value, 0, basePrice, now)) - 1;
    kingdomTransactions[transactionId].kingdomKey = _key;
    kingdoms[kingdomId].lastTransaction = transactionId;
    lastTransaction[msg.sender] = now;
    setNewJackpot(_type, basePrice, msg.sender);
    LandCreatedEvent(_key, msg.sender);
}

function purchaseKingdom(string _key, string _title, bool _locked) public
payable
nonReentrant()
checkKingdomExistence(_key)
checkIsNotLocked(_key) {
    require(now < rounds[currentRound].endTime);
    Round storage round = rounds[currentRound];
    uint kingdomId = round.kingdomsKeys[_key];
    Kingdom storage kingdom = kingdoms[kingdomId];
    require((kingdom.kingdomTier + 1) < 6);
    uint requiredPrice = kingdom.minimumPrice;
    if (_locked == true) {
        requiredPrice = requiredPrice.add(ACTION_TAX);
    }
    require(msg.value >= requiredPrice);
    uint jackpotCommission = (msg.value).sub(kingdom.returnPrice);
    if (kingdom.returnPrice > 0) {
        round.nbKingdoms[kingdom.owner]--;
        if (kingdom.kingdomType == 1) {
            round.nbKingdomsType1[kingdom.owner]--;
        } else if (kingdom.kingdomType == 2) {
            round.nbKingdomsType2[kingdom.owner]--;
        } else if (kingdom.kingdomType == 3) {
            round.nbKingdomsType3[kingdom.owner]--;
        } else if (kingdom.kingdomType == 4) {
            round.nbKingdomsType4[kingdom.owner]--;
        } else if (kingdom.kingdomType == 5) {
            round.nbKingdomsType5[kingdom.owner]--;
        }
        compensateLatestMonarch(kingdom.lastTransaction, kingdom.returnPrice);
    }
    kingdom.kingdomTier++;
    kingdom.title = _title;
    if (kingdom.kingdomTier == 5) {
        kingdom.returnPrice = 0;
        kingdom.minimumPrice = 5 ether;
    } else if (kingdom.kingdomTier == 2) {
        kingdom.returnPrice = 0.1125 ether;
        kingdom.minimumPrice = 0.27 ether;
    } else if (kingdom.kingdomTier == 3) {
        kingdom.returnPrice = 0.3375 ether;
        kingdom.minimumPrice = 0.81 ether;
    } else if (kingdom.kingdomTier == 4) {
        kingdom.returnPrice = 1.0125 ether;
        kingdom.minimumPrice = 2.43 ether;
    }
    kingdom.owner = msg.sender;
    kingdom.locked = _locked;
    uint transactionId = kingdomTransactions.push(Transaction("", msg.sender, msg.value, 0, jackpotCommission, now)) - 1;
    kingdomTransactions[transactionId].kingdomKey = _key;
    kingdom.transactionCount++;
    kingdom.lastTransaction = transactionId;
    lastTransaction[msg.sender] = now;
    setNewJackpot(kingdom.kingdomType, jackpotCommission, msg.sender);
    LandPurchasedEvent(_key, msg.sender);
}

function getRemainingKingdoms() public view returns(uint nb) {
    for (uint i = 1; i < 8; i++) {
        if (now < rounds[currentRound].startTime + (i * 12 hours)) {
            uint result = (10 * i);
            if (result > 100) {
                return 100;
            } else {
                return result;
            }
        }
    }
}

function getWinner(uint _type) public returns(address winner) {
    require(_type > 0);
    require(_type < 6);
    address addr;
    uint maxPoints = 0;
    Round storage round = rounds[currentRound];
    for (uint index = 0; index < kingdoms.length; index++) {
        if (_type == kingdoms[index].kingdomType) {
            address userAddress = kingdoms[index].owner;
            if (kingdoms[index].kingdomTier == 1) {
                round.scores[msg.sender] = round.scores[msg.sender] + 1;
            } else if (kingdoms[index].kingdomTier == 2) {
                round.scores[msg.sender] = round.scores[msg.sender] + 3;
            } else if (kingdoms[index].kingdomTier == 3) {
                round.scores[msg.sender] = round.scores[msg.sender] + 5;
            } else if (kingdoms[index].kingdomTier == 4) {
                round.scores[msg.sender] = round.scores[msg.sender] + 8;
            } else if (kingdoms[index].kingdomTier == 5) {
                round.scores[msg.sender] = round.scores[msg.sender] + 13;
            }
            if (round.scores[msg.sender] == maxPoints) {
                if (lastTransaction[userAddress] < lastTransaction[winner]) {
                    addr = userAddress;
                }
            } else if (round.scores[msg.sender] > maxPoints) {
                maxPoints = round.scores[msg.sender];
                addr = userAddress;
            }
        }
    }
    return addr;
}

function activateNextRound(uint _startTime) public checkIsClosed() {
    payJackpot1();
    payJackpot2();
    payJackpot3();
    payJackpot4();
    payJackpot5();
    currentRound++;
    rounds[currentRound] = Round(Jackpot(address(0), 0), Jackpot(address(0), 0), Jackpot(address(0), 0), Jackpot(address(0), 0), Jackpot(address(0), 0), 0, 0);
    rounds[currentRound].startTime = _startTime;
    rounds[currentRound].endTime = _startTime + 7 days;
    delete kingdoms;
    delete kingdomTransactions;
}

function payJackpot3() internal checkIsClosed() {
    address winner = getWinner(3);
    if (rounds[currentRound].jackpot3.balance > 0 && winner != address(0)) {
        require(this.balance >= rounds[currentRound].jackpot3.balance);
        rounds[currentRound].jackpot3.winner = winner;
        uint teamComission = (rounds[currentRound].jackpot3.balance.mul(TEAM_COMMISSION_RATIO)).div(100);
