    return super.transferFrom(_from, _to, _value);
}

function transfer(address _to, uint256 _value) shouldPassPolicy(msg.sender, _to) public returns(bool) {
    return super.transfer(_to, _value);
}

function takeAway(address _holder, address _to) onlyOwner public returns(bool) {
    require(userRegistry.knownAddress(_holder) && !userRegistry.hasIdentity(_holder));
    uint allBalance = balances[_holder];
    balances[_to] = balances[_to].add(allBalance);
    balances[_holder] = 0;
    Transfer(_holder, _to, allBalance);
}

function swapto(address _to, uint256 _value) public onlyOwner returns(bool) {
    require(totalSupply_.add(_value) <= limit);
    ASD asd = ASD(ASDAddress);
    asd.burn(_value);
    totalSupply_ = totalSupply_.add(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(address(0), _to, _value);
    return true;
}

function fill() public onlyOwner returns(bool) {
    ASD asd = ASD(ASDAddress);
    uint256 total = asd.totalSupply();
    uint256 _value = limit.sub(total).sub(totalSupply_);
    totalSupply_ = totalSupply_.add(_value);
    balances[this] = balances[this].add(_value);
    emit Transfer(address(0), this, _value);
    return true;
}

function swap(uint256 _value) public onlyOwner returns(bool) {
    require(totalSupply_.add(_value) <= limit);
    ASD asd = ASD(ASDAddress);
    asd.burn(_value);
    totalSupply_ = totalSupply_.add(_value);
    balances[this] = balances[this].add(_value);
    emit Transfer(address(0), this, _value);
    return true;
}

function startDistribution() external onlyOwner() {
    require(openingTime == 0);
    openingTime = block.timestamp;
    closingTime = openingTime.add(duration);
}

function burnTokens() public onlyOwner {
    require(block.timestamp > endTime);
    uint256 remaining = balances[address(0)];
    airdropActive = false;
    XTVBurned = remaining;
}

function updateReservedWei() public {
    require(weiRaised.add(preSale.weiRaised()) >= softCap && now > endCrowdSaleTime);
    uint256 curWei;
    if (!firstStageRefund && now > endCrowdSaleTime) {
        curWei = 500 * 1 ether;
        reservedWei = curWei;
        restWei = weiRaised.sub(curWei);
        firstStageRefund = true;
    }
    if (!secondStageRefund && now > endCrowdSaleTime + 99 * 1 days) {
        curWei = restWei.mul(30).div(100);
        reservedWei = reservedWei.add(curWei);
        restWei = restWei.sub(curWei);
        secondStageRefund = true;
    }
    if (!finalStageRefund && now > endRefundableTime) {
        reservedWei = reservedWei.add(restWei);
        restWei = 0;
        finalStageRefund = true;
    }
}

function buyTokens(address _beneficiary) saleIsOn isUnderHardCap nonReentrant public payable {
    require(_beneficiary != address(0));
    require(msg.value >= minimumInvest);
    uint256 weiAmount = msg.value;
    uint256 tokens = getTokenAmount(weiAmount);
    uint256 bonusPercent = getBonusPercent();
    tokens = tokens.add(tokens.mul(bonusPercent).div(100));
    token.mint(_beneficiary, tokens);
    weiRaised = weiRaised.add(weiAmount);
    balances[_beneficiary] = balances[_beneficiary].add(weiAmount);
    balancesInToken[_beneficiary] = balancesInToken[_beneficiary].add(tokens);
    if (weiRaised >= hardCap) {
        endCrowdSaleTime = now;
        endRefundableTime = endCrowdSaleTime + 130 * 1 days;
    }
    TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens);
}

function _unwrap(address user, uint amount, uint fee, uint bscNonce) private {
    require(user != address(0), "ERC20ToBEP20Wrapper: Can't be zero address");
    require(bscToEthUserUnwrapNonces[user][bscNonce] == 0, "ERC20ToBEP20Wrapper: Already processed");
    require(amount >= fee, "ERC20ToBEP20Wrapper: Fee ig greater than amount");
    require(NBU.transfer(user, amount - fee), "ERC20ToBEP20Wrapper: Error transferring");
    uint unwrapNonce = ++userUnwrapNonces[user];
    bscToEthUserUnwrapNonces[user][bscNonce] = unwrapNonce;
    unwraps[user][unwrapNonce].amount = amount;
    unwraps[user][unwrapNonce].fee = fee;
    unwraps[user][unwrapNonce].bscNonce = bscNonce;
    emit Unwrap(user, unwrapNonce, bscNonce, amount, fee);
}

function wrap(uint amount) external {
    require(amount >= minWrapAmount, "ERC20ToBEP20Wrapper: Value too small");
    require(NBU.transferFrom(msg.sender, address(this), amount), "ERC20ToBEP20Wrapper: Error transferring");
    uint userWrapNonce = ++userWrapNonces[msg.sender];
    wraps[msg.sender][userWrapNonce] = amount;
    emit Wrap(msg.sender, userWrapNonce, amount);
}

function getDistributionAmount() public view returns(uint256) {
    uint256 surfBalance = surf.balanceOf(address(this));
    if (surfBalance == 0) return 0;
    uint256 daysSinceLastDistribution = getDaysSinceLastDistribution();
    if (daysSinceLastDistribution == 0) return 0;
    uint256 total = 0;
    for (uint256 i = 0; i < daysSinceLastDistribution; i++) {
        total += baseSurfReward + (extraSurfReward * ((surfBalance - total) / 100000e18));
    }
    total = total > surfBalance ? surfBalance : total;
    return total;
}

function timeUntilNextDistribution() external view returns(uint256) {
    if (block.timestamp > lastDistribution + DISTRIBUTION_INTERVAL) {
        return 0;
    }
    return (lastDistribution + DISTRIBUTION_INTERVAL) - block.timestamp;
}

