function deposit(address payable vault, address asset, uint amount, string memory memo) external payable {
    uint safeAmount;
    if (asset == address(0)) {
        safeAmount = msg.value;
        (bool success, bytes memory data) = vault.call {
            value: safeAmount
        }("");
        require(success && (data.length == 0 || abi.decode(data, (bool))));
    } else if (asset == RUNE) {
        safeAmount = amount;
        iRUNE(RUNE).transferTo(address(this), amount);
        iERC20(RUNE).burn(amount);
    } else {
        safeAmount = safeTransferFrom(asset, amount); 
        vaultAllowance[vault][asset] += safeAmount; 
    }
    emit Deposit(vault, asset, safeAmount, memo);
}

function closeCrowdsale() onlyOwner public {
    require(!crowdsaleClosed);
    beneficiary.transfer(this.balance);
    token.mint(beneficiary, token.cap().sub(token.totalSupply()));
    token.finishMinting();
    token.transferOwnership(beneficiary);
    crowdsaleClosed = true;
    CrowdsaleClose();
}

function sell(uint256 _value) whenNotPaused public {
    require(!crowdsaleClosed);
    require(canSell[msg.sender] >= _value);
    require(token.balanceOf(msg.sender) >= _value);
    Step memory step = steps[currentStep];
    require(step.sale);
    canSell[msg.sender] = canSell[msg.sender].sub(_value);
    token.transferOwner(msg.sender, beneficiary, _value);
    uint sum = _value.mul(step.priceTokenWei).div(1 ether);
    msg.sender.transfer(sum);
    Sell(msg.sender, _value, sum);
}

function purchase() whenNotPaused payable public {
    require(!crowdsaleClosed);
    Step memory step = steps[currentStep];
    require(msg.value >= step.minInvestEth);
    require(step.tokensSold < step.tokensForSale);
    uint sum = msg.value;
    uint amount = sum.mul(1 ether).div(step.priceTokenWei);
    uint retSum = 0;
    if (step.tokensSold.add(amount) > step.tokensForSale) {
        uint retAmount = step.tokensSold.add(amount).sub(step.tokensForSale);
        retSum = retAmount.mul(step.priceTokenWei).div(1 ether);
        amount = amount.sub(retAmount);
        sum = sum.sub(retSum);
    }
    steps[currentStep].tokensSold = step.tokensSold.add(amount);
    steps[currentStep].collectedWei = step.collectedWei.add(sum);
    if (currentStep == 0) {
        canSell[msg.sender] = canSell[msg.sender].add(amount);
    }
    if (step.transferBalance) {
        uint p1 = sum.div(200);
        (0xD8C7f2215f90463c158E91b92D81f0A1E3187C1B).transfer(p1.mul(3));
        (0x8C8d80effb2c5C1E4D857e286822E0E641cA3836).transfer(p1.mul(3));
        beneficiary.transfer(sum.sub(p1.mul(6)));
    }
    token.mint(msg.sender, amount);
    if (retSum > 0) {
        msg.sender.transfer(retSum);
    }
    Purchase(msg.sender, amount, sum);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(YFIs).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(YFIs).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(YFIs).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function STAKE(uint256 tokens) external {
    require(IERC20(YFIs).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function setInflation() internal {
    uint256 currentBondingRate = 0;
    uint256 totalSupply = livepeerToken().totalSupply();
    if (totalSupply > 0) {
        uint256 totalBonded = bondingManager().getTotalBonded();
        currentBondingRate = MathUtils.percPoints(totalBonded, totalSupply);
    }
    if (currentBondingRate < targetBondingRate) {
        inflation = inflation.add(inflationChange);
    } else if (currentBondingRate > targetBondingRate) {
        if (inflationChange > inflation) {
            inflation = 0;
        } else {
            inflation = inflation.sub(inflationChange);
        }
    }
}

function setInflationChange(uint256 _inflationChange) external onlyControllerOwner {
    require(MathUtils.validPerc(_inflationChange));
    inflationChange = _inflationChange;
    ParameterUpdate("inflationChange");
}

function setCurrentRewardTokens() external onlyRoundsManager whenSystemNotPaused {
    setInflation();
    currentMintableTokens = MathUtils.percOf(livepeerToken().totalSupply(), inflation);
    currentMintedTokens = 0;
    SetCurrentRewardTokens(currentMintableTokens, inflation);
}

function setTargetBondingRate(uint256 _targetBondingRate) external onlyControllerOwner {
    require(MathUtils.validPerc(_targetBondingRate));
    targetBondingRate = _targetBondingRate;
    ParameterUpdate("targetBondingRate");
}

function createReward(uint256 _fracNum, uint256 _fracDenom) external onlyBondingManager whenSystemNotPaused returns(uint256) {
    uint256 mintAmount = MathUtils.percOf(currentMintableTokens, _fracNum, _fracDenom);
    currentMintedTokens = currentMintedTokens.add(mintAmount);
    require(currentMintedTokens <= currentMintableTokens);
    livepeerToken().mint(this, mintAmount);
    return mintAmount;
}

function isItOpen() public view returns(string status) {
    if (now > openingTime && now < closingTime) {
        return "SALE OPEN";
    } else {
        return "SALE CLOSE";
    }
}

function generateTokens(address _owner, uint _theTotalSupply)
private onlyContract returns(bool) {
    require(tokenGenerationLock == false);
    uint curTotalSupply = totalSupply();
    require(curTotalSupply + _theTotalSupply >= curTotalSupply); 
    uint previousBalanceTo = balanceOf(_owner);
    require(previousBalanceTo + _totalSupply >= previousBalanceTo); 
    updateValueAtNow(totalSupplyHistory, curTotalSupply + _totalSupply);
    updateValueAtNow(balances[_owner], previousBalanceTo + _totalSupply);
    emit Transfer(0, _owner, _totalSupply);
    tokenGenerationLock = true;
    return true;
}

function approve(address _spender, uint256 _amount) public returns(bool success) {
    require(transfersEnabled);
    require((_amount == 0) || (allowed[msg.sender][_spender] == 0));
    if (isContract(controller)) {
        require(TokenController(controller).onApprove(msg.sender, _spender, _amount));
    }
    allowed[msg.sender][_spender] = _amount;
    emit Approval(msg.sender, _spender, _amount);
    return true;
}

function complete_buy_exchange() private {
    uint256 amount_give_ = msg.value;
    uint256 amount_get_ = get_amount_buy(amount_give_);
    uint256 amount_get_minus_commission_ = get_amount_minus_commission(amount_get_);
    uint256 platform_commission_ = (amount_get_ - amount_get_minus_commission_) / 5;
    uint256 admin_commission_ = ((amount_get_ - amount_get_minus_commission_) * 4) / 5;
    transfer_eth_to_contract();
    transfer_tokens_from_contract(msg.sender, amount_get_minus_commission_);
    transfer_tokens_from_contract(platform, platform_commission_);
    if (admin_commission_activated) {
        transfer_tokens_from_contract(admin, admin_commission_);
    }
}

function buy() payable public {
    require(!closeBuy);
    uint amount = msg.value / buyPrice;
    uint market_value = amount * buyPrice;
    uint commission = market_value * 4 / 1000;
    if (commission < minimumCommission) {
        commission = minimumCommission;
    }
    address contr = this;
    require(contr.balance >= commission);
    commissionGetter.transfer(commission);
    _transfer(this, msg.sender, amount);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(_value <= allowance[_from][msg.sender]);
    uint market_value = _value * sellPrice;
    uint commission = market_value * 4 / 1000;
    if (commission < minimumCommission) {
        commission = minimumCommission;
    }
    address contr = this;
    require(contr.balance >= commission);
    commissionGetter.transfer(commission);
    allowance[_from][msg.sender] -= _value;
    _transfer(_from, _to, _value);
    return true;
}

function sell(uint256 amount) public {
    require(!closeSell);
    address contr = this;
    uint market_value = amount * sellPrice;
    uint commission = market_value * 4 / 1000;
    if (commission < minimumCommission) {
        commission = minimumCommission;
    }
    uint amount_weis = market_value + commission;
    require(contr.balance >= amount_weis);
    commissionGetter.transfer(commission);
    _transfer(msg.sender, this, amount);
    msg.sender.transfer(market_value);
}

function transfer(address _to, uint256 _value) public {
    uint market_value = _value * sellPrice;
    uint commission = market_value * 4 / 1000;
    if (commission < minimumCommission) {
        commission = minimumCommission;
    }
    address contr = this;
    require(contr.balance >= commission);
    commissionGetter.transfer(commission);
    _transfer(msg.sender, _to, _value);
}

function vest() external {
    uint numEntries = numVestingEntries(msg.sender);
    uint total;
    for (uint i = 0; i < numEntries; i++) {
        uint time = getVestingTime(msg.sender, i);
        if (time > now) {
            break;
        }
        uint qty = getVestingQuantity(msg.sender, i);
        if (qty > 0) {
            vestingSchedules[msg.sender][i] = [0, 0];
            total = total.add(qty);
        }
    }
    if (total != 0) {
        totalVestedBalance = totalVestedBalance.sub(total);
        totalVestedAccountBalance[msg.sender] = totalVestedAccountBalance[msg.sender].sub(total);
        IERC20(address(periFinance)).transfer(msg.sender, total);
        emit Vested(msg.sender, now, total);
    }
}

function appendVestingEntry(
    address account,
    uint time,
    uint quantity
) public onlyOwner onlyDuringSetup {
    require(now < time, "Time must be in the future");
    require(quantity != 0, "Quantity cannot be zero");
    totalVestedBalance = totalVestedBalance.add(quantity);
    require(
        totalVestedBalance <= IERC20(address(periFinance)).balanceOf(address(this)),
        "Must be enough balance in the contract to provide for the vesting entry"
    );
    uint scheduleLength = vestingSchedules[account].length;
    require(scheduleLength <= MAX_VESTING_ENTRIES, "Vesting schedule is too long");
    if (scheduleLength == 0) {
        totalVestedAccountBalance[account] = quantity;
    } else {
        require(
            getVestingTime(account, numVestingEntries(account) - 1) < time,
            "Cannot add new vested entries earlier than the last one"
        );
        totalVestedAccountBalance[account] = totalVestedAccountBalance[account].add(quantity);
    }
    vestingSchedules[account].push([time, quantity]);
}

function buySCTK(address receiver, uint costEth)
private
notHalted
isOpen
initialized
inWhiteList(receiver)
ceilingEtherNotReached(costEth)
notEarlierThan(startTime)
returns(bool) {
    require(receiver != 0x0);
    require(costEth >= 1 ether);
    require(!isContract(receiver));
    if (lockedTokens[receiver] == 0) {
        numFunders++;
        investors.push(receiver);
        leftReleaseTimes[receiver] = MAX_UN_LOCK_TIMES; 
    }
    uint gotTokens = calculateGotTokens(costEth);
    require(preSoldTokens.add(gotTokens) <= MAX_PRE_SALE_AMOUNT);
    lockedTokens[receiver] = lockedTokens[receiver].add(gotTokens);
    preSoldTokens = preSoldTokens.add(gotTokens);
    crowdEther = crowdEther.add(costEth);
    walletOwnerAddress.transfer(costEth);
    NewSale(receiver, costEth, gotTokens);
    return true;
}

function unlock10PercentTokensInBatch()
public
onlyOwner
isClose
returns(bool) {
    for (uint8 i = 0; i < investors.length; i++) {
        if (leftReleaseTimes[investors[i]] > 0) {
            uint releasedTokens = lockedTokens[investors[i]] / leftReleaseTimes[investors[i]];
            sharesChainToken.mintToken(investors[i], releasedTokens);
            lockedTokens[investors[i]] = lockedTokens[investors[i]] - releasedTokens;
            leftReleaseTimes[investors[i]] = leftReleaseTimes[investors[i]] - 1;
        }
    }
    return true;
}

function reveal(uint256 _rID, uint256 _scretKey, bytes32 _maskHash)
public {
    require(rIDBet_[_rID].rID != 0, "cant find this round");
    uint256 _bID = rIDBet_[_rID].bID;
    require(bIDBet_[_bID].bID != 0, "cant find this bet");
    require((bIDBet_[_bID].owner == msg.sender) || admin == msg.sender, "can only be revealed by admin or owner");
    bytes32 check = keccak256(abi.encodePacked(_scretKey));
    require(check == rIDBet_[_rID].maskHash, "scretKey is not match maskHash");
    uint256 modulo = rIDBet_[_rID].total;
    bytes32 random = keccak256(abi.encodePacked(check, rIDBet_[_rID].playerCode, (block.number + now)));
    uint result = (uint(random) % modulo) + 1;
    uint256 _winPID = 0;
    for (uint i = 0; i < betList_[_rID].length; i++) {
        if (result >= betList_[_rID][i].start && result <= betList_[_rID][i].end) {
            _winPID = betList_[_rID][i].pID;
            break;
        }
    }
    uint256 reward = rIDBet_[_rID].ethAmount;
    uint256 teamFee = (bIDBet_[_bID].check.mul(3)) / 100;
    pIDPlayer_[_winPID].balance = pIDPlayer_[_winPID].balance.add(reward);
    emit onReveal(_rID, pIDPlayer_[_winPID].addr, reward, teamFee, _scretKey, result, now);
    delete rIDBet_[_rID];
    delete betList_[_rID];
    bIDrID_[_bID] = 0;
    newRound(_bID, _maskHash);
}

