function getTimeBonus(uint256 _value) public view returns(uint256) {
    if (now < startTime + 61 days) { 
        return getBonus(_value);
    } else if (now >= startTime + 61 days && now < startTime + 120 days) { 
        return getBonus2(_value);
    } else if (now >= startTime + 120 days && now < startTime + 181 days) { 
        return getBonus3(_value);
    } else if (now >= startTime + 181 days && now < endTime) { 
        return getBonus4(_value);
    }
}

function makePick(uint8 _game, uint256 _cardId) external {
    Game memory game = games[_game];
    require(now < game.startTime, "This game has already started.");
    require(strikersBaseContract.ownerOf(_cardId) == msg.sender, "You don&#39;t own this card.");
    uint8 checklistId;
    (, checklistId, ) = strikersBaseContract.cards(_cardId);
    require(_arrayContains(game.acceptedChecklistIds, checklistId), "This card is invalid for this game.");
    picksForUser[msg.sender][_game] = _cardId;
    emit PickMade(msg.sender, _game, _cardId);
