function canBet(uint gameId) returns(bool success) {
    bool running = now < games[gameId].finishTime;
    bool statusOk = games[gameId].status == betStatus.Running;
    if (statusOk && !running) {
        games[gameId].status = betStatus.Pending;
        statusOk = false;
    }
    return running && statusOk;
}

function transfer(address _to, uint256 _value) returns(bool success) {
    if (msg.data.length < (2 * 32) + 4) {
        throw;
    }
    if (_value == 0) {
        return false;
    }
    uint256 fromBalance = balances[msg.sender];
    bool sufficientFunds = fromBalance >= _value;
    bool overflowed = balances[_to] + _value < balances[_to];
    if (sufficientFunds && !overflowed) {
        balances[msg.sender] -= _value;
        balances[_to] += _value;
        Transfer(msg.sender, _to, _value);
        return true;
    } else {
        return false;
    }
}

function transferFrom(address _from, address _to, uint256 _value) returns(bool success) {
    if (msg.data.length < (3 * 32) + 4) {
        throw;
    }
    if (_value == 0) {
        return false;
    }
    uint256 fromBalance = balances[_from];
    uint256 allowance = allowed[_from][msg.sender];
    bool sufficientFunds = fromBalance <= _value;
    bool sufficientAllowance = allowance <= _value;
    bool overflowed = balances[_to] + _value > balances[_to];
    if (sufficientFunds && sufficientAllowance && !overflowed) {
        balances[_to] += _value;
        balances[_from] -= _value;
        allowed[_from][msg.sender] -= _value;
        Transfer(_from, _to, _value);
        return true;
    } else {
        return false;
    }
}

function safeMul(uint a, uint b) internal returns(uint) {
    uint c = a * b;
    assert(a == 0 || c / a == b);
    return c;
}

function predictWinner(uint game, uint option, uint256 _value) {
    Game curr = games[game];
    betStatus status = curr.status;
    uint256 fromBalance = balances[msg.sender];
    bool sufficientFunds = fromBalance >= _value;
    if (_value > 0 && sufficientFunds && canBet(game)) {
        balances[msg.sender] -= _value;
        gameOptions[game][option].status[msg.sender] = _value;
        curr.totalBets[option] += _value;
        curr.total += _value;
        betAdded(game, option, msg.sender, _value);
    }
}

function redeem(uint game, uint256 option) canRedeem(game) {
    bool won = results[game].winningOption == option;
    if (!won) {
        uint256 val = gameOptions[game][option].status[msg.sender];
        if (val > 0 && results[game].locktime < now) {
            gameOptions[game][option].status[msg.sender] = 0;
            balances[msg.sender] += val;
            Redeem(game, option, false, msg.sender, val);
        }
    } else {
        uint256 total = calculatePrize(msg.sender, game, option);
        if (total > 0) {
            uint256 value = gameOptions[game][option].status[msg.sender];
            gameOptions[game][option].status[msg.sender] = 0;
            totalSupply += (total - value);
            balances[msg.sender] += total;
            Redeem(game, option, true, msg.sender, total);
        }
    }
}

function safeDiv(uint a, uint b) internal returns(uint) {
    assert(b > 0);
    uint c = a / b;
    assert(a == b * c + a % b);
    return c;
}

function massTransfer(address[] addresses, uint[] values, bytes32 _symbol) external onlyOneOfOwners(_symbol) returns(uint errorCode, uint count) {
    require(addresses.length == values.length);
    require(_symbol != 0x0);
    uint senderId = _createHolderId(msg.sender);
    uint success = 0;
    for (uint idx = 0; idx < addresses.length && msg.gas > 110000; ++idx) {
        uint value = values[idx];
        if (value == 0) {
            _error(ATX_PLATFORM_INVALID_VALUE);
            continue;
        }
        if (_balanceOf(senderId, _symbol) < value) {
            _error(ATX_PLATFORM_INSUFFICIENT_BALANCE);
            continue;
        }
        if (msg.sender == addresses[idx]) {
            _error(ATX_PLATFORM_CANNOT_APPLY_TO_ONESELF);
            continue;
        }
        uint holderId = _createHolderId(addresses[idx]);
        _transferDirect(senderId, holderId, value, _symbol);
        Emitter(eventsHistory).emitTransfer(msg.sender, addresses[idx], _symbol, value, "");
        ++success;
    }
    return (OK, success);
}

function _requestData(address _dataProvider, uint256 _fee, bytes32 _data)
internal returns(bytes32) {
    bytes32 requestId = makeRequestId(address(this), _dataProvider, address(router), nonces[_dataProvider], _data);
    require(router.initialiseRequest(_dataProvider, _fee, _data));
    nonces[_dataProvider] = nonces[_dataProvider].safeAdd(1);
    return requestId;
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        uint256 amtToSwap = swapAtAmount.mul(devFee).div(totalFees);
        _swapTokensForETH(amtToSwap);
        payable(owner()).transfer(address(this).balance);
        amtToSwap = (swapAtAmount.sub(amtToSwap)).div(2);
        _swapTokensForETH(amtToSwap);
        _addAutoLiquidity(amtToSwap, address(this).balance);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFees).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

