    if (lastPrice < currentPrice) {
        _sellFRUITForJUICE();
        _burnJuice();
        nextConvertTime = block.timestamp + 23 hours;
    }
    lastPrice = currentPrice;
}

function payOut(address _getter) onlyContractOwner returns(uint errorCode) {
    uint amount = lock.balance;
    if (now < lock.releaseTime) {
        return TIME_LOCK_TIMESTAMP_ERROR;
    }
    if (amount == 0) {
        return TIME_LOCK_BALANCE_ERROR;
    }
    if (!ERC20Interface(asset).transfer(_getter, amount)) {
        return TIME_LOCK_TRANSFER_ERROR;
    }
    selfdestruct(msg.sender);
    return OK;
}

function payIn() onlyContractOwner returns(uint errorCode) {
    uint amount = ERC20Interface(asset).balanceOf(this);
    if (lock.balance != 0) {
        if (lock.balance != amount) {
            lock.balance = amount;
            return OK;
        }
        return TIME_LOCK_INVALID_INVOCATION;
    }
    if (amount == 0) {
        return TIME_LOCK_BALANCE_ERROR;
    }
    lock = accountData(amount, 1533081600);
    return OK;
}

function createLighthouse(
    uint256 _minimalFreeze,
    uint256 _timeoutBlocks,
    string _name
)
external
returns(address lighthouse) {
    bytes32 subnode = keccak256(abi.encodePacked(lighthouseNode, keccak256(_name)));
    require(ens.resolver(subnode) == 0);
    lighthouse = new Lighthouse(lighthouseLib, _minimalFreeze, _timeoutBlocks);
    emit NewLighthouse(lighthouse, _name);
    isLighthouse[lighthouse] = true;
    ens.setSubnodeOwner(lighthouseNode, keccak256(_name), this);
    ens.setResolver(subnode, resolver);
    resolver.setAddr(subnode, lighthouse);
}

function() external payable {
    require(msg.value > 0);
    _pre_sale_list[msg.sender] = _pre_sale_list[msg.sender].add(msg.value);
    _owner.transfer(msg.value);
    emit AddPreSaleList(msg.sender, address(this), msg.value);
}

function unlistSubName(bytes32 node) node_owner(node) {
    require(records[node].subSale == true);
    ens.setOwner(node, records[node].originalOwner);
    records[node].originalOwner = address(0x0);
    records[node].subSale = false;
    records[node].subPrice = 0;
    records[node].subExpiry = 0;
}

function expand() {
    if (expanded || saleOn()) {
        return;
    }
    expanded = true;
    uint ext = inCirculation * 1428571428 / 10 ** 9 - inCirculation;
    oxen[OX_ORG] += ext;
    inCirculation += ext;
    Transfer(this, OX_ORG, ext);
}

function saleOn() constant returns(bool) {
    return now - starttime < 31 days;
}

function buyOx() payable {
    if (!saleOn() || msg.value < 10 ** 17) {
        throw; 
    }
    uint tobuy = (msg.value * 3 * (100 + bonus())) / 10 ** 17;
    if (inCirculation + tobuy > 700000000) {
        throw; 
    }
    inCirculation += tobuy;
    oxen[msg.sender] += tobuy;
    Receipt(msg.sender, tobuy, msg.value);
}

function transfer(address to, uint ox) {
    if (ox > oxen[msg.sender] || saleOn()) {
        return;
    }
    if (!expanded) {
        expand();
    }
    oxen[msg.sender] -= ox;
    oxen[to] += ox;
    Transfer(msg.sender, to, ox);
}

function bonus() constant returns(uint) {
    uint elapsed = now - starttime;
    if (elapsed < 1 days) return 25;
    if (elapsed < 1 weeks) return 20;
    if (elapsed < 2 weeks) return 15;
    if (elapsed < 3 weeks) return 10;
    if (elapsed < 4 weeks) return 5;
    return 0;
}

function startSale() onlyOwner {
    if (starttime != 0) return;
    starttime = now; 
    inCirculation = 200000000;
    oxen[OX_ORG] = inCirculation;
    Transfer(OX_ORG, OX_ORG, inCirculation);
}

