function getPendingDivs(address _holder) public view returns(uint) {
    if (!holders.contains(_holder)) return 0;
    if (depositedTokens[_holder] == 0) return 0;
    uint timeDiff;
    uint _now = now;
    if (_now > stakingEndTime) {
        _now = stakingEndTime;
    }
    if (lastClaimedTime[_holder] >= _now) {
        timeDiff = 0;
    } else {
        timeDiff = _now.sub(lastClaimedTime[_holder]);
    }
    uint stakedAmount = depositedTokens[_holder];
    uint pendingDivs = stakedAmount
        .mul(rewardRate)
        .mul(timeDiff)
        .div(rewardInterval)
        .div(1e4);
    return pendingDivs;
}

function getPendingDivsFD(address _holder) public view returns(uint) {
    if (!holdersFD.contains(_holder)) return 0;
    if (depositedTokensFD[_holder] == 0) return 0;
    uint timeDiff;
    uint _now = now;
    if (_now > stakingEndTime) {
        _now = stakingEndTime;
    }
    if (lastClaimedTimeFD[_holder] >= _now) {
        timeDiff = 0;
    } else {
        timeDiff = _now.sub(lastClaimedTimeFD[_holder]);
    }
    uint stakedAmount = depositedTokensFD[_holder];
    uint pendingDivs = stakedAmount
        .mul(rewardRateFD)
        .mul(timeDiff)
        .div(rewardInterval)
        .div(1e4);
    return pendingDivs;
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 10;
    } else {
        tokens = msg.value * 5;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function newContract(
    address _tokenContract,
    uint256 _amount,
    string memory _toChain,
    string memory _toAddress
)
external
tokensTransferable(_tokenContract, msg.sender, _amount)
returns(bytes32 contractId) {
    contractId = sha256(
        abi.encodePacked(
            msg.sender,
            _tokenContract,
            _amount,
            block.timestamp
        )
    );
    if (haveContract(contractId))
        revert("Contract already exists");
    if (!ERC20(_tokenContract).transferFrom(msg.sender, owner(), _amount))
        revert("transferFrom sender failed");
    contracts[contractId] = SwapContract(
        msg.sender,
        owner(),
        _tokenContract,
        _amount,
        _toChain,
        _toAddress
    );
    emit SwapNew(
        contractId,
        msg.sender,
        owner(),
        _tokenContract,
        _amount
    );
}

