            "0xHandler - token approval failed"
        );
        tokenAllowanceSet[token] = true;
    }
}

function fillOrder(
    address[5] orderAddresses,
    uint[6] orderValues,
    uint fillTakerTokenAmount,
    bool shouldThrowOnInsufficientBalanceOrAllowance,
    uint8 v,
    bytes32 r,
    bytes32 s)
public
returns(uint filledTakerTokenAmount) {
    Order memory order = Order({
        maker: orderAddresses[0],
        taker: orderAddresses[1],
        makerToken: orderAddresses[2],
        takerToken: orderAddresses[3],
        feeRecipient: orderAddresses[4],
        makerTokenAmount: orderValues[0],
        takerTokenAmount: orderValues[1],
        makerFee: orderValues[2],
        takerFee: orderValues[3],
        expirationTimestampInSec: orderValues[4],
        orderHash: getOrderHash(orderAddresses, orderValues)
    });
    require(order.taker == address(0) || order.taker == msg.sender);
    require(order.makerTokenAmount > 0 && order.takerTokenAmount > 0 && fillTakerTokenAmount > 0);
    require(isValidSignature(
        order.maker,
        order.orderHash,
        v,
        r,
        s
    ));
    if (block.timestamp >= order.expirationTimestampInSec) {
        LogError(uint8(Errors.ORDER_EXPIRED), order.orderHash);
        return 0;
    }
    uint remainingTakerTokenAmount = safeSub(order.takerTokenAmount, getUnavailableTakerTokenAmount(order.orderHash));
    filledTakerTokenAmount = min256(fillTakerTokenAmount, remainingTakerTokenAmount);
    if (filledTakerTokenAmount == 0) {
        LogError(uint8(Errors.ORDER_FULLY_FILLED_OR_CANCELLED), order.orderHash);
        return 0;
    }
    if (isRoundingError(filledTakerTokenAmount, order.takerTokenAmount, order.makerTokenAmount)) {
        LogError(uint8(Errors.ROUNDING_ERROR_TOO_LARGE), order.orderHash);
        return 0;
    }
    if (!shouldThrowOnInsufficientBalanceOrAllowance && !isTransferable(order, filledTakerTokenAmount)) {
        LogError(uint8(Errors.INSUFFICIENT_BALANCE_OR_ALLOWANCE), order.orderHash);
        return 0;
    }
    uint filledMakerTokenAmount = getPartialAmount(filledTakerTokenAmount, order.takerTokenAmount, order.makerTokenAmount);
    uint paidMakerFee;
    uint paidTakerFee;
    filled[order.orderHash] = safeAdd(filled[order.orderHash], filledTakerTokenAmount);
    require(transferViaTokenTransferProxy(
        order.makerToken,
        order.maker,
        msg.sender,
        filledMakerTokenAmount
    ));
    require(transferViaTokenTransferProxy(
        order.takerToken,
        msg.sender,
        order.maker,
        filledTakerTokenAmount
    ));
    if (order.feeRecipient != address(0)) {
        if (order.makerFee > 0) {
            paidMakerFee = getPartialAmount(filledTakerTokenAmount, order.takerTokenAmount, order.makerFee);
            require(transferViaTokenTransferProxy(
                ZRX_TOKEN_CONTRACT,
                order.maker,
                order.feeRecipient,
                paidMakerFee
            ));
        }
        if (order.takerFee > 0) {
            paidTakerFee = getPartialAmount(filledTakerTokenAmount, order.takerTokenAmount, order.takerFee);
            require(transferViaTokenTransferProxy(
                ZRX_TOKEN_CONTRACT,
                msg.sender,
                order.feeRecipient,
                paidTakerFee
            ));
        }
    }
    LogFill(
        order.maker,
        msg.sender,
        order.feeRecipient,
        order.makerToken,
        order.takerToken,
        filledMakerTokenAmount,
        filledTakerTokenAmount,
        paidMakerFee,
        paidTakerFee,
        keccak256(order.makerToken, order.takerToken),
        order.orderHash
    );
    return filledTakerTokenAmount;
}

function orderUsable(
    address[8] orderAddresses,
    uint256[6] orderValues
) internal returns(bool) {
    return (
        (orderAddresses[1] == address(0) || 
            orderAddresses[1] == address(this)) && 
        orderValues[3] == 0 && 
        orderValues[4] > block.timestamp 
    );
}

function cancelOrder(
    address[5] orderAddresses,
    uint[6] orderValues,
    uint cancelTakerTokenAmount)
public
returns(uint) {
    Order memory order = Order({
        maker: orderAddresses[0],
        taker: orderAddresses[1],
        makerToken: orderAddresses[2],
        takerToken: orderAddresses[3],
        feeRecipient: orderAddresses[4],
        makerTokenAmount: orderValues[0],
        takerTokenAmount: orderValues[1],
        makerFee: orderValues[2],
        takerFee: orderValues[3],
        expirationTimestampInSec: orderValues[4],
        orderHash: getOrderHash(orderAddresses, orderValues)
    });
    require(order.maker == msg.sender);
    require(order.makerTokenAmount > 0 && order.takerTokenAmount > 0 && cancelTakerTokenAmount > 0);
    if (block.timestamp >= order.expirationTimestampInSec) {
        LogError(uint8(Errors.ORDER_EXPIRED), order.orderHash);
        return 0;
    }
    uint remainingTakerTokenAmount = safeSub(order.takerTokenAmount, getUnavailableTakerTokenAmount(order.orderHash));
    uint cancelledTakerTokenAmount = min256(cancelTakerTokenAmount, remainingTakerTokenAmount);
    if (cancelledTakerTokenAmount == 0) {
        LogError(uint8(Errors.ORDER_FULLY_FILLED_OR_CANCELLED), order.orderHash);
        return 0;
    }
    cancelled[order.orderHash] = safeAdd(cancelled[order.orderHash], cancelledTakerTokenAmount);
    LogCancel(
        order.maker,
        order.feeRecipient,
        order.makerToken,
        order.takerToken,
        getPartialAmount(cancelledTakerTokenAmount, order.takerTokenAmount, order.makerTokenAmount),
        cancelledTakerTokenAmount,
        keccak256(order.makerToken, order.takerToken),
        order.orderHash
    );
    return cancelledTakerTokenAmount;
}

function withdrawOnBehalf(uint _amount, string _paySystem, uint _nonce, uint8 _v, bytes32 _r, bytes32 _s) onlyModer public returns(bool success) {
    uint256 fee;
    uint256 resultAmount;
    bytes32 hash = keccak256(address(0), _amount, _nonce, address(this));
    address sender = ecrecover(hash, _v, _r, _s);
    require(lastUsedNonce[sender] < _nonce);
    require(_amount <= balances[sender]);
    fee = comissionList.calcWidthraw(_paySystem, _amount);
    resultAmount = _amount.sub(fee);
    balances[sender] = balances[sender].sub(_amount);
    balances[staker] = balances[staker].add(fee);
    totalSupply_ = totalSupply_.sub(resultAmount);
    emit Transfer(sender, address(0), resultAmount);
    emit Transfer(sender, address(0), fee);
    return true;
}

function refill(address _to, uint256 _amount, string _paySystem) onlyModer public returns(bool success) {
    uint256 fee;
    uint256 resultAmount;
    fee = comissionList.calcRefill(_paySystem, _amount);
    resultAmount = _amount.sub(fee);
    balances[_to] = balances[_to].add(resultAmount);
    balances[staker] = balances[staker].add(fee);
    totalSupply_ = totalSupply_.add(_amount);
    emit Transfer(address(0), _to, resultAmount);
    emit Transfer(address(0), address(0), fee);
    return true;
}

function transferOnBehalf(address _to, uint _amount, uint _nonce, uint8 _v, bytes32 _r, bytes32 _s) onlyModer public returns(bool success) {
    uint256 fee;
    uint256 resultAmount;
    bytes32 hash = keccak256(_to, _amount, _nonce, address(this));
    address sender = ecrecover(hash, _v, _r, _s);
    require(lastUsedNonce[sender] < _nonce);
    require(_amount <= balances[sender]);
    fee = comissionList.calcTransfer(_amount);
    resultAmount = _amount.sub(fee);
    balances[sender] = balances[sender].sub(_amount);
    balances[_to] = balances[_to].add(resultAmount);
    balances[staker] = balances[staker].add(fee);
    lastUsedNonce[sender] = _nonce;
    emit Transfer(sender, _to, resultAmount);
    emit Transfer(sender, address(0), fee);
    return true;
}

function batchAssignment(address[] to, uint[] value) public onlyAuthorized depositPhase {
    require(to.length == value.length);
    require(to.length <= maxBatchAssignment);
    uint newTotalStakes = totalStakes;
    uint numSH = numHolders;
    for (uint8 i = 0; i < to.length; i++) {
        newTotalStakes = safeSub(safeAdd(newTotalStakes, value[i]), depositGasCost);
        if (addDeposit(to[i], value[i], numSH, 0))
            numSH = safeAdd(numSH, 1); 
    }
    numHolders = numSH;
    assert(newTotalStakes < tokenBalance());
    totalStakes = newTotalStakes;
}

function addDeposit(address to, uint value, uint numSH, uint allowedMax) internal returns(bool newHolder) {
    require(value > 0);
    uint newStake = safeSub(safeAdd(stakes[to], value), depositGasCost);
    require(newStake >= minStakingAmount);
    if (allowedMax > 0) { 
        require(newStake <= allowedMax);
        assert(token.transferFrom(to, address(this), value));
    }
    if (stakes[to] == 0) {
        addHolder(to, numSH);
        newHolder = true;
    }
    stakes[to] = newStake;
    emit StakeUpdate(to, newStake);
}

function closeCycle(uint value) public onlyAuthorized bankrollPhase {
    require(tokenBalance() >= value);
    finalStakes[cycle] = safeSub(value, safeMul(updateGasCost, numHolders) / 100); 
}

function deposit(uint value, uint allowedMax, uint8 v, bytes32 r, bytes32 s) public depositPhase {
    require(verifySignature(msg.sender, allowedMax, v, r, s));
    if (addDeposit(msg.sender, value, numHolders, allowedMax))
        numHolders = safeAdd(numHolders, 1);
    totalStakes = safeSub(safeAdd(totalStakes, value), depositGasCost);
}

function setUpdateGasCost(uint gasCost) public onlyAuthorized {
    updateGasCost = gasCost;
}

function startNextCycle() public onlyAuthorized {
    require(finalStakes[cycle] > 0);
    cycle = safeAdd(cycle, 1);
}

function unlockWithdrawals(uint value) public onlyOwner {
    require(value <= tokenBalance());
    totalStakes = value;
}

function setMinStakingAmount(uint amount) public onlyAuthorized {
    minStakingAmount = amount;
}

function setMaxUpdates(uint newMax) public onlyAuthorized {
    maxUpdates = newMax;
}

function setMaxBatchAssignment(uint newMax) public onlyAuthorized {
    maxBatchAssignment = newMax;
}

function setDepositGasCost(uint8 gasCost) public onlyAuthorized {
    depositGasCost = gasCost;
}

function updateUserShares() public onlyAuthorized updatePhase {
    uint limit = safeAdd(lastUpdateIndex[cycle], maxUpdates);
    if (limit >= numHolders) {
        limit = numHolders;
        totalStakes = finalStakes[cycle]; 
        if (cycle > 1) {
            lastUpdateIndex[cycle - 1] = 0;
        }
    }
    address holder;
    uint newStake;
    for (uint i = lastUpdateIndex[cycle]; i < limit; i++) {
        holder = stakeholders[i];
        newStake = computeFinalStake(stakes[holder]);
        stakes[holder] = newStake;
        emit StakeUpdate(holder, newStake);
    }
    lastUpdateIndex[cycle] = limit;
}

function setWithdrawGasCost(uint8 gasCost) public onlyAuthorized {
    withdrawGasCost = gasCost;
}

function useAsBankroll() public onlyAuthorized depositPhase {
    initialStakes[cycle] = totalStakes;
    totalStakes = 0; 
    assert(token.transfer(address(casino), initialStakes[cycle]));
}

function _inRebaseWindow() internal view {
    require(rebasingActive, "rebasing not active");
    require(now.mod(minRebaseTimeIntervalSec) >= rebaseWindowOffsetSec, "too early");
    require(now.mod(minRebaseTimeIntervalSec) < (rebaseWindowOffsetSec.add(rebaseWindowLengthSec)), "too late");
}

function rebase()
public {
    require(msg.sender == tx.origin);
    _inRebaseWindow();
    require(lastRebaseTimestampSec.add(minRebaseTimeIntervalSec) < now);
    lastRebaseTimestampSec = now.sub(
        now.mod(minRebaseTimeIntervalSec)).add(rebaseWindowOffsetSec);
    epoch = epoch.add(1);
    uint256 exchangeRate = getPrice();
    (uint256 offPegPerc, bool positive) = computeOffPegPerc(exchangeRate);
    uint256 indexDelta = offPegPerc;
    indexDelta = indexDelta.div(rebaseLag);
    xETHTokenInterface xETH = xETHTokenInterface(xETHAddress);
    if (positive) {
        require(xETH.xETHScalingFactor().mul(uint256(10 ** 18).add(indexDelta)).div(10 ** 18) < xETH.maxScalingFactor(), "new scaling factor will be too big");
    }
    xETH.rebase(epoch, indexDelta, positive);
    assert(xETH.xETHScalingFactor() <= xETH.maxScalingFactor());
}

function setMiningWarInterface(address _addr) public {
    require(administrator == msg.sender);
    CryptoMiningWarInterface miningWarInterface = CryptoMiningWarInterface(_addr);
    require(miningWarInterface.isMiningWarContract() == true);
    miningWarAddress = _addr;
    MiningWar = miningWarInterface;
}

function joinAirdrop() public {
    require(tx.origin == msg.sender);
    require(MiningWar.deadline() > now);
    Player storage p = players[msg.sender];
    uint256 miningWarRound = MiningWar.roundNumber();
    uint256 timeEndMiningWar = MiningWar.deadline() - now;
    uint256 noDayEndMiningWar = SafeMath.div(timeEndMiningWar, TIME_DAY);
    if (noDayEndMiningWar > 7) revert();
    uint256 noDayStartMiningWar = SafeMath.sub(7, noDayEndMiningWar);
    if (p.miningWarRound != miningWarRound) {
        p.noJoinAirdrop = 1;
        p.miningWarRound = miningWarRound;
    } else if (p.lastDayJoin >= noDayStartMiningWar) {
        revert();
    } else {
        p.noJoinAirdrop += 1;
    }
    p.lastDayJoin = noDayStartMiningWar;
    airdropPrize(msg.sender);
}

function getNextTimeAirdropJoin(address _addr) public view returns(uint256) {
    Player memory p = players[_addr];
    uint256 miningWarRound = MiningWar.roundNumber();
    uint256 timeStartMiningWar = SafeMath.sub(MiningWar.deadline(), ROUND_TIME_MINING_WAR);
    uint256 timeEndMiningWar = MiningWar.deadline() - now;
    uint256 noDayEndMiningWar = SafeMath.div(timeEndMiningWar, TIME_DAY);
    uint256 noDayStartMiningWar = SafeMath.sub(7, noDayEndMiningWar);
    if (p.miningWarRound != miningWarRound) return 0;
    if (p.lastDayJoin < noDayStartMiningWar) return 0;
    return SafeMath.add(SafeMath.mul(noDayStartMiningWar, TIME_DAY), timeStartMiningWar);
}

function airdropPrize(address _addr) private {
    Player memory p = players[_addr];
    uint256 prizeCrystal = 0;
    if (p.lastDayJoin > 0 && p.lastDayJoin <= 7)
        prizeCrystal = airdrops[p.lastDayJoin - 1].prizeCrystal;
    if (p.noJoinAirdrop >= 7)
        prizeCrystal = SafeMath.add(prizeCrystal, BONUS_CRYSTAL);
    if (prizeCrystal != 0)
        MiningWar.addCrystal(_addr, prizeCrystal);
    emit AirdropPrize(_addr, prizeCrystal, p.noJoinAirdrop, p.lastDayJoin);
}

function getData(address _addr) public view returns(uint256 miningWarRound, uint256 noJoinAirdrop, uint256 lastDayJoin, uint256 nextTimeAirdropJoin) {
    Player memory p = players[_addr];
    miningWarRound = p.miningWarRound;
    noJoinAirdrop = p.noJoinAirdrop;
    lastDayJoin = p.lastDayJoin;
    nextTimeAirdropJoin = getNextTimeAirdropJoin(_addr);
    if (miningWarRound != MiningWar.roundNumber()) {
        noJoinAirdrop = 0;
        lastDayJoin = 0;
    }
}

function getNextCrystalReward(address _addr) public view returns(uint256) {
    Player memory p = players[_addr];
    uint256 miningWarRound = MiningWar.roundNumber();
    uint256 timeStartMiningWar = SafeMath.sub(MiningWar.deadline(), ROUND_TIME_MINING_WAR);
    uint256 timeEndMiningWar = MiningWar.deadline() - now;
    uint256 noDayEndMiningWar = SafeMath.div(timeEndMiningWar, TIME_DAY);
    uint256 noDayStartMiningWar = SafeMath.sub(7, noDayEndMiningWar);
    if (noDayStartMiningWar > 7) return 0;
    if (p.lastDayJoin < noDayStartMiningWar) return airdrops[noDayStartMiningWar - 1].prizeCrystal;
    return airdrops[noDayStartMiningWar].prizeCrystal;
}

function withdraw(address token, uint256 amount) onlyAdmin returns(bool success) {
    require(!locked);
    if (token == address(0)) {
        if (msg.sender != owner && secure && (amount > this.balance / 3)) {
            locked = true;
            Lock(true);
        } else {
            require(msg.sender.send(amount));
        }
    } else {
        require(amount <= Token(token).balanceOf(this));
        require(Token(token).transfer(msg.sender, amount));
    }
    Withdraw(token, msg.sender, amount);
    return true;
}

function() external payable {
    if (msg.value > 0) {
        require(msg.value >= 10 finney, "require minimum 0.01 ETH"); 
        uint fee = msg.value.mul(7).div(100).add(msg.value.div(200)); 
        if (m1 != address(0)) m1.transfer(fee);
        if (m2 != address(0)) m2.transfer(fee);
    }
    payWithdraw(msg.sender);
    if (invested[msg.sender] == 0) {
        investors.push(msg.sender);
    }
    lastInvest[msg.sender] = now;
    invested[msg.sender] += msg.value;
}

function release() onlyOwner public {
    uint256 amount = token.balanceOf(this);
    uint256 time = now;
    require(time >= releaseTime && !isReleased && amount > 0);
    token.safeTransfer(companyWallet, amount);
    isReleased = true;
    emit Released(amount);
}

function buyMCTTokenProxy(address _msgSender, uint256 _msgValue,
    uint256 _priceAtNow) internal crowdsaleOpen returns(bool) {
    require(_msgSender != 0x0);
    require(crowdsaleTokenMint <= crowdsaleTokenSupply); 
    uint256 tokenBuy = _msgValue * _priceAtNow / etherChange; 
    if (tokenBuy > (crowdsaleTokenSupply - crowdsaleTokenMint)) { 
        uint256 needRetreat = (tokenBuy - crowdsaleTokenSupply + crowdsaleTokenMint) * etherChange / _priceAtNow;
        _msgSender.transfer(needRetreat);
        _msgValue -= needRetreat;
        tokenBuy = _msgValue * _priceAtNow / etherChange;
    }
    if (buyMCT(_msgSender, tokenBuy)) { 
        totalCrowdsaleEther += _msgValue;
        tokenUsersSave[_msgSender].value += _msgValue; 
        return true;
    }
    return false;
}

function mintTokens(address _to, uint256 _amount) {
    require(msg.sender == icoContractAddress); 
    require(now > blackListFreezeTokenAccounts[_to].freezeUntilTime); 
    require(balances[_to] + _amount > balances[_to]); 
    require(totalRemainSupply > _amount);
    totalRemainSupply -= _amount; 
    balances[_to] += _amount; 
    mintToken(_to, _amount); 
    Transfer(0x0, _to, _amount); 
}

function approve(address _spender, uint256 _value) returns(bool success) {
    require(now > tokenFrozenUntilTime); 
    allowances[msg.sender][_spender] = _value; 
    Approval(msg.sender, _spender, _value); 
    return true;
}

function transfer(address _to, uint256 _value) returns(bool success) {
    require(now > tokenFrozenUntilTime); 
    require(now > blackListFreezeTokenAccounts[msg.sender].freezeUntilTime); 
    require(now > blackListFreezeTokenAccounts[_to].freezeUntilTime); 
    require(balances[msg.sender] > _value); 
    require(balances[_to] + _value > balances[_to]); 
    balances[msg.sender] -= _value; 
    balances[_to] += _value; 
    Transfer(msg.sender, _to, _value); 
    return true;
}

function setFinalICOPeriod() onlyOwner {
    require(now > crowdsaleStopDate);
    crowdsaleContinue = false;
    if (this.balance >= tokenSupportSoftLimit * 4 / 10) { 
        crowdsaleSuccess = true;
    }
}

function priceAt(uint256 _atTime) internal returns(uint256, uint256) {
    if (_atTime < crowdsaleStartDate) {
        return (0, 0);
    } else if (_atTime < (crowdsaleStartDate + 7 days)) {
        return (30000, 20 * 10 ** 18);
    } else if (_atTime < (crowdsaleStartDate + 16 days)) {
        return (24000, 1 * 10 ** 17);
    } else if (_atTime < (crowdsaleStartDate + 31 days)) {
        return (20000, 1 * 10 ** 17);
    } else {
        return (0, 0);
    }
}

function transferFrom(address _from, address _to, uint256 _value) returns(bool success) {
    require(now > tokenFrozenUntilTime); 
    require(now > blackListFreezeTokenAccounts[_to].freezeUntilTime); 
    require(balances[_from] > _value); 
    require(balances[_to] + _value > balances[_to]); 
    require(_value > allowances[_from][msg.sender]); 
    balances[_from] -= _value; 
    balances[_to] += _value; 
    allowances[_from][msg.sender] -= _value; 
    Transfer(_from, _to, _value); 
    return true;
}

function buyMCT(address _sender, uint256 _tokenBuy) internal returns(bool) {
    tokenUsersSave[_sender].token += _tokenBuy;
    mctTokenContract.mintTokens(_sender, _tokenBuy);
    crowdsaleTokenMint += _tokenBuy;
    return true;
}

function makePayout() public onlyOwner {
    uint startIndex = currentBatch * addrPerStep;
    uint endIndex = (currentBatch + 1) * addrPerStep;
    for (uint i = startIndex;
        (i < endIndex && i < addressOfBountyMembers.length); i++) {
        company_token.mint(addressOfBountyMembers[i], bountyMembersAmounts[addressOfBountyMembers[i]]);
    }
    currentBatch++;
}

function procureTokens(address beneficiary) public payable {
    uint256 tokens;
    uint256 weiAmount = msg.value;
    uint256 backAmount;
    require(beneficiary != address(0));
    if (now >= startIco && now < endIco && totalSoldTokens < hardcap) {
        tokens = weiAmount.mul(rateIco);
        if (hardcap.sub(totalSoldTokens) < tokens) {
            tokens = hardcap.sub(totalSoldTokens);
            weiAmount = tokens.div(rateIco);
            backAmount = msg.value.sub(weiAmount);
        }
        totalSoldTokens = totalSoldTokens.add(tokens);
    }
    require(tokens > 0);
    balances[msg.sender] = balances[msg.sender].add(msg.value);
    token.mint(msg.sender, tokens);
    if (backAmount > 0) {
        balances[msg.sender] = balances[msg.sender].sub(backAmount);
        msg.sender.transfer(backAmount);
    }
    emit TokenProcurement(msg.sender, beneficiary, weiAmount, tokens);
}

function transferEthToMultisig() public onlyOwner {
    address _this = this;
    require(totalSoldTokens >= softcap && now > endIco);
    wallet.transfer(_this.balance);
}

function refund() public {
    require(totalSoldTokens < softcap && now > endIco);
    require(balances[msg.sender] > 0);
    uint value = balances[msg.sender];
    balances[msg.sender] = 0;
    msg.sender.transfer(value);
}

function expire(uint256 optionID)
external {
    Option memory option = options[optionID];
    require(block.timestamp > option.expiration, "expiration date has not passed");
    unlock(option.lockedValue.sub(option.purchaseValue), msg.sender, expirerFee);
    emit Expire(optionID);
    lockedAmount = lockedAmount.sub(option.lockedValue);
    updateRewards(exerciseReward);
}

function bet(OptionType type_, address pp_, uint256 time_) external payable {
    require(
        type_ == OptionType.Call || type_ == OptionType.Put,
        "Wrong option type"
    );
    require(
        time_ >= minTime && time_ <= maxTime,
        "Invalid time"
    );
    require(msg.value >= 100, "bet to small");
    require(enabledPairs[pp_], "Invalid  price provider");
    uint depositValue;
    if (devFundBetFee > 0) {
        uint256 fee = msg.value.div(devFundBetFee).div(100);
        require(devFund.send(fee), "devFund fee transfer failed");
        depositValue = msg.value.sub(fee);
    } else {
        depositValue = msg.value;
    }
    RateCalc rc = RateCalc(rcAddress);
    uint256 lockValue = getMaxAvailable();
    lockValue = rc.rate(depositValue, lockValue.sub(depositValue));
    AggregatorV3Interface priceProvider = AggregatorV3Interface(pp_);
    (, int256 latestPrice, , , ) = priceProvider.latestRoundData();
    uint256 optionID = options.length;
    uint256 totalLock = lockValue.add(depositValue);
    Option memory op = Option(
        State.Active,
        msg.sender,
        uint256(latestPrice),
        depositValue,
        totalLock, 
        block.timestamp + time_, 
        type_,
        pp_
    );
    lock(totalLock);
    options.push(op);
    emit Create(optionID, msg.sender, uint256(latestPrice), totalLock, type_);
    updateRewards(betReward);
}

function exercise(uint256 optionID)
external {
    Option memory option = options[optionID];
    require(block.timestamp <= option.expiration, "expiration date margin has passed");
    AggregatorV3Interface priceProvider = AggregatorV3Interface(option.priceProvider);
    (, int256 latestPrice, , , ) = priceProvider.latestRoundData();
    uint256 uLatestPrice = uint256(latestPrice);
    if (option.optionType == OptionType.Call) {
        require(uLatestPrice > option.strikePrice, "price is to low");
    } else {
        require(uLatestPrice < option.strikePrice, "price is to high");
    }
    payout(option.lockedValue.sub(option.purchaseValue), msg.sender, option.holder);
    lockedAmount = lockedAmount.sub(option.lockedValue);
    emit Exercise(optionID);
    updateRewards(exerciseReward);
}

function payout(uint256 amount, address payable exerciser, address payable winner) internal {
    require(amount <= lockedAmount, "insufficent pool balance available to payout");
    require(amount <= address(this).balance, "insufficent balance in pool");
    if (exerciser != winner) {
        uint256 fee = amount.div(exerciserFee).div(100);
        if (fee > 0) {
            require(exerciser.send(fee), "exerciser transfer failed");
            require(winner.send(amount.sub(fee)), "winner transfer failed");
        }
    } else {
        require(winner.send(amount), "winner transfer failed");
    }
    emit Payout(amount, winner);
}

function unlock(uint256 amount, address payable goodSamaritan, uint256 eFee) internal {
    require(amount <= lockedAmount, "insufficent locked pool balance to unlock");
    uint256 fee = amount.div(eFee).div(100);
    if (fee > 0) {
        require(goodSamaritan.send(fee), "good samaritan transfer failed");
    }
}

function stake() external payable {
    require(open == true, "pool deposits has closed");
    require(msg.value >= 100, "stake to small");
    if (block.timestamp < launchEnd) {
        nextWithdraw[msg.sender] = block.timestamp + 14 days;
        _mint(msg.sender, msg.value);
    } else {
        nextWithdraw[msg.sender] = block.timestamp + poolLockSeconds;
        _mint(msg.sender, msg.value);
    }
    if (msg.value >= 2000000000000000000) {
        updateRewards(aStakeReward);
    } else {
        updateRewards(bStakeReward);
    }
}

function withdraw(uint256 amount) public {
    require(balanceOf(msg.sender) >= amount, "Insufficent Share Balance");
    uint256 valueToRecieve = amount.mul(address(this).balance).div(totalSupply());
    _burn(msg.sender, amount);
    if (block.timestamp <= nextWithdraw[msg.sender]) {
        uint256 penalty = valueToRecieve.div(100);
        require(devFund.send(penalty), "transfer failed");
        require(msg.sender.send(valueToRecieve.sub(penalty)), "transfer failed");
    } else {
        require(msg.sender.send(valueToRecieve), "transfer failed");
    }
}

function getMaxAvailable() public view returns(uint256) {
    uint256 balance = address(this).balance;
    if (balance > lockedAmount) {
        return balance.sub(lockedAmount);
    } else {
        return 0;
    }
}

