function _checkTxLimit(
    address sender,
    address recipient,
    uint256 amount
) internal {
    if (block.timestamp - lastSapphireChange > resetPeriod) {
        _resetSapphire();
    }
    if (block.timestamp - lastRubyChange > resetPeriod) {
        _resetRuby();
    }
    if (block.timestamp - lastEmeraldChange > resetPeriod) {
        _resetEmerald();
    }
    if (
        sender != owner &&
        recipient != owner &&
        !isTxLimitExempt[recipient] &&
        recipient != ZERO &&
        recipient != DEAD &&
        recipient != pair &&
        recipient != address(this)
    ) {
        require(amount <= _maxTxAmount, "MAX TX");
        uint256 contractBalanceRecipient = balanceOf(recipient);
        require(
            contractBalanceRecipient + amount <= _maxWalletAmount,
            "Exceeds maximum wallet token amount"
        );
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(this);
        uint256 usedEth = router.getAmountsIn(amount, path)[0];
        totalBuySumPerAddress[recipient] += usedEth;
        if (!hasSold[recipient]) {
            if (totalBuySumPerAddress[recipient] > biggestBuySum) {
                biggestBuySum = totalBuySumPerAddress[recipient];
                lastSapphireChange = block.timestamp;
                if (Sapphire != recipient) {
                    Sapphire = recipient;
                    emit NewSapphire(Sapphire, biggestBuySum);
                }
            }
            if (usedEth > biggestBuy) {
                biggestBuy = usedEth;
                lastRubyChange = block.timestamp;
                if (Ruby != recipient) {
                    Ruby = recipient;
                    emit NewRuby(Ruby, biggestBuy);
                }
            }
            if (usedEth < lowestBuy) {
                lowestBuy = usedEth;
                lastEmeraldChange = block.timestamp;
                if (Emerald != recipient) {
                    Emerald = recipient;
                    emit NewEmerald(Emerald, lowestBuy);
                }
            }
        }
    }
    if (
        sender != owner &&
        recipient != owner &&
        !isTxLimitExempt[sender] &&
        sender != pair &&
        recipient != address(this)
    ) {
        require(amount <= _maxTxAmount, "MAX TX");
        if (Sapphire == sender) {
            emit SapphireSold(Sapphire, biggestBuySum);
            _resetSapphire();
            hasSold[sender] = true;
        }
        if (Ruby == sender) {
            emit RubySold(Ruby, biggestBuy);
            _resetRuby();
            hasSold[sender] = true;
        }
        if (Emerald == sender) {
            emit EmeraldSold(Emerald, lowestBuy);
            _resetEmerald();
            hasSold[sender] = true;
        }
    }
}

function _transferFrom(
    address sender,
    address recipient,
    uint256 amount
) internal returns(bool) {
    if (inSwapAndLiquify) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (sniiperProtection) {
        if (!_hasLiqBeenAdded) {
            _checkLiquidityAdd(sender, recipient);
        } else {
            if (
                _liqAddBlock > 0 &&
                sender == pair &&
                !_liquidityHolders[sender] &&
                !_liquidityHolders[recipient]
            ) {
                if (block.number - _liqAddBlock < 2) {
                    if (!_isSniiper[recipient]) {
                        _sniipers.push(recipient);
                    }
                    _isSniiper[recipient] = true;
                }
            }
        }
    }
    if (
        msg.sender != pair &&
        !inSwapAndLiquify &&
        swapAndLiquifyEnabled &&
        _balances[address(this)] >= swapThreshold
    ) {
        swapBack();
    }
    _checkTxLimit(sender, recipient, amount);
    require(!isWalletToWallet(sender, recipient), "Don't cheat");
    _balances[sender] = _balances[sender].sub(
        amount,
        "Insufficient Balance"
    );
    uint256 amountReceived = !isFeeExempt[sender] && !isFeeExempt[recipient] ?
        takeFee(sender, recipient, amount) :
        amount;
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(msg.sender, recipient, amountReceived);
    return true;
}

function swapBack() internal lockTheSwap {
    uint256 tokensToLiquify = swapThreshold;
    uint256 amountToSwap = tokensToLiquify;
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = router.WETH();
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        amountToSwap,
        0,
        path,
        address(this),
        block.timestamp
    );
    uint256 amountETH = address(this).balance;
    uint256 amountETHMarketing = amountETH.mul(marketingFee).div(totalFee);
    uint256 amountETHSapphire = amountETH.mul(sapphireFee).div(totalFee);
    uint256 amountETHRuby = amountETH.mul(rubyFee).div(totalFee);
    uint256 amountETHEmerald = amountETH.mul(emeraldFee).div(totalFee);
    (bool tmpSuccess, ) = payable(marketingWallet).call {
        value: amountETHMarketing,
        gas: 30000
    }("");
    (bool tmpSuccess2, ) = payable(Sapphire).call {
        value: amountETHSapphire,
        gas: 30000
    }("");
    if (totalRewardsPerAddress[Sapphire] == 0) {
        rewardedAddresses.push(Sapphire);
    }
    totalRewardsPerAddress[Sapphire] += amountETHSapphire;
    emit SapphirePayout(Sapphire, amountETHSapphire);
    (bool tmpSuccess3, ) = payable(Ruby).call {
        value: amountETHRuby,
        gas: 30000
    }("");
    if (totalRewardsPerAddress[Ruby] == 0) {
        rewardedAddresses.push(Ruby);
    }
    totalRewardsPerAddress[Ruby] += amountETHRuby;
    emit RubyPayout(Ruby, amountETHRuby);
    (bool tmpSuccess4, ) = payable(Emerald).call {
        value: amountETHEmerald,
        gas: 30000
    }("");
    if (totalRewardsPerAddress[Emerald] == 0) {
        rewardedAddresses.push(Emerald);
    }
    totalRewardsPerAddress[Emerald] += amountETHEmerald;
    emit EmeraldPayout(Emerald, amountETHEmerald);
    tmpSuccess = false;
    tmpSuccess2 = false;
    tmpSuccess3 = false;
    tmpSuccess4 = false;
}

function averagePrice() external onlyTautrino returns(uint32) {
    require(providers.length > 0, "No providers");
    delete lastPrices;
    uint _priceSum = 0;
    uint _xSum = 0;
    for (uint i = 0; i < providers.length; i++) {
        if (providers[i].updateRequred()) {
            providers[i].update();
        }
        uint32 _price = providers[i].lastPrice();
        uint _x = uint(keccak256(abi.encodePacked(_price, block.coinbase, block.timestamp, block.difficulty, blockhash(block.number)))).mod(uint(primeNumbers[i])).add(1);
        lastPrices.push(Price({
            provider: providers[i].providerName(),
            timestamp: uint64(block.timestamp),
            price: _price,
            x: uint32(_x)
        }));
        _priceSum = _priceSum.add(uint(_price).mul(_x));
        _xSum = _xSum.add(_x);
    }
    require(_priceSum > 0, "Price is not updated yet");
    lastAvgPrice = uint32(_priceSum.div(_xSum));
    return lastAvgPrice;
}

function addProvider(address _provider) external onlyOwner {
    IPriceProvider _newProvider = IPriceProvider(_provider);
    if (_newProvider.updateRequred()) {
        _newProvider.update();
    }
    providers.push(_newProvider);
}

function diemlibreFaucet(address _faucetAddress) external returns(bool) {
    require(sentAddresses[_faucetAddress] == false, "Error 501: Address has already been fauced with DLB.");
    require(currentState.isInit, "Error 500: Contract Not Initialized or Contract Turned Off.");
    uint256 tokenAllowance = DLB.allowance(currentState.holder, currentState.self);
    require(currentState.faucetAmount > 0 && currentState.faucetAmount <= tokenAllowance, "Error 502: Insufficient Liquidity");
    require(DLB.transferFrom(currentState.holder, _faucetAddress, currentState.faucetAmount), "Error 503: Oops... Could not complete Transaction. Please try again later.");
    sentAddresses[_faucetAddress] = true;
    savedAddresses.push(_faucetAddress);
    return true;
}

function revoke(uint256 _id) public {
    require(msg.sender == orderBook[_id].owner);
    require(orderBook[_id].endTime <= now);
    Issuer issuer = Issuer(orderBook[_id].issuer);
    issuer.transfer(msg.sender, orderBook[_id].tokenId);
    orderBook[_id] = orderBook[orderBookSize - 1];
    orderBookSize -= 1;
}

function buy(uint256 _id) public payable {
    require(msg.value >= orderBook[_id].price);
    require(msg.sender != orderBook[_id].owner);
    require(!isContract(msg.sender));
    require(orderBook[_id].startTime <= now && now <= orderBook[_id].endTime);
    orderBook[_id].owner.transfer(orderBook[_id].price * 24 / 25); 
    orderBook[_id].creator.transfer(orderBook[_id].price / 50); 
    if (msg.value > orderBook[_id].price) {
        msg.sender.transfer(msg.value - orderBook[_id].price);
    }
    orderBook[_id].owner = msg.sender;
    orderBook[_id].price = getNextPrice(orderBook[_id].price);
}

function put(address _issuer, uint256 _tokenId, uint256 _price,
    uint256 _startTime, uint256 _endTime) public {
    require(_startTime <= _endTime);
    Issuer issuer = Issuer(_issuer);
    require(issuer.ownerOf(_tokenId) == msg.sender);
    issuer.transferFrom(msg.sender, address(this), _tokenId);
    if (orderBookSize == orderBook.length) {
        orderBook.push(Order(msg.sender, msg.sender, _issuer, _tokenId, _price, _startTime, _endTime));
    } else {
        orderBook[orderBookSize] = Order(msg.sender, msg.sender, _issuer, _tokenId, _price, _startTime, _endTime);
    }
    orderBookSize += 1;
}

function bountyFunds(address[] beneficiary, uint256[] tokens) public onlyOwner {
    for (uint256 i = 0; i < beneficiary.length; i++) {
        tokens[i] = SafeMath.mul(tokens[i], 1 ether);
        require(beneficiary[i] != 0x0);
        require(bountySupply >= tokens[i]);
        bountySupply = SafeMath.sub(bountySupply, tokens[i]);
        token.mint(beneficiary[i], tokens[i]);
    }
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = now >= privateSaleStartTime && now <= ICOEndTime;
    bool nonZeroPurchase = msg.value != 0;
    return withinPeriod && nonZeroPurchase;
}

function icoTokens(uint256 weiAmount, uint256 tokens, uint256 accessTime) internal returns(uint256) {
    require(icoSupply > 0);
    if (!upgradeICOSupply) {
        icoSupply = SafeMath.add(icoSupply, preICOSupply);
        upgradeICOSupply = true;
    }
    if (accessTime <= weekOne) {
        tokens = SafeMath.add(tokens, weiAmount.mul(firstWeekBonus));
    } else if (accessTime <= weekTwo) {
        tokens = SafeMath.add(tokens, weiAmount.mul(secondWeekBonus));
    } else if (accessTime < weekThree) {
        tokens = SafeMath.add(tokens, weiAmount.mul(thirdWeekBonus));
    } else if (accessTime < weekFour) {
        tokens = SafeMath.add(tokens, weiAmount.mul(forthWeekBonus));
    } else if (accessTime < weekFive) {
        tokens = SafeMath.add(tokens, weiAmount.mul(fifthWeekBonus));
    }
    tokens = SafeMath.add(tokens, weiAmount.mul(rate));
    icoSupply = icoSupply.sub(tokens);
    return tokens;
}

function buyTokens(address beneficiary) whenNotPaused internal {
    require(beneficiary != 0x0);
    require(validPurchase());
    uint256 accessTime = now;
    uint256 tokens = 0;
    uint256 weiAmount = msg.value;
    require((weiAmount >= (100000000000000000)) && (weiAmount <= (20000000000000000000)));
    if ((accessTime >= privateSaleStartTime) && (accessTime < privateSaleEndTime)) {
        tokens = privateSaleTokens(weiAmount, tokens);
    } else if ((accessTime >= preSaleStartTime) && (accessTime < preSaleEndTime)) {
        tokens = preSaleTokens(weiAmount, tokens);
    } else if ((accessTime >= preICOStartTime) && (accessTime < preICOEndTime)) {
        tokens = preICOTokens(weiAmount, tokens);
    } else if ((accessTime >= ICOstartTime) && (accessTime <= ICOEndTime)) {
        tokens = icoTokens(weiAmount, tokens, accessTime);
    } else {
        revert();
    }
    publicSupply = publicSupply.sub(tokens);
    weiRaised = weiRaised.add(weiAmount);
    token.mint(beneficiary, tokens);
    emit TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function hasEnded() public view returns(bool) {
    return super.hasEnded() || weiRaised >= cap;
}

function tallyVotes(TellorStorage.TellorStorageStruct storage self, uint256 _disputeId) public {
    TellorStorage.Dispute storage disp = self.disputesById[_disputeId];
    require(disp.executed == false, "Dispute has been already executed");
    require(now >= disp.disputeUintVars[keccak256("minExecutionDate")], "Time for voting haven't elapsed");
    require(disp.reportingParty != address(0), "reporting Party is address 0");
    int256 _tally = disp.tally;
    if (_tally > 0) {
        disp.disputeVotePassed = true;
    }
    if (disp.isPropFork == false) {
        TellorStorage.StakeInfo storage stakes = self.stakerDetails[disp.reportedMiner];
        if (stakes.currentStatus == 3) {
            stakes.currentStatus = 4;
        }
    } else if (uint(_tally) >= ((self.uintVars[keccak256("total_supply")] * 10) / 100)) {
        emit NewTellorAddress(disp.proposedForkAddress);
    }
    disp.disputeUintVars[keccak256("tallyDate")] = now;
    disp.executed = true;
    emit DisputeVoteTallied(_disputeId, _tally, disp.reportedMiner, disp.reportingParty, disp.disputeVotePassed);
}

function newBlock(TellorStorage.TellorStorageStruct storage self, string memory _nonce, uint256[5] memory _requestId) public {
    TellorStorage.Request storage _tblock = self.requestDetails[self.uintVars[_tBlock]];
    int256 _change = int256(SafeMath.min(1200, (now - self.uintVars[timeOfLastNewValue])));
    int256 _diff = int256(self.uintVars[difficulty]);
    _change = (_diff * (int256(self.uintVars[timeTarget]) - _change)) / 4000;
    if (_change == 0) {
        _change = 1;
    }
    self.uintVars[difficulty] = uint256(SafeMath.max(_diff + _change, 1));
    bytes32 _currChallenge = self.currentChallenge;
    uint256 _timeOfLastNewValue = now - (now % 1 minutes);
    self.uintVars[timeOfLastNewValue] = _timeOfLastNewValue;
    uint[5] memory a;
    for (uint k = 0; k < 5; k++) {
        for (uint i = 1; i < 5; i++) {
            uint256 temp = _tblock.valuesByTimestamp[k][i];
            address temp2 = _tblock.minersByValue[k][i];
            uint256 j = i;
            while (j > 0 && temp < _tblock.valuesByTimestamp[k][j - 1]) {
                _tblock.valuesByTimestamp[k][j] = _tblock.valuesByTimestamp[k][j - 1];
                _tblock.minersByValue[k][j] = _tblock.minersByValue[k][j - 1];
                j--;
            }
            if (j < i) {
                _tblock.valuesByTimestamp[k][j] = temp;
                _tblock.minersByValue[k][j] = temp2;
            }
        }
        TellorStorage.Request storage _request = self.requestDetails[_requestId[k]];
        a = _tblock.valuesByTimestamp[k];
        _request.finalValues[_timeOfLastNewValue] = a[2];
        _request.minersByValue[_timeOfLastNewValue] = _tblock.minersByValue[k];
        _request.valuesByTimestamp[_timeOfLastNewValue] = _tblock.valuesByTimestamp[k];
        delete _tblock.minersByValue[k];
        delete _tblock.valuesByTimestamp[k];
        _request.requestTimestamps.push(_timeOfLastNewValue);
        _request.minedBlockNum[_timeOfLastNewValue] = block.number;
        _request.apiUintVars[totalTip] = 0;
    }
    emit NewValue(
        _requestId,
        _timeOfLastNewValue,
        a,
        self.uintVars[runningTips],
        _currChallenge
    );
    self.requestIdByTimestamp[_timeOfLastNewValue] = _requestId[0];
    self.newValueTimestamps.push(_timeOfLastNewValue);
    uint _currReward = self.uintVars[currentReward];
    _timeOfLastNewValue = _currReward;
    if (_currReward > 1e18) {
        _currReward = _currReward - _currReward * 15306316590563 / 1e18;
        self.uintVars[devShare] = _currReward * 50 / 100;
        _timeOfLastNewValue = _currReward;
    } else {
        _timeOfLastNewValue = 1e18;
    }
    self.uintVars[currentReward] = _timeOfLastNewValue;
    _currReward = _timeOfLastNewValue;
    uint _devShare = self.uintVars[devShare];
    self.uintVars[total_supply] += _devShare + _currReward * 5 - (self.uintVars[currentTotalTips]);
    TellorTransfer.doTransfer(self, address(this), self.addressVars[_owner], _devShare);
    self.uintVars[_tBlock]++;
    uint256[5] memory _topId = TellorStake.getTopRequestIDs(self);
    for (uint i = 0; i < 5; i++) {
        self.currentMiners[i].value = _topId[i];
        self.requestQ[self.requestDetails[_topId[i]].apiUintVars[requestQPosition]] = 0;
        self.uintVars[currentTotalTips] += self.requestDetails[_topId[i]].apiUintVars[totalTip];
    }
    _currChallenge = keccak256(abi.encode(_nonce, _currChallenge, blockhash(block.number - 1)));
    self.currentChallenge = _currChallenge; 
    emit NewChallenge(
        _currChallenge,
        _topId,
        self.uintVars[difficulty],
        self.uintVars[currentTotalTips]
    );
}

function withdrawStake(TellorStorage.TellorStorageStruct storage self) public {
    TellorStorage.StakeInfo storage stakes = self.stakerDetails[msg.sender];
    require(now - (now % 86400) - stakes.startDate >= 7 days, "7 days didn't pass");
    require(stakes.currentStatus == 2, "Miner was not locked for withdrawal");
    stakes.currentStatus = 0;
    emit StakeWithdrawn(msg.sender);
}

function beginDispute(TellorStorage.TellorStorageStruct storage self, uint256 _requestId, uint256 _timestamp, uint256 _minerIndex) public {
    TellorStorage.Request storage _request = self.requestDetails[_requestId];
    require(_request.minedBlockNum[_timestamp] != 0, "Mined block is 0");
    require(_minerIndex < 5, "Miner index is wrong");
    address _miner = _request.minersByValue[_timestamp][_minerIndex];
    bytes32 _hash = keccak256(abi.encodePacked(_miner, _requestId, _timestamp));
    uint256 disputeId = self.uintVars[keccak256("disputeCount")] + 1;
    self.uintVars[keccak256("disputeCount")] = disputeId;
    uint256 hashId = self.disputeIdByDisputeHash[_hash];
    if (hashId != 0) {
        self.disputesById[disputeId].disputeUintVars[keccak256("origID")] = hashId;
    } else {
        self.disputeIdByDisputeHash[_hash] = disputeId;
        hashId = disputeId;
    }
    uint256 origID = hashId;
    uint256 dispRounds = self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")] + 1;
    self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")] = dispRounds;
    self.disputesById[origID].disputeUintVars[keccak256(abi.encode(dispRounds))] = disputeId;
    if (disputeId != origID) {
        uint256 lastID = self.disputesById[origID].disputeUintVars[keccak256(abi.encode(dispRounds - 1))];
        require(self.disputesById[lastID].disputeUintVars[keccak256("minExecutionDate")] <= now, "Dispute is already open");
        if (self.disputesById[lastID].executed) {
            require(now - self.disputesById[lastID].disputeUintVars[keccak256("tallyDate")] <= 1 days, "Time for voting haven't elapsed");
        }
    }
    uint256 _fee;
    if (_minerIndex == 2) {
        self.requestDetails[_requestId].apiUintVars[keccak256("disputeCount")] = self.requestDetails[_requestId].apiUintVars[keccak256("disputeCount")] + 1;
        _fee = self.uintVars[keccak256("stakeAmount")] * self.requestDetails[_requestId].apiUintVars[keccak256("disputeCount")];
    } else {
        _fee = self.uintVars[keccak256("disputeFee")] * dispRounds;
    }
    self.disputesById[disputeId] = TellorStorage.Dispute({
        hash: _hash,
        isPropFork: false,
        reportedMiner: _miner,
        reportingParty: msg.sender,
        proposedForkAddress: address(0),
        executed: false,
        disputeVotePassed: false,
        tally: 0
    });
    self.disputesById[disputeId].disputeUintVars[keccak256("requestId")] = _requestId;
    self.disputesById[disputeId].disputeUintVars[keccak256("timestamp")] = _timestamp;
    self.disputesById[disputeId].disputeUintVars[keccak256("value")] = _request.valuesByTimestamp[_timestamp][_minerIndex];
    self.disputesById[disputeId].disputeUintVars[keccak256("minExecutionDate")] = now + 2 days * dispRounds;
    self.disputesById[disputeId].disputeUintVars[keccak256("blockNumber")] = block.number;
    self.disputesById[disputeId].disputeUintVars[keccak256("minerSlot")] = _minerIndex;
    self.disputesById[disputeId].disputeUintVars[keccak256("fee")] = _fee;
    TellorTransfer.doTransfer(self, msg.sender, address(this), _fee);
    if (_minerIndex == 2) {
        _request.inDispute[_timestamp] = true;
        _request.finalValues[_timestamp] = 0;
    }
    if (self.stakerDetails[_miner].currentStatus != 4) {
        self.stakerDetails[_miner].currentStatus = 3;
    }
    emit NewDispute(disputeId, _requestId, _timestamp, _miner);
}

function updateTellor(TellorStorage.TellorStorageStruct storage self, uint _disputeId) public {
    bytes32 _hash = self.disputesById[_disputeId].hash;
    uint256 origID = self.disputeIdByDisputeHash[_hash];
    uint256 lastID = self.disputesById[origID].disputeUintVars[keccak256(abi.encode(self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")]))];
    TellorStorage.Dispute storage disp = self.disputesById[lastID];
    require(disp.disputeVotePassed == true, "vote needs to pass");
    require(now - disp.disputeUintVars[keccak256("tallyDate")] > 1 days, "Time for voting for further disputes has not passed");
    self.addressVars[keccak256("tellorContract")] = disp.proposedForkAddress;
}

function submitMiningSolution(TellorStorage.TellorStorageStruct storage self, string calldata _nonce, uint256[5] calldata _requestId, uint256[5] calldata _value)
external {
    bytes32 _hashMsgSender = keccak256(abi.encode(msg.sender));
    require(self.stakerDetails[msg.sender].currentStatus == 1, "Miner status is not staker");
    require(now - self.uintVars[_hashMsgSender] > 15 minutes, "Miner can only win rewards once per 15 min");
    require(_requestId[0] == self.currentMiners[0].value, "Request ID is wrong");
    require(_requestId[1] == self.currentMiners[1].value, "Request ID is wrong");
    require(_requestId[2] == self.currentMiners[2].value, "Request ID is wrong");
    require(_requestId[3] == self.currentMiners[3].value, "Request ID is wrong");
    require(_requestId[4] == self.currentMiners[4].value, "Request ID is wrong");
    self.uintVars[_hashMsgSender] = now;
    bytes32 _currChallenge = self.currentChallenge;
    uint256 _slotProgress = self.uintVars[slotProgress];
    require(uint256(
            sha256(abi.encodePacked(ripemd160(abi.encodePacked(keccak256(abi.encodePacked(_currChallenge, msg.sender, _nonce))))))
        ) %
        self.uintVars[difficulty] == 0 ||
        (now - (now % 1 minutes)) - self.uintVars[timeOfLastNewValue] >= 15 minutes,
        "Incorrect nonce for current challenge"
    );
    require(self.minersByChallenge[_currChallenge][msg.sender] == false, "Miner already submitted the value");
    self.minersByChallenge[_currChallenge][msg.sender] = true;
    TellorStorage.Request storage _tblock = self.requestDetails[self.uintVars[_tBlock]];
    _tblock.minersByValue[1][_slotProgress] = msg.sender;
    _tblock.valuesByTimestamp[0][_slotProgress] = _value[0];
    _tblock.valuesByTimestamp[1][_slotProgress] = _value[1];
    _tblock.valuesByTimestamp[2][_slotProgress] = _value[2];
    _tblock.valuesByTimestamp[3][_slotProgress] = _value[3];
    _tblock.valuesByTimestamp[4][_slotProgress] = _value[4];
    _tblock.minersByValue[0][self.uintVars[slotProgress]] = msg.sender;
    _tblock.minersByValue[1][self.uintVars[slotProgress]] = msg.sender;
    _tblock.minersByValue[2][self.uintVars[slotProgress]] = msg.sender;
    _tblock.minersByValue[3][self.uintVars[slotProgress]] = msg.sender;
    _tblock.minersByValue[4][self.uintVars[slotProgress]] = msg.sender;
    _payReward(self, _slotProgress);
    self.uintVars[slotProgress]++;
    if (_slotProgress + 1 == 5) { 
        newBlock(self, _nonce, _requestId);
        self.uintVars[slotProgress] = 0;
    }
    emit NonceSubmitted(msg.sender, _nonce, _requestId, _value, _currChallenge);
}

function unlockDisputeFee(TellorStorage.TellorStorageStruct storage self, uint _disputeId) public {
    uint256 origID = self.disputeIdByDisputeHash[self.disputesById[_disputeId].hash];
    uint256 lastID = self.disputesById[origID].disputeUintVars[keccak256(abi.encode(self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")]))];
    if (lastID == 0) {
        lastID = origID;
    }
    TellorStorage.Dispute storage disp = self.disputesById[origID];
    TellorStorage.Dispute storage last = self.disputesById[lastID];
    uint256 dispRounds = disp.disputeUintVars[keccak256("disputeRounds")];
    if (dispRounds == 0) {
        dispRounds = 1;
    }
    uint256 _id;
    require(disp.disputeUintVars[keccak256("paid")] == 0, "already paid out");
    require(now - last.disputeUintVars[keccak256("tallyDate")] > 1 days, "Time for voting haven't elapsed");
    TellorStorage.StakeInfo storage stakes = self.stakerDetails[disp.reportedMiner];
    disp.disputeUintVars[keccak256("paid")] = 1;
    if (last.disputeVotePassed == true) {
        stakes.startDate = now - (now % 86400);
        self.uintVars[keccak256("stakerCount")] -= 1;
        updateMinDisputeFee(self);
        if (stakes.currentStatus == 4) {
            stakes.currentStatus = 5;
            TellorTransfer.doTransfer(self, disp.reportedMiner, disp.reportingParty, self.uintVars[keccak256("stakeAmount")]);
            stakes.currentStatus = 0;
        }
        for (uint i = 0; i < dispRounds; i++) {
            _id = disp.disputeUintVars[keccak256(abi.encode(dispRounds - i))];
            if (_id == 0) {
                _id = origID;
            }
            TellorStorage.Dispute storage disp2 = self.disputesById[_id];
            TellorTransfer.doTransfer(self, address(this), disp2.reportingParty, disp2.disputeUintVars[keccak256("fee")]);
        }
    } else {
        stakes.currentStatus = 1;
        TellorStorage.Request storage _request = self.requestDetails[disp.disputeUintVars[keccak256("requestId")]];
        if (disp.disputeUintVars[keccak256("minerSlot")] == 2) {
            _request.finalValues[disp.disputeUintVars[keccak256("timestamp")]] = disp.disputeUintVars[keccak256("value")];
        }
        if (_request.inDispute[disp.disputeUintVars[keccak256("timestamp")]] == true) {
            _request.inDispute[disp.disputeUintVars[keccak256("timestamp")]] = false;
        }
        for (uint i = 0; i < dispRounds; i++) {
            _id = disp.disputeUintVars[keccak256(abi.encode(dispRounds - i))];
            if (_id != 0) {
                last = self.disputesById[_id]; 
            }
            TellorTransfer.doTransfer(self, address(this), last.reportedMiner, self.disputesById[_id].disputeUintVars[keccak256("fee")]);
        }
    }
    if (disp.disputeUintVars[keccak256("minerSlot")] == 2) {
        self.requestDetails[disp.disputeUintVars[keccak256("requestId")]].apiUintVars[keccak256("disputeCount")]--;
    }
}

function proposeFork(TellorStorage.TellorStorageStruct storage self, address _propNewTellorAddress) public {
    bytes32 _hash = keccak256(abi.encode(_propNewTellorAddress));
    TellorTransfer.doTransfer(self, msg.sender, address(this), 100e18); 
    self.uintVars[keccak256("disputeCount")]++;
    uint256 disputeId = self.uintVars[keccak256("disputeCount")];
    if (self.disputeIdByDisputeHash[_hash] != 0) {
        self.disputesById[disputeId].disputeUintVars[keccak256("origID")] = self.disputeIdByDisputeHash[_hash];
    } else {
        self.disputeIdByDisputeHash[_hash] = disputeId;
    }
    uint256 origID = self.disputeIdByDisputeHash[_hash];
    self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")]++;
    uint256 dispRounds = self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")];
    self.disputesById[origID].disputeUintVars[keccak256(abi.encode(dispRounds))] = disputeId;
    if (disputeId != origID) {
        uint256 lastID = self.disputesById[origID].disputeUintVars[keccak256(abi.encode(dispRounds - 1))];
        require(self.disputesById[lastID].disputeUintVars[keccak256("minExecutionDate")] <= now, "Dispute is already open");
        if (self.disputesById[lastID].executed) {
            require(now - self.disputesById[lastID].disputeUintVars[keccak256("tallyDate")] <= 1 days, "Time for voting haven't elapsed");
        }
    }
    self.disputesById[disputeId] = TellorStorage.Dispute({
        hash: _hash,
        isPropFork: true,
        reportedMiner: msg.sender,
        reportingParty: msg.sender,
        proposedForkAddress: _propNewTellorAddress,
        executed: false,
        disputeVotePassed: false,
        tally: 0
    });
    self.disputesById[disputeId].disputeUintVars[keccak256("blockNumber")] = block.number;
    self.disputesById[disputeId].disputeUintVars[keccak256("minExecutionDate")] = now + 7 days;
}

function requestStakingWithdraw(TellorStorage.TellorStorageStruct storage self) public {
    TellorStorage.StakeInfo storage stakes = self.stakerDetails[msg.sender];
    require(stakes.currentStatus == 1, "Miner is not staked");
    stakes.currentStatus = 2;
    stakes.startDate = now - (now % 86400);
    self.uintVars[keccak256("stakerCount")] -= 1;
    TellorDispute.updateMinDisputeFee(self);
    emit StakeWithdrawRequested(msg.sender);
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 20;
    uint256 bonusCond2 = 1 ether / 10;
    uint256 bonusCond3 = 1 ether / 5;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 20 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 30 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 40 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 30 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 50e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
}

function sell(uint256 amount) {
    require(!frozenAccount[msg.sender]);
    require(tokenBalanceOf[msg.sender] >= amount); 
    require(amount > 0);
    require(sellPrice > 0);
    sellCommission = msg.value / 1000; 
    require(address(this).send(buyCommission));
    _transfer(msg.sender, this, amount);
    uint256 revenue = amount * sellPrice;
    require(this.balance >= revenue);
    msg.sender.transfer(revenue); 
}

function buy() payable public {
    require(!frozenAccount[msg.sender]);
    require(msg.value > 0);
    buyCommission = msg.value / 1000; 
    require(address(this).send(buyCommission));
    buyToken();
}

function _endPool(address owner) internal {
    _updateAllReward();
    for (uint256 i = 0; i < CONTRACT_LIST.length; i++) {
        address account = CONTRACT_LIST[i];
        if (USER_REWARD[account] > 0) {
            uint256 rewards = USER_REWARD[account];
            USER_REWARD[account] = 0;
            rewardToken.transfer(account, rewards);
        }
        _stake_token_withdraw(account, USER_STAKED_AMOUNT[account]);
    }
    if (TEAM_POOL != address(0)) {
        if (USER_REWARD[TEAM_POOL] > 0) {
            uint256 rewards = USER_REWARD[TEAM_POOL];
            USER_REWARD[TEAM_POOL] = 0;
            rewardToken.transfer(TEAM_POOL, rewards);
        }
    }
    uint256 endRewardAmount = rewardToken.balanceOf(address(this));
    if (endRewardAmount > 0) {
        rewardToken.transfer(owner, endRewardAmount);
    }
    _setIsRunningPool(false);
}

function emergencyTokenExit(address account) external returns(bool) {
    uint256 amount = USER_STAKED_AMOUNT[account];
    _stake_token_withdraw(account, amount);
    USER_STAKED_AMOUNT[account] = 0;
    USER_REWARD[account] = 0;
    emit EmergencyWithdraw(account, amount);
}

function Unstake(address account) external returns(bool) {
    _updateAllReward();
    if (USER_REWARD[account] > 0) {
        uint256 rewards = USER_REWARD[account];
        USER_REWARD[account] = 0;
        rewardToken.transfer(account, rewards);
    }
    USER_STAKE_TIME[account] = 0;
    _stake_token_withdraw(account, USER_STAKED_AMOUNT[account]);
}

function stake(address account, uint256 amount) external returns(bool) {
    require(IS_RUNNING_POOL == true, "The pool has ended.");
    require(amount > 0, "The pool has ended.");
    _registAddress(account);
    _updateAllReward();
    if (UPDATED_TIMESTAMP[account] <= 0) {
        UPDATED_TIMESTAMP[account] = block.timestamp;
    }
    USER_STAKE_TIME[account] = block.timestamp;
    stakeToken.transferFrom(account, address(this), amount);
    USER_STAKED_AMOUNT[account] = USER_STAKED_AMOUNT[account].add(amount);
    TOTAL_STAKED_AMOUNT = TOTAL_STAKED_AMOUNT.add(amount);
    emit Stake(account, amount);
}

function _calculateEarn(uint256 elapsed, uint256 staked) internal view returns(uint256) {
    if (staked == 0) {
        return 0;
    }
    if (elapsed <= 0) {
        return 0;
    }
    uint256 oneYearReward = staked.mul(REWARD_RATE).div(100);
    uint256 oneDayReward = oneYearReward.div(365);
    uint256 oneTimesReward = oneDayReward.div(24);
    uint256 oneMinReward = oneTimesReward.div(60);
    uint256 oneSeconReward = oneMinReward.div(60);
    uint256 secondReward = oneSeconReward.mul(elapsed); 
    return secondReward;
}

function _elapsedBlock(uint256 updated) internal view returns(uint256) {
    uint256 open = updated;
    uint256 close = block.timestamp;
    return open >= close ? 0 : close - open;
}

function _updateReward(address host) internal {
    uint256 elapsed = _elapsedBlock(UPDATED_TIMESTAMP[host]);
    if (elapsed <= 0) {
        return;
    }
    uint256 stakeAmount = USER_STAKED_AMOUNT[host];
    if (stakeAmount <= 0) {
        return;
    }
    UPDATED_TIMESTAMP[host] = block.timestamp;
    uint256 baseEarned = _calculateEarn(elapsed, stakeAmount);
    if (REMAIN_REWARD >= baseEarned) {
        USER_REWARD[host] = baseEarned.mul(95).div(100).add(USER_REWARD[host]);
        USER_REWARD[TEAM_POOL] = baseEarned.mul(5).div(100).add(USER_REWARD[TEAM_POOL]);
        REMAIN_REWARD = REMAIN_REWARD.sub(baseEarned);
    } else {
        if (REMAIN_REWARD > 0) {
            uint256 remainAll = REMAIN_REWARD;
            REMAIN_REWARD = 0;
            USER_REWARD[host] = remainAll.mul(95).div(100).add(USER_REWARD[host]);
            USER_REWARD[TEAM_POOL] = remainAll.mul(5).div(100).add(USER_REWARD[TEAM_POOL]);
        }
        _setIsRunningPool(false);
    }
}

function claimReward(address account) external returns(bool) {
    _updateAllReward();
    require(USER_REWARD[account] > 0, "Nothing to claim");
    uint256 withrawAmount = USER_REWARD[account];
    USER_REWARD[account] = 0;
    USER_STAKE_TIME[account] = block.timestamp;
    rewardToken.transfer(account, withrawAmount);
}

function commitTeam(
    address _player,
    uint _value,
    uint[] _team
)
private returns(bool success) {
    require(players[_player].status >= 1);
    require(_team.length <= maxTeamSize);
    uint oldPrice = players[_player].teamPrice;
    uint newPrice = getTeamPrice(_team);
    require(oldPrice + _value >= newPrice);
    require(oldPrice + _value <= playerBudget);
    if (newPrice < oldPrice) {
        ERC20Interface(diipCoinContract).transfer(_player, (oldPrice - newPrice));
    }
    players[_player].teamPrice = newPrice;
    players[_player].team = _team;
    players[_player].status = 2;
    emit TeamCommitted(_player, newPrice, _team);
    return true;
}

