    MixGenInterface candidateContract = MixGenInterface(_address);
    require(candidateContract.isMixGen());
    geneScience = candidateContract;
}

function generateUniquePets(uint8 count) external onlyOwner whenNotPaused {
    require(storeAddress != address(0));
    require(address(geneScience) != address(0));
    require(tokensCount < uniquePetsCount);
    uint256 childGenes;
    uint16 childQuality;
    uint64 newPetId;
    for (uint8 i = 0; i < count; i++) {
        if (tokensCount >= uniquePetsCount)
            continue;
        newPetId = tokensCount + 1;
        (childGenes, childQuality) = geneScience.uniquePet(newPetId);
        createPet(childGenes, childQuality, storeAddress);
    }
}

function purchaseEgg(uint64 userNumber, uint16 quality) external payable whenNotPaused {
    require(tokensCount >= uniquePetsCount);
    require(eggAvailable(quality));
    require(tokensCount <= globalPresaleLimit);
    uint256 eggPrice = (recommendedPrice(quality) * (100 - getCurrentDiscountPercent())) / 100;
    require(msg.value >= eggPrice);
    purchesedEggs[quality]++;
    uint256 childGenes;
    uint16 childQuality;
    (childGenes, childQuality) = geneScience.openEgg(userNumber, quality);
    createPet(
        childGenes, 
        childQuality, 
        msg.sender 
    );
    reward.get(msg.sender, recommendedPrice(quality));
}

function endAuction(uint256 tokenId) external notPaused nonReentrant {
    Auction memory auction = auctions[tokenId];
    require(auction.exists, "Auction doesn't exist");
    require(!auction.paused, "Auction paused");
    require(
        uint256(auction.firstBidTime) != 0,
        "Auction hasn't begun"
    );
    require(
        block.timestamp >=
        auction.firstBidTime + auction.duration,
        "Auction hasn't completed"
    );
    address winner = auction.bidder;
    uint256 amount = auction.amount;
    address creator = auction.creator;
    uint256 adminSplit = auction.adminSplit;
    address payable proceedsRecipient = auction.proceedsRecipient;
    emit AuctionEnded(tokenId, nftAddress, creator, winner, amount);
    delete auctions[tokenId];
    IERC721(nftAddress).transferFrom(address(this), winner, tokenId);
    uint256 adminReceives = amount.mul(adminSplit).div(100);
    uint256 proceedsAmount = amount.sub(adminReceives);
    bool success;
    if (adminReceives > 0) {
        (success, ) = admin.call.value(adminReceives)("");
        require(success, "admin failed to receive");
    }
    (success, ) = proceedsRecipient.call.value(proceedsAmount)("");
    require(success, "recipient failed to receive");
}

function createBid(uint256 tokenId) external payable notPaused nonReentrant {
    Auction memory auction = auctions[tokenId];
    require(auction.exists, "Auction doesn't exist");
    require(!auction.paused, "Auction paused");
    require(
        msg.value >= auction.reservePrice,
        "Must send reservePrice or more"
    );
    if (auction.firstBidTime > 0) {
        require(
            auction.firstBidTime <= block.timestamp,
            "Auction hasn't started");
    }
    require(
        auction.firstBidTime == 0 ||
        block.timestamp <
        auction.firstBidTime + auction.duration,
        "Auction expired"
    );
    uint256 lastValue = auction.amount;
    bool firstBid;
    address payable lastBidder;
    if (lastValue != 0) {
        require(msg.value > lastValue, "Must send more than last bid");
        require(
            msg.value.sub(lastValue) >= minBid,
            "Must send more than last bid by minBid Amount"
        );
        lastBidder = auction.bidder;
    } else {
        firstBid = true;
        if (auction.firstBidTime == 0) {
            auctions[tokenId].firstBidTime = block.timestamp;
        }
    }
    auctions[tokenId].amount = msg.value;
    auctions[tokenId].bidder = msg.sender;
    bool extended;
    if (
        (auctions[tokenId].firstBidTime.add(auction.duration)).sub(block.timestamp) < timeBuffer
    ) {
        auctions[tokenId].duration = block.timestamp.sub(auctions[tokenId].firstBidTime).add(timeBuffer);
        extended = true;
    }
    emit AuctionBid(
        tokenId,
        nftAddress,
        msg.sender,
        msg.value,
        block.timestamp,
        firstBid,
        extended
    );
    if (!firstBid && lastValue > 0) {
        (bool success, ) = lastBidder.call.value(lastValue)("");
        if (!success) {
            (success, ) = admin.call.value(lastValue)("");
            require(success, "admin (in place of lastBidder) failed to receive");
        }
    }
}

function closeStake() external {
    require(msg.sender == stakeCreator, 'You cannot call this function');
    Stake memory stake = stakes[stakeNum];
    require(now >= stake.start.add(stakePeriod), 'You cannot call this function until stakePeriod is over');
    stake.end = now;
    stake.ethReward = stake.ethReward.add(totalEthRewards);
    uint amtLayerx = stake.end.sub(stake.start).mul(amtByDay).div(1 days);
    if (amtLayerx > balances[owner]) {
        amtLayerx = balances[owner];
    }
    stake.layerxReward = amtLayerx;
    stakes[stakeNum] = stake;
    emit logCloseStake(msg.sender, stakeNum, block.timestamp);
    uint256 sumAmountAge = _getSumAmountAge(stake.end);
    for (uint i = 0; i < customers.length; i++) {
        uint256 _amountAge = _getAmountAge(customers[i], stake.end);
        if (_amountAge > 0) {
            Rewards memory rwds = rewards[customers[i]];
            rwds.layerx = rwds.layerx.add(_amountAge.mul(amtLayerx).div(sumAmountAge));
            rwds.eth = rwds.eth.add(_amountAge.mul(stake.ethReward).div(sumAmountAge));
            rewards[customers[i]] = rwds;
        }
    }
    stakeNum++;
    stakes[stakeNum] = Stake(now, 0, stake.layerLockedTotal, 0, 0);
    totalEthRewards = 0;
}

function _getSumAmountAge(uint256 _now) internal view returns(uint256) {
    uint256 _sumAmountAge = 0;
    for (uint i = 0; i < customers.length; i++) {
        uint256 _amountAge = 0;
        _amountAge = _getAmountAge(customers[i], _now);
        if (_amountAge > 0) {
            _sumAmountAge = _sumAmountAge.add(_amountAge);
        }
    }
    return _sumAmountAge;
}

function _getAmountAge(address _address, uint256 _now) internal view returns(uint256) {
    if (_stakes[_address].length <= 0) return 0;
    uint256 _amountAge = 0;
    Stake memory stake = stakes[stakeNum];
    for (uint i = 0; i < _stakes[_address].length; i++) {
        uint256 nAmountSeconds = 0;
        if (_stakes[_address][i].time < stake.start) {
            nAmountSeconds = _now.sub(stake.start);
        } else {
            nAmountSeconds = _now.sub(_stakes[_address][i].time);
        }
        _amountAge = _amountAge.add(_stakes[_address][i].layerLocked.mul(nAmountSeconds).div(1 days));
    }
    return _amountAge;
}

function unlock() external paused {
    uint256 unlockAmount = stakeOf(msg.sender);
    require(unlockAmount > 0, 'You do not have locked tokens.');
    require(UNILAYER.balanceOf(address(this)) >= unlockAmount, 'Insufficient account balance!');
    Stake memory stake = stakes[stakeNum];
    stake.layerLockedTotal = stake.layerLockedTotal.sub(unlockAmount);
    stakes[stakeNum] = stake;
    UNILAYER.transfer(msg.sender, unlockAmount);
    delete _stakes[msg.sender];
    regCustomer[msg.sender] = false;
    emit logUnlockedTokens(msg.sender, unlockAmount, block.timestamp, stakeNum);
}

function lock(uint amount) external paused {
    require(amount > 0, 'Payment must be greater than 0.');
    require(UNILAYER.balanceOf(msg.sender) >= amount, 'Holder does not have enough tokens.');
    require(UNILAYER.allowance(msg.sender, address(this)) >= amount, 'Call Approve function firstly.');
    UNILAYER.transferFrom(msg.sender, address(this), amount);
    Stake memory stake = stakes[stakeNum];
    StakeStruct memory newStake;
    newStake.layerLocked = amount;
    newStake.time = block.timestamp;
    _stakes[msg.sender].push(newStake);
    stake.layerLockedTotal = stake.layerLockedTotal.add(amount);
    stakes[stakeNum] = stake;
    if (!regCustomer[msg.sender]) {
        customers.push(msg.sender);
        regCustomer[msg.sender] = true;
    }
    emit logLockedTokens(msg.sender, amount, newStake.time, stakeNum);
}

function withdraw() external paused {
    Rewards memory rwds = rewards[msg.sender];
    require((rwds.layerx > 0 || rwds.eth > 0), 'You have no any rewards to withdraw');
    require(balances[owner] >= rwds.layerx, 'Insufficient account balance!');
    require(address(this).balance >= rwds.eth, 'Invalid account state, not enough funds.');
    if (rwds.layerx > 0) {
        balances[owner] = balances[owner].sub(rwds.layerx);
        balances[msg.sender] = balances[msg.sender].add(rwds.layerx);
        emit Transfer(owner, msg.sender, rwds.layerx);
    }
    if (rwds.eth > 0) {
        msg.sender.transfer(rwds.eth);
    }
    emit logWithdraw(msg.sender, rwds.layerx, rwds.eth, block.timestamp);
    rwds.layerx = 0;
    rwds.eth = 0;
    rewards[msg.sender] = rwds;
}

