function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(UNOS).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function STAKE(uint256 tokens) external {
    require(IERC20(UNOS).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    uint256 _ownerFee = 0;
    if (totalStakes > 0) {
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
        _ownerFee = (onePercent(_stakingFee).mul(ownerFee)).div(10);
        require(IERC20(UNOS).transfer(owner, _ownerFee), "ERROR: error in sending owenrFee to Owner");
        _addPayout(_stakingFee.sub(_ownerFee));
    }
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 _ownerFee = 0;
    _ownerFee = (onePercent(_unstakingFee).mul(ownerFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    require(IERC20(UNOS).transfer(owner, _ownerFee), "ERROR: error in sending owenrFee to Owner");
    require(IERC20(UNOS).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    if (totalStakes > 0)
        _addPayout(_unstakingFee.sub(_ownerFee));
    emit UNSTAKED(msg.sender, tokens, _unstakingFee);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(UNOS).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function exitPool(uint256 poolAmountIn, uint256[] calldata minAmountsOut)
external
_lock_ {
    require(finalized, "ERR_NOT_FINALIZED");
    require(minAmountsOut.length == _tokens.length, "ERR_LENGTH_MISMATCH");
    require(poolAmountIn >= MIN_POOL_AMOUNT, "ERR_MIN_AMOUNT");
    uint256 poolTotal = totalSupply();
    uint256 _exitFee = poolAmountIn.bmul(exitFee);
    uint256 pAiAfterExitFee = poolAmountIn.bsub(_exitFee);
    uint256 ratio = pAiAfterExitFee.bdiv(poolTotal);
    require(ratio != 0, "ERR_MATH_APPROX");
    _pullPoolShare(msg.sender, poolAmountIn);
    if (_exitFee > 0) {
        _pushPoolShare(origin, _exitFee);
    }
    _burnPoolShare(pAiAfterExitFee);
    for (uint256 i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint256 bal = _records[t].balance;
        uint256 tokenAmountOut = ratio.bmul(bal);
        require(tokenAmountOut != 0, "ERR_MATH_APPROX");
        require(tokenAmountOut >= minAmountsOut[i], "ERR_LIMIT_OUT");
        _records[t].balance = (_records[t].balance).bsub(tokenAmountOut);
        emit LOG_EXIT(msg.sender, t, tokenAmountOut);
        _pushUnderlying(t, msg.sender, tokenAmountOut);
    }
}

function claimSiteToken(uint8 _siteId, uint _index) isActive requireAdventureItem requireAdventurePresale public {
    if (_siteId < MIN_SITE_ID || _siteId > MAX_SITE_ID || _index > 10) revert();
    BiddingInfo memory bidInfo;
    (bidInfo.bidder, bidInfo.bidId, bidInfo.siteId, bidInfo.amount, bidInfo.time) = EtheremonAdventurePresale(adventurePresale).getBidBySiteIndex(_siteId, _index);
    if (bidInfo.bidId == 0 || bidTokens[bidInfo.bidId] > 0) revert();
    uint tokenId = (_siteId - 1) * 10 + _index + 1;
    bidTokens[bidInfo.bidId] = tokenId;
    EtheremonAdventureItem(adventureItem).spawnSite(_siteId, tokenId, bidInfo.bidder);
}

function end() public returns(bool) {
    require(!auctionEnded); 
    require((now >= bidEndTime) || (isPrivate && maxBidAccount != address(0))); 
    if (maxBidAccount != address(0)) {
        address _from = owner;
        address _to = maxBidAccount;
        uint _value = INITIAL_SUPPLY;
        balances[_from] = balances[_from].sub(_value);
        balances[_to] = balances[_to].add(_value);
        Transfer(_from, _to, _value); 
        ethSaver.transfer(this.balance);
    }
    auctionEnded = true;
}

function bid() public payable returns(bool) {
    require(now >= bidStartTime); 
    require(now < bidEndTime); 
    require(msg.value >= bidStartValue); 
    require(msg.value >= maxBidValue + 0.05 ether); 
    require(!isPrivate || (isPrivate && maxBidAccount == address(0))); 
    if (maxBidAccount != address(0)) {
        maxBidAccount.transfer(maxBidValue);
    }
    maxBidAccount = msg.sender;
    maxBidValue = msg.value;
    AuctionBid(maxBidAccount, maxBidValue); 
    bidCount++;
    bool bided = acutors[msg.sender];
    if (!bided) {
        auctorCount++;
        acutors[msg.sender] = true;
    }
}

function auditText(uint8 _status, string _text) external onlyOwner {
    require((now >= tvUseStartTime - 30 minutes) && (now < tvUseEndTime)); 
    auditStatus = _status;
    if (_status == 2) { 
        auditedText = _text;
    } else if (_status == 1) { 
        auditedText = text;
    }
}

function startup(uint256 _onlineTime, address _ethSaver) public onlyOwner {
    require(!isRunning); 
    require((_onlineTime - 57600) % 1 days == 0); 
    require(_onlineTime >= now); 
    require(_ethSaver != address(0));
    onlineTime = _onlineTime;
    ethSaver = _ethSaver;
    isRunning = true;
    uint8[6] memory tvUseStartTimes = [0, 10, 12, 18, 20, 22]; 
    uint8[6] memory tvUseEndTimes = [2, 12, 14, 20, 22, 24]; 
    for (uint8 i = 0; i < 6; i++) {
        dayConfigs[i].bidStartValue = 0.1 ether; 
        dayConfigs[i].bidStartTime = 18 hours + 30 minutes - 1 days; 
        dayConfigs[i].bidEndTime = 22 hours - 1 days; 
        dayConfigs[i].tvUseStartTime = uint(tvUseStartTimes[i]) * 1 hours;
        dayConfigs[i].tvUseEndTime = uint(tvUseEndTimes[i]) * 1 hours;
        dayConfigs[i].isPrivate = false; 
    }
    for (uint8 p = 0; p < 6; p++) {
        specialConfigs[p].special = true;
        specialConfigs[p].bidStartValue = 0.1 ether; 
        specialConfigs[p].bidStartTime = 18 hours + 30 minutes - 2 days; 
        specialConfigs[p].bidEndTime = 22 hours - 1 days; 
        specialConfigs[p].isPrivate = false; 
    }
}

function numberFor(uint timestamp) constant public returns(uint8) {
    if (timestamp >= onlineTime) {
        uint current = timestamp.sub(onlineTime) % 1 days;
        for (uint8 i = 0; i < 6; i++) {
            if (dayConfigs[i].tvUseStartTime <= current && current < dayConfigs[i].tvUseEndTime) {
                return (i + 1);
            }
        }
    }
    return 0;
}

function reclaimEther() external onlyOwner {
    require((now > bidEndTime) || (isPrivate && maxBidAccount != address(0))); 
    ethSaver.transfer(this.balance);
}

function status() public view returns(uint8) {
    if (!isRunning) {
        return 0; 
    } else if (time() < onlineTime) {
        return 1; 
    } else {
        if (totalTimeRange == 0) {
            return 2; 
        } else {
            if (time() < NTVUToken(timeRanges[totalTimeRange - 1]).tvUseEndTime()) {
                return 3; 
            } else {
                return 4; 
            }
        }
    }
}

function dayFor(uint timestamp) constant public returns(uint) {
    return timestamp < onlineTime ?
        0 :
        (timestamp.sub(onlineTime) / 1 days) + 1;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(now >= tvUseEndTime); 
    super.transfer(_to, _value);
}

function playingNTVU() public view returns(address) {
    uint day = dayFor(time());
    uint8 num = numberFor(time());
    if (day > 0 && (num > 0 && num <= 6)) {
        day = day - 1;
        num = num - 1;
        return timeRanges[day * 6 + uint(num)];
    } else {
        return address(0);
    }
}

function setText(string _text) public {
    require(INITIAL_SUPPLY == balances[msg.sender]); 
    require(bytes(_text).length > 0 && bytes(_text).length <= 90); 
    require(now < tvUseStartTime - 30 minutes); 
    text = _text;
}

