    require(_balances[msg.sender] > 0, "Sender is not due any tokens");
    require(_token.balanceOf(address(this)) >= _balances[msg.sender], "Insufficent contract balance to make claim, try again later.");
    _token.transfer(msg.sender, _balances[msg.sender]);
    emit Claimed(msg.sender, _balances[msg.sender]);
    _balances[msg.sender] = 0;
}

function withdraw() {
    require(withdrew[msg.sender] == false);
    withdrew[msg.sender] = true;
    uint256 balance = contr.balances_bonus(msg.sender);
    uint256 contract_token_balance = token.balanceOf(address(this));
    uint256 tokens_to_withdraw = (balance * contract_token_balance) / eth_balance;
    eth_balance -= balance;
    require(token.transfer(msg.sender, tokens_to_withdraw));
}

function mintShares(
    MinterReceiver receiver,
    address supplier,
    uint256 newStakedHearts,
    uint256 newStakedDays
) external lock {
    require(
        ERC165Checker.supportsInterface(
            address(receiver),
            type(MinterReceiver).interfaceId
        ),
        "UNSUPPORTED_RECEIVER"
    );
    hexContract.transferFrom(msg.sender, address(this), newStakedHearts);
    hexContract.stakeStart(newStakedHearts, newStakedDays);
    uint256 stakeCount = hexContract.stakeCount(address(this));
    (
        uint40 stakeId,
        uint72 stakedHearts,
        uint72 stakeShares,
        uint16 lockedDay,
        uint16 stakedDays, ,
    ) = hexContract.stakeLists(address(this), stakeCount - 1);
    uint24 unlockDay = lockedDay + stakedDays;
    Stake storage stake = stakes[stakeId];
    stake.receiver = receiver;
    stake.unlockDay = unlockDay;
    receiver.onSharesMinted(stakeId, supplier, stakedHearts, stakeShares);
    emit MintShares(stakeId, receiver, stakeShares);
}

