function buy(address recipient) payable {
    if (recipient == 0x0) throw;
    if (msg.value < MIN_ETHER) throw;
    if (totalTokens >= totalSupply) throw;
    if (_saleState == TokenSaleState.Frozen) throw;
    if ((_saleState == TokenSaleState.Initial || _saleState == TokenSaleState.Presale) && presaleSupply >= presaleAllocation) throw;
    if ((_saleState == TokenSaleState.Initial || _saleState == TokenSaleState.Presale) && presaleEtherRaised >= etherCap) throw;
    updateTokenSaleState();
    uint tokens = mul(msg.value, price());
    if (tokens == 0) throw;
    balances[recipient] = add(balances[recipient], tokens);
    totalTokens = add(totalTokens, tokens);
    if (_saleState == TokenSaleState.Initial || _saleState == TokenSaleState.Presale) {
        presaleEtherRaised = add(presaleEtherRaised, msg.value);
        presaleSupply = add(presaleSupply, tokens);
    }
    founder.transfer(msg.value);
    Transfer(0, recipient, tokens);
    Buy(recipient, msg.value, tokens);
}

function checkKingFounder(address gladiator) internal {
    if (gladiatorToPower[gladiator] > gladiatorToPower[kingGladiatorFounder] && now < initGameAt) {
        kingGladiatorFounder = gladiator;
    }
}

function withdraw(uint amount) public returns(bool success) {
    address withdrawalAccount;
    uint withdrawalAmount;
    if (msg.sender == m_Owner || msg.sender == partner) {
        withdrawalAccount = m_Owner;
        withdrawalAmount = m_OwnerFees;
        uint kingGladiatorFounderProffits = SafeMath.div(withdrawalAmount, 4);
        uint partnerFee = SafeMath.div(SafeMath.mul(SafeMath.sub(withdrawalAmount, kingGladiatorFounderProffits), 15), 100);
        m_OwnerFees = 0;
        if (!m_Owner.send(SafeMath.sub(SafeMath.sub(withdrawalAmount, partnerFee), kingGladiatorFounderProffits))) revert(); 
        if (!partner.send(partnerFee)) revert(); 
        if (!kingGladiatorFounder.send(kingGladiatorFounderProffits)) revert(); 
        return true;
    } else {
        withdrawalAccount = msg.sender;
        withdrawalAmount = amount;
        if (gladiatorToCooldown[msg.sender] < now && gladiatorToPower[withdrawalAccount] >= withdrawalAmount) {
            gladiatorToPower[withdrawalAccount] = SafeMath.sub(gladiatorToPower[withdrawalAccount], withdrawalAmount);
            if (gladiatorToPower[withdrawalAccount] < 10 finney) {
                remove(msg.sender);
            }
        } else {
            return false;
        }
    }
    if (withdrawalAmount == 0) revert();
    if (!msg.sender.send(withdrawalAmount)) revert();
    return true;
}

function joinArena() public payable returns(bool) {
    require(msg.value >= 10 finney && getGladiatorCooldown(msg.sender) != 9999999999999);
    if (queue.length > gladiatorToQueuePosition[msg.sender]) {
        if (queue[gladiatorToQueuePosition[msg.sender]] == msg.sender) {
            gladiatorToPower[msg.sender] += msg.value;
            checkKingFounder(msg.sender);
            return false;
        }
    }
    enter(msg.sender);
    return true;
}

function fight(address gladiator1, string _result) public {
    require(msg.sender == oraclizeContract);
    if (queue.length == 0) {
        gladiatorToCooldown[gladiator1] = now + 1 days;
        queue.push(gladiator1);
        gladiatorToQueuePosition[gladiator1] = queue.length - 1;
        kingGladiator = gladiator1;
    } else {
        uint indexgladiator2 = uint(sha3(_result)) % queue.length; 
        uint randomNumber = uint(sha3(_result)) % 1000;
        address gladiator2 = queue[indexgladiator2];
        require(gladiatorToPower[gladiator1] >= 10 finney && gladiator1 != gladiator2);
        uint g1chance = gladiatorToPower[gladiator1];
        uint g2chance = gladiatorToPower[gladiator2];
        uint fightPower = SafeMath.add(g1chance, g2chance);
        g1chance = (g1chance * 1000) / fightPower;
        if (g1chance <= 958) {
            g1chance = SafeMath.add(g1chance, 40);
        } else {
            g1chance = 998;
        }
        fightEvent(gladiator1, gladiator2, randomNumber, fightPower, gladiatorToPower[gladiator1]);
        uint devFee;
        if (randomNumber <= g1chance) { 
            devFee = SafeMath.div(SafeMath.mul(gladiatorToPower[gladiator2], 5), 100);
            gladiatorToPower[gladiator1] = SafeMath.add(gladiatorToPower[gladiator1], SafeMath.sub(gladiatorToPower[gladiator2], devFee));
            queue[gladiatorToQueuePosition[gladiator2]] = gladiator1;
            gladiatorToQueuePosition[gladiator1] = gladiatorToQueuePosition[gladiator2];
            gladiatorToPower[gladiator2] = 0;
            gladiatorToCooldown[gladiator1] = now + 1 days; 
            if (gladiatorToPower[gladiator1] > gladiatorToPower[kingGladiator]) { 
                kingGladiator = gladiator1;
            }
        } else {
            devFee = SafeMath.div(SafeMath.mul(gladiatorToPower[gladiator1], 5), 100);
            gladiatorToPower[gladiator2] = SafeMath.add(gladiatorToPower[gladiator2], SafeMath.sub(gladiatorToPower[gladiator1], devFee));
            gladiatorToPower[gladiator1] = 0;
            gladiatorToCooldown[gladiator1] = 0;
            if (gladiatorToPower[gladiator2] > gladiatorToPower[kingGladiator]) {
                kingGladiator = gladiator2;
            }
        }
        kingGladiator.transfer(SafeMath.div(devFee, 5)); 
        m_OwnerFees = SafeMath.add(m_OwnerFees, SafeMath.sub(devFee, SafeMath.div(devFee, 5))); 
    }
}

function finalize() auth note {
    require(time() >= endTime);
    kkk.start();
    kkk.transfer(destFoundation, kkk.balanceOf(this));
    kkk.setOwner(destFoundation);
}

function setStartTime(uint startTime_) auth note {
    require(time() <= startTime && time() <= startTime_);
    startTime = startTime_;
    endTime = startTime + 14 days;
}

function() payable stoppable note {
    require(!isContract(msg.sender));
    require(msg.value >= 0.01 ether);
    require(tx.gasprice <= MAX_GAS_PRICE);
    assert(time() >= startTime && time() < endTime);
    var toFund = cast(msg.value);
    var requested = wmul(toFund, PUBLIC_SALE_PRICE);
    if (add(sold, requested) >= SELL_HARD_LIMIT) {
        requested = SELL_HARD_LIMIT - sold;
        toFund = wdiv(requested, PUBLIC_SALE_PRICE);
        endTime = time();
    }
    var totalUserBuy = add(userBuys[msg.sender], toFund);
    assert(canBuy(totalUserBuy));
    userBuys[msg.sender] = totalUserBuy;
    sold = hadd(sold, requested);
    if (!moreThanSoftLimit && sold >= SELL_SOFT_LIMIT) {
        moreThanSoftLimit = true;
        endTime = time() + 24 hours; 
    }
    kkk.start();
    kkk.transfer(msg.sender, requested);
    kkk.stop();
    exec(destFoundation, toFund); 
    uint toReturn = sub(msg.value, toFund);
    if (toReturn > 0) {
        exec(msg.sender, toReturn);
    }
}

function disbursePrinciple(address _useraddress) internal { 
    uint reward;
    if (getLocktime(_useraddress) > now) {
        reward = ((phoenix.Packs(phoenix.getLastBuyPack(_useraddress)[1]) * fetchPrice(usdtFetchId) + users[_useraddress].extraPrinciple)) / fetchPrice(ecoFetchId);
        users[_useraddress].earnings[1] += reward;
        users[_useraddress].ecoBalance += reward;
        totalECOBalance += reward;
        users[_useraddress].ecoPauser = true;
    }
}

function weektrigger() public { 
    require(msg.sender == owner);
    for (uint i = 1000001; i < phoenix.lastuid(); i++) {
        address _address = phoenix.useridmap(i);
        uint _lastbuy = phoenix.getLastBuyPack(_address)[1];
        if (!users[_address].ecoPauser && _lastbuy > 0) {
            if (_lastbuy > lastweek) {
                users[_address].week = 0;
            }
            users[_address].week += 1;
            disburseRebate(_address);
            disbursePrinciple(_address);
        }
    }
    lastweek = now;
}

function disburseRebate(address _useraddress) internal { 
    uint reward;
    if (users[_useraddress].trainingLevel >= users[_useraddress].week && getLocktime(_useraddress) >= now) {
        reward = ((phoenix.Packs(phoenix.getLastBuyPack(_useraddress)[1]) * fetchPrice(usdtFetchId) + users[_useraddress].extraPrinciple) * 25) / 1000 / fetchPrice(ecoFetchId);
        users[_useraddress].earnings[0] += reward;
        users[_useraddress].ecoBalance += reward;
        totalECOBalance += reward;
    }
}

function disburseOptions(address _useraddress) internal { 
    uint reward;
    if (users[_useraddress].options == true && getLocktime(_useraddress) > now) {
        reward = (((phoenix.Packs(phoenix.getLastBuyPack(_useraddress)[1]) * fetchPrice(usdtFetchId) + users[_useraddress].extraPrinciple) * 20) / 100) / fetchPrice(ecoFetchId);
        users[_useraddress].earnings[2] += reward;
        users[_useraddress].ecoBalance += reward;
        totalECOBalance += reward;
    }
}

function disburseReward(address _useraddress) internal { 
    uint reward;
    reward = (((phoenix.Packs(phoenix.getLastBuyPack(_useraddress)[1]) * fetchPrice(usdtFetchId) + users[_useraddress].extraPrinciple) * 10) / 100) / fetchPrice(ecoFetchId);
    users[_useraddress].dueReward += reward;
    if (users[_useraddress].trainingLevel > 5 && getLocktime(_useraddress) > now) {
        users[_useraddress].earnings[1] += users[_useraddress].dueReward;
        users[_useraddress].ecoBalance += users[_useraddress].dueReward;
        totalECOBalance += users[_useraddress].dueReward;
        users[_useraddress].dueReward = 0;
    }
}

function redeemEcoBalance(address _useraddress) public { 
    require(phoenix.isUserExists(_useraddress), "user not exists");
    require(users[msg.sender].ecoBalance > 0, "insufficient balance");
    Eco.transfer(_useraddress, users[_useraddress].ecoBalance);
    users[_useraddress].ecoBalance = 0;
    totalECOBalance = totalECOBalance - users[_useraddress].ecoBalance;
    emit RedeemEarning(
        _useraddress,
        users[_useraddress].ecoBalance
    );
}

