function withdraw(uint tokenAmount, bytes signedData) external {
    uint256 nonce = withdrawalsNonce[msg.sender] + 1;
    bytes32 validatingHash = keccak256(msg.sender, tokenAmount, nonce);
    address addressRecovered = validatingHash.recover(signedData);
    require(addressRecovered == owner);
    require(token.transfer(msg.sender, tokenAmount));
    withdrawalsNonce[msg.sender] = nonce;
    Withdraw(msg.sender, tokenAmount);
}

function withdrawloss(address _from, address _to) public {
    require(_to == msg.sender);
    require(tos[_from] == _to);
    require(states[_from] == State.Verify);
    require(states[_to] == State.Normal);
    require(now >= verifytimes[_from] + 5 days);
    require(balances[_from] >= withdraw_fee_lost);
    emit onEventWithdrawLost(_from, _to, balances[_from].div(100000000000000));
    owner.transfer(withdraw_fee_lost);
    balances[_to] = balances[_to].add(balances[_from]).sub(withdraw_fee_lost);
    balances[_from] = 0;
    states[_from] = State.Normal;
    verifytimes[_from] = 0;
    tos[_from] = 0;
}

function withdraw(address _to, uint256 _value) public {
    require(states[msg.sender] != State.Lock);
    require(balances[msg.sender] >= _value.add(withdraw_fee));
    balances[msg.sender] = balances[msg.sender].sub(_value.add(withdraw_fee));
    _to.transfer(_value);
    owner.transfer(withdraw_fee);
    emit onEventWithdraw(msg.sender, _to, _value.div(100000000000000));
}

function resetState(address _from) public onlyOwner {
    require(states[_from] == State.Report || states[_from] == State.Lock);
    if (states[_from] == State.Report) {
        states[_from] = State.Normal;
        verifytimes[_from] = 0;
        tos[_from] = 0;
        emit onEventReset(_from);
    } else if (states[_from] == State.Lock) {
        states[_from] = State.Normal;
        balances[_from] = balances[_from].sub(report_lock);
        owner.transfer(report_lock);
        emit onEventUnlock(_from);
    }
}

function startMaxBuyLimitTimer() public onlyOwner {
    require(liquidityAdditionTime == 0, "Timer already started!");
    liquidityAdditionTime = now;
}

function _transferWithFee(address sender, address recipient, uint256 amount) internal {
    if (now < liquidityAdditionTime.add(20 minutes)) {
        require(sender == owner || amount <= 6552e16, "Cannot transfer more than 65.52 Tokens for now!");
        if (sender == owner) {
            _transfer(sender, recipient, amount);
            return;
        }
    }
    uint swissFee = amount.mul(swissFeePercentX100).div(100e2);
    uint deshFee = amount.mul(deshFeePercentX100).div(100e2);
    uint amountAfterFee = amount.sub(swissFee).sub(deshFee);
    _transfer(sender, fees_wallet_swiss, swissFee);
    _transfer(sender, fees_wallet_decash, deshFee);
    _transfer(sender, recipient, amountAfterFee);
}

function setStartTime(uint _startTime, uint _deadline) onlyOwner {
    if (block.timestamp >= startTime) throw;
    startTime = _startTime;
    deadline = _deadline;
}

function() payable {
    if (tx.gasprice > MAX_GAS_PRICE) throw;
    if (block.timestamp < startTime || block.timestamp >= deadline) throw;
    if (this.balance >= capAmount) throw;
    if (this.balance + msg.value >= capAmount) {
        deadline = block.timestamp;
    }
}

function shortenDeadline(uint t) onlyOwner {
    if (t > deadline) throw;
    deadline = t;
}

function withdraw() public {
    for (uint i = 0; i < activityCount; i++) {
        address addr = activityAccounts[i].addr;
        if (addr == msg.sender || msg.sender == owner) {
            uint amount = activityAccounts[i].balance;
            if (amount > 0) {
                activityAccounts[i].balance = 0;
                totalFundsWithdrawn += amount;
                if (!addr.call.gas(withdrawGas).value(amount)()) {
                    activityAccounts[i].balance = amount;
                    totalFundsWithdrawn -= amount;
                    MessageEvent("err: error sending funds");
                    return;
                }
            }
        }
    }
}

