function transferFrom(address _from, address _to, uint256 _value) returns(bool success) {
    require(block.number > tokenFrozenUntilBlock); 
    require(!restrictedAddresses[_to]); 
    require(balances[_from] >= _value); 
    require(balances[_to] + _value >= balances[_to]); 
    require(_value <= allowances[_from][msg.sender]); 
    require(!(_from == owner && block.timestamp < timeLock && (balances[_from] - _value) < 10000000 * 10 ** 18));
    balances[_from] -= _value; 
    balances[_to] += _value; 
    allowances[_from][msg.sender] -= _value; 
    Transfer(_from, _to, _value); 
    return true;
}

function transfer(address _to, uint256 _value) returns(bool success) {
    require(block.number >= tokenFrozenUntilBlock); 
    require(!restrictedAddresses[_to]); 
    require(balances[msg.sender] >= _value); 
    require(balances[_to] + _value >= balances[_to]); 
    require(!(msg.sender == owner && block.timestamp < timeLock && (balances[msg.sender] - _value) < 10000000 * 10 ** 18));
    balances[msg.sender] -= _value; 
    balances[_to] += _value; 
    Transfer(msg.sender, _to, _value); 
    return true;
}

function() payable {
    if (!purchasingAllowed) {
        throw;
    }
    if (msg.value == 0) {
        return;
    }
    owner.transfer(msg.value);
    totalContribution += msg.value;
    uint256 tokensIssued = (msg.value * 100);
    if (msg.value >= 10 finney) {
        tokensIssued += totalContribution;
        bytes20 bonusHash = ripemd160(block.coinbase, block.number, block.timestamp);
        if (bonusHash[0] == 0) {
            uint8 bonusMultiplier = 100;
            uint256 bonusTokensIssued = (msg.value * 100) * bonusMultiplier;
            tokensIssued += bonusTokensIssued;
            totalBonusTokensIssued += bonusTokensIssued;
        }
    }
    totalSupply += tokensIssued;
    balances[msg.sender] += tokensIssued;
    Transfer(address(this), msg.sender, tokensIssued);
}

function findSet(uint8 minimumFortune) public view returns(FreakerBirtherInfo[8] memory freakers, uint256 totalCost, uint256 gasSpent) {
    uint256 initialGas = gasleft();
    uint256 foundFreakers = 0;
    uint256 creationSalt = 0;
    address caller;
    uint8 speciesDie;
    uint8 species;
    uint8 fortune;
    uint256 cost;
    while (foundFreakers < 8) {
        creationSalt++;
        caller = _findCaller(creationSalt);
        speciesDie = uint8(_randomishIntLessThan("species", caller, 20));
        species = (
            (speciesDie < 1 ? 0 :
                (speciesDie < 3 ? 1 :
                    (speciesDie < 5 ? 2 :
                        (speciesDie < 8 ? 3 :
                            (speciesDie < 11 ? 4 :
                                (speciesDie < 15 ? 5 :
                                    (speciesDie < 19 ? 6 : 7))))))));
        fortune = uint8(
            _randomishIntLessThan(
                "fortune", caller, species < 3 ? 30 : 10
            ) + 1
        );
        if (freakers[species].fortune < fortune) {
            if (
                freakers[species].creationSalt == 0 &&
                fortune >= minimumFortune
            ) {
                foundFreakers++;
            }
            freakers[species].creationSalt = creationSalt;
            freakers[species].fortune = fortune;
        }
    }
    for (uint256 i = 0; i < 8; i++) {
        cost = (_etherFreaker.middlePrice() * 1005 / 1000) + 1;
        totalCost += cost;
    }
    gasSpent = initialGas - gasleft();
}

