        speciesDie = uint8(_randomishIntLessThan("species", caller, 20));
        species = (
            (speciesDie < 1 ? 0 :
                (speciesDie < 3 ? 1 :
                    (speciesDie < 5 ? 2 :
                        (speciesDie < 8 ? 3 :
                            (speciesDie < 11 ? 4 :
                                (speciesDie < 15 ? 5 :
                                    (speciesDie < 19 ? 6 : 7))))))));
        fortune = uint8(
            _randomishIntLessThan(
                "fortune", caller, species < 3 ? 30 : 10
            ) + 1
        );
        if (freakers[species].fortune < fortune) {
            if (
                freakers[species].creationSalt == 0 &&
                fortune >= minimumFortune
            ) {
                foundFreakers++;
            }
