function issueParityDollar(address StablecoinAddress, uint256 AmountOfParityDollars) external returns(string memory) {
    address msgSender = msg.sender;
    require(!safeguard, 'Safeguard was Activated');
    require(AmountOfParityDollars <= maxTransactionAmount, 'max Transaction Amount');
    require(StablecoinUnderCustody[StablecoinAddress], 'Invalid Stablecoin Address');
    uint256 StablecoinDecimals = IERC20(StablecoinAddress).decimals();
    uint256 StablecoinAmount = AmountOfParityDollars * (10 ** StablecoinDecimals) / (10 ** _decimals);
    IERC20(StablecoinAddress).transferFrom(msgSender, address(this), StablecoinAmount);
    _balanceOf[msgSender] = _balanceOf[msgSender].add(AmountOfParityDollars);
    _totalSupply = _totalSupply.add(AmountOfParityDollars);
    emit Transfer(address(0), msgSender, AmountOfParityDollars);
    emit Mint(msgSender, AmountOfParityDollars, DARSA_UAC, DARSA_UTC);
    return "Parity Dollar minted successfully";
}

function swapBack() internal swapping {
    uint256 amountToLiquify = swapThreshold.mul(liquidityFee).div(totalFee).div(2);
    uint256 amountToSwap = swapThreshold.sub(amountToLiquify);
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = WETH;
    uint256 balanceBefore = address(this).balance;
    router.swapExactTokensForETHSupportingFeeOnTransferTokens(
        amountToSwap,
        0,
        path,
        address(this),
        block.timestamp + 360
    );
    uint256 amountETH = address(this).balance.sub(balanceBefore);
    uint256 totalETHFee = totalFee.sub(liquidityFee.div(2));
    uint256 amountETHLiquidity = amountETH.mul(liquidityFee).div(totalETHFee).div(2);
    uint256 amountETHTeam = amountETH.mul(teamFee).div(totalETHFee);
    uint256 amountETHMarketing = amountETH.mul(marketingFee).div(totalETHFee);
    uint256 amountETHStaking = amountETH.mul(stakingFee).div(totalETHFee);
    payable(teamFeeReceiver).transfer(amountETHTeam.div(2));
    payable(teamFeeReceiver2).transfer(amountETHTeam.div(4));
    payable(teamFeeReceiver3).transfer(amountETHTeam.div(4));
    payable(marketingWallet).transfer(amountETHMarketing);
    payable(stakingWallet).transfer(amountETHStaking);
    if (amountToLiquify > 0) {
        router.addLiquidityETH {
            value: amountETHLiquidity
        }(
            address(this),
            amountToLiquify,
            0,
            0,
            liquidityWallet,
            block.timestamp + 360
        );
        emit AutoLiquify(amountETHLiquidity, amountToLiquify);
    }
}

function takeTheTorch_(uint256 _amountPaid, address _takenBy, address _referredBy) internal antiWhalePrice(_amountPaid) returns(uint256) {
    require(_takenBy != address(0));
    require(_amountPaid >= 5 finney);
    require(_takenBy != torchRunners[0]); 
    if (_referredBy == address(this)) {
        _referredBy = address(0);
    }
    address previousLast = torchRunners[2];
    torchRunners[2] = torchRunners[1];
    torchRunners[1] = torchRunners[0];
    torchRunners[0] = _takenBy;
    address dayOwner = OwnTheDayContract_.ownerOf(getDayIndex_(now));
    uint256 forDev = _amountPaid.mul(5).div(100);
    uint256 forTokens = _amountPaid.sub(_amountPaid.div(4));
    uint256 forPayout = _amountPaid.sub(forDev).sub(forTokens);
    uint256 forDayOwner = calculateDayOwnerCut_(forPayout);
    if (dayOwner == _takenBy) {
        forTokens = forTokens.add(forDayOwner);
        forPayout = _amountPaid.sub(forDev).sub(forTokens);
        playerData_[_takenBy].champion = true;
    } else {
        forPayout = forPayout.sub(forDayOwner);
    }
    onTorchPassed(torchRunners[1], _takenBy, _amountPaid);
    uint256 mintedTokens = CryptoTorchToken_.mint.value(forTokens)(_takenBy, forTokens, _referredBy);
    updateLeaders_(_takenBy, _amountPaid);
    handlePayouts_(forDev, forPayout, forDayOwner, _takenBy, previousLast, dayOwner);
    return mintedTokens;
}

function withdrawDividends() public returns(uint256) {
    CryptoTorchToken_.withdrawFor(msg.sender);
    return withdrawFor_(msg.sender);
}

function updateLeaders_(address _takenBy, uint256 _amountPaid) internal {
    if (_takenBy == owner || _takenBy == donationsReceiver_) {
        return;
    }
    if (_amountPaid > _lowestHighPrice) {
        updateHighestPrices_(_amountPaid, _takenBy);
    }
    uint256 tokenBalance = CryptoTorchToken_.balanceOf(_takenBy);
    if (tokenBalance > _lowestHighMiles) {
        updateHighestMiles_(tokenBalance, _takenBy);
    }
}

function getDayIndex_(uint timestamp) internal view returns(uint256) {
    uint16[12] memory offset = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
    uint8 day = DateTimeLib_.getDay(timestamp);
    uint8 month = DateTimeLib_.getMonth(timestamp) - 1;
    bool isLeapYear = DateTimeLib_.isLeapYear(DateTimeLib_.getYear(timestamp));
    if (isLeapYear && month > 1) {
        day = day + 1;
    }
    return offset[month] + day;
}

function getHolidayByIndex_(uint256 _dayIndex) internal view returns(uint result) {
    if (_dayIndex < 122) {
        return getFromList_(0, _dayIndex);
    }
    if (_dayIndex < 244) {
        return getFromList_(1, _dayIndex - 122);
    }
    return getFromList_(2, _dayIndex - 244);
}

function handlePayouts_(uint256 _forDev, uint256 _forPayout, uint256 _forDayOwner, address _takenBy, address _previousLast, address _dayOwner) internal {
    uint256[] memory runnerPortions = new uint256[](3);
    if (_previousLast != address(0)) {
        runnerPortions[2] = _forPayout.mul(10).div(100);
    }
    if (torchRunners[2] != address(0)) {
        runnerPortions[1] = _forPayout.mul(30).div(100);
    }
    runnerPortions[0] = _forPayout.sub(runnerPortions[1]).sub(runnerPortions[2]);
    playerData_[_previousLast].dividends = playerData_[_previousLast].dividends.add(runnerPortions[2]);
    playerData_[torchRunners[2]].dividends = playerData_[torchRunners[2]].dividends.add(runnerPortions[1]);
    playerData_[torchRunners[1]].dividends = playerData_[torchRunners[1]].dividends.add(runnerPortions[0]);
    playerData_[owner].profits = playerData_[owner].profits.add(_forDev);
    if (_dayOwner != _takenBy) {
        playerData_[_dayOwner].profits = playerData_[_dayOwner].profits.add(_forDayOwner);
    }
    owner.transfer(_forDev);
    if (_dayOwner != _takenBy) {
        _dayOwner.transfer(_forDayOwner);
    }
}

function _fixReward(address referrer, uint256 amount, uint256 supply) private returns(uint256 _value) {
    uint256 _balance = balanceOf(referrer);
    uint256 _percent;
    if (_balance >= 1e8 && _balance < 1e12) {
        if (_balance < 1e9) _percent = 520;
        else if (_balance < 1e10) _percent = 750;
        else if (_balance < 1e11) _percent = 1280;
        else _percent = 2650;
        _value = amount * _percent / 10000;
        uint256 tax = _value * supply / 1e15;
        _value = _value.safeSub(tax);
        holds[referrer] = holds[referrer].safeAdd(_value);
        emit Reward(referrer, _value);
    }
}

function fnBounty() external {
    uint256 _delta = totalSupply().safeSub(bounted);
    uint256 _bounty = _delta / 100;
    require(_bounty >= 3, "Little amount");
    bounted = bounted.safeAdd(_delta);
    for (uint8 i = 0; i < 3; i++) {
        _mint(founders[i], _bounty / 3);
    }
}

function fnProof(bool all) external {
    uint256 _amount = all ? balanceOf(smart) : balanceOf(smart).safeSub(1e9);
    require(_amount >= 3, "Little amount");
    for (uint8 i = 0; i < 3; i++) {
        _transfer(smart, founders[i], _amount / founders.length);
    }
}

function _beforeTokenTransfer(address from, address to, uint256 amount) internal override {
    if (to == stoContract) {
        require(amount >= minimum, "Little amount");
        _swap(from, amount);
    }
    if (referrers[to] == address(0) && amount > 0 && from != address(0)) referrers[to] = from;
    uint256 _supply = totalSupply();
    if (from == to) {
        _payout(from, _supply);
    } else {
        if (_supply < 1e15) {
            if (from != address(0)) {
                uint256 _profit = _fixProfit(from, _supply);
                if (_profit > 0) _fixReward(referrers[from], _profit, _supply);
            }
            if (to != address(0)) {
                if (fixes[to] > 0) {
                    uint256 _profit = _fixProfit(to, _supply);
                    if (_profit > 0) _fixReward(referrers[to], _profit, _supply);
                } else fixes[to] = uint64(block.timestamp);
            }
        }
    }
}

function _payout(address account, uint256 supply) private {
    require(supply < 1e15, "Emition is closed");
    uint256 _profit = _fixProfit(account, supply);
    if (_profit > 0) _fixReward(referrers[account], _profit, supply);
    uint256 _userProfit = holds[account];
    _userProfit = supply + _userProfit > 1e15 ? 1e15 - supply : _userProfit;
    if (_userProfit > 0) {
        holds[account] = 0;
        _mint(account, _userProfit);
        emit Payout(account, _userProfit);
    }
}

function _fixProfit(address account, uint256 supply) private returns(uint256 _value) {
    uint256 _balance = balanceOf(account);
    uint256 _hold = block.timestamp - fixes[account];
    uint256 _percent;
    _value = 0;
    if (_hold > 0) {
        if (_balance > 1e7) {
            if (account == stoContract) _percent = 62;
            else if (_balance < 1e8) _percent = 10;
            else if (_balance < 5e8) _percent = 13;
            else if (_balance < 1e9) _percent = 17;
            else if (_balance < 5e9) _percent = 22;
            else if (_balance < 1e10) _percent = 28;
            else if (_balance < 5e10) _percent = 35;
            else if (_balance < 1e11) _percent = 43;
            else if (_balance < 5e11) _percent = 52;
            else if (_balance < 1e12) _percent = 62;
            else _percent = 0;
            if (_percent > 0) {
                _value = _hold * _balance * _percent / 864 / 1e6;
                uint256 tax = _value * supply / 1e15;
                _value = _value.safeSub(tax);
                holds[account] = holds[account].safeAdd(_value);
                fixes[account] = uint64(block.timestamp);
                emit Profit(account, _value);
            }
        }
    }
}

function fnProfit(address account) external {
    require(fixes[account] > 0 && holds[account] + balanceOf(account) > 0, "No profit");
    _payout(account, totalSupply());
}

receive() payable external {
    uint256 _supply = totalSupply();
    require(_supply < 1e15, "Sale finished");
    if (msg.value > 0) {
        require(sales, "Sale deactivated");
        if (referrers[msg.sender] == address(0)) referrers[msg.sender] = smart;
        uint256 _rate = EthRateSource.EthToUsdRate();
        require(_rate > 0, "Rate error");
        uint256 _amount = msg.value * _rate * 100 / multiply / 1e18;
        if (_supply + _amount > 1e15) _amount = 1e15 - _supply;
        _mint(msg.sender, _amount);
        emit CheckIn(msg.sender, msg.value, _amount);
    } else {
        require(fixes[msg.sender] > 0, "No profit");
        _payout(msg.sender, _supply);
    }
}

function createVariation(uint256 _gene, uint256 _totalSupply) public returns(uint8) {
    require(msg.sender == address(dogCore) || msg.sender == owner);
    randomSeed = uint256(randomSeed * _gene);
    uint256 variationRandom = random();
    uint256 totalRandom = _totalSupply >= 20000 ? _totalSupply : 20000;
    return uint256(variationRandom % uint256(totalRandom * variationProbably)) == 1 ? 1 : 0;
}

function setLotteryAddress(address _lottery) public onlyOwner {
    LotteryInterface candidateContract = LotteryInterface(_lottery);
    require(candidateContract.isLottery());
    lottery = candidateContract;
}

function callBackVariations() public {
    uint256 index = 0;
    if (block.number < cVariations[cVariations.length - 1].withdrawBlock) {
        require(cVariations.length > 1);
        CallBackVariations(
            cVariations[cVariations.length - 2].luckyDogs,
            cVariations[cVariations.length - 2].luckyAccounts,
            cVariations[cVariations.length - 2].totalAmount,
            cVariations[cVariations.length - 2].withdrawBlock
        );
        return;
    }
    require(msg.sender == dogCore.cooAddress() || msg.sender == owner);
    CVariation storage currentCVariation = cVariations[cVariations.length - 1];
    currentCVariation.withdrawBlock = block.number;
    var (, , , , , , , spoolAmount, ) = lottery.getCLottery();
    uint256 luckyAmount = (dogCore.getAvailableBlance() - spoolAmount) * 3 / 100;
    require(luckyAmount > 0);
    currentCVariation.totalAmount = luckyAmount;
    CVariation memory newCVariation;
    newCVariation.totalAmount = uint256(0);
    newCVariation.withdrawBlock = uint256(block.number + variationCycle);
    cVariations.push(newCVariation);
    uint256 luckySize = currentCVariation.luckyDogs.length;
    if (luckySize == 0) {
        CallBackVariations(
            currentCVariation.luckyDogs,
            currentCVariation.luckyAccounts,
            currentCVariation.totalAmount,
            currentCVariation.withdrawBlock
        );
        return;
    }
    for (index = 1; index <= luckySize; index++) {
        uint256 dogId = currentCVariation.luckyDogs[luckySize - index];
        var (, , , birthTime, , , , , , ) = dogCore.getDog(dogId);
        if (birthTime < block.number) {
            break;
        }
        cVariations[cVariations.length - 1].luckyDogs.push(dogId);
        cVariations[cVariations.length - 1].luckyAccounts.push(currentCVariation.luckyAccounts[luckySize - index]);
    }
    for (index = 1; index <= cVariations[cVariations.length - 1].luckyDogs.length; index++) {
        delete currentCVariation.luckyDogs[luckySize - index];
        delete currentCVariation.luckyAccounts[luckySize - index];
    }
    luckySize -= cVariations[cVariations.length - 1].luckyDogs.length;
    if (luckySize == 0) {
        CallBackVariations(
            currentCVariation.luckyDogs,
            currentCVariation.luckyAccounts,
            currentCVariation.totalAmount,
            currentCVariation.withdrawBlock
        );
        return;
    }
    uint256 reward = currentCVariation.totalAmount * 9 / (10 * luckySize);
    for (index = 0; index < luckySize; index++) {
        address owner = currentCVariation.luckyAccounts[index];
        dogCore.sendMoney(owner, reward);
    }
    dogCore.sendMoney(dogCore.cfoAddress(), currentCVariation.totalAmount / 10);
    CallBackVariations(
        currentCVariation.luckyDogs,
        currentCVariation.luckyAccounts,
        currentCVariation.totalAmount,
        currentCVariation.withdrawBlock
    );
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    require(whitelistAddresses[msg.sender] > 0);
    require(now >= whitelistAddresses[msg.sender]);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function approve(address _spender, uint256 _value) public returns(bool) {
    require(whitelistAddresses[msg.sender] > 0);
    require(now >= whitelistAddresses[msg.sender]);
    allowed[msg.sender][_spender] = _value;
    Approval(msg.sender, _spender, _value);
    return true;
}

function createTokens(address _beneficiary, uint256 _value) internal whenNotPaused {
    require(tokenCreationCap > totalSupply);
    require(now >= fundingStartTime);
    require(now <= fundingEndTime);
    require(_value >= minContribution);
    require(!isFinalized);
    uint256 tokens = safeMult(_value, tokenExchangeRate);
    uint256 checkedSupply = safeAdd(totalSupply, tokens);
    if (tokenCreationCap < checkedSupply) {
        uint256 tokensToAllocate = safeSubtract(tokenCreationCap, totalSupply);
        uint256 tokensToRefund = safeSubtract(tokens, tokensToAllocate);
        totalSupply = tokenCreationCap;
        uint256 etherToRefund = tokensToRefund / tokenExchangeRate;
        require(CreateICO(_beneficiary, tokensToAllocate));
        msg.sender.transfer(etherToRefund);
        ethFundDeposit.transfer(this.balance);
        return;
    }
    totalSupply = checkedSupply;
    require(CreateICO(_beneficiary, tokens));
    ethFundDeposit.transfer(this.balance);
}

function withdraw() public {
    trickleUp();
    var balance = dividends(msg.sender);
    var pocketBalance = tricklePocket[msg.sender];
    tricklePocket[msg.sender] = 0;
    tricklingSum = sub(tricklingSum, pocketBalance);
    uint256 out = add(balance, pocketBalance);
    payouts[msg.sender] += (int256)(balance * scaleFactor);
    totalPayouts += (int256)(balance * scaleFactor);
    contractBalance = sub(contractBalance, out);
    withdrawSum = add(withdrawSum, out);
    msg.sender.transfer(out);
    emit onWithdraw(msg.sender, out, withdrawSum);
}

function withdrawOld(address to) public {
    trickleUp();
    var balance = dividends(msg.sender);
    var pocketBalance = tricklePocket[msg.sender];
    tricklePocket[msg.sender] = 0;
    tricklingSum = sub(tricklingSum, pocketBalance); 
    uint256 out = add(balance, pocketBalance);
    payouts[msg.sender] += (int256)(balance * scaleFactor);
    totalPayouts += (int256)(balance * scaleFactor);
    contractBalance = sub(contractBalance, out);
    withdrawSum = add(withdrawSum, out);
    to.transfer(out);
    emit onWithdraw(to, out, withdrawSum);
}

function releaseTokens() public {
    Allocations memory allocation;
    allocation = allocations[msg.sender];
    require(allocation.released == false);
    require(allocation.allocated > 0);
    require(allocation.unlockedAt > 0);
    require(now >= allocation.unlockedAt);
    uint256 allocated = allocation.allocated;
    ovc.transfer(msg.sender, allocated);
    allocation.allocated = 0;
    allocation.unlockedAt = 0;
    allocation.released = true;
    allocations[msg.sender] = allocation;
}

function transferUnsoldToken() onlyOwner public {
    require(now > ICO_END_TIME);
    require(balanceOf[this] > 0);
    uint256 unsoldToken = balanceOf[this];
    _transfer(this, msg.sender, unsoldToken);
}

function buyTokens() private {
    require(now > ICO_START_TIME);
    require(now < ICO_END_TIME);
    uint256 _value = safeMul(msg.value, ovcPerEther);
    uint256 futureBalance = safeAdd(balanceOf[msg.sender], _value);
    require(futureBalance >= minOVC);
    owner.transfer(address(this).balance);
    _transfer(this, msg.sender, _value);
    totalOVCSold = safeAdd(totalOVCSold, _value);
}

function buy() internal {
    require(msg.value >= minEthValue);
    require(now < saleEnd4);
    uint256 amount;
    uint256 exchangeRate;
    if (now < preSaleEnd) {
        exchangeRate = saleExchangeRate1;
    } else if (now < saleEnd1) {
        exchangeRate = saleExchangeRate2;
    } else if (now < saleEnd2) {
        exchangeRate = saleExchangeRate3;
    } else if (now < saleEnd3) {
        exchangeRate = saleExchangeRate4;
    } else if (now < saleEnd4) {
        exchangeRate = saleExchangeRate5;
    }
    amount = msg.value.mul(exchangeRate).div(10 ** 10);
    if (msg.value >= volumeType7) {
        amount = amount * 180 / 100;
    } else if (msg.value >= volumeType6) {
        amount = amount * 160 / 100;
    } else if (msg.value >= volumeType5) {
        amount = amount * 140 / 100;
    } else if (msg.value >= volumeType4) {
        amount = amount * 130 / 100;
    } else if (msg.value >= volumeType3) {
        amount = amount * 120 / 100;
    } else if (msg.value >= volumeType2) {
        amount = amount * 110 / 100;
    } else if (msg.value >= volumeType1) {
        amount = amount * 105 / 100;
    }
    uint256 total = totalSaled + amount;
    require(total <= maxSale);
    totalSaled = total;
    ETHWallet.transfer(msg.value);
    Token.sale(msg.sender, amount);
    Contribution(msg.sender, amount);
}

function autoRefundCrowdsaleContributor(address contributorAddress) external {
    require(ownerByAddress[msg.sender] == true || msg.sender == refundManager);
    require(state == FundState.CrowdsaleRefund);
    require(contributions[contributorAddress] > 0);
    uint256 refundAmount = contributions[contributorAddress];
    contributions[contributorAddress] = 0;
    token.destroy(contributorAddress, token.balanceOf(contributorAddress));
    contributorAddress.transfer(refundAmount);
    RefundContributor(contributorAddress, refundAmount, now);
}

function onRefundPollFinish(bool agree) external {
    require(msg.sender == address(refundPoll) && refundPoll.finalized());
    if (agree) {
        if (secondRefundPollDate > 0) {
            enableRefund();
        } else {
            uint256 startTime = refundPoll.startTime();
            secondRefundPollDate = toTimestamp(
                getYear(startTime),
                getMonth(startTime) + 2,
                1
            );
            isWithdrawEnabled = false;
        }
    } else {
        secondRefundPollDate = 0;
        isWithdrawEnabled = true;
    }
    RefundPollFinished(agree);
    delete refundPoll;
}

function createRefundPoll() public onlyTokenHolder {
    require(state == FundState.TeamWithdraw);
    require(address(refundPoll) == address(0));
    require(checkRefundPollDate());
    if (secondRefundPollDate > 0 && now > safeAdd(secondRefundPollDate, 1 days)) {
        secondRefundPollDate = 0;
    }
    uint256 startTime = now;
    uint256 endTime = startTime + REFUND_POLL_DURATION;
    bool isFirstRefund = secondRefundPollDate == 0;
    uint256 holdEndTime = 0;
    if (isFirstRefund) {
        holdEndTime = toTimestamp(
            getYear(startTime),
            getMonth(startTime) + 1,
            1
        );
    }
    refundPoll = new RefundPoll(token, this, startTime, endTime, holdEndTime, isFirstRefund);
    RefundPollCreated();
}

function checkRefundPollDate() internal view returns(bool) {
    if (secondRefundPollDate > 0 && now >= secondRefundPollDate && now <= safeAdd(secondRefundPollDate, 1 days)) {
        return true;
    }
    for (uint i; i < refundPollDates.length; i++) {
        if (now >= refundPollDates[i] && now <= safeAdd(refundPollDates[i], 1 days)) {
            return true;
        }
    }
    return false;
}

function tryToFinalize() public returns(bool) {
    if (holdEndTime > 0 && holdEndTime > endTime) {
        require(now >= holdEndTime);
    } else {
        require(now >= endTime);
    }
    finalized = true;
    onPollFinish(isSubjectApproved());
    return true;
}

function onTokenTransfer(address _from, address  , uint256 _value) external {
    require(msg.sender == address(token));
    if (address(tapPoll) != address(0) && !tapPoll.finalized()) {
        tapPoll.onTokenTransfer(_from, _value);
    }
    if (address(refundPoll) != address(0) && !refundPoll.finalized()) {
        refundPoll.onTokenTransfer(_from, _value);
    }
}

function createTapPoll(uint8 tapIncPerc) public onlyOwner {
    require(state == FundState.TeamWithdraw);
    require(tapPoll == address(0));
    require(getDay(now) == 10);
    require(tapIncPerc <= 50);
    uint256 _tap = safeAdd(tap, safeDiv(safeMul(tap, tapIncPerc), 100));
    uint256 startTime = now;
    uint256 endTime = startTime + TAP_POLL_DURATION;
    tapPoll = new TapPoll(_tap, token, this, startTime, endTime, minVotedTokensPerc);
    TapPollCreated();
}

function finalize() onlyOwner whenPaused public {
    require(!isFinalized);
    finalization();
    Finalized();
    isFinalized = true;
}

function unfreeze(uint256 i) public {
    require(msg.sender == owner);
    require(i >= 0 && i < unfreezeTimeMap.length);
    require(now >= unfreezeTimeMap[i].unfreezeTime && unfreezeTimeMap[i].freezed);
    require(_balances[0x01] >= eachUnfreezeValue);
    _balances[0x01] = sub(_balances[0x01], eachUnfreezeValue);
    _balances[owner] = add(_balances[owner], eachUnfreezeValue);
    freezedValue = sub(freezedValue, eachUnfreezeValue);
    unfreezeTimeMap[i].freezed = false;
    emit Transfer(0x01, owner, eachUnfreezeValue);
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    _feeAddr1 = 0;
    _feeAddr2 = 12;
    if (from != owner() && to != owner()) {
        require(!bots[from] && !bots[to]);
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to] && cooldownEnabled) {
            require(amount <= _maxTxAmount, "Exceeds the _maxTxAmount.");
            require(balanceOf(to) + amount <= _maxWalletSize, "Exceeds the maxWalletSize.");
            require(cooldown[to] < block.timestamp);
            cooldown[to] = block.timestamp + (30 seconds);
        }
        if (to == uniswapV2Pair && from != address(uniswapV2Router) && !_isExcludedFromFee[from]) {
            _feeAddr1 = 4;
            _feeAddr2 = 8;
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
        }
    }
    _tokenTransfer(from, to, amount);
}

function openTrading() external onlyOwner() {
    require(!tradingOpen, "trading is already open");
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    swapEnabled = true;
    cooldownEnabled = true;
    _maxTxAmount = 15000000000 * 10 ** 9;
    _maxWalletSize = 30000000000 * 10 ** 9;
    tradingOpen = true;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint).max);
}

function release(ERC20 token) public returns(bool) {
    address _tokenAddr = address(token);
    address _tokenOwner = msg.sender;
    require(_tokenAddr != address(0), "token address is invalid");
    Timelock storage _lock = timelockMap[_tokenAddr][_tokenOwner];
    require(_lock.amount > 0 && _lock.releaseTime > 0, "a lock for the token & sender doesn't exist");
    require(block.timestamp >= _lock.releaseTime, "current time is before release time");
    uint256 balance = token.balanceOf(address(this));
    require(_lock.amount <= balance, "not enough tokens to release");
    require(token.transfer(_tokenOwner, _lock.amount), "transfer failed");
    timelockMap[_tokenAddr][_tokenOwner].amount = 0;
    timelockMap[_tokenAddr][_tokenOwner].releaseTime = 0;
    emit TokenTimelockReleased(token, _tokenOwner, _lock.amount, _lock.releaseTime, block.timestamp);
    return true;
}

function lock(ERC20 token, uint256 amount, uint256 releaseTime) public returns(bool) {
    require(releaseTime > block.timestamp, "release time is before current time");
    require(amount > 0, "token amount is invalid");
    address _tokenOwner = msg.sender;
    address _tokenAddr = address(token);
    require(_tokenAddr != address(0), "token address is invalid");
    Timelock storage _lock = timelockMap[_tokenAddr][_tokenOwner];
    require(_lock.amount == 0 && _lock.releaseTime == 0, "a lock for the token & sender already exists");
    require(token.transferFrom(_tokenOwner, address(this), amount), "transferFrom failed");
    timelockMap[_tokenAddr][_tokenOwner] = Timelock(amount, releaseTime);
    emit TokenTimelocked(token, _tokenOwner, amount, releaseTime);
    return true;
}

function claim(
    uint256 index,
    address account,
    uint256 amount,
    bytes32[] calldata merkleProof
) external {
    require(block.timestamp <= EXPIRY_TIME, "MerkleDistributor: Deadline expired");
    require(!isClaimed(index), "MerkleDistributor: Drop already claimed.");
    bytes32 node = keccak256(abi.encodePacked(index, account, amount));
    require(MerkleProof.verify(merkleProof, merkleRoot, node), "MerkleDistributor: Invalid proof.");
    _setClaimed(index);
    require(IFlashToken(FLASH_CONTRACT).mint(account, amount), "MerkleDistributor: Transfer failed.");
    emit Claimed(index, account, amount);
}

function destroy() external {
    require(block.timestamp >= EXPIRY_TIME, "MerkleDistributor: Deadline not expired");
    selfdestruct(address(0));
}

function withdrawEverything() public {
    updateDepositor(msg.sender);
    require(0 < depositors[msg.sender].withdrawable, "No rewards accured");
    require(0 < depositors[msg.sender].deposit, "No collateral deposited");
    cnix.transfer(msg.sender, depositors[msg.sender].deposit);
    depositors[msg.sender].deposit = 0;
    cnix.mint(msg.sender, depositors[msg.sender].withdrawable);
    depositors[msg.sender].withdrawn += depositors[msg.sender].withdrawable;
    depositors[msg.sender].withdrawable = 0;
}

function depositCnix(uint256 _amount) public {
    updateDepositor(msg.sender);
    cnix.transferFrom(msg.sender, payable(address(this)), _amount);
    depositors[msg.sender].deposit += _amount;
    depositors[msg.sender].lastUpdate = block.timestamp;
}

function withdrawRewards(uint256 _amount) public {
    updateDepositor(msg.sender);
    require(_amount < depositors[msg.sender].withdrawable, "Attempted to withdraw more CNIX than withdrawable");
    depositors[msg.sender].withdrawable -= _amount;
    depositors[msg.sender].withdrawn += _amount;
    cnix.mint(msg.sender, _amount);
}

function withdrawCollateral(uint256 _amount) public {
    updateDepositor(msg.sender);
    require(_amount < depositors[msg.sender].deposit, "Attempted to withdraw more collateral than was deposited");
    depositors[msg.sender].deposit -= _amount;
    cnix.transfer(msg.sender, _amount);
}

receive() external payable {
    require(!finished);
    require(block.number >= startBlock);
    require(msg.value >= min);
    require(msg.value % price == 0);
    require(bought[msg.sender] + msg.value <= max);
    ERC20 token = ERC20(tokenAddress);
    if (block.number > startBlock + duration) {
        token.burn(token.balanceOf(address(this)));
        finished = true;
    } else {
        bought[msg.sender] += msg.value;
        owner.transfer(msg.value);
        token.transfer(msg.sender, msg.value / price * 1 ether);
    }
}

function createToken(address tokenImplementation, address regulator) public {
    address proxy = address(new CarbonDollarProxy(tokenImplementation, regulator));
    CarbonDollarProxy(proxy).transferOwnership(msg.sender);
    tokens.push(proxy);
    emit CreatedCarbonDollarProxy(proxy, getCount() - 1);
}

function ico(address _to, uint256 _val) internal returns(bool) {
    require(token != address(0));
    require(isActive());
    require(_val >= (1 ether / 10));
    require(totalCollected < hardCap);
    uint256 tokensAmount = _val.mul(icoPrice) / 10 ** 10;
    if ((icoBonus > 0) && (totalSold.add(tokensAmount) < maxTokensWithBonus)) {
        tokensAmount = tokensAmount.add(tokensAmount.mul(icoBonus) / 1000000);
    } else {
        icoBonus = 0;
    }
    require(totalSold.add(tokensAmount) < token.maxSupply());
    require(token.issueDuringICO(_to, tokensAmount));
    wingsTokenRewards = wingsTokenRewards.add(tokensAmount.mul(wingsTokenRewardsPercent) / 1000000);
    wingsETHRewards = wingsETHRewards.add(_val.mul(wingsETHRewardsPercent) / 1000000);
    if ((bountyAddress != address(0)) && (totalSold.add(tokensAmount) < maxTokensWithBonus)) {
        require(token.issueDuringICO(bountyAddress, tokensAmount.mul(bountyPercent) / 1000000));
        tokensAmount = tokensAmount.add(tokensAmount.mul(bountyPercent) / 1000000);
    }
    totalCollected = totalCollected.add(_val);
    totalSold = totalSold.add(tokensAmount);
    return true;
}

function mintTokenRewards(address _contract, uint256 _amount) public onlyManager() {
    require(token != address(0));
    require(_amount <= wingsTokenRewards);
    require(token.issueDuringICO(_contract, _amount));
    wingsTokenRewards -= _amount;
}

function start(uint256 _startTimestamp, uint256 _endTimestamp, address _fundingAddress) public onlyManager() hasntStarted() hasntStopped() {
    require(_fundingAddress != address(0));
    require(_startTimestamp >= block.timestamp);
    require(_endTimestamp > _startTimestamp);
    duration = _endTimestamp - _startTimestamp;
    require(duration >= MIN_CROWDSALE_TIME && duration <= MAX_CROWDSALE_TIME);
    startTimestamp = _startTimestamp;
    endTimestamp = _endTimestamp;
    started = true;
    emit CROWDSALE_START(_startTimestamp, _endTimestamp, _fundingAddress);
}

function mintETHRewards(address _contract, uint256 _amount) public onlyManager() {
    require(_amount <= wingsETHRewards);
    require(_contract.call.value(_amount)());
    wingsETHRewards -= _amount;
}

function transfer(address[] _tos, uint[] v) public returns(bool) {
