        totalFEG,
        bmul(BASE, 25),
        _totalSupply,
        bmul(BASE, 25),
        tokensToStake,
        0
    );
    require(IERC20(FEG).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user for locking");
    _mint(poolAmountOut);
    IERC20(poolShares).transfer(msg.sender, poolAmountOut);
