function changePrice(StageStorage storage self, uint8 _stage, uint256 _tokenPrice) internal {
    require(self.stages[_stage].deadline > now);
    self.stages[_stage].tokenPrice = _tokenPrice;
}

function changeDeadline(StageStorage storage self, uint8 _stage, uint256 _deadline) internal {
    require(self.stages[_stage].deadline > now);
    self.stages[_stage].deadline = _deadline;
}

function getStage(StageStorage storage self) public view returns(uint8 stage) {
    uint8 thisStage = self.stageCount + 1;
    for (uint8 i = 0; i < thisStage; i++) {
        if (now <= self.stages[i].deadline) {
            return i;
        }
    }
    return thisStage;
}

function validPurchase(uint256 _tokens) internal view returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    return withinPeriod && nonZeroPurchase;
}

function extendStart(uint256 _newStart) external onlyOwner {
    require(_newStart > startTime);
    require(_newStart > now);
    require(now < startTime);
    uint256 difference = _newStart - startTime;
    uint256 oldStart = startTime;
    startTime = _newStart;
    endTime = endTime + difference;
    for (uint8 i = 0; i < 4; i++) {
        uint256 temp = stages.stages[i].deadline;
        temp = temp + difference;
        stages.changeDeadline(i, temp);
    }
    ExtendedStart(oldStart, _newStart);
}

function Crowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet, PickToken _token) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != address(0));
    token = _token;
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
    transferOwnership(_wallet);
}

function refundParticipant(address participant, uint256 _stage1, uint256 _stage2, uint256 _stage3, uint256 _stage4) external onlyOwner {
    require(balanceOf[participant] > 0);
    uint256 balance = balanceOf[participant];
    uint256 tokens = tokenBalanceOf[participant];
    balanceOf[participant] = 0;
    tokenBalanceOf[participant] = 0;
    refundable[participant] = balance;
    weiRaised = weiRaised.sub(balance);
    tokensSent = tokensSent.sub(tokens);
    token.reclaimAllAndBurn(participant);
    blacklist[participant] = true;
    AddedToBlacklist(participant, now);
    stages.refundParticipant(_stage1, _stage2, _stage3, _stage4);
    TokensReclaimed(participant, tokens, now);
}

function releaseTokens(uint256 _bounty, uint256 _founders) onlyOwner external {
    require(_bounty > 0 || tokensSent == hardCap);
    require(_founders > 0 || tokensSent == hardCap);
    burnFoundersTokens(_bounty, _founders);
    token.releaseTokenTransfer();
    canWithdraw = true;
    TokensReleased(msg.sender, now, _bounty, _founders);
}

function preallocate(address receiver, uint tokens, uint weiPrice) internal {
    uint decimals = token.decimals();
    uint tokenAmount = tokens * 10 ** decimals;
    uint weiAmount = weiPrice * tokens;
    presaleWeiRaised = presaleWeiRaised.add(weiAmount);
    tokensSent = tokensSent.add(tokenAmount);
    tokenBalanceOf[receiver] = tokenBalanceOf[receiver].add(tokenAmount);
    presaleBalanceOf[receiver] = presaleBalanceOf[receiver].add(weiAmount);
    produceTokens(receiver, weiAmount, tokenAmount);
}

function successfulWithdraw() external onlyOwner stopInEmergency {
    require(hasEnded());
    require(canWithdraw);
    require(tokensSent > softCap);
    uint256 withdrawalAmount = weiRaised.sub(withdrawn);
    withdrawn = withdrawn.add(withdrawalAmount);
    beneficiary.transfer(withdrawalAmount);
    BeneficiaryWithdrawal(msg.sender, withdrawalAmount, now);
}

function collectRefund() external {
    require(refundable[msg.sender] > 0);
    require(refunded[msg.sender] == false);
    uint256 theirwei = refundable[msg.sender];
    refundable[msg.sender] = 0;
    refunded[msg.sender] == true;
    msg.sender.transfer(theirwei);
    RefundCollected(msg.sender, now);
}

function setPreallocations() external onlyOwner onlyOnce(preallocated) {
    preallocate(buyer, 1250000, 10000000000);
    preallocate(founders, 1777777, 0);
    preallocate(bounty, 444445, 0);
    preallocated = true;
}

function getCard() public view returns(uint256 _price, address _owner) {
    if (currentRound() > purchaseRound) {
        _price = STARTING_PRICE;
        _owner = owner;
    } else {
        _price = cardPrice;
        _owner = cardOwner;
    }
}

function _updateRecord(address account) private returns(bool success) {
    LockRecord[] memory tempRecords = records[account];
    uint256 unlockedTokenCount = 0;
    for (uint256 i = 0; i < tempRecords.length; i++) {
        if (tempRecords[i].lockingPeriod < now && tempRecords[i].isUnlocked == false) {
            unlockedTokenCount = unlockedTokenCount.add(tempRecords[i].tokens);
            tempRecords[i].isUnlocked = true;
            records[account][i] = LockRecord(tempRecords[i].lockingPeriod, tempRecords[i].tokens, tempRecords[i].isUnlocked);
        }
    }
    _unlockedTokens[account] = _unlockedTokens[account].add(unlockedTokenCount);
    return true;
}

function _contribute() private returns(bool) {
    address contributor = _msgSender();
    uint256 contribution = msg.value;
    require(_checkContribution(contribution),
        "error: must comply with contribution requirements");
    uint256 processedContribution;
    uint256 excessContribution;
    uint256 tokens;
    if (_isFirstMover()) {
        processedContribution = _FIRST_CEILING.sub(getFunds());
        if (_isExcessive(contribution, processedContribution)) {
            excessContribution = contribution.sub(processedContribution);
            tokens = (processedContribution.mul(_fr)).add((excessContribution.mul(_rr)).div(_PRECISION));
            _token.transfer(contributor, tokens);
            _funds = _funds.add(contribution);
        } else {
            tokens = (contribution.mul(_fr));
            _token.transfer(contributor, tokens);
            _funds = _funds.add(contribution);
        }
    } else {
        processedContribution = _TOTAL_CEILING.sub(getFunds());
        if (_isExcessive(contribution, processedContribution)) {
            excessContribution = contribution.sub(processedContribution);
            tokens = (processedContribution.mul(_rr)).div(_PRECISION);
            _token.transfer(contributor, tokens);
            _msgSender().transfer(excessContribution);
            _funds = _funds.add(processedContribution);
            emit Contributed(contributor, processedContribution);
        }
        tokens = (contribution.mul(_rr)).div(_PRECISION);
        _token.transfer(contributor, tokens);
        _funds = _funds.add(contribution);
    }
    emit Contributed(contributor, contribution);
    return true;
}

function finalize() external returns(bool) {
    require(_isOver(),
        "error: must be over");
    require(_isLocked(),
        "error: must be locked");
    _vault();
    _boost();
    emit Finalized(_time());
    return true;
}

function _isCompliant(address account, uint256 amount) private view returns(bool) {
    if (balanceOf(account).add(amount) >= getRequirement()) {
        return true;
    } else {
        return false;
    }
}

function _isActive() private view returns(bool) {
    if (getOver() > _time() || getFunds() < _TOTAL_CEILING) {
        return true;
    } else {
        return false;
    }
}

function _checkChallenger(address account, uint256 amount) private {
    if (_isChallenger(account)) {
        if (balanceOf(account).sub(amount) < getChallenge(account)) {
            uint256 challenged = getChallenge(account);
            _challenges = _challenges.sub(challenged);
            delete _challengers[account].acceptance;
            delete _challengers[account].challenge;
            emit Forfeited(account, challenged);
        }
    }
}

function _isExcessive(uint256 amount, uint256 ceiling) private pure returns(bool) {
    if (amount > ceiling) {
        return true;
    } else {
        return false;
    }
}

function _isEligible(address account, uint256 amount) private view returns(bool) {
    if (balanceOf(account) >= amount) {
        return true;
    } else {
        return false;
    }
}

function reward() external returns(bool) {
    uint256 prizes = getPrizesTotal();
    require(prizes > 0,
        "error: must be prizes available");
    address account = _msgSender();
    require(getReward(account) > 0,
        "error: must be worthy of a reward");
    uint256 amount = getReward(account);
    if (_isExcessive(amount, prizes)) {
        uint256 excess = amount.sub(prizes);
        amount = amount.sub(excess);
        _challengers[account].acceptance = _time();
        _prizes = _prizes.sub(amount);
        _mint(account, amount);
        emit Rewarded(account, amount);
    } else {
        _challengers[account].acceptance = _time();
        _prizes = _prizes.sub(amount);
        _mint(account, amount);
        emit Rewarded(account, amount);
    }
    return true;
}

function _isElastic() private view returns(bool) {
    if (getContributorsTotal() <= getContributorsLimit() && getContributorsTotal() > 0) {
        return true;
    } else {
        return false;
    }
}

function _isNotUnique(address account) private view returns(bool) {
    if (balanceOf(account) > getRequirement()) {
        return true;
    } else {
        return false;
    }
}

function _isOver() private view returns(bool) {
    if (getOver() <= _time() || getFunds() >= _TOTAL_CEILING) {
        return true;
    } else {
        return false;
    }
}

function _isLaunched() private view returns(bool) {
    if (getLaunch() > 0) {
        return true;
    } else {
        return false;
    }
}

function getPeriod(address account) public view returns(uint256) {
    if (getAcceptance(account) > 0) {
        uint256 period = _time().sub(_challengers[account].acceptance);
        uint256 term = getTerm();
        if (period >= term) {
            return period.div(term);
        } else {
            return 0;
        }
    } else {
        return 0;
    }
}

function _isUnique(address account) private view returns(bool) {
    if (balanceOf(account) < getRequirement()) {
        return true;
    } else {
        return false;
    }
}

function _isNotCompliant(address account, uint256 amount) private view returns(bool) {
    if (balanceOf(account).sub(amount) < getRequirement()) {
        return true;
    } else {
        return false;
    }
}

function _isContributor(address account) private view returns(bool) {
    if (balanceOf(account) >= getRequirement()) {
        return true;
    } else {
        return false;
    }
}

function transferToContract(address _to, uint256 _value, bytes _data) internal returns(bool) {
    require(balances[msg.sender] >= _value);
    require(vestingEnded(msg.sender));
    if (msg.sender != contractOwner) {
        ERC223ReceivingContract _tokenReceiver = ERC223ReceivingContract(_to);
        _tokenReceiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    emit Transfer(msg.sender, _to, _value, _data);
    return true;
}

function vestingEnded(address _user) public view returns(bool) {
    if (vestings[_user].endTime <= now) {
        return true;
    } else {
        return false;
    }
}

function unlock(uint256 _id) public {
    TokenTimeLockInfo memory lockInfo = locks[_id];
    delete locks[_id];
    require(lockInfo.amount > 0);
    require(lockInfo.unlockTime <= block.timestamp);
    Unlock(_id);
    require(
        lockInfo.token.transfer(
            lockInfo.beneficiary, lockInfo.amount));
}

function isPreviousStageFinalized() public returns(bool) {
    if (previousStageIsFinalized) {
        return true;
    }
    if (previousStage.isFinalized()) {
        previousStageIsFinalized = true;
    }
    return previousStageIsFinalized;
}

function updateCurrentStage() public returns(StageCrowdsale currentStage) {
    if (currentStageIndex < stages.length) {
        currentStage = stages[currentStageIndex];
        while (currentStage.isFinalized() && currentStageIndex + 1 < stages.length) {
            currentStage = stages[++currentStageIndex];
        }
    }
}

function addStageCrowdsale(address _stageCrowdsaleAddress) public onlyOwner {
    require(_stageCrowdsaleAddress != address(0));
    StageCrowdsale stageToBeAdded = StageCrowdsale(_stageCrowdsaleAddress);
    if (stages.length > 0) {
        require(stageToBeAdded.previousStage() != address(0));
        StageCrowdsale lastStage = stages[stages.length - 1];
        require(stageToBeAdded.openingTime() >= lastStage.closingTime());
    }
    stages.push(stageToBeAdded);
    emit StageAdded();
}

function proxyBuyTokens(address _beneficiary) public payable {
    uint256 weiAmount = msg.value;
    _preValidatePurchase(_beneficiary, weiAmount);
    uint256 tokens = _getTokenAmount(weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(tx.origin, _beneficiary, weiAmount, tokens);
    _updatePurchasingState(_beneficiary, weiAmount);
    _forwardFunds();
    _postValidatePurchase(_beneficiary, weiAmount);
}

function buyTokens(address _beneficiary) public payable validBuyCall(_beneficiary) hasCurrentStage {
    StageCrowdsale stage = updateCurrentStage();
    stage.proxyBuyTokens.value(msg.value)(_beneficiary);
    updateCurrentStage();
}

function withdraw() public {
    uint amount;
    require(now > end_date); 
    amount = holder_balance[msg.sender];
    holder_balance[msg.sender] = 0;
    msg.sender.transfer(amount);
}

function lockTokens(address _tokenExemption, address _tokenAddress, address _ownerAddress, uint256 _amount, uint256 _unlockedAtTime) public payable ReEntrancyGuard {
    bool takeFee = true;
    if (addressExemptFromFee[msg.sender] || (feeExemptToken[_tokenExemption] && (ERC20(_tokenExemption).balanceOf(msg.sender) >= tokenBalanceThreshold[_tokenExemption]))) {
        takeFee = false;
    }
    if (takeFee) require(msg.value == ethFeePerLock, "Fee amount invalid");
    require(_amount > 0, "Must be more than 0");
    require(ERC20(_tokenAddress).balanceOf(msg.sender) >= _amount, "Insuffecient balance");
    require(ERC20(_tokenAddress).transferFrom(msg.sender, address(this), _amount), "Transfer failed");
    uint256 _thisLockID = ++lockID;
    locksCreatedByAddress[msg.sender].push(_thisLockID);
    locksOwnedByAddress[_ownerAddress].push(_thisLockID);
    locksByTokenAddress[_tokenAddress].push(_thisLockID);
    Lock memory lock = Lock(_thisLockID, msg.sender, _tokenAddress, _ownerAddress, _amount, _unlockedAtTime, block.timestamp, false);
    tokenLocked[_thisLockID] = lock;
    emit TokensLocked(_tokenAddress, msg.sender, _ownerAddress, _amount, _unlockedAtTime);
}

function createVest(address _tokenExemption, address _tokenAddress, address[] calldata _vestOwnersAddresses, uint256 _totalAmount, uint256[] calldata _unlockTimes, uint256[] calldata _unlockAmounts) public payable ReEntrancyGuard {
    bool takeFee = true;
    if (addressExemptFromFee[msg.sender] || (feeExemptToken[_tokenExemption] && (ERC20(_tokenExemption).balanceOf(msg.sender) >= tokenBalanceThreshold[_tokenExemption]))) {
        takeFee = false;
    }
    uint256 feeCost = ethFeePerLock.mul(_vestOwnersAddresses.length);
    if (takeFee) require(msg.value == feeCost, "Fee amount invalid");
    require(_unlockTimes.length == _unlockAmounts.length, "Array sizes must match");
    uint256 _sumOfUnlockAmounts;
    for (uint256 i = 0; i < _unlockAmounts.length; i++) {
        _sumOfUnlockAmounts += _unlockAmounts[i];
    }
    uint256 _totalVestAmount = _sumOfUnlockAmounts.mul(_vestOwnersAddresses.length);
    require(_totalAmount > 0 && _totalAmount == _totalVestAmount, "Invalid amount input");
    require(ERC20(_tokenAddress).balanceOf(msg.sender) >= _totalAmount, "Insufficient balance");
    require(ERC20(_tokenAddress).transferFrom(msg.sender, address(this), _totalAmount), "Transfer failed");
    for (uint256 i = 0; i < _vestOwnersAddresses.length; i++) {
        for (uint256 j = 0; j < _unlockTimes.length; j++) {
            _lockTokens(msg.sender, _tokenAddress, _vestOwnersAddresses[i], _unlockAmounts[j], _unlockTimes[j]);
            emit TokensLocked(_tokenAddress, msg.sender, _vestOwnersAddresses[i], _unlockAmounts[j], _unlockTimes[j]);
        }
    }
}

function withdrawAllTokens(uint256 _lockID) public ReEntrancyGuard {
    require(block.timestamp >= tokenLocked[_lockID].unlockedAtTime, "Timed lock has not expired");
    require(msg.sender == tokenLocked[_lockID].ownerAddress, "Not authorized to withdraw");
    require(!tokenLocked[_lockID].hasWithdrawn, "Lock already withdrawn");
    require(ERC20(tokenLocked[_lockID].tokenAddress).transfer(msg.sender, tokenLocked[_lockID].amount), "Tokens not withdrawn");
    tokenLocked[_lockID].hasWithdrawn = true;
    emit TokensWithdrawn(_lockID, msg.sender, tokenLocked[_lockID].amount);
}

function extendLock(uint256 _lockID, uint256 _newUnlockTime) public ReEntrancyGuard {
    require(msg.sender == tokenLocked[_lockID].ownerAddress);
    require(_newUnlockTime > tokenLocked[_lockID].unlockedAtTime);
    uint256 previousUnlockAtTime = tokenLocked[_lockID].unlockedAtTime;
    tokenLocked[_lockID].unlockedAtTime = _newUnlockTime;
    emit LockExtended(_lockID, previousUnlockAtTime, _newUnlockTime);
}

function addToLock(uint256 _lockID, address _tokenAddress, uint256 _amount) public ReEntrancyGuard {
    require(_amount > 0, "Invalid amount");
    require(tokenLocked[_lockID].unlockedAtTime > block.timestamp, "Lock has expired");
    require(tokenLocked[_lockID].tokenAddress == _tokenAddress, "Token not held in lock");
    require(ERC20(_tokenAddress).balanceOf(msg.sender) >= _amount, "Insuffecient balance");
    require(ERC20(_tokenAddress).approve(address(this), _amount), "Must approve to transfer");
    require(ERC20(_tokenAddress).transferFrom(msg.sender, address(this), _amount), "Tokens not transferred");
    tokenLocked[_lockID].amount = tokenLocked[_lockID].amount.add(_amount);
    emit LockBalanceIncreased(msg.sender, _lockID, _amount);
}

function transferVestOwnerShip(uint256 _lockID, address _newOwner) external {
    require(msg.sender == tokenLocked[_lockID].ownerAddress, "Not owner");
    tokenLocked[_lockID].ownerAddress = _newOwner;
    emit LockOwnershipTransferred(_lockID, msg.sender, _newOwner);
}

function registerAndStake(uint _amount, address _referrer) external onlyUnregistered() whenActive() {
    require(msg.sender != _referrer, "Cannot refer self");
    require(registered[_referrer] || address(0x0) == _referrer, "Referrer must be registered");
    require(IERC20(lead).balanceOf(msg.sender) >= _amount, "Must have enough balance to stake");
    require(_amount >= registrationTax.add(minimumStakeValue), "Must send at least enough MANDOX to pay registration fee.");
    require(IERC20(lead).transferFrom(msg.sender, address(this), _amount), "Stake failed due to failed amount transfer.");
    uint finalAmount = _amount.sub(registrationTax);
    uint stakingTax = (stakingTaxRate.mul(finalAmount)).div(1000);
    if (_referrer != address(0x0)) {
        referralCount[_referrer]++;
        referralRewards[_referrer] = (referralRewards[_referrer]).add(stakingTax);
    }
    registered[msg.sender] = true;
    lastClock[msg.sender] = now;
    totalStaked = totalStaked.add(finalAmount).sub(stakingTax);
    stakes[msg.sender] = (stakes[msg.sender]).add(finalAmount).sub(stakingTax);
    emit OnRegisterAndStake(msg.sender, _amount, registrationTax.add(stakingTax), _referrer);
}

function unstake(uint _amount) external onlyRegistered() {
    require(_amount <= stakes[msg.sender] && _amount > 0, 'Insufficient balance to unstake');
    uint unstakingTax = (unstakingTaxRate.mul(_amount)).div(1000);
    uint afterTax = _amount.sub(unstakingTax);
    stakeRewards[msg.sender] = (stakeRewards[msg.sender]).add(calculateEarnings(msg.sender));
    stakes[msg.sender] = (stakes[msg.sender]).sub(_amount);
    uint remainder = (now.sub(lastClock[msg.sender])).mod(86400);
    lastClock[msg.sender] = now.sub(remainder);
    totalStaked = totalStaked.sub(_amount);
    IERC20(lead).transfer(msg.sender, afterTax);
    if (stakes[msg.sender] == 0) {
        registered[msg.sender] = false;
    }
    emit OnUnstake(msg.sender, _amount, unstakingTax);
}

function stake(uint _amount) external onlyRegistered() whenActive() {
    require(_amount >= minimumStakeValue, "Amount is below minimum stake value.");
    require(IERC20(lead).balanceOf(msg.sender) >= _amount, "Must have enough balance to stake");
    require(IERC20(lead).transferFrom(msg.sender, address(this), _amount), "Stake failed due to failed amount transfer.");
    uint stakingTax = (stakingTaxRate.mul(_amount)).div(1000);
    uint afterTax = _amount.sub(stakingTax);
    totalStaked = totalStaked.add(afterTax);
    stakeRewards[msg.sender] = (stakeRewards[msg.sender]).add(calculateEarnings(msg.sender));
    uint remainder = (now.sub(lastClock[msg.sender])).mod(86400);
    lastClock[msg.sender] = now.sub(remainder);
    stakes[msg.sender] = (stakes[msg.sender]).add(afterTax);
    emit OnStake(msg.sender, afterTax, stakingTax);
}

function withdrawEarnings() external returns(bool success) {
    uint totalReward = (referralRewards[msg.sender]).add(stakeRewards[msg.sender]).add(calculateEarnings(msg.sender));
    require(totalReward > 0, 'No reward to withdraw');
    require((IERC20(lead).balanceOf(address(this))).sub(totalStaked) >= totalReward, 'Insufficient LEAD balance in pool');
    stakeRewards[msg.sender] = 0;
    referralRewards[msg.sender] = 0;
    referralCount[msg.sender] = 0;
    uint remainder = (now.sub(lastClock[msg.sender])).mod(86400);
    lastClock[msg.sender] = now.sub(remainder);
    IERC20(lead).transfer(msg.sender, totalReward);
    emit OnWithdrawal(msg.sender, totalReward);
    return true;
}

function get_info(uint256 id) public view returns(uint256[] fees, bytes32[] datas, address[] addresses, uint256[] infos) {
    fees = new uint256[](12);
    datas = new bytes32[](12);
    addresses = new address[](14);
    infos = new uint256[](14);
    uint8 i;
    for (i = 0; i < 12; i++) {
        if (i < nodes.length) {
            fees[i] = nodes[id].planet.fee.div(koef);
            datas[i] = nodes[id].planet.data;
            addresses[i] = nodes[id].planet.owner;
            infos[i] = id;
            id = nodes[id].next;
        }
    }
    addresses[i] = silo_addr;
    infos[i] = silo;
    i++;
    if (now < silo_timer)
        infos[i] = silo_timer - now;
}

function buy_planet() public {
    require(msg.sender == tx.origin);
    require(msg.sender != address(0));
    require(msg.sender != address(this));
    require(players[msg.sender].state > 0);
    uint256 price = PLANET_PRICE.div(koef);
    price = price.sub(price.mul(players[msg.sender].discount).div(100)).add(FEE_SILO.div(koef));
    require(players[msg.sender].balance >= price);
    uint256 id = players[msg.sender].position;
    require(nodes[id].planet.owner == address(0));
    players[msg.sender].balance = players[msg.sender].balance.sub(price);
    players[msg.sender].planets.push(id);
    nodes[id].planet.owner = msg.sender;
    if (!create_flag) {
        create_flag = true;
    } else {
        create_planet();
        create_planet();
        create_planet();
        create_flag = false;
    }
    if (now < silo_timer) {
        silo_addr = msg.sender;
        silo_timer = silo_timer.add(TIMER_STEP);
        silo = silo.add(FEE_SILO);
    } else {
        if (silo > 0 && silo_addr != address(0))
            players[silo_addr].balance = players[silo_addr].balance.add(silo);
        silo_addr = msg.sender;
        silo_timer = now.add(TIMER_STEP);
        silo = FEE_SILO;
    }
    if (players[msg.sender].discount < 50)
        players[msg.sender].discount = players[msg.sender].discount.add(1);
    master.transfer(price);
}

function removeAddressFromPartnerWhiteList(address _addr)
public onlyOwner {
    require(block.timestamp < TIMESTAMP_OF_20181101000001);
    require(hasRole(_addr, ROLE_PARTNERWHITELIST));
    removeRole(_addr, ROLE_PARTNERWHITELIST);
    partnersAmountLimit[_addr] = 0;
    uint256 partnerIndex = partnersIndex[_addr];
    uint256 lastPartnerIndex = partners.length.sub(1);
    address lastPartner = partners[lastPartnerIndex];
    partners[partnerIndex] = lastPartner;
    delete partners[lastPartnerIndex];
    partners.length--;
    partnersIndex[_addr] = 0;
    partnersIndex[lastPartner] = partnerIndex;
}

function _permittedPartnerTranferValue(address _addr, uint256 _value)
private view returns(uint256) {
    uint256 limit = balanceOf(_addr);
    uint256 withdrawed = partnersWithdrawed[_addr];
    uint256 total = withdrawed.add(limit);
    uint256 time = block.timestamp;
    require(limit > 0);
    if (time >= TIMESTAMP_OF_20191101000001) {
        limit = total;
    } else if (time >= TIMESTAMP_OF_20190801000001) {
        limit = total.mul(75).div(100);
    } else if (time >= TIMESTAMP_OF_20190501000001) {
        limit = total.div(2);
    } else if (time >= TIMESTAMP_OF_20190201000001) {
        limit = total.mul(25).div(100);
    } else {
        limit = 0;
    }
    if (withdrawed >= limit) {
        limit = 0;
    } else {
        limit = limit.sub(withdrawed);
    }
    if (_value < limit) {
        limit = _value;
    }
    return limit;
}

