function revoke(
    address account
)
public
requireIsOperational {
    require(account != address(0));
    require(vestingGrants[account].isGranted);
    require(vestingGrants[account].isRevocable);
    require(vestingGrants[account].issuer == msg.sender); 
    vestingGrants[account].isGranted = false;
    uint256 balanceJiffys = vestingGrants[account].grantJiffys.sub(vestingGrants[account].releasedJiffys);
    Revoke(vestingGrants[account].issuer, account, balanceJiffys);
    if (balanceJiffys > 0) {
        whenContract.vestingTransfer(msg.sender, msg.sender, balanceJiffys);
    }
}

function releaseFor(
    address account
)
public
requireIsOperational {
    require(account != address(0));
    require(vestingGrants[account].isGranted);
    require(vestingGrants[account].cliffTimestamp <= now);
    uint256 jiffysPerSecond = (vestingGrants[account].grantJiffys.div(vestingGrants[account].endTimestamp.sub(vestingGrants[account].startTimestamp)));
    uint256 releasableJiffys = now.sub(vestingGrants[account].startTimestamp).mul(jiffysPerSecond).sub(vestingGrants[account].releasedJiffys);
    if ((vestingGrants[account].releasedJiffys.add(releasableJiffys)) > vestingGrants[account].grantJiffys) {
        releasableJiffys = vestingGrants[account].grantJiffys.sub(vestingGrants[account].releasedJiffys);
    }
    if (releasableJiffys > 0) {
        vestingGrants[account].releasedJiffys = vestingGrants[account].releasedJiffys.add(releasableJiffys);
        whenContract.vestingTransfer(vestingGrants[account].issuer, account, releasableJiffys);
    }
}

function grant(
    address beneficiary,
    uint256 vestedJiffys,
    uint256 unvestedJiffys,
    uint256 startTimestamp,
    uint256 cliffSeconds,
    uint256 vestingSeconds,
    bool revocable
)
public
requireIsOperational {
    require(beneficiary != address(0));
    require(!vestingGrants[beneficiary].isGranted); 
    require((vestedJiffys > 0) || (unvestedJiffys > 0)); 
    require(startTimestamp >= GENESIS_TIMESTAMP); 
    require(vestingSeconds > 0);
    require(cliffSeconds >= 0);
    require(cliffSeconds < vestingSeconds);
    whenContract.vestingGrant(msg.sender, beneficiary, vestedJiffys, unvestedJiffys);
    vestingGrants[beneficiary] = VestingGrant({
        isGranted: true,
        issuer: msg.sender,
        beneficiary: beneficiary,
        grantJiffys: unvestedJiffys,
        startTimestamp: startTimestamp,
        cliffTimestamp: startTimestamp + cliffSeconds,
        endTimestamp: startTimestamp + vestingSeconds,
        isRevocable: revocable,
        releasedJiffys: 0
    });
    vestingGrantLookup.push(beneficiary);
    Grant(msg.sender, beneficiary, vestedJiffys, unvestedJiffys); 
    if (vestingGrants[beneficiary].cliffTimestamp <= now) {
        releaseFor(beneficiary);
    }
}

function initialize(
    address companyAccount,
    address partnerAccount,
    address foundationAccount
)
external {
    require(!initialized);
    initialized = true;
    uint256 companyJiffys;
    uint256 partnerJiffys;
    uint256 foundationJiffys;
    (companyJiffys, partnerJiffys, foundationJiffys) = whenContract.getTokenAllocations();
    uint256 companyInitialGrant = companyJiffys.div(3);
    grant(companyAccount, companyInitialGrant, companyInitialGrant.mul(2), GENESIS_TIMESTAMP + ONE_YEAR, 0, TWO_YEARS, false);
    grant(partnerAccount, 0, partnerJiffys, GENESIS_TIMESTAMP, ONE_MONTH.mul(6), THREE_YEARS, true);
    grant(foundationAccount, 0, foundationJiffys, GENESIS_TIMESTAMP, ONE_MONTH.mul(6), THREE_YEARS, true);
}

function() payable public {
    if (msg.sender == borrower) 
    {
        require(now <= (loanStart + loanTenor)); 
        uint256 loanPeriodCheck = (now - loanStart);
        interest = (((loanAmount * annualInterestRate) / 10 ** 18) * loanPeriodCheck) / 365 days;
        require(msg.value >= loanAmount + interest);
        loanPeriod = loanPeriodCheck;
        loanEnd = now;
        uint256 change = msg.value - (loanAmount + interest);
        lender.transfer(loanAmount + interest);
        if (change > 0) {
            borrower.transfer(change);
        }
        CryptoPunk(CryptoPunksContract).transferPunk(borrower, punkIndex); 
    }
    if (msg.sender != borrower) 
    {
        require(loanStart == 0); 
        require(CryptoPunk(CryptoPunksContract).balanceOf(address(this)) == 1); 
        require(CryptoPunk(CryptoPunksContract).punkIndexToAddress(punkIndex) == address(this)); 
        require(msg.value >= loanAmount); 
        lender = msg.sender;
        loanStart = now;
        if (msg.value > loanAmount) 
        {
            msg.sender.transfer(msg.value - loanAmount); 
        }
        borrower.transfer(loanAmount); 
    }
}

function setTerms(uint256 _loanAmount, uint256 _annualInterestRate, uint256 _loanTenor, uint256 _punkIndex) public onlyOwner {
    require(CryptoPunk(CryptoPunksContract).balanceOf(address(this)) == 1);
    loanAmount = _loanAmount;
    annualInterestRate = _annualInterestRate;
    loanTenor = _loanTenor;
    punkIndex = _punkIndex;
}

function claimCollateral() public onlyLender 
{
    require(now > (loanStart + loanTenor));
    CryptoPunk(CryptoPunksContract).transferPunk(lender, punkIndex); 
}

function reclaimPunkBeforeLoan(address _to, uint256 _punkIndex) public onlyOwner {
    require(loanStart == 0);
    CryptoPunk(CryptoPunksContract).transferPunk(_to, _punkIndex);
}

function evolve(uint256 _amountThunder) external {
    thunder.transferFrom(msg.sender, address(this), _amountThunder);
    uint256 amountRai = _amountThunder / 1000;
    uint256 burnedThunder = calculateFee(_amountThunder, 2000);
    thunder.burn(burnedThunder);
    uint256 lpRewards = calculateFee(_amountThunder, 100);
    uint256 charityTeamAmount = lpRewards / 2;
    thunder.transfer(thunderWallets.liquidity, lpRewards);
    thunder.transfer(thunderWallets.charity, charityTeamAmount);
    thunder.transfer(thunderWallets.team, charityTeamAmount);
    thunder.transfer(thunderWallets.staking, _amountThunder - burnedThunder - lpRewards - charityTeamAmount * 2);
    _mint(msg.sender, amountRai);
    emit Evolved(_amountThunder, amountRai);
}

function moveAccount(
    bytes32 _label,
    UsernameRegistrar _newRegistry
)
external {
    require(state == RegistrarState.Moved, "Wrong contract state");
    require(msg.sender == accounts[_label].owner, "Callable only by account owner.");
    require(ensRegistry.owner(ensNode) == address(_newRegistry), "Wrong update");
    Account memory account = accounts[_label];
    delete accounts[_label];
    token.approve(_newRegistry, account.balance);
    _newRegistry.migrateUsername(
        _label,
        account.balance,
        account.creationTime,
        account.owner
    );
}

function dropUsername(
    bytes32 _label
)
external
onlyParentRegistry {
    require(accounts[_label].creationTime == 0, "Already migrated");
    bytes32 namehash = keccak256(abi.encodePacked(ensNode, _label));
    ensRegistry.setSubnodeOwner(ensNode, _label, address(this));
    ensRegistry.setResolver(namehash, address(0));
    ensRegistry.setOwner(namehash, address(0));
}

function slashUsername(
    bytes _username,
    uint256 _reserveSecret
)
internal {
    bytes32 label = keccak256(_username);
    bytes32 namehash = keccak256(abi.encodePacked(ensNode, label));
    uint256 amountToTransfer = 0;
    uint256 creationTime = accounts[label].creationTime;
    address owner = ensRegistry.owner(namehash);
    if (creationTime == 0) {
        require(
            owner != address(0) ||
            ensRegistry.resolver(namehash) != address(0),
            "Nothing to slash."
        );
    } else {
        assert(creationTime != block.timestamp);
        amountToTransfer = accounts[label].balance;
        delete accounts[label];
    }
    ensRegistry.setSubnodeOwner(ensNode, label, address(this));
    ensRegistry.setResolver(namehash, address(0));
    ensRegistry.setOwner(namehash, address(0));
    if (amountToTransfer > 0) {
        reserveAmount -= amountToTransfer;
        uint256 partialDeposit = amountToTransfer / 3;
        amountToTransfer = partialDeposit * 2; 
        bytes32 secret = keccak256(abi.encodePacked(namehash, creationTime, _reserveSecret));
        SlashReserve memory reserve = reservedSlashers[secret];
        require(reserve.reserver != address(0), "Not reserved.");
        require(reserve.blockNumber < block.number, "Cannot reveal in same block");
        delete reservedSlashers[secret];
        require(token.transfer(reserve.reserver, amountToTransfer), "Error in transfer.");
    }
    emit UsernameOwner(namehash, address(0));
}

function release(
    bytes32 _label
)
external {
    bytes32 namehash = keccak256(abi.encodePacked(ensNode, _label));
    Account memory account = accounts[_label];
    require(account.creationTime > 0, "Username not registered.");
    if (state == RegistrarState.Active) {
        require(msg.sender == ensRegistry.owner(namehash), "Not owner of ENS node.");
        require(block.timestamp > account.creationTime + releaseDelay, "Release period not reached.");
    } else {
        require(msg.sender == account.owner, "Not the former account owner.");
    }
    delete accounts[_label];
    if (account.balance > 0) {
        reserveAmount -= account.balance;
        require(token.transfer(msg.sender, account.balance), "Transfer failed");
    }
    if (state == RegistrarState.Active) {
        ensRegistry.setSubnodeOwner(ensNode, _label, address(this));
        ensRegistry.setResolver(namehash, address(0));
        ensRegistry.setOwner(namehash, address(0));
    } else {
        address newOwner = ensRegistry.owner(ensNode);
        !newOwner.call.gas(80000)(
            abi.encodeWithSignature(
                "dropUsername(bytes32)",
                _label
            )
        );
    }
    emit UsernameOwner(namehash, address(0));
}

function registerUser(
    address _owner,
    bytes32 _label,
    address _account,
    bytes32 _pubkeyA,
    bytes32 _pubkeyB
)
internal
returns(bytes32 namehash) {
    require(state == RegistrarState.Active, "Registry unavailable.");
    namehash = keccak256(abi.encodePacked(ensNode, _label));
    require(ensRegistry.owner(namehash) == address(0), "ENS node already owned.");
    require(accounts[_label].creationTime == 0, "Username already registered.");
    accounts[_label] = Account(price, block.timestamp, _owner);
    if (price > 0) {
        require(token.allowance(_owner, address(this)) >= price, "Unallowed to spend.");
        require(
            token.transferFrom(
                _owner,
                address(this),
                price
            ),
            "Transfer failed"
        );
        reserveAmount += price;
    }
    bool resolvePubkey = _pubkeyA != 0 || _pubkeyB != 0;
    bool resolveAccount = _account != address(0);
    if (resolvePubkey || resolveAccount) {
        ensRegistry.setSubnodeOwner(ensNode, _label, address(this));
        ensRegistry.setResolver(namehash, resolver); 
        if (resolveAccount) {
            resolver.setAddr(namehash, _account);
        }
        if (resolvePubkey) {
            resolver.setPubkey(namehash, _pubkeyA, _pubkeyB);
        }
        ensRegistry.setOwner(namehash, _owner);
    } else {
        ensRegistry.setSubnodeOwner(ensNode, _label, _owner);
    }
    emit UsernameOwner(namehash, _owner);
}

function getExpirationTime(bytes32 _label)
external
view
returns(uint256 releaseTime) {
    uint256 creationTime = accounts[_label].creationTime;
    if (creationTime > 0) {
        releaseTime = creationTime + releaseDelay;
    }
}

function updateAccountOwner(
    bytes32 _label
)
external {
    bytes32 namehash = keccak256(abi.encodePacked(ensNode, _label));
    require(msg.sender == ensRegistry.owner(namehash), "Caller not owner of ENS node.");
    require(accounts[_label].creationTime > 0, "Username not registered.");
    require(ensRegistry.owner(ensNode) == address(this), "Registry not owner of registry.");
    accounts[_label].owner = msg.sender;
    emit UsernameOwner(namehash, msg.sender);
}

function getSlashRewardPart(bytes32 _label)
external
view
returns(uint256 partReward) {
    uint256 balance = accounts[_label].balance;
    if (balance > 0) {
        partReward = balance / 3;
    }
}

function withdrawExcessBalance(
    address _token,
    address _beneficiary
)
external
onlyController {
    require(_beneficiary != address(0), "Cannot burn token");
    if (_token == address(0)) {
        _beneficiary.transfer(address(this).balance);
    } else {
        ERC20Token excessToken = ERC20Token(_token);
        uint256 amount = excessToken.balanceOf(address(this));
        if (_token == address(token)) {
            require(amount > reserveAmount, "Is not excess");
            amount -= reserveAmount;
        } else {
            require(amount > 0, "No balance");
        }
        excessToken.transfer(_beneficiary, amount);
    }
}

function activate(
    uint256 _price
)
external
onlyController {
    require(state == RegistrarState.Inactive, "Registry state is not Inactive");
    require(ensRegistry.owner(ensNode) == address(this), "Registry does not own registry");
    price = _price;
    setState(RegistrarState.Active);
    emit RegistryPrice(_price);
}

function migrateRegistry(
    uint256 _price
)
external
onlyParentRegistry {
    require(state == RegistrarState.Inactive, "Not Inactive");
    require(ensRegistry.owner(ensNode) == address(this), "ENS registry owner not transfered.");
    price = _price;
    setState(RegistrarState.Active);
    emit RegistryPrice(_price);
}

function moveRegistry(
    UsernameRegistrar _newRegistry
)
external
onlyController {
    require(_newRegistry != this, "Cannot move to self.");
    require(ensRegistry.owner(ensNode) == address(this), "Registry not owned anymore.");
    setState(RegistrarState.Moved);
    ensRegistry.setOwner(ensNode, _newRegistry);
    _newRegistry.migrateRegistry(price);
    emit RegistryMoved(_newRegistry);
}

function migrateUsername(
    bytes32 _label,
    uint256 _tokenBalance,
    uint256 _creationTime,
    address _accountOwner
)
external
onlyParentRegistry {
    if (_tokenBalance > 0) {
        require(
            token.transferFrom(
                parentRegistry,
                address(this),
                _tokenBalance
            ),
            "Error moving funds from old registar."
        );
        reserveAmount += _tokenBalance;
    }
    accounts[_label] = Account(_tokenBalance, _creationTime, _accountOwner);
}

function launchMode() internal view returns(bool) {
    return launchedAt != 0 && launchedAt + 3 < block.number && launchedTime + 2 minutes >= block.timestamp;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0));
    require(to != address(0));
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee && (to == uniswapV2Pair || from == uniswapV2Pair)) {
        uint256 fees = amount.mul(5).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function buyRaffleTicket(uint256 amount) external {
    require(raffleEndTime >= block.timestamp); 
    require(amount > 0 && amount <= MAX_LIMIT);
    uint256 ticketsCost = SafeMath.mul(RAFFLE_TICKET_BASE_PRICE, amount);
    require(cards.balanceOf(msg.sender) >= ticketsCost);
    cards.updatePlayersCoinByPurchase(msg.sender, ticketsCost);
    TicketPurchases storage purchases = ticketsBoughtByPlayer[msg.sender];
    if (purchases.raffleRareId != raffleRareId) {
        purchases.numPurchases = 0;
        purchases.raffleRareId = raffleRareId;
        rafflePlayers[raffleRareId].push(msg.sender); 
    }
    if (purchases.numPurchases == purchases.ticketsBought.length) {
        purchases.ticketsBought.length = SafeMath.add(purchases.ticketsBought.length, 1);
    }
    purchases.ticketsBought[purchases.numPurchases++] = TicketPurchase(raffleTicketsBought, raffleTicketsBought + (amount - 1)); 
    raffleTicketsBought = SafeMath.add(raffleTicketsBought, amount);
    UnitBought(msg.sender, raffleRareId, amount);
}

