function buyTokens(uint256 _numberOfTokens) public payable {
    uint256 tokenTotalPrice = (multiply(_numberOfTokens, tokenPrice)).div(10 ** 18);
    uint256 totalFeePercent = getTotalFeePercent();
    uint256 _totalFeeAmount = tokenTotalPrice.mul(totalFeePercent).div(100000); 
    totalFeeAmount = totalFeeAmount.add(_totalFeeAmount);
    require(msg.value >= tokenTotalPrice.add(_totalFeeAmount), 'incorrect amount');
    require(tokenContract.balanceOf(address(this)) >= _numberOfTokens, 'contract has not enough token');
    require(tokenContract.transfer(msg.sender, _numberOfTokens), 'transfer error');
    uint256 ethAmount = msg.value;
    _transferPayments(ethAmount);
    tokensSold += _numberOfTokens;
    emit Sell(msg.sender, _numberOfTokens);
}

function _transferPayments(uint256 ethAmount) internal {
    require(ethAmount > 0, "no ether recieved");
    uint256 _ownerFunds = ethAmount.sub(totalFeeAmount);
    etherWallet.transfer(_ownerFunds);
    uint256 feesCount = getFeeDistributionsCount();
    _Fee[] storage fees = feeDistributions;
    for (uint i = 0; i < feesCount; i++) {
        if (fees[i].active) {
            uint feeValue = _ownerFunds.mul(fees[i].percent).div(100000); 
            fees[i].wallet.transfer(feeValue);
        }
    }
    if (address(this).balance != 0) {
        etherWallet.transfer(address(this).balance);
    }
    totalFeeAmount = 0;
}

function transferFunds() public onlyOwner {
    uint256 totalFunds = address(this).balance;
    uint256 _ownerFunds = totalFunds.sub(totalFeeAmount);
    etherWallet.transfer(_ownerFunds);
    uint256 feesCount = getFeeDistributionsCount();
    _Fee[] storage fees = feeDistributions;
    for (uint i = 0; i < feesCount; i++) {
        if (fees[i].active) {
            uint feeValue = _ownerFunds.mul(fees[i].percent).div(100000); 
            fees[i].wallet.transfer(feeValue);
        }
    }
    if (address(this).balance != 0) {
        etherWallet.transfer(address(this).balance);
    }
    totalFeeAmount = 0;
}

function vasaPowerSwitch(uint256 senderBalanceOf) public {
    require(block.number >= _startBlock, "Switch still not started!");
    IERC20 oldToken = IERC20(_oldTokenAddress);
    uint256 mintableAmount = calculateMintable(senderBalanceOf);
    require(mintableAmount > 0, "Zero tokens to mint!");
    oldToken.transferFrom(msg.sender, address(this), senderBalanceOf);
    oldToken.burn(senderBalanceOf);
    _totalMintable -= senderBalanceOf;
    IMVDProxy(IDoubleProxy(_doubleProxy).proxy()).submit("mintAndTransfer", abi.encode(address(0), 0, mintableAmount, msg.sender));
}

function requestDetachment(
    uint256 _tokenId
)
public {
    require(isApprovedOrOwner(msg.sender, _tokenId));
    uint256 isAttached = getIsNFTAttached(_tokenId);
    require(isAttached >= 1);
    if (attachedSystemActive == true) {
        if (isAttached > 1 && block.timestamp - isAttached > detachmentTime) {
            isAttached = 0;
        } else if (isAttached > 1) {
            require(isAttached == 1);
        } else {
            emit DetachRequest(msg.sender, _tokenId, block.timestamp);
            isAttached = block.timestamp;
        }
    } else {
        isAttached = 0;
    }
    if (isAttached == 0) {
        emit NFTDetached(msg.sender, _tokenId);
    }
    updateIsAttached(_tokenId, isAttached);
}

