function getBonusRate(uint256 weiAmount) internal view returns(uint256) {
    uint256 bonusRate = rate;
    uint[2] memory weiRaisedStartsBoundaries = [uint(0), uint(0)];
    uint[2] memory weiRaisedEndsBoundaries = [uint(336000000000000000000000), uint(336000000000000000000000)];
    uint64[2] memory timeStartsBoundaries = [uint64(1523734197), uint64(1524252540)];
    uint64[2] memory timeEndsBoundaries = [uint64(1524252540), uint64(1525116540)];
    uint[2] memory weiRaisedAndTimeRates = [uint(400), uint(300)];
    for (uint i = 0; i < 2; i++) {
        bool weiRaisedInBound = (weiRaisedStartsBoundaries[i] <= weiRaised) && (weiRaised < weiRaisedEndsBoundaries[i]);
        bool timeInBound = (timeStartsBoundaries[i] <= now) && (now < timeEndsBoundaries[i]);
        if (weiRaisedInBound && timeInBound) {
            bonusRate += bonusRate * weiRaisedAndTimeRates[i] / 1000;
        }
    }
    uint[2] memory weiAmountBoundaries = [uint(336000000000000000000000), uint(10000000000000000000)];
    uint[2] memory weiAmountRates = [uint(0), uint(100)];
    for (uint j = 0; j < 2; j++) {
        if (weiAmount >= weiAmountBoundaries[j]) {
            bonusRate += bonusRate * weiAmountRates[j] / 1000;
            break;
        }
    }
    return bonusRate;
}

function determineBonus(uint tokens, uint amountSent, address sender) internal returns(uint256 bonus) {
    uint256 timeElapsed = now - startTime;
    uint256 timeElapsedInDays = timeElapsed.div(1 days);
    if (timeElapsedInDays < 30) {
        require(amountSent >= minimumContributionInPrivatePhase);
        bonus = tokens.mul(bonusInPrivateSale);
        bonus = bonus.div(100);
        require(TOKENS_SOLD.add(tokens.add(bonus)) <= maxTokensToSaleInPrivateSale);
        token.addPrivateSaleBuyer(sender, tokens.add(bonus));
    }
    else if (timeElapsedInDays >= 30 && timeElapsedInDays < 51) {
        revert();
    }
    else if (timeElapsedInDays >= 51 && timeElapsedInDays < 72) {
        require(amountSent >= minimumContributionInPreICO && amountSent <= maximumContributionInPreICO);
        if (amountSent >= 1.68 ether && amountSent < 17 ether) {
            bonus = tokens.mul(5);
            bonus = bonus.div(100);
            require(TOKENS_SOLD.add(tokens.add(bonus)) <= maxTokensToSaleInPreICO);
        } else if (amountSent >= 17 ether && amountSent < 169 ether) {
            bonus = tokens.mul(10);
            bonus = bonus.div(100);
            require(TOKENS_SOLD.add(tokens.add(bonus)) <= maxTokensToSaleInPreICO);
        } else if (amountSent >= 169 ether && amountSent < 841 ether) {
            bonus = tokens.mul(15);
            bonus = bonus.div(100);
            require(TOKENS_SOLD.add(tokens.add(bonus)) <= maxTokensToSaleInPreICO);
        } else if (amountSent >= 841 ether && amountSent < 1680 ether) {
            bonus = tokens.mul(20);
            bonus = bonus.div(100);
            require(TOKENS_SOLD.add(tokens.add(bonus)) <= maxTokensToSaleInPreICO);
        }
        if (EthersSentByBuyers[sender] == 0) {
            EthersSentByBuyers[sender] = amountSent;
            tokenBuyers.push(sender);
        } else {
            EthersSentByBuyers[sender] = EthersSentByBuyers[sender].add(amountSent);
        }
        weiRaisedInPreICO = weiRaisedInPreICO.add(amountSent);
        token.addPreSaleBuyer(sender, tokens.add(bonus));
    }
    else if (timeElapsedInDays >= 72 && timeElapsedInDays < 83) {
        revert();
    }
    else if (timeElapsedInDays >= 83) {
        require(amountSent <= maximumContributionInMainICO);
        bonus = 0;
    }
}

constructor(uint256 _startTime, address _wallet, address _tokenAddress) public {
    require(_startTime >= now);
    require(_wallet != 0x0);
    startTime = _startTime;
    endTime = startTime + totalDurationInDays;
    require(endTime >= startTime);
    owner = _wallet;
    maxTokensToSaleInPrivateSale = 100000000 * 10 ** uint256(decimals);
    maxTokensToSaleInPreICO = 200000000 * 10 ** uint256(decimals);
    maxTokensToSale = 550000000 * 10 ** uint256(decimals);
    bonusInPrivateSale = 100;
    minimumContributionInPrivatePhase = 168 ether;
    minimumContributionInPreICO = 1.68 ether;
    maximumContributionInPreICO = 1680 ether;
    maximumContributionInMainICO = 168 ether;
    token = TokenInterface(_tokenAddress);
}

function RefundToBuyers() public payable onlyOwner {
    require(weiRaised < softCapForPreICO);
    require(msg.value >= weiRaisedInPreICO);
    for (uint i = 0; i < tokenBuyers.length; i++) {
        uint etherAmount = EthersSentByBuyers[tokenBuyers[i]];
        if (etherAmount > 0) {
            tokenBuyers[i].transfer(etherAmount);
            EthersSentByBuyers[tokenBuyers[i]] = 0;
        }
    }
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(isCrowdsalePaused == false);
    require(validPurchase());
    require(TOKENS_SOLD < maxTokensToSale && weiRaised < hardCap);
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(ratePerWei);
    uint256 bonus = determineBonus(tokens, weiAmount, beneficiary);
    tokens = tokens.add(bonus);
    require(TOKENS_SOLD.add(tokens) <= maxTokensToSale);
    weiRaised = weiRaised.add(weiAmount);
    token.transfer(beneficiary, tokens);
    emit TokenPurchase(owner, beneficiary, weiAmount, tokens);
    TOKENS_SOLD = TOKENS_SOLD.add(tokens);
    forwardFunds();
}

function saleTokens(address _to, uint256 _value) public onlySaleAgent returns(bool) {
    require(_to != address(0));
    require(_value <= balances[owner]);
    balances[owner] = balances[owner].sub(_value);
    if (now > freezTime) {
        balances[_to] = balances[_to].add(_value);
    } else {
        preSaleBalances[_to] = preSaleBalances[_to].add(_value);
    }
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function transferPreSaleBalance(address _to, uint256 _value) public returns(bool) {
    require(now > freezTime);
    require(_to != address(0));
    require(_value <= preSaleBalances[msg.sender]);
    preSaleBalances[msg.sender] = preSaleBalances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function initialize(
    uint _startInSeconds,
    uint _releaseInSeconds)
external onlyOwner() {
    require(
        _start == 0,
        "already initialized"
    );
    _start = block.timestamp + _startInSeconds;
    _release = block.timestamp + _releaseInSeconds;
    _init = block.timestamp;
}

function _released2() internal view returns(uint) {
    uint start = _start;
    uint release = _release;
    uint total = _beneficiaries[beneficiary].total2;
    uint taken = _beneficiaries[beneficiary].taken2;
    uint releasedPct;
    if (block.timestamp <= start) return 0;
    if (block.timestamp >= release) releasedPct = 100;
    else releasedPct =
        ((block.timestamp - start) * 100000) /
        ((release - start) * 1000);
    uint released = (total * releasedPct) / 100;
    return released - taken;
}

function _released1() internal view returns(uint) {
    uint start = _init;
    uint release = _start;
    uint total = _beneficiaries[beneficiary].total1;
    uint taken = _beneficiaries[beneficiary].taken1;
    uint releasedPct;
    if (block.timestamp <= start) return 0;
    if (block.timestamp >= release) releasedPct = 100;
    else releasedPct =
        ((block.timestamp - start) * 100000) /
        ((release - start) * 1000);
    uint released = (total * releasedPct) / 100;
    return released - taken;
}

function claim() external returns(bool success) {
    require(
        _start != 0,
        "not yet initialized"
    );
    uint release1 = _released1();
    uint release2 = _released2();
    require(
        release1 > 0 || release2 > 0,
        "You do not have any balance available"
    );
    if (release1 > 0) _claim1(release1);
    if (release2 > 0) _claim2(release2);
    return true;
}

function _claim2(
    uint released)
internal {
    _beneficiaries[beneficiary].taken2 += released;
    require(
        _DES.transfer(beneficiary, released),
        "Error in sending token"
    );
    uint release = _release;
    if (release <= block.timestamp) {
        _beneficiaries[beneficiary].total2 = 0;
        _beneficiaries[beneficiary].taken2 = 0;
    }
    emit Withdrawal(beneficiary, released);
}

function getReleaseTime()
external view returns(
    uint initialRelease,
    uint finalRelease) {
    uint start = _start;
    uint release = _release;
    block.timestamp > start ?
        initialRelease = 0 :
        initialRelease = start - block.timestamp;
    block.timestamp > release ?
        finalRelease = 0 :
        finalRelease = release - block.timestamp;
}

function _claim1(
    uint released)
internal {
    _beneficiaries[beneficiary].taken1 += released;
    require(
        _DES.transfer(beneficiary, released),
        "Error in sending token"
    );
    uint release = _start;
    if (release <= block.timestamp) {
        _beneficiaries[beneficiary].total1 = 0;
        _beneficiaries[beneficiary].taken1 = 0;
    }
    emit Withdrawal(beneficiary, released);
}

