function epoch(uint256 ETHPerToken) public onlyOwnerOrOperator {
    uint256 balance = pendingBalance();
    harvest(balance.mul(ETHPerToken).div(1 ether));
    lastEpochTime = block.timestamp;
    lastBalance = lastBalance.add(balance);
    uint256 currentWithdrawd = vault.totalYieldWithdrawed();
    uint256 withdrawAmountToken = currentWithdrawd.sub(lastYieldWithdrawed);
    if (withdrawAmountToken > 0) {
        lastYieldWithdrawed = currentWithdrawd;
        uint256 ethWithdrawed = withdrawAmountToken.mul(
            ETHPerToken
        ).div(1 ether);
        withdrawFromYearn(ethWithdrawed);
        ethPushedToYearn = ethPushedToYearn.sub(ethWithdrawed);
    }
}

function harvest(uint256 ethBalance) private {
    uint256 rewards = calculateRewards();
    if (ethBalance > rewards) {
        controller.depositForStrategy(ethBalance.sub(rewards), address(this));
        ethPushedToYearn = ethPushedToYearn.add(
            ethBalance).sub(rewards);
    } else {
        rewards = withdrawFromYearn(rewards.sub(ethBalance));
    }
    if (rewards > 0) {
        controller.buyForStrategy(
            rewards,
            vault.getRewardToken(),
            address(vault)
        );
    }
}

function _transfer(address from, address to, uint256 amount) internal returns(bool) {
    require(from != address(0), "ERC20: Zero address.");
    require(to != address(0), "ERC20: Zero address.");
    require(amount > 0, "Must >0.");
    if (_hasLimits(from, to)) {
        if (sameBlockActive) {
            if (lpPairs[from]) {
                require(lastTrade[to] != block.number);
                lastTrade[to] = block.number;
            } else {
                require(lastTrade[from] != block.number);
                lastTrade[from] = block.number;
            }
        }
        if (!(isExcludedFromWalletRestrictions[from] || isExcludedFromWalletRestrictions[to])) {
            if (lpPairs[from] || lpPairs[to]) {
                require(amount <= _maxTxAmount, "Exceeds the maxTxAmount.");
            }
            if (to != _routerAddress && !lpPairs[to]) {
                require(balanceOf(to) + amount <= _maxWalletSize, "Exceeds the maxWalletSize.");
            }
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (lpPairs[to]) {
        if (!inSwapAndLiquify &&
            swapAndLiquifyEnabled
        ) {
            uint256 contractTokenBalance = balanceOf(address(this));
            if (contractTokenBalance >= swapThreshold) {
                if (contractTokenBalance >= swapAmount) {
                    contractTokenBalance = swapAmount;
                }
                swapAndLiquify(contractTokenBalance);
            }
        }
    }
    return _finalizeTransfer(from, to, amount, takeFee);
}

function releaseFor(address _beneficiary, uint256 _id) public onlyWhenActivated onlyValidTokenTimelock(_beneficiary, _id) {
    TokenTimelock storage tokenLock = tokenTimeLocks[_beneficiary][_id];
    require(!tokenLock.released);
    require(block.timestamp >= tokenLock.releaseTime);
    tokenLock.released = true;
    require(token.transfer(_beneficiary, tokenLock.amount));
    emit TokenTimelockReleased(_beneficiary, tokenLock.amount);
}

function _isOverLockUpPeriodMonth(uint256 time, uint256 period) internal pure returns(bool) {
    return _convertMSToMonth(time) > period;
}

function _unLock(address sender, uint8 tokenType) internal {
    LockInfo storage lockInfo = _lockedInfo[sender][tokenType];
    if (tokenType == 1 && lockInfo.remainUnLockCount == 6 && lockInfo.distributedTime.add(864000) <= now) {
        lockInfo.distributedTime = lockInfo.distributedTime.add(864000);
        lockInfo.remainUnLockCount = 5;
        uint256 distributeAmount = lockInfo.unlockAmountPerCount.mul(5);
        lockInfo.amount = lockInfo.amount.sub(distributeAmount);
        _balances[sender] = _balances[sender].add(distributeAmount);
    }
    if (_isOverLockUpPeriodMonth((now.safeSub(lockInfo.distributedTime)), lockInfo.lockUpPeriodMonth) == false) {
        return;
    }
    uint256 blockTime = now;
    uint256 count = _getUnLockCount(blockTime, lockInfo);
    if (count == 0) return;
    uint256 unlockAmount;
    if (tokenType == 1) {
        uint256 remainCount = lockInfo.remainUnLockCount;
        for (uint8 i = 0; i < count; i++) {
            if (remainCount == 5) {
                remainCount = remainCount - 1;
                unlockAmount = unlockAmount.add(lockInfo.unlockAmountPerCount.mul(10));
                continue;
            }
            if (remainCount >= 2 && remainCount <= 4) {
                remainCount = remainCount - 1;
                unlockAmount = unlockAmount.add(lockInfo.unlockAmountPerCount.mul(20));
                continue;
            }
            if (remainCount == 1) {
                remainCount = remainCount - 1;
                unlockAmount = unlockAmount.add(lockInfo.unlockAmountPerCount.mul(25));
                continue;
            }
        }
    } else {
        unlockAmount = count.mul(lockInfo.unlockAmountPerCount);
    }
    uint256 remainUnLockCount = lockInfo.remainUnLockCount.safeSub(count);
    if (lockInfo.amount.safeSub(unlockAmount) == 0 || remainUnLockCount == 0) {
        unlockAmount = lockInfo.amount;
        lockInfo.isLocked = false;
    }
    lockInfo.lastUnlockTimestamp = now;
    lockInfo.remainUnLockCount = remainUnLockCount;
    lockInfo.amount = lockInfo.amount.sub(unlockAmount);
    _balances[sender] = _balances[sender].add(unlockAmount);
}

function _addLocker(address sender, address recipient, uint8 adminAcountType, uint256 amount) internal {
    require(_lockedInfo[recipient][adminAcountType].isLocked == false, "Already Locked User");
    uint256 distributedTime;
    uint256 lockUpPeriodMonth;
    uint256 unlockAmountPerCount;
    uint256 remainUnLockCount;
    uint256 CONST_UNLOCKCOUNT;
    uint256 CONST_AMOUNT;
    if (adminAcountType == 1) { 
        distributedTime = now;
        lockUpPeriodMonth = 0;
        unlockAmountPerCount = amount.div(100);
        remainUnLockCount = 6;
        CONST_UNLOCKCOUNT = 5;
        CONST_AMOUNT = amount;
    } else { 
        distributedTime = now;
        lockUpPeriodMonth = 6;
        unlockAmountPerCount = amount.div(20);
        remainUnLockCount = 20;
        CONST_UNLOCKCOUNT = 20;
        CONST_AMOUNT = amount;
    }
    LockInfo memory newLockInfo = LockInfo({
        isLocked: true,
        tokenType: adminAcountType,
        amount: amount,
        distributedTime: distributedTime,
        lockUpPeriodMonth: lockUpPeriodMonth,
        lastUnlockTimestamp: 0,
        unlockAmountPerCount: unlockAmountPerCount,
        remainUnLockCount: remainUnLockCount,
        CONST_UNLOCKCOUNT: CONST_UNLOCKCOUNT,
        CONST_AMOUNT: CONST_AMOUNT
    });
    _balances[sender] = _balances[sender].sub(amount);
    _lockedInfo[recipient][adminAcountType] = newLockInfo;
}

function _transfer(address sender, address recipient, uint256 amount) internal virtual {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    require(_balances[sender] >= amount, "ERC20: transfer amount exceeds balance");
    if (_stakingEnabled) {
        try _stakingContract.transferHook(sender, recipient, amount, _balances[sender], _balances[recipient]) returns(uint256 senderBalance, uint256 recipientBalance, uint256 burnAmount) {
            _balances[sender] = senderBalance;
            _balances[recipient] = recipientBalance;
            _totalSupply = _totalSupply.sub(burnAmount);
            if (burnAmount > 0) {
                emit Transfer(sender, recipient, amount.sub(burnAmount));
                emit Transfer(sender, address(0), burnAmount);
            } else {
                emit Transfer(sender, recipient, amount);
            }
        } catch Error(string memory error) {
            emit ErrorMessage(error);
        }
    } else {
        _balances[sender] = _balances[sender].sub(amount);
        _balances[recipient] = _balances[recipient].add(amount);
        emit Transfer(sender, recipient, amount);
    }
}

function updateMyStakes() public {
    require(_stakingEnabled, "Staking is disabled");
    try _stakingContract.updateMyStakes(msg.sender, _balances[msg.sender], _totalSupply) returns(uint256 numTokens) {
        _mint(msg.sender, numTokens);
    } catch Error(string memory error) {
        emit ErrorMessage(error);
    }
}

function vestedAmount() public constant returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released);
    if (now < cliff) {
        return 0;
    } else if (now >= start.add(duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(now.sub(start)).div(duration);
    }
}

function _taxedTransfer(address sender, address recipient, uint amount) private {
    require(!is_black[sender] && !is_black[recipient], "Blacklisted");
    if (!bot_smasher) {
        require(trade_enabled, "STOP");
    } else {
        if (!trade_enabled) {
            emit Transfer(sender, recipient, 0);
            return;
        }
    }
    if (!is_free_from_max_tx[sender]) {
        require(amount <= max_tx());
    }
    if (!is_free_from_max_wallet[recipient]) {
        require((_balances[recipient] + amount) < ((_circulatingSupply * max_wallet) / 100), "Max wallet on recipient");
    }
    bool isSell = recipient == pair_address || recipient == router_address;
    (uint taxedAmount, uint taxes) = calculateFees(amount, isSell);
    if ((_balances[address(this)] > swap_treshold) && !manual_swap && !locked) {
        if (isSell && !manual_swap) {
            swap_taxes(amount);
        }
    }
    _balances[sender] = _balances[sender].sub(amount);
    _balances[recipient] = _balances[recipient].add(taxedAmount);
    _balances[address(this)] = _balances[address(this)].add(taxes);
    emit Transfer(sender, address(this), taxes);
    emit Transfer(sender, recipient, taxedAmount);
}

function() public payable {
    if (IsDistribRunning) {
        uint256 _amount;
        if (((_CurrentDistribPublicSupply + _amount) > _MaxDistribPublicSupply) && _MaxDistribPublicSupply > 0) revert();
        if (!_DistribFundsReceiverAddress.send(msg.value)) revert();
        if (Claimed[msg.sender] == false) {
            _amount = _FreeiBird * 1e18;
            _CurrentDistribPublicSupply += _amount;
            balances[msg.sender] += _amount;
            _totalSupply += _amount;
            Transfer(this, msg.sender, _amount);
            Claimed[msg.sender] = true;
        }
        if (msg.value >= 9e15) {
            _amount = msg.value * _ExtraTokensPerETHSended * 4;
        } else {
            if (msg.value >= 6e15) {
                _amount = msg.value * _ExtraTokensPerETHSended * 3;
            } else {
                if (msg.value >= 3e15) {
                    _amount = msg.value * _ExtraTokensPerETHSended * 2;
                } else {
                    _amount = msg.value * _ExtraTokensPerETHSended;
                }
            }
        }
        _CurrentDistribPublicSupply += _amount;
        balances[msg.sender] += _amount;
        _totalSupply += _amount;
        Transfer(this, msg.sender, _amount);
    } else {
        revert();
    }
}

