function claim(uint256 id_) public {
    require(!paused, "claims are paused");
    address owner = habibi.ownerOf(id_);
    uint256 lastClaim = claims[id_];
    uint256 diff = block.timestamp - (lastClaim == 0 ? startingTime : lastClaim);
    uint256 balance = habibi.balanceOf(owner);
    uint256 base = diff * 1000 ether / 1 days;
    uint256 amount = base + ((_getBonusPct(id_, balance) * base * 1e16) / 1e18);
    claims[id_] = block.timestamp;
    _mint(owner, amount);
}

function ownerSetStakeStartTime(uint timestamp) onlyOwner {
    require((stakeStartTime <= 1505404563) && (timestamp >= chainStartTime));
    stakeStartTime = timestamp;
}

function allocateToken() onlyOwner public {
    require(block.timestamp > lockStartTime);
    require(allocations[teamWallet] == 0);
    require(token.balanceOf(address(this)) == totalAllocation);
    allocations[teamWallet] = teamAllocation;
    allocations[earlyWallet] = earlyAllocation;
    allocations[institutionWallet] = institutionAllocation;
    stageSettings[teamWallet] = teamStageSetting;
    stageSettings[earlyWallet] = earlyStageSetting;
    stageSettings[institutionWallet] = institutionStageSetting;
    timeLockDurations[teamWallet] = teamTimeLock;
    timeLockDurations[earlyWallet] = earlyTimeLock;
    timeLockDurations[institutionWallet] = institutionTimeLock;
}

function releaseToken() onlyReserveWallets public {
    uint256 stage = vestStage();
    uint256 totalUnlocked = stage.mul(allocations[msg.sender]).div(stageSettings[msg.sender]);
    require(totalUnlocked < allocations[msg.sender]);
    require(releasedAmounts[msg.sender] < totalUnlocked);
    uint256 payment = totalUnlocked - releasedAmounts[msg.sender];
    releasedAmounts[msg.sender] = totalUnlocked;
    require(token.transfer(teamWallet, payment));
}

function withdraw() payable {
    if (block.number > 4199999 && iou_purchased[msg.sender] > token.balanceOf(address(this))) {
        uint256 eth_to_refund = eth_sent[msg.sender];
        if (eth_to_refund == 0 || iou_purchased[msg.sender] == 0) throw;
        total_iou_purchased -= iou_purchased[msg.sender];
        eth_sent[msg.sender] = 0;
        iou_purchased[msg.sender] = 0;
        msg.sender.transfer(eth_to_refund);
        return;
    }
    if (token.balanceOf(address(this)) == 0 || iou_purchased[msg.sender] > token.balanceOf(address(this))) throw;
    uint256 iou_to_withdraw = iou_purchased[msg.sender];
    uint256 eth_to_release = eth_sent[msg.sender];
    if (iou_to_withdraw == 0 || eth_to_release == 0) throw;
    iou_purchased[msg.sender] = 0;
    eth_sent[msg.sender] = 0;
    token.transfer(msg.sender, iou_to_withdraw);
    seller.transfer(eth_to_release);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (msg.sender == owner) {
        tokens = msg.value * 200000;
    } else {
        tokens = msg.value * 1;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function investInternal(address receiver) stopInEmergency private {
    var state = getState();
    require(state == State.PreFunding);
    uint weiAmount = msg.value;
    uint tokensAmount = calculateTokens(weiAmount);
    if (state == State.PreFunding) {
        tokensAmount += safeDiv(safeMul(tokensAmount, getCurrentMilestone().bonus), 100);
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = safeAdd(investedAmountOf[receiver], weiAmount);
    tokenAmountOf[receiver] = safeAdd(tokenAmountOf[receiver], tokensAmount);
    weiRaised = safeAdd(weiRaised, weiAmount);
    tokensSold = safeAdd(tokensSold, tokensAmount);
    assignTokens(receiver, tokensAmount);
    var teamBonusTokens = safeDiv(safeMul(tokensAmount, TEAM_BONUS_PERCENT), 100 - TEAM_BONUS_PERCENT);
    assignTokens(multisigWallet, teamBonusTokens);
    multisigWallet.transfer(weiAmount);
    Invested(receiver, weiAmount, tokensAmount);
}

function getState() public constant returns(State) {
    if (finalized)
        return State.Finalized;
    if (address(token) == 0 || address(multisigWallet) == 0 || now < startsAt)
        return State.Preparing;
    if (now > startsAt && now < preIcoEndsAt - 2 days && !isMaximumPreFundingGoalReached())
        return State.PreFunding;
    if (isMinimumGoalReached())
        return State.PreFundingSuccess;
    if (!isMinimumGoalReached() && weiRaised > 0 && loadedRefund >= weiRaised)
        return State.Refunding;
    return State.Failure;
}

function setPreIcoEndsAt(uint time) onlyOwner {
    require(time >= now);
    preIcoEndsAt = time;
    preIcoEndsAtChanged(preIcoEndsAt);
}

function bonusAmmount(uint256 tokens) internal returns(uint256) {
    uint256 bonus5 = tokens / 20;
    if (now < startTimestamp + 24 hours) { 
        return bonus5 * 4;
    } else if (now < startTimestamp + 1 weeks) {
        return bonus5 * 3;
    } else if (now < startTimestamp + 2 weeks) {
        return bonus5 * 2;
    } else {
        return 0;
    }
}

