        reward = (((phoenix.Packs(phoenix.getLastBuyPack(_useraddress)[1]) * fetchPrice(usdtFetchId) + users[_useraddress].extraPrinciple) * 20 * (10 ** 8)) / 100) / fetchPrice(ecoFetchId);
