function distributeBonus(address[] addresses) public onlyOwner {
    require(now > bonusUnlockTime);
    for (uint i = 0; i < addresses.length; i++) {
        if (bonusOf[addresses[i]] > 0) {
            uint256 bonusAmount = bonusOf[addresses[i]];
            _deliverTokens(addresses[i], bonusAmount);
            totalBonus = totalBonus.sub(bonusAmount);
            bonusOf[addresses[i]] = 0;
        }
    }
    if (totalBonus == 0 && reservedTokensClaimStage == 3) {
        MintableToken(token).finishMinting();
    }
}

function withdrawBonus() public {
    require(now > bonusUnlockTime);
    require(bonusOf[msg.sender] > 0);
    _deliverTokens(msg.sender, bonusOf[msg.sender]);
    totalBonus = totalBonus.sub(bonusOf[msg.sender]);
    bonusOf[msg.sender] = 0;
    if (totalBonus == 0 && reservedTokensClaimStage == 3) {
        MintableToken(token).finishMinting();
    }
}

function _processPurchase(address _beneficiary, uint256 _tokenAmount) internal {
    _saveBonus(_beneficiary, _tokenAmount);
    _deliverTokens(_beneficiary, _tokenAmount);
    soldTokens = soldTokens.add(_tokenAmount);
}

function unlockTokenTransfers() public onlyOwner {
    require(isFinalized);
    require(now > closingTime + 30 days);
    require(PausableToken(token).paused());
    bonusUnlockTime = now + 30 days;
    PausableToken(token).unpause();
}

function claimReservedTokens() public onlyOwner {
    uint256 toMintNow = totalTokens.mul(5).div(100);
    if (reservedTokensClaimStage == 0) {
        require(now > closingTime + 6 * 30 days);
        reservedTokensClaimStage = 1;
        _deliverTokens(tokensWallet, toMintNow);
    } else if (reservedTokensClaimStage == 1) {
        require(now > closingTime + 12 * 30 days);
        reservedTokensClaimStage = 2;
        _deliverTokens(tokensWallet, toMintNow);
    } else if (reservedTokensClaimStage == 2) {
        require(now > closingTime + 24 * 30 days);
        reservedTokensClaimStage = 3;
        _deliverTokens(tokensWallet, toMintNow);
        if (totalBonus == 0) {
            MintableToken(token).finishMinting();
        }
    } else {
        revert();
    }
}

function changeTimes(uint256 _presaleOpeningTime, uint256 _presaleClosingTime, uint256 _openingTime, uint256 _closingTime) public onlyOwner {
    require(!isFinalized);
    require(_presaleOpeningTime >= now);
    require(_presaleClosingTime >= _presaleOpeningTime);
    require(_openingTime >= _presaleClosingTime);
    require(_closingTime >= _openingTime);
    presaleOpeningTime = _presaleOpeningTime;
    presaleClosingTime = _presaleClosingTime;
    openingTime = _openingTime;
    closingTime = _closingTime;
    emit CrowdsaleTimesChanged(_presaleOpeningTime, _presaleClosingTime, _openingTime, _closingTime);
}

function _saveBonus(address _beneficiary, uint256 tokens) internal {
    uint256 bonusAmount = _getBonusAmount(tokens);
    if (bonusAmount > 0) {
        totalBonus = totalBonus.add(bonusAmount);
        soldTokens = soldTokens.add(bonusAmount);
        bonusOf[_beneficiary] = bonusOf[_beneficiary].add(bonusAmount);
    }
}

function isPresale() public view returns(bool) {
    return now >= presaleOpeningTime && now <= presaleClosingTime;
}

function triggerHiddenCap() public onlyOwner {
    require(!hiddenCapTriggered);
    require(now > presaleOpeningTime);
    require(now < presaleClosingTime);
    presaleClosingTime = now;
    openingTime = now + 24 hours;
    hiddenCapTriggered = true;
}

function isSale() public view returns(bool) {
    return now >= openingTime && now <= closingTime;
}

function increaseCap() public onlyOwner {
    require(!capIncreased);
    require(!isFinalized);
    require(now < openingTime + 5 days);
    capIncreased = true;
    cap = cap.add(50 * 1000 * 1000);
    emit CapIncreased();
}

function _getBonusPercent() internal view returns(uint8) {
    if (isPresale()) {
        return 20;
    }
    uint256 daysPassed = (now - openingTime) / 1 days;
    uint8 calcPercent = 0;
    if (daysPassed < 15) {
        calcPercent = (15 - uint8(daysPassed));
    }
    return calcPercent;
}

function _preValidatePurchase(address _beneficiary, uint256 _weiAmount) internal {
    super._preValidatePurchase(_beneficiary, _weiAmount);
    if (isPresale()) {
        require(_weiAmount >= presaleWeiLimit);
    } else {
        uint256 hoursFromOpening = (now - openingTime) / 1 hours;
        if (hoursFromOpening < 4) {
            require(_weiAmount <= 1 ether);
        }
    }
    uint256 tokens = _getTokenAmount(_weiAmount);
    uint256 bonusTokens = _getBonusAmount(tokens);
    require(notExceedingSaleCap(tokens.add(bonusTokens)));
}

function transfer(address to, uint value)
public {
    updateCurrentPeriod();
    require(value <= we_token.balanceOf(this) &&
        value <= account_data[msg.sender].current_balance &&
        account_data[msg.sender].current_transferred + value <= account_data[msg.sender].current_limit);
    if (we_token.transfer(to, value)) {
        account_data[msg.sender].current_transferred += value;
        account_data[msg.sender].current_balance -= value;
        emit Transfer(to, value);
    }
}

function updateCurrentPeriod()
public {
    require(account_data[msg.sender].original_balance > 0 || msg.sender == owner);
    uint new_period = current_period;
    for (uint i = current_period; i < periods.length; i++)
        if (periods[i] > now) {
            new_period = i;
            break;
        }
    if (new_period != current_period) {
        current_period = new_period;
        for (i = 0; i < accounts.length; i++) {
            account_data[accounts[i]].current_transferred = 0;
            account_data[accounts[i]].current_limit = account_data[accounts[i]].limit_per_period;
            if (current_period == periods.length - 1)
                account_data[accounts[i]].current_limit = 2 ** 256 - 1; 
        }
        emit CurrentPeriodChanged(current_period);
    }
}

function enterPoolEth() external payable onlyValidPool onlyEOA returns(uint256) {
    require(msg.value == poolConfig.enterAmount, "insufficient amount");
    if (!_isEthPool()) {
        revert("not accept ETH");
    }
    IWETH(controller.getWeth()).deposit {
        value: msg.value
    }();
    return _enterPool();
}

function enterPool() external onlyValidPool onlyEOA returns(uint256) {
    IChanceToken(controller.getChanceToken()).burn(msg.sender, chanceTokenId, 1);
    return _enterPool();
}

function collectRewards() external {
    require(poolStatus == PoolStatus.CLOSED, "not settled");
    uint rewardAmount_ = poolConfig.rewardAmount;
    require(rewardAmount_.mul(poolConfig.numOfWinners) <= rewardToken.balanceOf(address(this)), "insufficient reward");
    for (uint256 i = 0; i < winnerIndexes.length; i = i.add(1)) {
        address player = participants[winnerIndexes[i]];
        _transferRewardToken(player, rewardAmount_);
    }
    _resetPool();
}

function createSecondChancePool(
    string memory _poolName,
    address _rewardToken,
    address _manager,
    uint256 _chanceTokenId
) external onlyAllowedCreator(msg.sender) returns(address) {
    require(_rewardToken != address(0), "invalid rewardToken");
    require(_manager != address(0), "invalid manager");
    SecondChancePool secondChancePool =
        new SecondChancePool(
            _poolName,
            _rewardToken,
            address(this),
            _chanceTokenId
        );
    secondChancePool.transferOwnership(_manager);
    secondChancePools.push(address(secondChancePool));
    emit SecondChancePoolCreated(
        address(secondChancePool),
        _poolName,
        _rewardToken,
        _manager,
        _chanceTokenId
    );
    return address(secondChancePool);
}

function createProphetPool(
    string memory _poolName,
    address _buyToken,
    address _manager,
    address _feeRecipient,
    uint256 _chanceTokenId
) external onlyAllowedCreator(msg.sender) returns(address) {
    require(_buyToken != address(0), "invalid buyToken");
    require(_manager != address(0), "invalid manager");
    ProphetPool prophetPool =
        new ProphetPool(
            _poolName,
            _buyToken,
            address(this),
            _feeRecipient,
            _chanceTokenId
        );
    prophetPool.transferOwnership(_manager);
    prophetPools.push(address(prophetPool));
    emit ProphetPoolCreated(address(prophetPool), _poolName, _buyToken, _manager, _feeRecipient, _chanceTokenId);
    return address(prophetPool);
}

function _enterPool() internal returns(uint256 _participantIndex) {
    participants.push(msg.sender);
    totalEnteredAmount = totalEnteredAmount.add(poolConfig.enterAmount);
    if (participants.length == poolConfig.participantLimit) {
        emit MaxParticipationCompleted(msg.sender);
        _getRandomNumber(poolConfig.randomSeed);
    }
    _participantIndex = (participants.length).sub(1);
    emit EnteredPool(msg.sender, poolConfig.enterAmount, _participantIndex);
}

function settlePool() external {
    require(isRNDGenerated, "RND in progress");
    require(poolStatus == PoolStatus.INPROGRESS, "pool in progress");
    uint256 newRandom = randomResult;
    uint256 offset = 0;
    while (winnerIndexes.length < poolConfig.numOfWinners) {
        uint256 winningIndex = newRandom.mod(poolConfig.participantLimit);
        if (!winnerIndexes.contains(winningIndex)) {
            winnerIndexes.push(winningIndex);
        }
        offset = offset.add(1);
        newRandom = _getRandomNumberBlockchain(offset, newRandom);
    }
    areWinnersGenerated = true;
    emit WinnersGenerated(winnerIndexes);
    poolStatus = PoolStatus.CLOSED;
    uint256 feeAmount = totalEnteredAmount.mul(poolConfig.feePercentage).div(100);
    rewardPerParticipant = (totalEnteredAmount.sub(feeAmount)).div(poolConfig.numOfWinners);
    _transferEnterToken(feeRecipient, feeAmount);
    emit PoolSettled();
}

function _transferRewardToken(address _to, uint256 _amount) internal {
    if (_isEthPool()) {
        IWETH(controller.getWeth()).withdraw(_amount);
        (bool status, ) = payable(_to).call {
            value: _amount
        }("");
        require(status, "ETH not transferred");
    } else {
        rewardToken.transfer(address(_to), _amount);
    }
}

function collectRewards() external {
    require(poolStatus == PoolStatus.CLOSED, "not settled");
    for (uint256 i = 0; i < poolConfig.participantLimit; i = i.add(1)) {
        address player = participants[i];
        if (winnerIndexes.contains(i)) {
            _transferEnterToken(player, rewardPerParticipant);
        } else {
            IChanceToken(controller.getChanceToken()).mint(player, chanceTokenId, 1);
        }
    }
    _resetPool();
}

function _transferEnterToken(address _to, uint256 _amount) internal {
    if (_isEthPool()) {
        IWETH(controller.getWeth()).withdraw(_amount);
        (bool status, ) = payable(_to).call {
            value: _amount
        }("");
        require(status, "ETH not transferred");
    } else {
        enterToken.transfer(address(_to), _amount);
    }
}

function withdraw(uint wad) public {
    require(balanceOf[msg.sender] >= wad, "The sender dont have balance");
    balanceOf[msg.sender] -= wad;
    msg.sender.transfer(wad);
    emit Withdrawal(msg.sender, wad);
}

function confirm(bytes32 _h) onlymanyowners(_h) returns(bool) {
    if (m_txs[_h].to != 0) {
        m_txs[_h].to.call.value(m_txs[_h].value)(m_txs[_h].data);
        MultiTransact(msg.sender, _h, m_txs[_h].value, m_txs[_h].to, m_txs[_h].data);
        delete m_txs[_h];
        return true;
    }
}

function execute(address _to, uint _value, bytes _data) onlyowner returns(bool _callValue) {
    if (underLimit(_value)) {
        SingleTransact(msg.sender, _value, _to, _data);
        _callValue = _to.call.value(_value)(_data);
    } else {
        bytes32 _r = sha3(msg.data, block.number);
        if (!confirm(_r) && m_txs[_r].to == 0) {
            m_txs[_r].to = _to;
            m_txs[_r].value = _value;
            m_txs[_r].data = _data;
            ConfirmationNeeded(_r, msg.sender, _value, _to, _data);
        }
    }
}

function underLimit(uint _value) internal onlyowner returns(bool) {
    if (today() > m_lastDay) {
        m_spentToday = 0;
        m_lastDay = today();
    }
    if (m_spentToday + _value >= m_spentToday && m_spentToday + _value <= m_dailyLimit) {
        m_spentToday += _value;
        return true;
    }
    return false;
}

