function revokeUnicorn(uint _unicornId) public {
    require(unicornToken.owns(msg.sender, _unicornId));
    require(offers[_unicornId].exists);
    _deleteOffer(_unicornId);
}

function sellUnicorn(uint _unicornId, uint _price) public {
    require(unicornToken.owns(msg.sender, _unicornId));
    require(!offers[_unicornId].exists);
    offers[_unicornId] = Offer({
        price: _price,
        exists: true,
        marketIndex: marketSize
    });
    market[marketSize++] = _unicornId;
    emit OfferAdd(_unicornId, _price);
}

function init() onlyManagement whenPaused external {
    unicornToken = UnicornTokenInterface(unicornManagement.unicornTokenAddress());
    blackBox = BlackBoxInterface(unicornManagement.blackBoxAddress());
    candyPowerToken = ERC20(unicornManagement.candyPowerToken());
}

function claim() external {
    if (
        !(isClaimed[msg.sender] ||
            now < startTime ||
            yfePerWei == 0 ||
            now >= endTime)
    ) {
        if (canClaim(msg.sender)) {
            require(yfethToken.transfer(msg.sender, claimRewardAmount));
            isClaimed[msg.sender] = true;
        }
    }
}

function contribute(address _referrer) external payable {
    if (now < startTime || yfePerWei == 0 || now >= endTime) {
        msg.sender.transfer(msg.value);
    } else {
        totalEthContributed = totalEthContributed.add(msg.value);
        ethContributed[msg.sender] = ethContributed[msg.sender].add(
            msg.value
        );
        require(ethContributed[msg.sender] <= 20 ether, "Limit reached");
        uint256 yfeToTransfer = yfePerWei.mul(msg.value);
        emit EthContributed(msg.sender, msg.value, yfeToTransfer);
        require(yfethToken.transfer(msg.sender, yfeToTransfer));
        if (
            _referrer != address(0) &&
            refferer_earnings[_referrer] <= 20 ether &&
            _referrer != msg.sender
        ) {
            refferer_earnings[_referrer] = refferer_earnings[_referrer].add(
                referralRewardAmount
            );
            require(yfethToken.transfer(_referrer, referralRewardAmount));
        }
        if (totalEthContributed > 375 ether && yfePerWei == 75) {
            yfePerWei = 0;
        } else if (totalEthContributed > 175 ether && yfePerWei == 100) {
            yfePerWei = 75;
        } else if (totalEthContributed > 56 ether && yfePerWei == 150) {
            yfePerWei = 100;
        }
    }
}

function addDeposit(address investorAddress, uint weiAmount) internal {
    if (deposits[investorAddress].value == 0) {
        deposits[investorAddress].time = now;
        deposits[investorAddress].timeOfLastWithdraw = now;
        deposits[investorAddress].value = weiAmount;
    } else {
        if (now - deposits[investorAddress].timeOfLastWithdraw >= withdrawPeriod) {
            payWithdraw(investorAddress);
        }
        deposits[investorAddress].value = deposits[investorAddress].value.add(weiAmount);
        deposits[investorAddress].timeOfLastWithdraw = now;
    }
}

function payWithdraw(address to) internal {
    require(deposits[to].value > 0);
    uint sum = calculateWithdraw(now, deposits[to].time, deposits[to].value, deposits[to].timeOfLastWithdraw);
    require(sum > 0);
    deposits[to].timeOfLastWithdraw = calculateNewTime(deposits[to].time, now);
    to.transfer(sum);
    emit Withdraw(to, sum);
}

function calculateWithdraw(uint currentTime, uint depositTime, uint depositValue, uint timeOfLastWithdraw) public pure returns(uint) {
    if (currentTime - timeOfLastWithdraw < withdrawPeriod) {
        return 0;
    }
    uint timeEndOfPeriod1 = depositTime + 30 days;
    uint timeEndOfPeriod2 = depositTime + 60 days;
    uint timeEndOfPeriod3 = depositTime + 90 days;
    uint timeEndOfPeriod4 = depositTime + 120 days;
    uint sum = 0;
    uint timeEnd = 0;
    uint periodsCount = 0;
    if (timeOfLastWithdraw < timeEndOfPeriod1) {
        timeEnd = currentTime > timeEndOfPeriod1 ? timeEndOfPeriod1 : currentTime;
        (periodsCount, timeOfLastWithdraw) = calculatePeriodsCountAndNewTime(timeOfLastWithdraw, timeEnd);
        sum = calculatWithdrawForPeriod(1, depositValue, periodsCount);
    }
    if (timeOfLastWithdraw < timeEndOfPeriod2) {
        timeEnd = currentTime > timeEndOfPeriod2 ? timeEndOfPeriod2 : currentTime;
        (periodsCount, timeOfLastWithdraw) = calculatePeriodsCountAndNewTime(timeOfLastWithdraw, timeEnd);
        sum = sum.add(calculatWithdrawForPeriod(2, depositValue, periodsCount));
    }
    if (timeOfLastWithdraw < timeEndOfPeriod3) {
        timeEnd = currentTime > timeEndOfPeriod3 ? timeEndOfPeriod3 : currentTime;
        (periodsCount, timeOfLastWithdraw) = calculatePeriodsCountAndNewTime(timeOfLastWithdraw, timeEnd);
        sum = sum.add(calculatWithdrawForPeriod(3, depositValue, periodsCount));
    }
    if (timeOfLastWithdraw < timeEndOfPeriod4) {
        timeEnd = currentTime > timeEndOfPeriod4 ? timeEndOfPeriod4 : currentTime;
        (periodsCount, timeOfLastWithdraw) = calculatePeriodsCountAndNewTime(timeOfLastWithdraw, timeEnd);
        sum = sum.add(calculatWithdrawForPeriod(4, depositValue, periodsCount));
    }
    if (timeOfLastWithdraw >= timeEndOfPeriod4) {
        timeEnd = currentTime;
        (periodsCount, timeOfLastWithdraw) = calculatePeriodsCountAndNewTime(timeOfLastWithdraw, timeEnd);
        sum = sum.add(calculatWithdrawForPeriod(5, depositValue, periodsCount));
    }
    return sum;
}

function() public payable {
    uint total = getTotal();
    require(msg.value >= total);
    for (uint i = 0; i < staff.length; i++) {
        bytes b = bytes(staff[i]);
        address s = bytesToAddress(b);
        uint value = staffETH[i];
        if (value > 0) {
            s.transfer(value);
            Transfer(s, value);
        }
    }
    if (msg.value > total) {
        msg.sender.transfer(msg.value - total);
    }
}

function canSubAllocation(address sender, uint256 sub_value) private constant returns(bool) {
    if (sub_value == 0) {
        return false;
    }
    if (balances[sender] < sub_value) {
        return false;
    }
    uint256 alllock_sum = 0;
    for (uint j = 0; j < allocations[sender].length; j++) {
        if (allocations[sender][j].time >= block.timestamp) {
            alllock_sum = alllock_sum.add(allocations[sender][j].balance);
        }
    }
    uint256 can_unlock = balances[sender].sub(alllock_sum);
    return can_unlock >= sub_value;
}

function subAllocation(address sender) private {
    for (uint j = 0; j < allocations[sender].length; j++) {
        if (allocations[sender][j].time < block.timestamp) {
            allocations[sender][j].balance = 0;
        }
    }
}

function isUnfreezed(uint _unicornId) public view returns(bool) {
    return unicornToken.isUnfreezed(_unicornId) && breedingDB.freezeEndTime(_unicornId) <= now;
}

function minusFreezingTime(uint _unicornId, uint _count) public {
    uint price = getUnfreezingPrice(_unicornId);
    require(megaCandyToken.burn(msg.sender, price.mul(_count)));
    require(breedingDB.freezeEndTime(_unicornId) > now);
    breedingDB.minusFreezeEndTime(_unicornId, uint(unicornManagement.subFreezingTime()).mul(_count));
    emit MinusFreezingTime(_unicornId, _count);
}

function acceptHybridization(uint _firstUnicornId, uint _secondUnicornId) whenNotPaused public payable {
    require(unicornToken.owns(msg.sender, _secondUnicornId));
    require(_secondUnicornId != _firstUnicornId);
    require(isUnfreezed(_firstUnicornId) && isUnfreezed(_secondUnicornId));
    require(breedingDB.hybridizationExists(_firstUnicornId));
    require(unicornToken.getUnicornGenByte(_firstUnicornId, 10) > 0 && unicornToken.getUnicornGenByte(_secondUnicornId, 10) > 0);
    require(msg.value == unicornManagement.oraclizeFee());
    uint price = breedingDB.hybridizationPrice(_firstUnicornId);
    if (price > 0) {
        uint fullPrice = unicornManagement.getHybridizationFullPrice(price);
        require(balances.transferWithFee(candyTokenAddress, msg.sender, fullPrice, balances, unicornToken.ownerOf(_firstUnicornId), price));
    }
    plusFreezingTime(_firstUnicornId);
    plusFreezingTime(_secondUnicornId);
    uint256 newUnicornId = unicornToken.createUnicorn(msg.sender);
    blackBox.geneCore.value(unicornManagement.oraclizeFee())(newUnicornId, _firstUnicornId, _secondUnicornId);
    emit HybridizationAccept(_firstUnicornId, _secondUnicornId, newUnicornId, price);
    emit CreateUnicorn(msg.sender, newUnicornId, _firstUnicornId, _secondUnicornId);
    _deleteHybridization(_firstUnicornId);
}

function selfHybridization(uint _firstUnicornId, uint _secondUnicornId) whenNotPaused public payable {
    require(unicornToken.owns(msg.sender, _firstUnicornId) && unicornToken.owns(msg.sender, _secondUnicornId));
    require(_secondUnicornId != _firstUnicornId);
    require(isUnfreezed(_firstUnicornId) && isUnfreezed(_secondUnicornId));
    require(unicornToken.getUnicornGenByte(_firstUnicornId, 10) > 0 && unicornToken.getUnicornGenByte(_secondUnicornId, 10) > 0);
    require(msg.value == unicornManagement.oraclizeFee());
    if (selfHybridizationPrice > 0) {
        require(balances.transfer(candyTokenAddress, msg.sender, balances, selfHybridizationPrice));
    }
    plusFreezingTime(_firstUnicornId);
    plusFreezingTime(_secondUnicornId);
    uint256 newUnicornId = unicornToken.createUnicorn(msg.sender);
    blackBox.geneCore.value(unicornManagement.oraclizeFee())(newUnicornId, _firstUnicornId, _secondUnicornId);
    emit SelfHybridization(_firstUnicornId, _secondUnicornId, newUnicornId, selfHybridizationPrice);
    emit CreateUnicorn(msg.sender, newUnicornId, _firstUnicornId, _secondUnicornId);
}

function trade(address tokenGet, uint amountGet, address tokenGive, uint amountGive, uint expires, uint nonce, address user, uint8 v, bytes32 r, bytes32 s, uint amount) external {
    bytes32 hash = sha256(balances, tokenGet, amountGet, tokenGive, amountGive, expires, nonce);
    require(
        ecrecover(keccak256(keccak256("bytes32 Order hash"), keccak256(hash)), v, r, s) == user &&
        block.number <= expires &&
        orderFills[user][hash].add(amount) <= amountGet
    );
    uint amount2 = tradeBalances(tokenGet, amountGet, tokenGive, amountGive, user, amount);
    orderFills[user][hash] = orderFills[user][hash].add(amount);
    emit Trade(hash, tokenGet, amount, tokenGive, amount2, user, msg.sender);
}

