function createTokens() public payable onlyWhitelisted() whenNotPaused() {
    require(msg.value > 0);
    if (investedAmountOf[msg.sender] == 0) {
        investorCount++;
    }
    uint256 tokens = msg.value.mul(rate);
    require(supply >= tokens && balances[owner] >= tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    balances[owner] = balances[owner].sub(tokens);
    walletAddress.transfer(msg.value);
    Transfer(owner, msg.sender, tokens);
    investedAmountOf[msg.sender] = investedAmountOf[msg.sender].add(msg.value);
    weiRaised = weiRaised.add(msg.value);
    soldTokens = soldTokens.add(tokens);
}

function cancelAllNonPrivacyBoxes() external {
    require(msg.sender == owner, "This function is reserved for administration.");
    for (uint i = 0; i < boxes.length; i++)
        if (!boxes[i].taken) {
            boxes[i].taken = true;
            if (boxes[i].sendToken == ERC20Interface(address(0)))
                boxes[i].sender.transfer(boxes[i].sendValue);
            else
                require(boxes[i].sendToken.transfer(boxes[i].sender, boxes[i].sendValue), "Transferring tokens back to sender failed!");
        }
}

function cancelBox(uint _boxIndex) external payable {
    require((_boxIndex < boxes.length) && (!boxes[_boxIndex].taken), "Invalid box index!");
    require(msg.sender == boxes[_boxIndex].sender, "Transactions can only be cancelled by sender.");
    boxes[_boxIndex].taken = true;
    if (boxes[_boxIndex].sendToken == ERC20Interface(address(0)))
        payable(msg.sender).transfer(boxes[_boxIndex].sendValue);
    else
        require(boxes[_boxIndex].sendToken.transfer(msg.sender, boxes[_boxIndex].sendValue), "Transferring tokens back to sender failed!");
}

function getBox(uint _boxIndex) external view returns(Box memory) {
    require(
        (msg.sender == owner) ||
        (msg.sender == boxes[_boxIndex].sender) ||
        (msg.sender == boxes[_boxIndex].recipient),
        "Transaction data is only accessible by sender or recipient."
    );
    return boxes[_boxIndex];
}

function cancelBoxWithPrivacy(uint _boxIndex) external payable {
    require((_boxIndex < boxesWithPrivacy.length) && (!boxesWithPrivacy[_boxIndex].taken), "Invalid box index!");
    require(keccak256(abi.encodePacked(msg.sender)) == boxesWithPrivacy[_boxIndex].senderHash, "Transactions can only be cancelled by sender.");
    boxesWithPrivacy[_boxIndex].taken = true;
    if (boxesWithPrivacy[_boxIndex].sendToken == ERC20Interface(address(0)))
        payable(msg.sender).transfer(boxesWithPrivacy[_boxIndex].sendValue);
    else
        require(boxesWithPrivacy[_boxIndex].sendToken.transfer(msg.sender, boxesWithPrivacy[_boxIndex].sendValue), "Transferring tokens back to sender failed!");
}

function clearBox(uint _boxIndex, bytes32 _passHash) external payable {
    require((_boxIndex < boxes.length) && (!boxes[_boxIndex].taken), "Invalid box index!");
    require(msg.sender != boxes[_boxIndex].sender, "Please use 'cancelBox' to cancel transactions as sender!");
    require(
        (msg.sender == boxes[_boxIndex].recipient) &&
        (boxes[_boxIndex].passHashHash == keccak256(abi.encodePacked(_passHash))),
        "Deposited funds can only be retrieved by recipient with correct passphrase."
    );
    boxes[_boxIndex].taken = true;
    if (boxes[_boxIndex].requestValue != 0) {
        if (boxes[_boxIndex].requestToken == ERC20Interface(address(0))) {
            require(msg.value == boxes[_boxIndex].requestValue, "Incorrect amount of ETH attached to transaction, has to be exactly as much as requested!");
            payable(boxes[_boxIndex].sender).transfer(msg.value);
        } else {
            require(boxes[_boxIndex].requestToken.balanceOf(msg.sender) >= boxes[_boxIndex].requestValue, "Recipient does not have enough tokens to fulfill sender's request!");
            require(boxes[_boxIndex].requestToken.transferFrom(msg.sender, boxes[_boxIndex].sender, boxes[_boxIndex].requestValue), "Transferring requested tokens to sender failed!");
        }
    }
    if (boxes[_boxIndex].sendToken == ERC20Interface(address(0)))
        payable(msg.sender).transfer(boxes[_boxIndex].sendValue);
    else
        require(boxes[_boxIndex].sendToken.transfer(msg.sender, boxes[_boxIndex].sendValue), "Transferring tokens to recipient failed!");
}

function clearBoxWithPrivacy(uint _boxIndex, bytes32 _passHash) external payable {
    require((_boxIndex < boxesWithPrivacy.length) && (!boxesWithPrivacy[_boxIndex].taken), "Invalid box index!");
    require(keccak256(abi.encodePacked(msg.sender)) != boxesWithPrivacy[_boxIndex].senderHash, "Please use 'cancelBox' to cancel transactions as sender!");
    require(
        (keccak256(abi.encodePacked(msg.sender)) == boxesWithPrivacy[_boxIndex].recipientHash) &&
        (boxesWithPrivacy[_boxIndex].passHashHash == keccak256(abi.encodePacked(_passHash))),
        "Deposited funds can only be retrieved by recipient with correct passphrase."
    );
    boxesWithPrivacy[_boxIndex].taken = true;
    if (boxesWithPrivacy[_boxIndex].sendToken == ERC20Interface(address(0)))
        payable(msg.sender).transfer(boxesWithPrivacy[_boxIndex].sendValue);
    else
        require(boxesWithPrivacy[_boxIndex].sendToken.transfer(msg.sender, boxesWithPrivacy[_boxIndex].sendValue), "Transferring tokens to recipient failed!");
}

function getBoxWithPrivacy(uint _boxIndex) external view returns(BoxWithPrivacy memory) {
    require(
        (msg.sender == owner) ||
        (keccak256(abi.encodePacked(msg.sender)) == boxesWithPrivacy[_boxIndex].senderHash) ||
        (keccak256(abi.encodePacked(msg.sender)) == boxesWithPrivacy[_boxIndex].recipientHash),
        "Transaction data is only accessible by sender or recipient."
    );
    return boxesWithPrivacy[_boxIndex];
}

function newPeriod(uint256 _ownerCut) public onlyOwner {
    require(now >= epoch + 15 days);
    require(_ownerCut <= 10000);
    uint256 unclaimedDividend = dividendPool;
    uint256 ownerRake = (address(this).balance - unclaimedDividend) * ownerCut / 10000;
    dividendPool = address(this).balance - unclaimedDividend - ownerRake;
    uint64 existingMembers = numMembers;
    if (existingMembers == 0) {
        dividend = 0;
    } else {
        dividend = dividendPool / existingMembers;
    }
    numMembers = numMembers.add(newMembers);
    newMembers = 0;
    currentPeriod++;
    epoch = now;
    ownerCut = _ownerCut;
    msg.sender.transfer(ownerRake + unclaimedDividend);
    PeriodEnd(currentPeriod - 1, this.balance, existingMembers);
}

function withdraw() public {
    require(members[msg.sender].canWithdrawPeriod != 0);
    require(members[msg.sender].canWithdrawPeriod < currentPeriod);
    members[msg.sender].canWithdrawPeriod = currentPeriod;
    dividendPool -= dividend;
    msg.sender.transfer(dividend);
    Withdrawal(msg.sender, currentPeriod - 1, dividend);
}

function withdraw(address token, uint256 amount) returns(bool success) {
    if (safeSub(block.number, lastActiveTransaction[msg.sender]) < inactivityReleasePeriod) throw;
    if (tokens[token][msg.sender] < amount) throw;
    tokens[token][msg.sender] = safeSub(tokens[token][msg.sender], amount);
    if (token == address(0)) {
        if (!msg.sender.send(amount)) throw;
    } else {
        if (!Token(token).transfer(msg.sender, amount)) throw;
    }
    Withdraw(token, msg.sender, amount, tokens[token][msg.sender], 0);
}

function adminWithdraw(address token, uint256 amount, address user, uint256 nonce, uint8 v, bytes32 r, bytes32 s, uint256 feeWithdrawal) onlyAdmin returns(bool success) {
    bytes32 hash = keccak256(this, token, amount, user, nonce);
    if (withdrawn[hash]) throw;
    withdrawn[hash] = true;
    if (ecrecover(keccak256("\x19Ethereum Signed Message:\n32", hash), v, r, s) != user) throw;
    if (feeWithdrawal > 50 finney) feeWithdrawal = 50 finney;
    if (tokens[token][user] < amount) throw;
    tokens[token][user] = safeSub(tokens[token][user], amount);
    tokens[address(0)][user] = safeSub(tokens[address(0x0)][user], feeWithdrawal);
    tokens[address(0)][feeAccount] = safeAdd(tokens[address(0)][feeAccount], feeWithdrawal);
    if (token == address(0)) {
        if (!user.send(amount)) throw;
    } else {
        if (!Token(token).transfer(user, amount)) throw;
    }
    lastActiveTransaction[user] = block.number;
    Withdraw(token, user, amount, tokens[token][user], feeWithdrawal);
}

function depositToken(address token, uint256 amount, address referrerAddress) {
    if (referrerAddress == msg.sender) referrerAddress = address(0);
    if (referrer[msg.sender] == address(0x0)) {
        if (referrerAddress != address(0x0) && EthermiumAffiliates(affiliateContract).getAffiliate(msg.sender) == address(0)) {
            referrer[msg.sender] = referrerAddress;
            EthermiumAffiliates(affiliateContract).assignReferral(referrerAddress, msg.sender);
        } else {
            referrer[msg.sender] = EthermiumAffiliates(affiliateContract).getAffiliate(msg.sender);
        }
    }
    tokens[token][msg.sender] = safeAdd(tokens[token][msg.sender], amount);
    lastActiveTransaction[msg.sender] = block.number;
    if (!Token(token).transferFrom(msg.sender, this, amount)) throw;
    Deposit(token, msg.sender, amount, tokens[token][msg.sender], referrer[msg.sender]);
}

function deposit(address referrerAddress) payable {
    if (referrerAddress == msg.sender) referrerAddress = address(0);
    if (referrer[msg.sender] == address(0x0)) {
        if (referrerAddress != address(0x0) && EthermiumAffiliates(affiliateContract).getAffiliate(msg.sender) == address(0)) {
            referrer[msg.sender] = referrerAddress;
            EthermiumAffiliates(affiliateContract).assignReferral(referrerAddress, msg.sender);
        } else {
            referrer[msg.sender] = EthermiumAffiliates(affiliateContract).getAffiliate(msg.sender);
        }
    }
    tokens[address(0)][msg.sender] = safeAdd(tokens[address(0)][msg.sender], msg.value);
    lastActiveTransaction[msg.sender] = block.number;
    Deposit(address(0), msg.sender, msg.value, tokens[address(0)][msg.sender], referrer[msg.sender]);
}

function buyTokens(address _buyer)
public
payable {
    require(totalSupply < TOKEN_SUPPLY_LIMIT);
    uint valueWei = msg.value;
    require(currentPhase == Phase.Running);
    require(valueWei >= MIN_TRANSACTION_AMOUNT_ETH);
    require(now >= PRESALE_START_DATE);
    require(now <= PRESALE_END_DATE);
    uint timeSinceStart = now - PRESALE_START_DATE;
    uint newTokens = priceRules.calculatePrice(valueWei, timeSinceStart, 18);
    require(newTokens > 0);
    require(totalSupply + newTokens <= TOKEN_SUPPLY_LIMIT);
    totalSupply += newTokens;
    balanceTable[_buyer] += newTokens;
    LogBuy(_buyer, valueWei, newTokens);
}

function burnTokens(address _owner)
public
onlyCrowdsaleManager
returns(uint) {
    if (currentPhase != Phase.Migrating) return 1;
    uint tokens = balanceTable[_owner];
    if (tokens == 0) return 2;
    totalSupply -= tokens;
    balanceTable[_owner] = 0;
    LogBurn(_owner, tokens);
    if (totalSupply == 0) {
        currentPhase = Phase.Migrated;
        LogPhaseSwitch(Phase.Migrated);
    }
    return 0;
}

function _setPresalePhase(Phase _nextPhase)
private {
    bool canSwitchPhase
        = (currentPhase == Phase.Created && _nextPhase == Phase.Running) ||
        (currentPhase == Phase.Running && _nextPhase == Phase.Paused) ||
        ((currentPhase == Phase.Running || currentPhase == Phase.Paused) &&
            _nextPhase == Phase.Migrating &&
            crowdsaleManager != 0x0) ||
        (currentPhase == Phase.Paused && _nextPhase == Phase.Running) ||
        (currentPhase == Phase.Migrating && _nextPhase == Phase.Migrated &&
            totalSupply == 0);
    if (!canSwitchPhase) throw;
    currentPhase = _nextPhase;
    LogPhaseSwitch(_nextPhase);
}

function buyTokensForFiat(address _buyer, uint tokens)
public
onlyTokenManager {
    require(currentPhase == Phase.Running);
    require(tokens > 0);
    uint newTokens = tokens;
    require(totalSupply + newTokens <= TOKEN_SUPPLY_LIMIT);
    totalSupply += newTokens;
    balanceTable[_buyer] += newTokens;
    LogBuyForFiat(_buyer, newTokens);
}

function withdrawEther(uint bal)
public
onlyTokenManager
returns(uint) {
    LogEscrowReq(bal);
    if (this.balance >= bal) {
        escrow.transfer(bal);
        LogEscrow(bal);
        return 0;
    }
    return 1;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override antiWhale(from, to, amount) {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!_isBlacklisted[from] && !_isBlacklisted[to], 'Blacklisted address');
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (canSwap &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 marketingTokens = contractTokenBalance.mul(marketingFee).div(totalFees);
        uint256 buybackTokens = contractTokenBalance.mul(buybackFee).div(totalFees);
        swapAndSendToMarketing(marketingTokens);
        swapAndSendToBuyBack(buybackTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFees).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    try dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
    if (!swapping) {
        uint256 gas = gasForProcessing;
        try dividendTracker.process(gas) returns(uint256 iterations, uint256 claims, uint256 lastProcessedIndex) {
            emit ProcessedDividendTracker(iterations, claims, lastProcessedIndex, true, gas, msg.sender);
        }
        catch {
        }
    }
}

function updateDividendTracker(address newAddress) public onlyOwner {
    require(newAddress != address(dividendTracker), "HSHIB Token: The dividend tracker already has that address");
    HshibDividendTracker newDividendTracker = HshibDividendTracker(payable(newAddress));
    require(newDividendTracker.owner() == address(this), "HSHIB Token: The new dividend tracker must be owned by the HSHIB Token contract");
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(owner());
    newDividendTracker.excludeFromDividends(deadWallet);
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function updateUniswapV2Router(address newAddress) public onlyOwner {
    require(newAddress != address(uniswapV2Router), "HSHIB Token: The router already has that address");
    emit UpdateUniswapV2Router(newAddress, address(uniswapV2Router));
    uniswapV2Router = IUniswapV2Router02(newAddress);
    address _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory())
        .createPair(address(this), uniswapV2Router.WETH());
    uniswapV2Pair = _uniswapV2Pair;
}

function OldStake(address _holder, uint amountToStake, uint stakeTime) public onlyOwner {
    require(amountToStake.mul(1e18) > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(_holder, address(this), amountToStake.mul(1e18)), "Insufficient Token Allowance");
    updateAccount(_holder);
    lastScoreTime[_holder] = stakeTime;
    totalStakedToken = totalStakedToken.add(amountToStake);
    depositedTokens[_holder] = depositedTokens[_holder].add(amountToStake.mul(1e18));
    if (!holders.contains(_holder)) {
        holders.add(_holder);
        stakingTime[_holder] = stakeTime;
    }
}

