function purchase() public payable isStarted {
    if (now > lastAction + timeBeforeJackpot &&
        jackpotLastQualified != 0x0) {
        claim();
        if (msg.value > 0) {
            msg.sender.transfer(msg.value);
        }
        return;
    }
    if (jackpotBalance <= 1 ether) {
        require(msg.value >= minMinBuyETH); 
        require(msg.value <= minMaxBuyETH); 
    } else {
        uint256 purchaseMin = SafeMath.mul(msg.value, minBuy);
        uint256 purchaseMax = SafeMath.mul(msg.value, maxBuy);
        require(purchaseMin >= jackpotBalance);
        require(purchaseMax <= jackpotBalance);
    }
    uint256 valueAfterTax = SafeMath.div(SafeMath.mul(msg.value, buyFee), 100); 
    uint256 potFee = SafeMath.sub(msg.value, valueAfterTax); 
    jackpotBalance += potFee; 
    jackpotLastQualified = msg.sender; 
    lastAction = now; 
    timeBeforeJackpot += timeIncreasePerTx; 
    uint256 valueMultiplied = SafeMath.mul(msg.value, 2); 
    games[gameIndex].gameTotalInvested += msg.value;
    games[gameIndex].gameTotalBacklog += valueMultiplied;
    games[gameIndex].totalInvested[msg.sender] += msg.value;
    games[gameIndex].totalValue[msg.sender] += valueMultiplied;
    games[gameIndex].buyIns.push(BuyIn({
        value: valueMultiplied,
        owner: msg.sender
    }));
    emit Purchase(msg.value, msg.sender);
    while (games[gameIndex].index < games[gameIndex].buyIns.length &&
        valueAfterTax > 0) {
        BuyIn storage buyIn = games[gameIndex].buyIns[games[gameIndex].index];
        if (valueAfterTax < buyIn.value) {
            buyIn.owner.transfer(valueAfterTax);
            games[gameIndex].gameTotalBacklog -= valueAfterTax;
            games[gameIndex].gameTotalPaidOut += valueAfterTax;
            games[gameIndex].totalPaidOut[buyIn.owner] += valueAfterTax;
            games[gameIndex].totalValue[buyIn.owner] -= valueAfterTax;
            buyIn.value -= valueAfterTax;
            valueAfterTax = 0;
        } else {
            buyIn.owner.transfer(buyIn.value);
            games[gameIndex].gameTotalBacklog -= buyIn.value;
            games[gameIndex].gameTotalPaidOut += buyIn.value;
            games[gameIndex].totalPaidOut[buyIn.owner] += buyIn.value;
            games[gameIndex].totalValue[buyIn.owner] -= buyIn.value;
            valueAfterTax -= buyIn.value;
            buyIn.value = 0;
            games[gameIndex].index++;
        }
    }
}

function claim() public payable isStarted {
    require(now > lastAction + timeBeforeJackpot);
    require(jackpotLastQualified != 0x0); 
    uint256 reseed = SafeMath.div(SafeMath.mul(jackpotBalance, gameReseeds[jackpotCount]), 100);
    uint256 payout = jackpotBalance - reseed;
    jackpotLastQualified.transfer(payout); 
    jackpotBalance = reseed;
    jackpotLastWinner = jackpotLastQualified;
    jackpotLastPayout = payout;
    games[gameIndex].winners.push(jackpotLastQualified);
    games[gameIndex].winnerPayouts.push(payout);
    timeBeforeJackpot = timeBeforeJackpotReset; 
    jackpotLastQualified = 0x0; 
    if (jackpotCount == gameReseeds.length - 1) {
        gameStartTime = now + timeBetweenGames; 
        lastAction = gameStartTime; 
        gameIndex += 1; 
        jackpotCount = 0; 
    } else {
        lastAction = now + timeBetweenRounds;
        roundStartTime = lastAction;
        jackpotCount += 1;
    }
}

function changeStartTime(uint256 _time) public onlyContractOwner {
    require(now < _time); 
    gameStartTime = _time;
    lastAction = gameStartTime; 
}

function bid()
public
payable
atStage(Stages.AuctionStarted) {
    require(msg.value > 0);
    assert(bids[msg.sender] + msg.value >= msg.value);
    uint missingFunds = missingFundsToEndAuction();
    require(msg.value <= missingFunds);
    bids[msg.sender] += msg.value;
    receivedWei += msg.value;
    walletAddress.transfer(msg.value);
    BidSubmission(msg.sender, msg.value, missingFunds, block.timestamp);
    assert(receivedWei >= msg.value);
}

function proxyClaimTokens(address receiverAddress)
public
atStage(Stages.AuctionEnded)
returns(bool) {
    require(now > finalizedTime + TOKEN_CLAIM_WAITING_PERIOD);
    require(receiverAddress != 0x0);
    if (bids[receiverAddress] == 0) {
        return false;
    }
    uint num = (tokenMultiplier * bids[receiverAddress]) / finalPrice;
    uint auctionTokensBalance = token.balanceOf(address(this));
    if (num > auctionTokensBalance) {
        num = auctionTokensBalance;
    }
    fundsClaimed += bids[receiverAddress];
    bids[receiverAddress] = 0;
    require(token.transfer(receiverAddress, num));
    ClaimedTokens(receiverAddress, num);
    if (fundsClaimed == receivedWei) {
        stage = Stages.TokensDistributed;
        TokensDistributed();
    }
    assert(token.balanceOf(receiverAddress) >= num);
    assert(bids[receiverAddress] == 0);
    return true;
}

function setup(address _tokenAddress) public isOwner atStage(Stages.AuctionDeployed) {
    require(_tokenAddress != 0x0);
    token = LetsbetToken(_tokenAddress);
    tokensAuctioned = token.balanceOf(address(this));
    tokenMultiplier = 10 ** uint(token.decimals());
    stage = Stages.AuctionSetUp;
    Setup();
}

function finalizeAuction() public isOwner atStage(Stages.AuctionStarted) {
    uint missingFunds = missingFundsToEndAuction();
    require(missingFunds == 0 || now > endTimeOfBids);
    finalPrice = tokenMultiplier * receivedWei / tokensAuctioned;
    finalizedTime = now;
    stage = Stages.AuctionEnded;
    AuctionEnded(finalPrice);
    assert(finalPrice > 0);
}

function changeSettings(
    uint _startPrice,
    uint _priceDecreaseRate,
    uint _endTimeOfBids
)
internal {
    require(stage == Stages.AuctionDeployed || stage == Stages.AuctionSetUp);
    require(_startPrice > 0);
    require(_priceDecreaseRate > 0);
    require(_endTimeOfBids > now);
    endTimeOfBids = _endTimeOfBids;
    startPrice = _startPrice;
    priceDecreaseRate = _priceDecreaseRate;
}

function buyTokenFrom(address _seller, address _tokenAddress, uint256 _buyerTokenPrice) public payable returns(bool _result) {
    require(_seller != 0x0);
    require(_tokenAddress != 0x0);
    require(_buyerTokenPrice > 0);
    require(!_isBuying); 
    _isBuying = true; 
    userEtherOf[msg.sender] += msg.value;
    if (userEtherOf[msg.sender] == 0) {
        _isBuying = false;
        return;
    }
    ERC20Token token = ERC20Token(_tokenAddress);
    var sellingAmount = token.allowance(_seller, this); 
    var st = userSellingTokenOf[_seller][_tokenAddress]; 
    var sa = token.balanceOf(_seller); 
    bool bigger = false;
    if (sa < sellingAmount) { 
        sellingAmount = sa;
        bigger = true;
    }
    if (st.price > 0 && st.lineTime > now && sellingAmount > 0 && !st.cancel) {
        if (_buyerTokenPrice < st.price) { 
            OnBuyToken(userEtherOf[msg.sender], msg.sender, _seller, _tokenAddress, 0, _buyerTokenPrice, sellingAmount);
            _result = false;
            _isBuying = false;
            return;
        }
        uint256 canTokenAmount = userEtherOf[msg.sender] / st.price;
        if (canTokenAmount > 0 && canTokenAmount * st.price > userEtherOf[msg.sender]) {
            canTokenAmount -= 1;
        }
        if (canTokenAmount == 0) {
            OnBuyToken(userEtherOf[msg.sender], msg.sender, _seller, _tokenAddress, 0, st.price, sellingAmount);
            _result = false;
            _isBuying = false;
            return;
        }
        if (canTokenAmount > sellingAmount) {
            canTokenAmount = sellingAmount;
        }
        var etherAmount = canTokenAmount * st.price;
        userEtherOf[msg.sender] -= etherAmount; 
        require(userEtherOf[msg.sender] >= 0); 
        token.transferFrom(_seller, msg.sender, canTokenAmount); 
        if (userEtherOf[_seller] >= sellerGuaranteeEther) { 
            _seller.transfer(etherAmount); 
        } else { 
            userEtherOf[_seller] += etherAmount; 
        }
        st.soldoutAmount += canTokenAmount; 
        st.thisAmount = token.allowance(_seller, this); 
        OnBuyToken(userEtherOf[msg.sender], msg.sender, _seller, _tokenAddress, canTokenAmount, st.price, st.thisAmount);
        _result = true;
    } else {
        _result = false;
        OnBuyToken(userEtherOf[msg.sender], msg.sender, _seller, _tokenAddress, 0, _buyerTokenPrice, sellingAmount);
    }
    if (bigger && sellerGuaranteeEther > 0) { 
        if (checkSellerGuarantee(_seller)) { 
            userEtherOf[owner] += sellerGuaranteeEther / 2;
            userEtherOf[msg.sender] += sellerGuaranteeEther / 2;
            userEtherOf[_seller] -= sellerGuaranteeEther;
        } else if (userEtherOf[_seller] > 0) 
        {
            userEtherOf[owner] += userEtherOf[_seller] / 2;
            userEtherOf[msg.sender] += userEtherOf[_seller] - userEtherOf[_seller] / 2;
            userEtherOf[_seller] = 0;
        }
    }
    _isBuying = false; 
    return;
}

function setSellerGuarantee(bool _has, uint256 _gurateeEther) public onlyOwner {
    require(now - createTime > 1 years); 
    require(_gurateeEther < 0.1 ether); 
