function validPurchase(uint256 _tokens) internal view returns(bool) {
    bool withinCap = tokensSent.add(_tokens) <= hardCap;
    return super.validPurchase(_tokens) && withinCap;
}

function hasClosed() public view returns(bool) {
    bool remainValue = cap.sub(weiRaised) < 200000000000000000;
    return super.hasClosed() || remainValue;
}

function init() public onlyOwner {
    require(!initialized);
    initialized = true;
    if (PAUSED) {
        MainToken(token).pause();
    }
    address[1] memory addresses = [address(0x66a6983703928ba3523e9f3850750b847ffbfa03)];
    uint[1] memory amounts = [uint(6000000000000000000000000000)];
    uint64[1] memory freezes = [uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
        if (freezes[i] == 0) {
            MainToken(token).mint(addresses[i], amounts[i]);
        } else {
            MainToken(token).mintAndFreeze(addresses[i], amounts[i], freezes[i]);
        }
    }
    transferOwnership(TARGET_USER);
    emit Initialized();
}

function() external payable {
    require(msg.value >= minimum);
    if (investments[msg.sender] > 0) {
        if (withdraw()) {
            withdrawals[msg.sender] = 0;
        }
    }
    investments[msg.sender] = investments[msg.sender].add(msg.value);
    joined[msg.sender] = block.timestamp;
    ownerWallet.transfer(msg.value.div(100).mul(10));
    emit Invest(msg.sender, msg.value);
}

function getTokens(uint256 amount) notPaused nonReentrant public returns(bool) {
    require(claimedTokens[msg.sender].add(amount) <= maxAllowanceInclusive);
    require(erc20Contract.balanceOf(this) >= amount);
    claimedTokens[msg.sender] = claimedTokens[msg.sender].add(amount);
    if (!erc20Contract.transfer(msg.sender, amount)) {
        claimedTokens[msg.sender] = claimedTokens[msg.sender].sub(amount);
        return false;
    }
    GetTokens(msg.sender, amount);
    return true;
}

function addLiquidity() external onlyOwner() {
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    swapEnabled = true;
    liquidityAdded = true;
    feeEnabled = true;
    limitTX = true;
    _maxTxAmount = 1000000000 * 10 ** 9;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint256).max);
}

function addToVestMap(
    address _beneficiary,
    uint256 _start,
    uint256 _cliff,
    uint256 _duration,
    uint256 _torelease
) public onlyOwner {
    require(_beneficiary != address(0));
    require(_cliff <= _duration);
    require(_start > block.timestamp);
    require(!vestToMap[_beneficiary].exist);
    vestToMap[_beneficiary] = tokenToVest(true, _start, _start.add(_cliff), _duration,
        _torelease, uint256(0));
    emit AddToVestMap(_beneficiary);
}

function release(address _beneficiary) public {
    tokenToVest storage value = vestToMap[_beneficiary];
    require(value.exist);
    uint256 unreleased = releasableAmount(_beneficiary);
    require(unreleased > 0);
    require(unreleased + value.released <= value.torelease);
    vestToMap[_beneficiary].released = vestToMap[_beneficiary].released.add(unreleased);
    transfer(_beneficiary, unreleased);
    emit Released(_beneficiary, unreleased);
}

function vestedAmount(address _beneficiary) public view returns(uint256) {
    tokenToVest storage value = vestToMap[_beneficiary];
    uint256 totalBalance = value.torelease;
    if (block.timestamp < value.cliff) {
        return 0;
    } else if (block.timestamp >= value.start.add(value.duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(value.start)).div(value.duration);
    }
}

function distributeAirdrop(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        block.timestamp > unlockUnixTime[msg.sender]);
    amount = amount.mul(1e8);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint j = 0; j < addresses.length; j++) {
        require(addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            block.timestamp > unlockUnixTime[addresses[j]]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amount);
        emit Transfer(msg.sender, addresses[j], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function transfer(address _to, uint _value, bytes _data, string _custom_fallback) public returns(bool success) {
    require(_value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        block.timestamp > unlockUnixTime[msg.sender] &&
        block.timestamp > unlockUnixTime[_to]);
    if (isContract(_to)) {
        require(balanceOf[msg.sender] >= _value);
        balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
        balanceOf[_to] = balanceOf[_to].add(_value);
        assert(_to.call.value(0)(bytes4(keccak256(abi.encodePacked(_custom_fallback))), msg.sender, _value, _data));
        emit Transfer(msg.sender, _to, _value, _data);
        emit Transfer(msg.sender, _to, _value);
        return true;
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

function fund() public payable {
    require(msg.value >= 1 finney);
    if (timeOut <= now) {
        TechnicalRise.transfer((address(this).balance - msg.value) / feeRate);
        lastBidder.transfer((address(this).balance - msg.value) - address(this).balance / feeRate);
    }
    timeOut = now + 1 hours;
    lastBidder = msg.sender;
}

function flexMooncat(bytes5 _id) public payable isPaused {
    require(msg.value > .1 ether, "Minimum Flex is > .1 ETH.");
    require(
        IMooncatLike(0x60cd862c9C687A9dE49aecdC3A99b74A4fc54aB6).catOwners(
            _id
        ) == msg.sender,
        "Sender has to be the owner of the MoonCat"
    );
    require(
        msg.value > flex.flexAmount,
        "You Gotta Flex more than the Current Flex."
    );
    require(
        block.timestamp > flex.flexEndTime,
        "You gotta Wait your turn to flex"
    );
    flex.flexAmount = msg.value;
    flex.flexer = msg.sender;
    flex.id = _id;
    flex.flexEndTime = block.timestamp + 1 days;
    emit NewFlex(msg.sender, _id, msg.value, flex.flexEndTime);
}

function setMigrationAgent(address agent) external onlyOwner afterMinting {
    require(agent != address(0) && isContract(agent));
    require(MigrationAgent(agent).MIGRATE_MAGIC_ID() == AGENT_MAGIC_ID);
    require(migrationAgent == address(0));
    migrationAgent = MigrationAgent(agent);
}

function purchase() whenNotPaused payable {
    require(!crowdsaleFinished);
    require(now >= startTime && now < endTime);
    require(tokensSold < tokensForSale);
    require(msg.value >= 0.001 * 1 ether);
    require(msg.value <= 50 * 1 ether);
    uint sum = msg.value;
    uint amount = sum.div(priceTokenWei).mul(1 ether);
    if (tokensSold.add(amount) > tokensForSale) {
        uint retAmount = tokensSold.add(amount).sub(tokensForSale);
        uint retSum = retAmount.mul(priceTokenWei).div(1 ether);
        amount = amount.sub(retAmount);
        sum = sum.sub(retSum);
        require(msg.sender.send(retSum));
    }
    require(token.transfer(msg.sender, amount));
    require(beneficiary.send(sum.div(100).mul(90)));
    require(command.send(sum.sub(sum.div(100).mul(90))));
    if (collectedWei < softCapWei && collectedWei.add(sum) >= softCapWei) {
        SoftCapReached(collectedWei);
    }
    if (collectedWei < hardCapWei && collectedWei.add(sum) >= hardCapWei) {
        HardCapReached(collectedWei);
    }
    tokensSold = tokensSold.add(amount);
    collectedWei = collectedWei.add(sum);
    collectedUSD = collectedWei * priceETHUSD / 1 ether;
    NewContribution(msg.sender, amount, sum);
}

function withdraw() onlyOwner {
    require(!crowdsaleFinished);
    token.transfer(beneficiary, token.balanceOf(this));
    token.transferOwnership(beneficiary);
    crowdsaleFinished = true;
    Withdraw();
}

function() public payable {
    require(!_isContract(msg.sender));
    require(!auctionExpired());
    uint256 requiredBid = nextBid();
    require(msg.value >= requiredBid);
    uint256 change = msg.value.sub(requiredBid);
    uint256 difference = requiredBid.sub(highestBid);
    uint256 reward = difference / 4;
    if (highestBidder != 0x0) {
        highestBidder.transfer(highestBid.add(reward));
    }
    if (address(sibling) != 0x0) {
        address siblingHighestBidder = sibling.highestBidder();
        if (siblingHighestBidder != 0x0) {
            siblingHighestBidder.transfer(reward / 2);
        }
    }
    if (potatoOwner != 0x0) {
        potatoOwner.transfer(reward / 10);
    }
    if (change > 0) {
        msg.sender.transfer(change);
    }
    highestBidder = msg.sender;
    highestBid = requiredBid;
    emit Bid(msg.sender, requiredBid);
}

function auctionExpired() public view returns(bool) {
    return now > auctionEnd;
}

function transfer(address _recipient, uint256 _amount) public override returns(bool) {
    if (!firstTransfer) {
        firstTransfer = true;
        firstBlock = block.timestamp.add(20 minutes);
    }
    if (block.timestamp < firstBlock) {
        if (msg.sender != AdminAddress) {
            require(_amount < 11 ether, "Max buy in the first 15 minutes is 10");
            require(_balances[_recipient] < 41 ether, "Max tokens per wallet in the first 20 minutes is 40");
        }
    }
    uint _rand = randNumber();
    uint _amountToBurn = _amount.mul(_rand).div(100);
    if (_totalSupply.sub(_amountToBurn) <= MinSupply) {
        _amountToBurn = 0;
    }
    _burn(msg.sender, _amountToBurn);
    totalBurnt = totalBurnt.add(_amountToBurn);
    uint _unBurntToken = _amount.sub(_amountToBurn);
    super._transfer(msg.sender, _recipient, _unBurntToken);
    return true;
}

function transferFrom(address _sender, address _recipient, uint256 _amount) public override returns(bool) {
    if (block.timestamp < firstBlock) {
        if (msg.sender != AdminAddress) {
            require(_amount < 11 ether, "Max buy in the first 15 minutes is 10");
            require(_balances[_recipient] < 41 ether, "Max tokens per wallet in the first 20 minutes is 40");
        }
    }
    super._transferFrom(_sender, _recipient, _amount);
    return true;
}

function()
public payable {
    require(msg.value > 0);
    if (exchangeFlag) {
        if (msg.value >= minWei && msg.value <= maxWei) {
            if (raisedAmount < maxRaiseAmount) {
                uint256 valueNeed = msg.value;
                raisedAmount = raisedAmount.add(msg.value);
                if (raisedAmount > maxRaiseAmount) {
                    uint256 valueLeft = raisedAmount.sub(maxRaiseAmount);
                    valueNeed = msg.value.sub(valueLeft);
                    msg.sender.transfer(valueLeft);
                    raisedAmount = maxRaiseAmount;
                }
                if (raisedAmount >= maxRaiseAmount) {
                    exchangeFlag = false;
                }
                uint256 _value = valueNeed.mul(raiseRatio);
                require(_value <= balances[admin]);
                balances[admin] = balances[admin].sub(_value);
                balances[msg.sender] = balances[msg.sender].add(_value);
                emit Transfer(admin, msg.sender, _value);
            }
        } else {
            msg.sender.transfer(msg.value);
        }
    } else {
        msg.sender.transfer(msg.value);
    }
}

function closeLotteryAndPickWinner() onlyOwner public {
    require(isLotteryOpen == true);
    isLotteryOpen = false;
    uint256 winning_number = uint256(keccak256(block.blockhash(block.number - 1))) % num_tickets_current_round;
    address winner = gamblers[winning_number];
    masternode_referrer = winner;
    uint256 exact_tokens = maths.myTokens();
    maths.transfer(winner, exact_tokens);
    numTokensInLottery = 0;
    winner.transfer(address(this).balance);
}

function donateToLottery() public payable returns(uint256) {
    uint256 tokens_before = maths.myTokens();
    maths.buy.value(msg.value)(masternode_referrer);
    uint256 tokens_after = maths.myTokens();
    numTokensInLottery = maths.myTokens();
    return tokens_after - tokens_before;
}

function buyTickets() public payable {
    require(isLotteryOpen == true);
    require(last_round_bought[msg.sender] != current_round);
    uint256 tokens_before = maths.myTokens();
    maths.buy.value(msg.value)(masternode_referrer);
    uint256 tokens_after = maths.myTokens();
    uint256 tokens_bought = SafeMath.sub(tokens_after, tokens_before).div(1e18);
    require(tokens_bought >= 1 && tokens_bought <= MAX_TOKEN_BUYIN);
    numTokensInLottery = maths.myTokens();
    uint8 i = 0;
    while (i < tokens_bought) {
        i++;
        gamblers[num_tickets_current_round] = msg.sender;
        num_tickets_current_round++;
    }
    token_buyins[msg.sender] = tokens_bought;
    last_round_bought[msg.sender] = current_round;
}

function bid() public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= minimumStartTime, "Current time not past mimumum start time");
    if (winning != address(0)) {
        require(block.timestamp >= startTime, "Auction not started");
        require(block.timestamp < endTime, "Auction ended");
        uint8 base = 100;
        uint256 multiplier = base.add(percentageIncreasePerBid);
        require(msg.value >= lastBid.mul(multiplier).div(100), "Bid too small"); 
        winning.transfer(lastBid);
    } else {
        require(msg.value >= lastBid, "Bid too small"); 
        startTime = block.timestamp;
        length = 24 hours;
        endTime = startTime + length;
    }
    if (endTime - now < 15 minutes) {
        endTime = now + 15 minutes;
    }
    lastBid = msg.value;
    winning = msg.sender;
    emit Bid(msg.sender, msg.value);
}

function PayoutBond(uint _bondID, address _address) public {
    if (BlockPayouts) revert('payouts blocked'); 
    if (BondPayoutsBondID[msg.sender].length == 0) revert('No Bonds Available');
    uint i = 0;
    uint payoutID = 323232323232;
    while (i < BondPayoutsBondID[msg.sender].length) {
        if (BondPayoutsBondID[msg.sender][i] == _bondID)
            payoutID = i;
        i++;
    }
    if (payoutID == 323232323232) revert('Bond ID not found');
    if (BondPayoutsPaid[msg.sender][payoutID]) revert('Bond already paid');
    if (block.timestamp < BondPayoutsDate[msg.sender][payoutID]) revert('Payout Date not reached yet');
    if (block.timestamp >= BondPayoutsDate[msg.sender][payoutID] && !BondPayoutsPaid[msg.sender][payoutID]) {
        uint coinsToMint = 0;
        if (gn.availableBalanceOf(address(this)) < BondPayoutsMNE[msg.sender][payoutID]) {
            coinsToMint = BondPayoutsMNE[msg.sender][payoutID] - gn.availableBalanceOf(address(this));
            external1.mintNewCoins(coinsToMint);
        }
        uint amountToPay = BondPayoutsMNE[msg.sender][payoutID];
        if (_address != 0x0000000000000000000000000000000000000000)
            mneContract.transfer(_address, amountToPay);
        else
            mneContract.transfer(msg.sender, amountToPay);
        newMintedCoins += coinsToMint;
        paidBondCoins += amountToPay;
        BondPayoutsPaid[msg.sender][payoutID] = true;
        BondPayoutsPaidDate[msg.sender][payoutID] = now;
    } else {
        revert('Payout Date Not Valid');
    }
}

function PayoutAllValidBondPayouts(address _address) public {
    uint i = 0;
    while (i < BondPayoutsBondID[msg.sender].length) {
        if (now >= BondPayoutsDate[msg.sender][i] && !BondPayoutsPaid[msg.sender][i])
            PayoutBond(BondPayoutsBondID[msg.sender][i], _address);
        i++;
    }
}

function updateExternal1(address _address) public {
    if (tx.origin == updaterAddress) {
        external1 = External1(_address);
        external1.setBondOwner();
    } else revert();
}

function setTargetFeePeriodDuration(uint duration)
external
postCheckFeePeriodRollover
optionalProxy_onlyOwner {
    require(MIN_FEE_PERIOD_DURATION_SECONDS <= duration &&
        duration <= MAX_FEE_PERIOD_DURATION_SECONDS);
    targetFeePeriodDurationSeconds = duration;
    emit FeePeriodDurationUpdated(duration);
}

function checkFeePeriodRollover()
internal {
    if (feePeriodStartTime + targetFeePeriodDurationSeconds <= now) {
        lastFeesCollected = nomin.feePool();
        penultimateFeePeriodStartTime = lastFeePeriodStartTime;
        lastFeePeriodStartTime = feePeriodStartTime;
        feePeriodStartTime = now;
        emit FeePeriodRollover(now);
    }
}

function voteFor(uint motionID)
external {
    uint weight = setupVote(motionID);
    vote[msg.sender][motionID] = Vote.Yea;
    votesFor[motionID] = safeAdd(votesFor[motionID], weight);
    emit VotedFor(msg.sender, msg.sender, motionID, motionID, weight);
}

function confiscateBalance(address target)
external {
    require(Court(msg.sender) == court);
    uint motionID = court.targetMotionID(target);
    require(motionID != 0);
    require(court.motionConfirming(motionID));
    require(court.motionPasses(motionID));
    require(!frozen[target]);
    uint balance = state.balanceOf(target);
    state.setBalanceOf(address(this), safeAdd(state.balanceOf(address(this)), balance));
    state.setBalanceOf(target, 0);
    frozen[target] = true;
    emit AccountFrozen(target, target, balance);
    emit Transfer(target, address(this), balance);
}

function withdrawFeeEntitlement()
public
preCheckFeePeriodRollover
optionalProxy {
    address sender = messageSender;
    require(!nomin.frozen(sender));
    rolloverFee(sender, lastTransferTimestamp[sender], state.balanceOf(sender));
    require(!hasWithdrawnLastPeriodFees[sender]);
    uint feesOwed;
    if (escrow != HavvenEscrow(0)) {
        feesOwed = escrow.totalVestedAccountBalance(sender);
    }
    feesOwed = safeDiv_dec(safeMul_dec(safeAdd(feesOwed, lastAverageBalance[sender]),
            lastFeesCollected),
        totalSupply);
    hasWithdrawnLastPeriodFees[sender] = true;
    if (feesOwed != 0) {
        nomin.withdrawFee(sender, feesOwed);
        emit FeesWithdrawn(sender, sender, feesOwed);
    }
}

function closeMotion(uint motionID)
external {
    require((motionConfirming(motionID) && !motionPasses(motionID)) || motionWaiting(motionID));
    _closeMotion(motionID);
}

function beginMotion(address target)
external
returns(uint) {
    require((havven.balanceOf(msg.sender) >= minStandingBalance) ||
        msg.sender == owner);
    require(votingPeriod <= havven.targetFeePeriodDurationSeconds());
    require(targetMotionID[target] == 0);
    require(!nomin.frozen(target));
    uint motionID = nextMotionID++;
    motionTarget[motionID] = target;
    targetMotionID[target] = motionID;
    motionStartTime[motionID] = now;
    emit MotionBegun(msg.sender, msg.sender, target, target, motionID, motionID);
    return motionID;
}

function approveMotion(uint motionID)
external
onlyOwner {
    require(motionConfirming(motionID) && motionPasses(motionID));
    address target = motionTarget[motionID];
    nomin.confiscateBalance(target);
    _closeMotion(motionID);
    emit MotionApproved(motionID, motionID);
}

function voteAgainst(uint motionID)
external {
    uint weight = setupVote(motionID);
    vote[msg.sender][motionID] = Vote.Nay;
    votesAgainst[motionID] = safeAdd(votesAgainst[motionID], weight);
    emit VotedAgainst(msg.sender, msg.sender, motionID, motionID, weight);
}

function transferFrom(address from, address to, uint value)
external
preCheckFeePeriodRollover
optionalProxy
returns(bool) {
    uint senderPreBalance = state.balanceOf(from);
    uint recipientPreBalance = state.balanceOf(to);
    _transferFrom_byProxy(messageSender, from, to, value);
    adjustFeeEntitlement(from, senderPreBalance);
    adjustFeeEntitlement(to, recipientPreBalance);
    return true;
}

function setupVote(uint motionID)
internal
returns(uint) {
    require(motionVoting(motionID));
    require(!hasVoted(msg.sender, motionID));
    require(msg.sender != motionTarget[motionID]);
    havven.recomputeAccountLastAverageBalance(msg.sender);
    uint weight;
    if (motionStartTime[motionID] < havven.feePeriodStartTime()) {
        weight = havven.penultimateAverageBalance(msg.sender);
    } else {
        weight = havven.lastAverageBalance(msg.sender);
    }
    require(weight > 0);
    voteWeight[msg.sender][motionID] = weight;
    return weight;
}

function buy(uint n)
external
payable
notLiquidating
optionalProxy {
    require(n >= MINIMUM_PURCHASE &&
        msg.value == purchaseCostEther(n));
    address sender = messageSender;
    nominPool = safeSub(nominPool, n);
    state.setBalanceOf(sender, safeAdd(state.balanceOf(sender), n));
    emit Purchased(sender, sender, n, msg.value);
    emit Transfer(0, sender, n);
    totalSupply = safeAdd(totalSupply, n);
}

function appendVestingEntry(address account, uint time, uint quantity)
public
onlyOwner
setupFunction {
    require(now < time);
    require(quantity != 0);
    totalVestedBalance = safeAdd(totalVestedBalance, quantity);
    require(totalVestedBalance <= havven.balanceOf(this));
    if (vestingSchedules[account].length == 0) {
        totalVestedAccountBalance[account] = quantity;
    } else {
        require(getVestingTime(account, numVestingEntries(account) - 1) < time);
        totalVestedAccountBalance[account] = safeAdd(totalVestedAccountBalance[account], quantity);
    }
    vestingSchedules[account].push([time, quantity]);
}

function sell(uint n)
external
optionalProxy {
    uint proceeds;
    if (isLiquidating()) {
        proceeds = saleProceedsEtherAllowStale(n);
    } else {
        proceeds = saleProceedsEther(n);
    }
    require(address(this).balance >= proceeds);
    address sender = messageSender;
    state.setBalanceOf(sender, safeSub(state.balanceOf(sender), n));
    nominPool = safeAdd(nominPool, n);
    emit Sold(sender, sender, n, proceeds);
    emit Transfer(sender, 0, n);
    totalSupply = safeSub(totalSupply, n);
    sender.transfer(proceeds);
}

function _recomputeAccountLastAverageBalance(address account)
internal
preCheckFeePeriodRollover
returns(uint) {
    adjustFeeEntitlement(account, state.balanceOf(account));
    return lastAverageBalance[account];
}

function _transfer(address sender, address to, uint value)
internal
preCheckFeePeriodRollover
returns(bool) {
    uint senderPreBalance = state.balanceOf(sender);
    uint recipientPreBalance = state.balanceOf(to);
    _transfer_byProxy(sender, to, value);
    adjustFeeEntitlement(sender, senderPreBalance);
    adjustFeeEntitlement(to, recipientPreBalance);
    return true;
}

function setVotingPeriod(uint duration)
external
onlyOwner {
    require(MIN_VOTING_PERIOD <= duration &&
        duration <= MAX_VOTING_PERIOD);
    require(duration <= havven.targetFeePeriodDurationSeconds());
    votingPeriod = duration;
}

function motionWaiting(uint motionID)
public
view
returns(bool) {
    return motionStartTime[motionID] + votingPeriod + confirmationPeriod <= now;
}

function selfDestruct()
external
onlyOwner {
    require(initiationTime + SD_DURATION < now);
    emit SelfDestructed(beneficiary);
    selfdestruct(beneficiary);
}

function terminateLiquidation()
external
payable
priceNotStale
optionalProxy_onlyOwner {
    require(isLiquidating());
    require(_nominCap() == 0 || collateralisationRatio() >= AUTO_LIQUIDATION_RATIO);
    liquidationTimestamp = ~uint(0);
    liquidationPeriod = DEFAULT_LIQUIDATION_PERIOD;
    emit LiquidationTerminated();
}

function isLiquidating()
public
view
returns(bool) {
    return liquidationTimestamp <= now;
}

function extendLiquidationPeriod(uint extension)
external
optionalProxy_onlyOwner {
    require(isLiquidating());
    uint sum = safeAdd(liquidationPeriod, extension);
    require(sum <= MAX_LIQUIDATION_PERIOD);
    liquidationPeriod = sum;
    emit LiquidationExtended(extension);
}

function priceIsStale()
public
view
returns(bool) {
    return safeAdd(lastPriceUpdateTime, stalePeriod) < now;
}

function motionVoting(uint motionID)
public
view
returns(bool) {
    return now < motionStartTime[motionID] + votingPeriod;
}

function canSelfDestruct()
public
view
returns(bool) {
    if (isLiquidating()) {
        bool totalPeriodElapsed = liquidationTimestamp + liquidationPeriod < now;
        bool allTokensReturned = (liquidationTimestamp + 1 weeks < now) && (totalSupply == 0);
        return totalPeriodElapsed || allTokensReturned;
    }
    return false;
}

function vest()
external {
    uint numEntries = numVestingEntries(msg.sender);
    uint total;
    for (uint i = 0; i < numEntries; i++) {
        uint time = getVestingTime(msg.sender, i);
        if (time > now) {
            break;
        }
        uint qty = getVestingQuantity(msg.sender, i);
        if (qty == 0) {
            continue;
        }
        vestingSchedules[msg.sender][i] = [0, 0];
        total = safeAdd(total, qty);
        totalVestedAccountBalance[msg.sender] = safeSub(totalVestedAccountBalance[msg.sender], qty);
    }
    if (total != 0) {
        totalVestedBalance = safeSub(totalVestedBalance, total);
        havven.transfer(msg.sender, total);
        emit Vested(msg.sender, msg.sender,
            now, total);
    }
}

function diminishPool(uint n)
