function replenishPool(uint n)
external
payable
notLiquidating
optionalProxy_onlyOwner {
    require(fiatBalance() >= safeMul_dec(safeAdd(_nominCap(), n), MINIMUM_ISSUANCE_RATIO));
    nominPool = safeAdd(nominPool, n);
    emit PoolReplenished(n, msg.value);
}

