function isBeneficiary(address _address) public view returns(bool) {
    if (beneficiaries[_address]._address != 0) {
        return true;
    } else {
        return false;
    }
}

function checkLimit(address _address, uint256 value) internal view returns(bool) {
    uint256 remaining = balanceOf(_address).sub(value);
    if (isBeneficiary(_address) && isInvestor(_address)) {
        uint256 ilocked = _getInvestorLockedAmount(_address);
        uint256 locked = _getLockedAmount(_address);
        return remaining >= locked.add(ilocked);
    }
    if (isBeneficiary(_address)) {
        return remaining >= _getLockedAmount(_address);
    }
    if (isInvestor(_address)) {
        return remaining >= _getInvestorLockedAmount(_address);
    }
}

function _getInvestorLockedAmount(address _address) public view returns(uint256) {
    Investor memory i = investorList[_address];
    uint256 amount = i._amount;
    uint256 timeValue = _getTimeValue(_address);
    uint256 calcAmount = amount.mul(timeValue.mul(percent)).div(100);
    if (calcAmount >= amount) {
        return 0;
    } else {
        return amount.sub(calcAmount);
    }
}

function _getLockedAmount(address _address) public view returns(uint256) {
    Beneficiary memory b = beneficiaries[_address];
    uint256 amount = b._amount;
    uint256 percent = b._percent;
    uint256 timeValue = _getTimeValue(_address);
    uint256 calcAmount = amount.mul(timeValue.mul(percent)).div(100);
    if (calcAmount >= amount) {
        return 0;
    } else {
        return amount.sub(calcAmount);
    }
}

function dig(uint capsuleNumber) {
    Capsule storage capsule = depositors[msg.sender].capsules[capsuleNumber];
    require(capsule.unlockTime <= block.timestamp);
    require(capsule.withdrawnTime == 0);
    totalBuriedCapsules--;
    capsule.withdrawnTime = block.timestamp;
    msg.sender.transfer(capsule.value);
}

function bury(uint unlockTime) payable {
    require(msg.value >= minDeposit);
    require(unlockTime <= block.timestamp + maxDuration);
    if (unlockTime < block.timestamp + minDuration) {
        unlockTime = SafeMath.add(block.timestamp, minDuration);
    }
    if (depositors[msg.sender].numCapsules <= 0) {
        depositors[msg.sender] = Depositor({
            numCapsules: 0
        });
    }
    Depositor storage depositor = depositors[msg.sender];
    depositor.numCapsules++;
    depositor.capsules[depositor.numCapsules] = Capsule({
        value: msg.value,
        id: depositors[msg.sender].numCapsules,
        lockTime: block.timestamp,
        unlockTime: unlockTime,
        withdrawnTime: 0
    });
    totalBuriedCapsules++;
    totalCapsules++;
    totalValue = SafeMath.add(totalValue, msg.value);
}

function transferMultiple(address[] _tos, uint256[] _values, uint count) payable public returns(bool) {
    uint256 total = 0;
    uint256 total_prev = 0;
    uint i = 0;
    for (i = 0; i < count; i++) {
        require(_tos[i] != address(0) && !isContract(_tos[i])); 
        if (isContract(_tos[i])) {
            ERC223ReceivingContract receiver = ERC223ReceivingContract(_tos[i]);
            bytes memory _data = new bytes(1);
            receiver.tokenFallback(msg.sender, _values[i], _data);
        }
        total_prev = total;
        total = SafeMath.add(total, _values[i]);
        require(total >= total_prev);
    }
    require(total <= balances[msg.sender]);
    for (i = 0; i < count; i++) {
        balances[msg.sender] = SafeMath.sub(balances[msg.sender], _values[i]);
        balances[_tos[i]] = SafeMath.add(balances[_tos[i]], _values[i]);
        emit Transfer(msg.sender, _tos[i], _values[i]);
    }
    return true;
}

function transferdata(address _to, uint _value, bytes _data) public payable {
    require(_value > 0);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transferdata(msg.sender, _to, _value, _data);
}

function releaseLockedBalance() public {
    address _owner = msg.sender;
    require(address(0) != _owner && lockedBalanceOf(_owner) > 0 && releaseTimeOf(_owner) <= now);
    mintToken(_owner, lockedBalanceOf(_owner));
    _lockedSupply = SafeMath.sub(_lockedSupply, lockedBalanceOf(_owner));
    emit UnlockBalance(_owner, addressFrozenFund[_owner].release, lockedBalanceOf(_owner));
    delete addressFrozenFund[_owner];
}

function lockBalance(uint256 duration, uint256 amount) public {
    address _owner = msg.sender;
    require(address(0) != _owner && amount > 0 && duration > 0 && balanceOf(_owner) >= amount);
    require(addressFrozenFund[_owner].release <= now && addressFrozenFund[_owner].amount == 0);
    addressFrozenFund[_owner].start = now;
    addressFrozenFund[_owner].duration = duration;
    addressFrozenFund[_owner].release = SafeMath.add(addressFrozenFund[_owner].start, duration);
    addressFrozenFund[_owner].amount = amount;
    burnToken(_owner, amount);
    _lockedSupply = SafeMath.add(_lockedSupply, lockedBalanceOf(_owner));
    emit LockBalance(_owner, addressFrozenFund[_owner].release, amount);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        bytes memory _data = new bytes(1);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], _value);
    balances[_to] = SafeMath.add(balances[_to], _value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    if (_from == fundsWallet) {
        require(_value <= balances[_from]);
    }
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        bytes memory _data = new bytes(1);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[_from] = SafeMath.sub(balances[_from], _value);
    balances[_to] = SafeMath.add(balances[_to], _value);
    allowed[_from][msg.sender] = SafeMath.sub(allowed[_from][msg.sender], _value);
    emit Transfer(_from, _to, _value);
    return true;
}

