function purchase(uint256 _tokenId) public payable {
    require(!jackpotCompleted);
    require(msg.sender != owner);
    address oldOwner = countryIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 sellingPrice = countryIndexToPrice[_tokenId];
    uint256 lastSellingPrice = countryToLastPrice[_tokenId];
    if (sellingPrice.mul(2) < firstStepLimit) {
        countryIndexToPrice[_tokenId] = sellingPrice.mul(2);
    } else if (sellingPrice.mul(4).div(10) < secondStepLimit) {
        countryIndexToPrice[_tokenId] = sellingPrice.add(sellingPrice.mul(4).div(10));
    } else if (sellingPrice.mul(2).div(10) < thirdStepLimit) {
        countryIndexToPrice[_tokenId] = sellingPrice.add(sellingPrice.mul(2).div(10));
    } else {
        countryIndexToPrice[_tokenId] = sellingPrice.add(sellingPrice.mul(15).div(100));
    }
    _transfer(oldOwner, newOwner, _tokenId);
    countryToLastPrice[_tokenId] = sellingPrice;
    if (oldOwner != owner) {
        uint256 priceDifference = sellingPrice.sub(lastSellingPrice);
        uint256 oldOwnerPayment = lastSellingPrice.add(priceDifference.sub(priceDifference.div(2)));
        oldOwner.transfer(oldOwnerPayment);
    }
    emit TokenSold(_tokenId, sellingPrice, countryIndexToPrice[_tokenId], oldOwner, newOwner, countries[_tokenId].name);
    uint256 purchaseExcess = msg.value.sub(sellingPrice);
    msg.sender.transfer(purchaseExcess);
}

function freezeFrom(address _who, uint256 _value, uint256 _cliff, uint256 _duration) onlyOwner public {
    require(_who != address(0));
    require(_value > 0 && _value <= balances[_who]);
    require(freezed[_who].amount == 0);
    require(_cliff <= _duration);
    require(_duration >= MIN_FREEZE_DURATION);
    balances[_who] = balances[_who].sub(_value);
    uint256 timestamp = block.timestamp;
    freezed[_who] = Schedule({
        amount: _value,
        start: timestamp,
        cliff: timestamp.add(_cliff),
        duration: _duration,
        released: 0,
        lastReleased: timestamp.add(_cliff)
    });
    emit Freeze(_who, _value, _cliff, _duration);
}

function freeze(uint256 _value, uint256 _duration) public {
    require(_value > 0 && _value <= balances[msg.sender]);
    require(freezed[msg.sender].amount == 0);
    require(_duration >= MIN_FREEZE_DURATION);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    uint256 timestamp = block.timestamp;
    freezed[msg.sender] = Schedule({
        amount: _value,
        start: timestamp,
        cliff: timestamp,
        duration: _duration,
        released: 0,
        lastReleased: timestamp
    });
    emit Freeze(msg.sender, _value, 0, _duration);
}

function unfreeze(address _who) public returns(uint256) {
    require(_who != address(0));
    Schedule storage schedule = freezed[_who];
    uint256 timestamp = block.timestamp;
    require(schedule.lastReleased.add(MIN_FREEZE_DURATION) < timestamp);
    require(schedule.amount > 0 && timestamp > schedule.cliff);
    uint256 unreleased = 0;
    if (timestamp >= schedule.start.add(schedule.duration)) {
        unreleased = schedule.amount;
    } else {
        unreleased = (schedule.amount.add(schedule.released)).mul(timestamp.sub(schedule.start)).div(schedule.duration).sub(schedule.released);
    }
    require(unreleased > 0);
    schedule.released = schedule.released.add(unreleased);
    schedule.lastReleased = timestamp;
    schedule.amount = schedule.amount.sub(unreleased);
    balances[_who] = balances[_who].add(unreleased);
    emit Unfreeze(_who, unreleased);
    return unreleased;
}

function unstakeAll() public {
    require(stakerToTokenIds[msg.sender].length > 0, "Must have at least one token staked!");
    uint256 totalRewards = 0;
    bool receiveMultiple = (stakerToTokenIds[msg.sender].length == MAX_WALLET_STAKED) ? true : false;
    for (uint256 i = stakerToTokenIds[msg.sender].length; i > 0; i--) {
        uint256 tokenId = stakerToTokenIds[msg.sender][i - 1];
        IERC721(dingersAddress).transferFrom(address(this), msg.sender, tokenId);
        totalRewards = totalRewards + getRewards(tokenIdToTimeStamp[tokenId], receiveMultiple);
        removeTokenIdFromStaker(msg.sender, tokenId);
        tokenIdToStaker[tokenId] = nullAddress;
    }
    _mint(msg.sender, totalRewards);
}

function unstakeByIds(uint256[] memory tokenIds) public {
    uint256 totalRewards = 0;
    bool receiveMultiple = (tokenIds.length == MAX_WALLET_STAKED) ? true : false;
    for (uint256 i = 0; i < tokenIds.length; i++) {
        require(tokenIdToStaker[tokenIds[i]] == msg.sender, "Message Sender was not original staker!");
        IERC721(dingersAddress).transferFrom(address(this), msg.sender, tokenIds[i]);
        totalRewards = totalRewards + getRewards(tokenIdToTimeStamp[tokenIds[i]], receiveMultiple);
        removeTokenIdFromStaker(msg.sender, tokenIds[i]);
        tokenIdToStaker[tokenIds[i]] = nullAddress;
    }
    _mint(msg.sender, totalRewards);
}

function stakeByIds(uint256[] memory tokenIds) public {
    require(stakerToTokenIds[msg.sender].length + tokenIds.length <= MAX_WALLET_STAKED,
        "Must have less than 10 dingers staked!"
    );
    for (uint256 i = 0; i < tokenIds.length; i++) {
        require(
            IERC721(dingersAddress).ownerOf(tokenIds[i]) == msg.sender &&
            tokenIdToStaker[tokenIds[i]] == nullAddress,
            "Token must be stakable by you!"
        );
        IERC721(dingersAddress).transferFrom(msg.sender, address(this), tokenIds[i]);
        stakerToTokenIds[msg.sender].push(tokenIds[i]);
        tokenIdToTimeStamp[tokenIds[i]] = block.timestamp;
        tokenIdToStaker[tokenIds[i]] = msg.sender;
    }
}

