function cancelAuction(uint256 _tokenId) external {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    address seller = auction.seller;
    require(msg.sender == seller);
    _cancelAuction(_tokenId, seller);
}

function _buy(uint256 _tokenId, uint256 _bidAmount) internal returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    uint256 price = auction.price;
    require(_bidAmount >= price);
    address seller = auction.seller;
    uint256 uID = auction.id;
    _removeAuction(_tokenId);
    ownershipAuctionCount[seller]--;
    if (price > 0) {
        uint256 auctioneerCut = _computeCut(price);
        uint256 sellerProceeds = price - auctioneerCut;
        if (seller != address(core)) {
            seller.transfer(sellerProceeds);
        }
    }
    uint256 bidExcess = _bidAmount - price;
    msg.sender.transfer(bidExcess);
    AuctionSuccessful(_tokenId, price, msg.sender, uID);
    return price;
}

function _settleAndRestart() private {
    gameActive = false;
    uint payment = tokensInPlay / 2;
    contractBalance = contractBalance.sub(payment);
    if (tokensInPlay > 0) {
        ZTHTKN.transfer(currentWinner, payment);
        if (address(this).balance > 0) {
            ZTHBANKROLL.transfer(address(this).balance);
        }
    }
    emit GameEnded(currentWinner, payment, now);
    tokensInPlay = tokensInPlay.sub(payment);
    gameActive = true;
}

function _stakeTokens(TKN _tkn) private {
    require(gameActive);
    require(_zthToken(msg.sender));
    require(validTokenBet[_tkn.value]);
    if (now > gameEnds) {
        _settleAndRestart();
    }
    address _customerAddress = _tkn.sender;
    uint _wagered = _tkn.value;
    uint rightNow = now;
    uint timePurchased = tokenToTimer[_tkn.value];
    uint newGameEnd = rightNow.add(timePurchased);
    gameStarted = rightNow;
    gameEnds = newGameEnd;
    currentWinner = _customerAddress;
    contractBalance = contractBalance.add(_wagered);
    uint houseCut = _wagered.div(100);
    uint toAdd = _wagered.sub(houseCut);
    houseTake = houseTake.add(houseCut);
    tokensInPlay = tokensInPlay.add(toAdd);
    emit TokensWagered(_customerAddress, _wagered, newGameEnd);
}

function createTokens(address _beneficiary, uint256 _value) internal whenNotPaused {
    require(tokenCreationCap > totalSupply);
    require(now >= fundingStartTime);
    require(_value >= minContribution);
    require(!isFinalized);
    uint256 tokens = safeMult(_value, tokenExchangeRate);
    uint256 checkedSupply = safeAdd(totalSupply, tokens);
    if (tokenCreationCap < checkedSupply) {
        uint256 tokensToAllocate = safeSubtract(tokenCreationCap, totalSupply);
        uint256 tokensToRefund = safeSubtract(tokens, tokensToAllocate);
        totalSupply = tokenCreationCap;
        uint256 etherToRefund = tokensToRefund / tokenExchangeRate;
        require(CreateICO(_beneficiary, tokensToAllocate));
        msg.sender.transfer(etherToRefund);
        ethFundDeposit.transfer(this.balance);
        return;
    }
    totalSupply = checkedSupply;
    require(CreateICO(_beneficiary, tokens));
    ethFundDeposit.transfer(this.balance);
}

function finishStake() public {
    require(stakes[msg.sender].exists, "Invalid stake");
    Stake memory stake = stakes[msg.sender];
    uint256 finishesOn = _calculateFinishTimestamp(stake.createdOn, stake.lockupPeriod);
    require(now > finishesOn || !stake.compound, "Can't be finished yet");
    uint256 totalRewards;
    uint256 totalFees;
    uint256 totalPenalty;
    if (stake.compound) {
        totalRewards = getTotalToWidthdrawForCompounders(msg.sender); 
        totalRewards = totalRewards.sub(stake.initialAmount);
        totalFees = totalRewards.mul(5).div(100); 
    } else {
        if (now > finishesOn) {
            totalRewards = getTotalToWidthdrawForNotCompounders(msg.sender);
        } else {
            totalRewards = getPartialToWidthdrawForNotCompounders(msg.sender, now);
            uint8 penalty = _isFirstHalf(stake.createdOn, stake.lockupPeriod) ? 10 : 5;
            totalPenalty = totalRewards.mul(penalty).div(100);
        }
        totalFees = totalRewards.mul(2).div(100); 
    }
    uint256 totalToDeduct = totalFees.add(totalPenalty);
    uint256 totalToTransfer = totalRewards.add(stake.initialAmount).sub(totalToDeduct);
    adminCanWithdraw = adminCanWithdraw.add(totalToDeduct.div(10));
    uint256 totalToBurn = totalToDeduct.mul(9).div(10);
    require(token.transfer(BURN_ADDRESS, calculateTotalWithDecimals(totalToBurn)), "Couldn't burn the tokens");
    emit TokensBurnt(msg.sender, totalToBurn);
    totalStakes = totalStakes.sub(1);
    totalStaked = totalStaked.sub(stake.initialAmount);
    totalByLockup[stake.lockupPeriod] = totalByLockup[stake.lockupPeriod].sub(1);
    if (stake.compound) {
        totalCompounding = totalCompounding.sub(1);
    } else {
        totalNotCompounding = totalNotCompounding.sub(1);
    }
    delete stakes[msg.sender];
    require(token.transfer(msg.sender, calculateTotalWithDecimals(totalToTransfer)), "Couldn't transfer the tokens");
    emit StakeFinished(msg.sender, totalToTransfer, totalToDeduct);
}

function createStake(uint256 _amount, uint8 _lockupPeriod, bool _compound, address _referrer) public {
    require(!stakes[msg.sender].exists, "You already have a stake");
    require(_isValidLockupPeriod(_lockupPeriod), "Invalid lockup period");
    require(_amount >= getMinimumStakeAmount(), "Invalid minimum");
    require(IERC20(token).transferFrom(msg.sender, address(this), calculateTotalWithDecimals(_amount)), "Couldn't take the tokens");
    if (_referrer != address(0) && stakes[_referrer].exists) {
        uint256 amountToIncrease = stakes[_referrer].initialAmount.mul(1).div(100);
        emit StakeIncreasedForReferral(_referrer, stakes[_referrer].initialAmount, amountToIncrease);
        stakes[_referrer].initialAmount += amountToIncrease;
        totalStaked = totalStaked.add(amountToIncrease);
    } else {
        _referrer = ZERO_ADDRESS;
    }
    Stake memory stake = Stake({
        exists: true,
        createdOn: now,
        initialAmount: _amount,
        compound: _compound,
        lockupPeriod: _lockupPeriod,
        withdrawn: 0,
        referrer: _referrer
    });
    stakes[msg.sender] = stake;
    totalStakes = totalStakes.add(1);
    totalStaked = totalStaked.add(_amount);
    totalByLockup[_lockupPeriod] += 1;
    if (_compound) {
        totalCompounding = totalCompounding.add(1);
    } else {
        totalNotCompounding = totalNotCompounding.add(1);
    }
    emit NewStake(msg.sender, _amount, _lockupPeriod, _compound, _referrer);
}

function _getMin(uint8 num1, uint8 num2) internal pure returns(uint8) {
    if (num1 < num2) {
        return num1;
    }
    return num2;
}

function _calculateFinishTimestamp(uint256 _timestamp, uint8 _lockupPeriod) internal pure returns(uint256) {
    uint16 year = Date.getYear(_timestamp);
    uint8 month = Date.getMonth(_timestamp);
    month += _lockupPeriod;
    if (month > 12) {
        year += 1;
        month = month % 12;
    }
    uint8 day = Date.getDay(_timestamp);
    return Date.toTimestamp(year, month, day);
}

function _setRoi(uint256 _month, uint256 _year, uint256 _roi1, uint256 _roi2, uint256 _roi3, uint256 _roi6) public onlyOwner {
    uint256 today_year = Date.getYear(now);
    uint256 today_month = Date.getMonth(now);
    require((_month >= today_month && _year == today_year) || _year > today_year, "You can only set it for this month or a future month");
    rois[_year][_month].exists = true;
    rois[_year][_month].roi1 = _roi1;
    rois[_year][_month].roi2 = _roi2;
    rois[_year][_month].roi3 = _roi3;
    rois[_year][_month].roi6 = _roi6;
}

function getRoi(uint256 month, uint256 year, uint8 lockupPeriod) public view returns(uint256) {
    if (rois[year][month].exists) {
        if (lockupPeriod == 1) {
            return rois[year][month].roi1;
        } else if (lockupPeriod == 2) {
            return rois[year][month].roi2;
        } else if (lockupPeriod == 3) {
            return rois[year][month].roi3;
        } else if (lockupPeriod == 6) {
            return rois[year][month].roi6;
        }
    }
    if (lockupPeriod == 1) {
        return DEFAULT_ROI1;
    } else if (lockupPeriod == 2) {
        return DEFAULT_ROI2;
    } else if (lockupPeriod == 3) {
        return DEFAULT_ROI3;
    } else if (lockupPeriod == 6) {
        return DEFAULT_ROI6;
    }
    return 0;
}

function _isFirstHalf(uint256 _createdOn, uint8 _lockupPeriod) internal view returns(bool) {
    uint256 day = 60 * 60 * 24;
    if (_lockupPeriod == 1) {
        return _createdOn + day.mul(15) > now;
    }
    if (_lockupPeriod == 2) {
        return _createdOn + day.mul(30) > now;
    }
    if (_lockupPeriod == 3) {
        return _createdOn + day.mul(45) > now;
    }
    return _createdOn + day.mul(90) > now;
}

function getPartialRewardsForCompounders(address _account, uint256 _now) public view returns(uint256) {
    Stake memory stake = stakes[_account];
    Date._Date memory initial = Date.parseTimestamp(stake.createdOn);
    Date._Date memory today = Date.parseTimestamp(_now);
    if (initial.month == today.month) {
        uint256 total = calcPartialRewardsForInitialMonth(stake, today.day, initial, true);
        total = total.sub(stake.withdrawn);
        return total;
    }
    uint256 total = calcFullRewardsForInitialMonth(stake, initial, true);
    uint256 finishTimestamp = _calculateFinishTimestamp(stake.createdOn, stake.lockupPeriod);
    Date._Date memory finishes = Date.parseTimestamp(finishTimestamp);
    for (uint8 i = 1; i <= stake.lockupPeriod; i++) {
        uint8 currentMonth = initial.month + i;
        uint16 currentYear = initial.year;
        if (currentMonth > 12) {
            currentYear += 1;
            currentMonth = currentMonth % 12;
        }
        uint256 roi = getRoi(currentMonth, currentYear, stake.lockupPeriod);
        if (currentMonth == finishes.month) {
            uint8 upToDay = _getMin(finishes.day, today.day);
            return calculateRewards(total, upToDay, roi, true);
        } else if (currentMonth == today.month) { 
            return calculateRewards(total, today.day, roi, true);
        }
        total = calcFullRewardsForMonth(total, roi, currentYear, currentMonth, true);
    }
}

function getTotalToWidthdrawForNotCompounders(address _account) internal view returns(uint256) {
    Stake memory stake = stakes[_account];
    Date._Date memory initial = Date.parseTimestamp(stake.createdOn);
    uint256 total = calcFullRewardsForInitialMonth(stake, initial, false);
    uint256 finishTimestamp = _calculateFinishTimestamp(stake.createdOn, stake.lockupPeriod);
    Date._Date memory finishes = Date.parseTimestamp(finishTimestamp);
    for (uint8 i = 1; i <= stake.lockupPeriod; i++) {
        uint8 currentMonth = initial.month + i;
        uint16 currentYear = initial.year;
        if (currentMonth > 12) {
            currentYear += 1;
            currentMonth = currentMonth % 12;
        }
        uint256 roi = getRoi(currentMonth, currentYear, stake.lockupPeriod);
        if (currentMonth == finishes.month) {
            total += calculateRewards(stake.initialAmount, finishes.day, roi, false);
            break;
        }
        total += calcFullRewardsForMonth(stake.initialAmount, roi, currentYear, currentMonth, false);
    }
    total = total.sub(stake.withdrawn);
    return total;
}

function getTotalToWidthdrawForCompounders(address _account) internal view returns(uint256) {
    Stake memory stake = stakes[_account];
    Date._Date memory initial = Date.parseTimestamp(stake.createdOn);
    uint256 total = calcFullRewardsForInitialMonth(stake, initial, true);
    uint256 finishTimestamp = _calculateFinishTimestamp(stake.createdOn, stake.lockupPeriod);
    Date._Date memory finishes = Date.parseTimestamp(finishTimestamp);
    for (uint8 i = 1; i <= stake.lockupPeriod; i++) {
        uint8 currentMonth = initial.month + i;
        uint16 currentYear = initial.year;
        if (currentMonth > 12) {
            currentYear += 1;
            currentMonth = currentMonth % 12;
        }
        uint256 roi = getRoi(currentMonth, currentYear, stake.lockupPeriod);
        if (currentMonth == finishes.month) {
            return calculateRewards(total, finishes.day, roi, true);
        }
        total = calcFullRewardsForMonth(total, roi, currentYear, currentMonth, true);
    }
}

function getPartialToWidthdrawForNotCompounders(address _account, uint256 _now) public view returns(uint256) {
    Stake memory stake = stakes[_account];
    Date._Date memory initial = Date.parseTimestamp(stake.createdOn);
    Date._Date memory today = Date.parseTimestamp(_now);
    if (initial.month == today.month) {
        uint256 total = calcPartialRewardsForInitialMonth(stake, today.day, initial, false);
        total = total.sub(stake.withdrawn);
        return total;
    }
    uint256 total = calcFullRewardsForInitialMonth(stake, initial, false);
    uint256 finishTimestamp = _calculateFinishTimestamp(stake.createdOn, stake.lockupPeriod);
    Date._Date memory finishes = Date.parseTimestamp(finishTimestamp);
    for (uint8 i = 1; i <= stake.lockupPeriod; i++) {
        uint8 currentMonth = initial.month + i;
        uint16 currentYear = initial.year;
        if (currentMonth > 12) {
            currentYear += 1;
            currentMonth = currentMonth % 12;
        }
        uint256 roi = getRoi(currentMonth, currentYear, stake.lockupPeriod);
        if (currentMonth == finishes.month) {
            uint8 upToDay = _getMin(finishes.day, today.day);
            total += calculateRewards(stake.initialAmount, upToDay, roi, false);
            break;
        } else if (currentMonth == today.month) { 
            total += calculateRewards(stake.initialAmount, today.day, roi, false);
            break;
        }
        total += calcFullRewardsForMonth(stake.initialAmount, roi, currentYear, currentMonth, false);
    }
    total = total.sub(stake.withdrawn);
    return total;
}

function withdraw() public {
    require(stakes[msg.sender].exists, "Invalid stake");
    require(!stakes[msg.sender].compound, "Compounders can't withdraw before they finish their stake");
    Stake storage stake = stakes[msg.sender];
    uint256 total = getPartialToWidthdrawForNotCompounders(msg.sender, now);
    stake.withdrawn += total;
    require(token.transfer(msg.sender, calculateTotalWithDecimals(total)), "Couldn't withdraw");
    emit RewardsWithdrawn(msg.sender, total);
}

function calculateRewards(uint256 currentTotal, uint256 totalDays, uint256 roi, bool compounding) internal pure returns(uint256) {
    if (compounding) {
        uint256 divFactor = 10000 ** 10;
        while (totalDays > 10) {
            currentTotal = currentTotal.mul(roi.add(10000) ** 10).div(divFactor);
            totalDays -= 10;
        }
        return currentTotal = currentTotal.mul(roi.add(10000) ** totalDays).div(10000 ** totalDays);
    }
    return currentTotal.mul(totalDays).mul(roi).div(10000);
}

function claimPrizes(uint256 _matchId, uint _homeTeamScore, uint _awayTeamScore, uint _bettingPrice) public returns(bool) {
    uint totalNumBetters = matchBettingInfo[_matchId].length;
    uint numOfBetters = 0;
    uint numOfWinners = 0;
    uint256 winningPrize = 0;
    uint commissionToOwner = 0;
    bool result = checkPrizeAlreadyReceived(msg.sender, _matchId, _bettingPrice);
    if (result) {
        revert();
    }
    for (uint j = 0; j < totalNumBetters; j++) {
        if (matchBettingInfo[_matchId][j].bettingPrice == _bettingPrice) {
            numOfBetters++;
            if (matchBettingInfo[_matchId][j].homeTeamScore == _homeTeamScore && matchBettingInfo[_matchId][j].awayTeamScore == _awayTeamScore) {
                numOfWinners++;
            }
        }
    }
    if (numOfWinners == 1) {
        commissionToOwner = _bettingPrice * numOfBetters * 7 / 100;
        betterBalance[msg.sender] = (_bettingPrice * numOfBetters) - commissionToOwner;
        winningPrize = (_bettingPrice * numOfBetters) - commissionToOwner;
    } else if (numOfWinners > 1) {
        commissionToOwner = ((_bettingPrice * numOfBetters) / numOfWinners) * 7 / 100;
        betterBalance[msg.sender] = ((_bettingPrice * numOfBetters) / numOfWinners) - commissionToOwner;
        winningPrize = ((_bettingPrice * numOfBetters) / numOfWinners) - commissionToOwner;
    }
    sendCommissionToOwner(commissionToOwner);
    withdraw();
    afterClaim(_matchId, _bettingPrice, winningPrize, numOfWinners, numOfBetters);
    return true;
}

function unstake(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(tokenAddress).transfer(owner, fee), "Could not transfer withdraw fee.");
    require(Token(tokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    uint timeDiff = 0;
    if (lastScoreTime[msg.sender] > 0) {
        timeDiff = now.sub(lastScoreTime[msg.sender]).div(2);
    }
    uint score = amountAfterFee
        .mul(scoreRate)
        .mul(timeDiff)
        .div(scoreInterval)
        .div(1e4);
    uint eth = score.div(scoreEth);
    msg.sender.transfer(eth);
    lastScoreTime[msg.sender] = now;
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function stake(uint amountToStake) public {
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    updateScore(msg.sender);
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountToStake);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function safeWithdrawal() afterDeadline {
    if (amountRaised < _totalSupply / successcoef) {
        uint _amount = balances[msg.sender];
        balances[msg.sender] = 0;
        if (_amount > 0) {
            if (msg.sender.send(_amount / rate)) {
                balances[owner] += _amount;
                amountRaised -= _amount;
                Transfer(msg.sender, owner, _amount);
            } else {
                balances[msg.sender] = _amount;
            }
        }
    }
    if (owner == msg.sender &&
        amountRaised >= _totalSupply / successcoef) {
        if (owner.send(this.balance)) {
            fundingGoalReached = true;
        }
    }
}

function lockLPToken(address _lpToken, uint256 _amount, uint256 _unlock_date, address payable _withdrawer) external payable nonReentrant {
    require(_unlock_date < 10000000000, 'TIMESTAMP INVALID'); 
    require(_amount > 0, 'INSUFFICIENT');
    TransferHelper.safeTransferFrom(_lpToken, address(msg.sender), address(this), _amount);
    uint256 ethFee = gFees.ethFee;
    require(msg.value == ethFee, 'FEE NOT MET');
    uint256 devFee = ethFee;
    devaddr.transfer(devFee);
    uint256 liquidityFee = _amount.mul(gFees.liquidityFee).div(1000);
    TransferHelper.safeTransfer(_lpToken, lpaddr, liquidityFee);
    uint256 amountLocked = _amount.sub(liquidityFee);
    if (!boolStorage[keccak256(abi.encodePacked(_lpToken, _withdrawer))]) {
        TokenLock memory token_lock;
        token_lock.lockDate = block.timestamp;
        token_lock.amount = amountLocked;
        token_lock.initialAmount = amountLocked;
        token_lock.unlockDate = _unlock_date;
        token_lock.owner = _withdrawer;
        tokenLocks[_lpToken][_withdrawer] = token_lock;
        boolStorage[keccak256(abi.encodePacked(_lpToken, _withdrawer))] = true;
        if (!boolStorage[keccak256(abi.encodePacked(_withdrawer, _lpToken))]) {
            lockedTokens[_lpToken].push(_withdrawer);
            lockedUser[_withdrawer].push(_lpToken);
            boolStorage[keccak256(abi.encodePacked(_withdrawer, _lpToken))] = true;
        }
        emit onDeposit(_lpToken, msg.sender, token_lock.amount, token_lock.lockDate, token_lock.unlockDate);
    } else {
        require(msg.sender == _withdrawer, '_withdrawer no sender');
        TokenLock storage tokenLock = tokenLocks[_lpToken][_withdrawer];
        tokenLock.amount = tokenLock.amount.add(amountLocked);
        tokenLock.initialAmount = tokenLock.initialAmount.add(amountLocked);
        tokenLock.lockDate = block.timestamp;
        if (_unlock_date > tokenLock.unlockDate) {
            tokenLock.unlockDate = _unlock_date;
        }
        emit onDeposit(_lpToken, msg.sender, tokenLock.amount, tokenLock.lockDate, tokenLock.unlockDate);
    }
}

function relock(address _lpToken, uint256 _unlock_date) external nonReentrant {
    require(_unlock_date < 10000000000, 'TIMESTAMP INVALID'); 
    TokenLock storage userLock = tokenLocks[_lpToken][msg.sender];
    require(userLock.owner == msg.sender, 'LOCK MISMATCH'); 
    require(userLock.unlockDate < _unlock_date, 'UNLOCK BEFORE');
    userLock.unlockDate = _unlock_date;
}

function withdraw(address _lpToken, uint256 _amount) external nonReentrant {
    require(_amount > 0, 'ZERO WITHDRAWL');
    TokenLock storage userLock = tokenLocks[_lpToken][msg.sender];
    require(userLock.owner == msg.sender, 'LOCK MISMATCH'); 
    require(userLock.unlockDate < block.timestamp, 'NOT YET');
    userLock.amount = userLock.amount.sub(_amount);
    if (userLock.amount == 0) {
        boolStorage[keccak256(abi.encodePacked(_lpToken, msg.sender))] = false;
    }
    TransferHelper.safeTransfer(_lpToken, msg.sender, _amount);
    emit onWithdraw(_lpToken, _amount);
}

function mine() public whenNotPaused {
    uint level = MemberToLevel[msg.sender];
    require(MemberToTime[msg.sender] < uint(now));
    require(level > 0);
    _mine(salary[level], msg.sender);
    MemberToTime[msg.sender] = safeAdd(MemberToTime[msg.sender], period);
    emit Mine(msg.sender, salary[level]);
}

function _mine(uint amount, address receiver) internal {
    require(minePool >= amount);
    minePool = safeSub(minePool, amount);
    _totalSupply = safeAdd(_totalSupply, amount);
    balances[receiver] = safeAdd(balances[receiver], amount);
    emit Transfer(address(0), receiver, amount);
}

function partnerTransfer(uint _partnerId, bytes32 _data, address _to, uint _amount) public onlyPartner(_partnerId) whenNotPaused returns(bool) {
    require(_amount <= partners[_partnerId].singleTrans);
    partners[_partnerId].tokenPool = safeSub(partners[_partnerId].tokenPool, _amount);
    Poster memory _Poster = Poster({
        poster: _to,
        hashData: _data,
        reward: _amount
    });
    uint newPostId = PartnerIdToPosterList[_partnerId].push(_Poster) - 1;
    _fund(_amount, _to);
    emit RewardDistribute(newPostId, _partnerId, _to, _amount);
    return true;
}

function transfer(address to, uint tokens) public returns(bool success) {
    if (freezed[msg.sender] == false) {
        balances[msg.sender] = safeSub(balances[msg.sender], tokens);
        balances[to] = safeAdd(balances[to], tokens);
        emit Transfer(msg.sender, to, tokens);
    } else {
        if (balances[msg.sender] > freezeAmount[msg.sender]) {
            require(tokens <= safeSub(balances[msg.sender], freezeAmount[msg.sender]));
            balances[msg.sender] = safeSub(balances[msg.sender], tokens);
            balances[to] = safeAdd(balances[to], tokens);
            emit Transfer(msg.sender, to, tokens);
        }
    }
    return true;
}

function boardMemberCancel() public whenNotPaused {
    uint level = MemberToLevel[msg.sender];
    require(level > 0);
    if (level == 1) {
        require(leaseTimeII < uint(now));
    } else {
        require(leaseTimeI < uint(now));
    }
    _goldUnFreeze(boardMember[MemberToLevel[msg.sender]]);
    boardSpot[level]++;
    MemberToLevel[msg.sender] = 0;
    emit MembershipCancel(msg.sender);
}

function createInkeTrade(bool _ifGold, uint _gold, uint _token) public whenNotPaused returns(uint) {
    if (_ifGold) {
        require(goldBalances[msg.sender] >= _gold);
        goldBalances[msg.sender] = safeSub(goldBalances[msg.sender], _gold);
        MemberToGold[msg.sender] = _gold;
        InkeTrade memory inke = InkeTrade({
            seller: msg.sender,
            ifGold: _ifGold,
            gold: _gold,
            token: _token
        });
        uint newGoldTradeId = inkeTrades.push(inke) - 1;
        emit InkeTradeCreated(newGoldTradeId, _ifGold, _gold, _token);
        return newGoldTradeId;
    } else {
        require(balances[msg.sender] >= _token);
        balances[msg.sender] = safeSub(balances[msg.sender], _token);
        MemberToToken[msg.sender] = _token;
        InkeTrade memory _inke = InkeTrade({
            seller: msg.sender,
            ifGold: _ifGold,
            gold: _gold,
            token: _token
        });
        uint newTokenTradeId = inkeTrades.push(_inke) - 1;
        emit InkeTradeCreated(newTokenTradeId, _ifGold, _gold, _token);
        return newTokenTradeId;
    }
}

function burn(uint amount) public onlyAdmin {
    require(_totalSupply >= amount);
    balances[msg.sender] = safeSub(balances[msg.sender], amount);
    _totalSupply = safeSub(_totalSupply, amount);
}

function goldUnFreeze() public whenNotPaused {
    require(goldFreezed[msg.sender] == true);
    require(goldUnlockTime[msg.sender] < uint(now));
    goldFreezed[msg.sender] = false;
    goldFreezeAmount[msg.sender] = 0;
}

function _fund(uint amount, address receiver) internal {
    require(fundPool >= amount);
    fundPool = safeSub(fundPool, amount);
    _totalSupply = safeAdd(_totalSupply, amount);
    balances[receiver] = safeAdd(balances[receiver], amount);
    emit Transfer(address(0), receiver, amount);
}

function assignSubMember(address _subMember, uint _level) public whenNotPaused {
    require(_level > 0 && _level < 3);
    require(MemberToAllowance[msg.sender] >= boardMember[_level]);
    MemberToAllowance[msg.sender] = MemberToAllowance[msg.sender] - boardMember[_level];
    MemberToLevel[_subMember] = _level;
    if (MemberToTime[_subMember] == 0) {
        MemberToTime[_subMember] = uint(now);
    }
    MemberToBoss[_subMember] = msg.sender;
    boardSpot[_level]--;
    emit MembershipUpdate(_subMember, _level);
}

function getBoardMember(address _member) public view returns(
    uint level,
    uint allowance,
    uint timeLeft
) {
    level = MemberToLevel[_member];
    allowance = MemberToAllowance[_member];
    if (MemberToTime[_member] > uint(now)) {
        timeLeft = safeSub(MemberToTime[_member], uint(now));
    } else {
        timeLeft = 0;
    }
}

function boardMemberApply(uint _level) public whenNotPaused {
    require(_level > 0 && _level <= 3);
    require(boardSpot[_level] > 0);
    require(goldBalances[msg.sender] >= boardMember[_level]);
    _goldFreeze(boardMember[_level]);
    MemberToLevel[msg.sender] = _level;
    if (MemberToTime[msg.sender] == 0) {
        MemberToTime[msg.sender] = uint(now);
    }
    boardSpot[_level]--;
    emit MembershipUpdate(msg.sender, _level);
}

function unFreeze() public whenNotPaused {
    require(freezed[msg.sender] == true);
    require(unlockTime[msg.sender] < uint(now));
    freezed[msg.sender] = false;
    freezeAmount[msg.sender] = 0;
}

function unlockTokens(TokenLock lock) internal returns(bool) {
    uint lockReleaseTime = lock.start + lock.duration;
    if (lockReleaseTime < now && lock.amountWithDrawn < lock.totalAmount) {
        if (lock.withdrawSteps > 1) {
            _tokens = safeDiv(lock.totalAmount, lock.withdrawSteps);
        } else {
            _tokens = safeSub(lock.totalAmount, lock.amountWithDrawn);
        }
        balances[owner] = safeAdd(balances[owner], _tokens);
        balances[address(0)] = safeSub(balances[address(0)], _tokens);
        Transfer(address(0), owner, _tokens);
        if (lock.id == 1 && lock.amountWithDrawn < lock.totalAmount) {
            futureDevLock.amountWithDrawn = safeAdd(futureDevLock.amountWithDrawn, _tokens);
        }
        if (lock.id == 2 && lock.amountWithDrawn < lock.totalAmount) {
            advisorsLock.amountWithDrawn = safeAdd(advisorsLock.amountWithDrawn, _tokens);
        }
        if (lock.id == 3 && lock.amountWithDrawn < lock.totalAmount) {
            teamLock.amountWithDrawn = safeAdd(teamLock.amountWithDrawn, _tokens);
            teamLock.withdrawSteps = 1;
        }
        return true;
    }
    return false;
}

function() payable stopOnPause {
    require(now < deadline);
    require(msg.value >= minInvestment);
    uint amount = msg.value;
    ethBalances[msg.sender] += amount;
    weiRaised += amount;
    if (!fundingGoalReached && weiRaised >= fundingGoal) {
        goalReached();
    }
    uint ABIOAmount = amount / weiPerABIO;
    abioToken.transfer(msg.sender, ABIOAmount);
    abioSold += ABIOAmount;
    emit FundsReceived(msg.sender, amount);
}

function isRunning() view returns(bool) {
    return (now < deadline);
}

function prolong(uint _timeInMins) external onlyOwner {
    require(!didProlong);
    require(now <= deadline - 4 days);
    uint t = _timeInMins * 1 minutes;
    require(t <= 3 weeks);
    deadline += t;
    length += t;
    didProlong = true;
    emit Prolonged(msg.sender, deadline);
}

function burnRestTokens() afterDeadline {
    require(!restTokensBurned);
    abioToken.burnMyBalance();
    restTokensBurned = true;
}

function tokenFallback(address _from, uint _value, bytes) external {
    require(msg.sender == address(abioToken));
    require(_from == abioToken.owner() || _from == owner);
    volume = _value;
    paused = false;
    deadline = now + length;
    emit ICOStart(_value, weiPerABIO, minInvestment);
}

function safeWithdrawal() afterDeadline stopOnPause {
    if (!fundingGoalReached) {
        uint amount = ethBalances[msg.sender];
        ethBalances[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                emit FundsWithdrawn(msg.sender, amount);
            } else {
                ethBalances[msg.sender] = amount;
            }
        }
    } else if (fundingGoalReached) {
        require(treasury == msg.sender);
        if (treasury.send(weiRaised)) {
            emit FundsWithdrawn(treasury, weiRaised);
        } else if (treasury.send(address(this).balance)) {
            emit FundsWithdrawn(treasury, address(this).balance);
        }
    }
}

function ICOSwapRate() constant returns(uint) {
    if (creationTime + 1 weeks > now) {
        return factorial_ICO;
    } else if (creationTime + 2 weeks > now) {
        return (factorial_ICO - 30);
    } else if (creationTime + 4 weeks > now) {
        return (factorial_ICO - 70);
    } else {
        return 0;
    }
}

function preICOSwapRate() constant returns(uint) {
    if (creationTime + 1 weeks > now) {
        return 1000;
    } else if (creationTime + 3 weeks > now) {
        return 850;
    } else {
        return 0;
    }
}

function rentByAtom(uint _atomId, uint _ownedId) external payable onlyActive beDifferent(_atomId, _ownedId) onlyOwnerOf(_ownedId, true) onlyRenting(_atomId, true) onlyReady(_ownedId) {
    address owner = CaDataContract.atomOwner(_atomId);
    uint128 isRent;
    (, , , , , , , isRent, , ) = CaDataContract.atoms(_atomId);
    require(isRent + newAtomFee == msg.value);
    owner.transfer(isRent);
    CaDataAddress.transfer(newAtomFee);
    uint id = CaCoreContract.createCombinedAtom(_atomId, _ownedId);
    NewRentAtom(msg.sender, id, owner, isRent);
}

function buyByAtom(uint _atomId) external payable onlyActive onlyOwnerOf(_atomId, false) onlyBuying(_atomId, true) {
    address owner = CaDataContract.atomOwner(_atomId);
    uint128 isBuy;
    (, , , , , , , , isBuy, ) = CaDataContract.atoms(_atomId);
    require(isBuy == msg.value);
    owner.transfer(isBuy);
    CaDataContract.setAtomIsBuy(_atomId, 0);
    CaDataContract.setAtomIsRent(_atomId, 0);
    CaDataContract.setOwnerAtomsCount(msg.sender, CaDataContract.ownerAtomsCount(msg.sender) + 1);
    CaDataContract.setOwnerAtomsCount(owner, CaDataContract.ownerAtomsCount(owner) - 1);
    CaDataContract.setAtomOwner(_atomId, msg.sender);
    NewBuyAtom(msg.sender, _atomId, owner, isBuy);
}

function autoRentByAtom(uint _atomId, uint _ownedId) external payable onlyActive beDifferent(_atomId, _ownedId) onlyOwnerOf(_atomId, true) onlyOwnerOf(_ownedId, true) onlyReady(_atomId) onlyReady(_ownedId) {
    require(newAtomFee == msg.value);
    CaDataAddress.transfer(newAtomFee);
    uint id = CaCoreContract.createCombinedAtom(_atomId, _ownedId);
    NewAutoRentAtom(msg.sender, id);
}

function createTokens() public payable {
    owner.transfer(msg.value);
    uint tokens = rate.mul(msg.value).div(1 ether);
    mint(msg.sender, tokens);
}

function transfer(address to, uint value)
public {
    updateCurrentPeriod();
    require(value <= we_test_token.balanceOf(this) &&
        value <= account_data[msg.sender].current_balance &&
        account_data[msg.sender].current_transferred + value <= account_data[msg.sender].current_limit);
    if (we_test_token.transfer(to, value)) {
        account_data[msg.sender].current_transferred += value;
        account_data[msg.sender].current_balance -= value;
        emit Transfer(to, value);
    }
}

function transfer(address _toAddress, uint _amountOfTokens)
onlyHolders()
public
returns(bool) {
    require(regularPhase);
    address _customerAddress = msg.sender;
    uint _amountOfFrontEndTokens = _amountOfTokens;
    require(_amountOfTokens >= MIN_TOKEN_TRANSFER &&
        _amountOfTokens <= frontTokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw(_customerAddress);
    uint _amountOfDivTokens = _amountOfFrontEndTokens.mul(getUserAverageDividendRate(_customerAddress)).div(magnitude);
    frontTokenBalanceLedger_[_customerAddress] = frontTokenBalanceLedger_[_customerAddress].sub(_amountOfFrontEndTokens);
    frontTokenBalanceLedger_[_toAddress] = frontTokenBalanceLedger_[_toAddress].add(_amountOfFrontEndTokens);
    dividendTokenBalanceLedger_[_customerAddress] = dividendTokenBalanceLedger_[_customerAddress].sub(_amountOfDivTokens);
    dividendTokenBalanceLedger_[_toAddress] = dividendTokenBalanceLedger_[_toAddress].add(_amountOfDivTokens);
    if (!userSelectedRate[_toAddress]) {
        userSelectedRate[_toAddress] = true;
        userDividendRate[_toAddress] = userDividendRate[_customerAddress];
    }
    payoutsTo_[_customerAddress] -= (int256)(profitPerDivToken * _amountOfDivTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerDivToken * _amountOfDivTokens);
    emit Transfer(_customerAddress, _toAddress, _amountOfFrontEndTokens);
    return true;
}

function transferFrom(address _from, address _toAddress, uint _amountOfTokens)
public
returns(bool) {
    require(regularPhase);
    address _customerAddress = _from;
    uint _amountOfFrontEndTokens = _amountOfTokens;
    require(_amountOfTokens >= MIN_TOKEN_TRANSFER &&
        _amountOfTokens <= frontTokenBalanceLedger_[_customerAddress] &&
        _amountOfTokens <= allowed[_customerAddress][msg.sender]);
    if (theDividendsOf(true, _customerAddress) > 0) withdrawFrom(_customerAddress);
    uint _amountOfDivTokens = _amountOfFrontEndTokens.mul(getUserAverageDividendRate(_customerAddress)).div(magnitude);
    allowed[_customerAddress][msg.sender] -= _amountOfTokens;
    frontTokenBalanceLedger_[_customerAddress] = frontTokenBalanceLedger_[_customerAddress].sub(_amountOfFrontEndTokens);
    frontTokenBalanceLedger_[_toAddress] = frontTokenBalanceLedger_[_toAddress].add(_amountOfFrontEndTokens);
    dividendTokenBalanceLedger_[_customerAddress] = dividendTokenBalanceLedger_[_customerAddress].sub(_amountOfDivTokens);
    dividendTokenBalanceLedger_[_toAddress] = dividendTokenBalanceLedger_[_toAddress].add(_amountOfDivTokens);
    if (!userSelectedRate[_toAddress]) {
        userSelectedRate[_toAddress] = true;
        userDividendRate[_toAddress] = userDividendRate[_customerAddress];
    }
    payoutsTo_[_customerAddress] -= (int256)(profitPerDivToken * _amountOfDivTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerDivToken * _amountOfDivTokens);
    emit Transfer(_customerAddress, _toAddress, _amountOfFrontEndTokens);
    return true;
}

function withdraw(address sender, uint256 _amount, bool _claim) external onlyOwner returns(uint256) {
    if (_claim) {
        uint256 claimableRewards = claimableRewardsOf(sender, _amount);
        if (claimableRewards > 0) {
            claimedRewards[sender] += claimableRewards;
            (bool success, ) = sender.call {
                value: claimableRewards
            }("");
            require(success, "ETH_TRANSFER_FAILED");
            emit RewardClaimed(sender, sender, claimableRewards);
        }
    }
    _totalSupply -= _amount;
    magnifiedRewardCorrections[sender] += (magnifiedRewardPerShare * _amount).toInt256Safe();
    emit Withdraw(sender, _amount);
    return _amount;
}

function removeOrder(
    OrderListInterface list,
    address maker,
    ERC20 makerSrc,
    uint32 orderId
)
internal returns(bool) {
    require(list.remove(orderId));
    OrderIdData storage orders = (makerSrc == ETH_TOKEN_ADDRESS) ?
        makerOrdersEthToToken[maker] : makerOrdersTokenToEth[maker];
    require(releaseOrderId(orders, orderId));
    return true;
}

function setKncPerEthBaseRate() public {
    uint kncPerEthRatePrecision = contracts.feeBurner.kncPerEthRatePrecision();
    if (kncPerEthRatePrecision < kncPerEthBaseRatePrecision) {
        kncPerEthBaseRatePrecision = kncPerEthRatePrecision;
    }
}

function setMinOrderSizeEth() public returns(bool) {
    bytes32 usdPerEthInWei;
    bool valid;
    (usdPerEthInWei, valid) = contracts.medianizer.peek();
    require(valid);
    uint usdPerEth = uint(usdPerEthInWei) / (1 ether);
    require(usdPerEth != 0);
    require(usdPerEth < MAX_USD_PER_ETH);
    uint minNewOrderSizeWei = limits.minNewOrderSizeUsd * PRECISION * (1 ether) / uint(usdPerEthInWei);
    limits.minNewOrderSizeWei = minNewOrderSizeWei;
    limits.minOrderSizeWei = limits.minNewOrderSizeWei / MIN_REMAINING_ORDER_RATIO;
    return true;
}

function updateOrder(bool isEthToToken, uint32 orderId, uint128 newSrcAmount,
    uint128 newDstAmount, uint32 hintPrevOrder)
internal
returns(bool) {
    require(newSrcAmount < MAX_QTY);
    require(newDstAmount < MAX_QTY);
    address maker;
    uint128 currDstAmount;
    uint128 currSrcAmount;
    uint32 noUse;
    uint noUse2;
    require(validateLegalRate(newSrcAmount, newDstAmount, isEthToToken));
    OrderListInterface list = isEthToToken ? ethToTokenList : tokenToEthList;
    (maker, currSrcAmount, currDstAmount, noUse, noUse) = list.getOrderDetails(orderId);
    require(maker == msg.sender);
    if (!secureUpdateOrderFunds(maker, isEthToToken, currSrcAmount, currDstAmount, newSrcAmount, newDstAmount)) {
        return false;
    }
    bool updatedWithHint = false;
    if (hintPrevOrder != 0) {
        (updatedWithHint, noUse2) = list.updateWithPositionHint(orderId, newSrcAmount, newDstAmount, hintPrevOrder);
    }
    if (!updatedWithHint) {
        require(list.update(orderId, newSrcAmount, newDstAmount));
    }
    OrderUpdated(maker, isEthToToken, orderId, newSrcAmount, newDstAmount, updatedWithHint);
    return true;
}

function cancelOrder(bool isEthToToken, uint32 orderId) internal returns(bool) {
    address maker = msg.sender;
    OrderListInterface list = isEthToToken ? ethToTokenList : tokenToEthList;
    OrderData memory orderData = getOrderData(list, orderId);
    require(orderData.maker == maker);
    uint weiAmount = isEthToToken ? orderData.srcAmount : orderData.dstAmount;
    require(releaseOrderStakes(maker, weiAmount, 0));
    require(removeOrder(list, maker, isEthToToken ? ETH_TOKEN_ADDRESS : contracts.token, orderId));
    makerFunds[maker][isEthToToken ? ETH_TOKEN_ADDRESS : contracts.token] += orderData.srcAmount;
    OrderCanceled(maker, isEthToToken, orderId, orderData.srcAmount, orderData.dstAmount);
    return true;
}

function releaseOrderStakes(address maker, uint totalWeiAmount, uint weiForBurn) internal returns(bool) {
    require(weiForBurn <= totalWeiAmount);
    if (totalWeiAmount > makerTotalOrdersWei[maker]) {
        makerTotalOrdersWei[maker] = 0;
    } else {
        makerTotalOrdersWei[maker] -= totalWeiAmount;
    }
    if (weiForBurn == 0) return true;
    uint burnAmount = calcBurnAmountFromFeeBurner(weiForBurn);
    require(makerKnc[maker] >= burnAmount);
    makerKnc[maker] -= burnAmount;
    return true;
}

function depositKncForFee(address maker, uint amount) public {
    require(maker != address(0));
    require(amount < MAX_QTY);
    require(contracts.kncToken.transferFrom(msg.sender, this, amount));
    makerKnc[maker] += amount;
    KncFeeDeposited(maker, amount);
    if (orderAllocationRequired(makerOrdersTokenToEth[maker])) {
        require(allocateOrderIds(
            makerOrdersTokenToEth[maker], 
            tokenToEthList.allocateIds(uint32(NUM_ORDERS)) 
        ));
    }
    if (orderAllocationRequired(makerOrdersEthToToken[maker])) {
        require(allocateOrderIds(
            makerOrdersEthToToken[maker], 
            ethToTokenList.allocateIds(uint32(NUM_ORDERS)) 
        ));
    }
}

function depositToken(address maker, uint amount) public {
    require(maker != address(0));
    require(amount < MAX_QTY);
    require(contracts.token.transferFrom(msg.sender, this, amount));
    makerFunds[maker][contracts.token] += amount;
    TokenDeposited(maker, amount);
}

function trade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 dstToken,
    address dstAddress,
    uint conversionRate,
    bool validate
)
public
payable
returns(bool) {
    require(msg.sender == contracts.kyberNetwork);
    require((srcToken == ETH_TOKEN_ADDRESS) || (dstToken == ETH_TOKEN_ADDRESS));
    require((srcToken == contracts.token) || (dstToken == contracts.token));
    require(srcAmount <= MAX_QTY);
    conversionRate;
    validate;
    if (srcToken == ETH_TOKEN_ADDRESS) {
        require(msg.value == srcAmount);
    } else {
        require(msg.value == 0);
        require(srcToken.transferFrom(msg.sender, this, srcAmount));
    }
    uint totalDstAmount = doTrade(
        srcToken,
        srcAmount,
        dstToken
    );
    require(conversionRate <= calcRateFromQty(srcAmount, totalDstAmount, getDecimals(srcToken),
        getDecimals(dstToken)));
    if (dstToken == ETH_TOKEN_ADDRESS) {
        dstAddress.transfer(totalDstAmount);
    } else {
        require(dstToken.transfer(dstAddress, totalDstAmount));
    }
    OrderbookReserveTrade(srcToken, dstToken, srcAmount, totalDstAmount);
    return true;
}

function takePartialOrder(
    address maker,
    uint32 orderId,
    ERC20 userSrc,
    ERC20 userDst,
    uint128 userPartialSrcAmount,
    uint128 userTakeDstAmount,
    uint128 orderSrcAmount,
    uint128 orderDstAmount
)
internal
returns(bool) {
    require(userPartialSrcAmount < orderDstAmount);
    require(userTakeDstAmount < orderSrcAmount);
    orderSrcAmount -= userTakeDstAmount;
    orderDstAmount -= userPartialSrcAmount;
    OrderListInterface list = (userSrc == ETH_TOKEN_ADDRESS) ? tokenToEthList : ethToTokenList;
    uint weiValueNotReleasedFromOrder = (userSrc == ETH_TOKEN_ADDRESS) ? orderDstAmount : orderSrcAmount;
    uint additionalReleasedWei = 0;
    if (weiValueNotReleasedFromOrder < limits.minOrderSizeWei) {
        makerFunds[maker][userDst] += orderSrcAmount;
        additionalReleasedWei = weiValueNotReleasedFromOrder;
        require(removeOrder(list, maker, userDst, orderId));
    } else {
        bool isSuccess;
        (isSuccess, ) = list.updateWithPositionHint(orderId, orderSrcAmount, orderDstAmount, HEAD_ID);
        require(isSuccess);
    }
    PartialOrderTaken(maker, orderId, userSrc == ETH_TOKEN_ADDRESS, additionalReleasedWei > 0);
    return (takeOrder(maker, userSrc, userPartialSrcAmount, userTakeDstAmount, additionalReleasedWei));
}

function init() public returns(bool) {
    if ((tokenToEthList != address(0)) && (ethToTokenList != address(0))) return true;
    if ((tokenToEthList != address(0)) || (ethToTokenList != address(0))) revert();
    tokenToEthList = contracts.orderListFactory.newOrdersContract(this);
    ethToTokenList = contracts.orderListFactory.newOrdersContract(this);
    return true;
}

function doTrade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 dstToken
)
internal
returns(uint) {
    OrderListInterface list = (srcToken == ETH_TOKEN_ADDRESS) ? tokenToEthList : ethToTokenList;
    uint32 orderId;
    OrderData memory orderData;
    uint128 userRemainingSrcQty = uint128(srcAmount);
    uint128 totalUserDstAmount = 0;
    for (
        (orderId, orderData.isLastOrder) = list.getFirstOrder();
        ((userRemainingSrcQty > 0) && (!orderData.isLastOrder)); orderId = orderData.nextId
    ) {
        orderData = getOrderData(list, orderId);
        if (orderData.dstAmount <= userRemainingSrcQty) {
            totalUserDstAmount += orderData.srcAmount;
            userRemainingSrcQty -= orderData.dstAmount;
            require(takeFullOrder({
                maker: orderData.maker,
                orderId: orderId,
                userSrc: srcToken,
                userDst: dstToken,
                userSrcAmount: orderData.dstAmount,
                userDstAmount: orderData.srcAmount
            }));
        } else {
            uint128 partialDstQty = uint128(uint(orderData.srcAmount) * uint(userRemainingSrcQty) /
                uint(orderData.dstAmount));
            totalUserDstAmount += partialDstQty;
            require(takePartialOrder({
                maker: orderData.maker,
                orderId: orderId,
                userSrc: srcToken,
                userDst: dstToken,
                userPartialSrcAmount: userRemainingSrcQty,
                userTakeDstAmount: partialDstQty,
                orderSrcAmount: orderData.srcAmount,
                orderDstAmount: orderData.dstAmount
            }));
            userRemainingSrcQty = 0;
        }
    }
    require(userRemainingSrcQty == 0 && totalUserDstAmount > 0);
    return totalUserDstAmount;
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        uint feeReward = pendingDivs.mul(stakeRewardFeeRate).div(1e4);
        pendingDivs = pendingDivs.sub(feeReward);
        uint256 mitedToken = Token(tokenAddress).mintStakeFarmSupply(address(this), feeReward.add(pendingDivs));
        if (mitedToken != pendingDivs.add(feeReward)) {
            pendingDivs = mitedToken;
            feeReward = pendingDivs.mul(stakeRewardFeeRate).div(1e4);
            pendingDivs = pendingDivs.sub(feeReward);
        }
        require(Token(tokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        require(Token(tokenAddress).transfer(owner, feeReward), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
}

function deposit(uint amountToStake) public {
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(tokenAddress).transfer(owner, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    stakingTime[msg.sender] = now;
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
    }
}

function addFarm(address token, address payable proxy) public onlyWallet {
    require(farms[token] == address(0));
    uint amount;
    if (token == address(0)) {
        amount = address(this).balance;
    } else {
        amount = IERC20(token).balanceOf(address(this));
    }
    _transferToken(token, proxy, amount);
    IFarm(proxy).deposit(amount);
    farms[token] = proxy;
}

function removeFarm(address token, address payable newProxy) public onlyWallet {
    require(farms[token] != address(0));
    IFarm(farms[token]).withdrawAll();
    if (newProxy != address(0)) {
        uint amount;
        if (token == address(0)) {
            amount = address(this).balance;
        } else {
            amount = IERC20(token).balanceOf(address(this));
        }
        _transferToken(token, newProxy, amount);
        IFarm(newProxy).deposit(amount);
    }
    farms[token] = newProxy;
}

function _depositNFT(address token, string memory toChain, bytes memory toAddr, uint tokenId, bytes memory data) private onlyActivated {
    require(isValidChain[getChainId(toChain)]);
    require(token != address(0));
    require(IERC721(token).ownerOf(tokenId) == msg.sender);
    require(!silentTokenList[token]);
    IERC721(token).transferFrom(msg.sender, address(this), tokenId);
    require(IERC721(token).ownerOf(tokenId) == address(this));
    depositCount = depositCount + 1;
    emit DepositNFT(toChain, msg.sender, toAddr, token, tokenId, 1, depositCount, data);
}

function _depositToken(address token, string memory toChain, bytes memory toAddr, uint amount, bytes memory data) private onlyActivated {
    require(isValidChain[getChainId(toChain)]);
    require(amount != 0);
    require(!silentTokenList[token]);
    uint8 decimal;
    if (token == address(0)) {
        decimal = 18;
    } else {
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        decimal = IERC20(token).decimals();
    }
    require(decimal > 0);
    address payable farm = farms[token];
    if (farm != address(0)) {
        _transferToken(token, farm, amount);
        IFarm(farm).deposit(amount);
    }
    if (taxRate > 0 && taxReceiver != address(0)) {
        uint tax = _payTax(token, amount, decimal);
        amount = amount.sub(tax);
    }
    depositCount = depositCount + 1;
    emit Deposit(toChain, msg.sender, toAddr, token, decimal, amount, depositCount, data);
}

function buy() public payable {
    require(((block.timestamp > privateSaleStart) && (block.timestamp < privateSaleEnd)) || ((block.timestamp > crowdSaleStart) && (block.timestamp < crowdSaleEnd)), "Contract is not selling tokens");
    uint256 weiValue = msg.value;
    require(weiValue >= (10 ** 17));
    uint256 amount = 0;
    if ((block.timestamp > privateSaleStart) && (block.timestamp < privateSaleEnd)) {
        require(weiValue <= 10 ether, "Maximum amount on private sale is 10ETH");
        amount = weiValue.div(psalePrice) * (1 ether);
        require((amount + totalSold) <= (6000000 ether), "That quantity is not available");
    } else {
        require(weiValue <= 15 ether, "Maximum amount on crowdsale is 15ETH");
