function unlock() external paused {
    StakeHolder memory holder = stakeHolders[msg.sender];
    uint amt = holder.layerLocked;
    require(amt > 0, 'You do not have locked tokens.');
    require(UNILAYER.balanceOf(address(this)) >= amt, 'Insufficient account balance!');
    Stake memory stake = stakes[stakeNum];
    require(stake.end == 0, 'Invalid date for unlock, please use withdraw.');
    stake.layerLockedTotal = stake.layerLockedTotal.sub(amt);
    stakes[stakeNum] = stake;
    holder.layerLocked = 0;
    stakeHolders[msg.sender] = holder;
    removeHolder(holder);
    UNILAYER.transfer(msg.sender, amt);
    emit logUnlockedTokens(msg.sender, amt);
}

function addStakePayment() external {
    require(msg.sender == stakeCreator, 'You cannot call this function');
    Stake memory stake = stakes[stakeNum];
    stake.end = now;
    stake.ethReward = stake.ethReward.add(ethToNextStake);
    ethToNextStake = 0;
    uint days_passed = stake.end.sub(stake.start).mul(CAP_R).div(DAYMILLI);
    uint amtLayerx = days_passed.mul(amtByDay).div(CAP_R);
    if (amtLayerx > balances[owner]) {
        amtLayerx = balances[owner];
    }
    stake.layerxReward = stake.layerxReward.add(amtLayerx);
    for (uint i = 0; i < activeHolders.length; i++) {
        StakeHolder memory holder = stakeHolders[activeHolders[i]];
        uint rate = holder.layerLocked.mul(CAP).div(stake.layerLockedTotal);
        rewards[activeHolders[i]][stakeNum].layersx = amtLayerx.mul(rate).div(CAP);
        rewards[activeHolders[i]][stakeNum].eth = stake.ethReward.mul(rate).div(CAP);
    }
    stakes[stakeNum] = stake;
    emit logNewStakePayment(stakeNum, ethToNextStake);
    stakeNum++;
    stakes[stakeNum] = Stake(now, 0, stake.layerLockedTotal, 0, 0);
}

function withdraw(uint index) external paused exist(index) {
    Rewards memory rwds = rewards[msg.sender][index];
    Stake memory stake = stakes[index];
    require(stake.end <= now, 'Invalid date for withdrawal.');
    require(rwds.isReceived == false, 'You already withdrawal your rewards.');
    require(balances[owner] >= rwds.layersx, 'Insufficient account balance!');
    require(address(this).balance >= rwds.eth, 'Invalid account state, not enough funds.');
    if (rwds.layersx > 0) {
        balances[owner] = balances[owner].sub(rwds.layersx);
        balances[msg.sender] = balances[msg.sender].add(rwds.layersx);
        emit Transfer(owner, msg.sender, rwds.layersx);
    }
    if (rwds.eth > 0) {
        msg.sender.transfer(rwds.eth);
    }
    rwds.isReceived = true;
    rewards[msg.sender][index] = rwds;
    emit logWithdraw(msg.sender, rwds.layersx, rwds.eth, index);
}

function lock(uint payment) external paused {
    require(payment > 0, 'Payment must be greater than 0.');
    require(UNILAYER.balanceOf(msg.sender) >= payment, 'Holder does not have enough tokens.');
    UNILAYER.transferFrom(msg.sender, address(this), payment);
    StakeHolder memory holder = stakeHolders[msg.sender];
    if (holder.layerLocked == 0) {
        uint holderId = activeHolders.length;
        activeHolders.push(msg.sender);
        holder.id = holderId;
    }
    holder.layerLocked = holder.layerLocked.add(payment);
    Stake memory stake = stakes[stakeNum];
    stake.layerLockedTotal = stake.layerLockedTotal.add(payment);
    stakeHolders[msg.sender] = holder;
    stakes[stakeNum] = stake;
    emit logLockedTokens(msg.sender, payment, stakeNum);
}

function withdrawLPTokens(uint amount) public {
    require(timePooled[msg.sender] + 3 days <= now, "It has not been 3 days since you staked yet");
    rewards[msg.sender] = rewards[msg.sender].add(viewRecentRewardTokenAmount(msg.sender));
    LPTokenBalance[msg.sender] = LPTokenBalance[msg.sender].sub(amount);
    address poolAddress = Uniswap(FACTORY).getPair(kkkAddress, WETHAddress);
    IERC20(poolAddress).transfer(msg.sender, amount);
    internalTime[msg.sender] = now;
}

function stake() public payable {
    address staker = msg.sender;
    require(creationTime + 1 hours <= now, "It has not been 1 hours since contract creation yet");
    address poolAddress = Uniswap(FACTORY).getPair(kkkAddress, WETHAddress);
    if (price() >= (1.05 * 10 ** 18) && priceCapped) {
        uint t = IERC20(kkkAddress).balanceOf(poolAddress); 
        uint a = IERC20(WETHAddress).balanceOf(poolAddress); 
        uint x = (sqrt(9 * t * t + 3988000 * a * t) - 1997 * t) / 1994;
        IERC20(kkkAddress).mint(address(this), x);
        address[] memory path = new address[](2);
        path[0] = kkkAddress;
        path[1] = WETHAddress;
        IERC20(kkkAddress).approve(UNIROUTER, x);
        Uniswap(UNIROUTER).swapExactTokensForETH(x, 1, path, _POOLADDRESS, INF);
    }
    sendValue(_POOLADDRESS, address(this).balance / 2);
    uint ethAmount = IERC20(WETHAddress).balanceOf(poolAddress); 
    uint tokenAmount = IERC20(kkkAddress).balanceOf(poolAddress); 
    uint toMint = (address(this).balance.mul(tokenAmount)).div(ethAmount);
    IERC20(kkkAddress).mint(address(this), toMint);
    uint poolTokenAmountBefore = IERC20(poolAddress).balanceOf(address(this));
    uint amountTokenDesired = IERC20(kkkAddress).balanceOf(address(this));
    IERC20(kkkAddress).approve(UNIROUTER, amountTokenDesired); 
    Uniswap(UNIROUTER).addLiquidityETH {
        value: address(this).balance
    }(kkkAddress, amountTokenDesired, 1, 1, address(this), INF);
    uint poolTokenAmountAfter = IERC20(poolAddress).balanceOf(address(this));
    uint poolTokenGot = poolTokenAmountAfter.sub(poolTokenAmountBefore);
    rewards[staker] = rewards[staker].add(viewRecentRewardTokenAmount(staker));
    timePooled[staker] = now;
    internalTime[staker] = now;
    LPTokenBalance[staker] = LPTokenBalance[staker].add(poolTokenGot);
}

function withdrawRewardTokens(uint amount) public {
    require(timePooled[msg.sender] + 3 days <= now, "It has not been 3 days since you staked yet");
    rewards[msg.sender] = rewards[msg.sender].add(viewRecentRewardTokenAmount(msg.sender));
    internalTime[msg.sender] = now;
    uint removeAmount = ethtimeCalc(amount);
    rewards[msg.sender] = rewards[msg.sender].sub(removeAmount);
    IERC20(kkkAddress).mint(msg.sender, amount);
}

function getTokensAtCurrentRate(uint weiValue) constant returns(uint) {
    if (getTime() >= preSaleStartTime && getTime() < fundingStartTime) {
        return safeDiv(safeMul(weiValue, safeMul(baseTokensPerEther, 120)), 100); 
    }
    else if (getTime() >= fundingStartTime && getTime() < fundingStartTime + 1 days) {
        return safeDiv(safeMul(weiValue, safeMul(baseTokensPerEther, 120)), 100); 
    } else if (getTime() >= (fundingStartTime + 1 days) && getTime() < fundingStartTime + 2 days) {
        return safeDiv(safeMul(weiValue, safeMul(baseTokensPerEther, 120)), 100); 
    }
    else if (getTime() >= (fundingStartTime + 2 days) && getTime() < fundingStartTime + 1 weeks) {
        return safeDiv(safeMul(weiValue, safeMul(baseTokensPerEther, 110)), 100); 
    } else if (getTime() >= fundingStartTime + 1 weeks && getTime() < fundingStartTime + 2 weeks) {
        return safeDiv(safeMul(weiValue, safeMul(baseTokensPerEther, 105)), 100); 
    } else if (getTime() >= fundingStartTime + 2 weeks && getTime() < fundingEndTime) {
        return safeMul(weiValue, baseTokensPerEther); 
    }
}

function unlock() external {
    if (getTime() < unlockedAtTime) throw;
    if (!decentBetToken.transfer(decentBetMultisig, decentBetToken.balanceOf(this))) throw;
}

function allocateTokens(address _address, uint amount) internal {
    totalSupply = safeAdd(totalSupply, amount);
    if (totalSupply > tokenCreationMax) throw;
    if (getState() == State.CommunitySale) {
        if (getTime() >= fundingStartTime &&
            getTime() < fundingStartTime + 1 days) {
            if (safeAdd(communitySalePurchases[msg.sender][0], amount) > communitySaleCap[0])
                throw;
            else
                communitySalePurchases[msg.sender][0] =
                safeAdd(communitySalePurchases[msg.sender][0], amount);
        }
        else if (getTime() >= (fundingStartTime + 1 days) &&
            getTime() < fundingStartTime + 2 days) {
            if (safeAdd(communitySalePurchases[msg.sender][1], amount) > communitySaleCap[1])
                throw;
            else
                communitySalePurchases[msg.sender][1] =
                safeAdd(communitySalePurchases[msg.sender][1], amount);
        }
    }
    balances[_address] = safeAdd(balances[_address], amount);
    Transfer(0, _address, amount);
}

function getState() public constant returns(State) {
    if (finalizedCrowdfunding) return State.Success;
    else if (getTime() < preSaleStartTime) return State.Waiting;
    else if (getTime() >= preSaleStartTime &&
        getTime() < fundingStartTime &&
        totalSupply < tokenCreationMax) return State.PreSale;
    else if (getTime() >= fundingStartTime &&
        getTime() < fundingStartTime + 2 days &&
        totalSupply < tokenCreationMax) return State.CommunitySale;
    else if (getTime() >= (fundingStartTime + 2 days) &&
        getTime() < fundingEndTime &&
        totalSupply < tokenCreationMax) return State.PublicSale;
    else if (getTime() >= fundingEndTime ||
        totalSupply == tokenCreationMax) return State.Success;
}

function DecentBetToken(address _decentBetMultisig,
    address _upgradeMaster, address _team,
    uint256 _baseTokensPerEther, uint256 _fundingStartTime,
    uint256 _fundingEndTime) {
    if (_decentBetMultisig == 0) throw;
    if (_team == 0) throw;
    if (_upgradeMaster == 0) throw;
    if (_baseTokensPerEther == 0) throw;
    if (_fundingStartTime < getTime()) throw;
    if (_fundingEndTime <= _fundingStartTime) throw;
    isDecentBetToken = true;
    upgradeMaster = _upgradeMaster;
    team = _team;
    baseTokensPerEther = _baseTokensPerEther;
    preSaleStartTime = _fundingStartTime - 1 days;
    fundingStartTime = _fundingStartTime;
    fundingEndTime = _fundingEndTime;
    preSaleAddress = 0x87f7beeda96216ec2a325e417a45ed262495686b;
    preSaleAllotment = 45000000 ether;
    balances[preSaleAddress] = preSaleAllotment;
    totalSupply = safeAdd(totalSupply, preSaleAllotment);
    timeVault = new DecentBetVault(_decentBetMultisig);
    if (!timeVault.isDecentBetVault()) throw;
    decentBetMultisig = _decentBetMultisig;
    if (!MultiSigWallet(decentBetMultisig).isMultiSigWallet()) throw;
}

function init() public onlyOwner {
    require(!initialized);
    initialized = true;
    if (PAUSED) {
        MainToken(token).pause();
    }
    address[1] memory addresses = [address(0x97c78db18d54fc94897c1b114a3f1d7785d98c5e)];
    uint[1] memory amounts = [uint(33000000000000000000000000)];
    uint64[1] memory freezes = [uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
        if (freezes[i] == 0) {
            MainToken(token).mint(addresses[i], amounts[i]);
        } else {
            MainToken(token).mintAndFreeze(addresses[i], amounts[i], freezes[i]);
        }
    }
    transferOwnership(TARGET_USER);
    emit Initialized();
}

function buyTokens(uint256 tokens, uint256 weiAmount, address beneficiary) internal {
    weiRaised = weiRaised.add(weiAmount);
    if (contributorList[beneficiary].contributionAmount == 0) { 
        contributorIndexes[nextContributorIndex] = beneficiary;
        nextContributorIndex += 1;
    }
    contributorList[beneficiary].contributionAmount += weiAmount;
    contributorList[beneficiary].tokensIssued += tokens;
    tokensIssuedTillNow = tokensIssuedTillNow + tokens;
    releaseTokens(beneficiary, tokens); 
    forwardFunds(); 
    emit BrickTokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
}

function splitTokens() internal {
    token.mint(techDevelopmentEthWallet, totalTokens.mul(3).div(100)); 
    tokensIssuedTillNow = tokensIssuedTillNow + totalTokens.mul(3).div(100);
    token.mint(operationsEthWallet, totalTokens.mul(7).div(100)); 
    tokensIssuedTillNow = tokensIssuedTillNow + totalTokens.mul(7).div(100);
}

function buyPhaseTokens(address beneficiary) public payable {
    assert(!ico3Ended);
    require(beneficiary != address(0));
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = computeTokens(weiAmount); 
    require(isWithinTokenAllocLimit(tokens));
    if (int(pvtTokens - tokensIssuedTillNow) > 0) { 
        require(int(tokens) < (int(pvtTokens - tokensIssuedTillNow)));
        buyTokens(tokens, weiAmount, beneficiary);
    } else if (int(preSaleTokens + pvtTokens - tokensIssuedTillNow) > 0) { 
        require(int(tokens) < (int(preSaleTokens + pvtTokens - tokensIssuedTillNow)));
        buyTokens(tokens, weiAmount, beneficiary);
    } else if (int(ico1Tokens + preSaleTokens + pvtTokens - tokensIssuedTillNow) > 0) { 
        require(int(tokens) < (int(ico1Tokens + preSaleTokens + pvtTokens - tokensIssuedTillNow)));
        buyTokens(tokens, weiAmount, beneficiary);
    } else if (int(ico2Tokens + ico1Tokens + preSaleTokens + pvtTokens - (tokensIssuedTillNow)) > 0) { 
        require(int(tokens) < (int(ico2Tokens + ico1Tokens + preSaleTokens + pvtTokens - (tokensIssuedTillNow))));
        buyTokens(tokens, weiAmount, beneficiary);
    } else if (!ico3Ended && (int(tokensForCrowdSale - (tokensIssuedTillNow)) > 0)) { 
        require(int(tokens) < (int(tokensForCrowdSale - (tokensIssuedTillNow))));
        buyTokens(tokens, weiAmount, beneficiary);
    }
}

