    daiToken.transfer(to, amount);
}

function settlePut(uint expiration, uint strike, address writer) public {
    bytes32 series = keccak256(expiration, strike);
    require(
        (msg.sender == writer || isAuthorized(msg.sender, msg.sig)) &&
        now > expiration &&
        putsSold[series][writer] > 0
    );
    if (putsAssigned[series] < putsExercised[series]) {
        uint maximum = putsSold[series][writer];
        uint needed = putsExercised[series] - putsAssigned[series];
        uint assignment = maximum > needed ? needed : maximum;
        totalDai[writer] -= assignment * strike / 1 ether;
        putsSold[series][writer] -= assignment;
        putsAssigned[series] += assignment;
        _addEth(assignment, writer);
        emit AssignPut(writer, assignment, expiration, strike);
    }
    uint yield = putsSold[series][writer] * strike / 1 ether;
    _collectFee(writer, settlementFee);
    dai[writer] += yield;
    putsSold[series][writer] = 0;
    emit SettlePut(writer, expiration, strike);
}

function depositDaiFor(uint amount, address account) public {
    require(
        account != 0x0 &&
        daiToken.transferFrom(msg.sender, this, amount)
    );
    _addDai(amount, account);
    emit DepositDai(account, amount);
}

function settleCall(uint expiration, uint strike, address writer) public {
    bytes32 series = keccak256(expiration, strike);
    require(
        (msg.sender == writer || isAuthorized(msg.sender, msg.sig)) &&
        now > expiration &&
        callsSold[series][writer] > 0
    );
    if (callsAssigned[series] < callsExercised[series]) {
        uint maximum = callsSold[series][writer];
        uint needed = callsExercised[series] - callsAssigned[series];
        uint assignment = needed > maximum ? maximum : needed;
        totalEth[writer] -= assignment;
        callsAssigned[series] += assignment;
        callsSold[series][writer] -= assignment;
        uint value = strike * assignment / 1 ether;
        _addDai(value, writer);
        emit AssignCall(msg.sender, assignment, expiration, strike);
    }
    _collectFee(writer, settlementFee);
    eth[writer] += callsSold[series][writer];
    callsSold[series][writer] = 0;
    emit SettleCall(writer, expiration, strike);
}

function depositDai(uint amount) public {
    require(daiToken.transferFrom(msg.sender, this, amount));
    _addDai(amount, msg.sender);
    emit DepositDai(msg.sender, amount);
}

function exerciseCall(
    uint amount,
    uint expiration,
    uint strike
) public {
    uint cost = amount * strike / 1 ether;
    bytes32 series = keccak256(expiration, strike);
    require(
        now < expiration &&
        amount % 1 finney == 0 &&
        callsOwned[series][msg.sender] >= amount &&
        amount > 0
    );
    callsOwned[series][msg.sender] -= amount;
    callsExercised[series] += amount;
    _collectFee(msg.sender, exerciseFee);
    _subDai(cost, msg.sender);
    _addEth(amount, msg.sender);
    emit ExerciseCall(msg.sender, amount, expiration, strike);
}

function _validateOrder(uint amount, uint expiration, bytes32 h, address maker, uint price, uint validUntil, uint size, uint strike) internal {
    require(
        strike % 1 ether == 0 &&
        amount % 1 finney == 0 &&
        price % 1 finney == 0 &&
        expiration % 86400 == 0 &&
        cancelled[maker][h] == false &&
        amount <= size - filled[maker][h] &&
        now < validUntil &&
        now < expiration &&
        strike > 10 ether &&
        price < 1200000 ether &&
        size < 1200000 ether &&
        strike < 1200000 ether &&
        price >= 1 finney
    );
    filled[maker][h] += amount;
    emit TakeOrder(msg.sender, maker, amount, h);
}

function exercisePut(
    uint amount,
    uint expiration,
    uint strike
) public {
    uint yield = amount * strike / 1 ether;
    bytes32 series = keccak256(expiration, strike);
    require(
        now < expiration &&
        amount % 1 finney == 0 &&
        putsOwned[series][msg.sender] >= amount &&
        amount > 0
    );
    putsOwned[series][msg.sender] -= amount;
    putsExercised[series] += amount;
    _subEth(amount, msg.sender);
    _addDai(yield, msg.sender);
    _collectFee(msg.sender, exerciseFee);
    emit ExercisePut(msg.sender, amount, expiration, strike);
}

function proposeAction(
    address actionTo,
    uint256 actionValue,
    bytes calldata actionData,
    bytes32 details
) external returns(uint256) {
    require(actionTo != address(0), "invalid actionTo");
    uint256 proposalId = moloch.submitProposal(
        address(this),
        0,
        0,
        0,
        molochDepositToken,
        0,
        molochDepositToken,
        details
    );
    Action memory action = Action({
        value: actionValue,
        to: actionTo,
        proposer: msg.sender,
        executed: false,
        data: actionData
    });
    actions[proposalId] = action;
    emit ProposeAction(proposalId, msg.sender);
    return proposalId;
}

function unfarm(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > PossibleUnstakeTime, "You have not staked for a while yet, kindly wait a bit more");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(liquiditytoken1).transfer(admin, fee), "Could not transfer withdraw fee.");
    require(Token(liquiditytoken1).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function withdrawReward(address holder) external {
    require(_status == RE_NOT_ENTERED || (_status == RE_FROZEN && msg.sender == _owner));
    _status = RE_ENTERED;
    _checkRewardBalance(holder);
    uint256 balance = _rewardBalance[holder];
    require(balance > 0, "No reward balance");
    _rewardBalance[holder] = 0;
    require(_reservedRewardBalance - balance > 0, "Reserved balance underflow");
    _reservedRewardBalance -= balance;
    IERC20(_rewardToken).transfer(holder, balance);
    _status = RE_NOT_ENTERED;
}

function convertToken(address[] calldata path, uint256 deadline) external {
    require(_status == RE_NOT_ENTERED);
    _status = RE_ENTERED;
    require(msg.sender == _owner, "Not owner");
    IERC20 tokenContract = IERC20(path[0]);
    uint256 amount = tokenContract.balanceOf(address(this));
    require(amount > 0, "No balance for token");
    require(path[path.length - 1] == _rewardToken, "Last must be reward token");
    tokenContract.approve(_uniswapRouterAddress, amount);
    IUniswapV2Router02(_uniswapRouterAddress).swapExactTokensForTokens(amount, 1, path, address(this), deadline);
    _status = RE_NOT_ENTERED;
}

function notifyGoaldCreated(address creator, address goaldAddress) external {
    require(_status == RE_NOT_ENTERED);
    _status = RE_ENTERED;
    require(_allowedDeployersMap[msg.sender], "Not allowed deployer");
    IGoaldToken goaldToken = IGoaldToken(_goaldToken);
    require(goaldToken.getLatestDAO() == address(this), "Not latest DAO");
    require(_ready == READY, "Not ready");
    if (_governanceStage == STAGE_ALL_GOVERNANCE_ISSUED) {
        goaldToken.goaldDeployed(creator, goaldAddress);
        _deployedGoalds.push(goaldAddress);
        _goaldOwners.push(creator);
        return;
    }
    bool increaseHolders;
    if (goaldToken.balanceOf(creator) < REWARD_THRESHOLD) {
        increaseHolders = true;
    }
    uint256 amount = goaldToken.goaldDeployed(creator, goaldAddress);
    if (amount > 0) {
        _checkRewardBalance(creator);
        if (increaseHolders) {
            _rewardHolders++;
        }
    }
    else if (_governanceStage == STAGE_DAO_INITIATED) {
        _governanceStage = STAGE_ALL_GOVERNANCE_ISSUED;
    }
    _deployedGoalds.push(goaldAddress);
    _goaldOwners.push(creator);
    _status = RE_NOT_ENTERED;
}

function convertTokens(address[] calldata tokenAddresses, bool isIndirect, uint256 deadline) external {
    require(_status == RE_NOT_ENTERED);
    _status = RE_ENTERED;
    require(msg.sender == _owner, "Not owner");
    address[] memory path;
    if (isIndirect) {
        path = new address[](3);
        path[1] = _intermediaryToken;
        path[2] = _rewardToken;
    } else {
        path = new address[](2);
        path[1] = _rewardToken;
    }
    IUniswapV2Router02 uniswap = IUniswapV2Router02(_uniswapRouterAddress);
    address tokenAddress;
    IERC20 tokenContract;
    uint256 amount;
    uint256 count = tokenAddresses.length;
    for (uint256 i; i < count; i++) {
        tokenAddress = tokenAddresses[i];
        require(tokenAddress != address(0), "Can't be zero address");
        require(tokenAddress != address(this), "Can't be this address");
        require(tokenAddress != _rewardToken, "Can't be target address");
        tokenContract = IERC20(tokenAddress);
        amount = tokenContract.balanceOf(address(this));
        if (amount == 0) {
            continue;
        }
        tokenContract.approve(_uniswapRouterAddress, amount);
        path[0] = tokenAddress;
        uniswap.swapExactTokensForTokens(amount, 1, path, address(this), deadline);
    }
    _status = RE_NOT_ENTERED;
}

function _stake(address from, uint256 amount) private returns(bool) {
    if (!_payMe(from, amount)) {
        return false;
    }
    hasStaked[from] = true;
    bool stakerEligibility;
    if (amount >= eligibilityAmount) {
        stakerEligibility = true;
    }
    deposits[from] = Deposits(
        amount,
        block.timestamp,
        block.timestamp.add((lockDuration.mul(86400))), 
        index,
        false,
        stakerEligibility
    );
    emit Staked(tokenAddress, from, amount);
    stakedBalance = stakedBalance.add(amount);
    stakedTotal = stakedTotal.add(amount);
    return true;
}

function withdraw() external returns(bool) {
    address from = msg.sender;
    require(hasStaked[from], "No stakes found for user");
    require(
        block.timestamp >= deposits[from].endTime,
        "Requesting before lock time"
    );
    require(!deposits[from].paid, "Already paid out");
    return (_withdraw(from));
}

function _calculate(address from) private view returns(uint256) {
    if (!hasStaked[from]) return 0;
    (
        uint256 amount,
        uint256 depositTime,
        uint256 endTime,
        uint64 userIndex
    ) =
    (
        deposits[from].depositAmount,
        deposits[from].depositTime,
        deposits[from].endTime,
        deposits[from].userIndex
    );
    uint256 time;
    uint256 interest;
    uint256 _lockduration = endTime.sub(depositTime);
    for (uint64 i = userIndex; i < index; i++) {
        if (endTime < rates[i + 1].timeStamp) {
            break;
        } else {
            time = rates[i + 1].timeStamp.sub(depositTime);
            interest = amount.mul(rates[i].newInterestRate).mul(time).div(
                _lockduration.mul(10000)
            ); 
            amount += interest;
            depositTime = rates[i + 1].timeStamp;
            userIndex++;
        }
    }
    if (depositTime < endTime) {
        time = endTime.sub(depositTime);
        interest = time
            .mul(amount)
            .mul(rates[userIndex].newInterestRate)
            .div(_lockduration.mul(10000)); 
        amount += interest;
    }
    return (amount);
}

function emergencyWithdraw() external returns(bool) {
    address from = msg.sender;
    require(hasStaked[from], "No stakes found for user");
    require(
        block.timestamp >= deposits[from].endTime,
        "Requesting before lock time"
    );
    require(!deposits[from].paid, "Already paid out");
    return (_emergencyWithdraw(from));
}

function buy1(uint256 _tokenId) payable public {
    require(price1Of(_tokenId) > 0);
    require(owner1Of(_tokenId) != address(0));
    require(msg.value >= price1Of(_tokenId));
    require(owner1Of(_tokenId) != msg.sender);
    require(!isContract(msg.sender));
    require(msg.sender != address(0));
    require(now >= free1OfToken[_tokenId]);
    require(now <= free2OfToken[_tokenId]);
    address oldOwner = owner1Of(_tokenId);
    address newOwner = msg.sender;
    uint256 price = price1Of(_tokenId);
    uint256 excess = msg.value.sub(price);
    price1OfToken[_tokenId] = nextPrice1Of(_tokenId);
    uint256 devCut = calculateDevCut(price);
    oldOwner.transfer(price.sub(devCut));
    if (excess > 0) {
        newOwner.transfer(excess);
    }
    owner1OfToken[_tokenId] = newOwner;
}

function buy2(uint256 _tokenId) payable public {
    require(price2Of(_tokenId) > 0);
    require(owner2Of(_tokenId) != address(0));
    require(msg.value >= price2Of(_tokenId));
    require(owner2Of(_tokenId) != msg.sender);
    require(!isContract(msg.sender));
    require(msg.sender != address(0));
    require(now >= free1OfToken[_tokenId]);
    require(now <= free2OfToken[_tokenId]);
    address oldOwner = owner2Of(_tokenId);
    address newOwner = msg.sender;
    uint256 price = price2Of(_tokenId);
    uint256 excess = msg.value.sub(price);
    price2OfToken[_tokenId] = nextPrice2Of(_tokenId);
    uint256 devCut = calculateDevCut(price);
    oldOwner.transfer(price.sub(devCut));
    if (excess > 0) {
        newOwner.transfer(excess);
    }
    owner2OfToken[_tokenId] = newOwner;
}

function cancel2(uint256 _tokenId) public {
    require(msg.sender == p1OfToken[_tokenId]);
    require(bet1deltaOfToken[_tokenId] != 0);
    msg.sender.transfer(bet1deltaOfToken[_tokenId]);
    bet1deltaOfToken[_tokenId] = 0;
}

function judge(uint256 _tokenId, bool _isP1Win) onlyWitness(_tokenId) public {
    require(price2OfToken[_tokenId] != 0);
    require(now > free2OfToken[_tokenId]);
    uint reward = bet1OfToken[_tokenId] + bet2OfToken[_tokenId];
    reward -= calculateDevCut(reward);
    if (_isP1Win == true) {
        p1OfToken[_tokenId].transfer(reward.mul(bet1OfToken[_tokenId]).div(bet1OfToken[_tokenId] + price1OfToken[_tokenId]));
        owner1OfToken[_tokenId].transfer(reward.mul(price1OfToken[_tokenId]).div(bet1OfToken[_tokenId] + price1OfToken[_tokenId]));
    } else {
        p2OfToken[_tokenId].transfer(reward.mul(bet2OfToken[_tokenId]).div(bet2OfToken[_tokenId] + price2OfToken[_tokenId]));
        owner2OfToken[_tokenId].transfer(reward.mul(price2OfToken[_tokenId]).div(bet2OfToken[_tokenId] + price2OfToken[_tokenId]));
    }
}

