function usdToEth(uint _usdAmount) public override view returns(uint) {
    IAggregator agg = IAggregator(usdAggregators[WETH]);
    (, int256 answer, , uint256 updatedAt, ) = agg.latestRoundData();
    require(updatedAt > block.timestamp - 6 hours, "Unit Protocol: STALE_CHAINLINK_PRICE");
    return _usdAmount.mul(10 ** agg.decimals()).div(uint(answer));
}

function _assetToUsd(address asset, uint amount) internal view returns(uint) {
    IAggregator agg = IAggregator(usdAggregators[asset]);
    (, int256 answer, , uint256 updatedAt, ) = agg.latestRoundData();
    require(updatedAt > block.timestamp - 24 hours, "Unit Protocol: STALE_CHAINLINK_PRICE");
    require(answer >= 0, "Unit Protocol: NEGATIVE_CHAINLINK_PRICE");
    int decimals = 18 - int(IToken(asset).decimals()) - int(agg.decimals());
    if (decimals < 0) {
        return amount.mul(uint(answer)).mul(Q112).div(10 ** uint(-decimals));
    } else {
        return amount.mul(uint(answer)).mul(Q112).mul(10 ** uint(decimals));
    }
}

function assetToEth(address asset, uint amount) public view override returns(uint) {
    if (amount == 0) {
        return 0;
    }
    if (asset == WETH) {
        return amount.mul(Q112);
    }
    IAggregator agg = IAggregator(ethAggregators[asset]);
    if (address(agg) == address(0)) {
        require(usdAggregators[asset] != address(0), "Unit Protocol: AGGREGATOR_DOES_NOT_EXIST");
        return usdToEth(_assetToUsd(asset, amount));
    }
    (, int256 answer, , uint256 updatedAt, ) = agg.latestRoundData();
    require(updatedAt > block.timestamp - 24 hours, "Unit Protocol: STALE_CHAINLINK_PRICE");
    require(answer >= 0, "Unit Protocol: NEGATIVE_CHAINLINK_PRICE");
    int decimals = 18 - int(IToken(asset).decimals()) - int(agg.decimals());
    if (decimals < 0) {
        return amount.mul(uint(answer)).mul(Q112).div(10 ** uint(-decimals));
    } else {
        return amount.mul(uint(answer)).mul(Q112).mul(10 ** uint(decimals));
    }
}

function ethToUsd(uint ethAmount) public override view returns(uint) {
    IAggregator agg = IAggregator(usdAggregators[WETH]);
    (, int256 answer, , uint256 updatedAt, ) = agg.latestRoundData();
    require(updatedAt > block.timestamp - 6 hours, "Unit Protocol: STALE_CHAINLINK_PRICE");
    return ethAmount.mul(uint(answer)).div(10 ** agg.decimals());
}

function _addTimeLock(address account, uint amount, uint expiresAt) internal {
    require(amount > 0, "Time Lock: lock amount must be greater than 0");
    require(expiresAt > block.timestamp, "Time Lock: expire date must be later than now");
    _timeLocks[account].push(TimeLock(amount, expiresAt));
}

function getTimeLockedAmount(address account) public view returns(uint) {
    uint timeLockedAmount = 0;
    uint len = _timeLocks[account].length;
    for (uint i = 0; i < len; i++) {
        if (block.timestamp < _timeLocks[account][i].expiresAt) {
            timeLockedAmount = timeLockedAmount.add(_timeLocks[account][i].amount);
        }
    }
    return timeLockedAmount;
}

function _determineRewardParams(address payable userAddr) internal returns(bool) {
    uint256 thisBlockNum = _blockContext();
    IManagerDataStorage _dataStorage = dataStorageInstance;
    uint256 delta = thisBlockNum - _dataStorage.getRewardParamUpdated();
    _dataStorage.setRewardParamUpdated(thisBlockNum);
    if (delta == 0) {
        return false;
    }
    uint256 globalRewardPerBlock = _dataStorage.getGlobalRewardPerBlock();
    uint256 globalRewardDecrement = _dataStorage.getGlobalRewardDecrement();
    uint256 globalRewardTotalAmount = _dataStorage.getGlobalRewardTotalAmount();
    uint256 remainingPeriod = globalRewardPerBlock.unifiedDiv(globalRewardDecrement);
    if (remainingPeriod >= delta.mul(SafeMath.unifiedPoint)) {
        remainingPeriod = remainingPeriod.sub(delta.mul(SafeMath.unifiedPoint));
    } else {
        return _epilogueOfDetermineRewardParams(_dataStorage, userAddr, delta, 0, globalRewardDecrement, 0);
    }
    if (globalRewardTotalAmount >= globalRewardPerBlock.mul(delta)) {
        globalRewardTotalAmount = globalRewardTotalAmount - globalRewardPerBlock.mul(delta);
    } else {
        return _epilogueOfDetermineRewardParams(_dataStorage, userAddr, delta, 0, globalRewardDecrement, 0);
    }
    globalRewardPerBlock = globalRewardTotalAmount.mul(2).unifiedDiv(remainingPeriod.add(SafeMath.unifiedPoint));
    return _epilogueOfDetermineRewardParams(_dataStorage, userAddr, delta, globalRewardPerBlock, globalRewardDecrement, globalRewardTotalAmount);
}

function interestUpdateReward() external returns(bool) {
    uint256 thisBlock = _blockContext();
    uint256 interestRewardUpdated = dataStorageInstance.getInterestRewardUpdated();
    uint256 delta = thisBlock - interestRewardUpdated;
    if (delta == 0) {
        return false;
    }
    dataStorageInstance.setInterestRewardUpdated(thisBlock);
    for (uint256 handlerID; handlerID < tokenHandlerLength; handlerID++) {
        IProxy tokenHandler = IProxy(dataStorageInstance.getTokenHandlerAddr(handlerID));
        bytes memory data;
        (, data) = tokenHandler.handlerProxy(
            abi.encodeWithSelector(
                IMarketHandler
                .checkFirstAction.selector
            )
        );
    }
    return _rewardTransfer(msg.sender, delta.mul(dataStorageInstance.getInterestUpdateRewardPerblock()));
}

function _rewardTransfer(address payable userAddr, uint256 _amount) internal returns(bool) {
    IERC20 _rewardERC20 = rewardErc20Instance;
    if (address(_rewardERC20) != address(0x0)) {
        uint256 beforeBalance = _rewardERC20.balanceOf(userAddr);
        _rewardERC20.transfer(userAddr, _amount);
        require(_amount == _rewardERC20.balanceOf(userAddr).sub(beforeBalance), REWARD_TRANSFER);
        return true;
    }
}

function upgradeCardShield(uint256 _cardId) public {
    require(cardShieldUpgradeLevel[_cardId].isLessThan(maxCardUpgradeLevel));
    uint256 costOfUpgrade = 2 ** (cardShieldUpgradeLevel[_cardId] + 1);
    MythereumERC20Token mythexContract = MythereumERC20Token(mythexTokenAddress);
    require(mythexContract.balanceOf(msg.sender).isAtLeast(costOfUpgrade));
    burnMythexTokens(msg.sender, costOfUpgrade);
    cardShieldUpgradeLevel[_cardId]++;
    MythereumCardToken cardToken = MythereumCardToken(cardTokenAddress);
    require(cardToken.improveCard(_cardId, 0, cardShieldUpgradeLevel[_cardId]));
    CardShieldUpgraded(_cardId, cardShieldUpgradeLevel[_cardId], costOfUpgrade);
}

