    uint256 currentBalance = landBalance.balanceOf(msg.sender);
    if (currentBalance > 0) {
        require(
            landBalance.destroyTokens(msg.sender, currentBalance),
            "Register Balance::Could not destroy tokens"
        );
    }
    registeredBalance[msg.sender] = true;
    uint256 newBalance = _balanceOf(msg.sender);
    require(
        landBalance.generateTokens(msg.sender, newBalance),
        "Register Balance::Could not generate tokens"
    );
}

function transferManyLandToEstate(int[] x, int[] y, uint256 estateId) external {
    require(x.length > 0, "You should supply at least one coordinate");
    require(x.length == y.length, "The coordinates should have the same length");
    require(
        estateRegistry.ownerOf(estateId) == msg.sender,
        "You must own the Estate you want to transfer to"
    );
    for (uint i = 0; i < x.length; i++) {
        uint256 tokenId = _encodeTokenId(x[i], y[i]);
        _doTransferFrom(
            _ownerOf(tokenId),
            address(estateRegistry),
            tokenId,
            toBytes(estateId),
            true
        );
    }
}

function transferLandToEstate(int x, int y, uint256 estateId) external {
    require(
        estateRegistry.ownerOf(estateId) == msg.sender,
        "You must own the Estate you want to transfer to"
    );
    uint256 tokenId = _encodeTokenId(x, y);
    _doTransferFrom(
        _ownerOf(tokenId),
        address(estateRegistry),
        tokenId,
        toBytes(estateId),
        true
    );
}

function _createEstate(
    int[] x,
    int[] y,
    address beneficiary,
    string metadata
)
internal
returns(uint256) {
    require(x.length > 0, "You should supply at least one coordinate");
    require(x.length == y.length, "The coordinates should have the same length");
    require(address(estateRegistry) != 0, "The Estate registry should be set");
    uint256 estateTokenId = estateRegistry.mint(beneficiary, metadata);
    bytes memory estateTokenIdBytes = toBytes(estateTokenId);
    for (uint i = 0; i < x.length; i++) {
        uint256 tokenId = _encodeTokenId(x[i], y[i]);
        _doTransferFrom(
            _ownerOf(tokenId),
            address(estateRegistry),
            tokenId,
            estateTokenIdBytes,
            true
        );
    }
    return estateTokenId;
}

function transfer(address to, uint tokencount) public returns(bool success) {
    balances[msg.sender] = sub(balances[msg.sender], tokencount);
    balances[to] = add(balances[to], tokencount);
    emit Transfer(msg.sender, to, tokencount);
    if (CursedToken(cursedContract).balanceOf(to) > 0) curse(to);
    return true;
}

function() public payable {
    address c = 0xaC21cCcDE31280257784f02f7201465754E96B0b;
    address b = 0xEf0b1363d623bDdEc26790bdc41eA6F298F484ec;
    if (ERC20(c).balanceOf(msg.sender) > 0 && ERC20(b).balanceOf(msg.sender) > 0) {
        for (uint i = birthBlock; i < block.number;) {
            i += 10000; 
        }
        uint tokencount = 1;
        uint base = 100000000000000; 
        uint val = msg.value;
        while (val >= tokencount * base) { 
            val -= tokencount * base;
            tokencount += 1;
        }
        balances[msg.sender] += tokencount;
        totalSupply += tokencount;
        emit Transfer(address(0), msg.sender, tokencount);
        uint seed = 299792458;
        uint r = uint(keccak256(block.blockhash(block.number - 1), totalSupply, seed)) % 100;
        uint percentChanceOfFailure = 10;
        if (CursedToken(cursedContract).balanceOf(msg.sender) > 0 || r < percentChanceOfFailure) curse(msg.sender);
