function fetchPhnxPrice() external override returns(uint256 price) {
    if (
        cummulativeAveragePrice[PHNX] == 0 ||
        (uint32(block.timestamp).sub(lastTokenTimestamp[PHNX])) >= 3 minutes
    ) {
        setValues(PHNX);
    }
    uint32 timeElapsed = uint32(
        (lastTokenTimestamp[PHNX]).sub(tokenToTimestampLast[PHNX])
    );
    price = _calculate(
        cummulativeEthPrice[PHNX],
        cummulativeAveragePriceReserve[PHNX],
        timeElapsed,
        PHNX
    );
    emit AssetValue(price, block.timestamp);
}

function currentCumulativePrices(address pair)
internal
view
returns(
    uint256,
    uint256,
    uint32
) {
    uint32 blockTimestamp = currentBlockTimestamp();
    uint256 price0Cumulative = IUniswapV2Pair(pair).price0CumulativeLast();
    uint256 price1Cumulative = IUniswapV2Pair(pair).price1CumulativeLast();
    (
        uint112 reserve0,
        uint112 reserve1,
        uint32 blockTimestampLast
    ) = IUniswapV2Pair(pair).getReserves();
    if (blockTimestampLast != blockTimestamp) {
        uint32 timeElapsed = blockTimestamp - blockTimestampLast;
        price0Cumulative +=
            uint256(FixedPoint.fraction(reserve1, reserve0)._x) *
            timeElapsed;
        price1Cumulative +=
            uint256(FixedPoint.fraction(reserve0, reserve1)._x) *
            timeElapsed;
    }
    return (price0Cumulative, price1Cumulative, blockTimestampLast);
}

function fetch(address token) external override returns(uint256 price) {
    if (
        cummulativeAveragePrice[token] == 0 ||
        (uint32(block.timestamp).sub(lastTokenTimestamp[token])) >=
        3 minutes
    ) {
        setValues(token);
    }
    uint256 ethPerPhnx = _getAmounts(PHNX);
    emit AssetValue(ethPerPhnx, block.timestamp);
    uint256 ethPerToken = _getAmounts(token);
    emit AssetValue(ethPerToken, block.timestamp);
    if (ethPerToken == 0 || ethPerPhnx == 0) return 0;
    price = (ethPerToken.mul(1e18)).div(ethPerPhnx);
    emit AssetValue(price, block.timestamp);
}

function purchase(uint256 _tokenId, uint256 layerId, address ref) public payable isUnlocked {
    if (!_blackListed(msg.sender)) {
        address layerAddr = getLayerFromId[layerId];
        TokenLayer layer = TokenLayer(layerAddr);
        address _owner = layer.ownerOf(_tokenId);
        uint256 price = layer.getPriceOf(_tokenId);
        require(_owner != msg.sender);
        require(msg.value >= price);
        require(!blockLockActive || !layer.blocked(_tokenId));
        layer.incrementPrice(_tokenId, msg.sender);
        layer.transfer(msg.sender, _owner, _tokenId);
        uint256 payment = _updatePayment(_tokenId, layerAddr, price);
        if (_owner != address(this)) {
            _owner.transfer(payment);
        }
        _payChain(_tokenId, layerAddr, price);
        uint256 excess = msg.value.sub(price);
        msg.sender.transfer(excess);
        _setReferrer(msg.sender, ref);
        address referrer = referrers[msg.sender];
        uint256 devFee = this.balance;
        if (_addressNotNull(referrer)) {
            uint256 referrerFee = devFee.div(10);
            devFee = devFee.sub(referrerFee);
            referrer.transfer(referrerFee);
        }
        owner.transfer(devFee);
    }
}

function updateAccount(address account) private {
    uint unclaimedDivs = getUnclaimedDivs(account);
    if (unclaimedDivs > 0) {
        require(Token(VAPEAddress).transfer(account, unclaimedDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(unclaimedDivs);
        totalClaimedRewards = totalClaimedRewards.add(unclaimedDivs);
        emit RewardsTransferred(account, unclaimedDivs);
    }
    lastClaimedTime[account] = now;
}

function getFundedTokens() public view returns(uint) {
    if (totalClaimedRewards >= ToBeFarmedTokens) {
        return 0;
    }
    uint remaining = ToBeFarmedTokens.sub(totalClaimedRewards);
    return remaining;
}

function unfarm(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(farmingTime[msg.sender]) > PossibleUnfarmTime, "You have not staked for a while yet, kindly wait a bit more");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unfarmingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(LPTokenAddress).transfer(admin, fee), "Could not transfer withdraw fee.");
    require(Token(LPTokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function farm(uint amountToFarm) public {
    require(farmingStatus == true, "Staking is not yet initialized");
    require(amountToFarm > 0, "Cannot deposit 0 Tokens");
    require(Token(LPTokenAddress).transferFrom(msg.sender, address(this), amountToFarm), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToFarm.mul(farmingFeeRate).div(1e4);
    uint amountAfterFee = amountToFarm.sub(fee);
    require(Token(LPTokenAddress).transfer(admin, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        farmingTime[msg.sender] = now;
    }
}

function mint(uint256 amount) public onlyBeneficiary() {
    require(s_started == true, "TokenMinter: not started");
    require(amount > 0, "TokenMinter: nothing to mint");
    s_minted = s_minted.add(amount);
    require(s_minted <= mintLimit(), "TokenMinter: amount too high");
    s_token.mint(s_beneficiary, amount);
    emit Minted(amount, block.timestamp);
}

function mintLimit() public view returns(uint256) {
    uint256 maxMinting = TARGET_SUPPLY.sub(s_initialSupply);
    uint256 currentDuration = block.timestamp.sub(s_startTime);
    uint256 effectiveDuration = currentDuration < DURATION ? currentDuration : DURATION;
    return maxMinting.mul(effectiveDuration).div(DURATION);
}

receive() external payable {
    require(saleOpen, "Sale is not open");
    require(usersInvestments[msg.sender].add(msg.value) <= 3 ether, "Max participation is 3 eth");
    uint256 tokens = getTokenAmount(msg.value);
    require(IToken(tokenAddress).transfer(msg.sender, tokens), "Sale is filled");
    usersInvestments[msg.sender] = usersInvestments[msg.sender].add(msg.value);
    owner.transfer(msg.value);
}

function Contribute() payable public {
    uint256 vaultBalance = this.getVaultJFCBalance();
    if (vaultBalance == 0) {
        revert("Not enough JFC in the vault to transfer");
    }
    uint256 amountContributed = msg.value;
    uint256 jfcAmount = (amountContributed * 10000) / (10 ** 18);
    uint256 mJFC = jfcAmount * 100;
    if (mJFC >= vaultBalance) {
        revert("Not enough JFC in the vault to transfer");
    }
    token.transfer(msg.sender, mJFC);
    balances[msg.sender] += msg.value;
    earnedJFC[msg.sender] += mJFC;
    emit Contributed(msg.value);
}

function grant()
public {
    require(wallet == msg.sender);
    require(tranchesPayedOut < tranchesCount);
    require(startTimestamp > 0);
    require(now >= startTimestamp + (period * (tranchesPayedOut + 1)));
    tranchesPayedOut = tranchesPayedOut + 1;
    token.transfer(wallet, trancheSize);
}

function createTokens() isUnderHardCap saleIsOn payable {
    multisig.transfer(msg.value);
    uint tokens = rate.mul(msg.value).div(1 ether);
    uint bonusTokens = 0;
    if (now < start + (period * 1 days).div(3)) {
        bonusTokens = tokens.div(5);
    } else {
        bonusTokens = 0;
    }
    tokens += bonusTokens;
    token.mint(msg.sender, tokens);
}

function buyFci(address _buyer, uint _valueNac) onlyController public {
    require(isPause == false && now < timeExpires);
    require(_buyer != 0x0);
    require(_valueNac * fciDecimals > priceFci);
    uint fciReceive = (_valueNac.mul(fciDecimals)) / priceFci;
    balanceOf[_buyer] = balanceOf[_buyer].add(fciReceive);
    totalSupply = totalSupply.add(fciReceive);
    NetfBalance = NetfBalance.add(_valueNac);
    emit Transfer(address(this), _buyer, fciReceive);
    emit BuyFci(_buyer, _valueNac, fciReceive, now);
}

function updatePriceFci(uint _price, uint _timeExpires) onlyController public {
    require(now > timeExpires);
    priceFci = _price;
    timeExpires = _timeExpires;
}

function sellFci(address _seller, uint _valueFci) onlyController public {
    require(isPause == false && now < timeExpires);
    require(_seller != 0x0);
    require(_valueFci * priceFci > fciDecimals);
    uint nacReturn = (_valueFci.mul(priceFci)) / fciDecimals;
    balanceOf[address(this)] = balanceOf[address(this)].sub(_valueFci);
    totalSupply = totalSupply.sub(_valueFci);
    NetfBalance = NetfBalance.sub(nacReturn);
    NamiCrowdSale namiToken = NamiCrowdSale(NamiAddr);
    namiToken.transfer(_seller, nacReturn);
    emit Transfer(_seller, address(this), _valueFci);
    emit SellFci(_seller, nacReturn, _valueFci, now);
}

