function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(isCrowdsalePaused == false);
    require(validPurchase());
    require(msg.value >= 1 * 10 ** 18);
    require(TOKENS_SOLD < maxTokensToSale);
    uint256 weiAmount = msg.value;
    uint256 timeElapsed = now - startTime;
    uint256 timeElapsedInDays = timeElapsed.div(1 days);
    if (timeElapsedInDays < 12) {
        require(usersAddressForPreICO.length <= 5000);
        if (EthSentAgainstAddress[beneficiary] == 0) {
            usersAddressForPreICO.push(beneficiary);
        }
        EthSentAgainstAddress[beneficiary] += weiAmount;
        weiRaised = weiRaised.add(weiAmount);
        weiRaisedInPreICO = weiRaisedInPreICO.add(weiAmount);
        forwardFunds();
    }
    else if (timeElapsedInDays >= 12 && timeElapsedInDays < 27) {
        revert();
    } else {
        uint256 tokens = weiAmount.mul(ratePerWei);
        uint256 bonus = determineBonus(tokens);
        tokens = tokens.add(bonus);
        require(TOKENS_SOLD.add(tokens) <= maxTokensToSale);
        weiRaised = weiRaised.add(weiAmount);
        token.transfer(beneficiary, tokens);
        emit TokenPurchase(owner, beneficiary, weiAmount, tokens);
        TOKENS_SOLD = TOKENS_SOLD.add(tokens);
        forwardFunds();
    }
}

function burnUnsoldTokens() public onlyOwner {
    require(hasEnded());
    uint value = remainingTokensForSale();
    token.burn(value);
    TOKENS_SOLD = maxTokensToSale;
}

function determineBonus(uint tokens) internal view returns(uint256 bonus) {
    uint256 timeElapsed = now - startTime;
    uint256 timeElapsedInDays = timeElapsed.div(1 days);
    if (timeElapsedInDays < 12) {
        bonus = 0;
    }
    else if (timeElapsedInDays >= 12 && timeElapsedInDays < 27) {
        revert();
    }
    else if (timeElapsedInDays >= 27 && timeElapsedInDays < 37) {
        bonus = tokens.mul(bonusPercInICOPhase1);
        bonus = bonus.div(100);
        require(TOKENS_SOLD.add(tokens.add(bonus)) <= maxTokensToSale);
    }
    else if (timeElapsedInDays >= 37 && timeElapsedInDays < 47) {
        bonus = tokens.mul(bonusPercInICOPhase2);
        bonus = bonus.div(100);
        require(TOKENS_SOLD.add(tokens.add(bonus)) <= maxTokensToSale);
    }
    else if (timeElapsedInDays >= 47 && timeElapsedInDays < 57) {
        bonus = tokens.mul(bonusPercInICOPhase3);
        bonus = bonus.div(100);
        require(TOKENS_SOLD.add(tokens.add(bonus)) <= maxTokensToSale);
    } else {
        bonus = 0;
    }
}

function enter(uint256 leftorright) public payable {
    if (leftorright == 1) {
        maximumBalance = getMaximumBetRate();
        require(msg.value < maximumBalance && msg.value > .001 ether, "Your bet is too high!");
        rewardnumber = randomtests();
        if (rewardnumber < 45) {
            msg.sender.transfer(msg.value.mul(2));
            members[msg.sender].time = now;
            members[msg.sender].luckNumber = rewardnumber;
            members[msg.sender].horseType = leftorright;
            listofUsers.push(msg.sender) - 1;
        } else {
            members[msg.sender].time = now;
            members[msg.sender].luckNumber = rewardnumber;
            members[msg.sender].horseType = leftorright;
            listofUsers.push(msg.sender) - 1;
        }
    } else {
        maximumBalance = getMaximumBetRate();
        require(msg.value < maximumBalance && msg.value > .001 ether, "Your bet is too high or low");
        rewardnumber = randomtests();
        if (rewardnumber > 55) {
            msg.sender.transfer(msg.value.mul(2));
            members[msg.sender].time = now;
            members[msg.sender].horseType = leftorright;
            members[msg.sender].luckNumber = rewardnumber;
            listofUsers.push(msg.sender) - 1;
        } else {
            members[msg.sender].time = now;
            members[msg.sender].horseType = leftorright;
            members[msg.sender].luckNumber = rewardnumber;
            listofUsers.push(msg.sender) - 1;
        }
    }
}

function getAccDetails(address _address) view public returns(string, string, string, string) {
    if (members[_address].time == 0) {
        return ("0", "0", "0", "You have never played this game before");
    } else {
        if (members[_address].horseType == 1) {
            if (rewardnumber < 45) {
                return (uint2str(members[_address].time), uint2str(members[_address].luckNumber), uint2str(members[_address].horseType), "You Win because your number smaller than 45");
            } else {
                return (uint2str(members[_address].time), uint2str(members[_address].luckNumber), uint2str(members[_address].horseType), "youre lose  because your number bigger than 45");
            }
        } else {
            if (rewardnumber > 55) {
                return (uint2str(members[_address].time), uint2str(members[_address].luckNumber), uint2str(members[_address].horseType), "You win, because your number bigger than 55");
            } else {
