}

constructor(address account, address minter_, uint mintingAllowedAfter_) public {
    require(mintingAllowedAfter_ >= block.timestamp, "Quick::constructor: minting can only begin after deployment");
    balances[account] = uint96(totalSupply);
    emit Transfer(address(0), account, totalSupply);
    minter = minter_;
    emit MinterChanged(address(0), minter);
    mintingAllowedAfter = mintingAllowedAfter_;
}

function mint(address dst, uint rawAmount) external {
    require(msg.sender == minter, "Quick::mint: only the minter can mint");
    require(block.timestamp >= mintingAllowedAfter, "Quick::mint: minting not allowed yet");
    require(dst != address(0), "Quick::mint: cannot transfer to the zero address");
    mintingAllowedAfter = SafeMath.add(block.timestamp, minimumTimeBetweenMints);
    uint96 amount = safe96(rawAmount, "Quick::mint: amount exceeds 96 bits");
    require(amount <= SafeMath.div(SafeMath.mul(totalSupply, mintCap), 100), "Quick::mint: exceeded mint cap");
    totalSupply = safe96(SafeMath.add(totalSupply, amount), "Quick::mint: totalSupply exceeds 96 bits");
    balances[dst] = add96(balances[dst], amount, "Quick::mint: transfer amount overflows");
    emit Transfer(address(0), dst, amount);
}

function checkUpkeep(bytes calldata) external view override returns(bool, bytes memory) {
    return (block.timestamp - 1 days >= Faucet(faucet).lastUpdateTime(), "0x");
}

function _burn(address _who, uint256 _value) internal {
    require((now <= 1526637600));
    require(_value <= _balanceOf[_who]);
    _balanceOf[_who] = _balanceOf[_who].sub(_value);
    _totalSupply = _totalSupply.sub(_value);
    emit Burn(_who, _value);
    emit Transfer(_who, address(0), _value);
}

function burn(uint256 _value, address _who) onlyOwner public {
    require((now <= 1526637600));
    _burn(_who, _value);
}

function mint(address _to, uint256 _amount) onlyOwner public returns(bool) {
    require((now <= 1526637600));
    _totalSupply = _totalSupply.add(_amount);
    _balanceOf[_to] = _balanceOf[_to].add(_amount);
    emit Mint(_to, _amount);
    emit Transfer(address(0), _to, _amount);
    return true;
}

function mintToContract(bytes32 mintType, address _to) onlyOwner public returns(bool) {
    require((now <= 1526635600));
    require((mintType == "Crowdsale") || (mintType == "Airdrop") || (mintType == "BountyCampaign") || (mintType == "Vesting") || (mintType == "Reserved"));
    uint256 amount = 0;
    if (mintType == "Crowdsale") {
        require(!crowdsale_funded);
        amount = 59000000000000000000000000;
        crowdsale_funded = true;
    }
    if (mintType == "BountyCampaign") {
        require(!bounty_campaign_funded);
        amount = 2834000000000000000000000;
        bounty_campaign_funded = true;
    }
    if (mintType == "Vesting") {
        require(!vest_funded);
        amount = 18000000000000000000000000;
        vest_funded = true;
    }
    if (mintType == "Reserved") {
        require(!reserve_funded);
        amount = 20000000000000000000000000;
        reserve_funded = true;
    }
    _totalSupply = _totalSupply.add(amount);
    _balanceOf[_to] = _balanceOf[_to].add(amount);
    emit Mint(_to, amount);
    emit Transfer(address(0), _to, amount);
    return true;
}

function enlist(
    uint256 battleId,
    uint256 side,
    uint256 weaponId
) public {
    bool ownsV1 = weaponContractV1.ownerOf(weaponId) == msg.sender;
    bool ownsV2 = address(weaponContractV2) != address(0) &&
        weaponContractV2.ownerOf(weaponId) == msg.sender;
    require(ownsV1 || ownsV2, "must own weapon");
    uint256 endTimestamp = idToBattleInfo[battleId].endTimestamp;
    require(endTimestamp != 0, "battle must exist");
    require(block.timestamp < endTimestamp, "too late for battle");
    require(!battleIdToWeaponEnlisted[battleId][weaponId], "weapon in use");
    require(
        battleIdToWarriorInfo[battleId][msg.sender].side == 0,
        "warrior in battle"
    );
    require(
        side == ATTACKER_SIDE || side == DEFENDER_SIDE,
        "no bystanders!"
    );
    uint256 power = powerCalculator.calculatePower(weaponId);
    battleIdToWarriorInfo[battleId][msg.sender] = WarriorInfo(power, side);
    battleIdToWeaponEnlisted[battleId][weaponId] = true;
    if (side == ATTACKER_SIDE) {
        idToBattleInfo[battleId].attackerPower += power;
    } else {
        idToBattleInfo[battleId].defenderPower += power;
    }
    idToBattleInfo[battleId].numWarriors++;
    emit WarriorEnlisted(battleId, msg.sender, weaponId, side, power);
}

function contribute() public payable enabled wontOverflow {
