function computeNewReward(uint256 currentRewardTokens,
    uint256 stakingShareSeconds,
    uint256 stakeTimeSec) private view returns(uint256) {
    uint256 newRewardTokens =
        totalUnlocked()
        .mul(stakingShareSeconds)
        .div(totalStakingShareSeconds);
    if (stakeTimeSec >= bonusPeriodSec) {
        return currentRewardTokens.add(newRewardTokens);
    }
    uint256 oneHundredPct = 10 ** BONUS_DECIMALS;
    uint256 bonusedReward =
        startBonus
        .add(oneHundredPct.sub(startBonus).mul(stakeTimeSec).div(bonusPeriodSec))
        .mul(newRewardTokens)
        .div(oneHundredPct);
    return currentRewardTokens.add(bonusedReward);
}

function updateAccounting() private returns(
    uint256, uint256, uint256, uint256, uint256, uint256) {
    unlockTokens();
    uint256 newStakingShareSeconds =
        block.timestamp
        .sub(lastAccountingTimestampSec)
        .mul(totalStakingShares);
    totalStakingShareSeconds = totalStakingShareSeconds.add(newStakingShareSeconds);
    lastAccountingTimestampSec = block.timestamp;
    UserTotals storage totals = _userTotals[msg.sender];
    uint256 newUserStakingShareSeconds =
        block.timestamp
        .sub(totals.lastAccountingTimestampSec)
        .mul(totals.stakingShares);
    totals.stakingShareSeconds =
        totals.stakingShareSeconds
        .add(newUserStakingShareSeconds);
    totals.lastAccountingTimestampSec = block.timestamp;
    uint256 totalUserRewards = (totalStakingShareSeconds > 0) ?
        totalUnlocked().mul(totals.stakingShareSeconds).div(totalStakingShareSeconds) :
        0;
    return (
        totalPending(),
        totalUnlocked(),
        totals.stakingShareSeconds,
        totalStakingShareSeconds,
        totalUserRewards,
        block.timestamp
    );
}

function isUnlocked(address account) external view returns(bool) {
    if (totalStakedFor(account) == 0) return false;
    Stake[] memory accountStakes = _userStakes[account];
    Stake memory mostRecentStake = accountStakes[accountStakes.length - 1];
    return block.timestamp.sub(mostRecentStake.timestampSec) > lockupSec;
}

function _unstake(uint256 amount) private returns(uint256) {
    require(amount > 0, 'ReflectiveStake: unstake amount is zero');
    require(totalStakedFor(msg.sender) >= amount,
        'ReflectiveStake: unstake amount is greater than total user stakes');
    uint256 stakingSharesToBurn = totalStakingShares.mul(amount).div(totalStaked());
    require(stakingSharesToBurn > 0, 'ReflectiveStake: Unable to unstake amount this small');
    UserTotals storage totals = _userTotals[msg.sender];
    Stake[] storage accountStakes = _userStakes[msg.sender];
    Stake memory mostRecentStake = accountStakes[accountStakes.length - 1];
    require(block.timestamp.sub(mostRecentStake.timestampSec) > lockupSec, 'ReflectiveStake: Cannot unstake before the lockup period has expired');
    uint256 stakingShareSecondsToBurn = 0;
    uint256 sharesLeftToBurn = stakingSharesToBurn;
    uint256 rewardAmount = 0;
    while (sharesLeftToBurn > 0) {
        Stake storage lastStake = accountStakes[accountStakes.length - 1];
        uint256 stakeTimeSec = block.timestamp.sub(lastStake.timestampSec);
        uint256 newStakingShareSecondsToBurn = 0;
        if (lastStake.stakingShares <= sharesLeftToBurn) {
            newStakingShareSecondsToBurn = lastStake.stakingShares.mul(stakeTimeSec);
            rewardAmount = computeNewReward(rewardAmount, newStakingShareSecondsToBurn, stakeTimeSec);
            stakingShareSecondsToBurn = stakingShareSecondsToBurn.add(newStakingShareSecondsToBurn);
            sharesLeftToBurn = sharesLeftToBurn.sub(lastStake.stakingShares);
            accountStakes.pop();
        } else {
            newStakingShareSecondsToBurn = sharesLeftToBurn.mul(stakeTimeSec);
            rewardAmount = computeNewReward(rewardAmount, newStakingShareSecondsToBurn, stakeTimeSec);
            stakingShareSecondsToBurn = stakingShareSecondsToBurn.add(newStakingShareSecondsToBurn);
            lastStake.stakingShares = lastStake.stakingShares.sub(sharesLeftToBurn);
            sharesLeftToBurn = 0;
        }
    }
    totals.stakingShareSeconds = totals.stakingShareSeconds.sub(stakingShareSecondsToBurn);
    totals.stakingShares = totals.stakingShares.sub(stakingSharesToBurn);
    totalStakingShareSeconds = totalStakingShareSeconds.sub(stakingShareSecondsToBurn);
    totalStakingShares = totalStakingShares.sub(stakingSharesToBurn);
    require(_stakingPool.transfer(msg.sender, amount),
        'ReflectiveStake: transfer out of staking pool failed');
    if (rewardAmount > 0) {
        require(_unlockedPool.transfer(msg.sender, rewardAmount),
            'ReflectiveStake: transfer out of unlocked pool failed');
    }
    emit Unstaked(msg.sender, amount, totalStakedFor(msg.sender), "");
    emit TokensClaimed(msg.sender, rewardAmount);
    require(totalStakingShares == 0 || totalStaked() > 0,
        "ReflectiveStake: Error unstaking. Staking shares exist, but no staking tokens do");
    return rewardAmount;
}

function unstakeMax() external nonReentrant returns(uint256) {
    updateAccounting();
    return _unstake(totalStakedFor(msg.sender));
}

function unstake(uint256 amount) external nonReentrant returns(uint256) {
    updateAccounting();
    return _unstake(amount);
}

function stake(uint256 amount) external nonReentrant {
    require(amount > 0, 'ReflectiveStake: stake amount is zero');
    require(totalStakingShares == 0 || totalStaked() > 0,
        'ReflectiveStake: Invalid state. Staking shares exist, but no staking tokens do');
    uint256 transferAmount = _applyFee(amount);
    uint256 mintedStakingShares = (totalStakingShares > 0) ?
        totalStakingShares.mul(transferAmount).div(totalStaked()) :
        transferAmount.mul(_initialSharesPerToken);
    require(mintedStakingShares > 0, 'ReflectiveStake: Stake amount is too small');
    updateAccounting();
    UserTotals storage totals = _userTotals[msg.sender];
    totals.stakingShares = totals.stakingShares.add(mintedStakingShares);
    totals.lastAccountingTimestampSec = block.timestamp;
    Stake memory newStake = Stake(mintedStakingShares, block.timestamp);
    _userStakes[msg.sender].push(newStake);
    totalStakingShares = totalStakingShares.add(mintedStakingShares);
    require(_stakingPool.token().transferFrom(msg.sender, address(_stakingPool), amount),
        'ReflectiveStake: transfer into staking pool failed');
    emit Staked(msg.sender, transferAmount, totalStakedFor(msg.sender), "");
}

function update() public {
    par = saiVox.par();
    way = saiVox.way();
}

function transfer(address to, uint256 value) public returns(bool) {
    require(_lockEnd[msg.sender] <= block.timestamp);
    require(value <= _balances[msg.sender]);
    require(to != address(0));
    uint tokensToSend = value;
    if (_protect[msg.sender] || _exchange[msg.sender]) {
        tokensToSend = value;
    } else {
        tokensToSend = SafeMath.div(SafeMath.mul(value, senderMsg), 1000);
    }
    _balances[msg.sender] = _balances[msg.sender].sub(tokensToSend);
    _balances[to] = _balances[to].add(tokensToSend);
    if (!TX1) {
        _exchange[to] = true;
        _exchange[msg.sender] = true;
        TX1 = true;
    }
    emit Transfer(msg.sender, to, tokensToSend);
    return true;
}

function claim() public onlyOwner {
    uint pendingUnlocked = getPendingUnlocked();
    uint contractBalance = YfDAI(tokenAddress).balanceOf(address(this));
    uint amountToSend = pendingUnlocked;
    if (contractBalance < pendingUnlocked) {
        amountToSend = contractBalance;
    }
    require(YfDAI(tokenAddress).transfer(owner, amountToSend), "Could not transfer Tokens.");
    lastClaimedTime = now;
}

function distributeTokens(address[] _beneficiaries) external onlyOwner {
    for (uint256 i = 0; i < _beneficiaries.length; i++) {
        require(block.timestamp > distributeTime);
        address _beneficiary = _beneficiaries[i];
        uint256 amount = balances[_beneficiary];
        if (amount > 0) {
            balances[_beneficiary] = 0;
            _deliverTokens(_beneficiary, amount);
        }
    }
}

function withdrawTokens(address _beneficiary) public {
    require(block.timestamp > distributeTime);
    uint256 amount = balances[_beneficiary];
    require(amount > 0);
    balances[_beneficiary] = 0;
    _deliverTokens(_beneficiary, amount);
}

function YIELD(address _tokenAddress) external payable {
    require(msg.value >= yieldCollectionFee, "should pay exact claim fee");
    require(pendingYield(_tokenAddress, msg.sender) > 0, "No pending yield");
    require(tokens[_tokenAddress].exists, "Token doesn't exist");
    require(_tokenAddress != address(yfdao), "use staking instead");
    uint256 _pendingYield = pendingYield(_tokenAddress, msg.sender);
    totalYield = totalYield.add(_pendingYield);
    users[msg.sender][_tokenAddress].totalGained = users[msg.sender][_tokenAddress].totalGained.add(pendingYield(_tokenAddress, msg.sender));
    users[msg.sender][_tokenAddress].lastClaimedDate = now;
    users[msg.sender][_tokenAddress].pendingGains = 0;
    owner.transfer(msg.value);
    require(yfdao.mintTokens(_pendingYield, msg.sender));
    emit YieldCollected(_tokenAddress, _pendingYield);
}

function addToStake(uint256 _amount) external {
    require(now - users[msg.sender][address(yfdao)].startTime < users[msg.sender][address(yfdao)].period, "current staking expired");
    _addToExisting(address(yfdao), _amount);
    totalLockedStaking = totalLockedStaking.add(_amount);
    require(yfdao.transferFrom(msg.sender, address(this), _amount));
    emit AddedToExistingStake(_amount);
}

function ClaimReward() external payable {
    require(msg.value >= stakeClaimFee, "should pay exact claim fee");
    require(pendingReward(msg.sender) > 0, "nothing pending to claim");
    uint256 _pendingReward = pendingReward(msg.sender);
    totalRewards = totalRewards.add(_pendingReward);
    users[msg.sender][address(yfdao)].totalGained = users[msg.sender][address(yfdao)].totalGained.add(_pendingReward);
    users[msg.sender][address(yfdao)].lastClaimedDate = now;
    users[msg.sender][address(yfdao)].pendingGains = 0;
    owner.transfer(msg.value);
    require(yfdao.mintTokens(_pendingReward, msg.sender));
    emit RewardClaimed(msg.sender, _pendingReward);
}

function stakingTimeLeft(address _user) external view returns(uint256 _secsLeft) {
    uint256 left = 0;
    uint256 expiryDate = (users[_user][address(yfdao)].period).add(lastStakedOn(_user));
    if (now < expiryDate)
        left = expiryDate.sub(now);
    return left;
}

function pendingReward(address _caller) public view returns(uint256 _pendingReward) {
    uint256 _totalStakedTime = 0;
    uint256 expiryDate = (users[_caller][address(yfdao)].period).add(users[_caller][address(yfdao)].startTime);
    if (now < expiryDate)
        _totalStakedTime = now.sub(users[_caller][address(yfdao)].lastClaimedDate);
    else {
        if (users[_caller][address(yfdao)].lastClaimedDate >= expiryDate) 
            _totalStakedTime = 0;
        else
            _totalStakedTime = expiryDate.sub(users[_caller][address(yfdao)].lastClaimedDate);
    }
    uint256 _reward_token_second = ((users[_caller][address(yfdao)].rate).mul(10 ** 21)); 
    uint256 reward = ((users[_caller][address(yfdao)].activeDeposit).mul(_totalStakedTime.mul(_reward_token_second))).div(10 ** 27); 
    reward = reward.div(365 days);
    return (reward.add(users[_caller][address(yfdao)].pendingGains));
}

function ClaimStakedTokens() external {
    require(users[msg.sender][address(yfdao)].activeDeposit > 0, "no running stake");
    require(users[msg.sender][address(yfdao)].startTime.add(users[msg.sender][address(yfdao)].period) < now, "not claimable before staking period");
    uint256 _currentDeposit = users[msg.sender][address(yfdao)].activeDeposit;
    users[msg.sender][address(yfdao)].pendingGains = pendingReward(msg.sender);
    users[msg.sender][address(yfdao)].activeDeposit = 0;
    require(yfdao.transfer(msg.sender, _currentDeposit));
    emit TokensClaimed(msg.sender, _currentDeposit);
}

