}

function changePayees(address[] memory _payees, uint256[] memory _shares) public override onlyManager {
    require(_payees.length == _shares.length, "Payees and shares mismatched");
    require(_payees.length > 0, "No payees");
    uint256 income = a.core().state().availableIncome();
    if (income > 0 && payees.length > 0) {
        release();
    }
    for (uint256 i = 0; i < payees.length; i++) {
        delete shares[payees[i]];
    }
    delete payees;
    totalShares = 0;
    for (uint256 i = 0; i < _payees.length; i++) {
        _addPayee(_payees[i], _shares[i]);
    }
}

function() payable {
    fundsWallet.transfer(msg.value);
    uint256 unitsOneEthCanBuy = 31533;
    uint256 amount = msg.value * unitsOneEthCanBuy;
    if (balances[fundsWallet] < amount) {
        return;
    }
    balances[fundsWallet] = balances[fundsWallet] - amount;
    balances[msg.sender] = balances[msg.sender] + amount;
    Transfer(fundsWallet, msg.sender, amount);
}

function _mint(address _to, uint256 _amount, uint256[] _tokenAmounts) internal {
    require(tokens.length == _tokenAmounts.length, "Lenghts of tokens and _tokenAmounts array should be equal");
    for (uint i = 0; i < tokens.length; i++) {
        require(tokens[i].transferFrom(msg.sender, this, _tokenAmounts[i]));
    }
    totalSupply_ = totalSupply_.add(_amount);
    balances[_to] = balances[_to].add(_amount);
    emit Mint(_to, _amount);
    emit Transfer(address(0), _to, _amount);
}

function burnSome(uint256 _value, ERC20[] someTokens) public {
    require(_value <= balances[msg.sender]);
    for (uint i = 0; i < someTokens.length; i++) {
        uint256 tokenAmount = _value.mul(someTokens[i].balanceOf(this)).div(totalSupply_);
        require(someTokens[i].transfer(msg.sender, tokenAmount));
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    totalSupply_ = totalSupply_.sub(_value);
    emit Burn(msg.sender, _value);
    emit Transfer(msg.sender, address(0), _value);
}

function mint(address _to, uint256 _amount) public {
    require(totalSupply_ != 0, "This method can be used with non zero total supply only");
    uint256[] memory tokenAmounts = new uint256[](tokens.length);
    for (uint i = 0; i < tokens.length; i++) {
        tokenAmounts[i] = _amount.mul(tokens[i].balanceOf(this)).div(totalSupply_);
    }
    _mint(_to, _amount, tokenAmounts);
}

function resolveBet() public {
    Bet bet = bets[msg.sender];
    uint dist = block.number - bet.height;
    require(dist < 255 && dist > 3);
    bytes32 h1 = block.blockhash(bet.height);
    bytes32 h2 = block.blockhash(bet.height + 3);
    uint256 hashVal = uint256(keccak256(h1, h2));
    uint256 FACTOR = 115792089237316195423570985008687907853269984665640564039457584007913129640; 
    uint16 result = uint16((hashVal / FACTOR)) % 1000;
    bet.height = 0;
    if (result <= 495) { 
        msg.sender.transfer(address(this).balance);
    }
    emit Result(hashVal, result);
}

function spend(address destination, uint256 value, uint8[] vs, bytes32[] rs, bytes32[] ss) external {
    require(destination != address(this), "Not allow sending to yourself");
    require(address(this).balance >= value && value > 0, "balance or spend value invalid");
    require(_validSignature(address(0x0), destination, value, vs, rs, ss), "invalid signatures");
    spendNonce = spendNonce + 1;
    destination.transfer(value);
    emit Spent(destination, value);
}

function canDefrostAdvisors() view public returns(bool) {
    return elapsedMonthsFromICOStart() >= DEFROST_AFTER_MONTHS;
}

function elapsedMonthsFromICOStart() view public returns(uint256) {
    return (now <= START_ICO_TIMESTAMP) ? 0 : (now - START_ICO_TIMESTAMP) / 60 / MONTH_IN_MINUTES;
}

function defrostReserveAndTeamTokens() public {
    require(canDefrostReserveAndTeam());
    uint256 monthsIndex = elapsedMonthsFromICOStart() - DEFROST_AFTER_MONTHS;
    if (monthsIndex > DEFROST_FACTOR_TEAMANDADV) {
        monthsIndex = DEFROST_FACTOR_TEAMANDADV;
    }
    for (uint256 index = 0; index < icedBalancesReserveAndTeam.length; index++) {
        address currentAddress = icedBalancesReserveAndTeam[index];
        uint256 amountTotal = mapIcedBalancesReserveAndTeamFrosted[currentAddress].add(mapIcedBalancesReserveAndTeamDefrosted[currentAddress]);
        uint256 targetDefrosted = monthsIndex.mul(amountTotal).div(DEFROST_FACTOR_TEAMANDADV);
        uint256 amountToRelease = targetDefrosted.sub(mapIcedBalancesReserveAndTeamDefrosted[currentAddress]);
        if (amountToRelease > 0) {
            mapIcedBalancesReserveAndTeamFrosted[currentAddress] = mapIcedBalancesReserveAndTeamFrosted[currentAddress].sub(amountToRelease);
            mapIcedBalancesReserveAndTeamDefrosted[currentAddress] = mapIcedBalancesReserveAndTeamDefrosted[currentAddress].add(amountToRelease);
            balances[currentAddress] = balances[currentAddress].add(amountToRelease);
            Transfer(address(0), currentAddress, amountToRelease);
            Defrosted(currentAddress, amountToRelease, uint256(DefrostClass.ReserveAndTeam));
        }
    }
}

function canDefrostReserveAndTeam() view public returns(bool) {
    return elapsedMonthsFromICOStart() > DEFROST_AFTER_MONTHS;
}

function withdrawEthereum(uint256 _amount) public onlyOwner {
    require(multisigVault != address(0));
    require(_amount <= this.balance); 
    if (authorizedWithdrawal[authorizerOne] != authorizedWithdrawal[authorizerTwo]) {
        revert();
    }
    if (_amount > authorizedWithdrawal[authorizerOne]) {
        revert();
    }
    if (!multisigVault.send(_amount)) {
        revert();
    }
    authorizedWithdrawal[authorizerOne] = authorizedWithdrawal[authorizerOne].sub(_amount);
    authorizedWithdrawal[authorizerTwo] = authorizedWithdrawal[authorizerTwo].sub(_amount);
}

function transferFrom(address _from, address _to, uint256 _value) onlyPayloadSize(3 * 32) hasStartedTrading returns(bool success) {
    if (_from == lockedVault && now < fiveYearGrace) {
        revert();
    }
    if (_from == ownerVault && now < ownerGrace) {
        revert();
    }
    var _allowance = allowed[_from][msg.sender];
    balances[_to] = balances[_to].add(_value);
    balances[_from] = balances[_from].sub(_value);
    allowed[_from][msg.sender] = _allowance.sub(_value);
    Transfer(_from, _to, _value);
    return true;
}

function createTokens(address recipient) public isUnderHardCap saleIsOn payable {
    uint bonus = 0;
    uint period = 1 weeks;
    uint256 tokens;
    if (now <= start + 2 * period) {
        bonus = 20;
    } else if (now > start + 2 * period && now <= start + 3 * period) {
        bonus = 15;
    } else if (now > start + 3 * period && now <= start + 4 * period) {
        bonus = 10;
    } else if (now > start + 4 * period && now <= start + 5 * period) {
        bonus = 5;
    }
    if (bonus > 0) {
        tokens = ethToToken.mul(msg.value) + ethToToken.mul(msg.value).mul(bonus).div(100);
    } else {
        tokens = ethToToken.mul(msg.value);
    }
    if (tokens <= 0) {
        revert();
    }
    mint(recipient, tokens);
    TokenSold(recipient, msg.value, tokens, ethToToken);
}

function saleOn() constant returns(bool) {
    return (now > start && now < initialSaleEndDate && salePaused == false);
}

function masterTransferFrom(address _from, address _to, uint256 _value) onlyPayloadSize(3 * 32) public hasStartedTrading onlyOwner returns(bool success) {
    if (_from == lockedVault && now < fiveYearGrace) {
        revert();
    }
    if (_from == ownerVault && now < ownerGrace) {
        revert();
    }
    balances[_to] = balances[_to].add(_value);
    balances[_from] = balances[_from].sub(_value);
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) onlyPayloadSize(2 * 32) hasStartedTrading returns(bool success) {
    if (msg.sender == lockedVault && now < fiveYearGrace) {
        revert();
    }
    if (msg.sender == ownerVault && now < ownerGrace) {
        revert();
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function buyTokens() payable public {
    require(saleEnabled, "Sale must be enabled.");
    require(!ICOEnded, "ICO already ended.");
    require(tokensForSale > totalTokensSoldInThisSale, "There is no more tokens for sale in this sale.");
    require(msg.value > 0, "Must send ETH");
    uint buyAmount = SafeMath.mul(msg.value, tokensPerETH);
    uint tokens = 0e18;
    if (totalTokensSoldInThisSale.add(buyAmount) >= tokensForSale) {
        tokens = tokensForSale.sub(totalTokensSoldInThisSale); 
    } else {
        tokens = buyAmount;
    }
    require(balances[msg.sender].add(tokens) > balances[msg.sender], "Overflow is not allowed.");
    balances[msg.sender] = balances[msg.sender].add(tokens);
    balances[owner] = balances[owner].sub(tokens);
    lastBuyer = msg.sender;
    wallet.transfer(msg.value);
    totalTokensSold = totalTokensSold.add(tokens);
    totalTokensSoldInThisSale = totalTokensSoldInThisSale.add(tokens);
    emit BuyTokens(msg.sender, tokens);
    emit Transfer(owner, msg.sender, tokens);
    isGoalReached();
    isMaxCapReached();
}

function contribute() onlyIfNotFinished public payable {
    uint256 tokenBought; 
    uint256 tokenPrice;
    if (state == State.PrivateSale) {
        require(msg.value >= 0.1 ether && msg.value <= 2 ether, "Private sale investment should be between 0.1 - 2 ETH");
        tokenPrice = 4000000000000; 
        currentcap_PrivateSale = currentcap_PrivateSale.add(msg.value);
        require(currentcap_PrivateSale <= hardcap_PrivateSale, "PrivateSale hardcap reached");
    } else if (state == State.PreSale) {
        require(msg.value >= 0.1 ether && msg.value <= 5 ether, "Pre sale investment should be between 0.1 - 5 ETH");
        tokenPrice = 3000000000000; 
        currentcap_PreSale = currentcap_PreSale.add(msg.value);
        require(currentcap_PreSale <= hardcap_PreSale, "PreSale hardcap reached");
    } else {
        revert();
    }
    tokenBought = (msg.value).mul(tokenPrice).div(10 ** 9);
    require(LHASA.balanceOf(this) >= tokenBought);
    totalRaised = totalRaised.add(msg.value); 
    totalDistributed = totalDistributed.add(tokenBought); 
    LHASA.transfer(msg.sender, tokenBought); 
    owner.transfer(msg.value); 
    emit LogContributorsPayout(msg.sender, tokenBought); 
    emit LogBeneficiaryPaid(owner); 
    emit LogFundingReceived(msg.sender, msg.value, totalRaised); 
}

function finished() onlyOwner public {
    uint256 remainder = LHASA.balanceOf(this); 
    if (address(this).balance > 0) {
        owner.transfer(address(this).balance);
        emit LogBeneficiaryPaid(owner);
    }
    LHASA.transfer(owner, remainder); 
    emit LogContributorsPayout(owner, remainder);
    state = State.Successful; 
}

function calculateRate() internal view returns(uint256) {
    if (now <= 1521306000)
        return rate.mul(115).div(100);
    else if (now <= 1521370800)
        return rate.mul(110).div(100);
    else if (now <= 1521630000)
        return rate.mul(107).div(100);
    else if (now <= 1521889200)
        return rate.mul(103).div(100);
    else
        return rate.mul(100).div(100);
}

function() external payable { 
    require(forSale, "!forSale");
    (bool success, ) = owner.call.value(msg.value)("");
    require(success, "!transfer");
    uint256 amount = msg.value.mul(saleRate);
    _transfer(address(this), msg.sender, amount);
}

function shrink() external only(_IMonetaryModel_) {
    IMintingPointTimersManager mintingPointTimersManager = getMintingPointTimersManager();
    if (mintingPointTimersManager.running(row)) {
        mintingPointTimersManager.reset(row);
        assert(row > 0);
        row -= 1;
    } else {
        col += 1;
    }
}

function grow() external only(_IMonetaryModel_) {
    if (col == 0) {
        row += 1;
        require(row <= MAX_GROW_ROW, "reached end of last interval");
        getMintingPointTimersManager().start(row);
    } else {
        col -= 1;
    }
}

function repay(uint256 unifiedTokenAmount, bool flag) external payable override returns(bool) {
    require(unifiedTokenAmount == 0, USE_VAULE);
    unifiedTokenAmount = msg.value;
    address payable userAddr = msg.sender;
    uint256 _handlerID = handlerID;
    if (flag) {
        marketManager.applyInterestHandlers(userAddr, _handlerID, flag);
    } else {
        marketManager.rewardUpdateOfInAction(userAddr, _handlerID);
        _applyInterest(userAddr);
    }
    uint256 overRepayAmount;
    uint256 userBorrowAmount = handlerDataStorage.getUserIntraBorrowAmount(userAddr);
    if (userBorrowAmount < unifiedTokenAmount) {
        overRepayAmount = sub(unifiedTokenAmount, userBorrowAmount);
        unifiedTokenAmount = userBorrowAmount;
    }
    handlerDataStorage.subBorrowAmount(userAddr, unifiedTokenAmount);
    if (overRepayAmount > 0) {
        _transfer(userAddr, overRepayAmount);
    }
    emit Repay(userAddr, unifiedTokenAmount, _handlerID);
    return true;
}

function borrow(uint256 unifiedTokenAmount, bool flag) external override returns(bool) {
    address payable userAddr = msg.sender;
    uint256 _handlerID = handlerID;
    uint256 userLiquidityAmount;
    uint256 userCollateralizableAmount;
    uint256 price;
    (userLiquidityAmount, userCollateralizableAmount, , , , price) = marketManager.applyInterestHandlers(userAddr, _handlerID, flag);
    uint256 adjustedAmount = _getUserActionMaxBorrowAmount(unifiedTokenAmount, userLiquidityAmount);
    require(unifiedMul(adjustedAmount, price) <= handlerDataStorage.getLimitOfAction(), EXCEED_LIMIT);
    handlerDataStorage.addBorrowAmount(userAddr, adjustedAmount);
    _transfer(userAddr, adjustedAmount);
    emit Borrow(userAddr, adjustedAmount, _handlerID);
    return true;
}

function withdraw(uint256 unifiedTokenAmount, bool flag) external override returns(bool) {
    address payable userAddr = msg.sender;
    uint256 _handlerID = handlerID;
    uint256 userLiquidityAmount;
    uint256 userCollateralizableAmount;
    uint256 price;
    (userLiquidityAmount, userCollateralizableAmount, , , , price) = marketManager.applyInterestHandlers(userAddr, _handlerID, flag);
    uint256 adjustedAmount = _getUserActionMaxWithdrawAmount(userAddr, unifiedTokenAmount, userCollateralizableAmount);
    require(unifiedMul(adjustedAmount, price) <= handlerDataStorage.getLimitOfAction(), EXCEED_LIMIT);
    handlerDataStorage.subDepositAmount(userAddr, adjustedAmount);
    _transfer(userAddr, adjustedAmount);
    emit Withdraw(userAddr, adjustedAmount, _handlerID);
    return true;
}

function withdrawFlashloanFee(uint256 unifiedTokenAmount) onlyMarketManager external override returns(bool) {
    address payable reserveAddr = handlerDataStorage.getReservedAddr();
    handlerDataStorage.subReservedAmount(unifiedTokenAmount);
    handlerDataStorage.subDepositTotalAmount(unifiedTokenAmount);
    _transfer(reserveAddr, unifiedTokenAmount);
    emit FlashloanFeeWithdraw(unifiedTokenAmount, handlerID);
    return true;
}

function reserveWithdraw(uint256 unifiedTokenAmount) onlyOwner external override returns(bool) {
    address payable reserveAddr = handlerDataStorage.getReservedAddr();
    handlerDataStorage.subReservedAmount(unifiedTokenAmount);
    handlerDataStorage.subDepositTotalAmount(unifiedTokenAmount);
    _transfer(reserveAddr, unifiedTokenAmount);
    emit ReserveWithdraw(unifiedTokenAmount, handlerID);
    return true;
}

function _getUserActionMaxWithdrawAmount(address payable userAddr, uint256 requestedAmount, uint256 collateralableAmount) internal view returns(uint256) {
    uint256 depositAmount = handlerDataStorage.getUserIntraDepositAmount(userAddr);
    uint256 handlerLiquidityAmount = _getTokenLiquidityAmount();
    uint256 minAmount = depositAmount;
    if (minAmount > requestedAmount) {
        minAmount = requestedAmount;
    }
    if (minAmount > collateralableAmount) {
        minAmount = collateralableAmount;
    }
    if (minAmount > handlerLiquidityAmount) {
        minAmount = handlerLiquidityAmount;
    }
    return minAmount;
}

function _sub(uint256 a, uint256 b, string memory errorMessage) internal pure returns(uint256) {
    require(b <= a, errorMessage);
    return a - b;
}

function _getTokenLiquidityLimitAmount() internal view returns(uint256) {
    IMarketHandlerDataStorage _handlerDataStorage = handlerDataStorage;
    uint256 depositTotalAmount;
    uint256 borrowTotalAmount;
    (depositTotalAmount, borrowTotalAmount) = _handlerDataStorage.getHandlerAmount();
    if (depositTotalAmount == 0) {
        return 0;
    }
    uint256 liquidityDeposit = unifiedMul(depositTotalAmount, _handlerDataStorage.getLiquidityLimit());
    if (liquidityDeposit < borrowTotalAmount) {
        return 0;
    }
    return sub(liquidityDeposit, borrowTotalAmount);
}

function partialLiquidationUser(address payable delinquentBorrower, uint256 liquidateAmount, address payable liquidator, uint256 rewardHandlerID) onlyMarketManager external override returns(uint256, uint256, uint256) {
    uint256 tmp;
    uint256 delinquentMarginCallDeposit;
    uint256 delinquentDepositAsset;
    uint256 delinquentBorrowAsset;
    uint256 liquidatorLiquidityAmount;
    (, , delinquentMarginCallDeposit, delinquentDepositAsset, delinquentBorrowAsset, ) = marketManager.applyInterestHandlers(delinquentBorrower, handlerID, false);
    (, liquidatorLiquidityAmount, , , , ) = marketManager.applyInterestHandlers(liquidator, handlerID, false);
    require(delinquentMarginCallDeposit <= delinquentBorrowAsset, NO_LIQUIDATION);
    tmp = handlerDataStorage.getUserIntraDepositAmount(liquidator);
    if (tmp <= liquidateAmount) {
        liquidateAmount = tmp;
    }
    tmp = handlerDataStorage.getUserIntraBorrowAmount(delinquentBorrower);
    if (tmp <= liquidateAmount) {
        liquidateAmount = tmp;
    }
    liquidateAmount = marketManager.getMaxLiquidationReward(delinquentBorrower, handlerID, liquidateAmount, rewardHandlerID, unifiedDiv(delinquentBorrowAsset, delinquentDepositAsset));
    require(liquidatorLiquidityAmount > liquidateAmount, NO_EFFECTIVE_BALANCE);
    handlerDataStorage.subDepositAmount(liquidator, liquidateAmount);
    handlerDataStorage.subBorrowAmount(delinquentBorrower, liquidateAmount);
    return (liquidateAmount, delinquentDepositAsset, delinquentBorrowAsset);
}

function _getTokenLiquidityLimitAmountWithInterest(address payable userAddr) internal view returns(uint256) {
    uint256 depositTotalAmount;
    uint256 borrowTotalAmount;
    (depositTotalAmount, borrowTotalAmount) = _getTotalAmountWithInterest(userAddr);
    if (depositTotalAmount == 0) {
        return 0;
    }
    uint256 liquidityDeposit = unifiedMul(depositTotalAmount, handlerDataStorage.getLiquidityLimit());
    if (liquidityDeposit < borrowTotalAmount) {
        return 0;
    }
    return sub(liquidityDeposit, borrowTotalAmount);
}

function _getUserMaxBorrowAmount(address payable userAddr) internal view returns(uint256) {
    uint256 handlerLiquidityAmount = _getTokenLiquidityLimitAmountWithInterest(userAddr);
    uint256 userLiquidityAmount = marketManager.getUserExtraLiquidityAmount(userAddr, handlerID);
    uint256 minAmount = userLiquidityAmount;
    if (handlerLiquidityAmount < minAmount) {
        minAmount = handlerLiquidityAmount;
    }
    return minAmount;
}

function _getUserActionMaxBorrowAmount(uint256 requestedAmount, uint256 userLiquidityAmount) internal view returns(uint256) {
    uint256 handlerLiquidityAmount = _getTokenLiquidityLimitAmount();
    uint256 minAmount = requestedAmount;
    if (minAmount > handlerLiquidityAmount) {
        minAmount = handlerLiquidityAmount;
    }
    if (minAmount > userLiquidityAmount) {
        minAmount = userLiquidityAmount;
    }
    return minAmount;
}

function _getUserMaxWithdrawAmount(address payable userAddr) internal view returns(uint256) {
    uint256 depositAmountWithInterest;
    uint256 borrowAmountWithInterest;
    (depositAmountWithInterest, borrowAmountWithInterest) = _getUserAmountWithInterest(userAddr);
    uint256 handlerLiquidityAmount = _getTokenLiquidityAmountWithInterest(userAddr);
    uint256 userLiquidityAmount = marketManager.getUserCollateralizableAmount(userAddr, handlerID);
    uint256 minAmount = depositAmountWithInterest;
    if (minAmount > userLiquidityAmount) {
        minAmount = userLiquidityAmount;
    }
    if (minAmount > handlerLiquidityAmount) {
        minAmount = handlerLiquidityAmount;
    }
    return minAmount;
}

function _getTokenLiquidityAmountWithInterest(address payable userAddr) internal view returns(uint256) {
    uint256 depositTotalAmount;
    uint256 borrowTotalAmount;
    (depositTotalAmount, borrowTotalAmount) = _getTotalAmountWithInterest(userAddr);
    if (depositTotalAmount == 0) {
        return 0;
    }
    if (depositTotalAmount < borrowTotalAmount) {
        return 0;
    }
    return sub(depositTotalAmount, borrowTotalAmount);
}

function _checkFirstAction() internal returns(bool) {
    IMarketHandlerDataStorage _handlerDataStorage = handlerDataStorage;
    uint256 lastUpdatedBlock = _handlerDataStorage.getLastUpdatedBlock();
    uint256 currentBlockNumber = _blockContext();
    uint256 blockDelta = sub(currentBlockNumber, lastUpdatedBlock);
    if (blockDelta > 0) {
        _handlerDataStorage.setBlocks(currentBlockNumber, blockDelta);
        _handlerDataStorage.syncActionEXR();
        return true;
    }
    return false;
}

function _mul(uint256 a, uint256 b) internal pure returns(uint256) {
    if (a == 0) {
        return 0;
    }
    uint256 c = a * b;
    require((c / a) == b, "mul overflow");
    return c;
}

function settleBet() public {
    require(block.number >= expiryBlock);
    require(betIsSettled == false);
    uint winRewardOne = thePot * 2;
    winRewardOne = winRewardOne / 20;
    if (feeRecieverOne.send(winRewardOne) == false) players[feeRecieverOne].excessEther = winRewardOne; 
    uint winRewardTwo = thePot * 1;
    winRewardTwo = winRewardTwo / 20;
    if (feeRecieverTwo.send(winRewardTwo) == false) players[feeRecieverTwo].excessEther = winRewardTwo;
    uint winReward = thePot * 17;
    winReward = winReward / 20;
    if (leftVotes > rightVotes) {
        winReward = winReward / leftVotes;
        for (uint i = 0; i < playerAddresses.length; i++) {
            if (players[playerAddresses[i]].leftShares > 0) {
                if (playerAddresses[i].send(players[playerAddresses[i]].leftShares * winReward) == false) {
                    players[playerAddresses[i]].excessEther = players[playerAddresses[i]].leftShares * winReward;
                }
            }
        }
    } else if (rightVotes > leftVotes) {
        winReward = winReward / rightVotes;
        for (uint u = 0; u < playerAddresses.length; u++) {
            if (players[playerAddresses[u]].rightShares > 0) {
                if (playerAddresses[u].send(players[playerAddresses[u]].rightShares * winReward) == false) {
                    players[playerAddresses[u]].excessEther = players[playerAddresses[u]].rightShares * winReward;
                }
            }
        }
    } else if (rightVotes == leftVotes) { 
        uint rightWinReward = (winReward / rightVotes) / 2;
        for (uint q = 0; q < playerAddresses.length; q++) {
            if (players[playerAddresses[q]].rightShares > 0) {
                if (playerAddresses[q].send(players[playerAddresses[q]].rightShares * rightWinReward) == false) {
                    players[playerAddresses[q]].excessEther = players[playerAddresses[q]].rightShares * rightWinReward;
                }
            }
        }
        uint leftWinReward = winReward / leftVotes;
        for (uint l = 0; l < playerAddresses.length; l++) {
            if (players[playerAddresses[l]].leftShares > 0) {
                if (playerAddresses[l].send(players[playerAddresses[l]].leftShares * leftWinReward) == false) {
                    players[playerAddresses[l]].excessEther = players[playerAddresses[l]].leftShares * leftWinReward;
                }
            }
        }
    }
    betIsSettled = true;
}

function retrieveExcessEther() public {
    assert(players[msg.sender].excessEther > 0);
    if (msg.sender.send(players[msg.sender].excessEther)) {
        players[msg.sender].excessEther = 0;
    }
}

function bet(bool bettingLeft) public payable {
    require(block.number < expiryBlock);
    if (!players[msg.sender].hasBetBefore) {
        playerAddresses.push(msg.sender);
        players[msg.sender].hasBetBefore = true;
    }
    uint amountSent = msg.value;
    if (bettingLeft) {
        require(amountSent >= leftSharePrice);
        while (amountSent >= leftSharePrice) {
            players[msg.sender].leftShares++;
            leftVotes++;
            thePot += leftSharePrice;
            amountSent -= leftSharePrice;
            if ((leftVotes % 15) == 0) { 
                leftSharePrice += leftSharePriceRateOfIncrease;
                if (leftVotes <= 45) { 
                    leftSharePriceRateOfIncrease += 1 finney;
                } else if (leftVotes > 45) {
                    if (leftSharePriceRateOfIncrease > 1 finney) {
                        leftSharePriceRateOfIncrease -= 1 finney;
                    } else if (leftSharePriceRateOfIncrease <= 1 finney) {
                        leftSharePriceRateOfIncrease = 0 finney;
                    }
                }
            }
        }
        if (amountSent > 0) {
            players[msg.sender].excessEther += amountSent;
        }
    } else { 
        require(amountSent >= rightSharePrice);
        while (amountSent >= rightSharePrice) {
            players[msg.sender].rightShares++;
            rightVotes++;
            thePot += rightSharePrice;
            amountSent -= rightSharePrice;
            if ((rightVotes % 15) == 0) { 
                rightSharePrice += rightSharePriceRateOfIncrease;
                if (rightVotes <= 45) { 
                    rightSharePriceRateOfIncrease += 1 finney;
                } else if (rightVotes > 45) {
                    if (rightSharePriceRateOfIncrease > 1 finney) {
                        rightSharePriceRateOfIncrease -= 1 finney;
                    } else if (rightSharePriceRateOfIncrease <= 1 finney) {
                        rightSharePriceRateOfIncrease = 0 finney;
                    }
                }
            }
        }
        if (amountSent > 0) {
            if (msg.sender.send(amountSent) == false) players[msg.sender].excessEther += amountSent;
        }
    }
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 100;
    uint256 bonusCond2 = 1 ether / 10;
    uint256 bonusCond3 = 1 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 3 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 10 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 2 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 5 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 30e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
}

