function swapExactAmountIn(
    address tokenIn,
    uint tokenAmountIn,
    address tokenOut,
    uint minAmountOut,
    uint maxPrice
)
external
_lock_
_logs_
returns(uint tokenAmountOut, uint spotPriceAfter) {
    require(_records[tokenIn].bound, "!bound");
    require(_records[tokenOut].bound, "!bound");
    require(publicSwap, "!publicSwap");
    Record storage inRecord = _records[address(tokenIn)];
    Record storage outRecord = _records[address(tokenOut)];
    require(tokenAmountIn <= bmul(inRecord.balance, BConst.MAX_IN_RATIO), ">maxIRat");
    uint spotPriceBefore = calcSpotPrice(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        swapFee
    );
    require(spotPriceBefore <= maxPrice, "badLimPrice");
    tokenAmountOut = calcOutGivenIn(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        tokenAmountIn,
        swapFee
    );
    require(tokenAmountOut >= minAmountOut, "<limO");
    inRecord.balance = badd(inRecord.balance, tokenAmountIn);
    outRecord.balance = bsub(outRecord.balance, tokenAmountOut);
    spotPriceAfter = calcSpotPrice(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        swapFee
    );
    require(spotPriceAfter >= spotPriceBefore, "errMathAprox");
    require(spotPriceAfter <= maxPrice, ">limPrice");
    require(spotPriceBefore <= bdiv(tokenAmountIn, tokenAmountOut), "errMathAprox");
    emit LOG_SWAP(msg.sender, tokenIn, tokenOut, tokenAmountIn, tokenAmountOut);
    _pullUnderlying(tokenIn, msg.sender, tokenAmountIn);
    uint _subTokenAmountIn;
    (_subTokenAmountIn, tokenAmountOut) = _pushCollectedFundGivenOut(tokenIn, tokenAmountIn, tokenOut, tokenAmountOut);
    if (_subTokenAmountIn > 0) inRecord.balance = bsub(inRecord.balance, _subTokenAmountIn);
    _pushUnderlying(tokenOut, msg.sender, tokenAmountOut);
    return (tokenAmountOut, spotPriceAfter);
}

function swapExactAmountOut(
    address tokenIn,
    uint maxAmountIn,
    address tokenOut,
    uint tokenAmountOut,
    uint maxPrice
)
external
_lock_
_logs_
returns(uint tokenAmountIn, uint spotPriceAfter) {
    require(_records[tokenIn].bound, "!bound");
    require(_records[tokenOut].bound, "!bound");
    require(publicSwap, "!publicSwap");
    Record storage inRecord = _records[address(tokenIn)];
    Record storage outRecord = _records[address(tokenOut)];
    require(tokenAmountOut <= bmul(outRecord.balance, BConst.MAX_OUT_RATIO), ">maxORat");
    uint spotPriceBefore = calcSpotPrice(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        swapFee
    );
    require(spotPriceBefore <= maxPrice, "badLimPrice");
    tokenAmountIn = calcInGivenOut(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        tokenAmountOut,
        swapFee
    );
    require(tokenAmountIn <= maxAmountIn, "<limIn");
    inRecord.balance = badd(inRecord.balance, tokenAmountIn);
    outRecord.balance = bsub(outRecord.balance, tokenAmountOut);
    spotPriceAfter = calcSpotPrice(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        swapFee
    );
    require(spotPriceAfter >= spotPriceBefore, "errMathAprox");
    require(spotPriceAfter <= maxPrice, ">limPrice");
    require(spotPriceBefore <= bdiv(tokenAmountIn, tokenAmountOut), "errMathAprox");
    emit LOG_SWAP(msg.sender, tokenIn, tokenOut, tokenAmountIn, tokenAmountOut);
    _pullUnderlying(tokenIn, msg.sender, tokenAmountIn);
    _pushUnderlying(tokenOut, msg.sender, tokenAmountOut);
    uint _collectedFeeAmount = _pushCollectedFundGivenIn(tokenIn, tokenAmountIn);
    if (_collectedFeeAmount > 0) inRecord.balance = bsub(inRecord.balance, _collectedFeeAmount);
    return (tokenAmountIn, spotPriceAfter);
}

function exitswapExternAmountOut(address tokenOut, uint tokenAmountOut, uint maxPoolAmountIn)
external
_lock_
_logs_
returns(uint poolAmountIn) {
    require(finalized, "!finalized");
    require(_records[tokenOut].bound, "!bound");
    require(tokenAmountOut <= bmul(_records[tokenOut].balance, BConst.MAX_OUT_RATIO), ">maxORat");
    Record storage outRecord = _records[tokenOut];
    poolAmountIn = calcPoolInGivenSingleOut(
        outRecord.balance,
        outRecord.denorm,
        _totalSupply,
        _totalWeight,
        tokenAmountOut,
        swapFee,
        exitFee
    );
    require(poolAmountIn != 0, "errMathAprox");
    require(poolAmountIn <= maxPoolAmountIn, "<limIn");
    outRecord.balance = bsub(outRecord.balance, tokenAmountOut);
    uint _exitFee = bmul(poolAmountIn, exitFee);
    emit LOG_EXIT(msg.sender, tokenOut, tokenAmountOut);
    _pullPoolShare(msg.sender, poolAmountIn);
    uint _collectedFeeAmount = _pushCollectedFundGivenIn(address(this), poolAmountIn);
    _burnPoolShare(bsub(bsub(poolAmountIn, _exitFee), _collectedFeeAmount));
    _pushPoolShare(factory, _exitFee);
    _pushUnderlying(tokenOut, msg.sender, tokenAmountOut);
    return poolAmountIn;
}

function joinswapExternAmountIn(address tokenIn, uint tokenAmountIn, uint minPoolAmountOut)
external
_lock_
_logs_
returns(uint poolAmountOut)
{
    require(finalized, "!finalized");
    require(_records[tokenIn].bound, "!bound");
    require(tokenAmountIn <= bmul(_records[tokenIn].balance, BConst.MAX_IN_RATIO), ">maxIRat");
    Record storage inRecord = _records[tokenIn];
    poolAmountOut = calcPoolOutGivenSingleIn(
        inRecord.balance,
        inRecord.denorm,
        _totalSupply,
        _totalWeight,
        tokenAmountIn,
        swapFee
    );
    require(poolAmountOut >= minPoolAmountOut, "<limO");
    inRecord.balance = badd(inRecord.balance, tokenAmountIn);
    emit LOG_JOIN(msg.sender, tokenIn, tokenAmountIn);
    _mintPoolShare(poolAmountOut);
    _pullUnderlying(tokenIn, msg.sender, tokenAmountIn);
    uint _subTokenAmountIn;
    (_subTokenAmountIn, poolAmountOut) = _pushCollectedFundGivenOut(tokenIn, tokenAmountIn, address(this), poolAmountOut);
    if (_subTokenAmountIn > 0) inRecord.balance = bsub(inRecord.balance, _subTokenAmountIn);
    _pushPoolShare(msg.sender, poolAmountOut);
    return poolAmountOut;
}

function joinswapPoolAmountOut(address tokenIn, uint poolAmountOut, uint maxAmountIn)
external
_lock_
_logs_
returns(uint tokenAmountIn) {
    require(finalized, "!finalized");
    require(_records[tokenIn].bound, "!bound");
    Record storage inRecord = _records[tokenIn];
    tokenAmountIn = calcSingleInGivenPoolOut(
        inRecord.balance,
        inRecord.denorm,
        _totalSupply,
        _totalWeight,
        poolAmountOut,
        swapFee
    );
    require(tokenAmountIn != 0, "errMathAprox");
    require(tokenAmountIn <= maxAmountIn, "<limIn");
    require(tokenAmountIn <= bmul(_records[tokenIn].balance, BConst.MAX_IN_RATIO), ">maxIRat");
    inRecord.balance = badd(inRecord.balance, tokenAmountIn);
    emit LOG_JOIN(msg.sender, tokenIn, tokenAmountIn);
    _mintPoolShare(poolAmountOut);
    _pushPoolShare(msg.sender, poolAmountOut);
    _pullUnderlying(tokenIn, msg.sender, tokenAmountIn);
    uint _collectedFeeAmount = _pushCollectedFundGivenIn(tokenIn, tokenAmountIn);
    if (_collectedFeeAmount > 0) inRecord.balance = bsub(inRecord.balance, _collectedFeeAmount);
    return tokenAmountIn;
}

function exitPool(uint poolAmountIn, uint[] calldata minAmountsOut)
external
_lock_
_logs_ {
    require(finalized, "!finalized");
    uint poolTotal = totalSupply();
    uint _exitFee = bmul(poolAmountIn, exitFee);
    uint pAiAfterExitFee = bsub(poolAmountIn, _exitFee);
    uint ratio = bdiv(pAiAfterExitFee, poolTotal);
    require(ratio != 0, "errMathAprox");
    _pullPoolShare(msg.sender, poolAmountIn);
    _pushPoolShare(factory, _exitFee);
    _burnPoolShare(pAiAfterExitFee);
    for (uint i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint bal = _records[t].balance;
        uint tokenAmountOut = bmul(ratio, bal);
        require(tokenAmountOut != 0, "errMathAprox");
        require(tokenAmountOut >= minAmountsOut[i], "<limO");
        _records[t].balance = bsub(_records[t].balance, tokenAmountOut);
        emit LOG_EXIT(msg.sender, t, tokenAmountOut);
        _pushUnderlying(t, msg.sender, tokenAmountOut);
    }
}

function joinPool(uint poolAmountOut, uint[] calldata maxAmountsIn)
external
_lock_
_logs_ {
    require(finalized, "!finalized");
    uint poolTotal = totalSupply();
    uint ratio = bdiv(poolAmountOut, poolTotal);
    require(ratio != 0, "errMathAprox");
    for (uint i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint bal = _records[t].balance;
        uint tokenAmountIn = bmul(ratio, bal);
        require(tokenAmountIn != 0, "errMathAprox");
        require(tokenAmountIn <= maxAmountsIn[i], "<limIn");
        _records[t].balance = badd(_records[t].balance, tokenAmountIn);
        emit LOG_JOIN(msg.sender, t, tokenAmountIn);
        _pullUnderlying(t, msg.sender, tokenAmountIn);
    }
    _mintPoolShare(poolAmountOut);
    _pushPoolShare(msg.sender, poolAmountOut);
}

function releaseToken() public {
    require(now >= startTime + 2 years);
    uint256 i = ((now - startTime - 2 years) / (0.5 years));
    uint256 releasevalue = totalSupply / 40;
    require(lockAmount > (4 - i - 1) * releasevalue);
    lockAmount -= releasevalue;
    balances[lockOwner] += releasevalue;
}

function executeSignatures(uint8[] vs, bytes32[] rs, bytes32[] ss, bytes message) external {
    Message.hasEnoughValidSignatures(message, vs, rs, ss, validatorContract());
    address recipient;
    uint256 amount;
    bytes32 txHash;
    address contractAddress;
    (recipient, amount, txHash, contractAddress) = Message.parseMessage(message);
    if (messageWithinLimits(amount)) {
        require(contractAddress == address(this));
        require(!relayedMessages(txHash));
        setRelayedMessages(txHash, true);
        require(onExecuteMessage(recipient, amount));
        emit RelayedMessage(recipient, amount, txHash);
    } else {
        onFailedMessage(recipient, amount, txHash);
    }
}

function sendFunds(address beneficiary, uint amount, uint successLogAmount) private {
    if (beneficiary.send(amount)) {
        emit Payment(beneficiary, successLogAmount);
    } else {
        emit FailedPayment(beneficiary, amount);
    }
}

function finalize() {
    require(!isFinalized);
    require(hasEnded() || maxReached());
    finalization();
    Finalized();
    isFinalized = true;
}

function PLCCrowdsale(
    address _kyc,
    address _token,
    address _refundVault,
    address _devMultisig,
    address[] _reserveWallet,
    uint64[6] _timelines, 
    uint256 _maxEtherCap,
    uint256 _minEtherCap) {
    for (uint8 i = 0; i < _timelines.length - 1; i++) {
        require(_timelines[i] < _timelines[i + 1]);
    }
    require(_timelines[0] >= now);
    require(_kyc != 0x00 && _token != 0x00 && _refundVault != 0x00 && _devMultisig != 0x00);
    for (i = 0; i < _reserveWallet.length; i++) {
        require(_reserveWallet[i] != 0x00);
    }
    require(_minEtherCap < _maxEtherCap);
    kyc = KYC(_kyc);
    token = PLC(_token);
    vault = RefundVault(_refundVault);
    devMultisig = _devMultisig;
    reserveWallet = _reserveWallet;
    startTime = _timelines[0];
    endTime = _timelines[5];
    deadlines[0] = _timelines[1];
    deadlines[1] = _timelines[2];
    deadlines[2] = _timelines[3];
    deadlines[3] = _timelines[4];
    deadlines[4] = _timelines[5];
    maxEtherCap = _maxEtherCap;
    minEtherCap = _minEtherCap;
}

function calculateVestedTokens(
    uint256 tokens,
    uint256 time,
    uint256 start,
    uint256 cliff,
    uint256 vesting) constant returns(uint256) {
    if (time < cliff) return 0;
    if (time >= vesting) return tokens;
    uint256 vestedTokens = div(
        mul(
            tokens,
            sub(time, start)
        ),
        sub(vesting, start)
    );
    return vestedTokens;
}

function getRate() constant returns(uint256 rate) {
    for (uint8 i = 0; i < deadlines.length; i++)
        if (now < deadlines[i])
            return rates[i];
    return rates[rates.length - 1]; 
}

function() payable {
    if (isDeferred[msg.sender])
        buyDeferredPresaleTokens(msg.sender);
    else if (now < startTime)
        buyPresaleTokens(msg.sender);
    else
        buyTokens();
}

function close() onlyOwner {
    require(state == State.Active);
    state = State.Closed;
    uint256 balance = this.balance;
    uint256 devAmount = div(balance, 10);
    devMultisig.transfer(devAmount);
    Transferred(devMultisig, devAmount);
    uint256 reserveAmount = div(mul(balance, 9), 10);
    uint256 reserveAmountForEach = div(reserveAmount, reserveWallet.length);
    for (uint8 i = 0; i < reserveWallet.length; i++) {
        reserveWallet[i].transfer(reserveAmountForEach);
        Transferred(reserveWallet[i], reserveAmountForEach);
    }
    Closed();
}

function refund(address investor) returns(bool) {
    require(state == State.Refunding);
    if (refunded[investor] > 0) {
        return false;
    }
    uint256 depositedValue = deposited[investor];
    deposited[investor] = 0;
    refunded[investor] = depositedValue;
    investor.transfer(depositedValue);
    Refunded(investor, depositedValue);
    return true;
}

function buyDeferredPresaleTokens(address beneficiary)
payable
whenNotPaused {
    require(beneficiary != 0x00);
    require(isDeferred[beneficiary]);
    uint guaranteedLimit = presaleGuaranteedLimit[beneficiary];
    require(guaranteedLimit > 0);
    uint256 weiAmount = msg.value;
    require(weiAmount != 0);
    uint256 totalAmount = add(buyerFunded[true][beneficiary], weiAmount);
    uint256 toFund;
    if (totalAmount > guaranteedLimit) {
        toFund = sub(guaranteedLimit, buyerFunded[true][beneficiary]);
    } else {
        toFund = weiAmount;
    }
    require(toFund > 0);
    require(weiAmount >= toFund);
    uint256 tokens = mul(toFund, presaleRate[beneficiary]);
    uint256 toReturn = sub(weiAmount, toFund);
    buy(beneficiary, tokens, toFund, toReturn, true);
    uint256 devAmount = div(mul(tokens, 20), 70);
    uint256 reserveAmount = div(mul(tokens, 10), 70);
    distributeToken(devAmount, reserveAmount, true);
    uint256 devEtherAmount = div(toFund, 10);
    uint256 reserveEtherAmount = div(mul(toFund, 9), 10);
    distributeEther(devEtherAmount, reserveEtherAmount);
    DeferredPresaleTokenPurchase(msg.sender, beneficiary, toFund, tokens);
}

function buyTokens()
payable
whenNotPaused
canBuyInBlock
onlyAfterStart
onlyRegistered(msg.sender) {
