}

function unstake(uint256 amount) external {
    require(
        _stakedBalances[_msgSender()] >= amount,
        "Unstake amount exceededs the staked amount."
    );
    require(
        _mainTokenContract.transfer(
            _msgSender(),
            amount
        ),
        "Unstake failed"
    );
    _stakedBalances[_msgSender()] = _stakedBalances[_msgSender()].sub(amount);
    _totalStackedAmount = _totalStackedAmount.sub(amount);
    if (_stakedBalances[_msgSender()] == 0) {
        for (uint i = 0; i < _stakers.length; i++) {
            if (_stakers[i] == _msgSender()) {
                _stakers[i] = _stakers[_stakers.length - 1];
                _stakers.pop();
                break;
            }
        }
    }
    emit Unstaked(_msgSender(), amount);
    uint256 rewardsAmount = _rewards[_msgSender()];
    if (rewardsAmount > 0) {
        require(
            _storeWalletContract.giveReward(_msgSender(), rewardsAmount),
            "Claim failed."
        );
        _rewards[_msgSender()] = 0;
        emit Claim(_msgSender(), rewardsAmount);
    }
}

function endStake() external {
    uint256 rewardsAmount = _rewards[_msgSender()];
    if (rewardsAmount > 0) {
        require(
            _storeWalletContract.giveReward(_msgSender(), rewardsAmount),
            "Claim failed."
        );
        _rewards[_msgSender()] = 0;
        emit Claim(_msgSender(), rewardsAmount);
    }
    uint256 unstakeAmount = _stakedBalances[_msgSender()];
    if (unstakeAmount > 0) {
        require(
            _mainTokenContract.transfer(
                _msgSender(),
                unstakeAmount
            ),
            "Unstake failed"
        );
        _stakedBalances[_msgSender()] = 0;
        _totalStackedAmount = _totalStackedAmount.sub(unstakeAmount);
        for (uint i = 0; i < _stakers.length; i++) {
            if (_stakers[i] == _msgSender()) {
                _stakers[i] = _stakers[_stakers.length - 1];
                _stakers.pop();
                break;
            }
        }
        emit Unstaked(_msgSender(), unstakeAmount);
    }
}

function calcRewards() external {
    uint256 currentTimestamp = uint256(now);
    uint256 diff = currentTimestamp.sub(_lastTimestamp);
    if (diff >= _rewardPeriod) {
        uint256 rewardDays = diff.div(_rewardPeriod);
        uint256 offsetTimestamp = diff.sub(_rewardPeriod.mul(rewardDays));
        uint256 _storeBalance = _storeWalletContract.getStoreBalance();
        for (uint j = 0; j < rewardDays; j++) {
            uint256 _totalRewardsAmount = _storeBalance.div(_rewardPortion);
            if (_totalRewardsAmount > 0) {
                uint256 _rewardForStaker = _totalRewardsAmount.mul(_rewardFee).div(100);
                uint256 _rewardForDev = _totalRewardsAmount.sub(_rewardForStaker);
                for (uint i = 0; i < _stakers.length; i++) {
                    if (_stakers[i] != address(0)) {
                        _rewards[_stakers[i]] = _rewards[_stakers[i]].add(_stakedBalances[_stakers[i]].mul(_rewardForStaker).div(_totalStackedAmount));
                    }
                }
                if (_rewardForDev > 0)
                    _storeWalletContract.giveReward(_devWallet, _rewardForDev);
            }
            _storeBalance = _storeBalance.sub(_totalRewardsAmount);
        }
        _lastTimestamp = currentTimestamp.sub(offsetTimestamp);
    }
}

function claim(uint256 amount) external {
    require(
        _rewards[_msgSender()] >= amount,
        "Claim amount exceededs the pendnig rewards."
    );
    require(
        _storeWalletContract.giveReward(_msgSender(), amount),
        "Claim failed."
    );
    _rewards[_msgSender()] = _rewards[_msgSender()].sub(amount);
    emit Claim(_msgSender(), amount);
}

function stake(uint256 amount) external {
    require(
        amount >= _minStakeAmount,
        "Too small amount"
    );
    require(
        _mainTokenContract.transferFrom(
            _msgSender(),
            address(this),
            amount
        ),
        "Stake failed"
    );
    uint256 taxAmount = amount.mul(_taxFee).div(100);
    uint256 stackedAmount = amount.sub(taxAmount);
    if (_stakers.length == 0)
        _lastTimestamp = uint256(now);
    if (_stakedBalances[_msgSender()] == 0)
        _stakers.push(_msgSender());
    _stakedBalances[_msgSender()] = _stakedBalances[_msgSender()].add(stackedAmount);
    _totalStackedAmount = _totalStackedAmount.add(stackedAmount);
    emit Staked(_msgSender(), stackedAmount);
}

function withdrawReward() public disableContract {
    if (games[round].endTime <= now) endRound();
    updateReward(msg.sender);
    Player storage p = players[msg.sender];
    msg.sender.send(p.reward);
    p.reward = 0;
}

function share(uint256 _value) public disableContract {
    require(miningWarDeadline > now);
    require(games[round].ended == false);
    require(_value >= 10000);
    MiningWarContract.subCrystal(msg.sender, _value);
    if (games[round].endTime <= now) endRound();
    updateReward(msg.sender);
    Game storage g = games[round];
    uint256 _share = SafeMath.mul(_value, CRTSTAL_MINING_PERIOD);
    g.crystals = SafeMath.add(g.crystals, _share);
    Player storage p = players[msg.sender];
    if (p.currentRound == round) {
        p.share = SafeMath.add(p.share, _share);
    } else {
        p.share = _share;
        p.currentRound = round;
    }
}

function startRound() private {
    require(games[round].ended == true);
    uint256 crystalsLastRound = games[round].crystals;
    uint256 prizePoolLastRound = games[round].prizePool;
    round = round + 1;
    uint256 endTime = now + HALF_TIME;
    uint256 engineerPrizePool = getEngineerPrizePool();
    uint256 prizePool = SafeMath.div(SafeMath.mul(engineerPrizePool, 5), 100);
    if (crystalsLastRound <= 0) {
        prizePool = SafeMath.add(prizePool, prizePoolLastRound);
    }
    EngineerContract.claimPrizePool(address(this), prizePool);
    games[round] = Game(round, 0, prizePool, endTime, false);
}

function startGame() public {
    require(msg.sender == administrator);
    require(init == false);
    init = true;
    miningWarDeadline = getMiningWarDealine();
    games[round].ended = true;
    startRound();
}

function calculateReward(address _addr, uint256 _round) public view returns(uint256) {
    Player memory p = players[_addr];
    Game memory g = games[_round];
    if (g.endTime > now) return 0;
    if (g.crystals == 0) return 0;
    return SafeMath.div(SafeMath.mul(g.prizePool, p.share), g.crystals);
}

function endRound() private {
    require(games[round].ended == false);
    require(games[round].endTime <= now);
    Game storage g = games[round];
    g.ended = true;
    startRound();
    emit EndRound(g.round, g.crystals, g.prizePool, g.endTime);
}

function updateReward(address _addr) private {
    Player storage p = players[_addr];
    if (
        games[p.currentRound].ended == true &&
        p.lastRound < p.currentRound
    ) {
        p.reward = SafeMath.add(p.share, calculateReward(msg.sender, p.currentRound));
        p.lastRound = p.currentRound;
    }
}

function() payable {
    if (!purchasingAllowed) {
        throw;
    }
    if (msg.value == 0) {
        return;
    }
    if (totalSupply > maxSupply && msg.sender != owner) {
        throw;
    }
    owner.transfer(msg.value);
    totalContribution += msg.value;
    uint256 tokensIssued = (msg.value * 100);
    totalSupply += tokensIssued;
    if (msg.sender == owner) {
        maxSupply += (msg.value * 1000000000000000000); 
    }
    balances[msg.sender] += tokensIssued;
    Transfer(address(this), msg.sender, tokensIssued);
}

function releaseToken() public {
    require(vestingSchedule.length > 0);
    require(msg.sender == owner() || msg.sender == receivingAddress);
    if (vestingStartTime == 0) {
        require(msg.sender == owner());
        vestingStartTime = block.timestamp;
    }
    for (uint256 i = index; i < vestingSchedule.length; i++) {
        if (block.timestamp >= vestingStartTime + (index * releaseInterval)) {
            tokenContract.transfer(receivingAddress, (vestingSchedule[i] * 1 ether));
            index = index.add(1);
        } else {
            break;
        }
    }
}

function updateVestingSchedule(uint256[] memory _vestingSchedule) public onlyOwner {
    require(vestingStartTime == 0);
    vestingSchedule = _vestingSchedule;
}

function pendingBalanceOf(address _account) external view returns(uint256) {
    if (!IVotingEligibility(eligiblelist).isEligible(_account)) {
        return 0;
    }
    uint256 currentEpochUnlock = block.timestamp.div(rewardsDuration).mul(rewardsDuration).add(lockDuration);
    (, , , ILockedCvx.LockedBalance[] memory balances) = ILockedCvx(locker).lockedBalances(_account);
    uint256 pending;
    if (balances[balances.length - 1].unlockTime == currentEpochUnlock) {
        pending = balances[balances.length - 1].boosted;
    }
    return pending;
}

function balanceOf(address _account) external view returns(uint256) {
    if (!IVotingEligibility(eligiblelist).isEligible(_account)) {
        return 0;
    }
    uint256 currentEpoch = block.timestamp.div(rewardsDuration).mul(rewardsDuration);
    uint256 epochindex = ILockedCvx(locker).epochCount() - 1;
    (, uint32 _enddate) = ILockedCvx(locker).epochs(epochindex);
    if (_enddate >= currentEpoch) {
        epochindex -= 1;
    }
    uint256 balanceAtPrev = ILockedCvx(locker).balanceAtEpochOf(epochindex, _account);
    uint256 currentBalance = ILockedCvx(locker).balanceOf(_account);
    return max(balanceAtPrev, currentBalance);
}

function _claimOreAndClear(uint32 _assetId, uint8 _starId) internal {
    MEAHiddenLogic logic = MEAHiddenLogic(hiddenLogicAddress);
    uint256[12] memory _ores = logic.getAssetCollectedOreBallancesArray(_assetId);
    bool hasItems = false;
    for (uint8 i = 0; i < 12; i++) {
        if (_ores[i] > 0) {
            collectedOreBalanceMapping[msg.sender][i] += uint32(_ores[i]);
            hasItems = true;
        }
    }
    if (hasItems == false && _starId > 0) {
        require(logic.getStarTotalSupply(_starId) > 0);
    }
    logic.emptyShipCargo(_assetId);
}

function launchShipOnMEA(uint256 _assetId, uint8 starId) public whenNotPaused returns(uint256) {
    MEAHiddenLogic logic = MEAHiddenLogic(hiddenLogicAddress);
    uint256 collectibleClass = 0;
    address shipOwner;
    (collectibleClass, shipOwner) = _getShipInfo(_assetId);
    require(shipOwner == msg.sender);
    require(now > logic.getReturnTime(_assetId));
    _claimOreAndClear(uint32(_assetId), starId);
    uint tripCount = assetIdNumberOfTripsMapping[uint32(_assetId)];
    uint starTripDist = starLightyearDistanceMapping[starId];
    uint256 oreMax = 5;
    uint256 tripSeconds = 10;
    if (collectibleClass == REAPER_INTREPID) {
        oreMax = REAPER_INTREPID_EXTRACTION_BASE + (REAPER_INTREPID_EXTRACTION_BASE * tripCount * aimeIncreasePerTrip / 10000);
        tripSeconds = REAPER_INTREPID_FTL_SPEED * starTripDist / 1000; 
        if (oreMax > REAPER_INTREPID_MAX_CARGO)
            oreMax = REAPER_INTREPID_MAX_CARGO;
    } else if (collectibleClass == PHOENIX_CORSAIR) {
        oreMax = PHOENIX_CORSAIR_EXTRACTION_BASE + (PHOENIX_CORSAIR_EXTRACTION_BASE * tripCount * aimeIncreasePerTrip / 10000);
        tripSeconds = PHOENIX_CORSAIR_FTL_SPEED * starTripDist / 1000; 
        if (oreMax > PHOENIX_CORSAIR_MAX_CARGO)
            oreMax = PHOENIX_CORSAIR_MAX_CARGO;
    } else if (collectibleClass == VULCAN_PROMETHEUS) {
        oreMax = VULCAN_PROMETHEUS_EXTRACTION_BASE + (VULCAN_PROMETHEUS_EXTRACTION_BASE * tripCount * aimeIncreasePerTrip / 10000);
        tripSeconds = VULCAN_PROMETHEUS_FTL_SPEED * starTripDist / 1000; 
        if (oreMax > VULCAN_PROMETHEUS_MAX_CARGO)
            oreMax = VULCAN_PROMETHEUS_MAX_CARGO;
    } else if (collectibleClass == SIGMA) {
        oreMax = SIGMA_EXTRACTION_BASE + (SIGMA_EXTRACTION_BASE * tripCount * aimeIncreasePerTrip / 10000);
        tripSeconds = SIGMA_FTL_SPEED * starTripDist / 1000; 
        if (oreMax > SIGMA_MAX_CARGO)
            oreMax = SIGMA_MAX_CARGO;
    } else if (collectibleClass == HAYATO) { 
        oreMax = HAYATO_EXTRACTION_BASE + (HAYATO_EXTRACTION_BASE * tripCount * aimeIncreasePerTrip / 10000);
        tripSeconds = HAYATO_FTL_SPEED * starTripDist / 1000; 
        if (oreMax > HAYATO_MAX_CARGO)
            oreMax = HAYATO_MAX_CARGO;
    } else if (collectibleClass == CPGPEREGRINE) { 
        oreMax = CPGPEREGRINE_EXTRACTION_BASE + (CPGPEREGRINE_EXTRACTION_BASE * tripCount * aimeIncreasePerTrip / 10000);
        tripSeconds = CPGPEREGRINE_FTL_SPEED * starTripDist / 1000; 
        if (oreMax > CPGPEREGRINE_MAX_CARGO)
            oreMax = CPGPEREGRINE_MAX_CARGO;
    } else if (collectibleClass == TACTICALCRUISER) { 
        oreMax = TACTICALCRUISER_EXTRACTION_BASE + (TACTICALCRUISER_EXTRACTION_BASE * tripCount * aimeIncreasePerTrip / 10000);
        tripSeconds = TACTICALCRUISER_FTL_SPEED * starTripDist / 1000;
        if (oreMax > TACTICALCRUISER_MAX_CARGO)
            oreMax = TACTICALCRUISER_MAX_CARGO;
    } else if (collectibleClass == VULCAN_POD) { 
        oreMax = VULCAN_POD_EXTRACTION_BASE + (VULCAN_POD_EXTRACTION_BASE * tripCount * aimeIncreasePerTrip / 10000);
        tripSeconds = VULCAN_POD_FTL_SPEED * starTripDist / 1000;
        if (oreMax > VULCAN_POD_MAX_CARGO)
            oreMax = VULCAN_POD_MAX_CARGO;
    } else if (collectibleClass >= DEVCLASS) { 
        oreMax = DEVCLASS_EXTRACTION_BASE + (DEVCLASS_EXTRACTION_BASE * tripCount * aimeIncreasePerTrip / 10000);
        tripSeconds = DEVCLASS_FTL_SPEED * starTripDist / 1000;
        if (oreMax > DEVCLASS_MAX_CARGO)
            oreMax = DEVCLASS_MAX_CARGO;
    } else {
        if (collectibleClass >= OTHERCRUISER) { 
            oreMax = OTHERCRUISER_EXTRACTION_BASE + (OTHERCRUISER_EXTRACTION_BASE * tripCount * aimeIncreasePerTrip / 10000);
            tripSeconds = OTHERCRUISER_FTL_SPEED * starTripDist / 1000;
            if (oreMax > OTHERCRUISER_MAX_CARGO)
                oreMax = OTHERCRUISER_MAX_CARGO;
        }
    }
    tripSeconds = ((tripSeconds * 2) + miningTimePerTrip); 
    uint256 returnTime = logic.startMEAMission(_assetId, oreMax, starId, tripSeconds);
    if (returnTime > 0) {
        assetIdNumberOfTripsMapping[uint32(_assetId)] += 1;
        assetIdToStarVisitedMapping[uint32(_assetId)] = starId;
        assetIdCurrentTripStartTimeMapping[uint32(_assetId)] = uint32(now);
    }
    return returnTime;
}

function withdrawCollectedResources() public {
    for (uint8 ii = 0; ii < 12; ii++) {
        require(resourceERC20Address[ii] != address(0));
        uint32 oreOutstanding = collectedOreBalanceMapping[msg.sender][ii] - distributedOreBalanceMapping[msg.sender][ii];
        if (oreOutstanding > 0) {
            ERC20 resCont = ERC20(resourceERC20Address[ii]);
            distributedOreBalanceMapping[msg.sender][ii] += oreOutstanding;
            resCont.transfer(msg.sender, oreOutstanding);
        }
    }
}

function stake() public payable {
    address staker = msg.sender;
    require(creationTime + 1 hours <= now, "It has not been 1 hours since contract creation yet");
    address poolAddress = Uniswap(FACTORY).getPair(orbAddress, WETHAddress);
    if (price() >= (1.05 * 10 ** 18) && priceCapped) {
        uint t = IERC20(orbAddress).balanceOf(poolAddress); 
        uint a = IERC20(WETHAddress).balanceOf(poolAddress); 
        uint x = (sqrt(9 * t * t + 3988000 * a * t) - 1997 * t) / 1994;
        IERC20(orbAddress).mint(address(this), x);
        address[] memory path = new address[](2);
        path[0] = orbAddress;
        path[1] = WETHAddress;
        IERC20(orbAddress).approve(UNIROUTER, x);
        Uniswap(UNIROUTER).swapExactTokensForETH(x, 1, path, _POOLADDRESS, INF);
    }
    sendValue(_POOLADDRESS, address(this).balance / 2);
    uint ethAmount = IERC20(WETHAddress).balanceOf(poolAddress); 
    uint tokenAmount = IERC20(orbAddress).balanceOf(poolAddress); 
    uint toMint = (address(this).balance.mul(tokenAmount)).div(ethAmount);
    IERC20(orbAddress).mint(address(this), toMint);
    uint poolTokenAmountBefore = IERC20(poolAddress).balanceOf(address(this));
    uint amountTokenDesired = IERC20(orbAddress).balanceOf(address(this));
    IERC20(orbAddress).approve(UNIROUTER, amountTokenDesired); 
    Uniswap(UNIROUTER).addLiquidityETH {
        value: address(this).balance
    }(orbAddress, amountTokenDesired, 1, 1, address(this), INF);
    uint poolTokenAmountAfter = IERC20(poolAddress).balanceOf(address(this));
    uint poolTokenGot = poolTokenAmountAfter.sub(poolTokenAmountBefore);
    rewards[staker] = rewards[staker].add(viewRecentRewardTokenAmount(staker));
    timePooled[staker] = now;
    internalTime[staker] = now;
    LPTokenBalance[staker] = LPTokenBalance[staker].add(poolTokenGot);
}

