function min(uint a, uint b) pure internal returns(uint) {
    if (a <= b) return a;
    return b;
}

function getAvailableReward(address _staker) view public returns(uint) {
    Staker storage staker = stakerMap[_staker];
    Reward storage reward = rewardLevels[staker.rewardLevel];
    if (staker.balance == 0 || staker.lastClaim.add(86400) > now) {
        return 0;
    }
    uint unclaimed = 0;
    uint periodEnd = 9999999999;
    for (uint i = reward.rewardEpochStart.length; i > 0; i--) {
        uint start = staker.stakingSince.add(reward.rewardEpochStart[i.sub(1)]);
        if (start >= now) {
            continue;
        }
        uint length = min(now, periodEnd).sub(max(start, staker.lastClaim));
        unclaimed = unclaimed.add(reward.rewardAmounts[i.sub(1)].mul(length).div(31622400));
        if (staker.lastClaim >= start) {
            break;
        }
        periodEnd = start;
    }
    return unclaimed;
}

function claimGrant(bytes32 _key) {
    bytes32 hashedKey = sha3(_key);
    require(!claimed[hashedKey]);
    claimed[hashedKey] = true;
    uint amount = grants[hashedKey];
    require(amount > 0);
    require(msg.sender.send(amount));
    LogGrantClaimed(hashedKey, amount);
}

function distributeAirdrop(address[] addresses, uint[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e8);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        emit Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function sellTokens() public saleIsOn payable {
    owner.transfer(msg.value);
    uint price = 526;
    if (now < start + (period * 1 days).div(2)) {
        price = 1052;
    } else if (now >= start + (period * 1 days).div(2) && now < start + (period * 1 days).div(4).mul(3)) {
        price = 751;
    } else if (now >= start + (period * 1 days).div(4).mul(3) && now < start + (period * 1 days)) {
        price = 657;
    }
    uint tokens = msg.value.mul(price);
    tokenReward.transfer(msg.sender, tokens);
}

