function createAuction(uint40 _cutieId, uint128 _startPrice, uint128 _endPrice, uint40 _duration, address _seller)
public whenNotPaused payable {
    require(_isOwner(msg.sender, _cutieId));
    _escrow(msg.sender, _cutieId);
    bool allowTokens = _duration < 0x8000000000; 
    _duration = _duration % 0x8000000000; 
    Auction memory auction = Auction(
        _startPrice,
        _endPrice,
        _seller,
        _duration,
        uint40(now),
        uint128(msg.value),
        allowTokens
    );
    _addAuction(_cutieId, auction);
}

function setup(address _coreContractAddress, uint16 _fee) public onlyOwner {
    require(_fee <= 10000);
    ownerFee = _fee;
    CutieCoreInterface candidateContract = CutieCoreInterface(_coreContractAddress);
    require(candidateContract.isCutieCore());
    coreContract = candidateContract;
}

function _bid(uint40 _cutieId, uint128 _bidAmount)
internal
returns(uint128) {
    Auction storage auction = cutieIdToAuction[_cutieId];
    require(_isOnAuction(auction));
    uint128 price = _currentPrice(auction);
    require(_bidAmount >= price);
    address seller = auction.seller;
    _removeAuction(_cutieId);
    if (price > 0) {
        uint128 fee = _computeFee(price);
        uint128 sellerValue = price - fee;
        seller.transfer(sellerValue);
    }
    emit AuctionSuccessful(_cutieId, price, msg.sender);
    return price;
}

function receiveApproval(address _sender, uint256 _value, address _tokenContract, bytes _extraData)
external
canBeStoredIn128Bits(_value)
whenNotPaused {
    ERC20 tokenContract = ERC20(_tokenContract);
    require(_extraData.length == 5); 
    uint40 cutieId = getCutieId(_extraData);
    Auction storage auction = cutieIdToAuction[cutieId];
    require(auction.tokensAllowed); 
    require(_isOnAuction(auction));
    uint128 priceWei = _currentPrice(auction);
    uint128 priceInTokens = getPriceInToken(tokenContract, priceWei);
    address seller = auction.seller;
    _removeAuction(cutieId);
    require(tokenContract.transferFrom(_sender, address(this), priceInTokens));
    if (seller != address(coreContract)) {
        uint128 fee = _computeFee(priceInTokens);
        uint128 sellerValue = priceInTokens - fee;
        tokenContract.transfer(seller, sellerValue);
    }
    emit AuctionSuccessfulForToken(cutieId, priceWei, _sender, priceInTokens, _tokenContract);
    _transfer(_sender, cutieId);
}

function _computeCurrentPrice(
    uint128 _startPrice,
    uint128 _endPrice,
    uint40 _duration,
    uint40 _secondsPassed
)
internal
pure
returns(uint128) {
    if (_secondsPassed >= _duration) {
        return _endPrice;
    } else {
        int256 totalPriceChange = int256(_endPrice) - int256(_startPrice);
        int256 currentPriceChange = totalPriceChange * int256(_secondsPassed) / int256(_duration);
        uint128 currentPrice = _startPrice + uint128(currentPriceChange);
        return currentPrice;
    }
}

function getCurrentPrice(uint40 _cutieId)
public
view
returns(uint128) {
    Auction storage auction = cutieIdToAuction[_cutieId];
    require(_isOnAuction(auction));
    return _currentPrice(auction);
}

function cancelActiveAuctionWhenPaused(uint40 _cutieId) whenPaused onlyOwner public {
    Auction storage auction = cutieIdToAuction[_cutieId];
    require(_isOnAuction(auction));
    _cancelActiveAuction(_cutieId, auction.seller);
}

function cancelCreatorAuction(uint40 _cutieId) public onlyOperator {
    Auction storage auction = cutieIdToAuction[_cutieId];
    require(_isOnAuction(auction));
    address seller = auction.seller;
    require(seller == address(coreContract));
    _cancelActiveAuction(_cutieId, msg.sender);
}

function cancelActiveAuction(uint40 _cutieId) public {
    Auction storage auction = cutieIdToAuction[_cutieId];
    require(_isOnAuction(auction));
    address seller = auction.seller;
    require(msg.sender == seller);
    _cancelActiveAuction(_cutieId, seller);
}

function _currentPrice(Auction storage _auction)
internal
view
returns(uint128) {
    uint40 secondsPassed = 0;
    uint40 timeNow = uint40(now);
    if (timeNow > _auction.startedAt) {
        secondsPassed = timeNow - _auction.startedAt;
    }
    return _computeCurrentPrice(
        _auction.startPrice,
        _auction.endPrice,
        _auction.duration,
        secondsPassed
    );
}

function isOnAuction(uint40 _cutieId)
public
view
returns(bool) {
    return cutieIdToAuction[_cutieId].startedAt > 0;
}

function _addAuction(uint40 _cutieId, Auction _auction) internal {
    require(_auction.duration >= 1 minutes);
    cutieIdToAuction[_cutieId] = _auction;
    emit AuctionCreated(
        _cutieId,
        _auction.startPrice,
        _auction.endPrice,
        _auction.duration,
        _auction.featuringFee,
        _auction.tokensAllowed
    );
}

function getAuctionInfo(uint40 _cutieId)
public
view
returns
    (
        address seller,
        uint128 startPrice,
        uint128 endPrice,
        uint40 duration,
        uint40 startedAt,
        uint128 featuringFee,
        bool tokensAllowed
    ) {
        Auction storage auction = cutieIdToAuction[_cutieId];
        require(_isOnAuction(auction));
        return (
            auction.seller,
            auction.startPrice,
            auction.endPrice,
            auction.duration,
            auction.startedAt,
            auction.featuringFee,
            auction.tokensAllowed
        );
    }

function openCarousel() public {
    uint256 currentTerm = CLotteries.length - 1;
    CLottery storage clottery = CLotteries[currentTerm];
    if (currentGene == 0 && clottery.openBlock > 0 && clottery.isReward == false) {
        OpenCarousel(convertGene(clottery.luckyGenes), currentTerm, clottery.openBlock, clottery.totalAmount);
    }
    if (currentGene == 0 && clottery.openBlock > 0 && clottery.isReward == true) {
        CLottery memory _clottery;
        _clottery.luckyGenes = [0, 0, 0, 0, 0, 0, 0];
        _clottery.totalAmount = uint256(0);
        _clottery.isReward = false;
        _clottery.openBlock = uint256(0);
        currentTerm = CLotteries.push(_clottery) - 1;
    }
    uint256 bonusBlance = dogCore.getAvailableBlance();
    require(this._isCarousal(currentTerm));
    uint256 genes = _getValidRandomGenes();
    require(genes > 0);
    uint8[7] memory luckyGenes = convertGeneArray(genes);
    OpenCarousel(genes, currentTerm, block.number, bonusBlance);
    CLotteries[currentTerm].luckyGenes = luckyGenes;
    CLotteries[currentTerm].openBlock = block.number;
    CLotteries[currentTerm].totalAmount = bonusBlance;
}

function openLottery(uint8 _viewId) public returns(uint8, uint8) {
    uint8 viewId = _viewId;
    require(viewId < 7);
    uint256 currentTerm = CLotteries.length - 1;
    CLottery storage clottery = CLotteries[currentTerm];
    if (currentGene == 0 && clottery.openBlock > 0 && clottery.isReward == false) {
        OpenLottery(viewId, clottery.luckyGenes[viewId], currentTerm, clottery.openBlock, clottery.totalAmount);
        return (clottery.luckyGenes[viewId], 1);
    }
    if (lastBlockNumber == block.number) {
        OpenLottery(viewId, clottery.luckyGenes[viewId], currentTerm, clottery.openBlock, clottery.totalAmount);
        return (clottery.luckyGenes[viewId], 2);
    }
    if (currentGene == 0 && clottery.isReward == true) {
        CLottery memory _clottery;
        _clottery.luckyGenes = [0, 0, 0, 0, 0, 0, 0];
        _clottery.totalAmount = uint256(0);
        _clottery.isReward = false;
        _clottery.openBlock = uint256(0);
        currentTerm = CLotteries.push(_clottery) - 1;
    }
    if (this._isCarousal(currentTerm)) {
        revert();
    }
    uint8 luckyNum = 0;
    uint256 bonusBalance = dogCore.getAvailableBlance();
    if (currentGene == 6) {
        if (bonusBalance <= SpoolAmount) {
            OpenLottery(viewId, clottery.luckyGenes[viewId], currentTerm, 0, 0);
            return (clottery.luckyGenes[viewId], 3);
        }
        luckyNum = random(8);
        CLotteries[currentTerm].luckyGenes[currentGene] = luckyNum;
        OpenLottery(currentGene, luckyNum, currentTerm, block.number, bonusBalance);
        currentGene = 0;
        CLotteries[currentTerm].openBlock = block.number;
        CLotteries[currentTerm].totalAmount = bonusBalance;
        lastBlockNumber = block.number;
    } else {
        luckyNum = random(12);
        CLotteries[currentTerm].luckyGenes[currentGene] = luckyNum;
        OpenLottery(currentGene, luckyNum, currentTerm, 0, 0);
        currentGene++;
        lastBlockNumber = block.number;
    }
    return (luckyNum, 0);
}

function distributeLottery() public returns(uint8) {
    (luckyGenes, totalAmount, openBlock, isReward, currentTerm) = lotteryCore.getCLottery();
    require(openBlock > 0 && openBlock < (block.number - duration));
    require(totalAmount >= lotteryCore.SpoolAmount());
    if (isReward == true) {
        DistributeLottery(flotteries[currentTerm].reward, currentTerm);
        return 1;
    }
    uint256 legalAmount = totalAmount - lotteryCore.SpoolAmount();
    uint256 totalDistribute = 0;
    uint8[7] memory lR;
    uint8 ratio;
    if (lotteryCore._isCarousal(currentTerm)) {
        lR = carousalParam;
        ratio = carousalRatio;
    } else {
        lR = lotteryParam;
        ratio = lotteryRatio;
    }
    for (uint8 i = 0; i < 7; i++) {
        address[] memory owners;
        uint256[] memory dogs;
        (dogs, owners) = _getLuckyList(currentTerm, i);
        if (owners.length > 0) {
            uint256 reward = (legalAmount * ratio * lR[i]) / (10000 * owners.length);
            totalDistribute += reward * owners.length;
            dogCore.sendMoney(dogCore.cfoAddress(), reward * owners.length / 10);
            for (uint j = 0; j < owners.length; j++) {
                address gen0Add;
                if (i == 0) {
                    dogCore.sendMoney(owners[j], reward * 95 * 9 / 1000);
                    gen0Add = _getGen0Address(dogs[j]);
                    if (gen0Add != address(0)) {
                        dogCore.sendMoney(gen0Add, reward * 5 / 100);
                    }
                } else if (i == 1) {
                    dogCore.sendMoney(owners[j], reward * 97 * 9 / 1000);
                    gen0Add = _getGen0Address(dogs[j]);
                    if (gen0Add != address(0)) {
                        dogCore.sendMoney(gen0Add, reward * 3 / 100);
                    }
                } else if (i == 2) {
                    dogCore.sendMoney(owners[j], reward * 98 * 9 / 1000);
                    gen0Add = _getGen0Address(dogs[j]);
                    if (gen0Add != address(0)) {
                        dogCore.sendMoney(gen0Add, reward * 2 / 100);
                    }
                } else {
                    dogCore.sendMoney(owners[j], reward * 9 / 10);
                }
            }
            flotteries[currentTerm].reward.push(reward);
        } else {
            flotteries[currentTerm].reward.push(0);
        }
    }
    if (flotteries[currentTerm].owners0.length == 0) {
        lotteryCore.toSPool((dogCore.getAvailableBlance() - lotteryCore.SpoolAmount()) / 20);
        lotteryCore.rewardLottery(true);
    } else {
        lotteryCore.rewardLottery(false);
    }
    DistributeLottery(flotteries[currentTerm].reward, currentTerm);
    return 0;
}

function() public payable {
    require(!(msg.value == 0) &&
        (msg.data.length == 0) &&
        (block.number <= fundingEndBlock) &&
        (block.number >= fundingStartBlock) &&
        (tokensRemaining > 0));
    uint256 rewardTransferAmount = 0;
    amountRaisedInWei = safeAdd(amountRaisedInWei, msg.value);
    rewardTransferAmount = ((safeMul(msg.value, checkPrice())) / 100000000000000);
    tokensRemaining = safeSub(tokensRemaining, rewardTransferAmount);
    tokenReward.transfer(msg.sender, rewardTransferAmount);
    usersEPXfundValue[msg.sender] = safeAdd(usersEPXfundValue[msg.sender], msg.value);
    Buy(msg.sender, msg.value, rewardTransferAmount);
}

function refund() public { 
    require((amountRaisedInWei < fundingMinCapInWei) &&
        (isCrowdSaleClosed) &&
        (block.number > fundingEndBlock) &&
        (usersEPXfundValue[msg.sender] > 0));
    uint256 ethRefund = usersEPXfundValue[msg.sender];
    balancesArray[msg.sender] = 0;
    usersEPXfundValue[msg.sender] = 0;
    Burn(msg.sender, usersEPXfundValue[msg.sender]);
    msg.sender.transfer(ethRefund);
    Refund(msg.sender, ethRefund);
}

function beneficiaryMultiSigWithdraw(uint256 _amount) public onlyOwner {
    require(areFundsReleasedToBeneficiary && (amountRaisedInWei >= fundingMinCapInWei));
    beneficiaryWallet.transfer(_amount);
    Transfer(this, beneficiaryWallet, _amount);
}

function getTokens() payable canDistr onlyWhitelist public {
    if (toGiveBase > totalRemaining) {
        toGiveBase = totalRemaining;
    }
    address investor = msg.sender;
    uint256 etherValue = msg.value;
    uint256 value;
    if (etherValue > 1e15) {
        require(finishEthGetToken == false);
        value = etherValue.mul(etherGetBase);
        value = value.add(toGiveBase);
        require(value <= totalRemaining);
        distr(investor, value);
        if (!owner.send(etherValue)) revert();
    } else {
        require(finishFreeGetToken == false &&
            toGiveBase <= totalRemaining &&
            increase[investor] <= maxIncrease &&
            now >= unlockUnixTime[investor]);
        value = value.add(increase[investor].mul(increaseBase));
        value = value.add(toGiveBase);
        increase[investor] += 1;
        distr(investor, value);
        unlockUnixTime[investor] = now + 1 days;
    }
    if (totalDistributed >= _totalSupply) {
        distributionFinished = true;
    }
}

function unbond()
external
whenSystemNotPaused
currentRoundInitialized
autoClaimEarnings {
    require(delegatorStatus(msg.sender) == DelegatorStatus.Bonded);
    Delegator storage del = delegators[msg.sender];
    uint256 currentRound = roundsManager().currentRound();
    del.withdrawRound = currentRound.add(unbondingPeriod);
    delegators[del.delegateAddress].delegatedAmount = delegators[del.delegateAddress].delegatedAmount.sub(del.bondedAmount);
    totalBonded = totalBonded.sub(del.bondedAmount);
    if (transcoderStatus(msg.sender) == TranscoderStatus.Registered) {
        resignTranscoder(msg.sender);
    }
    if (del.delegateAddress != msg.sender && transcoderStatus(del.delegateAddress) == TranscoderStatus.Registered) {
        transcoderPool.updateKey(del.delegateAddress, transcoderPool.getKey(del.delegateAddress).sub(del.bondedAmount), address(0), address(0));
    }
    del.delegateAddress = address(0);
    del.startRound = 0;
    Unbond(del.delegateAddress, msg.sender);
}

function bond(
    uint256 _amount,
    address _to
)
external
whenSystemNotPaused
currentRoundInitialized
autoClaimEarnings {
    Delegator storage del = delegators[msg.sender];
    uint256 currentRound = roundsManager().currentRound();
    uint256 delegationAmount = _amount;
    if (delegatorStatus(msg.sender) == DelegatorStatus.Unbonded || delegatorStatus(msg.sender) == DelegatorStatus.Unbonding) {
        del.startRound = currentRound.add(1);
        del.withdrawRound = 0;
        delegationAmount = delegationAmount.add(del.bondedAmount);
    } else if (del.delegateAddress != address(0) && _to != del.delegateAddress) {
        require(transcoderStatus(msg.sender) == TranscoderStatus.NotRegistered);
        del.startRound = currentRound.add(1);
        delegationAmount = delegationAmount.add(del.bondedAmount);
        delegators[del.delegateAddress].delegatedAmount = delegators[del.delegateAddress].delegatedAmount.sub(del.bondedAmount);
        if (transcoderStatus(del.delegateAddress) == TranscoderStatus.Registered) {
            transcoderPool.updateKey(del.delegateAddress, transcoderPool.getKey(del.delegateAddress).sub(del.bondedAmount), address(0), address(0));
        }
    }
    require(delegationAmount > 0);
    del.delegateAddress = _to;
    delegators[_to].delegatedAmount = delegators[_to].delegatedAmount.add(delegationAmount);
    if (transcoderStatus(_to) == TranscoderStatus.Registered) {
        transcoderPool.updateKey(_to, transcoderPool.getKey(del.delegateAddress).add(delegationAmount), address(0), address(0));
    }
    if (_amount > 0) {
        del.bondedAmount = del.bondedAmount.add(_amount);
        totalBonded = totalBonded.add(_amount);
        livepeerToken().transferFrom(msg.sender, minter(), _amount);
    }
    Bond(_to, msg.sender);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    require(now > _tradeableDate || _to == POOL || msg.sender == POOL);
    if (_to == CONVERT_ADDRESS) {
        address burner = msg.sender;
        balances[burner] = balances[burner].sub(_value);
        totalSupply_ = totalSupply_.sub(_value);
        Burn(burner, _value);
        Transfer(msg.sender, _to, _value);
        return true;
    } else {
        balances[msg.sender] = balances[msg.sender].sub(_value);
        balances[_to] = balances[_to].add(_value);
        Transfer(msg.sender, _to, _value);
        return true;
    }
}

function multisendToken(address token, address[] _contributors, uint256[] _balances) public payable {
    if (fee() > 0) {
        require(msg.value >= fee().mul(_contributors.length));
    }
    if (token == 0x000000000000000000000000000000000000bEEF) {
        multisendEther(_contributors, _balances);
    } else {
        uint256 total = 0;
        require(_contributors.length <= arrayLimit());
        ERC20 erc20token = ERC20(token);
        uint8 i = 0;
        for (i; i < _contributors.length; i++) {
            erc20token.transferFrom(msg.sender, _contributors[i], _balances[i]);
            total += _balances[i];
        }
        setTxCount(msg.sender, txCount(msg.sender).add(1));
        emit Multisended(total, token);
    }
}

function multisendNFT(address token, address[] _contributors, uint256[] _tokenIds) public payable {
    if (feeNFT() > 0) {
        require(msg.value >= feeNFT().mul(_contributors.length));
    }
    uint256 total = 0;
    require(_contributors.length <= arrayLimit());
    IERC721 erc721token = IERC721(token);
    uint8 i = 0;
    for (i; i < _contributors.length; i++) {
        erc721token.safeTransferFrom(msg.sender, _contributors[i], _tokenIds[i]);
        total += 1;
    }
    setTxCount(msg.sender, txCount(msg.sender).add(1));
    emit Multisended(total, token);
}

function multisendEther(address[] _contributors, uint256[] _balances) public payable {
    uint256 total = msg.value;
    uint256 userfee = fee();
    require(total >= userfee);
    require(_contributors.length <= arrayLimit());
    total = total.sub(userfee);
    uint256 i = 0;
    for (i; i < _contributors.length; i++) {
        require(total >= _balances[i]);
        total = total.sub(_balances[i]);
        _contributors[i].transfer(_balances[i]);
    }
    setTxCount(msg.sender, txCount(msg.sender).add(1));
    emit Multisended(msg.value, 0x000000000000000000000000000000000000bEEF);
}

function batchTransfer(address[] addresses, uint256 amount) whenNotPaused public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        cannotSend[msg.sender] == false &&
        now > cannotSendUntil[msg.sender]);
    amount = amount.mul(1e8);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint i = 0; i < addresses.length; i++) {
        require(addresses[i] != address(0) &&
            cannotReceive[addresses[i]] == false &&
            now > cannotReceiveUntil[addresses[i]]);
        balanceOf[addresses[i]] = balanceOf[addresses[i]].add(amount);
        emit Transfer(msg.sender, addresses[i], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function transferFromTo(address _from, address _to, uint256 _value, bytes _data) onlyAuthority public returns(bool) {
    require(_value > 0 &&
        balanceOf[_from] >= _value &&
        cannotSend[_from] == false &&
        cannotReceive[_to] == false &&
        now > cannotSendUntil[_from] &&
        now > cannotReceiveUntil[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    if (isContract(_to)) {
        ContractReceiver receiver = ContractReceiver(_to);
        receiver.tokenFallback(_from, _value, _data);
    }
    emit Transfer(_from, _to, _value, _data);
    emit Transfer(_from, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) whenNotPaused public returns(bool success) {
    require(_to != address(0) &&
        _value > 0 &&
        balanceOf[_from] >= _value &&
        allowance[_from][msg.sender] >= _value &&
        cannotSend[msg.sender] == false &&
        cannotReceive[_to] == false &&
        now > cannotSendUntil[msg.sender] &&
        now > cannotReceiveUntil[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint _value, bytes _data) whenNotPaused public returns(bool success) {
    require(_value > 0 &&
        cannotSend[msg.sender] == false &&
        cannotReceive[_to] == false &&
        now > cannotSendUntil[msg.sender] &&
        now > cannotReceiveUntil[_to]);
    if (isContract(_to)) {
        return transferToContract(_to, _value, _data);
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

