function _attack(uint _heroId, uint _genes, uint _heroStrength, uint _heroCurrentHealth) internal {
    Monster storage monster = heroIdToMonster[_heroId];
    uint8 currentLevel = monster.level;
    uint heroPower;
    (heroPower, , , , ) = edCoreContract.getHeroPower(_genes, dungeonDifficulty);
    uint damageByMonster;
    uint damageByHero;
    if (now > monster.creationTime + monsterFleeTime) {
        damageByMonster = currentLevel + monsterStrength;
    } else {
        if (currentLevel >= 2) {
            damageByMonster = _getRandomNumber(currentLevel / 2);
        }
    }
    if (damageByMonster >= _heroCurrentHealth) {
        heroIdToHealth[_heroId] = 0;
        uint addToJackpot = entranceFee - heroIdToRefundedFee[_heroId];
        jackpot += addToJackpot;
        entranceFeePool -= addToJackpot;
        assert(addToJackpot <= entranceFee);
    } else {
        heroIdToHealth[_heroId] -= damageByMonster;
        if (now > monster.creationTime + monsterFleeTime) {
            currentLevel++;
            heroIdToMonster[_heroId] = Monster(uint64(monster.creationTime + monsterFleeTime),
                currentLevel, currentLevel * monsterHealth, currentLevel * monsterHealth);
            monster = heroIdToMonster[_heroId];
        }
        damageByHero = (_heroStrength * 1e9 + heroPower * 1e9 / (10 * (1 + _getRandomNumber(5)))) / tx.gasprice;
        bool isMonsterDefeated = damageByHero >= monster.health;
        uint rewards;
        if (isMonsterDefeated) {
            uint8 newLevel = currentLevel + 1;
            heroIdToMonster[_heroId] = Monster(uint64(now), newLevel, newLevel * monsterHealth, newLevel * monsterHealth);
            monster = heroIdToMonster[_heroId];
            if (currentLevel == checkpointLevel) {
                rewards = entranceFee / 2;
                heroIdToRefundedFee[_heroId] += rewards;
                entranceFeePool -= rewards;
            } else if (currentLevel == breakevenLevel) {
                rewards = entranceFee / 2;
                heroIdToRefundedFee[_heroId] += rewards;
                entranceFeePool -= rewards;
            } else if (currentLevel == jackpotLevel) {
                rewards = jackpot / 2;
                jackpot -= rewards;
            }
            msg.sender.transfer(rewards);
        } else {
            monster.health -= uint8(damageByHero);
        }
    }
    LogAttack(now, msg.sender, _heroId, currentLevel, damageByHero, damageByMonster, isMonsterDefeated, rewards);
}

function attack(uint _heroId) whenNotPaused onlyHumanAddress external payable {
    uint genes;
    address owner;
    (, , , genes, owner, , ) = edCoreContract.getHeroDetails(_heroId);
    require(msg.sender == owner);
    uint heroInitialHealth = (genes / (32 ** 12)) % 32 + 1;
    uint heroStrength = (genes / (32 ** 8)) % 32 + 1;
    Monster memory monster = heroIdToMonster[_heroId];
    uint currentLevel = monster.level;
    uint heroCurrentHealth = heroIdToHealth[_heroId];
    bool dungeonRunEnded;
    if (currentLevel == 0) {
        require(msg.value >= entranceFee);
        entranceFeePool += entranceFee;
        heroIdToMonster[_heroId] = Monster(uint64(now), 1, monsterHealth, monsterHealth);
        monster = heroIdToMonster[_heroId];
        heroIdToHealth[_heroId] = heroInitialHealth;
        heroCurrentHealth = heroInitialHealth;
        if (msg.value > entranceFee) {
            msg.sender.transfer(msg.value - entranceFee);
        }
    } else {
        require(heroCurrentHealth > 0);
        dungeonRunEnded = now > monster.creationTime + monsterFleeTime * 2 ||
            (monster.health == monster.initialHealth && now > monster.creationTime + monsterFleeTime);
        if (dungeonRunEnded) {
            uint addToJackpot = entranceFee - heroIdToRefundedFee[_heroId];
            jackpot += addToJackpot;
            entranceFeePool -= addToJackpot;
            assert(addToJackpot <= entranceFee);
        }
        msg.sender.transfer(msg.value);
    }
    if (!dungeonRunEnded) {
        _attack(_heroId, genes, heroStrength, heroCurrentHealth);
    }
}

function doDistributionRange(uint256 start, address[] contributors,
    uint256[] contributorExpectedTokens) public {
    require(contributors.length == contributorExpectedTokens.length);
    uint256 tokensTransferredSoFar = tokensTransferred;
    uint256 end = start + contributors.length;
    State _state = state;
    for (uint256 i = start; i < end; ++i) {
        address contributor = contributors[i];
        uint256 expectedTokens = contributorExpectedTokens[i];
        require(contributionHashes[i] == keccak256(contributor, expectedTokens));
        contributionHashes[i] = 0x00000000000000000000000000000000;
        uint256 numTokens = _numTokensForContributor(expectedTokens, tokensTransferredSoFar, _state);
        tokensTransferredSoFar += numTokens;
        require(tokenContract.transfer(contributor, numTokens));
    }
    tokensTransferred = tokensTransferredSoFar;
    if (tokensTransferred == actualTotalTokens) {
        state = State.Done;
    }
}

function withdrawToBuyer(IERC20Token _token, address[] _to) public ownerOnly {
    require(_to.length > 0 && _to.length < 10000);
    for (uint16 i = 0; i < _to.length; i++) {
        if (pendingBalanceMap[_to[i]] > 0) {
            assert(_token.transfer(_to[i], pendingBalanceMap[_to[i]]));
            withdrawYOOMap[_to[i]] = safeAdd(withdrawYOOMap[_to[i]], pendingBalanceMap[_to[i]]);
            pendingBalanceMap[_to[i]] = 0;
        }
    }
}

function initLeftICOTokens() public ownerOnly {
    require(!hasInitLeftICOTokens);
    leftICOTokens = yoobaTokenAddress.balanceOf(this);
    hasInitLeftICOTokens = true;
}

function refund(address[] _to) public ownerOnly {
    require(_to.length > 0 && _to.length < 10000);
    for (uint16 i = 0; i < _to.length; i++) {
        if (pendingBalanceMap[_to[i]] > 0 && withdrawYOOMap[_to[i]] == 0 && totalBuyerETHMap[_to[i]] > 0 && totalBuyMap[_to[i]] > 0) {
            if (totalBuyerETHMap[_to[i]] <= this.balance) {
                _to[i].transfer(totalBuyerETHMap[_to[i]]);
                tatalEthFromBuyer = tatalEthFromBuyer - totalBuyerETHMap[_to[i]];
                leftICOTokens = leftICOTokens + pendingBalanceMap[_to[i]];
                totalBuyerETHMap[_to[i]] = 0;
                pendingBalanceMap[_to[i]] = 0;
                totalBuyMap[_to[i]] = 0;
            }
        }
    }
}

function buyToken() internal {
    require(!stopped && now >= startICOTime && now <= endICOTime);
    require(msg.value >= 0.1 ether && msg.value <= 100 ether);
    uint256 dayNum = ((now - startICOTime) / 1 days) + 1;
    daysnumber = dayNum;
    assert(daySellMap[dayNum] <= dayLimit);
    uint256 amount = 0;
    if (now < (startICOTime + 1 weeks) && leftICOTokens > milestone1) {
        if (msg.value * 320000 <= (leftICOTokens - milestone1)) {
            amount = msg.value * 320000;
        } else {
            uint256 priceOneEther1 = (leftICOTokens - milestone1) / 320000;
            amount = (msg.value - priceOneEther1) * 250000 + priceOneEther1 * 320000;
        }
    } else {
        if (leftICOTokens > milestone2) {
            if (msg.value * 250000 <= (leftICOTokens - milestone2)) {
                amount = msg.value * 250000;
            } else {
                uint256 priceOneEther2 = (leftICOTokens - milestone2) / 250000;
                amount = (msg.value - priceOneEther2) * 180000 + priceOneEther2 * 250000;
            }
        } else {
            assert(msg.value * 180000 <= leftICOTokens);
            if ((leftICOTokens - msg.value * 180000) < 18000 && msg.value * 180000 <= 100 * 180000 * (10 ** 18)) {
                amount = leftICOTokens;
            } else {
                amount = msg.value * 180000;
            }
        }
    }
    if (amount >= 18000 * (10 ** 18) && amount <= 320000 * 100 * (10 ** 18)) {
        leftICOTokens = safeSub(leftICOTokens, amount);
        pendingBalanceMap[msg.sender] = safeAdd(pendingBalanceMap[msg.sender], amount);
        totalBuyMap[msg.sender] = safeAdd(totalBuyMap[msg.sender], amount);
        daySellMap[dayNum] += amount;
        totalBuyerETHMap[msg.sender] = safeAdd(totalBuyerETHMap[msg.sender], msg.value);
        tatalEthFromBuyer += msg.value;
        return;
    } else {
        revert();
    }
}

function joinMiniGame() public disableContract {
    require(now >= minigames[miniGameId].startTime && minigames[miniGameId].ended == false);
    PlayerData storage p = players[msg.sender];
    if (now <= minigames[miniGameId].endTime) {
        if (p.currentMiniGameId == miniGameId) {
            p.totalJoin = p.totalJoin + 1;
        } else {
            updateShareCrystal();
            p.currentMiniGameId = miniGameId;
            p.totalJoin = 1;
            p.miningWarRoundNumber = minigames[miniGameId].miningWarRoundNumber;
        }
        if (p.totalJoin <= 1) { 
            minigames[miniGameId].totalPlayer = minigames[miniGameId].totalPlayer + 1;
        }
        minigames[miniGameId].playerWin = msg.sender;
        minigames[miniGameId].endTime = minigames[miniGameId].endTime + MINI_GAME_ADD_TIME_DEFAULT;
        emit eventJoinMiniGame(p.totalJoin);
    } else {
        if (minigames[miniGameId].playerWin == 0x0) {
            updateShareCrystal();
            p.currentMiniGameId = miniGameId;
            p.lastMiniGameId = miniGameId;
            p.totalJoin = 1;
            p.miningWarRoundNumber = minigames[miniGameId].miningWarRoundNumber;
            minigames[miniGameId].playerWin = msg.sender;
        }
        endMiniGame();
    }
}

function claimCrystal() public {
    if (minigames[miniGameId].endTime < now) {
        endMiniGame();
    }
    updateShareCrystal();
    uint256 crystalBonus = players[msg.sender].win + players[msg.sender].share;
    MiningWarContract.addCrystal(msg.sender, crystalBonus);
    PlayerData storage p = players[msg.sender];
    p.win = 0;
    p.share = 0;
}

function updateShareCrystal() private {
    uint256 miningWarRoundNumber = getMiningWarRoundNumber();
    PlayerData storage p = players[msg.sender];
    if (p.miningWarRoundNumber != miningWarRoundNumber) {
        p.share = 0;
        p.win = 0;
    } else if (minigames[p.currentMiniGameId].ended == true && p.lastMiniGameId < p.currentMiniGameId && minigames[p.currentMiniGameId].miningWarRoundNumber == miningWarRoundNumber) {
        p.share = SafeMath.add(p.share, calculateShareCrystal(p.currentMiniGameId));
        p.lastMiniGameId = p.currentMiniGameId;
    }
}

function startMiniGame() private {
    uint256 miningWarRoundNumber = getMiningWarRoundNumber();
    require(minigames[miniGameId].ended == true);
    uint256 currentPrizeCrystal;
    if (noRoundMiniGame == 0) {
        currentPrizeCrystal = SafeMath.div(SafeMath.mul(MINI_GAME_PRIZE_CRYSTAL, MINI_GAME_BONUS), 100);
    } else {
        uint256 rate = 168 * MINI_GAME_BONUS;
        currentPrizeCrystal = SafeMath.div(SafeMath.mul(minigames[miniGameId].prizeCrystal, rate), 10000); 
    }
    uint256 startTime = now + MINI_GAME_BETWEEN_TIME;
    uint256 endTime = startTime + MINI_GAME_TIME_DEFAULT;
    noRoundMiniGame = noRoundMiniGame + 1;
    miniGameId = miniGameId + 1;
    minigames[miniGameId] = MiniGame(miningWarRoundNumber, false, currentPrizeCrystal, startTime, endTime, 0x0, 0);
}

function setupMiniGame(uint256 _miningWarRoundNumber, uint256 _miningWarDeadline) public {
    require(minigames[miniGameId].miningWarRoundNumber < _miningWarRoundNumber && msg.sender == miningWarContractAddress);
    minigames[miniGameId] = MiniGame(0, true, 0, 0, 0, 0x0, 0);
    noRoundMiniGame = 0;
    startMiniGame();
}

function endMiniGame() private {
    require(minigames[miniGameId].ended == false && (minigames[miniGameId].endTime <= now));
    uint256 crystalBonus = SafeMath.div(SafeMath.mul(minigames[miniGameId].prizeCrystal, 50), 100);
    if (minigames[miniGameId].playerWin != 0x0) {
        PlayerData storage p = players[minigames[miniGameId].playerWin];
        p.win = p.win + crystalBonus;
    }
    minigames[miniGameId].ended = true;
    emit eventEndMiniGame(minigames[miniGameId].playerWin, crystalBonus);
    startMiniGame();
}

function calculateShareCrystal(uint256 _miniGameId) public view returns(uint256 _share) {
    PlayerData memory p = players[msg.sender];
    if (p.lastMiniGameId >= p.currentMiniGameId && p.currentMiniGameId != 0) {
        _share = 0;
    } else {
        _share = SafeMath.div(SafeMath.div(SafeMath.mul(minigames[_miniGameId].prizeCrystal, 50), 100), minigames[_miniGameId].totalPlayer);
    }
}

function purchase() whenNotPaused payable public {
    require(!crowdsaleClosed);
    require(msg.value >= 0.01 ether);
    Step memory step = steps[currentStep];
    require(step.tokensSold < step.tokensForSale);
    uint sum = msg.value;
    uint amount = sum.mul(1 ether).div(step.priceTokenWei);
    uint retSum = 0;
    if (step.tokensSold.add(amount) > step.tokensForSale) {
        uint retAmount = step.tokensSold.add(amount).sub(step.tokensForSale);
        retSum = retAmount.mul(step.priceTokenWei).div(1 ether);
        amount = amount.sub(retAmount);
        sum = sum.sub(retSum);
    }
    steps[currentStep].tokensSold = step.tokensSold.add(amount);
    steps[currentStep].collectedWei = step.collectedWei.add(sum);
    beneficiary.transfer(sum.div(100).mul(16));
    beneficiary2.transfer(sum.sub(sum.div(100).mul(16)));
    token.mint(msg.sender, amount);
    if (retSum > 0) {
        msg.sender.transfer(retSum);
    }
    Purchase(msg.sender, amount, sum);
}

