}

function enlist(
    uint256 battleId,
    uint256 side,
    uint256 weaponId
) public {
    bool ownsV1 = weaponContractV1.ownerOf(weaponId) == msg.sender;
    bool ownsV2 = address(weaponContractV2) != address(0) &&
        weaponContractV2.ownerOf(weaponId) == msg.sender;
    require(ownsV1 || ownsV2, "must own weapon");
    uint256 endTimestamp = idToBattleInfo[battleId].endTimestamp;
    require(endTimestamp != 0, "battle must exist");
    require(block.timestamp < endTimestamp, "too late for battle");
    require(!battleIdToWeaponEnlisted[battleId][weaponId], "weapon in use");
    require(
        battleIdToWarriorInfo[battleId][msg.sender].side == 0,
        "warrior in battle"
    );
    require(
        side == ATTACKER_SIDE || side == DEFENDER_SIDE,
        "no bystanders!"
    );
    uint256 power = powerCalculator.calculatePower(weaponId);
    battleIdToWarriorInfo[battleId][msg.sender] = WarriorInfo(power, side);
    if (side == ATTACKER_SIDE) {
        idToBattleInfo[battleId].attackerPower += power;
    } else {
        idToBattleInfo[battleId].defenderPower += power;
    }
    idToBattleInfo[battleId].numWarriors++;
}

function finish(uint256 battleId) public {
    BattleInfo memory battleInfo = idToBattleInfo[battleId];
    require(battleInfo.endTimestamp != 0, "battle must exist");
    require(block.timestamp >= battleInfo.endTimestamp, "too early");
    require(!battleInfo.finished, "already finished");
    idToBattleInfo[battleId].finished = true;
    uint256 winner = battleInfo.attackerPower > battleInfo.defenderPower ?
        ATTACKER_SIDE :
        DEFENDER_SIDE;
    emit BattleFinished(
        battleId,
        winner,
        battleInfo.attackerPower,
        battleInfo.defenderPower,
        battleInfo.numWarriors
    );
    if (address(battleRewarder) != address(0)) {
        battleRewarder.battleFinished(battleId);
    }
}

function drop(address[] _recipients, uint256[] _amount)
external
onlyOwner returns(bool) {
    require(_recipients.length == _amount.length);
    for (uint i = 0; i < _recipients.length; i++) {
        require(_recipients[i] != address(0), "Address is zero address");
        require(individualCap >= airdropContribution[_recipients[i]].add(_amount[i]), "Exceding individual cap");
        require(token.balanceOf(address(this)) >= _amount[i], "No enoufgh tokens available");
        airdropContribution[_recipients[i]] = airdropContribution[_recipients[i]].add(_amount[i]);
        totalAlloctedToken = totalAlloctedToken.add(_amount[i]);
        token.transfer(_recipients[i], _amount[i]);
        emit Airdrop(_recipients[i], _amount[i]);
    }
    return true;
}

function add(MutableUint memory _original, uint256 _amount)
internal
pure
returns(MutableUint _transformed) {
    require((_original.pre + _amount) >= _original.pre);
    _transformed = _original;
    _transformed.post = _original.pre + _amount;
}

function advance_by(MutableTimestamp memory _original, uint256 _units)
internal
constant
returns(MutableTimestamp _transformed) {
    _transformed = _original;
    require(now >= _original.time.pre);
    uint256 _lapsed = now - _original.time.pre;
    _transformed.in_units = _lapsed / _units;
    uint256 _ticks = _transformed.in_units * _units;
    if (_transformed.in_units == 0) {
        _transformed.time.post = _original.time.pre;
    } else {
        _transformed.time = add(_transformed.time, _ticks);
    }
}

function updateDemurrageReporter() public {
    Types.MutableTimestamp memory payment_timestamp;
    payment_timestamp.time.pre = last_payment_timestamp;
    payment_timestamp = payment_timestamp.advance_by(1 days);
    uint256 _base;
    uint256 _rate;
    (_base, _rate, , ) = token_information().showDemurrageConfigs();
    culmulative_demurrage_collected += (payment_timestamp.in_units * last_demurrageable_balance * _rate) / _base;
    last_payment_timestamp = payment_timestamp.time.post;
    last_demurrageable_balance = getDemurrageableBalance();
}

function transferFrom(address _from, address _to, uint _value) public returns(bool ok) {
    require(_from != 0 && _to != 0 && _value > 0);
    require(allowed[_from][msg.sender] >= _value && balances[_from] >= _value);
    balances[_from] = safeSub(balances[_from], _value);
    balances[_to] = safeAdd(balances[_to], _value);
    allowed[_from][msg.sender] = safeSub(allowed[_from][msg.sender], _value);
    Transfer(_from, _to, _value);
    return true;
}

function assignToken(address _investor, uint256 _tokens) external {
    require(_investor != address(0) && _tokens > 0);
    require(_tokens <= balances[msg.sender]);
    balances[msg.sender] = safeSub(balances[msg.sender], _tokens);
    totalSupply = safeAdd(totalSupply, _tokens);
    if (msg.sender == walletAddresses[0]) {
        walletA[_investor] = safeAdd(walletA[_investor], _tokens);
    } else if (msg.sender == walletAddresses[1]) {
        walletB[_investor] = safeAdd(walletB[_investor], _tokens);
    } else if (msg.sender == walletAddresses[2]) {
        walletC[_investor] = safeAdd(walletC[_investor], _tokens);
    } else if (msg.sender == walletAddresses[5]) {
        walletF[_investor] = safeAdd(walletF[_investor], _tokens);
    } else if (msg.sender == walletAddresses[6]) {
        walletG[_investor] = safeAdd(walletG[_investor], _tokens);
    } else if (msg.sender == walletAddresses[7]) {
        walletH[_investor] = safeAdd(walletH[_investor], _tokens);
    } else {
        revert();
    }
}

