    if (bytes(idToUri[_tokenId]).length != 0) {
        delete idToUri[_tokenId];
    }
}

function catchMonster(address _player, uint32 _classId, string _name) isActive external payable returns(uint tokenId) {
    EtheremonDataBase data = EtheremonDataBase(dataContract);
    MonsterClassAcc memory class;
    (class.classId, class.price, class.returnPrice, class.total, class.catchable) = data.getMonsterClass(_classId);
    if (class.classId == 0) {
        revert();
    }
    if (class.catchable == false) {
        if (addressWhitelist[msg.sender] == false || classWhitelist[_classId] == false) {
            revert();
        }
    }
    uint price = class.price;
    if (class.total > 0)
        price += class.price * (class.total - 1) / priceIncreasingRatio;
    if (msg.value + gapFactor < price) {
        revert();
    }
    uint64 objId = data.addMonsterObj(_classId, _player, _name);
    uint8 value;
    seed = getRandom(_player, block.number - 1, seed, objId);
    for (uint i = 0; i < STAT_COUNT; i += 1) {
        value = uint8(seed % STAT_MAX) + data.getElementInArrayType(EtheremonEnum.ArrayType.STAT_START, uint64(_classId), i);
        data.addElementToArrayType(EtheremonEnum.ArrayType.STAT_BASE, objId, value);
    }
    emit Transfer(address(0), _player, objId);
    return objId;
}

function mintMonster(uint32 _classId, address _trainer, string _name) onlyModerators external returns(uint) {
    EtheremonDataBase data = EtheremonDataBase(dataContract);
    uint64 objId = data.addMonsterObj(_classId, _trainer, _name);
    uint8 value;
    seed = getRandom(_trainer, block.number - 1, seed, objId);
    for (uint i = 0; i < STAT_COUNT; i += 1) {
        value = uint8(seed % STAT_MAX) + data.getElementInArrayType(EtheremonEnum.ArrayType.STAT_START, uint64(_classId), i);
        data.addElementToArrayType(EtheremonEnum.ArrayType.STAT_BASE, objId, value);
    }
    emit Transfer(address(0), _trainer, objId);
    return objId;
}

function approve(address _approved, uint256 _tokenId) external {
    EtheremonDataBase data = EtheremonDataBase(dataContract);
    MonsterObjAcc memory obj;
    (obj.monsterId, obj.classId, obj.trainer, obj.exp, obj.createIndex, obj.lastClaimIndex, obj.createTime) = data.getMonsterObj(uint64(_tokenId));
    require(obj.trainer != address(0));
    _canOperate(obj.trainer);
    EtheremonBattle battle = EtheremonBattle(battleContract);
    EtheremonTradeInterface trade = EtheremonTradeInterface(tradeContract);
    if (battle.isOnBattle(obj.monsterId) || trade.isOnTrading(obj.monsterId))
        revert();
    require(_approved != obj.trainer);
    idToApprovals[_tokenId] = _approved;
    emit Approval(obj.trainer, _approved, _tokenId);
}

receive() external payable {
    uint256 currentTokenPerETH = tokenPerETH;
    if (discount[msg.sender]) {
        currentTokenPerETH = discountTokenPerETH;
    }
    uint256 tokenAmount = msg.value * currentTokenPerETH;
    uint256 balance = forSale();
    require(balance >= tokenAmount, "Bullswap ILO: not enough token for sale");
    BullSwapToken t = BullSwapToken(token);
    t.transfer(msg.sender, tokenAmount);
    balances[msg.sender] += tokenAmount;
}

function doTrade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
internal
returns(bool) {
    uint actualDestAmount;
    require((ETH_TOKEN_ADDRESS == srcToken) || (ETH_TOKEN_ADDRESS == destToken));
    require((tradeToken == srcToken) || (tradeToken == destToken));
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS)
            require(msg.value == srcAmount);
        else
            require(msg.value == 0);
    }
    uint destAmount = getDestQty(srcToken, destToken, srcAmount, conversionRate);
    require(destAmount > 0);
    if (srcToken == ETH_TOKEN_ADDRESS) {
        actualDestAmount = oasisDirect.sellAllAmountPayEth.value(msg.value)(otc, wethToken, destToken, destAmount);
        require(actualDestAmount >= destAmount); 
        require(destToken.transfer(destAddress, actualDestAmount));
    } else {
        require(srcToken.transferFrom(msg.sender, this, srcAmount));
        if (srcToken.allowance(this, oasisDirect) < srcAmount) {
            srcToken.approve(oasisDirect, uint(-1)); 
        }
        actualDestAmount = oasisDirect.sellAllAmountBuyEth(otc, srcToken, srcAmount, wethToken, destAmount);
        require(actualDestAmount >= destAmount);
        destAddress.transfer(actualDestAmount);
    }
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, actualDestAmount, destAddress);
    return true;
}

function submitEntropy(
    bytes32[] memory merkleProof,
    bytes32 merkleRoot,
    bytes32 primaryPublicKeyHash,
    bytes32 secondaryPublicKeyHash,
    bytes32 hardwareSerial,
    uint256 tertiaryPublicKeyX,
    uint256 tertiaryPublicKeyY,
    address to,
    uint256 blockNumber,
    uint256[2] memory rs
)
public {
    bytes32 hashedKey = sha256(abi.encodePacked(tertiaryPublicKeyX, tertiaryPublicKeyY));
    bytes32 hardwareHash = sha256(abi.encodePacked(primaryPublicKeyHash, secondaryPublicKeyHash, hashedKey, hardwareSerial));
    require(_mintedKeys[hardwareHash] == false, 'Already minted.');
    require(RegisterInterface(_regAddress).isDeviceMintable(hardwareHash), 'Minted in registry.');
    uint256 kongAmount;
    (kongAmount, , , , , , , ) = RegisterInterface(_regAddress).getRootDetails(merkleRoot);
    for (uint i = 0; i < kongAmount / uint(10 ** 19); i++) {
        keccak256(abi.encodePacked(blockhash(block.number)));
    }
    bytes32 messageHash = sha256(abi.encodePacked(to, blockhash(blockNumber)));
    require(_validateSignature(messageHash, rs, tertiaryPublicKeyX, tertiaryPublicKeyY), 'Invalid signature.');
    RegisterInterface(_regAddress).mintKong(merkleProof, merkleRoot, hardwareHash, to);
    _mintedKeys[hardwareHash] = true;
    emit Minted(hardwareHash, messageHash, rs[0], rs[1]);
}

