function release(address account) public {
    require(_shares[account] > 0);
    uint256 totalReceived = address(this).balance.add(_totalReleased);
    uint256 payment = totalReceived.mul(
        _shares[account]).div(
        _totalShares).sub(
        _released[account]
    );
    require(payment != 0);
    _released[account] = _released[account].add(payment);
    _totalReleased = _totalReleased.add(payment);
    account.transfer(payment);
    emit PaymentReleased(account, payment);
}

function inflate() public onlyRole("InflationOperator") returns(uint256) {
    uint256 currentTime = block.timestamp;
    uint256 currentDayStart = currentTime / 1 days;
    uint256 inflationAmount;
    require(lastInflationDayStart != currentDayStart);
    lastInflationDayStart = currentDayStart;
    uint256 createDurationYears = (currentTime - deployTime) / 1 years;
    if (createDurationYears < 1) {
        inflationAmount = initialAmount / 10 / 365;
    } else if (createDurationYears >= 20) {
        inflationAmount = 0;
    } else {
        inflationAmount = initialAmount * (100 - (5 * createDurationYears)) / 365 / 1000;
    }
    incentivesPool = incentivesPool.add(inflationAmount);
    totalSupply = totalSupply.add(inflationAmount);
    emit Inflate(incentivesPool);
    return incentivesPool;
}

function getMaxMakerAmount(
    address makerToken,
    address takerToken,
    bytes orderData
)
external
view
returns(uint256) {
    address zeroExExchange = ZERO_EX_EXCHANGE;
    Order memory order = parseOrder(orderData);
    if (block.timestamp >= order.expirationUnixTimestampSec) {
        return 0;
    }
    bytes32 orderHash = getOrderHash(
        zeroExExchange,
        makerToken,
        takerToken,
        order
    );
    uint256 unavailableTakerAmount =
        ZeroExExchangeInterfaceV1(zeroExExchange).getUnavailableTakerTokenAmount(orderHash);
    uint256 takerAmount = order.takerTokenAmount.sub(unavailableTakerAmount);
    uint256 makerAmount = MathHelpers.getPartialAmount(
        takerAmount,
        order.takerTokenAmount,
        order.makerTokenAmount
    );
    return makerAmount;
}

