function transferFrom(address _from, address _to, uint256 _value) public onlyIfUnlocked returns(bool) {
    uint yourCurrentMntpBalance = mntpToken.balanceOf(_from);
    uint fee = goldFee.calculateFee(msg.sender, migrationStarted, migrationFinished, yourCurrentMntpBalance, _value);
    if (0 != fee) {
        if (migrationStarted) {
            super.transferFrom(_from, goldmintTeamAddress, fee);
        } else {
            super.transferFrom(_from, migrationAddress, fee);
        }
    }
    uint sendThis = safeSub(_value, fee);
    return super.transferFrom(_from, _to, sendThis);
}

function transfer(address _to, uint256 _value) public onlyIfUnlocked onlyPayloadSize(2 * 32) returns(bool) {
    uint yourCurrentMntpBalance = mntpToken.balanceOf(msg.sender);
    uint fee = goldFee.calculateFee(msg.sender, migrationStarted, migrationFinished, yourCurrentMntpBalance, _value);
    uint sendThis = _value;
    if (0 != fee) {
        sendThis = safeSub(_value, fee);
        if (migrationStarted) {
            super.transfer(goldmintTeamAddress, fee);
        } else {
            super.transfer(migrationAddress, fee);
        }
    }
    return super.transfer(_to, sendThis);
}

function miningResolve(uint256 _orderIndex, uint256 _seed)
external
onlyService {
    require(_orderIndex > 0 && _orderIndex < ordersArray.length);
    MiningOrder storage order = ordersArray[_orderIndex];
    require(order.tmResolve == 0);
    address miner = order.miner;
    require(miner != address(0));
    uint64 chestCnt = order.chestCnt;
    require(chestCnt >= 1 && chestCnt <= 10);
    uint256 rdm = _seed;
    uint16[9] memory attrs;
    for (uint64 i = 0; i < chestCnt; ++i) {
        rdm = _randBySeed(rdm);
        attrs = _getFashionParam(rdm);
        tokenContract.createFashion(miner, attrs, 6);
    }
    order.tmResolve = uint64(block.timestamp);
    MiningPlatResolved(_orderIndex, miner, chestCnt);
}

function receiveApproval(address _sender, uint256 _value, address _tokenContract, bytes _extraData)
external
whenNotPaused {
    require(msg.sender == address(bitGuildContract));
    require(_extraData.length == 1);
    uint32 miningType = uint32(_extraData[0]);
    if (miningType == 0) {
        require(_value == miningOnePlat);
        require(bitGuildContract.transferFrom(_sender, address(this), _value));
        _miningOneSelf(_sender);
    } else if (miningType == 10) {
        require(_value == miningTenPlat);
        require(bitGuildContract.transferFrom(_sender, address(this), _value));
        _addOrder(_sender, 10);
    } else if (miningType == 3) {
        require(_value == miningThreePlat);
        require(bitGuildContract.transferFrom(_sender, address(this), _value));
        _addOrder(_sender, 3);
    } else if (miningType == 5) {
        require(_value == miningFivePlat);
        require(bitGuildContract.transferFrom(_sender, address(this), _value));
        _addOrder(_sender, 5);
    } else if (miningType == 1) {
        require(_value == miningOnePlat);
        require(bitGuildContract.transferFrom(_sender, address(this), _value));
        _addOrder(_sender, 1);
    } else {
        require(false);
    }
    _transferHelper(_sender, _value);
}

function CLAIMREWARD() public {
    require(breaker == false, "Admin Restricted WITHDRAW");
    if (totalDividends >= stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        msg.sender.transfer(owing);
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function STAKE(uint256 tokens) external {
    require(IERC20(BBP).transferFrom(msg.sender, address(lpLockAddress), tokens), "Tokens cannot be transferred from user for locking");
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = tokens.add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    (bool _isStakeholder) = isStakeholder(msg.sender);
    if (!_isStakeholder) farmTime[msg.sender] = block.timestamp;
    totalStakes = totalStakes.add(tokens);
    addStakeholder(msg.sender);
    emit STAKED(msg.sender, tokens);
}

