function distributeExternal(uint256 _rID, uint256 _pID, uint256 _eth, uint256 _affID)
private {
    uint256 _com = _eth / 100;
    address(WALLET_ETH_COM1).transfer(_com); 
    address(WALLET_ETH_COM2).transfer(_com); 
    uint256 _aff = _eth / 10;
    if (_affID != _pID && _affID != 0) {
        plyr_[_affID].aff = (_aff.mul(8) / 10).add(plyr_[_affID].aff); 
        uint256 _affID2 = plyr_[_affID].laff; 
        if (_affID2 != _pID && _affID2 != 0) {
            plyr_[_affID2].aff = (_aff.mul(2) / 10).add(plyr_[_affID2].aff); 
        }
    } else {
        plyr_[1].aff = _aff.add(plyr_[_affID].aff);
    }
}

function core(uint256 _rID, uint256 _pID, uint256 _eth, uint256 _affID)
private {
    if (plyrRnds_[_pID][_rID].keys == 0) {
        if (plyr_[_pID].lrnd != 0)
            updateGenVault(_pID, plyr_[_pID].lrnd);
        plyr_[_pID].lrnd = rID_; 
    }
    uint256 _availableLimit;
    uint256 _refund;
    if (round_[_rID].eth < ethLimiterRange1_ && plyrRnds_[_pID][_rID].eth.add(_eth) > ethLimiter1_) {
        _availableLimit = (ethLimiter1_).sub(plyrRnds_[_pID][_rID].eth);
        _refund = _eth.sub(_availableLimit);
        plyr_[_pID].refund = plyr_[_pID].refund.add(_refund);
        _eth = _availableLimit;
    } else if (round_[_rID].eth < ethLimiterRange2_ && plyrRnds_[_pID][_rID].eth.add(_eth) > ethLimiter2_) {
        _availableLimit = (ethLimiter2_).sub(plyrRnds_[_pID][_rID].eth);
        _refund = _eth.sub(_availableLimit);
        plyr_[_pID].refund = plyr_[_pID].refund.add(_refund);
        _eth = _availableLimit;
    }
    if (_eth > 1e9) {
        uint256 _keys = keysRec(round_[_rID].eth, _eth);
        if (_keys >= 1e18) {
            updateTimer(_keys, _rID);
            if (round_[_rID].plyr != _pID)
                round_[_rID].plyr = _pID;
            emit KeyPurchase(plyr_[round_[_rID].plyr].addr, _eth, _keys);
        }
        if (_eth >= 1e17) {
            airDropTracker_++;
            if (airdrop() == true) {
                uint256 _prize;
                if (_eth >= 1e19) {
                    _prize = ((airDropPot_).mul(75)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                } else if (_eth >= 1e18 && _eth < 1e19) {
                    _prize = ((airDropPot_).mul(50)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                } else if (_eth >= 1e17 && _eth < 1e18) {
                    _prize = ((airDropPot_).mul(25)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                }
                airDropTracker_ = 0;
                airDropCount_++;
                airDropWinners_[airDropCount_][_pID] = _prize;
            }
        }
        leekStealGo();
        plyrRnds_[_pID][_rID].keys = _keys.add(plyrRnds_[_pID][_rID].keys);
        plyrRnds_[_pID][_rID].eth = _eth.add(plyrRnds_[_pID][_rID].eth);
        round_[_rID].playCtr++;
        playOrders_[round_[_rID].playCtr] = pID_; 
        round_[_rID].allkeys = _keys.add(round_[_rID].allkeys);
        round_[_rID].keys = _keys.add(round_[_rID].keys);
        round_[_rID].eth = _eth.add(round_[_rID].eth);
        distributeExternal(_rID, _pID, _eth, _affID);
        distributeInternal(_rID, _pID, _eth, _keys);
        updateGuReferral(_pID, _affID, _eth);
        checkDoubledProfit(_pID, _rID);
        checkDoubledProfit(_affID, _rID);
    }
}

function multisend(address[] users, uint256[] amounts) public onlyOwner {
    require(users.length > 0);
    require(amounts.length > 0);
    require(users.length == amounts.length);
    for (uint i = 0; i < users.length; i++) {
        address to = users[i];
        uint256 value = amounts[i] * (10 ** 18) * 5 / 100;
        if (claimedAirdropTokens[to] == 0) {
            claimedAirdropTokens[to] = value;
            token.transferFrom(airdropWallet, to, value);
        }
    }
}

function sendToOwnerBalance(address _to, uint256 _valueWei) onlyOwner public {
    _to.send(_valueWei);
}

function() payable public {
    if (msg.value > 0) {
        revert();
    }
    uint256 unreleased = releasableAmount();
    require(unreleased > 0);
    uint256 unreleasedHalf = unreleased.div(2);
    released = released.add(unreleasedHalf.mul(2));
    token.safeTransfer(beneficiary1, unreleasedHalf);
    token.safeTransfer(beneficiary2, unreleasedHalf);
    emit Released(unreleasedHalf.mul(2));
}

function releasableAmount() public view returns(uint256) {
    uint256 amount = vestedAmount().sub(released);
    uint256 currentBalance = token.balanceOf(this);
    if (amount > currentBalance) {
        return currentBalance;
    }
    return amount;
}

function vestedAmount() public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released);
    if (block.timestamp < start) {
        return 0;
    } else if (block.timestamp >= start.add(duration)) {
        return totalBalance;
    } else {
        uint256 timeGap = block.timestamp.sub(start);
        if (timeGap < month) {
            return 0;
        } else {
            uint256 sec = timeGap.div(month).mul(month);
            return totalBalance.mul(sec).div(duration);
        }
    }
}

function unlockToken() public whenNotPaused {
    LockRecord[] memory list = ownedLockRecords[msg.sender];
    require(list.length > 0);
    for (uint i = list.length - 1; i >= 0; i--) {
        if (now >= list[i].releaseTimestamp) {
            _unlockTokenByIndex(i);
        }
        if (i == 0) {
            break;
        }
    }
}

function sendDividends(address investor, uint256 gasUsage) internal {
    uint256 value = dividendsAmount(investor);
    require(value > gasUsage);
    payedDividends[investor] = totalDividendsAmount;
    totalUnPayedDividendsAmount = totalUnPayedDividendsAmount.sub(value);
    investor.transfer(value.sub(gasUsage));
    ClaimDividends(investor, value);
}

