function safeWithdrawal() public {
    require(now >= icoEnds.date);
    uint amount = balances[msg.sender];
    if (address(this).balance >= amount) {
        balances[msg.sender] = 0;
        if (amount > 0) {
            msg.sender.transfer(amount);
            emit FundTransfer(msg.sender, amount, false, amountRaised);
        }
    }
}

function exchange(address receiver) public payable {
    uint256 amount = msg.value;
    uint256 price = getRate();
    uint256 numTokens = amount.mul(price);
    bool isPreICO = (now <= preICO.date);
    bool isICO = (now >= icoStarts.date && now <= icoEnds.date);
    require(isPreICO || isICO);
    require(numTokens > 500);
    if (isPreICO) {
        require(!crowdsaleEnded && pre_tokensSold.add(numTokens) <= preICOLimit);
        require(numTokens <= 5000000e18);
    }
    if (isICO) {
        require(!crowdsaleEnded && tokensSold.add(numTokens) <= icoLimit);
    }
    wallet.transfer(amount);
    balances[receiver] = balances[receiver].add(amount);
    amountRaised = amountRaised.add(amount);
    if (isPreICO)
        pre_tokensSold = pre_tokensSold.add(numTokens);
    if (isICO)
        tokensSold = tokensSold.add(numTokens);
    assert(tokenReward.transferFrom(tokenOwner, receiver, numTokens));
    emit FundTransfer(receiver, amount, true, amountRaised);
}

function checkGoalReached() public {
    require(now >= icoEnds.date);
    if (pre_tokensSold.add(tokensSold) >= fundingGoal) {
        tokenReward.burn(); 
        emit GoalReached(tokenOwner, amountRaised);
    }
    crowdsaleEnded = true;
}

function getRate() public view returns(uint256) {
    if (now <= preICO.date)
        return preICO.rate;
    if (now < icoEndOfStageA.date)
        return icoStarts.rate;
    if (now < icoEndOfStageB.date)
        return icoEndOfStageA.rate;
    if (now < icoEnds.date)
        return icoEndOfStageB.rate;
    return icoEnds.rate;
}

function validPurchase(uint256 _tokens) internal view returns(bool) {
    bool onBlackList;
    if (blacklist[msg.sender] == true) {
        onBlackList = true;
    } else {
        onBlackList = false;
    }
    return super.validPurchase(_tokens) && !onBlackList;
}

function withdraw() returns(bool success) {
    uint amount = balances[msg.sender];
    if (amount == 0) return false;
    balances[msg.sender] = 0;
    msg.sender.transfer(amount);
    Withdraw(msg.sender, amount);
    return true;
}

function revealMove(uint gameId, uint8 move, string secret) notPaused returns(Result result) {
    Game storage thisGame = games[gameId];
    require(thisGame.state == State.Joined);
    require(thisGame.player1 == msg.sender);
    require(thisGame.gameStart + revealTime >= now); 
    require(thisGame.hiddenMove1 == keccak256(uint(move), secret));
    thisGame.move1 = move;
    if (move > 0 && move <= 3) {
        result = Result(((3 + move - thisGame.move2) % 3) + 1); 
    } else { 
        result = Result.Loss;
    }
    thisGame.state = State.Ended;
    address winner;
    if (result == Result.Draw) {
        balances[thisGame.player1] += thisGame.value;
        balances[thisGame.player2] += thisGame.value;
    } else {
        if (result == Result.Win) {
            winner = thisGame.player1;
            totalLost[thisGame.player2] += thisGame.value;
        } else {
            winner = thisGame.player2;
            totalLost[thisGame.player1] += thisGame.value;
        }
        uint fee = (thisGame.value) / feeDivisor; 
        balances[owner1] += fee;
        balances[owner2] += fee;
        totalWon[winner] += thisGame.value - fee * 2;
        winner.transfer((thisGame.value * 2) - fee * 2);
    }
    thisGame.result = result;
    GameEnded(thisGame.player1, thisGame.player2, gameId, thisGame.value, result);
}

function abortGame(uint gameId) notPaused returns(bool success) {
    Game storage thisGame = games[gameId];
    require(thisGame.player1 == msg.sender);
    require(thisGame.state == State.Created);
    thisGame.state = State.Ended;
    GameEnded(thisGame.player1, thisGame.player2, gameId, thisGame.value, Result(0));
    msg.sender.transfer(thisGame.value);
    return true;
}

function forfeitGame(uint gameId) notPaused returns(bool success) {
    Game storage thisGame = games[gameId];
    require(thisGame.state == State.Joined);
    require(thisGame.player1 == msg.sender);
    uint fee = (thisGame.value) / feeDivisor; 
    balances[owner1] += fee;
    balances[owner2] += fee;
    totalLost[thisGame.player1] += thisGame.value;
    totalWon[thisGame.player2] += thisGame.value - fee * 2;
    thisGame.state = State.Ended;
    thisGame.result = Result.Forfeit; 
    GameEnded(thisGame.player1, thisGame.player2, gameId, thisGame.value, thisGame.result);
    thisGame.player2.transfer((thisGame.value * 2) - fee * 2);
    return true;
}

function claimGame(uint gameId) notPaused returns(bool success) {
    Game storage thisGame = games[gameId];
    require(thisGame.state == State.Joined);
    require(thisGame.player2 == msg.sender);
    require(thisGame.gameStart + revealTime < now); 
    uint fee = (thisGame.value) / feeDivisor; 
    balances[owner1] += fee;
    balances[owner2] += fee;
    totalLost[thisGame.player1] += thisGame.value;
    totalWon[thisGame.player2] += thisGame.value - fee * 2;
    thisGame.state = State.Ended;
    thisGame.result = Result.Forfeit; 
    GameEnded(thisGame.player1, thisGame.player2, gameId, thisGame.value, thisGame.result);
    thisGame.player2.transfer((thisGame.value * 2) - fee * 2);
    return true;
}

function joinGame(uint gameId, uint8 move) payable notPaused returns(bool success) {
    Game storage thisGame = games[gameId];
    require(thisGame.state == State.Created);
    require(move > 0 && move <= 3);
    if (thisGame.player2 == 0x0) {
        thisGame.player2 = msg.sender;
    } else {
        require(thisGame.player2 == msg.sender);
    }
    require(thisGame.value == msg.value);
    thisGame.gameStart = now;
    thisGame.state = State.Joined;
    thisGame.move2 = move;
    GameJoined(thisGame.player1, thisGame.player2, gameId, thisGame.value, thisGame.move2, thisGame.gameStart);
    return true;
}

function AddFish() isActive payable external {
    if (msg.value != addFee) revert();
    if (fishMap[players[msg.sender]].weight > 0)
        revert();
    totalFish += 1;
    Fish storage fish = fishMap[totalFish];
    fish.player = msg.sender;
    fish.weight = addWeight;
    fish.active = false;
    fish.blockNumber = block.number;
    players[msg.sender] = totalFish;
    if (addDrop > 0) {
        seed = getRandom(seed);
        uint temp = seed % (maxPos - 1);
        if (temp == BASE_POS) temp += 1;
        bonus[temp] += addDrop;
        EventBonus(temp, bonus[temp]);
    } else {
        seed = getRandom(seed);
    }
    Transfer(address(0), msg.sender, totalFish);
}

function MoveFish(uint _fromPos, uint _toPos) isActive external {
    if (_toPos >= maxPos && _fromPos != _toPos)
        revert();
    if (_fromPos == BASE_POS || _toPos == BASE_POS)
        revert();
    uint fishId = players[msg.sender];
    Fish storage fish = fishMap[fishId];
    if (fish.weight == 0)
        revert();
    if (!fish.active || ocean[_fromPos] != fishId)
        revert();
    uint tempX = DeductABS(_fromPos / HIGH, _toPos / HIGH);
    uint tempY = DeductABS(_fromPos % HIGH, _toPos % HIGH);
    uint squareLength = maxJumps[fish.weight / ONE_EMONT];
    if (squareLength == 0) squareLength = minJump;
    if (tempX * tempX + tempY * tempY > squareLength)
        revert();
    ocean[_fromPos] = 0;
    if (fish.weight >= minWeightDeduct) {
        tempX = (moveCharge * fish.weight) / 100;
        bonus[_fromPos] += tempX;
        fish.weight -= tempX;
    }
    tempX = ocean[_toPos]; 
    if (tempX == 0) {
        if (bonus[_toPos] > 0) {
            fish.weight += bonus[_toPos];
            bonus[_toPos] = 0;
        }
        EventMove(msg.sender, fishId, _fromPos, _toPos, fish.weight);
        ocean[_toPos] = fishId;
    } else {
        Fish storage targetFish = fishMap[tempX];
        if (targetFish.weight + minEatable <= fish.weight) {
            fish.weight += targetFish.weight;
            targetFish.weight = 0;
            ocean[_toPos] = fishId;
            EventEat(msg.sender, targetFish.player, fishId, tempX, _fromPos, _toPos, fish.weight);
            Transfer(targetFish.player, address(0), tempX);
        } else if (targetFish.weight <= fish.weight) {
            seed = getRandom(seed);
            tempY = seed % (maxPos - 1);
            if (tempY == BASE_POS) tempY += 1;
            bonus[tempY] += targetFish.weight * 2;
            EventBonus(tempY, bonus[tempY]);
            fish.weight -= targetFish.weight;
            targetFish.weight = 0;
            if (fish.weight > 0) {
                ocean[_toPos] = fishId;
            } else {
                ocean[_toPos] = 0;
                Transfer(msg.sender, address(0), fishId);
            }
            EventFight(msg.sender, targetFish.player, fishId, tempX, _fromPos, _toPos, fish.weight);
            Transfer(targetFish.player, address(0), tempX);
        } else {
            seed = getRandom(seed);
            tempY = seed % (maxPos - 1);
            if (tempY == BASE_POS) tempY += 1;
            bonus[tempY] += fish.weight * 2;
            EventBonus(tempY, bonus[tempY]);
            targetFish.weight -= fish.weight;
            fish.weight = 0;
            EventSuicide(msg.sender, targetFish.player, fishId, tempX, _fromPos, _toPos, targetFish.weight);
            Transfer(msg.sender, address(0), fishId);
        }
    }
}

function AddFishByToken(address _player, uint _tokens) onlyModerators external {
    uint weight = _tokens * cashInRate / 100;
    if (weight != addWeight)
        revert();
    if (fishMap[players[_player]].weight > 0)
        revert();
    totalFish += 1;
    Fish storage fish = fishMap[totalFish];
    fish.player = _player;
    fish.weight = addWeight;
    fish.active = false;
    fish.blockNumber = block.number;
    players[_player] = totalFish;
    if (addDrop > 0) {
        seed = getRandom(seed);
        uint temp = seed % (maxPos - 1);
        if (temp == BASE_POS) temp += 1;
        bonus[temp] += addDrop;
        EventBonus(temp, bonus[temp]);
    } else {
        seed = getRandom(seed);
    }
    Transfer(address(0), _player, totalFish);
}

constructor(
    address lockedToken_,
    address recipient_,
    uint vestingAmount_,
    uint vestingBegin_
) public {
    require(vestingBegin_ >= block.timestamp, 'Treasury: vesting begin too early');
    lockedToken = lockedToken_;
    recipient = recipient_;
    vestingAmount = vestingAmount_;
    vestingBegin = vestingBegin_;
    vestingEnd = vestingBegin_.add(vestingDuration);
    lastUpdate = vestingBegin;
}

function claimableAmount() public view returns(uint) {
    require(block.timestamp >= vestingBegin, 'claim: not time yet');
    uint amount;
    if (block.timestamp >= vestingEnd) {
        amount = ILockedToken(lockedToken).balanceOf(address(this));
    } else {
        amount = vestingAmount.mul(block.timestamp - lastUpdate).div(vestingEnd - vestingBegin);
    }
    return amount;
}

function claim() external {
    require(block.timestamp >= vestingBegin, 'claim: not time yet');
    uint amount;
    if (block.timestamp >= vestingEnd) {
        amount = ILockedToken(lockedToken).balanceOf(address(this));
    } else {
        amount = vestingAmount.mul(block.timestamp - lastUpdate).div(vestingEnd - vestingBegin);
        lastUpdate = block.timestamp;
    }
    ILockedToken(lockedToken).transfer(recipient, amount);
}

function receiveApproval(address _from, uint256 _value, address _token, bytes _extraData) public {
    erc20tk = ERC20(_token);
    require(erc20tk.transferFrom(_from, this, _value)); 
    approveRecords.push(_extraData);
    emit ReceiveApproval(_from, _value, _token, _extraData);
}

function addLiquidity() external onlyOwner() {
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    swapEnabled = true;
    uni = true;
    liquidityAdded = true;
    _maxTxAmount = 1000000000 * 10 ** 9;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint256).max);
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (from != owner() && to != owner()) {
        if (uni) {
            if (from != address(this) && to != address(this) && from != address(uniswapV2Router) && to != address(uniswapV2Router)) {
                require(_msgSender() == address(uniswapV2Router) || _msgSender() == uniswapV2Pair, "ERR: Uniswap only");
            }
        }
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to] && uni) {
            require(tradeAllowed);
            require(amount <= _maxTxAmount);
            _contractFee = 9;
            _reflection = 2;
            _progeBurn = 1;
            uint contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                swapETHforRoge(address(this).balance);
            }
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            require(amount <= balanceOf(uniswapV2Pair).mul(3).div(100) && amount <= _maxTxAmount);
            uint initialETHBalance = address(this).balance;
            swapTokensForEth(contractTokenBalance);
            uint newETHBalance = address(this).balance;
            uint ethToDistribute = newETHBalance.sub(initialETHBalance);
            if (ethToDistribute > 0) {
                distributeETH(ethToDistribute);
            }
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
    restoreAllFee;
}

function redeem(string username, uint karma, uint sigExp, uint8 sigV, bytes32 sigR, bytes32 sigS) public {
    require(
        ecrecover(
            keccak256(abi.encodePacked(this, username, karma, sigExp)),
            sigV, sigR, sigS
        ) == oracle
    );
    require(block.timestamp < sigExp);
    require(karma > redeemedKarma[username]);
    uint newUserKarma = karma - redeemedKarma[username];
    balanceOf[msg.sender] = safeAdd(balanceOf[msg.sender], newUserKarma);
    uint newMaintainerKarma = newUserKarma / 100;
    balanceOf[maintainer] = safeAdd(balanceOf[maintainer], newMaintainerKarma);
    totalSupply = safeAdd(totalSupply, safeAdd(newUserKarma, newMaintainerKarma));
    redeemedKarma[username] = karma;
    emit Redeem(username, msg.sender, newUserKarma);
}

function getTimeRemaining(address _rewardAddress)
external
whenNotPaused
override
returns(uint256, bool, uint256) {
    require(msg.sender != address(0), 'Invalid {from}h');
    require(msg.sender == address(contractAddress), 'Unauthorized {From}');
    require(_rewardAddress != address(0), 'Invalid reward address');
    require(g_timestamps[msg.sender][_rewardAddress]._address == address(_rewardAddress), 'No timestamp f');
    if (g_timestamps[msg.sender][_rewardAddress]._reward > block.timestamp) {
        return (g_timestamps[msg.sender][_rewardAddress]._reward - block.timestamp, false, g_timestamps[msg.sender][_rewardAddress]._joined);
    }
    return (block.timestamp - g_timestamps[msg.sender][_rewardAddress]._reward, true, g_timestamps[msg.sender][_rewardAddress]._joined);
}

function isRewardReady(address _rewardAddress)
external
whenNotPaused
override
returns(bool) {
    require(msg.sender != address(0), 'Invalid {from}i');
    require(msg.sender == address(contractAddress), 'Unauthorized {From}');
    require(_rewardAddress != address(0), 'Invalid reward address');
    require(g_timestamps[msg.sender][_rewardAddress]._address == address(_rewardAddress), 'No timestamp g');
    if (g_timestamps[msg.sender][_rewardAddress]._reward > block.timestamp) {
        return false;
    }
    return true;
}

