function submitOrder(
    bytes _prefix,
    uint64 _settlementID,
    uint64 _tokens,
    uint256 _price,
    uint256 _volume,
    uint256 _minimumVolume
) external withGasPriceLimit(submissionGasPriceLimit) {
    SettlementUtils.OrderDetails memory order = SettlementUtils.OrderDetails({
        settlementID: _settlementID,
        tokens: _tokens,
        price: _price,
        volume: _volume,
        minimumVolume: _minimumVolume
    });
    bytes32 orderID = SettlementUtils.hashOrder(_prefix, order);
    require(orderStatus[orderID] == OrderStatus.None, "order already submitted");
    require(orderbookContract.orderState(orderID) == Orderbook.OrderState.Confirmed, "unconfirmed order");
    orderSubmitter[orderID] = msg.sender;
    orderStatus[orderID] = OrderStatus.Submitted;
    orderDetails[orderID] = order;
}

function settle(bytes32 _buyID, bytes32 _sellID) external {
    require(orderStatus[_buyID] == OrderStatus.Submitted, "invalid buy status");
    require(orderStatus[_sellID] == OrderStatus.Submitted, "invalid sell status");
    require(
        orderDetails[_buyID].settlementID == RENEX_ATOMIC_SETTLEMENT_ID ||
        orderDetails[_buyID].settlementID == RENEX_SETTLEMENT_ID,
        "invalid settlement id"
    );
    require(SettlementUtils.verifyMatchDetails(orderDetails[_buyID], orderDetails[_sellID]), "incompatible orders");
    require(orderbookContract.orderMatch(_buyID) == _sellID, "unconfirmed orders");
    TokenPair memory tokens = getTokenDetails(orderDetails[_buyID].tokens);
    require(tokens.priorityToken.registered, "unregistered priority token");
    require(tokens.secondaryToken.registered, "unregistered secondary token");
    address buyer = orderbookContract.orderTrader(_buyID);
    address seller = orderbookContract.orderTrader(_sellID);
    require(buyer != seller, "orders from same trader");
    execute(_buyID, _sellID, buyer, seller, tokens);
    matchTimestamp[_buyID][_sellID] = now;
    orderStatus[_buyID] = OrderStatus.Settled;
    orderStatus[_sellID] = OrderStatus.Settled;
}

function transferBalanceWithFee(address _traderFrom, address _traderTo, address _token, uint256 _value, uint256 _fee, address _feePayee)
external onlyRenExSettlementContract {
    require(traderBalances[_traderFrom][_token] >= _fee, "insufficient funds for fee");
    if (address(_token) == ETHEREUM) {
        rewardVaultContract.deposit.value(_fee)(_feePayee, ERC20(_token), _fee);
    } else {
        CompatibleERC20(_token).safeApprove(rewardVaultContract, _fee);
        rewardVaultContract.deposit(_feePayee, ERC20(_token), _fee);
    }
    privateDecrementBalance(_traderFrom, ERC20(_token), _value + _fee);
    if (_value > 0) {
        privateIncrementBalance(_traderTo, ERC20(_token), _value);
    }
}

function deposit(address _darknode, ERC20 _token, uint256 _value) public payable {
    uint256 receivedValue = _value;
    if (address(_token) == ETHEREUM) {
        require(msg.value == _value, "mismatched ether value");
    } else {
        require(msg.value == 0, "unexpected ether value");
        receivedValue = CompatibleERC20(_token).safeTransferFromWithFees(msg.sender, address(this), _value);
    }
    darknodeBalances[_darknode][_token] = darknodeBalances[_darknode][_token].add(receivedValue);
}

function withdraw(address _darknode, ERC20 _token) public {
    address darknodeOwner = darknodeRegistry.getDarknodeOwner(address(_darknode));
    require(darknodeOwner != 0x0, "invalid darknode owner");
    uint256 value = darknodeBalances[_darknode][_token];
    darknodeBalances[_darknode][_token] = 0;
    if (address(_token) == ETHEREUM) {
        darknodeOwner.transfer(value);
    } else {
        CompatibleERC20(_token).safeTransfer(darknodeOwner, value);
    }
}

function slash(bytes32 _guiltyOrderID) external onlySlasher {
    require(orderDetails[_guiltyOrderID].settlementID == RENEX_ATOMIC_SETTLEMENT_ID, "slashing non-atomic trade");
    bytes32 innocentOrderID = orderbookContract.orderMatch(_guiltyOrderID);
    require(orderStatus[_guiltyOrderID] == OrderStatus.Settled, "invalid order status");
    require(orderStatus[innocentOrderID] == OrderStatus.Settled, "invalid order status");
    orderStatus[_guiltyOrderID] = OrderStatus.Slashed;
    (bytes32 buyID, bytes32 sellID) = isBuyOrder(_guiltyOrderID) ?
        (_guiltyOrderID, innocentOrderID) : (innocentOrderID, _guiltyOrderID);
    TokenPair memory tokens = getTokenDetails(orderDetails[buyID].tokens);
    SettlementDetails memory settlementDetails = calculateAtomicFees(buyID, sellID, tokens);
    renExBalancesContract.transferBalanceWithFee(
        orderbookContract.orderTrader(_guiltyOrderID),
        orderbookContract.orderTrader(innocentOrderID),
        settlementDetails.leftTokenAddress,
        settlementDetails.leftTokenFee,
        0,
        0x0
    );
    renExBalancesContract.transferBalanceWithFee(
        orderbookContract.orderTrader(_guiltyOrderID),
        slasherAddress,
        settlementDetails.leftTokenAddress,
        settlementDetails.leftTokenFee,
        0,
        0x0
    );
}

function get(bytes calldata data) external override returns(bool, uint256) {
    uint32 blockTimestamp = uint32(block.timestamp);
    if (pairInfo.blockTimestampLast == 0) {
        pairInfo.blockTimestampLast = blockTimestamp;
        pairInfo.priceCumulativeLast = _get(blockTimestamp);
        return (false, 0);
    }
    uint32 timeElapsed = blockTimestamp - pairInfo.blockTimestampLast; 
    if (timeElapsed < PERIOD) {
        return (true, pairInfo.priceAverage);
    }
    uint256 priceCumulative = _get(blockTimestamp);
    pairInfo.priceAverage = uint144(1e44 / WOHM.sOHMTowOHM(uint256(FixedPoint
        .uq112x112(uint224((priceCumulative - pairInfo.priceCumulativeLast) / timeElapsed))
        .mul(1e18)
        .decode144())).mul(uint256(DAI_USD.latestAnswer())));
    pairInfo.blockTimestampLast = blockTimestamp;
    pairInfo.priceCumulativeLast = priceCumulative;
    return (true, pairInfo.priceAverage);
}

function peek(bytes calldata data) public view override returns(bool, uint256) {
    uint32 blockTimestamp = uint32(block.timestamp);
    if (pairInfo.blockTimestampLast == 0) {
        return (false, 0);
    }
    uint32 timeElapsed = blockTimestamp - pairInfo.blockTimestampLast; 
    if (timeElapsed < PERIOD) {
        return (true, pairInfo.priceAverage);
    }
    uint256 priceCumulative = _get(blockTimestamp);
    uint144 priceAverage = uint144(1e44 / WOHM.sOHMTowOHM(uint256(FixedPoint
        .uq112x112(uint224((priceCumulative - pairInfo.priceCumulativeLast) / timeElapsed))
        .mul(1e18)
        .decode144())).mul(uint256(DAI_USD.latestAnswer())));
    return (true, priceAverage);
}

function() public payable {
    require(msg.value > 0);
    require(white.isWhitelisted(msg.sender) == true);
    require(!crowdsaleClosed);
    require(now <= deadline && now >= start);
    uint256 amount = (((msg.value * 100) * getTokenPrice()) / 100);
    totalSold += (amount / tokenPrice) * 100;
    if (tokenSold < 6000000) {
        amount = amount + ((amount * 25) / 100);
    } else if (tokenSold < 12000000) {
        amount = amount + ((amount * 15) / 100);
    } else {
        amount = amount + ((amount * 10) / 100);
    }
    ETHWallet.transfer(msg.value);
    Token.transferFrom(owner, msg.sender, amount);
    emit Contribution(msg.sender, amount);
}

function removeUnitMultipliers(address player, uint256 upgradeClass, uint256 unitId, uint256 upgradeValue) external onlyAccess {
    uint256 productionLoss;
    if (upgradeClass == 0) {
        unitCoinProductionIncreases[player][unitId] -= upgradeValue;
        productionLoss = unitsOwned[player][unitId] * upgradeValue * (10 + unitCoinProductionMultiplier[player][unitId]);
        reducePlayersJadeProduction(player, productionLoss);
    } else if (upgradeClass == 1) {
        unitCoinProductionMultiplier[player][unitId] -= upgradeValue;
        productionLoss = unitsOwned[player][unitId] * upgradeValue * (schema.unitCoinProduction(unitId) + unitCoinProductionIncreases[player][unitId]);
        reducePlayersJadeProduction(player, productionLoss);
    } else if (upgradeClass == 2) {
        unitAttackIncreases[player][unitId] -= upgradeValue;
    } else if (upgradeClass == 3) {
        unitAttackMultiplier[player][unitId] -= upgradeValue;
    } else if (upgradeClass == 4) {
        unitDefenseIncreases[player][unitId] -= upgradeValue;
    } else if (upgradeClass == 5) {
        unitDefenseMultiplier[player][unitId] -= upgradeValue;
    } else if (upgradeClass == 6) {
        unitJadeStealingIncreases[player][unitId] -= upgradeValue;
    } else if (upgradeClass == 7) {
        unitJadeStealingMultiplier[player][unitId] -= upgradeValue;
    }
}

function upgradeUnitMultipliers(address player, uint256 upgradeClass, uint256 unitId, uint256 upgradeValue) external onlyAccess {
    uint256 productionGain;
    if (upgradeClass == 0) {
        unitCoinProductionIncreases[player][unitId] += upgradeValue;
        productionGain = unitsOwned[player][unitId] * upgradeValue * (10 + unitCoinProductionMultiplier[player][unitId]);
        increasePlayersJadeProduction(player, productionGain);
    } else if (upgradeClass == 1) {
        unitCoinProductionMultiplier[player][unitId] += upgradeValue;
        productionGain = unitsOwned[player][unitId] * upgradeValue * (schema.unitCoinProduction(unitId) + unitCoinProductionIncreases[player][unitId]);
        increasePlayersJadeProduction(player, productionGain);
    } else if (upgradeClass == 2) {
        unitAttackIncreases[player][unitId] += upgradeValue;
    } else if (upgradeClass == 3) {
        unitAttackMultiplier[player][unitId] += upgradeValue;
    } else if (upgradeClass == 4) {
        unitDefenseIncreases[player][unitId] += upgradeValue;
    } else if (upgradeClass == 5) {
        unitDefenseMultiplier[player][unitId] += upgradeValue;
    } else if (upgradeClass == 6) {
        unitJadeStealingIncreases[player][unitId] += upgradeValue;
    } else if (upgradeClass == 7) {
        unitJadeStealingMultiplier[player][unitId] += upgradeValue;
    } else if (upgradeClass == 8) {
        unitMaxCap[player][unitId] = upgradeValue; 
    }
}

function transfer(address recipient, uint256 amount) public returns(bool) {
    updatePlayersCoin(msg.sender);
    require(amount <= jadeBalance[msg.sender]);
    jadeBalance[msg.sender] = SafeMath.sub(jadeBalance[msg.sender], amount);
    jadeBalance[recipient] = SafeMath.add(jadeBalance[recipient], amount);
    Transfer(msg.sender, recipient, amount);
    return true;
}

function transferFrom(address player, address recipient, uint256 amount) public returns(bool) {
    updatePlayersCoin(player);
    require(amount <= allowed[player][msg.sender] && amount <= jadeBalance[player]);
    jadeBalance[player] = SafeMath.sub(jadeBalance[player], amount);
    jadeBalance[recipient] = SafeMath.add(jadeBalance[recipient], amount);
    allowed[player][msg.sender] = SafeMath.sub(allowed[player][msg.sender], amount);
    Transfer(player, recipient, amount);
    return true;
}

function balanceOfUnclaimed(address player) public constant returns(uint256) {
    uint256 lSave = lastJadeSaveTime[player];
    if (lSave > 0 && lSave < block.timestamp) {
        return SafeMath.mul(getJadeProduction(player), SafeMath.div(SafeMath.sub(block.timestamp, lSave), 100));
    }
    return 0;
}

function updatePlayersCoinByPurchase(address player, uint256 purchaseCost) public onlyAccess {
    uint256 unclaimedJade = balanceOfUnclaimed(player);
    if (purchaseCost > unclaimedJade) {
        uint256 jadeDecrease = SafeMath.sub(purchaseCost, unclaimedJade);
        require(jadeBalance[player] >= jadeDecrease);
        roughSupply = SafeMath.sub(roughSupply, jadeDecrease);
        jadeBalance[player] = SafeMath.sub(jadeBalance[player], jadeDecrease);
    } else {
        uint256 jadeGain = SafeMath.sub(unclaimedJade, purchaseCost);
        roughSupply = SafeMath.add(roughSupply, jadeGain);
        jadeBalance[player] = SafeMath.add(jadeBalance[player], jadeGain);
    }
    lastJadeSaveTime[player] = block.timestamp;
}

function placeBet(address _miner)
public
payable
notContract(msg.sender)
notLess
notMore
onlyOnce {
    totalBetCount = totalBetCount.add(1);
    BetReceived(msg.sender, _miner, block.coinbase);
    owner.balance = owner.balance.add(safeGetPercent(allowedBetAmount, ownerProfitPercent));
    prizePool = prizePool.add(safeGetPercent(allowedBetAmount, prizePoolPercent));
    nextPrizePool = nextPrizePool.add(safeGetPercent(allowedBetAmount, nextPrizePoolPercent));
    if (_miner == block.coinbase) {
        playersPoints[msg.sender]++;
        if (playersPoints[msg.sender] == requiredPoints) {
            if (prizePool >= allowedBetAmount) {
                Jackpot(msg.sender, prizePool);
                playersStorage[msg.sender].balance = playersStorage[msg.sender].balance.add(prizePool);
                prizePool = nextPrizePool;
                nextPrizePool = 0;
                playersPoints[msg.sender] = 0;
            } else {
                playersPoints[msg.sender]--;
            }
        }
    } else {
        playersPoints[msg.sender] = 0;
    }
}

function setupDisbursement(
    address vestor,
    uint256 tokens,
    uint256 timestamp
)
external
onlyOwner {
    require(block.timestamp < timestamp);
    disbursements[vestor].push(Disbursement(timestamp, tokens));
    totalAmount = totalAmount.add(tokens);
    LogSetup(vestor, timestamp, tokens);
}

function sendFundsToWallet() external atState(State.Closed) {
    require(lastDisbursement.add(DISBURSEMENT_DURATION) <= now);
    lastDisbursement = now;
    uint256 amountToSend = Math.min256(address(this).balance, disbursementAmount);
    refundable = amountToSend > refundable ? 0 : refundable.sub(amountToSend);
    trustedWallet.transfer(amountToSend);
}

function setStateStartTime(bytes32 _stateId, uint256 _timestamp) internal {
    require(block.timestamp < _timestamp);
    if (startTime[_stateId] == 0) {
        addStartCondition(_stateId, hasStartTimePassed);
    }
    startTime[_stateId] = _timestamp;
    LogSetStateStartTime(_stateId, _timestamp);
}

function close() external atState(State.Success) {
    require(closingDeadline != 0 && closingDeadline <= now);
    state = State.Closed;
    LogClosed();
}

function beginClosingPeriod() external onlyOwner atState(State.Success) {
    require(closingDeadline == 0);
    closingDeadline = now.add(closingDuration);
}

function Sale(
    uint256 _totalSaleCap,
    uint256 _minContribution,
    uint256 _minThreshold,
    uint256 _maxTokens,
    address _whitelistAdmin,
    address _wallet,
    uint256 _closingDuration,
    uint256 _vaultInitialAmount,
    uint256 _vaultDisbursementAmount,
    uint256 _startTime,
    string _tokenName,
    string _tokenSymbol,
    uint8 _tokenDecimals
)
Whitelistable(_whitelistAdmin)
public {
    require(_totalSaleCap != 0);
    require(_maxTokens != 0);
    require(_wallet != 0);
    require(_minThreshold <= _totalSaleCap);
    require(_vaultInitialAmount <= _minThreshold);
    require(now < _startTime);
    totalSaleCap = _totalSaleCap;
    minContribution = _minContribution;
    minThreshold = _minThreshold;
    trustedToken = new Token(_maxTokens, _tokenName, _tokenSymbol, _tokenDecimals);
    disbursementHandler = new DisbursementHandler(trustedToken);
    trustedToken.setController(this);
    trustedVault = new Vault(
        _wallet,
        _vaultInitialAmount,
        _vaultDisbursementAmount, 
        _closingDuration
    );
    setStates(states);
    allowFunction(SETUP, this.setup.selector);
    allowFunction(FREEZE, this.setEndTime.selector);
    allowFunction(SALE_IN_PROGRESS, this.setEndTime.selector);
    allowFunction(SALE_IN_PROGRESS, this.contribute.selector);
    allowFunction(SALE_IN_PROGRESS, this.endSale.selector);
    allowFunction(SALE_ENDED, this.allocateTokens.selector);
    addStartCondition(SALE_ENDED, wasCapReached);
    addCallback(SALE_ENDED, onSaleEnded);
    setStateStartTime(SALE_IN_PROGRESS, _startTime);
}

function calcMaxWithdraw(address beneficiary)
public
view
returns(uint256) {
    uint256 maxTokens = 0;
    Disbursement[] storage temp = disbursements[beneficiary];
    uint256 tempLength = temp.length;
    for (uint256 i = 0; i < tempLength; i++) {
        if (block.timestamp > temp[i].timestamp) {
            maxTokens = maxTokens.add(temp[i].tokens);
        }
    }
    return maxTokens.sub(withdrawnTokens[beneficiary]);
}

function onSaleEnded() internal {
    if (weiContributed < minThreshold) {
        trustedVault.enableRefunds();
    } else {
        trustedVault.beginClosingPeriod();
        tokensPerWei = tokensForSale.div(weiContributed);
    }
    trustedToken.transferOwnership(owner);
    trustedVault.transferOwnership(owner);
}

function setup() public onlyOwner checkAllowed {
    require(trustedToken.transfer(disbursementHandler, disbursementHandler.totalAmount()));
    tokensForSale = trustedToken.balanceOf(this);
    require(tokensForSale >= totalSaleCap);
    goToNextState();
}

function refund(address contributor) external atState(State.Refunding) {
    uint256 refundAmount = deposited[contributor].mul(refundable).div(totalDeposited);
    deposited[contributor] = 0;
    contributor.transfer(refundAmount);
    LogRefunded(contributor, refundAmount);
}

function contribute(uint256 contributionLimit, uint256 currentSaleCap, uint8 v, bytes32 r, bytes32 s)
external
payable
checkAllowed {
    require(currentSaleCap <= totalSaleCap);
    require(weiContributed < currentSaleCap);
    require(checkWhitelisted(msg.sender, contributionLimit, currentSaleCap, v, r, s));
    uint256 current = contributions[msg.sender];
    require(current < contributionLimit);
    uint256 remaining = Math.min256(contributionLimit.sub(current), currentSaleCap.sub(weiContributed));
    uint256 contribution = Math.min256(msg.value, remaining);
    uint256 totalContribution = current.add(contribution);
    require(totalContribution >= minContribution);
    contributions[msg.sender] = totalContribution;
    hasContributed[msg.sender] = true;
    weiContributed = weiContributed.add(contribution);
    trustedVault.deposit.value(contribution)(msg.sender);
    if (weiContributed >= minThreshold && trustedVault.state() != Vault.State.Success) trustedVault.saleSuccessful();
    uint256 excess = msg.value.sub(contribution);
    if (excess > 0) msg.sender.transfer(excess);
    LogContribution(msg.sender, contribution, excess);
    assert(totalContribution <= contributionLimit);
}

function withdraw(uint256 _sellEth)
public {
    address _customerAddress = msg.sender;
    require(_sellEth > 0, "user cant spam transactions with 0 value");
    require(_sellEth <= ethBalanceOf(_customerAddress), "user cant withdraw more then he holds ");
    _customerAddress.transfer(_sellEth);
    balanceLedger_[_customerAddress] = ethBalanceOf(_customerAddress).sub(_sellEth);
    personalFactorLedger_[_customerAddress] = constantFactor / globalFactor;
    emit onWithdraw(_customerAddress, _sellEth, getBalance(), now);
}

function withdrawAll()
public {
    address _customerAddress = msg.sender;
    uint256 _sellEth = ethBalanceOf(_customerAddress);
    require(_sellEth > 0, "user cant call withdraw, when holds nothing");
    _customerAddress.transfer(_sellEth);
    balanceLedger_[_customerAddress] = 0;
    personalFactorLedger_[_customerAddress] = constantFactor / globalFactor;
    emit onWithdraw(_customerAddress, _sellEth, getBalance(), now);
}

function airdropManually(address _holder, uint _amount) public onlyOwner isAllowed {
    require(_holder != address(0));
    require(tokenReceived[_holder] == false);
    if (!token.transfer(_holder, _amount)) revert();
    tokenReceived[_holder] = true;
    totalClaimed = totalClaimed.add(_amount);
}

function airdrop(address[] _recipients, uint[] _amounts) public onlyOwner isAllowed {
    for (uint i = 0; i < _recipients.length; i++) {
        require(_recipients[i] != address(0));
        require(tokenReceived[_recipients[i]] == false);
        require(token.transfer(_recipients[i], _amounts[i]));
        tokenReceived[_recipients[i]] = true;
        totalClaimed = totalClaimed.add(_amounts[i]);
    }
}

function transfer(address _to, uint _value, bytes _data) public {
    require(_value > 0);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value, _data);
}

function executeTransaction(uint transactionId)
public
notExecuted(transactionId)
returns(bool) {
    if (transactions[transactionId].transactionType == TransactionType.Standard &&
        isConfirmed(transactionId) &&
        this.balance >= transactions[transactionId].value) {
        transactions[transactionId].executed = true;
        transactions[transactionId].destination.transfer(transactions[transactionId].value);
        Execution(transactionId, now);
        return true;
    } else if (transactions[transactionId].transactionType == TransactionType.Token &&
        isConfirmed(transactionId) &&
        StandardToken(transactions[transactionId].token).balanceOf(address(this)) >= transactions[transactionId].value) {
        require(now >= vestedDate);
        transactions[transactionId].executed = true;
        StandardToken(transactions[transactionId].token).transfer(transactions[transactionId].destination, transactions[transactionId].value);
        Execution(transactionId, now);
        return true;
    } else if (transactions[transactionId].transactionType == TransactionType.Unfreeze &&
        isConfirmed(transactionId)) {
        transactions[transactionId].executed = true;
        FreezableToken(transactions[transactionId].token).unfreeze();
        Execution(transactionId, now);
        return true;
    } else if (transactions[transactionId].transactionType == TransactionType.PassOwnership &&
        isConfirmed(transactionId)) {
        transactions[transactionId].executed = true;
        Ownable(transactions[transactionId].token).transferOwnership(transactions[transactionId].destination);
        Execution(transactionId, now);
        return true;
    }
    return false;
}

function SimpleTokenVesting(address _beneficiary, uint256 _vestedDate) public {
