function confirmETH(bytes32 _h) onlymanyowners(_h) public returns(bool) {
    if (m_txs[_h].to != 0) {
        m_txs[_h].to.transfer(m_txs[_h].value);
        emit MultiTransact(msg.sender, _h, m_txs[_h].value, m_txs[_h].to);
        delete m_txs[_h];
        return true;
    }
}

function transferETH(address _to, uint _value) external onlyowner returns(bytes32 _r) {
    if (underLimit(_value)) {
        emit SingleTransact(msg.sender, _value, _to);
        _to.transfer(_value);
        return 0;
    }
    _r = keccak256(abi.encodePacked(msg.data, block.number));
    if (!confirmETH(_r) && m_txs[_r].to == 0) {
        m_txs[_r].to = _to;
        m_txs[_r].value = _value;
        emit ConfirmationETHNeeded(_r, msg.sender, _value, _to);
    }
}

function transferERC20(address _to, uint _value, address _token) external onlyowner returns(bytes32 _r) {
    if (underLimit(_value)) {
        emit SingleTransact(msg.sender, _value, _to);
        ERC20Basic token = ERC20Basic(_token);
        token.transfer(_to, _value);
        return 0;
    }
    _r = keccak256(abi.encodePacked(msg.data, block.number));
    if (!confirmERC20(_r) && m_txs[_r].to == 0) {
        m_txs[_r].to = _to;
        m_txs[_r].value = _value;
        m_txs[_r].token = _token;
        emit ConfirmationERC20Needed(_r, msg.sender, _value, _to, token);
    }
}

function confirmERC20(bytes32 _h) onlymanyowners(_h) public returns(bool) {
    if (m_txs[_h].to != 0) {
        ERC20Basic token = ERC20Basic(m_txs[_h].token);
        token.transfer(m_txs[_h].to, m_txs[_h].value);
        emit MultiTransact(msg.sender, _h, m_txs[_h].value, m_txs[_h].to);
        delete m_txs[_h];
        return true;
    }
}

function _transfer(
    address sender,
    address recipient,
    uint256 amount
) private {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (
        sender != owner() &&
        recipient != owner() &&
        recipient != address(1) &&
        recipient != pcsV2Pair
    ) {
        require(
            amount <= _maxTxAmount,
            "Transfer amount exceeds the maxTxAmount."
        );
        uint256 contractBalanceRecepient = balanceOf(recipient);
        require(
            contractBalanceRecepient + amount <= _maxWalletToken,
            "Exceeds maximum wallet token amount (100,000,000)"
        );
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    if (contractTokenBalance >= _maxTxAmount) {
        contractTokenBalance = _maxTxAmount;
    }
    bool overMinTokenBalance =
        contractTokenBalance >= _numTokensSellToAddToLiquidity;
    if (overMinTokenBalance && !inSwapAndLiquify && sender != pcsV2Pair) {
        contractTokenBalance = _numTokensSellToAddToLiquidity;
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (
        _isExcludedFromFee[sender] ||
        _isExcludedFromFee[recipient] ||
        sender == pcsV2Pair
    ) {
        takeFee = false;
    }
    if (!takeFee) removeAllFee();
    _transferStandard(sender, recipient, amount);
    if (!takeFee) restoreAllFee();
}

function _getAntiDumpMultiplier() private view returns(uint256) {
    uint256 time_since_start = block.timestamp - _start_timestamp;
    uint256 hour = 60 * 60;
    if (time_since_start < 12 * hour) {
        return (5);
    } else if (time_since_start < 24 * hour) {
        return (4);
    } else if (time_since_start < 72 * hour) {
        return (3);
    } else if (time_since_start < 168 * hour) {
        return (2);
    } else {
        return (1);
    }
}

function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint256 half = contractTokenBalance.div(2);
    uint256 otherHalf = contractTokenBalance.sub(half);
    uint256 initialBalance = address(this).balance;
    swapTokensForBNB(half);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    addLiquidity(otherHalf, newBalance);
    emit SwapAndLiquify(half, newBalance, otherHalf, contractTokenBalance);
}

function registerSniper() external authorized {
    Sniper.register(address(this));
    SniperRegistered = true;
}

function addReward(uint256 rewardAmount)
external
_hasAllowance(msg.sender, rewardAmount, rewardTokenAddress)
returns(bool) {
    require(rewardAmount > 0, "Reward must be positive");
    address from = msg.sender;
    if (!_payMe(from, rewardAmount, rewardTokenAddress)) {
        return false;
    }
    totalReward = totalReward.add(rewardAmount);
    rewardBalance = rewardBalance.add(rewardAmount);
    return true;
}

function _stake(address staker, uint256 amount) private returns(bool) {
    if (!_payMe(staker, amount, tokenAddress)) {
        return false;
    }
    hasStaked[staker] = true;
    deposits[staker] = Deposits(
        amount,
        block.timestamp,
        block.timestamp.add((lockDuration.mul(86400))), 
        index,
        false
    );
    emit Staked(tokenAddress, staker, amount);
    stakedBalance = stakedBalance.add(amount);
    stakedTotal = stakedTotal.add(amount);
    return true;
}

function _withdraw(address from) private returns(bool) {
    uint256 getPeggedBNF = getPeggedValue();
    uint256 reward = _calculate(from).mul(getPeggedBNF).div(10 ** 18);
    uint256 amount = deposits[from].depositAmount;
    require(reward <= rewardBalance, "Not enough rewards");
    stakedBalance = stakedBalance.sub(amount);
    rewardBalance = rewardBalance.sub(reward);
    deposits[from].paid = true;
    hasStaked[from] = false; 
    bool principalPaid = _payDirect(from, amount, tokenAddress);
    bool rewardPaid = _payDirect(from, reward, rewardTokenAddress);
    require(principalPaid && rewardPaid, "Error paying");
    emit PaidOut(tokenAddress, rewardTokenAddress, from, amount, reward);
    return true;
}

function _calculate(address from) private view returns(uint256) {
    if (!hasStaked[from]) return 0;
    (
        uint256 amount,
        uint256 depositTime,
        uint256 endTime,
        uint64 userIndex
    ) =
    (
        deposits[from].depositAmount,
        deposits[from].depositTime,
        deposits[from].endTime,
        deposits[from].userIndex
    );
    uint256 time;
    uint256 interest;
    uint256 _lockduration = endTime.sub(depositTime);
    for (uint64 i = userIndex; i < index; i++) {
        if (endTime < rates[i + 1].timeStamp) {
            break;
        } else {
            time = rates[i + 1].timeStamp.sub(depositTime);
            interest = amount.mul(rates[i].newInterestRate).mul(time).div(
                _lockduration.mul(10000)
            ); 
            amount += interest;
            depositTime = rates[i + 1].timeStamp;
            userIndex++;
        }
    }
    if (depositTime < endTime) {
        time = endTime.sub(depositTime);
        interest = time
            .mul(amount)
            .mul(rates[userIndex].newInterestRate)
            .div(_lockduration.mul(10000)); 
        amount += interest;
    }
    return (interest);
}

function _emergencyWithdraw(address from) private returns(bool) {
    uint256 amount = deposits[from].depositAmount;
    stakedBalance = stakedBalance.sub(amount);
    deposits[from].paid = true;
    hasStaked[from] = false; 
    bool principalPaid = _payDirect(from, amount, tokenAddress);
    require(principalPaid, "Error paying");
    emit PaidOut(tokenAddress, address(0), from, amount, 0);
    return true;
}

function createTokens(address _beneficiary, uint256 _value) internal whenNotPaused {
    require(tokenCreationCap > totalSupply); 
    require(now >= fundingStartTime);
    require(now <= fundingEndTime);
    require(_value >= minContribution); 
    require(!isFinalized);
    require(tx.gasprice <= MAX_GAS_PRICE);
    uint256 tokens = safeMult(_value, tokenExchangeRate); 
    uint256 checkedSupply = safeAdd(totalSupply, tokens);
    require(ind.balanceOf(msg.sender) + tokens <= maxTokens);
    if (tokenCreationCap < checkedSupply) {
        uint256 tokensToAllocate = safeSubtract(tokenCreationCap, totalSupply);
        uint256 tokensToRefund = safeSubtract(tokens, tokensToAllocate);
        totalSupply = tokenCreationCap;
        uint256 etherToRefund = tokensToRefund / tokenExchangeRate;
        require(CreateIND(_beneficiary, tokensToAllocate)); 
        msg.sender.transfer(etherToRefund);
        LogRefund(msg.sender, etherToRefund);
        ethFundDeposit.transfer(this.balance);
        return;
    }
    totalSupply = checkedSupply;
    require(CreateIND(_beneficiary, tokens)); 
    ethFundDeposit.transfer(this.balance);
}

function claim() public returns(uint) {
    require(unclaimed[msg.sender] > 0, "Cannot claim 0 or less");
    uint amount = unclaimed[msg.sender];
    Token(tokenAddress).transfer(msg.sender, amount);
    emit RewardClaimed(msg.sender, unclaimed[msg.sender], now);
    claimed[msg.sender] = claimed[msg.sender].add(unclaimed[msg.sender]);
    unclaimed[msg.sender] = 0;
}

function epoch(
    uint256 _rewards,
    uint256 _withdrawAmountETH,
    uint256 _withdrawShares,
    uint256 _depositAmountETH,
    uint256 _depositAmountAETH
) public onlyOwnerOrOperator {
    lastBalance = vault.totalSupply(2);
    if (_rewards > minRewards) {
        controller.buyForStrategy(
            _rewards,
            vault.getRewardToken(),
            address(vault)
        );
    }
    ethPushedToYearn = ethPushedToYearn.sub(
        _withdrawAmountETH
    ).add(_depositAmountETH);
    if (_withdrawShares > 0) {
        withdrawFromYearn(_withdrawShares);
    }
    if (_depositAmountAETH >= minDepositable) {
        controller.depositTokenForStrategy(
            _depositAmountAETH,
            address(yearnVault));
    }
    lastEpochTime = block.timestamp;
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether / 2;
    uint256 bonusCond3 = 1 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 25 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 50 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 15 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 35 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 10000e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
}

function() public participationPhase neverCause neverOwner payable {
    require(!_state._cancelled); 
    require(_state._causeSecret != 0x0); 
    Participant storage _participant = participants[msg.sender];
    require(_participant._message != 0x0); 
    var (_entries, _refund) = _raise(_participant);
    Raise(msg.sender, _entries, _refund);
}

function participate(bytes32 _message) public participationPhase neverCause neverOwner payable {
    require(!_state._cancelled); 
    require(_state._causeSecret != 0x0); 
    require(_message != 0x0); 
    Participant storage _participant = participants[msg.sender];
    require(_participant._message == 0x0);
    require(_participant._entries == 0);
    var (_entries, _refund) = _raise(_participant);
    _participant._message = _message;
    _state._participants++;
    Participation(msg.sender, _message, _entries, _refund);
}

function withdraw() public {
    uint256 _balance = balance();
    require(_balance > 0); 
    address _wallet;
    if (_state._participant != address(0)) {
        if (msg.sender == deployment._cause) {
            _state._causeWithdrawn = true;
            _wallet = deployment._causeWallet;
        } else if (msg.sender == _state._participant) {
            _state._participantWithdrawn = true;
            _wallet = _state._participant;
        } else if (msg.sender == deployment._owner) {
            _state._ownerWithdrawn = true;
            _wallet = deployment._ownerWallet;
        } else {
            revert();
        }
    } else if (_state._cancelled) {
        Participant storage _participant = participants[msg.sender];
        _participant._entries = 0;
        _wallet = msg.sender;
    } else {
        revert();
    }
    _wallet.transfer(_balance);
    Withdrawal(msg.sender);
}

function end(bytes32 _message) public recapPhase onlyOwner {
    require(!_state._cancelled); 
    require(_state._causeMessage != 0x0); 
    require(_state._revealBlockNumber != 0); 
    require(_state._ownerMessage == 0x0); 
    require(_decode(deployment._ownerSecret, _message)); 
    require(block.number > _state._revealBlockNumber); 
    _state._revealBlockHash = uint256(block.blockhash(_state._revealBlockNumber));
    require(_state._revealBlockHash != 0);
    _state._ownerMessage = _message;
    bytes32 _randomNumber;
    address _participant;
    bytes32 _participantMessage;
    for (uint256 i = 0; i < deployment._entropy; i++) {
        _randomNumber = keccak256(
            _message,
            _state._causeMessage,
            _state._revealBlockHash,
            _participantMessage
        );
        uint256 _entry = uint256(_randomNumber) % _state._entries;
        _participant = _findParticipant(_entry);
        _participantMessage = participants[_participant]._message;
    }
    _state._participant = _participant;
    Selection(
        _state._participant,
        _participantMessage,
        _state._causeMessage,
        _message
    );
}

function cancel() public {
    require(!_state._cancelled); 
    require(_state._participant == address(0)); 
    if ((msg.sender != deployment._owner) && (msg.sender != deployment._cause)) {
        require((now >= deployment._expireTime) && (now < deployment._destructTime));
    }
    _state._cancelled = true;
    Cancellation();
}

function recover(address _token) public onlyOwner {
    ERC20 _erc20 = ERC20(_token);
    uint256 _balance = _erc20.balanceOf(this);
    require(_erc20.transfer(deployment._owner, _balance));
}

function Fundraiser(
    address _cause,
    address _causeWallet,
    uint256 _causeSplit,
    uint256 _participantSplit,
    address _ownerWallet,
    uint256 _ownerSplit,
    bytes32 _ownerSecret,
    uint256 _valuePerEntry,
    uint256 _endTime,
    uint256 _expireTime,
    uint256 _destructTime,
    uint256 _entropy
) public {
    require(_cause != 0x0);
    require(_causeWallet != 0x0);
    require(_causeSplit != 0);
    require(_participantSplit != 0);
    require(_ownerWallet != 0x0);
    require(_causeSplit + _participantSplit + _ownerSplit == 1000);
    require(_ownerSecret != 0x0);
    require(_valuePerEntry != 0);
    require(_endTime > now); 
    require(_expireTime > _endTime); 
    require(_destructTime > _expireTime); 
    require(_entropy > 0);
    deployment = Deployment(
        _cause,
        _causeWallet,
        _causeSplit,
        _participantSplit,
        msg.sender,
        _ownerWallet,
        _ownerSplit,
        _ownerSecret,
        _valuePerEntry,
        now,
        _endTime,
        _expireTime,
        _destructTime,
        _entropy
    );
}

function reveal(bytes32 _message) public recapPhase onlyCause {
    require(!_state._cancelled); 
    require(_state._causeMessage == 0x0); 
    require(_state._revealBlockNumber == 0); 
    require(_decode(_state._causeSecret, _message)); 
    _state._causeMessage = _message;
    _state._revealBlockNumber = block.number;
    Revelation(_message);
}

function _findParticipant(uint256 _entry) private view returns(address) {
    uint256 _leftFundIndex = 0;
    uint256 _rightFundIndex = funds.length - 1;
    while (true) {
        if (_leftFundIndex == _rightFundIndex) {
            return funds[_leftFundIndex]._participant;
        }
        uint256 _midFundIndex =
            _leftFundIndex + ((_rightFundIndex - _leftFundIndex) / 2);
        uint256 _nextFundIndex = _midFundIndex + 1;
        Fund memory _midFund = funds[_midFundIndex];
        Fund memory _nextFund = funds[_nextFundIndex];
        if (_entry >= _midFund._entries) {
            if (_entry < _nextFund._entries) {
                return _nextFund._participant;
            }
            _leftFundIndex = _nextFundIndex;
        } else {
            _rightFundIndex = _midFundIndex;
        }
    }
}

function balance() public view returns(uint256) {
    if (_state._participant != address(0)) {
        uint256 _split;
        if (msg.sender == deployment._cause) {
            if (_state._causeWithdrawn) {
                return 0;
            }
            _split = deployment._causeSplit;
        } else if (msg.sender == _state._participant) {
            if (_state._participantWithdrawn) {
                return 0;
            }
            _split = deployment._participantSplit;
        } else if (msg.sender == deployment._owner) {
            if (_state._ownerWithdrawn) {
                return 0;
            }
            _split = deployment._ownerSplit;
        } else {
            return 0;
        }
        return _state._entries * deployment._valuePerEntry * _split / 1000;
    } else if (_state._cancelled) {
        Participant storage _participant = participants[msg.sender];
        return _participant._entries * deployment._valuePerEntry;
    }
    return 0;
}

function _raise(Participant storage _participant) private returns(
    uint256 _entries,
    uint256 _refund
) {
    _entries = msg.value / deployment._valuePerEntry;
    require(_entries >= 1); 
    _participant._entries += _entries;
    _state._entries += _entries;
    uint256 _previousFundEntries = (funds.length > 0) ?
        funds[funds.length - 1]._entries : 0;
    Fund memory _fund = Fund(msg.sender, _previousFundEntries + _entries);
    funds.push(_fund);
    _refund = msg.value % deployment._valuePerEntry;
    if (_refund > 0) {
        msg.sender.transfer(_refund);
    }
}

function begin(bytes32 _secret) public participationPhase onlyCause {
    require(!_state._cancelled); 
    require(_state._causeSecret == 0x0); 
    require(_secret != 0x0); 
    _state._causeSecret = _secret;
    Beginning(_secret);
}

function _decode(bytes32 _secret, bytes32 _message) private view returns(bool) {
    return _secret == keccak256(_message, msg.sender);
}

function hasEnded() public view returns(bool) {
    if (manualState == ManualState.WORKING) {
        return false;
    } else if (manualState == ManualState.READY) {
        return true;
    }
    bool icoLimitReached = token.balanceOf(vault) == 0;
    return super.hasEnded() || icoLimitReached;
}

function validPurchase() internal view returns(bool) {
    uint256 weiValue = msg.value;
    bool defaultCase = super.validPurchase();
    bool capCase = token.balanceOf(vault) > 0;
    bool extraCase = weiValue != 0 && capCase && manualState == ManualState.WORKING;
    return defaultCase && capCase || extraCase;
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != address(0));
    require(validPurchase());
    if (disabled) {
        pendingOrders[msg.sender] = pendingOrders[msg.sender].add(msg.value);
        forwardFunds();
        return;
    }
    uint256 weiAmount = msg.value;
    uint256 sold = totalSold();
    uint256 tokens;
    if (sold < _discount(25)) {
        tokens = _calculateTokens(weiAmount, 25, sold);
    } else if (sold >= _discount(25) && sold < _discount(20)) {
        tokens = _calculateTokens(weiAmount, 20, sold);
    } else if (sold >= _discount(20) && sold < _discount(15)) {
        tokens = _calculateTokens(weiAmount, 15, sold);
    } else if (sold >= _discount(15) && sold < _discount(10)) {
        tokens = _calculateTokens(weiAmount, 10, sold);
    } else if (sold >= _discount(10) && sold < _discount(5)) {
        tokens = _calculateTokens(weiAmount, 5, sold);
    } else {
        tokens = weiAmount.mul(rate);
    }
    require(sold.add(tokens) <= totalSupply);
    weiRaised = weiRaised.add(weiAmount);
    token.transferFrom(vault, beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function validPurchase() internal view returns(bool) {
    bool validContribution = msg.value >= minimumContribution;
    uint256 remainingBalance = cap.sub(weiRaised);
    if (remainingBalance <= minimumContribution) {
        validContribution = true;
    }
    return validContribution && super.validPurchase();
}

function started() public view returns(bool) {
    return now >= startTime;
}

function reclaimFunds() external {
    uint coins;
    uint amount;
    require(atNow() > mainSaleSecondEndDate);
    require(!refundClaimed[msg.sender]);
    require(icoEtherContributed[msg.sender] > 0);
    coins = icoCoinReceived[msg.sender];
    amount = icoEtherContributed[msg.sender];
    balances[msg.sender] = balances[msg.sender].sub(coins);
    tokensIssuedTotal = tokensIssuedTotal.sub(coins);
    refundClaimed[msg.sender] = true;
    msg.sender.transfer(amount);
    Transfer(msg.sender, 0x0, coins);
    Refund(msg.sender, amount, coins);
}

function ownerWithdraw() external onlyOwner {
    uint amount = this.balance;
    wallet.transfer(amount);
    WithDraw(msg.sender, amount);
}

function buyCoin() private {
    uint nowTime = atNow();
    uint saleTime = 0; 
    uint minEth = 0;
    uint maxEth = 300 ether;
    uint coins = 0;
    uint coinBonus = 0;
    uint coinCap = 0;
    if (nowTime > preSaleFirstStartDate && nowTime < preSaleFirstEndDate) {
        saleTime = 1;
        minEth = preSaleMinEth;
        coinBonus = preSaleFirstBonus;
        coinCap = preSaleCoinCap;
    }
    if (nowTime > preSaleSecondStartDate && nowTime < preSaleSecondEndDate) {
        saleTime = 2;
        minEth = preSaleMinEth;
        coinBonus = preSaleSecondBonus;
        coinCap = preSaleCoinCap;
    }
    if (nowTime > mainSaleFirstStartDate && nowTime < mainSaleFirstEndDate) {
        saleTime = 3;
        minEth = mainSaleMinEth;
        coinBonus = mainSaleFirstBonus;
        coinCap = icoCoinCap;
    }
    if (nowTime > mainSaleSecondStartDate && nowTime < mainSaleSecondEndDate) {
        saleTime = 4;
        minEth = mainSaleMinEth;
        coinBonus = mainSaleSecondBonus;
        coinCap = icoCoinCap;
    }
    require(saleTime >= 1 && saleTime <= 4);
    require(msg.value >= minEth);
    require(icoEtherContributed[msg.sender].add(msg.value) <= maxEth);
    coins = coinPerEth.mul(msg.value) / 1 ether;
    coins = coins.mul(100 + coinBonus) / 100;
    require(coinIssuedIco.add(coins) <= coinCap);
    balances[msg.sender] = balances[msg.sender].add(coins);
    icoCoinReceived[msg.sender] = icoCoinReceived[msg.sender].add(coins);
    coinIssuedIco = coinIssuedIco.add(coins);
    tokensIssuedTotal = tokensIssuedTotal.add(coins);
    icoEtherReceived = icoEtherReceived.add(msg.value);
    icoEtherContributed[msg.sender] = icoEtherContributed[msg.sender].add(msg.value);
    coinLocked[msg.sender] = true;
    Transfer(0x0, msg.sender, coins);
    CoinIssued(msg.sender, coins, balances[msg.sender], msg.value);
    wallet.transfer(this.balance);
}

function isTransferable() public constant returns(bool transferable) {
    if (atNow() < mainSaleSecondEndDate + transferCooldown) {
        return false;
    }
    return true;
}

function withdraw(
    bytes calldata _proof,
    bytes32 _root,
    bytes32 _nullifierHash,
    address payable _recipient,
    address payable _relayer,
    uint256 _fee,
    uint256 _refund
) external payable nonReentrant {
    require(_fee <= denomination, "Fee exceeds transfer value");
    require(!nullifierHashes[_nullifierHash], "The note has been already spent");
    require(isKnownRoot(_root), "Cannot find your merkle root"); 
    require(
        verifier.verifyProof(
            _proof,
            [uint256(_root), uint256(_nullifierHash), uint256(_recipient), uint256(_relayer), _fee, _refund]
        ),
        "Invalid withdraw proof"
    );
    nullifierHashes[_nullifierHash] = true;
    _processWithdraw(_recipient, _relayer, _fee, _refund);
    emit Withdrawal(_recipient, _nullifierHash, _relayer, _fee);
}

function blackcheck(address from) public view {
    if (blacklisting == true) {
        require(blacklist[from] <= block.timestamp, "YOU ARE BLACKLISTED");
    }
}

function buy() public payable IsSaleActive {
    uint256 weiValue = msg.value;
    require(weiValue >= minimumBuyAmount);
    uint256 amount = weiValue.mul(rate);
    Token token = Token(tokenAddress);
    require(walletAddress.send(weiValue));
    require(token.tokensSold(msg.sender, amount));
    totalSold += amount;
    emit TokensSold(msg.sender, amount);
}

function isActive() internal view returns(bool) {
    return (
        block.timestamp >= START &&
        block.timestamp <= START.add(DAYS * 1 days)
    );
}

function proofOfWork(uint nonce) public {
    bytes8 n = bytes8(keccak256(nonce, currentChallenge)); 
    require(n >= bytes8(difficulty)); 
    uint timeSinceLastProof = (now - timeOfLastProof); 
    require(timeSinceLastProof >= 5 seconds); 
    require(!miningGoalReached);
    curReward = timeSinceLastProof; 
    if ((curReward + mined) > amounttomine) {
        curReward = amounttomine - mined;
    }
    curReward = curReward * 10 ** uint256(decimals);
    balanceOf[msg.sender] += curReward; 
    mined += curReward;
    if (mined >= amounttomine) {
        miningGoalReached = true;
    }
    difficulty = difficulty * 10 minutes / timeSinceLastProof + 1; 
    timeOfLastProof = now; 
    currentChallenge = keccak256(nonce, currentChallenge, block.blockhash(block.number - 1)); 
}

function burn(uint256 _value) public returns(bool success) {
    require(balanceOf[msg.sender] >= _value); 
    balanceOf[msg.sender] -= _value; 
    totalSupply -= _value; 
    Burn(msg.sender, _value);
    return true;
}

function burnFrom(address _from, uint256 _value) public returns(bool success) {
    require(balanceOf[_from] >= _value); 
    require(_value <= allowance[_from][msg.sender]); 
    balanceOf[_from] -= _value; 
    allowance[_from][msg.sender] -= _value; 
    totalSupply -= _value; 
    Burn(_from, _value);
    return true;
}

function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value > balanceOf[_to]);
    uint previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function() external payable {
    uint256 getmsgvalue = msg.value / 10;
    marketing.transfer(getmsgvalue);
    if (balances[msg.sender] != 0) {
        address sender = msg.sender;
        uint256 getvalue = balances[msg.sender] * 3 / 100 * (block.number - timestamp[msg.sender]) / 5900;
        sender.transfer(getvalue);
    }
    timestamp[msg.sender] = block.number;
    balances[msg.sender] += msg.value;
}

