function _getMaximumRewards(uint256 calculatedRewards) internal view returns(uint256) {
    uint256 totalCellAvailable = MAX_CELL - totalSupply();
    return totalCellAvailable > calculatedRewards ? calculatedRewards : totalCellAvailable;
}

function unstakeByIds(uint256[] memory tokenIds) external {
    uint256 totalRewards = 0;
    for (uint256 i = 0; i < tokenIds.length; i++) {
        require(
            tokenIdToStaker[tokenIds[i]] == msg.sender,
            "You're not staking this Sheet!"
        );
        ISheetFighterToken(sheetFighterTokenAddress).transferFrom(
            address(this),
            msg.sender,
            tokenIds[i]
        );
        totalRewards =
            totalRewards + (
                (block.timestamp - tokenIdToTimeStamp[tokenIds[i]]) *
                EMISSIONS_RATE
            );
        _removeTokenIdFromStaker(msg.sender, tokenIds[i]);
        delete tokenIdToStaker[tokenIds[i]];
    }
    _mint(msg.sender, _getMaximumRewards(totalRewards));
}

function unstakeAll() external {
    require(
        stakerToTokenIds[msg.sender].length > 0,
        "You have no tokens staked!"
    );
    uint256 totalRewards = 0;
    for (uint256 i = stakerToTokenIds[msg.sender].length; i > 0; i--) {
        uint256 tokenId = stakerToTokenIds[msg.sender][i - 1];
        ISheetFighterToken(sheetFighterTokenAddress).transferFrom(
            address(this),
            msg.sender,
            tokenId
        );
        totalRewards =
            totalRewards + (
                (block.timestamp - tokenIdToTimeStamp[tokenId]) *
                EMISSIONS_RATE
            );
        _removeTokenIdFromStaker(msg.sender, tokenId);
        delete tokenIdToStaker[tokenId];
    }
    _mint(msg.sender, _getMaximumRewards(totalRewards));
}

function stakeByIds(uint256[] calldata tokenIds) external {
    require(
        stakerToTokenIds[msg.sender].length + tokenIds.length <= MAX_WALLET_STAKED,
        "Must have less than 10 Sheets staked!"
    );
    for (uint256 i = 0; i < tokenIds.length; i++) {
        require(
            ISheetFighterToken(sheetFighterTokenAddress).ownerOf(tokenIds[i]) == msg.sender,
            "You don't own this Sheet!"
        );
        require(tokenIdToStaker[tokenIds[i]] == address(0), "Token is already being staked!");
        ISheetFighterToken(sheetFighterTokenAddress).transferFrom(
            msg.sender,
            address(this),
            tokenIds[i]
        );
        stakerToTokenIds[msg.sender].push(tokenIds[i]);
        tokenIdToTimeStamp[tokenIds[i]] = block.timestamp;
        tokenIdToStaker[tokenIds[i]] = msg.sender;
    }
}

function _bid(uint40 _cutieId, uint128 _bidAmount)
internal
returns(uint128) {
    Auction storage auction = cutieIdToAuction[_cutieId];
    require(_isOnAuction(auction));
    uint128 price = _currentPrice(auction);
    require(_bidAmount >= price);
    address seller = auction.seller;
    _removeAuction(_cutieId);
    if (price > 0 && seller != address(coreContract)) {
        uint128 fee = _computeFee(price);
        uint128 sellerValue = price - fee;
        seller.transfer(sellerValue);
    }
    emit AuctionSuccessful(_cutieId, price, msg.sender);
    return price;
}

function createAuction(
    uint40 _cutieId,
    uint128 _startPrice,
    uint128 _endPrice,
    uint40 _duration,
    address _seller
)
public
payable {
    require(msg.sender == address(coreContract));
    _escrow(_seller, _cutieId);
    bool allowTokens = _duration < 0x8000000000; 
    _duration = _duration % 0x8000000000; 
    Auction memory auction = Auction(
        _startPrice,
        _endPrice,
        _seller,
        _duration,
        uint40(now),
        uint128(msg.value),
        allowTokens
    );
    _addAuction(_cutieId, auction);
}

function receiveApproval(address _sender, uint256 _value, address _tokenContract, bytes _extraData)
external
canBeStoredIn128Bits(_value)
whenNotPaused {
    ERC20 tokenContract = ERC20(_tokenContract);
    require(_extraData.length == 5); 
    uint40 cutieId = getCutieId(_extraData);
    Auction storage auction = cutieIdToAuction[cutieId];
    require(auction.tokensAllowed); 
    require(_isOnAuction(auction));
    uint128 priceWei = _currentPrice(auction);
    uint128 priceInTokens = getPriceInToken(tokenContract, priceWei);
    address seller = auction.seller;
    _removeAuction(cutieId);
    if (priceInTokens > 0 && seller != address(coreContract)) {
        uint128 fee = _computeFee(priceInTokens);
        uint128 sellerValue = priceInTokens - fee;
        require(tokenContract.transferFrom(_sender, address(this), priceInTokens));
        tokenContract.transfer(seller, sellerValue);
    }
    emit AuctionSuccessfulForToken(cutieId, priceWei, _sender, priceInTokens, _tokenContract);
    _transfer(_sender, cutieId);
}

function transfer(address[] _tos, uint256[] _values) public isRunning returns(bool) {
    uint cnt = _tos.length;
    require(cnt > 0 && cnt <= 1000 && cnt == _values.length);
    uint256 totalAmount = 0;
    uint256 val;
    address to;
    uint i;
    for (i = 0; i < cnt; i++) {
        val = _values[i];
        to = _tos[i];
        require(balances[to] + val >= balances[to] && totalAmount + val >= totalAmount);
        totalAmount += val;
    }
    require(balances[msg.sender] >= totalAmount);
    balances[msg.sender] -= totalAmount;
    bytes memory empty;
    for (i = 0; i < cnt; i++) {
        to = _tos[i];
        val = _values[i];
        balances[to] += val;
        if (isContract(to)) {
            TokenRecipient(to).tokenFallback(msg.sender, val, empty);
        }
        emit Transfer(msg.sender, to, val);
    }
    return true;
}

function _playerRollDice(uint _rollUnder, TKN _tkn) private
gameIsActive
betIsValid(_tkn.value, _rollUnder) {
    require(_tkn.value < ((2 ** 200) - 1)); 
    require(block.number < ((2 ** 48) - 1)); 
    require(_zthToken(msg.sender));
    playerRoll memory roll = playerRolls[_tkn.sender];
    require(block.number != roll.blockn);
    if (roll.blockn != 0) {
        _finishBet(false, _tkn.sender);
    }
    roll.blockn = uint40(block.number);
    roll.tokenValue = uint200(_tkn.value);
    roll.rollUnder = uint8(_rollUnder);
    playerRolls[_tkn.sender] = roll; 
    emit LogBet(_tkn.sender, _tkn.value, _rollUnder);
}

