function delegateBySig(address delegatee, uint nonce, uint expiry, uint8 v, bytes32 r, bytes32 s) public {
    bytes32 structHash = keccak256(abi.encode(DELEGATION_TYPEHASH, delegatee, nonce, expiry));
    bytes32 digest = keccak256(abi.encodePacked("\x19\x01", domainSeparator, structHash));
    address signatory = ecrecover(digest, v, r, s);
    require(signatory != address(0), "Nova::delegateBySig: invalid signature");
    require(nonce == nonces[signatory]++, "Nova::delegateBySig: invalid nonce");
    require(block.timestamp <= expiry, "Nova::delegateBySig: signature expired");
    return _delegate(signatory, delegatee);
}

function unlock(uint8 mode, uint8 round) public {
    require(msg.sender == owner);
    require(mode < 5);
    if (mode < 2) require(round < 20); 
    else if (mode == 2) require(round == 11); 
    else if (mode == 3) require(round == 0); 
    else if (mode == 4) require(round == 0); 
    require(now >= unlockTime[round]);
    require(!unlockCheck[mode * 20 + round]);
    unlockCheck[mode * 20 + round] = true;
    _burn(address(this), unlockAmount[mode] * (10 ** uint256(decimals())));
    _mint(msg.sender, unlockAmount[mode] * (10 ** uint256(decimals())));
}

