function getRateAt(uint256 at) public constant returns(uint256) {
    if (at < startDate) {
        return 0;
    } else if (at < (startDate + 3 days)) {
        return 1500;
    } else if (at < (startDate + 9 days)) {
        return 1440;
    } else if (at < (startDate + 15 days)) {
        return 1380;
    } else if (at < (startDate + 21 days)) {
        return 1320;
    } else if (at < (startDate + 27 days)) {
        return 1260;
    } else if (at <= endDate) {
        return 1200;
    } else {
        return 0;
    }
}

