function listPairForReserve(address reserve, ERC20 src, ERC20 dest, bool add) public onlyAdmin {
    (perReserveListedPairs[reserve])[keccak256(src, dest)] = add;
    if (src != ETH_TOKEN_ADDRESS) {
        if (add) {
            src.approve(reserve, 2 ** 255); 
        } else {
            src.approve(reserve, 0);
        }
    }
    setDecimals(src);
    setDecimals(dest);
    ListReservePairs(reserve, src, dest, add);
}

function doTrade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
internal
returns(bool) {
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS)
            require(msg.value == srcAmount);
        else
            require(msg.value == 0);
    }
    uint destAmount = getDestQty(srcToken, destToken, srcAmount, conversionRate);
    require(destAmount > 0);
    ERC20 token;
    int buy;
    if (srcToken == ETH_TOKEN_ADDRESS) {
        buy = int(destAmount);
        token = destToken;
    } else {
        buy = -1 * int(srcAmount);
        token = srcToken;
    }
    conversionRatesContract.recordImbalance(
        token,
        buy,
        0,
        block.number
    );
    if (srcToken != ETH_TOKEN_ADDRESS) {
        require(srcToken.transferFrom(msg.sender, this, srcAmount));
    }
    if (destToken == ETH_TOKEN_ADDRESS) {
        destAddress.transfer(destAmount);
    } else {
        require(destToken.transfer(destAddress, destAmount));
    }
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, destAmount, destAddress);
    return true;
}

