    return true;
}

function subscribeProduct(uint256 _product_id, uint256 _amount) external whenNotPaused {
    uint256 time = block.timestamp;
    require(_amount > 0, "Amount has to be bigger than 0");
    require(block.timestamp < products[_product_id].endDate, "Already ended the subscription");
    if (block.timestamp < products[_product_id].startDate) {
        time = products[_product_id].startDate;
    }
    require(_amount <= erc20.allowance(msg.sender, address(this)), "Spender not authorized to spend this tokens, allow first");
    require(products[_product_id].totalMaxAmount > (products[_product_id].currentAmount + _amount), "Max Amount was already hit");
    require(_amount >= products[_product_id].individualMinimumAmount, "Has to be highger than minimum");
    require(_amount <= products[_product_id].individualMaximumAmount, "Has to be smaller than maximum");
    uint256 futureAPRAmount = getAPRAmount(products[_product_id].APR, time, products[_product_id].endDate, _amount);
    require(availableTokens() >= futureAPRAmount, "Available Tokens has to be higher than the future APR Amount");
    require(erc20.transferFrom(msg.sender, address(this), _amount), "Transfer Failed");
    lockedTokens = lockedTokens.add(_amount.add(futureAPRAmount));
    uint256 subscription_id = incrementId;
    incrementId = incrementId + 1;
    SubscriptionAPR memory subscriptionAPR = SubscriptionAPR(subscription_id, _product_id, time, products[_product_id].endDate, _amount,
        msg.sender, products[_product_id].APR, false, 0);
    mySubscriptions[msg.sender].push(subscription_id);
    products[_product_id].subscriptionIds.push(subscription_id);
    products[_product_id].subscriptions[subscription_id] = subscriptionAPR;
    products[_product_id].currentAmount = products[_product_id].currentAmount + _amount;
    products[_product_id].subscribers.push(msg.sender);
}

function withdrawSubscription(uint256 _product_id, uint256 _subscription_id) external whenNotPaused {
    require(products[_product_id].endDate != 0, "Product has expired");
    require(products[_product_id].subscriptions[_subscription_id].endDate != 0, "Product does not exist");
    require(products[_product_id].subscriptions[_subscription_id].finalized == false, "Subscription was finalized already");
    require(products[_product_id].subscriptions[_subscription_id].subscriberAddress == msg.sender, "Not the subscription owner");
    SubscriptionAPR memory subscription = products[_product_id].subscriptions[_subscription_id];
    require(block.timestamp > subscription.startDate, "Now is below the start date");
    uint256 finishDate = block.timestamp;
    if (block.timestamp >= products[_product_id].endDate) {
        finishDate = products[_product_id].endDate;
    } else {
        require(products[_product_id].lockedUntilFinalization == false, "Product has to close to be withdrawned");
    }
    uint256 APRedAmount = getAPRAmount(subscription.APR, subscription.startDate, finishDate, subscription.amount);
    require(APRedAmount > 0, "APR amount has to be bigger than 0");
    uint256 totalAmount = subscription.amount.add(APRedAmount);
    uint256 totalAmountWithFullAPR = subscription.amount.add(getAPRAmount(subscription.APR, subscription.startDate, products[_product_id].endDate, subscription.amount));
    require(totalAmount > 0, "Total Amount has to be bigger than 0");
    products[_product_id].subscriptions[_subscription_id].finalized = true;
    products[_product_id].subscriptions[_subscription_id].endDate = finishDate;
    products[_product_id].subscriptions[_subscription_id].withdrawAmount = totalAmount;
    require(erc20.transfer(subscription.subscriberAddress, totalAmount), "Transfer has failed");
    lockedTokens = lockedTokens.sub(totalAmountWithFullAPR);
}

function createProduct(uint256 _startDate, uint256 _endDate, uint256 _totalMaxAmount, uint256 _individualMinimumAmount, uint256 _individualMaximumAmount, uint256 _APR, bool _lockedUntilFinalization) external whenNotPaused onlyOwner {
    require(block.timestamp < _endDate);
    require(block.timestamp <= _startDate);
    require(_startDate < _endDate);
    require(_totalMaxAmount > 0);
    require(_individualMinimumAmount > 0);
    require(_individualMaximumAmount > 0);
    require(_totalMaxAmount > _individualMinimumAmount);
    require(_totalMaxAmount > _individualMaximumAmount);
    require(_APR > 0);
    address[] memory addressesI;
    uint256[] memory subscriptionsI;
    ProductAPR memory productAPR = ProductAPR(block.timestamp, _startDate, _endDate, _totalMaxAmount, _individualMinimumAmount, _individualMaximumAmount, _APR, 0, _lockedUntilFinalization,
        addressesI, subscriptionsI);
    uint256 product_id = productIds.length + 1;
    productIds.push(product_id);
    products[product_id] = productAPR;
}

function buyTokens(address beneficiary) public payable whenNotPaused {
    require(beneficiary != address(0));
    validPurchase();
    uint256 weiAmount = msg.value;
    uint256 tokens = getTokenAmount(weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    tokensSold = tokensSold.add(tokens);
    deposited[msg.sender] = deposited[msg.sender].add(weiAmount);
    uint256 lockedFor = assignTokens(beneficiary, tokens);
    emit TokenPurchase(msg.sender, beneficiary, weiAmount, tokens, lockedFor);
    forwardFunds();
}

function buy(uint256 amount) public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= start, "early");
    require(amount <= supply(), "ordered too many");
    require(amount <= 5, "ordered too many");
    require(msg.value == price.mul(amount), "wrong amount");
    nft.safeTransferFrom(address(this), msg.sender, id, amount, new bytes(0x0));
    multisig.transfer(address(this).balance);
    emit Buy(msg.sender, amount);
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether / 2;
    uint256 bonusCond3 = 1 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 25 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 50 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 100 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 50 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 100 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 1000e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
}

function refund(address buyer) {
    require(state == State.Refunding);
    uint256 depositedValue = deposited[buyer];
    deposited[buyer] = 0;
    buyer.transfer(depositedValue);
    Refunded(buyer, depositedValue);
}

function finalize() onlyOwner {
    require(!isFinalized);
    if (goalReached()) {
        vault.close();
    } else {
        vault.enableRefunds();
    }
    Finalized();
    isFinalized = true;
}

function sendTokens(address beneficiary) onlyOwner {
    require(isFinalized);
    require(goalReached());
    uint256 amount = token.balanceOf(this);
    require(amount > 0);
    uint256 tokens = allocations[beneficiary];
    allocations[beneficiary] = 0;
    require(token.transfer(beneficiary, tokens));
    TokenRedeem(beneficiary, tokens);
}

function claimTokens() {
    require(isFinalized);
    require(goalReached());
    uint256 amount = token.balanceOf(this);
    require(amount > 0);
    uint256 tokens = allocations[msg.sender];
    allocations[msg.sender] = 0;
    require(token.transfer(msg.sender, tokens));
    TokenRedeem(msg.sender, tokens);
}

function hasEnded() public constant returns(bool) {
    bool capReached = weiRaised >= cap;
    bool passedEndTime = now > endTime;
    return passedEndTime || capReached;
}

function validPurchase() internal constant returns(bool) {
    bool withinCap = weiRaised.add(msg.value) <= cap;
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    return withinPeriod && nonZeroPurchase && withinCap;
}

function CirclesTokenOffering(address _token, uint256 _startTime, uint256 _endTime, uint256 _rate, uint256 _cap, uint256 _goal, address _wallet) {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_cap > 0);
    require(_wallet != 0x0);
    require(_goal > 0);
    vault = new RefundVault(_wallet);
    goal = _goal;
    token = StandardToken(_token);
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    cap = _cap;
    goal = _goal;
    wallet = _wallet;
}

function buy() public payable {
    require(block.timestamp < pubEnd); 
    require(msg.value > 0); 
    require(msg.value <= msg.sender.balance + msg.value); 
    require(msg.value >= minPersonalCap); 
    require(msg.value + totalSold <= maxCap);
    uint256 tokenAmount = (msg.value * tokenUnit) / tokenPrice;
    require(tokenAmount + ((totalSold * tokenUnit) / tokenPrice) <= TokenCHK(SpaceImpulseERC20).balanceOf(contractAddr));
    transferBuy(msg.sender, tokenAmount); 
    totalSold = totalSold.add(msg.value); 
    FWDaddrETH.transfer(msg.value); 
}

function withdrawPUB() public returns(bool) {
    require(block.timestamp > pubEnd); 
    require(sold[msg.sender] > 0); 
    if (!SpaceImpulseERC20.call(bytes4(keccak256("transfer(address,uint256)")), msg.sender, sold[msg.sender])) {
        revert();
    }
    delete sold[msg.sender];
    return true;
}

function remainingDurationForWorkClaim(
    bytes32 blockHeader,
    bytes32 seedHash,
    bytes32 target,
    uint blockNumber,
    uint blockPayment,
    address poolOperator,
    address mevProducer,
    uint8 v,
    bytes32 r,
    bytes32 s
) public view returns(uint) {
    bytes32 hash = sha256(abi.encode(blockHeader, seedHash, target, blockNumber, blockPayment, poolOperator));
    if (claimedBlockCost[hash] != 0) return 0;
    if (ecrecover(keccak256(abi.encode("\x19Ethereum Signed Message:\n32", hash)), v, r, s) != mevProducer) return 0;
    if (depositedEther[mevProducer] < blockPayment) return 0;
    if (block.timestamp >= timestampOfPossibleExit[mevProducer]) return 0;
    return timestampOfPossibleExit[mevProducer] - block.timestamp;
}

function withdrawUpTo(uint etherAmount) external {
    require(depositedEther[msg.sender] > 0);
    require(block.timestamp > timestampOfPossibleExit[msg.sender]);
    if (depositedEther[msg.sender] < etherAmount)
        etherAmount = depositedEther[msg.sender];
    require(address(this).balance >= etherAmount);
    depositedEther[msg.sender] -= etherAmount;
    msg.sender.transfer(etherAmount);
    emit Withdraw(msg.sender, etherAmount);
}

function unstake(uint amount) external whenStakingActive {
    require(stakeValue[msg.sender] >= amount, "Cannot unstake more Token than you have staked.");
    _updateCheckpointValueAtNow(
        stakeValueHistory[msg.sender],
        stakeValue[msg.sender],
        stakeValue[msg.sender].sub(amount)
    );
    _updateCheckpointValueAtNow(
        totalStakedHistory,
        totalStaked,
        totalStaked.sub(amount)
    );
    withdraw(dividendsOf(msg.sender));
    if (stakeValue[msg.sender] == amount) totalStakers = totalStakers.sub(1);
    totalStaked = totalStaked.sub(amount);
    stakeValue[msg.sender] = stakeValue[msg.sender].sub(amount);
    stakerPayouts[msg.sender] = uintToInt(profitPerShare.mul(stakeValue[msg.sender]));
    require(token.transferFrom(address(this), msg.sender, amount), "Unstake failed due to failed transfer.");
    emit OnUnstake(msg.sender, amount);
}

function withdraw(uint amount) public whenStakingActive {
    require(dividendsOf(msg.sender) >= amount, "Cannot withdraw more dividends than you have earned.");
    stakerPayouts[msg.sender] = stakerPayouts[msg.sender] + uintToInt(amount.mul(DISTRIBUTION_MULTIPLIER));
    msg.sender.transfer(amount);
    emit OnWithdraw(msg.sender, amount);
}

function deposit(
    address beneficiary,
    uint256 amount
)
external
nonReentrant
returns(uint256) {
    Margin margin = Margin(DYDX_MARGIN);
    bytes32 positionId = POSITION_ID;
    require(
        beneficiary != address(0),
        "BucketLender#deposit: Beneficiary cannot be the zero address"
    );
    require(
        amount != 0,
        "BucketLender#deposit: Cannot deposit zero tokens"
    );
    require(
        !margin.isPositionClosed(positionId),
        "BucketLender#deposit: Cannot deposit after the position is closed"
    );
    require(
        !margin.isPositionCalled(positionId),
        "BucketLender#deposit: Cannot deposit while the position is margin-called"
    );
    rebalanceBucketsInternal();
    OWED_TOKEN.transferFrom(
        msg.sender,
        address(this),
        amount
    );
    uint256 bucket = getCurrentBucket();
    uint256 effectiveAmount = availableForBucket[bucket].add(getBucketOwedAmount(bucket));
    uint256 weightToAdd = 0;
    if (effectiveAmount == 0) {
        weightToAdd = amount; 
    } else {
        weightToAdd = MathHelpers.getPartialAmount(
            amount,
            effectiveAmount,
            weightForBucket[bucket]
        );
    }
    require(
        weightToAdd != 0,
        "BucketLender#deposit: Cannot deposit for zero weight"
    );
    updateAvailable(bucket, amount, true);
    weightForBucketForAccount[bucket][beneficiary] =
        weightForBucketForAccount[bucket][beneficiary].add(weightToAdd);
    weightForBucket[bucket] = weightForBucket[bucket].add(weightToAdd);
    emit Deposit(
        beneficiary,
        bucket,
        amount,
        weightToAdd
    );
    return bucket;
}

function withdrawOwedToken(
    uint256 bucket,
    uint256 userWeight,
    uint256 bucketWeight
)
private
returns(uint256) {
    uint256 owedTokenToWithdraw = MathHelpers.getPartialAmount(
        userWeight,
        bucketWeight,
        availableForBucket[bucket].add(getBucketOwedAmount(bucket))
    );
    require(
        owedTokenToWithdraw <= availableForBucket[bucket],
        "BucketLender#withdrawOwedToken: There must be enough available owedToken"
    );
    updateAvailable(bucket, owedTokenToWithdraw, false);
    return owedTokenToWithdraw;
}

function withdrawSingleBucket(
    address onBehalfOf,
    uint256 bucket,
    uint256 maxWeight,
    uint256 maxHeldToken
)
private
returns(uint256, uint256) {
    uint256 bucketWeight = weightForBucket[bucket];
    if (bucketWeight == 0) {
        return (0, 0);
    }
    uint256 userWeight = weightForBucketForAccount[bucket][onBehalfOf];
    uint256 weightToWithdraw = Math.min256(maxWeight, userWeight);
    if (weightToWithdraw == 0) {
        return (0, 0);
    }
    weightForBucket[bucket] = weightForBucket[bucket].sub(weightToWithdraw);
    weightForBucketForAccount[bucket][onBehalfOf] = userWeight.sub(weightToWithdraw);
    uint256 owedTokenToWithdraw = withdrawOwedToken(
        bucket,
        weightToWithdraw,
        bucketWeight
    );
    uint256 heldTokenToWithdraw = withdrawHeldToken(
        bucket,
        weightToWithdraw,
        bucketWeight,
        maxHeldToken
    );
    emit Withdraw(
        onBehalfOf,
        bucket,
        weightToWithdraw,
        owedTokenToWithdraw,
        heldTokenToWithdraw
    );
    return (owedTokenToWithdraw, heldTokenToWithdraw);
}

function rebalanceBucketsInternal()
private {
    if (wasForceClosed) {
        return;
    }
    uint256 marginPrincipal = Margin(DYDX_MARGIN).getPositionPrincipal(POSITION_ID);
    accountForClose(principalTotal.sub(marginPrincipal));
    assert(principalTotal == marginPrincipal);
}

function getBucketOwedAmount(
    uint256 bucket
)
public
view
returns(uint256) {
    if (Margin(DYDX_MARGIN).isPositionClosed(POSITION_ID)) {
        return 0;
    }
    uint256 lentPrincipal = principalForBucket[bucket];
    if (lentPrincipal == 0) {
        return 0;
    }
    uint256 owedAmount = Margin(DYDX_MARGIN).getPositionOwedAmountAtTime(
        POSITION_ID,
        principalTotal,
        uint32(block.timestamp)
    );
    return MathHelpers.getPartialAmount(
        lentPrincipal,
        principalTotal,
        owedAmount
    );
}

function updateAvailable(
    uint256 bucket,
    uint256 amount,
    bool increase
)
private {
    if (amount == 0) {
        return;
    }
    uint256 newTotal;
    uint256 newForBucket;
    if (increase) {
        newTotal = availableTotal.add(amount);
        newForBucket = availableForBucket[bucket].add(amount);
        emit AvailableIncreased(newTotal, bucket, newForBucket, amount); 
    } else {
        newTotal = availableTotal.sub(amount);
        newForBucket = availableForBucket[bucket].sub(amount);
        emit AvailableDecreased(newTotal, bucket, newForBucket, amount); 
    }
    availableTotal = newTotal;
    availableForBucket[bucket] = newForBucket;
}

function receiveLoanOwnership(
    address from,
    bytes32 positionId
)
external
onlyMargin
nonReentrant
onlyPosition(positionId)
returns(address) {
    MarginCommon.Position memory position = MarginHelper.getPosition(DYDX_MARGIN, POSITION_ID);
    uint256 initialPrincipal = position.principal;
    uint256 minHeldToken = MathHelpers.getPartialAmount(
        uint256(MIN_HELD_TOKEN_NUMERATOR),
        uint256(MIN_HELD_TOKEN_DENOMINATOR),
        initialPrincipal
    );
    assert(initialPrincipal > 0);
    assert(principalTotal == 0);
    assert(from != address(this)); 
    require(
        position.owedToken == OWED_TOKEN,
        "BucketLender#receiveLoanOwnership: Position owedToken mismatch"
    );
    require(
        position.heldToken == HELD_TOKEN,
        "BucketLender#receiveLoanOwnership: Position heldToken mismatch"
    );
    require(
        position.maxDuration == MAX_DURATION,
        "BucketLender#receiveLoanOwnership: Position maxDuration mismatch"
    );
    require(
        position.callTimeLimit == CALL_TIMELIMIT,
        "BucketLender#receiveLoanOwnership: Position callTimeLimit mismatch"
    );
    require(
        position.interestRate == INTEREST_RATE,
        "BucketLender#receiveLoanOwnership: Position interestRate mismatch"
    );
    require(
        position.interestPeriod == INTEREST_PERIOD,
        "BucketLender#receiveLoanOwnership: Position interestPeriod mismatch"
    );
    require(
        Margin(DYDX_MARGIN).getPositionBalance(POSITION_ID) >= minHeldToken,
        "BucketLender#receiveLoanOwnership: Not enough heldToken as collateral"
    );
    principalForBucket[0] = initialPrincipal;
    principalTotal = initialPrincipal;
    weightForBucket[0] = weightForBucket[0].add(initialPrincipal);
    weightForBucketForAccount[0][from] =
        weightForBucketForAccount[0][from].add(initialPrincipal);
    return address(this);
}

function accountForIncrease(
    uint256 principalAdded,
    uint256 lentAmount
)
private {
    require(
        lentAmount <= availableTotal,
        "BucketLender#accountForIncrease: No lending not-accounted-for funds"
    );
    uint256 principalToAdd = principalAdded;
    uint256 availableToSub = lentAmount;
    uint256 criticalBucketTemp;
    uint256 lastBucket = getCurrentBucket();
    for (
        uint256 bucket = criticalBucket; principalToAdd > 0; bucket++
    ) {
        assert(bucket <= lastBucket); 
        uint256 availableTemp = Math.min256(availableToSub, availableForBucket[bucket]);
        if (availableTemp == 0) {
            continue;
        }
        uint256 principalTemp = MathHelpers.getPartialAmount(
            availableTemp,
            availableToSub,
            principalToAdd
        );
        updateAvailable(bucket, availableTemp, false);
        updatePrincipal(bucket, principalTemp, true);
        principalToAdd = principalToAdd.sub(principalTemp);
        availableToSub = availableToSub.sub(availableTemp);
        criticalBucketTemp = bucket;
    }
    assert(principalToAdd == 0);
    assert(availableToSub == 0);
    setCriticalBucket(criticalBucketTemp);
}

function increaseLoanOnBehalfOf(
    address payer,
    bytes32 positionId,
    uint256 principalAdded,
    uint256 lentAmount
)
external
onlyMargin
nonReentrant
onlyPosition(positionId)
returns(address) {
    Margin margin = Margin(DYDX_MARGIN);
    require(
        payer == address(this),
        "BucketLender#increaseLoanOnBehalfOf: Other lenders cannot lend for this position"
    );
    require(
        !margin.isPositionCalled(POSITION_ID),
        "BucketLender#increaseLoanOnBehalfOf: No lending while the position is margin-called"
    );
    uint256 principalAfterIncrease = margin.getPositionPrincipal(POSITION_ID);
    uint256 principalBeforeIncrease = principalAfterIncrease.sub(principalAdded);
    accountForClose(principalTotal.sub(principalBeforeIncrease));
    accountForIncrease(principalAdded, lentAmount);
    assert(principalTotal == principalAfterIncrease);
    return address(this);
}

function accountForClose(
    uint256 principalRemoved
)
private {
    if (principalRemoved == 0) {
        return;
    }
    uint256 newRepaidAmount = Margin(DYDX_MARGIN).getTotalOwedTokenRepaidToLender(POSITION_ID);
    assert(newRepaidAmount.sub(cachedRepaidAmount) >= principalRemoved);
    uint256 principalToSub = principalRemoved;
    uint256 availableToAdd = newRepaidAmount.sub(cachedRepaidAmount);
    uint256 criticalBucketTemp = criticalBucket;
    for (
        uint256 bucket = criticalBucketTemp; principalToSub > 0; bucket--
    ) {
        assert(bucket <= criticalBucketTemp); 
        uint256 principalTemp = Math.min256(principalToSub, principalForBucket[bucket]);
        if (principalTemp == 0) {
            continue;
        }
        uint256 availableTemp = MathHelpers.getPartialAmount(
            principalTemp,
            principalToSub,
            availableToAdd
        );
        updateAvailable(bucket, availableTemp, true);
        updatePrincipal(bucket, principalTemp, false);
        principalToSub = principalToSub.sub(principalTemp);
        availableToAdd = availableToAdd.sub(availableTemp);
        criticalBucketTemp = bucket;
    }
    assert(principalToSub == 0);
    assert(availableToAdd == 0);
    setCriticalBucket(criticalBucketTemp);
    cachedRepaidAmount = newRepaidAmount;
}

function withdraw(
    uint256[] buckets,
    uint256[] maxWeights,
    address onBehalfOf
)
external
nonReentrant
returns(uint256, uint256) {
    require(
        buckets.length == maxWeights.length,
        "BucketLender#withdraw: The lengths of the input arrays must match"
    );
    if (onBehalfOf != msg.sender) {
        require(
            TRUSTED_WITHDRAWERS[msg.sender],
            "BucketLender#withdraw: Only trusted withdrawers can withdraw on behalf of others"
        );
    }
    rebalanceBucketsInternal();
    uint256 lockedBucket = 0;
    if (
        Margin(DYDX_MARGIN).containsPosition(POSITION_ID) &&
        criticalBucket == getCurrentBucket()
    ) {
        lockedBucket = criticalBucket;
    }
    uint256[2] memory results; 
    uint256 maxHeldToken = 0;
    if (wasForceClosed) {
        maxHeldToken = HELD_TOKEN.balanceOf(address(this));
    }
    for (uint256 i = 0; i < buckets.length; i++) {
        uint256 bucket = buckets[i];
        if ((bucket != 0) && (bucket == lockedBucket)) {
            continue;
        }
        (uint256 owedTokenForBucket, uint256 heldTokenForBucket) = withdrawSingleBucket(
            onBehalfOf,
            bucket,
            maxWeights[i],
            maxHeldToken
        );
        results[0] = results[0].add(owedTokenForBucket);
        results[1] = results[1].add(heldTokenForBucket);
    }
    OWED_TOKEN.transfer(msg.sender, results[0]);
    HELD_TOKEN.transfer(msg.sender, results[1]);
    return (results[0], results[1]);
}

function updatePrincipal(
    uint256 bucket,
    uint256 amount,
    bool increase
)
private {
    if (amount == 0) {
        return;
    }
    uint256 newTotal;
    uint256 newForBucket;
    if (increase) {
        newTotal = principalTotal.add(amount);
        newForBucket = principalForBucket[bucket].add(amount);
        emit PrincipalIncreased(newTotal, bucket, newForBucket, amount); 
    } else {
        newTotal = principalTotal.sub(amount);
        newForBucket = principalForBucket[bucket].sub(amount);
        emit PrincipalDecreased(newTotal, bucket, newForBucket, amount); 
    }
    principalTotal = newTotal;
    principalForBucket[bucket] = newForBucket;
}

function forceRecoverCollateralInternal(
    address recipient
)
internal
returns(address) {
    require(
        recipient == address(this),
        "BucketLender#forceRecoverCollateralOnBehalfOf: Recipient must be this contract"
    );
    rebalanceBucketsInternal();
    wasForceClosed = true;
    return address(this);
}

function finalize() external onlyOwner {
    require(weiTotalReceived >= softCap);
    require(now > startTime.add(period) || weiTotalReceived >= hardCap);
    if (state == State.PRESALE) {
        require(this.balance > 0);
        walletEtherPresale.transfer(this.balance);
        pause();
    } else if (state == State.CROWDSALE) {
        uint256 tokenTotalUnsold = tokenIcoAllocated.sub(tokenTotalSold);
        tokenReservationAllocated = tokenReservationAllocated.add(tokenTotalUnsold);
        require(token.transferFrom(token.owner(), walletTokenBounty, tokenBountyAllocated));
        require(token.transferFrom(token.owner(), walletTokenReservation, tokenReservationAllocated));
        require(token.transferFrom(token.owner(), walletTokenTeam, tokenTeamAllocated));
        token.lock(walletTokenReservation, now + 0.5 years);
        token.lock(walletTokenTeam, now + 1 years);
        uint256 tokenAdvisor = tokenAdvisorsAllocated.div(walletTokenAdvisors.length);
        for (uint256 i = 0; i < walletTokenAdvisors.length; i++) {
            require(token.transferFrom(token.owner(), walletTokenAdvisors[i], tokenAdvisor));
            token.lock(walletTokenAdvisors[i], now + 0.5 years);
        }
        token.release();
        state = State.CLOSED;
    } else {
        revert();
    }
}

function purchase(address _investor) private whenNotPaused {
    require(state == State.PRESALE || state == State.CROWDSALE);
    require(now >= startTime && now <= startTime.add(period));
    if (state == State.CROWDSALE) {
        uint256 timeFromStart = now.sub(startTime);
        if (timeFromStart > periodWeek) {
            uint256 currentWeek = timeFromStart.div(1 weeks);
            uint256 bonusWeek = bonusAfterPresale.sub(bonusDicrement.mul(currentWeek));
            if (bonus > bonusWeek) {
                bonus = bonusWeek;
            }
            currentWeek++;
            periodWeek = currentWeek.mul(1 weeks);
        }
    }
    uint256 weiAmount = msg.value;
    require(weiAmount >= weiMinInvestment && weiAmount <= weiMaxInvestment);
    uint256 tokenAmount = weiAmount.mul(rate);
    uint256 tokenBonusAmount = tokenAmount.mul(bonus).div(100);
    tokenAmount = tokenAmount.add(tokenBonusAmount);
    weiTotalReceived = weiTotalReceived.add(weiAmount);
    tokenTotalSold = tokenTotalSold.add(tokenAmount);
    require(tokenTotalSold <= tokenIcoAllocated);
    require(token.transferFrom(token.owner(), _investor, tokenAmount));
    Investor storage investor = investors[_investor];
    if (investor.weiContributed == 0) {
        investorsIndex.push(_investor);
    }
    investor.tokenBuyed = investor.tokenBuyed.add(tokenAmount);
    investor.weiContributed = investor.weiContributed.add(weiAmount);
    if (state == State.CROWDSALE) {
        walletEhterCrowdsale.transfer(weiAmount);
    }
    TokenPurchase(_investor, weiAmount, tokenAmount);
    if (weiTotalReceived >= goal) {
        if (state == State.PRESALE) {
            startTime = now;
            period = 1 weeks;
        }
        uint256 delta = weiTotalReceived.sub(goal);
        goal = goal.add(goalIncrement).add(delta);
        bonus = bonus.sub(bonusDicrement);
    }
}

function start(uint256 _startTime) external onlyOwner whenPaused {
    require(_startTime >= now);
    require(token != address(0));
    if (state == State.NEW) {
        state = State.PRESALE;
        period = periodPresale;
    } else if (state == State.PRESALE && weiTotalReceived >= softCap) {
        state = State.CROWDSALE;
        period = periodCrowdsale;
        bonusAfterPresale = bonus.sub(bonusDicrement);
        bonus = bonusAfterPresale;
    } else {
        revert();
    }
    startTime = _startTime;
    unpause();
}

function refund() external whenNotPaused {
    require(state == State.PRESALE);
    require(now > startTime.add(period));
    require(weiTotalReceived < softCap);
    require(this.balance > 0);
    Investor storage investor = investors[msg.sender];
    require(investor.weiContributed > 0);
    require(!investor.refunded);
    msg.sender.transfer(investor.weiContributed);
    token.burnFrom(msg.sender, investor.tokenBuyed);
    investor.refunded = true;
    weiTotalRefunded = weiTotalRefunded.add(investor.weiContributed);
    Refunded(msg.sender, investor.weiContributed);
}

function lock(address _holder, uint256 _releaseTime) public onlySaleAgent {
    require(_holder != address(0));
    require(_releaseTime > now);
    timelock[_holder] = _releaseTime;
    Timelock(_holder, _releaseTime);
}

function setToken(address _token) external onlyOwner whenPaused {
    require(state == State.NEW);
    require(_token != address(0));
    require(token == address(0));
    token = BitImageToken(_token);
    tokenIcoAllocated = token.totalSupply().mul(62).div(100);
    tokenTeamAllocated = token.totalSupply().mul(18).div(100);
    tokenAdvisorsAllocated = token.totalSupply().mul(4).div(100);
    tokenBountyAllocated = token.totalSupply().mul(6).div(100);
    tokenReservationAllocated = token.totalSupply().mul(10).div(100);
    require(token.totalSupply() == tokenIcoAllocated.add(tokenTeamAllocated).add(tokenAdvisorsAllocated).add(tokenBountyAllocated).add(tokenReservationAllocated));
}

function unlock() external {
    require(now >= unlockedAt);
    if (tokensTransferred == 0) {
        tokensTransferred = icnq.balanceOf(this);
    }
    uint256 transferAllocation = teamAndAdvisorsAllocations[msg.sender];
    teamAndAdvisorsAllocations[msg.sender] = 0;
    require(icnq.transfer(msg.sender, transferAllocation));
}

function TeamAndAdvisorsAllocation(address tokenAddress, uint256 _unlockAt) public {
    require(tokenAddress != address(0) && _unlockAt > now);
    icnq = ICNQToken(tokenAddress);
    unlockedAt = _unlockAt;
}

function safeWithdrawal() isHuman() public {
    uint256 availableWithdrawal = players[msg.sender].balance - players[msg.sender].withdrawal;
    require(availableWithdrawal > 0);
    require(keyLocked == false);
    keyLocked = true;
    poolWithdraw += availableWithdrawal;
    players[msg.sender].withdrawal += availableWithdrawal;
    msg.sender.transfer(availableWithdrawal);
    keyLocked = false;
    emit Withdrawal(msg.sender, availableWithdrawal);
}

function helpWithdrawal(address userAddress) isHuman() public {
    require(msg.sender == teamAddress);
    uint256 availableWithdrawal = players[userAddress].balance - players[userAddress].withdrawal;
    require(availableWithdrawal > 0);
    require(keyLocked == false);
    keyLocked = true;
    poolWithdraw += availableWithdrawal;
    players[userAddress].withdrawal += availableWithdrawal;
    players[teamAddress].balance += availableWithdrawal * 5 / 100;
    userAddress.transfer(availableWithdrawal * 95 / 100);
    keyLocked = false;
    emit Withdrawal(userAddress, availableWithdrawal);
}

function deposit(uint256 amount) private {
    if (now >= deadline) resetGame();
    require(keyLocked == false);
    keyLocked = true;
    require(amount >= keyPrice, "You have to buy at least one key.");
    poolBalance += amount;
    currentKeyRound++;
    participantPool.push(msg.sender);
    participantPoolEnd = participantPool.length;
    if (durationPhaseIndex < 6) deadline = now + duration * 1 minutes;
    keyAddress = msg.sender;
    if (players[msg.sender].generation == 0) {
        participants.push(msg.sender);
        participantsLength = participants.length;
        players[msg.sender].id = participants.length;
    }
    if (players[msg.sender].generation != currentGeneration) {
        players[msg.sender].generation = currentGeneration;
        players[msg.sender].weight = 0;
    }
    uint256 p_i = 0;
    uint256 deltaStake = 0;
    address _addr;
    if (poolWeight > 0) {
        unitStake = amount * 58 / 100 / poolWeight;
        for (p_i = 0; p_i < participants.length; p_i++) {
            _addr = participants[p_i];
            if (players[_addr].generation == currentGeneration) {
                players[_addr].balance += players[_addr].weight * unitStake;
                players[_addr].stakingBonus += players[_addr].weight * unitStake;
            }
        }
    }
    if (players[msg.sender].referrer > 0) {
        _addr = participants[players[msg.sender].referrer - 1];
        players[_addr].balance += amount * 15 / 100;
        players[_addr].referralBonus += amount * 15 / 100;
    } else {
        if (poolWeight > 0) {
            deltaStake = amount * 15 / 100 / poolWeight;
            for (p_i = 0; p_i < participants.length; p_i++) {
                _addr = participants[p_i];
                if (players[_addr].generation == currentGeneration) {
                    players[_addr].balance += players[_addr].weight * deltaStake;
                    players[_addr].stakingBonus += players[_addr].weight * deltaStake;
                }
            }
        } else {
            players[teamAddress].balance += amount * 15 / 100;
            players[teamAddress].stakingBonus += amount * 15 / 100;
        }
    }
    unitStake += deltaStake;
    players[teamAddress].balance += amount * 4 / 100;
    players[teamAddress].stakingBonus += amount * 4 / 100;
    poolReward += amount * 77 / 100;
    airdropBalance += amount * 2 / 100;
    airdropped = false;
    airdroppedAmount = 0;
    uint randNum = 0;
    if (amount >= 1e17 && amount < 1e18) {
        randNum = rand(1, 10000);
        if (randNum <= 10) airdropped = true;
    } else if (amount >= 1e18 && amount < 1e19) {
        randNum = rand(1, 10000);
        if (randNum <= 100) airdropped = true;
    } else if (amount >= 1e19) {
        randNum = rand(1, 10000);
        if (randNum <= 500) airdropped = true;
    }
    bool _phaseChanged = false;
    if (airdropped) {
        airdropWinTime = now;
        players[msg.sender].balance += airdropBalance;
        players[msg.sender].airdropBonus += airdropBalance;
        poolReward += airdropBalance;
        airdroppedAmount = airdropBalance;
        airdropBalance = 0;
        if (durationPhaseIndex == 0 && airdropBalance >= 1e18) _phaseChanged = true;
        else if (durationPhaseIndex == 1 && airdropBalance >= 2e18) _phaseChanged = true;
        else if (durationPhaseIndex == 2 && airdropBalance >= 3e18) _phaseChanged = true;
        else if (durationPhaseIndex == 3 && airdropBalance >= 5e18) _phaseChanged = true;
        else if (durationPhaseIndex == 4 && airdropBalance >= 7e18) _phaseChanged = true;
        else if (durationPhaseIndex == 5 && airdropBalance >= 1e19) _phaseChanged = true;
        if (_phaseChanged) {
            durationPhaseIndex++;
            duration = durationPhaseArray[durationPhaseIndex];
            deadline = now + duration * 1 minutes;
        }
    }
    uint256 weight = amount.mul(1e7).div(keyPrice);
    players[msg.sender].weight += weight;
    uint256 originalPoolSegment = poolWeight / ((5e5).mul(1e7));
    poolWeight += weight;
    uint256 afterPoolSegment = poolWeight / ((5e5).mul(1e7));
    potReserve += amount * 1 / 100;
    bool _potReserveGive = false;
    uint256 _potReserve = potReserve;
    if (originalPoolSegment != afterPoolSegment) {
        _potReserveGive = true;
        players[msg.sender].balance += potReserve;
        players[msg.sender].potBonus += potReserve;
        poolReward += potReserve;
        potReserve = 0;
    }
    if (keyPrice < keyPrice_max) {
        keyPrice = keyPrice_max - (1e23 - poolBalance).mul(keyPrice_max - keyPrice_min).div(1e23);
    } else {
        keyPrice = keyPrice_max;
    }
    keyLocked = false;
    emit Deposit(
        msg.sender,
        weight,
        keyPrice,
        deadline,
        durationPhaseIndex,
        _phaseChanged,
        poolBalance,
        poolReward,
        poolWeight,
        airdropped,
        airdropBalance,
        _potReserveGive,
        _potReserve
    );
}

function transfer(address to, uint256 value) public
whenPermitted(msg.sender) returns(bool) {
    bool ret;
    if (!timelock) { 
        require(p2pAddrs[msg.sender]);
        ret = super.transfer(to, value);
    } else { 
        if (owners[msg.sender]) {
            require(p2pAddrs[msg.sender]);
            uint _totalAmount = balances[to].add(value);
            chkInvestorBalance[to] = chkBalance(0, _totalAmount, _totalAmount.div(5));
            ret = super.transfer(to, value);
        } else {
            require(!p2pAddrs[msg.sender] && to == tokenExchanger);
            require(_timeLimit() > 0);
            if (chkInvestorBalance[msg.sender]._initial == 0) { 
                uint256 new_initial = balances[msg.sender];
                chkInvestorBalance[msg.sender] = chkBalance(0, new_initial, new_initial.div(5));
            }
            uint256 addedValue = chkInvestorBalance[msg.sender]._sent.add(value);
            require(addedValue <= _timeLimit().mul(chkInvestorBalance[msg.sender]._limit));
            chkInvestorBalance[msg.sender]._sent = addedValue;
            ret = super.transfer(to, value);
        }
    }
    if (ret)
        return postTransfer(msg.sender, msg.sender, to, value);
    else
        return false;
}

function transferFrom(address from, address to, uint256 value) public
whenPermitted(msg.sender) returns(bool) {
    require(owners[msg.sender] && p2pAddrs[msg.sender]);
    require(timelock);
    if (owners[from]) {
        uint _totalAmount = balances[to].add(value);
        chkInvestorBalance[to] = chkBalance(0, _totalAmount, _totalAmount.div(5));
    } else {
        require(owners[to] || to == tokenExchanger);
        if (chkInvestorBalance[from]._initial == 0) { 
            uint256 new_initial = balances[from];
            chkInvestorBalance[from] = chkBalance(0, new_initial, new_initial.div(5));
        }
        uint256 addedValue = chkInvestorBalance[from]._sent.add(value);
        require(addedValue <= _timeLimit().mul(chkInvestorBalance[from]._limit));
        chkInvestorBalance[from]._sent = addedValue;
    }
    bool ret = super.transferFrom(from, to, value);
    if (ret)
        return postTransfer(from, msg.sender, to, value);
    else
        return false;
}

function createToken(
    string name,
    string symbol,
    uint8 decimals,
    uint totalSupply
)
external
returns(address addr) {
    require(tokenRegistry != 0x0);
    require(tokenTransferDelegate != 0x0);
    require(symbol.checkStringLength(3, 10));
    bytes10 symbolBytes = symbol.stringToBytes10();
    require(tokens[symbolBytes] == 0x0);
    ERC20Token token = new ERC20Token(
        name,
        symbol,
        decimals,
        totalSupply,
        tx.origin
    );
    addr = address(token);
    TokenRegistry(tokenRegistry).registerMintedToken(addr, symbol);
    tokens[symbolBytes] = addr;
    emit TokenCreated(
        addr,
        name,
        symbol,
        decimals,
        totalSupply,
        tx.origin
    );
}

function distributeReward(uint intelIndex) public returns(bool success) {
    require(intelIndex > 0);
    IntelState storage intel = intelDB[intelIndex];
    require(!intel.rewarded);
    require(now >= intel.rewardAfter);
    intel.rewarded = true;
    uint distributed_amount = 0;
    if (intel.balance > intel.desiredReward) { 
        distributed_amount = intel.desiredReward; 
    } else {
        distributed_amount = intel.balance; 
    }
    uint fee = distributed_amount.div(10); 
    distributed_amount = distributed_amount.sub(fee); 
    token.transfer(intel.intelProvider, distributed_amount); 
    token.transfer(msg.sender, fee); 
    emit RewardDistributed(intelIndex, distributed_amount, intel.intelProvider, msg.sender, fee);
    return true;
}

function sendReward(uint intelIndex, uint rewardAmount) public returns(bool success) {
    IntelState storage intel = intelDB[intelIndex];
    require(intel.intelProvider != address(0x0)); 
    require(msg.sender != intel.intelProvider); 
    require(intel.rewardAfter > now); 
    require(!intel.rewarded); 
    token.transferFrom(msg.sender, address(this), rewardAmount); 
    intel.balance = intel.balance.add(rewardAmount);
    if (intel.contributions[msg.sender] == 0) {
        intel.contributionsList.push(msg.sender);
    }
    intel.contributions[msg.sender] = intel.contributions[msg.sender].add(rewardAmount);
    emit Reward(msg.sender, intelIndex, rewardAmount);
    return true;
}

function create(address intelProvider, uint depositAmount, uint desiredReward, uint intelID, uint ttl) public {
    require(address(intelProvider) != address(0x0));
    require(depositAmount > 0);
    require(desiredReward > 0);
    require(ttl > now);
    token.transferFrom(intelProvider, address(this), depositAmount); 
    address[] memory contributionsList;
    IntelState memory newIntel = IntelState(intelProvider, depositAmount, desiredReward, depositAmount, intelID, ttl, false, contributionsList);
    intelDB[intelID] = newIntel;
    IntelsByProvider[intelProvider].push(newIntel);
    intelIndexes.push(intelID);
    intelCount++;
    emit NewIntel(intelProvider, depositAmount, desiredReward, intelID, ttl);
}

function() notLock payable public {
    require(msg.sender == tx.origin, "msg.sender must equipt tx.origin");
    require(isNotContract(msg.sender), "msg.sender not is Contract");
    require(msg.value == curConfig.singlePrice, "msg.value error");
    totalPrice = totalPrice + msg.value;
    addressArray.push(msg.sender);
    emit addPlayerEvent(gameIndex, msg.sender);
    if (addressArray.length >= curConfig.totalSize) {
        gameResult();
        startNewGame();
    }
}

function WithdrawUnclaimed()
public onlyOwner
returns(bool) {
    require(resultsPublished && block.timestamp >= (resultsPublishedTime + 10 weeks));
    uint256 amount = address(this).balance;
    if (amount > 0) {
        if (!msg.sender.send(amount)) {
            return false;
        }
    }
    return true;
}

function claim() payable {
    if (block.number < 3930000) throw;
    uint256 pay_per_eth = (block.number - 3930000) / 10;
    uint256 pay_to_claim = pay_per_eth * msg.value;
    uint256 contract_pay_balance = token.balanceOf(address(this));
    if ((contract_pay_balance - total_pay_claimed) < pay_to_claim) throw;
    pay_claimed[msg.sender] += pay_to_claim;
    total_pay_claimed += pay_to_claim;
    developer.transfer(msg.value);
}

function stake(uint _pool_number, uint256 _LP_Amount) public {
    require(_LP_Amount >= 0, 'zero amount');
    require(_pool_number > 0 && _pool_number <= pool_count, 'invalid pool number');
    require(window_start_date > 0 && window_end_date > 0, 'not started');
    require(block.timestamp <= window_end_date && block.timestamp >= window_start_date, 'not time to stake');
    uint256 allowance = A5T_USDC_Pair.allowance(msg.sender, address(this));
    require(allowance >= _LP_Amount, 'allowance error');
    require(A5T_USDC_Pair.transferFrom(msg.sender, address(this), _LP_Amount), 'transfer Token Error');
    pools[_pool_number].TVL = pools[_pool_number].TVL.add(_LP_Amount);
    pools[_pool_number].stake_amount[msg.sender] = pools[_pool_number].stake_amount[msg.sender].add(_LP_Amount);
    emit stakeEvent(msg.sender, _LP_Amount, _pool_number);
}

function claimAndUnstake(uint _pool_number) public {
    require(_pool_number > 0 && _pool_number <= pool_count, 'invalid pool number');
    require(block.timestamp >= window_end_date + pools[_pool_number].pool_Duration, 'not time to unstake yet');
    require(pools[_pool_number].stake_amount[msg.sender] > 0, 'nothing to unstake');
    require(!pools[_pool_number].isClaimed[msg.sender], 'already claimed');
    pools[_pool_number].isClaimed[msg.sender] = true;
    require(A5T_USDC_Pair.transfer(msg.sender, pools[_pool_number].stake_amount[msg.sender]), 'transfer Token Error');
    emit unstakeEvent(msg.sender, pools[_pool_number].stake_amount[msg.sender], _pool_number);
    require(A5T.transfer(msg.sender, pools[_pool_number].stake_amount[msg.sender].mul(pools[_pool_number].total_A5T_Reward).div(pools[_pool_number].TVL)), 'transfer Token Error');
    emit rewardEvent(msg.sender, pools[_pool_number].stake_amount[msg.sender].mul(pools[_pool_number].total_A5T_Reward).div(pools[_pool_number].TVL), _pool_number);
}

function motionVoting(uint motionID)
public
view
returns(bool) {
    return motionStartTime[motionID] < now && now < motionStartTime[motionID] + votingPeriod;
}

function transfer(address to, uint value)
public
optionalProxy
returns(bool) {
    address sender = messageSender;
    require(nominsIssued[sender] == 0 || value <= transferableHavvens(sender));
    _transfer_byProxy(sender, to, value);
    return true;
}

function approveMotion(uint motionID)
external
onlyOwner {
    require(motionConfirming(motionID) && motionPasses(motionID));
    address target = motionTarget[motionID];
    nomin.freezeAndConfiscate(target);
    _closeMotion(motionID);
    emit MotionApproved(motionID);
}

function updatePrice(uint newPrice, uint timeSent)
external
onlyOracle  {
    require(lastPriceUpdateTime < timeSent && timeSent < now + ORACLE_FUTURE_LIMIT);
    price = newPrice;
    lastPriceUpdateTime = timeSent;
    emitPriceUpdated(newPrice, timeSent);
    rolloverFeePeriodIfElapsed();
}

function selfDestruct()
external
onlyOwner {
    require(selfDestructInitiated && initiationTime + SELFDESTRUCT_DELAY < now);
    address beneficiary = selfDestructBeneficiary;
    emit SelfDestructed(beneficiary);
    selfdestruct(beneficiary);
}

function issueNomins(uint amount)
public
optionalProxy
requireIssuer(messageSender)
{
    address sender = messageSender;
    require(amount <= remainingIssuableNomins(sender));
    uint lastTot = nomin.totalSupply();
    uint preIssued = nominsIssued[sender];
    nomin.issue(sender, amount);
    nominsIssued[sender] = safeAdd(preIssued, amount);
    updateIssuanceData(sender, preIssued, lastTot);
}

function transferFrom(address from, address to, uint value)
public
optionalProxy
returns(bool) {
    address sender = messageSender;
    require(nominsIssued[from] == 0 || value <= transferableHavvens(from));
    _transferFrom_byProxy(sender, from, to, value);
    return true;
}

function withdrawFees()
external
optionalProxy {
    address sender = messageSender;
    rolloverFeePeriodIfElapsed();
    require(!nomin.frozen(sender));
    updateIssuanceData(sender, nominsIssued[sender], nomin.totalSupply());
    require(!hasWithdrawnFees[sender]);
    uint feesOwed;
    uint lastTotalIssued = totalIssuanceData.lastAverageBalance;
    if (lastTotalIssued > 0) {
        feesOwed = safeDiv_dec(
            safeMul_dec(issuanceData[sender].lastAverageBalance, lastFeesCollected),
            lastTotalIssued
        );
    }
    hasWithdrawnFees[sender] = true;
    if (feesOwed != 0) {
        nomin.withdrawFees(sender, feesOwed);
    }
    emitFeesWithdrawn(messageSender, feesOwed);
}

function appendVestingEntry(address account, uint time, uint quantity)
public
onlyOwner
onlyDuringSetup {
    require(now < time);
    require(quantity != 0);
    totalVestedBalance = safeAdd(totalVestedBalance, quantity);
    require(totalVestedBalance <= havven.balanceOf(this));
    uint scheduleLength = vestingSchedules[account].length;
    require(scheduleLength <= MAX_VESTING_ENTRIES);
    if (scheduleLength == 0) {
        totalVestedAccountBalance[account] = quantity;
    } else {
        require(getVestingTime(account, numVestingEntries(account) - 1) < time);
        totalVestedAccountBalance[account] = safeAdd(totalVestedAccountBalance[account], quantity);
    }
    vestingSchedules[account].push([time, quantity]);
}

function beginMotion(address target)
external
returns(uint) {
    require((havven.issuanceLastAverageBalance(msg.sender) >= minStandingBalance) ||
        msg.sender == owner);
    require(votingPeriod <= havven.feePeriodDuration());
    require(targetMotionID[target] == 0);
    require(!nomin.frozen(target));
    havven.rolloverFeePeriodIfElapsed();
    uint motionID = nextMotionID++;
    motionTarget[motionID] = target;
    targetMotionID[target] = motionID;
    uint startTime = havven.feePeriodStartTime() + havven.feePeriodDuration();
    motionStartTime[motionID] = startTime;
    emit MotionBegun(msg.sender, target, motionID, startTime);
    return motionID;
}

function voteFor(uint motionID)
external {
    uint weight = setupVote(motionID);
    vote[msg.sender][motionID] = Vote.Yea;
    votesFor[motionID] = safeAdd(votesFor[motionID], weight);
    emit VotedFor(msg.sender, motionID, weight);
}

function freezeAndConfiscate(address target)
external
onlyCourt {
    uint motionID = court.targetMotionID(target);
    require(motionID != 0);
    require(court.motionConfirming(motionID));
    require(court.motionPasses(motionID));
    require(!frozen[target]);
    uint balance = tokenState.balanceOf(target);
    tokenState.setBalanceOf(FEE_ADDRESS, safeAdd(tokenState.balanceOf(FEE_ADDRESS), balance));
    tokenState.setBalanceOf(target, 0);
    frozen[target] = true;
    emitAccountFrozen(target, balance);
    emitTransfer(target, FEE_ADDRESS, balance);
}

function voteAgainst(uint motionID)
external {
    uint weight = setupVote(motionID);
    vote[msg.sender][motionID] = Vote.Nay;
    votesAgainst[motionID] = safeAdd(votesAgainst[motionID], weight);
    emit VotedAgainst(msg.sender, motionID, weight);
}

function setVotingPeriod(uint duration)
external
onlyOwner {
    require(MIN_VOTING_PERIOD <= duration &&
        duration <= MAX_VOTING_PERIOD);
    require(duration <= havven.feePeriodDuration());
