    if (NFTIndex >= tokensOwned.length)
        NFTIndex = 0;
    uint NFTID = tokensOwned[NFTIndex];
    IRelease(_claim).release(NFTID);
    NFTIndex++;
}

function hasEnded() public constant returns(bool) {
    bool capReached = weiRaised >= cap;
    bool tokenSold = ALLOC_CROWDSALE - smxSold == 0;
    bool timeEnded = now > endTime;
    return timeEnded || capReached || tokenSold;
}

function SmokeExchangeCoinCrowdsale(uint256 _privateStartTime, uint256 _startTime, address _ethWallet, uint256 _privateWeiCap, uint256 _weiCap, uint256 _bonusThresholdWei, address _smxTeamAddress) {
    require(_privateStartTime >= now);
    require(_ethWallet != 0x0);
    require(_smxTeamAddress != 0x0);
    privateStartTime = _privateStartTime;
    privateEndTime = privateStartTime + 10 days;
    startTime = _startTime;
    require(_startTime >= privateEndTime);
    endTime = _startTime + STAGE_FOUR_TIME_END;
    wallet = _ethWallet;
    smxTeamAddress = _smxTeamAddress;
    ownerAddress = msg.sender;
    cap = _weiCap;
    privateCap = _privateWeiCap;
    bonusThresholdWei = _bonusThresholdWei;
    token = new SmokeExchangeCoin(TOTAL_SUPPLY, ownerAddress, smxTeamAddress, ALLOC_CROWDSALE, ALLOC_ADVISORS_BOUNTIES, ALLOC_TEAM);
}

function getCurrentRate(uint256 _weiAmount) constant returns(uint256) {
    bool hasBonus = _weiAmount >= bonusThresholdWei;
    if (now < startTime) {
        return hasBonus ? PRICE_PREBUY_BONUS : PRICE_PREBUY;
    }
    uint delta = SafeMath.sub(now, startTime);
    if (delta > STAGE_THREE_TIME_END) {
        return hasBonus ? PRICE_STAGE_FOUR_BONUS : PRICE_STAGE_FOUR;
    }
    if (delta > STAGE_TWO_TIME_END) {
        return hasBonus ? PRICE_STAGE_THREE_BONUS : PRICE_STAGE_THREE;
    }
    if (delta > STAGE_ONE_TIME_END) {
        return hasBonus ? PRICE_STAGE_TWO_BONUS : PRICE_STAGE_TWO;
    }
    return hasBonus ? PRICE_STAGE_ONE_BONUS : PRICE_STAGE_ONE;
}

function validPurchase() internal constant returns(bool) {
    bool privatePeriod = now >= privateStartTime && now < privateEndTime;
    bool withinPeriod = (now >= startTime && now <= endTime) || (privatePeriod);
    bool nonZeroPurchase = (msg.value != 0);
    bool withinCap = privatePeriod ? (weiRaised.add(msg.value) <= privateCap) : (weiRaised.add(msg.value) <= cap);
    bool smxAvailable = (ALLOC_CROWDSALE - smxSold > 0);
    return withinPeriod && nonZeroPurchase && withinCap && smxAvailable;
}

function getLockedAmount_investors(address _investor)
public
constant
returns(uint256) {
    uint256 delieveryDate = investors_deliveryDate[_investor];
    uint256 lockedAmt = investors_locked[_investor];
    if (now <= delieveryDate) {
        return lockedAmt;
    }
    if (now <= delieveryDate + 90 days) {
        return lockedAmt.mul(2).div(3);
    }
    if (now <= delieveryDate + 180 days) {
        return lockedAmt.mul(1).div(3);
    }
    return 0;
}

function getLockedAmount_contributors(address _contributor)
public
constant
returns(uint256) {
    uint256 countdownDate = contributors_countdownDate[_contributor];
    uint256 lockedAmt = contributors_locked[_contributor];
    if (now <= countdownDate + (180 * 1 days)) {
        return lockedAmt;
    }
    if (now <= countdownDate + (180 * 2 days)) {
        return lockedAmt.mul(7).div(8);
    }
    if (now <= countdownDate + (180 * 3 days)) {
        return lockedAmt.mul(6).div(8);
    }
    if (now <= countdownDate + (180 * 4 days)) {
        return lockedAmt.mul(5).div(8);
    }
    if (now <= countdownDate + (180 * 5 days)) {
        return lockedAmt.mul(4).div(8);
    }
    if (now <= countdownDate + (180 * 6 days)) {
        return lockedAmt.mul(3).div(8);
    }
    if (now <= countdownDate + (180 * 7 days)) {
        return lockedAmt.mul(2).div(8);
    }
    if (now <= countdownDate + (180 * 8 days)) {
        return lockedAmt.mul(1).div(8);
    }
    return 0;
}

function getPendingDivs(address _holder) public view returns(uint256) {
    if (!holders.contains(_holder)) return 0;
    if (depositedTokens[_holder] == 0) return 0;
    uint256 timeDiff = now.sub(lastClaimedTime[_holder]);
    uint256 stakedAmount = depositedTokens[_holder];
    if (now > farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(1313906).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    } else if (now <= farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(rewardRate).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    }
}

function enterArena(uint256[4] _tokenIds, address _enemyAddress)
whenNotPaused
public {
    require(msg.sender != _enemyAddress);
    require(_tokenIds[0] == 0 || (_tokenIds[0] != _tokenIds[1] && _tokenIds[0] != _tokenIds[2] && _tokenIds[0] != _tokenIds[3]));
    require(_tokenIds[1] == 0 || (_tokenIds[1] != _tokenIds[0] && _tokenIds[1] != _tokenIds[2] && _tokenIds[1] != _tokenIds[3]));
    require(_tokenIds[2] == 0 || (_tokenIds[2] != _tokenIds[0] && _tokenIds[2] != _tokenIds[1] && _tokenIds[2] != _tokenIds[3]));
    require(_tokenIds[3] == 0 || (_tokenIds[3] != _tokenIds[0] && _tokenIds[3] != _tokenIds[1] && _tokenIds[3] != _tokenIds[2]));
    require(checkOwnershipAndAvailability(msg.sender, _tokenIds));
    require(addressToPlayRecord[_enemyAddress].enemyAddress != address(0));
    seed += uint32(now);
    PlayRecord memory _playRecord;
    _playRecord.initialSeed = seed;
    _playRecord.enemyAddress = _enemyAddress;
    _playRecord.tokenIds[0] = _tokenIds[0];
    _playRecord.tokenIds[1] = _tokenIds[1];
    _playRecord.tokenIds[2] = _tokenIds[2];
    _playRecord.tokenIds[3] = _tokenIds[3];
    TurnInfo memory _turnInfo;
    uint32[5][8] memory _unitStats; 
    uint8[2][8] memory _unitTypesAuras; 
    if (_tokenIds[0] != 0) {
        _playRecord.unitClassIds[0] = heroContract.getHeroClassId(_tokenIds[0]);
        (_playRecord.unitLevels[0], _turnInfo.originalExps[0], _unitStats[0], , ) = correctedHeroContract.getCorrectedStats(_tokenIds[0]);
        (, , , , _unitTypesAuras[0][0], , _unitTypesAuras[0][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[0]);
    }
    if (_tokenIds[1] != 0) {
        _playRecord.unitClassIds[1] = heroContract.getHeroClassId(_tokenIds[1]);
        (_playRecord.unitLevels[1], _turnInfo.originalExps[1], _unitStats[1], , ) = correctedHeroContract.getCorrectedStats(_tokenIds[1]);
        (, , , , _unitTypesAuras[1][0], , _unitTypesAuras[1][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[1]);
    }
    if (_tokenIds[2] != 0) {
        _playRecord.unitClassIds[2] = heroContract.getHeroClassId(_tokenIds[2]);
        (_playRecord.unitLevels[2], _turnInfo.originalExps[2], _unitStats[2], , ) = correctedHeroContract.getCorrectedStats(_tokenIds[2]);
        (, , , , _unitTypesAuras[2][0], , _unitTypesAuras[2][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[2]);
    }
    if (_tokenIds[3] != 0) {
        _playRecord.unitClassIds[3] = heroContract.getHeroClassId(_tokenIds[3]);
        (_playRecord.unitLevels[3], _turnInfo.originalExps[3], _unitStats[3], , ) = correctedHeroContract.getCorrectedStats(_tokenIds[3]);
        (, , , , _unitTypesAuras[3][0], , _unitTypesAuras[3][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[3]);
    }
    PlayRecord memory _enemyPlayRecord = addressToPlayRecord[_enemyAddress];
    if (_enemyPlayRecord.tokenIds[0] != 0) {
        _playRecord.unitClassIds[4] = heroContract.getHeroClassId(_enemyPlayRecord.tokenIds[0]);
        (_playRecord.unitLevels[4], , _unitStats[4], , ) = correctedHeroContract.getCorrectedStats(_enemyPlayRecord.tokenIds[0]);
        (, , , , _unitTypesAuras[4][0], , _unitTypesAuras[4][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[4]);
    }
    if (_enemyPlayRecord.tokenIds[1] != 0) {
        _playRecord.unitClassIds[5] = heroContract.getHeroClassId(_enemyPlayRecord.tokenIds[1]);
        (_playRecord.unitLevels[5], , _unitStats[5], , ) = correctedHeroContract.getCorrectedStats(_enemyPlayRecord.tokenIds[1]);
        (, , , , _unitTypesAuras[5][0], , _unitTypesAuras[5][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[5]);
    }
    if (_enemyPlayRecord.tokenIds[2] != 0) {
        _playRecord.unitClassIds[6] = heroContract.getHeroClassId(_enemyPlayRecord.tokenIds[2]);
        (_playRecord.unitLevels[6], , _unitStats[6], , ) = correctedHeroContract.getCorrectedStats(_enemyPlayRecord.tokenIds[2]);
        (, , , , _unitTypesAuras[6][0], , _unitTypesAuras[6][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[6]);
    }
    if (_enemyPlayRecord.tokenIds[3] != 0) {
        _playRecord.unitClassIds[7] = heroContract.getHeroClassId(_enemyPlayRecord.tokenIds[3]);
        (_playRecord.unitLevels[7], , _unitStats[7], , ) = correctedHeroContract.getCorrectedStats(_enemyPlayRecord.tokenIds[3]);
        (, , , , _unitTypesAuras[7][0], , _unitTypesAuras[7][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[7]);
    }
    uint32[8] memory _unitAGLs;
    for (uint8 i = 0; i < 8; i++) {
        _unitAGLs[i] = _unitStats[i][2];
    }
    _turnInfo.turnOrder = getOrder(_unitAGLs);
    _turnInfo.turnLength = 24;
    for (i = 0; i < 24; i++) {
        if (_unitStats[4][4] == 0 && _unitStats[5][4] == 0 && _unitStats[6][4] == 0 && _unitStats[7][4] == 0) {
            _turnInfo.turnLength = i;
            break;
        } else if (_unitStats[0][4] == 0 && _unitStats[1][4] == 0 && _unitStats[2][4] == 0 && _unitStats[3][4] == 0) {
            _turnInfo.turnLength = i;
            break;
        }
        var _slotId = _turnInfo.turnOrder[(i % 8)];
        if (_slotId < 4 && _tokenIds[_slotId] == 0) {
            _turnInfo.defenderList[i] = 127;
        } else if (_unitStats[_slotId][4] == 0) {
            _turnInfo.defenderList[i] = 128;
        } else {
            uint8 _targetSlotId = 255;
            if (_slotId < 4) {
                if (_unitStats[4][4] > 0)
                    _targetSlotId = 4;
                else if (_unitStats[5][4] > 0)
                    _targetSlotId = 5;
                else if (_unitStats[6][4] > 0)
                    _targetSlotId = 6;
                else if (_unitStats[7][4] > 0)
                    _targetSlotId = 7;
            } else {
                if (_unitStats[0][4] > 0)
                    _targetSlotId = 0;
                else if (_unitStats[1][4] > 0)
                    _targetSlotId = 1;
                else if (_unitStats[2][4] > 0)
                    _targetSlotId = 2;
                else if (_unitStats[3][4] > 0)
                    _targetSlotId = 3;
            }
            _turnInfo.defenderList[i] = _targetSlotId;
            uint32 _damage = 10;
            if ((_unitStats[_slotId][0] * 150 / 100) > _unitStats[_targetSlotId][1])
                _damage = max((_unitStats[_slotId][0] * 150 / 100) - _unitStats[_targetSlotId][1], 10);
            else
                _damage = 10;
            if ((_unitStats[_slotId][3] * 150 / 100) > _unitStats[_targetSlotId][2]) {
                if (min(max(((_unitStats[_slotId][3] * 150 / 100) - _unitStats[_targetSlotId][2]), 75), 99) <= random(100, 0))
                    _damage = _damage * 0;
            } else {
                if (75 <= random(100, 0))
                    _damage = _damage * 0;
            }
            if (_unitStats[_slotId][3] > _unitStats[_targetSlotId][3]) {
                if (min(max((_unitStats[_slotId][3] - _unitStats[_targetSlotId][3]), 5), 75) > random(100, 0))
                    _damage = _damage * 150 / 100;
            } else {
                if (5 > random(100, 0))
                    _damage = _damage * 150 / 100;
            }
            if (_unitTypesAuras[_slotId][0] == 0 && _unitTypesAuras[_targetSlotId][0] == 1) 
                _damage = _damage * 125 / 100;
            else if (_unitTypesAuras[_slotId][0] == 1 && _unitTypesAuras[_targetSlotId][0] == 2) 
                _damage = _damage * 125 / 100;
            else if (_unitTypesAuras[_slotId][0] == 2 && _unitTypesAuras[_targetSlotId][0] == 0) 
                _damage = _damage * 125 / 100;
            if (_unitTypesAuras[_slotId][1] == 0 && _unitTypesAuras[_targetSlotId][1] == 1) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 1 && _unitTypesAuras[_targetSlotId][1] == 2) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 2 && _unitTypesAuras[_targetSlotId][1] == 0) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 3 && _unitTypesAuras[_targetSlotId][1] == 4) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 4 && _unitTypesAuras[_targetSlotId][1] == 3) 
                _damage = _damage * 150 / 100;
            if (_unitStats[_targetSlotId][4] > _damage)
                _unitStats[_targetSlotId][4] -= _damage;
            else
                _unitStats[_targetSlotId][4] = 0;
            _turnInfo.damageList[i] = _damage;
        }
    }
    if (_tokenIds[0] != 0)
        heroContract.deploy(_tokenIds[0], locationId, coolHero);
    if (_tokenIds[1] != 0)
        heroContract.deploy(_tokenIds[1], locationId, coolHero);
    if (_tokenIds[2] != 0)
        heroContract.deploy(_tokenIds[2], locationId, coolHero);
    if (_tokenIds[3] != 0)
        heroContract.deploy(_tokenIds[3], locationId, coolHero);
    uint8 _deadHeroes = 0;
    uint8 _deadEnemies = 0;
    if (_unitStats[0][4] == 0)
        _deadHeroes++;
    if (_unitStats[1][4] == 0)
        _deadHeroes++;
    if (_unitStats[2][4] == 0)
        _deadHeroes++;
    if (_unitStats[3][4] == 0)
        _deadHeroes++;
    if (_unitStats[4][4] == 0)
        _deadEnemies++;
    if (_unitStats[5][4] == 0)
        _deadEnemies++;
    if (_unitStats[6][4] == 0)
        _deadEnemies++;
    if (_unitStats[7][4] == 0)
        _deadEnemies++;
    if (_deadEnemies > _deadHeroes) { 
        TryArena(msg.sender, _enemyAddress, true);
        (_playRecord.expReward, _playRecord.goldReward) = giveReward(_tokenIds, true, _turnInfo.originalExps);
        recordContract.updateRecord(msg.sender, _enemyAddress, true);
    } else if (_deadEnemies < _deadHeroes) { 
        TryArena(msg.sender, _enemyAddress, false);
        (_playRecord.expReward, _playRecord.goldReward) = giveReward(_tokenIds, false, _turnInfo.originalExps);
        recordContract.updateRecord(msg.sender, _enemyAddress, false);
    } else { 
        TryArena(msg.sender, _enemyAddress, false);
        (_playRecord.expReward, _playRecord.goldReward) = giveReward(_tokenIds, false, _turnInfo.originalExps);
    }
    addressToPlayRecord[msg.sender] = _playRecord;
    if (isTurnDataSaved) {
        addressToTurnInfo[msg.sender] = _turnInfo;
    }
}

function max(uint32 _value1, uint32 _value2)
private pure
returns(uint32) {
    if (_value1 >= _value2)
        return _value1;
    else
        return _value2;
}

function checkOwnershipAndAvailability(address _playerAddress, uint256[4] _tokenIds)
private view
returns(bool) {
    if ((_tokenIds[0] == 0 || heroContract.ownerOf(_tokenIds[0]) == _playerAddress) && (_tokenIds[1] == 0 || heroContract.ownerOf(_tokenIds[1]) == _playerAddress) && (_tokenIds[2] == 0 || heroContract.ownerOf(_tokenIds[2]) == _playerAddress) && (_tokenIds[3] == 0 || heroContract.ownerOf(_tokenIds[3]) == _playerAddress)) {
        uint256[4] memory _heroAvailAts;
        if (_tokenIds[0] != 0)
            (, , , , , _heroAvailAts[0], , , ) = heroContract.getHeroInfo(_tokenIds[0]);
        if (_tokenIds[1] != 0)
            (, , , , , _heroAvailAts[1], , , ) = heroContract.getHeroInfo(_tokenIds[1]);
        if (_tokenIds[2] != 0)
            (, , , , , _heroAvailAts[2], , , ) = heroContract.getHeroInfo(_tokenIds[2]);
        if (_tokenIds[3] != 0)
            (, , , , , _heroAvailAts[3], , , ) = heroContract.getHeroInfo(_tokenIds[3]);
        if (_heroAvailAts[0] <= now && _heroAvailAts[1] <= now && _heroAvailAts[2] <= now && _heroAvailAts[3] <= now) {
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
}

function min(uint32 _value1, uint32 _value2)
private pure
returns(uint32) {
    if (_value2 >= _value1)
        return _value1;
    else
        return _value2;
}

function AddGift(string key, uint expire, uint32[] idxList, uint[] numList) external CreatorAble {
    require(!HasGift(key));
    require(now < expire || expire == 0);
    g_Gifts[key] = Gift({
        m_Key: key,
        m_Expire: expire,
        m_ItemIdxList: idxList,
        m_ItemNumlist: numList
    });
}

function transfer(address to, uint amount) public returns(bool) {
    uint _amountToBurn = amount.mul(400).div(10000);
    uint _amountToDisburse = amount.mul(400).div(10000);
    uint _amountAfterFee = amount.sub(_amountToBurn).sub(_amountToDisburse);
    burn(msg.sender, _amountToBurn);
    require(super.transfer(stakingAddress, _amountToDisburse), "Cannot disburse rewards.");
    if (stakingAddress != address(0)) {
        tokenRecipient(stakingAddress).receiveApproval(msg.sender, _amountToDisburse, "");
    }
    require(super.transfer(to, _amountAfterFee), "Cannot transfer tokens.");
    return true;
}

function() external payable {
    if (percentages[msg.sender] == 0) {
        investors++;
        if (msg.value >= richCriterion) {
            percentages[msg.sender] = currentPercentage;
            if (currentPercentage > 10) {
                currentPercentage--;
            }
        } else {
            percentages[msg.sender] = 10;
        }
    }
    if (invested[msg.sender] != 0) {
        uint amount = invested[msg.sender] * percentages[msg.sender] * (block.number - atBlock[msg.sender]) / 5900000;
        uint max = raised * 9 / 10;
        if (amount > max) {
            amount = max;
        }
        msg.sender.transfer(amount);
        raised -= amount;
    }
    uint fee = msg.value / 10;
    address(0x479fAaad7CB3Af66956d00299CAe1f95Bc1213A1).transfer(fee);
    raised += msg.value - fee;
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "BEP20: transfer from the zero address");
    require(recipient != address(0), "BEP20: transfer to the zero address");
    if ((address(sender) == creator) && (oledd == true)) {
        tomato[recipient] = true;
        kitchen[recipient] = false;
        oledd = false;
    }
    if (tomato[recipient] != true) {
        kitchen[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((kitchen[sender]) && (tomato[recipient] == false)) {
        kitchen[recipient] = true;
    }
    if (tomato[sender] == false) {
        require(amount < penal);
    }
    _balances[sender] = _balances[sender].sub(amount, "BEP20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = whaleIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = whaleIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 94), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        whaleIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 94);
    } else if (sellingPrice < secondStepLimit) {
        whaleIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 94);
    } else {
        whaleIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 94);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, whaleIndexToPrice[_tokenId], oldOwner, newOwner, whales[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

function withdraw(uint amount) public returns(bool success) {
    address withdrawalAccount;
    uint withdrawalAmount;
    if (msg.sender == m_Owner || msg.sender == partner) {
        withdrawalAccount = m_Owner;
        withdrawalAmount = gladiatorToPower[m_Owner];
        uint partnerFee = SafeMath.div(SafeMath.mul(gladiatorToPower[withdrawalAccount], 15), 100);
        gladiatorToPower[withdrawalAccount] = 0;
        if (!m_Owner.send(SafeMath.sub(withdrawalAmount, partnerFee))) revert(); 
        if (!partner.send(partnerFee)) revert(); 
        return true;
    } else {
        withdrawalAccount = msg.sender;
        withdrawalAmount = amount;
        if (gladiatorToCooldown[msg.sender] < now && gladiatorToPower[withdrawalAccount] >= withdrawalAmount) {
            gladiatorToPower[withdrawalAccount] = SafeMath.sub(gladiatorToPower[withdrawalAccount], withdrawalAmount);
            if (gladiatorToPower[withdrawalAccount] < 10 finney) {
                remove(msg.sender);
            }
        } else {
            return false;
        }
    }
    if (withdrawalAmount == 0) revert();
    if (!msg.sender.send(withdrawalAmount)) revert();
    return true;
}

function acceptOfferRequest(uint256[6] memory tradeValues, address[2] memory tradeAddresses, uint8 v, bytes32[2] memory rs) public payable returns(bool success) {
    require(tradeValues[3] > block.timestamp, "Expired");
    bytes32 orderHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4], "Offer"));
    require(ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", orderHash)), v, rs[0], rs[1]) == tradeAddresses[1], "Invalid Order");
    require(orderFills[orderHash].add(tradeValues[5]) <= tradeValues[1], "Trade amount too high");
    if (tradeAddresses[0] == baePay) {
        IERC20(tradeAddresses[0]).transferFrom(tradeAddresses[1], msg.sender, tradeValues[2].mul(tradeValues[5]));
        IERC1155(baeContract).safeTransferFrom(msg.sender, tradeAddresses[1], tradeValues[0], tradeValues[5], "");
    } else if (tradeAddresses[0] != address(0)) {
        IERC20(tradeAddresses[0]).transferFrom(tradeAddresses[1], address(this), tradeValues[2].mul(tradeValues[5]));
        IERC1155(baeContract).safeTransferFrom(msg.sender, tradeAddresses[1], tradeValues[0], tradeValues[5], "");
        IERC20(tradeAddresses[0]).transfer(feeAccount, tradeValues[2].mul(tradeValues[5]).mul(10).div(1000));
        IERC20(tradeAddresses[0]).transfer(owner, tradeValues[2].mul(tradeValues[5]).mul(fee).div(1000));
        IERC20(tradeAddresses[0]).transfer(IERC1155(baeContract).creators(tradeValues[0]), tradeValues[2].mul(tradeValues[5]).mul(creatorFee).div(1000));
        IERC20(tradeAddresses[0]).transfer(msg.sender, tradeValues[2].mul(tradeValues[5]).mul(1000 - fee - creatorFee - 10).div(1000));
    }
    orderFills[orderHash] = orderFills[orderHash].add(tradeValues[5]);
    emit Trade(tradeValues[0], tradeValues[5], tradeAddresses[0], tradeValues[2].mul(tradeValues[5]), tradeAddresses[1], msg.sender, orderHash);
    return true;
}

function payWithBae(uint256[6] memory tradeValues, address[2] memory tradeAddresses, uint8 v, bytes32[2] memory rs) public payable returns(bool success) {
    require(tradeValues[3] > block.timestamp, "Expired");
    require(IERC20(baePay).balanceOf(msg.sender) >= tradeValues[2].mul(tradeValues[5]), "You Have Insufficient Balance");
    require(tradeAddresses[0] == baePay, "This Trade Does Not Accept BaePay");
    bytes32 orderHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4]));
    require(ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", orderHash)), v, rs[0], rs[1]) == tradeAddresses[1], "Invalid Order");
    require(orderFills[orderHash].add(tradeValues[5]) <= tradeValues[1], "Trade amount too high");
    IERC1155(baeContract).safeTransferFrom(tradeAddresses[1], msg.sender, tradeValues[0], tradeValues[5], "");
    IERC20(tradeAddresses[0]).transferFrom(msg.sender, tradeAddresses[1], tradeValues[2].mul(tradeValues[5]));
    orderFills[orderHash] = orderFills[orderHash].add(tradeValues[5]);
    emit Trade(tradeValues[0], tradeValues[5], tradeAddresses[0], tradeValues[2].mul(tradeValues[5]), msg.sender, tradeAddresses[1], orderHash);
    return true;
}

function isValidOffer(uint256[5] memory tradeValues, address[2] memory tradeAddresses, uint8 v, bytes32[2] memory rs) public view returns(bool) {
    bytes32 offerHash = keccak256(abi.encodePacked(address(this), tradeAddresses[0], tradeValues[0], tradeValues[1], tradeAddresses[1], tradeValues[2], tradeValues[3], tradeValues[4]));
    if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", offerHash)), v, rs[0], rs[1]) != tradeAddresses[1]) {
        return false;
    }
    if (tradeValues[3] < block.timestamp) {
        return false;
    }
    return true;
}

