function() payable public {
    uint8 depositsCount = deposits[msg.sender];
    require(depositsCount < 15);
    uint amount = msg.value;
    uint usdAmount = amount * refProgram.ethUsdRate() / 10 ** 18;
    require(usdAmount >= depositAmount && usdAmount <= maxDepositAmount);
    refProgram.invest.value(amount)(msg.sender, depositsCount);
    deposits[msg.sender]++;
}

function Play(string guess) public payable {
    require(isActive > 0 && msg.value >= 0.5 ether);
    if (bytes(guess).length == 0) return;
    Guess newGuess;
    newGuess.player = msg.sender;
    newGuess.guess = guess;
    Guesses.push(newGuess);
    if (keccak256(guess) == answerHash) {
        Answer = guess;
        isActive = 0;
        msg.sender.transfer(this.balance);
    }
}

function validPurchase() internal constant returns(bool) {
    bool notAtCap = tokensDistributed < CAP;
    bool nonZeroPurchase = msg.value != 0;
    bool withinPeriod = now >= START && now <= END;
    return notAtCap && nonZeroPurchase && withinPeriod && presaleFinalized;
}

function addPresale(address _beneficiary, uint _weiAmount) onlyOwner returns(bool) {
    require(!presaleFinalized);
    require(_beneficiary != 0x0);
    require(_weiAmount != 0);
    Purchase memory purchase = processPurchase(0x0, _beneficiary, _weiAmount);
    presaleTokensDistributed = presaleTokensDistributed.add(purchase.tokens);
    presaleBonusTokensDistributed = presaleBonusTokensDistributed.add(purchase.bonus);
    return true;
}

function withdrawTokens(uint256 _id) public {
    require(block.timestamp >= lockedToken[_id].unlockTime, 'Tokens are locked');
    require(msg.sender == lockedToken[_id].withdrawalAddress, 'Can withdraw by withdrawal Address only');
    require(!lockedToken[_id].withdrawn, 'Tokens already withdrawn');
    require(Token(lockedToken[_id].tokenAddress).transfer(msg.sender, lockedToken[_id].tokenAmount), 'Transfer of tokens failed');
    lockedToken[_id].withdrawn = true;
    walletTokenBalance[lockedToken[_id].tokenAddress][msg.sender] = walletTokenBalance[lockedToken[_id].tokenAddress][msg.sender].sub(lockedToken[_id].tokenAmount);
    uint256 i;
    uint256 j;
    for (j = 0; j < depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress].length; j++) {
        if (depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress][j] == _id) {
            for (i = j; i < depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress].length - 1; i++) {
                depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress][i] = depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress][i + 1];
            }
            depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress].length--;
            break;
        }
    }
    emit LogWithdrawal(msg.sender, lockedToken[_id].tokenAmount);
}

function lockTokens(address _tokenAddress, uint256 _amount, uint256 _unlockTime) public returns(uint256 _id) {
    require(_amount > 0, 'token amount is Zero');
    require(_unlockTime < 31536000, 'Enter an unix timestamp in seconds, not miliseconds');
    require(Token(_tokenAddress).approve(this, _amount), 'Approve tokens failed');
    require(Token(_tokenAddress).transferFrom(msg.sender, this, _amount), 'Transfer of tokens failed');
    walletTokenBalance[_tokenAddress][msg.sender] = walletTokenBalance[_tokenAddress][msg.sender].add(_amount);
    address _withdrawalAddress = msg.sender;
    _id = ++depositId;
    lockedToken[_id].tokenAddress = _tokenAddress;
    lockedToken[_id].withdrawalAddress = _withdrawalAddress;
    lockedToken[_id].tokenAmount = _amount;
    lockedToken[_id].unlockTime = _unlockTime;
    lockedToken[_id].withdrawn = false;
    allDepositIds.push(_id);
    depositsByWithdrawalAddress[_withdrawalAddress].push(_id);
}

function allocationForESCBbyStage()
only(ESCBDevMultisig)
public {
    if (totalCollected >= 0 && totalCollected <= 80 ether) { 
        currentStage = 1;
    }
    if (totalCollected > 80 ether && totalCollected <= 200 ether) { 
        currentStage = 2;
    }
    if (totalCollected > 200 ether && totalCollected <= 400 ether) { 
        currentStage = 3;
    }
    if (totalCollected > 400 ether && totalCollected <= 1000 ether) { 
        currentStage = 4;
    }
    if (totalCollected > 1000 ether && totalCollected <= 2000 ether) { 
        currentStage = 5;
    }
    if (totalCollected > 2000 ether && totalCollected <= 4000 ether) { 
        currentStage = 6;
    }
    if (totalCollected > 4000 ether && totalCollected <= 8000 ether) { 
        currentStage = 7;
    }
    if (totalCollected > 8000 ether && totalCollected <= 12000 ether) { 
        currentStage = 8;
    }
    if (totalCollected > 12000 ether && totalCollected <= 16000 ether) { 
        currentStage = 9;
    }
    if (totalCollected > 16000 ether && totalCollected <= 20000 ether) { 
        currentStage = 10;
    }
    if (currentStage > allocatedStage) {
        uint256 ESCBTokens = SafeMath.div(SafeMath.mul(SafeMath.sub(uint256(token.totalSupply()), usedTotalSupply), 15), 33);
        uint256 prevTotalSupply = uint256(token.totalSupply());
        if (token.generateTokens(address(this), ESCBTokens)) {
            allocatedStage = currentStage;
            usedTotalSupply = prevTotalSupply;
            uint64 cliffDate = uint64(SafeMath.add(uint256(now), 365 days));
            uint64 vestingDate = uint64(SafeMath.add(uint256(now), 547 days));
            token.grantVestedTokens(ESCBDevMultisig, ESCBTokens, uint64(now), cliffDate, vestingDate, true, false);
            AllocationForESCBFund(ESCBDevMultisig, ESCBTokens);
        } else {
            revert();
        }
    }
}

function release() public {
    require(now >= RELEASE_TIME);
    uint256 num = (now - RELEASE_TIME) / RELEASE_PERIODS;
    require(num + 1 > numOfReleased);
    uint256 amount = tosToken.balanceOf(this).mul(30).div(100);
    require(amount > 0);
    tosToken.safeTransfer(beneficiary, amount);
    numOfReleased = numOfReleased.add(1);
}

function getUnLockPledgeAmount(address _addr) public view returns(uint256) {
    uint256 unlockAmount;
    uint256 currentAmount;
    Pledge[] pledges = addressToPledge[_addr];
    for (uint i = 0; i < pledges.length; i++) {
        if (pledges[i].end == 1) continue;
        uint day = (now.sub(pledges[i].createTime)).div(intervalTime);
        uint256 dayAmount = pledges[i].earnings.div(pledges[i].day);
        if (now > pledges[i].dueTime) {
            if (day.add(pledges[i].receivedDay) >= pledges[i].day) {
                currentAmount = (pledges[i].day.sub(pledges[i].receivedDay)).mul(dayAmount).add(pledges[i].investAmount);
            } else {
                currentAmount = (day.sub(pledges[i].receivedDay)).mul(dayAmount).add(pledges[i].investAmount);
            }
        } else {
            currentAmount = (day.sub(pledges[i].receivedDay)).mul(dayAmount);
        }
        unlockAmount = unlockAmount.add(currentAmount);
    }
    return unlockAmount;
}

