function depositeFod(uint256 _amount, uint _mode) public {
    uint256 yie = 100;
    if (useInviteCodeMap[msg.sender] != 0) {
        yie = yieldRate;
    }
    IERC20 fodToken = IERC20(fod);
    fodToken.transferFrom(msg.sender, this, _amount);
    uint256 dueTime = now.add(dayMap[_mode].mul(intervalTime));
    uint256 earnings = _amount.mul(yie).mul(dateToYields[_mode]).mul(dayMap[_mode]).div(3650000);
    Pledge memory pledge = Pledge(dayMap[_mode], _amount, earnings, now, dueTime, 0, 0);
    addressToPledge[msg.sender].push(pledge);
    if (useInviteCodeMap[msg.sender] != 0) {
        Invite memory invite = Invite(msg.sender, earnings.mul(inviteYieldRate).div(100), dayMap[_mode], now, dueTime, 0, 0);
        inviteLogs[useInviteCodeMap[msg.sender]].push(invite);
    }
    if (inviteCodeMap[bytes4(keccak256((msg.sender)))] == 0) {
        inviteCodeMap[bytes4(keccak256((msg.sender)))] = msg.sender;
    }
    emit DepositeFod(msg.sender, _amount);
}

function trade(TradeInput tradeInput) internal returns(uint) {
    require(isEnabled);
    require(tx.gasprice <= maxGasPriceValue);
    require(validateTradeInput(tradeInput.src, tradeInput.srcAmount, tradeInput.dest, tradeInput.destAddress));
    BestRateResult memory rateResult =
        findBestRateTokenToToken(tradeInput.src, tradeInput.dest, tradeInput.srcAmount, tradeInput.hint);
    require(rateResult.rate > 0);
    require(rateResult.rate < MAX_RATE);
    require(rateResult.rate >= tradeInput.minConversionRate);
    uint actualDestAmount;
    uint weiAmount;
    uint actualSrcAmount;
    (actualSrcAmount, weiAmount, actualDestAmount) = calcActualAmounts(tradeInput.src,
        tradeInput.dest,
        tradeInput.srcAmount,
        tradeInput.maxDestAmount,
        rateResult);
    require(getUserCapInWei(tradeInput.trader) >= weiAmount);
    require(handleChange(tradeInput.src, tradeInput.srcAmount, actualSrcAmount, tradeInput.trader));
    require(doReserveTrade( 
        tradeInput.src,
        actualSrcAmount,
        ETH_TOKEN_ADDRESS,
        this,
        weiAmount,
        KyberReserveInterface(rateResult.reserve1),
        rateResult.rateSrcToEth,
        true));
    require(doReserveTrade( 
        ETH_TOKEN_ADDRESS,
        weiAmount,
        tradeInput.dest,
        tradeInput.destAddress,
        actualDestAmount,
        KyberReserveInterface(rateResult.reserve2),
        rateResult.rateEthToDest,
        true));
    if (tradeInput.src != ETH_TOKEN_ADDRESS) 
        require(feeBurnerContract.handleFees(weiAmount, rateResult.reserve1, tradeInput.walletId));
    if (tradeInput.dest != ETH_TOKEN_ADDRESS) 
        require(feeBurnerContract.handleFees(weiAmount, rateResult.reserve2, tradeInput.walletId));
    KyberTrade({
        trader: tradeInput.trader,
        src: tradeInput.src,
        dest: tradeInput.dest,
        srcAmount: actualSrcAmount,
        dstAmount: actualDestAmount,
        destAddress: tradeInput.destAddress,
        ethWeiValue: weiAmount,
        reserve1: (tradeInput.src == ETH_TOKEN_ADDRESS) ? address(0) : rateResult.reserve1,
        reserve2: (tradeInput.dest == ETH_TOKEN_ADDRESS) ? address(0) : rateResult.reserve2,
        hint: tradeInput.hint
    });
    return actualDestAmount;
}

function listPairForReserve(address reserve, ERC20 token, bool ethToToken, bool tokenToEth, bool add)
public
onlyOperator
returns(bool) {
    require(reserveType[reserve] != ReserveType.NONE);
    if (ethToToken) {
        listPairs(reserve, token, false, add);
        ListReservePairs(reserve, ETH_TOKEN_ADDRESS, token, add);
    }
    if (tokenToEth) {
        listPairs(reserve, token, true, add);
        if (add) {
            require(token.approve(reserve, 2 ** 255)); 
        } else {
            require(token.approve(reserve, 0));
        }
        ListReservePairs(reserve, token, ETH_TOKEN_ADDRESS, add);
    }
    setDecimals(token);
    return true;
}

function airDrop(address[] recipients, uint amount) onlyOwner public {
    require(amount > 0);
    for (uint i = 0; i < recipients.length; i++) {
        myToken.transfer(recipients[i], amount);
        emit TokenDrop(recipients[i], amount);
    }
    numDrops += recipients.length;
    dropAmount += recipients.length * amount;
}

function pushPrivateInvestment(uint256 _weiAmount, uint256 _tokenAmount, address _beneficiary) external onlyOwner {
    require(block.timestamp <= closingTime);
    require(_weiAmount >= minimumInvestment, "Wei amount lower than minimum investment");
    require(_beneficiary != address(0));
    require(weiRaised.add(_weiAmount) <= cap);
    _deliverTokens(_beneficiary, _tokenAmount);
    weiRaised = weiRaised.add(_weiAmount);
    _addToWhitelist(_beneficiary);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        _weiAmount,
        _tokenAmount
    );
}

function changeRate(uint256 _newRate) external onlyOwner {
    require(block.timestamp <= closingTime);
    require(_newRate >= initialRate, "New rate must be greater than initial rate");
    rate = _newRate;
}

function processSalesForSingleBuyer(uint apiId, address buyerAddress) private returns(uint) {
    APIBalance storage apiBalance = owed[apiId];
    uint buyerOwes = apiBalance.amounts[buyerAddress];
    uint buyerLastPaidAtTime = apiBalance.buyerLastPaidAt[buyerAddress];
    if (buyerLastPaidAtTime == 0) {
        buyerLastPaidAtTime = now - defaultBuyerLastPaidAt; 
    }
    uint elapsedSecondsSinceLastPayout = now - buyerLastPaidAtTime;
    uint buyerNowOwes = buyerOwes;
    uint buyerPaid = 0;
    bool overdrafted = false;
    (buyerPaid, overdrafted) = chargeBuyer(apiId, buyerAddress, elapsedSecondsSinceLastPayout, buyerOwes);
    buyerNowOwes = buyerOwes.sub(buyerPaid);
    apiBalance.amounts[buyerAddress] = buyerNowOwes;
    if (buyerNowOwes != 0) {
        removeAddressFromNonzeroBalancesArray(apiId, buyerAddress);
    }
    if (buyerPaid == 0) {
        return 0;
    }
    emit LogSpendCredits(buyerAddress, apiId, buyerPaid, overdrafted);
    apiBalance.buyerLastPaidAt[buyerAddress] = now;
    return buyerPaid;
}

function withdrawCredits(uint amount) public {
    BuyerInfo storage buyer = buyers[msg.sender];
    require(buyer.credits >= amount);
    buyer.credits = buyer.credits.sub(amount);
    msg.sender.transfer(amount);
    emit LogWithdrawCredits(msg.sender, amount);
}

function withdrawEther(uint amount) public {
    require(msg.sender == withdrawAddress);
    require(amount <= this.balance);
    require(amount <= safeWithdrawAmount);
    safeWithdrawAmount = safeWithdrawAmount.sub(amount);
    withdrawAddress.transfer(amount);
}

function chargeBuyer(
    uint apiId,
    address buyerAddress,
    uint elapsedSecondsSinceLastPayout,
    uint buyerOwes
)
private
returns(
    uint paid,
    bool overdrafted
) {
    BuyerInfo storage buyer = buyers[buyerAddress];
    uint approvedAmountPerSecond = buyer.approvedAmounts[apiId];
    uint approvedAmountSinceLastPayout = approvedAmountPerSecond.mul(elapsedSecondsSinceLastPayout);
    if (buyer.credits >= buyerOwes) {
        overdrafted = false;
        buyer.overdrafted = false;
        if (approvedAmountSinceLastPayout >= buyerOwes) {
            buyer.exceededApprovedAmount[apiId] = false;
            paid = buyerOwes;
        } else {
            buyer.exceededApprovedAmount[apiId] = true;
            buyer.lifetimeExceededApprovalAmountCount += 1;
            paid = approvedAmountSinceLastPayout;
        }
    } else {
        overdrafted = true;
        buyer.overdrafted = true;
        buyer.lifetimeOverdraftCount += 1;
        if (buyer.credits >= approvedAmountSinceLastPayout) {
            paid = approvedAmountSinceLastPayout;
        } else {
            paid = buyer.credits;
        }
    }
    buyer.credits = buyer.credits.sub(paid);
    buyer.lifetimeCreditsUsed = buyer.lifetimeCreditsUsed.add(paid);
}

function paySellerForBuyer(uint apiId, address buyerAddress) public {
    Relay relay = Relay(relayContractAddress);
    address apiRegistryAddress = relay.apiRegistryContractAddress();
    APIRegistry apiRegistry = APIRegistry(apiRegistryAddress);
    uint pricePerCall;
    bytes32 sellerUsername;
    bytes32 apiName;
    address sellerAddress;
    (pricePerCall, sellerUsername, apiName, sellerAddress) = apiRegistry.getApiByIdWithoutDynamics(apiId);
    require(pricePerCall != 0 && sellerUsername != "" && apiName != "" && sellerAddress != address(0));
    uint buyerPaid = processSalesForSingleBuyer(apiId, buyerAddress);
    if (buyerPaid == 0) {
        return; 
    }
    uint fee = buyerPaid.mul(saleFee).div(100);
    uint payout = buyerPaid.sub(fee);
    safeWithdrawAmount += fee;
    emit LogAPICallsPaid(
        apiId,
        sellerAddress,
        buyerPaid,
        tokenReward,
        fee
    );
    rewardTokens(sellerAddress, tokenReward);
    sellerAddress.transfer(payout);
}

function paySeller(uint apiId) public {
    Relay relay = Relay(relayContractAddress);
    address apiRegistryAddress = relay.apiRegistryContractAddress();
    APIRegistry apiRegistry = APIRegistry(apiRegistryAddress);
    uint pricePerCall;
    bytes32 sellerUsername;
    bytes32 apiName;
    address sellerAddress;
    (pricePerCall, sellerUsername, apiName, sellerAddress) = apiRegistry.getApiByIdWithoutDynamics(apiId);
    require(pricePerCall != 0 && sellerUsername != "" && apiName != "" && sellerAddress != address(0));
    uint totalPayable = 0;
    uint totalBuyers = 0;
    (totalPayable, totalBuyers) = processSalesForAllBuyers(apiId);
    if (totalPayable == 0) {
        return; 
    }
    uint fee = totalPayable.mul(saleFee).div(100);
    uint payout = totalPayable.sub(fee);
    safeWithdrawAmount += fee;
    uint totalTokenReward = tokenReward.mul(totalBuyers);
    emit LogAPICallsPaid(
        apiId,
        sellerAddress,
        totalPayable,
        totalTokenReward,
        fee
    );
    rewardTokens(sellerAddress, totalTokenReward);
    sellerAddress.transfer(payout);
}

function rewardTokens(address toReward, uint amount) private {
    DeconetToken token = DeconetToken(tokenContractAddress);
    address tokenOwner = token.owner();
    uint tokenOwnerBalance = token.balanceOf(tokenOwner);
    uint tokenOwnerAllowance = token.allowance(tokenOwner, address(this));
    if (tokenOwnerBalance >= amount && tokenOwnerAllowance >= amount) {
        token.transferFrom(tokenOwner, toReward, amount);
    }
}

function processSalesForAllBuyers(uint apiId) private returns(uint totalPayable, uint totalBuyers) {
    APIBalance storage apiBalance = owed[apiId];
    uint currentTime = now;
    address[] memory oldNonzeroAddresses = apiBalance.nonzeroAddresses;
    apiBalance.nonzeroAddresses = new address[](0);
    for (uint i = 0; i < oldNonzeroAddresses.length; i++) {
        address buyerAddress = oldNonzeroAddresses[i];
        uint buyerOwes = apiBalance.amounts[buyerAddress];
        uint buyerLastPaidAtTime = apiBalance.buyerLastPaidAt[buyerAddress];
        if (buyerLastPaidAtTime == 0) {
            buyerLastPaidAtTime = now - defaultBuyerLastPaidAt; 
        }
        uint elapsedSecondsSinceLastPayout = currentTime - buyerLastPaidAtTime;
        uint buyerNowOwes = buyerOwes;
        uint buyerPaid = 0;
        bool overdrafted = false;
        (buyerPaid, overdrafted) = chargeBuyer(apiId, buyerAddress, elapsedSecondsSinceLastPayout, buyerOwes);
        totalPayable = totalPayable.add(buyerPaid);
        buyerNowOwes = buyerOwes.sub(buyerPaid);
        apiBalance.amounts[buyerAddress] = buyerNowOwes;
        if (buyerNowOwes != 0) {
            apiBalance.nonzeroAddresses.push(buyerAddress);
        }
        if (buyerPaid != 0) {
            emit LogSpendCredits(buyerAddress, apiId, buyerPaid, overdrafted);
            apiBalance.buyerLastPaidAt[buyerAddress] = now;
            totalBuyers += 1;
        }
    }
}

function reportUsage(uint apiId, uint numCalls, address buyerAddress) public {
    Relay relay = Relay(relayContractAddress);
    address apiRegistryAddress = relay.apiRegistryContractAddress();
    APIRegistry apiRegistry = APIRegistry(apiRegistryAddress);
    uint pricePerCall;
    bytes32 sellerUsername;
    bytes32 apiName;
    address sellerAddress;
    (pricePerCall, sellerUsername, apiName, sellerAddress) = apiRegistry.getApiByIdWithoutDynamics(apiId);
    require(sellerAddress != address(0));
    require(msg.sender == sellerAddress || msg.sender == usageReportingAddress);
    require(sellerUsername != "" && apiName != "");
    uint totalPrice = pricePerCall.mul(numCalls);
    require(totalPrice > 0);
    APIBalance storage apiBalance = owed[apiId];
    if (apiBalance.amounts[buyerAddress] == 0) {
        apiBalance.nonzeroAddresses.push(buyerAddress);
    }
    apiBalance.amounts[buyerAddress] = apiBalance.amounts[buyerAddress].add(totalPrice);
    emit LogAPICallsMade(
        apiId,
        sellerAddress,
        buyerAddress,
        pricePerCall,
        numCalls,
        totalPrice,
        msg.sender
    );
}

