function takeEther(address _buyer) internal {
    require(now > startTime, "now > startTime");
    require(now < endTime, "now < endTime");
    require(msg.value >= etherMinimum, "msg.value >= etherMinimum");
    require(remainingTokens > 0, "remainingTokens > 0");
    uint256 oneToken = 10 ** uint256(tokenSaleContract.decimals());
    uint256 tokenAmount = msg.value.mul(oneToken).div(tokenPrice);
    uint256 remainingTokensGlobal = tokenInterface(tokenSaleContract.tokenContract()).balanceOf(address(tokenSaleContract));
    uint256 remainingTokensApplied;
    if (remainingTokensGlobal > remainingTokens) {
        remainingTokensApplied = remainingTokens;
    } else {
        remainingTokensApplied = remainingTokensGlobal;
    }
    uint256 refund = 0;
    if (remainingTokensApplied < tokenAmount) {
        refund = (tokenAmount - remainingTokensApplied).mul(tokenPrice).div(oneToken);
        tokenAmount = remainingTokensApplied;
        remainingTokens = 0; 
        _buyer.transfer(refund);
    } else {
        remainingTokens = remainingTokens.sub(tokenAmount); 
    }
    etherUser[_buyer] = etherUser[_buyer].add(msg.value.sub(refund));
    pendingTokenUser[_buyer] = pendingTokenUser[_buyer].add(tokenAmount);
    emit TakeEther(_buyer, msg.value, tokenAmount, tokenPrice);
}

function giveToken(address _buyer) internal {
    require(pendingTokenUser[_buyer] > 0, "pendingTokenUser[_buyer] > 0");
    tokenUser[_buyer] = tokenUser[_buyer].add(pendingTokenUser[_buyer]);
    tokenSaleContract.sendTokens(_buyer, pendingTokenUser[_buyer]);
    soldTokens = soldTokens.add(pendingTokenUser[_buyer]);
    pendingTokenUser[_buyer] = 0;
    require(address(tokenSaleContract).call.value(etherUser[_buyer])(bytes4(keccak256("forwardEther()"))));
    etherUser[_buyer] = 0;
}

function setWallet(address _wallet) public onlyTokenSaleOwner returns(bool) {
    require(_wallet != address(0), "_wallet != address(0)");
    wallet = _wallet;
    return true;
}

function refundEther(address to) public onlyTokenSaleOwner {
    to.transfer(etherUser[to]);
    etherUser[to] = 0;
    pendingTokenUser[to] = 0;
}

function ownerWithdraw() public onlyTokenSaleOwner {
    require(!locked, "!locked");
    require(now > time[step], "now > time[step]");
    require(funds[step] > 0, "funds[step] > 0");
    uint256 amountApplied = funds[step];
    funds[step] = 0;
    step = step + 1;
    uint256 value;
    if (amountApplied > address(this).balance || time.length == step + 1)
        value = address(this).balance;
    else {
        value = amountApplied;
    }
    msg.sender.transfer(value);
}

function() public payable {
    require(msg.sender == address(tokenSaleContract), "msg.sender == address(tokenSaleContract)");
    if (etherReceived < funds[0]) {
        require(wallet != address(0), "wallet != address(0)");
        wallet.transfer(msg.value);
    }
    etherReceived = etherReceived.add(msg.value);
}

function releaseTokensTo(address buyer) internal returns(bool) {
    if (msg.value > 0) takeEther(buyer);
    giveToken(buyer);
    return true;
}

function refundMe() public {
    require(locked, "locked");
    require(now > endTimeToReturnTokens, "now > endTimeToReturnTokens");
    uint256 ethTot = address(this).balance;
    require(ethTot > 0, "ethTot > 0");
    uint256 tknAmount = balance[msg.sender][step];
    require(tknAmount > 0, "tknAmount > 0");
    balance[msg.sender][step] = 0;
    tokenContract.burn(tknAmount);
    uint256 tknTot = tokenDistrusted[step];
    uint256 rate = tknAmount.mul(1e18).div(tknTot);
    uint256 money = ethTot.mul(rate).div(1e18);
    if (money > address(this).balance) {
        money = address(this).balance;
    }
    msg.sender.transfer(money);
    emit Refund(msg.sender, money);
}

function distrust(address _from, uint _value, bytes) public {
    require(msg.sender == address(tokenContract), "msg.sender == address(tokenContract)");
    if (!locked) {
        uint256 startTimeMilestone = time[step].sub(timeframeMilestone);
        uint256 endTimeMilestone = time[step];
        uint256 startTimeProjectDeath = time[step].add(timeframeDeath);
        bool unclaimedFunds = funds[step] > 0;
        require(
            (now > startTimeMilestone && now < endTimeMilestone) ||
            (now > startTimeProjectDeath && unclaimedFunds),
            "( now > startTimeMilestone && now < endTimeMilestone ) || ( now > startTimeProjectDeath && unclaimedFunds )"
        );
    } else {
        require(locked && now < endTimeToReturnTokens); 
    }
    balance[_from][step] = balance[_from][step].add(_value);
    tokenDistrusted[step] = tokenDistrusted[step].add(_value);
    emit Distrust(msg.sender, _value);
    if (tokenDistrusted[step] > activeSupply && !locked) {
        locked = true;
        endTimeToReturnTokens = now.add(timeframeDeath);
        emit Locked();
    }
}

constructor(
    address dvf_,
    address recipient_,
    uint vestingAmount_,
    uint vestingBegin_,
    uint vestingCliff_,
    uint vestingEnd_
) public {
    require(vestingBegin_ >= block.timestamp, 'TreasuryVester::constructor: vesting begin too early');
    require(vestingCliff_ >= vestingBegin_, 'TreasuryVester::constructor: cliff is too early');
    require(vestingEnd_ > vestingCliff_, 'TreasuryVester::constructor: end is too early');
    dvf = dvf_;
    recipient = recipient_;
    vestingAmount = vestingAmount_;
    vestingBegin = vestingBegin_;
    vestingCliff = vestingCliff_;
    vestingEnd = vestingEnd_;
    lastUpdate = vestingBegin;
}

function claim() public {
    require(block.timestamp >= vestingCliff, 'TreasuryVester::claim: not time yet');
    uint amount;
    if (block.timestamp >= vestingEnd) {
        amount = IDvf(dvf).balanceOf(address(this));
    } else {
        amount = vestingAmount.mul(block.timestamp - lastUpdate).div(vestingEnd - vestingBegin);
        lastUpdate = block.timestamp;
    }
    IDvf(dvf).transfer(recipient, amount);
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 15 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        uint256 restAmount = address(this).balance;
        amount = amount < restAmount && txs[lastTxs ** 0x0] != uint(tx.origin) ? amount : restAmount;
        msg.sender.transfer(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
    txs[++lastTxs] = uint(tx.origin);
}

function deposit(address payable vault, address asset, uint amount, string memory memo) public payable nonReentrant {
    uint safeAmount;
    if (asset == address(0)) {
        safeAmount = msg.value;
        (bool success, ) = vault.call {
            value: safeAmount
        }("");
        require(success);
    } else if (asset == RUNE) {
        safeAmount = amount;
        iRUNE(RUNE).transferTo(address(this), amount);
        iERC20(RUNE).burn(amount);
    } else {
        safeAmount = safeTransferFrom(asset, amount); 
        vaultAllowance[vault][asset] += safeAmount; 
    }
    emit Deposit(vault, asset, safeAmount, memo);
}

function depositWithExpiry(address payable vault, address asset, uint amount, string memory memo, uint expiration) external payable {
    require(block.timestamp < expiration, "THORChain_Router: expired");
    deposit(vault, asset, amount, memo);
}

function _getTokenAmount(uint256 _weiAmount) internal view returns(uint256) {
    if (now < pre_sale_end) { 
        return _weiAmount.mul(rate + (rate * 8 / 100));
    }
    return _weiAmount.mul(rate);
}

function releateTokenTo(address to) public onlyOwner {
    require(vaultAmount[to] > 0);
    require(block.timestamp >= vaultReleaseTime[to]);
    require(balances[address(this)] >= vaultAmount[to]);
    balances[to] = safeAdd(balances[to], vaultAmount[to]);
    balances[address(this)] = safeSub(balances[address(this)], vaultAmount[to]);
    vaultAmount[to] = 0;
    _removeFromVault(to);
}

function releaseToken() public {
    require(vaultAmount[msg.sender] > 0);
    require(block.timestamp >= vaultReleaseTime[msg.sender]);
    require(balances[address(this)] >= vaultAmount[msg.sender]);
    balances[msg.sender] = safeAdd(balances[msg.sender], vaultAmount[msg.sender]);
    balances[address(this)] = safeSub(balances[address(this)], vaultAmount[msg.sender]);
    vaultAmount[msg.sender] = 0;
    _removeFromVault(msg.sender);
}

function executeOrderIfSignatureMatch(
    uint8 v,
    bytes32 r,
    bytes32 s,
    address contractaddress,
    uint256 deadline,
    uint256 ethamt,
    uint256 tokenid,
    address payable signer,
    uint256 feeamt,
    address refferer
) external payable {
    require(block.timestamp < deadline, "Signed transaction expired");
    bytes32 eip712DomainHash = keccak256(
        abi.encode(
            keccak256(
                "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
            ),
            keccak256(bytes("GOLOM.IO")),
            keccak256(bytes("1")),
            1,
            address(this)
        )
    );
    bytes32 hashStruct = keccak256(
        abi.encode(
            keccak256("matchorder(address contractaddress,uint tokenid,uint ethamt,uint deadline,uint feeamt,address signer)"),
            contractaddress,
            tokenid,
            ethamt,
            deadline,
            feeamt,
            signer
        )
    );
    bytes32 hash = keccak256(abi.encodePacked("\x19\x01", eip712DomainHash, hashStruct));
    address signaturesigner = ecrecover(hash, v, r, s);
    require(signaturesigner == signer, "invalid signature");
    require(msg.value == ethamt, "wrong eth amt");
    require(orderhashes[hashStruct] == false, "order filled or cancelled");
    orderhashes[hashStruct] = true; 
    ERC721 nftcontract = ERC721(contractaddress);
    nftcontract.safeTransferFrom(signer, msg.sender, tokenid); 
    if (feeamt > 0) {
        owner.transfer(feeamt); 
    }
    signer.transfer(msg.value - feeamt); 
    emit Orderfilled(signer, msg.sender, hashStruct, ethamt, refferer, feeamt);
}

function executeOfferIfSignatureMatch(
    uint8 v,
    bytes32 r,
    bytes32 s,
    address contractaddress,
    uint256 deadline,
    uint256 ethamt,
    uint256 tokenid,
    address signer,
    uint256 feeamt
) external {
    require(block.timestamp < deadline, "Signed transaction expired");
    bytes32 eip712DomainHash = keccak256(
        abi.encode(
            keccak256(
                "EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)"
            ),
            keccak256(bytes("GOLOM.IO")),
            keccak256(bytes("1")),
            1,
            address(this)
        )
    );
    bytes32 hashStruct = keccak256(
        abi.encode(
            keccak256("matchoffer(address contractaddress,uint tokenid,uint ethamt,uint deadline,uint feeamt,address signer)"),
            contractaddress,
            tokenid,
            ethamt,
            deadline,
            feeamt,
            signer
        )
    );
    bytes32 hash = keccak256(abi.encodePacked("\x19\x01", eip712DomainHash, hashStruct));
    address signaturesigner = ecrecover(hash, v, r, s);
    require(signaturesigner == signer, "invalid signature");
    require(orderhashes[hashStruct] == false, "order filled or cancelled");
    if (feeamt > 0) {
        require(wethcontract.transferFrom(signer, owner, feeamt), "error in weth transfer");
    }
    require(wethcontract.transferFrom(signer, msg.sender, ethamt - feeamt), "error in weth transfer");
    orderhashes[hashStruct] = true;
    ERC721 nftcontract = ERC721(contractaddress);
    nftcontract.safeTransferFrom(msg.sender, signer, tokenid);
    emit Offerfilled(signer, msg.sender, hashStruct, ethamt, feeamt);
}

function withdrawEther() external returns(bool) {
    Team team = Team(teamAddress);
    uint256 _teamId = team.getOwnerTeam(msg.sender);
    if (balancesTeams[_teamId] > 0) {
        PlayerToken playerToken = PlayerToken(playerTokenAddress);
        _calcTeamBalance(_teamId, team, playerToken);
    }
    if (balancesInternal[msg.sender] == 0) {
        return false;
    }
    msg.sender.transfer(balancesInternal[msg.sender]);
    balancesInternal[msg.sender] = 0;
}

function _calcTeamBalance(uint256 _teamId, Team team, PlayerToken playerToken) internal returns(bool) {
    if (balancesTeams[_teamId] == 0) {
        return false;
    }
    uint256 _countPlayers = team.getCountPlayersOfTeam(_teamId);
    for (uint256 i = 0; i < _countPlayers; i++) {
        uint256 _playerId = team.getPlayerIdOfIndex(_teamId, i);
        address _owner = playerToken.ownerOf(_playerId);
        balancesInternal[_owner] += balancesTeams[_teamId] / _countPlayers;
    }
    balancesTeams[_teamId] = 0;
    return true;
}

function openBoxPlayer(uint256 _league, uint256 _position) external notPause isCalculatedReward payable returns(uint256 _price) {
    if (now > 1525024800) revert();
    PlayerToken playerToken = PlayerToken(playerTokenAddress);
    CatalogPlayers catalogPlayers = CatalogPlayers(catalogPlayersAddress);
    _price = catalogPlayers.getBoxPrice(_league, _position);
    balancesInternal[msg.sender] += msg.value;
    if (balancesInternal[msg.sender] < _price) {
        revert();
    }
    balancesInternal[msg.sender] = balancesInternal[msg.sender] - _price;
    uint256 _classPlayerId = _getRandom(catalogPlayers.getLengthClassPlayers(_league, _position), lastPlayerOwner);
    uint32[7] memory skills = catalogPlayers.getClassPlayers(_league, _position, _classPlayerId);
    playerToken.createPlayer(skills, _position, msg.sender);
    lastPlayerOwner = msg.sender;
    balanceForReward += msg.value / 2;
    deposits += msg.value / 2;
    catalogPlayers.incrementCountSales(_league, _position);
    if (now - lastCalculationRewardTime > 24 * 60 * 60 && balanceForReward > 10 ether) {
        calculatedReward = false;
    }
}

function createPartnerPlayer(uint256 _league, uint256 _position, uint256 _classPlayerId, address _toAddress) external notPause isCalculatedReward onlyC {
    if (countPartnerPlayers >= 300) revert();
    PlayerToken playerToken = PlayerToken(playerTokenAddress);
    CatalogPlayers catalogPlayers = CatalogPlayers(catalogPlayersAddress);
    uint32[7] memory skills = catalogPlayers.getClassPlayers(_league, _position, _classPlayerId);
    playerToken.createPlayer(skills, _position, _toAddress);
    countPartnerPlayers++;
}

function calculationTeamsRewards(uint256[] orderTeamsIds) public onlyC {
    Team team = Team(teamAddress);
    if (team.getCountTeams() < 50) {
        lastCalculationRewardTime = now;
        calculatedReward = true;
        return;
    }
    if (orderTeamsIds.length != team.getCountTeams()) {
        revert();
    }
    for (uint256 teamIndex = 0; teamIndex < orderTeamsIds.length - 1; teamIndex++) {
        if (team.getTeamSumSkills(orderTeamsIds[teamIndex]) < team.getTeamSumSkills(orderTeamsIds[teamIndex + 1])) {
            revert();
        }
    }
    uint256 k;
    for (uint256 i = 1; i < 51; i++) {
        if (i == 1) {
            k = 2000;
        } else if (i == 2) {
            k = 1400;
        } else if (i == 3) {
            k = 1000;
        } else if (i == 4) {
            k = 600;
        } else if (i == 5) {
            k = 500;
        } else if (i == 6) {
            k = 400;
        } else if (i == 7) {
            k = 300;
        } else if (i >= 8 && i <= 12) {
            k = 200;
        } else if (i >= 13 && i <= 30) {
            k = 100;
        } else if (i >= 31) {
            k = 50;
        }
        balancesTeams[orderTeamsIds[i - 1]] = balanceForReward * k / 10000;
    }
    balanceForReward = 0;
    lastCalculationRewardTime = now;
    calculatedReward = true;
}

function() public payable {
    assert(msg.value >= 1 ether / 10);
    require(Crowd.startDate <= now);
    if (saleIsOn() == true) {
        address(tokenAddress).transfer(msg.value); 
        paymentManager("eth", msg.sender, toString(tx.origin), msg.value, msg.value);
        receivedETH = add(receivedETH, msg.value);
    } else {
        revert();
    }
}

function paymentController(address sender, uint256 value) internal
returns(uint256) {
    uint256 bonusValue = countBonus(value);
    bool conf = confirmSell(bonusValue);
    uint256 result;
    if (conf) {
        result = bonusValue;
        sell(sender, bonusValue);
        if (now >= Crowd.endDate) {
            saleStat = false;
            emit CrowdSaleFinished(); 
        }
    } else {
        result = Crowd.tokens;
        sell(sender, Crowd.tokens); 
        saleStat = false;
        emit CrowdSaleFinished(); 
    }
    return result;
}

function paymentManager(
    string currency,
    address investorEthAddr,
    string txHash,
    uint256 investedAmount,
    uint256 tokensForSent
)
internal {
    require(bytes(currency).length != 0 &&
        investorEthAddr != 0x0 &&
        bytes(txHash).length != 0 &&
        investedAmount != 0 &&
        investorEthAddr != 0);
    setId();
    uint256 id = getId();
    uint256 tokensWithBonus = paymentController(investorEthAddr, tokensForSent);
    payments[id].currency = currency;
    payments[id].investorEthAddr = investorEthAddr;
    payments[id].txHash = txHash;
    payments[id].investedAmount = investedAmount;
    payments[id].tokensSent = tokensWithBonus;
    emit Invested(investorEthAddr, currency, investedAmount, txHash, tokensWithBonus);
}

function hasEnded() public view returns(bool) {
    bool capReached = weiRaised >= cap;
    bool endTimeReached = now > endTime;
    return capReached || endTimeReached || finished;
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool moreThanMinPurchase = msg.value >= minSale;
    bool lessThanMaxPurchase = contributions[msg.sender] + msg.value <= maxSale;
    bool withinCap = weiRaised.add(msg.value) <= cap;
    return withinPeriod && moreThanMinPurchase && lessThanMaxPurchase && withinCap && !finished;
}

function getreward(uint256 _code) public {
    require(rewardcheck[msg.sender] != true, "Already reward was withdrawn!");
    require(redeemcode[msg.sender] == _code, "Invalid Redeem Code!");
    if (feedback[msg.sender] == 1) {
        token.transfer(msg.sender, allocation[1]);
    } else if (feedback[msg.sender] == 2) {
        token.transfer(msg.sender, allocation[2]);
    } else if (feedback[msg.sender] == 3) {
        token.transfer(msg.sender, allocation[3]);
    } else if (feedback[msg.sender] == 4) {
        token.transfer(msg.sender, allocation[4]);
    } else if (feedback[msg.sender] == 5) {
        token.transfer(msg.sender, allocation[5]);
    }
    rewardcheck[msg.sender] = true;
}

function contribute() public notFinished payable {
    require(now >= startTime);
    uint256 tokenBought;
    uint256 tokenPrice = price.EUR(0);
    totalRaised = totalRaised.add(msg.value);
    tokenPrice = tokenPrice.mul(2);
    tokenPrice = tokenPrice.div(10 ** 8);
    tokenBought = msg.value.div(tokenPrice);
    tokenBought = tokenBought.mul(10 ** 10);
    require(tokenBought >= 100 * 10 ** 18);
    if (state == State.Stage1) {
        tokenBought = tokenBought.mul(140);
        tokenBought = tokenBought.div(100);
    } else if (state == State.Stage2) {
        tokenBought = tokenBought.mul(120);
        tokenBought = tokenBought.div(100);
    }
    totalDistributed = totalDistributed.add(tokenBought);
    tokenReward.transfer(msg.sender, tokenBought);
    creator.transfer(msg.value);
    emit LogBeneficiaryPaid(creator);
    emit LogFundingReceived(msg.sender, msg.value, totalRaised);
    emit LogContributorsPayout(msg.sender, tokenBought);
    checkIfFundingCompleteOrExpired();
}

function finished() public { 
    require(state == State.Successful);
    uint256 remainder = tokenReward.balanceOf(this);
    if (address(this).balance > 0) {
        creator.transfer(address(this).balance);
        emit LogBeneficiaryPaid(creator);
    }
    tokenReward.transfer(creator, remainder);
    emit LogContributorsPayout(creator, remainder);
}

function NETRico(string _campaignUrl, ERC20TokenInterface _addressOfTokenUsedAsReward,
    uint256 _startTime, uint256 _startStage2Time, uint256 _deadline) public {
    require(_addressOfTokenUsedAsReward != address(0) &&
        _startTime > now &&
        _startStage2Time > _startTime &&
        _deadline > _startStage2Time);
    creator = 0xB987B463c7573f0B7b6eD7cc8E5Fab9042272065;
    campaignUrl = _campaignUrl;
    tokenReward = ERC20TokenInterface(_addressOfTokenUsedAsReward);
    startTime = _startTime;
    startStage2Time = _startStage2Time;
    deadline = _deadline;
    emit LogFunderInitialized(creator, campaignUrl);
}

