    if (daysFromStart == 2) return 10; 
    if (daysFromStart == 3) return 10; 
    if (daysFromStart == 4) return 5; 
    if (daysFromStart == 5) return 5; 
    if (daysFromStart == 6) return 5; 
    return 0;
}

