function() payable external whenNotPaused {
    require(msg.value >= minimalEthers);
    uint256 tokens = msg.value.mul(depositCommission).mul(priceEthPerToken).div(10000);
    totalSupply_ = totalSupply_.add(tokens);
    uint256 lockTokens = tokens.mul(100).div(lockTokensPercent);
    _lockPaymentTokens(msg.sender, lockTokens, now.add(lockTimestamp));
    balances[msg.sender] = balances[msg.sender].add(tokens);
    investWallet.transfer(msg.value.mul(investCommission).div(100));
    depositWallet.transfer(msg.value.mul(uint256(100).sub(depositCommission)).div(100));
    emit Transfer(rubusBlackAddress, msg.sender, tokens);
    emit Deposit(msg.sender, msg.value, tokens, priceEthPerToken, depositCommission);
}

function transferFrom(
    address _from,
    address _to,
    uint256 _value
)
public
whenNotPaused
returns(bool) {
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    require(_value <= checkVesting(_from));
    if (_to == rubusBlackAddress) {
        require(!lock);
        uint256 weiAmount = _value.mul(withdrawCommission).div(priceEthPerToken);
        require(weiAmount <= uint256(address(this).balance));
        totalSupply_ = totalSupply_.sub(_value);
        msg.sender.transfer(weiAmount);
        withdrawWallet.transfer(weiAmount.mul(uint256(100).sub(withdrawCommission)).div(100));
        emit Withdraw(msg.sender, weiAmount, _value, priceEthPerToken, withdrawCommission);
    } else {
        balances[_to] = balances[_to].add(_value);
    }
    balances[_from] = balances[_from].sub(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) whenNotPaused public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    require(_value <= checkVesting(msg.sender));
    if (_to == rubusBlackAddress) {
        require(!lock);
        uint256 weiAmount = _value.mul(withdrawCommission).div(priceEthPerToken);
        require(weiAmount <= uint256(address(this).balance));
        totalSupply_ = totalSupply_.sub(_value);
        msg.sender.transfer(weiAmount);
        withdrawWallet.transfer(weiAmount.mul(uint256(100).sub(withdrawCommission)).div(100));
        emit Withdraw(msg.sender, weiAmount, _value, priceEthPerToken, withdrawCommission);
    } else {
        balances[_to] = balances[_to].add(_value);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function checkVesting(address sender) public view returns(uint256) {
    uint256 availableTokens = 0;
    for (uint i = 0; i < balancesLock[sender].length; i++) {
        (uint lockTokens, uint lockTime) = getPurchases(sender, i);
        if (now >= lockTime) {
            availableTokens = availableTokens.add(lockTokens);
        }
    }
    return availableTokens;
}

function buyTokens() public payable {
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value.mul(105); 
    } else {
        tokens = msg.value.mul(100); 
    }
    tokens = msg.value.mul(100);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    allTokens = allTokens.add(tokens);
    emit Transfer(address(0), msg.sender, tokens);
    allContributers++;
}

function unlockLiquidity(uint idx) external { 
    require(liquidityRewardData[msg.sender][idx].liquidityClaimed == false, "LiquidityAlreadyClaimed");
    if (liquidityRewardData[msg.sender][idx].rewardClaimed == false) {
        rewardTask(idx, 0);
    }
    totalUniswapLiquidity -= liquidityRewardData[msg.sender][idx].quantity;
    ERC20Token(LIQUIDITY_TOKEN).approve(address(this), liquidityRewardData[msg.sender][idx].quantity);
    ERC20Token(LIQUIDITY_TOKEN).transferFrom(address(this), address(msg.sender), liquidityRewardData[msg.sender][idx].quantity);
    liquidityRewardData[msg.sender][idx].quantity = 0;
    liquidityRewardData[msg.sender][idx].liquidityClaimed = true;
}

function removeReward() external onlyOwner {
    require(ERC20Token(REWARD_TOKEN).transferFrom(address(this), address(msg.sender), unallocatedRewards), "tokenXferFail");
    unallocatedRewards = 0;
}

function lockLiquidity(uint idx, uint stakeMonths, uint stakeTokens) external {
    require(stakeMonths <= MAX_MONTHS, "tooManyMonths");
    require(ERC20Token(LIQUIDITY_TOKEN).transferFrom(address(msg.sender), address(this), stakeTokens), "tokenXferFail");
    require((liquidityRewardData[msg.sender][idx].quantity == 0), "previousLiquidityInSlot");
    uint reward = calcReward(stakeMonths, stakeTokens);
    require(unallocatedRewards >= reward, "notEnoughRewardRemaining");
    allocatedRewards += reward;
    unallocatedRewards -= reward;
    totalUniswapLiquidity += stakeTokens;
    liquidityRewardData[msg.sender][idx] = LiquidityRewardData(stakeTokens, block.timestamp, stakeMonths, reward, false, false);
}

function rewardTask(uint idx, uint renewMonths) public {
    require(liquidityRewardData[msg.sender][idx].rewardClaimed == false, "RewardClaimedAlready");
    liquidityRewardData[msg.sender][idx].rewardClaimed = true;
    uint reward = liquidityRewardData[msg.sender][idx].reward;
    allocatedRewards -= reward;
    if (liquidityRewardData[msg.sender][idx].timestamp.add(liquidityRewardData[msg.sender][idx].stakeMonths.mul(ONE_MONTH)) <= block.timestamp) {
        if (renewMonths > 0 && liquidityRewardData[msg.sender][idx].liquidityClaimed == false) { 
            uint newReward = calcReward(renewMonths, liquidityRewardData[msg.sender][idx].quantity);
            require(newReward < unallocatedRewards, "NotEnoughRewardsRemaining");
            allocatedRewards += newReward;
            unallocatedRewards -= newReward;
            liquidityRewardData[msg.sender][idx].timestamp = block.timestamp;
            liquidityRewardData[msg.sender][idx].stakeMonths = renewMonths;
            liquidityRewardData[msg.sender][idx].reward = newReward;
            liquidityRewardData[msg.sender][idx].rewardClaimed = false;
        }
        ERC20Token(REWARD_TOKEN).approve(address(this), reward);
        ERC20Token(REWARD_TOKEN).transferFrom(address(this), address(msg.sender), reward);
    } else {
        unallocatedRewards += reward;
    }
}

function topupReward(uint amount) external {
    require(ERC20Token(REWARD_TOKEN).transferFrom(address(msg.sender), address(this), amount), "tokenXferFail");
    uint tokensToBurn = findOnePercent(amount);
    uint actual = amount.sub(tokensToBurn);
    unallocatedRewards += actual;
}

function issue(address[] payees, uint256[] values, uint16[] deferDays) public onlyOwner returns(bool) {
    require(payees.length > 0 && payees.length == values.length);
    uint256 _now0 = _getNow0();
    for (uint i = 0; i < payees.length; i++) {
        require(balances[owner] >= values[i], "Issuer balance is insufficient.");
        if (payees[i] == address(0) || values[i] == uint256(0)) {
            continue;
        }
        balances[owner] = balances[owner].sub(values[i]);
        balances[payees[i]] = balances[payees[i]].add(values[i]);
        emit Transfer(owner, payees[i], values[i]);
        uint256 _date0 = _now0.add(deferDays[i] * 24 * 3600);
        if (_date0 > _now0) {
            Info storage _info = fellowInfo[payees[i]];
            uint256 _fValue = _info.frozenValues[_date0];
            if (_fValue == 0) {
                _info.defrozenDates.push(_date0);
            }
            _info.totalFrozenValue = _info.totalFrozenValue.add(values[i]);
            _info.frozenValues[_date0] = _info.frozenValues[_date0].add(values[i]);
            balances[payees[i]] = balances[payees[i]].sub(values[i]);
            balances[frozenAddress] = balances[frozenAddress].add(values[i]);
            emit Transfer(payees[i], frozenAddress, values[i]);
            emit Frozen(payees[i], values[i], _date0, _info.totalFrozenValue);
        }
    }
    return true;
}

function defrozen(address fellow) public onlyOwner returns(bool) {
    require(fellow != address(0));
    Info storage _info = fellowInfo[fellow];
    require(_info.totalFrozenValue > 0);
    for (uint i = 0; i < _info.defrozenDates.length; i++) {
        uint256 _date0 = _info.defrozenDates[i];
        if (_info.frozenValues[_date0] > 0 && now >= _date0) {
            uint256 _defrozenValue = _info.frozenValues[_date0];
            require(balances[frozenAddress] >= _defrozenValue);
            balances[frozenAddress] = balances[frozenAddress].sub(_defrozenValue);
            balances[fellow] = balances[fellow].add(_defrozenValue);
            _info.totalFrozenValue = _info.totalFrozenValue.sub(_defrozenValue);
            _info.frozenValues[_date0] = 0;
            emit Transfer(frozenAddress, fellow, _defrozenValue);
            emit Defrozen(fellow, _defrozenValue, _date0, _info.totalFrozenValue);
        }
    }
    return true;
}

function airdrop(address[] payees, uint256 value, uint16 deferDays) public onlyOwner returns(bool) {
    require(payees.length > 0 && value > 0);
    uint256 _amount = value.mul(payees.length);
    require(balances[owner] > _amount);
    uint256 _now0 = _getNow0();
    uint256 _date0 = _now0.add(deferDays * 24 * 3600);
    for (uint i = 0; i < payees.length; i++) {
        require(balances[owner] >= value, "Issuer balance is insufficient.");
        if (payees[i] == address(0)) {
            _amount = _amount.sub(value);
            continue;
        }
        balances[payees[i]] = balances[payees[i]].add(value);
        emit Transfer(owner, payees[i], value);
        if (_date0 > _now0) {
            Info storage _info = fellowInfo[payees[i]];
            uint256 _fValue = _info.frozenValues[_date0];
            if (_fValue == 0) {
                _info.defrozenDates.push(_date0);
            }
            _info.totalFrozenValue = _info.totalFrozenValue.add(value);
            _info.frozenValues[_date0] = _info.frozenValues[_date0].add(value);
            balances[payees[i]] = balances[payees[i]].sub(value);
            balances[frozenAddress] = balances[frozenAddress].add(value);
            emit Transfer(payees[i], frozenAddress, value);
            emit Frozen(payees[i], value, _date0, _info.totalFrozenValue);
        }
    }
    balances[owner] = balances[owner].sub(_amount);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    if (_to == frozenAddress) {
        Info storage _info = fellowInfo[msg.sender];
        if (_info.totalFrozenValue > 0) {
            for (uint i = 0; i < _info.defrozenDates.length; i++) {
                uint256 _date0 = _info.defrozenDates[i];
                if (_info.frozenValues[_date0] > 0 && now >= _date0) {
                    uint256 _defrozenValue = _info.frozenValues[_date0];
                    require(balances[frozenAddress] >= _defrozenValue);
                    balances[frozenAddress] = balances[frozenAddress].sub(_defrozenValue);
                    balances[msg.sender] = balances[msg.sender].add(_defrozenValue);
                    _info.totalFrozenValue = _info.totalFrozenValue.sub(_defrozenValue);
                    _info.frozenValues[_date0] = 0;
                    emit Transfer(frozenAddress, msg.sender, _defrozenValue);
                    emit Defrozen(msg.sender, _defrozenValue, _date0, _info.totalFrozenValue);
                }
            }
        }
    }
    return true;
}

function _transfer(
    address sender,
    address recipient,
    uint256 amount
) internal virtual {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if (botProtector_ != address(0)) {
        require(!IBotProtector(botProtector_).isPotentialBotTransfer(sender, recipient), "Bot transaction debounced");
    }
    uint256 senderBalance = balances_[sender];
    require(senderBalance >= amount, "ERC20: transfer amount exceeds balance");
    unchecked {
        balances_[sender] = senderBalance - amount;
    }
    balances_[recipient] += amount;
    emit Transfer(sender, recipient, amount);
}

function transferFrom(
    address sender,
    address recipient,
    uint256 amount
) external virtual override returns(bool) {
    _transfer(sender, recipient, amount);
    uint256 currentAllowance = allowances_[sender][_msgSender()];
    require(currentAllowance >= amount, "ERC20: transfer amount exceeds allowance");
    unchecked {
        _approve(sender, _msgSender(), currentAllowance - amount);
    }
    return true;
}

function() payable {
    if (!purchasingAllowed) {
        throw;
    }
    if (msg.value == 0) {
        return;
    }
    owner.transfer(msg.value);
    totalContribution += msg.value;
    uint256 tokensIssued = (msg.value * 20000);
    balances[msg.sender] += tokensIssued;
    Transfer(address(this), msg.sender, tokensIssued);
}

function processActionProposal(uint256 proposalIndex) external nonReentrant returns(bool, bytes memory) {
    _validateProposalForProcessing(proposalIndex);
    uint256 proposalId = proposalQueue[proposalIndex];
    bytes memory action = actions[proposalId];
    Proposal storage proposal = proposals[proposalId];
    require(proposal.flags[6] == 1, "!action");
    proposal.flags[1] = 1; 
    bool didPass = _didPass(proposalIndex);
    if (proposal.paymentToken == address(0) && proposal.tributeOffered > address(this).balance) {
        didPass = false;
    }
    if (proposal.paymentToken == stakeToken && proposal.paymentRequested > IERC20(stakeToken).balanceOf(address(this))) {
        didPass = false;
    }
    if (proposal.paymentToken != address(0) && proposal.paymentToken != stakeToken && proposal.paymentRequested > userTokenBalances[GUILD][proposal.paymentToken]) {
        didPass = false;
    }
    if (didPass == true) {
        proposal.flags[2] = 1; 
        (bool success, bytes memory retData) = proposal.applicant.call.value(proposal.tributeOffered)(action);
        if (proposal.paymentToken != address(0) && proposal.paymentToken != stakeToken) {
            unsafeSubtractFromBalance(GUILD, proposal.paymentToken, proposal.paymentRequested);
            if (userTokenBalances[GUILD][proposal.paymentToken] == 0 && proposal.paymentRequested > 0) {
                totalGuildBankTokens -= 1;
            }
        }
        return (success, retData);
    }
    emit ProcessActionProposal(proposalIndex, proposalId, didPass);
}

function submitProposal(
    address applicant,
    uint256 sharesRequested,
    uint256 lootRequested,
    uint256 tributeOffered,
    address tributeToken,
    uint256 paymentRequested,
    address paymentToken,
    bytes32 details
) payable external nonReentrant returns(uint256 proposalId) {
    require(sharesRequested.add(lootRequested) <= MAX_GUILD_BOUND, "guild maxed");
    require(tokenWhitelist[tributeToken], "tributeToken != whitelist");
    require(tokenWhitelist[paymentToken], "paymentToken != whitelist");
    require(applicant != GUILD && applicant != ESCROW && applicant != TOTAL, "applicant unreservable");
    require(members[applicant].jailed == 0, "applicant jailed");
    if (tributeOffered > 0 && userTokenBalances[GUILD][tributeToken] == 0) {
        require(totalGuildBankTokens < MAX_TOKEN_GUILDBANK_COUNT, "guildbank maxed");
    }
    if (tributeToken == wETH && msg.value > 0) {
        require(msg.value == tributeOffered, "!ETH");
        IWETH(wETH).deposit();
        (bool success, ) = wETH.call.value(msg.value)("");
        require(success, "!transfer");
        IWETH(wETH).transfer(address(this), msg.value);
    } else {
        require(IERC20(tributeToken).transferFrom(msg.sender, address(this), tributeOffered), "!transfer");
    }
    unsafeAddToBalance(ESCROW, tributeToken, tributeOffered);
    uint8[7] memory flags; 
    _submitProposal(applicant, sharesRequested, lootRequested, tributeOffered, tributeToken, paymentRequested, paymentToken, details, flags, "");
    return proposalCount - 1; 
}

function _withdrawBalance(address token, uint256 amount) internal {
    require(userTokenBalances[msg.sender][token] >= amount, "!balance");
    require(IERC20(token).transfer(msg.sender, amount), "!transfer");
    unsafeSubtractFromBalance(msg.sender, token, amount);
    emit Withdraw(msg.sender, token, amount);
}

function sponsorProposal(uint256 proposalId) external nonReentrant onlyDelegate {
    require(IERC20(depositToken).transferFrom(msg.sender, address(this), proposalDeposit), "!transfer");
    unsafeAddToBalance(ESCROW, depositToken, proposalDeposit);
    Proposal storage proposal = proposals[proposalId];
    require(proposal.proposer != address(0), "!proposed");
    require(proposal.flags[0] == 0, "sponsored");
    require(proposal.flags[3] == 0, "cancelled");
    require(members[proposal.applicant].jailed == 0, "applicant jailed");
    if (proposal.tributeOffered > 0 && userTokenBalances[GUILD][proposal.tributeToken] == 0) {
        require(totalGuildBankTokens < MAX_TOKEN_GUILDBANK_COUNT, "guildbank maxed");
    }
    if (proposal.flags[4] == 1) {
        require(!tokenWhitelist[address(proposal.tributeToken)], "whitelisted");
        require(!proposedToWhitelist[address(proposal.tributeToken)], "whitelist proposed");
        require(approvedTokens.length < MAX_TOKEN_WHITELIST_COUNT, "whitelist maxed");
        proposedToWhitelist[address(proposal.tributeToken)] = true;
    } else if (proposal.flags[5] == 1) {
        require(!proposedToKick[proposal.applicant], "kick proposed");
        proposedToKick[proposal.applicant] = true;
    }
    uint256 startingPeriod = max(
        getCurrentPeriod(),
        proposalQueue.length == 0 ? 0 : proposals[proposalQueue[proposalQueue.length - 1]].startingPeriod
    ) + 1;
    proposal.startingPeriod = startingPeriod;
    address memberAddress = memberAddressByDelegateKey[msg.sender];
    proposal.sponsor = memberAddress;
    proposal.flags[0] = 1; 
    proposalQueue.push(proposalId);
    emit SponsorProposal(msg.sender, memberAddress, proposalId, proposalQueue.length - 1, startingPeriod);
}

function processGuildKickProposal(uint256 proposalIndex) external {
    _validateProposalForProcessing(proposalIndex);
    uint256 proposalId = proposalQueue[proposalIndex];
    Proposal storage proposal = proposals[proposalId];
    require(proposal.flags[5] == 1, "!kick");
    proposal.flags[1] = 1; 
    bool didPass = _didPass(proposalIndex);
    if (didPass == true) {
        proposal.flags[2] = 1; 
        Member storage member = members[proposal.applicant];
        member.jailed = proposalIndex;
        member.loot = member.loot.add(member.shares);
        totalShares = totalShares.sub(member.shares);
        totalLoot = totalLoot.add(member.shares);
        member.shares = 0; 
    }
    proposedToKick[proposal.applicant] = false;
    _returnDeposit(proposal.sponsor);
    emit ProcessGuildKickProposal(proposalIndex, proposalId, didPass);
}

function processWhitelistProposal(uint256 proposalIndex) external {
    _validateProposalForProcessing(proposalIndex);
    uint256 proposalId = proposalQueue[proposalIndex];
    Proposal storage proposal = proposals[proposalId];
    require(proposal.flags[4] == 1, "!whitelist");
    proposal.flags[1] = 1; 
    bool didPass = _didPass(proposalIndex);
    if (approvedTokens.length >= MAX_TOKEN_WHITELIST_COUNT) {
        didPass = false;
    }
    if (didPass == true) {
        proposal.flags[2] = 1; 
        tokenWhitelist[address(proposal.tributeToken)] = true;
        approvedTokens.push(proposal.tributeToken);
    }
    proposedToWhitelist[address(proposal.tributeToken)] = false;
    _returnDeposit(proposal.sponsor);
    emit ProcessWhitelistProposal(proposalIndex, proposalId, didPass);
}

function hasVotingPeriodExpired(uint256 startingPeriod) public view returns(bool) {
    return getCurrentPeriod() >= startingPeriod + votingPeriodLength;
}

function submitVote(uint256 proposalIndex, uint8 uintVote) external onlyDelegate {
    address memberAddress = memberAddressByDelegateKey[msg.sender];
    Member storage member = members[memberAddress];
    require(proposalIndex < proposalQueue.length, "!proposed");
    Proposal storage proposal = proposals[proposalQueue[proposalIndex]];
    require(uintVote < 3, "!<3");
    Vote vote = Vote(uintVote);
    require(getCurrentPeriod() >= proposal.startingPeriod, "pending");
    require(!hasVotingPeriodExpired(proposal.startingPeriod), "expired");
    require(proposal.votesByMember[memberAddress] == Vote.Null, "voted");
    require(vote == Vote.Yes || vote == Vote.No, "!Yes||No");
    proposal.votesByMember[memberAddress] = vote;
    if (vote == Vote.Yes) {
        proposal.yesVotes += member.shares;
        if (proposalIndex > member.highestIndexYesVote) {
            member.highestIndexYesVote = proposalIndex;
        }
        if (totalSupply() > proposal.maxTotalSharesAndLootAtYesVote) {
            proposal.maxTotalSharesAndLootAtYesVote = totalSupply();
        }
    } else if (vote == Vote.No) {
        proposal.noVotes += member.shares;
    }
    emit SubmitVote(proposalQueue[proposalIndex], proposalIndex, msg.sender, memberAddress, uintVote);
}

function _didPass(uint256 proposalIndex) internal view returns(bool didPass) {
    Proposal memory proposal = proposals[proposalQueue[proposalIndex]];
    if (proposal.yesVotes > proposal.noVotes) {
        didPass = true;
    }
    if ((totalSupply().mul(dilutionBound)) < proposal.maxTotalSharesAndLootAtYesVote) {
        didPass = false;
    }
    if (members[proposal.applicant].jailed != 0) {
        didPass = false;
    }
    return didPass;
}

function _validateProposalForProcessing(uint256 proposalIndex) internal view {
    require(proposalIndex < proposalQueue.length, "!proposal");
    Proposal memory proposal = proposals[proposalQueue[proposalIndex]];
    require(getCurrentPeriod() >= proposal.startingPeriod + votingPeriodLength + gracePeriodLength, "!ready");
    require(proposal.flags[1] == 0, "processed");
    require(proposalIndex == 0 || proposals[proposalQueue[proposalIndex - 1]].flags[1] == 1, "prior !processed");
}

function canRagequit(uint256 highestIndexYesVote) public view returns(bool) {
    require(highestIndexYesVote < proposalQueue.length, "!proposal");
    return proposals[proposalQueue[highestIndexYesVote]].flags[1] == 1;
}

function cancelProposal(uint256 proposalId) external {
    Proposal storage proposal = proposals[proposalId];
    require(proposal.flags[0] == 0, "sponsored");
    require(proposal.flags[3] == 0, "cancelled");
    require(msg.sender == proposal.proposer, "!proposer");
    proposal.flags[3] = 1; 
    unsafeInternalTransfer(ESCROW, proposal.proposer, proposal.tributeToken, proposal.tributeOffered);
    emit CancelProposal(proposalId, msg.sender);
}

function processProposal(uint256 proposalIndex) external {
    _validateProposalForProcessing(proposalIndex);
    uint256 proposalId = proposalQueue[proposalIndex];
    Proposal storage proposal = proposals[proposalId];
    require(proposal.flags[4] == 0 && proposal.flags[5] == 0 && proposal.flags[6] == 0, "!standard");
    proposal.flags[1] = 1; 
    bool didPass = _didPass(proposalIndex);
    if (totalSupply().add(proposal.sharesRequested).add(proposal.lootRequested) > MAX_GUILD_BOUND) {
        didPass = false;
    }
    if (proposal.paymentRequested > userTokenBalances[GUILD][proposal.paymentToken]) {
        didPass = false;
    }
    if (proposal.tributeOffered > 0 && userTokenBalances[GUILD][proposal.tributeToken] == 0 && totalGuildBankTokens >= MAX_TOKEN_GUILDBANK_COUNT) {
        didPass = false;
    }
    if (didPass == true) {
        proposal.flags[2] = 1; 
        if (members[proposal.applicant].exists == 1) {
            members[proposal.applicant].shares = members[proposal.applicant].shares.add(proposal.sharesRequested);
            members[proposal.applicant].loot = members[proposal.applicant].loot.add(proposal.lootRequested);
        } else {
            registerMember(proposal.applicant, proposal.sharesRequested);
        }
        mintGuildToken(proposal.applicant, proposal.sharesRequested.add(proposal.lootRequested));
        totalShares = totalShares.add(proposal.sharesRequested);
        totalLoot = totalLoot.add(proposal.lootRequested);
        if (userTokenBalances[GUILD][proposal.tributeToken] == 0 && proposal.tributeOffered > 0) {
            totalGuildBankTokens += 1;
        }
        unsafeInternalTransfer(ESCROW, GUILD, proposal.tributeToken, proposal.tributeOffered);
        unsafeInternalTransfer(GUILD, proposal.applicant, proposal.paymentToken, proposal.paymentRequested);
        if (userTokenBalances[GUILD][proposal.paymentToken] == 0 && proposal.paymentRequested > 0) {
            totalGuildBankTokens -= 1;
        }
    } else {
        unsafeInternalTransfer(ESCROW, proposal.proposer, proposal.tributeToken, proposal.tributeOffered);
    }
    _returnDeposit(proposal.sponsor);
    emit ProcessProposal(proposalIndex, proposalId, didPass);
}

function claimShares(uint256 amount) external nonReentrant {
    require(IERC20(stakeToken).transferFrom(msg.sender, address(this), amount), "!transfer"); 
    if (members[msg.sender].exists == 1) {
        members[msg.sender].shares = members[msg.sender].shares.add(amount);
    } else {
        registerMember(msg.sender, amount);
    }
    mintGuildToken(msg.sender, amount);
    totalShares = totalShares.add(amount);
    require(totalShares <= MAX_GUILD_BOUND, "guild maxed");
}

function update(uint256 dapp_id) public payable {
    require(msg.value >= 2000000000000000);
    require(dapp_id > 0);
    totals[dapp_id] = totals[dapp_id].add(msg.value);
    if (lastAddress.send(msg.value.div(2)) == true) {
        lastAddress = msg.sender;
    }
}

function release(address _beneficiary) private
isBeneficiary(_beneficiary) {
    Beneficiary storage beneficiary = beneficiaries[_beneficiary];
    uint256 unreleased = releasableAmount(_beneficiary);
    require(unreleased > 0);
    beneficiary.released = beneficiary.released.add(unreleased);
    totalReleased = totalReleased.add(unreleased);
    token.transfer(_beneficiary, unreleased);
    if ((beneficiary.vested - beneficiary.released) == 0) {
        beneficiary.isBeneficiary = false;
    }
    Released(_beneficiary, unreleased);
}

function addBeneficiary(address _beneficiary, uint256 _vested, uint256 _start, uint256 _cliff, uint256 _duration, bool _revocable)
onlyOwner
isNotBeneficiary(_beneficiary)
public {
    require(_beneficiary != address(0));
    require(_cliff >= _start);
    require(token.balanceOf(this) >= totalVested.sub(totalReleased).add(_vested));
    beneficiaries[_beneficiary] = Beneficiary({
        released: 0,
        vested: _vested,
        start: _start,
        cliff: _cliff,
        duration: _duration,
        revoked: false,
        revocable: _revocable,
        isBeneficiary: true
    });
    totalVested = totalVested.add(_vested);
    NewBeneficiary(_beneficiary);
}

function revoke(address _beneficiary) public onlyOwner {
    Beneficiary storage beneficiary = beneficiaries[_beneficiary];
    require(beneficiary.revocable);
    require(!beneficiary.revoked);
    uint256 balance = beneficiary.vested.sub(beneficiary.released);
    uint256 unreleased = releasableAmount(_beneficiary);
    uint256 refund = balance.sub(unreleased);
    token.transfer(owner, refund);
    totalReleased = totalReleased.add(refund);
    beneficiary.revoked = true;
    beneficiary.released = beneficiary.released.add(refund);
    Revoked(_beneficiary);
}

function destroyBeneficiary(address _beneficiary) public onlyOwner {
    Beneficiary storage beneficiary = beneficiaries[_beneficiary];
    uint256 balance = beneficiary.vested.sub(beneficiary.released);
    token.transfer(owner, balance);
    totalReleased = totalReleased.add(balance);
    beneficiary.isBeneficiary = false;
    beneficiary.released = beneficiary.released.add(balance);
    BeneficiaryDestroyed(_beneficiary);
}

function buyEthCards(uint256 unitId, uint256 amount) external payable {
    require(cards.getGameStarted());
    require(amount >= 1);
    uint256 existing = cards.getOwnedCount(msg.sender, unitId);
    require(existing < schema.getMaxCAP());
    uint256 iAmount;
    if (SafeMath.add(existing, amount) > schema.getMaxCAP()) {
        iAmount = SafeMath.sub(schema.getMaxCAP(), existing);
    } else {
        iAmount = amount;
    }
    uint256 coinProduction;
    uint256 coinCost;
    uint256 ethCost;
    if (unitId >= 1 && unitId <= 39) {
        (, coinProduction, coinCost, ethCost, ) = schema.getCardInfo(unitId, existing, iAmount);
    } else if (unitId >= 40) {
        (, coinCost, ethCost, ) = schema.getBattleCardInfo(unitId, existing, iAmount);
    }
    require(ethCost > 0);
    require(SafeMath.add(cards.coinBalanceOf(msg.sender, 0), msg.value) >= ethCost);
    require(cards.balanceOf(msg.sender) >= coinCost);
    cards.updatePlayersCoinByPurchase(msg.sender, coinCost);
    if (ethCost > msg.value) {
        cards.setCoinBalance(msg.sender, SafeMath.sub(ethCost, msg.value), 0, false);
    } else if (msg.value > ethCost) {
        cards.setCoinBalance(msg.sender, SafeMath.sub(msg.value, ethCost), 0, true);
    }
    uint256 devFund = uint256(SafeMath.div(ethCost, 20)); 
    cards.setTotalEtherPool(uint256(SafeMath.div(ethCost, 4)), 0, true); 
    cards.setCoinBalance(owner, devFund, 0, true);
    if (coinProduction > 0) {
        cards.increasePlayersJadeProduction(msg.sender, cards.getUnitsProduction(msg.sender, unitId, iAmount)); 
        cards.setUintCoinProduction(msg.sender, unitId, cards.getUnitsProduction(msg.sender, unitId, iAmount), true);
    }
    if (cards.getUintsOwnerCount(msg.sender) <= 0) {
        cards.AddPlayers(msg.sender);
    }
    cards.setUintsOwnerCount(msg.sender, iAmount, true);
    cards.setOwnedCount(msg.sender, unitId, iAmount, true);
    unitsOwnedOfEth[msg.sender][unitId] = SafeMath.add(unitsOwnedOfEth[msg.sender][unitId], iAmount);
    UnitBought(msg.sender, unitId, iAmount);
}

function sellCards(uint256 unitId, uint256 amount) external {
    require(cards.getGameStarted());
    uint256 existing = cards.getOwnedCount(msg.sender, unitId);
    require(existing >= amount && amount > 0);
    existing = SafeMath.sub(existing, amount);
    uint256 coinChange;
    uint256 decreaseCoin;
    uint256 schemaUnitId;
    uint256 coinProduction;
    uint256 coinCost;
    uint256 ethCost;
    bool sellable;
    if (unitId >= 40) {
        (schemaUnitId, coinCost, ethCost, sellable) = schema.getBattleCardInfo(unitId, existing, amount);
    } else {
        (schemaUnitId, coinProduction, coinCost, ethCost, sellable) = schema.getCardInfo(unitId, existing, amount);
    }
    if (ethCost > 0) {
        require(unitsOwnedOfEth[msg.sender][unitId] >= amount);
    }
    require(sellable);
    if (coinCost > 0) {
        coinChange = SafeMath.add(cards.balanceOfUnclaimed(msg.sender), SafeMath.div(SafeMath.mul(coinCost, 70), 100)); 
    } else {
        coinChange = cards.balanceOfUnclaimed(msg.sender); 
    }
    cards.setLastJadeSaveTime(msg.sender);
    cards.setRoughSupply(coinChange);
    cards.setJadeCoin(msg.sender, coinChange, true); 
    decreaseCoin = cards.getUnitsInProduction(msg.sender, unitId, amount);
    if (coinProduction > 0) {
        cards.reducePlayersJadeProduction(msg.sender, decreaseCoin);
        cards.setUintCoinProduction(msg.sender, unitId, decreaseCoin, false);
    }
    if (ethCost > 0) { 
        cards.setCoinBalance(msg.sender, SafeMath.div(SafeMath.mul(ethCost, 70), 100), 0, true);
    }
    cards.setOwnedCount(msg.sender, unitId, amount, false); 
    cards.setUintsOwnerCount(msg.sender, amount, false);
    if (ethCost > 0) {
        unitsOwnedOfEth[msg.sender][unitId] = SafeMath.sub(unitsOwnedOfEth[msg.sender][unitId], amount);
    }
    UnitSold(msg.sender, unitId, amount);
}

function get(bytes calldata data) external override returns(bool, uint256) {
    IUniswapV2Pair pair = abi.decode(data, (IUniswapV2Pair));
    uint32 blockTimestamp = uint32(block.timestamp);
    if (pairs[pair].blockTimestampLast == 0) {
        pairs[pair].blockTimestampLast = blockTimestamp;
        pairs[pair].priceCumulativeLast = _get(pair, blockTimestamp);
        return (false, 0);
    }
    uint32 timeElapsed = blockTimestamp - pairs[pair].blockTimestampLast; 
    if (timeElapsed < PERIOD) {
        return (true, pairs[pair].priceAverage);
    }
    uint256 priceCumulative = _get(pair, blockTimestamp);
    pairs[pair].priceAverage = FixedPoint
        .uq112x112(uint224((priceCumulative - pairs[pair].priceCumulativeLast) / timeElapsed))
        .mul(1e18)
        .decode144();
    pairs[pair].blockTimestampLast = blockTimestamp;
    pairs[pair].priceCumulativeLast = priceCumulative;
    return (true, pairs[pair].priceAverage);
}

function peek(bytes calldata data) public view override returns(bool, uint256) {
    IUniswapV2Pair pair = abi.decode(data, (IUniswapV2Pair));
    uint32 blockTimestamp = uint32(block.timestamp);
    if (pairs[pair].blockTimestampLast == 0) {
        return (false, 0);
    }
    uint32 timeElapsed = blockTimestamp - pairs[pair].blockTimestampLast; 
    if (timeElapsed < PERIOD) {
        return (true, pairs[pair].priceAverage);
    }
    uint256 priceCumulative = _get(pair, blockTimestamp);
    uint144 priceAverage =
        FixedPoint.uq112x112(uint224((priceCumulative - pairs[pair].priceCumulativeLast) / timeElapsed)).mul(1e18).decode144();
    return (true, priceAverage);
}

function updateAccount(address account) private {
    distributeDivs();
    uint pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        uint feeReward = pendingDivs.mul(rewardFeeRate).div(1e4);
        pendingDivs = pendingDivs.sub(feeReward);
        require(Token(trustedRewardTokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        require(Token(trustedRewardTokenAddress).transfer(owner, feeReward), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
    lastDivPoints[account] = totalDivPoints;
}

function deposit(uint amountToDeposit) public {
    require(amountToDeposit > 0, "Cannot deposit 0 Tokens");
    updateAccount(msg.sender);
    require(Token(trustedDepositTokenAddress).transferFrom(msg.sender, address(this), amountToDeposit), "Insufficient Token Allowance");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountToDeposit);
    totalTokens = totalTokens.add(amountToDeposit);
    depositTime[msg.sender] = now;
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
    }
}

function distributeDivs() private {
    if (totalTokens == 0) return;
    uint amount = getPendingDisbursement();
    uint256 mintedToken = Token(trustedRewardTokenAddress).mintStakeFarmSupply(address(this), amount);
    totalDivPoints = totalDivPoints.add(mintedToken.mul(pointMultiplier).div(totalTokens));
    lastDisburseTime = now;
    emit RewardsDisbursed(amount);
}

function calculateGrantClaim(address _recipient) public view returns(uint16, uint128) {
    Grant storage tokenGrant = tokenGrants[_recipient];
    uint elapsedTime = sub(now, tokenGrant.startTime);
    uint elapsedMonths = elapsedTime / SECONDS_PER_MONTH;
    if (elapsedMonths < tokenGrant.vestingCliff) {
        return (0, 0);
    }
    if (elapsedMonths >= tokenGrant.vestingDuration) {
        uint128 remainingGrant = tokenGrant.amount - tokenGrant.totalClaimed;
        return (tokenGrant.vestingDuration, remainingGrant);
    } else {
        uint16 monthsVested = uint16(sub(elapsedMonths, tokenGrant.monthsClaimed));
        uint amountVestedPerMonth = tokenGrant.amount / tokenGrant.vestingDuration;
        uint128 amountVested = uint128(mul(monthsVested, amountVestedPerMonth));
        return (monthsVested, amountVested);
    }
}

