    teamContract = candidateContract;
}

function bid() public payable returns(uint256, uint256, uint256) {
    require(msg.sender == tx.origin);
    require(msg.value == 0.01 ether);
    checkRoundEnd();
    devFee = devFee + (msg.value / 100);
    uint256 toAdd = msg.value - (msg.value / 100);
    hourPot = hourPot + (toAdd / 3);
    dayPot = dayPot + (toAdd / 3);
    weekPot = weekPot + (toAdd - ((toAdd / 3) + (toAdd / 3)));
    seed = uint256(keccak256(blockhash(block.number - 1), seed, now));
    uint256 seed1 = seed;
    if (seed > hourPotHighscore) {
        hourPotLeader = msg.sender;
        hourPotExpiration = now + 1 hours;
        hourPotHighscore = seed;
    }
    seed = uint256(keccak256(blockhash(block.number - 1), seed, now));
    uint256 seed2 = seed;
    if (seed > dayPotHighscore) {
        dayPotLeader = msg.sender;
        dayPotExpiration = now + 1 days;
        dayPotHighscore = seed;
    }
    seed = uint256(keccak256(blockhash(block.number - 1), seed, now));
    uint256 seed3 = seed;
    if (seed > weekPotHighscore) {
        weekPotLeader = msg.sender;
        weekPotExpiration = now + 1 weeks;
        weekPotHighscore = seed;
    }
    totalBids++;
    playerLastScores[msg.sender] = threeUints(seed1, seed2, seed3);
    return (seed1, seed2, seed3);
}

function checkRoundEnd() internal {
    if (now > hourPotExpiration) {
        uint256 hourToSend = hourPot / 2;
        hourPot = hourPot - hourToSend;
        hourPotLeader.send(hourToSend);
        hourPotLeader = msg.sender;
        hourPotHighscore = 0;
        hourPotExpiration = now + 1 hours;
    }
    if (now > dayPotExpiration) {
        uint256 dayToSend = dayPot / 2;
        dayPot = dayPot - dayToSend;
        dayPotLeader.send(dayToSend);
        dayPotLeader = msg.sender;
        dayPotHighscore = 0;
        dayPotExpiration = now + 1 days;
    }
    if (now > weekPotExpiration) {
        uint256 weekToSend = weekPot / 2;
        weekPot = weekPot - weekToSend;
        weekPotLeader.send(weekToSend);
        weekPotLeader = msg.sender;
        weekPotHighscore = 0;
        weekPotExpiration = now + 1 weeks;
    }
}

function withdraw(uint amount) payable onlyOwner {
    if (now >= openDate) {
        uint max = deposits[msg.sender];
        if (amount <= max && max > 0) {
            msg.sender.send(amount);
            Withdrawal(msg.sender, amount);
        }
    }
}

function refund(uint _instId, address _whoToRefund) public onlyInstanceOwner(_instId) instanceExists(_instId) whenNotPaused returns(bool) {
    SecurityInstance storage curInst = instances[_instId];
    if (curInst.depositorState[_whoToRefund] != DepositorState.Active) {
        return false;
    }
    curInst.depositorState[_whoToRefund] = DepositorState.Refunded;
    _whoToRefund.transfer(curInst.depositAmount);
    RefundSent(_instId, _whoToRefund, curInst.depositAmount);
    return true;
}

function claim(uint _instId, address _whoToClaim) public onlyInstanceOwner(_instId) instanceExists(_instId) whenNotPaused returns(bool) {
    SecurityInstance storage curInst = instances[_instId];
    if (curInst.depositorState[_whoToClaim] != DepositorState.Active) {
        return false;
    }
    curInst.depositorState[_whoToClaim] = DepositorState.Claimed;
    curInst.instOwner.transfer(curInst.depositAmount);
    DepositClaimed(_instId, _whoToClaim, curInst.depositAmount);
    return true;
}

function createNewSecurityDeposit(string _ownerNote, string _depositPurpose, uint _depositAmount) external blockCatEntryPoint whenNotPaused returns(uint currentId) {
    require(_depositAmount <= ethPerTransactionLimit);
    require(_depositAmount > 0);
    currentId = instanceId;
    address instanceOwner = msg.sender;
    uint depositAmountETH = _depositAmount;
    SecurityInstance storage curInst = instances[currentId];
    curInst.instId = currentId;
    curInst.instOwner = instanceOwner;
    curInst.ownerNote = _ownerNote;
    curInst.depositPurpose = _depositPurpose;
    curInst.depositAmount = depositAmountETH;
    SecurityDepositCreated(currentId, instanceOwner, _ownerNote, _depositPurpose, depositAmountETH);
    instanceId++;
}

function() public payable {
    require(!_isContract(msg.sender));
    require(!auctionExpired());
    uint256 requiredBid = nextBid();
    require(msg.value >= requiredBid);
    uint256 change = msg.value.sub(requiredBid);
    uint256 difference = requiredBid.sub(highestBid);
    uint256 reward = difference / 4;
    if (highestBidder != 0x0) {
        highestBidder.transfer(highestBid.add(reward));
    }
    if (change > 0) {
        msg.sender.transfer(change);
    }
    highestBidder = msg.sender;
    highestBid = requiredBid;
    emit Bid(msg.sender, requiredBid);
}

function getAuctionCost(
    bytes32 positionId,
    uint256 totalHeldToken
)
public
view
returns(uint256) {
    (
        uint256 auctionStartTimestamp,
        uint256 auctionEndTimestamp
    ) = getAuctionTimeLimits(positionId);
    require(
        block.timestamp >= auctionStartTimestamp,
        "DutchAuctionCloser#getAuctionTimeLimits: Auction has not started"
    );
    if (block.timestamp >= auctionEndTimestamp) {
        return 0;
    }
    return MathHelpers.getPartialAmount(
        auctionEndTimestamp.sub(block.timestamp),
        auctionEndTimestamp.sub(auctionStartTimestamp),
        totalHeldToken
    );
}

function buyDepo(address _depo) public payable {
    require(isSale[_depo] == true, "So sorry, but this deposit is not for sale.");
    require(forSale[_depo] == msg.value, "Summ for buying deposit is incorrect.");
    address seller = _depo;
    uint256 amount = invested[_depo] * 4 / 100 * (block.number - atBlock[_depo]) / 5900;
    invested[_depo] += amount;
    if (invested[msg.sender] > 0) {
        amount = invested[msg.sender] * 4 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        invested[msg.sender] += amount;
    }
    invested[msg.sender] += invested[_depo];
    atBlock[msg.sender] = block.number;
    invested[_depo] = 0;
    atBlock[_depo] = block.number;
    isSale[_depo] = false;
    seller.transfer(msg.value * 9 / 10); 
    emit Deals(_depo, msg.sender, msg.value);
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 4 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        address sender = msg.sender;
        sender.transfer(amount);
        emit Profit(sender, amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(GEX).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function STAKE(uint256 tokens) external {
    require(IERC20(GEX).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(GEX).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(GEX).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

