    if (now > endTimestamp)
        return true;
    return false;
}

constructor() public {
    require(startTimestamp >= now);
    require(endTimestamp >= startTimestamp);
}

function buyTokens(address beneficiary) public payable validPurchase {
    require(beneficiary != 0x0);
    uint256 weiAmount = msg.value;
    uint256 weiRaisedSoFar = weiRaised.add(weiAmount);
    require(weiRaisedSoFar + weiRaisedInPresale <= hardcap);
    if (deposits[msg.sender] == 0) {
        numberOfPurchasers++;
    }
    deposits[msg.sender] = weiAmount.add(deposits[msg.sender]);
    uint256 daysInSale = (now - startTimestamp) / (1 days);
    uint256 thisBonus = 0;
    if (daysInSale < 29) {
        thisBonus = bonus[daysInSale];
    }
    uint256 tokens = weiAmount.mul(rate);
    uint256 extraBonus = tokens.mul(thisBonus);
    extraBonus = extraBonus.div(100);
    tokens = tokens.add(extraBonus);
    uint256 finalTokenCount;
    finalTokenCount = tokens.add(tokensSold);
    weiRaised = weiRaisedSoFar;
    tokensSold = finalTokenCount;
    token.mint(beneficiary, tokens);
    hardwareWallet.transfer(msg.value);
    emit TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
}

function finishMinting() public onlyOwner returns(bool) {
    require(hasEnded());
    uint issuedTokenSupply = token.totalSupply();
    uint publicTokens = issuedTokenSupply - advisorTokensGranted;
    if (publicTokens > 60 * advisorTokensGranted / 40) {
        uint restrictedTokens = (publicTokens) * 40 / 60 - advisorTokensGranted;
        token.mint(restrictedWallet, restrictedTokens);
        advisorTokensGranted = advisorTokensGranted + restrictedTokens;
    } else if (publicTokens < 60 * advisorTokensGranted / 40) {
        uint256 deltaCommonPool = advisorTokensGranted * 60 / 40 - publicTokens;
        token.mint(additionalTokensFromCommonPoolWallet, deltaCommonPool);
    }
    token.finishMinting();
    token.transferOwnership(owner);
    emit MainSaleClosed();
    return true;
}

function createBid(uint256 tokenId) external payable notPaused nonReentrant {
    require(auctions[tokenId].exists, "Auction doesn't exist");
    require(!auctions[tokenId].paused, "Auction paused");
    require(
        msg.value >= auctions[tokenId].reservePrice,
        "Must send reservePrice or more"
    );
    require(
        auctions[tokenId].firstBidTime == 0 ||
        block.timestamp <
        auctions[tokenId].firstBidTime + auctions[tokenId].duration,
        "Auction expired"
    );
    uint256 lastValue = auctions[tokenId].amount;
    bool firstBid;
    address payable lastBidder;
    if (lastValue != 0) {
        require(msg.value > lastValue, "Must send more than last bid");
        require(
            msg.value.sub(lastValue) >= minBid,
            "Must send more than last bid by minBid Amount"
        );
        lastBidder = auctions[tokenId].bidder;
    } else {
        firstBid = true;
        auctions[tokenId].firstBidTime = block.timestamp;
    }
    auctions[tokenId].amount = msg.value;
    auctions[tokenId].bidder = msg.sender;
    bool extended;
    if (
        (auctions[tokenId].firstBidTime.add(auctions[tokenId].duration))
        .sub(block.timestamp) < timeBuffer
    ) {
        auctions[tokenId].duration = block.timestamp.sub(auctions[tokenId].firstBidTime).add(timeBuffer);
        extended = true;
    }
    emit AuctionBid(
        tokenId,
        nftAddress,
        msg.sender,
        msg.value,
        block.timestamp,
        firstBid,
        extended
    );
    if (!firstBid) {
        if (!lastBidder.send(lastValue)) {
            auctions[tokenId].admin.transfer(lastValue);
        }
    }
}

function endAuction(uint256 tokenId) external notPaused nonReentrant {
    require(auctions[tokenId].exists, "Auction doesn't exist");
    require(!auctions[tokenId].paused, "Auction paused");
    require(
        uint256(auctions[tokenId].firstBidTime) != 0,
        "Auction hasn't begun"
    );
    require(
        block.timestamp >=
        auctions[tokenId].firstBidTime + auctions[tokenId].duration,
        "Auction hasn't completed"
    );
    address winner = auctions[tokenId].bidder;
    uint256 amount = auctions[tokenId].amount;
    address creator = auctions[tokenId].creator;
    uint256 adminSplit = auctions[tokenId].adminSplit;
    address payable admin = auctions[tokenId].admin;
    address payable proceedsRecipient = auctions[tokenId].proceedsRecipient;
    emit AuctionEnded(tokenId, nftAddress, creator, winner, amount);
    delete auctions[tokenId];
    IERC721(nftAddress).transferFrom(address(this), winner, tokenId);
    uint256 adminReceives = amount.mul(adminSplit).div(100);
    uint256 proceedsAmount = amount.sub(adminReceives);
    if (adminReceives > 0) {
        admin.transfer(adminReceives);
    }
    proceedsRecipient.transfer(proceedsAmount);
}

function deposit(uint256 pid, uint256 amount) external {
    require(pid < poolInfo.length, "Pool does not exist");
    uint256 rewardAmount = getRewardAmount(
        poolInfo[pid].stakeToken,
        amount,
        poolInfo[pid].rewardRate
    );
    require(
        rewardAmount <= getRemainingRewards(),
        "Not enough rewards remaining"
    );
    require(
        IERC20(poolInfo[pid].stakeToken).transferFrom(
            msg.sender,
            address(this),
            amount
        )
    );
    PoolInfo storage pool = poolInfo[pid];
    stakeAmount[pool.stakeToken] = stakeAmount[pool.stakeToken].add(amount);
    stakeInfo[msg.sender].push(
        StakeInfo({
            stakeToken: pool.stakeToken,
            amount: amount,
            rewardAmount: rewardAmount,
            endTime: block.timestamp.add(pool.lockupDuration)
        })
    );
    totalRewardAmount = totalRewardAmount.add(rewardAmount);
    emit Deposit(msg.sender, pool.stakeToken, amount);
}

function withdraw(uint256 stakeId) external {
    require(
        stakeId < stakeInfo[msg.sender].length,
        "Stake info does not exist"
    );
    StakeInfo storage info = stakeInfo[msg.sender][stakeId];
    require(
        IERC20(info.stakeToken).transfer(msg.sender, info.amount),
        "Withdrawl failed"
    );
    emit Withdraw(msg.sender, info.stakeToken, info.amount);
    stakeAmount[info.stakeToken] = stakeAmount[info.stakeToken].sub(
        info.amount
    );
    if (info.endTime < block.timestamp) {
        if (
            info.rewardAmount.add(stakeAmount[rewardToken]) <=
            IERC20(rewardToken).balanceOf(address(this))
        ) {
            require(
                IERC20(rewardToken).transfer(msg.sender, info.rewardAmount),
                "Claim failed"
            );
            totalRewardAmount = totalRewardAmount.sub(info.rewardAmount);
            emit Claim(msg.sender, rewardToken, info.rewardAmount);
        }
    }
    stakeInfo[msg.sender][stakeId] = stakeInfo[msg.sender][
        stakeInfo[msg.sender].length - 1
    ];
    stakeInfo[msg.sender].pop();
}

