}

function solveTask(uint _taskId, uint256 _answerPrivateKey, uint256 publicXPoint, uint256 publicYPoint) public isLastestVersion {
    uint taskIndex = safeIndexOfTaskId(_taskId);
    Task storage task = tasks[taskIndex];
    require(task.answerPrivateKey == 0, "solveTask: task is already solved");
    require(_answerPrivateKey >> 128 == uint256(msg.sender) >> 32, "solveTask: this solution does not match miner address");
    if (task.taskType == TaskType.BITCOIN_ADDRESS_PREFIX) {
        require(ec.publicKeyVerify(_answerPrivateKey, publicXPoint, publicYPoint));
        (publicXPoint, publicYPoint) = ec.ecadd(
            task.requestPublicXPoint,
            task.requestPublicYPoint,
            publicXPoint,
            publicYPoint
        );
        require(isValidPublicKey(publicXPoint, publicYPoint));
        bytes32 btcAddress = createBtcAddress(publicXPoint, publicYPoint);
        uint prefixLength = lengthOfCommonPrefix(btcAddress, task.data);
        require(prefixLength == task.dataLength);
        task.answerPrivateKey = _answerPrivateKey;
    } else {
        revert();
    }
    uint256 minerReward = task.reward.mul(MAX_PERCENT - serviceFee).div(MAX_PERCENT); 
    uint256 referrerReward = task.reward.mul(serviceFee).mul(referrerFee).div(MAX_PERCENT).div(MAX_PERCENT); 
    msg.sender.transfer(minerReward);
    task.referrer.transfer(referrerReward);
    totalReward = totalReward.sub(task.reward.sub(minerReward.add(referrerReward)));
    _completeTask(_taskId, taskIndex);
    emit TaskSolved(_taskId, minerReward);
}

function updateUniswapV2Router(address newAddress) public onlyOwner {
    require(newAddress != address(uniswapV2Router), "NUTRA: The router already has that address");
    emit UpdateUniswapV2Router(newAddress, address(uniswapV2Router));
    uniswapV2Router = IUniswapV2Router02(newAddress);
    address _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory())
        .createPair(address(this), uniswapV2Router.WETH());
    uniswapV2Pair = _uniswapV2Pair;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!_blacklisted[to] && !_blacklisted[from], "address is blacklisted");
    if (!_whitelisted[from]) {
        require(tradingEnabled, "Trading is not enabled yet");
    }
    if (
        from != owner() &&
        to != owner() &&
        to != address(0) &&
        to != address(0xdead) &&
        to != uniswapV2Pair
    ) {
        uint256 contractBalanceRecepient = balanceOf(to);
        if (!_isExcludedFromMaxWallet[to])
            require(
                contractBalanceRecepient + amount <= maxWalletToken,
                "Exceeds maximum wallet token amount."
            );
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if ((!_isExcludedFromFees[from]) && (!_isExcludedFromFees[to])) {
        if ((!_isExcludedFromMaxTx[from]) && (!_isExcludedFromMaxTx[from])) {
            require(amount <= maxTransactionAmount, "transfer amount exceeds the maxSellTransactionAmount.");
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (canSwap &&
        !swapping &&
        from != address(uniswapV2Pair) &&
        from != owner() &&
        to != owner()
    )
    {
        swapping = true;
        uint256 walletTokens = contractTokenBalance.mul(_SellMarketingFee.add(_SellDevFee)).div(_SellTotalFees);
        uint256 contractBalance = address(this).balance;
        swapTokensForEth(walletTokens);
        uint256 newBalance = address(this).balance.sub(contractBalance);
        uint256 marketingShare = newBalance.mul(_SellMarketingFee).div(_SellDevFee.add(_SellMarketingFee));
        uint256 developmentShare = newBalance.sub(marketingShare);
        payable(_marketingWalletAddress).transfer(marketingShare);
        payable(_developmentWalletAddress).transfer(developmentShare);
        uint256 swapTokens = contractTokenBalance.mul(_SellLiquidityFee).div(_SellTotalFees);
        swapAndLiquify(swapTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (!automatedMarketMakerPairs[to] && !automatedMarketMakerPairs[from]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(_BuyTotalFees).div(100);
        if (automatedMarketMakerPairs[to]) {
            fees += amount.mul(extraFeeOnSell()).div(100);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    try dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {
        emit log("failed");
    }
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {
        emit log("failed");
    }
    if (!swapping) {
        uint256 gas = gasForProcessing;
        try dividendTracker.process(gas) returns(uint256 iterations, uint256 claims, uint256 lastProcessedIndex) {
            emit ProcessedDividendTracker(iterations, claims, lastProcessedIndex, true, gas, tx.origin);
        }
        catch {
            emit log("failed");
        }
    }
}

function updateDividendTracker(address newAddress) public onlyOwner {
    require(newAddress != address(dividendTracker), "NUTRA: The dividend tracker already has that address");
    NUTRADividendTracker newDividendTracker = NUTRADividendTracker(payable(newAddress));
    require(newDividendTracker.owner() == address(this), "NUTRA: The new dividend tracker must be owned by the EFT token contract");
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(owner());
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    dividendTracker.excludeFromDividends(_marketingWalletAddress);
    dividendTracker.excludeFromDividends(_developmentWalletAddress);
    dividendTracker.excludeFromDividends(deadWallet);
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function MyTotalRewards(address user) external view returns(uint256 poolreward) {
    if (stakers[user].stakedAmount > 0) {
        uint256 timeToday = block.timestamp - creationTimeContract;
        uint256 timeT = timeToday.div(86400);
        if (timeT > 59) {
            return 0;
        } else {
            uint256 staked = SafeMath.mul(50000000000000000000, (stakers[user].stakedAmount)).div(TotalStakedETH);
            return staked;
        }
    } else
        return 0;
}

function rewardController(address _investor, bytes5 _type) internal view returns(uint256) {
    uint256 _period;
    uint256 _balance;
    uint256 _created;
    invest storage inv = investInfo[msg.sender][_type];
    _period = countPeriod(_investor, _type);
    _balance = inv.balance;
    _created = inv.created;
    uint256 full_steps;
    uint256 last_step;
    uint256 _d;
    if (_type == _td) _d = 365;
    if (_type == _tw) _d = 54;
    if (_type == _tm) _d = 12;
    if (_type == _ty) _d = 1;
    full_steps = _period / _d;
    last_step = _period - (full_steps * _d);
    for (uint256 i = 0; i < full_steps; i++) { 
        _balance = compaundIntrest(_d, _type, _balance, _created);
        _created += 1 years;
    }
    if (last_step > 0) _balance = compaundIntrest(last_step, _type, _balance, _created);
    return _balance;
}

function compaundIntrest(uint256 _period, bytes5 _type, uint256 _balance, uint256 _created) internal view returns(uint256) {
    uint256 full_steps;
    uint256 last_step;
    uint256 _d = 100; 
    uint256 _bonus = bonusSystem(_type, _created);
    if (_period > _d) {
        full_steps = _period / _d;
        last_step = _period - (full_steps * _d);
        for (uint256 i = 0; i < full_steps; i++) {
            _balance = loopFor(_d, _balance, _bonus);
        }
        if (last_step > 0) _balance = loopFor(last_step, _balance, _bonus);
    } else
    if (_period <= _d) {
        _balance = loopFor(_period, _balance, _bonus);
    }
    return _balance;
}

function closeInvest(bytes5 _interval) internal {
    uint256 _intrest;
    address _to = msg.sender;
    uint256 _period = countPeriod(_to, _interval);
    invest storage inv = investInfo[_to][_interval];
    uint256 _value = inv.balance;
    if (_period == 0) {
        balances[this] -= _value;
        balances[_to] += _value;
        emit Transfer(this, _to, _value); 
        emit InvestClosed(_to, _value);
    } else
    if (_period > 0) {
        balances[this] -= _value;
        totalSupply -= _value;
        emit Transfer(this, 0x0, _value);
        emit Destruction(_value);
        _intrest = rewardController(_to, _interval);
        if (manager[msg.sender]) {
            _intrest = mulsm(divsm(_intrest, 100), 105); 
        }
        issue(_to, _intrest); 
        emit InvestClosed(_to, _intrest);
    }
    inv.exists = false; 
    inv.balance = 0;
    inv.closed = now;
}

function countPeriod(address _investor, bytes5 _t) internal view returns(uint256) {
    uint256 _period;
    uint256 _now = now; 
    if (_t == _td) _period = 1 * _day;
    if (_t == _tw) _period = 7 * _day;
    if (_t == _tm) _period = 31 * _day;
    if (_t == _ty) _period = 365 * _day;
    invest storage inv = investInfo[_investor][_t];
    if (_now - inv.created < _period) return 0;
    return (_now - inv.created) / _period; 
}

