constructor(
    uint256 _endTime,
    uint256 _rate,
    address _wallet,
    uint256 _tokenCap,
    uint256 _minimumContribution,
    address _token,
    address _contributions,
    uint256[] _bonusRanges,
    uint256[] _bonusValues
) public {
    require(_endTime >= block.timestamp);
    require(_rate > 0);
    require(_wallet != address(0));
    require(_tokenCap > 0);
    require(_token != address(0));
    require(_contributions != address(0));
    require(_bonusRanges.length == _bonusValues.length);
    for (uint256 i = 0; i < (_bonusValues.length - 1); i++) {
        require(_bonusValues[i] > _bonusValues[i + 1]);
        require(_bonusRanges[i] > _bonusRanges[i + 1]);
    }
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
    tokenCap = _tokenCap;
    token = _token;
    minimumContribution = _minimumContribution;
    contributions = _contributions;
    bonusRanges = _bonusRanges;
    bonusValues = _bonusValues;
}

function ended() public view returns(bool) {
    return hasClosed() || tokenCapReached();
}

function started() public view returns(bool) {
    return block.timestamp >= openingTime;
}

function yearFor(uint timestamp) public constant returns(uint) {
    return timestamp < rewardStartTime ?
        0 :
        sub(timestamp, rewardStartTime) / (365 days);
}

function KeyRewardPool(uint _rewardStartTime, address _key, address _withdrawer) public {
    require(_rewardStartTime != 0);
    require(_key != address(0));
    require(_withdrawer != address(0));
    uint _time = time();
    require(_rewardStartTime > _time - 364 days);
    rewardStartTime = _rewardStartTime;
    key = DSToken(_key);
    withdrawer = _withdrawer;
    owner = msg.sender;
    paused = false;
}

function collectToken() public notPaused onlyWithdrawer {
    uint _time = time();
    require(_time > rewardStartTime);
    var _key = key; 
    uint balance = _key.balanceOf(address(this));
    uint total = add(collectedTokens, balance);
    uint remainingTokens = total;
    uint yearCount = yearFor(_time);
    for (uint i = 0; i < yearCount; i++) {
        remainingTokens = div(mul(remainingTokens, 100 - yearlyRewardPercentage), 100);
    }
    totalRewardThisYear = div(mul(remainingTokens, yearlyRewardPercentage), 100);
    uint canExtractThisYear = div(mul(totalRewardThisYear, (_time - rewardStartTime) % 365 days), 365 days);
    uint canExtract = canExtractThisYear + (total - remainingTokens);
    canExtract = sub(canExtract, collectedTokens);
    if (canExtract > balance) {
        canExtract = balance;
    }
    collectedTokens = add(collectedTokens, canExtract);
    assert(_key.transfer(withdrawer, canExtract)); 
    TokensWithdrawn(withdrawer, canExtract);
}

function release() public {
    require(block.timestamp >= _releaseTime + (stepTime * releaseCount), 'before release time');
    uint thisBalance = _token.balanceOf(address(this));
    require(thisBalance > 0, 'release done');
    uint currRlease = releaseQty;
    if (thisBalance < releaseQty) {
        currRlease = thisBalance;
    }
    uint amount1 = (currRlease * 80) / 100;
    uint amount2 = (currRlease * 20) / 100;
    _token.transfer(_beneficiary_m, amount1);
    _token.transfer(_beneficiary_s, amount2);
    releaseCount++;
}

constructor(IERC20 token, address beneficiary_m, address beneficiary_s, uint256 releaseTime) public {
    require(releaseTime > block.timestamp, 'release time is before');
    _token = token;
    _beneficiary_m = beneficiary_m;
    _beneficiary_s = beneficiary_s;
    _releaseTime = releaseTime;
}

function buyTokens(address _beneficiary) public payable {
    require(now >= startICO);
    require(msg.value <= maxEther);
    require(allTokenICO <= maxTokens);
    uint256 weiAmount = msg.value;
    _preValidatePurchase(_beneficiary, weiAmount);
    uint256 tokens = _getTokenAmount(weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    _processPurchase(_beneficiary, tokens);
    allTokenICO = allTokenICO.add(tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        weiAmount,
        tokens
    );
    _forwardFunds();
}

function _updateStage(uint256 weiAmount, uint256 callAmount) internal {
    uint256 _duration = stages_duration[uint256(stage)];
    uint256 call_tokens = 0;
    if (weiAmount != 0) {
        call_tokens = getAmountForCurrentStage(weiAmount);
    } else {
        call_tokens = callAmount;
    }
    uint256 callg_tokens = call_tokens.mul(200);
    (uint256 _hardcapCall, uint256 _hardcapCallg) = getHardCap();
    if (stageStartTime.add(_duration) <= block.timestamp || callDistributed.add(call_tokens) >= _hardcapCall || callgDistributed.add(callg_tokens) >= _hardcapCallg) {
        stages next_stage = _getNextStage();
        emit StageChanged(stage, next_stage, stageStartTime);
        stage = next_stage;
        if (next_stage != stages.FINALIZED) {
            stageStartTime = block.timestamp;
        } else {
            finalization();
        }
    }
}

function transferTokens(address _to, uint256 _amount) public onlyOwner {
    require(!is_finalized);
    require(_to != address(0));
    require(_amount > 0);
    _updateStage(0, _amount);
    callDistributed = callDistributed.add(_amount);
    callgDistributed = callgDistributed.add(_amount.mul(200));
    if (stage == stages.FINALIZED) {
        (uint256 _hardcapCall, uint256 _hardcapCallg) = getHardCap();
        require(callDistributed.add(callDistributed) <= _hardcapCall);
        require(callgDistributed.add(callgDistributed) <= _hardcapCallg);
    }
    MintableToken(token_call).mint(_to, _amount);
    MintableToken(token_callg).mint(_to, _amount.mul(200));
    userHistory[_to] = userHistory[_to].add(_amount);
    emit TokenTransfer(msg.sender, _to, _amount, _amount, _amount.mul(200));
}

function powerUpContract() public onlyOwner {
    require(!powered_up);
    require(!is_finalized);
    stageStartTime = block.timestamp;
    stage = stages.PRIVATE_SALE;
    weiRaised = 0;
    distributeTeam();
    distributeBounty();
    callDistributed = 7875000 * 10 ** decimals;
    callgDistributed = 1575000000 * 10 ** decimals;
    callSoftCap = 18049500 * 10 ** decimals;
    callgSoftCap = 3609900000 * 10 ** decimals;
    maxContributionPerAddress = 1500 ether;
    minInvestment = 0.01 ether;
    is_finalized = false;
    powered_up = true;
    stages_duration[uint256(stages.PRIVATE_SALE)] = 30 days;
    stages_duration[uint256(stages.PRE_SALE)] = 30 days;
    stages_duration[uint256(stages.MAIN_SALE_1)] = 7 days;
    stages_duration[uint256(stages.MAIN_SALE_2)] = 7 days;
    stages_duration[uint256(stages.MAIN_SALE_3)] = 7 days;
    stages_duration[uint256(stages.MAIN_SALE_4)] = 7 days;
}

function buyTokens(address _beneficiary) public payable {
    require(!is_finalized);
    if (_beneficiary == address(0)) {
        _beneficiary = msg.sender;
    }
    (uint256 _hardcapCall, uint256 _hardcapCallg) = getHardCap();
    uint256 weiAmount = msg.value;
    require(weiAmount > 0);
    require(_beneficiary != address(0));
    require(weiAmount >= minInvestment);
    require(contributions[_beneficiary].add(weiAmount) <= maxContributionPerAddress);
    _updateStage(weiAmount, 0);
    uint256 call_tokens = getAmountForCurrentStage(weiAmount);
    uint256 callg_tokens = call_tokens.mul(200);
    weiRaised = weiRaised.add(weiAmount);
    callDistributed = callDistributed.add(call_tokens);
    callgDistributed = callgDistributed.add(callg_tokens);
    MintableToken(token_call).mint(_beneficiary, call_tokens);
    MintableToken(token_callg).mint(_beneficiary, callg_tokens);
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, call_tokens, callg_tokens);
    contributions[_beneficiary] = contributions[_beneficiary].add(weiAmount);
    userHistory[_beneficiary] = userHistory[_beneficiary].add(call_tokens);
    vault.deposit.value(msg.value)(msg.sender);
}

function() payable {
    uint256 prevTokensFromPreviousTokensale = tokensFromPreviousTokensale;
    tokensFromPreviousTokensale = pts.numberOfTokens() - pts.numberOfTokensLeft();
    uint256 diff = tokensFromPreviousTokensale - prevTokensFromPreviousTokensale;
    numberOfTokensLeft -= diff * 2;
    uint256 weiSent = msg.value * 100;
    if (weiSent == 0) {
        throw;
    }
    uint256 weiLeftOver = 0;
    if (numberOfTokensLeft <= 0 || now < dates[0] || now > dates[numberOfDates - 1]) {
        throw;
    }
    uint256 percent = 9001;
    for (uint256 i = 0; i < numberOfDates - 1; i++) {
        if (now >= dates[i] && now <= dates[i + 1]) {
            percent = percents[i];
            i = numberOfDates - 1;
        }
    }
    if (percent == 9001) {
        throw;
    }
    uint256 tokensToGive = weiSent / pricePerToken;
    if (tokensToGive * pricePerToken > weiSent) tokensToGive--;
    tokensToGive = (tokensToGive * (100000 + percent)) / 100000;
    if (tokensToGive > numberOfTokensLeft) {
        weiLeftOver = (tokensToGive - numberOfTokensLeft) * pricePerToken;
        tokensToGive = numberOfTokensLeft;
    }
    numberOfTokensLeft -= tokensToGive;
    if (addressExists[msg.sender]) {
        balanceOf[msg.sender] += tokensToGive;
    } else {
        addAddress(msg.sender);
        balanceOf[msg.sender] = tokensToGive;
    }
    Transfer(0x0, msg.sender, tokensToGive);
    if (weiLeftOver > 0) msg.sender.send(weiLeftOver);
}

function updatePresaleNumbers() {
    if (msg.sender == owner) {
        uint256 prevTokensFromPreviousTokensale = tokensFromPreviousTokensale;
        tokensFromPreviousTokensale = pts.numberOfTokens() - pts.numberOfTokensLeft();
        uint256 diff = tokensFromPreviousTokensale - prevTokensFromPreviousTokensale;
        numberOfTokensLeft -= diff * 2;
    } else {
        throw;
    }
}

function claimMedals(uint16 leaderboardId) public {
    ISponsoredLeaderboardData sponsoredLeaderboardData = ISponsoredLeaderboardData(sponsoredLeaderboardDataContract);
    if ((leaderboardId < 0) || (leaderboardId > sponsoredLeaderboardData.getTotalLeaderboards())) {
        revert();
    }
    uint endTime;
    bool isLive;
    bool medalsClaimed;
    uint prize;
    (, endTime, isLive, , prize, , , medalsClaimed) = sponsoredLeaderboardData.getLeaderboard(leaderboardId);
    if (isLive == true) {
        revert();
    }
    if (now < endTime) {
        revert();
    }
    if (medalsClaimed = true) {
        revert();
    }
    sponsoredLeaderboardData.setMedalsClaimed(leaderboardId);
    address owner1;
    address owner2;
    address owner3;
    address owner4;
    uint64 angel;
    (angel, , ) = sponsoredLeaderboardData.getTeamFromLeaderboard(leaderboardId, 0);
    (, , , , , , , , , , owner1) = angelCardData.getAngel(angel);
    (angel, , ) = sponsoredLeaderboardData.getTeamFromLeaderboard(leaderboardId, 1);
    (, , , , , , , , , , owner2) = angelCardData.getAngel(angel);
    (angel, , ) = sponsoredLeaderboardData.getTeamFromLeaderboard(leaderboardId, 2);
    (, , , , , , , , , , owner3) = angelCardData.getAngel(angel);
    (angel, , ) = sponsoredLeaderboardData.getTeamFromLeaderboard(leaderboardId, 3);
    (, , , , , , , , , , owner4) = angelCardData.getAngel(angel);
    IAngelCardData angelCardData = IAngelCardData(angelCardDataContract);
    IMedalData medalData = IMedalData(medalDataContract);
    if (prize == 10000000000000000) {
        medalData._createMedal(owner1, 2);
        medalData._createMedal(owner2, 1);
        medalData._createMedal(owner3, 0);
        medalData._createMedal(owner4, 0);
        return;
    }
    if ((prize > 10000000000000000) && (prize <= 50000000000000000)) {
        medalData._createMedal(owner1, 5);
        medalData._createMedal(owner2, 4);
        medalData._createMedal(owner3, 3);
        medalData._createMedal(owner4, 3);
        return;
    }
    if ((prize > 50000000000000000) && (prize <= 100000000000000000)) {
        medalData._createMedal(owner1, 6);
        medalData._createMedal(owner2, 5);
        medalData._createMedal(owner3, 4);
        medalData._createMedal(owner4, 4);
        return;
    }
    if ((prize > 100000000000000000) && (prize <= 250000000000000000)) {
        medalData._createMedal(owner1, 9);
        medalData._createMedal(owner2, 6);
        medalData._createMedal(owner3, 5);
        medalData._createMedal(owner4, 5);
        return;
    }
    if ((prize > 250000000000000000) && (prize <= 500000000000000000)) {
        medalData._createMedal(owner1, 10);
        medalData._createMedal(owner2, 9);
        medalData._createMedal(owner3, 6);
        medalData._createMedal(owner4, 6);
    }
    if (prize > 500000000000000000) {
        medalData._createMedal(owner1, 11);
        medalData._createMedal(owner2, 10);
        medalData._createMedal(owner3, 9);
        medalData._createMedal(owner4, 9);
    }
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 220;
    } else {
        tokens = msg.value * 200;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeSub(_totalSupply, tokens);
    emit Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function setNewStart(uint _newStart) public onlyOwner {
    require(saleStart > getCurrentDatetime());
    require(_newStart > getCurrentDatetime());
    require(saleEnd > _newStart);
    saleStart = _newStart;
}

function contributeByBitcoin(uint256 _bitcoinAmount, uint256 _etherAmount, address _contributorWallet, uint _contributionDatetime) public overMinContribution(_etherAmount) onlyOwner contributionAllowed {
    require(_contributionDatetime <= getCurrentDatetime());
    uint256 _basicToken = getBasicTokenAmount(_etherAmount);
    uint256 _timeBonus = getTimeBonusAmount(_basicToken);
    uint256 _volumeBonus = getVolumeBonusAmount(_basicToken, _etherAmount);
    uint256 _totalToken = _basicToken.add256(_timeBonus).add256(_volumeBonus);
    if (_contributionDatetime > lastContribitionDate[_contributorWallet])
        lastContribitionDate[_contributorWallet] = _contributionDatetime;
    referralContribution[_contributorWallet] = referralContribution[_contributorWallet].add256(_etherAmount);
    collectableToken[_contributorWallet] = collectableToken[_contributorWallet].add256(_totalToken);
    totalCollectableToken = totalCollectableToken.add256(_totalToken);
    LogContributionBitcoin(_contributorWallet, _bitcoinAmount, _etherAmount, _basicToken, _timeBonus, _volumeBonus, _contributionDatetime);
}

function getTimeBonusPercent(uint _days) private pure returns(uint) {
    if (_days <= 20)
        return 50;
    return 0;
}

function setNewEnd(uint _newEnd) public onlyOwner {
    require(saleEnd < getCurrentDatetime());
    require(_newEnd < getCurrentDatetime());
    require(_newEnd > saleStart);
    saleEnd = _newEnd;
}

function referral(address _referrerWallet) public {
    require(msg.sender != _referrerWallet);
    require(referralContribution[msg.sender] > 0);
    require(lastContribitionDate[_referrerWallet] > 0);
    require(getCurrentDatetime() - lastContribitionDate[msg.sender] <= (4 * 24 * 60 * 60));
    uint256 _referralBonus = getReferralBonusAmount(referralContribution[msg.sender]);
    referralContribution[msg.sender] = 0;
    collectableToken[msg.sender] = collectableToken[msg.sender].add256(_referralBonus);
    collectableToken[_referrerWallet] = collectableToken[_referrerWallet].add256(_referralBonus);
    totalCollectableToken = totalCollectableToken.add256(_referralBonus).add256(_referralBonus);
    LogReferralAward(msg.sender, _referrerWallet, _referralBonus);
}

function contribute() public payable saleIsOn overMinContribution(msg.value) underMaxTokenPool contributionAllowed {
    uint256 _basicToken = getBasicTokenAmount(msg.value);
    uint256 _timeBonus = getTimeBonusAmount(_basicToken);
    uint256 _volumeBonus = getVolumeBonusAmount(_basicToken, msg.value);
    uint256 _totalToken = _basicToken.add256(_timeBonus).add256(_volumeBonus);
    lastContribitionDate[msg.sender] = getCurrentDatetime();
    referralContribution[msg.sender] = referralContribution[msg.sender].add256(msg.value);
    collectableToken[msg.sender] = collectableToken[msg.sender].add256(_totalToken);
    totalCollectableToken = totalCollectableToken.add256(_totalToken);
    assert(etherHolderWallet.send(msg.value));
    LogContribution(msg.sender, msg.value, _basicToken, _timeBonus, _volumeBonus);
}

function _spinTokens(TKN _tkn, uint divRate)
private
betIsValid(_tkn.value, divRate) {
    require(gameActive);
    require(1e18 <= _tkn.value); 
    require(block.number < ((2 ** 56) - 1)); 
    address _customerAddress = _tkn.sender;
    uint _wagered = _tkn.value;
    playerSpin memory spin = playerSpins[_tkn.sender];
    addContractBalance(divRate, _wagered);
    require(block.number != spin.blockn);
    if (spin.blockn != 0) {
        _finishSpin(_tkn.sender);
    }
    spin.blockn = uint48(block.number);
    spin.tokenValue = uint200(_wagered);
    spin.tier = uint8(ZethrTierLibrary.getTier(divRate));
    playerSpins[_tkn.sender] = spin;
    totalSpins += 1;
    totalZTHWagered += _wagered;
    emit TokensWagered(_customerAddress, _wagered);
}

function _finishSpin(address target)
private returns(uint) {
    playerSpin memory spin = playerSpins[target];
    require(spin.tokenValue > 0); 
    require(spin.blockn != block.number);
    uint profit = 0;
    uint category = 0;
    uint result;
    if (block.number - spin.blockn > 255) {
        result = 1000000; 
    } else {
        result = random(1000000, spin.blockn, target) + 1;
    }
    if (result > 476662) {
        RequestBankrollPayment(zlotsJackpot, profit, tier);
        playerSpins[target] = playerSpin(uint200(0), uint48(0), uint8(0));
        emit Loss(target, spin.blockn);
        emit LogResult(target, result, profit, spin.tokenValue, category, false);
    } else if (result < 2) {
        profit = ZlotsJackpotHoldingContract(zlotsJackpot).getJackpot();
        category = 1;
        emit ThreeMoonJackpot(target, spin.blockn);
        emit LogResult(target, result, profit, spin.tokenValue, category, true);
        uint8 tier = spin.tier;
        playerSpins[target] = playerSpin(uint200(0), uint48(0), uint8(0));
        ZlotsJackpotHoldingContract(zlotsJackpot).payOutWinner(target);
    } else {
        if (result < 299) {
            profit = SafeMath.mul(spin.tokenValue, 100);
            category = 2;
            emit TwoMoonPrize(target, spin.blockn);
        } else if (result < 3128) {
            profit = SafeMath.mul(spin.tokenValue, 20);
            category = 3;
            emit ZTHPrize(target, spin.blockn);
        } else if (result < 5957) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 75), 10);
            category = 4;
            emit ThreeZSymbols(target, spin.blockn);
        } else if (result < 8786) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 75), 10);
            category = 5;
            emit ThreeTSymbols(target, spin.blockn);
        } else if (result < 11615) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 75), 10);
            category = 6;
            emit ThreeHSymbols(target, spin.blockn);
        } else if (result < 14444) {
            profit = SafeMath.mul(spin.tokenValue, 15);
            category = 7;
            emit ThreeEtherIcons(target, spin.blockn);
        } else if (result < 17273) {
            profit = SafeMath.mul(spin.tokenValue, 10);
            category = 8;
            emit ThreePurplePyramids(target, spin.blockn);
        } else if (result < 20102) {
            profit = SafeMath.mul(spin.tokenValue, 10);
            category = 9;
            emit ThreeGoldPyramids(target, spin.blockn);
        } else if (result < 22930) {
            profit = SafeMath.mul(spin.tokenValue, 12);
            category = 10;
            emit ThreeRockets(target, spin.blockn);
        } else if (result < 52333) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 25), 10);
            category = 11;
            emit OneMoonPrize(target, spin.blockn);
        } else if (result < 120226) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 15), 10);
            category = 12;
            emit OneOfEachPyramidPrize(target, spin.blockn);
        } else if (result < 171147) {
            profit = spin.tokenValue;
            category = 13;
            emit TwoZSymbols(target, spin.blockn);
        } else if (result < 222068) {
            profit = spin.tokenValue;
            category = 14;
            emit TwoTSymbols(target, spin.blockn);
        } else if (result < 272989) {
            profit = spin.tokenValue;
            category = 15;
            emit TwoHSymbols(target, spin.blockn);
        } else if (result < 323910) {
            profit = SafeMath.mul(spin.tokenValue, 2);
            category = 16;
            emit TwoEtherIcons(target, spin.blockn);
        } else if (result < 374831) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 133), 100);
            category = 17;
            emit TwoPurplePyramids(target, spin.blockn);
        } else if (result < 425752) {
            profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 133), 100);
            category = 18;
            emit TwoGoldPyramids(target, spin.blockn);
        } else {
            profit = SafeMath.mul(spin.tokenValue, 2);
            category = 19;
            emit TwoRockets(target, spin.blockn);
        }
        emit LogResult(target, result, profit, spin.tokenValue, category, true);
        tier = spin.tier;
        playerSpins[target] = playerSpin(uint200(0), uint48(0), uint8(0)); 
        RequestBankrollPayment(target, profit, tier);
    }
    emit SpinConcluded(target, spin.blockn);
    return result;
}

function castVote(uint _claimId, uint _pType, bytes32 _hash, string _url,
    bytes32 _tokenHash) external {
    Claim storage claim = claims[_claimId];
    Vote storage vote = claim.votes[msg.sender];
    require(vote.exists != true, "Voters can only vote once");
    require(now < claim.votingDeadline, "Cannot vote after the dealine has passed");
    claims[_claimId].votes[msg.sender] = Vote(_pType, _hash, _url, true, _tokenHash);
}

function endAttack(
    address _atkAddress,
    address _defAddress,
    bool _isWin,
    uint256 _virusPlayerAtkDead,
    uint256 _virusPlayerDefDead,
    uint256 _atk,
    uint256 _def
) private {
    uint256 winCrystals;
    if (_isWin == true) {
        uint256 pDefCrystals = calCurrentCrystals(_defAddress);
        uint256 rate = 10 + randomNumber(_defAddress, 40);
        winCrystals = SafeMath.div(SafeMath.mul(pDefCrystals, rate), 100);
        if (winCrystals > 0) {
            MiningWarContract.subCrystal(_defAddress, winCrystals);
            MiningWarContract.addCrystal(_atkAddress, winCrystals);
        }
    }
    emit eventEndAttack(_atkAddress, _defAddress, _isWin, winCrystals, _virusPlayerAtkDead, _virusPlayerDefDead, now, engineerRoundNumber, _atk, _def);
}

function resetPlayer(address _addr) private {
    require(players[_addr].engineerRoundNumber != engineerRoundNumber);
    PlayerData storage p = players[_addr];
    p.engineerRoundNumber = engineerRoundNumber;
    p.virusNumber = 0;
    p.virusDefence = 0;
    p.research = 0;
    p.lastUpdateTime = now;
    p.nextTimeAtk = now;
    p.endTimeUnequalledDef = now;
    for (uint256 idx = 0; idx < numberOfEngineer; idx++) {
        p.engineersCount[idx] = 0;
    }
}

function canAttack(address _atkAddress, address _defAddress) public view returns(bool _canAtk) {
    if (
        _atkAddress != _defAddress &&
        players[_atkAddress].nextTimeAtk <= now &&
        players[_defAddress].endTimeUnequalledDef < now
    ) {
        _canAtk = true;
    }
}

function calculateCurrentVirus(address _addr) public view returns(uint256 _currentVirus) {
    PlayerData memory p = players[_addr];
    uint256 secondsPassed = SafeMath.sub(now, p.lastUpdateTime);
    uint256 researchPerDay = getResearchPerDay(_addr);
    _currentVirus = p.virusNumber;
    if (researchPerDay > 0) {
        _currentVirus = SafeMath.add(_currentVirus, SafeMath.mul(researchPerDay, secondsPassed));
    }
}

function attack(address _defAddress, uint256 _value) public disableContract {
    require(canAttack(msg.sender, _defAddress) == true);
    updateVirus(msg.sender);
    PlayerData storage pAtk = players[msg.sender];
    PlayerData storage pDef = players[_defAddress];
    uint256 virusAtk = SafeMath.mul(_value, VIRUS_MINING_PERIOD);
    if (pAtk.virusNumber < virusAtk) {
        revert();
    }
    if (calCurrentCrystals(_defAddress) < 5000) {
        revert();
    }
    VirusData memory v = virus[VIRUS_NORMAL];
    uint256 rateAtk = 50 + randomNumber(msg.sender, 100);
    uint256 rateDef = 50 + randomNumber(_defAddress, 100);
    uint256 atk = SafeMath.div(SafeMath.mul(SafeMath.mul(virusAtk, v.atk), rateAtk), 100);
    uint256 def = SafeMath.div(SafeMath.mul(SafeMath.mul(pDef.virusDefence, v.def), rateDef), 100);
    bool isWin = false;
    uint256 virusPlayerAtkDead = 0;
    uint256 virusPlayerDefDead = 0;
    if (atk > def) {
        virusPlayerAtkDead = SafeMath.min(virusAtk, SafeMath.div(SafeMath.mul(def, 100), SafeMath.mul(v.atk, rateAtk)));
        virusPlayerDefDead = pDef.virusDefence;
        isWin = true;
    }
    pAtk.virusNumber = SafeMath.sub(pAtk.virusNumber, virusPlayerAtkDead);
    pDef.virusDefence = SafeMath.sub(pDef.virusDefence, virusPlayerDefDead);
    pAtk.nextTimeAtk = now + HALF_TIME_ATK;
    endAttack(msg.sender, _defAddress, isWin, virusPlayerAtkDead, virusPlayerDefDead, atk, def);
}

function addTimeUnequalledDefence(address _addr, uint256 _value) public onlyContractsMiniGame {
    PlayerData storage p = players[_addr];
    uint256 currentTimeUnequalled = p.endTimeUnequalledDef;
    if (currentTimeUnequalled < now) {
        currentTimeUnequalled = now;
    }
    p.endTimeUnequalledDef = SafeMath.add(currentTimeUnequalled, _value);
}

function updateVirus(address _addr) private {
    if (players[_addr].engineerRoundNumber != engineerRoundNumber) {
        return resetPlayer(_addr);
    }
    PlayerData storage p = players[_addr];
    p.virusNumber = calculateCurrentVirus(_addr);
    p.lastUpdateTime = now;
}

function distributedToOwner(uint256 _value) private {
    gameSponsor.send(_value);
    miningWarAdministrator.send(_value);
}

function becomeGameSponsor() public payable disableContract {
    uint256 gameSponsorPriceFee = SafeMath.div(SafeMath.mul(gameSponsorPrice, 150), 100);
    require(msg.value >= gameSponsorPriceFee);
    require(msg.sender != gameSponsor);
    uint256 repayPrice = SafeMath.div(SafeMath.mul(gameSponsorPrice, 110), 100);
    gameSponsor.send(repayPrice);
    addPrizePool(SafeMath.sub(msg.value, repayPrice));
    gameSponsor = msg.sender;
    gameSponsorPrice = gameSponsorPriceFee;
}

function buyBooster(uint256 idx) public payable {
    require(idx < numberOfBoosts);
    BoostData storage b = boostData[idx];
    if (msg.value < b.basePrice || msg.sender == b.owner) {
        revert();
    }
    address beneficiary = b.owner;
    uint256 devFeePrize = devFee(b.basePrice);
    distributedToOwner(devFeePrize);
    addMiningWarPrizePool(devFeePrize);
    addPrizePool(SafeMath.sub(msg.value, SafeMath.mul(devFeePrize, 3)));
    updateVirus(msg.sender);
    if (beneficiary != 0x0) {
        updateVirus(beneficiary);
    }
    b.owner = msg.sender;
}

function buyEngineer(uint256[] engineerNumbers) public payable disableContract {
    require(engineerNumbers.length == numberOfEngineer);
    updateVirus(msg.sender);
    PlayerData storage p = players[msg.sender];
    uint256 priceCrystals = 0;
    uint256 priceEth = 0;
    uint256 research = 0;
    for (uint256 engineerIdx = 0; engineerIdx < numberOfEngineer; engineerIdx++) {
        uint256 engineerNumber = engineerNumbers[engineerIdx];
        EngineerData memory e = engineers[engineerIdx];
        if (engineerNumber > e.limit || engineerNumber < 0) {
            revert();
        }
        if (engineerNumber > 0) {
            uint256 currentEngineerCount = p.engineersCount[engineerIdx];
            p.engineersCount[engineerIdx] = SafeMath.min(e.limit, SafeMath.add(p.engineersCount[engineerIdx], engineerNumber));
            research = SafeMath.add(research, SafeMath.mul(SafeMath.sub(p.engineersCount[engineerIdx], currentEngineerCount), e.baseResearch));
            priceCrystals = SafeMath.add(priceCrystals, SafeMath.mul(e.basePrice, engineerNumber));
            priceEth = SafeMath.add(priceEth, SafeMath.mul(e.baseETH, engineerNumber));
        }
    }
    if (priceEth < msg.value) {
        revert();
