onlyOwner uninitialized {
    require(_start >= getCurrentTimestamp());
    require(_start < _end);
    require(_wallet != 0x0);
    require(_totalSupply > _saleCap);
    startDate = _start;
    endDate = _end;
    saleCap = _saleCap;
    wallet = _wallet;
    totalSupply = _totalSupply;
    balances[wallet] = _totalSupply.sub(saleCap);
    balances[0x1] = saleCap;
}

