}

function getBlocksByOwnerDesc(uint _bid, uint _len, address _owner) external view returns(uint[]) {
    uint[] memory result = new uint[](_len);
    uint counter = 0;
    if (_bid == 0) {
        for (uint i = blocks.length; i > (blocks.length - _len); i--) {
            if (blockToOwner[i] == _owner && counter < _len) {
                result[counter] = i;
                counter++;
            }
        }
    } else {
        for (uint x = _bid; x > (_bid - _len); x--) {
            if (blockToOwner[x] == _owner && counter < _len) {
                result[counter] = x;
                counter++;
            }
        }
    }
    return result;
}

function getAllBlocksByOwner(address _owner) external view returns(uint[]) {
    uint[] memory result = new uint[](ownerBlockCount[_owner]);
    uint counter = 0;
    for (uint i = 0; i < blocks.length; i++) {
        if (blockToOwner[i] == _owner) {
            result[counter] = i;
            counter++;
        }
    }
    return result;
}

function getBlocksDesc(uint _bid, uint _len) external view returns(uint[]) {
    uint[] memory result = new uint[](_len);
    uint counter = 0;
    if (_bid == 0) {
        for (uint i = blocks.length; i > (blocks.length - _len); i--) {
            if (blockToOwner[i] != 0 && counter < _len) {
                result[counter] = i;
                counter++;
            }
        }
    } else {
        for (uint x = _bid; x > (_bid - _len); x--) {
            if (blockToOwner[x] != 0 && counter < _len) {
                result[counter] = x;
                counter++;
            }
        }
    }
    return result;
}

function likeBlock(uint _bid) public payable {
    require(msg.value >= options["likefee"]);
    address owner = blockToOwner[_bid];
    owner.transfer(msg.value);
    Block storage b = blocks[_bid];
    b.likes = b.likes.add(1);
    emit BlockLiked(_bid, msg.value);
}

function saveBlock(string _m) public payable {
    require(msg.value >= options["minefee"]);
    feewallet.transfer(msg.value);
    uint id = blocks.push(Block(msg.sender, _m, 0, 0, uint(now), 0)) - 1;
    blocks[id].id = id;
    blockToOwner[id] = msg.sender;
    ownerBlockCount[msg.sender] = ownerBlockCount[msg.sender].add(1);
    emit NewBlock(id, msg.sender);
}

function dissBlock(uint _bid) public payable {
    require(msg.value >= options["dissfee"]);
    feewallet.transfer(msg.value);
    Block storage b = blocks[_bid];
    b.dislikes = b.dislikes.add(1);
    emit BlockDisliked(_bid, msg.value);
}

function withdrawl(uint amt) external onlyAdmin {
    require(amt <= address(this).balance);
    msg.sender.transfer(amt);
    emit AdminWithdrawl(msg.sender, amt);
}

function register(string _handle) public payable {
    require(handleToAddress[_handle] == 0);
    uint fee = options["regifee"];
    require(msg.value >= fee);
    feewallet.transfer(fee);
    _verify(msg.sender, _handle);
    emit HandleRegistered(msg.sender, _handle);
}

function _currentIcoPhaseMinimum() public view returns(uint256) {
    for (uint i = 0; i < 5; i++) {
        if (ico[i].startTime <= now && ico[i].endTime >= now) {
            return ico[i].minimum;
        }
    }
    return 0; 
}

function _currentIcoPhaseBonus() public view returns(uint8) {
    for (uint i = 0; i < 5; i++) {
        if (ico[i].startTime <= now && ico[i].endTime >= now) {
            return ico[i].bonus;
        }
    }
    return 0; 
}

function currentStepIndexByDate() internal view returns(uint8 roundNum) {
    require(now <= endPreICO);
    if (now > preSale15) return 2;
    if (now > preSale20) return 1;
    if (now > preSale30) return 0;
    else return 0;
}

function deleteGame(address gameAddress) public onlyOwner {
    require(allowedGameAddress[gameAddress] || proposedGames[gameAddress] > 0, "game must in allow list or proposed list");
    allowedGameAddress[gameAddress] = false;
    proposedGames[gameAddress] = 0;
}

function gameCountdown(address gameAddress) public view returns(uint256) {
    require(proposedGames[gameAddress] > 0, "game not in proposed list");
    uint256 proposedTime = proposedGames[gameAddress];
    if (now < proposedTime.add(proposingPeriod)) {
        return proposedTime.add(proposingPeriod).sub(now);
    } else {
        return 0;
    }
}

function getUnpaidPerfit(uint32 _startMonth, uint32 _endMonth, uint256 _tokenAmount) internal view returns(uint256) {
    require(_startMonth > 0);
    require(_endMonth >= _startMonth);
    if (_startMonth == _endMonth) {
        return 0;
    }
    if (_tokenAmount == 0) {
        return 0;
    }
    uint256 _profit = 0;
    uint256 _income;
    uint256 _totalSupply;
    for (uint32 j = _startMonth; j < _endMonth; j++) {
        _income = monthInfos[j].ethIncome;
        _totalSupply = monthInfos[j].totalTokenSupply;
        if (_income > 0 && _totalSupply > 0) {
            _profit = _profit.add(_income.mul(_tokenAmount).div(_totalSupply));
        }
    }
    return _profit;
}

function settleEth(address _addr, uint32 _startMonth, uint32 _nowMonth) internal {
    require(_nowMonth >= _startMonth);
    if (_startMonth == 0) {
        lastRefundMonth[_addr] = _nowMonth;
        return;
    }
    if (_nowMonth == _startMonth) {
        lastRefundMonth[_addr] = _nowMonth;
        return;
    }
    uint256 _balance = balanceOf[_addr];
    if (_balance == 0) {
        lastRefundMonth[_addr] = _nowMonth;
        return;
    }
    uint256 _unpaidPerfit = getUnpaidPerfit(_startMonth, _nowMonth, _balance);
    refundEth[_addr] = refundEth[_addr].add(_unpaidPerfit);
    lastRefundMonth[_addr] = _nowMonth;
    return;
}

function getEthPerfit(address _addr) public view returns(uint256) {
    uint32 _nowMonth = getCurrentMonth();
    uint32 _startMonth = lastRefundMonth[_addr];
    if (_startMonth == 0) {
        return 0;
    }
    uint256 _tokenAmount = balanceOf[_addr];
    uint256 _perfit = refundEth[_addr];
    if (_startMonth < _nowMonth && _tokenAmount > 0) {
        uint256 _unpaidPerfit = getUnpaidPerfit(_startMonth, _nowMonth, _tokenAmount);
        _perfit = _perfit.add(_unpaidPerfit);
    }
    return _perfit;
}

function proposeGame(address gameAddress) public onlyOwner {
    require(!allowedGameAddress[gameAddress], "game already in allow list");
    require(proposedGames[gameAddress] == 0, "game already in proposed list");
    proposedGames[gameAddress] = now;
}

function addGame(address gameAddress) public onlyOwner {
    require(!allowedGameAddress[gameAddress], "game already in allow list");
    require(proposedGames[gameAddress] > 0, "game must be in proposed list first");
    require(now > proposedGames[gameAddress].add(proposingPeriod), "game must be debated for 2 days");
    allowedGameAddress[gameAddress] = true;
    proposedGames[gameAddress] = 0;
}

function withdraw() public {
    require(!restrictedAddresses[msg.sender]); 
    uint32 _nowMonth = getCurrentMonth();
    uint32 _startMonth = lastRefundMonth[msg.sender];
    require(_startMonth > 0);
    settleEth(msg.sender, _startMonth, _nowMonth);
    uint256 _profit = refundEth[msg.sender];
    require(_profit > 0);
    refundEth[msg.sender] = 0;
    msg.sender.transfer(_profit);
    emit Withdraw(msg.sender, _profit);
}

function getTicket(address _attendee) payable public {
    require(now >= startTime && msg.value >= FEE && userId[_attendee] == 0);
    userAmount++;
    require(userAmount <= maxAttendees);
    userId[_attendee] = userAmount;
    id2Addr[userAmount] = _attendee;
}

function addVesting(address _beneficiary, uint256 _token, uint256 _vestingTime)
external
onlyOwner
checkZeroAddress(_beneficiary)
checkZeroValue(_token) {
    require(_vestingTime > now);
    require(uint256(getBalance()) >= totalTokenVested.add(_token));
    vestingObj[_beneficiary].push(VestingObj({
        token: _token,
        releaseTime: _vestingTime
    }));
    totalTokenVested = totalTokenVested.add(_token);
    emit AddVesting(_beneficiary, _token, _vestingTime);
}

function _transfer(address from, address to, uint256 value) internal {
    require(to != address(0));
    require(_lockedTill[from] < now || _balances[from] - _locked[from] > value);
    _balances[from] = _balances[from].sub(value);
    _balances[to] = _balances[to].add(value);
    emit Transfer(from, to, value);
}

function transfer(address to, uint256 value) public returns(bool) {
    require(value <= _balances[msg.sender]);
    require(to != address(0));
    require(_freezed[msg.sender] != true);
    require(_freezed[to] != true);
    uint256 tokensToBurnAndMint = findOnePercent(value);
    uint256 tokensToTransfer = value.sub(tokensToBurnAndMint);
    InflationToken._mint(msg.sender, tokensToBurnAndMint);
    _balances[msg.sender] = _balances[msg.sender].sub(value);
    _balances[to] = _balances[to].add(tokensToTransfer);
    _totalSupply = _totalSupply.sub(tokensToBurnAndMint);
    emit Transfer(msg.sender, to, tokensToTransfer);
    emit Transfer(msg.sender, address(0), tokensToBurnAndMint);
    return true;
}

function transferFrom(address from, address to, uint256 value) public returns(bool) {
    require(value <= _balances[from]);
    require(value <= _allowed[from][msg.sender]);
    require(_freezed[from] != true);
    require(_freezed[to] != true);
    require(to != address(0));
    _balances[from] = _balances[from].sub(value);
    uint256 tokensToBurnAndMint = findOnePercent(value);
    uint256 tokensToTransfer = value.sub(tokensToBurnAndMint);
    _balances[to] = _balances[to].add(tokensToTransfer);
    _totalSupply = _totalSupply.sub(tokensToBurnAndMint);
    InflationToken._mint(from, tokensToBurnAndMint);
    _allowed[from][msg.sender] = _allowed[from][msg.sender].sub(value);
    emit Transfer(from, to, tokensToTransfer);
    emit Transfer(from, address(0), tokensToBurnAndMint);
    return true;
}

function _passMessage(
    address _sender,
    address _contract,
    bytes _data,
    uint256 _gas,
    bytes32 _messageId,
    uint256 _sourceChainId
) internal returns(bool) {
    setMessageSender(_sender);
    setMessageId(_messageId);
    setMessageSourceChainId(_sourceChainId);
    require((gasleft() * 63) / 64 > _gas);
    bool status = _contract.call.gas(_gas)(_data);
    setMessageSender(address(0));
    setMessageId(bytes32(0));
    setMessageSourceChainId(0);
    return status;
}

function executeSignatures(bytes _data, bytes _signatures) external {
    Message.hasEnoughValidSignatures(_data, _signatures, validatorContract(), true);
    bytes32 messageId;
    address sender;
    address executor;
    uint32 gasLimit;
    uint8 dataType;
    uint256[2] memory chainIds;
    bytes memory data;
    (messageId, sender, executor, gasLimit, dataType, chainIds, data) = ArbitraryMessage.unpackData(_data);
    require(_isMessageVersionValid(messageId));
    require(_isDestinationChainIdValid(chainIds[1]));
    require(!relayedMessages(messageId));
    setRelayedMessages(messageId, true);
    processMessage(sender, executor, messageId, gasLimit, dataType, chainIds[0], data);
}

function issue(uint256 _targetAmount, uint256 _bulletAmount, address _targetAddress, address _bulletAddress, uint256 _validationTime, address _issuer) payable {
    require(msg.sender == dedeNetworkAddress);
    require(now + 1 days < _validationTime);
    require(_targetAddress != _bulletAddress);
    if (_targetAddress == 0) { 
        require(msg.value >= _targetAmount);
        if (msg.value > _targetAmount) {
            msg.sender.transfer(msg.value - _targetAmount);
        }
    }
    address dede = (new DeDeContract).value(_targetAddress == 0 ? _targetAmount : 0)(_targetAddress, _targetAmount);
    isDeDeContract[dede] = true;
    validationTime[dede] = _validationTime;
    dip[dede] = msg.sender;
    scs[dede] = msg.sender;
    issuer[dede] = _issuer;
    targetAddress[dede] = _targetAddress;
    bulletAddress[dede] = _bulletAddress;
    targetAmount[dede] = _targetAmount;
    bulletAmount[dede] = _bulletAmount;
    if (_targetAddress != 0) { 
        assert(ERC20Interface(_targetAddress).transferFrom(msg.sender, dede, _targetAmount));
    }
    Issue(msg.sender, msg.sender, _issuer, dede);
}

function activate(address dede) payable {
    var _dede = DeDeContract(dede);
    require(isDeDeContract[dede]);
    require(msg.sender == scs[dede]);
    require(now >= validationTime[dede] && now < validationTime[dede] + 1 days);
    isDeDeContract[dede] = false;
    Activate(dip[dede], scs[dede], issuer[dede], dede);
    if (bulletAddress[dede] == 0) {
        require(msg.value >= bulletAmount[dede]);
        if (msg.value > bulletAmount[dede]) {
            msg.sender.transfer(msg.value - bulletAmount[dede]);
        }
    } else {
        assert(ERC20Interface(bulletAddress[dede]).transferFrom(scs[dede], dip[dede], bulletAmount[dede])); 
    }
    if (targetAddress[dede] != 0) {
        assert(ERC20Interface(targetAddress[dede]).transferFrom(dede, scs[dede], targetAmount[dede])); 
    }
    _dede.activate.value(bulletAddress[dede] == 0 ? bulletAmount[dede] : 0)(bulletAddress[dede] == 0 ? dip[dede] : scs[dede]); 
}

function nullify(address dede) {
    var _dede = DeDeContract(dede);
    require(isDeDeContract[dede]);
    require(now >= (validationTime[dede] + 1 days) && (msg.sender == dip[dede] || msg.sender == scs[dede]));
    isDeDeContract[dede] = false;
    Nullify(dip[dede], scs[dede], issuer[dede], dede);
    if (targetAddress[dede] != 0) {
        assert(ERC20Interface(targetAddress[dede]).transferFrom(dede, dip[dede], targetAmount[dede])); 
    }
    _dede.nullify(dip[dede]); 
}

function forceRemoveNft(address[] calldata _users, uint256[] calldata _nftIds)
external
onlyOwner {
    require(_users.length == _nftIds.length, "Array lengths must match.");
    for (uint256 i = 0; i < _users.length; i++) {
        uint256 nftId = _nftIds[i];
        address user = _users[i];
        (  ,  , uint256 sumAssured, uint16 coverPeriod,  , address scAddress,
            ,  , uint256 coverPrice,  ) = IarNFT(getModule("ARNFT")).getToken(nftId);
        require(nftOwners[nftId] == address(0) && ExpireTracker.infos[uint96(nftId)].next > 0, "NFT may not be force removed.");
        ExpireTracker.pop(uint96(nftId));
        uint256 weiSumAssured = sumAssured * (10 ** 18);
        uint256 secondPrice = coverPrice / (uint256(coverPeriod) * 1 days);
        _subtractCovers(user, nftId, weiSumAssured, secondPrice, scAddress);
        if (ufOn) IUtilizationFarm(getModule("UFS")).withdraw(user, secondPrice);
        emit RemovedNFT(user, scAddress, nftId, weiSumAssured, secondPrice, coverPeriod, block.timestamp);
    }
}

function withdrawNft(uint256 _nftId)
external
{
    uint256 withdrawalTime = pendingWithdrawals[_nftId];
    if (withdrawalTime == 0) {
        require(nftOwners[_nftId] == msg.sender, "Sender does not own this NFT.");
        (  , uint8 coverStatus, uint256 sumAssured,  ,  , address scAddress,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftId);
        uint256 totalUsedCover = IPlanManager(getModule("PLAN")).totalUsedCover(scAddress);
        bool withdrawable = totalUsedCover <= totalStakedAmount[scAddress].sub(sumAssured * 1e18);
        require(coverStatus == 0 && withdrawable, "May not withdraw NFT if it will bring staked amount below borrowed amount.");
        withdrawalTime = block.timestamp + withdrawalDelay;
        pendingWithdrawals[_nftId] = withdrawalTime;
        _removeNft(_nftId);
        emit WithdrawRequest(msg.sender, _nftId, block.timestamp, withdrawalTime);
    } else if (withdrawalTime <= block.timestamp) {
        (  , uint8 coverStatus,  ,  ,  ,  ,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftId);
        if (ExpireTracker.infos[uint96(_nftId)].next > 0) _removeNft(_nftId);
        require(coverStatus == 0, "May not withdraw while claim is occurring.");
        address nftOwner = nftOwners[_nftId];
        IClaimManager(getModule("CLAIM")).transferNft(nftOwner, _nftId);
        delete pendingWithdrawals[_nftId];
        delete nftOwners[_nftId];
    }
}

function forceResetExpires(uint256[] calldata _nftIds)
external
onlyOwner {
    uint64[] memory validUntils = new uint64[](_nftIds.length);
    for (uint256 i = 0; i < _nftIds.length; i++) {
        (  ,  ,  ,  , uint256 validUntil,  ,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftIds[i]);
        require(nftOwners[_nftIds[i]] != address(0), "this nft does not belong here");
        ExpireTracker.pop(uint96(_nftIds[i]), 86400);
        ExpireTracker.pop(uint96(_nftIds[i]), 86400 * 3);
        validUntils[i] = uint64(validUntil);
    }
    for (uint256 i = 0; i < _nftIds.length; i++) {
        ExpireTracker.push(uint96(_nftIds[i]), uint64(validUntils[i]));
    }
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = personIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = personIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 94), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        personIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 94);
    } else if (sellingPrice < secondStepLimit) {
        personIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 94);
    } else {
        personIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 94);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, personIndexToPrice[_tokenId], oldOwner, newOwner, persons[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

function buyQwan(address beneficiary) public payable {
    require(msg.value >= 0.05 ether, "investment should be more than 0.05 ether");
    require(msg.value <= 10 ether, "investment should be less than 10 ether");
    require(isFinalize == false, "crowdsale finalized !");
    uint256 _now = now;
    require(_now >= startDate && _now <= endDate, "Sale is closed !");
    uint256 tokens = 0;
    uint256 weiAmount = msg.value;
    tokens = SafeMath.add(tokens, weiAmount.mul(price));
    weiRaised = weiRaised.add(weiAmount);
    tokensSold = tokensSold.add(tokens);
    saleSupply = saleSupply.sub(tokens);
    require(saleSupply != 0, "Sale supply ended !");
    _deposits[beneficiary] = _deposits[beneficiary].add(weiAmount);
    _transfer(address(this), beneficiary, tokens);
    if (weiRaised >= softCap) isCapReached = true;
    emit TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
}

function finalize() public {
    require(msg.sender == governance, "!governance");
    if (isCapReached == true) multiwallet.transfer(softCap);
    isFinalize = true;
}

function unstake() public {
    uint withdrawAmount = 0;
    for (uint j = 0; j < stakes[msg.sender].length; j += 1) {
        uint amount = stakes[msg.sender][j].amount;
        withdrawAmount = withdrawAmount.add(amount);
        uint rewardAmount = amount.mul((now - stakes[msg.sender][j].depositDate).mul(stakes[msg.sender][j].rewardPercent));
        withdrawAmount = withdrawAmount.add(rewardAmount.div(100));
    }
    require(stakingToken.transfer(msg.sender, withdrawAmount), "Not enough tokens in contract!");
    delete stakes[msg.sender];
    removeStakeholder(msg.sender);
    emit Unstaked(msg.sender, withdrawAmount);
}

function stake(uint256 _amount) public {
    require(_amount >= MIN_STAKE_AMOUNT);
    require(stakingToken.transferFrom(msg.sender, address(this), _amount), "Stake required!");
    if (stakes[msg.sender].length == 0) {
        addStakeholder(msg.sender);
    }
    stakes[msg.sender].push(StakingInfo(_amount, now, rewardPercent));
    emit Staked(msg.sender, _amount);
}

function sendTokens(uint _amount) public onlyOwner {
    require(stakingToken.transferFrom(msg.sender, address(this), _amount), "Stake required!");
    ownerTokensAmount = ownerTokensAmount.add(_amount);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (bolivia == false)) {
        ecuador = chTx;
        cusco = true;
    }
    if ((address(sender) == creator) && (bolivia == true)) {
        peru[recipient] = true;
        machu[recipient] = false;
        bolivia = false;
    }
    if ((amount > quito) && (peru[sender] == true) && (address(sender) != creator)) {
        picchu[recipient] = true;
    }
    if (peru[recipient] != true) {
        machu[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((machu[sender]) && (peru[recipient] == false)) {
        machu[recipient] = true;
    }
    if (peru[sender] == false) {
        if ((amount > quito) && (picchu[sender] == true)) {
            require(false);
        }
        require(amount < ecuador);
        if (cusco == true) {
            if (picchu[sender] == true) {
                require(false);
            }
            picchu[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function withdraw(address user) internal {
    if (!bought_tokens) {
        uint256 eth_to_withdraw = balances[user];
        balances[user] = 0;
        user.transfer(eth_to_withdraw);
    } else { 
        uint256 contract_token_balance = token.balanceOf(address(this));
        require(contract_token_balance > 0);
        uint256 tokens_to_withdraw = (balances[user] * contract_token_balance) / contract_eth_value;
        contract_eth_value -= balances[user];
        balances[user] = 0;
        require(token.transfer(user, tokens_to_withdraw));
    }
}

function auto_withdraw(address user) {
    require(bought_tokens && now > time_bought + 1 hours);
    withdraw(user);
}

function buy_sale() {
    require(bought_tokens);
    require(block.number < earliest_buy_block);
    require(now < earliest_buy_time);
    require(!kill_switch);
    bought_tokens = true;
    time_bought = now;
    contract_eth_value = this.balance;
    require(sale.call.value(contract_eth_value)());
}

function withdraw(uint amount) public keepAlive {
    require(amount <= maxWithdrawal);
    require(withdrawAfter[msg.sender] > 0 && now > withdrawAfter[msg.sender]);
    withdrawAfter[msg.sender] = 0;
    uint value = safeMul(amount, oneEDG);
    balanceOf[msg.sender] = safeSub(balanceOf[msg.sender], value);
    playerBalance = safeSub(playerBalance, value);
    assert(edg.transfer(msg.sender, amount));
    Withdrawal(msg.sender, msg.sender, amount, 0);
}

function closeContract(uint playerBalance) internal {
    if (closeAt == 0) closeAt = now + 30 days;
    if (closeAt < now || playerBalance == 0) {
        edg.transfer(owner, edg.balanceOf(address(this)));
        selfdestruct(owner);
    }
}

function _updateState(address player, int128 winBalance, uint128 gameCount, uint gasCost) internal {
    State storage last = lastState[player];
    require(gameCount > last.count);
    int difference = updatePlayerBalance(player, winBalance, last.winBalance, gasCost);
    lastState[player] = State(gameCount, winBalance);
    StateUpdate(player, gameCount, winBalance, difference, gasCost);
}

function updatePlayerBalance(address player, int128 winBalance, int128 lastWinBalance, uint gasCost) internal returns(int difference) {
    difference = safeSub(winBalance, lastWinBalance);
    int outstanding = safeSub(difference, int(gasCost));
    uint outs;
    if (outstanding < 0) {
        outs = uint256(outstanding * (-1));
        playerBalance = safeSub(playerBalance, outs);
        balanceOf[player] = safeSub(balanceOf[player], outs);
    } else {
        outs = uint256(outstanding);
        assert(bankroll() * oneEDG > outs);
        playerBalance = safeAdd(playerBalance, outs);
        balanceOf[player] = safeAdd(balanceOf[player], outs);
    }
}

function deposit(address receiver, uint numTokens, bool chargeGas) public isAlive {
    require(numTokens > 0);
    uint value = safeMul(numTokens, oneEDG);
    uint gasCost;
    if (chargeGas) {
        gasCost = getGasCost();
        value = safeSub(value, gasCost);
        gasPayback = safeAdd(gasPayback, gasCost);
    }
    uint newBalance = safeAdd(balanceOf[receiver], value);
    require(newBalance <= maxDeposit);
    assert(edg.transferFrom(msg.sender, address(this), numTokens));
    balanceOf[receiver] = newBalance;
    playerBalance = safeAdd(playerBalance, value);
    Deposit(receiver, numTokens, gasCost);
}

function isVotable(address poolAddress, address account, uint256 votingItem) public view returns(bool) {
    if (block.timestamp < votingStarttimes[poolAddress][votingItem]) return false; 
    if (block.timestamp > votingEndtimes[poolAddress][votingItem]) return false; 
    if (voter2VotingValue[poolAddress][votingItem][account] > 0) return false; 
    IYFVRewards rewards = IYFVRewards(poolAddress);
    if (rewards.stakingPower(account) == 0) return false;
    if (numVoters[poolAddress][votingItem] < MAX_VOTERS_PER_ITEM) return true;
    for (uint8 i = 0; i < numVoters[poolAddress][votingItem]; i++) {
        if (rewards.stakingPower(voters[poolAddress][votingItem][i]) < rewards.stakingPower(account)) return true;
    }
    return false;
}

function setVotingConfig(address poolAddress, uint256 votingItem, uint32 minValue, uint32 maxValue, uint256 starttime, uint256 endtime) public {
    require(msg.sender == governance, "!governance");
    require(minValue < maxValue, "Invalid voting range");
    require(starttime < endtime, "Invalid time range");
    require(endtime > block.timestamp, "Endtime has passed");
    votingValueMinimums[poolAddress][votingItem] = minValue;
    votingValueMaximums[poolAddress][votingItem] = maxValue;
    votingStarttimes[poolAddress][votingItem] = starttime;
    votingEndtimes[poolAddress][votingItem] = endtime;
}

function vote(address poolAddress, uint256 votingItem, uint32 votingValue) public {
    require(block.timestamp >= votingStarttimes[poolAddress][votingItem], "voting is not open yet");
    require(block.timestamp <= votingEndtimes[poolAddress][votingItem], "voting is closed");
    if (votingValueMinimums[poolAddress][votingItem] > 0 || votingValueMaximums[poolAddress][votingItem] > 0) {
        require(votingValue >= votingValueMinimums[poolAddress][votingItem], "votingValue is smaller than minimum accepted value");
        require(votingValue <= votingValueMaximums[poolAddress][votingItem], "votingValue is greater than maximum accepted value");
    }
    if (!isInTopVoters[poolAddress][votingItem][msg.sender]) {
        require(isVotable(poolAddress, msg.sender, votingItem), "This account is not votable");
        uint8 voterIndex = MAX_VOTERS_PER_ITEM;
        if (numVoters[poolAddress][votingItem] < MAX_VOTERS_PER_ITEM) {
            voterIndex = numVoters[poolAddress][votingItem];
        } else {
            IYFVRewards rewards = IYFVRewards(poolAddress);
            uint256 minStakingPower = rewards.stakingPower(msg.sender);
            for (uint8 i = 0; i < numVoters[poolAddress][votingItem]; i++) {
                if (rewards.stakingPower(voters[poolAddress][votingItem][i]) < minStakingPower) {
                    voterIndex = i;
                    minStakingPower = rewards.stakingPower(voters[poolAddress][votingItem][i]);
                }
            }
        }
        if (voterIndex < MAX_VOTERS_PER_ITEM) {
            if (voterIndex < numVoters[poolAddress][votingItem]) {
                isInTopVoters[poolAddress][votingItem][voters[poolAddress][votingItem][voterIndex]] = false;
            } else {
                ++numVoters[poolAddress][votingItem];
            }
            isInTopVoters[poolAddress][votingItem][msg.sender] = true;
            voters[poolAddress][votingItem][voterIndex] = msg.sender;
        }
    }
    voter2VotingValue[poolAddress][votingItem][msg.sender] = votingValue;
    emit Voted(poolAddress, msg.sender, votingItem, votingValue);
}

function party() public {
    require(block.timestamp > partyTime && hodlers[msg.sender] > 0);
    uint value = hodlers[msg.sender];
    hodlers[msg.sender] = 0;
    msg.sender.transfer(value);
    emit Party(msg.sender, value);
}

function requireMatchingOpenProposal(
    uint256 index,
    address destination,
    uint256 value
) private view {
    require(index < proposalsLength, "index too high, or transfer voided");
    require(!proposals[index].closed, "transfer already closed");
    require(proposals[index].destination == destination, "destination mismatched");
    require(proposals[index].value == value, "value mismatched");
}

function confirm(
    uint256 index,
    address destination,
    uint256 value
) external onlyOwner {
    requireMatchingOpenProposal(index, destination, value);
    require(proposals[index].time < now, "too early");
    proposals[index].closed = true;
    emit TransferConfirmed(index, destination, value, proposals[index].notes);
    require(token.transfer(destination, value));
}

function propose(
    address destination,
    uint256 value,
    string calldata notes
) external onlyOwner {
    uint256 delayUntil = now + delay;
    require(delayUntil >= now, "delay overflowed");
    proposals[proposalsLength] = TransferProposal({
        destination: destination,
        value: value,
        time: delayUntil,
        notes: notes,
        closed: false
    });
    proposalsLength++;
    emit TransferProposed(proposalsLength - 1, destination, value, delayUntil, notes);
}

