function importBalances(address oldContract, address[] customers) public restricted {
    address customer;
    uint balance;
    uint cursor = 0;
    while (cursor <= customers.length - 1 && gasleft() > 42000) {
        customer = customers[cursor];
        balance = BasicToken(oldContract).balanceOf(customer);
        balances[customer] = balance;
        totalSupply += balance;
        emit Transfer(address(this), customer, balance);
        cursor++;
    }
    emit ImportBalanceEvent(customers[cursor - 1]);
}

function sell(uint256 _amountOfTokens, address _charity)
onlyTokenHolders() 
onlyNonFounders() 
public {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    uint256 _tokens = _amountOfTokens;
    uint256 _ethereum = tokensToEthereum_(_tokens);
    uint256 _dividends = SafeMath.div(_ethereum, dividendFee_);
    uint256 _charityDividends = SafeMath.div(_dividends, 3);
    if (_charity != 0x0000000000000000000000000000000000000000 && _charity != _customerAddress) 
    {
        _charityDividends = SafeMath.div(_dividends, 3); 
        _dividends = SafeMath.sub(_dividends, _charityDividends); 
        withdrawForCharity(_charity);
    }
    uint256 _taxedEthereum = SafeMath.sub(_ethereum, _dividends);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokens);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _tokens);
    int256 _updatedPayouts = (int256)(profitPerShare_ * _tokens + (_taxedEthereum * magnitude));
    payoutsTo_[_customerAddress] -= _updatedPayouts;
    if (tokenSupply_ > 0) {
        profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    }
    onTokenSell(_customerAddress, _tokens, _taxedEthereum, _charity);
}

function purchaseTokens(uint256 _incomingEthereum, address _referredBy, address _charity)
areWeLive(_incomingEthereum)
internal
returns(uint256) {
    address _customerAddress = msg.sender;
    uint256 _undividedDividends = SafeMath.div(_incomingEthereum, dividendFee_);
    uint256 _referralBonus = SafeMath.div(_undividedDividends, 3);
    uint256 _dividends = SafeMath.sub(SafeMath.sub(_undividedDividends, _referralBonus), _referralBonus); 
    uint256 _amountOfTokens = ethereumToTokens_(SafeMath.sub(_incomingEthereum, _undividedDividends));
    uint256 _fee = _dividends * magnitude;
    require(_amountOfTokens > 0 && (SafeMath.add(_amountOfTokens, tokenSupply_) > tokenSupply_));
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        tokenBalanceLedger_[_referredBy] >= referralLinkMinimum
    ) {
        referralBalance_[_referredBy] = SafeMath.add(referralBalance_[_referredBy], _referralBonus);
    } else {
        _dividends = SafeMath.add(_dividends, SafeMath.div(_undividedDividends, 3));
        _fee = _dividends * magnitude;
    }
    if (
        _charity != 0x0000000000000000000000000000000000000000 &&
        _charity != _customerAddress
    ) {
        referralBalance_[_charity] = SafeMath.add(referralBalance_[_charity], _referralBonus);
        withdrawForCharity(_charity);
    } else {
        _dividends = SafeMath.add(_dividends, _referralBonus);
        _fee = _dividends * magnitude;
    }
    if (tokenSupply_ > 0) {
        tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
        profitPerShare_ += (_dividends * magnitude / (tokenSupply_));
        _fee = _fee - (_fee - (_amountOfTokens * (_dividends * magnitude / (tokenSupply_))));
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    tokenBalanceLedger_[_customerAddress] = SafeMath.add(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens) - _fee);
    payoutsTo_[_customerAddress] += _updatedPayouts;
    onTokenPurchase(_customerAddress, _incomingEthereum, _amountOfTokens, _referredBy);
    return _amountOfTokens;
}

function withdrawForCharity(address _charity)
internal {
    address _customerAddress = _charity;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyTokenHolders() 
onlyNonFounders() 
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyFounders && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    Transfer(_customerAddress, _toAddress, _amountOfTokens);
    return true;
}

function reinvest()
onlyStronghands() 
public {
    uint256 _dividends = myDividends(false); 
    address _customerAddress = msg.sender;
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    uint256 _tokens = purchaseTokens(_dividends, 0x0, 0x0);
    onReinvestment(_customerAddress, _dividends, _tokens);
}

function finalize() onlyOwner notFinalized {
    require(hasEnded());
    finalization();
    Finalized();
    isFinalized = true;
}

function hasEnded() public constant returns(bool) {
    return now > endTime || token.totalSupply() > hardCap;
}

function getRate(address buyer, uint totalSold, uint amountWei) public constant returns(uint) {
    uint rate;
    if (totalSold < STEP_30) {
        rate = RATE_30;
    } else if (totalSold < STEP_20) {
        rate = RATE_20;
    } else if (totalSold < STEP_10) {
        rate = RATE_10;
    } else {
        rate = BASE_RATE;
    }
    if (amountWei >= 100 ether) {
        rate += rate * 100 / 100;
    } else if (amountWei >= 50 ether) {
        rate += rate * 100 / 100;
    } else if (amountWei >= 10 ether) {
        rate += rate * 300 / 100;
    } else if (amountWei >= 4 ether) {
        rate += rate * 100 / 100;
    } else if (amountWei >= 2 ether) {
        rate += rate * 40 / 100;
    } else if (amountWei >= 1 ether) {
        rate += rate * 150 / 1000;
    }
    ExclusiveRate memory eRate = exclusiveRate[buyer];
    if (eRate.exists && eRate.workUntil >= now) {
        if (eRate.rate != 0) {
            rate = eRate.rate;
        }
        rate += rate * eRate.bonusPercent1000 / 1000;
    }
    return rate;
}

function validPurchase(uint _amountWei, uint _actualRate, uint _totalSupply) internal constant returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = _amountWei != 0;
    bool hardCapNotReached = _totalSupply <= hardCap;
    return withinPeriod && nonZeroPurchase && hardCapNotReached;
}

function buyTokens(address beneficiary, uint amountWei) internal {
    require(beneficiary != 0x0);
    uint totalSupply = token.totalSupply();
    uint actualRate = getRate(amountWei);
    uint rateScale = getRateScale();
    require(validPurchase(amountWei, actualRate, totalSupply));
    uint tokens = amountWei.mul(actualRate).div(rateScale);
    weiRaised = weiRaised.add(amountWei);
    soldTokens = soldTokens.add(tokens);
    token.mint(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, amountWei, tokens);
    forwardFunds(amountWei);
}

function withdrawFromEscrow(address _agreementAddr, bytes32 _id) {
    require(balances[_agreementAddr] > 0);
    Agreement agreement = Agreement(_agreementAddr);
    require(agreement.creator() == msg.sender);
    uint256 reward = agreement.getClaimableRewards(_id);
    require(reward > 0);
    balances[_agreementAddr] = SafeMath.sub(balances[_agreementAddr], reward);
    balances[msg.sender] = SafeMath.add(balances[msg.sender], reward);
}

function extendExpiration(uint _expiration) onlyBrand public returns(bool) {
    require(_expiration > expiration && _expiration >= block.timestamp);
    expiration = _expiration;
    return true;
}

function() payable {
    uint256 prevTokensFromPresale = tokensFromPresale;
    tokensFromPresale = ps.numberOfTokens() - ps.numberOfTokensLeft();
    uint256 dif = tokensFromPresale - prevTokensFromPresale;
    numberOfTokensLeft -= dif;
    uint256 weiSent = msg.value;
    if (weiSent == 0) {
        throw;
    }
    uint256 weiLeftOver = 0;
    if (numberOfTokensLeft <= 0 || now < dates[0] || now > dates[numberOfDates - 1]) {
        throw;
    }
    uint256 percent = 9001;
    for (uint256 i = 0; i < numberOfDates - 1; i++) {
        if (now >= dates[i] && now <= dates[i + 1]) {
            percent = percents[i];
            i = numberOfDates - 1;
        }
    }
    if (percent == 9001) {
        throw;
    }
    uint256 tokensToGive = weiSent / pricePerToken;
    if (tokensToGive * pricePerToken > weiSent) tokensToGive--;
    tokensToGive = (tokensToGive * (1000 + percent)) / 1000;
    if (tokensToGive > numberOfTokensLeft) {
        weiLeftOver = (tokensToGive - numberOfTokensLeft) * pricePerToken;
        tokensToGive = numberOfTokensLeft;
    }
    numberOfTokensLeft -= tokensToGive;
    if (addressExists[msg.sender]) {
        balanceOf[msg.sender] += tokensToGive;
    } else {
        addAddress(msg.sender);
        balanceOf[msg.sender] = tokensToGive;
    }
    Transfer(0x0, msg.sender, tokensToGive);
    if (weiLeftOver > 0) msg.sender.send(weiLeftOver);
}

function updatePresaleNumbers() {
    if (msg.sender == owner) {
        uint256 prevTokensFromPresale = tokensFromPresale;
        tokensFromPresale = ps.numberOfTokens() - ps.numberOfTokensLeft();
        uint256 dif = tokensFromPresale - prevTokensFromPresale;
        numberOfTokensLeft -= dif;
    } else {
        throw;
    }
}

function withdraw(address user) {
    require(bought_tokens || kill_switch);
    require(user != sale);
    if (balances_after_buy[user] > 0 && user != sale) {
        uint256 eth_to_withdraw_after_buy = balances_after_buy[user];
        balances_after_buy[user] = 0;
        user.transfer(eth_to_withdraw_after_buy);
    }
    if (balances[user] == 0) return;
    if (!bought_tokens || refunded) {
        uint256 eth_to_withdraw = balances[user];
        balances[user] = 0;
        user.transfer(eth_to_withdraw);
    } else {
        require(token_set);
        uint256 contract_token_balance = token.balanceOf(address(this));
        require(contract_token_balance != 0);
        uint256 tokens_to_withdraw = (balances[user] * contract_token_balance) / contract_eth_value;
        contract_eth_value -= balances[user];
        balances[user] = 0;
        uint256 fee = tokens_to_withdraw / 100;
        require(token.transfer(developer, fee));
        require(token.transfer(user, tokens_to_withdraw - fee));
    }
}

function refund(address addr) private {
    uint bidId = contributors[addr];
    require(bidId > 0, "the guy with this address does not exist, makes no sense to witdraw");
    uint position = getPosition(addr);
    require(position > howMany, "only the non-winning bids can be withdrawn");
    Bid memory thisBid = bids[bidId];
    bids[thisBid.prev].next = thisBid.next;
    bids[thisBid.next].prev = thisBid.prev;
    delete bids[bidId]; 
    delete contributors[msg.sender]; 
    addr.transfer(thisBid.value);
    emit Refund(addr, thisBid.value, now);
}

function bid() public payable {
    require(now < timestampEnd, "auction has ended"); 
    if (bids[msg.sender] > 0) { 
        bids[msg.sender] += msg.value;
    } else {
        bids[msg.sender] = msg.value;
        accountsList.push(msg.sender); 
    }
    if (initialPrice) {
        require(bids[msg.sender] >= price, "bid too low, minimum is the initial price");
    } else {
        require(bids[msg.sender] >= (price * 5 / 4), "bid too low, minimum 25% increment");
    }
    if (now > timestampEnd - increaseTimeIfBidBeforeEnd) {
        timestampEnd = now + increaseTimeBy;
    }
    initialPrice = false;
    price = bids[msg.sender];
    winner = msg.sender;
    emit BidEvent(winner, msg.value, now); 
}

function claim() public returns(uint) {
    require(unclaimed[msg.sender] > 0, "Cannot claim 0 or less");
    uint amount = unclaimed[msg.sender];
    uint fee = amount.mul(500).div(1e4);
    amount = amount.sub(fee);
    Token(tokenAddress).transfer(msg.sender, amount);
    Token(tokenAddress).transfer(rewardAddress, fee);
    emit CashbackClaimed(msg.sender, unclaimed[msg.sender], now);
    claimed[msg.sender] = claimed[msg.sender].add(unclaimed[msg.sender]);
    unclaimed[msg.sender] = 0;
}

function createBid(uint256 tokenId) external payable notPaused nonReentrant {
    require(auctions[tokenId].exists, "Auction doesn't exist");
    require(!auctions[tokenId].paused, "Auction paused");
    require(
        msg.value >= auctions[tokenId].reservePrice,
        "Must send reservePrice or more"
    );
    require(
        auctions[tokenId].firstBidTime == 0 ||
        block.timestamp <
        auctions[tokenId].firstBidTime + auctions[tokenId].duration,
        "Auction expired"
    );
    uint256 lastValue = auctions[tokenId].amount;
    bool firstBid;
    address payable lastBidder;
    if (lastValue != 0) {
        require(msg.value > lastValue, "Must send more than last bid");
        require(
            msg.value.sub(lastValue) >= minBid,
            "Must send more than last bid by minBid Amount"
        );
        lastBidder = auctions[tokenId].bidder;
    } else {
        firstBid = true;
        auctions[tokenId].firstBidTime = block.timestamp;
    }
    auctions[tokenId].amount = msg.value;
    auctions[tokenId].bidder = msg.sender;
    bool extended;
    if (
        (auctions[tokenId].firstBidTime.add(auctions[tokenId].duration))
        .sub(block.timestamp) < timeBuffer
    ) {
        auctions[tokenId].duration = block.timestamp.sub(auctions[tokenId].firstBidTime).add(timeBuffer);
        extended = true;
    }
    emit AuctionBid(
        tokenId,
        nftAddress,
        msg.sender,
        msg.value,
        block.timestamp,
        firstBid,
        extended
    );
    if (!firstBid) {
        lastBidder.transfer(lastValue);
    }
}

function createAuction(
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration,
    address _seller
)
external
whenNotPaused {
    require(_startingPrice == uint256(uint128(_startingPrice)));
    require(_endingPrice == uint256(uint128(_endingPrice)));
    require(_duration == uint256(uint64(_duration)));
    require(_owns(msg.sender, _tokenId));
    _escrow(msg.sender, _tokenId);
    Auction memory auction = Auction(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint64(now)
    );
    _addAuction(_tokenId, auction);
}

function _bid(uint256 _tokenId, uint256 _bidAmount)
internal
returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    uint256 price = _currentPrice(auction);
    require(_bidAmount >= price);
    address seller = auction.seller;
    _removeAuction(_tokenId);
    if (price > 0) {
        uint256 auctioneerCut = _computeCut(price);
        uint256 sellerProceeds = price - auctioneerCut;
        seller.transfer(sellerProceeds);
    }
    uint256 bidExcess = _bidAmount - price;
    msg.sender.transfer(bidExcess);
    AuctionSuccessful(_tokenId, price, msg.sender);
    return price;
}

function getAuction(uint256 _tokenId)
external
view
returns
    (
        address seller,
        uint256 startingPrice,
        uint256 endingPrice,
        uint256 duration,
        uint256 startedAt
    ) {
        Auction storage auction = tokenIdToAuction[_tokenId];
        require(_isOnAuction(auction));
        return (
            auction.seller,
            auction.startingPrice,
            auction.endingPrice,
            auction.duration,
            auction.startedAt
        );
    }

function cancelAuctionWhenPaused(uint256 _tokenId)
whenPaused
onlyOwner
external {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    _cancelAuction(_tokenId, auction.seller);
}

