function createTokens(address _sender, uint256 _value) public whenNotPaused {
    require(_value > 0);
    require(depositorsTokens > 0);
    require(now <= fundingEndTime);
    require(_value >= minContribution);
    uint256 tokens = (_value * RATE) / oneTokenInWei;
    require(tokens > 0);
    if (now <= firstPeriodEND) {
        tokens = ((tokens * 100) * (firstPeriodDis + 100)) / 10000;
    } else if (now > firstPeriodEND && now <= secondPeriodEND) {
        tokens = ((tokens * 100) * (secondPeriodDis + 100)) / 10000;
    } else if (now > secondPeriodEND && now <= thirdPeriodEND) {
        tokens = ((tokens * 100) * (thirdPeriodDis + 100)) / 10000;
    }
    require(depositorsTokens.sub(tokens) >= 0);
    depositorsTokens = depositorsTokens.sub(tokens);
    _totalSupply = _totalSupply.add(tokens);
    require(sell(_sender, tokens));
    owner.transfer(_value);
}

function isLeftTokens(uint256 _value) public view returns(bool) {
    require(_value > 0);
    uint256 tokens = (_value * RATE) / oneTokenInWei;
    require(tokens > 0);
    if (now <= firstPeriodEND) {
        tokens = ((tokens * 100) * (firstPeriodDis + 100)) / 10000;
    } else if (now > firstPeriodEND && now <= secondPeriodEND) {
        tokens = ((tokens * 100) * (secondPeriodDis + 100)) / 10000;
    } else if (now > secondPeriodEND && now <= thirdPeriodEND) {
        tokens = ((tokens * 100) * (thirdPeriodDis + 100)) / 10000;
    }
    return depositorsTokens.sub(tokens) >= 0;
}

function withdrawAll() onlyOwner public {
    rebalancing = true;
    emptyAssets();
    owner.call {
        value: address(this).balance
    }("");
    spreadToAssets();
    rebalancing = false;
}

function spreadToAssets() internal {
    uint totalAmount = address(this).balance;
    uint currentAmount = totalAmount;
    for (uint i = 0; i < totalAssets; i++) {
        if (currentAmount == 0) {
            break;
        }
        Asset memory asset = assets[i];
        uint assetRatio = asset.ratio;
        if (assetRatio == 0) {
            break;
        }
        uint amountPerAsset = totalAmount * assetRatio / 10000;
        if (amountPerAsset <= currentAmount) {
            buyAsset(i, amountPerAsset);
            if (amountPerAsset == currentAmount) {
                currentAmount = 0;
            } else {
                currentAmount -= amountPerAsset;
            }
        } else {
            buyAsset(i, currentAmount);
            currentAmount = 0;
        }
    }
}

function withdraw(uint amount) onlyOwner public {
    rebalancing = true;
    emptyAssets();
    owner.call {
        value: amount
    }("");
    spreadToAssets();
    rebalancing = false;
}

function buyAsset(uint currentIndex, uint amountIn) internal {
    Asset memory asset = assets[currentIndex];
    address buyingAddress = asset.tokenAddress;
    address wethAddress = config.wethAddress;
    require(amountIn <= address(this).balance, "Can't send more than current balance");
    if (buyingAddress == wethAddress) {
        iWeth.deposit {
            value: amountIn
        }();
    } else {
        uint slippage = config.slippage;
        uint swapTimeLimit = config.swapTimeLimit;
        address[] memory path = new address[](2);
        path[0] = wethAddress;
        path[1] = buyingAddress;
        uint[] memory amountsOut = iUniswapRouter.getAmountsOut(amountIn, path);
        uint tokenOutput = amountsOut[1];
        uint amountOutMin = tokenOutput * (10000 - slippage) / 10000;
        uint deadline = block.timestamp + swapTimeLimit;
        uint[] memory amounts = iUniswapRouter.swapExactETHForTokens {
            value: amountIn
        }(amountOutMin, path, address(this), deadline);
    }
    updateAssetBalance(currentIndex);
}

function fundPortfolio(uint portfolioIndex) public payable {
    Portfolio portfolio = portfolios[portfolioIndex];
    address(portfolio).call {
