        ) = TaskRegister(upgradableState.prevVersion).tasks(j);
    }
    for (j = index; j < index + _size && j < tasksCount; j++) {
        (, 
            , 
            , 
            , 
            , 
            , 
            , 
            , 
            tasks[j].requestPublicYPoint,
            tasks[j].answerPrivateKey
        ) = TaskRegister(upgradableState.prevVersion).tasks(j);
    }
}

function withdraw()
onlyStronghands()
sell_timestamp()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
sell_timestamp()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function checkLocked(address _addr, uint256 _value) internal view returns(bool) {
    if (balanceLocked[_addr] > 0) { 
        if (now > lockAtTime[_addr] + 180 days) {
            return true;
        } else if (now > lockAtTime[_addr] + 90 days) {
            return (balances[_addr] - _value >= balanceLocked[_addr] / 10 * 4);
        } else {
            return (balances[_addr] - _value >= balanceLocked[_addr] / 10 * 7);
        }
    }
    return true;
}

function getFreeBalances(address _addr) public view returns(uint) {
    if (balanceLocked[_addr] > 0) {
        if (now > lockAtTime[_addr] + 180 days) {
            return balances[_addr];
        } else if (now > lockAtTime[_addr] + 90 days) {
            return balances[_addr] - balanceLocked[_addr] / 10 * 4;
        } else {
            return balances[_addr] - balanceLocked[_addr] / 10 * 7;
        }
    }
    return balances[_addr];
}

function payout() nonReentrant public returns(uint256 reward) {
    (uint256 unitradeOut, uint256 _reward) = _applyReward();
    emit Withdraw(msg.sender, unitradeOut, _reward);
    reward = _reward;
    require(reward > 0, "Nothing to pay out");
    TransferHelper.safeTransferETH(msg.sender, reward);
    _stake(unitradeOut);
    timelock[msg.sender] = block.timestamp.add(DEFAULT_STAKE_PERIOD);
}

function withdraw() nonReentrant public returns(uint256 unitradeOut, uint256 reward) {
    require(block.timestamp >= timelock[msg.sender], "Stake is locked");
    (unitradeOut, reward) = _applyReward();
    emit Withdraw(msg.sender, unitradeOut, reward);
    timelock[msg.sender] = 0;
    TransferHelper.safeTransfer(unitrade, msg.sender, unitradeOut);
    if (reward > 0) {
        TransferHelper.safeTransferETH(msg.sender, reward);
    }
}

function redistributeEthForAddresses(uint256 index, address[] addresses) public {
    if ((msg.sender == ideas[index].creator) || (msg.sender == ideas[index].host)) {
        if (ideas[index].status == FAILED_STATUS) {
            for (uint256 i = 0; i < addresses.length; i++) {
                address addr = addresses[i];
                if (!ideas[index].reclaimed[addr]) {
                    uint256 reclaimAmount = ideas[index].amountPledged[addr];
                    if (reclaimAmount > 0) {
                        ideas[index].reclaimed[addr] = true;
                        emit UserRegainedAmountAtIndex(addr, reclaimAmount, index);
                        addr.transfer(reclaimAmount);
                    }
                }
            }
        }
    }
}

function pledgeEth(uint256 index) payable returns(bool) {
    uint256 amount = msg.value;
    if (msg.sender == ideas[index].creator || msg.sender == ideas[index].host) revert();
    if (amount == 0 || amount > MAX_FUNDING_AMOUNT) revert();
    if ((ideas[index].status == UNDERWAY_STATUS) || (ideas[index].status == SUFFICIENT_STATUS)) {
        if (block.number <= SafeMath.add(ideas[index].startTime, ideas[index].duration)) {
            uint256 amountAvailable = SafeMath.sub(ideas[index].maxGoal, ideas[index].amountRaisedSoFar);
            if (amount > amountAvailable) revert();
            ideas[index].amountRaisedSoFar = SafeMath.add(ideas[index].amountRaisedSoFar, amount);
            ideas[index].amountPledged[msg.sender] = SafeMath.add(ideas[index].amountPledged[msg.sender], amount);
            if (ideas[index].amountRaisedSoFar == ideas[index].maxGoal) {
                maxGoalReached(index);
            } else if ((ideas[index].amountRaisedSoFar >= ideas[index].minGoal) && (ideas[index].status == UNDERWAY_STATUS)) {
                ideas[index].status = SUFFICIENT_STATUS;
                emit SufficientFundingReached(index);
            }
            emit UserPledgedAmountAtIndex(msg.sender, amount, index);
            return true;
        }
    }
    return false;
}

function finalize() onlyOwner public {
    require(!isFinalized);
    require(hasClosed() || goalReached());
    finalization();
    Finalized();
    isFinalized = true;
}

function _getTokenAmount(uint256 _weiAmount) internal view returns(uint256) {
    uint256 tokens = _weiAmount.mul(rate);
    uint256 bonusTokens = 0;
    if (now < openingTime.add(7 days)) {
        bonusTokens = tokens.mul(15).div(100);
    } else {
        bonusTokens = tokens.mul(75).div(1000);
    }
    return tokens.add(bonusTokens);
}

function batchTransferEther(address[] _receivers, uint[] _amounts) public payable checkArrayArgument(_receivers, _amounts) {
    require(msg.value != 0 && msg.value == getTotalSendingAmount(_amounts));
    for (uint i = 0; i < _receivers.length; i++) {
        require(_receivers[i] != address(0));
        _receivers[i].transfer(_amounts[i]);
        emit TransferEther(msg.sender, _receivers[i], _amounts[i]);
    }
}

function closeAgreementWithTimeout(bytes _state, uint8[2] _sigV, bytes32[2] _sigR, bytes32[2] _sigS) public onlyParticipants whenNotPaused {
    address _ambassador = getSig(_state, _sigV[0], _sigR[0], _sigS[0]);
    address _expert = getSig(_state, _sigV[1], _sigR[1], _sigS[1]);
    require(getTokenAddress(_state) == nectarAddress, "Invalid token address");
    require(settlementPeriodEnd <= block.number, "Settlement period hasn&#39;t ended");
    require(isClosed == 0, "Offer is closed");
    require(isInSettlementState == 1, "Offer is not in settlement state");
    require(_hasAllSigs(_ambassador, _expert), "Missing signatures");
    require(keccak256(state) == keccak256(_state), "State hash mismatch");
    isClosed = 1;
    finalize(_state);
    isOpen = false;
    emit ClosedAgreement(_expert, _ambassador);
}

function initializeOfferChannel(uint128 guid, address _ambassador, address _expert, uint _settlementPeriodLength) external whenNotPaused {
    require(address(0) != _expert, "Invalid expert address");
    require(address(0) != _ambassador, "Invalid ambassador address");
    require(msg.sender == _ambassador, "Initializer isn&#39;t ambassador");
    require(guidToChannel[guid].msig == address(0), "GUID already in use");
    bytes32 key = getParticipantsHash(_ambassador, _expert);
    if (participantsToChannel[key] != address(0)) {
        require(OfferMultiSig(participantsToChannel[key]).isChannelOpen() == false,
            "Channel already exists between parties");
    }
    address msig = new OfferMultiSig(nectarAddress, _ambassador, _expert, _settlementPeriodLength);
    participantsToChannel[key] = msig;
    guidToChannel[guid].msig = msig;
    guidToChannel[guid].ambassador = _ambassador;
    guidToChannel[guid].expert = _expert;
    channelsGuids.push(guid);
    emit InitializedChannel(msig, _ambassador, _expert, guid);
}

function closeAgreement(bytes _state, uint8[2] _sigV, bytes32[2] _sigR, bytes32[2] _sigS) public onlyParticipants whenNotPaused {
    address _ambassador = getSig(_state, _sigV[0], _sigR[0], _sigS[0]);
    address _expert = getSig(_state, _sigV[1], _sigR[1], _sigS[1]);
    require(getTokenAddress(_state) == nectarAddress, "Invalid token address");
    require(isClosed == 0, "Offer is closed");
    require(isInSettlementState == 0, "Offer is in settlement state");
    require(_isClosed(_state), "State did not have a signed close out state");
    require(_hasAllSigs(_ambassador, _expert), "Missing signatures");
    isClosed = 1;
    state = _state;
    finalize(_state);
    isOpen = false;
    emit ClosedAgreement(_expert, _ambassador);
}

function _execute(
    address target,
    uint value,
    bytes calldata data,
    uint eta,
    uint nonce
) private {
    bytes32 txHash = _getTxHash(target, value, data, eta, nonce);
    require(queued[txHash], "!queued");
    require(block.timestamp >= eta, "eta < now");
    require(block.timestamp <= eta + GRACE_PERIOD, "eta expired");
    queued[txHash] = false;
    (bool success, ) = target.call {
        value: value
    }(data);
    require(success, "tx failed");
    emit Log(txHash, target, value, data, eta, nonce, State.Executed);
}

function cancel(
    address target,
    uint value,
    bytes calldata data,
    uint eta,
    uint nonce
) external onlyAdmin {
    bytes32 txHash = _getTxHash(target, value, data, eta, nonce);
    require(queued[txHash], "!queued");
    queued[txHash] = false;
    emit Log(txHash, target, value, data, eta, nonce, State.Canceled);
}

function _queue(
    address target,
    uint value,
    bytes calldata data,
    uint delay,
    uint nonce
) private {
    require(delay >= MIN_DELAY, "delay < min");
    require(delay <= MAX_DELAY, "delay > max");
    uint eta = block.timestamp + delay;
    bytes32 txHash = _getTxHash(target, value, data, eta, nonce);
    require(!queued[txHash], "queued");
    queued[txHash] = true;
    emit Log(txHash, target, value, data, eta, nonce, State.Queued);
}

function init() private {
    require(!initialized);
    initialized = true;
    if (PAUSED) {
        pause();
    }
    address[1] memory addresses = [address(0x945c0172763b665045a9a19056f82d65bef06408)];
    uint[1] memory amounts = [uint(1000000000000000000000)];
    uint64[1] memory freezes = [uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
        if (freezes[i] == 0) {
            mint(addresses[i], amounts[i]);
        } else {
            mintAndFreeze(addresses[i], amounts[i], freezes[i]);
        }
    }
    if (!CONTINUE_MINTING) {
        finishMinting();
    }
    emit Initialized();
}

function createAuction(
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration,
    address _seller
)
public
whenNotPaused
canBeStoredWith128Bits(_startingPrice)
canBeStoredWith128Bits(_endingPrice)
canBeStoredWith64Bits(_duration) {
    require(_owns(msg.sender, _tokenId));
    _escrow(msg.sender, _tokenId);
    Auction memory auction = Auction(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint64(now)
    );
    _addAuction(_tokenId, auction);
}

function buy(
    address sellToken, uint256 sellTokenId,
    address owner,
    uint256 buyValue,
    address buyer
) payable external {
    validateBuyRequest(sellToken, sellTokenId, buyValue);
    uint256 serviceFeeAmount = buyValue.mul(serviceFee).div(1000);
    uint256 amount = buyValue - serviceFeeAmount;
    address[] memory fee_receivers = IERC721(sellToken).getFeeReceivers();
    uint256 feePercentage = IERC721(sellToken).getFeePercentage();
    if (feePercentage == 0) {
        transferProxy.erc721safeTransferFrom(IERC721(sellToken), owner, buyer, sellTokenId);
        address payable to_address = address(uint160(owner));
        to_address.send(amount);
    } else {
        DistributionItem[] memory distributions = getDistributions(sellToken, owner, fee_receivers, feePercentage, amount);
        transferProxy.erc721safeTransferFrom(IERC721(sellToken), owner, buyer, sellTokenId);
        for (uint256 i = 0; i < distributions.length; i++) {
            if (distributions[i]._amount > 0) {
                address payable to_address = address(uint160(distributions[i]._address));
                to_address.transfer(distributions[i]._amount);
            }
        }
    }
    if (serviceFeeAmount > 0) {
        serviceAddress.transfer(serviceFeeAmount);
    }
    buyOrder[sellToken][sellTokenId] = 0;
}

function stake(IERC721 token, uint256 tokenID) public {
    require(IERC721(token).ownerOf(tokenID) == _msgSender(), "Not owner.");
    transferProxy.erc721Stake(token, tokenID, address(this));
    erc20TransferProxy.erc20safeTransferFrom(IERC20(caribmarsAddress), governanceAddress, _msgSender(), farmTokenAmount);
    tokenStakings[address(token)][tokenID] = true;
    stakingBlockNumbers[address(token)][tokenID] = block.number;
}

function exchange(
    address sellToken, uint256 sellTokenId,
    address owner,
    address buyToken, uint256 buyValue,
    address buyer
) payable external {
    require(owner == _msgSender(), "Exchange: The only token owner can accept bid.");
    validateBidRequest(sellToken, sellTokenId, buyer, buyToken, buyValue);
    uint256 serviceFeeAmount = buyValue.mul(serviceFee).div(1000);
    uint256 amount = buyValue - serviceFeeAmount;
    address[] memory fee_receivers = IERC721(sellToken).getFeeReceivers();
    uint256 feePercentage = IERC721(sellToken).getFeePercentage();
    if (feePercentage == 0) {
        transferProxy.erc721safeTransferFrom(IERC721(sellToken), owner, buyer, sellTokenId);
        erc20TransferProxy.erc20safeTransferFrom(IERC20(buyToken), buyer, owner, amount);
    } else {
        DistributionItem[] memory distributions = getDistributions(sellToken, owner, fee_receivers, feePercentage, amount);
        transferProxy.erc721safeTransferFrom(IERC721(sellToken), owner, buyer, sellTokenId);
        for (uint256 i = 0; i < distributions.length; i++) {
            if (distributions[i]._amount > 0) {
                erc20TransferProxy.erc20safeTransferFrom(IERC20(buyToken), buyer, distributions[i]._address, distributions[i]._amount);
            }
        }
    }
    if (serviceFeeAmount > 0) {
        erc20TransferProxy.erc20safeTransferFrom(IERC20(buyToken), buyer, serviceAddress, serviceFeeAmount);
    }
    CancelAllBid(sellToken, sellTokenId, buyToken);
    auctionOrder[sellToken][sellTokenId] = address(0);
}

function clearStake(IERC721 token, uint256 tokenID) public {
    require(tokenStakings[address(token)][tokenID] == true, "Not staked token.");
    require(IERC721(token).ownerOf(tokenID) == _msgSender(), "Not owner.");
    uint256 feeAmount = (block.number - stakingBlockNumbers[address(token)][tokenID]) * farmFeePerBlock;
    erc20TransferProxy.erc20safeTransferFrom(IERC20(caribmarsAddress), _msgSender(), governanceAddress, farmTokenAmount);
    IERC721(token).clearStake(tokenID);
    erc20TransferProxy.erc20safeTransferFrom(IERC20(caribmarsAddress), governanceAddress, _msgSender(), feeAmount);
    tokenStakings[address(token)][tokenID] = false;
}

