    balances[msg.sender] = balances[msg.sender].add(tokens);
    _totalMintSupply = _totalMintSupply.add(tokens);
    contractModifierAddress.transfer(msg.value);
    emit Transfer(0x0, msg.sender, tokens);
}

function() public payable {
