    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(contractAddress, false); 
    balanceLedger[_customerAddress][contractAddress].payOut += (int256)(_dividends * magnitude);
    _dividends += balanceLedger[_customerAddress][contractAddress].referralBalance;
    balanceLedger[_customerAddress][contractAddress].referralBalance = 0;
    if (contractAddress == address(0)) {
        payable(address(_customerAddress)).transfer(_dividends);
    } else {
        ERC20(contractAddress).transfer(_customerAddress, _dividends);
    }
    emit onWithdraw(_customerAddress, contractAddress, _dividends);
}

function totalSupply() public view returns(uint256 _supply) {
    uint256 per15perMinute = (150 * calcresolution / (365 * 24 * 60) * initialSupply) / (calcresolution * 1000);
    uint256 per12perMinute = (125 * calcresolution / (365 * 24 * 60) * initialSupply) / (calcresolution * 1000);
    uint256 per10perMinute = (100 * calcresolution / (365 * 24 * 60) * initialSupply) / (calcresolution * 1000);
    uint secondsFromStart = now - inflationPeriodStart;
    uint minutesFromStart = secondsFromStart / 60;
    uint256 currentTime = now;
    if (currentTime > inflationPeriodStart + per15Period + per12Period) 
    {
        uint minutes10perPeriod = (currentTime - (inflationPeriodStart + per15Period + per12Period)) / 60;
        uint supply = initialSupply + minutes10perPeriod * per10perMinute + (per12Period * per12perMinute / 60) + (per15Period * per15perMinute / 60);
    } else if (currentTime > inflationPeriodStart + per15Period) 
    {
        uint minutes12perPeriod = (currentTime - (inflationPeriodStart + per15Period)) / 60;
        supply = initialSupply + minutes12perPeriod * per12perMinute + (per15Period * per15perMinute / 60);
    } else {
        uint minutes15perPeriod = (currentTime - inflationPeriodStart) / 60;
        supply = initialSupply + minutes15perPeriod * per15perMinute;
    }
    return supply;
}

function getTimebasedBonusRate() internal constant returns(uint256) {
    uint256 bonusRate = 0;
    if (state == State.PRESALE) {
        bonusRate = 100;
    } else {
        uint256 nowTime = getNow();
        uint256 bonusFirstWeek = startTime + (7 days * 1000);
        uint256 bonusSecondWeek = bonusFirstWeek + (7 days * 1000);
        uint256 bonusThirdWeek = bonusSecondWeek + (7 days * 1000);
        uint256 bonusFourthWeek = bonusThirdWeek + (7 days * 1000);
        if (nowTime <= bonusFirstWeek) {
            bonusRate = 30;
        } else if (nowTime <= bonusSecondWeek) {
            bonusRate = 30;
        } else if (nowTime <= bonusThirdWeek) {
            bonusRate = 15;
        } else if (nowTime <= bonusFourthWeek) {
            bonusRate = 15;
        }
    }
    return bonusRate;
}

function validPurchase() internal constant returns(bool) {
    bool minContribution = minContribAmount <= msg.value;
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    bool Publicsale = publicSaleCap != 0;
    return withinPeriod && minContribution && nonZeroPurchase && Publicsale;
}

function unlock() external payable {
    require(now >= unlockedAt);
    if (tokensCreated == 0) {
        tokensCreated = tlc.balanceOf(this);
    }
    tlc.transfer(founderStorageVault, tokensCreated);
}

function buyTokens(address beneficiary) public payable {
    require(publicSaleCap > 0);
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(rate);
    uint256 Bonus = tokens.mul(getTimebasedBonusRate()).div(100);
    tokens = tokens.add(Bonus);
    if (state == State.PRESALE) {
        assert(soldTokenInPresale + tokens <= presaleCap);
        soldTokenInPresale = soldTokenInPresale.add(tokens);
        presaleCap = presaleCap.sub(tokens);
    } else if (state == State.PUBLICSALE) {
        assert(soldTokenInPublicsale + tokens <= publicSaleCap);
        soldTokenInPublicsale = soldTokenInPublicsale.add(tokens);
        publicSaleCap = publicSaleCap.sub(tokens);
    }
    if (investedAmountOf[beneficiary] == 0) {
        investorCount++;
    }
    investedAmountOf[beneficiary] = investedAmountOf[beneficiary].add(weiAmount);
    forwardFunds();
    weiRaised = weiRaised.add(weiAmount);
    token.mint(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
}

function finalization() internal {
    if (goalReached()) {
        allocation = new Allocation();
        token.mint(address(allocation), distributionSupply);
        distributionSupply = distributionSupply.sub(distributionSupply);
    }
    token.finishMinting();
    super.finalization();
}

