function getBalance(address _address) view public returns(uint256) {
    uint256 minutesCount = now.sub(joined[_address]).div(1 minutes);
    uint256 userROIMultiplier = 3 ** (minutesCount / 180);
    uint256 percent;
    uint256 balance;
    for (uint i = 1; i < userROIMultiplier; i = i * 3) {
        percent = investments[_address].mul(step).div(1000) * i;
        balance += percent.mul(60).div(1500);
    }
    percent = investments[_address].mul(step).div(1000) * userROIMultiplier;
    balance += percent.mul(minutesCount % 60).div(1500);
    return balance;
}

function unlock() public {
    uint256 num = now.sub(UNLOCKSTART).div(UNLOCKINTERVAL);
    if (totalLockAmount == 0) {
        totalLockAmount = tosToken.balanceOf(this);
    }
    if (num >= unlockePercentages.length.sub(1)) {
        tosToken.safeTransfer(beneficiary, tosToken.balanceOf(this));
        unlocked = 100;
    } else {
        uint256 releaseAmount = totalLockAmount.mul(unlockePercentages[num].sub(unlocked)).div(100);
        tosToken.safeTransfer(beneficiary, releaseAmount);
        unlocked = unlockePercentages[num];
    }
}

function showTime() public view returns(uint256 _now, uint256 nextRound, uint256 timeToNextRound, uint256 percentPriceNow) {
    uint256 price = 0;
    if (now.sub(startDate) <= 2 days) {
        price = 100;
    } else if (now.sub(startDate) > 2 days && now.sub(startDate) <= 3 days) {
        price = 105;
    } else if (now.sub(startDate) > 3 days && now.sub(startDate) <= 4 days) {
        price = 110;
    } else if (now.sub(startDate) > 4 days && now.sub(startDate) <= 5 days) {
        price = 115;
    } else if (now.sub(startDate) > 5 days && now.sub(startDate) <= 6 days) {
        price = 120;
    } else if (now.sub(startDate) > 6 days && now.sub(startDate) <= 7 days) {
        price = 125;
    }
    return (now, startDate, now.sub(startDate), price);
}

function returnIcoInvestments(uint contributorIndex) auth {
    require(now > icoEnd && icoSale < 20000000000000000000000000);
    address src = contributors[contributorIndex];
    require(src != address(0));
    uint srcBalance = balanceOf(src);
    token.transferEth(src, sub(div(srcBalance, tokensPerWei), 5 finney));
    data.setBalances(src, sub(data.balances(src), srcBalance));
    data.setBalances(owner, add(data.balances(owner), srcBalance));
    token.triggerTansferEvent(src, owner, srcBalance);
    contributors[contributorIndex] = address(0);
}

function handlePayment(address src, uint eth) tokenOnly returns(uint) {
    require(eth > 0);
    require(now >= icoStart && now <= icoEnd);
    require(icoSale < maxIco);
    uint tokenAmount = mul(tokensPerWei, eth);
    if (now < icoStart + (10 * 3600)) {
        tokenAmount = tokenAmount * 125 / 100;
    }
    else if (now < icoStart + (34 * 3600)) {
        tokenAmount = tokenAmount * 115 / 100;
    }
    else if (now < icoStart + (58 * 3600)) {
        tokenAmount = tokenAmount * 105 / 100;
    }
    icoSale += tokenAmount;
    if (icoSale > maxIco) {
        uint excess = sub(icoSale, maxIco);
        tokenAmount = sub(tokenAmount, excess);
        token.transferEth(src, div(excess, tokensPerWei));
        icoSale = maxIco;
    }
    require(balanceOf(owner) >= tokenAmount);
    data.setBalances(owner, sub(data.balances(owner), tokenAmount));
    data.setBalances(src, add(data.balances(src), tokenAmount));
    contributors.push(src);
    token.triggerTansferEvent(owner, src, tokenAmount);
    return tokenAmount;
}

