    participant[9].owner.transfer(uint256(SafeMath.mul(SafeMath.div(seatPrice, 100), SafeMath.div(100, SafeMath.div(200, 17)))));
    participant[10] = participant[9];
    participant[9] = participant[8];
    participant[8] = participant[7];
    participant[7] = participant[6];
    participant[6] = participant[5];
    participant[5] = participant[4];
    participant[4] = participant[3];
    participant[3] = participant[2];
    participant[2] = participant[1];
    participant[1] = Cost(msg.sender, seatPrice);
    Address.transfer(uint256(SafeMath.mul(SafeMath.div(seatPrice, 100), 15)));
    NewParticipant(msg.sender, seatPrice, SafeMath.mul(SafeMath.div(seatPrice, 100), 115));
    seatPrice = SafeMath.mul(SafeMath.div(seatPrice, 100), 115);
    msg.sender.transfer(excess);
}

function depositGHT(uint256 amount, address user) public whenNotPaused {
    GHT.transferFrom(user, address(this), amount);
    _GHTAmount[user] = _GHTAmount[user].add(amount);
    emit DepositGHT(user, amount);
}

function confirmedGHTWithdrawal(uint256 amount, address whitelistAddress, address to, uint256 update) public onlyMod whenNotPaused {
    if (update != 0)
        _GHTAmount[whitelistAddress] = update;
    GHT.transfer(to, amount);
    _GHTAmount[whitelistAddress] = _GHTAmount[whitelistAddress].sub(amount);
    assert(_GHTAmount[whitelistAddress] >= 0);
    emit GHTWithdrawalConfirmation(whitelistAddress, to, amount);
}

function lockB21EthFees(uint256 amount) external payable whenNotPaused returns(bool) {
    require(msg.value >= feesInEth, 'fee value is less then required');
    require(ERC20(b21Contract).balanceOf(msg.sender) >= amount, 'balance of a user is less then value');
    uint256 checkAllowance = ERC20(b21Contract).allowance(msg.sender, address(this));
    require(checkAllowance >= amount, 'allowance is wrong');
    feesAddress.transfer(msg.value);
    require(ERC20(b21Contract).transferFrom(msg.sender, address(this), amount), 'transfer From failed');
    emit LockTokens(msg.sender, address(this), amount);
    return true;
}

function isUnlocked() public view returns(bool) {
    return block.timestamp > unlockTime;
}

function SyncOldData(OldProductionBoiler oldBoiler, address[] accounts) external CreatorAble {
    require(!g_Synced);
    g_Synced = true;
    for (uint i = 0; i < accounts.length; i++) {
        address acc = accounts[i];
        for (uint idx = 0; idx < 3; idx++) {
            (uint expire, uint32[] memory chips) = oldBoiler.GetBoilerInfo(acc, idx);
            if (expire == 0) continue;
            g_Boilers[acc][idx].m_Expire = expire;
            g_Boilers[acc][idx].m_Chips = chips;
        }
    }
}

function IsBoilerExpire(address acc, uint idx) external view returns(bool) {
    Boiler storage obj = g_Boilers[acc][idx];
    return obj.m_Expire <= now;
}

function GenChipLevel_General(uint costAll, uint x, uint seed) internal view returns(uint8, uint) {
    uint8 outLv;
    uint random;
    uint baseR = BASERATIO * x / 100;
    (random, seed) = GenRandom(seed, BASERATIO);
    if (costAll <= CREATE_COST_FEW) {
        baseR /= 2;
        if (random <= BASERATIO - baseR) {
            outLv = 1;
        } else {
            outLv = 2;
        }
    } else if (costAll <= CREATE_COST_MANY) {
        baseR = baseR * 14 / 100;
        if (random <= BASERATIO * 70 / 100 - baseR) {
            outLv = 1;
        } else if (random <= BASERATIO * 95 / 100 - baseR / 4) {
            outLv = 2;
        } else {
            outLv = 3;
        }
    } else {
        baseR = baseR * 11 / 100;
        if (random <= BASERATIO * 50 / 100 - baseR) {
            outLv = 1;
        } else if (random <= BASERATIO * 90 / 100 - baseR / 3) {
            outLv = 2;
        } else {
            outLv = 3;
        }
    }
    return (outLv, seed);
}

function GenChipIndex(
    uint seed,
    uint8 level,
    uint[] extWeight3,
    uint[] extWeight4,
    uint[] extWeight5
) internal returns(uint32, uint) {
    uint random;
    (random, seed) = GenRandom(seed, 0);
    if (level == 1 || level == 2) {
        return (g_Main.GenChipByRandomWeight(random, level, extWeight3), seed);
    } else if (level == 3 || level == 4) {
        return (g_Main.GenChipByRandomWeight(random, level, extWeight4), seed);
    } else {
        return (g_Main.GenChipByRandomWeight(random, level, extWeight5), seed);
    }
}

function GenOutChipsNum(uint seed, uint costAll, uint x) internal view returns(uint, uint) {
    uint amount;
    uint random;
    uint baseR = BASERATIO * x / 100;
    (random, seed) = GenRandom(seed, BASERATIO);
    if (costAll <= CREATE_COST_FEW) {
        if (random <= BASERATIO - baseR) {
            amount = 3;
        } else {
            amount = 4;
        }
    } else {
        baseR /= 10;
        if (costAll <= CREATE_COST_MANY) {
            if (random <= BASERATIO * 7 / 10 - baseR * 2) {
                amount = 3;
            } else if (random <= BASERATIO * 3 / 10 + baseR) {
                amount = 4;
            } else {
                amount = 5;
            }
        } else {
            if (random <= BASERATIO * 7 / 10 - baseR) {
                amount = 4;
            } else {
                amount = 5;
            }
        }
    }
    return (amount, seed);
}

function GenChipsLevel(uint costAll, bool bUseX) internal view returns(uint8[] lvList, uint seed) {
    uint x = costAll - CREATE_COST_MIN;
    uint i;
    uint amount;
    (amount, seed) = GenOutChipsNum(0, costAll, x);
    lvList = new uint8[](amount);
    if (bUseX) {
        (lvList[0], seed) = GenChipLevel_Special(costAll, x, seed);
        for (i = 1; i < amount; i++) {
            (lvList[i], seed) = GenChipLevel_Extra(costAll, x, seed);
        }
    } else {
        for (i = 0; i < amount; i++) {
            (lvList[i], seed) = GenChipLevel_General(costAll, x, seed);
        }
    }
}

function GenChipLevel_Extra(uint costAll, uint x, uint seed) internal view returns(uint8, uint) {
    uint8 outLv;
    uint random;
    uint baseR = BASERATIO * x / 100;
    (random, seed) = GenRandom(seed, BASERATIO);
    if (costAll <= CREATE_COST_FEW) {
        baseR /= 4;
        if (random <= BASERATIO * 80 / 100 - baseR) {
            outLv = 1;
        } else if (random <= BASERATIO * 98 / 100 - baseR * 3 / 4) {
            outLv = 2;
        } else if (random <= BASERATIO - baseR / 4) {
            outLv = 3;
        } else {
            outLv = 4;
        }
    } else if (costAll <= CREATE_COST_MANY) {
        baseR /= 10;
        if (random <= BASERATIO * 55 / 100 - baseR) {
            outLv = 1;
        } else if (random <= BASERATIO * 85 / 100 - baseR * 4 / 5) {
            outLv = 2;
        } else if (random <= BASERATIO * 95 / 100 - baseR * 2 / 5) {
            outLv = 3;
        } else if (random <= BASERATIO - baseR / 5) {
            outLv = 4;
        } else {
            outLv = 5;
        }
    } else {
        baseR /= 10;
        if (random <= BASERATIO * 30 / 100 - baseR / 2) {
            outLv = 1;
        } else if (random <= BASERATIO * 75 / 100 - baseR) {
            outLv = 2;
        } else if (random <= BASERATIO * 88 / 100 - baseR * 4 / 7) {
            outLv = 3;
        } else if (random <= BASERATIO * 97 / 100 - baseR / 7) {
            outLv = 4;
        } else {
            outLv = 5;
        }
    }
    return (outLv, seed);
}

function IsBoilerValid(uint idx) internal view returns(bool) {
    if (idx != BOILER_FREE_IDX) {
        uint32 iStuff = GetPermissionIdx(idx);
        if (iStuff == 0) return false;
        if (g_Main.GetTempStuffExpire(msg.sender, iStuff) < now) return false;
    }
    return g_Boilers.IsBoilerValid(msg.sender, idx);
}

function Accelerate(uint idx) external payable {
    (uint expire, ) = g_Boilers.GetBoilerInfo(msg.sender, idx);
    require(expire > now);
    uint remain = expire - now;
    uint num = remain / ACCELERATE_UNITTIME;
    if (remain != num * ACCELERATE_UNITTIME) {
        num++;
    }
    uint fee = num * ACCELERATE_UNITFEE;
    require(fee == msg.value);
    AddBonus(BONUS_PERCENT_ACCELERATE);
    CollectChips(idx);
}

function GenChipLevel_Special(uint costAll, uint x, uint seed) internal view returns(uint8, uint) {
    uint8 outLv;
    uint random;
    if (costAll <= CREATE_COST_FEW) {
        outLv = 3;
    } else {
        (random, seed) = GenRandom(seed, BASERATIO);
        uint baseR = BASERATIO * x / 100;
        if (costAll <= CREATE_COST_MANY) {
            baseR /= 10;
            if (random <= BASERATIO * 80 / 100 - baseR) {
                outLv = 3;
            } else if (random <= BASERATIO - baseR / 4) {
                outLv = 4;
            } else {
                outLv = 5;
            }
        } else {
            baseR /= 10;
            if (random <= BASERATIO * 70 / 100 - baseR) {
                outLv = 3;
            } else if (random <= BASERATIO * 95 / 100 - baseR / 5) {
                outLv = 4;
            } else {
                outLv = 5;
            }
        }
    }
    return (outLv, seed);
}

function CreateChips(uint costAll, uint costA, uint costB, uint costC, bool bUseX) internal returns(uint32[]) {
    (uint[] memory ext3,
        uint[] memory ext4,
        uint[] memory ext5
    ) = GenExtWeightList(costA, costB, costC);
    (uint8[] memory lvList, uint seed) = GenChipsLevel(costAll, bUseX);
    uint32[] memory chips = new uint32[](lvList.length);
    for (uint i = 0; i < lvList.length; i++) {
        uint8 chipLv = lvList[i];
        (chips[i], seed) = GenChipIndex(seed, chipLv, ext3, ext4, ext5);
    }
    return chips;
}

function investInternal(address receiver, uint128 customerId) stopInEmergency private {
    if (getState() == State.PreFunding) {
        if (!earlyParticipantWhitelist[receiver]) {
            throw;
        }
    } else if (getState() == State.Funding) {} else {
        throw;
    }
    uint weiAmount = msg.value;
    uint tokenAmount = pricingStrategy.calculatePrice(weiAmount, weiRaised, tokensSold, msg.sender, token.decimals());
    if (tokenAmount == 0) {
        throw;
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = safeAdd(investedAmountOf[receiver], weiAmount);
    tokenAmountOf[receiver] = safeAdd(tokenAmountOf[receiver], tokenAmount);
    weiRaised = safeAdd(weiRaised, weiAmount);
    tokensSold = safeAdd(tokensSold, tokenAmount);
    if (isBreakingCap(weiAmount, tokenAmount, weiRaised, tokensSold)) {
        throw;
    }
    assignTokens(receiver, tokenAmount);
    if (!multisigWallet.send(weiAmount)) throw;
    Invested(receiver, weiAmount, tokenAmount, customerId);
}

function preallocate(address receiver, uint fullTokens, uint weiPrice) public onlyOwner {
    uint tokenAmount = fullTokens * 10 ** token.decimals();
    uint weiAmount = weiPrice * fullTokens;
    weiRaised = safeAdd(weiRaised, weiAmount);
    tokensSold = safeAdd(tokensSold, tokenAmount);
    investedAmountOf[receiver] = safeAdd(investedAmountOf[receiver], weiAmount);
    tokenAmountOf[receiver] = safeAdd(tokenAmountOf[receiver], tokenAmount);
    assignTokens(receiver, tokenAmount);
    Invested(receiver, weiAmount, tokenAmount, 0);
}

function finalizeCrowdsale() {
    if (msg.sender != address(crowdsale)) {
        throw;
    }
    uint tokensSold = crowdsale.tokensSold();
    for (uint i = 0; i < totalMembers; i++) {
        allocatedBonus = safeMul(tokensSold, bonusOf[teamAddresses[i]]) / 10000;
        token.mint(teamAddresses[i], allocatedBonus);
    }
    token.releaseTokenTransfer();
}

function confirmMintRequest(bytes32 requestHash) external onlyCustodian returns(bool) {
    uint nonce;
    Request memory request;
    (nonce, request) = getPendingMintRequest(requestHash);
    mintRequests[nonce].status = RequestStatus.APPROVED;
    require(controller.mint(request.requester, request.amount), "mint failed");
    emit MintConfirmed(
        request.nonce,
        request.requester,
        request.amount,
        request.depositAddress,
        request.txid,
        request.timestamp,
        requestHash
    );
    return true;
}

function validatePendingRequest(Request memory request, bytes32 requestHash) internal pure {
    require(request.status == RequestStatus.PENDING, "request is not pending");
    require(requestHash == calcRequestHash(request), "given request hash does not match a pending request");
}

function getStatusString(RequestStatus status) internal pure returns(string memory) {
    if (status == RequestStatus.PENDING) {
        return "pending";
    } else if (status == RequestStatus.CANCELED) {
        return "canceled";
    } else if (status == RequestStatus.APPROVED) {
        return "approved";
    } else if (status == RequestStatus.REJECTED) {
        return "rejected";
    } else {
        return "unknown";
    }
}

function cancelMintRequest(bytes32 requestHash) external onlyBroker returns(bool) {
    uint nonce;
    Request memory request;
    (nonce, request) = getPendingMintRequest(requestHash);
    require(msg.sender == request.requester, "cancel sender is different than pending request initiator");
    mintRequests[nonce].status = RequestStatus.CANCELED;
    emit MintRequestCancel(nonce, msg.sender, requestHash);
    return true;
}

function _saleTokens() internal {
    require(msg.value >= 10 ** 16, "Minimum value is 0.01 ether");
    require(hardCapCrowdSale >= currentFunds.add(msg.value), "Upper limit on fund raising exceeded");
    require(msg.sender != address(0), "Address sender is empty");
    require(wallet != address(0), "Enter address profit wallet");
    require(isSaleActive, "Set saleStatus in true");
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(tokenSaleRate);
    token.mint(msg.sender, tokens);
    emit TokenSale(msg.sender, weiAmount, tokens);
    currentFunds = currentFunds.add(msg.value);
    wallet.transfer(msg.value);
}

function _CalcDiv() internal {
    uint256 myAround = 1 ether;
    uint256 i;
    uint256 k;
    address invAddress;
    receivedDividends = receivedDividends.add(msg.value);
    if (receivedDividends >= crowdSaleContract.hardCapDividends()) {
        uint256 lengthArrInvesotrs = token.getInvestorsCount();
        crowdSaleContract.lockTransfer(true);
        k = receivedDividends.mul(myAround).div(token.totalSupply());
        uint256 myProfit;
        for (i = 0; i < lengthArrInvesotrs; i++) {
            invAddress = token.getInvestorAddress(i);
            myProfit = token.balanceOf(invAddress).mul(k).div(myAround);
            divmap[invAddress] = divmap[invAddress].add(myProfit);
        }
        crowdSaleContract.lockTransfer(false);
        receivedDividends = 0;
    }
}

function Pay() public {
    uint256 dividends = divmap[msg.sender];
    require(dividends > 0);
    require(dividends <= address(this).balance);
    divmap[msg.sender] = 0;
    msg.sender.transfer(dividends);
    emit PayDividends(msg.sender, dividends);
}

function stake(uint256 _amount) public payable {
    require(paused == false, "E09");
    require(block.timestamp >= stakingStart, "E07");
    StakerInfo storage user = stakerInfo[msg.sender];
    require(user.amount.add(_amount) >= minimumStake, "E01");
    require(dnxcToken.transferFrom(msg.sender, address(this), _amount), "E02");
    if (user.startStakeTime == 0) {
        require(msg.value >= stakingFee, "E04");
        user.startStakeTime = block.timestamp;
    }
    user.amount = user.amount.add(_amount);
    user.amounts.push(user.amount);
    user.times.push(block.timestamp);
}

function unstake(uint256 _amount) public {
    require(block.timestamp >= stakingEnd || block.timestamp <= stakingClosed, "E08");
    StakerInfo storage user = stakerInfo[msg.sender];
    require(user.amount > 0, "E06");
    if (_amount > user.amount) {
        _amount = user.amount;
    }
    dnxcToken.transfer(
        msg.sender,
        _amount
    );
    user.amount = user.amount.sub(_amount);
    user.amounts.push(user.amount);
    user.times.push(block.timestamp);
}

function claim() public {
    require(owedBalance(msg.sender) > 0, "nothing to claim");
    require(block.timestamp > stakes[msg.sender].payday.sub(earlyExit), "too early");
    uint256 owed = stakes[msg.sender].reward.add(stakes[msg.sender].initial);
    totalStaked = totalStaked.sub(stakes[msg.sender].initial);
    totalRewards = totalRewards.sub(stakes[msg.sender].reward);
    stakes[msg.sender].initial = 0;
    stakes[msg.sender].reward = 0;
    stakes[msg.sender].payday = 0;
    stakes[msg.sender].startday = 0;
    require(kp4r.transfer(msg.sender, owed), "transfer failed");
}

function stake(uint256 _amount, uint256 _days) public {
    require(_days > minDays, "less than minimum staking period");
    require(_days < maxDays, "more than maximum staking period");
    require(stakes[msg.sender].payday == 0, "already staked");
    require(_amount > 100, "amount to small");
    require(!isClosed, "staking is closed");
    uint256 _reward = calculateReward(_amount, _days);
    require(kp4r.balanceOf(address(this)) > totalOwedValue().add(_reward).add(_amount), "insufficient contract bal");
    require(kp4r.transferFrom(msg.sender, address(this), _amount), "transfer failed");
    stakes[msg.sender].payday = block.timestamp.add(_days * (1 days));
    stakes[msg.sender].reward = _reward;
    stakes[msg.sender].startday = block.timestamp;
    stakes[msg.sender].initial = _amount;
    totalStaked = totalStaked.add(_amount);
    totalRewards = totalRewards.add(_reward);
}

function cashback() internal fromPartner {
    uint amountPartner = msg.value.mul(cashbackPartner).div(100);
    transfer(msg.data.toAddr(), amountPartner);
    uint amountInvestor = msg.value.mul(cashbackInvestor).div(100);
    transfer(msg.sender, amountInvestor);
    totalPaid = totalPaid.add(amountPartner).add(amountInvestor);
}

