function processBuy(address _to, uint256 _value) internal returns(bool) {
    require(!halted);
    require(_value > 0);
    uint tokens = _value / price();
    require(balances[owner] > tokens);
    if (preIco) {
        tokens = tokens + (tokens / 2);
    }
    if (preIco) {
        require(safeAdd(presaleTokenSupply, tokens) < preIcoCap);
    } else {
        require(safeAdd(presaleTokenSupply, tokens) < safeSub(icoCap, preIcoTokenSupply));
    }
    founder.transfer(_value);
    balances[_to] = safeAdd(balances[_to], tokens);
    balances[owner] = safeSub(balances[owner], tokens);
    if (preIco) {
        preIcoTokenSupply = safeAdd(preIcoTokenSupply, tokens);
    }
    presaleTokenSupply = safeAdd(presaleTokenSupply, tokens);
    presaleEtherRaised = safeAdd(presaleEtherRaised, _value);
    Buy(_to, _value, tokens);
    TokensSent(_to, tokens);
    ContributionReceived(_to, _value);
    Transfer(owner, _to, tokens);
    return true;
}

function() payable {
    if (msg.value < 0) throw;
    if (this.balance > 47000000000000000000000) throw; 
    if (now > 1505865600) throw; 
    operation_address[operation] = msg.sender;
    operation_amount[operation] = msg.value;
    operation = operation.add(1);
}

function executeProposal(uint proposalNumber, bytes transactionBytecode) public {
    Proposal storage p = proposals[proposalNumber];
    require(now > p.minExecutionDate 
        &&
        !p.executed 
        &&
        p.proposalHash == keccak256(p.recipient, p.amount, transactionBytecode)); 
    uint quorum = 0;
    uint yea = 0;
    uint nay = 0;
    for (uint i = 0; i < p.votes.length; ++i) {
        Vote storage v = p.votes[i];
        uint voteWeight = sharesTokenAddress.balanceOf(v.voter);
        quorum += voteWeight;
        if (v.inSupport) {
            yea += voteWeight;
        } else {
            nay += voteWeight;
        }
    }
    require(quorum >= minimumQuorum); 
    if (yea > nay) {
        p.executed = true;
        require(p.recipient.call.value(p.amount)(transactionBytecode));
        p.proposalPassed = true;
    } else {
        p.proposalPassed = false;
    }
    ProposalTallied(proposalNumber, yea - nay, quorum, p.proposalPassed);
}

function vote(
    uint proposalNumber,
    bool supportsProposal
)
onlyShareholders public
returns(uint voteID) {
    Proposal storage p = proposals[proposalNumber];
    require(p.voted[msg.sender] != true);
    voteID = p.votes.length++;
    p.votes[voteID] = Vote({
        inSupport: supportsProposal,
        voter: msg.sender
    });
    p.voted[msg.sender] = true;
    p.numberOfVotes = voteID + 1;
    Voted(proposalNumber, supportsProposal, msg.sender);
    return voteID;
}

function newProposal(
    address beneficiary,
    uint weiAmount,
    string jobDescription,
    bytes transactionBytecode
)
onlyShareholders public
returns(uint proposalID) {
    proposalID = proposals.length++;
    Proposal storage p = proposals[proposalID];
    p.recipient = beneficiary;
    p.amount = weiAmount;
    p.description = jobDescription;
    p.proposalHash = keccak256(beneficiary, weiAmount, transactionBytecode);
    p.minExecutionDate = now + debatingPeriodInMinutes * 1 minutes;
    p.executed = false;
    p.proposalPassed = false;
    p.numberOfVotes = 0;
    ProposalAdded(proposalID, beneficiary, weiAmount, jobDescription);
    numProposals = proposalID + 1;
    return proposalID;
}

function newProposalInEther(
    address beneficiary,
    uint etherAmount,
    string jobDescription,
    bytes transactionBytecode
)
onlyShareholders public
returns(uint proposalID) {
    return newProposal(beneficiary, etherAmount * 1 ether, jobDescription, transactionBytecode);
}

function transfer(address to, uint256 value) public returns(bool) {
    require(msg.sender != to);
    require(value > 0);
    require(balances[msg.sender] >= value);
    require(frozenTokens[msg.sender].isFrozenAll != true);
    if (frozenTokens[msg.sender].unfrozenDate > now) {
        require(balances[msg.sender] - value >= frozenTokens[msg.sender].amount);
    }
    balances[msg.sender] -= value;
    balances[to] += value;
    Transfer(msg.sender, to, value);
    return true;
}

function freezeAccountToken(address target, uint256 amount, uint256 date) onlyOwner public {
