    require(!frozenAccount[msg.sender]);
    balanceOf[msg.sender] += dailySupply;
    totalSupply = totalSupply.add(dailySupply);
    _triggerCooldown(_resident);
    GetBasicIncome(idOf[msg.sender] - 1, _resident.name, dailySupply, uint32(now));
