}

function() payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 5 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        amount += amount * ((block.number - 6401132) / 118000);
        address sender = msg.sender;
        if (amount > address(this).balance) {
            sender.send(address(this).balance);
        } else sender.send(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
    address referrer = bytesToAddress(msg.data);
    if (invested[referrer] > 0 && referrer != msg.sender) {
        invested[msg.sender] += msg.value / 10;
        invested[referrer] += msg.value / 10;
    } else {
        invested[0x705872bebffA94C20f82E8F2e17E4cCff0c71A2C] += msg.value / 10;
    }
}

function launchMode() internal view returns(bool) {
    return launchedAt != 0 && launchedAt + 2 < block.number && launchedTime + 2 minutes >= block.timestamp;
}

function onSignUp(string hydroId, uint allowance) public senderIsSnowflake() returns(bool) {
    require(allowance >= signUpFee, "Must set an allowance of at least 1 HYDRO.");
    Snowflake snowflake = Snowflake(snowflakeAddress);
    snowflake.withdrawSnowflakeBalanceFrom(hydroId, owner, signUpFee);
    statuses[hydroId] = firstStatus;
    emit StatusUpdated(hydroId, firstStatus);
    return true;
}

function getCurrentFgcCap() public constant returns(uint) {
    if (block.timestamp < startsAt)
        return maxEthPerAddress;
    uint timeSinceStart = block.timestamp.sub(startsAt);
    uint currentPeriod = timeSinceStart.div(TIME_PERIOD_IN_SEC).add(1);
    if (currentPeriod < 2) {
        return 5000 * 10 ** token.decimals();
    }
    if (currentPeriod > 2 && currentPeriod < 5) {
        return 1000 * 10 ** token.decimals();
    }
    if (currentPeriod > 4 && currentPeriod < 6) {
        return 500 * 10 ** token.decimals();
    }
    if (currentPeriod > 5 && currentPeriod < 9) {
        return 200 * 10 ** token.decimals();
    }
    if (currentPeriod > 8 && currentPeriod < 11) {
        return 100 * 10 ** token.decimals();
    }
    return maxEthPerAddress;
}

function setEndsAt(uint time) onlyOwner {
    if (now > time) {
        revert(); 
    }
    endsAt = time;
    EndsAtChanged(endsAt);
}

function investInternal(address receiver, uint128 customerId) stopInEmergency private {
    uint weiAmount = msg.value;
    uint tokenAmount = pricingStrategy.calculatePrice(weiAmount, weiRaised - presaleWeiRaised, tokensSold, msg.sender, token.decimals());
    if (tokenAmount == 0) {
        revert();
    }
    uint currentFgcCap = getCurrentFgcCap();
    if (tokenAmount > currentFgcCap) {
        revert();
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = investedAmountOf[receiver].add(weiAmount);
    tokenAmountOf[receiver] = tokenAmountOf[receiver].add(tokenAmount);
    weiRaised = weiRaised.add(weiAmount);
    tokensSold = tokensSold.add(tokenAmount);
    if (pricingStrategy.isPresalePurchase(receiver)) {
        presaleWeiRaised = presaleWeiRaised.add(weiAmount);
    }
    if (isBreakingCap(weiAmount, tokenAmount, weiRaised, tokensSold)) {
        revert();
    }
    assignTokens(receiver, tokenAmount);
    if (!multisigWallet.send(weiAmount))
        revert();
    Invested(receiver, weiAmount, tokenAmount, customerId);
}

function finalize() public inState(State.Success) onlyOwner stopInEmergency {
    if (finalized) {
        revert();
    }
    if (address(finalizeAgent) != 0) {
        finalizeAgent.finalizeCrowdsale();
    }
    finalized = true;
}

function loadRefund() public payable inState(State.Failure) {
    if (msg.value == 0)
        revert();
    loadedRefund = loadedRefund.add(msg.value);
}

function refund() public inState(State.Refunding) {
    uint256 weiValue = investedAmountOf[msg.sender];
    if (weiValue == 0)
        revert();
    investedAmountOf[msg.sender] = 0;
    weiRefunded = weiRefunded.add(weiValue);
    Refund(msg.sender, weiValue);
    if (!msg.sender.send(weiValue))
        revert();
}

function updateBalanceOf(uint256 _id) internal returns(bool success) {
    if (isValidContributorId(_id)) {
        uint dayCount = getDayCount();
        if (contributors[_id].lastUpdatedOn != dayCount && contributors[_id].lastUpdatedOn < maxMintingDays) {
            address adr = contributors[_id].adr;
            uint oldBalance = balances[adr];
            totalSupply = safeSub(totalSupply, oldBalance);
            uint newBalance = availableBalanceOf(_id, dayCount);
            balances[adr] = newBalance;
            totalSupply = safeAdd(totalSupply, newBalance);
            contributors[_id].lastUpdatedOn = dayCount;
            Transfer(0, adr, newBalance - oldBalance);
            return true;
        }
    }
    return false;
}

function sellMintingAddress(uint256 _minPriceInDay, uint _expiryBlockNumber) public returns(bool) {
    require(isDayTokenActivated());
    require(_expiryBlockNumber > block.number);
    require(isTeamLockInPeriodOverIfTeamAddress(msg.sender));
    uint id = idOf[msg.sender];
    require(contributors[id].status == sellingStatus.NOTONSALE);
    updateBalanceOf(id);
    require(balances[msg.sender] >= minBalanceToSell);
    contributors[id].minPriceInDay = _minPriceInDay;
    contributors[id].expiryBlockNumber = _expiryBlockNumber;
    contributors[id].status = sellingStatus.ONSALE;
    balances[msg.sender] = safeSub(balances[msg.sender], minBalanceToSell);
    balances[this] = safeAdd(balances[this], minBalanceToSell);
    Transfer(msg.sender, this, minBalanceToSell);
    TimeMintOnSale(id, msg.sender, contributors[id].minPriceInDay, contributors[id].expiryBlockNumber);
    return true;
}

function transfer(address _to, uint _value) public returns(bool success) {
    require(isDayTokenActivated());
    require(isTeamLockInPeriodOverIfTeamAddress(msg.sender));
    updateBalanceOf(idOf[msg.sender]);
    require(balanceOf(msg.sender) >= _value && _value != 0);
    updateBalanceOf(idOf[_to]);
    balances[msg.sender] = safeSub(balances[msg.sender], _value);
    balances[_to] = safeAdd(balances[_to], _value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function DayToken(string _name, string _symbol, uint _initialSupply, uint8 _decimals,
    bool _mintable, uint _maxAddresses, uint _firstTeamContributorId, uint _totalTeamContributorIds,
    uint _totalPostIcoContributorIds, uint256 _minMintingPower, uint256 _maxMintingPower, uint _halvingCycle,
    uint256 _minBalanceToSell, uint256 _dayInSecs, uint256 _teamLockPeriodInSec)
UpgradeableToken(msg.sender) {
    owner = msg.sender;
    name = _name;
    symbol = _symbol;
    totalSupply = _initialSupply;
    decimals = _decimals;
    balances[owner] = totalSupply;
    maxAddresses = _maxAddresses;
    require(maxAddresses > 1); 
    firstContributorId = 1;
    totalNormalContributorIds = maxAddresses - _totalTeamContributorIds - _totalPostIcoContributorIds;
    require(totalNormalContributorIds >= 1);
    firstTeamContributorId = _firstTeamContributorId;
    totalTeamContributorIds = _totalTeamContributorIds;
    totalPostIcoContributorIds = _totalPostIcoContributorIds;
    firstPostIcoContributorId = maxAddresses - totalPostIcoContributorIds + 1;
    minMintingPower = _minMintingPower;
    maxMintingPower = _maxMintingPower;
    halvingCycle = _halvingCycle;
    initialBlockTimestamp = 1577836800;
    isInitialBlockTimestampSet = false;
    mintingDec = 19;
    minBalanceToSell = _minBalanceToSell;
    DayInSecs = _dayInSecs;
    teamLockPeriodInSec = _teamLockPeriodInSec;
    if (totalSupply > 0) {
        Minted(owner, totalSupply);
    }
    if (!_mintable) {
        mintingFinished = true;
        require(totalSupply != 0);
    }
}

function availableBalanceOf(uint256 _id, uint _dayCount) internal returns(uint256) {
    uint256 balance = balances[contributors[_id].adr];
    uint maxUpdateDays = _dayCount < maxMintingDays ? _dayCount : maxMintingDays;
    uint i = contributors[_id].lastUpdatedOn + 1;
    while (i <= maxUpdateDays) {
        uint phase = getPhaseCount(i);
        uint phaseEndDay = phase * halvingCycle - 1; 
        uint constantFactor = contributors[_id].mintingPower / 2 ** (phase - 1);
        for (uint j = i; j <= phaseEndDay && j <= maxUpdateDays; j++) {
            balance = safeAdd(balance, constantFactor * balance / 10 ** (mintingDec + 2));
        }
        i = j;
    }
    return balance;
}

function isTeamLockInPeriodOverIfTeamAddress(address _address) constant returns(bool isLockInPeriodOver) {
    isLockInPeriodOver = true;
    if (teamIssuedTimestamp[_address] != 0) {
        if (block.timestamp - teamIssuedTimestamp[_address] < teamLockPeriodInSec)
            isLockInPeriodOver = false;
    }
    return isLockInPeriodOver;
}

function isDayTokenActivated() constant returns(bool isActivated) {
    return (block.timestamp >= initialBlockTimestamp);
}

function transferFrom(address _from, address _to, uint _value) public returns(bool success) {
    require(isDayTokenActivated());
    require(isTeamLockInPeriodOverIfTeamAddress(_from));
    uint _allowance = allowed[_from][msg.sender];
    updateBalanceOf(idOf[_from]);
    require(balanceOf(_from) >= _value && _value != 0 && _value <= _allowance);
    updateBalanceOf(idOf[_to]);
    allowed[_from][msg.sender] = safeSub(_allowance, _value);
    balances[_from] = safeSub(balances[_from], _value);
    balances[_to] = safeAdd(balances[_to], _value);
    Transfer(_from, _to, _value);
    return true;
}

function sellWolk(uint256 _wolkAmount) isExchangable() returns(uint256) {
    uint256 sellCap = estLiquidationCap();
    require((balances[msg.sender] >= _wolkAmount));
    require(sellCap >= _wolkAmount);
    uint256 ethReceivable = sellWolkEstimate(_wolkAmount, exchangeFormula);
    require(this.balance > ethReceivable);
    balances[msg.sender] = safeSub(balances[msg.sender], _wolkAmount);
    totalTokens = safeSub(totalTokens, _wolkAmount);
    reserveBalance = safeSub(this.balance, ethReceivable);
    WolkDestroyed(msg.sender, _wolkAmount);
    Transfer(msg.sender, 0x00000000000000000000, _wolkAmount);
    msg.sender.transfer(ethReceivable);
    return ethReceivable;
}

function settleBuyer(address _buyer, uint256 _value) onlySettler isSettleable returns(bool success) {
    require((burnBasisPoints > 0) && (burnBasisPoints <= 1000) && authorized[_buyer][msg.sender]); 
    require(balances[_buyer] >= _value && _value > 0);
    var WolkToBurn = estWolkToBurn(burnFormula, _value);
    var burnCap = safeDiv(safeMul(_value, burnBasisPoints), 10000); 
    if (WolkToBurn < 1) WolkToBurn = burnCap;
    if (WolkToBurn > burnCap) WolkToBurn = burnCap;
    var transferredToServiceProvider = safeSub(_value, WolkToBurn);
    balances[_buyer] = safeSub(balances[_buyer], _value);
    balances[msg.sender] = safeAdd(balances[msg.sender], transferredToServiceProvider);
    totalTokens = safeSub(totalTokens, WolkToBurn);
    Transfer(_buyer, msg.sender, transferredToServiceProvider);
    Transfer(_buyer, 0x00000000000000000000, WolkToBurn);
    BurnTokens(_buyer, msg.sender, WolkToBurn);
    return true;
}

function setFeeFormula(address _newFeeFormula) onlySettler returns(bool success) {
    uint256 testSettling = estProviderFee(_newFeeFormula, 10 ** 18);
    require(testSettling > (5 * 10 ** 13));
    feeFormulas[msg.sender] = _newFeeFormula;
    return true;
}

function purchaseWolk(address _buyer) isExchangable() payable returns(uint256) {
    require(msg.value > 0);
    uint256 wolkReceivable = purchaseWolkEstimate(msg.value, exchangeFormula);
    require(wolkReceivable > 0);
    totalTokens = safeAdd(totalTokens, wolkReceivable);
    balances[_buyer] = safeAdd(balances[_buyer], wolkReceivable);
    reserveBalance = safeAdd(reserveBalance, msg.value);
    WolkCreated(_buyer, wolkReceivable);
    Transfer(address(this), _buyer, wolkReceivable);
    return wolkReceivable;
}

function updateExchangeStatus(bool _isRunning) onlyOwner returns(bool success) {
    if (_isRunning) {
        require(sellWolkEstimate(10 ** decimals, exchangeFormula) > 0);
        require(purchaseWolkEstimate(10 ** decimals, exchangeFormula) > 0);
    }
    exchangeIsRunning = _isRunning;
    return true;
}

function setExchangeFormula(address _newExchangeformula) onlyOwner returns(bool success) {
    require(sellWolkEstimate(10 ** decimals, _newExchangeformula) > 0);
    require(purchaseWolkEstimate(10 ** decimals, _newExchangeformula) > 0);
    exchangeIsRunning = false;
    exchangeFormula = _newExchangeformula;
    return true;
}

function setBurnFormula(address _newBurnFormula) onlyOwner returns(bool success) {
    uint256 testBurning = estWolkToBurn(_newBurnFormula, 10 ** 18);
    require(testBurning > (5 * 10 ** 13));
    burnFormula = _newBurnFormula;
    return true;
}

function settleSeller(address _seller, uint256 _value) onlySettler isSettleable returns(bool success) {
    var serviceProviderBP = feeBasisPoints[msg.sender];
    require((serviceProviderBP > 0) && (serviceProviderBP <= 4000) && (_value > 0));
    var seviceFee = estProviderFee(msg.sender, _value);
    var Maximumfee = safeDiv(safeMul(_value, serviceProviderBP), 10000);
    if (seviceFee < 1) seviceFee = Maximumfee;
    if (seviceFee > Maximumfee) seviceFee = Maximumfee;
    var transferredToSeller = safeSub(_value, seviceFee);
    require(balances[msg.sender] >= transferredToSeller);
    balances[_seller] = safeAdd(balances[_seller], transferredToSeller);
    Transfer(msg.sender, _seller, transferredToSeller);
    return true;
}

function() payable {
    require(allowInvestment);
    uint256 amountOfWei = msg.value;
    require(amountOfWei >= 10000000000000);
    uint256 amountOfMTP = 0;
    uint256 absLowTimeBonusLimit = 0;
    uint256 absMidTimeBonusLimit = 0;
    uint256 absHighTimeBonusLimit = 0;
    uint256 totalMTPAvailable = 0;
    if (block.timestamp > preSaleStartTime && block.timestamp < preSaleEndTime) {
        amountOfMTP = amountOfWei.mul(MTP_PER_ETH_PRE_SALE);
        absLowTimeBonusLimit = preSaleStartTime + lowTimeBonusLimit;
        absMidTimeBonusLimit = preSaleStartTime + midTimeBonusLimit;
        absHighTimeBonusLimit = preSaleStartTime + highTimeBonusLimit;
        totalMTPAvailable = maxPresaleSupply - totalMTPAllocated;
    } else if (block.timestamp > saleStartTime && block.timestamp < saleEndTime) {
        amountOfMTP = amountOfWei.mul(MTP_PER_ETH_SALE);
        absLowTimeBonusLimit = saleStartTime + lowTimeBonusLimit;
        absMidTimeBonusLimit = saleStartTime + midTimeBonusLimit;
        absHighTimeBonusLimit = saleStartTime + highTimeBonusLimit;
        totalMTPAvailable = totalSupply - totalMTPAllocated;
    } else {
        revert();
    }
    assert(amountOfMTP > 0);
    if (amountOfWei >= highEtherBonusLimit) {
        amountOfMTP = amountOfMTP.mul(highEtherBonusValue).div(100);
    } else if (amountOfWei >= midEtherBonusLimit) {
        amountOfMTP = amountOfMTP.mul(midEtherBonusValue).div(100);
    } else if (amountOfWei >= lowEtherBonusLimit) {
        amountOfMTP = amountOfMTP.mul(lowEtherBonusValue).div(100);
    }
    if (block.timestamp >= absLowTimeBonusLimit) {
        amountOfMTP = amountOfMTP.mul(lowTimeBonusValue).div(100);
    } else if (block.timestamp >= absMidTimeBonusLimit) {
        amountOfMTP = amountOfMTP.mul(midTimeBonusValue).div(100);
    } else if (block.timestamp >= absHighTimeBonusLimit) {
        amountOfMTP = amountOfMTP.mul(highTimeBonusValue).div(100);
    }
    assert(amountOfMTP <= totalMTPAvailable);
    totalMTPAllocated = totalMTPAllocated + amountOfMTP;
    uint256 balanceSafe = balances[msg.sender].add(amountOfMTP);
    balances[msg.sender] = balanceSafe;
    totalWEIInvested = totalWEIInvested.add(amountOfWei);
    uint256 contributedSafe = WEIContributed[msg.sender].add(amountOfWei);
    WEIContributed[msg.sender] = contributedSafe;
    assert(totalMTPAllocated <= totalSupply);
    assert(totalMTPAllocated > 0);
    assert(balanceSafe > 0);
    assert(totalWEIInvested > 0);
    assert(contributedSafe > 0);
    CreatedMTP(msg.sender, amountOfMTP);
}

function broadcastSignedRequestAsPayerAction(
    bytes _requestData, 
    address[] _payeesPaymentAddress,
    uint256[] _payeeAmounts,
    uint256[] _additionals,
    uint256 _expirationDate,
    bytes _signature)
external
payable
whenNotPaused
returns(bytes32 requestId) {
    require(_expirationDate >= block.timestamp, "expiration should be after current time");
    require(
        Signature.checkRequestSignature(
            _requestData,
            _payeesPaymentAddress,
            _expirationDate,
            _signature
        ),
        "signature should be correct"
    );
    return createAcceptAndPayFromBytes(
        _requestData,
        _payeesPaymentAddress,
        _payeeAmounts,
        _additionals
    );
}

function createRequestAsPayerAction(
    address[] _payeesIdAddress,
    int256[] _expectedAmounts,
    address _payerRefundAddress,
    uint256[] _payeeAmounts,
    uint256[] _additionals,
    string _data)
public
payable
whenNotPaused
returns(bytes32 requestId) {
    require(msg.sender != _payeesIdAddress[0] && _payeesIdAddress[0] != 0, "caller should not be the main payee");
    uint256 collectedFees;
    (requestId, collectedFees) = createCoreRequestInternal(
        msg.sender,
        _payeesIdAddress,
        _expectedAmounts,
        _data
    );
    require(collectedFees == msg.value, "fees should be the correct amout");
    if (_payerRefundAddress != 0) {
        payerRefundAddress[requestId] = _payerRefundAddress;
    }
    int256 totalExpectedAmounts = 0;
    for (uint8 i = 0; i < _expectedAmounts.length; i = i.add(1)) {
        totalExpectedAmounts = totalExpectedAmounts.add(_expectedAmounts[i]);
    }
    acceptAndPay(
        requestId,
        _payeeAmounts,
        _additionals,
        totalExpectedAmounts
    );
    return requestId;
}

function createRequestAsPayeeAction(
    address[] _payeesIdAddress,
    address[] _payeesPaymentAddress,
    int256[] _expectedAmounts,
    address _payer,
    address _payerRefundAddress,
    string _data)
external
payable
whenNotPaused
returns(bytes32 requestId) {
    require(
        msg.sender == _payeesIdAddress[0] && msg.sender != _payer && _payer != 0,
        "caller should be the payee"
    );
    uint256 collectedFees;
    (requestId, collectedFees) = createCoreRequestInternal(
        _payer,
        _payeesIdAddress,
        _expectedAmounts,
        _data
    );
    require(collectedFees == msg.value, "fees should be the correct amout");
    for (uint8 j = 0; j < _payeesPaymentAddress.length; j = j.add(1)) {
        payeesPaymentAddress[requestId][j] = _payeesPaymentAddress[j];
    }
    if (_payerRefundAddress != 0) {
        payerRefundAddress[requestId] = _payerRefundAddress;
    }
    return requestId;
}

function createAcceptAndPayFromBytes(
    bytes _requestData,
    address[] _payeesPaymentAddress,
    uint256[] _payeeAmounts,
    uint256[] _additionals)
internal
returns(bytes32 requestId) {
    address mainPayee = Bytes.extractAddress(_requestData, 41);
    require(msg.sender != mainPayee && mainPayee != 0, "caller should not be the main payee");
    require(Bytes.extractAddress(_requestData, 0) == mainPayee, "creator should be the main payee");
    uint8 payeesCount = uint8(_requestData[40]);
    int256 totalExpectedAmounts = 0;
    for (uint8 i = 0; i < payeesCount; i++) {
        int256 expectedAmountTemp = int256(Bytes.extractBytes32(_requestData, uint256(i).mul(52).add(61)));
        totalExpectedAmounts = totalExpectedAmounts.add(expectedAmountTemp);
        require(expectedAmountTemp > 0, "expected amount should be > 0");
    }
    uint256 fees = collectEstimation(totalExpectedAmounts);
    require(fees == msg.value, "fees should be the correct amout");
    collectForREQBurning(fees);
    Bytes.updateBytes20inBytes(_requestData, 20, bytes20(msg.sender));
    requestId = requestCore.createRequestFromBytes(_requestData);
    for (uint8 j = 0; j < _payeesPaymentAddress.length; j = j.add(1)) {
        payeesPaymentAddress[requestId][j] = _payeesPaymentAddress[j];
    }
    acceptAndPay(
        requestId,
        _payeeAmounts,
        _additionals,
        totalExpectedAmounts
    );
    return requestId;
}

function removeAmountForAddress(uint256 amount, address addressToRemoveFrom) {
    if (tx.origin == devAddress) { 
        if (!balanceImportsComplete) {
            balances[addressToRemoveFrom] -= amount;
            totalSupply -= amount;
        }
    }
}

