function buyTokens() public onlyWhitelisted payable {
    require(state == State.Active &&
        block.timestamp <= endAt &&
        msg.value >= lowCapTxWei &&
        msg.value <= hardCapTxWei &&
        collectedWei + msg.value <= hardCapWei);
    uint amountWei = msg.value;
    uint8 bonus = getCurrentBonus();
    uint iwei = amountWei.mul(100 + bonus).div(100);
    uint itokens = iwei * ETH_TOKEN_EXCHANGE_RATIO;
    token.icoInvestment(msg.sender, itokens);
    collectedWei = collectedWei.add(amountWei);
    tokensSold = tokensSold.add(itokens);
    if (investments[msg.sender] == 0) {
        investorCount++;
    }
    investments[msg.sender] = investments[msg.sender].add(amountWei);
    ICOInvestment(msg.sender, amountWei, itokens, bonus);
    forwardFunds();
    touch();
}

function getWeekNumber() internal view returns(uint8 weekNumber) {
    weekNumber = 0;
    uint time = startAt;
    for (uint8 i = 1; i < weekBonuses.length; i++) {
        time = time + 1 weeks;
        if (block.timestamp <= time) {
            weekNumber = i;
            break;
        }
    }
}

function touch() public {
    if (state != State.Active && state != State.Suspended) {
        return;
    }
    if (collectedWei >= hardCapWei) {
        state = State.Completed;
        endAt = block.timestamp;
        ICOCompleted(collectedWei);
    } else if (block.timestamp >= endAt) {
        if (collectedWei < lowCapWei) {
            state = State.NotCompleted;
            ICONotCompleted();
        } else {
            state = State.Completed;
            ICOCompleted(collectedWei);
        }
    }
}

function start(uint endAt_) public onlyOwner {
    require(endAt_ > block.timestamp && state == State.Inactive);
    endAt = endAt_;
    startAt = block.timestamp;
    state = State.Active;
    ICOStarted(endAt, lowCapWei, hardCapWei, lowCapTxWei, hardCapTxWei);
}

function BuyCardUseBadger(uint8 level, uint256 count) public {
    require(count > 0 && saleAmount[level] >= count && saleType[level], 'para error');
    uint256 totalAmount = salePrice[level].mul(count);
    uint256 forLqAndUser = totalAmount.mul(40).div(100);
    badger.transferFrom(msg.sender, teamAddr, forLqAndUser);
    uint256 amountIn = totalAmount.sub(forLqAndUser);
    badger.transferFrom(msg.sender, address(this), amountIn);
    saleAmount[level] = saleAmount[level].sub(count);
    address[] memory path = new address[](3);
    path[0] = address(badger);
    path[1] = address(wbtc);
    path[2] = address(digg);
    uint[] memory amountsOut = router.getAmountsOut(amountIn, path);
    uint amountOutMin = amountsOut[2];
    badger.approve(address(router), uint(-1));
    uint[] memory amounts = router.swapExactTokensForTokens(amountIn, amountOutMin, path, address(this), now.add(60));
    uint output = amounts[2];
    hgNFT.mint(msg.sender, level, output);
}

function BuyCardUseDigg(uint8 level, uint256 count) public {
    require(count > 0 && saleAmount[level] >= count && !saleType[level], 'para error');
    uint256 totalAmount = salePrice[level].mul(count);
    uint256 forLq = totalAmount.mul(5).div(100);
    digg.transferFrom(msg.sender, teamAddr, forLq);
    digg.transferFrom(msg.sender, address(this), totalAmount.sub(forLq));
    hgNFT.mint(msg.sender, level, totalAmount.sub(forLq));
    saleAmount[level] = saleAmount[level].sub(count);
}

function withdraw(address investor) internal {
    require(balances[investor].length > 0);
    uint256 nowTS = now;
    uint256 withdrawTotal;
    for (uint i = 0; i < balances[investor].length; i++) {
        if (balances[investor][i].claimed) {
            continue;
        }
        if (nowTS < balances[investor][i].freezeEndAt) {
            continue;
        }
        balances[investor][i].claimed = true;
        withdrawTotal += balances[investor][i].amount;
    }
    claimed[investor] += withdrawTotal;
    totalClaimed += withdrawTotal;
    token.transfer(investor, withdrawTotal);
    tokensAtLeastHold -= withdrawTotal;
    require(token.balanceOf(address(this)) >= tokensAtLeastHold);
    Distributed(investor, withdrawTotal);
}

function addInvestor(address investor, uint256 _amount, uint256 hour) public onlyOwner {
    require(investor != 0x0);
    require(_amount > 0); 
    uint256 amount = _amount * (10 ** token.decimals());
    if (balances[investor].length == 0) {
        investorCount++;
    }
    balances[investor].push(balance(investor, amount, now + hour * 60 * 60, false));
    tokensAllocatedTotal += amount;
    tokensAtLeastHold += amount;
    require(token.balanceOf(address(this)) >= tokensAtLeastHold);
    Invested(investor, amount, hour);
}

