function endVesting(address _addressToEnd, address _addressToRefund)
public
onlyOwner
addressNotNull(_addressToRefund) {
    VestingSchedule storage vestingSchedule = schedules[_addressToEnd];
    uint amountWithdrawable = 0;
    uint amountRefundable = 0;
    if (getTime() < vestingSchedule.cliffTimeInSec) {
        amountRefundable = vestingSchedule.totalAmount;
    } else {
        uint totalAmountVested = getTotalAmountVested(vestingSchedule);
        amountWithdrawable = safeSub(totalAmountVested, vestingSchedule.totalAmountWithdrawn);
        amountRefundable = safeSub(vestingSchedule.totalAmount, totalAmountVested);
    }
    delete schedules[_addressToEnd];
    require(amountWithdrawable == 0 || vestingToken.transfer(_addressToEnd, amountWithdrawable));
    require(amountRefundable == 0 || vestingToken.transfer(_addressToRefund, amountRefundable));
    VestingEndedByOwner(_addressToEnd, amountWithdrawable, amountRefundable);
}

function registerVestingSchedule(
    address _addressToRegister,
    address _depositor,
    uint _startTimeInSec,
    uint _cliffTimeInSec,
    uint _endTimeInSec,
    uint _totalAmount
)
public
onlyOwner
addressNotNull(_depositor)
validVestingScheduleTimes(_startTimeInSec, _cliffTimeInSec, _endTimeInSec) {
    require(vestingToken.transferFrom(approvedWallet, address(this), _totalAmount));
    require(vestingToken.balanceOf(address(this)) >= _totalAmount);
    schedules[_addressToRegister] = VestingSchedule({
        startTimeInSec: _startTimeInSec,
        cliffTimeInSec: _cliffTimeInSec,
        endTimeInSec: _endTimeInSec,
        totalAmount: _totalAmount,
        totalAmountWithdrawn: 0,
        depositor: _depositor
    });
    VestingScheduleRegistered(
        _addressToRegister,
        _depositor,
        _startTimeInSec,
        _cliffTimeInSec,
        _endTimeInSec,
        _totalAmount
    );
}

function withdraw()
public
pastCliffTime(msg.sender) {
    VestingSchedule storage vestingSchedule = schedules[msg.sender];
    uint totalAmountVested = getTotalAmountVested(vestingSchedule);
    uint amountWithdrawable = safeSub(totalAmountVested, vestingSchedule.totalAmountWithdrawn);
    vestingSchedule.totalAmountWithdrawn = totalAmountVested;
    if (amountWithdrawable > 0) {
        require(vestingToken.transfer(msg.sender, amountWithdrawable));
        Withdrawal(msg.sender, amountWithdrawable);
    }
}

function getTotalAmountVested(VestingSchedule vestingSchedule)
internal
view
returns(uint) {
    if (getTime() >= vestingSchedule.endTimeInSec) {
        return vestingSchedule.totalAmount;
    }
    uint timeSinceStartInSec = safeSub(getTime(), vestingSchedule.startTimeInSec);
    uint totalVestingTimeInSec = safeSub(vestingSchedule.endTimeInSec, vestingSchedule.startTimeInSec);
    uint totalAmountVested = safeDiv(
        safeMul(timeSinceStartInSec, vestingSchedule.totalAmount), totalVestingTimeInSec
    );
    return totalAmountVested;
}

function tradeLayersxToEth(uint index) external paused exist(index) {
    Rewards memory rwds = rewards[msg.sender][index];
    Stake memory stake = stakes[index];
    require(stake.end <= now, 'Invalid date for withdrawal.');
    require(rwds.layersx > 0, 'You do not have Layersx for this stake to exchange for ETH.');
    require(rwds.eth == 0, 'You already traded the Layersx of this stake for ETH');
    balances[msg.sender] = balances[msg.sender].sub(rwds.layersx);
    balances[owner] = balances[owner].add(rwds.layersx);
    uint eths = stake.ethLayerx.mul(rwds.layersx).div(CAP);
    rwds.eth = eths;
    msg.sender.transfer(eths);
    rewards[msg.sender][index] = rwds;
    emit logTradeLayersxEth(msg.sender, eths, index);
}

function unlock() external paused {
    StakeHolder memory holder = stakeHolders[msg.sender];
    uint amt = holder.layerLocked;
    require(amt > 0, 'You do not have locked tokens.');
    UNILAYER.transfer(msg.sender, amt);
    Stake memory stake = stakes[stakeNum];
    require(stake.end == 0, 'Invalid date for unlock, please use withdraw.');
    stake.layerLockedTotal = stake.layerLockedTotal.sub(amt);
    stakes[stakeNum] = stake;
    holder.layerLocked = 0;
    stakeHolders[msg.sender] = holder;
    removeHolder(holder);
    emit logUnlockedTokens(msg.sender, amt);
}

function withdraw(uint index) external paused exist(index) {
    Rewards memory rwds = rewards[msg.sender][index];
    Stake memory stake = stakes[index];
    require(stake.end <= now, 'Invalid date for withdrawal.');
    require(stake.rewardPayment > 0, 'There is no value to distribute.');
    require(rwds.withLayersx == false, 'You already withdrawal your Layersx.');
    require(rwds.layersx > 0, 'You dont have Layerx to withdraw.');
    balances[owner] = balances[owner].sub(rwds.layersx);
    balances[msg.sender] = balances[msg.sender].add(rwds.layersx);
    rwds.withLayersx = true;
    emit logWithdraw(msg.sender, rwds.layersx, index);
    rewards[msg.sender][index] = rwds;
}

function _vestedAmount() private view returns(uint256) {
    uint256 currentBalance = _token.balanceOf(address(this));
    uint256 totalBalance = currentBalance.add(_released);
    if (block.timestamp < _cliff) {
        return 0;
    } else if (block.timestamp >= _start.add(_duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(_start)).div(_duration);
    }
}

constructor(address beneficiary, uint256 cliffDuration, uint256 duration) public {
    _start = block.timestamp;
    require(beneficiary != address(0), "no beneficiary");
    require(cliffDuration <= duration, "invalid cliff period");
    require(duration > 0, "invalid duration");
    require(_start.add(duration) > block.timestamp, "invalid final time");
    _beneficiary = beneficiary;
    _duration = duration;
    _cliff = _start.add(cliffDuration);
    _start = _start;
    _deployer = msg.sender;
}

function release() public {
    uint256 unreleased = _releasableAmount();
    require(unreleased > 0, "No tokens TBR");
    _released = _released.add(unreleased);
    _token.safeTransfer(_beneficiary, unreleased);
    emit TokensReleased(unreleased);
}

