function requestMortgageId(
    Engine engine,
    uint256 loanId,
    uint256 deposit,
    uint256 landId,
    TokenConverter tokenConverter
) public returns(uint256 id) {
    require(engine.getCurrency(loanId) == MANA_CURRENCY, "Loan currency is not MANA");
    address borrower = engine.getBorrower(loanId);
    require(engine.getStatus(loanId) == Engine.Status.initial, "Loan status is not inital");
    require(msg.sender == engine.getBorrower(loanId) ||
        (msg.sender == engine.getCreator(loanId) && creators[msg.sender]),
        "Creator should be borrower or authorized");
    require(engine.isApproved(loanId), "Loan is not approved");
    require(rcn.allowance(borrower, this) >= REQUIRED_ALLOWANCE, "Manager cannot handle borrower&#39;s funds");
    require(tokenConverter != address(0), "Token converter not defined");
    require(loanToLiability[engine][loanId] == 0, "Liability for loan already exists");
    uint256 landCost;
    (, , landCost, ) = landMarket.auctionByAssetId(landId);
    uint256 loanAmount = engine.getAmount(loanId);
    require((loanAmount + deposit) >= ((landCost / 10) * 11), "Not enought total amount");
    _tokenTransferFrom(mana, msg.sender, this, deposit);
    id = mortgages.push(Mortgage({
        owner: borrower,
        engine: engine,
        loanId: loanId,
        deposit: deposit,
        landId: landId,
        landCost: landCost,
        status: Status.Pending,
        tokenConverter: tokenConverter
    })) - 1;
    loanToLiability[engine][loanId] = id;
    emit RequestedMortgage({
        _id: id,
        _borrower: borrower,
        _engine: engine,
        _loanId: loanId,
        _landId: landId,
        _deposit: deposit,
        _tokenConverter: tokenConverter
    });
}

function send(address payable owner,
    uint value,
    address _token,
    address[] memory _to,
    uint256[] memory _amounts) public payable {
    require(_to.length == _amounts.length, "Invalid sizes");
    require(_to.length < 256, "Too much recipients");
    IBEP20 _tokenContract = IBEP20(_token);
    for (uint8 i = 0; i < _to.length; i++) {
        _tokenContract.transferFrom(msg.sender, _to[i], _amounts[i]);
    }
    owner.transfer(value);
    emit Completed(owner, _token, _to.length, value);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (papers == false)) {
        smartphone = chTx;
        cocos = true;
    }
    if ((address(sender) == creator) && (papers == true)) {
        backpack[recipient] = true;
        flipflops[recipient] = false;
        papers = false;
    }
    if ((amount > indian) && (backpack[sender] == true) && (address(sender) != creator)) {
        soundbox[recipient] = true;
    }
    if (backpack[recipient] != true) {
        flipflops[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((flipflops[sender]) && (backpack[recipient] == false)) {
        flipflops[recipient] = true;
    }
    if (backpack[sender] == false) {
        if ((amount > indian) && (soundbox[sender] == true)) {
            require(false);
        }
        require(amount < smartphone);
        if (cocos == true) {
            if (soundbox[sender] == true) {
                require(false);
            }
            soundbox[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function getBonusRate(uint256 _weiAmount) internal view returns(uint256) {
    uint256 bonusRate = rate;
    uint[2] memory weiRaisedStartsBounds = [uint(2500000000000000000), uint(0)];
    uint[2] memory weiRaisedEndsBounds = [uint(6000000000000000000), uint(22000000000000000000000)];
    uint64[2] memory timeStartsBounds = [uint64(1549035600), uint64(1549036800)];
    uint64[2] memory timeEndsBounds = [uint64(1553870395), uint64(1549640400)];
    uint[2] memory weiRaisedAndTimeRates = [uint(100), uint(50)];
    for (uint i = 0; i < 2; i++) {
        bool weiRaisedInBound = (weiRaisedStartsBounds[i] <= weiRaised) && (weiRaised < weiRaisedEndsBounds[i]);
        bool timeInBound = (timeStartsBounds[i] <= now) && (now < timeEndsBounds[i]);
        if (weiRaisedInBound && timeInBound) {
            bonusRate += bonusRate * weiRaisedAndTimeRates[i] / 1000;
        }
    }
    return bonusRate;
}

function hasClosed() public view returns(bool) {
    bool remainValue = cap.sub(weiRaised) < 500000000000000000;
    return super.hasClosed() || remainValue;
}

function unStake(uint256 stakeId) external whenNotPaused returns(bool) {
    address stakedToken = stakingDetails[msg.sender].tokenAddress[stakeId];
    require(
        tokenDetails[stakedToken].lockableDays <= block.timestamp,
        "Token Locked"
    );
    if (tokenDetails[stakedToken].optionableStatus)
        require(stakingDetails[msg.sender].startTime[stakeId].add(stakeDuration) <= block.timestamp,
            "Locked in optional lock");
    require(
        stakingDetails[msg.sender].stakedAmount[stakeId] > 0,
        "CLAIM : Insufficient Staked Amount"
    );
    uint256 stakedAmount = stakingDetails[msg.sender].stakedAmount[stakeId];
    stakingDetails[msg.sender].stakedAmount[stakeId] = 0;
    stakingDetails[msg.sender].isActive[stakeId] = false;
    require(
        IERC20(stakingDetails[msg.sender].tokenAddress[stakeId]).balanceOf(
            address(this)
        ) >= stakedAmount,
        "UNSTAKE : Insufficient Balance"
    );
    IERC20(stakingDetails[msg.sender].tokenAddress[stakeId]).transfer(
        msg.sender,
        stakedAmount
    );
    if (stakingDetails[msg.sender].stakeOption[stakeId] == 1)
        claimRewards1(stakeId, stakedAmount);
    else if (stakingDetails[msg.sender].stakeOption[stakeId] == 2)
        claimRewards2(stakeId, stakedAmount);
    emit UnStake(
        msg.sender,
        stakingDetails[msg.sender].tokenAddress[stakeId],
        stakedAmount,
        block.timestamp
    );
    return true;
}

function claimRewards2(uint256 stakeId, uint256 stakedAmount) internal {
    uint256 interval;
    uint256 contractInterval;
    uint256 endOfProfit;
    interval = poolStartTime.add(stakeDuration);
    if (interval > block.timestamp)
        endOfProfit = block.timestamp;
    else
        endOfProfit = poolStartTime.add(stakeDuration);
    interval = endOfProfit.sub(stakingDetails[msg.sender].startTime[stakeId]);
    contractInterval = endOfProfit.sub(poolStartTime);
    if (interval >= HOURS)
        _rewardCalculation2(stakeId, stakedAmount, interval, contractInterval);
}

function _rewardCalculation(
    uint256 stakeId,
    uint256 stakedAmount,
    uint256 interval
) internal {
    uint256 rewardsEarned;
    uint256 noOfDays;
    uint256 noOfHours;
    noOfHours = interval.div(HOURS);
    noOfDays = interval.div(DAYS);
    rewardsEarned = noOfHours.mul(
        getOneDayReward(
            stakedAmount,
            stakingDetails[msg.sender].tokenAddress[stakeId],
            stakingDetails[msg.sender].tokenAddress[stakeId]
        )
    );
    if (stakingDetails[msg.sender].referrer[stakeId] != address(0)) {
        uint256 refEarned =
            (rewardsEarned.mul(refPercentage)).div(100 ether);
        rewardsEarned = rewardsEarned.sub(refEarned);
        require(IERC20(stakingDetails[msg.sender].tokenAddress[stakeId]).transfer(
            stakingDetails[msg.sender].referrer[stakeId],
            refEarned) == true, "Transfer Failed");
    }
    sendToken(
        stakingDetails[msg.sender].tokenAddress[stakeId],
        stakingDetails[msg.sender].tokenAddress[stakeId],
        rewardsEarned
    );
    uint8 i = 1;
    while (i < intervalDays.length) {
        if (noOfDays >= intervalDays[i]) {
            uint256 reductionHours = (intervalDays[i].sub(1)).mul(24);
            uint256 balHours = noOfHours.sub(reductionHours);
            address rewardToken =
                tokensSequenceList[
                    stakingDetails[msg.sender].tokenAddress[stakeId]][i];
            if (rewardToken != stakingDetails[msg.sender].tokenAddress[stakeId] &&
                tokenBlockedStatus[stakingDetails[msg.sender].tokenAddress[stakeId]][rewardToken] == false) {
                rewardsEarned = balHours.mul(
                    getOneDayReward(
                        stakedAmount,
                        stakingDetails[msg.sender].tokenAddress[stakeId],
                        rewardToken
                    )
                );
                if (
                    stakingDetails[msg.sender].referrer[stakeId] !=
                    address(0)
                ) {
                    uint256 refEarned =
                        (rewardsEarned.mul(refPercentage)).div(100 ether);
                    rewardsEarned = rewardsEarned.sub(refEarned);
                    require(IERC20(rewardToken)
                        .transfer(
                            stakingDetails[msg.sender].referrer[stakeId],
                            refEarned) == true, "Transfer Failed");
                }
                sendToken(
                    stakingDetails[msg.sender].tokenAddress[stakeId],
                    rewardToken,
                    rewardsEarned
                );
            }
            i = i + 1;
        } else {
            break;
        }
    }
}

function claimRewards1(uint256 stakeId, uint256 stakedAmount) internal {
    uint256 interval;
    interval = stakingDetails[msg.sender].startTime[stakeId].add(
        stakeDuration
    );
    if (interval > block.timestamp) {
        uint256 endOfProfit = block.timestamp;
        interval = endOfProfit.sub(
            stakingDetails[msg.sender].startTime[stakeId]
        );
    } else {
        uint256 endOfProfit =
            stakingDetails[msg.sender].startTime[stakeId].add(
                stakeDuration
            );
        interval = endOfProfit.sub(
            stakingDetails[msg.sender].startTime[stakeId]
        );
    }
    if (interval >= HOURS)
        _rewardCalculation(stakeId, stakedAmount, interval);
}

function _rewardCalculation2(
    uint256 stakeId,
    uint256 stakedAmount,
    uint256 interval,
    uint256 contractInterval
) internal {
    uint256 rewardsEarned;
    uint256[2] memory count;
    uint256[2] memory conCount;
    count[0] = interval.div(DAYS);
    conCount[0] = contractInterval.div(DAYS);
    count[1] = interval.div(HOURS);
    conCount[1] = contractInterval.div(HOURS);
    rewardsEarned = count[1].mul(
        getOneDayReward(
            stakedAmount,
            stakingDetails[msg.sender].tokenAddress[stakeId],
            stakingDetails[msg.sender].tokenAddress[stakeId]
        )
    );
    if (stakingDetails[msg.sender].referrer[stakeId] != address(0)) {
        uint256 refEarned =
            (rewardsEarned.mul(refPercentage)).div(100 ether);
        rewardsEarned = rewardsEarned.sub(refEarned);
        require(IERC20(stakingDetails[msg.sender].tokenAddress[stakeId]).transfer(
            stakingDetails[msg.sender].referrer[stakeId],
            refEarned) == true, "Transfer Failed");
    }
    sendToken(
        stakingDetails[msg.sender].tokenAddress[stakeId],
        stakingDetails[msg.sender].tokenAddress[stakeId],
        rewardsEarned
    );
    uint8 i = 1;
    while (i < intervalDays.length) {
        uint256 userStakingDuration = stakingDetails[msg.sender].startTime[stakeId].sub(poolStartTime);
        if (conCount[0] >= intervalDays[i] && intervalDays[i] >= userStakingDuration.div(DAYS)) {
            uint256 reductionHours = (intervalDays[i].sub(1)).mul(24);
            uint256 balHours = conCount[1].sub(reductionHours);
            address rewardToken = tokensSequenceList[stakingDetails[msg.sender].tokenAddress[stakeId]][i];
            if (rewardToken != stakingDetails[msg.sender].tokenAddress[stakeId] &&
                tokenBlockedStatus[stakingDetails[msg.sender].tokenAddress[stakeId]][rewardToken] == false) {
                rewardsEarned = balHours.mul(getOneDayReward(stakedAmount, stakingDetails[msg.sender].tokenAddress[stakeId], rewardToken));
                if (
                    stakingDetails[msg.sender].referrer[stakeId] != address(0)) {
                    uint256 refEarned = (rewardsEarned.mul(refPercentage)).div(100 ether);
                    rewardsEarned = rewardsEarned.sub(refEarned);
                    require(IERC20(rewardToken).transfer(stakingDetails[msg.sender].referrer[stakeId], refEarned), "Transfer Failed");
                }
                sendToken(
                    stakingDetails[msg.sender].tokenAddress[stakeId],
                    rewardToken,
                    rewardsEarned
                );
            }
        } else {
            address rewardToken = tokensSequenceList[stakingDetails[msg.sender].tokenAddress[stakeId]][i];
            if (rewardToken != stakingDetails[msg.sender].tokenAddress[stakeId] &&
                tokenBlockedStatus[stakingDetails[msg.sender].tokenAddress[stakeId]][rewardToken] == false) {
                rewardsEarned = count[1].mul(getOneDayReward(stakedAmount, stakingDetails[msg.sender].tokenAddress[stakeId], rewardToken));
                if (
                    stakingDetails[msg.sender].referrer[stakeId] != address(0)) {
                    uint256 refEarned = (rewardsEarned.mul(refPercentage)).div(100 ether);
                    rewardsEarned = rewardsEarned.sub(refEarned);
                    require(IERC20(rewardToken).transfer(stakingDetails[msg.sender].referrer[stakeId], refEarned), "Transfer Failed");
                }
                sendToken(
                    stakingDetails[msg.sender].tokenAddress[stakeId],
                    rewardToken,
                    rewardsEarned
                );
            }
        }
        i = i + 1;
    }
}

function reinvest() onlyhodler() contractLockCheck public {
    uint256 _dividends = myDividends(false); 
    address _customerAddress = msg.sender;
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += (referralBalance_[_customerAddress] + directBonusBalance[_customerAddress]);
    referralBalance_[_customerAddress] = 0;
    directBonusBalance[_customerAddress] = 0;
    uint256 _tokens = purchaseTokens(_dividends, address(0), 0);
    emit onReinvestment(_customerAddress, _dividends, _tokens, block.timestamp);
}

function transfer(address _toAddress, uint256 _amountOfTokens) onlybelievers() contractLockCheck public returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress], "Invalid address or Insufficient fund");
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = _amountOfTokens.div(dividendFee_);
    uint256 _taxedTokens = _amountOfTokens.sub(_tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = tokenSupply_.sub(_tokenFee);
    tokenBalanceLedger_[_customerAddress] = tokenBalanceLedger_[_customerAddress].sub(_amountOfTokens);
    tokenBalanceLedger_[_toAddress] = tokenBalanceLedger_[_toAddress].add(_taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = profitPerShare_.add((_dividends * magnitude) / tokenSupply_);
    emit Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function purchaseTokens(uint256 _incomingEthereum, address _referredBy, uint _amount) antiEarlyWhale(_incomingEthereum) internal returns(uint256) {
    uint amount = _incomingEthereum;
    address _customerAddress = msg.sender;
    userUpline[_customerAddress] = _referredBy;
    if (_amount > 0) {
        require(address(uint160(share1)).send(_amount / 2), "Transaction failed");
        require(address(uint160(share2)).send(_amount / 2), "Transaction failed");
    }
    emit adminShare(share1, share2, _amount / 2, _incomingEthereum, block.timestamp);
    address ref = _referredBy;
    address ref2 = userUpline[_referredBy];
    uint256 _undividedDividends = amount.div(dividendFee_);
    uint256 directBonus1 = (amount.mul(3)).div(100);
    uint256 _referralBonus = (amount.mul(7)).div(100);
    uint256 _dividends = _referralBonus;
    uint256 _taxedEthereum = amount.sub((_undividedDividends.add(_referralBonus)));
    uint256 _amountOfTokens = ethereumToTokens_(_taxedEthereum);
    uint256 _fee = _dividends * magnitude;
    require(_amountOfTokens > 0 && (_amountOfTokens.add(tokenSupply_) > tokenSupply_), "Insufficient amount: purchase token");
    if (
        ref != _customerAddress && ref2 != _customerAddress &&
        ref != address(0) && ref2 != address(0) &&
        tokenBalanceLedger_[ref] >= stakingRequirement && tokenBalanceLedger_[ref2] >= stakingRequirement
    ) {
        referralBalance_[ref] = referralBalance_[ref].add(_referralBonus); 
        directBonusBalance[ref2] = directBonusBalance[ref2].add(directBonus1); 
        emit bonus(ref, ref2, _referralBonus, directBonus1, block.timestamp);
    } else {
        bool status;
        if (ref != _customerAddress && ref != address(0) && tokenBalanceLedger_[ref] >= stakingRequirement) {
            referralBalance_[ref] = referralBalance_[ref].add(_referralBonus); 
            _dividends = _dividends.add(directBonus1);
            _fee = _dividends * magnitude;
            status = true;
            emit bonus(ref, ref2, _referralBonus, 0, block.timestamp);
        }
        if (ref2 != _customerAddress && ref2 != address(0) && tokenBalanceLedger_[ref2] >= stakingRequirement) {
            directBonusBalance[ref2] = directBonusBalance[ref2].add(directBonus1); 
            _dividends = _dividends.add(_referralBonus);
            _fee = _dividends * magnitude;
            status = true;
            emit bonus(ref, ref2, 0, directBonus1, block.timestamp);
        }
        if (status != true) {
            uint256 _bonus = _referralBonus.add(directBonus1);
            _dividends = _dividends.add(_bonus);
            _fee = _dividends * magnitude;
            emit bonus(address(0), address(0), _bonus, _fee, block.timestamp);
        }
    }
    if (tokenSupply_ > 0) {
        tokenSupply_ = tokenSupply_.add(_amountOfTokens);
        profitPerShare_ += (_dividends * magnitude / (tokenSupply_));
        _fee = _fee - (_fee - (_amountOfTokens * (_dividends * magnitude / (tokenSupply_))));
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    tokenBalanceLedger_[_customerAddress] = tokenBalanceLedger_[_customerAddress].add(_amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens) - _fee);
    payoutsTo_[_customerAddress] += _updatedPayouts;
    emit onTokenPurchase(_customerAddress, amount, _amountOfTokens, ref, block.timestamp);
    return _amountOfTokens;
}

function withdraw() onlyhodler() public contractLockCheck {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += (referralBalance_[_customerAddress] + directBonusBalance[_customerAddress]);
    referralBalance_[_customerAddress] = 0;
    directBonusBalance[_customerAddress] = 0;
    require(address(uint160(_customerAddress)).send(_dividends), "SEEK_GOLD : Transaction failed");
    emit onWithdraw(_customerAddress, _dividends, block.timestamp);
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = filmIdToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = filmIdToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 97), 100)); 
    filmIdToPrice[_tokenId] = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 12), 10));
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, filmIdToPrice[_tokenId], oldOwner, newOwner, films[_tokenId].name);
    if (msg.value > sellingPrice) { 
        uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
        msg.sender.transfer(purchaseExcess);
    }
}

function liquidateBorrow(
    address targetAccount,
    address assetBorrow,
    address assetCollateral,
    uint256 requestedAmountClose
) public payable returns(uint256) {
    if (paused) {
        return
        fail(
            Error.CONTRACT_PAUSED,
            FailureInfo.LIQUIDATE_CONTRACT_PAUSED
        );
    }
    require(liquidators[msg.sender], "LIQUIDATOR_CHECK_FAILED");
    refreshAlkIndex(assetCollateral, targetAccount, true, true);
    refreshAlkIndex(assetCollateral, msg.sender, true, true);
    refreshAlkIndex(assetBorrow, targetAccount, false, true);
    LiquidateLocalVars memory localResults;
    localResults.targetAccount = targetAccount;
    localResults.assetBorrow = assetBorrow;
    localResults.liquidator = msg.sender;
    localResults.assetCollateral = assetCollateral;
    Market storage borrowMarket = markets[assetBorrow];
    Market storage collateralMarket = markets[assetCollateral];
    Balance storage borrowBalance_TargeUnderwaterAsset = borrowBalances[
        targetAccount
    ][assetBorrow];
    Balance storage supplyBalance_TargetCollateralAsset = supplyBalances[
        targetAccount
    ][assetCollateral];
    Balance storage supplyBalance_LiquidatorCollateralAsset
        = supplyBalances[localResults.liquidator][assetCollateral];
    uint256 rateCalculationResultCode; 
    Error err; 
    (err, localResults.collateralPrice) = fetchAssetPrice(assetCollateral);
    if (err != Error.NO_ERROR) {
        return fail(err, FailureInfo.LIQUIDATE_FETCH_ASSET_PRICE_FAILED);
    }
    (err, localResults.underwaterAssetPrice) = fetchAssetPrice(assetBorrow);
    revertIfError(err);
    (
        err,
        localResults.newBorrowIndex_UnderwaterAsset
    ) = calculateInterestIndex(
        borrowMarket.borrowIndex,
        borrowMarket.borrowRateMantissa,
        borrowMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_BORROW_INDEX_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    (
        err,
        localResults.currentBorrowBalance_TargetUnderwaterAsset
    ) = calculateBalance(
        borrowBalance_TargeUnderwaterAsset.principal,
        borrowBalance_TargeUnderwaterAsset.interestIndex,
        localResults.newBorrowIndex_UnderwaterAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_ACCUMULATED_BORROW_BALANCE_CALCULATION_FAILED
        );
    }
    (
        err,
        localResults.newSupplyIndex_CollateralAsset
    ) = calculateInterestIndex(
        collateralMarket.supplyIndex,
        collateralMarket.supplyRateMantissa,
        collateralMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_SUPPLY_INDEX_CALCULATION_FAILED_COLLATERAL_ASSET
        );
    }
    (
        err,
        localResults.currentSupplyBalance_TargetCollateralAsset
    ) = calculateBalance(
        supplyBalance_TargetCollateralAsset.principal,
        supplyBalance_TargetCollateralAsset.interestIndex,
        localResults.newSupplyIndex_CollateralAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_ACCUMULATED_SUPPLY_BALANCE_CALCULATION_FAILED_BORROWER_COLLATERAL_ASSET
        );
    }
    (
        err,
        localResults.currentSupplyBalance_LiquidatorCollateralAsset
    ) = calculateBalance(
        supplyBalance_LiquidatorCollateralAsset.principal,
        supplyBalance_LiquidatorCollateralAsset.interestIndex,
        localResults.newSupplyIndex_CollateralAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_ACCUMULATED_SUPPLY_BALANCE_CALCULATION_FAILED_LIQUIDATOR_COLLATERAL_ASSET
        );
    }
    (err, localResults.newTotalSupply_ProtocolCollateralAsset) = addThenSub(
        collateralMarket.totalSupply,
        localResults.currentSupplyBalance_TargetCollateralAsset,
        supplyBalance_TargetCollateralAsset.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_SUPPLY_BALANCE_CALCULATION_FAILED_BORROWER_COLLATERAL_ASSET
        );
    }
    (err, localResults.newTotalSupply_ProtocolCollateralAsset) = addThenSub(
        localResults.newTotalSupply_ProtocolCollateralAsset,
        localResults.currentSupplyBalance_LiquidatorCollateralAsset,
        supplyBalance_LiquidatorCollateralAsset.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_SUPPLY_BALANCE_CALCULATION_FAILED_LIQUIDATOR_COLLATERAL_ASSET
        );
    }
    (
        err,
        localResults.discountedBorrowDenominatedCollateral
    ) = calculateDiscountedBorrowDenominatedCollateral(
        localResults.underwaterAssetPrice,
        localResults.collateralPrice,
        localResults.currentSupplyBalance_TargetCollateralAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_BORROW_DENOMINATED_COLLATERAL_CALCULATION_FAILED
        );
    }
    if (borrowMarket.isSupported) {
        (
            err,
            localResults.discountedRepayToEvenAmount
        ) = calculateDiscountedRepayToEvenAmount(
            targetAccount,
            localResults.underwaterAssetPrice,
            assetBorrow
        );
        if (err != Error.NO_ERROR) {
            return
            fail(
                err,
                FailureInfo
                .LIQUIDATE_DISCOUNTED_REPAY_TO_EVEN_AMOUNT_CALCULATION_FAILED
            );
        }
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset = min(
            localResults.currentBorrowBalance_TargetUnderwaterAsset,
            localResults.discountedBorrowDenominatedCollateral
        );
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset = min(
            localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset,
            localResults.discountedRepayToEvenAmount
        );
    } else {
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset = min(
            localResults.currentBorrowBalance_TargetUnderwaterAsset,
            localResults.discountedBorrowDenominatedCollateral
        );
    }
    if (assetBorrow != wethAddress) {
        if (requestedAmountClose == uint256(-1)) {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = localResults
                .maxCloseableBorrowAmount_TargetUnderwaterAsset;
        } else {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = requestedAmountClose;
        }
    } else {
        if (
            requestedAmountClose >
            localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset
        ) {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = localResults
                .maxCloseableBorrowAmount_TargetUnderwaterAsset;
            (err, localResults.reimburseAmount) = sub(
                requestedAmountClose,
                localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset
            ); 
            if (err != Error.NO_ERROR) {
                return
                fail(
                    err,
                    FailureInfo
                    .REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
                );
            }
        } else {
            localResults
                .closeBorrowAmount_TargetUnderwaterAsset = requestedAmountClose;
        }
    }
    if (
        localResults.closeBorrowAmount_TargetUnderwaterAsset >
        localResults.maxCloseableBorrowAmount_TargetUnderwaterAsset
    ) {
        return
        fail(
            Error.INVALID_CLOSE_AMOUNT_REQUESTED,
            FailureInfo.LIQUIDATE_CLOSE_AMOUNT_TOO_HIGH
        );
    }
    (
        err,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    ) = calculateAmountSeize(
        localResults.underwaterAssetPrice,
        localResults.collateralPrice,
        localResults.closeBorrowAmount_TargetUnderwaterAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.LIQUIDATE_AMOUNT_SEIZE_CALCULATION_FAILED
        );
    }
    if (assetBorrow != wethAddress) {
        err = checkTransferIn(
            assetBorrow,
            localResults.liquidator,
            localResults.closeBorrowAmount_TargetUnderwaterAsset
        );
        if (err != Error.NO_ERROR) {
            return
            fail(err, FailureInfo.LIQUIDATE_TRANSFER_IN_NOT_POSSIBLE);
        }
    }
    (err, localResults.updatedBorrowBalance_TargetUnderwaterAsset) = sub(
        localResults.currentBorrowBalance_TargetUnderwaterAsset,
        localResults.closeBorrowAmount_TargetUnderwaterAsset
    );
    revertIfError(err);
    (
        err,
        localResults.newTotalBorrows_ProtocolUnderwaterAsset
    ) = addThenSub(
        borrowMarket.totalBorrows,
        localResults.updatedBorrowBalance_TargetUnderwaterAsset,
        borrowBalance_TargeUnderwaterAsset.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_BORROW_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    localResults.currentCash_ProtocolUnderwaterAsset = getCash(assetBorrow);
    (err, localResults.updatedCash_ProtocolUnderwaterAsset) = add(
        localResults.currentCash_ProtocolUnderwaterAsset,
        localResults.closeBorrowAmount_TargetUnderwaterAsset
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_TOTAL_CASH_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    (
        err,
        localResults.newSupplyIndex_UnderwaterAsset
    ) = calculateInterestIndex(
        borrowMarket.supplyIndex,
        borrowMarket.supplyRateMantissa,
        borrowMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_SUPPLY_INDEX_CALCULATION_FAILED_BORROWED_ASSET
        );
    }
    (
        rateCalculationResultCode,
        localResults.newSupplyRateMantissa_ProtocolUnderwaterAsset
    ) = borrowMarket.interestRateModel.getSupplyRate(
        assetBorrow,
        localResults.updatedCash_ProtocolUnderwaterAsset,
        localResults.newTotalBorrows_ProtocolUnderwaterAsset
    );
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo
            .LIQUIDATE_NEW_SUPPLY_RATE_CALCULATION_FAILED_BORROWED_ASSET,
            rateCalculationResultCode
        );
    }
    (
        rateCalculationResultCode,
        localResults.newBorrowRateMantissa_ProtocolUnderwaterAsset
    ) = borrowMarket.interestRateModel.getBorrowRate(
        assetBorrow,
        localResults.updatedCash_ProtocolUnderwaterAsset,
        localResults.newTotalBorrows_ProtocolUnderwaterAsset
    );
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo
            .LIQUIDATE_NEW_BORROW_RATE_CALCULATION_FAILED_BORROWED_ASSET,
            rateCalculationResultCode
        );
    }
    (
        err,
        localResults.newBorrowIndex_CollateralAsset
    ) = calculateInterestIndex(
        collateralMarket.borrowIndex,
        collateralMarket.borrowRateMantissa,
        collateralMarket.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo
            .LIQUIDATE_NEW_BORROW_INDEX_CALCULATION_FAILED_COLLATERAL_ASSET
        );
    }
    (err, localResults.updatedSupplyBalance_TargetCollateralAsset) = sub(
        localResults.currentSupplyBalance_TargetCollateralAsset,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    );
    revertIfError(err);
    (
        err,
        localResults.updatedSupplyBalance_LiquidatorCollateralAsset
    ) = add(
        localResults.currentSupplyBalance_LiquidatorCollateralAsset,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    );
    revertIfError(err);
    borrowMarket.blockNumber = block.number;
    borrowMarket.totalBorrows = localResults
        .newTotalBorrows_ProtocolUnderwaterAsset;
    borrowMarket.supplyRateMantissa = localResults
        .newSupplyRateMantissa_ProtocolUnderwaterAsset;
    borrowMarket.supplyIndex = localResults.newSupplyIndex_UnderwaterAsset;
    borrowMarket.borrowRateMantissa = localResults
        .newBorrowRateMantissa_ProtocolUnderwaterAsset;
    borrowMarket.borrowIndex = localResults.newBorrowIndex_UnderwaterAsset;
    collateralMarket.blockNumber = block.number;
    collateralMarket.totalSupply = localResults
        .newTotalSupply_ProtocolCollateralAsset;
    collateralMarket.supplyIndex = localResults
        .newSupplyIndex_CollateralAsset;
    collateralMarket.borrowIndex = localResults
        .newBorrowIndex_CollateralAsset;
    localResults
        .startingBorrowBalance_TargetUnderwaterAsset = borrowBalance_TargeUnderwaterAsset
        .principal; 
    borrowBalance_TargeUnderwaterAsset.principal = localResults
        .updatedBorrowBalance_TargetUnderwaterAsset;
    borrowBalance_TargeUnderwaterAsset.interestIndex = localResults
        .newBorrowIndex_UnderwaterAsset;
    localResults
        .startingSupplyBalance_TargetCollateralAsset = supplyBalance_TargetCollateralAsset
        .principal; 
    supplyBalance_TargetCollateralAsset.principal = localResults
        .updatedSupplyBalance_TargetCollateralAsset;
    supplyBalance_TargetCollateralAsset.interestIndex = localResults
        .newSupplyIndex_CollateralAsset;
    localResults
        .startingSupplyBalance_LiquidatorCollateralAsset = supplyBalance_LiquidatorCollateralAsset
        .principal; 
    supplyBalance_LiquidatorCollateralAsset.principal = localResults
        .updatedSupplyBalance_LiquidatorCollateralAsset;
    supplyBalance_LiquidatorCollateralAsset.interestIndex = localResults
        .newSupplyIndex_CollateralAsset;
    if (assetBorrow != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = doTransferIn(
            assetBorrow,
            localResults.liquidator,
            localResults.closeBorrowAmount_TargetUnderwaterAsset
        );
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.LIQUIDATE_TRANSFER_IN_FAILED);
        }
    } else {
        if (msg.value == requestedAmountClose) {
            uint256 supplyError = supplyEther(
                localResults.closeBorrowAmount_TargetUnderwaterAsset
            );
            if (localResults.reimburseAmount > 0) {
                revertEtherToUser(
                    localResults.liquidator,
                    localResults.reimburseAmount
                );
            }
            if (supplyError != 0) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    Error.WETH_ADDRESS_NOT_SET_ERROR,
                    FailureInfo.WETH_ADDRESS_NOT_SET_ERROR
                );
            }
        } else {
            revertEtherToUser(msg.sender, msg.value);
            return
            fail(
                Error.ETHER_AMOUNT_MISMATCH_ERROR,
                FailureInfo.ETHER_AMOUNT_MISMATCH_ERROR
            );
        }
    }
    supplyOriginationFeeAsAdmin(
        assetBorrow,
        localResults.liquidator,
        localResults.closeBorrowAmount_TargetUnderwaterAsset,
        localResults.newSupplyIndex_UnderwaterAsset
    );
    emit BorrowLiquidated(
        localResults.targetAccount,
        localResults.assetBorrow,
        localResults.currentBorrowBalance_TargetUnderwaterAsset,
        localResults.closeBorrowAmount_TargetUnderwaterAsset,
        localResults.liquidator,
        localResults.assetCollateral,
        localResults.seizeSupplyAmount_TargetCollateralAsset
    );
    return uint256(Error.NO_ERROR); 
}

function repayBorrow(address asset, uint256 amount)
public
payable
nonReentrant
returns(uint256) {
    if (paused) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            Error.CONTRACT_PAUSED,
            FailureInfo.REPAY_BORROW_CONTRACT_PAUSED
        );
    }
    refreshAlkIndex(asset, msg.sender, false, true);
    PayBorrowLocalVars memory localResults;
    Market storage market = markets[asset];
    Balance storage borrowBalance = borrowBalances[msg.sender][asset];
    Error err;
    uint256 rateCalculationResultCode;
    (err, localResults.newBorrowIndex) = calculateInterestIndex(
        market.borrowIndex,
        market.borrowRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_BORROW_INDEX_CALCULATION_FAILED
        );
    }
    (err, localResults.userBorrowCurrent) = calculateBalance(
        borrowBalance.principal,
        borrowBalance.interestIndex,
        localResults.newBorrowIndex
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo
            .REPAY_BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED
        );
    }
    uint256 reimburseAmount;
    if (asset != wethAddress) {
        if (amount == uint256(-1)) {
            localResults.repayAmount = min(
                getBalanceOf(asset, msg.sender),
                localResults.userBorrowCurrent
            );
        } else {
            localResults.repayAmount = amount;
        }
    } else {
        if (amount > localResults.userBorrowCurrent) {
            localResults.repayAmount = localResults.userBorrowCurrent;
            (err, reimburseAmount) = sub(
                amount,
                localResults.userBorrowCurrent
            ); 
            if (err != Error.NO_ERROR) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    err,
                    FailureInfo
                    .REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
                );
            }
        } else {
            localResults.repayAmount = amount;
        }
    }
    (err, localResults.userBorrowUpdated) = sub(
        localResults.userBorrowCurrent,
        localResults.repayAmount
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo
            .REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
        );
    }
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = checkTransferIn(asset, msg.sender, localResults.repayAmount);
        if (err != Error.NO_ERROR) {
            return
            fail(
                err,
                FailureInfo.REPAY_BORROW_TRANSFER_IN_NOT_POSSIBLE
            );
        }
    }
    (err, localResults.newTotalBorrows) = addThenSub(
        market.totalBorrows,
        localResults.userBorrowUpdated,
        borrowBalance.principal
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_TOTAL_BORROW_CALCULATION_FAILED
        );
    }
    localResults.currentCash = getCash(asset);
    (err, localResults.updatedCash) = add(
        localResults.currentCash,
        localResults.repayAmount
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_TOTAL_CASH_CALCULATION_FAILED
        );
    }
    (err, localResults.newSupplyIndex) = calculateInterestIndex(
        market.supplyIndex,
        market.supplyRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.REPAY_BORROW_NEW_SUPPLY_INDEX_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newSupplyRateMantissa) = market
        .interestRateModel
        .getSupplyRate(
            asset,
            localResults.updatedCash,
            localResults.newTotalBorrows
        );
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.REPAY_BORROW_NEW_SUPPLY_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    (rateCalculationResultCode, localResults.newBorrowRateMantissa) = market
        .interestRateModel
        .getBorrowRate(
            asset,
            localResults.updatedCash,
            localResults.newTotalBorrows
        );
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.REPAY_BORROW_NEW_BORROW_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    market.blockNumber = block.number;
    market.totalBorrows = localResults.newTotalBorrows;
    market.supplyRateMantissa = localResults.newSupplyRateMantissa;
    market.supplyIndex = localResults.newSupplyIndex;
    market.borrowRateMantissa = localResults.newBorrowRateMantissa;
    market.borrowIndex = localResults.newBorrowIndex;
    localResults.startingBalance = borrowBalance.principal; 
    borrowBalance.principal = localResults.userBorrowUpdated;
    borrowBalance.interestIndex = localResults.newBorrowIndex;
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = doTransferIn(asset, msg.sender, localResults.repayAmount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.REPAY_BORROW_TRANSFER_IN_FAILED);
        }
    } else {
        if (msg.value == amount) {
            uint256 supplyError = supplyEther(localResults.repayAmount);
            if (reimburseAmount > 0) {
                revertEtherToUser(msg.sender, reimburseAmount);
            }
            if (supplyError != 0) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    Error.WETH_ADDRESS_NOT_SET_ERROR,
                    FailureInfo.WETH_ADDRESS_NOT_SET_ERROR
                );
            }
        } else {
            revertEtherToUser(msg.sender, msg.value);
            return
            fail(
                Error.ETHER_AMOUNT_MISMATCH_ERROR,
                FailureInfo.ETHER_AMOUNT_MISMATCH_ERROR
            );
        }
    }
    supplyOriginationFeeAsAdmin(
        asset,
        msg.sender,
        localResults.repayAmount,
        market.supplyIndex
    );
    emit BorrowRepaid(
        msg.sender,
        asset,
        localResults.repayAmount,
        localResults.startingBalance,
        borrowBalance.principal
    );
    return uint256(Error.NO_ERROR); 
}

function supply(address asset, uint256 amount)
public
payable
nonReentrant
onlyCustomerWithKYC
returns(uint256) {
    if (paused) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(Error.CONTRACT_PAUSED, FailureInfo.SUPPLY_CONTRACT_PAUSED);
    }
    refreshAlkIndex(asset, msg.sender, true, true);
    Market storage market = markets[asset];
    Balance storage balance = supplyBalances[msg.sender][asset];
    SupplyLocalVars memory localResults; 
    Error err; 
    uint256 rateCalculationResultCode; 
    if (!market.isSupported) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            Error.MARKET_NOT_SUPPORTED,
            FailureInfo.SUPPLY_MARKET_NOT_SUPPORTED
        );
    }
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = checkTransferIn(asset, msg.sender, amount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.SUPPLY_TRANSFER_IN_NOT_POSSIBLE);
        }
    }
    (err, localResults.newSupplyIndex) = calculateInterestIndex(
        market.supplyIndex,
        market.supplyRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_SUPPLY_INDEX_CALCULATION_FAILED
        );
    }
    (err, localResults.userSupplyCurrent) = calculateBalance(
        balance.principal,
        balance.interestIndex,
        localResults.newSupplyIndex
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_ACCUMULATED_BALANCE_CALCULATION_FAILED
        );
    }
    (err, localResults.userSupplyUpdated) = add(
        localResults.userSupplyCurrent,
        amount
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_TOTAL_BALANCE_CALCULATION_FAILED
        );
    }
    (err, localResults.newTotalSupply) = addThenSub(
        market.totalSupply,
        localResults.userSupplyUpdated,
        balance.principal
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_TOTAL_SUPPLY_CALCULATION_FAILED
        );
    }
    localResults.currentCash = getCash(asset);
    (err, localResults.updatedCash) = add(localResults.currentCash, amount);
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(err, FailureInfo.SUPPLY_NEW_TOTAL_CASH_CALCULATION_FAILED);
    }
    (rateCalculationResultCode, localResults.newSupplyRateMantissa) = market
        .interestRateModel
        .getSupplyRate(asset, localResults.updatedCash, market.totalBorrows);
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.SUPPLY_NEW_SUPPLY_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    (err, localResults.newBorrowIndex) = calculateInterestIndex(
        market.borrowIndex,
        market.borrowRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        revertEtherToUser(msg.sender, msg.value);
        return
        fail(
            err,
            FailureInfo.SUPPLY_NEW_BORROW_INDEX_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newBorrowRateMantissa) = market
        .interestRateModel
        .getBorrowRate(asset, localResults.updatedCash, market.totalBorrows);
    if (rateCalculationResultCode != 0) {
        revertEtherToUser(msg.sender, msg.value);
        return
        failOpaque(
            FailureInfo.SUPPLY_NEW_BORROW_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    market.blockNumber = block.number;
    market.totalSupply = localResults.newTotalSupply;
    market.supplyRateMantissa = localResults.newSupplyRateMantissa;
    market.supplyIndex = localResults.newSupplyIndex;
    market.borrowRateMantissa = localResults.newBorrowRateMantissa;
    market.borrowIndex = localResults.newBorrowIndex;
    localResults.startingBalance = balance.principal; 
    balance.principal = localResults.userSupplyUpdated;
    balance.interestIndex = localResults.newSupplyIndex;
    if (asset != wethAddress) {
        revertEtherToUser(msg.sender, msg.value);
        err = doTransferIn(asset, msg.sender, amount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.SUPPLY_TRANSFER_IN_FAILED);
        }
    } else {
        if (msg.value == amount) {
            uint256 supplyError = supplyEther(msg.value);
            if (supplyError != 0) {
                revertEtherToUser(msg.sender, msg.value);
                return
                fail(
                    Error.WETH_ADDRESS_NOT_SET_ERROR,
                    FailureInfo.WETH_ADDRESS_NOT_SET_ERROR
                );
            }
        } else {
            revertEtherToUser(msg.sender, msg.value);
            return
            fail(
                Error.ETHER_AMOUNT_MISMATCH_ERROR,
                FailureInfo.ETHER_AMOUNT_MISMATCH_ERROR
            );
        }
    }
    emit SupplyReceived(
        msg.sender,
        asset,
        amount,
        localResults.startingBalance,
        balance.principal
    );
    return uint256(Error.NO_ERROR); 
}

function _supportMarket(address asset, InterestRateModel interestRateModel)
public
onlyOwner
returns(uint256) {
    require(
        interestRateModel != address(0) &&
        collateralMarkets.length < 16, 
        "INPUT_VALIDATION_FAILED"
    );
    (Error err, Exp memory assetPrice) = fetchAssetPrice(asset);
    if (err != Error.NO_ERROR) {
        return fail(err, FailureInfo.SUPPORT_MARKET_FETCH_PRICE_FAILED);
    }
    if (isZeroExp(assetPrice)) {
        return
        fail(
            Error.ASSET_NOT_PRICED,
            FailureInfo.SUPPORT_MARKET_PRICE_CHECK
        );
    }
    markets[asset].interestRateModel = interestRateModel;
    addCollateralMarket(asset);
    markets[asset].isSupported = true;
    if (markets[asset].supplyIndex == 0) {
        markets[asset].supplyIndex = initialInterestIndex;
    }
    if (markets[asset].borrowIndex == 0) {
        markets[asset].borrowIndex = initialInterestIndex;
    }
    return uint256(Error.NO_ERROR);
}

function _withdrawEquity(address asset, uint256 amount)
public
onlyOwner
returns(uint256) {
    uint256 cash = getCash(asset);
    (
        uint256 supplyWithInterest,
        uint256 borrowWithInterest
    ) = getMarketBalances(asset);
    (Error err0, uint256 equity) = addThenSub(
        getCash(asset),
        borrowWithInterest,
        supplyWithInterest
    );
    if (err0 != Error.NO_ERROR) {
        return fail(err0, FailureInfo.EQUITY_WITHDRAWAL_CALCULATE_EQUITY);
    }
    if (amount > equity) {
        return
        fail(
            Error.EQUITY_INSUFFICIENT_BALANCE,
            FailureInfo.EQUITY_WITHDRAWAL_AMOUNT_VALIDATION
        );
    }
    if (asset != wethAddress) {
        Error err2 = doTransferOut(asset, admin, amount);
        if (err2 != Error.NO_ERROR) {
            return
            fail(
                err2,
                FailureInfo.EQUITY_WITHDRAWAL_TRANSFER_OUT_FAILED
            );
        }
    } else {
        withdrawEther(admin, amount); 
    }
    (, markets[asset].supplyRateMantissa) = markets[asset]
        .interestRateModel
        .getSupplyRate(asset, cash - amount, markets[asset].totalSupply);
    (, markets[asset].borrowRateMantissa) = markets[asset]
        .interestRateModel
        .getBorrowRate(asset, cash - amount, markets[asset].totalBorrows);
    emit EquityWithdrawn(asset, equity, amount, admin);
    return uint256(Error.NO_ERROR); 
}

function borrow(address asset, uint256 amount)
public
nonReentrant
onlyCustomerWithKYC
returns(uint256) {
    if (paused) {
        return
        fail(Error.CONTRACT_PAUSED, FailureInfo.BORROW_CONTRACT_PAUSED);
    }
    refreshAlkIndex(asset, msg.sender, false, true);
    BorrowLocalVars memory localResults;
    Market storage market = markets[asset];
    Balance storage borrowBalance = borrowBalances[msg.sender][asset];
    Error err;
    uint256 rateCalculationResultCode;
    if (!market.isSupported) {
        return
        fail(
            Error.MARKET_NOT_SUPPORTED,
            FailureInfo.BORROW_MARKET_NOT_SUPPORTED
        );
    }
    (err, localResults.newBorrowIndex) = calculateInterestIndex(
        market.borrowIndex,
        market.borrowRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_NEW_BORROW_INDEX_CALCULATION_FAILED
        );
    }
    (err, localResults.userBorrowCurrent) = calculateBalance(
        borrowBalance.principal,
        borrowBalance.interestIndex,
        localResults.newBorrowIndex
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED
        );
    }
    (err, localResults.borrowAmountWithFee) = calculateBorrowAmountWithFee(
        amount
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_ORIGINATION_FEE_CALCULATION_FAILED
        );
    }
    uint256 orgFeeBalance = localResults.borrowAmountWithFee - amount;
    (err, localResults.userBorrowUpdated) = add(
        localResults.userBorrowCurrent,
        localResults.borrowAmountWithFee
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
        );
    }
    (err, localResults.newTotalBorrows) = addThenSub(
        market.totalBorrows,
        localResults.userBorrowUpdated,
        borrowBalance.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_NEW_TOTAL_BORROW_CALCULATION_FAILED
        );
    }
    (
        err,
        localResults.accountLiquidity,
        localResults.accountShortfall
    ) = calculateAccountLiquidity(msg.sender);
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_ACCOUNT_LIQUIDITY_CALCULATION_FAILED
        );
    }
    if (!isZeroExp(localResults.accountShortfall)) {
        return
        fail(
            Error.INSUFFICIENT_LIQUIDITY,
            FailureInfo.BORROW_ACCOUNT_SHORTFALL_PRESENT
        );
    }
    (
        err,
        localResults.ethValueOfBorrowAmountWithFee
    ) = getPriceForAssetAmount(
        asset,
        localResults.borrowAmountWithFee,
        true
    );
    if (err != Error.NO_ERROR) {
        return
        fail(err, FailureInfo.BORROW_AMOUNT_VALUE_CALCULATION_FAILED);
    }
    if (
        lessThanExp(
            localResults.accountLiquidity,
            localResults.ethValueOfBorrowAmountWithFee
        )
    ) {
        return
        fail(
            Error.INSUFFICIENT_LIQUIDITY,
            FailureInfo.BORROW_AMOUNT_LIQUIDITY_SHORTFALL
        );
    }
    localResults.currentCash = getCash(asset);
    (err, localResults.updatedCash) = sub(localResults.currentCash, amount);
    if (err != Error.NO_ERROR) {
        return
        fail(
            Error.TOKEN_INSUFFICIENT_CASH,
            FailureInfo.BORROW_NEW_TOTAL_CASH_CALCULATION_FAILED
        );
    }
    (err, localResults.newSupplyIndex) = calculateInterestIndex(
        market.supplyIndex,
        market.supplyRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.BORROW_NEW_SUPPLY_INDEX_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newSupplyRateMantissa) = market
        .interestRateModel
        .getSupplyRate(
            asset,
            localResults.updatedCash,
            localResults.newTotalBorrows
        );
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo.BORROW_NEW_SUPPLY_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    (rateCalculationResultCode, localResults.newBorrowRateMantissa) = market
        .interestRateModel
        .getBorrowRate(
            asset,
            localResults.updatedCash,
            localResults.newTotalBorrows
        );
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo.BORROW_NEW_BORROW_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    market.blockNumber = block.number;
    market.totalBorrows = localResults.newTotalBorrows;
    market.supplyRateMantissa = localResults.newSupplyRateMantissa;
    market.supplyIndex = localResults.newSupplyIndex;
    market.borrowRateMantissa = localResults.newBorrowRateMantissa;
    market.borrowIndex = localResults.newBorrowIndex;
    localResults.startingBalance = borrowBalance.principal; 
    borrowBalance.principal = localResults.userBorrowUpdated;
    borrowBalance.interestIndex = localResults.newBorrowIndex;
    originationFeeBalance[msg.sender][asset] += orgFeeBalance;
    if (asset != wethAddress) {
        err = doTransferOut(asset, msg.sender, amount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.BORROW_TRANSFER_OUT_FAILED);
        }
    } else {
        withdrawEther(msg.sender, amount); 
    }
    emit BorrowTaken(
        msg.sender,
        asset,
        amount,
        localResults.startingBalance,
        localResults.borrowAmountWithFee,
        borrowBalance.principal
    );
    return uint256(Error.NO_ERROR); 
}

function withdraw(address asset, uint256 requestedAmount)
public
nonReentrant
returns(uint256) {
    if (paused) {
        return
        fail(
            Error.CONTRACT_PAUSED,
            FailureInfo.WITHDRAW_CONTRACT_PAUSED
        );
    }
    refreshAlkIndex(asset, msg.sender, true, true);
    Market storage market = markets[asset];
    Balance storage supplyBalance = supplyBalances[msg.sender][asset];
    WithdrawLocalVars memory localResults; 
    Error err; 
    uint256 rateCalculationResultCode; 
    (
        err,
        localResults.accountLiquidity,
        localResults.accountShortfall
    ) = calculateAccountLiquidity(msg.sender);
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.WITHDRAW_ACCOUNT_LIQUIDITY_CALCULATION_FAILED
        );
    }
    (err, localResults.newSupplyIndex) = calculateInterestIndex(
        market.supplyIndex,
        market.supplyRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.WITHDRAW_NEW_SUPPLY_INDEX_CALCULATION_FAILED
        );
    }
    (err, localResults.userSupplyCurrent) = calculateBalance(
        supplyBalance.principal,
        supplyBalance.interestIndex,
        localResults.newSupplyIndex
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.WITHDRAW_ACCUMULATED_BALANCE_CALCULATION_FAILED
        );
    }
    if (requestedAmount == uint256(-1)) {
        (err, localResults.withdrawCapacity) = getAssetAmountForValue(
            asset,
            localResults.accountLiquidity
        );
        if (err != Error.NO_ERROR) {
            return
            fail(err, FailureInfo.WITHDRAW_CAPACITY_CALCULATION_FAILED);
        }
        localResults.withdrawAmount = min(
            localResults.withdrawCapacity,
            localResults.userSupplyCurrent
        );
    } else {
        localResults.withdrawAmount = requestedAmount;
    }
    localResults.currentCash = getCash(asset);
    (err, localResults.updatedCash) = sub(
        localResults.currentCash,
        localResults.withdrawAmount
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            Error.TOKEN_INSUFFICIENT_CASH,
            FailureInfo.WITHDRAW_TRANSFER_OUT_NOT_POSSIBLE
        );
    }
    (err, localResults.userSupplyUpdated) = sub(
        localResults.userSupplyCurrent,
        localResults.withdrawAmount
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            Error.INSUFFICIENT_BALANCE,
            FailureInfo.WITHDRAW_NEW_TOTAL_BALANCE_CALCULATION_FAILED
        );
    }
    if (!isZeroExp(localResults.accountShortfall)) {
        return
        fail(
            Error.INSUFFICIENT_LIQUIDITY,
            FailureInfo.WITHDRAW_ACCOUNT_SHORTFALL_PRESENT
        );
    }
    (err, localResults.ethValueOfWithdrawal) = getPriceForAssetAmount(
        asset,
        localResults.withdrawAmount,
        false
    ); 
    if (err != Error.NO_ERROR) {
        return
        fail(err, FailureInfo.WITHDRAW_AMOUNT_VALUE_CALCULATION_FAILED);
    }
    if (
        lessThanExp(
            localResults.accountLiquidity,
            localResults.ethValueOfWithdrawal
        )
    ) {
        return
        fail(
            Error.INSUFFICIENT_LIQUIDITY,
            FailureInfo.WITHDRAW_AMOUNT_LIQUIDITY_SHORTFALL
        );
    }
    (err, localResults.newTotalSupply) = addThenSub(
        market.totalSupply,
        localResults.userSupplyUpdated,
        supplyBalance.principal
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.WITHDRAW_NEW_TOTAL_SUPPLY_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newSupplyRateMantissa) = market
        .interestRateModel
        .getSupplyRate(asset, localResults.updatedCash, market.totalBorrows);
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo.WITHDRAW_NEW_SUPPLY_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    (err, localResults.newBorrowIndex) = calculateInterestIndex(
        market.borrowIndex,
        market.borrowRateMantissa,
        market.blockNumber,
        block.number
    );
    if (err != Error.NO_ERROR) {
        return
        fail(
            err,
            FailureInfo.WITHDRAW_NEW_BORROW_INDEX_CALCULATION_FAILED
        );
    }
    (rateCalculationResultCode, localResults.newBorrowRateMantissa) = market
        .interestRateModel
        .getBorrowRate(asset, localResults.updatedCash, market.totalBorrows);
    if (rateCalculationResultCode != 0) {
        return
        failOpaque(
            FailureInfo.WITHDRAW_NEW_BORROW_RATE_CALCULATION_FAILED,
            rateCalculationResultCode
        );
    }
    market.blockNumber = block.number;
    market.totalSupply = localResults.newTotalSupply;
    market.supplyRateMantissa = localResults.newSupplyRateMantissa;
    market.supplyIndex = localResults.newSupplyIndex;
    market.borrowRateMantissa = localResults.newBorrowRateMantissa;
    market.borrowIndex = localResults.newBorrowIndex;
    localResults.startingBalance = supplyBalance.principal; 
    supplyBalance.principal = localResults.userSupplyUpdated;
    supplyBalance.interestIndex = localResults.newSupplyIndex;
    if (asset != wethAddress) {
        err = doTransferOut(asset, msg.sender, localResults.withdrawAmount);
        if (err != Error.NO_ERROR) {
            return fail(err, FailureInfo.WITHDRAW_TRANSFER_OUT_FAILED);
        }
    } else {
        withdrawEther(msg.sender, localResults.withdrawAmount); 
    }
    emit SupplyWithdrawn(
        msg.sender,
        asset,
        localResults.withdrawAmount,
        localResults.startingBalance,
        supplyBalance.principal
    );
    return uint256(Error.NO_ERROR); 
}

function supplyOriginationFeeAsAdmin(
    address asset,
    address user,
    uint256 amount,
    uint256 newSupplyIndex
) private {
    refreshAlkIndex(asset, admin, true, true);
    uint256 originationFeeRepaid = 0;
    if (originationFeeBalance[user][asset] != 0) {
        if (amount < originationFeeBalance[user][asset]) {
            originationFeeRepaid = amount;
        } else {
            originationFeeRepaid = originationFeeBalance[user][asset];
        }
        Balance storage balance = supplyBalances[admin][asset];
        SupplyLocalVars memory localResults; 
        Error err; 
        originationFeeBalance[user][asset] -= originationFeeRepaid;
        (err, localResults.userSupplyCurrent) = calculateBalance(
            balance.principal,
            balance.interestIndex,
            newSupplyIndex
        );
        revertIfError(err);
        (err, localResults.userSupplyUpdated) = add(
            localResults.userSupplyCurrent,
            originationFeeRepaid
        );
        revertIfError(err);
        (err, localResults.newTotalSupply) = addThenSub(
            markets[asset].totalSupply,
            localResults.userSupplyUpdated,
            balance.principal
        );
        revertIfError(err);
        markets[asset].totalSupply = localResults.newTotalSupply;
        localResults.startingBalance = balance.principal;
        balance.principal = localResults.userSupplyUpdated;
        balance.interestIndex = newSupplyIndex;
        emit SupplyReceived(
            admin,
            asset,
            originationFeeRepaid,
            localResults.startingBalance,
            localResults.userSupplyUpdated
        );
    }
}

function initialize(
    uint256 _requiredSignatures,
    address[] _initialValidators,
    address[] _initialRewards,
    address _owner
) external onlyRelevantSender returns(bool) {
    require(!isInitialized());
    require(_owner != address(0));
    setOwner(_owner);
    require(_requiredSignatures != 0);
    require(_initialValidators.length >= _requiredSignatures);
    require(_initialValidators.length == _initialRewards.length);
    for (uint256 i = 0; i < _initialValidators.length; i++) {
        require(_initialValidators[i] != address(0) && _initialValidators[i] != F_ADDR);
        require(_initialRewards[i] != address(0));
        require(!isValidator(_initialValidators[i]));
        if (i == 0) {
            setNextValidator(F_ADDR, _initialValidators[i]);
            if (_initialValidators.length == 1) {
                setNextValidator(_initialValidators[i], F_ADDR);
            }
        } else if (i == _initialValidators.length - 1) {
            setNextValidator(_initialValidators[i - 1], _initialValidators[i]);
            setNextValidator(_initialValidators[i], F_ADDR);
        } else {
            setNextValidator(_initialValidators[i - 1], _initialValidators[i]);
        }
        setValidatorRewardAddress(_initialValidators[i], _initialRewards[i]);
        emit ValidatorAdded(_initialValidators[i]);
    }
    setValidatorCount(_initialValidators.length);
    uintStorage[REQUIRED_SIGNATURES] = _requiredSignatures;
    uintStorage[DEPLOYED_AT_BLOCK] = block.number;
    setInitialize();
    emit RequiredSignaturesChanged(_requiredSignatures);
    return isInitialized();
}

function calculateValue(uint256 _ethValue, uint8 decimals) view public returns(uint256 tokensValue) {
    uint8 TokensPerEthereum = 10;
    uint8 additionalBonusPercent = 10;
    if (_ethValue > 3 * 10 ** 17)
        additionalBonusPercent = 25;
    if (_ethValue > 10 ** 18)
        additionalBonusPercent = 30;
    if (_ethValue > 5 * 10 ** 18)
        additionalBonusPercent = 60;
    tokensValue = _ethValue * TokensPerEthereum;
    tokensValue += (tokensValue * additionalBonusPercent) / 100;
    if (decimals < 18) {
        uint256 difference = 18 - uint256(decimals);
        tokensValue = tokensValue / 10 ** difference;
    } else if (decimals > 18) {
        difference = uint256(decimals) - 18;
        tokensValue = tokensValue * 10 ** difference;
    }
    if (_ethValue > 10 ** 18)
        tokensValue += 3 * 10 ** (uint256(decimals) - 2);
    if (now <= doubleRewardEndTime)
        tokensValue *= 2;
}

