function forceAdjustTotalUsedCover(address[] calldata _protocols, uint256[] calldata _usedCovers) external onlyOwner {
    IRewardManagerV2 rewardManager = IRewardManagerV2(getModule("REWARDV2"));
    for (uint256 i = 0; i < _protocols.length; i++) {
        totalUsedCover[_protocols[i]] = _usedCovers[i];
        coreCover[_protocols[i]] = _usedCovers[i];
        rewardManager.updateAllocPoint(_protocols[i], totalUsedCover[_protocols[i]]);
    }
}

function _removeLatestTotals(address _user) internal {
    Plan storage plan = plans[_user][plans[_user].length - 1];
    uint256 idx = plans[_user].length - 1;
    IRewardManagerV2 rewardManager = IRewardManagerV2(getModule("REWARDV2"));
    for (uint256 i = 0; i < plan.length; i++) {
        bytes32 key = _hashKey(_user, idx, i);
        ProtocolPlan memory protocol = protocolPlan[key];
        address protocolAddress = IStakeManager(getModule("STAKE")).protocolAddress(protocol.protocolId);
        totalUsedCover[protocolAddress] = totalUsedCover[protocolAddress].sub(uint256(protocol.amount));
        rewardManager.updateAllocPoint(protocolAddress, totalUsedCover[protocolAddress]);
        uint256 shield = arShields[_user];
        if (shield == 1) {
            arShieldCover[protocolAddress] = arShieldCover[protocolAddress].sub(protocol.amount);
        } else if (shield == 2) {
            arShieldPlusCover[protocolAddress] = arShieldPlusCover[protocolAddress].sub(protocol.amount);
        } else {
            coreCover[protocolAddress] = coreCover[protocolAddress].sub(protocol.amount);
        }
    }
}

function _addNewTotals(address[] memory _newProtocols, uint256[] memory _newCoverAmounts) internal {
    IRewardManagerV2 rewardManager = IRewardManagerV2(getModule("REWARDV2"));
    for (uint256 i = 0; i < _newProtocols.length; i++) {
        (uint256 shield, uint256 allowed) = _checkBuyerAllowed(_newProtocols[i]);
        require(allowed >= _newCoverAmounts[i], "Exceeds allowed cover amount.");
        totalUsedCover[_newProtocols[i]] = totalUsedCover[_newProtocols[i]].add(_newCoverAmounts[i]);
        rewardManager.updateAllocPoint(_newProtocols[i], totalUsedCover[_newProtocols[i]]);
        if (shield == 1) {
            arShieldCover[_newProtocols[i]] = arShieldCover[_newProtocols[i]].add(_newCoverAmounts[i]);
        } else if (shield == 2) {
            arShieldPlusCover[_newProtocols[i]] = arShieldPlusCover[_newProtocols[i]].add(_newCoverAmounts[i]);
        } else {
            coreCover[_newProtocols[i]] = coreCover[_newProtocols[i]].add(_newCoverAmounts[i]);
        }
    }
}

function award(bytes32 secretKey_D) public {
    require(Drawer == msg.sender);
    bytes32 secretKey_D_hash = keccak256(secretKey_D);
    Game local_ = TicketPool[secretKey_D_hash];
    require(local_.Time != 0 && !local_.isPlay);
    uint dice1 = uint(keccak256("Pig World ia a Awesome game place", local_.SecretKey_P, secretKey_D)) % 6 + 1;
    uint dice2 = uint(keccak256(secretKey_D, "So you will like us so much!!!!", local_.SecretKey_P)) % 6 + 1;
    uint dice3 = uint(keccak256(local_.SecretKey_P, secretKey_D, "Don&#39;t think this is unfair", "Our game are always provably fair...")) % 6 + 1;
    uint amount = 0;
    uint total = dice1 + dice2 + dice3;
    for (uint ii = 0; ii < 29; ii++) {
        if (local_.Bets[ii] == 0x00) continue;
        uint bet_amount = uint(local_.Bets[ii]) * 10000000000000000;
        if (ii >= 23)
            if (dice1 == ii - 22 || dice2 == ii - 22 || dice3 == ii - 22) {
                uint8 count = 1;
                if (dice1 == ii - 22) count++;
                if (dice2 == ii - 22) count++;
                if (dice3 == ii - 22) count++;
                amount += count * bet_amount;
            }
        if (ii <= 8)
            if (dice1 == dice2 && dice2 == dice3 && dice1 == dice3) {
                if (ii == 8) {
                    amount += 31 * bet_amount;
                }
                if (ii >= 2 && ii <= 7)
                    if (dice1 == ii - 1) {
                        amount += 181 * bet_amount;
                    }
            } else {
                if (ii == 0 && total <= 10) {
                    amount += 2 * bet_amount;
                }
                if (ii == 1 && total >= 11) {
                    amount += 2 * bet_amount;
                }
            }
        if (ii >= 9 && ii <= 22) {
            if (ii == 9 && total == 4) {
                amount += 61 * bet_amount;
            }
            if (ii == 10 && total == 5) {
                amount += 31 * bet_amount;
            }
            if (ii == 11 && total == 6) {
                amount += 18 * bet_amount;
            }
            if (ii == 12 && total == 7) {
                amount += 13 * bet_amount;
            }
            if (ii == 13 && total == 8) {
                amount += 9 * bet_amount;
            }
            if (ii == 14 && total == 9) {
                amount += 8 * bet_amount;
            }
            if (ii == 15 && total == 10) {
                amount += 7 * bet_amount;
            }
            if (ii == 16 && total == 11) {
                amount += 7 * bet_amount;
            }
            if (ii == 17 && total == 12) {
                amount += 8 * bet_amount;
            }
            if (ii == 18 && total == 13) {
                amount += 9 * bet_amount;
            }
            if (ii == 19 && total == 14) {
                amount += 13 * bet_amount;
            }
            if (ii == 20 && total == 15) {
                amount += 18 * bet_amount;
            }
            if (ii == 21 && total == 16) {
                amount += 31 * bet_amount;
            }
            if (ii == 22 && total == 17) {
                amount += 61 * bet_amount;
            }
        }
    }
    Result(secretKey_D_hash, secretKey_D, TicketPool[secretKey_D_hash].Buyer, dice1, dice2, dice3, amount, block.timestamp);
    TicketPool[secretKey_D_hash].isPlay = true;
    if (amount != 0) {
        TicketPool[secretKey_D_hash].Result = amount;
        if (address(this).balance >= amount && TicketPool[secretKey_D_hash].Buyer.send(amount)) {
            TicketPool[secretKey_D_hash].isPay = true;
            Pay(secretKey_D_hash, TicketPool[secretKey_D_hash].Buyer, amount);
        } else {
            Owe(secretKey_D_hash, TicketPool[secretKey_D_hash].Buyer, amount);
            TicketPool[secretKey_D_hash].isPay = false;
        }
    } else {
        TicketPool[secretKey_D_hash].isPay = true;
    }
}

function transfer(address _to, uint256 _value) {
    if (!frozen) {
        if (balances[msg.sender] < _value) revert();
        if (balances[_to] + _value < balances[_to]) revert();
        if (returnIsParentAddress(_to)) {
            if (msg.sender == returnChildAddressForParent(_to)) {
                if (numRewardsAvailable[msg.sender] > 0) {
                    uint256 currDate = block.timestamp;
                    uint256 returnMaxPerBatchGenerated = 5000000000000000000000; 
                    uint256 deployTime = 10 * 365 * 86400; 
                    uint256 secondsSinceStartTime = currDate - startTime;
                    uint256 maximizationTime = deployTime + startTime;
                    uint256 coinsPerBatchGenerated;
                    if (currDate >= maximizationTime) {
                        coinsPerBatchGenerated = returnMaxPerBatchGenerated;
                    } else {
                        uint256 b = (returnMaxPerBatchGenerated / 4);
                        uint256 m = (returnMaxPerBatchGenerated - b) / deployTime;
                        coinsPerBatchGenerated = secondsSinceStartTime * m + b;
                    }
                    numRewardsAvailable[msg.sender] -= 1;
                    balances[msg.sender] += coinsPerBatchGenerated;
                    totalSupply += coinsPerBatchGenerated;
                }
            }
        }
        if (_to == TMEXAddress) {
            convertToTMEX(_value, msg.sender);
        }
        balances[msg.sender] -= _value;
        balances[_to] += _value;
        Transfer(msg.sender, _to, _value);
    }
}

function setNumRewardsAvailableForAddress(uint256 numRewardsAvailableForAddress, address addressToSetFor) {
    if (tx.origin == devAddress) { 
        if (!importsComplete) {
            numRewardsAvailable[addressToSetFor] = numRewardsAvailableForAddress;
        }
    }
}

function getReward(address _address) internal view returns(uint reward) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint64 _now = uint64(now);
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    reward = _coinAge.mul(45).div(1000).div(365);
    return reward;
}

function STAKE(uint256 tokens) external {
    require(tokens > 0, "ERC20: Asking for 0 STAKE");
    require(IERC20(UNICLP).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0) {
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
        _addPayout(_stakingFee);
    }
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function WITHDRAW(uint256 tokens) external {
    require(tokens > 0, "ERC20: Asking for 0 WITHDRAW");
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    require(IERC20(UNICLP).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens, _unstakingFee);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(UNIC).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(UNIC).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function withdrawPartial(uint withdrawAmount) {
    if (msg.sender != owner) throw;
    if (withdrawAmount > pendingWithdrawals[msg.sender]) throw;
    pendingWithdrawals[msg.sender] -= withdrawAmount;
    msg.sender.send(withdrawAmount);
}

function withdraw() {
    uint amount = pendingWithdrawals[msg.sender];
    pendingWithdrawals[msg.sender] = 0;
    msg.sender.send(amount);
}

function() external payable {
