function init() public onlyOwner {
    require(!initialized);
    initialized = true;
    if (PAUSED) {
        MainToken(token).pause();
    }
    address[4] memory addresses = [address(0xf5af490a53e8b87ec26733d8ea39bcaf7eeeb689), address(0x4e27d74c6435b85ea56bf2d7e10b6c090a6a3e58), address(0xf5af490a53e8b87ec26733d8ea39bcaf7eeeb689), address(0xf5af490a53e8b87ec26733d8ea39bcaf7eeeb689)];
    uint[4] memory amounts = [uint(500000000000000000000000), uint(1500000000000000000000000), uint(1000000000000000000000000), uint(3000000000000000000000000)];
    uint64[4] memory freezes = [uint64(0), uint64(0), uint64(0), uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
        if (freezes[i] == 0) {
            MainToken(token).mint(addresses[i], amounts[i]);
        } else {
            MainToken(token).mintAndFreeze(addresses[i], amounts[i], freezes[i]);
        }
    }
    transferOwnership(TARGET_USER);
    emit Initialized();
}

function releaseWithStage(address _target, address _dest) onlyOwner public returns(bool) {
    require(_target != address(0));
    require(_dest != address(0));
    assert(owned.allowance(_target, this) > 0);
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address frozenAddr = frozenAccounts[i];
        if (frozenAddr == _target) {
            uint256 timeRecLen = frozenTimes[frozenAddr].length;
            bool released = false;
            for (uint256 j = 0; j < timeRecLen; released = false) {
                TimeRec storage timePair = frozenTimes[frozenAddr][j];
                uint256 nowTime = now;
                if (nowTime > timePair.endTime && timePair.endTime > 0 && timePair.duration > 0) {
                    uint256 value = timePair.amount * (nowTime - timePair.endTime) / timePair.duration;
                    if (value > timePair.remain) {
                        value = timePair.remain;
                    }
                    timePair.endTime = nowTime;
                    timePair.remain = timePair.remain.sub(value);
                    if (timePair.remain < 1e8) {
                        if (!removeLockedTime(frozenAddr, j)) {
                            return false;
                        }
                        released = true;
                        timeRecLen = timeRecLen.sub(1);
                    }
                    ReleaseFunds(frozenAddr, value);
                    preReleaseAmounts[frozenAddr] = preReleaseAmounts[frozenAddr].add(value);
                } else if (nowTime >= timePair.endTime && timePair.endTime > 0 && timePair.duration == 0) {
                    if (!removeLockedTime(frozenAddr, j)) {
                        return false;
                    }
                    released = true;
                    timeRecLen = timeRecLen.sub(1);
                    ReleaseFunds(frozenAddr, timePair.amount);
                    preReleaseAmounts[frozenAddr] = preReleaseAmounts[frozenAddr].add(timePair.amount);
                } 
                if (!released) {
                    j = j.add(1);
                }
            }
            if (preReleaseAmounts[frozenAddr] > 0) {
                owned.freezeAccount(frozenAddr, false);
                if (!owned.transferFrom(_target, _dest, preReleaseAmounts[frozenAddr])) {
                    return false;
                }
            }
            if (frozenTimes[frozenAddr].length == 0) {
                if (!removeAccount(i)) {
                    return false;
                }
            } else {
                owned.freezeAccount(frozenAddr, true);
            }
            return true;
        }
        i = i.add(1);
    }
    return false;
}

function releaseAllOnceLock() onlyOwner public returns(bool) {
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address target = frozenAccounts[i];
        if (frozenTimes[target].length == 1 && 0 == frozenTimes[target][0].duration && frozenTimes[target][0].endTime > 0 && now >= frozenTimes[target][0].endTime) {
            bool res = removeAccount(i);
            if (!res) {
                return false;
            }
            owned.freezeAccount(target, false);
            ReleaseFunds(target, frozenTimes[target][0].amount);
            len = len.sub(1);
        } else {
            i = i.add(1);
        }
    }
    return true;
}

function changeContractOwner(address _newOwner) public onlyOwner returns(bool) {
    require(_newOwner != address(0));
    owned.transferOwnership(_newOwner);
    owned = itoken(address(0));
    return true;
}

function releaseAccount(address _target) onlyOwner public returns(bool) {
    require(_target != address(0));
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address destAddr = frozenAccounts[i];
        if (destAddr == _target) {
            if (frozenTimes[destAddr].length == 1 && 0 == frozenTimes[destAddr][0].duration && frozenTimes[destAddr][0].endTime > 0 && now >= frozenTimes[destAddr][0].endTime) {
                bool res = removeAccount(i);
                if (!res) {
                    return false;
                }
                owned.freezeAccount(destAddr, false);
                ReleaseFunds(destAddr, frozenTimes[destAddr][0].amount);
            }
            return true;
        }
        i = i.add(1);
    }
    return false;
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedAmount >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercentofTokens(tokens).mul(UnstakingFee)).div(10);
    if (amounts[msg.sender] > 0) {
        uint256 time = now - stakers[msg.sender].creationTime;
        uint256 daysCount = time.div(86400);
        if (daysCount > 0) {
            uint256 owing = (amounts[msg.sender]).mul(daysCount);
            stakers[msg.sender].reward = (stakers[msg.sender].reward).add(owing);
        }
    }
    require(tokenInstance.transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedAmount = stakers[msg.sender].stakedAmount.sub(tokens);
    if (stakers[msg.sender].stakedAmount == 0) {
        stakers[msg.sender].creationTime = 0;
        amounts[msg.sender] = 0;
    } else {
        uint256 percal = calPercentofTokens(stakers[msg.sender].stakedAmount, WeekRewardPercent);
        amounts[msg.sender] = percal;
    }
    TotalStakedOMB = TotalStakedOMB.sub(tokens);
    FeesCollectedForJustwap = FeesCollectedForJustwap.add(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function calculateReward(address user) public view returns(uint256 result) {
    uint256 time = block.timestamp - stakers[user].creationTime;
    uint256 daysCount = time.div(86400);
    if (daysCount > 0) {
        uint256 owing = 0;
        if (amounts[user] > 0) {
            uint256 a = daysCount * 86400;
            a = time.sub(a);
            owing = (amounts[user]).mul(daysCount);
            if (a != 0)
                owing = (owing.mul(a)).div(86400);
            if (stakers[user].reward > 0) {
                owing = owing.add(stakers[user].reward);
            }
        } else {
            if (stakers[user].reward > 0) {
                owing = stakers[user].reward;
            } else {
                owing = 0;
            }
        }
        return owing;
    } else {
        uint256 owing = 0;
        if (amounts[user] > 0) {
            owing = ((amounts[user]).mul(time)).div(86400);
            if (stakers[user].reward > 0) {
                owing = owing.add(stakers[user].reward);
            }
        } else {
            if (stakers[user].reward > 0) {
                owing = stakers[user].reward;
            } else {
                owing = 0;
            }
        }
        return owing;
    }
}

function STAKE(uint256 tokens) external {
    require(tokenInstance.transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (TotalStakedOMB > 0)
        _stakingFee = (onePercentofTokens(tokens).mul(StakingFee)).div(10);
    if (amounts[msg.sender] > 0) {
        uint256 time = now - stakers[msg.sender].creationTime;
        uint256 daysCount = time.div(86400);
        if (daysCount > 0) {
            uint256 owing = (amounts[msg.sender]).mul(daysCount);
            stakers[msg.sender].reward = (stakers[msg.sender].reward).add(owing);
        }
    }
    stakers[msg.sender].stakedAmount = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedAmount);
    stakers[msg.sender].creationTime = now;
    TotalStakedOMB = TotalStakedOMB.add(tokens.sub(_stakingFee));
    uint256 percal = calPercentofTokens(stakers[msg.sender].stakedAmount, WeekRewardPercent);
    amounts[msg.sender] = percal;
    TeamFeesCollector = TeamFeesCollector.add(_stakingFee);
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

