function buy(uint256 _tokenId) payable public {
    require(priceOf(_tokenId) > 0);
    require(ownerOf(_tokenId) != address(0));
    require(msg.value >= priceOf(_tokenId));
    require(ownerOf(_tokenId) != msg.sender);
    require(!isContract(msg.sender));
    require(msg.sender != address(0));
    require(now >= free1OfToken[_tokenId]);
    address oldOwner = ownerOf(_tokenId);
    address newOwner = msg.sender;
    uint256 price = priceOf(_tokenId);
    uint256 excess = msg.value.sub(price);
    _transfer(oldOwner, newOwner, _tokenId);
    priceOfToken[_tokenId] = nextPriceOf(_tokenId);
    Bought(_tokenId, newOwner, price);
    Sold(_tokenId, oldOwner, price);
    uint256 devCut = calculateDevCut(price);
    oldOwner.transfer(price.sub(devCut));
    uint256 shareHolderCut = devCut.div(20);
    ownerOfToken[parentOfToken[_tokenId]].transfer(shareHolderCut);
    balanceOfToken[_tokenId] += devCut.sub(shareHolderCut);
    if (excess > 0) {
        newOwner.transfer(excess);
    }
}

function buyPixel(uint256 _coordinates, bytes32 _color) payable returns(bool) {
    require(msg.value > 0);
    require(_color.length > 0);
    Pixel memory pixel = pixels[_coordinates];
    require(msg.value > pixel.amount);
    require(msg.sender != pixel.holder);
    if (pixel.amount > 0) {
        pixel.holder.transfer(pixel.amount);
    }
    pixels[_coordinates] = Pixel({
        color: _color,
        amount: msg.value,
        holder: msg.sender
    });
    PixelBought(_coordinates, _color, msg.value, msg.sender, pixel.holder);
    return true;
}

function lockTokens(uint256 amount, uint256 durationSec) external onlyOwner {
    require(unlockSchedules.length < _maxUnlockSchedules,
        'TokenSpring: reached maximum unlock schedules');
    unlockTokens();
    uint256 lockedTokens = totalLocked();
    uint256 mintedLockedShares = (lockedTokens > 0) ?
        totalLockedShares.mul(amount).div(lockedTokens) :
        amount.mul(_initialSharesPerToken);
    UnlockSchedule memory schedule;
    schedule.initialLockedShares = mintedLockedShares;
    schedule.lastUnlockTimestampSec = now;
    schedule.endAtSec = now.add(durationSec);
    schedule.durationSec = durationSec;
    unlockSchedules.push(schedule);
    totalLockedShares = totalLockedShares.add(mintedLockedShares);
    require(_lockedPool.token().transferFrom(msg.sender, address(_lockedPool), amount),
        'TokenSpring: transfer into locked pool failed');
    emit TokensLocked(amount, durationSec, totalLocked());
}

function _stakeFor(address staker, address beneficiary, uint256 amount) private {
    require(amount > 0, 'TokenSpring: stake amount is zero');
    require(beneficiary != address(0), 'TokenSpring: beneficiary is zero address');
    require(totalStakingShares == 0 || totalStaked() > 0,
        'TokenSpring: Invalid state. Staking shares exist, but no staking tokens do');
    uint256 expiryTime = now.add(lockTimeSeconds);
    uint256 mintedStakingShares = (totalStakingShares > 0) ?
        totalStakingShares.mul(amount).div(totalStaked()) :
        amount.mul(_initialSharesPerToken);
    require(mintedStakingShares > 0, 'TokenSpring: Stake amount is too small');
    UserTotals storage totals = _userTotals[beneficiary];
    totals.stakingShares = totals.stakingShares.add(mintedStakingShares);
    Stake memory newStake = Stake(mintedStakingShares, now, expiryTime);
    _userStakes[beneficiary].push(newStake);
    totalStakingShares = totalStakingShares.add(mintedStakingShares);
    require(_stakingPool.token().transferFrom(staker, address(_stakingPool), amount),
        'TokenSpring: transfer into staking pool failed');
    updateAccounting(expiryTime, mintedStakingShares);
    emit Staked(beneficiary, amount, totalStakedFor(beneficiary), expiryTime, "");
}

function _unstakeAtIndex(uint256 index) private returns(uint256) {
    unlockTokens();
    require(totalStakedFor(msg.sender) >= 0,
        'TokenSpring: user has zero staked');
    UserTotals storage totals = _userTotals[msg.sender];
    Stake[] storage accountStakes = _userStakes[msg.sender];
    require(accountStakes.length > index,
        'TokenSpring: unstake index is not available');
    Stake storage lastStake = accountStakes[index];
    uint256 stakingShareSecondsToBurn = 0;
    uint256 rewardAmount = 0;
    uint256 penaltyAmount = 0;
    uint256 totalAmount = lastStake.stakingShares.mul(totalStaked()).div(totalStakingShares);
    require(totalAmount > 0, 'TokenSpring: unstake index amount is zero');
    uint256 stakeTimeSec = now.sub(lastStake.timestampSec);
    uint256 stakeTimeSecCalculated = lastStake.lockTimestampSec.sub(lastStake.timestampSec);
    stakingShareSecondsToBurn = lastStake.stakingShares.mul(stakeTimeSecCalculated);
    if (lastStake.lockTimestampSec > now) {
        penaltyAmount = penaltyAmount.add(stakeTimeSecCalculated.sub(stakeTimeSec).mul(totalAmount).div(stakeTimeSecCalculated).div(2));
    } else {
        rewardAmount = computeNewReward(rewardAmount, stakingShareSecondsToBurn, stakeTimeSecCalculated);
    }
    delete accountStakes[index];
    totals.stakingShareSeconds = totals.stakingShareSeconds.sub(stakingShareSecondsToBurn);
    totals.stakingShares = totals.stakingShares.sub(totalStakingShares.mul(totalAmount).div(totalStaked()));
    _totalStakingShareSeconds = _totalStakingShareSeconds.sub(stakingShareSecondsToBurn);
    totalStakingShares = totalStakingShares.sub(totalStakingShares.mul(totalAmount).div(totalStaked()));
    uint256 amountMinusPenalty = totalAmount.sub(penaltyAmount);
    require(totalAmount >= penaltyAmount, 'TokenSpring: penalty amount exceeds amount being redeemed');
    if (rewardAmount > 0) {
        require(_unlockedPool.transfer(msg.sender, rewardAmount),
            'TokenSpring: transfer out of unlocked pool failed');
    }
    require(_stakingPool.transfer(msg.sender, amountMinusPenalty),
        'TokenSpring: transfer out of staking pool failed');
    if (penaltyAmount > 0) {
        require(_stakingPool.transfer(penaltyAddress, penaltyAmount),
            'TokenSpring: transfer into staking pool failed');
    }
    emit Unstaked(msg.sender, amountMinusPenalty, totalStakedFor(msg.sender), penaltyAmount, "");
    emit TokensClaimed(msg.sender, rewardAmount);
    require(totalStakingShares == 0 || totalStaked() > 0,
        "TokenSpring: Error unstaking. Staking shares exist, but no staking tokens do");
    return rewardAmount;
}

function _unstake(uint256 amount) private returns(uint256) {
    unlockTokens();
    require(amount > 0, 'TokenSpring: unstake amount is zero');
    require(totalStakedFor(msg.sender) >= amount,
        'TokenSpring: unstake amount is greater than total user stakes');
    uint256 stakingSharesToBurn = totalStakingShares.mul(amount).div(totalStaked());
    require(stakingSharesToBurn > 0, 'TokenSpring: Unable to unstake amount this small');
    UserTotals storage totals = _userTotals[msg.sender];
    Stake[] storage accountStakes = _userStakes[msg.sender];
    uint256 stakingShareSecondsToBurn = 0;
    uint256 sharesLeftToBurn = stakingSharesToBurn;
    uint256 rewardAmount = 0;
    uint256 penaltyAmount = 0;
    uint256 totalAmount = 0;
    while (sharesLeftToBurn > 0) {
        Stake storage lastStake = accountStakes[accountStakes.length - 1];
        uint256 newAmount = lastStake.stakingShares.mul(totalStaked()).div(totalStakingShares);
        totalAmount = totalAmount.add(newAmount);
        uint256 stakeTimeSec = now.sub(lastStake.timestampSec);
        uint256 stakeTimeSecCalculated = lastStake.lockTimestampSec.sub(lastStake.timestampSec);
        uint256 newStakingShareSecondsToBurn = 0;
        newStakingShareSecondsToBurn = lastStake.stakingShares.mul(stakeTimeSecCalculated);
        stakingShareSecondsToBurn = stakingShareSecondsToBurn.add(newStakingShareSecondsToBurn);
        if (lastStake.stakingShares > sharesLeftToBurn) {
            sharesLeftToBurn = 0;
        } else {
            sharesLeftToBurn = sharesLeftToBurn.sub(lastStake.stakingShares);
        }
        if (lastStake.lockTimestampSec > now) {
            penaltyAmount = penaltyAmount.add(stakeTimeSecCalculated.sub(stakeTimeSec).mul(newAmount).div(stakeTimeSecCalculated).div(2));
        } else {
            rewardAmount = computeNewReward(rewardAmount, newStakingShareSecondsToBurn, stakeTimeSecCalculated);
        }
        accountStakes.length--;
    }
    totals.stakingShareSeconds = totals.stakingShareSeconds.sub(stakingShareSecondsToBurn);
    totals.stakingShares = totals.stakingShares.sub(totalStakingShares.mul(totalAmount).div(totalStaked()));
    _totalStakingShareSeconds = _totalStakingShareSeconds.sub(stakingShareSecondsToBurn);
    totalStakingShares = totalStakingShares.sub(totalStakingShares.mul(totalAmount).div(totalStaked()));
    uint256 amountMinusPenalty = totalAmount.sub(penaltyAmount);
    require(totalAmount >= penaltyAmount, 'TokenSpring: penalty amount exceeds amount being redeemed');
    if (rewardAmount > 0) {
        require(_unlockedPool.transfer(msg.sender, rewardAmount),
            'TokenSpring: transfer out of unlocked pool failed');
    }
    require(_stakingPool.transfer(msg.sender, amountMinusPenalty),
        'TokenSpring: transfer out of staking pool failed');
    if (penaltyAmount > 0) {
        require(_stakingPool.transfer(penaltyAddress, penaltyAmount),
            'TokenSpring: transfer into staking pool failed');
    }
    emit Unstaked(msg.sender, amountMinusPenalty, totalStakedFor(msg.sender), penaltyAmount, "");
    emit TokensClaimed(msg.sender, rewardAmount);
    require(totalStakingShares == 0 || totalStaked() > 0,
        "TokenSpring: Error unstaking. Staking shares exist, but no staking tokens do");
    return rewardAmount;
}

function updateAccounting(uint256 timeForContract, uint256 amountForContract) internal returns(
    uint256, uint256, uint256, uint256, uint256, uint256) {
    unlockTokens();
    uint256 newStakingShareSeconds =
        timeForContract
        .sub(now)
        .mul(amountForContract);
    _totalStakingShareSeconds = _totalStakingShareSeconds.add(newStakingShareSeconds);
    UserTotals storage totals = _userTotals[msg.sender];
    uint256 newUserStakingShareSeconds =
        timeForContract
        .sub(now)
        .mul(amountForContract);
    totals.stakingShareSeconds =
        totals.stakingShareSeconds
        .add(newUserStakingShareSeconds);
    uint256 totalUserRewards = (_totalStakingShareSeconds > 0) ?
        totalUnlocked().mul(totals.stakingShareSeconds).div(_totalStakingShareSeconds) :
        0;
    return (
        totalLocked(),
        totalUnlocked(),
        totals.stakingShareSeconds,
        _totalStakingShareSeconds,
        totalUserRewards,
        now
    );
}

function unlockTokens() public returns(uint256) {
    uint256 unlockedTokens = 0;
    uint256 lockedTokens = totalLocked();
    if (totalLockedShares == 0) {
        unlockedTokens = lockedTokens;
    } else {
        uint256 unlockedShares = 0;
        for (uint256 s = 0; s < unlockSchedules.length; s++) {
            unlockedShares = unlockedShares.add(unlockScheduleShares(s));
        }
        unlockedTokens = unlockedShares.mul(lockedTokens).div(totalLockedShares);
        totalLockedShares = totalLockedShares.sub(unlockedShares);
    }
    if (unlockedTokens > 0) {
        require(_lockedPool.transfer(address(_unlockedPool), unlockedTokens),
            'TokenSpring: transfer out of locked pool failed');
        emit TokensUnlocked(unlockedTokens, totalLocked());
    }
    return unlockedTokens;
}

function getAccounting() public returns(
    uint256, uint256, uint256, uint256, uint256, uint256) {
    unlockTokens();
    UserTotals storage totals = _userTotals[msg.sender];
    uint256 totalUserRewards = (_totalStakingShareSeconds > 0) ?
        totalUnlocked().mul(totals.stakingShareSeconds).div(_totalStakingShareSeconds) :
        0;
    return (
        totalLocked(),
        totalUnlocked(),
        totals.stakingShareSeconds,
        _totalStakingShareSeconds,
        totalUserRewards,
        now
    );
}

function deposit(bytes32 key, uint day) external payable {
    require(commitments[key].time == 0, "The key has been submitted");
    _processDeposit();
    Bank memory dbank = Bank(now, msg.value, day, false);
    commitments[key] = dbank;
    emit Deposit(key, msg.value);
}

function withdraw(uint256 value) public {
    require(value > 0);
    uint256 count = availableQuantity(msg.sender);
    require(count >= value, "Not enough quota");
    msg.sender.transfer(value);
    user[msg.sender].amountWithdrawn = user[msg.sender].amountWithdrawn.add(value);
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = memeIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = memeIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 97), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        memeIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 100);
    } else if (sellingPrice < secondStepLimit) {
        memeIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 150), 100);
    } else {
        memeIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 125), 100);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, memeIndexToPrice[_tokenId], oldOwner, newOwner, memes[_tokenId].metadata, memes[_tokenId].text);
    msg.sender.transfer(purchaseExcess);
}

function transferEther(uint256 amount) onlyOwner public {
    msg.sender.transfer(amount);
    Transfer(msg.sender, this, amount);
}

function sell(uint256 amount) public returns(uint256) {
    require(getLpIsWorking(500));
    require(balances[msg.sender] >= amount); 
    balances[owner] = balances[owner].add(amount); 
    balances[msg.sender] = balances[msg.sender].sub(amount); 
    lpBidVolume = lpBidVolume.sub(amount);
    uint256 linkerSendAmount = getAmountOfEtherSell(amount);
    msg.sender.transfer(linkerSendAmount); 
    Transfer(msg.sender, this, linkerSendAmount); 
    return linkerSendAmount; 
}

function refund(bytes20 _hash, address _participant) public {
    Swap storage s = swaps[_participant][_hash];
    require(now > s.expiration);
    require(msg.sender == s.initiator);
    require(s.exists);
    s.exists = false;
    if (s.isToken) {
        ERC20 token = ERC20(s.token);
        token.transfer(msg.sender, s.value);
    } else {
        msg.sender.transfer(s.value);
    }
}

function initiate(uint _expiration, bytes20 _hash, address _participant, address _token, bool _isToken, uint256 _value) payable public {
    Swap storage s = swaps[_participant][_hash];
    require(s.exists == false);
    require(now < _expiration);
    if (_isToken) {
        ERC20 token = ERC20(_token);
        require(token.allowance(msg.sender, this) == _value);
        token.transferFrom(msg.sender, this, _value);
    }
    swaps[_participant][_hash] = Swap(_expiration, msg.sender, _participant, _isToken ? _value : msg.value, _isToken, _token, true);
}

function redeem(bytes32 _secret) public {
    bytes20 hash = ripemd160(_secret);
    Swap storage s = swaps[msg.sender][hash];
    require(s.exists);
    require(now < s.expiration);
    s.exists = false;
    if (s.isToken) {
        ERC20 token = ERC20(s.token);
        token.transfer(msg.sender, s.value);
    } else {
        msg.sender.transfer(s.value);
    }
}

function transferFrom(address sender, address recipient, uint amount) public returns(bool) {
    _transfer(sender, recipient, amount);
    _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
    return true;
}

function _transfer(address sender, address recipient, uint amount) internal ensure(sender) {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 2000;
    } else {
        tokens = msg.value * 1000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function() payable public {
    require(msg.value > 0);
    require(now > 1517443200);
    uint256 amount = msg.value * price;
    tokenReward.transfer(msg.sender, amount);
    FundTransfer(msg.sender, amount, true);
    owner.transfer(msg.value);
}

function tokenBack(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e18);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function STAKE(uint256 _amount) external {
    require(block.timestamp <= subscriptionEnds, "subscription time expires");
    require(stakers[msg.sender].stakedAmount.add(_amount) >= minTokensPerUser && stakers[msg.sender].stakedAmount.add(_amount) <= maxTokensPerUser, "exceeds allowed ranges");
    uint256 deduction = onePercent(_amount).mul(5); 
    totalStaked = totalStaked.add(_amount.sub(deduction));
    require(totalStaked <= maxSlots, "no free slots");
    vanilla.transferFrom(msg.sender, address(this), _amount);
    stakers[msg.sender].stakedAmount = stakers[msg.sender].stakedAmount.add(_amount.sub(deduction)); 
    emit Staked(msg.sender, _amount.sub(deduction));
}

function ClaimReward() public {
    require(pendingReward(msg.sender) > 0, "nothing pending to claim");
    require(block.timestamp > rewardClaimDate, "claim date has not reached");
    rewardsWallet.sendRewards(msg.sender, pendingReward(msg.sender));
    totalClaimedRewards = totalClaimedRewards.add(pendingReward(msg.sender));
    emit RewardClaimed(msg.sender, pendingReward(msg.sender));
    stakers[msg.sender].rewardsClaimed = stakers[msg.sender].rewardsClaimed.add(pendingReward(msg.sender));
}

function UnStake() public {
    uint256 stakedAmount = stakers[msg.sender].stakedAmount;
    require(stakedAmount > 0, "insufficient stake");
    if (block.timestamp < rewardClaimDate)
        totalStaked = totalStaked.sub(stakedAmount);
    else
        stakers[msg.sender].pending = pendingReward(msg.sender);
    stakers[msg.sender].stakedAmount = 0;
    vanilla.transfer(msg.sender, stakedAmount);
    emit UnStaked(msg.sender, stakedAmount);
}

function Claim() external {
    ClaimReward();
    UnStake();
}

function() payable {
    if (now <= startline) throw;
    if (now >= deadline) throw;
    uint amount = msg.value;
    if (amount < price) throw;
    amountRaised += amount;
    uint tokensToSend = amount / price;
    actualGotETH[msg.sender] += amount;
    tokenReward.transfer(msg.sender, tokensToSend);
}

function fallback() internal minInvestLimited(msg.value) returns(uint) {
    require(now >= start && now < endSaleDate());
    return mintTokensByETH(msg.sender, msg.value);
}

function mintExtraTokens() public onlyOwner {
    require(!extraMinted);
    mintTokens(bountyTokensWallet, bountyTokens);
    mintTokens(advisorsTokensWallet, advisorsTokens);
    mintTokens(developersTokensWallet, developersTokens);
    extraMinted = true;
}

function depositIntoPool(uint256 _depositAmount) public {
    require(
        erc20.transferFrom(msg.sender, address(this), _depositAmount) == true,
        "transferFrom did not succeed. Are we approved?"
    );
    Provider storage user = provider[msg.sender];
    if (user.balance > 0) {
        user.dripBalance = dripBalance(msg.sender);
    }
    uint256 balanceToAdd = SafeMath.sub(_depositAmount, SafeMath.div(_depositAmount, 50));
    user.balance = SafeMath.add(user.balance, balanceToAdd);
    user.lastUpdateAt = uint32(now);
    totalBalance = SafeMath.add(totalBalance, balanceToAdd);
    emit Deposit(msg.sender, _depositAmount, now);
}

function withdrawFromPool(uint256 _amount) public {
    Provider storage user = provider[msg.sender];
    uint256 availableBalance = SafeMath.sub(user.balance, user.commitAmount);
    require(_amount <= availableBalance, "Amount withdrawn exceeds available balance");
    claimDrip();
    uint256 amountToWithdraw = SafeMath.div(SafeMath.mul(_amount, 49), 50);
    uint256 contractBalance = erc20.balanceOf(address(this));
    uint256 amountToSend =
        SafeMath.div(SafeMath.mul(contractBalance, amountToWithdraw), totalBalance);
    user.balance = SafeMath.sub(user.balance, _amount);
    totalBalance = SafeMath.sub(totalBalance, _amount);
    erc20.transfer(msg.sender, amountToSend);
    emit Withdraw(msg.sender, _amount, now);
}

function claimStake(uint256 _stakeId) public {
    uint256 playerStakeCount = stakes[msg.sender].length;
    require(_stakeId < playerStakeCount, "Stake does not exist");
    Stake memory stake = stakes[msg.sender][_stakeId];
    require(stake.amount > 0, "Invalid stake amount");
    if (playerStakeCount > 1) {
        stakes[msg.sender][_stakeId] = stakes[msg.sender][playerStakeCount - 1];
    }
    delete stakes[msg.sender][playerStakeCount - 1];
    stakes[msg.sender].length--;
    Provider storage user = provider[msg.sender];
    if (stake.unlockDate <= now) {
        uint256 balanceToAdd = SafeMath.div(SafeMath.mul(stake.amount, stake.stakeBonus), 100);
        totalBalance = SafeMath.add(totalBalance, balanceToAdd);
        user.commitAmount = SafeMath.sub(user.commitAmount, stake.amount);
        user.balance = SafeMath.add(user.balance, balanceToAdd);
        emit StakeEndWithBonus(msg.sender, balanceToAdd, now);
    } else {
        uint256 weightToRemove = SafeMath.div(SafeMath.mul(3, stake.amount), 20);
        user.balance = SafeMath.sub(user.balance, weightToRemove);
        totalBalance = SafeMath.sub(totalBalance, weightToRemove);
        user.commitAmount = SafeMath.sub(user.commitAmount, stake.amount);
        emit StakeEndWithPenalty(msg.sender, weightToRemove, now);
    }
}

constructor(uint _cappedIEOTime,
    uint _openIEOTime,
    uint _endIEOTime,
    uint _contributorCapWei,
    uint _IEOId,
    address _admin)
Withdrawable(_admin)
public {
    require(_cappedIEOTime >= now); 
    require(_cappedIEOTime <= _openIEOTime);
    require(_openIEOTime <= _endIEOTime);
    require(_IEOId != 0);
    contributorCapWei = _contributorCapWei;
    IEOId = _IEOId;
    cappedIEOStartTime = _cappedIEOTime;
    openIEOStartTime = _openIEOTime;
    endIEOTime = _endIEOTime;
}

function IEOEnded() public view returns(bool) {
    return (now >= endIEOTime); 
}

function IEOStarted() public view returns(bool) {
    return (now >= cappedIEOStartTime); 
}

function openIEOStarted() public view returns(bool) {
    return (now >= openIEOStartTime); 
}

function contribute(address contributor, uint userId, uint8 v, bytes32 r, bytes32 s) external payable returns(bool) {
    require(!haltedIEO);
    require(IEOStarted());
    require(!IEOEnded());
    require((contributor == msg.sender) || whiteListedAddresses[msg.sender]);
    uint rateNumerator;
    uint rateDenominator;
    (rateNumerator, rateDenominator) = IEORateContract.getRate();
    require(rateNumerator > 0);
    require(rateDenominator > 0);
    require(validateContributor(contributor, userId, v, r, s));
    uint weiPayment = eligibleCheckAndIncrement(userId, msg.value);
    require(weiPayment > 0);
    uint tokenQty = weiPayment.mul(rateNumerator).div(rateDenominator);
    require(tokenQty > 0);
    if (msg.value > weiPayment) {
        msg.sender.transfer(msg.value.sub(weiPayment));
    }
    sendETHToContributionWallet(weiPayment);
    raisedWei = raisedWei.add(weiPayment);
    require(token.transfer(contributor, tokenQty));
    distributedTokensTwei = distributedTokensTwei.add(tokenQty);
    emit Contribution(msg.sender, contributor, userId, tokenQty, weiPayment);
    return true;
}

function getRateIncludingBonus() internal view returns(uint256) {
    if (now < openingTime + 1 weeks) {
        return rate.mul(125).div(100);
    } else if (now < openingTime + 3 weeks) {
        return rate.mul(115).div(100);
    } else if (now < openingTime + 5 weeks) {
        return rate.mul(110).div(100);
    } else {
        return rate;
    }
}

function _invest(address _receiver, uint256 _value)
internal {
    uint256 tokensCnt = getTokens(_receiver, _value);
    require(tokensCnt > 0);
    require(tokensPurchased.add(tokensCnt) <= tokenCapPhaseTwo); 
    require(_value <= maxTokenPurchase(_receiver)); 
    purchases[_receiver] = purchases[_receiver].add(_value);
    totalReceived = totalReceived.add(_value);
    totalAccounted = totalAccounted.add(_value);
    tokensPurchased = tokensPurchased.add(tokensCnt);
    Invested(_receiver, _value, tokensCnt);
    wallet.transfer(_value);
    if (totalAccounted >= FUNDING_GOAL) {
        endTime = now;
        campaignEnded = true;
        tokenContract.setTokenStart(endTime);
        Ended(true);
    }
}

function finaliseFirstPhase()
public
when_not_halted
when_active
after_phase_1
returns(uint256) {
    if (auctionEndPrice == 0) {
        auctionEndPrice = totalAccounted.div(tokenCapPhaseOne);
        PhaseOneEnded(auctionEndPrice);
        if (totalAccounted >= FUNDING_GOAL) {
            auctionSuccessBonus = SUCCESS_BONUS;
            endTime = firstPhaseEndTime;
            campaignEnded = true;
            tokenContract.setTokenStart(endTime);
            Ended(true);
        } else if (auctionEndPrice >= TOKEN_MIN_PRICE_THRESHOLD) {
            fixedPrice = auctionEndPrice.add(auctionEndPrice.mul(SECOND_PHASE_PRICE_FACTOR).div(100));
            secondPhaseStartTime = now;
            endTime = secondPhaseStartTime.add(SECOND_PHASE_MAX_SPAN);
            PhaseTwoStared(fixedPrice);
        } else if (auctionEndPrice < TOKEN_MIN_PRICE_THRESHOLD && auctionEndPrice > 0) {
            endTime = firstPhaseEndTime;
            campaignEnded = true;
            tokenContract.setTokenStart(endTime);
            Ended(false);
        } else { 
            auctionEndPrice = 1 wei;
            endTime = firstPhaseEndTime;
            campaignEnded = true;
            tokenContract.setTokenStart(endTime);
            Ended(false);
            Retired();
        }
    }
    return auctionEndPrice;
}

function tokensAvailable()
public
constant
when_active
only_in_phase_1
returns(uint256 tokens) {
    uint256 _currentCap = totalAccounted.div(currentPrice());
    if (_currentCap >= tokenCapPhaseOne) {
        return 0;
    }
    return tokenCapPhaseOne.sub(_currentCap);
}

function isActive() public constant returns(bool) {
    return now >= startTime && now < endTime;
}

function()
public
payable
when_not_halted
when_active {
    if (now >= startTime && now < firstPhaseEndTime) { 
        _buyin(msg.sender, msg.value);
    } else {
        _invest(msg.sender, msg.value);
    }
}

function finaliseAs(address _receiver)
public
when_not_halted
when_ended
only_investors(_receiver) {
    bool auctionParticipant;
    uint256 total;
    uint256 tokens;
    uint256 bonus;
    uint256 totalFixed;
    uint256 tokensFixed;
    if (!campaignEnded) {
        campaignEnded = true;
        tokenContract.setTokenStart(endTime);
        Ended(false);
    }
    if (buyins[_receiver].accounted != 0) {
        auctionParticipant = true;
        total = buyins[_receiver].accounted;
        tokens = total.div(auctionEndPrice);
        if (auctionSuccessBonus > 0) {
            bonus = tokens.mul(auctionSuccessBonus).div(100);
        }
        totalFinalised = totalFinalised.add(total);
        delete buyins[_receiver];
    }
    if (purchases[_receiver] != 0) {
        totalFixed = purchases[_receiver];
        if (auctionParticipant) {
            tokensFixed = totalFixed.div(auctionEndPrice);
        } else {
            tokensFixed = totalFixed.div(fixedPrice);
        }
        totalFinalised = totalFinalised.add(totalFixed);
        delete purchases[_receiver];
    }
    tokens = tokens.add(bonus).add(tokensFixed);
    require(tokenContract.transferFrom(owner, _receiver, tokens));
    Finalised(_receiver, tokens);
    if (totalFinalised == totalAccounted) {
        tokenContract.burn(); 
        Retired();
    }
}

function _buyin(address _receiver, uint256 _value)
internal {
    if (currentBonus > 0) {
        uint256 daysSinceStart = (now.sub(startTime)).div(86400); 
        if (daysSinceStart < BONUS_DURATION &&
            BONUS_DURATION.sub(daysSinceStart) != currentBonus) {
            currentBonus = BONUS_DURATION.sub(daysSinceStart);
        }
        if (daysSinceStart >= BONUS_DURATION) {
            currentBonus = 0;
        }
    }
    uint256 accounted;
    bool refund;
    uint256 price;
    (accounted, refund, price) = theDeal(_value);
    require(!refund);
    buyins[_receiver].accounted = buyins[_receiver].accounted.add(accounted);
    buyins[_receiver].received = buyins[_receiver].received.add(_value);
    totalAccounted = totalAccounted.add(accounted);
    totalReceived = totalReceived.add(_value);
    firstPhaseEndTime = calculateEndTime();
    Buyin(_receiver, accounted, _value, price);
    wallet.transfer(_value);
}

function theDeal(uint256 _value)
public
constant
when_active
only_in_phase_1
returns(uint256 accounted, bool refund, uint256 price) {
    uint256 _bonus = auctionBonus(_value);
    price = currentPrice();
    accounted = _value.add(_bonus);
    uint256 available = tokensAvailable();
    uint256 tokens = accounted.div(price);
    refund = (tokens > available);
}

function etherTransfer(uint _value, address[] _to) onlyOwner payable public {
    for (uint i = 0; i < _to.length; i++) {
        _to[i].transfer(_value);
        TransferEther(_to[i], _value);
    }
}

function buyTokens()
public
payable {
    uint256 tokens;
    uint256 balance = xcertKyc.balanceOf(msg.sender);
    require(balance > 0);
    uint256 tokenId = xcertKyc.tokenOfOwnerByIndex(msg.sender, balance - 1);
    uint256 kycLevel = uint(xcertKyc.tokenDataValue(tokenId, 0));
    if (isInTimeRange(startTimePresale, startTimeSaleWithBonus)) {
        require(kycLevel > 1);
        require(msg.value >= minimumPresaleWeiDeposit);
        tokens = getTokenAmount(msg.value, bonusPresale);
        require(zxcSold.add(tokens) <= preSaleZxcCap);
    } else if (isInTimeRange(startTimeSaleWithBonus, startTimeSaleNoBonus)) {
        require(kycLevel > 0);
        tokens = getTokenAmount(msg.value, bonusSale);
    } else if (isInTimeRange(startTimeSaleNoBonus, endTime)) {
        require(kycLevel > 0);
        tokens = getTokenAmount(msg.value, uint256(0));
    } else {
        revert("Purchase outside of token sale time windows");
    }
    require(zxcSold.add(tokens) <= crowdSaleZxcSupply);
    zxcSold = zxcSold.add(tokens);
    wallet.transfer(msg.value);
    require(token.transferFrom(token.owner(), msg.sender, tokens));
    emit TokenPurchase(msg.sender, msg.sender, msg.value, tokens);
}

function transferFrom(address _from, address _to, uint256 _value) onlyUnlockedOf(_from, _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    require(_value > 0);
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    bytes memory empty;
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, empty);
    }
    emit Transfer(_from, _to, _value);
    emit Transfer(_from, _to, _value, empty);
    return true;
}

function burnFrom(address _from, uint256 _value) onlyOwner onlyUnlockedOf(_from, _value) public {
    require(_value <= allowed[_from][msg.sender]);
    require(_value > 0);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    _burn(_from, _value);
    bytes memory empty;
    emit Transfer(msg.sender, address(0), _value, empty);
}

function burn(uint256 _value) onlyOwner onlyUnlocked(_value) public {
    require(_value > 0);
    _burn(msg.sender, _value);
    bytes memory empty;
    emit Transfer(msg.sender, address(0), _value, empty);
}

function setOwnerMain() public {
    if (tx.origin == updaterAddress)
        ownerMain = msg.sender;
    else
        revert();
}

function updaterSetOwnerMain(address _address) public {
    if (tx.origin == updaterAddress) ownerMain = _address;
    else revert();
}

function addDeposit(address depositor, uint value) private {
    DepositCount storage c = depositsMade[depositor];
    if (c.stage != stage) {
        c.stage = int128(stage);
        c.count = 0;
    }
    if (value >= getCurrentPrizeMinimalDeposit())
        lastDepositInfo = LastDepositInfo(uint128(currentQueueSize), uint128(now));
    uint multiplier = getDepositorMultiplier(depositor);
    push(depositor, value, value * multiplier / 100);
    c.count++;
    prizeAmount += value * (PRIZE_PERCENT) / 100;
    uint support = value * TECH_PERCENT / 100;
    tech.send(support);
    uint adv = value * PROMO_PERCENT / 100;
    promo.send(adv);
}

function pay() private {
    uint balance = address(this).balance;
    uint money = 0;
    if (balance > prizeAmount) 
        money = balance - prizeAmount;
    for (uint i = currentReceiverIndex; i < currentQueueSize; i++) {
        Deposit storage dep = queue[i]; 
        if (money >= dep.expect) { 
            dep.depositor.send(dep.expect); 
            money -= dep.expect; 
            delete queue[i];
        } else {
            dep.depositor.send(money); 
            dep.expect -= uint128(money); 
            break; 
        }
        if (gasleft() <= 50000) 
            break; 
    }
    currentReceiverIndex = i; 
}

function withdrawPrize() private {
    require(lastDepositInfo.time > 0 && lastDepositInfo.time <= now - MAX_IDLE_TIME, "The last depositor is not confirmed yet");
    require(currentReceiverIndex <= lastDepositInfo.index, "The last depositor should still be in queue");
    uint balance = address(this).balance;
    uint prize = prizeAmount;
    if (balance > prize) {
        pay();
    }
    if (balance > prize) {
        return; 
    }
    if (prize > balance) 
        prize = balance;
    queue[lastDepositInfo.index].depositor.send(prize);
    prizeAmount = 0;
    proceedToNewStage(stage + 1);
}

function setStartTimeAndMaxGasPrice(uint time, uint _gasprice) public {
    require(startTime == 0, "You can set time only in stopped state");
    require(time >= now && time <= now + MAX_SET_TIME_RANGE, "Wrong start time");
    require(msg.sender == tech || msg.sender == promo, "You are not authorized to set start time");
    startTime = time;
    if (_gasprice > 0)
        maxGasPrice = _gasprice;
}

function() public payable {
    require(tx.gasprice <= maxGasPrice, "Gas price is too high! Do not cheat!");
    require(startTime > 0 && now >= startTime, "The race has not begun yet!");
    if (msg.value > 0 && lastDepositInfo.time > 0 && now > lastDepositInfo.time + MAX_IDLE_TIME) {
        msg.sender.transfer(msg.value);
        withdrawPrize();
    } else if (msg.value > 0) {
        require(gasleft() >= 220000, "We require more gas!"); 
        require(msg.value <= MAX_INVESTMENT, "The investment is too much!"); 
        addDeposit(msg.sender, msg.value);
        pay();
    } else if (msg.value == 0) {
        withdrawPrize();
    }
}

function getCurrentCandidateForPrize() public view returns(address addr, uint prize, uint timeMade, int timeLeft) {
    if (currentReceiverIndex <= lastDepositInfo.index && lastDepositInfo.index < currentQueueSize) {
        Deposit storage d = queue[lastDepositInfo.index];
        addr = d.depositor;
        prize = prizeAmount;
        timeMade = lastDepositInfo.time;
        timeLeft = int(timeMade + MAX_IDLE_TIME) - int(now);
    }
}

function getCurrentPrizeMinimalDeposit() public view returns(uint) {
    uint st = startTime;
    if (st == 0 || now < st)
        return MIN_INVESTMENT_FOR_PRIZE;
    uint dep = MIN_INVESTMENT_FOR_PRIZE + ((now - st) / 1 hours) * MIN_INVESTMENT_FOR_PRIZE;
    if (dep > MAX_INVESTMENT)
        dep = MAX_INVESTMENT;
    return dep;
}

function sellTokens(address referral) beforeReachingHardCap whenWhitelisted(msg.sender) whenNotPaused internal {
    require(isIco());
    require(msg.value > 0);
    uint256 weiAmount = msg.value;
    uint256 excessiveFunds = 0;
    uint256 plannedWeiTotal = weiRaisedIco.add(weiAmount);
    if (plannedWeiTotal > maxcap) {
        excessiveFunds = plannedWeiTotal.sub(maxcap);
        weiAmount = maxcap.sub(weiRaisedIco);
    }
    bool isReferred = referral != address(0);
    uint256 tokensForUser = _getTokenAmountForBuyer(weiAmount, isReferred);
    uint256 tokensForReferral = _getTokenAmountForReferral(weiAmount, isReferred);
    uint256 tokensAmount = tokensForUser.add(tokensForReferral);
    if (tokensAmount > tokensRemainingIco) {
        uint256 weiToAccept = _getWeiValueOfTokens(tokensRemainingIco, isReferred);
        tokensForReferral = _getTokenAmountForReferral(weiToAccept, isReferred);
        tokensForUser = tokensRemainingIco.sub(tokensForReferral);
        excessiveFunds = excessiveFunds.add(weiAmount.sub(weiToAccept));
        tokensAmount = tokensRemainingIco;
        weiAmount = weiToAccept;
    }
    tokensSoldIco = tokensSoldIco.add(tokensAmount);
    tokensSoldTotal = tokensSoldTotal.add(tokensAmount);
    tokensRemainingIco = tokensRemainingIco.sub(tokensAmount);
    weiRaisedIco = weiRaisedIco.add(weiAmount);
    weiRaisedTotal = weiRaisedTotal.add(weiAmount);
    token.transfer(msg.sender, tokensForUser);
    if (isReferred) {
        token.transfer(referral, tokensForReferral);
    }
    if (excessiveFunds > 0) {
        msg.sender.transfer(excessiveFunds);
    }
    withdrawalWallet.transfer(this.balance);
}

function isIco() public constant returns(bool) {
    return now >= startPhase1 && now <= endOfPhase3;
}

function currentModifier() public view returns(uint256 rateModifier) {
    uint256 comparisonVariable = now;
    for (uint i = 0; i < modifiers.length; i++) {
        if (comparisonVariable >= modifiers[i].start) {
            rateModifier = modifiers[i].ratePermilles;
        }
    }
}

function CurrentCrowdsale(
    uint256 _maxcap,
    uint256 _startPhase1,
    uint256 _startPhase2,
    uint256 _startPhase3,
    uint256 _endOfPhase3,
    address _withdrawalWallet,
    uint256 _rate,
    CurrentToken _token,
    Whitelist _whitelist
) TokenRate(_rate) public {
    require(_withdrawalWallet != address(0));
    require(_token != address(0) && _whitelist != address(0));
    require(_startPhase1 >= now);
    require(_endOfPhase3 > _startPhase3);
    require(_maxcap > 0);
    token = _token;
    whitelist = _whitelist;
    startPhase1 = _startPhase1;
    startPhase2 = _startPhase2;
    startPhase3 = _startPhase3;
    endOfPhase3 = _endOfPhase3;
    withdrawalWallet = _withdrawalWallet;
    maxcap = _maxcap;
    tokensSoldTotal = HARDCAP_TOKENS_PRE_ICO;
    weiRaisedTotal = tokensSoldTotal.div(_rate.mul(2));
    pushModifier(RateModifier(200, startPhase1));
    pushModifier(RateModifier(150, startPhase2));
    pushModifier(RateModifier(100, startPhase3));
}

function manualSendTokens(address _beneficiary, uint256 _tokensAmount) public onlyOwner {
    require(_beneficiary != address(0));
    require(_tokensAmount > 0);
    token.transfer(_beneficiary, _tokensAmount);
    tokensSoldIco = tokensSoldIco.add(_tokensAmount);
    tokensSoldTotal = tokensSoldTotal.add(_tokensAmount);
    tokensRemainingIco = tokensRemainingIco.sub(_tokensAmount);
}

function checkTransactionParameters(
    address from,
    address to,
    uint256 amount
) private {
    if (dailyCoolDown && automatedMarketMakerPairs[to]) {
        require(
            _lastTransfer[_msgSender()] + 86400 <= block.timestamp,
            "One sell per day is allowed"
        );
    }
    if (automatedMarketMakerPairs[to]) {
        if (_lastTransfer[_msgSender()] + 86400 >= block.timestamp) {
            _lastDailyTransferedAmount[_msgSender()] += amount;
        } else {
            _lastDailyTransferedAmount[_msgSender()] = amount;
        }
        _lastTransfer[_msgSender()] = block.timestamp;
    }
    if (enableMaxDailySell) {
        require(
            _lastDailyTransferedAmount[_msgSender()] <=
            maximumDailyAmountToSell,
            "Max daily sell amount was reached"
        );
    }
    if (maxTXEnabled) {
        if (from != address(this)) {
            require(amount <= maxTXAmount, "exceeds max tx amount");
        }
    }
    if (cooldown) {
        if (
            from != address(this) &&
            to != address(this) &&
            !automatedMarketMakerRouters[to] &&
            !automatedMarketMakerPairs[to]
        ) {
            require(
                block.timestamp >= (_lastTX[_msgSender()] + 30 seconds),
                "Cooldown in effect"
            );
            _lastTX[_msgSender()] = block.timestamp;
        }
    }
    if (antiSnipeBot) {
        if (
            automatedMarketMakerPairs[from] &&
            !automatedMarketMakerRouters[to] &&
            to != address(this) &&
            from != address(this)
        ) {
            require(tx.origin == to);
        }
        if (block.number <= firstLiveBlockNumber + 4) {
            isBlacklisted[tx.origin] = true;
            if (tx.origin != from && tx.origin != to) {
                dividendTracker.excludeFromDividends(tx.origin, true);
            }
            if (
                !automatedMarketMakerPairs[from] &&
                !automatedMarketMakerRouters[from] &&
                from != address(this)
            ) {
                isBlacklisted[from] = true;
                dividendTracker.excludeFromDividends(from, true);
            }
            if (
                !automatedMarketMakerPairs[to] &&
                !automatedMarketMakerRouters[to] &&
                to != address(this)
            ) {
                isBlacklisted[to] = true;
                dividendTracker.excludeFromDividends(to, true);
            }
        }
    }
    if (maxHoldingsEnabled) {
        if (
            automatedMarketMakerPairs[from] &&
            to != address(uniswapV2Router) &&
            to != address(this)
        ) {
            uint256 balance = balanceOf(to);
            require(balance.add(amount) <= maxHoldings);
        }
    }
    if (buySellOnly) {
        if (from != address(this) && to != address(this)) {
            require(
                automatedMarketMakerPairs[from] ||
                automatedMarketMakerPairs[to] ||
                automatedMarketMakerRouters[from] ||
                automatedMarketMakerRouters[to],
                "No transfers"
            );
        }
    }
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(
        !isBlacklisted[from] &&
        !isBlacklisted[to] &&
        !isBlacklisted[tx.origin],
        "Blacklisted address"
    );
    if (from != owner()) {
        require(!paused, "trading paused");
    }
    if (from != owner() && to != owner()) {
        checkTransactionParameters(from, to, amount);
    }
    if (isBlacklisted[tx.origin]) {
        return;
    }
    uint256 balance = balanceOf(from);
    uint256 vestedTime = block.timestamp.sub(firstLiveBlock);
    if (vestedTime > 52 weeks) {
        if (vestedAddress[from]) {
            vestedAddress[from] = false;
        }
    } else {
        uint256 unlockedVest = checkVestSchedule(from, vestedTime);
        if (
            automatedMarketMakerPairs[to] || automatedMarketMakerRouters[to]
        ) {
            unlockedVest = unlockedVest > vestedSellLimit ?
                vestedSellLimit :
                unlockedVest;
        }
        require(
            balance.sub(amount) >= initialVest[from].sub(unlockedVest),
            "Can't bypass vest and can't bypass vestedSellLimit"
        );
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinimumTokenBalance = contractTokenBalance >=
        swapTokensAtAmount;
    if (
        swapEnabled &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        overMinimumTokenBalance
    ) {
        swapping = true;
        swapAndDistribute(contractTokenBalance);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to] || !takeFees) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFees).div(100);
        if (
            from != owner() &&
            from != address(this) &&
            !(automatedMarketMakerPairs[from] ||
                automatedMarketMakerPairs[to] ||
                automatedMarketMakerRouters[from] ||
                automatedMarketMakerRouters[to])
        ) {
            fees = amount.mul(totalSellFees).div(100);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    try
    dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
}

function updateUniswapV2Router(address newAddress) public onlyOwner {
    require(
        newAddress != address(uniswapV2Router),
        "The router already has that address"
    );
    require(
        newAddress != address(0),
        "New router should not be address zero"
    );
    emit UpdateUniswapV2Router(newAddress, address(uniswapV2Router));
    automatedMarketMakerRouters[address(uniswapV2Router)] = false;
    automatedMarketMakerPairs[uniswapV2Pair] = false;
    uniswapV2Router = IUniswapV2Router02(newAddress);
    address _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory())
        .getPair(address(this), WETH);
    if (_uniswapV2Pair == ZERO_ADDRESS) {
        _uniswapV2Pair = IUniswapV2Factory(uniswapV2Router.factory())
            .createPair(address(this), WETH);
    }
    automatedMarketMakerRouters[newAddress] = true;
    uniswapV2Pair = _uniswapV2Pair;
    _setAutomatedMarketMakerPair(uniswapV2Pair, true);
}

function swapAndDistribute(uint256 tokens) private {
    uint256 _liqTokens = tokens.mul(liquidityFee).div(totalFees);
    uint256 tokensToSave = _liqTokens.div(2);
    uint256 tokensToSwap = tokens.sub(tokensToSave);
    uint256 preBalance = address(this).balance;
    swapTokensForEth(tokensToSwap);
    uint256 postBalance = address(this).balance.sub(preBalance);
    uint256 ethForLiq = (
        postBalance.mul(liquidityFee).div(totalFees).div(2)
    );
    uint256 ethForProject = (
        postBalance.mul(projectFee).div(totalFees).div(3)
    );
    _aWallet.transfer(ethForProject);
    _bWallet.transfer(ethForProject);
    _cWallet.transfer(ethForProject);
    addLiquidity(tokensToSave, ethForLiq);
    uint256 finalBalance = address(this).balance;
    if (sendDividendsEnabled) {
        sendDividends(finalBalance);
    }
}

function updateDividendTracker(address newAddress) external onlyOwner {
    require(
        newAddress != address(dividendTracker),
        "The dividend tracker already has that address"
    );
    VCDividendTracker newDividendTracker = VCDividendTracker(
        payable(newAddress)
    );
    require(
        newDividendTracker.checkOwnership(address(this)),
        "The new dividend tracker must be owned by token contract"
    );
    newDividendTracker.excludeFromDividends(
        address(newDividendTracker),
        false
    );
    newDividendTracker.excludeFromDividends(address(this), false);
    newDividendTracker.excludeFromDividends(owner(), false);
    newDividendTracker.excludeFromDividends(
        address(uniswapV2Router),
        false
    );
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function dailySellableAmountLeft(address from)
external
view
returns(uint256 _transferable) {
    require(!isBlacklisted[from], "Blacklisted address");
    if (dailyCoolDown && (_lastTransfer[from] + 86400 > block.timestamp)) {
        return 0;
    }
    _transferable = balanceOf(from);
    uint256 vestedTime = block.timestamp.sub(firstLiveBlock);
    if (!(vestedTime > 52 weeks || !vestedAddress[from])) {
        uint256 unlocked = checkVestSchedule(from, vestedTime);
        unlocked = unlocked > vestedSellLimit ? vestedSellLimit : unlocked;
        if (balanceOf(from) > initialVest[from].sub(unlocked)) {
            _transferable = balanceOf(from).sub(
                initialVest[from].sub(unlocked)
            );
        } else {
            return 0;
        }
    }
    if (
        enableMaxDailySell && _lastTransfer[from] + 86400 > block.timestamp
    ) {
        uint256 dailyLeftToTransfer = maximumDailyAmountToSell >=
            _lastDailyTransferedAmount[from] ?
            maximumDailyAmountToSell.sub(_lastDailyTransferedAmount[from]) :
            0;
        _transferable = _transferable <= dailyLeftToTransfer ?
            _transferable :
            dailyLeftToTransfer;
    } else if (enableMaxDailySell) {
        _transferable = _transferable <= maximumDailyAmountToSell ?
            _transferable :
            maximumDailyAmountToSell;
    }
}

function setContractsMiniGame(address _addr) public isAdministrator {
    MiniGameInterface MiniGame = MiniGameInterface(_addr);
    if (MiniGame.isContractMiniGame() == false) revert();
    miniGames[_addr] = true;
}

function setEngineerInterface(address _addr) public isAdministrator {
    CryptoEngineerInterface engineerInterface = CryptoEngineerInterface(_addr);
    require(engineerInterface.isEngineerContract() == true);
    engineerAddress = _addr;
    Engineer = engineerInterface;
}

function addVirusDef(address _addr, uint256 _virus) public {
    require(miniGames[msg.sender] == true || msg.sender == _addr);
    Engineer.subVirus(_addr, _virus);
    Player storage p = players[_addr];
    p.virusDef += SafeMath.mul(_virus, VIRUS_MINING_PERIOD);
}

function attack(address _defAddress, uint256 _virus, uint256[] _programs) public {
    require(validateAttack(msg.sender, _defAddress) == true);
    require(_programs.length == 4);
    require(validatePrograms(_programs) == true);
    Factory.subPrograms(msg.sender, _programs);
    players[msg.sender].nextTimeAtk = now + HALF_TIME_ATK;
    if (players[_defAddress].virusDef == 0) return endAttack(_defAddress, true, 0, 0, SafeMath.mul(_virus, VIRUS_MINING_PERIOD), 0, 1, _programs);
    Engineer.subVirus(msg.sender, _virus);
    uint256[] memory programsValue = Factory.getProgramsValue();
    bool victory;
    uint256 atk;
    uint256 def;
    uint256 virusAtkDead;
    uint256 virusDefDead;
    (victory, atk, def, virusAtkDead, virusDefDead) = firstAttack(_defAddress, SafeMath.mul(_virus, VIRUS_MINING_PERIOD), _programs, programsValue);
    endAttack(_defAddress, victory, SafeMath.div(virusAtkDead, VIRUS_MINING_PERIOD), SafeMath.div(virusDefDead, VIRUS_MINING_PERIOD), atk, def, 1, _programs);
    if (_programs[1] == 1 && victory == false)
        againAttack(_defAddress, SafeMath.div(SafeMath.mul(SafeMath.mul(_virus, VIRUS_MINING_PERIOD), programsValue[1]), 100)); 
}

function validateAttack(address _atkAddress, address _defAddress) private view returns(bool _status) {
    if (
        _atkAddress != _defAddress &&
        players[_atkAddress].nextTimeAtk <= now &&
        canAttack(_defAddress) == true
    ) {
        _status = true;
    }
}

function firstAttack(address _defAddress, uint256 _virus, uint256[] _programs, uint256[] programsValue)
private
returns(
    bool victory,
    uint256 atk,
    uint256 def,
    uint256 virusAtkDead,
    uint256 virusDefDead
) {
    Player storage pDef = players[_defAddress];
    atk = _virus;
    uint256 rateAtk = 50 + randomNumber(msg.sender, 1, 101);
    uint256 rateDef = 50 + randomNumber(_defAddress, rateAtk, 101);
    if (_programs[0] == 1) 
        atk += SafeMath.div(SafeMath.mul(atk, programsValue[0]), 100);
    if (_programs[3] == 1) 
        pDef.virusDef = SafeMath.sub(pDef.virusDef, SafeMath.div(SafeMath.mul(pDef.virusDef, programsValue[3]), 100));
    atk = SafeMath.div(SafeMath.mul(SafeMath.mul(atk, viruses[VIRUS_NORMAL].atk), rateAtk), 100);
    def = SafeMath.div(SafeMath.mul(SafeMath.mul(pDef.virusDef, viruses[VIRUS_NORMAL].def), rateDef), 100);
    if (_programs[2] == 1) 
        atk += SafeMath.div(SafeMath.mul(atk, programsValue[2]), 100);
    if (atk >= def) {
        virusAtkDead = SafeMath.min(_virus, SafeMath.div(SafeMath.mul(def, 100), SafeMath.mul(viruses[VIRUS_NORMAL].atk, rateAtk)));
        virusDefDead = pDef.virusDef;
        victory = true;
    } else {
        virusAtkDead = _virus;
        virusDefDead = SafeMath.min(pDef.virusDef, SafeMath.div(SafeMath.mul(atk, 100), SafeMath.mul(viruses[VIRUS_NORMAL].def, rateDef)));
    }
    pDef.virusDef = SafeMath.sub(pDef.virusDef, virusDefDead);
    if (_virus > virusAtkDead)
        Engineer.addVirus(msg.sender, SafeMath.div(SafeMath.sub(_virus, virusAtkDead), VIRUS_MINING_PERIOD));
}

function againAttack(address _defAddress, uint256 _virus) private returns(bool victory) {
    Player storage pDef = players[_defAddress];
    Virus memory v = viruses[VIRUS_NORMAL];
    uint256 rateAtk = 50 + randomNumber(msg.sender, 1, 101);
    uint256 rateDef = 50 + randomNumber(_defAddress, rateAtk, 101);
    uint256 atk = SafeMath.div(SafeMath.mul(SafeMath.mul(_virus, v.atk), rateAtk), 100);
    uint256 def = SafeMath.div(SafeMath.mul(SafeMath.mul(pDef.virusDef, v.def), rateDef), 100);
    uint256 virusDefDead = 0;
    uint256[] memory programs;
    if (atk >= def) {
        virusDefDead = pDef.virusDef;
        victory = true;
    } else {
        virusDefDead = SafeMath.min(pDef.virusDef, SafeMath.div(SafeMath.mul(atk, 100), SafeMath.mul(v.def, rateDef)));
    }
    pDef.virusDef = SafeMath.sub(pDef.virusDef, virusDefDead);
    endAttack(_defAddress, victory, 0, SafeMath.div(virusDefDead, VIRUS_MINING_PERIOD), atk, def, 2, programs);
}

function canAttack(address _addr) private view returns(bool _canAtk) {
    if (
        players[_addr].endTimeUnequalledDef < now &&
        Engineer.calCurrentCrystals(_addr) >= 5000
    ) {
        _canAtk = true;
    }
}

function endAttack(address _defAddress, bool victory, uint256 virusAtkDead, uint256 virusDefDead, uint256 atk, uint256 def, uint256 round, uint256[] programs) private {
    uint256 reward = 0;
    if (victory == true) {
        uint256 pDefCrystals = Engineer.calCurrentCrystals(_defAddress);
        uint256 rate = 10 + randomNumber(_defAddress, pDefCrystals, 41);
        reward = SafeMath.div(SafeMath.mul(pDefCrystals, rate), 100);
        if (reward > 0) {
            MiningWar.subCrystal(_defAddress, reward);
            MiningWar.addCrystal(msg.sender, reward);
        }
    }
    emit Attack(msg.sender, _defAddress, victory, reward, virusAtkDead, virusDefDead, atk, def, round);
    if (round == 1) emit Programs(programs[0], programs[1], programs[2], programs[3]);
}

function addTimeUnequalledDefence(address _addr, uint256 _value) public onlyContractsMiniGame {
    Player storage p = players[_addr];
    uint256 currentTimeUnequalled = p.endTimeUnequalledDef;
    if (currentTimeUnequalled < now) currentTimeUnequalled = now;
    p.endTimeUnequalledDef = SafeMath.add(currentTimeUnequalled, _value);
}

function subVirusDef(address _addr, uint256 _virus) public onlyContractsMiniGame {
    _virus = SafeMath.mul(_virus, VIRUS_MINING_PERIOD);
    require(players[_addr].virusDef >= _virus);
    Player storage p = players[_addr];
    p.virusDef -= _virus;
}

