function relaseVestingGrant(VestingGrant storage grant) internal {
    uint256 amount = releasableAmount(now, grant);
    require(amount > 0);
    grant.transfered = grant.transfered.add(amount);
    balances[grant.beneficiary] = balances[grant.beneficiary].add(amount);
    emit Transfer(address(0), grant.beneficiary, amount);
}

function releasableAmount(uint256 time, VestingGrant grant) internal pure returns(uint256) {
    if (grant.amount == grant.transfered) {
        return 0;
    }
    if (time < grant.start) {
        return 0;
    }
    uint256 amountPerRelease = grant.amount.div(grant.releaseCount);
    uint256 amount = amountPerRelease.mul((time.sub(grant.start)).div(grant.duration));
    if (amount > grant.amount) {
        amount = grant.amount;
    }
    amount = amount.sub(grant.transfered);
    return amount;
}

function() payable public {
    require(reward != address(0));
    require(whitelist != address(0));
    require(msg.value >= (2 ether / 10));
    require(icoHasStarted);
    require(!icoHasClosed);
    require(valueInUSD != 0);
    require(whitelist.isWhitelisted(msg.sender));
    if (contributed[msg.sender] == 0) {
        participantIndex[nextParticipantIndex] = msg.sender;
        nextParticipantIndex += 1;
    }
    uint256 amountOfWei = msg.value;
    contributed[msg.sender] = contributed[msg.sender].add(amountOfWei);
    currentAmountRaised = currentAmountRaised.add(amountOfWei);
    uint256 tokens = tokensToMint(amountOfWei);
    reward.mintTokens(msg.sender, tokens);
    currentAmountOfTokens = currentAmountOfTokens.add(tokens);
    emit Received(msg.sender, msg.value);
    emit TokensGiven(msg.sender, tokens);
    if (address(this).balance >= 50 ether) {
        if (!address(recipient).send(address(this).balance)) {
            emit ErrorReturningEth(recipient, address(this).balance);
        }
    }
}

function tokensToMint(uint256 _amountOfWei) private returns(uint256) {
    uint256 tokensPerEth = valueInUSD.div(PRICEOFTOKEN);
    uint256 rewardAmount = tokensPerEth.mul(_amountOfWei);
    if (currentAmountOfTokensWithNoBonus.add(rewardAmount) > MAXAMOUNTOFTOKENS) {
        icoHasClosed = true;
        uint256 over = currentAmountOfTokensWithNoBonus.add(rewardAmount).sub(MAXAMOUNTOFTOKENS);
        rewardAmount = rewardAmount.sub(over);
        uint256 weiToReturn = over.div(tokensPerEth);
        currentAmountRaised = currentAmountRaised.sub(weiToReturn);
        contributed[msg.sender] = contributed[msg.sender].sub(weiToReturn);
        if (address(msg.sender).send(weiToReturn)) {
            emit ErrorReturningEth(msg.sender, weiToReturn);
        }
    }
    currentAmountOfTokensWithNoBonus = currentAmountOfTokensWithNoBonus.add(rewardAmount);
    if (block.timestamp <= startTime.add(BONUS25)) {
        rewardAmount = rewardAmount.add(rewardAmount.mul(25).div(100));
    } else if (block.timestamp <= startTime.add(BONUS15)) {
        rewardAmount = rewardAmount.add(rewardAmount.mul(15).div(100));
    } else if (block.timestamp <= startTime.add(BONUS7)) {
        rewardAmount = rewardAmount.add(rewardAmount.mul(7).div(100));
    }
    return rewardAmount;
}

function settleBetCommon(Bet storage bet, uint reveal, bytes32 entropyBlockHash) private {
    uint amount = bet.amount;
    uint rollUnder = bet.rollUnder;
    address gambler = bet.gambler;
    require(amount != 0, "Bet should be in an &#39;active&#39; state");
    applyVIPLevel(gambler, amount);
    bet.amount = 0;
    bytes32 entropy = keccak256(abi.encodePacked(reveal, entropyBlockHash));
    uint modulo = 100;
    uint dice = uint(entropy) % modulo;
    uint diceWinAmount;
    uint _jackpotFee;
    (diceWinAmount, _jackpotFee) = getDiceWinAmount(amount, rollUnder);
    uint diceWin = 0;
    uint jackpotWin = 0;
    if (modulo <= MAX_MASK_MODULO) {
        if ((2 ** dice) & bet.mask != 0) {
            diceWin = diceWinAmount;
        }
    } else {
        if (dice < rollUnder) {
            diceWin = diceWinAmount;
        }
    }
    lockedInBets -= uint128(diceWinAmount);
    if (amount >= MIN_JACKPOT_BET) {
        if ((uint(entropy) / modulo) % JACKPOT_MODULO == 0) {
            jackpotWin = jackpotSize;
            jackpotSize = 0;
        }
    }
    if (jackpotWin > 0) {
        emit JackpotPayment(gambler, jackpotWin, dice, rollUnder, amount);
    }
    if (bet.inviter != address(0)) {
        bet.inviter.transfer(amount * HOUSE_EDGE_PERCENT / 100 * 10 / 100);
    }
    todaysRewardSize += amount * HOUSE_EDGE_PERCENT / 100 * 9 / 100;
    sendFunds(gambler, diceWin + jackpotWin == 0 ? 1 wei : diceWin + jackpotWin, diceWin, dice, rollUnder, amount);
}

function payTodayReward(address to) external onlyOwner {
    uint prize = todaysRewardSize / 2;
    todaysRewardSize = todaysRewardSize - prize;
    if (to.send(prize)) {
        emit TodaysRankingPayment(to, prize);
    }
}

function applyVIPLevel(address gambler, uint amount) private {
    uint accuAmount = accuBetAmount[gambler];
    uint rate;
    if (accuAmount >= 30 ether && accuAmount < 150 ether) {
        rate = 1;
    } else if (accuAmount >= 150 ether && accuAmount < 300 ether) {
        rate = 2;
    } else if (accuAmount >= 300 ether && accuAmount < 1500 ether) {
        rate = 4;
    } else if (accuAmount >= 1500 ether && accuAmount < 3000 ether) {
        rate = 6;
    } else if (accuAmount >= 3000 ether && accuAmount < 15000 ether) {
        rate = 8;
    } else if (accuAmount >= 15000 ether && accuAmount < 30000 ether) {
        rate = 10;
    } else if (accuAmount >= 30000 ether && accuAmount < 150000 ether) {
        rate = 12;
    } else if (accuAmount >= 150000 ether) {
        rate = 15;
    } else {
        return;
    }
    uint vipPayback = amount * rate / 10000;
    if (gambler.send(vipPayback)) {
        emit VIPPayback(gambler, vipPayback);
    }
}

function sendFunds(address beneficiary, uint amount, uint successLogAmount, uint dice, uint rollUnder, uint betAmount) private {
    if (beneficiary.send(amount)) {
        emit Payment(beneficiary, successLogAmount, dice, rollUnder, betAmount);
    } else {
        emit FailedPayment(beneficiary, amount);
    }
}

function getRamdon() private view returns(uint) {
    bytes32 ramdon = baseRandom.getBaseRandom();
    require(ramdon != 0, "baseRandom error!");
    ramdon = keccak256(abi.encodePacked(ramdon, now, blockhash(block.number - 1)));
    for (uint i = 0; i < addressArray.length; i++) {
        ramdon = keccak256(abi.encodePacked(ramdon, now, addressArray[i]));
    }
    uint index = uint(ramdon) % addressArray.length;
    return index;
}

