function createCard(
    uint256 pool,
    uint256 supply,
    uint256 points,
    uint256 mintFee,
    uint256 releaseTime
) public onlyOwner poolExists(pool) returns(uint256) {
    uint256 tokenId = memeLtd.create(supply, 0, "", "");
    require(tokenId > 0, "ERC1155 create did not succeed");
    Card storage c = pools[pool].cards[tokenId];
    c.points = points;
    c.releaseTime = releaseTime;
    c.mintFee = mintFee;
