function validPurchase() internal constant returns(bool) {
    if (msg.value < 20000000000000000) {
        return false;
    }
    if (token.totalSupply().add(msg.value.mul(getRate())) >= CAP) {
        return false;
    }
    if (now > 1538208000 && now < 1554105600) {
        return false;
    }
    if (1535788800 >= now && 1538208000 <= now) {
        if (token.totalSupply().add(msg.value.mul(getRate())) >= CAP_PRE_SALE) {
            return false;
        }
    }
    if (1554105600 >= now && 1556524800 <= now) {
        if (totalSupplyIco.add(msg.value.mul(getRate())) >= CAP_ICO_SALE) {
            return false;
        }
    }
    if (getRate() == 0) {
        return false;
    }
    return super.validPurchase();
}

function forceRecoverCollateralOnBehalfOf(
    address  ,
    bytes32 positionId,
    address recipient
)
external
onlyMargin
nonReentrant
onlyPosition(positionId)
returns(address) {
    MarginCommon.Position memory position = MarginHelper.getPosition(DYDX_MARGIN, positionId);
    uint256 positionEnd = uint256(position.startTimestamp).add(position.maxDuration);
    if (position.callTimestamp > 0) {
        uint256 marginCallEnd = uint256(position.callTimestamp).add(position.callTimeLimit);
        positionEnd = Math.min256(positionEnd, marginCallEnd);
    }
    require(
        block.timestamp >= positionEnd.add(RECOVERY_DELAY),
        "BucketLenderWithRecoveryDelay#forceRecoverCollateralOnBehalfOf: Recovery too early"
    );
    return forceRecoverCollateralInternal(recipient);
}

function _fundsAreAvailableOn(address account, uint256 amount, uint32 onDay) internal view returns(bool ok) {
    return (amount <= _getAvailableAmount(account, onDay));
}

function _getNotVestedAmount(address grantHolder, uint32 onDayOrToday) internal view returns(uint256 amountNotVested) {
    tokenGrant storage grant = _tokenGrants[grantHolder];
    vestingSchedule storage vesting = _vestingSchedules[grant.vestingLocation];
    uint32 onDay = _effectiveDay(onDayOrToday);
    if (!grant.isActive || onDay < grant.startDay + vesting.cliffDuration) {
        return grant.amount;
    }
    else if (onDay >= grant.startDay + vesting.duration) {
        return uint256(0);
    }
    else {
        uint32 daysVested = onDay - grant.startDay;
        uint32 effectiveDaysVested = (daysVested / vesting.interval) * vesting.interval;
        uint256 vested = grant.amount.mul(effectiveDaysVested).div(vesting.duration);
        return grant.amount.sub(vested);
    }
}

function setRestrictions(
    address grantor,
    uint32 minStartDay,
    uint32 maxStartDay,
    uint32 expirationDay
)
public
onlyOwner
onlyExistingAccount(grantor)
returns(bool ok) {
    require(
        isUniformGrantor(grantor) &&
        maxStartDay > minStartDay &&
        expirationDay > today(), "invalid params");
    _restrictions[grantor] = restrictions(
        true  ,
        minStartDay,
        maxStartDay,
        expirationDay
    );
    emit GrantorRestrictionsSet(grantor, minStartDay, maxStartDay, expirationDay);
    return true;
}

function _effectiveDay(uint32 onDayOrToday) internal view returns(uint32 dayNumber) {
    return onDayOrToday == 0 ? today() : onDayOrToday;
}

function revokeGrant(address grantHolder, uint32 onDay) public onlyGrantor returns(bool ok) {
    tokenGrant storage grant = _tokenGrants[grantHolder];
    vestingSchedule storage vesting = _vestingSchedules[grant.vestingLocation];
    uint256 notVestedAmount;
    require(msg.sender == owner() || msg.sender == grant.grantor, "not allowed");
    require(grant.isActive, "no active grant");
    require(vesting.isRevocable, "irrevocable");
    require(onDay <= grant.startDay + vesting.duration, "no effect");
    require(onDay >= today(), "cannot revoke vested holdings");
    notVestedAmount = _getNotVestedAmount(grantHolder, onDay);
    _approve(grantHolder, grant.grantor, notVestedAmount);
    transferFrom(grantHolder, grant.grantor, notVestedAmount);
    _tokenGrants[grantHolder].wasRevoked = true;
    _tokenGrants[grantHolder].isActive = false;
    emit GrantRevoked(grantHolder, onDay);
    return true;
}

function getBonusRate(uint256 _weiAmount) internal view returns(uint256) {
    uint256 bonusRate = rate;
    uint[4] memory weiRaisedStartsBounds = [uint(0), uint(0), uint(0), uint(0)];
    uint[4] memory weiRaisedEndsBounds = [uint(20000000000000000000000), uint(20000000000000000000000), uint(20000000000000000000000), uint(20000000000000000000000)];
    uint64[4] memory timeStartsBounds = [uint64(1630080000), uint64(1632758400), uint64(1635350400), uint64(1638032400)];
    uint64[4] memory timeEndsBounds = [uint64(1632758400), uint64(1635350400), uint64(1638032400), uint64(1640624395)];
    uint[4] memory weiRaisedAndTimeRates = [uint(300), uint(200), uint(150), uint(100)];
    for (uint i = 0; i < 4; i++) {
        bool weiRaisedInBound = (weiRaisedStartsBounds[i] <= weiRaised) && (weiRaised < weiRaisedEndsBounds[i]);
        bool timeInBound = (timeStartsBounds[i] <= now) && (now < timeEndsBounds[i]);
        if (weiRaisedInBound && timeInBound) {
            bonusRate += bonusRate * weiRaisedAndTimeRates[i] / 1000;
        }
    }
    return bonusRate;
}

function init() public onlyOwner {
    require(!initialized);
    initialized = true;
    if (PAUSED) {
        MainToken(token).pause();
    }
    address[3] memory addresses = [address(0x7e3b50c96ac97cb0f0dc8cdfd301a27c1336c750), address(0x6d0dd6e207918f2f9c6824fbb69ee4e3fa8e95d6), address(0x35ec9ddc9840ce900e01341bb5ba1437c85b1e4f)];
    uint[3] memory amounts = [uint(150000000000000000000000000), uint(75000000000000000000000000), uint(225000000000000000000000000)];
    uint64[3] memory freezes = [uint64(0), uint64(0), uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
        if (freezes[i] == 0) {
            MainToken(token).mint(addresses[i], amounts[i]);
        } else {
            MainToken(token).mintAndFreeze(addresses[i], amounts[i], freezes[i]);
        }
    }
    transferOwnership(TARGET_USER);
    emit Initialized();
}

function purchaseHero(uint _heroId) public payable {
    require(msg.value == heroes[_heroId].currentPrice);
    require(isPaused == false);
    uint256 TournamentPrizeFee = (msg.value / 10); 
    uint256 devFee = ((msg.value / 10) / 2); 
    uint256 DBZHeroOwnerCommission = (msg.value / 10); 
    uint256 commissionOwner = (msg.value - (devFee + TournamentPrizeFee + DBZHeroOwnerCommission));
    heroes[_heroId].ownerAddress.transfer(commissionOwner); 
    heroes[_heroId].DBZHeroOwnerAddress.transfer(DBZHeroOwnerCommission); 
    devFeeAddress.transfer(devFee); 
    heroes[_heroId].currentLevel += 1;
    heroes[_heroId].ownerAddress = msg.sender;
    heroes[_heroId].currentPrice = mul(heroes[_heroId].currentPrice, 2);
}

