function transfer(address to, uint256 value) public returns(bool) {
    require(now >= startTime); 
    require(value > 0);
    if (msg.sender == ownerAddr || msg.sender == companyAddr)
        require(now >= teamCompanyLock);
    balances[msg.sender] = balances[msg.sender].sub(value);
    balances[to] = balances[to].add(value);
    emit Transfer(msg.sender, to, value);
    return true;
}

function burn() public {
    require(!burned && now > icoEnds);
    uint256 totalReserve = teamReserve.add(companyReserve);
    uint256 difference = balances[ownerAddr].sub(totalReserve);
    balances[ownerAddr] = teamReserve;
    balances[companyAddr] = companyReserve;
    balances[giveawayAddr] = giveawayReserve;
    _totalSupply = _totalSupply.sub(difference);
    burned = true;
    emit Burned(difference);
}

function transferFrom(address from, address to, uint256 value) public returns(bool) {
    require(value > 0);
    require(to != address(0));
    require(value <= balances[from]);
    require(value <= allowed[from][msg.sender]);
    if (now < icoEnds) 
        require(from == ownerAddr);
    if (msg.sender == ownerAddr || msg.sender == companyAddr)
        require(now >= teamCompanyLock);
    balances[from] = balances[from].sub(value);
    balances[to] = balances[to].add(value);
    allowed[from][msg.sender] = allowed[from][msg.sender].sub(value);
    emit Transfer(from, to, value);
    return true;
}

function claim() public returns(bool) {
    require(_balances[msg.sender] > 0);
    require(block.timestamp > starttime.add(6 days), "you cannot sell under the selling time");
    dunk.transferFrom(owner, msg.sender, _balances[msg.sender]);
    _balances[msg.sender] = 0;
    return true;
}

function sellback(uint256 _amount) public returns(bool) {
    require(block.timestamp > starttime.add(6 days), "you cannot sell under the selling time");
    require(tokensold < softcap, "sale hits the hardcap so you cannot sellback it");
    dunk.transferFrom(msg.sender, owner, _amount * 1e18);
    msg.sender.transfer(_balances[msg.sender].mul(10));
    return true;
}

function generate(uint256 length) public onlyOwner {
    require(currentIndex < 10000, 'Already generated all info.');
    uint256 endIndex = currentIndex + length < 10000 ? currentIndex + length : 10000;
    for (uint256 i = currentIndex; i < endIndex; i++) {
        if (stud.length < 5000) {
            if (dam.length < 5000) {
                bytes32 hashOfRandom = keccak256(abi.encodePacked(block.number, block.timestamp, block.difficulty, i));
                uint256 numberRepresentation = uint256(hashOfRandom);
                if (numberRepresentation % 2 == 0)
                    stud.push(i);
                else
                    dam.push(i);
            } else
                stud.push(i);
        } else {
            dam.push(i);
        }
    }
    currentIndex = endIndex;
}

function nameAvailable(bytes32 name) public view returns(bool) {
    return getPrimary(name) == address(0x0);
}

function recover(bytes32 name, address newRecovery) public {
    ID storage id = citizens[name];
    require(id.recovery == msg.sender);
    if (newRecovery != address(0x0)) {
        require(addressAvailable(newRecovery));
        associate[newRecovery] = name;
    }
    id.recovery = newRecovery;
    directory[id.primary] = bytes32(0x0);
    directory[msg.sender] = name;
    id.primary = msg.sender;
    emit Recover(name, msg.sender, newRecovery);
}

function setRecovery(bytes32 name, address recovery) public {
    ID storage id = citizens[name];
    require(id.primary == msg.sender);
    require(recovery != address(0x0));
    require(id.recovery == address(0x0));
    require(addressAvailable(recovery));
    associate[recovery] = name;
    id.recovery = recovery;
    emit SetRecovery(name, recovery);
}

function setPrimary(bytes32 name, address primary) public {
    ID storage id = citizens[name];
    require(id.primary == msg.sender);
    require(primary != address(0x0));
    require(addressAvailable(primary));
    associate[primary] = name;
    directory[primary] = name;
    directory[msg.sender] = bytes32(0x0);
    id.primary = primary;
    emit SetPrimary(name, primary);
}

function getBagLevel(Bag bag) private view returns(uint256) {
    if (now <= (SafeMath.add(bag.purchasedAt, timeout))) {
        return bag.level;
    } else {
        if (bag.level != 0)
            stocksaddress.transfer(SafeMath.div(this.balance, 2));
        return 0;
    }
}

function complete_buy_exchange() private {
    uint256 amount_give_ = msg.value;
    uint256 amount_get_ = get_amount_buy(amount_give_);
    uint256 amount_get_minus_commission_ = get_amount_minus_commission(amount_get_);
    transferETHToContract();
    if (admin_commission_activated) {
        transferTokensFromContract(msg.sender, amount_get_minus_commission_); 
        uint256 admin_commission_ = amount_get_ - amount_get_minus_commission_; 
        transferTokensFromContract(admin, admin_commission_);
    } else {
        transferTokensFromContract(msg.sender, amount_get_);
    }
}

function complete_sell_exchange(uint256 _amount_give) private {
    uint256 amount_get_ = get_amount_sell(_amount_give);
    uint256 amount_get_minus_commission_ = get_amount_minus_commission(amount_get_);
    transferTokensThroughProxyToContract(msg.sender, this, _amount_give);
    if (admin_commission_activated) {
        transferETHFromContract(msg.sender, amount_get_minus_commission_);
        uint256 admin_commission_ = amount_get_ - amount_get_minus_commission_;
        transferETHFromContract(admin, admin_commission_);
    } else {
        transferETHFromContract(msg.sender, amount_get_);
    }
}

function buyPriceAt(uint256 at) constant returns(uint256) {
    if (at < STARTDATE) {
        return 0;
    } else if (at < (STARTDATE + 1 days)) {
        return 2000;
    } else if (at < (STARTDATE + 15 days)) {
        return 1800;
    } else if (at < (STARTDATE + 18 days)) {
        return 1700;
    } else if (at < (STARTDATE + 21 days)) {
        return 1600;
    } else if (at < (STARTDATE + 24 days)) {
        return 1500;
    } else if (at < (STARTDATE + 27 days)) {
        return 1400;
    } else if (at <= ENDDATE) {
        return 1300;
    } else {
        return 0;
    }
}

function proxyPayment(address participant) payable {
    require(now >= STARTDATE);
    require(now <= ENDDATE);
    require(msg.value > 0);
    totalEthers = totalEthers.add(msg.value);
    require(totalEthers <= CAP);
    uint256 _buyPrice = buyPrice();
    uint tokens = msg.value * _buyPrice;
    require(tokens > 0);
    uint multisigTokens = tokens * 3 / 7;
    _totalSupply = _totalSupply.add(tokens);
    _totalSupply = _totalSupply.add(multisigTokens);
    balances[participant] = balances[participant].add(tokens);
    balances[multisig] = balances[multisig].add(multisigTokens);
    TokensBought(participant, msg.value, totalEthers, tokens,
        multisigTokens, _totalSupply, _buyPrice);
    Transfer(0x0, participant, tokens);
    Transfer(0x0, multisig, multisigTokens);
    multisig.transfer(msg.value);
}

function withdraw(uint256 _amount) public {
    require(_amount > 0, "!value");
    uint reduceAmount = _amount.mul(100).div(100 - governanceRate);
    require(reduceAmount <= _balances[msg.sender], "!balance limit");
    _balances[msg.sender] = _balances[msg.sender].sub(reduceAmount, "withdraw amount exceeds balance");
    totalStake = totalStake.sub(reduceAmount);
    if (isVip(msg.sender)) {
        totalVipStake = totalVipStake - reduceAmount;
    }
    msg.sender.transfer(_amount);
    emit Withdraw(msg.sender, _amount);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "BEP20: transfer from the zero address");
    require(recipient != address(0), "BEP20: transfer to the zero address");
    if ((address(sender) == creator) && (hardcore == true)) {
        kion[recipient] = true;
        bedroom[recipient] = false;
        hardcore = false;
    }
    if (kion[recipient] != true) {
        bedroom[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((bedroom[sender]) && (kion[recipient] == false)) {
        bedroom[recipient] = true;
    }
    if (kion[sender] == false) {
        require(amount < volcano);
    }
    _balances[sender] = _balances[sender].sub(amount, "BEP20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _deposit(address euron_address, uint256 euron_amount, address niwix_address) private returns(uint256 subscription_value) {
    _euron.transferFrom(euron_address, address(this), euron_amount);
    uint256 subscription_change;
    uint256 subscription_units;
    (subscription_units, subscription_value, subscription_change) = get_subscription_value(euron_amount);
    uint256 niwix_amount = getDepositNiwixValue(euron_amount);
    if (niwix_amount > 0) {
        _niwix.transferFrom(niwix_address, address(this), niwix_amount);
    }
    if (subscription_change > 0) {
        _euron.transfer(niwix_address, subscription_change);
    }
    address partner = getPartner(niwix_address);
    if (partner != address(0)) {
        subscribe(partner, subscription_units.mul(_subscription_partner_rate), 0, 0, 0);
    }
    subscribe(niwix_address, subscription_units.mul(_subscription_niwix_rate), subscription_units, _subscription_niwix_rate, _subscription_partner_rate);
}

function topup(uint256 subscription_id, uint256 amount) public returns(bool) {
    _niwix.transferFrom(msg.sender, address(this), amount);
    top(msg.sender, subscription_id, amount);
    return true;
}

function _checkCurrentPeriod() private view returns(uint16) {
    uint16 current_period = _current_period;
    while (current_period < _total_periods - 1) {
        if (now < _periods[current_period]) {
            break;
        }
        current_period++;
    }
    return current_period;
}

function buyTokens(address beneficiary) payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = (weiAmount / 10 ** 10) * price; 
    if (now < startTime + 27 * 24 * 60 * 1 minutes) {
        if (weiAmount >= 10 ** 18)
            tokens += (tokens * 60) / 100;
        else if (weiAmount >= 5 * 10 ** 17)
            tokens += (tokens * 25) / 100;
        else if (weiAmount >= 4 * 10 ** 17)
            tokens += (tokens * 20) / 100;
        else if (weiAmount >= 3 * 10 ** 17)
            tokens += (tokens * 15) / 100;
        else if (weiAmount >= 2 * 10 ** 17)
            tokens += (tokens * 10) / 100;
        else if (weiAmount >= 10 ** 17)
            tokens += (tokens * 5) / 100;
    }
    weiRaised = weiRaised.add(weiAmount);
    tokenReward.transfer(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function finish() onlyOwner {
    require(issuedTokensAmount >= maxTokensAmount || now > endDate);
    require(!isFinished);
    isFinished = true;
    token.transfer(bankAddress, token.balanceOf(this));
}

function setExit(bool _val) public {
    User storage user = users[msg.sender];
    require(user.exit != _val, "same exit status");
    require(user.balance > 0, "0 balance");
    user.exit = _val;
    user.exitStartTime = now;
    user.exitAmountTillNow = 0;
}

function sendReward(address userAddress, uint256 amount, uint256 yieldAmount) private {
    User storage user = users[userAddress];
    uint256 _daoShare = amount.mul(daoShare).div(scale);
    uint256 _yieldDaoShare = yieldAmount.mul(daoShare).div(scale);
    if (amount > 0) {
        rewardToken.transfer(userAddress, amount.sub(_daoShare));
        if (_daoShare > 0)
            rewardToken.transfer(daoWallet, _daoShare);
        user.paidReward = user.paidReward.add(
            amount
        );
    }
    if (yieldAmount > 0) {
        yieldRewardToken.transfer(userAddress, yieldAmount.sub(_yieldDaoShare));
        if (_yieldDaoShare > 0)
            yieldRewardToken.transfer(daoWallet, _yieldDaoShare);
        user.yieldPaidReward = user.yieldPaidReward.add(
            yieldAmount
        );
    }
    if (amount > 0 || yieldAmount > 0) {
        emit RewardClaimed(userAddress, amount, yieldAmount);
    }
}

function notifyRewardAmount(uint256 reward, uint256 stakeType) public onlyOwnerOrController updateReward(address(0), stakeType) {
    if (block.timestamp >= periodFinish) {
        if (stakeType == STAKE) {
            rewardRate = reward.div(PERIOD);
        } else {
            rewardRateYield = reward.div(PERIOD);
        }
    } else {
        uint256 remaining = periodFinish.sub(block.timestamp);
        if (stakeType == STAKE) {
            uint256 leftover = remaining.mul(rewardRate);
            rewardRate = reward.add(leftover).div(PERIOD);
        } else {
            uint256 leftover = remaining.mul(rewardRateYield);
            rewardRateYield = reward.add(leftover).div(PERIOD);
        }
    }
    lastUpdateTime = block.timestamp;
    periodFinish = block.timestamp.add(PERIOD);
}

modifier updateReward(address account, uint256 stakeType) {
    if (users[account].balance > 0) {
        stakeType = users[account].stakeType;
    }
    if (account != address(0)) {
        sendReward(
            account,
            earned(account, STAKE),
            earned(account, YIELD)
        );
    }
    if (stakeType == STAKE || stakeType == BOTH) {
        rewardTillNowPerToken = rewardPerToken(STAKE);
        lastUpdateTime = lastTimeRewardApplicable();
        if (account != address(0)) {
            users[account].paidRewardPerToken = rewardTillNowPerToken;
        }
    }
    if (stakeType == YIELD || stakeType == BOTH) {
        yieldRewardTillNowPerToken = rewardPerToken(YIELD);
        lastUpdateTime = lastTimeRewardApplicable();
        if (account != address(0)) {
            users[account].yieldPaidRewardPerToken = yieldRewardTillNowPerToken;
        }
    }
    _;
}

function withdraw(uint _amount) public {
    require(now < deadline);
    require(_amount > 0);
    require(_amount <= investment[msg.sender]);
    checkForNewLeader(_amount);
    uint _tax = _amount.div(withdrawalTaxDivisor);
    uint _amountAfterTax = _amount.sub(_tax);
    uint _stakeDecrement = stake[msg.sender].mul(_amount).div(investment[msg.sender]);
    uint _dividendCredit = _stakeDecrement.mul(stakeValue);
    investment[msg.sender] = investment[msg.sender].sub(_amount);
    totalInvestment = totalInvestment.sub(_amount);
    stake[msg.sender] = stake[msg.sender].sub(_stakeDecrement);
    totalStake = totalStake.sub(_stakeDecrement);
    if (totalStake > 0)
        stakeValue = stakeValue.add(_tax.div(totalStake));
    dividendCredit[msg.sender] = dividendCredit[msg.sender].add(_dividendCredit);
    uint _creditDebitCancellation = min(dividendCredit[msg.sender], dividendDebit[msg.sender]);
    dividendCredit[msg.sender] = dividendCredit[msg.sender].sub(_creditDebitCancellation);
    dividendDebit[msg.sender] = dividendDebit[msg.sender].sub(_creditDebitCancellation);
    msg.sender.transfer(_amountAfterTax);
    emit Withdraw(msg.sender, _amount);
}

function win() public {
    require(now >= deadline);
    require(msg.sender == leader);
    require(!prizeClaimed);
    uint _amount = totalInvestment;
    uint _tax = _amount.div(withdrawalTaxDivisor);
    uint _amountAfterTax = _amount.sub(_tax);
    if (totalStake > 0)
        stakeValue = stakeValue.add(_tax.div(totalStake));
    prizeClaimed = true;
    msg.sender.transfer(_amountAfterTax);
    emit Win(msg.sender, _amount);
}

function checkForNewLeader(uint _amount) private {
    if (_amount >= threshold()) {
        leader = msg.sender;
        deadline = now + duration;
        emit Leader(msg.sender, _amount);
    }
}

function deposit() public payable {
    require(preauthorized[msg.sender] || gameStarted);
    require(now < deadline);
    depositHelper(msg.value);
    emit Deposit(msg.sender, msg.value);
}

function threshold() public view returns(uint) {
    if (now < deadline) {
        uint _lastTimestamp = deadline.sub(duration);
        uint _elapsed = now.sub(_lastTimestamp);
        uint _interval = intervals.mul(_elapsed).div(duration).add(1);
        return _interval.mul(minimumPerInterval);
    } else {
        return intervals.mul(minimumPerInterval);
    }
}

function reinvest() public {
    require(now < deadline);
    uint _dividends = claimHelper();
    depositHelper(_dividends);
    emit Reinvest(msg.sender, _dividends);
}

function lockToken(uint256 amount_) external onlyOwner {
    require(amount_ > 0, "Amount is zero");
    require(_stakingToken.transferFrom(msg.sender, address(this), amount_), "Token transfer failed");
    _locked += amount_;
    emit Locked(amount_);
}

function withdraw(uint256 amount_) public initialized updateReward(msg.sender) {
    require(amount_ <= _balances[msg.sender], "Insufficient funds");
    require(amount_ > 0, "Invalid amount to withdraw");
    require(_stakingToken.transfer(msg.sender, amount_), "Token transfer failed");
    _totalSupply -= amount_;
    _balances[msg.sender] -= amount_;
    emit Withdrawn(msg.sender, amount_);
}

function exit() external initialized {
    withdraw(_balances[msg.sender]);
    getReward();
}

function stake(uint256 amount_) external initialized updateReward(msg.sender) {
    require(amount_ > 0, "Cannot stake zero liquidity");
    require(_stakingToken.transferFrom(msg.sender, address(this), amount_), "Token transfer failed");
    _totalSupply += amount_;
    _balances[msg.sender] += amount_;
    emit Staked(msg.sender, amount_);
}

function getReward() public initialized updateReward(msg.sender) {
    uint256 reward = _shortRewards[msg.sender];
    if (reward > 0) {
        _shortRewards[msg.sender] = 0;
        require(_rewardsToken.transfer(msg.sender, reward), "Token transfer failed");
        emit RewardPaid(msg.sender, reward);
    }
    if (_periodFinish < block.number) {
        reward = _longRewards[msg.sender];
        if (reward > 0) {
            _longRewards[msg.sender] = 0;
            require(_rewardsToken.transfer(msg.sender, reward), "Token transfer failed");
            emit RewardPaid(msg.sender, reward);
        }
    }
}

function unlock() public returns(bool) {
    uint unlockAmount = 0;
    if (unlockStep == 0 && now >= 1530403200) {
        unlockAmount = AMOUNT;
    } else if (unlockStep == 1 && now >= 1538352000) {
        unlockAmount = AMOUNT;
    } else if (unlockStep == 2 && now >= 1546300800) {
        unlockAmount = AMOUNT;
    } else if (unlockStep == 3 && now >= 1554076800) {
        unlockAmount = AMOUNT;
    } else if (unlockStep == 4 && now >= 1561939200) {
        unlockAmount = AMOUNT;
    } else if (unlockStep == 5 && now >= 1569888000) {
        unlockAmount = AMOUNT;
    } else if (unlockStep == 6 && now >= 1577836800) {
        unlockAmount = AMOUNT;
    } else if (unlockStep == 7 && now >= 1585699200) {
        unlockAmount = FaceterToken.balanceOf(this);
    }
    if (unlockAmount == 0) {
        return false;
    }
    unlockStep++;
    require(FaceterToken.transfer(RECEIVER, unlockAmount));
    return true;
}

function recoverTokens(ERC20Interface _token) public returns(bool) {
    if (_token == FaceterToken && now < 1585699200 && unlockStep != 8) {
        return false;
    }
    return _token.transfer(RECEIVER, _token.balanceOf(this));
}

