function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * 8 / 100 * (block.number - atBlock[msg.sender]) / 5900;
        address sender = msg.sender;
        sender.send(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function _updateStake(address user, uint256 stake) internal returns(bool) {
    uint256 oldStake = _users[user].stake;
    if (stake > oldStake) {
        _increaseStake(user, stake.sub(oldStake));
    }
    if (stake < oldStake) {
        _decreaseStake(user, oldStake.sub(stake));
    }
}

function seed() external {
    require(!isSeeded);
    TransferHelper.safeTransferFrom(COFFEE_ADDRESS, msg.sender, address(this), INITIAL_COFFEE_SUPPLY);
    isSeeded = true;
}

function _stakePoolShare(address _account, uint _shares) internal {
    UserInfo storage user = userInfo[_account];
    getAllRewards(_account);
    user.amount = user.amount.add(_shares);
    uint8 rewardPoolLength = uint8(rewardPoolInfo.length);
    for (uint8 _pid = 0; _pid < rewardPoolLength; ++_pid) {
        user.rewardDebt[_pid] = user.amount.mul(rewardPoolInfo[_pid].accRewardPerShare).div(1e18);
    }
    user.lastStakeTime = block.timestamp;
    emit Deposit(_account, _shares);
}

function joinPoolNotStake(uint poolAmountOut, uint[] calldata maxAmountsIn) external _lock_ {
    _joinPool(msg.sender, poolAmountOut, maxAmountsIn);
    _pushPoolShare(msg.sender, poolAmountOut);
}

function exitPool(uint poolAmountIn, uint[] calldata minAmountsOut) external override _lock_ {
    require(finalized, "!fnl");
    uint rewardTotal = totalSupply();
    uint _exitFee = bmul(poolAmountIn, exitFee);
    uint pAiAfterExitFee = bsub(poolAmountIn, _exitFee);
    uint ratio = bdiv(pAiAfterExitFee, rewardTotal);
    require(ratio != 0, "erMApr");
    uint _externalShares = balanceOf(msg.sender);
    if (_externalShares < poolAmountIn) {
        uint _withdrawShares = bsub(poolAmountIn, _externalShares);
        uint _stakedShares = userInfo[msg.sender].amount;
        require(_stakedShares >= _withdrawShares, "stk<wdr");
        withdraw(_withdrawShares);
    }
    _pullPoolShare(msg.sender, poolAmountIn);
    if (_exitFee > 0) {
        _pushPoolShare(factory, _exitFee);
    }
    _burnPoolShare(pAiAfterExitFee);
    for (uint i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint bal = _records[t].balance;
        uint tokenAmountOut = bmul(ratio, bal);
        require(tokenAmountOut != 0, "erMApr");
        require(tokenAmountOut >= minAmountsOut[i], "<limO");
        _records[t].balance = bsub(_records[t].balance, tokenAmountOut);
        emit LOG_EXIT(msg.sender, t, tokenAmountOut);
        _pushUnderlying(t, msg.sender, tokenAmountOut);
    }
}

function withdraw(uint _amount) public override {
    UserInfo storage user = userInfo[msg.sender];
    require(user.amount >= _amount, "am>us.am");
    require(block.timestamp >= user.lastStakeTime.add(unstakingFrozenTime), "frozen");
    getAllRewards(msg.sender);
    user.amount = bsub(user.amount, _amount);
    uint8 rewardPoolLength = uint8(rewardPoolInfo.length);
    for (uint8 _pid = 0; _pid < rewardPoolLength; ++_pid) {
        user.rewardDebt[_pid] = user.amount.mul(rewardPoolInfo[_pid].accRewardPerShare).div(1e18);
    }
    _pushPoolShare(msg.sender, _amount);
    emit Withdraw(msg.sender, _amount);
}

function swapExactAmountIn(
    address tokenIn,
    uint tokenAmountIn,
    address tokenOut,
    uint minAmountOut,
    uint maxPrice
)
external
_lock_
returns(uint tokenAmountOut, uint spotPriceAfter) {
    require(_records[tokenIn].bound, "!bound");
    require(_records[tokenOut].bound, "!bound");
    Record storage inRecord = _records[address(tokenIn)];
    Record storage outRecord = _records[address(tokenOut)];
    require(tokenAmountIn <= bmul(inRecord.balance, BConst.MAX_IN_RATIO), ">maxIRat");
    uint spotPriceBefore = calcSpotPrice(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        swapFee
    );
    require(spotPriceBefore <= maxPrice, "badLimPrice");
    tokenAmountOut = calcOutGivenIn(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        tokenAmountIn,
        swapFee
    );
    require(tokenAmountOut >= minAmountOut, "<limO");
    inRecord.balance = badd(inRecord.balance, tokenAmountIn);
    outRecord.balance = bsub(outRecord.balance, tokenAmountOut);
    spotPriceAfter = calcSpotPrice(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        swapFee
    );
    require(spotPriceAfter >= spotPriceBefore, "erMApr");
    require(spotPriceAfter <= maxPrice, ">limPrice");
    require(spotPriceBefore <= bdiv(tokenAmountIn, tokenAmountOut), "erMApr");
    emit LOG_SWAP(msg.sender, tokenIn, tokenOut, tokenAmountIn, tokenAmountOut);
    _pullUnderlying(tokenIn, msg.sender, tokenAmountIn);
    uint _subTokenAmountIn;
    (_subTokenAmountIn, tokenAmountOut) = _pushCollectedFundGivenOut(tokenIn, tokenAmountIn, tokenOut, tokenAmountOut);
    if (_subTokenAmountIn > 0) inRecord.balance = bsub(inRecord.balance, _subTokenAmountIn);
    _pushUnderlying(tokenOut, msg.sender, tokenAmountOut);
    return (tokenAmountOut, spotPriceAfter);
}

function joinPool(uint poolAmountOut, uint[] calldata maxAmountsIn)
external virtual
_lock_ {
    require(finalized, "!fnl");
    uint poolTotal = totalSupply();
    uint ratio = bdiv(poolAmountOut, poolTotal);
    require(ratio != 0, "erMApr");
    for (uint i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint bal = _records[t].balance;
        uint tokenAmountIn = bmul(ratio, bal);
        require(tokenAmountIn != 0, "erMApr");
        require(tokenAmountIn <= maxAmountsIn[i], "<limIn");
        _records[t].balance = badd(_records[t].balance, tokenAmountIn);
        emit LOG_JOIN(msg.sender, t, tokenAmountIn);
        _pullUnderlying(t, msg.sender, tokenAmountIn);
    }
    _mintPoolShare(poolAmountOut);
    _pushPoolShare(msg.sender, poolAmountOut);
}

function _joinPool(address account, uint poolAmountOut, uint[] calldata maxAmountsIn) internal {
    require(finalized, "!fnl");
    uint rewardTotal = totalSupply();
    uint ratio = bdiv(poolAmountOut, rewardTotal);
    require(ratio != 0, "erMApr");
    for (uint i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint bal = _records[t].balance;
        uint tokenAmountIn = bmul(ratio, bal);
        require(tokenAmountIn != 0 && tokenAmountIn <= maxAmountsIn[i], "erMApr||<limIn");
        _records[t].balance = badd(_records[t].balance, tokenAmountIn);
        emit LOG_JOIN(account, t, tokenAmountIn);
        _pullUnderlying(t, msg.sender, tokenAmountIn);
    }
    _mintPoolShare(poolAmountOut);
}

function joinswapExternAmountIn(address tokenIn, uint tokenAmountIn, uint minPoolAmountOut)
external
_lock_
returns(uint poolAmountOut)
{
    require(finalized, "!fnl");
    require(_records[tokenIn].bound, "!bound");
    require(tokenAmountIn <= bmul(_records[tokenIn].balance, BConst.MAX_IN_RATIO), ">maxIRat");
    Record storage inRecord = _records[tokenIn];
    poolAmountOut = calcPoolOutGivenSingleIn(
        inRecord.balance,
        inRecord.denorm,
        _totalSupply,
        _totalWeight,
        tokenAmountIn,
        swapFee
    );
    require(poolAmountOut >= minPoolAmountOut, "<limO");
    inRecord.balance = badd(inRecord.balance, tokenAmountIn);
    emit LOG_JOIN(msg.sender, tokenIn, tokenAmountIn);
    _mintPoolShare(poolAmountOut);
    _pullUnderlying(tokenIn, msg.sender, tokenAmountIn);
    uint _subTokenAmountIn;
    (_subTokenAmountIn, poolAmountOut) = _pushCollectedFundGivenOut(tokenIn, tokenAmountIn, address(this), poolAmountOut);
    if (_subTokenAmountIn > 0) inRecord.balance = bsub(inRecord.balance, _subTokenAmountIn);
    _pushPoolShare(msg.sender, poolAmountOut);
    return poolAmountOut;
}

function getReward(uint8 _pid, address _account) public override {
    updateReward(_pid);
    UserInfo storage user = userInfo[_account];
    RewardPoolInfo storage rewardPool = rewardPoolInfo[_pid];
    uint _pendingReward = user.amount.mul(rewardPool.accRewardPerShare).div(1e18).sub(user.rewardDebt[_pid]);
    uint _lockRewardPercent = rewardPool.lockRewardPercent;
    if (_lockRewardPercent > 0) {
        if (block.number > rewardPool.endVestingBlock) {
            uint _unlockReward = user.lockReward[_pid].sub(user.lockRewardReleased[_pid]);
            if (_unlockReward > 0) {
                _pendingReward = _pendingReward.add(_unlockReward);
                user.lockRewardReleased[_pid] = user.lockRewardReleased[_pid].add(_unlockReward);
            }
        } else {
            if (_pendingReward > 0) {
                uint _toLocked = _pendingReward.mul(_lockRewardPercent).div(100);
                _pendingReward = _pendingReward.sub(_toLocked);
                user.lockReward[_pid] = user.lockReward[_pid].add(_toLocked);
            }
            if (block.number > rewardPool.startVestingBlock) {
                uint _toReleased = user.lockReward[_pid].mul(block.number.sub(rewardPool.startVestingBlock)).div(rewardPool.numOfVestingBlocks);
                uint _lockRewardReleased = user.lockRewardReleased[_pid];
                if (_toReleased > _lockRewardReleased) {
                    uint _unlockReward = _toReleased.sub(_lockRewardReleased);
                    user.lockRewardReleased[_pid] = _lockRewardReleased.add(_unlockReward);
                    _pendingReward = _pendingReward.add(_unlockReward);
                }
            }
        }
    }
    if (_pendingReward > 0) {
        user.accumulatedEarned[_pid] = user.accumulatedEarned[_pid].add(_pendingReward);
        rewardPool.totalPaidRewards = rewardPool.totalPaidRewards.add(_pendingReward);
        rewardFund.safeTransfer(rewardPool.rewardToken, _account, _pendingReward);
        emit RewardPaid(_pid, _account, _pendingReward);
        user.rewardDebt[_pid] = user.amount.mul(rewardPoolInfo[_pid].accRewardPerShare).div(1e18);
    }
}

function swapExactAmountOut(
    address tokenIn,
    uint maxAmountIn,
    address tokenOut,
    uint tokenAmountOut,
    uint maxPrice
)
external
_lock_
returns(uint tokenAmountIn, uint spotPriceAfter) {
    require(_records[tokenIn].bound, "!bound");
    require(_records[tokenOut].bound, "!bound");
    Record storage inRecord = _records[address(tokenIn)];
    Record storage outRecord = _records[address(tokenOut)];
    require(tokenAmountOut <= bmul(outRecord.balance, BConst.MAX_OUT_RATIO), ">maxORat");
    uint spotPriceBefore = calcSpotPrice(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        swapFee
    );
    require(spotPriceBefore <= maxPrice, "badLimPrice");
    tokenAmountIn = calcInGivenOut(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        tokenAmountOut,
        swapFee
    );
    require(tokenAmountIn <= maxAmountIn, "<limIn");
    inRecord.balance = badd(inRecord.balance, tokenAmountIn);
    outRecord.balance = bsub(outRecord.balance, tokenAmountOut);
    spotPriceAfter = calcSpotPrice(
        inRecord.balance,
        inRecord.denorm,
        outRecord.balance,
        outRecord.denorm,
        swapFee
    );
    require(spotPriceAfter >= spotPriceBefore, "erMApr");
    require(spotPriceAfter <= maxPrice, ">limPrice");
    require(spotPriceBefore <= bdiv(tokenAmountIn, tokenAmountOut), "erMApr");
    emit LOG_SWAP(msg.sender, tokenIn, tokenOut, tokenAmountIn, tokenAmountOut);
    _pullUnderlying(tokenIn, msg.sender, tokenAmountIn);
    _pushUnderlying(tokenOut, msg.sender, tokenAmountOut);
    uint _collectedFeeAmount = _pushCollectedFundGivenIn(tokenIn, tokenAmountIn);
    if (_collectedFeeAmount > 0) inRecord.balance = bsub(inRecord.balance, _collectedFeeAmount);
    return (tokenAmountIn, spotPriceAfter);
}

function getTokensUnlocked(address role) private view returns(uint256) {
    uint256 allowedTokens;
    for (uint8 i = 0; i < stages.length; i++) {
        if (now >= stages[i].date) {
            if (role == FOUNDERS_ADDRESS) {
                allowedTokens = stages[i].foundersTokensUnlocked;
            } else if (role == ADVISORS_ADDRESS) {
                allowedTokens = stages[i].advisorsTokensUnlocked;
            } else if (role == TEAM_ADDRESS) {
                allowedTokens = stages[i].teamTokensUnlocked;
            }
        }
    }
    return allowedTokens;
}

function sell(uint256 amount) payable public returns(uint256 revenue) {
    require(balanceOf[msg.sender] >= amount);
    balanceOf[msg.sender] -= amount;
    balanceOf[centralMinter] += amount;
    revenue = amount * sellPrice / divisor;
    msg.sender.transfer(revenue);
    emit Transfer(msg.sender, centralMinter, amount);
    return revenue;
}

function play(bytes32 luckyblockId) public payable whenNotPaused {
    require(!isContract(msg.sender));
    LuckyblockBase storage _luckyblockBase = luckyblockIdToLuckyblockBase[luckyblockId];
    LuckyblockSpend storage _luckyblockSpend = luckyblockIdToLuckyblockSpend[luckyblockId];
    LuckyblockEarn storage _luckyblockEarn = luckyblockIdToLuckyblockEarn[luckyblockId];
    require(!_luckyblockBase.ended, "luckyblock is ended");
    require(msg.value >= _luckyblockSpend.spendEtherCount, "sender value not enough");
    if (_luckyblockSpend.spendTokenAddresses[0] != address(0x0)) {
        for (uint8 i = 0; i < _luckyblockSpend.spendTokenAddresses.length; i++) {
            require(
                ERC20Interface(
                    _luckyblockSpend.spendTokenAddresses[i]
                ).balanceOf(address(msg.sender)) >= _luckyblockSpend.spendTokenCount[i]
            );
            require(
                ERC20Interface(
                    _luckyblockSpend.spendTokenAddresses[i]
                ).allowance(address(msg.sender), address(this)) >= _luckyblockSpend.spendTokenCount[i]
            );
            ERC20Interface(_luckyblockSpend.spendTokenAddresses[i])
                .transferFrom(msg.sender, address(this), _luckyblockSpend.spendTokenCount[i]);
        }
    }
    if (_luckyblockEarn.earnTokenAddresses[0] !=
        address(0x0)) {
        for (uint8 j = 0; j < _luckyblockEarn.earnTokenAddresses.length; j++) {
            uint256 earnTokenCount = _luckyblockEarn.earnTokenCount[j];
            require(
                ERC20Interface(_luckyblockEarn.earnTokenAddresses[j])
                .balanceOf(address(this)) >= earnTokenCount
            );
        }
    }
    require(address(this).balance >= _luckyblockEarn.earnEtherCount, "contract value not enough");
    uint8 _random = random();
    for (uint8 k = 0; k < _luckyblockEarn.earnTokenAddresses.length; k++) {
        if (_luckyblockEarn.earnTokenAddresses[0] !=
            address(0x0)) {
            if (_random + _luckyblockEarn.earnTokenProbability[k] >= 100) {
                ERC20Interface(_luckyblockEarn.earnTokenAddresses[k])
                    .transfer(msg.sender, _luckyblockEarn.earnTokenCount[k]);
            }
        }
    }
    uint256 value = msg.value;
    uint256 payExcess = value.sub(_luckyblockSpend.spendEtherCount);
    if (_random + _luckyblockEarn.earnEtherProbability >= 100) {
        uint256 balance = _luckyblockEarn.earnEtherCount.add(payExcess);
        if (balance > 0) {
            msg.sender.transfer(balance);
        }
    } else if (payExcess > 0) {
        msg.sender.transfer(payExcess);
    }
    emit Play(luckyblockId, msg.sender, _random);
}

function withdrawEth(address to, uint256 balance) external onlySuperuser {
    if (balance == uint256(0x0)) {
        to.transfer(address(this).balance);
        emit WithdrawEth(to, address(this).balance);
    } else {
        to.transfer(balance);
        emit WithdrawEth(to, balance);
    }
}

function serverForceGameEnd(
    uint8 _gameType,
    uint _betNum,
    uint _betValue,
    int _balance,
    uint _stake,
    uint _endInitiatedTime
)
public
view
onlyValidBalance(_balance, _stake)
returns(int) {
    require(_endInitiatedTime + SERVER_TIMEOUT <= block.timestamp);
    require(isValidBet(_gameType, _betNum, _betValue) ||
        (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0));
    int newBalance = _balance - int(_betValue);
    newBalance -= NOT_ENDED_FINE;
    int stake = int(_stake);
    if (newBalance < -stake) {
        newBalance = -stake;
    }
    return newBalance;
}

function playerForceGameEnd(
    uint8 _gameType,
    uint _betNum,
    uint _betValue,
    int _balance,
    uint _stake,
    uint _endInitiatedTime
)
public
view
onlyValidBalance(_balance, _stake)
returns(int) {
    require(_endInitiatedTime + PLAYER_TIMEOUT <= block.timestamp);
    require(isValidBet(_gameType, _betNum, _betValue) ||
        (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0));
    int profit = 0;
    if (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0) {
        profit = 0;
    } else {
        profit = calculateDiceProfit(_betNum, _betValue);
    }
    profit += NOT_ENDED_FINE;
    return _balance + profit;
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        require(Token(trustedRewardTokenAddress).transfer(account, pendingDivs.mul(getTokenPerDaiUniswap()).div(1e18)), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
}

function distributeDividend(address shareholder) internal {
    if (shares[shareholder].amount == 0) {
        return;
    }
    uint256 amount = getUnpaidEarnings(shareholder);
    if (amount > 0) {
        totalDistributed = totalDistributed.add(amount);
        RWRD.transfer(shareholder, amount);
        shareholderClaims[shareholder] = block.timestamp;
        shares[shareholder].totalRealised = shares[shareholder].totalRealised.add(amount);
        shares[shareholder].totalExcluded = getCumulativeDividends(shares[shareholder].amount);
        emit Distribution(shareholder, amount);
    }
}

function process(uint256 gas) external override onlyToken {
    uint256 shareholderCount = shareholders.length;
    if (shareholderCount == 0) {
        return;
    }
    uint256 gasUsed = 0;
    uint256 gasLeft = gasleft();
    uint256 iterations = 0;
    uint256 count = 0;
    while (gasUsed < gas && iterations < shareholderCount) {
        if (currentIndex >= shareholderCount) {
            currentIndex = 0;
        }
        if (shouldDistribute(shareholders[currentIndex])) {
            distributeDividend(shareholders[currentIndex]);
            count++;
        }
        gasUsed = gasUsed.add(gasLeft.sub(gasleft()));
        gasLeft = gasleft();
        currentIndex++;
        iterations++;
    }
    emit DividendsProcessed(iterations, count, currentIndex);
}

function setShare(address shareholder, uint256 amount) external override onlyToken {
    distributeDividend(shareholder);
    if (amount > 0 && shares[shareholder].amount == 0) {
        addShareholder(shareholder);
    } else if (amount == 0 && shares[shareholder].amount > 0) {
        removeShareholder(shareholder);
    }
    totalShares = totalShares.sub(shares[shareholder].amount).add(amount);
    shares[shareholder].amount = amount;
    shares[shareholder].totalExcluded = getCumulativeDividends(shares[shareholder].amount);
    emit ShareUpdated(shareholder, amount);
}

function deposit() external payable override {
    uint256 balanceBefore = RWRD.balanceOf(address(this));
    address[] memory path = new address[](2);
    path[0] = WFTM;
    path[1] = address(RWRD);
    router.swapExactETHForTokensSupportingFeeOnTransferTokens {
        value: msg.value
    }(
        0,
        path,
        address(this),
        block.timestamp
    );
    uint256 amount = RWRD.balanceOf(address(this)).sub(balanceBefore);
    totalDividends = totalDividends.add(amount);
    dividendsPerShare = dividendsPerShare.add(dividendsPerShareAccuracyFactor.mul(amount).div(totalShares));
    emit Deposit(msg.value, amount);
}

function swapBack() internal swapping {
    if (liquidityFeeAccumulator >= swapThreshold && autoLiquifyEnabled) {
        liquidityFeeAccumulator = liquidityFeeAccumulator.sub(swapThreshold);
        uint256 amountToLiquify = swapThreshold.div(2);
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = WFTM;
        uint256 balanceBefore = address(this).balance;
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToLiquify,
            0,
            path,
            address(this),
            block.timestamp
        );
        uint256 amountETH = address(this).balance.sub(balanceBefore);
        router.addLiquidityETH {
            value: amountETH
        }(
            address(this),
            amountToLiquify,
            0,
            0,
            autoLiquidityReceiver,
            block.timestamp
        );
        emit AutoLiquify(amountETH, amountToLiquify);
    } else {
        uint256 amountToSwap = swapThreshold;
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = WFTM;
        uint256 balanceBefore = address(this).balance;
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            amountToSwap,
            0,
            path,
            address(this),
            block.timestamp
        );
        uint256 amountETH = address(this).balance.sub(balanceBefore);
        uint256 amountETHReflection = amountETH.mul(reflectionFee).div(totalFee);
        uint256 amountETHMarketing = amountETH.mul(marketingFee).div(totalFee);
        uint256 amountETHDev = amountETH.mul(devFee).div(totalFee);
        try distributor.deposit {
            value: amountETHReflection
        }() {} catch {}
        (bool success, ) = payable(marketingFeeReceiver).call {
            value: amountETHMarketing,
            gas: 10000000
        }("");
        if (success) {
            marketingFees = marketingFees.add(amountETHMarketing);
        }
        (success, ) = payable(devFeeReceiver).call {
            value: amountETHDev,
            gas: 10000000
        }("");
        if (success) {
            devFees = devFees.add(amountETHDev);
        }
        emit SwapBack(amountToSwap, amountETH);
    }
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    require(bannedUsers[sender] == false, "Sender is banned");
    require(bannedUsers[recipient] == false, "Recipient is banned");
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    checkLaunched(sender);
    checkTxLimit(sender, amount);
    checkWalletLimit(recipient, amount);
    if (shouldSwapBack()) {
        swapBack();
    }
    if (shouldAutoBuyback()) {
        triggerAutoBuyback();
    }
    if (!launched() && recipient == pair) {
        require(_balances[sender] > 0);
        launch();
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    uint256 amountReceived = shouldTakeFee(sender) ? takeFee(sender, recipient, amount) : amount;
    _balances[recipient] = _balances[recipient].add(amountReceived);
    if (!isDividendExempt[sender]) {
        try distributor.setShare(sender, _balances[sender]) {} catch {}
    }
    if (!isDividendExempt[recipient]) {
        try distributor.setShare(recipient, _balances[recipient]) {} catch {}
    }
    if (autoClaimEnabled) {
        try distributor.process(distributorGas) {} catch {}
    }
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function setWalletBanStatus(address user, bool banned) external authorized {
    if (banned) {
        require(block.timestamp + 3650 days > block.timestamp, "User was put in a cage.");
        bannedUsers[user] = true;
    } else {
        delete bannedUsers[user];
    }
    emit WalletBanStatusUpdated(user, banned);
}

function enterDungeon(uint256[4] _tokenIds, uint32 _tryingProgress)
whenNotPaused
public {
    require(_tokenIds[0] == 0 || (_tokenIds[0] != _tokenIds[1] && _tokenIds[0] != _tokenIds[2] && _tokenIds[0] != _tokenIds[3]));
    require(_tokenIds[1] == 0 || (_tokenIds[1] != _tokenIds[0] && _tokenIds[1] != _tokenIds[2] && _tokenIds[1] != _tokenIds[3]));
    require(_tokenIds[2] == 0 || (_tokenIds[2] != _tokenIds[0] && _tokenIds[2] != _tokenIds[1] && _tokenIds[2] != _tokenIds[3]));
    require(_tokenIds[3] == 0 || (_tokenIds[3] != _tokenIds[0] && _tokenIds[3] != _tokenIds[1] && _tokenIds[3] != _tokenIds[2]));
    if (requiredProgressOfPreviousDungeon != 0) {
        require(progressContract.getProgressOfAddressAndId(msg.sender, previousDungeonId) >= requiredProgressOfPreviousDungeon);
    }
    require(_tryingProgress > 0);
    require(_tryingProgress <= progressContract.getProgressOfAddressAndId(msg.sender, locationId) + 1);
    require(addressToPlayRecordDateTime[msg.sender] + coolDungeon <= now);
    require(checkOwnershipAndAvailability(msg.sender, _tokenIds));
    addressToPlayRecordDateTime[msg.sender] = now;
    seed += uint32(now);
    PlayRecord memory _playRecord;
    _playRecord.initialSeed = seed;
    _playRecord.progress = _tryingProgress;
    _playRecord.tokenIds[0] = _tokenIds[0];
    _playRecord.tokenIds[1] = _tokenIds[1];
    _playRecord.tokenIds[2] = _tokenIds[2];
    _playRecord.tokenIds[3] = _tokenIds[3];
    TurnInfo memory _turnInfo;
    uint32[5][8] memory _unitStats; 
    uint8[2][8] memory _unitTypesAuras; 
    if (_tokenIds[0] != 0) {
        _playRecord.unitClassIds[0] = heroContract.getHeroClassId(_tokenIds[0]);
        (_playRecord.unitLevels[0], _turnInfo.originalExps[0], _unitStats[0], , ) = correctedHeroContract.getCorrectedStats(_tokenIds[0]);
        (, , , , _unitTypesAuras[0][0], , _unitTypesAuras[0][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[0]);
    }
    if (_tokenIds[1] != 0) {
        _playRecord.unitClassIds[1] = heroContract.getHeroClassId(_tokenIds[1]);
        (_playRecord.unitLevels[1], _turnInfo.originalExps[1], _unitStats[1], , ) = correctedHeroContract.getCorrectedStats(_tokenIds[1]);
        (, , , , _unitTypesAuras[1][0], , _unitTypesAuras[1][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[1]);
    }
    if (_tokenIds[2] != 0) {
        _playRecord.unitClassIds[2] = heroContract.getHeroClassId(_tokenIds[2]);
        (_playRecord.unitLevels[2], _turnInfo.originalExps[2], _unitStats[2], , ) = correctedHeroContract.getCorrectedStats(_tokenIds[2]);
        (, , , , _unitTypesAuras[2][0], , _unitTypesAuras[2][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[2]);
    }
    if (_tokenIds[3] != 0) {
        _playRecord.unitClassIds[3] = heroContract.getHeroClassId(_tokenIds[3]);
        (_playRecord.unitLevels[3], _turnInfo.originalExps[3], _unitStats[3], , ) = correctedHeroContract.getCorrectedStats(_tokenIds[3]);
        (, , , , _unitTypesAuras[3][0], , _unitTypesAuras[3][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[3]);
    }
    var _enemyCombination = addressToEnemyCombination[msg.sender];
    if (_enemyCombination.isPersonalized == false) {
        _enemyCombination = initialEnemyCombination;
    }
    uint32[5][8] memory _tmpEnemyBaseStatsAndIVs; 
    (, , , , _unitTypesAuras[4][0], , _unitTypesAuras[4][1], _tmpEnemyBaseStatsAndIVs[0], _tmpEnemyBaseStatsAndIVs[4], ) = heroContract.getClassInfo(_enemyCombination.enemySlotClassIds[0]);
    (, , , , _unitTypesAuras[5][0], , _unitTypesAuras[5][1], _tmpEnemyBaseStatsAndIVs[1], _tmpEnemyBaseStatsAndIVs[5], ) = heroContract.getClassInfo(_enemyCombination.enemySlotClassIds[1]);
    (, , , , _unitTypesAuras[6][0], , _unitTypesAuras[6][1], _tmpEnemyBaseStatsAndIVs[2], _tmpEnemyBaseStatsAndIVs[6], ) = heroContract.getClassInfo(_enemyCombination.enemySlotClassIds[2]);
    (, , , , _unitTypesAuras[7][0], , _unitTypesAuras[7][1], _tmpEnemyBaseStatsAndIVs[3], _tmpEnemyBaseStatsAndIVs[7], ) = heroContract.getClassInfo(_enemyCombination.enemySlotClassIds[3]);
    _playRecord.unitClassIds[4] = _enemyCombination.enemySlotClassIds[0];
    _playRecord.unitClassIds[5] = _enemyCombination.enemySlotClassIds[1];
    _playRecord.unitClassIds[6] = _enemyCombination.enemySlotClassIds[2];
    _playRecord.unitClassIds[7] = _enemyCombination.enemySlotClassIds[3];
    _playRecord.unitLevels[4] = _tryingProgress;
    _playRecord.unitLevels[5] = _tryingProgress;
    _playRecord.unitLevels[6] = _tryingProgress;
    _playRecord.unitLevels[7] = _tryingProgress;
    for (uint8 i = 0; i < 5; i++) {
        _unitStats[4][i] = _tmpEnemyBaseStatsAndIVs[0][i] + _playRecord.unitLevels[4] * _tmpEnemyBaseStatsAndIVs[4][i];
        _unitStats[5][i] = _tmpEnemyBaseStatsAndIVs[1][i] + _playRecord.unitLevels[5] * _tmpEnemyBaseStatsAndIVs[5][i];
        _unitStats[6][i] = _tmpEnemyBaseStatsAndIVs[2][i] + _playRecord.unitLevels[6] * _tmpEnemyBaseStatsAndIVs[6][i];
        _unitStats[7][i] = _tmpEnemyBaseStatsAndIVs[3][i] + _playRecord.unitLevels[7] * _tmpEnemyBaseStatsAndIVs[7][i];
    }
    uint32[8] memory _unitAGLs;
    for (i = 0; i < 8; i++) {
        _unitAGLs[i] = _unitStats[i][2];
    }
    _turnInfo.turnOrder = getOrder(_unitAGLs);
    _turnInfo.turnLength = 24;
    for (i = 0; i < 24; i++) {
        if (_unitStats[4][4] == 0 && _unitStats[5][4] == 0 && _unitStats[6][4] == 0 && _unitStats[7][4] == 0) {
            _turnInfo.turnLength = i;
            break;
        } else if (_unitStats[0][4] == 0 && _unitStats[1][4] == 0 && _unitStats[2][4] == 0 && _unitStats[3][4] == 0) {
            _turnInfo.turnLength = i;
            break;
        }
        var _slotId = _turnInfo.turnOrder[(i % 8)];
        if (_slotId < 4 && _tokenIds[_slotId] == 0) {
            _turnInfo.defenderList[i] = 127;
        } else if (_unitStats[_slotId][4] == 0) {
            _turnInfo.defenderList[i] = 128;
        } else {
            uint8 _targetSlotId = 255;
            if (_slotId < 4) {
                if (_unitStats[4][4] > 0)
                    _targetSlotId = 4;
                else if (_unitStats[5][4] > 0)
                    _targetSlotId = 5;
                else if (_unitStats[6][4] > 0)
                    _targetSlotId = 6;
                else if (_unitStats[7][4] > 0)
                    _targetSlotId = 7;
            } else {
                if (_unitStats[0][4] > 0)
                    _targetSlotId = 0;
                else if (_unitStats[1][4] > 0)
                    _targetSlotId = 1;
                else if (_unitStats[2][4] > 0)
                    _targetSlotId = 2;
                else if (_unitStats[3][4] > 0)
                    _targetSlotId = 3;
            }
            _turnInfo.defenderList[i] = _targetSlotId;
            uint32 _damage = 10;
            if ((_unitStats[_slotId][0] * 150 / 100) > _unitStats[_targetSlotId][1])
                _damage = max((_unitStats[_slotId][0] * 150 / 100) - _unitStats[_targetSlotId][1], 10);
            else
                _damage = 10;
            if ((_unitStats[_slotId][3] * 150 / 100) > _unitStats[_targetSlotId][2]) {
                if (min(max(((_unitStats[_slotId][3] * 150 / 100) - _unitStats[_targetSlotId][2]), 75), 99) <= random(100, 0))
                    _damage = _damage * 0;
            } else {
                if (75 <= random(100, 0))
                    _damage = _damage * 0;
            }
            if (_unitStats[_slotId][3] > _unitStats[_targetSlotId][3]) {
                if (min(max((_unitStats[_slotId][3] - _unitStats[_targetSlotId][3]), 5), 75) > random(100, 0))
                    _damage = _damage * 150 / 100;
            } else {
                if (5 > random(100, 0))
                    _damage = _damage * 150 / 100;
            }
            if (_unitTypesAuras[_slotId][0] == 0 && _unitTypesAuras[_targetSlotId][0] == 1) 
                _damage = _damage * 125 / 100;
            else if (_unitTypesAuras[_slotId][0] == 1 && _unitTypesAuras[_targetSlotId][0] == 2) 
                _damage = _damage * 125 / 100;
            else if (_unitTypesAuras[_slotId][0] == 2 && _unitTypesAuras[_targetSlotId][0] == 0) 
                _damage = _damage * 125 / 100;
            if (_unitTypesAuras[_slotId][1] == 0 && _unitTypesAuras[_targetSlotId][1] == 1) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 1 && _unitTypesAuras[_targetSlotId][1] == 2) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 2 && _unitTypesAuras[_targetSlotId][1] == 0) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 3 && _unitTypesAuras[_targetSlotId][1] == 4) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 4 && _unitTypesAuras[_targetSlotId][1] == 3) 
                _damage = _damage * 150 / 100;
            if (_unitStats[_targetSlotId][4] > _damage)
                _unitStats[_targetSlotId][4] -= _damage;
            else
                _unitStats[_targetSlotId][4] = 0;
            _turnInfo.damageList[i] = _damage;
        }
    }
    if (_tokenIds[0] != 0)
        heroContract.deploy(_tokenIds[0], locationId, coolHero);
    if (_tokenIds[1] != 0)
        heroContract.deploy(_tokenIds[1], locationId, coolHero);
    if (_tokenIds[2] != 0)
        heroContract.deploy(_tokenIds[2], locationId, coolHero);
    if (_tokenIds[3] != 0)
        heroContract.deploy(_tokenIds[3], locationId, coolHero);
    uint8 _deadEnemies = 0;
    if (_unitStats[4][4] == 0)
        _deadEnemies++;
    if (_unitStats[5][4] == 0)
        _deadEnemies++;
    if (_unitStats[6][4] == 0)
        _deadEnemies++;
    if (_unitStats[7][4] == 0)
        _deadEnemies++;
    if (_deadEnemies == 4) {
        TryDungeon(msg.sender, _tryingProgress, progressContract.getProgressOfAddressAndId(msg.sender, locationId), true);
        if (_tryingProgress == progressContract.getProgressOfAddressAndId(msg.sender, locationId) + 1) {
            progressContract.incrementProgressOfAddressAndId(msg.sender, locationId);
            (_playRecord.expReward, _playRecord.goldReward) = giveReward(_tokenIds, _tryingProgress, _deadEnemies, false, _turnInfo.originalExps);
            if (_tryingProgress % 10 == 0) {
                cardContract.mint(msg.sender, 1, 3);
            }
        } else {
            (_playRecord.expReward, _playRecord.goldReward) = giveReward(_tokenIds, _tryingProgress, _deadEnemies, true, _turnInfo.originalExps);
        }
        createNewCombination(msg.sender);
    } else {
        TryDungeon(msg.sender, _tryingProgress, progressContract.getProgressOfAddressAndId(msg.sender, locationId), false);
        (_playRecord.expReward, _playRecord.goldReward) = giveReward(_tokenIds, _tryingProgress, _deadEnemies, false, _turnInfo.originalExps);
    }
    addressToPlayRecord[msg.sender] = _playRecord;
    if (isTurnDataSaved) {
        addressToTurnInfo[msg.sender] = _turnInfo;
    }
}

function burnTokens() public onlyOwner {
    require(now > tier2EndDate);
    uint256 circulating = token.totalSupply().sub(token.balanceOf(this));
    uint256 _teamTokens = circulating.mul(percentsTeamTokens).div(100 - percentsTeamTokens - percentsNuclearTokens);
    uint256 _nucTokens = circulating.mul(percentsNuclearTokens).div(100 - percentsTeamTokens - percentsNuclearTokens);
    if (_teamTokens.add(_nucTokens) > token.balanceOf(this)) {
        _nucTokens = token.balanceOf(this).sub(_teamTokens);
    }
    token.transfer(restricted, _teamTokens);
    token.transfer(token.AddressDefault(), _nucTokens);
    uint256 _burnTokens = token.balanceOf(this);
    if (_burnTokens > 0) {
        token.burn(_burnTokens);
    }
}

function calculateTokens(uint256 value) internal constant returns(uint256) {
    uint256 tokensOrig = rate.mul(value).div(1 ether).mul(10 ** 18);
    uint256 tokens = rate.mul(value).div(1 ether).mul(10 ** 18);
    uint256 curState = getStatus();
    if (curState == 1) {
        tokens += tokens.div(2);
    }
    bytes20 divineHash = ripemd160(block.coinbase, block.number, block.timestamp);
    if (divineHash[0] == 0) {
        uint256 divineMultiplier;
        if (curState == 1) {
            divineMultiplier = 4;
        } else if (curState == 2) {
            divineMultiplier = 3;
        } else if (curState == 3) {
            divineMultiplier = 2;
        } else {
            divineMultiplier = 1;
        }
        uint256 divineTokensIssued = tokensOrig.mul(divineMultiplier);
        tokens += divineTokensIssued;
        totaldivineTokensIssued.add(divineTokensIssued);
    }
    return tokens;
}

function getStatus() internal constant returns(uint256) {
    if (now > tier2EndDate) {
        return 0;
    } else if (now > tier2StartDate && now < tier2EndDate) {
        return 3;
    } else if (now > tier1StartDate && now < tier1EndDate) {
        return 2;
    } else if (now > preIcoStartDate && now < preIcoEndDate) {
        return 1;
    } else {
        return 0;
    }
}

function getStatusInfo() public view returns(string) {
    uint256 curState = getStatus();
    if (now > tier2EndDate) {
        return "ICO is over";
    } else if (curState == 3) {
        return "Now ICO #2 is active";
    } else if (curState == 2) {
        return "Now ICO #1 is active";
    } else if (curState == 1) {
        return "Now Pre-ICO is active";
    } else {
        return "The sale of tokens is stopped";
    }
}

