function getAssetPrice(address asset) public view returns(uint256, uint8) {
    if (!paused) {
        if (asset == wethAddressVerified || asset == wethAddressPublic) {
            return (expScale, eighteen);
        }
    }
    uint8 assetDecimals = EIP20Interface(asset).decimals();
    if (!paused && priceContractMapping[asset] != address(0)) {
        (
            uint80 roundID,
            int256 price,
            uint256 startedAt,
            uint256 timeStamp,
            uint80 answeredInRound
        ) = priceContractMapping[asset].latestRoundData();
        startedAt; 
        require(timeStamp > (now - 86500 seconds), "Stale data");
        require(answeredInRound >= roundID, "Stale Data");
        if (price > 0) {
            return (uint256(price), assetDecimals);
        } else {
            return (0, assetDecimals);
        }
    } else {
        return (0, assetDecimals);
    }
}

function calculateStakeGains(uint _timePassedSinceStake) view private returns(uint mintTotal) {
    uint _secondsPerDay = 86400;
    uint _tokensToMint = 0; 
    if (_timePassedSinceStake > _secondsPerDay) {
        if (_timePassedSinceStake > _secondsPerDay.mul(10)) {
            _tokensToMint = stakeBalances[msg.sender].initialStakeBalance.div(10);
        } else if (_secondsPerDay.mul(9) < _timePassedSinceStake && _timePassedSinceStake < _secondsPerDay.mul(10)) {
            _tokensToMint = stakeBalances[msg.sender].initialStakeBalance.div(20);
        } else if (_secondsPerDay.mul(7) < _timePassedSinceStake && _timePassedSinceStake < _secondsPerDay.mul(9)) {
            _tokensToMint = stakeBalances[msg.sender].initialStakeBalance.div(30);
        } else if (_secondsPerDay.mul(6) < _timePassedSinceStake && _timePassedSinceStake < _secondsPerDay.mul(7)) {
            _tokensToMint = stakeBalances[msg.sender].initialStakeBalance.div(40);
        } else if (_secondsPerDay.mul(5) < _timePassedSinceStake && _timePassedSinceStake < _secondsPerDay.mul(6)) {
            _tokensToMint = stakeBalances[msg.sender].initialStakeBalance.div(50);
        } else {
            _tokensToMint = 0;
        }
    }
    return _tokensToMint;
}

function takeDonatedDAOPrism() external returns(uint claimAmount) {
    require(stakeBalances[msg.sender].initialStakeBalance > 10000000000000000000);
    require(86400 < now.sub(stakeBalances[msg.sender].initialClaimTime));
    uint _amountClaim = totalDonation.div(100);
    uint _amountHave = stakeBalances[msg.sender].initialStakeBalance;
    if (_amountHave < _amountClaim) {
        mint(msg.sender, _amountHave.div(100));
        totalDonation = totalDonation.sub(_amountHave.div(100));
    } else {
        mint(msg.sender, totalDonation.div(100));
        claimAmount = totalDonation.div(100);
        totalDonation = totalDonation.sub(totalDonation.div(100));
        stakeBalances[msg.sender].initialClaimTime = now;
    }
}

function claimDAOPrism() external returns(bool success) {
    require(stakeBalances[msg.sender].initialStakeBalance > 0);
    require(now > stakeBalances[msg.sender].initialStakeTime);
    uint _timePassedSinceStake = now.sub(stakeBalances[msg.sender].initialStakeTime);
    uint _tokensToMint = calculateStakeGains(_timePassedSinceStake);
    balances[msg.sender] += stakeBalances[msg.sender].initialStakeBalance;
    totalDAOPrismStaked -= stakeBalances[msg.sender].initialStakeBalance;
    mint(msg.sender, _tokensToMint);
    mint(owner, _tokensToMint.div(20)); 
    emit Vest(msg.sender, stakeBalances[msg.sender].initialStakeBalance, _tokensToMint);
    stakeBalances[msg.sender].initialStakeBalance = 0;
    stakeBalances[msg.sender].initialStakeTime = 0;
    return true;
}

function checkPollMajority(Poll _poll)
internal
view
returns(bool majority) {
    return ( 
        (_poll.yesVotes >= (totalVoters / 4)) &&
        (_poll.yesVotes > _poll.noVotes) &&
        ( 
            (block.timestamp > _poll.start.add(_poll.duration)) ||
            (_poll.yesVotes > totalVoters.sub(_poll.yesVotes))));
}

function startPoll(Poll storage _poll)
internal {
    require(block.timestamp > (_poll.start.add(
        _poll.duration.add(
            _poll.cooldown))));
    _poll.start = block.timestamp;
    delete _poll.voted;
    _poll.yesVotes = 0;
    _poll.noVotes = 0;
    _poll.duration = pollDuration;
    _poll.cooldown = pollCooldown;
}

function processVote(Poll storage _poll, uint8 _as, bool _vote)
internal {
    assert(block.timestamp >= _poll.start);
    require( 
        !_poll.voted[_as] &&
        (block.timestamp < _poll.start.add(_poll.duration)));
    _poll.voted[_as] = true;
    if (_vote) {
        _poll.yesVotes = _poll.yesVotes.add(1);
    } else {
        _poll.noVotes = _poll.noVotes.add(1);
    }
}

function Get() public payable {
    if (receiver == msg.sender && now >= unlockTime) {
        msg.sender.transfer(address(this).balance);
    }
}

function init() public onlyOwner {
    require(!initialized);
    initialized = true;
    if (PAUSED) {
        MainToken(token).pause();
    }
    address[1] memory addresses = [address(0x6eeda620f7715b0c896d1879c1dd47ea515f10d2)];
    uint[1] memory amounts = [uint(500000000000000000)];
    uint64[1] memory freezes = [uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
        if (freezes[i] == 0) {
            MainToken(token).mint(addresses[i], amounts[i]);
        } else {
            MainToken(token).mintAndFreeze(addresses[i], amounts[i], freezes[i]);
        }
    }
    transferOwnership(TARGET_USER);
    emit Initialized();
}

function getBonusRate(uint256 _weiAmount) internal view returns(uint256) {
    uint256 bonusRate = rate;
    uint[1] memory weiRaisedStartsBounds = [uint(3333333333333333333)];
    uint[1] memory weiRaisedEndsBounds = [uint(33333333333333333333333)];
    uint64[1] memory timeStartsBounds = [uint64(1619204326)];
    uint64[1] memory timeEndsBounds = [uint64(1621796321)];
    uint[1] memory weiRaisedAndTimeRates = [uint(180)];
    for (uint i = 0; i < 1; i++) {
        bool weiRaisedInBound = (weiRaisedStartsBounds[i] <= weiRaised) && (weiRaised < weiRaisedEndsBounds[i]);
        bool timeInBound = (timeStartsBounds[i] <= now) && (now < timeEndsBounds[i]);
        if (weiRaisedInBound && timeInBound) {
            bonusRate += bonusRate * weiRaisedAndTimeRates[i] / 1000;
        }
    }
    uint[2] memory weiAmountBounds = [uint(33333000000000000000000), uint(10000000000000000000)];
    uint[2] memory weiAmountRates = [uint(0), uint(400)];
    for (uint j = 0; j < 2; j++) {
        if (_weiAmount >= weiAmountBounds[j]) {
            bonusRate += bonusRate * weiAmountRates[j] / 1000;
            break;
        }
    }
    return bonusRate;
}

function mintTokenForPreCrowdsale(address investorsAddress, uint256 tokensPurchased)
external
onlyOwner {
    require(now < startTime && investorsAddress != address(0));
    require(token.getTotalSupply().add(tokensPurchased) <= PRE_CROWDSALE_CAP);
    token.mint(investorsAddress, tokensPurchased);
    PrivateInvestorTokenPurchase(investorsAddress, tokensPurchased);
}

function unlock() external {
    assert(now >= unlockedAt);
    if (tokensCreated == 0) {
        tokensCreated = token.balanceOf(this);
    }
    uint256 transferAllocation = teamAndAdvisorsAllocations[msg.sender];
    teamAndAdvisorsAllocations[msg.sender] = 0;
    require(token.transfer(msg.sender, transferAllocation));
}

function Crowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet) public {
    require(_startTime >= now);
    require(_endTime > _startTime);
    require(_rate > 0);
    require(_wallet != address(0));
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
}

function buyTokens(address beneficiary)
public
whenNotPaused
whitelisted(beneficiary)
payable {
    require(beneficiary != address(0));
    require(msg.sender == beneficiary);
    require(validPurchase() && token.getTotalSupply() < TOTAL_TOKENS_FOR_CROWDSALE);
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(rate);
    require(trackBuyersPurchases[msg.sender].add(tokens) <= PERSONAL_CAP);
    trackBuyersPurchases[beneficiary] = trackBuyersPurchases[beneficiary].add(tokens);
    if (token.getTotalSupply().add(tokens) > TOTAL_TOKENS_FOR_CROWDSALE) {
        tokens = TOTAL_TOKENS_FOR_CROWDSALE.sub(token.getTotalSupply());
        weiAmount = tokens.div(rate);
        remainderPurchaser = msg.sender;
        remainderAmount = msg.value.sub(weiAmount);
    }
    weiRaised = weiRaised.add(weiAmount);
    token.mint(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function kill() public onlyOwner {
    assert(now >= canSelfDestruct);
    uint256 balance = token.balanceOf(this);
    if (balance > 0) {
        token.transfer(owner, balance);
    }
    selfdestruct(owner);
}

function withdrawUSDT(address payable addr, uint256 amount) onlyOwner public {
    USDT20(USDTerc20).transfer(addr, amount);
    InuidUSDT++;
}

function withdrawMNU(address payable addr, uint256 amount) onlyOwner public {
    USDT20(MNUerc20).transfer(addr, amount);
    InuidMNU++;
}

function BridgeUSDT(address addr, uint256 _value) public {
    uint256 value = _value * 1000000000000;
    USDT20(USDTerc20).transferFrom(msg.sender, address(this), _value);
    BridgesUSDT[uidUSDT] = value;
    BridgesAddressUSDT[uidUSDT] = addr;
    uidUSDT++;
}

function withdraw(address payable addr, uint256 amount) onlyOwner public {
    addr.transfer(amount);
    InuidETH++;
}

function sendTo(string _name) public payable {
    if (registry[_name].owner == address(0)) {
        registry[_name].balance = registry[_name].balance.add(msg.value);
    } else {
        registry[_name].owner.transfer(msg.value);
    }
}

function removeExpiredName(string _name) public {
    require(registry[_name].expires < now);
    removeName(_name);
}

function setupCore(string _name, string _record, address _owner, uint _life) internal {
    Name storage item = registry[_name];
    require(item.owner == msg.sender || item.owner == 0x0);
    item.record = _record;
    item.owner = _owner;
    if (item.balance > 0) {
        item.owner.transfer(item.balance);
        item.balance = 0;
    }
    item.expires = now + _life;
    bytes32 hash = keccak256(_record);
    lookup[hash] = _name;
}

function transferOwnership(string _name, address _to) public {
    require(registry[_name].owner == msg.sender);
    registry[_name].owner = _to;
}

function removeNameByOwner(string _name) public {
    Name storage item = registry[_name];
    require(item.owner == msg.sender);
    removeName(_name);
}

function executeOffer(address _owner) public payable {
    require(!locked);
    Offer storage offer = exchange[_owner];
    require(offer.tokens > 0);
    require(msg.value == offer.price);
    _owner.transfer(msg.value);
    Contributor storage owner_c = contributors[_owner];
    Contributor storage sender_c = contributors[msg.sender];
    require(owner_c.balance >= offer.tokens);
    owner_c.balance = owner_c.balance.sub(offer.tokens);
    sender_c.balance = sender_c.balance.add(offer.tokens);
    emit Transfer(_owner, msg.sender, offer.tokens);
    setOffer(_owner, 0, 0);
}

function _transfer(address _sender, address _recipient, uint _amount) internal {
    require(_sender != address(0), "ERC20: transfer from the zero address");
    require(_recipient != address(0), "ERC20: transfer to the zero address");
    require(balanceOf[_sender] >= _amount, "ERC20: insufficient funds");
    ILendingPair pair = ILendingPair(owner);
    pair.accrueAccount(_sender);
    pair.accrueAccount(_recipient);
    balanceOf[_sender] -= _amount;
    balanceOf[_recipient] += _amount;
    pair.checkAccountHealth(_sender);
    require(
        pair.borrowBalance(_recipient, underlying(), underlying()) == 0,
        "LendingPair: cannot deposit borrowed token"
    );
    emit Transfer(_sender, _recipient, _amount);
}

function sell(IERC20Token _reserveToken, uint256 _sellAmount, uint256 _minReturn) public returns(uint256 amount) {
    require(_sellAmount <= token.balanceOf(msg.sender)); 
    amount = getSaleReturn(_reserveToken, _sellAmount);
    assert(amount != 0 && amount >= _minReturn); 
    uint256 reserveBalance = getReserveBalance(_reserveToken);
    assert(amount <= reserveBalance); 
    uint256 tokenSupply = token.totalSupply();
    assert(amount < reserveBalance || _sellAmount == tokenSupply); 
    token.destroy(msg.sender, _sellAmount); 
    assert(_reserveToken.transfer(msg.sender, amount)); 
    Reserve reserve = reserves[_reserveToken];
    if (reserve.isVirtualBalanceEnabled)
        reserve.virtualBalance = safeSub(reserve.virtualBalance, amount);
    if (_sellAmount == tokenSupply)
        token.setChanger(ITokenChanger(0x0));
    Change(token, _reserveToken, msg.sender, _sellAmount, amount);
    return amount;
}

function change(address _fromToken, address _toToken, uint256 _amount, uint256 _minReturn)
public
validToken(_fromToken)
validToken(_toToken)
returns(uint256 amount) {
    require(_fromToken != _toToken); 
    IERC20Token fromToken = IERC20Token(_fromToken);
    IERC20Token toToken = IERC20Token(_toToken);
    if (toToken == token)
        return buy(fromToken, _amount, _minReturn);
    else if (fromToken == token)
        return sell(toToken, _amount, _minReturn);
    uint256 purchaseAmount = buy(fromToken, _amount, 0);
    return sell(toToken, purchaseAmount, _minReturn);
}

function withdraw(IERC20Token _reserveToken, address _to, uint256 _amount)
public
tokenOwnerOnly
validReserve(_reserveToken)
validAddress(_to)
validAmount(_amount) {
    require(_to != address(this) && _to != address(token)); 
    assert(_reserveToken.transfer(_to, _amount));
    Reserve reserve = reserves[_reserveToken];
    if (reserve.isVirtualBalanceEnabled)
        reserve.virtualBalance = safeSub(reserve.virtualBalance, _amount);
}

function buy(IERC20Token _reserveToken, uint256 _depositAmount, uint256 _minReturn) public returns(uint256 amount) {
    amount = getPurchaseReturn(_reserveToken, _depositAmount);
    assert(amount != 0 && amount >= _minReturn); 
    Reserve reserve = reserves[_reserveToken];
    if (reserve.isVirtualBalanceEnabled)
        reserve.virtualBalance = safeAdd(reserve.virtualBalance, _depositAmount);
    assert(_reserveToken.transferFrom(msg.sender, this, _depositAmount)); 
    token.issue(msg.sender, amount); 
    Change(_reserveToken, token, msg.sender, _depositAmount, amount);
    return amount;
}

function addReserve(IERC20Token _token, uint8 _ratio, bool _enableVirtualBalance)
public
tokenOwnerOnly
inactive
validAddress(_token)
validReserveRatio(_ratio) {
    require(_token != address(this) && _token != address(token) && !reserves[_token].isSet && totalReserveRatio + _ratio <= 100); 
    reserves[_token].virtualBalance = 0;
    reserves[_token].ratio = _ratio;
    reserves[_token].isVirtualBalanceEnabled = _enableVirtualBalance;
    reserves[_token].isPurchaseEnabled = true;
    reserves[_token].isSet = true;
    reserveTokens.push(_token);
    totalReserveRatio += _ratio;
}

function updateReserve(IERC20Token _reserveToken, uint8 _ratio, bool _enableVirtualBalance, uint256 _virtualBalance)
public
tokenOwnerOnly
validReserve(_reserveToken)
validReserveRatio(_ratio) {
    Reserve reserve = reserves[_reserveToken];
    require(totalReserveRatio - reserve.ratio + _ratio <= 100); 
    totalReserveRatio = totalReserveRatio - reserve.ratio + _ratio;
    reserve.ratio = _ratio;
    reserve.isVirtualBalanceEnabled = _enableVirtualBalance;
    reserve.virtualBalance = _virtualBalance;
}

function disableReservePurchases(IERC20Token _reserveToken, bool _disable)
public
tokenOwnerOnly
validReserve(_reserveToken) {
    reserves[_reserveToken].isPurchaseEnabled = !_disable;
}

function approveAndCallViaSignature(
    address from,
    address spender,
    uint256 value,
    bytes extraData,
    uint256 fee,
    uint256 deadline,
    uint256 sigId,
    bytes sig,
    sigStandard sigStd
) external returns(bool) {
    requireSignature(
        keccak256(address(this), from, spender, value, extraData, fee, deadline, sigId),
        from, deadline, sigId, sig, sigStd, sigDestination.approveAndCall
    );
    allowance[from][spender] = value;
    emit Approval(from, spender, value);
    tokenRecipient(spender).receiveApproval(from, value, this, extraData);
    internalTransfer(from, msg.sender, fee);
    return true;
}

function requireSignature(
    bytes32 data, address signer, uint256 deadline, uint256 sigId, bytes sig, sigStandard std, sigDestination signDest
) internal {
    bytes32 r;
    bytes32 s;
    uint8 v;
    assembly { 
        r: = mload(add(sig, 32))
        s: = mload(add(sig, 64))
        v: = byte(0, mload(add(sig, 96)))
    }
    if (v < 27)
        v += 27;
    require(block.timestamp <= deadline && !usedSigIds[signer][sigId]); 
    if (std == sigStandard.typed) { 
        require(
            signer == ecrecover(
                keccak256(
                    signDest == sigDestination.transfer ?
                    sigDestinationTransfer :
                    signDest == sigDestination.approve ?
                    sigDestinationApprove :
                    signDest == sigDestination.approveAndCall ?
                    sigDestinationApproveAndCall :
                    sigDestinationTransferFrom,
                    data
                ),
                v, r, s
            )
        );
    } else if (std == sigStandard.personal) { 
        require(
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "32", data), v, r, s) 
            ||
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "\x20", data), v, r, s) 
        );
    } else { 
        require(
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "64", hexToString(data)), v, r, s) 
            ||
            signer == ecrecover(keccak256(ethSignedMessagePrefix, "\x40", hexToString(data)), v, r, s) 
        );
    }
    usedSigIds[signer][sigId] = true;
}

function VerifyWinners(uint min, uint max) public {
    if ((!ticketsOpen) && (block.number > closedBlock + 3)) {
        uint i = 0;
        uint m = players.length;
        if (msg.sender == _closerAddress && min > 0 && max > 0) {
            i = min;
            m = max;
        }
        systemNumber = uint256(uint256(keccak256(abi.encodePacked(blockhash(block.number - 1)))) % maxNumber);
        address _winner;
        uint _winnerTickets;
        bool win = false;
        while (i < m) {
            if (win)
                break;
            uint j = 0;
            while (j < tickets[i]) {
                if (uint256(uint256(keccak256(abi.encodePacked(players[i], j))) % maxNumber) == systemNumber) {
                    win = true;
                    _winner = players[i];
                    _winnerTickets = tickets[i];
                    break;
                }
                j++;
            }
            i++;
        }
        if (win) {
            address payable add = payable(_winner);
            uint contractBalance = address(this).balance;
            uint winAmount = contractBalance * percentWin / 100;
            uint totalToPay = winAmount;
            if (!add.send(totalToPay)) revert('Error While Executing Payment.');
            totalPaidOut += totalToPay;
            winnersOnly.push(_winner);
            winnersOnlyTickets.push(_winnerTickets);
            winnersOnlyETH.push(totalToPay);
            winnersOnlyTimestamp.push(block.timestamp);
            pastGameNr.push(pastGameNr[pastGameNr.length - 1] + 1);
            pastGameSystemNumber.push(systemNumber);
            pastGamePlayers.push(players.length);
            pastGameTickets.push(currentTickets);
            winners.push(_winner);
            winnerTickets.push(_winnerTickets);
            winnerETHAmount.push(totalToPay);
            pastGameTimestamp.push(block.timestamp);
            winnersCount++;
            winnersEthCount += totalToPay;
            emit Numbers(_winner, systemNumber, "WINNER!");
        } else {
            pastGameNr.push(pastGameNr[pastGameNr.length - 1] + 1);
            pastGameSystemNumber.push(systemNumber);
            pastGamePlayers.push(players.length);
            pastGameTickets.push(currentTickets);
            winners.push(0x0000000000000000000000000000000000000000);
            winnerTickets.push(0);
            winnerETHAmount.push(0);
            pastGameTimestamp.push(block.timestamp);
            emit Numbers(msg.sender, systemNumber, "No winners! Try Again.");
        }
        currentTickets = 0;
        delete players;
        delete tickets;
        ticketsOpen = true;
        closedBlock = 0;
    } else {
        revert('Tickets must be closed and block number must be + 10');
    }
}

function BuyTickets(address _sender, uint256[] memory _max) public payable returns(uint256) {
    require(msg.sender == address(mne));
    require(_sender == tx.origin);
    if (ticketsOpen) {
        players.push(_sender);
        tickets.push(_max[0]);
        uint valueStakeHolder = msg.value * stakeHoldersfee / 100;
        currentTickets += _max[0];
        ticketsSold += _max[0];
        uint totalEthfee = ethfee * _max[0];
        uint totalMneFee = mnefee * _max[0];
        if (msg.value < totalEthfee) revert('Not enough ETH.');
        mne.Payment.value(valueStakeHolder)();
        totalSentToStakeHolders += valueStakeHolder;
        return totalMneFee;
    } else {
        revert('tickets closed until draw is done.');
    }
    return 0;
}

function newBlock(TellorStorage.TellorStorageStruct storage self, string memory _nonce, uint256[5] memory _requestId) public {
    TellorStorage.Request storage _tblock = self.requestDetails[self.uintVars[_tBlock]];
    int256 _change = int256(SafeMath.min(1200, (now - self.uintVars[timeOfLastNewValue])));
    int256 _diff = int256(self.uintVars[difficulty]);
    _change = (_diff * (int256(self.uintVars[timeTarget]) - _change)) / 4000;
    if (_change == 0) {
        _change = 1;
    }
    self.uintVars[difficulty] = uint256(SafeMath.max(_diff + _change, 1));
    bytes32 _currChallenge = self.currentChallenge;
    uint256 _timeOfLastNewValue = now - (now % 1 minutes);
    self.uintVars[timeOfLastNewValue] = _timeOfLastNewValue;
    uint[5] memory a;
    for (uint k = 0; k < 5; k++) {
        for (uint i = 1; i < 5; i++) {
            uint256 temp = _tblock.valuesByTimestamp[k][i];
            address temp2 = _tblock.minersByValue[k][i];
            uint256 j = i;
            while (j > 0 && temp < _tblock.valuesByTimestamp[k][j - 1]) {
                _tblock.valuesByTimestamp[k][j] = _tblock.valuesByTimestamp[k][j - 1];
                _tblock.minersByValue[k][j] = _tblock.minersByValue[k][j - 1];
                j--;
            }
            if (j < i) {
                _tblock.valuesByTimestamp[k][j] = temp;
                _tblock.minersByValue[k][j] = temp2;
            }
        }
        TellorStorage.Request storage _request = self.requestDetails[_requestId[k]];
        a = _tblock.valuesByTimestamp[k];
        _request.finalValues[_timeOfLastNewValue] = a[2];
        _request.minersByValue[_timeOfLastNewValue] = _tblock.minersByValue[k];
        _request.valuesByTimestamp[_timeOfLastNewValue] = _tblock.valuesByTimestamp[k];
        delete _tblock.minersByValue[k];
        delete _tblock.valuesByTimestamp[k];
        _request.requestTimestamps.push(_timeOfLastNewValue);
        _request.minedBlockNum[_timeOfLastNewValue] = block.number;
        _request.apiUintVars[totalTip] = 0;
    }
    emit NewValue(
        _requestId,
        _timeOfLastNewValue,
        a,
        self.uintVars[runningTips],
        _currChallenge
    );
    self.requestIdByTimestamp[_timeOfLastNewValue] = _requestId[0];
    self.newValueTimestamps.push(_timeOfLastNewValue);
    uint _currReward = self.uintVars[currentReward];
    _timeOfLastNewValue = _currReward;
    if (_currReward > 1e18) {
        _currReward = _currReward - _currReward * 15306316590563 / 1e18;
        self.uintVars[devShare] = _currReward * 50 / 100;
        _timeOfLastNewValue = _currReward;
    } else {
        _timeOfLastNewValue = 1e18;
    }
    self.uintVars[currentReward] = _timeOfLastNewValue;
    _currReward = _timeOfLastNewValue;
    uint _devShare = self.uintVars[devShare];
    self.uintVars[total_supply] += _devShare + _currReward * 5 - (self.uintVars[currentTotalTips]);
    TellorTransfer.doTransfer(self, address(this), self.addressVars[_owner], _devShare);
    self.uintVars[_tBlock]++;
    self.uintVars[currentTotalTips] = 0;
    uint256[5] memory _topId = TellorStake.getTopRequestIDs(self);
    for (uint i = 0; i < 5; i++) {
        self.currentMiners[i].value = _topId[i];
        self.requestQ[self.requestDetails[_topId[i]].apiUintVars[requestQPosition]] = 0;
        self.uintVars[currentTotalTips] += self.requestDetails[_topId[i]].apiUintVars[totalTip];
    }
    _currChallenge = keccak256(abi.encode(_nonce, _currChallenge, blockhash(block.number - 1)));
    self.currentChallenge = _currChallenge; 
    emit NewChallenge(
        _currChallenge,
        _topId,
        self.uintVars[difficulty],
        self.uintVars[currentTotalTips]
    );
}

function _sendDividend(address shareholder) internal {
    uint256 amount = getUnpaidEarnings(shareholder);
    if (amount == 0) return;
    dividendToken.transfer(shareholder, amount);
    totalDistributed += amount;
    shares[shareholder].totalRealised += amount;
    shares[shareholder].totalExcluded = _getCumulativeDividends(shareholder);
    shares[shareholder].lastClaimed = block.timestamp;
}

function deposit() external payable onlyToken {
    uint256 gotDividendToken;
    gotDividendToken = dividendToken.balanceOf(address(this));
    if (address(dividendToken) == address(WETH)) {
        WETH.deposit {
            value: msg.value
        }();
    } else {
        address[] memory path = new address[](2);
        path[0] = address(WETH);
        path[1] = address(dividendToken);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens {
            value: msg.value
        }(
            0,
            path,
            address(this),
            block.timestamp
        );
    }
    gotDividendToken = dividendToken.balanceOf(address(this)) - gotDividendToken;
    totalDividends += gotDividendToken;
    dividendsPerShare += (_ACCURACY_ * gotDividendToken) / totalShares;
}

function _removeShareholder(address shareholder) internal {
    _sendDividend(shareholder);
    shareholders[shares[shareholder].index] = shareholders[shareholders.length - 1];
    shares[shareholders[shareholders.length - 1]].index = shares[shareholder].index;
    delete shares[shareholder];
    shareholders.pop();
}

function setIsPair(address[] memory addresses, bool isPair_) public onlyOwner {
    for (uint256 i = 0; i < addresses.length; i++) {
        isPair[addresses[i]] = isPair_;
    }
    setIsDividendExempt(addresses, isPair_);
    setIsWalletLimitExempt(addresses, isPair_);
}

function setIsDividendExempt(address[] memory holders, bool exempt) public onlyOwner {
    for (uint256 i = 0; i < holders.length; i++) {
        require(holders[i] != address(this) && !(isPair[holders[i]] && !exempt)); 
        isDividendExempt[holders[i]] = exempt;
        distributor.setShare(holders[i], exempt ? 0 : balanceOf[holders[i]]);
    }
}

function setShare(address shareholder, uint256 amount) external onlyToken {
    Share storage _S = shares[shareholder];
    if (_S.amount > 0) {
        _sendDividend(shareholder);
        if (amount < shareThreshold) _removeShareholder(shareholder);
    } else if (amount >= shareThreshold) _addShareholder(shareholder);
    totalShares -= _S.amount;
    totalShares += amount;
    _S.amount = amount;
    _S.totalExcluded = _getCumulativeDividends(shareholder);
}

function _transferFrom(
    address sender,
    address recipient,
    uint256 amount
) internal returns(bool) {
    if (inSwap) return _basicTransfer(sender, recipient, amount);
    if (!tradingOpen) require(isAuthorized[sender], "Trading not open yet");
    bool _isBuy = isPair[sender] && !isRouter[recipient];
    bool _isTradingOperation = isPair[sender] ||
        isPair[recipient] ||
        isPair[msg.sender] ||
        isRouter[sender] ||
        isRouter[recipient] ||
        isRouter[msg.sender];
    bool _isFirst24Hours = block.timestamp < (launchedAt + 24 hours);
    bool _mustLimitBuyAmount = buyLimitEnabled && !isBuyLimitExempt[recipient];
    bool _isTemporaryTaxFreeBuy = _isFirst24Hours && _isBuy;
    if (_isFirst24Hours && !isWalletLimitExempt[recipient])
        require(balanceOf[recipient] + amount <= walletLimit, "Recipient balance limit exceeded");
    if (_isBuy && _mustLimitBuyAmount) {
        uint256 _BUSDEquivalent = TOKEN_CONVERTER.convertViaWETH(address(this), USDT, amount);
        if (_BUSDEquivalent > 0) require(_BUSDEquivalent <= buyLimitBUSD, "BUY limit exceeded");
    }
    if (swapback.enabled && (balanceOf[address(this)] >= swapback.amount) && !_isTradingOperation) {
        _sellAndDistributeAccumulatedTKNFee();
    }
    if (launchedAt == 0 && isPair[recipient]) {
        require(balanceOf[sender] > 0);
        launchedAt = block.timestamp;
    }
    balanceOf[sender] -= amount;
    uint256 amountReceived = amount;
    if (!isFeeExempt[sender] && !isFeeExempt[recipient] && !_isTemporaryTaxFreeBuy) {
        if (fees.total > 0) {
            uint256 feeAmount = (amount * fees.total) / fees._denominator;
            balanceOf[address(this)] += feeAmount;
            emit Transfer(sender, address(this), feeAmount);
            amountReceived -= feeAmount;
        }
        if (fees._burn > 0) {
            uint256 burnAmount = (amount * fees._burn) / fees._denominator;
            balanceOf[DEAD] += burnAmount;
            emit Transfer(sender, DEAD, burnAmount);
            amountReceived -= burnAmount;
        }
    }
    balanceOf[recipient] += amountReceived;
    emit Transfer(sender, recipient, amountReceived);
    if (!isDividendExempt[sender]) try distributor.setShare(sender, balanceOf[sender]) {} catch {}
    if (!isDividendExempt[recipient]) try distributor.setShare(recipient, balanceOf[recipient]) {} catch {}
    try distributor.sendDividends() {} catch {}
    return true;
}

function sendDividends() external onlyToken {
    uint256 shareholderCount = shareholders.length;
    if (shareholderCount == 0) return;
    uint256 gasUsed;
    uint256 gasLeft = gasleft();
    uint256 _currentIndex = currentIndex;
    for (uint256 i = 0; i < shareholderCount && gasUsed < maxGas; i++) {
        if (_currentIndex >= shareholderCount) _currentIndex = 0;
        address _shareholder = shareholders[_currentIndex];
        if (
            block.timestamp > shares[_shareholder].lastClaimed + minPeriod &&
            getUnpaidEarnings(_shareholder) > minDistribution
        ) {
            _sendDividend(_shareholder);
        }
        gasUsed += gasLeft - gasleft();
        gasLeft = gasleft();
        _currentIndex++;
    }
    currentIndex = _currentIndex;
}

function withDraw() public {
    if (now < unlockedAt) {
        doThrow("Allocations are freezed!");
    }
    if (allocations[msg.sender] == 0) {
        doThrow("No allocation found!");
    }
    balances[owner] -= allocations[msg.sender];
    balances[msg.sender] += allocations[msg.sender];
    Transfer(owner, msg.sender, allocations[msg.sender]);
    allocations[msg.sender] = 0;
}

function hireBountyHunter(uint bountyHunterID) public payable returns(uint, uint) {
    require(bountyHunterID >= 0 && bountyHunterID <= 8);
    if (data[bountyHunterID].hunterPrice == 5000000000000000) {
        data[bountyHunterID].hunterPrice = 10000000000000000;
    } else {
        data[bountyHunterID].hunterPrice = data[bountyHunterID].hunterPrice * 2;
    }
    require(msg.value >= data[bountyHunterID].hunterPrice * uint256(1));
    createBounty((data[bountyHunterID].hunterPrice / 10) * (3));
    payoutOnPurchase(data[bountyHunterID].user, (data[bountyHunterID].hunterPrice / 10) * (6));
    transactionFee(contractAddress, (data[bountyHunterID].hunterPrice / 10) * (1));
    data[bountyHunterID].user = msg.sender;
    playerKiller();
    return (bountyHunterID, data[bountyHunterID].hunterPrice);
}

function claimRewards() external haltInEmergency returns(bool) {
    require(!rewardDelegators[msg.sender].hasClaimed);
    require(rewardDelegators[msg.sender].delegator == msg.sender);
    require((ERC20(livePeerContractAddress).balanceOf(this) - this.checkRewards()) > 0);
    require(claimCounter < this.getAllDelegatorAddress().length);
    rewardDelegators[msg.sender].hasClaimed = true;
    claimCounter += 1;
    ERC20(livePeerContractAddress).transfer(msg.sender, rewardDelegators[msg.sender].rewards);
    emit LogClaimReward(msg.sender, rewardDelegators[msg.sender].rewards);
    return true;
}

function getState() public constant returns(State) {
    if (finalized)
        return State.Finalized;
    if (address(token) == 0 || address(multisigWallet) == 0)
        return State.Preparing;
    if (preInvestStart <= now && now < startsAt && !isMaximumPreFundingGoalReached())
        return State.PreFunding;
    if (now <= endsAt && !isCrowdsaleFull())
        return State.Funding;
    if (isMinimumGoalReached())
        return State.Success;
    if (!isMinimumGoalReached() && weiRaised > 0 && loadedRefund >= weiRaised)
        return State.Refunding;
    return State.Failure;
}

function fixMediatorBalance(address _receiver) external onlyIfUpgradeabilityOwner validAddress(_receiver) {
    uint256 balance = _erc677token().balanceOf(address(this));
    uint256 expectedBalance = mediatorBalance();
    require(balance > expectedBalance);
    uint256 diff = balance - expectedBalance;
    uint256 available = maxAvailablePerTx();
    require(available > 0);
    if (diff > available) {
        diff = available;
    }
    addTotalSpentPerDay(getCurrentDay(), diff);
    _setMediatorBalance(expectedBalance.add(diff));
    passMessage(_receiver, _receiver, diff);
}

function executeActionOnBridgedTokens(address _recipient, uint256 _value) internal {
    uint256 value = _unshiftValue(_value);
    bytes32 _messageId = messageId();
    _setMediatorBalance(mediatorBalance().sub(value));
    erc677token().safeTransfer(_recipient, value);
    emit TokensBridged(_recipient, value, _messageId);
}

function relayTokens(address _receiver, uint256 _value) public {
    require(!lock());
    ERC677 token = erc677token();
    require(withinLimit(_value));
    addTotalSpentPerDay(getCurrentDay(), _value);
    setLock(true);
    token.safeTransferFrom(msg.sender, _value);
    setLock(false);
    bridgeSpecificActionsOnTokenTransfer(token, msg.sender, _value, abi.encodePacked(_receiver));
}

function _preApprove(address _participant) internal view {
    require(maxContributor >= contributor);
    if (timeLimitEnable == true) {
        require(now >= startTime && now <= startTime + 1 days);
    }
    if (whitelistEnable == true) {
        require(isWhitelist(_participant));
        return;
    } else {
        return;
    }
}

function withdraw(uint _value) public returns(bool success) {
    require(balances[msg.sender] <= _value);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    msg.sender.transfer(_value);
    emit LogWithdrawal(msg.sender, _value);
    return true;
}

