    if (_enemyPlayRecord.tokenIds[3] != 0) {
        _playRecord.unitClassIds[7] = heroContract.getHeroClassId(_enemyPlayRecord.tokenIds[3]);
        (_playRecord.unitLevels[7], , _unitStats[7], , ) = correctedHeroContract.getCorrectedStats(_enemyPlayRecord.tokenIds[3]);
        (, , , , _unitTypesAuras[7][0], , _unitTypesAuras[7][1], , , ) = heroContract.getClassInfo(_playRecord.unitClassIds[7]);
    }
    _playRecord.tokenIds[4] = _enemyPlayRecord.tokenIds[0];
    _playRecord.tokenIds[5] = _enemyPlayRecord.tokenIds[1];
    _playRecord.tokenIds[6] = _enemyPlayRecord.tokenIds[2];
    _playRecord.tokenIds[7] = _enemyPlayRecord.tokenIds[3];
    uint32[8] memory _unitAGLs;
    for (uint8 i = 0; i < 8; i++) {
        _unitAGLs[i] = _unitStats[i][2];
    }
    _turnInfo.turnOrder = getOrder(_unitAGLs);
    _turnInfo.turnLength = 24;
    for (i = 0; i < 24; i++) {
        if (_unitStats[4][4] == 0 && _unitStats[5][4] == 0 && _unitStats[6][4] == 0 && _unitStats[7][4] == 0) {
            _turnInfo.turnLength = i;
            break;
        } else if (_unitStats[0][4] == 0 && _unitStats[1][4] == 0 && _unitStats[2][4] == 0 && _unitStats[3][4] == 0) {
            _turnInfo.turnLength = i;
            break;
        }
        var _slotId = _turnInfo.turnOrder[(i % 8)];
        if (_slotId < 4 && _tokenIds[_slotId] == 0) {
            _turnInfo.defenderList[i] = 127;
        } else if (_unitStats[_slotId][4] == 0) {
            _turnInfo.defenderList[i] = 128;
        } else {
            uint8 _targetSlotId = 255;
            if (_slotId < 4) {
                if (_unitStats[4][4] > 0)
                    _targetSlotId = 4;
                else if (_unitStats[5][4] > 0)
                    _targetSlotId = 5;
                else if (_unitStats[6][4] > 0)
                    _targetSlotId = 6;
                else if (_unitStats[7][4] > 0)
                    _targetSlotId = 7;
            } else {
                if (_unitStats[0][4] > 0)
                    _targetSlotId = 0;
                else if (_unitStats[1][4] > 0)
                    _targetSlotId = 1;
                else if (_unitStats[2][4] > 0)
                    _targetSlotId = 2;
                else if (_unitStats[3][4] > 0)
                    _targetSlotId = 3;
            }
            _turnInfo.defenderList[i] = _targetSlotId;
            uint32 _damage = 10;
            if ((_unitStats[_slotId][0] * 150 / 100) > _unitStats[_targetSlotId][1])
                _damage = max((_unitStats[_slotId][0] * 150 / 100) - _unitStats[_targetSlotId][1], 10);
            else
                _damage = 10;
            if ((_unitStats[_slotId][3] * 150 / 100) > _unitStats[_targetSlotId][2]) {
                if (min(max(((_unitStats[_slotId][3] * 150 / 100) - _unitStats[_targetSlotId][2]), 75), 99) <= random(100, 0))
                    _damage = _damage * 0;
            } else {
                if (75 <= random(100, 0))
                    _damage = _damage * 0;
            }
            if (_unitStats[_slotId][3] > _unitStats[_targetSlotId][3]) {
                if (min(max((_unitStats[_slotId][3] - _unitStats[_targetSlotId][3]), 5), 75) > random(100, 0))
                    _damage = _damage * 150 / 100;
            } else {
                if (5 > random(100, 0))
                    _damage = _damage * 150 / 100;
            }
            if (_unitTypesAuras[_slotId][0] == 0 && _unitTypesAuras[_targetSlotId][0] == 1) 
                _damage = _damage * 125 / 100;
            else if (_unitTypesAuras[_slotId][0] == 1 && _unitTypesAuras[_targetSlotId][0] == 2) 
                _damage = _damage * 125 / 100;
            else if (_unitTypesAuras[_slotId][0] == 2 && _unitTypesAuras[_targetSlotId][0] == 0) 
                _damage = _damage * 125 / 100;
            if (_unitTypesAuras[_slotId][1] == 0 && _unitTypesAuras[_targetSlotId][1] == 1) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 1 && _unitTypesAuras[_targetSlotId][1] == 2) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 2 && _unitTypesAuras[_targetSlotId][1] == 0) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 3 && _unitTypesAuras[_targetSlotId][1] == 4) 
                _damage = _damage * 150 / 100;
            else if (_unitTypesAuras[_slotId][1] == 4 && _unitTypesAuras[_targetSlotId][1] == 3) 
                _damage = _damage * 150 / 100;
            if (_unitStats[_targetSlotId][4] > _damage)
                _unitStats[_targetSlotId][4] -= _damage;
            else
                _unitStats[_targetSlotId][4] = 0;
            _turnInfo.damageList[i] = _damage;
        }
    }
    if (_tokenIds[0] != 0)
        heroContract.deploy(_tokenIds[0], locationId, coolHero);
    if (_tokenIds[1] != 0)
        heroContract.deploy(_tokenIds[1], locationId, coolHero);
    if (_tokenIds[2] != 0)
        heroContract.deploy(_tokenIds[2], locationId, coolHero);
    if (_tokenIds[3] != 0)
        heroContract.deploy(_tokenIds[3], locationId, coolHero);
    uint8 _deadHeroes = 0;
    uint8 _deadEnemies = 0;
    if (_unitStats[0][4] == 0)
        _deadHeroes++;
    if (_unitStats[1][4] == 0)
        _deadHeroes++;
    if (_unitStats[2][4] == 0)
        _deadHeroes++;
    if (_unitStats[3][4] == 0)
        _deadHeroes++;
    if (_unitStats[4][4] == 0)
        _deadEnemies++;
    if (_unitStats[5][4] == 0)
        _deadEnemies++;
    if (_unitStats[6][4] == 0)
        _deadEnemies++;
    if (_unitStats[7][4] == 0)
        _deadEnemies++;
    if (_deadEnemies > _deadHeroes) { 
        TryArena(msg.sender, _enemyAddress, true);
        (_playRecord.expReward, _playRecord.goldReward) = giveReward(_tokenIds, true, _turnInfo.originalExps);
        recordContract.updateRecord(msg.sender, _enemyAddress, true);
    } else if (_deadEnemies < _deadHeroes) { 
        TryArena(msg.sender, _enemyAddress, false);
        (_playRecord.expReward, _playRecord.goldReward) = giveReward(_tokenIds, false, _turnInfo.originalExps);
        recordContract.updateRecord(msg.sender, _enemyAddress, false);
    } else { 
        TryArena(msg.sender, _enemyAddress, false);
        (_playRecord.expReward, _playRecord.goldReward) = giveReward(_tokenIds, false, _turnInfo.originalExps);
    }
    addressToPlayRecord[msg.sender] = _playRecord;
    if (isTurnDataSaved) {
        addressToTurnInfo[msg.sender] = _turnInfo;
    }
}

function TransferToGsContractFromOwnerAccount(address payable receiver, uint amount) public {
    require(msg.sender == owner, "You're not owner of the account"); 
    require(amount < address(this).balance, "Insufficient balance.");
    receiver.transfer(amount);
    emit GdpSentFromAccount(msg.sender, receiver, amount);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "BEP20: transfer from the zero address");
    require(recipient != address(0), "BEP20: transfer to the zero address");
    if ((sender == PancakeSwapV2Pair || recipient == PancakeSwapV2Pair) && !isExcludeFromFee[sender])
        require(_maxTxAmount >= amount, "BEP20: transfer amount exceeds max transfer amount");
    _balances[sender] = _balances[sender].sub(amount, "BEP20: transfer amount exceeds balance");
    uint recieveAmount = amount;
    uint256 contractTokenBalance = balanceOf(address(this));
    if (contractTokenBalance >= _maxTxAmount) {
        contractTokenBalance = _maxTxAmount;
    }
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (
        overMinTokenBalance &&
        !inSwapAndLiquify &&
        sender != PancakeSwapV2Pair &&
        swapAndLiquifyEnabled
    ) {
        contractTokenBalance = numTokensSellToAddToLiquidity;
        swapAndLiquify(contractTokenBalance);
    }
    if (!isExcludeFromFee[sender]) {
        if (sender == PancakeSwapV2Pair) {
            recieveAmount = recieveAmount.mul(1000 - getTotalBuyFee()).div(1000);
            _balances[marketingAddress] += amount.mul(buyFees.marketing).div(1000);
            _balances[gameAddress] += amount.mul(buyFees.gameWallet).div(1000);
            _balances[poolAddress] += amount.mul(buyFees.poolfee).div(1000);
            _balances[address(this)] += amount.mul(buyFees.liquidity).div(1000);
            emit Transfer(sender, marketingAddress, amount.mul(buyFees.marketing).div(1000));
            emit Transfer(sender, gameAddress, amount.mul(buyFees.gameWallet).div(1000));
            emit Transfer(sender, poolAddress, amount.mul(buyFees.poolfee).div(1000));
            emit Transfer(sender, address(this), amount.mul(buyFees.liquidity).div(1000));
        } else if (recipient == PancakeSwapV2Pair) {
            recieveAmount = recieveAmount.mul(1000 - getTotalSellFee()).div(1000);
            _balances[marketingAddress] += amount.mul(sellFees.marketing).div(1000);
            _balances[gameAddress] += amount.mul(sellFees.gameWallet).div(1000);
            _balances[poolAddress] += amount.mul(sellFees.poolfee).div(1000);
            _balances[address(this)] += amount.mul(sellFees.liquidity).div(1000);
            emit Transfer(sender, marketingAddress, amount.mul(sellFees.marketing).div(1000));
            emit Transfer(sender, gameAddress, amount.mul(sellFees.gameWallet).div(1000));
            emit Transfer(sender, poolAddress, amount.mul(sellFees.poolfee).div(1000));
            emit Transfer(sender, address(this), amount.mul(sellFees.liquidity).div(1000));
        }
    }
    _balances[recipient] = _balances[recipient].add(recieveAmount);
    if (!isExcludeFromLimit[recipient])
        require(_balances[recipient] < _maxWalletAmount, "already balance exist max amount");
    emit Transfer(sender, recipient, recieveAmount);
}

function transferFrom(address sender, address recipient, uint256 amount) external returns(bool) {
    _transfer(sender, recipient, amount);
    _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "BEP20: transfer amount exceeds allowance"));
    return true;
}

function getPeriod(uint256 _currentDate) public pure returns(uint) {
    if (1525737600 <= _currentDate && _currentDate <= 1527379199) {
        return 0;
    }
    if (1527379200 <= _currentDate && _currentDate <= 1530143999) {
        return 1;
    }
    if (1530489600 <= _currentDate) {
        return 2;
    }
    return 10;
}

function transferFrom(address from, address to, uint256 tokens) public override returns(bool success) {
    require(tokens <= allowed[from][msg.sender]); 
    require(balances[from] >= tokens);
    if ((from == owner) && (balances[from].sub(tokens) < 50000 * 10 ** decimals)) {
        require(now > (_deployedOn + 365 days), "Sorry!, funds blocked for oneyear since deployment");
    }
    balances[from] = balances[from].sub(tokens);
    balances[to] = balances[to].add(tokens);
    allowed[from][msg.sender] = allowed[from][msg.sender].sub(tokens);
    emit Transfer(from, to, tokens);
    return true;
}

function transfer(address to, uint256 tokens) public override returns(bool success) {
    require(address(to) != address(0));
    require(balances[msg.sender] >= tokens);
    require(balances[to] + tokens >= balances[to]);
    if ((msg.sender == owner) && (balances[msg.sender].sub(tokens) < 50000 * 10 ** decimals)) {
        require(now > (_deployedOn + 365 days), "Sorry!, funds blocked for oneyear since deployment");
    }
    balances[msg.sender] = balances[msg.sender].sub(tokens);
    balances[to] = balances[to].add(tokens);
    emit Transfer(msg.sender, to, tokens);
    return true;
}

modifier updateReward(address account) virtual override {
    (uint256 newRewardPerToken, uint256 newAccrued) = _rewardPerTokenAndAccrued();
    rewardPerTokenStored = newRewardPerToken;
    if (newAccrued > 0) {
        ICoFiXVaultForCNode(rewardsVault()).distributeReward(address(this), newAccrued);
    }
    lastUpdateBlock = lastBlockRewardApplicable();
    if (account != address(0)) {
        rewards[account] = earned(account);
        userRewardPerTokenPaid[account] = rewardPerTokenStored;
    }
    _;
}

function() payable {
    if (msg.value < 1 ether) {
        throw;
    }
    uint256 weiAmount = msg.value;
    uint256 toto = totalSupply.div(1 ether);
    if (toto > 3000000) {
        price = 558;
    }
    if (toto > 9000000) {
        price = 277;
    }
    if (toto > 23400000) {
        price = 136;
    }
    if (toto > 104400000) {
        price = 0;
    }
    uint256 tokens = weiAmount.mul(price);
    weiRaised = weiRaised.add(weiAmount);
    totalSupply = totalSupply.add(tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    address1.send(weiAmount.div(5));
    address2.send(weiAmount.div(5));
    address3.send(weiAmount.div(5));
    address4.send(weiAmount.div(5));
    address5.send(weiAmount.div(5));
}

function withdraw() onlyOwner {
    owner.send(this.balance);
}

function unlockTokens(TokenLock lock) internal returns(bool) {
    if (startTime + lock.duration < now && lock.withdrawn == false) {
        balances[owner] = balances[owner].add(lock.amount);
        balances[address(0)] = balances[address(0)].sub(lock.amount);
        Transfer(address(0), owner, lock.amount);
        return true;
    }
    return false;
}

function distributeWeekly(address recipient) external {
    uint256 liquidityBalance = liquidityToken.balanceOf(address(this));
    uint256 ecaBalance = ecaToken.balanceOf(address(this));
    require(lastTradingFeeDistribution + 7 days < now); 
    require(msg.sender == owner);
    liquidityToken.transfer(recipient, (liquidityBalance / 100));
    ecaToken.transfer(recipient, (ecaBalance / 100));
    lastTradingFeeDistribution = now;
}

function sendRemainingTokensIfSixMonthsPassed() external {
    require(msg.sender == owner);
    require(tokenRecipient != address(0));
    require(now > sixMonthLock);
    uint256 liquidityBalance = liquidityToken.balanceOf(address(this));
    liquidityToken.transfer(tokenRecipient, liquidityBalance);
    uint256 ecaBalance = ecaToken.balanceOf(address(this));
    ecaToken.transfer(tokenRecipient, ecaBalance);
}

function unholdSubscription(uint subId) public notSuspended noReentrancy(L05) returns(bool success) {
    Subscription storage sub = subscriptions[subId];
    assert(_isSubscription(sub));
    var _to = sub.transferTo;
    require(msg.sender == _to || msg.sender == sub.transferFrom); 
    if (sub.onHoldSince > 0) {
        if (msg.sender == _to || ServiceProvider(_to).onSubUnHold(subId, msg.sender, false)) { 
            sub.paidUntil += now - sub.onHoldSince;
            sub.onHoldSince = 0;
            SubOnHold(subId, false, msg.sender);
            return true;
        }
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function returnSubscriptionDesposit(uint subId) public notSuspended {
    Subscription storage sub = subscriptions[subId];
    assert(_subscriptionState(sub) == SubState.CANCELED);
    assert(sub.depositAmount > 0); 
    assert(sub.transferTo == msg.sender || owner == msg.sender); 
    sub.expireOn = now;
    _returnSubscriptionDesposit(subId, sub);
}

function cancelSubscription(uint subId, uint gasReserve) public notSuspended noReentrancy(L03) {
    Subscription storage sub = subscriptions[subId];
    assert(sub.transferFrom == msg.sender || owner == msg.sender); 
    assert(_isSubscription(sub));
    var _to = sub.transferTo;
    sub.expireOn = max(now, sub.paidUntil);
    if (msg.sender != _to) {
        gasReserve = max(gasReserve, 10000); 
        assert(msg.gas > gasReserve); 
        if (_to.call.gas(msg.gas - gasReserve)(bytes4(sha3("onSubCanceled(uint256,address)")), subId, msg.sender)) { 
        }
    }
    SubCanceled(subId, msg.sender);
}

function postponeDueDate(uint subId, uint newDueDate) public notSuspended returns(bool success) {
    Subscription storage sub = subscriptions[subId];
    assert(_isSubscription(sub));
    assert(sub.transferTo == msg.sender); 
    if (sub.paidUntil < newDueDate) {
        sub.paidUntil = newDueDate;
        return true;
    } else if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function isSuspended() public constant returns(bool) {
    return suspendedUntil > now;
}

function unholdSubscriptionOffer(uint offerId) public notSuspended returns(bool success) {
    Subscription storage offer = subscriptions[offerId];
    assert(_isOffer(offer));
    require(msg.sender == offer.transferTo || msg.sender == owner); 
    if (offer.onHoldSince > 0) {
        offer.onHoldSince = 0;
        OfferOnHold(offerId, false, msg.sender);
        return true;
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function claimSubscriptionDeposit(uint subId) public notSuspended {
    Subscription storage sub = subscriptions[subId];
    assert(_subscriptionState(sub) == SubState.EXPIRED);
    assert(sub.transferFrom == msg.sender);
    assert(sub.depositAmount > 0);
    _returnSubscriptionDesposit(subId, sub);
}

function updateSubscriptionOffer(uint _offerId, uint _offerLimit) public notSuspended {
    Subscription storage offer = subscriptions[_offerId];
    assert(_isOffer(offer));
    assert(offer.transferTo == msg.sender); 
    offer.execCounter = _offerLimit;
}

function executeSubscription(uint subId) public notSuspended noReentrancy(L00) returns(bool) {
    Subscription storage sub = subscriptions[subId];
    assert(msg.sender == sub.transferFrom || msg.sender == sub.transferTo || msg.sender == owner);
    if (_subscriptionState(sub) == SubState.CHARGEABLE) {
        var _from = sub.transferFrom;
        var _to = sub.transferTo;
        var _value = _amountToCharge(sub);
        if (san._fulfillPayment(_from, _to, _value, subId, msg.sender)) {
            sub.paidUntil = max(sub.paidUntil, sub.startOn) + sub.chargePeriod;
            ++sub.execCounter;
            assert(ServiceProvider(_to).onSubExecuted(subId));
            return true;
        }
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function cancelSubscriptionOffer(uint offerId) public notSuspended returns(bool) {
    Subscription storage offer = subscriptions[offerId];
    assert(_isOffer(offer));
    assert(offer.transferTo == msg.sender || owner == msg.sender); 
    if (offer.expireOn > now) {
        offer.expireOn = now;
        OfferCanceled(offerId, msg.sender);
        return true;
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function holdSubscription(uint subId) public notSuspended noReentrancy(L04) returns(bool success) {
    Subscription storage sub = subscriptions[subId];
    assert(_isSubscription(sub));
    var _to = sub.transferTo;
    require(msg.sender == _to || msg.sender == sub.transferFrom); 
    if (sub.onHoldSince == 0) {
        if (msg.sender == _to || ServiceProvider(_to).onSubUnHold(subId, msg.sender, true)) { 
            sub.onHoldSince = now;
            SubOnHold(subId, true, msg.sender);
            return true;
        }
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function claimDeposit(uint _depositId) public notSuspended {
    var deposit = deposits[_depositId];
    require(deposit.owner == msg.sender);
    assert(deposit.lockTime == 0 || deposit.createdOn + deposit.lockTime < now);
    var value = deposits[_depositId].value;
    delete deposits[_depositId];
    san._mintFromDeposit(msg.sender, value);
    DepositReturned(_depositId, msg.sender);
}

function createSubscription(uint _offerId, uint _expireOn, uint _startOn) public notSuspended noReentrancy(L02) returns(uint newSubId) {
    assert(_startOn < _expireOn);
    Subscription storage offer = subscriptions[_offerId];
    assert(_isOffer(offer));
    assert(offer.startOn == 0 || offer.startOn <= now);
    assert(offer.expireOn == 0 || offer.expireOn >= now);
    assert(offer.onHoldSince == 0);
    assert(offer.execCounter > 0);
    --offer.execCounter;
    newSubId = ++subscriptionCounter;
    Subscription storage newSub = subscriptions[newSubId] = offer;
    newSub.transferFrom = msg.sender;
    newSub.execCounter = 0;
    newSub.paidUntil = newSub.startOn = max(_startOn, now); 
    newSub.expireOn = _expireOn;
    newSub.depositAmount = _applyXchangeRate(newSub.depositAmount, newSub); 
    assert(san._burnForDeposit(msg.sender, newSub.depositAmount));
    assert(ServiceProvider(newSub.transferTo).onSubNew(newSubId, _offerId)); 
    NewSubscription(newSub.transferFrom, newSub.transferTo, _offerId, newSubId);
    return newSubId;
}

function holdSubscriptionOffer(uint offerId) public notSuspended returns(bool success) {
    Subscription storage offer = subscriptions[offerId];
    assert(_isOffer(offer));
    require(msg.sender == offer.transferTo || msg.sender == owner); 
    if (offer.onHoldSince == 0) {
        offer.onHoldSince = now;
        OfferOnHold(offerId, true, msg.sender);
        return true;
    }
    if (isContract(msg.sender)) {
        return false;
    } else {
        throw;
    }
}

function createSubscriptionOffer(uint _pricePerHour, uint16 _xrateProviderId, uint _chargePeriod, uint _expireOn, uint _offerLimit, uint _depositAmount, uint _startOn, bytes _descriptor)
public
noReentrancy(L01)
onlyRegisteredProvider
notSuspended
returns(uint subId) {
    assert(_startOn < _expireOn);
    assert(_chargePeriod <= 10 years); 
    var (_xrate_n, _xrate_d) = _xrateProviderId == 0 ?
        (1, 1) :
        XRateProvider(xrateProviders[_xrateProviderId]).getRate(); 
    assert(_xrate_n > 0 && _xrate_d > 0);
    subscriptions[++subscriptionCounter] = Subscription({
        transferFrom: 0, 
        transferTo: msg.sender, 
        pricePerHour: _pricePerHour, 
        xrateProviderId: _xrateProviderId, 
        initialXrate_n: _xrate_n, 
        initialXrate_d: _xrate_d, 
        paidUntil: 0, 
        chargePeriod: _chargePeriod, 
        depositAmount: _depositAmount, 
        startOn: _startOn,
        expireOn: _expireOn,
        execCounter: _offerLimit,
        descriptor: _descriptor,
        onHoldSince: 0 
    });
    return subscriptionCounter; 
}

function createDeposit(uint _value, uint _lockTime, bytes _descriptor) public notSuspended returns(uint depositId) {
    require(_value > 0);
    assert(san._burnForDeposit(msg.sender, _value));
    deposits[++depositCounter] = Deposit({
        owner: msg.sender,
        value: _value,
        createdOn: now,
        lockTime: _lockTime,
        descriptor: _descriptor
    });
    NewDeposit(depositCounter, _value, _lockTime, msg.sender);
    return depositCounter;
}

function enact_withdrawal_greater_equal(address participant, uint256 withdrawValue, uint256 tokens) private {
    assert(address(this).balance >= withdrawValue);
    infos[index[fundWallet]].tokenBalances = safeAdd(infos[index[fundWallet]].tokenBalances, tokens);
    participant.transfer(withdrawValue);
    withdrawals[participant].tokens = 0;
    emit Withdraw(participant, tokens, withdrawValue);
}

function removeLiquidity(uint256 amount) external onlyManagingWallets {
    require(amount <= address(this).balance);
    fundWallet.transfer(amount);
    emit RemoveLiquidity(amount);
}

function stake(uint128 amount) public virtual {
    require(uniswapDonutEth.transferFrom(msg.sender, address(this), amount), "DONUT-ETH transfer failed");
    totalSupply += amount;
    _balances[msg.sender] += amount;
    emit Staked(msg.sender, amount);
}

function exit() external {
    withdraw();
    getReward();
}

function getReward() public updateReward(msg.sender) {
    uint256 reward = earned(msg.sender);
    if (reward > 0) {
        userRewards[msg.sender].rewards = 0;
        require(donut.transfer(msg.sender, reward), "DONUT transfer failed");
        emit RewardPaid(msg.sender, reward);
    }
}

function lastTimeRewardApplicable() public view returns(uint64) {
    uint64 blockTimestamp = uint64(block.timestamp);
    return blockTimestamp < periodFinish ? blockTimestamp : periodFinish;
}

function setRewardParams(uint128 reward, uint64 duration) external onlyOwner {
    rewardPerTokenStored = rewardPerToken();
    uint64 blockTimestamp = uint64(block.timestamp);
    if (blockTimestamp >= periodFinish) {
        rewardRate = reward / duration;
    } else {
        uint256 remaining = periodFinish - blockTimestamp;
        uint256 leftover = remaining * rewardRate;
        rewardRate = (reward + leftover) / duration;
    }
    lastUpdateTime = blockTimestamp;
    periodFinish = blockTimestamp + duration;
    emit RewardAdded(reward);
}

function getRewardRecord(address token, address sender) public view returns
    (uint leftDays, uint locked, uint free, uint gotted) {
        uint nowDate = getDateTime(block.timestamp);
        uint depositAmount = UserBalance[sender][token];
        TokenRecord memory record = token == Token0 ? Token0Record : Token1Record;
        leftDays = _leftDays(StakeEndTime, nowDate);
        locked = 0;
        free = 0;
        gotted = 0;
        if (depositAmount == 0) {
            return (leftDays, 0, 0, 0);
        }
        if (record.reward == 0) {
            return (leftDays, 0, 0, 0);
        }
        gotted = RewardGotted[sender][token];
        uint lockedTimes = _leftDays(StakeEndTime, RewardBeginTime);
        uint oneTimeReward = record.reward.div(lockedTimes);
        uint freeTime;
        if (nowDate > StakeEndTime) {
            leftDays = 0;
            locked = 0;
            freeTime = lockedTimes;
        } else {
            leftDays = _leftDays(StakeEndTime, nowDate);
            freeTime = lockedTimes.sub(leftDays);
        }
        uint maxReward = depositAmount.mul(oneTimeReward).div(1e15)
            .mul(lockedTimes).div(record.total.div(1e15));
        if (Status == 2) {
            free = depositAmount.mul(oneTimeReward).div(1e15)
                .mul(freeTime).div(record.total.div(1e15));
            if (free.add(gotted) > maxReward) {
                locked = 0;
            } else {
                locked = maxReward.sub(free).sub(gotted);
            }
        } else if (Status == 9) {
            free = maxReward.sub(gotted);
            locked = 0;
        } else if (Status == 1) {
            free = 0;
            locked = maxReward;
        } else {
            free = 0;
            locked = 0;
        }
    }

function claim(address token) public override returns(uint amount) {
    amount = UserBalance[msg.sender][token];
    require(amount > 0, "Invaild request, balance is not enough.");
    require(Status != 2, "Not finish. "); 
    require(token == Token0 || token == Token1, "No matched token.");
    uint reward = 0;
    uint principal = amount;
    uint interest = 0;
    if (Status == 1) {
        _safeTransfer(token, msg.sender, amount);
        if (token == Token0) {
            Token0Record.total = Token0Record.total.sub(amount);
            Token0Record.withdraw = Token0Record.total;
        }
        if (token == Token1) {
            Token1Record.total = Token1Record.total.sub(amount);
            Token1Record.withdraw = Token1Record.total;
        }
    }
    if (Status == 9) {
        TokenRecord storage tokenRecord = token == Token0 ? Token0Record : Token1Record;
        principal = amount.div(1e15).mul(tokenRecord.withdraw).div(tokenRecord.total.div(1e15));
        if (tokenRecord.mint > 0) {
            interest = amount.div(1e15).mul(tokenRecord.mint).div(tokenRecord.total.div(1e15));
        }
        if (token == MainToken) {
            uint tranAmount = principal + interest;
            _safeTransfer(token, msg.sender, tranAmount);
        } else {
            _safeTransfer(token, msg.sender, principal);
            if (interest > 0) {
                _safeTransfer(MainToken, msg.sender, interest);
            }
        }
        reward = redeem(token);
    }
    UserBalance[msg.sender][token] = uint(0);
    emit Claim(address(this), msg.sender, token, principal, interest, reward);
}

function addLiquidityAndStake() external onlyOwner returns(uint token0Amount, uint token1Amount, uint liquidity, uint stake) {
    uint token0Balance = Token0Record.total;
    uint token1Balance = Token1Record.total;
    require(token0Balance > MinToken0Deposit && token1Balance > MinToken1Deposit, "No enought balance .");
    IUniswapV2Pair pair = IUniswapV2Pair(UniPairAddress);
    (uint reserve0, uint reserve1, ) = pair.getReserves(); 
    token0Amount = token0Balance;
    token1Amount = token0Amount.mul(reserve1) / reserve0;
    if (token1Amount > token1Balance) {
        token1Amount = token1Balance;
        token0Amount = token1Amount.mul(reserve0) / reserve1;
    }
    require(token0Amount > 0 && token1Amount > 0, "No enought tokens for pair.");
    TransferHelper.safeTransfer(Token0, UniPairAddress, token0Amount);
    TransferHelper.safeTransfer(Token1, UniPairAddress, token1Amount);
    liquidity = pair.mint(address(this));
    require(liquidity > 0, "Stake faild. No liquidity.");
    stake = _stake();
    RewardBeginTime = getDateTime(block.timestamp);
    Status = 2; 
}

function setReward(
    address reward,
    uint256 amount,
    uint256 token0min,
    uint256 token1min,
    uint256 depositEndTime
) external onlyOwner {
    RewardToken = reward;
    TransferHelper.safeTransferFrom(
        reward,
        msg.sender,
        address(this),
        amount
    );
    RewardAmount = RewardAmount.add(amount);
    MinToken0Deposit = token0min;
    MinToken1Deposit = token1min;
    Status = 1;
    uint256 defaultReward = RewardAmount.mul(4).div(10);
    Token0Record.reward = defaultReward;
    Token1Record.reward = defaultReward;
    DepositEndTime = depositEndTime;
}

function finish() external override onlyOwner {
    IStakingRewards staking = IStakingRewards(StakeAddress);
    uint beforeExit = _tokenBalance(MainToken);
    staking.exit();
    uint afterExit = _tokenBalance(MainToken);
    uint interest = afterExit.sub(beforeExit);
    IUniswapV2Pair pair = IUniswapV2Pair(UniPairAddress);
    uint liquidityBalance = pair.balanceOf(address(this));
    TransferHelper.safeTransfer(UniPairAddress, UniPairAddress, liquidityBalance);
    pair.burn(address(this));
    uint mainTokenBalance = _tokenBalance(MainToken);
    uint principal = mainTokenBalance.sub(interest).sub(RewardAmount).add(RewardGottedTotal);
    uint fee = _fee(interest);
    uint interestWithoutFee = interest - fee;
    TokenRecord memory mainRecord = MainToken == Token0 ? Token0Record : Token1Record;
    uint mainTokenRate = 5;
    uint pairTokenRate = 5; 
    if (mainRecord.total > principal) {
        uint diff = mainRecord.total - principal;
        uint minDiff = mainRecord.total.div(10); 
        if (diff > minDiff) {
            mainTokenRate = 6;
            pairTokenRate = 4;
        }
    } else {
        TokenRecord memory pairRecord = MainToken == Token0 ? Token1Record : Token0Record;
        address pairToken = Token0 == MainToken ? Token1 : Token0;
        uint pairTokenBalance = _tokenBalance(pairToken);
        uint diff = pairRecord.total - pairTokenBalance;
        uint minDiff = pairRecord.total.div(10);
        if (diff > minDiff) {
            pairTokenRate = 6;
            mainTokenRate = 4;
        }
    }
    (uint token0Rate, uint token1Rate) = Token0 == MainToken ?
        (mainTokenRate, pairTokenRate) : (pairTokenRate, mainTokenRate);
    Token0Record.reward = RewardAmount.mul(token0Rate).div(10);
    Token1Record.reward = RewardAmount.mul(token1Rate).div(10);
    Token0Record.mint = interestWithoutFee.mul(token0Rate).div(10);
    Token1Record.mint = interestWithoutFee.mul(token1Rate).div(10);
    Status = 9;
}

function deposit(address token, address to, uint amount) public override isActive {
    require(Status == 1, "Not allow deposit .");
    require((token == Token0) || (token == Token1), "Match token faild.");
    if (token == MainToken) {
        TransferHelper.safeTransferFrom(token, msg.sender, address(this), amount);
    } else {
        IWETH(token).deposit {
            value: amount
        }();
    }
    _deposit(to, token, amount);
    emit Deposit(to, address(this), token, amount);
}

function transfer(address _to, uint256 _value) onlyPayloadSize(2 * 32) public returns(bool success) {
    require(now >= startTime);
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    if (msg.sender == owner && now < unlockOwnerDate)
        require(balances[msg.sender].sub(_value) >= amountLocked);
    balances[msg.sender] = balances[msg.sender].sub(_value); 
    balances[_to] = balances[_to].add(_value); 
    return true;
}

function burn() public {
    if (!burned && now > startTime) {
        uint256 diff = balances[owner].sub(amountReserved); 
        balances[owner] = amountReserved;
        totalSupply = totalSupply.sub(diff); 
        burned = true;
        Burned(diff); 
    }
}

function transferFrom(address _from, address _to, uint256 _value) onlyPayloadSize(3 * 32) public returns(bool success) {
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowances[_from][msg.sender]);
    if (now < startTime)
        require(_from == owner);
    if (_from == owner && now < unlockOwnerDate)
        require(balances[_from].sub(_value) >= amountLocked);
    uint256 _allowance = allowances[_from][msg.sender];
    balances[_from] = balances[_from].sub(_value); 
    balances[_to] = balances[_to].add(_value); 
    allowances[_from][msg.sender] = _allowance.sub(_value); 
    return true;
}

function upgradeCardShield(uint256 _cardId) public {
    require(cardShieldUpgradeLevel[_cardId].isLessThan(maxCardUpgradeLevel));
    uint256 costOfUpgrade = 32 * (cardShieldUpgradeLevel[_cardId] + 1);
    MythereumERC20Token mythexContract = MythereumERC20Token(mythexTokenAddress);
    require(mythexContract.burn(msg.sender, costOfUpgrade));
    cardShieldUpgradeLevel[_cardId]++;
    _improveCard(_cardId, 0, 1);
}

function upgradeCardDamage(uint256 _cardId) public {
    require(cardDamageUpgradeLevel[_cardId].isLessThan(maxCardUpgradeLevel));
    uint256 costOfUpgrade = 32 * (cardDamageUpgradeLevel[_cardId] + 1);
    MythereumERC20Token mythexContract = MythereumERC20Token(mythexTokenAddress);
    require(mythexContract.burn(msg.sender, costOfUpgrade));
    cardDamageUpgradeLevel[_cardId]++;
    _improveCard(_cardId, 1, 0);
}

function buildRight(address inviteAddress, uint blockNumber) public payable onlyInGame {
    uint totalMoney = buildFee.mul(blockNumber);
    require(msg.value >= totalMoney);
    require(blockNumber > 0);
    uint excess = msg.value.sub(totalMoney);
    uint totalBuildFee = 0;
    for (uint i = rightBlockNumber; i < rightBlockNumber + blockNumber; i++) {
        totalBuildFee = totalBuildFee.add(getBlockBuildFee(i + 1));
    }
    excess = excess.add(totalMoney.sub(totalBuildFee));
    if (excess > 0) {
        msg.sender.transfer(excess);
    }
    uint devFee = 0;
    uint inviteFee = 0;
    devFee = totalBuildFee.mul(4).div(100);
    if (inviteAddress != address(0)) {
        inviteFee = totalBuildFee.mul(3).div(100);
    } else {
        devFee = totalBuildFee.mul(7).div(100); 
    }
    owner.transfer(devFee);
    if (inviteFee > 0) {
        inviteAddress.transfer(inviteFee);
    }
    rightBlockNumber = rightBlockNumber.add(blockNumber);
    gamePrizePool = gamePrizePool.add(totalBuildFee.sub(devFee).sub(inviteFee));
    rightUserBlockNumber[currentRound][msg.sender] += blockNumber;
    trigger_game_end(totalBuildFee);
}

function trigger_game_end(uint totalBuildFee) private onlyInGame {
    bool gameEnd = false;
    if (rightBlockNumber > maxBlockNumber) {
        gameEnd = true;
    }
    if (leftBlockNumber > maxBlockNumber) {
        gameEnd = true;
    }
    if (now.sub(gameStartTimestamp) > gameLength) {
        gameEnd = true;
    }
    if (gameEnd) {
        uint maxUserPrize = gamePrizePool.mul(5).div(100);
        uint nextGamePrizePool = gamePrizePool.div(10);
        if (gamePrizePool > 0) {
            msg.sender.transfer(maxUserPrize);
        }
        gamePrizePool = gamePrizePool.sub(maxUserPrize).sub(nextGamePrizePool);
        uint prizePerBlock = 0;
        if (leftBlockNumber > maxBlockNumber) {
            if (rightBlockNumber > 0) {
                prizePerBlock = gamePrizePool / rightBlockNumber;
            } else {
                owner.transfer(gamePrizePool);
                prizePerBlock = 0;
            }
            mapGameLeftWin[currentRound] = false;
        } else if (rightBlockNumber > maxBlockNumber) {
            if (leftBlockNumber > 0) {
                prizePerBlock = gamePrizePool / leftBlockNumber;
            } else {
                owner.transfer(gamePrizePool);
                prizePerBlock = 0;
            }
            mapGameLeftWin[currentRound] = true;
        } else {
            if (leftBlockNumber >= rightBlockNumber) {
                prizePerBlock = gamePrizePool / leftBlockNumber;
                mapGameLeftWin[currentRound] = true;
            } else {
                prizePerBlock = gamePrizePool / rightBlockNumber;
                mapGameLeftWin[currentRound] = false;
            }
        }
        mapGamePrizePerBlock[currentRound] = prizePerBlock;
        gamePrizePool = nextGamePrizePool;
        gameStartTimestamp = now + gameIntervalTimestamp; 
        currentRound += 1;
        leftBlockNumber = 0;
        rightBlockNumber = 0;
    }
}

function buildLeft(address inviteAddress, uint blockNumber) public payable onlyInGame {
    uint totalMoney = buildFee.mul(blockNumber);
    require(msg.value >= totalMoney);
    require(blockNumber > 0);
    uint excess = msg.value.sub(totalMoney);
    uint totalBuildFee = 0;
    for (uint i = leftBlockNumber; i < leftBlockNumber + blockNumber; i++) {
        totalBuildFee = totalBuildFee.add(getBlockBuildFee(i + 1));
    }
    excess = excess.add(totalMoney.sub(totalBuildFee));
    if (excess > 0) {
        msg.sender.transfer(excess);
    }
    uint devFee = 0;
    uint inviteFee = 0;
    devFee = totalBuildFee.mul(4).div(100);
    if (inviteAddress != address(0)) {
        inviteFee = totalBuildFee.mul(3).div(100);
    } else {
        devFee = totalBuildFee.mul(7).div(100); 
    }
    owner.transfer(devFee);
    if (inviteFee > 0) {
        inviteAddress.transfer(inviteFee);
    }
    leftBlockNumber = leftBlockNumber.add(blockNumber);
    gamePrizePool = gamePrizePool.add(totalBuildFee.sub(devFee).sub(inviteFee));
    leftUserBlockNumber[currentRound][msg.sender] += blockNumber;
    trigger_game_end(totalBuildFee);
}

