function close() onlyOwner public {
    require(state == State.Active);
    state = State.Closed;
    wallet.transfer(this.balance);
    Closed();
}

function buyTokens(address _recipient, uint256 _value) internal nonZero returns(bool success) {
    uint256 boughtTokens = calculateTokens(_value);
    require(boughtTokens != 0);
    boughtTokens = boughtTokens * (10 ** decimals);
    if (balanceOf(_recipient) == 0) {
        investorCount++;
    }
    if (isCrowdSaleStatePreSale()) {
        transferTokens(_recipient, boughtTokens);
        vault.deposit.value(_value)(_recipient);
        preSaleRaised = preSaleRaised.add(_value);
        return true;
    } else if (isCrowdSaleStateICO()) {
        transferTokens(_recipient, boughtTokens);
        vault.deposit.value(_value)(_recipient);
        icoRaised = icoRaised.add(_value);
        return true;
    }
}

function getVested(address _beneficiary) public returns(uint256) {
    require(balances[_beneficiary] > 0);
    if (_beneficiary == owner) {
        vested[owner] = balances[owner];
        total_vested[owner] = balances[owner];
    } else if (block.timestamp < start) {
        vested[_beneficiary] = 0;
        total_vested[_beneficiary] = 0;
    } else if (block.timestamp >= start.add(duration)) {
        total_vested[_beneficiary] = balances[_beneficiary];
        vested[_beneficiary] = balances[_beneficiary];
    } else {
        uint vested_now = balances[_beneficiary].mul(block.timestamp.sub(start)).div(duration);
        if (total_vested[_beneficiary] == 0) {
            total_vested[_beneficiary] = vested_now;
        }
        if (vested_now > total_vested[_beneficiary]) {
            vested[_beneficiary] = vested[_beneficiary].add(vested_now.sub(total_vested[_beneficiary]));
            total_vested[_beneficiary] = vested_now;
        }
    }
    return vested[_beneficiary];
}

function approve(address _spender, uint256 _tokens_in_cents) returns(bool success) {
    require(vested[msg.sender] >= _tokens_in_cents);
    allowed[msg.sender][_spender] = _tokens_in_cents;
    Approval(msg.sender, _spender, _tokens_in_cents);
    return true;
}

function isICOPeriod() public constant returns(bool) {
    if (icoRaised > icoHardCapInWei || now >= icoEndTimestamp) {
        crowdSaleState = State.ICOFinalized;
        return false;
    } else {
        return now > icoStartTimestamp;
    }
}

function calculateTokens(uint256 _amount) internal returns(uint256 tokens) {
    if (crowdSaleState == State.Preparing && isPreSalePeriod()) {
        crowdSaleState = State.PreSale;
    }
    if (isCrowdSaleStatePreSale()) {
        tokens = _amount.div(rateICO);
    } else if (isCrowdSaleStateICO()) {
        tokens = _amount.div(rateICO);
    } else {
        tokens = 0;
    }
}

function transferFrom(address _from, address _to, uint256 _tokens_in_cents) public returns(bool success) {
    require(_tokens_in_cents > 0);
    require(_from != _to);
    getVested(_from);
    require(balances[_from] >= _tokens_in_cents);
    require(vested[_from] >= _tokens_in_cents);
    require(allowed[_from][msg.sender] >= _tokens_in_cents);
    if (balanceOf(_to) == 0) { 
        investorCount++;
    }
    balances[_from] = balances[_from].sub(_tokens_in_cents);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_tokens_in_cents);
    vested[_from] = vested[_from].sub(_tokens_in_cents);
    balances[_to] = balances[_to].add(_tokens_in_cents);
    if (balanceOf(_from) == 0) { 
        investorCount = investorCount - 1;
    }
    Transfer(_from, _to, _tokens_in_cents);
    return true;
}

function isPreSalePeriod() public constant returns(bool) {
    if (preSaleRaised > preSaleMaxCapInWei || now >= presaleEndTimestamp) {
        crowdSaleState = State.PresaleFinalized;
        return false;
    } else {
        return now > presaleStartTimestamp;
    }
}

function transfer(address _to, uint256 _tokens_in_cents) public returns(bool) {
    require(_tokens_in_cents > 0);
    require(_to != msg.sender);
    getVested(msg.sender);
    require(balances[msg.sender] >= _tokens_in_cents);
    require(vested[msg.sender] >= _tokens_in_cents);
    if (balanceOf(_to) == 0) { 
        investorCount++;
    }
    balances[msg.sender] = balances[msg.sender].sub(_tokens_in_cents);
    vested[msg.sender] = vested[msg.sender].sub(_tokens_in_cents);
    balances[_to] = balances[_to].add(_tokens_in_cents);
    if (balanceOf(msg.sender) == 0) { 
        investorCount = investorCount - 1;
    }
    Transfer(msg.sender, _to, _tokens_in_cents);
    return true;
}

function endCrowdSale() public onlyOwner {
    require(now >= icoEndTimestamp || icoRaised >= icoSoftCapInWei);
    if (icoRaised >= icoSoftCapInWei) {
        crowdSaleState = State.Success;
        vault.close(); 
    } else {
        crowdSaleState = State.Failure;
        vault.enableRefunds(); 
    }
}

function transferEther(address _to, uint256 _value) onlyOwner public returns(bool) {
    require(_value <= contractEth);
    _to.transfer(_value);
    contractEth = contractEth.sub(_value);
    TransferContractEth(_to, _value);
    return true;
}

function sellTokens(uint256 _value) public returns(bool) {
    uint256 sellEth;
    require(allowSell);
    require(_value > 0);
    require(balances[msg.sender] >= _value);
    if (sellPrice == 0) {
        sellEth = 0;
    } else {
        sellEth = _value.mul(sellPrice).div(100);
    }
    super.transferByInternal(msg.sender, owner, _value);
    SellToken(msg.sender, _value, sellEth);
    msg.sender.transfer(sellEth);
    contractEth = contractEth.sub(sellEth);
}

function isWithinPeriod(address beneficiary) internal view returns(bool) {
    uint batchNumber = whiteListed.getBatchNumber(beneficiary);
    return now >= batchStartTimes[batchNumber] && now <= endTime;
}

function batchActive() public view returns(uint) {
    if (now > endTime) {
        return batchStartTimes.length + 1;
    }
    for (uint i = batchStartTimes.length; i > 0; i--) {
        if (now > batchStartTimes[i - 1]) {
            return i;
        }
    }
    return 0;
}

function isBatchActive(uint batch) public view returns(bool) {
    if (now > endTime) {
        return false;
    }
    if (uint(batch) >= batchStartTimes.length) {
        return false;
    }
    if (now > batchStartTimes[batch]) {
        return true;
    }
    return false;
}

function updateUsdPerMEth(uint _usdPerMEth) public canOperate {
    require(now < batchStartTimes[0]);
    usdPerMEth = _usdPerMEth;
    publicSaleSencPerMEth = usdPerMEth.mul(MILLION).div(PUBLICSALE_USD_PER_MSENC);
    privateSaleSencPerMEth = usdPerMEth.mul(MILLION).div(PRIVATESALE_USD_PER_MSENC);
}

function buyTokens(address beneficiary, uint weiAmount) internal whenNotPaused {
    require(beneficiary != address(0));
    require(isWhiteListed(beneficiary));
    require(isWithinPeriod(beneficiary));
    require(isWithinAllocation(beneficiary, weiAmount));
    uint tokens = weiAmount.mul(publicSaleSencPerMEth).div(MILLION);
    weiRaised = weiRaised.add(weiAmount);
    if (contributions[beneficiary] == 0) {
        numContributors++;
    }
    contributions[beneficiary] = contributions[beneficiary].add(weiAmount);
    token.mint(beneficiary, tokens);
    TokenPurchase(beneficiary, weiAmount, tokens);
    forwardFunds();
}

function finalize() onlyOwner public {
    require(!isFinalized);
    require(hasEnded());
    finalization();
    Finalized();
    isFinalized = true;
}

function withdrawBalance(address _beneficiary) external {
    uint256 payout = creatorBalances[_beneficiary];
    creatorBalances[_beneficiary] = 0;
    _beneficiary.transfer(payout);
    endingBalance = address(this).balance;
}

function refundSubmission(address _refundee, uint256 _amount) external onlyAdmin() {
    submissionPool = submissionPool.sub(_amount);
    _refundee.transfer(_amount);
    endingBalance = address(this).balance;
}

function withdraw(uint256 _devAmount, uint256 _submissionAmount) public onlyAdmin() {
    if (_devAmount == 0) {
        _devAmount = developerCut;
    }
    if (_submissionAmount == 0) {
        _submissionAmount = submissionPool;
    }
    developerCut = developerCut.sub(_devAmount);
    submissionPool = submissionPool.sub(_submissionAmount);
    owner.transfer(_devAmount + _submissionAmount);
    endingBalance = address(this).balance;
}

function buyToken(uint256 _tokenId) public
payable {
    Meme storage meme = memeData[_tokenId];
    uint256 price = meme.price;
    address oldOwner = meme.owner;
    address newOwner = msg.sender;
    uint256 excess = msg.value.sub(price);
    require(price > 0);
    require(msg.value >= price);
    require(oldOwner != msg.sender);
    uint256 devCut = price.mul(2).div(100);
    developerCut = developerCut.add(devCut);
    uint256 creatorCut = price.mul(2).div(100);
    creatorBalances[meme.creator] = creatorBalances[meme.creator].add(creatorCut);
    uint256 transferAmount = price.sub(creatorCut + devCut);
    transferToken(oldOwner, newOwner, _tokenId);
    emit Purchase(_tokenId, newOwner, oldOwner, price);
    meme.price = getNextPrice(price);
    safeTransfer(oldOwner, transferAmount);
    if (excess > 0) {
        newOwner.transfer(excess);
    }
    if (address(this).balance > endingBalance + creatorCut + devCut) submissionPool += transferAmount;
    endingBalance = address(this).balance;
}

function refundByToken(uint256 _tokenId) external onlyAdmin() {
    submissionPool = submissionPool.sub(submissionPrice);
    memeData[_tokenId].creator.transfer(submissionPrice);
    endingBalance = address(this).balance;
}

