function giveBirth(uint256 _matronId, uint256 genes)
external
whenNotPaused
returns(uint256) {
    Dog storage matron = dogs[_matronId];
    require(matron.birthTime != 0);
    require(_isReadyToGiveBirth(matron));
    uint256 sireId = matron.siringWithId;
    Dog storage sire = dogs[sireId];
    uint16 parentGen = matron.generation;
    if (sire.generation > matron.generation) {
        parentGen = sire.generation;
    }
    uint256 gen0 = matron.generation == 0 ? _matronId : matron.gen0;
    uint256 childGenes = genes;
    if (giveBirthByUser) {
        require(address(geneScience) != address(0));
        childGenes = geneScience.mixGenes(matron.genes, sire.genes, matron.cooldownEndBlock - 1);
    } else {
        require(msg.sender == ceoAddress || msg.sender == cooAddress || msg.sender == cfoAddress);
    }
    address owner = dogIndexToOwner[_matronId];
    uint8 _variation = variation.createVariation(childGenes, dogs.length);
    bool isGen0Siring = matron.generation == 0;
    uint256 kittenId = _createDog(_matronId, matron.siringWithId, parentGen + 1, childGenes, owner, _variation, gen0, isGen0Siring);
    delete matron.siringWithId;
    pregnantDogs--;
    if (_variation != 0) {
        variation.registerVariation(kittenId, owner);
        _transfer(owner, address(variation), kittenId);
    }
    return kittenId;
}

function _breedWith(uint256 _matronId, uint256 _sireId) internal {
    require(_matronId > 1);
    require(_sireId > 1);
    Dog storage sire = dogs[_sireId];
    Dog storage matron = dogs[_matronId];
    require(sire.variation == 0);
    require(matron.variation == 0);
    if (matron.generation > 0) {
        var (, , openBlock, , , , , , ) = lottery.getCLottery();
        if (matron.birthTime < openBlock) {
            require(lottery.checkLottery(matron.genes) == 100);
        }
    }
    matron.siringWithId = uint32(_sireId);
    _triggerCooldown(sire);
    _triggerCooldown(matron);
    delete sireAllowedToAddress[_matronId];
    delete sireAllowedToAddress[_sireId];
    pregnantDogs++;
    cfoAddress.transfer(autoBirthFee);
    address owner = getOwner(0);
    if (owner != address(0)) {
        _sendMoney(owner, creationProfit);
    }
    owner = getOwner(1);
    if (owner != address(0)) {
        _sendMoney(owner, creationProfit);
    }
    if (matron.generation > 0) {
        owner = getOwner(matron.gen0);
        if (owner != address(0)) {
            _sendMoney(owner, gen0Profit);
        }
    }
    Pregnant(dogIndexToOwner[_matronId], _matronId, _sireId, matron.cooldownEndBlock, sire.cooldownEndBlock, matron.cooldownIndex, sire.cooldownIndex);
}

function bidOnSaleAuction(
    uint256 _dogId
)
external
payable
whenNotPaused {
    Dog storage dog = dogs[_dogId];
    if (dog.generation > 0) {
        var (, , openBlock, , , , , , ) = lottery.getCLottery();
        if (dog.birthTime < openBlock) {
            require(lottery.checkLottery(dog.genes) == 100);
        }
    }
    uint256 currentPrice = saleAuction.getCurrentPrice(_dogId);
    require(msg.value >= currentPrice);
    bool isCreationKitty = _dogId == 0 || _dogId == 1;
    uint256 fee = 0;
    if (isCreationKitty) {
        fee = uint256(currentPrice / 5);
    }
    uint256 auctioneerCut = saleAuction.computeCut(currentPrice);
    saleAuction.bid.value(currentPrice - (auctioneerCut + fee))(_dogId, msg.sender);
    if (isCreationKitty) {
        cfoAddress.transfer(fee);
        uint256 nextPrice = uint256(uint128(2 * currentPrice));
        if (nextPrice < currentPrice) {
            nextPrice = currentPrice;
        }
        _approve(_dogId, saleAuction);
        saleAuction.createAuction(
            _dogId,
            nextPrice,
            nextPrice,
            GEN0_AUCTION_DURATION,
            msg.sender);
    }
    uint256 bidExcess = msg.value - currentPrice;
    if (bidExcess > 0) {
        msg.sender.transfer(bidExcess);
    }
}

function withdraw() public {
    uint256 value = profit[msg.sender];
    require(value > 0);
    msg.sender.transfer(value);
    spendMoney -= value;
    delete profit[msg.sender];
    Withdraw(msg.sender, value);
}

function bidOnSiringAuction(
    uint256 _sireId,
    uint256 _matronId
)
external
payable
whenNotPaused {
    require(_owns(msg.sender, _matronId));
    require(isReadyToBreed(_matronId));
    require(_canBreedWithViaAuction(_matronId, _sireId));
    uint256 currentPrice = siringAuction.getCurrentPrice(_sireId);
    uint256 totalFee = currentPrice + autoBirthFee + creationProfit + creationProfit;
    Dog storage matron = dogs[_matronId];
    if (matron.generation > 0) {
        totalFee += gen0Profit;
    }
    require(msg.value >= totalFee);
    uint256 auctioneerCut = saleAuction.computeCut(currentPrice);
    siringAuction.bid.value(currentPrice - auctioneerCut)(_sireId, msg.sender);
    _breedWith(uint32(_matronId), uint32(_sireId));
    uint256 bidExcess = msg.value - totalFee;
    if (bidExcess > 0) {
        msg.sender.transfer(bidExcess);
    }
}

function claim() external returns(uint) {
    uint _period = _update_period();
    uint _last = Math.max(_period, _last_claim[msg.sender]);
    uint _reward = ve(_veibff).balanceOf(msg.sender, _period) * _reward_per / PRECISION;
    uint _accrued = _reward * (block.timestamp - _last) / WEEK;
    if (_accrued > 0) {
        _last_claim[msg.sender] = block.timestamp;
        _safeTransfer(_ibff, msg.sender, _accrued);
    }
    return _accrued;
}

function confirmAndExecuteWithdrawal() public onlyOwners payable {
    isConfirmed[msg.sender] = true;
    for (uint i = 0; i < threshold; i++) {
        if (isConfirmed[ownersArr[i]]) {
            confirmedTimesByOwners++;
        }
    }
    if (confirmedTimesByOwners >= (threshold - 1)) { 
        nonce = nonce + 1;
        pendingAddress.transfer(pendingAmount);
        pendingAmount = 0;
        pendingAddress = 0x0;
        confirmedTimesByOwners = 0;
        for (uint j = 0; j < threshold; j++) {
            isConfirmed[ownersArr[j]] = false;
        }
    }
}

function createTokens(address recipient) public payable {
    if (ICOActive && (now < ICO_hardcoded_expiry_date)) {
        require(msg.value >= 0.1 * (1 ether)); 
        tokensToBuy = safeDiv(safeMul(msg.value * 1 ether, ICOTokenPrice), 1000000000000000000 ether);
        require(totalCollected + tokensToBuy <= totalTokensCap); 
        ICOCollected = safeAdd(ICOCollected, tokensToBuy);
        totalCollected = safeAdd(totalCollected, tokensToBuy);
        balances[recipient] = safeAdd(balances[recipient], tokensToBuy);
        balances[owner] = safeSub(balances[owner], tokensToBuy);
        emit Transfer(owner, recipient, tokensToBuy);
    } else {
        revert("Edgecoin ICO has ended.");
    }
}

function receivePercent() isIssetUser timePayment internal {
    uint balanceLimit = counterDeposits.mul(responseStubFundLimit).div(1000);
    uint payoutRatio = calculationOfPayment();
    uint remain = counterDeposits.mul(6).div(100);
    if (addressStub.balance > 0) {
        if (address(this).balance < balanceLimit) {
            stubF.ReturnEthToEtherhero();
        }
    }
    require(address(this).balance >= remain, 'contract balance is too small');
    uint rate = userDeposit[msg.sender].mul(standartPercent).div(1000).mul(payoutRatio);
    userTime[msg.sender] = now;
    msg.sender.transfer(rate);
    counterPercents += rate;
    timeLastayment = now;
    insertBeneficiaries(msg.sender, standartPercent, rate, 0);
    emit dividendPayment(msg.sender, rate);
}

function makeDeposit() private {
    uint value = msg.value;
    uint calcProjectPercent = value.mul(percentProjectFund).div(100);
    uint calcStubFundPercent = value.mul(percentStubFund).div(100);
    if (msg.value > 0) {
        require(msg.value >= minPayment, 'Minimum deposit 1 finney');
        if (userDeposit[msg.sender] == 0) {
            emit NewInvestor(msg.sender, msg.value);
        }
        userDeposit[msg.sender] = userDeposit[msg.sender].add(msg.value);
        userTime[msg.sender] = now;
        insertBeneficiaries(msg.sender, 0, 0, msg.value);
        projectFund.transfer(calcProjectPercent);
        stubF.call.value(calcStubFundPercent).gas(estGas)();
        counterDeposits += msg.value;
        emit NewDeposit(msg.sender, msg.value);
    } else {
        receivePercent();
    }
}

function calculationOfPayment() public view returns(uint) {
    uint interestRate = now.sub(userTime[msg.sender]).div(chargingTime);
    if (userDeposit[msg.sender] < 10 ether) {
        if (interestRate >= 1) {
            return (1);
        } else {
            return (interestRate);
        }
    }
    if (userDeposit[msg.sender] >= 10 ether && userDeposit[msg.sender] < 50 ether) {
        if (interestRate > 3) {
            return (3);
        } else {
            return (interestRate);
        }
    }
    if (userDeposit[msg.sender] >= 50 ether) {
        if (interestRate > 7) {
            return (7);
        } else {
            return (interestRate);
        }
    }
}

