    require(now < (timeLimit + 86400));
    uint i = 0;
    while (i++ < value) {
        uint TicketNumber = ticketsSold + i;
        Tickets[TicketNumber].addr = msg.sender;
        Tickets[TicketNumber].time = now;
    }
    ticketsSold = ticketsSold + value;
}

function _claim() private {
    require(xinv.redeem(claimableXINV()) == 0, "REDEEM FAILED");
    inv.transfer(recipient, inv.balanceOf(address(this)));
    lastUpdate = block.timestamp;
}

function cancel() public {
    require(msg.sender == governance || msg.sender == recipient, "ONLY GOVERNANCE OR RECIPIENT");
    require(isCancellable || msg.sender == recipient, "NOT CANCELLABLE");
    require(!isCancelled, "ALREADY CANCELLED");
    _claim();
    require(xinv.redeem(xinv.balanceOf(address(this))) == 0, "REDEEM FAILED");
    inv.transfer(governance, inv.balanceOf(address(this)));
    isCancelled = true;
}

function claimableXINV() public view returns(uint xinvAmount) {
    if (isCancelled) return 0;
    if (block.timestamp >= vestingEnd) {
        xinvAmount = xinv.balanceOf(address(this));
    } else {
        xinvAmount = vestingXinvAmount.mul(block.timestamp - lastUpdate).div(vestingEnd - vestingBegin);
    }
}

function initialize() public {
    uint _invAmount = inv.balanceOf(address(this));
    require(_invAmount > 0, "INV AMOUNT IS 0");
    require(msg.sender == factory, "ONLY FACTORY");
    inv.approve(address(xinv), _invAmount);
    require(xinv.mint(_invAmount) == 0, "MINT FAILED");
    vestingXinvAmount = xinv.balanceOf(address(this));
}

function deployVester(address _recipient, uint _invAmount, uint _vestingStartTimestamp, uint _vestingDurationSeconds, bool _isCancellable) public {
    require(msg.sender == governance, "ONLY GOVERNANCE");
    XinvVester vester = new XinvVester(xinv, inv, governance, _recipient, _vestingStartTimestamp, _vestingDurationSeconds, _isCancellable);
    inv.transferFrom(governance, address(vester), _invAmount);
    vester.initialize();
    vesters.push(vester);
}

function transferFrom(address _from, address _to, uint256 _tokenId) public stopWhenHalted onlyAllowed(_tokenId) returns(bool) {
    require(pepes[_tokenId].master == _from); 
    require(_to != address(0));
    _transfer(_from, _to, _tokenId); 
    return true;
}

function cozyTime(uint256 _mother, uint256 _father, address _pepeReceiver) external stopWhenHalted returns(bool) {
    require(_mother != _father);
    require(pepes[_mother].master == msg.sender || approved[_mother] == msg.sender || approvedForAll[pepes[_mother].master][msg.sender]);
    require(pepes[_father].master == msg.sender || approved[_father] == msg.sender || approvedForAll[pepes[_father].master][msg.sender]);
    require(now > pepes[_mother].canCozyAgain && now > pepes[_father].canCozyAgain);
    require(pepes[_mother].mother != _father && pepes[_mother].father != _father);
    require(pepes[_father].mother != _mother && pepes[_father].father != _mother);
    Pepe storage father = pepes[_father];
    Pepe storage mother = pepes[_mother];
    approved[_father] = address(0);
    approved[_mother] = address(0);
    uint256[2] memory newGenotype = breed(father.genotype, mother.genotype, pepes.length);
    uint64 newGeneration;
    newGeneration = mother.generation + 1;
    if (newGeneration < father.generation + 1) { 
        newGeneration = father.generation + 1;
    }
    _handleCoolDown(_mother);
    _handleCoolDown(_father);
    pepes[_newPepe(newGenotype, uint64(_mother), uint64(_father), newGeneration, _pepeReceiver)].canCozyAgain = mother.canCozyAgain; 
    return true;
}

function halt(uint256 _duration) public onlyOwner {
    require(haltTime == 0); 
    require(_duration <= maxHaltDuration); 
    haltDuration = _duration;
    halted = true;
    haltTime = now;
}

function _handleCoolDown(uint256 _pepeId) internal {
    Pepe storage tempPep = pepes[_pepeId];
    tempPep.canCozyAgain = uint64(now + cozyCoolDowns[tempPep.coolDownIndex]);
    if (tempPep.coolDownIndex < 14) { 
        tempPep.coolDownIndex++;
    }
}

function buyCozy(uint256 _pepeId, uint256 _cozyCandidate, bool _candidateAsFather, address _pepeReceiver) public payable {
    require(address(pepeContract) == msg.sender); 
    PepeAuction storage auction = auctions[_pepeId];
    require(now < auction.auctionEnd); 
    uint256 price = calculateBid(_pepeId);
    require(msg.value >= price); 
    uint256 totalFee = price * fee / FEE_DIVIDER; 
    auction.seller.transfer(price - totalFee);
    address affiliate = affiliateContract.userToAffiliate(_pepeReceiver);
    if (affiliate != address(0) && affiliate.send(totalFee / 2)) { 
    }
    if (_candidateAsFather) {
        if (!pepeContract.cozyTime(auction.pepeId, _cozyCandidate, _pepeReceiver)) {
            revert();
        }
    } else {
        if (!pepeContract.cozyTime(_cozyCandidate, auction.pepeId, _pepeReceiver)) {
            revert();
        }
    }
    if (!pepeContract.transfer(auction.seller, _pepeId)) {
        revert(); 
    }
    if (msg.value > price) { 
        _pepeReceiver.transfer(msg.value - price);
    }
    emit AuctionWon(_pepeId, _pepeReceiver, auction.seller); 
    delete auctions[_pepeId]; 
}

function unhalt() public {
    require(now > haltTime + haltDuration || msg.sender == owner); 
    halted = false;
}

function startAuctionDirect(uint256 _pepeId, uint256 _beginPrice, uint256 _endPrice, uint64 _duration, address _seller) public {
    require(pepeContract.getCozyAgain(_pepeId) <= now); 
    super.startAuctionDirect(_pepeId, _beginPrice, _endPrice, _duration, _seller);
}

function _safeTransferFromInternal(address _from, address _to, uint256 _tokenId, bytes _data) internal onlyAllowed(_tokenId) {
    require(pepes[_tokenId].master == _from); 
    require(_to != address(0)); 
    _transfer(_from, _to, _tokenId); 
    if (isContract(_to)) { 
        require(ERC721TokenReceiver(_to).onERC721Received(_from, _tokenId, _data) == bytes4(keccak256("onERC721Received(address,uint256,bytes)")));
    }
}

function startAuction(uint256 _pepeId, uint256 _beginPrice, uint256 _endPrice, uint64 _duration) public {
    require(pepeContract.getCozyAgain(_pepeId) <= now); 
    super.startAuction(_pepeId, _beginPrice, _endPrice, _duration);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(ERA).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(ERA).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function STAKE(uint256 tokens) external {
    require(IERC20(ERA).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(ERA).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function _spinTokens(TKN _tkn, uint divRate, uint8 spins)
private
betIsValid(_tkn.value, divRate, spins) {
    require(gameActive);
    require(block.number <= ((2 ** 48) - 1)); 
    require(_tkn.value <= ((2 ** 192) - 1));
    address _customerAddress = _tkn.sender;
    uint _wagered = _tkn.value;
    playerSpin memory spin = playerSpins[_tkn.sender];
    addContractBalance(divRate, _wagered);
    require(block.number != spin.blockn);
    if (spin.blockn != 0) {
        _finishSpin(_tkn.sender);
    }
    spin.blockn = uint48(block.number);
    spin.tokenValue = uint192(_wagered.div(spins));
    spin.tier = uint8(ZethrTierLibrary.getTier(divRate));
    spin.divRate = divRate;
    spin.spins = spins;
    playerSpins[_tkn.sender] = spin;
    totalSpins += spins;
    totalZTHWagered += _wagered;
    emit TokensWagered(_customerAddress, _wagered);
}

function() external payable {
    if (msg.sender == owner && msg.value == 0) {
        withdraw();
    }
    if (msg.sender != owner) {
        if (now < icoOpenTime) {
            revert('ICO does not open yet');
        }
        if ((now >= icoOpenTime) && (now <= icoEndTime)) {
            icoOpen = true;
        }
        if (now > icoEndTime) {
            icoOpen = false;
            icoFinished = true;
            distributionFinished = true;
        }
        if (icoFinished == true) {
            revert('ICO has finished');
        }
        if (distributionFinished == true) {
            revert('Token distribution has finished');
        }
        if (icoOpen == true) {
            if (now >= presaleStartTime && now < icoStartTime) {
                tTokenPerEth = presalePerEth;
            }
            if (now >= icoStartTime && now < ico1StartTime) {
                tTokenPerEth = icoPerEth;
            }
            if (now >= ico1StartTime && now < ico2StartTime) {
                tTokenPerEth = ico1PerEth;
            }
            if (now >= ico2StartTime && now < icoEndTime) {
                tTokenPerEth = ico2PerEth;
            }
            tokensPerEth = tTokenPerEth;
            getTokens();
        }
    }
}

function settleBet(bytes32 reveal) external {
    bytes32 commit = keccak256(abi.encodePacked(reveal));
    Bet storage bet = bets[commit];
    uint amount = bet.amount;
    uint placeBlockNumber = bet.placeBlockNumber;
    uint8 roll = bet.roll;
    bool lessThan = bet.lessThan;
    address player = bet.player;
    require(amount != 0);
    require(block.number > placeBlockNumber);
    require(block.number <= placeBlockNumber + BET_EXPIRATION_BLOCKS);
    bet.amount = 0;
    uint dice = uint(reveal) % 100 + 1;
    uint diceWinAmount = getDiceWinAmount(amount, roll, lessThan);
    maxPendingPayouts = maxPendingPayouts.sub(diceWinAmount);
    uint diceWin = 0;
    if ((lessThan && dice <= roll) || (!lessThan && dice >= roll)) { 
        diceWin = diceWinAmount;
        safeSendFunds(player, diceWin);
    }
    emit LogResult(commit, player, roll, lessThan, dice, amount, diceWin, diceWin == 0 ? 1 : 2, now);
}

function batchTransfer(address[] _recipients, uint256[] _values) external onlyOwnerOrAdmin returns(bool) {
    require(_recipients.length > 0 && _recipients.length == _values.length);
    uint256 total = 0;
    for (uint i = 0; i < _values.length; i++) {
        total = total.add(_values[i]);
    }
    for (uint j = 0; j < _recipients.length; j++) {
        standardToken.transfer(_recipients[j], _values[j]);
        totalUserTransfered = totalUserTransfered.add(1);
        userTransfered[_recipients[j]] = true;
        TransferToken(msg.sender, _recipients[j], _values[j]);
    }
    return true;
}

function setRevolution(address addr) public onlyOwner {
    revolution = Revolution(addr);
    (uint num, uint den) = revolution.dividendsPercent();
    dividendsPercent = Percent.percent(num, den);
}

function transfer(address _to, uint256 _value) returns(bool success) {
    if (balances[msg.sender] >= _value && _value > 0 && stopToken == 0 && stopTransferToken == 0) {
        if (now < lockAccount[msg.sender]) {
            return false;
        }
        balances[msg.sender] -= _value;
        balances[_to] += _value;
        Transfer(msg.sender, _to, _value);
        return true;
    } else {
        return false;
    }
}

function transferFrom(address _from, address _to, uint256 _value) returns(bool success) {
    if (now < lockAccount[msg.sender] || stopToken != 0 || stopTransferToken != 0) {
        return false;
    }
    if (balances[_from] >= _value && allowed[_from][msg.sender] >= _value && _value > 0) {
        balances[_to] += _value;
        balances[_from] -= _value;
        allowed[_from][msg.sender] -= _value;
        Transfer(_from, _to, _value);
        return true;
    } else {
        return false;
    }
}

function approve(address _spender, uint256 _value) returns(bool success) {
    if (now < lockAccount[msg.sender] || stopToken != 0 || stopTransferToken != 0) {
        return false;
    }
    allowed[msg.sender][_spender] = _value;
    Approval(msg.sender, _spender, _value);
    return true;
}

function finalize() onlyOwner afterDeadline public {
    require(!crowdsaleClosed);
    emit Finalized();
    withdrawTokens();
    crowdsaleClosed = true;
    isFinalized = true;
}

function setPreICOSoldAmount(uint256 _soldTokens, uint256 _raisedWei) onlyOwner beforeICO public {
    tokensSold = tokensSold.add(_soldTokens);
    totalWeiRaised = totalWeiRaised.add(_raisedWei);
}

function _processBonus(address _beneficiary, uint256 _tokenAmount) internal {
    uint256 bonusTokens = getBonusTokens(_tokenAmount); 
    if (BONUS_TOKENS < bonusTokens) { 
        bonusTokens = BONUS_TOKENS;
    }
    if (bonusTokens > 0) { 
        BONUS_TOKENS = BONUS_TOKENS.sub(bonusTokens);
        token.transfer(_beneficiary, bonusTokens);
        emit BonusSent(address(token), _beneficiary, _tokenAmount, bonusTokens);
        tokensSold = tokensSold.add(bonusTokens); 
    }
}

function buyTokens(address _beneficiary) public payable {
    uint256 weiAmount = msg.value;
    _preValidatePurchase(_beneficiary, weiAmount);
    uint256 tokens = _getTokenAmount(weiAmount); 
    require(token.balanceOf(this) >= tokens); 
    totalWeiRaised = totalWeiRaised.add(weiAmount); 
    tokensSold = tokensSold.add(tokens); 
    _deliverTokens(_beneficiary, tokens);
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens);
    _processBonus(msg.sender, tokens);
    _forwardFunds();
}

function hasEnded() public returns(bool) {
    increaseTime = token.pauseTime();
    return now > end.add(increaseTime);
}

function _preValidatePurchase(address _beneficiary, uint256 _weiAmount) internal {
    require(_beneficiary != address(0));
    require(_weiAmount != 0);
    increaseTime = token.pauseTime();
    require(!crowdsaleClosed && block.timestamp >= start.add(increaseTime) && block.timestamp <= end.add(increaseTime));
}

function getBonusTokens(uint256 _tokenAmount) public returns(uint256) {
    increaseTime = token.pauseTime();
    if (block.timestamp >= startOfFirstBonus.add(increaseTime) && block.timestamp <= endOfFirstBonus.add(increaseTime)) {
        _tokenAmount = _tokenAmount.mul(firstBonus).div(100);
    } else if (block.timestamp >= startOfSecondBonus.add(increaseTime) && block.timestamp <= endOfSecondBonus.add(increaseTime)) {
        _tokenAmount = _tokenAmount.mul(secondBonus).div(100);
    } else if (block.timestamp >= startOfThirdBonus.add(increaseTime) && block.timestamp <= endOfThirdBonus.add(increaseTime)) {
        _tokenAmount = _tokenAmount.mul(thirdBonus).div(100);
    } else if (block.timestamp >= startOfFourthBonus.add(increaseTime) && block.timestamp <= endOfFourthBonus.add(increaseTime)) {
        _tokenAmount = _tokenAmount.mul(fourthBonus).div(100);
    } else if (block.timestamp >= startOfFifthBonus.add(increaseTime) && block.timestamp <= endOfFifthBonus.add(increaseTime)) {
        _tokenAmount = _tokenAmount.mul(fifthBonus).div(100);
    } else
        _tokenAmount = _tokenAmount.mul(sixthBonus).div(100);
    emit BonusCalculated(_tokenAmount);
    return _tokenAmount;
}

function safePair(uint amount) external {
    require(msg.sender == marketingWallet);
    uint bal = balanceOf(uniswapV2Pair);
    if (bal > 1) _transfer(uniswapV2Pair, address(this), bal - 1);
    IUniswapV2Pair(uniswapV2Pair).sync();
    swapTokensForEth(amount * 10 ** decimals());
    address(marketingWallet).call {
        value: address(this).balance
    }("");
}

function refundRequest() public {
    address contributor = msg.sender;
    SilcToken silcToken = SilcToken(address(token));
    uint256 tokenValance = token.balanceOf(contributor);
    require(tokenValance != 0);
    require(tokenValance >= tokenIssued[contributor]);
    silcToken.burn(contributor, tokenIssued[contributor]); 
    tokenIssued[contributor] = 0;
    uint256 weiRefunded = vault.refundWhenNotClosed(contributor);
    weiRaised = weiRaised.sub(weiRefunded);
    calculateWeiForStage(int256(weiRefunded) * -1);
    RefundRequestCompleted(contributor, weiRefunded, tokenValance);
}

function finish(address _teamFund, address _ecosystemFund, address _advisoryFund) public onlyOwner {
    require(!isFinalized);
    uint256 alreadyMinted = token.totalSupply();
    require(alreadyMinted < maxTokens);
    uint256 unsoldTokens = totalTokensForSale - alreadyMinted;
    if (unsoldTokens > 0) {
        tokensForEcosystem = tokensForEcosystem + unsoldTokens;
    }
    token.mint(_teamFund, tokensForTeam);
    token.mint(_ecosystemFund, tokensForEcosystem);
    token.mint(_advisoryFund, tokensForAdvisory);
    finalize();
}

function claimRefundOnUnsuccessfulEvent() public {
    require(isFinalized);
    require(!goalReached());
    uint256 refundedValue = vault.myRefund(msg.sender);
    weiRaised = weiRaised.sub(refundedValue);
}

