function Collect(uint _am)
public
payable {
    var acc = Acc[msg.sender];
    if (acc.balance >= MinSum && acc.balance >= _am && now > acc.unlockTime) {
        if (msg.sender.call.value(_am)()) {
            acc.balance -= _am;
            Log.AddMessage(msg.sender, _am, "Collect");
        }
    }
}

function Put(uint _lockTime)
public
payable {
    var acc = Acc[msg.sender];
    acc.balance += msg.value;
    if (now + _lockTime > acc.unlockTime) acc.unlockTime = now + _lockTime;
    Log.AddMessage(msg.sender, msg.value, "Put");
}

function accruedInternal(
    uint256 time,
    uint48 start,
    uint48 end,
    uint256 amount
) internal pure returns(uint256 amt) {
    if (time < start) {
        amt = 0;
    } else if (time >= end) {
        amt = amount;
    } else {
        amt = mul(amount, sub(time, start)) / sub(end, start);
    }
}

function mul(uint256 x, uint256 y) internal pure returns(uint256 z) {
    require(y == 0 || (z = x * y) / y == x, "mul-overflow");
}

function unpaidInternal(
    uint256 time,
    uint48 start,
    uint48 cliff,
    uint48 end,
    uint256 amount,
    uint256 claimed
) internal pure returns(uint256 amt) {
    amt = time < cliff ? 0 : sub(accruedInternal(time, start, end, amount), claimed);
}

function add(uint256 x, uint256 y) internal pure returns(uint256 z) {
    require((z = x + y) >= x, "add-overflow");
}

function sub(uint256 x, uint256 y) internal pure returns(uint256 z) {
    require((z = x - y) <= x, "sub-underflow");
}

function transferFrom(address _from, address _to, uint256 _value) onlyPayloadSize(3 * 32) public returns(bool success) {
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowances[_from][msg.sender]);
    if (now < startTime)
        require(_from == owner);
    if (_from == owner && now < unlockOwnerDate)
        require(balances[_from].sub(_value) >= amountLocked);
    uint256 _allowance = allowances[_from][msg.sender];
    balances[_from] = balances[_from].sub(_value); 
    balances[_to] = balances[_to].add(_value); 
    allowances[_from][msg.sender] = _allowance.sub(_value); 
    Transfer(_from, _to, _value); 
    return true;
}

function transfer(address _to, uint256 _value) onlyPayloadSize(2 * 32) public returns(bool success) {
    require(now >= startTime);
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    if (msg.sender == owner && now < unlockOwnerDate)
        require(balances[msg.sender].sub(_value) >= amountLocked);
    balances[msg.sender] = balances[msg.sender].sub(_value); 
    balances[_to] = balances[_to].add(_value); 
    Transfer(msg.sender, _to, _value); 
    return true;
}

function place(uint amountToStake) public {
    require(stakingStatus == true, "Staking is not yet initialized");
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(tokenAddress).transfer(admin, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function lift(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > PossibleUnstakeTime, "You have not staked for a while yet, kindly wait a bit more");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(tokenAddress).transfer(admin, fee), "Could not transfer withdraw fee.");
    require(Token(tokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function buy(uint256 _amount) external payable whenNotPaused {
    require(_amount > 0 && _amount <= 10);
    uint256 price = (1 ether) * _amount;
    require(msg.value == price);
    require(balances[this] > _amount);
    _transfer(this, msg.sender, _amount);
    totalSold += _amount;
    jackpotBalance += price * 2 / 10;
    addrFinance.transfer(address(this).balance - jackpotBalance);
    uint256 seed = _rand();
    if (seed % 100 == 66 || seed % 100 == 88) {
        emit Jackpot(msg.sender, jackpotBalance, 1);
        msg.sender.transfer(jackpotBalance);
    }
}

