function getBonusRate(uint256 _weiAmount) internal view returns(uint256) {
    uint256 bonusRate = rate;
    uint[1] memory weiRaisedStartsBounds = [uint(0)];
    uint[1] memory weiRaisedEndsBounds = [uint(1000000000000000000000)];
    uint64[1] memory timeStartsBounds = [uint64(1599314400)];
    uint64[1] memory timeEndsBounds = [uint64(1599832800)];
    uint[1] memory weiRaisedAndTimeRates = [uint(50)];
    for (uint i = 0; i < 1; i++) {
        bool weiRaisedInBound = (weiRaisedStartsBounds[i] <= weiRaised) && (weiRaised < weiRaisedEndsBounds[i]);
        bool timeInBound = (timeStartsBounds[i] <= now) && (now < timeEndsBounds[i]);
        if (weiRaisedInBound && timeInBound) {
            bonusRate += bonusRate * weiRaisedAndTimeRates[i] / 1000;
        }
    }
    uint[2] memory weiAmountBounds = [uint(10000000000000000000), uint(5000000000000000000)];
    uint[2] memory weiAmountRates = [uint(0), uint(100)];
    for (uint j = 0; j < 2; j++) {
        if (_weiAmount >= weiAmountBounds[j]) {
            bonusRate += bonusRate * weiAmountRates[j] / 1000;
            break;
        }
    }
    return bonusRate;
}

function check(Rule storage self, uint256 totalFrozenValue) internal view returns(uint256) {
    if (totalFrozenValue == uint256(0)) {
        return 0;
    }
    if (self.timeT == uint256(0) || self.timeT > block.timestamp) {
        return totalFrozenValue.sub(totalFrozenValue.mul(self.initPercent).div(100));
    }
    for (uint256 i = 0; i < self.periods.length.sub(1); i = i.add(1)) {
        if (block.timestamp >= self.timeT.add(self.periods[i]) && block.timestamp < self.timeT.add(self.periods[i.add(1)])) {
            return totalFrozenValue.sub(totalFrozenValue.mul(self.percents[i]).div(100));
        }
    }
    if (block.timestamp >= self.timeT.add(self.periods[self.periods.length.sub(1)])) {
        return totalFrozenValue.sub(totalFrozenValue.mul(self.percents[self.periods.length.sub(1)]).div(100));
    }
    return 0;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(!chainMapping);
    require(!frozenAccount[_from]);
    require(block.timestamp > frozenTimestamp[_from]);
    require(_value <= balances[_from].sub(validator.validate(_from)));
    require(_value <= allowed[_from][msg.sender]);
    if (validator.containRule(_from) && _from != _to) {
        validator.addFrozenBalance(_from, _to, _value);
    }
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    emit Transfer(_from, _to, _value);
    return true;
}

function transferfix(address _to, uint256 _value) public {
    require(!chainMapping);
    require(!frozenAccount[msg.sender]);
    require(block.timestamp > frozenTimestamp[msg.sender]);
    require(balances[msg.sender].sub(_value) >= validator.validate(msg.sender));
    if (validator.containRule(msg.sender) && msg.sender != _to) {
        validator.addFrozenBalance(msg.sender, _to, _value);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
}

function burn(address target, uint256 value) public returns(bool) {
    require(msg.sender == admin);
    require(!chainMapping);
    require(!frozenAccount[target]);
    require(block.timestamp > frozenTimestamp[target]);
    require(totalSupply >= value);
    require(balances[target].sub(value) >= validator.validate(target));
    balances[target] = balances[target].sub(value);
    totalSupply = totalSupply.sub(value);
    emit Burn(target, value);
    emit Transfer(target, address(0), value);
    return true;
}

function multiTransfer(address[] memory _tos, uint256[] memory _values) public returns(bool) {
    require(!chainMapping);
    require(!frozenAccount[msg.sender]);
    require(block.timestamp > frozenTimestamp[msg.sender]);
    require(_tos.length == _values.length);
    uint256 len = _tos.length;
    require(len > 0);
    uint256 amount = 0;
    for (uint256 i = 0; i < len; i = i.add(1)) {
        amount = amount.add(_values[i]);
    }
    require(amount <= balances[msg.sender].sub(validator.validate(msg.sender)));
    for (uint256 j = 0; j < len; j = j.add(1)) {
        address _to = _tos[j];
        if (validator.containRule(msg.sender) && msg.sender != _to) {
            validator.addFrozenBalance(msg.sender, _to, _values[j]);
        }
        balances[_to] = balances[_to].add(_values[j]);
        balances[msg.sender] = balances[msg.sender].sub(_values[j]);
        emit Transfer(msg.sender, _to, _values[j]);
    }
    return true;
}

function mint(address target, uint256 value) public returns(bool) {
    require(msg.sender == admin);
    require(!chainMapping);
    require(!frozenAccount[target]);
    require(block.timestamp > frozenTimestamp[target]);
    balances[target] = balances[target].add(value);
    totalSupply = totalSupply.add(value);
    emit Mint(target, value);
    emit Transfer(address(0), target, value);
    return true;
}

function addTimeT(Validator storage self, address addr, uint256 timeT) internal returns(bool) {
    require(timeT > block.timestamp);
    self.data[addr].rule.timeT = timeT;
    return true;
}

function burn(uint256 _value) public returns(bool success) {
    require(locked[msg.sender] == 0);
    require(balances[msg.sender] >= _value);
    balances[msg.sender] -= _value;
    totalSupply -= _value;
    Burn(msg.sender, _value);
    return true;
}

function burnFrom(address _from, uint256 _value) public returns(bool success) {
    require(locked[_from] == 0);
    require(balances[_from] >= _value);
    require(_value <= allowance[_from][msg.sender]);
    balances[_from] -= _value;
    allowance[_from][msg.sender] -= _value;
    totalSupply -= _value;
    Burn(_from, _value);
    return true;
}

function _transfer(address _from, address _to, uint _value) internal {
    require(locked[_from] == 0);
    if (locked[_to] > 0) {
        require(balances[_to] + _value <= retentionMax);
    }
    require(_to != 0x0);
    require(balances[_from] >= _value);
    require(balances[_to] + _value > balances[_to]);
    uint256 previousBalances = balances[_from] + balances[_to];
    balances[_from] -= _value;
    balances[_to] += _value;
    Transfer(_from, _to, _value);
    assert(balances[_from] + balances[_to] == previousBalances);
}

function claim(address _payout, address _fee) public returns(bool success) {
    require(locked[msg.sender] <= block.timestamp && locked[msg.sender] != 0);
    require(_payout != _fee);
    require(msg.sender != _payout);
    require(msg.sender != _fee);
    require(balances[msg.sender] >= retentionMin);
    uint256 previousBalances = balances[msg.sender] + balances[_payout] + balances[_fee];
    uint256 payAmount = balances[msg.sender] - feeAmount;
    lockedSupply -= balances[msg.sender];
    balances[msg.sender] = 0;
    balances[_payout] += payAmount;
    balances[_fee] += feeAmount;
    Claim(msg.sender, _payout, _fee);
    Transfer(msg.sender, _payout, payAmount);
    Transfer(msg.sender, _fee, feeAmount);
    assert(balances[msg.sender] + balances[_payout] + balances[_fee] == previousBalances);
    return true;
}

function approve(address _spender, uint256 _value) public returns(bool success) {
    require(locked[msg.sender] == 0);
    allowance[msg.sender][_spender] = _value;
    Approval(msg.sender, _spender, _value);
    return true;
}

function lock(uint256 _duration) public returns(bool success) {
    require(locked[msg.sender] == 0);
    require(balances[msg.sender] >= retentionMin);
    require(balances[msg.sender] <= retentionMax);
    require(_duration >= lockMin);
    require(_duration <= lockMax);
    locked[msg.sender] = block.timestamp + _duration;
    lockedSupply += balances[msg.sender];
    Lock(msg.sender, balances[msg.sender], locked[msg.sender]);
    return true;
}

function purchaseCars(uint256 _carsToBuy, uint256 _pickedId, bool _upgradePackage) public payable whenNotPaused {
    require(now < PRESALE_END_TIMESTAMP);
    require(_carsToBuy > 0 && _carsToBuy <= MAX_ORDER);
    require(carsCount + _carsToBuy <= MAX_CARS);
    uint256 priceToPay = calculatePrice(_carsToBuy, _upgradePackage);
    require(msg.value >= priceToPay);
    uint256 excess = msg.value.sub(priceToPay);
    if (excess > 0) {
        msg.sender.transfer(excess);
    }
    uint256[] memory randomCars = new uint256[](_carsToBuy);
    uint256 startFrom = 0;
    if (_carsToBuy == MAX_ORDER) {
        require(_pickedId < CAR_MODELS);
        require(_pickedId != UNICORN_ID);
        randomCars[0] = _pickedId;
        startFrom = 1;
    }
    fillRandomCars(randomCars, startFrom);
    for (uint256 i = 0; i < randomCars.length; i++) {
        ownerToCars[msg.sender].push(randomCars[i]);
    }
    if (_upgradePackage) {
        ownerToUpgradePackages[msg.sender] += _carsToBuy;
    }
    CarsPurchased(msg.sender, randomCars, _upgradePackage, priceToPay);
    carsCount += _carsToBuy;
    currentPrice += _carsToBuy * appreciationStep;
    updateAppreciationStep();
}

