public {
    require(now <= _endTime);
    tokenOWL = _tokenOWL;
    tokenGNO = _tokenGNO;
    endTime = _endTime;
}

function transferLockedBalance(address _beneficiary) public {
    require(_beneficiary != address(0));
    require(now >= lockedTill);
    require(lockedTokens > 0);
    require(approved[_beneficiary]);
    require(lockedBalances[_beneficiary] > 0);
    uint256 _lockedTokensToTransfer = lockedBalances[_beneficiary];
    token.transfer(_beneficiary, _lockedTokensToTransfer);
    distributedBalances[_beneficiary] = distributedBalances[_beneficiary].add(_lockedTokensToTransfer);
    lockedTokens = lockedTokens.sub(_lockedTokensToTransfer);
    lockedBalances[_beneficiary] = 0;
    distributedTokens = distributedTokens.add(_lockedTokensToTransfer);
}

function transferApprovedBalance(address _beneficiary) public {
    require(_beneficiary != address(0));
    require(now >= approvedTill);
    require(allocatedTokens > 0);
    require(approved[_beneficiary]);
    require(allocatedBalances[_beneficiary] > 0);
    uint256 _approvedTokensToTransfer = allocatedBalances[_beneficiary];
    token.transfer(_beneficiary, _approvedTokensToTransfer);
    distributedBalances[_beneficiary] = distributedBalances[_beneficiary].add(_approvedTokensToTransfer);
    allocatedTokens = allocatedTokens.sub(_approvedTokensToTransfer);
    allocatedBalances[_beneficiary] = 0;
    distributedTokens = distributedTokens.add(_approvedTokensToTransfer);
}

function buyTokens(address _beneficiary) public payable whenNotPaused {
    uint256 amountPaid = msg.value;
    _preValidatePurchase(_beneficiary, amountPaid);
    uint256 tokens = 0;
    uint256 bonusTokens = 0;
    uint256 fullTokens = 0;
    if (processedTokens < capLevels[1]) {
        tokens = _getTokensAmount(amountPaid, 1);
        bonusTokens = _getBonusAmount(tokens, 1);
        fullTokens = tokens.add(bonusTokens);
        if (processedTokens.add(fullTokens) > capLevels[1]) {
            tokens = _calculateExcessTokens(amountPaid, 1);
            bonusTokens = _calculateExcessBonus(tokens, 1);
            setCurrentRound(2);
        }
    } else if (processedTokens >= capLevels[1] && processedTokens < capLevels[2]) {
        tokens = _getTokensAmount(amountPaid, 2);
        bonusTokens = _getBonusAmount(tokens, 2);
        fullTokens = tokens.add(bonusTokens);
        if (processedTokens.add(fullTokens) > capLevels[2]) {
            tokens = _calculateExcessTokens(amountPaid, 2);
            bonusTokens = _calculateExcessBonus(tokens, 2);
            setCurrentRound(3);
        }
    } else if (processedTokens >= capLevels[2] && processedTokens < capLevels[3]) {
        tokens = _getTokensAmount(amountPaid, 3);
        bonusTokens = _getBonusAmount(tokens, 3);
        fullTokens = tokens.add(bonusTokens);
        if (processedTokens.add(fullTokens) > capLevels[3]) {
            tokens = _calculateExcessTokens(amountPaid, 3);
            bonusTokens = _calculateExcessBonus(tokens, 3);
            setCurrentRound(4);
        }
    } else if (processedTokens >= capLevels[3] && processedTokens < capLevels[4]) {
        tokens = _getTokensAmount(amountPaid, 4);
        bonusTokens = _getBonusAmount(tokens, 4);
        fullTokens = tokens.add(bonusTokens);
        if (processedTokens.add(fullTokens) > capLevels[4]) {
            tokens = _calculateExcessTokens(amountPaid, 4);
            bonusTokens = _calculateExcessBonus(tokens, 4);
            setCurrentRound(5);
        }
    } else if (processedTokens >= capLevels[4] && processedTokens < capLevels[5]) {
        tokens = _getTokensAmount(amountPaid, 5);
        bonusTokens = _getBonusAmount(tokens, 5);
        fullTokens = tokens.add(bonusTokens);
        if (processedTokens.add(fullTokens) > capLevels[5]) {
            tokens = _calculateExcessTokens(amountPaid, 5);
            bonusTokens = 0;
            setCurrentRound(6);
        }
    } else if (processedTokens >= capLevels[5]) {
        tokens = _getTokensAmount(amountPaid, 6);
    }
    weiRaised = weiRaised.add(amountPaid);
    fullTokens = tokens.add(bonusTokens);
    soldTokens = soldTokens.add(fullTokens);
    processedTokens = processedTokens.add(fullTokens);
    tokensBought[msg.sender] = tokensBought[msg.sender].add(tokens);
    crowdsaleBalances[msg.sender] = crowdsaleBalances[msg.sender].add(amountPaid);
    bonusBalances[msg.sender] = bonusBalances[msg.sender].add(bonusTokens);
    uint256 totalTokens = tokens.add(bonusTokens);
    _processPurchase(_beneficiary, totalTokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        amountPaid,
        totalTokens
    );
}

function hasStarted() public constant returns(bool) {
    return now > startTime;
}

function _preValidatePurchase(address _beneficiary, uint256 _weiAmount) view internal {
    require(_beneficiary != address(0));
    require(_weiAmount != 0);
    bool withinPeriod = hasStarted() && hasNotEnded();
    bool nonZeroPurchase = msg.value > 0;
    bool withinTokenLimit = processedTokens < maxTokensRaised;
    bool minimumPurchase = msg.value >= minPurchase;
    require(withinPeriod);
    require(nonZeroPurchase);
    require(withinTokenLimit);
    require(minimumPurchase);
}

function burnUnsold() public onlyOwner {
    require(now > lockedTill);
    require(address(this).balance == 0);
    require(lockedTokens == 0);
    require(allocatedTokens == 0);
    require(unSoldTokens > 0);
    selfdestruct(owner);
}

function hasNotEnded() public constant returns(bool) {
    return now < endTime && processedTokens < maxTokensRaised;
}

function buyTokens() internal {
    uint256 amount = msg.value;
    bool success = false;
    if (uint(period) == 1) {
        tokens = amount.mul(ratePresale);
    } else if (uint(period) == 3) {
        tokens = amount.mul(rateThirdWeek);
    } else if (uint(period) == 4) {
        tokens = amount.mul(rateSecondWeek);
    } else if (uint(period) == 5) {
        tokens = amount.mul(rateFirstWeek);
    } else {
        tokens = amount.mul(rate);
    }
    success = token.transfer(msg.sender, tokens);
    balance = balance.add(tokens);
    require(success);
    wallet.transfer(msg.value);
}

function createSwap(bytes20 _secretHash, address _participantAddress, uint256 _value, address _token) public {
    require(_value > 0);
    require(swaps[msg.sender][_participantAddress].balance == uint256(0));
    require(ERC20(_token).transferFrom(msg.sender, this, _value));
    swaps[msg.sender][_participantAddress] = Swap(
        _token,
        bytes32(0),
        _secretHash,
        now,
        _value
    );
    CreateSwap(now);
}

function refund(address _participantAddress) public {
    Swap memory swap = swaps[msg.sender][_participantAddress];
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) < now);
    ERC20(swap.token).transfer(msg.sender, swap.balance);
    clean(msg.sender, _participantAddress);
    Refund();
}

function withdraw(bytes32 _secret, address _ownerAddress) public {
    Swap memory swap = swaps[_ownerAddress][msg.sender];
    require(swap.secretHash == ripemd160(_secret));
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) > now);
    ERC20(swap.token).transfer(msg.sender, swap.balance);
    swaps[_ownerAddress][msg.sender].balance = 0;
    swaps[_ownerAddress][msg.sender].secret = _secret;
    Withdraw(_secret, msg.sender, swap.balance);
}

function claimETH() onlyAdmin(2) public {
    require(creator.send(address(this).balance));
    emit LogBeneficiaryPaid(creator);
}

function finish() onlyAdmin(2) public { 
    if (state != State.Successful) {
        state = State.Successful;
        completedAt = now;
    }
    uint256 remanent = tokenReward.balanceOf(this);
    require(creator.send(address(this).balance));
    tokenReward.transfer(creator, remanent);
    emit LogBeneficiaryPaid(creator);
    emit LogContributorsPayout(creator, remanent);
}

function calculateAndMintTokens(address to, uint weiInvested) internal {
    uint stageIndex = currentStage();
    Stage storage stage = stages[stageIndex];
    uint tokens = weiInvested.mul(stage.price);
    if (investedAmountOf[msg.sender] == 0) {
        contributors[uniqueContributors] = msg.sender;
        uniqueContributors += 1;
    }
    investedAmountOf[msg.sender] = investedAmountOf[msg.sender].add(weiInvested);
    tokenAmountOf[msg.sender] = tokenAmountOf[msg.sender].add(tokens);
    mintTokens(to, tokens);
    totalInvested = totalInvested.add(weiInvested);
    stage.invested = stage.invested.add(weiInvested);
    if (stage.invested >= stage.hardcap) {
        stage.closed = now;
    }
}

function createTokens() public whenNotPaused payable {
    require(msg.value >= minInvestment);
    uint masterValue = msg.value.mul(percentRate.sub(slaveWalletPercent)).div(percentRate);
    uint slaveValue = msg.value.sub(masterValue);
    masterWallet.transfer(masterValue);
    slaveWallet.transfer(slaveValue);
    calculateAndMintTokens(msg.sender, msg.value);
    TokenPurchased(msg.sender, msg.value, now);
}

function refund() public saleIsUnsuccessful {
    uint value = investedAmountOf[msg.sender];
    investedAmountOf[msg.sender] = 0;
    msg.sender.transfer(value);
    InvestmentReturned(msg.sender, value, now);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(locked[_from] < now);
    return super.transferFrom(_from, _to, _value);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(locked[msg.sender] < now);
    return super.transfer(_to, _value);
}

function() external onlyIfWhitelisted payable {
    require(now >= start && now < lastSaleDate());
    createTokens();
}

function lock(address addr, uint periodInDays) public {
    require(locked[addr] < now && (msg.sender == saleAgent || msg.sender == addr));
    locked[addr] = now + periodInDays * 1 days;
}

function unlockFor(address _owner) public {
    require(now >= unlockPart1);
    uint256 share = shares[_owner].proportion;
    if (now < unlockPart2) {
        share = share.mul(shares[_owner].forPart) / 100;
        shares[_owner].forPart = 0;
    }
    if (share > 0) {
        uint256 unlockedToken = token.balanceOf(this).mul(share).div(totalShare);
        shares[_owner].proportion = shares[_owner].proportion.sub(share);
        totalShare = totalShare.sub(share);
        token.transfer(_owner, unlockedToken);
    }
}

function initialize() public {
    onlyAdmin(false);
    require(!isInitialized);
    begin();
    require(now <= startTime);
    initialization();
    emit Initialized();
    isInitialized = true;
    renewal = 0;
    canFirstMint = false;
}

function setup(uint256 _startTime, uint256 _endTime, uint256 _softCap, uint256 _hardCap,
    uint256 _rate, uint256 _exchange,
    uint256 _maxAllProfit, uint256 _overLimit, uint256 _minPay,
    uint256[] _durationTB, uint256[] _percentTB, uint256[] _valueVB, uint256[] _percentVB, uint256[] _freezeTimeVB) public {
    onlyAdmin(false);
    require(!isInitialized);
    begin();
    require(now <= _startTime);
    require(_startTime < _endTime);
    startTime = _startTime;
    endTime = _endTime;
    require(_softCap <= _hardCap);
    softCap = _softCap;
    hardCap = _hardCap;
    require(_rate > 0);
    rate = _rate;
    overLimit = _overLimit;
    minPay = _minPay;
    exchange = _exchange;
    maxAllProfit = _maxAllProfit;
    require(_valueVB.length == _percentVB.length && _valueVB.length == _freezeTimeVB.length);
    bonuses.length = _valueVB.length;
    for (uint256 i = 0; i < _valueVB.length; i++) {
        bonuses[i] = Bonus(_valueVB[i], _percentVB[i], _freezeTimeVB[i]);
    }
    require(_percentTB.length == _durationTB.length);
    profits.length = _percentTB.length;
    for (i = 0; i < _percentTB.length; i++) {
        profits[i] = Profit(_percentTB[i], _durationTB[i]);
    }
}

function finalization() internal {
    if (goalReached()) {
        if (address(vault) != 0x0) {
            vault.close(wallets[uint8(Roles.beneficiary)], wallets[uint8(Roles.fees)], ethWeiRaised.mul(7).div(100)); 
        }
        if (tokenReserved > 0) {
            token.mint(wallets[uint8(Roles.accountant)], tokenReserved);
            tokenReserved = 0;
        }
        if (TokenSale == TokenSaleType.round1) {
            isInitialized = false;
            isFinalized = false;
            TokenSale = TokenSaleType.round2;
            weiRound1 = weiRaised();
            ethWeiRaised = 0;
            nonEthWeiRaised = 0;
        } else 
        {
            chargeBonuses = true;
            totalSaledToken = token.totalSupply();
        }
    } else if (address(vault) != 0x0) 
    {
        vault.enableRefunds();
    }
}

function refund(address investor) public {
    require(state == State.Refunding);
    uint256 depositedValue = deposited[round][investor];
    require(depositedValue > 0);
    deposited[round][investor] = 0;
    investor.transfer(depositedValue);
    emit Refunded(investor, depositedValue);
}

function distructVault() public {
    require(address(vault) != 0x0);
    if (wallets[uint8(Roles.beneficiary)] == msg.sender && (now > startTime.add(FORCED_REFUND_TIMEOUT1))) {
        vault.del(wallets[uint8(Roles.beneficiary)]);
    }
    if (wallets[uint8(Roles.manager)] == msg.sender && (now > startTime.add(FORCED_REFUND_TIMEOUT2))) {
        vault.del(wallets[uint8(Roles.manager)]);
    }
}

function finalize() public {
    require(wallets[uint8(Roles.manager)] == msg.sender || wallets[uint8(Roles.beneficiary)] == msg.sender || !goalReached());
    require(!isFinalized);
    require(hasEnded() || ((wallets[uint8(Roles.manager)] == msg.sender || wallets[uint8(Roles.beneficiary)] == msg.sender) && goalReached()));
    isFinalized = true;
    finalization();
    emit Finalized();
}

function hasEnded() public view returns(bool) {
    bool timeReached = now > endTime.add(renewal);
    bool capReached = weiRaised() >= hardCap;
    return (timeReached || capReached) && isInitialized;
}

function getProfitPercentForData(uint256 _timeNow) public constant returns(uint256) {
    uint256 allDuration;
    for (uint8 i = 0; i < profits.length; i++) {
        allDuration = allDuration.add(profits[i].duration);
        if (_timeNow < startTime.add(allDuration)) {
            return profits[i].percent;
        }
    }
    return 0;
}

function lokedMint(address _beneficiary, uint256 _value, uint256 _freezeTime) internal {
    if (_freezeTime > 0) {
        uint256 totalBloked = token.freezedTokenOf(_beneficiary).add(_value);
        uint256 pastDateUnfreeze = token.defrostDate(_beneficiary);
        uint256 newDateUnfreeze = _freezeTime.add(now);
        newDateUnfreeze = (pastDateUnfreeze > newDateUnfreeze) ? pastDateUnfreeze : newDateUnfreeze;
        token.freezeTokens(_beneficiary, totalBloked, newDateUnfreeze);
    }
    token.mint(_beneficiary, _value);
}

function prolong(uint256 _duration) external {
    onlyAdmin(false);
    require(now > startTime && now < endTime.add(renewal) && isInitialized);
    renewal = renewal.add(_duration);
    require(renewal <= ROUND_PROLONGATE);
}

function tokenUnpause() external {
    require(wallets[uint8(Roles.manager)] == msg.sender ||
        (now > endTime.add(renewal).add(USER_UNPAUSE_TOKEN_TIMEOUT) && TokenSale == TokenSaleType.round2 && isFinalized && goalReached()));
    token.setPause(false);
}

function paymentsInOtherCurrency(uint256 _token, uint256 _value) public {
    onlyAdmin(true);
    bool withinPeriod = (now >= startTime && now <= endTime.add(renewal));
    bool withinCap = _value.add(ethWeiRaised) <= hardCap.add(overLimit);
    require(withinPeriod && withinCap && isInitialized);
    nonEthWeiRaised = _value;
    tokenReserved = _token;
}

function massBurnTokens(address[] _beneficiary, uint256[] _value) external {
    onlyAdmin(false);
    require(endTime.add(renewal).add(BURN_TOKENS_TIME) > now);
    require(_beneficiary.length == _value.length);
    for (uint16 i; i < _beneficiary.length; i++) {
        token.burn(_beneficiary[i], _value[i]);
    }
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = (now > startTime && now < endTime.add(renewal));
    bool nonZeroPurchase = msg.value >= minPay;
    bool withinCap = msg.value <= hardCap.sub(weiRaised()).add(overLimit);
    return withinPeriod && nonZeroPurchase && withinCap && isInitialized && !isPausedCrowdsale;
}

function begin() internal {
    if (isBegin) return;
    isBegin = true;
    token = creator.createToken();
    if (creator2) {
        vault = creator.createRefund();
    }
    token.setUnpausedWallet(wallets[uint8(Roles.accountant)], true);
    token.setUnpausedWallet(wallets[uint8(Roles.manager)], true);
    token.setUnpausedWallet(wallets[uint8(Roles.bounty)], true);
    token.setUnpausedWallet(wallets[uint8(Roles.company)], true);
    token.setUnpausedWallet(wallets[uint8(Roles.observer)], true);
    bonuses.push(Bonus(71 ether, 30, 30 * 5 days));
    profits.push(Profit(15, 1 days));
    profits.push(Profit(10, 2 days));
    profits.push(Profit(5, 4 days));
}

function setUnpausedWallet(address _wallet, bool mode) public {
    require(owner == msg.sender || msg.sender == Crowdsale(owner).wallets(uint8(Crowdsale.Roles.manager)));
    unpausedWallet[_wallet] = mode;
}

function grantToSetUnpausedWallet(address _to, bool permission) public {
    require(owner == msg.sender || msg.sender == Crowdsale(owner).wallets(uint8(Crowdsale.Roles.manager)));
    grantedToSetUnpausedWallet[_to] = permission;
}

function() payable public {
    require(msg.value >= minInvestment); 
    require(!crowdSalePaused);
    require(!crowdSaleEnded);
    if (currentLevel < 9) { 
        if (levelEndDate < block.timestamp) { 
            currentLevel += 1; 
            levelTokens += baseTokens; 
            levelEndDate = levelEndDate.add(1 * 7 days); 
        }
        prepareSell(msg.sender, msg.value);
    } else {
        if (levelEndDate < block.timestamp) { 
            crowdSaleEnded = true;
            msg.sender.transfer(msg.value);
        } else {
            prepareSell(msg.sender, msg.value);
        }
    }
}

function prepareSell(address _investor, uint256 _amount) private {
    uint256 remaining;
    uint256 pricePerCent;
    uint256 pricePerToken;
    uint256 toSell;
    uint256 amount = _amount;
    uint256 sellInWei;
    address investor = _investor;
    pricePerCent = getUSDPrice();
    pricePerToken = pricePerCent.mul(tokenPrice[currentLevel]);
    toSell = _amount.div(pricePerToken);
    if (toSell < levelTokens) { 
        levelTokens = levelTokens.sub(toSell);
        weiRised = weiRised.add(_amount);
        executeSell(investor, toSell, _amount);
        owner.transfer(_amount);
    } else { 
        while (amount > 0) {
            if (toSell > levelTokens) {
                toSell = levelTokens; 
                sellInWei = toSell.mul(pricePerToken);
                amount = amount.sub(sellInWei);
                if (currentLevel < 9) {
                    currentLevel += 1;
                    levelTokens = baseTokens;
                    if (currentLevel == 9) {
                        baseTokens = tkn.balanceOf(address(this)); 
                    }
                } else {
                    remaining = amount;
                    amount = 0;
                }
            } else {
                sellInWei = amount;
                amount = 0;
            }
            executeSell(investor, toSell, sellInWei);
            weiRised = weiRised.add(sellInWei);
            owner.transfer(amount);
            if (amount > 0) {
                toSell = amount.div(pricePerToken);
            }
            if (remaining > 0) {
                investor.transfer(remaining);
                owner.transfer(address(this).balance);
                crowdSaleEnded = true;
            }
        }
    }
}

function flexPunk(uint256 _id) public payable {
    require(msg.value > .1 ether, "Minimu Flex is .1 ETH.");
    require(ICryptoPunkLike(0xb47e3cd837dDF8e4c57F05d70Ab865de6e193BBB).punkIndexToAddress(
            _id
        ) == msg.sender,
        "Sender has to be the owner of the Punk"
    );
    require(
        msg.value > flex.flexAmount,
        "You Gotta Flex more than the Current Flex"
    );
    require(
        block.timestamp > flex.time,
        "You gotta Wait your turn to flex"
    );
    flex.flexAmount = msg.value;
    flex.flexer = msg.sender;
    flex.id = _id;
    flex.time = block.timestamp + 1 days;
    emit NewFlex(msg.sender, _id, msg.value);
}

function withdrawEther() public {
    if (roundFailedToStart == true) {
        require(msg.sender.send(deals[msg.sender].etherAmount));
    }
    if (msg.sender == operator) {
        require(projectWallet.send(ethForMilestone + postDisputeEth));
        ethForMilestone = 0;
        postDisputeEth = 0;
    }
    if (msg.sender == juryOperator) {
        require(juryOnlineWallet.send(etherAllowance));
        etherAllowance = 0;
        jotAllowance = 0;
    }
    if (deals[msg.sender].verdictForInvestor == true) {
        require(msg.sender.send(deals[msg.sender].etherAmount - deals[msg.sender].etherUsed));
    }
}

function withdrawOffer(uint _offerNumber) public {
    require(offers[msg.sender][_offerNumber].accepted == false);
    require(msg.sender.send(offers[msg.sender][_offerNumber].etherAmount));
    offers[msg.sender][_offerNumber].etherAmount = 0;
}

function openDispute(address _icoRoundAddress, string _reason) public {
    AgileCycleWithAssistance cycle = AgileCycleWithAssistance(_icoRoundAddress);
    uint milestoneDispute = cycle.currentMilestone();
    require(milestoneDispute > 0);
    require(cycle.investorExists(msg.sender) == true);
    disputes[disputeLength].milestone = milestoneDispute;
    disputes[disputeLength].icoRoundAddress = _icoRoundAddress;
    disputes[disputeLength].investorAddress = msg.sender;
    disputes[disputeLength].timestamp = now;
    disputes[disputeLength].reason = _reason;
    disputes[disputeLength].pending = true;
    cycle.disputeOpened(msg.sender);
    disputeLength += 1;
}

function withdrawToken() public {
    require(token.transfer(msg.sender, deals[msg.sender].tokenAllowance));
    deals[msg.sender].tokenAllowance = 0;
}

function acceptOffer(address _investor, uint _offerNumber) public onlyAdmin {
    require(offers[_investor][_offerNumber].etherAmount > 0);
    require(offers[_investor][_offerNumber].accepted != true);
    AgileCycleWithAssistance cycle = AgileCycleWithAssistance(currentCycleAddress);
    require(cycle.sealTimestamp() > 0);
    offers[_investor][_offerNumber].accepted = true;
    uint _etherAmount = offers[_investor][_offerNumber].etherAmount;
    uint _tokenAmount = offers[_investor][_offerNumber].tokenAmount;
    require(token.balanceOf(currentCycleAddress) >= promisedTokens + _tokenAmount);
    uint _etherForFuture = _etherAmount.mul(percentForFuture).div(100);
    uint _tokenForFuture = _tokenAmount.mul(percentForFuture).div(100);
    if (_offerNumber == 0) {
        futureDeals[_investor].etherAmount += _etherForFuture;
        futureDeals[_investor].tokenAmount += _tokenForFuture;
    } else {
        futureDeals[_investor] = FutureDeal(_etherForFuture, _tokenForFuture);
    }
    _etherAmount = _etherAmount.sub(_etherForFuture);
    _tokenAmount = _tokenAmount.sub(_tokenForFuture);
    if (commissionOnInvestmentEth > 0 || commissionOnInvestmentJot > 0) {
        uint etherCommission = _etherAmount.mul(commissionOnInvestmentEth).div(100);
        uint jotCommission = _etherAmount.mul(commissionOnInvestmentJot).div(100);
        _etherAmount = _etherAmount.sub(etherCommission).sub(jotCommission);
        offers[_investor][_offerNumber].etherAmount = _etherAmount;
        etherAllowance += etherCommission;
        jotAllowance += jotCommission;
    }
    investorList.push(_investor);
    cycle.offerAccepted.value(_etherAmount)(_investor, _tokenAmount);
}

function vote(uint _disputeId, bool _voteForInvestor) public {
    require(disputes[_disputeId].pending == true);
    require(arbiterPool[disputes[_disputeId].icoRoundAddress][msg.sender] == true);
    require(disputes[_disputeId].voters[msg.sender] != true);
    if (_voteForInvestor == true) {
        disputes[_disputeId].votesForInvestor += 1;
    } else {
        disputes[_disputeId].votesForProject += 1;
    }
    if (disputes[_disputeId].votesForInvestor == quorum) {
        executeVerdict(_disputeId, true);
    }
    if (disputes[_disputeId].votesForProject == quorum) {
        executeVerdict(_disputeId, false);
    }
    disputes[_disputeId].voters[msg.sender] == true;
}

function setNextCycle() public onlyAdmin {
    require(cycles.length > 0);
    if (currentCycleNumber > 0) {
        AgileCycleWithAssistance cycle = AgileCycleWithAssistance(currentCycleAddress);
        uint finishedTimeStamp = cycle.finishedTimeStamp();
        require(now > finishedTimeStamp);
        uint interval = now - finishedTimeStamp;
    }
    currentCycleAddress = cycles[currentCycleNumber];
    currentCycleNumber += 1;
}

function() public payable {
    require(msg.value > minimumInvestment);
    for (uint i = 0; i < roundPrices.length; i++) {
        if (now > roundPrices[i].startTime && now < roundPrices[i].endTime) {
            rate = roundPrices[i].rate;
            if (roundPrices[i].hasWhitelist == true) {
                require(whitelist[i][msg.sender] == true);
            }
        }
    }
    uint dealNumber = offers[msg.sender][0].numberOfDeals;
    offers[msg.sender][dealNumber].etherAmount = msg.value;
    offers[msg.sender][dealNumber].tokenAmount = msg.value * rate;
    offers[msg.sender][0].numberOfDeals += 1;
}

function startMilestone() public sealed onlyAdmin {
    require(cycleApproved);
    if (currentMilestone != 0) {
        require(milestones[currentMilestone - 1].finishTime > 0);
        uint interval = now - milestones[currentMilestone - 1].finishTime;
        require(interval > 3 days);
    }
    for (uint i = 0; i < dealsList.length; i++) {
        address investor = dealsList[i];
        if (deals[investor].disputing == false) {
            if (deals[investor].verdictForInvestor != true) {
                ethForMilestone += etherPartition[investor][currentMilestone];
                deals[investor].etherUsed += etherPartition[investor][currentMilestone];
                if (tokenReleaseAtStart == false) {
                    deals[investor].tokenAllowance += tokenPartition[investor][currentMilestone];
                }
            }
        }
    }
    milestones[currentMilestone].startTime = now;
    currentMilestone += 1;
    ethForMilestone = payCommission();
}

function offerAccepted(address _investor, uint _tokenAmount) public payable only(icoAddress) {
    require(sealTimestamp > 0);
    uint _etherAmount = msg.value;
    assignPartition(_investor, _etherAmount, _tokenAmount);
    if (!(deals[_investor].etherAmount > 0)) dealsList.push(_investor);
    if (tokenReleaseAtStart == true) {
        deals[_investor].tokenAllowance = _tokenAmount;
    }
    deals[_investor].etherAmount += _etherAmount;
    deals[_investor].tokenAmount += _tokenAmount;
    promisedTokens += _tokenAmount;
    raisedEther += _etherAmount;
}

function finishMilestone(string _result) public onlyAdmin {
    require(milestones[currentMilestone - 1].finishTime == 0);
    uint interval = now - milestones[currentMilestone - 1].startTime;
    require(interval > 1 weeks);
    milestones[currentMilestone - 1].finishTime = now;
    milestones[currentMilestone - 1].result = _result;
    if (currentMilestone == milestones.length) {
        finishedTimeStamp = now;
    }
}

function sendFundsToNextCycle(uint _startLoop, uint _endLoop) public onlyAdmin {
    AgileCycleWithAssistance cycle = AgileCycleWithAssistance(currentCycleAddress);
    require(cycle.sealTimestamp() > 0);
    uint _promisedTokens = cycle.promisedTokens();
    uint _balanceTokens = token.balanceOf(currentCycleAddress);
    if (_endLoop == 0) _endLoop = investorList.length;
    require(_endLoop <= investorList.length);
    require(token.balanceOf(currentCycleAddress) >= promisedTokens + _tokenAmount);
    for (uint i = _startLoop; i < _endLoop; i++) {
        address _investor = investorList[i];
        uint _etherAmount = futureDeals[_investor].etherAmount;
        uint _tokenAmount = futureDeals[_investor].tokenAmount;
        _promisedTokens += _tokenAmount;
        if (requireTokens) require(_balanceTokens >= _promisedTokens);
        cycle.offerAccepted.value(_etherAmount)(_investor, _tokenAmount);
        futureDeals[_investor].etherAmount = 0;
        futureDeals[_investor].tokenAmount = 0;
    }
}

function() public payable {
