        starToken.transferFrom(beneficiary, wallet, starAllocationToTokenSale);
        wallet.splitStarFunds();
    }
}

function calcRates() public {
    require(getState() == State.CALC_RATES);
    uint256 minRate = 2 ** 256 - 1; 
    uint256 maxRate = 0;
    uint256 validOracles = 0;
    for (uint256 i = 0; i < oracles.length; i++) {
        OracleI oracle = OracleI(oracles[i]);
        uint256 rate = oracle.rate();
        if (oracle.waitQuery()) {
            continue;
        }
        if (isRateValid(rate)) {
            minRate = Math.min256(rate, minRate);
            maxRate = Math.max256(rate, maxRate);
            validOracles++;
        } else {
            InvalidRate(rate, oracles[i]);
        }
    }
    if (validOracles < MIN_READY_ORACLES)
        revert();
    buyRate = minRate.mul(FEE_MULTIPLIER * RATE_MULTIPLIER - buyFee * RATE_MULTIPLIER / 100) / FEE_MULTIPLIER / RATE_MULTIPLIER;
    sellRate = maxRate.mul(FEE_MULTIPLIER * RATE_MULTIPLIER + sellFee * RATE_MULTIPLIER / 100) / FEE_MULTIPLIER / RATE_MULTIPLIER;
    calcTime = now;
}

function requestRates() public payable {
    require(getState() == State.REQUEST_RATES);
    uint256 value = msg.value;
    for (uint256 i = 0; i < oracles.length; i++) {
        OracleI oracle = OracleI(oracles[i]);
        uint callPrice = oracle.getPrice();
        if (oracles[i].balance < callPrice) {
            value = value.sub(callPrice);
            oracles[i].transfer(callPrice);
        }
        if (oracle.updateRate())
            OracleRequest(oracles[i]);
    }
    requestTime = now;
    if (value > 0)
        msg.sender.transfer(value);
}

function ComplexExchanger(
    address _token,
    uint256 _buyFee,
    uint256 _sellFee,
    address[] _oracles,
    uint256 _deadline,
    address _withdrawWallet
) public {
    require(
        _withdrawWallet != address(0x0) &&
        _token != address(0x0) &&
        _deadline > now &&
        _oracles.length >= MIN_READY_ORACLES
    );
    tokenAddress = _token;
    token = LibreCash(tokenAddress);
    oracles = _oracles;
    buyFee = _buyFee;
    sellFee = _sellFee;
    deadline = _deadline;
    withdrawWallet = _withdrawWallet;
}

function waitingOracles() public view returns(uint256) {
    uint256 count = 0;
    for (uint256 i = 0; i < oracles.length; i++) {
        if (OracleI(oracles[i]).waitQuery() && (now - requestTime) < ORACLE_TIMEOUT) {
            count++;
        }
    }
    return count;
}

function getState() public view returns(State) {
    if (now >= deadline)
        return State.LOCKED;
    if (now - calcTime < RATE_PERIOD)
        return State.PROCESSING_ORDERS;
    if (waitingOracles() != 0)
        return State.WAIT_ORACLES;
    if (readyOracles() >= MIN_READY_ORACLES)
        return State.CALC_RATES;
    return State.REQUEST_RATES;
}

function readyOracles() public view returns(uint256) {
    uint256 count = 0;
    for (uint256 i = 0; i < oracles.length; i++) {
        OracleI oracle = OracleI(oracles[i]);
        if ((oracle.rate() != 0) &&
            !oracle.waitQuery() &&
            (now - oracle.updateTime()) < ORACLE_ACTUAL)
            count++;
    }
    return count;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "To or From address is blacklisted.");
    if (!isTradingEnabled) {
        require(_isExcluded[to] || _isExcluded[from], "Trading is not yet enabled. Be patient!");
    } else if (block.timestamp - startTime < 600 && from == uniswapV2Pair) {
        require(amount <= maxBuyTxAmount, "Over the max buy amount.");
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 swapTokens = contractTokenBalance.mul(liquidityFee).div(100);
        swapAndLiquify(swapTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee) {
        if (from == uniswapV2Pair) {
            liquidityFee = buy_liquidityFee;
            devFee = buy_devFee;
            protocolFee = buy_protocolFee;
            burnFee = buy_burnFee;
        } else if (to == uniswapV2Pair) {
            liquidityFee = sell_liquidityFee;
            devFee = sell_devFee;
            protocolFee = sell_protocolFee;
            burnFee = sell_burnFee;
        } else {
            liquidityFee = 0;
            devFee = 0;
            protocolFee = 0;
            burnFee = 0;
        }
        uint256 fees = amount.mul(liquidityFee + devFee + protocolFee + burnFee).div(1000);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

