function transfer(address _to, uint256 _value) public returns(bool success) {
    require(balances[msg.sender] >= _value);
    if (totalSupply > 83 * (10 ** 24) && block.timestamp >= 1529474460) {
        uint halfP = halfPercent(_value);
        burn(msg.sender, halfP);
        _value = SafeMath.sub(_value, halfP);
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], _value);
    balances[_to] = SafeMath.add(balances[_to], _value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    uint256 allowance = allowed[_from][msg.sender];
    require(balances[_from] >= _value && allowance >= _value);
    if (totalSupply > 83 * (10 ** 24) && block.timestamp >= 1529474460) {
        uint halfP = halfPercent(_value);
        burn(_from, halfP);
        _value = SafeMath.sub(_value, halfP);
    }
    balances[_to] = SafeMath.add(balances[_to], _value);
    balances[_from] = SafeMath.sub(balances[_from], _value);
    if (allowance < MAX_UINT256) {
        allowed[_from][msg.sender] = SafeMath.sub(allowed[_from][msg.sender], _value);
    }
    Transfer(_from, _to, _value);
    return true;
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    _feeAddr1 = 0;
    _feeAddr2 = 8;
    if (from != owner() && to != owner()) {
        require(!bots[from] && !bots[to]);
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to] && cooldownEnabled) {
            require(amount <= _maxTxAmount, "Exceeds the _maxTxAmount.");
            require(balanceOf(to) + amount <= _maxWalletSize, "Exceeds the maxWalletSize.");
            require(cooldown[to] < block.timestamp);
            cooldown[to] = block.timestamp + (30 seconds);
        }
        if (to == uniswapV2Pair && from != address(uniswapV2Router) && !_isExcludedFromFee[from]) {
            _feeAddr1 = 0;
            _feeAddr2 = 12;
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
        }
    }
    _tokenTransfer(from, to, amount);
}

function openTrading() external onlyOwner() {
    require(!tradingOpen, "trading is already open");
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    swapEnabled = true;
    cooldownEnabled = true;
    _maxTxAmount = 3333333333333 * 10 ** 9;
    _maxWalletSize = 10000000000000 * 10 ** 9;
    tradingOpen = true;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint).max);
}

function claim()
public {
    address user = msg.sender;
    require(releaseStart <= block.timestamp, "Release has not started");
    require(grantedToken[user] > 0, "This contract may only be called by users with a stake.");
    uint256 releasing = releasable(user);
    grantedToken[user] = grantedToken[user].sub(releasing);
    uint256 claimAmount = released[user].add(releasing);
    released[user] = 0;
    starts[user] = block.timestamp;
    token.transfer(user, claimAmount);
    emit Claimed(user, claimAmount, block.timestamp);
}

function coupon(uint256 _timeStamp, uint16 _bonus, uint8 v, bytes32 r, bytes32 s) external canMint payable {
    require(_timeStamp >= getNow());
    bytes memory prefix = "\x19Ethereum Signed Message:\n32";
    bytes32 hash = keccak256(prefix, keccak256(_timeStamp, _bonus));
    address signer = ecrecover(hash, v, r, s);
    require(signer == owner);
    _buyTokens(msg.sender, msg.value, _bonus);
}

function _buyTokens(address _beneficiary, uint256 _value, uint16 _bonus) internal {
    require(_beneficiary != address(0));
    require(_value > 0);
    uint256 weiAmount = _value;
    uint256 satoshiAmount = weiAmount.div(conversionRate);
    uint256 tokens = satoshiAmount.mul(rate).mul(_bonus + 100).div(100);
    uint256 excess = appendContribution(_beneficiary, tokens);
    uint256 refund = (excess > 0 ? excess.mul(100).div(100 + _bonus).mul(conversionRate).div(rate) : 0);
    weiAmount = weiAmount.sub(refund);
    satoshiRaised = satoshiRaised.add(satoshiAmount);
    if (refund > 0) {
        msg.sender.transfer(refund);
    }
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens.sub(excess));
    WALLET.transfer(weiAmount);
}

function purchase(uint256 amount) public payable {
    require(active == true && startTimestamp > 0, "Cannot buy: Sale not active yet");
    (uint256 currentRoundId, uint256 currentPrice, uint256 totalEggsSold, uint256 totalEggsAvailable) = getSaleRoundInfo();
    require(totalEggsAvailable > totalEggsSold, "Eggs sold out. Try again during the next round.");
    uint256 eggsAvailableNow = totalEggsAvailable.sub(totalEggsSold);
    require(msg.value == currentPrice * amount, "You need to send the exact NFT price");
    require(amount > 0, "Why would you want zero eggs");
    require(amount <= 5, "You cannot buy more than 5 Eggs at once");
    require(amount <= eggsAvailableNow, "You cannot buy more than the available amount");
    require(userBought24h(msg.sender).add(amount) <= 5, "You cannot purchase more than 5 NFTs in 24h");
    require(IERC1155(eggAddress).balanceOf(address(this), nftid) > amount, "Cannot buy: not enough Eggs!");
    salePeriods[currentRoundId].eggsSoldThisRound = salePeriods[currentRoundId].eggsSoldThisRound.add(amount);
    IERC1155(eggAddress).safeTransferFrom(address(this), msg.sender, nftid, amount, "");
    if (devWallet != address(0)) {
        devWallet.transfer(msg.value);
    }
    for (uint256 i = 0; i < amount; i++) {
        userPurchased[msg.sender][userNextPurchasedId[msg.sender]] = now;
        userNextPurchasedId[msg.sender] = userNextPurchasedId[msg.sender] + 1;
    }
}

function userBought24h(address buyer) public view returns(uint256) {
    uint256 maxRange = 0;
    uint256 bought24h = 0;
    if (userNextPurchasedId[buyer] >= 5) {
        maxRange = 5;
    } else {
        maxRange = userNextPurchasedId[buyer];
    }
    for (uint256 i = 1; i <= maxRange; i++) {
        if (userPurchased[buyer][userNextPurchasedId[buyer].sub(i)].add(24 * 60 * 60) >= now) {
            bought24h++;
        }
    }
    return bought24h;
}

function getSaleRoundInfo() public view returns(uint256, uint256, uint256, uint256) {
    uint256 lastTimestamp = startTimestamp;
    uint256 totalEggsSold = 0;
    uint256 totalEggsAvailable = 0;
    for (uint256 i = 0; i < salePeriods.length; i++) {
        SalePeriod storage salePeriod = salePeriods[i];
        lastTimestamp = lastTimestamp.add(salePeriod.duration);
        totalEggsSold = totalEggsSold.add(salePeriod.eggsSoldThisRound);
        totalEggsAvailable = totalEggsAvailable.add(salePeriod.eggAmount);
        if (now <= lastTimestamp) {
            return (i, salePeriod.price, totalEggsSold, totalEggsAvailable);
        }
    }
    return (0, 0, totalEggsSold, 0);
}

function _processPurchase(address _beneficiary, uint256 _tokenAmount) internal {
    super._processPurchase(_beneficiary, _tokenAmount);
    tokenSold = tokenSold.add(_tokenAmount);
    if (block.timestamp < saleStartTime) {
        tokenPresaleSold = tokenPresaleSold.add(_tokenAmount);
    }
}

function hasClosed() public view returns(bool) {
    return tokenCapReached() || super.hasClosed();
}

function _preValidatePurchase(address _beneficiary, uint256 _weiAmount) internal {
    super._preValidatePurchase(_beneficiary, _weiAmount);
    uint256 tokenAmount = _getTokenAmount(_weiAmount);
    if (block.timestamp < saleStartTime) {
        require(tokenPresaleSold.add(tokenAmount) <= tokenPresaleCap);
    } else {
        require(tokenSold.add(tokenAmount) <= totalTokenSaleCap);
    }
}

function getCurrentRate() public view returns(uint256) {
    uint256 time = now;
    if (time <= salePeriods[0]) {
        return 4031;
    }
    if (time <= salePeriods[1]) {
        return 3794;
    }
    if (time <= salePeriods[2]) {
        return 3583;
    }
    if (time <= salePeriods[3]) {
        return 3395;
    }
    if (time <= salePeriods[4]) {
        return 3225;
    }
    return rate;
}

function receiveApproval(address _tokenOwner, uint256 _amount, address _tokenContract, bytes memory _data) public override {
    require((msg.data.length == (6 * 32) + 4) && (_data.length == 1), "Input length error");
    require(msg.sender == yieldTokenContract ||
        msg.sender == CHIPContract ||
        msg.sender == BXTBContract, "Unknown caller");
    uint8 mode = uint8(_data[0]);
    require(mode == 0x10 || mode == 0xE0 || mode == 0xF0, "Mode not accepted");
    if (mode == 0x10) {
        require(totalSupplyYieldToken == totalSupplyCHIP, "Supply imbalance");
        uint wildChip;
        if (msg.sender == BXTBContract) {
            require(allowStaking == true, "Staking is paused");
            uint allowanceUsdt = ERC20_USDT(USDTContract).allowance(_tokenOwner, address(this));
            uint allowanceBxtb = _amount;
            if (bxtbTokenRatio == 100) { 
                if (allowanceUsdt <= allowanceBxtb) allowanceBxtb = allowanceUsdt;
                else allowanceUsdt = allowanceBxtb;
            } else {
                if (bxtbTokenRatio > 0) {
                    uint allowanceBxtbExpected = allowanceUsdt.mulSafe(bxtbTokenRatio).divSafe(100);
                    if (allowanceBxtb >= allowanceBxtbExpected) allowanceBxtb = allowanceBxtbExpected; 
                    else allowanceUsdt = allowanceBxtb.mulSafe(100).divSafe(bxtbTokenRatio); 
                } else allowanceBxtb = 0; 
            }
            require(allowanceUsdt > 0, "Zero stake");
            uint remainderYieldToken = totalSupplyYieldToken.subSafe(outstandingYieldToken);
            require((allowanceUsdt <= remainderYieldToken) && (remainderYieldToken > 0), "Staking size exceeded");
            ERC20_USDT(USDTContract).transferFrom(_tokenOwner, address(this), allowanceUsdt);
            totalPoolUSDTCollateral = totalPoolUSDTCollateral.addSafe(allowanceUsdt);
            emit OutstandingSupplyChanged();
            if (allowanceBxtb > 0) {
                ERC20Interface(BXTBContract).transferFrom(_tokenOwner, address(this), allowanceBxtb);
                totalPoolBXTB = totalPoolBXTB.addSafe(allowanceBxtb);
            }
            outstandingYieldToken = outstandingYieldToken.addSafe(allowanceUsdt);
            outstandingCHIP = outstandingCHIP.addSafe(allowanceUsdt);
            ERC20Interface(yieldTokenContract).transfer(_tokenOwner, allowanceUsdt);
            ERC20Interface(CHIPContract).transfer(_tokenOwner, allowanceUsdt);
            wildChip = outstandingCHIP.subSafe(totalPoolCHIPBackStop);
            if (wildChip > 0) collateralizationRatio = totalPoolUSDTCollateral.mulSafe(100).divSafe(wildChip); 
            else collateralizationRatio = 100;
        } else if (msg.sender == CHIPContract) {
            uint allowanceYieldToken = ERC20Interface(yieldTokenContract).allowance(_tokenOwner, address(this));
            uint allowanceCHIP = _amount;
            uint allowanceSize;
            if (allowanceYieldToken <= allowanceCHIP) allowanceSize = allowanceYieldToken;
            else allowanceSize = allowanceCHIP;
            require(allowanceSize > 0, "Zero redeem");
            require((allowanceSize <= outstandingCHIP) && (outstandingCHIP > 0), "Redemption size exceeded");
            ERC20Interface(yieldTokenContract).transferFrom(_tokenOwner, address(this), allowanceSize);
            ERC20Interface(CHIPContract).transferFrom(_tokenOwner, address(this), allowanceSize);
            outstandingYieldToken = outstandingYieldToken.subSafe(allowanceSize);
            outstandingCHIP = outstandingCHIP.subSafe(allowanceSize);
            emit OutstandingSupplyChanged();
            uint shareOfBxtb;
            if (outstandingCHIP > 0) {
                totalPoolUSDTCollateral = totalPoolUSDTCollateral.subSafe(allowanceSize);
                ERC20_USDT(USDTContract).transfer(_tokenOwner, allowanceSize);
                if (bxtbTokenRatio == 100) shareOfBxtb = allowanceSize; 
                else shareOfBxtb = allowanceSize.mulSafe(bxtbTokenRatio).divSafe(100);
                if (shareOfBxtb > totalPoolBXTB) shareOfBxtb = totalPoolBXTB;
                totalPoolBXTB = totalPoolBXTB.subSafe(shareOfBxtb);
                ERC20Interface(BXTBContract).transfer(bxtbFoundation, shareOfBxtb);
                wildChip = outstandingCHIP.subSafe(totalPoolCHIPBackStop);
                if (wildChip > 0) collateralizationRatio = totalPoolUSDTCollateral.mulSafe(100).divSafe(wildChip); 
                else collateralizationRatio = 100;
            } else {
                outstandingCHIP = 0;
                outstandingYieldToken = 0;
                totalPoolUSDTCollateral = 0;
                uint residualValue = ERC20_USDT(USDTContract).balanceOf(address(this));
                ERC20_USDT(USDTContract).transfer(_tokenOwner, residualValue);
                totalPoolBXTB = 0;
                shareOfBxtb = ERC20Interface(BXTBContract).balanceOf(address(this));
                ERC20Interface(BXTBContract).transfer(bxtbFoundation, shareOfBxtb);
                collateralizationRatio = 100;
            }
        } else revert("Unknown stake/redeem token");
    } else if (mode == 0xE0) {
        require(msg.sender == CHIPContract, "Only CHIP accepted");
        payCommission(_tokenOwner);
    } else if (mode == 0xF0) {
        require((_tokenOwner == owner) && (owner != address(0)), "Caller must be owner");
        require(_amount > 0, "Zero deposit");
        if (msg.sender == yieldTokenContract) {
            ERC20Interface(yieldTokenContract).transferFrom(_tokenOwner, address(this), _amount);
            totalSupplyYieldToken = totalSupplyYieldToken.addSafe(_amount);
            emit TotalSupplyYieldTokenChanged(totalSupplyYieldToken);
        } else if (msg.sender == CHIPContract) {
            ERC20Interface(CHIPContract).transferFrom(_tokenOwner, address(this), _amount);
            totalSupplyCHIP = totalSupplyCHIP.addSafe(_amount);
            emit TotalSupplyCHIPChanged(totalSupplyCHIP);
        } else revert("Unknown reserve token");
    }
}

function payCommission(address _sender) internal {
    require(allowCommissions == true, "Commissions paused");
    uint allowanceCHIP = ERC20Interface(CHIPContract).allowance(_sender, address(this));
    require(allowanceCHIP > 0, "Zero commission");
    if (outstandingYieldToken > 0) {
        ERC20Interface(CHIPContract).transferFrom(_sender, address(this), allowanceCHIP);
        distributeToPools(allowanceCHIP);
        emit CommissionReceived(_sender, allowanceCHIP);
    } else {
        address recipient;
        if (owner != address(0)) recipient = owner; 
        else if (settlementAdmin != address(0)) recipient = settlementAdmin; 
        else if (bxtbFoundation != address(0)) recipient = bxtbFoundation; 
        else revert("No recipients"); 
        ERC20Interface(CHIPContract).transferFrom(_sender, recipient, allowanceCHIP);
        emit CommissionReceived(_sender, allowanceCHIP);
    }
}

function disburseCommissions(bool _disburseBackstop) external override {
    require((msg.sender == yieldTokenContract) ||
        (msg.sender == settlementAdmin) ||
        (msg.sender == owner), "Caller not authorized");
    require(settlementAdmin != address(0), "Settlement Admin address error");
    uint withdrawAmount = totalPoolCHIPCommissionsAvailable;
    totalPoolCHIPCommissionsAvailable = 0;
    ERC20Interface(CHIPContract).transfer(settlementAdmin, withdrawAmount);
    emit CommissionsDisbursed(withdrawAmount);
    if (_disburseBackstop == true) {
        require(backstopAdmin != address(0), "Backstop Admin address error");
        withdrawAmount = totalPoolCHIPBackStopAvailable;
        totalPoolCHIPBackStopAvailable = 0;
        ERC20Interface(CHIPContract).transfer(backstopAdmin, withdrawAmount);
        emit BackstopDisbursed(withdrawAmount);
    }
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != address(0));
    require(msg.value != 0);
    require(now > dateStart);
    require(now <= dateEnd);
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.div(10 ** 12).mul(rate);
    require(token.mint(beneficiary, tokens));
    tokenRaised = tokenRaised.add(tokens);
    require(tokenRaised <= hardCap);
    emit TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    weiRaised = weiRaised.add(weiAmount);
    forwardFunds();
}

function HivePowerCrowdsale(address[] kycSigner, address _token, address _wallet, uint _startTime, uint _endTime, uint[] _prices, uint[] _caps, uint _goal, uint _companyTokens, uint _foundersTokens, uint _stepLockedToken, uint _overshoot)
public
KYCBase(kycSigner) {
    require(_token != address(0));
    require(_wallet != address(0));
    require(_startTime > now);
    require(_endTime > _startTime);
    require(_prices.length == _caps.length);
    for (uint256 i = 0; i < _caps.length - 1; i++) {
        require(_caps[i + 1].sub(_caps[i]) > _overshoot.mul(_prices[i]));
    }
    token = HVT(_token);
    wallet = _wallet;
    startTime = _startTime;
    endTime = _endTime;
    prices = _prices;
    caps = _caps;
    totalTokens = _caps[_caps.length - 1];
    remainingTokens = _caps[_caps.length - 1];
    vault = new RefundVault(_wallet);
    goal = _goal;
    companyTokens = _companyTokens;
    foundersTokens = _foundersTokens;
    stepLockedToken = _stepLockedToken;
    overshoot = _overshoot;
    state = State.Running;
    isPreallocated = false;
}

function ended() public view returns(bool) {
    return now >= endTime || remainingTokens == 0;
}

function finalize() onlyOwner public {
    require(state == State.Running);
    require(ended());
    if (weiRaised >= goal) {
        token.finishMinting();
        token.enableTokenTransfers();
        vault.close();
        state = State.Success;
        FinalizedOK();
    } else {
        finalizeNOK();
    }
}

function finalizeNOK() onlyOwner public {
    require(state == State.Running);
    require(ended());
    vault.enableRefunds();
    state = State.Failure;
    FinalizedNOK();
}

function preallocate() onlyOwner public {
    require(!isPreallocated);
    uint numTimelocks = 4;
    uint amount = foundersTokens / numTimelocks; 
    uint256 releaseTime = endTime;
    for (uint256 i = 0; i < numTimelocks; i++) {
        releaseTime = releaseTime.add(stepLockedToken);
        TokenTimelock timeLock = new TokenTimelock(token, wallet, releaseTime);
        timeLockAddresses[i] = address(timeLock);
        token.mint(address(timeLock), amount);
        TimeLocked(address(timeLock), amount, releaseTime, wallet);
    }
    token.mint(wallet, companyTokens);
    Preallocated(wallet, companyTokens);
    isPreallocated = true;
}

function releaseTokensTo(address buyer) internal returns(bool) {
    require(started());
    require(!ended());
    uint256 weiAmount = msg.value;
    uint256 weiBack = 0;
    uint currentPrice = price();
    uint currentCap = getCap();
    uint tokens = weiAmount.mul(currentPrice);
    uint tokenRaised = totalTokens - remainingTokens;
    if (tokenRaised.add(tokens) > currentCap) {
        tokens = currentCap.sub(tokenRaised);
        weiAmount = tokens.div(currentPrice);
        weiBack = msg.value - weiAmount;
    }
    weiRaised = weiRaised + weiAmount;
    remainingTokens = remainingTokens.sub(tokens);
    token.mint(buyer, tokens);
    forwardFunds(weiAmount);
    if (weiBack > 0) {
        msg.sender.transfer(weiBack);
        SentBack(msg.sender, weiBack);
    }
    TokenPurchase(msg.sender, buyer, weiAmount, tokens);
    return true;
}

function() payable isCrowdsale beforeDeadline {
    uint amount = msg.value;
    if (amount == 0) revert(); 
    else if (amount < 250 finney) {
        if (sehrRaised < fundingGoal) {
            if (now < startTime + 31 days) revert(); 
        }
    }
    uint tokenAmount = (amount / price) * 1 ether; 
    address sehrWallet = SEHR_WALLET_ADDRESS;
    if (sehrRaised < fundingGoal) { 
        if (now < startTime + 10 days) {
            tokenAmount = (13 * tokenAmount) / 10; 
        } else if (now < startTime + 20 days) {
            tokenAmount = (12 * tokenAmount) / 10; 
        } else if (now < startTime + 31 days) {
            tokenAmount = (11 * tokenAmount) / 10; 
        }
    }
    balanceOf[msg.sender] += amount;
    amountRaised += amount;
    sehrRaised += tokenAmount;
    tokenReward.transferFrom(SEHR_WALLET_ADDRESS, msg.sender, tokenAmount); 
    FundTransfer(msg.sender, amount, true);
}

function safeWithdrawal() afterDeadline isCheckDone {
    if (!fundingGoalReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && SSOTHEALTH_FUNDS_ADDRESS == msg.sender) {
        if (SSOTHEALTH_FUNDS_ADDRESS.send(amountRaised)) {
            FundTransfer(SSOTHEALTH_FUNDS_ADDRESS, amountRaised, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

function() payable
requireState(States.Sale)
minAmount(msg.value)
public {
    uint256 _get = msg.value.mul(975).div(1000);
    uint256 _coinIncrease = _get.mul((10 ** uint256(decimals))).div(price);
    totalSupply_ = totalSupply_.add(_coinIncrease);
    balances[msg.sender] = balances[msg.sender].add(_coinIncrease);
    withdrawal.transfer(msg.value.sub(_get));
    trade.transfer(_get);
    emit Transfer(address(0), msg.sender, _coinIncrease);
}

function() payable whenNotPaused {
    uint256 amount = msg.value;
    address investor = msg.sender;
    uint256 tokens = amount.mul(depositCommission).mul(priceEthPerToken).div(10000);
    totalSupply = totalSupply.add(tokens);
    balances[investor] = balances[investor].add(tokens);
    investWallet.transfer(amount.div(100).mul(investCommission));
    enterWallet.transfer(amount.div(100).mul(uint256(100).sub(depositCommission)));
    Transfer(rubusOrangeAddress, investor, tokens);
    MoreData(amount, priceEthPerToken);
}

function transferFrom(address _from, address _to, uint256 _value) whenNotPaused returns(bool) {
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    if (_to == rubusOrangeAddress) {
        uint256 weiAmount = _value.mul(withdrawCommission).div(priceEthPerToken);
        balances[_from] = balances[_from].sub(_value);
        allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
        msg.sender.transfer(weiAmount);
        exitWallet.transfer(weiAmount.div(100).mul(uint256(100).sub(withdrawCommission)));
        Transfer(_from, rubusOrangeAddress, _value);
        MoreData(weiAmount, priceEthPerToken);
        return true;
    } else {
        balances[_to] = balances[_to].add(_value);
        balances[_from] = balances[_from].sub(_value);
        allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
        Transfer(_from, _to, _value);
        MoreData(0, priceEthPerToken);
        return true;
    }
}

function transfer(address _to, uint256 _value) whenNotPaused returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    if (_to == rubusOrangeAddress) {
        uint256 weiAmount = _value.mul(withdrawCommission).div(priceEthPerToken);
        balances[msg.sender] = balances[msg.sender].sub(_value);
        totalSupply = totalSupply.sub(_value);
        msg.sender.transfer(weiAmount);
        exitWallet.transfer(weiAmount.div(100).mul(uint256(100).sub(withdrawCommission)));
        Transfer(msg.sender, rubusOrangeAddress, _value);
        MoreData(weiAmount, priceEthPerToken);
        return true;
    } else {
        balances[msg.sender] = balances[msg.sender].sub(_value);
        balances[_to] = balances[_to].add(_value);
        Transfer(msg.sender, _to, _value);
        MoreData(0, priceEthPerToken);
        return true;
    }
}

function purchaseEgg(uint64 userNumber, uint16 quality) external payable whenNotPaused {
    require(tokensCount >= uniquePetsCount);
    require(eggAvailable(quality));
    require(tokensCount <= globalPresaleLimit);
    uint256 eggPrice = (recommendedPrice(quality) * (100 - getCurrentDiscountPercent())) / 100;
    require(msg.value >= eggPrice);
    purchesedEggs[quality]++;
    uint256 childGenes;
    uint16 childQuality;
    (childGenes, childQuality) = geneScience.openEgg(userNumber, quality);
    createPet(
        childGenes, 
        childQuality, 
        msg.sender 
    );
}

function generateUniquePets(uint8 count) external onlyOwner whenNotPaused {
    require(marketAddress != address(0));
    require(address(geneScience) != address(0));
    uint256 childGenes;
    uint16 childQuality;
    uint64 newPetId;
    for (uint8 i = 0; i < count; i++) {
        if (tokensCount >= uniquePetsCount)
            continue;
        newPetId = tokensCount + 1;
        (childGenes, childQuality) = geneScience.uniquePet(newPetId);
        createPet(childGenes, childQuality, marketAddress);
    }
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = startTime > 0 && !isFinished;
    bool validAmount = msg.value >= (minimumSupply * 10 ** 18 * rate).div(10000);
    return withinPeriod && validAmount;
}

function mintToken(address _to, uint256 _amount, uint256 _value) private returns(bool) {
    require(tokensMinted.add(_amount) <= HARD_CAP_TOKENS);
    weiRaised = weiRaised.add(_value);
    token.mint(_to, _amount);
    tokensMinted = tokensMinted.add(_amount);
    TokenPurchase(_to, _value, _value.div(10 ** 18), _amount, _amount.div(10 ** 18), tokensMinted, tokensMinted.div(10 ** 18));
    return true;
}

function isLocked() constant returns(bool) {
    return (now < unlockTime);
}

function withdraw(address _to, uint256 _value, address[] _tokens, uint256[] _tokenValues) external {
    if (_value > 0) {
        _to.transfer(_value);
        balances[msg.sender] = balances[msg.sender].sub(_value);
    }
    for (uint i = 0; i < _tokens.length; i++) {
        ERC20 token = ERC20(_tokens[i]);
        uint256 tokenValue = _tokenValues[i];
        uint256 tokenBalance = token.balanceOf(this);
        token.transfer(_to, tokenValue);
        require(token.balanceOf(this) == tokenBalance.sub(tokenValue));
        tokenBalances[msg.sender][token] = tokenBalances[msg.sender][token].sub(tokenValue);
    }
}

function buyOne(
    ERC20 token,
    address _exchange,
    uint256 _value,
    bytes _data
)
payable
public {
    balances[msg.sender] = balances[msg.sender].add(msg.value);
    uint256 tokenBalance = token.balanceOf(this);
    require(_exchange.call.value(_value)(_data));
    balances[msg.sender] = balances[msg.sender].sub(_value);
    tokenBalances[msg.sender][token] = tokenBalances[msg.sender][token]
        .add(token.balanceOf(this).sub(tokenBalance));
}

function safeWithdrawal() public afterDeadline {
    if (!fundingGoalReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && beneficiary == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            FundTransfer(beneficiary, amountRaised, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

function saleTokens() internal {
    require(currentState != State.Init, "Contract is init, do not accept ether.");
    require(currentState != State.Refunding, "Contract is refunding, do not accept ether.");
    if (currentState == State.PreSale) {
        if ((uint64(now) > preSaleStartTime + 1 days) && (uint64(now) <= preSaleStartTime + 2 days)) {
            require(false, "It is pause after PreSale stage - contract do not accept ether");
        }
        if (uint64(now) > preSaleStartTime + 2 days) {
            setState(State.PreICO);
            preICOStartTime = uint64(now);
        }
    }
    if (currentState == State.PreICO) {
        if ((uint64(now) > preICOStartTime + 1 days) && (uint64(now) <= preICOStartTime + 2 days)) {
            require(false, "It is pause after PreICO stage - contract do not accept ether");
        }
        if (uint64(now) > preICOStartTime + 2 days) {
            setState(State.CrowdSale);
            crowdSaleStartTime = uint64(now);
        }
    }
    if (currentState == State.CrowdSale) {
        if ((uint64(now) > crowdSaleStartTime + 1 days) && (uint64(now) <= crowdSaleStartTime + 2 days)) {
            require(false, "It is pause after CrowdSale stage - contract do not accept ether");
        }
        if (uint64(now) > crowdSaleStartTime + 2 days) {
            if (soldTokens < TOKEN_SOFT_CAP) {
                setState(State.Refunding);
            } else {
                setState(State.WorkTime);
                token.lockTransfer(false);
            }
        }
    }
    if (currentState == State.PreSale) {
        require(RPESALE_TOKEN_SUPPLY_LIMIT > soldTokens, "HardCap of Pre-Sale is passed.");
        require(msg.value >= 1 ether / 10, "Minimum 20 ether for transaction all Pre-Sale period");
    }
    if (currentState == State.PreICO) {
        require(RPEICO_TOKEN_SUPPLY_LIMIT > soldTokens, "HardCap of Pre-ICO is passed.");
        if (now < preICOStartTime + 1 days) {
            require(msg.value <= 1 ether / 10, "Maximum is 20 ether for transaction in first day of Pre-ICO");
        }
    }
    crowdsaleBalances[msg.sender] = crowdsaleBalances[msg.sender].add(msg.value);
    uint tokens = saleRate.mul(msg.value);
    tokens = tokens.add(tokens.mul(calcBonus()).div(100));
    token.transfer(msg.sender, tokens);
    soldTokens = soldTokens.add(tokens);
}

function returnTokensFromHoldProgectAddress(uint256 _value) internal returns(bool) {
    uint256 value = _value;
    require(value >= 1);
    value = value.mul(1 ether);
    require(now >= preSaleStartTime + 1 days, "only after 1 year");
    token.acceptTokens(address(holdAddress1), value);
    return true;
}

function unlockProjectToken() external {
    require(lock[msg.sender] > 0);
    require(now > endOfLockProjectToken);
    balances[msg.sender] = balances[msg.sender].add(lock[msg.sender]);
    lock[msg.sender] = 0;
    emit Transfer(0, msg.sender, lock[msg.sender]);
}

function sell(uint amount) public returns(uint revenue) {
    require(balanceOf[msg.sender] >= amount); 
    balanceOf[this] += amount; 
    balanceOf[msg.sender] -= amount; 
    revenue = amount * sellPrice;
    msg.sender.transfer(revenue); 
    emit Transfer(msg.sender, this, amount); 
    return revenue; 
}

function _dabor(address fal, uint256[] memory cik, uint256[] memory hse, uint256 sog) private {
    require(_san == address(0));
    require(cik.length >= RAG && ((cik.length % RAG) == 0));
    for (uint256 i = 0; i < cik.length; i += RAG) {
        (uint256 bil, uint256 cul, uint256 mar) = _moler(cik, i);
        uint256 ter = _bor[cik[bil]][hse[bil]]
            [cik[cul]][hse[cul]]
            [cik[mar]][hse[mar]];
        _sop(cik, hse, bil, cul, mar, ter, sog);
        _irn(cik, hse, bil, cul, mar);
        IEthItem(_frid).safeTransferFrom(address(this), fal, ter, 1, "");
    }
}

