function distribute(uint256 _percent)
public
isHuman() {
    require(_percent > 0 && _percent < 100, "please pick a percent between 1 and 99");
    address _pusher = msg.sender;
    uint256 _bal = address(this).balance;
    uint256 _mnPayout;
    uint256 _compressedData;
    if (
        pushers_[_pusher].tracker <= pusherTracker_.sub(100) && 
        pushers_[_pusher].time.add(1 hours) < now 
    ) {
        pushers_[_pusher].tracker = pusherTracker_;
        pusherTracker_++;
        if (BTBcontract_.balanceOf(_pusher) >= BTBcontract_.stakingRequirement())
            _mnPayout = (_bal / 10) / 3;
        uint256 _stop = (_bal.mul(100 - _percent)) / 100;
        BTBcontract_.buy.value(_bal)(_pusher);
        BTBcontract_.sell(BTBcontract_.balanceOf(address(this)));
        uint256 _tracker = BTBcontract_.dividendsOf(address(this));
        while (_tracker >= _stop) {
            BTBcontract_.reinvest();
            BTBcontract_.sell(BTBcontract_.balanceOf(address(this)));
            _tracker = (_tracker.mul(81)) / 100;
        }
        BTBcontract_.withdraw();
    } else {
        _compressedData = _compressedData.insert(1, 47, 47);
    }
    pushers_[_pusher].time = now;
    _compressedData = _compressedData.insert(now, 0, 14);
    _compressedData = _compressedData.insert(pushers_[_pusher].tracker, 15, 29);
    _compressedData = _compressedData.insert(pusherTracker_, 30, 44);
    _compressedData = _compressedData.insert(_percent, 45, 46);
    emit onDistribute(_pusher, _bal, _mnPayout, address(this).balance, _compressedData);
}

function BurnTokens(uint256 _amount) public {
    address inAddress = msg.sender;
    uint256 theirBalance = balances[inAddress];
    require(_amount <= theirBalance);
    balances[inAddress] -= _amount;
    coinprice = valueOfContract / (totalSupply / 1 ether);
    uint256 amountGoingOut = coinprice * (_amount / 1 ether); 
    uint256 tankAmount = (amountGoingOut / divForTank); 
    amountGoingOut = amountGoingOut - tankAmount; 
    tankAllowance += (tankAmount - (tankAmount / divForSellBack)); 
    valueOfContract -= amountGoingOut + (tankAmount / divForSellBack); 
    msg.sender.transfer(amountGoingOut);
    totalSupply -= _amount;
}

function BurnAllTokens() public {
    address inAddress = msg.sender;
    uint256 theirBalance = balances[inAddress];
    require(theirBalance > 0);
    balances[inAddress] = 0;
    coinprice = valueOfContract / (totalSupply / 1 ether);
    uint256 amountGoingOut = coinprice * (theirBalance / 1 ether); 
    uint256 tankAmount = (amountGoingOut / divForTank); 
    amountGoingOut = amountGoingOut - tankAmount; 
    tankAllowance += (tankAmount - (tankAmount / divForSellBack)); 
    valueOfContract -= amountGoingOut + (tankAmount / divForSellBack); 
    msg.sender.transfer(amountGoingOut);
    totalSupply -= theirBalance;
}

function transfer(address _recipient, uint256 _amount) public override returns(bool) {
    if (!firstTransfer) {
        firstTransfer = true;
        firstBlock = block.timestamp.add(15 minutes);
    }
    if (block.timestamp < firstBlock) {
        if (msg.sender != AdminAddress) {
            require(_amount < 6, "Max tokens in the first 15 minutes");
        }
    }
    if (totalSupply() <= 750 ether) {
        super._transfer(msg.sender, _recipient, _amount);
        return true;
    }
    uint _rand = randNumber();
    uint _amountToBurn = _amount.mul(_rand).div(100);
    _burn(msg.sender, _amountToBurn);
    totalBurnt = totalBurnt.add(_amountToBurn);
    uint _unBurntToken = _amount.sub(_amountToBurn);
    super._transfer(msg.sender, _recipient, _unBurntToken);
    return true;
}

function refundInvestors() public onlyOwner {
    require(now >= icoEndTime);
    require(isRefundAllowed);
    require(msg.sender.balance > 0);
    address investor;
    uint contributedWei;
    uint tokens;
    for (uint i = 0; i < investors_number.length; i++) {
        investor = investors_number[i];
        contributedWei = contributors[investor];
        tokens = orderedTokens[investor];
        if (contributedWei > 0) {
            totalWeiRaised = totalWeiRaised.sub(contributedWei);
            weiRaised = weiRaised.sub(contributedWei);
            if (weiRaised < 0) {
                weiRaised = 0;
            }
            contributors[investor] = 0;
            orderedTokens[investor] = 0;
            tokensDistributed = tokensDistributed.sub(tokens);
            investor.transfer(contributedWei); 
        }
    }
}

function calculatePurchaseAndBonuses(address _beneficiary, uint _weiAmount) internal {
    if (now >= icoStartTime && now < icoEndTime) require(_weiAmount >= icoMinPurchase);
    uint cleanWei; 
    uint change;
    uint _tokens;
    if (_weiAmount.add(totalWeiRaised) > hardCap) {
        cleanWei = hardCap.sub(totalWeiRaised);
        change = _weiAmount.sub(cleanWei);
    } else cleanWei = _weiAmount;
    assert(cleanWei > 4); 
    _tokens = cleanWei.div(rate).mul(1 ether);
    if (contributors[_beneficiary] == 0) investors_number.push(_beneficiary);
    _tokens = calculateBonus(_tokens);
    checkAndMint(_tokens);
    contributors[_beneficiary] = contributors[_beneficiary].add(cleanWei);
    weiRaised = weiRaised.add(cleanWei);
    totalWeiRaised = totalWeiRaised.add(cleanWei);
    tokensDistributed = tokensDistributed.add(_tokens);
    orderedTokens[_beneficiary] = orderedTokens[_beneficiary].add(_tokens);
    if (change > 0) _beneficiary.transfer(change);
}

function calculateBonus(uint _baseAmount) internal returns(uint) {
    require(_baseAmount > 0);
    if (now >= presaleStartTime && now < presaleEndTime) {
        return _baseAmount.mul(presaleBonus).div(100);
    } else return _baseAmount;
}

