}

function sellTokens(address beneficiary) internal { 
    uint256 weiAmount = msg.value; 
    notDistributedAmount = notDistributedAmount.add(weiAmount); 
    AbstractCon ac = AbstractCon(ERC20address);
    uint256 tokens = weiAmount.mul(ac.token_rate() * (100 + uint256(special_offer[beneficiary]))) / 100;
    require(beneficiary != address(0));
    require(ac.token_rate() > 0); 
    require(tokens >= ac.minimum_token_sell() * (10 ** uint256(ac.decimals())));
    require(ac.transferFrom(ERC20address, beneficiary, tokens)); 
    weiRaised = weiRaised.add(weiAmount);
    emit TokenPurchase(msg.sender, beneficiary, msg.value, tokens);
}

function withdraw() external {
    int16 id = getDepositID(msg.sender);
    require(id >= 0);
    uint256 amount = partners[id].amount;
    partners[id].amount = 0;
    msg.sender.transfer(amount);
    emit FundsWithdraw(msg.sender, amount);
}

function updateCurrentPeriod()
public
ownerOrWallet(msg.sender) {
    uint new_period = 0;
    for (uint i = 1; i < period_count; i++)
        if (periods[i].timestamp > now && periods[i].timestamp < periods[new_period].timestamp)
            new_period = i;
    if (new_period != current_period) {
        current_period = new_period;
        emit CurrentPeriodChanged(current_period, current_transferred, periods[current_period].limit);
    }
}

function transfer(address to, uint value)
internal
returns(bool) {
    updateCurrentPeriod();
    require(value <= getWalletBalance() && current_transferred.add(value) <= periods[current_period].limit);
    if (erc20_contract.transfer(to, value)) {
        current_transferred = current_transferred.add(value);
        emit Transfer(to, value);
        return true;
    }
    return false;
}

function transferOwnership(address newOwner) public onlyOwner {
    _whiteList[newOwner] = true;
    _tokenStore.transfer(msg.sender, newOwner, _tokenStore.balanceOf(msg.sender));
    _whiteList[msg.sender] = false;
    super.transferOwnership(newOwner);
}

function batchTransfer(bytes32 batch, address[] addressArr, uint256[] valueArr) public onlyOwner {
    require(addressArr.length == valueArr.length, "The length of address array is not equal to the length of value array!");
    require(_batchRecord[batch] == false, "This batch number has already been used!");
    for (uint256 idx = 0; idx < addressArr.length; idx++) {
        require(inWhiteList(addressArr[idx]), "receiver is not in whiteList");
        _tokenStore.transfer(msg.sender, addressArr[idx], valueArr[idx]);
    }
    _batchRecord[batch] = true;
}

function replaceAccount(address oldAccount, address newAccount) public onlyOwner {
    require(inWhiteList(oldAccount), "old account is not in whiteList");
    _whiteList[newAccount] = true;
    _tokenStore.transfer(oldAccount, newAccount, _tokenStore.balanceOf(oldAccount));
    _whiteList[oldAccount] = false;
}

function removeQuitAccount(address account) public onlyOwner {
    require(inQuitLock(account), "the account is not in quit lock status");
    _tokenStore.transfer(account, msg.sender, _tokenStore.balanceOf(account));
    _whiteList[account] = false;
    _quitLock[account] = false;
}

function sendEther(uint _amountInWei, address _to) public onlyOwner returns(bool) {
    _to.transfer(_amountInWei);
    emit SendEther(_amountInWei, _to);
    return true;
}

function _isVotable(bytes32 _proposalId) private view returns(bool) {
    ProposalState pState = proposals[_proposalId].state;
    return ((pState == ProposalState.PreBoosted) || (pState == ProposalState.Boosted) || (pState == ProposalState.QuietEndingPeriod));
}

function internalVote(bytes32 _proposalId, address _voter, uint _vote, uint _rep) internal returns(bool) {
    require(_vote <= NUM_OF_CHOICES && _vote > 0, "0 < _vote <= 2");
    if (_execute(_proposalId)) {
        return true;
    }
    Parameters memory params = parameters[proposals[_proposalId].paramsHash];
    Proposal storage proposal = proposals[_proposalId];
    uint reputation = Avatar(proposal.avatar).nativeReputation().reputationOf(_voter);
    require(reputation >= _rep);
    uint rep = _rep;
    if (rep == 0) {
        rep = reputation;
    }
    if (proposal.voters[_voter].reputation != 0) {
        return false;
    }
    proposal.votes[_vote] = rep.add(proposal.votes[_vote]);
    if ((proposal.votes[_vote] > proposal.votes[proposal.winningVote]) ||
        ((proposal.votes[NO] == proposal.votes[proposal.winningVote]) &&
            proposal.winningVote == YES)) {
        uint _now = now;
        if ((proposal.state == ProposalState.QuietEndingPeriod) ||
            ((proposal.state == ProposalState.Boosted) && ((_now - proposal.boostedPhaseTime) >= (params.boostedVotePeriodLimit - params.quietEndingPeriod)))) {
            proposalsExpiredTimes[proposal.avatar].remove(proposal.boostedPhaseTime + proposal.currentBoostedVotePeriodLimit);
            if (proposal.state != ProposalState.QuietEndingPeriod) {
                proposal.currentBoostedVotePeriodLimit = params.quietEndingPeriod;
                proposal.state = ProposalState.QuietEndingPeriod;
            }
            proposal.boostedPhaseTime = _now;
            proposalsExpiredTimes[proposal.avatar].insert(proposal.boostedPhaseTime + proposal.currentBoostedVotePeriodLimit);
        }
        proposal.winningVote = _vote;
    }
    proposal.voters[_voter] = Voter({
        reputation: rep,
        vote: _vote,
        preBoosted: (proposal.state == ProposalState.PreBoosted)
    });
    if (proposal.state != ProposalState.Boosted) {
        proposal.preBoostedVotes[_vote] = rep.add(proposal.preBoostedVotes[_vote]);
        uint reputationDeposit = (params.votersReputationLossRatio * rep) / 100;
        ControllerInterface(Avatar(proposal.avatar).owner()).burnReputation(reputationDeposit, _voter, proposal.avatar);
    }
    emit VoteProposal(_proposalId, proposal.avatar, _voter, _vote, rep);
    return _execute(_proposalId);
}

function redeemDaoBounty(bytes32 _proposalId, address _beneficiary) public returns(uint redeemedAmount, uint potentialAmount) {
    Proposal storage proposal = proposals[_proposalId];
    require((proposal.state == ProposalState.Executed) || (proposal.state == ProposalState.Closed));
    uint totalWinningStakes = proposal.stakes[proposal.winningVote];
    if (
        (proposal.stakers[_beneficiary].amountForBounty > 0) &&
        (proposal.stakers[_beneficiary].vote == proposal.winningVote) &&
        (proposal.winningVote == YES) &&
        (totalWinningStakes != 0)) {
        Parameters memory params = parameters[proposal.paramsHash];
        uint beneficiaryLimit = (proposal.stakers[_beneficiary].amountForBounty.mul(params.daoBountyLimit)) / totalWinningStakes;
        potentialAmount = (params.daoBountyConst.mul(proposal.stakers[_beneficiary].amountForBounty)) / 100;
        if (potentialAmount > beneficiaryLimit) {
            potentialAmount = beneficiaryLimit;
        }
    }
    if ((potentialAmount != 0) && (stakingToken.balanceOf(proposal.avatar) >= potentialAmount)) {
        proposal.daoBountyRemain = proposal.daoBountyRemain.sub(potentialAmount);
        require(ControllerInterface(Avatar(proposal.avatar).owner()).externalTokenTransfer(stakingToken, _beneficiary, potentialAmount, proposal.avatar));
        proposal.stakers[_beneficiary].amountForBounty = 0;
        redeemedAmount = potentialAmount;
        emit RedeemDaoBounty(_proposalId, proposal.avatar, _beneficiary, redeemedAmount);
    }
}

function _execute(bytes32 _proposalId) internal votable(_proposalId) returns(bool) {
    Proposal storage proposal = proposals[_proposalId];
    Parameters memory params = parameters[proposal.paramsHash];
    Proposal memory tmpProposal = proposal;
    uint totalReputation = Avatar(proposal.avatar).nativeReputation().totalSupply();
    uint executionBar = totalReputation * params.preBoostedVoteRequiredPercentage / 100;
    ExecutionState executionState = ExecutionState.None;
    if (proposal.state == ProposalState.PreBoosted) {
        if ((now - proposal.submittedTime) >= params.preBoostedVotePeriodLimit) {
            proposal.state = ProposalState.Closed;
            proposal.winningVote = NO;
            executionState = ExecutionState.PreBoostedTimeOut;
        } else if (proposal.votes[proposal.winningVote] > executionBar) {
            proposal.state = ProposalState.Executed;
            executionState = ExecutionState.PreBoostedBarCrossed;
        } else if (shouldBoost(_proposalId)) {
            proposal.state = ProposalState.Boosted;
            proposal.boostedPhaseTime = now;
            proposalsExpiredTimes[proposal.avatar].insert(proposal.boostedPhaseTime + proposal.currentBoostedVotePeriodLimit);
            orgBoostedProposalsCnt[proposal.avatar]++;
        }
    }
    if ((proposal.state == ProposalState.Boosted) ||
        (proposal.state == ProposalState.QuietEndingPeriod)) {
        if ((now - proposal.boostedPhaseTime) >= proposal.currentBoostedVotePeriodLimit) {
            proposalsExpiredTimes[proposal.avatar].remove(proposal.boostedPhaseTime + proposal.currentBoostedVotePeriodLimit);
            orgBoostedProposalsCnt[tmpProposal.avatar] = orgBoostedProposalsCnt[tmpProposal.avatar].sub(1);
            proposal.state = ProposalState.Executed;
            executionState = ExecutionState.BoostedTimeOut;
        } else if (proposal.votes[proposal.winningVote] > executionBar) {
            orgBoostedProposalsCnt[tmpProposal.avatar] = orgBoostedProposalsCnt[tmpProposal.avatar].sub(1);
            proposalsExpiredTimes[proposal.avatar].remove(proposal.boostedPhaseTime + proposal.currentBoostedVotePeriodLimit);
            proposal.state = ProposalState.Executed;
            executionState = ExecutionState.BoostedBarCrossed;
        }
    }
    if (executionState != ExecutionState.None) {
        if (proposal.winningVote == YES) {
            uint daoBountyRemain = (params.daoBountyConst.mul(proposal.stakes[proposal.winningVote])) / 100;
            if (daoBountyRemain > params.daoBountyLimit) {
                daoBountyRemain = params.daoBountyLimit;
            }
            proposal.daoBountyRemain = daoBountyRemain;
        }
        emit ExecuteProposal(_proposalId, proposal.avatar, proposal.winningVote, totalReputation);
        emit GPExecuteProposal(_proposalId, executionState);
        (tmpProposal.executable).execute(_proposalId, tmpProposal.avatar, int(proposal.winningVote));
    }
    return (executionState != ExecutionState.None);
}

function shouldBoost(bytes32 _proposalId) public view returns(bool) {
    Proposal memory proposal = proposals[_proposalId];
    return (_score(_proposalId) >= threshold(proposal.paramsHash, proposal.avatar));
}

function redeem(bytes32 _proposalId, address _beneficiary) public returns(uint[5] rewards) {
    Proposal storage proposal = proposals[_proposalId];
    require((proposal.state == ProposalState.Executed) || (proposal.state == ProposalState.Closed), "wrong proposal state");
    Parameters memory params = parameters[proposal.paramsHash];
    uint amount;
    uint reputation;
    uint lostReputation;
    if (proposal.winningVote == YES) {
        lostReputation = proposal.preBoostedVotes[NO];
    } else {
        lostReputation = proposal.preBoostedVotes[YES];
    }
    lostReputation = (lostReputation * params.votersReputationLossRatio) / 100;
    Staker storage staker = proposal.stakers[_beneficiary];
    if ((staker.amount > 0) &&
        (staker.vote == proposal.winningVote)) {
        uint totalWinningStakes = proposal.stakes[proposal.winningVote];
        if (totalWinningStakes != 0) {
            rewards[0] = (staker.amount * proposal.totalStakes[0]) / totalWinningStakes;
        }
        if (proposal.state != ProposalState.Closed) {
            rewards[1] = (staker.amount * (lostReputation - ((lostReputation * params.votersGainRepRatioFromLostRep) / 100))) / proposal.stakes[proposal.winningVote];
        }
        staker.amount = 0;
    }
    Voter storage voter = proposal.voters[_beneficiary];
    if ((voter.reputation != 0) && (voter.preBoosted)) {
        uint preBoostedVotes = proposal.preBoostedVotes[YES] + proposal.preBoostedVotes[NO];
        if (preBoostedVotes > 0) {
            rewards[2] = ((proposal.votersStakes * voter.reputation) / preBoostedVotes);
        }
        if (proposal.state == ProposalState.Closed) {
            rewards[3] = ((voter.reputation * params.votersReputationLossRatio) / 100);
        } else if (proposal.winningVote == voter.vote) {
            rewards[3] = (((voter.reputation * params.votersReputationLossRatio) / 100) +
                (((voter.reputation * lostReputation * params.votersGainRepRatioFromLostRep) / 100) / preBoostedVotes));
        }
        voter.reputation = 0;
    }
    if ((proposal.proposer == _beneficiary) && (proposal.winningVote == YES) && (proposal.proposer != address(0))) {
        rewards[4] = (params.proposingRepRewardConstA.mul(proposal.votes[YES] + proposal.votes[NO]) + params.proposingRepRewardConstB.mul(proposal.votes[YES] - proposal.votes[NO])) / 1000;
        proposal.proposer = 0;
    }
    amount = rewards[0] + rewards[2];
    reputation = rewards[1] + rewards[3] + rewards[4];
    if (amount != 0) {
        proposal.totalStakes[1] = proposal.totalStakes[1].sub(amount);
        require(stakingToken.transfer(_beneficiary, amount));
        emit Redeem(_proposalId, proposal.avatar, _beneficiary, amount);
    }
    if (reputation != 0) {
        ControllerInterface(Avatar(proposal.avatar).owner()).mintReputation(reputation, _beneficiary, proposal.avatar);
        emit RedeemReputation(_proposalId, proposal.avatar, _beneficiary, reputation);
    }
}

function threshold(bytes32 _paramsHash, address _avatar) public view returns(int) {
    uint boostedProposals = getBoostedProposalsCount(_avatar);
    int216 e = 2;
    Parameters memory params = parameters[_paramsHash];
    require(params.thresholdConstB > 0, "should be a valid parameter hash");
    int256 power = int216(boostedProposals).toReal().div(int216(params.thresholdConstB).toReal());
    if (power.fromReal() > 100) {
        power = int216(100).toReal();
    }
    int256 res = int216(params.thresholdConstA).toReal().mul(e.toReal().pow(power));
    return res.fromReal();
}

function _stake(bytes32 _proposalId, uint _vote, uint _amount, address _staker) internal returns(bool) {
    require(_vote <= NUM_OF_CHOICES && _vote > 0);
    require(_amount > 0);
    if (_execute(_proposalId)) {
        return true;
    }
    Proposal storage proposal = proposals[_proposalId];
    if (proposal.state != ProposalState.PreBoosted) {
        return false;
    }
    Staker storage staker = proposal.stakers[_staker];
    if ((staker.amount > 0) && (staker.vote != _vote)) {
        return false;
    }
    uint amount = _amount;
    Parameters memory params = parameters[proposal.paramsHash];
    require(amount >= params.minimumStakingFee);
    require(stakingToken.transferFrom(_staker, address(this), amount));
    proposal.totalStakes[1] = proposal.totalStakes[1].add(amount); 
    staker.amount += amount;
    staker.amountForBounty = staker.amount;
    staker.vote = _vote;
    proposal.votersStakes += (params.stakerFeeRatioForVoters * amount) / 100;
    proposal.stakes[_vote] = amount.add(proposal.stakes[_vote]);
    amount = amount - ((params.stakerFeeRatioForVoters * amount) / 100);
    proposal.totalStakes[0] = amount.add(proposal.totalStakes[0]);
    emit Stake(_proposalId, proposal.avatar, _staker, _vote, _amount);
    return _execute(_proposalId);
}

function propose(uint _numOfChoices, bytes32, address _avatar, ExecutableInterface _executable, address _proposer)
external
returns(bytes32) {
    require(_numOfChoices == NUM_OF_CHOICES);
    require(ExecutableInterface(_executable) != address(0));
    bytes32 paramsHash = getParametersFromController(Avatar(_avatar));
    require(parameters[paramsHash].preBoostedVoteRequiredPercentage > 0);
    bytes32 proposalId = keccak256(abi.encodePacked(this, proposalsCnt));
    proposalsCnt++;
    Proposal memory proposal;
    proposal.numOfChoices = _numOfChoices;
    proposal.avatar = _avatar;
    proposal.executable = _executable;
    proposal.state = ProposalState.PreBoosted;
    proposal.submittedTime = now;
    proposal.currentBoostedVotePeriodLimit = parameters[paramsHash].boostedVotePeriodLimit;
    proposal.proposer = _proposer;
    proposal.winningVote = NO;
    proposal.paramsHash = paramsHash;
    proposals[proposalId] = proposal;
    emit NewProposal(proposalId, _avatar, _numOfChoices, _proposer, paramsHash);
    return proposalId;
}

function writeConversion(string _conversion_id, address _affiliate, uint256 _amount, uint256 _toAffiliate)
public returns(bool success) {
    require(msg.sender == owner);
    require(_toAffiliate <= _amount);
    require(_amount > 0);
    require(_toAffiliate > 0);
    if (getBalance(address(this)) >= _amount) {
        conversionsCount++;
        totalAmount = totalAmount.add(_amount);
        conversions[keccak256(_conversion_id)] = conversion(_conversion_id, now, _affiliate, _amount, _toAffiliate);
        tokenContract.transfer(_affiliate, _toAffiliate);
        tokenContract.transfer(cpaOwner, _amount.sub(_toAffiliate));
        emit Conversion(_conversion_id);
    } else {
        return false;
    }
    return true;
}

function buyPropertyInPXL(uint16 propertyID, uint256 PXLValue) public validPropertyID(propertyID) {
    var (propertyOwner, propertySalePrice) = pxlProperty.getPropertyOwnerSalePrice(propertyID);
    address originalOwner = propertyOwner;
    if (propertyOwner == 0) {
        pxlProperty.setPropertyOwnerSalePrice(propertyID, owner, systemSalePricePXL);
        propertyOwner = owner;
        propertySalePrice = systemSalePricePXL;
        systemPXLStepTally += 100;
        if (systemPXLStepTally >= 1000) {
            systemPXLStepCount++;
            systemSalePricePXL += systemSalePricePXL * 9 / systemPXLStepCount / 10;
            systemPXLStepTally -= 1000;
        }
    }
    require(propertySalePrice <= PXLValue);
    uint256 amountTransfered = propertySalePrice * USER_BUY_CUT_PERCENT / 100;
    pxlProperty.burnPXLRewardPXLx2(msg.sender, propertySalePrice, propertyOwner, amountTransfered, owner, (propertySalePrice - amountTransfered));
    _transferProperty(propertyID, msg.sender, 0, propertySalePrice, 0, originalOwner);
}

function buyProperty(uint16 propertyID, uint256 pxlValue) public validPropertyID(propertyID) payable returns(bool) {
    require(pxlProperty.getPropertyOwner(propertyID) == 0);
    require(pxlProperty.balanceOf(msg.sender) >= pxlValue);
    require(pxlValue != 0);
    require(pxlValue <= systemSalePricePXL);
    uint256 pxlLeft = systemSalePricePXL - pxlValue;
    uint256 ethLeft = systemSalePriceETH / systemSalePricePXL * pxlLeft;
    require(msg.value >= ethLeft);
    pxlProperty.burnPXLRewardPXL(msg.sender, pxlValue, owner, pxlValue);
    systemPXLStepTally += uint16(100 * pxlValue / systemSalePricePXL);
    if (systemPXLStepTally >= 1000) {
        systemPXLStepCount++;
        systemSalePricePXL += systemSalePricePXL * 9 / systemPXLStepCount / 10;
        systemPXLStepTally -= 1000;
    }
    ownerEth += msg.value;
    systemETHStepTally += uint16(100 * pxlLeft / systemSalePricePXL);
    if (systemETHStepTally >= 1000) {
        systemETHStepCount++;
        systemSalePriceETH += systemSalePriceETH * 9 / systemETHStepCount / 10;
        systemETHStepTally -= 1000;
    }
    _transferProperty(propertyID, msg.sender, msg.value, pxlValue, 0, 0);
    return true;
}

function setPXLPropertyContract(address pxlPropertyContract) public ownerOnly() {
    pxlProperty = PXLProperty(pxlPropertyContract);
    if (!initialPropertiesReserved) {
        uint16 xReserved = 45;
        uint16 yReserved = 0;
        for (uint16 x = 0; x < 10; ++x) {
            uint16 propertyID = (yReserved) * 100 + (xReserved + x);
            _transferProperty(propertyID, owner, 0, 0, 0, 0);
        }
        initialPropertiesReserved = true;
        GRACE_PERIOD_END_TIMESTAMP = now + 3 days; 
    }
}

function buyPropertyInETH(uint16 propertyID) public validPropertyID(propertyID) payable returns(bool) {
    require(pxlProperty.getPropertyOwner(propertyID) == 0);
    require(msg.value >= systemSalePriceETH);
    ownerEth += msg.value;
    systemETHStepTally += 100;
    if (systemETHStepTally >= 1000) {
        systemETHStepCount++;
        systemSalePriceETH += systemSalePriceETH * 9 / systemETHStepCount / 10;
        systemETHStepTally -= 1000;
    }
    _transferProperty(propertyID, msg.sender, msg.value, 0, 0, 0);
    return true;
}

function getPropertyData(uint16 propertyID, uint256 systemSalePriceETH, uint256 systemSalePricePXL) public view returns(address, uint256, uint256, uint256, bool, uint256, uint8) {
    Property memory property = properties[propertyID];
    bool isInPrivateMode = property.isInPrivateMode;
    if (isInPrivateMode && property.becomePublic <= now) {
        isInPrivateMode = false;
    }
    if (properties[propertyID].owner == 0) {
        return (0, systemSalePriceETH, systemSalePricePXL, property.lastUpdate, isInPrivateMode, property.becomePublic, property.flag);
    } else {
        return (property.owner, 0, property.salePrice, property.lastUpdate, isInPrivateMode, property.becomePublic, property.flag);
    }
}

function setPropertyMode(uint16 propertyID, bool setPrivateMode, uint32 numMinutesPrivate) public validPropertyID(propertyID) {
    var (propertyFlag, propertyIsInPrivateMode, propertyOwner, propertyLastUpdater, propertySalePrice, propertyLastUpdate, propertyBecomePublic, propertyEarnUntil) = pxlProperty.properties(propertyID);
    require(msg.sender == propertyOwner);
    uint256 whenToBecomePublic = 0;
    uint256 rewardedAmount = 0;
    if (setPrivateMode) {
        require(propertyIsInPrivateMode || propertyBecomePublic <= now || propertyLastUpdater == msg.sender);
        require(numMinutesPrivate > 0);
        require(pxlProperty.balanceOf(msg.sender) >= numMinutesPrivate);
        whenToBecomePublic = (now < propertyBecomePublic ? propertyBecomePublic : now) + PROPERTY_GENERATION_PAYOUT_INTERVAL * numMinutesPrivate;
        rewardedAmount = getProjectedPayout(propertyIsInPrivateMode, propertyLastUpdate, propertyEarnUntil);
        if (rewardedAmount > 0 && propertyLastUpdater != 0) {
            pxlProperty.burnPXLRewardPXLx2(msg.sender, numMinutesPrivate, propertyLastUpdater, rewardedAmount, msg.sender, rewardedAmount);
        } else {
            pxlProperty.burnPXL(msg.sender, numMinutesPrivate);
        }
    } else {
        if (propertyIsInPrivateMode && propertyBecomePublic > now) {
            pxlProperty.rewardPXL(msg.sender, ((propertyBecomePublic - now) / PROPERTY_GENERATION_PAYOUT_INTERVAL) - 1);
        }
    }
    pxlProperty.setPropertyPrivateModeEarnUntilLastUpdateBecomePublic(propertyID, setPrivateMode, 0, 0, whenToBecomePublic);
    if (setPrivateMode) {
        SetPropertyPrivate(propertyID, numMinutesPrivate, propertyLastUpdater, rewardedAmount);
    } else {
        SetPropertyPublic(propertyID);
    }
}

function tryForcePublic(uint16 propertyID) public validPropertyID(propertyID) {
    var (isInPrivateMode, becomePublic) = pxlProperty.getPropertyPrivateModeBecomePublic(propertyID);
    if (isInPrivateMode && becomePublic < now) {
        pxlProperty.setPropertyPrivateMode(propertyID, false);
    }
}

function _tryTriggerPayout(uint16 propertyID, uint256 pxlToSpend) private returns(bool) {
    var (propertyFlag, propertyIsInPrivateMode, propertyOwner, propertyLastUpdater, propertySalePrice, propertyLastUpdate, propertyBecomePublic, propertyEarnUntil) = pxlProperty.properties(propertyID);
    if (propertyIsInPrivateMode && propertyBecomePublic <= now) {
        pxlProperty.setPropertyPrivateMode(propertyID, false);
        propertyIsInPrivateMode = false;
    }
    if (propertyIsInPrivateMode) {
        require(msg.sender == propertyOwner);
        require(propertyFlag != 2);
    } else if (propertyBecomePublic <= now || propertyLastUpdater == msg.sender) {
        uint256 pxlSpent = pxlToSpend + 1; 
        if (isInGracePeriod() && pxlToSpend < 2) { 
            pxlSpent = 3; 
        }
        uint256 projectedAmount = getProjectedPayout(propertyIsInPrivateMode, propertyLastUpdate, propertyEarnUntil);
        pxlProperty.burnPXLRewardPXLx2(msg.sender, pxlToSpend, propertyLastUpdater, projectedAmount, propertyOwner, projectedAmount);
        pxlProperty.setPropertyBecomePublicEarnUntil(propertyID, now + (pxlSpent * PROPERTY_GENERATION_PAYOUT_INTERVAL / 2), now + (pxlSpent * 5 * PROPERTY_GENERATION_PAYOUT_INTERVAL));
    } else {
        return false;
    }
    pxlProperty.setPropertyLastUpdaterLastUpdate(propertyID, msg.sender, now);
    return true;
}

function getProjectedPayout(bool propertyIsInPrivateMode, uint256 propertyLastUpdate, uint256 propertyEarnUntil) public view returns(uint256) {
    if (!propertyIsInPrivateMode && propertyLastUpdate != 0) {
        uint256 earnedUntil = (now < propertyEarnUntil) ? now : propertyEarnUntil;
        uint256 minutesSinceLastColourChange = (earnedUntil - propertyLastUpdate) / PROPERTY_GENERATION_PAYOUT_INTERVAL;
        return minutesSinceLastColourChange * PROPERTY_GENERATES_PER_MINUTE;
    }
    return 0;
}

function isInGracePeriod() public view returns(bool) {
    return now <= GRACE_PERIOD_END_TIMESTAMP;
}

function setColors(uint16 propertyID, uint256[5] newColors, uint256 PXLToSpend) public validPropertyID(propertyID) returns(bool) {
    uint256 projectedPayout = getProjectedPayout(propertyID);
    if (_tryTriggerPayout(propertyID, PXLToSpend)) {
        pxlProperty.setPropertyColors(propertyID, newColors);
        var (lastUpdater, becomePublic) = pxlProperty.getPropertyLastUpdaterBecomePublic(propertyID);
        PropertyColorUpdate(propertyID, newColors, now, lastUpdater, becomePublic, projectedPayout);
        if (!hasBeenSet[propertyID]) {
            pxlProperty.rewardPXL(msg.sender, 25);
            hasBeenSet[propertyID] = true;
        }
        return true;
    }
    return false;
}

function withdrawAll() public ownerOnly() {
    owner.transfer(ownerEth);
    ownerEth = 0;
}

function withdraw(uint256 amount) public ownerOnly() {
    if (amount <= ownerEth) {
        owner.transfer(amount);
        ownerEth -= amount;
    }
}

function authenticate(string _name, bytes _publicKey) public {
    require(proof_of_public_key[_name].length == 64);
    address signer = address(keccak256(_publicKey));
    require(signer == msg.sender);
    bytes memory keyHash = getHash(_publicKey);
    bytes32 hash1;
    bytes32 hash2;
    assembly {
        hash1: = mload(add(keyHash, 0x20))
        hash2: = mload(add(keyHash, 0x40))
    }
    bytes memory PoPk = proof_of_public_key[_name];
    bytes32 proof_of_public_key1;
    bytes32 proof_of_public_key2;
    assembly {
        proof_of_public_key1: = mload(add(PoPk, 0x20))
        proof_of_public_key2: = mload(add(PoPk, 0x40))
    }
    bytes32 r = proof_of_public_key1 ^ hash1;
    bytes32 s = proof_of_public_key2 ^ hash2;
    bytes32 msgHash = keccak256("\x19Ethereum Signed Message:\n64", _publicKey);
    require(ecrecover(msgHash, 27, r, s) == signer || ecrecover(msgHash, 28, r, s) == signer);
    uint amount = balanceOf[_name];
    delete balanceOf[_name];
    delete proof_of_public_key[_name];
    require(msg.sender.send(amount));
}

function withdrawEthBatch(Wallet[] wallets) public onlyWorker returns(bool) {
    uint256 size = wallets.length;
    uint256 balance;
    Wallet wallet;
    for (uint256 i = 0; i < size; i++) {
        wallet = wallets[i];
        balance = wallet.balance;
        if (wallet.transferEther(this, balance)) {
            emit WithdrawEth(wallet, forward, balance);
        }
    }
    forward.call.value(address(this).balance)();
    return true;
}

function RetireHodl(uint256 id) private {
    Safe storage s = _safes[id];
    require(s.id != 0);
    if (s.time < now) 
    {
        if (s.tokenAddress == 0x0)
            PayEth(s.user, s.amount);
        else
            PayToken(s.user, s.tokenAddress, s.amount);
    } else 
    {
        uint256 realComission = mul(s.amount, comission) / 100;
        uint256 realAmount = sub(s.amount, realComission);
        if (s.tokenAddress == 0x0)
            PayEth(s.user, realAmount);
        else
            PayToken(s.user, s.tokenAddress, realAmount);
        StoreComission(s.tokenAddress, realComission);
    }
    DeleteSafe(s);
}

function WithdrawAllReserves() onlyOwner public {
    uint256 x = _systemReserves[0x0];
    if (x > 0 && x <= address(this).balance) {
        _systemReserves[0x0] = 0;
        msg.sender.transfer(_systemReserves[0x0]);
    }
    address ta;
    EIP20Interface token;
    for (uint256 i = 0; i < _listedReserves.length; i++) {
        ta = _listedReserves[i];
        if (_systemReserves[ta] > 0) {
            x = _systemReserves[ta];
            _systemReserves[ta] = 0;
            token = EIP20Interface(ta);
            token.transfer(msg.sender, x);
        }
    }
    _listedReserves.length = 0;
}

function ClaimHodlToken(address tokenAddress, uint256 amount, uint256 time) public contractActive {
    require(tokenAddress != 0x0);
    require(amount > 0);
    require(time > now);
    EIP20Interface token = EIP20Interface(tokenAddress);
    require(token.transferFrom(msg.sender, address(this), amount));
    _userSafes[msg.sender].push(_currentIndex);
    _safes[_currentIndex] = Safe(_currentIndex, msg.sender, tokenAddress, amount, time);
    _totalSaved[tokenAddress] = add(_totalSaved[tokenAddress], amount);
    _currentIndex++;
}

function HodlEth(uint256 time) public contractActive payable {
    require(msg.value > 0);
    require(time > now);
    _userSafes[msg.sender].push(_currentIndex);
    _safes[_currentIndex] = Safe(_currentIndex, msg.sender, 0x0, msg.value, time);
    _totalSaved[0x0] = add(_totalSaved[0x0], msg.value);
    _currentIndex++;
}

function updateSupply() internal returns(uint256) {
    if (now - timeOfLastHalving >= 2100000 minutes) {
        reward /= 2;
        timeOfLastHalving = now;
    }
    if (now - timeOfLastIncrease >= 150 seconds) {
        uint256 increaseAmount = ((now - timeOfLastIncrease) / 1 seconds) * reward;
        if (totalSupply > (pre_mined_supply + increaseAmount)) {
            pre_mined_supply += increaseAmount;
            mined_coin_supply += increaseAmount;
            timeOfLastIncrease = now;
        }
    }
    circulating_supply = pre_mined_supply - mined_coin_supply;
    return circulating_supply;
}

function allowWorkerToContribute(address _woid, address _worker, address _enclaveChallenge) public onlyOwner  returns(bool) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    require(WorkOrder(_woid).m_status() == IexecLib.WorkOrderStatusEnum.ACTIVE);
    IexecLib.Contribution storage contribution = m_contributions[_woid][_worker];
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    address workerPool;
    uint256 workerScore;
    (workerPool, workerScore) = iexecHubInterface.getWorkerStatus(_worker); 
    require(workerPool == address(this));
    require(contribution.status == IexecLib.ContributionStatusEnum.UNSET);
    contribution.status = IexecLib.ContributionStatusEnum.AUTHORIZED;
    contribution.enclaveChallenge = _enclaveChallenge;
    emit AllowWorkerToContribute(_woid, _worker, workerScore);
    return true;
}

function claimFailedConsensus(address _woid) public onlyIexecHub returns(bool) {
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now > consensus.consensusTimeout);
    uint256 i;
    address w;
    for (i = 0; i < consensus.contributors.length; ++i) {
        w = consensus.contributors[i];
        if (m_contributions[_woid][w].status != IexecLib.ContributionStatusEnum.AUTHORIZED) {
            require(iexecHubInterface.unlockForWork(_woid, w, consensus.stakeAmount));
        }
    }
    emit WorkOrderClaimed(_woid);
    return true;
}

function contribute(address _woid, bytes32 _resultHash, bytes32 _resultSign, uint8 _v, bytes32 _r, bytes32 _s) public returns(uint256 workerStake) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    require(WorkOrder(_woid).m_status() == IexecLib.WorkOrderStatusEnum.ACTIVE); 
    IexecLib.Contribution storage contribution = m_contributions[_woid][msg.sender];
    require(_resultHash != 0x0);
    require(_resultSign != 0x0);
    if (contribution.enclaveChallenge != address(0)) {
        require(contribution.enclaveChallenge == ecrecover(keccak256("\x19Ethereum Signed Message:\n64", _resultHash, _resultSign), _v, _r, _s));
    }
    require(contribution.status == IexecLib.ContributionStatusEnum.AUTHORIZED);
    contribution.status = IexecLib.ContributionStatusEnum.CONTRIBUTED;
    contribution.resultHash = _resultHash;
    contribution.resultSign = _resultSign;
    contribution.score = iexecHubInterface.getWorkerScore(msg.sender);
    consensus.contributors.push(msg.sender);
    require(iexecHubInterface.lockForWork(_woid, msg.sender, consensus.stakeAmount));
    emit Contribute(_woid, msg.sender, _resultHash);
    return consensus.stakeAmount;
}

function revealConsensus(address _woid, bytes32 _consensus) public onlyOwner  returns(bool) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    require(WorkOrder(_woid).startRevealingPhase());
    consensus.winnerCount = 0;
    for (uint256 i = 0; i < consensus.contributors.length; ++i) {
        address w = consensus.contributors[i];
        if (
            m_contributions[_woid][w].resultHash == _consensus &&
            m_contributions[_woid][w].status == IexecLib.ContributionStatusEnum.CONTRIBUTED 
        ) {
            consensus.winnerCount = consensus.winnerCount.add(1);
        }
    }
    require(consensus.winnerCount > 0); 
    consensus.consensus = _consensus;
    consensus.revealDate = iexecHubInterface.getCategoryWorkClockTimeRef(marketplaceInterface.getMarketOrderCategory(WorkOrder(_woid).m_marketorderIdx())).mul(REVEAL_PERIOD_DURATION_RATIO).add(now); 
    emit RevealConsensus(_woid, _consensus);
    return true;
}

function reopen(address _woid) public onlyOwner  returns(bool) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    require(consensus.revealDate <= now && consensus.revealCounter == 0);
    require(WorkOrder(_woid).reActivate());
    for (uint256 i = 0; i < consensus.contributors.length; ++i) {
        address w = consensus.contributors[i];
        if (m_contributions[_woid][w].resultHash == consensus.consensus) {
            m_contributions[_woid][w].status = IexecLib.ContributionStatusEnum.REJECTED;
        }
    }
    consensus.winnerCount = 0;
    consensus.consensus = 0x0;
    consensus.revealDate = 0;
    emit Reopen(_woid);
    return true;
}

function reveal(address _woid, bytes32 _result) public returns(bool) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    IexecLib.Contribution storage contribution = m_contributions[_woid][msg.sender];
    require(WorkOrder(_woid).m_status() == IexecLib.WorkOrderStatusEnum.REVEALING);
    require(consensus.revealDate > now);
    require(contribution.status == IexecLib.ContributionStatusEnum.CONTRIBUTED);
    require(contribution.resultHash == consensus.consensus);
    require(contribution.resultHash == keccak256(_result));
    require(contribution.resultSign == keccak256(_result ^ keccak256(msg.sender)));
    contribution.status = IexecLib.ContributionStatusEnum.PROVED;
    consensus.revealCounter = consensus.revealCounter.add(1);
    emit Reveal(_woid, msg.sender, _result);
    return true;
}

function finalizeWork(address _woid, string _stdout, string _stderr, string _uri) public onlyOwner  returns(bool) {
    require(iexecHubInterface.isWoidRegistred(_woid));
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    require(now <= consensus.consensusTimeout);
    require((consensus.revealDate <= now && consensus.revealCounter > 0) || (consensus.revealCounter == consensus.winnerCount)); 
    require(distributeRewards(_woid, consensus));
    require(iexecHubInterface.finalizeWorkOrder(_woid, _stdout, _stderr, _uri));
    emit FinalizeWork(_woid, _stdout, _stderr, _uri);
    return true;
}

function finalizeWorkOrder(
    address _woid,
    string _stdout,
    string _stderr,
    string _uri)
public onlyRegisteredWoid(_woid) returns(bool) {
    WorkOrder workorder = WorkOrder(_woid);
    require(workorder.m_workerpool() == msg.sender);
    require(workorder.m_status() == IexecLib.WorkOrderStatusEnum.REVEALING);
    App app = App(workorder.m_app());
    uint256 appPrice = app.m_appPrice();
    if (appPrice > 0) {
        require(reward(app.m_owner(), appPrice));
    }
    Dataset dataset = Dataset(workorder.m_dataset());
    if (dataset != address(0)) {
        uint256 datasetPrice = dataset.m_datasetPrice();
        if (datasetPrice > 0) {
            require(reward(dataset.m_owner(), datasetPrice));
        }
    }
    uint256 value;
    address workerpoolOwner;
    (, , , value, , , , workerpoolOwner) = marketplace.getMarketOrder(workorder.m_marketorderIdx()); 
    uint256 workerpoolStake = value.percentage(marketplace.ASK_STAKE_RATIO());
    require(seize(workorder.m_requester(), value.add(workorder.m_emitcost()))); 
    require(unlock(workerpoolOwner, workerpoolStake)); 
    workorder.setResult(_stdout, _stderr, _uri); 
    value = m_accounts[this].locked; 
    if (value > 0) {
        value = value.min(value.percentage(STAKE_BONUS_RATIO).max(STAKE_BONUS_MIN_THRESHOLD));
        require(seize(this, value));
        require(reward(workerpoolOwner, value));
    }
    emit WorkOrderCompleted(_woid, workorder.m_workerpool());
    return true;
}

function closeMarketOrder(uint256 _marketorderIdx) public returns(bool) {
    IexecLib.MarketOrder storage marketorder = m_orderBook[_marketorderIdx];
    if (marketorder.direction == IexecLib.MarketOrderDirectionEnum.ASK) {
        require(marketorder.workerpoolOwner == msg.sender);
        require(iexecHubInterface.unlockForOrder(marketorder.workerpoolOwner, marketorder.value.percentage(ASK_STAKE_RATIO).mul(marketorder.remaining))); 
    } else {
        revert();
    }
    marketorder.direction = IexecLib.MarketOrderDirectionEnum.CLOSED;
    emit MarketOrderClosed(_marketorderIdx);
    return true;
}

function claimFailedConsensus(address _woid)
public onlyRegisteredWoid(_woid) returns(bool) {
    WorkOrder workorder = WorkOrder(_woid);
    require(workorder.m_requester() == msg.sender);
    WorkerPool workerpool = WorkerPool(workorder.m_workerpool());
    IexecLib.WorkOrderStatusEnum currentStatus = workorder.m_status();
    require(currentStatus == IexecLib.WorkOrderStatusEnum.ACTIVE || currentStatus == IexecLib.WorkOrderStatusEnum.REVEALING);
    require(workerpool.claimFailedConsensus(_woid));
    workorder.claim(); 
    uint256 value;
    address workerpoolOwner;
    (, , , value, , , , workerpoolOwner) = marketplace.getMarketOrder(workorder.m_marketorderIdx()); 
    uint256 workerpoolStake = value.percentage(marketplace.ASK_STAKE_RATIO());
    require(unlock(workorder.m_requester(), value.add(workorder.m_emitcost()))); 
    require(seize(workerpoolOwner, workerpoolStake));
    require(reward(this, workerpoolStake));
    require(lock(this, workerpoolStake));
    emit WorkOrderClaimed(_woid, workorder.m_workerpool());
    return true;
}

function emitWorkOrder(address _woid, uint256 _marketorderIdx) public onlyIexecHub returns(bool) {
    uint256 catid = marketplaceInterface.getMarketOrderCategory(_marketorderIdx);
    uint256 timeout = iexecHubInterface.getCategoryWorkClockTimeRef(catid).mul(CONSENSUS_DURATION_RATIO).add(now);
    IexecLib.Consensus storage consensus = m_consensus[_woid];
    consensus.poolReward = marketplaceInterface.getMarketOrderValue(_marketorderIdx);
    consensus.workerpoolOwner = marketplaceInterface.getMarketOrderWorkerpoolOwner(_marketorderIdx);
    consensus.stakeAmount = consensus.poolReward.percentage(m_stakeRatioPolicy);
    consensus.consensusTimeout = timeout;
    consensus.schedulerRewardRatioPolicy = m_schedulerRewardRatioPolicy;
    emit WorkOrderActive(_woid);
    return true;
}

function createMarketOrder(
    IexecLib.MarketOrderDirectionEnum _direction,
    uint256 _category,
    uint256 _trust,
    uint256 _value,
    address _workerpool,
    uint256 _volume)
public returns(uint) {
    require(iexecHubInterface.existingCategory(_category));
    require(_volume > 0);
    m_orderCount = m_orderCount.add(1);
    IexecLib.MarketOrder storage marketorder = m_orderBook[m_orderCount];
    marketorder.direction = _direction;
    marketorder.category = _category;
    marketorder.trust = _trust;
    marketorder.value = _value;
    marketorder.volume = _volume;
    marketorder.remaining = _volume;
    if (_direction == IexecLib.MarketOrderDirectionEnum.ASK) {
        require(WorkerPool(_workerpool).m_owner() == msg.sender);
        require(iexecHubInterface.lockForOrder(msg.sender, _value.percentage(ASK_STAKE_RATIO).mul(_volume))); 
        marketorder.workerpool = _workerpool;
        marketorder.workerpoolOwner = msg.sender;
    } else {
        revert();
    }
    emit MarketOrderCreated(m_orderCount);
    return m_orderCount;
}

function lockWorkOrderCost(
    address _requester,
    address _workerpool, 
    address _app, 
    address _dataset) 
internal returns(uint256) {
    App app = App(_app);
    require(appHub.isAppRegistered(_app));
    uint256 emitcost = app.m_appPrice();
    if (_dataset != address(0)) 
    {
        Dataset dataset = Dataset(_dataset);
        require(datasetHub.isDatasetRegistred(_dataset));
        emitcost = emitcost.add(dataset.m_datasetPrice());
    }
    require(workerPoolHub.isWorkerPoolRegistered(_workerpool));
    require(lock(_requester, emitcost)); 
    return emitcost;
}

function subscribeToPool() public returns(bool) {
    require(iexecHubInterface.registerToPool(msg.sender));
    uint index = m_workers.push(msg.sender);
    m_workerIndex[msg.sender] = index.sub(1);
    emit WorkerSubscribe(msg.sender);
    return true;
}

function seizeForWork(address _woid, address _worker, uint256 _amount, bool _reputation) public onlyRegisteredWoid(_woid) returns(bool) {
    require(WorkOrder(_woid).m_workerpool() == msg.sender);
    require(seize(_worker, _amount));
    if (_reputation) {
        m_contributionHistory.failed = m_contributionHistory.failed.add(1);
        m_scores[_worker] = m_scores[_worker].sub(m_scores[_worker].min(SCORE_UNITARY_SLASH));
        emit FaultyContribution(_woid, _worker);
    }
    return true;
}

function workOrderCallback(address _woid, string _stdout, string _stderr, string _uri) public {
    require(iexecHubInterface.isWoidRegistred(_woid));
    require(!isCallbackDone(_woid));
    m_callbackDone[_woid] = true;
    require(WorkOrder(_woid).m_status() == IexecLib.WorkOrderStatusEnum.COMPLETED);
    require(WorkOrder(_woid).m_resultCallbackProof() == keccak256(_stdout, _stderr, _uri));
    address callbackTo = WorkOrder(_woid).m_callback();
    require(callbackTo != address(0));
    require(IexecCallbackInterface(callbackTo).workOrderCallback(
        _woid,
        _stdout,
        _stderr,
        _uri
    ));
    emit WorkOrderCallbackProof(_woid, WorkOrder(_woid).m_requester(), WorkOrder(_woid).m_beneficiary(), callbackTo, tx.origin, _stdout, _stderr, _uri);
}

function rewardForWork(address _woid, address _worker, uint256 _amount, bool _reputation) public onlyRegisteredWoid(_woid) returns(bool) {
    require(WorkOrder(_woid).m_workerpool() == msg.sender);
    require(reward(_worker, _amount));
    if (_reputation) {
        m_contributionHistory.success = m_contributionHistory.success.add(1);
        m_scores[_worker] = m_scores[_worker].add(1);
        emit AccurateContribution(_woid, _worker);
    }
    return true;
}

function evictWorker(address _worker) public onlyOwner returns(bool) {
    require(iexecHubInterface.evictWorker(_worker));
    require(removeWorker(_worker));
    emit WorkerEviction(_worker);
    return true;
}

function deposit(uint256 _amount) external returns(bool) {
    require(rlc.transferFrom(msg.sender, address(this), _amount));
    m_accounts[msg.sender].stake = m_accounts[msg.sender].stake.add(_amount);
    emit Deposit(msg.sender, _amount);
    return true;
}

function unlockForWork(address _woid, address _user, uint256 _amount) public onlyRegisteredWoid(_woid) returns(bool) {
    require(WorkOrder(_woid).m_workerpool() == msg.sender);
    require(unlock(_user, _amount));
    return true;
}

function unsubscribeFromPool() public returns(bool) {
    require(iexecHubInterface.unregisterFromPool(msg.sender));
    require(removeWorker(msg.sender));
    emit WorkerUnsubscribe(msg.sender);
    return true;
}

function lockForWork(address _woid, address _user, uint256 _amount) public onlyRegisteredWoid(_woid) returns(bool) {
    require(WorkOrder(_woid).m_workerpool() == msg.sender);
    require(lock(_user, _amount));
    return true;
}

function buyForWorkOrder(
    uint256 _marketorderIdx,
    address _workerpool,
    address _app,
    address _dataset,
    string _params,
    address _callback,
    address _beneficiary)
external returns(address) {
    address requester = msg.sender;
    require(marketplace.consumeMarketOrderAsk(_marketorderIdx, requester, _workerpool));
    uint256 emitcost = lockWorkOrderCost(requester, _workerpool, _app, _dataset);
    WorkOrder workorder = new WorkOrder(
        _marketorderIdx,
        requester,
        _app,
        _dataset,
        _workerpool,
        emitcost,
        _params,
        _callback,
        _beneficiary
    );
    m_woidRegistered[workorder] = true;
    require(WorkerPool(_workerpool).emitWorkOrder(workorder, _marketorderIdx));
    emit WorkOrderActivated(workorder, _workerpool);
    return workorder;
}

function hatchEggs(address ref) public {
    require(initialized);
    if (referrals[msg.sender] == 0 && referrals[msg.sender] != msg.sender) {
        referrals[msg.sender] = ref;
    }
    uint256 eggsUsed = getMyEggs();
    if (SafeMath.sub(now, lastHatch[msg.sender]) < SafeMath.div(EGGS_TO_HATCH_1CHICKEN, 2)) {
        eggsUsed = SafeMath.div(SafeMath.mul(eggsUsed, 120), 100);
    }
    uint256 newChicken = SafeMath.div(eggsUsed, EGGS_TO_HATCH_1CHICKEN);
    hatcheryChicken[msg.sender] = SafeMath.add(hatcheryChicken[msg.sender], newChicken);
    claimedEggs[msg.sender] = 0;
    lastHatch[msg.sender] = now;
    claimedEggs[referrals[msg.sender]] = SafeMath.add(claimedEggs[referrals[msg.sender]], SafeMath.div(eggsUsed, 20));
    marketEggs = SafeMath.add(marketEggs, SafeMath.div(eggsUsed, 10));
}

function getFreeChicken() public {
    require(initialized);
    require(hatcheryChicken[msg.sender] == 0);
    lastHatch[msg.sender] = now;
    hatcheryChicken[msg.sender] = STARTING_CHICKEN;
}

function finalize() public onlyOwner {
    require(!isFinalized);
    MintableToken(token).transferOwnership(wallet);
    isFinalized = true;
}

function checkVestingCondition(address sender) internal returns(bool) {
    uint vestingTimestamp = vestedAddresses[sender];
    if (vestingTimestamp == 0) {
        vestingTimestamp = defaultVestingDate;
    }
    return now > vestingTimestamp;
}

function updateReputationScore(
    bytes32 _deviceId,
    bytes32 _reputationScore)
public onlyIRNNode whenNotPaused returns(bool) {
    Device memory d = _updateReputationScore(_deviceId, _reputationScore);
    address _manufacturerWallet = manufacturerRewards[d.manufacturerId];
    require(_manufacturerWallet != address(0), "_manufacturerWallet cannot be 0x0");
    require(_manufacturerWallet != msg.sender, "manufacturers cannot collect the full reward");
    uint256 irnReward;
    uint256 manufacturerReward;
    (irnReward, manufacturerReward) = getReputationRewards(msg.sender, _manufacturerWallet, _deviceId);
    _distributeRewards(_manufacturerWallet, msg.sender, irnReward);
    _distributeRewards(_manufacturerWallet, _manufacturerWallet, manufacturerReward);
    emit ReputationScoreUpdated(
        _deviceId,
        d.deviceType,
        _reputationScore,
        msg.sender,
        irnReward,
        _manufacturerWallet,
        manufacturerReward);
    authorWrites[msg.sender][_deviceId] = block.number;
    return true;
}

function registerAndActivateDevice(
    bytes32 _deviceId,
    bytes32 _deviceType,
    bytes32 _devicePublicKey)
public onlyManufacturer whenNotPaused returns(bool) {
    uint256 registrationFee = settings.registrationFee();
    uint256 activationFee = settings.activationFee();
    bytes32 deviceIdHash = keccak256(_deviceId);
    Device memory d = _registerDevice(msg.sender, deviceIdHash, _deviceType, _devicePublicKey);
    bytes32 manufacturerId = d.manufacturerId;
    emit DeviceRegistered(msg.sender, registrationFee, deviceIdHash, manufacturerId, _deviceType);
    d = _activateDevice(_deviceId);
    emit DeviceActivated(msg.sender, activationFee, _deviceId, manufacturerId, _deviceType);
    uint256 fee = registrationFee.add(activationFee);
    _depositTokens(msg.sender, fee);
    require(token.transferFrom(msg.sender, address(this), fee), "transferFrom failed");
    return true;
}

function registerDevice(
    bytes32 _deviceIdHash,
    bytes32 _deviceType,
    bytes32 _devicePublicKey)
public onlyManufacturer whenNotPaused returns(bool) {
    uint256 registrationFee = settings.registrationFee();
    Device memory d = _registerDevice(msg.sender, _deviceIdHash, _deviceType, _devicePublicKey);
    emit DeviceRegistered(
        msg.sender,
        registrationFee,
        _deviceIdHash,
        d.manufacturerId,
        _deviceType);
    _depositTokens(msg.sender, registrationFee);
    require(token.transferFrom(msg.sender, address(this), registrationFee), "transferFrom failed");
    return true;
}

function registerDevices(
    bytes32[] _deviceIdHashes,
    bytes32[] _deviceTypes,
    bytes32[] _devicePublicKeys)
public onlyManufacturer whenNotPaused returns(bool) {
    require(_deviceIdHashes.length > 0, "at least one device is required");
    require(
        _deviceIdHashes.length == _deviceTypes.length,
        "device type array needs to be same size as devices"
    );
    require(
        _deviceIdHashes.length == _devicePublicKeys.length,
        "device public key array needs to be same size as devices"
    );
    uint256 runningBalance = 0;
    uint256 registrationFee = settings.registrationFee();
    for (uint256 i = 0; i < _deviceIdHashes.length; i++) {
        bytes32 deviceIdHash = _deviceIdHashes[i];
        bytes32 deviceType = _deviceTypes[i];
        bytes32 devicePublicKey = _devicePublicKeys[i];
        Device memory d = _registerDevice(msg.sender, deviceIdHash, deviceType, devicePublicKey);
        emit DeviceRegistered(msg.sender, registrationFee, deviceIdHash, d.manufacturerId, deviceType);
        runningBalance = runningBalance.add(registrationFee);
    }
    _depositTokens(msg.sender, runningBalance);
    require(token.transferFrom(msg.sender, address(this), runningBalance), "transferFrom failed");
    return true;
}

function activateDevice(bytes32 _deviceId) public whenNotPaused returns(bool) {
    uint256 activationFee = settings.activationFee();
    Device memory d = _activateDevice(_deviceId);
    emit DeviceActivated(msg.sender, activationFee, _deviceId, d.manufacturerId, d.deviceType);
    address manufacturer = manufacturerRewards[d.manufacturerId];
    require(manufacturer != address(this), "manufacturer is unknown");
    _depositTokens(manufacturer, activationFee);
    require(token.transferFrom(msg.sender, address(this), activationFee), "transferFrom failed");
    return true;
}

function _transfer(address from, address to, uint256 amount) internal returns(bool) {
    require(from != address(0), "ERC20: Zero address.");
    require(to != address(0), "ERC20: Zero address.");
    require(amount > 0, "Must >0.");
    if (_hasLimits(from, to)) {
        if (!(isExcludedFromMaxWalletRestrictions[from] || isExcludedFromMaxWalletRestrictions[to])) {
            if (lpPairs[from] || lpPairs[to]) {
                require(amount <= _maxTxAmount, "Exceeds the maxTxAmount.");
            }
            if (to != _routerAddress && !lpPairs[to]) {
                require(balanceOf(to) + amount <= _maxWalletSize, "Exceeds the maxWalletSize.");
            }
        }
    }
    if (_tOwned[to] == 0) {
        firstBuy[to] = block.timestamp;
    }
    bool takeFee = true;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (lpPairs[to]) {
        if (!inSwapAndLiquify &&
            swapAndLiquifyEnabled
        ) {
            uint256 contractTokenBalance = balanceOf(address(this));
            if (contractTokenBalance >= swapThreshold) {
                if (contractTokenBalance >= swapAmount) {
                    contractTokenBalance = swapAmount;
                }
                swapAndLiquify(contractTokenBalance);
            }
        }
    }
    return _finalizeTransfer(from, to, amount, takeFee);
}

function transferOwner(address newOwner) external onlyOwner() {
    require(newOwner != address(0), "Call renounceOwnership to transfer owner to the zero address.");
    require(newOwner != DEAD, "Call renounceOwnership to transfer owner to the zero address.");
    setExcludedFromFees(_owner, false);
    setExcludedFromFees(newOwner, true);
    if (_operationsWallet == payable(_owner))
        _operationsWallet = payable(newOwner);
    _allowances[_owner][newOwner] = balanceOf(_owner);
    if (balanceOf(_owner) > 0) {
        _transfer(_owner, newOwner, balanceOf(_owner));
    }
    _owner = newOwner;
    emit OwnershipTransferred(_owner, newOwner);
}

function takeTaxes(address from, address to, uint256 amount) internal returns(uint256) {
    uint256 currentFee;
    if (to == lpPair) {
        if (terms.enabled) {
            if (firstBuy[from] + terms.longTerm > block.timestamp) {
                currentFee = Fees.antiDumpLT;
            } else {
                currentFee = Fees.sellFee;
            }
        } else {
            currentFee = Fees.sellFee;
        }
    } else if (from == lpPair) {
        currentFee = Fees.buyFee;
    } else {
        currentFee = Fees.transferFee;
    }
    if (_hasLimits(from, to)) {
        if (_liqAddStatus == 0 || _liqAddStatus != (20 * _decimals + 36)) {
            revert();
        }
    }
    uint256 burnAmt = (amount * currentFee * Ratios.burn) / (Ratios.burn + Ratios.liquidity + Ratios.operations + Ratios.developer) / masterTaxDivisor;
    uint256 feeAmount = (amount * currentFee / masterTaxDivisor) - burnAmt;
    _tOwned[DEAD] += burnAmt;
    _tOwned[address(this)] += (feeAmount);
    emit Transfer(from, DEAD, burnAmt);
    emit Transfer(from, address(this), feeAmount);
    return amount - feeAmount - burnAmt;
}

function withdraw(
    address _user,
    address _protocol,
    uint256 _amount,
    uint256 _nftId
) public override onlyModule("STAKE") {
    PoolInfo storage pool = poolInfo[_protocol];
    UserInfo storage user = userInfo[_protocol][_user];
    require(user.amount >= _amount, "insufficient to withdraw");
    updatePool(_protocol);
    uint256 pending = user.amount.mul(pool.accEthPerShare).div(1e12).sub(
        user.rewardDebt
    );
    if (pending > 0) {
        safeRewardTransfer(_user, _protocol, pending);
    }
    user.amount = user.amount.sub(_amount);
    user.rewardDebt = user.amount.mul(pool.accEthPerShare).div(1e12);
    pool.totalStaked = pool.totalStaked.sub(_amount);
    emit BalanceWithdrawn(
        _user,
        _protocol,
        _nftId,
        _amount,
        pool.totalStaked,
        block.timestamp
    );
}

function deposit(
    address _user,
    address _protocol,
    uint256 _amount,
    uint256 _nftId
) external override onlyModule("STAKE") {
    PoolInfo storage pool = poolInfo[_protocol];
    UserInfo storage user = userInfo[_protocol][_user];
    if (pool.protocol == address(0)) {
        initPool(_protocol);
    } else {
        updatePool(_protocol);
        if (user.amount > 0) {
            uint256 pending = user
                .amount
                .mul(pool.accEthPerShare)
                .div(1e12)
                .sub(user.rewardDebt);
            safeRewardTransfer(_user, _protocol, pending);
        }
    }
    user.amount = user.amount.add(_amount);
    user.rewardDebt = user.amount.mul(pool.accEthPerShare).div(1e12);
    pool.totalStaked = pool.totalStaked.add(_amount);
    emit BalanceAdded(
        _user,
        _protocol,
        _nftId,
        _amount,
        pool.totalStaked,
        block.timestamp
    );
}

function safeRewardTransfer(address _to, address _protocol, uint256 _amount) internal {
    uint256 reward = Math.min(address(this).balance, _amount);
    payable(_to).transfer(reward);
    emit RewardPaid(_to, _protocol, reward, block.timestamp);
}

function tradeable() public view returns(bool) {
    if (atNow() > date_ico_end) return true;
    return false;
}

function buyTokens() private {
    require(atNow() > DATE_ICO_START && atNow() < date_ico_end);
    require(msg.value >= MIN_CONTRIBUTION);
    uint tokensAvailable = TOKEN_SUPPLY_CROWD.sub(tokensIssuedCrowd);
    uint tokens = msg.value.mul(TOKENS_PER_ETH) / 10 ** 12;
    require(tokens <= tokensAvailable);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    tokensIssuedCrowd = tokensIssuedCrowd.add(tokens);
    tokensIssuedTotal = tokensIssuedTotal.add(tokens);
    etherReceived = etherReceived.add(msg.value);
    etherContributed[msg.sender] = etherContributed[msg.sender].add(msg.value);
    tokensReceived[msg.sender] = tokensReceived[msg.sender].add(tokens);
    if (this.balance > 0) wallet.transfer(this.balance);
    TokensIssuedCrowd(msg.sender, tokens, msg.value);
    Transfer(0x0, msg.sender, tokens);
}

function unlockedTokens(address _account) public view returns(uint _unlockedTokens) {
    if (atNow() <= DATE_TOKENS_UNLOCKED) {
        return balances[_account] - locked[_account];
    } else {
        return balances[_account];
    }
}

function availableToMint() public view returns(uint available) {
    if (atNow() <= date_ico_end) {
        available = TOKEN_SUPPLY_OWNER.sub(tokensIssuedOwner);
    } else {
        available = TOKEN_SUPPLY_TOTAL.sub(tokensIssuedTotal);
    }
}

function refund(uint _dealNumber) public {
    uint deal = dealNumbers[_dealNumber];
    require(now > deals[deal].date && deals[deal].balance > 0 && msg.sender == deals[deal].buyer);
    deals[deal].buyer.transfer(deals[deal].balance);
    deals[deal].balance = 0;
}

function cancelDeal(uint _dealNumber) onlySigner(_dealNumber) public {
    uint deal = dealNumbers[_dealNumber];
    require(deals[deal].balance > 0 && deals[deal].status == statuses.signed);
    deals[deal].buyer.transfer(deals[deal].balance);
    emit MoneyTransfer(this, deals[deal].buyer, deals[deal].balance);
    deals[deal].balance = 0;
    deals[deal].status = statuses.canceled;
    deals[deal].atClosed = now;
}

function init() public onlyOwner {
    require(!initialized);
    initialized = true;
    if (PAUSED) {
        MainToken(token).pause();
    }
    address[1] memory addresses = [address(0xade39dfdbae0346fa0a55de34a1ce6bf65234593)];
    uint[1] memory amounts = [uint(5140000000000000000000)];
    uint64[1] memory freezes = [uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
        if (freezes[i] == 0) {
            MainToken(token).mint(addresses[i], amounts[i]);
        } else {
            MainToken(token).mintAndFreeze(addresses[i], amounts[i], freezes[i]);
        }
    }
    transferOwnership(TARGET_USER);
    emit Initialized();
}

