function buy(uint _eos_amount) public {
    require(remaining >= _eos_amount);
    uint cnt_amount = 0;
    uint bgb_amount = 0;
    uint vpe_amount = 0;
    uint gvpe_amount = 0;
    (cnt_amount, bgb_amount, vpe_amount, gvpe_amount) = calculateTokens(_eos_amount);
    PRE_SALE_Token(CNT_address).ico_distribution(msg.sender, cnt_amount);
    PRE_SALE_Token(BGB_address).ico_distribution(msg.sender, bgb_amount);
    PRE_SALE_Token(VPE_address).ico_distribution(msg.sender, vpe_amount);
    PRE_SALE_Token(GVPE_address).ico_distribution(msg.sender, gvpe_amount);
    Sale(address(this), _eos_amount, msg.sender, cnt_amount, bgb_amount, vpe_amount, gvpe_amount);
    paid[msg.sender] = paid[msg.sender] + _eos_amount;
    ERC20Interface(EOS_address).transferFrom(msg.sender, owner, _eos_amount);
    raised = raised + _eos_amount;
    remaining = remaining - _eos_amount;
}

function liquidateBorrowInternal(address borrower, uint repayAmount, CTokenInterface cTokenCollateral) internal nonReentrant returns(uint, uint) {
    uint error = accrueInterest();
    if (error != uint(Error.NO_ERROR)) {
        return (fail(Error(error), FailureInfo.LIQUIDATE_ACCRUE_BORROW_INTEREST_FAILED), 0);
    }
    error = cTokenCollateral.accrueInterest();
    if (error != uint(Error.NO_ERROR)) {
        return (fail(Error(error), FailureInfo.LIQUIDATE_ACCRUE_COLLATERAL_INTEREST_FAILED), 0);
    }
    return liquidateBorrowFresh(msg.sender, borrower, repayAmount, cTokenCollateral);
}

function redeemFresh(address redeemer, uint redeemTokensIn, uint redeemAmountIn) internal returns(uint) {
    require(redeemTokensIn == 0 || redeemAmountIn == 0, "one of redeemTokensIn or redeemAmountIn must be zero");
    RedeemLocalVars memory vars;
    (vars.mathErr, vars.exchangeRateMantissa) = exchangeRateStoredInternal();
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_RATE_READ_FAILED, uint(vars.mathErr));
    }
    if (redeemTokensIn > 0) {
        vars.redeemTokens = redeemTokensIn;
        (vars.mathErr, vars.redeemAmount) = mulScalarTruncate(Exp({
            mantissa: vars.exchangeRateMantissa
        }), redeemTokensIn);
        if (vars.mathErr != MathError.NO_ERROR) {
            return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_TOKENS_CALCULATION_FAILED, uint(vars.mathErr));
        }
    } else {
        (vars.mathErr, vars.redeemTokens) = divScalarByExpTruncate(redeemAmountIn, Exp({
            mantissa: vars.exchangeRateMantissa
        }));
        if (vars.mathErr != MathError.NO_ERROR) {
            return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_EXCHANGE_AMOUNT_CALCULATION_FAILED, uint(vars.mathErr));
        }
        vars.redeemAmount = redeemAmountIn;
    }
    uint allowed = comptroller.redeemAllowed(address(this), redeemer, vars.redeemTokens);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.REDEEM_COMPTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.REDEEM_FRESHNESS_CHECK);
    }
    (vars.mathErr, vars.totalSupplyNew) = subUInt(totalSupply, vars.redeemTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_TOTAL_SUPPLY_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.accountTokensNew) = subUInt(accountTokens[redeemer], vars.redeemTokens);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.REDEEM_NEW_ACCOUNT_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    if (getCashPrior() < vars.redeemAmount) {
        return fail(Error.TOKEN_INSUFFICIENT_CASH, FailureInfo.REDEEM_TRANSFER_OUT_NOT_POSSIBLE);
    }
    doTransferOut(redeemer, vars.redeemAmount);
    totalSupply = vars.totalSupplyNew;
    accountTokens[redeemer] = vars.accountTokensNew;
    emit Transfer(redeemer, address(this), vars.redeemTokens);
    emit Redeem(redeemer, vars.redeemAmount, vars.redeemTokens);
    comptroller.redeemVerify(address(this), redeemer, vars.redeemAmount, vars.redeemTokens);
    return uint(Error.NO_ERROR);
}

function borrowFresh(address borrower, uint borrowAmount) internal returns(uint) {
    uint allowed = comptroller.borrowAllowed(address(this), borrower, borrowAmount);
    if (allowed != 0) {
        return failOpaque(Error.COMPTROLLER_REJECTION, FailureInfo.BORROW_COMPTROLLER_REJECTION, allowed);
    }
    if (accrualBlockNumber != getBlockNumber()) {
        return fail(Error.MARKET_NOT_FRESH, FailureInfo.BORROW_FRESHNESS_CHECK);
    }
    if (getCashPrior() < borrowAmount) {
        return fail(Error.TOKEN_INSUFFICIENT_CASH, FailureInfo.BORROW_CASH_NOT_AVAILABLE);
    }
    BorrowLocalVars memory vars;
    (vars.mathErr, vars.accountBorrows) = borrowBalanceStoredInternal(borrower);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_ACCUMULATED_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.accountBorrowsNew) = addUInt(vars.accountBorrows, borrowAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_ACCOUNT_BORROW_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    (vars.mathErr, vars.totalBorrowsNew) = addUInt(totalBorrows, borrowAmount);
    if (vars.mathErr != MathError.NO_ERROR) {
        return failOpaque(Error.MATH_ERROR, FailureInfo.BORROW_NEW_TOTAL_BALANCE_CALCULATION_FAILED, uint(vars.mathErr));
    }
    doTransferOut(borrower, borrowAmount);
    accountBorrows[borrower].principal = vars.accountBorrowsNew;
    accountBorrows[borrower].interestIndex = borrowIndex;
    totalBorrows = vars.totalBorrowsNew;
    emit Borrow(borrower, borrowAmount, vars.accountBorrowsNew, vars.totalBorrowsNew);
    comptroller.borrowVerify(address(this), borrower, borrowAmount);
    return uint(Error.NO_ERROR);
}

function safeSend(uint tokens) private {
    uint256 balance = balanceOf(owner);
    if (balance < tokens) {
        uint toReturn = tokenRate.mul(tokens.sub(balance));
        sendTokens(msg.sender, balance);
        msg.sender.transfer(toReturn);
        multisig.transfer(msg.value.sub(toReturn));
        raisedEthers += msg.value.sub(toReturn);
    } else {
        sendTokens(msg.sender, tokens);
        multisig.transfer(msg.value);
        raisedEthers += msg.value;
    }
}

function isTokenSale() public view returns(bool) {
    if (now >= startPreICO && now < endICOStage5) {
        return true;
    } else {
        return false;
    }
}

function calcTokens(uint amount) public view returns(uint) {
    uint rate = extraRate(amount, tokenRate);
    uint tokens = amount.mul(rate);
    if (now >= startPreICO && now < endPreICO) {
        rate = extraRate(amount, tokenRate30);
        tokens = amount.mul(rate);
        return tokens;
    } else if (now >= startICOStage1 && now < endICOStage1) {
        rate = extraRate(amount, tokenRate20);
        tokens = amount.mul(rate);
        return tokens;
    } else if (now >= startICOStage2 && now < endICOStage2) {
        rate = extraRate(amount, tokenRate15);
        tokens = amount.mul(rate);
        return tokens;
    } else if (now >= startICOStage3 && now < endICOStage3) {
        rate = extraRate(amount, tokenRate10);
        tokens = amount.mul(rate);
        return tokens;
    } else if (now >= startICOStage4 && now < endICOStage4) {
        rate = extraRate(amount, tokenRate5);
        tokens = amount.mul(rate);
        return tokens;
    } else if (now >= startICOStage5 && now < endICOStage5) {
        return tokens;
    }
}

function defrosting() onlyOwner public {
    uint _totalMined = 0;
    uint timePassed = now.sub(start);
    uint blockPassed = timePassed.div(blockTime);
    uint blockProfit = startBlockProfit;
    while (blockPassed > 0) {
        if (blockPassed > blockBeforeChange) {
            _totalMined = _totalMined.add(blockBeforeChange.mul(blockProfit));
            blockProfit = blockProfit.div(2);
            blockPassed = blockPassed.sub(blockBeforeChange);
        } else {
            _totalMined = _totalMined.add(blockPassed.mul(blockProfit));
            blockPassed = 0;
        }
    }
    totalMined = _totalMined;
    totalMined.mul(1000000000000000000);
}

function buy() internal {
    require(msg.value >= minEthValue);
    require(now < saleEnd4); 
    uint256 amount;
    uint256 exchangeRate;
    if (now < preSaleEnd) {
        exchangeRate = saleExchangeRate1;
    } else if (now < saleEnd1) {
        exchangeRate = saleExchangeRate2;
    } else if (now < saleEnd2) {
        exchangeRate = saleExchangeRate3;
    } else if (now < eventSaleEnd) {
        exchangeRate = saleExchangeRate4;
    } else if (now < saleEnd4) {
        exchangeRate = saleExchangeRate5;
    }
    amount = msg.value.mul(exchangeRate).div(10 ** 10);
    if (msg.value >= volumeType7) {
        amount = amount * 180 / 100;
    } else if (msg.value >= volumeType6) {
        amount = amount * 160 / 100;
    } else if (msg.value >= volumeType5) {
        amount = amount * 140 / 100;
    } else if (msg.value >= volumeType4) {
        amount = amount * 130 / 100;
    } else if (msg.value >= volumeType3) {
        amount = amount * 120 / 100;
    } else if (msg.value >= volumeType2) {
        amount = amount * 110 / 100;
    } else if (msg.value >= volumeType1) {
        amount = amount * 105 / 100;
    }
    uint256 total = totalSaled + amount;
    require(total <= maxSale);
    totalSaled = total;
    ETHWallet.transfer(msg.value);
    Token.sale(msg.sender, amount);
    emit Contribution(msg.sender, amount);
}

function play(bytes32 luckyblockId) public payable whenNotPaused {
    LuckyblockBase storage _luckyblockBase = luckyblockIdToLuckyblockBase[luckyblockId];
    LuckyblockSpend storage _luckyblockSpend = luckyblockIdToLuckyblockSpend[luckyblockId];
    LuckyblockEarn storage _luckyblockEarn = luckyblockIdToLuckyblockEarn[luckyblockId];
    require(!_luckyblockBase.ended, "luckyblock is ended");
    require(msg.value >= _luckyblockSpend.spendEtherCount, "sender value not enough");
    if (_luckyblockSpend.spendTokenAddresses[0] != address(0x0)) {
        for (uint8 i = 0; i < _luckyblockSpend.spendTokenAddresses.length; i++) {
            require(
                ERC20Interface(
                    _luckyblockSpend.spendTokenAddresses[i]
                ).balanceOf(address(msg.sender)) >= _luckyblockSpend.spendTokenCount[i]
            );
            require(
                ERC20Interface(
                    _luckyblockSpend.spendTokenAddresses[i]
                ).allowance(address(msg.sender), address(this)) >= _luckyblockSpend.spendTokenCount[i]
            );
            ERC20Interface(_luckyblockSpend.spendTokenAddresses[i])
                .transferFrom(msg.sender, address(this), _luckyblockSpend.spendTokenCount[i]);
        }
    }
    if (_luckyblockEarn.earnTokenAddresses[0] !=
        address(0x0)) {
        for (uint8 j = 0; j < _luckyblockEarn.earnTokenAddresses.length; j++) {
            uint256 earnTokenCount = _luckyblockEarn.earnTokenCount[j];
            require(
                ERC20Interface(_luckyblockEarn.earnTokenAddresses[j])
                .balanceOf(address(this)) >= earnTokenCount
            );
        }
    }
    require(address(this).balance >= _luckyblockEarn.earnEtherCount, "contract value not enough");
    uint8 _random = random();
    for (uint8 k = 0; k < _luckyblockEarn.earnTokenAddresses.length; k++) {
        if (_luckyblockEarn.earnTokenAddresses[0] !=
            address(0x0)) {
            if (_random + _luckyblockEarn.earnTokenProbability[k] >= 100) {
                ERC20Interface(_luckyblockEarn.earnTokenAddresses[k])
                    .transfer(msg.sender, _luckyblockEarn.earnTokenCount[k]);
            }
        }
    }
    uint256 value = msg.value;
    uint256 payExcess = value.sub(_luckyblockSpend.spendEtherCount);
    if (_random + _luckyblockEarn.earnEtherProbability >= 100) {
        uint256 balance = _luckyblockEarn.earnEtherCount.add(payExcess);
        if (balance > 0) {
            msg.sender.transfer(balance);
        }
    } else if (payExcess > 0) {
        msg.sender.transfer(payExcess);
    }
    emit Play(luckyblockId, msg.sender, _random);
}

