    require(twitterIdToEthereumAddress[_twitterId] == msg.sender);
    uint256 transferAmount = twitterIdToEthereumBalance[_twitterId];
    twitterIdToEthereumBalance[_twitterId] = 0;
    (msg.sender).transfer(transferAmount);
