    require(twitterIdToEthereumBalance[_twitterId] > 0);
    require(twitterIdToTransferCredits[_twitterId] > 0);
    twitterIdToTransferCredits[_twitterId] = twitterIdToTransferCredits[_twitterId] - 1;
