function transferERC20Token(Token token, address to, uint256 amount) public returns(bool) {
    require(msg.sender == owner);
    uint256 prevBalance = token.balanceOf(address(this));
    if (prevBalance < amount) {
        return false;
    }
    address(token).call(
        abi.encodeWithSignature("transfer(address,uint256)", to, amount)
    );
    return prevBalance - amount == token.balanceOf(address(this));
}

function rescueToken(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 && addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e18);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function getBonusRate(uint256 _weiAmount) internal view returns(uint256) {
    uint256 bonusRate = rate;
    uint[2] memory weiRaisedStartsBounds = [uint(0), uint(15625000000000000000000)];
    uint[2] memory weiRaisedEndsBounds = [uint(15625000000000000000000), uint(17968750000000000000000)];
    uint64[2] memory timeStartsBounds = [uint64(1533585600), uint64(1533585600)];
    uint64[2] memory timeEndsBounds = [uint64(1535471995), uint64(1535471995)];
    uint[2] memory weiRaisedAndTimeRates = [uint(500), uint(300)];
    for (uint i = 0; i < 2; i++) {
        bool weiRaisedInBound = (weiRaisedStartsBounds[i] <= weiRaised) && (weiRaised < weiRaisedEndsBounds[i]);
        bool timeInBound = (timeStartsBounds[i] <= now) && (now < timeEndsBounds[i]);
        if (weiRaisedInBound && timeInBound) {
            bonusRate += bonusRate * weiRaisedAndTimeRates[i] / 1000;
        }
    }
    return bonusRate;
}

function hasClosed() public view returns(bool) {
    bool remainValue = cap.sub(weiRaised) < 250000000000000000;
    return super.hasClosed() || remainValue;
}

function transfer(address _to, uint256 _value) public onlyPayloadSize(2) returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    require(transfersEnabled);
    if (msg.sender == addressFundTeam) {
        require(checkVesting(_value, now) > 0);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function checkVesting(uint256 _value, uint256 _currentTime) public view returns(uint8 period) {
    period = 0;
    require(endTimeIco <= _currentTime);
    if (endTimeIco + 26 weeks <= _currentTime && _currentTime < endTimeIco + 52 weeks) {
        period = 1;
        require(balances[addressFundTeam].sub(_value) >= fundTeam.mul(95).div(100));
    }
    if (endTimeIco + 52 weeks <= _currentTime && _currentTime < endTimeIco + 78 weeks) {
        period = 2;
        require(balances[addressFundTeam].sub(_value) >= fundTeam.mul(85).div(100));
    }
    if (endTimeIco + 78 weeks <= _currentTime && _currentTime < endTimeIco + 104 weeks) {
        period = 3;
        require(balances[addressFundTeam].sub(_value) >= fundTeam.mul(65).div(100));
    }
    if (endTimeIco + 104 weeks <= _currentTime && _currentTime < endTimeIco + 130 weeks) {
        period = 4;
        require(balances[addressFundTeam].sub(_value) >= fundTeam.mul(35).div(100));
    }
    if (endTimeIco + 130 weeks <= _currentTime) {
        period = 5;
        require(balances[addressFundTeam].sub(_value) >= 0);
    }
}

function calculateTally(address _claimsAddress, uint _claimId) constant returns(bool) {
    NaiveClaims claimsContract = NaiveClaims(_claimsAddress);
    uint votingDeadline;
    (, votingDeadline) = claimsContract.claims(_claimId);
    uint voterCount = claimsContract.getVoterCount(_claimId);
    require(votingDeadline < now);
    uint indorsements;
    for (uint voterIndex = 0; voterIndex < voterCount; voterIndex++) {
        address voter = claimsContract.getVoter(_claimId, voterIndex);
        var (, hash, , voteExists, ) = claimsContract.getVote(_claimId, voter);
        if (voteExists == true) {
            if (hash == yesHash) {
                indorsements++;
            }
        }
    }
    return indorsements > 5;
}

function rollDice(uint256 _tokenId) public {
    require(msg.sender == ownerOfToken[_tokenId]);
    require(packageSize > 0);
    _transfer(msg.sender, owner, _tokenId);
    uint256 result = uint(keccak256(block.timestamp + block.difficulty)); 
    result %= sigmaRatio;
    uint256 rt;
    for (uint256 i = 0; i < packageSize; i++) {
        if (result >= package[i].ratio) {
            result -= package[i].ratio;
        } else {
            rt = i;
            break;
        }
    }
    Issuer issuer = Issuer(package[rt].issuer);
    issuer.transfer(msg.sender, package[rt].tokenId);
    sigmaRatio -= package[rt].ratio;
    package[rt] = package[packageSize - 1];
    packageSize -= 1;
    emit RollDice(msg.sender, package[rt].issuer, package[rt].tokenId);
}

function putIntoPackage(uint256 _tokenId, uint256 _ratio, address _issuer) onlyAdmins() public {
    Issuer issuer = Issuer(_issuer);
    require(issuer.ownerOf(_tokenId) == msg.sender);
    issuer.transferFrom(msg.sender, address(this), _tokenId);
    if (packageSize >= package.length) {
        package.push(Package(_tokenId, _ratio, _issuer));
    } else {
        package[packageSize].tokenId = _tokenId;
        package[packageSize].ratio = _ratio;
        package[packageSize].issuer = _issuer;
    }
    packageSize += 1;
    sigmaRatio += _ratio;
}

function transfer(address _to, uint _value, bytes _data) external {
    require(_value > 0);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value, _data);
}

function beginDispute(TellorStorage.TellorStorageStruct storage self, uint256 _requestId, uint256 _timestamp, uint256 _minerIndex) public {
    TellorStorage.Request storage _request = self.requestDetails[_requestId];
    require(_request.minedBlockNum[_timestamp] != 0, "Mined block is 0");
    require(_minerIndex < 5, "Miner index is wrong");
    address _miner = _request.minersByValue[_timestamp][_minerIndex];
    bytes32 _hash = keccak256(abi.encodePacked(_miner, _requestId, _timestamp));
    uint256 disputeId = self.uintVars[keccak256("disputeCount")] + 1;
    self.uintVars[keccak256("disputeCount")] = disputeId;
    uint256 hashId = self.disputeIdByDisputeHash[_hash];
    if (hashId != 0) {
        self.disputesById[disputeId].disputeUintVars[keccak256("origID")] = hashId;
    } else {
        self.disputeIdByDisputeHash[_hash] = disputeId;
        hashId = disputeId;
    }
    uint256 origID = hashId;
    uint256 dispRounds = self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")] + 1;
    self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")] = dispRounds;
    self.disputesById[origID].disputeUintVars[keccak256(abi.encode(dispRounds))] = disputeId;
    if (disputeId != origID) {
        uint256 lastID = self.disputesById[origID].disputeUintVars[keccak256(abi.encode(dispRounds - 1))];
        require(self.disputesById[lastID].disputeUintVars[keccak256("minExecutionDate")] <= now, "Dispute is already open");
        if (self.disputesById[lastID].executed) {
            require(now - self.disputesById[lastID].disputeUintVars[keccak256("tallyDate")] <= 1 days, "Time for voting haven't elapsed");
        }
    }
    uint256 _fee;
    if (_minerIndex == 2) {
        self.requestDetails[_requestId].apiUintVars[keccak256("disputeCount")] = self.requestDetails[_requestId].apiUintVars[keccak256("disputeCount")] + 1;
        _fee = self.uintVars[keccak256("stakeAmount")] * self.requestDetails[_requestId].apiUintVars[keccak256("disputeCount")];
    } else {
        _fee = self.uintVars[keccak256("disputeFee")] * dispRounds;
    }
    self.disputesById[disputeId] = TellorStorage.Dispute({
        hash: _hash,
        isPropFork: false,
        reportedMiner: _miner,
        reportingParty: msg.sender,
        proposedForkAddress: address(0),
        executed: false,
        disputeVotePassed: false,
        tally: 0
    });
    self.disputesById[disputeId].disputeUintVars[keccak256("requestId")] = _requestId;
    self.disputesById[disputeId].disputeUintVars[keccak256("timestamp")] = _timestamp;
    self.disputesById[disputeId].disputeUintVars[keccak256("value")] = _request.valuesByTimestamp[_timestamp][_minerIndex];
    self.disputesById[disputeId].disputeUintVars[keccak256("minExecutionDate")] = now + 2 days * dispRounds;
    self.disputesById[disputeId].disputeUintVars[keccak256("blockNumber")] = block.number;
    self.disputesById[disputeId].disputeUintVars[keccak256("minerSlot")] = _minerIndex;
    self.disputesById[disputeId].disputeUintVars[keccak256("fee")] = _fee;
    TellorTransfer.doTransfer(self, msg.sender, address(this), _fee);
    if (_minerIndex == 2) {
        _request.inDispute[_timestamp] = true;
        _request.finalValues[_timestamp] = 0;
    }
    self.stakerDetails[_miner].currentStatus = 3;
    emit NewDispute(disputeId, _requestId, _timestamp, _miner);
}

function _submitMiningSolution(
    TellorStorage.TellorStorageStruct storage self,
    string memory _nonce,
    uint256[5] memory _requestId,
    uint256[5] memory _value
) internal {
    bytes32 _hashMsgSender = keccak256(abi.encode(msg.sender));
    require(
        self.stakerDetails[msg.sender].currentStatus == 1,
        "Miner status is not staker"
    );
    require(
        now - self.uintVars[_hashMsgSender] > 15 minutes,
        "Miner can only win rewards once per 15 min"
    );
    require(
        _requestId[0] == self.currentMiners[0].value,
        "Request ID is wrong"
    );
    require(
        _requestId[1] == self.currentMiners[1].value,
        "Request ID is wrong"
    );
    require(
        _requestId[2] == self.currentMiners[2].value,
        "Request ID is wrong"
    );
    require(
        _requestId[3] == self.currentMiners[3].value,
        "Request ID is wrong"
    );
    require(
        _requestId[4] == self.currentMiners[4].value,
        "Request ID is wrong"
    );
    self.uintVars[_hashMsgSender] = now;
    bytes32 _currChallenge = self.currentChallenge;
    uint256 _slotProgress = self.uintVars[slotProgress];
    require(
        self.minersByChallenge[_currChallenge][msg.sender] == false,
        "Miner already submitted the value"
    );
    self.minersByChallenge[_currChallenge][msg.sender] = true;
    TellorStorage.Request storage _tblock =
        self.requestDetails[self.uintVars[_tBlock]];
    _tblock.valuesByTimestamp[0][_slotProgress] = _value[0];
    _tblock.valuesByTimestamp[1][_slotProgress] = _value[1];
    _tblock.valuesByTimestamp[2][_slotProgress] = _value[2];
    _tblock.valuesByTimestamp[3][_slotProgress] = _value[3];
    _tblock.valuesByTimestamp[4][_slotProgress] = _value[4];
    _tblock.minersByValue[0][_slotProgress] = msg.sender;
    _tblock.minersByValue[1][_slotProgress] = msg.sender;
    _tblock.minersByValue[2][_slotProgress] = msg.sender;
    _tblock.minersByValue[3][_slotProgress] = msg.sender;
    _tblock.minersByValue[4][_slotProgress] = msg.sender;
    if (_slotProgress + 1 == 4) {
        adjustDifficulty(self);
    }
    if (_slotProgress + 1 == 5) {
        newBlock(self, _nonce, _requestId);
        self.uintVars[slotProgress] = 0;
    } else {
        self.uintVars[slotProgress]++;
    }
    emit NonceSubmitted(
        msg.sender,
        _nonce,
        _requestId,
        _value,
        _currChallenge,
        _slotProgress
    );
}

function proposeFork(TellorStorage.TellorStorageStruct storage self, address _propNewTellorAddress) public {
    bytes32 _hash = keccak256(abi.encode(_propNewTellorAddress));
    self.uintVars[keccak256("disputeCount")]++;
    uint256 disputeId = self.uintVars[keccak256("disputeCount")];
    if (self.disputeIdByDisputeHash[_hash] != 0) {
        self.disputesById[disputeId].disputeUintVars[keccak256("origID")] = self.disputeIdByDisputeHash[_hash];
    } else {
        self.disputeIdByDisputeHash[_hash] = disputeId;
    }
    uint256 origID = self.disputeIdByDisputeHash[_hash];
    self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")]++;
    uint256 dispRounds = self.disputesById[origID].disputeUintVars[keccak256("disputeRounds")];
    self.disputesById[origID].disputeUintVars[keccak256(abi.encode(dispRounds))] = disputeId;
    if (disputeId != origID) {
        uint256 lastID = self.disputesById[origID].disputeUintVars[keccak256(abi.encode(dispRounds - 1))];
        require(self.disputesById[lastID].disputeUintVars[keccak256("minExecutionDate")] <= now, "Dispute is already open");
        if (self.disputesById[lastID].executed) {
            require(now - self.disputesById[lastID].disputeUintVars[keccak256("tallyDate")] <= 1 days, "Time for voting haven't elapsed");
        }
    }
    self.disputesById[disputeId] = TellorStorage.Dispute({
        hash: _hash,
        isPropFork: true,
        reportedMiner: msg.sender,
        reportingParty: msg.sender,
        proposedForkAddress: _propNewTellorAddress,
        executed: false,
        disputeVotePassed: false,
        tally: 0
    });
    TellorTransfer.doTransfer(self, msg.sender, address(this), 100e18 * 2 ** (dispRounds - 1)); 
    self.disputesById[disputeId].disputeUintVars[keccak256("blockNumber")] = block.number;
    self.disputesById[disputeId].disputeUintVars[keccak256("minExecutionDate")] = now + 7 days;
}

function _verifyNonce(
    TellorStorage.TellorStorageStruct storage self,
    string memory _nonce
) internal view {
    require(
        uint256(
            sha256(
                abi.encodePacked(
                    ripemd160(
                        abi.encodePacked(
                            keccak256(
                                abi.encodePacked(
                                    self.currentChallenge,
                                    msg.sender,
                                    _nonce
                                )
                            )
                        )
                    )
                )
            )
        ) %
        self.uintVars[difficulty] ==
        0 ||
        now - self.uintVars[timeOfLastNewValue] >= 15 minutes,
        "Incorrect nonce for current challenge"
    );
}

function adjustDifficulty(TellorStorage.TellorStorageStruct storage self)
internal {
    uint256 timeDiff = now - self.uintVars[timeOfLastNewValue];
    int256 _change = int256(SafeMath.min(1200, timeDiff));
    int256 _diff = int256(self.uintVars[difficulty]);
    _change =
        (_diff * (int256(self.uintVars[timeTarget]) - _change)) /
        4000;
    if (_change == 0) {
        _change = 1;
    }
    self.uintVars[difficulty] = uint256(SafeMath.max(_diff + _change, 1));
}

function() payable {
    require(sale_step != 0);
    if (msg.sender != owner) 
    {
        uint amount = 0;
        uint nowprice = 0;
        if (sale_step == 1)
            nowprice = 10000; 
        else
        if (sale_step == 2)
            nowprice = 5000; 
        else
            nowprice = 1000; 
        amount = msg.value * nowprice;
        require(balanceOf[waracoin_corp] >= amount);
        balanceOf[waracoin_corp] -= amount;
        balanceOf[msg.sender] += amount; 
        require(waracoin_corp.send(msg.value));
        Transfer(this, msg.sender, amount); 
    }
}

function deposit(uint _amount) public {
    require(_amount > 0);
    require(token.transferFrom(msg.sender, this, _amount));
    balances[msg.sender] = balances[msg.sender].add(_amount);
    Deposit(msg.sender, _amount, balances[msg.sender]);
}

