function withdrawForCharity(address _charity)
internal {
    address _customerAddress = _charity;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    emit onWithdraw(_customerAddress, _dividends);
}

function sell(uint256 _amountOfTokens, address _charity)
onlyTokenHolders() 
onlyNonFounders() 
public {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    uint256 _tokens = _amountOfTokens;
    uint256 _ethereum = tokensToEthereum_(_tokens);
    uint256 _dividends = SafeMath.div(_ethereum, dividendFee_);
    uint256 _charityDividends = SafeMath.div(_dividends, 3);
    if (_charity != 0x0000000000000000000000000000000000000000 && _charity != _customerAddress) 
    {
        _charityDividends = SafeMath.div(_dividends, 3); 
        _dividends = SafeMath.sub(_dividends, _charityDividends); 
        withdrawForCharity(_charity);
    }
    uint256 _taxedEthereum = SafeMath.sub(_ethereum, _dividends);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokens);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _tokens);
    int256 _updatedPayouts = (int256)(profitPerShare_ * _tokens + (_taxedEthereum * magnitude));
    payoutsTo_[_customerAddress] -= _updatedPayouts;
    if (tokenSupply_ > 0) {
        profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    }
    emit onTokenSell(_customerAddress, _tokens, _taxedEthereum, _charity);
}

function purchaseTokens(uint256 _incomingEthereum, address _referredBy, address _charity)
areWeLive(_incomingEthereum)
internal
returns(uint256) {
    address _customerAddress = msg.sender;
    uint256 _undividedDividends = SafeMath.div(_incomingEthereum, dividendFee_);
    uint256 _referralBonus = SafeMath.div(_undividedDividends, 3);
    uint256 _dividends = SafeMath.sub(SafeMath.sub(_undividedDividends, _referralBonus), _referralBonus); 
    uint256 _amountOfTokens = ethereumToTokens_(SafeMath.sub(_incomingEthereum, _undividedDividends));
    uint256 _fee = _dividends * magnitude;
    require(_amountOfTokens > 0 && (SafeMath.add(_amountOfTokens, tokenSupply_) > tokenSupply_));
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        tokenBalanceLedger_[_referredBy] >= referralLinkMinimum
    ) {
        referralBalance_[_referredBy] = SafeMath.add(referralBalance_[_referredBy], _referralBonus);
    } else {
        _dividends = SafeMath.add(_dividends, SafeMath.div(_undividedDividends, 3));
        _fee = _dividends * magnitude;
    }
    if (
        _charity != 0x0000000000000000000000000000000000000000 &&
        _charity != _customerAddress
    ) {
        referralBalance_[_charity] = SafeMath.add(referralBalance_[_charity], _referralBonus);
        withdrawForCharity(_charity);
    } else {
        _dividends = SafeMath.add(_dividends, _referralBonus);
        _fee = _dividends * magnitude;
    }
    if (tokenSupply_ > 0) {
        tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
        profitPerShare_ += (_dividends * magnitude / (tokenSupply_));
        _fee = _fee - (_fee - (_amountOfTokens * (_dividends * magnitude / (tokenSupply_))));
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    tokenBalanceLedger_[_customerAddress] = SafeMath.add(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens) - _fee);
    payoutsTo_[_customerAddress] += _updatedPayouts;
    emit onTokenPurchase(_customerAddress, _incomingEthereum, _amountOfTokens, _referredBy);
    return _amountOfTokens;
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + 4 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

function LuckyDraw() public {
    require(msg.sender == tx.origin);
    if (block.number >= playerBlock[msg.sender] + 256) {
        uint[] memory empty = new uint[](0);
        emit Numbers(address(this), empty, "Your tickets expired or are invalid. Try Again.");
    } else if (block.number > playerBlock[msg.sender] + blockInterval) {
        bool win = false;
        uint[] memory numbers = new uint[](playerTickets[msg.sender]);
        uint i = 0;
        while (i < playerTickets[msg.sender]) {
            numbers[i] = uint256(uint256(keccak256(abi.encodePacked(blockhash(playerBlock[msg.sender] + 2), i))) % maxNumber);
            if (numbers[i] == systemNumber)
                win = true;
            i++;
        }
        ticketsPlayed += playerTickets[msg.sender];
        if (win) {
            address payable add = payable(msg.sender);
            uint contractBalance = address(this).balance;
            uint winAmount = contractBalance * percentWin / 100;
            uint totalToPay = winAmount;
            if (!add.send(totalToPay)) revert('Error While Executing Payment.');
            totalPaidOut += totalToPay;
            winnersCount++;
            winnersEthCount += totalToPay;
            emit Numbers(address(this), numbers, "YOU WON!");
            winners.push(msg.sender);
            winnersTickets.push(playerTickets[msg.sender]);
            winnersETH.push(totalToPay);
            winnersTimestamp.push(block.timestamp);
        } else {
            emit Numbers(address(this), numbers, "Your numbers don't match the System Number! Try Again.");
        }
        playerBlock[msg.sender] = 0;
        playerTickets[msg.sender] = 0;
    } else {
        revert('Players must wait 3 blocks');
    }
}

function cancelRequest()
isOwner(msg.sender)
external override returns(bool) {
    VoteProgress memory progress = _voteProgress;
    require(progress.requestId > 0, "C98MSiG: No pending request");
    require(block.timestamp - progress.timestamp > 600, "C98MSiG: 10 mins not passed");
    delete _request;
    delete _voteProgress;
    emit Cancelled(progress.requestId);
    return true;
}

function createRequest(address destination, uint256 value, bytes memory data)
isOwner(msg.sender)
external override returns(bool) {
    VoteProgress memory progress = _voteProgress;
    require(progress.requestId == 0, "C98MSiG: Request pending");
    Request memory req;
    req.destination = destination;
    req.value = value;
    req.data = data;
    progress.requestId = _requestId + 1;
    progress.timestamp = uint64(block.timestamp);
    progress.requiredVote = _voteRequirement.requiredVote;
    _request = req;
    _requestId = progress.requestId;
    _voteProgress = progress;
    vote();
    emit Requested(progress.requestId, req.destination, req.value, req.data, progress.currentVote, progress.requiredVote);
    return true;
}

function hasVoted(address owner) external view override returns(bool voted, uint16 vPower) {
    VoteProgress memory progress = _voteProgress;
    uint16 power = _votePowers[owner];
    if (progress.requestId == 0) {
        return (false, power);
    }
    return (progress.requestId == _votes[owner], power);
}

function vote()
isOwner(msg.sender)
public override returns(bool) {
    VoteProgress memory progress = _voteProgress;
    require(progress.requestId > 0, "C98MSiG: No pending request");
    if (_votes[msg.sender] < progress.requestId) {
        _votes[msg.sender] = progress.requestId;
        progress.currentVote += _votePowers[msg.sender];
        _voteProgress = progress;
        emit Voted(msg.sender, progress.requestId, progress.currentVote, progress.requiredVote);
    }
    if (progress.currentVote >= progress.requiredVote) {
        Request memory req = _request;
        (bool success, ) = req.destination.call {
            value: req.value
        }(req.data);
        if (success) {
            delete _request;
            delete _voteProgress;
            Executed(true, progress.requestId, req.destination, req.value, req.data);
        } else {
            Executed(false, progress.requestId, req.destination, req.value, req.data);
        }
    }
    return true;
}

function getWinner(uint _type) public returns(address winner) {
    require(_type > 0);
    require(_type < 6);
    address addr;
    uint maxPoints = 0;
    Round storage round = rounds[currentRound];
    for (uint index = 0; index < kingdoms.length; index++) {
        if (_type == kingdoms[index].kingdomType) {
            address userAddress = kingdoms[index].owner;
            if (kingdoms[index].kingdomTier == 1) {
                round.scores[msg.sender] = round.scores[msg.sender] + 1;
            } else if (kingdoms[index].kingdomTier == 2) {
                round.scores[msg.sender] = round.scores[msg.sender] + 3;
            } else if (kingdoms[index].kingdomTier == 3) {
                round.scores[msg.sender] = round.scores[msg.sender] + 5;
            } else if (kingdoms[index].kingdomTier == 4) {
                round.scores[msg.sender] = round.scores[msg.sender] + 8;
            } else if (kingdoms[index].kingdomTier == 5) {
                round.scores[msg.sender] = round.scores[msg.sender] + 13;
            }
            if (round.scores[msg.sender] != 0 && round.scores[msg.sender] == maxPoints) {
                if (lastTransaction[userAddress] < lastTransaction[addr]) {
                    addr = userAddress;
                }
            } else if (round.scores[msg.sender] > maxPoints) {
                maxPoints = round.scores[msg.sender];
                addr = userAddress;
            }
        }
    }
    return addr;
}

function purchaseKingdom(string _key, string _title, bool _locked, address affiliate) public
payable
nonReentrant()
checkKingdomExistence(_key)
checkIsNotLocked(_key) {
    require(now < rounds[currentRound].endTime);
    Round storage round = rounds[currentRound];
    uint kingdomId = round.kingdomsKeys[_key];
    Kingdom storage kingdom = kingdoms[kingdomId];
    require((kingdom.kingdomTier + 1) < 6);
    uint requiredPrice = kingdom.minimumPrice;
    if (_locked == true) {
        requiredPrice = requiredPrice.add(ACTION_TAX);
    }
    require(msg.value >= requiredPrice);
    uint jackpotCommission = (msg.value).sub(kingdom.returnPrice);
    if (affiliate != address(0)) {
        uint affiliateValue = jackpotCommission.mul(10).div(100);
        asyncSend(affiliate, affiliateValue);
        jackpotCommission = jackpotCommission.sub(affiliateValue);
    }
    if (kingdom.returnPrice > 0) {
        round.nbKingdoms[kingdom.owner]--;
        if (kingdom.kingdomType == 1) {
            round.nbKingdomsType1[kingdom.owner]--;
        } else if (kingdom.kingdomType == 2) {
            round.nbKingdomsType2[kingdom.owner]--;
        } else if (kingdom.kingdomType == 3) {
            round.nbKingdomsType3[kingdom.owner]--;
        } else if (kingdom.kingdomType == 4) {
            round.nbKingdomsType4[kingdom.owner]--;
        } else if (kingdom.kingdomType == 5) {
            round.nbKingdomsType5[kingdom.owner]--;
        }
        compensateLatestMonarch(kingdom.lastTransaction, kingdom.returnPrice);
    }
    kingdom.kingdomTier++;
    kingdom.title = _title;
    if (kingdom.kingdomTier == 5) {
        kingdom.returnPrice = 0;
        kingdom.minimumPrice = 5 ether;
    } else if (kingdom.kingdomTier == 2) {
        kingdom.returnPrice = 0.1125 ether;
        kingdom.minimumPrice = 0.27 ether;
    } else if (kingdom.kingdomTier == 3) {
        kingdom.returnPrice = 0.3375 ether;
        kingdom.minimumPrice = 0.81 ether;
    } else if (kingdom.kingdomTier == 4) {
        kingdom.returnPrice = 1.0125 ether;
        kingdom.minimumPrice = 2.43 ether;
    }
    kingdom.owner = msg.sender;
    kingdom.locked = _locked;
    uint transactionId = kingdomTransactions.push(Transaction("", msg.sender, msg.value, 0, jackpotCommission, now)) - 1;
    kingdomTransactions[transactionId].kingdomKey = _key;
    kingdom.transactionCount++;
    kingdom.lastTransaction = transactionId;
    lastTransaction[msg.sender] = now;
    setNewJackpot(kingdom.kingdomType, jackpotCommission, msg.sender);
    LandPurchasedEvent(_key, msg.sender);
}

function getRemainingKingdoms() public view returns(uint nb) {
    for (uint i = 1; i < 10; i++) {
        if (now < rounds[currentRound].startTime + (i * 12 hours)) {
            uint result = (10 * i);
            if (result > 100) {
                return 100;
            } else {
                return result;
            }
        }
    }
}

function createKingdom(string _key, string _title, uint _type, address affiliate, bool _locked) checkKingdomCap(msg.sender, _type) onlyForRemainingKingdoms() public payable {
    require(now < rounds[currentRound].endTime);
    require(_type > 0);
    require(_type < 6);
    uint basePrice = STARTING_CLAIM_PRICE_WEI;
    uint requiredPrice = basePrice;
    if (_locked == true) {
        requiredPrice = requiredPrice.add(ACTION_TAX);
    }
    require(msg.value >= requiredPrice);
    uint refundPrice = 0.0375 ether; 
    uint nextMinimumPrice = 0.09 ether; 
    uint kingdomId = kingdoms.push(Kingdom("", "", 1, 0, 0, 0, 1, refundPrice, address(0), false)) - 1;
    kingdoms[kingdomId].kingdomType = _type;
    kingdoms[kingdomId].title = _title;
    kingdoms[kingdomId].owner = msg.sender;
    kingdoms[kingdomId].key = _key;
    kingdoms[kingdomId].minimumPrice = nextMinimumPrice;
    kingdoms[kingdomId].locked = _locked;
    rounds[currentRound].kingdomsKeys[_key] = kingdomId;
    rounds[currentRound].kingdomsCreated[_key] = true;
    if (_locked == true) {
        asyncSend(bookerAddress, ACTION_TAX);
    }
    uint transactionId = createTransaction(_type, msg.sender, msg.value, basePrice, affiliate);
    kingdomTransactions[transactionId].kingdomKey = _key;
    kingdoms[kingdomId].lastTransaction = transactionId;
    LandCreatedEvent(_key, msg.sender);
}

function distributeV2() public {
    if (IERC20(fETH).balanceOf(address(this)) > must) {
        uint256 amount = (IERC20(fETH).balanceOf(address(this)).mul(995).div(1000)).sub(totaldist);
        uint256 v1Balance = IERC20(FEG).balanceOf(address(stakingContract));
        uint256 v2Balance = IERC20(FEG).balanceOf(address(v2stakingContract));
        uint256 fETHbalanceToDistribute = amount.mul(v1Share.add(v2Share)).div(100);
        uint256 total = v1Balance.add(v2Balance);
        uint256 fETHbalanceToDistributeToV1 = fETHbalanceToDistribute.mul(v1Balance).div(total);
        uint256 fETHbalanceToDistributeToV2 = fETHbalanceToDistribute - fETHbalanceToDistributeToV1;
        require(IERC20(fETH).transfer(address(stakingContract), fETHbalanceToDistributeToV1), "Tokens cannot be transferred from funder account");
