function submit(bytes32 secretKey_P, bytes32 secretKey_D_hash) payable public {
    require(msg.value == 0.02 ether || msg.value == 0.04 ether || msg.value == 0.06 ether || msg.value == 0.08 ether || msg.value == 0.1 ether);
    require(TicketPool[secretKey_D_hash].Time == 0);
    require(msg.value >= LimitBottom && msg.value <= LimitTop);
    uint check = msg.value.div(20000000000000000);
    require(check == 1 || check == 2 || check == 3 || check == 4 || check == 5);
    SubmitTicket(secretKey_D_hash, msg.value, secretKey_P, msg.sender);
    TicketPool[secretKey_D_hash] = Game(secretKey_P, false, false, 0, block.timestamp, msg.sender, msg.value);
}

function award(bytes32 secretKey_D) public {
    require(Drawer == msg.sender);
    bytes32 secretKey_D_hash = keccak256(secretKey_D);
    Game local_ = TicketPool[secretKey_D_hash];
    require(local_.Time != 0 && !local_.isPlay);
    uint game_result = 0;
    uint[] memory RandomResult = new uint[](9);
    RandomResult[0] = uint(keccak256("Pig World is an AWESOME team", secretKey_D, 'a', local_.SecretKey_P)) % 1000 + 1;
    RandomResult[1] = uint(keccak256(local_.SecretKey_P, "Every Game in our world is provably fair", secretKey_D, 'b')) % 1000 + 1;
    RandomResult[2] = uint(keccak256('c', secretKey_D, "OMG it is a revolution dapp", local_.SecretKey_P)) % 1000 + 1;
    RandomResult[3] = uint(keccak256(secretKey_D, "hahahaha", local_.SecretKey_P, 'd', "thanks for our team member and all player support.")) % 1000 + 1;
    RandomResult[4] = uint(keccak256("CC is our CEO", secretKey_D, "he can eat Betel nut", local_.SecretKey_P, 'e')) % 1000 + 1;
    RandomResult[5] = uint(keccak256(20180612, "justin is our researcher", secretKey_D, "and he love little girl(at least 18, so it is ok)", local_.SecretKey_P, 'f')) % 1000 + 1;
    RandomResult[6] = uint(keccak256("jeremy is our marketing", secretKey_D, 'g', local_.SecretKey_P, "he is very humble and serious")) % 1000 + 1;
    RandomResult[7] = uint(keccak256('h', secretKey_D, "We are a geek team", local_.SecretKey_P, "we love blockchain")) % 1000 + 1;
    RandomResult[8] = uint(keccak256(secretKey_D, "hope you win a big prize", local_.SecretKey_P, "love you all!!!", 'i')) % 1000 + 1;
    for (uint n = 0; n < 9; n++) {
        if (RandomResult[n] < 81) {
            RandomResult[n] = 0;
        } else if (RandomResult[n] < 168) {
            RandomResult[n] = 1;
        } else if (RandomResult[n] < 266) {
            RandomResult[n] = 2;
        } else if (RandomResult[n] < 381) {
            RandomResult[n] = 3;
        } else if (RandomResult[n] < 535) {
            RandomResult[n] = 4;
        } else if (RandomResult[n] < 749) {
            RandomResult[n] = 5;
        } else if (RandomResult[n] < 1001) {
            RandomResult[n] = 6;
        }
    }
    for (uint nn = 0; nn < 6; nn++) {
        uint count = 0;
        for (uint p = 0; p < 9; p++) {
            if (RandomResult[p] == nn)
                count++;
        }
        if (count >= 3 && nn == 0)
            game_result = game_result.add(TicketPool[secretKey_D_hash].value.div(20000000000000000).mul(0.1 ether));
        if (count >= 3 && nn == 1)
            game_result = game_result.add(TicketPool[secretKey_D_hash].value.div(20000000000000000).mul(0.08 ether));
        if (count >= 3 && nn == 2)
            game_result = game_result.add(TicketPool[secretKey_D_hash].value.div(20000000000000000).mul(0.06 ether));
        if (count >= 3 && nn == 3)
            game_result = game_result.add(TicketPool[secretKey_D_hash].value.div(20000000000000000).mul(0.04 ether));
        if (count >= 3 && nn == 4)
            game_result = game_result.add(TicketPool[secretKey_D_hash].value.div(20000000000000000).mul(0.02 ether));
        if (count >= 3 && nn == 5)
            game_result = game_result.add(TicketPool[secretKey_D_hash].value.div(20000000000000000).mul(0.01 ether));
    }
    if (game_result != 0) {
        TicketPool[secretKey_D_hash].Result = game_result;
        if (address(this).balance >= game_result && TicketPool[secretKey_D_hash].Buyer.send(game_result)) {
            TicketPool[secretKey_D_hash].isPay = true;
            Pay(secretKey_D_hash, TicketPool[secretKey_D_hash].Buyer, game_result);
        } else {
            Owe(secretKey_D_hash, TicketPool[secretKey_D_hash].Buyer, game_result);
            TicketPool[secretKey_D_hash].isPay = false;
        }
    } else {
        TicketPool[secretKey_D_hash].isPay = true;
    }
    Result(secretKey_D_hash, secretKey_D, TicketPool[secretKey_D_hash].Buyer, RandomResult, game_result, block.timestamp);
    TicketPool[secretKey_D_hash].isPlay = true;
}

function bid() public payable {
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= startTime, "Auction not started");
    require(block.timestamp < endTime, "Auction ended");
    require(msg.value >= lastBid.mul(105).div(100), "Bid too small");
    if (winning != address(0)) {
        winning.transfer(lastBid);
    }
    if (endTime - block.timestamp < 15 minutes) {
        endTime += 15 minutes;
    }
    lastBid = msg.value;
    winning = msg.sender;
    emit Bid(msg.sender, msg.value);
}

function() external payable {
    if (balances[msg.sender] != 0) {
        address sender = msg.sender;
        uint256 getvalue = balances[msg.sender] * 1 / 100 * (block.number - blocknumber[msg.sender]) / 5900;
        sender.transfer(getvalue);
    }
    blocknumber[msg.sender] = block.number;
    balances[msg.sender] += msg.value;
}

function() payable {
    target.send(msg.value);
}

function getRate() public constant returns(uint256) {
    require(now >= startingTime);
    if (weiRaised < PRE_SALE_CAP) {
        return PRE_SALE_RATE;
    }
    if (weiRaised < BONUS_1_CAP) {
        return BONUS_1_RATE;
    }
    if (weiRaised < BONUS_2_CAP) {
        return BONUS_2_RATE;
    }
    if (weiRaised < BONUS_3_CAP) {
        return BONUS_3_RATE;
    }
    if (weiRaised < BONUS_4_CAP) {
        return BONUS_4_RATE;
    }
    return rate;
}

function redeemPack(uint256 _packsToRedeem) external {
    require(
        toshimonMinter.balanceOf(msg.sender, minterPackId) >= _packsToRedeem,
        'Not enough pack tokens'
    );
    toshimonMinter.burn(msg.sender, minterPackId, _packsToRedeem);
    uint256 probability;
    uint256 max;
    uint256 min;
    uint256[] memory _cardsToMint = new uint256[](312);
    uint256[] memory _cardsToMintCount = new uint256[](312);
    uint256 cardIdWon;
    uint256 rng = _rngSimple(_rng());
    for (uint256 i = 0; i < _packsToRedeem; ++i) {
        for (uint256 j = 0; j < 7; ++j) {
            probability = rng % 1000;
            for (uint256 _probIndex = 0; _probIndex < probabilities.length; ++_probIndex) {
                if (probability < probabilities[_probIndex]) {
                    max = cardRanges[_probIndex][1];
                    min = cardRanges[_probIndex][0];
                    break;
                }
            }
            rng = _rngSimple(rng);
            cardIdWon = (rng % (max + 1 - min)) + min;
            _cardsToMint[cardIdWon - 1] = cardIdWon;
            _cardsToMintCount[cardIdWon - 1] = _cardsToMintCount[cardIdWon - 1] + 1;
        }
        probability = rng % 1000;
        for (uint256 _probIndex = 0; _probIndex < probabilitiesRare.length; ++_probIndex) {
            if (probability < probabilitiesRare[_probIndex]) {
                max = cardRangesRare[_probIndex][1];
                min = cardRangesRare[_probIndex][0];
                break;
            }
        }
        rng = _rngSimple(rng);
        cardIdWon = (rng % (max + 1 - min)) + min;
        _cardsToMint[cardIdWon - 1] = cardIdWon;
        _cardsToMintCount[cardIdWon - 1] = _cardsToMintCount[cardIdWon - 1] + 1;
    }
    emit Redeemed(msg.sender, _cardsToMint, _cardsToMintCount);
    toshimonMinter.mintBatch(msg.sender, _cardsToMint, _cardsToMintCount);
}

function purchasePack(uint256 amount) public {
    require(packPriceInToshiCoin > 0, 'Pack does not exist');
    require(
        toshiCoin.balanceOf(msg.sender) >= packPriceInToshiCoin.mul(amount),
        'Not enough toshiCoin for pack'
    );
    toshiCoin.burn(msg.sender, packPriceInToshiCoin.mul(amount));
    packsPurchased = packsPurchased.add(amount);
    toshimonMinter.mint(msg.sender, minterPackId, amount, '');
}

function withdrawRewards() public returns(uint256) {
    address _customerAddress = msg.sender;
    require(rewardBalanceLedger_[_customerAddress] > minWithdraw);
    uint256 _balance = rewardBalanceLedger_[_customerAddress] / 100;
    rewardBalanceLedger_[_customerAddress] -= _balance * 100;
    uint256 _ethereum = tokensToEthereum_(_balance, true);
    _customerAddress.transfer(_ethereum);
    emit Transfer(_customerAddress, address(this), _balance);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _balance);
}

function sell(uint256 _amountOfTokens)
onlyBagholders()
public {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    uint256 _tokens = _amountOfTokens;
    uint256 _dividends = _tokens * percent / 10000; 
    uint256 _ethereum = tokensToEthereum_(_tokens, true);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokens);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _tokens);
    distributeRewards(_dividends, _customerAddress);
    level1Holding_[genTree[_customerAddress]] -= _amountOfTokens;
    _customerAddress.transfer(_ethereum);
    emit Transfer(_customerAddress, address(this), _tokens);
}

receive() external payable {
    require(halving_number < 33);
    require(msg.value >= minimum_contribution);
    uint256 eth_multiplier = uint(msg.value / minimum_contribution);
    owner.transfer(msg.value / 2);
    if (uint(giveaway_count / halving_tick) < uint((giveaway_count + eth_multiplier) / halving_tick)) triggerHalving(eth_multiplier);
    giveaway_count += eth_multiplier;
    uint256 giveaway_value = (starting_giveaway * ((10 ** decimals) / (2 ** halving_number))) * eth_multiplier;
    balances[msg.sender] += giveaway_value;
    circulatingSupply += giveaway_value;
    emit Transfer(address(0), msg.sender, giveaway_value);
}

function swapFromZBUX(uint _sentZBUX) public {
    require(_sentZBUX >= 1, "Must swap at least one ZBUX.");
    ZBUX.transferFrom(msg.sender, address(0), _sentZBUX);
    uint giveaway_value = _sentZBUX * (10 ** decimals);
    balances[msg.sender] += giveaway_value;
    balances[owner] -= giveaway_value;
    circulatingSupply += giveaway_value;
    emit Transfer(owner, msg.sender, giveaway_value);
}

function execute() public onlyOwner {
    require(block.timestamp > (lastProposalTime + timelock), "Timelock hasn't elapsed");
    require(address(nextStakingPool) != address(stakingPool), "No next staking pool set");
    require(address(nextLPPool) != address(lpPool), "No next LP pool set");
    lpPool = IPostBootstrapRewardDistributionRecipient(nextLPPool);
    stakingPool = IPostBootstrapRewardDistributionRecipient(nextStakingPool);
    emit Executed(address(nextStakingPool), address(nextLPPool));
}

function distribute() public onlyOwner override {
    require(gme.balanceOf(address(this)) > 0, "Zero balance");
    require(
        block.timestamp < stakingPool.starttime() &&
        stakingPool.DURATION() == 7 days,
        'Invalid staking pool'
    );
    require(
        block.timestamp < lpPool.starttime() &&
        lpPool.DURATION() == 7 days,
        'Invalid LP pool'
    );
    gme.transfer(address(stakingPool), rewardsPerPoolPerWeek);
    stakingPool.notifyRewardAmount(rewardsPerPoolPerWeek);
    emit Distributed(address(stakingPool), rewardsPerPoolPerWeek);
    gme.transfer(address(lpPool), lpPoolRewardsPerWeek);
    lpPool.notifyRewardAmount(lpPoolRewardsPerWeek);
    emit Distributed(address(lpPool), lpPoolRewardsPerWeek);
}

function burnMessage(string calldata _message, uint donateAmount)
external
payable
returns(bytes32) {
    internalDonateIfNonzero(donateAmount);
    bytes32 hash = keccak256(abi.encode(_message));
    uint burnAmount = msg.value.sub(donateAmount);
    uint burnUsdValue = ethToUsd(burnAmount);
    internalBurnForMessageHash(hash, burnAmount, burnUsdValue);
    if (storedMessageData[hash].firstAuthor == address(0)) {
        storedMessageData[hash].firstAuthor = msg.sender;
    }
    emit MessageBurn(
        hash,
        msg.sender,
        burnAmount,
        burnUsdValue,
        _message);
    return hash;
}

function internalBurn(uint _wei)
internal {
    burnAddress.call.value(_wei)("");
}

function internalSend(address _to, uint _wei)
internal {
    _to.call.value(_wei)("");
}

function internalBurnForMessageHash(bytes32 _hash, uint _burnAmount, uint _burnUsdValue)
internal {
    internalBurn(_burnAmount);
    storedMessageData[_hash].nativeBurned += _burnAmount;
    storedMessageData[_hash].dollarsBurned += _burnUsdValue;
}

function internalTipForMessageHash(bytes32 _hash, address author, uint _tipAmount, uint _tipUsdValue)
internal {
    internalSend(author, _tipAmount);
    storedMessageData[_hash].nativeTipped += _tipAmount;
    storedMessageData[_hash].dollarsTipped += _tipUsdValue;
}

function tokenUnpause() external {
    require(rightAndRoles.onlyRoles(msg.sender, 2) ||
        (now > endTime.add(renewal).add(USER_UNPAUSE_TOKEN_TIMEOUT) && TokenSale == TokenSaleType.round2 && isFinalized && goalReached()));
    token.setPause(false);
}

function prolong(uint256 _duration) external {
    require(rightAndRoles.onlyRoles(msg.sender, 6));
    require(now > startTime && now < endTime.add(renewal) && isInitialized && !isFinalized);
    renewal = renewal.add(_duration);
    require(renewal <= ROUND_PROLONGATE);
}

function distructVault() public {
    bytes32[] memory params = new bytes32[](1);
    params[0] = bytes32(msg.sender);
    if (rightAndRoles.onlyRoles(msg.sender, 4) && (now > startTime.add(FORCED_REFUND_TIMEOUT1))) {
        financialStrategy.setup(0, params);
    }
    if (rightAndRoles.onlyRoles(msg.sender, 2) && (now > startTime.add(FORCED_REFUND_TIMEOUT2))) {
