function withdraw(bytes calldata _proof, bytes32 _root, bytes32 _nullifierHash, address payable _recipient, address payable _relayer, uint256 _fee, uint256 _refund) external payable nonReentrant {
    require(_fee <= denomination, "Fee exceeds transfer value");
    require(!nullifierHashes[_nullifierHash], "The note has been already spent");
    require(isKnownRoot(_root), "Cannot find your merkle root"); 
    require(verifier.verifyProof(_proof, [uint256(_root), uint256(_nullifierHash), uint256(_recipient), uint256(_relayer), _fee, _refund]), "Invalid withdraw proof");
    nullifierHashes[_nullifierHash] = true;
    _processWithdraw(_recipient, _relayer, _fee, _refund);
    emit Withdrawal(_recipient, _nullifierHash, _relayer, _fee);
}

function burn(uint amount, address adminAddress) external payable {
    require(admins[adminAddress].isAdmin == true, 'only admin');
    require(msg.value >= transferFeeMinimum, "Transfer Fee needs to be higher than minimum");
    TransferHelper.safeTransferFrom(
        FDCContract, msg.sender, address(this), amount
    );
    TransferHelper.safeTransferETH(
        adminAddress, msg.value
    );
    uint transferRate = amount / 10;
    require(transferRate > 0, "Transfer Rate needs to be higher than the minimum");
    require(amount > transferRate, "Amount sent needs to be higher than the Transfer Rate");
    uint sendValue = amount - transferRate;
    if (feeModifier > 0) {
        uint fee = amount / feeModifier;
        require(fee > 0, "Fee needs to be higher than the minimum");
        TransferHelper.safeTransfer(
            FDCContract, adminAddress, fee
        );
        sendValue -= fee;
    }
    require((admins[adminAddress].limit >= sendValue), 'not enough admin limit');
    admins[adminAddress].limit -= sendValue;
    admins[adminAddress].approvedLimit += sendValue;
    balanceAdd(msg.sender, sendValue);
    emit TransferBridge(
        msg.sender,
        adminAddress,
        sendValue
    );
}

function getAvailableBalance(address sender) internal returns(uint balance) {
    if (frozenAccount[sender].isValue) {
        if (now < frozenAccount[sender].unlockStartTime) {
            return balances[sender] - frozenAccount[sender].amount;
        } else {
            uint unlockPercent = ((now - frozenAccount[sender].unlockStartTime) / frozenAccount[sender].unlockInterval + 1) * frozenAccount[sender].unlockPercent;
            if (unlockPercent > 100) {
                unlockPercent = 100;
            }
            assert(frozenAccount[sender].amount <= balances[sender]);
            uint available = balances[sender] - (100 - unlockPercent) * frozenAccount[sender].amount / 100;
            if (unlockPercent >= 100) {
                frozenAccount[sender].isValue = false;
                delete frozenAccount[sender];
            }
            return available;
        }
    }
    return balances[sender];
}

function transferAndFreeze(address target, uint256 value, uint unlockStartTime, uint unlockIntervalUnit, uint unlockInterval, uint unlockPercent) external onlyOwner freezeOutCheck(target, 0) {
    require(value > 0);
    require(frozenAccount[target].isValue == false);
    require(unlockStartTime > now);
    require(unlockInterval > 0);
    require(unlockPercent > 0 && unlockPercent <= 100);
    _transfer(msg.sender, target, value);
    uint unlockIntervalSecond = toSecond(unlockIntervalUnit, unlockInterval);
    frozenAccount[target] = Fund(value, unlockStartTime, unlockIntervalSecond, unlockPercent, true);
    emit FrozenFunds(target, value, unlockStartTime, unlockIntervalUnit, unlockInterval, unlockPercent);
}

function freezeAccount(address target, uint value, uint unlockStartTime, uint unlockIntervalUnit, uint unlockInterval, uint unlockPercent) external onlyOwner freezeOutCheck(target, 0) {
    require(value > 0);
    require(frozenAccount[target].isValue == false);
    require(balances[msg.sender] >= value);
    require(unlockStartTime > now);
    require(unlockInterval > 0);
    require(unlockPercent > 0 && unlockPercent <= 100);
    uint unlockIntervalSecond = toSecond(unlockIntervalUnit, unlockInterval);
    frozenAccount[target] = Fund(value, unlockStartTime, unlockIntervalSecond, unlockPercent, true);
    emit FrozenFunds(target, value, unlockStartTime, unlockIntervalUnit, unlockInterval, unlockPercent);
}

function fulfillRandomness(bytes32 requestId, uint256 randomness) internal override {
    uint256 startIndex = nftRecipientStart[requestId];
    uint256 endIndex = nftRecipientEnd[requestId];
    address recipient = IERC721(nftRecipientAddress[requestId]).ownerOf(randomness % (endIndex + 1 - startIndex) + startIndex);
    IERC721(rewardAddress[requestId]).transferFrom(
        address(this),
        recipient,
        rewardId[requestId]
    );
    emit RecipientSelected(rewardAddress[requestId], rewardId[requestId], recipient);
    delete nftRecipientAddress[requestId];
    delete nftRecipientStart[requestId];
    delete nftRecipientEnd[requestId];
}

function() public payable duringSale {
    uint _quantity = msg.value / tokenPrice;
    if (_quantity > tokensRemaining)
        _quantity = tokensRemaining;
    require(_quantity >= 1);
    uint _cost = safeMul(_quantity, tokenPrice);
    uint _refund = safeSub(msg.value, _cost);
    balances[msg.sender] = safeAdd(balances[msg.sender], _quantity);
    tokenSupply = safeAdd(tokenSupply, _quantity);
    tokensRemaining = safeSub(tokensRemaining, _quantity);
    if (_refund > 0)
        msg.sender.transfer(_refund);
    PaymentEvent(msg.sender, msg.value);
}

function endSale() public ownerOnly {
    require(beneficiary != 0);
    if (!beneficiary.call.gas(contractSendGas).value(this.balance)())
        revert();
    tokensRemaining = 0;
}

function preOrder(address _guestaddress, address _hostaddress, bytes32 _houseinfo, uint _from, uint _to, uint _days)
payable
public
returns(address _contractaddress) {
    uint transferPrice = _days * houseInfo[_houseinfo].price;
    transferPriceForTest = transferPrice;
    PreOrder preorder = new PreOrder(tokenAddress, _hostaddress, _guestaddress, _houseinfo, _from, _to, _days, 0, transferPrice);
    preOrderaddressfortest = preorder;
    if (Token(tokenAddress).transferFrom(_guestaddress, preorder, transferPrice)) 
    {
        PreOrders[_houseinfo].push(preorder);
        GuestOrders[_guestaddress].push(preorder);
        HouseOwnerOrders[_hostaddress].push(preorder);
        return address(preorder);
    } else {
        return;
    }
    return;
}

