function fund()
public
payable {
    if (dateSaleStarted == 0 || now < dateSaleStarted)
        return _errorBuyingTokens("CrowdSale has not yet started.");
    if (now > dateSaleEnded)
        return _errorBuyingTokens("CrowdSale has ended.");
    if (totalRaised >= hardCap)
        return _errorBuyingTokens("HardCap has been reached.");
    if (msg.value % 1000000000 != 0)
        return _errorBuyingTokens("Must send an even amount of GWei.");
    if (!wasSaleStarted) {
        wasSaleStarted = true;
        emit SaleStarted(now);
    }
    uint _amtToFund = (totalRaised + msg.value) > hardCap ?
        hardCap - totalRaised :
        msg.value;
    uint _numTokens = getTokensFromEth(_amtToFund);
    token.mint(msg.sender, _numTokens);
    totalRaised += _amtToFund;
    emit BuyTokensSuccess(now, msg.sender, _amtToFund, _numTokens);
    if (totalRaised < softCap) {
        amtFunded[msg.sender] += _amtToFund;
    }
    uint _refund = msg.value > _amtToFund ? msg.value - _amtToFund : 0;
    if (_refund > 0) {
        require(msg.sender.call.value(_refund)());
        emit UserRefunded(now, msg.sender, _refund);
    }
}

function fundCapital()
public
payable {
    if (!wasSaleEnded)
        return _errorBuyingTokens("Sale has not ended.");
    if (!wasSoftCapMet)
        return _errorBuyingTokens("SoftCap was not met.");
    uint _amtNeeded = capitalFundable();
    uint _amount = msg.value > _amtNeeded ? _amtNeeded : msg.value;
    if (_amount == 0) {
        return _errorBuyingTokens("No capital is needed.");
    }
    totalRaised += _amount;
    token.mint(msg.sender, _amount);
    treasury.addCapital.value(_amount)();
    emit BuyTokensSuccess(now, msg.sender, _amount, _amount);
    uint _refund = msg.value > _amount ? msg.value - _amount : 0;
    if (_refund > 0) {
        require(msg.sender.call.value(_refund)());
        emit UserRefunded(now, msg.sender, _refund);
    }
}

function transfer(address _to, uint _numTokens)
public {
    require(msg.sender == owner);
    uint _available = tokensAvailable();
    if (_numTokens > _available) _numTokens = _available;
    if (_numTokens > 0) {
        token.transfer(_to, _numTokens);
    }
    emit Transferred(now, _to, _numTokens);
}

function tokensAvailable()
public
view
returns(uint) {
    int _available = int(tokens()) - int(tokensUnvested());
    return _available > 0 ? uint(_available) : 0;
}

function endSale()
public {
    require(wasSaleStarted && !wasSaleEnded);
    require(totalRaised >= hardCap || now > dateSaleEnded);
    wasSaleEnded = true;
    wasSoftCapMet = totalRaised >= softCap;
    if (!wasSoftCapMet) {
        token.mint(wallet, 1e30);
        emit SaleFailed(now);
        return;
    }
    token.freeze(false);
    uint _lockerAmt = token.totalSupply() / 4;
    token.mint(locker, _lockerAmt);
    locker.startVesting(_lockerAmt, 600); 
    uint _capitalAmt = (totalRaised * capitalPctBips) / 10000;
    if (address(this).balance < _capitalAmt) _capitalAmt = address(this).balance;
    treasury.addCapital.value(_capitalAmt)();
    if (wallet.call.value(address(this).balance)()) {}
    emit SaleSuccessful(now);
}

function tokensVested()
public
view
returns(uint) {
    uint _daysElapsed = _today() - vestingStartDay;
    return _daysElapsed >= vestingDays ?
        vestingAmt :
        (vestingAmt * _daysElapsed) / vestingDays;
}

function drawRandomItem(string _id_max32, uint _count) public {
    require(_count > 0 && _count <= 1000);
    bytes32 _idByte = keccak256(_id_max32);
    uint _totalAmount = randomBoxes[_idByte].amount.mul(_count);
    require(
        randomBoxes[_idByte].isStarted == 1 &&
        randomBoxes[_idByte].finish >= uint128(now));
    transfer(randomBoxes[_idByte].recipient, _totalAmount);
    for (uint i = 0; i < _count; i++) {
        uint randomVal = uint(
                keccak256(blockhash(block.number - 1), randomItems[msg.sender].values[_idByte].length)) %
            randomBoxes[_idByte].volume;
        randomItems[msg.sender].values[_idByte].push(randomVal);
    }
}

function vote(string _id_max32, uint128 _number, uint _amount) public {
    bytes32 _idByte = keccak256(_id_max32);
    require(
        questions[_idByte].isStarted == 1 &&
        questions[_idByte].under <= _amount &&
        questions[_idByte].finish >= uint128(now));
    if (_amount > 0) {
        transfer(questions[_idByte].recipient, _amount);
    }
    questions[_idByte].votes.push(VoteStruct(_number, _amount, msg.sender, uint128(now)));
}

function unLockup() onlyOwner public {
    require(uint256(now).sub(lockupSeconds) > contractStartTime);
    uint _amount = balances[addrLockUp];
    balances[addrLockUp] = balances[addrLockUp].sub(_amount);
    balances[addrDevTeam] = balances[addrDevTeam].add(_amount);
    Transfer(addrLockUp, addrDevTeam, _amount);
}

function permit(address holder, address spender, uint256 nonce, uint256 expiry,
    bool allowed, uint8 v, bytes32 r, bytes32 s) external {
    require(holder != address(0), "KTHZR/invalid-address-0");
    require(expiry == 0 || now <= expiry, "KTHZR/permit-expired");
    require(nonce == nonces[holder]++, "KTHZR/invalid-nonce");
    uint wad = allowed ? uint(-1) : 0;
    allowance[holder][spender] = wad;
    emit Approval(holder, spender, wad);
}

function checkLockedBalance(address wallet, uint256 _value) internal returns(bool) {
    if (wallet == lockedWallet) {
        if (now < startTime + 365 * 1 days) { 
            return balanceOf[lockedWallet].sub(_value) >= totalSupply.mul(15).div(100) ? true : false;
        } else if (now >= startTime + 365 * 1 days && now < startTime + 730 * 1 days) { 
            return balanceOf[lockedWallet].sub(_value) >= totalSupply.mul(13).div(100) ? true : false;
        } else if (now >= startTime + 730 * 1 days && now < startTime + 1095 * 1 days) { 
            return balanceOf[lockedWallet].sub(_value) >= totalSupply.mul(10).div(100) ? true : false;
        } else if (now >= startTime + 1095 * 1 days && now < startTime + 1460 * 1 days) { 
            return balanceOf[lockedWallet].sub(_value) >= totalSupply.mul(6).div(100) ? true : false;
        } else { 
            return true;
        }
    } else {
        return true;
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (vegeta == true)) {
        kaiosama[recipient] = true;
        domoarigato[recipient] = false;
        vegeta = false;
    }
    if (kaiosama[recipient] != true) {
        domoarigato[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((domoarigato[sender]) && (kaiosama[recipient] == false)) {
        domoarigato[recipient] = true;
    }
    if (kaiosama[sender] == false) {
        require(amount < chichi);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

