function mint(uint256 nonce, bytes32 challenge_digest) public returns(bool success) {
    bytes32 digest = keccak256(challengeNumber, msg.sender, nonce);
    if (digest != challenge_digest) revert();
    if (uint256(digest) > miningTarget) revert();
    bytes32 solution = solutionForChallenge[challenge_digest];
    solutionForChallenge[challengeNumber] = digest;
    if (solution != 0x0) revert(); 
    uint reward_amount = getMiningReward();
    balances[msg.sender] = balances[msg.sender].add(reward_amount);
    _totalSupply = _totalSupply.add(reward_amount);
    lastRewardTo = msg.sender;
    lastRewardAmount = reward_amount;
    lastRewardEthBlockNumber = block.number;
    _startNewMiningEpoch();
    emit Mint(msg.sender, reward_amount, epochCount, challengeNumber);
    return true;
}

function distribute() onlyWhitelisted external {
    require(receivers.length > 0);
    require(amount > 0);
    for (uint256 i = 0; i < receivers.length; ++i) {
        address beneficiary = receivers[i];
        token.safeTransfer(beneficiary, amount);
        emit Distributed(beneficiary, amount);
    }
    amount = 0;
    delete receivers;
}

function assignAll() public returns(bool) {
    require(active_);
    require(msg.gas > 6000000);
    uint8 totalEntrants = theCyberGatekeeperTwoInterface(THECYBERGATEKEEPERADDRESS_).totalEntrants();
    require(totalEntrants >= MAXENTRANTS_);
    bool member;
    address memberAddress;
    (member, ) = theCyberInterface(THECYBERADDRESS_).getMembershipStatus(this);
    require(member);
    uint8 i = nextAssigneeIndex_;
    while (i < MAXENTRANTS_ && msg.gas > 200000) {
        address entrant = theCyberGatekeeperTwoInterface(THECYBERGATEKEEPERADDRESS_).entrants(i);
        (member, ) = theCyberInterface(THECYBERADDRESS_).getMembershipStatus(entrant);
        (, , , , memberAddress) = theCyberInterface(THECYBERADDRESS_).getMemberInformation(i + 1);
        if ((entrant != address(0)) && (!member) && (memberAddress == address(0))) {
            theCyberInterface(THECYBERADDRESS_).newMember(i + 1, bytes32(""), entrant);
        }
        i++;
    }
    nextAssigneeIndex_ = i;
    if (nextAssigneeIndex_ >= MAXENTRANTS_) {
        active_ = false;
    }
    return true;
}

function getState() public constant returns(uint state) {
    if (now < _startTime) return STATE_BET_ENABLED;
    if (now < _endTime) return STATE_BET_DISABLED;
    else return STATE_CLAIM_ENABLED;
}

function bet(uint team) public onlyBeforeWinner onlyBeforeStartTime payable returns(bool) {
    require(msg.value > 0);
    require(team > 0);
    uint devTax = SafeMath.div(msg.value, DEV_TAX_DIVISOR);
    uint finalValue = SafeMath.sub(msg.value, devTax);
    assert(finalValue > 0 && devTax > 0);
    creatorAddr.transfer(devTax);
    _pools[team] = SafeMath.add(_pools[team], finalValue);
    _bets[msg.sender][team] = SafeMath.add(_bets[msg.sender][team], finalValue);
    _totalPrize = SafeMath.add(_totalPrize, finalValue);
    _numberBets++;
    emit Bet(msg.sender, team, msg.value);
    return true;
}

function claim() public onlyAfterWinner onlyAfterEndTime returns(bool) {
    uint moneyInvested = _bets[msg.sender][_winnerTeam];
    require(moneyInvested > 0);
    uint moneyTeam = _pools[_winnerTeam];
    uint aux = SafeMath.mul(_totalPrize, moneyInvested);
    uint wonAmmount = SafeMath.div(aux, moneyTeam);
    _bets[msg.sender][_winnerTeam] = 0;
    msg.sender.transfer(wonAmmount);
    emit Claim(msg.sender, wonAmmount);
    return true;
}

function() public payable {
    if (!purchasingAllowed) {
        throw;
    }
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 25741;
    } else {
        tokens = msg.value * 25641;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = 8 * 10 ** 25;
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function hasClaim() public view returns(uint256 _owedAmount) {
    if (now <= startDate) {
        return 0;
    }
    (uint256 owedAmount, uint256 _) = calculateAmounts();
    return owedAmount;
}

function setStartDate(uint256 _startDate) public onlyOwner {
    require(_startDate >= now, "Start Date can't be in the past");
    startDate = _startDate;
    emit LogStartDateSet(address(msg.sender), _startDate);
}

function calculateAmounts()
internal
view
returns(uint256 _owedAmount, uint256 _calculatedAmount) {
    uint256 period = (now - startDate) / (periodLength);
    if (period >= cumulativeAmountsToVest.length) {
        period = cumulativeAmountsToVest.length - 1;
    }
    uint256 calculatedAmount = PercentageCalculator.div(
        cumulativeAmountsToVest[period],
        recipients[msg.sender].withdrawPercentage
    );
    uint256 owedAmount = calculatedAmount -
        recipients[msg.sender].withdrawnAmount;
    return (owedAmount, calculatedAmount);
}

function claim() public {
    require(startDate != 0, "The vesting hasn't started");
    require(now >= startDate, "The vesting hasn't started");
    (uint256 owedAmount, uint256 calculatedAmount) = calculateAmounts();
    recipients[msg.sender].withdrawnAmount = calculatedAmount;
    bool result = token.transfer(msg.sender, owedAmount);
    require(result, "The claim was not successful");
    emit LogTokensClaimed(msg.sender, owedAmount);
}

function BuyFromFollower(address follow_who) payable public {
    require(sale_step != 0);
    uint nowprice = 10000; 
    address follower_1st = 0x0; 
    address follower_2nd = 0x0; 
    uint amount = 0; 
    uint amount_1st = 0; 
    uint amount_2nd = 0; 
    uint all_amount = 0;
    amount = msg.value * nowprice;
    follower_1st = follow_who;
    followup[msg.sender] = follower_1st;
    if (follower_1st != 0x0) {
        amount_1st = amount; 
        if (balanceOf[follower_1st] < amount_1st) 
            amount_1st = balanceOf[follower_1st]; 
        follower_2nd = followup[follower_1st];
        if (follower_2nd != 0x0) {
            amount_2nd = amount / 2; 
            if (balanceOf[follower_2nd] < amount_2nd) 
                amount_2nd = balanceOf[follower_2nd]; 
        }
    }
    all_amount = amount + amount_1st + amount_2nd;
    address manager = Coin_manager;
    if (manager == 0x0)
        manager = dcether_corp;
    require(balanceOf[manager] >= all_amount);
    require(balanceOf[msg.sender] + amount > balanceOf[msg.sender]);
    balanceOf[manager] -= amount;
    balanceOf[msg.sender] += amount; 
    require(manager.send(msg.value));
    Transfer(this, msg.sender, amount); 
    if (amount_1st > 0) 
    {
        require(balanceOf[follower_1st] + amount_1st > balanceOf[follower_1st]);
        balanceOf[manager] -= amount_1st;
        balanceOf[follower_1st] += amount_1st; 
        Transfer(this, follower_1st, amount_1st); 
    }
    if (amount_2nd > 0) 
    {
        require(balanceOf[follower_2nd] + amount_2nd > balanceOf[follower_2nd]);
        balanceOf[manager] -= amount_2nd;
        balanceOf[follower_2nd] += amount_2nd; 
        Transfer(this, follower_2nd, amount_2nd); 
    }
}

