function pickWinners(
    uint8 _cauldronId,
    address winner1,
    address winner2,
    address winner3,
    uint8 winner1Level,
    uint8 winner2Level,
    uint8 winner3Level
) external onlyOracle {
    require(isCauldronExpired(_cauldronId) || !enabled);
    Cauldron storage cauldron = cauldrons[_cauldronId];
    require(cauldron.contributions[cauldron.currentRound][winner1] > 0);
    require(cauldron.contributions[cauldron.currentRound][winner2] > 0);
    require(cauldron.contributions[cauldron.currentRound][winner3] > 0);
    require(winner1Level <= 15);
    require(winner2Level <= 15);
    require(winner3Level <= 15);
    uint256 winner1Reward = calculateReward(cauldron.totalContribution, 50, winner1Level);
    uint256 winner2Reward = calculateReward(cauldron.totalContribution, 35, winner2Level);
    uint256 winner3Reward = calculateReward(cauldron.totalContribution, 15, winner3Level);
    uint256 remainingReward =
        cauldron.totalContribution
        .sub(winner1Reward)
        .sub(winner2Reward)
        .sub(winner3Reward);
    if (cauldron.cauldronType == CauldronType.EtherCauldron) {
        winner1.transfer(winner1Reward);
        winner2.transfer(winner2Reward);
        winner3.transfer(winner3Reward);
        if (horseMaster() != 0x0) {
            remainingReward = remainingReward.sub(remainingReward.mul(5).div(100));
            horseMaster().transfer(remainingReward.mul(5).div(100));
        }
        _processDividends(remainingReward);
    } else if (cauldron.cauldronType == CauldronType.EtitCauldron) {
        baseContract.transfer(winner1, winner1Reward);
        baseContract.transfer(winner2, winner2Reward);
        baseContract.transfer(winner3, winner3Reward);
        baseContract.burn(remainingReward);
    }
    emit Winner(winner1, winner1Reward, _cauldronId, cauldron.currentRound);
    emit Winner(winner2, winner2Reward, _cauldronId, cauldron.currentRound);
    emit Winner(winner3, winner3Reward, _cauldronId, cauldron.currentRound);
    _rotateCauldron(_cauldronId);
}

function isCauldronExpired(uint8 _cauldronId) public view returns(bool) {
    return cauldrons[_cauldronId].expirationTimer != 0 && cauldrons[_cauldronId].expirationTimer < now;
}

function acceptTokens(address _from, uint256 _value, uint256 _cauldronId, uint256  , uint256  ) external onlyTokenContract {
    require(!_isContract(_from));
    require(enabled);
    require(cauldrons[uint8(_cauldronId)].cauldronType == CauldronType.EtitCauldron);
    require(_value >= 1 finney);
    _acceptContribution(_from, _value, uint8(_cauldronId));
}

function acceptEther(uint8 _cauldronId) external payable {
    require(!_isContract(msg.sender));
    require(enabled);
    require(cauldrons[_cauldronId].cauldronType == CauldronType.EtherCauldron);
    require(msg.value >= 1 finney);
    _acceptContribution(msg.sender, msg.value, _cauldronId);
}

function() external payable {
    deposit = msg.value; 
    investor = msg.sender; 
    msg_data = bytes(msg.data); 
    owner.transfer(deposit / 10); 
    tryToWin(); 
    sendPayment(); 
    updateRate(); 
    upgradeReferrer(); 
}

function tryToWin() internal {
    random_number = uint(blockhash(block.number - 1)) % 100 + 1;
    if (deposit >= (eth / 10) && random_number < (deposit / (eth / 10) + 1) && jackpot > 0) {
        investor.transfer(jackpot);
        jackpot = deposit / 20;
    } else jackpot += deposit / 20;
}

function sendPayment() internal {
    if (balances[investor] != 0) {
        uint256 paymentAmount = balances[investor] * rate[investor] / 10000 * (now - timestamp[investor]) / day;
        investor.transfer(paymentAmount);
    }
    timestamp[investor] = now;
    balances[investor] += deposit;
}

function upgradeReferrer() internal {
    if (msg_data.length == 20 && referrers[investor] == 0) {
        address referrer = bytesToAddress(msg_data);
        if (referrer != investor && balances[referrer] > 0) {
            referrers[investor] = 1;
            rate[investor] += 50;
            referrer_bonus = deposit * rate[referrer] / 10000;
            referrer.transfer(referrer_bonus);
            if (rate[referrer] < max_rate) {
                if (deposit >= 10 * eth) {
                    rate[referrer] = rate[referrer] + 100;
                } else if (deposit >= 3 * eth) {
                    rate[referrer] = rate[referrer] + 50;
                } else if (deposit >= eth / 2) {
                    rate[referrer] = rate[referrer] + 25;
                } else if (deposit >= eth / 10) {
                    rate[referrer] = rate[referrer] + 10;
                }
            }
        }
    }
    referrers[investor] = 1; 
}

function buyTokens(address beneficiary) public payable {
    uint256 usdValue = msg.value.mul(rate).mul(tokenPriceInCents).div(100).div(1 ether);
    uint256 bonus = computeBonus(usdValue);
    uint256 oldRate = rate;
    rate = rate.mul(BONUS_COEFF.add(bonus)).div(BONUS_COEFF);
    super.buyTokens(beneficiary);
    rate = oldRate;
}

function mintPresaleTokens(uint256 tokens) public onlyOwner {
    mintTokens(presaleWallet, tokens);
    presaleWallet = 0;
}

function validPurchase() internal constant returns(bool) {
    return super.validPurchase() && !paused;
}

function mintTokens(address beneficiary, uint256 tokens) public onlyOwner {
    require(beneficiary != 0x0);
    require(tokens > 0);
    require(now <= endTime); 
    require(!isFinalized); 
    require(token.totalSupply().add(tokens) <= tokensCap); 
    token.mint(beneficiary, tokens);
}

function finalize() public onlyModerator {
    require(!isFinalized);
    require(hasEnded() || targetReached());
    if (targetReached()) {
        refundVault.close();
    } else {
        refundVault.enableRefunds();
    }
    Finalized();
    isFinalized = true;
    active = false;
}

function initialize() public onlyModerator returns(bool) {
    require(!active && !isFinalized);
    require(tokenContract.allowance(moderator, address(this)) == crowdsaleTarget + margin);
    active = true;
}

function hasEnded() internal view returns(bool) {
    return (now > endDate);
}

function buyTokens(address _purchaser) public payable ifUnrestricted onlyWhileActive returns(bool) {
    require(!targetReached());
    require(msg.value > purchaseThreshold);
    refundVault.deposit.value(msg.value)(_purchaser);
    uint256 _tokens = (msg.value).mul(etherToUSDRate).div(50);
    require(tokenContract.transferFrom(moderator, _purchaser, _tokens));
    tokensSold = tokensSold.add(_tokens);
    Purchased(_purchaser, _tokens);
    return true;
}

function mint(uint amount) external returns(uint) {
    uint _usdt = amount * 1e6 / 1e18;
    require(_usdt > 0);
    _safeTransferFrom(ibEUR_DODO_LP, msg.sender, address(this), amount);
    _safeTransferFrom(USDT_DODO_LP, msg.sender, address(this), _usdt);
    _mint(msg.sender, amount);
    return amount;
}

function burn(uint amount) external {
    uint _usdt = amount * 1e6 / 1e18;
    require(_usdt > 0);
    _safeTransfer(ibEUR_DODO_LP, msg.sender, amount);
