function queueTransaction(
    address target,
    address lev,
    uint256 amount,
    uint256 eta
) external returns(bytes32) {
    require(
        msg.sender == admin,
        "Timelock::queueTransaction: Call must come from admin."
    );
    require(
        eta >= getBlockTimestamp().add(delay),
        "Timelock::queueTransaction: Estimated execution block must satisfy delay."
    );
    bytes32 txHash = keccak256(abi.encode(target, lev, amount, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, lev, amount, eta);
    return txHash;
}

function setPendingAdmin(address pendingAdmin_, uint256 eta) external {
    require(
        msg.sender == admin,
        "Timelock::queueTransaction: Call must come from admin."
    );
    require(
        pendingAdmin_ != address(0),
        "Timelock::queueTransaction: Cannot change the admin to the zero address"
    );
    require(
        eta >= getBlockTimestamp().add(delay),
        "Timelock::queueTransaction: Estimated execution block must satisfy delay."
    );
    bytes32 txHash = keccak256(abi.encode(pendingAdmin_, eta));
    queuedTransactions[txHash] = true;
    emit NewPendingAdmin(pendingAdmin_);
}

function executeTransaction(
    address target,
    address lev,
    uint256 amount,
    uint256 eta
) external {
    require(
        msg.sender == admin,
        "Timelock::executeTransaction: Call must come from admin."
    );
    bytes32 txHash = keccak256(abi.encode(target, lev, amount, eta));
    require(
        queuedTransactions[txHash],
        "Timelock::executeTransaction: Transaction hasn't been queued."
    );
    require(
        getBlockTimestamp() >= eta,
        "Timelock::executeTransaction: Transaction hasn't surpassed time lock."
    );
    require(
        getBlockTimestamp() <= eta.add(GRACE_PERIOD),
        "Timelock::executeTransaction: Transaction is stale."
    );
    queuedTransactions[txHash] = false;
    bool success = ILev(lev).transfer(target, amount);
    require(
        success,
        "Timelock::executeTransaction: Transaction execution reverted."
    );
    emit ExecuteTransaction(txHash, target, lev, amount, eta);
}

function acceptAdmin(address pendingAdmin_, uint256 eta) external {
    require(
        msg.sender == admin,
        "Timelock::queueTransaction: Call must come from admin."
    );
    require(
        getBlockTimestamp() >= eta,
        "Timelock::executeTransaction: Transaction hasn't surpassed time lock."
    );
    bytes32 txHash = keccak256(abi.encode(pendingAdmin_, eta));
    require(
        queuedTransactions[txHash],
        "Timelock::executeTransaction: Transaction hasn't been queued."
    );
    queuedTransactions[txHash] = false;
    admin = pendingAdmin_;
    emit NewAdmin(admin);
}

function executeSubscription(
    address from, 
    address to, 
    address tokenAddress, 
    uint256 tokenAmount, 
    uint256 periodSeconds, 
    uint256 gasPrice, 
    uint256 nonce, 
    bytes signature 
)
public
returns(bool success) {
    bytes32 subscriptionHash = getSubscriptionHash(
        from, to, tokenAddress, tokenAmount, periodSeconds, gasPrice, nonce
    );
    address signer = getSubscriptionSigner(subscriptionHash, signature);
    require(to != from, "Can not send to the from address");
    require(signer == from, "Invalid Signature");
    require(
        block.timestamp >= nextValidTimestamp[subscriptionHash],
        "Subscription is not ready"
    );
    require(requiredToAddress == address(0) || to == requiredToAddress);
    require(requiredTokenAddress == address(0) || tokenAddress == requiredTokenAddress);
    require(requiredTokenAmount == 0 || tokenAmount == requiredTokenAmount);
    require(requiredPeriodSeconds == 0 || periodSeconds == requiredPeriodSeconds);
    require(requiredGasPrice == 0 || gasPrice == requiredGasPrice);
    nextValidTimestamp[subscriptionHash] = block.timestamp.add(periodSeconds);
    if (nonce > extraNonce[from]) {
        extraNonce[from] = nonce;
    }
    ERC20(tokenAddress).transferFrom(from, to, tokenAmount);
    require(
        checkSuccess(),
        "Subscription::executeSubscription TransferFrom failed"
    );
    emit ExecuteSubscription(
        from, to, tokenAddress, tokenAmount, periodSeconds, gasPrice, nonce
    );
    if (gasPrice > 0) {
        ERC20(tokenAddress).transferFrom(from, msg.sender, gasPrice);
        require(
            checkSuccess(),
            "Subscription::executeSubscription Failed to pay gas as from account"
        );
    }
    return true;
}

function isSubscriptionActive(
    bytes32 subscriptionHash,
    uint256 gracePeriodSeconds
)
external
view
returns(bool) {
    return (block.timestamp <=
        nextValidTimestamp[subscriptionHash].add(gracePeriodSeconds)
    );
}

function isSubscriptionReady(
    address from, 
    address to, 
    address tokenAddress, 
    uint256 tokenAmount, 
    uint256 periodSeconds, 
    uint256 gasPrice, 
    uint256 nonce, 
    bytes signature 
)
external
view
returns(bool) {
    bytes32 subscriptionHash = getSubscriptionHash(
        from, to, tokenAddress, tokenAmount, periodSeconds, gasPrice, nonce
    );
    address signer = getSubscriptionSigner(subscriptionHash, signature);
    uint256 allowance = ERC20(tokenAddress).allowance(from, address(this));
    uint256 balance = ERC20(tokenAddress).balanceOf(from);
    return (
        signer == from &&
        from != to &&
        block.timestamp >= nextValidTimestamp[subscriptionHash] &&
        allowance >= tokenAmount.add(gasPrice) &&
        balance >= tokenAmount.add(gasPrice)
    );
}

