function submitClaim(
    bytes32 blockHeader,
    bytes32 seedHash,
    bytes32 target,
    uint blockNumber,
    uint blockPayment,
    address payable miningPoolAddress,
    address mevProducerAddress,
    uint8 v,
    bytes32 r,
    bytes32 s,
    uint blockNonce,
    bytes32 mixDigest
) public {
    require(msg.sender == blockSubmissionsOperator[miningPoolAddress]);
    bytes32 hash = keccak256(abi.encodePacked(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress));
    if (claimedBlockNonce[hash] == 0 && blockNonce < FLAG_BLOCK_NONCE_LIMIT) {
        if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash)), v, r, s) == mevProducerAddress) {
            require(depositedEther[mevProducerAddress] >= blockPayment);
            claimedBlockNonce[hash] = FLAG_BLOCK_NONCE_LIMIT + blockNonce;
            claimedBlockMixDigest[hash] = mixDigest;
            depositedEther[mevProducerAddress] -= blockPayment;
            miningPoolAddress.transfer(blockPayment);
            emit BlockClaimed(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress, mevProducerAddress, blockNonce, mixDigest);
        }
    }
}

function withdraw(bool _onlyBonus) payable public {
    require(msg.value >= etherFee);
    uint256 bonus = querySelfBonus(msg.sender);
    DrawTime[msg.sender] = now;
    uint256 last = kolp.getLockInviteBonusLen(msg.sender);
    uint256 yestodayLastSecond = kolp.getYestodayLastSecond(now);
    uint256 lastingDays;
    if (last > 0) {
        dayInviteBonus memory theDayIB = dayInviteBonus(0, 0, 0);
        uint256 realLast = last;
        while (realLast >= 1) {
            (theDayIB.theDayLastSecond, theDayIB.theDayInviteBonus, theDayIB.totalInviteBonus) = kolp.LockInviteBonus(msg.sender, realLast - 1);
            realLast--;
            if (theDayIB.theDayLastSecond <= yestodayLastSecond) {
                lastingDays = (yestodayLastSecond - theDayIB.theDayLastSecond) / every;
                bonus += (lastingDays * theDayIB.theDayInviteBonus) + theDayIB.totalInviteBonus;
                if (theDayIB.theDayLastSecond < yestodayLastSecond) {
                    kolp.pushInvite(msg.sender, yestodayLastSecond, theDayIB.theDayInviteBonus, 0);
                } else if (theDayIB.theDayLastSecond == yestodayLastSecond) {
                    kolp.setLastInvite(msg.sender, theDayIB.theDayInviteBonus, 0);
                }
            }
        }
    }
    last = kolp.getLockTeamBonusLen(msg.sender);
    if (last > 0) {
        dayTeamBonus memory theDayTB = dayTeamBonus(0, 0, 0, 0);
        while (last >= 1) {
            (theDayTB.theDayLastSecond, theDayTB.theDayTeamBonus, theDayTB.totalTeamBonus, theDayTB.theDayRate) = kolp.LockTeamBonus(msg.sender, last - 1);
            last--;
            if (theDayTB.theDayLastSecond <= yestodayLastSecond) {
                lastingDays = (yestodayLastSecond - theDayTB.theDayLastSecond) / every;
                bonus += (lastingDays * theDayTB.theDayTeamBonus * theDayTB.theDayRate / 100) + theDayTB.totalTeamBonus;
                if (theDayTB.theDayLastSecond < yestodayLastSecond) {
                    kolp.pushTeam(msg.sender, yestodayLastSecond, theDayTB.theDayTeamBonus, 0, theDayTB.theDayRate);
                } else if (theDayTB.theDayLastSecond == yestodayLastSecond) {
                    kolp.setLastTeam(msg.sender, theDayTB.theDayTeamBonus, 0, theDayTB.theDayRate);
                }
            }
        }
    }
    uint256 realBonus = bonus;
    if (leftBonus == 0) {
        _onlyBonus = false;
        realBonus = 0;
    } else if (bonus >= leftBonus) {
        realBonus = leftBonus;
    }
    uint256 subLeft = realBonus;
    uint256 tax = realBonus * fee / 100;
    realBonus = realBonus.sub(tax);
    if (!_onlyBonus) {
        uint256 balance = kolp.LockBalance(msg.sender);
        if (bonus < minBonus) {
            realBonus = balance;
            tax = 0;
            subLeft = 0;
        } else {
            realBonus += balance;
        }
        kolp.subTotalBalance(balance);
        kolp.clearLock(msg.sender);
        afterWithdraw(msg.sender, balance);
    } else {
        require(bonus >= minBonus);
    }
    if (realBonus > 0) {
        kol.transfer(msg.sender, realBonus);
        TotalWithDraws[msg.sender] += realBonus;
        emit WithDrawed(msg.sender, realBonus);
    }
    if (tax > 0) kol.transfer(reciever, tax);
    leftBonus = leftBonus.sub(subLeft);
}

function draw() onlyOwner public {
    reciever.send(address(this).balance);
}

function queryInviteBonus(address _addr) public view returns(uint256) {
    uint256 last = kolp.getLockInviteBonusLen(_addr);
    if (last > 0) {
        uint256 yestodayLastSecond = kolp.getYestodayLastSecond(now);
        uint256 lastingDays;
        uint256 newDayInviteTotalBonus;
        dayInviteBonus memory theDayIB = dayInviteBonus(0, 0, 0);
        while (last >= 1) {
            (theDayIB.theDayLastSecond, theDayIB.theDayInviteBonus, theDayIB.totalInviteBonus) = kolp.LockInviteBonus(_addr, last - 1);
            last--;
            if (theDayIB.theDayLastSecond <= yestodayLastSecond) {
                lastingDays = (yestodayLastSecond - theDayIB.theDayLastSecond) / every;
                newDayInviteTotalBonus = (lastingDays * theDayIB.theDayInviteBonus) + theDayIB.totalInviteBonus;
                return (newDayInviteTotalBonus);
            }
        }
        return 0;
    } else
        return 0;
}

function calcuAllBonus(bool _onlyBonus) public view returns(uint256) {
    uint256 bonus = querySelfBonus(msg.sender);
    bonus += queryInviteBonus(msg.sender);
    bonus += queryTeamBonus(msg.sender);
    if (leftBonus == 0) {
        bonus = 0;
    } else if (bonus >= leftBonus) {
        bonus = leftBonus;
    }
    bonus = bonus * (100 - fee) / 100;
    if (!_onlyBonus) {
        uint256 balance = kolp.LockBalance(msg.sender);
        bonus += balance;
    }
    return bonus;
}

function queryTeamBonus(address _addr) public view returns(uint256) {
    uint256 last = kolp.getLockTeamBonusLen(_addr);
    if (last > 0) {
        uint256 yestodayLastSecond = kolp.getYestodayLastSecond(now);
        uint256 lastingDays;
        uint256 newDayTeamTotalBonus;
        dayTeamBonus memory theDayTB = dayTeamBonus(0, 0, 0, 0);
        while (last >= 1) {
            (theDayTB.theDayLastSecond, theDayTB.theDayTeamBonus, theDayTB.totalTeamBonus, theDayTB.theDayRate) = kolp.LockTeamBonus(_addr, last - 1);
            last--;
            if (theDayTB.theDayLastSecond <= yestodayLastSecond) {
                lastingDays = (yestodayLastSecond - theDayTB.theDayLastSecond) / every;
                newDayTeamTotalBonus = (lastingDays * theDayTB.theDayTeamBonus * theDayTB.theDayRate / 100) + theDayTB.totalTeamBonus;
                return (newDayTeamTotalBonus);
            }
        }
        return 0;
    } else
        return 0;
}

function querySelfBonus(address _addr) public view returns(uint256) {
    uint256 len = kolp.getLockLen(_addr);
    uint256 selfBonus;
    if (len > 0) {
        uint256 begin;
        uint256 end;
        uint256 amount;
        bool withDrawed;
        for (uint i = 0; i < len; i++) {
            (begin, amount, end, withDrawed) = kolp.LockHistory(_addr, i);
            if (!withDrawed) {
                if (DrawTime[_addr] > begin) begin = DrawTime[_addr];
                uint256 lastingDays = (kolp.getYestodayLastSecond(now) - kolp.getYestodayLastSecond(begin)) / every;
                if (kolp.USDTOrCoin(_addr)) {
                    begin = kolp.getYestodayLastSecond(begin) + every;
                    for (uint j = 0; j < lastingDays; j++) {
                        uint256 theTime = begin + j * every;
                        selfBonus += amount * 3 / 1000 * kolp.ClosePrice(begin) / kolp.ClosePrice(theTime);
                    }
                } else {
                    selfBonus += lastingDays * amount * 3 / 1000;
                }
            }
        }
    }
    return (selfBonus);
}

function sendSignal(bytes32 _register) public {
    uint signalValue = Token(token).balanceOf(msg.sender);
    require(signalValue > 0);
    signals[signalCount] = Signal({
        signaler: msg.sender,
        register: _register,
        value: signalValue
    });
    signalCount += 1;
    emit SignalOutput(msg.sender, _register, signalValue);
}

function airDrop(address parent, uint[] amounts, address[] droptargets) public payable {
    if (msg.value > 0) {
        buyTokens();
    }
    require(balances[msg.sender] >= droptargets.length, "Insufficient funds to execute this airdrop");
    ERC20TokenInterface parentContract = ERC20TokenInterface(parent);
    uint allowance = parentContract.allowance(msg.sender, flairdrop);
    uint amount = amounts[0];
    uint x = 0;
    address target;
    while (gasleft() > 21000 && x <= droptargets.length - 1) {
        target = droptargets[x];
        if (amounts.length == droptargets.length) {
            amount = amounts[x];
        }
        if (allowance >= amount) {
            parentContract.transferFrom(msg.sender, target, amount);
            allowance -= amount;
        }
        x++;
    }
    balances[msg.sender] -= x;
    totalSupply = totalSupply >= x ? totalSupply - x : 0;
    emit Transfer(msg.sender, address(0), x);
    emit AirDropEvent(parent, droptargets, amounts);
}

function buyTokens() public payable {
    address(manager).transfer(msg.value);
    uint tokensBought = msg.value.div(tokenPrice);
    balances[msg.sender] = balances[msg.sender].add(tokensBought);
    totalSupply += tokensBought;
    emit Transfer(address(this), msg.sender, tokensBought);
}

function placeABid() public payable {
    uint256 income = msg.value;
    require(income >= minBid, "Bid should be greater than min bid");
    uint256 ownerRevenue = income.mul(OWNER_REVENUE_PERCENT).div(100);
    uint256 realIncome = income.sub(ownerRevenue);
    require(ownerRevenue != 0 && realIncome != 0, "Income too small");
    currentBalance = currentBalance.add(realIncome);
    currentKing = msg.sender;
    lastKingBlock = block.number;
    blockDistance = blockDistance - 1;
    if (blockDistance < MIN_BLOCK_DISTANCE) {
        blockDistance = MIN_BLOCK_DISTANCE;
    }
    minBid = minBid.add(BID_INCRASE);
    _owner.transfer(ownerRevenue);
    emit NewKing(msg.sender, realIncome);
}

function claim() public payable {
    require(currentKing == msg.sender, "You are not king");
    require(currentBalance > 0, "The treasury is empty");
    require(block.number - lastKingBlock >= blockDistance, "You can pick up the reward only after waiting for the minimum time");
    currentKing.transfer(currentBalance);
    emit Winner(msg.sender, currentBalance);
    currentBalance = 0;
    currentKing = address(0x0);
    lastKingBlock = block.number;
    blockDistance = START_BLOCK_DISTANCE;
    minBid = 725000 gwei;
}

function flipCoin() public payable {
    require(msg.value > 1500 szabo && tx.origin == msg.sender);
    uint value = m_RandomGen.random(100, uint8(msg.value));
    if (value > 55) {
        msg.sender.transfer(msg.value * 2);
    }
    FlipCoinEvent(value, msg.sender);
}

