    require(msg.sender == owner || msg.sender == devWallet);
    require(softcapAchieved);
    if (!feePayed) {
        devWallet.transfer(devLimit.sub(18 ether));
        special.transfer(18 ether);
        feePayed = true;
    }
    wallet.transfer(this.balance);
}

function curQuater() public view returns(uint) {
    if (now > quater4)
        return 4;
    if (now > quater3)
        return 3;
    if (now > quater2)
        return 2;
    return 1;
}

function withdraw(address to) public onlyOwner {
    require(started);
    if (now >= endDate) {
        to.transfer(this.balance);
    } else {
        uint cQuater = curQuater();
        uint toTransfer = initialBalance.mul(availableAfterStart).div(percentRate);
        if (startQuater < 4 && cQuater > startQuater) {
            uint secondInitialBalance = initialBalance.sub(toTransfer);
            uint quaters = 4;
            uint allQuaters = quaters.sub(startQuater);
            uint value = secondInitialBalance.mul(cQuater.sub(startQuater)).div(allQuaters);
            toTransfer = toTransfer.add(value);
        }
        toTransfer = toTransfer.sub(withdrawed);
        to.transfer(toTransfer);
        withdrawed = withdrawed.add(toTransfer);
    }
}

function mintTokens(address to, uint tokens) internal {
    token.mint(to, tokens);
    minted = minted.add(tokens);
}

function finalize() afterDeadline {
    require(!crowdsaleEnded);
    tokenReward.burn(); 
    Finalize(tokenOwner, amountRaised);
    crowdsaleEnded = true;
}

function exchange(address receiver) payable {
    uint amount = msg.value;
    uint price = getPrice();
    uint numTokens = amount.mul(price);
    require(numTokens > 0);
    require(!crowdsaleEnded && current() >= start && current() <= end && tokensSold.add(numTokens) <= maxGoal);
    wallet.transfer(amount);
    balances[receiver] = balances[receiver].add(amount);
    amountRaised = amountRaised.add(amount);
    tokensSold = tokensSold.add(numTokens);
    assert(tokenReward.transferFrom(tokenOwner, receiver, numTokens));
    FundTransfer(receiver, amount, true, amountRaised);
}

function checkGoalReached() public afterDeadline {
    if (amountRaised >= fundingGoal) {
        emit GoalReached(beneficiary, amountRaised);
    } else {
        tokenReward.transfer(beneficiary, (fundingGoal - amountRaised) * 6 / price);
    }
    crowdsaleClosed = true;
}

function safeWithdrawal() public afterDeadline {
    if (beneficiary == msg.sender) {
        if (beneficiary.send(amountRemaining)) {
            amountRemaining = 0;
            emit FundTransfer(beneficiary, amountRemaining, false);
        }
    }
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 15000;
    } else {
        tokens = msg.value * 15000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    require(!_isBlacklisted[from] && !_isBlacklisted[to]);
    if (!tradingLive) {
        require(from == owner()); 
    }
    if (maxTXEnabled) {
        if (from != owner() && to != owner()) {
            require(amount <= _maxTxAmount, "Transfer amount exceeds the maxTxAmount.");
        }
    }
    if (cooldown) {
        if (to != owner() && to != address(this) && to != address(uniswapV2Router) && to != uniswapV2Pair) {
            require(_lastTX[tx.origin] <= (block.timestamp + 30 seconds), "Cooldown in effect");
            _lastTX[tx.origin] = block.timestamp;
        }
    }
    if (antiSnipe) {
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && to != address(this)) {
            require(tx.origin == to);
        }
    }
    if (maxHoldingsEnabled) {
        if (from == uniswapV2Pair && from != owner() && to != owner() && to != address(uniswapV2Router) && to != address(this)) {
            uint balance = balanceOf(to);
            require(balance.add(amount) <= _maxHoldings);
        }
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    if (contractTokenBalance >= _maxTxAmount) {
        contractTokenBalance = _maxTxAmount;
    }
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (overMinTokenBalance && !inSwapAndLiquify && from != uniswapV2Pair && swapAndLiquifyEnabled) {
        contractTokenBalance = numTokensSellToAddToLiquidity;
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    if (from == uniswapV2Pair && to != address(this) && to != address(uniswapV2Router)) {
        _spinach = 3;
        _liquidityMarketingFee = 10;
    } else {
        _spinach = 10;
        _liquidityMarketingFee = 3;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint256 tokensForLiq = (contractTokenBalance.div(5));
    uint256 half = tokensForLiq.div(2);
    uint256 toSwap = contractTokenBalance.sub(half);
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(toSwap);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    addLiquidity(half, newBalance);
    payable(_projWallet).transfer(address(this).balance);
    emit SwapAndLiquify(half, newBalance, half);
}

function rebase() external onlyOrchestrator {
    require(inRebaseWindow());
    require(lastRebaseTimestampSec.add(minRebaseTimeIntervalSec) < now);
    lastRebaseTimestampSec = now.sub(
        now.mod(minRebaseTimeIntervalSec)).add(rebaseWindowOffsetSec);
    epoch = epoch.add(1);
    uint256 targetRate;
    bool targetRateValid;
    (targetRate, targetRateValid) = targetPriceOracle.getData();
    require(targetRateValid);
    uint256 exchangeRate;
    bool rateValid;
    (exchangeRate, rateValid) = marketOracle.getData(); 
    require(rateValid);
    if (exchangeRate > MAX_RATE) {
        exchangeRate = MAX_RATE;
    }
    int256 supplyDelta = computeSupplyDelta(exchangeRate, targetRate);
    supplyDelta = supplyDelta.div(rebaseLag.toInt256Safe());
    if (supplyDelta > 0 && uFrags.totalSupply().add(uint256(supplyDelta)) > MAX_SUPPLY) {
        supplyDelta = (MAX_SUPPLY.sub(uFrags.totalSupply())).toInt256Safe();
    }
    uint256 supplyAfterRebase = uFrags.rebase(epoch, supplyDelta);
    assert(supplyAfterRebase <= MAX_SUPPLY);
    emit LogRebase(epoch, exchangeRate, targetRate, supplyDelta, now);
}

function purchase(uint256 amount) public payable {
    require(active == true && startTimestamp <= now, "Cannot buy: Sale not active yet");
    (uint256 currentRoundId, uint256 currentPrice, uint256 totalEggsSold, uint256 totalEggsAvailable) = getSaleRoundInfo();
    require(totalEggsAvailable > totalEggsSold, "Eggs sold out. Try again during the next round.");
    uint256 eggsAvailableNow = totalEggsAvailable.sub(totalEggsSold);
    require(msg.value == currentPrice * amount, "You need to send the exact NFT price");
    require(amount > 0, "Why would you want zero eggs");
    require(amount <= 5, "You cannot buy more than 5 Eggs at once");
    require(amount <= eggsAvailableNow, "You cannot buy more than the available amount");
    require(userBought24h(msg.sender).add(amount) <= 5, "You cannot purchase more than 5 NFTs in 24h");
    require(IERC1155(eggAddress).balanceOf(address(this), nftid) > amount, "Cannot buy: not enough Eggs!");
    salePeriods[currentRoundId].eggsSoldThisRound = salePeriods[currentRoundId].eggsSoldThisRound.add(amount);
    IERC1155(eggAddress).safeTransferFrom(address(this), msg.sender, nftid, amount, "");
    if (devWallet != address(0)) {
        devWallet.transfer(msg.value);
    }
    for (uint256 i = 0; i < amount; i++) {
        userPurchased[msg.sender][userNextPurchasedId[msg.sender]] = now;
        userNextPurchasedId[msg.sender] = userNextPurchasedId[msg.sender] + 1;
    }
}

function makeSwapInternal() private isNotPaused { 
    require(stage > 0 && stage < 3 && msg.value >= minAcceptedETH);
    Whitelist wl = Whitelist(whitelistAdd);
    if (stage == 1 || stage == 2) require(wl.registered(msg.sender));
    ERC223 GXVCtoken = ERC223(tokenAdd);
    address _address = msg.sender;
    uint _value = msg.value;
    uint _price = getPrice();
    uint tokensToSend = _price * _value / 10 ** 18;
    receivedFrom[_address] += _value;
    totalReceived += _value;
    sentTo[_address] += tokensToSend;
    totalSent = tokensToSend;
    require(GXVCtoken.transferFrom(tokenSpender, _address, tokensToSend));
    TokensSent(_address, _value, tokensToSend);
    require(collectorAddress.send(_value));
}

function calculatePrice(uint _when) constant public returns(uint _result) {
    if (_when == 0) _when = now;
    uint delay = (_when - initialTime) / 25;
    uint factor = delay * increasePerBlock;
    uint multip = initialPrice * factor;
    uint result = initialPrice - multip / increasePerBlockDiv / 100; 
    require(result <= initialPrice);
    return result;
}

function transferFrom(address _from, address _to, uint256 _value) public mintingFinished returns(bool) {
    require(_to != address(0x0));
    require(_to != address(this));
    if (lockups[_from] != 0) {
        require(now >= lockups[_from]);
    }
    uint256 allowance = allowed[_from][msg.sender];
    require(balances[_from] >= _value);
    require(allowance >= _value);
    assert(balances[_to] + _value >= balances[_to]); 
    allowed[_from][msg.sender] -= _value;
    balances[_from] -= _value;
    balances[_to] += _value;
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) public mintingFinished returns(bool) {
    require(_to != address(0x0));
    require(_to != address(this));
    if (lockups[msg.sender] != 0) {
        require(now >= lockups[msg.sender]);
    }
    require(balances[msg.sender] >= _value);
    assert(balances[_to] + _value >= balances[_to]); 
    balances[msg.sender] -= _value;
    balances[_to] += _value;
    Transfer(msg.sender, _to, _value);
    return true;
}

function payJosh() public {
    uint totalPayout = perSecondDaiParticlePayout * (now - createdAt);
    dai.transfer(josh, totalPayout - amountPaid);
    amountPaid = totalPayout;
}

function claim() external returns(bool) {
    require(block.timestamp > dateStart, "Initial vesting in progress");
    if (!_initialized[msg.sender]) {
        _init(msg.sender);
    }
    uint256 pct = 20;
    uint256 time = dateStart + 1 weeks;
    while (time < block.timestamp) {
        pct += 4;
        if (pct == 100) {
            break;
        }
        time += 1 weeks;
    }
    if (pct > _pctWithdrawn[msg.sender]) {
        uint256 thisTime = pct - _pctWithdrawn[msg.sender];
        if (pct > 59) {
            if (_pctWithdrawn[msg.sender] < 21) {
                _bonus[msg.sender] = 1;
                if (pct == 100 && thisTime > 79) {
                    _bonus[msg.sender] = 2;
                }
            }
        }
        uint256 amt = (_tokensTotal[msg.sender] * thisTime) / 100;
        _pctWithdrawn[msg.sender] += thisTime;
        return IContracts(token).transfer(msg.sender, amt);
    }
    return false;
}

