}

function hasEnded() public constant returns(bool) {
    if (currentTime() > endTimestamp)
        return true;
    if (tokenRaised >= tokensForSale)
        return true; 
    return false;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(transfersEnabled);
    require(parentSnapShotBlock < block.number);
    require(_to != address(0));
    require(_value <= allowed[_from][msg.sender]);
    uint256 lastBalance = balanceOfAt(_from, block.number);
    require(_value <= lastBalance);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    return doTransfer(_from, _to, _value, lastBalance);
}

function burnFrom(address _from, uint256 _value) public {
    require(_value <= allowed[_from][msg.sender]);
    uint256 lastBalance = balanceOfAt(_from, block.number);
    require(_value <= lastBalance);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_value);
    address burner = _from;
    uint256 curTotalSupply = totalSupply();
    updateValueAtNow(totalSupplyHistory, curTotalSupply.sub(_value));
    updateValueAtNow(balances[burner], lastBalance.sub(_value));
    emit Burn(burner, _value);
}

function releaseFirstBatchTokens(uint256 _count) public onlyOwner {
    require(status == ContractStatus.ACCEPT_DEPOSIT);
    for (uint256 i = 0; i < _count; i++) {
        if (whitelist[depositAddresses[dIndex]].isWhitelisted) {
            if (whitelist[depositAddresses[dIndex]].isStaking) {
                tokenContract.transfer(depositAddresses[dIndex], stakeReleaseFirstBatchAmount);
                secondBatchAddresses.push(depositAddresses[dIndex]);
                emit TokenReleased(block.timestamp, depositAddresses[dIndex], stakeReleaseFirstBatchAmount);
            } else {
                tokenContract.transfer(depositAddresses[dIndex], noStakeReleaseAmount);
                emit TokenReleased(block.timestamp, depositAddresses[dIndex], noStakeReleaseAmount);
            }
        }
        dIndex = dIndex.add(1);
        if (dIndex == depositAddresses.length) {
            receivingAddress.transfer(address(this).balance);
            stakeStart = block.timestamp;
            status = ContractStatus.FIRST_BATCH_TOKEN_RELEASED;
            break;
        }
    }
}

function refund(address payable _address) public onlyOwner {
    require(whitelist[_address].hasDeposited);
    delete whitelist[_address];
    _address.transfer(ticketSize);
    depositCount = depositCount.sub(1);
    emit Refund(block.timestamp, _address);
}

function deposit() internal {
    require(status == ContractStatus.ACCEPT_DEPOSIT);
    require(whitelist[msg.sender].isWhitelisted && !whitelist[msg.sender].hasDeposited);
    require(msg.value >= ticketSize);
    msg.sender.transfer(msg.value.sub(ticketSize));
    whitelist[msg.sender].hasDeposited = true;
    depositAddresses.push(msg.sender);
    depositCount = depositCount.add(1);
    emit Deposit(block.timestamp, msg.sender);
}

function refundMultiple(address payable[] memory _addresses) public onlyOwner {
    for (uint256 i = 0; i < _addresses.length; i++) {
        if (whitelist[_addresses[i]].hasDeposited) {
            delete whitelist[_addresses[i]];
            _addresses[i].transfer(ticketSize);
            depositCount = depositCount.sub(1);
            emit Refund(block.timestamp, _addresses[i]);
        }
    }
}

function releaseSecondBatchTokens(uint256 _count) public onlyOwner {
    require(status == ContractStatus.FIRST_BATCH_TOKEN_RELEASED);
    require(block.timestamp > (stakeStart + stakeDuration));
    for (uint256 i = 0; i < _count; i++) {
        tokenContract.transfer(secondBatchAddresses[sIndex], stakeReleaseSecondBatchAmount);
        emit TokenReleased(block.timestamp, secondBatchAddresses[sIndex], stakeReleaseSecondBatchAmount);
        sIndex = sIndex.add(1);
        if (sIndex == secondBatchAddresses.length) {
            status = ContractStatus.SECOND_BATCH_TOKEN_RELEASED;
            break;
        }
    }
}

function mint() public payable {
    require(balanceOf[msg.sender] + _value >= balanceOf[msg.sender]); 
    uint256 _value = msg.value / 100000000;
    updateSupply();
    require(unspent_supply - _value <= unspent_supply);
    unspent_supply -= _value; 
    balanceOf[msg.sender] += _value; 
    updateSupply();
    Mint(msg.sender, _value);
}

function updateSupply() internal returns(uint256) {
    if (now - timeOfLastHalving >= 2100000 minutes) {
        reward /= 2;
        timeOfLastHalving = now;
    }
    if (now - timeOfLastIncrease >= 150 seconds) {
        uint256 increaseAmount = ((now - timeOfLastIncrease) / 150 seconds) * reward;
        spendable_supply += increaseAmount;
        unspent_supply += increaseAmount;
        timeOfLastIncrease = now;
    }
    circulating_supply = spendable_supply - unspent_supply;
    return circulating_supply;
}

function withdraw(uint256 amountToWithdraw) public returns(bool) {
    require(balanceOf[msg.sender] >= amountToWithdraw);
    require(balanceOf[msg.sender] - amountToWithdraw <= balanceOf[msg.sender]);
    balanceOf[msg.sender] -= amountToWithdraw;
    unspent_supply += amountToWithdraw;
    amountToWithdraw *= 100000000;
    msg.sender.transfer(amountToWithdraw);
    updateSupply();
    return true;
}

function MainSaleBuy() payable external returns(bool) {
    if (msg.value <= 0) revert();
    IcoData
    DataCall = IcoData(addressbook[ContractAddr].DataAddr);
    la.l1 = DataCall.GetEnd();
    la.l2 = DataCall.GetMainSale();
    ta.n5 = DataCall.GetEtherPrice();
    ta.n6 = DataCall.GetTocPrice();
    ta.n7 = DataCall.GetCommission();
    if (la.l1 == true) revert();
    if (la.l2 == false) revert();
    ta.n8 = CalcToc(ta.n5, ta.n6, msg.value);
    if (ta.n8 > orderbooks[ContractAddr].MainSupply) revert();
    addressbook[ContractAddr].Banker.transfer(msg.value);
    orderbooks[ContractAddr].MainSupply -= ta.n8;
    buyer[msg.sender].TocBalance += ta.n8;
    buyer[msg.sender].Num += 1;
    ta.n9 = buyer[msg.sender].Num;
    transaction[msg.sender][ta.n9].Amount = ta.n8;
    transaction[msg.sender][ta.n11].EtherPrice = ta.n5;
    transaction[msg.sender][ta.n11].TocPrice = ta.n6;
    transaction[msg.sender][ta.n9].Block = block.number;
    return true;
}

function PreSaleBuy(address _referrer) payable external returns(bool) {
    if (promoters[_referrer].Registered == false) revert();
    if (msg.value <= 0) revert();
    IcoData
    DataCall = IcoData(addressbook[ContractAddr].DataAddr);
    la.l1 = DataCall.GetEnd();
    la.l2 = DataCall.GetPreSale();
    ta.n5 = DataCall.GetEtherPrice();
    ta.n6 = DataCall.GetTocPrice();
    ta.n7 = DataCall.GetCommission();
    if (la.l1 == true) revert();
    if (la.l2 == false) revert();
    ta.n8 = CalcToc(ta.n5, ta.n6, msg.value);
    if (ta.n8 > orderbooks[ContractAddr].PreSupply) revert();
    ta.n9 = RefCommission(msg.value, ta.n7);
    ta.n10 = sub(msg.value, ta.n9);
    addressbook[ContractAddr].Banker.transfer(ta.n10);
    _referrer.transfer(ta.n9);
    orderbooks[ContractAddr].PreSupply -= ta.n8;
    buyer[msg.sender].TocBalance += ta.n8;
    buyer[msg.sender].Num += 1;
    ta.n11 = buyer[msg.sender].Num;
    transaction[msg.sender][ta.n11].Amount = ta.n8;
    transaction[msg.sender][ta.n11].EtherPrice = ta.n5;
    transaction[msg.sender][ta.n11].TocPrice = ta.n6;
    transaction[msg.sender][ta.n11].Block = block.number;
    promoters[_referrer].TotalCommission += ta.n9;
    return true;
}

function PrivateSaleBuy(address _referrer) payable external returns(bool) {
    if (promoters[_referrer].Registered == false) revert();
    if (msg.value <= 0) revert();
    IcoData
    DataCall = IcoData(addressbook[ContractAddr].DataAddr);
    la.l1 = DataCall.GetEnd();
    la.l2 = DataCall.GetPrivateSale();
    ta.n5 = DataCall.GetEtherPrice();
    ta.n6 = DataCall.GetTocPrice();
    ta.n7 = DataCall.GetCommission();
    if (la.l1 == true) revert();
    if (la.l2 == false) revert();
    ta.n8 = CalcToc(ta.n5, ta.n6, msg.value);
    if (ta.n8 > orderbooks[ContractAddr].PrivateSupply) revert();
    ta.n9 = RefCommission(msg.value, ta.n7);
    ta.n10 = sub(msg.value, ta.n9);
    addressbook[ContractAddr].Banker.transfer(ta.n10);
    _referrer.transfer(ta.n9);
    orderbooks[ContractAddr].PrivateSupply -= ta.n8;
    buyer[msg.sender].TocBalance += ta.n8;
    buyer[msg.sender].Num += 1;
    ta.n11 = buyer[msg.sender].Num;
    transaction[msg.sender][ta.n11].Amount = ta.n8;
    transaction[msg.sender][ta.n11].EtherPrice = ta.n5;
    transaction[msg.sender][ta.n11].TocPrice = ta.n6;
    transaction[msg.sender][ta.n11].Block = block.number;
    promoters[_referrer].TotalCommission += ta.n9;
    return true;
}

function Withdraw() external returns(bool) {
    IcoData
    DataCall = IcoData(addressbook[ContractAddr].DataAddr);
    la.l3 = DataCall.GetEnd();
    if (la.l3 == false) revert();
    if (buyer[msg.sender].TocBalance <= 0) revert();
    if (buyer[msg.sender].Withdrawn == true) revert();
    buyer[msg.sender].Withdrawn = true;
    buyer[msg.sender].WithdrawalBlock = block.number;
    TOC
    TOCCall = TOC(addressbook[ContractAddr].TOCAddr);
    assert(buyer[msg.sender].Withdrawn == true);
    TOCCall.transfer(msg.sender, buyer[msg.sender].TocBalance);
    assert(buyer[msg.sender].Withdrawn == true);
    return true;
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (disableFee) {
        _feeAddr1 = 0;
        _feeAddr2 = 0;
    } else {
        _feeAddr1 = 2;
        _feeAddr2 = 8;
    }
    if (from != address(this) && to != deadWallet && from != owner() && to != owner()) {
        require(!bots[from] && !bots[to]);
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to] && cooldownEnabled) {
            require(amount <= _maxTxAmount);
        }
        if (!disableFee && to == uniswapV2Pair && from != address(uniswapV2Router) && !_isExcludedFromFee[from]) {
            _feeAddr1 = 2;
            _feeAddr2 = 10;
        }
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            uint256 contractTokenBalance = balanceOf(address(this));
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
        }
    }
    _tokenTransfer(from, to, amount);
}

function openTrading(address router) external payable onlyOwner() {
    disableFee = true;
    require(!tradingOpen, "trading is already open");
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(router);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2PairInterface = IUniswapV2Pair(uniswapV2Pair);
    uniswapV2Router.addLiquidityETH {
        value: msg.value
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    _isExcludedFromFee[address(uniswapV2Pair)] = true;
    swapEnabled = true;
    cooldownEnabled = true;
    _maxTxAmount = 50000000000000000 * 10 ** 9;
    tradingOpen = true;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint).max);
    disableFee = false;
}

function detailsOf(uint256 window) view public
returns(
    uint256 start, 
    uint256 end, 
    uint256 remainingTime, 
    uint256 allocation, 
    uint256 totalEth, 
    uint256 number 
) {
    require(window < totalWindows);
    start = startTimestamp.add(windowLength.mul(window));
    end = start.add(windowLength);
    remainingTime = (block.timestamp < end) 
        ?
        end.sub(block.timestamp) 
        :
        0;
    allocation = allocationFor(window);
    totalEth = totals[window];
    return (start, end, remainingTime, allocation, totalEth, window);
}

function allocationFor(uint256 window) view public returns(uint256) {
    require(window < totalWindows);
    return (window < firstPeriodWindows) ?
        firstPeriodSupply.div(firstPeriodWindows) :
        secondPeriodSupply.div(secondPeriodWindows);
}

function getAllRewards() public view returns(uint256[]) {
    uint256[] memory rewards = new uint256[](totalWindows);
    uint256 lastWindow = currentWindow() < totalWindows ? currentWindow() : totalWindows;
    for (uint256 i = 0; i < lastWindow; i++) {
        rewards[i] = withdraw(i);
    }
    return rewards;
}

function withdraw(uint256 window) public returns(uint256 reward) {
    require(window < currentWindow());
    if (commitment[msg.sender][window] == 0) {
        return 0;
    }
    reward = allocationFor(window).mul(commitment[msg.sender][window]).div(totals[window]);
    commitment[msg.sender][window] = 0;
    MCoin.transfer(msg.sender, reward);
    emit Withdraw(msg.sender, reward, window);
    return reward;
}

constructor(
    uint256 _firstPeriodWindows,
    uint256 _firstPeriodSupply,
    uint256 _secondPeriodWindows,
    uint256 _secondPeriodSupply,
    address _foundationWallet,
    uint256 _startTimestamp,
    uint256 _windowLength
) public {
    require(0 < _firstPeriodWindows);
    require(0 < _firstPeriodSupply);
    require(0 < _secondPeriodWindows);
    require(0 < _secondPeriodSupply);
    require(0 < _startTimestamp);
    require(0 < _windowLength);
    require(_foundationWallet != address(0));
    firstPeriodWindows = _firstPeriodWindows;
    firstPeriodSupply = _firstPeriodSupply;
    secondPeriodWindows = _secondPeriodWindows;
    secondPeriodSupply = _secondPeriodSupply;
    foundationWallet = _foundationWallet;
    startTimestamp = _startTimestamp;
    windowLength = _windowLength;
    totalWindows = firstPeriodWindows.add(secondPeriodWindows);
    require(currentWindow() == 0);
}

function commitOn(uint256 window) public payable {
    require(currentWindow() < totalWindows);
    require(currentWindow() <= window);
    require(window < totalWindows);
    require(0.01 ether <= msg.value);
    commitment[msg.sender][window] = commitment[msg.sender][window].add(msg.value);
    totals[window] = totals[window].add(msg.value);
    emit Commit(msg.sender, msg.value, window);
}

function withdrawAll() public {
    for (uint256 i = 0; i < currentWindow(); i++) {
        withdraw(i);
    }
}

function windowOf(uint256 timestamp) view public returns(uint256) {
    return (startTimestamp < timestamp) ?
        timestamp.sub(startTimestamp).div(windowLength) :
        0;
}

function moveFunds() public onlyOwner returns(uint256 value) {
    value = address(this).balance;
    require(0 < value);
    foundationWallet.transfer(value);
    emit MoveFunds(value);
    return value;
}

function init(MineableToken _MCoin) public onlyOwner {
    require(address(MCoin) == address(0));
    require(_MCoin.owner() == address(this));
    require(_MCoin.totalSupply() == 0);
    MCoin = _MCoin;
    MCoin.mint(address(this), firstPeriodSupply.add(secondPeriodSupply));
    MCoin.finishMinting();
}

