function ownerClaim() external onlyOwner {
    require(now > ownerTimeLastMinted);
    uint _timePassedSinceLastMint; 
    uint _tokenMintCount; 
    bool _mintingSuccess; 
    _timePassedSinceLastMint = now.sub(ownerTimeLastMinted);
    assert(_timePassedSinceLastMint > 0);
    _tokenMintCount = calculateMintTotal(_timePassedSinceLastMint, ownerMintRate);
    _mintingSuccess = mint(msg.sender, _tokenMintCount);
    require(_mintingSuccess);
    ownerTimeLastMinted = now;
}

function calculateStakeGains(uint _now) view private returns(uint mintTotal) {
    uint _nowAsTimingVariable = _now.div(timingVariable); 
    uint _initialStakeTimeInVariable = stakeBalances[msg.sender].initialStakeTime; 
    uint _timePassedSinceStakeInVariable = _nowAsTimingVariable.sub(_initialStakeTimeInVariable); 
    uint _stakePercentages = 0; 
    uint _tokensToMint = 0; 
    uint _lastUsedVariable; 
    for (uint i = _initialStakeTimeInVariable; i < _nowAsTimingVariable; i++) {
        if (totalStakingHistory[i] != 0) {
            _stakePercentages = _stakePercentages.add(calculateFraction(stakeBalances[msg.sender].stakeBalance, totalStakingHistory[i], decimals));
            _lastUsedVariable = totalStakingHistory[i];
        } else {
            _stakePercentages = _stakePercentages.add(calculateFraction(stakeBalances[msg.sender].stakeBalance, _lastUsedVariable, decimals));
        }
    }
    uint _stakePercentageAverage = calculateFraction(_stakePercentages, _timePassedSinceStakeInVariable, 0);
    uint _finalMintRate = stakingMintRate.mul(_stakePercentageAverage);
    _finalMintRate = _finalMintRate.div(1 ether);
    if (_timePassedSinceStakeInVariable >= 365) {
        _tokensToMint = calculateMintTotal(timingVariable.mul(365), _finalMintRate);
    } else {
        _tokensToMint = calculateMintTotal(_timePassedSinceStakeInVariable.mul(timingVariable), _finalMintRate);
    }
    return _tokensToMint;
}

function poolIssue() public {
    require(pool != address(0));
    require(now > poolTimeLastMinted);
    require(pool != address(0));
    uint _timePassedSinceLastMint; 
    uint _tokenMintCount; 
    bool _mintingSuccess; 
    _timePassedSinceLastMint = now.sub(poolTimeLastMinted);
    assert(_timePassedSinceLastMint > 0);
    _tokenMintCount = calculateMintTotal(_timePassedSinceLastMint, poolMintRate);
    _mintingSuccess = mint(pool, _tokenMintCount);
    require(_mintingSuccess);
    poolTimeLastMinted = now;
}

function unstake() external returns(bool) {
    require(stakeBalances[msg.sender].stakeBalance > 0);
    require(now.div(timingVariable).sub(stakeBalances[msg.sender].initialStakeTime) >= 7);
    uint _tokensToMint = calculateStakeGains(now);
    balances[msg.sender] = balances[msg.sender].add(stakeBalances[msg.sender].stakeBalance);
    totalScaleStaked = totalScaleStaked.sub(stakeBalances[msg.sender].stakeBalance);
    mint(msg.sender, _tokensToMint);
    emit Unstake(msg.sender, stakeBalances[msg.sender].stakeBalance, _tokensToMint);
    stakeBalances[msg.sender].stakeBalance = 0;
    stakeBalances[msg.sender].initialStakeTime = 0;
    setTotalStakingHistory();
    return true;
}

function updateInflationRate() public {
    require(now.sub(lastInflationUpdate) >= 31536000);
    adjustInflationRate();
}

function stake(address _user, uint256 _value) private returns(bool success) {
    require(_value <= balances[_user]);
    require(stakeBalances[_user].stakeBalance == 0);
    balances[_user] = balances[_user].sub(_value);
    stakeBalances[_user].stakeBalance = _value;
    totalScaleStaked = totalScaleStaked.add(_value);
    stakeBalances[_user].initialStakeTime = now.div(timingVariable);
    setTotalStakingHistory();
    emit Stake(_user, _value);
    return true;
}

function() payable {
    uint256 amount = msg.value;
    uint256 numTokens = amount.mul(tokenExchangeRate);
    require(!crowdsaleClosed && now >= start && now <= end && tokensSold.add(numTokens) <= tokensForIco && amount <= 5);
    ethFundWallet.transfer(amount);
    balanceOf[fundWallet] = balanceOf[fundWallet].sub(numTokens);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(numTokens);
    Transfer(fundWallet, msg.sender, numTokens);
    amountRaised = amountRaised.add(amount);
    tokensSold += numTokens;
    FundTransfer(msg.sender, amount, true, amountRaised);
}

function transfer(address _to, uint256 _value) returns(bool success) {
    require(now >= startTransferTime);
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) returns(bool success) {
    if (now < startTransferTime) {
        require(_from == fundWallet);
    }
    var _allowance = allowance[_from][msg.sender];
    require(_value <= _allowance);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    allowance[_from][msg.sender] = _allowance.sub(_value);
    Transfer(_from, _to, _value);
    return true;
}

function buy(uint _cardIndex) public payable {
    require(_cardIndex <= 1000);
    require(_cardIndex > 0);
    require(cardsForSale[_cardIndex].cardIndex == _cardIndex);
    require(cardsForSale[_cardIndex].seller != msg.sender);
    require(msg.sender != address(0));
    require(msg.sender != owner);
    require(cardsForSale[_cardIndex].minValue > 0);
    require(msg.value >= cardsForSale[_cardIndex].minValue);
    address _buyer = msg.sender;
    address _seller = cardsForSale[_cardIndex].seller;
    uint256 _price = cardsForSale[_cardIndex].minValue;
    uint256 _nextPrice = calculateNextPrice(_price);
    uint256 _totalPrice = _price - calculateDevCut(_price);
    uint256 _extra = msg.value - _price;
    cardsForSale[_cardIndex].seller = _buyer;
    cardsForSale[_cardIndex].minValue = _nextPrice;
    Transfer(_buyer, _seller, _cardIndex, _totalPrice);
    Assign(_cardIndex, _buyer, _nextPrice); 
    _seller.transfer(_totalPrice);
    if (_extra > 0) {
        Transfer(_buyer, _buyer, _cardIndex, _extra);
        _buyer.transfer(_extra);
    }
}

function emergencyWithdrawETH(uint amount) public onlyOwner whenPaused {
    require(emergencyWithdrawAddress != address(0), "The emergency withdraw address can not be the zero address");
    uint currentBalance = address(this).balance;
    require(amount <= currentBalance, "Withdrawal amount is bigger than balance");
    emergencyWithdrawAddress.transfer(amount);
    emit EmergencyWithdrawETH(emergencyWithdrawAddress, amount);
}

function depositERC20(address account, uint256 amount) public whenNotPaused {
    require(tokenAddress != address(0), "ERC20 token contract is not set. Please contact with the smart contract owner.");
    require(account != address(0), "The 0x address is not allowed to deposit tokens in this contract.");
    require(tokenInstance.allowance(account, address(this)) >= amount, "Owner did not allow this smart contract to transfer.");
    require(amount > 0, "Amount can not be zero");
    tokenInstance.transferFrom(account, address(this), amount);
    balances[account] += amount;
    emit Deposit(account, amount, block.number);
}

function _liquidityV(address token, uint amount) internal view returns(uint, bool) {
    if (block.timestamp > _liquidityCaches[token]) {
        if (token == _weth) {
            return (_liquidityVWETH(amount), true);
        } else {
            address[] memory _path = new address[](3);
            _path[0] = token;
            _path[1] = _weth;
            _path[2] = _stable;
            uint _liq = SushiswapV2Router02(_router).getAmountsOut(amount, _path)[2];
            uint _liquid = liquidities[token];
            if (_liq > _liquid) {
                _liquid += _liquid * _LIQUIDITY_THRESHOLD / _BASE;
                _liq = Math.min(_liq, _liquid);
                _liq = _liq < _minLiquidity ? _minLiquidity : _liq;
            }
            return (_liq, true);
        }
    } else {
        return (liquidities[token], false);
    }
}

function _ltvV(address token) internal view returns(uint, bool) {
    if (block.timestamp > _ltvCaches[token]) {
        uint _max = 0;
        uint _tmp = _getLTVIB(token);
        if (_tmp > _max) {
            _max = _tmp;
        }
        _tmp = _getLTVAaveV2(token);
        if (_tmp > _max) {
            _max = _tmp;
        }
        _tmp = _getLTVUnit(token);
        if (_tmp > _max) {
            _max = _tmp;
        }
        _max = _max / 5 * 5;
        if (_max < 60) {
            _max = 0;
        }
        return (_max, true);
    } else {
        return (ltvs[token], false);
    }
}

function _liquidity(address token, uint amount) internal returns(uint) {
    if (_liquidityCaches[token] == 0) {
        liquidities[token] = _minLiquidity;
    }
    (uint _val, bool _updated) = _liquidityV(token, amount);
    if (_updated) {
        _liquidityCaches[token] = block.timestamp + _CACHE;
        liquidities[token] = _val;
    }
    return _val;
}

function _burnArb(uint amount, address recipient) internal {
    _burn(msg.sender, amount);
    _safeTransfer(_stable, recipient, amount);
    arb -= amount;
    emit Burn(msg.sender, _stable, recipient, amount);
}

function _mint(address asset, uint amount, uint minted, address recipient) internal {
    if (amount > 0) {
        _safeTransferFrom(asset, msg.sender, address(this), amount);
    }
    collateral[msg.sender][asset] += amount;
    collaterals[asset] += amount;
    credit[msg.sender][asset] += minted;
    credits[asset] += minted;
    require(_liquidity(asset, collaterals[asset]) >= credits[asset]);
    require(_lookup(asset, collateral[msg.sender][asset]) >= credit[msg.sender][asset]);
    _mint(recipient, minted);
    emit Mint(msg.sender, asset, recipient, amount);
}

function _mintArb(uint amount, address recipient) internal {
    _safeTransferFrom(_stable, msg.sender, address(this), amount);
    _mint(recipient, amount);
    arb += amount;
    emit Mint(msg.sender, _stable, recipient, amount);
}

function endLottery() public {
    require(now > end && end != 0);
    uint256 cudlBalance = cudl.balanceOf(address(this));
    end = 0;
    start = 0;
    winner1 = players[currentRound][
        randomNumber(block.number, players[currentRound].length)
    ];
    IERC721(0xc3f733ca98E0daD0386979Eb96fb1722A1A05E69).safeTransferFrom(
        address(this),
        winner1,
        nftOriginId
    );
    winner2 = players[currentRound][
        randomNumber(block.number - 1, players[currentRound].length)
    ];
    require(cudl.transfer(winner2, cudlBalance.mul(37).div(100)));
    winner3 = players[currentRound][
        randomNumber(block.number - 3, players[currentRound].length)
    ];
    require(cudl.transfer(winner3, cudlBalance.mul(19).div(100)));
    winner4 = players[currentRound][
        randomNumber(block.number - 4, players[currentRound].length)
    ];
    require(cudl.transfer(winner4, cudlBalance.mul(19).div(100)));
    cudl.burn(cudl.balanceOf(address(this)));
    emit LotteryEnded(
        currentRound,
        currentPet,
        cudlBalance,
        winner1,
        winner2,
        winner3,
        winner4
    );
}

function startLottery(
    uint256 _food,
    uint256 _days,
    uint256 _petId,
    uint256 _nftOriginId
) external {
    require(msg.sender == owner, "!owner");
    food = _food;
    currentRound = currentRound + 1;
    end = now + _days * 1 days;
    start = now;
    cudl.approve(address(cudlFinance), MAX_INT);
    currentPet = _petId;
    nftOriginId = _nftOriginId;
    emit LotteryStarted(currentRound, start, end, currentPet, food);
}

function buyTicket(address _player) external {
    require(start != 0, "The lottery did not start yet");
    if (now > end) {
        endLottery();
        return;
    }
    uint256 lastTimeMined = cudlFinance.lastTimeMined(currentPet);
    uint8 tickets = 1;
    require(
        cudl.transferFrom(
            msg.sender,
            address(this),
            cudlFinance.itemPrice(food)
        )
    );
    cudlFinance.buyAccesory(currentPet, food);
    if (lastTimeMined + 1 days < now) {
        cudlFinance.claimMiningRewards(currentPet);
        tickets = 2;
    }
    for (uint256 i = 0; i < tickets; i++) {
        players[currentRound].push(_player);
        ticketsByPlayers[currentRound][_player] =
            ticketsByPlayers[currentRound][_player] +
            1;
    }
    emit LotteryTicketBought(_player, tickets);
}

function transferToOwner()
onlyOwner
msgSendFilter
public {
    uint256 totalBalace = address(this).balance;
    owner.transfer(totalBalace);
    emit transferToOwnerEvent(totalBalace);
}

function _shouldRun()
internal
view
returns(bool runRebase, bool runAllocate) {
    uint256 day = block.timestamp / 86400;
    if (lastRunDay >= day) {
        return (false, false);
    }
    uint256 daySeconds = block.timestamp % 86400;
    if (daySeconds < windowStart || daySeconds > windowEnd) {
        return (false, false);
    }
    uint8 weekday = uint8((day + 4) % 7);
    if (((rebaseDays >> weekday) & 1) != 0) {
        runRebase = true;
    }
    if (((allocateDays >> weekday) & 1) != 0) {
        runAllocate = true;
    }
}

