function withdrawal(address _to, uint256 Ether, uint256 Token) onlyOwner public {
    require(this.balance >= Ether && balances[this] >= Token);
    if (Ether > 0) {
        _to.transfer(Ether);
        WithdrawEth(_to, Ether);
    }
    if (Token > 0) {
        require(balances[_to] + Token > balances[_to]);
        balances[this] -= Token;
        balances[_to] += Token;
        Transfer(this, _to, Token);
    }
}

function createTokens() public whenNotPaused payable {
    require(msg.value >= minPrice);
    uint masterValue = msg.value.mul(percentRate.sub(slaveWalletPercent)).div(percentRate);
    uint slaveValue = msg.value.sub(masterValue);
    masterWallet.transfer(masterValue);
    slaveWallet.transfer(slaveValue);
    mintTokens(msg.sender, msg.value);
}

function mintTokens(address to, uint weiInvested) internal {
    uint stageIndex = currentStage();
    Stage storage stage = stages[stageIndex];
    uint tokens = weiInvested.mul(stage.price);
    token.mint(this, tokens);
    token.transfer(to, tokens);
    totalTokensMinted = totalTokensMinted.add(tokens);
    totalInvested = totalInvested.add(weiInvested);
    stage.invested = stage.invested.add(weiInvested);
    if (stage.invested >= stage.hardcap) {
        stage.closed = now;
    }
}

function finishMinting() public whenNotPaused onlyOwner {
    uint summaryTokensPercent = bountyTokensPercent + foundersTokensPercent;
    uint mintedTokens = token.totalSupply();
    uint totalSupply = mintedTokens.mul(percentRate).div(percentRate.sub(summaryTokensPercent));
    uint foundersTokens = totalSupply.mul(foundersTokensPercent).div(percentRate);
    uint bountyTokens = totalSupply.mul(bountyTokensPercent).div(percentRate);
    token.mint(this, foundersTokens);
    token.transfer(foundersTokensWallet, foundersTokens);
    token.mint(this, bountyTokens);
    token.transfer(bountyTokensWallet, bountyTokens);
    totalTokensMinted = totalTokensMinted.add(foundersTokens).add(bountyTokens);
    token.finishMinting();
}

function swap(uint amount0Out, uint amount1Out, address to, bytes calldata data) external override lock {
    require(amount0Out > 0 || amount1Out > 0, 'Nimbus: INSUFFICIENT_OUTPUT_AMOUNT');
    (uint112 _reserve0, uint112 _reserve1, ) = getReserves(); 
    require(amount0Out < _reserve0 && amount1Out < _reserve1, 'Nimbus: INSUFFICIENT_LIQUIDITY');
    uint balance0;
    uint balance1;
    { 
        address _token0 = token0;
        address _token1 = token1;
        require(to != _token0 && to != _token1, 'Nimbus: INVALID_TO');
        if (amount0Out > 0) _safeTransfer(_token0, to, amount0Out); 
        if (amount1Out > 0) _safeTransfer(_token1, to, amount1Out); 
        if (data.length > 0) INimbusCallee(to).NimbusCall(msg.sender, amount0Out, amount1Out, data);
        balance0 = IERC20(_token0).balanceOf(address(this));
        balance1 = IERC20(_token1).balanceOf(address(this));
    }
    uint amount0In = balance0 > _reserve0 - amount0Out ? balance0 - (_reserve0 - amount0Out) : 0;
    uint amount1In = balance1 > _reserve1 - amount1Out ? balance1 - (_reserve1 - amount1Out) : 0;
    require(amount0In > 0 || amount1In > 0, 'Nimbus: INSUFFICIENT_INPUT_AMOUNT');
    {
        address referralProgram = INimbusFactory(factory).nimbusReferralProgram();
        if (amount0In > 0) {
            address _token0 = token0;
            uint refFee = amount0In.mul(3) / 2000;
            _safeTransfer(_token0, referralProgram, refFee);
            INimbusReferralProgram(referralProgram).recordFee(_token0, to, refFee);
            balance0 = balance0.sub(refFee);
        }
        if (amount1In > 0) {
            uint refFee = amount1In.mul(3) / 2000;
            address _token1 = token1;
            _safeTransfer(_token1, referralProgram, refFee);
            INimbusReferralProgram(referralProgram).recordFee(_token1, to, refFee);
            balance1 = balance1.sub(refFee);
        }
    }
    { 
        uint balance0Adjusted = balance0.mul(10000).sub(amount0In.mul(15));
        uint balance1Adjusted = balance1.mul(10000).sub(amount1In.mul(15));
        require(balance0Adjusted.mul(balance1Adjusted) >= uint(_reserve0).mul(_reserve1).mul(10000 ** 2), 'Nimbus: K');
    }
    _update(balance0, balance1, _reserve0, _reserve1);
    emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out, to);
}

function burn(address to) external override lock returns(uint amount0, uint amount1) {
    (uint112 _reserve0, uint112 _reserve1, ) = getReserves(); 
    address _token0 = token0; 
    address _token1 = token1; 
    uint balance0 = IERC20(_token0).balanceOf(address(this));
    uint balance1 = IERC20(_token1).balanceOf(address(this));
    uint liquidity = balanceOf[address(this)];
    bool feeOn = _mintFee(_reserve0, _reserve1);
    uint _totalSupply = totalSupply; 
    amount0 = liquidity.mul(balance0) / _totalSupply; 
    amount1 = liquidity.mul(balance1) / _totalSupply; 
    require(amount0 > 0 && amount1 > 0, 'Nimbus: INSUFFICIENT_LIQUIDITY_BURNED');
    _burn(address(this), liquidity);
    _safeTransfer(_token0, to, amount0);
    _safeTransfer(_token1, to, amount1);
    balance0 = IERC20(_token0).balanceOf(address(this));
    balance1 = IERC20(_token1).balanceOf(address(this));
    _update(balance0, balance1, _reserve0, _reserve1);
    if (feeOn) kLast = uint(reserve0).mul(reserve1); 
    emit Burn(msg.sender, amount0, amount1, to);
}

function _update(uint balance0, uint balance1, uint112 _reserve0, uint112 _reserve1) private {
    require(balance0 <= (2 ** 112 - 1) && balance1 <= (2 ** 112 - 1), 'Nimbus: OVERFLOW'); 
    uint32 blockTimestamp = uint32(block.timestamp % 2 ** 32);
    uint32 timeElapsed = blockTimestamp - blockTimestampLast; 
    if (timeElapsed > 0 && _reserve0 != 0 && _reserve1 != 0) {
        price0CumulativeLast += uint(UQ112x112.encode(_reserve1).uqdiv(_reserve0)) * timeElapsed;
        price1CumulativeLast += uint(UQ112x112.encode(_reserve0).uqdiv(_reserve1)) * timeElapsed;
    }
    reserve0 = uint112(balance0);
    reserve1 = uint112(balance1);
    blockTimestampLast = blockTimestamp;
    emit Sync(reserve0, reserve1);
}

function _safeTransfer(address token, address to, uint value) private {
    (bool success, bytes memory data) = token.call(abi.encodeWithSelector(SELECTOR, to, value));
    require(success && (data.length == 0 || abi.decode(data, (bool))), 'Nimbus: TRANSFER_FAILED');
}

function _mintFee(uint112 _reserve0, uint112 _reserve1) private returns(bool feeOn) {
    address feeTo = INimbusFactory(factory).feeTo();
    feeOn = feeTo != address(0);
    uint _kLast = kLast; 
    if (feeOn) {
        if (_kLast != 0) {
            uint rootK = Math.sqrt(uint(_reserve0).mul(_reserve1));
            uint rootKLast = Math.sqrt(_kLast);
            if (rootK > rootKLast) {
                uint numerator = totalSupply.mul(rootK.sub(rootKLast));
                uint denominator = rootK.mul(5).add(rootKLast);
                uint liquidity = numerator / denominator;
                if (liquidity > 0) _mint(feeTo, liquidity);
            }
        }
    } else if (_kLast != 0) {
        kLast = 0;
    }
}

function permit(address owner, address spender, uint value, uint deadline, uint8 v, bytes32 r, bytes32 s) external override {
    require(deadline >= block.timestamp, 'Nimbus: EXPIRED');
    bytes32 digest = keccak256(
        abi.encodePacked(
            '\x19\x01',
            DOMAIN_SEPARATOR,
            keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonces[owner]++, deadline))
        )
    );
    address recoveredAddress = ecrecover(digest, v, r, s);
    require(recoveredAddress != address(0) && recoveredAddress == owner, 'Nimbus: INVALID_SIGNATURE');
    _approve(owner, spender, value);
}

function mint(address to) external override lock returns(uint liquidity) {
    (uint112 _reserve0, uint112 _reserve1, ) = getReserves(); 
    uint balance0 = IERC20(token0).balanceOf(address(this));
    uint balance1 = IERC20(token1).balanceOf(address(this));
    uint amount0 = balance0.sub(_reserve0);
    uint amount1 = balance1.sub(_reserve1);
    bool feeOn = _mintFee(_reserve0, _reserve1);
    uint _totalSupply = totalSupply; 
    if (_totalSupply == 0) {
        liquidity = Math.sqrt(amount0.mul(amount1)).sub(MINIMUM_LIQUIDITY);
        _mint(address(0), MINIMUM_LIQUIDITY); 
    } else {
        liquidity = Math.min(amount0.mul(_totalSupply) / _reserve0, amount1.mul(_totalSupply) / _reserve1);
    }
    require(liquidity > 0, 'Nimbus: INSUFFICIENT_LIQUIDITY_MINTED');
    _mint(to, liquidity);
    _update(balance0, balance1, _reserve0, _reserve1);
    if (feeOn) kLast = uint(reserve0).mul(reserve1); 
    emit Mint(msg.sender, amount0, amount1);
}

function getState() public view returns(State, State) {
    if (needInitialization) {
        return (State.Init, State.Init);
    }
    if (destructed) {
        return (State.Destructed, State.Destructed);
    }
    if (now < startDate) {
        return (State.Waiting, State.Waiting);
    }
    State _hardcapState = (finishedHardcap || (tokenHardcapIssuedValue == tokenHardcapValue) || (now > endDate)) ?
        State.Reached :
        State.Sale;
    State _softcapState = (tokenSoftcapIssued == tokenSoftcap) ?
        State.Reached :
        State.Sale;
    return (_hardcapState, _softcapState);
}

function endRound(F4Ddatasets.EventReturns memory _eventData_)
private
returns(F4Ddatasets.EventReturns) {
    uint256 _rID = rID_;
    uint256 _winPID = round_[_rID].plyr;
    uint256 _winTID = round_[_rID].team;
    uint256 _pot = round_[_rID].pot;
    uint256 _win = (_pot.mul(48)) / 100;
    uint256 _own = (_pot.mul(14) / 100);
    owner_.transfer(_own);
    uint256 _gen = (_pot.mul(potSplit_[_winTID].gen)) / 100;
    uint256 _res = (((_pot.sub(_win)).sub(_own)).sub(_gen));
    uint256 _ppt = (_gen.mul(1000000000000000000)) / (round_[_rID].keys);
    uint256 _dust = _gen.sub((_ppt.mul(round_[_rID].keys)) / 1000000000000000000);
    if (_dust > 0) {
        _gen = _gen.sub(_dust);
        _res = _res.add(_dust);
    }
    plyr_[_winPID].win = _win.add(plyr_[_winPID].win);
    round_[_rID].mask = _ppt.add(round_[_rID].mask);
    _eventData_.compressedData = _eventData_.compressedData + (round_[_rID].end * 1000000);
    _eventData_.compressedIDs = _eventData_.compressedIDs + (_winPID * 100000000000000000000000000) + (_winTID * 100000000000000000);
    _eventData_.winnerAddr = plyr_[_winPID].addr;
    _eventData_.winnerName = plyr_[_winPID].name;
    _eventData_.amountWon = _win;
    _eventData_.genAmount = _gen;
    _eventData_.newPot = _res;
    rID_++;
    _rID++;
    round_[_rID].strt = now;
    round_[_rID].end = now.add(rndInit_).add(rndGap_);
    round_[_rID].pot = _res;
    return (_eventData_);
}

function withdraw()
isActivated()
isHuman()
public {
    uint256 _rID = rID_;
    uint256 _now = now;
    uint256 _pID = pIDxAddr_[msg.sender];
    uint256 _eth;
    if (_now > round_[_rID].end && round_[_rID].ended == false && round_[_rID].plyr != 0) {
        F4Ddatasets.EventReturns memory _eventData_;
        round_[_rID].ended = true;
        _eventData_ = endRound(_eventData_);
        _eth = withdrawEarnings(_pID);
        if (_eth > 0)
            plyr_[_pID].addr.transfer(_eth);
        _eventData_.compressedData = _eventData_.compressedData + (_now * 1000000000000000000);
        _eventData_.compressedIDs = _eventData_.compressedIDs + _pID;
        emit F4Devents.onWithdrawAndDistribute(
            msg.sender,
            plyr_[_pID].name,
            _eth,
            _eventData_.compressedData,
            _eventData_.compressedIDs,
            _eventData_.winnerAddr,
            _eventData_.winnerName,
            _eventData_.amountWon,
            _eventData_.newPot,
            _eventData_.genAmount
        );
    } else {
        _eth = withdrawEarnings(_pID);
        if (_eth > 0)
            plyr_[_pID].addr.transfer(_eth);
        emit F4Devents.onWithdraw(_pID, msg.sender, plyr_[_pID].name, _eth, _now);
    }
}

function buyCore(uint256 _pID, uint256 _affID, uint256 _team, F4Ddatasets.EventReturns memory _eventData_)
private {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now > round_[_rID].strt + rndGap_ && (_now <= round_[_rID].end || (_now > round_[_rID].end && round_[_rID].plyr == 0))) {
        core(_rID, _pID, msg.value, _affID, _team, _eventData_);
    } else {
        if (_now > round_[_rID].end && round_[_rID].ended == false) {
            round_[_rID].ended = true;
            _eventData_ = endRound(_eventData_);
            _eventData_.compressedData = _eventData_.compressedData + (_now * 1000000000000000000);
            _eventData_.compressedIDs = _eventData_.compressedIDs + _pID;
            emit F4Devents.onBuyAndDistribute(
                msg.sender,
                plyr_[_pID].name,
                msg.value,
                _eventData_.compressedData,
                _eventData_.compressedIDs,
                _eventData_.winnerAddr,
                _eventData_.winnerName,
                _eventData_.amountWon,
                _eventData_.newPot,
                _eventData_.genAmount
            );
        }
        plyr_[_pID].gen = plyr_[_pID].gen.add(msg.value);
    }
}

function core(uint256 _rID, uint256 _pID, uint256 _eth, uint256 _affID, uint256 _team, F4Ddatasets.EventReturns memory _eventData_)
private {
    if (plyrRnds_[_pID][_rID].keys == 0)
        _eventData_ = managePlayer(_pID, _eventData_);
    if (round_[_rID].eth < 100000000000000000000 && plyrRnds_[_pID][_rID].eth.add(_eth) > 1000000000000000000) {
        uint256 _availableLimit = (1000000000000000000).sub(plyrRnds_[_pID][_rID].eth);
        uint256 _refund = _eth.sub(_availableLimit);
        plyr_[_pID].gen = plyr_[_pID].gen.add(_refund);
        _eth = _availableLimit;
    }
    if (_eth > 1000000000) {
        uint256 _keys = (round_[_rID].eth).keysRec(_eth);
        if (_keys >= 1000000000000000000) {
            updateTimer(_keys, _rID);
            if (round_[_rID].plyr != _pID)
                round_[_rID].plyr = _pID;
            if (round_[_rID].team != _team)
                round_[_rID].team = _team;
            _eventData_.compressedData = _eventData_.compressedData + 100;
        }
        plyrRnds_[_pID][_rID].keys = _keys.add(plyrRnds_[_pID][_rID].keys);
        plyrRnds_[_pID][_rID].eth = _eth.add(plyrRnds_[_pID][_rID].eth);
        round_[_rID].keys = _keys.add(round_[_rID].keys);
        round_[_rID].eth = _eth.add(round_[_rID].eth);
        rndTmEth_[_rID][_team] = _eth.add(rndTmEth_[_rID][_team]);
        _eventData_ = distributeExternal(_rID, _pID, _eth, _eventData_);
        _eventData_ = distributeInternal(_rID, _pID, _eth, _affID, _team, _keys, _eventData_);
        endTx(_pID, _team, _eth, _keys, _eventData_);
    }
}

function reLoadCore(uint256 _pID, uint256 _affID, uint256 _team, uint256 _eth, F4Ddatasets.EventReturns memory _eventData_)
private {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now > round_[_rID].strt + rndGap_ && (_now <= round_[_rID].end || (_now > round_[_rID].end && round_[_rID].plyr == 0))) {
        plyr_[_pID].gen = withdrawEarnings(_pID).sub(_eth);
        core(_rID, _pID, _eth, _affID, _team, _eventData_);
    } else if (_now > round_[_rID].end && round_[_rID].ended == false) {
        round_[_rID].ended = true;
        _eventData_ = endRound(_eventData_);
        _eventData_.compressedData = _eventData_.compressedData + (_now * 1000000000000000000);
        _eventData_.compressedIDs = _eventData_.compressedIDs + _pID;
        emit F4Devents.onReLoadAndDistribute(
            msg.sender,
            plyr_[_pID].name,
            _eventData_.compressedData,
            _eventData_.compressedIDs,
            _eventData_.winnerAddr,
            _eventData_.winnerName,
            _eventData_.amountWon,
            _eventData_.newPot,
            _eventData_.genAmount
        );
    }
}

