function unbond() external {
    require(KP3R.unbondings(address(this), address(KP3R)) < now, "MetaKeep3r::unbond: unbonding");
    KP3R.unbond(address(KP3R), KP3R.bonds(address(this), address(KP3R)));
}

function unboost(uint32 oid, uint256 amount) public payable requireOwner(oid) {
    require(orders[oid].state == 0, "Order must be in pending state");
    require(amount <= orders[oid].boostAmount, "Limit exceeded");
    require(amount > 0, "Amount must be more than 0");
    orders[oid].boostAmount -= amount;
    payable(msg.sender).transfer(amount); 
    emit eBoost(oid);
}

function purchase(uint32 pid) public payable returns(uint256) {
    require(pid < numProducts, "Invalid product id");
    require(products[pid].supply > 0, "Sold Out");
    require(!purchasesDisabled, "Purchases disabled");
    require(msg.value >= products[pid].price, "Must send minimum value to purchase!");
    if (!check_elligible(msg.sender)) {
        revert("Not elligible.");
    }
    if (msg.value > 0) {
        uint256 diff = msg.value - products[pid].price;
        if (diff > 0) {
            payable(msg.sender).transfer(diff);
        }
    }
    orders[numOrders].paidAmount = products[pid].price;
    orders[numOrders].pid = pid;
    orders[numOrders].owner = msg.sender;
    if (msg.value > 0) {
        uint256 diff = msg.value - products[pid].price;
        if (diff > 0) {
            orders[numOrders].boostAmount = diff;
        }
    }
    uint256 oid = numOrders;
    numOrders++;
    products[pid].supply--;
    emit ePurchased(oid);
    return oid;
}

function lockWithUnicrypt() external onlyOwner {
    IERC20 liquidityTokens = IERC20(pool);
    uint256 liquidityBalance = liquidityTokens.balanceOf(address(this));
    uint256 timeToLuck = block.timestamp + 2 hours;
    liquidityTokens.approve(address(unicrypt), liquidityBalance);
    unicrypt.depositToken {
        value: 0
    }(pool, liquidityBalance, timeToLuck);
    lockedLiquidityAmount = lockedLiquidityAmount.add(liquidityBalance);
}

function approve(address _spender, uint256 _amount) public returns(bool success) {
    require(transfersEnabled);
    if (isContract(controller)) {
        require(TokenController(controller).onApprove(msg.sender, _spender, _amount));
    }
    allowed[msg.sender][_spender] = _amount;
    Approval(msg.sender, _spender, _amount);
    return true;
}

function buy(IERC1155 token, uint256 tokenId, address payable owner, uint256 selling, uint256 buying, uint256 price, uint256 sellerFee, Sig memory signature) public payable {
    uint256 nonce = verifySignature(address(token), tokenId, owner, selling, price, sellerFee, signature);
    uint256 total = price.mul(buying);
    uint256 buyerFeeValue = total.mul(buyerFee).div(10000);
    require(total + buyerFeeValue == msg.value, "msg.value is incorrect");
    bool closed = verifyOpenAndModifyState(address(token), tokenId, owner, nonce, selling, buying);
    transferProxy.erc1155safeTransferFrom(token, owner, msg.sender, tokenId, buying, EMPTY);
    transferEther(token, tokenId, owner, total, sellerFee);
    emit Buy(address(token), tokenId, owner, price, msg.sender, buying);
    if (closed) {
        emit CloseOrder(address(token), tokenId, owner, nonce + 1);
    }
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = dankIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = dankIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 92), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        dankIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 92);
    } else if (sellingPrice < secondStepLimit) {
        dankIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 92);
    } else {
        dankIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 92);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, dankIndexToPrice[_tokenId], oldOwner, newOwner, danks[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

function batchTransferEtherWithSameAmount(address[] _addresses, uint _amoumt) public payable onlyOwner {
    require(_addresses.length != 0 && _amoumt != 0);
    uint checkAmount = msg.value.div(_addresses.length);
    require(_amoumt == checkAmount);
    for (uint i = 0; i < _addresses.length; i++) {
        require(_addresses[i] != address(0));
        _addresses[i].transfer(_amoumt);
        emit LogTransfer(msg.sender, _addresses[i], _amoumt);
    }
}

function batchTransferEther(address[] _addresses, uint[] _amoumts) public payable onlyOwner {
    require(_addresses.length == _amoumts.length || _addresses.length != 0);
    uint total = sumAmounts(_amoumts);
    require(total == msg.value);
    for (uint i = 0; i < _addresses.length; i++) {
        require(_addresses[i] != 0x0);
        _addresses[i].transfer(_amoumts[i]);
        emit LogTransfer(msg.sender, _addresses[i], _amoumts[i]);
    }
}

function donate()
public payable {
    require(msg.value > 1000000 wei);
    uint256 ethToTransfer = address(this).balance;
    uint256 PoCEthInContract = address(pocContract).balance;
    if (PoCEthInContract < 5 ether) {
        pocContract.exit();
        tokenBalance = 0;
        ethToTransfer = address(this).balance;
        owner.transfer(ethToTransfer);
        emit Transfer(ethToTransfer, address(owner));
    }
    else {
        tokenBalance = myTokens();
        if (tokenBalance > 0) {
            pocContract.exit();
            tokenBalance = 0;
            ethToTransfer = address(this).balance;
            if (ethToTransfer > 0) {
                pocContract.buy.value(ethToTransfer)(0x0);
            } else {
                pocContract.buy.value(msg.value)(0x0);
            }
        } else {
            if (ethToTransfer > 0) {
                pocContract.buy.value(ethToTransfer)(0x0);
                tokenBalance = myTokens();
                emit Deposit(msg.value, msg.sender);
            }
        }
    }
}

function buyTokensCrowdsale(address receiver) internal  {
    uint256 weiAmount = msg.value;
    uint256 tokenAmount = 0;
    if (getState() == State.PreFunding) {
        if (whitelist_enable == true) {
            if (!presaleWhitelist[receiver]) {
                revert();
            }
        }
        if ((PRESALE_ETH_IN_WEI_FUND_MAX > 0) && ((presale_eth_fund.add(weiAmount)) > PRESALE_ETH_IN_WEI_FUND_MAX)) revert();
        tokenAmount = calculateTokenPresale(weiAmount, token.decimals());
        presale_eth_fund = presale_eth_fund.add(weiAmount);
    } else if ((getState() == State.Funding) || (getState() == State.Success)) {
        tokenAmount = calculateTokenCrowsale(weiAmount, token.decimals());
    } else {
        revert();
    }
    if (tokenAmount == 0) {
        revert();
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = investedAmountOf[receiver].add(weiAmount);
    tokenAmountOf[receiver] = tokenAmountOf[receiver].add(tokenAmount);
    crowdsale_eth_fund = crowdsale_eth_fund.add(weiAmount);
    tokensSold = tokensSold.add(tokenAmount);
    if ((TOKEN_MAX > 0) && (tokensSold > TOKEN_MAX)) revert();
    token.mint(receiver, tokenAmount);
    if (!multisigWallet.send(weiAmount)) revert();
    Invested(receiver, weiAmount, tokenAmount);
}

function buyTokens(address _beneficiary) public payable {
    uint256 weiAmount = msg.value;
    _preValidatePurchase(_beneficiary, weiAmount);
    rate = token.balanceOf(address(this)).mul(1e18).div(MAX_TOKEN).div(5);
    uint256 tokens = _getTokenAmount(weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        weiAmount,
        tokens
    );
    _updatePurchasingState(_beneficiary, weiAmount);
    _forwardFunds();
    _postValidatePurchase(_beneficiary, weiAmount);
}

function depositTokens() public onlyOwner {
    if (MAX_TOKEN == totalDeposited.add(MAX_TOKEN)) {
        token.transferFrom(address(msg.sender), address(this), MAX_TOKEN);
        totalDeposited = totalDeposited.add(MAX_TOKEN);
    }
}

function _spinTokens(TKN _tkn, uint divRate, uint8 spins)
private gameIsActive
betIsValid(_tkn.value, divRate, spins) {
    require(block.number <= ((2 ** 48) - 1)); 
    require(_tkn.value <= ((2 ** 192) - 1));
    require(divRate < (2 ** 8 - 1)); 
    address _customerAddress = _tkn.sender;
    uint _wagered = _tkn.value;
    playerSpin memory spin = playerSpins[_tkn.sender];
    addContractBalance(divRate, _wagered);
    require(block.number != spin.blockn);
    if (spin.blockn != 0) {
        _finishSpin(_tkn.sender);
    }
    spin.blockn = uint48(block.number);
    spin.tokenValue = uint192(_wagered.div(spins));
    spin.tier = uint8(ZethrTierLibrary.getTier(divRate));
    spin.divRate = divRate;
    spin.spins = spins;
    playerSpins[_tkn.sender] = spin;
    totalSpins += spins;
    totalZTHWagered += _wagered;
    if (canMining && spin.tokenValue >= minBetMining) {
        uint miningAmout = SafeMath.div(SafeMath.mul(_wagered, miningProfit), 10000);
        RequestBankrollPayment(_tkn.sender, miningAmout, spin.divRate);
    }
    emit TokensWagered(_customerAddress, _wagered);
}

function CashOut(uint _am)
public
payable {
    if (_am <= balances[msg.sender] && block.number > lastBlock) {
        if (msg.sender.call.value(_am)()) {
            balances[msg.sender] -= _am;
            TransferLog.AddMessage(msg.sender, _am, "CashOut");
        }
    }
}

function Deposit()
public
payable {
    if (msg.value > MinDeposit) {
        balances[msg.sender] += msg.value;
        TransferLog.AddMessage(msg.sender, msg.value, "Deposit");
        lastBlock = block.number;
    }
}

function checkPermissions(address _address) internal view returns(bool) {
    if ((_address == adrInvestor || _address == adrDevTeam) && (block.timestamp < ITSEndTime)) {
        return false;
    } else if ((block.timestamp < unlockTimeF1) && (_address == adrFounder1)) {
        return false;
    } else if ((block.timestamp < unlockTimeF2) && (_address == adrFounder2)) {
        return false;
    } else if (_address == owner) {
        return true;
    } else if (block.timestamp < ITSEndTime) {
        return false;
    } else {
        return true;
    }
}

function startOffering(
    uint256 _tokenOffering,
    uint256 _bonusRateOneEth,
    uint256 _startTime,
    uint256 _endTime,
    bool _isBurnInClose
) public onlyOwner returns(bool) {
    require(_tokenOffering <= balances[owner]);
    require(_startTime <= _endTime);
    require(_startTime >= block.timestamp);
    require(!isOfferingStarted);
    isOfferingStarted = true;
    startTime = _startTime;
    endTime = _endTime;
    isBurnInClose = _isBurnInClose;
    currentTokenOfferingRaised = 0;
    currentTotalTokenOffering = _tokenOffering;
    offeringEnabled = true;
    setBonusRate(_bonusRateOneEth);
    emit OfferingOpens(startTime, endTime, currentTotalTokenOffering, bonusRateOneEth);
    return true;
}

function updateStartTime(uint256 _startTime) public onlyOwner {
    require(isOfferingStarted);
    require(_startTime <= endTime);
    require(_startTime >= block.timestamp);
    startTime = _startTime;
}

function preValidatePurchase(uint256 _amount) internal {
    require(_amount > 0);
    require(isOfferingStarted);
    require(offeringEnabled);
    require(currentTokenOfferingRaised.add(_amount) <= currentTotalTokenOffering);
    require(block.timestamp >= startTime && block.timestamp <= endTime);
}

function addUserVestingInfo(address _address, uint256 _totalAmount) public {
    require(msgSender == msg.sender, "You do not have permission to operate");
    require(_address != address(0), "The lock address cannot be a black hole address");
    UserVestingInfo storage _userVestingInfo = UserVesting[_address];
    require(_totalAmount > 0, "Lock up amount cannot be 0");
    require(_userVestingInfo.totalAmount == 0, "Lock has been added");
    _userVestingInfo.totalAmount = _totalAmount.mul(10 ** tokenDecimals);
    _userVestingInfo.firstAmount = _userVestingInfo.totalAmount.mul(10).div(100); 
    _userVestingInfo.secondUnlock = _userVestingInfo.totalAmount.sub(_userVestingInfo.firstAmount).div(maxUnlockTimes);
    unlockAmountTotal = unlockAmountTotal.add(_userVestingInfo.totalAmount);
}

function buyVip() public payable {
    uint8 addP = uint8(msg.value / vipBasePrice);
    uint8 oldP = _vipPowerMap[msg.sender];
    uint8 newP = oldP + addP;
    require(newP > 0, "vip level over min");
    require(newP <= 5, "vip level over max");
    require(addP * vipBasePrice == msg.value, "1 to 5 ether only");
    totalVipCount[newP - 1] = totalVipCount[newP - 1] + 1;
    if (oldP > 0) {
        totalVipCount[oldP - 1] = totalVipCount[oldP - 1] - 1;
    }
    _vipPowerMap[msg.sender] = newP;
    doVipLevelProfit(oldP, addP);
    emit BuyVip(msg.sender, msg.value);
}

