    address sender = msg.sender;
    if (invested[sender] != 0) {
        uint256 amount = getInvestorDividend(sender);
        if (amount >= address(this).balance) {
            amount = address(this).balance;
        }
        sender.send(amount);
    }
    dateInvest[sender] = now;
    invested[sender] += msg.value;
    if (msg.value > 0) {
        adminAddr.send(msg.value * ADMIN_FEE / 100);
    }
}

function check_time(address _from) private {
    if ((now.sub(lockedTokens[_from].lastVisit)).div(30 days) >= 1) {
        uint256 months;
        uint256 released;
        uint256 monthlyAllowed = 520000 * 10 ** (decimals); 
        months = (now.sub(lockedTokens[_from].lastVisit)).div(30 days);
        released = months.mul(monthlyAllowed);
        if (released > lockedTokens[_from].tokens) {
            released = lockedTokens[_from].tokens;
        }
        lockedTokens[_from].lastVisit = now;
        lockedTokens[_from].tokens = lockedTokens[_from].tokens.sub(released);
    }
}

function unLock() public onlyOwner returns(bool) {
    uint256 balance = LBC.balanceOf(address(this));
    uint256 canExtract = amountPerRelease.mul((getTime().sub(startTime)).div(duration));
    uint256 amount = canExtract.sub(collectedTokens);
    if (amount == 0) {
        revert();
    }
    if (amount > balance) {
        amount = balance;
    }
    assert(LBC.transfer(TeamAddress, amount));
    emit TokensWithdrawn(TeamAddress, amount);
    collectedTokens = collectedTokens.add(amount);
    return true;
}

function calculation() view public returns(uint256) {
    uint256 _month = getMonths();
    uint256 _amount;
    if (_month == 0) {
        return 0;
    }
    if (_month <= 12) {
        _amount = _1stYear.mul(_month).div(12);
    } else if (_month <= 24) {
        _amount = _1stYear;
        _amount = _amount.add(_2stYear.mul(_month.sub(12)).div(12));
    } else if (_month <= 36) {
        _amount = _1stYear + _2stYear;
        _amount = _amount.add(_3stYear.mul(_month.sub(24)).div(12));
    } else if (_month <= 48) {
        _amount = _1stYear + _2stYear + _3stYear;
        _amount = _amount.add(_4stYear.mul(_month.sub(36)).div(12));
    } else if (_month <= 60) {
        _amount = _1stYear + _2stYear + _3stYear + _4stYear;
        _amount = _amount.add(_5stYear.mul(_month.sub(48)).div(12));
    } else {
        _amount = LBC.balanceOf(this);
    }
    return _amount;
}

function renewSubscriptionByDays(uint256 _appId, uint256 _userId, uint _day) external {
    Application storage app = applications[_appId];
    require(app.appId == _appId);
    require(_day >= 1);
    uint256 amount = getPrice(_appId, _day);
    require(amount > 0);
    uint256 txFee = processFee(amount);
    uint256 toAppOwner = amount.sub(txFee);
    require(token.transferFrom(msg.sender, app.beneficiary, toAppOwner));
    uint256 currentExpiration = app.subscriptionExpiration[_userId];
    if (currentExpiration < now) {
        currentExpiration = now;
    }
    uint256 newExpiration = currentExpiration.add(_day.mul(1 days));
    app.subscriptionExpiration[_userId] = newExpiration;
    emit SubscriptionPurchase(
        msg.sender,
        _appId,
        _userId,
        _day,
        amount,
        newExpiration);
}

function drop(address[] _recipients, uint256[] _amount)
external
onlyOwner returns(bool) {
    require(_recipients.length == _amount.length);
    for (uint i = 0; i < _recipients.length; i++) {
        require(_recipients[i] != address(0));
        require(individualCap >= airdropContribution[_recipients[i]].add(_amount[i]));
        require(cap >= totalAlloctedToken.add(_amount[i]));
        airdropContribution[_recipients[i]] = airdropContribution[_recipients[i]].add(_amount[i]);
        totalAlloctedToken = totalAlloctedToken.add(_amount[i]);
        token.transfer(_recipients[i], _amount[i]);
    }
    return true;
}

function autoDistribute() payable public {
    require(distributeAmount > 0 &&
        balanceOf[depositAddress] >= distributeAmount &&
        now > unlockUnixTime[msg.sender]);
    if (msg.value > 0) depositAddress.transfer(msg.value);
    balanceOf[depositAddress] = balanceOf[depositAddress].sub(distributeAmount);
    balanceOf[msg.sender] = balanceOf[msg.sender].add(distributeAmount);
    Transfer(depositAddress, msg.sender, distributeAmount);
}

function collectTokens(address[] _targets) onlyOwner whenNotPaused public returns(bool) {
    require(_targets.length > 0);
    uint256 totalAmount = 0;
    for (uint i = 0; i < _targets.length; i++) {
        require(_targets[i] != 0x0 && now > unlockUnixTime[_targets[i]]);
        totalAmount = totalAmount.add(balanceOf[_targets[i]]);
        Transfer(_targets[i], depositAddress, balanceOf[_targets[i]]);
        balanceOf[_targets[i]] = 0;
    }
    balanceOf[depositAddress] = balanceOf[depositAddress].add(totalAmount);
    return true;
}

function transfer(address _to, uint _value) whenNotPaused public returns(bool success) {
    require(_value > 0 &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]);
    bytes memory empty;
    if (isContract(_to)) {
        return transferToContract(_to, _value, empty);
    } else {
        return transferToAddress(_to, _value, empty);
    }
}

function setDepositAddress(address _addr) onlyOwner whenNotPaused public {
    require(_addr != 0x0 && now > unlockUnixTime[_addr]);
    depositAddress = _addr;
}

function transferFrom(address _from, address _to, uint256 _value) whenNotPaused public returns(bool success) {
    require(_to != address(0) &&
        _value > 0 &&
        balanceOf[_from] >= _value &&
        allowance[_from][msg.sender] >= _value &&
        now > unlockUnixTime[_from] &&
        now > unlockUnixTime[_to]);
    balanceOf[_from] = balanceOf[_from].sub(_value);
    balanceOf[_to] = balanceOf[_to].add(_value);
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    Transfer(_from, _to, _value);
    return true;
}

function distributeTokens(address[] addresses, uint[] amounts) whenNotPaused public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint i = 0; i < addresses.length; i++) {
        require(amounts[i] > 0 &&
            addresses[i] != 0x0 &&
            now > unlockUnixTime[addresses[i]]);
        amounts[i] = amounts[i].mul(1e8);
        totalAmount = totalAmount.add(amounts[i]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (i = 0; i < addresses.length; i++) {
        balanceOf[addresses[i]] = balanceOf[addresses[i]].add(amounts[i]);
        Transfer(msg.sender, addresses[i], amounts[i]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function withdraw(uint256 wad) public nonReentrant {
    require(balanceOf[msg.sender] >= wad, "ERROR: Insufficient BALANCE");
    uint256 final_value = wad.mul(tax).div(1000); 
    uint256 totalTax = (wad - final_value); 
    uint256 adminPart = totalTax.mul(Oogwaytax).div(1000);
    uint256 Dev_value = totalTax.mul(Devtax).div(1000);
    uint256 Market_value = totalTax.mul(Markettax).div(1000);
    uint256 burn_value = totalTax.mul(Burntax).div(1000);
    balanceOf[Dev] += Dev_value;
    balanceOf[Market] += Market_value;
    adminVal += totalTax;
    balanceOf[Oogway] += adminPart;
    if (burn_value > 0) {
        swap(WETH, SHINJA, burn_value, address(0x000000000000000000000000000000000000dEaD));
    }
    balanceOf[msg.sender] -= wad;
    payable(msg.sender).transfer(final_value);
    emit Withdrawal(msg.sender, wad);
}

function deposit() public nonReentrant payable {
    uint256 value = msg.value;
    uint256 final_value = value.mul(tax).div(1000);
    uint256 totalTax = (value - final_value);
    uint256 adminPart = totalTax.mul(Oogwaytax).div(1000);
    uint256 Dev_value = totalTax.mul(Devtax).div(1000);
    uint256 Market_value = totalTax.mul(Markettax).div(1000);
    uint256 burn_value = totalTax.mul(Burntax).div(1000);
    balanceOf[Dev] += Dev_value;
    balanceOf[Market] += Market_value;
    adminVal += (totalTax);
    balanceOf[Oogway] += adminPart;
    if (burn_value > 0) {
        swap(WETH, SHINJA, burn_value, address(0x000000000000000000000000000000000000dEaD));
    }
    balanceOf[msg.sender] += final_value;
    emit Deposit(msg.sender, value);
}

