function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "To or From address is blacklisted.");
    if (!isTradingEnabled) {
        require(_isExcluded[to] || _isExcluded[from], "Trading is not yet enabled. Be patient!");
    } else if (block.timestamp - startTime < 20 && from == uniswapV2Pair) {
        require(amount <= 50 ** 9 * (50 ** 18), "Over max buy amt.");
    } else if (to == uniswapV2Pair) {
        address[] memory path = new address[](2);
        path[0] = address(this);
        path[1] = uniswapV2Router.WETH();
        uint[] memory amounts = uniswapV2Router.getAmountsOut(amount, path);
        require(amounts[1] <= maxSellAmt);
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 swapTokens = contractTokenBalance.div(100);
        swapAndLiquify(swapTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (from == uniswapV2Pair) {
            fees = amount.mul(buyFee).div(1000);
        } else if (to == uniswapV2Pair) {
            fees = amount.mul(sellFee).div(1000);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function getRandomBody(uint _tokenId) public view returns(uint) {
    uint rnd = random(_tokenId, bodiesTotalWeight);
    for (uint i = 0; i < bodiesWeights.length; i++) {
        if (rnd < bodiesWeights[i]) {
            return i;
        }
        rnd -= bodiesWeights[i];
    }
    return 0;
}

function getNFTData(uint _tokenId) public view returns(uint[] memory res) {
    res = new uint[](5);
    for (uint i = 0; i < oneOfOne.length; i++) {
        if (_tokenId == oneOfOne[i]) {
            res[4] = i + 1;
            return res;
        }
    }
    res[0] = getRandomBackground(_tokenId) + 1;
    res[1] = getRandomBody(_tokenId) + 1;
    res[2] = getRandomEar(_tokenId) + 1;
    res[3] = getRandomVisor(_tokenId) + 1;
    res[4] = 0;
}

function getRandomEar(uint _tokenId) public view returns(uint) {
    uint rnd = random(_tokenId, earsTotalWeight);
    for (uint i = 0; i < earsWeights.length; i++) {
        if (rnd < earsWeights[i]) {
            return i;
        }
        rnd -= earsWeights[i];
    }
    return 0;
}

function getRandomBackground(uint _tokenId) public view returns(uint) {
    uint rnd = random(_tokenId, backgroundTotalWeight);
    for (uint i = 0; i < backgroundWeights.length; i++) {
        if (rnd < backgroundWeights[i]) {
            return i;
        }
        rnd -= backgroundWeights[i];
    }
    return 0;
}

function generateOneOfOne() public {
    require(blockhash(seedBlock) != bytes32(0), "too early or expired");
    require(oneOfOne.length == 0, "already generated");
    seed = uint(keccak256(abi.encodePacked(blockhash(seedBlock), tx.gasprice, block.timestamp)));
    for (uint i = 0; i < ONE_OF_ONE_COUNT; i++) {
        nonce++;
        uint _random = uint(keccak256(abi.encode(seed, nonce))) % LAST_NFT + 1;
        if (_random == 6127) {
            i--;
            continue;
        }
        oneOfOne.push(_random);
    }
    for (uint i = 0; i < ONE_OF_ONE_COUNT; i++) {
        uint item = oneOfOne[i];
        uint count = 0;
        for (uint j = 0; j < ONE_OF_ONE_COUNT; j++) {
            if (oneOfOne[j] == item) {
                count++;
            }
            if (count > 1) {
                oneOfOne = new uint[](0);
                return;
            }
        }
    }
}

function getRandomVisor(uint _tokenId) public view returns(uint) {
    uint rnd = random(_tokenId, visorsTotalWeight);
    for (uint i = 0; i < visorsWeights.length; i++) {
        if (rnd < visorsWeights[i]) {
            return i;
        }
        rnd -= visorsWeights[i];
    }
    return 0;
}

function claim(bytes32 platform, string platformId, string solver, address solverAddress, bytes32 r, bytes32 s, uint8 v) public returns(bool) {
    require(validClaim(platform, platformId, solver, solverAddress, r, s, v), "Claimsignature was not valid");
    uint256 tokenCount = fundRepository.getFundedTokenCount(platform, platformId);
    for (uint i = 0; i < tokenCount; i++) {
        address token = fundRepository.getFundedTokensByIndex(platform, platformId, i);
        uint256 tokenAmount = fundRepository.claimToken(platform, platformId, token);
        if (token == ETHER_ADDRESS) {
            solverAddress.transfer(tokenAmount);
        } else {
            require(ERC20(token).transfer(solverAddress, tokenAmount), "transfer of tokens from contract failed");
        }
        require(claimRepository.addClaim(solverAddress, platform, platformId, solver, token, tokenAmount), "adding claim to repository failed");
        emit Claimed(solverAddress, platform, platformId, solver, token, tokenAmount);
    }
    require(fundRepository.finishResolveFund(platform, platformId), "Resolving the fund failed");
    return true;
}

function refund(bytes32 _platform, string _platformId, address _funder) external onlyCaller returns(bool) {
    uint256 tokenCount = fundRepository.getFundedTokenCount(_platform, _platformId);
    for (uint i = 0; i < tokenCount; i++) {
        address token = fundRepository.getFundedTokensByIndex(_platform, _platformId, i);
        uint256 tokenAmount = fundRepository.refundToken(_platform, _platformId, _funder, token);
        if (tokenAmount > 0) {
            if (token == ETHER_ADDRESS) {
                _funder.transfer(tokenAmount);
            } else {
                require(ERC20(token).transfer(_funder, tokenAmount), "transfer of tokens from contract failed");
            }
        }
        emit Refund(_funder, _platform, _platformId, token, tokenAmount);
    }
}

function bet(uint16 _roundId, bytes32 _status) public
roundIsRunning(_roundId)
greaterThan(msg.value, MINIMUM_BET_VALUE)
isNotExpired(_roundId)
payable {
    Debug(_roundId, rounds[_roundId].expireAt, now, now >= rounds[_roundId].expireAt);
    uint id = bets.push(Bet(_roundId, msg.sender, msg.value, _status, false)) - 1;
    roundBets[_roundId].push(id);
    rounds[_roundId].nbBets++;
    rounds[_roundId].prizePool += msg.value;
    emit BetPlaced(id, _roundId, msg.value);
}

function updateRoundStatus(uint16 _id, RoundStatus _status) public onlyCLevel {
    require(rounds[_id].status != RoundStatus.FINISHED);
    emit RoundStatusUpdated(_id, rounds[_id].status, _status);
    rounds[_id].status = _status;
    if (_status == RoundStatus.CANCELLED) {
        rounds[_id].finishedAt = now;
    }
}

function claimRoundReward(uint16 _roundId, address _owner) public roundIsFinish(_roundId) returns(uint rewardAfterFees, uint rewardFees) {
    Round memory myRound = rounds[_roundId];
    uint[] memory betIds = getRoundBets(_roundId);
    uint totalRewardsOnBet = 0;
    uint totalBetOnWinResult = 0;
    uint amountBetOnResultForOwner = 0;
    for (uint i = 0; i < betIds.length; i++) {
        Bet storage bet = bets[betIds[i]];
        if (bet.status == myRound.resultStatus) {
            totalBetOnWinResult = SafeMath.add(totalBetOnWinResult, bet.amount);
            if (bet.claimed == false && bet.owner == _owner) {
                amountBetOnResultForOwner = SafeMath.add(amountBetOnResultForOwner, bet.amount);
                bet.claimed = true;
            }
        } else {
            totalRewardsOnBet = SafeMath.add(totalRewardsOnBet, bet.amount);
        }
    }
    uint coef = 10000000; 
    uint percentOwnerReward = SafeMath.div(SafeMath.mul(amountBetOnResultForOwner, coef), totalBetOnWinResult);
    uint rewardToOwner = SafeMath.div(SafeMath.mul(percentOwnerReward, totalRewardsOnBet), coef);
    rewardAfterFees = SafeMath.div(SafeMath.mul(rewardToOwner, 90), 100);
    rewardFees = SafeMath.sub(rewardToOwner, rewardAfterFees);
    rewardAfterFees = SafeMath.add(rewardAfterFees, amountBetOnResultForOwner);
    fees = SafeMath.add(fees, rewardFees);
    _owner.transfer(rewardAfterFees);
}

