function getTeamSalary() public onlyOwner returns(bool) {
    require(!salarySent);
    require(deusETH.gameOver());
    require(!deusETH.gameOverByUser());
    salarySent = true;
    weiReceived = this.balance;
    uint256 salary = weiReceived / 10;
    weiReceived = weiReceived.sub(salary);
    owner.transfer(salary);
    return true;
}

function getGain(uint256 _id) public {
    require((deusETH.gameOver() && salarySent) || deusETH.gameOverByUser());
    require(deusETH.getHolder(_id) == msg.sender);
    require(deusETH.getState(_id) == 1); 
    require(payments[_id] == false);
    address winner = msg.sender;
    uint256 gain = calcGain();
    require(gain != 0);
    require(this.balance >= gain);
    totalPayments = totalPayments.add(gain);
    payments[_id] = true;
    winner.transfer(gain);
}

function calcGain() internal returns(uint256) {
    if (deusETH.gameOverByUser() && (weiReceived == 0)) {
        weiReceived = this.balance;
    }
    return weiReceived / deusETH.livingSupply();
}

function transferWithLock(address recipient, uint256 amount, uint256 releaseTime) public onlyOwner returns(bool) {
    require(recipient != address(0), "SperaxToken: transferWithLock to zero address");
    require(releaseTime > block.timestamp, "SperaxToken: release time before lock time");
    require(_timelock[recipient].releaseTime == 0, "SperaxToken: already locked");
    TimeLock memory timelock = TimeLock({
        releaseTime: releaseTime,
        amount: amount
    });
    _timelock[recipient] = timelock;
    _transfer(_msgSender(), recipient, amount);
    return true;
}

function _beforeTokenTransfer(address from, address to, uint256 amount) internal override {
    require(!paused(), "SperaxToken: token transfer while paused");
    TimeLock storage timelock = _timelock[from];
    if (timelock.releaseTime != 0 && balanceOf(from).sub(amount) < timelock.amount) {
        require(block.timestamp >= timelock.releaseTime, "SperaxToken: current time is before from account release time");
        timelock.amount = balanceOf(from).sub(amount);
        if (timelock.amount == 0) {
            timelock.releaseTime = 0;
        }
    }
    super._beforeTokenTransfer(from, to, amount);
}

function deposit(ERC20 _token, uint256 _value) external payable {
    address trader = msg.sender;
    if (address(_token) == ETHEREUM) {
        require(msg.value == _value, "mismatched value parameter and tx value");
    } else {
        require(msg.value == 0, "unexpected ether transfer");
        CompatibleERC20(_token).safeTransferFromWithFees(trader, this, _value);
    }
    privateIncrementBalance(trader, _token, _value);
}

function withdraw(ERC20 _token, uint256 _value, bytes _signature) external withBrokerSignatureOrSignal(_token, _signature) {
    address trader = msg.sender;
    privateDecrementBalance(trader, _token, _value);
    if (address(_token) == ETHEREUM) {
        trader.transfer(_value);
    } else {
        CompatibleERC20(_token).safeTransfer(trader, _value);
    }
}

function registerMeOnTokenCore(address _token, address _user, uint _value, string _json) internal {
    require(this.isTokenRegistered(_token));
    raisedAmount[_token] = raisedAmount[_token] + _value;
    uint _credit = NRB_Users(USERS_address).getUserTotalCredit(_user, _token);
    uint _totalpaid = NRB_Users(USERS_address).getUserTotalPaid(_user, _token) + _value - _credit;
    uint flc = NRB_Tokens(TOKENS_address).sendFLC(_user, _token, _totalpaid);
    NRB_Users(USERS_address).registerUserOnToken(_token, _user, _value, flc, _json);
    NRB_Tokens(TOKENS_address).registerTokenPayment(_token, _value);
    withdrawalFrom(_token, _user, _value);
}

