function writeMessage(string argMsg, string argTitle, string argAuthorName, string argLink, string argMeta) public payable {
    require(block.timestamp >= expirationTime);
    require(msg.value >= price);
    Message memory newMessage = Message({
        msg: argMsg,
        value: msg.value,
        sourceAddr: msg.sender,
        authorName: argAuthorName,
        time: block.timestamp,
        blockNumber: block.number,
        metadata: argMeta,
        link: argLink,
        title: argTitle
    });
    messages.push(newMessage);
    address thisContract = this;
    root.transfer(thisContract.balance);
    emit MessageEthernalized(messages.length - 1);
    price = (price * multNumerator) / multDenominator;
    expirationTime = block.timestamp + expirationSeconds;
}

function() public payable {
    require(msg.value >= (1 * 1e18 / ethUSD * 100));
    if (now >= startCloseSale || now <= endCloseSale) {
        require(isWhitelisted(msg.sender));
        closeSale(msg.sender, msg.value);
        stageNow = "Close Sale for Whitelist's members";
    } else if (now >= startStage1 || now <= endStage1) {
        sale1(msg.sender, msg.value);
        stageNow = "Stage 1";
    } else if (now >= startStage2 || now <= endStage2) {
        sale2(msg.sender, msg.value);
        stageNow = "Stage 2";
    } else if (now >= startStage3 || now <= endStage3) {
        sale3(msg.sender, msg.value);
        stageNow = "Stage 3";
    } else {
        stageNow = "No Sale";
        revert();
    }
}

