function convertChest(uint256 _tokenId) onlyChestOwner(_tokenId) public {
    Chest memory chest = chests[_tokenId];
    uint16 numberOfBoosters = chest.boosters;
    if (chest.onlySpecificType != 0) { 
        if (chest.onlySpecificType == 1 || chest.onlySpecificType == 3) {
            boosterContract.mintBooster(msg.sender, 2 days, chest.onlySpecificType, chest.onlySpecificStrength, chest.boosters, chest.raiseStrength);
        } else if (chest.onlySpecificType == 5) { 
            boosterContract.mintBooster(msg.sender, 0, 5, 1, chest.boosters, chest.raiseStrength);
        } else if (chest.onlySpecificType == 2) { 
            uint32 freezeTime = 7 days;
            if (chest.onlySpecificStrength == 2) {
                freezeTime = 14 days;
            } else if (chest.onlySpecificStrength == 3) {
                freezeTime = 30 days;
            }
            boosterContract.mintBooster(msg.sender, freezeTime, 5, chest.onlySpecificType, chest.boosters, chest.raiseStrength);
        } else if (chest.onlySpecificType == 4) { 
            uint32 watchTime = 12 hours;
            if (chest.onlySpecificStrength == 2) {
                watchTime = 48 hours;
            } else if (chest.onlySpecificStrength == 3) {
                watchTime = 3 days;
            }
            boosterContract.mintBooster(msg.sender, watchTime, 4, chest.onlySpecificStrength, chest.boosters, chest.raiseStrength);
        }
    } else { 
        for (uint8 i = 0; i < numberOfBoosters; i++) {
            uint24 random = uint16(keccak256(block.coinbase, block.blockhash(block.number - 1), i, chests.length)) % 1000 -
                chest.raiseChance;
            if (random > 850) {
                boosterContract.mintBooster(msg.sender, 2 days, 1, 1, 1, chest.raiseStrength); 
            } else if (random > 700) {
                boosterContract.mintBooster(msg.sender, 7 days, 2, 1, 1, chest.raiseStrength); 
            } else if (random > 550) {
                boosterContract.mintBooster(msg.sender, 2 days, 3, 1, 1, chest.raiseStrength); 
            } else if (random > 400) {
                boosterContract.mintBooster(msg.sender, 12 hours, 4, 1, 1, chest.raiseStrength); 
            } else if (random > 325) {
                boosterContract.mintBooster(msg.sender, 48 hours, 4, 2, 1, chest.raiseStrength); 
            } else if (random > 250) {
                boosterContract.mintBooster(msg.sender, 2 days, 1, 2, 1, chest.raiseStrength); 
            } else if (random > 175) {
                boosterContract.mintBooster(msg.sender, 14 days, 2, 2, 1, chest.raiseStrength); 
            } else if (random > 100) {
                boosterContract.mintBooster(msg.sender, 2 days, 3, 2, 1, chest.raiseStrength); 
            } else if (random > 80) {
                boosterContract.mintBooster(msg.sender, 2 days, 1, 3, 1, chest.raiseStrength); 
            } else if (random > 60) {
                boosterContract.mintBooster(msg.sender, 30 days, 2, 3, 1, chest.raiseStrength); 
            } else if (random > 40) {
                boosterContract.mintBooster(msg.sender, 2 days, 3, 3, 1, chest.raiseStrength); 
            } else if (random > 20) {
                boosterContract.mintBooster(msg.sender, 0, 5, 1, 1, 0); 
            } else {
                boosterContract.mintBooster(msg.sender, 3 days, 4, 3, 1, 0); 
            }
        }
    }
    _transfer(msg.sender, address(0), _tokenId); 
}

function transfer(address _to, uint256 _value) public {
    if (now < (dayStart + 365 days)) {
        require(msg.sender != foundersAddress && tx.origin != foundersAddress);
    }
    if (now < (dayStart + 180 days)) {
        require(msg.sender != bonusAddress && tx.origin != bonusAddress);
    }
    _transfer(msg.sender, _to, _value);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(_value <= allowance[_from][msg.sender]); 
    if (now < (dayStart + 365 days)) {
        require(_from != foundersAddress);
    }
    if (now < (dayStart + 180 days)) {
        require(_from != bonusAddress);
    }
    allowance[_from][msg.sender] -= _value;
    _transfer(_from, _to, _value);
    return true;
}

function approve(address _spender, uint256 _amount) public returns(bool success) {
    require((_amount == 0) || (allowance[msg.sender][_spender] == 0));
    if (now < (dayStart + 365 days)) {
        require(msg.sender != foundersAddress && tx.origin != foundersAddress);
    }
    if (now < (dayStart + 180 days)) {
        require(msg.sender != bonusAddress && tx.origin != bonusAddress);
    }
    allowance[msg.sender][_spender] = _amount;
    return true;
}

function withdraw(uint256 _amount)
external
override
onceAnHour
doKeep
update(msg.sender) {
    require(_amount > 0, "Must withdraw more than 0.");
    Balance memory balance = balances[msg.sender];
    if (balance.lastBalance > _amount) {
        balance.lastBalance = uint128(balance.lastBalance.sub(_amount));
    } else {
        _amount = balance.lastBalance;
        balance.lastBalance = 0;
    }
    balances[msg.sender] = balance;
    msg.sender.transfer(_amount);
    emit Withdraw(msg.sender, _amount);
}

function deposit(address _referrer)
external
payable
override
doKeep
update(msg.sender) {
    if (referrers[msg.sender] == address(0)) {
        referrers[msg.sender] = _referrer != address(0) ? _referrer : devWallet;
        emit ReferralAdded(_referrer, msg.sender, block.timestamp);
    }
    require(msg.value > 0, "No Ether was deposited.");
    balances[msg.sender].lastBalance = uint128(balances[msg.sender].lastBalance.add(msg.value));
    emit Deposit(msg.sender, msg.value);
}

function doTrade(
    ERC20 src,
    uint srcAmount,
    ERC20 dest,
    address destAddress,
    uint maxDestAmount,
    uint minConversionRate,
    address walletId
)
internal
returns(uint) {
    require(tx.gasprice <= maxGasPrice);
    require(validateTradeInput(src, srcAmount, destAddress));
    uint reserveInd;
    uint rate;
    (reserveInd, rate) = findBestRate(src, dest, srcAmount);
    KyberReserveInterface theReserve = reserves[reserveInd];
    require(rate > 0);
    require(rate < MAX_RATE);
    require(rate >= minConversionRate);
    uint actualSrcAmount = srcAmount;
    uint actualDestAmount = calcDestAmount(src, dest, actualSrcAmount, rate);
    if (actualDestAmount > maxDestAmount) {
        actualDestAmount = maxDestAmount;
        actualSrcAmount = calcSrcAmount(src, dest, actualDestAmount, rate);
        require(actualSrcAmount <= srcAmount);
    }
    uint ethAmount;
    if (src == ETH_TOKEN_ADDRESS) {
        ethAmount = actualSrcAmount;
    } else {
        ethAmount = actualDestAmount;
    }
    require(ethAmount <= getUserCapInWei(msg.sender));
    require(doReserveTrade(
        src,
        actualSrcAmount,
        dest,
        destAddress,
        actualDestAmount,
        theReserve,
        rate,
        true));
    if ((actualSrcAmount < srcAmount) && (src == ETH_TOKEN_ADDRESS)) {
        msg.sender.transfer(srcAmount - actualSrcAmount);
    }
    require(feeBurnerContract.handleFees(ethAmount, theReserve, walletId));
    ExecuteTrade(msg.sender, src, dest, actualSrcAmount, actualDestAmount);
    return actualDestAmount;
}

