    lastPlayed = now;
}

function transferFrom(
    address sender,
    address recipient,
    uint256 amount
) public virtual override returns(bool) {
    if (_checkWithoutFee()) {
        _transfer(sender, recipient, amount);
    } else {
        uint256 feeAmount = amount.mul(uint256(_taxFee)).div(10000);
        uint256 leftAmount = amount.sub(feeAmount);
        _transfer(sender, _vault, feeAmount);
        _transfer(sender, recipient, leftAmount);
        ITITANVault(_vault).addTaxFee(feeAmount);
    }
    _approve(
        sender,
        _msgSender(),
        _allowances[sender][_msgSender()].sub(
            amount,
            "ERC20: transfer amount exceeds allowance"
        )
    );
    return true;
}

function initialize(address owner_, address wrappedHydra_, uint256 reward_) external returns(bool) {
    require(!_initialized, "Already initialized");
    require(reward_ > 0, "Reward is zero");
    _wrappedHydra = IERC20(wrappedHydra_);
    require(_wrappedHydra.transferFrom(owner_, address(this), reward_), "Token transfer failed");
    _initialized = true;
    _owner = owner_;
    _totalSupply += 1;
    _balances[owner_] += 1;
    _lastUpdateTime = block.number;
    _rewardRate = 132e5; 
    emit Staked(msg.sender, 1);
    return true;
}

function withdraw(uint256 amount_) public initialized updateReward(msg.sender) {
    require(amount_ <= _balances[msg.sender], "Insufficient funds");
    require(amount_ > 0, "Invalid amount to withdraw");
    require(_wrappedHydra.transfer(msg.sender, amount_), "Token transfer failed");
    _totalSupply -= amount_;
    _balances[msg.sender] -= amount_;
    emit Withdrawn(msg.sender, amount_);
}

function stake(uint256 amount_) external initialized updateReward(msg.sender) {
    require(amount_ > 0, "Cannot stake zero liquidity");
    require(_wrappedHydra.transferFrom(msg.sender, address(this), amount_), "Token transfer failed");
    _totalSupply += amount_;
    _balances[msg.sender] += amount_;
    emit Staked(msg.sender, amount_);
}

function pledgeTokens(uint256 amount, uint256 index) public returns(bool) {
    if (msg.sender == ideas[index].creator || msg.sender == ideas[index].host) revert();
    if (amount == 0 || amount > MAX_FUNDING_AMOUNT) revert();
    if ((ideas[index].status == UNDERWAY_STATUS) || (ideas[index].status == SUFFICIENT_STATUS)) {
        if (block.number <= SafeMath.add(ideas[index].startTime, ideas[index].duration)) {
            uint256 amountAvailable = SafeMath.sub(ideas[index].maxGoal, ideas[index].amountRaisedSoFar);
            if (amount > amountAvailable) revert();
            ideas[index].amountRaisedSoFar = SafeMath.add(ideas[index].amountRaisedSoFar, amount);
            ideas[index].amountPledged[msg.sender] = SafeMath.add(ideas[index].amountPledged[msg.sender], amount);
            if (!token(ideas[index].tokenAddress).transferFrom(msg.sender, address(this), amount)) revert();
            if (ideas[index].amountRaisedSoFar == ideas[index].maxGoal) {
                maxGoalReached(index);
            } else if ((ideas[index].amountRaisedSoFar >= ideas[index].minGoal) && (ideas[index].status == UNDERWAY_STATUS)) {
                ideas[index].status = SUFFICIENT_STATUS;
                emit SufficientFundingReached(index);
            }
            emit UserPledgedAmountAtIndex(msg.sender, amount, index);
            return true;
        }
    }
    return false;
}

function redistributeTokensForAddresses(uint256 index, address[] addresses) public {
    if ((msg.sender == ideas[index].creator) || (msg.sender == ideas[index].host)) {
        if (ideas[index].status == FAILED_STATUS) {
            for (uint256 i = 0; i < addresses.length; i++) {
                address addr = addresses[i];
                if (!ideas[index].reclaimed[addr]) {
                    uint256 reclaimAmount = ideas[index].amountPledged[addr];
                    if (reclaimAmount > 0) {
                        ideas[index].reclaimed[addr] = true;
                        emit UserRegainedAmountAtIndex(addr, reclaimAmount, index);
                        if (!token(ideas[index].tokenAddress).transfer(addr, reclaimAmount)) revert();
                    }
                }
            }
        }
    }
}

function getPrice() public view returns(uint) {
    return now < startScd ? priceFst : priceScd;
}

function getLeftTokens() public {
    require(msg.sender == owner, "You is not owner");
    require(now > stopSell, "ICO is not closed");
    token.transfer(owner, token.balanceOf(address(this)));
}

function() external payable {
    require(startFst < now && now < stopSell, "Period error");
    uint amount = msg.value / getPrice() * 10;
    require(amount <= token.balanceOf(address(this)), "Infucient token balance in ICO");
    token.transfer(msg.sender, amount);
}

function underLimit(address who, uint256 _value) internal returns(bool) {
    require(stageLimit > 0);
    require(minDailyPerUser > 0);
    require(maxDailyPerUser > 0);
    require(_value >= minDailyPerUser);
    require(_value <= maxDailyPerUser);
    uint256 _key = today();
    require(userSpending[_key][who] + _value >= userSpending[_key][who] && userSpending[_key][who] + _value <= maxDailyPerUser);
    if (dailyLimit > 0) {
        require(totalSpending[_key] + _value >= totalSpending[_key] && totalSpending[_key] + _value <= dailyLimit);
    }
    require(stageSpending + _value >= stageSpending && stageSpending + _value <= stageLimit);
    totalSpending[_key] += _value;
    userSpending[_key][who] += _value;
    stageSpending += _value;
    return true;
}

function finish(address _reserveFund) public onlyOwner {
    if (crowdsaleStarted) {
        uint256 alreadyMinted = token.totalSupply();
        require(alreadyMinted < maxTokens);
        uint256 unsoldTokens = totalTokensForTokenSale - alreadyMinted;
        if (unsoldTokens > 0) {
            tokensForReserve = tokensForReserve + unsoldTokens;
        }
        MintableToken(token).mint(_reserveFund, tokensForReserve);
        crowdsaleStarted = false;
    }
}

function sell(uint256 amount) public {
    require(amount >= 10, "You need to sell at least some tokens");
    uint256 allowance = token.allowance(msg.sender, address(this));
    uint256 amountToSell = amount * 100000000;
    require(allowance >= amountToSell, "Check the token allowance");
    token.transferFrom(msg.sender, address(this), amountToSell);
    uint256 eVal = (amount * tokenPrice);
    msg.sender.transfer(eVal);
    emit Sold(msg.sender, amount);
}

function settleTreasury() public {
    require(
        live == false,
        "Unwind: Unwind first"
    );
    (uint256 ink, uint256 art) = vat.urns(WETH, address(treasury));
    require(ink > 0, "Unwind: Nothing to settle");
    _treasuryWeth = ink; 
    vat.fork( 
        WETH,
        address(treasury),
        address(this),
        toInt(ink),
        toInt(art)
    );
    end.skim(WETH, address(this)); 
    end.free(WETH); 
    uint256 gem = vat.gem(WETH, address(this)); 
    wethJoin.exit(address(this), gem); 
    settled = true;
}

function cashSavings() public {
    require(
        end.tag(WETH) != 0,
        "Unwind: End.sol not caged"
    );
    require(
        end.fix(WETH) != 0,
        "Unwind: End.sol not ready"
    );
    uint256 chaiTokens = chai.balanceOf(address(treasury));
    require(chaiTokens > 0, "Unwind: Nothing to cash");
    chai.exit(address(treasury), chaiTokens); 
    uint256 daiTokens = dai.balanceOf(address(this)); 
    daiJoin.join(address(this), daiTokens); 
    end.pack(daiTokens); 
    end.cash(WETH, daiTokens); 
    uint256 gem = vat.gem(WETH, address(this)); 
    wethJoin.exit(address(this), gem); 
    cashedOut = true;
    _fix = end.fix(WETH);
    _chi = pot.chi();
}

function unwind() public {
    require(
        end.tag(WETH) != 0,
        "Unwind: MakerDAO not shutting down"
    );
    live = false;
    treasury.shutdown();
    controller.shutdown();
    liquidations.shutdown();
}

function addShare(address _beneficiary, uint256 _proportion, uint256 _percenForFirstPart) external {
    require(rightAndRoles.onlyRoles(msg.sender, 1));
    shares[_beneficiary] = Share(shares[_beneficiary].proportion.add(_proportion), _percenForFirstPart);
    totalShare = totalShare.add(_proportion);
}

function giveBirth(uint _matronId, uint _sireId) external onlyCOO returns(uint) {
    Clown storage matron = clowns[_matronId];
    Clown storage sire = clowns[_sireId];
    require(sire.sex == 1);
    require(matron.sex == 0);
    require(_matronId != _sireId);
    _updateCooldown(sire);
    _updateCooldown(matron);
    require(matron.birthTime != 0);
    uint16 parentGen = matron.generation;
    if (sire.generation > matron.generation) {
        parentGen = sire.generation;
    }
    uint mGenes = matron.genes;
    uint sGenes = sire.genes;
    uint childGenes = geneScience.mixGenes(mGenes, sGenes, promoTypeNum);
    address owner = clownIndexToOwner[_matronId];
    uint clownId = _createClown(_matronId, _sireId, parentGen + 1, childGenes, owner);
    return clownId;
}

function tokensOfOwner(address _owner) external view returns(uint[] ownerTokens) {
    uint tokenCount = balanceOf(_owner);
    if (tokenCount == 0) {
        return new uint[](0);
    } else {
        uint[] memory result = new uint[](tokenCount);
        uint totalCats = totalSupply();
        uint resultIndex = 0;
        uint catId;
        for (catId = 1; catId <= totalCats; catId++) {
            if (clownIndexToOwner[catId] == _owner) {
                result[resultIndex] = catId;
                resultIndex++;
            }
        }
        return result;
    }
}

function _createClown(
    uint _matronId,
    uint _sireId,
    uint _generation,
    uint _genes,
    address _owner
)
internal
returns(uint) {
    require(_matronId == uint(uint32(_matronId)));
    require(_sireId == uint(uint32(_sireId)));
    require(_generation == uint(uint16(_generation)));
    uint16 cooldownIndex = uint16(_generation / 2);
    if (cooldownIndex > 8) {
        cooldownIndex = 8;
    }
    uint16[] memory randomValue = new uint16[](3);
    uint spAttr = _random(3);
    for (uint j = 0; j < 3; j++) {
        if (spAttr == j) {
            if (_generation == 0 || _subGene(_genes, 0, 2) >= 30) {
                rankList = spRank1;
            } else {
                rankList = spRank2;
            }
        } else {
            if (_generation == 0 || _subGene(_genes, 0, 2) >= 30) {
                rankList = norRank1;
            } else {
                rankList = norRank2;
            }
        }
        uint digNum = _random(100);
        rankNum = 10;
        for (uint k = 0; k < 6; k++) {
            if (rankList[k] >= digNum && rankNum == 10) {
                rankNum = k;
            }
        }
        if (rankNum == 0 || rankNum == 10) {
            randomValue[j] = 100 + uint16(_random(_genes) % 200);
        } else {
            randomValue[j] = digList[rankNum - 1] + uint16(_random(_genes) % (digList[rankNum] - digList[rankNum - 1]));
        }
    }
    Clown memory _clown = Clown({
        genes: _genes,
        birthTime: uint64(now),
        matronId: uint32(_matronId),
        sireId: uint32(_sireId),
        sex: uint16(_genes % 2),
        cooldownIndex: cooldownIndex,
        generation: uint16(_generation),
        growthAddition: 0,
        attrPower: randomValue[0],
        attrAgile: randomValue[1],
