    uint256 tmpAffID = 0;
    if (_affID == 0 || plyrAddr_[_affID] == _addr) {
        tmpAffID = plyr_[_addr].laff;
    } else if (plyr_[_addr].laff == 0 && plyrAddr_[_affID] != address(0)) {
        plyr_[_addr].laff = _affID;
        tmpAffID = _affID;
