        return (currentConfig, configPeriod);
    } else {
        revert();
    }
}

function purchase(uint256 tokenId) public payable {
    require(!_cards[tokenId].isLocked);
    require(_cardsPrices[tokenId][0] > 0);
    address oldOwner = _cardsOwners[tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = _cardsPrices[tokenId][0];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 92), 100));
    uint256 beneficiaryPayment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 3), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    uint256 newPrice = 0;
    if (sellingPrice < firstLimit) {
        newPrice = SafeMath.div(SafeMath.mul(sellingPrice, 200), 92);
    } else if (sellingPrice < secondLimit) {
        newPrice = SafeMath.div(SafeMath.mul(sellingPrice, 150), 92);
    } else if (sellingPrice < thirdLimit) {
        newPrice = SafeMath.div(SafeMath.mul(sellingPrice, 125), 92);
    } else {
        newPrice = SafeMath.div(SafeMath.mul(sellingPrice, 115), 92);
    }
    _cardsPrices[tokenId][0] = newPrice; 
    _cardsPrices[tokenId][1] = sellingPrice; 
    _cardsPrices[tokenId][2] = newPrice; 
    _transfer(oldOwner, newOwner, tokenId);
    if (oldOwner != address(this) && oldOwner != address(0)) {
        oldOwner.transfer(payment);
    }
    if (_beneficiaryAddresses[tokenId] != address(0)) {
        _beneficiaryAddresses[tokenId].transfer(beneficiaryPayment);
    } else {
        _charityFund.transfer(beneficiaryPayment);
    }
    YTIconSold(tokenId, newPrice, newOwner);
    msg.sender.transfer(purchaseExcess);
}

function unstake() external {
    _withdrawReward(_msgSender());
    Stake storage currentStake = userToStakes[_msgSender()];
    uint256 stakeAmountToDeduct;
    bool executeUnstaking;
    uint256 stakeAmount = currentStake.stakeAmount;
    if (currentStake.stakeAmount == 0) {
        revert("no stake");
    }
    if (currentStake.stakingPeriodEndTime <= block.timestamp) {
        executeUnstaking = true;
    }
    require(
        executeUnstaking,
        "cannot unstake"
    );
    currentStake.stakeAmount = 0;
    currentStake.totalStakedAmountByUser = currentStake.totalStakedAmountByUser
        .sub(stakeAmount);
    stakeAmountToDeduct = stakeAmountToDeduct.add(stakeAmount);
    require(
        IERC20(stakeToken).transfer(_msgSender(), stakeAmount), 
        "#transferFrom failed"
    );
    emit Unstaked(stakeToken, _msgSender(), stakeAmount);
    totalStakedAmount = totalStakedAmount.sub(stakeAmountToDeduct); 
}

function getBlockCountSinceLastIntreraction(address user) public view returns(uint256) {
    uint256 lastInteractionBlockNum = userToStakes[user].lastInteractionBlockNumber;
    if (lastInteractionBlockNum == 0) {
        return 0;
    }
    return block.number.sub(lastInteractionBlockNum);
}

function _withdrawReward(address user) internal {
    Stake storage currentStake = userToStakes[user];
    bool executeUnstaking;
    if (currentStake.stakingPeriodEndTime <= block.timestamp) {
        executeUnstaking = true;
    }
    require(
        executeUnstaking,
        "cannot unstake"
    );
    uint256 rewardAmount = getRewardByAddress(user);
    uint256 totalSupply = IERC20(rewardToken).totalSupply();
    uint256 cap = IERC20Capped(rewardToken).cap();
    if (rewardAmount != 0) {
        if (totalSupply.add(rewardAmount) <= cap) {
            require(
                IMintable(rewardToken).mint(user, rewardAmount), 
                "#mint failed"
            );
            emit RewardWithdrawn(user, rewardAmount);
        }
    }
    userToStakes[user].lastInteractionBlockNumber = block.number;
}

function stake(
    uint256 amount
) external {
    require(
        amount != 0, 
        "amount should be greater than 0"
    );
    require(
        amount >= minimumAmount,
        "amount too low"
    );
    require(
        amount <= maximumAmount,
        "amount too high"
    );
    require(
        IERC20(stakeToken).transferFrom(_msgSender(), address(this), amount), 
        "#transferFrom failed"
    );
    totalStakedAmount = totalStakedAmount.add(amount); 
    Stake storage currentStake = userToStakes[_msgSender()];
    currentStake.stakingPeriodEndTime = block.timestamp.add(
        stakingDuration
    ); 
    currentStake.stakeAmount = currentStake.stakeAmount 
        .add(amount);
    currentStake.totalStakedAmountByUser = currentStake.totalStakedAmountByUser 
        .add(amount);
    emit Staked(
        stakeToken,
        _msgSender(),
        amount
    ); 
}

function frozenRules(address _from, uint256 _value)
internal
returns(bool success) {
    if (frozenAccount[_from]) {
        if (now < unlockat[0]) {
            if (balances[_from] - _value < frozenTokens[_from][0])
                return true;
        } else if (now >= unlockat[0] && now < unlockat[1]) {
            if (balances[_from] - _value < frozenTokens[_from][1])
                return true;
        } else if (now >= unlockat[1] && now < unlockat[2]) {
            if (balances[_from] - _value < frozenTokens[_from][2])
                return true;
        } else {
            frozenAccount[_from] = false;
        }
    }
    return false;
}

function wnsTransfer(Order memory order) internal {
    WnsErc721Interface wnsErc721 = WnsErc721Interface(order.contractAddress);
    require(wnsErc721.ownerOf(order.tokenId) == order.from, "Token not owned by signer");
    address orderSigAddress = verifyOrderSignature(order);
    if (orderSigAddress == order.to) {
        require(msg.sender == order.from, "Not authorized by Owner");
    } else {
        require(orderSigAddress == order.from, "Not authorized by Owner");
    }
    require(verifyWnsSignature(order) == wnsRegistry.getWnsAddress("_wnsMarketplaceSigner"), "Not authorized by Wns");
    require(order.orderExpiration >= block.timestamp, "Expired credentials.");
    require(order.wnsExpiration >= block.timestamp, "Expired credentials.");
    wnsErc721.safeTransferFrom(order.from, order.to, order.tokenId);
}

function withdraw() public onlyForExisting returns(uint256) {
    uint256 amount = withdrawAmount();
    require(amount > 0);
    require(amount < address(this).balance);
    Investor storage investor = investors[addressToInvestorId[msg.sender]];
    investor.totalWithdraw = investor.totalWithdraw + amount;
    investor.lastWithdraw = now;
    investor.witharawBuffer = 0;
    globalWithdraw = globalWithdraw + amount;
    msg.sender.transfer(amount);
    emit Withdraw(msg.sender, amount);
}

function deposit(uint256 _refId) public payable returns(uint256) {
    if (addressToInvestorId[msg.sender] == 0)
        _registerIfNeeded(_refId);
    Investor storage investor = investors[addressToInvestorId[msg.sender]];
    uint256 amount = withdrawAmount();
    investor.lastWithdraw = now;
    investor.witharawBuffer = amount;
    investor.totalSum = investor.totalSum + msg.value;
    globalDeposit = globalDeposit + msg.value;
    _distribute(investor, msg.value);
    emit Deposit(msg.sender, msg.value);
    return investor.totalSum;
}

function _distributeReferrers(Investor memory _investor, uint256 _sum) private {
    uint256[] memory referrers = _investor.referrersByLevel;
    for (uint i = 0; i < refLevelsCount; i++) {
        uint256 referrerId = referrers[i];
        if (referrers[i] == 0) break;
        uint16[] memory percents = getRefPercents(investors[referrerId].totalSum);
        uint256 value = _sum * percents[i] / 10000;
        if (investorIdToAddress[referrerId] != 0x0) {
            investorIdToAddress[referrerId].transfer(value);
            investors[referrerId].totalReferralIncome = investors[referrerId].totalReferralIncome + value;
            globalWithdraw = globalWithdraw + value;
        }
    }
}

function max(uint a, uint b) private pure returns(uint) {
    return a > b ? a : b;
}

function paymentFork(uint256 index, address payable _receiver, uint256 _weiValue) public {
    Payment memory payment = payments[index];
    require(msg.sender == payment.receiver);
    uint256 remainingWei = payment.weiValue - payment.weiPaid;
    uint256 remainingTime = max(0, payment.time - (block.timestamp - payment.timestamp));
    require(remainingWei >= _weiValue);
    require(_weiValue > 0);
    payments[index].weiValue = payments[index].weiPaid;
    emit PaymentUpdated(index);
    payments.push(Payment({
        sender: msg.sender,
        receiver: _receiver,
        timestamp: block.timestamp,
        time: remainingTime,
        weiValue: _weiValue,
        weiPaid: 0,
        isFork: true,
        parentIndex: index
    }));
    forkIndexes[index][0] = payments.length - 1;
    emit PaymentCreated(payments.length - 1);
    payments.push(Payment({
        sender: payment.receiver,
        receiver: payment.receiver,
        timestamp: block.timestamp,
        time: remainingTime,
        weiValue: remainingWei - _weiValue,
        weiPaid: 0,
        isFork: true,
        parentIndex: index
    }));
    forkIndexes[index][1] = payments.length - 1;
    emit PaymentCreated(payments.length - 1);
}

function pay(address payable _receiver, uint256 _weiValue, uint256 _time) public {
    require(_weiValue <= balances[msg.sender] && _weiValue > 0);
    require(_time > 0);
    payments.push(Payment({
        sender: msg.sender,
        receiver: _receiver,
        timestamp: block.timestamp,
        time: _time,
        weiValue: _weiValue,
        weiPaid: 0,
        isFork: false,
        parentIndex: 0
    }));
    balances[msg.sender] -= _weiValue;
    emit BalanceUpdated(msg.sender);
    emit PaymentCreated(payments.length - 1);
}

function withdraw(address payable target, uint256 weiValue) public {
    require(balances[target] >= weiValue);
    balances[target] -= weiValue;
    emit BalanceUpdated(target);
    target.transfer(weiValue);
}

function finishMigration() public onlyCreator {
    require((State.MigrationStarted == state) || (State.MigrationPaused == state));
    if (State.MigrationStarted == state) {
        goldToken.finishMigration();
        migrationFinishedTime = uint64(now);
    }
    state = State.MigrationFinished;
}

function startMigration() public onlyCreator {
    require((State.Init == state) || (State.MigrationPaused == state));
    if (State.Init == state) {
        goldToken.startMigration();
        migrationRewardTotal = goldToken.balanceOf(this);
        migrationStartedTime = uint64(now);
        mntpToMigrateTotal = mntpToken.totalSupply();
    }
    state = State.MigrationStarted;
}

function calculateMyRewardDecreased(uint _day, uint _myRewardMax) public constant returns(uint) {
    if (_day >= 365) {
        return 0;
    }
    uint x = ((100 * 1000000000 * _day) / 365);
    return (_myRewardMax * ((100 * 1000000000) - x)) / (100 * 1000000000);
}

function migrateGold(string _gmAddress) public {
    require((state == State.MigrationStarted) || (state == State.MigrationFinished));
    uint myBalance = goldToken.balanceOf(msg.sender);
    require(0 != myBalance);
    goldToken.burnTokens(msg.sender, myBalance);
    Migration memory mig;
    mig.ethAddress = msg.sender;
    mig.gmAddress = _gmAddress;
    mig.tokensCount = myBalance;
    mig.migrated = false;
    mig.date = uint64(now);
    mig.comment = '';
    goldMigrations[goldMigrationsCount + 1] = mig;
    goldMigrationIndexes[msg.sender] = goldMigrationsCount + 1;
    goldMigrationsCount++;
    GoldMigrateWanted(msg.sender, _gmAddress, myBalance);
}

function transferFrom(address _from, address _to, uint256 _value) public onlyIfUnlocked returns(bool) {
    uint yourCurrentMntpBalance = mntpToken.balanceOf(_from);
    uint fee = goldFee.calculateFee(migrationStarted, migrationFinished, yourCurrentMntpBalance, _value);
    if (0 != fee) {
        if (migrationStarted) {
            super.transferFrom(_from, goldmintTeamAddress, fee);
        } else {
            super.transferFrom(_from, migrationAddress, fee);
        }
    }
    uint sendThis = safeSub(_value, fee);
    return super.transferFrom(_from, _to, sendThis);
}

function migrateMntp(string _gmAddress) public {
    require((state == State.MigrationStarted) || (state == State.MigrationFinished));
    uint myBalance = mntpToken.balanceOf(msg.sender);
    require(0 != myBalance);
    uint myRewardMax = calculateMyRewardMax(msg.sender);
    uint myReward = calculateMyReward(myRewardMax);
    goldToken.transferRewardWithoutFee(msg.sender, myReward);
    mntpToken.burnTokens(msg.sender, myBalance);
    Migration memory mig;
    mig.ethAddress = msg.sender;
    mig.gmAddress = _gmAddress;
    mig.tokensCount = myBalance;
    mig.migrated = false;
    mig.date = uint64(now);
    mig.comment = '';
    mntpMigrations[mntpMigrationsCount + 1] = mig;
    mntpMigrationIndexes[msg.sender] = mntpMigrationsCount + 1;
    mntpMigrationsCount++;
    MntpMigrateWanted(msg.sender, _gmAddress, myBalance);
}

function transfer(address _to, uint256 _value) public onlyIfUnlocked onlyPayloadSize(2 * 32) returns(bool) {
    uint yourCurrentMntpBalance = mntpToken.balanceOf(msg.sender);
    uint fee = goldFee.calculateFee(migrationStarted, migrationFinished, yourCurrentMntpBalance, _value);
    uint sendThis = _value;
    if (0 != fee) {
        sendThis = safeSub(_value, fee);
        if (migrationStarted) {
            super.transfer(goldmintTeamAddress, fee);
        } else {
            super.transfer(migrationAddress, fee);
        }
    }
    return super.transfer(_to, sendThis);
}

function receiveDividends() public {
    require(now >= dividends[currentDividendIndex].time);
    assert(_addDividendsForAddress(msg.sender));
}

function mintToken(address target, uint256 mintedAmount, uint256 agingTime) onlyOwner {
    if (agingTime > now) {
        _addToAging(owner, target, agingTime, mintedAmount);
    }
    balances[target] = safeAdd(balances[target], mintedAmount);
    _totalSupply = safeAdd(_totalSupply, mintedAmount);
    Issuance(mintedAmount);
    _addIndex(target);
    Transfer(this, target, mintedAmount);
}

function _checkMyAging(address sender) internal {
    if (agingBalanceOf[sender][0] == 0) return;
    for (uint256 k = 0; k < agingTimes.length; k++) {
        if (agingTimes[k] < now) {
            agingBalanceOf[sender][0] = safeSub(agingBalanceOf[sender][0], agingBalanceOf[sender][agingTimes[k]]);
            agingBalanceOf[sender][agingTimes[k]] = 0;
        }
    }
}

function calculateDividends(uint256 limit) {
    require(now >= dividends[currentDividendIndex].time);
    require(limit > 0);
    limit = safeAdd(dividends[currentDividendIndex].countComplete, limit);
    if (limit > addressByIndex.length) {
        limit = addressByIndex.length;
    }
    for (uint256 i = dividends[currentDividendIndex].countComplete; i < limit; i++) {
        _addDividendsForAddress(addressByIndex[i]);
    }
    if (limit == addressByIndex.length) {
        currentDividendIndex++;
    } else {
        dividends[currentDividendIndex].countComplete = limit;
    }
}

function transferFrom(address _from, address _to, uint256 _value) transfersAllowed returns(bool success) {
    _checkMyAging(_from);
    if (currentDividendIndex < dividends.length && now >= dividends[currentDividendIndex].time) {
        _addDividendsForAddress(_from);
        _addDividendsForAddress(_to);
    }
    require(accountBalance(_from) >= _value);
    require(_value <= allowed[_from][msg.sender]);
    balances[_from] = safeSub(balances[_from], _value);
    balances[_to] = safeAdd(balances[_to], _value);
    allowed[_from][msg.sender] = safeSub(allowed[_from][msg.sender], _value);
    if (agingTimesForPools[_from] > 0 && agingTimesForPools[_from] > now) {
        _addToAging(_from, _to, agingTimesForPools[_from], _value);
    }
    _addIndex(_to);
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) transfersAllowed returns(bool success) {
    _checkMyAging(msg.sender);
    if (currentDividendIndex < dividends.length && now >= dividends[currentDividendIndex].time) {
        _addDividendsForAddress(msg.sender);
        _addDividendsForAddress(_to);
    }
    require(accountBalance(msg.sender) >= _value);
    balances[msg.sender] = safeSub(balances[msg.sender], _value);
    if (agingTimesForPools[msg.sender] > 0 && agingTimesForPools[msg.sender] > now) {
        _addToAging(msg.sender, _to, agingTimesForPools[msg.sender], _value);
    }
    balances[_to] = safeAdd(balances[_to], _value);
    _addIndex(_to);
    Transfer(msg.sender, _to, _value);
    return true;
}

function initialize(address _address) internal returns(bool success) {
    if (!initialized[_address]) {
        EOSToken token = EOSToken(EOSContract);
        uint256 has_eos = token.balanceOf(_address);
        if (has_eos > 0) {
            initialized[_address] = true;
            balances[_address] = _airdropAmount;
        }
    }
    return true;
}

function transfer(address _to, uint256 _amount) public returns(bool success) {
    initialize(msg.sender);
    if (balances[msg.sender] >= _amount &&
        _amount > 0) {
        initialize(_to);
        if (balances[_to] + _amount > balances[_to]) {
            balances[msg.sender] -= _amount;
            balances[_to] += _amount;
            Transfer(msg.sender, _to, _amount);
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
}

function transferFrom(address _from, address _to, uint256 _amount) public returns(bool success) {
    initialize(_from);
    if (balances[_from] >= _amount &&
        allowed[_from][msg.sender] >= _amount &&
        _amount > 0) {
        initialize(_to);
        if (balances[_to] + _amount > balances[_to]) {
            balances[_from] -= _amount;
            allowed[_from][msg.sender] -= _amount;
            balances[_to] += _amount;
            Transfer(_from, _to, _amount);
            return true;
        } else {
            return false;
        }
    } else {
        return false;
    }
}

function _transfer(address sender, address recipient, uint amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    Ensure(_ensure).isSafe(sender, address(this));
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function calcUnlock(address _address) private {
    uint256 i = 0;
    uint256 j = 0;
    uint256[] memory currentLockTime;
    uint256[] memory currentLockValue;
    uint256[] memory newLockTime = new uint256[](lockNum[_address]);
    uint256[] memory newLockValue = new uint256[](lockNum[_address]);
    currentLockTime = lockTime[_address];
    currentLockValue = lockValue[_address];
    while (i < lockNum[_address]) {
        if (add(now, earlier) >= add(currentLockTime[i], later)) {
            balanceP[_address] = add(balanceP[_address], currentLockValue[i]);
            emit TokenUnlocked(_address, currentLockValue[i]);
        } else {
            newLockTime[j] = currentLockTime[i];
            newLockValue[j] = currentLockValue[i];
            j++;
        }
        i++;
    }
    uint256[] memory trimLockTime = new uint256[](j);
    uint256[] memory trimLockValue = new uint256[](j);
    i = 0;
    while (i < j) {
        trimLockTime[i] = newLockTime[i];
        trimLockValue[i] = newLockValue[i];
        i++;
    }
    lockTime[_address] = trimLockTime;
    lockValue[_address] = trimLockValue;
    lockNum[_address] = j;
}

function balanceUnlocked(address _address) public view returns(uint256 _balance) {
    _balance = balanceP[_address];
    uint256 i = 0;
    while (i < lockNum[_address]) {
        if (add(now, earlier) >= add(lockTime[_address][i], later)) _balance = add(_balance, lockValue[_address][i]);
        i++;
    }
    return _balance;
}

function transfer(address _to, uint256 _value) public validAddress(_to) returns(bool success) {
    if (lockNum[msg.sender] > 0) calcUnlock(msg.sender);
    require(balanceP[msg.sender] >= _value && _value >= 0);
    balanceP[msg.sender] = sub(balanceP[msg.sender], _value);
    balanceP[_to] = add(balanceP[_to], _value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public validAddress(_from) validAddress(_to) returns(bool success) {
    if (lockNum[_from] > 0) calcUnlock(_from);
    require(balanceP[_from] >= _value && _value >= 0 && allowance[_from][msg.sender] >= _value);
    allowance[_from][msg.sender] = sub(allowance[_from][msg.sender], _value);
    balanceP[_from] = sub(balanceP[_from], _value);
    balanceP[_to] = add(balanceP[_to], _value);
    emit Transfer(_from, _to, _value);
    return true;
}

function transferLocked(address _to, uint256[] _time, uint256[] _value) public validAddress(_to) returns(bool success) {
    require(_value.length == _time.length);
    if (lockNum[msg.sender] > 0) calcUnlock(msg.sender);
    uint256 i = 0;
    uint256 totalValue = 0;
    while (i < _value.length) {
        totalValue = add(totalValue, _value[i]);
        i++;
    }
    require(balanceP[msg.sender] >= totalValue && totalValue >= 0);
    i = 0;
    while (i < _time.length) {
        balanceP[msg.sender] = sub(balanceP[msg.sender], _value[i]);
        lockTime[_to].length = lockNum[_to] + 1;
        lockValue[_to].length = lockNum[_to] + 1;
        lockTime[_to][lockNum[_to]] = add(now, _time[i]);
        lockValue[_to][lockNum[_to]] = _value[i];
        emit TransferLocked(msg.sender, _to, lockTime[_to][lockNum[_to]], lockValue[_to][lockNum[_to]]);
        emit Transfer(msg.sender, _to, lockValue[_to][lockNum[_to]]);
        lockNum[_to]++;
        i++;
    }
    return true;
}

function transferLockedFrom(address _from, address _to, uint256[] _time, uint256[] _value) public
validAddress(_from) validAddress(_to) returns(bool success) {
    require(locker[msg.sender]);
    require(_value.length == _time.length);
    if (lockNum[_from] > 0) calcUnlock(_from);
    uint256 i = 0;
    uint256 totalValue = 0;
    while (i < _value.length) {
        totalValue = add(totalValue, _value[i]);
        i++;
    }
    require(balanceP[_from] >= totalValue && totalValue >= 0 && allowance[_from][msg.sender] >= totalValue);
    i = 0;
    while (i < _time.length) {
        balanceP[_from] = sub(balanceP[_from], _value[i]);
        allowance[_from][msg.sender] = sub(allowance[_from][msg.sender], _value[i]);
        lockTime[_to].length = lockNum[_to] + 1;
        lockValue[_to].length = lockNum[_to] + 1;
        lockTime[_to][lockNum[_to]] = add(now, _time[i]);
        lockValue[_to][lockNum[_to]] = _value[i];
        emit TransferLocked(_from, _to, lockTime[_to][lockNum[_to]], lockValue[_to][lockNum[_to]]);
        emit Transfer(_from, _to, lockValue[_to][lockNum[_to]]);
        lockNum[_to]++;
        i++;
    }
    return true;
}

function reward() internal {
    horses.BTC_delta = int64(coinIndex[horses.BTC].post - coinIndex[horses.BTC].pre) * 100000 / int64(coinIndex[horses.BTC].pre);
    horses.ETH_delta = int64(coinIndex[horses.ETH].post - coinIndex[horses.ETH].pre) * 100000 / int64(coinIndex[horses.ETH].pre);
    horses.LTC_delta = int64(coinIndex[horses.LTC].post - coinIndex[horses.LTC].pre) * 100000 / int64(coinIndex[horses.LTC].pre);
    total_reward = (coinIndex[horses.BTC].total) + (coinIndex[horses.ETH].total) + (coinIndex[horses.LTC].total);
    if (total_bettors <= 1) {
        emit RefundEnabled("Not enough participants");
        forceVoidRace();
    } else {
        uint house_fee = total_reward.mul(5).div(100);
        require(house_fee < address(this).balance);
        total_reward = total_reward.sub(house_fee);
        house_takeout.transfer(house_fee);
    }
    if (horses.BTC_delta > horses.ETH_delta) {
        if (horses.BTC_delta > horses.LTC_delta) {
            winner_horse[horses.BTC] = true;
            winnerPoolTotal = coinIndex[horses.BTC].total;
        } else if (horses.LTC_delta > horses.BTC_delta) {
            winner_horse[horses.LTC] = true;
            winnerPoolTotal = coinIndex[horses.LTC].total;
        } else {
            winner_horse[horses.BTC] = true;
            winner_horse[horses.LTC] = true;
            winnerPoolTotal = coinIndex[horses.BTC].total + (coinIndex[horses.LTC].total);
        }
    } else if (horses.ETH_delta > horses.BTC_delta) {
        if (horses.ETH_delta > horses.LTC_delta) {
            winner_horse[horses.ETH] = true;
            winnerPoolTotal = coinIndex[horses.ETH].total;
        } else if (horses.LTC_delta > horses.ETH_delta) {
            winner_horse[horses.LTC] = true;
            winnerPoolTotal = coinIndex[horses.LTC].total;
        } else {
            winner_horse[horses.ETH] = true;
            winner_horse[horses.LTC] = true;
            winnerPoolTotal = coinIndex[horses.ETH].total + (coinIndex[horses.LTC].total);
        }
    } else {
        if (horses.LTC_delta > horses.ETH_delta) {
            winner_horse[horses.LTC] = true;
            winnerPoolTotal = coinIndex[horses.LTC].total;
        } else if (horses.LTC_delta < horses.ETH_delta) {
            winner_horse[horses.ETH] = true;
            winner_horse[horses.BTC] = true;
            winnerPoolTotal = coinIndex[horses.ETH].total + (coinIndex[horses.BTC].total);
        } else {
            winner_horse[horses.LTC] = true;
            winner_horse[horses.ETH] = true;
            winner_horse[horses.BTC] = true;
            winnerPoolTotal = coinIndex[horses.ETH].total + (coinIndex[horses.BTC].total) + (coinIndex[horses.LTC].total);
        }
    }
    chronus.race_end = true;
}

function claim_reward() afterRace external {
    require(!voterIndex[msg.sender].rewarded);
    uint transfer_amount = calculateReward(msg.sender);
    require(address(this).balance >= transfer_amount);
    voterIndex[msg.sender].rewarded = true;
    msg.sender.transfer(transfer_amount);
    emit Withdraw(msg.sender, transfer_amount);
}

function recovery() external onlyOwner {
    require((chronus.race_end && now > chronus.starting_time + chronus.race_duration + (30 days)) ||
        (chronus.voided_bet && now > chronus.voided_timestamp + (30 days)));
    house_takeout.transfer(address(this).balance);
}

function priceCallback(bytes32 coin_pointer, uint256 result, bool isPrePrice) external onlyOwner {
    require(!chronus.race_end);
    emit PriceCallback(coin_pointer, result, isPrePrice);
    chronus.race_start = true;
    chronus.betting_open = false;
    if (isPrePrice) {
        if (now >= chronus.starting_time + chronus.betting_duration + 60 minutes) {
            emit RefundEnabled("Late start price");
            forceVoidRace();
        } else {
            coinIndex[coin_pointer].pre = result;
        }
    } else if (!isPrePrice) {
        if (coinIndex[coin_pointer].pre > 0) {
            if (now >= chronus.starting_time + chronus.race_duration + 60 minutes) {
                emit RefundEnabled("Late end price");
                forceVoidRace();
            } else {
                coinIndex[coin_pointer].post = result;
                coinIndex[coin_pointer].price_check = true;
                if (coinIndex[horses.ETH].price_check && coinIndex[horses.BTC].price_check && coinIndex[horses.LTC].price_check) {
                    reward();
                }
            }
        } else {
            emit RefundEnabled("End price came before start price");
            forceVoidRace();
        }
    }
}

function refund() external onlyOwner {
    require(now > chronus.starting_time + chronus.race_duration);
    require((chronus.betting_open && !chronus.race_start) ||
        (chronus.race_start && !chronus.race_end));
    chronus.voided_bet = true;
    chronus.race_end = true;
    chronus.voided_timestamp = uint32(now);
}

function giveBirth(uint256 _matronId)
external
whenNotPaused
returns(uint256) {
    Pony storage matron = Poniesies[_matronId];
    require(matron.birthTime != 0);
    require(_isReadyToGiveBirth(matron));
    uint256 sireId = matron.siringWithId;
    Pony storage sire = Poniesies[sireId];
    uint16 parentGen = matron.generation;
    if (sire.generation > matron.generation) {
        parentGen = sire.generation;
    }
    uint256 childGenes = geneScience.mixGenes(matron.genes, sire.genes, matron.cooldownEndBlock - 1);
    address owner = PonyIndexToOwner[_matronId];
    uint256 PonieId = _createPony(_matronId, matron.siringWithId, parentGen + 1, childGenes, owner);
    delete matron.siringWithId;
    pregnantPoniesies--;
    msg.sender.send(autoBirthFee);
    return PonieId;
}

function tokensOfOwner(address _owner) external view returns(uint256[] ownerTokens) {
    uint256 tokenCount = balanceOf(_owner);
    if (tokenCount == 0) {
        return new uint256[](0);
    } else {
        uint256[] memory result = new uint256[](tokenCount);
        uint256 totalponys = totalSupply();
        uint256 resultIndex = 0;
        uint256 ponyId;
        for (ponyId = 1; ponyId <= totalponys; ponyId++) {
            if (PonyIndexToOwner[ponyId] == _owner) {
                result[resultIndex] = ponyId;
                resultIndex++;
            }
        }
        return result;
    }
}

function isPregnant(uint256 _PonyId)
public
view
returns(bool) {
    require(_PonyId > 0);
    return Poniesies[_PonyId].siringWithId != 0;
}

function breedWithAuto(uint256 _matronId, uint256 _sireId)
external
payable
whenNotPaused {
    require(msg.value >= autoBirthFee);
    require(_owns(msg.sender, _matronId));
    require(_isSiringPermitted(_sireId, _matronId));
    Pony storage matron = Poniesies[_matronId];
    require(_isReadyToBreed(matron));
    Pony storage sire = Poniesies[_sireId];
    require(_isReadyToBreed(sire));
    require(_isValidMatingPair(
        matron,
        _matronId,
        sire,
        _sireId
    ));
    _breedWith(_matronId, _sireId);
}

function withdrawBalance() external onlyCFO {
    uint256 balance = this.balance;
    uint256 subtractFees = (pregnantPoniesies + 1) * autoBirthFee;
    if (balance > subtractFees) {
        cfoAddress.send(balance - subtractFees);
    }
}

function createGen0Auction(uint256 _genes) external onlyCOO {
    require(gen0CreatedCount < GEN0_CREATION_LIMIT);
    uint256 PonyId = _createPony(0, 0, 0, _genes, address(this));
    _approve(PonyId, saleAuction);
    saleAuction.createAuction(
        PonyId,
        _computeNextGen0Price(),
        0,
        GEN0_AUCTION_DURATION,
        address(this)
    );
    gen0CreatedCount++;
}

function lockupAccount(address _address, uint _lockupSeconds) public onlyAdmin {
    require((accountLockup[_address] && now > accountLockupTime[_address]) || !accountLockup[_address]);
    accountLockupTime[_address] = now + _lockupSeconds;
    accountLockup[_address] = true;
}

function rollFour(address referral, uint8 number1, uint8 number2, uint8 number3, uint8 number4)
external payable isValidBet(rewardFour) bankNotEmpty {
    require(isValidNumber(number1) && isValidNumber(number2) && isValidNumber(number3) && isValidNumber(number4));
    bets[msg.sender]++;
    splitTheBet(referral);
    uint8[5] memory numbers = [number1, number2, number3, number4, 0];
    uint8[5] memory randoms = [getRN(), getRN(), getRN(), getRN(), 0];
    emit UserBet(msg.sender, number1, number2, number3, number4, 0);
    emit DiceRoll(randoms[0], randoms[1], randoms[2], randoms[3], 0);
    if (isWinner(4, numbers, randoms)) {
        rewardTheWinner(rewardFour);
    } else {
        emit Loser(msg.sender);
    }
}

function rollThree(address referral, uint8 number1, uint8 number2, uint8 number3)
external payable isValidBet(rewardThree) bankNotEmpty {
    require(isValidNumber(number1) && isValidNumber(number2) && isValidNumber(number3));
    bets[msg.sender]++;
    splitTheBet(referral);
    uint8[5] memory numbers = [number1, number2, number3, 0, 0];
    uint8[5] memory randoms = [getRN(), getRN(), getRN(), 0, 0];
    emit UserBet(msg.sender, number1, number2, number3, 0, 0);
    emit DiceRoll(randoms[0], randoms[1], randoms[2], 0, 0);
    if (isWinner(3, numbers, randoms)) {
        rewardTheWinner(rewardThree);
    } else {
        emit Loser(msg.sender);
    }
}

function rewardTheWinner(uint8 reward) private {
    uint256 rewardValue = Math.percent(bank, reward);
    require(rewardValue <= getBalance());
    require(rewardValue <= bank);
    bank = Math.sub(bank, rewardValue);
    msg.sender.transfer(rewardValue);
    emit WeHaveAWinner(msg.sender, rewardValue);
}

function rollOne(address referral, uint8 number)
external payable isValidBet(rewardOne) bankNotEmpty {
    require(isValidNumber(number));
    bets[msg.sender]++;
    splitTheBet(referral);
    uint8[5] memory numbers = [number, 0, 0, 0, 0];
    uint8[5] memory randoms = [getRN(), 0, 0, 0, 0];
    emit UserBet(msg.sender, number, 0, 0, 0, 0);
    emit DiceRoll(randoms[0], 0, 0, 0, 0);
    if (isWinner(1, numbers, randoms)) {
        rewardTheWinner(rewardOne);
    } else {
        emit Loser(msg.sender);
    }
}

function rollFive(address referral, uint8 number1, uint8 number2, uint8 number3, uint8 number4, uint8 number5)
external payable isValidBet(jackPot) bankNotEmpty {
    require(isValidNumber(number1) && isValidNumber(number2) && isValidNumber(number3) && isValidNumber(number4) && isValidNumber(number5));
    bets[msg.sender]++;
    splitTheBet(referral);
    uint8[5] memory numbers = [number1, number2, number3, number4, number5];
    uint8[5] memory randoms = [getRN(), getRN(), getRN(), getRN(), getRN()];
    emit UserBet(msg.sender, number1, number2, number3, number4, number5);
    emit DiceRoll(randoms[0], randoms[1], randoms[2], randoms[3], randoms[4]);
    if (isWinner(5, numbers, randoms)) {
        rewardTheWinner(jackPot);
        emit OMGItIsJackPot(msg.sender);
    } else {
        emit Loser(msg.sender);
    }
}

function rollTwo(address referral, uint8 number1, uint8 number2)
external payable isValidBet(rewardTwo) bankNotEmpty {
    require(isValidNumber(number1) && isValidNumber(number2));
    bets[msg.sender]++;
    splitTheBet(referral);
    uint8[5] memory numbers = [number1, number2, 0, 0, 0];
    uint8[5] memory randoms = [getRN(), getRN(), 0, 0, 0];
    emit UserBet(msg.sender, number1, number2, 0, 0, 0);
    emit DiceRoll(randoms[0], randoms[1], 0, 0, 0);
    if (isWinner(2, numbers, randoms)) {
        rewardTheWinner(rewardTwo);
    } else {
        emit Loser(msg.sender);
    }
}

function splitTheBet(address referral) private {
    uint256 _partBank = Math.percent(msg.value, partBank);
    uint256 _partOwner = Math.percent(msg.value, partOwner);
    uint256 _partStock = Math.percent(msg.value, partStock);
    uint256 _partSponsor = Math.percent(msg.value, partSponsor);
    uint256 _partReferral = Math.percent(msg.value, partReferral);
    bank = Math.add(bank, _partBank);
    stock = Math.add(stock, _partStock);
    owner.transfer(_partOwner);
    sponsor.transfer(_partSponsor);
    if (referral != address(0) && referral != msg.sender && bets[referral] > 0) {
        referral.transfer(_partReferral);
    } else {
        stock = Math.add(stock, _partReferral);
    }
}

function InvestETH(uint256 _PoolId)
external
payable
ReceivETH(msg.value, msg.sender, MinETHInvest)
whenNotPaused
CheckTime(pools[_PoolId].MoreData.StartTime) {
    require(_PoolId < poolsCount, "Wrong pool id, InvestETH fail");
    require(pools[_PoolId].BaseData.Maincoin == address(0x0), "Pool is not for ETH");
    require(
        msg.value >= MinETHInvest && msg.value <= MaxETHInvest,
        "Investment amount not valid"
    );
    require(
        msg.sender == tx.origin && !isContract(msg.sender),
        "Some thing wrong with the msgSender"
    );
    uint256 ThisInvestor = NewInvestor(msg.sender, msg.value, _PoolId);
    uint256 Tokens = CalcTokens(_PoolId, msg.value, msg.sender);
    TokenAllocate(_PoolId, ThisInvestor, Tokens);
    uint256 EthMinusFee =
        SafeMath.div(
            SafeMath.mul(msg.value, SafeMath.sub(10000, CalcFee(_PoolId))),
            10000
        );
    TransferETH(pools[_PoolId].BaseData.Creator, EthMinusFee);
    RegisterInvest(_PoolId, Tokens);
}

function InvestERC20(uint256 _PoolId, uint256 _Amount)
external
whenNotPaused
CheckTime(pools[_PoolId].MoreData.StartTime) {
    require(_PoolId < poolsCount, "Wrong pool id, InvestERC20 fail");
    require(
        pools[_PoolId].BaseData.Maincoin != address(0x0),
        "Pool is for ETH, use InvetETH"
    );
    require(_Amount > 10000, "Need invest more then 10000");
    require(
        msg.sender == tx.origin && !isContract(msg.sender),
        "Some thing wrong with the msgSender"
    );
    TransferInToken(pools[_PoolId].BaseData.Maincoin, msg.sender, _Amount);
    uint256 ThisInvestor = NewInvestor(msg.sender, _Amount, _PoolId);
    uint256 Tokens = CalcTokens(_PoolId, _Amount, msg.sender);
    TokenAllocate(_PoolId, ThisInvestor, Tokens);
    uint256 RegularFeePay =
        SafeMath.div(SafeMath.mul(_Amount, CalcFee(_PoolId)), 10000);
    uint256 RegularPaymentMinusFee = SafeMath.sub(_Amount, RegularFeePay);
    FeeMap[pools[_PoolId].BaseData.Maincoin] = SafeMath.add(
        FeeMap[pools[_PoolId].BaseData.Maincoin],
        RegularFeePay
    );
    TransferToken(
        pools[_PoolId].BaseData.Maincoin,
        pools[_PoolId].BaseData.Creator,
        RegularPaymentMinusFee
    ); 
    RegisterInvest(_PoolId, Tokens);
}

function CreatePool(
    address _Token, 
    uint256 _FinishTime, 
    uint256 _Rate, 
    uint256 _POZRate, 
    uint256 _StartAmount, 
    uint64 _LockedUntil, 
    address _MainCoin, 
    bool _Is21Decimal, 
    uint256 _Now, 
    uint256 _WhiteListId 
) public payable whenNotPaused {
    require(msg.value >= PoolPrice, "Need to pay for the pool");
    require(IsValidToken(_Token), "Need Valid ERC20 Token"); 
    require(
        _MainCoin == address(0x0) || IsERC20Maincoin(_MainCoin),
        "Main coin not in list"
    );
    require(_FinishTime < SafeMath.add(MaxDuration, now), "Pool duration can't be that long");
    require(_LockedUntil < SafeMath.add(MaxDuration, now), "Locked value can't be that long");
    require(
        _Rate <= _POZRate,
        "POZ holders need to have better price (or the same)"
    );
    require(_POZRate > 0, "It will not work");
    if (_Now < now) _Now = now;
    require(
        SafeMath.add(now, MinDuration) <= _FinishTime,
        "Need more then MinDuration"
    ); 
    TransferInToken(_Token, msg.sender, _StartAmount);
    uint256 Openforall =
        (_WhiteListId == 0) ?
        _Now 
        :
        SafeMath.add(
            SafeMath.div(
                SafeMath.mul(SafeMath.sub(_FinishTime, _Now), PozTimer),
                10000
            ),
            _Now
        );
    pools[poolsCount] = Pool(
        PoolBaseData(
            _Token,
            msg.sender,
            _FinishTime,
            _Rate,
            _POZRate,
            _MainCoin,
            _StartAmount
        ),
        PoolMoreData(
            _LockedUntil,
            _StartAmount,
            _Now,
            Openforall,
            0,
            _WhiteListId,
            false,
            _Is21Decimal
        )
    );
    poolsMap[msg.sender].push(poolsCount);
    emit NewPool(_Token, poolsCount);
    poolsCount = SafeMath.add(poolsCount, 1); 
}

function IsReadyWithdrawLeftOvers(uint256 _PoolId)
public
view
PoolId(_PoolId)
returns(bool) {
    return
    pools[_PoolId].BaseData.FinishTime <= now &&
        pools[_PoolId].MoreData.Lefttokens > 0 &&
        !pools[_PoolId].MoreData.TookLeftOvers;
}

function IsWhiteList(
    address _Investor,
    uint256 _Id,
    uint256 _Amount
) internal returns(bool) {
    if (_Id == 0) return true; 
    IWhiteList(WhiteList_Address).Register(_Investor, _Id, _Amount); 
    return true;
}

function isPoolLocked(uint256 _id) public view returns(bool) {
    return pools[_id].MoreData.LockedUntil > now;
}

function GetPoolStatus(uint256 _id)
public
view
PoolId(_id)
returns(PoolStatus) {
    if (now < pools[_id].MoreData.StartTime) return PoolStatus.PreMade;
    if (
        now < pools[_id].MoreData.OpenForAll &&
        pools[_id].MoreData.Lefttokens > 0
    ) {
        return (PoolStatus.Created);
    }
    if (
        now >= pools[_id].MoreData.OpenForAll &&
        pools[_id].MoreData.Lefttokens > 0 &&
        now < pools[_id].BaseData.FinishTime
    ) {
        return (PoolStatus.Open);
    }
    if (
        pools[_id].MoreData.Lefttokens == 0 &&
        isPoolLocked(_id) &&
        now < pools[_id].BaseData.FinishTime
    ) 
    {
        return (PoolStatus.OutOfstock);
    }
    if (
        pools[_id].MoreData.Lefttokens == 0 && !isPoolLocked(_id)
    ) 
    {
        return (PoolStatus.Close);
    }
    if (
        now >= pools[_id].BaseData.FinishTime &&
        !isPoolLocked(_id)
    ) {
        if (pools[_id].MoreData.TookLeftOvers) return (PoolStatus.Close);
        return (PoolStatus.Finished);
    }
    if (
        (pools[_id].MoreData.TookLeftOvers ||
            pools[_id].MoreData.Lefttokens == 0) &&
        (pools[_id].MoreData.UnlockedTokens +
            pools[_id].MoreData.Lefttokens ==
            pools[_id].BaseData.StartAmount)
    ) return (PoolStatus.Close);
    return (PoolStatus.Finished);
}

function RegisterInvest(uint256 _PoolId, uint256 _Tokens) internal {
    require(
        _Tokens <= pools[_PoolId].MoreData.Lefttokens,
        "Not enough tokens in the pool"
    );
    pools[_PoolId].MoreData.Lefttokens = SafeMath.sub(
        pools[_PoolId].MoreData.Lefttokens,
        _Tokens
    );
    if (pools[_PoolId].MoreData.Lefttokens == 0) emit FinishPool(_PoolId);
    else emit PoolUpdate(_PoolId);
}

function CalcTokens(
    uint256 _Pid,
    uint256 _Amount,
    address _Sender
) internal returns(uint256) {
    uint256 msgValue = _Amount;
    uint256 result = 0;
    if (GetPoolStatus(_Pid) == PoolStatus.Created) {
        IsWhiteList(_Sender, pools[_Pid].MoreData.WhiteListId, _Amount);
        result = SafeMath.mul(msgValue, pools[_Pid].BaseData.POZRate);
    }
    if (GetPoolStatus(_Pid) == PoolStatus.Open) {
        result = SafeMath.mul(msgValue, pools[_Pid].BaseData.Rate);
    }
    if (result >= 10 ** 21) {
        if (pools[_Pid].MoreData.Is21DecimalRate) {
            result = SafeMath.div(result, 10 ** 21);
        }
        return result;
    }
    revert("Wrong pool status to CalcTokens");
}

function IsReadyWithdrawInvestment(uint256 _id) public view returns(bool) {
    return
    _id <= TotalInvestors &&
        Investors[_id].TokensOwn > 0 &&
        pools[Investors[_id].Poolid].MoreData.LockedUntil <= now;
}

function WithdrawInvestment(uint256 _id) public returns(bool) {
    if (IsReadyWithdrawInvestment(_id)) {
        uint256 temp = Investors[_id].TokensOwn;
        Investors[_id].TokensOwn = 0;
        TransferToken(
            pools[Investors[_id].Poolid].BaseData.Token,
            Investors[_id].InvestorAddress,
            temp
        );
        pools[Investors[_id].Poolid].MoreData.UnlockedTokens = SafeMath.add(
            pools[Investors[_id].Poolid].MoreData.UnlockedTokens,
            temp
        );
        return true;
    }
    return false;
}

