function cancel_contract() public {
    assert(contract_terminated == false);
    assert(init_level < 3);
    organizer.transfer(this.balance);
    contract_terminated = true;
}

function finalize_contract() public {
    assert(contract_terminated == false);
    assert(init_level == 3);
    assert(block.number >= init3_block_height + submission_stage_block_size + reveal_test_data_groups_block_size + evaluation_stage_block_size);
    Submission memory best_submission = submission_queue[best_submission_index];
    if (best_submission_accuracy >= model_accuracy_criteria) {
        best_submission.payment_address.transfer(this.balance);
    } else {
        organizer.transfer(this.balance);
    }
    contract_terminated = true;
}

function swapBack(uint256 totalTokensForFee) private {
    uint256 toSwap = swapAtAmount;
    uint256 liquidityTokens = toSwap.mul(tokensForLiquidity).div(totalTokensForFee).div(2);
    uint256 taxTokens = toSwap.sub(liquidityTokens).sub(liquidityTokens);
    uint256 amountToSwapForETH = toSwap.sub(liquidityTokens);
    _swapTokensForETH(amountToSwapForETH);
    uint256 ethBalance = address(this).balance;
    uint256 ethForTax = ethBalance.mul(taxTokens).div(amountToSwapForETH);
    uint256 ethForLiquidity = ethBalance.sub(ethForTax);
    tokensForLiquidity = tokensForLiquidity.sub(liquidityTokens.mul(2));
    tokensForTax = tokensForTax.sub(toSwap.sub(liquidityTokens.mul(2)));
    if ((ethForLiquidity > 0) && liquifyEnabled) {
        _addLiquidity(liquidityTokens, ethForLiquidity);
        payable(address(dev)).transfer(ethForTax);
    } else {
        payable(address(dev)).transfer(ethBalance);
    }
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    buyTxFee = defaultBuyTxFee;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + deadblocks &&
        !isExcludedFromFees[to]
    ) {
        buyTxFee = 90;
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            if (useBuyMap) {
                if (_buyMap[from] != 0 &&
                    (_buyMap[from] + (1 hours) >= block.timestamp)) {
                    sellLiquidityFee = hourSellLiquidityFee;
                    sellTxFee = hourSellTxFee;
                    _buyMap[from] = block.timestamp;
                } else {
                    sellLiquidityFee = defaultSellLiquidityFee;
                    sellTxFee = defaultSellTxFee;
                }
            } else {
                sellLiquidityFee = defaultSellLiquidityFee;
                sellTxFee = defaultSellTxFee;
            }
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            if (cooldownEnabled) {
                require(cooldown[to] < block.timestamp);
                cooldown[to] = block.timestamp + (30 seconds);
            }
            if (useBuyMap && _buyMap[to] == 0) {
                _buyMap[to] = block.timestamp;
            }
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

function _forwardFunds() internal {
    uint256 _rateWei = 100000000;
    uint256 tecTokensRate = 6896551;
    uint256 msgValue = msg.value;
    uint256 tecValue = msgValue.mul(tecTokensRate).div(_rateWei);
    uint256 crowdValue = msgValue.sub(tecValue);
    techWallet.transfer(tecValue);
    wallet.transfer(crowdValue);
    emit TokenAmount("_forwardFunds ", msgValue);
    emit TokenAmount("_forwardFunds ", tecValue);
    emit TokenAmount("_forwardFunds ", crowdValue);
}

function computeTokens(uint256 _weiAmount) public constant returns(uint256) {
    uint256 tokens = _weiAmount.mul(getRate());
    uint256 crowNums = CROWDSALE_TOKENS_NUMS;
    uint256 totolCrowd_ = token.totalCrowdSale();
    uint256 leftNums = crowNums.sub(totolCrowd_);
    require(leftNums >= tokens);
    return tokens;
}

function getRate() public constant returns(uint256) {
    uint256 ret = 1;
    uint256 reduInterval = 1000;
    uint256 reduRate = reduInterval.div(9);
    uint256 startTimeStamp = now.sub(openingTime);
    if (startTimeStamp < intervalTime) {
        startTimeStamp = 0;
    }
    ret = startRate - (startTimeStamp.div(intervalTime).mul(reduRate));
    if (closingTime.sub(now) < intervalTime) {
        ret = 10000;
    }
    return ret;
}

function buyTokens(address _beneficiary) public payable {
    uint256 weiAmount = msg.value;
    _preValidatePurchase(_beneficiary, weiAmount);
    uint256 tokens = _getTokenAmount(weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens);
    _processPurchase(_beneficiary, tokens);
    _updatePurchasingState(_beneficiary, weiAmount);
    _forwardFunds();
    _postValidatePurchase(_beneficiary, weiAmount);
}

