function getLateFee(address contributor) public view returns(uint) {
    require(loanMatured(contributor));
    Loan memory memLoan = Loans[contributor];
    uint totalReward = memLoan.totalContribution + memLoan.bounty;
    uint endDate = memLoan.start + memLoan.contractTime;
    uint periodsLateBy = (now - endDate) / period;
    uint totalPenalty;
    uint periodPenalty;
    if (periodsLateBy >= 2000) {
        totalPenalty = totalReward;
    } else if (periodsLateBy <= 10) {
        return (0);
    } else {
        uint i;
        while (i++ < uint(periodsLateBy - 10)) {
            periodPenalty = totalReward * 7 / 1000;
            totalPenalty += periodPenalty; 
            totalReward -= periodPenalty;
        }
    }
    return (totalPenalty);
}

function settleBetCommon(Bet storage bet, uint reveal, uint commit, bytes32 entropyBlockHash) private {
    uint amount = bet.amount;
    uint modulo = bet.modulo;
    uint rollUnder = bet.rollUnder;
    address gambler = bet.gambler;
    require(amount != 0, "Bet should be in an 'active' state");
    bet.amount = 0;
    bytes32 entropy = keccak256(abi.encodePacked(reveal, entropyBlockHash));
    uint dice = uint(entropy).mod(modulo);
    uint diceWinAmount;
    diceWinAmount = getDiceWinAmount(amount, modulo, rollUnder);
    uint diceWin = 0;
    if (modulo <= MAX_MASK_MODULO) {
        if ((2 ** dice) & bet.mask != 0) {
            diceWin = diceWinAmount;
        }
    } else {
        if (dice < rollUnder) {
            diceWin = diceWinAmount;
        }
    }
    lockedInBets = lockedInBets.sub(diceWinAmount);
    gambler.transfer(diceWin == 0 ? 1 wei : diceWin);
    emit SettleBet(commit, dice, amount, diceWin);
}

function refundBet(uint commit) external {
    Bet storage bet = bets[commit];
    uint amount = bet.amount;
    require(amount != 0, "Bet should be in an 'active' state");
    require(block.number > bet.placeBlockNumber.add(betExpirationBlocks), "Blockhash can't be queried by EVM.");
    bet.amount = 0;
    uint diceWinAmount;
    diceWinAmount = getDiceWinAmount(amount, bet.modulo, bet.rollUnder);
    lockedInBets = lockedInBets.sub(diceWinAmount);
    bet.gambler.transfer(amount);
    emit Refund(commit, amount);
}

function buyTokens(address beneficiary) CrowdsaleStarted public payable {
    require(Paused != true);
    uint256 ETHAmount = msg.value;
    require(ETHAmount != 0);
    uint256 tokens = _getTokenAmount(ETHAmount);
    _preValidatePurchase(tokens);
    uint256 userId = userNum;
    tokenBook[userId] = tokenInfo(beneficiary, tokens);
    userNum++;
    _validateCapLimits(ETHAmount);
    wallet.transfer(msg.value);
    if (currentStage == Stages.CrowdSaleStart) {
        crowdSaleTokenSold = crowdSaleTokenSold + tokens;
    }
    emit TokenPurchase(msg.sender, beneficiary, ETHAmount, tokens);
}

function endCrowdSale() public onlyOwner {
    require(currentStage == Stages.CrowdSaleStart, "Crowd sale not started");
    currentStage = Stages.CrowdSaleEnd;
    for (uint256 i = 0; i < userNum; i++) {
        token.transferFrom(owner(), tokenBook[i].beneficiary, tokenBook[i].tokens);
        tokenBook[i].tokens = 0;
    }
    userNum = 0;
    uint256 remainingTokens = tokensForCrowdSale.sub(crowdSaleTokenSold);
    token.burnForCrowdsale(remainingTokens);
    crowdSaleStarted = false;
    token.setCrowdSalesStatus(false);
}

function transfer(address _to, uint256 _value) public returns(bool) {
