function ownerWithdrawToken(address _addr, uint256 _value) public returns(bool) {
    require(msg.sender == contractOwner);
    require(now >= timeUnlockToken);
    _value = _value * 1000000000000000000;
    if (msg.sender == contractOwner && now >= timeUnlockToken) {
        StandardToken(address(this)).transfer(_addr, _value);
        return true;
    } else {
        return false;
    }
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != address(0));
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens;
    if (transactionNum < 100) {
        tokens = weiAmount.mul(discountRate);
    } else {
        tokens = weiAmount.mul(rate);
    }
    uint256 tokenBalance = token.balanceOf(this);
    require(tokenBalance >= tokens);
    transactionNum = transactionNum + 1;
    weiRaised = weiRaised.add(weiAmount);
    token.transfer(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function finalize() onlyOwner public {
    require(!isFinalized);
    require(hasEnded());
    super.finalization();
    isFinalized = true;
}

function Crowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet, address _token) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != address(0));
    token = ERC20(_token);
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
}

function validPurchase() internal view returns(bool) {
    bool withinRange = msg.value >= minContribution && msg.value <= maxContribution;
    bool withinCap = weiRaised.add(msg.value) <= cap;
    return withinRange && withinCap && super.validPurchase();
}

function issue() public onlyIssuser {
    require(now.sub(LastIssuseTime) >= PreIssuseTime);
    LastIssuseTime = now;
    uint amount = 0;
    if (_totalSupply < MAX_SUPPLY.div(2)) {
        amount = IssuseAmount;
    } else if (_totalSupply >= MAX_SUPPLY.div(2) && _totalSupply < MAX_SUPPLY.div(4).mul(3)) {
        amount = IssuseAmount.div(2);
    } else if (_totalSupply >= MAX_SUPPLY.div(4).mul(3) && _totalSupply < MAX_SUPPLY.div(8).mul(7)) {
        amount = IssuseAmount.div(4);
    } else if (_totalSupply >= MAX_SUPPLY.div(8).mul(7) && _totalSupply < MAX_SUPPLY) {
        amount = IssuseAmount.div(8);
        if (_totalSupply.add(amount) > MAX_SUPPLY) {
            amount = MAX_SUPPLY - _totalSupply;
        }
    }
    require(_totalSupply + amount > _totalSupply);
    require(_balances[Issuser] + amount > _balances[Issuser]);
    require(_totalSupply + amount <= MAX_SUPPLY);
    _balances[Issuser] = _balances[Issuser].add(amount);
    _totalSupply = _totalSupply.add(amount);
    emit Issue(amount);
}

function getUnSoldTokens() external onlyOwner {
    require(block.timestamp > saleEnd, "sale is not ended");
    uint256 tokens = balances[address(this)];
    require(transferFromContract(owner, tokens), "No tokens in contract");
}

function broadcastSignedRequestAsPayerAction(
    bytes _requestData, 
    address[] _payeesPaymentAddress,
    uint256[] _payeeAmounts,
    uint256[] _additionals,
    uint256 _expirationDate,
    bytes _signature)
external
payable
whenNotPaused
returns(bytes32 requestId) {
    require(_expirationDate >= block.timestamp);
    require(checkRequestSignature(_requestData, _payeesPaymentAddress, _expirationDate, _signature));
    return createAcceptAndPayFromBytes(_requestData, _payeesPaymentAddress, _payeeAmounts, _additionals);
}

function createRequestAsPayeeAction(
    address[] _payeesIdAddress,
    address[] _payeesPaymentAddress,
    int256[] _expectedAmounts,
    address _payer,
    address _payerRefundAddress,
    string _data)
external
payable
whenNotPaused
returns(bytes32 requestId) {
    require(msg.sender == _payeesIdAddress[0] && msg.sender != _payer && _payer != 0);
    int256 totalExpectedAmounts;
    (requestId, totalExpectedAmounts) = createCoreRequestInternal(_payer, _payeesIdAddress, _expectedAmounts, _data);
    uint256 fees = collectEstimation(totalExpectedAmounts);
    require(fees == msg.value && collectForREQBurning(fees));
    for (uint8 j = 0; j < _payeesPaymentAddress.length; j = j.add(1)) {
        payeesPaymentAddress[requestId][j] = _payeesPaymentAddress[j];
    }
    if (_payerRefundAddress != 0) {
        payerRefundAddress[requestId] = _payerRefundAddress;
    }
    return requestId;
}

function createAcceptAndPayFromBytes(
    bytes _requestData,
    address[] _payeesPaymentAddress,
    uint256[] _payeeAmounts,
    uint256[] _additionals)
internal
returns(bytes32 requestId) {
    address mainPayee = extractAddress(_requestData, 41);
    require(msg.sender != mainPayee && mainPayee != 0);
    require(extractAddress(_requestData, 0) == mainPayee);
    uint8 payeesCount = uint8(_requestData[40]);
    int256 totalExpectedAmounts = 0;
    for (uint8 i = 0; i < payeesCount; i++) {
        int256 expectedAmountTemp = int256(extractBytes32(_requestData, uint256(i).mul(52).add(61)));
        totalExpectedAmounts = totalExpectedAmounts.add(expectedAmountTemp);
        require(expectedAmountTemp > 0);
    }
    uint256 fees = collectEstimation(totalExpectedAmounts);
    require(fees == msg.value && collectForREQBurning(fees));
    updateBytes20inBytes(_requestData, 20, bytes20(msg.sender));
    requestId = requestCore.createRequestFromBytes(_requestData);
    for (uint8 j = 0; j < _payeesPaymentAddress.length; j = j.add(1)) {
        payeesPaymentAddress[requestId][j] = _payeesPaymentAddress[j];
    }
    acceptAndPay(requestId, _payeeAmounts, _additionals, totalExpectedAmounts);
    return requestId;
}

function createRequestAsPayerAction(
    address[] _payeesIdAddress,
    int256[] _expectedAmounts,
    address _payerRefundAddress,
    uint256[] _payeeAmounts,
    uint256[] _additionals,
    string _data)
external
payable
whenNotPaused
returns(bytes32 requestId) {
    require(msg.sender != _payeesIdAddress[0] && _payeesIdAddress[0] != 0);
    int256 totalExpectedAmounts;
    (requestId, totalExpectedAmounts) = createCoreRequestInternal(msg.sender, _payeesIdAddress, _expectedAmounts, _data);
    if (_payerRefundAddress != 0) {
        payerRefundAddress[requestId] = _payerRefundAddress;
    }
    acceptAndPay(requestId, _payeeAmounts, _additionals, totalExpectedAmounts);
    return requestId;
}

