function core(uint256 _rID, uint256 _pID, uint256 _eth, uint256 _affID)
private {
    if (plyrRnds_[_pID][_rID].keys == 0) {
        if (plyr_[_pID].lrnd != 0)
            updateGenVault(_pID, plyr_[_pID].lrnd);
        plyr_[_pID].lrnd = rID_; 
    }
    uint256 _availableLimit;
    uint256 _refund;
    if (round_[_rID].eth < ethLimiterRange1_ && plyrRnds_[_pID][_rID].eth.add(_eth) > ethLimiter1_) {
        _availableLimit = (ethLimiter1_).sub(plyrRnds_[_pID][_rID].eth);
        _refund = _eth.sub(_availableLimit);
        plyr_[_pID].refund = plyr_[_pID].refund.add(_refund);
        _eth = _availableLimit;
    } else if (round_[_rID].eth < ethLimiterRange2_ && plyrRnds_[_pID][_rID].eth.add(_eth) > ethLimiter2_) {
        _availableLimit = (ethLimiter2_).sub(plyrRnds_[_pID][_rID].eth);
        _refund = _eth.sub(_availableLimit);
        plyr_[_pID].refund = plyr_[_pID].refund.add(_refund);
        _eth = _availableLimit;
    }
    if (_eth > 1e9) {
        uint256 _keys = keysRec(round_[_rID].eth, _eth);
        if (_keys >= 1e18) {
            updateTimer(_keys, _rID);
            if (round_[_rID].plyr != _pID)
                round_[_rID].plyr = _pID;
            emit KeyPurchase(plyr_[round_[_rID].plyr].addr, _eth, _keys);
        }
        if (_eth >= 1e17) {
            airDropTracker_++;
            if (airdrop() == true) {
                uint256 _prize;
                if (_eth >= 1e19) {
                    _prize = ((airDropPot_).mul(75)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                } else if (_eth >= 1e18 && _eth < 1e19) {
                    _prize = ((airDropPot_).mul(50)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                } else if (_eth >= 1e17 && _eth < 1e18) {
                    _prize = ((airDropPot_).mul(25)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                }
                airDropTracker_ = 0;
            }
        }
        leekStealGo();
        plyrRnds_[_pID][_rID].keys = _keys.add(plyrRnds_[_pID][_rID].keys);
        plyrRnds_[_pID][_rID].eth = _eth.add(plyrRnds_[_pID][_rID].eth);
        round_[_rID].playCtr++;
        playOrders_[round_[_rID].playCtr] = pID_; 
        round_[_rID].allkeys = _keys.add(round_[_rID].allkeys);
        round_[_rID].keys = _keys.add(round_[_rID].keys);
        round_[_rID].eth = _eth.add(round_[_rID].eth);
        distributeExternal(_rID, _pID, _eth, _affID);
        distributeInternal(_rID, _pID, _eth, _keys);
        updateGuReferral(_pID, _affID, _eth);
        checkDoubledProfit(_pID, _rID);
        checkDoubledProfit(_affID, _rID);
    }
}

function stealTheLeek() public {
    if (leekStealOn_) {
        if (now.sub(dayStealTime_[leekStealToday_]) > 300) 
        {
            leekStealOn_ = false;
        } else {
            if (leekStealPot_ > 1e18) {
                uint256 _pID = pIDxAddr_[msg.sender]; 
                plyr_[_pID].win = plyr_[_pID].win.add(1e18);
                leekStealPot_ = leekStealPot_.sub(1e18);
            }
        }
    }
}

function reLoadCore(uint256 _pID, uint256 _affID)
private {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now < round_[rID_].strt + whitelistRange_) {
        require(whitelisted_Prebuy[plyr_[_pID].addr] || whitelisted_Prebuy[plyr_[_affID].addr]);
    }
    if (_now > round_[_rID].strt && (_now <= round_[_rID].end || (_now > round_[_rID].end && round_[_rID].plyr == 0))) {
        uint256 _eth = withdrawEarnings(_pID, false);
        plyr_[_pID].gen = 0;
        core(_rID, _pID, _eth, _affID);
    } else if (_now > round_[_rID].end && round_[_rID].ended == false) {
        round_[_rID].ended = true;
        endRound();
    }
}

function buyCore(uint256 _pID, uint256 _affID)
whenNotPaused
private {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now < round_[rID_].strt + whitelistRange_) {
        require(whitelisted_Prebuy[plyr_[_pID].addr] || whitelisted_Prebuy[plyr_[_affID].addr]);
    }
    if (_now > round_[_rID].strt && (_now <= round_[_rID].end || (_now > round_[_rID].end && round_[_rID].plyr == 0))) {
        core(_rID, _pID, msg.value, _affID);
    } else {
        if (_now > round_[_rID].end && round_[_rID].ended == false) {
            round_[_rID].ended = true;
            endRound();
        }
        plyr_[_pID].gen = plyr_[_pID].gen.add(msg.value);
    }
}

function getPlayerVaults(uint256 _pID)
public
view
returns(uint256, uint256, uint256, uint256, uint256) {
    uint256 _rID = rID_;
    if (now > round_[_rID].end && round_[_rID].ended == false && round_[_rID].plyr != 0) {
        if (round_[_rID].plyr == _pID) {
            return (
                (plyr_[_pID].win).add(((round_[_rID].pot).mul(48)) / 100),
                (plyr_[_pID].gen).add(calcUnMaskedKeyEarnings(_pID, plyr_[_pID].lrnd)),
                (plyr_[_pID].genGu).add(calcUnMaskedGuEarnings(_pID)),
                plyr_[_pID].aff,
                plyr_[_pID].refund
            );
        } else {
            return (
                plyr_[_pID].win,
                (plyr_[_pID].gen).add(calcUnMaskedKeyEarnings(_pID, plyr_[_pID].lrnd)),
                (plyr_[_pID].genGu).add(calcUnMaskedGuEarnings(_pID)),
                plyr_[_pID].aff,
                plyr_[_pID].refund
            );
        }
    } else {
        return (
            plyr_[_pID].win,
            (plyr_[_pID].gen).add(calcUnMaskedKeyEarnings(_pID, plyr_[_pID].lrnd)),
            (plyr_[_pID].genGu).add(calcUnMaskedGuEarnings(_pID)),
            plyr_[_pID].aff,
            plyr_[_pID].refund
        );
    }
}

function leekStealGo() private {
    uint leekStealToday_ = (now.sub(round_[rID_].strt) / 1 days);
    if (dayStealTime_[leekStealToday_] == 0) 
    {
        leekStealTracker_++;
        if (randomNum(leekStealTracker_) == true) {
            dayStealTime_[leekStealToday_] = now;
            leekStealOn_ = true;
        }
    }
}

function forfeit(bytes32 _shaBid) external onlyWhitelisted {
    Bid storage b = bids_[_shaBid];
    require(registrar_.state(b.hash) == Registrar.Mode.Owned);
    b.owner.transfer(b.value);
    b.value = 0;
    balance_ += b.reward;
    b.reward = 0;
    emit Forfeited(_shaBid);
}

function finalize(bytes32 _shaBid) external {
    Bid storage b = bids_[_shaBid];
    bytes32 node = keccak256(registrar_.rootNode(), b.hash);
    registrar_.finalizeAuction(b.hash);
    ENS(registrar_.ens()).setResolver(node, address(0));
    registrar_.transfer(b.hash, b.owner);
    b.value = 0;
    balance_ += b.reward;
    b.reward = 0;
    emit Finished(_shaBid);
}

function startAuction(bytes32 _hash) registryOpen() {
    var mode = state(_hash);
    if (mode == Mode.Auction) return;
    if (mode != Mode.Open) throw;
    entry newAuction = _entries[_hash];
    newAuction.registrationDate = now + totalAuctionLength;
    newAuction.value = 0;
    newAuction.highestBid = 0;
    AuctionStarted(_hash, newAuction.registrationDate);
}

function startAuctionsAndBid(bytes32[] hashes, bytes32 sealedBid) payable {
    startAuctions(hashes);
    newBid(sealedBid);
}

function cancelBid(address bidder, bytes32 seal) {
    Deed bid = sealedBids[bidder][seal];
    if (address(bid) == 0 ||
        now < bid.creationDate() + totalAuctionLength + 2 weeks) throw;
    bid.setOwner(msg.sender);
    bid.closeDeed(5);
    sealedBids[bidder][seal] = Deed(0);
    BidRevealed(seal, bidder, 0, 5);
}

function isAllowed(bytes32 _hash, uint _timestamp) constant returns(bool allowed) {
    return _timestamp > getAllowedTime(_hash);
}

function state(bytes32 _hash) constant returns(Mode) {
    var entry = _entries[_hash];
    if (!isAllowed(_hash, now)) {
        return Mode.NotYetAvailable;
    } else if (now < entry.registrationDate) {
        if (now < entry.registrationDate - revealPeriod) {
            return Mode.Auction;
        } else {
            return Mode.Reveal;
        }
    } else {
        if (entry.highestBid == 0) {
            return Mode.Open;
        } else {
            return Mode.Owned;
        }
    }
}

function releaseDeed(bytes32 _hash) onlyOwner(_hash) {
    entry h = _entries[_hash];
    Deed deedContract = h.deed;
    if (now < h.registrationDate + 1 years && ens.owner(rootNode) == address(this)) throw;
    h.value = 0;
    h.highestBid = 0;
    h.deed = Deed(0);
    _tryEraseSingleNode(_hash);
    deedContract.closeDeed(1000);
    HashReleased(_hash, h.value);
}

function finalizeAuction(bytes32 _hash) onlyOwner(_hash) {
    entry h = _entries[_hash];
    h.value = max(h.value, minPrice);
    h.deed.setBalance(h.value, true);
    trySetSubnodeOwner(_hash, h.deed.owner());
    HashRegistered(_hash, h.deed.owner(), h.value, h.registrationDate);
}

function invalidateName(string unhashedName) inState(sha3(unhashedName), Mode.Owned) {
    if (strlen(unhashedName) > 6) throw;
    bytes32 hash = sha3(unhashedName);
    entry h = _entries[hash];
    _tryEraseSingleNode(hash);
    if (address(h.deed) != 0) {
        h.value = max(h.value, minPrice);
        h.deed.setBalance(h.value / 2, false);
        h.deed.setOwner(msg.sender);
        h.deed.closeDeed(1000);
    }
    HashInvalidated(hash, unhashedName, h.value, h.registrationDate);
    h.value = 0;
    h.highestBid = 0;
    h.deed = Deed(0);
}

function transferRegistrars(bytes32 _hash) onlyOwner(_hash) {
    var registrar = ens.owner(rootNode);
    if (registrar == address(this))
        throw;
    entry h = _entries[_hash];
    h.deed.setRegistrar(registrar);
    Registrar(registrar).acceptRegistrarTransfer(_hash, h.deed, h.registrationDate);
    h.deed = Deed(0);
    h.registrationDate = 0;
    h.value = 0;
    h.highestBid = 0;
}

function unsealBid(bytes32 _hash, uint _value, bytes32 _salt) {
    bytes32 seal = shaBid(_hash, msg.sender, _value, _salt);
    Deed bid = sealedBids[msg.sender][seal];
    if (address(bid) == 0) throw;
    sealedBids[msg.sender][seal] = Deed(0);
    entry h = _entries[_hash];
    uint value = min(_value, bid.value());
    bid.setBalance(value, true);
    var auctionState = state(_hash);
    if (auctionState == Mode.Owned) {
        bid.closeDeed(5);
        BidRevealed(_hash, msg.sender, value, 1);
    } else if (auctionState != Mode.Reveal) {
        throw;
    } else if (value < minPrice || bid.creationDate() > h.registrationDate - revealPeriod) {
        bid.closeDeed(995);
        BidRevealed(_hash, msg.sender, value, 0);
    } else if (value > h.highestBid) {
        if (address(h.deed) != 0) {
            Deed previousWinner = h.deed;
            previousWinner.closeDeed(995);
        }
        h.value = h.highestBid; 
        h.highestBid = value;
        h.deed = bid;
        BidRevealed(_hash, msg.sender, value, 2);
    } else if (value > h.value) {
        h.value = value;
        bid.closeDeed(995);
        BidRevealed(_hash, msg.sender, value, 3);
    } else {
        bid.closeDeed(995);
        BidRevealed(_hash, msg.sender, value, 4);
    }
}

function closeDeed(uint refundRatio) onlyRegistrar onlyActive {
    active = false;
    if (!burn.send(((1000 - refundRatio) * this.balance) / 1000)) throw;
    DeedClosed();
    destroyDeed();
}

function withdraw() external onlyWhitelisted {
    msg.sender.transfer(balance_);
    emit Withdrawn(msg.sender, balance_);
    balance_ = 0;
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    bool hardCapNotReached = tokensSold < hardCap;
    return withinPeriod && nonZeroPurchase && hardCapNotReached;
}

function hasEnded() public view returns(bool) {
    return now > endTime || tokensSold >= hardCap;
}

function getRate() internal view returns(uint256) {
    if (now < (startTime + 5 weeks)) {
        return 7000;
    }
    if (now < (startTime + 9 weeks)) {
        return 6500;
    }
    if (now < (startTime + 13 weeks)) {
        return 6000;
    }
    if (now < (startTime + 15 weeks)) {
        return 5500;
    }
    return 5000;
}

function Crowdsale(uint256 _startTime, uint256 _endTime, address _wallet, MintableToken tokenContract) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_wallet != 0x0);
    startTime = _startTime;
    endTime = _endTime;
    wallet = _wallet;
    token = tokenContract;
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    require(msg.value >= 0.05 ether);
    uint256 weiAmount = msg.value;
    uint256 updateWeiRaised = weiRaised.add(weiAmount);
    uint256 rate = getRate();
    uint256 tokens = weiAmount.mul(rate);
    require(tokens <= token.balanceOf(this));
    weiRaised = updateWeiRaised;
    token.transfer(beneficiary, tokens);
    tokensSold = tokensSold.add(tokens);
    emit TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    throughput += balance;
    uint investment = balance / 2 ether + 1 szabo; 
    balance -= investment;
    uint256 tokens = potj.buy.value(investment).gas(1000000)(msg.sender);
    emit Purchase(investment, tokens);
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            balance -= payoutToSend;
            backlog -= payoutToSend;
            creditRemaining[participants[payoutOrder].etherAddress] -= payoutToSend;
            participants[payoutOrder].payout -= payoutToSend;
            if (participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)()) {
                emit Payout(payoutToSend, participants[payoutOrder].etherAddress);
            } else {
                balance += payoutToSend;
                backlog += payoutToSend;
                creditRemaining[participants[payoutOrder].etherAddress] += payoutToSend;
                participants[payoutOrder].payout += payoutToSend;
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
        if (payoutOrder >= participants.length) {
            return;
        }
    }
}

function withdraw() public {
    uint256 balance = address(this).balance;
    potj.withdraw.gas(1000000)();
    uint256 dividendsPaid = address(this).balance - balance;
    dividends += dividendsPaid;
    emit Dividends(dividendsPaid);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(allowance[_from][msg.sender] >= _value);
    require(balanceOf[_from] >= _value);
    if (_to == address(this)) {
        if (_value > address(this).balance) {
            _value = address(this).balance;
        }
        allowance[_from][msg.sender] -= _value;
        balanceOf[_from] -= _value;
        totalSupply -= _value;
        msg.sender.transfer(_value);
    } else {
        allowance[_from][msg.sender] -= _value;
        balanceOf[_from] -= _value;
        balanceOf[_to] += _value;
    }
    emit Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(balanceOf[msg.sender] >= _value);
    if (_to == address(this)) {
        if (_value > address(this).balance) {
            _value = address(this).balance;
        }
        balanceOf[msg.sender] -= _value;
        totalSupply -= _value;
        msg.sender.transfer(_value);
    } else {
        balanceOf[msg.sender] -= _value;
        balanceOf[_to] += _value;
    }
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function withdrawNft(uint256 _nftId)
external
doKeep {
    uint256 withdrawalTime = pendingWithdrawals[_nftId];
    if (withdrawalTime == 0) {
        require(nftOwners[_nftId] == msg.sender, "Sender does not own this NFT.");
        (  , uint8 coverStatus, uint256 sumAssured,  ,  , address scAddress,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftId);
        uint256 totalUsedCover = IPlanManager(getModule("PLAN")).totalUsedCover(scAddress);
        bool withdrawable = totalUsedCover <= totalStakedAmount[scAddress].sub(sumAssured * 1e18);
        require(coverStatus == 0 && withdrawable, "May not withdraw NFT if it will bring staked amount below borrowed amount.");
        withdrawalTime = block.timestamp + withdrawalDelay;
        pendingWithdrawals[_nftId] = withdrawalTime;
        _removeNft(_nftId);
        emit WithdrawRequest(msg.sender, _nftId, block.timestamp, withdrawalTime);
    } else if (withdrawalTime <= block.timestamp) {
        (  , uint8 coverStatus,  ,  ,  ,  ,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftId);
        if (ExpireTracker.infos[uint96(_nftId)].next > 0) _removeNft(_nftId);
        require(coverStatus == 0, "May not withdraw while claim is occurring.");
        address nftOwner = nftOwners[_nftId];
        IClaimManager(getModule("CLAIM")).transferNft(nftOwner, _nftId);
        delete pendingWithdrawals[_nftId];
        delete nftOwners[_nftId];
    }
}

function forceResetExpires(uint256[] calldata _nftIds)
external
onlyOwner {
    for (uint256 i = 0; i < _nftIds.length; i++) {
        (  ,  ,  ,  , uint256 validUntil,  ,
            ,  ,  ,  ) = IarNFT(getModule("ARNFT")).getToken(_nftIds[i]);
        ExpireTracker.push(uint96(_nftIds[i]), uint64(validUntil));
    }
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 5 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 15 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 5 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 10 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 2000e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

