function userVoteFor(address _standFor, uint256 _index, uint256 _whichTeam, uint256 _amount) internal {
    Combat storage c = combats[_index];
    uint256 voteVal = _amount.sub(_amount.mul(voteCut).div(100));
    if (voteVal < _amount) {
        owner.transfer(_amount.sub(voteVal));
    }
    if (_whichTeam == c.teamAID) {
        c.poolOfTeamA = c.poolOfTeamA.add(voteVal);
        if (forTeamAInCombat[_index][_standFor] == 0) {
            usersForTeamAInCombat[_index].push(_standFor);
        }
        forTeamAInCombat[_index][_standFor] = forTeamAInCombat[_index][_standFor].add(voteVal);
    } else {
        c.poolOfTeamB = c.poolOfTeamB.add(voteVal);
        if (forTeamBInCombat[_index][_standFor] == 0) {
            usersForTeamBInCombat[_index].push(_standFor);
        }
        forTeamBInCombat[_index][_standFor] = forTeamAInCombat[_index][_standFor].add(voteVal);
    }
    emit VoteSuccessful(_standFor, _index, _whichTeam, _amount);
}

function queue(uint256 proposalId) public {
    require(
        state(proposalId) == ProposalState.Succeeded,
        'GovernorAlpha::queue: proposal can only be queued if it is succeeded'
    );
    Proposal storage proposal = proposals[proposalId];
    uint256 eta = add256(block.timestamp, timelock.delay());
    for (uint256 i = 0; i < proposal.targets.length; i++) {
        _queueOrRevert(
            proposal.targets[i],
            proposal.values[i],
            proposal.signatures[i],
            proposal.calldatas[i],
            eta
        );
    }
    proposal.eta = eta;
    treasury.sendReward(queueReward, msg.sender);
    emit ProposalQueued(proposalId, eta);
}

function _queueOrRevert(
    address target,
    uint256 value,
    string memory signature,
    bytes memory data,
    uint256 eta
) internal {
    require(
        !timelock.queuedTransactions(
            keccak256(abi.encode(target, value, signature, data, eta))
        ),
        'GovernorAlpha::_queueOrRevert: proposal action already queued at eta'
    );
    timelock.queueTransaction(target, value, signature, data, eta);
}

function propose(
    address[] memory targets,
    uint256[] memory values,
    string[] memory signatures,
    bytes[] memory calldatas,
    string memory description
) public returns(uint256) {
    require(
        block.number > proposeDelay,
        'GovernorAlpha::propose: Not allowed to propose yet'
    );
    require(
        (add256(pheezez.getPriorVotes(msg.sender, sub256(block.number, 1)),
            poolPHZT.getPriorVotesinPool(msg.sender, sub256(block.number, 1)))) >
        proposalThreshold(),
        'GovernorAlpha::propose: proposer votes below proposal threshold'
    );
    require(
        targets.length == values.length &&
        targets.length == signatures.length &&
        targets.length == calldatas.length,
        'GovernorAlpha::propose: proposal function information mismatch'
    );
    require(
        targets.length != 0,
        'GovernorAlpha::propose: must provide actions'
    );
    require(
        targets.length <= proposalMaxOperations(),
        'GovernorAlpha::propose: too many actions'
    );
    uint256 latestProposalId = latestProposalIds[msg.sender];
    if (latestProposalId != 0) {
        ProposalState proposersLatestProposalState = state(
            latestProposalId
        );
        require(
            proposersLatestProposalState != ProposalState.Active,
            'GovernorAlpha::propose: one live proposal per proposer, found an already active proposal'
        );
        require(
            proposersLatestProposalState != ProposalState.Pending,
            'GovernorAlpha::propose: one live proposal per proposer, found an already pending proposal'
        );
    }
    uint256 startBlock = add256(block.number, votingDelay());
    uint256 endBlock = add256(startBlock, votingPeriod());
    uint256 quorum = quorumVotes();
    proposalCount++;
    Proposal memory newProposal = Proposal({
        id: proposalCount,
        proposer: msg.sender,
        eta: 0,
        targets: targets,
        values: values,
        signatures: signatures,
        calldatas: calldatas,
        startBlock: startBlock,
        endBlock: endBlock,
        forVotes: 0,
        againstVotes: 0,
        canceled: false,
        executed: false,
        quorumatPropose: quorum 
    });
    proposals[newProposal.id] = newProposal;
    latestProposalIds[newProposal.proposer] = newProposal.id;
    emit ProposalCreated(
        newProposal.id,
        msg.sender,
        targets,
        values,
        signatures,
        calldatas,
        startBlock,
        endBlock,
        description
    );
    treasury.sendReward(proposeReward, msg.sender);
    return newProposal.id;
}

function state(uint256 proposalId) public view returns(ProposalState) {
    require(
        proposalCount >= proposalId && proposalId > 0,
        'GovernorAlpha::state: invalid proposal id'
    );
    Proposal storage proposal = proposals[proposalId];
    if (proposal.canceled) {
        return ProposalState.Canceled;
    } else if (block.number <= proposal.startBlock) {
        return ProposalState.Pending;
    } else if (block.number <= proposal.endBlock) {
        return ProposalState.Active;
    } else if (
        proposal.forVotes <= proposal.againstVotes ||
        proposal.forVotes < proposal.quorumatPropose
    ) {
        return ProposalState.Defeated;
    } else if (proposal.eta == 0) {
        return ProposalState.Succeeded;
    } else if (proposal.executed) {
        return ProposalState.Executed;
    } else if (
        block.timestamp >= add256(proposal.eta, timelock.GRACE_PERIOD())
    ) {
        return ProposalState.Expired;
    } else {
        return ProposalState.Queued;
    }
}

function _castVote(
    address voter,
    uint256 proposalId,
    bool support
) internal {
    require(
        state(proposalId) == ProposalState.Active,
        'GovernorAlpha::_castVote: voting is closed'
    );
    Proposal storage proposal = proposals[proposalId];
    Receipt storage receipt = proposal.receipts[voter];
    require(
        receipt.hasVoted == false,
        'GovernorAlpha::_castVote: voter already voted'
    );
    uint256 votes = add256(pheezez.getPriorVotes(msg.sender, proposal.startBlock),
        poolPHZT.getPriorVotesinPool(msg.sender, proposal.startBlock));
    uint256 voteLimiter = SafeMath.div(
        SafeMath.mul(pheezez.votesAvailable(), vRatio),
        100
    );
    if (votes > voteLimiter) {
        votes = voteLimiter;
    }
    if (support) {
        proposal.forVotes = add256(proposal.forVotes, votes);
    } else {
        proposal.againstVotes = add256(proposal.againstVotes, votes);
    }
    receipt.hasVoted = true;
    receipt.support = support;
    receipt.votes = votes;
    treasury.sendReward(voteReward, msg.sender);
    emit VoteCast(voter, proposalId, support, votes);
}

function cancel(uint256 proposalId) public {
    ProposalState state = state(proposalId);
    require(
        state != ProposalState.Executed,
        'GovernorAlpha::cancel: cannot cancel executed proposal'
    );
    Proposal storage proposal = proposals[proposalId];
    require(
        msg.sender == guardian || proposal.proposer == msg.sender,
        'GovernorAlpha::cancel: Only the creator can cancel a proposal'
    ); 
    proposal.canceled = true;
    for (uint256 i = 0; i < proposal.targets.length; i++) {
        timelock.cancelTransaction(
            proposal.targets[i],
            proposal.values[i],
            proposal.signatures[i],
            proposal.calldatas[i],
            proposal.eta
        );
    }
    emit ProposalCanceled(proposalId);
}

function buyTokens(address _buyer) public payable {
    require((currentPhase == Phase.PresaleRunning) || (currentPhase == Phase.ICORunning));
    require(_buyer != address(0));
    require(msg.value > 0);
    require(validPurchase());
    uint tokensWouldAddTo = 0;
    uint weiWouldAddTo = 0;
    uint256 weiAmount = msg.value;
    uint newTokens = msg.value.mul(RATE);
    weiWouldAddTo = weiRaised.add(weiAmount);
    require(weiWouldAddTo <= TOKEN_SALE_LIMIT);
    newTokens = addBonusTokens(token.totalSupply(), newTokens);
    tokensWouldAddTo = newTokens.add(token.totalSupply());
    require(tokensWouldAddTo <= TOKENS_FOR_SALE);
    token.mint(_buyer, newTokens);
    TokenPurchase(msg.sender, _buyer, weiAmount, newTokens);
    weiRaised = weiWouldAddTo;
    forwardFunds();
    if (weiRaised == TOKENS_FOR_SALE) {
        weiCapReached = true;
    }
}

function validPurchase() internal view returns(bool) {
    bool withinPeriod = now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    bool isRunning = ((currentPhase == Phase.ICORunning) || (currentPhase == Phase.PresaleRunning));
    return withinPeriod && nonZeroPurchase && isRunning;
}

