}

function getDragonPriceNo(uint eth) public view returns(uint) {
    uint256 d = userHatchRate[msg.sender];
    if (d == 0)
        d = SafeMath.add(EGGS_TO_HATCH_1Dragon, getEggsToHatchDragon());
    return getDragonPrice(d, eth);
}

function buyDrangon() public payable {
    require(initialized);
    require(userHatchRate[msg.sender] != 0);
    uint dragonPrice = getDragonPrice(userHatchRate[msg.sender], address(this).balance);
    uint dragonAmount = SafeMath.div(msg.value, dragonPrice);
    require(dragonAmount > 0);
    ceoEtherBalance += calculatePercentage(msg.value, 20);
    premiumDragons[msg.sender] += dragonAmount;
}

function purchase(uint256 _tokenId, uint256 newSellingPrice) public payable whenNotPaused {
    address oldOwner = cryptonIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    bool isAlreadyProtected = cryptonIndexToProtected[_tokenId];
    uint256 sellingPrice = cryptonIndexToPrice[_tokenId];
    uint256 markup = cryptons[_tokenId].markup;
    if (cryptons[_tokenId].category != PROMO) {
        require(markup > 0); 
    }
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice); 
    if (newSellingPrice > 0) { 
        uint256 purchasePrice = sellingPrice; 
        if (!cryptonIndexToProtected[_tokenId]) { 
            purchasePrice = sellingPrice + markup; 
        }
        require(msg.value >= purchasePrice);
        cryptonIndexToPrice[_tokenId] = newSellingPrice; 
        cryptonIndexToProtected[_tokenId] = true; 
        emit CryptonIsProtected(_tokenId); 
    } else {
        if (
            (oldOwner == address(this)) && 
            (cryptons[_tokenId].category == XPROMO) 
        ) {
            cryptonIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, XPROMO_MULTIPLIER), NET_PRICE_PERCENT);
        } else {
            if (sellingPrice < FIRST_STEP_LIMIT) {
                cryptonIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, FIRST_STEP_MULTIPLIER), NET_PRICE_PERCENT);
            } else {
                cryptonIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, SECOND_STEP_MULTIPLIER), NET_PRICE_PERCENT);
            }
        }
    }
    _transfer(oldOwner, newOwner, _tokenId);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, NET_PRICE_PERCENT), 100));
    string storage cname = cryptons[_tokenId].name;
    bool isReservedToken = (cryptons[_tokenId].category == RESERVED);
    if (isReservedToken && isAlreadyProtected) {
        oldOwner.transfer(payment); 
        emit PaymentTransferredToPreviousOwner(_tokenId, sellingPrice, cryptonIndexToPrice[_tokenId], oldOwner, newOwner, cname);
        emit TokenSold(_tokenId, sellingPrice, cryptonIndexToPrice[_tokenId], oldOwner, newOwner, cname);
        return;
    }
    if ((oldOwner != address(this)) && !isReservedToken) 
    {
        oldOwner.transfer(payment); 
        emit PaymentTransferredToPreviousOwner(_tokenId, sellingPrice, cryptonIndexToPrice[_tokenId], oldOwner, newOwner, cname);
    }
    emit TokenSold(_tokenId, sellingPrice, cryptonIndexToPrice[_tokenId], oldOwner, newOwner, cname);
}

function unstake(uint256 _amount) public {
    uint256 userBalance = stakes[msg.sender].yeldBalance;
    require(userBalance > 0 && _amount > 0, "You can't unstake less than zero");
    require(_amount <= userBalance, "You can't withdraw more than your balance");
    stakes[msg.sender] = Stake(now, stakes[msg.sender].yeldBalance.sub(_amount));
    totalStaked = totalStaked.sub(_amount);
    yeld.transfer(msg.sender, _amount);
}

function finish(uint256 _count) public onlyOwner finishOrHardcap overSoftcap returns(bool) {
    require(_count > 0);
    require(distributionDate > 0 && distributionDate <= now);
    if (finishCurrentLimit == 0) {
        finishCurrentLimit = bountyLimit.add(teamLimit.add(advisersLimit));
    }
    uint256 totalCnt = adviser.length.add(bounty.length);
    if (finishLastCount < adviser.length) {
        for (uint256 i = finishLastCount; i <= adviser.length - 1; i++) {
            finishCurrentLimit = finishCurrentLimit.sub(adviserAmount[adviser[i]]);
            bgxTokenInterface.distribute(adviser[i], adviserAmount[adviser[i]]);
            finishLastCount++;
            _count--;
            if (_count <= 0) {
                return true;
            }
        }
    }
    if (finishLastCount < totalCnt) {
        for (i = finishLastCount.sub(adviser.length); i <= bounty.length - 1; i++) {
            finishCurrentLimit = finishCurrentLimit.sub(bountyAmount[bounty[i]]);
            bgxTokenInterface.distribute(bounty[i], bountyAmount[bounty[i]]);
            finishLastCount++;
            _count--;
            if (_count <= 0) {
                return true;
            }
        }
    }
    if (finishLastCount >= totalCnt && finishLastCount < totalCnt.add(team.length)) {
        for (i = finishLastCount.sub(totalCnt); i <= team.length - 1; i++) {
            finishCurrentLimit = finishCurrentLimit.sub(teamAmount[team[i]]);
            bgxTokenInterface.distribute(team[i], teamAmount[team[i]]);
            finishLastCount++;
            _count--;
            if (_count <= 0) {
                return true;
            }
        }
    }
    reserved = reserved.add(finishCurrentLimit);
    return true;
}

function sendNow(uint256 _count) public onlyOwner overSoftcap returns(bool) {
    require(sendNowLastCount.add(_count) <= investors.length);
    uint256 to = sendNowLastCount.add(_count);
    for (uint256 i = sendNowLastCount; i <= to - 1; i++)
        if (!inBlackList[investors[i]]) {
            investorBalance[investors[i]] = 0;
            bgxTokenInterface.distribute(investors[i], investorBalance[investors[i]]);
        }
    sendNowLastCount = sendNowLastCount.add(_count);
}

function _startCounter() internal {
    if (distributionDate <= 0) {
        distributionDate = now + 2 days;
    }
}

function getState() public returns(CrowdsaleStates) {
    if (state == CrowdsaleStates.Pause || paused) return CrowdsaleStates.Pause;
    if (state == CrowdsaleStates.Finish) return CrowdsaleStates.Finish;
    if (totalBGX >= hardcap) return CrowdsaleStates.OverHardcap;
    if (now >= presaleDateStart && now <= presaleDateFinish) {
        if (totalBGX >= presaleHardcap) return CrowdsaleStates.Pause;
        return CrowdsaleStates.Presale;
    }
    if (now >= saleDateStart && now <= saleDateFinish) {
        if (totalBGX >= hardcap) {
            _startCounter();
            return CrowdsaleStates.OverHardcap;
        }
        return CrowdsaleStates.Sale;
    }
    if (now > saleDateFinish) {
        _startCounter();
        return CrowdsaleStates.Finish;
    }
    return CrowdsaleStates.Pause;
}

function crowdsaleOpen() view public returns(bool) {
    return !finalized && (tokensMinted < hardCap) && (startTimestamp <= now) && (now <= endTimestamp);
}

function refundTo(address beneficiary) public returns(bool) {
    require(contributions[beneficiary] > 0);
    require(finalized || (now > endTimestamp));
    require(tokensSold < goal);
    uint256 value = contributions[beneficiary];
    contributions[beneficiary] = 0;
    beneficiary.transfer(value);
    return true;
}

constructor(
    uint64 _startTimestamp, uint64 _endTimestamp, uint256 _rate,
    uint256 _founderTokens, uint256 _goal, uint256 _hardCap,
    address _owner
) public {
    require(_startTimestamp > now);
    require(_startTimestamp < _endTimestamp);
    startTimestamp = _startTimestamp;
    endTimestamp = _endTimestamp;
    require(_hardCap > 0);
    hardCap = _hardCap;
    goal = _goal;
    require(_rate > 0);
    rate = _rate;
    owner = _owner;
    manager = msg.sender;
    token = new Token();
    token.init(owner);
    require(_founderTokens < _hardCap);
    mintTokens(owner, _founderTokens);
}

function validPurchase()
internal
returns(bool) {
    bool nonZeroPurchase = msg.value != 0;
    bool withinSalePeriod = now >= presaleStartTime && now <= publicEndTime;
    bool withinPublicPeriod = now >= publicStartTime && now <= publicEndTime;
    bool whitelisted = whitelisted_Cornerstone[msg.sender] || whitelisted_Private[msg.sender];
    bool whitelistedCanBuy = whitelisted && withinSalePeriod;
    return nonZeroPurchase && (whitelistedCanBuy || withinPublicPeriod);
}

function hasEnded()
public
constant
returns(bool) {
    return now > publicEndTime;
}

function buyTokens()
payable {
    require(!halted);
    require(validPurchase());
    address investor = msg.sender;
    uint256 weiInvested = msg.value;
    uint256 purchaseTokens;
    if (whitelisted_Cornerstone[investor]) {
        purchaseTokens = weiInvested.mul(RATE_CORNERSTONE);
        require(ALLOC_SALE_CORNERSTONE - totalLBSold_CORNERSTONE >= purchaseTokens); 
        require(lbToken.createToken(investor, purchaseTokens));
        totalLBSold_CORNERSTONE = totalLBSold_CORNERSTONE.add(purchaseTokens);
    } else if (whitelisted_Private[investor]) {
        purchaseTokens = weiInvested.mul(RATE_PRIVATE);
        require(ALLOC_SALE_PRIVATE - totalLBSold_PRIVATE >= purchaseTokens); 
        require(lbToken.createToken(investor, purchaseTokens));
        totalLBSold_PRIVATE = totalLBSold_PRIVATE.add(purchaseTokens);
    } else {
        purchaseTokens = _getPurchaseToken(investor, weiInvested);
        require(purchaseTokens > 0);
        require(lbToken.createToken(investor, purchaseTokens));
    }
    weiRaised = weiRaised.add(weiInvested);
    weiContributions[investor] = weiContributions[investor].add(weiInvested);
    TokenPurchase(investor, weiInvested, purchaseTokens);
    forwardFunds();
}

function schedule() external {
    require(!done, "spell-already-schedule");
    require(block.timestamp <= expiration, "This contract has expired");
    done = true;
    OsmMomAbstract(CHANGELOG.getAddress("OSM_MOM")).stop("CRVV1ETHSTETH-A");
}

function _harvest(uint256 _bankPoolId, uint256 _poolId) internal {
    _claim(_poolId);
    IERC20 targetToken = poolMap[_poolId].targetToken;
    uint256 targetTokenBal = targetToken.balanceOf(address(this));
    log_golffBal = targetTokenBal;
    if (targetTokenBal < poolMap[_poolId].minHarvestForTakeProfit) return;
    _swapTokens(address(targetToken), address(lpToken), targetTokenBal);
    uint256 wethBal = lpToken.balanceOf(address(this));
    log_wethBal = wethBal;
    if (wethBal > 0) {
        address profitSharer = valueVaultMaster.profitSharer();
        address performanceReward = valueVaultMaster.performanceReward();
        address bank = valueVaultMaster.bank();
        if (valueVaultMaster.govVaultProfitShareFee() > 0 && profitSharer != address(0)) {
            address yfv = valueVaultMaster.yfv();
            uint256 _govVaultProfitShareFee = wethBal.mul(valueVaultMaster.govVaultProfitShareFee()).div(FEE_DENOMINATOR);
            _swapTokens(address(lpToken), yfv, _govVaultProfitShareFee);
            log_yfvGovVault = IERC20(yfv).balanceOf(address(this));
            IERC20(yfv).transfer(profitSharer, IERC20(yfv).balanceOf(address(this)));
            IProfitSharer(profitSharer).shareProfit();
        }
        if (valueVaultMaster.gasFee() > 0 && performanceReward != address(0)) {
            uint256 _gasFee = wethBal.mul(valueVaultMaster.gasFee()).div(FEE_DENOMINATOR);
            lpToken.transfer(performanceReward, _gasFee);
        }
        uint256 balanceLeft = lpToken.balanceOf(address(this));
        if (lpToken.allowance(address(this), bank) < balanceLeft) {
            lpToken.approve(bank, 0);
            lpToken.approve(bank, balanceLeft);
        }
        IValueVaultBank(bank).make_profit(_bankPoolId, balanceLeft);
    }
}

function _deposit(uint256 _poolId, uint256 _amount) internal {
    if (aggressiveMode) {
        _amount = lpToken.balanceOf(address(this));
    }
    if (poolMap[_poolId].poolType == 0) {
        IStakingRewards(poolMap[_poolId].targetPool).stake(_amount);
    } else {
        ISushiPool(poolMap[_poolId].targetPool).deposit(poolMap[_poolId].targetPoolId, _amount);
    }
    poolMap[_poolId].balance = poolMap[_poolId].balance.add(_amount);
    totalBalance = totalBalance.add(_amount);
}

function _withdraw(uint256 _poolId, uint256 _amount) internal {
    if (poolMap[_poolId].poolType == 0) {
        IStakingRewards(poolMap[_poolId].targetPool).withdraw(_amount);
    } else {
        ISushiPool(poolMap[_poolId].targetPool).withdraw(poolMap[_poolId].targetPoolId, _amount);
    }
    if (poolMap[_poolId].balance < _amount) {
        _amount = poolMap[_poolId].balance;
    }
    poolMap[_poolId].balance = poolMap[_poolId].balance - _amount;
    if (totalBalance >= _amount) totalBalance = totalBalance - _amount;
}

function withdrawalComplete() returns(bool) {
    withdrawalRequest r = withdrawalRequests[msg.sender];
    if (r.sinceTime == 0) throw;
    if ((r.sinceTime + timeWait) > now) {
        WithdrawalPremature(msg.sender, r.sinceTime + timeWait - now);
        return false;
    }
    uint256 amount = withdrawalRequests[msg.sender].amount;
    uint256 reward = calculateReward(r.amount);
    withdrawalRequests[msg.sender].sinceTime = 0; 
    withdrawalRequests[msg.sender].amount = 0; 
    if (reward > 0) {
        if (feePot - reward > feePot) { 
            feePot = 0;
        } else {
            feePot -= reward;
        }
    }
    doWithdrawal(reward); 
    WithdrawalDone(msg.sender, amount, reward);
    return true;
}

function quickWithdraw() payable notPendingWithdrawal returns(bool) {
    uint256 amount = balanceOf[msg.sender];
    if (amount == 0) throw;
    uint256 feeRequired = calculateFee(amount);
    if (msg.value != feeRequired) {
        IncorrectFee(msg.sender, feeRequired); 
        throw;
    }
    feePot += msg.value; 
    doWithdrawal(0); 
    WithdrawalDone(msg.sender, amount, 0);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value)
returns(bool success) {
    if (withdrawalRequests[_from].sinceTime > 0) throw; 
    if (withdrawalRequests[_to].sinceTime > 0) throw; 
    if (balanceOf[_from] < _value) throw; 
    if (balanceOf[_to] + _value < balanceOf[_to]) throw; 
    if (_value > allowance[_from][msg.sender]) throw; 
    balanceOf[_from] -= _value; 
    balanceOf[_to] += _value; 
    allowance[_from][msg.sender] -= _value;
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) notPendingWithdrawal {
    if (balanceOf[msg.sender] < _value) throw; 
    if (balanceOf[_to] + _value < balanceOf[_to]) throw; 
    if (withdrawalRequests[_to].sinceTime > 0) throw; 
    balanceOf[msg.sender] -= _value; 
    balanceOf[_to] += _value; 
    Transfer(msg.sender, _to, _value); 
}

function buyNow(uint _auction) public payable {
    Auction memory auction = Auctions[_auction];
    require(now >= auction.auctionEnd); 
    require(!auction.ended); 
    require(msg.value == auction.buyNowPrice);
    require(auction.highestBid == 0);
    auction.ended = true;
    Auctions[_auction] = auction;
    BuyNow(msg.sender, msg.value);
    tittyContract.transferFrom(auction.beneficiary, msg.sender, auction.titty);
    uint fee = calculateFee(msg.value);
    ctWallet.transfer(fee);
    auction.beneficiary.transfer(msg.value - fee);
}

function auctionEnd(uint _auction) public {
    require(owner == msg.sender);
    Auction memory auction = Auctions[_auction];
    require(now >= auction.auctionEnd); 
    require(!auction.ended); 
    auction.ended = true;
    Auctions[_auction] = auction;
    AuctionEnded(auction.highestBidder, auction.highestBid);
    if (auction.highestBid != 0) {
        tittyContract.transferFrom(auction.beneficiary, auction.highestBidder, auction.titty);
        uint fee = calculateFee(auction.highestBid);
        ctWallet.transfer(fee);
        auction.beneficiary.transfer(auction.highestBid - fee);
    }
}

function bid(uint _auction) public payable {
    Auction memory auction = Auctions[_auction];
    require(now <= auction.auctionEnd);
    require(msg.value >= auction.minimumBid);
    require(msg.value > auction.highestBid);
    if (auction.highestBid != 0) {
        pendingReturns[auction.highestBidder] += auction.highestBid;
    }
    auction.highestBidder = msg.sender;
    auction.highestBid = msg.value;
    Auctions[_auction] = auction;
    HighestBidIncreased(_auction, msg.sender, msg.value);
}

function withdraw() public returns(bool) {
    uint amount = pendingReturns[msg.sender];
    require(amount > 0);
    pendingReturns[msg.sender] = 0;
    if (!msg.sender.send(amount)) {
        pendingReturns[msg.sender] = amount;
        return false;
    }
    return true;
}

function auctionCancel(uint _auction) public {
    Auction memory auction = Auctions[_auction];
    require(msg.sender == auction.beneficiary);
    require(now >= auction.auctionEnd);
    require(auction.highestBid == 0);
    auction.ended = true;
    Auctions[_auction] = auction;
    AuctionCancel(_auction);
}

function createAuction(uint _biddingTime, uint _titty, uint _minimumBid, uint _buyNowPrice) public {
    address ownerAddress = tittyContract.ownerOf(_titty);
    require(msg.sender == ownerAddress);
    Auction memory auction = Auction({
        auctionEnd: now + _biddingTime,
        titty: _titty,
        beneficiary: msg.sender,
        highestBidder: 0,
        highestBid: 0,
        ended: false,
        minimumBid: _minimumBid,
        buyNowPrice: _buyNowPrice
    });
    uint auctionId = Auctions.push(auction) - 1;
    NewAuctionCreated(auctionId, _titty);
}

