function join(uint256 _refference) public payable onlyFirst(_refference) investAmount returns(bool) {
    require(users[msg.sender].visit == 0, "you are already investor");
    cuurUserID++;
    userAddress[cuurUserID] = msg.sender;
    invested[msg.sender] = msg.value;
    user memory obj = user({
        recomendation: 0,
        creationTime: now,
        total_Days: 0,
        id: cuurUserID,
        total_Amount: 0,
        level: 0,
        referBy: _refference,
        expirePeriod: false,
        visit: 1,
        ref_Income: 0,
        total_Withdraw: 0,
        reffrals: new address[](0)
    });
    userList.push(obj);
    users[msg.sender] = obj;
    isRecomended[msg.sender] = true;
    commission = (msg.value.mul(10)).div(100);
    Creators(commission);
    address payable a = userAddress[_refference];
    recomendators[msg.sender] = a;
    users[a].reffrals.push(msg.sender);
    users[a].recomendation += 1;
    if (users[a].level < 1) {
        users[a].level = 1;
    }
    amount[msg.sender] = (invested[msg.sender].mul(1)).div(100);
    return true;
}

function withDraw() public payable returns(string memory) {
    uint256 d;
    address payable r = msg.sender;
    user memory obj = users[r];
    require(obj.expirePeriod == false);
    uint256 t = obj.total_Days;
    uint256 time = now - obj.creationTime;
    uint256 daysCount = time.div(86400);
    users[msg.sender].total_Days += daysCount;
    t += daysCount;
    if (t >= 401) {
        return session_Expire();
    }
    d = amount[msg.sender].mul(daysCount);
    uint256 p = obj.total_Amount;
    users[msg.sender].total_Amount += d;
    p += d;
    p += obj.ref_Income;
    if (daysCount > 0) {
        uint256 depth = 1;
        down_Income(msg.sender, depth, d);
        users[msg.sender].creationTime = now;
    }
    d = obj.ref_Income.add(d);
    if (p > invested[msg.sender].mul(4)) {
        uint256 x = (invested[msg.sender].mul(4)).sub(obj.total_Withdraw);
        r.transfer(x);
        session = session_Expire();
        return "you have WithDraw all your profit";
    } else {
        users[msg.sender].total_Withdraw = obj.total_Withdraw.add(d);
        r.transfer(d);
        return "you have succesfully WithDrawl your money";
    }
}

function owner_withdraw() public payable onlyOwner returns(bool) {
    user memory obj = users[owner];
    require(obj.ref_Income > 0, "your earnings are less than 0");
    owner.transfer(obj.ref_Income);
    users[owner].ref_Income = 0;
    return true;
}

function Reinvest() public payable reinvest investAmount returns(bool) {
    require(users[msg.sender].expirePeriod == true, "your session should be new");
    invested[msg.sender] = msg.value;
    users[msg.sender].creationTime = now;
    users[msg.sender].expirePeriod = false;
    users[msg.sender].visit += 1;
    amount[msg.sender] = (invested[msg.sender].mul(1)).div(100);
    return true;
}

function transferSubscription(bytes32 productId, address newSubscriber) public whenNotHalted {
    var (isValid, product, sub) = _getSubscription(productId, msg.sender);
    require(isValid, "error_subscriptionNotValid");
    uint secondsLeft = sub.endTimestamp.sub(block.timestamp);
    TimeBasedSubscription storage newSub = product.subscriptions[newSubscriber];
    _addSubscription(product, newSubscriber, secondsLeft, newSub);
    delete product.subscriptions[msg.sender];
    emit SubscriptionTransferred(productId, msg.sender, newSubscriber, secondsLeft);
}

function _addSubscription(Product storage p, address subscriber, uint addSeconds, TimeBasedSubscription storage oldSub) internal {
    uint endTimestamp;
    if (oldSub.endTimestamp > block.timestamp) {
        require(addSeconds > 0, "error_topUpTooSmall");
        endTimestamp = oldSub.endTimestamp.add(addSeconds);
        oldSub.endTimestamp = endTimestamp;
        emit SubscriptionExtended(p.id, subscriber, endTimestamp);
    } else {
        require(addSeconds >= p.minimumSubscriptionSeconds, "error_newSubscriptionTooSmall");
        endTimestamp = block.timestamp.add(addSeconds);
        TimeBasedSubscription memory newSub = TimeBasedSubscription(endTimestamp);
        p.subscriptions[subscriber] = newSub;
        emit NewSubscription(p.id, subscriber, endTimestamp);
    }
    emit Subscribed(p.id, subscriber, endTimestamp);
}

function _getSubscription(bytes32 productId, address subscriber) internal constant returns(bool subIsValid, Product storage, TimeBasedSubscription storage) {
    Product storage p = products[productId];
    require(p.id != 0x0, "error_notFound");
    TimeBasedSubscription storage s = p.subscriptions[subscriber];
    return (s.endTimestamp >= block.timestamp, p, s);
}

function sendPrize(address[] winners, uint256[] amounts, uint64 _flag)
external
onlyService
whenNotPaused {
    uint64 tmNow = uint64(block.timestamp);
    uint256 length = winners.length;
    require(length == amounts.length);
    require(length <= 64);
    uint256 sum = 0;
    for (uint32 i = 0; i < length; ++i) {
        sum = sum.add(amounts[i]);
    }
    uint256 balance = this.balance;
    require((sum.mul(100).div(balance)) <= maxPrizeOneDay);
    address addrZero = address(0);
    for (uint32 j = 0; j < length; ++j) {
        if (winners[j] != addrZero) {
            winners[j].transfer(amounts[j]);
        }
    }
    nextPrizeTime = tmNow + 72000;
    SendPrizeSuccesss(_flag, balance, sum);
}

function transferWithAuthorization(
    address from,
    address to,
    uint256 value,
    uint256 validAfter,
    uint256 validBefore,
    bytes32 nonce,
    uint8 v,
    bytes32 r,
    bytes32 s
)
external {
    require(block.timestamp > validAfter, "ANTV2:AUTH_NOT_YET_VALID");
    require(block.timestamp < validBefore, "ANTV2:AUTH_EXPIRED");
    require(!authorizationState[from][nonce], "ANTV2:AUTH_ALREADY_USED");
    bytes32 encodedData = keccak256(abi.encode(TRANSFER_WITH_AUTHORIZATION_TYPEHASH, from, to, value, validAfter, validBefore, nonce));
    _validateSignedData(from, encodedData, v, r, s);
    authorizationState[from][nonce] = true;
    emit AuthorizationUsed(from, nonce);
    _transfer(from, to, value);
}

function permit(address owner, address spender, uint256 value, uint256 deadline, uint8 v, bytes32 r, bytes32 s) external {
    require(deadline >= block.timestamp, "ANTV2:AUTH_EXPIRED");
    bytes32 encodedData = keccak256(abi.encode(PERMIT_TYPEHASH, owner, spender, value, nonces[owner]++, deadline));
    _validateSignedData(owner, encodedData, v, r, s);
    _approve(owner, spender, value);
}

