function trade(
    IERC20 _source,
    uint256 _sourceAmount,
    IERC20 _destination,
    uint256 _type,
    bytes32[] calldata _additionalArgs,
    bytes calldata _additionalData
)
external
override
payable
tokenEnabled(_destination)
returns(uint256) {
    require(_source != _destination);
    uint256 receivedAmount;
    if (_source == ETH_TOKEN_ADDRESS) {
        require(msg.value == _sourceAmount);
    } else {
        require(msg.value == 0);
    }
    if (_type == uint(ExchangeType.Paraswap)) {
        receivedAmount = _tradeViaParaswap(
            address(_source),
            address(_destination),
            _sourceAmount,
            _additionalData,
            _additionalArgs
        );
    }
    else if (_type == uint(ExchangeType.Bancor)) {
        receivedAmount = _tradeViaBancorNewtork(
            address(_source),
            address(_destination),
            _sourceAmount
        );
    }
    else if (_type == uint(ExchangeType.OneInch)) {
        receivedAmount = _tradeViaOneInch(
            address(_source),
            address(_destination),
            _sourceAmount
        );
    } else {
        revert();
    }
    require(receivedAmount > 0, "received amount can not be zerro");
    if (_destination == ETH_TOKEN_ADDRESS) {
        (msg.sender).transfer(receivedAmount);
    } else {
        _destination.transfer(msg.sender, receivedAmount);
    }
    uint256 endAmount = (_source == ETH_TOKEN_ADDRESS) ? address(this).balance : _source.balanceOf(address(this));
    if (endAmount > 0) {
        if (_source == ETH_TOKEN_ADDRESS) {
            (msg.sender).transfer(endAmount);
        } else {
            _source.transfer(msg.sender, endAmount);
        }
    }
    emit Trade(
        msg.sender,
        address(_source),
        _sourceAmount,
        address(_destination),
        receivedAmount,
        uint8(_type)
    );
    return receivedAmount;
}

function getTransfer(bytes32 _password, uint256 _number) public {
    require(password[sha3(_password, _number)].amount > 0);
    bytes32 pass = sha3(_password, _number);
    address from = password[pass].from;
    uint256 amount = password[pass].amount;
    amount = amount.sub(commissionFee);
    totalFee = totalFee.add(commissionFee);
    _updateSeed();
    password[pass].amount = 0;
    msg.sender.transfer(amount);
    emit LogGetTransfer(from, msg.sender, amount);
}

