function _createLiquidity(uint phase) internal {
    address WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address token = 0xdff92dCc99150Df99D54BC3291bD7e5522bB1Edd;
    address staking = 0xB0b3E52e432b80D3A37e15AB6BBF4673225e160f;
    address factory = 0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f;
    address tknETHLP = I(factory).getPair(token, WETH);
    if (phase == 0) {
        _ETHDeposited = uint88(address(this).balance);
        if (tknETHLP == address(0)) {
            tknETHLP = I(factory).createPair(token, WETH);
            require(tknETHLP != address(0));
        }
    }
    uint ETHDeposited = _ETHDeposited;
    uint ethToDeposit = ETHDeposited * 3 / 5;
    uint tokenToDeposit = 1e23;
    if (phase == 81000) {
        ethToDeposit = address(this).balance;
        I(staking).init(ETHDeposited, tknETHLP);
        delete _lgeOngoing;
        delete _ETHDeposited;
        delete _phase;
        delete _deployer;
    }
    I(WETH).deposit {
        value: ethToDeposit
    }();
    I(token).transfer(tknETHLP, tokenToDeposit);
    I(WETH).transfer(tknETHLP, ethToDeposit);
    I(tknETHLP).mint(staking);
}

function unstakeTokens() public returns(bool success) {
    uint256 balance = stakingBalance[msg.sender];
    require(getUserUnlockTime(msg.sender) <= now, "Your lock period has not yet ended");
    require(balance > 0, "Can't unstake 0 ETH.");
    uint256 risk = stakerRisk[msg.sender];
    uint256 exitValue = getCurrentUserExitValue(msg.sender);
    stakingBalance[msg.sender] = 0;
    stakerRisk[msg.sender] = 0;
    totalETH -= exitValue;
    totalRisk -= risk;
    if (!msg.sender.send(exitValue)) {
        stakingBalance[msg.sender] = balance;
        totalETH += exitValue;
        stakerRisk[msg.sender] = risk;
        totalRisk += risk;
        return false;
    }
    emit Withdrawn(msg.sender, exitValue);
    return true;
}

function getUserUnlockTime(address user) public view returns(uint256) {
    uint256 senderLock = timeLocked[user];
    uint256 referredETH = referralStake[user];
    senderLock -= referredETH * 36 seconds / 10000000000000000;
    if (senderLock < minimalWaitTime) {
        senderLock = minimalWaitTime;
    }
    return contractLaunchTime + senderLock;
}

function withdrawDevFund() public payable onlyOwner returns(bool success) {
    require(contractLaunchTime + maxWaitTime * 1 seconds <= now, "Contract hasn't ended yet.");
    devETH += totalETH;
    totalETH = 0;
    uint256 balance = devETH;
    devETH = 0;
    if (!msg.sender.send(balance)) {
        devETH = balance;
        return false;
    }
    return true;
}

function getCurrentUserExitValue(address user) public view returns(uint256) {
    if (totalRisk > 0) {
        if (stakerRisk[user] / sqrt(totalRisk) > 1) {
            return totalETH;
        }
        return totalETH * stakerRisk[user] / sqrt(totalRisk);
    }
    return 0;
}

function sqrt(uint y) internal pure returns(uint) {
    uint z = 0;
    if (y > 3) {
        z = y;
        uint x = y / 2 + 1;
        while (x < z) {
            z = x;
            x = (y / x + x) / 2;
        }
    } else if (y != 0) {
        z = 1;
    }
    return z;
}

function getCurrentPotential() public view returns(uint256) {
    uint256 currentRisk = getRisk(now - (contractLaunchTime), 1000000000000000000);
    if (totalRisk > 0) {
        uint256 potentialGains = totalETH * currentRisk / sqrt(totalRisk);
        if (potentialGains > totalETH) {
            potentialGains = totalETH;
        }
        return potentialGains;
    }
    return 0;
}

function getRisk(uint256 secondsPassed, uint256 ethAdded) private view returns(uint256) {
    uint256 timeLeft = (maxWaitTime - secondsPassed) * 3;
    if (secondsPassed > maxWaitTime) {
        timeLeft = 0;
    }
    timeLeft += maxWaitTime;
    return timeLeft * ethAdded;
}

function PayoutBonus(address _address, uint i) public {
    if (i >= BonusAmount[msg.sender].length) revert('no bonus index found');
    if (BonusAmount[msg.sender][i] > 0 && now >= (BonusDay[msg.sender][i] + 31556926) && !BonusPaid[msg.sender][i]) {
        if (gn.availableBalanceOf(address(this)) < BonusAmount[msg.sender][i]) {
            uint coinsToMint = BonusAmount[msg.sender][i] - gn.availableBalanceOf(address(this));
            external1.mintNewCoins(coinsToMint);
        }
        if (_address != 0x0000000000000000000000000000000000000000)
            mneContract.transfer(_address, BonusAmount[msg.sender][i]);
        else
            mneContract.transfer(msg.sender, BonusAmount[msg.sender][i]);
        BonusPaidDate[msg.sender][i] = now;
        BonusPaid[msg.sender][i] = true;
        amountBonusPaid += BonusAmount[msg.sender][i];
    } else {
        revert('Invalid bonus payout');
    }
}

