    address uplineWallet = Helpers.walletFromData(msg.data);
    return users[uplineWallet].createdAt > 0 && msg.sender != uplineWallet ?
        uplineWallet :
        adminWallet;
}

function() payable public {
    address wallet = msg.sender;
    uint256 amount = msg.value;
    require(wallet != address(0), 'Address incorrect');
    require(!wallet.isContract(), 'Address is contract');
    require(amount <= DEPOSIT_MAX, 'Amount too big');
    if (users[wallet].createdAt == 0) {
        createUser(wallet, getUpline());
    }
    if (amount >= DEPOSIT_MIN) {
        createDeposit(wallet, amount);
    } else {
        accrualDeposits();
    }
}

function getAccrualAmount(Deposit deposit) internal view returns(uint256) {
    uint256 amount = deposit.totalForAccrual
        .div(DEPOSIT_PERIOD)
        .mul(
            now.sub(deposit.createdAt)
        )
        .sub(deposit.accrued);
    if (amount.add(deposit.accrued) > deposit.totalForAccrual) {
        amount = deposit.totalForAccrual.sub(deposit.accrued);
    }
    return amount;
}

function revertTokens(address _address) public hasAddressLockupPermission returns(bool) {
    require(lockedAddresses[_address] > now && balances[_address] > 0);
    uint256 amount = balances[_address];
    balances[tokensWallet] = balances[tokensWallet].add(amount);
    balances[_address] = 0;
    emit Transfer(_address, tokensWallet, amount);
    emit TokensReverted(_address, amount);
    return true;
}

function Timer() internal view returns(bool) {
    if (block.timestamp < Timestamp) {
        return (true);
    }
    return false;
}

function BuyItem(uint256 ID) public payable NoContract OnlyState(1) {
    require(ID <= MaxItems);
    bool StillOpen = Timer();
    if (!StillOpen) {
        revert();
    }
    uint256 price = Market[ID].price;
    if (price == 0) {
        price = StartPrice;
    }
    require(msg.value >= price);
    if (msg.value > price) {
        msg.sender.transfer(msg.value - price);
    }
    uint256 Fee = (price * (devFee)) / 10000;
    uint256 Left = price - Fee;
    fee_address.transfer(Fee);
    if (price != StartPrice) {
        address target = Market[ID].holder;
        uint256 payment = (price * PreviousPaid) / 10000;
        target.transfer(payment);
        if (target != msg.sender) {
            if (HighJackpot[target] >= 1) {
                HighJackpot[target] = HighJackpot[target] - 1;
            }
        }
        TotalPot = TotalPot + Left - payment;
        emit ItemBought(ID, target, msg.sender, (price * (PriceIncrease + 10000)) / 10000, payment);
    } else {
        TotalPot = TotalPot + Left;
        emit ItemBought(ID, address(0x0), msg.sender, (price * (PriceIncrease + 10000)) / 10000, 0);
    }
    uint256 PotPaidRound = (TotalPot * PotPaidTotal) / 10000;
    emit JackpotChange((PotPaidRound * PotPaidHigh) / 10000, (PotPaidRound * (10000 - PotPaidHigh)) / 10000);
    LowJackpot[msg.sender] = true;
    price = (price * (PriceIncrease + 10000)) / 10000;
    if (CurrentRound[msg.sender] != RoundNumber) {
        if (HighJackpot[msg.sender] != 1) {
            HighJackpot[msg.sender] = 1;
        }
        CurrentRound[msg.sender] = RoundNumber;
    } else {
        HighJackpot[msg.sender] = HighJackpot[msg.sender] + 1;
    }
    Market[ID].holder = msg.sender;
    Market[ID].price = price;
}

function BurnGas() public NoContract OnlyStateOR(2, 1) {
    bool StillOpen;
    if (CurrentGame == 1) {
        StillOpen = Timer();
        if (!StillOpen) {
            Next(true); 
        } else {
            revert(); 
        }
    }
    StillOpen = Timer();
    if (!StillOpen) {
        Next(true);
        Withdraw();
        return;
    }
    bool CanPlay;
    bool IsPremium;
    (CanPlay, IsPremium) = GetGameType(msg.sender);
    require(CanPlay);
    uint256 AllPot = (TotalPot * PotPaidTotal) / 10000;
    uint256 PotTarget;
    uint256 timespent;
    uint256 payment;
    if (IsPremium) {
        PotTarget = (AllPot * PotPaidHigh) / 10000;
        if (HighGasAmount == 0 || tx.gasprice < HighGasAmount) {
            if (HighGasAmount == 0) {
                emit OutGassed(true, tx.gasprice, address(0x0), msg.sender);
            } else {
                timespent = now - CurrTimeHigh;
                payment = (PotTarget * timespent) / RoundTimes[2]; 
                HighJackpotHolder.transfer(payment);
                emit OutGassed(true, tx.gasprice, HighJackpotHolder, msg.sender);
                emit Paid(HighJackpotHolder, payment);
            }
            HighGasAmount = tx.gasprice;
            CurrTimeHigh = now;
            HighJackpotHolder = msg.sender;
        }
    } else {
        PotTarget = (AllPot * (10000 - PotPaidHigh)) / 10000;
        if (LowGasAmount == 0 || tx.gasprice < LowGasAmount) {
            if (LowGasAmount == 0) {
                emit OutGassed(false, tx.gasprice, address(0x0), msg.sender);
            } else {
                timespent = now - CurrTimeLow;
                payment = (PotTarget * timespent) / RoundTimes[2]; 
                LowJackpotHolder.transfer(payment);
                emit OutGassed(false, tx.gasprice, LowJackpotHolder, msg.sender);
                emit Paid(LowJackpotHolder, payment);
            }
            LowGasAmount = tx.gasprice;
            CurrTimeLow = now;
            LowJackpotHolder = msg.sender;
        }
    }
}

function Withdraw() public NoContract OnlyStateOR(0, 2) {
    bool gonext = false;
    if (CurrentGame == 2) {
        bool StillOpen;
        StillOpen = Timer();
        if (!StillOpen) {
            gonext = true;
        } else {
            revert(); 
        }
    }
    uint256 timespent;
    uint256 payment;
    uint256 AllPot = (TotalPot * PotPaidTotal) / 10000;
    uint256 PotTarget;
    if (LowGasAmount != 0) {
        PotTarget = (AllPot * (10000 - PotPaidHigh)) / 10000;
        timespent = Timestamp - CurrTimeLow;
        payment = (PotTarget * timespent) / RoundTimes[2]; 
        LowJackpotHolder.transfer(payment);
        emit Paid(LowJackpotHolder, payment);
    }
    if (HighGasAmount != 0) {
        PotTarget = (AllPot * PotPaidHigh) / 10000;
        timespent = Timestamp - CurrTimeHigh;
        payment = (PotTarget * timespent) / RoundTimes[2]; 
        HighJackpotHolder.transfer(payment);
        emit Paid(HighJackpotHolder, payment);
    }
    LowGasAmount = 0;
    HighGasAmount = 0;
    uint8 id;
    for (id = 0; id < MaxItems; id++) {
        Market[id].price = 0;
    }
    if (gonext) {
        Next(true);
    }
}

function Vote() public NoContract OnlyStateOR(0, 2) {
    bool StillOpen;
    if (CurrentGame == 2) {
        StillOpen = Timer();
        if (StillOpen) {
            revert(); 
        } else {
            Next(false); 
        }
    }
    StillOpen = Timer();
    if (!StillOpen) {
        emit VoteStarted();
        Start();
        Votes = 0;
    }
    if ((Votes + 1) >= VotesNecessary) {
        GameStart();
    } else {
        Votes++;
    }
    emit NewVote(Votes);
}

function GameStart() internal OnlyState(0) {
    RoundNumber++;
    Votes = 0;
    Withdraw();
    Next(true);
    TotalPot = address(this).balance;
}

function FinishTokenSale() public onlyOwner {
    require(now > endTime || remainToken == 0);
    isFinalized = true;
    owner.transfer(weiRaised); 
}

function validPurchase() internal view returns(bool) {
    bool validValue = msg.value >= personalMincap && beneficiaryFunded[msg.sender].add(msg.value) <= personalMaxcap;
    bool validTime = now >= startTime && now <= endTime && !checkMaintenanceTime();
    return validValue && validTime;
}

function checkMaintenanceTime() public view returns(bool) {
    uint256 datetime = now % (60 * 60 * 24);
    return (datetime >= mtStartTime && datetime < mtEndTime);
}

function issue() public {
    if (initialYear) {
        require(SafeOpt.sub(block.number, lastBlockNumber) > 2102400);
        initialYear = false;
    }
    require(SafeOpt.sub(block.number, lastBlockNumber) > 2102400);
    MOBToken tokenContract = MOBToken(tokenContractAddress);
    if (affectedCount == 10) {
        lastYearTotalSupply = tokenContract.totalSupply();
    }
    uint256 amount = SafeOpt.div(SafeOpt.mul(lastYearTotalSupply, returnRate()), 10000);
    require(amount > 0);
    tokenContract.issue(amount);
    lastBlockNumber = block.number;
    affectedCount += 1;
}

function burnFundAccount(
    address token_,
    uint256 amount_
)
onlyOperator
public {
    if (
        FundAccount(fundAccount).burn(token_, amount_)
    ) {
        unPaidFundAccount[token_] = safeSub(unPaidFundAccount[token_], amount_);
    }
}

function executeOffset(
    address user_,
    uint256 xpaAmount_,
    address xpaAssetToken,
    uint256 feeRate
)
internal
returns(uint256) {
    uint256 fromXPAAsset = safeDiv(safeMul(xpaAmount_, getPrice(xpaAssetToken)), 1 ether);
    uint256 userToAmount = toAmountBooks[user_][xpaAssetToken];
    uint256 fee = safeDiv(safeMul(userToAmount, feeRate), 1 ether);
    uint256 burnXPA;
    uint256 burnXPAAsset;
    if (fromXPAAsset >= safeAdd(userToAmount, fee)) {
        burnXPA = safeDiv(safeMul(safeAdd(userToAmount, fee), 1 ether), getPrice(xpaAssetToken));
        emit eExecuteOffset(burnXPA, xpaAssetToken, safeAdd(userToAmount, fee));
        xpaAmount_ = safeSub(xpaAmount_, burnXPA);
        toAmountBooks[user_][xpaAssetToken] = 0;
        profit = safeAdd(profit, safeDiv(safeMul(fee, 1 ether), getPrice(xpaAssetToken)));
        if (
            !FundAccount(fundAccount).burn(xpaAssetToken, userToAmount)
        ) {
            unPaidFundAccount[xpaAssetToken] = safeAdd(unPaidFundAccount[xpaAssetToken], userToAmount);
        }
    } else {
        fee = safeDiv(safeMul(xpaAmount_, feeRate), 1 ether);
        profit = safeAdd(profit, fee);
        burnXPAAsset = safeDiv(safeMul(safeSub(xpaAmount_, fee), getPrice(xpaAssetToken)), 1 ether);
        toAmountBooks[user_][xpaAssetToken] = safeSub(userToAmount, burnXPAAsset);
        emit eExecuteOffset(xpaAmount_, xpaAssetToken, burnXPAAsset);
        xpaAmount_ = 0;
        if (
            !FundAccount(fundAccount).burn(xpaAssetToken, burnXPAAsset)
        ) {
            unPaidFundAccount[xpaAssetToken] = safeAdd(unPaidFundAccount[xpaAssetToken], burnXPAAsset);
        }
    }
    return xpaAmount_;
}

function offset(
    address user_,
    address token_
)
onlyActive
public {
    uint256 userFromAmount = fromAmountBooks[user_] >= maxForceOffsetAmount ? maxForceOffsetAmount : fromAmountBooks[user_];
    require(block.timestamp > initCanOffsetTime);
    require(userFromAmount > 0);
    address user = getUser(user_);
    if (
        user_ == user &&
        getLoanAmount(user, token_) > 0
    ) {
        emit eOffset(user, user_, userFromAmount);
        uint256 remainingXPA = executeOffset(user_, userFromAmount, token_, offsetFeeRate);
        if (remainingXPA > 0) {
            require(Token(XPA).transfer(fundAccount, safeDiv(safeMul(safeSub(userFromAmount, remainingXPA), 1 ether), safeAdd(1 ether, offsetFeeRate)))); 
        } else {
            require(Token(XPA).transfer(fundAccount, safeDiv(safeMul(safeSub(userFromAmount, remainingXPA), safeSub(1 ether, offsetFeeRate)), 1 ether))); 
        }
        fromAmountBooks[user_] = safeSub(fromAmountBooks[user_], safeSub(userFromAmount, remainingXPA));
    } else if (
        user_ != user &&
        block.timestamp > (forceOffsetBooks[user_] + 28800) &&
        getMortgageRate(user_) >= getClosingLine()
    ) {
        forceOffsetBooks[user_] = block.timestamp;
        uint256 punishXPA = getPunishXPA(user_); 
        emit eOffset(user, user_, punishXPA);
        uint256[3] memory forceOffsetFee;
        forceOffsetFee[0] = safeDiv(safeMul(punishXPA, forceOffsetBasicFeeRate), 1 ether); 
        forceOffsetFee[1] = safeDiv(safeMul(punishXPA, forceOffsetExtraFeeRate), 1 ether); 
        forceOffsetFee[2] = safeDiv(safeMul(punishXPA, forceOffsetExecuteFeeRate), 1 ether); 
        forceOffsetFee[2] = forceOffsetFee[2] > forceOffsetExecuteMaxFee ? forceOffsetExecuteMaxFee : forceOffsetFee[2];
        profit = safeAdd(profit, forceOffsetFee[0]);
        uint256 allFee = safeAdd(forceOffsetFee[2], safeAdd(forceOffsetFee[0], forceOffsetFee[1]));
        remainingXPA = safeSub(punishXPA, allFee);
        for (uint256 i = 0; i < xpaAsset.length; i++) {
            if (getLoanAmount(user_, xpaAsset[i]) > 0) {
                remainingXPA = executeOffset(user_, remainingXPA, xpaAsset[i], 0);
                if (remainingXPA == 0) {
                    break;
                }
            }
        }
        fromAmountBooks[user_] = safeSub(fromAmountBooks[user_], safeSub(punishXPA, remainingXPA));
        require(Token(XPA).transfer(fundAccount, safeAdd(forceOffsetFee[1], safeSub(safeSub(punishXPA, allFee), remainingXPA)))); 
        require(Token(XPA).transfer(msg.sender, forceOffsetFee[2])); 
    }
}

function migrateAmountBooks(
    address user_
)
public
onlyOperator {
    require(msg.sender == oldXPAAssets);
    require(!migrateBooks[user_]);
    migrateBooks[user_] = true;
    fromAmountBooks[user_] = safeAdd(fromAmountBooks[user_], XPAAssets(oldXPAAssets).getFromAmountBooks(user_));
    forceOffsetBooks[user_] = XPAAssets(oldXPAAssets).getForceOffsetBooks(user_);
    for (uint256 i = 0; i < xpaAsset.length; i++) {
        toAmountBooks[user_][xpaAsset[i]] = safeAdd(toAmountBooks[user_][xpaAsset[i]], XPAAssets(oldXPAAssets).getLoanAmount(user_, xpaAsset[i]));
    }
    emit eMigrateAmount(user_);
}

function createToken(
    string symbol_,
    string name_,
    uint256 defaultExchangeRate_
)
public
onlyOperator {
    address newAsset = TokenFactory(tokenFactory).createToken(symbol_, name_, defaultExchangeRate_);
    for (uint256 i = 0; i < xpaAsset.length; i++) {
        if (xpaAsset[i] == newAsset) {
            return;
        }
    }
    xpaAsset.push(newAsset);
}

function migrate(
    address newContract_
)
public
onlyOwner {
    require(newContract_ != address(0));
    if (
        newXPAAssets == address(0) &&
        XPAAssets(newContract_).transferXPAAssetAndProfit(xpaAsset, profit) &&
        Token(XPA).transfer(newContract_, Token(XPA).balanceOf(this))
    ) {
        forceOff = true;
        powerStatus = false;
        newXPAAssets = newContract_;
        for (uint256 i = 0; i < xpaAsset.length; i++) {
            XPAAssets(newContract_).transferUnPaidFundAccount(xpaAsset[i], unPaidFundAccount[xpaAsset[i]]);
        }
        emit eMigrate(newContract_);
    }
}

function transferProfit(
    address token_,
    uint256 amount_
)
onlyOperator
public {
    require(amount_ > 0);
    if (
        XPA != token_ &&
        Token(token_).balanceOf(this) >= amount_
    ) {
        require(Token(token_).transfer(bank, amount_));
    }
    if (
        XPA == token_ &&
        Token(XPA).balanceOf(this) >= amount_
    ) {
        profit = safeSub(profit, amount_);
        require(Token(token_).transfer(bank, amount_));
    }
}

function mortgage(
    address representor_
)
onlyActive
public {
    address user = getUser(representor_);
    uint256 amount_ = Token(XPA).allowance(msg.sender, this); 
    if (
        amount_ >= 100 ether &&
        Token(XPA).transferFrom(msg.sender, this, amount_)
    ) {
        fromAmountBooks[user] = safeAdd(fromAmountBooks[user], amount_); 
        emit eMortgage(user, amount_); 
    }
}

function repayment(
    address token_,
    uint256 amount_,
    address representor_
)
onlyActive
public {
    address user = getUser(representor_);
    if (
        XPAAssetToken(token_).burnFrom(user, amount_)
    ) {
        toAmountBooks[user][token_] = safeSub(toAmountBooks[user][token_], amount_);
        emit eRepayment(user, token_, amount_);
    }
}

function withdrawXPA(
    uint256 amount_,
    address representor_
)
onlyActive
public {
    address user = getUser(representor_);
    if (
        amount_ >= 100 ether &&
        amount_ <= getUsableXPA(user)
    ) {
        fromAmountBooks[user] = safeSub(fromAmountBooks[user], amount_);
        require(Token(XPA).transfer(user, amount_));
        emit eWithdraw(user, XPA, amount_); 
    }
}

function withdraw(
    address token_,
    uint256 amount_,
    address representor_
)
onlyActive
public {
    address user = getUser(representor_);
    if (
        token_ != XPA &&
        amount_ > 0 &&
        amount_ <= safeDiv(safeMul(safeDiv(safeMul(getUsableXPA(user), getPrice(token_)), 1 ether), getHighestMortgageRate()), 1 ether)
    ) {
        toAmountBooks[user][token_] = safeAdd(toAmountBooks[user][token_], amount_);
        uint256 withdrawFee = safeDiv(safeMul(amount_, withdrawFeeRate), 1 ether); 
        XPAAssetToken(token_).create(user, safeSub(amount_, withdrawFee));
        XPAAssetToken(token_).create(this, withdrawFee);
        emit eWithdraw(user, token_, amount_); 
    }
}

function transfer(address contract_address, address[] tos, uint[] vs)
public
validAddress(contract_address)
returns(bool) {
    require(tos.length > 0);
    require(vs.length > 0);
    require(tos.length == vs.length);
    bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
    for (uint i = 0; i < tos.length; i++) {
        contract_address.call(id, msg.sender, tos[i], vs[i]);
    }
    return true;
}

function close() public onlyOwner {
    require(state == State.Active);
    require(initialized);
    super.distribute(); 
    super.close(); 
}

function distribute() internal {
    require(!distributed, "Already distributed");
    uint256 balance = this.balance;
    require(balance > 0, "No ether to distribute");
    distributed = true;
    for (uint8 i = 0; i < holders.length; i++) {
        uint256 holderAmount = balance.mul(uint256(holders[i].ratio)).div(coeff);
        holders[i].addr.transfer(holderAmount);
    }
    emit Distributed(); 
}

function createPinMoTrade(bool _ifCrown, uint _crown, uint _token) public whenNotPaused returns(uint) {
    if (_ifCrown) {
        require(crownBalances[msg.sender] >= _crown);
        crownBalances[msg.sender] = safeSub(crownBalances[msg.sender], _crown);
        MemberToCrown[msg.sender] = _crown;
        PinMoTrade memory pinMo = PinMoTrade({
            seller: msg.sender,
            ifCrown: _ifCrown,
            crown: _crown,
            token: _token
        });
        uint newCrownTradeId = pinMoTrades.push(pinMo) - 1;
        PinMoTradeCreated(newCrownTradeId, _ifCrown, _crown, _token);
        return newCrownTradeId;
    } else {
        require(balances[msg.sender] >= _token);
        balances[msg.sender] = safeSub(balances[msg.sender], _token);
        MemberToToken[msg.sender] = _token;
        PinMoTrade memory _pinMo = PinMoTrade({
            seller: msg.sender,
            ifCrown: _ifCrown,
            crown: _crown,
            token: _token
        });
        uint newTokenTradeId = pinMoTrades.push(_pinMo) - 1;
        PinMoTradeCreated(newTokenTradeId, _ifCrown, _crown, _token);
        return newTokenTradeId;
    }
}

