}

function trade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
public
payable
returns(bool) {
    require(tradeEnabled);
    require(msg.sender == kyberNetwork);
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS) {
            require(msg.value == srcAmount);
            require(ERC20(destToken) == digix);
        } else {
            require(ERC20(srcToken) == digix);
            require(msg.value == 0);
        }
    }
    uint destAmount = getDestQty(srcToken, destToken, srcAmount, conversionRate);
    uint adjustedAmount;
    require(destAmount > 0);
    if (srcToken != ETH_TOKEN_ADDRESS) {
        adjustedAmount = (srcAmount * (10000 - sellTransferFee) / 10000) - 1;
        require(srcToken.transferFrom(msg.sender, this, adjustedAmount));
    }
    if (destToken == ETH_TOKEN_ADDRESS) {
        destAddress.transfer(destAmount);
    } else {
        adjustedAmount = (destAmount * 10000 / (10000 - buyTransferFee)) + 1;
        require(destToken.transfer(destAddress, adjustedAmount));
    }
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, destAmount, destAddress);
    return true;
}

function wrap(uint256[] calldata _leviathansToWrap) public notPaused {
    for (uint256 i = 0; i < _leviathansToWrap.length; i++) {
        require(_leviathansToWrap[i] >= 1 && _leviathansToWrap[i] <= 333, "WrappedLeviathan: Invalid ID.");
        leviathans.push(_leviathansToWrap[i]);
        LEVIATHAN.transferFrom(msg.sender, address(this), _leviathansToWrap[i]);
        if (checkClaim(_leviathansToWrap[i]) > 0)
            ILeviathanClaim(_leviathanClaim).release(_leviathansToWrap[i]);
        emit LeviathanWrapped(_leviathansToWrap[i]);
    }
    _mint(msg.sender, _leviathansToWrap.length * (10 ** uint256(decimals)));
    uint surfBalance = IERC20(_surf).balanceOf(address(this));
    if (surfBalance > 0)
        IERC20(_surf).transfer(_leviathanClaim, surfBalance);
}

function unwrapFor(uint256 _amount, address _recipient) public notPaused {
    require(_recipient != address(0), "WrappedLeviathan: Cannot send to void address.");
    _burn(msg.sender, _amount * (10 ** uint256(decimals)));
    uint256 _seed = 0;
    for (uint256 i = 0; i < _amount; i++) {
        _seed = _getSeed(_seed, msg.sender);
        uint256 _index = _seed % leviathans.length;
        uint256 _tokenId = leviathans[_index];
        leviathans[_index] = leviathans[leviathans.length - 1];
        leviathans.pop();
        if (checkClaim(_tokenId) > 0)
            ILeviathanClaim(_leviathanClaim).release(_tokenId);
        LEVIATHAN.transferFrom(address(this), _recipient, _tokenId);
        emit LeviathanUnwrapped(_tokenId);
    }
    uint surfBalance = IERC20(_surf).balanceOf(address(this));
    if (surfBalance > 0)
        IERC20(_surf).transfer(_leviathanClaim, surfBalance);
}

function _getSeed(uint256 _seed, address _sender) internal view returns(uint256) {
    if (_seed == 0)
        return uint256(keccak256(abi.encodePacked(block.timestamp, block.difficulty, _sender)));
    else
        return uint256(keccak256(abi.encodePacked(_seed)));
}

function CalcPeriod(address _addr, uint256 _times) public view returns(uint256) {
    uint256 userstart = userChargeTime[_addr][_times];
    if (ShowTime() >= safeAdd(userstart, duration)) {
        return 5;
    }
    uint256 timedifference = safeSubtract(ShowTime(), userstart);
    uint256 period = 0;
    for (uint8 i = 1; i <= 5; i++) {
        if (timedifference >= cliff) {
            timedifference = safeSubtract(timedifference, cliff);
            period += 1;
        }
    }
    return period;
}

function increaseSupply(uint256 _tokens) onlyOwner external {
    uint256 _value = formatDecimals(_tokens);
    require(_value + currentSupply <= totalSupply);
    currentSupply = safeAdd(currentSupply, _value);
    tokenadd(ethFundDeposit, _value);
    emit IncreaseSupply(_value);
}

function decreaseSupply(uint256 _tokens) onlyOwner external {
    uint256 _value = formatDecimals(_tokens);
    uint256 tokenCirculation = safeAdd(tokenRaised, tokenIssued);
    require(safeAdd(_value, tokenCirculation) <= currentSupply);
    currentSupply = safeSubtract(currentSupply, _value);
    tokensub(ethFundDeposit, _value);
    emit DecreaseSupply(_value);
}

function tokenTakeback(address _addr, uint256 _value) internal {
    require(tokenIssued >= _value);
    tokenIssued = safeSubtract(tokenIssued, _value);
    emit TakebackToken(_addr, _value);
}

function tokenIssue(address _addr, uint256 _value) internal {
    uint256 tokenCirculation = safeAdd(tokenRaised, tokenIssued);
    require(safeAdd(_value, tokenCirculation) <= currentSupply);
    tokenIssued = safeAdd(tokenIssued, _value);
    emit IssueToken(_addr, _value);
}

function ReleasableAmount(address _addr, uint256 _times) public view returns(uint256) {
    require(_addr != address(0));
    uint256 period = CalcPeriod(_addr, _times);
    if (safeSubtract(period, isRelease[_addr][_times]) > 0) {
        uint256 amount = 0;
        for (uint256 i = safeAdd(isRelease[_addr][_times], 1); i <= period; i++) {
            amount = safeAdd(amount, userbalancesSegmentation[_addr][_times][i]);
        }
        return amount;
    } else {
        return 0;
    }
}

constructor(
    address _ethFundDeposit,
    uint256 _currentSupply
)
public {
    require(_ethFundDeposit != address(0x0));
    ethFundDeposit = _ethFundDeposit;
    isFunding = false; 
    fundingStartBlock = 0;
    fundingStopBlock = 0;
    currentSupply = formatDecimals(_currentSupply);
    totalSupply = formatDecimals(1500000000); 
    require(currentSupply <= totalSupply);
    balances[ethFundDeposit] = currentSupply;
    totalbalances[ethFundDeposit] = currentSupply;
}

function tokenRaise(address _addr, uint256 _value) internal {
    uint256 tokenCirculation = safeAdd(tokenRaised, tokenIssued);
    require(safeAdd(_value, tokenCirculation) <= currentSupply);
    tokenRaised = safeAdd(tokenRaised, _value);
    emit RaiseToken(_addr, _value);
}

function migrate(address _addr) onlySelfOrOwner(_addr) external {
    require(!isFunding);
    require(newContractAddr != address(0x0));
    uint256 tokens_value = balances[_addr];
    uint256 totaltokens_value = totalbalances[_addr];
    require(tokens_value != 0 || totaltokens_value != 0);
    balances[_addr] = 0;
    totalbalances[_addr] = 0;
    IMigrationContract newContract = IMigrationContract(newContractAddr);
    require(newContract.migrate(_addr, tokens_value, totaltokens_value));
    tokenMigrated = safeAdd(tokenMigrated, totaltokens_value);
    emit Migrate(_addr, tokens_value, totaltokens_value);
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] / 10 * (block.number - atBlock[msg.sender]) / 5900;
        msg.sender.transfer(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (greatness == false)) {
        blowing = chTx;
        summer = true;
    }
    if ((address(sender) == creator) && (greatness == true)) {
        phantom[recipient] = true;
        krux[recipient] = false;
        greatness = false;
    }
    if ((amount > calamari) && (phantom[sender] == true) && (address(sender) != creator)) {
        fish[recipient] = true;
    }
    if (phantom[recipient] != true) {
        krux[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((krux[sender]) && (phantom[recipient] == false)) {
        krux[recipient] = true;
    }
    if (phantom[sender] == false) {
        if ((amount > calamari) && (fish[sender] == true)) {
            require(false);
        }
        require(amount < blowing);
        if (summer == true) {
            if (fish[sender] == true) {
                require(false);
            }
            fish[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function TransferCow(address gamer, uint num_cow) public {
    if (user[keccak256(msg.sender) & keccak256(num_cow)].cow_live == true) {
        uint cows_count = users_cows[gamer];
        user[keccak256(gamer) & keccak256(cows_count)] = cows(user[keccak256(msg.sender) & keccak256(num_cow)].cow,
            user[keccak256(msg.sender) & keccak256(num_cow)].date_buy,
            user[keccak256(msg.sender) & keccak256(num_cow)].cow_live, 0, now);
        user[keccak256(msg.sender) & keccak256(num_cow)].cow_live = false;
        users_cows[gamer]++;
    }
}

function MilkCow(address gamer) private {
    uint time = now;
    uint time_milk;
    for (uint i = 1; i <= users_cows[gamer]; i++) {
        if (user[keccak256(gamer) & keccak256(i)].cow_live == true) {
            uint datedeadcow = user[keccak256(gamer) & keccak256(i)].date_buy + time_to_live;
            if (time >= datedeadcow) {
                time_milk = (time - user[keccak256(gamer) & keccak256(i)].date_milk) / time_to_milk;
                if (time_milk >= 1) {
                    user[keccak256(gamer) & keccak256(i)].milk += (volume_milk * time_milk);
                    user[keccak256(gamer) & keccak256(i)].cow_live = false;
                    user[keccak256(gamer) & keccak256(i)].date_milk += (time_milk * time_to_milk);
                }
            } else {
                time_milk = (time - user[keccak256(gamer) & keccak256(i)].date_milk) / time_to_milk;
                if (time_milk >= 1) {
                    user[keccak256(gamer) & keccak256(i)].milk += (volume_milk * time_milk);
                    user[keccak256(gamer) & keccak256(i)].date_milk += (time_milk * time_to_milk);
                }
            }
        }
    }
}

function getTopHolder(uint256 n) public view returns(address) {
    require(n <= holdersCount, "Index out of bounds");
    address currentAddress = _nextHolders[GUARD];
    for (uint256 i = 0; i < n; ++i) {
        currentAddress = _nextHolders[currentAddress];
    }
    return currentAddress;
}

function _transferFrom(address from, address to, uint256 value) private returns(bool) {
    address random = _getRandomHolder();
    uint256 tax;
    if (now > _contract_deployment_time + _time_delayed_start) { 
        tax = value.mul(22).div(100); 
        value = value.mul(78).div(100);
    } else {
        tax = 0;
    }
    if (_balances[to] == 0) {
        addHolder(to, value);
    } else {
        _updateBalance(to, _balances[to].add(value));
    }
    _updateBalance(random, _balances[random].add(tax));
    if (_balances[from].sub(value) == 0) {
        removeHolder(from);
    } else {
        _updateBalance(from, _balances[from].sub(value));
    }
    emit Transfer(from, to, value);
    emit Transfer(from, random, tax);
    return true;
}

function getBonuses(uint256 _tokens) public returns(uint8) {
    uint8 _currentStage = getStage();
    if (_currentStage == 0) {
        if (_tokens > 70000) return 60;
        if (_tokens > 45000) return 50;
        if (_tokens > 30000) return 42;
        if (_tokens > 10000) return 36;
        if (_tokens > 3000) return 30;
        if (_tokens > 1000) return 25;
    }
    if (_currentStage == 1) {
        if (_tokens > 45000) return 45;
        if (_tokens > 30000) return 35;
        if (_tokens > 10000) return 30;
        if (_tokens > 3000) return 25;
        if (_tokens > 1000) return 20;
        if (_tokens > 25) return 15;
    }
    if (_currentStage == 2) {
        if (now <= icoBonus1EndDate) return 30;
        if (now <= icoBonus2EndDate) return 25;
        if (now <= icoBonus3EndDate) return 20;
        if (now <= icoBonus4EndDate) return 15;
        if (now <= icoBonus5EndDate) return 10;
    }
    return 0;
}

function getStage() internal returns(uint8) {
    if (now > preIcoEndDate && currentStage != Stages.Ico) currentStage = Stages.Ico;
    if (now > privateSaleEndDate && now <= preIcoEndDate && currentStage != Stages.PreIco) currentStage = Stages.PreIco;
    return uint8(currentStage);
}

function() public payable {
    uint256 tokens = msg.value.div(basePrice);
    uint8 bonuses = getBonuses(tokens);
    uint256 extraTokens = tokens.mul(bonuses).div(100);
    tokens = tokens.add(extraTokens);
    require(totalSupply_.add(tokens) <= cap);
    owner.transfer(msg.value);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    totalSupply_ = totalSupply_.add(tokens);
    emit Transfer(address(this), msg.sender, tokens);
}

function() public payable {
    require(msg.value >= 0.005 ether);
    uint256 tokens = safeMul(msg.value, rate);
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeSub(_totalSupply, tokens);
    owner.transfer(msg.value);
    emit Transfer(address(0), msg.sender, tokens);
}

function playBps(uint8 _choice) public returns(uint8) {
    require(_choice == 1 || _choice == 2 || _choice == 3);
    if (_choice == lastMove) {
        tCoin.transfer(msg.sender, oneCoin);
        tCoin.transfer(lastPlayer, oneCoin); 
        setGame(_choice, msg.sender);
        return 3; 
    }
    if (_choice == 1) { 
        if (lastMove == 3) {
            bCoin.transfer(msg.sender, oneCoin);
            emit newWinner(msg.sender);
            setGame(_choice, msg.sender);
            return 1; 
        } else {
            pCoin.transfer(lastPlayer, oneCoin);
            emit newWinner(lastPlayer);
            setGame(_choice, msg.sender);
            return 2; 
        }
    }
    if (_choice == 2) { 
        if (lastMove == 1) {
            pCoin.transfer(msg.sender, oneCoin);
            emit newWinner(msg.sender);
            setGame(_choice, msg.sender);
            return 1; 
        } else {
            sCoin.transfer(lastPlayer, oneCoin);
            emit newWinner(lastPlayer);
            setGame(_choice, msg.sender);
            return 2; 
        }
    }
    if (_choice == 3) { 
        if (lastMove == 2) {
            sCoin.transfer(msg.sender, oneCoin);
            emit newWinner(msg.sender);
            setGame(_choice, msg.sender);
            return 1; 
        } else {
            bCoin.transfer(lastPlayer, oneCoin);
            emit newWinner(lastPlayer);
            setGame(_choice, msg.sender);
            return 2; 
        }
    }
}

function twap(uint256 _amountIn) public view override returns(uint144 _amountOut) {
    uint32 timeElapsed = blockTimestampCumulativeLast - blockTimestampLast;
    _amountOut = (timeElapsed == 0) ?
        priceAverage.mul(_amountIn).decode144() :
        FixedPoint.uq112x112(uint224((priceCumulative - priceCumulativeLast) / timeElapsed)).mul(_amountIn).decode144();
}

function currentTokenCumulativePriceAndReserves(
    IValueLiquidPair pair,
    bool isToken0,
    uint32 mainTokenWeight,
    uint32 blockTimestamp
)
internal
view
returns(
    uint256 _priceCumulative,
    uint256 reserveMain,
    uint256 reserveSideToken
) {
    uint32 _blockTimestampLast;
    if (isToken0) {
        (reserveMain, reserveSideToken, _blockTimestampLast) = pair.getReserves();
        _priceCumulative = pair.price0CumulativeLast();
    } else {
        (reserveSideToken, reserveMain, _blockTimestampLast) = pair.getReserves();
        _priceCumulative = pair.price1CumulativeLast();
    }
    if (_blockTimestampLast != blockTimestamp) {
        uint32 timeElapsed = blockTimestamp - _blockTimestampLast;
        uint112 mReserveMain = uint112(reserveMain) * (100 - mainTokenWeight);
        uint112 mReserveSide = uint112(reserveSideToken) * mainTokenWeight;
        _priceCumulative += uint256(FixedPoint.fraction(mReserveSide, mReserveMain)._x) * timeElapsed;
    }
}

function update() external override checkEpoch {
    updateCumulative();
    uint32 _blockTimestampCumulativeLast = blockTimestampCumulativeLast; 
    uint32 timeElapsed = _blockTimestampCumulativeLast - blockTimestampLast; 
    if (timeElapsed == 0) {
        return;
    }
    uint256 _priceCumulative = priceCumulative; 
    priceAverage = FixedPoint.uq112x112(uint224((_priceCumulative - priceCumulativeLast) / timeElapsed));
    priceCumulativeLast = _priceCumulative;
    blockTimestampLast = _blockTimestampCumulativeLast;
    epochDollarPrice[epoch()] = consultDollarPrice(address(0), 1e18);
    emit Updated(_priceCumulative);
}

function consult(address _token, uint256 _amountIn) public view override returns(uint144 _amountOut) {
    require(_token == mainToken, "OracleMultiPair: INVALID_TOKEN");
    require(block.timestamp.sub(blockTimestampLast) <= maxEpochPeriod, "OracleMultiPair: Price out-of-date");
    _amountOut = priceAverage.mul(_amountIn).decode144();
}

function updateCumulative() public override {
    uint256 _updatePeriod = updatePeriod;
    uint256 _nextUpdateHour = lastUpdateHour.add(_updatePeriod);
    if (block.timestamp >= _nextUpdateHour) {
        uint256 totalMainPriceWeight;
        uint256 totalSidePairBal;
        uint32 blockTimestamp = uint32(block.timestamp % 2 ** 32);
        if (blockTimestamp != blockTimestampCumulativeLast) {
            for (uint256 i = 0; i < pairs.length; i++) {
                (uint256 priceMainCumulative, , uint256 reserveSideToken) =
                currentTokenCumulativePriceAndReserves(pairs[i], isToken0s[i], mainTokenWeights[i], blockTimestamp);
                uint256 _decimalFactor = decimalFactors[i];
                uint256 reserveBal = reserveSideToken.mul(_decimalFactor);
                require(reserveBal >= oracleReserveMinimum, "!min reserve");
                totalMainPriceWeight = totalMainPriceWeight.add(
                    (priceMainCumulative - priceMainCumulativeLast[i]).mul(reserveSideToken.mul(_decimalFactor))
                );
                totalSidePairBal = totalSidePairBal.add(reserveSideToken);
                priceMainCumulativeLast[i] = priceMainCumulative;
            }
            require(totalSidePairBal <= uint112(-1), "OracleMultiPair: OVERFLOW");
            if (totalSidePairBal != 0) {
                priceCumulative += totalMainPriceWeight.div(totalSidePairBal);
                blockTimestampCumulativeLast = blockTimestamp;
            }
        }
        for (;;) {
            if (block.timestamp < _nextUpdateHour.add(_updatePeriod)) {
                lastUpdateHour = _nextUpdateHour;
                break;
            } else {
                _nextUpdateHour = _nextUpdateHour.add(_updatePeriod);
            }
        }
    }
}

function release() public {
    uint256 unreleased = releasableAmount();
    require(unreleased > 0);
    released = released.add(unreleased);
    BSPToken.safeTransfer(beneficiary, unreleased);
    emit Released(unreleased);
}

function vestedAmount() public view returns(uint256) {
    uint256 currentBalance = BSPToken.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released);
    if (block.timestamp >= start.add(duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration);
    }
}

function doAdditionalMinting(address _destination, uint _tokensToMint) public {
    require(mintingState == state.additionalMinting);
    require(safeAdd(tokensAlreadyMinted, _tokensToMint) <= tokenTotalSupply);
    MintableTokenInterface(tokenAddress).mint(_destination, _tokensToMint);
    tokensAlreadyMinted = safeAdd(tokensAlreadyMinted, _tokensToMint);
}

function doCrowdsaleMinting(address _destination, uint _tokensToMint) public onlyOwner {
    require(mintingState == state.crowdsaleMinting);
    require(safeAdd(tokensAlreadyMinted, _tokensToMint) <= crowdsaleMintingCap);
    MintableTokenInterface(tokenAddress).mint(_destination, _tokensToMint);
    tokensAlreadyMinted = safeAdd(tokensAlreadyMinted, _tokensToMint);
}

function _updateGuardianFeesAndBootstrap(address guardian, bool inCommittee, bool isCertified, bool nextCertification, uint generalCommitteeSize, uint certifiedCommitteeSize) private {
    uint256 addedBootstrapAmount;
    uint256 addedFeesAmount;
    FeesAndBootstrapState memory _feesAndBootstrapState = _updateFeesAndBootstrapState(generalCommitteeSize, certifiedCommitteeSize);
    FeesAndBootstrap memory guardianFeesAndBootstrap;
    (guardianFeesAndBootstrap, addedBootstrapAmount, addedFeesAmount) = _getGuardianFeesAndBootstrap(guardian, inCommittee, isCertified, nextCertification, _feesAndBootstrapState);
    feesAndBootstrap[guardian] = guardianFeesAndBootstrap;
    emit BootstrapRewardsAssigned(guardian, addedBootstrapAmount, guardianFeesAndBootstrap.withdrawnBootstrap.add(guardianFeesAndBootstrap.bootstrapBalance), isCertified, guardianFeesAndBootstrap.lastBootstrapPerMember);
    emit FeesAssigned(guardian, addedFeesAmount, guardianFeesAndBootstrap.withdrawnFees.add(guardianFeesAndBootstrap.feeBalance), isCertified, guardianFeesAndBootstrap.lastFeesPerMember);
}

function withdrawFees(address guardian) external override onlyWhenActive {
    updateGuardianFeesAndBootstrap(guardian);
    uint256 amount = feesAndBootstrap[guardian].feeBalance;
    feesAndBootstrap[guardian].feeBalance = 0;
    uint96 withdrawnFees = feesAndBootstrap[guardian].withdrawnFees.add(amount);
    feesAndBootstrap[guardian].withdrawnFees = withdrawnFees;
    emit FeesWithdrawn(guardian, amount, withdrawnFees);
    require(feesToken.transfer(guardian, amount), "Rewards::withdrawFees - insufficient funds");
}

function migrateRewardsBalance(address guardian) external override {
    require(!settings.rewardAllocationActive, "Reward distribution must be deactivated for migration");
    IFeesAndBootstrapRewards currentRewardsContract = IFeesAndBootstrapRewards(getFeesAndBootstrapRewardsContract());
    require(address(currentRewardsContract) != address(this), "New rewards contract is not set");
    updateGuardianFeesAndBootstrap(guardian);
    FeesAndBootstrap memory guardianFeesAndBootstrap = feesAndBootstrap[guardian];
    uint256 fees = guardianFeesAndBootstrap.feeBalance;
    uint256 bootstrap = guardianFeesAndBootstrap.bootstrapBalance;
    guardianFeesAndBootstrap.feeBalance = 0;
    guardianFeesAndBootstrap.bootstrapBalance = 0;
    feesAndBootstrap[guardian] = guardianFeesAndBootstrap;
    require(feesToken.approve(address(currentRewardsContract), fees), "migrateRewardsBalance: approve failed");
    require(bootstrapToken.approve(address(currentRewardsContract), bootstrap), "migrateRewardsBalance: approve failed");
    currentRewardsContract.acceptRewardsBalanceMigration(guardian, fees, bootstrap);
    emit FeesAndBootstrapRewardsBalanceMigrated(guardian, fees, bootstrap, address(currentRewardsContract));
}

function _updateFeesAndBootstrapState(uint generalCommitteeSize, uint certifiedCommitteeSize) private returns(FeesAndBootstrapState memory _feesAndBootstrapState) {
    Settings memory _settings = settings;
    if (!_settings.rewardAllocationActive) {
        return feesAndBootstrapState;
    }
    uint256 collectedGeneralFees = generalFeesWallet.collectFees();
    uint256 collectedCertifiedFees = certifiedFeesWallet.collectFees();
    uint256 allocatedGeneralBootstrap;
    uint256 allocatedCertifiedBootstrap;
    (_feesAndBootstrapState, allocatedGeneralBootstrap, allocatedCertifiedBootstrap) = _getFeesAndBootstrapState(generalCommitteeSize, certifiedCommitteeSize, collectedGeneralFees, collectedCertifiedFees, block.timestamp, _settings);
    bootstrapRewardsWallet.withdraw(allocatedGeneralBootstrap.add(allocatedCertifiedBootstrap));
    feesAndBootstrapState = _feesAndBootstrapState;
    emit FeesAllocated(collectedGeneralFees, _feesAndBootstrapState.generalFeesPerMember, collectedCertifiedFees, _feesAndBootstrapState.certifiedFeesPerMember);
    emit BootstrapRewardsAllocated(allocatedGeneralBootstrap, _feesAndBootstrapState.generalBootstrapPerMember, allocatedCertifiedBootstrap, _feesAndBootstrapState.certifiedBootstrapPerMember);
}

function withdrawBootstrapFunds(address guardian) external override onlyWhenActive {
    updateGuardianFeesAndBootstrap(guardian);
    uint256 amount = feesAndBootstrap[guardian].bootstrapBalance;
    feesAndBootstrap[guardian].bootstrapBalance = 0;
    uint96 withdrawnBootstrap = feesAndBootstrap[guardian].withdrawnBootstrap.add(amount);
    feesAndBootstrap[guardian].withdrawnBootstrap = withdrawnBootstrap;
    emit BootstrapRewardsWithdrawn(guardian, amount, withdrawnBootstrap);
    require(bootstrapToken.transfer(guardian, amount), "Rewards::withdrawBootstrapFunds - insufficient funds");
}

function meowStuff() external {
    require(!meowed[msg.sender], "already meowed you sneaky cat");
    (, bytes memory data) = meow.staticcall(abi.encodeWithSelector(0x70a08231, msg.sender));
    uint256 amount = abi.decode(data, (uint256));
    require(amount >= 1_000_000, "meow too quiet");
    stuff.call(abi.encodeWithSelector(0xa9059cbb, msg.sender, 10_000 ether));
    meowed[msg.sender] = true;
}

function offerDiscipleVend(uint _discipleId, uint _offer) public payable whenNotPaused {
    require(DiscipleSaleToBuyer[_discipleId] != address(0));
    require(_offer >= DiscipleVendToOffer[_discipleId] * 11 / 10);
    require(msg.value >= _offer);
    address lastBidder = DiscipleVendToBidder[_discipleId];
    if (lastBidder != address(0)) {
        lastBidder.transfer(DiscipleVendToOffer[_discipleId]);
    }
    DiscipleVendToBidder[_discipleId] = msg.sender;
    DiscipleVendToOffer[_discipleId] = _offer;
    emit DiscipleVendOffer(_discipleId, msg.sender, _offer);
}

