        GuardianSaleToBuyer[_guardianId] = msg.sender;
        GuardianVendToOffer[_guardianId] = GuardianVending[2];
    } else if (_guardianId > 4000 && _guardianId <= 5000) {
        require(GuardianSaleToBuyer[_guardianId] == address(0));
