function closeSession(uint _priceClose)
public
onlyEscrow {
    require(_priceClose != 0 && now > (session.timeOpen + timeOneSession * 1 minutes));
    require(!session.investOpen && session.isOpen);
    session.priceClose = _priceClose;
    bool result = (_priceClose > session.priceOpen) ? true : false;
    uint etherToBuy;
    NamiCrowdSale namiContract = NamiCrowdSale(namiCrowdSaleAddr);
    uint price = namiContract.getPrice();
    for (uint i = 0; i < session.investorCount; i++) {
        if (session.win[i] == result) {
            etherToBuy = getEtherToBuy(session.amountInvest[i], rate, true);
        } else {
            etherToBuy = getEtherToBuy(session.amountInvest[i], rate, false);
        }
        namiContract.buy.value(etherToBuy)(session.investor[i]);
        session.investor[i] = 0x0;
        session.win[i] = false;
        session.amountInvest[i] = 0;
    }
    session.isOpen = false;
    SessionClose(now, sessionId, _priceClose, price, rate);
    sessionId += 1;
    session.priceOpen = 0;
    session.priceClose = 0;
    session.isReset = true;
    session.investOpen = false;
    session.investorCount = 0;
}

function changeRate(uint _rate)
public
onlyEscrow {
    require(100 < _rate && _rate < 200 && !session.isOpen);
    rate = _rate;
}

function getLockedAmount(
    address _granted
)
public
view
returns(uint256) {
    uint256 lockedAmount = 0;
    Lock[] storage locks = grantedLocks[_granted];
    for (uint i = 0; i < locks.length; i++) {
        if (now < locks[i].expiresAt) {
            lockedAmount = lockedAmount.add(locks[i].amount);
        }
    }
    return lockedAmount;
}

function addLock(
    address _granted,
    uint256 _amount,
    uint256 _expiresAt
)
public
onlyOwner {
    require(_amount > 0);
    require(_expiresAt > now);
    grantedLocks[_granted].push(Lock(_amount, _expiresAt));
}

function mintTokensForCrowdsaleParticipants(address[] investorsAddress, uint256[] amountOfTokens)
external
onlyOwner {
    require(investorsAddress.length == amountOfTokens.length);
    for (uint256 i = 0; i < investorsAddress.length; i++) {
        require(token.totalSupply().add(amountOfTokens[i]) <= TOTAL_TOKENS_FOR_CROWDSALE);
        token.mint(investorsAddress[i], amountOfTokens[i]);
        icoContributions[investorsAddress[i]] = icoContributions[investorsAddress[i]].add(amountOfTokens[i]);
        emit MintedTokensFor(investorsAddress[i], amountOfTokens[i]);
    }
}

function finalization() internal {
    require(teamVestTokenAllocation != address(0) && contributorsVestTokenAllocation != address(0));
    if (TOTAL_TOKENS_FOR_CROWDSALE > token.totalSupply()) {
        uint256 remainingTokens = TOTAL_TOKENS_FOR_CROWDSALE.sub(token.totalSupply());
        token.mint(contributorsVestTokenAllocation, remainingTokens);
        isStakingPeriod = true;
    }
    token.mint(marketingWallet, MARKETING_SHARE);
    token.mint(shareHoldersWallet, SHAREHOLDERS_SHARE);
    token.mint(teamVestTokenAllocation, FOUNDERS_SHARE);
    token.finishMinting();
    GolixToken(token).unpause();
    super.finalization();
}

function batchTransfer(address[] _recipients, uint _tokens) onlyOwner returns(bool) {
    require(_recipients.length > 0);
    uint total = 0;
    require(total <= balances[msg.sender]);
    uint64 _now = uint64(now);
    for (uint j = 0; j < _recipients.length; j++) {
        balances[_recipients[j]] = safeAdd(balances[_recipients[j]], _tokens);
        balances[owner] = safeSub(balances[owner], _tokens);
        Transfer(owner, _recipients[j], _tokens);
    }
    return true;
}

function unlockTokens(TokenLock lock) internal returns(bool) {
    uint lockReleaseTime = lock.start + lock.duration;
    if (lockReleaseTime < now && lock.amountWithDrawn < lock.totalAmount) {
        if (lock.withdrawSteps > 1) {
            _tokens = safeDiv(lock.totalAmount, lock.withdrawSteps);
        } else {
            _tokens = safeSub(lock.totalAmount, lock.amountWithDrawn);
        }
        if (lock.id == 1 && lock.amountWithDrawn < lock.totalAmount) {
            futureLock.amountWithDrawn = safeAdd(futureLock.amountWithDrawn, _tokens);
        }
        balances[owner] = safeAdd(balances[owner], _tokens);
        balances[address(0)] = safeSub(balances[address(0)], _tokens);
        Transfer(address(0), owner, _tokens);
        return true;
    }
    return false;
}

function manualDeposit(address _depositer, uint amountToDeposit, uint _time, uint _claimTime, uint _divPoints) public onlyOwner {
    require(amountToDeposit > 0, "Cannot deposit 0 Tokens");
    require(Token(trustedDepositTokenAddress).transferFrom(msg.sender, address(this), amountToDeposit), "Insufficient Token Allowance");
    depositedTokens[_depositer] = depositedTokens[_depositer].add(amountToDeposit);
    totalTokens = totalTokens.add(amountToDeposit);
    lastClaimedTime[_depositer] = _claimTime;
    lastDivPoints[_depositer] = _divPoints;
    if (!holders.contains(_depositer)) {
        holders.add(_depositer);
        depositTime[_depositer] = _time;
    }
}

