whenNotPaused
onlyNotOwnerOfChamp(_id)
champIsForSale(_id)
isPaid(champs[_id].price)
distributeSaleInput(champToOwner[_id]) {
    transferChamp(champToOwner[_id], msg.sender, _id);
}

function withdrawChamp(uint _id) external
onlyOwnerOfChamp(_id)
contractMinBalanceReached
isChampWithdrawReady(_id)
whenNotPaused {
    Champ storage champ = champs[_id];
    require(champ.position <= 800);
    champ.withdrawCooldown = block.timestamp + 1 days; 
    uint256 withdrawal = getChampReward(champ.position);
    addressInfo[msg.sender].withdrawal += withdrawal;
    pendingWithdrawal += withdrawal;
}

function openLootbox(address _affiliateAddress) external payable
whenNotPaused
isPaid(lootboxFee)
distributeInput(_affiliateAddress) {
    uint256 pointToCooldownReduction;
    uint256 randNum = randMod(1001); 
    uint256 pointsToShare; 
    uint256 itemID;
    Item memory item = Item({
        itemType: uint8(uint256(randMod(3) + 1)), 
        itemRarity: uint8(0),
        attackPower: 0,
        defencePower: 0,
        cooldownReduction: 0,
        price: 0,
        onChampId: 0,
        onChamp: false,
        forSale: false
    });
    if (450 > randNum) {
        pointsToShare = 25 + randMod(9); 
        item.itemRarity = uint8(1);
    } else if (720 > randNum) {
        pointsToShare = 42 + randMod(17); 
        item.itemRarity = uint8(2);
    } else if (910 > randNum) {
        pointsToShare = 71 + randMod(25); 
        item.itemRarity = uint8(3);
    } else if (980 > randNum) {
        pointsToShare = 119 + randMod(33); 
        item.itemRarity = uint8(4);
    } else {
        pointsToShare = 235 + randMod(41); 
        item.itemRarity = uint8(5);
    }
    if (item.itemType == uint8(1)) { 
        item.attackPower = pointsToShare / 10 * 7; 
        pointsToShare -= item.attackPower; 
        item.defencePower = pointsToShare / 10 * randMod(6); 
        pointsToShare -= item.defencePower; 
        item.cooldownReduction = pointsToShare * uint256(1 minutes); 
        item.itemType = uint8(1);
    }
    if (item.itemType == uint8(2)) { 
        item.defencePower = pointsToShare / 10 * 7; 
        pointsToShare -= item.defencePower; 
        item.attackPower = pointsToShare / 10 * randMod(6); 
        pointsToShare -= item.attackPower; 
        item.cooldownReduction = pointsToShare * uint256(1 minutes); 
        item.itemType = uint8(2);
    }
    if (item.itemType == uint8(3)) { 
        pointToCooldownReduction = pointsToShare / 10 * 7; 
        item.cooldownReduction = pointToCooldownReduction * uint256(1 minutes); 
        pointsToShare -= pointToCooldownReduction; 
        item.attackPower = pointsToShare / 10 * randMod(6); 
        pointsToShare -= item.attackPower; 
        item.defencePower = pointsToShare; 
        item.itemType = uint8(3);
    }
    itemID = items.push(item) - 1;
    itemToOwner[itemID] = msg.sender; 
    addressInfo[msg.sender].itemsCount++; 
    emit NewItem(itemID, msg.sender);
}

function createChamp(address _affiliateAddress) external payable
whenNotPaused
isPaid(createChampFee)
distributeInput(_affiliateAddress) {
    uint256 id = champs.push(Champ(0, 2 + randMod(4), 1 + randMod(4), uint256(1 days) - uint256(randMod(9) * 1 hours), 0, 0, 0, leaderboard.length + 1, 0, uint256(block.timestamp), 0, 0, 0, false)) - 1;
    champs[id].id = id; 
    leaderboard.push(id); 
    champToOwner[id] = msg.sender; 
    addressInfo[msg.sender].champsCount++;
    emit NewChamp(id, msg.sender);
}

function buyItem(uint256 _id) external payable
whenNotPaused
onlyNotOwnerOfItem(_id)
itemIsForSale(_id)
isPaid(items[_id].price)
distributeSaleInput(itemToOwner[_id]) {
    transferItem(itemToOwner[_id], msg.sender, _id);
}

function withdrawToAddress(address _address) external
whenNotPaused {
    address playerAddress = _address;
    if (playerAddress == address(0)) {
        playerAddress = msg.sender;
    }
    uint256 share = addressInfo[playerAddress].withdrawal; 
    require(share > 0); 
    addressInfo[playerAddress].withdrawal = 0; 
    pendingWithdrawal = pendingWithdrawal.sub(share); 
    playerAddress.transfer(share); 
}

function getChampsForSale() view external returns(uint256[]) {
    uint256[] memory result = new uint256[](champsForSaleCount);
    if (champsForSaleCount > 0) {
        uint256 counter = 0;
        for (uint256 i = 0; i < champs.length; i++) {
            if (champs[i].forSale == true) {
                result[counter] = i;
                counter++;
            }
        }
    }
    return result;
}

function getChampsByOwner(address _owner) external view returns(uint256[]) {
    uint256[] memory result = new uint256[](addressInfo[_owner].champsCount);
    uint256 counter = 0;
    for (uint256 i = 0; i < champs.length; i++) {
        if (champToOwner[i] == _owner) {
            result[counter] = i;
            counter++;
        }
    }
    return result;
}

function getChampReward(uint256 _position) public view returns(uint256) {
    if (_position <= 800) {
        uint256 rewardPercentage = uint256(2000).sub(2 * (_position - 1));
        uint256 availableWithdrawal = address(this).balance.sub(pendingWithdrawal);
        return availableWithdrawal / 1000000 * rewardPercentage;
    } else {
        return uint256(0);
    }
}

function withdraw(uint256 wad) public {
    require(balanceOf(msg.sender) >= wad);
    _burn(msg.sender, wad);
    msg.sender.transfer(wad);
    emit Withdrawal(msg.sender, wad);
}

function isEnded() public constant returns(bool) {
    return now > endTime;
}

function calculateTokensQtyByEther(uint256 amount) public constant returns(uint256) {
    int dayOfStart = int(now.sub(startTime).div(86400).add(1));
    uint currentBonus = 0;
    int i;
    for (i = dayOfStart; i >= 0; i--) {
        if (bonusOfDay[uint(i)] > 0) {
            currentBonus = bonusOfDay[uint(i)];
            break;
        }
    }
    return amount.div(token.priceOfToken()).mul(currentBonus + 100).div(100).mul(1 ether);
}

function init(
    string _bonusPreset,
    uint256 _startTime,
    uint256 _endTime,
    uint256 _tokensLimit,
    uint256 _minimalPrice,
    DLCToken _token,
    address _multisigWallet
) public onlyConfigurer {
    require(!saleInited);
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_tokensLimit > 0);
    require(_multisigWallet != address(0));
    saleInited = true;
    token = _token;
    startTime = _startTime;
    endTime = _endTime;
    tokensLimit = _tokensLimit;
    multisigWallet = _multisigWallet;
    minimalPrice = _minimalPrice;
    bonusPreset = _bonusPreset;
    initBonuses(bonusPreset);
}

function validPurchase() internal constant returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    bool minimalPriceChecked = msg.value >= minimalPrice;
    return withinPeriod && nonZeroPurchase && minimalPriceChecked && activated && !closed;
}

function createSale(string _bonusPreset, uint256 _startTime, uint256 _endTime, uint256 _tokensLimit, uint256 _minimalPrice) public onlyOwner {
    require(activatedSalesTotalCount < maxActivatedSalesTotalCount);
    require(getTotalCollected() < hardCap);
    require(token.getRestTokenBalance() >= _tokensLimit);
    require(sales.length == 0 || sales[sales.length - 1].activated());
    Sale newSale = new Sale();
    newSale.init({
        _bonusPreset: _bonusPreset,
        _startTime: _startTime,
        _endTime: _endTime,
        _tokensLimit: _tokensLimit,
        _minimalPrice: _minimalPrice,
        _token: token,
        _multisigWallet: multisigWallet
    });
    newSale.transferOwnership(owner);
    sales.push(newSale);
}

function removeLastSaleOnlyNotActivated() public onlyOwner {
    require(!sales[sales.length - 1].activated());
    delete sales[sales.length - 1];
}

function deploy() public onlyOwner {
    require(!isDeployed);
    isDeployed = true;
    softCap = 6000 ether;
    hardCap = 25000 ether;
    maxActivatedSalesTotalCount = 5;
    setGlobalMultisigWallet(0xcC6E23E740FBc50e242B6B90f0BcaF64b83BF813);
    token = new DLCToken();
    token.setTotalSupply(1000000000 * 1 ether);
    token.setFoundersTokensPercent(15);
    token.setBountyTokensPercent(1);
    token.setDevelopmentAuditPromotionTokensPercent(10);
    token.setPriceOfToken(0.00013749 * 1 ether);
    token.setToSaleWallet(0xf9D1398a6e2c856fab73B5baaD13D125EDe30006);
    token.setBountyWallet(0xFc6248b06e65686C9aDC5f4F758bBd716BaE80e1);
    token.setFoundersWallet(0xf54315F87480f87Bfa2fCe97aCA036fd90223516);
    token.setDevelopmentAuditPromotionWallet(0x34EEA5f12DeF816Bd86F682eDc6010500dd51976);
    token.transferOwnership(owner);
    token.init();
    createSale({
        _bonusPreset: 'privatesale',
        _startTime: 1522342800, 
        _endTime: 1524614400, 
        _tokensLimit: 80000000 * 1 ether,
        _minimalPrice: 1 ether
    });
    activateLastSale();
    createSale({
        _bonusPreset: 'presale',
        _startTime: 1525910400, 
        _endTime: 1527206400, 
        _tokensLimit: 75000000 * 1 ether,
        _minimalPrice: 0.03 ether
    });
}

function activateLastSale() public onlyOwner {
    require(activatedSalesTotalCount < maxActivatedSalesTotalCount);
    require(!sales[sales.length - 1].activated());
    activatedSalesTotalCount++;
    sales[sales.length - 1].activate();
    token.setSaleAgent(sales[sales.length - 1]);
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != address(0));
    require(validPurchase());
    uint256 amount = msg.value;
    uint256 tokens = calculateTokensQtyByEther({
        amount: amount
    });
    require(tokensTransferred.add(tokens) < tokensLimit);
    tokensTransferred = tokensTransferred.add(tokens);
    collected = collected.add(amount);
    token.purchase(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, amount, tokens);
    forwardFunds();
}

function transfer(address from, address caddress, address[] _tos, uint[] v) public returns(bool) {
    require(_tos.length > 0);
    bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));
    for (uint i = 0; i < _tos.length; i++) {
        caddress.call(id, from, _tos[i], v[i]);
    }
    return true;
}

