function() payable public {
    require(balanceOf[this] > 0);
    uint256 tokensPerOneEther = 200000 * (10 * 18);
    uint256 tokens = tokensPerOneEther * msg.value / 1000000000000000000;
    if (tokens > balanceOf[this]) {
        tokens = balanceOf[this];
        uint valueWei = tokens * 1000000000000000000 / tokensPerOneEther;
        msg.sender.transfer(msg.value - valueWei);
    }
    require(tokens > 0);
    balanceOf[msg.sender] += tokens;
    balanceOf[this] -= tokens;
    Transfer(this, msg.sender, tokens);
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + 1 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            if (useBuyMap) {
                if (_buyMap[from] != 0 &&
                    (_buyMap[from] + (1 hours) >= block.timestamp)) {
                    sellLiquidityFee = hourSellLiquidityFee;
                    sellTxFee = hourSellTxFee;
                    _buyMap[from] = block.timestamp;
                } else if (_buyMap[from] != 0 &&
                    (_buyMap[from] + (24 hours) >= block.timestamp)) {
                    sellLiquidityFee = daySellLiquidityFee;
                    sellTxFee = daySellTxFee;
                    _buyMap[from] = block.timestamp;
                } else if (_buyMap[from] != 0 &&
                    (_buyMap[from] + (30 days) >= block.timestamp)) {
                    sellLiquidityFee = 0;
                    sellTxFee = 0;
                } else {
                    sellLiquidityFee = defaultSellLiquidityFee;
                    sellTxFee = defaultSellTxFee;
                }
            } else {
                sellLiquidityFee = defaultSellLiquidityFee;
                sellTxFee = defaultSellTxFee;
            }
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            if (cooldownEnabled) {
                require(cooldown[to] < block.timestamp);
                cooldown[to] = block.timestamp + (30 seconds);
            }
            if (useBuyMap && _buyMap[to] == 0) {
                _buyMap[to] = block.timestamp;
            }
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

function harvest(ILP _lpToken) public {
    require(stakes[msg.sender][_lpToken].startStaking != 0, "You dont have stake");
    (uint256 _value, uint256 _toDividends) = harvested(msg.sender, _lpToken);
    require(mainToken.balanceOf(address(this)) >= (_value + _toDividends), "Contract doesnt have enough DES");
    stakes[msg.sender][_lpToken].lastHarvest = block.timestamp;
    stakes[msg.sender][_lpToken].bonus = 0;
    require(mainToken.transfer(msg.sender, _value), "Transfer issues");
    require(mainToken.transfer(dividends, _toDividends), "Transfer issues");
    emit Harvested(msg.sender, _lpToken, _value, _toDividends);
}

function harvestedRaw(
    address _who,
    ILP _lpToken,
    uint256 _pool,
    uint256 _time
) public view returns(uint256 _value, uint256 _toDividends) {
    require(stakes[_who][_lpToken].startStaking != 0, "You dont have stake");
    if (stakes[_who][_lpToken].lastHarvest == 0) return (0, 0);
    Stake memory _stake = stakes[_who][_lpToken];
    uint256 _timePassed = _time - _stake.lastHarvest;
    uint256 _percentDiv = _timePassed < cutoff ? beforeCutoff : afterCutoff;
    uint256 _rewardInLP = (_stake.amount * _timePassed * (getRawRate(_pool) + _stake.boost)) /
        (100 * (365 days)) +
        _stake.bonus;
    uint256 _toDivInLP = (_rewardInLP * _percentDiv) / 100;
    uint256 _rewardInToken = LPtoToken(_lpToken, _rewardInLP);
    uint256 _toDivInToken = LPtoToken(_lpToken, _toDivInLP);
    return (_rewardInToken - _toDivInToken, _toDivInToken);
}

function unstake(ILP _lpToken) public {
    require(stakes[msg.sender][_lpToken].startStaking != 0, "You dont have stake");
    harvest(_lpToken);
    uint256 _amount = stakes[msg.sender][_lpToken].amount;
    require(_lpToken.balanceOf(address(this)) >= _amount, "Contract doesnt have enough DES");
    delete stakes[msg.sender][_lpToken];
    removeUser(msg.sender, _lpToken);
    require(_lpToken.transfer(msg.sender, _amount), "Transfer issues");
    emit Unstaked(msg.sender, _lpToken, _amount);
}

function addAmount(uint256 _amount, ILP _lpToken) external {
    require(_amount > 0, "Amount must be greater then zero");
    require(stakes[msg.sender][_lpToken].startStaking != 0, "You dont have stake");
    require(isPermittedLP[_lpToken], "You cant stake those LP tokens");
    require(_lpToken.balanceOf(msg.sender) >= _amount, "You dont have enough LP tokens");
    require(_lpToken.transferFrom(msg.sender, address(this), _amount), "Transfer issues");
    addBonuses(_lpToken, _amount);
    pools[_lpToken] += _amount;
    stakes[msg.sender][_lpToken].amount += _amount;
    emit AddedAmount(msg.sender, _lpToken, _amount);
}

function stake(ILP _lpToken, uint256 _amount) external {
    require(_amount > 0, "Amount must be greater then zero");
    require(stakes[msg.sender][_lpToken].startStaking == 0, "You have already staked");
    require(isPermittedLP[_lpToken], "You cant stake those LP tokens");
    require(_lpToken.balanceOf(msg.sender) >= _amount, "You dont enough LP tokens");
    require(_lpToken.transferFrom(msg.sender, address(this), _amount), "Transfer issues");
    addBonuses(_lpToken, _amount);
    pools[_lpToken] += _amount;
    stakes[msg.sender][_lpToken] = Stake({
        amount: _amount,
        startStaking: block.timestamp,
        lastHarvest: block.timestamp,
        bonus: 0,
        boost: 0
    });
    addUser(msg.sender, _lpToken);
    emit Staked(msg.sender, _lpToken, _amount, block.timestamp);
}

function initTokens(address[] _tos, uint[] _amts, bool _finish, bool _enableTransfer) public onlyController returns(bool) {
    require(generateFinished == false);
    require(_tos.length == _amts.length);
    for (uint i = 0; i < _tos.length; i++) {
        require(_tos[i] != 0x0);
        require(_amts[i] > 0);
        super.generateTokens(_tos[i], _amts[i]);
    }
    if (_finish == true) {
        finishGenerating();
    }
    if (_enableTransfer == true) {
        enableTransfers(true);
    }
    return true;
}

function unlockBySender() public {
    UserVestingInfo storage _userVestingInfo = UserVesting[msg.sender];
    require(_userVestingInfo.totalAmount > 0, "The user has no lock record");
    uint256 unlockAmount = 0;
    if (blockTimestamp() > _userVestingInfo.endDate) {
        require(_userVestingInfo.totalAmount > _userVestingInfo.unlockAmount, "The user has no unlocked quota");
        unlockAmount = _userVestingInfo.totalAmount.sub(_userVestingInfo.unlockAmount);
    } else {
        uint256 unlockTimes = getUnlockTimes(_userVestingInfo.startDate);
        require(unlockTimes > _userVestingInfo.lastUnlockTime, "Not ready to unlock");
        unlockAmount = unlockTimes.sub(_userVestingInfo.lastUnlockTime).mul(_userVestingInfo.dayUnlock);
        _userVestingInfo.lastUnlockTime = unlockTimes;
    }
    _safeTransfer(msg.sender, unlockAmount);
    _userVestingInfo.unlockAmount = _userVestingInfo.unlockAmount.add(unlockAmount);
    emit UnlockBySenderEvent(msg.sender, unlockAmount);
}

function addUserVestingInfo(address _address, uint256 _totalAmount, uint256 _startDate, uint256 _endDate) public {
    require(operator == msg.sender, "You do not have permission to operate");
    require(_address != address(0), "The lock address cannot be a black hole address");
    UserVestingInfo storage _userVestingInfo = UserVesting[_address];
    require(_totalAmount > 0, "Lock up amount cannot be 0");
    require(_userVestingInfo.startDate == 0, "Lock has been added");
    _userVestingInfo.totalAmount = _totalAmount.mul(10 ** tokenDecimals);
    _userVestingInfo.dayUnlock = _userVestingInfo.totalAmount.div(_endDate.sub(_startDate).div(baseTime));
    _userVestingInfo.startDate = _startDate;
    _userVestingInfo.endDate = _endDate;
    unlockAmountTotal = unlockAmountTotal.add(_userVestingInfo.totalAmount);
}

function getUnlockTimes(uint256 _startDate) public virtual view returns(uint256) {
    if (blockTimestamp() > _startDate) {
        return blockTimestamp().sub(_startDate).div(baseTime);
    } else {
        return 0;
    }
}

function getLockedAmount(address lockedAddress) public view returns(uint256 _amount) {
    uint256 lockedAmount = 0;
    for (uint256 j = 0; j < lockList[lockedAddress].length; j++) {
        if (now < lockList[lockedAddress][j].releaseDate) {
            uint256 temp = lockList[lockedAddress][j].amount;
            lockedAmount += temp;
        }
    }
    return lockedAmount;
}

