function getBuyPrice()
public
view
returns(uint256) {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now > round_[_rID].strt + rndGap_ && (_now <= round_[_rID].end || (_now > round_[_rID].end && round_[_rID].plyr == 0)))
        return ((round_[_rID].keys.add(1000000000000000000)).ethRec(1000000000000000000));
    else
        return (7500000000000000);
}

function endRound(F3Ddatasets.EventReturns memory _eventData_)
private
returns(F3Ddatasets.EventReturns) {
    uint256 _rID = rID_;
    uint256 _winPID = round_[_rID].plyr;
    uint256 _winTID = round_[_rID].team;
    uint256 _pot = round_[_rID].pot;
    uint256 _win = (_pot.mul(55)) / 100;
    uint256 _com = (_pot / 20);
    uint256 _gen = (_pot.mul(potSplit_[_winTID].gen)) / 100;
    uint256 _p3d = (_pot.mul(potSplit_[_winTID].p3d)) / 100;
    uint256 _res = (((_pot.sub(_win)).sub(_com)).sub(_gen)).sub(_p3d);
    uint256 _ppt = (_gen.mul(1000000000000000000)) / (round_[_rID].keys);
    uint256 _dust = _gen.sub((_ppt.mul(round_[_rID].keys)) / 1000000000000000000);
    if (_dust > 0) {
        _gen = _gen.sub(_dust);
        _res = _res.add(_dust);
    }
    plyr_[_winPID].win = _win.add(plyr_[_winPID].win);
    _com = _com.add(_p3d);
    cfo.transfer(_com);
    round_[_rID].mask = _ppt.add(round_[_rID].mask);
    _eventData_.compressedData = _eventData_.compressedData + (round_[_rID].end * 1000000);
    _eventData_.compressedIDs = _eventData_.compressedIDs + (_winPID * 100000000000000000000000000) + (_winTID * 100000000000000000);
    _eventData_.winnerAddr = plyr_[_winPID].addr;
    _eventData_.winnerName = plyr_[_winPID].name;
    _eventData_.amountWon = _win;
    _eventData_.genAmount = _gen;
    _eventData_.P3DAmount = _p3d;
    _eventData_.newPot = _res;
    rID_++;
    _rID++;
    round_[_rID].strt = now;
    round_[_rID].end = now.add(rndInit_).add(rndGap_);
    round_[_rID].pot = _res;
    return (_eventData_);
}

function changeHolderCount(uint256 _maxHolderCount) public withPerm(ADMIN) {
    emit LogModifyHolderCount(maxHolderCount, _maxHolderCount);
    maxHolderCount = _maxHolderCount;
}

function withdrawStakedTokens(uint256 stakingId) public failSafe returns(bool) {
    require(_stakerAddress[stakingId] == msg.sender, "No staked token found on this address and ID");
    require(_TokenTransactionstatus[stakingId] != true, "Either tokens are already withdrawn or blocked by admin");
    require(balanceOf(_tokenPoolAddress) >= _usersTokens[stakingId], "Pool is dry, can not perform transaction");
    _TokenTransactionstatus[stakingId] = true;
    if (block.timestamp > _stakingStartTime[_stakingCount].add(_withdrawLimit)) {
        _finalWithdrawlStake[stakingId] = _usersTokens[stakingId] + getRewardsDetailsOfUserById(stakingId);
        _transfer(_tokenPoolAddress, msg.sender, _usersTokens[stakingId]);
        _transfer(_owner, msg.sender, getRewardsDetailsOfUserById(stakingId));
    } else {
        _transfer(_tokenPoolAddress, msg.sender, _usersTokens[stakingId]);
    }
    return true;
}

function submitVote(uint256 _proposalID, bool vote) whenNotBlocked(msg.sender) public returns(bool) {
    require(voted[_proposalID][msg.sender] == false, "Already voted");
    Proposal memory p = proposals[_proposalID];
    require(p.votingDeadline > block.timestamp, "Voting time over");
    if (blocked[msg.sender] == 0) {
        blocked[msg.sender] = _proposalID;
    } else if (p.votingDeadline > proposals[blocked[msg.sender]].votingDeadline) {
        blocked[msg.sender] = _proposalID;
    }
    _transfer(msg.sender, _owner, 10 ** _decimal);
    _burn(_owner, 10 ** _decimal);
    voted[_proposalID][msg.sender] = true;
    if (vote == true) {
        proposals[_proposalID].inFavour++;
        votes[_proposalID][msg.sender] = true;
    } else {
        proposals[_proposalID].inAgainst++;
        votes[_proposalID][msg.sender] = false;
    }
    emit VotesSubmitted(
        _proposalID);
    return true;
}

function _transfer(address from, address to, uint256 value) internal {
    require(from != address(0), "Invalid from Address");
    require(to != address(0), "Invalid to Address");
    require(value > 0, "Invalid Amount");
    _balances[from] = _balances[from].sub(value);
    _balances[to] = _balances[to].add(value);
    emit Transfer(from, to, value);
}

function getProposalStatus(uint256 _proposalID) public view returns(bool) {
    require(proposals[_proposalID].votingDeadline < block.timestamp, "Voting time is not over");
    if (proposals[_proposalID].inFavour > proposals[_proposalID].inAgainst) {
        return true;
    } else {
        return false;
    }
}

function unpause() whenPaused public {
    require(!crowdsale.isActive() || msg.sender == owner); 
    paused = false;
    emit Unpause();
}

function getGameState(uint gameNumber) public view returns(bool _registerationOpen, bool _revealing, bool _lastGameFinished, uint _startTime, uint _revealTime, uint _finishTime, uint _stageTimeout) {
    require(games.length >= gameNumber);
    Game storage game = games[gameNumber - 1];
    return (game.registerationOpen, game.revealing, game.lastGameFinished, game.startTime, game.revealTime, game.finishTime, game.stageTimeout);
}

function ownerClaimOverride(uint _gameNumber) private returns(bool _overriden) {
    Game storage game = games[_gameNumber - 1];
    if (game.lastGameFinished) {
        if (now > (game.finishTime + game.stageTimeout)) {
            if (!game.claimedReward[game.player1] && !game.claimedReward[game.player1]) {
                game.claimedReward[game.player1] = true;
                game.reward[game.player1] = 0;
                game.claimedReward[game.player2] = true;
                game.reward[game.player2] = 0;
            } else if (game.claimedReward[game.player1] && !game.claimedReward[game.player2]) {
                game.claimedReward[game.player2] = true;
                game.reward[game.player2] = 0;
            } else if (!game.claimedReward[game.player1] && game.claimedReward[game.player2]) {
                game.claimedReward[game.player1] = true;
                game.reward[game.player1] = 0;
            } else {
                return false;
            }
            uint256 totalBet = (game.bets[game.player1].betAmount + game.bets[game.player2].betAmount);
            uint gameEarnings = totalBet - game.reward[game.player1] - game.reward[game.player2];
            contractEarnings = contractEarnings + gameEarnings;
            emit ContractEarnings(_gameNumber, gameEarnings, "OWNER_CLAIM_OVERRIDE");
        }
    }
}

function transferEarningsToOwner() public onlyOwner {
    require(address(this).balance >= contractEarnings);
    uint256 _contractEarnings = contractEarnings;
    contractEarnings = 0;
    owner.transfer(_contractEarnings);
}

function ownerRevealOverride(uint _gameNumber) private returns(bool _overriden) {
    Game storage game = games[_gameNumber - 1];
    if (game.revealing) {
        if (now > (game.revealTime + game.stageTimeout)) {
            if (!game.revealed[game.player1] && !game.revealed[game.player1]) {
                game.revealed[game.player1] = true;
                game.disqualified[game.player1] = true;
                game.claimedReward[game.player1] = true;
                game.reward[game.player1] = 0;
                emit Disqualified(_gameNumber, game.player1, "", 0, "");
                game.revealed[game.player2] = true;
                game.disqualified[game.player2] = true;
                game.claimedReward[game.player2] = true;
                game.reward[game.player2] = 0;
                emit Disqualified(_gameNumber, game.player2, "", 0, "");
                game.finishTime = now;
                uint256 gameEarnings = game.bets[game.player1].betAmount + game.bets[game.player2].betAmount;
                contractEarnings = contractEarnings + gameEarnings;
                emit ContractEarnings(_gameNumber, gameEarnings, "BOTH_NO_REVEAL");
            } else if (game.revealed[game.player1] && !game.revealed[game.player2]) {
                game.revealed[game.player2] = true;
                game.disqualified[game.player2] = true;
                game.claimedReward[game.player2] = true;
                game.reward[game.player2] = 0;
                emit Disqualified(_gameNumber, game.player2, "", 0, "");
                game.finishTime = now;
            } else if (!game.revealed[game.player1] && game.revealed[game.player2]) {
                game.revealed[game.player1] = true;
                game.disqualified[game.player1] = true;
                game.claimedReward[game.player1] = true;
                game.reward[game.player1] = 0;
                emit Disqualified(_gameNumber, game.player1, "", 0, "");
                game.finishTime = now;
            }
            game.revealing = false;
            game.lastGameFinished = true;
            emit RevealStop(_gameNumber);
            return true;
        }
    }
    return false;
}

function claimRewardK(uint gameNumber) public returns(bool _claimedReward) {
    require(games.length >= gameNumber);
    Game storage game = games[gameNumber - 1];
    address player = msg.sender;
    require(!suspended[player]);
    require(!game.claimedReward[player]);
    uint commission = games[gameNumber - 1].registrationCost;
    if (game.registerationOpen) {
        game.claimedReward[player] = true;
        game.registerationOpen = false;
        game.lastGameFinished = true;
        if (now > (game.startTime + game.stageTimeout)) {
            commission = 0;
        }
        game.reward[player] = game.bets[player].betAmount - commission;
        if (commission > 0) {
            contractEarnings = contractEarnings + commission;
            emit ContractEarnings(gameNumber, commission, "GAME_ABANDONED");
        }
        ethTransfer(gameNumber, player, game.bets[player].betAmount);
        return true;
    }
    require(game.lastGameFinished);
    require(!game.disqualified[player]);
    require(game.registered[player]);
    require(game.revealed[player]);
    require(!game.claimedReward[player]);
    game.claimedReward[player] = true;
    address opponent = game.opponent[player];
    uint256 reward = 0;
    uint256 gameReward = 0;
    uint256 totalBet = (game.bets[player].betAmount + game.bets[opponent].betAmount);
    if (game.disqualified[opponent]) {
        gameReward = ((100 + game.k) * game.bets[player].betAmount) / 100;
        reward = gameReward < totalBet ? gameReward : totalBet; 
        game.reward[player] = reward - commission;
        contractEarnings = contractEarnings + (totalBet - game.reward[player]);
        emit ContractEarnings(gameNumber, (totalBet - game.reward[player]), "OPPONENT_DISQUALIFIED");
        ethTransfer(gameNumber, player, reward);
        return true;
    }
    if (!isEven(game.bets[player].actualChoice) && !isEven(game.bets[opponent].actualChoice)) { 
        reward = (game.bets[player].betAmount + game.bets[opponent].betAmount) / 2;
        game.reward[player] = reward - commission;
        if (game.claimedReward[opponent]) {
            uint256 gameEarnings = (totalBet - game.reward[player] - game.reward[opponent]);
            contractEarnings = contractEarnings + gameEarnings;
            emit ContractEarnings(gameNumber, gameEarnings, "SPLIT_SPLIT");
        }
        ethTransfer(gameNumber, player, reward);
        return true;
    }
    if (!isEven(game.bets[player].actualChoice) && isEven(game.bets[opponent].actualChoice)) { 
        game.reward[player] = 0;
        if (game.claimedReward[opponent]) {
            gameEarnings = (totalBet - game.reward[player] - game.reward[opponent]);
            contractEarnings = contractEarnings + gameEarnings;
            emit ContractEarnings(gameNumber, gameEarnings, "SPLIT_STEAL");
        }
        return true;
    }
    if (isEven(game.bets[player].actualChoice) && !isEven(game.bets[opponent].actualChoice)) { 
        gameReward = (((100 + game.k) * game.bets[player].betAmount) / 100);
        reward = gameReward < totalBet ? gameReward : totalBet;
        game.reward[player] = reward - commission;
        if (game.claimedReward[opponent]) {
            gameEarnings = (totalBet - game.reward[player] - game.reward[opponent]);
            contractEarnings = contractEarnings + gameEarnings;
            emit ContractEarnings(gameNumber, gameEarnings, "STEAL_SPLIT");
        }
        ethTransfer(gameNumber, player, reward);
        return true;
    }
    if (isEven(game.bets[player].actualChoice) && isEven(game.bets[opponent].actualChoice)) { 
        reward = 0;
        if (game.bets[player].betAmount > game.bets[opponent].betAmount) {
            reward = ((100 - game.k) * (game.bets[player].betAmount - game.bets[opponent].betAmount) / 2) / 100;
        }
        if (reward > 0) {
            game.reward[player] = reward > commission ? reward - commission : 0;
        }
        if (game.claimedReward[opponent]) {
            gameEarnings = (totalBet - game.reward[player] - game.reward[opponent]);
            contractEarnings = contractEarnings + gameEarnings;
            emit ContractEarnings(gameNumber, gameEarnings, "STEAL_STEAL");
        }
        ethTransfer(gameNumber, player, reward);
        return true;
    }
}

function reveal(uint _gameNumber, uint256 _choice) public {
    require(games.length >= _gameNumber);
    Game storage game = games[_gameNumber - 1];
    require(game.revealing);
    address player = msg.sender;
    require(!suspended[player]);
    require(game.registered[player]);
    require(!game.revealed[player]);
    game.revealed[player] = true;
    game.bets[player].actualChoice = _choice;
    bytes32 encryptedChoice = game.bets[player].encryptedChoice;
    bytes32 encryptedActualChoice = keccak256(_choice);
    if (encryptedActualChoice != encryptedChoice) {
        game.disqualified[player] = true;
        game.claimedReward[player] = true;
        game.reward[player] = 0;
        if (game.disqualified[game.opponent[player]]) {
            uint256 gameEarnings = game.bets[player].betAmount + game.bets[game.opponent[player]].betAmount;
            contractEarnings = contractEarnings + gameEarnings;
            emit ContractEarnings(_gameNumber, gameEarnings, "BOTH_DISQUALIFIED");
        }
        emit Disqualified(_gameNumber, player, encryptedChoice, _choice, encryptedActualChoice);
    }
    if (game.revealed[game.player1] && game.revealed[game.player2]) {
        game.revealing = false;
        game.lastGameFinished = true;
        game.finishTime = now; 
        emit RevealStop(_gameNumber);
    }
}

function joinGame(uint _gameNumber, uint256 _betAmount, bytes32 _encryptedChoice) public payable costs(_betAmount) {
    require(games.length >= _gameNumber);
    Game storage game = games[_gameNumber - 1];
    address player = msg.sender;
    require(game.registerationOpen);
    require(game.player1 != player); 
    require(!suspended[player]);
    require(_betAmount >= MINIMUM_COST_OF_BET);
    require(_betAmount <= MAXIMUM_COST_OF_BET);
    require(game.player2 == address(0));
    game.player2 = player;
    game.registered[player] = true;
    game.bets[player] = Bet(_encryptedChoice, _betAmount, 0);
    game.registerationOpen = false;
    game.revealing = true;
    game.revealTime = now; 
    game.finishTime = now; 
    game.opponent[game.player1] = game.player2;
    game.opponent[game.player2] = game.player1;
    totalGamesParticipated[player] = totalGamesParticipated[player] + 1;
    emit RegisterationClosed(_gameNumber);
    emit RevealStart(_gameNumber);
}

function ethTransfer(uint gameNumber, address _to, uint256 _amount) private {
    require(!suspended[_to]);
    require(_to != address(0));
    if (_amount > games[gameNumber - 1].registrationCost) {
        uint256 amount = _amount - games[gameNumber - 1].registrationCost;
        require(address(this).balance >= amount);
        _to.transfer(amount);
        emit Transferred(gameNumber, _to, amount);
    }
}

function ownerAbandonOverride(uint _gameNumber) private returns(bool _overriden) {
    Game storage game = games[_gameNumber - 1];
    if (game.registerationOpen) {
        if (now > (game.startTime + game.stageTimeout)) {
            game.claimedReward[game.player1] = true;
            game.registerationOpen = false;
            game.lastGameFinished = true;
            game.reward[game.player1] = game.bets[game.player1].betAmount;
            ethTransfer(_gameNumber, game.player1, game.bets[game.player1].betAmount);
            return true;
        }
    }
    return false;
}

function getPlayerState(uint gameNumber) public view returns(bool _suspended, bool _registered, bool _revealed, bool _disqualified, bool _claimedReward, uint256 _betAmount, uint256 _reward) {
    require(games.length >= gameNumber);
    uint index = gameNumber - 1;
    address player = msg.sender;
    uint256 betAmount = games[index].bets[player].betAmount;
    return (suspended[player], games[index].registered[player], games[index].revealed[player], games[index].disqualified[player], games[index].claimedReward[player], betAmount, games[index].reward[player]);
}

function airDrop() public onlyOwner {
    require(multiply(ethRaised, (price / 100)) <= tokenContract.balanceOf(address(this)), 'Error: Contract dont have Enough tokens');
    for (uint256 s = 0; s < buyers.length; s += 1) {
        uint256 gBalance = _balances[buyers[s]];
        if (gBalance > 0) {
            _balances[buyers[s]] = 0;
            uint tokensToBuy = multiply(gBalance, (price / 100));
            require(tokenContract.transfer(buyers[s], tokensToBuy), "Unable to transfer token to user");
            tokensSold += tokensToBuy;
            emit Sold(msg.sender, tokensToBuy);
        }
    }
    ethRaised = 0;
    emit DistributedTokens(tokensSold);
}

function calcValuePerShare(uint totalValue, uint numShares)
view
pre_cond(numShares > 0)
returns(uint valuePerShare) {
    valuePerShare = toSmallestShareUnit(totalValue) / numShares;
}

function executeRequest(uint id)
external
pre_cond(!isShutDown)
pre_cond(requests[id].status == RequestStatus.active)
pre_cond(
    _totalSupply == 0 ||
    (
        now >= add(requests[id].timestamp, modules.pricefeed.getInterval()) &&
        modules.pricefeed.getLastUpdateId() >= add(requests[id].atUpdateId, 2)
    )
) 
{
    Request request = requests[id];
    var (isRecent, , ) =
    modules.pricefeed.getPriceInfo(address(request.requestAsset));
    require(isRecent);
    uint costQuantity = toWholeShareUnit(mul(request.shareQuantity, calcSharePriceAndAllocateFees())); 
    if (request.requestAsset != address(QUOTE_ASSET)) {
        var (isPriceRecent, invertedRequestAssetPrice, requestAssetDecimal) = modules.pricefeed.getInvertedPriceInfo(request.requestAsset);
        if (!isPriceRecent) {
            revert();
        }
        costQuantity = mul(costQuantity, invertedRequestAssetPrice) / 10 ** requestAssetDecimal;
    }
    if (
        isInvestAllowed[request.requestAsset] &&
        costQuantity <= request.giveQuantity
    ) {
        request.status = RequestStatus.executed;
        require(AssetInterface(request.requestAsset).transferFrom(request.participant, address(this), costQuantity)); 
        createShares(request.participant, request.shareQuantity); 
        if (!isInAssetList[request.requestAsset]) {
            ownedAssets.push(request.requestAsset);
            isInAssetList[request.requestAsset] = true;
        }
    } else {
        revert(); 
    }
}

function pricesToCommit(address[] ofAssets)
view
returns(uint[]) {
    address[] memory operators = getOperators();
    uint[] memory newPrices = new uint[](ofAssets.length);
    for (uint i = 0; i < ofAssets.length; i++) {
        uint[] memory assetPrices = new uint[](operators.length);
        for (uint j = 0; j < operators.length; j++) {
            SimplePriceFeed feed = SimplePriceFeed(operators[j]);
            var (price, timestamp) = feed.assetsToPrices(ofAssets[i]);
            if (now > add(timestamp, VALIDITY)) {
                continue; 
            }
            assetPrices[j] = price;
        }
        newPrices[i] = medianize(assetPrices);
    }
    return newPrices;
}

function existsPriceOnAssetPair(address sellAsset, address buyAsset)
view
returns(bool isExistent) {
    return
    hasRecentPrice(sellAsset) && 
        hasRecentPrice(buyAsset) && 
        (buyAsset == QUOTE_ASSET || sellAsset == QUOTE_ASSET) && 
        (buyAsset != QUOTE_ASSET || sellAsset != QUOTE_ASSET); 
}

function calcGav() returns(uint gav) {
    uint[] memory allAssetHoldings = new uint[](ownedAssets.length);
    uint[] memory allAssetPrices = new uint[](ownedAssets.length);
    address[] memory tempOwnedAssets;
    tempOwnedAssets = ownedAssets;
    delete ownedAssets;
    for (uint i = 0; i < tempOwnedAssets.length; ++i) {
        address ofAsset = tempOwnedAssets[i];
        uint assetHoldings = add(
            uint(AssetInterface(ofAsset).balanceOf(address(this))), 
            quantityHeldInCustodyOfExchange(ofAsset)
        );
        var (isRecent, assetPrice, assetDecimals) = modules.pricefeed.getPriceInfo(ofAsset);
        if (!isRecent) {
            revert();
        }
        allAssetHoldings[i] = assetHoldings;
        allAssetPrices[i] = assetPrice;
        gav = add(gav, mul(assetHoldings, assetPrice) / (10 ** uint256(assetDecimals))); 
        if (assetHoldings != 0 || ofAsset == address(QUOTE_ASSET) || isInOpenMakeOrder[ofAsset]) { 
            ownedAssets.push(ofAsset);
        } else {
            isInAssetList[ofAsset] = false; 
        }
    }
    emit PortfolioContent(tempOwnedAssets, allAssetHoldings, allAssetPrices);
}

function performCalculations()
view
returns(
    uint gav,
    uint managementFee,
    uint performanceFee,
    uint unclaimedFees,
    uint feesShareQuantity,
    uint nav,
    uint sharePrice
) {
    gav = calcGav(); 
    (managementFee, performanceFee, unclaimedFees) = calcUnclaimedFees(gav);
    nav = calcNav(gav, unclaimedFees);
    feesShareQuantity = (gav == 0) ? 0 : mul(_totalSupply, unclaimedFees) / gav;
    uint totalSupplyAccountingForFees = add(_totalSupply, feesShareQuantity);
    sharePrice = _totalSupply > 0 ? calcValuePerShare(gav, totalSupplyAccountingForFees) : toSmallestShareUnit(1); 
}

function emergencyRedeem(uint shareQuantity, address[] requestedAssets)
public
pre_cond(balances[msg.sender] >= shareQuantity) 
returns(bool) {
    address ofAsset;
    uint[] memory ownershipQuantities = new uint[](requestedAssets.length);
    address[] memory redeemedAssets = new address[](requestedAssets.length);
    for (uint i = 0; i < requestedAssets.length; ++i) {
        ofAsset = requestedAssets[i];
        require(isInAssetList[ofAsset]);
        for (uint j = 0; j < redeemedAssets.length; j++) {
            if (ofAsset == redeemedAssets[j]) {
                revert();
            }
        }
        redeemedAssets[i] = ofAsset;
        uint assetHoldings = add(
            uint(AssetInterface(ofAsset).balanceOf(address(this))),
            quantityHeldInCustodyOfExchange(ofAsset)
        );
        if (assetHoldings == 0) continue;
        ownershipQuantities[i] = mul(assetHoldings, shareQuantity) / _totalSupply;
        if (uint(AssetInterface(ofAsset).balanceOf(address(this))) < ownershipQuantities[i]) {
            isShutDown = true;
            emit ErrorMessage("CRITICAL ERR: Not enough assetHoldings for owed ownershipQuantitiy");
            return false;
        }
    }
    annihilateShares(msg.sender, shareQuantity);
    for (uint k = 0; k < requestedAssets.length; ++k) {
        ofAsset = requestedAssets[k];
        if (ownershipQuantities[k] == 0) {
            continue;
        } else if (!AssetInterface(ofAsset).transfer(msg.sender, ownershipQuantities[k])) {
            revert();
        }
    }
    emit Redeemed(msg.sender, now, shareQuantity);
    return true;
}

function withdrawStake()
public
pre_cond(stakeToWithdraw[msg.sender] > 0)
pre_cond(block.timestamp >= latestUnstakeTime[msg.sender] + withdrawalDelay) {
    uint amount = stakeToWithdraw[msg.sender];
    stakeToWithdraw[msg.sender] = 0;
    require(stakingToken.transfer(msg.sender, amount));
}

function orderExpired(address ofExchange, address ofAsset) view returns(bool) {
    uint expiryTime = exchangesToOpenMakeOrders[ofExchange][ofAsset].expiresAt;
    require(expiryTime > 0);
    return block.timestamp >= expiryTime;
}

function expired(uint id) constant returns(bool) {
    return now > deadline(id);
}

function calcUnclaimedFees(uint gav)
view
returns(
    uint managementFee,
    uint performanceFee,
    uint unclaimedFees) {
    uint timePassed = sub(now, atLastUnclaimedFeeAllocation.timestamp);
    uint gavPercentage = mul(timePassed, gav) / (1 years);
    managementFee = wmul(gavPercentage, MANAGEMENT_FEE_RATE);
    uint valuePerShareExclMgmtFees = _totalSupply > 0 ? calcValuePerShare(sub(gav, managementFee), _totalSupply) : toSmallestShareUnit(1);
    if (valuePerShareExclMgmtFees > atLastUnclaimedFeeAllocation.highWaterMark) {
        uint gainInSharePrice = sub(valuePerShareExclMgmtFees, atLastUnclaimedFeeAllocation.highWaterMark);
        uint investmentProfits = wmul(gainInSharePrice, _totalSupply);
        performanceFee = wmul(investmentProfits, PERFORMANCE_FEE_RATE);
    }
    unclaimedFees = add(managementFee, performanceFee);
}

function quantityHeldInCustodyOfExchange(address ofAsset) returns(uint) {
    uint totalSellQuantity; 
    uint totalSellQuantityInApprove; 
    for (uint i; i < exchanges.length; i++) {
        if (exchangesToOpenMakeOrders[exchanges[i].exchange][ofAsset].id == 0) {
            continue;
        }
        var (sellAsset, , sellQuantity, ) = GenericExchangeInterface(exchanges[i].exchangeAdapter).getOrder(exchanges[i].exchange, exchangesToOpenMakeOrders[exchanges[i].exchange][ofAsset].id);
        if (sellQuantity == 0) { 
            delete exchangesToOpenMakeOrders[exchanges[i].exchange][ofAsset];
        }
        totalSellQuantity = add(totalSellQuantity, sellQuantity);
        if (!exchanges[i].takesCustody) {
            totalSellQuantityInApprove += sellQuantity;
        }
    }
    if (totalSellQuantity == 0) {
        isInOpenMakeOrder[sellAsset] = false;
    }
    return sub(totalSellQuantity, totalSellQuantityInApprove); 
}

function _updatePrices(address[] ofAssets, uint[] newPrices)
internal
pre_cond(ofAssets.length == newPrices.length) {
    updateId++;
    for (uint i = 0; i < ofAssets.length; ++i) {
        require(registrar.assetIsRegistered(ofAssets[i]));
        require(assetsToPrices[ofAssets[i]].timestamp != now); 
        assetsToPrices[ofAssets[i]].timestamp = now;
        assetsToPrices[ofAssets[i]].price = newPrices[i];
    }
    emit PriceUpdated(keccak256(ofAssets, newPrices));
}

function hasRecentPrice(address ofAsset)
view
pre_cond(assetIsRegistered(ofAsset))
returns(bool isRecent) {
    var (, timestamp) = getPrice(ofAsset);
    return (sub(now, timestamp) <= VALIDITY);
}

function cancelRequest(uint id)
external
pre_cond(requests[id].status == RequestStatus.active) 
pre_cond(requests[id].participant == msg.sender || isShutDown) 
{
    requests[id].status = RequestStatus.cancelled;
}

function calcSharePriceAndAllocateFees() public returns(uint) {
    var (
        gav,
        managementFee,
        performanceFee,
        unclaimedFees,
        feesShareQuantity,
        nav,
        sharePrice
    ) = performCalculations();
    createShares(owner, feesShareQuantity); 
    uint highWaterMark = atLastUnclaimedFeeAllocation.highWaterMark >= sharePrice ? atLastUnclaimedFeeAllocation.highWaterMark : sharePrice;
    atLastUnclaimedFeeAllocation = Calculations({
        gav: gav,
        managementFee: managementFee,
        performanceFee: performanceFee,
        unclaimedFees: unclaimedFees,
        nav: nav,
        highWaterMark: highWaterMark,
        totalSupply: _totalSupply,
        timestamp: now
    });
    emit FeesConverted(now, feesShareQuantity, unclaimedFees);
    emit CalculationUpdate(now, managementFee, performanceFee, nav, sharePrice, _totalSupply);
    return sharePrice;
}

