function executeTransaction(uint transactionId)
public
notExecuted(transactionId) {
    if (isConfirmed(transactionId)) {
        Transaction storage txn = transactions[transactionId];
        txn.executed = true;
        (bool success, bytes memory returnData) = txn.destination.call.value(txn.value)(txn.data);
        if (success)
            emit Execution(transactionId, returnData);
        else {
            emit ExecutionFailure(transactionId, returnData);
            txn.executed = false;
        }
    }
}

function getAllowedAmountToContribute(address addr) view public returns(uint256) {
    if (!whitelist[addr]._whitelisted) {
        return 0;
    } else if (now <= timeThatFinishGuaranteedPeriod) {
        if (whitelist[addr]._shouldWaitGuaranteedPeriod) {
            return 0;
        } else {
            if (whitelist[addr]._doubleValue) {
                uint256 amount = maximumValueDuringGuaranteedPeriod * 2;
                if (whitelist[addr]._unlimited || amount < maximumValueWithoutProofOfAddress) {
                    return amount;
                } else {
                    return maximumValueWithoutProofOfAddress;
                }
            } else {
                return maximumValueDuringGuaranteedPeriod;
            }
        }
    } else {
        if (whitelist[addr]._unlimited) {
            return maximumValueAfterGuaranteedPeriod;
        } else {
            return maximumValueWithoutProofOfAddress;
        }
    }
}

function claim() external returns(uint amount) {
    uint blockTimestamp = getBlockTimestamp();
    uint timeElapsed = blockTimestamp.sub(lastClaim);
    lastClaim = blockTimestamp;
    uint balance = IERC20(imx).balanceOf(address(this));
    if (timeElapsed > periodLength) {
        amount = balance;
    } else {
        amount = balance.mul(timeElapsed).div(periodLength);
    }
    if (amount > 0) {
        IERC20(imx).transfer(xImx, amount);
        IPoolToken(xImx).sync();
    }
    emit Claim(balance, timeElapsed, amount);
}

