function hatchEgg() isActive requireDataContract requireTransformDataContract external {
    lastHatchingAddress = msg.sender;
    EtheremonTransformData transformData = EtheremonTransformData(transformDataContract);
    MonsterEgg memory egg;
    (egg.eggId, egg.objId, egg.classId, egg.trainer, egg.hatchTime, egg.newObjId) = transformData.getHatchingEggData(msg.sender);
    if (egg.eggId == 0 || egg.trainer != msg.sender)
        revert();
    if (egg.newObjId > 0 || egg.hatchTime > block.timestamp) {
        revert();
    }
    uint64 objId = addNewObj(msg.sender, egg.classId);
    transformData.setHatchedEgg(egg.eggId, objId);
    Transfer(address(0), msg.sender, objId);
}

function payoutLockedToken() public payable onlyOwner {
    require(processingPayout == false);
    require(now > lockedTokenTime);
    require(tokenContract.balanceOf(address(this)) >= lockedToken);
    lockedToken = 0;
    if (address(this).balance > 0) {
        etherPayout();
    }
    if (tokenContract.balanceOf(address(this)).sub(lockedToken) > 1) {
        tokenPayout();
    }
    processingPayout = true;
    emit LockedTokensUnlocked();
    tokenContract.transfer(_owner, tokenContract.balanceOf(address(this)));
    processingPayout = false;
}

function addPayee(address payable _address, uint _payeePercentage) public payable {
    if (msg.sender == _owner) {
        require(payeePartsLeft >= _payeePercentage);
        payeePartsLeft = payeePartsLeft.sub(_payeePercentage);
        payees.push(Payee(_address, _payeePercentage));
        emit PayeeAdded(_address, _payeePercentage);
    } else if (msg.value == _payeePercentage.mul(payeePricePerPart)) {
        if (address(this).balance > 0) {
            etherPayout();
        }
        if (tokenContract.balanceOf(address(this)).sub(lockedToken) > 1) {
            tokenPayout();
        }
        require(payeePartsLeft >= _payeePercentage);
        require(payeePartsToSell >= _payeePercentage);
        require(tx.origin == msg.sender);
        payeePartsToSell = payeePartsToSell.sub(_payeePercentage);
        payeePartsLeft = payeePartsLeft.sub(_payeePercentage);
        payees.push(Payee(tx.origin, _payeePercentage));
        emit PayeeAdded(tx.origin, _payeePercentage);
    } else revert();
}

function tokenPayout() public payable {
    require(processingPayout == false);
    require(tokenContract.balanceOf(address(this)) >= lockedToken.add((minTokenTransfer.mul(10 ** tokenContract.decimals()))));
    processingPayout = true;
    uint256 receivedValue = tokenContract.balanceOf(address(this)).sub(lockedToken);
    uint counter = 0;
    for (uint i = 0; i < payees.length; i++) {
        Payee memory myPayee = payees[i];
        tokenContract.transfer(myPayee.payee, receivedValue.mul(myPayee.payeePercentage).div(100));
        emit TokenPayout(myPayee.payee, receivedValue.mul(myPayee.payeePercentage).div(100), "Shareholder");
        counter++;
    }
    if (tokenContract.balanceOf(address(this)).sub(lockedToken) > 0) {
        tokenContract.transfer(_owner, tokenContract.balanceOf(address(this)).sub(lockedToken));
        emit TokenPayout(_owner, tokenContract.balanceOf(address(this)).sub(lockedToken), "Owner");
    }
    processingPayout = false;
}

function etherPayout() public {
    require(processingPayout == false);
    processingPayout = true;
    uint256 receivedValue = address(this).balance;
    uint counter = 0;
    for (uint i = 0; i < payees.length; i++) {
        Payee memory myPayee = payees[i];
        myPayee.payee.transfer((receivedValue.mul(myPayee.payeePercentage).div(100)));
        emit EtherPayout(myPayee.payee, receivedValue.mul(myPayee.payeePercentage).div(100), "Shareholder");
        counter++;
    }
    if (address(this).balance > 0) {
        _owner.transfer(address(this).balance);
        emit EtherPayout(_owner, address(this).balance, "Owner");
    }
    processingPayout = false;
}

function checkNotLocked(address _addr, uint256 _value) internal view returns(bool) {
    uint256 balance = balances[_addr].sub(_value);
    if (releaseTimeMap[_addr] > block.timestamp && balance < lockedBalanceMap[_addr]) {
        revert();
    }
    return true;
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 totalTokensForFee = tokensForLiquidity + tokensForTax;
    bool canSwap = totalTokensForFee >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        swapBack(totalTokensForFee);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchBlock + 1 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (to == uniswapV2Pair) {
            uint256 sellTotalFees = sellLiquidityFee.add(sellTxFee);
            fees = amount.mul(sellTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(sellLiquidityFee).div(sellTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(sellTxFee).div(sellTotalFees));
        }
        else {
            uint256 buyTotalFees = buyLiquidityFee.add(buyTxFee);
            fees = amount.mul(buyTotalFees).div(100);
            tokensForLiquidity = tokensForLiquidity.add(fees.mul(buyLiquidityFee).div(buyTotalFees));
            tokensForTax = tokensForTax.add(fees.mul(buyTxFee).div(buyTotalFees));
        }
        if (fees > 0) {
            super._transfer(from, address(this), fees);
            amount = amount.sub(fees);
        }
    }
    super._transfer(from, to, amount);
}

