function findRegularTime() internal view returns(uint32) {
    if (now < regularTransTime[0]) {
        return 0;
    }
    uint256 i = 0;
    while (i < regularTransTime.length && now >= regularTransTime[i]) {
        i++;
    }
    return regularTransTime[i - 1];
}

function getFutureTransIdxByAddress(address _beneficiary) public view returns(uint256[]) {
    uint256 i = 0;
    uint256 num = 0;
    for (i = 0; i < futureTrans.length; i++) {
        if (futureTrans[i].beneficiary == _beneficiary) {
            num++;
        }
    }
    uint256[] memory transList = new uint256[](num);
    uint256 idx = 0;
    for (i = 0; i < futureTrans.length; i++) {
        if (futureTrans[i].beneficiary == _beneficiary) {
            transList[idx] = i;
            idx++;
        }
    }
    return transList;
}

function triggerTransaction(uint256 beginIdx, uint256 endIdx) public returns(bool) {
    uint32 regularTime = findRegularTime();
    require(regularTime > 0 && endIdx < futureTrans.length);
    bool bRemove = false;
    uint256 i = 0;
    for (i = beginIdx; i <= endIdx && i < futureTrans.length;) {
        bRemove = false;
        if (futureTrans[i].lastTime < regularTime) { 
            uint256 transNum = futureTrans[i].num;
            address beneficiary = futureTrans[i].beneficiary;
            futureTrans[i].lastTime = now;
            futureTrans[i].times = futureTrans[i].times - 1;
            require(futureTrans[i].times <= transTimes);
            if (futureTrans[i].times == 0) {
                bRemove = true;
                futureTrans[i].beneficiary = futureTrans[futureTrans.length - 1].beneficiary;
                futureTrans[i].num = futureTrans[futureTrans.length - 1].num;
                futureTrans[i].lastTime = futureTrans[futureTrans.length - 1].lastTime;
                futureTrans[i].times = futureTrans[futureTrans.length - 1].times;
                futureTrans.length = futureTrans.length.sub(1);
            }
            oweCbnt = oweCbnt.sub(transNum);
            _deliverTokens(beneficiary, transNum);
        }
        if (!bRemove) {
            i++;
        }
    }
    return true;
}

constructor(uint64 _lockUntil) public {
    require(_lockUntil > currentTime(), "TLV02");
    lockUntil = _lockUntil;
}

function tryFinalizeStage()
public {
    assert(numberOfStages >= numberOfFinalizedStages);
    if (numberOfStages == numberOfFinalizedStages) {
        return;
    }
    Stage storage stageToFinalize = stages[numberOfFinalizedStages];
    assert(!stageToFinalize.finalized);
    if (stageToFinalize.numberOfPlayers < MAX_PLAYERS_PER_STAGE) {
        return;
    }
    assert(stageToFinalize.blocknumber != 0);
    if (block.number - 256 <= stageToFinalize.blocknumber) {
        if (block.number == stageToFinalize.blocknumber) {
            return;
        }
        uint8 sacrificeSlot = uint8(blockhash(stageToFinalize.blocknumber)) % MAX_PLAYERS_PER_STAGE;
        uint256 jackpot = uint256(blockhash(stageToFinalize.blocknumber)) % 1000;
        address sacrifice = stageToFinalize.slotXplayer[sacrificeSlot];
        Loser[numberOfFinalizedStages] = sacrifice;
        emit SacrificeChosen(sacrifice);
        allocateSurvivorWinnings(sacrifice);
        if (jackpot == 777) {
            sacrifice.transfer(Jackpot);
            emit JackpotWon(sacrifice, Jackpot);
            Jackpot = 0;
        }
        RefundWaitingLine[NextAtLineEnd] = sacrifice;
        NextAtLineEnd++;
        Refundpot = Refundpot.add(0.005 ether);
        p3dContract.buy.value(0.005 ether)(stageToFinalize.setMN[1]);
        p3dContract.buy.value(0.005 ether)(stageToFinalize.setMN[2]);
    } else {
        invalidateStage(numberOfFinalizedStages);
        emit StageInvalidated(numberOfFinalizedStages);
    }
    stageToFinalize.finalized = true;
    numberOfFinalizedStages++;
}

function xfLobbyPendingDays(address memberAddr)
external
view
returns(uint256[XF_LOBBY_DAY_WORDS] memory words) {
    uint256 day = _currentDay() + 1;
    while (day-- != 0) {
        if (xfLobbyMembers[day][memberAddr].tailIndex > xfLobbyMembers[day][memberAddr].headIndex) {
            words[day >> 8] |= 1 << (day & 255);
        }
    }
    return words;
}

function xfLobbyExit(uint256 enterDay, uint256 count)
external {
    require(enterDay < _currentDay(), "E2X: Round is not complete");
    XfLobbyQueueStore storage qRef = xfLobbyMembers[enterDay][msg.sender];
    uint256 headIndex = qRef.headIndex;
    uint256 endIndex;
    if (count != 0) {
        require(count <= qRef.tailIndex - headIndex, "E2X: count invalid");
        endIndex = headIndex + count;
    } else {
        endIndex = qRef.tailIndex;
        require(headIndex < endIndex, "E2X: count invalid");
    }
    uint256 waasLobby = _waasLobby(enterDay);
    uint256 _xfLobby = xfLobby[enterDay];
    uint256 totalXfAmount = 0;
    do {
        uint256 rawAmount = qRef.entries[headIndex].rawAmount;
        address referrerAddr = qRef.entries[headIndex].referrerAddr;
        delete qRef.entries[headIndex];
        uint256 xfAmount = waasLobby * rawAmount / _xfLobby;
        if (referrerAddr == address(0) || referrerAddr == msg.sender) {
            _emitXfLobbyExit(enterDay, headIndex, xfAmount, referrerAddr);
        } else {
            uint256 referralBonusSuns = xfAmount / 20;
            xfAmount += referralBonusSuns;
            uint256 referrerBonusSuns = xfAmount / 10;
            _emitXfLobbyExit(enterDay, headIndex, xfAmount, referrerAddr);
            _mint(referrerAddr, referrerBonusSuns);
        }
        totalXfAmount += xfAmount;
    } while (++headIndex < endIndex);
    qRef.headIndex = uint40(headIndex);
    if (totalXfAmount != 0) {
        _mint(msg.sender, totalXfAmount);
    }
}

function xfLobbyRange(uint256 beginDay, uint256 endDay)
external
view
returns(uint256[] memory list) {
    require(
        beginDay < endDay && endDay <= _currentDay(),
        "E2X: invalid range"
    );
    list = new uint256[](endDay - beginDay);
    uint256 src = beginDay;
    uint256 dst = 0;
    do {
        list[dst++] = uint256(xfLobby[src++]);
    } while (src < endDay);
    return list;
}

function xfFlush()
external {
    GlobalsCache memory g;
    GlobalsCache memory gSnapshot;
    _globalsLoad(g, gSnapshot);
    require(address(this).balance != 0, "E2X: No value");
    require(LAST_FLUSHED_DAY < _currentDay(), "E2X: Invalid day");
    _dailyDataUpdateAuto(g);
    T2X_SHARE_ADDR.transfer((dailyData[LAST_FLUSHED_DAY].dayDividends * 10) / 100);
    LAST_FLUSHED_DAY++;
    _globalsSync(g, gSnapshot);
}

function _currentDay()
internal
view
returns(uint256) {
    if (block.timestamp < LAUNCH_TIME) {
        return 0;
    } else {
        return (block.timestamp - LAUNCH_TIME) / 1 days;
    }
}

function stakeEnd(uint256 stakeIndex, uint40 stakeIdParam)
external {
    GlobalsCache memory g;
    GlobalsCache memory gSnapshot;
    _globalsLoad(g, gSnapshot);
    StakeStore[] storage stakeListRef = stakeLists[msg.sender];
    require(stakeListRef.length != 0, "E2X: Empty stake list");
    require(stakeIndex < stakeListRef.length, "E2X: stakeIndex invalid");
    StakeCache memory st;
    _stakeLoad(stakeListRef[stakeIndex], stakeIdParam, st);
    _dailyDataUpdateAuto(g);
    uint256 servedDays = 0;
    bool prevUnlocked = (st._unlockedDay != 0);
    uint256 stakeReturn;
    uint256 payout = 0;
    uint256 dividends = 0;
    uint256 penalty = 0;
    uint256 cappedPenalty = 0;
    if (g._currentDay >= st._lockedDay) {
        if (prevUnlocked) {
            servedDays = st._stakedDays;
        } else {
            _stakeUnlock(g, st);
            servedDays = g._currentDay - st._lockedDay;
            if (servedDays > st._stakedDays) {
                servedDays = st._stakedDays;
            }
        }
        (stakeReturn, payout, dividends, penalty, cappedPenalty) = _stakePerformance(g, st, servedDays);
        msg.sender.transfer(dividends);
    } else {
        g._nextStakeSharesTotal -= st._stakeShares;
        stakeReturn = st._stakedSuns;
    }
    emit StakeEnd(
        stakeIdParam,
        prevUnlocked ? 1 : 0,
        msg.sender,
        st._lockedDay,
        servedDays,
        st._stakedSuns,
        st._stakeShares,
        dividends,
        payout,
        penalty,
        stakeReturn
    );
    if (cappedPenalty != 0 && !prevUnlocked) {
        g._stakePenaltyTotal += cappedPenalty;
    }
    if (stakeReturn != 0) {
        _mint(msg.sender, stakeReturn);
    }
    g._lockedSunsTotal -= st._stakedSuns;
    _stakeRemove(stakeListRef, stakeIndex);
    _globalsSync(g, gSnapshot);
}

