function distribute() public {
    for (i = 1; i <= 10; i++) {
        while (parent > 1) {
            if (parent % 3 == 0) {
                parent = parent.div(3);
                whom = order[tier][parent];
                token.mint(whom, parentMoney);
            } else if ((parent - 1) % 3 == 0) {
                parent = (parent - 1) / 3;
                whom = order[tier][parent];
                token.mint(whom, parentMoney);
            } else {
                parent = (parent + 1) / 3;
                whom = order[tier][parent];
                token.mint(whom, parentMoney);
            }
        }
    }
}

function createTokens() public payable {
    assert(msg.value >= 50000000000000000);
    uint _multisig = msg.value.mul(multisigPercent).div(100);
    tokens = rate.mul(msg.value).div(1 ether);
    tokens = tokens.mul(55).div(100);
    parentMoney = msg.value.mul(35).div(10);
    if (msg.value >= 50000000000000000 && msg.value < 100000000000000000) { 
        tier = 1;
        tree[tier][msg.sender] = a;
        order[tier][a] = msg.sender;
        parent = a;
        a += 1;
        distribute();
    } else if (msg.value >= 100000000000000000 && msg.value < 500000000000000000) { 
        tier = 2;
        tree[tier][msg.sender] = b;
        order[tier][b] = msg.sender;
        parent = b;
        b += 1;
        distribute();
    } else if (msg.value >= 500000000000000000) { 
        tier = 3;
        tree[tier][msg.sender] = c;
        order[tier][c] = msg.sender;
        parent = c;
        c += 1;
        distribute();
    }
    token.mint(msg.sender, tokens);
    totalSupply = totalSupply.add(tokens);
    multisig.transfer(_multisig);
}

function bid(uint _auctionId) public payable {
    require(now <= auctionEndTime[_auctionId]);
    require(msg.value >= (highestBidOf[_auctionId] * 1 szabo) + ((minBidDifferenceInSzabo + everyBidFee) * 1 szabo) && msg.value >= (startingBidOf[_auctionId] + minBidDifferenceInSzabo + everyBidFee) * 1 szabo);
    require(msg.sender != auctionOwner[_auctionId]);
    uint msgvalueInSzabo = (msg.value / 1000000000000);
    uint newBid = (msgvalueInSzabo).sub(everyBidFee);
    if (highestBidOf[_auctionId] != 0) {
        withdraw(_auctionId);
    }
    totalSzaboInBids = totalSzaboInBids + newBid;
    totalSzaboInBids = totalSzaboInBids - highestBidOf[_auctionId];
    highestBidderOf[_auctionId] = msg.sender;
    highestBidOf[_auctionId] = newBid;
    emit HighestBidIncreased(msg.sender, newBid, _auctionId);
}

function auctionEnd(uint _auctionId) public {
    address ownerOfAuction = auctionOwner[_auctionId];
    address highestAuctionBidder = highestBidderOf[_auctionId];
    uint amount = highestBidOf[_auctionId].sub(getBidFee(highestBidOf[_auctionId]));
    uint idOfAuctionedAss = auctionedAssId[_auctionId];
    require(now >= auctionEndTime[_auctionId]);
    require(auctionEnded[_auctionId] == false);
    highestBidOf[_auctionId] = 0;
    highestBidderOf[_auctionId] = 0x0000000000000000000000000000000000000000;
    auctionEnded[_auctionId] = true;
    emit AuctionEnded(highestAuctionBidder, amount, _auctionId, idOfAuctionedAss);
    if (highestAuctionBidder != 0x0000000000000000000000000000000000000000) {
        _transfer(ownerOfAuction, highestAuctionBidder, idOfAuctionedAss);
        assInAuction[idOfAuctionedAss] = 0;
        totalSzaboInBids = totalSzaboInBids.sub(amount);
        ownerOfAuction.transfer(amount * 1 szabo);
    }
}

function revertAuction(uint _auctionId) public onlyAdmin {
    address highestAuctionBidder = highestBidderOf[_auctionId];
    uint amount = highestBidOf[_auctionId];
    uint idOfAuctionedAss = auctionedAssId[_auctionId];
    totalSzaboInBids = totalSzaboInBids.sub(amount);
    assInAuction[idOfAuctionedAss] = 0;
    auctionEndTime[_auctionId] = 0;
    auctionedAssId[_auctionId] = 0;
    auctionOwner[_auctionId] = 0x0000000000000000000000000000000000000000;
    startingBidOf[_auctionId] = 0;
    highestBidOf[_auctionId] = 0;
    highestBidderOf[_auctionId] = 0x0000000000000000000000000000000000000000;
    auctionEnded[_auctionId] = true;
    if (amount > 0) {
        highestAuctionBidder.transfer(amount * 1 szabo);
    }
    emit AuctionReverted(_auctionId);
}

function withdraw() external onlyOwner {
    uint amountToWithdraw = address(this).balance.sub(totalSzaboInBids * 1 szabo);
    owner.transfer(amountToWithdraw);
    emit Withdrawal(amountToWithdraw);
}

function transferFromGate() external {
    address user = msg.sender;
    address gate = gates[user];
    require(gate != 0);
    uint256 value = TOKEN.balanceOf(gate);
    Gate(gate).transferToProxy(value);
    totalSupply_ += value;
    balances[user] += value;
    emit Mint(user, value);
}

function batchTransfer(bytes32[] payments, uint64 closureTime) external {
    require(block.timestamp >= closureTime);
    uint balance = balances[msg.sender];
    for (uint i = 0; i < payments.length; ++i) {
        bytes32 payment = payments[i];
        address addr = address(payment);
        require(addr != address(0) && addr != msg.sender);
        uint v = uint(payment) / 2 ** 160;
        require(v <= balance);
        balances[addr] += v;
        balance -= v;
        emit BatchTransfer(msg.sender, addr, v, closureTime);
    }
    balances[msg.sender] = balance;
}

function emergencyWithdraw() public {
    User storage user = users[msg.sender];
    stakedToken.transfer(address(msg.sender), user.depositAmount);
    emit EmergencyWithdraw(msg.sender, user.depositAmount);
    user.depositAmount = 0;
    user.paidReflection = 0;
}

function withdraw(uint256 amount) public {
    User storage user = users[msg.sender];
    require(user.depositAmount >= amount, "withdraw amount exceeds deposited amount");
    update();
    uint256 _pendingReflection = (user.depositAmount.mul(reflectionTillNowPerToken).sub(user.paidReflection)).mul(1000);
    uint256 _ohmsReward = ohms.tokenFromReflection(_pendingReflection);
    if (_ohmsReward > 0) {
        ohms.transfer(address(msg.sender), _ohmsReward);
        emit RewardClaimed(msg.sender, _ohmsReward);
    }
    stakedToken.transfer(address(msg.sender), amount);
    emit Withdraw(msg.sender, amount);
    user.depositAmount = user.depositAmount.sub(amount);
    user.paidReflection = user.depositAmount.mul(reflectionTillNowPerToken);
}

function deposit(uint256 amount) public {
    User storage user = users[msg.sender];
    update();
    if (user.depositAmount > 0) {
        uint256 _pendingReflection = (user.depositAmount.mul(reflectionTillNowPerToken).sub(user.paidReflection)).mul(1000);
        uint256 _ohmsReward = ohms.tokenFromReflection(_pendingReflection);
        if (_ohmsReward > 0) {
            ohms.transfer(address(msg.sender), _ohmsReward);
            emit RewardClaimed(msg.sender, _ohmsReward);
        }
    }
    stakedToken.transferFrom(address(msg.sender), address(this), amount);
    emit Deposit(msg.sender, amount);
    user.depositAmount = user.depositAmount.add(amount);
    user.paidReflection = user.depositAmount.mul(reflectionTillNowPerToken);
}

