function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(isCrowdsalePaused == false);
    require(validPurchase());
    require(TOKENS_SOLD < maxTokensToSale);
    uint256 weiAmount = msg.value;
    uint256 tokens = 0;
    if (TOKENS_SOLD <= 5000000 * 10 ** 18) {
        tokens = weiAmount.mul(ratePerEthPhase1);
    } else if (TOKENS_SOLD > 5000000 * 10 ** 18 && TOKENS_SOLD <= 15000000 * 10 ** 18) {
        tokens = weiAmount.mul(ratePerEthPhase2);
    } else if (TOKENS_SOLD > 15000000 * 10 ** 18 && TOKENS_SOLD <= 51000000 * 10 ** 18) {
        tokens = weiAmount.mul(ratePerEthPhase3);
    } else {
        revert();
    }
    weiRaised = weiRaised.add(weiAmount);
    token.transfer(beneficiary, tokens);
    emit TokenPurchase(owner, beneficiary, weiAmount, tokens);
    TOKENS_SOLD = TOKENS_SOLD.add(tokens);
    forwardFunds();
}

function manualTransfer(address beneficiary, uint tokens) public onlyOwner {
    token.transfer(beneficiary, tokens);
    emit TokenPurchase(owner, beneficiary, 0, tokens);
    TOKENS_SOLD = TOKENS_SOLD.add(tokens);
}

function _drawDown(address _beneficiary) internal returns(bool) {
    require(vestedAmount[_beneficiary] > 0, "VestingContract::_drawDown: There is no schedule currently in flight");
    uint256 amount = _availableDrawDownAmount(_beneficiary);
    require(amount > 0, "VestingContract::_drawDown: No allowance left to withdraw");
    lastDrawnAt[_beneficiary] = _getNow();
    totalDrawn[_beneficiary] = totalDrawn[_beneficiary].add(amount);
    require(
        totalDrawn[_beneficiary] <= vestedAmount[_beneficiary],
        "VestingContract::_drawDown: Safety Mechanism - Drawn exceeded Amount Vested"
    );
    require(token.transfer(_beneficiary, amount), "VestingContract::_drawDown: Unable to transfer tokens");
    emit DrawDown(_beneficiary, amount);
    return true;
}

function _availableDrawDownAmount(address _beneficiary) internal view returns(uint256 _amount) {
    if (_getNow() <= start.add(cliffDuration)) {
        return 0;
    }
    if (_getNow() > end) {
        return vestedAmount[_beneficiary].sub(totalDrawn[_beneficiary]);
    }
    uint256 timeLastDrawnOrStart = lastDrawnAt[_beneficiary] == 0 ? start : lastDrawnAt[_beneficiary];
    uint256 timePassedSinceLastInvocation = _getNow().sub(timeLastDrawnOrStart);
    uint256 drawDownRate = vestedAmount[_beneficiary].div(end.sub(start));
    uint256 amount = timePassedSinceLastInvocation.mul(drawDownRate);
    return amount;
}

function claimStake() external returns(bool) {
    require(now.div(timingVariable).sub(stakeBalances[msg.sender].unstakeTime) >= 14);
    uint _userStakeBalance = stakeBalances[msg.sender].stakeBalance;
    uint _tokensToMint = calculateStakeGains(stakeBalances[msg.sender].unstakeTime);
    stakeBalances[msg.sender].stakeBalance = 0;
    stakeBalances[msg.sender].initialStakeTime = 0;
    stakeBalances[msg.sender].unstakeTime = 0;
    transferFromContract(_userStakeBalance);
    mint(msg.sender, _tokensToMint);
    emit ClaimStake(msg.sender, _userStakeBalance, _tokensToMint);
    return true;
}

function stakeScale(address _user, uint256 _value) private returns(bool success) {
    require(_value <= balances[msg.sender]);
    require(stakeBalances[_user].unstakeTime == 0);
    transfer(address(this), _value);
    uint _nowAsDay = now.div(timingVariable);
    uint _newStakeBalance = stakeBalances[_user].stakeBalance.add(_value);
    if (stakeBalances[_user].stakeBalance == 0) {
        stakeBalances[_user].initialStakeTime = _nowAsDay;
    }
    stakeBalances[_user].stakeBalance = _newStakeBalance;
    stakeBalances[_user].stakePerDay[_nowAsDay] = _newStakeBalance;
    totalScaleStaked = totalScaleStaked.add(_value);
    setTotalStakingHistory();
    emit Stake(_user, _value);
    return true;
}

function transferFromContract(uint _value) internal {
    require(_value <= balances[address(this)]);
    balances[msg.sender] = balances[msg.sender].add(_value);
    balances[address(this)] = balances[address(this)].sub(_value);
    emit Transfer(address(this), msg.sender, _value);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    bool transferResult;
    uint256 lockQuantity;
    uint256 lockTotalQuantity;
    uint256 lockPeriod;
    require(FreezedWallet[msg.sender] == false);
    require(FreezedWallet[_to] == false);
    if (lockStatus[msg.sender] == false) {
        transferResult = _transfer(msg.sender, _to, _value);
        if (transferResult == true) {
            unlockQuantity[msg.sender] = unlockQuantity[msg.sender].sub(
                _value
            );
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    } else {
        for (uint256 i = 0; i < tokenLockInfo[msg.sender].length; i++) {
            lockQuantity = tokenLockInfo[msg.sender][i].lockQuantity;
            lockPeriod = tokenLockInfo[msg.sender][i].lockPeriod;
            if (lockPeriod <= now && lockQuantity != 0) {
                unlockQuantity[msg.sender] = unlockQuantity[msg.sender].add(
                    lockQuantity
                );
                tokenLockInfo[msg.sender][i].lockQuantity = 0;
                lockQuantity = tokenLockInfo[msg.sender][i].lockQuantity;
            }
            lockTotalQuantity = lockTotalQuantity.add(lockQuantity);
        }
        if (lockTotalQuantity == 0) lockStatus[msg.sender] = false;
        require(_value <= unlockQuantity[msg.sender]);
        transferResult = _transfer(msg.sender, _to, _value);
        if (transferResult == true) {
            unlockQuantity[msg.sender] = unlockQuantity[msg.sender].sub(
                _value
            );
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    }
    return transferResult;
}

function transferFrom(
    address _from,
    address _to,
    uint256 _value
) public returns(bool) {
    bool transferResult;
    uint256 lockQuantity;
    uint256 lockTotalQuantity;
    uint256 lockPeriod;
    require(FreezedWallet[_from] == false);
    require(FreezedWallet[_to] == false);
    if (lockStatus[_from] == false) {
        transferResult = _transferFrom(_from, _to, _value);
        if (transferResult == true) {
            unlockQuantity[_from] = unlockQuantity[_from].sub(_value);
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    } else {
        for (uint256 i = 0; i < tokenLockInfo[_from].length; i++) {
            lockQuantity = tokenLockInfo[_from][i].lockQuantity;
            lockPeriod = tokenLockInfo[_from][i].lockPeriod;
            if (lockPeriod <= now && lockQuantity != 0) {
                unlockQuantity[_from] = unlockQuantity[_from].add(
                    lockQuantity
                );
                tokenLockInfo[_from][i].lockQuantity = 0;
                lockQuantity = tokenLockInfo[_from][i].lockQuantity;
            }
            lockTotalQuantity = lockTotalQuantity.add(lockQuantity);
        }
        if (lockTotalQuantity == 0) lockStatus[_from] = false;
        require(_value <= unlockQuantity[_from]);
        transferResult = _transferFrom(_from, _to, _value);
        if (transferResult == true) {
            unlockQuantity[_from] = unlockQuantity[_from].sub(_value);
            unlockQuantity[_to] = unlockQuantity[_to].add(_value);
        }
    }
    return transferResult;
}

