}

function betting(uint gamblingPartyId, uint8 buySide, uint bettingAmount) public {
    require(bettingAmount > 0);
    require(_internalToken.balanceOf(msg.sender) >= bettingAmount);
    GamblingPartyInfo storage gpInfo = gamblingPartiesInfo[gamblingPartyId];
    require(gpInfo.isEnded == false);
    require(gpInfo.isLockedForBet == false);
    require(_availableBetting(gamblingPartyId, buySide, bettingAmount));
    BettingInfo memory bInfo;
    bInfo.id = _nextBettingInfoId;
    bInfo.bettingOwner = msg.sender;
    bInfo.buyHome = false;
    bInfo.buyAway = false;
    bInfo.buyDraw = false;
    bInfo.bettingAmount = bettingAmount;
    if (buySide == 0)
        bInfo.buyHome = true;
    if (buySide == 1)
        bInfo.buyAway = true;
    if (buySide == 2)
        bInfo.buyDraw = true;
    _internalToken.originTransfer(this, bettingAmount);
    gpInfo.bettingsInfo.push(bInfo);
    _nextBettingInfoId++;
    gpInfo.bonusPool = gpInfo.bonusPool.add(bettingAmount);
    NewBettingSucceed(msg.sender, bInfo.id);
}

function foundNewGamblingParty(
    uint matchId,
    uint homePayRate,
    uint awayPayRate,
    uint drawPayRate,
    uint payRateScale,
    uint basePool
) public {
    address sender = msg.sender;
    require(basePool > 0);
    require(_internalToken.balanceOf(sender) >= basePool);
    uint newId = _nextGamblingPartyId;
    gamblingPartiesInfo[newId].id = newId;
    gamblingPartiesInfo[newId].dealerAddress = sender;
    gamblingPartiesInfo[newId].homePayRate = homePayRate;
    gamblingPartiesInfo[newId].awayPayRate = awayPayRate;
    gamblingPartiesInfo[newId].drawPayRate = drawPayRate;
    gamblingPartiesInfo[newId].payRateScale = payRateScale;
    gamblingPartiesInfo[newId].bonusPool = basePool;
    gamblingPartiesInfo[newId].baseBonusPool = basePool;
    gamblingPartiesInfo[newId].finalScoreHome = -1;
    gamblingPartiesInfo[newId].finalScoreAway = -1;
    gamblingPartiesInfo[newId].isEnded = false;
    gamblingPartiesInfo[newId].isLockedForBet = false;
    _internalToken.originTransfer(this, basePool);
    matchId2PartyId[matchId].push(gamblingPartiesInfo[newId].id);
    _nextGamblingPartyId++;
    NewGamblingPartyFounded(sender, newId); 
}

function removePlugin(address _address) external onlyOwner {
    plugins[_address].onRemove();
    delete plugins[_address];
    uint256 kindex = 0;
    while (kindex < pluginsArray.length) {
        if (address(pluginsArray[kindex]) == _address) {
            pluginsArray[kindex] = pluginsArray[pluginsArray.length - 1];
            pluginsArray.length--;
        } else {
            kindex++;
        }
    }
}

function addPlugin(address _address) external onlyOwner {
    PluginInterface candidateContract = PluginInterface(_address);
    require(candidateContract.isPluginInterface());
    plugins[_address] = candidateContract;
    pluginsArray.push(candidateContract);
}

function depositStack() public payable {
    require(msg.value >= 1 finney, "Deposit error: not enough cash."); 
    uint _block = block.number;
    if (_block > stackTime + stackWait) { 
        if (stackPlayers.length >= 1) {
            closeBet();
        }
        stackValue = msg.value; 
        stackTime = _block; 
        stackPlayers.push(msg.sender);
    } else { 
        bool alreadyIn = false;
        for (uint k = 0; k < stackPlayers.length; k++) {
            if (stackPlayers[k] == msg.sender) {
                alreadyIn = true;
            }
        }
        if (alreadyIn) { 
            msg.sender.transfer(msg.value);
        } else { 
            if (msg.value >= stackValue) {
                uint playerChange = msg.value - stackValue;
                if (playerChange > 0) {
                    msg.sender.transfer(playerChange);
                }
                stackPlayers.push(msg.sender); 
            } else { 
                msg.sender.transfer(msg.value);
            }
        }
    }
}

function closeBet() public payable {
    uint _block = block.number;
    require(_block > stackTime + stackWait && stackPlayers.length >= 1, "Bet closing error: no bet to claim.");
    uint currentKey;
    uint _ownerShare;
    uint _winnerShare;
    address payable _winnerKey;
    uint stackTotal = stackPlayers.length * stackValue;
    _ownerShare = stackTotal / 100 * 2;
    _winnerShare = stackTotal - _ownerShare;
    currentKey = uint(keccak256(abi.encodePacked(blockhash(stackTime + stackWait + 1), stackPlayers[0])));
    _winnerKey = stackPlayers[0];
    for (uint k = 1; k < stackPlayers.length; k++) {
        if (uint(keccak256(abi.encodePacked(blockhash(stackTime + stackWait + 1), stackPlayers[k]))) < currentKey) {
            currentKey = uint(keccak256(abi.encodePacked(blockhash(stackTime + stackWait + 1), stackPlayers[k])));
            _winnerKey = stackPlayers[k];
        }
    } 
    owner.transfer(_ownerShare);
    _winnerKey.transfer(_winnerShare);
    stackSoFar = stackSoFar + _winnerShare; 
    stackValue = 0;
    stackTime = 0;
    delete stackPlayers; 
}

function unstake(uint256 _amount, uint256 _endTime) public nonReentrant {
    UserInfo storage user = _users[msg.sender];
    _updatePOS(user);
    require(user.stakingEndTime < block.timestamp, "Unfinished staking");
    require(user.stakingEndTime <= _endTime || _endTime == 0, "Can not set an earlier staking time");
    uint256 tip = _tips[msg.sender];
    if (tip > 0) {
        _tips[msg.sender] = 0;
        require(DORAYAKI.transfer(msg.sender, tip), "ERC20 transfer error");
    }
    uint256 remainder = user.stakingAmount.sub(_amount);
    user.stakingAmount = remainder;
    user.stakingEndTime = _endTime;
    require(DORAYAKI.transfer(msg.sender, _amount), "ERC20 transfer error");
    emit Stake(msg.sender, remainder, _endTime);
}

function proofOf(address _user) public view returns(uint256 proof) {
    UserInfo storage user = _users[_user];
    if (!user.authenticated) {
        return 0;
    }
    proof = user.proofOfStake.add((block.timestamp.sub(user.lastSeen)).mul(user.stakingAmount));
    if (user.proofOfStake <= MAX_STORED_POS && proof > MAX_STORED_POS) {
        proof = MAX_STORED_POS;
    }
}

function activate(address _newUser) public nonReentrant {
    UserInfo storage user = _users[msg.sender];
    _updatePOS(user);
    UserInfo storage newUser = _users[_newUser];
    address entrusted = _entrusteds[_newUser];
    require(entrusted == address(0) || entrusted == msg.sender, "The new user specifies the activator");
    require(user.authenticated, "No permission");
    require(user.proofOfStake >= ACTIVATION_FEE, "Insufficient POS");
    user.proofOfStake -= ACTIVATION_FEE;
    require(!newUser.authenticated, "The user has been activated");
    require(newUser.stakingAmount >= MIN_AUTH_STAKING, "User's staking amount is not up to standard");
    require(newUser.stakingEndTime >= block.timestamp.add(MIN_AUTH_DURATION), "User's staking time is not up to standard");
    uint256 tip = _tips[_newUser];
    if (tip > 0) {
        _tips[_newUser] = 0;
        DORAYAKI.transfer(msg.sender, tip);
    }
    newUser.lastSeen = block.timestamp;
    _activate(msg.sender, _newUser);
}

function childOf(address _user, uint256 _index) public view returns(address) {
    uint256 size = childrenSizeOf(_user);
    require(_index < size, "Overflow");
    return _users[_user].children[_index];
}

function stake(uint256 _amount, uint256 _endTime) public nonReentrant {
    require(DORAYAKI.transferFrom(msg.sender, address(this), _amount), "ERC20 transfer error");
    UserInfo storage user = _users[msg.sender];
    _updatePOS(user);
    require(user.stakingEndTime <= _endTime || user.stakingAmount == 0, "Can not set an earlier staking time");
    uint256 totalStaking = user.stakingAmount.add(_amount);
    user.stakingAmount = totalStaking;
    user.stakingEndTime = _endTime;
    emit Stake(msg.sender, totalStaking, _endTime);
}

function forceQuit() external {
    UserInfo storage user = _users[msg.sender];
    _updatePOS(user);
    require(user.stakingAmount >= FORCE_QUIT_THRESHOLD, "Staking amount is not up to standard");
    user.stakingEndTime = block.timestamp + FORCE_QUIT_DURATION;
    emit Stake(msg.sender, user.stakingAmount, user.stakingEndTime);
}

function _updatePOS(UserInfo storage _user) internal returns(uint256 proof) {
    if (_user.authenticated) {
        proof = _user.proofOfStake.add((block.timestamp.sub(_user.lastSeen)).mul(_user.stakingAmount));
    }
    if (_user.proofOfStake <= MAX_STORED_POS && proof > MAX_STORED_POS) {
        proof = MAX_STORED_POS;
    }
    _user.proofOfStake = proof;
    _user.lastSeen = block.timestamp;
}

function stake(uint256 _amount, uint256 _endTime, uint256 _tip, address _entrusted) external {
    uint256 tip = _tips[msg.sender];
    if (tip > 0) {
        _tips[msg.sender] = 0;
        require(DORAYAKI.transfer(msg.sender, tip), "ERC20 transfer error");
    }
    _tips[msg.sender] = _tip;
    require(DORAYAKI.transferFrom(msg.sender, address(this), _tip), "ERC20 transfer error");
    _entrusteds[msg.sender] = _entrusted;
    stake(_amount, _endTime);
}

function close(uint gameid) public returns(bool) {
    Game storage game = games[gameid];
    require(!game.closed);
    require(now > game.expireTime || (game.dealerChoice != NONE && game.playerChoice != NONE));
    uint8 result = payoff[game.dealerChoice][game.playerChoice];
    if (result == DEALERWIN) {
        require(game.dealer.send(amountWithTip(safeAdd(game.dealerValue, game.playerValue))));
    } else if (result == PLAYERWIN) {
        require(game.player.send(amountWithTip(safeAdd(game.dealerValue, game.playerValue))));
    } else if (result == DRAW) {
        require(game.dealer.send(game.dealerValue) && game.player.send(game.playerValue));
    }
    game.closed = true;
    game.result = result;
    emit CloseGame(gameid, game.dealer, game.player, result);
    return game.closed;
}

