function claimTokenReserveEcon() onlyTokenReserveEcon locked public {
    address reserveWallet = msg.sender;
    require(block.timestamp > timeLocks[reserveWallet]);
    uint256 vestingStage = econVestingStage();
    uint256 totalUnlocked;
    if (vestingStage <= 72) {
        totalUnlocked = vestingStage.mul(1200000 * (10 ** 8));
    } else { 
        totalUnlocked = ((vestingStage.sub(72)).mul(200000 * (10 ** 8))).add(86400000 * (10 ** 8));
    }
    require(totalUnlocked <= allocations[econReserveWallet]);
    require(claimed[econReserveWallet] < totalUnlocked);
    uint256 payment = totalUnlocked.sub(claimed[econReserveWallet]);
    claimed[econReserveWallet] = totalUnlocked;
    require(token.transfer(reserveWallet, payment));
    Distributed(reserveWallet, payment);
}

function join(bytes32 _hash)
public
payable
circleIsPublic(closed)
ticketIsAffordable(ticketPrice)
returns(uint gameId) {
    require(
        counter < 40,
        "Game is full."
    );
    if (counter == 0) {
        elapsed = block.number;
        emit FirstBlock(block.number);
    }
    player[lastId][msg.sender].commit = _hash;
    if (counter == 39) {
        closed = true;
        uint temp = sub(block.number, elapsed);
        timeout = add(temp, block.number);
        emit LastBlock(timeout);
    }
    counter++;
    emit Join(counter);
    return lastId;
}

function disputePrivateDataExchange(uint256 _exchangeIdx, bytes32 _exchangeKey) external {
    require(_exchangeIdx < privateDataExchanges.length, "invalid exchange index");
    PrivateDataExchange storage exchange = privateDataExchanges[_exchangeIdx];
    require(PrivateDataExchangeState.Accepted == exchange.state, "exchange must be in accepted state");
    require(msg.sender == exchange.dataRequester, "only data requester allowed");
    require(_nowSeconds() < exchange.stateExpired, "exchange must not be expired");
    require(keccak256(abi.encodePacked(_exchangeKey)) == exchange.exchangeKeyHash, "exchange key hash must match");
    bytes32 dataKey = _exchangeKey ^ exchange.encryptedDataKey;
    bool validDataKey = keccak256(abi.encodePacked(dataKey)) == exchange.dataKeyHash;
    exchange.state = PrivateDataExchangeState.Closed;
    uint256 val = exchange.dataRequesterValue.add(exchange.passportOwnerValue);
    address cheater;
    if (validDataKey) { 
        require(exchange.passportOwner.send(val));
        cheater = exchange.dataRequester;
    } else { 
        require(exchange.dataRequester.send(val));
        cheater = exchange.passportOwner;
    }
    _decOpenPrivateDataExchangesCount();
    emit PrivateDataExchangeClosed(_exchangeIdx);
    emit PrivateDataExchangeDisputed(_exchangeIdx, !validDataKey, cheater);
}

function timeoutPrivateDataExchange(uint256 _exchangeIdx) external {
    require(_exchangeIdx < privateDataExchanges.length, "invalid exchange index");
    PrivateDataExchange storage exchange = privateDataExchanges[_exchangeIdx];
    require(PrivateDataExchangeState.Proposed == exchange.state, "exchange must be in proposed state");
    require(msg.sender == exchange.dataRequester, "only data requester allowed");
    require(_nowSeconds() > exchange.stateExpired, "exchange must be expired");
    exchange.state = PrivateDataExchangeState.Closed;
    require(exchange.dataRequester.send(exchange.dataRequesterValue));
    _decOpenPrivateDataExchangesCount();
    emit PrivateDataExchangeClosed(_exchangeIdx);
}

function finishPrivateDataExchange(uint256 _exchangeIdx) external {
    require(_exchangeIdx < privateDataExchanges.length, "invalid exchange index");
    PrivateDataExchange storage exchange = privateDataExchanges[_exchangeIdx];
    require(PrivateDataExchangeState.Accepted == exchange.state, "exchange must be in accepted state");
    require(_nowSeconds() > exchange.stateExpired || msg.sender == exchange.dataRequester, "exchange must be either expired or be finished by the data requester");
    exchange.state = PrivateDataExchangeState.Closed;
    uint256 val = exchange.dataRequesterValue.add(exchange.passportOwnerValue);
    require(exchange.passportOwner.send(val));
    _decOpenPrivateDataExchangesCount();
    emit PrivateDataExchangeClosed(_exchangeIdx);
}

function _nowSeconds() private view returns(uint256) {
    uint256 t = now;
    if (t > 150000000000000000) {
        t /= 1000000000;
    }
    return t;
}

function acceptPrivateDataExchange(uint256 _exchangeIdx, bytes32 _encryptedDataKey) external payable {
    require(_exchangeIdx < privateDataExchanges.length, "invalid exchange index");
    PrivateDataExchange storage exchange = privateDataExchanges[_exchangeIdx];
    require(msg.sender == exchange.passportOwner, "only passport owner allowed");
    require(PrivateDataExchangeState.Proposed == exchange.state, "exchange must be in proposed state");
    require(msg.value >= exchange.dataRequesterValue, "need to stake at least data requester amount");
    require(_nowSeconds() < exchange.stateExpired, "exchange state expired");
    exchange.passportOwnerValue = msg.value;
    exchange.encryptedDataKey = _encryptedDataKey;
    exchange.state = PrivateDataExchangeState.Accepted;
    exchange.stateExpired = _nowSeconds() + privateDataExchangeAcceptTimeout;
    emit PrivateDataExchangeAccepted(_exchangeIdx, exchange.dataRequester, msg.sender);
}

function createTokens() saleIsOn payable {
    require(msg.value >= minPaymentWei);
    uint tokens = rate.mul(msg.value).div(1 ether);
    uint bonusTokens = 0;
    if (now <= startPresale + (periodPresale * 1 days)) {
        require(totalTokensSold.add(tokens) <= maxCapTokenPresale);
        bonusTokens = tokens.div(100).mul(50);
    } else {
        require(totalTokensSold.add(tokens) <= maxCapTokenTotal);
        if (now < startSale + (15 * 1 days)) {
            bonusTokens = tokens.div(100).mul(25);
        } else if (now < startSale + (25 * 1 days)) {
            bonusTokens = tokens.div(100).mul(15);
        } else if (now < startSale + (35 * 1 days)) {
            bonusTokens = tokens.div(100).mul(7);
        }
    }
    totalTokensSold = totalTokensSold.add(tokens);
    totalWeiReceived = totalWeiReceived.add(msg.value);
    uint tokensWithBonus = tokens.add(bonusTokens);
    multisig.transfer(msg.value);
    token.transfer(msg.sender, tokensWithBonus);
}

function getVIATokens() public {
    require(now > startSale + (91 * 1 days));
    address contractAddress = address(this);
    uint allTokens = token.balanceOf(contractAddress).sub(restrictedTeam);
    token.transfer(restricted_address, allTokens);
}

function getTeamTokens() public {
    require(now > startSale + (180 * 1 days));
    token.transfer(restricted_address, restrictedTeam);
}

function attackTile(address _msgSender, uint16 _tileId, uint _attackAmount, bool _useBattleValue, bool _autoFortify) public isValidCaller {
    require(_attackAmount >= 1 finney); 
    require(_attackAmount % 1 finney == 0);
    address claimer;
    uint blockValue;
    (claimer, blockValue) = bwData.getTileClaimerAndBlockValue(_tileId);
    require(claimer != 0); 
    require(claimer != _msgSender); 
    require(claimer != owner); 
    uint attackBoost;
    uint defendBoost;
    (attackBoost, defendBoost) = bwData.calculateBattleBoost(_tileId, _msgSender, claimer);
    uint totalAttackAmount = _attackAmount + attackBoost;
    uint totalDefendAmount = blockValue + defendBoost;
    require(totalAttackAmount >= _attackAmount); 
    require(totalDefendAmount >= blockValue); 
    require(totalAttackAmount + totalDefendAmount > totalAttackAmount && totalAttackAmount + totalDefendAmount > totalDefendAmount); 
    require(totalAttackAmount / 10 <= blockValue); 
    require(totalAttackAmount >= blockValue / 10); 
    uint attackRoll = random(totalAttackAmount + totalDefendAmount); 
    if (attackRoll > totalDefendAmount) {
        emit TileAttackedSuccessfully(_tileId, _msgSender, _attackAmount, totalAttackAmount, claimer, blockValue, totalDefendAmount, attackRoll, block.timestamp);
        bwData.setClaimerForTile(_tileId, _msgSender);
        if (_useBattleValue) {
            if (_autoFortify) {
                fortifyClaim(_msgSender, _tileId, _attackAmount);
                subUserBattleValue(_msgSender, _attackAmount, false);
            } else {
            }
        } else {
            if (_autoFortify) {
                fortifyClaim(_msgSender, _tileId, _attackAmount);
            } else {
                addUserBattleValue(_msgSender, _attackAmount); 
            }
        }
    } else {
        if (_useBattleValue) {
            subUserBattleValue(_msgSender, _attackAmount, false); 
        }
        addUserBattleValue(claimer, _attackAmount); 
        emit TileDefendedSuccessfully(_tileId, _msgSender, _attackAmount, totalAttackAmount, claimer, blockValue, totalDefendAmount, attackRoll, block.timestamp);
        bwData.updateTileTimeStamp(_tileId);
    }
}

function fillBuyOrder(uint _key) public {
    uint order = orderBook.get(_key);
    ORDER_TYPE orderType = ORDER_TYPE(order >> 254);
    require(orderType == ORDER_TYPE.BUY, "This is not a buy order");
    uint index = addressRegister(msg.sender);
    require(index != (order << 2) >> 224, "You cannot fill your own order");
    uint price = (order << 34) >> 145;
    uint amount = (order << 145) >> 145;
    uint orderFee = feeForOrder(price, amount);
    require(feeBalances[index] >= orderFee, "You do not have enough deposited fees to fill this order");
    uint cost = price.mul(amount).div(1 ether);
    require(orderBook.remove(_key), "Map remove failed");
    msg.sender.transfer(cost);
    poolOwners.sendOwnershipFrom(msg.sender, addressRegistry[(order << 2) >> 224], amount);
    if (orderFee > 0) {
        feeBalances[index] = feeBalances[index].sub(orderFee);
        uint totalFee = orderFee.mul(2);
        totalFees = totalFees.sub(totalFee);
        feeToken.transfer(poolOwners, totalFee);
    }
    emit OrderFilled(orderType, addressRegistry[(order << 2) >> 224], msg.sender, price, amount);
}

function fillSellOrder(uint _key) public payable {
    uint order = orderBook.get(_key);
    ORDER_TYPE orderType = ORDER_TYPE(order >> 254);
    require(orderType == ORDER_TYPE.SELL, "This is not a sell order");
    uint index = addressRegister(msg.sender);
    require(index != (order << 2) >> 224, "You cannot fill your own order");
    uint price = (order << 34) >> 145;
    uint amount = (order << 145) >> 145;
    uint orderFee = feeForOrder(price, amount);
    require(feeBalances[index] >= orderFee, "You do not have enough deposited fees to fill this order");
    uint cost = price.mul(amount).div(1 ether);
    require(msg.value == cost, "ETH sent needs to equal the cost");
    require(orderBook.remove(_key), "Map remove failed");
    addressRegistry[(order << 2) >> 224].transfer(msg.value);
    poolOwners.sendOwnership(msg.sender, amount);
    if (orderFee > 0) {
        feeBalances[index] = feeBalances[index].sub(orderFee);
        uint totalFee = orderFee.mul(2);
        totalFees = totalFees.sub(totalFee);
        feeToken.transfer(poolOwners, totalFee);
    }
    emit OrderFilled(orderType, addressRegistry[(order << 2) >> 224], msg.sender, price, amount);
}

function addSellOrder(uint _price, uint _amount) public {
    require(is111bit(_price) && is111bit(_amount), "Price or amount exceeds 111 bits");
    require(_price > 0, "Price needs to be greater than 0");
    require(_amount > 0, "Amount needs to be greater than 0");
    uint orderFee = feeForOrder(_price, _amount);
    uint index = addressRegister(msg.sender);
    if (orderFee > 0) {
        require(feeBalances[index] >= orderFee, "You do not have enough deposited for fees");
        feeBalances[index] = feeBalances[index].sub(orderFee);
    }
    poolOwners.sendOwnershipFrom(msg.sender, this, _amount);
    require(
        !orderBook.insert(orderCount, (((uint(ORDER_TYPE.SELL) << 32 | index) << 111 | _price) << 111) | _amount),
        "Map replacement detected"
    );
    orderCount += 1;
    emit NewOrder(ORDER_TYPE.SELL, msg.sender, _price, _amount);
}

function removeBuyOrder(uint _key) public {
    uint order = orderBook.get(_key);
    ORDER_TYPE orderType = ORDER_TYPE(order >> 254);
    require(orderType == ORDER_TYPE.BUY, "This is not a buy order");
    uint index = addressIndex[msg.sender];
    require(index == (order << 2) >> 224, "You are not the sender of this order");
    uint price = (order << 34) >> 145;
    uint amount = (order << 145) >> 145;
    require(orderBook.remove(_key), "Map remove failed");
    uint orderFee = feeForOrder(price, amount);
    if (orderFee > 0) {
        feeBalances[index] = feeBalances[index].add(orderFee);
    }
    uint cost = price.mul(amount).div(1 ether);
    msg.sender.transfer(cost);
    emit OrderRemoved(orderType, msg.sender, price, amount);
}

function unlockAllocationAddress(
    address allocationAddress
) public onlyOwner returns(bool) {
    require(token != address(0));
    token.setInitialAllocationUnlock(allocationAddress);
    for (uint idx = 0; idx < lockedAddressesList.length; idx++) {
        if (lockedAddressesList[idx] == allocationAddress) {
            lockedAddressesList[idx] = address(0);
            break;
        }
    }
    return true;
}

function lockAllocationAddress(
    address allocationAddress
) public onlyOwner returns(bool) {
    require(token != address(0));
    token.setInitialAllocationLock(allocationAddress);
    lockedAddressesList.push(allocationAddress);
    return true;
}

function finalize() public onlyOwner {
    if (finalizeType == "transfer") {
        token.transfer(
            token.allocationAddressesTypes(finalizeTransferAddressType),
            token.balanceOf(this)
        );
    } else if (finalizeType == "burn") {
        token.burn(token.balanceOf(this));
    }
    require(unlockAllAllocationAddresses());
    removeOwnership();
    isFinalized = true;
    emit Finalized();
}

function multivestMint(
    address _address,
    uint256 _amount,
    uint8 _v,
    bytes32 _r,
    bytes32 _s
) public onlyAllowedMultivests(verify(keccak256(msg.sender, _amount), _v, _r, _s)) {
    _amount = _amount.mul(10 ** DECIMALS);
    require(
        claimed[_address] == false &&
        _address == msg.sender &&
        _amount > 0 &&
        _amount <= totalSupply &&
        _amount == token.mint(_address, _amount)
    );
    totalSupply = totalSupply.sub(_amount);
    claimed[_address] = true;
    lockupContract.log(_address, _amount);
}

function burnUnsoldTokens() public onlyOwner {
    if (block.timestamp >= tiers[PRE_ICO_TIER].endTime && preICOStats.burned == false) {
        token.burnTokens(tiers[PRE_ICO_TIER].maxAmount.sub(preICOStats.soldTokens));
        preICOStats.burned = true;
    }
    if (block.timestamp >= endTime && maxTokenSupply > soldTokens) {
        token.burnTokens(maxTokenSupply.sub(soldTokens));
        maxTokenSupply = soldTokens;
    }
}

function refund() public returns(bool) {
    uint256 balance = etherBalances[msg.sender];
    if (!isRefundPossible() || balance == 0) {
        return false;
    }
    uint256 burnedAmount = token.burnInvestorTokens(msg.sender, icoBalances[msg.sender]);
    if (burnedAmount == 0) {
        return false;
    }
    if (icoLockedBalance[msg.sender] > 0) {
        lockupContract.decreaseAfterBurn(msg.sender, icoLockedBalance[msg.sender]);
    }
    Refund(msg.sender, balance, burnedAmount);
    etherBalances[msg.sender] = 0;
    msg.sender.transfer(balance);
    return true;
}

function claimUnsoldTokens() public {
    if (msg.sender == tokenHolder && totalSupply > 0) {
        require(totalSupply == token.mint(msg.sender, totalSupply));
        totalSupply = 0;
    }
}

function buy(address _address, uint256 _value) internal returns(bool) {
    if (_value == 0 || _address == address(0)) {
        return false;
    }
    uint8 activeTier = getActiveTier();
    if (activeTier == tiers.length) {
        return false;
    }
    uint256 tokenAmount;
    uint256 usdAmount;
    uint256 mintedAmount;
    (tokenAmount, usdAmount) = calculateTokensAmount(_value, true);
    require(usdAmount > 0 && tokenAmount > 0);
    if (usdAmount >= lockupThreshold) {
        lockupContract.logLargeContribution(_address, tokenAmount);
        icoLockedBalance[_address] = icoLockedBalance[_address].add(tokenAmount);
    }
    if (activeTier == PRE_ICO_TIER) {
        mintedAmount = mintPreICO(_address, tokenAmount, _value, usdAmount);
    } else {
        mintedAmount = mintInternal(_address, tokenAmount);
        collectedEthers = collectedEthers.add(_value);
        collectedUSD = collectedUSD.add(usdAmount);
        require(hardCap >= collectedUSD);
        etherBalances[_address] = etherBalances[_address].add(_value);
        icoBalances[_address] = icoBalances[_address].add(tokenAmount);
    }
    Contribution(_address, _value, tokenAmount);
    return true;
}

function burnUnsoldTokens() public onlyOwner {
    if (block.timestamp >= endTime && maxTokenSupply > soldTokens) {
        token.burnTokens(maxTokenSupply.sub(soldTokens));
        maxTokenSupply = soldTokens;
    }
}

function freezing(bool _transferFrozen) public onlyOwner {
    if (address(ico) != address(0) && !ico.isActive() && block.timestamp >= ico.startTime()) {
        transferFrozen = _transferFrozen;
    }
}

function isTransferAllowed(address _address, uint256 _value) public view returns(bool) {
    if (ico.endTime().add(lockPeriod) < block.timestamp) {
        return checkLargeContributionsLock(_address, _value);
    }
    if (token.balanceOf(_address).sub(lockedAmount[_address]) >= _value) {
        return checkLargeContributionsLock(_address, _value);
    }
    return false;
}

function getActiveTier() public view returns(uint8) {
    for (uint8 i = 0; i < tiers.length; i++) {
        if (block.timestamp >= tiers[i].startTime && block.timestamp <= tiers[i].endTime) {
            return i;
        }
    }
    return uint8(tiers.length);
}

function isRefundPossible() public view returns(bool) {
    if (getActiveTier() != tiers.length || block.timestamp < startTime || collectedUSD >= softCap) {
        return false;
    }
    return true;
}

function checkLargeContributionsLock(address _address, uint256 _value) public view returns(bool) {
    if (ico.endTime().add(contributionLockPeriod) < block.timestamp) {
        return true;
    }
    if (token.balanceOf(_address).sub(lockedContributions[_address]) >= _value) {
        return true;
    }
    return false;
}

function buy(address _address, uint256 _value) internal returns(bool) {
    if (_value == 0) {
        return false;
    }
    require(_address != address(0) && withinPeriod());
    uint256 tokenAmount;
    uint256 usdAmount;
    (tokenAmount, usdAmount) = calculateTokensAmount(_value);
    uint256 mintedAmount = token.mint(_address, tokenAmount);
    soldTokens = soldTokens.add(tokenAmount);
    require(mintedAmount == tokenAmount && maxTokenSupply >= soldTokens && usdAmount > 0 && mintedAmount > 0);
    collectedEthers = collectedEthers.add(_value);
    collectedUSD = collectedUSD.add(usdAmount);
    Contribution(_address, _value, tokenAmount);
    etherHolder.transfer(this.balance);
    return true;
}

function calculateEthersAmount(uint256 _amount) public view returns(uint256 ethersAmount) {
    uint8 activeTier = getActiveTier();
    if (activeTier == tiers.length) {
        if (endTime < block.timestamp) {
            return 0;
        }
        if (startTime > block.timestamp) {
            activeTier = PRE_ICO_TIER;
        }
    }
    if (_amount == 0 || _amount.mul(tiers[activeTier].price) < minPurchase) {
        return 0;
    }
    ethersAmount = _amount.mul(tiers[activeTier].price).div(etherPriceInUSD);
}

function calculateTokensAmount(uint256 _value, bool _isEther) public view returns(
    uint256 tokenAmount,
    uint256 currencyAmount
) {
    uint8 activeTier = getActiveTier();
    if (activeTier == tiers.length) {
        if (endTime < block.timestamp) {
            return (0, 0);
        }
        if (startTime > block.timestamp) {
            activeTier = PRE_ICO_TIER;
        }
    }
    if (_isEther) {
        currencyAmount = _value.mul(etherPriceInUSD);
        tokenAmount = currencyAmount.div(tiers[activeTier].price);
        if (currencyAmount < minPurchase.mul(1 ether)) {
            return (0, 0);
        }
        currencyAmount = currencyAmount.div(1 ether);
    } else {
        if (_value < minPurchase) {
            return (0, 0);
        }
        currencyAmount = uint256(1 ether).mul(_value).div(etherPriceInUSD);
        tokenAmount = _value.mul(uint256(10) ** DECIMALS).div(tiers[activeTier].price);
    }
}

function transfer(address _to, uint _value) public returns(bool) {
    require(msg.sender == bountyAddress || transferAllowed(msg.sender, _value));
    if (msg.sender == bountyAddress) {
        lockupContract.log(_to, _value);
    }
    return super.transfer(_to, _value);
}

function transferFrom(address _from, address _to, uint _value) public returns(bool success) {
    require(_from == bountyAddress || transferAllowed(_from, _value));
    if (_from == bountyAddress) {
        lockupContract.log(_to, _value);
    }
    return super.transferFrom(_from, _to, _value);
}

function mintInternal(address _address, uint256 _tokenAmount) internal returns(uint256) {
    uint256 mintedAmount = token.mint(_address, _tokenAmount);
    require(mintedAmount == _tokenAmount);
    mintedAmount = mintedAmount.add(token.mint(compensationAddress, _tokenAmount.mul(5).div(1000)));
    soldTokens = soldTokens.add(_tokenAmount);
    if (maxTokenSupply > 0) {
        require(maxTokenSupply >= soldTokens);
    }
    return _tokenAmount;
}

function mintPreICO(
    address _address,
    uint256 _tokenAmount,
    uint256 _ethAmount,
    uint256 _usdAmount
) internal returns(uint256) {
    uint256 mintedAmount = token.mint(_address, _tokenAmount);
    require(mintedAmount == _tokenAmount);
    preICOStats.soldTokens = preICOStats.soldTokens.add(_tokenAmount);
    preICOStats.collectedEthers = preICOStats.collectedEthers.add(_ethAmount);
    preICOStats.collectedUSD = preICOStats.collectedUSD.add(_usdAmount);
    require(tiers[PRE_ICO_TIER].maxAmount >= preICOStats.soldTokens);
    if (preICOStats.collectedUSD <= compensationAmount) {
        compensatedAmount = compensatedAmount.add(_usdAmount);
        compensationAddress.transfer(this.balance);
    }
    return _tokenAmount;
}

function withdraw(
    address erc20,
    uint tokenAmt
) external payable {
    uint amt;
    if (erc20 == getEthAddr()) {
        amt = tokenAmt == uint(-1) ? address(this).balance : tokenAmt;
        msg.sender.transfer(amt);
    } else {
        TokenInterface token = TokenInterface(erc20);
        amt = tokenAmt == uint(-1) ? token.balanceOf(address(this)) : tokenAmt;
        token.transfer(msg.sender, amt);
    }
    emit LogWithdraw(erc20, amt, msg.sender);
    bytes32 _eventCode = keccak256("LogWithdraw(address,uint256,address)");
    bytes memory _eventParam = abi.encode(erc20, amt, msg.sender);
    (uint _type, uint _id) = connectorID();
    EventInterface(getEventAddr()).emitEvent(_type, _id, _eventCode, _eventParam);
}

function insertHash(uint16 year, uint8 month, uint8 day, string hash) onlyOwner public {
    dt = new DateTime();
    uint t = dt.toTimestamp(year, month, day);
    event_details[t] = hash;
}

function transfer(address _to, uint256 _value) public returns(bool success) {
    require(!paused);
    require(msg.sender != cfoAddress);
    require(msg.sender != _to);
    if (_balancesMap[msg.sender].unlockLeft > 0) {
        UserToken storage sender = _balancesMap[msg.sender];
        uint256 diff = now.sub(sender.unlockLastTime);
        uint256 round = diff.div(sender.unlockPeriod);
        if (round > 0) {
            uint256 unlocked = sender.unlockUnit.mul(round);
            if (unlocked > sender.unlockLeft) {
                unlocked = sender.unlockLeft;
            }
            sender.unlockLeft = sender.unlockLeft.sub(unlocked);
            sender.tokens = sender.tokens.add(unlocked);
            sender.unlockLastTime = sender.unlockLastTime.add(sender.unlockPeriod.mul(round));
            emit Unlock(msg.sender, unlocked);
            log(actionUnlock, msg.sender, 0, unlocked, 0, 0);
        }
    }
    require(_balancesMap[msg.sender].tokens >= _value);
    _balancesMap[msg.sender].tokens = _balancesMap[msg.sender].tokens.sub(_value);
    uint index = _balancesMap[_to].index;
    if (index == 0) {
        UserToken memory user;
        user.index = _balancesArray.length;
        user.addr = _to;
        user.tokens = _value;
        user.unlockUnit = 0;
        user.unlockPeriod = 0;
        user.unlockLeft = 0;
        user.unlockLastTime = 0;
        _balancesMap[_to] = user;
        _balancesArray.push(_to);
    } else {
        _balancesMap[_to].tokens = _balancesMap[_to].tokens.add(_value);
    }
    emit Transfer(msg.sender, _to, _value);
    log(actionTransfer, msg.sender, _to, _value, 0, 0);
    success = true;
}

function grant(address _to, uint256 _value, uint256 _duration, uint256 _periods) public returns(bool success) {
    require(msg.sender != _to);
    require(_balancesMap[msg.sender].tokens >= _value);
    require(_balancesMap[_to].unlockLastTime == 0);
    _balancesMap[msg.sender].tokens = _balancesMap[msg.sender].tokens.sub(_value);
    if (_balancesMap[_to].index == 0) {
        UserToken memory user;
        user.index = _balancesArray.length;
        user.addr = _to;
        user.tokens = 0;
        user.unlockUnit = _value.div(_periods);
        user.unlockPeriod = _duration.mul(1 days).div(_periods); 
        user.unlockLeft = _value;
        user.unlockLastTime = now;
        _balancesMap[_to] = user;
        _balancesArray.push(_to);
    } else {
        _balancesMap[_to].unlockUnit = _value.div(_periods);
        _balancesMap[_to].unlockPeriod = _duration.mul(1 days).div(_periods); 
        _balancesMap[_to].unlockLeft = _value;
        _balancesMap[_to].unlockLastTime = now;
    }
    emit Grant(msg.sender, _to, _value);
    log(actionGrant, msg.sender, _to, _value, _duration, _periods);
    success = true;
}

function getLog(uint256 _index) public view returns(uint time, uint32 action, address from, address to, uint256 _v1, uint256 _v2, uint256 _v3) {
    require(_index < _logs.length);
    require(_index >= 0);
    LogEntry storage entry = _logs[_index];
    action = entry.action;
    time = entry.time;
    from = entry.from;
    to = entry.to;
    _v1 = entry.v1;
    _v2 = entry.v2;
    _v3 = entry.v3;
}

function addConnector(IERC20Token _token, uint32 _weight, bool _enableVirtualBalance)
public
ownerOnly
inactive
validAddress(_token)
notThis(_token)
validConnectorWeight(_weight) {
    require(_token != token && !connectors[_token].isSet && totalConnectorWeight + _weight <= MAX_WEIGHT); 
    connectors[_token].virtualBalance = 0;
    connectors[_token].weight = _weight;
    connectors[_token].isVirtualBalanceEnabled = _enableVirtualBalance;
    connectors[_token].isPurchaseEnabled = true;
    connectors[_token].isSet = true;
    connectorTokens.push(_token);
    totalConnectorWeight += _weight;
}

function sell(IERC20Token _connectorToken, uint256 _sellAmount, uint256 _minReturn) internal returns(uint256) {
    require(_sellAmount <= token.balanceOf(msg.sender)); 
    uint256 amount = getSaleReturn(_connectorToken, _sellAmount);
    require(amount != 0 && amount >= _minReturn);
    uint256 tokenSupply = token.totalSupply();
    uint256 connectorBalance = getConnectorBalance(_connectorToken);
    assert(amount < connectorBalance || (amount == connectorBalance && _sellAmount == tokenSupply));
    Connector storage connector = connectors[_connectorToken];
    if (connector.isVirtualBalanceEnabled)
        connector.virtualBalance = safeSub(connector.virtualBalance, amount);
    token.destroy(msg.sender, _sellAmount);
    assert(_connectorToken.transfer(msg.sender, amount));
    uint256 feeAmount = safeSub(amount, getFinalAmount(amount, 1));
    dispatchConversionEvent(token, _connectorToken, _sellAmount, amount, feeAmount);
    emit PriceDataUpdate(_connectorToken, token.totalSupply(), getConnectorBalance(_connectorToken), connector.weight);
    return amount;
}

function convertInternal(IERC20Token _fromToken, IERC20Token _toToken, uint256 _amount, uint256 _minReturn)
public
bancorNetworkOnly
conversionsAllowed
greaterThanZero(_minReturn)
returns(uint256) {
    require(_fromToken != _toToken); 
    if (_toToken == token)
        return buy(_fromToken, _amount, _minReturn);
    else if (_fromToken == token)
        return sell(_toToken, _amount, _minReturn);
    uint256 amount = getCrossConnectorReturn(_fromToken, _toToken, _amount);
    require(amount != 0 && amount >= _minReturn);
    Connector storage fromConnector = connectors[_fromToken];
    if (fromConnector.isVirtualBalanceEnabled)
        fromConnector.virtualBalance = safeAdd(fromConnector.virtualBalance, _amount);
    Connector storage toConnector = connectors[_toToken];
    if (toConnector.isVirtualBalanceEnabled)
        toConnector.virtualBalance = safeSub(toConnector.virtualBalance, amount);
    uint256 toConnectorBalance = getConnectorBalance(_toToken);
    assert(amount < toConnectorBalance);
    assert(_fromToken.transferFrom(msg.sender, this, _amount));
    assert(_toToken.transfer(msg.sender, amount));
    uint256 feeAmount = safeSub(amount, getFinalAmount(amount, 2));
    dispatchConversionEvent(_fromToken, _toToken, _amount, amount, feeAmount);
    emit PriceDataUpdate(_fromToken, token.totalSupply(), getConnectorBalance(_fromToken), fromConnector.weight);
    emit PriceDataUpdate(_toToken, token.totalSupply(), getConnectorBalance(_toToken), toConnector.weight);
    return amount;
}

function buy(IERC20Token _connectorToken, uint256 _depositAmount, uint256 _minReturn) internal returns(uint256) {
    uint256 amount = getPurchaseReturn(_connectorToken, _depositAmount);
    require(amount != 0 && amount >= _minReturn);
    Connector storage connector = connectors[_connectorToken];
    if (connector.isVirtualBalanceEnabled)
        connector.virtualBalance = safeAdd(connector.virtualBalance, _depositAmount);
    assert(_connectorToken.transferFrom(msg.sender, this, _depositAmount));
    token.issue(msg.sender, amount);
    uint256 feeAmount = safeSub(amount, getFinalAmount(amount, 1));
    dispatchConversionEvent(_connectorToken, token, _depositAmount, amount, feeAmount);
    emit PriceDataUpdate(_connectorToken, token.totalSupply(), getConnectorBalance(_connectorToken), connector.weight);
    return amount;
}

