function bid(uint16 _activityId, uint16 _packId)
external
payable
whenNotPaused {
    bool isPause;
    uint16 buyLimit;
    uint128 packPrice;
    uint64 startDate;
    uint64 endDate;
    (isPause, buyLimit, packPrice, startDate, endDate) = activityStorage.activities(_activityId);
