function optionPoolMembersLockTotalOf(address _memAdd) public view returns(uint _optionPoolMembersLockTotal) {
    if (optionPoolMembers[_memAdd] != true) {
        return 0;
    }
    uint unlockPercent = 0;
    for (uint8 i = 0; i < optionPoolMembersUnlockPlans.length; i++) {
        if (now >= optionPoolMembersUnlockPlans[i][0]) {
            unlockPercent = optionPoolMembersUnlockPlans[i][1];
        } else {
            break;
        }
    }
    return optionPoolLockTotal * (100 - unlockPercent) / 100;
}

function inAllocationLockPeriod() constant returns(bool) {
    return (block.timestamp < ALLOCATION_LOCK_END_TIMESTAMP);
}

function transferFrom(address from, address to, uint tokens) onlyPayloadSize(3 * 32) {
    if (isAllocationLocked(from) || isAllocationLocked(to)) {
        throw;
    } else {
        super.transferFrom(from, to, tokens);
    }
}

function isAllocationLocked(address _spender) constant returns(bool) {
    return inAllocationLockPeriod() && isTeamMember(_spender);
}

function lock(uint256 lockTime) public onlyOwner returns(bool) {
    require(!isLocked);
    require(tokenBalance() > 0);
    start_time = now;
    end_time = lockTime;
    isLocked = true;
}

function unwrap(address user, uint amount, uint fee, uint bscNonce) external onlyOwner {
    require(user != address(0), "ERC20ToBEP20Wrapper: Can't be zero address");
    require(bscToEthUserUnwrapNonces[user][bscNonce] == 0, "ERC20ToBEP20Wrapper: Already processed");
    NBU.transfer(user, amount - fee);
    uint unwrapNonce = ++userUnwrapNonces[user];
    bscToEthUserUnwrapNonces[user][bscNonce] = unwrapNonce;
    unwraps[user][unwrapNonce].amount = amount;
    unwraps[user][unwrapNonce].fee = fee;
    unwraps[user][unwrapNonce].bscNonce = bscNonce;
    emit Unwrap(user, unwrapNonce, bscNonce, amount, fee);
}

function wrap(uint amount) external {
    require(amount >= minWrapAmount, "ERC20ToBEP20Wrapper: Value too small");
    NBU.transferFrom(msg.sender, address(this), amount);
    uint userWrapNonce = ++userWrapNonces[msg.sender];
    wraps[msg.sender][userWrapNonce] = amount;
    emit Wrap(msg.sender, userWrapNonce, amount);
}

function ClaimReward() public {
    require(pendingReward(msg.sender) > 0, "nothing pending to claim");
    require(ERC20Interface(SBX).transfer(msg.sender, pendingReward(msg.sender)));
    emit RewardClaimed(msg.sender, pendingReward(msg.sender));
    totalRewards = totalRewards.add(pendingReward(msg.sender));
    users[msg.sender].totalGained = users[msg.sender].totalGained.add(pendingReward(msg.sender));
    users[msg.sender].lastClaimedDate = now;
    users[msg.sender].pendingGains = 0;
}

function ClaimStakedTokens() external {
    require(users[msg.sender].activeDeposit > 0, "no running stake");
    uint256 _penaltyFee = 0;
    if (users[msg.sender].startTime + latestStakingPeriod() > now) { 
        _penaltyFee = penaltyFee;
    }
    uint256 toTransfer = users[msg.sender].activeDeposit.sub(_onePercent(users[msg.sender].activeDeposit).mul(_penaltyFee));
    require(ERC20Interface(SBX).transfer(msg.sender, toTransfer));
    users[msg.sender].pendingGains = pendingReward(msg.sender);
    emit TokensClaimed(msg.sender, toTransfer);
    users[msg.sender].activeDeposit = 0;
}

function GetDiv() public payable {
    if (receiver == msg.sender && now > unlockTime) {
        msg.sender.transfer(address(this).balance);
    }
}

function epoch(uint256 ETHPerToken) public onlyOwnerOrOperator {
    uint256 balance = pendingBalance();
    uint256 withdrawable = harvest(balance.mul(ETHPerToken).div(1 ether));
    lastEpochTime = block.timestamp;
    lastBalance = lastBalance.add(balance);
    uint256 currentWithdrawd = vault.totalYieldWithdrawed();
    uint256 withdrawAmountToken = currentWithdrawd.sub(lastYieldWithdrawed);
    if (withdrawAmountToken > 0) {
        lastYieldWithdrawed = currentWithdrawd;
        uint256 ethWithdrawed = withdrawAmountToken.mul(
            ETHPerToken
        ).div(1 ether);
        withdrawFromYearn(ethWithdrawed.add(withdrawable));
        ethPushedToYearn = ethPushedToYearn.sub(ethWithdrawed);
    } else {
        if (withdrawable > 0) {
            withdrawFromYearn(withdrawable);
        }
    }
}

function harvest(uint256 ethBalance) private returns(
    uint256 withdrawable
) {
    uint256 rewards = calculateRewards();
    uint256 depositable = ethBalance > rewards ? ethBalance.sub(rewards) : 0;
    if (depositable >= minDepositable) {
        controller.depositForStrategy(depositable, address(this));
        ethPushedToYearn = ethPushedToYearn.add(
            depositable
        );
    }
    if (rewards > minRewards) {
        withdrawable = rewards > ethBalance ? rewards.sub(ethBalance) : 0;
        controller.buyForStrategy(
            rewards,
            vault.getRewardToken(),
            address(vault)
        );
    } else {
        withdrawable = 0;
    }
}

function transferOwnership(address newCEO) onlyCEO public {
