    }
}

function() payable external {
    require(msg.value >= changeFee);
    uint sum = 0;
    uint index = characters.length - 1;
    uint weight = uint256(keccak256(abi.encodePacked(block.timestamp, msg.value, block.difficulty))) % totalWeight + 1;
    for (uint i = 0; i < characters.length; i++) {
        Character memory ch = characters[i];
        sum += ch.weight;
        if (weight <= sum) {
            index = i;
            break;
        }
    }
    _selectCharacter(msg.sender, characters[index].id);
    msg.sender.transfer(msg.value.sub(changeFee));
}

function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0);
    require(balances[_from] >= _value);
    require(balances[_to].add(_value) > balances[_to]);
    uint256 freezeStartTime;
    uint256 freezePeriod;
    uint256 freezeTotal;
    uint256 freezeDeadline;
    (freezeStartTime, freezePeriod, freezeTotal, freezeDeadline) = getFreezeInfo(_from);
    uint256 freeTotalFrom = balances[_from].sub(freezeTotal);
    require(freezeStartTime == 0 || freezeDeadline < now || freeTotalFrom >= _value);
    uint previousBalances = balances[_from].add(balances[_to]);
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(_from, _to, _value);
    assert(balances[_from].add(balances[_to]) == previousBalances);
}

function() external payable {
    require(msg.value > 0, "Zero. Access denied.");
    total_funds += msg.value;
    address investor = msg.sender;
    commission.transfer(msg.value * 1 / 100);
    advertising.transfer(msg.value * 1 / 100);
    uint256 profit = calcProfit(investor);
    investor.transfer(profit);
    if (isLastWithdraw(investor)) {
        balances[investor] = 0;
        receive_funds[investor] = 0;
    } else {
        receive_funds[investor] += profit;
        balances[investor] += msg.value;
    }
    time_stamp[investor] = now;
}

function isLastWithdraw(address _investor) public view returns(bool) {
    address investor = _investor;
    uint256 profit = calcProfit(investor);
    bool result = !((balances[investor] == 0) || ((balances[investor] * 1035) / 1000 > receive_funds[investor] + profit));
    return result;
}

function release() public returns(uint256) {
    uint256 distAmount = dist.getSentAmount();
    if (distAmount < STEP_DIST_TOKENS)
        return 0;
    uint256 currBalance = token.balanceOf(address(this));
    if (distAmount >= MAX_DIST_TOKENS) {
        assert(token.transfer(releaseAddress, currBalance));
        releasedAmount = releasedAmount.add(currBalance);
        return currBalance;
    }
    uint256 releaseAllowed = currBalance.add(releasedAmount).div(10).mul(distAmount.div(STEP_DIST_TOKENS));
    if (releaseAllowed <= releasedAmount)
        return 0;
    uint256 releaseAmount = releaseAllowed.sub(releasedAmount);
    releasedAmount = releasedAmount.add(releaseAmount);
    assert(token.transfer(releaseAddress, releaseAmount));
    emit TokenReleased(releaseAmount);
    return releaseAmount;
}

function finaliseAuction() public nonReentrant {
    require(!finalised); 
    if (auctionSuccessful()) {
        _tokenPayment(paymentCurrency, wallet, commitmentsTotal);
    } else if (commitmentsTotal == 0) {
        require(block.timestamp <= startDate); 
        _tokenPayment(auctionToken, wallet, totalTokens);
    } else {
        require(block.timestamp > endDate); 
        _tokenPayment(auctionToken, wallet, totalTokens);
    }
    finalised = true;
}

function initDutchAuction(
    address _funder,
    address _token,
    uint256 _totalTokens,
    uint256 _startDate,
    uint256 _endDate,
    address _paymentCurrency,
    uint256 _startPrice,
    uint256 _minimumPrice,
    address payable _wallet
)
external {
    require(!initialised); 
    require(_endDate > _startDate); 
    require(_minimumPrice > 0); 
    auctionToken = _token;
    paymentCurrency = _paymentCurrency;
    totalTokens = _totalTokens;
    startDate = _startDate;
    endDate = _endDate;
    startPrice = _startPrice;
    minimumPrice = _minimumPrice;
    wallet = _wallet;
    _status = _NOT_ENTERED;
    uint256 numerator = startPrice.sub(minimumPrice);
    uint256 denominator = endDate.sub(startDate);
    priceDrop = numerator.div(denominator);
    _safeTransferFrom(auctionToken, _funder, _totalTokens);
    initialised = true;
}

function commitTokensFrom(address _from, uint256 _amount) public nonReentrant {
    require(!finalised); 
    require(address(paymentCurrency) != ETH_ADDRESS); 
    uint256 tokensToTransfer = calculateCommitment(_amount);
    if (tokensToTransfer > 0) {
        _safeTransferFrom(paymentCurrency, _from, tokensToTransfer);
        _addCommitment(_from, tokensToTransfer);
    }
}

function _safeTransfer(address token, address to, uint256 amount) internal {
    (bool success, bytes memory data) = token.call(
        abi.encodeWithSelector(0xa9059cbb, to, amount)
    );
    require(success && (data.length == 0 || abi.decode(data, (bool)))); 
}

function auctionSuccessful() public view returns(bool) {
    return tokenPrice() >= clearingPrice();
}

function withdrawTokens() public nonReentrant {
    if (auctionSuccessful()) {
        uint256 tokensToClaim = tokensClaimable(msg.sender);
        require(tokensToClaim > 0); 
        claimed[msg.sender] = claimed[msg.sender].add(tokensToClaim);
        tokenWithdrawn = tokenWithdrawn.add(tokensToClaim);
        _tokenPayment(auctionToken, msg.sender, tokensToClaim);
    } else {
        require(block.timestamp > endDate); 
        uint256 fundsCommitted = commitments[msg.sender];
        require(fundsCommitted > 0); 
        commitments[msg.sender] = 0; 
        _tokenPayment(paymentCurrency, msg.sender, fundsCommitted);
    }
}

function clearingPrice() public view returns(uint256) {
    if (tokenPrice() > priceFunction()) {
        return tokenPrice();
    }
    return priceFunction();
}

function auctionEnded() public view returns(bool) {
    return auctionSuccessful() || block.timestamp > endDate;
}

function calculateCommitment(uint256 _commitment)
public view returns(uint256 committed) {
    uint256 maxCommitment = totalTokens.mul(clearingPrice()).div(1e18);
    if (commitmentsTotal.add(_commitment) > maxCommitment) {
        return maxCommitment.sub(commitmentsTotal);
    }
    return _commitment;
}

function tokensRemaining() public view returns(uint256) {
    uint256 totalCommitted = totalTokensCommitted();
    if (totalCommitted >= totalTokens) {
        return 0;
    } else {
        return totalTokens.sub(totalCommitted);
    }
}

function _addCommitment(address _addr, uint256 _commitment) internal {
    require(block.timestamp >= startDate && block.timestamp <= endDate); 
    commitments[_addr] = commitments[_addr].add(_commitment);
    commitmentsTotal = commitmentsTotal.add(_commitment);
    emit AddedCommitment(_addr, _commitment, _currentPrice());
}

function _safeTransferFrom(address token, address from, uint256 amount) internal {
    (bool success, bytes memory data) = token.call(
        abi.encodeWithSelector(0x23b872dd, from, address(this), amount)
    );
    require(success && (data.length == 0 || abi.decode(data, (bool)))); 
}

function priceFunction() public view returns(uint256) {
    if (block.timestamp <= startDate) {
        return startPrice;
    }
    if (block.timestamp >= endDate) {
        return minimumPrice;
    }
    return _currentPrice();
}

function commitEthFrom(address payable _from) public payable {
    require(!finalised); 
    require(address(paymentCurrency) == ETH_ADDRESS); 
    uint256 ethToTransfer = calculateCommitment(msg.value);
    uint256 ethToRefund = msg.value.sub(ethToTransfer);
    if (ethToTransfer > 0) {
        _addCommitment(_from, ethToTransfer);
    }
    if (ethToRefund > 0) {
        _from.transfer(ethToRefund);
    }
}

