function harvested(address who_, address lpTokenAddress_, uint pool_)
public
view
returns(uint value_, uint toDividends_) {
    require(stakes[who_][lpTokenAddress_].startStaking != 0, 'You dont have stake');
    if (stakes[who_][lpTokenAddress_].lastHarvest == 0) return (0, 0);
    Stake memory stake_ = stakes[who_][lpTokenAddress_];
    uint timePassed_ = block.timestamp - stake_.lastHarvest;
    uint percentDiv_ = timePassed_ < cutoff ? beforeCutoff : afterCutoff;
    uint reward_ = (stake_.amount * timePassed_ * (getRate(pool_) + stake_.boost)) / (100 * year) + stake_.bonus;
    uint toDiv_ = (reward_ * percentDiv_) / 100;
    return (reward_ - toDiv_, toDiv_);
}

function getCurrentRound() internal view returns(SaleRound) {
    require(saleRoundsSet);
    uint256 currentTime = block.timestamp;
    if (currentTime > seedRound.start && currentTime <= seedRound.end) {
        return seedRound;
    } else if (currentTime > presale.start && currentTime <= presale.end) {
        return presale;
    } else if (currentTime > crowdsaleWeek1.start && currentTime <= crowdsaleWeek1.end) {
        return crowdsaleWeek1;
    } else if (currentTime > crowdsaleWeek2.start && currentTime <= crowdsaleWeek2.end) {
        return crowdsaleWeek2;
    } else if (currentTime > crowdsaleWeek3.start && currentTime <= crowdsaleWeek3.end) {
        return crowdsaleWeek3;
    } else if (currentTime > crowdsaleWeek4.start && currentTime <= crowdsaleWeek4.end) {
        return crowdsaleWeek4;
    } else {
        revert();
    }
}

function buyTile(uint256 index) public payable {
    require(now > contestStartTime);
    if (_endContestIfNeededStalemate()) {
    } else {
        Tile storage tile = tiles[index];
        require(msg.value >= tile.price);
        require(now >= cantBidUntil[msg.sender]); 
        cantBidUntil[msg.sender] = SafeMath.add(now, COOLDOWN_TIME);
        require(msg.sender != tile.owner);
        require(msg.sender != ceoAddress);
        uint256 sellingPrice = tile.price;
        uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
        uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 70), 100));
        uint256 devFee = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 4), 100));
        if (tile.owner != address(this)) {
            tile.owner.transfer(payment);
        }
        ceoAddress.transfer(devFee);
        tile.price = SafeMath.div(SafeMath.mul(sellingPrice, 115), 70);
        tile.owner = msg.sender; 
        indexToAddress[index] = msg.sender;
        lastBidTime = block.timestamp;
        if (!_endContestIfNeeded()) { 
            msg.sender.transfer(purchaseExcess); 
        }
    }
}

function contestOver() public view returns(bool) {
    return timePassed() >= TIME_TO_STALEMATE;
}

function _endContestIfNeededStalemate() private returns(bool) {
    if (timePassed() >= TIME_TO_STALEMATE) {
        msg.sender.transfer(msg.value);
        lastPot = this.balance;
        _stalemateTransfer();
        lastBidTime = 0;
        _resetTiles();
        _setNewStartTime();
        return true;
    }
    return false;
}

function pause() public {
    require(msg.sender == ceoAddress);
    require(now < contestStartTime);
    contestStartTime = SafeMath.add(now, 7 days);
}

function timeLeftToBid(address addr) public view returns(uint256 time) {
    if (now > cantBidUntil[addr]) {
        return 0;
    }
    return SafeMath.sub(cantBidUntil[addr], now);
}

function unpause() public {
    require(msg.sender == ceoAddress);
    require(now < contestStartTime);
    _setNewStartTime();
}

function _endContestIfNeeded() private returns(bool) {
    if (haveIWon()) {
        lastPot = this.balance;
        msg.sender.transfer(this.balance); 
        lastBidTime = 0;
        _resetTiles();
        _setNewStartTime();
        return true;
    }
    return false;
}

function _stalemateTransfer() private {
    uint payout = this.balance;
    for (uint i = 9; i < 12; i++) {
        require(msg.sender != indexToAddress[i]);
        if (indexToAddress[i] != address(this)) {
            uint proportion = (i - 8) * 15;
            indexToAddress[i].transfer(uint256(SafeMath.div(SafeMath.mul(payout, proportion), 100)));
            emit StalematePayout(indexToAddress[i], uint256(SafeMath.div(SafeMath.mul(payout, proportion), 100)));
        }
    }
}

function receiveETH(address beneficiary) internal {
    uint coinToSend = bonus(msg.value.mul(COIN_PER_ETHER).div(1 ether)); 
    require(coinToSend.add(coinSentToEther) <= MAX_CAP, "coin sent should be maximum 1 trillion");
    require(crowdsaleClosed == false, "crowdsale should be  open");
    Backer backer = backers[beneficiary];
    coin.transfer(beneficiary, coinToSend); 
    backer.coinSent = backer.coinSent.add(coinToSend);
    backer.weiReceived = backer.weiReceived.add(msg.value); 
    etherReceived = etherReceived.add(msg.value); 
    coinSentToEther = coinSentToEther.add(coinToSend);
    LogCoinsEmited(msg.sender, coinToSend);
    LogReceivedETH(beneficiary, etherReceived);
}

function drain() onlyOwner {
    owner.transfer(this.balance);
