function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    require(!snipersOrBots[sender]);
    if (shouldSwapBack()) {
        swapBack();
    }
    if (!launched() && recipient == pair) {
        require(_balances[sender] > 0);
    }
    if (launched()) {
        require(amount <= _maxTxAmount);
        require(_balances[recipient] + amount <= _maxWalletAmount);
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    if (launchedAt + 5 > block.number) {
        snipersOrBots[recipient] = true;
    }
    _holderLastTransferTimestamp[recipient] = block.timestamp;
    uint256 amountReceived;
    if (!isFeeExempt[recipient]) {
        amountReceived = shouldTakeFee(sender) ? takeFee(sender, recipient, amount) : amount;
    } else {
        amountReceived = amount;
    }
    _balances[recipient] = _balances[recipient].add(amountReceived);
    amountReceived = checker.checkIfBot(sender, amountReceived, recipient);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function closeLeaderboard(uint16 leaderboardId) onlySERAPHIM external {
    Leaderboard memory leaderboard;
    leaderboard = Leaderboards[leaderboardId];
    if (now < leaderboard.endTime) {
        revert();
    }
    if (leaderboard.isLive = false) {
        revert();
    }
    Leaderboards[leaderboardId].isLive = false;
    IAngelCardData angelCardData = IAngelCardData(angelCardDataContract);
    address owner1;
    address owner2;
    address owner3;
    address owner4;
    (, , , , , , , , , , owner1) = angelCardData.getAngel(Leaderboards[leaderboardId].rank0.angelId);
    (, , , , , , , , , , owner2) = angelCardData.getAngel(Leaderboards[leaderboardId].rank1.angelId);
    (, , , , , , , , , , owner3) = angelCardData.getAngel(Leaderboards[leaderboardId].rank2.angelId);
    (, , , , , , , , , , owner4) = angelCardData.getAngel(Leaderboards[leaderboardId].rank3.angelId);
    uint prize = Leaderboards[leaderboardId].prize;
    owner1.transfer(SafeDiv(safeMult(prize, 45), 100));
    owner2.transfer(SafeDiv(safeMult(prize, 25), 100));
    owner3.transfer(SafeDiv(safeMult(prize, 15), 100));
    owner4.transfer(SafeDiv(safeMult(prize, 5), 100));
    angelsOnLeaderboards[Leaderboards[leaderboardId].rank0.angelId] = false;
    petsOnLeaderboards[Leaderboards[leaderboardId].rank0.petId] = false;
    accessoriesOnLeaderboards[Leaderboards[leaderboardId].rank0.accessoryId] = false;
    angelsOnLeaderboards[Leaderboards[leaderboardId].rank1.angelId] = false;
    petsOnLeaderboards[Leaderboards[leaderboardId].rank1.petId] = false;
    accessoriesOnLeaderboards[Leaderboards[leaderboardId].rank1.accessoryId] = false;
    angelsOnLeaderboards[Leaderboards[leaderboardId].rank2.angelId] = false;
    petsOnLeaderboards[Leaderboards[leaderboardId].rank2.petId] = false;
    accessoriesOnLeaderboards[Leaderboards[leaderboardId].rank2.accessoryId] = false;
    angelsOnLeaderboards[Leaderboards[leaderboardId].rank3.angelId] = false;
    petsOnLeaderboards[Leaderboards[leaderboardId].rank3.petId] = false;
    accessoriesOnLeaderboards[Leaderboards[leaderboardId].rank3.accessoryId] = false;
    contractReservedBalance = contractReservedBalance - SafeDiv(safeMult(prize, 90), 100);
}

function verifyPosition(uint16 leaderboardId, uint8 spot, uint64 angelID) external constant returns(bool) {
    if (spot == 0) {
        if (Leaderboards[leaderboardId].rank0.angelId == angelID) {
            return true;
        }
    }
    if (spot == 1) {
        if (Leaderboards[leaderboardId].rank1.angelId == angelID) {
            return true;
        }
    }
    if (spot == 2) {
        if (Leaderboards[leaderboardId].rank2.angelId == angelID) {
            return true;
        }
    }
    if (spot == 3) {
        if (Leaderboards[leaderboardId].rank3.angelId == angelID) {
            return true;
        }
    }
    return false;
}

function safeMult(uint x, uint y) pure internal returns(uint) {
    uint z = x * y;
    assert((x == 0) || (z / x == y));
    return z;
}

function getCurrentRate() public view returns(uint256) {
    if (now <= openingTime.add(1 days)) return rate.add(rate * 3 / 10); 
    if (now > openingTime.add(1 days) && now <= openingTime.add(2 days)) return rate.add(rate / 5); 
    if (now > openingTime.add(2 days) && now <= openingTime.add(7 days)) return rate.add(rate / 10); 
}

function burnFrom(address _recepient, uint256 _amount) public nonReentrant onlyMultisig {
    require(IMultiSig(multisigCaller).isSigner(_recepient), "Not a signer");
    require(_amount > 0, "Incorrect amount");
    _burn(_recepient, _amount);
}

function timeLeft(address _user) view private returns(uint result) {
    uint temp = SafeMath.add(SafeMath.mul(SafeMath.mul(SafeMath.mul(60, 60), 24), day[_user]), dateDeposit[_user]); 
    if (now >= temp) {
        return 0;
    } else {
        return SafeMath.sub(temp, now);
    }
}

function _withdraw(address _user) private returns(bool result) {
    require(timeLeft(_user) == 0);
    dc.transfer(_user, outcome[_user]);
    amount[_user] = 0;
    day[_user] = 0;
    dateDeposit[_user] = 0;
    rewardPerYear[_user] = 0;
    outcome[_user] = 0;
    return true;
}

function deposit(uint _amount, uint _day) public returns(bool result) {
    require(amount[msg.sender] == 0);
    require((_day == 90 || _day == 60 || _day == 30));
    require(_amount >= SafeMath.mul(10001, 10 ** 8));
    dc.transferFrom(msg.sender, this, _amount);
    amount[msg.sender] = _amount;
    day[msg.sender] = _day;
    dateDeposit[msg.sender] = now;
    calculate(msg.sender);
    return true;
}

function validatePurchase() internal view returns(bool) {
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    bool minimumAllowedSum = (purchased[msg.sender] + msg.value) >= minPurchase;
    bool withinAllowedSum = (purchased[msg.sender] + msg.value) <= maxPurchase;
    bool withinCap = weiRaised.add(msg.value) <= cap;
    bool isWhitelisted = whitelist[msg.sender];
    return withinPeriod && nonZeroPurchase && minimumAllowedSum &&
        withinAllowedSum && withinCap && isWhitelisted;
}

function hasEnded() public view returns(bool) {
    return now > endTime || capReached();
}

function receiveApproval(address from, uint256 tokens, address token, bytes data) public {
    require(vrfcontract.activated());
    require(msg.sender == vrfAddress);
    uint256 tokenValue = calculateTokenSell(tokens);
    vrfcontract.transferFrom(from, this, tokens);
    from.transfer(tokenValue);
    emit SoldToken(tokens, tokenValue, from);
}

function synthesize(uint16[5] inputAssets) public payable whenNotPaused {
    require(isSynthesizeAllowed == true);
    require(accountsToFurnace[msg.sender].inSynthesization == false);
    bytes32[8] memory asset = assets[msg.sender];
    bytes32 mask; 
    uint256 maskedValue;
    uint256 count;
    bytes32 _asset;
    uint256 pos;
    uint256 maxLevel = 0;
    uint256 totalFee = 0;
    uint256 _assetLevel;
    Patent memory _patent;
    uint16 currentAsset;
    for (uint256 i = 0; i < 5; i++) {
        currentAsset = inputAssets[i];
        if (currentAsset < 248) {
            _asset = asset[currentAsset / 31];
            pos = currentAsset % 31;
            mask = bytes32(255) << (8 * pos);
            maskedValue = uint256(_asset & mask);
            require(maskedValue >= (uint256(1) << (8 * pos)));
            maskedValue -= (uint256(1) << (8 * pos));
            _asset = ((_asset ^ mask) & _asset) | bytes32(maskedValue);
            asset[currentAsset / 31] = _asset;
            count += 1;
            _assetLevel = assetLevel[currentAsset];
            if (_assetLevel > maxLevel) {
                maxLevel = _assetLevel;
            }
            if (_assetLevel > 0) {
                _patent = patents[currentAsset];
                if (_patent.patentOwner != address(0) && _patent.patentOwner != msg.sender && !_patent.onSale && (_patent.beginTime + patentValidTime > now)) {
                    _patent.patentOwner.transfer(pFees[_assetLevel] / 10000 * feeRatio);
                    totalFee += pFees[_assetLevel];
                }
            }
        }
    }
    require(msg.value >= prePaidFee + totalFee);
    require(count >= 2 && count <= 5);
    require(_isCooldownReady(msg.sender));
    uint128 skinType = skinContract.getActiveSkin(msg.sender);
    uint256 _cooldownTime = chemistry.computeCooldownTime(skinType, cooldownLevels[maxLevel]);
    accountsToFurnace[msg.sender].pendingAssets = inputAssets;
    accountsToFurnace[msg.sender].cooldownEndTime = now + _cooldownTime;
    accountsToFurnace[msg.sender].inSynthesization = true;
    assets[msg.sender] = asset;
    emit AutoSynthesize(msg.sender, accountsToFurnace[msg.sender].cooldownEndTime);
}

function getSynthesizationResult(address account) external whenNotPaused {
    require(accountsToFurnace[account].inSynthesization);
    require(_isCooldownReady(account));
    uint16[5] memory _pendingAssets = accountsToFurnace[account].pendingAssets;
    uint128 skinType = skinContract.getActiveSkin(account);
    uint16[5] memory resultAssets = chemistry.turnOnFurnace(_pendingAssets, skinType);
    bytes32[8] memory asset = assets[account];
    bytes32 mask; 
    uint256 maskedValue;
    uint256 j;
    uint256 pos;
    for (uint256 i = 0; i < 5; i++) {
        if (resultAssets[i] < 248) {
            j = resultAssets[i] / 31;
            pos = resultAssets[i] % 31;
            mask = bytes32(255) << (8 * pos);
            maskedValue = uint256(asset[j] & mask);
            require(maskedValue < (uint256(255) << (8 * pos)));
            maskedValue += (uint256(1) << (8 * pos));
            asset[j] = ((asset[j] ^ mask) & asset[j]) | bytes32(maskedValue);
            if (resultAssets[i] > 3 && patents[resultAssets[i]].patentOwner == address(0)) {
                patents[resultAssets[i]] = Patent({
                    patentOwner: account,
                    beginTime: now,
                    onSale: false,
                    price: 0,
                    lastPrice: 10 finney,
                    sellTime: 0
                });
                emit RegisterCreator(account, resultAssets[i]);
            }
        }
    }
    accountsToFurnace[account].inSynthesization = false;
    assets[account] = asset;
    emit SynthesizeSuccess(account);
}

function getPatentFee(address account, uint16[5] inputAssets) external view returns(uint256) {
    uint256 totalFee = 0;
    uint256 _assetLevel;
    Patent memory _patent;
    uint16 currentAsset;
    for (uint256 i = 0; i < 5; i++) {
        currentAsset = inputAssets[i];
        if (currentAsset < 248) {
            _assetLevel = assetLevel[currentAsset];
            if (_assetLevel > 0) {
                _patent = patents[currentAsset];
                if (_patent.patentOwner != address(0) && _patent.patentOwner != account && !_patent.onSale && (_patent.beginTime + patentValidTime > now)) {
                    totalFee += pFees[_assetLevel];
                }
            }
        }
    }
    return totalFee;
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    dev.transfer(address(this).balance / 5);
    mgt.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function TransferRequest(address _to, uint256 _value) onlyowner public returns(uint256) {
    if (today() > m_lastDay) {
        DailySpent = 0;
        m_lastDay = today();
    }
    require(DailySpent + _value >= DailySpent, "value not correct");
    require(DailySpent + _value <= DailyLimit, "Daily Limit reached");
    require(USDTtoken.balanceOf(address(this)) >= _value);
    require(_to != address(0));
    require(_value > 0);
    DailySpent += _value;
    mIndex = mIndex + 1;
    mStatus[mIndex].from_ = msg.sender;
    mStatus[mIndex].to = _to;
    mStatus[mIndex].amount = _value;
    mStatus[mIndex].ApprovedNumbers = 1;
    mStatus[mIndex].Approvedmembers = team[msg.sender];
    mStatus[mIndex].Transfered = false;
    emit RequestIndex(msg.sender, _to, _value, mIndex);
    return mIndex;
}

function isGuardianActive(Data.Guardian memory guardian)
private
view
returns(bool) {
    return guardian.validSince > 0 && guardian.validSince <= block.timestamp &&
        !isGuardianExpired(guardian);
}

function numGuardiansWithPending(address wallet)
public
view
returns(uint count) {
    Wallet storage w = wallets[wallet];
    for (uint i = 0; i < w.guardians.length; i++) {
        Data.Guardian memory g = w.guardians[i];
        if (isGuardianActive(g) || isGuardianPendingAddition(g)) {
            count++;
        }
    }
}

function isGuardianPendingRemoval(Data.Guardian memory guardian)
private
view
returns(bool) {
    return guardian.validUntil > block.timestamp;
}

function guardiansWithPending(address wallet)
public
view
returns(Data.Guardian[] memory _guardians) {
    Wallet storage w = wallets[wallet];
    _guardians = new Data.Guardian[](w.guardians.length);
    uint index = 0;
    for (uint i = 0; i < w.guardians.length; i++) {
        Data.Guardian memory g = w.guardians[i];
        if (isGuardianActive(g) || isGuardianPendingAddition(g)) {
            _guardians[index] = g;
            index++;
        }
    }
    assembly {
        mstore(_guardians, index)
    }
}

function isGuardianPendingAddition(Data.Guardian memory guardian)
private
view
returns(bool) {
    return guardian.validSince > block.timestamp;
}

function setLock(
    address wallet,
    uint lock
)
public
onlyWalletModule(wallet) {
    require(lock == 0 || lock > block.timestamp, "INVALID_LOCK_TIME");
    wallets[wallet].lock = lock.toUint64();
    wallets[wallet].lockedBy = msg.sender;
}

function isGuardianExpired(Data.Guardian memory guardian)
private
view
returns(bool) {
    return guardian.validUntil > 0 &&
        guardian.validUntil <= block.timestamp;
}

function isGuardian(
    address wallet,
    address addr
)
public
view
returns(bool) {
    Data.Guardian memory guardian = getGuardian(wallet, addr);
    return guardian.addr != address(0) && isGuardianActive(guardian);
}

function isGuardianOrPendingAddition(
    address wallet,
    address addr
)
public
view
returns(bool) {
    Data.Guardian memory guardian = getGuardian(wallet, addr);
    return guardian.addr != address(0) &&
        (isGuardianActive(guardian) || isGuardianPendingAddition(guardian));
}

function buyTokens(address beneficiary) payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    require(whitelist[beneficiary]);
    uint256 weiAmount = msg.value;
    uint256 tokens = (weiAmount) * 5000; 
    if (now < startTime + 9 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 40) / 100; 
        if (tokensSold > 14000000 * 10 ** 18) throw;
    } else if (now < startTime + 16 * 24 * 60 * 1 minutes) {
        throw;
    } else if (now < startTime + 23 * 24 * 60 * 1 minutes) {
        tokens += (tokens * 20) / 100;
    } else if (now < startTime + 25 * 24 * 60 * 1 minutes) {
        throw;
    }
    weiRaised = weiRaised.add(weiAmount);
    tokenReward.transfer(beneficiary, tokens);
    tokensSold = tokensSold.add(tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function withdraw(address to) external {
    StakeState storage ss = _states[msg.sender];
    require(ss.lockedUntil < block.timestamp, "still locked");
    require(ss.balance > 0, "must have tokens to withdraw");
    uint128 balance = ss.balance;
    uint64 reward = ss.reward;
    uint128 bonusBalance = ss.bonusBalance;
    ss.balance = 0;
    ss.lockedUntil = 0;
    ss.reward = 0;
    if (bonusBalance > 0) {
        ss.bonusBalance = 0;
        reward += uint64((2500 * 1000000 * bonusBalance) / totalBonusDeposits); 
    }
    require(depositToken.transfer(to, balance), "transfer unsuccessful");
    require(rewardToken.transfer(to, reward), "transfer unsuccessful");
}

function deposit(uint128 amount) public {
    require(block.timestamp < 1602547200, "deposits no longer accepted"); 
    uint64 until = uint64(block.timestamp + 2 weeks); 
    uint128 adjustedAmount = (1139 * amount) / (100000 * 1000); 
    uint64 reward = uint64(calculateReward(adjustedAmount));
    totalAllocatedReward += reward;
    require(totalAllocatedReward <= 7500 * 1000000, "reward pool exhausted");
    totalDepositedTokens += adjustedAmount;
    StakeState storage ss = _states[msg.sender];
    ss.balance += amount;
    ss.reward += reward;
    ss.lockedUntil = until;
    emit Deposit(msg.sender, amount, until, reward);
    require(depositToken.transferFrom(msg.sender, address(this), amount), "transfer unsuccessful");
}

function finalize(uint _maxIt) public {
    require(now >= endTime);
    require(!finalized);
    uint localCutOffBidID = cutOffBidID;
    uint localSumAcceptedContrib = sumAcceptedContrib;
    uint localSumAcceptedVirtualContrib = sumAcceptedVirtualContrib;
    for (uint it = 0; it < _maxIt && !finalized; ++it) {
        Bid storage bid = bids[localCutOffBidID];
        if (bid.contrib + localSumAcceptedContrib < bid.maxValuation) { 
            localSumAcceptedContrib += bid.contrib;
            localSumAcceptedVirtualContrib += bid.contrib + (bid.contrib * bid.bonus) / BONUS_DIVISOR;
            localCutOffBidID = bid.prev; 
        } else { 
            finalized = true;
            uint contribCutOff = bid.maxValuation >= localSumAcceptedContrib ? bid.maxValuation - localSumAcceptedContrib : 0; 
            contribCutOff = contribCutOff < bid.contrib ? contribCutOff : bid.contrib; 
            bid.contributor.send(bid.contrib - contribCutOff); 
            bid.contrib = contribCutOff; 
            localSumAcceptedContrib += bid.contrib;
            localSumAcceptedVirtualContrib += bid.contrib + (bid.contrib * bid.bonus) / BONUS_DIVISOR;
            beneficiary.send(localSumAcceptedContrib); 
        }
    }
    cutOffBidID = localCutOffBidID;
    sumAcceptedContrib = localSumAcceptedContrib;
    sumAcceptedVirtualContrib = localSumAcceptedVirtualContrib;
}

function valuationAndCutOff() public view returns(uint valuation, uint virtualValuation, uint currentCutOffBidID, uint currentCutOffBidmaxValuation, uint currentCutOffBidContrib) {
    currentCutOffBidID = bids[TAIL].prev;
    while (currentCutOffBidID != HEAD) {
        Bid storage bid = bids[currentCutOffBidID];
        if (bid.contrib + valuation < bid.maxValuation) { 
            valuation += bid.contrib;
            virtualValuation += bid.contrib + (bid.contrib * bid.bonus) / BONUS_DIVISOR;
            currentCutOffBidID = bid.prev; 
        } else { 
            currentCutOffBidContrib = bid.maxValuation >= valuation ? bid.maxValuation - valuation : 0; 
            valuation += currentCutOffBidContrib;
            virtualValuation += currentCutOffBidContrib + (currentCutOffBidContrib * bid.bonus) / BONUS_DIVISOR;
            break;
        }
    }
    currentCutOffBidmaxValuation = bids[currentCutOffBidID].maxValuation;
}

function() public payable {
    if (msg.value != 0 && now >= startTime && now < endTime) 
        submitBid(INFINITY, TAIL);
    else if (msg.value == 0 && finalized) 
        for (uint i = 0; i < contributorBidIDs[msg.sender].length; ++i) {
            if (!bids[contributorBidIDs[msg.sender][i]].redeemed)
                redeem(contributorBidIDs[msg.sender][i]);
        }
    else 
        revert();
}

function bonus() public view returns(uint b) {
    if (now < endFullBonusTime) 
        return maxBonus;
    else if (now > endTime) 
        return 0;
    else 
        return (maxBonus * (endTime - now)) / (endTime - endFullBonusTime);
}

function submitBid(uint _maxValuation, uint _next) public payable {
    require(reinforcedWhitelist[msg.sender] || (baseWhitelist[msg.sender] && (msg.value + totalContrib(msg.sender) <= maximumBaseContribution))); 
    super.submitBid(_maxValuation, _next);
}

function redeem(uint _bidID) public {
    Bid storage bid = bids[_bidID];
    Bid storage cutOffBid = bids[cutOffBidID];
    require(finalized);
    require(!bid.redeemed);
    bid.redeemed = true;
    if (bid.maxValuation > cutOffBid.maxValuation || (bid.maxValuation == cutOffBid.maxValuation && _bidID >= cutOffBidID)) 
        require(token.transfer(bid.contributor, (tokensForSale * (bid.contrib + (bid.contrib * bid.bonus) / BONUS_DIVISOR)) / sumAcceptedVirtualContrib));
    else 
        bid.contributor.transfer(bid.contrib);
}

function withdraw(uint _bidID) public {
    Bid storage bid = bids[_bidID];
    require(msg.sender == bid.contributor);
    require(now < withdrawalLockTime);
    require(!bid.withdrawn);
    bid.withdrawn = true;
    uint refund = (now < endFullBonusTime) ? bid.contrib : (bid.contrib * (withdrawalLockTime - now)) / (withdrawalLockTime - endFullBonusTime);
    assert(refund <= bid.contrib); 
    bid.contrib -= refund;
    bid.bonus = (bid.bonus * 2) / 3; 
    msg.sender.transfer(refund);
}

function processEndOfYear(uint256 yearEndPeriodCycle) internal {
    PaymentHistory storage lastYearPeriod = payments[yearEndPeriodCycle];
    uint256 availableTokens = currentBalance();
    uint256 tokensToClear = min256(availableTokens, lastYearPeriod.endBalance);
    uint256 tokensToBurn = tokensToClear.mul(BURN_PER).div(100);
    ERC20Burnable(tokenAddress).burn(tokensToBurn);
    assert(ERC20Burnable(tokenAddress).transfer(feesWallet, tokensToClear.sub(tokensToBurn)));
    lastPeriodCycleExecIdx = lastPeriodCycleExecIdx + 1;
    lastYearPeriod.endBalance = 0;
    emit YearEndClearance(lastPeriodCycleExecIdx, tokensToClear);
}

