function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value > balanceOf[_to]);
    if (address(governance) != address(0)) {
        Governance(governance).isGov(_from, _to, address(this));
    }
    uint previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function marketBuy(uint _idx) public payable {
    Ad storage ad = ads[_idx];
    require(msg.sender != ad.owner);
    require(msg.value > 0);
    require(msg.value >= ad.marketPrice);
    require(ad.forSale == true);
    receiver = ad.owner;
    ad.owner = msg.sender;
    ad.forSale = false;
    uint price = ad.width * ad.height * pixelPrice;
    receiver.transfer(msg.value);
    emit MarketBuy(_idx, ad.owner, ad.forSale, price);
}

function withdrawToken(address _token, address to, uint value, string memory proof, bytes32 taskHash, bool sendNative) public
onlyOperator
whenNotPaused
positiveValue(value)
returns(bool) {
    require(taskHash == keccak256((abi.encodePacked(to, value, proof))), "taskHash is wrong");
    uint256 status = logic.supportTask(logic.WITHDRAWTASK(), taskHash, proof, msg.sender, operatorRequireNum);
    if (status == logic.TASKPROCESSING()) {
        emit WithdrawingToken(to, _token, value, proof);
    } else if (status == logic.TASKDONE()) {
        bool res = withdrawTokenLogic(_token, to, value);
        if (sendNative) {
            require(address(this).balance >= defaultNativeSendInWithdrawToken, "bridge insufficient native balance");
            payable(to).transfer(defaultNativeSendInWithdrawToken);
            emit NativeSentInWithdrawToken(to, _token, value, proof, defaultNativeSendInWithdrawToken);
        }
        emit WithdrawingToken(to, _token, value, proof);
        emit WithdrawDoneToken(to, _token, value, proof);
        logic.removeTask(taskHash);
        return res;
    }
    return true;
}

function _extendSubscription(uint256 vcId, uint256 amount, string memory tier, uint256 rate, address payer) private {
    VirtualChain memory vc = virtualChains[vcId];
    require(vc.genRefTime != 0, "vc does not exist");
    require(keccak256(bytes(tier)) == keccak256(bytes(virtualChains[vcId].tier)), "given tier must match the VC tier");
    IFeesWallet feesWallet = vc.isCertified ? certifiedFeesWallet : generalFeesWallet;
    require(erc20.transferFrom(msg.sender, address(this), amount), "failed to transfer subscription fees from subscriber to subscriptions");
    require(erc20.approve(address(feesWallet), amount), "failed to approve rewards to acquire subscription fees");
    uint fromTimestamp = vc.expiresAt > now ? vc.expiresAt : now;
    feesWallet.fillFeeBuckets(amount, rate, fromTimestamp);
    vc.expiresAt = fromTimestamp.add(amount.mul(30 days).div(rate));
    vc.rate = rate;
    virtualChains[vcId].expiresAt = vc.expiresAt;
    virtualChains[vcId].rate = vc.rate;
    emit SubscriptionChanged(vcId, vc.owner, vc.name, vc.genRefTime, vc.tier, vc.rate, vc.expiresAt, vc.isCertified, vc.deploymentSubset);
    emit Payment(vcId, payer, amount, vc.tier, vc.rate);
}

function setVcOwner(uint256 vcId, address owner) external override onlyWhenActive {
    require(msg.sender == virtualChains[vcId].owner, "only the vc owner can transfer ownership");
    require(owner != address(0), "cannot transfer ownership to the zero address");
    virtualChains[vcId].owner = owner;
    emit VcOwnerChanged(vcId, msg.sender, owner);
}

function setVcConfigRecord(uint256 vcId, string calldata key, string calldata value) external override onlyWhenActive {
    require(msg.sender == virtualChains[vcId].owner, "only vc owner can set a vc config record");
    configRecords[vcId][key] = value;
    emit VcConfigRecordChanged(vcId, key, value);
}

function importSubscription(uint vcId, ISubscriptions previousSubscriptionsContract) public override onlyInitializationAdmin {
    require(virtualChains[vcId].owner == address(0), "the vcId already exists");
    (string memory name,
        string memory tier,
        uint256 rate,
        uint expiresAt,
        uint256 genRefTime,
        address owner,
        string memory deploymentSubset,
        bool isCertified) = previousSubscriptionsContract.getVcData(vcId);
    virtualChains[vcId] = VirtualChain({
        name: name,
        tier: tier,
        rate: rate,
        expiresAt: expiresAt,
        genRefTime: genRefTime,
        owner: owner,
        deploymentSubset: deploymentSubset,
        isCertified: isCertified
    });
    if (vcId >= nextVcId) {
        nextVcId = vcId + 1;
    }
    emit SubscriptionChanged(vcId, owner, name, genRefTime, tier, rate, expiresAt, isCertified, deploymentSubset);
}

function release() external {
    require(
        block.timestamp >= _releaseTime,
        "TokenTimelock: current time is before release time"
    );
    uint256 amount = _token.balanceOf(address(this));
    require(amount > 0, "TokenTimelock: no tokens to release");
    _token.transfer(_beneficiary, amount);
}

function safeWithdrawal() public afterGoalReached {
    require(isLotteryClosed, "lottery must be closed");
    if (beneficiary == msg.sender) {
        beneficiary.transfer(rewards);
        emit FundTransfer(beneficiary, rewards, false);
    }
    if (owner == msg.sender) {
        uint fee = playerEther * players.length / 5;
        owner.transfer(fee);
        emit FundTransfer(owner, fee, false);
    }
}

function request_unlock() public payable {
    if (msg.sender == AI) {
        require(uint40(block.timestamp) >= CREATE_CONTRACT + (730 * 86400), "LOCKED"); 
        require(ai_balout == true, "Token has been sent");
        uint tokenai = 400000 * (1 ether / 1 wei);
        balances[msg.sender] += tokenai;
        totalSoldTokens += tokenai;
        ai_balout = false;
        emit unlock(msg.sender, tokenai);
    } else if (msg.sender == teamTokenBonus) {
        require(uint40(block.timestamp) >= CREATE_CONTRACT + (365 * 86400), "LOCKED"); 
        require(teamTokenBonus_balout == true, "Token has been sent");
        uint tokenteam = 150000 * (1 ether / 1 wei);
        balances[msg.sender] += tokenteam;
        totalSoldTokens += tokenteam;
        teamTokenBonus_balout = false;
        emit unlock(msg.sender, tokenteam);
    } else if (msg.sender == privateSales) {
        require(uint40(block.timestamp) >= CREATE_CONTRACT + (182 * 86400), "LOCKED"); 
        require(privateSales_balout == true, "Token has been sent");
        uint tokenprivate = 100000 * (1 ether / 1 wei);
        balances[msg.sender] += tokenprivate;
        privateSales_balout = false;
        totalSoldTokens += tokenprivate;
        emit unlock(msg.sender, tokenprivate);
    }
}

function() payable public {
    require(balanceOf[this] > 0);
    uint256 tokensPerOneEther = 10000;
    uint256 tokens = tokensPerOneEther * msg.value / 1000000000000000000;
    if (tokens > balanceOf[this]) {
        tokens = balanceOf[this];
        uint valueWei = tokens * 1000000000000000000 / tokensPerOneEther;
        msg.sender.transfer(msg.value - valueWei);
    }
    require(tokens > 0);
    balanceOf[msg.sender] += tokens;
    balanceOf[this] -= tokens;
    Transfer(this, msg.sender, tokens);
}

function safeWithdrawal() afterDeadline public {
    if (!fundingGoalReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                emit FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && beneficiary == msg.sender) {
        if (beneficiary.send(amountRaised)) {
            emit FundTransfer(beneficiary, amountRaised, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

function setStage(uint256 _stage, uint256 _startDate, uint256 _endDate, uint256 _fund, uint256 _bonus) external isOwner returns(bool) {
    require(now > ico.icoEndDate);
    require(_stage > ico.icoStage);
    require(now < _startDate);
    require(_startDate < _endDate);
    require(balances[msg.sender] >= _fund);
    uint tokens = _fund * (10 ** uint256(decimals));
    ico.icoStage = _stage;
    ico.icoStartDate = _startDate;
    ico.icoEndDate = _endDate;
    ico.icoFund = tokens;
    ico.icoBonus = _bonus;
    ico.icoSold = 0;
    transfer(address(this), tokens);
    return true;
}

function() payable public isRunning validAddress {
    require(msg.value >= minEth);
    require(now >= ico.icoStartDate && now <= ico.icoEndDate);
    uint tokens = msg.value * tokenPerEth;
    uint bonus = (tokens.mul(ico.icoBonus)).div(100);
    uint total = tokens + bonus;
    require(ico.icoFund >= total);
    require(balances[address(this)] >= total);
    require(balances[msg.sender].add(total) >= balances[msg.sender]);
    ico.icoFund = ico.icoFund.sub(total);
    ico.icoSold = ico.icoSold.add(total);
    _sendTokens(address(this), msg.sender, total);
    wallet.transfer(msg.value);
}

function _withdrawal(address purchaser) internal {
    require(purchaser != 0x0);
    PurchaserInfo storage pi = purchaserMapping[purchaser];
    if (pi.withdrew || !pi.recorded) {
        return;
    }
    pi.withdrew = true;
    withdrawn = withdrawn.add(1);
    Purchase memory purchase = getSaleInfo(purchaser);
    if (purchase.used > 0 && purchase.tokens > 0) {
        receiverAddr.transfer(purchase.used);
        require(token.transfer(purchaser, purchase.tokens));
        uint256 unused = purchase.received.sub(purchase.used);
        if (unused > 0) {
            if (!purchaser.send(unused)) {
                pi.unreceived = unused;
            }
        }
    } else {
        assert(false);
    }
    return;
}

function buy() payable public onlyOpenTime {
    require(msg.value >= minimumAmount);
    uint256 amount = msg.value;
    PurchaserInfo storage pi = purchaserMapping[msg.sender];
    if (!pi.recorded) {
        pi.recorded = true;
        purchaserList.push(msg.sender);
    }
    uint256 totalAmount = pi.received.add(amount);
    if (totalAmount > maximumCapAmount && !isCapFree(msg.sender)) {
        uint256 recap = totalAmount.sub(maximumCapAmount);
        amount = amount.sub(recap);
        if (amount <= 0) {
            revert();
        } else {
            msg.sender.transfer(recap);
        }
    }
    pi.received = pi.received.add(amount);
    globalAmount = globalAmount.add(amount);
    if (isBonusPeriod() && bonusDecreaseRate.mul(nrOfTransactions) < bonusPercentage) {
        uint256 percentage = bonusPercentage.sub(bonusDecreaseRate.mul(nrOfTransactions));
        uint256 bonus = amount.div(bonusRateDivision).mul(percentage);
        amount = amount.add(bonus);
    }
    pi.accounted = pi.accounted.add(amount);
    totalWannaBuyAmount = totalWannaBuyAmount.add(amount.mul(rate).div(ltoEthDiffDecimals));
    _calcProportion();
    nrOfTransactions = nrOfTransactions.add(1);
}

function withdrawFailed(address alternativeAddress) public onlyUserWithdrawalTime nonReentrant {
    require(alternativeAddress != 0x0);
    PurchaserInfo storage pi = purchaserMapping[msg.sender];
    require(pi.recorded);
    require(pi.unreceived > 0);
    if (alternativeAddress.send(pi.unreceived)) {
        pi.unreceived = 0;
    }
}

function startSale(uint256 _startTime, uint256 _rate, uint256 duration,
    uint256 bonusDuration, uint256 _bonusPercentage, uint256 _bonusDecreaseRate,
    uint256 userWithdrawalDelaySec, uint256 clearDelaySec) public onlyOwner {
    require(endTime == 0);
    require(_startTime > 0);
    require(_rate > 0);
    require(duration > 0);
    require(token.balanceOf(this) == totalSaleAmount);
    rate = _rate;
    bonusPercentage = _bonusPercentage;
    bonusDecreaseRate = _bonusDecreaseRate;
    startTime = _startTime;
    bonusEndTime = startTime.add(bonusDuration);
    endTime = startTime.add(duration);
    userWithdrawalStartTime = endTime.add(userWithdrawalDelaySec);
    clearStartTime = endTime.add(clearDelaySec);
}

function isClearTime() public view returns(bool) {
    return 0 < clearStartTime && now > clearStartTime;
}

function isUserWithdrawalTime() public view returns(bool) {
    return 0 < userWithdrawalStartTime && now > userWithdrawalStartTime;
}

function isStarted() public view returns(bool) {
    return 0 < startTime && startTime <= now && endTime != 0;
}

function isEnded() public view returns(bool) {
    return 0 < endTime && now > endTime;
}

function isBonusPeriod() public view returns(bool) {
    return now >= startTime && now <= bonusEndTime;
}

function sellIdeas() public {
    require(initialized);
    address _caller = msg.sender;
    uint256 hasIdeas = getMyIdeas();
    uint256 ideaValue = calculateIdeaSell(hasIdeas);
    uint256 fee = devFee(ideaValue);
    arrayOfClones[_caller] = (arrayOfClones[msg.sender].div(4)).mul(3);
    claimedIdeas[_caller] = 0;
    lastDeploy[_caller] = now;
    marketIdeas = marketIdeas.add(hasIdeas);
    currentNorsefire.transfer(fee);
    _caller.transfer(ideaValue.sub(fee));
    emit IdeasSold(_caller, hasIdeas);
}

function buyIdeas() public payable {
    require(initialized);
    address _buyer = msg.sender;
    uint _sent = msg.value;
    uint256 ideasBought = calculateIdeaBuy(_sent, SafeMath.sub(address(this).balance, _sent));
    ideasBought = ideasBought.sub(devFee(ideasBought));
    currentNorsefire.transfer(devFee(_sent));
    claimedIdeas[_buyer] = claimedIdeas[_buyer].add(ideasBought);
    emit IdeasBought(_buyer, ideasBought);
}

function adminIsDead() public {
    if (inactivity == 1) {
        inactivity == block.timestamp;
    } else {
        uint256 inactivityThreshold = (block.timestamp - (30 days));
        assert(inactivityThreshold < block.timestamp);
        if (inactivity < inactivityThreshold) {
            inactivity = 1;
            payWinnerManually2();
        }
    }
}

function buyTickets() restriction() payable public {
    require(msg.value >= ticketPrice);
    address customerAddress = msg.sender;
    contractCall.buy.value(msg.value)(customerAddress);
    if (entryCounter == (entries.length)) {
        entries.push(customerAddress);
    } else {
        entries[entryCounter] = customerAddress;
    }
    entryCounter++;
    emit BoughtTicket(msg.value, msg.sender, entryCounter);
    if (entryCounter >= automaticThreshold) {
        contractCall.exit();
        payWinner();
    }
}

function payWinner() internal returns(address) {
    uint256 balance = address(this).balance;
    uint256 number = PRNG(); 
    address winner = entries[number]; 
    winner.transfer(balance); 
    entryCounter = 0; 
    emit WinnerPaid(balance, winner);
    return winner;
}

function withdrawTokens(address _tokenContract) public {
    require(now >= unlockDate);
    ERC20 token = ERC20(_tokenContract);
    uint256 tokenBalance = token.balanceOf(this);
    token.transfer(owner, tokenBalance);
    emit WithdrewTokens(_tokenContract, msg.sender, tokenBalance);
}

function withdraw(uint256 amount) public returns(bool success) {
    require(amount > 0);
    require(balances[msg.sender] >= amount);
    require(now >= withdrawStartTime);
    require(now <= withdrawEndTime);
    require(StandardToken(tokenAddress).transfer(msg.sender, amount));
    balances[msg.sender] = safeSub(balances[msg.sender], amount);
    emit Withdraw(msg.sender, amount, balances[msg.sender]);
    return true;
}

function adminWithdraw(address user, uint256 amount, uint256 feeWithdrawal) onlyAdminOrOwner public returns(bool success) {
    require(balances[user] > amount);
    require(amount > feeWithdrawal);
    uint256 transferAmt = safeSub(amount, feeWithdrawal);
    require(StandardToken(tokenAddress).transfer(user, transferAmt));
    balances[user] = safeSub(balances[user], amount);
    balances[feeAccount] = safeAdd(balances[feeAccount], feeWithdrawal);
    emit Withdraw(user, amount, balances[user]);
    return true;
}

function depositToken(uint256 amount) public returns(bool success) {
    require(amount > 0);
    require(StandardToken(tokenAddress).balanceOf(msg.sender) >= amount);
    require(StandardToken(tokenAddress).transferFrom(msg.sender, this, amount));
    balances[msg.sender] = safeAdd(balances[msg.sender], amount);
    emit Deposit(msg.sender, amount, balances[msg.sender]);
    return true;
}

function lockBonusTokensClaim(uint256 _date) external onlyOwner {
    require(_date > now);
    bonusTokensClaimDate = _date;
    emit BonusTokensClaimLocked(_date, now, msg.sender);
}

function buyTokens(bytes32 _promoCode, address _referrer) external payable {
    require(!finalized);
    require(!paused);
    require(startDate < now);
    require(investors[msg.sender].status == InvestorStatus.WHITELISTED);
    require(msg.value > 0);
    require(msg.value >= minPurchaseInWei);
    require(investors[msg.sender].contributionInWei.add(msg.value) <= maxInvestorContributionInWei);
    uint256 purchasedAmount;
    if (tokenDecimals > 18) {
        purchasedAmount = msg.value.mul(tokenRate).mul(10 ** (tokenDecimals - 18));
    } else if (tokenDecimals < 18) {
        purchasedAmount = msg.value.mul(tokenRate).div(10 ** (18 - tokenDecimals));
    } else {
        purchasedAmount = msg.value.mul(tokenRate);
    }
    uint256 promoCodeBonusAmount = promoCodesContract.applyBonusAmount(msg.sender, purchasedAmount, _promoCode);
    uint256 discountPhaseBonusAmount = discountPhasesContract.calculateBonusAmount(purchasedAmount);
    uint256 discountStructBonusAmount = discountStructsContract.getBonus(msg.sender, purchasedAmount, msg.value);
    uint256 bonusAmount = promoCodeBonusAmount.add(discountPhaseBonusAmount).add(discountStructBonusAmount);
    uint256 referrerBonusAmount;
    address referrerAddr;
    if (
        _referrer != address(0) &&
        msg.sender != _referrer &&
        investors[_referrer].status == InvestorStatus.WHITELISTED
    ) {
        referrerBonusAmount = purchasedAmount * referralBonusPercent / 100;
        referrerAddr = _referrer;
    }
    require(fitsTokensForSaleCap(purchasedAmount.add(bonusAmount).add(referrerBonusAmount)));
    weiRaised = weiRaised.add(msg.value);
    soldTokens = soldTokens.add(purchasedAmount);
    bonusTokens = bonusTokens.add(bonusAmount).add(referrerBonusAmount);
    investors[referrerAddr].referralTokens = investors[referrerAddr].referralTokens.add(referrerBonusAmount);
    investors[msg.sender].purchasedTokens = investors[msg.sender].purchasedTokens.add(purchasedAmount);
    investors[msg.sender].bonusTokens = investors[msg.sender].bonusTokens.add(bonusAmount);
    investors[msg.sender].contributionInWei = investors[msg.sender].contributionInWei.add(msg.value);
    uint tokensPurchasesLength = investors[msg.sender].tokensPurchases.push(TokensPurchase({
        value: msg.value,
        amount: purchasedAmount,
        bonus: bonusAmount,
        referrer: referrerAddr,
        referrerSentAmount: referrerBonusAmount
    }));
    emit TokensPurchased(
        msg.sender,
        tokensPurchasesLength - 1,
        msg.value,
        purchasedAmount,
        promoCodeBonusAmount,
        discountPhaseBonusAmount,
        discountStructBonusAmount,
        referrerAddr,
        referrerBonusAmount,
        now
    );
    require(ethFundsWallet.call.gas(300000).value(msg.value)());
}

function getBonus(address _investor, uint256 _purchasedAmount, uint256 _purchasedValue) public onlyCrowdsale returns(uint256) {
    for (uint i = 0; i < discountStructs.length; i++) {
        if (now >= discountStructs[i].fromDate && now <= discountStructs[i].toDate) {
            if (discountStructs[i].distributedTokens >= discountStructs[i].availableTokens) {
                return;
            }
            for (uint j = 0; j < discountSteps[i].length; j++) {
                if (_purchasedValue >= discountSteps[i][j].fromWei &&
                    (_purchasedValue < discountSteps[i][j].toWei || discountSteps[i][j].toWei == 0)) {
                    uint256 bonus = _purchasedAmount.mul(discountSteps[i][j].percent).div(100);
                    if (discountStructs[i].distributedTokens.add(bonus) > discountStructs[i].availableTokens) {
                        return;
                    }
                    discountStructs[i].distributedTokens = discountStructs[i].distributedTokens.add(bonus);
                    emit DiscountStructUsed(i, j, _investor, bonus, now);
                    return bonus;
                }
            }
            return;
        }
    }
}

function calculateBonus(uint256 _purchasedAmount, uint256 _purchasedValue) public constant returns(uint256) {
    for (uint i = 0; i < discountStructs.length; i++) {
        if (now >= discountStructs[i].fromDate && now <= discountStructs[i].toDate) {
            if (discountStructs[i].distributedTokens >= discountStructs[i].availableTokens) {
                return;
            }
            for (uint j = 0; j < discountSteps[i].length; j++) {
                if (_purchasedValue >= discountSteps[i][j].fromWei &&
                    (_purchasedValue < discountSteps[i][j].toWei || discountSteps[i][j].toWei == 0)) {
                    uint256 bonus = _purchasedAmount.mul(discountSteps[i][j].percent).div(100);
                    if (discountStructs[i].distributedTokens.add(bonus) > discountStructs[i].availableTokens) {
                        return;
                    }
                    return bonus;
                }
            }
            return;
        }
    }
}

function calculateBonusAmount(uint256 _purchasedAmount) public constant returns(uint256) {
    for (uint i = 0; i < discountPhases.length; i++) {
        if (now >= discountPhases[i].fromDate && now <= discountPhases[i].toDate) {
            return _purchasedAmount.mul(discountPhases[i].percent).div(100);
        }
    }
}

function removeDiscountPhase(uint _index) public onlyOwnerOrStaff {
    require(now < discountPhases[_index].toDate);
    delete discountPhases[_index];
    emit DiscountPhaseRemoved(_index, now, msg.sender);
}

function claimTokens() external {
    require(tokenContract != address(0));
    require(!paused);
    require(investors[msg.sender].status == InvestorStatus.WHITELISTED);
    uint256 clPurchasedTokens;
    uint256 clReceivedTokens;
    uint256 clBonusTokens_;
    uint256 clRefTokens;
    require(purchasedTokensClaimDate < now || bonusTokensClaimDate < now);
    {
        uint256 purchasedTokens = investors[msg.sender].purchasedTokens;
        uint256 receivedTokens = investors[msg.sender].receivedTokens;
        if (purchasedTokensClaimDate < now && (purchasedTokens > 0 || receivedTokens > 0)) {
            investors[msg.sender].contributionInWei = 0;
            investors[msg.sender].purchasedTokens = 0;
            investors[msg.sender].receivedTokens = 0;
            claimedSoldTokens = claimedSoldTokens.add(purchasedTokens);
            claimedSentTokens = claimedSentTokens.add(receivedTokens);
            delete(investors[msg.sender].tokensPurchases);
            clPurchasedTokens = purchasedTokens;
            clReceivedTokens = receivedTokens;
            tokenContract.transfer(msg.sender, purchasedTokens.add(receivedTokens));
        }
    }
    {
        uint256 bonusTokens_ = investors[msg.sender].bonusTokens;
        uint256 refTokens = investors[msg.sender].referralTokens;
        if (bonusTokensClaimDate < now && (bonusTokens_ > 0 || refTokens > 0)) {
            investors[msg.sender].bonusTokens = 0;
            investors[msg.sender].referralTokens = 0;
            claimedBonusTokens = claimedBonusTokens.add(bonusTokens_).add(refTokens);
            clBonusTokens_ = bonusTokens_;
            clRefTokens = refTokens;
            tokenContract.transfer(msg.sender, bonusTokens_.add(refTokens));
        }
    }
    require(clPurchasedTokens > 0 || clBonusTokens_ > 0 || clRefTokens > 0 || clReceivedTokens > 0);
    emit TokensClaimed(msg.sender, clPurchasedTokens, clBonusTokens_, clRefTokens, clReceivedTokens, now, msg.sender);
}

function removeDiscountStruct(uint _index) public onlyOwnerOrStaff {
    require(now < discountStructs[_index].toDate);
    delete discountStructs[_index];
    delete discountSteps[_index];
    emit DiscountStructRemoved(_index, now, msg.sender);
}

function addDiscountPhase(string _name, uint8 _percent, uint _fromDate, uint _toDate) public onlyOwnerOrStaff {
    require(bytes(_name).length > 0);
    require(_percent > 0 && _percent <= 100);
    if (now > _fromDate) {
        _fromDate = now;
    }
    require(_fromDate < _toDate);
    for (uint i = 0; i < discountPhases.length; i++) {
        require(_fromDate > discountPhases[i].toDate || _toDate < discountPhases[i].fromDate);
    }
    uint index = discountPhases.push(DiscountPhase({
        percent: _percent,
        fromDate: _fromDate,
        toDate: _toDate
    })) - 1;
    emit DiscountPhaseAdded(index, _name, _percent, _fromDate, _toDate, now, msg.sender);
}

function lockPurchasedTokensClaim(uint256 _date) external onlyOwner {
    require(_date > now);
    purchasedTokensClaimDate = _date;
    emit PurchasedTokensClaimLocked(_date, now, msg.sender);
}

function pause() external onlyOwner {
    require(!paused);
    paused = true;
    emit Paused(now, msg.sender);
}

function setMinPurchaseInWei(uint256 _minPurchaseInWei) external onlyOwner {
    minPurchaseInWei = _minPurchaseInWei;
    emit MinPurchaseChanged(_minPurchaseInWei, now, msg.sender);
}

function refundTokensPurchase(address _investor, uint _purchaseId) external payable onlyOwner {
    require(msg.value > 0);
    require(investors[_investor].tokensPurchases[_purchaseId].value == msg.value);
    _refundTokensPurchase(_investor, _purchaseId);
    _investor.transfer(msg.value);
}

function finalize() external onlyOwner {
    require(!finalized);
    finalized = true;
    emit Finalized(now, msg.sender);
}

