function refundAll() onlyOwner public {
    require(now > VaultCreation + 30 days);
    token.transfer(owner(), token.balanceOf(this));
}

function STAKE(uint256 tokens) external {
    require(IERC20(NPT).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(NPT).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(NPT).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(NPT).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function execute()
external {
    uint[3] memory IDstack = stackMap[stackID];
    for (uint x = 0; x < 3; x++)
        if (IWLEV(_wlev).checkClaim(IDstack[x]) > 0)
            IRelease(_claim).release(IDstack[x]);
    stackID++;
    if (stackID > 10)
        stackID = 0;
}

function buyToken() external payable {
    require(presaleTimeEnds > block.timestamp, "Presale Finished");
    uint8 memberType = getMemberType(msg.sender);
    uint256 noOfTokens = calculateTokens(msg.value, memberType);
    if (memberType == TYPE_WHITELIST) {
        if (whitelistingSold.add(noOfTokens) <= WHITELISTING_SHARE) {
            whitelistingSold = whitelistingSold.add(noOfTokens);
        } else {
            revert("Whitelist Sale Quota has finished");
        }
    }
    if (memberType == TYPE_PRIVATEMEMBER) {
        if (privateSaleSold.add(noOfTokens) <= PRIVATE_SALE_SHARE) {
            privateSaleSold = privateSaleSold.add(noOfTokens);
        } else {
            revert("PRIVATE Sale Quota has finished");
        }
    } else {
        if (normalSaleSold.add(noOfTokens) <= NORMAL_SALE_SHARE) {
            normalSaleSold = normalSaleSold.add(noOfTokens);
        } else {
            revert("Normal Sale Quota has finished");
        }
    }
    require(getTokenBalance() >= noOfTokens, "Contract has no balance");
    token.transfer(msg.sender, noOfTokens);
    totalTokenSold = totalTokenSold.add(noOfTokens);
}

function daysToUnfreeze(address _address) public view returns(uint256) {
    require(_address != 0x0);
    uint256 _now = now;
    uint256 result = 0;
    if (_now <= creationDate + freezingPeriod[_address] * 1 days) {
        uint256 finalPeriod = (creationDate + freezingPeriod[_address] * 1 days) / 1 days;
        uint256 currePeriod = _now / 1 days;
        result = finalPeriod - currePeriod;
    }
    return result;
}

function _isTransferAllowed(address _address) view public returns(bool) {
    if (now >= creationDate + freezingPeriod[_address] * 1 days) {
        return (true);
    } else {
        return (false);
    }
}

function initialize() public {
    onlyAdmin(false);
    require(!isInitialized);
    begin();
    require(now <= startTime);
    initialization();
    emit Initialized();
    renewal = 0;
    isInitialized = true;
    canFirstMint = false;
}

function changeExchange(uint256 _ETHUSD) public {
    require(wallets[uint8(Roles.manager)] == msg.sender || wallets[uint8(Roles.observer)] == msg.sender);
    require(_ETHUSD >= 1 ether);
    softCap = softCap.mul(exchange).div(_ETHUSD); 
    hardCap = hardCap.mul(exchange).div(_ETHUSD); 
    minPay = minPay.mul(exchange).div(_ETHUSD); 
    rate = rate.mul(_ETHUSD).div(exchange); 
    for (uint16 i = 0; i < bonuses.length; i++) {
        bonuses[i].value = bonuses[i].value.mul(exchange).div(_ETHUSD); 
    }
    financialStrategy.setup(wallets[uint8(Roles.beneficiary)], exchange, _ETHUSD, 5);
    exchange = _ETHUSD;
}

function finalization() internal {
    if (goalReached()) {
        financialStrategy.setup(wallets[uint8(Roles.beneficiary)], weiRaised(), 0, 1); 
        if (tokenReserved > 0) {
            token.mint(wallets[uint8(Roles.accountant)], tokenReserved);
            tokenReserved = 0;
        }
        if (TokenSale == TokenSaleType.round1) {
            isInitialized = false;
            isFinalized = false;
            TokenSale = TokenSaleType.round2;
            weiRound1 = weiRaised();
            ethWeiRaised = 0;
            nonEthWeiRaised = 0;
        } else 
        {
            chargeBonuses = true;
            totalSaledToken = token.totalSupply();
        }
    } else 
    {
        financialStrategy.setup(wallets[uint8(Roles.beneficiary)], weiRaised(), 0, 3);
    }
}

function paymentsInOtherCurrency(uint256 _token, uint256 _value) public {
    require(wallets[uint8(Roles.observer)] == msg.sender || wallets[uint8(Roles.manager)] == msg.sender);
    bool withinPeriod = (now >= startTime && now <= endTime.add(renewal));
    bool withinCap = _value.add(ethWeiRaised) <= hardCap.add(overLimit);
    require(withinPeriod && withinCap && isInitialized);
    nonEthWeiRaised = _value;
    tokenReserved = _token;
}

function distructVault(bool mode) public {
    if (mode) {
        if (wallets[uint8(Roles.beneficiary)] == msg.sender && (now > startTime.add(FORCED_REFUND_TIMEOUT1))) {
            financialStrategy.setup(wallets[uint8(Roles.beneficiary)], weiRaised(), 0, 0);
        }
        if (wallets[uint8(Roles.manager)] == msg.sender && (now > startTime.add(FORCED_REFUND_TIMEOUT2))) {
            financialStrategy.setup(wallets[uint8(Roles.manager)], weiRaised(), 0, 0);
        }
    } else {
        onlyAdmin(false);
        financialStrategy.setup(wallets[uint8(Roles.beneficiary)], 0, 0, 4);
    }
}

function prolongate(uint256 _duration) external {
    onlyAdmin(false);
    require(now > startTime && now < endTime.add(renewal) && isInitialized);
    renewal = renewal.add(_duration);
    require(renewal <= ROUND_PROLONGATE);
}

function freezeTokens(address _beneficiary, uint256 _amount, uint256 _when) public {
    onlyAdmin();
    freeze storage _freeze = freezedTokens[_beneficiary];
    _freeze.amount = _amount;
    _freeze.when = _when;
}

function begin() public {
    onlyAdmin(true);
    if (isBegin) return;
    isBegin = true;
    token = creator.createToken();
    financialStrategy = creator.createFinancialStrategy();
    token.setUnpausedWallet(wallets[uint8(Roles.accountant)], true);
    token.setUnpausedWallet(wallets[uint8(Roles.manager)], true);
    token.setUnpausedWallet(wallets[uint8(Roles.bounty)], true);
    token.setUnpausedWallet(wallets[uint8(Roles.company)], true);
    token.setUnpausedWallet(wallets[uint8(Roles.observer)], true);
    bonuses.push(Bonus(20 ether, 2, 0));
    bonuses.push(Bonus(100 ether, 5, 0));
    bonuses.push(Bonus(400 ether, 8, 0));
    profits.push(Profit(30, 900 days));
}

function() payable external {
    uint256 marketingPerc = msg.value.mul(5).div(100);
    marketingAddress.transfer(marketingPerc);
    if (deposited[msg.sender] != 0) {
        address investor = msg.sender;
        uint256 depositsPercents = deposited[msg.sender].mul(5).div(100).mul(block.number - blocklock[msg.sender]).div(5900);
        investor.transfer(depositsPercents);
        withdrew[msg.sender] += depositsPercents;
        totalWithdrewWei = totalWithdrewWei.add(depositsPercents);
    }
    address referrer = bytesToAddress(msg.data);
    uint256 refPerc = msg.value.mul(5).div(100);
    if (referrer > 0x0 && referrer != msg.sender) {
        referrer.transfer(refPerc);
        refearned[referrer] += refPerc;
    }
    blocklock[msg.sender] = block.number;
    deposited[msg.sender] += msg.value;
    totalDepositedWei = totalDepositedWei.add(msg.value);
}

function EMACCrowdsale(uint256 _startTime, uint256 _endTime, uint256 _rate, address _wallet) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_rate > 0);
    require(_wallet != address(0));
    startTime = _startTime;
    endTime = _endTime;
    rate = _rate;
    wallet = _wallet;
    token = new EMACToken(INIT_TOKENS);
}

function distribute() external {
    require(distributing == true);
    require(checkAgentPercentage() == true);
    require(getDistributionAmount() > 0);
    for (uint256 i = 0; i < agents.length; i++) {
        uint256 amount = getAgentDistributionAmount(i);
        if (amount > 0) {
            require(token.transfer(agents[i].agent, amount));
        }
    }
    lastDistributionTimestamp = block.timestamp;
}

function getElapsedTime() public view returns(uint256) {
    require(block.timestamp >= lastDistributionTimestamp);
    return (block.timestamp - lastDistributionTimestamp);
}

function init(address _sgaToSGRTokenExchangeAddress, uint256 _sgaToSGRTokenExchangeSGRSupply) external onlyIfNotInitialized only(_SGAToSGRInitializer_) {
    require(_sgaToSGRTokenExchangeAddress != address(0), "SGA to SGR token exchange address is illegal");
    initialized = true;
    _mint(_sgaToSGRTokenExchangeAddress, _sgaToSGRTokenExchangeSGRSupply);
    emit SgrTokenInitialized(msg.sender, _sgaToSGRTokenExchangeAddress, _sgaToSGRTokenExchangeSGRSupply);
}

function exchange() external payable {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    uint256 amount = sgrTokenManager.exchangeEthForSgr(msg.sender, msg.value);
    _mint(msg.sender, amount);
    sgrTokenManager.afterExchangeEthForSgr(msg.sender, msg.value, amount);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    if (_to == address(this)) {
        uint256 amount = sgrTokenManager.exchangeSgrForEth(msg.sender, _value);
        _burn(msg.sender, _value);
        msg.sender.transfer(amount);
        return sgrTokenManager.afterExchangeSgrForEth(msg.sender, _value, amount);
    }
    sgrTokenManager.uponTransfer(msg.sender, _to, _value);
    bool transferResult = super.transfer(_to, _value);
    return sgrTokenManager.afterTransfer(msg.sender, _to, _value, transferResult);
}

function mintSgrForSgnHolders(uint256 _value) external only(_IMintManager_) {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    sgrTokenManager.uponMintSgrForSgnHolders(_value);
    _mint(SGR_MINTED_FOR_SGN_HOLDERS, _value);
    sgrTokenManager.afterMintSgrForSgnHolders(_value);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    require(_to != address(this), "custodian-transfer of SGR into this contract is illegal");
    sgrTokenManager.uponTransferFrom(msg.sender, _from, _to, _value);
    bool transferFromResult = super.transferFrom(_from, _to, _value);
    return sgrTokenManager.afterTransferFrom(msg.sender, _from, _to, _value, transferFromResult);
}

function transferSgrToSgnHolder(address _to, uint256 _value) external only(_SgnToSgrExchangeInitiator_) {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    sgrTokenManager.uponTransferSgrToSgnHolder(_to, _value);
    _transfer(SGR_MINTED_FOR_SGN_HOLDERS, _to, _value);
    sgrTokenManager.afterTransferSgrToSgnHolder(_to, _value);
}

function() external payable {
    ISGRTokenManager sgrTokenManager = getSGRTokenManager();
    uint256 amount = sgrTokenManager.exchangeEthForSgr(msg.sender, msg.value);
    _mint(msg.sender, amount);
    sgrTokenManager.afterExchangeEthForSgr(msg.sender, msg.value, amount);
}

function addDestructionProposal(string _reason) external payable returns(uint256) {
    require(!queued[uint(Subject.Destruction)]);
    addProposal(Subject.Destruction, _reason);
    queued[uint(Subject.Destruction)] = true;
    emit ProposalRaised(msg.sender, "SelfDestruction");
}

function addRaiseTapProposal(
    string _reason,
    uint256 _tapMultiplierRate
) external payable returns(uint256) {
    require(!queued[uint(Subject.RaiseTap)]);
    require(100 < _tapMultiplierRate && _tapMultiplierRate <= 200);
    uint256 newID = addProposal(Subject.RaiseTap, _reason);
    proposals[newID].tapMultiplierRate = _tapMultiplierRate;
    queued[uint(Subject.RaiseTap)] = true;
    emit ProposalRaised(msg.sender, "RaiseTap");
}

constructor(
    address _votingTokenAddr,
    address _poolAddr
) public {
    require(_votingTokenAddr != address(0x0));
    require(_poolAddr != address(0x0));
    votingTokenAddr = _votingTokenAddr;
    poolAddr = _poolAddr;
    Proposal memory proposal;
    proposal.subject = Subject.RaiseTap;
    proposal.reason = "PROPOSAL_HEADER";
    proposal.start_time = block.timestamp - 1;
    proposal.end_time = block.timestamp - 1;
    proposal.voter_count = 0;
    proposal.isFinalized = true;
    proposals.push(proposal);
    assert(proposals.length == 1);
}

function getNays(uint256 pid) public view returns(uint256) {
    require(pid < proposals.length);
    require(proposals[pid].isFinalized);
    return proposals[pid].votes[false];
}

function finalizeVoting() external {
    uint256 pid = this.getCurrentVoting();
    require(pid != PROPOSAL_EMPTY);
    require(proposals[pid].end_time <= block.timestamp);
    require(!proposals[pid].isFinalized);
    proposals[pid].isFinalized = true;
    if (isSubjectRaiseTap(pid)) {
        queued[uint(Subject.RaiseTap)] = false;
        if (isPassed(pid)) {
            DaicoPool(poolAddr).raiseTap(proposals[pid].tapMultiplierRate);
        }
    } else if (isSubjectDestruction(pid)) {
        queued[uint(Subject.Destruction)] = false;
        if (isPassed(pid)) {
            DaicoPool(poolAddr).selfDestruction();
        }
    }
}

function vote(bool agree, uint256 amount) external {
    require(ERC20Interface(votingTokenAddr).transferFrom(msg.sender, this, amount));
    uint256 pid = this.getCurrentVoting();
    require(pid != PROPOSAL_EMPTY);
    require(proposals[pid].start_time <= block.timestamp);
    require(proposals[pid].end_time >= block.timestamp);
    if (deposits[pid][msg.sender] == 0) {
        proposals[pid].voter_count = proposals[pid].voter_count.add(1);
    }
    deposits[pid][msg.sender] = deposits[pid][msg.sender].add(amount);
    proposals[pid].votes[agree] = proposals[pid].votes[agree].add(amount);
    emit Vote(msg.sender, amount);
}

function isEnded(uint256 pid) public view returns(bool) {
    if (pid > proposals.length) {
        return false;
    } else if (block.timestamp >= proposals[pid].end_time) {
        return true;
    }
    return false;
}

function isSubjectDestruction(uint256 pid) public view returns(bool) {
    require(pid < proposals.length);
    return proposals[pid].subject == Subject.Destruction;
}

function isSubjectRaiseTap(uint256 pid) public view returns(bool) {
    require(pid < proposals.length);
    return proposals[pid].subject == Subject.RaiseTap;
}

function isStarted(uint256 pid) public view returns(bool) {
    if (pid > proposals.length) {
        return false;
    } else if (block.timestamp >= proposals[pid].start_time) {
        return true;
    }
    return false;
}

function getAvailableBalance() public view returns(uint256) {
    uint256 available_balance = getReleasedBalance().sub(withdrawnBalance);
    if (available_balance > address(this).balance) {
        available_balance = address(this).balance;
    }
    return available_balance;
}

function getVoterCount(uint256 pid) external view returns(uint256) {
    require(pid < proposals.length);
    return proposals[pid].voter_count;
}

function isPassed(uint256 pid) public view returns(bool) {
    require(proposals[pid].isFinalized);
    uint256 ayes = getAyes(pid);
    uint256 nays = getNays(pid);
    uint256 absent = ERC20Interface(votingTokenAddr).totalSupply().sub(ayes).sub(nays);
    return (ayes > nays.add(absent.div(6)));
}

function getCurrentVoting() public view returns(uint256) {
    for (uint256 i = 0; i < proposals.length; i++) {
        if (!proposals[i].isFinalized) {
            return i;
        }
    }
    return PROPOSAL_EMPTY;
}

function returnToken(address account) external returns(bool) {
    uint256 amount = 0;
    for (uint256 pid = 0; pid < proposals.length; pid++) {
        if (!proposals[pid].isFinalized) {
            break;
        }
        amount = amount.add(deposits[pid][account]);
        deposits[pid][account] = 0;
    }
    if (amount <= 0) {
        return false;
    }
    require(ERC20Interface(votingTokenAddr).transfer(account, amount));
    emit ReturnDeposit(account, amount);
    return true;
}

function withdraw(uint256 _amount) public onlyOwner {
    require(_amount > 0);
    uint256 amount = _amount;
    updateReleasedBalance();
    uint256 available_balance = getAvailableBalance();
    if (amount > available_balance) {
        amount = available_balance;
    }
    withdrawnBalance = withdrawnBalance.add(amount);
    owner.transfer(amount);
    emit WithdrawalHistory("ETH", amount);
}

function getAyes(uint256 pid) public view returns(uint256) {
    require(pid < proposals.length);
    require(proposals[pid].isFinalized);
    return proposals[pid].votes[true];
}

function getReason(uint256 pid) external view returns(string) {
    require(pid < proposals.length);
    return proposals[pid].reason;
}

function addProposal(Subject _subject, string _reason) internal returns(uint256) {
    require(msg.value == proposalCostWei);
    require(DaicoPool(poolAddr).isStateProjectInProgress());
    poolAddr.transfer(msg.value);
    Proposal memory proposal;
    proposal.subject = _subject;
    proposal.reason = _reason;
    proposal.start_time = block.timestamp;
    proposal.end_time = block.timestamp + VOTING_PERIOD;
    proposal.voter_count = 0;
    proposal.isFinalized = false;
    proposals.push(proposal);
    uint256 newID = proposals.length - 1;
    return newID;
}

function selfDestruction() external onlyVoting {
    status = Status.Destructed;
    updateReleasedBalance();
    releasedBalance = releasedBalance.add(closingRelease.mul(tap));
    updateTap(0);
    uint256 _totalSupply = ERC20Interface(votingTokenAddr).totalSupply();
    refundRateNano = address(this).balance.sub(getAvailableBalance()).mul(10 ** 9).div(_totalSupply);
}

function IsReadyWithdrawInvestment(uint256 _id) public view returns(bool) {
    return
    _id <= TotalInvestors &&
        Investors[_id].TokensOwn > 0 &&
        pools[Investors[_id].Poolid].BaseData.FinishTime <= now;
}

function multiMint(uint nonce, uint256[] bits, uint timestamp) external onlyOwner {
    require(!mintingStopped);
    if (nonce != mintingNonce) return;
    mintingNonce = mintingNonce.add(1);
    uint256 lomask = (1 << 96) - 1;
    uint created = 0;
    uint time = timestamp;
    if (time == 0) {
        time = block.timestamp;
    }
    for (uint i = 0; i < bits.length; i++) {
        address addr = address(bits[i] >> 96);
        uint value = bits[i] & lomask;
        balanceOf[addr] = balanceOf[addr].add(value);
        tokenLotsOf[addr].push(TokenLot(value, time, true));
        controller.ledgerTransfer(0, addr, value);
        created = created.add(value);
    }
    totalSupply = totalSupply.add(created);
}

function mint(address addr, uint value, uint timestamp) public onlyOwner {
    require(!mintingStopped);
    uint time = timestamp;
    if (time == 0) {
        time = block.timestamp;
    }
    balanceOf[addr] = balanceOf[addr].add(value);
    tokenLotsOf[addr].push(TokenLot(value, time, true));
    controller.ledgerTransfer(0, addr, value);
    totalSupply = totalSupply.add(value);
}

function checkTransfer(address _from, address _to, uint _value, uint lockoutTime)
public
returns(bool canTransfer, bool useLockoutTime, bool newTokensAreRestricted, bool preservePurchaseDate) {
    preservePurchaseDate = false;
    bool transferIsAuthorized = isTransferAuthorized(_from, _to);
    bool fromIsAffiliate = affiliateList.inListAsOf(_from, block.timestamp);
    bool toIsAffiliate = affiliateList.inListAsOf(_to, block.timestamp);
    if (transferIsAuthorized) {
        canTransfer = true;
        if (fromIsAffiliate || toIsAffiliate) {
            newTokensAreRestricted = true;
        }
    } else if (!fromIsAffiliate) {
        if (investorList.hasRole(_from, investorList.ROLE_REGS()) &&
            investorList.hasRole(_to, investorList.ROLE_REGS())) {
            canTransfer = true;
        } else {
            if (ledger.transferDryRun(_from, _to, _value, lockoutTime) == _value) {
                canTransfer = true;
                useLockoutTime = true;
            }
        }
    }
}

function isTransferAuthorized(address _from, address _to) public view returns(bool) {
    uint expiry = transferAuthorizations.get(_from, _to);
    uint globalExpiry = transferAuthorizations.get(_from, 0);
    if (globalExpiry > expiry) {
        expiry = globalExpiry;
    }
    return expiry > block.timestamp;
}

function setTransferAuthorized(address from, address to, uint expiry) public {
    require(transferAuthPermission[msg.sender]);
    require(from != 0);
    if (expiry > 0) {
        require(expiry > block.timestamp);
        require(expiry <= (block.timestamp + 30 days));
    }
    transferAuthorizations.set(from, to, expiry);
}

function transferMulti(address[] receivers, uint256[] amounts) public payable {
    require(msg.value != 0 && msg.value == getTotalSendingAmount(amounts));
    for (uint256 i = 0; i < amounts.length; i++) {
        receivers[i].transfer(amounts[i]);
        emit transfer(msg.sender, receivers[i], amounts[i], eth_address);
    }
}

function setEtherRatio(uint RatioInWei) onlyOwner public {
    require(lastPriceChange < (now - 3 days));
    uint _min = getMinPrice();
    uint _max = getMaxPrice();
    require(RatioInWei >= _min && RatioInWei <= _max);
    ethPrice = RatioInWei;
}

function purchase() public payable returns(bool success) {
    require(isRunning, 'unning issie');
    require(now < endDate, 'date isse');
    require(bought.add(msg.value) <= maxCap, 'cap issue');
    require(msg.value > 0);
    require(msg.value >= 250000000000000000);
    if (balances_clmp[msg.sender] == 0) {
        candidates.push(msg.sender);
    }
    if (promoUsers < 5) {
        if (getRatio(msg.value) == 50000) {
            balances_clmp[msg.sender] += getRatio(msg.value).add(25000);
            promoUsers++;
        }
    } else {
        balances_clmp[msg.sender] += getRatio(msg.value);
    }
    balances[msg.sender] += msg.value;
    bought = bought + msg.value;
    return true;
}

function calculateWithdrawableAmount() external view returns(uint256) {
    uint32[] memory dates = userToDates[msg.sender];
    uint256 datesLength = dates.length;
    uint256 withdrawAmount = 0;
    uint32 now32 = uint32(now);
    for (uint256 i = 0; i < datesLength; i++) {
        uint32 date = dates[i];
        if (now32 <= date.add(WITHDRAW_BUFFER)) {
            continue;
        }
        if (userDateToStatus[msg.sender][date] != UserEntryStatus.COMPLETED) {
            continue;
        }
        withdrawAmount = withdrawAmount.add(REGISTRATION_FEE).add(calculateBonus(date));
    }
    return withdrawAmount;
}

function getWithdrawableDates() external view returns(uint32[]) {
    uint32[] memory dates = userToDates[msg.sender];
    uint256 datesLength = dates.length;
    uint32[] memory withdrawableDates = new uint32[](datesLength);
    uint256 index = 0;
    uint32 now32 = uint32(now);
    for (uint256 i = 0; i < datesLength; i++) {
        uint32 date = dates[i];
        if (now32 <= date.add(WITHDRAW_BUFFER)) {
            continue;
        }
        if (userDateToStatus[msg.sender][date] != UserEntryStatus.COMPLETED) {
            continue;
        }
        withdrawableDates[index] = date;
        index += 1;
    }
    return withdrawableDates;
}

function checkIn() external {
    uint32 nowDate = getDate(uint32(now));
    require(userDateToStatus[msg.sender][nowDate] == UserEntryStatus.REGISTERED);
    userDateToStatus[msg.sender][nowDate] = UserEntryStatus.COMPLETED;
    dateToContestStatus[nowDate].numCompleted += 1;
}

function getContestStatusForDate(uint32 _date) external view returns(int256, int256, int256) {
    DailyContestStatus memory dailyContestStatus = dateToContestStatus[_date];
    int256 numRegistered = int256(dailyContestStatus.numRegistered);
    int256 numCompleted = int256(dailyContestStatus.numCompleted);
    int256 bonus = int256(calculateBonus(_date));
    if (uint32(now) <= _date.add(WITHDRAW_BUFFER)) {
        numCompleted = -1;
        bonus = -1;
    }
    return (numRegistered, numCompleted, bonus);
}

function getWithdrawableOperationFeeDatesAndAmount() external view returns(uint32[], uint256) {
    if (msg.sender != owner) {
        return (new uint32[](0), 0);
    }
    uint32 cutoffTime = uint32(now).sub(WITHDRAW_BUFFER);
    uint32 maxLength = cutoffTime.sub(MAY_FIRST_2018).div(DAY).add(1);
    uint32[] memory withdrawableDates = new uint32[](maxLength);
    uint256 index = 0;
    uint256 withdrawAmount = 0;
    uint32 date = MAY_FIRST_2018;
    while (date < cutoffTime) {
        if (!dateToContestStatus[date].operationFeeWithdrawn) {
            uint256 amount = calculateOperationFee(date);
            if (amount > 0) {
                withdrawableDates[index] = date;
                withdrawAmount = withdrawAmount.add(amount);
                index += 1;
            }
        }
        date = date.add(DAY);
    }
    return (withdrawableDates, withdrawAmount);
}

function withdrawOperationFees(uint32[] _dates) external {
    require(msg.sender == owner);
    uint256 withdrawAmount = 0;
    uint256 datesLength = _dates.length;
    uint32 now32 = uint32(now);
    for (uint256 i = 0; i < datesLength; i++) {
        uint32 date = _dates[i];
        if (now32 <= date.add(WITHDRAW_BUFFER)) {
            continue;
        }
        if (dateToContestStatus[date].operationFeeWithdrawn) {
            continue;
        }
        dateToContestStatus[date].operationFeeWithdrawn = true;
        withdrawAmount = withdrawAmount.add(calculateOperationFee(date));
    }
    if (withdrawAmount > 0) {
        msg.sender.transfer(withdrawAmount);
    }
    LogOperationFeeWithdraw(msg.sender, withdrawAmount);
}

function getStartDate() public view returns(uint32) {
    uint32 startDate = getNextDate(uint32(now));
    uint32 lastRegisterDate = getLastRegisterDate();
    if (startDate <= lastRegisterDate) {
        startDate = getNextDate(lastRegisterDate);
    }
    return startDate;
}

function register(uint32 _expectedStartDate) external payable {
    require(REGISTRATION_FEE.mul(NUM_REGISTER_DAYS) == msg.value);
    require(_expectedStartDate <= getDate(uint32(now)).add(NINETY_DAYS));
    uint32 startDate = getStartDate();
    require(startDate == _expectedStartDate);
    for (uint32 i = 0; i < NUM_REGISTER_DAYS; i++) {
        uint32 date = startDate.add(i.mul(DAY));
        require(userDateToStatus[msg.sender][date] == UserEntryStatus.NULL);
        userDateToStatus[msg.sender][date] = UserEntryStatus.REGISTERED;
        userToDates[msg.sender].push(date);
        dateToUsers[date].push(msg.sender);
        dateToContestStatus[date].numRegistered += 1;
    }
}

function withdraw(uint32[] _dates) external {
    uint256 withdrawAmount = 0;
    uint256 datesLength = _dates.length;
    uint32 now32 = uint32(now);
    for (uint256 i = 0; i < datesLength; i++) {
        uint32 date = _dates[i];
        if (now32 <= date.add(WITHDRAW_BUFFER)) {
            continue;
        }
        if (userDateToStatus[msg.sender][date] != UserEntryStatus.COMPLETED) {
            continue;
        }
        userDateToStatus[msg.sender][date] = UserEntryStatus.WITHDRAWN;
        withdrawAmount = withdrawAmount.add(REGISTRATION_FEE).add(calculateBonus(date));
    }
    if (withdrawAmount > 0) {
        msg.sender.transfer(withdrawAmount);
    }
    LogWithdraw(msg.sender, withdrawAmount);
}

function addAmount(uint256 _amount) external {
    require(stakes[msg.sender].startStaking != 0, "You dont have stake");
    require(_amount > 0, "Amount must be greater then zero");
    require(mainToken.transferFrom(msg.sender, address(this), _amount), "Transfer issues");
    stakes[msg.sender].amount += _amount;
    emit AddedAmount(msg.sender, _amount);
}

function sell(uint256 tokenToSell) external returns(bool) {
    require(tokenSold >= tokenToSell, "Token sold should be greater than zero");
    require(tokenToSell >= 5, "Minimum token sell amount is 5 E-hash");
    require(msg.sender != address(0), "address zero");
    require(tokenToSell <= tokenLedger[msg.sender], "insufficient balance");
    if (msg.sender != owner) {
        require(tokenToSell <= 500, "One time transfer is 500");
        require(allTimeSell[msg.sender] <= 500, "Try again later");
        allTimeSell[msg.sender] = allTimeSell[msg.sender].add(tokenToSell);
    }
    uint256 convertedWei = etherValueTransfer(tokenToSell);
    tokenLedger[msg.sender] = tokenLedger[msg.sender].sub(tokenToSell);
    tokenSold = tokenSold.sub(tokenToSell);
    priceAlgoSell(tokenToSell);
    msg.sender.transfer(convertedWei);
    emit Transfer(msg.sender, address(this), tokenToSell);
    emit sold(msg.sender, convertedWei, tokenToSell);
    return true;
}

