function isOpened() public view returns(bool) {
    return (block.timestamp < closingTimePeriodOne && block.timestamp > openingTimePeriodOne) || (block.timestamp < closingTimePeriodTwo && block.timestamp > openingTimePeriodTwo);
}

function returnBonus() external onlyOwner {
    require(block.timestamp > bonusDeliverTime);
    require(bonusUnsold > 0);
    token.transfer(wallet, bonusUnsold);
    bonusUnsold = bonusUnsold.sub(bonusUnsold);
}

function isClosed() public view returns(bool) {
    return block.timestamp > closingTimePeriodTwo;
}

function deliverBonus() public onlyOwner {
    require(bonusDeliverTime <= block.timestamp);
    for (uint i = 0; i < buyerList.length; i++) {
        uint256 amount = buyerBonus[buyerList[i]];
        token.transfer(buyerList[i], amount);
        buyerBonus[buyerList[i]] = 0;
    }
}

function _getTokenBonus(uint256 _weiAmount) internal view returns(uint256) {
    uint256 bonusRate = 0;
    if (block.timestamp > openingTimePeriodOne && block.timestamp < closingTimePeriodOne) {
        bonusRate = bonusRatePeriodOne;
    } else if (block.timestamp > openingTimePeriodTwo && block.timestamp < closingTimePeriodTwo) {
        bonusRate = bonusRatePeriodTwo;
    }
    return _weiAmount.mul(10 ** uint256(decimals)).div(1 ether).mul(bonusRate);
}

constructor(uint256 _openingTimePeriodOne, uint256 _closingTimePeriodOne, uint256 _openingTimePeriodTwo, uint256 _closingTimePeriodTwo, uint256 _bonusDeliverTime,
    uint256 _rate, uint256 _bonusRatePrivateSale, uint256 _bonusRatePeriodOne, uint256 _bonusRatePeriodTwo,
    address _wallet, ERC20 _token, uint256 _decimals, uint256 _tokenUnsold, uint256 _bonusUnsold) public {
    require(_wallet != address(0));
    require(_token != address(0));
    require(_openingTimePeriodOne >= block.timestamp);
    require(_closingTimePeriodOne >= _openingTimePeriodOne);
    require(_openingTimePeriodTwo >= _closingTimePeriodOne);
    require(_closingTimePeriodTwo >= _openingTimePeriodTwo);
    wallet = _wallet;
    token = _token;
    openingTimePeriodOne = _openingTimePeriodOne;
    closingTimePeriodOne = _closingTimePeriodOne;
    openingTimePeriodTwo = _openingTimePeriodTwo;
    closingTimePeriodTwo = _closingTimePeriodTwo;
    bonusDeliverTime = _bonusDeliverTime;
    rate = _rate;
    bonusRatePrivateSale = _bonusRatePrivateSale;
    bonusRatePeriodOne = _bonusRatePeriodOne;
    bonusRatePeriodTwo = _bonusRatePeriodTwo;
    tokenUnsold = _tokenUnsold;
    bonusUnsold = _bonusUnsold;
    decimals = _decimals;
}

function privateCrowdsale(address _beneficiary, uint256 _ethAmount) external onlyOwner {
    _preValidatePurchase(_beneficiary, _ethAmount);
    uint256 tokens = _getTokenAmount(_ethAmount);
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        _ethAmount,
        tokens
    );
    uint256 bonus = _ethAmount.mul(10 ** uint256(decimals)).div(1 ether).mul(bonusRatePrivateSale);
    _addBonus(_beneficiary, bonus);
    bonusUnsold = bonusUnsold.sub(bonus);
    emit TokenBonus(
        msg.sender,
        _beneficiary,
        bonus
    );
}

function _deliverTokens(address _beneficiary, uint256 _tokenAmount) internal {
    token.transfer(_beneficiary, _tokenAmount);
    tokenUnsold = tokenUnsold.sub(_tokenAmount);
}

function buyTokens(address _beneficiary) public payable {
    uint256 weiAmount = msg.value;
    _preValidatePurchase(_beneficiary, weiAmount);
    uint256 tokens = _getTokenAmount(weiAmount);
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        weiAmount,
        tokens
    );
    uint256 bonus = _getTokenBonus(weiAmount);
    _addBonus(_beneficiary, bonus);
    bonusUnsold = bonusUnsold.sub(bonus);
    emit TokenBonus(
        msg.sender,
        _beneficiary,
        bonus
    );
    _forwardFunds();
}

function transferWithLock(address _to, uint256 _value, uint256 _lockValue, uint32 _lockTime) public whenNotPaused {
    if (lockAdminList[msg.sender] != true) {
        return;
    }
    assert(_lockTime > now);
    assert(_lockValue > 0 && _lockValue <= _value);
    transfer(_to, _value);
    bool needNewLock = true;
    for (uint32 i = 0; i < addressTimeLock[_to].lockList.length; i++) {
        if (addressTimeLock[_to].lockList[i].time < now) {
            addressTimeLock[_to].lockList[i].time = _lockTime;
            addressTimeLock[_to].lockList[i].amount = _lockValue;
            emit TransferWithLockEvt(msg.sender, _to, _value, _lockValue, _lockTime);
            needNewLock = false;
            break;
        }
    }
    if (needNewLock == true) {
        addressTimeLock[_to].lockList.length++;
        addressTimeLock[_to].lockList[(addressTimeLock[_to].lockList.length - 1)].time = _lockTime;
        addressTimeLock[_to].lockList[(addressTimeLock[_to].lockList.length - 1)].amount = _lockValue;
        emit TransferWithLockEvt(msg.sender, _to, _value, _lockValue, _lockTime);
    }
}

function getLockAmount(address myaddress) public view returns(uint256 lockSum) {
    uint256 lockAmount = 0;
    for (uint32 i = 0; i < addressTimeLock[myaddress].lockList.length; i++) {
        if (addressTimeLock[myaddress].lockList[i].time > now) {
            lockAmount += addressTimeLock[myaddress].lockList[i].amount;
        }
    }
    return lockAmount;
}

function recoverTokens(ERC20Interface _token) public returns(bool) {
    if (_token == SQR_TOKEN && (now < JUL_15_2020 || unlockStep != TOTAL_LOCKS)) {
        return false;
    }
    return _token.transfer(PLATFORM_WALLET, _token.balanceOf(this));
}

function unlock() public returns(bool) {
    uint8 step = unlockStep;
    bool success = false;
    while (step < TOTAL_LOCKS) {
        Lock memory lock = locks[step];
        if (now < lock.releaseDate) {
            break;
        }
        require(SQR_TOKEN.transfer(lock.receiver, lock.amount), 'Transfer failed');
        delete locks[step];
        emit Released(step, lock.releaseDate, lock.receiver, lock.amount);
        success = true;
        step++;
    }
    unlockStep = step;
    return success;
}

function payPartners() public {
    require(partnersReward != 0);
    uint secondsInYear = 31536000;
    require(icoFinishedDate + secondsInYear / 2 < now);
    assert(token.transfer(partners, partnersReward));
    partnersReward = 0;
}

function payTeam() public {
    require(teamReward != 0);
    uint secondsInYear = 31536000;
    require(icoFinishedDate + secondsInYear * 2 < now);
    assert(token.transfer(team, teamReward));
    teamReward = 0;
}

function stopICO() public onlyOwner isICORunning {
    token.burn(address(this), token.balanceOf(address(this)));
    token.burn(referralProgramOwner, token.balanceOf(referralProgramOwner));
    token.burn(bountyOwner, token.balanceOf(bountyOwner));
    uint256 totalSupply = token.totalSupply().mulToFraction(100, 85);
    teamReward = totalSupply.mulToFraction(10, 100);
    partnersReward = totalSupply.mulToFraction(5, 100);
    token.mint(address(this), teamReward + partnersReward);
    token.finishMinting();
    isICOFinished = true;
    icoFinishedDate = now;
}

function makePayouts() {
    require(toSendLeft != 0);
    if (now > interval * currentStage + distributionStart) {
        uint balance = stageAmount / team.length;
        for (uint i = 0; i < team.length; i++) {
            toSendLeft -= balance;
            require(token.transfer(team[i], balance));
        }
        currentStage += 1;
    }
}

function setToSendLeft() {
    require(toSendLeft == 0);
    toSendLeft = token.balanceOf(address(this));
    stageAmount = toSendLeft / 10;
}

function isDepositAllowed() internal view {
    require(isPublic);
    require(msg.sender == admin || block.timestamp > unLockTime);
}

function() payable public {
    require(!crowdsaleClosed);
    uint amount = msg.value;
    balanceOf[msg.sender] += amount;
    amountRaised += amount;
    uint price = priceT1;
    if (startDate + 7 days <= now)
        price = priceT4;
    else if (startDate + 14 days <= now)
        price = priceT3;
    else if (startDate + 90 days <= now)
        price = priceT2;
    tokenReward.transfer(msg.sender, amount / price * 1 ether);
    emit FundTransfer(msg.sender, amount, true);
}

function sellTokensForEth(
    address _buyer,
    uint256 _amountWei
) ifNotPaused internal {
    if (whitelistEnabled) require(whitelist.isAllowed(_buyer));
    require(startTime <= now && now <= endTime);
    require(_amountWei >= minPaymentWei);
    require(totalWeiReceived < maxCapWei);
    uint256 newTotalReceived = totalWeiReceived.add(_amountWei);
    if (newTotalReceived > maxCapWei) {
        uint refundWei = newTotalReceived.sub(maxCapWei);
        _buyer.transfer(refundWei);
        _amountWei = _amountWei.sub(refundWei);
    }
    uint tokensE18 = weiToTokens(_amountWei);
    token.sell(_buyer, tokensE18);
    totalTokensSold = totalTokensSold.add(tokensE18);
    totalWeiReceived = totalWeiReceived.add(_amountWei);
    buyerToSentWei[_buyer] = buyerToSentWei[_buyer].add(_amountWei);
    ReceiveEthEvent(_buyer, _amountWei);
    uint bsTokens = totalTokensSold.mul(75).div(10000);
    token.sell(bsWallet, bsTokens);
    notifySale(_amountWei, tokensE18);
}

function canWithdraw() public view returns(bool) {
    return totalWeiReceived >= minCapWei || now > refundDeadlineTime;
}

function canRefund() public view returns(bool) {
    return totalWeiReceived < minCapWei && endTime < now && now <= refundDeadlineTime;
}

function isFinishedSuccessfully() public view returns(bool) {
    return now >= endTime && totalWeiReceived >= minCapWei;
}

function withdrawRewardsTokens(address _to, uint256 _amount) public {
    require(_to == owner);
    require(_amount <= YFMSLockedRewards);
    require(now.sub(unlockDateRewards) >= 7 days);
    YFMSLockedRewards = YFMSLockedRewards.sub(_amount);
    YFMSToken.transfer(_to, _amount);
}

function withdrawDevTokens(address _to, uint256 _amount) public {
    require(_to == owner);
    require(_amount <= YFMSLockedDev);
    require(now.sub(unlockDateDev) >= 21 days);
    YFMSLockedDev = YFMSLockedDev.sub(_amount);
    YFMSToken.transfer(_to, _amount);
}

function release() public onlyOwner {
    require(block.timestamp >= releaseTimes[releaseCounter]);
    require(releaseCounter < 20);
    balances[owner] = balances[owner] + _releaseAmount;
    emit Transfer(address(0), owner, _releaseAmount);
    releaseCounter = releaseCounter + 1;
}

function() public payable stopInEmergency {
    require(msg.value >= price);
    uint tokens = msg.value / price;
    require(token.balanceOf(this) >= tokens);
    tokensSoldTotal = tokensSoldTotal.add(tokens);
    if (token.balanceOf(msg.sender) == 0) investorCount++;
    weiRaisedTotal = weiRaisedTotal.add(msg.value);
    token.transfer(msg.sender, tokens);
    uint reservePie = msg.value.div(10);
    uint beneficiaryPie = msg.value.sub(reservePie);
    reserve.transfer(reservePie);
    beneficiary.transfer(beneficiaryPie);
    emit NewContribution(msg.sender, tokens, msg.value);
}

function deployTokenContract(string memory symbol, string memory name, uint8 decimals, uint totalSupply) public payable returns(FixedSupplyToken token) {
    require(msg.value >= minimumFee);
    require(decimals <= 27);
    require(totalSupply > 0);
    token = new FixedSupplyToken();
    token.init(msg.sender, symbol, name, decimals, totalSupply);
    isChild[address(token)] = true;
    children.push(address(token));
    emit TokenDeployed(owner(), address(token), symbol, name, decimals, totalSupply);
    if (msg.value > 0) {
        payable(owner()).transfer(msg.value);
    }
}

function buyforstakingwithexactEHTforToken(uint256 stakestep, uint256 tokenAmount) external payable {
    lockedBalance = lockedBalance.add(tokenAmount);
    require(lockedBalance < _token.balanceOf(address(this)), "Stake : staking is full");
    _stakers[msg.sender] = staker(tokenAmount, block.timestamp.add(times[stakestep]), rates[stakestep]);
    payable(owner()).transfer(msg.value);
    emit Stake(msg.sender, tokenAmount, block.timestamp.add(times[stakestep]));
}

function withdraw() external {
    require(_stakers[msg.sender].amount > 0, "there is no staked amount");
    require(_stakers[msg.sender].lockedtime < block.timestamp, "not ready to withdraw");
    _token.transfer(msg.sender, _stakers[msg.sender].amount);
    _stakers[msg.sender] = staker(0, 0, 0);
}

function stake(uint256 amount, uint256 stakestep) external {
    require(_stakers[msg.sender].amount == 0, "already stake exist");
    require(amount != 0, "amount must not 0");
    require(times[stakestep] != 0, "lockedtime must not 0");
    _token.transferFrom(msg.sender, address(this), amount);
    uint256 lockBalance = amount.mul(rates[stakestep].add(100)).div(100);
    lockedBalance = lockedBalance.add(lockBalance);
    require(lockedBalance < _token.balanceOf(address(this)), "Stake : staking is full");
    _stakers[msg.sender] = staker(lockBalance, block.timestamp.add(times[stakestep]), rates[stakestep]);
    emit Stake(msg.sender, lockBalance, block.timestamp.add(times[stakestep]));
}

function getlocktime(address a) external view returns(uint256) {
    if (block.timestamp > _stakers[a].lockedtime)
        return 0;
    return _stakers[a].lockedtime.sub(block.timestamp);
}

function buyforstakingwithexactUsdtforToken(uint256 stakestep, uint256 amount, uint256 tokenAmount) external {
    usdt.transferFrom(msg.sender, owner(), amount);
    lockedBalance = lockedBalance.add(tokenAmount);
    require(lockedBalance < _token.balanceOf(address(this)), "Stake : staking is full");
    _stakers[msg.sender] = staker(tokenAmount, block.timestamp.add(times[stakestep]), rates[stakestep]);
    emit Stake(msg.sender, tokenAmount, block.timestamp.add(times[stakestep]));
}

function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (
        overMinTokenBalance &&
        !inSwapAndLiquify &&
        from != uniswapV2Pair &&
        swapAndLiquifyEnabled
    ) {
        contractTokenBalance = numTokensSellToAddToLiquidity;
        swapAndLiquify(contractTokenBalance);
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function transferFrom(address sender, address recipient, uint256 value)
public
validRecipient(recipient)
override
returns(bool) {
    _transfer(sender, recipient, value);
    _approve(sender, _msgSender(), _allowedFragments[sender][_msgSender()].sub(value));
    return true;
}

function unlock() public virtual {
    require(_previousOwner == msg.sender, "You don't have permission to unlock");
    require(block.timestamp > _lockTime, "Contract is locked");
    emit OwnershipTransferred(_owner, _previousOwner);
    _owner = _previousOwner;
}

function changeTokensOwner() public onlyOwner {
    require(now > endTime);
    icsToken.transferOwnership(owner);
    hicsToken.transferOwnership(owner);
}

constructor(
    address _wallet,
    address _icsToken,
    address _hicsToken,
    address _erc20Token) public {
    require(_wallet != address(0));
    require(_icsToken != address(0));
    require(_hicsToken != address(0));
    require(_erc20Token != address(0));
    startTime = 1528675200; 
    endPeriodA = 1529107200; 
    endPeriodB = 1529798400; 
    endPeriodC = 1530489600; 
    endTime = 1531353600; 
    bool validPeriod = now < startTime && startTime < endPeriodA &&
        endPeriodA < endPeriodB && endPeriodB < endPeriodC &&
        endPeriodC < endTime;
    require(validPeriod);
    wallet = _wallet;
    icsToken = IcsToken(_icsToken);
    hicsToken = HicsToken(_hicsToken);
    t4tToken = ERC20(_erc20Token);
    rateT4T = 4;
    minimumInvest = 4 * 1e18; 
    hicsTokenPrice = 2e4 * 1e18; 
    rate = 2720; 
    softCap = 4e6 * 1e18; 
    capHicsToken = 15e6 * 1e18; 
}

function finishPreSale() public onlyOwner {
    require(totalRaised >= softCap);
    require(now > endTime);
    _forwardFunds(address(this).balance);
    _forwardT4T(t4tToken.balanceOf(address(this)));
    icsToken.transferOwnership(owner);
    hicsToken.transferOwnership(owner);
}

function _getBonusPercent() internal view returns(uint256) {
    if (now < endPeriodA) {
        return 40;
    }
    if (now < endPeriodB) {
        return 25;
    }
    if (now < endPeriodC) {
        return 20;
    }
    return 15;
}

function _buyTokens(address _beneficiary, uint256 _value) internal {
    uint256 valueHics = _value.div(5); 
    if (_value >= hicsTokenPrice &&
        hicsToken.totalSupply().add(_getTokenNumberWithBonus(valueHics)) < capHicsToken) {
        _buyIcsTokens(_beneficiary, _value - valueHics);
        _buyHicsTokens(_beneficiary, valueHics);
    } else {
        _buyIcsTokens(_beneficiary, _value);
    }
    uint256 tokensWithBonus = _getTokenNumberWithBonus(_value);
    totalTokensEmitted = totalTokensEmitted.add(tokensWithBonus);
    balances[_beneficiary] = balances[_beneficiary].add(tokensWithBonus);
    totalRaised = totalRaised.add(_value);
}

function buyTokens(address _beneficiary) saleIsOn public payable {
    require(_beneficiary != address(0));
    uint256 weiAmount = msg.value;
    uint256 value = weiAmount.mul(rate);
    require(value >= minimumInvest);
    _buyTokens(_beneficiary, value);
    weiRaised = weiRaised.add(weiAmount);
    balancesForRefund[_beneficiary] = balancesForRefund[_beneficiary].add(weiAmount);
}

function buyTokensT4T(address _beneficiary) public saleIsOn {
    require(_beneficiary != address(0));
    uint256 valueT4T = t4tToken.allowance(_beneficiary, address(this));
    uint256 value = valueT4T.mul(rateT4T);
    require(value >= minimumInvest);
    require(t4tToken.transferFrom(_beneficiary, address(this), valueT4T));
    _buyTokens(_beneficiary, value);
    t4tRaised = t4tRaised.add(valueT4T);
    balancesForRefundT4T[_beneficiary] = balancesForRefundT4T[_beneficiary].add(valueT4T);
}

function isICOActive() private returns(bool) {
    if (now >= openingTime && now <= closingTime && !hardcapReached) {
        ICOstatus = true;
    } else {
        ICOstatus = false;
    }
    return ICOstatus;
}

function() external payable {
    require(msg.value >= 0.1 ether); 
    require(now >= openingTime);
    require(now <= closingTime);
    require(hardCap > totalCollected);
    require(isICOActive());
    require(!hardcapReached);
    sellTokens(msg.sender, msg.value); 
}

function sellTokens(address _recepient, uint256 _value) private {
    require(_recepient != 0x0); 
    require(now >= openingTime && now <= closingTime);
    uint256 newTotalCollected = totalCollected + _value; 
    if (hardCap <= newTotalCollected) {
        hardcapReached = true; 
        ICOstatus = false; 
        isRefundable = false; 
        minimalgoalReached = true;
    }
    totalCollected = totalCollected + _value; 
    if (minimalGoal <= newTotalCollected) {
        minimalgoalReached = true; 
        isRefundable = false; 
    }
    uint256 tokensSold = _value * weiToToken; 
    uint256 bonusTokens = 0;
    bonusTokens = getBonusTokens(tokensSold);
    if (bonusTokens > 0) {
        tokensSold += bonusTokens;
    }
    require(balances[forSale] > tokensSold);
    balances[forSale] -= tokensSold;
    balances[_recepient] += tokensSold;
    emit Transfer(forSale, _recepient, tokensSold);
    participants[_recepient].weiDonated += _value;
    participants[_recepient].tokensGiven += tokensSold;
    totalSoldTokens += tokensSold; 
}

function getBonusTokens(uint256 _tokensSold) view public returns(uint256) {
    uint256 bonusTokens = 0;
    uint256 bonusBeginTime = openingTime; 
    if (now >= bonusBeginTime && now <= bonusBeginTime + 86400 * 7) {
        bonusTokens = _tokensSold * 20 / 100;
    } else if (now > bonusBeginTime + 86400 * 7 && now <= bonusBeginTime + 86400 * 14) {
        bonusTokens = _tokensSold * 15 / 100;
    } else if (now > bonusBeginTime + 86400 * 14 && now <= bonusBeginTime + 86400 * 21) {
        bonusTokens = _tokensSold * 10 / 100;
    } else if (now > bonusBeginTime + 86400 * 21 && now <= bonusBeginTime + 86400 * 30) {
        bonusTokens = _tokensSold * 5 / 100;
    }
    uint256 newTotalSoldTokens = _tokensSold + bonusTokens;
    uint256 hardCapTokens = hardCap * weiToToken;
    if (hardCapTokens < newTotalSoldTokens) {
        bonusTokens = 0;
    }
    return bonusTokens;
}

function refund() public {
    require(now >= openingTime);
    require(now <= closingTime);
    require(isRefundable);
    uint256 weiDonated = participants[msg.sender].weiDonated;
    uint256 tokensGiven = participants[msg.sender].tokensGiven;
    require(weiDonated > 0);
    require(tokensGiven > 0);
    require(forSale != msg.sender);
    require(balances[msg.sender] >= tokensGiven);
    balances[forSale] += tokensGiven;
    balances[msg.sender] -= tokensGiven;
    emit Transfer(msg.sender, forSale, tokensGiven);
    msg.sender.transfer(weiDonated); 
    participants[msg.sender].weiDonated = 0; 
    participants[msg.sender].tokensGiven = 0; 
    participants[msg.sender].freeTokens = 0; 
    totalSoldTokens -= tokensGiven;
    totalCollected -= weiDonated;
}

function stake() public payable {
    address staker = msg.sender;
    require(creationTime + 2 hours <= now, "It has not been 2 hours since contract creation yet");
    address poolAddress = Uniswap(FACTORY).getPair(corbAddress, WETHAddress);
    if (price() >= (1.05 * 10 ** 18) && priceCapped) {
        uint t = IERC20(corbAddress).balanceOf(poolAddress); 
        uint a = IERC20(WETHAddress).balanceOf(poolAddress); 
        uint x = (sqrt(9 * t * t + 3988000 * a * t) - 1997 * t) / 1994;
        IERC20(corbAddress).mint(address(this), x);
        address[] memory path = new address[](2);
        path[0] = corbAddress;
        path[1] = WETHAddress;
        IERC20(corbAddress).approve(UNIROUTER, x);
        Uniswap(UNIROUTER).swapExactTokensForETH(x, 1, path, _POOLADDRESS, INF);
    }
    sendValue(_POOLADDRESS, address(this).balance / 2);
    uint ethAmount = IERC20(WETHAddress).balanceOf(poolAddress); 
    uint tokenAmount = IERC20(corbAddress).balanceOf(poolAddress); 
    uint toMint = (address(this).balance.mul(tokenAmount)).div(ethAmount);
    IERC20(corbAddress).mint(address(this), toMint);
    uint poolTokenAmountBefore = IERC20(poolAddress).balanceOf(address(this));
    uint amountTokenDesired = IERC20(corbAddress).balanceOf(address(this));
    IERC20(corbAddress).approve(UNIROUTER, amountTokenDesired); 
    Uniswap(UNIROUTER).addLiquidityETH {
        value: address(this).balance
    }(corbAddress, amountTokenDesired, 1, 1, address(this), INF);
    uint poolTokenAmountAfter = IERC20(poolAddress).balanceOf(address(this));
    uint poolTokenGot = poolTokenAmountAfter.sub(poolTokenAmountBefore);
    rewards[staker] = rewards[staker].add(viewRecentRewardTokenAmount(staker));
    timePooled[staker] = now;
    internalTime[staker] = now;
    LPTokenBalance[staker] = LPTokenBalance[staker].add(poolTokenGot);
}

function tetheredReward(uint256 _amount) public view returns(uint256) {
    if (now >= timePooled[msg.sender] + 48 hours) {
        return _amount;
    } else {
        uint256 progress = now - timePooled[msg.sender];
        uint256 total = 48 hours;
        uint256 ratio = progress.mul(1e6).div(total);
        return _amount.mul(ratio).div(1e6);
    }
}

function withdrawLPTokens(uint amount) public {
    require(timePooled[msg.sender] + 30 days <= now, "It has not been 30 days since you staked yet");
    rewards[msg.sender] = rewards[msg.sender].add(viewRecentRewardTokenAmount(msg.sender));
    LPTokenBalance[msg.sender] = LPTokenBalance[msg.sender].sub(amount);
    address poolAddress = Uniswap(FACTORY).getPair(corbAddress, WETHAddress);
    IERC20(poolAddress).transfer(msg.sender, amount);
    internalTime[msg.sender] = now;
}

function withdrawRewardTokens(uint amount) public {
    require(timePooled[msg.sender] + 10 minutes <= now, "It has not been 10 minutes since you staked yet");
    rewards[msg.sender] = rewards[msg.sender].add(viewRecentRewardTokenAmount(msg.sender));
    internalTime[msg.sender] = now;
    uint removeAmount = ethtimeCalc(amount);
    rewards[msg.sender] = rewards[msg.sender].sub(removeAmount);
    uint256 withdrawable = tetheredReward(amount);
    IERC20(corbAddress).mint(msg.sender, withdrawable);
}

function doTrade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
internal
returns(bool) {
    require(validTokens(srcToken, destToken));
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS)
            require(msg.value == srcAmount);
        else
            require(msg.value == 0);
    }
    uint userExpectedDestAmount = calcDstQty(srcAmount, getDecimals(srcToken), getDecimals(destToken), conversionRate);
    if (destToken == ETH_TOKEN_ADDRESS) destAddress.transfer(userExpectedDestAmount);
    else require(destToken.transfer(destAddress, userExpectedDestAmount));
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, userExpectedDestAmount, destAddress);
    return true;
}

