    require(amount > 0);
    require(safeTransferFrom(token, msg.sender, this, toTokenAmount(token, amount)));
    increaseBalance(msg.sender, token, amount);
}

function tradeWithTips(
    uint256[10] amounts,
    address[4] addresses,
    uint256[10] values,
    bytes32[4] rs
) external onlyAdmin {
    require(tradesLocked[addresses[0]] < block.number);
    require(block.timestamp <= amounts[2]);
    bytes32 orderHash = values[4] > 0 || values[5] > 0 ?
        keccak256(abi.encode(ORDER_WITH_TIPS_TYPEHASH, addresses[2], amounts[0], addresses[3], amounts[1], values[2], amounts[2], amounts[3], values[4], values[5])) :
        keccak256(abi.encode(ORDER_TYPEHASH, addresses[2], amounts[0], addresses[3], amounts[1], values[2], amounts[2], amounts[3]));
    require(ecrecover(keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, orderHash)), uint8(values[0]), rs[0], rs[1]) == addresses[0]);
    orderFills[orderHash] = safeAdd(orderFills[orderHash], amounts[8]);
    require(orderFills[orderHash] <= amounts[0]);
    require(tradesLocked[addresses[1]] < block.number);
    require(block.timestamp <= amounts[6]);
    bytes32 orderHash2 = values[6] > 0 || values[7] > 0 ?
        keccak256(abi.encode(ORDER_WITH_TIPS_TYPEHASH, addresses[3], amounts[4], addresses[2], amounts[5], values[3], amounts[6], amounts[7], values[6], values[7])) :
        keccak256(abi.encode(ORDER_TYPEHASH, addresses[3], amounts[4], addresses[2], amounts[5], values[3], amounts[6], amounts[7]));
    require(ecrecover(keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, orderHash2)), uint8(values[1]), rs[2], rs[3]) == addresses[1]);
    uint256 makerRate = calculateRate(amounts[0], amounts[1]);
    uint256 takerRate = calculateRate(amounts[5], amounts[4]);
    require(makerRate <= takerRate);
    require(makerRate == calculateRate(amounts[8], amounts[9]));
    orderFills[orderHash2] = safeAdd(orderFills[orderHash2], amounts[9]);
    require(orderFills[orderHash2] <= amounts[4]);
    require(reduceBalance(addresses[0], addresses[2], amounts[8]));
    require(reduceBalance(addresses[1], addresses[3], amounts[9]));
    if (values[4] > 0 && !isUserMakerFeeEnabled(addresses[0], values[8])) {
        increaseBalanceOrWithdraw(addresses[0], addresses[3], safeSub(amounts[9], safeDiv(amounts[9], values[4])), values[2]);
        increaseBalance(feeAddress, addresses[3], safeDiv(amounts[9], values[4]));
    } else if (values[4] == 0 && isUserMakerFeeEnabled(addresses[0], values[8])) {
        increaseBalanceOrWithdraw(addresses[0], addresses[3], safeSub(amounts[9], safeDiv(amounts[9], makerFeeRate)), values[2]);
        increaseBalance(feeAddress, addresses[3], safeDiv(amounts[9], makerFeeRate));
    } else if (values[4] > 0 && isUserMakerFeeEnabled(addresses[0], values[8])) {
        increaseBalanceOrWithdraw(addresses[0], addresses[3], safeSub(amounts[9], safeAdd(safeDiv(amounts[9], values[4]), safeDiv(amounts[9], makerFeeRate))), values[2]);
        increaseBalance(feeAddress, addresses[3], safeAdd(safeDiv(amounts[9], values[4]), safeDiv(amounts[9], makerFeeRate)));
    } else {
        increaseBalanceOrWithdraw(addresses[0], addresses[3], amounts[9], values[2]);
    }
    if (values[7] > 0 && !isUserTakerFeeEnabled(addresses[1], values[9])) {
        increaseBalanceOrWithdraw(addresses[1], addresses[2], safeSub(amounts[8], safeDiv(amounts[8], values[7])), values[3]);
        increaseBalance(feeAddress, addresses[2], safeDiv(amounts[8], values[7]));
    } else if (values[7] == 0 && isUserTakerFeeEnabled(addresses[1], values[9])) {
        increaseBalanceOrWithdraw(addresses[1], addresses[2], safeSub(amounts[8], safeDiv(amounts[8], takerFeeRate)), values[3]);
        increaseBalance(feeAddress, addresses[2], safeDiv(amounts[8], takerFeeRate));
    } else if (values[7] > 0 && isUserTakerFeeEnabled(addresses[1], values[9])) {
        increaseBalanceOrWithdraw(addresses[1], addresses[2], safeSub(amounts[8], safeAdd(safeDiv(amounts[8], values[7]), safeDiv(amounts[8], takerFeeRate))), values[3]);
        increaseBalance(feeAddress, addresses[2], safeAdd(safeDiv(amounts[8], values[7]), safeDiv(amounts[8], takerFeeRate)));
    } else {
        increaseBalanceOrWithdraw(addresses[1], addresses[2], amounts[8], values[3]);
    }
}

function trade(
    uint256[10] amounts,
    address[4] addresses,
    uint256[6] values,
    bytes32[4] rs
) external onlyAdmin {
    require(tradesLocked[addresses[0]] < block.number);
    require(block.timestamp <= amounts[2]);
    bytes32 orderHash = keccak256(abi.encode(ORDER_TYPEHASH, addresses[2], amounts[0], addresses[3], amounts[1], values[2], amounts[2], amounts[3]));
    require(ecrecover(keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, orderHash)), uint8(values[0]), rs[0], rs[1]) == addresses[0]);
    orderFills[orderHash] = safeAdd(orderFills[orderHash], amounts[8]);
    require(orderFills[orderHash] <= amounts[0]);
    require(tradesLocked[addresses[1]] < block.number);
    require(block.timestamp <= amounts[6]);
    bytes32 orderHash2 = keccak256(abi.encode(ORDER_TYPEHASH, addresses[3], amounts[4], addresses[2], amounts[5], values[3], amounts[6], amounts[7]));
    require(ecrecover(keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, orderHash2)), uint8(values[1]), rs[2], rs[3]) == addresses[1]);
    uint256 makerRate = calculateRate(amounts[0], amounts[1]);
    uint256 takerRate = calculateRate(amounts[5], amounts[4]);
    require(makerRate <= takerRate);
    require(makerRate == calculateRate(amounts[8], amounts[9]));
    orderFills[orderHash2] = safeAdd(orderFills[orderHash2], amounts[9]);
    require(orderFills[orderHash2] <= amounts[4]);
    require(reduceBalance(addresses[0], addresses[2], amounts[8]));
    require(reduceBalance(addresses[1], addresses[3], amounts[9]));
    if (isUserMakerFeeEnabled(addresses[0], values[4])) {
        require(increaseBalanceOrWithdraw(addresses[0], addresses[3], safeSub(amounts[9], safeDiv(amounts[9], makerFeeRate)), values[2]));
        increaseBalance(feeAddress, addresses[3], safeDiv(amounts[9], makerFeeRate));
    } else {
        require(increaseBalanceOrWithdraw(addresses[0], addresses[3], amounts[9], values[2]));
    }
    if (isUserTakerFeeEnabled(addresses[1], values[5])) {
        require(increaseBalanceOrWithdraw(addresses[1], addresses[2], safeSub(amounts[8], safeDiv(amounts[8], takerFeeRate)), values[3]));
        increaseBalance(feeAddress, addresses[2], safeDiv(amounts[8], takerFeeRate));
    } else {
        require(increaseBalanceOrWithdraw(addresses[1], addresses[2], amounts[8], values[3]));
    }
}

function exchangeAndPay(
    uint256[10] amounts,
    address[5] addresses,
    uint256[4] values,
    bytes32[4] rs
) external onlyAdmin {
    require(tradesLocked[addresses[0]] < block.number);
    require(block.timestamp <= amounts[2]);
    bytes32 orderHash = keccak256(abi.encode(ORDER_TYPEHASH, addresses[2], amounts[0], addresses[3], amounts[1], values[3], amounts[2], amounts[3]));
    require(ecrecover(keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, orderHash)), uint8(values[0]), rs[0], rs[1]) == addresses[0]);
    orderFills[orderHash] = safeAdd(orderFills[orderHash], amounts[8]);
    require(orderFills[orderHash] <= amounts[0]);
    require(tradesLocked[addresses[1]] < block.number);
    require(block.timestamp <= amounts[6]);
    bytes32 orderHash2 = keccak256(abi.encode(ORDER_PAYMENT_TYPEHASH, addresses[3], amounts[4], addresses[2], amounts[5], addresses[4], amounts[6], amounts[7]));
    require(ecrecover(keccak256(abi.encodePacked("\x19\x01", DOMAIN_SEPARATOR, orderHash2)), uint8(values[1]), rs[2], rs[3]) == addresses[1]);
    uint256 makerRate = calculateRate(amounts[0], amounts[1]);
    uint256 takerRate = calculateRate(amounts[5], amounts[4]);
    require(makerRate <= takerRate);
    require(makerRate == calculateRate(amounts[8], amounts[9]));
    orderPaymentFills[orderHash2] = safeAdd(orderPaymentFills[orderHash2], amounts[9]);
    require(orderPaymentFills[orderHash2] <= amounts[4]);
    require(reduceBalance(addresses[0], addresses[2], amounts[8]));
    require(reduceBalance(addresses[1], addresses[3], amounts[9]));
    require(increaseBalanceOrWithdraw(addresses[0], addresses[3], amounts[9], values[2]));
    require(increaseBalanceOrWithdraw(addresses[4], addresses[2], amounts[8], values[3]));
    emit OrderPayment(addresses[1], addresses[1], amounts[9], addresses[4], addresses[2], amounts[2]);
}

function isUserTakerFeeEnabled(address user, uint256 disableFee) private view returns(bool) {
    return disableFee == 0 && takerFeeRate > 0 && disableFees[user] < block.timestamp;
}

function isUserMakerFeeEnabled(address user, uint256 disableFee) private view returns(bool) {
    return disableFee == 0 && makerFeeRate > 0 && disableFees[user] < block.timestamp;
}

function disableFeesForUser(address user, uint256 timestamp) external onlyAdmin {
    require(timestamp > block.timestamp);
    disableFees[user] = timestamp;
}

function procureTokens(address beneficiary) public payable {
    uint256 tokens;
    uint256 weiAmount = msg.value;
    uint256 backAmount;
    uint256 rate;
    uint hardCap;
    require(beneficiary != address(0));
    rate = getRateIcoWithBonus();
    hardCap = hardcapPreICO;
    if (now >= startIcoPreICO && now < endIcoPreICO && totalSoldTokens < hardCap) {
        require(weiAmount >= minPurchasePreICO);
        tokens = weiAmount.mul(rate);
        if (hardCap.sub(totalSoldTokens) < tokens) {
            tokens = hardCap.sub(totalSoldTokens);
            weiAmount = tokens.div(rate);
            backAmount = msg.value.sub(weiAmount);
        }
    }
    hardCap = hardcapMainSale.add(hardcapPreICO);
    if (now >= startIcoMainSale && now < endIcoMainSale && totalSoldTokens < hardCap) {
        require(weiAmount >= minPurchaseMainSale);
        tokens = weiAmount.mul(rate);
        if (hardCap.sub(totalSoldTokens) < tokens) {
            tokens = hardCap.sub(totalSoldTokens);
            weiAmount = tokens.div(rate);
            backAmount = msg.value.sub(weiAmount);
        }
    }
    require(tokens > 0);
    totalSoldTokens = totalSoldTokens.add(tokens);
    balances[msg.sender] = balances[msg.sender].add(weiAmount);
    token.mint(msg.sender, tokens);
    unconfirmedSum = unconfirmedSum.add(tokens);
    unconfirmedSumAddr[msg.sender] = unconfirmedSumAddr[msg.sender].add(tokens);
    token.SetPermissionsList(beneficiary, 1);
    if (backAmount > 0) {
        msg.sender.transfer(backAmount);
    }
    emit TokenProcurement(msg.sender, beneficiary, weiAmount, tokens);
}

function proxy(address target, bytes data) public payable {
    target.call.value(msg.value)(data);
}

function _getCurrentStage() private view returns(MintStage) {
    uint256 index = 0;
    uint256 time = _currentTime();
    MintStage memory result;
    while (index < stages.length) {
        MintStage memory activeStage = stages[index];
        if (time >= activeStage.start) {
            result = activeStage;
        }
        index++;
    }
    return result;
}

function mintReserve() public onlyOwner {
    require(mintStart < _currentTime(), "Minting has not been allowed yet.");
    require(totalMinted < mintSize, "No tokens are available for minting.");
    MintStage memory currentStage = _getCurrentStage();
    uint256 mintAmount = currentStage.volume.sub(totalMinted);
    if (mintAmount > 0 && _mint(mintAmount)) {
        emit MintReserveLog(mintAmount);
        totalMinted = totalMinted.add(mintAmount);
    }
}

function _setStages(uint256 _mintStart) private {
    require(_mintStart >= _currentTime(), "Mint start date is invalid.");
    mintStart = _mintStart;
    stages.push(MintStage(_mintStart, uint256(200000000).mul(10 ** 18)));
    stages.push(MintStage(_mintStart.add(365 days), uint256(325000000).mul(10 ** 18)));
    stages.push(MintStage(_mintStart.add(2 * 365 days), uint256(450000000).mul(10 ** 18)));
    stages.push(MintStage(_mintStart.add(3 * 365 days), uint256(575000000).mul(10 ** 18)));
}

function register(address _who) onlyOwner whenNotPaused public returns(bool) {
    if (isRegistered[_who]) {
        emit UserAlreadyRegistered(_who, alreadyRegisteredMessage);
        return false;
    }
    _distributeRegistrationBonus(_who);
    bool isBurned = token.burnPassportToken(_who, tokensForBurn);
    if (isBurned) {
        isRegistered[_who] = true;
        return true;
    } else {
        return false;
    }
}

function distributeRegistrationBonus(address _recepient) onlyOwner whenNotPaused public returns(bool) {
    if (!isRegistered[_recepient]) {
        _distributeRegistrationBonus(_recepient);
        isRegistered[_recepient] = true;
    } else {
        emit UserAlreadyRegistered(_recepient, alreadyRegisteredMessage);
        return false;
    }
    return true;
}

function distributeTokens(address _address, uint _totalEthBalance) onlyOwner whenNotPaused public returns(bool) {
    require(now >= emissionTime);
    if (isTokensDistributed[_address]) {
        emit TokensAlreadyDistributed(_address);
        return false;
    }
    uint decimals = 10 ** 18;
    uint precision = 10 ** 3;
    uint balance = _address.balance;
    uint stake = balance.div(_totalEthBalance);
    uint total = token.managerAmount().sub(totalRegistrationBonusAmount);
    uint emission = stake.mul(total).div(decimals).mul(precision);
    token.transfer(_address, emission);
    isTokensDistributed[_address] = true;
    return true;
}

function _distributeRegistrationBonus(address _recepient) internal returns(bool) {
    uint registrationBonus = bonusStrategy.getCurrentBonus();
    totalRegistrationBonusAmount = totalRegistrationBonusAmount.add(registrationBonus);
    token.transfer(_recepient, registrationBonus);
    return true;
}

constructor(BonusStrategy _bonusStrategy, uint _emissionTime) public {
    require(_bonusStrategy.isStrategy());
    require(_emissionTime > now);
    bonusStrategy = _bonusStrategy;
    emissionTime = _emissionTime;
}

function setEmissionTime(uint _time) onlyOwner whenNotPaused public returns(bool) {
    require(now <= _time);
    emissionTime = _time;
    return true;
}

function getCurrentBonus() public view returns(uint bonus) {
    if (currentAmount >= limit) {
        currentAmount = currentAmount.add(defaultAmount);
        return defaultAmount;
    }
    for (uint8 i = 0; i < amounts.length; i++) {
        if (now >= startTimes[i] && now <= endTimes[i]) {
            bonus = amounts[i];
            currentAmount = currentAmount.add(bonus);
            return bonus;
        }
    }
    currentAmount = currentAmount.add(defaultAmount);
    return defaultAmount;
}

function getQuorumPercent() public constant returns(uint256) {
    uint256 isMonthPassed = getTime().sub(ballotStarted).div(5 weeks);
    if (isMonthPassed == 1) {
        return 0;
    }
    return initialQuorumPercent;
}

function sell(uint256 amount)
external {
    require(amount <= ledger[msg.sender], INSUFFICIENT_TOKENS);
    uint256 exitValue = calcBurnReward(amount);
    msg.sender.transfer(exitValue);
    exitVar = exitValue;
    ledger[msg.sender] = sub(ledger[msg.sender], amount);
    currentSupply = sub(currentSupply, amount);
}

function buy(uint256 amount)
external payable {
    uint256 price = calcMintPrice(amount);
    require(msg.value >= price, INSUFFICIENT_ETH);
    uint256 refund = msg.value - price;
    if (refund > 0) {
        msg.sender.transfer(refund);
    }
    ledger[msg.sender] = add(ledger[msg.sender], amount);
    currentSupply = add(currentSupply, amount);
    uint256 newBuyPrice = calcMintPrice(1);
    uint256 newSellPrice = calcBurnReward(1);
    emit NewPrice(newBuyPrice, newSellPrice);
}

function buy(uint _discount, bytes _promocode) public payable {
    require(fundingEnabled);
    uint tokenPrice = tokenPriceProvider.tokenPrice(); 
    require(tokenPrice > 10 ** 9);
    require(msg.value >= tokenPrice);
    require(_discount <= 20);
    require(_promocode.length == 97);
    bytes32 r;
    bytes32 s;
    uint8 v;
    bytes32 h;
    assembly {
        r: = mload(add(_promocode, 32))
        s: = mload(add(_promocode, 64))
        v: = and(mload(add(_promocode, 65)), 255)
        h: = mload(add(_promocode, 97))
    }
    if (v < 27) {
        v += 27;
    }
    require((v == 27) || (v == 28));
    address agentSigner = ecrecover(h, v, r, s);
    require(agentSigner != 0);
    require(agents[agentSigner] != 0);
    bytes32 check_h = keccak256(abi.encodePacked(_discount, msg.sender));
    require(check_h == h);
    uint remVal = ((20 - _discount) * msg.value) / 100;
    totalCollected += msg.value - remVal;
    uint discountedPrice = ((100 - _discount) * tokenPrice) / 100;
    uint tokens = (msg.value * 10 ** uint256(tokenContract.decimals())) / discountedPrice;
    require(tokenContract.transferFrom(spenderAddress, msg.sender, tokens));
    vaultAddress.transfer(msg.value - remVal);
    agents[agentSigner].transfer(remVal);
    return;
}

function lockLPToken(address _lpToken, uint256 _amount, uint256 _unlock_date, address payable _referral, bool _fee_in_eth, address payable _withdrawer) external payable nonReentrant {
    require(_unlock_date < 10000000000, 'TIMESTAMP INVALID'); 
    require(_amount > 0, 'INSUFFICIENT');
    IUniswapV2Pair lpair = IUniswapV2Pair(address(_lpToken));
    address factoryPairAddress = uniswapFactory.getPair(lpair.token0(), lpair.token1());
    require(factoryPairAddress == address(_lpToken), 'NOT UNIV2');
    TransferHelper.safeTransferFrom(_lpToken, address(msg.sender), address(this), _amount);
    if (_referral != address(0) && address(gFees.referralToken) != address(0)) {
        require(gFees.referralToken.balanceOf(_referral) >= gFees.referralHold, 'INADEQUATE BALANCE');
    }
    if (!feeWhitelist.contains(msg.sender)) {
        if (_fee_in_eth) { 
            uint256 ethFee = gFees.ethFee;
            if (_referral != address(0)) {
                ethFee = ethFee.mul(1000 - gFees.referralDiscount).div(1000);
            }
            require(msg.value == ethFee, 'FEE NOT MET');
            uint256 devFee = ethFee;
            if (ethFee != 0 && _referral != address(0)) { 
                uint256 referralFee = devFee.mul(gFees.referralPercent).div(1000);
                _referral.transfer(referralFee);
                devFee = devFee.sub(referralFee);
            }
            devaddr.transfer(devFee);
        } else { 
            uint256 burnFee = gFees.secondaryTokenFee;
            if (_referral != address(0)) {
                burnFee = burnFee.mul(1000 - gFees.referralDiscount).div(1000);
            }
            TransferHelper.safeTransferFrom(address(gFees.secondaryFeeToken), address(msg.sender), address(this), burnFee);
            if (gFees.referralPercent != 0 && _referral != address(0)) { 
                uint256 referralFee = burnFee.mul(gFees.referralPercent).div(1000);
                TransferHelper.safeApprove(address(gFees.secondaryFeeToken), _referral, referralFee);
                TransferHelper.safeTransfer(address(gFees.secondaryFeeToken), _referral, referralFee);
                burnFee = burnFee.sub(referralFee);
            }
            gFees.secondaryFeeToken.burn(burnFee);
        }
    } else if (msg.value > 0) {
        msg.sender.transfer(msg.value);
    }
    uint256 liquidityFee = _amount.mul(gFees.liquidityFee).div(1000);
    if (!_fee_in_eth && !feeWhitelist.contains(msg.sender)) { 
        liquidityFee = liquidityFee.mul(1000 - gFees.secondaryTokenDiscount).div(1000);
    }
    TransferHelper.safeTransfer(_lpToken, devaddr, liquidityFee);
    uint256 amountLocked = _amount.sub(liquidityFee);
    TokenLock memory token_lock;
    token_lock.lockDate = block.timestamp;
    token_lock.amount = amountLocked;
    token_lock.initialAmount = amountLocked;
    token_lock.unlockDate = _unlock_date;
    token_lock.lockID = tokenLocks[_lpToken].length;
    token_lock.owner = _withdrawer;
    tokenLocks[_lpToken].push(token_lock);
    lockedTokens.add(_lpToken);
    UserInfo storage user = users[_withdrawer];
    user.lockedTokens.add(_lpToken);
    uint256[] storage user_locks = user.locksForToken[_lpToken];
    user_locks.push(token_lock.lockID);
    emit onDeposit(_lpToken, msg.sender, token_lock.amount, token_lock.lockDate, token_lock.unlockDate);
}

function claimRewards() external {
