function buytoken(uint256 _tokenId) payable public {
    address newOwner = msg.sender;
    address oldOwner = tokenOwners[_tokenId];
    require(tokenExists[_tokenId]);
    require(newOwner != ownerOf(_tokenId));
    require(msg.value >= tokens[_tokenId].price);
    uint256 _remainder = msg.value - tokens[_tokenId].price;
    newOwner.transfer(_remainder);
    uint256 price20 = tokens[_tokenId].price / 5;
    _admin.transfer(price20 / 20);
    oldOwner.transfer(tokens[_tokenId].price - price20 / 20);
    tokens[_tokenId].price += price20;
    tokenOwners[_tokenId] = newOwner;
    balances[oldOwner] -= 1;
    balances[newOwner] += 1;
    emit Transfer(oldOwner, newOwner, _tokenId);
}

function stake(uint256 _amount) public payable {
    require(paused == false, "E09");
    require(currentStakers <= maximumStakers, "E03");
    StakerInfo storage user = stakerInfo[msg.sender];
    require(user.amount.add(_amount) >= minimumStake, "E01");
    require(dnxcToken.transferFrom(msg.sender, address(this), _amount), "E02");
    if (user.amount == 0) {
        require(msg.value >= stakingFee, "E04");
        user.startStakeTime = block.timestamp;
        currentStakers = currentStakers.add(1);
    }
    user.amount = user.amount.add(_amount);
}

function unstake() public {
    StakerInfo storage user = stakerInfo[msg.sender];
    require(user.amount > 0, "E06");
    dnxcToken.transfer(
        msg.sender,
        user.amount
    );
    if (user.claimedEggs == 0) {
        currentStakers = currentStakers - 1;
    }
    user.amount = 0;
    user.claimedEggs = 0;
    user.claimedTickets = 0;
    user.startStakeTime = 0;
    delete stakerInfo[msg.sender];
}

function requestRandomness(
    bytes32 _keyHash,
    uint256 _fee
)
internal
returns(
    bytes32 requestId
) {
    LINK.transferAndCall(vrfCoordinator, _fee, abi.encode(_keyHash, USER_SEED_PLACEHOLDER));
    uint256 vRFSeed = makeVRFInputSeed(_keyHash, USER_SEED_PLACEHOLDER, address(this), nonces[_keyHash]);
    nonces[_keyHash] = nonces[_keyHash] + 1;
    return makeRequestId(_keyHash, vRFSeed);
}

function isEggClaimable(address _user) public view returns(bool) {
    StakerInfo storage user = stakerInfo[_user];
    require(user.claimedEggs < 1, "E05");
    uint256 cappedAmount = user.amount;
    if (cappedAmount > maximumStake) {
        cappedAmount = maximumStake;
    }
    uint256 ratio = cappedAmount.sub(minimumStake).div(10000000000000000000);
    if (ratio > 450) {
        ratio = 450;
    }
    return (block.timestamp > user.startStakeTime + (timeTable[ratio] * 1 days));
}

function claimEgg(address _recipent) public {
    require(msg.sender == _rewardDistributor, "E03");
    StakerInfo storage user = stakerInfo[_recipent];
    require(isEggClaimable(_recipent), "E07");
    require(user.claimedEggs < 1, "E05");
    user.claimedEggs = 1;
}

function claimTickets(address _recipent) public {
    require(msg.sender == _rewardDistributor, "E03");
    StakerInfo storage user = stakerInfo[_recipent];
    require(countTicketsClaimable(_recipent) > 0, "E08");
    user.claimedTickets = user.claimedTickets.add(countTicketsClaimable(_recipent));
}

function isRoundOneSalePeriod(uint date) public constant returns(bool) {
    return date >= roundOneFrom && date <= roundOneUntil && roundOneAmount > 0;
}

function isRoundThreeSalePeriod(uint date) public constant returns(bool) {
    return date >= roundThreeFrom && date <= roundThreeUntil && roundThreeAmount > 0;
}

function isRoundTwoSalePeriod(uint date) public constant returns(bool) {
    return date >= roundTwoFrom && date <= roundTwoUntil && roundTwoAmount > 0;
}

function isPreSalePeriod(uint date) public constant returns(bool) {
    return date >= preSaleFrom && date <= preSaleUntil && preSaleAmount > 0;
}

function() public payable {
    require(now >= startDate && msg.value >= 1000000000000000000);
    uint tokens = 0;
    if (isPreSalePeriod(now)) {
        tokens = msg.value * 13000;
        preSaleAmount = zeroSub(preSaleAmount, tokens);
    }
    if (isRoundOneSalePeriod(now)) {
        tokens = msg.value * 11500;
        roundOneAmount = zeroSub(roundOneAmount, tokens);
    }
    if (isRoundTwoSalePeriod(now)) {
        tokens = msg.value * 11000;
        roundTwoAmount = zeroSub(roundTwoAmount, tokens);
    }
    if (isRoundThreeSalePeriod(now)) {
        tokens = msg.value * 10500;
        roundThreeAmount = zeroSub(roundThreeAmount, tokens);
    }
    require(tokens > 0);
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    emit Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function withdraw() external {
    require(
        block.timestamp > endTime,
        'MerkleDistributor: Withdraw failed, cannot claim until after validBlocks diff'
    );
    require(
        IERC20(token).transfer(withdrawAddress, IERC20(token).balanceOf(address(this))),
        'MerkleDistributor: Withdraw transfer failed.'
    );
}

function claim(uint256 index, uint256 amount, bytes32[] calldata merkleProof) external override {
    require(!isClaimed(index), 'MerkleDistributor: Drop already claimed.');
    require(endTime >= block.timestamp, 'MerkleDistributor: Drop already end.');
    address account = msg.sender;
    require(!blackAccountMap[account], "MerkleDistributor: in black list");
    bytes32 node = keccak256(abi.encodePacked(index, account, amount));
    require(MerkleProof.verify(merkleProof, merkleRoot, node), 'MerkleDistributor: Invalid proof.');
    _setClaimed(index);
    require(IERC20(token).transfer(account, amount), 'MerkleDistributor: Transfer failed.');
    emit Claimed(index, account, amount);
}

function distributeReward(
    address pair,
    uint256 ethAmount,
    uint256 erc20Amount,
    address rewardTo
) external override nonReentrant {
    require(routerAllowed[msg.sender], "CVaultForTrader: not allowed router"); 
    require(pair != address(0), "CVaultForTrader: invalid pair");
    require(rewardTo != address(0), "CVaultForTrader: invalid rewardTo");
    uint256 amount;
    {
        uint256 totalAccruedAmount;
        uint256 neededETHAmount;
        (uint256 reserve0, uint256 reserve1) = ICoFiXV2Pair(pair).getReserves();
        (amount, totalAccruedAmount, neededETHAmount) = actualMiningAmount(pair, reserve0, reserve1, ethAmount, erc20Amount);
        lastMinedBlock[pair] = uint128(block.number); 
        lastTotalAccruedAmount[pair] = totalAccruedAmount;
        lastNeededETHAmount[pair] = neededETHAmount;
    }
    {
        uint256 amountForTrader = amount.mul(SHARE_FOR_TRADER).div(SHARE_BASE);
        uint256 amountForCNode = amount.mul(SHARE_FOR_CNODE).div(SHARE_BASE);
        ICoFiToken(cofiToken).mint(rewardTo, amountForTrader); 
        pendingRewardsForCNode = pendingRewardsForCNode.add(amountForCNode);
    }
}

function joinPool(uint poolAmountOut, uint[] calldata maxAmountsIn)
external
_logs_
_lock_ {
    require(_finalized, "NOT_FINALIZED");
    uint poolTotal = totalSupply();
    uint ratio = bdiv(poolAmountOut, poolTotal);
    require(ratio != 0, "MATH_APPROX");
    for (uint i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint bal = _records[t].balance;
        uint tokenAmountIn = bmul(ratio, bal);
        require(tokenAmountIn != 0, "MATH_APPROX");
        require(tokenAmountIn <= maxAmountsIn[i], "LIMIT_IN");
        _records[t].balance = badd(_records[t].balance, tokenAmountIn);
        emit LOG_JOIN(msg.sender, t, tokenAmountIn);
        _pullUnderlying(t, msg.sender, tokenAmountIn);
    }
    (uint poolAmountOutAfterFee, uint poolAmountOutFee) = calcAmountWithCommunityFee(
        poolAmountOut,
        _communityJoinFee,
        msg.sender
    );
    _mintPoolShare(poolAmountOut);
    _pushPoolShare(msg.sender, poolAmountOutAfterFee);
    _pushPoolShare(_communityFeeReceiver, poolAmountOutFee);
}

function exitPool(uint poolAmountIn, uint[] calldata minAmountsOut)
external
_logs_
_lock_ {
    require(_finalized, "NOT_FINALIZED");
    (uint poolAmountInAfterFee, uint poolAmountInFee) = calcAmountWithCommunityFee(
        poolAmountIn,
        _communityExitFee,
        msg.sender
    );
    uint poolTotal = totalSupply();
    uint ratio = bdiv(poolAmountInAfterFee, poolTotal);
    require(ratio != 0, "MATH_APPROX");
    _pullPoolShare(msg.sender, poolAmountIn);
    _pushPoolShare(_communityFeeReceiver, poolAmountInFee);
    _burnPoolShare(poolAmountInAfterFee);
    for (uint i = 0; i < _tokens.length; i++) {
        address t = _tokens[i];
        uint bal = _records[t].balance;
        uint tokenAmountOut = bmul(ratio, bal);
        require(tokenAmountOut != 0, "MATH_APPROX");
        require(tokenAmountOut >= minAmountsOut[i], "LIMIT_OUT");
        _records[t].balance = bsub(_records[t].balance, tokenAmountOut);
        emit LOG_EXIT(msg.sender, t, tokenAmountOut);
        _pushUnderlying(t, msg.sender, tokenAmountOut);
    }
}

function takeOwnership(uint256 _tokenId) requireDataContract requireBattleContract requireTradeContract isActive external {
    EtheremonDataBase data = EtheremonDataBase(dataContract);
    MonsterObjAcc memory obj;
    (obj.monsterId, obj.classId, obj.trainer, obj.exp, obj.createIndex, obj.lastClaimIndex, obj.createTime) = data.getMonsterObj(uint64(_tokenId));
    require(obj.monsterId == uint64(_tokenId));
    require(msg.sender != obj.trainer);
    require(allowed[obj.trainer][_tokenId] == msg.sender);
    EtheremonBattle battle = EtheremonBattle(battleContract);
    EtheremonTradeInterface trade = EtheremonTradeInterface(tradeContract);
    if (battle.isOnBattle(obj.monsterId) || trade.isOnTrading(obj.monsterId))
        revert();
    allowed[obj.trainer][_tokenId] = address(0);
    data.removeMonsterIdMapping(obj.trainer, obj.monsterId);
    data.addMonsterIdMapping(msg.sender, obj.monsterId);
    Transfer(obj.trainer, msg.sender, _tokenId);
}

