function _getCategoryIdx(uint position) private view returns(uint8) {
    uint32 tempSum = 0;
    uint8 chosenIdx = 255;
    for (uint8 i = 0; i < mineralCounts.length; i++) {
        uint32 value = mineralCounts[i];
        tempSum += value;
        if (tempSum > position) {
            chosenIdx = i;
            break;
        }
    }
    return chosenIdx;
}

function executeOrder(uint256 assetId, uint256 price) public whenNotPaused {
    address seller = auctionByAssetId[assetId].seller;
    require(seller != address(0));
    require(seller != msg.sender);
    require(auctionByAssetId[assetId].price == price);
    require(now < auctionByAssetId[assetId].expiresAt);
    require(seller == nonFungibleRegistry.ownerOf(assetId));
    uint saleShareAmount = 0;
    if (ownerCutPercentage > 0) {
        saleShareAmount = price.mul(ownerCutPercentage).div(100);
        acceptedToken.transferFrom(
            msg.sender,
            owner,
            saleShareAmount
        );
    }
    acceptedToken.transferFrom(
        msg.sender,
        seller,
        price.sub(saleShareAmount)
    );
    nonFungibleRegistry.safeTransferFrom(
        seller,
        msg.sender,
        assetId
    );
    bytes32 auctionId = auctionByAssetId[assetId].id;
    delete auctionByAssetId[assetId];
    AuctionSuccessful(auctionId, assetId, seller, price, msg.sender);
}

function createOrder(uint256 assetId, uint256 priceInWei, uint256 expiresAt) public whenNotPaused {
    address assetOwner = nonFungibleRegistry.ownerOf(assetId);
    require(msg.sender == assetOwner);
    require(nonFungibleRegistry.isAuthorized(address(this), assetId));
    require(priceInWei > 0);
    require(expiresAt > now.add(1 minutes));
    bytes32 auctionId = keccak256(
        block.timestamp,
        assetOwner,
        assetId,
        priceInWei
    );
    auctionByAssetId[assetId] = Auction({
        id: auctionId,
        seller: assetOwner,
        price: priceInWei,
        expiresAt: expiresAt
    });
    if (publicationFeeInWei > 0) {
        require(acceptedToken.transferFrom(
            msg.sender,
            owner,
            publicationFeeInWei
        ));
    }
    AuctionCreated(
        auctionId,
        assetId,
        assetOwner,
        priceInWei,
        expiresAt
    );
}

function cancelOrder(uint256 assetId) public whenNotPaused {
    require(auctionByAssetId[assetId].seller == msg.sender || msg.sender == owner);
    bytes32 auctionId = auctionByAssetId[assetId].id;
    address auctionSeller = auctionByAssetId[assetId].seller;
    delete auctionByAssetId[assetId];
    AuctionCancelled(auctionId, assetId, auctionSeller);
}

function createMultipleLocks(address _tokenAddress, address _withdrawalAddress, uint256[] _amounts, uint256[] _unlockTimes) public returns(uint256 _id) {
    require(_amounts.length > 0);
    require(_amounts.length == _unlockTimes.length);
    uint256 i;
    for (i = 0; i < _amounts.length; i++) {
        require(_amounts[i] > 0);
        require(_unlockTimes[i] < 10000000000);
        walletTokenBalance[_tokenAddress][_withdrawalAddress] = walletTokenBalance[_tokenAddress][_withdrawalAddress].add(_amounts[i]);
        _id = ++depositId;
        lockedToken[_id].tokenAddress = _tokenAddress;
        lockedToken[_id].withdrawalAddress = _withdrawalAddress;
        lockedToken[_id].tokenAmount = _amounts[i];
        lockedToken[_id].unlockTime = _unlockTimes[i];
        lockedToken[_id].withdrawn = false;
        allDepositIds.push(_id);
        depositsByWithdrawalAddress[_withdrawalAddress].push(_id);
        require(Token(_tokenAddress).transferFrom(msg.sender, this, _amounts[i]));
    }
}

function withdrawTokens(uint256 _id) public {
    require(block.timestamp >= lockedToken[_id].unlockTime);
    require(msg.sender == lockedToken[_id].withdrawalAddress);
    require(!lockedToken[_id].withdrawn);
    lockedToken[_id].withdrawn = true;
    walletTokenBalance[lockedToken[_id].tokenAddress][msg.sender] = walletTokenBalance[lockedToken[_id].tokenAddress][msg.sender].sub(lockedToken[_id].tokenAmount);
    uint256 j;
    uint256 arrLength = depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress].length;
    for (j = 0; j < arrLength; j++) {
        if (depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress][j] == _id) {
            depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress][j] = depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress][arrLength - 1];
            depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress].length--;
            break;
        }
    }
    require(Token(lockedToken[_id].tokenAddress).transfer(msg.sender, lockedToken[_id].tokenAmount));
    emit LogWithdrawal(msg.sender, lockedToken[_id].tokenAmount);
}

function Buy(address seller, address tokenAddress) public payable {
    if (seller == msg.sender) revert('buyer and seller cannot be the same');
    erc20 token = erc20(tokenAddress);
    uint allowance = getAvailableBalanceForSale(seller, tokenAddress);
    uint sellerPrice = weiPriceUnitTokenList[seller][tokenAddress] * allowance / 10 ** token.decimals();
    uint buyFee = fee * sellerPrice / feeDecimals;
    if ((msg.value != sellerPrice + buyFee) || msg.value == 0) revert('Price sent not correct');
    token.transferFrom(seller, msg.sender, allowance);
    if (!payable(seller).send(sellerPrice)) revert('Error while sending payment to seller');
    emit SoldEvent(seller, msg.sender, tokenAddress, allowance, weiPriceUnitTokenList[seller][tokenAddress], (sellerPrice + buyFee), buyFee);
    weiPriceUnitTokenList[seller][tokenAddress] = 0;
}

function userWithdraw(address withdrawAddress, uint256 amount)
public
payable
onlyGovernance {
    require(
