function requestMortgageId(
    Engine engine,
    uint256 loanId,
    uint256 deposit,
    uint256 landId,
    TokenConverter tokenConverter
) public returns(uint256 id) {
    require(engine.getCurrency(loanId) == MANA_CURRENCY, "Loan currency is not MANA");
    address borrower = engine.getBorrower(loanId);
    require(engine.getStatus(loanId) == Engine.Status.initial, "Loan status is not inital");
    require(msg.sender == engine.getBorrower(loanId) ||
        (msg.sender == engine.getCreator(loanId) && creators[msg.sender]),
        "Creator should be borrower or authorized");
    require(engine.isApproved(loanId), "Loan is not approved");
    require(rcn.allowance(borrower, this) >= REQUIRED_ALLOWANCE, "Manager cannot handle borrower's funds");
    require(tokenConverter != address(0), "Token converter not defined");
    require(loanToLiability[engine][loanId] == 0, "Liability for loan already exists");
    uint256 landCost;
    (, , landCost, ) = landMarket.auctionByAssetId(landId);
    uint256 loanAmount = engine.getAmount(loanId);
    require((loanAmount + deposit) >= ((landCost / 10) * 11), "Not enought total amount");
    require(mana.transferFrom(msg.sender, this, deposit), "Error pulling mana");
    id = mortgages.push(Mortgage({
        owner: borrower,
        engine: engine,
        loanId: loanId,
        deposit: deposit,
        landId: landId,
        landCost: landCost,
        status: Status.Pending,
        tokenConverter: tokenConverter
    })) - 1;
    loanToLiability[engine][loanId] = id;
    emit RequestedMortgage({
        _id: id,
        _borrower: borrower,
        _engine: engine,
        _loanId: loanId,
        _landId: landId,
        _deposit: deposit,
        _tokenConverter: tokenConverter
    });
}

function fixedExp(int256 a) public pure returns(uint256 exp) {
    int256 scale = (a + (ln2_64dot5)) / ln2 - 64;
    a -= scale * ln2;
    int256 z = (a * a) / one;
    int256 R = ((int256)(2) * one) +
        (z * (c2 + (z * (c4 + (z * (c6 + (z * c8 / one)) / one)) / one)) / one);
    exp = (uint256)(((R + a) * one) / (R - a));
    if (scale >= 0)
        exp <<= scale;
    else
        exp >>= -scale;
    return exp;
}

function _claimTokens(address target) internal {
    if (timer[target] == 0) {
        if (balances[target] > 0) {
        } else {
            return;
        }
    }
    if (timer[target] == now) {
        return;
    }
    uint256 totalTkn = _getPoS(target);
    if (totalTkn > 0) {
        balances[target] = balances[target].add(totalTkn);
        emit PoS(target, totalTkn);
    }
    emit Transfer(address(0x0), target, totalTkn);
}

function _getPoS(address target) internal view returns(uint256) {
    if (balances[target] == 0) {
        return 0;
    }
    int ONE_SECOND = 0x10000000000000000;
    uint TIME = timer[target];
    if (TIME == 0) {
        TIME = GLOBAL_START_TIMER;
    }
    if (balances[target] < getStakingRequirementTime(target, TIME)) {
        uint flipTime = getRequirementTime(target);
        if (now > flipTime) {
            TIME = flipTime;
        } else {
            return 0;
        }
    }
    int PORTION_SCALED = ((int(GLOBAL_START_TIMER) - int(TIME)) * ONE_SECOND) / int(stakeUnit);
    uint256 exp = fixedExp(PORTION_SCALED);
    PORTION_SCALED = ((int(GLOBAL_START_TIMER) - int(now)) * ONE_SECOND) / int(stakeUnit);
    uint256 exp2 = fixedExp(PORTION_SCALED);
    uint256 MULT = (9 * (exp.sub(exp2)) * (balances[target])) / (uint(one));
    return (MULT);
}

function getRequirementTime(address target) view returns(uint256) {
    uint256 balance = balances[target];
    int ONE = 0x10000000000000000;
    if (balance == 0) {
        return (uint256(0) - 1); 
    }
    uint TIME = timer[target];
    if (TIME == 0) {
        TIME = GLOBAL_START_TIMER;
    }
    int ln = fixedLog((balance * uint(one)) / stakingRequirement);
    int mul = (int(timerUnit) * ln) / (int(one));
    uint pos = uint(-mul);
    return (pos + GLOBAL_START_TIMER);
}

function isOpen() public view returns(bool) {
    return now >= openingTime;
}

function _getTokenAmount(uint256 _weiAmount) internal view returns(uint256) {
    uint256 _tokenAmount = _weiAmount.mul(rate);
    uint256 _bonus = 0;
    if (_tokenAmount >= oneHundredThousand && _tokenAmount < fiveHundredThousand) {
        _bonus = (_tokenAmount.mul(5)).div(100);
    } else if (_tokenAmount >= fiveHundredThousand && _tokenAmount < oneMillion) {
        _bonus = (_tokenAmount.mul(10)).div(100);
    } else if (_tokenAmount >= oneMillion && _tokenAmount < twoMillionFourHundredThousand) {
        _bonus = (_tokenAmount.mul(15)).div(100);
    } else if (_tokenAmount >= twoMillionFourHundredThousand && _tokenAmount < threeMillionTwoHundredThousand) {
        _bonus = (_tokenAmount.mul(20)).div(100);
    } else if (_tokenAmount >= threeMillionTwoHundredThousand) {
        _bonus = (_tokenAmount.mul(25)).div(100);
    }
    _tokenAmount = _tokenAmount.add(_bonus);
    if (now.sub(openingTime) <= earlyBirdDuration) {
        _bonus = (_tokenAmount.mul(10)).div(100);
        _tokenAmount = _tokenAmount.add(_bonus);
    }
    return _tokenAmount;
}

