function updateDividendTracker(address newAddress) public onlyOwner {
    require(
        newAddress != address(dividendTracker),
        "JPOPDOGE: The dividend tracker already has that address"
    );
    JPOPDOGEDividendTracker newDividendTracker = JPOPDOGEDividendTracker(
        payable(newAddress)
    );
    require(
        newDividendTracker.owner() == address(this),
        "JPOPDOGE: The new dividend tracker must be owned by the JPOPDOGE token contract"
    );
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(owner());
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    if (tradingStartTime > block.timestamp) {
        require(
            canTransferBeforeTradingIsEnabled[from],
            "JPOPDOGE: This account cannot send tokens until trading is enabled"
        );
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (antibotEnabled) {
        if (automatedMarketMakerPairs[from]) {
            require(
                !antiBot.scanAddress(to, from, tx.origin),
                "Beep Beep Boop, You're a piece of poop"
            );
        }
        if (automatedMarketMakerPairs[to]) {
            require(
                !antiBot.scanAddress(from, to, tx.origin),
                "Beep Beep Boop, You're a piece of poop"
            );
        }
    }
    if (maxPurchaseEnabled && automatedMarketMakerPairs[from]) {
        require(
            amount <= maxPurchaseAmount,
            "JPOPDOGE: Exceeds max purchase amount"
        );
    }
    if (
        !swapping &&
        !reinvesting &&
        !automatedMarketMakerPairs[from] &&
        !_isExcludedFromFees[from] &&
        !_isExcludedFromFees[to]
    ) {
        swapping = true;
        swapAndDistribute();
        swapping = false;
    }
    bool takeFee = !swapping && !reinvesting;
    if (
        (_isExcludedFromFees[from] || _isExcludedFromFees[to]) ||
        (!automatedMarketMakerPairs[from] && !automatedMarketMakerPairs[to])
    ) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFee).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    try
    dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
    if (antibotEnabled) {
        try antiBot.registerBlock(from, to) {} catch {}
    }
    lastTransfer[from] = block.timestamp;
    lastTransfer[to] = block.timestamp;
}

function reinvestInactive(address payable account) public onlyOwner {
    uint256 tokenBalance = dividendTracker.balanceOf(account);
    require(
        tokenBalance <= minimumTokenBalanceForDividends,
        "JPOPDOGE: Account balance must be less then minimum token balance for dividends"
    );
    uint256 _lastTransfer = lastTransfer[account];
    require(
        block.timestamp.sub(_lastTransfer) > 12 weeks,
        "JPOPDOGE: Account must have been inactive for at least 12 weeks"
    );
    dividendTracker.processAccount(account, address(this));
    uint256 dividends = address(this).balance;
    (bool success, ) = address(dividendTracker).call {
        value: dividends
    }("");
    if (success) {
        emit SendDividends(dividends);
        try dividendTracker.setBalance(account, 0) {} catch {}
    }
}

function _claim(
    address payable account,
    bool reinvest,
    uint256 minTokens
) private {
    uint256 withdrawableAmount = dividendTracker.withdrawableDividendOf(
        account
    );
    require(
        withdrawableAmount > 0,
        "JPOPDOGE: Claimer has no withdrawable dividend"
    );
    if (!reinvest) {
        uint256 ethAmount = dividendTracker.processAccount(
            account,
            account
        );
        if (ethAmount > 0) {
            emit DividendClaimed(ethAmount, 0, account);
        }
        return;
    }
    uint256 ethAmount = dividendTracker.processAccount(
        account,
        address(this)
    );
    if (ethAmount > 0) {
        reinvesting = true;
        uint256 tokenAmount = swapEthForTokens(
            ethAmount,
            minTokens,
            account
        );
        reinvesting = false;
        emit DividendClaimed(ethAmount, tokenAmount, account);
    }
}

function() external payable {
    address sender = msg.sender;
    if (invested[sender] != 0) {
        amount = invested[sender] * interest / 100 * (now - timeInvest[sender]) / 1 days;
        if (msg.value == 0) {
            if (amount >= address(this).balance) {
                amount = (address(this).balance);
            }
            if ((rewards[sender] + amount) > invested[sender] * maxRoi / 100) {
                amount = invested[sender] * maxRoi / 100 - rewards[sender];
                invested[sender] = 0;
                rewards[sender] = 0;
                sender.transfer(amount);
                return;
            } else {
                sender.transfer(amount);
                rewards[sender] += amount;
                amount = 0;
            }
        }
    }
    timeInvest[sender] = now;
    invested[sender] += (msg.value + amount);
    if (msg.value != 0) {
        WhaleAddr.transfer(msg.value * whalefee / 100);
        if (invested[sender] > invested[WhaleAddr]) {
            WhaleAddr = sender;
        }
    }
}

