function transfer(address _to, uint value) public returns(bool success) {
    require(_to != 0x0);
    require(balances[msg.sender] >= value);
    startDate = now;
    if (msg.sender == owner1 || msg.sender == owner2) {
        balances[_to] = balances[_to].add(value);
        balances[msg.sender] = balances[msg.sender].sub(value);
    } else if (startDate > endDate) {
        balances[_to] = balances[_to].add(value);
        balances[msg.sender] = balances[msg.sender].sub(value);
    }
    emit Transfer(msg.sender, _to, value);
    return true;
}

function checkSale() public view returns(bool success) {
    if (startDate > endDate) {
        return true;
    } else {
        return false;
    }
}

function _createLiquidity(uint phase) internal {
    address WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address token = 0x95A28A02Ffb969e48B78554777f223445661fB9f;
    address staking = 0xB0b3E52e432b80D3A37e15AB6BBF4673225e160f;
    address factory = 0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f;
    address tknETHLP = I(factory).getPair(token, WETH);
    if (tknETHLP == address(0)) {
        tknETHLP = I(factory).createPair(token, WETH);
    }
    _ETHDeposited += address(this).balance;
    uint ethToDeposit = address(this).balance;
    uint tokenToDeposit = 1e23;
    if (phase == 81000) {
        I(staking).init(_ETHDeposited, tknETHLP);
        delete _lgeOngoing;
        delete _ETHDeposited;
        delete _phase;
        delete _deployer;
    }
    I(WETH).deposit {
        value: ethToDeposit
    }();
    I(token).transfer(tknETHLP, tokenToDeposit);
    I(WETH).transfer(tknETHLP, ethToDeposit);
    I(tknETHLP).mint(staking);
}

function() payable {
    totalEthInWei = totalEthInWei + msg.value;
    require(balances[fundsWallet] >= amount);
    require(now >= startDate && now <= endDate);
    uint256 amount;
    if (now <= bonus1Ends) {
        amount = msg.value * unitsOneEthCanBuy * 8;
    } else if (now <= bonus2Ends && now > bonus1Ends) {
        amount = msg.value * unitsOneEthCanBuy * 6;
    } else if (now <= bonus3Ends && now > bonus2Ends) {
        amount = msg.value * unitsOneEthCanBuy * 5;
    } else {
        amount = msg.value * unitsOneEthCanBuy * 4;
    }
    balances[fundsWallet] = balances[fundsWallet] - amount;
    balances[msg.sender] = balances[msg.sender] + amount;
    Transfer(fundsWallet, msg.sender, amount);
    fundsWallet.transfer(msg.value);
}

function getBagLevel(Bag bag) private view returns(uint256) {
    if (now <= (SafeMath.add(bag.purchasedAt, timeout))) {
        return bag.level;
    } else {
        StocksAddress.transfer(SafeMath.div(this.balance, 2));
        return 0;
    }
}

function ownerSetStakeStartTime(uint timestamp) public onlyOwner {
    require(stakeStartTime <= 0);
    stakeStartTime = timestamp;
}

function annualInterest() public returns(uint interest) {
    uint _now = now;
    interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime).div(1 years) == 0) || (_now.sub(stakeStartTime).div(1 years) == 1)) {
        interest = (1650 * maxMintProofOfStake).div(100);
    } else if ((_now.sub(stakeStartTime).div(1 years) == 2) || (_now.sub(stakeStartTime).div(1 years) == 3) ||
        (_now.sub(stakeStartTime).div(1 years) == 4) || (_now.sub(stakeStartTime).div(1 years) == 5) ||
        (_now.sub(stakeStartTime).div(1 years) == 6)) {
        interest = (435 * maxMintProofOfStake).div(100);
    }
}

function getProofOfStakeReward(address _address) internal view returns(uint) {
    require((now >= stakeStartTime) && (stakeStartTime > 0));
    uint _now = now;
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    uint interest = maxMintProofOfStake;
    if ((_now.sub(stakeStartTime).div(1 years) == 0) || (_now.sub(stakeStartTime).div(1 years) == 1)) {
        interest = (1650 * maxMintProofOfStake).div(100);
    } else if ((_now.sub(stakeStartTime).div(1 years) == 2) || (_now.sub(stakeStartTime).div(1 years) == 3) ||
        (_now.sub(stakeStartTime).div(1 years) == 4) || (_now.sub(stakeStartTime).div(1 years) == 5) ||
        (_now.sub(stakeStartTime).div(1 years) == 6)) {
        interest = (435 * maxMintProofOfStake).div(100);
    }
    return (_coinAge * interest).div(365 * (10 ** decimals));
}

function setCrowdsale(address _crowdsale) external onlyOwner {
    require(_crowdsale != address(0));
    require(crowdsale == address(0));
    crowdsale = _crowdsale;
}

function() public payable {
    require(msg.sender == crowdsale);
    uint256 fundsToTransfer = msg.value;
    if (txFeeCapInWei > 0 && txFeeSentInWei < txFeeCapInWei) {
        for (uint i = 0; i < txFeeAddresses.length; i++) {
            uint256 txFeeToSendInWei = msg.value.mul(txFeeNumerator[i]).div(txFeeDenominator);
            if (txFeeToSendInWei > 0) {
                txFeeSentInWei = txFeeSentInWei.add(txFeeToSendInWei);
                fundsToTransfer = fundsToTransfer.sub(txFeeToSendInWei);
                txFeeAddresses[i].transfer(txFeeToSendInWei);
            }
        }
    }
    ethFundsWallet.transfer(fundsToTransfer);
}

function getAuctions(address bidder) public view returns(
    uint40[5] _timeEnd,
    uint40[5] _lastBidTime,
    uint256[5] _highestBid,
    address[5] _highestBidder,
    uint16[5] _auctionIndex,
    uint256 _pendingReturn) {
    _pendingReturn = pendingReturns[bidder];
    uint16 j = 0;
    for (uint16 i = 0; i < auctions.length; i++) {
        if (!isEnded(i)) {
            _timeEnd[j] = auctions[i].timeEnd;
            _lastBidTime[j] = auctions[i].lastBidTime;
            _highestBid[j] = auctions[i].highestBid;
            _highestBidder[j] = auctions[i].highestBidder;
            _auctionIndex[j] = i;
            j++;
            if (j > 5) {
                break;
            }
        }
    }
}

function bid(uint16 auction, uint256 useFromPendingReturn) public payable whenNotPaused {
    if (auctions[auction].highestBidder != address(0)) {
        pendingReturns[auctions[auction].highestBidder] += auctions[auction].highestBid;
        totalReturns += auctions[auction].highestBid;
    }
    require(useFromPendingReturn <= pendingReturns[msg.sender]);
    uint256 bank = useFromPendingReturn;
    pendingReturns[msg.sender] -= bank;
    totalReturns -= bank;
    uint256 currentBid = bank + msg.value;
    require(currentBid > auctions[auction].highestBid ||
        currentBid == auctions[auction].highestBid && auctions[auction].highestBidder == address(0));
    require(!isEnded(auction));
    auctions[auction].highestBid = currentBid;
    auctions[auction].highestBidder = msg.sender;
    auctions[auction].lastBidTime = uint40(now);
}

function Retrieve(string _password, address _originAddress) external
isAddress(_originAddress)
onlyPayloadSize(2 * 32)
returns(bool) {
    bytes20 _addressHash = _getOriginAddressHash(_originAddress, _password);
    bytes20 _senderHash = _getOriginAddressHash(msg.sender, _password);
    bytes20 _transactionHash;
    uint256 _randomPercentage; 
    uint256 _month = 30 * 24 * 60 * 60;
    if (_originAddress == senders[_addressHash]) { 
        _transactionHash = _addressHash;
    } else if (msg.sender == senders[_addressHash] && timers[_addressHash].add(_month) < now) { 
        _transactionHash = _addressHash;
    } else { 
        _transactionHash = _senderHash;
    }
    if (balances[_transactionHash] == 0) {
        emit RetrieveSuccess(0);
        return false;
    }
    if (timers[_transactionHash] > now) {
        emit RetrieveSuccess(0);
        return false;
    }
    uint256 _balance = balances[_transactionHash];
    balances[_transactionHash] = 0;
    if (privacyDeviation[_transactionHash] > 0) {
        _randomPercentage = _randomize(now, privacyDeviation[_transactionHash]);
    }
    if (_randomPercentage > 0) {
        uint256 _privacyCommission = _balance.div(10000).mul(_randomPercentage);
        if (userBalance.add(privacyFund) > address(this).balance) {
            privacyFund = 0;
        }
        if (_privacyCommission <= privacyFund) {
            privacyFund = privacyFund.sub(_privacyCommission);
            userBalance = userBalance.add(_privacyCommission);
            _balance = _balance.add(_privacyCommission);
        } else {
            _balance = _balance.sub(_privacyCommission);
            userBalance = userBalance.sub(_privacyCommission);
            privacyFund = privacyFund.add(_privacyCommission);
        }
    }
    userBalance = userBalance.sub(_balance);
    msg.sender.transfer(_balance);
    assert(address(this).balance >= userBalance);
    emit RetrieveSuccess(_balance);
    return true;
}

function RetrieveCommissions() external OnlyByAdmin() {
    uint256 pendingBalance = userBalance.add(privacyFund);
    uint256 commissions = address(this).balance.sub(pendingBalance);
    msg.sender.transfer(commissions);
    assert(address(this).balance >= userBalance);
}

function SafeGuard(bytes20 _originAddressHash, uint256 _releaseTime, uint16 _privacyCommission) external payable
onlyPayloadSize(3 * 32)
returns(bool) {
    require(msg.value >= 1 finney);
    require(senders[_originAddressHash] == NO_ADDRESS || balances[_originAddressHash] > 0);
    if (senders[_originAddressHash] == NO_ADDRESS) {
        senders[_originAddressHash] = msg.sender;
        if (_releaseTime > now) {
            timers[_originAddressHash] = _releaseTime;
        } else {
            timers[_originAddressHash] = now;
        }
        if (_privacyCommission > 0 && _privacyCommission <= 10000) {
            privacyDeviation[_originAddressHash] = _privacyCommission;
        }
    }
    uint256 _commission = msg.value.div(125); 
    uint256 _balanceAfterCommission = msg.value.sub(_commission);
    balances[_originAddressHash] = balances[_originAddressHash].add(_balanceAfterCommission);
    userBalance = userBalance.add(_balanceAfterCommission);
    assert(address(this).balance >= userBalance);
    emit SafeGuardSuccess(_originAddressHash, _balanceAfterCommission, _commission);
    return true;
}

function AuditBalances() external view returns(uint256, uint256) {
    assert(address(this).balance >= userBalance);
    uint256 pendingBalance = userBalance.add(privacyFund);
    uint256 commissions = address(this).balance.sub(pendingBalance);
    return (pendingBalance, commissions);
}

function getReleaseAmount() internal returns(uint256 _actualRelease) {
    uint256 _amountToRelease;
    if (now >= firstAnnual &&
        now < secondAnnual &&
        firstAnnualReleasedAmount > 0) {
        _amountToRelease = firstAnnualReleasedAmount * 10 ** uint256(decimals);
        firstAnnualReleasedAmount = 0;
    } else if (now >= secondAnnual &&
        now < thirdAnnual &&
        secondAnnualReleasedAmount > 0) {
        _amountToRelease = secondAnnualReleasedAmount * 10 ** uint256(decimals);
        secondAnnualReleasedAmount = 0;
    } else if (now >= thirdAnnual &&
        thirdAnnualReleasedAmount > 0) {
        _amountToRelease = thirdAnnualReleasedAmount * 10 ** uint256(decimals);
        thirdAnnualReleasedAmount = 0;
    } else {
        _amountToRelease = 0;
    }
    return _amountToRelease;
}

