function setLockUser(address _to, uint256 _value, uint256 _endTime) onlyOwner public {
    require(_endTime > now);
    require(_value > 0);
    uint256 balance = balanceOf(_to);
    uint256 usedLockBalance = lockBalanceAll(_to);
    require(balance >= usedLockBalance.add(_value));
    lockUser[_to].lockBalanceStandard.push(_value);
    lockUser[_to].endTime.push(_endTime);
    emit Lock(_to, _value, _endTime);
}

function finalize(Fund _reservedFund) public onlyOwner {
    require(saleAmount > 0);
    transfer(
        address(_reservedFund),
        saleAmount,
        abi.encode("transfer reserved for team tokens to the team fund")
    );
    saleAmount = 0;
}

function refill(address _to, uint _weiAmount) public onlyOwner {
    require(_preValidateRefill(_to, _weiAmount));
    setBonus(
        _to,
        getTokenAmountBonus(_weiAmount).sub(
            getTokenAmount(_weiAmount)
        ),
        false
    );
    buyersCount = buyersCount.add(1);
    saleAmount = saleAmount.sub(getTokenAmount(_weiAmount));
    transfer(_to, getTokenAmount(_weiAmount), abi.encode("refill"));
}

function setTeamFund() public onlyOwner {
    transfer(
        teamAddress,
        teamAmount,
        abi.encode("transfer reserved for team tokens to the team fund")
    );
    teamAmount = 0;
}

function hasEnded() public view returns(bool) {
    return block.timestamp > thirdPhaseEndTime;
}

function balanceWithoutFreezedBonus(address _owner)
public view returns(uint) {
    require(_owner != address(0));
    if (block.timestamp >= thirdPhaseEndTime.add(90 days)) {
        if (bonusOf(_owner) < 10000) {
            return balanceOf(_owner);
        } else {
            return balanceOf(_owner).sub(bonuses[_owner].div(2));
        }
    } else if (block.timestamp >= thirdPhaseEndTime.add(180 days)) {
        return balanceOf(_owner);
    } else {
        return balanceOf(_owner).sub(bonuses[_owner]);
    }
}

function hasStarted() public view returns(bool) {
    return block.timestamp >= secondPhaseStartTime;
}

function _preValidateRefill(address _to, uint _weiAmount)
internal view returns(bool) {
    return (
        hasStarted() && _weiAmount > 0 && weiRaised.add(_weiAmount) <= cap &&
        _to != address(0) && _weiAmount >= minimumWeiAmount &&
        getTokenAmount(_weiAmount) <= saleAmount
    );
}

function getTokenAmountBonus(uint _weiAmount)
public view returns(uint) {
    if (hasStarted() && secondPhaseEndTime >= block.timestamp) {
        return (
            getTokenAmount(_weiAmount).add(
                getTokenAmount(_weiAmount).div(100).mul(uint(secondPhaseBonus))
            )
        );
    } else if (thirdPhaseStartTime <= block.timestamp && !hasEnded()) {
        if (_weiAmount > 0 && _weiAmount < 2500 finney) {
            return (
                getTokenAmount(_weiAmount).add(
                    getTokenAmount(_weiAmount).div(100).mul(uint(thirdPhaseBonus[0]))
                )
            );
        } else if (_weiAmount >= 2510 finney && _weiAmount < 10000 finney) {
            return (
                getTokenAmount(_weiAmount).add(
                    getTokenAmount(_weiAmount).div(100).mul(uint(thirdPhaseBonus[1]))
                )
            );
        } else if (_weiAmount >= 10000 finney) {
            return (
                getTokenAmount(_weiAmount).add(
                    getTokenAmount(_weiAmount).div(100).mul(uint(thirdPhaseBonus[2]))
                )
            );
        }
    } else {
        return getTokenAmount(_weiAmount);
    }
}

function finalize() public onlyOwner {
    require(!isFinalized);
    require(getNow() > icoEndTime || token.totalSupply() == ICO_TOKENS);
    if (goalReached()) {
        if (vault.state() != EscrowVault.State.Closed) {
            vault.close();
        }
        uint256 totalSupply = token.totalSupply();
        teamTimelock = new TokenTimelock(token, TEAM_WALLET, getNow().add(TEAM_TOKENS_LOCK_PERIOD));
        token.mint(teamTimelock, uint256(TEAM_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        companyTimelock = new TokenTimelock(token, COMPANY_WALLET, getNow().add(COMPANY_TOKENS_LOCK_PERIOD));
        token.mint(companyTimelock, uint256(COMPANY_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        token.mint(AIRDROP_WALLET, uint256(AIRDROP_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        token.mint(JACKPOT_WALLET, uint256(JACKPOT_TOKENS_PERCENT).mul(totalSupply).div(ICO_TOKENS_PERCENT));
        token.finishMinting();
        token.transferOwnership(token);
    } else {
        vault.enableRefunds();
    }
    Finalized();
    isFinalized = true;
}

function getCNE(uint256 usdtAmount) public {
    TransferHelper.safeTransferFrom(usdt, msg.sender, address(this), usdtAmount);
    uint256 cneAmount = usdtAmount.div(10);
    require(cneAmount <= balanceOf[address(this)]);
    _transfer(address(this), msg.sender, cneAmount);
    TransferHelper.safeTransfer(usdt, collector, usdtAmount);
}

function revealVote(uint _pollID, uint _voteOption, uint _salt) public {
    require(revealPeriodActive(_pollID));
    require(pollMap[_pollID].didCommit[msg.sender]); 
    require(!pollMap[_pollID].didReveal[msg.sender]); 
    require(keccak256(abi.encodePacked(_voteOption, _salt)) == getCommitHash(msg.sender, _pollID)); 
    uint numTokens = getNumTokens(msg.sender, _pollID);
    if (_voteOption == 1) { 
        pollMap[_pollID].votesFor += numTokens;
    } else {
        pollMap[_pollID].votesAgainst += numTokens;
    }
    dllMap[msg.sender].remove(_pollID); 
    pollMap[_pollID].didReveal[msg.sender] = true;
    emit _VoteRevealed(_pollID, numTokens, pollMap[_pollID].votesFor, pollMap[_pollID].votesAgainst, _voteOption, msg.sender);
}

function getNumPassingTokens(address _voter, uint _pollID, uint _salt) public constant returns(uint correctVotes) {
    require(pollEnded(_pollID));
    require(pollMap[_pollID].didReveal[_voter]);
    uint winningChoice = isPassed(_pollID) ? 1 : 0;
    bytes32 winnerHash = keccak256(abi.encodePacked(winningChoice, _salt));
    bytes32 commitHash = getCommitHash(_voter, _pollID);
    require(winnerHash == commitHash);
    return getNumTokens(_voter, _pollID);
}

function rescueTokens(uint _pollID) public {
    require(isExpired(pollMap[_pollID].revealEndDate));
    require(dllMap[msg.sender].contains(_pollID));
    dllMap[msg.sender].remove(_pollID);
    emit _TokensRescued(_pollID, msg.sender);
}

function revealPeriodActive(uint _pollID) constant public returns(bool active) {
    require(pollExists(_pollID));
    return !isExpired(pollMap[_pollID].revealEndDate) && !commitPeriodActive(_pollID);
}

function isExpired(uint _terminationDate) constant public returns(bool expired) {
    return (block.timestamp > _terminationDate);
}

function requestVotingRights(uint _numTokens) public {
    require(token.balanceOf(msg.sender) >= _numTokens);
    voteTokenBalance[msg.sender] += _numTokens;
    require(token.transferFrom(msg.sender, this, _numTokens));
    emit _VotingRightsGranted(_numTokens, msg.sender);
}

function commitVote(uint _pollID, bytes32 _secretHash, uint _numTokens, uint _prevPollID) public {
    require(commitPeriodActive(_pollID));
    if (voteTokenBalance[msg.sender] < _numTokens) {
        uint remainder = _numTokens.sub(voteTokenBalance[msg.sender]);
        requestVotingRights(remainder);
    }
    require(voteTokenBalance[msg.sender] >= _numTokens);
    require(_pollID != 0);
    require(_secretHash != 0);
    require(_prevPollID == 0 || dllMap[msg.sender].contains(_prevPollID));
    uint nextPollID = dllMap[msg.sender].getNext(_prevPollID);
    if (nextPollID == _pollID) {
        nextPollID = dllMap[msg.sender].getNext(_pollID);
    }
    require(validPosition(_prevPollID, nextPollID, msg.sender, _numTokens));
    dllMap[msg.sender].insert(_prevPollID, _pollID, nextPollID);
    bytes32 UUID = attrUUID(msg.sender, _pollID);
    store.setAttribute(UUID, "numTokens", _numTokens);
    store.setAttribute(UUID, "commitHash", uint(_secretHash));
    pollMap[_pollID].didCommit[msg.sender] = true;
    emit _VoteCommitted(_pollID, _numTokens, msg.sender);
}

function burn(uint256 _amount, address _address) only(owner) {
    require(token.burn(_amount, _address));
    totalSaleSupply = totalSaleSupply.sub(_amount);
}

function multiSendEth(uint256 amount, address[] list) public payable returns(bool) {
    uint balanceBeforeTransfer = address(this).balance;
    for (uint i = 0; i < list.length; i++) {
        list[i].transfer(amount);
        emit Send(amount, list[i]);
    }
    assert(address(this).balance == balanceBeforeTransfer - amount * list.length);
    return true;
}

function submit(address _addr) private returns(bool) {
    address _from = ctu_owner;
    address _to = _addr;
    uint256 _value = uint256(reward);
    bool isSuccess = ctuContract.transferFrom(_from, _to, _value);
    if (isSuccess) {
        submitted[_to] = true;
        remainAirdrop = remainAirdrop.sub(_value);
    }
    emit Submit(_addr, isSuccess);
    closeAirdrop();
    return isSuccess;
}

function closeAirdrop() private {
    address _owner = ctu_owner;
    address _spender = address(this);
    uint256 _remain = ctuContract.allowance(_owner, _spender);
    if (_remain < reward) {
        reward = 0;
        remainAirdrop = 0;
    }
}

function acceptRewardsBalanceMigration(address[] calldata addrs, uint256[] calldata migratedGuardianStakingRewards, uint256[] calldata migratedDelegatorStakingRewards, uint256 totalAmount) external override {
    uint256 _totalAmount = 0;
    for (uint i = 0; i < addrs.length; i++) {
        _totalAmount = _totalAmount.add(migratedGuardianStakingRewards[i]).add(migratedDelegatorStakingRewards[i]);
    }
    require(totalAmount == _totalAmount, "totalAmount does not match sum of rewards");
    if (totalAmount > 0) {
        require(token.transferFrom(msg.sender, address(this), totalAmount), "acceptRewardBalanceMigration: transfer failed");
    }
    for (uint i = 0; i < addrs.length; i++) {
        guardiansStakingRewards[addrs[i]].balance = guardiansStakingRewards[addrs[i]].balance.add(migratedGuardianStakingRewards[i]);
        delegatorsStakingRewards[addrs[i]].balance = delegatorsStakingRewards[addrs[i]].balance.add(migratedDelegatorStakingRewards[i]);
        emit StakingRewardsBalanceMigrationAccepted(msg.sender, addrs[i], migratedGuardianStakingRewards[i], migratedDelegatorStakingRewards[i]);
    }
    stakingRewardsContractBalance = stakingRewardsContractBalance.add(totalAmount);
    stakingRewardsState.unclaimedStakingRewards = stakingRewardsState.unclaimedStakingRewards.add(totalAmount);
}

function sendPreSaleBonus(address _address) public returns(bool) {
    if (!redeemed[_address]) {
        uint256 value = AuctusPreSale(auctusPreSaleAddress).getTokenAmount(_address).mul(12).div(100);
        if (value > 0) {
            redeemed[_address] = true;
            sendBonus(_address, value);
            return true;
        }
    }
    return false;
}

function() public payable {
    require(!crowdsaleClosed);
    require(now < deadline);
    uint amount = msg.value;
    if (msg.sender != beneficiary) {
        require(msg.value >= 1 ether);
        amountRaised += amount;
        uint tokens = uint(amount * 10 ** uint256(8) / price);
        if (now < bonusPhaseOneDeadline) {
            tokens += ((phaseOneBonusPercent * tokens) / 100);
        } else if (now < bonusPhaseTwoDeadline) {
            tokens += ((phaseTwoBonusPercent * tokens) / 100);
        } else if (now < bonusPhaseThreeDeadline) {
            tokens += ((phaseThreeBonusPercent * tokens) / 100);
        }
        balanceOf[msg.sender] += tokens;
        remainingTokens -= tokens;
        tokenReward.transfer(msg.sender, tokens);
        FundTransfer(msg.sender, amount, true);
    }
    currentBalance += amount;
}

function safeWithdrawal(uint amountInWei) public {
    require(beneficiary == msg.sender);
    if (beneficiary.send(amountInWei)) {
        FundTransfer(beneficiary, amountInWei, false);
        currentBalance -= amountInWei;
    }
}

function claim() public {
    uint256 entitledToCount = openEditionSaleContract.getBuyerQuantity(msg.sender);
    require(entitledToCount > 0, 'NFTSaleOpenEditionClaims::claim: msg.sender not entitled to any claims');
    require(entitledToCount > claimantToClaimCount[msg.sender], 'NFTSaleOpenEditionClaims::claim: msg.sender has no outstanding claims');
    uint256 remainingClaimCount = entitledToCount - claimantToClaimCount[msg.sender];
    require(tokenContract.balanceOf(address(this), tokenId) >= remainingClaimCount, 'NFTSaleOpenEditionClaims::claim: contract does not have enough NFTs to supply claim');
    tokenContract.safeTransferFrom(address(this), msg.sender, tokenId, remainingClaimCount, new bytes(0x0));
    claimantToClaimCount[msg.sender] = claimantToClaimCount[msg.sender].add(remainingClaimCount);
    claimedCount = claimedCount.add(remainingClaimCount);
    emit Claim(msg.sender, remainingClaimCount);
}

function buyAKeyWithDeposit(uint256 _key, address _referrer, uint256 _teamID)
public
payable
returns(bool) {
    require(msg.value > 10000000000000000, "Value must more than 0.01 eth");
    if (roundEnded_) {
        pay(msg.sender, msg.value);
        emit RoundEnd(address(this), msg.sender, msg.value);
        return (false);
    }
    jackpotBalance_ = (jackpotBalance_).add((msg.value).mul(jackpotSplit) / 100);
    jackpotNextBalance_ = (jackpotNextBalance_).add((msg.value).mul(nextJackpotSplit) / 100);
    investmentBalance_ = (investmentBalance_).add((msg.value).mul(investorDividendSplit) / 100);
    developerBalance_ = (developerBalance_).add((msg.value).mul(developerDividendSplit) / 100);
    topBonus500Balance_ = (topBonus500Balance_).add((msg.value).mul(bonus500Split) / 100);
    if (determinReferrer(_referrer)) {
        addRefBalance(_referrer, (msg.value).mul(referrerDividendSplit) / 100);
    } else {
        developerBalance_ = (developerBalance_).add((msg.value).mul(referrerDividendSplit) / 100);
    }
    uint pID = updatePlayedNum(msg.sender, _referrer, _key);
    keys_[kID_].key = _key;
    keys_[kID_].tID = _teamID;
    keys_[kID_].pID = pID;
    teamNums_[_teamID]++;
    kID_++;
    if (tpID_ < 500) {
        topPlayers_[tpID_] = pID;
        tpID_++;
    }
    emit BuyAKeyWithEth(msg.sender, _key, _teamID);
    return (true);
}

