function _transfer(address _from, address _to, uint _value) airnow(_from, _to) internal {
    require(_to != 0x0);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value > balanceOf[_to]);
    uint previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function claim(uint256 tokens) external {
    address holder = msg.sender;
    require(address(_milker) != address(0), "StableV2: Milker contract is not set up");
    require(!_milker.isWhitelisted(holder), "StableV2: whitelisted holders cannot claim tokens");
    _update(holder);
    bool ok = _token.transfer(holder, tokens);
    require(ok, "StableV2: unable to transfer tokens from the StableV2 contract");
    uint256 units = _maxUnits != 0 ? tokens.mul(_maxUnits.div(_token.totalSupply())) : tokens;
    _tokens[holder] = _tokens[holder].sub(units);
    _totalTokens = _totalTokens.sub(units);
    _stakeshots[holder].volume = _tokens[holder];
    emit Claimed(holder, tokens);
}

function stake(uint256 tokens) external {
    address holder = msg.sender;
    require(address(_milker) != address(0), "StableV2: Milker contract is not set up");
    require(!_milker.isWhitelisted(holder), "StableV2: whitelisted holders cannot stake tokens");
    _update(holder);
    bool ok = _token.transferFrom(holder, address(this), tokens);
    require(ok, "StableV2: unable to transfer tokens to the StableV2 contract");
    uint256 units = _maxUnits != 0 ? tokens.mul(_maxUnits.div(_token.totalSupply())) : tokens;
    _tokens[holder] = _tokens[holder].add(units);
    _totalTokens = _totalTokens.add(units);
    _stakeshots[holder].volume = _tokens[holder];
    emit Staked(holder, tokens);
}

function decayedPriceFrom(uint256 _lastPrice, uint256 _lastTimestamp) public view returns(uint128 decayedPrice) {
    if (_lastTimestamp == 0) {
        decayedPrice = INITIAL_CARD_PRICE;
    } else {
        uint128 startPrice = uint128(_lastPrice) + (uint128(_lastPrice) * PURCHASE_PREMIUM_RATE / 10000);
        require(startPrice >= uint128(_lastPrice));
        uint128 secondsLapsed;
        if (now > _lastTimestamp) { 
            secondsLapsed = uint128(now) - uint128(_lastTimestamp); 
        } else {
            secondsLapsed = 0;
        }
        uint128 hoursLapsed = secondsLapsed / 1 hours;
        uint128 totalDecay = (hoursLapsed * (startPrice * HOURLY_VALUE_DECAY_RATE / 10000));
        if (totalDecay > startPrice) {
            decayedPrice = MIN_CARD_PRICE;
        } else {
            decayedPrice = startPrice - totalDecay;
            if (decayedPrice < MIN_CARD_PRICE) {
                decayedPrice = MIN_CARD_PRICE;
            }
        }
    }
    return decayedPrice;
}

function atomicMatch(Order memory buy, Sig memory buySig, Order memory sell, Sig memory sellSig, bytes32 metadata)
internal
reentrancyGuard {
    bytes32 buyHash;
    if (buy.maker == msg.sender) {
        require(validateOrderParameters(buy));
    } else {
        buyHash = requireValidOrder(buy, buySig);
    }
    bytes32 sellHash;
    if (sell.maker == msg.sender) {
        require(validateOrderParameters(sell));
    } else {
        sellHash = requireValidOrder(sell, sellSig);
    }
    require(ordersCanMatch(buy, sell));
    uint size;
    address target = sell.target;
    assembly {
        size: = extcodesize(target)
    }
    require(size > 0);
    if (buy.replacementPattern.length > 0) {
        ArrayUtils.guardedArrayReplace(buy.calldata, sell.calldata, buy.replacementPattern);
    }
    if (sell.replacementPattern.length > 0) {
        ArrayUtils.guardedArrayReplace(sell.calldata, buy.calldata, sell.replacementPattern);
    }
    require(ArrayUtils.arrayEq(buy.calldata, sell.calldata));
    AuthenticatedProxy proxy = registry.proxies(sell.maker);
    require(proxy != address(0));
    if (msg.sender != buy.maker) {
        cancelledOrFinalized[buyHash] = true;
    }
    if (msg.sender != sell.maker) {
        cancelledOrFinalized[sellHash] = true;
    }
    uint price = executeFundsTransfer(buy, sell);
    require(proxy.proxy(sell.target, sell.howToCall, sell.calldata));
    if (buy.staticTarget != address(0)) {
        require(staticCall(buy.staticTarget, sell.calldata, buy.staticExtradata));
    }
    if (sell.staticTarget != address(0)) {
        require(staticCall(sell.staticTarget, sell.calldata, sell.staticExtradata));
    }
    OrdersMatched(buyHash, sellHash, sell.feeRecipient != address(0) ? sell.maker : buy.maker, sell.feeRecipient != address(0) ? buy.maker : sell.maker, price, metadata);
}

