function start() public onlyOwner {
    require(!started);
    require(totalTokens > 0);
    require(totalTokens == token.balanceOf(this));
    started = true;
    startTimestamp = now;
}

function addEntry(address beneficiary, uint tokens, bool advance, uint periods, uint periodLength) internal {
    require(!started);
    require(beneficiary != address(0));
    require(tokens > 0);
    require(periods > 0);
    require(entries[beneficiary].tokens == 0);
    entries[beneficiary] = Entry({
        tokens: tokens,
        advance: advance,
        periods: periods,
        periodLength: periodLength,
        withdrawn: 0
    });
    totalTokens = totalTokens.add(tokens);
    NewEntry(beneficiary, tokens, advance, periods, periodLength);
}

function withdrawable(address beneficiary) public view returns(uint) {
    uint result = 0;
    Entry memory entry = entries[beneficiary];
    if (entry.tokens > 0) {
        uint _vested = vested(beneficiary, now);
        result = _vested.sub(entry.withdrawn);
    }
    return result;
}

function vested(address beneficiary, uint time) public view returns(uint) {
    uint result = 0;
    if (startTimestamp > 0 && time >= startTimestamp) {
        Entry memory entry = entries[beneficiary];
        if (entry.tokens > 0) {
            uint periods = time.sub(startTimestamp).div(entry.periodLength);
            if (entry.advance) {
                periods++;
            }
            if (periods >= entry.periods) {
                result = entry.tokens;
            } else {
                result = entry.tokens.mul(periods).div(entry.periods);
            }
        }
    }
    return result;
}

function withdrawInternal(address beneficiary) internal {
    Entry storage entry = entries[beneficiary];
    require(entry.tokens > 0);
    uint _vested = vested(beneficiary, now);
    uint _withdrawn = entry.withdrawn;
    require(_vested > _withdrawn);
    uint _withdrawable = _vested.sub(_withdrawn);
    entry.withdrawn = _vested;
    require(token.transfer(beneficiary, _withdrawable));
    Withdrawn(beneficiary, _withdrawable);
}

function regSpots(uint16 cntryId, uint16 numOfSpots, bytes32 stxt) external payable {
    require(numOfSpots > 0 && numOfSpots <= 600);
    uint i;
    uint j;
    uint j1;
    uint flagCompleted;
    if (cntry_flgs[cntryId].length > 0) {
        require(msg.value == cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotRate * numOfSpots);
        i = cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotOwner.length;
        if (600 - i >= numOfSpots) {
            j = numOfSpots;
            while (j > 0) {
                regSpot(cntryId, stxt);
                j--;
                i++;
            }
        } else {
            j1 = 600 - i;
            j = numOfSpots - j1;
            while (j1 > 0) {
                regSpot(cntryId, stxt);
                j1--;
                i++;
            }
            uint currRateHolder = cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotRate;
            completedFlag(cntryId);
            flagCompleted = 1;
            createFlag(cntryId, currRateHolder);
            i = 0;
            while (j > 0) {
                regSpot(cntryId, stxt);
                j--;
                i++;
            }
        }
    } else {
        require(msg.value == curr_rate * numOfSpots);
        createFlag(cntryId, curr_rate);
        i = 0;
        j = numOfSpots;
        while (j > 0) {
            regSpot(cntryId, stxt);
            j--;
            i++;
        }
    }
    if (i == 600) {
        completedFlag(cntryId);
        flagCompleted = 1;
        createFlag(cntryId, curr_rate);
    }
    UpdateFlagList(cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotOwner, cntry_flgs[cntryId][cntry_flgs[cntryId].length - 1].spotTxt, flagCompleted);
}

