}

function transfer(address _toAddress, uint256 _amountOfTokens) onlyBagholders public returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) {
        withdraw(true);
    }
    uint256 _tokenFee = SafeMath.div(SafeMath.mul(_amountOfTokens, transferFee_), 100);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    emit Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function withdraw(bool _isTransfer) onlyStronghands public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    uint256 _estimateTokens = calculateTokensReceived(_dividends);
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    emit onWithdraw(_customerAddress, _dividends, _estimateTokens, _isTransfer);
}

function stake(
    address _to,
    uint256 _amount,
    bool _rebasing,
    bool _claim
) external returns(uint256) {
    OHM.safeTransferFrom(msg.sender, address(this), _amount);
    _amount = _amount.add(rebase()); 
    if (_claim && warmupPeriod == 0) {
        return _send(_to, _amount, _rebasing);
    } else {
        Claim memory info = warmupInfo[_to];
        if (!info.lock) {
            require(_to == msg.sender, "External deposits for account are locked");
        }
        warmupInfo[_to] = Claim({
            deposit: info.deposit.add(_amount),
            gons: info.gons.add(sOHM.gonsForBalance(_amount)),
            expiry: epoch.number.add(warmupPeriod),
            lock: info.lock
        });
        gonsInWarmup = gonsInWarmup.add(sOHM.gonsForBalance(_amount));
        return _amount;
    }
}

function rebase() public returns(uint256) {
    uint256 bounty;
    if (epoch.end <= block.timestamp) {
        sOHM.rebase(epoch.distribute, epoch.number);
        epoch.end = epoch.end.add(epoch.length);
        epoch.number++;
        if (address(distributor) != address(0)) {
            distributor.distribute();
            bounty = distributor.retrieveBounty(); 
        }
        uint256 balance = OHM.balanceOf(address(this));
        uint256 staked = sOHM.circulatingSupply();
        if (balance <= staked.add(bounty)) {
            epoch.distribute = 0;
        } else {
            epoch.distribute = balance.sub(staked).sub(bounty);
        }
    }
    return bounty;
}

function burnTokens(uint256 _tokens) external {
    require(!locked);
    require(contractManager.authorize(contractName, msg.sender));
    require(depositAddress != address(0));
    require(_tokens != 0);
    require(_tokens <= balances[depositAddress]);
    balances[depositAddress] = balances[depositAddress].sub(_tokens);
    totalSupply_ = totalSupply_.sub(_tokens);
    emit TokensBurned(msg.sender, depositAddress, _tokens);
}

function sendBoughtTokens(address _beneficiary, uint256 _tokens) external {
    require(locked);
    require(contractManager.authorize(contractName, msg.sender));
    require(_beneficiary != address(0));
    require(_tokens != 0);
    totalSupply_ = totalSupply_.add(_tokens);
    balances[depositAddress] = balances[depositAddress].add(_tokens);
    emit TokensMinted(msg.sender, depositAddress, _tokens);
    _transfer(depositAddress, _beneficiary, _tokens);
}

function unlockTokens() public {
    require(contractManager.authorize(contractName, msg.sender));
    BasicToken.unlockTokens();
}

function changeDepositAddress(address _depositAddress) external {
    require(contractManager.authorize(contractName, msg.sender));
    require(_depositAddress != address(0));
    require(_depositAddress != depositAddress);
    address oldDepositAddress = depositAddress;
    depositAddress = _depositAddress;
    emit DepositAddressChanged(oldDepositAddress, _depositAddress);
}

function mintTokens(uint256 _tokens) external {
    require(!locked);
    require(contractManager.authorize(contractName, msg.sender));
    require(_tokens != 0);
    totalSupply_ = totalSupply_.add(_tokens);
    balances[depositAddress] = balances[depositAddress].add(_tokens);
    emit TokensMinted(msg.sender, depositAddress, _tokens);
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether;
    uint256 bonusCond3 = 5 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 1 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 2 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 3 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 2 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 3 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 100000e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
    multisig.transfer(msg.value);
}

function ExchangeETHforToken(address _addr, uint256 _amount) private {
    uint256 amount = _amount;
    address userAdd = _addr;
    ethAmount = ((amount.mul(10 ** uint256(tokenDecimal)).div(tokenPriceEth)).mul(10 ** uint256(tokenDecimal))).div(10 ** uint256(tokenDecimal));
    require(Token(tokenAddr).balanceOf(address(this)) >= ethAmount, "There is low token balance in contract");
    require(Token(tokenAddr).transfer(userAdd, ethAmount));
    emit TokenTransfer(userAdd, ethAmount);
    tokenExchanged[msg.sender] = tokenExchanged[msg.sender].add(ethAmount);
    _owner.transfer(amount);
}

function ExchangeETHforTokenMannual() public payable {
    uint256 amount = msg.value;
    address userAdd = msg.sender;
    ethAmount = ((amount.mul(10 ** uint256(tokenDecimal)).div(tokenPriceEth)).mul(10 ** uint256(tokenDecimal))).div(10 ** uint256(tokenDecimal));
    require(Token(tokenAddr).balanceOf(address(this)) >= ethAmount, "There is low token balance in contract");
    require(Token(tokenAddr).transfer(userAdd, ethAmount));
    balances[msg.sender] = balances[msg.sender].add(msg.value);
    emit TokenTransfer(userAdd, ethAmount);
    tokenExchanged[msg.sender] = tokenExchanged[msg.sender].add(ethAmount);
    _owner.transfer(amount);
}

function finalize() public onlyDonationAddress returns(bool) {
    require(getSencBalance() >= sencHardCap || now >= endDate, "SENC hard cap rached OR End date reached");
    require(!finalized, "Donation not already finalized");
    totalSencCollected = getSencBalance();
    if (totalSencCollected >= sencHardCap) {
        donationWallet.transfer(address(this).balance);
    } else {
        uint256 totalDonatedEthers = convertToEther(totalSencCollected) + INFOCORP_DONATION;
        donationWallet.transfer(totalDonatedEthers);
        claimTokens(address(0), foundationWallet);
    }
    claimTokens(SENC_CONTRACT_ADDRESS, foundationWallet);
    finalized = true;
    return finalized;
}

