    if (block.timestamp <= (openingTime.add(14 days))) {
        return rate.add(200);
    }
    if (block.timestamp <= (openingTime.add(28 days))) {
        return rate.add(100);
    }
    if (block.timestamp <= (openingTime.add(49 days))) {
