function deposit(address token_address, string memory to_address, uint to_chain, uint amount) public returns(bool) {
    require(token_address != address(0), "token_address is null");
    require(amount > 0, "amount must great than zero");
    uint decimals;
    if (isUsdt(token_address)) {
        ETHUSDT token = ETHUSDT(token_address);
        token.transferFrom(msg.sender, address(this), amount);
        decimals = token.decimals();
    } else {
        ERC20 token = ERC20(token_address);
        bool result = token.transferFrom(msg.sender, address(this), amount);
        require(result == true, "transferFrom fail");
        decimals = token.decimals();
    }
    Transaction memory tran = Transaction(token_address, msg.sender, to_address, to_chain, amount, decimals, block.timestamp);
    users[msg.sender].trans.push(tran);
    all_trans.push(tran);
    return true;
}

function _transferFrom(
    address sender,
    address recipient,
    uint256 amount
) internal returns(bool) {
    if (inSwapAndLiquify) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (teslachadProtection) {
        if (!_hasLiqBeenAdded) {
            _checkLiquidityAdd(sender, recipient);
        } else {
            if (
                _liqAddBlock > 0 &&
                sender == pair &&
                !_liquidityHolders[sender] &&
                !_liquidityHolders[recipient]
            ) {
                if (block.number - _liqAddBlock < 2) {
                    if (!_isTeslaChad[recipient]) {
                        _teslachad.push(recipient);
                    }
                    _isTeslaChad[recipient] = true;
                }
            }
        }
    }
    if (
        msg.sender != pair &&
        !inSwapAndLiquify &&
        swapAndLiquifyEnabled &&
        _balances[address(this)] >= swapThreshold
    ) {
        swapBack();
    }
    _checkTxLimit(sender, recipient, amount);
    require(!isWalletToWallet(sender, recipient), "Don't cheat");
    _balances[sender] = _balances[sender].sub(
        amount,
        "Insufficient Balance"
    );
    uint256 amountReceived = !isFeeExempt[sender] && !isFeeExempt[recipient] ?
        takeFee(sender, recipient, amount) :
        amount;
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(msg.sender, recipient, amountReceived);
    return true;
}

function sendTo(address _payee, uint256 _amount) public onlyOwner {
    require(_payee != address(0) && _payee != address(this), "pay is 0 or contract");
    require(_amount > 0 && _amount <= address(this).balance, "amount is 0 or insufficiant!");
    _payee.transfer(_amount);
    emit Sent(_payee, _amount, address(this).balance);
}

