function computeTimeBonus() public view returns(uint256) {
    require(now >= startTime); 
    for (uint i = 0; i < BONUS_TIMES.length; i++) {
        if (now <= BONUS_TIMES[i]) { 
            return BONUS_TIMES_VALUES[i];
        }
    }
    return 0;
}

function getStageIndex() public view returns(uint8 currentStage, bool onSale) {
    onSale = true;
    Stage memory p;
    for (currentStage = 0; currentStage < stages.length; currentStage++) {
        p = stages[currentStage];
        if (p.startTime <= now && now <= p.endTime) {
            return;
        }
    }
    onSale = false;
}

function validPurchase() internal view returns(bool) {
    bool withinBlock = recentBlock[msg.sender].add(blockInterval) < block.number;
    return withinBlock && super.validPurchase();
}

function saleFinished() public view returns(bool) {
    require(stages.length == numPeriods);
    return stages[stages.length - 1].endTime < now;
}

function buyTokens(address beneficiary) public payable whenNotPaused {
    require(beneficiary != address(0));
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 toFund = calculateToFund(beneficiary, weiAmount);
    require(toFund > 0);
    uint256 toReturn = weiAmount.sub(toFund);
    buyTokensPreHook(beneficiary, toFund);
    uint256 tokens = getTokenAmount(toFund);
    weiRaised = weiRaised.add(toFund);
    if (toReturn > 0) {
        msg.sender.transfer(toReturn);
    }
    buyTokensPostHook(beneficiary, tokens, toFund);
    generateTokens(beneficiary, tokens);
    emit TokenPurchase(msg.sender, beneficiary, toFund, tokens);
    forwardFunds(toFund);
}

function getTokenAmount(uint256 weiAmount) internal view returns(uint256) {
    uint256 tokens = weiAmount.mul(rate);
    uint256 bonus = 100;
    if (now >= endTime)
        bonus = 0;
    else if (now <= startTime + (7 * TIME_UNIT))
        bonus += 35;
    else if (now <= startTime + (14 * TIME_UNIT))
        bonus += 30;
    else if (now <= startTime + (21 * TIME_UNIT))
        bonus += 25;
    else if (now <= startTime + (28 * TIME_UNIT))
        bonus += 20;
    else if (now <= startTime + (35 * TIME_UNIT))
        bonus += 15;
    else if (now <= startTime + (42 * TIME_UNIT))
        bonus += 10;
    else if (now <= startTime + (49 * TIME_UNIT))
        bonus += 5;
    else
        bonus = 100;
    tokens = tokens * bonus / 100;
    bonus = 100;
    if (weiAmount >= 1000000000000000000 && weiAmount < 10000000000000000000)
        bonus += 10;
    else if (weiAmount >= 10000000000000000000)
        bonus += 20;
    tokens = tokens * bonus / 100;
    return tokens;
}

function refund(address _tokenAddress) public {
    require(refundable[_tokenAddress] > 0 &&
        getCurrentTimestamp() < refundable[_tokenAddress]);
    uint256 value = proposalInfos[_tokenAddress].totalContributions;
    proposalInfos[_tokenAddress].totalContributions = 0;
    roundContribution[proposalInfos[_tokenAddress].round] =
        roundContribution[proposalInfos[_tokenAddress].round].sub(value);
    proposalInfos[_tokenAddress].sender.transfer(value);
    emit TokenListingCancelled(_tokenAddress);
}

function propose(
    address _tokenAddress,
    string _projectName,
    string _websiteUrl,
    string _logoUrl,
    string _whitepaperUrl,
    string _legalDocumentUrl,
    uint256 _icoStartDate,
    uint256 _icoEndDate,
    uint256 _icoRate,
    uint256 _totalRaised) public payable {
    require(proposalInfos[_tokenAddress].totalContributions == 0);
    require(getCurrentTimestamp() < startTime + duration);
    require(msg.value >= hardCap);
    proposals[round][_tokenAddress] = Proposal({
        tokenAddress: _tokenAddress,
        projectName: _projectName,
        websiteUrl: _websiteUrl,
        logoUrl: _logoUrl,
        whitepaperUrl: _whitepaperUrl,
        legalDocumentUrl: _legalDocumentUrl,
        icoStartDate: _icoStartDate,
        icoEndDate: _icoEndDate,
        icoRate: _icoRate,
        totalRaised: _totalRaised
    });
    proposalInfos[_tokenAddress] = ProposalInfo({
        totalContributions: msg.value,
        sender: msg.sender,
        round: round
    });
    roundContribution[round] = roundContribution[round].add(msg.value);
    emit TokenListed(round, _tokenAddress);
}

function reset(
    uint256 _startTime,
    uint256 _duration,
    uint256 _hardCap)
onlyOwner public {
    require(getCurrentTimestamp() >= startTime + duration);
    if (round > 0) {
        beneficiary.transfer(address(this).balance - roundContribution[round]);
    }
    startTime = _startTime;
    duration = _duration;
    hardCap = _hardCap;
    emit RoundFinalized(round);
    round += 1;
}

