function wantItMoreThanYou(uint tokenId) external payable {
    require(block.number >= user[msg.sender].bidBlock + auctionTime);
    address previousOwner = auction[tokenId].owner;
    require(block.number < user[previousOwner].bidBlock + auctionTime);
    uint128 previousPrice = auction[tokenId].currentPrice;
    uint128 price;
    if (previousPrice == 0) {
        price = 2 finney;
    } else if (previousPrice < 500 finney) {
        price = 2 * previousPrice;
    } else {
        price = (previousPrice + 500 finney) / 500 finney * 500 finney;
    }
    require(msg.value >= price);
    uint128 priceDiff = price - previousPrice;
    user[previousOwner] = User({
        balance: previousPrice + priceDiff / 4,
        bidBlock: 0
    });
    whaleBalance += priceDiff / 2;
    ownerBalance += priceDiff / 4;
    auction[tokenId] = Auction({
        owner: msg.sender,
        currentPrice: price
    });
    user[msg.sender].bidBlock = uint32(block.number);
    if (msg.value > price) {
        msg.sender.transfer(msg.value - price);
    }
    emit Bid(tokenId);
}

function currentReward(uint64 _depositId)
view
public
returns(uint256 amount) {
    Deposit memory deposit = deposits[_depositId];
    if (deposit.timeFrom > now)
        return 0;
    uint16 dayDecimalPercent = rewardDecimalPercentByTime(deposit.timeFrom);
    uint256 amountByDay = (deposit.amount * dayDecimalPercent / 10 ** percentDecimals);
    uint256 minutesPassed = (now - deposit.timeFrom) / 60;
    amount = amountByDay * minutesPassed / 1440;
}

function rewardDecimalPercentByTime(uint256 _timeFrom)
view
public
returns(uint16 decimalPercent) {
    if (_timeFrom >= now)
        return uint16(startDecimalPercent);
    decimalPercent = uint16(startDecimalPercent + (((now - _timeFrom) / periodLength) * bonusDecimalPercentByPeriod));
    if (decimalPercent > maximalDecimalPercent)
        return uint16(maximalDecimalPercent);
}

function withdrawPercents(uint64 _depositId) external {
    Deposit memory deposit = deposits[_depositId];
    require(deposit.owner == msg.sender);
    uint256 reward = currentReward(_depositId);
    deposit.timeFrom = uint64(now);
    deposits[_depositId] = deposit;
    deposit.owner.transfer(reward);
}

function receiveApproval(address _from, uint256 _value, address _token, bytes _extraData) public {
    require(erc20tk.transferFrom(_from, this, _value)); 
    approveRecords.push(_extraData);
    emit ReceiveApproval(_from, _value, _token, _extraData);
}

function submitAnswerReveal(bytes32 question_id, bytes32 answer, uint256 nonce, uint256 bond)
stateOpen(question_id)
external {
    bytes32 answer_hash = keccak256(answer, nonce);
    bytes32 commitment_id = keccak256(question_id, answer_hash, bond);
    require(!commitments[commitment_id].is_revealed);
    require(commitments[commitment_id].reveal_ts > uint32(now)); 
    commitments[commitment_id].revealed_answer = answer;
    commitments[commitment_id].is_revealed = true;
    if (bond == questions[question_id].bond) {
        _updateCurrentAnswer(question_id, answer, questions[question_id].timeout);
    }
    LogAnswerReveal(question_id, msg.sender, answer_hash, answer, nonce, bond);
}

function epoch(
    uint256 _rewards,
    uint256 _withdrawAmountETH,
    uint256 _withdrawShares,
    uint256 _depositAmountETH,
    uint256 _depositAmountAETH
) public onlyOwnerOrOperator {
    lastBalance = vault.totalSupply(2);
    if (_rewards > minRewards) {
        controller.buyForStrategy(
            _rewards,
            vault.getRewardToken(),
            address(vault)
        );
    }
    ethPushedToYearn = ethPushedToYearn.sub(
        _withdrawAmountETH
    ).add(_depositAmountAETH);
    if (_withdrawShares > 0) {
        withdrawFromYearn(_withdrawShares);
    }
    if (_depositAmountAETH >= minDepositable) {
        controller.depositTokenForStrategy(
            _depositAmountAETH,
            address(yearnVault));
    }
    lastEpochTime = block.timestamp;
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (sender != owner && recipient != owner) {
        require(tradingOn, "Trading is not turned on yet");
    }
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    checkTxLimit(sender, recipient, amount);
    if (shouldSwapBack()) {
        swapBack();
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    uint256 amountReceived = shouldTakeFee(sender) ? takeFee(sender, amount) : amount;
    _balances[recipient] = _balances[recipient].add(amountReceived);
    if (!isDividendExempt[sender]) {
        try distributor.setShare(sender, _balances[sender]) {} catch {}
    }
    if (!isDividendExempt[recipient]) {
        try distributor.setShare(recipient, _balances[recipient]) {} catch {}
    }
    try distributor.process(distributorGas) {} catch {}
    if (_isBuy(sender) && _buyMap[recipient] == 0) {
        _buyMap[recipient] = block.timestamp;
    }
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function distributeDividend(address shareholder) public payable {
    if (shares[shareholder].amount == 0) {
        return;
    }
    uint256 amount = getUnpaidEarnings(shareholder);
    if (amount > 0) {
        totalDistributed = totalDistributed.add(amount);
        payable(shareholder).transfer(amount);
        shareholderClaims[shareholder] = block.timestamp;
        shares[shareholder].totalRealised = shares[shareholder].totalRealised.add(amount);
        shares[shareholder].totalExcluded = getCumulativeDividends(shares[shareholder].amount);
    }
}

function swapBack() internal swapping {
    uint256 amountToSwap = _balances[address(this)];
    uint256 amountReflection = amountToSwap.mul(reflectionFee).div(totalFee);
    uint256 amountMarketing = amountToSwap.mul(marketingFee).div(totalFee);
    uint256 amountDev = amountToSwap.mul(devFee).div(totalFee);
    uint256 amountLiquidity = amountToSwap.mul(liquidityFee).div(totalFee);
    swapAndSendToMarketing(amountMarketing);
    swapAndSendToRef(amountReflection);
    swapAndLiquify(amountLiquidity);
    swapAndSendToDev(amountDev);
}

function TimeLeftToDistribute(address shareholder) public view returns(uint256) {
    uint256 timeleft;
    if (shareholderClaims[shareholder] + minPeriod > block.timestamp) {
        timeleft = shareholderClaims[shareholder] + minPeriod - block.timestamp;
    } else {
        timeleft = 0;
    }
    return timeleft;
}

function takeFee(address sender, uint256 amount) internal returns(uint256) {
    uint256 feeAmount;
    if (originalPurchase(sender) != 0 &&
        ((originalPurchase(sender) + (10 minutes)) >= block.timestamp)) {
        feeAmount = amount.mul(AD_24HR_totalFee).div(10000);
        _balances[address(this)] = _balances[address(this)].add(feeAmount);
        emit Transfer(sender, address(this), feeAmount);
    } else {
        feeAmount = amount.mul(totalFee).div(10000);
        _balances[address(this)] = _balances[address(this)].add(feeAmount);
        emit Transfer(sender, address(this), feeAmount);
    }
    return amount.sub(feeAmount);
}

function verifyStage() internal {
    if (stage == Stage.second && Remain == 0) {
        stage = Stage.secondreturn;
    }
    if (stage == Stage.firstreturn && confirm2stage) {
        stage = Stage.second;
    }
    if (uint32(block.timestamp) > endtime && Remain > 10000000 * 10 ** 9 && stage == Stage.first) {
        stage = Stage.fail;
    }
    if (uint32(block.timestamp) >= endtime && stage == Stage.first) {
        stage = Stage.firstreturn;
    }
}

function ownerconfirm() public onlyowner {
    require(uint32(block.timestamp) > endtime);
    require(!confirm2stage);
    Remain = Remain.add(40000000 * 10 ** 9);
    totaltoken = 90000000 * 10 ** 9;
    confirm2stage = true;
    verifyStage();
}

function buyAtoken() public payable {
    require(!isContract(msg.sender));
    require(Remain > 0);
    uint256 rate = price();
    require(rate > 0);
    uint256 requested;
    uint256 toreturn;
    requested = msg.value.mul(rate);
    if (requested > Remain) {
        requested = Remain;
        toreturn = msg.value.sub(Remain.div(rate));
    }
    Remain = Remain.sub(requested);
    balances[msg.sender] = balances[msg.sender].add(requested);
    if (toreturn > 0) {
        msg.sender.transfer(toreturn);
    }
    verifyStage();
}

function withdrawal(uint index, address to, uint256 amount) public returns(bool) {
    Loan storage loan = loans[index];
    require(msg.sender == loan.lender);
    loan.lenderBalance = safeSubtract(loan.lenderBalance, amount);
    require(rcn.transfer(to, amount));
    unlockTokens(rcn, amount);
    return true;
}

function withdrawalRange(uint256 fromIndex, uint256 toIndex, address to) public returns(uint256) {
    uint256 loanId;
    uint256 totalWithdraw = 0;
    for (loanId = fromIndex; loanId <= toIndex; loanId++) {
        Loan storage loan = loans[loanId];
        if (loan.lender == msg.sender) {
            totalWithdraw += loan.lenderBalance;
            loan.lenderBalance = 0;
        }
    }
    require(rcn.transfer(to, totalWithdraw));
    unlockTokens(rcn, totalWithdraw);
    return totalWithdraw;
}

function withdrawalList(uint256[] memory loanIds, address to) public returns(uint256) {
    uint256 inputId;
    uint256 totalWithdraw = 0;
    for (inputId = 0; inputId < loanIds.length; inputId++) {
        Loan storage loan = loans[loanIds[inputId]];
        if (loan.lender == msg.sender) {
            totalWithdraw += loan.lenderBalance;
            loan.lenderBalance = 0;
        }
    }
    require(rcn.transfer(to, totalWithdraw));
    unlockTokens(rcn, totalWithdraw);
    return totalWithdraw;
}

function pay(uint index, uint256 _amount, address _from, bytes oracleData) public returns(bool) {
    Loan storage loan = loans[index];
    require(loan.status == Status.lent);
    addInterest(index);
    uint256 toPay = min(getPendingAmount(index), _amount);
    PartialPayment(index, msg.sender, _from, toPay);
    loan.paid = safeAdd(loan.paid, toPay);
    if (getRawPendingAmount(index) == 0) {
        TotalPayment(index);
        loan.status = Status.paid;
        lendersBalance[loan.lender] -= 1;
        activeLoans -= 1;
        Transfer(loan.lender, 0x0, index);
    }
    uint256 rate = getRate(loan, oracleData);
    uint256 transferValue = safeMult(toPay, rate);
    lockTokens(rcn, transferValue);
    require(rcn.transferFrom(msg.sender, this, transferValue));
    loan.lenderBalance = safeAdd(transferValue, loan.lenderBalance);
    return true;
}

function lend(uint index, bytes oracleData, Cosigner cosigner, bytes cosignerData) public returns(bool) {
    Loan storage loan = loans[index];
    require(loan.status == Status.initial);
    require(isApproved(index));
    require(block.timestamp <= loan.expirationRequest);
    loan.lender = msg.sender;
    loan.dueTime = safeAdd(block.timestamp, loan.duesIn);
    loan.interestTimestamp = block.timestamp;
    loan.status = Status.lent;
    if (loan.cancelableAt > 0)
        internalAddInterest(loan, safeAdd(block.timestamp, loan.cancelableAt));
    uint256 rate = getRate(loan, oracleData);
    if (cosigner != address(0)) {
        loan.cosigner = address(uint256(cosigner) + 2);
        require(cosigner.requestCosign(this, index, cosignerData, oracleData));
        require(loan.cosigner == address(cosigner));
    }
    require(rcn.transferFrom(msg.sender, loan.borrower, safeMult(loan.amount, rate)));
    Transfer(0x0, loan.lender, index);
    activeLoans += 1;
    lendersBalance[loan.lender] += 1;
    Lent(index, loan.lender, cosigner);
    return true;
}

function approveLoan(uint index) public returns(bool) {
    Loan storage loan = loans[index];
    require(loan.status == Status.initial);
    loan.approbations[msg.sender] = true;
    ApprovedBy(index, msg.sender);
    return true;
}

function transferFrom(address from, address to, uint256 index) public returns(bool) {
    require(loans[index].lender == from);
    return transfer(to, index);
}

function getRate(Loan loan, bytes data) internal returns(uint256) {
    if (loan.oracle == address(0)) {
        return 1;
    } else {
        return loan.oracle.getRate(loan.currency, data);
    }
}

function internalAddInterest(Loan storage loan, uint256 timestamp) internal {
    if (timestamp > loan.interestTimestamp) {
        uint256 newInterest = loan.interest;
        uint256 newPunitoryInterest = loan.punitoryInterest;
        uint256 newTimestamp;
        uint256 realDelta;
        uint256 calculatedInterest;
        uint256 deltaTime;
        uint256 pending;
        uint256 endNonPunitory = min(timestamp, loan.dueTime);
        if (endNonPunitory > loan.interestTimestamp) {
            deltaTime = endNonPunitory - loan.interestTimestamp;
            if (loan.paid < loan.amount) {
                pending = loan.amount - loan.paid;
            } else {
                pending = 0;
            }
            (realDelta, calculatedInterest) = calculateInterest(deltaTime, loan.interestRate, pending);
            newInterest = safeAdd(calculatedInterest, newInterest);
            newTimestamp = loan.interestTimestamp + realDelta;
        }
        if (timestamp > loan.dueTime) {
            uint256 startPunitory = max(loan.dueTime, loan.interestTimestamp);
            deltaTime = timestamp - startPunitory;
            uint256 debt = safeAdd(loan.amount, newInterest);
            pending = min(debt, safeSubtract(safeAdd(debt, newPunitoryInterest), loan.paid));
            (realDelta, calculatedInterest) = calculateInterest(deltaTime, loan.interestRatePunitory, pending);
            newPunitoryInterest = safeAdd(newPunitoryInterest, calculatedInterest);
            newTimestamp = startPunitory + realDelta;
        }
        if (newInterest != loan.interest || newPunitoryInterest != loan.punitoryInterest) {
            loan.interestTimestamp = newTimestamp;
            loan.interest = newInterest;
            loan.punitoryInterest = newPunitoryInterest;
        }
    }
}

function transfer(address to, uint256 index) public returns(bool) {
    Loan storage loan = loans[index];
    require(loan.status != Status.destroyed && loan.status != Status.paid);
    require(msg.sender == loan.lender || msg.sender == loan.approvedTransfer);
    require(to != address(0));
    loan.lender = to;
    loan.approvedTransfer = address(0);
    lendersBalance[msg.sender] -= 1;
    lendersBalance[to] += 1;
    Transfer(loan.lender, to, index);
    return true;
}

function createLoan(Oracle _oracleContract, address _borrower, bytes32 _currency, uint256 _amount, uint256 _interestRate,
    uint256 _interestRatePunitory, uint256 _duesIn, uint256 _cancelableAt, uint256 _expirationRequest, string _metadata) public returns(uint256) {
    require(!deprecated);
    require(_cancelableAt <= _duesIn);
    require(_oracleContract != address(0) || _currency == 0x0);
    require(_borrower != address(0));
    require(_amount != 0);
    require(_interestRatePunitory != 0);
    require(_interestRate != 0);
    require(_expirationRequest > block.timestamp);
    var loan = Loan(Status.initial, _oracleContract, _borrower, 0x0, msg.sender, 0x0, _amount, 0, 0, 0, 0, _interestRate,
        _interestRatePunitory, 0, _duesIn, _currency, _cancelableAt, 0, 0x0, _expirationRequest, _metadata);
    uint index = loans.push(loan) - 1;
    CreatedLoan(index, _borrower, msg.sender);
    if (msg.sender == _borrower) {
        approveLoan(index);
    }
    return index;
}

function cosign(uint index, uint256 cost) external returns(bool) {
    Loan storage loan = loans[index];
    require(loan.status == Status.lent && (loan.dueTime - loan.duesIn) == block.timestamp);
    require(loan.cosigner != address(0));
    require(loan.cosigner == address(uint256(msg.sender) + 2));
    loan.cosigner = msg.sender;
    require(rcn.transferFrom(loan.lender, msg.sender, cost));
    return true;
}

function calculateInterest(uint256 timeDelta, uint256 interestRate, uint256 amount) internal pure returns(uint256 realDelta, uint256 interest) {
    if (amount == 0) {
        interest = 0;
        realDelta = timeDelta;
    } else {
        interest = safeMult(safeMult(100000, amount), timeDelta) / interestRate;
        realDelta = safeMult(interest, interestRate) / (amount * 100000);
    }
}

function approve(address to, uint256 index) public returns(bool) {
    Loan storage loan = loans[index];
    require(msg.sender == loan.lender);
    loan.approvedTransfer = to;
    Approval(msg.sender, to, index);
    return true;
}

function addInterest(uint index) public returns(bool) {
    Loan storage loan = loans[index];
    require(loan.status == Status.lent);
    internalAddInterest(loan, block.timestamp);
}

function destroy(uint index) public returns(bool) {
    Loan storage loan = loans[index];
    require(loan.status != Status.destroyed);
    require(msg.sender == loan.lender || (msg.sender == loan.borrower && loan.status == Status.initial));
    DestroyedBy(index, msg.sender);
    if (loan.status != Status.initial) {
        lendersBalance[loan.lender] -= 1;
        activeLoans -= 1;
        Transfer(loan.lender, 0x0, index);
    }
    loan.status = Status.destroyed;
    return true;
}

function transfer(address to, uint256 index) public returns(bool) {
    Loan storage loan = loans[index];
    require(msg.sender == loan.lender || msg.sender == loan.approvedTransfer || operators[loan.lender][msg.sender]);
    require(to != address(0));
    loan.lender = to;
    loan.approvedTransfer = address(0);
    lendersBalance[msg.sender] -= 1;
    lendersBalance[to] += 1;
    Transfer(loan.lender, to, index);
    return true;
}

function lend(uint index, bytes oracleData, Cosigner cosigner, bytes cosignerData) public returns(bool) {
    Loan storage loan = loans[index];
    require(loan.status == Status.initial);
    require(isApproved(index));
    require(block.timestamp <= loan.expirationRequest);
    loan.lender = msg.sender;
    loan.dueTime = safeAdd(block.timestamp, loan.duesIn);
    loan.interestTimestamp = block.timestamp;
    loan.status = Status.lent;
    Transfer(0x0, loan.lender, index);
    activeLoans += 1;
    lendersBalance[loan.lender] += 1;
    if (loan.cancelableAt > 0)
        internalAddInterest(loan, safeAdd(block.timestamp, loan.cancelableAt));
    uint256 transferValue = convertRate(loan.oracle, loan.currency, oracleData, loan.amount);
    require(rcn.transferFrom(msg.sender, loan.borrower, transferValue));
    if (cosigner != address(0)) {
        loan.cosigner = address(uint256(cosigner) + 2);
        require(cosigner.requestCosign(this, index, cosignerData, oracleData));
        require(loan.cosigner == address(cosigner));
    }
    Lent(index, loan.lender, cosigner);
    return true;
}

function registerApprove(bytes32 identifier, uint8 v, bytes32 r, bytes32 s) public returns(bool) {
    uint256 index = identifierToIndex[identifier];
    require(index != 0);
    Loan storage loan = loans[index];
    require(loan.borrower == ecrecover(keccak256("\x19Ethereum Signed Message:\n32", identifier), v, r, s));
    loan.approbations[loan.borrower] = true;
    ApprovedBy(index, loan.borrower);
    return true;
}

function createLoan(Oracle _oracleContract, address _borrower, bytes32 _currency, uint256 _amount, uint256 _interestRate,
    uint256 _interestRatePunitory, uint256 _duesIn, uint256 _cancelableAt, uint256 _expirationRequest, string _metadata) public returns(uint256) {
    require(!deprecated);
    require(_cancelableAt <= _duesIn);
    require(_oracleContract != address(0) || _currency == 0x0);
    require(_borrower != address(0));
    require(_amount != 0);
    require(_interestRatePunitory != 0);
    require(_interestRate != 0);
    require(_expirationRequest > block.timestamp);
    var loan = Loan(Status.initial, _oracleContract, _borrower, 0x0, msg.sender, 0x0, _amount, 0, 0, 0, 0, _interestRate,
        _interestRatePunitory, 0, _duesIn, _currency, _cancelableAt, 0, 0x0, _expirationRequest, _metadata);
    uint index = loans.push(loan) - 1;
    CreatedLoan(index, _borrower, msg.sender);
    bytes32 identifier = getIdentifier(index);
    require(identifierToIndex[identifier] == 0);
    identifierToIndex[identifier] = index;
    if (msg.sender == _borrower) {
        approveLoan(index);
    }
    return index;
}

function convertRate(Oracle oracle, bytes32 currency, bytes data, uint256 amount) public returns(uint256) {
    if (oracle == address(0)) {
        return amount;
    } else {
        uint256 rate;
        uint256 decimals;
        (rate, decimals) = oracle.getRate(currency, data);
        require(decimals <= RCN_DECIMALS);
        return (safeMult(safeMult(amount, rate), (10 ** (RCN_DECIMALS - decimals)))) / PRECISION;
    }
}

function pay(uint index, uint256 _amount, address _from, bytes oracleData) public returns(bool) {
    Loan storage loan = loans[index];
    require(loan.status == Status.lent);
    addInterest(index);
    uint256 toPay = min(getPendingAmount(index), _amount);
    PartialPayment(index, msg.sender, _from, toPay);
    loan.paid = safeAdd(loan.paid, toPay);
    if (getRawPendingAmount(index) == 0) {
        TotalPayment(index);
        loan.status = Status.paid;
        lendersBalance[loan.lender] -= 1;
        activeLoans -= 1;
        Transfer(loan.lender, 0x0, index);
    }
    uint256 transferValue = convertRate(loan.oracle, loan.currency, oracleData, toPay);
    require(transferValue > 0 || toPay < _amount);
    lockTokens(rcn, transferValue);
    require(rcn.transferFrom(msg.sender, this, transferValue));
    loan.lenderBalance = safeAdd(transferValue, loan.lenderBalance);
    return true;
}

function convertRate(Oracle oracle, bytes32 currency, bytes data, uint256 amount) public returns(uint256) {
    if (oracle == address(0)) {
        return amount;
    } else {
        uint256 rate;
        uint256 decimals;
        (rate, decimals) = oracle.getRate(currency, data);
        require(decimals <= MAX_DECIMALS);
        return (safeMult(safeMult(amount, rate), (10 ** decimals))) / PRECISION;
    }
}

function lend(uint index, bytes oracleData, Cosigner cosigner, bytes cosignerData) public returns(bool) {
    Loan storage loan = loans[index];
    require(loan.status == Status.initial);
    require(isApproved(index));
    require(block.timestamp <= loan.expirationRequest);
    loan.lender = msg.sender;
    loan.dueTime = safeAdd(block.timestamp, loan.duesIn);
    loan.interestTimestamp = block.timestamp;
    loan.status = Status.lent;
    Transfer(0x0, loan.lender, index);
    activeLoans += 1;
    lendersBalance[loan.lender] += 1;
    if (loan.cancelableAt > 0)
        internalAddInterest(loan, safeAdd(block.timestamp, loan.cancelableAt));
    require(rcn.transferFrom(msg.sender, loan.borrower, safeMult(loan.amount, getRate(loan, oracleData))));
    if (cosigner != address(0)) {
        loan.cosigner = address(uint256(cosigner) + 2);
        require(cosigner.requestCosign(this, index, cosignerData, oracleData));
        require(loan.cosigner == address(cosigner));
    }
    Lent(index, loan.lender, cosigner);
    return true;
}

