    require(msg.sender == loan.lender || msg.sender == loan.approvedTransfer || operators[loan.lender][msg.sender]);
    require(to != address(0));
    lendersBalance[loan.lender] -= 1;
    lendersBalance[to] += 1;
    Transfer(loan.lender, to, index);
    loan.lender = to;
    loan.approvedTransfer = address(0);
    return true;
}

function getRateIncludingBonus() internal view returns(uint256) {
    if (now < openingTime + 1 weeks) {
        return rate.mul(125).div(100);
    } else if (now < openingTime + 2 weeks) {
        return rate.mul(115).div(100);
    } else if (now < openingTime + 4 weeks) {
        return rate.mul(110).div(100);
    } else {
        return rate;
    }
}

function _validFromLockedAddress(address sender) private view returns(bool) {
    if (sender != lockedAddress)
        return true;
    if (unlockedTime < block.timestamp)
        return true;
    return false;
}

function _addAuction(uint40 _cutieId, Auction _auction, uint256 _fee) internal {
    require(_auction.duration >= 1 minutes);
    cutieIdToAuction[_cutieId] = _auction;
    emit AuctionCreated(
        _cutieId,
        _auction.startPrice,
        _auction.endPrice,
        _auction.duration,
        _fee
    );
}

function getAuctionInfo(uint40 _cutieId)
