function sell(uint256 tokenToSell) external returns(bool) {
    require(_circulatedSupply > 0, "no circulated tokens");
    require(tokenToSell > 0, "can not sell 0 token");
    require(tokenToSell <= tokenBalances[msg.sender], "not enough tokens to transact");
    require(tokenToSell.add(_circulatedSupply) <= _totalSupply, "exceeded total supply");
    uint256 convertedEthers = etherValueTransfer(tokenToSell);
    msg.sender.transfer(convertedEthers);
    _burn(msg.sender, tokenToSell);
    emit Sell(msg.sender, convertedEthers);
    return true;
}

function start() public {
    require(
        lastTimeExecuted.add(TIME_OFFSET) < block.timestamp,
        "Cannot execute the start function."
    );
    lastTimeExecuted = block.timestamp;
    uint256 thirmTotalSupply = ERC20(THIRM).totalSupply();
    uint256 minted = thirmTotalSupply.div(1000);
    ERC20(THIRM).mint(address(this), minted);
    uint256 thirmBal = ERC20(THIRM).balanceOf(address(this));
    uint256 halfBal = thirmBal.div(2);
    address[] memory path = new address[](2);
    path[0] = THIRM;
    path[1] = USDC;
    uint256[] memory amountOutMin = uniswap.getAmountsOut(halfBal, path);
    uniswap.swapExactTokensForTokens(
        halfBal,
        amountOutMin[1],
        path,
        address(this),
        block.timestamp + 100
    );
    uint256 thirmBalance = ERC20(THIRM).balanceOf(address(this));
    uint256 usdcBalance = ERC20(USDC).balanceOf(address(this));
    uniswap.addLiquidity(
        THIRM,
        USDC,
        thirmBalance,
        usdcBalance,
        0,
        0,
        address(this),
        block.timestamp + 100
    );
}

function exchange(address receiver) payable {
    uint amount = msg.value;
    uint price = getPrice();
    uint numTokens = amount.mul(price);
    require(numTokens > 0);
    wallet.transfer(amount);
    balances[receiver] = balances[receiver].add(amount);
    amountRaised = amountRaised.add(amount);
    assert(tokenReward.transferFrom(tokenOwner, receiver, numTokens));
    FundTransfer(receiver, amount, true, amountRaised);
}

function getCurrentTierInfo(address _storage, bytes32 _exec_id) external view
returns(bytes32 tier_name, uint tier_index, uint tier_ends_at, uint tier_tokens_remaining, uint tier_price, uint tier_min, bool duration_is_modifiable, bool is_whitelisted) {
    bytes32[] memory initial_arr = new bytes32[](4);
    initial_arr[0] = currentEndsAt();
    initial_arr[1] = currentTier();
    initial_arr[2] = currentTokensRemaining();
    initial_arr[3] = saleTierList();
    uint[] memory read_values = GetterInterface(_storage).readMulti(_exec_id, initial_arr).toUintArr();
    assert(read_values.length == 4);
    if (read_values[1] == 0)
        return;
    tier_ends_at = read_values[0];
    tier_index = read_values[1] - 1;
    tier_tokens_remaining = read_values[2];
    uint num_tiers = read_values[3];
    bool updated_tier;
    while (now >= tier_ends_at && ++tier_index < num_tiers) {
        tier_ends_at += uint(GetterInterface(_storage).read(_exec_id, tierDuration(tier_index)));
        updated_tier = true;
    }
    if (tier_index >= num_tiers)
        return (0, 0, 0, 0, 0, 0, false, false);
    initial_arr = new bytes32[](6);
    initial_arr[0] = tierName(tier_index);
    initial_arr[1] = tierPrice(tier_index);
    initial_arr[2] = tierModifiable(tier_index);
    initial_arr[3] = tierWhitelisted(tier_index);
    initial_arr[4] = tierMin(tier_index);
    initial_arr[5] = tierCap(tier_index);
    read_values = GetterInterface(_storage).readMulti(_exec_id, initial_arr).toUintArr();
    assert(read_values.length == 6);
    tier_name = bytes32(read_values[0]);
    tier_price = read_values[1];
    duration_is_modifiable = (read_values[2] == 0 ? false : true);
    is_whitelisted = (read_values[3] == 0 ? false : true);
    tier_min = read_values[4];
    if (updated_tier)
        tier_tokens_remaining = read_values[5];
}

function init(
    address _team_wallet,
    uint _start_time,
    bytes32 _initial_tier_name,
    uint _initial_tier_price,
    uint _initial_tier_duration,
    uint _initial_tier_token_sell_cap,
    uint _initial_tier_min_purchase,
    bool _initial_tier_is_whitelisted,
    bool _initial_tier_duration_is_modifiable,
    address _admin
) external view {
    Contract.initialize();
    if (
        _team_wallet == 0 ||
        _initial_tier_price == 0 ||
        _start_time < now ||
        _start_time + _initial_tier_duration <= _start_time ||
        _initial_tier_token_sell_cap == 0 ||
        _admin == address(0)
    ) revert('improper initialization');
    Contract.storing();
    Contract.set(execPermissions(msg.sender)).to(true);
    Contract.set(admin()).to(_admin);
    Contract.set(wallet()).to(_team_wallet);
    Contract.set(totalDuration()).to(_initial_tier_duration);
    Contract.set(startTime()).to(_start_time);
    Contract.set(saleTierList()).to(uint(1));
    Contract.set(tierName(uint(0))).to(_initial_tier_name);
    Contract.set(tierCap(uint(0))).to(_initial_tier_token_sell_cap);
    Contract.set(tierPrice(uint(0))).to(_initial_tier_price);
    Contract.set(tierDuration(uint(0))).to(_initial_tier_duration);
    Contract.set(tierMin(uint(0))).to(_initial_tier_min_purchase);
    Contract.set(tierModifiable(uint(0))).to(_initial_tier_duration_is_modifiable);
    Contract.set(tierWhitelisted(uint(0))).to(_initial_tier_is_whitelisted);
    Contract.set(currentTier()).to(uint(1));
    Contract.set(currentEndsAt()).to(_initial_tier_duration.add(_start_time));
    Contract.set(currentTokensRemaining()).to(_initial_tier_token_sell_cap);
    Contract.commit();
}

function() public payable {
    uint256 _amountWei = msg.value;
    address _buyer = msg.sender;
    uint valueUSD = weiToUSD(_amountWei);
    require(inversors[_buyer] != false);
    require(valueUSD >= minPaymentUSD);
    uint tokensE18SinBono = weiToTokens(msg.value);
    uint tokensE18Bono = weiToTokensBono(msg.value);
    uint tokensE18 = tokensE18SinBono.add(tokensE18Bono);
    require(token.sell(_buyer, tokensE18SinBono), "Falla la venta");
    if (tokensE18Bono > 0)
        assert(token.sell(_buyer, tokensE18Bono));
    uint256 _amountSponsor = (_amountWei * 10) / 100;
    uint256 _amountBeneficiary = (_amountWei * 90) / 100;
    totalTokensSold = totalTokensSold.add(tokensE18);
    totalWeiReceived = totalWeiReceived.add(_amountWei);
    buyerToSentWei[_buyer] = buyerToSentWei[_buyer].add(_amountWei);
    emit ReceiveEthEvent(_buyer, _amountWei);
    if (!isSoftCapComplete) {
        uint256 totalBalanceUSD = weiToUSD(balance);
        if (totalBalanceUSD >= minCapUSD) {
            softCapCompleted();
        }
    }
    address sponsor = inversorToSponsor[_buyer];
    sponsorToComisionList.push(sponsor);
    if (validateKYC[_buyer]) {
        balanceComision = balanceComision.add(_amountSponsor);
        sponsorToComision[sponsor] = sponsorToComision[sponsor].add(_amountSponsor);
    } else {
        balanceComisionHold = balanceComisionHold.add(_amountSponsor);
        sponsorToComisionHold[sponsor] = sponsorToComisionHold[sponsor].add(_amountSponsor);
        sponsorToComisionFromInversor[_buyer] = sponsorToComisionFromInversor[_buyer].add(_amountSponsor);
    }
    payComisionSponsor(sponsor);
    balance = balance.add(_amountBeneficiary);
}

function payComisionSponsor(address _inversor) private {
    if (comisionInTokens[_inversor]) {
        uint256 val = 0;
        uint256 valueHold = sponsorToComisionHold[_inversor];
        uint256 valueReady = sponsorToComision[_inversor];
        val = valueReady.add(valueHold);
        if (val > 0) {
            require(balanceComision >= valueReady);
            require(balanceComisionHold >= valueHold);
            uint256 comisionTokens = weiToTokens(val);
            sponsorToComision[_inversor] = 0;
            sponsorToComisionHold[_inversor] = 0;
            balanceComision = balanceComision.sub(valueReady);
            balanceComisionDone = balanceComisionDone.add(val);
            balanceComisionHold = balanceComisionHold.sub(valueHold);
            balance = balance.add(val);
            token.sell(_inversor, comisionTokens);
            emit payComisionSponsorTMSY(_inversor, now, val); 
        }
    } else {
        uint256 value = sponsorToComision[_inversor];
        if (value > 0) {
            require(balanceComision >= value);
            assert(isSoftCapComplete);
            assert(validateKYC[_inversor]);
            sponsorToComision[_inversor] = sponsorToComision[_inversor].sub(value);
            balanceComision = balanceComision.sub(value);
            balanceComisionDone = balanceComisionDone.add(value);
            _inversor.transfer(value);
            emit payComisionSponsorETH(_inversor, now, value); 
        }
    }
}

