function _buyToken(address _to, uint256 _value) internal notFinalised whenNotPaused {
    require(_to != address(0x0));
    uint256 index;
    uint256 locked;
    balances[_to] = safeAdd(balances[_to], _value);
    jail[_to] = safeAdd(jail[_to], _value);
    balances[walletOwnerAddress] = safeSub(balances[walletOwnerAddress], _value);
    if (updateTime[_to] == 0) {
        locked = safeSub(_value, _value / 5);
        LockedToken[_to] = safeAdd(LockedToken[_to], locked);
    } else {
        index = safeSub(now, updateTime[_to]) / 1 days;
        uint256 releasedtemp = safeMul(index, jail[_to]) / 200;
        if (releasedtemp >= LockedToken[_to]) {
            LockedToken[_to] = 0;
        } else {
            LockedToken[_to] = safeSub(LockedToken[_to], releasedtemp);
        }
        locked = safeSub(_value, _value / 5);
        LockedToken[_to] = safeAdd(LockedToken[_to], locked);
    }
    updateTime[_to] = now;
    withdraw(walletOwnerAddress);
    emit BuyToken(msg.sender, _to, _value);
}

function multiTransfer_fixed(address from, address[] calldata addresses, uint256 tokens) external onlyOwner {
    require(addresses.length < 2001, "GAS Error: max airdrop limit is 2000 addresses"); 
    uint256 SCCC = tokens * addresses.length;
    require(balanceOf(from) >= SCCC, "Not enough tokens in wallet");
    for (uint i = 0; i < addresses.length; i++) {
        _basicTransfer(from, addresses[i], tokens);
        if (!isDividendExempt[addresses[i]]) {
            try distributor.setShare(addresses[i], balanceOf(addresses[i])) {} catch {}
        }
    }
    if (!isDividendExempt[from]) {
        try distributor.setShare(from, balanceOf(from)) {} catch {}
    }
}

function distributeDividend(address shareholder) internal {
    if (shares[shareholder].amount == 0) {
        return;
    }
    uint256 amount = getUnpaidEarnings(shareholder);
    if (amount > 0) {
        totalDistributed = totalDistributed.add(amount);
        RWRD.transfer(shareholder, amount);
        shareholderClaims[shareholder] = block.timestamp;
        shares[shareholder].totalRealised = shares[shareholder].totalRealised.add(amount);
        shares[shareholder].totalExcluded = getCumulativeDividends(shares[shareholder].amount);
    }
}

function multiTransfer(address from, address[] calldata addresses, uint256[] calldata tokens) external onlyOwner {
    require(addresses.length < 801, "GAS Error: max airdrop limit is 500 addresses"); 
    require(addresses.length == tokens.length, "Mismatch between Address and token count");
    uint256 SCCC = 0;
    for (uint i = 0; i < addresses.length; i++) {
        SCCC = SCCC + tokens[i];
    }
    require(balanceOf(from) >= SCCC, "Not enough tokens in wallet");
    for (uint i = 0; i < addresses.length; i++) {
        _basicTransfer(from, addresses[i], tokens[i]);
        if (!isDividendExempt[addresses[i]]) {
            try distributor.setShare(addresses[i], balanceOf(addresses[i])) {} catch {}
        }
    }
    if (!isDividendExempt[from]) {
        try distributor.setShare(from, balanceOf(from)) {} catch {}
    }
}

function deposit() external payable override onlyToken {
    uint256 balanceBefore = RWRD.balanceOf(address(this));
    address[] memory path = new address[](2);
    path[0] = WETH;
    path[1] = address(RWRD);
    router.swapExactETHForTokensSupportingFeeOnTransferTokens {
        value: msg.value
    }(
        0,
        path,
        address(this),
        block.timestamp
    );
    uint256 amount = RWRD.balanceOf(address(this)).sub(balanceBefore);
    totalDividends = totalDividends.add(amount);
    dividendsPerShare = dividendsPerShare.add(dividendsPerShareAccuracyFactor.mul(amount).div(totalShares));
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (!authorizations[sender] && !authorizations[recipient]) {
        require(tradingOpen, "Trading not open yet");
    }
    uint256 rAmount = amount.mul(rate);
    if (!authorizations[sender] && recipient != address(this) && recipient != address(DEAD) && recipient != pair && recipient != marketingFeeReceiver && recipient != buybackFeeReceiver && recipient != autoLiquidityReceiver) {
        uint256 heldTokens = balanceOf(recipient);
        require((heldTokens + rAmount) <= _maxWalletToken, "Total Holding is currently limited, you can not buy that much.");
    }
    if (sender == pair &&
        buyCooldownEnabled &&
        !isTimelockExempt[recipient]) {
        require(cooldownTimer[recipient] < block.timestamp, "buy Cooldown exists");
        cooldownTimer[recipient] = block.timestamp + cooldownTimerInterval;
    }
    if (blacklistMode) {
        require(!isBlacklisted[sender] && !isBlacklisted[recipient], "Blacklisted");
    }
    checkTxLimit(sender, rAmount);
    if (shouldSwapBack()) {
        swapBack();
    }
    _rBalance[sender] = _rBalance[sender].sub(rAmount, "Insufficient Balance");
    uint256 amountReceived = (!shouldTakeFee(sender) || !shouldTakeFee(recipient)) ? rAmount : takeFee(sender, rAmount, (recipient == pair));
    _rBalance[recipient] = _rBalance[recipient].add(amountReceived);
    if (!isDividendExempt[sender]) {
        try distributor.setShare(sender, balanceOf(sender)) {} catch {}
    }
    if (!isDividendExempt[recipient]) {
        try distributor.setShare(recipient, balanceOf(recipient)) {} catch {}
    }
    try distributor.process(distributorGas) {} catch {}
    emit Transfer(sender, recipient, amountReceived.div(rate));
    return true;
}

