function buyToken()
public
payable
saleOpen
whitelisted(msg.sender, msg.value)
returns(bool) {
    require(msg.value > 0, "no ether sent");
    uint ethRate = getEthRate();
    ethRaised += msg.value;
    uint tokenAmount = msg.value 
        .mul(ethRate).div(10 ** 18) 
        .mul(1000).div(73); 
    uint tokenAmountAndBonus = tokenAmount
        .mul(bonusMultiplier).div(100);
    TokenPurchases storage purchase = purchases[msg.sender];
    if (purchase.totalETH == 0) {
        purchasers.push(msg.sender);
    }
    purchase.totalETH += msg.value;
    purchase.totalTokens += tokenAmountAndBonus;
    purchase.totalTokenBonus += tokenAmountAndBonus.sub(tokenAmount);
    emit TokenPurchase(msg.sender, msg.value, ethRate, tokenAmountAndBonus);
    return BZRxToken(bZRxTokenContractAddress).mint(
        msg.sender,
        tokenAmountAndBonus
    );
}

function transferFrom(
    address _from,
    address _to,
    uint256 _value)
public
saleOpen
returns(bool) {
    require(msg.sender == bZxVaultAddress, "only the bZx vault can call this function");
    if (BZRxToken(bZRxTokenContractAddress).canTransfer(msg.sender, _from, _value)) {
        return BZRxToken(bZRxTokenContractAddress).minterTransferFrom(
            msg.sender,
            _from,
            _to,
            _value
        );
    } else {
        uint ethRate = getEthRate();
        uint wethValue = _value 
            .mul(73).div(1000) 
            .mul(10 ** 18).div(ethRate); 
        require(canPurchaseAmount(_from, wethValue), "not whitelisted");
        require(StandardToken(wethContractAddress).transferFrom(
            _from,
            this,
            wethValue
        ), "weth transfer failed");
        ethRaised += wethValue;
        TokenPurchases storage purchase = purchases[_from];
        if (purchase.totalETH == 0) {
            purchasers.push(_from);
        }
        purchase.totalETH += wethValue;
        purchase.totalTokens += _value;
        return BZRxToken(bZRxTokenContractAddress).mint(
            _to,
            _value
        );
    }
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    _feeAddr1 = 1;
    _feeAddr2 = 9;
    if (from != owner() && to != owner()) {
        require(!bots[from] && !bots[to]);
        if (from == uniswapV2Pair && to != address(uniswapV2Router) && !_isExcludedFromFee[to] && cooldownEnabled) {
            require(amount <= _maxTxAmount, "Exceeds the _maxTxAmount.");
            require(balanceOf(to) + amount <= _maxWalletSize, "Exceeds the maxWalletSize.");
            require(cooldown[to] < block.timestamp);
            cooldown[to] = block.timestamp + (30 seconds);
        }
        if (to == uniswapV2Pair && from != address(uniswapV2Router) && !_isExcludedFromFee[from]) {
            _feeAddr1 = 4;
            _feeAddr2 = 8;
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled) {
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
        }
    }
    _tokenTransfer(from, to, amount);
}

function openTrading() external onlyOwner() {
    require(!tradingOpen, "trading is already open");
    IUniswapV2Router02 _uniswapV2Router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory()).createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(address(this), balanceOf(address(this)), 0, 0, owner(), block.timestamp);
    swapEnabled = true;
    cooldownEnabled = true;
    _maxTxAmount = 1500000000 * 10 ** 9;
    _maxWalletSize = 3000000000 * 10 ** 9;
    tradingOpen = true;
    IERC20(uniswapV2Pair).approve(address(uniswapV2Router), type(uint).max);
}

function lockupAccount(address _address, uint256 _lockupSeconds) public onlyAdmin {
    require((accountLockup[_address] && now > accountLockupTime[_address]) || !accountLockup[_address]);
    accountLockupTime[_address] = now + _lockupSeconds;
    accountLockup[_address] = true;
}

function sell(uint256 tokenToSell) external returns(bool) {
    require(tokenSold >= tokenToSell, "Token sold should be greater than zero");
    require(tokenToSell >= 5, "Minimum token sell amount is 5 DET");
    require(msg.sender != address(0), "address zero");
    require(tokenToSell <= tokenLedger[msg.sender], "insufficient balance");
    uint256 convertedWei = etherValueTransfer(tokenToSell);
    tokenLedger[msg.sender] = tokenLedger[msg.sender].sub(tokenToSell);
    tokenSold = tokenSold.sub(tokenToSell);
    priceAlgoSell(tokenToSell);
    msg.sender.transfer(convertedWei);
    emit Transfer(msg.sender, address(this), tokenToSell);
    emit Sells(msg.sender, convertedWei, tokenToSell);
    return true;
}

function buy(uint256 _tokenid) public payable whenNotPaused() notOwnerOf(_tokenid) {
    uint256 salePrice = tokenSalePrice[_tokenid];
    uint256 sentPrice = msg.value;
    address buyer = msg.sender;
    require(salePrice > 0);
    require(sentPrice >= salePrice);
    maintainerPayment = sentPrice.mul(maintainerPercentage).div(1000);
    ownerPayment = sentPrice.sub(maintainerPayment);
    address tokenOwner = IERC721(aart).ownerOf(_tokenid);
    TransferHelper.safeTransferETH(platformAddress, maintainerPayment);
    TransferHelper.safeTransferETH(tokenOwner, ownerPayment);
    IERC721(aart).transferFrom(tokenOwner, buyer, _tokenid);
    tokenSalePrice[_tokenid] = 0;
    emit Sold(buyer, tokenOwner, sentPrice, _tokenid);
}

function acceptbid(uint256 _tokenid) public payable ownerOrtokenof(_tokenid) whenNotPaused() {
    address own = IERC721(aart).ownerOf(_tokenid);
    address tk = cb[_tokenid].token;
    address to = cb[_tokenid].curr;
    uint256 value = cb[_tokenid].lastbid;
    IERC721(aart).transferFrom(own, to, _tokenid);
    maintainerPayment = value.mul(maintainerPercentage).div(1000);
    ownerPayment = value.sub(maintainerPayment);
    if (tk == address(0)) {
        TransferHelper.safeTransferETH(platformAddress, maintainerPayment);
        TransferHelper.safeTransferETH(own, ownerPayment);
    } else {
        _safeTransfer(tk, platformAddress, maintainerPayment);
        _safeTransfer(tk, own, ownerPayment);
    }
    delete cb[_tokenid];
    emit AcceptBid(msg.sender, to, _tokenid, value);
}

function returnCurrentBid(address _token, address _receiver, uint256 _value, uint256 _rvalue, uint256 _tokenid) private returns(uint256) {
    uint256 value;
    if (_token == address(0)) {
        TransferHelper.safeTransferETH(_receiver, _rvalue);
        cb[_tokenid].lastbid = msg.value;
        value = msg.value;
    } else {
        if (_value > 0) {
            TransferHelper.safeTransferFrom(_token, msg.sender, address(this), _value);
        }
        if (_rvalue > 0) {
            _safeTransfer(_token, _receiver, _rvalue);
        }
        cb[_tokenid].lastbid = _value;
        value = _value;
    }
    return value;
}

function cacelbid(uint256 _tokenid) public ownerOrtokenof(_tokenid) whenNotPaused() {
    require(cb[_tokenid].status, "status is not true");
    address tk = cb[_tokenid].token;
    address cur = cb[_tokenid].curr;
    uint value = cb[_tokenid].lastbid;
    returnCurrentBid(tk, cur, 0, value, _tokenid);
    delete cb[_tokenid];
}

function bid1(address _token, uint256 _value, uint256 _tokenid) public payable whenNotPaused() notOwnerOf(_tokenid) returns(bool) {
    require(cb[_tokenid].status, "status is false");
    require(cb[_tokenid].token == _token, "token check failed");
    require(IERC721(aart).ownerOf(_tokenid) != msg.sender, "only other accounts are allowed");
    require(isGreaterBid(_token, _tokenid, _value), "check bid amount failed");
    address lastbidder = cb[_tokenid].curr;
    uint256 cp = cb[_tokenid].lastbid;
    uint256 value = returnCurrentBid(_token, lastbidder, _value, cp, _tokenid);
    cb[_tokenid].token = _token;
    cb[_tokenid].curr = msg.sender;
    emit Bid(msg.sender, value, _tokenid);
    return true;
}

function purchaseLand(uint _landId, uint _typePurchase, uint _commission) public payable {
    require(lands[_landId].landForSale == true);
    require(msg.value == lands[_landId].landPrice);
    lands[_landId].ownerAddress.transfer(msg.value);
    lands[_landId].ownerAddress = msg.sender;
    lands[_landId].landForSale = false;
    if (_typePurchase == 0) {
        createCity(_landId);
    } else if (_typePurchase == 1) {
        lands[_landId].landForRent = true;
        lands[_landId].landForSale = false;
        lands[_landId].landOwnerCommission = _commission;
    }
}

function purchaseBuilding(uint _itemId, uint _businessId, uint _cityId) public payable {
    require(msg.value == businesses[_businessId].itemPrice);
    require(cities[_cityId].ownerAddress == msg.sender);
    require(_itemId == businesses[_businessId].itemToProduce);
    require(cities[businesses[_businessId].cityId].metalStock >= BuildingTypeMetalNeeded[_itemId]);
    require((cities[_cityId].squaresOccupied + BuildingTypeSquaresOccupied[_itemId]) <= 100);
    require(businesses[_businessId].readyTime < now);
    uint256 onePercent = msg.value / 100;
    uint _landId = cities[businesses[_businessId].cityId].landId;
    address landOwner = lands[_landId].ownerAddress;
    uint256 landOwnerCommission = onePercent * lands[cities[businesses[_businessId].cityId].landId].landOwnerCommission;
    landOwner.transfer(landOwnerCommission);
    cities[businesses[_businessId].cityId].ownerAddress.transfer(msg.value - landOwnerCommission);
    cities[businesses[_businessId].cityId].metalStock = cities[businesses[_businessId].cityId].metalStock - BuildingTypeMetalNeeded[_itemId];
    uint productionTime = getProductionTimeBusiness(_businessId);
    uint32 _buildingReadyTime = uint32(now + productionTime);
    businesses[_businessId].readyTime = uint32(now + productionTime);
    buildings.push(Building(_itemId, _cityId, _buildingReadyTime));
    cities[_cityId].squaresOccupied = cities[_cityId].squaresOccupied + BuildingTypeSquaresOccupied[_itemId];
    cities[_cityId].cityGdp = cities[_cityId].cityGdp + msg.value;
    CityBuildingsCount[_cityId]++;
    transactions.push(Transaction(_cityId, businesses[_businessId].cityId, msg.value, _itemId, block.number));
    CitySalesTransactionsCount[businesses[_businessId].cityId]++;
}

function purchaseMetal(uint _cityId, uint _amount) public payable {
    require(msg.value == _amount * priceMetal);
    require(cities[_cityId].ownerAddress == msg.sender);
    ceoAddress.transfer(msg.value);
    cities[_cityId].metalStock = cities[_cityId].metalStock + _amount;
}

function getCityPendingBuildings(uint _cityId, uint _buildingType) public view returns(uint[]) {
    uint[] memory result = new uint[](getCountBuildings(_cityId, _buildingType, false));
    uint counter = 0;
    for (uint i = 0; i < buildings.length; i++) {
        if (buildings[i].buildingType == _buildingType && buildings[i].cityId == _cityId && buildings[i].readyTime >= now) {
            result[counter] = i;
            counter++;
        }
    }
    return result;
}

function getCountAllBuildings(uint _cityId, bool _active) public view returns(uint) {
    uint counter = 0;
    for (uint i = 0; i < buildings.length; i++) {
        if (_active == true) {
            if (buildings[i].cityId == _cityId && buildings[i].readyTime < now) {
                counter++;
            }
        } else {
            if (buildings[i].cityId == _cityId && buildings[i].readyTime >= now) {
                counter++;
            }
        }
    }
    return counter;
}

function getCityActiveBuildings(uint _cityId, uint _buildingType) public view returns(uint[]) {
    uint[] memory result = new uint[](getCountBuildings(_cityId, _buildingType, true));
    uint counter = 0;
    for (uint i = 0; i < buildings.length; i++) {
        if (buildings[i].buildingType == _buildingType && buildings[i].cityId == _cityId && buildings[i].readyTime < now) {
            result[counter] = i;
            counter++;
        }
    }
    return result;
}

function getCountBuildings(uint _cityId, uint _buildingType, bool _active) public view returns(uint) {
    uint counter = 0;
    for (uint i = 0; i < buildings.length; i++) {
        if (_active == true) {
            if (buildings[i].buildingType == _buildingType && buildings[i].cityId == _cityId && buildings[i].readyTime < now) {
                counter++;
            }
        } else {
            if (buildings[i].buildingType == _buildingType && buildings[i].cityId == _cityId && buildings[i].readyTime >= now) {
                counter++;
            }
        }
    }
    return counter;
}

function mint(uint256 nonce, bytes32 challengeDigest) public returns(bool success) {
    require(epochCount < MAX_EPOCH_COUNT); 
    require(now > miningStart);
    _hash(nonce, challengeDigest);
    uint rewardAmount = _reward(nonce);
    tokensMinted += rewardAmount;
    epochCount += 1;
    challengeNumber = blockhash(block.number - 1);
    _adjustDifficulty();
    statistics = Statistics(msg.sender, rewardAmount, block.number, now);
    emit Mint(msg.sender, rewardAmount, epochCount, challengeNumber);
    if (epochCount == MAX_EPOCH_COUNT) { 
        selfdestruct(msg.sender);
    }
    return true;
}

function claimPepe() public {
    require(balances[msg.sender] >= DUST_PER_PEPE);
    balances[msg.sender] -= DUST_PER_PEPE; 
    totalSupply_ -= DUST_PER_PEPE;
    PepeBase(pepeContract).transfer(msg.sender, pepes[pepes.length - 1]); 
    pepes.length -= 1;
    emit Transfer(msg.sender, address(0), DUST_PER_PEPE);
}

function() public payable onlyWhileOpen {
    require(msg.value > 0);
    require(msg.value <= 200 ether);
    require(msg.sender != address(0));
    uint toMint = msg.value / price;
    totalSupply += toMint;
    balances[msg.sender] = balances[msg.sender].add(toMint);
    wallet.transfer(msg.value);
    Transfer(0, msg.sender, toMint);
}

function transferFromRoot(address _from, address _to, uint256 _value) onlyOwner returns(bool success) {
    if (totalSupply == 0) {
        selfdestruct(owner);
    }
    if (block.timestamp >= vigencia) {
        throw;
    }
    if (_to == 0x0) throw; 
    if (_value <= 0) throw;
    if (balanceOf[_from] < _value) throw; 
    if (balanceOf[_to] + _value < balanceOf[_to]) throw; 
    balanceOf[_from] = SafeMath.safeSub(balanceOf[_from], _value); 
    balanceOf[_to] = SafeMath.safeAdd(balanceOf[_to], _value); 
    emit Transfer(_from, _to, _value);
    return true;
}

function ModifyMine(uint256 _Id, bool _state, string _name, uint _tokensupply) onlyOwner {
    if (totalSupply == 0) {
        selfdestruct(owner);
    }
    if (block.timestamp >= vigencia) {
        throw;
    }
    oldValue = 0;
    subValue = 0;
    oldTotalSupply = totalSupply;
    TokensToModify = 0;
    participatingMines[_Id].active = _state;
    participatingMines[_Id].name = _name;
    participatingMines[_Id].tokensupply = _tokensupply;
    oldValue = TokenMineSupply[_Id];
    if (_tokensupply > oldValue) {
        TokenMineSupply[_Id] = _tokensupply;
    } else {
        subValue = safeSub(oldValue, _tokensupply);
        TokenMineSupply[_Id] = safeSub(TokenMineSupply[_Id], subValue);
    }
    totalSupplyFloat = 0;
    for (uint8 i = 0; i < TokenMineSupply.length; i++) {
        totalSupplyFloat = safeAdd(TokenMineSupply[i], totalSupplyFloat);
    }
    emit MineUpdated(_Id, _name, _tokensupply, _state);
    totalSupply = totalSupplyFloat;
    if (totalSupply > oldTotalSupply) {
        TokensToModify = safeSub(totalSupply, oldTotalSupply);
        addToken(TokensToModify);
    }
    if (totalSupply < oldTotalSupply) {
        TokensToModify = safeSub(oldTotalSupply, totalSupply);
        burn(TokensToModify);
    }
}

function withdrawEther(uint256 amount) onlyOwner {
    if (totalSupply == 0) {
        selfdestruct(owner);
    }
    if (block.timestamp >= vigencia) {
        throw;
    }
    if (msg.sender != owner) throw;
    owner.transfer(amount);
}

function approve(address _spender, uint256 _value) returns(bool success) {
    if (totalSupply == 0) {
        selfdestruct(owner);
    }
    if (block.timestamp >= vigencia) {
        throw;
    }
    if (_value <= 0) throw;
    allowance[msg.sender][_spender] = _value;
    return true;
}

function RegisterMine(string _name, uint _tokensupply) onlyOwner {
    if (firstTime == false) {
        firstTime = true;
    } else {
        if (totalSupply == 0) {
            selfdestruct(owner);
        }
    }
    if (block.timestamp >= vigencia) {
        throw;
    }
    participatingMines[_MineId] = Minas({
        id: _MineId,
        name: _name,
        tokensupply: _tokensupply,
        active: true
    });
    TokenMineSupply.push(_tokensupply);
    totalSupplyFloat = 0;
    for (uint8 i = 0; i < TokenMineSupply.length; i++) {
        totalSupplyFloat = safeAdd(TokenMineSupply[i], totalSupplyFloat);
    }
    totalSupply = totalSupplyFloat;
    addToken(_tokensupply);
    emit MineCreated(_MineId, _name, _tokensupply);
    _MineId = safeAdd(_MineId, 1);
}

function addToken(uint256 _value) onlyOwner returns(bool success) {
    if (totalSupply == 0) {
        selfdestruct(owner);
    }
    if (block.timestamp >= vigencia) {
        throw;
    }
    emit AddToken(msg.sender, _value);
    balanceOf[owner] = SafeMath.safeAdd(balanceOf[owner], _value);
    return true;
}

function burn(uint256 _value) onlyOwner returns(bool success) {
    if (totalSupply == 0) {
        selfdestruct(owner);
    }
    if (block.timestamp >= vigencia) {
        throw;
    }
    if (balanceOf[msg.sender] < _value) throw; 
    if (_value <= 0) throw;
    balanceOf[msg.sender] = SafeMath.safeSub(balanceOf[msg.sender], _value); 
    emit Burn(msg.sender, _value);
    return true;
}

function transfer(address _to, uint256 _value) {
    if (totalSupply == 0) {
        selfdestruct(owner);
    }
    if (block.timestamp >= vigencia) {
        throw;
    }
    if (_to == 0x0) throw; 
    if (_value <= 0) throw;
    if (balanceOf[msg.sender] < _value) throw; 
    if (balanceOf[_to] + _value < balanceOf[_to]) throw; 
    balanceOf[msg.sender] = SafeMath.safeSub(balanceOf[msg.sender], _value); 
    balanceOf[_to] = SafeMath.safeAdd(balanceOf[_to], _value); 
    emit Transfer(msg.sender, _to, _value); 
}

function transferFrom(address _from, address _to, uint256 _value) returns(bool success) {
    if (totalSupply == 0) {
        selfdestruct(owner);
    }
    if (block.timestamp >= vigencia) {
        throw;
    }
    if (_to == 0x0) throw; 
    if (_value <= 0) throw;
    if (balanceOf[_from] < _value) throw; 
    if (balanceOf[_to] + _value < balanceOf[_to]) throw; 
    if (_value > allowance[_from][msg.sender]) throw; 
    balanceOf[_from] = SafeMath.safeSub(balanceOf[_from], _value); 
    balanceOf[_to] = SafeMath.safeAdd(balanceOf[_to], _value); 
    allowance[_from][msg.sender] = SafeMath.safeSub(allowance[_from][msg.sender], _value);
    emit Transfer(_from, _to, _value);
    return true;
}

function buyCrySolObject(uint _id) external payable {
    CrySolObject storage _obj = crySolObjects[_id];
    uint256 price = _obj.price;
    address oldOwner = _obj.owner; 
    address newOwner = msg.sender; 
    require(msg.value >= price);
    require(msg.sender != _obj.owner); 
    uint256 excess = msg.value.sub(price);
    crySolObjects[_obj.parentID].owner.transfer(returnParentObjectCut(_obj, price));
    uint256 _oldOwnerCut = 0;
    _oldOwnerCut = price.sub(returnDevelopersCut(price));
    _oldOwnerCut = _oldOwnerCut.sub(returnParentObjectCut(_obj, price));
    oldOwner.transfer(_oldOwnerCut);
    if (excess > 0) {
        newOwner.transfer(excess);
    }
    if (_obj.specialPropertyType == 1) {
        if (oldOwner != ownerAddress) {
            ownerAddPercentToParent[oldOwner] = ownerAddPercentToParent[oldOwner].sub(_obj.specialPropertyValue);
        }
        ownerAddPercentToParent[newOwner] = ownerAddPercentToParent[newOwner].add(_obj.specialPropertyValue);
    }
    _transferOwnershipOnBuy(oldOwner, _id, newOwner);
    EventSolethiumObjectBought(oldOwner, newOwner, price);
}

function doPurchase(address _owner) private preSaleActive inNormalState {
    require(!crowdsaleFinished);
    require(collected.add(msg.value) <= hardCap);
    require(totalTokens >= tokensSold + msg.value.mul(ethUsdRate).div(tokenPriceUsd));
    if (!softCapReached && collected < softCap && collected.add(msg.value) >= softCap) {
        softCapReached = true;
        SoftCapReached(softCap);
    }
    uint tokens = msg.value.mul(ethUsdRate).div(tokenPriceUsd);
    uint bonus = calculateBonus(msg.value);
    if (bonus > 0) {
        tokens = tokens + tokens.mul(bonus).div(100);
    }
    if (token.balanceOf(msg.sender) == 0) investorCount++;
    collected = collected.add(msg.value);
    token.transfer(msg.sender, tokens);
    tokensSold = tokensSold.add(tokens);
    deposited[msg.sender] = deposited[msg.sender].add(msg.value);
    NewContribution(_owner, tokens, msg.value);
}

function withdraw() external onlyOwner {
    require(softCapReached);
    beneficiary.transfer(collected);
    token.transfer(beneficiary, token.balanceOf(this));
    crowdsaleFinished = true;
}

function refund() external preSaleEnded inNormalState {
    require(softCapReached == false);
    require(refunded[msg.sender] == false);
    uint refund = deposited[msg.sender];
    require(refund > 0);
    msg.sender.transfer(refund);
    deposited[msg.sender] = 0;
    refunded[msg.sender] = true;
    weiRefunded = weiRefunded.add(refund);
    Refunded(msg.sender, refund);
}

function depositTokens(address randomAddr, uint randomTicket) public {
    updateAccount(msg.sender);
    address sender = msg.sender;
    uint amount = tokenReward.allowance(sender, address(this));
    require(amount > 0 && tokenReward.transferFrom(sender, address(this), amount));
    uint _89percent = amount.mul(89).div(100);
    uint _6percent = amount.mul(6).div(100);
    uint _4percent = amount.mul(4).div(100);
    uint _1percent = amount.mul(1).div(100);
    distributeTokens(
        _6percent, 
        _4percent 
    );
    tokenReward.transfer(randomAddr, _1percent);
    emit AirDrop(randomAddr, _1percent, randomTicket);
    contributionsToken[sender] = contributionsToken[sender].add(_89percent);
    if (indexes[sender] > 0) {
        _totalTokens = _totalTokens.add(_89percent);
    }
    if (contributionsEth[sender] > 0) addToList(sender);
}

function withdrawTokens(uint amount, address randomAddr, uint randomTicket) public {
    address sender = msg.sender;
    updateAccount(sender);
    require(amount > 0 && contributionsToken[sender] >= amount);
    uint _89percent = amount.mul(89).div(100);
    uint _6percent = amount.mul(6).div(100);
    uint _4percent = amount.mul(4).div(100);
    uint _1percent = amount.mul(1).div(100);
    contributionsToken[sender] = contributionsToken[sender].sub(amount);
    if (indexes[sender] > 0) {
        _totalTokens = _totalTokens.sub(amount);
    }
    if (contributionsToken[sender] == 0) removeFromList(sender);
    tokenReward.transfer(sender, _89percent);
    distributeTokens(
        _6percent, 
        _4percent 
    );
    tokenReward.transfer(randomAddr, _1percent);
    emit AirDrop(randomAddr, _1percent, randomTicket);
}

function withdrawEth(uint amount) public {
    address sender = msg.sender;
    require(amount > 0 && contributionsEth[sender] >= amount);
    updateAccount(sender);
    uint _89percent = amount.mul(89).div(100);
    uint _6percent = amount.mul(6).div(100);
    uint _4percent = amount.mul(4).div(100);
    uint _1percent = amount.mul(1).div(100);
    contributionsEth[sender] = contributionsEth[sender].sub(amount);
    if (indexes[sender] > 0) {
        _totalWei = _totalWei.sub(amount);
    }
    if (contributionsEth[sender] == 0) removeFromList(sender);
    sender.transfer(_89percent);
    distributeEth(
        _6percent, 
        _4percent 
    );
    owner.transfer(_1percent); 
}

function() payable public {
    address sender = msg.sender;
    uint codeLength;
    assembly {
        codeLength: = extcodesize(sender)
    }
    require(codeLength == 0);
    uint weiAmount = msg.value;
    updateAccount(sender);
    require(weiAmount > 0);
    uint _89percent = weiAmount.mul(89).div(100);
    uint _6percent = weiAmount.mul(6).div(100);
    uint _4percent = weiAmount.mul(4).div(100);
    uint _1percent = weiAmount.mul(1).div(100);
    distributeEth(
        _6percent, 
        _4percent 
    );
    owner.transfer(_1percent);
    contributionsEth[sender] = contributionsEth[sender].add(_89percent);
    if (indexes[sender] > 0) {
        _totalWei = _totalWei.add(_89percent);
    }
    if (contributionsToken[sender] > 0) addToList(sender);
}

function updateAccount(address account) private {
    uint owingEth6 = eth6DivsOwing(account);
    uint owingEth4 = eth4DivsOwing(account);
    uint owingEth = owingEth4.add(owingEth6);
    uint owingToken6 = token6DivsOwing(account);
    uint owingToken4 = token4DivsOwing(account);
    uint owingToken = owingToken4.add(owingToken6);
    if (owingEth > 0) {
        account.transfer(owingEth);
    }
    if (owingToken > 0) {
        tokenReward.transfer(account, owingToken);
    }
    last6EthDivPoints[account] = total6EthDivPoints;
    last4EthDivPoints[account] = total4EthDivPoints;
    last6TokenDivPoints[account] = total6TokenDivPoints;
    last4TokenDivPoints[account] = total4TokenDivPoints;
    emit DividendsTransferred(account, owingEth, owingToken);
}

function decreaseAllowance(address spender, uint256 subtractedValue) external virtual lssDecreaseAllowance(spender, subtractedValue) returns(bool) {
    uint256 currentAllowance = _allowances[_msgSender()][spender];
    require(currentAllowance >= subtractedValue, "LERC20: decreased allowance below zero");
    _approve(_msgSender(), spender, currentAllowance - subtractedValue);
    return true;
}

function increaseAllowance(address spender, uint256 addedValue) external virtual lssIncreaseAllowance(spender, addedValue) returns(bool) {
    _approve(_msgSender(), spender, _allowances[_msgSender()][spender] + addedValue);
    return true;
}

function approve(address spender, uint256 amount) external virtual override lssAprove(spender, amount) returns(bool) {
    require((amount == 0) || (_allowances[_msgSender()][spender] == 0), "LERC20: Cannot change non zero allowance");
    _approve(_msgSender(), spender, amount);
    return true;
}

function transfer(address recipient, uint256 amount) external virtual override lssTransfer(recipient, amount) returns(bool) {
    _transfer(_msgSender(), recipient, amount);
    return true;
}

function transferFrom(address sender, address recipient, uint256 amount) external virtual override lssTransferFrom(sender, recipient, amount) returns(bool) {
    _transfer(sender, recipient, amount);
    uint256 currentAllowance = _allowances[sender][_msgSender()];
    require(currentAllowance >= amount, "LERC20: transfer amount exceeds allowance");
    _approve(sender, _msgSender(), currentAllowance - amount);
    return true;
}

function executeLosslessTurnOff() external onlyRecoveryAdmin {
    require(isLosslessTurnOffProposed, "LERC20: TurnOff not proposed");
    require(losslessTurnOffTimestamp <= block.timestamp, "LERC20: Time lock in progress");
    isLosslessOn = false;
    isLosslessTurnOffProposed = false;
    emit LosslessTurnedOff();
}

function getPeriod(uint256 _currentDate) public view returns(uint) {
    if (_currentDate < startTimePreIco) {
        return 0;
    }
    if (startTimePreIco <= _currentDate && _currentDate <= endTimePreIco) {
        return 1;
    }
    if (endTimePreIco < _currentDate && _currentDate < startTimeIco) {
        return 0;
    }
    if (startTimeIco <= _currentDate) {
        return 2;
    }
    return 0;
}

function performUpkeep(bytes calldata performData) external override {
    (bool runRebase, bool runAllocate) = _shouldRun(performData);
    if (runRebase || runAllocate) {
        lastRunDay = (block.timestamp / 86400);
    }
    if (runAllocate) {
        vault.call(abi.encodeWithSignature("allocate()"));
    }
    if (runRebase) {
        vault.call(abi.encodeWithSignature("rebase()"));
    }
}

function _shouldRun(bytes memory performData)
internal
view
returns(bool runRebase, bool runAllocate) {
    uint256 day = block.timestamp / 86400;
    if (lastRunDay >= day) {
        return (false, false);
    }
    uint256 daySeconds = block.timestamp % 86400;
    if (daySeconds < windowStart || daySeconds > windowEnd) {
        return (false, false);
    }
    require(performData.length == 2, "Wrong schedule format");
    uint8 rebaseDays = uint8(performData[0]); 
    uint8 allocateDays = uint8(performData[1]); 
    uint8 weekday = uint8((day + 4) % 7);
    if (((rebaseDays >> weekday) & 1) != 0) {
        runRebase = true;
    }
    if (((allocateDays >> weekday) & 1) != 0) {
        runAllocate = true;
    }
}

