function requestMutualJobCancellation(
    bytes16 _jobId,
    address _hirer,
    address _contractor,
    uint256 _value,
    uint256 _fee
) external onlyHirerOrContractor(_hirer, _contractor) {
    bytes32 jobHash = getJobHash(
        _jobId,
        _hirer,
        _contractor,
        _value,
        _fee);
    require(jobEscrows[jobHash].exists);
    require(jobEscrows[jobHash].status == STATUS_JOB_STARTED);
    if (msg.sender == _hirer) {
        jobEscrows[jobHash].status = STATUS_HIRER_REQUEST_CANCEL;
        emit HirerRequestedCancel(jobHash, msg.sender);
    }
    if (msg.sender == _contractor) {
        jobEscrows[jobHash].status = STATUS_CONTRACTOR_REQUEST_CANCEL;
        emit ContractorRequestedCancel(jobHash, msg.sender);
    }
}

function resolveDispute(
    bytes16 _jobId,
    address _hirer,
    address _contractor,
    uint256 _value,
    uint256 _fee,
    uint8 _contractorPercent
) external onlyArbitrator {
    bytes32 jobHash = getJobHash(
        _jobId,
        _hirer,
        _contractor,
        _value,
        _fee);
    require(jobEscrows[jobHash].exists);
    require(jobEscrows[jobHash].status == STATUS_JOB_IN_DISPUTE);
    require(_contractorPercent <= 100);
    uint256 jobValue = hirerEscrowMap[_hirer][jobHash];
    require(jobValue > 0 && jobValue == _value);
    require(jobValue >= jobValue.sub(_fee));
    require(totalInEscrow >= jobValue && totalInEscrow > 0);
    totalInEscrow = totalInEscrow.sub(jobValue);
    feesAvailableForWithdraw = feesAvailableForWithdraw.add(_fee);
    delete jobEscrows[jobHash];
    delete hirerEscrowMap[_hirer][jobHash];
    uint256 contractorAmount = jobValue.sub(_fee).mul(_contractorPercent).div(100);
    uint256 hirerAmount = jobValue.sub(_fee).mul(100 - _contractorPercent).div(100);
    emit DisputeResolved(
        jobHash,
        msg.sender,
        hirerAmount,
        contractorAmount);
    emit AddFeesToCoinSparrowPool(jobHash, _fee);
    _contractor.transfer(contractorAmount);
    _hirer.transfer(hirerAmount);
}

function processMutuallyAgreedJobCancellation(
    bytes16 _jobId,
    address _hirer,
    address _contractor,
    uint256 _value,
    uint256 _fee,
    uint8 _contractorPercent,
    bytes _hirerMsgSig,
    bytes _contractorMsgSig
) external {
    bytes32 jobHash = getJobHash(
        _jobId,
        _hirer,
        _contractor,
        _value,
        _fee);
    require(jobEscrows[jobHash].exists);
    require(msg.sender == _hirer || msg.sender == _contractor);
    require(_contractorPercent <= 100 && _contractorPercent >= 0);
    require(
        checkRefundSignature(_contractorPercent, _hirerMsgSig, _hirer) &&
        checkRefundSignature(_contractorPercent, _contractorMsgSig, _contractor));
    uint256 jobValue = hirerEscrowMap[_hirer][jobHash];
    require(jobValue > 0 && jobValue == _value);
    require(jobValue >= jobValue.sub(_fee));
    require(totalInEscrow >= jobValue && totalInEscrow > 0);
    totalInEscrow = totalInEscrow.sub(jobValue);
    feesAvailableForWithdraw = feesAvailableForWithdraw.add(_fee);
    delete jobEscrows[jobHash];
    delete hirerEscrowMap[_hirer][jobHash];
    uint256 contractorAmount = jobValue.sub(_fee).mul(_contractorPercent).div(100);
    uint256 hirerAmount = jobValue.sub(_fee).mul(100 - _contractorPercent).div(100);
    emit MutuallyAgreedCancellation(
        jobHash,
        msg.sender,
        hirerAmount,
        contractorAmount);
    emit AddFeesToCoinSparrowPool(jobHash, _fee);
    if (contractorAmount > 0) {
        _contractor.transfer(contractorAmount);
    }
    if (hirerAmount > 0) {
        _hirer.transfer(hirerAmount);
    }
}

function createJobEscrow(
    bytes16 _jobId,
    address _hirer,
    address _contractor,
    uint256 _value,
    uint256 _fee,
    uint32 _jobStartedWindowInSeconds,
    uint32 _secondsToComplete
) payable external whenNotPaused onlyHirer(_hirer) {
    require(msg.value == _value && msg.value > 0);
    require(_fee < _value);
    require(msg.value <= MAX_SEND);
    require(_jobStartedWindowInSeconds > 0);
    require(_secondsToComplete > 0);
    bytes32 jobHash = getJobHash(
        _jobId,
        _hirer,
        _contractor,
        _value,
        _fee);
    require(!jobEscrows[jobHash].exists);
    jobEscrows[jobHash] = JobEscrow(
        true,
        uint32(block.timestamp) + _jobStartedWindowInSeconds,
        STATUS_JOB_CREATED,
        0,
        _secondsToComplete,
        0);
    totalInEscrow = totalInEscrow.add(msg.value);
    hirerEscrowMap[msg.sender][jobHash] = msg.value;
    emit JobCreated(jobHash, msg.sender, msg.value);
}

function buyTokensByReferrer(address holder, address referrer) payable public pending {
    if (_canSetReferrer(holder, referrer)) {
        _setReferrer(holder, referrer);
    }
    uint256 amount = msg.value - OPERATIONS_FEE;
    holder.transfer(OPERATIONS_FEE);
    _buyTokens(holder, amount);
}

constructor(
    uint256 _totalSupply,
    uint256 _startTime,
    uint256 _endTime,
    ERC20 _token
) public {
    require(_startTime >= now);
    require(_startTime < _endTime);
    totalSupply = _totalSupply;
    startTime = _startTime;
    endTime = _endTime;
    token = _token;
}

function mint(uint256 baseTokenAmount) external updateReserve returns(uint) {
    uint256 rate = redeemRate();
    uint256 pyroTokensToMint = baseTokenAmount.mul(ONE).div(rate);
    require(
        IERC20(baseToken).transferFrom(
            msg.sender,
            address(this),
            baseTokenAmount
        ),
        "PYROTOKEN: baseToken transfer failed."
    );
    mint(msg.sender, pyroTokensToMint);
    emit Mint(msg.sender, baseToken, address(this), rate);
    return pyroTokensToMint;
}

function redeem(uint256 pyroTokenAmount) external updateReserve returns(uint) {
    balances[msg.sender] = balances[msg.sender].sub(
        pyroTokenAmount,
        "PYROTOKEN: insufficient balance"
    );
    uint256 rate = redeemRate();
    _totalSupply = _totalSupply.sub(pyroTokenAmount);
    uint256 exitFee = pyroTokenAmount.mul(2).div(100); 
    uint256 net = pyroTokenAmount.sub(exitFee);
    uint256 baseTokensToRelease = rate.mul(net).div(ONE);
    IERC20(baseToken).transfer(msg.sender, baseTokensToRelease);
    emit Redeem(msg.sender, baseToken, address(this), rate);
    return baseTokensToRelease;
}

function lock() public
notLocked
onlyOwner {
    uint totalLockedAmount = firstPrivateLockedAmount.add(secondPrivateLockedAmount);
    totalLockedAmount = totalLockedAmount.add(minerLockedAmount);
    require(token.balanceOf(address(this)) == totalLockedAmount);
    lockedAt = block.timestamp;
    firstPrivateReleaseTime = lockedAt.add(firstPrivateLockTime);
    secondPrivateReleaseTime = lockedAt.add(secondPrivateLockTime);
    minerRelaseTime = lockedAt.add(minerLockTime);
}

function unlockSecondPrivate() public
locked
onlyOwner {
    require(block.timestamp >= secondPrivateReleaseTime);
    require(secondPrivateLockedAmount > 0);
    uint256 amount = token.balanceOf(this);
    require(amount >= secondPrivateLockedAmount);
    token.transfer(privateLockAddress, secondPrivateLockedAmount);
    secondPrivateLockedAmount = 0;
}

function unlockFirstPrivate() public
locked
onlyOwner {
    require(block.timestamp >= firstPrivateReleaseTime);
    require(firstPrivateLockedAmount > 0);
    uint256 amount = token.balanceOf(this);
    require(amount >= firstPrivateLockedAmount);
    token.transfer(privateLockAddress, firstPrivateLockedAmount);
    firstPrivateLockedAmount = 0;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    epoch[] epochs = lockEpochsMap[_from];
    uint256 needLockBalance = 0;
    for (uint256 i = 0; i < epochs.length; i++) {
        if (now < epochs[i].lockEndTime) {
            needLockBalance = needLockBalance.add(epochs[i].lockAmount);
        }
    }
    require(balances[_from].sub(_value) >= needLockBalance);
    uint256 _allowance = allowed[_from][msg.sender];
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowed[_from][msg.sender] = _allowance.sub(_value);
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    epoch[] epochs = lockEpochsMap[msg.sender];
    uint256 needLockBalance = 0;
    for (uint256 i = 0; i < epochs.length; i++) {
        if (now < epochs[i].lockEndTime) {
            needLockBalance = needLockBalance.add(epochs[i].lockAmount);
        }
    }
    require(balances[msg.sender].sub(_value) >= needLockBalance);
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    Transfer(msg.sender, _to, _value);
    return true;
}

