function deposit()
public
payable
onlyOwner {
    require(msg.value > 0, "Must deposit something");
    uint snapshotId = token.snapshot();
    uint totalSupplyAtSnapshot = token.totalSupplyAt(snapshotId);
    uint newId = rewards.length;
    for (uint i = 0; i < blacklistLength(); i++) {
        address blacklisted = blacklistAt(i);
        uint balanceAtSnapshot = token.balanceOfAt(blacklisted, snapshotId);
        totalSupplyAtSnapshot = totalSupplyAtSnapshot.sub(balanceAtSnapshot);
        claimedRewards[blacklisted][newId] = true;
    }
    EthReward memory newReward = EthReward({
        snapshotId: snapshotId,
        totalSupplyAtSnapshot: totalSupplyAtSnapshot,
        rewardAmount: msg.value,
        claimedAmount: 0,
        timestamp: _getNow()
    });
    rewards.push(newReward);
    emit NewReward(newId, snapshotId, msg.value, _getNow());
}

function beforeDeadline(uint _rewardId)
public
view
returns(bool) {
    return _getNow() <= deadline(_rewardId);
}

function getRewardInfo(uint _rewardId)
public
view
returns(uint snapshotId, uint totalSupplyAtSnapshot, uint rewardAmount, uint claimedAmount, uint timestamp) {
    require(_rewardId >= 0 && _rewardId < getNumberOfRewards(), "Invalid reward id");
    EthReward memory reward = rewards[_rewardId];
    snapshotId = reward.snapshotId;
    totalSupplyAtSnapshot = reward.totalSupplyAtSnapshot;
    rewardAmount = reward.rewardAmount;
    claimedAmount = reward.claimedAmount;
    timestamp = reward.timestamp;
}

function claim(uint _rewardId)
public
nonReentrant {
    require(!claimedRewards[_msgSender()][_rewardId], "Already claimed");
    require(beforeDeadline(_rewardId), "Too late");
    uint myShare = getMyShare(_rewardId);
    require(myShare > 0, "Nothing to claim");
    EthReward storage reward = rewards[_rewardId];
    reward.claimedAmount = reward.claimedAmount.add(myShare);
    claimedRewards[_msgSender()][_rewardId] = true;
    (bool success, ) = _msgSender().call {
        value: myShare
    }("");
    require(success, "Claim: unable to send value, recipient may have reverted");
    emit Claimed(_msgSender(), _rewardId, myShare, _getNow());
}

function drain(uint _rewardId)
public
onlyOwner {
    require(!beforeDeadline(_rewardId), "Too early");
    require(!drained[_rewardId], "Already drained");
    (, , uint rewardAmount, uint claimedAmount, ) = getRewardInfo(_rewardId);
    uint unclaimedAmount = rewardAmount.sub(claimedAmount);
    drained[_rewardId] = true;
    _msgSender().transfer(unclaimedAmount);
    emit Drained(_rewardId, unclaimedAmount, _getNow());
}

function permissibleWithdrawal(uint _toWithdraw)
public
onlyWallet
returns(bool) {
    uint currentTime = now;
    uint contractBalance = address(this).balance;
    uint maxPerTx = (contractBalance.mul(MAX_WITHDRAW_PCT_TX)).div(100);
    require(_toWithdraw <= maxPerTx);
    if (currentTime - dailyResetTime >= resetTimer) {
        dailyResetTime = currentTime;
        dailyLimit = (contractBalance.mul(MAX_WITHDRAW_PCT_DAILY)).div(100);
        ethDispensedToday = _toWithdraw;
        return true;
    } else {
        if (ethDispensedToday.add(_toWithdraw) <= dailyLimit) {
            ethDispensedToday += _toWithdraw;
            return true;
        } else {
            return false;
        }
    }
}

function devWithdraw(uint amount) public
onlyWallet {
    require(permissibleWithdrawal(amount));
    uint amountPerPerson = SafeMath.div(amount, owners.length);
    for (uint i = 0; i < owners.length; i++) {
        owners[i].transfer(amountPerPerson);
    }
    emit DevWithdraw(amount, amountPerPerson);
}

function payEther(address[] receivers, uint256[] shares) external payable {
    require(receivers.length == shares.length);
    require(msg.value > adminFee.mul(shares.length));
    uint256 _eth = msg.value;
    uint256 totalshares = 0;
    for (uint256 i = 0; i < receivers.length; i++) {
        require(shares[i] > 0);
        totalshares = totalshares.add(shares[i]);
    }
    for (uint256 j = 0; j < receivers.length; j++) {
        uint256 eth_ = _eth.mul(shares[j]).div(totalshares).sub(adminFee);
        receivers[j].transfer(eth_);
    }
    emit EtherPay(_eth, receivers, shares);
    feeWallet.transfer(adminFee.mul(receivers.length));
}

function withdrawToWallet() onlyOwner public {
    require(state == State.Withdraw);
    wallet.transfer(this.balance);
    emit Withdrawn(wallet);
}

function setTiersInfo(uint8 _noOfPhases, uint256[] _startTimes, uint256[] _endTimes, uint256[] _hardCaps, uint8[3][4] _bonusPercentages) private {
    require(_noOfPhases == 4);
    require(_startTimes.length == _noOfPhases);
    require(_endTimes.length == _noOfPhases);
    require(_hardCaps.length == _noOfPhases);
    require(_bonusPercentages.length == _noOfPhases);
    noOfPhases = _noOfPhases;
    for (uint8 i = 0; i < _noOfPhases; i++) {
        require(_hardCaps[i] > 0);
        require(_endTimes[i] > _startTimes[i]);
        if (i > 0) {
            require(_startTimes[i] > _endTimes[i - 1]);
            phases.push(PhaseInfo({
                hardcap: _hardCaps[i],
                startTime: _startTimes[i],
                endTime: _endTimes[i],
                bonusPercentages: _bonusPercentages[i],
                weiRaised: 0
            }));
        } else {
            require(_startTimes[i] > now);
            phases.push(PhaseInfo({
                hardcap: _hardCaps[i],
                startTime: _startTimes[i],
                endTime: _endTimes[i],
                bonusPercentages: _bonusPercentages[i],
                weiRaised: 0
            }));
        }
    }
}

function claim() public payable game_over() {
    require(!claim_status[msg.sender] == true);
    uint tmp_value;
    if (msg.sender == winner) {
        tmp_value = price - 0.1 ether + (balance - price + 0.1 ether) / 20;
    }
    tmp_value += (balance - (balance - price + 0.1 ether) / 10 - price + 0.1 ether) / total_tickets * own_tickets[msg.sender];
    msg.sender.transfer(tmp_value);
    claim_status[msg.sender] = true;
}

function owner_withdraw() public payable game_over() {
    require(owner_flag == false);
    owner.transfer((balance - price + 0.1 ether) / 20);
    owner_flag = true;
}

function buy() public payable {
    require(msg.value >= price);
    require(now < stop_time);
    own_tickets[msg.sender]++;
    balance += msg.value;
    winner = msg.sender;
    stop_time = now + time;
    price += 0.1 ether;
    total_tickets++;
}

function withdraw(uint256 amount) public {
    require(tokens[0x0][msg.sender] >= amount);
    tokens[0x0][msg.sender] = tokens[0x0][msg.sender].sub(amount);
    msg.sender.transfer(amount);
    Withdraw(0x0, msg.sender, amount, tokens[0x0][msg.sender]);
}

function tradeBalances(
    address tokenGet,
    uint256 amountGet,
    address tokenGive,
    uint256 amountGive,
    address user,
    uint256 amount
)
private {
    uint256 feeMakeXfer = amount.mul(feeMake).div(1 ether);
    uint256 feeTakeXfer = amount.mul(feeTake).div(1 ether);
    uint256 feeRebateXfer = 0;
    if (accountLevelsAddr != 0x0) {
        uint256 accountLevel = AccountLevels(accountLevelsAddr).accountLevel(user);
        if (accountLevel == 1) {
            feeRebateXfer = amount.mul(feeRebate).div(1 ether);
        } else if (accountLevel == 2) {
            feeRebateXfer = feeTakeXfer;
        }
    }
    tokens[tokenGet][msg.sender] = tokens[tokenGet][msg.sender].sub(amount.add(feeTakeXfer));
    tokens[tokenGet][user] = tokens[tokenGet][user].add(amount.add(feeRebateXfer).sub(feeMakeXfer));
    tokens[tokenGet][feeAccount] = tokens[tokenGet][feeAccount].add(feeMakeXfer.add(feeTakeXfer).sub(feeRebateXfer));
    tokens[tokenGive][user] = tokens[tokenGive][user].sub(amountGive.mul(amount).div(amountGet));
    tokens[tokenGive][msg.sender] = tokens[tokenGive][msg.sender].add(amountGive.mul(amount).div(amountGet));
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint thisBalance = address(this).balance;
        uint amount = invested[msg.sender] * calculateProfitPercent(thisBalance) / 1000 * (block.number - atBlock[msg.sender]) / 6100;
        address sender = msg.sender;
        sender.transfer(amount);
    }
    if (msg.value > 0) {
        transferDefaultPercentsOfInvested(msg.value);
        transferRefPercents(msg.value, msg.sender);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += (msg.value);
}

function safeSend(uint tokens) private {
    uint256 balance = balanceOf(tokenWallet);
    if (balance < tokens) {
        uint toReturn = tokenRate.mul(tokens.sub(balance));
        sendTokens(msg.sender, balance);
        msg.sender.transfer(toReturn);
        multisig.transfer(msg.value.sub(toReturn));
        raisedEthers += msg.value.sub(toReturn);
    } else {
        sendTokens(msg.sender, tokens);
        multisig.transfer(msg.value);
        raisedEthers += msg.value;
    }
}

function() public payable {
    uint eth_sent = msg.value;
    uint tokens_amount = eth_sent.mul(exchangeRate);
    require(eth_sent > 0);
    require(exchangeRate > 0);
    require(stateStartDate < now && now < stateEndDate);
