function join(uint amount) public {
    uint bal = spaghetti.balanceOf(address(this));
    require(spaghetti.transferFrom(msg.sender, address(this), amount), "join/transferFrom-fail");
    balances[msg.sender] += spaghetti.balanceOf(address(this)) - bal;
}

function add(uint x, uint y) internal pure returns(uint z) {
    require((z = x + y) >= x);
}

function voteFor(uint id) public {
    require(proposals[id].start < block.timestamp, "<start");
    require(proposals[id].end > block.timestamp, ">end");
    uint votes = sub(balances[msg.sender], proposals[id].forVotes[msg.sender]);
    proposals[id].totalForVotes = add(votes, proposals[id].totalForVotes);
    proposals[id].forVotes[msg.sender] = balances[msg.sender];
    voteLock[msg.sender] = add(block.timestamp, lock);
}

function voteAgainst(uint id) public {
    require(proposals[id].start < block.timestamp, "<start");
    require(proposals[id].end > block.timestamp, ">end");
    uint votes = sub(balances[msg.sender], proposals[id].againstVotes[msg.sender]);
    proposals[id].totalAgainstVotes = add(votes, proposals[id].totalAgainstVotes);
    proposals[id].againstVotes[msg.sender] = balances[msg.sender];
    voteLock[msg.sender] = add(block.timestamp, lock);
}

function propose(address _newFood, address _newGov) public {
    require(block.timestamp >= govLock, "No governance for 2 weeks");
    require(balances[msg.sender] > minimum, "<minimum");
    proposals[proposalCount++] = Proposal({
        id: proposalCount,
        proposer: msg.sender,
        totalForVotes: 0,
        totalAgainstVotes: 0,
        start: block.timestamp,
        end: add(block.timestamp, period),
        newFood: _newFood,
        newGov: _newGov
    });
    voteLock[msg.sender] = add(block.timestamp, lock);
}

function sub(uint x, uint y) internal pure returns(uint z) {
    require((z = x - y) <= x);
}

function free(uint amount) public {
    require(voteLock[msg.sender] < block.timestamp, "still votelocked");
    require(balances[msg.sender] <= amount, "amount too high");
    balances[msg.sender] = sub(balances[msg.sender], amount);
    require(spaghetti.transfer(msg.sender, amount), "free/transfer-failed");
}

function execute(uint id) public {
    if ((proposals[id].end + lock) < block.timestamp && proposals[id].totalForVotes > proposals[id].totalAgainstVotes) {
        if (proposals[id].newFood != address(0)) {
            spaghetti.setFoodbank(proposals[id].newFood);
        }
        if (proposals[id].newGov != address(0)) {
            spaghetti.setGovernance(proposals[id].newGov);
        }
    }
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    if (allowedContracts[_to]) {
        Receiver receiver = Receiver(_to);
        receiver.tokenFallback(msg.sender, _value);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(msg.sender, _to, _value);
    return true;
}

function() payable public {
    require(!finalised);
    require(block.timestamp >= startTime);
    require(block.timestamp <= endTime);
    require(ethRaised < hardCap);
    require(msg.value >= minimumDonation);
    uint256 etherValue = msg.value;
    if (ethRaised + etherValue > hardCap) {
        etherValue = hardCap - ethRaised;
        assert(msg.value > etherValue);
        msg.sender.transfer(msg.value - etherValue);
    }
    ethFundAddress.transfer(etherValue);
    donationCount += 1;
    ethRaised += etherValue;
}

function transfer(address _to, uint256 _value) public {
    require(block.timestamp > lockEndTime || _isInWhiteAddresses(msg.sender));
    _transfer(msg.sender, _to, _value);
}

function burnFrom(address _from, uint256 _value) public returns(bool success) {
    require(block.timestamp > lockEndTime);
    require(balanceOf[_from] >= _value); 
    require(_value <= allowance[_from][msg.sender]); 
    balanceOf[_from] -= _value; 
    allowance[_from][msg.sender] -= _value; 
    totalSupply -= _value; 
    emit Burn(_from, _value);
    return true;
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(block.timestamp > lockEndTime || _isInWhiteAddresses(_from));
    require(_value <= allowance[_from][msg.sender]); 
    allowance[_from][msg.sender] -= _value;
    _transfer(_from, _to, _value);
    return true;
}

function burn(uint256 _value) public returns(bool success) {
    require(block.timestamp > lockEndTime);
    require(balanceOf[msg.sender] >= _value); 
    balanceOf[msg.sender] -= _value; 
    totalSupply -= _value; 
    emit Burn(msg.sender, _value);
    return true;
}

function upgrade() public onlyAdmin {
    require(proposedImplementation != address(0));
    require(proposedTimestamp < now);
    implementation = proposedImplementation;
    Upgraded(implementation);
}

function updateStage() public returns(uint256) {
    require(tokenSaleEnabled == true);
    require(currentStage < maxStage);
    require(now >= stages[currentStage].opening);
    uint256 remains = stages[currentStage].capacity.sub(stages[currentStage].sold);
    if (now > stages[currentStage].closing) {
        uint256 nextStage = currentStage.add(1);
        if (remains > 0 && nextStage < maxStage) {
            stages[nextStage].capacity = stages[nextStage].capacity.add(remains);
            remains = stages[nextStage].capacity;
        }
        currentStage = nextStage;
        emit StageUpdated(nextStage);
    }
    return remains;
}

function addStage(
    uint256 _openingTime,
    uint256 _closingTime,
    uint256 _capacity,
    uint256 _minimumWei,
    uint256 _maximumWei,
    uint256 _rate) onlyOwner public {
    require(tokenSaleEnabled == false);
    require(_openingTime > now);
    require(_closingTime > _openingTime);
    require(_capacity > 0);
    require(_capacity < hardCap);
    require(_minimumWei > 0);
    require(_maximumWei >= _minimumWei);
    require(_rate > 0);
    require(_minimumWei.mul(_rate) < _capacity);
    require(_maximumWei.mul(_rate) < _capacity);
    if (stages.length > 0) {
        StageInfo memory prevStage = stages[stages.length - 1];
        require(_openingTime > prevStage.closing);
    }
    stages.push(StageInfo(_openingTime, _closingTime, _capacity, _minimumWei, _maximumWei, _rate, 0));
    emit StageAdded(_openingTime, _closingTime, _capacity, _minimumWei, _maximumWei, _rate);
}

