function releaseRoto(address _user, bytes32 _tournamentID, uint256 _etherReward) external onlyOwner stopInEmergency returns(bool successful) {
    Tournament storage tournament = tournaments[_tournamentID];
    require(tournament.open == true);
    Stake storage user_stake = tournament.stakes[_user][_tournamentID];
    uint256 initial_stake = user_stake.amount;
    require(initial_stake > 0);
    require(user_stake.resolved == false);
    require(manager.balance > _etherReward);
    require(tournament.etherLeft >= _etherReward);
    user_stake.amount = 0;
    assert(token.releaseRoto(_user, _tournamentID)); 
    tournament.stakesResolved = tournament.stakesResolved.add(1);
    user_stake.resolved = true;
    user_stake.successful = true;
    if (_etherReward > 0) {
        tournament.etherLeft = tournament.etherLeft.sub(_etherReward);
        _user.transfer(_etherReward);
    }
    emit StakeReleased(_tournamentID, _user, _etherReward, initial_stake);
    return true;
}

function destroyRoto(address _user, bytes32 _tournamentID) external onlyOwner stopInEmergency returns(bool successful) {
    Tournament storage tournament = tournaments[_tournamentID];
    require(tournament.open == true);
    Stake storage user_stake = tournament.stakes[_user][_tournamentID];
    uint256 initial_stake = user_stake.amount;
    require(initial_stake > 0);
    require(user_stake.resolved == false);
    user_stake.amount = 0;
    user_stake.resolved = true;
    user_stake.successful = false;
    assert(token.destroyRoto(_user, _tournamentID));
    tournament.stakesResolved = tournament.stakesResolved.add(1);
    emit StakeDestroyed(_tournamentID, _user, initial_stake);
    return true;
}

function _stake(address _staker, bytes32 _tournamentID, uint256 _value) internal returns(bool successful) {
    Tournament storage tournament = tournaments[_tournamentID];
    require((tournament.open == true));
    require(tournament.etherPrize > 0);
    Stake storage user_stake = tournament.stakes[_staker][_tournamentID];
    require(user_stake.amount == 0); 
    require(_value > 0); 
    require(_staker != roto && _staker != owner); 
    assert(token.canStake(_staker, _value));
    user_stake.amount = _value;
    assert(token.stakeRoto(_staker, _tournamentID, _value));
    tournament.userStakes = tournament.userStakes.add(1);
    emit StakeProcessed(_staker, user_stake.amount, _tournamentID);
    return true;
}

function closeTournament(bytes32 _tournamentID) external onlyOwner returns(bool successful) {
    Tournament storage tournament = tournaments[_tournamentID];
    require(tournament.open == true);
    require(tournament.rotoLeft == 0 && tournament.etherLeft == 0);
    require(tournament.userStakes == tournament.stakesResolved);
    tournament.open = false;
    emit TournamentClosed(_tournamentID);
    return true;
}

function rewardRoto(address _user, bytes32 _tournamentID, uint256 _rotoReward) external onlyOwner stopInEmergency returns(bool successful) {
    Tournament storage tournament = tournaments[_tournamentID];
    require(tournament.open == true);
    Stake storage user_stake = tournament.stakes[_user][_tournamentID];
    uint256 initial_stake = user_stake.amount;
    require(initial_stake == 0);
    require(tournament.rotoLeft >= _rotoReward);
    require(user_stake.resolved == false);
    tournament.rotoLeft = tournament.rotoLeft.sub(_rotoReward);
    assert(token.rewardRoto(_user, _rotoReward));
    user_stake.resolved = true;
    user_stake.successful = true;
    emit SubmissionRewarded(_tournamentID, _user, _rotoReward);
    return true;
}

function createTournament(bytes32 _tournamentID, uint256 _etherPrize, uint256 _rotoPrize) external payable onlyOwner returns(bool successful) {
    Tournament storage newTournament = tournaments[_tournamentID];
    require(newTournament.creationTime == 0);
    newTournament.open = true;
    newTournament.etherPrize = _etherPrize;
    newTournament.etherLeft = _etherPrize;
    newTournament.rotoPrize = _rotoPrize;
    newTournament.rotoLeft = _rotoPrize;
    newTournament.creationTime = block.timestamp;
    emit TournamentCreated(_tournamentID, _etherPrize, _rotoPrize);
    return true;
}

function buyTokens() payable public {
    if (!active) {
        revert();
    }
    if (msg.value < purchaseLimit) {
        revert();
    }
    uint256 purchasedAmount = msg.value.div(priceDiv);
    if (purchasedAmount == 0) {
        revert();
    }
    if (purchasedAmount > hardCap - sold) {
        revert();
    }
    if (lockup[msg.sender] == 0) {
        lockup[msg.sender] = now + 1 years;
    }
    purchased[msg.sender] = purchased[msg.sender] + purchasedAmount;
    sold = sold + purchasedAmount;
    treasury.transfer(msg.value);
    Purchase(msg.sender, purchasedAmount, now, lockup[msg.sender]);
}

function redeem() public {
    if (purchased[msg.sender] == 0) {
        revert();
    }
    if (now < lockup[msg.sender]) {
        revert();
    }
    uint256 withdrawal = purchased[msg.sender];
    purchased[msg.sender] = 0;
    ERC223 token = ERC223(tokenAddress);
    token.transfer(msg.sender, withdrawal);
}

function getPendingDivs(address _holder) public view returns(uint256) {
    if (!holders.contains(_holder)) return 0;
    if (depositedTokens[_holder] == 0) return 0;
    uint256 timeDiff = now.sub(lastClaimedTime[_holder]);
    uint256 stakedAmount = depositedTokens[_holder];
    if (now > farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(38502858097).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    } else if (now <= farmEnableat + 7 days) {
        uint256 pendingDivs = stakedAmount.mul(rewardRate).mul(timeDiff).div(rewardInterval).div(1e4);
        return pendingDivs;
    }
}

function VerifyWinners(uint min, uint max) public {
    require(msg.sender == tx.origin);
    if ((!ticketsOpen) && (block.number > closedBlock + 3)) {
        uint i = 0;
        uint m = players.length;
        if (msg.sender == _closerAddress && min > 0 && max > 0) {
            i = min;
            m = max;
        }
        systemNumber = uint256(uint256(keccak256(abi.encodePacked(blockhash(block.number - 1)))) % maxNumber);
        address _winner;
        uint _winnerTickets;
        bool win = false;
        while (i < m) {
            if (win)
                break;
            uint j = 0;
            while (j < tickets[i]) {
                if (uint256(uint256(keccak256(abi.encodePacked(players[i], j))) % maxNumber) == systemNumber) {
                    win = true;
                    _winner = players[i];
                    _winnerTickets = tickets[i];
                    break;
                }
                j++;
            }
            i++;
        }
        if (win) {
            address payable add = payable(_winner);
            uint contractBalance = address(this).balance;
            uint winAmount = contractBalance * percentWin / 100;
            uint totalToPay = winAmount;
            if (!add.send(totalToPay)) revert('Error While Executing Payment.');
            totalPaidOut += totalToPay;
            winnersOnly.push(_winner);
            winnersOnlyTickets.push(_winnerTickets);
            winnersOnlyETH.push(totalToPay);
            winnersOnlyTimestamp.push(block.timestamp);
            pastGameNr.push(pastGameNr[pastGameNr.length - 1] + 1);
            pastGameSystemNumber.push(systemNumber);
            pastGamePlayers.push(players.length);
            pastGameTickets.push(currentTickets);
            winners.push(_winner);
            winnerTickets.push(_winnerTickets);
            winnerETHAmount.push(totalToPay);
            pastGameTimestamp.push(block.timestamp);
            winnersCount++;
            winnersEthCount += totalToPay;
            emit Numbers(_winner, systemNumber, "WINNER!");
        } else {
            pastGameNr.push(pastGameNr[pastGameNr.length - 1] + 1);
            pastGameSystemNumber.push(systemNumber);
            pastGamePlayers.push(players.length);
            pastGameTickets.push(currentTickets);
            winners.push(0x0000000000000000000000000000000000000000);
            winnerTickets.push(0);
            winnerETHAmount.push(0);
            pastGameTimestamp.push(block.timestamp);
            emit Numbers(msg.sender, systemNumber, "No winners! Try Again.");
        }
        currentTickets = 0;
        delete players;
        delete tickets;
        ticketsOpen = true;
        closedBlock = 0;
    } else {
        revert('Tickets must be closed and block number must be + 10');
    }
}

