    if (msg.sender == contractOwner && now >= timeUnlockToken) {
        StandardToken(address(this)).transfer(_addr, _value);
        return true;
    } else {
        if (msg.sender == contractOwner) {
            if ((balanceOf(address(this)) - _value) >= lockToken) {
                StandardToken(address(this)).transfer(_addr, _value);
                return true;
            } else {
                return false;
            }
