function serverForceGameEnd(
    uint8 _gameType,
    uint _betNum,
    uint _betValue,
    int _balance,
    uint _stake,
    uint _endInitiatedTime
)
public
view
onlyValidBalance(_balance, _stake)
returns(int) {
    require(_endInitiatedTime + SERVER_TIMEOUT <= block.timestamp, "too low timeout");
    require(isValidBet(_gameType, _betNum, _betValue) ||
        (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0), "inv bet");
    int newBalance = _balance.sub(_betValue.castToInt());
    newBalance = newBalance.sub(NOT_ENDED_FINE);
    int stake = _stake.castToInt();
    if (newBalance < -stake) {
        newBalance = -stake;
    }
    return newBalance;
}

function userForceGameEnd(
    uint8 _gameType,
    uint _betNum,
    uint _betValue,
    int _balance,
    uint _stake,
    uint _endInitiatedTime
)
public
view
onlyValidBalance(_balance, _stake)
returns(int) {
    require(_endInitiatedTime + USER_TIMEOUT <= block.timestamp, "too low timeout");
    require(isValidBet(_gameType, _betNum, _betValue) ||
        (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0), "inv bet");
    int profit = 0;
    if (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0) {
        profit = 0;
    } else {
        profit = calculateProfit(_gameType, _betNum, _betValue); 
    }
    profit = profit.add(NOT_ENDED_FINE);
    return _balance.add(profit);
}

function depositExactTokenForTokenOrder(address router, address sellToken, address pair, uint amountIn, uint amountOut) external override payable {
    uint fee = ethFee;
    require(msg.value >= fee, "TitanSwapV1 : no fee enough");
    orderIds = orderIds.add(1);
    uint _orderId = orderIds;
    TransferHelper.safeTransferFrom(sellToken, msg.sender, address(this), amountIn);
    depositOrders[_orderId] = Order(true, router, pair, msg.sender, sellToken, amountIn, amountOut, msg.value);
    emit Deposit(_orderId, router, pair, msg.sender, amountIn, amountOut, msg.value);
    orderCount = orderCount.add(1);
    userBalance = userBalance.add(msg.value);
}

function depositExactTokenForEth(address router, address sellToken, address pair, uint amountIn, uint amountOut) external override payable {
    uint fee = ethFee;
    require(msg.value >= fee, "TitanSwapV1 : no fee enough");
    orderIds = orderIds.add(1);
    uint _orderId = orderIds;
    TransferHelper.safeTransferFrom(sellToken, msg.sender, address(this), amountIn);
    depositOrders[_orderId] = Order(true, router, pair, msg.sender, sellToken, amountIn, amountOut, msg.value);
    emit Deposit(_orderId, router, pair, msg.sender, amountIn, amountOut, msg.value);
    orderCount = orderCount.add(1);
    userBalance = userBalance.add(msg.value);
}

function cancelTokenOrder(uint orderId) external override {
    Order memory order = depositOrders[orderId];
    require(order.exist, "order not exist.");
    require(msg.sender == order.user, "no auth to cancel.");
    TransferHelper.safeTransferETH(order.user, order.ethValue);
    if (order.sellToken != address(0)) {
        TransferHelper.safeTransfer(order.sellToken, order.user, order.amountIn);
    }
    userBalance = userBalance.sub(order.ethValue);
    delete(depositOrders[orderId]);
    orderCount = orderCount.sub(1);
    emit Cancel(orderId);
}

function executeExactTokenForTokenOrder(
    uint orderId,
    address[] calldata path,
    uint deadline
) external override {
    require(msg.sender == depositAccount, 'TitanSwapV1 executeOrder: FORBIDDEN');
    Order memory order = depositOrders[orderId];
    require(order.exist, "order not exist!");
    TransferHelper.safeApprove(path[0], order.router, order.amountIn);
    delete(depositOrders[orderId]);
    orderCount = orderCount.sub(1);
    userBalance = userBalance.sub(order.ethValue);
    ITitanSwapV1Router01(order.router).swapExactTokensForTokens(order.amountIn, order.amountOut, path, order.user, deadline);
    emit Success(orderId);
}

function executeExactTokenForETHOrder(uint orderId, address[] calldata path, uint deadline) external override {
    require(msg.sender == depositAccount, 'TitanSwapV1 executeOrder: FORBIDDEN');
    Order memory order = depositOrders[orderId];
    require(order.exist, "order not exist!");
    TransferHelper.safeApprove(path[0], order.router, order.amountIn);
    delete(depositOrders[orderId]);
    orderCount = orderCount.sub(1);
    userBalance = userBalance.sub(order.ethValue);
    ITitanSwapV1Router01(order.router).swapExactTokensForETH(order.amountIn, order.amountOut, path, order.user, deadline);
    emit Success(orderId);
}

function executeExactETHForTokenOrder(uint orderId, address[] calldata path, uint deadline) external override payable {
    require(deadline >= block.timestamp, 'UniswapV2Router: EXPIRED');
    require(msg.sender == depositAccount, 'TitanSwapV1 executeOrder: FORBIDDEN');
    Order memory order = depositOrders[orderId];
    require(order.exist, "order not exist!");
    delete(depositOrders[orderId]);
    orderCount = orderCount.sub(1);
    userBalance = userBalance.sub(order.ethValue);
    address factory = ITitanSwapV1Router01(order.router).factory();
    require(path[0] == WETH, 'UniswapV2Router: INVALID_PATH');
    uint[] memory amounts = TitanSwapV1Library.getAmountsOut(factory, order.amountIn, path);
    require(amounts[amounts.length - 1] >= order.amountOut, 'UniswapV2Router: INSUFFICIENT_OUTPUT_AMOUNT');
    IWETH(WETH).deposit {
        value: order.amountIn
    }();
    assert(IWETH(WETH).transfer(order.pair, amounts[0]));
    _swap(factory, amounts, path, order.user);
    emit Success(orderId);
}

