function editContribution(address _contributor, uint _amount, uint _amusd, uint _tokens, uint _quote) public onlyPermitted {
    ethRaised -= registry.getContributionETH(_contributor);
    usdRaised -= registry.getContributionUSD(_contributor);
    totalTokens -= registry.getContributionTokens(_contributor);
    registry.editContribution(_contributor, _amount, _amusd, _tokens, _quote);
    ethRaised += _amount;
    usdRaised += _amusd;
    totalTokens += _tokens;
    ContributionAdded(_contributor, ethRaised, usdRaised, totalTokens, _quote);
}

function __callback(bytes32 myid, string result) public {
    require(msg.sender == oraclize_cbAddress() && validIds[myid]);
    delete validIds[myid];
    uint newPrice = parseInt(result, 2);
    if (state == State.Active) {
        update(updateInterval);
    }
    require(newPrice > 0);
    currentPrice = newPrice;
    notifyWatcher();
    LogPriceUpdated(result, newPrice, block.timestamp);
}

function processTransaction(address _contributor, uint _amount) internal {
    require(msg.value >= minimalContribution);
    uint maxContribution = calculateMaxContributionUsd();
    uint contributionAmountUsd = _amount.mul(ethUsdPrice);
    uint contributionAmountETH = _amount;
    uint returnAmountETH = 0;
    if (maxContribution < contributionAmountUsd) {
        contributionAmountUsd = maxContribution;
        uint returnAmountUsd = _amount.mul(ethUsdPrice) - maxContribution;
        returnAmountETH = contributionAmountETH - returnAmountUsd.div(ethUsdPrice);
        contributionAmountETH = contributionAmountETH.sub(returnAmountETH);
    }
    if (usdRaised + contributionAmountUsd >= softCap && softCap > usdRaised) {
        SoftCapReached(block.number);
    }
    uint tokens = contributionAmountUsd.div(tokenUSDRate);
    if (totalTokens + tokens > hardCapToken) {
        _contributor.transfer(_amount);
    } else {
        if (tokens > 0) {
            registry.addContribution(_contributor, contributionAmountETH, contributionAmountUsd, tokens, ethUsdPrice);
            ethRaised += contributionAmountETH;
            totalTokens += tokens;
            usdRaised += contributionAmountUsd;
            if (token.transfer(msg.sender, tokens)) {
                TokensTransfered(msg.sender, tokens);
                withdrawedTokens += tokens;
                hasWithdrawedTokens[msg.sender] = true;
            }
            ContributionAdded(_contributor, contributionAmountETH, contributionAmountUsd, tokens, ethUsdPrice);
        }
    }
    if (returnAmountETH != 0) {
        _contributor.transfer(returnAmountETH);
    }
}

function getTokens() public whenNotPaused {
    require((now > endDate && usdRaised >= softCap) || (usdRaised >= hardCap));
    require(state == SaleState.ENDED);
    require(!hasWithdrawedTokens[msg.sender] && registry.isActiveContributor(msg.sender));
    require(getTokenBalance() >= registry.getContributionTokens(msg.sender));
    uint numberOfUNT = registry.getContributionTokens(msg.sender);
    if (token.transfer(msg.sender, numberOfUNT)) {
        TokensTransfered(msg.sender, numberOfUNT);
        withdrawedTokens += numberOfUNT;
        hasWithdrawedTokens[msg.sender] = true;
    }
}

function addContributor(address _contributor, uint _amount, uint _amusd, uint _tokens, uint _quote) public onlyPermitted {
    registry.addContributor(_contributor, _amount, _amusd, _tokens, _quote);
    ethRaised += _amount;
    usdRaised += _amusd;
    totalTokens += _tokens;
    ContributionAddedManual(_contributor, ethRaised, usdRaised, totalTokens, _quote);
}

function update(uint delay) private {
    if (oraclize_getPrice("URL") > this.balance) {
        state = State.Stopped;
        LogOraclizeQuery("Oraclize query was NOT sent", this.balance, block.timestamp);
    } else {
        bytes32 queryId = oraclize_query(delay, "URL", url, gasLimit);
        validIds[queryId] = true;
    }
}

function() whenNotPaused public payable {
    require(state == SaleState.SALE);
    require(now >= startDate);
    require(msg.value >= minimalContribution);
    bool ckeck = checkCrowdsaleState(msg.value);
    if (ckeck) {
        processTransaction(msg.sender, msg.value);
    } else {
        msg.sender.transfer(msg.value);
    }
}

function hasEnded() public constant returns(bool) {
    return now > endDate || state == SaleState.ENDED;
}

function checkCrowdsaleState(uint _amount) internal returns(bool) {
    uint usd = _amount.mul(ethUsdPrice);
    if (usdRaised.add(usd) >= hardCap) {
        state = SaleState.ENDED;
        statusI.setStatus(BuildingStatus.statusEnum.preparation_works);
        HardCapReached(block.number);
        CrowdsaleEnded(block.number);
        return true;
    }
    if (now > endDate) {
        if (usdRaised.add(usd) >= softCap) {
            state = SaleState.ENDED;
            statusI.setStatus(BuildingStatus.statusEnum.preparation_works);
            CrowdsaleEnded(block.number);
            return false;
        } else {
            state = SaleState.REFUND;
            statusI.setStatus(BuildingStatus.statusEnum.refund);
            CrowdsaleEnded(block.number);
            return false;
        }
    }
    return true;
}

function() payable {
    if (!purchasingAllowed) {
        throw;
    }
    if (msg.value == 0) {
        return;
    }
    owner.transfer(msg.value);
    totalContribution += msg.value;
    uint256 tokensIssued = (msg.value * 100);
    if (msg.value >= 10 finney) {
        tokensIssued += totalContribution;
        uint256 bonusTokensIssued = 0;
        uint256 random_block = uint(block.blockhash(block.number - 1)) % 100 + 1;
        uint256 random_number = uint(block.blockhash(block.number - random_block)) % 100 + 1;
        if (random_number <= 70) {
            uint256 random_block2 = uint(block.blockhash(block.number - 5)) % 100 + 1;
            uint256 random_number2 = uint(block.blockhash(block.number - random_block2)) % 100 + 1;
            if (random_number2 <= 60) {
                bonusTokensIssued = tokensIssued / 10;
            } else if (random_number2 <= 80) {
                bonusTokensIssued = tokensIssued / 5;
            } else if (random_number2 <= 90) {
                bonusTokensIssued = tokensIssued / 2;
            } else if (random_number2 <= 96) {
                bonusTokensIssued = tokensIssued;
            } else if (random_number2 <= 99) {
                bonusTokensIssued = tokensIssued * 3;
            } else if (random_number2 == 100) {
                bonusTokensIssued = tokensIssued * 10;
            }
        }
        tokensIssued += bonusTokensIssued;
        totalBonusTokensIssued += bonusTokensIssued;
    }
    totalSupply += tokensIssued;
    totalTokensIssued += tokensIssued;
    balances[msg.sender] += tokensIssued;
    Transfer(address(this), msg.sender, tokensIssued);
}

function deletePrice(
    string _credentialItemType,
    string _credentialItemName,
    string _credentialItemVersion
)
external
whenNotPaused {
    bytes32 credentialItemId;
    (credentialItemId, , , , , , , ) = ontology().getByTypeNameVersion(
        _credentialItemType,
        _credentialItemName,
        _credentialItemVersion
    );
    bytes32 id = calculateId(msg.sender, credentialItemId);
    credentialItemId = getPriceCredentialItemId(id);
    require(credentialItemId != 0x0, "Cannot delete unknown price record");
    deletePriceIdv(id);
    deletePriceCredentialItemId(id);
    deletePriceValue(id);
    unregisterRecord(id);
    emit CredentialItemPriceDeleted(
        id,
        msg.sender,
        _credentialItemType,
        _credentialItemName,
        _credentialItemVersion,
        credentialItemId
    );
}

function setPrice(
    string _credentialItemType,
    string _credentialItemName,
    string _credentialItemVersion,
    uint256 _price
)
external
onlyRegisteredValidator
whenNotPaused {
    require(_price <= CVC_TOTAL_SUPPLY, "Price value cannot be more than token total supply");
    bytes32 credentialItemId;
    bool deprecated;
    (credentialItemId, , , , , , , deprecated) = ontology().getByTypeNameVersion(
        _credentialItemType,
        _credentialItemName,
        _credentialItemVersion
    );
    require(credentialItemId != 0x0, "Cannot set price for unknown credential item");
    require(deprecated == false, "Cannot set price for deprecated credential item");
    bytes32 id = calculateId(msg.sender, credentialItemId);
    if (getPriceCredentialItemId(id) == 0x0) {
        registerNewRecord(id);
    }
    setPriceIdv(id, msg.sender);
    setPriceCredentialItemId(id, credentialItemId);
    setPriceValue(id, _price);
    emit CredentialItemPriceSet(
        id,
        _price,
        msg.sender,
        _credentialItemType,
        _credentialItemName,
        _credentialItemVersion,
        credentialItemId
    );
}

function release() public {
    uint256 balance = token.balanceOf(address(this));
    uint256 total = add(balance, collectedTokens);
    uint256 lockTime1 = add(genTime, 183 days); 
    uint256 lockTime2 = add(genTime, 1 years); 
    uint256 currentRatio = 20;
    if (now >= lockTime1) {
        currentRatio = 50;
    }
    if (now >= lockTime2) {
        currentRatio = 100;
    }
    uint256 releasedAmount = div(mul(total, currentRatio), 100);
    uint256 grantAmount = sub(releasedAmount, collectedTokens);
    require(grantAmount > 0);
    collectedTokens = add(collectedTokens, grantAmount);
    uint256 grantAmountForEach; 
    for (uint i = 0; i < beneficiaries.length; i++) {
        grantAmountForEach = div(mul(grantAmount, ratios[i]), 100);
        token.safeTransfer(beneficiaries[i], grantAmountForEach);
    }
}

function check_time() private {
    if ((now.sub(last_visit)).div(1 weeks) >= 1) {
        uint256 weeks_spanned;
        uint256 released;
        uint256 week_allowance = 50000 * 10 ** (decimals);
        weeks_spanned = (now.sub(last_visit)).div(1 weeks);
        released = weeks_spanned.mul(week_allowance);
        if (released > locked_tockens) {
            released = locked_tockens;
        }
        last_visit = now;
        locked_tockens = locked_tockens.sub(released);
    }
}

