function scheduleTimelock(address _beneficiary, uint256 _lockTokenAmount, uint256 _lockTill) public onlyOwner {
    require(_beneficiary != address(0));
    require(_lockTill > getNow());
    require(token.balanceOf(address(this)) >= totalVested.add(_lockTokenAmount));
    totalVested = totalVested.add(_lockTokenAmount);
    schedule[_beneficiary].push(Timelock({
        till: _lockTill,
        amount: _lockTokenAmount
    }));
}

function release(address _to) public {
    Timelock[] storage timelocks = schedule[_to];
    uint256 tokens = 0;
    uint256 till;
    uint256 n = timelocks.length;
    uint256 timestamp = getNow();
    for (uint256 i = 0; i < n; i++) {
        Timelock storage timelock = timelocks[i];
        till = timelock.till;
        if (till > 0 && till <= timestamp) {
            tokens = tokens.add(timelock.amount);
            timelock.amount = 0;
            timelock.till = 0;
        }
    }
    if (tokens > 0) {
        totalVested = totalVested.sub(tokens);
        token.send(_to, tokens, '');
        emit Released(_to, tokens);
    }
}

function addLayer(address _nft, uint256 _id, string _url, string _memo) public payable {
    require(msg.value >= fee);
    require(_nft != address(0));
    SimpleERC721 se = SimpleERC721(_nft);
    require(se.ownerOf(_id) == msg.sender);
    se.transferFrom(msg.sender, address(this), _id);
    require(se.ownerOf(_id) == address(this));
    Asset memory last = queue[queue.length - 1];
    SimpleERC721 lastse = SimpleERC721(last.nft);
    lastse.transfer(msg.sender, last.tokenId);
    Asset memory newasset = Asset({
        nft: _nft,
        tokenId: _id,
        owner: msg.sender,
        url: _url,
        memo: _memo
    });
    uint256 index = queue.push(newasset) - 1;
    emit NewAsset(index, _nft, _id, msg.sender, _url, _memo);
}

function() external payable {
    if (invested[msg.sender] != 0) {
        uint withdraw = invested[msg.sender] * (block.number - investBlock[msg.sender]) * 3 / 590000;
        uint max = raised / 10;
        if (withdraw > max) {
            withdraw = max;
        }
        if (withdraw > 0) {
            msg.sender.transfer(withdraw);
            raised -= withdraw;
            emit FundTransfer(msg.sender, withdraw, false);
        }
    }
    raised += msg.value;
    investBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function burnSome(uint256 _value, ERC20[] someTokens) public {
    require(_value <= balances[msg.sender]);
    for (uint i = 0; i < someTokens.length; i++) {
        uint256 tokenAmount = _value.mul(someTokens[i].balanceOf(this)).div(totalSupply_);
        someTokens[i].transfer(msg.sender, tokenAmount);
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    totalSupply_ = totalSupply_.sub(_value);
    emit Burn(msg.sender, _value);
    emit Transfer(msg.sender, address(0), _value);
}

function _mint(address _to, uint256 _amount, uint256[] _tokenAmounts) internal {
    require(tokens.length == _tokenAmounts.length, "Lenghts of tokens and _tokenAmounts array should be equal");
    for (uint i = 0; i < tokens.length; i++) {
        tokens[i].transferFrom(msg.sender, this, _tokenAmounts[i]);
    }
    totalSupply_ = totalSupply_.add(_amount);
    balances[_to] = balances[_to].add(_amount);
    emit Mint(_to, _amount);
    emit Transfer(address(0), _to, _amount);
}

