    uint8 piranhaSize = uint8(piranha.size + (now - piranha.growthStartTime) / 900);
    require(piranhaSize < 240);
    piranha.hungry = 1;
}

function allPiranhasInfo(uint256 _startPiranhaId) public view returns(address[] owners, uint8[] sizes, uint8[] hungry, uint256[] prices) { 
    uint256 totalPiranhas = totalSupply();
    Piranha storage piranha;
    if (totalPiranhas == 0 || _startPiranhaId >= totalPiranhas) {
        return (new address[](0), new uint8[](0), new uint8[](0), new uint256[](0));
    }
    uint256 indexTo;
    if (totalPiranhas > _startPiranhaId + 1000)
        indexTo = _startPiranhaId + 1000;
    else
        indexTo = totalPiranhas;
    uint256 totalResultPiranhas = indexTo - _startPiranhaId;
    address[] memory owners_res = new address[](totalResultPiranhas);
    uint8[] memory size_res = new uint8[](totalResultPiranhas);
    uint8[] memory hungry_res = new uint8[](totalResultPiranhas);
    uint256[] memory prices_res = new uint256[](totalResultPiranhas);
    for (uint256 piranhaId = _startPiranhaId; piranhaId < indexTo; piranhaId++) {
        piranha = piranhas[piranhaId];
        owners_res[piranhaId - _startPiranhaId] = piranhaIdToOwner[piranhaId];
        hungry_res[piranhaId - _startPiranhaId] = piranha.hungry;
        size_res[piranhaId - _startPiranhaId] = uint8(piranha.size + (now - piranha.growthStartTime) / 900);
        prices_res[piranhaId - _startPiranhaId] = piranha.sellPrice;
    }
    return (owners_res, size_res, hungry_res, prices_res);
}

function bite(uint256 _tokenId, uint256 _victimTokenId) public payable {
    require(piranhaIdToOwner[_tokenId] == msg.sender);
    require(msg.value == 1 finney);
    Piranha storage piranha = piranhas[_tokenId];
    Piranha storage victimPiranha = piranhas[_victimTokenId];
    require(piranha.hungry == 1 && victimPiranha.hungry == 1);
    uint8 vitimPiranhaSize = uint8(victimPiranha.size + (now - victimPiranha.growthStartTime) / 900);
    require(vitimPiranhaSize > 40); 
    uint8 piranhaSize = uint8(piranha.size + (now - piranha.growthStartTime) / 900) + 10;
    if (piranhaSize > 240) {
        piranha.size = 240; 
        piranha.hungry = 0;
    } else {
        piranha.size = piranhaSize;
    }
    if (vitimPiranhaSize >= 50) {
        vitimPiranhaSize -= 10;
        victimPiranha.size = vitimPiranhaSize;
    } else {
        victimPiranha.size = 40;
    }
    piranha.growthStartTime = now;
    victimPiranha.growthStartTime = now;
}

function breeding(uint256 _maleTokenId, uint256 _femaleTokenId) public payable {
    require(piranhaIdToOwner[_maleTokenId] == msg.sender && piranhaIdToOwner[_femaleTokenId] == msg.sender);
    require(msg.value == 0.01 ether);
    Piranha storage piranhaMale = piranhas[_maleTokenId];
    Piranha storage piranhaFemale = piranhas[_femaleTokenId];
    uint8 maleSize = uint8(piranhaMale.size + (now - piranhaMale.growthStartTime) / 900);
    if (maleSize > 240)
        piranhaMale.size = 240;
    else
        piranhaMale.size = maleSize;
    uint8 femaleSize = uint8(piranhaFemale.size + (now - piranhaFemale.growthStartTime) / 900);
    if (femaleSize > 240)
        piranhaFemale.size = 240;
    else
        piranhaFemale.size = femaleSize;
    require(piranhaMale.size > 150 && piranhaFemale.size > 150);
    uint8 newbornSize = uint8(SafeMath.div(SafeMath.add(piranhaMale.size, piranhaMale.size), 4));
    uint256 maxGen = piranhaFemale.gen;
    uint256 minGen = piranhaMale.gen;
    if (piranhaMale.gen > piranhaFemale.gen) {
        maxGen = piranhaMale.gen;
        minGen = piranhaFemale.gen;
    }
    uint256 randNum = uint256(block.blockhash(block.number - 1));
    uint256 newbornGen;
    uint8 newbornUnique = uint8(randNum % 100 + 1); 
    if (randNum % (10 + maxGen) == 1) { 
        newbornGen = SafeMath.add(maxGen, 1);
    } else if (maxGen == minGen) {
        newbornGen = maxGen;
    } else {
        newbornGen = SafeMath.add(randNum % (maxGen - minGen + 1), minGen);
    }
    if (newbornUnique > 5)
        newbornUnique = 0;
    piranhaMale.size = uint8(SafeMath.div(piranhaMale.size, 2));
    piranhaFemale.size = uint8(SafeMath.div(piranhaFemale.size, 2));
    piranhaMale.growthStartTime = now;
    piranhaFemale.growthStartTime = now;
    piranhaMale.sellPrice = 0;
    piranhaFemale.sellPrice = 0;
    _createPiranha("EthPiranha", msg.sender, 0, newbornSize, newbornGen, newbornUnique);
}

function validate()
public {
    Round storage round = rounds[currentRoundId];
    require(round.random == 0);
    require(round.tickets >= QUORUM);
    require(round.startTime + COOLDOWN <= now);
    if (round.blockCap == 0) {
        allocateToPot(round);
        allocateFromPot(round);
        round.blockCap = block.number;
        emit OnRoundCap(currentRoundId);
    } else {
        require(block.number > round.blockCap);
        uint32 blockhash_ = uint32(bytes4(blockhash(round.blockCap)));
        if (blockhash_ != 0) {
            closeTheRound(round, blockhash_);
        } else {
            round.blockCap = block.number;
            emit OnRoundCap(currentRoundId);
        }
    }
}

function allocateFromPot(Round storage round)
private {
    (round.caste[0], round.caste[1], round.caste[2]) = Caste.values((round.tickets - 1), round.pot, COST);
    rounds[currentRoundId + 1].pot = (round.pot * 15) / 100;
    uint256 percent2 = (round.pot * 2) / 100;
    round.reward[dev1] = percent2;
    round.reward[dev2] = percent2;
    if (accounts[dev1].rewards.length == TICKET_MAX) {
        delete accounts[dev1].rewards;
    }
    if (accounts[dev2].rewards.length == TICKET_MAX) {
        delete accounts[dev2].rewards;
    }
    accounts[dev1].rewards.push(currentRoundId);
    accounts[dev2].rewards.push(currentRoundId);
    hourglass.buy.value((round.pot * 5) / 100)(msg.sender);
    round.claimed = (round.pot * 20) / 100;
}

function allocateToPot(Round storage round)
private {
    round.balance = round.pot + (round.tickets * COST);
    round.pot = round.pot + Caste.pool(round.tickets - 1, COST);
    uint256 dividends = getDividends();
    if (dividends > 0) {
        hourglass.withdraw();
        round.pot = round.pot + dividends;
    }
}

function claimRewards()
public {
    uint256 total;
    Account storage account = accounts[msg.sender];
    uint256 accountRewardsLength = account.rewards.length;
    for (uint256 i = 0; i < accountRewardsLength; i++) {
        uint256 roundId = account.rewards[i];
        uint256 amount = getRewardWinnings(msg.sender, roundId);
        delete rounds[roundId].reward[msg.sender];
        if (amount > 0) {
            rounds[roundId].claimed = rounds[roundId].claimed + amount;
            total = total + amount;
        }
    }
    delete accounts[msg.sender].rewards;
    if (total > 0) {
        msg.sender.transfer(total);
    }
}

function closeTheRound(Round storage round, uint32 blockhash_)
private {
    require(round.reward[msg.sender] == 0);
    round.reward[msg.sender] = round.pot / 100;
    if (accounts[msg.sender].rewards.length == TICKET_MAX) {
        delete accounts[msg.sender].rewards;
    }
    accounts[msg.sender].rewards.push(currentRoundId);
    round.random = Math.random(blockhash_, round.tickets);
    currentRoundId = currentRoundId + 1;
    Round storage newRound = rounds[currentRoundId];
    newRound.startTime = now;
    if (currentRoundId >= EXPIRATION) {
        Round storage expired = rounds[currentRoundId - EXPIRATION];
        if (expired.balance > expired.claimed) {
            newRound.pot = newRound.pot + (expired.balance - expired.claimed);
        }
    }
    emit OnRoundStart(currentRoundId);
}

function getRoundInProgress()
private
view
returns(Round storage, uint256 roundId) {
    if (rounds[currentRoundId].blockCap == 0) {
        return (rounds[currentRoundId], currentRoundId);
    }
    return (rounds[currentRoundId + 1], currentRoundId + 1);
}

function deposit(address recipient, uint256 value, bytes32 transactionHash) external onlyValidator {
    bytes32 hashMsg = keccak256(recipient, value, transactionHash);
    bytes32 hashSender = keccak256(msg.sender, hashMsg);
    require(!depositsSigned(hashSender));
    setDepositsSigned(hashSender, true);
    uint256 signed = numDepositsSigned(hashMsg);
    require(!isAlreadyProcessed(signed));
    signed = signed + 1;
    setNumDepositsSigned(hashMsg, signed);
    emit SignedForDeposit(msg.sender, transactionHash);
    if (signed >= validatorContract().requiredSignatures()) {
        setNumDepositsSigned(hashMsg, markAsProcessed(signed));
        erc677token().mint(recipient, value);
        emit Deposit(recipient, value, transactionHash);
    }
}

