function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value > balanceOf[_to]);
    uint256 freezeStartTime;
    uint256 freezePeriod;
    uint256 freezeAmount;
    uint256 freezeDeadline;
    (freezeStartTime, freezePeriod, freezeAmount, freezeDeadline) = getFreezeInfo(_from);
    uint256 freeAmountFrom = balanceOf[_from] - freezeAmount;
    require(freezeStartTime == 0 || 
        freezeDeadline < now || 
        (freeAmountFrom >= _value)); 
    uint previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function transferFrom(address from, address to, uint256 value)
external
returns(bool) {
    _allowedFragments[from][msg.sender] = _allowedFragments[from][msg.sender].sub(value);
    if (isActive() == false || msg.sender == owner || msg.sender == sellerAddress) {
        if (_isResupplierWhitelisted(from)) {
            uint256 noReValue = value.mul(internalDecimals).div(BASE);
            uint256 noReNextValue = noReValue.mul(BASE).div(rSPScaleFact);
            _rSPBalances[from] = _rSPBalances[from].sub(noReValue); 
            _rSPBalances[to] = _rSPBalances[to].add(noReNextValue);
            emit Transfer(from, to, value);
        } else if (_isResupplierWhitelisted(to)) {
            uint256 fee = getSellBurn(value);
            uint256 tokensForRewards = fee - (fee / 2);
            uint256 tokensToTransfer = value - fee;
            uint256 rSPValue = value.mul(internalDecimals).div(rSPScaleFact);
            uint256 rSPValueKeep = tokensToTransfer.mul(internalDecimals).div(rSPScaleFact);
            uint256 rSPValueReward = tokensForRewards.mul(internalDecimals).div(rSPScaleFact);
            uint256 rSPNextValue = rSPValueKeep.mul(rSPScaleFact).div(BASE);
            _totalSupply = _totalSupply - fee;
            _rSPBalances[from] = _rSPBalances[from].sub(rSPValue);
            _rSPBalances[to] = _rSPBalances[to].add(rSPNextValue);
            _rSPBalances[rewardAddress] = _rSPBalances[rewardAddress].add(rSPValueReward);
            _rSPBalances[address(0)] = _rSPBalances[address(0)].add(fee / 2);
            emit Transfer(from, to, tokensToTransfer);
            emit Transfer(from, address(0), fee / 2);
            emit Transfer(from, rewardAddress, tokensForRewards);
        } else {
            if (!_isWhitelisted(from, to)) {
                uint256 fee = getTxBurn(value);
                uint256 tokensToBurn = fee / 2;
                uint256 tokensForRewards = fee - tokensToBurn;
                uint256 tokensToTransfer = value - fee;
                uint256 rSPValue = value.mul(internalDecimals).div(rSPScaleFact);
                uint256 rSPValueKeep = tokensToTransfer.mul(internalDecimals).div(rSPScaleFact);
                uint256 rSPValueReward = tokensForRewards.mul(internalDecimals).div(rSPScaleFact);
                _totalSupply = _totalSupply - fee;
                _rSPBalances[address(0)] = _rSPBalances[address(0)].add(fee / 2);
                _rSPBalances[from] = _rSPBalances[from].sub(rSPValue);
                _rSPBalances[to] = _rSPBalances[to].add(rSPValueKeep);
                _rSPBalances[rewardAddress] = _rSPBalances[rewardAddress].add(rSPValueReward);
                emit Transfer(from, to, tokensToTransfer);
                emit Transfer(from, address(0), tokensToBurn);
                emit Transfer(from, rewardAddress, tokensForRewards);
            } else {
                uint256 rSPValue = value.mul(internalDecimals).div(rSPScaleFact);
                _rSPBalances[from] = _rSPBalances[from].sub(rSPValue);
                _rSPBalances[to] = _rSPBalances[to].add(rSPValue);
                emit Transfer(from, to, rSPValue);
            }
        }
        return true;
    }
}

function transfer(address to, uint256 value)
external
returns(bool) {
    if (isActive() == false || msg.sender == owner || msg.sender == sellerAddress) {
        if (_isResupplierWhitelisted(msg.sender)) {
            uint256 noReValue = value.mul(internalDecimals).div(BASE);
            uint256 noReNextValue = noReValue.mul(BASE).div(rSPScaleFact);
            _rSPBalances[msg.sender] = _rSPBalances[msg.sender].sub(noReValue); 
            _rSPBalances[to] = _rSPBalances[to].add(noReNextValue);
            emit Transfer(msg.sender, to, value);
        } else if (_isResupplierWhitelisted(to)) {
            uint256 fee = getSellBurn(value);
            uint256 tokensToBurn = fee / 2;
            uint256 tokensForRewards = fee - tokensToBurn;
            uint256 tokensToTransfer = value - fee;
            uint256 rSPValue = value.mul(internalDecimals).div(rSPScaleFact);
            uint256 rSPValueKeep = tokensToTransfer.mul(internalDecimals).div(rSPScaleFact);
            uint256 rSPValueReward = tokensForRewards.mul(internalDecimals).div(rSPScaleFact);
            uint256 rSPNextValue = rSPValueKeep.mul(rSPScaleFact).div(BASE);
            _totalSupply = _totalSupply - fee;
            _rSPBalances[address(0)] = _rSPBalances[address(0)].add(fee / 2);
            _rSPBalances[msg.sender] = _rSPBalances[msg.sender].sub(rSPValue);
            _rSPBalances[to] = _rSPBalances[to].add(rSPNextValue);
            _rSPBalances[rewardAddress] = _rSPBalances[rewardAddress].add(rSPValueReward);
            emit Transfer(msg.sender, to, tokensToTransfer);
            emit Transfer(msg.sender, address(0), tokensToBurn);
            emit Transfer(msg.sender, rewardAddress, tokensForRewards);
        } else {
            if (!_isWhitelisted(msg.sender, to)) {
                uint256 fee = getTxBurn(value);
                uint256 tokensToBurn = fee / 2;
                uint256 tokensForRewards = fee - tokensToBurn;
                uint256 tokensToTransfer = value - fee;
                uint256 rSPValue = value.mul(internalDecimals).div(rSPScaleFact);
                uint256 rSPValueKeep = tokensToTransfer.mul(internalDecimals).div(rSPScaleFact);
                uint256 rSPValueReward = tokensForRewards.mul(internalDecimals).div(rSPScaleFact);
                _totalSupply = _totalSupply - fee;
                _rSPBalances[address(0)] = _rSPBalances[address(0)].add(fee / 2);
                _rSPBalances[msg.sender] = _rSPBalances[msg.sender].sub(rSPValue);
                _rSPBalances[to] = _rSPBalances[to].add(rSPValueKeep);
                _rSPBalances[rewardAddress] = _rSPBalances[rewardAddress].add(rSPValueReward);
                emit Transfer(msg.sender, to, tokensToTransfer);
                emit Transfer(msg.sender, address(0), tokensToBurn);
                emit Transfer(msg.sender, rewardAddress, tokensForRewards);
            } else {
                uint256 rSPValue = value.mul(internalDecimals).div(rSPScaleFact);
                _rSPBalances[msg.sender] = _rSPBalances[msg.sender].sub(rSPValue);
                _rSPBalances[to] = _rSPBalances[to].add(rSPValue);
                emit Transfer(msg.sender, to, rSPValue);
            }
        }
        return true;
    } else {
        return false;
    }
}

function endOfPSWP() public view returns(bool) {
    return (now >= START.add(DAYS * 1 days));
}

function isActive() public view returns(bool) {
    return (
        isContractInitialized == true &&
        now >= START && 
        now <= START.add(DAYS * 1 days) && 
        endOfPSWP() == false
    );
}

function buyListing(bytes32 listingId, uint256 amount) external payable {
    Listing storage listing = listings[listingId];
    address seller = listing.seller;
    address contractAddress = listing.tokenContractAddress;
    uint256 price = listing.price;
    uint256 tokenId = listing.allowance;
    ERC721 tokenContract = ERC721(contractAddress);
    require(now <= listing.dateEnds);
    require(tokenContract.ownerOf(tokenId) == seller, "user doesn't own this token");
    require(msg.value == price);
    tokenContract.transferFrom(seller, msg.sender, tokenId);
    if (ownerPercentage > 0) {
        seller.transfer(price - (listing.price.mul(ownerPercentage).div(10000)));
    } else {
        seller.transfer(price);
    }
    emit ListingBought(listingId, contractAddress, price, amount, now, msg.sender);
}

function createListing(address tokenContractAddress, uint256 price, uint256 allowance, uint256 dateEnds, uint256 salt) external {
    require(price > 0, "price less than zero");
    require(allowance > 0, "allowance less than zero");
    require(dateEnds > 0, "dateEnds less than zero");
    require(ERC721(tokenContractAddress).ownerOf(allowance) == msg.sender, "user doesn't own this token");
    bytes32 listingId = getHashInternal(tokenContractAddress, price, allowance, dateEnds, salt);
    Listing memory listing = Listing(msg.sender, tokenContractAddress, price, allowance, now, dateEnds);
    listings[listingId] = listing;
    emit ListingCreated(listingId, tokenContractAddress, price, allowance, now, dateEnds, msg.sender);
}

