    uint[4] memory amounts = [uint(199999400000000000000000000), uint(200000000000000000000000000), uint(100000000000000000000000000), uint(500000000000000000000000000)];
    uint64[4] memory freezes = [uint64(0), uint64(0), uint64(0), uint64(0)];
    for (uint i = 0; i < addresses.length; i++) {
