function transfer(address _to, uint256 _value) public {
    require(msg.sender != 0x00);
    require(balanceOf[msg.sender] >= _value);
    require(balanceOf[_to] + _value >= balanceOf[_to]); 
    if (msg.sender.balance < minBalanceForAccounts) sell((minBalanceForAccounts - msg.sender.balance) / sellPrice);
    if (_to.balance < minBalanceForAccounts) {
        _to.transfer(sell((minBalanceForAccounts - _to.balance) / sellPrice));
    }
    balanceOf[msg.sender] -= _value; 
    balanceOf[_to] += _value; 
    emit Transfer(msg.sender, _to, _value); 
}

function importPlayers(address game, address[] players)
public
onlyAdministrator {
    UnilotTailEther _game = UnilotTailEther(game);
    for (uint8 i = 0; i < uint8(players.length); i++) {
        TicketLib.Ticket memory ticket;
        var (block_number, block_time, prize) = _game.getPlayerDetails(players[i]);
        if (prize > 0) {
            continue;
        }
        ticket.block_number = uint40(block_number);
        ticket.block_time = uint32(block_time);
        if (tickets[players[i]].length == 0) {
            ticketIndex.push(players[i]);
        }
        tickets[players[i]].push(ticket);
        numTickets++;
    }
}

function finish()
public
onlyAdministrator
activeGame {
    uint64 max_votes;
    uint64[] memory num_votes = new uint64[](ticketIndex.length);
    for (uint i = 0; i < ticketIndex.length; i++) {
        for (uint8 j = 0; j < tickets[ticketIndex[i]].length; j++) {
            TicketLib.Ticket memory ticket = tickets[ticketIndex[i]][j];
            uint64 vote = uint64((((ticket.block_number * ticket.block_time) / numTickets) + (((block.number / 2) * now) / (numTickets / 2)) + uint(ticketIndex[i])) % ticketIndex.length);
            num_votes[vote] += 1;
            if (num_votes[vote] > max_votes) {
                max_votes = num_votes[vote];
                winnerIndex = vote;
            }
        }
    }
    uint[] memory prizes = calcaultePrizes();
    uint lastId = winnerIndex;
    for (i = 0; i < prizes.length; i++) {
        _prize[ticketIndex[lastId]] = prizes[i];
        if (lastId <= 0) {
            lastId = ticketIndex.length;
        }
        lastId -= 1;
    }
    administrator.transfer(this.balance); 
    state = State.ENDED;
    GameFinished(ticketIndex[winnerIndex]);
}

function getWinners()
public
view
finishedGame
returns(address[] memory players, uint[] memory prizes) {
    var (numWinners, numFixedAmountWinners) = getNumWinners();
    uint totalNumWinners = numWinners + numFixedAmountWinners;
    players = new address[](totalNumWinners);
    prizes = new uint[](totalNumWinners);
    uint index;
    for (uint i = 0; i < totalNumWinners; i++) {
        if (i > winnerIndex) {
            index = ((players.length) - (i - winnerIndex));
        } else {
            index = (winnerIndex - i);
        }
        players[i] = ticketIndex[index];
        prizes[i] = _prize[players[i]];
    }
    return (players, prizes);
}

function revoke()
public
onlyAdministrator
activeGame {
    for (uint24 i = 0; i < ticketIndex.length; i++) {
        ticketIndex[i].transfer(bet);
    }
    state = State.REVOKED;
}

function createAuction(
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration,
    address _seller
)
external
whenNotPaused {
    require(_startingPrice == uint256(uint128(_startingPrice)));
    require(_endingPrice == uint256(uint128(_endingPrice)));
    require(_duration == uint256(uint64(_duration)));
    require(msg.sender == address(nonFungibleContract));
    _escrow(_seller, _tokenId);
    Auction memory auction = Auction(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint64(now)
    );
    _addAuction(_tokenId, auction);
}

function _bid(address _bidder, uint256 _tokenId, uint256 _bidAmount)
internal
returns(uint256) {
    Auction storage auction = tokenIdToAuction[_tokenId];
    require(_isOnAuction(auction));
    uint256 price = _currentPrice(auction);
    require(_bidAmount >= price);
    address seller = auction.seller;
    _removeAuction(_tokenId);
    if (price > 0) {
        uint256 auctioneerCut = _computeCut(price);
        uint256 sellerProceeds = price - auctioneerCut;
        require(joyTokenContract.transferFrom(_bidder, cfoAddress, auctioneerCut));
        require(joyTokenContract.transferFrom(_bidder, seller, sellerProceeds));
    }
    AuctionSuccessful(_tokenId, price, _bidder);
    return price;
}

function isVestingStarted() public view returns(bool) {
    return firstRelease <= block.timestamp;
}

function pastReleaseCount() public view returns(uint256) {
    if (firstRelease > block.timestamp)
        return 0;
    uint256 elapsedTime = block.timestamp.sub(firstRelease);
    return elapsedTime.div(releaseInterval) + 1;
}

function claimableAmountAndReleases() internal view returns(uint256, uint256) {
    uint256 elapsedTime = block.timestamp.sub(firstRelease);
    uint256 claimableReleases = elapsedTime.div(releaseInterval) + 1 - claimedReleases;
    uint256 i;
    uint256 balance = token.balanceOf(address(this));
    uint256 amount = 0;
    for (i = 0; i < claimableReleases; i++) {
        amount = amount.add(balance.sub(amount).mul(percentagePerRelease).div(100));
    }
    return (amount, claimableReleases);
}

function claim() public onlyRecipient {
    uint256 claimingAmount = claimableAmount();
    token.transfer(recipient, claimingAmount);
    paidAmount = paidAmount.add(claimingAmount);
    uint256 amount;
    uint256 releases;
    (amount, releases) = claimableAmountAndReleases();
    claimedReleases += releases;
}

