        msg.sender.transfer(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function DoVoterPayout(Music musicObj) private {
    uint j = 0;
    voters = musicVoterList[musicObj.musicId];
    localIntAsPerNeed = voteMusicPayoutSchemeObj.voterPercentage;
    uint voterPayout = musicObj.amountToBePaid.mul(localIntAsPerNeed);
    voterPayout = voterPayout.div(100);
    uint perVoterPayout = voterPayout.div(voters.length);
    localIntAsPerNeed = voteMusicPayoutSchemeObj.musicianPercentage;
    uint musicianPayout = musicObj.amountToBePaid.mul(localIntAsPerNeed);
    musicianPayout = musicianPayout.div(100);
    localIntAsPerNeed = voteMusicPayoutSchemeObj.systemPercentage;
    uint systemPayout = musicObj.amountToBePaid.mul(localIntAsPerNeed);
    systemPayout = systemPayout.div(100);
    for (j = 0; j < voters.length; j++) {
        token.mint(wallet, voters[j].publicKey, perVoterPayout);
        voters[j].amountEarned = voters[j].amountEarned.add(perVoterPayout);
        musicObj.amountToBePaid = musicObj.amountToBePaid.sub(perVoterPayout);
    }
    token.mint(wallet, musicObj.musician, musicianPayout);
    musicObj.amountToBePaid = musicObj.amountToBePaid.sub(musicianPayout);
    musicObj.amountToBePaid = musicObj.amountToBePaid.sub(systemPayout);
    require(musicObj.amountToBePaid == 0);
}

function DownloadMusic(uint musId, address senderId, uint tokenAmount) public returns(bool goAhead) {
    require(msg.sender == wallet);
    require(musicList[musId].musicId == musId);
    require(musicList[musId].isUnlocked == true);
    token.mint(senderId, wallet, tokenAmount * 10 ** 18);
    musicList[musId].totalEarning = musicList[musId].totalEarning.add(tokenAmount);
    musicList[musId].amountToBePaid = musicList[musId].amountToBePaid.add(tokenAmount);
    goAhead = true;
}

function SponsorMusic(uint musId, uint sponsorAmount, address sponsorAddress) public {
    sponsorAmount = sponsorAmount * 10 ** 18;
    require(token.balanceOf(sponsorAddress) > sponsorAmount);
    require(musicList[musId].musicId == musId);
    require(musicList[musId].isUnlocked == false);
    require(musicList[musId].marketType == false);
    require(musicList[musId].amountLeftForUnlock >= sponsorAmount);
    token.mint(sponsorAddress, wallet, sponsorAmount);
    musicList[musId].amountLeftForUnlock = musicList[musId].amountLeftForUnlock.sub(sponsorAmount);
    musicList[musId].amountToBePaid = musicList[musId].amountToBePaid.add(sponsorAmount);
    sponsor = Sponsor({
        publicKey: msg.sender,
        amountEarned: 0,
        amountPaid: sponsorAmount
    });
    musicSponsorList[musId].push(sponsor);
    if (musicList[musId].amountLeftForUnlock == 0) {
        musicList[musId].isUnlocked = true;
    }
}

function DoSponsorPayout(Music musicObj) private {
    localIntAsPerNeed = musicObj.musicId;
    sponsors = musicSponsorList[localIntAsPerNeed];
    localIntAsPerNeed = sponsorPayoutSchemeObj.sponsorPercentage;
    uint sponsorPayout = musicObj.amountToBePaid.mul(localIntAsPerNeed);
    sponsorPayout = sponsorPayout.div(100);
    voters = musicVoterList[musicObj.musicId];
    localIntAsPerNeed = sponsorPayoutSchemeObj.voterPercentage;
    uint voterPayout = musicObj.amountToBePaid.mul(localIntAsPerNeed);
    voterPayout = voterPayout.div(100);
    localIntAsPerNeed = sponsorPayoutSchemeObj.musicianPercentage;
    uint musicianPayout = musicObj.amountToBePaid.mul(localIntAsPerNeed);
    musicianPayout = musicianPayout.div(100);
    localIntAsPerNeed = sponsorPayoutSchemeObj.systemPercentage;
    uint systemPayout = musicObj.amountToBePaid.mul(localIntAsPerNeed);
    systemPayout = systemPayout.div(100);
    for (counter = 0; counter < sponsors.length; counter++) {
        localIntAsPerNeed = sponsors[counter].amountPaid.mul(100);
        localIntAsPerNeed = localIntAsPerNeed.div(musicObj.totalAmountForUnlock);
        uint amtToSend = sponsorPayout.mul(localIntAsPerNeed);
        amtToSend = amtToSend.div(100);
        token.mint(wallet, sponsors[counter].publicKey, amtToSend);
        sponsors[counter].amountEarned = sponsors[counter].amountEarned.add(amtToSend);
        musicObj.amountToBePaid = musicObj.amountToBePaid.sub(amtToSend);
    }
    if (voters.length > 0) {
        uint perVoterPayout = voterPayout.div(voters.length);
        for (counter = 0; counter < voters.length; counter++) {
            token.mint(wallet, voters[counter].publicKey, perVoterPayout);
            voters[counter].amountEarned = voters[counter].amountEarned.add(perVoterPayout);
            musicObj.amountToBePaid = musicObj.amountToBePaid.sub(perVoterPayout);
        }
    } else {
        musicObj.amountToBePaid = musicObj.amountToBePaid.sub(voterPayout);
    }
    localAddressAsPerNeed = musicObj.musician;
    token.mint(wallet, localAddressAsPerNeed, musicianPayout);
    musicObj.amountToBePaid = musicObj.amountToBePaid.sub(musicianPayout);
    musicObj.amountToBePaid = musicObj.amountToBePaid.sub(systemPayout);
    require(musicObj.amountToBePaid == 0);
}

function DoMusicPayout(uint musId) public {
    require(msg.sender == wallet);
    require(musicList[musId].musicId == musId);
    require(musicList[musId].isUnlocked == true);
    require(musicList[musId].amountToBePaid > 0);
    require(token.balanceOf(wallet) >= musicList[musId].amountToBePaid);
    bool unlock = musicList[musId].marketType;
    if (unlock == false) {
        DoSponsorPayout(musicList[musId]);
        musicList[musId].amountToBePaid = 0;
    } else {
        DoVoterPayout(musicList[musId]);
        musicList[musId].amountToBePaid = 0;
    }
}

function UploadMusic(uint muId, string lnk, address muPublicKey, bool unlocktype, uint amount, uint uploadTokenAmount) public {
    require(msg.sender == wallet);
    token.mint(muPublicKey, wallet, uploadTokenAmount * 10 ** 18); 
    require(musicList[muId].musicId == 0);
    music = Music({
        musician: muPublicKey,
        musicId: muId,
        musicLink: lnk,
        marketType: unlocktype,
        totalEarning: 0,
        totalAmountForUnlock: amount * 10 ** 18,
        amountLeftForUnlock: amount * 10 ** 18,
        amountToBePaid: uploadTokenAmount * 10 ** 18,
        isUnlocked: false
    });
    musicList[muId] = music;
}

function distributeExternal(uint256 _rID, uint256 _pID, uint256 _eth, uint256 _affID, uint256 _team, F3GDatasets.EventReturns memory _eventData_)
private returns(F3GDatasets.EventReturns) {
    uint256 _comm = (_eth.mul(3)).div(100);
    if (_comm > 0) {
        commAddr_.transfer(_comm);
    }
    distributeRef(_eth, _affID);
    uint256 _partner = (_eth.mul(2)).div(100);
    partnerAddr_.transfer(_partner);
    uint256 _dev = (_eth.mul(fees_[_team].dev)).div(100);
    if (_dev > 0) {
        devAddr_.transfer(_dev);
    }
    return (_eventData_);
}

function buyCore(uint256 _pID, uint256 _affID, uint256 _team, F3GDatasets.EventReturns memory _eventData_) private {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now > round_[_rID].strt && (_now <= round_[_rID].end || (_now > round_[_rID].end && round_[_rID].plyr == 0))) {
        core(_rID, _pID, msg.value, _affID, _team, _eventData_);
    } else {
        if (_now > round_[_rID].end && round_[_rID].ended == false) {
            round_[_rID].ended = true;
            _eventData_ = endRound(_eventData_);
            _eventData_.compressedData = _eventData_.compressedData + (_now * 1000000000000000000);
            _eventData_.compressedIDs = _eventData_.compressedIDs + _pID;
            emit onBuyAndDistribute(
                msg.sender,
                plyr_[_pID].name,
                msg.value,
                _eventData_.compressedData,
                _eventData_.compressedIDs,
                _eventData_.winnerAddr,
                _eventData_.winnerName,
                _eventData_.amountWon,
                _eventData_.newPot,
                _eventData_.R3Amount,
                _eventData_.genAmount
            );
        }
        plyr_[_pID].gen = plyr_[_pID].gen.add(msg.value);
    }
}

function reLoadCore(uint256 _pID, uint256 _affID, uint256 _team, uint256 _eth, F3GDatasets.EventReturns memory _eventData_) private {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_now > round_[_rID].strt && (_now <= round_[_rID].end || (_now > round_[_rID].end && round_[_rID].plyr == 0))) {
        plyr_[_pID].gen = withdrawEarnings(_pID).sub(_eth);
        core(_rID, _pID, _eth, _affID, _team, _eventData_);
    } else if (_now > round_[_rID].end && round_[_rID].ended == false) {
        round_[_rID].ended = true;
        _eventData_ = endRound(_eventData_);
        _eventData_.compressedData = _eventData_.compressedData + (_now * 1000000000000000000);
        _eventData_.compressedIDs = _eventData_.compressedIDs + _pID;
        emit onReLoadAndDistribute(
            msg.sender,
            plyr_[_pID].name,
            _eventData_.compressedData,
            _eventData_.compressedIDs,
            _eventData_.winnerAddr,
            _eventData_.winnerName,
            _eventData_.amountWon,
            _eventData_.newPot,
            _eventData_.R3Amount,
            _eventData_.genAmount
        );
    }
}

function withdraw() isActivated() isHuman() public {
    uint256 _rID = rID_;
    uint256 _now = now;
    uint256 _pID = pIDxAddr_[msg.sender];
    uint256 _eth;
    if (_now > round_[_rID].end && (round_[_rID].ended == false) && round_[_rID].plyr != 0) {
        F3GDatasets.EventReturns memory _eventData_;
        round_[_rID].ended = true;
        _eventData_ = endRound(_eventData_);
        _eth = withdrawEarnings(_pID);
        if (_eth > 0)
            plyr_[_pID].addr.transfer(_eth);
        _eventData_.compressedData = _eventData_.compressedData + (_now * 1000000000000000000);
        _eventData_.compressedIDs = _eventData_.compressedIDs + _pID;
        emit onWithdrawAndDistribute(
            msg.sender,
            plyr_[_pID].name,
            _eth,
            _eventData_.compressedData,
            _eventData_.compressedIDs,
            _eventData_.winnerAddr,
            _eventData_.winnerName,
            _eventData_.amountWon,
            _eventData_.newPot,
            _eventData_.R3Amount,
            _eventData_.genAmount
        );
    } else {
        _eth = withdrawEarnings(_pID);
        if (_eth > 0)
            plyr_[_pID].addr.transfer(_eth);
        emit onWithdraw(
            _pID,
            msg.sender,
            plyr_[_pID].name,
            _eth,
            _now
        );
    }
}

function core(uint256 _rID, uint256 _pID, uint256 _eth, uint256 _affID, uint256 _team, F3GDatasets.EventReturns memory _eventData_) private {
    if (plyrRnds_[_pID][_rID].keys == 0)
        _eventData_ = managePlayer(_pID, _eventData_);
    if (round_[_rID].eth < 100000000000000000000 && plyrRnds_[_pID][_rID].eth.add(_eth) > 5000000000000000000) {
        uint256 _availableLimit = (5000000000000000000).sub(plyrRnds_[_pID][_rID].eth);
        uint256 _refund = _eth.sub(_availableLimit);
        plyr_[_pID].gen = plyr_[_pID].gen.add(_refund);
        _eth = _availableLimit;
    }
    if (_eth > 1000000000) {
        uint256 _keys = (round_[_rID].eth).keysRec(_eth);
        if (_keys >= 1000000000000000000) {
            updateTimer(_keys, _rID);
            if (round_[_rID].plyr != _pID)
                round_[_rID].plyr = _pID;
            if (round_[_rID].team != _team)
                round_[_rID].team = _team;
            _eventData_.compressedData = _eventData_.compressedData + 100;
        }
        if (_eth >= 100000000000000000) {
            airDropTracker_++;
            if (airdrop() == true) {
                uint256 _prize;
                if (_eth >= 10000000000000000000) {
                    _prize = ((airDropPot_).mul(75)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                    _eventData_.compressedData += 300000000000000000000000000000000;
                } else if (_eth >= 1000000000000000000 && _eth < 10000000000000000000) {
                    _prize = ((airDropPot_).mul(50)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                    _eventData_.compressedData += 200000000000000000000000000000000;
                } else if (_eth >= 100000000000000000 && _eth < 1000000000000000000) {
                    _prize = ((airDropPot_).mul(25)) / 100;
                    plyr_[_pID].win = (plyr_[_pID].win).add(_prize);
                    airDropPot_ = (airDropPot_).sub(_prize);
                    _eventData_.compressedData += 300000000000000000000000000000000;
                }
                _eventData_.compressedData += 10000000000000000000000000000000;
                _eventData_.compressedData += _prize * 1000000000000000000000000000000000;
                airDropTracker_ = 0;
            }
        }
        _eventData_.compressedData = _eventData_.compressedData + (airDropTracker_ * 1000);
        plyrRnds_[_pID][_rID].keys = _keys.add(plyrRnds_[_pID][_rID].keys);
        plyrRnds_[_pID][_rID].eth = _eth.add(plyrRnds_[_pID][_rID].eth);
        round_[_rID].keys = _keys.add(round_[_rID].keys);
        round_[_rID].eth = _eth.add(round_[_rID].eth);
        rndTmEth_[_rID][_team] = _eth.add(rndTmEth_[_rID][_team]);
        _eventData_ = distributeExternal(_rID, _pID, _eth, _affID, _team, _eventData_);
        _eventData_ = distributeInternal(_rID, _pID, _eth, _team, _keys, _eventData_);
        endTx(_pID, _team, _eth, _keys, _eventData_);
    }
}

function endRound(F3GDatasets.EventReturns memory _eventData_) private returns(F3GDatasets.EventReturns) {
    uint256 _rID = rID_;
    uint256 _winPID = round_[_rID].plyr;
    uint256 _winTID = round_[_rID].team;
    uint256 _pot = round_[_rID].pot.add(round_[_rID].prevres);
    uint256 _win = (_pot.mul(48)) / 100;
    uint256 _com = (_pot.mul(3)) / 100;
    uint256 _gen = (_pot.mul(potSplit_[_winTID].gen)) / 100;
    uint256 _dev = (_pot.mul(potSplit_[_winTID].dev)) / 100;
    uint256 _res = (((_pot.sub(_win)).sub(_com)).sub(_gen)).sub(_dev);
    uint256 _ppt = (_gen.mul(1000000000000000000)) / (round_[_rID].keys);
    uint256 _dust = _gen.sub((_ppt.mul(round_[_rID].keys)) / 1000000000000000000);
    if (_dust > 0) {
        _gen = _gen.sub(_dust);
        _res = _res.add(_dust);
    }
    plyr_[_winPID].win = _win.add(plyr_[_winPID].win);
    if (_com > 0) {
        commAddr_.transfer(_com);
        _com = 0;
    }
    if (_dev > 0) {
        devAddr_.transfer(_dev);
    }
    round_[_rID].mask = _ppt.add(round_[_rID].mask);
    _eventData_.compressedData = _eventData_.compressedData + (round_[_rID].end * 1000000);
    _eventData_.compressedIDs = _eventData_.compressedIDs + (_winPID * 100000000000000000000000000) + (_winTID * 100000000000000000);
    _eventData_.winnerAddr = plyr_[_winPID].addr;
    _eventData_.winnerName = plyr_[_winPID].name;
    _eventData_.amountWon = _win;
    _eventData_.genAmount = _gen;
    _eventData_.R3Amount = 0;
    _eventData_.newPot = _res;
    rID_++;
    _rID++;
    round_[_rID].strt = now;
    round_[_rID].end = now.add(rndMax_);
    round_[_rID].prevres = _res;
    return (_eventData_);
}

function getTimeLeft() public view returns(uint256) {
    uint256 _rID = rID_;
    uint256 _now = now;
    if (_rID == 1 && _now < round_[_rID].strt) return (0);
    if (_now < round_[_rID].end)
        if (_now > round_[_rID].strt)
            return ((round_[_rID].end).sub(_now));
        else
            return ((round_[_rID].end).sub(_now));
    else
        return (0);
}

function getCurrentRoundInfo() public view
returns(uint256, uint256, uint256, uint256, uint256, uint256, uint256, address, bytes32, uint256, uint256, uint256, uint256, uint256) {
    uint256 _rID = rID_;
    return (
        round_[_rID].ico,
        _rID,
        round_[_rID].keys,
        ((_rID == 1) && (now < round_[_rID].strt)) ? 0 : round_[_rID].end,
        ((_rID == 1) && (now < round_[_rID].strt)) ? 0 : round_[_rID].strt,
        round_[_rID].pot,
        (round_[_rID].team + (round_[_rID].plyr * 10)),
        plyr_[round_[_rID].plyr].addr,
        plyr_[round_[_rID].plyr].name,
        rndTmEth_[_rID][0],
        rndTmEth_[_rID][1],
        rndTmEth_[_rID][2],
        rndTmEth_[_rID][3],
        airDropTracker_ + (airDropPot_ * 1000)
    );
}

function claim(
    address tokenContractAddress,
    uint tokenId,
    uint gemsReward,
    uint creditsReward,
    uint blockNumber,
    uint amountToWithdraw,
    bytes32 uuid,
    bytes calldata signature
) external onlyEnabled {
    cargoData.verifySigAndUuid(keccak256(
        abi.encodePacked(
            "CLAIM",
            tokenContractAddress,
            tokenId,
            gemsReward,
            creditsReward,
            amountToWithdraw,
            blockNumber,
            uuid
        )
    ), signature, uuid);
    IStakingErc721 erc721 = IStakingErc721(tokenContractAddress);
    require(erc721.ownerOf(tokenId) == msg.sender, "Staking: Sender not owner");
    require(tokenStakes[tokenContractAddress][tokenId].lastBlockClaimed < blockNumber, "Staking: block number invalid");
    tokenStakes[tokenContractAddress][tokenId].amount = tokenStakes[tokenContractAddress][tokenId].amount.add(gemsReward);
    totalStaked = totalStaked.add(gemsReward);
    if (amountToWithdraw > 0) {
        require(amountToWithdraw <= tokenStakes[tokenContractAddress][tokenId].amount, "Staking: Withdrawl amount must be lte staked amount");
        cargoGems.transfer(msg.sender, amountToWithdraw);
        tokenStakes[tokenContractAddress][tokenId].amount = tokenStakes[tokenContractAddress][tokenId].amount.sub(amountToWithdraw);
        totalStaked = totalStaked.sub(amountToWithdraw);
    }
    cargoCredits.increaseBalance(msg.sender, creditsReward);
    tokenStakes[tokenContractAddress][tokenId].lastBlockClaimed = block.number;
    emit Claim(msg.sender, tokenContractAddress, tokenId, gemsReward, creditsReward);
    emit TotalStakeUpdated(totalStaked);
    emit TokenStakeUpdated(
        tokenContractAddress,
        tokenId,
        tokenStakes[tokenContractAddress][tokenId].amount,
        !tokenStakes[tokenContractAddress][tokenId].exists
    );
}

function stake(address tokenContractAddress, uint tokenId, uint amountToStake) external onlyEnabled {
    require(amountToStake > 0, "Staking: Amount must be gt 0");
    if (config["onlyCargoContracts"]) {
        require(cargoData.verifyContract(tokenContractAddress), "Staking: Must be a cargo contract");
    }
    IStakingErc721 erc721 = IStakingErc721(tokenContractAddress);
    require(
        (erc721.supportsInterface(0x80ac58cd) || whiteList[tokenContractAddress]) &&
        !blackList[tokenContractAddress],
        "Staking: 721 not supported"
    );
    require(erc721.ownerOf(tokenId) == msg.sender, "Staking: Sender not owner");
    cargoGems.transferFrom(msg.sender, address(this), amountToStake);
    tokenStakes[tokenContractAddress][tokenId].amount = tokenStakes[tokenContractAddress][tokenId].amount.add(amountToStake);
    totalStaked = totalStaked.add(amountToStake);
    emit TotalStakeUpdated(totalStaked);
    emit TokenStakeUpdated(
        tokenContractAddress,
        tokenId,
        tokenStakes[tokenContractAddress][tokenId].amount,
        !tokenStakes[tokenContractAddress][tokenId].exists
    );
    if (!tokenStakes[tokenContractAddress][tokenId].exists) {
        tokenStakes[tokenContractAddress][tokenId].genesisBlock = block.number;
        tokenStakes[tokenContractAddress][tokenId].exists = true;
    }
}

function transfer(address _toAddress, uint256 _amountOfTokens) onlyBagholders() public returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFee = calculateDividends_(_amountOfTokens);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

function multiSendEth(
    uint256 amount,
    address[] list
)
external
returns(bool) {
    uint256 totalList = list.length;
    uint256 totalAmount = amount.mul(totalList);
    require(address(this).balance > totalAmount);
    for (uint256 i = 0; i < list.length; i++) {
        require(list[i] != address(0));
        require(list[i].send(amount));
        emit Send(amount, list[i]);
    }
    return true;
}

function buyTokens(address _beneficiary) public payable whenNotStopped {
    uint256 weiAmount = msg.value;
    require(_beneficiary != address(0));
    require(weiAmount != 0);
    weiRaised = weiRaised.add(weiAmount);
    require(weiRaised <= cap);
    uint256 dollars = _getUsdAmount(weiAmount);
    uint256 tokens = _getTokenAmount(dollars);
    uint256 previousEthBalance = ethBalances[_beneficiary];
    ethBalances[_beneficiary] = ethBalances[_beneficiary].add(weiAmount);
    elpBalances[_beneficiary] = elpBalances[_beneficiary].add(tokens);
    tokensSold = tokensSold.add(tokens);
    usdRaised = usdRaised.add(dollars);
    if (ethBalances[_beneficiary] > threshold) {
        whitelist[_beneficiary] = false;
        if (previousEthBalance < threshold)
            wallet.transfer(threshold - previousEthBalance);
        emit NeedKyc(_beneficiary, weiAmount, ethBalances[_beneficiary]);
    } else {
        whitelist[_beneficiary] = true;
        wallet.transfer(weiAmount);
        emit Contribution(_beneficiary, weiAmount, ethBalances[_beneficiary]);
    }
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens);
}

function withdraw() external whenWithdrawalEnabled {
    uint256 ethBalance = ethBalances[msg.sender];
    require(ethBalance > 0);
    uint256 elpBalance = elpBalances[msg.sender];
    elpBalances[msg.sender] = 0;
    ethBalances[msg.sender] = 0;
    if (isWhitelisted(msg.sender)) {
        token.transfer(msg.sender, elpBalance);
    } else {
        token.transfer(msg.sender, elpBalance.mul(threshold).div(ethBalance));
        if (ethBalance > threshold) {
            msg.sender.transfer(ethBalance - threshold);
        }
    }
    emit Withdrawal(msg.sender, ethBalance, elpBalance);
}

function addWorks(
    bytes32 _worksID,
    bytes32 _artistID,
    uint8 _debrisNum,
    uint256 _price,
    uint256 _beginTime
)
external
onlyAdmin()
whenNotHasWorks(_worksID)
whenHasArtist(_artistID) {
    require(
        _debrisNum >= 2 && _debrisNum < 256 &&
        _price > 0 && _price % _debrisNum == 0 &&
        _beginTime > 0 && _beginTime > now
    );
    works[_worksID] = Datasets.Works(
        _worksID,
        _artistID,
        _debrisNum,
        _price.mul(1 wei),
        _beginTime,
        0,
        false,
        bytes32(0)
    );
    emit OnAddWorks(
        _worksID,
        _artistID,
        _debrisNum,
        _price,
        _beginTime,
        false
    );
    initDebris(_worksID, _price, _debrisNum);
}

function getDebrisPrice(bytes32 _worksID, uint8 _debrisID) external view returns(uint256) {
    uint256 discountGap = rules[_worksID].discountGap;
    uint256 discountRatio = rules[_worksID].discountRatio;
    uint256 increaseRatio = rules[_worksID].increaseRatio;
    uint256 lastPrice;
    if (debris[_worksID][_debrisID].buyNum > 0 && debris[_worksID][_debrisID].lastTime.add(discountGap) < now) {
        uint256 n = (now.sub(debris[_worksID][_debrisID].lastTime.add(discountGap))) / discountGap;
        if ((now.sub(debris[_worksID][_debrisID].lastTime.add(discountGap))) % discountGap > 0) {
            n = n.add(1);
        }
        for (uint256 i = 0; i < n; i++) {
            if (0 == i) {
                lastPrice = debris[_worksID][_debrisID].lastPrice.mul(increaseRatio).mul(discountRatio) / 10000;
            } else {
                lastPrice = lastPrice.mul(discountRatio) / 100;
            }
        }
    } else if (debris[_worksID][_debrisID].buyNum > 0) {
        lastPrice = debris[_worksID][_debrisID].lastPrice.mul(increaseRatio) / 100;
    } else {
        lastPrice = debris[_worksID][_debrisID].initPrice;
    }
    return lastPrice;
}

function publish(bytes32 _worksID, uint256 _beginTime) external onlyAdmin() {
    require(works[_worksID].beginTime != 0 && works[_worksID].isPublish == false);
    require(this.getAllot(_worksID, 0, 0) != 0);
    if (_beginTime > 0) {
        require(_beginTime > now);
        works[_worksID].beginTime = _beginTime;
    }
    works[_worksID].isPublish = true;
}

function isStart(bytes32 _worksID) external view returns(bool) {
    return works[_worksID].beginTime <= now;
}

function getDebrisStatus(bytes32 _worksID, uint8 _debrisID) external view returns(uint256[4] memory, uint256, uint256, bytes32) {
    uint256 gap = 0;
    uint256 status = 0;
    if (0 == debris[_worksID][_debrisID].buyNum) {
    } else if (this.isProtect(_worksID, _debrisID)) {
        gap = rules[_worksID].protectGap;
        status = 1;
    } else {
        if (debris[_worksID][_debrisID].lastTime.add(rules[_worksID].discountGap) > now) {
            gap = rules[_worksID].discountGap;
        } else {
            uint256 n = (now.sub(debris[_worksID][_debrisID].lastTime)) / rules[_worksID].discountGap;
            if ((now.sub(debris[_worksID][_debrisID].lastTime.add(rules[_worksID].discountGap))) % rules[_worksID].discountGap > 0) {
                n = n.add(1);
            }
            gap = rules[_worksID].discountGap.mul(n);
        }
        status = 2;
    }
    uint256 price = this.getDebrisPrice(_worksID, _debrisID);
    bytes32 lastUnionID = debris[_worksID][_debrisID].lastUnionID;
    uint256[4] memory state = [status, debris[_worksID][_debrisID].lastTime, gap, now];
    return (state, price, debris[_worksID][_debrisID].buyNum, lastUnionID);
}

function getStartHourglass(bytes32 _worksID) external view returns(uint256) {
    if (works[_worksID].beginTime > 0 && works[_worksID].beginTime > now) {
        return works[_worksID].beginTime.sub(now);
    }
    return 0;
}

function getProtectHourglass(bytes32 _worksID, uint8 _debrisID) external view returns(uint256) {
    if (
        debris[_worksID][_debrisID].lastTime > 0 &&
        debris[_worksID][_debrisID].lastTime.add(rules[_worksID].protectGap) > now
    ) {
        return debris[_worksID][_debrisID].lastTime.add(rules[_worksID].protectGap).sub(now);
    }
    return 0;
}

function isProtect(bytes32 _worksID, uint8 _debrisID) external view returns(bool) {
    if (debris[_worksID][_debrisID].lastTime == 0) {
        return false;
    }
    uint256 protectGap = rules[_worksID].protectGap;
    return debris[_worksID][_debrisID].lastTime.add(protectGap) < now ? false : true;
}

function getDiscountHourglass(bytes32 _worksID, uint8 _debrisID) external view returns(uint256) {
    if (debris[_worksID][_debrisID].lastTime == 0) {
        return 0;
    }
    uint256 discountGap = rules[_worksID].discountGap;
    uint256 n = (now.sub(debris[_worksID][_debrisID].lastTime)) / discountGap;
    if ((now.sub(debris[_worksID][_debrisID].lastTime)) % discountGap > 0) {
        n = n.add(1);
    }
    return debris[_worksID][_debrisID].lastTime.add(discountGap.mul(n)).sub(now);
}

function updateEndTime(uint256 newTime) onlyOwner external {
    require(newTime > startTime);
    endTime = newTime;
    EndTimeUpdated();
}

function releaseDragonTokens() public {
    require(balances[msg.sender] > 0);
    uint256 amount = 0;
    for (uint8 i = 0; i < ledger[msg.sender].releaseTime.length; i++) {
        uint256 time = ledger[msg.sender].releaseTime[i];
        if (now >= time && ledger[msg.sender].balance[time] > 0) {
            amount = ledger[msg.sender].balance[time];
            ledger[msg.sender].balance[time] = 0;
            continue;
        }
    }
    if (amount <= 0 || balances[msg.sender] < amount) {
        revert();
    }
    balances[msg.sender] = balances[msg.sender].sub(amount);
    if (!token.transferFrom(tokenReserve, msg.sender, amount)) {
        revert();
    }
    TokenReleased(msg.sender, amount);
}

function finalizeNOK() onlyOwner public {
    require(state == State.Running);
    require(ended());
    token.finishMinting();
    token.enableTokenBurn();
    vault.enableRefunds();
    state = State.Failure;
    FinalizedNOK();
}

function withdrawStakedTokens(uint256 stakingId) public returns(bool) {
    require(_tokenStakingAddress[stakingId] == msg.sender, "No staked token found on this address and ID");
    require(_TokenTransactionstatus[stakingId] != true, "Either tokens are already withdrawn or blocked by admin");
    if (_tokenTotalDays[stakingId] == PERIOD_SILVER) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_SILVER, "Unable to Withdraw Staked token before 45 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            ilptoken.transfer(msg.sender, _usersTokens[stakingId]);
            itoken.transfer(msg.sender, getTokenRewardDetailsByStakingId(stakingId));
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenRewardDetailsByStakingId(stakingId));
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            ilptoken.transfer(msg.sender, _usersTokens[stakingId]);
            itoken.transfer(msg.sender, getTokenPenaltyDetailByStakingId(stakingId));
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenPenaltyDetailByStakingId(stakingId));
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_GOLD) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_GOLD, "Unable to Withdraw Staked token before 90 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            ilptoken.transfer(msg.sender, _usersTokens[stakingId]);
            itoken.transfer(msg.sender, getTokenRewardDetailsByStakingId(stakingId));
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenRewardDetailsByStakingId(stakingId));
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            ilptoken.transfer(msg.sender, _usersTokens[stakingId]);
            itoken.transfer(msg.sender, getTokenPenaltyDetailByStakingId(stakingId));
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenPenaltyDetailByStakingId(stakingId));
        }
    } else if (_tokenTotalDays[stakingId] == PERIOD_PLATINUM) {
        require(now >= _tokenStakingStartTime[stakingId] + WITHDRAW_TIME_PLATINUM, "Unable to Withdraw Staked token before 135 days of staking start time, Please Try Again Later!!!");
        _TokenTransactionstatus[stakingId] = true;
        if (now >= _tokenStakingEndTime[stakingId]) {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenRewardDetailsByStakingId(stakingId));
            ilptoken.transfer(msg.sender, _usersTokens[stakingId]);
            itoken.transfer(msg.sender, getTokenRewardDetailsByStakingId(stakingId));
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenRewardDetailsByStakingId(stakingId));
        } else {
            _finalTokenStakeWithdraw[stakingId] = _usersTokens[stakingId].add(getTokenPenaltyDetailByStakingId(stakingId));
            ilptoken.transfer(msg.sender, _usersTokens[stakingId]);
            itoken.transfer(msg.sender, getTokenPenaltyDetailByStakingId(stakingId));
            totalTokenStakesInContract = totalTokenStakesInContract.sub(_usersTokens[stakingId]);
            _ownerTokenAllowance = _ownerTokenAllowance.sub(getTokenPenaltyDetailByStakingId(stakingId));
        }
    } else {
        return false;
    }
    return true;
}

function SetRoundTime(uint256 p) public {
    require(msg.sender == owner);
    require(!Open() && (Winner == 0x0));
    RoundTime = p;
}

function BuyIn() public payable {
    require(msg.value == Price);
    if (now > RoundEndTime) {
        bool started = CheckGameStart(true);
        require(started);
        GasPrice = tx.gasprice;
        emit NewGameLeader(msg.sender, GasPrice, address(this).balance + (Price * 95) / 100);
    } else {
        if (tx.gasprice > GasPrice) {
            GasPrice = tx.gasprice;
            Winner = msg.sender;
            emit NewGameLeader(msg.sender, GasPrice, address(this).balance + (Price * 95) / 100);
        }
    }
    owner.transfer((msg.value * 500) / 10000); 
    emit NewTX(address(this).balance + (Price * 95) / 100);
}

function NextOpen() public view returns(uint256, uint256) {
    uint256 sliced = now % (1 days);
    if (sliced > UTCStop) {
        uint256 ret2 = (UTCStop) - sliced + UTCStop;
        return (ret2, now + ret2);
    } else {
        uint256 ret1 = (UTCStart - sliced);
        return (ret1, now + ret1);
    }
}

function Open() public view returns(bool) {
    uint256 sliced = now % (1 days);
    return (sliced >= UTCStart && sliced <= UTCStop);
}

function SetPrice(uint256 p) public {
    require(msg.sender == owner);
    require(!Open() && (Winner == 0x0)); 
    Price = p;
}

function _withdraw(bool reduce_price) internal {
    require((now > RoundEndTime));
    require(Winner != 0x0);
    uint256 subber = 0;
    if (reduce_price) {
        subber = Price;
    }
    uint256 Take = (mul(sub(address(this).balance, subber), TakePot)) / 10000;
    Winner.transfer(Take);
    emit GameWon(Winner, Take);
    Winner = 0x0;
    GasPrice = 0;
}

function CheckGameStart(bool remove_price) internal returns(bool) {
    if (Winner != 0x0) {
        _withdraw(remove_price && Open()); 
    }
    if (Winner == 0x0 && Open()) {
        Winner = msg.sender; 
        RoundEndTime = now + RoundTime;
        emit GameStart(RoundEndTime);
        return true;
    }
    return false;
}

function sellPatent(uint16 assetId, uint256 sellPrice) public whenNotPaused {
    Patent memory patent = patents[assetId];
    require(patent.patentOwner == msg.sender);
    require(sellPrice <= 2 * patent.lastPrice);
    require(!patent.onSale);
    patent.onSale = true;
    patent.price = sellPrice;
    patent.sellTime = now;
    patents[assetId] = patent;
    emit SellPatent(assetId, sellPrice);
}

function depositToken(address traderAddr, uint16 tokenCode, uint originalAmount) external {
    if (marketStatus != ACTIVE) revert();
    if (traderAddr == 0) revert();
    if (tokenCode == 0) revert(); 
    if (msg.data.length != 4 + 32 + 32 + 32) revert(); 
    TokenInfo memory tokenInfo = tokens[tokenCode];
    if (originalAmount < tokenInfo.minDeposit) revert();
    if (tokenInfo.scaleFactor == 0) revert(); 
    if (!Token(tokenInfo.tokenAddr).transferFrom(msg.sender, this, originalAmount)) revert();
    if (originalAmount > MAX_UINT256 / 10 ** 8) revert(); 
    uint amountE8 = originalAmount * 10 ** 8 / uint(tokenInfo.scaleFactor);
    if (amountE8 >= 2 ** 64 || amountE8 == 0) revert();
    uint64 depositIndex = ++lastDepositIndex;
    setDeposits(depositIndex, traderAddr, tokenCode, uint64(amountE8));
    emit DepositEvent(traderAddr, tokenCode, tokens[tokenCode].symbol, uint64(amountE8), depositIndex);
}

function transferFee(uint16 tokenCode, uint64 amountE8, address toAddr) external {
    if (msg.sender != admin) revert();
    if (toAddr == 0) revert();
    if (msg.data.length != 4 + 32 + 32 + 32) revert();
    TokenAccount memory feeAccount = accounts[uint176(tokenCode) << 160];
    uint64 withdrawE8 = feeAccount.pendingWithdrawE8;
    if (amountE8 < withdrawE8) {
        withdrawE8 = amountE8;
    }
    feeAccount.pendingWithdrawE8 -= withdrawE8;
    accounts[uint176(tokenCode) << 160] = feeAccount;
    TokenInfo memory tokenInfo = tokens[tokenCode];
    uint originalAmount = uint(withdrawE8) * uint(tokenInfo.scaleFactor) / 10 ** 8;
    if (tokenCode == 0) { 
        toAddr.transfer(originalAmount);
    } else {
        if (!Token(tokenInfo.tokenAddr).transfer(toAddr, originalAmount)) revert();
    }
    emit TransferFeeEvent(tokenCode, withdrawE8, toAddr);
}

function withdrawEth(address traderAddr) external {
    if (traderAddr == 0) revert();
    if (msg.data.length != 4 + 32) revert(); 
    uint176 accountKey = uint176(traderAddr);
    uint amountE8 = accounts[accountKey].pendingWithdrawE8;
    if (amountE8 == 0) return;
    accounts[accountKey].pendingWithdrawE8 = 0;
    uint truncatedWei = amountE8 * (ETH_SCALE_FACTOR / 10 ** 8);
    address withdrawAddr = traders[traderAddr].withdrawAddr;
    if (withdrawAddr == 0) withdrawAddr = traderAddr;
    withdrawAddr.transfer(truncatedWei);
    emit WithdrawEvent(traderAddr, 0, "ETH", uint64(amountE8), exeStatus.lastOperationIndex);
}

function rejectGame(address _playerAddress, uint _gameId) public onlyServer {
    uint gameId = playerGameId[_playerAddress];
    Game storage game = gameIdGame[gameId];
    require(_gameId == gameId);
    require(game.status == GameStatus.WAITING_FOR_SERVER);
    closeGame(game, gameId, _playerAddress, ReasonEnded.REJECTED_BY_SERVER, 0);
    payOut(game, _playerAddress);
    LogGameRejected(_playerAddress, gameId);
}

function regularEndGame(
    address _playerAddress,
    uint32 _roundId,
    uint8 _gameType,
    uint16 _num,
    uint _value,
    int _balance,
    uint _gameId,
    address _contractAddress
)
private {
    uint gameId = playerGameId[_playerAddress];
    Game storage game = gameIdGame[gameId];
    address contractAddress = this;
    int maxBalance = conflictRes.maxBalance();
    require(_gameId == gameId);
    require(_roundId > 0);
    require(-int(game.stake) <= _balance && _balance <= maxBalance);
    require((_gameType == 0) && (_num == 0) && (_value == 0));
    require(_contractAddress == contractAddress);
    require(game.status == GameStatus.ACTIVE);
    closeGame(game, gameId, _playerAddress, ReasonEnded.REGULAR_ENDED, _balance);
    payOut(game, _playerAddress);
}

function endGameConflict(Game storage _game, uint _gameId, address _playerAddress) private {
    int newBalance = conflictRes.endGameConflict(
        _game.gameType,
        _game.betNum,
        _game.betValue,
        _game.balance,
        _game.stake,
        _game.serverSeed,
        _game.playerSeed
    );
    closeGame(_game, _gameId, _playerAddress, ReasonEnded.REGULAR_ENDED, newBalance);
    payOut(_game, _playerAddress);
}

function playerEndGameConflictImpl(
    uint32 _roundId,
    uint8 _gameType,
    uint16 _num,
    uint _value,
    int _balance,
    bytes32 _playerHash,
    bytes32 _playerSeed,
    uint _gameId,
    address _playerAddress
)
private {
    uint gameId = playerGameId[_playerAddress];
    Game storage game = gameIdGame[gameId];
    int maxBalance = conflictRes.maxBalance();
    require(gameId == _gameId);
    require(_roundId > 0);
    require(keccak256(_playerSeed) == _playerHash);
    require(_value <= game.stake);
    require(-int(game.stake) <= _balance && _balance <= maxBalance); 
    require(int(game.stake) + _balance - int(_value) >= 0); 
    require(conflictRes.isValidBet(_gameType, _num, _value));
    if (game.status == GameStatus.SERVER_INITIATED_END && game.roundId == _roundId) {
        game.playerSeed = _playerSeed;
        endGameConflict(game, gameId, _playerAddress);
    } else if (game.status == GameStatus.ACTIVE ||
        (game.status == GameStatus.SERVER_INITIATED_END && game.roundId < _roundId)) {
        game.status = GameStatus.PLAYER_INITIATED_END;
        game.endInitiatedTime = block.timestamp;
        game.roundId = _roundId;
        game.gameType = _gameType;
        game.betNum = _num;
        game.betValue = _value;
        game.balance = _balance;
        game.playerSeed = _playerSeed;
        game.serverSeed = bytes32(0);
        LogPlayerRequestedEnd(msg.sender, gameId);
    } else {
        revert();
    }
}

function playerForceGameEnd(uint _gameId) public {
    address playerAddress = msg.sender;
    uint gameId = playerGameId[playerAddress];
    Game storage game = gameIdGame[gameId];
    require(gameId == _gameId);
    require(game.status == GameStatus.PLAYER_INITIATED_END);
    int newBalance = conflictRes.playerForceGameEnd(
        game.gameType,
        game.betNum,
        game.betValue,
        game.balance,
        game.stake,
        game.endInitiatedTime
    );
    closeGame(game, gameId, playerAddress, ReasonEnded.END_FORCED_BY_PLAYER, newBalance);
    payOut(game, playerAddress);
}

function serverForceGameEnd(address _playerAddress, uint _gameId) public onlyServer {
    uint gameId = playerGameId[_playerAddress];
    Game storage game = gameIdGame[gameId];
    require(gameId == _gameId);
    require(game.status == GameStatus.SERVER_INITIATED_END);
    int newBalance = conflictRes.serverForceGameEnd(
        game.gameType,
        game.betNum,
        game.betValue,
        game.balance,
        game.stake,
        game.endInitiatedTime
    );
    closeGame(game, gameId, _playerAddress, ReasonEnded.END_FORCED_BY_SERVER, newBalance);
    payOut(game, _playerAddress);
}

function createGame(bytes32 _endHash)
public
payable
onlyValidValue
onlyValidHouseStake(activeGames + 1)
onlyNotPaused {
    address playerAddress = msg.sender;
    uint previousGameId = playerGameId[playerAddress];
    Game storage game = gameIdGame[previousGameId];
    require(game.status == GameStatus.ENDED);
    uint gameId = gameIdCntr++;
    playerGameId[playerAddress] = gameId;
    Game storage newGame = gameIdGame[gameId];
    newGame.stake = msg.value;
    newGame.status = GameStatus.WAITING_FOR_SERVER;
    activeGames = activeGames + 1;
    LogGameCreated(playerAddress, gameId, msg.value, _endHash);
}

function serverEndGameConflictImpl(
    uint32 _roundId,
    uint8 _gameType,
    uint16 _num,
    uint _value,
    int _balance,
    bytes32 _serverHash,
    bytes32 _playerHash,
    bytes32 _serverSeed,
    bytes32 _playerSeed,
    uint _gameId,
    address _playerAddress
)
private {
    uint gameId = playerGameId[_playerAddress];
    Game storage game = gameIdGame[gameId];
    int maxBalance = conflictRes.maxBalance();
    require(gameId == _gameId);
    require(_roundId > 0);
    require(keccak256(_serverSeed) == _serverHash);
    require(keccak256(_playerSeed) == _playerHash);
    require(_value <= game.stake);
    require(-int(game.stake) <= _balance && _balance <= maxBalance); 
    require(int(game.stake) + _balance - int(_value) >= 0); 
    require(conflictRes.isValidBet(_gameType, _num, _value));
    if (game.status == GameStatus.PLAYER_INITIATED_END && game.roundId == _roundId) {
        game.serverSeed = _serverSeed;
        endGameConflict(game, gameId, _playerAddress);
    } else if (game.status == GameStatus.ACTIVE ||
        (game.status == GameStatus.PLAYER_INITIATED_END && game.roundId < _roundId)) {
        game.status = GameStatus.SERVER_INITIATED_END;
        game.endInitiatedTime = block.timestamp;
        game.roundId = _roundId;
        game.gameType = _gameType;
        game.betNum = _num;
        game.betValue = _value;
        game.balance = _balance;
        game.serverSeed = _serverSeed;
        game.playerSeed = _playerSeed;
        LogServerRequestedEnd(_playerAddress, gameId);
    } else {
        revert();
    }
}

function payOut(Game storage _game, address _playerAddress) internal {
    assert(_game.balance <= conflictRes.maxBalance());
    assert(_game.status == GameStatus.ENDED);
    assert(_game.stake <= maxStake);
    assert((int(_game.stake) + _game.balance) >= 0);
    uint valuePlayer = uint(int(_game.stake) + _game.balance);
    if (_game.balance > 0 && int(houseStake) < _game.balance) {
        valuePlayer = houseStake;
    }
    houseProfit = houseProfit - _game.balance;
    int newHouseStake = int(houseStake) - _game.balance;
    assert(newHouseStake >= 0);
    houseStake = uint(newHouseStake);
    pendingReturns[_playerAddress] += valuePlayer;
    if (pendingReturns[_playerAddress] > 0) {
        safeSend(_playerAddress);
    }
}

function activateConflictResolution() public onlyOwner {
    require(newConflictRes != 0);
    require(updateTime != 0);
    require(updateTime + MIN_TIMEOUT <= block.timestamp && block.timestamp <= updateTime + MAX_TIMEOUT);
    conflictRes = ConflictResolutionInterface(newConflictRes);
    newConflictRes = 0;
    updateTime = 0;
    LogUpdatedConflictResolution(newConflictRes);
}

function cancelGame(uint _gameId) public {
    address playerAddress = msg.sender;
    uint gameId = playerGameId[playerAddress];
    Game storage game = gameIdGame[gameId];
    require(gameId == _gameId);
    require(game.status == GameStatus.WAITING_FOR_SERVER);
    closeGame(game, gameId, playerAddress, ReasonEnded.CANCELLED_BY_PLAYER, 0);
    payOut(game, playerAddress);
}

function transferProfitToHouse() public {
    require(lastProfitTransferTimestamp + profitTransferTimeSpan <= block.timestamp);
    if (houseProfit <= 0) {
        lastProfitTransferTimestamp = block.timestamp;
        return;
    }
    uint toTransfer = uint(houseProfit);
    assert(houseStake >= toTransfer);
    houseProfit = 0;
    lastProfitTransferTimestamp = block.timestamp;
    houseStake = houseStake - toTransfer;
    houseAddress.transfer(toTransfer);
}

function acceptGame(address _playerAddress, uint _gameId, bytes32 _endHash)
public
onlyServer {
    uint gameId = playerGameId[_playerAddress];
    Game storage game = gameIdGame[gameId];
    require(_gameId == gameId);
    require(game.status == GameStatus.WAITING_FOR_SERVER);
    game.status = GameStatus.ACTIVE;
    LogGameAccepted(_playerAddress, gameId, _endHash);
}

function isMember(address payable _address) public view returns(bool) {
    return (users[_address].uid > 0);
}

function getUid(address payable _address) public view returns(uint) {
    require(users[_address].uid > 0);
    return (users[_address].uid);
}

function getNearestParent(address payable _referral) private view returns(address payable) {
    if (_referral == address(0))
        return (address(0));
    uint _level = 1;
    bool _found = false;
    address payable _parent;
    while (!_found) {
        _parent = findParentInLevel(_referral, _level);
        if (_parent == address(0))
            _level = _level.inc();
        else
            _found = true;
    }
    return (_parent);
}

function getMyPoolShare() public view returns(uint) {
    require(users[msg.sender].uid > 0);
    return (users[msg.sender].poolShare);
}

function generateUid() private returns(uint) {
    if (getUsersCount() >= (uidPrecision / 10))
        uidPrecision *= 10;
    int time = -int(now);
    uint uid = uint(msg.sender) ^ uint(address(this)) ^ uint(time) ^ uint(blockhash(block.number - 1));
    if (uid == 0)
        uid = 1;
    while (uid > uidPrecision)
        uid = uid / 10;
    while (users[uids[uid]].uid > 0) {
        if (uid == (uidPrecision.dec()))
            uid = 1;
        else
            uid = uid.inc();
    }
    return (uid);
}

function doRegisterData(address payable _referral, address payable _child, uint _share) private {
    uint _level;
    uint _uid = generateUid();
    if (_referral == address(0))
        _level = 1;
    else
        _level = users[_referral].level.inc();
    if (_level > maxLevel)
        maxLevel = _level;
    users[_child] = User({
        parent: _referral,
        level: _level,
        txCount: 1,
        ldirect: address(0),
        mdirect: address(0),
        rdirect: address(0),
        uid: _uid,
        poolShare: 0
    });
    users[_child].txs[0] = Tx({
        fr: users[_child].uid,
        to: 0,
        value: _share
    });
    uids[_uid] = _child;
    usersArray.push(_child);
    if (_referral != address(0)) {
        if (users[_referral].ldirect == address(0))
            users[_referral].ldirect = _child;
        else if (users[_referral].mdirect == address(0))
            users[_referral].mdirect = _child;
        else if (users[_referral].rdirect == address(0))
            users[_referral].rdirect = _child;
        else
            revert();
    }
    emit UserRegistered(_referral, _child, _level);
}

function getDirectChildsCount(address _node) public view isNode(_node) returns(uint) {
    uint childs = 0;
    if (users[_node].ldirect != address(0))
        childs = childs.inc();
    if (users[_node].mdirect != address(0))
        childs = childs.inc();
    if (users[_node].rdirect != address(0))
        childs = childs.inc();
    return (childs);
}

function doRegisterPayment(address payable _child, uint _share) private {
    address payable node = _child;
    uint value = msg.value;
    require(value >= _share);
    uint portionsSum = 0;
    for (uint l = 1; l < portions.length; l = l.inc()) {
        node = users[node].parent;
        if (portions[l] > 0) {
            if (node != address(0)) {
                portionsSum = portionsSum.add(portions[l]);
                node.transfer(portions[l]);
                users[node].txs[users[node].txCount] = Tx({
                    fr: users[_child].uid,
                    to: users[node].uid,
                    value: portions[l]
                });
                users[node].txCount = users[node].txCount.inc();
            }
        }
    }
    pool = pool.add(autoPoolShare);
    uint beneficiaryShare = _share.sub(portionsSum).sub(autoPoolShare);
    beneficiary.transfer(beneficiaryShare);
    uint remainedValue = value.sub(_share);
    if (remainedValue > 0)
        _child.transfer(remainedValue);
}

function findParentInLevel(address payable _referral, uint _level) private view returns(address payable) {
    if (_level == 1) {
        if (getDirectChildsCount(_referral) < 3)
            return (_referral);
        else
            return (address(0));
    } else {
        address payable ldirect = findParentInLevel(users[_referral].ldirect, _level.dec());
        if (ldirect == address(0)) {
            address payable mdirect = findParentInLevel(users[_referral].mdirect, _level.dec());
            if (mdirect == address(0)) {
                address payable rdirect = findParentInLevel(users[_referral].rdirect, _level.dec());
                return (rdirect);
            } else
                return (mdirect);
        } else
            return (ldirect);
    }
}

function doRegister(address payable _referral, uint _share) private {
    require(users[msg.sender].uid == 0);
    doRegisterData(_referral, msg.sender, _share);
    doRegisterPayment(msg.sender, _share);
}

function initialize(address payable _parent, address payable _child) public maintainanceOn {
    require((msg.sender == owner) || (msg.sender == beneficiary));
    require(_parent != address(0));
    require(_child != address(0));
    require(users[_parent].uid > 0);
    require(users[_child].uid == 0);
    doRegisterData(_parent, _child, share);
    doRegisterTx(_child);
}

function getEarned(address payable _address) public view registered(_address) returns(uint) {
    uint sum;
    for (uint i = 1; i < users[_address].txCount; i = i.inc())
        sum = sum.add(users[_address].txs[i].value);
    return (sum);
}

function doRegisterTx(address payable _child) private {
    address payable node = _child;
    for (uint l = 1; l < portions.length; l = l.inc()) {
        node = users[node].parent;
        if (portions[l] > 0) {
            if (node != address(0)) {
                users[node].txs[users[node].txCount] = Tx({
                    fr: users[_child].uid,
                    to: users[node].uid,
                    value: portions[l]
                });
                users[node].txCount = users[node].txCount.inc();
            }
        }
    }
}

function initializeDirect(address payable _direct) public maintainanceOn {
    require((msg.sender == owner) || (msg.sender == beneficiary));
    require(maxDirectRegister > directRegisterCount);
    require(_direct != address(0));
    require(users[_direct].uid == 0);
    directRegisterCount = directRegisterCount.inc();
    directUsers.push(msg.sender);
    doRegisterData(address(0), _direct, directShare);
}

function getTx(address payable _address, uint _index) public view registered(_address) returns(uint, uint, uint, uint, uint) {
    require(_index < users[_address].txCount);
    uint uid = getUid(_address);
    return (_index, uid, users[_address].txs[_index].fr, users[_address].txs[_index].to, users[_address].txs[_index].value);
}

function withdrawMyPoolShare() public {
    require(users[msg.sender].poolShare > 0);
    msg.sender.transfer(users[msg.sender].poolShare);
    users[msg.sender].poolShare = 0;
}

function getChildsCount(address _node) public view isNode(_node) returns(uint) {
    if (_node == address(0))
        return (0);
    uint childs = getDirectChildsCount(_node);
    if (users[_node].ldirect != address(0))
        childs = childs.add(getChildsCount(users[_node].ldirect));
    if (users[_node].mdirect != address(0))
        childs = childs.add(getChildsCount(users[_node].mdirect));
    if (users[_node].rdirect != address(0))
        childs = childs.add(getChildsCount(users[_node].rdirect));
    return (childs);
}

function mintForPrivateFiat(address _beneficiary, uint256 _weiAmount) public onlyOwner {
    require(_beneficiary != address(0));
    _preValidatePurchase(_beneficiary, _weiAmount);
    uint256 tokens = _getTokenAmount(_weiAmount);
    weiRaised = weiRaised.add(_weiAmount);
    tokensRaised = tokensRaised.add(tokens);
    if (capReached()) {
        emit CapOverflow(_beneficiary, _weiAmount, tokens, now);
        emit IncrementTieredState(getState());
    }
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(
        msg.sender,
        _beneficiary,
        _weiAmount,
        tokens
    );
    _updatePurchasingState(_beneficiary, _weiAmount);
    _forwardFunds();
}

function lastClaim(uint256 tokenIndex) public view returns(uint256) {
    require(
        INFToken(_nftAddress).ownerOf(tokenIndex) != address(0),
        "Owner cannot be 0 address"
    );
    require(
        tokenIndex < INFToken(_nftAddress).totalSupply(),
        "NFT at index has not been minted yet"
    );
    uint256 lastClaimed =
        uint256(_lastClaim[tokenIndex]) != 0 ?
        uint256(_lastClaim[tokenIndex]) :
        emissionStart;
    return lastClaimed;
}

function claim(uint256[] memory tokenIndices) public returns(uint256) {
    require(
        block.timestamp > emissionStart,
        "Emission has not started yet"
    );
    uint256 totalClaimQty = 0;
    for (uint256 i = 0; i < tokenIndices.length; i++) {
        require(
            tokenIndices[i] < INFToken(_nftAddress).totalSupply(),
            "NFT at index has not been minted yet"
        );
        for (uint256 j = i + 1; j < tokenIndices.length; j++) {
            require(
                tokenIndices[i] != tokenIndices[j],
                "Duplicate token index"
            );
        }
        uint256 tokenIndex = tokenIndices[i];
        require(
            INFToken(_nftAddress).ownerOf(tokenIndex) == msg.sender,
            "Sender is not the owner"
        );
        uint256 claimQty = accumulated(tokenIndex);
        if (claimQty != 0) {
            totalClaimQty = totalClaimQty.add(claimQty);
            _lastClaim[tokenIndex] = block.timestamp;
        }
    }
    require(totalClaimQty != 0, "No accumulated NCT");
    _mint(msg.sender, totalClaimQty);
    return totalClaimQty;
}

function accumulated(uint256 tokenIndex) public view returns(uint256) {
    require(
        block.timestamp > emissionStart,
        "Emission has not started yet"
    );
    require(
        INFToken(_nftAddress).ownerOf(tokenIndex) != address(0),
        "Owner cannot be 0 address"
    );
    require(
        tokenIndex < INFToken(_nftAddress).totalSupply(),
        "NFT at index has not been minted yet"
    );
    uint256 lastClaimed = lastClaim(tokenIndex);
    if (lastClaimed >= emissionEnd) return 0;
    uint256 accumulationPeriod =
        block.timestamp < emissionEnd ? block.timestamp : emissionEnd; 
    uint256 totalAccumulated =
        accumulationPeriod.sub(lastClaimed).mul(emissionPerDay).div(
            SECONDS_IN_A_DAY
        );
    if (lastClaimed == emissionStart) {
        uint256 initialAllotment =
            INFToken(_nftAddress).isMintedBeforeReveal(tokenIndex) == true ?
            INITIAL_ALLOTMENT.mul(PRE_REVEAL_MULTIPLIER) :
            INITIAL_ALLOTMENT;
        totalAccumulated = totalAccumulated.add(initialAllotment);
    }
    return totalAccumulated;
}

function claimAllocation()
public {
    Allocation memory alloc = allocation[msg.sender];
    require(alloc.amount != 0, 'WOMTokenLocker: client does not have allocation');
    require(now >= alloc.release, 'WOMTokenLocker: client cannot claim with time lock');
    require(WOM_TOKEN.balanceOf(address(this)) >= alloc.amount, 'WOMTokenLocker: contract does not have sufficient funds');
    delete allocation[msg.sender];
    WOM_TOKEN.transfer(msg.sender, alloc.amount);
    emit AllocationClaimed(msg.sender, alloc.release, alloc.amount);
}

function addAllocation(address recipient, uint256 release, uint256 amount)
public
onlyOwner {
    require(WOM_TOKEN.allowance(owner(), address(this)) >= amount, 'WOMTokenLocker: allowance is less than amount');
    WOM_TOKEN.transferFrom(owner(), address(this), amount);
    allocation[recipient] = Allocation({
        release: release,
        amount: amount
    });
    emit AllocationAdded(msg.sender, release, amount);
}

