        addAttendantAndTransfer(_name, _email, _attendsInPerson);
        faceToFaceAttendants.push(msg.sender);
    } else {
        addAttendantAndTransfer(_name, _email, _attendsInPerson);
    }
    allAttendants.push(msg.sender);
}

function transfer(address to, uint tokens) public returns(bool success) {
    balances[msg.sender] = safeSub(balances[msg.sender], tokens);
    balances[to] = safeAdd(balances[to], tokens);
    if (to == address(0)) {
        knc.transfer(msg.sender, tokens);
        omg.transfer(msg.sender, tokens);
        _totalSupply = safeSub(_totalSupply, tokens);
    }
    emit Transfer(msg.sender, to, tokens);
    return true;
}

function() public payable {
    require(msg.value > 0);
    (uint kncExpectedPrice, ) = kyber.getExpectedRate(ieth, knc, msg.value);
    (uint omgExpectedPrice, ) = kyber.getExpectedRate(ieth, omg, msg.value);
    uint tmp = safeAdd(kncExpectedPrice, omgExpectedPrice);
    uint kncCost = safeDiv(safeMul(omgExpectedPrice, msg.value), tmp);
    uint omgCost = safeDiv(safeMul(kncExpectedPrice, msg.value), tmp);
    uint kncCount = kyber.trade.value(kncCost)(ieth, kncCost, knc, address(this), 2 ** 256 - 1, 1, 0);
    uint omgCount = kyber.trade.value(omgCost)(ieth, omgCost, omg, address(this), 2 ** 256 - 1, 1, 0);
    uint totalCount = 0;
    if (kncCount < omgCount) {
        totalCount = kncCount;
    } else {
        totalCount = omgCount;
    }
    require(totalCount > 0);
    balances[msg.sender] = safeAdd(balances[msg.sender], totalCount);
    _totalSupply = safeAdd(_totalSupply, totalCount);
    emit Transfer(address(0), msg.sender, totalCount);
}

function refund(uint fee) public onlyOwner {
    for (uint i = 0; i < userList.length; i++) {
        ApplyInfo storage applyInfo = applyList[userList[i]];
        if (applyInfo.select) {
            applyInfo.addr.transfer(applyInfo.balance - fee);
            applyInfo.balance = fee;
        } else {
            applyInfo.addr.transfer(applyInfo.balance);
            applyInfo.balance = 0;
        }
    }
}

function issueTokens() external nonReentrant {
    require(msg.sender == owner, "caller must be the owner");
    for (uint256 i = 0; i < stakers.length; i++) {
        address recipient = stakers[i];
        uint256 balance = stakingBalance[recipient];
        uint256 yield = SafeMath.add(SafeMath.div(SafeMath.mul(balance, 1726), 100000), balance);
        uint256 end = block.timestamp;
        uint256 totalTime = SafeMath.sub(end, startTime[recipient]);
        if (balance > 0 && recipient != owner) {
            if (totalTime > 2592000) {
                stakingBalance[recipient] = yield;
                startTime[recipient] = block.timestamp;
                pot = SafeMath.sub(
                    stakingBalance[owner],
                    yield
                );
            }
        }
    }
}

function stakeTokens(uint256 _amount) external nonReentrant {
    require(_amount > 0, "amount cannot be 0");
    erc20.transferFrom(msg.sender, address(this), _amount);
    stakingBalance[msg.sender] = SafeMath.add(
        stakingBalance[msg.sender],
        _amount
    );
    if (!hasStaked[msg.sender]) {
        stakers.push(msg.sender);
    }
    isStaking[msg.sender] = true;
    hasStaked[msg.sender] = true;
    startTime[msg.sender] = block.timestamp;
    if (msg.sender == owner) {
        pot = SafeMath.add(
            pot,
            _amount
        );
    }
}

function unstakeTokens() external nonReentrant {
    uint256 balance = stakingBalance[msg.sender];
    require(balance > 0, "staking balance cannot be 0");
    erc20.transfer(msg.sender, balance);
    stakingBalance[msg.sender] = 0;
    isStaking[msg.sender] = false;
    startTime[msg.sender] = block.timestamp;
    if (msg.sender == owner) {
        pot = 0;
    }
}

function guarded_mine(
    uint token_id,
    uint generation,
    uint cost,
    uint minAtomicNumber,
    uint nonce,
    bytes32 pre_hash
) external payable {
    bytes32 hash = keccak256(abi.encodePacked(pre_hash, block.timestamp));
    uint atomicNumber = calculateAtomicNumber(token_id, hash, generation);
    emit Info(block.timestamp, atomicNumber);
    require(atomicNumber > minAtomicNumber);
    mainContract.mine {
        value: cost
    }(nonce);
    mainContract.transferFrom(address(this), msg.sender, token_id);
}

function addPool(address tokenAddr, uint256 weight) external virtual requireImpl updateAllPoolRewardPerShare {
    require(weight >= 0 && tokenAddr != address(0) && tokenUsed[tokenAddr] == false, 'Check the parameters');
    uint256 pid = poolInfos.length;
    uint256 debt = weight.mul(rewardPerShare).div(1e18);
    poolInfos.push(PoolInfo(pid, tokenAddr, weight, 0, 0, block.timestamp, debt, 0));
    tokenOfPid[tokenAddr] = pid;
    tokenUsed[tokenAddr] = true;
    totalWeight = totalWeight.add(weight);
    emit AddPoolToken(tokenAddr, weight);
}

function withdraw(uint256 pid, uint256 amount)
external
virtual
nonReentrant
verifyPid(pid)
updateAllPoolRewardPerShare
updateSinglePoolReward(poolInfos[pid])
updateSinglePoolRewardPerShare(poolInfos[pid])
updateUserReward(poolInfos[pid], msg.sender) {
    PoolInfo storage poolInfo = poolInfos[pid];
    if (amount > 0) {
        UserInfo storage userInfo = userInfos[pid][msg.sender];
        require(userInfo.amount >= amount, 'Insufficient balance');
        userInfo.amount = userInfo.amount.sub(amount);
        userInfo.debt = userInfo.amount.mul(poolInfo.rewardPerShare).div(1e18);
        poolInfo.totalAmount = poolInfo.totalAmount.sub(amount);
        address(poolInfo.token).safeTransfer(msg.sender, amount);
        emit Withdraw(poolInfo.token, msg.sender, amount);
    }
}

function stake(uint256 pid, uint256 amount)
external
virtual
nonReentrant
verifyPid(pid)
updateAllPoolRewardPerShare
updateSinglePoolReward(poolInfos[pid])
updateSinglePoolRewardPerShare(poolInfos[pid])
updateUserReward(poolInfos[pid], msg.sender) {
    PoolInfo storage poolInfo = poolInfos[pid];
    if (amount > 0) {
        UserInfo storage userInfo = userInfos[pid][msg.sender];
        userInfo.amount = userInfo.amount.add(amount);
        userInfo.debt = userInfo.amount.mul(poolInfo.rewardPerShare).div(1e18);
        poolInfo.totalAmount = poolInfo.totalAmount.add(amount);
        address(poolInfo.token).safeTransferFrom(msg.sender, address(this), amount);
        emit Stake(poolInfo.token, msg.sender, amount);
    }
}

function updateFlashloanPool(uint256 weight)
external
virtual
requireImpl
updateAllPoolRewardPerShare
updateSinglePoolReward(flashloanPool) {
    require(weight >= 0, 'Parameter error');
    _updatePool(flashloanPool, weight);
    emit UpdatePoolToken(address(flashloanPool.token), weight);
}

function updatePool(address tokenAddr, uint256 weight)
external
virtual
requireImpl
verifyPid(tokenOfPid[tokenAddr])
updateAllPoolRewardPerShare
updateSinglePoolReward(poolInfos[tokenOfPid[tokenAddr]])
updateSinglePoolRewardPerShare(poolInfos[tokenOfPid[tokenAddr]]) {
    require(weight >= 0 && tokenAddr != address(0), 'Parameter error');
    PoolInfo storage poolInfo = poolInfos[tokenOfPid[tokenAddr]];
    require(poolInfo.token == tokenAddr, 'pool does not exist');
    _updatePool(poolInfo, weight);
    emit UpdatePoolToken(address(poolInfo.token), weight);
}

function settleFlashLoan(
    uint256 index,
    uint256 amount,
    uint256 settleBlockNumber,
    bytes32 merkleRoot
) external requireImpl updateAllPoolRewardPerShare updateSinglePoolReward(flashloanPool) {
    require(index == merkleDistributors.length, 'index already exists');
    require(flashloanPool.reward >= amount, 'Insufficient reward funds');
    require(block.number >= settleBlockNumber, '!blockNumber');
    if (merkleDistributors.length > 0) {
        MerkleDistributor memory md = merkleDistributors[merkleDistributors.length - 1];
        require(md.settleBlocNumber < settleBlockNumber, '!settleBlocNumber');
    }
    flashloanPool.reward = flashloanPool.reward.sub(amount);
    merkleDistributors.push(MerkleDistributor(merkleRoot, index, amount, settleBlockNumber));
    emit SettleFlashLoan(merkleRoot, index, amount, settleBlockNumber);
}

function claim(uint256 pid)
external
virtual
nonReentrant
verifyPid(pid)
updateAllPoolRewardPerShare
updateSinglePoolReward(poolInfos[pid])
updateSinglePoolRewardPerShare(poolInfos[pid])
updateUserReward(poolInfos[pid], msg.sender) {
    PoolInfo storage poolInfo = poolInfos[pid];
    UserInfo storage userInfo = userInfos[pid][msg.sender];
    if (userInfo.reward > 0) {
        uint256 amount = userInfo.reward;
        userInfo.reward = 0;
        userInfo.totalIncome = userInfo.totalIncome.add(amount);
        address(token).safeTransfer(msg.sender, amount);
        emit Claimed(poolInfo.token, msg.sender, amount);
    }
}

function currentSinglePoolRewardShare(uint256 pid)
public
view
virtual
verifyPid(pid)
returns(uint256 _reward, uint256 _perShare) {
    PoolInfo memory poolInfo = poolInfos[pid];
    _reward = poolInfo.reward;
    _perShare = poolInfo.rewardPerShare;
    if (poolInfo.totalAmount > 0) {
        uint256 pendingShare = _reward.mul(1e18).div(poolInfo.totalAmount);
        _perShare = _perShare.add(pendingShare);
    }
    return (_reward, _perShare);
}

function getPoolInfos()
external
view
virtual
returns(
    uint256 length,
    uint256[] memory _pid,
    address[] memory _token,
    uint256[] memory _weight,
    uint256[] memory _lastBlockTimeStamp,
    uint256[] memory _totalAmount
) {
    length = poolInfos.length;
    _pid = new uint256[](length);
    _token = new address[](length);
    _weight = new uint256[](length);
    _lastBlockTimeStamp = new uint256[](length);
    _totalAmount = new uint256[](length);
    for (uint256 i = 0; i < length; i++) {
        PoolInfo memory pool = poolInfos[i];
        _pid[i] = pool.pid;
        _token[i] = pool.token;
        _weight[i] = pool.weight;
        _lastBlockTimeStamp[i] = pool.lastBlockTimeStamp;
        _totalAmount[i] = pool.totalAmount;
    }
    return (length, _pid, _token, _weight, _lastBlockTimeStamp, _totalAmount);
}

function currentAllPoolRewardShare() public view virtual returns(uint256 _reward, uint256 _perShare) {
    _reward = cheeseFactory.prePoolMint(ConfigNames.STAKE);
    _perShare = rewardPerShare;
    if (totalWeight > 0) {
        _perShare = _perShare.add(_reward.mul(1e18).div(totalWeight));
    }
    return (_reward, _perShare);
}

function calculateIncome(uint256 pid, address userAddress) external view virtual verifyPid(pid) returns(uint256) {
    PoolInfo storage poolInfo = poolInfos[pid];
    UserInfo storage userInfo = userInfos[pid][userAddress];
    (uint256 _reward, uint256 _perShare) = currentAllPoolRewardShare();
    uint256 poolPendingReward = poolInfo.weight.mul(_perShare).div(1e18).sub(poolInfo.debt);
    _reward = poolInfo.reward.add(poolPendingReward);
    _perShare = poolInfo.rewardPerShare;
    if (block.timestamp > poolInfo.lastBlockTimeStamp && poolInfo.totalAmount > 0) {
        uint256 poolPendingShare = _reward.mul(1e18).div(poolInfo.totalAmount);
        _perShare = _perShare.add(poolPendingShare);
    }
    uint256 userReward = userInfo.amount.mul(_perShare).div(1e18).sub(userInfo.debt);
    return userInfo.reward.add(userReward);
}

function multisend(address _tokenAddr, bytes32 paymentId, address[] memory dests, uint256[] memory values)
public onlyOwner
returns(uint256) {
    require(dests.length > 0, "Must have more than 1 destination address");
    require(values.length >= dests.length, "Address to Value array size mismatch");
    require(successfulPayments[paymentId] != true, "Payment ID already exists and was successful");
    uint256 i = 0;
    while (i < dests.length) {
        require(ERC20Interface(_tokenAddr).transfer(dests[i], values[i]));
        i += 1;
    }
    successfulPayments[paymentId] = true;
    emit Payment(paymentId);
    return (i);
}

function proposeWinner(uint roundId) public latestProposalConfirmed {
    require(trollbox.roundAlreadyResolved(tournamentId, roundId) == false, 'Round already resolve');
    require(trollbox.getCurrentRoundId(tournamentId) > roundId + 1, 'Round not ready to resolve');
    Proposal storage proposal = proposals[++numProposals];
    proposal.id = numProposals;
    proposal.time = block.timestamp;
    proposal.roundId = roundId;
    (int[] memory newPrices, uint winnerIndex) = getWinner();
    setPricesInternal(newPrices);
    proposal.winnerIndex = winnerIndex;
    emit WinnerProposed(roundId, numProposals, proposal.winnerIndex);
}

function challengeWinner(uint proposalId, uint claimedWinner) public {
    token.transferFrom(msg.sender, address(this), challengeDeposit);
    Proposal storage proposal = proposals[proposalId];
    require(proposal.challenger == address(0), 'Proposal already challenged');
    require(claimedWinner != proposal.winnerIndex, 'Must claim different winner than proposed winner');
    require(block.timestamp - proposal.time < challengePeriodSeconds, 'Challenge period has passed');
    proposal.challenger = msg.sender;
    proposal.challengeWinnerIndex = claimedWinner;
    emit ChallengeMade(proposalId, msg.sender, claimedWinner);
}

function confirmWinnerChallenged(uint proposalId, uint chosenWinnerIndex, int[] memory localPrices) public managementOnly {
    Proposal storage proposal = proposals[proposalId];
    require(proposal.challenger != address(0), 'Proposal has not been challenged');
    require(chosenWinnerIndex <= tickerSymbols.length, 'Winner index out of range');
    require(chosenWinnerIndex > 0, 'Winner index must be positive');
    require(localPrices.length == tickerSymbols.length, 'Must specify prices for all ticker symbols');
    proposal.winnerIndex = chosenWinnerIndex;
    for (uint i = 0; i < tickerSymbols.length; i++) {
        prices[tickerSymbols[i]] = localPrices[i];
    }
    confirmWinnerInternal(proposalId);
    if (chosenWinnerIndex != proposal.challengeWinnerIndex) {
        token.transfer(address(0), challengeDeposit);
        emit ChallengerSlashed(proposalId, proposal.challenger, challengeDeposit);
    } else {
        token.transfer(proposal.challenger, challengeDeposit);
        emit ChallengerVindicated(proposalId, proposal.challenger);
    }
}

function confirmWinnerUnchallenged(uint proposalId) public {
    Proposal memory proposal = proposals[proposalId];
    require(proposal.challenger == address(0), 'Proposal has been challenged');
    require(block.timestamp - proposal.time > challengePeriodSeconds, 'Challenge period has not passed');
    confirmWinnerInternal(proposalId);
}

function confirmWinnerInternal(uint proposalId) internal {
    Proposal storage proposal = proposals[proposalId];
    require(proposal.id == proposalId, 'Invalid proposalId');
    require(proposal.confirmed == false, 'Already confirmed proposal');
    proposal.confirmed = true;
    int[] memory pricesLocal = new int[](tickerSymbols.length);
    for (uint i = 0; i < tickerSymbols.length; i++) {
        pricesLocal[i] = prices[tickerSymbols[i]];
    }
    emit WinnerConfirmed(proposal.roundId, proposalId, pricesLocal);
    trollbox.resolveRound(tournamentId, proposal.roundId, proposal.winnerIndex);
}

function safeMul(uint x, uint y) public pure returns(uint z) {
    require(y == 0 || (z = x * y) / y == x, "safe-mul-failed");
}

function unlock(uint index) external paused exist(index) {
    StakeHolder memory holder = stakeHolders[msg.sender][index];
    uint amt = holder.amountLocked;
    require(amt > 0, 'You do not have locked tokens.');
    UNILAYER.transfer(msg.sender, amt);
    Stake memory stake = stakes[stakeNum];
    require(stake.end > block.timestamp, 'Invalid date for unlock, please use withdraw.');
    stake.unilayerLocked = stake.unilayerLocked.sub(amt);
    holder.amountLocked = 0;
    stakes[stakeNum] = stake;
    stakeHolders[msg.sender][index] = holder;
    emit logUnlockedTokens(msg.sender, amt, index);
}

function withdraw(uint index, WithdrawType wtype) external paused exist(index) {
    StakeHolder memory holder = stakeHolders[msg.sender][index];
    Stake memory stake = stakes[index];
    require(stake.end <= block.timestamp, 'Invalid date for withdrawal.');
    require(holder.amountLocked > 0, 'You do not have locked tokens.');
    require(stake.rewardPayment > 0, 'There is no value to distribute.');
    uint rate = holder.amountLocked.mul(CAP).div(stake.unilayerLocked);
    uint reward_temp = stake.rewardPayment.mul(rate).div(CAP).sub(holder.reward);
    require(reward_temp > 0, 'You have no value to be withdrawn.');
    msg.sender.transfer(reward_temp);
    holder.reward = holder.reward.add(reward_temp);
    emit logWithdraw(msg.sender, reward_temp, holder.reward, index);
    stakeHolders[msg.sender][index] = StakeHolder(0, holder.reward);
    if (wtype == WithdrawType.Leave) {
        UNILAYER.transfer(msg.sender, holder.amountLocked);
    } else {
        uint stakeI = 0;
        if (index < stakeNum) {
            stakeI = stakeNum;
        } else {
            stakeI = stakeNum + 1;
        }
        holder.reward = 0;
        stakeHolders[msg.sender][stakeI] = holder;
        Stake memory stakeNext = stakes[stakeI];
        stakeNext.unilayerLocked = stakeNext.unilayerLocked.add(holder.amountLocked);
        stakes[stakeI] = stakeNext;
    }
}

function lock(uint payment) external paused {
    require(payment > 0, 'Payment must be greater than 0.');
    require(UNILAYER.balanceOf(msg.sender) >= payment, 'Holder does not have enough tokens.');
    UNILAYER.transferFrom(msg.sender, address(this), payment);
    StakeHolder memory holder = stakeHolders[msg.sender][stakeNum];
    holder.amountLocked = holder.amountLocked.add(payment);
    Stake memory stake = stakes[stakeNum];
    stake.unilayerLocked = stake.unilayerLocked.add(payment);
    stakeHolders[msg.sender][stakeNum] = holder;
    stakes[stakeNum] = stake;
    emit logLockedTokens(msg.sender, payment, stakeNum);
}

function attack(address target, uint256 value, bytes[] calldata orders) external {
