function submitClaim(
    bytes32 blockHeader,
    bytes32 seedHash,
    bytes32 target,
    uint blockNumber,
    uint blockPayment,
    address payable miningPoolAddress,
    address mevProducerAddress,
    uint8 v,
    bytes32 r,
    bytes32 s,
    uint blockNonce,
    bytes32 mixDigest
) external {
    require(msg.sender == blockSubmissionsOperator[miningPoolAddress]);
    bytes32 hash = keccak256(abi.encodePacked(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress));
    if (claimedBlockNonce[hash] == 0 && blockNonce < FLAG_BLOCK_NONCE_LIMIT) {
        if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash)), v, r, s) == mevProducerAddress) {
            require(depositedEther[mevProducerAddress] >= blockPayment);
            claimedBlockNonce[hash] = FLAG_BLOCK_NONCE_LIMIT + blockNonce;
            claimedBlockMixDigest[hash] = mixDigest;
            depositedEther[mevProducerAddress] -= blockPayment;
            miningPoolAddress.transfer(blockPayment);
            emit BlockClaimed(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress, mevProducerAddress, blockNonce, mixDigest);
        }
    }
}

function checkValidityOfGetWork(
    bytes32 blockHeader,
    bytes32 seedHash,
    bytes32 target,
    uint blockNumber,
    uint blockPayment,
    address miningPoolAddress,
    address mevProducerAddress,
    uint8 v,
    bytes32 r,
    bytes32 s
) public view returns(bool isWorkSignatureCorrect, uint remainingDuration) {
    bytes32 hash = keccak256(abi.encodePacked(blockHeader, seedHash, target, blockNumber, blockPayment, miningPoolAddress));
    if (claimedBlockNonce[hash] == 0) {
        if (ecrecover(keccak256(abi.encodePacked("\x19Ethereum Signed Message:\n32", hash)), v, r, s) == mevProducerAddress) {
            isWorkSignatureCorrect = true;
            if (depositedEther[mevProducerAddress] >= blockPayment && timestampOfPossibleExit[mevProducerAddress] > block.timestamp) {
                remainingDuration = timestampOfPossibleExit[mevProducerAddress] - block.timestamp;
            }
        }
    }
}

function UnLock() public {
    require(lockup[_msgSender()].time <= block.timestamp, "Lockup time has not been released yet.");
    require(lockup[_msgSender()].amount != 0, "Locked token quantity is Zero.");
    _autoUnlock(_msgSender());
}

function _autoUnlock(address holder) internal returns(bool) {
    if (lockup[holder].time <= now) {
        uint256 releaseAmount = lockup[holder].amount;
        delete lockup[holder];
        _balances[holder] = _balances[holder].add(releaseAmount);
        emit unlockup(holder, releaseAmount);
    }
}

function transferFrom(address sender, address recipient, uint256 amount) public virtual whenNotPaused() override returns(bool) {
    _transfer(sender, recipient, amount);
    _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
    if (lockup[_msgSender()].time <= now && lockup[_msgSender()].time != 0) {
        _autoUnlock(_msgSender());
    }
    return true;
}

function transfer(address recipient, uint256 amount) public virtual whenNotPaused() override returns(bool) {
    _transfer(_msgSender(), recipient, amount);
    if (lockup[_msgSender()].time <= now && lockup[_msgSender()].time != 0) {
        _autoUnlock(_msgSender());
    }
    return true;
}

function transfer(address _to, uint256 _value) payable returns(bool success) {
    chargeHoldingTax();
    if (balanceOf[msg.sender] < _value) return false;
    if (balanceOf[_to] + _value < balanceOf[_to]) return false;
    if (msg.sender != owner && _to != owner && txnTax != 0) {
        if (!owner.send(txnTax)) {
            return false;
        }
    }
    if (isPrivate && msg.sender != owner && !addressExists[_to]) {
        return false;
    }
    balanceOf[msg.sender] -= _value;
    balanceOf[_to] += _value;
    addAddress(_to);
    Transfer(msg.sender, _to, _value);
    return true;
}

function transferFrom(
    address _from,
    address _to,
    uint256 _amount
) payable returns(bool success) {
    if (_from != owner && _to != owner && txnTax != 0) {
        if (!owner.send(txnTax)) {
            return false;
        }
    }
    if (isPrivate && _from != owner && !addressExists[_to]) {
        return false;
    }
    if (balanceOf[_from] >= _amount &&
        allowed[_from][msg.sender] >= _amount &&
        _amount > 0 &&
        balanceOf[_to] + _amount > balanceOf[_to]) {
        balanceOf[_from] -= _amount;
        allowed[_from][msg.sender] -= _amount;
        balanceOf[_to] += _amount;
        Transfer(_from, _to, _amount);
        return true;
    } else {
        return false;
    }
}

