function unlockEth(uint vaultId, uint shareBurnAmt) external 
{
    VAULT_INFO storage m = VAULT[vaultId];
    require(block.timestamp < m.tEnd, '!vaultEnded');
    require(shareBurnAmt > 0, '!shareBurnAmt');
    address payable user = msg.sender;
    uint ethOutAmt = shareBurnAmt.mul(getVaultValueInEth(vaultId)).div(m.shareTotal);
    _burnShare(m, user, shareBurnAmt);
    _sendEth(m, user, ethOutAmt);
    emit UNLOCK_ETH(vaultId, user, ethOutAmt, shareBurnAmt);
}

function lockToken(uint vaultId, uint tokenInAmt) external 
{
    VAULT_INFO storage m = VAULT[vaultId];
    require(block.timestamp < m.tEnd, '!vaultEnded');
    require(m.vaultStatus < VAULT_STATUS_BANNED, '!vaultBanned');
    require(tokenStatus[m.token] < TOKEN_STATUS_BANNED, '!tokenBanned');
    require(tokenInAmt > 0, '!tokenInAmt');
    address payable user = msg.sender;
    uint ethOutAmt = tokenInAmt.mul(getVaultPriceScaled(vaultId)) / (PRICE_SCALE);
    if (m.devFeeBP > 0) {
        uint treasuryAmt = ethOutAmt.mul(uint(m.devFeeBP)) / (10000);
        treasuryAmtTotal = treasuryAmtTotal.add(treasuryAmt);
        ethOutAmt = ethOutAmt.sub(treasuryAmt);
        m.ethTotal = (m.ethTotal).sub(treasuryAmt, '!ethInVault'); 
    }
    ERC20(m.token).transferFrom(user, address(this), tokenInAmt);
    _mintTllll(m, user, tokenInAmt);
    _sendEth(m, user, ethOutAmt);
    emit LOCK_TOKEN(vaultId, user, tokenInAmt, ethOutAmt);
}

function exitShare(uint vaultId, address payable user) external 
{
    VAULT_INFO storage m = VAULT[vaultId];
    require(block.timestamp > m.tEnd, '!vaultStillOpen');
    uint userShareAmt = m.share[user];
    require(userShareAmt > 0, '!userShareAmt');
    uint ethOutAmt = (m.ethTotal).mul(userShareAmt).div(m.shareTotal);
    uint tokenOutAmt = (m.tllllTotal).mul(userShareAmt).div(m.shareTotal);
    _burnShare(m, user, userShareAmt);
    if (tokenOutAmt > 0) {
        m.tllllTotal = (m.tllllTotal).sub(tokenOutAmt); 
        ERC20(m.token).transfer(user, tokenOutAmt);
    }
    if (ethOutAmt > 0)
        _sendEth(m, user, ethOutAmt);
    emit EXIT_SHARE(vaultId, user, userShareAmt);
}

function unlockToken(uint vaultId) external payable 
{
    VAULT_INFO storage m = VAULT[vaultId];
    require(block.timestamp < m.tEnd, '!vaultEnded');
    uint ethInAmt = msg.value;
    require(ethInAmt > 0, '!ethInAmt');
    uint ethReturnAmt = 0;
    address payable user = msg.sender;
    uint priceScaled = getVaultPriceScaled(vaultId);
    uint tokenOutAmt = ethInAmt.mul(PRICE_SCALE).div(priceScaled);
    if (tokenOutAmt > m.tllll[user]) {
        tokenOutAmt = m.tllll[user];
        ethReturnAmt = ethInAmt.sub(
            tokenOutAmt.mul(priceScaled) / (PRICE_SCALE)
        );
    }
    _burnTllll(m, user, tokenOutAmt);
    ERC20(m.token).transfer(user, tokenOutAmt);
    m.ethTotal = (m.ethTotal).add(ethInAmt); 
    if (ethReturnAmt > 0)
        _sendEth(m, user, ethReturnAmt);
    emit UNLOCK_TOKEN(vaultId, user, tokenOutAmt, ethInAmt.sub(ethReturnAmt));
}

function getVaultValueInEth(uint vaultId) public view returns(uint) {
    VAULT_INFO memory m = VAULT[vaultId];
    uint priceNowScaled;
    if (block.timestamp >= m.tEnd)
        priceNowScaled = m.priceEndScaled;
    else {
        uint FACTOR = 10 ** 18;
        priceNowScaled = uint(m.priceEndScaled) * FACTOR / (FACTOR + FACTOR * uint(m.apyBP) * (m.tEnd - block.timestamp) / (365 days) / 10000);
    }
    uint ethValue = m.ethTotal;
    uint tokenValue = (m.tllllTotal).mul(priceNowScaled) / (PRICE_SCALE);
    return ethValue.add(tokenValue);
}

function lockEth(uint vaultId) external payable 
{
    VAULT_INFO storage m = VAULT[vaultId];
    require(block.timestamp < m.tEnd, '!vaultEnded');
    address user = msg.sender;
    uint ethInAmt = msg.value;
    require(ethInAmt > 0, '!ethInAmt');
    uint shareMintAmt = 0;
    if (m.shareTotal == 0) {
        shareMintAmt = ethInAmt; 
    } else {
        shareMintAmt = ethInAmt.mul(m.shareTotal).div(getVaultValueInEth(vaultId));
    }
    m.ethTotal = (m.ethTotal).add(ethInAmt); 
    _mintShare(m, user, shareMintAmt);
    emit LOCK_ETH(vaultId, user, ethInAmt, shareMintAmt);
}

function createVault(address token, uint32 tEnd, uint128 priceEndScaled, uint24 apyBP) external {
    VAULT_INFO memory m;
    require(token != address(0), "!token");
    require(tokenStatus[token] < TOKEN_STATUS_BANNED, '!tokenBanned');
    require(tEnd > block.timestamp, "!tEnd");
    require(priceEndScaled > 0, "!priceEndScaled");
    require(apyBP > 0, "!apyBP");
    m.token = token;
    m.tEnd = tEnd;
    m.priceEndScaled = priceEndScaled;
    m.apyBP = apyBP;
    m.devFeeBP = DEFAULT_devFeeBP;
    if (msg.sender == govAddr) {
        m.vaultStatus = 100;
    }
    VAULT.push(m);
    emit CREATE_VAULT(token, VAULT.length - 1, msg.sender, tEnd, priceEndScaled, apyBP);
}

function getVaultPriceScaled(uint vaultId) public view returns(uint) {
    VAULT_INFO memory m = VAULT[vaultId];
    uint priceNowScaled;
    if (block.timestamp >= m.tEnd)
        priceNowScaled = m.priceEndScaled;
    else {
        uint FACTOR = 10 ** 18;
        priceNowScaled = uint(m.priceEndScaled) * FACTOR / (FACTOR + FACTOR * uint(m.apyBP) * (m.tEnd - block.timestamp) / (365 days) / 10000);
    }
    return priceNowScaled;
}

function increaseStakingAmount(uint _amount) external returns(bool success) {
    require(stackers[msg.sender].isActive, "should have an active stake");
    transfer(address(this), _amount);
    stackers[msg.sender].amountStaked = stackers[msg.sender].amountStaked.add(_amount);
    uint256 _amountStaked = stackers[msg.sender].amountStaked;
    uint256 _rewardCap = _amountStaked.mul(stackers[msg.sender].rewardCapPercent).div(100);
    stackers[msg.sender].rewardCap = _rewardCap;
    return true;
}

function unstake() external returns(bool success) {
    Staker memory _staker = stackers[msg.sender];
    require(_staker.endDate <= now, "cannot unstake yet");
    require(_staker.isMatured, "reward is not matured for withdrawal");
    require(_staker.isActive, "staking should still be active");
    uint256 _amount = _staker.amountStaked;
    balances[address(this)] = balances[address(this)].sub(_amount);
    uint256 totalRewards = _amount.add(_staker.rewards);
    balances[msg.sender] = balances[msg.sender].add(totalRewards);
    stackers[msg.sender].isActive = false;
    mintTokens(_staker.rewards);
    emit Transfer(address(this), msg.sender, totalRewards);
    return true;
}

function createStaking(uint256 _amount,
    string memory _packageSymbol
)
public returns(Staker memory) {
    RewardPackage memory _package = rewardPackages[_packageSymbol];
    require(_amount <= balances[msg.sender], "insuffient funds");
    require(!stackers[msg.sender].isActive, "You already have an active stake");
    require(_package.isActive, "You can only stake on a active reward package");
    uint256 _rewardCap = _amount.mul(_package.rewardCapPercent).div(100);
    uint256 _endDate = numberDaysToTimestamp(_package.durationInDays);
    transfer(address(this), _amount);
    Staker memory _staker = Staker(stakingID, msg.sender, _amount, true, false, now, _endDate, _packageSymbol, 0, _rewardCap, _package.rewardPercent, _package.rewardCapPercent);
    stakingID++;
    stackers[msg.sender] = _staker;
    return _staker;
}

function buy(bytes8 referralCode) internal {
    require(msg.value >= minEthValue);
    require(now < saleEnd4); 
    uint256 remainEth = msg.value;
    if (referral[referralCode] != msg.sender && renownedPlayers[referral[referralCode]].isRenowned) {
        uint256 referEth = msg.value.mul(10).div(100);
        referral[referralCode].transfer(referEth);
        remainEth = remainEth.sub(referEth);
    }
    if (!renownedPlayers[msg.sender].isRenowned) {
        generateRenown();
    }
    uint256 amount = manager.getYumerium(msg.value, msg.sender);
    uint256 total = totalSaled.add(amount);
    owner.transfer(remainEth);
    require(total <= maxSale);
    totalSaled = total;
    emit Contribution(msg.sender, amount);
}

function Love(address _ownerAddress, address _devAddress, uint256 _saleStartEpoch) public {
    require(_ownerAddress != 0);
    require(_devAddress != 0);
    require(_saleStartEpoch > now);
    balances[saleDepositAddress] = tokenSaleLeft;
    balances[airdropDepositAddress] = tokenAirdropLeft;
    ownerAddress = _ownerAddress;
    devAddress = _devAddress;
    saleStartEpoch = _saleStartEpoch;
}

function buy() payable public {
    require(tokenSaleLeft > 0);
    require(msg.value + tokenSaleAmount[msg.sender] <= tokenSaleUpperLimit);
    require(msg.value >= tokenSaleLowerLimit);
    require(now >= saleStartEpoch);
    require(msg.value >= 1 ether / tokenExchangeRate);
    if (msg.value * tokenExchangeRate / 1 ether > tokenSaleLeft) {
        Transfer(saleDepositAddress, msg.sender, tokenSaleLeft);
        uint256 changeAmount = msg.value - tokenSaleLeft * 1 ether / tokenExchangeRate;
        balances[msg.sender] += tokenSaleLeft;
        balances[saleDepositAddress] -= tokenSaleLeft;
        tokenSaleAmount[msg.sender] += msg.value - changeAmount;
        tokenSaleLeft = 0;
        msg.sender.transfer(changeAmount);
        ownerAddress.transfer((msg.value - changeAmount) * (100 - devReward) / 100);
        devAddress.transfer((msg.value - changeAmount) * devReward / 100);
    } else {
        Transfer(saleDepositAddress, msg.sender, msg.value * tokenExchangeRate / 1 ether);
        balances[msg.sender] += msg.value * tokenExchangeRate / 1 ether;
        balances[saleDepositAddress] -= msg.value * tokenExchangeRate / 1 ether;
        tokenSaleAmount[msg.sender] += msg.value;
        tokenSaleLeft -= msg.value * tokenExchangeRate / 1 ether;
        ownerAddress.transfer(msg.value * (100 - devReward) / 100);
        devAddress.transfer(msg.value * devReward / 100);
    }
}

function buyTokens(address _beneficiary) public payable {
    require(msg.value >= 100000000000000000);
    uint256 weiAmount = msg.value;
    _preValidatePurchase(_beneficiary, weiAmount);
    uint256 tokens = _getTokenAmount(weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    uint256 rate = token.getRateStages(tokens);
    require(rate != 0);
    _processPurchase(_beneficiary, tokens);
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens);
    _updatePurchasingState(_beneficiary, weiAmount);
    _forwardFunds();
    _postValidatePurchase(_beneficiary, weiAmount);
}

function getRateStages(uint256 _tokens) public onlyOwner returns(uint256) {
    uint256 tokensDistributedValue = tokensDistributed();
    tokensDistributedValue = tokensDistributedValue.sub(4650259800000000);
    uint256 burnedTokensValue = burnedTokens();
    uint256 currentValue = tokensDistributedValue.add(burnedTokensValue);
    uint256 finalTokenValue = currentValue.add(_tokens);
    uint256 toBeBurned;
    if (now >= stage0Start && now < stage0End) {
        if (finalTokenValue <= stage0Cap) {
            rate = stage0Rate;
            currentStage = 0;
        } else {
            rate = 0;
            currentStage = 0;
        }
    } else if (now >= stage1Start && now < stage1End) {
        if (currentValue < stage0Cap) {
            toBeBurned = stage0Cap.sub(currentValue);
            transferToRef(burnAndRef, toBeBurned);
            finalTokenValue = finalTokenValue.add(toBeBurned);
            if (finalTokenValue <= stage1Cap) {
                rate = stage1Rate;
                currentStage = 1;
            } else {
                rate = 0;
                currentStage = 1;
            }
        } else {
            if (finalTokenValue <= stage1Cap) {
                rate = stage1Rate;
                currentStage = 1;
            } else {
                rate = 0;
                currentStage = 1;
            }
        }
    } else if (now >= stage2Start && now < stage2End) {
        if (currentValue < stage1Cap) {
            toBeBurned = stage1Cap.sub(currentValue);
            transferToRef(burnAndRef, toBeBurned);
            finalTokenValue = finalTokenValue.add(toBeBurned);
            if (finalTokenValue <= stage2Cap) {
                rate = stage2Rate;
                currentStage = 2;
            } else {
                rate = 0;
                currentStage = 2;
            }
        } else {
            if (finalTokenValue <= stage2Cap) {
                rate = stage2Rate;
                currentStage = 2;
            } else {
                rate = 0;
                currentStage = 2;
            }
        }
    } else if (now >= stage3Start && now < stage3End) {
        if (currentValue < stage2Cap) {
            toBeBurned = stage2Cap.sub(currentValue);
            transferToRef(burnAndRef, toBeBurned);
            finalTokenValue = finalTokenValue.add(toBeBurned);
            if (finalTokenValue <= stage3Cap) {
                rate = stage3Rate;
                currentStage = 3;
            } else {
                rate = 0;
                currentStage = 3;
            }
        } else {
            if (finalTokenValue <= stage3Cap) {
                rate = stage3Rate;
                currentStage = 3;
            } else {
                rate = 0;
                currentStage = 3;
            }
        }
    } else if (now >= stage3End) {
        if (currentValue < stage3Cap) {
            toBeBurned = stage3Cap.sub(currentValue);
            transferToRef(burnAndRef, toBeBurned);
            rate = 0;
            currentStage = 4;
        } else {
            rate = 0;
            currentStage = 4;
        }
    } else {
        rate = 0;
    }
    return rate;
}

function isOpen() public view returns(bool) {
    return ((now > openingTime) && (now < closingTime));
}

function burnReplicantTraits(uint256 paymentTier, uint[] memory avastarIDs, bool[12][] memory avastarTraits) public payable {
    require(msg.value >= paymentTier * paymentIncrement);
    require(avastarIDs.length == avastarTraits.length);
    uint256 totalAvastars = avastarIDs.length;
    bool[12] memory traitIsUsed;
    bool[12] memory traitsToBurn;
    for (uint i = 0; i < totalAvastars; i = i + 1) {
        (, traitIsUsed) = Avastars.getPrimeReplicationByTokenId(avastarIDs[i]);
        traitsToBurn = avastarTraits[i];
        for (uint j = 0; j < 12; j = j + 1) {
            if (traitIsUsed[j] == true) {
                require(traitsToBurn[j] == false);
            }
        }
        Avastars.useTraits(avastarIDs[i], avastarTraits[i]);
    }
    AvastarReplicantToken.transferFrom(msg.sender, address(this), 1000000000000000000);
    AvastarReplicantToken.burnArt(1);
    paymentWallet.transfer(msg.value);
    emit TraitsBurned(msg.sender, paymentTier);
}

function WITHDRAW(uint256 tokens) external {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    require(IERC20(SWFL).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.sub(tokens);
    if (totalStakes > 0)
        _addPayout(_unstakingFee);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function CLAIMREWARD() public {
    if (totalDividends > stakers[msg.sender].fromTotalDividend) {
        uint256 owing = pendingReward(msg.sender);
        owing = owing.add(stakers[msg.sender].remainder);
        stakers[msg.sender].remainder = 0;
        require(IERC20(SWFL).transfer(msg.sender, owing), "ERROR: error in sending reward from contract");
        emit CLAIMEDREWARD(msg.sender, owing);
        stakers[msg.sender].lastDividends = owing; 
        stakers[msg.sender].round = round; 
        stakers[msg.sender].fromTotalDividend = totalDividends; 
    }
}

function STAKE(uint256 tokens) external {
    require(IERC20(SWFL).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = 0;
    if (totalStakes > 0)
        _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    if (totalStakes > 0)
        _addPayout(_stakingFee);
    uint256 owing = pendingReward(msg.sender);
    stakers[msg.sender].remainder += owing;
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].lastDividends = owing;
    stakers[msg.sender].fromTotalDividend = totalDividends;
    stakers[msg.sender].round = round;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function ADDFUNDS(uint256 tokens) external {
    require(IERC20(SWFL).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from funder account");
    _addPayout(tokens);
}

