    uint256 amount = msg.value;
    amount = amount.mul(REWARD_RATE);
    require(amount <= TOKEN_CONTRACT_ADDRESS.balanceOf(this));
    address(OWNER_ADDRESS).transfer(msg.value);
    tokenTransfer(amount);
}

function getPokemonCD(uint _pokemonId) public view returns(uint _pokemonCD) {
    if (battleCD[_pokemonId] <= now) {
        return 0;
    } else {
        return battleCD[_pokemonId] - now;
    }
}

function startpublicBattle(uint _pokemon1, uint _pokemon2) internal {
    require(publicBattlepm1 != 99999 && publicBattlepm2 != 99999);
    uint256 i = uint256(sha256(block.timestamp, block.number - i - 1)) % 100 + 1;
    uint256 threshold = dataCalc(_pokemon1, _pokemon2);
    if (i <= threshold) {
        pbWinner = publicBattlepm1;
    } else {
        pbWinner = publicBattlepm2;
    }
    battleresults.push(Battlelog(_pokemon1, _pokemon2, pbWinner));
    distributePrizes();
}

function initialBattle(uint _pokemonId1, uint _pokemonId2) public {
    require(pokemonContract.getPokemonOwner(_pokemonId1) == msg.sender);
    require(isPaused == false);
    require(_pokemonId1 != _pokemonId2);
    require(getPokemonCD(_pokemonId1) == 0);
    assert(publicbattlestart != true);
    publicBattlepm1 = _pokemonId1;
    publicBattlepm2 = _pokemonId2;
    publicbattlestart = true;
    pokemonGuessNumber[publicBattlepm1] = 0;
    pokemonGuessNumber[publicBattlepm2] = 0;
    pokemonGuessPrize[publicBattlepm1] = 0;
    pokemonGuessPrize[publicBattlepm2] = 0;
    isPaused = false;
    battleCD[_pokemonId1] = now + 12 * 1 hours;
    totalGuess = totalPool.div(100);
}

function withdrawAmount(uint256 _amount) onlyContractCreator() public {
    msg.sender.transfer(_amount);
    totalPool = totalPool - _amount;
}

function guess(uint _pokemonId) public payable {
    require(isPaused == false);
    assert(msg.value > 0);
    assert(_pokemonId == publicBattlepm1 || _pokemonId == publicBattlepm2);
    uint256 calcValue = msg.value;
    uint256 cutFee = calcValue.div(16);
    calcValue = calcValue - cutFee;
    pokemonContract.getPokemonOwner(_pokemonId).transfer(cutFee.div(2));
    devFeeAddress.transfer(cutFee.div(2));
    totalGuess += calcValue;
    pokemonGuessNumber[_pokemonId]++;
    pokemonGuessPrize[_pokemonId] = pokemonGuessPrize[_pokemonId] + calcValue;
    if (_pokemonId == publicBattlepm1) {
        if (playerGuessPM1Number[msg.sender] != 0) {
            playerGuessPM1Number[msg.sender] = playerGuessPM1Number[msg.sender] + calcValue;
        } else {
            pokemonGuessPlayers[_pokemonId].push(msg.sender);
            playerGuessPM1Number[msg.sender] = calcValue;
        }
    } else {
        if (playerGuessPM2Number[msg.sender] != 0) {
            playerGuessPM2Number[msg.sender] = playerGuessPM2Number[msg.sender] + calcValue;
        } else {
            pokemonGuessPlayers[_pokemonId].push(msg.sender);
            playerGuessPM2Number[msg.sender] = calcValue;
        }
    }
    if (pokemonGuessNumber[publicBattlepm1] + pokemonGuessNumber[publicBattlepm2] > 20) {
        startpublicBattle(publicBattlepm1, publicBattlepm2);
    }
}

function distributePrizes() internal {
    totalGuess = totalGuess - totalGuess.div(100);
    for (uint counter = 0; counter < pokemonGuessPlayers[pbWinner].length; counter++) {
        guesser = pokemonGuessPlayers[pbWinner][counter];
        if (pbWinner == publicBattlepm1) {
            guesser.transfer(playerGuessPM1Number[guesser].mul(totalGuess).div(pokemonGuessPrize[pbWinner]));
        } else {
            guesser.transfer(playerGuessPM2Number[guesser].mul(totalGuess).div(pokemonGuessPrize[pbWinner]));
        }
    }
    uint del;
    if (pbWinner == publicBattlepm1) {
        del = publicBattlepm2;
    } else {
        del = publicBattlepm1;
    }
    for (uint cdel1 = 0; cdel1 < pokemonGuessPlayers[pbWinner].length; cdel1++) {
        guesser = pokemonGuessPlayers[pbWinner][cdel1];
        if (pbWinner == publicBattlepm1) {
            delete playerGuessPM1Number[guesser];
        } else {
            delete playerGuessPM2Number[guesser];
        }
    }
    for (uint cdel = 0; cdel < pokemonGuessPlayers[del].length; cdel++) {
        guesser = pokemonGuessPlayers[del][cdel];
        if (del == publicBattlepm1) {
            delete playerGuessPM1Number[guesser];
        } else {
            delete playerGuessPM2Number[guesser];
        }
    }
    pokemonGuessNumber[publicBattlepm1] = 0;
    pokemonGuessNumber[publicBattlepm2] = 0;
    pokemonGuessPrize[publicBattlepm1] = 0;
    pokemonGuessPrize[publicBattlepm2] = 0;
    delete pokemonGuessPlayers[publicBattlepm2];
    delete pokemonGuessPlayers[publicBattlepm1];
    counter = 0;
    publicBattlepm1 = 99999;
    publicBattlepm2 = 99999;
    pbWinner = 99999;
    totalGuess = 0;
    publicbattlestart = false;
}

function pay(uint256 chainID, address token, address recipient, uint256 amount, uint256 txhash) public onlyManager {
    require(amount > 0);
    require(!receipt[txhash]);
    if (token == ETH) {
        TransferHelper.safeTransferETH(recipient, amount);
    } else {
        TransferHelper.safeTransfer(token, recipient, amount);
    }
    receipt[txhash] = true;
    emit Pay(
        recipient,
        token,
        chainID,
        amount,
        txhash
    );
}

function PayoutStaking(uint i, address _address) public {
    if (blockPayouts) revert('payouts blocked'); 
    if (daysParticipated[msg.sender].length == 0) revert('No Staking');
    if (block.timestamp >= startDate + (daysParticipated[msg.sender][0] * 86400) + 31556926 + contingency) {
        if (StakingPaid[msg.sender][i]) revert('Stake already paid');
        uint interestRateToPay = mneSentPerDay[msg.sender][i] * maxInterestRate[daysParticipated[msg.sender][i]] * 1000000000000000 / mnePerDay[daysParticipated[msg.sender][i]];
        uint coinsToMint = mneSentPerDay[msg.sender][i] * interestRateToPay / 1000000000000000 / 100;
        uint amountToPay = mneSentPerDay[msg.sender][i] + coinsToMint;
        external1.mintNewCoins(coinsToMint);
        if (_address != 0x0000000000000000000000000000000000000000)
            mneContract.transfer(_address, amountToPay);
        else
            mneContract.transfer(msg.sender, amountToPay);
        newStakingCoins += coinsToMint;
        paidStakingCoins += amountToPay;
        StakingPaid[msg.sender][i] = true;
    } else {
        revert('Payout Date Not Valid');
    }
}

function _attack(uint _heroId, uint _genes, uint _heroStrength, uint _heroCurrentHealth) internal {
    Monster storage monster = heroIdToMonster[_heroId];
    uint8 currentLevel = monster.level;
    uint heroPower;
    (heroPower, , , , ) = edCoreContract.getHeroPower(_genes, dungeonDifficulty);
    uint damageByMonster;
    uint damageByHero;
    damageByHero = (_heroStrength * 1e9 + heroPower * 1e9 / (10 * (1 + _getRandomNumber(5)))) / tx.gasprice;
    bool isMonsterDefeated = damageByHero >= monster.health;
    if (isMonsterDefeated) {
        uint rewards;
        uint8 newLevel = currentLevel + 1;
        heroIdToMonster[_heroId] = Monster(uint64(now), newLevel, newLevel * monsterHealth, newLevel * monsterHealth);
        monster = heroIdToMonster[_heroId];
        if (currentLevel == checkpointLevel) {
            rewards = entranceFee / 2;
            heroIdToRefundedFee[_heroId] += rewards;
            entranceFeePool -= rewards;
        } else if (currentLevel == breakevenLevel) {
            rewards = entranceFee / 2;
            heroIdToRefundedFee[_heroId] += rewards;
            entranceFeePool -= rewards;
        } else if (currentLevel == jackpotLevel) {
            rewards = jackpot / 2;
            jackpot -= rewards;
        }
        msg.sender.transfer(rewards);
    } else {
        monster.health -= uint8(damageByHero);
        if (now > monster.creationTime + monsterFleeTime) {
            damageByMonster = currentLevel + monsterStrength;
        } else {
            if (currentLevel >= 2) {
                damageByMonster = _getRandomNumber(currentLevel / 2);
            }
        }
    }
    if (damageByMonster >= _heroCurrentHealth) {
        heroIdToHealth[_heroId] = 0;
        uint addToJackpot = entranceFee - heroIdToRefundedFee[_heroId];
        if (addToJackpot > 0) {
            jackpot += addToJackpot;
            entranceFeePool -= addToJackpot;
            heroIdToRefundedFee[_heroId] += addToJackpot;
        }
        assert(addToJackpot <= entranceFee);
    } else {
        if (damageByMonster > 0) {
            heroIdToHealth[_heroId] -= damageByMonster;
        }
        if (now > monster.creationTime + monsterFleeTime) {
            currentLevel++;
            heroIdToMonster[_heroId] = Monster(uint64(monster.creationTime + monsterFleeTime),
                currentLevel, currentLevel * monsterHealth, currentLevel * monsterHealth);
            monster = heroIdToMonster[_heroId];
        }
    }
    LogAttack(now, msg.sender, _heroId, currentLevel, damageByHero, damageByMonster, isMonsterDefeated, rewards);
}

