    address owner = ownerOf(_tokenId);
    require(msg.sender == owner);
    avatar.isHibernated = false;
    emit WokenUp(_tokenId);
}

function evolveCryptoAvatar(
    uint256 _id,
    uint256 _statistics,
    uint256 _avatarType,
    uint256 _level,
    uint256 _experience
)
onlyWhitelisted
external {
    require(_avatarType == uint256(uint32(_avatarType)));
    require(_level == uint256(uint32(_level)));
    require(_experience == uint256(uint32(_experience)));
    require(exists(_id));
    CryptoAvatar storage avatar = avatars[_id];
    require(!avatar.isHibernated);
    avatar.statistics = _statistics;
    avatar.avatarType = uint32(_avatarType);
    avatar.level = uint32(_level);
    avatar.experience = uint32(_experience);
    emit Evolution(_id, _statistics, uint256(_avatarType), uint256(_level), uint256(_experience));
