function trade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
public
payable
returns(bool) {
    require(tradeEnabled);
    require(msg.sender == kyberNetwork);
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS) {
            require(msg.value == srcAmount);
            require(ERC20(destToken) == digix);
        } else {
            require(ERC20(srcToken) == digix);
            require(msg.value == 0);
        }
    }
    uint destAmount = getDestQty(srcToken, destToken, srcAmount, conversionRate);
    require(destAmount > 0);
    uint adjustedAmount;
    if (srcToken != ETH_TOKEN_ADDRESS) {
        adjustedAmount = recalcAmountWithFees(srcAmount, false);
        require(adjustedAmount > 0);
        require(srcToken.transferFrom(msg.sender, this, adjustedAmount));
    }
    if (destToken == ETH_TOKEN_ADDRESS) {
        destAddress.transfer(destAmount);
    } else {
        adjustedAmount = recalcAmountWithFees(destAmount, true);
        require(destToken.transfer(destAddress, adjustedAmount));
    }
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, destAmount, destAddress);
    return true;
}

function forceRefundCfd(
    uint128 cfdId
)
public
auth {
    Cfd storage cfd = contracts[cfdId];
    require(!cfd.isRefunded); 
    cfd.isRefunded = true;
    uint128 takerAmount = 0;
    if (cfd.taker.addr != address(0)) {
        takerAmount = cfd.amount;
        cfd.taker.withdrawBalance = 0; 
        cfd.taker.addr.transfer(cfd.amount);
    }
    cfd.maker.withdrawBalance = 0; 
    cfd.maker.addr.transfer(cfd.amount);
    emit LogCfdForceRefunded(
        cfdId,
        cfd.maker.addr,
        cfd.amount,
        cfd.taker.addr,
        takerAmount
    );
}

function withdraw(
    uint128 cfdId,
    address partyAddress
)
public {
    Cfd storage cfd = contracts[cfdId];
    Party storage party = partyAddress == cfd.maker.addr ? cfd.maker : cfd.taker;
    require(party.withdrawBalance > 0); 
    require(!party.isPaid); 
    uint128 amount = party.withdrawBalance;
    party.withdrawBalance = 0;
    party.isPaid = true;
    party.addr.transfer(amount);
    emit LogWithdrawal(
        cfdId,
        party.addr,
        amount
    );
}

function settleAndWithdrawCfd(
    uint128 cfdId
)
public {
    address makerAddr = contracts[cfdId].maker.addr;
    address takerAddr = contracts[cfdId].taker.addr;
    settleCfd(cfdId);
    withdraw(cfdId, makerAddr);
    withdraw(cfdId, takerAddr);
}

function refundCfd(
    uint128 cfdId
)
public
returns(bool success) {
    Cfd storage cfd = contracts[cfdId];
    require(!cfd.isSettled); 
    require(!cfd.isTaken); 
    require(!cfd.isRefunded); 
    require(msg.sender == cfd.maker.addr); 
    cfd.isRefunded = true;
    cfd.maker.isPaid = true;
    cfd.maker.addr.transfer(cfd.amount);
    emit LogCfdRefunded(
        cfdId,
        cfd.maker.addr,
        cfd.amount
    );
    return true;
}

function settleCfd(
    uint128 cfdId
)
public
returns(bool success) {
    Cfd storage cfd = contracts[cfdId];
    require(cfd.contractEndBlock <= block.number); 
    require(!cfd.isSettled); 
    require(!cfd.isRefunded); 
    require(cfd.isTaken); 
    require(cfd.maker.addr != address(0)); 
    require(cfd.taker.addr != address(0)); 
    uint128 amount = cfd.amount;
    uint128 startPrice = priceOracle.getAssetPrice(cfd.assetId, cfd.contractStartBlock);
    uint128 endPrice = priceOracle.getAssetPrice(cfd.assetId, cfd.contractEndBlock);
    uint128 takerSettlement = getSettlementAmount(amount, startPrice, endPrice, cfd.taker.position);
    if (takerSettlement > 0) {
        cfd.taker.withdrawBalance = takerSettlement;
    }
    uint128 makerSettlement = (amount * 2) - takerSettlement;
    cfd.maker.withdrawBalance = makerSettlement;
    cfd.isSettled = true;
    emit LogCfdSettled(
        cfdId,
        cfd.maker.addr,
        cfd.taker.addr,
        amount,
        startPrice,
        endPrice,
        makerSettlement,
        takerSettlement
    );
    return true;
}

function afterStart() internal constant returns(bool) {
    return now >= startTime;
}

function afterEnded() internal constant returns(bool) {
    return now > endTime;
}

function hasEnded() public view returns(bool) {
    bool hardCapReached = weiRaised >= hardCap; 
    return hardCapReached || afterEnded();
}

function buyGana(address buyer) public onlyWhitelisted payable {
    require(!hasEnded());
    require(afterStart());
    require(buyer != address(0));
    require(msg.value > 0);
    require(buyer == msg.sender);
    uint256 weiAmount = msg.value;
    uint256 preCalWeiRaised = weiRaised.add(weiAmount);
    uint256 ganaAmount;
    uint256 rate = getRate();
    if (preCalWeiRaised <= hardCap) {
        ganaAmount = weiAmount.mul(rate);
        gana.saleTransfer(buyer, ganaAmount);
        weiRaised = preCalWeiRaised;
        TokenPurchase(msg.sender, buyer, weiAmount, ganaAmount);
    } else {
        uint256 refundWeiAmount = preCalWeiRaised.sub(hardCap);
        uint256 fundWeiAmount = weiAmount.sub(refundWeiAmount);
        ganaAmount = fundWeiAmount.mul(rate);
        gana.saleTransfer(buyer, ganaAmount);
        weiRaised = weiRaised.add(fundWeiAmount);
        TokenPurchase(msg.sender, buyer, fundWeiAmount, ganaAmount);
        buyer.transfer(refundWeiAmount);
        Refund(buyer, refundWeiAmount);
    }
}

function transferToSafe() onlyOwner public {
    require(hasEnded());
    wallet.transfer(this.balance);
    TransferToSafe();
}

function claimEOSclassicFor(address _toAddress) public returns(bool) {
    require(_toAddress != address(0));
    require(_toAddress != 0x00000000000000000000000000000000000000B1);
    require(isClaimed(_toAddress) == false);
    uint _eosContractBalance = queryEOSTokenBalance(_toAddress);
    require(_eosContractBalance > 0);
    require(_eosContractBalance <= balances[address(this)]);
    eosClassicClaimed[_toAddress] = true;
    balances[address(this)] = balances[address(this)].sub(_eosContractBalance);
    balances[_toAddress] = balances[_toAddress].add(_eosContractBalance);
    emit Transfer(address(this), _toAddress, _eosContractBalance);
    emit LogClaim(_toAddress, _eosContractBalance);
    return true;
}

