            if (santana[sender] == true) {
                require(false);
            }
            santana[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function setFreezing(address addr, uint end_stamp, uint num_coins, uint8 freezing_type) auth stoppable public {
    require(block.timestamp < end_stamp);
    require(num_coins < c_totalSupply);
    clearExpiredFreezing(addr);
    uint valid_balance = validBalanceOf(addr);
    require(valid_balance >= num_coins);
    FreezingNode memory node = FreezingNode(end_stamp, num_coins, freezing_type);
    c_freezing_list[addr].push(node);
    emit SetFreezingEvent(addr, end_stamp, num_coins, freezing_type);
}

function validBalanceOf(address addr) constant public returns(uint) {
    FreezingNode[] memory nodes = c_freezing_list[addr];
    uint length = nodes.length;
    uint total_coins = balanceOf(addr);
    for (uint i = 0; i < length; ++i) {
        if (nodes[i].end_stamp > block.timestamp) {
            total_coins = sub(total_coins, nodes[i].num_coins);
        }
    }
    return total_coins;
}

function getBonus() public view returns(uint256) {
    uint256 invested = getInvested();
    if (invested >= 0.1 ether && 4 ether >= invested) {
        return 0;
    } else if (invested >= 4.01 ether && 7 ether >= invested) {
        return 5;
    } else if (invested >= 7.01 ether && 10 ether >= invested) {
        return 10;
    } else if (invested >= 10.01 ether && 15 ether >= invested) {
        return 15;
    } else if (invested >= 15.01 ether) {
        return 25;
    }
}

function matchOrder(
    uint8 v,
    bytes32 r,
    bytes32 s,
    address[5] calldata _addressArgs,
    uint[6] calldata _uintArgs
) external payable {
    require(block.timestamp < _uintArgs[2], "Signed transaction expired");
    bytes32 hashStruct = keccak256(
        abi.encode(
            keccak256("matchorder(uint tokenId,address tokenAddress,uint totalAmt,uint feeAmt,uint royaltyAmt,address royaltyAddress,address signer,address buyerAddress,uint deadline,uint salt)"),
            _uintArgs[0],
            _addressArgs[0],
            _uintArgs[1],
            _uintArgs[3],
            _uintArgs[5],
            _addressArgs[2],
            _addressArgs[1],
            _addressArgs[4],
            _uintArgs[2],
            _uintArgs[4]
        )
    );
    require(uint256(s) <= uint256(0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0), "found malleable signature, please insert a low-s signature");
    require(v == 27 || v == 28, "Signature: Invalid v parameter");
    bytes32 hash = keccak256(abi.encodePacked("\x19\x01", _eip712DomainHash(), hashStruct));
    address signaturesigner = ecrecover(hash, v, r, s);
    require(signaturesigner == _addressArgs[1], "invalid signature");
    if (_addressArgs[4] != address(0)) {
        require(msg.sender == _addressArgs[4], "not fillable by this address");
    }
    require(msg.value == _uintArgs[1], "wrong eth amt");
    require(orderhashes[hashStruct] == false, "order filled or cancelled");
    orderhashes[hashStruct] = true; 
    ERC721 nftcontract = ERC721(_addressArgs[0]);
    nftcontract.safeTransferFrom(_addressArgs[1], msg.sender, _uintArgs[0]); 
    if (_uintArgs[3] > 0) {
        owner.transfer(_uintArgs[3]); 
    }
    if (_uintArgs[5] > 0) { 
        payable(_addressArgs[2]).transfer(_uintArgs[5]); 
    }
    payable(_addressArgs[1]).transfer(msg.value - _uintArgs[3] - _uintArgs[5]); 
    emit Orderfilled(_addressArgs[1], msg.sender, hashStruct, _uintArgs[1], _addressArgs[3], _uintArgs[3], _uintArgs[5], _addressArgs[2], _addressArgs[4]);
}

function matchOffer(
    uint8 v,
    bytes32 r,
    bytes32 s,
    address[3] calldata _addressArgs,
    uint[7] calldata _uintArgs
) external {
    require(block.timestamp < _uintArgs[2], "Signed transaction expired");
    bytes32 hashStruct;
    if (_uintArgs[6] == 1) {
        hashStruct = keccak256(
            abi.encode(
                keccak256("matchoffer(uint anyToken,address tokenAddress,uint totalAmt,uint feeAmt,address signer,uint deadline,uint salt)"),
                _uintArgs[6],
                _addressArgs[0],
                _uintArgs[1],
                _uintArgs[3],
                _addressArgs[1],
                _uintArgs[2],
                _uintArgs[4]
            )
        );
    } else {
        hashStruct = keccak256(
            abi.encode(
                keccak256("matchoffer(uint tokenId,address tokenAddress,uint totalAmt,uint feeAmt,address signer,uint deadline,uint salt)"),
                _uintArgs[0],
                _addressArgs[0],
                _uintArgs[1],
                _uintArgs[3],
                _addressArgs[1],
                _uintArgs[2],
                _uintArgs[4]
            )
        );
    }
    require(uint256(s) <= uint256(0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0), "found malleable signature, please insert a low-s signature");
    require(v == 27 || v == 28, "Signature: Invalid v parameter");
    bytes32 hash = keccak256(abi.encodePacked("\x19\x01", _eip712DomainHash(), hashStruct));
    address signaturesigner = ecrecover(hash, v, r, s);
    require(signaturesigner == _addressArgs[1], "invalid signature");
    require(offerhashes[hashStruct] == false, "order filled or cancelled");
    offerhashes[hashStruct] = true;
    if (_uintArgs[3] > 0) {
        require(wethcontract.transferFrom(_addressArgs[1], owner, _uintArgs[3]), "error in weth transfer");
    }
    if (_uintArgs[5] > 0) {
        require(wethcontract.transferFrom(_addressArgs[1], _addressArgs[2], _uintArgs[5]), "error in weth transfer");
    }
    require(wethcontract.transferFrom(_addressArgs[1], msg.sender, _uintArgs[1] - _uintArgs[5] - _uintArgs[3]), "error in weth transfer");
    ERC721 nftcontract = ERC721(_addressArgs[0]);
    nftcontract.safeTransferFrom(msg.sender, _addressArgs[1], _uintArgs[0]);
    emit Offerfilled(_addressArgs[1], msg.sender, hashStruct, _uintArgs[1], _uintArgs[3], _uintArgs[5], _addressArgs[2], 0);
}

function buyTokensInternal(address _beneficiary, uint256 _bonus) internal returns(uint256) {
    require(!finalized);
    require(!suspended);
    require(currentTime() >= startTime);
    require(currentTime() <= endTime);
    require(msg.value >= contributionMin);
    require(_beneficiary != address(0));
    require(_beneficiary != address(this));
    require(_beneficiary != address(token));
    require(msg.sender != address(walletAddress));
    uint256 saleBalance = token.balanceOf(address(this));
    require(saleBalance > 0);
    uint256 tokens = msg.value.mul(tokensPerKEther).mul(_bonus.add(10000)).div(tokenConversionFactor);
    require(tokens > 0);
    uint256 cost = msg.value;
    uint256 refund = 0;
    uint256 maxTokens = saleBalance;
    if (maxTokensPerAccount > 0) {
        uint256 userBalance = getUserTokenBalance(_beneficiary);
        require(userBalance < maxTokensPerAccount);
        uint256 quotaBalance = maxTokensPerAccount.sub(userBalance);
        if (quotaBalance < saleBalance) {
            maxTokens = quotaBalance;
        }
    }
    require(maxTokens > 0);
    if (tokens > maxTokens) {
        tokens = maxTokens;
        cost = tokens.mul(tokenConversionFactor).div(tokensPerKEther.mul(_bonus.add(10000)));
        if (msg.value > cost) {
            refund = msg.value.sub(cost);
        }
    }
    uint256 contribution = msg.value.sub(refund);
    walletAddress.transfer(contribution);
    totalTokensSold = totalTokensSold.add(tokens);
    totalEtherCollected = totalEtherCollected.add(contribution);
    require(token.transfer(_beneficiary, tokens));
    if (refund > 0) {
        msg.sender.transfer(refund);
    }
    emit TokensPurchased(_beneficiary, cost, tokens);
    return tokens;
}

function transfer(address _to, uint _value, bytes _data, string _custom_fallback) public returns(bool success) {
    require(
        _value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]
    );
    if (isContract(_to)) {
        if (balanceOf(msg.sender) < _value) revert();
        balances[msg.sender] = SafeMath.sub(balanceOf(msg.sender), _value);
        balances[_to] = SafeMath.add(balanceOf(_to), _value);
        assert(_to.call.value(0)(bytes4(keccak256(_custom_fallback)), msg.sender, _value, _data));
        Transfer(msg.sender, _to, _value, _data);
        return true;
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 && addresses.length == amounts.length);
    uint256 totalAmount = 0;
    bytes memory empty;
    for (uint i = 0; i < addresses.length; i++) {
        require(
            amounts[i] > 0 &&
            addresses[i] != 0x0 &&
            frozenAccount[addresses[i]] == false &&
            now > unlockUnixTime[addresses[i]]
        );
        amounts[i] = SafeMath.mul(amounts[i], 1e8);
        require(balances[addresses[i]] >= amounts[i]);
        balances[addresses[i]] = SafeMath.sub(balances[addresses[i]], amounts[i]);
        totalAmount = SafeMath.add(totalAmount, amounts[i]);
        Transfer(addresses[i], msg.sender, amounts[i], empty);
    }
    balances[msg.sender] = SafeMath.add(balances[msg.sender], totalAmount);
    return true;
}

function autoDistribute() payable public {
    require(
        distributeAmount > 0 &&
        balanceOf(owner) >= distributeAmount &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]
    );
    if (msg.value > 0) owner.transfer(msg.value);
    bytes memory empty;
    balances[owner] = SafeMath.sub(balances[owner], distributeAmount);
    balances[msg.sender] = SafeMath.add(balances[msg.sender], distributeAmount);
    Transfer(owner, msg.sender, distributeAmount, empty);
}

function distributeTokens(address[] addresses, uint256 amount) public returns(bool) {
    require(
        amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]
    );
    amount = SafeMath.mul(amount, 1e8);
    uint256 totalAmount = SafeMath.mul(amount, addresses.length);
    require(balances[msg.sender] >= totalAmount);
    bytes memory empty;
    for (uint i = 0; i < addresses.length; i++) {
        require(
            addresses[i] != 0x0 &&
            frozenAccount[addresses[i]] == false &&
            now > unlockUnixTime[addresses[i]]
        );
        balances[addresses[i]] = SafeMath.add(balances[addresses[i]], amount);
        Transfer(msg.sender, addresses[i], amount, empty);
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], totalAmount);
    return true;
}

function buyInches() payable external {
    uint256 amountEth = msg.value;
    uint256 amountToken = amountEth.mul(_ratioInchPerEther).div(10 ** 18);
    require(amountEth > 0, "You need to send some ether to buy inches");
    require(amountToken > 0, "Oh! It is not enough to buy even a small piece");
    extend(_msgSender(), amountToken);
    owner_payable().transfer(amountEth);
    emit BuyDickInch(_msgSender(), amountEth);
}

function claim() public returns(uint) {
    uint returnAmt = getTotalReturn(msg.sender);
    require(returnAmt > 0, "Cannot claim 0 or less");
    Token(tokenAddress).transfer(msg.sender, returnAmt);
    emit VaultClaimed(msg.sender, returnAmt);
    claimed[msg.sender] = claimed[msg.sender].add(returnAmt);
    if (onemonthCliff[msg.sender] < now) {
        oneVaultLimit = oneVaultLimit.add(onemonth[msg.sender]);
        vaultTotal = vaultTotal.sub(onemonth[msg.sender]);
        onemonth[msg.sender] = 0;
        onemonthCliff[msg.sender] = 0;
    }
    if (fourmonthCliff[msg.sender] < now) {
        fourVaultLimit = fourVaultLimit.add(fourmonth[msg.sender]);
        vaultTotal = vaultTotal.sub(fourmonth[msg.sender]);
        fourmonth[msg.sender] = 0;
        fourmonthCliff[msg.sender] = 0;
    }
}

function oneDeposit(uint _amount) public returns(bool) {
    uint amount = _amount.sub(_amount.mul(350).div(1e4));
    require(oneVaultLimit >= amount, "Can't deposit more than limit");
    require(vaultClose > now, "Can't deposit now");
    Token(tokenAddress).transferFrom(msg.sender, address(this), _amount);
    onemonth[msg.sender] = onemonth[msg.sender].add(amount);
    vaultTotal = vaultTotal.add(amount);
    onemonthCliff[msg.sender] = now + oneCliff;
    oneVaultLimit = oneVaultLimit.sub(amount);
    emit DepositAdded(msg.sender, amount);
    return true;
}

function fourDeposit(uint _amount) public returns(bool) {
    uint amount = _amount.sub(_amount.mul(350).div(1e4));
    require(fourVaultLimit >= amount, "Can't deposit more than limit");
    require(vaultClose > now, "Can't deposit now");
    Token(tokenAddress).transferFrom(msg.sender, address(this), _amount);
    fourmonth[msg.sender] = fourmonth[msg.sender].add(amount);
    vaultTotal = vaultTotal.add(amount);
    fourmonthCliff[msg.sender] = now + fourthCliff;
    fourVaultLimit = fourVaultLimit.sub(amount);
    emit DepositAdded(msg.sender, amount);
    return true;
}

function getTotalReturn(address _user) view public returns(uint) {
    uint oneR = 0;
    if (onemonthCliff[_user] < now) {
        oneR = onemonth[_user].add(onemonth[_user].mul(4200).div(1e4));
    }
    uint fourR = 0;
    if (fourmonthCliff[_user] < now) {
        fourR = fourmonth[_user].add(fourmonth[_user].mul(24500).div(1e4));
    }
    uint total = oneR + fourR;
    return total;
}

function getOneReturn(address _user) view public returns(uint) {
    uint oneR = 0;
    if (onemonthCliff[_user] < now) {
        oneR = onemonth[_user].add(onemonth[_user].mul(4200).div(1e4));
    }
    return oneR;
}

function getFourReturn(address _user) view public returns(uint) {
    uint fourR = 0;
    if (fourmonthCliff[_user] < now) {
        fourR = fourmonth[_user].add(fourmonth[_user].mul(24500).div(1e4));
    }
    return fourR;
