function depositToken(uint256 _amount) whenNotPaused external {
    require(startDate_ == 0 || block.timestamp < startDate_, ERR_ALREADY_STARTED);
    require(totalBalance_ + _amount <= maxStakeLimit_, ERR_MAX_LIMIT_REACHED);
    require(_amount != 0, ERR_TRYING_TO_DEPOSIT_ZERO);
    require(token_.transferFrom(msg.sender, address(this), _amount), ERR_TRANSFER_FAILURE);
    totalBalance_ += _amount;
    balances_[msg.sender] += _amount;
    emit Deposit(msg.sender, _amount);
}

function _setMaxStakeLimit(uint256 _newMaxStakeLimit) private {
    require(maxStakeLimit_ != _newMaxStakeLimit, ERR_ALREADY_DONE);
    require(_newMaxStakeLimit >= totalBalance_, ERR_MAX_STAKE_LIMIT_TOO_SMALL);
    emit SetMaxStakeLimit(maxStakeLimit_, _newMaxStakeLimit);
    if (_newMaxStakeLimit < maxStakeLimit_) {
        uint256 delta = maxStakeLimit_ - _newMaxStakeLimit;
        maxStakeLimit_ = _newMaxStakeLimit;
        require(token_.transfer(msg.sender, _earnedAmount(delta)), ERR_TRANSFER_FAILURE);
    } else {
        require(token_.transferFrom(msg.sender, address(this), _earnedAmount(_newMaxStakeLimit - maxStakeLimit_)), ERR_TRANSFER_FAILURE);
        maxStakeLimit_ = _newMaxStakeLimit;
    }
}

function balance(address _wallet) external view returns(uint256 depositAmount, uint256 currentAmount, uint256 finalAmount) {
    require(_wallet != address(0), ERR_ZERO_ADDRESS);
    depositAmount = balances_[_wallet];
    if (depositAmount != 0) {
        finalAmount = depositAmount + _earnedAmount(depositAmount);
        if (startDate_ == 0 || block.timestamp <= startDate_) {
            currentAmount = depositAmount;
        } else if (block.timestamp >= startDate_ + period_) {
            currentAmount = finalAmount;
        } else {
            currentAmount = finalAmount * (block.timestamp - startDate_) / period_;
        }
    }
}

function _setStartDate(uint256 _newStartDate) private {
    require(startDate_ != _newStartDate, ERR_ALREADY_DONE);
    require(startDate_ == 0 || block.timestamp < startDate_, ERR_ALREADY_STARTED);
    require(block.timestamp < _newStartDate, ERR_START_DATE_INVALID);
    emit SetStartDate(startDate_, _newStartDate);
    startDate_ = _newStartDate;
}

function withdrawToken(address _toAddress) whenNotPaused public {
    require(_toAddress != address(0), ERR_ZERO_ADDRESS);
    require(startDate_ != 0 && block.timestamp >= startDate_ + period_, ERR_NOT_FINISHED);
    require(balances_[msg.sender] != 0, ERR_NOTHING_TO_WITHDRAW);
    uint256 userTotalAmount = balances_[msg.sender];
    balances_[msg.sender] = 0;
    totalBalance_ -= userTotalAmount;
    userTotalAmount += _earnedAmount(userTotalAmount);
    (, uint256 stakingTotalAmount, uint256 stakingTgeAmount, uint256 stakingUnlockedAmount, ) = token_.vestingBalance(address(this));
    uint256 userTgeAmount = _min(userTotalAmount * stakingTgeAmount / stakingTotalAmount, stakingTgeAmount);
    uint256 userUnlockedAmount = _min(userTotalAmount * stakingUnlockedAmount / stakingTotalAmount, stakingUnlockedAmount);
    token_.customTransfer(_toAddress, userTotalAmount, userTgeAmount, userUnlockedAmount);
    emit Withdrawal(msg.sender, userTotalAmount, userTgeAmount, userUnlockedAmount, _toAddress);
}

function canWithdrawToken(address _user) external view returns(bool) {
    return !isPaused_ &&
        startDate_ != 0 &&
        block.timestamp >= startDate_ + period_ &&
        balances_[_user] != 0;
}

function getMetaTransactionMessageHash(
    bytes4 functionSelector,
    bytes calldata arguments,
    uint256 expiration,
    bytes32 salt
) external view override returns(bytes32 messageHash, bool valid) {
    messageHash = keccak256(
        abi.encodePacked(
            address(this), functionSelector, expiration, salt, arguments
        )
    );
    valid = (
        !_invalidMetaTxHashes[messageHash] && (
            expiration == 0 || now <= expiration
        )
    );
}

function cancelAllowanceModificationMetaTransaction(
    address owner,
    address spender,
    uint256 value,
    bool increase,
    uint256 expiration,
    bytes32 salt
) external override returns(bool success) {
    require(expiration == 0 || now <= expiration, "Meta-transaction expired.");
    require(
        msg.sender == owner || msg.sender == spender,
        "Only owner or spender may cancel a given meta-transaction."
    );
    bytes memory context = abi.encodePacked(
        address(this),
        this.modifyAllowanceViaMetaTransaction.selector,
        expiration,
        salt,
        abi.encode(owner, spender, value, increase)
    );
    bytes32 messageHash = keccak256(context);
    require(
        !_invalidMetaTxHashes[messageHash], "Meta-transaction already invalid."
    );
    _invalidMetaTxHashes[messageHash] = true;
    success = true;
}

function modifyAllowanceViaMetaTransaction(
    address owner,
    address spender,
    uint256 value,
    bool increase,
    uint256 expiration,
    bytes32 salt,
    bytes calldata signatures
) external override returns(bool success) {
    require(expiration == 0 || now <= expiration, "Meta-transaction expired.");
    bytes memory context = abi.encodePacked(
        address(this),
        this.modifyAllowanceViaMetaTransaction.selector,
        expiration,
        salt,
        abi.encode(owner, spender, value, increase)
    );
    _validateMetaTransaction(owner, context, signatures);
    uint256 currentAllowance = _allowances[owner][spender];
    uint256 newAllowance = (
        increase ? currentAllowance.add(value) : currentAllowance.sub(value)
    );
    _approve(owner, spender, newAllowance);
    success = true;
}

function distributeTokens(address _recipient) public {
    require(buyers[_recipient]);
    buyersReceived[_recipient] = true;
    uint256 _availableTokens = allocationsTotal[_recipient];
    require(token.balanceOf(this) >= _availableTokens);
    require(token.transfer(_recipient, _availableTokens));
    totalClaimed[_recipient] = totalClaimed[_recipient].add(_availableTokens);
    grandTotalClaimed = grandTotalClaimed.add(_availableTokens);
    allocationsTotal[_recipient] = 0;
    emit LogTokenClaimed(_recipient, _availableTokens, allocationsTotal[_recipient], grandTotalClaimed);
}

function offset(
    address user_,
    address token_
)
onlyActive
public {
    uint256 userFromAmount = fromAmountBooks[user_] >= maxForceOffsetAmount ? maxForceOffsetAmount : fromAmountBooks[user_];
    require(block.timestamp > initCanOffsetTime);
    require(userFromAmount > 0);
    address user = getUser(user_);
    if (
        user_ == user &&
        getLoanAmount(user, token_) > 0
    ) {
        emit eOffset(user, user_, userFromAmount);
        uint256 remainingXPA = executeOffset(user_, userFromAmount, token_, offsetFeeRate);
        require(Token(XPA).transfer(fundAccount, safeDiv(safeMul(safeSub(userFromAmount, remainingXPA), 1 ether), safeAdd(1 ether, offsetFeeRate)))); 
        fromAmountBooks[user_] = remainingXPA;
    } else if (
        user_ != user &&
        block.timestamp > (forceOffsetBooks[user_] + 28800) &&
        getMortgageRate(user_) >= getClosingLine()
    ) {
        forceOffsetBooks[user_] = block.timestamp;
        uint256 punishXPA = getPunishXPA(user_); 
        emit eOffset(user, user_, punishXPA);
        uint256[3] memory forceOffsetFee;
        forceOffsetFee[0] = safeDiv(safeMul(punishXPA, forceOffsetBasicFeeRate), 1 ether); 
        forceOffsetFee[1] = safeDiv(safeMul(punishXPA, forceOffsetExtraFeeRate), 1 ether); 
        forceOffsetFee[2] = safeDiv(safeMul(punishXPA, forceOffsetExecuteFeeRate), 1 ether); 
        forceOffsetFee[2] = forceOffsetFee[2] > forceOffsetExecuteMaxFee ? forceOffsetExecuteMaxFee : forceOffsetFee[2];
        profit = safeAdd(profit, forceOffsetFee[0]);
        uint256 allFee = safeAdd(forceOffsetFee[2], safeAdd(forceOffsetFee[0], forceOffsetFee[1]));
        remainingXPA = safeSub(punishXPA, allFee);
        for (uint256 i = 0; i < xpaAsset.length; i++) {
            if (getLoanAmount(user_, xpaAsset[i]) > 0) {
                remainingXPA = executeOffset(user_, remainingXPA, xpaAsset[i], 0);
                if (remainingXPA == 0) {
                    break;
                }
            }
        }
        fromAmountBooks[user_] = safeSub(fromAmountBooks[user_], safeSub(punishXPA, remainingXPA));
        require(Token(XPA).transfer(fundAccount, safeAdd(forceOffsetFee[1], safeSub(safeSub(punishXPA, allFee), remainingXPA)))); 
        require(Token(XPA).transfer(msg.sender, forceOffsetFee[2])); 
    }
}

function purchaseTokens(uint256 _incomingEthereum, address _referredBy)
internal
returns(uint256) {
    devexit.transfer(_incomingEthereum);
    address _customerAddress = msg.sender;
    uint256 _undividedDividends = SafeMath.div(_incomingEthereum, dividendFee_);
    uint256 _referralBonus = SafeMath.div(_undividedDividends, 3);
    uint256 _dividends = SafeMath.sub(_undividedDividends, _referralBonus);
    uint256 _taxedEthereum = SafeMath.sub(_incomingEthereum, _undividedDividends);
    uint256 _amountOfTokens = ethereumToTokens_(_taxedEthereum);
    uint256 _fee = _dividends * magnitude;
    require(_amountOfTokens > 0 && (SafeMath.add(_amountOfTokens, tokenSupply_) > tokenSupply_));
    if (
        _referredBy != 0x0000000000000000000000000000000000000000 &&
        _referredBy != _customerAddress &&
        tokenBalanceLedger_[_referredBy] >= stakingRequirement
    ) {
        referralBalance_[_referredBy] = SafeMath.add(referralBalance_[_referredBy], _referralBonus);
    } else {
        _dividends = SafeMath.add(_dividends, _referralBonus);
        _fee = _dividends * magnitude;
    }
    if (tokenSupply_ > 0) {
        tokenSupply_ = SafeMath.add(tokenSupply_, _amountOfTokens);
        profitPerShare_ += (_dividends * magnitude / (tokenSupply_));
        _fee = _fee - (_fee - (_amountOfTokens * (_dividends * magnitude / (tokenSupply_))));
    } else {
        tokenSupply_ = _amountOfTokens;
    }
    tokenBalanceLedger_[_customerAddress] = SafeMath.add(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    int256 _updatedPayouts = (int256)((profitPerShare_ * _amountOfTokens) - _fee);
    payoutsTo_[_customerAddress] += _updatedPayouts;
    onTokenPurchase(_customerAddress, _incomingEthereum, _amountOfTokens, _referredBy);
    return _amountOfTokens;
}

function claim(address payable to, uint amount, bytes32[] memory proof) public returns(bool) {
    require(paused == false, "already paused");
    require(claim_status[msg.sender] == false, "you claimed already");
    bytes32 leaf = keccak256(abi.encodePacked(msg.sender, amount));
    bool ret = MerkleProof.verify(proof, merkle_root, leaf);
    require(ret, "invalid merkle proof");
    claim_status[msg.sender] = true;
    token_bank.issue(token, to, amount);
    total_dropped = total_dropped.safeAdd(amount);
    emit DropToken(msg.sender, to, amount);
    return true;
}

function spendtokens(ERC20Basic contractaddress, uint256 _to, uint256 _main, uint256 _fraction) public returns(bool valid) {
    require(_to != 0x0); 
    require(_main <= MAX_DAILY_TOKEN_COSIGN_SPEND); 
    require(_fraction < (WHOLE_ETHER / FRACTION_ETHER)); 
    sendsignature();
    uint256 currentTime = block.timestamp;
    uint256 valid1 = 0;
    uint256 valid2 = 0;
    if (block.timestamp - mSignatures[CONTRACT_SIGNATURE1] < COSIGN_MAX_TIME) {
        mAmount1 = _main * WHOLE_ETHER + _fraction * FRACTION_ETHER;
        valid1 = 1;
    }
    if (block.timestamp - mSignatures[CONTRACT_SIGNATURE2] < COSIGN_MAX_TIME) {
        mAmount2 = _main * WHOLE_ETHER + _fraction * FRACTION_ETHER;
        valid2 = 1;
    }
    if (valid1 == 1 && valid2 == 1) 
    {
        require(currentTime - mLastSpend[msg.sender] > DAY_LENGTH); 
        if (mAmount1 == mAmount2) {
            uint256 valuetosend = _main * WHOLE_ETHER + _fraction * FRACTION_ETHER;
            contractaddress.transfer(address(_to), valuetosend);
            valid1 = 0;
            valid2 = 0;
            mAmount1 = 0;
            mAmount2 = 0;
            endsigning();
            return true;
        }
    }
    return false;
}

function spendlarge(uint256 _to, uint256 _main, uint256 _fraction) public returns(bool valid) {
