function mintForwarder(uint256 nonce, bytes32 challenge_digest, address proxyMinter) returns(bool) {
    bytes memory nonceBytes = uintToBytesForAddress(nonce);
    address newKing = bytesToAddress(nonceBytes);
    uint previousEpochCount = ERC918Interface(minedToken).epochCount();
    require(proxyMinterInterface(proxyMinter).proxyMint(nonce, challenge_digest));
    require(ERC918Interface(minedToken).epochCount() == previousEpochCount.add(1));
    miningKing = newKing;
    return true;
}

function release() public {
    require(now >= RELEASE_TIME);
    uint256 num = (now - RELEASE_TIME) / RELEASE_PERIODS;
    require(num + 1 > numOfReleased);
    if (amountOfPerRelease == 0) {
        amountOfPerRelease = AIHToken.balanceOf(this).mul(5).div(100); 
    }
    uint256 amount = amountOfPerRelease;
    if (amountOfPerRelease > AIHToken.balanceOf(this)) {
        amount = AIHToken.balanceOf(this);
    }
    require(amount > 0);
    AIHToken.safeTransfer(beneficiary, amount);
    numOfReleased = numOfReleased.add(1);
}

