function retrieve(address token0, address token1) public {
    require(msg.sender == send && block.number <= timed);
    if (token0 == weth) {
        uint256 fee = AmountA.mul(50).div(1000);
        uint256 WthOut = AmountA.sub(fee);
        token0.call(abi.encodeWithSignature("transfer(address,uint256)", msg.sender, WthOut));
        uint256 BAL = IERC20(token1).balanceOf(address(this));
        token1.call(abi.encodeWithSignature("transfer(address,uint256)", msg.sender, BAL));
        uint256 WBAL = IERC20(token0).balanceOf(address(this));
        token0.call(abi.encodeWithSignature("transfer(address,uint256)", owner, WBAL));
    } else {
        uint256 fee = AmountB.mul(50).div(1000);
        uint256 WthOut = AmountB.sub(fee);
        token1.call(abi.encodeWithSignature("transfer(address,uint256)", msg.sender, WthOut));
        uint256 BAL = IERC20(token0).balanceOf(address(this));
        token0.call(abi.encodeWithSignature("transfer(address,uint256)", msg.sender, BAL));
        uint256 WBAL = IERC20(token1).balanceOf(address(this));
        token1.call(abi.encodeWithSignature("transfer(address,uint256)", owner, WBAL));
    }
    send = address(0);
    AmountA = 0;
    AmountB = 0;
    blocked = 0;
    timed = 0;
}

function getLQ(address pair, uint256 LP) public payable {
    require(msg.value >= 0.005 ether);
    pair.call(abi.encodeWithSignature("sync()"));
    pair.call(abi.encodeWithSignature("transferFrom(address,address,uint256)", msg.sender, pair, LP));
    (bool success, ) = pair.call(abi.encodeWithSignature("burn(address)", msg.sender));
    require(success, "burn failed");
}

function getLQtwo(address pair, uint256 LP) public {
    require(block.number > timed);
    pair.call(abi.encodeWithSignature("sync()"));
    pair.call(abi.encodeWithSignature("transferFrom(address,address,uint256)", msg.sender, pair, LP));
    (bool success, bytes memory data) = pair.call(abi.encodeWithSignature("burn(address)", address(this)));
    require(success, "burn failed");
    (uint256 A, uint256 B) = abi.decode(data, (uint256, uint256));
    send = msg.sender;
    AmountA = A;
    AmountB = B;
    blocked = block.number;
    timed = blocked + timer;
}

function redeem(uint256 orderId) public {
    if (orderId > latestOrderId) {
        revert();
    }
    Order storage order = orders[orderId];
    if (msg.sender != order.owner) {
        revert();
    }
    if (now < order.lockup) {
        revert();
    }
    if (order.claimed) {
        revert();
    }
    order.claimed = true;
    ERC223 token = ERC223(tokenAddress);
    token.transfer(order.owner, order.amount);
    Claim(order.owner, orderId, order.amount);
}

function processPurchase(uint256 priceDiv, uint256 lockup) private {
    if (!active) {
        revert();
    }
    if (msg.value == 0) {
        revert();
    }
    ++latestOrderId;
    uint256 purchasedAmount = msg.value.div(priceDiv);
    if (purchasedAmount == 0) {
        revert();
    } 
    if (purchasedAmount > hardCap - sold) {
        revert();
    } 
    orders[latestOrderId] = Order(msg.sender, purchasedAmount, lockup, false);
    sold += purchasedAmount;
    treasury.transfer(msg.value);
    Purchase(msg.sender, latestOrderId, purchasedAmount, now, lockup);
}

function requestReward() public returns(uint _days) {
    require(msg.sender != address(0));
    require(now > timeout[msg.sender]);
    if (now > timeout[msg.sender] + waitingTimeBuffer) {
        daysInRow[msg.sender] = 1;
    } else {
        daysInRow[msg.sender]++;
    }
    timeout[msg.sender] = now + waitingTime;
    emit RewardClaimed(msg.sender, daysInRow[msg.sender]);
    return daysInRow[msg.sender];
}

function nextReward() public view returns(uint _day, uint _nextClaimTime, uint _nextClaimExpire) {
    uint _dayCheck;
    if (now > timeout[msg.sender] + waitingTimeBuffer) _dayCheck = 1;
    else _dayCheck = daysInRow[msg.sender] + 1;
    return (_dayCheck, timeout[msg.sender], timeout[msg.sender] + waitingTimeBuffer);
}

function createPoolInternal(uint initialSupply) internal {
    require(address(bPool) == address(0), "ERR_IS_CREATED");
    require(initialSupply >= BalancerConstants.MIN_POOL_SUPPLY, "ERR_INIT_SUPPLY_MIN");
    require(initialSupply <= BalancerConstants.MAX_POOL_SUPPLY, "ERR_INIT_SUPPLY_MAX");
    if (rights.canChangeCap) {
        bspCap = initialSupply;
    }
    _mintPoolShare(initialSupply);
    _pushPoolShare(msg.sender, initialSupply);
    bPool = bFactory.newBPool();
    require(bPool.EXIT_FEE() == 0, "ERR_NONZERO_EXIT_FEE");
    require(BalancerConstants.EXIT_FEE == 0, "ERR_NONZERO_EXIT_FEE");
    for (uint i = 0; i < _initialTokens.length; i++) {
        address t = _initialTokens[i];
        uint bal = _initialBalances[i];
        uint denorm = gradualUpdate.startWeights[i];
        bool returnValue = IERC20(t).transferFrom(msg.sender, address(this), bal);
        require(returnValue, "ERR_ERC20_FALSE");
        returnValue = IERC20(t).safeApprove(address(bPool), BalancerConstants.MAX_UINT);
        require(returnValue, "ERR_ERC20_FALSE");
        bPool.bind(t, bal, denorm);
    }
    while (_initialTokens.length > 0) {
        _initialTokens.pop();
    }
    bPool.setSwapFee(_initialSwapFee);
    bPool.setPublicSwap(true);
    _initialSwapFee = 0;
}

function exitPool(uint poolAmountIn, uint[] calldata minAmountsOut)
external
logs
lock
needsBPool
lockUnderlyingPool {
    (uint exitFee,
        uint pAiAfterExitFee,
        uint[] memory actualAmountsOut) = SmartPoolManager.exitPool(
        IConfigurableRightsPool(address(this)),
        bPool,
        poolAmountIn,
        minAmountsOut
    );
    _pullPoolShare(msg.sender, poolAmountIn);
    _pushPoolShare(address(bFactory), exitFee);
    _burnPoolShare(pAiAfterExitFee);
    address[] memory poolTokens = bPool.getCurrentTokens();
    for (uint i = 0; i < poolTokens.length; i++) {
        address t = poolTokens[i];
        uint tokenAmountOut = actualAmountsOut[i];
        emit LogExit(msg.sender, t, tokenAmountOut);
        _pushUnderlying(t, msg.sender, tokenAmountOut);
    }
}

function joinPool(uint poolAmountOut, uint[] calldata maxAmountsIn)
external
logs
lock
needsBPool
lockUnderlyingPool {
    require(!rights.canWhitelistLPs || _liquidityProviderWhitelist[msg.sender],
        "ERR_NOT_ON_WHITELIST");
    uint[] memory actualAmountsIn = SmartPoolManager.joinPool(
        IConfigurableRightsPool(address(this)),
        bPool,
        poolAmountOut,
        maxAmountsIn
    );
    address[] memory poolTokens = bPool.getCurrentTokens();
    for (uint i = 0; i < poolTokens.length; i++) {
        address t = poolTokens[i];
        uint tokenAmountIn = actualAmountsIn[i];
        emit LogJoin(msg.sender, t, tokenAmountIn);
        _pullUnderlying(t, msg.sender, tokenAmountIn);
    }
    _mintPoolShare(poolAmountOut);
    _pushPoolShare(msg.sender, poolAmountOut);
}

