function lock(bytes32 toPlatform, address toAccount, uint value) external payable {
    require(admin.status == 2 || admin.status == 3);
    require(xcPlugin.getStatus());
    require(xcPlugin.existPlatform(toPlatform));
    require(toAccount != address(0));
    require(value > 0);
    uint allowance = token.allowance(msg.sender, this);
    require(toCompare(allowance, value));
    bool success = token.transferFrom(msg.sender, this, value);
    require(success);
    lockBalance = SafeMath.add(lockBalance, value);
    emit Lock(toPlatform, toAccount, bytes32(value), admin.tokenSymbol);
}

function unlock(string txid, bytes32 fromPlatform, address fromAccount, address toAccount, uint value) external payable {
    require(admin.status == 1 || admin.status == 3);
    require(xcPlugin.getStatus());
    require(xcPlugin.existPlatform(fromPlatform));
    require(toAccount != address(0));
    require(value > 0);
    bool complete;
    bool verify;
    (complete, verify) = xcPlugin.verifyProposal(fromPlatform, fromAccount, toAccount, value, admin.tokenSymbol, txid);
    require(verify && !complete);
    uint balance = token.balanceOf(this);
    require(toCompare(balance, value));
    require(token.transfer(toAccount, value));
    require(xcPlugin.commitProposal(fromPlatform, txid));
    lockBalance = SafeMath.sub(lockBalance, value);
    emit Unlock(txid, fromPlatform, fromAccount, bytes32(value), admin.tokenSymbol);
}

function approve(address _spender, uint256 _amount) public returns(bool success) {
    require(transfersEnabled);
    require((_amount == 0) || (allowed[msg.sender][_spender] == 0));
    if (isContract(owner)) {
        require(TokenController(owner).onApprove(msg.sender, _spender, _amount));
    }
    allowed[msg.sender][_spender] = _amount;
    emit Approval(msg.sender, _spender, _amount);
    return true;
}

function isExpired(address _etherBoxAddress) external view returns(bool) {
    return etherBoxes[_etherBoxAddress].expiration <= now ? true : false;
}

function deleteEtherBox(address _etherBoxAddress) external {
    require(etherBoxes[_etherBoxAddress].owner == msg.sender);
    require(etherBoxes[_etherBoxAddress].expiration <= now);
    address[] storage ownedEtherBoxes = ownerToEtherBoxes[msg.sender];
    address[] memory tempEtherBoxes = ownedEtherBoxes;
    uint newLength = 0;
    for (uint i = 0; i < tempEtherBoxes.length; i++) {
        if (tempEtherBoxes[i] != _etherBoxAddress) {
            ownedEtherBoxes[newLength] = tempEtherBoxes[i];
            newLength++;
        }
    }
    ownedEtherBoxes.length = newLength;
    delete etherBoxes[_etherBoxAddress];
    emit EtherBoxDeleted(msg.sender, nicknames[msg.sender], _etherBoxAddress, now);
}

function esteem(bytes32 _nickname, string _message, address _to) external payable {
    assert(bytes(_message).length <= 300);
    EtherBox storage etherBox = etherBoxes[_to];
    require(etherBox.expiration > now);
    assert(etherBox.owner != address(0));
    nicknames[msg.sender] = _nickname;
    emit NewEsteem(msg.sender, _nickname, _to, etherBox.label, _message, msg.value, now);
    etherBox.owner.transfer(msg.value);
}

