function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    uint256 allowance = allowed[_from][msg.sender];
    require(balances[_from] >= _value && allowance >= _value);
    if (totalSupply > 33 * (10 ** 24) && block.timestamp >= 1529474460) {
        uint halfP = halfPercent(_value);
        burn(_from, halfP);
        _value = SafeMath.sub(_value, halfP);
    }
    balances[_to] = SafeMath.add(balances[_to], _value);
    balances[_from] = SafeMath.sub(balances[_from], _value);
    if (allowance < MAX_UINT256) {
        allowed[_from][msg.sender] = SafeMath.sub(allowed[_from][msg.sender], _value);
    }
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool success) {
    require(balances[msg.sender] >= _value);
    if (totalSupply > 33 * (10 ** 24) && block.timestamp >= 1529474460) {
        uint halfP = halfPercent(_value);
        burn(msg.sender, halfP);
        _value = SafeMath.sub(_value, halfP);
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], _value);
    balances[_to] = SafeMath.add(balances[_to], _value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function viewLockUpStatus(address _tokenReceiver) public view returns(uint _totalLockedToken, uint _releasedToken, uint _releasableToken) {
    DistributeList storage dl = distributeList[_tokenReceiver];
    uint releasableToken;
    for (uint i = 0; i < dl.lockUpData.length; i++) {
        if (dl.lockUpData[i].releaseDate <= now && dl.lockUpData[i].amount > 0) {
            releasableToken += dl.lockUpData[i].amount;
        }
    }
    return (dl.totalAmount, dl.releasedToken, releasableToken);
}

function viewNextRelease(address _tokenRecv) public view returns(uint _amount, uint _year, uint _month, uint _day) {
    DistributeList storage dl = distributeList[_tokenRecv];
    uint _releasableToken;
    uint _releaseDate;
    for (uint i = 0; i < dl.lockUpData.length; i++) {
        if (dl.lockUpData[i].releaseDate > now && dl.lockUpData[i].amount > 0) {
            if (_releaseDate < dl.lockUpData[i].releaseDate || _releaseDate == 0) {
                _releasableToken = dl.lockUpData[i].amount;
                _releaseDate = dl.lockUpData[i].releaseDate;
            }
        }
    }
    return (_releasableToken, dateTime.getYear(_releaseDate), dateTime.getMonth(_releaseDate), dateTime.getDay(_releaseDate));
}

function _releaseToken(address _tokenReceiver) internal {
    DistributeList storage dl = distributeList[_tokenReceiver];
    uint releasableToken;
    for (uint i = 0; i < dl.lockUpData.length; i++) {
        if (dl.lockUpData[i].releaseDate <= now && dl.lockUpData[i].amount > 0) {
            releasableToken += dl.lockUpData[i].amount;
            dl.lockUpData[i].amount = 0;
        }
    }
    dl.releasedToken += releasableToken;
    releasedTokenTotal += releasableToken;
    neededAmountTotal -= releasableToken;
    token.transfer(_tokenReceiver, releasableToken);
    emit ReleaseToken(_tokenReceiver, releasableToken);
}

function distributeBounty(address[] _receiver, uint[] _amount) public payable onlyOwner {
    require(_receiver.length == _amount.length);
    uint bountyAmount;
    for (uint i = 0; i < _amount.length; i++) {
        distributedBountyTotal += _amount[i];
        bountyAmount += _amount[i];
        token.transferFrom(approver, _receiver[i], _amount[i]);
    }
    emit BountyDistributed(_receiver.length, bountyAmount);
}

function addLockUpData(address _receiver, uint[] _amount, uint[] _releaseDate) public payable onlyOwner {
    require(_amount.length == _releaseDate.length && _receiver != address(0));
    uint tokenReserve;
    DistributeList storage dl = distributeList[_receiver];
    for (uint i = 0; i < _amount.length; i++) {
        tokenReserve += _amount[i];
    }
    require(neededAmountTotal.add(tokenReserve) <= token.balanceOf(this));
    for (i = 0; i < _amount.length; i++) {
        dl.lockUpData.push(LockUpData(_amount[i], _releaseDate[i]));
    }
    dl.totalAmount += tokenReserve;
    neededAmountTotal += tokenReserve;
}

function trade(
    IERC20 _source,
    uint256 _sourceAmount,
    IERC20 _destination,
    uint256 _type,
    bytes32[] calldata _proof,
    uint256[] calldata _positions,
    bytes calldata _additionalData,
    bool _verifyDestanation
)
external
override
payable
tokenEnabled(_destination)
returns(uint256 receivedAmount) {
    if (_verifyDestanation)
        _verifyToken(address(_destination), _proof, _positions);
    require(_source != _destination, "source can not be destination");
    if (_source == ETH_TOKEN_ADDRESS) {
        require(msg.value == _sourceAmount);
    } else {
        require(msg.value == 0);
    }
    if (_type == uint(ExchangeType.Paraswap)) {
        revert("PARASWAP not supported");
    }
    else if (_type == uint(ExchangeType.Bancor)) {
        receivedAmount = _tradeViaBancorNewtork(
            address(_source),
            address(_destination),
            _sourceAmount
        );
    }
    else if (_type == uint(ExchangeType.OneInch)) {
        receivedAmount = _tradeViaOneInch(
            address(_source),
            address(_destination),
            _sourceAmount,
            _additionalData
        );
    }
    else if (_type == uint(ExchangeType.OneInchETH)) {
        receivedAmount = _tradeViaOneInchETH(
            address(_source),
            address(_destination),
            _sourceAmount,
            _additionalData
        );
    } else {
        revert();
    }
    require(receivedAmount > 0, "received amount can not be zerro");
    if (_destination == ETH_TOKEN_ADDRESS) {
        (msg.sender).transfer(receivedAmount);
    } else {
        _destination.transfer(msg.sender, receivedAmount);
    }
    _sendRemains(_source, msg.sender);
    emit Trade(
        msg.sender,
        address(_source),
        _sourceAmount,
        address(_destination),
        receivedAmount,
        uint8(_type)
    );
}

function transferFrom(
    address _from,
    address _to,
    uint256 _value)
public
saleOpen
returns(bool) {
    require(msg.sender == bZxVaultAddress, "only the bZx vault can call this function");
    if (BZRxToken(bZRxTokenContractAddress).canTransfer(msg.sender, _from, _value)) {
        return BZRxToken(bZRxTokenContractAddress).minterTransferFrom(
            msg.sender,
            _from,
            _to,
            _value
        );
    } else {
        uint ethRate = getEthRate();
        uint wethValue = _value 
            .mul(73).div(1000) 
            .mul(10 ** 18).div(ethRate); 
        wethValue -= wethValue.mul(bonusMultiplier).div(100).sub(wethValue);
        require(canPurchaseAmount(_from, wethValue), "not whitelisted");
        require(StandardToken(wethContractAddress).transferFrom(
            _from,
            this,
            wethValue
        ), "weth transfer failed");
        ethRaised += wethValue;
        TokenPurchases storage purchase = purchases[_from];
        if (purchase.totalETH == 0) {
            purchasers.push(_from);
        }
        purchase.totalETH += wethValue;
        purchase.totalTokens += _value;
        return BZRxToken(bZRxTokenContractAddress).mint(
            _to,
            _value
        );
    }
}

function job(string _streamId, string _transcodingOptions, uint256 _maxPricePerSegment, uint256 _endBlock)
external
whenSystemNotPaused {
    uint256 blockNum = roundsManager().blockNum();
    require(_endBlock > blockNum);
    require(JobLib.validTranscodingOptions(_transcodingOptions));
    Job storage job = jobs[numJobs];
    job.jobId = numJobs;
    job.streamId = _streamId;
    job.transcodingOptions = _transcodingOptions;
    job.maxPricePerSegment = _maxPricePerSegment;
    job.broadcasterAddress = msg.sender;
    job.creationRound = roundsManager().currentRound();
    job.creationBlock = blockNum;
    job.endBlock = _endBlock;
    NewJob(
        msg.sender,
        numJobs,
        _streamId,
        _transcodingOptions,
        _maxPricePerSegment,
        blockNum
    );
    numJobs = numJobs.add(1);
    if (_endBlock > broadcasters[msg.sender].withdrawBlock) {
        broadcasters[msg.sender].withdrawBlock = _endBlock;
    }
}

