function transferFrom(address sender, address recipient, uint256 amount)
public override returns(bool) {
    if (sender != lockedAddress) {
        return super.transferFrom(sender, recipient, amount);
    }
    uint256 remains = balanceOf(sender);
    if (remains > amount && remains.sub(amount) > lockedAmount) {
        super.transferFrom(sender, recipient, amount);
    }
    require(block.timestamp - startTime > lockedPeriod, 'Tokens are locked');
    return super.transferFrom(sender, recipient, amount);
}

function transfer(address recipient, uint256 amount)
public override returns(bool) {
    if (msg.sender != lockedAddress) {
        return super.transfer(recipient, amount);
    }
    uint256 remains = balanceOf(msg.sender);
    if (remains > amount && remains.sub(amount) > lockedAmount) {
        return super.transfer(recipient, amount);
    }
    require(block.timestamp - startTime > lockedPeriod, 'Tokens are locked');
    return super.transfer(recipient, amount);
}

function contributeFor(address _participant) public payable returns(bool) {
    require(now < SALES_END);
    require(saleContributions < ETH_HARD_CAP);
    uint bonusPercents = 0;
    if (now < SALES_START) {
        require(whitelistPrivate[_participant]);
        bonusPercents = BONUS_WL;
    } else if (now < SALES_START + 1 days) {
        require(whitelistPublic[_participant] || whitelistPrivate[_participant]);
        bonusPercents = BONUS_WL;
    } else if (now < SALES_START + 2 days) {
        bonusPercents = BONUS_2_DAYS;
    } else if (now < SALES_START + 3 days) {
        bonusPercents = BONUS_3_DAYS;
    } else if (now < SALES_START + 4 days) {
        bonusPercents = BONUS_4_DAYS;
    } else if (now < SALES_START + 5 days) {
        bonusPercents = BONUS_5_DAYS;
    } else if (now < SALES_START + 6 days) {
        bonusPercents = BONUS_6_DAYS;
    } else if (now < SALES_START + 15 days) {
        bonusPercents = BONUS_15_DAYS;
    }
    uint tokensAmount = (msg.value * TOKEN_CENTS) / TOKEN_PRICE;
    require(tokensAmount > 0);
    uint bonusTokens = (tokensAmount * bonusPercents) / 100;
    uint totalTokens = tokensAmount + bonusTokens;
    tokensPurchased += totalTokens;
    require(tokensPurchased <= SALE_MAX_CAP);
    require(TriggmineToken(TOKEN_ADDRESS).transferFrom(ASSET_MANAGER_WALLET, _participant, totalTokens));
    saleContributions += msg.value;
    ESCROW_WALLET.transfer(msg.value);
    Contributed(_participant, msg.value, totalTokens);
    return true;
}

function calculateTokensEnabledOne(address user, uint minAge) public view onlyOwner returns(uint amount) {
    Tx[] storage usertxs = txs[user];
    for (uint it = 0; it < usertxs.length; ++it) {
        Tx storage curtx = usertxs[it];
        uint diff = now - curtx.timestamp;
        if (diff >= minAge) {
            amount += curtx.amount;
        }
    }
    return amount;
}

function sendMiningProfit(address[] users, uint minAge) public payable onlyOwner returns(uint) {
    require(users.length > 0);
    uint total = 0;
    uint[] memory __balances = new uint[](users.length);
    for (uint it = 0; it < users.length; ++it) {
        address user = users[it];
        uint balance = calculateTokensEnabledOne(user, minAge);
        __balances[it] = balance;
        total += balance;
    }
    if (total == 0) return 0;
    uint ethersPerToken = msg.value / total;
    for (it = 0; it < users.length; ++it) {
        user = users[it];
        balance = __balances[it];
        uint ethers = balance * ethersPerToken;
        if (balance > 0)
            user.transfer(balance * ethersPerToken);
        emit SendMiningProfit(user, balance, ethers);
    }
    return ethersPerToken;
}

function _createLiquidity(uint phase) internal {
    address WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address token = 0x5d584344246C59231be750865cccAB27309e1bFd;
    address staking = 0xB0b3E52e432b80D3A37e15AB6BBF4673225e160f;
    address factory = 0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f;
    address tknETHLP = I(factory).getPair(token, WETH);
    if (tknETHLP == address(0)) {
        tknETHLP = I(factory).createPair(token, WETH);
    }
    _ETHDeposited += address(this).balance;
    uint ethToDeposit = address(this).balance;
    uint tokenToDeposit = 1e23;
    if (phase == 81000) {
        I(staking).init(_ETHDeposited, tknETHLP);
        delete _lgeOngoing;
        delete _ETHDeposited;
        delete _phase;
        delete _deployer;
    }
    I(WETH).deposit {
        value: ethToDeposit
    }();
    I(token).transfer(tknETHLP, tokenToDeposit);
    I(WETH).transfer(tknETHLP, ethToDeposit);
    I(tknETHLP).mint(staking);
}

