function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now >= SaleStage3_start) {
        tokens = safeDiv(msg.value * (10 ** 18), SaleStage3_tokenPrice);
        _supply = safeAdd(SaleStage3_supply, safeAdd(SaleStage2_supply, SaleStage1_supply));
    } else if (now >= SaleStage2_start) {
        tokens = safeDiv(msg.value * (10 ** 18), SaleStage2_tokenPrice);
        _supply = safeAdd(SaleStage2_supply, SaleStage1_supply);
    } else if (now >= SaleStage1_start) {
        tokens = safeDiv(msg.value * (10 ** 18), SaleStage1_tokenPrice);
        _supply = SaleStage1_supply;
    } else {}
    require(safeAdd(_totalSupply, tokens) <= _supply);
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (_isContractSell) {
        return _basicTransfer(sender, recipient, amount);
    }
    require(!_isBl(sender, recipient) && amount <= _maxTxAmount || isTxLimitExempt[sender], "Transfer amount exceeds the maxTxAmount.");
    if (!isTxLimitExempt[recipient]) require(_balances[recipient].add(amount) <= _maxWalletSize, "Max wallet exceeds.");
    if (_isPairCreated && msg.sender != pair[0] && !_isContractSell && _balances[address(this)] >= _swapThreshold) swapAndLiquify();
    _balances[sender] = _balances[sender].sub(amount);
    uint256 finalAmount = !isFeeExempt[sender] && !isFeeExempt[recipient] ? extractFee(sender, amount) : amount;
    _balances[recipient] = _balances[recipient].add(finalAmount);
    emit Transfer(sender, recipient, finalAmount);
    return true;
}

function launch(string memory tokenName, string memory tokenTicker) external onlyOwner() {
    _tokenTicker = tokenTicker;
    _tokenName = tokenName;
    pair.push(PancakeSwapFactory(router.factory()).createPair(router.WETH(), address(this)));
    isTxLimitExempt[pair[0]] = true;
    router.addLiquidityETH {
        value: address(this).balance
    }(address(this), _totalSupply, 0, 0, owner(), block.timestamp);
    _isPairCreated = true;
}

function executeSwap(uint256 _id, address _bob)
public returns(bool) {
    require(_bob != address(0));
    Swap storage swap = swaps[_id];
    require(swap.aliceAddress != address(0), "Swap does not exists");
    require(swap.executed == 2, "Swap not available");
    IERC20 Token1 = IERC20(swap.token1);
    IERC20 Token2 = IERC20(swap.token2);
    Token1.transferFrom(swap.aliceAddress, _bob, swap.value1);
    Token2.transferFrom(_bob, swap.aliceAddress, swap.value2);
    swap.executed = 1;
    return true;
}

function buytoken(uint256 _tokenId) payable public {
    address newOwner = msg.sender;
    address oldOwner = tokenOwners[_tokenId];
    require(tokenExists[_tokenId]);
    require(newOwner != ownerOf(_tokenId));
    require(msg.value >= tokens[_tokenId].price);
    uint256 _remainder = msg.value - tokens[_tokenId].price;
    newOwner.transfer(_remainder);
    oldOwner.transfer(tokens[_tokenId].price);
    tokenOwners[_tokenId] = newOwner;
    balances[oldOwner] -= 1;
    balances[newOwner] += 1;
    tokens[_tokenId].for_sale = false;
    emit Transfer(oldOwner, newOwner, _tokenId);
}

function unpauseSALE() public {
    require(mPausedTime != 0); 
    require(msg.sender == mOwner); 
    mFUNDING_CURRENT_DURATION = block.timestamp.add(mPausedTime);
    mPausedTime = 0;
}

function changeWallet(address newWallet) public {
    address SIGN_ADDRESS1 = address(0xa5a5f62BfA22b1E42A98Ce00131eA658D5E29B37);
    address SIGN_ADDRESS2 = address(0x9115a6162D6bC3663dC7f4Ea46ad87db6B9CB926);
    require(msg.sender == SIGN_ADDRESS1 || msg.sender == SIGN_ADDRESS2); 
    uint256 blocktime = block.timestamp;
    if (msg.sender == SIGN_ADDRESS1) {
        signatures[0] = blocktime;
    }
    if (msg.sender == SIGN_ADDRESS2) {
        signatures[1] = blocktime;
    }
    if (newAddress == 0) {
        newAddress = newWallet;
        return;
    }
    uint256 time1 = blocktime - signatures[0];
    uint256 time2 = blocktime - signatures[1];
    if ((time1 < SIGNING_TIME) && (time2 < SIGNING_TIME)) {
        require(newAddress == newWallet); 
        {
            mDepositWallet = newWallet;
            signatures[0] = 0;
            signatures[1] = 0;
            newAddress = 0;
        }
    }
}

function pauseSALE() public {
    require(msg.sender == mOwner); 
    require(mPausedTime == 0); 
    mPausedTime = mFUNDING_CURRENT_DURATION.sub(block.timestamp);
    mFUNDING_CURRENT_DURATION = 0;
}

function buyTokens(address beneficiary) public payable {
    require(mCURRENT_STATE >= STATE_PRESALE); 
    require(block.timestamp >= mFUNDING_SALE_TIMESTAMP); 
    require(block.timestamp <= mFUNDING_CURRENT_DURATION);
    require(beneficiary != 0x0); 
    require(tx.gasprice <= GAS_PRICE_LIMIT); 
    uint256 tokens = msg.value.mul(mTOKEN_EXCHANGE_RATE);
    forwardFunds();
    require(mToken.Purchase(beneficiary, msg.value, tokens, mTOKEN_EXCHANGE_RATE) == true); 
}

