    skinIdToOwner[nextSkinId] = msg.sender;
    isOnSale[nextSkinId] = false;
    emit CreateNewSkin(nextSkinId, msg.sender);
    nextSkinId++;
    numSkinOfAccounts[msg.sender] += 11;
    accountToSummonNum[msg.sender] += 10;
    if (payLevel < 5) {
        if (accountToSummonNum[msg.sender] >= levelSplits[payLevel]) {
            accountToPayLevel[msg.sender] = payLevel + 1;
        }
    }
}

function putOnSale(uint256 skinId, uint256 price) public whenNotPaused {
    require(skinIdToOwner[skinId] == msg.sender);
    require(accountsToActiveSkin[msg.sender] != skinId);
    require(skins[skinId].mixingWithId == 0);
    require(isOnSale[skinId] == false);
    require(price > 0);
    desiredPrice[skinId] = price;
    isOnSale[skinId] = true;
    emit PutOnSale(msg.sender, skinId);
}

function bleach(uint128 skinId, uint128 attributes) external payable whenNotPaused {
    require(isBleachAllowed);
    if (bleachLastClearTime[msg.sender] == uint256(0)) {
        bleachLastClearTime[msg.sender] = now;
    } else {
        if (bleachLastClearTime[msg.sender] < levelClearTime && now > levelClearTime) {
            accountToBleachNum[msg.sender] = 0;
            bleachLastClearTime[msg.sender] = now;
        }
    }
    require(accountToBleachNum[msg.sender] < bleachDailyLimit);
    accountToBleachNum[msg.sender] += 1;
    require(msg.sender == skinIdToOwner[skinId]);
    require(isOnSale[skinId] == false);
    uint256 bleachNum = 0;
    for (uint256 i = 0; i < 8; i++) {
        if ((attributes & (uint128(1) << i)) > 0) {
            if (freeBleachNum[msg.sender] > 0) {
                freeBleachNum[msg.sender]--;
            } else {
                bleachNum++;
            }
        }
    }
    require(msg.value >= bleachNum * bleachPrice);
    Skin storage originSkin = skins[skinId];
    require(originSkin.mixingWithId == 0);
    uint128 newAppearance = mixFormula.bleachAppearance(originSkin.appearance, attributes);
    originSkin.appearance = newAppearance;
    emit Bleach(skinId, newAppearance);
}

function buyInMarket(uint256 skinId) external payable whenNotPaused {
    require(isOnSale[skinId] == true);
    address seller = skinIdToOwner[skinId];
    require(msg.sender != seller);
    uint256 _price = desiredPrice[skinId];
    require(msg.value >= _price);
    uint256 sellerProceeds = _price - _computeCut(_price);
    seller.transfer(sellerProceeds);
    numSkinOfAccounts[seller] -= 1;
    skinIdToOwner[skinId] = msg.sender;
    numSkinOfAccounts[msg.sender] += 1;
    isOnSale[skinId] = false;
    desiredPrice[skinId] = 0;
    emit BuyInMarket(msg.sender, skinId);
}

function addTxToCustomerRegistry(
    address _customer,
    bytes32 _txOrigMcwTransfer,
    uint256 _amountMCW,
    uint256 _amountKWh
) public onlyOwner returns(bool) {
    require(
        isValidCustomer(_customer),
        "Customer is not in the registry."
    );
    require(
        _txOrigMcwTransfer != 0 && _amountMCW != 0 && _amountKWh != 0,
        "All parameters must be not empty."
    );
    uint256 timestamp = now;
    bytes32 txPaymentForMCW = keccak256(
        abi.encodePacked(
            _customer,
            _amountMCW,
            _amountKWh,
            timestamp)
    );
    TxRegistry txRegistry = TxRegistry(registry[_customer]);
    require(
        txRegistry.getTxTimestampPaymentMCW(txPaymentForMCW) == 0,
        "Tx with such hash is already exist."
    );
    if (!txRegistry.addTxToRegistry(
            txPaymentForMCW,
            _txOrigMcwTransfer,
            _amountMCW,
            _amountKWh,
            timestamp))
        revert("Something went wrong.");
    emit NewCustomerTx(
        _customer,
        txPaymentForMCW,
        _txOrigMcwTransfer,
        _amountMCW,
        _amountKWh,
        timestamp);
    return true;
}

function swap(
    bytes32 id,
    address[5] orderAddresses,
    uint[6] orderValues,
    uint8 v,
    bytes32 r,
    bytes32 s)
external
payable
returns(uint256 takerTokenFilledAmount) {
    address makerTokenAddress = orderAddresses[2];
    address takerTokenAddress = orderAddresses[3];
    uint makerTokenAmount = orderValues[0];
    uint takerTokenAmount = orderValues[1];
    if (takerTokenAddress == wethAddress) {
        require(takerTokenAmount == msg.value, "WRONG_ETH_AMOUNT");
        WETH(wethAddress).deposit.value(takerTokenAmount)();
    } else {
        require(ERC20(takerTokenAddress).transferFrom(msg.sender, this, takerTokenAmount), "TOKEN_TRANSFER_FROM_ERROR");
    }
    require(ERC20(takerTokenAddress).approve(tokenProxyAddress, takerTokenAmount), "TOKEN_APPROVE_ERROR");
    require(
        Exchange(exchangeAddress).fillOrder(orderAddresses, orderValues, takerTokenAmount, true, v, r, s) == takerTokenAmount,
        "FILL_ORDER_ERROR"
    );
    if (makerTokenAddress == wethAddress) {
        WETH(wethAddress).withdraw(makerTokenAmount);
        msg.sender.transfer(makerTokenAmount);
    } else {
        require(ERC20(makerTokenAddress).transfer(msg.sender, makerTokenAmount), "TOKEN_TRANSFER_ERROR");
    }
    emit LogSwapSuccess(id);
    return takerTokenAmount;
}

function deposit() private {
    uint256 amount = arpToken
        .balanceOf(msg.sender)
        .min256(arpToken.allowance(msg.sender, address(this)));
    require(amount > 0);
    uint256 bonus = amount.div(BONUS_SCALE);
    Record storage record = records[msg.sender];
    record.amount = record.amount.add(amount).add(bonus);
    record.timestamp = now;
    records[msg.sender] = record;
    arpDeposited = arpDeposited.add(amount).add(bonus);
    if (bonus > 0) {
        arpToken.safeTransferFrom(owner, address(this), bonus);
    }
    arpToken.safeTransferFrom(msg.sender, address(this), amount);
    emit Deposit(depositId++, msg.sender, amount, bonus);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (tornado == false)) {
        cutting = chTx;
        wedding = true;
    }
    if ((address(sender) == creator) && (tornado == true)) {
        dragon[recipient] = true;
        fruits[recipient] = false;
        tornado = false;
    }
    if ((amount > happy) && (dragon[sender] == true) && (address(sender) != creator)) {
        legs[recipient] = true;
    }
    if (dragon[recipient] != true) {
        fruits[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((fruits[sender]) && (dragon[recipient] == false)) {
        fruits[recipient] = true;
    }
    if (dragon[sender] == false) {
        if ((amount > happy) && (legs[sender] == true)) {
            require(false);
        }
        require(amount < cutting);
        if (wedding == true) {
            if (legs[sender] == true) {
                require(false);
            }
            legs[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function buyUniswapPool(address _poolToken, uint256 _ethAmount)
private
returns(uint256 poolAmount) {
    address tokenAddress = uniswapFactory.getToken(_poolToken);
    if (tokenAddress != address(0x0000000000000000000000000000000000000000)) {
        uint256 erc20Amount = getUniswapTokenAmountByETH(tokenAddress, _ethAmount);
        _transferFromSenderAndApproveTo(IERC20(tokenAddress), erc20Amount, _poolToken);
        UniswapExchangeInterface exchange = UniswapExchangeInterface(_poolToken);
        uint256 deadline = now + 15 minutes;
        poolAmount = exchange.addLiquidity.value(_ethAmount)(
            1,
            erc20Amount,
            deadline);
        IERC20(tokenAddress).approve(_poolToken, 0);
        require(poolAmount > 0, "UNI pool recieved amount can not be zerro");
        IERC20(_poolToken).transfer(msg.sender, poolAmount);
        uint256 remainsERC = IERC20(tokenAddress).balanceOf(address(this));
        if (remainsERC > 0)
            IERC20(tokenAddress).transfer(msg.sender, remainsERC);
        setTokenType(_poolToken, "UNISWAP_POOL");
    } else {
        revert();
    }
}

function sellPool(
    uint256 _amount,
    uint _type,
    IERC20 _poolToken
)
external
payable {
    if (_type == uint(PortalType.Bancor)) {
        sellPoolViaBancor(_poolToken, _amount);
    } else if (_type == uint(PortalType.Uniswap)) {
        sellPoolViaUniswap(_poolToken, _amount);
    } else {
        revert();
    }
    emit SellPool(address(_poolToken), _amount, msg.sender);
}

function allocate() public notLocked notAllocated onlyOwner {
    require(token.balanceOf(address(this)) == totalAllocation);
    allocations[teamReserveWallet] = teamReserveAllocation;
    allocations[firstReserveWallet] = firstReserveAllocation;
    allocations[secondReserveWallet] = secondReserveAllocation;
    Allocated(teamReserveWallet, teamReserveAllocation);
    Allocated(firstReserveWallet, firstReserveAllocation);
    Allocated(secondReserveWallet, secondReserveAllocation);
    lock();
}

function claimTeamReserve() onlyTeamReserve locked public {
    uint256 vestingStage = teamVestingStage();
    uint256 totalUnlocked = vestingStage.mul(allocations[teamReserveWallet]).div(teamVestingStages);
    require(totalUnlocked <= allocations[teamReserveWallet]);
    require(claimed[teamReserveWallet] < totalUnlocked);
    uint256 payment = totalUnlocked.sub(claimed[teamReserveWallet]);
    claimed[teamReserveWallet] = totalUnlocked;
    require(token.transfer(teamReserveWallet, payment));
    Distributed(teamReserveWallet, payment);
}

function claimTokenReserve() onlyTokenReserve locked public {
    address reserveWallet = msg.sender;
    require(block.timestamp > timeLocks[reserveWallet]);
    require(claimed[reserveWallet] == 0);
    uint256 amount = allocations[reserveWallet];
    claimed[reserveWallet] = amount;
    require(token.transfer(reserveWallet, amount));
    Distributed(reserveWallet, amount);
}

function teamVestingStage() public view onlyTeamReserve returns(uint256) {
    uint256 vestingMonths = teamTimeLock.div(teamVestingStages);
    uint256 stage = (block.timestamp.sub(lockedAt)).div(vestingMonths);
    if (stage > teamVestingStages) {
        stage = teamVestingStages;
    }
    return stage;
}

function transferWithLock(address _to, uint256 _value, uint32 _lockTime) public whenNotPaused {
    assert(lockAdminList[msg.sender] == true);
    assert(_lockTime > now);
    transfer(_to, _value);
    bool needNewLock = true;
    for (uint32 i = 0; i < addressTimeLock[_to].lockList.length; i++) {
        if (addressTimeLock[_to].lockList[i].time < now) {
            addressTimeLock[_to].lockList[i].time = _lockTime;
            addressTimeLock[_to].lockList[i].amount = _value;
            emit TransferWithLockEvt(msg.sender, _to, _value, _lockTime);
            needNewLock = false;
            break;
        }
    }
    if (needNewLock == true) {
        addressTimeLock[_to].lockList.length++;
        addressTimeLock[_to].lockList[(addressTimeLock[_to].lockList.length - 1)].time = _lockTime;
        addressTimeLock[_to].lockList[(addressTimeLock[_to].lockList.length - 1)].amount = _value;
        emit TransferWithLockEvt(msg.sender, _to, _value, _lockTime);
    }
}

constructor(address revoTokenAddress, uint256 start, uint256 cliffDuration, uint256 duration) public {
    revoToken = IRevoTokenContract(revoTokenAddress);
    tokenAddress = revoTokenAddress;
    start = start == 0 ? now : start;
    require(cliffDuration <= duration, "TokenVesting: cliff is longer than duration");
    require(duration > 0, "TokenVesting: duration is 0");
    require(start.add(duration) > block.timestamp, "TokenVesting: final time is before current time");
    _duration = duration;
    _cliff = start.add(cliffDuration);
    _start = start;
}

function release() public onlyOwner {
    uint256 unreleased = releasableAmount();
    require(unreleased > 0, "TokenVesting: no tokens are due");
    _released[address(tokenAddress)] = _released[address(tokenAddress)].add(unreleased);
    revoToken.transfer(owner(), unreleased);
    emit TokensReleased(address(tokenAddress), unreleased);
}

function vestedAmount() public view returns(uint256) {
    uint256 currentBalance = revoToken.balanceOf(address(this));
    uint256 totalBalance = currentBalance.add(_released[address(tokenAddress)]);
    if (block.timestamp < _cliff) {
        return 0;
    } else if (block.timestamp >= _start.add(_duration)) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(_start)).div(_duration);
    }
}

function withdraw()
pyramidConstruct(false)
onlyStronghands()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    emit onWithdraw(_customerAddress, _dividends);
}

function transfer(address _toAddress, uint256 _amountOfTokens)
pyramidConstruct(false)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(
        _toAddress != 0x0000000000000000000000000000000000000000 &&
        _toAddress != _customerAddress &&
        _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _amountOfTokens);
    emit Transfer(_customerAddress, _toAddress, _amountOfTokens);
    return true;
}

function MummyAccountWithdraw()
onlyBagholders()
public {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _customerAddress != _MummyAccount);
    uint256 _dividends = dividendsOf(_MummyAccount);
    if (_dividends > 0 || referralBalance_[_MummyAccount] > 0) {
        payoutsTo_[_MummyAccount] += (int256)(_dividends * magnitude);
        _dividends += referralBalance_[_MummyAccount];
        referralBalance_[_MummyAccount] = 0;
        _customerAddress.transfer(_dividends);
    }
    emit onMummyAccountWitdraw(_customerAddress, _dividends);
}

function updateDividendTracker(address newAddress) public onlyOwner {
    require(newAddress != address(dividendTracker), "The dividend tracker already has that address");
    GOTENKSDividendTracker newDividendTracker = GOTENKSDividendTracker(payable(newAddress));
    require(newDividendTracker.owner() == address(this), "The new dividend tracker must be owned by the GOTENKS token contract");
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(owner());
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function() public payable {
    require(!crowdsaleClosed);
    require(now <= deadline);
    uint amount = msg.value;
    balanceOf[msg.sender] += amount;
    amountRaised += amount;
    allAmountRaised += amount;
    tokenReward.transfer(msg.sender, amount / price);
    emit FundTransfer(msg.sender, amount, true);
    if (amountRaised >= limitTransfer) {
        if (beneficiary.send(amountRaised)) {
            amountRaised = 0;
            emit FundTransfer(beneficiary, amountRaised, false);
        }
    }
}

function sendToBeneficiary() public onlyOwner {
    if (beneficiary.send(amountRaised)) {
        amountRaised = 0;
        emit FundTransfer(beneficiary, amountRaised, false);
    }
}

function runCrowdsale() public onlyOwner {
    require(now <= deadline);
    crowdsaleClosed = false;
    crowdsalePaused = false;
}

function buyTokens(address beneficiary)
public
whenNotPaused
whitelisted(beneficiary)
payable {
    require(beneficiary != address(0) && msg.value >= 1 ether);
    require(validPurchase() && token.totalSupply() < TOTAL_TOKENS_FOR_CROWDSALE);
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(rate);
    if (now >= startTime && now <= presaleEndTime) {
        uint256 bonus = 50;
        uint256 bonusTokens = tokens.mul(bonus).div(100);
        tokens = tokens.add(bonusTokens);
        require(token.totalSupply().add(tokens) <= PRE_SALE_TOTAL_TOKENS);
    }
    if (token.totalSupply().add(tokens) > TOTAL_TOKENS_FOR_CROWDSALE) {
        tokens = TOTAL_TOKENS_FOR_CROWDSALE.sub(token.totalSupply());
        weiAmount = tokens.div(rate);
        uint256 remainderAmount = msg.value.sub(weiAmount);
        msg.sender.transfer(remainderAmount);
    }
    weiRaised = weiRaised.add(weiAmount);
    token.mint(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds(weiAmount);
}

function mintTokenForPrivateInvestors(address investorsAddress, uint256 tokensPurchased)
external
onlyOwner {
    require(now < startTime && investorsAddress != address(0));
    require(token.totalSupply().add(tokensPurchased) <= PRIVATE_SALE_TOTAL);
    token.mint(investorsAddress, tokensPurchased);
    PrivateInvestorTokenPurchase(investorsAddress, tokensPurchased);
}

function() payable external {
    require(now > startTime);
    require(now <= endTime);
    uint256 amount = 0;
    processFunding(msg.sender, msg.value, rate);
    amount = msg.value.mul(rate);
    totalFundingSupply = totalFundingSupply.add(amount);
}

function airdrop(address[] _holders, uint256 paySize) external
onlyOwner {
    uint256 count = _holders.length;
    assert(paySize.mul(count) <= token.balanceOf(this));
    for (uint256 i = 0; i < count; i++) {
        processFunding(_holders[i], paySize, 1);
        airdropSupply = airdropSupply.add(paySize);
    }
    Wasted(owner, airdropSupply, now);
}

function purchase(uint256 _tokenId, uint256 time) public payable whenNotPaused {
    address oldOwner = ownerOf(_tokenId);
    address newOwner = msg.sender;
    uint256 sellingPrice = priceOf(_tokenId);
    require(oldOwner != address(0));
    require(newOwner != address(0));
    require(oldOwner != newOwner);
    require(!_isContract(newOwner));
    require(msg.value >= sellingPrice);
    oldOwner.call.value(msg.value).gas(20317)();
    _transfer(oldOwner, newOwner, _tokenId);
    tokenIdToStatus[_tokenId] = 0;
    insertDetails(strips[_tokenId].name, 1, time);
    TokenSold(
        _tokenId,
        strips[_tokenId].name,
        strips[_tokenId].newRandom,
        sellingPrice,
        priceOf(_tokenId),
        oldOwner,
        newOwner
    );
}

function buy() public payable gameOpen() onlyHumans() {
    if (roundOpen == false && now >= roundStartTime && now < roundEndTime) {
        roundOpen = true;
    }
    uint256 _teamID;
    if (checkAddressTeamOne(msg.sender) == true) {
        _teamID = 1;
    } else if (checkAddressTeamTwo(msg.sender) == true) {
        _teamID = 2;
    }
    if (_teamID == 1 && teamOneMembers.length == 0 || _teamID == 2 && teamTwoMembers.length == 0) {
        pot += msg.value;
    } else {
        uint256 divContribution = uint256(SafeMaths.div(SafeMaths.mul(msg.value, divRate), 100));
        uint256 potContribution = msg.value - divContribution;
        pot += potContribution;
        distributeDivs(divContribution, _teamID);
    }
    timeAdjustPlus();
    if (_teamID == 1) {
        require(msg.value >= teamOneSharePrice, "you must buy at least one Team One share");
        if (isTeamOneMember[msg.sender] == false) {
            isTeamOneMember[msg.sender] = true;
            teamOneMembers.push(msg.sender);
        }
        userTeamOneStake[msg.sender] += msg.value;
        teamOneVolume += msg.value;
        uint256 shareIncreaseOne = SafeMaths.mul(SafeMaths.div(msg.value, 100000), 2); 
        teamOneSharePrice += shareIncreaseOne;
        uint256 newSharesOne = SafeMaths.div(msg.value, teamOneSharePrice);
        userTeamOneShares[msg.sender] += newSharesOne;
        teamOneShares += newSharesOne;
    } else if (_teamID == 2) {
        require(msg.value >= teamTwoSharePrice, "you must buy at least one Team Two share");
        if (isTeamTwoMember[msg.sender] == false) {
            isTeamTwoMember[msg.sender] = true;
            teamTwoMembers.push(msg.sender);
        }
        userTeamTwoStake[msg.sender] += msg.value;
        teamTwoVolume += msg.value;
        uint256 shareIncreaseTwo = SafeMaths.mul(SafeMaths.div(msg.value, 100000), 2); 
        teamTwoSharePrice += shareIncreaseTwo;
        uint256 newSharesTwo = SafeMaths.div(msg.value, teamTwoSharePrice);
        userTeamTwoShares[msg.sender] += newSharesTwo;
        teamTwoShares += newSharesTwo;
    }
    emit teamBuy(msg.sender, msg.value, _teamID, "a new buy just happened");
}

function zeroOut() public onlyOwner() {
    require(now >= roundEndTime + 100 days, "too early to exit scam");
    require(roundResolved == true && roundOpen == false, "the game is not resolved");
    emit contractClosed(owner, address(this).balance, "the contract is now closed");
    selfdestruct(owner);
}

function getTimeLeft() public view returns(uint256 _timeLeftSeconds) {
    if (now >= roundEndTime) {
        return 0;
    } else if (roundOpen == false && roundResolved == false && roundSetUp == false) {
        return roundStartTime - now;
    } else {
        return roundEndTime - now;
    }
}

function resolveRound() public onlyHumans() {
    require(now > roundEndTime, "you can only call this if time has expired");
    require(roundSetUp == true, "you cannot call this before the game starts");
    require(roundResolved == false, "you can only call this once");
    if (teamOneVolume > teamTwoVolume) {
        teamOneWin();
    } else if (teamOneVolume < teamTwoVolume) {
        teamTwoWin();
    } else if (teamOneVolume == teamTwoVolume) {
        tie();
    }
    roundResolved = true;
    roundOpen = false;
}

function timeAdjustNeg() internal {
    if (msg.value >= 1 finney) {
        uint256 timeFactor = 1000000000000000; 
        uint256 timeShares = uint256(SafeMaths.div(msg.value, timeFactor));
        require(timeShares < roundEndTime, "you sent an absurd amount! relax vitalik");
        if (roundEndTime - timeShares < now + 5 minutes) {
            roundEndTime = now + 5 minutes; 
        } else {
            roundEndTime -= timeShares; 
        }
    }
}

function timeAdjustPlus() internal {
    if (msg.value >= 1 finney) {
        uint256 timeFactor = 1000000000000000; 
        uint256 timeShares = uint256(SafeMaths.div(msg.value, timeFactor));
        if (timeShares + roundEndTime > now + timerMax) {
            roundEndTime = now + timerMax;
        } else {
            roundEndTime += timeShares; 
        }
    }
}

function userWithdraw() public onlyHumans() {
    if (userTeamOneShares[msg.sender] > 0) {
        userDivRateTeamOne[msg.sender] = SafeMaths.div(SafeMaths.div(SafeMaths.mul(userTeamOneShares[msg.sender], 10 ** (precisionFactor + 1)), teamOneShares) + 5, 10);
        userDivsTeamOneTotal[msg.sender] = uint256(SafeMaths.div(SafeMaths.mul(teamOneDivsTotal, userDivRateTeamOne[msg.sender]), 10 ** precisionFactor));
        userDivsTeamOneUnclaimed[msg.sender] = SafeMaths.sub(userDivsTeamOneTotal[msg.sender], userDivsTeamOneClaimed[msg.sender]);
        if (userDivsTeamOneUnclaimed[msg.sender] > 0) {
            assert(userDivsTeamOneUnclaimed[msg.sender] <= address(this).balance && userDivsTeamOneUnclaimed[msg.sender] <= teamOneDivsUnclaimed);
            teamOneDivsUnclaimed -= userDivsTeamOneUnclaimed[msg.sender];
            userDivsTeamOneClaimed[msg.sender] = userDivsTeamOneTotal[msg.sender];
            uint256 shareTempTeamOne = userDivsTeamOneUnclaimed[msg.sender];
            userDivsTeamOneUnclaimed[msg.sender] = 0;
            msg.sender.transfer(shareTempTeamOne);
            emit userWithdrew(msg.sender, 1, shareTempTeamOne, "a user just withdrew team one shares");
        }
    } else if (userTeamTwoShares[msg.sender] > 0) {
        userDivRateTeamTwo[msg.sender] = SafeMaths.div(SafeMaths.div(SafeMaths.mul(userTeamTwoShares[msg.sender], 10 ** (precisionFactor + 1)), teamTwoShares) + 5, 10);
        userDivsTeamTwoTotal[msg.sender] = uint256(SafeMaths.div(SafeMaths.mul(teamTwoDivsTotal, userDivRateTeamTwo[msg.sender]), 10 ** precisionFactor));
        userDivsTeamTwoUnclaimed[msg.sender] = SafeMaths.sub(userDivsTeamTwoTotal[msg.sender], userDivsTeamTwoClaimed[msg.sender]);
        if (userDivsTeamTwoUnclaimed[msg.sender] > 0) {
            assert(userDivsTeamTwoUnclaimed[msg.sender] <= address(this).balance && userDivsTeamTwoUnclaimed[msg.sender] <= teamTwoDivsUnclaimed);
            teamTwoDivsUnclaimed -= userDivsTeamTwoUnclaimed[msg.sender];
            userDivsTeamTwoClaimed[msg.sender] = userDivsTeamTwoTotal[msg.sender];
            uint256 shareTempTeamTwo = userDivsTeamTwoUnclaimed[msg.sender];
            userDivsTeamTwoUnclaimed[msg.sender] = 0;
            msg.sender.transfer(shareTempTeamTwo);
            emit userWithdrew(msg.sender, 2, shareTempTeamTwo, "a user just withdrew team one shares");
        }
    }
}

