function _addSale(uint256 _assetId, CollectibleSale _sale) internal {
    require(_sale.duration >= 1 minutes);
    tokenIdToSale[_assetId] = _sale;
    var ccNFT = CCNFTFactory(NFTAddress);
    uint256 assetType = ccNFT.getAssetIdItemType(_assetId);
    assetTypeSalesTokenId[assetType].push(_assetId);
    SaleCreated(
        uint256(_assetId),
        uint256(_sale.startingPrice),
        uint256(_sale.endingPrice),
        uint256(_sale.duration),
        uint64(_sale.startedAt)
    );
}

function _createSale(uint256 _tokenId, uint256 _startingPrice, uint256 _endingPrice, uint64 _duration, address _seller) internal {
    var ccNFT = CCNFTFactory(NFTAddress);
    require(ccNFT.isAssetIdOwnerOrApproved(this, _tokenId) == true);
    CollectibleSale memory onSale = tokenIdToSale[_tokenId];
    require(onSale.isActive == false);
    require(_startingPrice == uint256(uint128(_startingPrice)));
    require(_endingPrice == uint256(uint128(_endingPrice)));
    require(_duration == uint256(uint64(_duration)));
    if (ccNFT.ownerOf(_tokenId) != address(this)) {
        require(ccNFT.isApprovedForAll(msg.sender, this) == true);
        ccNFT.safeTransferFrom(ccNFT.ownerOf(_tokenId), this, _tokenId);
    }
    CollectibleSale memory sale = CollectibleSale(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint64(now),
        true,
        address(0),
        uint256(_tokenId)
    );
    _addSale(_tokenId, sale);
}

function _cancelSale(uint256 _assetId) internal {
    CollectibleSale storage _sale = tokenIdToSale[_assetId];
    require(_sale.isActive == true);
    address sellerAddress = _sale.seller;
    _removeSale(_assetId);
    var ccNFT = CCNFTFactory(NFTAddress);
    ccNFT.safeTransferFrom(this, sellerAddress, _assetId);
    emit SaleCancelled(sellerAddress, _assetId);
}

function _buy(uint256 _assetId, address _buyer, uint256 _price) internal {
    CollectibleSale storage _sale = tokenIdToSale[_assetId];
    uint256 currentPrice = _currentPrice(_sale);
    require(_price >= currentPrice);
    _sale.buyer = _buyer;
    _sale.isActive = false;
    _removeSale(_assetId);
    uint256 bidExcess = _price - currentPrice;
    _buyer.transfer(bidExcess);
    var ccNFT = CCNFTFactory(NFTAddress);
    uint256 assetType = ccNFT.getAssetIdItemType(_assetId);
    _updateSaleAvgHistory(assetType, _price);
    ccNFT.safeTransferFrom(this, _buyer, _assetId);
    emit SaleWinner(_buyer, _assetId, _price);
}

function BatchCreateSaleAvgPrice(uint256[] _tokenIds, uint256 _margin, uint _minPrice, uint256 _endingPrice, uint64 _duration, address _seller) public anyOperator {
    var ccNFT = CCNFTFactory(NFTAddress);
    uint256 assetType;
    uint256 _tokenId;
    uint256 salePrice;
    for (uint256 i = 0; i < _tokenIds.length; ++i) {
        _tokenId = _tokenIds[i];
        assetType = ccNFT.getAssetIdItemType(_tokenId);
        salePrice = GetAssetTypeAverageSalePrice(assetType);
        salePrice = salePrice * _margin / 10000;
        if (salePrice < _minPrice) {
            salePrice = _minPrice;
        }
        _tokenId = _tokenIds[i];
        _createSale(_tokenId, salePrice, _endingPrice, _duration, _seller);
    }
}

function vendingCreateCollectible(uint256 _collectibleType, address _toAddress) payable external whenNotPaused {
    require((vendingAmountType[_collectibleType] - vendingTypeSold[_collectibleType]) > 0);
    require(msg.value >= vendingPrice[_collectibleType]);
    require(msg.sender != address(0));
    require(msg.sender != address(this));
    require(_toAddress != address(0));
    require(_toAddress != address(this));
    var ccNFT = CCNFTFactory(NFTAddress);
    ccNFT.spawnAsset(_toAddress, _collectibleType, startingIndex, vendingAttachedState);
    startingIndex += 1;
    vendingTypeSold[_collectibleType] += 1;
    uint256 excessBid = msg.value - vendingPrice[_collectibleType];
    if (vendingTypeSold[_collectibleType] % vendingStepUpQty[_collectibleType] == 0) {
        vendingPrice[_collectibleType] += vendingStepUpAmount[_collectibleType];
    }
    if (excessBid > 0) {
        msg.sender.transfer(excessBid);
    }
}

function _removeSale(uint256 _assetId) internal {
    delete tokenIdToSale[_assetId];
    var ccNFT = CCNFTFactory(NFTAddress);
    uint256 assetType = ccNFT.getAssetIdItemType(_assetId);
    bool hasFound = false;
    for (uint i = 0; i < assetTypeSalesTokenId[assetType].length; i++) {
        if (assetTypeSalesTokenId[assetType][i] == _assetId) {
            hasFound = true;
        }
        if (hasFound == true) {
            if (i + 1 < assetTypeSalesTokenId[assetType].length)
                assetTypeSalesTokenId[assetType][i] = assetTypeSalesTokenId[assetType][i + 1];
            else
                delete assetTypeSalesTokenId[assetType][i];
        }
    }
    assetTypeSalesTokenId[assetType].length--;
}

function startDefinedGame(uint _index)
public
returns(address _game) {
    DefinedGame memory dGame = definedGames[_index];
    if (_index - 1 >= numDefinedGames) {
        _error("Index out of bounds.");
        return;
    }
    if (dGame.isEnabled == false) {
        _error("DefinedGame is not enabled.");
        return;
    }
    if (dGame.game != IMonarchyGame(0)) {
        _error("Game is already started.");
        return;
    }
    if (address(this).balance < dGame.initialPrize) {
        _error("Not enough funds to start this game.");
        return;
    }
    if (getDailyLimitRemaining() < dGame.initialPrize) {
        _error("Starting game would exceed daily limit.");
        return;
    }
    IMonarchyFactory _mf = getMonarchyFactory();
    if (_mf.getCollector() != address(this)) {
        _error("MonarchyFactory.getCollector() points to a different contract.");
        return;
    }
    bool _success = address(_mf).call.value(dGame.initialPrize)(
        bytes4(keccak256("createGame(uint256,uint256,int256,uint256,uint256)")),
        dGame.initialPrize,
        dGame.fee,
        dGame.prizeIncr,
        dGame.reignBlocks,
        dGame.initialBlocks
    );
    if (!_success) {
        emit DefinedGameFailedCreation(now, _index);
        _error("MonarchyFactory could not create game (invalid params?)");
        return;
    }
    _useFromDailyLimit(dGame.initialPrize);
    _game = _mf.lastCreatedGame();
    definedGames[_index].game = IMonarchyGame(_game);
    emit GameStarted(now, _index, _game, dGame.initialPrize);
    return _game;
}

function refreshGames()
public
returns(uint _numGamesEnded, uint _feesCollected) {
    for (uint _i = 1; _i <= numDefinedGames; _i++) {
        IMonarchyGame _game = definedGames[_i].game;
        if (_game == IMonarchyGame(0)) continue;
        uint _fees = _game.sendFees();
        _feesCollected += _fees;
        if (_game.isEnded()) {
            if (!_game.isPaid()) _game.sendPrize(2300);
            totalPrizes += _game.prize();
            totalOverthrows += _game.numOverthrows();
            definedGames[_i].game = IMonarchyGame(0);
            endedGames.push(_game);
            _numGamesEnded++;
            emit GameEnded(now, _i, address(_game), _game.monarch());
        }
    }
    if (_feesCollected > 0) emit FeesCollected(now, _feesCollected);
    return (_numGamesEnded, _feesCollected);
}

function editDefinedGame(
    uint _index,
    string _summary,
    uint _initialPrize,
    uint _fee,
    int _prizeIncr,
    uint _reignBlocks,
    uint _initialBlocks
)
public
fromAdmin
returns(bool _success) {
    if (_index - 1 > numDefinedGames || _index > 20) {
        emit Error(now, "Index out of bounds.");
        return;
    }
    if (_index - 1 == numDefinedGames) numDefinedGames++;
    definedGames[_index].summary = _summary;
    definedGames[_index].initialPrize = _initialPrize;
    definedGames[_index].fee = _fee;
    definedGames[_index].prizeIncr = _prizeIncr;
    definedGames[_index].reignBlocks = _reignBlocks;
    definedGames[_index].initialBlocks = _initialBlocks;
    emit DefinedGameEdited(now, _index);
    return true;
}

function enableDefinedGame(uint _index, bool _bool)
public
fromAdmin
returns(bool _success) {
    if (_index - 1 >= numDefinedGames) {
        emit Error(now, "Index out of bounds.");
        return;
    }
    definedGames[_index].isEnabled = _bool;
    emit DefinedGameEnabled(now, _index, _bool);
    return true;
}

function invest(address _referer) public payable notOnPause checkDayRollover {
    require(msg.value >= minInvestment);
    require(msg.value <= maxInvestment);
    uint256 devAmount = m_devPercent.mul(msg.value);
    if (!m_referrals[msg.sender]) {
        if (notZeroAndNotSender(_referer) && investor_contains(_referer)) {
            uint256 _reward = m_refPercent.mul(msg.value);
            devAmount.sub(_reward);
            assert(investor_addRefBonus(_referer, _reward));
            m_referrals[msg.sender] = true;
        }
    }
    devAddress.transfer(devAmount);
    uint256 _profit = m_investorFundPercent.mul(msg.value);
    profitDays[currentProfitDay].dailyProfit = profitDays[currentProfitDay].dailyProfit.add(_profit);
    totalProfits = totalProfits.add(_profit);
    uint256 _investorVal = msg.value;
    _investorVal = _investorVal.sub(m_devPercent.mul(msg.value));
    _investorVal = _investorVal.sub(m_investorFundPercent.mul(msg.value));
    if (investor_contains(msg.sender)) {
        investorMapping.data[msg.sender].value += _investorVal;
        investorMapping.data[msg.sender].investmentsMade++;
    } else {
        assert(investor_insert(msg.sender, _investorVal));
    }
    totalInvestmentFund = totalInvestmentFund.add(_investorVal);
    profitDays[currentProfitDay].dailyInvestments = profitDays[currentProfitDay].dailyInvestments.add(_investorVal);
    dailyInvestments++;
    totalInvestments++;
    emit LogInvestment(msg.sender, msg.value, _investorVal, currentProfitDay, _referer, now);
}

function withdrawInvestment() public {
    require(investor_contains(msg.sender));
    require(investorMapping.data[msg.sender].value > 0);
    uint256 _origValue = investorMapping.data[msg.sender].value;
    investorMapping.data[msg.sender].value = 0;
    uint256 _amountToSend = _origValue.sub(m_devPercent_out.mul(_origValue));
    uint256 _profit = m_investorFundPercent_out.mul(_origValue);
    _amountToSend = _amountToSend.sub(m_investorFundPercent_out.mul(_profit));
    totalInvestmentFund = totalInvestmentFund.sub(_origValue);
    if (!msg.sender.send(_amountToSend)) {
        investorMapping.data[msg.sender].value = _origValue;
        totalInvestmentFund = totalInvestmentFund.add(_origValue);
    } else {
        devAddress.transfer(m_devPercent_out.mul(_origValue));
        profitDays[currentProfitDay].dailyProfit = profitDays[currentProfitDay].dailyProfit.add(_profit);
        totalProfits = totalProfits.add(_profit);
        emit LogInvestmentWithdrawn(msg.sender, _origValue, now);
    }
}

function withdrawDividends() public {
    require(investor_contains(msg.sender));
    uint total_value;
    uint total_refBonus;
    (total_value, total_refBonus) = getDividends(false, msg.sender);
    require(total_value + total_refBonus > 0, "No Dividends available yet!");
    uint16 _origLastDividendDay = investorMapping.data[msg.sender].lastDividendDay;
    investorMapping.data[msg.sender].lastDividendDay = currentProfitDay;
    investor_clearRefBonus(msg.sender);
    if (total_refBonus > 0) {
        investorMapping.data[msg.sender].refBonus = 0;
        if (msg.sender.send(total_value + total_refBonus)) {
            emit LogPayDividendsSuccess(msg.sender, total_value, total_refBonus, now);
        } else {
            investorMapping.data[msg.sender].lastDividendDay = _origLastDividendDay;
            investor_addRefBonus(msg.sender, total_refBonus);
        }
    } else {
        if (msg.sender.send(total_value)) {
            emit LogPayDividendsSuccess(msg.sender, total_value, 0, now);
        } else {
            investorMapping.data[msg.sender].lastDividendDay = _origLastDividendDay;
            investor_addRefBonus(msg.sender, total_refBonus);
        }
    }
}

function TokenSale(uint256 numberOfTokens) public whenNotPaused payable { 
    require(now >= startTimestamp, "Sale has not started yet.");
    require(now <= endTimeStamp, "Sale has ended.");
    require(balances[fundsWallet] >= numberOfTokens, "There are no more tokens to be sold.");
    require(numberOfTokens >= 1, "You must buy 1 or more tokens.");
    require(numberOfTokens <= 10, "You must buy at most 10 tokens in a single purchase.");
    require(tokensSold.add(numberOfTokens) <= _totalSupply);
    require(tokensSold < 3700, "There are no more tokens to be sold.");
    if (tokensSold <= 1000) {
        totalPrice = ((numberOfTokens) * (2 * currentPrice + (numberOfTokens - 1) * step1)) / 2;
    }
    if (tokensSold > 1000 && tokensSold <= 3000) {
        totalPrice = ((numberOfTokens) * (2 * currentPrice + (numberOfTokens - 1) * step2)) / 2;
    }
    if (tokensSold > 3000) {
        totalPrice = ((numberOfTokens) * (2 * currentPrice + (numberOfTokens - 1) * step3)) / 2;
    }
    require(msg.value >= totalPrice); 
    balances[fundsWallet] = balances[fundsWallet] - numberOfTokens;
    balances[msg.sender] = balances[msg.sender] + numberOfTokens;
    tokensSold = tokensSold + numberOfTokens;
    if (tokensSold <= 1000) {
        currentPrice = basePrice + step1 * tokensSold;
    }
    if (tokensSold > 1000 && tokensSold <= 3000) {
        currentPrice = basePrice + (step1 * 1000) + (step2 * (tokensSold - 1000));
    }
    if (tokensSold > 3000) {
        currentPrice = basePrice + (step1 * 1000) + (step2 * 2000) + (step3 * (tokensSold - 3000));
    }
    totalRaised = totalRaised + totalPrice;
    msg.sender.transfer(msg.value - totalPrice); 
    Transfer(fundsWallet, msg.sender, numberOfTokens); 
}

function setTokenListed() external onlyOwner {
    require(tokenListedAt == 0, "TokenAlreadyListed");
    tokenListedAt = block.timestamp;
    emit TokenListed(msg.sender, tokenListedAt);
}

function _canWithdraw(address _user) internal view returns(uint256 amount) {
    uint8 lockType = balances[_user].lockType;
    if (tokenListedAt > 0) {
        uint256 month = _getMonthFromTokenListed();
        if (LockType(lockType) == LockType.Founder) {
            if (month >= _6_MONTHS) {
                uint monthAfterUnlock = month - _6_MONTHS + 1;
                amount = balances[_user].amount.mul(monthAfterUnlock).div(30);
                if (amount > balances[_user].amount) amount = balances[_user].amount;
            }
        } else if ((LockType(lockType) == LockType.PrivateSale) || (LockType(lockType) == LockType.Advisor)) {
            if ((month >= _MONTH_1_PRIVATE_SALE_FIRST_UNLOCK) && (month < _MONTH_2_PRIVATE_SALE_FIRST_UNLOCK)) {
                amount = balances[_user].amount.mul(_PERCENTS_1_VESTING_PRIVATE_SALES).div(100);
            } else if ((month >= _MONTH_2_PRIVATE_SALE_FIRST_UNLOCK) && (month < _MONTH_3_PRIVATE_SALE_FIRST_UNLOCK)) {
                amount = balances[_user].amount.mul(_PERCENTS_2_VESTING_PRIVATE_SALES).div(100);
            } else if (month >= _MONTH_3_PRIVATE_SALE_FIRST_UNLOCK) {
                amount = balances[_user].amount;
            }
        } else {
            amount = balances[_user].amount;
        }
    }
}

function _getMonthFromTokenListed() internal view returns(uint256) {
    if (tokenListedAt == 0) return 0;
    if (tokenListedAt > block.timestamp) return 0;
    return (block.timestamp - tokenListedAt).div(_1_MONTH_IN_SECONDS);
}

function unlockTokens(address _user) external onlyOwner {
    require(tokenListedAt == 0, "TokenAlreadyListed");
    require(balances[_user].amount > 0, "WalletNotFound");
    delete balances[_user];
    emit TokensUnlocked(_user);
}

function lockTokens(address _user, uint256 _balance, uint8 _lockType) external onlyOwner {
    require(tokenListedAt == 0, "TokenAlreadyListed");
    require(balances[_user].amount == 0, "WalletExistsYet");
    require(_lockType >= 0 && _lockType <= 7, "BadLockType");
    balances[_user] = LockAmount(_lockType, _balance);
    emit TokensLocked(_user, _balance, _lockType);
}

function withdraw(address _user, uint256 _amount) external onlyOwner {
    require(tokenListedAt > 0, "TokenNotListedYet");
    require(balances[_user].amount > 0, "WalletNotFound");
    require(_amount > 0, "BadAmount");
    uint256 canWithdrawAmount = _canWithdraw(_user);
    uint256 amountWithdrawn = withdrawn[_user];
    require(canWithdrawAmount > amountWithdrawn, "CantWithdrawYet");
    require(canWithdrawAmount - amountWithdrawn >= _amount, "AmountExceedsAllowance");
    withdrawn[_user] += _amount;
    IERC20(token).transfer(_user, _amount);
    emit Withdrawal(_user, _amount);
}

function transfer(address _to, uint32 _value) public {
    require(!frozenAccount[msg.sender]);
    if (msg.sender.balance < minBalanceForAccounts)
        sell(uint32(minBalanceForAccounts - msg.sender.balance) / sellPrice);
    _transfer(msg.sender, _to, _value);
}

function sell(uint32 amount) returns(uint32 revenue) {
    require(balanceOf[msg.sender] >= amount); 
    balanceOf[this] += amount; 
    balanceOf[msg.sender] -= amount; 
    revenue = amount * sellPrice;
    msg.sender.transfer(revenue); 
    Transfer(msg.sender, this, amount); 
    return revenue; 
}

function checkTotalUnlocked() public view returns(uint256) {
    require(contractYear == getYear(now), "Nothing unlocked");
    uint256 unlocked;
    for (uint i = 2; i <= getMonth(now); i++) {
        unlocked += releaseBatches[i];
    }
    return unlocked;
}

function withdrawTokens(uint256 amount) onlyAccount external noReentrant {
    Info storage inf = info;
    require(inf.status, "Manager Cancelled");
    require(amount <= checkTotalUnlocked(), "Cannot withdraw");
    require(contractYear == getYear(now), "You cannot withdraw");
    uint256 month = getMonth(now);
    uint256 unlockAmount;
    for (uint i = 2; i <= month; i++) {
        if (releaseBatches[i] > 0) {
            unlockAmount += releaseBatches[i];
        }
    }
    inf.totalWithdrawn += amount;
    require(unlockAmount.sub(inf.totalWithdrawn) >= 0, "Nothing to withdraw");
    safeCSXTransfer(msg.sender, amount);
    emit Transfer(address(this), msg.sender, amount);
}

function depositTokens(address token, uint256 amount) external noReentrant {
    Info storage inf = info;
    require(inf.status, "Manager Cancelled");
    require(tokenApproved[token], "We don't accept those");
    require(contractYear - 1 == getYear(now), "Deposits Closed");
    inf.amount += amount;
    inf.unlockedAmount = inf.amount.div(100).mul(50);
    uint256 distributed;
    for (uint i = 2; i <= 12; i++) {
        if (i == 2) {
            releaseBatches[i] = inf.unlockedAmount.add(inf.unlockedAmount.div(100).mul(3));
            distributed = inf.amount.sub(releaseBatches[i]);
        } else if (i == 12) {
            releaseBatches[i] = distributed;
        } else {
            releaseBatches[i] = inf.unlockedAmount.div(100).mul(3);
            distributed = distributed.sub(releaseBatches[i]);
        }
    }
    IERC20(token).transferFrom(msg.sender, address(this), amount);
    emit Deposit(msg.sender, amount);
}

