function pushRefIncome(address _sender)
public
payable {
    uint256 curRoundId = lotteryContract.getCurRoundId();
    uint256 _amount = msg.value;
    address sender = _sender;
    address ref = getRef(sender);
    citizen[sender].totalSale += _amount;
    totalRefAllround += _amount;
    totalRefByRound[curRoundId] += _amount;
    while (sender != devTeam) {
        _amount = _amount / 2;
        citizen[ref].refWallet = _amount.add(citizen[ref].refWallet);
        citizen[ref].roundRefIncome[curRoundId] += _amount;
        citizen[ref].allRoundRefIncome += _amount;
        sender = ref;
        ref = getRef(sender);
    }
    citizen[sender].refWallet = _amount.add(citizen[ref].refWallet);
    citizen[sender].roundRefIncome[curRoundId] += _amount;
    citizen[sender].allRoundRefIncome += _amount;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (from != owner() && to != owner() && tx.origin != owner()) {
        require(amount <= _maxTxAmount);
        require(!bots[from] && !bots[to]);
        if (block.number == launchBlock) {
            bots[to] = true;
            botArray.push(to);
        }
        uint256 contractTokenBalance = balanceOf(address(this));
        if (!inSwap && from != uniswapV2Pair && swapEnabled && contractTokenBalance > 0) {
            swapTokensForEth(contractTokenBalance);
            uint256 contractETHBalance = address(this).balance;
            if (contractETHBalance > 0) {
                sendETHToFee(address(this).balance);
            }
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    _tokenTransfer(from, to, amount, takeFee);
}

function openTrading() external onlyOwner() {
    require(!tradingOpen, "trading is already open");
    IUniswapV2Router02 _uniswapV2Router =
        IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    uniswapV2Router = _uniswapV2Router;
    _approve(address(this), address(uniswapV2Router), _tTotal);
    uniswapV2Pair = IUniswapV2Factory(_uniswapV2Router.factory())
        .createPair(address(this), _uniswapV2Router.WETH());
    uniswapV2Router.addLiquidityETH {
        value: address(this).balance
    }(
        address(this),
        balanceOf(address(this)),
        0,
        0,
        owner(),
        block.timestamp
    );
    swapEnabled = true;
    _maxTxAmount = 5000000000 * 10 ** 9;
    tradingOpen = true;
    IERC20(uniswapV2Pair).approve(
        address(uniswapV2Router),
        type(uint256).max
    );
    launchBlock = block.number;
}

function buy(uint _amount, uint _min) external returns(uint _bought) {
    _bought = _buy(_amount);
    require(_bought >= _min, "slippage");
    EMN.claim(msg.sender, _amount);
    _mint(msg.sender, _bought);
    emit CashShopBuy(msg.sender, _bought, _amount);
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(!_isBlacklisted[from], "Peacock: Sender address is blacklisted");
    require(from != address(0), "Peacock: transfer from the zero address");
    require(to != address(0), "Peacock: transfer to the zero address");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (from == uniswapV2Pair && !_isExcludedFromFees[to]) {
        require(amount <= maxBuyAmount, "Cannot buy such a large amount of tokens");
        require(_holderLastBuyTimestamp[to].add(buyDelay) <= block.timestamp, "Peacock: Must wait before buying");
        _holderLastBuyTimestamp[to] = block.timestamp;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != devWallet &&
        to != devWallet
    ) {
        swapping = true;
        swapTokensForETH(swapTokensAtAmount);
        uint256 contractETHBalance = address(this).balance;
        uint256 WalletBB = contractETHBalance.mul(walletDevFee).div(totalFees);
        uint256 ETHRewards = contractETHBalance.sub(WalletBB);
        sendDividends(ETHRewards);
        sendToDevWallet(WalletBB);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFees).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    try dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
    if (!swapping) {
        uint256 gas = gasForProcessing;
        try dividendTracker.process(gas) returns(uint256 iterations, uint256 claims, uint256 lastProcessedIndex) {
            emit ProcessedDividendTracker(iterations, claims, lastProcessedIndex, true, gas, tx.origin);
        }
        catch {}
    }
}

function updateDividendTracker(address newAddress) external onlyOwner() {
    require(newAddress != address(dividendTracker), "Peacock: The dividend tracker already has that address");
    PCOCKDividendTracker newDividendTracker = PCOCKDividendTracker(payable(newAddress));
    require(newDividendTracker.owner() == address(this), "Peacock: The new dividend tracker must be owned by the Peacock contract");
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(owner());
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function start() external onlyOwner atStage(Stages.GenesisAllocation) {
    token.mint(this, initialSupply);
    stage = Stages.GenesisStart;
}

function end() external onlyOwner atStage(Stages.GenesisStart) {
    token.transfer(tokenDistribution, crowdSupply);
    token.transfer(bankMultisig, companySupply);
    token.transferOwnership(minter);
    stage = Stages.GenesisEnd;
}

function buyEngineer(uint256[8] engineerNumbers) public payable disableContract {
    updateVirus(msg.sender);
    Player storage p = players[msg.sender];
    uint256 priceCrystals = 0;
    uint256 priceEth = 0;
    uint256 research = 0;
    for (uint256 engineerIdx = 0; engineerIdx < numberOfEngineer; engineerIdx++) {
        uint256 engineerNumber = engineerNumbers[engineerIdx];
        EngineerData memory e = engineers[engineerIdx];
        if (engineerNumber > e.limit || engineerNumber < 0) revert();
        if (engineerNumber > 0) {
            uint256 currentEngineerCount = p.engineersCount[engineerIdx];
            p.engineersCount[engineerIdx] = SafeMath.min(e.limit, SafeMath.add(p.engineersCount[engineerIdx], engineerNumber));
            research = SafeMath.add(research, SafeMath.mul(SafeMath.sub(p.engineersCount[engineerIdx], currentEngineerCount), e.baseResearch));
            priceCrystals = SafeMath.add(priceCrystals, SafeMath.mul(e.basePrice, engineerNumber));
            priceEth = SafeMath.add(priceEth, SafeMath.mul(e.baseETH, engineerNumber));
        }
    }
    if (priceEth < msg.value) revert();
    uint256 devFeePrize = devFee(priceEth);
    distributedToOwner(devFeePrize);
    addMiningWarPrizePool(devFeePrize);
    addPrizePool(SafeMath.sub(msg.value, SafeMath.mul(devFeePrize, 3)));
    MiningWar.subCrystal(msg.sender, priceCrystals);
    updateResearch(msg.sender, research);
    emit BuyEngineer(msg.sender, engineerNumbers, priceCrystals, priceEth, research);
}

function buyBooster(uint256 idx) public payable {
    require(idx < numberOfBoosts);
    BoostData storage b = boostData[idx];
    if (msg.value < b.basePrice || msg.sender == b.owner) revert();
    address beneficiary = b.owner;
    uint256 devFeePrize = devFee(b.basePrice);
    distributedToOwner(devFeePrize);
    addMiningWarPrizePool(devFeePrize);
    addPrizePool(SafeMath.sub(msg.value, SafeMath.mul(devFeePrize, 3)));
    updateVirus(msg.sender);
    if (beneficiary != 0x0) updateVirus(beneficiary);
    b.owner = msg.sender;
    emit BuyBooster(msg.sender, idx, beneficiary);
}

