    require(newOwner != owner);
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(cards[_cardId].isSale == true);
    require(msg.value >= sellingPrice);
    uint payment = _calculatePaymentToOwner(sellingPrice);
    uint excessPayment = msg.value.sub(sellingPrice);
    _transfer(oldOwner, newOwner, _cardId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment);
    }
    newOwner.transfer(excessPayment);
    CardSold(_cardId, sellingPrice, oldOwner, newOwner);
}

function buy(uint _card, address _referrer)
public
payable
{
    require(_card < totalCards);
    require(msg.value == cardPrice[_card]);
    require(msg.sender != cardOwner[_card]);
    addtotalCardValue(msg.value, cardPreviousPrice[_card]);
    uint _newPrice = SafeMath.div(SafeMath.mul(msg.value, cardPriceIncrement), 100);
    uint _baseDividends = SafeMath.sub(msg.value, cardPreviousPrice[_card]);
    totalDivsProduced = SafeMath.add(totalDivsProduced, _baseDividends);
    uint _mobDividends = SafeMath.div(SafeMath.mul(_baseDividends, mobDivRate), 100);
    uint _ownerDividends = SafeMath.div(SafeMath.mul(_baseDividends, ownerDivRate), 100);
    totalCardDivs[_card] = SafeMath.add(totalCardDivs[_card], _ownerDividends);
    _ownerDividends = SafeMath.add(_ownerDividends, cardPreviousPrice[_card]);
    uint _distDividends = SafeMath.div(SafeMath.mul(_baseDividends, distDivRate), 100);
    if (allowReferral && (_referrer != msg.sender) && (_referrer != 0x0000000000000000000000000000000000000000)) {
        uint _referralDividends = SafeMath.div(SafeMath.mul(_baseDividends, referralRate), 100);
        _distDividends = SafeMath.sub(_distDividends, _referralDividends);
        ownerAccounts[_referrer] = SafeMath.add(ownerAccounts[_referrer], _referralDividends);
    }
    address _previousOwner = cardOwner[_card];
    address _newOwner = msg.sender;
    ownerAccounts[_previousOwner] = SafeMath.add(ownerAccounts[_previousOwner], _ownerDividends);
    mobDivsAddr.transfer(_mobDividends);
    distributeDivs(_distDividends);
    cardPreviousPrice[_card] = msg.value;
    cardPrice[_card] = _newPrice;
    cardOwner[_card] = _newOwner;
    emit oncardPurchase(msg.sender, msg.value, _card, SafeMath.div(SafeMath.mul(msg.value, cardPriceIncrement), 100));
}

function distribute(IERC20Min token) external {
    require(_notEntered, "reentrant call");
    _notEntered = false;
    _revertZeroAddress(address(token));
    require(stakesSum != 0, "no stakes to distribute between");
    uint256 balance = token.balanceOf(address(this));
    uint256 scaledShare = _mul(balance, 1e4) / stakesSum;
    require(scaledShare != 0, "nothing to distribute");
    for (uint256 i = 1; i <= numOfStakes; i++) {
        StakeHolder memory holder = stakeholders[i];
        uint256 amount = _mul(scaledShare, holder.stake) / 1e4;
        _safeTransfer(token, holder.wallet, amount);
        emit Distributed(i, address(token), amount);
    }
    _notEntered = true;
}

function unlock() public returns(bool) {
    address tokenHolder = msg.sender;
    require(_lockupBalances[tokenHolder] > 0);
    require(_lockupExpireTime[tokenHolder] <= now);
    uint256 value = _lockupBalances[tokenHolder];
    _balances[tokenHolder] = _balances[tokenHolder].add(value);
    _lockupBalances[tokenHolder] = 0;
    return true;
}

function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 10;
    uint256 bonusCond2 = 1 ether / 2;
    uint256 bonusCond3 = 1 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 25 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 50 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 15 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 35 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 1000e2;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
}

function buy(uint256 _team, bytes32 _affCode)
public
payable
isActivated()
isHuman()
isWithinLimits(msg.value) {
    require(round_[rID_].state < 3, "This round has ended.");
    if (round_[rID_].state == 0) {
        require(now >= round_[rID_].start, "This round hasn't started yet.");
        round_[rID_].state = 1;
    }
    determinePID(msg.sender);
    uint256 _pID = pIDxAddr_[msg.sender];
    uint256 _tID;
    uint256 _affID;
    if (_affCode == "" || _affCode == plyr_[_pID].name) {
        _affID = plyr_[_pID].laff;
    } else {
        _affID = pIDxName_[_affCode];
        if (_affID != plyr_[_pID].laff) {
            plyr_[_pID].laff = _affID;
        }
    }
    if (round_[rID_].state == 1) {
        _tID = determinTID(_team, _pID);
        buyCore(_pID, _affID, _tID, msg.value);
        if (round_[rID_].tID_ >= 16) {
            round_[rID_].state = 2;
            startKilling();
        }
    } else if (round_[rID_].state == 2) {
        if (round_[rID_].liveTeams == 1) {
            endRound();
            refund(_pID, msg.value);
            return;
        }
        _tID = determinTID(_team, _pID);
        buyCore(_pID, _affID, _tID, msg.value);
        if (now > round_[rID_].lastKillingTime.add(killingGap_)) {
            kill();
        }
    }
}

