    uint256 total = 0;
    for (uint i = 0; i < locks[_addr].length; i++) {
        if (locks[_addr][i].TIME > now && locks[_addr][i].ADDRESS == _addr) {
            total = total.add(locks[_addr][i].AMOUNT);
        }
    }
    if (value > balanceOf(_addr).sub(total)) {
        return false;
    }
    return true;
}

