function refundBid(Bid bid) private {
    bid.bidder.send(bid.amount);
    emit Refund(now, bid.bidder, bid.amount);
}

function placeBid(string url) public payable {
    require(msg.value >= ((highestBid.amount * 11) / 10));
    Bid memory newBid = Bid(now, msg.sender, msg.value, url);
    if (highestBid.bidder != 0) {
        refundBid(highestBid);
    }
    highestBid = newBid;
    emit BidLog(newBid.timestamp, newBid.bidder, newBid.amount, newBid.url);
}

function pickWinner() public payable {
    require(msg.sender == owner);
    if (winningBid.bidTimestamp != highestBid.timestamp) {
        WinningBid memory newWinningBid = WinningBid(now, highestBid.timestamp, highestBid.bidder, highestBid.amount, highestBid.url);
        winningBid = newWinningBid;
        emit WinningBidLog(
            newWinningBid.winTimestamp,
            newWinningBid.bidTimestamp,
            newWinningBid.bidder,
            newWinningBid.bidAmount,
            newWinningBid.url
        );
    }
}

function execute(bytes32 _proposalId, address _avatar, int _param) public returns(bool) {
    require(parameters[getParametersFromController(Avatar(_avatar))].intVote == msg.sender);
    UpgradeProposal memory proposal = organizationsProposals[_avatar][_proposalId];
    require(proposal.proposalType != 0);
    delete organizationsProposals[_avatar][_proposalId];
    emit ProposalDeleted(_avatar, _proposalId);
    if (_param == 1) {
        ControllerInterface controller = ControllerInterface(Avatar(_avatar).owner());
        if (proposal.proposalType == 1) {
            require(controller.upgradeController(proposal.upgradeContract, _avatar));
        }
        if (proposal.proposalType == 2) {
            bytes4 permissions = controller.getSchemePermissions(this, _avatar);
            require(controller.registerScheme(proposal.upgradeContract, proposal.params, permissions, _avatar));
            if (proposal.upgradeContract != address(this)) {
                require(controller.unregisterSelf(_avatar));
            }
        }
    }
    emit ProposalExecuted(_avatar, _proposalId, _param);
    return true;
}

function proposeUpgrade(Avatar _avatar, address _newController)
public
returns(bytes32) {
    Parameters memory params = parameters[getParametersFromController(_avatar)];
    bytes32 proposalId = params.intVote.propose(2, params.voteParams, _avatar, ExecutableInterface(this), msg.sender);
    UpgradeProposal memory proposal = UpgradeProposal({
        proposalType: 1,
        upgradeContract: _newController,
        params: bytes32(0)
    });
    organizationsProposals[_avatar][proposalId] = proposal;
    emit NewUpgradeProposal(_avatar, proposalId, params.intVote, _newController);
    params.intVote.ownerVote(proposalId, 1, msg.sender); 
    return proposalId;
}

function proposeChangeUpgradingScheme(
    Avatar _avatar,
    address _scheme,
    bytes32 _params
)
public
returns(bytes32) {
    Parameters memory params = parameters[getParametersFromController(_avatar)];
    IntVoteInterface intVote = params.intVote;
    bytes32 proposalId = intVote.propose(2, params.voteParams, _avatar, ExecutableInterface(this), msg.sender);
    require(organizationsProposals[_avatar][proposalId].proposalType == 0);
    UpgradeProposal memory proposal = UpgradeProposal({
        proposalType: 2,
        upgradeContract: _scheme,
        params: _params
    });
    organizationsProposals[_avatar][proposalId] = proposal;
    emit ChangeUpgradeSchemeProposal(
        _avatar,
        proposalId,
        params.intVote,
        _scheme,
        _params
    );
    intVote.ownerVote(proposalId, 1, msg.sender); 
    return proposalId;
}

function updateMatchStartTime(uint8 _matchId, uint _startTime)
external onlyCLevel validMatch(_matchId) whenNotPaused {
    Match storage _match = matchs[_matchId];
    require(_match.outcome == INIT);
    require(now < _startTime);
    _match.startTime = _startTime;
    emit UpdateMatchStartTime(msg.sender, _matchId, _startTime);
}

function betMatch(uint8 _matchId, uint8 _prediction)
external payable validValue validMatch(_matchId) validPredictionOrOutcome(_prediction) whenNotPaused {
    Match storage _match = matchs[_matchId];
    require(_match.outcome == INIT);
    require(now < _match.startTime);
    {
        Better storage better = _match.betters[msg.sender];
        if (better.invested > 0) {
            better.invested = better.invested.add(msg.value);
        } else {
            _match.betters[msg.sender] = Better(msg.value, 0);
        }
        _match.betters[msg.sender].bPredictionInvest[_prediction] = _match.betters[msg.sender].bPredictionInvest[_prediction].add(msg.value);
    }
    {
        _match.mPredictionInvest[_prediction] = _match.mPredictionInvest[_prediction].add(msg.value);
        _match.totalInvest = _match.totalInvest.add(msg.value);
    }
    {
        totalInvest = totalInvest.add(msg.value);
    }
    {
        AccountInfo storage accountInfo = accountInfos[msg.sender];
        if (accountInfo.invested > 0) {
            accountInfo.invested = accountInfo.invested.add(msg.value);
        } else {
            accountInfos[msg.sender] = AccountInfo({
                invested: msg.value,
                prize: 0,
                claimed: 0
            });
        }
    }
    {
        uint8 index = getMatchIndex(_matchId);
        address[] memory match_betters = nm_players[index];
        bool ext = false;
        for (uint i = 0; i < match_betters.length; i++) {
            if (match_betters[i] == msg.sender) {
                ext = true;
                break;
            }
        }
        if (ext == false) {
            nm_players[index].push(msg.sender);
        }
    }
    emit BetMatch(msg.sender, msg.value, _matchId, _prediction);
}

function updateMatch(uint8 _matchId, uint8 _hostTeamId, uint8 _guestTeamId)
external onlyCLevel validMatch(_matchId) validTeam(_hostTeamId) validTeam(_guestTeamId) whenNotPaused {
    Match storage _match = matchs[_matchId];
    require(_match.outcome == INIT);
    require(now < _match.startTime);
    _match.hostTeamId = _hostTeamId;
    _match.guestTeamId = _guestTeamId;
    emit UpdateMatch(msg.sender, _matchId, _hostTeamId, _guestTeamId);
}

function withdrawPayments() public whenNotPaused {
    address payee = msg.sender;
    uint256 payment = payments[payee];
    require(payment != 0);
    require(address(this).balance >= payment);
    totalPayments = totalPayments.sub(payment);
    payments[payee] = 0;
    payee.transfer(payment);
    emit WithdrawPayments(payee, payment);
}

