function createRequest(uint _requestType, uint _changeTo, string memory _reason) public override {
    require(_requestType == 0 || _requestType == 1 || _requestType == 2, "Invalid request type!");
    require(!activeRequest[_requestType], "Another request is still active");
    require(ELLA.allowance(msg.sender, address(this)) >= requestCreationPower, "Insufficient ELLA allowance for vote!");
    ELLA.transferFrom(msg.sender, address(this), requestCreationPower);
    Requests memory _request = Requests({
        creator: msg.sender,
        requestType: _requestType,
        changeTo: _changeTo,
        reason: _reason,
        positiveVote: 0,
        negativeVote: 0,
        powerUsed: requestCreationPower,
        stale: false,
        votingPeriod: block.timestamp.add(4 days)
    });
    requests.push(_request);
    uint256 newRequestID = requests.length - 1;
    Requests memory request = requests[newRequestID];
    emit RequestCreated(
        request.creator,
        request.requestType,
        request.changeTo,
        request.reason,
        request.positiveVote,
        request.negativeVote,
        request.powerUsed,
        request.stale,
        request.votingPeriod,
        newRequestID
    );
}

function sell(uint _amount) internal returns(uint revenue) {
    require(_amount > 0);
    require(balances[msg.sender] >= _amount);
    uint oldBalance = balances[this].add(balances[msg.sender]);
    balances[this] = balances[this].add(_amount);
    balances[msg.sender] = balances[msg.sender].sub(_amount);
    revenue = _amount.mul(sellPriceInWei).div(1 ether);
    require(revenue > 0);
    if (!msg.sender.send(revenue)) {
        revert();
    } else {
        uint newBalance = balances[this].add(balances[msg.sender]);
        assert(newBalance == oldBalance);
        Transfer(msg.sender, this, _amount);
        return _amount;
    }
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(!frozenAccounts[msg.sender]);
    require(!frozenAccounts[_to]);
    require(_value <= balances[msg.sender]);
    if (msg.sender.balance < minBalanceForAccounts) {
        sell((minBalanceForAccounts.sub(msg.sender.balance)).div(sellPriceInWei));
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function buyTokens() public payable {
    require(isOpen(), "Sale is not open");
    uint etherRate = rateSource.etherRate();
    require(etherRate > 0, "Ether rate is zero");
    uint amount = msg.value.mul(etherRate).div(tokenPrice);
    require(amount <= tokenRemainingForPublicSale, "Not enough tokens available");
    require(amount >= tokenPurchaseMinimum, "Investment is too low");
    if (now < limitEndTime) {
        uint purchased = tokenPurchased[msg.sender].add(amount);
        require(purchased <= tokenPurchaseLimit, "Purchase limit reached");
        tokenPurchased[msg.sender] = purchased;
    }
    tokenRemainingForPublicSale = tokenRemainingForPublicSale.sub(amount);
    token.mint(msg.sender, amount);
    forwardFunds();
    emit TokenPurchase(msg.sender, msg.value, amount);
}

function refundInvestor(address payable _investor) internal {
    require(isFinalized, "Sale has not been finalized");
    require(!goalReached(), "Goal was reached");
    uint investment = investments[_investor];
    if (investment > 0) {
        investments[_investor] = 0;
        _investor.transfer(investment);
        emit InvestorRefund(_investor, investment);
    }
}

function _withdrawProfitShare(address _investor, address payable _beneficiary) internal {
    updateProfitShare(_investor);
    uint withdrawnProfitShare = accounts[_investor].profitShare;
    accounts[_investor].profitShare = 0;
    _beneficiary.transfer(withdrawnProfitShare);
    emit ProfitShareWithdrawal(_investor, _beneficiary, withdrawnProfitShare);
}

function finalize() public onlyOwner {
    require(!isFinalized, "Sale has already been finalized");
    require(hasClosed(), "Sale has not closed");
    if (tokenReservePerMill > 0) {
        token.mint(reserveAccount, tokenSold().mul(tokenReservePerMill).div(1000));
    }
    token.finishMinting();
    isFinalized = true;
    emit Finalization();
}

function distributeTokensViaPublicSale(
    address[] memory beneficiaries,
    uint[] memory amounts
)
public {
    super.distributeTokensViaPublicSale(beneficiaries, amounts);
    forwardFunds();
}

function distributeTokensViaPrivateSale(
    address[] memory beneficiaries,
    uint[] memory amounts
)
public {
    super.distributeTokensViaPrivateSale(beneficiaries, amounts);
    forwardFunds();
}

function changeClosingTime(uint _newClosingTime) public onlyOwner {
    require(!hasClosed(), "Sale has already ended");
    require(_newClosingTime > now, "ClosingTime not in the future");
    require(_newClosingTime > openingTime, "New offering is zero");
    require(_newClosingTime - openingTime <= MAXOFFERINGPERIOD, "New offering too long");
    emit ClosingTimeChange(closingTime, _newClosingTime);
    closingTime = _newClosingTime;
}

function hasClosed() public view returns(bool) {
    return now >= closingTime || tokenRemainingForPublicSale == 0;
}

constructor(
    RateSource _rateSource,
    MintableToken _token,
    uint _tokenCapOfPublicSale,
    uint _tokenCapOfPrivateSale,
    uint _tokenPurchaseMinimum,
    uint _tokenPurchaseLimit,
    uint _tokenReservePerMill,
    uint _tokenPrice,
    uint _openingTime,
    uint _closingTime,
    uint _limitEndTime,
    address payable _companyWallet,
    address _reserveAccount
)
public {
    require(address(_rateSource) != address(0x0), "Rate source is zero");
    require(address(_token) != address(0x0), "Token address is zero");
    require(_token.minter() == address(0x0), "Token has another minter");
    require(_tokenCapOfPublicSale > 0, "Cap of public sale is zero");
    require(_tokenCapOfPrivateSale > 0, "Cap of private sale is zero");
    require(_tokenPurchaseMinimum <= _tokenCapOfPublicSale &&
        _tokenPurchaseMinimum <= _tokenCapOfPrivateSale,
        "Purchase minimum exceeds cap");
    require(_tokenPrice > 0, "Token price is zero");
    require(_openingTime >= now, "Opening lies in the past");
    require(_closingTime >= _openingTime, "Closing lies before opening");
    require(_companyWallet != address(0x0), "Company wallet is zero");
    require(_reserveAccount != address(0x0), "Reserve account is zero");
    if (_limitEndTime > _openingTime) {
        require(_tokenPurchaseLimit >= _tokenPurchaseMinimum,
            "Purchase limit is below minimum");
    }
    _tokenCapOfPublicSale.add(_tokenCapOfPrivateSale).mul(_tokenReservePerMill);
    rateSource = _rateSource;
    token = _token;
    tokenCapOfPublicSale = _tokenCapOfPublicSale;
    tokenCapOfPrivateSale = _tokenCapOfPrivateSale;
    tokenPurchaseMinimum = _tokenPurchaseMinimum;
    tokenPurchaseLimit = _tokenPurchaseLimit;
    tokenReservePerMill = _tokenReservePerMill;
    tokenPrice = _tokenPrice;
    openingTime = _openingTime;
    closingTime = _closingTime;
    limitEndTime = _limitEndTime;
    companyWallet = _companyWallet;
    reserveAccount = _reserveAccount;
    tokenRemainingForPublicSale = _tokenCapOfPublicSale;
    tokenRemainingForPrivateSale = _tokenCapOfPrivateSale;
}

function isOpen() public view returns(bool) {
    return now >= openingTime && !hasClosed();
}

function changeOpeningTime(uint _newOpeningTime) public onlyOwner {
    require(now < openingTime, "Sale has started already");
    require(now < _newOpeningTime, "OpeningTime not in the future");
    uint _newClosingTime = _newOpeningTime + (closingTime - openingTime);
    emit OpeningTimeChange(openingTime, _newOpeningTime);
    emit ClosingTimeChange(closingTime, _newClosingTime);
    openingTime = _newOpeningTime;
    closingTime = _newClosingTime;
}

function()
public
isValidPayload
isExists
atStage(Stages.Started)
payable {
    uint amount = msg.value;
    uint maxAmount = totalAmount.div(priceFactor);
    if (amount > maxAmount) {
        uint refund = amount.sub(maxAmount);
        assert(msg.sender.send(refund));
        amount = maxAmount;
    }
    if (maxGasPrice != 0) {
        assert(tx.gasprice < maxGasPrice + 1);
    }
    totalReceived = totalReceived.add(amount);
    uint token = amount.mul(priceFactor);
    totalAmount = totalAmount.sub(token);
    yeedToken.transferFrom(tokenOwner, msg.sender, token);
    FundTransfer(msg.sender, token);
    ContributeAddress crowdData = _contributeInfo[msg.sender];
    crowdData.exists = true;
    crowdData.account = msg.sender;
    crowdData.data = msg.data;
    crowdData.amount = amount;
    crowdData.balance = token;
    _contruibuteData[msg.data] = crowdData;
    _contributeInfo[msg.sender] = crowdData;
    wallet.transfer(amount);
    if (amount == maxAmount)
        finalizeContruibute();
}

receive() external payable {
    require(whitelistIsSet = true);
    if (startTime == uint256(0)) {
        startTime = block.timestamp;
    }
    if ((block.timestamp.sub(startTime) <= 1 hours) && (totalSupply().sub(TOKENS_PREMINED) < TOKENS_FOR_SALE)) {
        stageOneBuy();
    } else if ((block.timestamp.sub(startTime) > 1 hours && block.timestamp.sub(startTime) <= 2 * (1 hours)) && (totalSupply().sub(TOKENS_PREMINED) < TOKENS_FOR_SALE)) {
        stageTwoBuy();
    } else {
        revert();
    }
}

function spend(address destination, uint256 value, uint8[] vs, bytes32[] rs, bytes32[] ss) public {
    require(address(this).balance >= value);
    require(_validSignature(0x0000000000000000000000000000000000000000, destination, value, vs, rs, ss));
    spendNonce = spendNonce + 1;
    destination.transfer(value);
    emit Spent(destination, value);
}

function returnAllTokens() public {
    require(token != address(0));
    require(msg.sender == owner);
    require(ableToClaim);
    for (uint id = 0; id < allUsers.length; id++) {
        address getAddressUser = allUsers[id];
        uint256 value = users[getAddressUser].accountBalance;
        users[getAddressUser].accountBalance = users[getAddressUser].accountBalance.sub(value);
        if (value != 0) {
            ERC20(token).transfer(getAddressUser, (value * multi) / diver);
        }
    }
}

function contribute() external payable {
    require(sellSystem);
    require(msg.value >= 0.01 ether);
    uint256 amount = msg.value;
    if (now.sub(startDate) <= 1 days) {
        amount = amount.mul(200);
    } else if (now.sub(startDate) > 1 days && now.sub(startDate) <= 2 days) {
        amount = amount.mul(190);
    } else if (now.sub(startDate) > 2 days && now.sub(startDate) <= 3 days) {
        amount = amount.mul(180);
    } else if (now.sub(startDate) > 3 days && now.sub(startDate) <= 4 days) {
        amount = amount.mul(170);
    } else if (now.sub(startDate) > 4 days && now.sub(startDate) <= 5 days) {
        amount = amount.mul(160);
    } else if (now.sub(startDate) > 5 days && now.sub(startDate) <= 6 days) {
        amount = amount.mul(150);
    } else if (now.sub(startDate) > 6 days && now.sub(startDate) <= 7 days) {
        amount = amount.mul(140);
    } else if (now.sub(startDate) > 7 days && now.sub(startDate) <= 8 days) {
        amount = amount.mul(130);
    } else if (now.sub(startDate) > 8 days && now.sub(startDate) <= 9 days) {
        amount = amount.mul(120);
    } else if (now.sub(startDate) > 9 days && now.sub(startDate) <= 10 days) {
        amount = amount.mul(110);
    } else {
        amount = amount.mul(100);
    }
    amount = amount.div(100);
    totalSold = totalSold.add(amount);
    users[msg.sender].accountBalance = users[msg.sender].accountBalance.add(amount);
    allUsers.push(msg.sender);
    owner.transfer(msg.value);
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != 0x0);
    require(isCrowdsalePaused == false);
    require(validPurchase());
    require(TOKENS_SOLD < maxTokensToSale);
    uint256 weiAmount = msg.value.div(10 ** 16);
    uint256 tokens = calculateTokens(weiAmount);
    require(TOKENS_SOLD.add(tokens) <= maxTokensToSale);
    weiRaised = weiRaised.add(msg.value);
    token.transfer(beneficiary, tokens);
    emit TokenPurchase(owner, beneficiary, msg.value, tokens);
    TOKENS_SOLD = TOKENS_SOLD.add(tokens);
    distributeFunds();
}

function calculateTokens(uint value) internal view returns(uint256 tokens) {
    uint256 timeElapsed = now - startTime;
    uint256 timeElapsedInDays = timeElapsed.div(1 days);
    uint256 bonus = 0;
    if (timeElapsedInDays < 15) {
        tokens = value.mul(ratePerWei);
        bonus = tokens.mul(bonusInPhase1);
        bonus = bonus.div(100);
        tokens = tokens.add(bonus);
        require(TOKENS_SOLD.add(tokens) <= maxTokensToSale);
    }
    else if (timeElapsedInDays >= 15 && timeElapsedInDays < 30) {
        tokens = value.mul(ratePerWei);
        bonus = tokens.mul(bonusInPhase2);
        bonus = bonus.div(100);
        tokens = tokens.add(bonus);
        require(TOKENS_SOLD.add(tokens) <= maxTokensToSale);
    }
    else if (timeElapsedInDays >= 30 && timeElapsedInDays < 45) {
        tokens = value.mul(ratePerWei);
        bonus = tokens.mul(bonusInPhase3);
        bonus = bonus.div(100);
        tokens = tokens.add(bonus);
        require(TOKENS_SOLD.add(tokens) <= maxTokensToSale);
    } else {
        bonus = 0;
    }
}

