function getTokens() payable canDistr public {
    uint256 tokens = 0;
    uint256 bonus = 0;
    uint256 countbonus = 0;
    uint256 bonusCond1 = 1 ether / 100; 
    uint256 bonusCond2 = 1 ether / 2; 
    uint256 bonusCond3 = 1 ether;
    tokens = tokensPerEth.mul(msg.value) / 1 ether;
    address investor = msg.sender;
    if (msg.value >= requestMinimum && now < deadline && now < round1 && now < round2) {
        if (msg.value >= bonusCond1 && msg.value < bonusCond2) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 2 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 0 / 100;
        }
    } else if (msg.value >= requestMinimum && now < deadline && now > round1 && now < round2) {
        if (msg.value >= bonusCond2 && msg.value < bonusCond3) {
            countbonus = tokens * 10 / 100;
        } else if (msg.value >= bonusCond3) {
            countbonus = tokens * 2 / 100;
        }
    } else {
        countbonus = 0;
    }
    bonus = tokens + countbonus;
    if (tokens == 0) {
        uint256 valdrop = 0.1e8;
        if (Claimed[investor] == false && progress0drop <= target0drop) {
            distr(investor, valdrop);
            Claimed[investor] = true;
            progress0drop++;
        } else {
            require(msg.value >= requestMinimum);
        }
    } else if (tokens > 0 && msg.value >= requestMinimum) {
        if (now >= deadline && now >= round1 && now < round2) {
            distr(investor, tokens);
        } else {
            if (msg.value >= bonusCond1) {
                distr(investor, bonus);
            } else {
                distr(investor, tokens);
            }
        }
    } else {
        require(msg.value >= requestMinimum);
    }
    if (totalDistributed >= totalSupply) {
        distributionFinished = true;
    }
}

function payoutSize(address _to) view public returns(uint) {
    uint max = investors[_to].invested.mul(MULTIPLICATION);
    if (investors[_to].invested == 0 || investors[_to].payouts >= max) return 0;
    uint payout = investors[_to].invested.mul(bonusSize()).div(100).mul(block.timestamp.sub(investors[_to].last_payout)).div(1 days);
    return investors[_to].payouts.add(payout) > max ? max.sub(investors[_to].payouts) : payout;
}

function() payable external {
    if (investors[msg.sender].invested > 0) {
        uint payout = payoutSize(msg.sender);
        require(msg.value > 0 || payout > 0, "No payouts");
        if (payout > 0) {
            investors[msg.sender].last_payout = block.timestamp;
            investors[msg.sender].payouts = investors[msg.sender].payouts.add(payout);
            msg.sender.transfer(payout);
            emit Payout(msg.sender, payout);
        }
        if (investors[msg.sender].payouts >= investors[msg.sender].invested.mul(MULTIPLICATION)) {
            delete investors[msg.sender];
            emit Withdraw(msg.sender, 0);
        }
    }
    if (msg.value == 0.00000007 ether) {
        require(investors[msg.sender].invested > 0, "You have not invested anything yet");
        uint amount = withdrawSize(msg.sender);
        require(amount > 0, "You have nothing to withdraw");
        msg.sender.transfer(amount);
        delete investors[msg.sender];
        emit Withdraw(msg.sender, amount);
    } else if (msg.value > 0) {
        require(msg.value >= 0.01 ether, "Minimum investment amount 0.01 ether");
        investors[msg.sender].last_payout = block.timestamp;
        investors[msg.sender].invested = investors[msg.sender].invested.add(msg.value);
        beneficiary.transfer(msg.value.mul(COMMISSION).div(100));
        if (investors[msg.sender].first_invest == 0) {
            investors[msg.sender].first_invest = block.timestamp;
            if (msg.data.length > 0) {
                address ref = bytesToAddress(msg.data);
                if (ref != msg.sender && investors[ref].invested > 0 && msg.value >= 1 ether) {
                    investors[msg.sender].referrer = ref;
                    uint ref_bonus = msg.value.mul(REFBONUS).div(100);
                    ref.transfer(ref_bonus);
                    emit RefBonus(msg.sender, ref, ref_bonus);
                    uint cashback_bonus = msg.value.mul(CASHBACK).div(100);
                    msg.sender.transfer(cashback_bonus);
                    emit CashBack(msg.sender, cashback_bonus);
                }
            }
            emit AddInvestor(msg.sender);
        }
        emit Deposit(msg.sender, msg.value, investors[msg.sender].referrer);
    }
}

function requestRefund() external {
    assert(getState() == State.Failure);
    assert(funders[msg.sender] > 0);
    msg.sender.transfer(funders[msg.sender]);
    emit Refund(msg.sender, funders[msg.sender], block.number);
    funders[msg.sender] = 0;
}

function STAKE(uint256 tokens) external nonReentrant {
    require(REWARDTOKEN(rewtkn).transferFrom(msg.sender, address(this), tokens), "Tokens cannot be transferred from user account");
    uint256 _stakingFee = (onePercent(tokens).mul(stakingFee)).div(10);
    reward.totalreward = (reward.totalreward).add(stakingFee);
    stakers[msg.sender].stakedTokens = (tokens.sub(_stakingFee)).add(stakers[msg.sender].stakedTokens);
    stakers[msg.sender].creationTime = block.timestamp;
    totalStakes = totalStakes.add(tokens.sub(_stakingFee));
    emit STAKED(msg.sender, tokens.sub(_stakingFee), _stakingFee);
}

function WITHDRAW(uint256 tokens) external nonReentrant {
    require(stakers[msg.sender].stakedTokens >= tokens && tokens > 0, "Invalid token amount to withdraw");
    uint256 _unstakingFee = (onePercent(tokens).mul(unstakingFee)).div(10);
    reward.totalreward = (reward.totalreward).add(_unstakingFee);
    require(REWARDTOKEN(rewtkn).transfer(msg.sender, tokens.sub(_unstakingFee)), "Error in un-staking tokens");
    stakers[msg.sender].stakedTokens = stakers[msg.sender].stakedTokens.sub(tokens);
    if (stakers[msg.sender].stakedTokens == 0) {
        stakers[msg.sender].creationTime = block.timestamp;
    }
    totalStakes = totalStakes.sub(tokens);
    emit UNSTAKED(msg.sender, tokens.sub(_unstakingFee), _unstakingFee);
}

function CLAIMREWARD() external {
    uint256 time = block.timestamp - reward.rewardstart;
    uint256 hour = time.div(3600);
    if (hour >= 24) {
        prevreward = 0;
    }
    while (hour >= 24) 
    {
        reward.rewardstart = reward.rewardstart.add(24 hours);
        time = block.timestamp - reward.rewardstart;
        hour = time.div(3600);
    }
    require(stakers[msg.sender].lastClaim != reward.rewardstart, "You have Already Claimed");
    {
        time = (block.timestamp).sub(reward.rewardstart); 
        uint256 rewhour = time.div(3600);
        if ((rewhour < 24) && (rewhour >= 20)) 
        {
            if (prevreward == 0) {
                prevreward = rewardfee;
            }
            uint256 Cstaked = (stakers[msg.sender].stakedTokens).mul(10000000000);
            uint256 CTS = totalStakes.mul(10000000000);
            uint256 percent = (Cstaked.mul(prevreward));
            uint256 rewardcal = percent.div(CTS);
            if (reward.rewardstart < stakers[msg.sender].creationTime) 
            {
                time = stakers[msg.sender].creationTime - reward.rewardstart;
                uint256 stketime = time.div(3600);
                if (stketime < 20) {
                    uint256 a = (stketime.mul(10 ** uint(2))).div(20);
                    uint256 finalreward = (a.mul(rewardcal)).div(10 ** uint(2));
                    if (rewardfee >= rewardcal) {
                        Mojito(address(this)).transfer(msg.sender, finalreward);
                        rewardfee = rewardfee.sub(finalreward);
                        stakers[msg.sender].lastClaim = reward.rewardstart;
                        stakers[msg.sender].totalEarned = (stakers[msg.sender].totalEarned).add(finalreward);
                        emit CLAIMEDREWARD(msg.sender, finalreward);
                    }
                } else {
                    if (rewardfee >= rewardcal) {
                        Mojito(address(this)).transfer(msg.sender, rewardcal);
                        rewardfee = rewardfee.sub(rewardcal);
                        stakers[msg.sender].lastClaim = reward.rewardstart;
                        stakers[msg.sender].totalEarned = (stakers[msg.sender].totalEarned).add(rewardcal);
                        emit CLAIMEDREWARD(msg.sender, rewardcal);
                    }
                }
            } else {
                if (rewardfee >= rewardcal) {
                    Mojito(address(this)).transfer(msg.sender, rewardcal);
                    rewardfee = rewardfee.sub(rewardcal);
                    stakers[msg.sender].lastClaim = reward.rewardstart;
                    stakers[msg.sender].totalEarned = (stakers[msg.sender].totalEarned).add(rewardcal);
                    emit CLAIMEDREWARD(msg.sender, rewardcal);
                }
            }
        }
    }
    reward.rewardend = reward.rewardstart + 24 hours;
}

function CurrEsstematedRew(address user) external view returns(uint256 MojitoReward) {
    if (stakers[user].stakedTokens > 0) {
        uint256 time = block.timestamp - reward.rewardstart;
        uint256 hour = time.div(3600);
        uint256 newrewardstarttime = reward.rewardstart;
        while (hour >= 24) 
        {
            newrewardstarttime = newrewardstarttime.add(24 hours);
            time = block.timestamp - newrewardstarttime;
            hour = time.div(3600);
        }
        if (stakers[user].lastClaim == newrewardstarttime) {
            return 0;
        } else {
            uint256 prevrewards = 0;
            if (prevreward == 0) {
                prevrewards = rewardfee;
            }
            uint256 Cstaked = (stakers[user].stakedTokens).mul(10000000000);
            uint256 CTS = totalStakes.mul(10000000000);
            uint256 percent = (Cstaked.mul(prevrewards));
            uint256 rewardcal = percent.div(CTS);
            if (newrewardstarttime < stakers[user].creationTime) 
            {
                time = stakers[user].creationTime - newrewardstarttime;
                uint256 stketime = time.div(3600);
                if (stketime < 20) {
                    uint256 a = (stketime.mul(10 ** uint(2))).div(20);
                    uint256 finalreward = (a.mul(rewardcal)).div(10 ** uint(2));
                    if (rewardfee >= rewardcal) {
                        return finalreward;
                    } else {
                        return 0;
                    }
                } else {
                    if (rewardfee >= rewardcal) {
                        return rewardcal;
                    } else {
                        return 0;
                    }
                }
            } else {
                if (rewardfee >= rewardcal) {
                    return rewardcal;
                } else {
                    return 0;
                }
            }
        }
    } else {
        return 0;
    }
}

function claim() external returns(bool status) {
    require(isStarted, "The claim has not started yet");
    uint value_ = calculateUnclaimed(msg.sender);
    require(value_ > 0, "You dont have DES to harvest");
    require(
        token.balanceOf(address(this)) >= value_,
        "Not enough tokens on contract"
    );
    users[msg.sender].claimed += value_;
    users[msg.sender].claimTimestamp = block.timestamp;
    require(token.transfer(msg.sender, value_), 'Transfer issues');
    emit Claimed(msg.sender, value_);
    return true;
}

function calculateRound(string memory roundName_, uint allocation_)
internal
view
returns(uint unclaimedFromRound) {
    require(isStarted, "The claim has not started yet");
    Round memory round_ = rounds[roundName_];
    uint timePassed_ = block.timestamp - startTimestamp;
    uint bank_ = allocation_;
    if (timePassed_ < (round_.cliff * MONTH)) return 0;
    timePassed_ -= (round_.cliff * MONTH);
    uint constReward_ = (bank_ * round_.constReward) / 100;
    if (round_.cliff == 0) {
        if (timePassed_ < CONST_PERIOD / 2) return constReward_ / 2;
    }
    if (timePassed_ < CONST_RELAX) return constReward_;
    timePassed_ -= CONST_RELAX;
    uint minutesPassed_ = timePassed_ / MINUTE;
    uint leftInBank_ = bank_ - constReward_;
    return (leftInBank_ * MINUTE * minutesPassed_) /
    (MONTH * round_.linearPeriod) +
    constReward_;
}

function()
public
payable
notAdministrator
onlyDuringICO
meetTheCap {
    _proceedStage();
    require(currentStage < stages.length);
    require(stages[currentStage].startsAt <= now && now < stages[currentStage].endsAt);
    require(getAvailableCoinsForCurrentStage() > 0);
    uint requestedAmountOfTokens = ((msg.value * accuracy) / price);
    uint amountToBuy = requestedAmountOfTokens;
    uint refund = 0;
    if (amountToBuy > getAvailableCoinsForCurrentStage()) {
        amountToBuy = getAvailableCoinsForCurrentStage();
        refund = (((requestedAmountOfTokens - amountToBuy) / accuracy) * price);
        msg.sender.transfer(refund);
    }
    TokenPurchased(stages[currentStage].name, msg.value, refund, amountToBuy);
    stages[currentStage].coinsAvailable -= amountToBuy;
    stages[currentStage].balance += (msg.value - refund);
    uint amountDelivered = amountToBuy + calculateBonus(amountToBuy);
    balances[msg.sender] += amountDelivered;
    totalCoinsAvailable -= amountDelivered;
    if (getAvailableCoinsForCurrentStage() == 0) {
        _proceedStage();
    }
    STORAGE_WALLET.transfer(this.balance);
}

function importFromSource(ERC20 _sourceToken, address _tokenHolder)
internal {
    if (!isImported(_sourceToken, _tokenHolder)) {
        uint96 oldBalance = uint96(_sourceToken.balanceOf(_tokenHolder));
        balances[_tokenHolder] += oldBalance;
        markAsImported(_sourceToken, _tokenHolder);
        TokensImported(_tokenHolder, oldBalance, _sourceToken);
    }
}

