function burn()
public
onlyAdministrator {
    require(!stagesManager.isICO());
    uint96 burnAmount = stagesManager.getPool() +
        stagesManager.getBonusPool() +
        stagesManager.getReferralPool();
    _totalSupply -= burnAmount;
    burned = true;
    Burned(burnAmount);
}

function delegateTokens(address tokenHolder, uint96 amount)
public
isNotBurned {
    require(paymentGateways.isInList(msg.sender));
    require(stagesManager.isICO());
    require(stagesManager.getPool() >= amount);
    uint88 bonus = stagesManager.calculateBonus(amount);
    stagesManager.delegateFromPool(amount);
    balances[tokenHolder] += amount + uint96(bonus);
    TokensDelegated(tokenHolder, amount, msg.sender);
}

function switchStage()
public {
    uint8 _stage = stage;
    uint8 _offer = 0;
    while (stages.length > _stage) {
        if (stages[_stage].endsAt <= uint32(now)) {
            _stage += 1;
            _offer = 0;
            continue;
        }
        while (stages[_stage].offers.length > _offer) {
            if (stages[_stage].offers[_offer].pool == 0) {
                _offer += 1;
            } else {
                break;
            }
        }
        if (stages[_stage].offers.length <= _offer) {
            _stage += 1;
            _offer = 0;
            continue;
        }
        break;
    }
    if (stage < _stage) {
        migratePool();
    }
    StageUpdated(stage, offer, _stage, _offer);
    stage = _stage;
    offer = _offer;
}

function _proceedStage()
internal {
    while (true) {
        if (currentStage < stages.length &&
            (now >= stages[currentStage].endsAt || getAvailableCoinsForCurrentStage() == 0)) {
            currentStage++;
            uint totalTokensForSale = TOKEN_AMOUNT_PRE_ICO +
                TOKEN_AMOUNT_ICO_STAGE1_PRE_SALE1 +
                TOKEN_AMOUNT_ICO_STAGE1_PRE_SALE2 +
                TOKEN_AMOUNT_ICO_STAGE1_PRE_SALE3 +
                TOKEN_AMOUNT_ICO_STAGE1_PRE_SALE4 +
                TOKEN_AMOUNT_ICO_STAGE2;
            if (currentStage >= stages.length) {
                _totalSupply -= (((stages[(stages.length - 1)].coinsAvailable * DST_BOUNTY) / 100) +
                    ((stages[(stages.length - 1)].coinsAvailable * DST_R_N_B_PROGRAM) / 100));
                balances[BOUNTY_WALLET] = (((totalTokensForSale - stages[(stages.length - 1)].coinsAvailable) * DST_BOUNTY) / 100);
                balances[R_N_D_WALLET] = (((totalTokensForSale - stages[(stages.length - 1)].coinsAvailable) * DST_R_N_B_PROGRAM) / 100);
                totalCoinsAvailable = 0;
                break; 
            }
            stages[currentStage].numCoinsStart = totalCoinsAvailable;
            if (currentStage > 0) {
                stages[(stages.length - 1)].coinsAvailable += stages[(currentStage - 1)].coinsAvailable;
                StageUpdated(stages[currentStage - 1].name, stages[currentStage].name);
            }
        } else {
            break;
        }
    }
}

function isFreezeTimeout()
public
constant
returns(bool) {
    return now >= (stages[stages.length - 1].endsAt + 180 days);
}

function isTimeout()
public
constant
returns(bool) {
    uint8 _stage = stage;
    if (!isICO()) {
        _stage = uint8(stages.length - 1);
    }
    return now >= stages[_stage].endsAt;
}

function setStorage(address contractAddress) external onlyOwner {
    AbstractBetStorage candidateContract = AbstractBetStorage(contractAddress);
    require(candidateContract.isBetStorage());
    betStorage = candidateContract;
}

function bet(uint lineId, uint betId) external payable {
    uint amount = msg.value;
    require(amount >= minBetAmount);
    address player = msg.sender;
    betStorage.addBet(lineId, betId, player, amount);
    blockedSum = blockedSum.add(amount);
    BetMade(lineId, betId, player, amount);
}

function payPlayers(uint lineId, uint chunkSize) external onlyOwnerOr("Pay") {
    uint startId;
    uint endId;
    PaymentType paymentType;
    uint luckyPool;
    uint unluckyPool;
    (paymentType, startId, endId, luckyPool, unluckyPool) = betStorage.startPayments(lineId, chunkSize);
    for (uint i = startId; i < endId; i++) {
        address player;
        uint amount;
        (player, amount) = betStorage.getSumOfPlayerBetsById(lineId, i, paymentType);
        if (amount == 0) {
            continue;
        }
        uint payment;
        if (paymentType == PaymentType.Gain) {
            payment = amount.add(amount.mul(unluckyPool).div(luckyPool)).div(10000).mul(10000 - getFee(player));
            if (payment < amount) {
                payment = amount;
            }
        } else {
            payment = amount;
        }
        if (payment > 0) {
            player.transfer(payment);
            PlayerPaid(lineId, player, payment);
        }
    }
    if (betStorage.tryCloseLine(lineId, endId, paymentType)) {
        uint totalPool = betStorage.getLineSum(lineId);
        blockedSum = blockedSum.sub(totalPool);
        LineClosed(lineId, paymentType, totalPool);
    }
}

function addLine(uint eventId, string title, LineType lineType, uint start, string outcomes) private {
    require(start > now);
    Line memory line = Line({
        eventId: eventId,
        title: title,
        outcomes: outcomes
    });
    uint lineId = lines.push(line) - 1;
    uint resultCount;
    if (lineType == LineType.ThreeWay || lineType == LineType.DoubleChance) {
        resultCount = 3;
    } else if (lineType == LineType.TwoWay) {
        resultCount = 2;
    } else {
        resultCount = getSplitCount(outcomes);
    }
    betStorage.addLine(lineId, lineType, start, resultCount);
    NewLine(eventId, lineId, title, lineType, start, outcomes);
}

function ownerLives() internal view returns(bool) {
    return timeOfDeath_ == 0;
}

function setDiscountForPlayer(address player, uint discount, uint till) external onlyOwner {
    require(till > now && discount > 0 && discount <= 100);
    discounts[player].till = uint64(till);
    discounts[player].discount = uint8(discount);
}

function claimHeirOwnership() public onlyHeir {
    require(!ownerLives());
    require(block.timestamp >= timeOfDeath_ + heartbeatTimeout_);
    OwnershipTransferred(owner, heir_);
    HeirOwnershipClaimed(owner, heir_);
    owner = heir_;
    timeOfDeath_ = 0;
}

function getFee(address player) private view returns(uint newFee) {
    var data = discounts[player];
    if (data.till > now) {
        return fee * (100 - data.discount) / 100;
    }
    return fee;
}

function acceptRewardsBalanceMigration(address[] memory guardians, uint256[] memory fees, uint256 totalFees, uint256[] memory bootstrap, uint256 totalBootstrap) external override {
    uint256 _totalFees = 0;
    uint256 _totalBootstrap = 0;
    for (uint i = 0; i < guardians.length; i++) {
        _totalFees = _totalFees.add(fees[i]);
        _totalBootstrap = _totalBootstrap.add(bootstrap[i]);
    }
    require(totalFees == _totalFees, "totalFees does not match fees sum");
    require(totalBootstrap == _totalBootstrap, "totalBootstrap does not match bootstrap sum");
    if (totalFees > 0) {
        require(feesToken.transferFrom(msg.sender, address(this), totalFees), "acceptRewardBalanceMigration: transfer failed");
    }
    if (totalBootstrap > 0) {
        require(bootstrapToken.transferFrom(msg.sender, address(this), totalBootstrap), "acceptRewardBalanceMigration: transfer failed");
    }
    FeesAndBootstrap memory guardianFeesAndBootstrap;
    for (uint i = 0; i < guardians.length; i++) {
        guardianFeesAndBootstrap = feesAndBootstrap[guardians[i]];
        guardianFeesAndBootstrap.feeBalance = guardianFeesAndBootstrap.feeBalance.add(fees[i]);
        guardianFeesAndBootstrap.bootstrapBalance = guardianFeesAndBootstrap.bootstrapBalance.add(bootstrap[i]);
        feesAndBootstrap[guardians[i]] = guardianFeesAndBootstrap;
        emit FeesAndBootstrapRewardsBalanceMigrationAccepted(msg.sender, guardians[i], fees[i], bootstrap[i]);
    }
}

function migrateRewardsBalance(address[] calldata guardians) external override {
    require(!settings.rewardAllocationActive, "Reward distribution must be deactivated for migration");
    IFeesAndBootstrapRewards currentRewardsContract = IFeesAndBootstrapRewards(getFeesAndBootstrapRewardsContract());
    require(address(currentRewardsContract) != address(this), "New rewards contract is not set");
    uint256 totalFees = 0;
    uint256 totalBootstrap = 0;
    uint256[] memory fees = new uint256[](guardians.length);
    uint256[] memory bootstrap = new uint256[](guardians.length);
    for (uint i = 0; i < guardians.length; i++) {
        updateGuardianFeesAndBootstrap(guardians[i]);
        FeesAndBootstrap memory guardianFeesAndBootstrap = feesAndBootstrap[guardians[i]];
        fees[i] = guardianFeesAndBootstrap.feeBalance;
        totalFees = totalFees.add(fees[i]);
        bootstrap[i] = guardianFeesAndBootstrap.bootstrapBalance;
        totalBootstrap = totalBootstrap.add(bootstrap[i]);
        guardianFeesAndBootstrap.feeBalance = 0;
        guardianFeesAndBootstrap.bootstrapBalance = 0;
        feesAndBootstrap[guardians[i]] = guardianFeesAndBootstrap;
    }
    require(feesToken.approve(address(currentRewardsContract), totalFees), "migrateRewardsBalance: approve failed");
    require(bootstrapToken.approve(address(currentRewardsContract), totalBootstrap), "migrateRewardsBalance: approve failed");
    currentRewardsContract.acceptRewardsBalanceMigration(guardians, fees, totalFees, bootstrap, totalBootstrap);
    for (uint i = 0; i < guardians.length; i++) {
        emit FeesAndBootstrapRewardsBalanceMigrated(guardians[i], fees[i], bootstrap[i], address(currentRewardsContract));
    }
}

