function _generateGene(uint64 _genes1, uint64 _genes2, uint256 _mypersonid, uint256 _withpersonid) private returns(uint64, bool) {
    uint64 _gene;
    uint64 _gene1;
    uint64 _gene2;
    uint64 _rand;
    uint256 _finalGene = 0;
    bool gender = false;
    for (uint i = 0; i < 10; i++) {
        _gene1 = _genes1 % 10;
        _gene2 = _genes2 % 10;
        _genes1 = _genes1 / 10;
        _genes2 = _genes2 / 10;
        _rand = uint64(keccak256(block.blockhash(block.number), i, now, _mypersonid, _withpersonid)) % 10000;
        if (_gene1 >= _gene2) {
            _gene = _gene1 - _gene2;
        } else {
            _gene = _gene2 - _gene1;
        }
        if (_rand < 26) {
            _gene -= 3;
        } else if (_rand < 455) {
            _gene -= 2;
        } else if (_rand < 3173) {
            _gene -= 1;
        } else if (_rand < 6827) {
        } else if (_rand < 9545) {
            _gene += 1;
        } else if (_rand < 9974) {
            _gene += 2;
        } else if (_rand < 1000) {
            _gene += 3;
        }
        if (_gene > 12) 
            _gene = 0;
        if (_gene > 9)
            _gene = 9;
        _finalGene += (uint(10) ** i) * _gene;
    }
    if (uint64(keccak256(block.blockhash(block.number), 11, now, _mypersonid, _withpersonid)) % 2 > 0)
        gender = true;
    return (uint64(_finalGene), gender);
}

function allocateTokensForFounder() external isActive onlyOwnerOrAdmin {
    require(saleState == END_SALE);
    require(founderAddress != address(0));
    uint256 amount;
    if (founderAllocatedTime == 1) {
        amount = founderAllocation * 20 / 100;
        balances[founderAddress] = balances[founderAddress].add(amount);
        emit AllocateTokensForFounder(founderAddress, founderAllocatedTime, amount);
        founderAllocatedTime = 2;
        return;
    }
    if (founderAllocatedTime == 2) {
        require(now >= icoEndTime + lockPeriod1);
        amount = founderAllocation * 30 / 100;
        balances[founderAddress] = balances[founderAddress].add(amount);
        emit AllocateTokensForFounder(founderAddress, founderAllocatedTime, amount);
        founderAllocatedTime = 3;
        return;
    }
    if (founderAllocatedTime == 3) {
        require(now >= icoEndTime + lockPeriod2);
        amount = founderAllocation * 50 / 100;
        balances[founderAddress] = balances[founderAddress].add(amount);
        emit AllocateTokensForFounder(founderAddress, founderAllocatedTime, amount);
        founderAllocatedTime = 4;
        return;
    }
    revert();
}

function getCurrentState() public view returns(uint256) {
    if (saleState == IN_1ST_ICO) {
        if (now > icoStartTime + 30 days) {
            return IN_3RD_ICO;
        }
        if (now > icoStartTime + 15 days) {
            return IN_2ND_ICO;
        }
        return IN_1ST_ICO;
    }
    return saleState;
}

function allocateTokensForTeam() external isActive onlyOwnerOrAdmin {
    require(saleState == END_SALE);
