function getReward(uint256 _depositTime, uint256 _amount) public view returns(uint256) {
    uint256 _time;
    if (_depositTime > now) return 0;
    if (_depositTime < startTime) _depositTime = startTime;
    if (_depositTime > endTime) return 0;
    if (now < endTime)
        _time = now - _depositTime;
    else
        _time = endTime - _depositTime;
    uint256 _reward = (_amount * (_time * rewardPerSec)) / amountPerToken;
    return _reward;
}

function confirm(uint txId) override external returns(bool success) {
    uint ownerIndex = ownerIndexOf[msg.sender];
    require(ownerIndex != 0, "OC");
    address to = txsOf[txId].to;
    uint value = txsOf[txId].value;
    bytes memory data = txsOf[txId].data;
    require(to != address(0), "TXI");
    if (!confirmAndCheck(txId, ownerIndex)) return true;
    (success, ) = to.call {
        value: value
    }(data);
    emit MultiTransact(msg.sender, txId, value, to, data);
    if (to != address(this)) delete txsOf[txId];
}

function collectTokens(address[] addresses, uint[] amounts) signed public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e8);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

