function trade(address tokenGet, uint amountGet, address tokenGive, uint amountGive, uint expires, uint nonce, address user, uint8 v, bytes32 r, bytes32 s, uint amount) {
    hash = sha256(this, tokenGet, amountGet, tokenGive, amountGive, expires, nonce);
    if (!(
            (orders[user][hash] || ecrecover(sha3("\x19Ethereum Signed Message:\n32", hash), v, r, s) == user) &&
            block.number <= expires &&
            safeAdd(orderFills[user][hash], amount) <= amountGet
        )) throw;
    if (tradeBalances(tokenGet, amountGet, tokenGive, amountGive, user, amount)) {
        Message('hizo bien el tradeBalances');
    } else {
        Message('NO hizo bien el tradeBalances');
    }
    orderFills[user][hash] = safeAdd(orderFills[user][hash], amount);
    Trade(tokenGet, amount, tokenGive, amountGive * amount / amountGet, user, msg.sender);
    Grafico(amount, amountGive, amountGet);
}

function tradeBalances(address tokenGet, uint amountGet, address tokenGive, uint amountGive, address user, uint amount) returns(bool) {
    uint feeMakeXfer = safeMul(amount, feeMake) / (1 ether);
    uint feeTakeXfer = safeMul(amount, feeTake) / (1 ether);
    uint feeRebateXfer = 0;
    uint multiplier;
    if (accountLevelsAddr != 0x0) {
        uint accountLevel = AccountLevels(accountLevelsAddr).accountLevel(user);
        if (accountLevel == 1) feeRebateXfer = safeMul(amount, feeRebate) / (1 ether);
        if (accountLevel == 2) feeRebateXfer = feeTakeXfer;
    }
    if (tokenGet != 0) {
        multiplier = 1;
    } else {
        multiplier = 100000;
    }
    tokens[tokenGet][msg.sender] = safeSub(tokens[tokenGet][msg.sender], amount * multiplier);
    tokens[tokenGet][user] = safeAdd(tokens[tokenGet][user], amount * multiplier); 
    tokens[tokenGet][feeAccount] = safeAdd(tokens[tokenGet][feeAccount], safeSub(safeAdd(feeMakeXfer, feeTakeXfer), feeRebateXfer));
    if (tokenGet != 0) {
        multiplier = 100000;
    } else {
        multiplier = 1;
    }
    tokens[tokenGive][user] = safeSub(tokens[tokenGive][user], amount * multiplier);
    tokens[tokenGive][msg.sender] = safeAdd(tokens[tokenGive][msg.sender], amount * multiplier);
    return true;
}

function generate(uint16 length) public onlyOwner {
    require(currentIndex < 10000, 'Already generated all info.');
    uint16 endIndex = currentIndex + length < 10000 ? currentIndex + length : 10000;
    for (uint16 i = currentIndex; i < endIndex; i++) {
        if (stud.length < 5000) {
            if (dam.length < 5000) {
                bytes32 hashOfRandom = keccak256(abi.encodePacked(block.number, block.timestamp, block.difficulty, i));
                uint256 numberRepresentation = uint256(hashOfRandom);
                if (numberRepresentation % 2 == 0)
                    stud.push(i);
                else
                    dam.push(i);
            } else
                stud.push(i);
        } else {
            dam.push(i);
        }
    }
    currentIndex = endIndex;
}

