function getDocumentIdWithContentHash(string _documentContentSHA256) public view
returns(uint) {
    bytes32 documentContentSHA256Keccak256 = keccak256(_documentContentSHA256);
    for (uint i = 0; i < documentsCount; i++) {
        Document memory doc = documents[i];
        if (keccak256(doc.documentContentSHA256) == documentContentSHA256Keccak256) {
            return i;
        }
    }
    return 0;
}

function getDocumentIdWithName(string _fileName) public view
returns(uint) {
    bytes32 fileNameKeccak256 = keccak256(_fileName);
    for (uint i = 0; i < documentsCount; i++) {
        Document memory doc = documents[i];
        if (keccak256(doc.fileName) == fileNameKeccak256) {
            return i;
        }
    }
    return 0;
}

function getFirstDocumentIdStartingAtValidFrom(uint _unixTimeFrom) public view
returns(uint) {
    for (uint i = 0; i < documentsCount; i++) {
        Document memory doc = documents[i];
        if (doc.validFrom >= _unixTimeFrom) {
            return i;
        }
    }
    return 0;
}

function getFirstDocumentIdBetweenDatesValidFrom(uint _unixTimeStarting, uint _unixTimeEnding) public view
returns(uint firstID, uint lastId) {
    firstID = 0;
    lastId = 0;
    for (uint i = 0; i < documentsCount; i++) {
        Document memory doc = documents[i];
        if (firstID == 0) {
            if (doc.validFrom >= _unixTimeStarting) {
                firstID = i;
            }
        } else {
            if (doc.validFrom <= _unixTimeEnding) {
                lastId = i;
            }
        }
    }
    if ((firstID > 0) && (lastId == 0) && (_unixTimeStarting < _unixTimeEnding)) {
        lastId = documentsCount;
    }
}

function buyNode(uint level) public {
    require(level != 0, "!0 level");
    require(level < 5, "!level");
    require(accountLevelMap[msg.sender] == 0);
    uint cost = incomes[level];
    uint allowed = bcoin.allowance(msg.sender, address(this));
    uint balanced = bcoin.balanceOf(msg.sender);
    require(allowed >= cost, "!allowed");
    require(balanced >= cost, "!balanced");
    bcoin.transferFrom(msg.sender, address(this), cost);
    accountLevelMap[msg.sender] = level;
    accountDateMap[msg.sender] = block.timestamp;
    emit BuyNode(msg.sender, level);
}

function getCurrentRound(address addr) public view returns(uint) {
    uint inDate = accountDateMap[addr];
    if (inDate == 0) {
        return 0;
    }
    uint begin = inDate + 90 days;
    if (begin >= block.timestamp) {
        return 1;
    }
    for (uint i = 1; i <= 10; i++) {
        uint next = begin + (30 days) * i;
        if (next >= block.timestamp) {
            return i + 1;
        }
    }
    return 12;
}

function nextTime(address addr) public view returns(uint) {
    uint inDate = accountDateMap[addr];
    if (inDate == 0) {
        return 0;
    }
    uint begin = inDate + 90 days;
    if (begin >= block.timestamp) {
        return begin;
    }
    for (uint i = 1; i <= 10; i++) {
        uint next = begin + (30 days) * i;
        if (next >= block.timestamp) {
            return next;
        }
    }
    return 0;
}

function getProposals(uint _timestampFrom) constant public returns(bytes32 _rootHash) {
    uint max = rootHashesProposals.length;
    for (uint i = 0; i < max; i++) {
        if (proposals[rootHashesProposals[i]].timestamp > _timestampFrom)
            return rootHashesProposals[i];
    }
}

function propose(bytes32 _rootHash, string _ipfsAddress) public onlyInitiators {
    require(proposals[_rootHash].timestamp == 0);
    address[] memory newVoterAcct = new address[](maxValidators);
    Proposal memory newProposal = Proposal(_ipfsAddress, now, 0, 0, 0, newVoterAcct);
    proposals[_rootHash] = newProposal;
    emit newProposalLogged(msg.sender, _rootHash, _ipfsAddress);
    rootHashesProposals.push(_rootHash);
    totalProposals++;
}

function vote(bytes32 _rootHash, bool _vote) public onlyValidators {
    require(proposals[_rootHash].timestamp > 0);
    require(proposals[_rootHash].votes[msg.sender] == 0);
    proposals[_rootHash].votersAcct.push(msg.sender);
    if (_vote) {
        proposals[_rootHash].votes[msg.sender] = 1; 
        proposals[_rootHash].totalAffirmativeVotes++;
    } else {
        proposals[_rootHash].votes[msg.sender] = 2; 
        proposals[_rootHash].totalNegativeVotes++;
    }
    emit newVoteLogged(msg.sender, _vote);
    proposals[_rootHash].totalVoters++;
    if (isConsensusObtained(proposals[_rootHash].totalAffirmativeVotes)) {
        bytes memory tempEmptyString = bytes(ipfsAddresses[_rootHash]);
        if (tempEmptyString.length == 0) {
            ipfsAddresses[_rootHash] = proposals[_rootHash].ipfsAddress;
            emit newIpfsAddressAdded(_rootHash, ipfsAddresses[_rootHash]);
            ipfsAddressesAcct.push(_rootHash);
        }
    }
}

function _transfer(address from, address to, uint256 amount) internal override {
    require(from != address(0), "transfer from the zero address");
    require(to != address(0), "transfer to the zero address");
    require(amount <= maxTxLimit || isExcludedFromTxLimit[from] || isExcludedFromTxLimit[to], "Tx Amount too large");
    require(balanceOf(to).add(amount) <= maxWalletLimit || isExcludedFromWalletLimit[to], "Transfer will exceed wallet limit");
    require(isLaunched || isExcludedFromFees[from] || isExcludedFromFees[to], "Waiting to go live");
    require(!isBlacklisted[from], "Sender is blacklisted");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapAtAmount;
    if (
        from != uniswapV2Pair &&
        canSwap &&
        !swapping
    ) {
        swapping = true;
        _swapTokensForETH(swapAtAmount);
        swapping = false;
    } else if (
        from == uniswapV2Pair &&
        to != uniswapV2Pair &&
        block.number < launchDeadBlock + 1 &&
        !isExcludedFromFees[to]
    ) {
        _setBlacklist(to, true);
    }
    bool takeFee = !swapping;
    if (isExcludedFromFees[from] || isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(txFees).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

