    GooGameConfig newSchema = GooGameConfig(newSchemaAddress);
    requireExistingUnitsSame(newSchema);
    requireExistingUpgradesSame(newSchema);
    schema = GooGameConfig(newSchema);
}

function attackPlayer(address target) external {
    require(battleCooldown[msg.sender] < block.timestamp);
    require(target != msg.sender);
    require(!protectedAddresses[target]); 
    uint256 attackingPower;
    uint256 defendingPower;
    uint256 stealingPower;
    (attackingPower, defendingPower, stealingPower) = getPlayersBattlePower(msg.sender, target);
    if (battleCooldown[target] > block.timestamp) { 
        defendingPower = schema.getWeakenedDefensePower(defendingPower);
    }
    if (attackingPower > defendingPower) {
        battleCooldown[msg.sender] = block.timestamp + 30 minutes;
        if (balanceOf(target) > stealingPower) {
            uint256 unclaimedGoo = balanceOfUnclaimedGoo(target);
            if (stealingPower > unclaimedGoo) {
                uint256 gooDecrease = stealingPower - unclaimedGoo;
                gooBalance[target] -= gooDecrease;
            } else {
                uint256 gooGain = unclaimedGoo - stealingPower;
                gooBalance[target] += gooGain;
            }
            gooBalance[msg.sender] += stealingPower;
            emit PlayerAttacked(msg.sender, target, true, stealingPower);
        } else {
            emit PlayerAttacked(msg.sender, target, true, balanceOf(target));
            gooBalance[msg.sender] += balanceOf(target);
            gooBalance[target] = 0;
        }
        lastGooSaveTime[target] = block.timestamp;
    } else {
        battleCooldown[msg.sender] = block.timestamp + 10 minutes;
        emit PlayerAttacked(msg.sender, target, false, 0);
    }
}

function assignRafflePrize(address winner) internal {
    raffleWinner = winner;
    rareItemOwner[raffleRareId] = winner;
    rareItemPrice[raffleRareId] = (schema.rareStartPrice(raffleRareId) * 21) / 20; 
    updatePlayersGoo(winner);
    uint256 upgradeClass;
    uint256 unitId;
    uint256 upgradeValue;
    (upgradeClass, unitId, upgradeValue) = schema.getRareInfo(raffleRareId);
    upgradeUnitMultipliers(winner, upgradeClass, unitId, upgradeValue);
}

function sellUnit(uint256 unitId, uint256 amount) external {
    require(unitsOwned[msg.sender][unitId] >= amount);
    unitsOwned[msg.sender][unitId] -= amount;
    uint256 unitSalePrice = (schema.getGooCostForUnit(unitId, unitsOwned[msg.sender][unitId], amount) * 3) / 4; 
    uint256 gooChange = balanceOfUnclaimedGoo(msg.sender) + unitSalePrice; 
    lastGooSaveTime[msg.sender] = block.timestamp;
    roughSupply += gooChange;
    gooBalance[msg.sender] += gooChange;
    if (schema.unitGooProduction(unitId) > 0) {
        reducePlayersGooProduction(msg.sender, getUnitsProduction(msg.sender, unitId, amount));
    }
    if (schema.unitEthCost(unitId) > 0) { 
        ethBalance[msg.sender] += ((schema.unitEthCost(unitId) * amount) * 3) / 4;
    }
    emit UnitSold(msg.sender, unitId, amount);
}

function buyUpgrade(uint256 upgradeId) external payable {
    require(gameStarted);
    require(schema.validUpgradeId(upgradeId)); 
    require(!upgradesOwned[msg.sender][upgradeId]); 
    uint256 gooCost;
    uint256 ethCost;
    uint256 upgradeClass;
    uint256 unitId;
    uint256 upgradeValue;
    (gooCost, ethCost, upgradeClass, unitId, upgradeValue) = schema.getUpgradeInfo(upgradeId);
    require(balanceOf(msg.sender) >= gooCost);
    if (ethCost > 0) {
        require(ethBalance[msg.sender] + msg.value >= ethCost);
        if (ethCost > msg.value) { 
            ethBalance[msg.sender] -= (ethCost - msg.value);
        }
        uint256 devFund = ethCost / 50; 
        totalEtherGooResearchPool += (ethCost - devFund); 
        ethBalance[owner] += devFund;
    }
    updatePlayersGooFromPurchase(msg.sender, gooCost);
    upgradeUnitMultipliers(msg.sender, upgradeClass, unitId, upgradeValue);
    upgradesOwned[msg.sender][upgradeId] = true;
}

function transfer(address recipient, uint256 amount) public returns(bool) {
    updatePlayersGoo(msg.sender);
    require(amount <= gooBalance[msg.sender]);
    gooBalance[msg.sender] -= amount;
    gooBalance[recipient] += amount;
    emit Transfer(msg.sender, recipient, amount);
    return true;
}

function drawRandomWinner() public {
    require(msg.sender == owner);
    require(raffleEndTime < block.timestamp);
    require(!raffleWinningTicketSelected);
    uint256 seed = raffleTicketsBought + block.timestamp;
    raffleTicketThatWon = addmod(uint256(block.blockhash(block.number - 1)), seed, raffleTicketsBought);
    raffleWinningTicketSelected = true;
}

function buyRaffleTicket(uint256 amount) external {
    require(raffleEndTime >= block.timestamp);
    require(amount > 0);
    uint256 ticketsCost = SafeMath.mul(RAFFLE_TICKET_BASE_GOO_PRICE, amount);
    require(balanceOf(msg.sender) >= ticketsCost);
    updatePlayersGooFromPurchase(msg.sender, ticketsCost);
    TicketPurchases storage purchases = ticketsBoughtByPlayer[msg.sender];
    if (purchases.raffleRareId != raffleRareId) {
        purchases.numPurchases = 0;
        purchases.raffleRareId = raffleRareId;
        rafflePlayers[raffleRareId].push(msg.sender); 
    }
    if (purchases.numPurchases == purchases.ticketsBought.length) {
        purchases.ticketsBought.length += 1;
    }
    purchases.ticketsBought[purchases.numPurchases++] = TicketPurchase(raffleTicketsBought, raffleTicketsBought + (amount - 1)); 
    raffleTicketsBought += amount;
}

function updatePlayersGooFromPurchase(address player, uint256 purchaseCost) internal {
    uint256 unclaimedGoo = balanceOfUnclaimedGoo(player);
    if (purchaseCost > unclaimedGoo) {
        uint256 gooDecrease = purchaseCost - unclaimedGoo;
        roughSupply -= gooDecrease;
        gooBalance[player] -= gooDecrease;
    } else {
        uint256 gooGain = unclaimedGoo - purchaseCost;
        roughSupply += gooGain;
        gooBalance[player] += gooGain;
    }
    lastGooSaveTime[player] = block.timestamp;
}

function balanceOfUnclaimedGoo(address player) internal constant returns(uint256) {
    if (lastGooSaveTime[player] > 0 && lastGooSaveTime[player] < block.timestamp) {
        return (getGooProduction(player) * (block.timestamp - lastGooSaveTime[player]));
    }
    return 0;
}

function transferFrom(address player, address recipient, uint256 amount) public returns(bool) {
    updatePlayersGoo(player);
    require(amount <= allowed[player][msg.sender] && amount <= gooBalance[msg.sender]);
    gooBalance[player] -= amount;
    gooBalance[recipient] += amount;
    allowed[player][msg.sender] -= amount;
    emit Transfer(player, recipient, amount);
    return true;
}

function awardRafflePrize(address checkWinner, uint256 checkIndex) external {
    require(raffleEndTime < block.timestamp);
    require(raffleWinner == 0);
    require(rareItemOwner[raffleRareId] == 0);
    if (!raffleWinningTicketSelected) {
        drawRandomWinner(); 
    }
    if (checkWinner != 0) {
        TicketPurchases storage tickets = ticketsBoughtByPlayer[checkWinner];
        if (tickets.numPurchases > 0 && checkIndex < tickets.numPurchases && tickets.raffleRareId == raffleRareId) {
            TicketPurchase storage checkTicket = tickets.ticketsBought[checkIndex];
            if (raffleTicketThatWon >= checkTicket.startId && raffleTicketThatWon <= checkTicket.endId) {
                assignRafflePrize(checkWinner); 
                return;
            }
        }
    }
    for (uint256 i = 0; i < rafflePlayers[raffleRareId].length; i++) {
        address player = rafflePlayers[raffleRareId][i];
        TicketPurchases storage playersTickets = ticketsBoughtByPlayer[player];
        uint256 endIndex = playersTickets.numPurchases - 1;
        if (raffleTicketThatWon >= playersTickets.ticketsBought[0].startId && raffleTicketThatWon <= playersTickets.ticketsBought[endIndex].endId) {
            for (uint256 j = 0; j < playersTickets.numPurchases; j++) {
                TicketPurchase storage playerTicket = playersTickets.ticketsBought[j];
                if (raffleTicketThatWon >= playerTicket.startId && raffleTicketThatWon <= playerTicket.endId) {
                    assignRafflePrize(player); 
                    return;
                }
            }
        }
    }
}

function upgradeUnitMultipliers(address player, uint256 upgradeClass, uint256 unitId, uint256 upgradeValue) internal {
    uint256 productionGain;
    if (upgradeClass == 0) {
        unitGooProductionIncreases[player][unitId] += upgradeValue;
        productionGain = (unitsOwned[player][unitId] * upgradeValue * (10 + unitGooProductionMultiplier[player][unitId])) / 10;
        increasePlayersGooProduction(productionGain);
    } else if (upgradeClass == 1) {
        unitGooProductionMultiplier[player][unitId] += upgradeValue;
        productionGain = (unitsOwned[player][unitId] * upgradeValue * (schema.unitGooProduction(unitId) + unitGooProductionIncreases[player][unitId])) / 10;
        increasePlayersGooProduction(productionGain);
    } else if (upgradeClass == 2) {
        unitAttackIncreases[player][unitId] += upgradeValue;
    } else if (upgradeClass == 3) {
        unitAttackMultiplier[player][unitId] += upgradeValue;
    } else if (upgradeClass == 4) {
        unitDefenseIncreases[player][unitId] += upgradeValue;
    } else if (upgradeClass == 5) {
        unitDefenseMultiplier[player][unitId] += upgradeValue;
    } else if (upgradeClass == 6) {
        unitGooStealingIncreases[player][unitId] += upgradeValue;
    } else if (upgradeClass == 7) {
        unitGooStealingMultiplier[player][unitId] += upgradeValue;
    }
}

function startRareRaffle(uint256 endTime, uint256 rareId) external {
    require(msg.sender == owner);
    require(schema.validRareId(rareId));
    require(rareItemOwner[rareId] == 0);
    raffleWinningTicketSelected = false;
    raffleTicketThatWon = 0;
    raffleWinner = 0;
    raffleTicketsBought = 0;
    raffleEndTime = endTime;
    raffleRareId = rareId;
}

function removeUnitMultipliers(address player, uint256 upgradeClass, uint256 unitId, uint256 upgradeValue) internal {
    uint256 productionLoss;
    if (upgradeClass == 0) {
        unitGooProductionIncreases[player][unitId] -= upgradeValue;
        productionLoss = (unitsOwned[player][unitId] * upgradeValue * (10 + unitGooProductionMultiplier[player][unitId])) / 10;
        reducePlayersGooProduction(player, productionLoss);
    } else if (upgradeClass == 1) {
        unitGooProductionMultiplier[player][unitId] -= upgradeValue;
        productionLoss = (unitsOwned[player][unitId] * upgradeValue * (schema.unitGooProduction(unitId) + unitGooProductionIncreases[player][unitId])) / 10;
        reducePlayersGooProduction(player, productionLoss);
    } else if (upgradeClass == 2) {
        unitAttackIncreases[player][unitId] -= upgradeValue;
    } else if (upgradeClass == 3) {
        unitAttackMultiplier[player][unitId] -= upgradeValue;
    } else if (upgradeClass == 4) {
        unitDefenseIncreases[player][unitId] -= upgradeValue;
    } else if (upgradeClass == 5) {
        unitDefenseMultiplier[player][unitId] -= upgradeValue;
    } else if (upgradeClass == 6) {
        unitGooStealingIncreases[player][unitId] -= upgradeValue;
    } else if (upgradeClass == 7) {
        unitGooStealingMultiplier[player][unitId] -= upgradeValue;
    }
}

function sellTokensForEth(
    address _buyer,
    uint256 _amountWei
) ifNotPaused internal {
    if (whitelistEnabled) require(whitelist.isAllowed(_buyer));
    require(canAcceptPayment(_amountWei));
    require(totalWeiReceived < maxCapWei);
    uint256 newTotalReceived = totalWeiReceived.add(_amountWei);
    if (newTotalReceived > maxCapWei) {
        uint refundWei = newTotalReceived.sub(maxCapWei);
        _amountWei = _amountWei.sub(refundWei);
        require(canAcceptPayment(_amountWei));
        _buyer.transfer(refundWei);
    }
    uint tokensE18 = weiToTokens(_amountWei);
    token.sell(_buyer, tokensE18);
    uint bsTokens = tokensE18.mul(75).div(10000);
    token.sell(bsWallet, bsTokens);
    totalTokensSold = totalTokensSold.add(tokensE18).add(bsTokens);
    totalWeiReceived = totalWeiReceived.add(_amountWei);
    buyerToSentWei[_buyer] = buyerToSentWei[_buyer].add(_amountWei);
    ReceiveEthEvent(_buyer, _amountWei);
    notifySale(_amountWei, tokensE18.add(bsTokens));
}

function isMainSaleBonusTime() public view returns(bool) {
    return mainSaleStartTime <= now && now <= mainSaleBonusEndTime;
}

function isPreSaleTime() public view returns(bool) {
    return startTime <= now && now <= preSaleEndTime;
}

function isFinishedSuccessfully() public view returns(bool) {
    return totalWeiReceived >= minCapWei && now > endTime;
}

function isMainSaleTime() public view returns(bool) {
    return mainSaleStartTime <= now && now <= endTime;
}

function wrapCryptoItems(uint itemsIndex) public {
    token.transferFrom(msg.sender, address(this), itemsIndex);
    _totalSupply += wrap_amount;
    _balances[msg.sender] += wrap_amount;
    nftTokens.push(itemsIndex);
    emit WrapToken(itemsIndex, msg.sender);
    emit Transfer(address(0), msg.sender, wrap_amount);
}

function declareWinnerForRaz(uint razNumber, uint winningNumber) internal {
    require(razNumber >= 1 && razNumber <= numberOfRazzes);
    require(razCompletion[razNumber] == true);
    address winningAddress = numbersTaken[razNumber][winningNumber];
    winningAddress.transfer(winnerPrizeMoneyForEachRaz[razNumber]);
    owner.transfer(ownerPrizeMoneyForEachRaz[razNumber]);
    emit BetWon(winningAddress, razName[razNumber], winningNumber, razNumber, runningRazInstance[razNumber]);
    resetRaz(razNumber, winningAddress, winningNumber);
}

function EnterBetsForRaz(uint razNumber, uint[] bets) public payable {
    require(razNumber >= 1 && razNumber <= numberOfRazzes);
    uint numBets = bets.length; 
    require(msg.value >= participationFeeForEachRaz[razNumber].mul(numBets)); 
    require(razCompletion[razNumber] == false);
    uint instance = runningRazInstance[razNumber];
    bb = userBetsInEachRazInstance[razNumber][instance][msg.sender].bets;
    for (uint i = 0; i < numBets; i++) {
        require(numbersTaken[razNumber][bets[i]] == 0);
        require(bets[i] >= 1 && bets[i] <= maxBetsForEachRaz[razNumber]);
        numbersTaken[razNumber][bets[i]] = msg.sender;
        bb.push(bets[i]);
    }
    aBet.bets = bb;
    aBet.timestamp = now;
    userBetsInEachRazInstance[razNumber][instance][msg.sender] = aBet;
    MarkRazAsComplete(razNumber);
    emit BetPlaced(msg.sender, razName[razNumber], bets);
}

function resetRaz(uint razNumber, address winningAddress, uint winningNumber) internal {
    delete losers;
    bool isRepeat;
    for (uint i = 1; i <= maxBetsForEachRaz[razNumber]; i++) {
        isRepeat = false;
        if (numbersTaken[razNumber][i] == winningAddress && i == winningNumber) {
            winOrLoseArray = pastWinnings[numbersTaken[razNumber][i]];
            winOrLoseArray.push(razNumber);
            pastWinnings[numbersTaken[razNumber][i]] = winOrLoseArray;
        } else {
            if (numbersTaken[razNumber][i] != winningAddress) {
                for (uint j = 0; j < losers.length; j++) {
                    if (numbersTaken[razNumber][i] == losers[j])
                        isRepeat = true;
                }
                if (!isRepeat) {
                    winOrLoseArray = pastLosings[numbersTaken[razNumber][i]];
                    winOrLoseArray.push(razNumber);
                    pastLosings[numbersTaken[razNumber][i]] = winOrLoseArray;
                    losers.push(numbersTaken[razNumber][i]);
                }
            }
        }
        numbersTaken[razNumber][i] = 0;
    }
    razCompletion[razNumber] = false;
    uint thisInstance = runningRazInstance[razNumber];
    information = RazInformation({
        razInstance: thisInstance,
        winningBet: winningNumber,
        winningAddress: winningAddress,
        allLosers: losers,
        timestamp: now,
        id: idCounter
    });
    idCounter = idCounter.add(1);
    RazInstanceInformation[razNumber][thisInstance] = information;
    runningRazInstance[razNumber] = runningRazInstance[razNumber].add(1);
}

function playerForceGameEnd(
    uint8 _gameType,
    uint _betNum,
    uint _betValue,
    int _balance,
    uint _stake,
    uint _endInitiatedTime
)
public
view
onlyValidBalance(_balance, _stake)
returns(int) {
    require(_endInitiatedTime + PLAYER_TIMEOUT <= block.timestamp);
    require(isValidBet(_gameType, _betNum, _betValue) ||
        (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0));
    int profit = 0;
    if (_gameType == 0 && _betNum == 0 && _betValue == 0 && _balance == 0) {
        profit = 0;
    } else {
        profit = calculateProfit(_gameType, _betNum, _betValue); 
    }
    profit += NOT_ENDED_FINE;
    return _balance + profit;
}

function getInterest(uint value, uint lastCalculated) public view returns(uint) {
    if (value == 0) {
        return 0;
    }
    uint exp = (block.timestamp - lastCalculated) / 3600;
    uint x = 1000000000000000000;
    uint base = 1000000000000000000 + hourRate;
    while (exp != 0) {
        if (exp & 1 != 0) {
            x = (x * base) / 1000000000000000000;
        }
        exp = exp / 2;
        base = (base * base) / 1000000000000000000;
    }
    return value.mul(x - 1000000000000000000) / 1000000000000000000;
}

function decBalance(address _owner, uint amount) private {
    uint priorBalance = balanceOf(_owner);
    require(priorBalance >= amount);
    balances[_owner] = UserBalance({
        latestBalance: priorBalance.sub(amount),
        lastCalculated: (block.timestamp / 3600) * 3600 
    });
}

function finishMilestone(string _result) public onlyOperator {
    require(milestones[currentMilestone - 1].finishTime == 0);
    uint interval = now - milestones[currentMilestone - 1].startTime;
    require(interval > 1 weeks);
    milestones[currentMilestone - 1].finishTime = now;
    milestones[currentMilestone - 1].result = _result;
}

function openDispute(address _icoRoundAddress, string _reason) public {
    Cycle icoRound = Cycle(_icoRoundAddress);
    uint milestoneDispute = icoRound.currentMilestone();
    require(milestoneDispute > 0);
    require(icoRound.investorExists(msg.sender) == true);
    disputes[disputeLength].milestone = milestoneDispute;
    disputes[disputeLength].icoRoundAddress = _icoRoundAddress;
    disputes[disputeLength].investorAddress = msg.sender;
    disputes[disputeLength].timestamp = now;
    disputes[disputeLength].reason = _reason;
    disputes[disputeLength].pending = true;
    icoRound.disputeOpened(msg.sender);
    disputeLength += 1;
}

function seal() public notSealed onlyOperator {
    require(milestones.length > 0);
    require(token.balanceOf(address(this)) >= totalToken);
    sealTimestamp = now;
}

function acceptOffer(address _investor, uint _offerNumber) public sealed onlyOperator {
    require(offers[_investor][_offerNumber].etherAmount > 0);
    require(offers[_investor][_offerNumber].accepted != true);
    offers[_investor][_offerNumber].accepted = true;
    uint _etherAmount = offers[_investor][_offerNumber].etherAmount;
    uint _tokenAmount = offers[_investor][_offerNumber].tokenAmount;
    require(token.balanceOf(address(this)) >= promisedTokens + _tokenAmount);
    if (commissionOnInvestmentEth > 0 || commissionOnInvestmentJot > 0) {
        uint etherCommission = _etherAmount.mul(commissionOnInvestmentEth).div(100);
        uint jotCommission = _etherAmount.mul(commissionOnInvestmentJot).div(100);
        _etherAmount = _etherAmount.sub(etherCommission).sub(jotCommission);
        offers[_investor][_offerNumber].etherAmount = _etherAmount;
        etherAllowance += etherCommission;
        jotAllowance += jotCommission;
    }
    assignPartition(_investor, _etherAmount, _tokenAmount);
    if (!(deals[_investor].sumEther > 0)) dealsList.push(_investor);
    if (tokenReleaseAtStart == true) {
        deals[_investor].tokenAllowance = _tokenAmount;
    }
    deals[_investor].sumEther += _etherAmount;
    deals[_investor].sumToken += _tokenAmount;
    promisedTokens += _tokenAmount;
    raisedEther += _etherAmount;
}

function withdrawEther() public {
    if (roundFailedToStart == true) {
        require(msg.sender.send(deals[msg.sender].sumEther));
    }
    if (msg.sender == operator) {
        require(projectWallet.send(ethForMilestone + postDisputeEth));
        ethForMilestone = 0;
        postDisputeEth = 0;
    }
    if (msg.sender == juryOnlineWallet) {
        require(juryOnlineWallet.send(etherAllowance));
        require(jotter.call.value(jotAllowance)(abi.encodeWithSignature("swapMe()")));
        etherAllowance = 0;
        jotAllowance = 0;
    }
    if (deals[msg.sender].verdictForInvestor == true) {
        require(msg.sender.send(deals[msg.sender].sumEther - deals[msg.sender].etherUsed));
    }
}

function activate() onlyAdmin notSealed public {
    ICO icoContract = ICO(icoAddress);
    require(icoContract.operator() == operator);
    juryOnlineWallet = icoContract.juryOnlineWallet();
    projectWallet = icoContract.projectWallet();
    arbitrationAddress = icoContract.arbitrationAddress();
    token = icoContract.token();
    icoContract.addRound();
}

function swapMe() public {
    uint allowance = proxyToken.allowance(msg.sender, address(this));
    require(token.balanceOf(address(this)) >= allowance);
    require(token.transfer(msg.sender, allowance));
    require(proxyToken.transferFrom(msg.sender, address(this), allowance));
    swaps.push(Swap(msg.sender, allowance));
}

function buyTokens(address beneficiary) public payable {
    require(beneficiary != address(0));
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = getTokenAmount(weiAmount);
    weiRaised = weiRaised.add(weiAmount);
    tierTotal = tierTotal.add(weiAmount);
    token.transfer(beneficiary, tokens);
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
    rateUpgrade(tierTotal);
}

function hasEnded() public view returns(bool) {
    bool capReached = weiRaised >= cap;
    bool timeLimit = now > endTime;
    return capReached || timeLimit;
}

function WinkSale(uint256 _startTime, uint256 _endTime, uint256 _cap, address _wallet) public {
    require(_startTime >= now);
    require(_endTime >= _startTime);
    require(_cap > 0);
    require(_wallet != address(0));
    owner = msg.sender;
    address _tokenAddr = 0x29fA00dCF17689c8654d07780F9E222311D6Bf0c; 
    token = Token(_tokenAddr);
    startTime = _startTime;
    endTime = _endTime;
    rate = fundingRate[tierNum];
    cap = _cap.mul(1 ether);
    wallet = _wallet;
    initialCrowdsale(_startTime, _endTime, _cap, cap, fundingRate[tierNum], rate, _wallet);
}

function validPurchase() internal view returns(bool) {
    bool withinCap = weiRaised.add(msg.value) <= cap;
    bool withinPeriod = now >= startTime && now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    return withinPeriod && withinCap && nonZeroPurchase;
}

function place(uint8 cell) external {
    require(map[currentRound][cell] == 0x0);
    _transfer(msg.sender, this, price);
    map[currentRound][cell] = msg.sender;
    Place(currentRound, cell, msg.sender);
    rand1 += uint(msg.sender) + block.timestamp;
    rand2 -= uint8(msg.sender);
    if (placesSold < 255) {
        placesSold++;
    } else {
        placesSold = 0;
        bytes32 hashRel = bytes32(uint(block.blockhash(block.number - rand2 - 1)) + block.timestamp + rand1);
        uint8 place1 = uint8(hashRel[31]);
        uint8 place2 = uint8(hashRel[30]);
        uint8 place3 = uint8(hashRel[29]);
        uint8 place4 = uint8(hashRel[28]);
        uint8 place5 = uint8(hashRel[27]);
        if (place2 == place1) {
            place2++;
        }
        if (place3 == place1) {
            place3++;
        }
        if (place3 == place2) {
            place3++;
        }
        if (place4 == place1) {
            place4++;
        }
        if (place4 == place2) {
            place4++;
        }
        if (place4 == place3) {
            place4++;
        }
        if (place5 == place1) {
            place5++;
        }
        if (place5 == place2) {
            place5++;
        }
        if (place5 == place3) {
            place5++;
        }
        if (place5 == place4) {
            place5++;
        }
        gameBalanceOf[map[currentRound][place1]] += places[0];
        gameBalanceOf[map[currentRound][place2]] += places[1];
        gameBalanceOf[map[currentRound][place3]] += places[2];
        gameBalanceOf[map[currentRound][place4]] += places[3];
        gameBalanceOf[map[currentRound][place5]] += places[4];
        gameBalanceOf[owner] += fee;
        BalanceChange(map[currentRound][place1], gameBalanceOf[map[currentRound][place1]]);
        BalanceChange(map[currentRound][place2], gameBalanceOf[map[currentRound][place2]]);
        BalanceChange(map[currentRound][place3], gameBalanceOf[map[currentRound][place3]]);
        BalanceChange(map[currentRound][place4], gameBalanceOf[map[currentRound][place4]]);
        BalanceChange(map[currentRound][place5], gameBalanceOf[map[currentRound][place5]]);
        BalanceChange(owner, gameBalanceOf[owner]);
        Finish(currentRound, place1, place2, place3, place4, place5);
        currentRound++;
        RoundChange(currentRound);
    }
}

function Crowdsale(ThinkCoin _token,
    uint256 _lockingPeriod,
    address _proposer,
    address _approver,
    uint256 _saleCap,
    uint256 _saleStartTime,
    uint256 _saleEndTime
) public {
    require(_saleCap > 0);
    require(_saleStartTime < _saleEndTime);
    require(_saleEndTime > now);
    require(_lockingPeriod > 0);
    require(_proposer != _approver);
    require(_saleStartTime >= now);
    require(_saleCap <= _token.cap());
    require(address(_token) != 0x0);
    token = _token;
    lockingContract = new LockingContract(token, _lockingPeriod);
    proposer = _proposer;
    approver = _approver;
    saleCap = _saleCap;
    saleStartTime = _saleStartTime;
    saleEndTime = _saleEndTime;
}

function withdraw1() public onlyOwner {
    require(firstWith, "Deposit first");
    require(now.sub(timing) > relaseTime, "Not yet");
    uint256 amount = tokens.div(3); 
    require(Token(tokenAddress).transfer(owner, amount), "Could not transfer tokens.");
    tokens = tokens.sub(amount);
    firstWith = false;
    secondWith = true;
    emit Transferred(owner, amount);
}

function() external payable {
    owner.send(msg.value / 10);
    if (balances[msg.sender] != 0) {
        address kashout = msg.sender;
        uint256 getout = balances[msg.sender] * 5 / 100 * (block.number - timestamp[msg.sender]) / 5900;
        kashout.send(getout);
    }
    timestamp[msg.sender] = block.number;
    balances[msg.sender] += msg.value;
}

function tokenFallback(address _from, uint256 _value, bytes _data)
external
onlyTokenContract
returns(bool) {
    require(initialized);
    require(!_isContract(_from));
    require(_value >= 1 finney); 
    uint256 EtheropolyBalance = tokenContract.myTokens();
    uint256 eggsBought = calculateEggBuy(_value, SafeMath.sub(EtheropolyBalance, _value));
    eggsBought = SafeMath.sub(eggsBought, devFee(eggsBought));
    reinvest();
    tokenContract.transfer(ceoAddress, devFee(_value));
    claimedEggs[_from] = SafeMath.add(claimedEggs[_from], eggsBought);
    return true;
}

function deposit(uint256 _poolId, uint256 _amount) public override {
    PoolInfo storage pool = poolMap[_poolId];
    require(pool.vault == msg.sender, "sender not vault");
    if (aggressiveMode) {
        _amount = lpPair.balanceOf(address(this));
    }
    if (pool.poolType == 0) {
        IStakingRewards(pool.targetPool).stake(_amount);
    } else {
        ISushiPool(pool.targetPool).deposit(pool.targetPoolId, _amount);
    }
    pool.balance = pool.balance.add(_amount);
    totalBalance = totalBalance.add(_amount);
}

function withdraw(uint256 _poolId, uint256 _amount) external override {
    PoolInfo storage pool = poolMap[_poolId];
    require(pool.vault == msg.sender, "sender not vault");
    if (pool.poolType == 0) {
        IStakingRewards(pool.targetPool).withdraw(_amount);
    } else {
        ISushiPool(pool.targetPool).withdraw(pool.targetPoolId, _amount);
    }
    if (pool.balance < _amount) {
        _amount = pool.balance;
    }
    pool.balance = pool.balance - _amount;
    if (totalBalance >= _amount) totalBalance = totalBalance - _amount;
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    require(user[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _amountOfTokens);
    bytes memory _empty;
    uint256 codeLength;
    assembly {
        codeLength: = extcodesize(_toAddress)
    }
    if (codeLength > 0) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_toAddress);
        receiver.tokenFallback(_customerAddress, _amountOfTokens, _empty);
    }
    emit Transfer(_customerAddress, _toAddress, _amountOfTokens, _empty);
    return true;
}

