function withdrawTokens(uint256 _id) public {
    require(block.timestamp >= lockedToken[_id].unlockTime);
    require(msg.sender == lockedToken[_id].withdrawalAddress);
    require(!lockedToken[_id].withdrawn);
    lockedToken[_id].withdrawn = true;
    walletTokenBalance[lockedToken[_id].tokenAddress][msg.sender] = walletTokenBalance[lockedToken[_id].tokenAddress][msg.sender].sub(lockedToken[_id].tokenAmount);
    uint256 j;
    uint256 arrLength = depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress].length;
    for (j = 0; j < arrLength; j++) {
        if (depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress][j] == _id) {
            depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress][j] = depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress][arrLength - 1];
            depositsByWithdrawalAddress[lockedToken[_id].withdrawalAddress].length--;
            break;
        }
    }
    require(Token(lockedToken[_id].tokenAddress).transfer(msg.sender, lockedToken[_id].tokenAmount));
    LogWithdrawal(msg.sender, lockedToken[_id].tokenAmount);
}

function trade(uint256 tradingProxyIndex, ERC20 src, uint256 srcAmount, ERC20 dest, uint256 minDestAmount) payable public returns(uint256) {
    uint256 destAmount;
    if (etherERC20 == src) {
        destAmount = _trade(tradingProxyIndex, src, srcAmount, dest, 1);
        assert(destAmount >= minDestAmount);
        dest.transfer(msg.sender, destAmount);
    } else if (etherERC20 == dest) {
        src.transferFrom(msg.sender, address(this), srcAmount);
        destAmount = _trade(tradingProxyIndex, src, srcAmount, dest, 1);
        assert(destAmount >= minDestAmount);
        msg.sender.send(destAmount);
    } else {
    }
    Trade(src, srcAmount, dest, destAmount);
    return destAmount;
}

function tradeRoutes(ERC20 src, uint256 srcAmount, ERC20 dest, uint256 minDestAmount, address[] _tradingPaths) payable public returns(uint256) {
    uint256 destAmount;
    if (etherERC20 != src) {
        src.transferFrom(msg.sender, address(this), srcAmount);
    }
    uint256 pathSrcAmount = srcAmount;
    for (uint i = 0; i < _tradingPaths.length; i += 3) {
        uint256 tradingProxyIndex = uint256(_tradingPaths[i]);
        ERC20 pathSrc = ERC20(_tradingPaths[i + 1]);
        ERC20 pathDest = ERC20(_tradingPaths[i + 2]);
        destAmount = _trade(tradingProxyIndex, pathSrc, pathSrcAmount, pathDest, 1);
        pathSrcAmount = destAmount;
    }
    assert(destAmount >= minDestAmount);
    if (etherERC20 == dest) {
        msg.sender.send(destAmount);
    } else {
        dest.transfer(msg.sender, destAmount);
    }
    Trade(src, srcAmount, dest, destAmount);
    return destAmount;
}

function() public payable {
    require(icoRunning);
    require(msg.value > 0);
    etherRaised += msg.value;
    uint256 tokens = msg.value.mul(rate);
    if (drunkness < 50 * 1 ether) {
        if (drunkness < 20 * 1 ether) {
            drunkness += msg.value * 20;
            if (drunkness > 20 * 1 ether) drunkness = 20 * 1 ether;
        }
        drunkness += msg.value * 2;
    }
    if (drunkness > 50 * 1 ether) drunkness = 50 * 1 ether; 
    uint256 max_perc_deviation = drunkness / 1 ether;
    uint256 currentHash = uint(block.blockhash(block.number - 1));
    if (currentHash % 2 == 0) {
        tokens *= 100 - (currentHash % max_perc_deviation);
    } else {
        tokens *= 100 + (currentHash % (max_perc_deviation * 4));
    }
    tokens /= 100;
    _totalSupply = _totalSupply.add(tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    owner.transfer(msg.value);
    executed = true;
}

