function() public isRunning payable {
    require(msg.value >= minPurchase);
    uint256 unsold = forSale.subtract(totalSold);
    uint256 paid = msg.value;
    uint256 purchased = paid.divide(price);
    if (purchased > unsold) {
        purchased = unsold;
    }
    uint256 toReturn = paid.subtract(purchased.multiply(price));
    uint256 reward = calculateReward(totalSold, purchased);
    if (toReturn > 0) {
        msg.sender.transfer(toReturn);
    }
    token.transfer(msg.sender, purchased.add(reward));
    allocateFunds();
    buyers[msg.sender] = buyers[msg.sender].add(paid.subtract(toReturn));
    totalSold = totalSold.add(purchased);
}

function allocateFunds() internal {
    if (totalSold < softCap) {
        return;
    }
    uint256 balance = address(this).balance - 5000 ether;
    uint length = beneficiaries.length;
    uint256 toTransfer = 0;
    for (uint i = 1; i < length; i++) {
        Beneficiary storage beneficiary = beneficiaries[i];
        toTransfer = beneficiary.toTransfer.subtract(beneficiary.transferred);
        if (toTransfer > 0) {
            if (toTransfer > balance) {
                toTransfer = balance;
            }
            beneficiary.wallet.transfer(toTransfer);
            beneficiary.transferred = beneficiary.transferred.add(toTransfer);
            break;
        }
    }
}

function getLatestPrice(address token) internal returns(uint256 _k, uint256 _ethAmount, uint256 _erc20Amount, uint256 _blockNum) {
    uint256 _balanceBefore = address(this).balance;
    OracleParams memory _op;
    (
        _op.blockNum,
        _op.erc20Amount,
        ,
        ,
        _op.avgPrice,
        _op.sigma
    ) = INestPriceFacade(oracle).latestPriceAndTriggeredPriceInfo {
        value: msg.value
    }(token, address(this));
    _op.sigma = sqrt(_op.sigma.mul(1e18));
    _op.ethAmount = 1 ether;
    _op.T = block.number.sub(_op.blockNum).mul(timespan);
    require(_op.T < T, "CoFiXCtrl: oralce price outdated"); 
    {
        uint256 price;
        bool isDeviated;
        price = _op.erc20Amount.mul(1e18).div(_op.ethAmount);
        uint256 diff = price > _op.avgPrice ? (price - _op.avgPrice) : (_op.avgPrice - price);
        isDeviated = (diff.mul(100) < _op.avgPrice.mul(PRICE_DEVIATION)) ? false : true;
        require(isDeviated == false, "CoFiXCtrl: price deviation"); 
    }
    {
        uint256 gamma = calcGamma(_op.sigma);
        _k = K_ALPHA.mul(_op.T).mul(1e18).add(K_BETA.mul(_op.sigma)).mul(gamma).div(K_GAMMA_BASE).div(1e18);
        emit NewK(token, _k, _op.sigma, _op.T, _op.ethAmount, _op.erc20Amount, _op.blockNum);
    }
    {
        uint256 oracleFeeChange = msg.value.sub(_balanceBefore.sub(address(this).balance));
        if (oracleFeeChange > 0) TransferHelper.safeTransferETH(msg.sender, oracleFeeChange);
        KInfoMap[token][0] = uint32(_k);
        KInfoMap[token][1] = uint32(block.timestamp); 
        return (_k, _op.ethAmount, _op.erc20Amount, _op.blockNum);
    }
}

