}

function getPeriod(uint256 _currentDate) public pure returns(uint) {
    if (1522454400 <= _currentDate && _currentDate <= 1523059199) {
        return 0;
    }
    if (1523059200 <= _currentDate && _currentDate <= 1523923199) {
        return 1;
    }
    if (1523923200 <= _currentDate && _currentDate <= 1524787199) {
        return 2;
    }
    if (1524787200 <= _currentDate && _currentDate <= 1525651199) {
        return 3;
    }
    if (1525651200 <= _currentDate && _currentDate <= 1526515199) {
        return 4;
    }
    if (1526515200 <= _currentDate && _currentDate <= 1527811199) {
        return 5;
    }
    return 10;
}

function getAfterIcoPeriod(uint256 _currentDate) public pure returns(uint) {
    uint256 endIco = 1527811199; 
    if (endIco < _currentDate && _currentDate <= endIco + 2 years) {
        return 100;
    }
    if (endIco + 2 years < _currentDate && _currentDate <= endIco + 4 years) {
        return 200;
    }
    if (endIco + 4 years < _currentDate && _currentDate <= endIco + 6 years) {
        return 300;
    }
    if (endIco + 6 years < _currentDate && _currentDate <= endIco + 8 years) {
        return 400;
    }
    return 0;
}

function awardTAC(address winner, address loser, address referee) public {
    require(msg.sender == coopDataContract, "Only the CoopData Contract may call this function");
    ITACLockup TACLockup = ITACLockup(lockupContract);
    uint256 tokensToIssue = (athleteBase + athleteBase + poolBase + refBase) * multiplier;
    if ((tokensToIssue + reserveIssued) <= maxTokenReserve) {
        reserveIssued += tokensToIssue;
        _mint(lockupContract, athleteBase * multiplier);
        TACLockup.adjustBalance(winner, athleteBase * multiplier);
        _mint(lockupContract, athleteBase * multiplier);
        TACLockup.adjustBalance(loser, athleteBase * multiplier);
        _mint(lockupContract, refBase * multiplier);
        TACLockup.adjustBalance(referee, refBase * multiplier);
        _mint(votingPoolContract, poolBase * multiplier);
    }
}

function tokensale(address recipient) public payable {
    price = getPrice();
    require(price != 0 && recipient != 0x0);
    uint256 weiAmount = msg.value;
    uint256 tokenToSend = weiAmount.mul(price);
    balances[owner] = balances[owner].sub(tokenToSend);
    balances[recipient] = balances[recipient].add(tokenToSend);
    owner.transfer(msg.value);
    emit TokenPurchase(msg.sender, recipient, weiAmount, tokenToSend);
}

function capitalNeeded()
public
view
returns(uint _amount) {
    return capitalRaisedTarget > capitalRaised ?
        capitalRaisedTarget - capitalRaised :
        0;
}

function executeRequest(uint32 _id)
public {
    Request storage r = requests[_id];
    require(r.id != 0 && r.dateCancelled == 0 && r.dateExecuted == 0);
    require(uint32(now) > r.dateCreated + WAITING_TIME);
    if (uint32(now) > r.dateCreated + TIMEOUT_TIME) {
        cancelRequest(_id, "Request timed out.");
        return;
    }
    r.dateExecuted = uint32(now);
    string memory _msg;
    bool _success;
    RequestType _type = RequestType(r.typeId);
    if (_type == RequestType.SendCapital) {
        (_success, _msg) = executeSendCapital(r.target, r.value);
    } else if (_type == RequestType.RecallCapital) {
        (_success, _msg) = executeRecallCapital(r.target, r.value);
    } else if (_type == RequestType.RaiseCapital) {
        (_success, _msg) = executeRaiseCapital(r.value);
    } else if (_type == RequestType.DistributeCapital) {
        (_success, _msg) = executeDistributeCapital(r.value);
    }
    r.executedSuccessfully = _success;
    r.executedMsg = _msg;
    _removePendingRequestId(_id);
    completedRequestIds.push(_id);
    emit RequestExecuted(now, r.id, r.typeId, r.target, _success, _msg);
}

function executeDistributeCapital(uint _value)
internal
returns(bool _success, string _result) {
    if (_value > capital)
        return (false, "Not enough capital.");
    capital -= _value;
    profits += _value;
    profitsTotal += _value;
    emit CapitalRemoved(now, this, _value);
    emit ProfitsReceived(now, this, _value);
    emit ExecutedDistributeCapital(now, _value);
    return (true, "Capital moved to profits.");
}

function cancelRequest(uint32 _id, string _msg)
public
fromAdmin {
    Request storage r = requests[_id];
    require(r.id != 0 && r.dateCancelled == 0 && r.dateExecuted == 0);
    r.dateCancelled = uint32(now);
    r.cancelledMsg = _msg;
    _removePendingRequestId(_id);
    cancelledRequestIds.push(_id);
    emit RequestCancelled(now, r.id, r.typeId, r.target, _msg);
}

function executeSendCapital(address _bankrollable, uint _value)
internal
returns(bool _success, string _result) {
    if (_value > capital)
        return (false, "Not enough capital.");
    if (!_hasCorrectTreasury(_bankrollable))
        return (false, "Bankrollable does not have correct Treasury.");
    capital -= _value;
    capitalLedger.add(_bankrollable, _value);
    _ITrBankrollable(_bankrollable).addBankroll.value(_value)();
    emit CapitalRemoved(now, _bankrollable, _value);
    emit ExecutedSendCapital(now, _bankrollable, _value);
    return (true, "Sent bankroll to target.");
}

function isRequestExecutable(uint32 _requestId)
public
view
returns(bool _isExecutable) {
    Request memory r = requests[_requestId];
    _isExecutable = (r.id > 0 && r.dateCancelled == 0 && r.dateExecuted == 0);
    _isExecutable = _isExecutable && (uint32(now) > r.dateCreated + WAITING_TIME);
    return _isExecutable;
}

function issueDividend()
public
returns(uint _profits) {
    if (address(comptroller) == address(0)) {
        emit DividendFailure(now, "Comptroller not yet set.");
        return;
    }
    if (comptroller.wasSaleEnded() == false) {
        emit DividendFailure(now, "CrowdSale not yet completed.");
        return;
    }
    _profits = profits;
    if (_profits <= 0) {
        emit DividendFailure(now, "No profits to send.");
        return;
    }
    address _token = comptroller.token();
    profits = 0;
    profitsSent += _profits;
    require(_token.call.value(_profits)());
    emit DividendSuccess(now, _token, _profits);
}

function initComptroller(_ITrComptroller _comptroller)
public {
    require(msg.sender == owner);
    require(address(comptroller) == address(0));
    require(_comptroller.treasury() == address(this));
    comptroller = _comptroller;
    emit ComptrollerSet(now, _comptroller, comptroller.token());
}

function createRequest(uint _typeId, address _target, uint _value, string _msg)
public
fromAdmin {
    uint32 _id = ++curRequestId;
    requests[_id].id = _id;
    requests[_id].typeId = uint8(RequestType(_typeId));
    requests[_id].dateCreated = uint32(now);
    requests[_id].createdMsg = _msg;
    requests[_id].target = _target;
    requests[_id].value = _value;
    _addPendingRequestId(_id);
    emit RequestCreated(now, _id, _typeId, _target, _value, _msg);
}

function batchFishAquarium(uint256[] _seeds, address _affiliate) payable public {
    require(_seeds.length > 0);
    require(msg.value >= aquariumCost);
    require(randomHashes.length > hashesUsed + _seeds.length);
    if (msg.value > aquariumCost * _seeds.length) {
        msg.sender.transfer(msg.value - aquariumCost * _seeds.length);
    }
    for (uint256 i = 0; i < _seeds.length; i++) {
        _fishAquarium(_seeds[i]);
    }
    if (_affiliate != address(0)) {
        pendingFishing[randomHashes[hashesUsed - 1]].affiliate = _affiliate;
    }
}

function restTime(address _member)
public
view
returns(uint256) {
    uint256 timeDist = block.timestamp - lastClaim[_member];
    if (timeDist >= TIME_OUT) return 0;
    return TIME_OUT - timeDist;
}

function timeout(address _member)
public
view
returns(bool) {
    return lastClaim[_member] > 0 && restTime(_member) == 0;
}

function checkTimeout(address _member)
public {
    require(timeout(_member), "member still got time to withdraw");
    require(_member != address(devTeamContract), "no right");
    uint256 _curBalance = balance[_member];
    uint256 _refIncome = collectRef(_member);
    uint256 _divIncome = collectDividends(_member);
    uint256 _rewardIncome = collectReward(_member);
    donateSum[_member] += _refIncome + _divIncome + _rewardIncome;
    balance[_member] = _curBalance;
    f2mContract.pushDividends.value(_divIncome + _rewardIncome)();
    citizenContract.pushRefIncome.value(_refIncome)(0x0);
}

function lotteryReinvest(string _sSalt, uint256 _amount)
public
payable {
    address _sender = msg.sender;
    uint256 _deposit = msg.value;
    uint256 _curBalance = balance[_sender];
    uint256 investAmount;
    uint256 collected = 0;
    if (_deposit == 0) {
        if (_amount > balance[_sender])
            collected = collectIncome(_sender);
        require(_amount <= _curBalance + collected, "balance not enough");
        investAmount = _amount; 
    } else {
        collected = collectIncome(_sender);
        investAmount = _deposit.add(_curBalance).add(collected);
    }
    balance[_sender] = _curBalance.add(collected + _deposit).sub(investAmount);
    lastClaim[_sender] = block.timestamp;
    lotteryContract.buyFor.value(investAmount)(_sSalt, _sender);
}

