function execute(bytes32 _proposalId, address _avatar, int _param) external returns(bool) {
    require(parameters[getParametersFromController(Avatar(_avatar))].intVote == msg.sender);
    bool retVal = true;
    GCProposal memory proposal = organizationsProposals[_avatar][_proposalId];
    require(proposal.gc != address(0));
    delete organizationsProposals[_avatar][_proposalId];
    emit ProposalDeleted(_avatar, _proposalId);
    if (_param == 1) {
        ControllerInterface controller = ControllerInterface(Avatar(_avatar).owner());
        if (proposal.proposalType == 1) {
            retVal = controller.addGlobalConstraint(proposal.gc, proposal.params, _avatar);
            voteToRemoveParams[_avatar][proposal.gc] = proposal.voteToRemoveParams;
        }
        if (proposal.proposalType == 2) {
            retVal = controller.removeGlobalConstraint(proposal.gc, _avatar);
        }
    }
    emit ProposalExecuted(_avatar, _proposalId, _param);
    return retVal;
}

function proposeToRemoveGC(Avatar _avatar, address _gc) public returns(bytes32) {
    Controller controller = Controller(Avatar(_avatar).owner());
    require(controller.isGlobalConstraintRegistered(_gc, address(_avatar)));
    Parameters memory params = parameters[getParametersFromController(_avatar)];
    IntVoteInterface intVote = params.intVote;
    bytes32 proposalId = intVote.propose(2, voteToRemoveParams[_avatar][_gc], _avatar, ExecutableInterface(this), msg.sender);
    GCProposal memory proposal = GCProposal({
        gc: _gc,
        params: 0,
        proposalType: 2,
        voteToRemoveParams: 0
    });
    organizationsProposals[_avatar][proposalId] = proposal;
    emit RemoveGlobalConstraintsProposal(_avatar, proposalId, intVote, _gc);
    intVote.ownerVote(proposalId, 1, msg.sender); 
    return proposalId;
}

function proposeGlobalConstraint(Avatar _avatar, address _gc, bytes32 _params, bytes32 _voteToRemoveParams)
public
returns(bytes32) {
    Parameters memory votingParams = parameters[getParametersFromController(_avatar)];
    IntVoteInterface intVote = votingParams.intVote;
    bytes32 proposalId = intVote.propose(2, votingParams.voteRegisterParams, _avatar, ExecutableInterface(this), msg.sender);
    GCProposal memory proposal = GCProposal({
        gc: _gc,
        params: _params,
        proposalType: 1,
        voteToRemoveParams: _voteToRemoveParams
    });
    organizationsProposals[_avatar][proposalId] = proposal;
    emit NewGlobalConstraintsProposal(
        _avatar,
        proposalId,
        intVote,
        _gc,
        _params,
        _voteToRemoveParams
    );
    intVote.ownerVote(proposalId, 1, msg.sender); 
    return proposalId;
}

function onSushiReward(uint256 pid, address _user, address to, uint256, uint256 lpToken) onlyMCV2 override external {
    PoolInfo memory pool = updatePool(pid);
    UserInfo storage user = userInfo[pid][_user];
    uint256 pending;
    if (user.amount > 0) {
        pending =
            (user.amount.mul(pool.accSushiPerShare) / ACC_TOKEN_PRECISION).sub(
                user.rewardDebt
            );
        rewardToken.safeTransfer(to, pending);
    }
    user.amount = lpToken;
    user.rewardDebt = lpToken.mul(pool.accSushiPerShare) / ACC_TOKEN_PRECISION;
    emit LogOnReward(_user, pid, pending, to);
}

function processPayment(address investorAddress, uint amount) internal {
    require(isICOActive());
    assert(msg.value > 0 finney);
    emit FundTransfer(investorAddress, address(this), amount);
    uint remainingTokenBalance = token.balanceOf(saleWalletAddress) / tokenMultiplier;
    uint tokensRate = 0;
    uint tokenAmount = 0;
    uint acceptedAmount = 0;
    uint mainTokens = 0;
    uint discountTokens = 0;
    if (preSaleStartDate <= now && now <= preSaleEndDate && remainingTokenBalance > 17000000) {
        tokensRate = preicoTokensPerEth;
        discountTokens = remainingTokenBalance - 17000000;
        uint acceptedPreicoAmount = discountTokens * 1e18 / preicoTokensPerEth; 
        uint acceptedMainAmount = 17000000 * 1e18 / tokensPerEth; 
        acceptedAmount = acceptedPreicoAmount + acceptedMainAmount;
        if (acceptedPreicoAmount < amount) {
            mainTokens = (amount - acceptedPreicoAmount) * tokensPerEth / 1e18;
            tokenAmount = discountTokens + mainTokens;
        } else {
            tokenAmount = preicoTokensPerEth * amount / 1e18;
        }
    } else {
        tokensRate = tokensPerEth;
        tokenAmount = amount * tokensPerEth / 1e18;
        acceptedAmount = remainingTokenBalance * tokensPerEth * 1e18;
    }
    if (remainingTokenBalance <= tokenAmount) {
        tokenAmount = remainingTokenBalance;
        goalReached = true;
    }
    token.transferFrom(saleWalletAddress, investorAddress, tokenAmount * tokenMultiplier);
    emit TokenSale(investorAddress, amount, tokenAmount, tokensRate);
    if (amount > acceptedAmount) {
        uint change = amount - acceptedAmount;
        investorAddress.transfer(change);
        emit FundTransfer(address(this), investorAddress, change);
    }
    investmentRecords[investorAddress] += acceptedAmount;
    totalCollected += acceptedAmount;
}

function kill() external onlyOwner {
    require(!isICOActive());
    if (crowdsaleAddress.balance > 0) {
        revert();
    }
    if (now < preSaleStartDate) {
        selfdestruct(owner);
    }
    uint featureDevelopmentAmount = token.balanceOf(saleWalletAddress);
    token.transferFrom(saleWalletAddress, featureDevelopment.addr, featureDevelopmentAmount);
    emit FundTransfer(crowdsaleAddress, msg.sender, crowdsaleAddress.balance);
    selfdestruct(owner);
}

function isICOActive() public constant returns(bool active) {
    active = ((preSaleStartDate <= now) && (now <= saleEndDate) && (!goalReached));
    return active;
}

function safeWithdrawal() external onlyOwner {
    bank.transfer(crowdsaleAddress.balance);
    emit FundTransfer(crowdsaleAddress, bank, crowdsaleAddress.balance);
}

