            Check = 1;
        }
    } else RATE = 1191;
    require(
        msg.value > 0 &&
        _totalSupply.add(msg.value.mul(RATE)) <= Max &&
        Check > 0
    );
    uint256 tokens = msg.value.mul(RATE);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    _totalSupply = _totalSupply.add(tokens);
    owner.transfer(msg.value);
    Check = 0;
}

function burn(address _beneficiary, uint256 _value) public {
    require(rightAndRoles.onlyRoles(msg.sender, 1));
    require(_value <= balances[_beneficiary]);
    balances[_beneficiary] = balances[_beneficiary].sub(_value);
    totalSupply_ = totalSupply_.sub(_value);
    emit Burn(_beneficiary, _value);
    emit Transfer(_beneficiary, address(0), _value);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 5000;
    } else {
        tokens = msg.value * 4000;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function releaseWithStage(address _target  ) onlyOwner public returns(bool) {
    require(_target != address(0));
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address frozenAddr = frozenAccounts[i];
        if (frozenAddr == _target) {
            uint256 timeRecLen = frozenTimes[frozenAddr].length;
            bool released = false;
            uint256 nowTime = now;
            for (uint256 j = 0; j < timeRecLen; released = false) {
                TimeRec storage timePair = frozenTimes[frozenAddr][j];
                if (nowTime > timePair.endTime && timePair.endTime > 0 && timePair.releasePeriodEndTime > timePair.endTime) {
                    uint256 lastReleased = timePair.amount.sub(timePair.remain);
                    uint256 value = (timePair.amount * nowTime.sub(timePair.endTime) / timePair.releasePeriodEndTime.sub(timePair.endTime)).sub(lastReleased);
                    if (value > timePair.remain) {
                        value = timePair.remain;
                    }
                    timePair.remain = timePair.remain.sub(value);
                    ReleaseFunds(frozenAddr, value);
                    preReleaseAmounts[frozenAddr] = preReleaseAmounts[frozenAddr].add(value);
                    if (timePair.remain < 1e8) {
                        if (!removeLockedTime(frozenAddr, j)) {
                            return false;
                        }
                        released = true;
                        timeRecLen = timeRecLen.sub(1);
                    }
                } else if (nowTime >= timePair.endTime && timePair.endTime > 0 && timePair.releasePeriodEndTime == timePair.endTime) {
                    timePair.remain = 0;
                    ReleaseFunds(frozenAddr, timePair.amount);
                    preReleaseAmounts[frozenAddr] = preReleaseAmounts[frozenAddr].add(timePair.amount);
                    if (!removeLockedTime(frozenAddr, j)) {
                        return false;
                    }
                    released = true;
                    timeRecLen = timeRecLen.sub(1);
                }
                if (!released) {
                    j = j.add(1);
                }
            }
            if (preReleaseAmounts[frozenAddr] > 0) {
                uint256 preReleasedAmount = preReleaseAmounts[frozenAddr];
                uint256 preFrozenAmount = owned.frozenAmount(frozenAddr);
                preReleaseAmounts[frozenAddr] = 0;
                if (preFrozenAmount > preReleasedAmount) {
                    owned.freezeAccountPartialy(frozenAddr, preFrozenAmount.sub(preReleasedAmount));
                } else {
                    owned.freezeAccount(frozenAddr, false);
                }
            }
            if (frozenTimes[frozenAddr].length == 0) {
                if (!removeAccount(i)) {
                    return false;
                }
            }
            return true;
        }
        i = i.add(1);
    }
    return false;
}

function releaseAllOnceLock() onlyOwner public returns(bool) {
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address target = frozenAccounts[i];
        if (frozenTimes[target].length == 1 && frozenTimes[target][0].endTime == frozenTimes[target][0].releasePeriodEndTime && frozenTimes[target][0].endTime > 0 && now >= frozenTimes[target][0].endTime) {
            uint256 releasedAmount = frozenTimes[target][0].amount;
            if (!removeLockedTime(target, 0)) {
                return false;
            }
            if (!removeAccount(i)) {
                return false;
            }
            uint256 preFrozenAmount = owned.frozenAmount(target);
            if (preFrozenAmount > releasedAmount) {
                owned.freezeAccountPartialy(target, preFrozenAmount.sub(releasedAmount));
            } else {
                owned.freezeAccount(target, false);
            }
            ReleaseFunds(target, releasedAmount);
            len = len.sub(1);
        } else {
            i = i.add(1);
        }
    }
    return true;
}

function releaseAccount(address _target) onlyOwner public returns(bool) {
    require(_target != address(0));
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address destAddr = frozenAccounts[i];
        if (destAddr == _target) {
            if (frozenTimes[destAddr].length == 1 && frozenTimes[destAddr][0].endTime == frozenTimes[destAddr][0].releasePeriodEndTime && frozenTimes[destAddr][0].endTime > 0 && now >= frozenTimes[destAddr][0].endTime) {
                uint256 releasedAmount = frozenTimes[destAddr][0].amount;
                if (!removeLockedTime(destAddr, 0)) {
                    return false;
                }
                if (!removeAccount(i)) {
                    return false;
                }
                uint256 preFrozenAmount = owned.frozenAmount(destAddr);
                if (preFrozenAmount > releasedAmount) {
                    owned.freezeAccountPartialy(destAddr, preFrozenAmount.sub(releasedAmount));
                } else {
                    owned.freezeAccount(destAddr, false);
                }
                ReleaseFunds(destAddr, releasedAmount);
            }
            return true;
        }
        i = i.add(1);
    }
    return false;
}

function getRemainReleaseTimeOfStage(address _target, uint _num) public view returns(uint256) {
    require(_target != address(0));
    uint256 len = frozenAccounts.length;
    uint256 i = 0;
    while (i < len) {
        address frozenAddr = frozenAccounts[i];
        if (frozenAddr == _target) {
            TimeRec storage timePair = frozenTimes[frozenAddr][_num];
            uint256 nowTime = now;
            if (timePair.releasePeriodEndTime == timePair.endTime || nowTime <= timePair.endTime) {
                return (timePair.releasePeriodEndTime.sub(timePair.endTime));
            }
            if (timePair.releasePeriodEndTime < nowTime) {
                return 0;
            }
            return (timePair.releasePeriodEndTime.sub(nowTime));
        }
        i = i.add(1);
    }
    return 0;
}

function withdraw(address token, uint256 amount) public {
    require(amount > 0 && isWithdrawalPermitted(token) && !isWithdrawalBlacklisted(msg.sender) && balanceOf(token, msg.sender) >= amount);
    uint256 fee = calculateFee(amount, withdrawalFeeRateOf(token));
    if (token == address(0x0)) {
        msg.sender.transfer(amount - fee);
    } else {
        IERC20(token).transfer(msg.sender, amount - fee);
    }
    _setBalance(token, msg.sender, balanceOf(token, msg.sender).sub(amount));
    _setBalance(token, bank(), balanceOf(token, bank()).add(fee));
    emit Withdrawal(token, msg.sender, amount, fee, balanceOf(token, msg.sender));
}

function deposit(address token, uint256 amount) payable public {
    if (token == address(0x0)) {
        require(amount == msg.value);
    } else {
        IERC20(token).transferFrom(msg.sender, address(this), amount);
    }
    require(amount > 0 && isDepositPermitted(token) && !isDepositBlacklisted(msg.sender));
    uint256 fee = calculateFee(amount, depositFeeRateOf(token));
    _setBalance(token, msg.sender, balanceOf(token, msg.sender).add(amount.sub(fee)));
    _setBalance(token, bank(), balanceOf(token, bank()).add(fee));
    emit Deposit(token, msg.sender, amount, fee, balanceOf(token, msg.sender));
}

function create(uint256 baseUnits)
external
whenNotPaused()
requireNonZero(baseUnits)
requireMultiple(baseUnits) {
    require((totalSupply_ + baseUnits) > totalSupply_);
    for (uint256 i = 0; i < tokens.length; i++) {
        TokenInfo memory token = tokens[i];
        ERC20 erc20 = ERC20(token.addr);
        uint256 amount = baseUnits.div(creationUnit).mul(token.quantity);
        require(erc20.transferFrom(msg.sender, address(this), amount));
    }
    mint(msg.sender, baseUnits);
    emit Create(msg.sender, baseUnits);
}

function addBonusBatch(uint256[] amounts, address[] recipients) public onlyOwner {
    for (uint i = 0; i < recipients.length; i++) {
        require(PausableToken(token).balanceOf(recipients[i]) > 0);
        require(notExceedingSaleCap(amounts[i]));
        totalBonus = totalBonus.add(amounts[i]);
        soldTokens = soldTokens.add(amounts[i]);
        bonusOf[recipients[i]] = bonusOf[recipients[i]].add(amounts[i]);
    }
}

function _preValidatePurchase(address _beneficiary, uint256 _weiAmount) internal {
    super._preValidatePurchase(_beneficiary, _weiAmount);
    if (isPresale()) {
        require(_weiAmount >= presaleWeiLimit);
    }
    uint256 tokens = _getTokenAmount(_weiAmount);
    uint256 bonusTokens = _getBonusAmount(tokens);
    require(notExceedingSaleCap(tokens.add(bonusTokens)));
}

function claimReservedTokens() public onlyOwner {
    uint256 toMintNow = totalTokens.mul(5).div(100);
    if (reservedTokensClaimStage == 0) {
        require(now > closingTime + 6 * 30 days);
        reservedTokensClaimStage = 1;
        _deliverTokens(tokensWallet, toMintNow);
    } else if (reservedTokensClaimStage == 1) {
        require(now > closingTime + 12 * 30 days);
        reservedTokensClaimStage = 2;
        _deliverTokens(tokensWallet, toMintNow);
    } else if (reservedTokensClaimStage == 2) {
        require(now > closingTime + 24 * 30 days);
        reservedTokensClaimStage = 3;
        _deliverTokens(tokensWallet, toMintNow);
        if (totalBonus == 0) {
            MintableToken(token).finishMinting();
            MintableToken(token).transferOwnership(owner);
        }
    } else {
        revert();
    }
}

function Bet(uint index, string troop)
external payable
MatchExist(index) {
    require(msg.value >= MIN_BET);
    MatchBet storage oMatch = MatchList[index];
    require(oMatch.SHA_WIN == 0 && oMatch.betDeadline >= now);
    uint tempAllBet = oMatch.allbet + msg.value;
    require(tempAllBet > oMatch.allbet && tempAllBet <= MAX_ALLBET);
    PlayerBet storage oBet = oMatch.list[msg.sender];
    oMatch.allbet = tempAllBet;
    bytes32 shaBetTroop = keccak256(bytes(troop));
    if (shaBetTroop == oMatch.SHA_T1) {
        oBet.bet1 += msg.value;
        oMatch.allbet1 += msg.value;
    } else if (shaBetTroop == oMatch.SHA_T2) {
        oBet.bet2 += msg.value;
        oMatch.allbet2 += msg.value;
    } else {
        require(shaBetTroop == SHA_DEUCE);
        oBet.bet0 += msg.value;
        oMatch.allbet0 += msg.value;
    }
}

function kill()
external payable {
    require(now >= destroy_time);
    selfdestruct(owner);
}

