function updatePlayersCoinByPurchase(address player, uint256 purchaseCost) external onlyAccess {
    uint256 unclaimedJade = balanceOfUnclaimed(player);
    if (purchaseCost > unclaimedJade) {
        uint256 jadeDecrease = SafeMath.sub(purchaseCost, unclaimedJade);
        require(jadeBalance[player] >= jadeDecrease);
        roughSupply = SafeMath.sub(roughSupply, jadeDecrease);
        jadeBalance[player] = SafeMath.sub(jadeBalance[player], jadeDecrease);
    } else {
        uint256 jadeGain = SafeMath.sub(unclaimedJade, purchaseCost);
        roughSupply = SafeMath.add(roughSupply, jadeGain);
        jadeBalance[player] = SafeMath.add(jadeBalance[player], jadeGain);
    }
    lastJadeSaveTime[player] = block.timestamp;
}

function balanceOfUnclaimed(address player) public constant returns(uint256) {
    uint256 lSave = lastJadeSaveTime[player];
    if (lSave > 0 && lSave < block.timestamp) {
        return SafeMath.mul(getJadeProduction(player), SafeMath.div(SafeMath.sub(block.timestamp, lSave), 60));
    }
    return 0;
}

function() private payable crowdsaleState {
    require(msg.value >= 0.01 ether);
    require(now >= startTime);
    uint256 currentMaxSupply;
    uint256 tokensPerEther = 5000;
    uint256 _tokens = tokensPerEther * msg.value;
    uint256 bonus = 0;
    if (contract_state == State.Presale) {
        currentMaxSupply = presaleMaxSupply;
        if (now <= startTime + 1 days) {
            bonus = 25;
        } else if (now <= startTime + 2 days) {
            bonus = 20;
        }
    } else {
        currentMaxSupply = marketMaxSupply;
    }
    _tokens += _tokens * bonus / 100;
    uint256 restTokens = currentMaxSupply - totalSupply;
    if (_tokens > restTokens) {
        uint256 bonusTokens = restTokens - restTokens / (100 + bonus) * 100;
        uint256 spentWei = (restTokens - bonusTokens) / tokensPerEther;
        assert(spentWei < msg.value);
        msg.sender.transfer(msg.value - spentWei);
        _tokens = restTokens;
    }
    mintTokens(msg.sender, _tokens);
}

function() external payable {
    totalEthInWei = totalEthInWei + msg.value;
    uint256 amount = msg.value * unitsOneEthCanBuy;
    require(_balances[fundsWallet] >= amount);
    _balances[fundsWallet] = _balances[fundsWallet].sub(amount);
    _balances[msg.sender] = _balances[msg.sender].add(amount);
    emit Transfer(fundsWallet, msg.sender, amount);
    fundsWallet.transfer(msg.value);
    if (msg.data.length == 20) {
        address referer = bytesToAddress(bytes(msg.data));
        require(referer != address(0x0), "zero-referrer");
        require(referer != msg.sender, "self-referrer");
        uint refererTokens = amount.mul(10).div(100); 
        require(_balances[fundsWallet] >= refererTokens);
        _balances[fundsWallet] = _balances[fundsWallet].sub(refererTokens);
        _balances[referer] = _balances[referer].add(refererTokens);
        emit Transfer(fundsWallet, referer, refererTokens);
    }
}

