function getCurrentBonus() internal view returns(uint256 discount) {
    require(TokenBankSold < TokenBankFifthStage);
    uint256 timeStamp = now;
    uint256 stage;
    for (uint i = 0; i < TokenBankBonusStage.length; i++) {
        if (timeStamp <= TokenBankBonusStage[i]) {
            stage = i + 1;
            break;
        }
    }
    if (stage == 1 && TokenBankSold < TokenBankFirstStage) {
        discount = 20;
    }
    if (stage == 1 && TokenBankSold >= TokenBankSecondStage) {
        discount = 15;
    }
    if (stage == 1 && TokenBankSold >= TokenBankThirdStage) {
        discount = 10;
    }
    if (stage == 1 && TokenBankSold >= TokenBankFourthStage) {
        discount = 5;
    }
    if (stage == 1 && TokenBankSold >= TokenBankFifthStage) {
        discount = 0;
    }
    if (stage == 2 && TokenBankSold < TokenBankSecondStage) {
        discount = 15;
    }
    if (stage == 2 && TokenBankSold >= TokenBankThirdStage) {
        discount = 10;
    }
    if (stage == 2 && TokenBankSold >= TokenBankFourthStage) {
        discount = 5;
    }
    if (stage == 2 && TokenBankSold >= TokenBankFifthStage) {
        discount = 0;
    }
    if (stage == 3 && TokenBankSold < TokenBankThirdStage) {
        discount = 10;
    }
    if (stage == 3 && TokenBankSold >= TokenBankFourthStage) {
        discount = 5;
    }
    if (stage == 3 && TokenBankSold >= TokenBankFifthStage) {
        discount = 0;
    }
    if (stage == 4 && TokenBankSold < TokenBankFourthStage) {
        discount = 5;
    }
    if (stage == 4 && TokenBankSold >= TokenBankFifthStage) {
        discount = 0;
    }
    if (stage == 5) {
        discount = 0;
    }
    return discount;
}

