function GetTreeByUserId(uint32 UserId, bool report) view public returns(User[]) {
    uint32 userposition = uint32(userlistbyid[uint32(UserId)].Position);
    uint userCount = 0;
    if (report) {
        userCount = uint((2 ** (uint(currentLevel) + 1)) - 1);
    } else {
        userCount = 15;
    }
    User[] memory userlist = new User[](userCount);
    uint counter = 0;
    uint32 availablenodes = 2;
    int8 userlevel = 2;
    userlist[counter] = userlistbyid[uint32(userlistbypos[userposition].Id)];
    counter++;
    while (true) {
        userposition = userposition * 2;
        for (uint32 i = 0; i < availablenodes; i++) {
            userlist[counter] = userlistbyid[uint32(userlistbypos[userposition + i].Id)];
            counter++;
        }
        availablenodes = availablenodes * 2;
        userlevel++;
        if (report == false) {
            if (availablenodes > 8) {
                break;
            }
        } else {
            if (userlevel > currentLevel) {
                break;
            }
        }
    }
    return userlist;
}

function depositTokens(
    uint32 uplineId
) internal returns(bool success) {
    require(token != 0x0);
    address from_ = msg.sender;
    if (investamt > ERC20Interface.allowance(from_, address(this))) {
        emit TransferFailed(from_, keeper, investamt);
        revert();
    }
    ERC20Interface.transferFrom(from_, address(this), investamt);
    emit TransferSuccessful(from_, address(this), investamt);
    if (nextPosition != 1) {
        ERC20Interface.transfer(userlistbyid[uplineId].OwnerAddress, referralamt);
    }
    MainterPayoutAmount = MainterPayoutAmount + maintaineramt;
    UnpaidUserCount++;
    return true;
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingDivs(account);
    require(TOTAL_REWARD_AVAILABLE > 0, 'reward is drained');
    if (pendingDivs > TOTAL_REWARD_AVAILABLE) {
        pendingDivs = TOTAL_REWARD_AVAILABLE;
    }
    if (pendingDivs > 0) {
        require(token.transfer(account, pendingDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        TOTAL_REWARD_AVAILABLE.sub(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
}

function deposit(uint amountToStake) public {
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    require(token.transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint fee = amountToStake.mul(stakingFeeRate).div(1e4);
    uint amountAfterFee = amountToStake.sub(fee);
    require(token.transfer(owner, fee), "Could not transfer deposit fee.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function withdraw(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    require(now.sub(stakingTime[msg.sender]) > cliffTime, "You recently staked, please wait before withdrawing.");
    updateAccount(msg.sender);
    uint fee = amountToWithdraw.mul(unstakingFeeRate).div(1e4);
    uint amountAfterFee = amountToWithdraw.sub(fee);
    require(token.transfer(owner, fee), "Could not transfer withdraw fee.");
    require(token.transfer(msg.sender, amountAfterFee), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function adminWithdraw(address[3] addresses, uint256[3] values, uint8 v, bytes32 r, bytes32 s)
public
onlyAdmin
isFeeAccount(addresses[2]) {
    address user = addresses[0];
    address token = addresses[1];
    address feeAccount = addresses[2];
    uint256 amount = values[0];
    uint256 nonce = values[1];
    uint256 fee = values[2];
    require(amount <= tokenList[token][user]);
    fee = checkFee(amount, fee);
    bytes32 hash = keccak256(this, user, token, amount, nonce);
    require(!withdrawn[hash]);
    withdrawn[hash] = true;
    require(ecrecover(keccak256("\x19Ethereum Signed Message:\n32", hash), v, r, s) == user);
    tokenList[token][user] = safeSub(tokenList[token][user], amount);
    tokenList[token][feeAccount] = safeAdd(tokenList[token][feeAccount], fee);
    amount = safeSub(amount, fee);
    if (token == 0) { 
        require(user.send(amount));
    } else { 
        require(Token(token).transfer(user, amount));
    }
    Withdraw(token, user, amount, tokenList[token][user]);
}

