function canSetBanker() public view returns(bool _result) {
    _result = false;
    if (now < bankerEndTime) {
        return;
    }
    if (userEtherOf[this] == 0) {
        _result = true;
    }
}

function newGame(string _team1, string _team2, uint _loseOdd, uint _winOdd, uint _sameOdd, uint _betLastTime, uint256 _gameMinBetAmount, uint256 _gameMaxBetAmount) public onlyBanker payable returns(bool _result) {
    if (msg.value > 0) {
        userEtherOf[msg.sender] = userEtherOf[msg.sender].add(msg.value);
    }
    require(bytes(_team1).length < 100);
    require(bytes(_team2).length < 100);
    require(gameOver);
    require(now > bankerBeginTime);
    require(_gameMinBetAmount >= 100000000000000);
    require(_gameMaxBetAmount >= _gameMinBetAmount);
    require(now < _betLastTime);
    require(_betLastTime + 1 days < bankerEndTime);
    _result = _newGame(_team1, _team2, _loseOdd, _winOdd, _sameOdd, _betLastTime, _gameMinBetAmount, _gameMaxBetAmount);
}

function _openGamePlayNo(uint _playNo) private returns(bool _result) {
    _result = false;
    require(_playNo >= gameBeginPlayNo && _playNo < playNo);
    _checkOpenGame();
    betInfo storage p = playerBetInfoOf[_playNo];
    require(!p.IsReturnAward);
    uint256 allAmount = 0;
    _cashPrize(p, allAmount, _playNo);
    _setGameOver();
    _result = true;
}

function failUserRefund(uint[] _playNos) public returns(bool _result) {
    _result = false;
    require(!gameOver);
    require(gameResult == 9);
    require(betLastTime + 31 days < now);
    for (uint _index = 0; _index < _playNos.length; _index++) {
        uint _playNo = _playNos[_index];
        if (_playNo >= gameBeginPlayNo && _playNo < playNo) {
            betInfo storage p = playerBetInfoOf[_playNo];
            if (!p.IsReturnAward) {
                p.IsReturnAward = true;
                uint256 ToUser = p.BetAmount;
                userEtherOf[this] = userEtherOf[this].sub(ToUser);
                userEtherOf[p.Player] = userEtherOf[p.Player].add(ToUser);
            }
        }
    }
    if (msg.sender == currentBanker && bankerAllDeposit > 0) {
        userEtherOf[this] = userEtherOf[this].sub(bankerAllDeposit);
        userEtherOf[currentBanker] = userEtherOf[currentBanker].add(bankerAllDeposit);
        bankerAllDeposit = 0;
    }
    if (userEtherOf[this] == 0) {
        gameOver = true;
    }
    _result = true;
}

function _checkOpenGame() private view {
    require(!gameOver);
    require(gameResult == loseNum || gameResult == winNum || gameResult == sameNum);
    require(betLastTime + 90 minutes < now);
}

function _play(uint _betNum, uint256 _betAmount) private returns(bool _result) {
    _result = false;
    require(!gameOver);
    require(loseNum == _betNum || _betNum == winNum || _betNum == sameNum);
    require(msg.sender != currentBanker);
    require(now < betLastTime);
    require(_betAmount >= gameMinBetAmount);
    if (_betAmount > gameMaxBetAmount) {
        _betAmount = gameMaxBetAmount;
    }
    _betAmount = _betAmount / 100 * 100;
    uint _odd = _seekOdd(_betNum, _betAmount);
    require(userEtherOf[msg.sender] >= _betAmount);
    betInfo memory bi = betInfo({
        Odd: _odd,
        Player: msg.sender,
        BetNum: _betNum,
        BetAmount: _betAmount,
        BetTime: now,
        IsReturnAward: false,
        ResultNO: 9
    });
    playerBetInfoOf[playNo] = bi;
    userEtherOf[msg.sender] = userEtherOf[msg.sender].sub(_betAmount);
    userEtherOf[this] = userEtherOf[this].add(_betAmount);
    uint _maxpooling = _getMaxPooling();
    if (userEtherOf[this] < _maxpooling) {
        uint BankerAmount = _maxpooling.sub(userEtherOf[this]);
        require(userEtherOf[currentBanker] >= BankerAmount);
        userEtherOf[currentBanker] = userEtherOf[currentBanker].sub(BankerAmount);
        userEtherOf[this] = userEtherOf[this].add(BankerAmount);
        bankerAllDeposit = bankerAllDeposit.add(BankerAmount);
    }
    emit OnPlay(gameID, playNo, msg.sender, gameName, _odd, team1, _betNum, _betAmount, now, getEventId());
    playNo = playNo.add(1);
    _result = true;
}

function setBanker(address _banker, uint _beginTime, uint _endTime) public onlyAuction returns(bool _result) {
    _result = false;
    require(_banker != 0x0);
    if (now < bankerEndTime) {
        emit OnSetNewBanker(gameID, msg.sender, _banker, _beginTime, _endTime, 1, now, getEventId());
        return;
    }
    if (userEtherOf[this] > 0) {
        emit OnSetNewBanker(gameID, msg.sender, _banker, _beginTime, _endTime, 5, now, getEventId());
        return;
    }
    if (_beginTime > now) {
        emit OnSetNewBanker(gameID, msg.sender, _banker, _beginTime, _endTime, 3, now, getEventId());
        return;
    }
    if (_endTime <= now) {
        emit OnSetNewBanker(gameID, msg.sender, _banker, _beginTime, _endTime, 4, now, getEventId());
        return;
    }
    currentBanker = _banker;
    bankerBeginTime = _beginTime;
    bankerEndTime = _endTime;
    unpayPooling = 0;
    losePooling = 0;
    winPooling = 0;
    samePooling = 0;
    bankerAllDeposit = 0;
    gameResult = 9;
    gameOver = true;
    emit OnSetNewBanker(gameID, msg.sender, _banker, _beginTime, _endTime, 0, now, getEventId());
    _result = true;
}

function setGameResult(uint _gameResult) public onlyDecider {
    require(!gameOver);
    require(betLastTime + 90 minutes < now);
    require(now < betLastTime + 30 days);
    require(gameResult == 9);
    require(_gameResult == loseNum || _gameResult == winNum || _gameResult == sameNum);
    gameResult = _gameResult;
    if (gameResult == 3) {
        unpayPooling = winPooling;
    } else if (gameResult == 1) {
        unpayPooling = losePooling;
    } else if (gameResult == 0) {
        unpayPooling = samePooling;
    }
}

function _userRefund(address _to) internal returns(bool _result) {
    require(_to != 0x0);
    require(_to != currentBanker || gameOver);
    lock();
    uint256 amount = userEtherOf[_to];
    if (amount > 0) {
        userEtherOf[msg.sender] = 0;
        _to.transfer(amount);
        _result = true;
    } else {
        _result = false;
    }
    emit OnRefund(gameID, _to, amount, _result, now, getEventId());
    unLock();
}

function _flashloan(
    uint256 handlerID,
    address receiverAddress,
    uint256 amount,
    bytes calldata params
) internal returns(bool) {
    ContractInfo memory handlerInfo;
    (handlerInfo.support, handlerInfo.addr) = dataStorageInstance.getTokenHandlerInfo(handlerID);
    require(handlerInfo.support);
    handlerInfo.tokenHandler = IProxy(handlerInfo.addr);
    IFlashloanReceiver receiver = IFlashloanReceiver(receiverAddress);
    bool success;
    uint256 fee = _getFee(handlerID, amount);
    (handlerInfo.tokenAddr, handlerInfo.expectedBalance) = _getThisBalance(handlerInfo, handlerID);
    handlerInfo.expectedBalance = handlerInfo.expectedBalance.add(_convertUnifiedToUnderlying(handlerInfo, amount)).add(_convertUnifiedToUnderlying(handlerInfo, fee));
    (success, handlerInfo.data) = handlerInfo.tokenHandler.handlerProxy(
        abi.encodeWithSelector(
            handlerInfo.handlerFunction
            .executeFlashloan.selector,
            receiverAddress,
            amount
        )
    );
    require(success);
    success = receiver.executeOperation(handlerInfo.tokenAddr, _convertUnifiedToUnderlying(handlerInfo, amount), _convertUnifiedToUnderlying(handlerInfo, fee), params);
    require(success);
    (, handlerInfo.afterBalance) = _getThisBalance(handlerInfo, handlerID);
    require(handlerInfo.expectedBalance <= handlerInfo.afterBalance);
    if (handlerID == 0) { 
        if (handlerInfo.expectedBalance < handlerInfo.afterBalance) {
            msg.sender.transfer(handlerInfo.afterBalance.sub(handlerInfo.expectedBalance));
        }
        payable(handlerInfo.addr).transfer(handlerInfo.expectedBalance);
    } else { 
        IERC20 token = IERC20(handlerInfo.tokenAddr);
        if (handlerInfo.afterBalance > handlerInfo.expectedBalance) {
            token.transfer(msg.sender, handlerInfo.afterBalance.sub(handlerInfo.expectedBalance));
        }
        token.transfer(handlerInfo.addr, handlerInfo.expectedBalance);
    }
    handlerFlashloan[handlerID].feeTotal = handlerFlashloan[handlerID].feeTotal.add(fee);
    (success, handlerInfo.data) = handlerInfo.tokenHandler.handlerProxy(
        abi.encodeWithSelector(
            handlerInfo.handlerFunction
            .depositFlashloanFee.selector,
            fee
        )
    );
    require(success);
    emit FlashLoan(receiverAddress, handlerInfo.addr, amount, fee);
    return true;
}

function withdrawFlashloanFee(uint256 handlerID) onlyOwner external returns(bool) {
    ContractInfo memory handlerInfo;
    (handlerInfo.support, handlerInfo.addr) = dataStorageInstance.getTokenHandlerInfo(handlerID);
    if (handlerInfo.support) {
        handlerInfo.tokenHandler = IProxy(handlerInfo.addr);
        (bool success, ) = handlerInfo.tokenHandler.handlerProxy(
            abi.encodeWithSelector(
                handlerInfo.handlerFunction
                .withdrawFlashloanFee.selector,
                handlerFlashloan[handlerID].feeTotal
            )
        );
        require(success);
        handlerFlashloan[handlerID].feeTotal = 0;
    }
    return true;
}

function deposit() public payable nonReentrant {
    require(controller != CFETHControllerInterface(0x0) && controller.get_current_pool() != ICurvePoolForETH(0x0), "paused");
    require(msg.value > 0, "CFVault: zero amount");
    require(slip != 0, "Slippage not set");
    uint _amount = msg.value;
    require(_amount <= max_amount, "too large amount");
    if (deposit_fee_ratio != 0 && fee_pool != address(0x0)) {
        uint256 f = _amount.safeMul(deposit_fee_ratio).safeDiv(ratio_base);
        emit CFFDepositFee(msg.sender, _amount, f);
        _amount = _amount.safeSub(f);
        if (f != 0) {
            fee_pool.call.value(f)("");
        }
    }
    uint eth_before = address(this).balance;
    uint vir = controller.get_current_pool().get_virtual_price();
    uint min_amount = _amount.safeMul(uint(1e14)).safeMul(slip).safeDiv(vir);
    uint lp_before = controller.get_current_pool().get_lp_token_balance();
    controller.get_current_pool().deposit.value(_amount)();
    uint eth_after = address(this).balance;
    uint actual_deposit = eth_before - eth_after;
    require(actual_deposit <= _amount, "deposit overflow");
    if (_amount != actual_deposit) {
        msg.sender.call.value(_amount - actual_deposit)("");
    }
    uint lp_after = controller.get_current_pool().get_lp_token_balance();
    uint256 lp_amount = lp_after.safeSub(lp_before);
    require(lp_amount >= min_amount, "Slippage");
    uint256 d = ERC20Base(controller.get_current_pool().get_lp_token_addr()).decimals();
    require(d <= 18, "invalid decimal");
    uint cff_amount = 0;
    if (lp_before == 0) {
        cff_amount = lp_amount.safeMul(uint256(10) ** 18).safeDiv(uint256(10) ** d);
    } else {
        cff_amount = lp_amount.safeMul(IERC20(lp_token).totalSupply()).safeDiv(lp_before);
    }
    TokenInterfaceETH(lp_token).generateTokens(msg.sender, cff_amount);
    emit CFFDeposit(msg.sender, actual_deposit, cff_amount, get_virtual_price());
}

function withdraw(uint256 _amount) public nonReentrant {
    require(controller != CFETHControllerInterface(0x0) && controller.get_current_pool() != ICurvePoolForETH(0x0), "paused");
    require(slip != 0, "Slippage not set");
    uint256 amount = IERC20(lp_token).balanceOf(msg.sender);
    require(amount >= _amount, "no enough LP tokens");
    uint LP_token_amount = _amount.safeMul(controller.get_current_pool().get_lp_token_balance()).safeDiv(IERC20(lp_token).totalSupply());
    uint vir = controller.get_current_pool().get_virtual_price();
    uint min_amount = _amount.safeMul(vir).safeMul(slip).safeDiv(uint(1e22));
    uint256 _before = address(this).balance;
    controller.get_current_pool().withdraw(LP_token_amount);
    uint256 _after = address(this).balance;
    uint256 eth_amount = _after.safeSub(_before);
    require(eth_amount >= min_amount, "Slippage");
    if (withdraw_fee_ratio != 0 && fee_pool != address(0x0)) {
        uint256 f = eth_amount.safeMul(withdraw_fee_ratio).safeDiv(ratio_base);
        uint256 r = eth_amount.safeSub(f);
        TokenInterfaceETH(lp_token).destroyTokens(msg.sender, _amount);
        msg.sender.call.value(r)("");
        fee_pool.call.value(f)("");
        emit CFFWithdraw(msg.sender, r, _amount, f, get_virtual_price());
    } else {
        TokenInterfaceETH(lp_token).destroyTokens(msg.sender, _amount);
        msg.sender.call.value(eth_amount)("");
        emit CFFWithdraw(msg.sender, eth_amount, _amount, 0, get_virtual_price());
    }
}

function forbid(bytes32 src, bytes32 dst, bytes32 sig) public auth {
    acl[src][dst][sig] = false;
    emit LogForbid(src, dst, sig);
}

function permit(bytes32 src, bytes32 dst, bytes32 sig) public auth {
    acl[src][dst][sig] = true;
    emit LogPermit(src, dst, sig);
}

function() payable public {
    uint256 bonus = 0;
    uint256 amount;
    uint256 ethamount = msg.value;
    require(!crowdsaleClosed);
    uint256 onlyAdt = ethamount.div(price);
    uint256 weiAdt = SafeMath.mul(onlyAdt, 100000000000000);
    require(isValidUser(msg.sender, weiAdt));
    balanceOf[msg.sender] = balanceOf[msg.sender].add(ethamount);
    amountRaised = amountRaised.add(ethamount);
    if (now >= preSaleStartdate && now <= preSaleDeadline) {
        amount = ethamount.div(price);
        bonus = amount * 33 / 100;
        amount = amount.add(bonus);
    } else if (now >= mainSaleStartdate && now <= mainSaleStartdate + 30 days) {
        amount = ethamount.div(price);
        bonus = amount * 25 / 100;
        amount = amount.add(bonus);
    } else if (now >= mainSaleStartdate + 30 days && now <= mainSaleStartdate + 45 days) {
        amount = ethamount.div(price);
        bonus = amount * 15 / 100;
        amount = amount.add(bonus);
    } else if (now >= mainSaleStartdate + 45 days && now <= mainSaleStartdate + 60 days) {
        amount = ethamount.div(price);
        bonus = amount * 10 / 100;
        amount = amount.add(bonus);
    } else {
        amount = ethamount.div(price);
        bonus = amount * 7 / 100;
        amount = amount.add(bonus);
    }
    amount = amount.mul(100000000000000);
    tokenReward.transfer(msg.sender, amount);
    tokenSold = tokenSold.add(amount);
    resetUserWhiteListAmount();
    emit FundTransfer(msg.sender, ethamount, true);
}

function safeWithdrawal() public afterDeadline {
    if (returnFunds) {
        uint amount = balanceOf[msg.sender];
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                emit FundTransfer(msg.sender, amount, false);
                balanceOf[msg.sender] = 0;
                fundTransferred = fundTransferred.add(amount);
            }
        }
    }
    if (returnFunds == false && beneficiary == msg.sender) {
        uint256 ethToSend = amountRaised - fundTransferred;
        if (beneficiary.send(ethToSend)) {
            fundTransferred = fundTransferred.add(ethToSend);
        }
    }
}

function getMeOutOfHere() public {
    for (uint8 i = 0; i < 16; i++) {
        sellMyTokens(i);
        withdraw(i);
    }
}

function withdrawOwnerFee() public {
    if (msg.sender == owner) {
        owner.transfer(ownerFee);
        ownerFee = 0;
    }
}

function collectTokens() public onlyOwner {
    uint256 balance = miniMeToken.balanceOf(address(this));
    uint256 total = collectedTokens.add(balance);
    uint256 finalizedTime = crowdsale.finalizedTime();
    require(finalizedTime > 0 && getTime() > finalizedTime.add(months(12)));
    uint256 canExtract = 0;
    if (getTime() <= finalizedTime.add(months(24))) {
        require(collectedTokens < total.percent(40));
        canExtract = total.percent(40);
    } else if (getTime() > finalizedTime.add(months(24)) && getTime() <= finalizedTime.add(months(36))) {
        require(collectedTokens < total.percent(80));
        canExtract = total.percent(80);
    } else {
        canExtract = total;
    }
    canExtract = canExtract.sub(collectedTokens);
    if (canExtract > balance) {
        canExtract = balance;
    }
    collectedTokens = collectedTokens.add(canExtract);
    miniMeToken.transfer(owner, canExtract);
    TokensWithdrawn(owner, canExtract);
}

function transfer_multisig(uint64 id, address _contract) public only_signer
is_majority_sig(id, "transfer_multisig") {
    require(_contract != address(0x0));
    address old = address(multisig_contract);
    multisig_contract = MultiSigInterface(_contract);
    emit TransferMultiSig(old, _contract);
}

function changeRewarder(uint64 id, address _rewarder) public only_signer
is_majority_sig(id, "changeRewarder") {
    address old = address(reward_contract);
    reward_contract = RewardInterface(_rewarder);
    emit ChangeRewarder(old, _rewarder);
}

function setEndsAt(uint time) public onlyOwner {
    assert(!finalized);
    assert(isUpdatable);
    assert(now <= time); 
    assert(startsAt <= time);
    assert(now <= endsAt);
    CrowdsaleExt lastTierCntrct = CrowdsaleExt(getLastTier());
    if (lastTierCntrct.finalized()) revert();
    uint8 tierPosition = getTierPosition(this);
    for (uint8 j = tierPosition + 1; j < joinedCrowdsalesLen; j++) {
        CrowdsaleExt crowdsale = CrowdsaleExt(joinedCrowdsales[j]);
        assert(time <= crowdsale.startsAt());
    }
    endsAt = time;
    emit EndsAtChanged(endsAt);
}

function allocate(address receiver, uint256 tokenAmount, uint128 customerId, uint256 lockedTokenAmount) public onlyAllocateAgent {
    require(lockedTokenAmount <= tokenAmount);
    uint weiPrice = pricingStrategy.oneTokenInWei(tokensSold, token.decimals());
    uint256 weiAmount = (weiPrice * tokenAmount) / 10 ** uint256(token.decimals());
    weiRaised = weiRaised.plus(weiAmount);
    tokensSold = tokensSold.plus(tokenAmount);
    investedAmountOf[receiver] = investedAmountOf[receiver].plus(weiAmount);
    tokenAmountOf[receiver] = tokenAmountOf[receiver].plus(tokenAmount);
    if (lockedTokenAmount > 0) {
        tokenVesting = TokenVesting(tokenVestingAddress);
        require(!tokenVesting.isVestingSet(receiver));
        assignTokens(tokenVestingAddress, lockedTokenAmount);
        tokenVesting.setVestingWithDefaultSchedule(receiver, lockedTokenAmount);
    }
    if (tokenAmount - lockedTokenAmount > 0) {
        assignTokens(receiver, tokenAmount - lockedTokenAmount);
    }
    emit Invested(receiver, weiAmount, tokenAmount, customerId);
}

function finalize() public inState(State.Success) onlyOwner stopInEmergency {
    if (finalized) {
        revert();
    }
    if (address(finalizeAgent) != address(0)) {
        finalizeAgent.finalizeCrowdsale();
    }
    finalized = true;
}

function setStartsAt(uint time) public onlyOwner {
    assert(!finalized);
    assert(isUpdatable);
    assert(now <= time); 
    assert(time <= endsAt);
    assert(now <= startsAt);
    CrowdsaleExt lastTierCntrct = CrowdsaleExt(getLastTier());
    if (lastTierCntrct.finalized()) revert();
    uint8 tierPosition = getTierPosition(this);
    for (uint8 j = 0; j < tierPosition; j++) {
        CrowdsaleExt crowdsale = CrowdsaleExt(joinedCrowdsales[j]);
        assert(time >= crowdsale.endsAt());
    }
    startsAt = time;
    emit StartsAtChanged(startsAt);
}

function investInternal(address receiver, uint128 customerId) private stopInEmergency {
    if (getState() == State.PreFunding) {
        revert();
    } else if (getState() == State.Funding) {
        if (isWhiteListed) {
            if (!earlyParticipantWhitelist[receiver].status) {
                revert();
            }
        }
    } else {
        revert();
    }
    uint weiAmount = msg.value;
    uint tokenAmount = pricingStrategy.calculatePrice(weiAmount, tokensSold, token.decimals());
    if (tokenAmount == 0) {
        revert();
    }
    if (isWhiteListed) {
        if (weiAmount < earlyParticipantWhitelist[receiver].minCap && tokenAmountOf[receiver] == 0) {
            revert();
        }
        if (isBreakingInvestorCap(receiver, weiAmount)) {
            revert();
        }
        updateInheritedEarlyParticipantWhitelist(receiver, weiAmount);
    } else {
        if (weiAmount < token.minCap() && tokenAmountOf[receiver] == 0) {
            revert();
        }
    }
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    investedAmountOf[receiver] = investedAmountOf[receiver].plus(weiAmount);
    tokenAmountOf[receiver] = tokenAmountOf[receiver].plus(tokenAmount);
    weiRaised = weiRaised.plus(weiAmount);
    tokensSold = tokensSold.plus(tokenAmount);
    if (isBreakingCap(tokensSold)) {
        revert();
    }
    assignTokens(receiver, tokenAmount);
    if (!multisigWallet.send(weiAmount)) revert();
    emit Invested(receiver, weiAmount, tokenAmount, customerId);
}

function setMaximumSellableTokens(uint tokens) public onlyOwner {
    assert(!finalized);
    assert(isUpdatable);
    assert(now <= startsAt);
    CrowdsaleExt lastTierCntrct = CrowdsaleExt(getLastTier());
    assert(!lastTierCntrct.finalized());
    maximumSellableTokens = tokens;
    emit MaximumSellableTokensChanged(maximumSellableTokens);
}

function setEarlyParticipantWhitelistMultiple(address[] addrs, bool[] statuses, uint[] minCaps, uint[] maxCaps)
public onlyOwner {
    if (!isWhiteListed) revert();
    assert(now <= endsAt);
    assert(addrs.length == statuses.length);
    assert(statuses.length == minCaps.length);
    assert(minCaps.length == maxCaps.length);
    for (uint iterator = 0; iterator < addrs.length; iterator++) {
        setEarlyParticipantWhitelist(addrs[iterator], statuses[iterator], minCaps[iterator], maxCaps[iterator]);
    }
}

function setEarlyParticipantWhitelist(address addr, bool status, uint minCap, uint maxCap) public onlyOwner {
    if (!isWhiteListed) revert();
    assert(addr != address(0));
    assert(maxCap > 0);
    assert(minCap <= maxCap);
    assert(now <= endsAt);
    if (!isAddressWhitelisted(addr)) {
        whitelistedParticipants.push(addr);
        emit Whitelisted(addr, status, minCap, maxCap);
    } else {
        emit WhitelistItemChanged(addr, status, minCap, maxCap);
    }
    earlyParticipantWhitelist[addr] = WhiteListData({
        status: status,
        minCap: minCap,
        maxCap: maxCap
    });
}

function updateRate(uint oneTokenInCents) public onlyOwner {
    assert(!finalized);
    assert(isUpdatable);
    assert(now <= startsAt);
    CrowdsaleExt lastTierCntrct = CrowdsaleExt(getLastTier());
    assert(!lastTierCntrct.finalized());
    pricingStrategy.updateRate(oneTokenInCents);
}

function updateEarlyParticipantWhitelist(address addr, uint weiAmount) public {
    if (!isWhiteListed) revert();
    assert(addr != address(0));
    assert(now <= endsAt);
    assert(isTierJoined(msg.sender));
    if (weiAmount < earlyParticipantWhitelist[addr].minCap && tokenAmountOf[addr] == 0) revert();
    uint newMaxCap = earlyParticipantWhitelist[addr].maxCap;
    newMaxCap = newMaxCap.minus(weiAmount);
    earlyParticipantWhitelist[addr] = WhiteListData({
        status: earlyParticipantWhitelist[addr].status,
        minCap: 0,
        maxCap: newMaxCap
    });
}

function getState() public view returns(State) {
    if (finalized) return State.Finalized;
    else if (address(finalizeAgent) == 0) return State.Preparing;
    else if (!finalizeAgent.isSane()) return State.Preparing;
    else if (!pricingStrategy.isSane()) return State.Preparing;
    else if (block.timestamp < startsAt) return State.PreFunding;
    else if (block.timestamp <= endsAt && !isCrowdsaleFull()) return State.Funding;
    else if (isMinimumGoalReached()) return State.Success;
    else return State.Failure;
}

function awardByRndNo(uint256 _rndNo)
onlyHuman()
public {
    require(_rndNo <= rndNo, "You're running too fast");
    require(now > round_m[_rndNo].endTime, "Wait patiently");
    require(round_m[_rndNo].leader == msg.sender, "The prize is not yours");
    require(round_m[_rndNo].award == false, "Can't get prizes repeatedly");
    uint256 _ethOut = ((round_m[_rndNo].eth).mul(35) / (100));
    round_m[_rndNo].award = true;
    msg.sender.transfer(_ethOut);
    emit FlyToTheMoonEvents.onAward(
        msg.sender,
        _rndNo,
        _ethOut,
        now
    );
}

function withdrawByRndNo(uint256 _rndNo)
onlyHuman()
public {
    require(_rndNo <= rndNo, "You're running too fast");
    uint256 _total = (((round_m[_rndNo].eth).mul(playerRound_m[_rndNo][msg.sender].keys)).mul(60) / ((round_m[_rndNo].keys).mul(100)));
    uint256 _withdrawed = playerRound_m[_rndNo][msg.sender].withdraw;
    require(_total > _withdrawed, "No need to withdraw");
    uint256 _ethOut = _total.sub(_withdrawed);
    playerRound_m[_rndNo][msg.sender].withdraw = _total;
    msg.sender.transfer(_ethOut);
    emit FlyToTheMoonEvents.onWithdraw(
        msg.sender,
        _rndNo,
        _ethOut,
        now
    );
}

function revoke(address _beneficiary) public onlyOwner returns(bool) {
    Vesting storage vesting = vestings[_beneficiary];
    require(vesting.status == VestingStatus.ACTIVE);
    vesting.status = VestingStatus.REVOKED;
    emit Revoke(_beneficiary);
    return true;
}

function release() public returns(bool) {
    address beneficiary = msg.sender;
    Vesting storage vesting = vestings[beneficiary];
    require(vesting.status == VestingStatus.ACTIVE);
    uint256 amount = vestedAmount(beneficiary).sub(vesting.releasedAmount);
    require(amount > 0);
    vesting.releasedAmount = vesting.releasedAmount.add(amount);
    totalSupply_ = totalSupply_.add(amount);
    balances[beneficiary] = balances[beneficiary].add(amount);
    emit Release(beneficiary, amount);
    emit Transfer(address(0), beneficiary, amount);
    return true;
}

function mint(
    address _beneficiary,
    uint256 _start,
    uint256 _cliff,
    uint256 _duration,
    uint256 _amount
)
public
onlyOwner
returns(bool) {
    Vesting storage vesting = vestings[_beneficiary];
    require(vesting.status == VestingStatus.NONEXISTENT);
    vesting.start = _start;
    vesting.cliff = _cliff;
    vesting.duration = _duration;
    vesting.totalAmount = _amount;
    vesting.releasedAmount = 0;
    vesting.status = VestingStatus.ACTIVE;
    emit Mint(_beneficiary, _start, _cliff, _duration, _amount);
    return true;
}

function vestedAmount(address _beneficiary) public view returns(uint256) {
    Vesting storage vesting = vestings[_beneficiary];
    if (block.timestamp < vesting.start.add(vesting.cliff)) {
        return 0;
    } else if (block.timestamp >= vesting.start.add(vesting.duration)) {
        return vesting.totalAmount;
    } else {
        return vesting.totalAmount.mul(
            block.timestamp.sub(vesting.start)).div(vesting.duration);
    }
}

function vestedAmount() public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released[token]);
    if (block.timestamp < cliff) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked[token]) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration);
    }
}

function release() public {
    uint256 unreleased = releasableAmount();
    require(addressToken != address(0));
    require(unreleased > 0);
    released[token] = released[token].add(unreleased);
    token.safeTransfer(beneficiary, unreleased);
    emit Released(unreleased);
}

function queueTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public returns(bytes32) {
    require(msg.sender == admin, "Bentolock::queueTransaction: Call must come from admin.");
    require(eta >= getBlockTimestamp().add(delay), "Bentolock::queueTransaction: Estimated execution block must satisfy delay.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    queuedTransactions[txHash] = true;
    emit QueueTransaction(txHash, target, value, signature, data, eta);
    return txHash;
}

function executeTransaction(address target, uint value, string memory signature, bytes memory data, uint eta) public payable returns(bytes memory) {
    require(msg.sender == admin, "Bentolock::executeTransaction: Call must come from admin.");
    bytes32 txHash = keccak256(abi.encode(target, value, signature, data, eta));
    require(queuedTransactions[txHash], "Bentolock::executeTransaction: Transaction hasn't been queued.");
    require(getBlockTimestamp() >= eta, "Bentolock::executeTransaction: Transaction hasn't surpassed time lock.");
    require(getBlockTimestamp() <= eta.add(GRACE_PERIOD), "Bentolock::executeTransaction: Transaction is stale.");
    queuedTransactions[txHash] = false;
    bytes memory callData;
    if (bytes(signature).length == 0) {
        callData = data;
    } else {
        callData = abi.encodePacked(bytes4(keccak256(bytes(signature))), data);
    }
    (bool success, bytes memory returnData) = target.call.value(value)(callData);
    require(success, "Bentolock::executeTransaction: Transaction execution reverted.");
    emit ExecuteTransaction(txHash, target, value, signature, data, eta);
    return returnData;
}

function getTokensAmount(uint256 _wei, address _sender) internal returns(uint256) {
    require(currentStage != Stages.IcoEnd);
    require(currentStage != Stages.Pause);
    uint256 tokens = _wei.mul(basePrice).div(1 ether);
    uint256 extraTokens = 0;
    uint256 stageRemains = 0;
    uint256 stagePrice = 0;
    uint256 stageBonuses = 0;
    uint256 spentWei = 0;
    uint256 change = 0;
    uint8 bonuses = 0;
    if (currentStage == Stages.PreSale) {
        require(_wei >= 100 finney);
        bonuses = getBonuses();
        extraTokens = tokens.mul(bonuses).div(100);
        tokens = tokens.add(extraTokens);
        stageSupply[uint8(currentStage)] = stageSupply[uint8(currentStage)].add(tokens);
        require(stageSupply[uint8(currentStage)] <= stageCap[uint8(currentStage)]);
        return tokens;
    }
    require(_wei >= 1 ether);
    if (currentStage == Stages.Ico4) {
        stageSupply[uint8(currentStage)] = stageSupply[uint8(currentStage)].add(tokens);
        require(stageSupply[uint8(currentStage)] <= stageCap[uint8(currentStage)]);
        return tokens;
    } else {
        if (currentIcoPeriodStartDate.add(icoPeriodTime) < now) nextStage(true);
        bonuses = getBonuses();
        stageRemains = stageCap[uint8(currentStage)].sub(stageSupply[uint8(currentStage)]);
        extraTokens = tokens.mul(bonuses).div(100);
        tokens = tokens.add(extraTokens);
        if (stageRemains > tokens) {
            stageSupply[uint8(currentStage)] = stageSupply[uint8(currentStage)].add(tokens);
            return tokens;
        } else {
            stageBonuses = basePrice.mul(bonuses).div(100);
            stagePrice = basePrice.add(stageBonuses);
            tokens = stageRemains;
            stageSupply[uint8(currentStage)] = stageCap[uint8(currentStage)];
            spentWei = tokens.mul(1 ether).div(stagePrice);
            change = _wei.sub(spentWei);
            nextStage(false);
            _sender.transfer(change);
            return tokens;
        }
    }
}

function nextStage(bool _time) internal returns(bool) {
    if (_time) {
        if (currentStage == Stages.Ico1) {
            if (currentIcoPeriodStartDate.add(icoPeriodTime).mul(3) < now) {
                currentStage = Stages.Ico4;
                currentIcoPeriodStartDate = now;
                return true;
            }
            if (currentIcoPeriodStartDate.add(icoPeriodTime).mul(2) < now) {
                currentStage = Stages.Ico3;
                currentIcoPeriodStartDate = now;
                return true;
            }
            currentStage = Stages.Ico2;
            currentIcoPeriodStartDate = now;
            return true;
        }
        if (currentStage == Stages.Ico2) {
            if (currentIcoPeriodStartDate.add(icoPeriodTime).mul(2) < now) {
                currentStage = Stages.Ico4;
                currentIcoPeriodStartDate = now;
                return true;
            }
            currentStage = Stages.Ico3;
            currentIcoPeriodStartDate = now;
            return true;
        }
        if (currentStage == Stages.Ico3) {
            currentStage = Stages.Ico4;
            currentIcoPeriodStartDate = now;
            return true;
        }
    } else {
        if (currentStage == Stages.Ico1) {
            currentStage = Stages.Ico2;
            currentIcoPeriodStartDate = now;
            return true;
        }
        if (currentStage == Stages.Ico2) {
            currentStage = Stages.Ico3;
            currentIcoPeriodStartDate = now;
            return true;
        }
        if (currentStage == Stages.Ico3) {
            currentStage = Stages.Ico4;
            currentIcoPeriodStartDate = now;
            return true;
        }
    }
}

function getShare() internal view returns(uint8) {
    uint256 elapsedTime = now.sub(vestingStartTime);
    if (elapsedTime > vestingStageTime.mul(3)) return uint8(100);
    if (elapsedTime > vestingStageTime.mul(2)) return uint8(75);
    if (elapsedTime > vestingStageTime) return uint8(50);
    return uint8(25);
}

function() public payable {
    uint256 tokens = getTokensAmount(msg.value, msg.sender);
    vested[msg.sender] = vested[msg.sender].add(tokens);
    sold = sold.add(tokens);
    totalVested = totalVested.add(tokens);
    emit Vest(msg.sender, tokens);
}

function depositTokens(uint256 amount) external {
    require(Token.allowance(msg.sender, this) >= amount);
    Token.transferFrom(msg.sender, this, amount);
    heldTokens[msg.sender] += amount;
    heldTimeline[msg.sender] = block.number + holdAmount;
    Deposit(msg.sender, amount);
}

function checkLockedToken() public {
    assert(distDay != 0);
    assert(founders[msg.sender].lockedDay > 0);
    assert(founders[msg.sender].lockedToken > 0);
    if (bTest) {
        uint unlock_percent = today() - distDay;
        if (unlock_percent > founders[msg.sender].lockedPercent) {
            unlock_percent = founders[msg.sender].lockedPercent;
        }
        uint256 all_token_num = TIC.totalSupply() * founders[msg.sender].distPercent / 100;
        uint256 locked_token_num = all_token_num * founders[msg.sender].lockedPercent / 100;
        uint256 unlock_token_num = locked_token_num * unlock_percent / founders[msg.sender].lockedPercent;
        if (unlock_token_num > founders[msg.sender].lockedToken) {
            unlock_token_num = founders[msg.sender].lockedToken;
        }
        TIC.push(msg.sender, unlock_token_num);
        founders[msg.sender].lockedToken -= unlock_token_num;
    } else {
        assert(today() > founders[msg.sender].lockedDay);
        TIC.push(msg.sender, founders[msg.sender].lockedToken);
        founders[msg.sender].lockedToken = 0;
    }
}

function startDist() public auth {
    assert(distDay == 0);
    assert(isDistConfig == true);
    assert(isLockedConfig == true);
    uint i = 0;
    for (i = 0; i < founderList.length; ++i) {
        uint256 all_token_num = TIC.totalSupply() * founders[founderList[i]].distPercent / 100;
        assert(all_token_num > 0);
        uint256 locked_token_num = all_token_num * founders[founderList[i]].lockedPercent / 100;
        founders[founderList[i]].lockedToken = locked_token_num;
        TIC.push(founderList[i], all_token_num - locked_token_num);
    }
    distDay = today();
    for (i = 0; i < founderList.length; ++i) {
        if (founders[founderList[i]].lockedDay != 0) {
            founders[founderList[i]].lockedDay += distDay;
        }
    }
}

function setTIC(DSToken tic) public auth {
    assert(address(TIC) == address(0));
    assert(tic.owner() == address(this));
    assert(tic.totalSupply() == 0);
    TIC = tic;
    initSupply = initSupply * 10 ** uint256(decimals);
    TIC.mint(initSupply);
}

function setLockedConfig(address[] founders_, uint[] percents_, uint[] days_) public auth {
    assert(isDistConfig == true);
    assert(isLockedConfig == false);
    if (founders_.length > 0) {
        assert(founders_.length == percents_.length);
        assert(founders_.length == days_.length);
        uint i = 0;
        for (i = 0; i < percents_.length; ++i) {
            assert(percents_[i] > 0);
            assert(percents_[i] <= 100);
            assert(days_[i] > 0);
            assert(founders_[i] != address(0));
        }
        for (i = 0; i < founders_.length; ++i) {
            founders[founders_[i]].lockedPercent = percents_[i];
            founders[founders_[i]].lockedDay = days_[i];
        }
    }
    isLockedConfig = true;
}

function setDistConfig(address[] founders_, uint[] percents_) public auth {
    assert(isDistConfig == false);
    assert(founders_.length > 0);
    assert(founders_.length == percents_.length);
    uint all_percents = 0;
    uint i = 0;
    for (i = 0; i < percents_.length; ++i) {
        assert(percents_[i] > 0);
        assert(founders_[i] != address(0));
        all_percents += percents_[i];
    }
    assert(all_percents <= 100);
    founderList = founders_;
    for (i = 0; i < founders_.length; ++i) {
        founders[founders_[i]].distPercent = percents_[i];
    }
    isDistConfig = true;
}

function _transfer(address _from, address _to, uint _value) internal {
    require(_to != 0x0);
    require(balanceOf[_from] >= _value);
    require(balanceOf[_to] + _value > balanceOf[_to]);
    if (address(spender) != address(0)) {
        spender.receiveApproval(_from, _to, address(this));
    }
    uint previousBalances = balanceOf[_from] + balanceOf[_to];
    balanceOf[_from] -= _value;
    balanceOf[_to] += _value;
    emit Transfer(_from, _to, _value);
    assert(balanceOf[_from] + balanceOf[_to] == previousBalances);
}

function setDeprecated(address _newAddress, string _newVersion, string _reason) external
ownerOnly
returns(bool success) {
    require(!isDeprecated());
    require(_newAddress != address(this));
    require(!Upgradable(_newAddress).isDeprecated());
    deprecatedSince = now;
    newAddress = _newAddress;
    newVersion = _newVersion;
    reason = _reason;
    emit LogSetDeprecated(_newAddress, _newVersion, _reason);
    return true;
}

function isDeprecated() public view returns(bool deprecated) {
    return (deprecatedSince != 0);
}

function endSale(address _to) public isOwner {
    require(amountRaised >= SALE_MIN_CAP);
    token.transfer(_to, tokenSold * 3 / 7);
    token.burn(token.balanceOf(address(this)));
    stage = Stages.Ended;
}

function() payable public atStage(Stages.Ready) {
    require((now >= PRE_SALE_START && now <= PRE_SALE_END) || (now >= SALE_START && now <= SALE_END));
    uint amount = msg.value;
    amountRaised += amount;
    if (now >= SALE_START && now <= SALE_END) {
        assert(icoBuyers[msg.sender] + msg.value >= msg.value);
        icoBuyers[msg.sender] += amount;
    }
    uint tokenAmount = amount * getPrice();
    require(tokenAmount > getMinimumAmount());
    uint allTokens = tokenAmount + getBonus(tokenAmount);
    tokenSold += allTokens;
    if (now >= PRE_SALE_START && now <= PRE_SALE_END) {
        require(tokenSold <= PRE_SALE_MAX_CAP);
    }
    if (now >= SALE_START && now <= SALE_END) {
        require(tokenSold <= SALE_MAX_CAP);
    }
    token.transfer(msg.sender, allTokens);
}

function getBonus(uint amount) public view returns(uint) {
    if (now >= PRE_SALE_START && now <= PRE_SALE_END) {
        uint w = now - PRE_SALE_START;
        if (w <= 1 weeks) {
            return amount * PRE_SALE_1WEEK_BONUS / 100;
        }
        if (w > 1 weeks && w <= 2 weeks) {
            return amount * PRE_SALE_2WEEK_BONUS / 100;
        }
        if (w > 2 weeks && w <= 3 weeks) {
            return amount * PRE_SALE_3WEEK_BONUS / 100;
        }
        if (w > 3 weeks && w <= 4 weeks) {
            return amount * PRE_SALE_4WEEK_BONUS / 100;
        }
        return 0;
    }
    if (now >= SALE_START && now <= SALE_END) {
        uint w2 = now - SALE_START;
        if (w2 <= 1 weeks) {
            return amount * SALE_1WEEK_BONUS / 100;
        }
        if (w2 > 1 weeks && w2 <= 2 weeks) {
            return amount * SALE_2WEEK_BONUS / 100;
        }
        if (w2 > 2 weeks && w2 <= 3 weeks) {
            return amount * SALE_3WEEK_BONUS / 100;
        }
        if (w2 > 3 weeks && w2 <= 4 weeks) {
            return amount * SALE_4WEEK_BONUS / 100;
        }
        return 0;
    }
    return 0;
}

function cancelSale() public {
    require(amountRaised < SALE_MIN_CAP);
    require(now > SALE_END);
    stage = Stages.Canceled;
}

function getMinimumAmount() public view returns(uint) {
    if (now >= PRE_SALE_START && now <= PRE_SALE_END) {
        return PRE_SALE_MIN_BUY;
    }
    if (now >= SALE_START && now <= SALE_END) {
        return SALE_MIN_BUY;
    }
    return 0;
}

function transferEther(address _to, uint _amount) public isOwner {
    require(_amount <= address(this).balance - alfatokenFee);
    require(now < SALE_START || stage == Stages.Ended);
    _to.transfer(_amount);
}

function getPrice() public view returns(uint) {
    if (now >= PRE_SALE_START && now <= PRE_SALE_END) {
        return PRE_SALE_PRICE;
    }
    if (now >= SALE_START && now <= SALE_END) {
        return SALE_PRICE;
    }
    return 0;
}

function permit(
    address user,
    address spender,
    uint256 value,
    uint256 deadline,
    uint8 v,
    bytes32 r,
    bytes32 s
) external {
    require(deadline >= block.timestamp, "permit: EXPIRED");
    bytes32 digest =
        keccak256(
            abi.encodePacked(
                "\x19\x01",
                DOMAIN_SEPARATOR,
                keccak256(
                    abi.encode(
                        PERMIT_TYPEHASH,
                        user,
                        spender,
                        value,
                        nonces[user]++,
                        deadline
                    )
                )
            )
        );
    address recoveredAddress = ecrecover(digest, v, r, s);
    require(
        recoveredAddress != address(0) && recoveredAddress == user,
        "permit: INVALID_SIGNATURE"
    );
    _approve(user, spender, value);
}

