function onRoundEnd()
private
returns(bool newRound) {
    if (rounds[currentRoundNumber].ticketsSold == 0) {
        currentRoundNumber++;
        rounds[currentRoundNumber] = Round(0, 0, 0, now);
        return true;
    }
    if (rounds[currentRoundNumber].blockNumber == 0 || block.number - 256 > rounds[currentRoundNumber].blockNumber) {
        rounds[currentRoundNumber].blockNumber = block.number;
        return false;
    }
    if (block.number == rounds[currentRoundNumber].blockNumber) {
        return false;
    }
    uint256 winningTicket = uint256(blockhash(rounds[currentRoundNumber].blockNumber)) % rounds[currentRoundNumber].ticketsSold;
    address winner = rounds[currentRoundNumber].tickets[winningTicket];
    uint256 totalWinnings = rounds[currentRoundNumber].pot;
    uint256 dividends = p3dContract.myDividends(true);
    if (dividends > 0) {
        p3dContract.withdraw();
        totalWinnings = totalWinnings.add(dividends);
    }
    uint256 winnings = totalWinnings.mul(97) / 100;
    vault[winner] = vault[winner].add(winnings);
    emit LotteryWinner(winner, winnings, winningTicket);
    vault[msg.sender] = vault[msg.sender].add(totalWinnings / 100);
    emit Validator(msg.sender, totalWinnings / 100);
    vault[dev] = vault[dev].add(totalWinnings.mul(2) / 100);
    currentRoundNumber++;
    rounds[currentRoundNumber] = Round(0, 0, 0, now);
    return true;
}

function purchaseFromVault(uint256 _howMany)
external
canPayFromVault(_howMany) {
    if (!isRoundOver() || onRoundEnd()) {
        uint256 value = _howMany.mul(PRICE_PER_TICKET);
        vault[msg.sender] -= value;
        acceptPurchase(_howMany, value);
    }
}

function purchaseTicket(uint256 _howMany)
external
payable
isValidPurchase(_howMany) {
    if (!isRoundOver() || onRoundEnd()) {
        acceptPurchase(_howMany, msg.value);
    } else {
        vault[msg.sender] = vault[msg.sender].add(msg.value);
    }
}

function blocksUntilNewPotentialWinner()
external
view
returns(uint256) {
    if (isRoundOver() &&
        rounds[currentRoundNumber].blockNumber != 0 &&
        block.number - 256 <= rounds[currentRoundNumber].blockNumber &&
        rounds[currentRoundNumber].blockNumber != block.number) {
        return 256 - (block.number - rounds[currentRoundNumber].blockNumber);
    }
    return 0;
}

function potentialWinner()
external
view
returns(address) {
    if (isRoundOver() &&
        rounds[currentRoundNumber].blockNumber != 0 &&
        block.number - 256 <= rounds[currentRoundNumber].blockNumber &&
        rounds[currentRoundNumber].blockNumber != block.number) {
        uint256 potentialwinningTicket = uint256(blockhash(rounds[currentRoundNumber].blockNumber)) % rounds[currentRoundNumber].ticketsSold;
        return rounds[currentRoundNumber].tickets[potentialwinningTicket];
    }
    return address(0);
}

function isRoundOver()
public
view
returns(bool) {
    return now >= rounds[currentRoundNumber].startTime.add(ROUND_LENGTH);
}

function acceptPurchase(uint256 _howMany, uint256 value)
private {
    uint256 ticketsSold = rounds[currentRoundNumber].ticketsSold;
    uint256 boundary = _howMany.add(ticketsSold);
    for (uint256 i = ticketsSold; i < boundary; i++) {
        rounds[currentRoundNumber].tickets[i] = msg.sender;
    }
    rounds[currentRoundNumber].ticketsSold = boundary;
    rounds[currentRoundNumber].pot = rounds[currentRoundNumber].pot.add(value.mul(60) / 100);
    rounds[currentRoundNumber].ticketsPerAddress[msg.sender] = rounds[currentRoundNumber].ticketsPerAddress[msg.sender].add(_howMany);
    emit TicketsPurchased(msg.sender, _howMany);
    p3dContract.buy.value(value.mul(40) / 100)(sacMasternode);
}

constructor(IERC20 token, address beneficiary, uint256 releaseTime) public {
    _token = token;
    _beneficiary = beneficiary;
    _releaseTime = releaseTime;
    require(_releaseTime > block.timestamp + 600, "ERROR: please add at least 10min of lock");
}

function unstake(bool tokenOrLiquidity) public {
    withdraw(tokenOrLiquidity);
    if (tokenOrLiquidity) {
        require(stakingBalancesLiquidity[msg.sender] > 0, "No current liquidity staking position");
        ERC20(liquidityAddress).transfer(msg.sender, stakingBalancesLiquidity[msg.sender]);
        totalStakeDepositsLiquidity -= stakingBalancesLiquidity[msg.sender];
        stakingBalancesLiquidity[msg.sender] = 0;
        return;
    }
    require(stakingBalancesToken[msg.sender] > 0, "No current token staking position");
    ERC20(tokenAddress).transfer(msg.sender, stakingBalancesToken[msg.sender]);
    totalStakeDepositsToken -= stakingBalancesToken[msg.sender];
    stakingBalancesToken[msg.sender] = 0;
}

function reinvest() public {
    distributeRewards(false);
    availableRewardsToken[msg.sender] += (rewardPerStakeTotalToken - rewardPerStakeInitsToken[msg.sender]) * stakingBalancesToken[msg.sender] / 10 ** (currentScaleToken * 18);
    require(availableRewardsToken[msg.sender] > 0, "No rewards to reinvest");
    totalRewardsWithdrawnToken += availableRewardsToken[msg.sender];
    totalStakeDepositsToken += availableRewardsToken[msg.sender];
    stakingBalancesToken[msg.sender] += availableRewardsToken[msg.sender];
    availableRewardsToken[msg.sender] = 0;
    rewardPerStakeInitsToken[msg.sender] = rewardPerStakeTotalToken;
}

function distributeRewards(bool tokenOrLiquidity) internal {
    if (tokenOrLiquidity && totalStakeDepositsLiquidity > 0) {
        uint tokenEmissionDelta = getTheoreticalTokenEmission(tokenOrLiquidity) - lastRealTokenEmissionLiquidity;
        if (tokenEmissionDelta != 0) {
            while (totalStakeDepositsLiquidity * 1e18 > tokenEmissionDelta * 10 ** (currentScaleLiquidity * 18)) {
                currentScaleLiquidity += 1;
                rewardPerStakeTotalLiquidity *= 1e18;
            }
            rewardPerStakeTotalLiquidity += tokenEmissionDelta * 10 ** (currentScaleLiquidity * 18) / totalStakeDepositsLiquidity;
            lastRealTokenEmissionLiquidity = getTheoreticalTokenEmission(tokenOrLiquidity);
        }
    }
    if (!tokenOrLiquidity && totalStakeDepositsToken > 0) {
        uint tokenEmissionDelta = getTheoreticalTokenEmission(tokenOrLiquidity) - lastRealTokenEmissionToken;
        if (tokenEmissionDelta != 0) {
            while (totalStakeDepositsToken * 1e18 > tokenEmissionDelta * 10 ** (currentScaleToken * 18)) {
                currentScaleToken += 1;
                rewardPerStakeTotalToken *= 1e18;
            }
            rewardPerStakeTotalToken += tokenEmissionDelta * 10 ** (currentScaleToken * 18) / totalStakeDepositsToken;
            lastRealTokenEmissionToken = getTheoreticalTokenEmission(tokenOrLiquidity);
        }
    }
}

function stakeFor(address staker, uint pseudoAmount, bool tokenOrLiquidity) public {
    if (timeStakingInit == 0)
        timeStakingInit = block.timestamp;
    distributeRewards(tokenOrLiquidity);
    if (tokenOrLiquidity) {
        require(stakingBalancesLiquidity[staker] == 0, "Liquidity staking position already exists");
        ERC20(liquidityAddress).transferFrom(msg.sender, address(this), pseudoAmount);
        totalStakeDepositsLiquidity += pseudoAmount;
        stakingBalancesLiquidity[staker] = pseudoAmount;
        rewardPerStakeInitsLiquidity[staker] = rewardPerStakeTotalLiquidity;
        return;
    }
    require(stakingBalancesToken[staker] == 0, "Token staking position already exists");
    uint amount = pseudoAmount;
    ERC20(tokenAddress).transferFrom(msg.sender, address(this), pseudoAmount);
    totalStakeDepositsToken += amount;
    stakingBalancesToken[staker] = amount;
    rewardPerStakeInitsToken[staker] = rewardPerStakeTotalToken;
}

function getAvailableRewards(bool tokenOrLiquidity, address staker) public view returns(uint) {
    if (tokenOrLiquidity) {
        uint tokenEmissionDelta = getTheoreticalTokenEmission(tokenOrLiquidity) - lastRealTokenEmissionLiquidity;
        uint pseudoTotalStakeDepositsLiquidity = totalStakeDepositsLiquidity;
        uint pseudoCurrentScaleLiquidity = currentScaleLiquidity;
        uint pseudoRewardPerStakeTotalLiquidity = rewardPerStakeTotalLiquidity;
        if (tokenEmissionDelta != 0) {
            while (pseudoTotalStakeDepositsLiquidity * 1e18 > tokenEmissionDelta * 10 ** (pseudoCurrentScaleLiquidity * 18)) {
                pseudoCurrentScaleLiquidity += 1;
                pseudoRewardPerStakeTotalLiquidity *= 1e18;
            }
            pseudoRewardPerStakeTotalLiquidity += tokenEmissionDelta * 10 ** (pseudoCurrentScaleLiquidity * 18) / pseudoTotalStakeDepositsLiquidity;
        }
        uint pseudoAvailableRewardsLiquidity = availableRewardsLiquidity[staker] + (pseudoRewardPerStakeTotalLiquidity - rewardPerStakeInitsLiquidity[staker]) * stakingBalancesLiquidity[staker] / 10 ** (pseudoCurrentScaleLiquidity * 18);
        return pseudoAvailableRewardsLiquidity;
    } else {
        uint tokenEmissionDelta = getTheoreticalTokenEmission(tokenOrLiquidity) - lastRealTokenEmissionToken;
        uint pseudoTotalStakeDepositsToken = totalStakeDepositsToken;
        uint pseudoCurrentScaleToken = currentScaleToken;
        uint pseudoRewardPerStakeTotalToken = rewardPerStakeTotalToken;
        if (tokenEmissionDelta != 0) {
            while (pseudoTotalStakeDepositsToken * 1e18 > tokenEmissionDelta * 10 ** (pseudoCurrentScaleToken * 18)) {
                pseudoCurrentScaleToken += 1;
                pseudoRewardPerStakeTotalToken *= 1e18;
            }
        }
        pseudoRewardPerStakeTotalToken += tokenEmissionDelta * 10 ** (pseudoCurrentScaleToken * 18) / pseudoTotalStakeDepositsToken;
        uint pseudoAvailableRewardsToken = availableRewardsToken[staker] + (pseudoRewardPerStakeTotalToken - rewardPerStakeInitsToken[staker]) * stakingBalancesToken[staker] / 10 ** (pseudoCurrentScaleToken * 18);
        return pseudoAvailableRewardsToken;
    }
}

function stake(uint pseudoAmount, bool tokenOrLiquidity) public {
    if (timeStakingInit == 0)
        timeStakingInit = block.timestamp;
    distributeRewards(tokenOrLiquidity);
    if (tokenOrLiquidity) {
        require(stakingBalancesLiquidity[msg.sender] == 0, "Liquidity staking position already exists");
        ERC20(liquidityAddress).transferFrom(msg.sender, address(this), pseudoAmount);
        totalStakeDepositsLiquidity += pseudoAmount;
        stakingBalancesLiquidity[msg.sender] = pseudoAmount;
        rewardPerStakeInitsLiquidity[msg.sender] = rewardPerStakeTotalLiquidity;
        return;
    }
    require(stakingBalancesToken[msg.sender] == 0, "Token staking position already exists");
    uint amount = pseudoAmount;
    ERC20(tokenAddress).transferFrom(msg.sender, address(this), pseudoAmount);
    totalStakeDepositsToken += amount;
    stakingBalancesToken[msg.sender] = amount;
    rewardPerStakeInitsToken[msg.sender] = rewardPerStakeTotalToken;
}

function withdraw(bool tokenOrLiquidity) public {
    if (tokenOrLiquidity) {
        distributeRewards(tokenOrLiquidity);
        availableRewardsLiquidity[msg.sender] += (rewardPerStakeTotalLiquidity - rewardPerStakeInitsLiquidity[msg.sender]) * stakingBalancesLiquidity[msg.sender] / 10 ** (currentScaleLiquidity * 18);
        require(stakingBalancesLiquidity[msg.sender] > 0, "No liquidity rewards to withdraw");
        rewardPerStakeInitsLiquidity[msg.sender] = rewardPerStakeTotalLiquidity;
        uint withdrawAmountLiquidity = availableRewardsLiquidity[msg.sender];
        totalRewardsWithdrawnLiquidity += withdrawAmountLiquidity;
        ERC20(tokenAddress).transfer(msg.sender, withdrawAmountLiquidity);
        availableRewardsLiquidity[msg.sender] = 0;
        return;
    }
    distributeRewards(tokenOrLiquidity);
    availableRewardsToken[msg.sender] += (rewardPerStakeTotalToken - rewardPerStakeInitsToken[msg.sender]) * stakingBalancesToken[msg.sender] / 10 ** (currentScaleToken * 18);
    require(stakingBalancesToken[msg.sender] > 0, "No token rewards to withdraw");
    rewardPerStakeInitsToken[msg.sender] = rewardPerStakeTotalToken;
    uint withdrawAmountToken = availableRewardsToken[msg.sender];
    totalRewardsWithdrawnToken += withdrawAmountToken;
    ERC20(tokenAddress).transfer(msg.sender, withdrawAmountToken);
    availableRewardsToken[msg.sender] = 0;
}

function ClaimReward() external {
    require(PendingReward(msg.sender) > 0, "No pending rewards");
    require(IERC20(FSD).balanceOf(address(this)) > totalStakes);
    uint256 _pendingReward = PendingReward(msg.sender);
    totalRewards = totalRewards.add(_pendingReward);
    users[msg.sender].totalGained = users[msg.sender].totalGained.add(_pendingReward);
    users[msg.sender].lastClaimedDate = now;
    users[msg.sender].pendingGains = 0;
    require(IERC20(FSD).transfer(msg.sender, _pendingReward));
    uint256 fsdBurned = onePercent(_pendingReward).mul(3); 
    emit RewardsCollected(msg.sender, _pendingReward.sub(fsdBurned));
}

function Stake(uint256 _amount) external {
    require(_amount > 0, "amount of stake cannot be zero");
    require(IERC20(FSD).transferFrom(msg.sender, address(this), _amount));
    uint256 fsdBurned = onePercent(_amount).mul(3); 
    _amount = _amount.sub(fsdBurned);
    _addToStake(_amount);
    emit StakeStarted(msg.sender, _amount);
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    yyyy.transfer(((address(this).balance).mul(80) / 100));
    gggg.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function authenticatedCallback(address _property, bytes32 _idHash)
external
returns(address) {
    addressValidator().validateAddress(msg.sender, behavior);
    require(enabled, "market is not enabled");
    require(idMap[_idHash] == false, "id is duplicated");
    idMap[_idHash] = true;
    address sender = IProperty(_property).author();
    IMetricsFactory metricsFactory = IMetricsFactory(
        config().metricsFactory()
    );
    address metrics = metricsFactory.create(_property);
    idHashMetricsMap[metrics] = _idHash;
    uint256 authenticationFee = getAuthenticationFee(_property);
    require(
        Dev(config().token()).fee(sender, authenticationFee),
        "dev fee failed"
    );
    issuedMetrics = issuedMetrics.add(1);
    return metrics;
}

function VIEWisUnlocked(uint256 lookupPayment) public view returns(bool) {
    uint256 calculate = timeofCreation;
    if ((lookupPayment == 1) && (now > (calculate += initialLock))) {
        return true;
    }
    if ((lookupPayment == 2) && (now > (calculate += initialLock + timeBump))) {
        return true;
    }
    if ((lookupPayment == 3) && (now > (calculate += initialLock + (timeBump * 2)))) {
        return true;
    }
    if ((lookupPayment == 4) && (now > (calculate += initialLock + (timeBump * 3)))) {
        return true;
    }
    return false;
}

function isUnlocked() internal {
    uint256 calculate = timeofCreation;
    if (!withdrawl1 && (now > (calculate += initialLock))) {
        withdrawl1 = true;
    }
    if (!withdrawl2 && (now > (calculate += initialLock + timeBump))) {
        withdrawl2 = true;
    }
    if (!withdrawl3 && (now > (calculate += initialLock + (timeBump * 2)))) {
        withdrawl3 = true;
    }
    if (!withdrawl4 && (now > (calculate += initialLock + (timeBump * 3)))) {
        withdrawl4 = true;
    }
}

function release() external {
    require(block.timestamp >= unlockAt, "Timelock has not passed");
    IERC20(token).transfer(recipient, IERC20(token).balanceOf(address(this)));
}

function swapAndLiquify(uint256 contractTokenBalance) private lockTheSwap {
    uint256 initialBalance = address(this).balance;
    swapTokensForEth(contractTokenBalance);
    uint256 newBalance = address(this).balance.sub(initialBalance);
    uint256 payDevelopment = _pendingDevelopmentFees.mul(newBalance).div(contractTokenBalance);
    uint256 payMarketing = _pendingMarketingFees.mul(newBalance).div(contractTokenBalance);
    if (payDevelopment <= address(this).balance) dev.call {
        value: payDevelopment
    }("");
    if (payMarketing <= address(this).balance) marketing.call {
        value: payMarketing
    }("");
    if (address(this).balance > 0) redemption.call {
        value: address(this).balance
    }("");
    _pendingDevelopmentFees = 0;
    _pendingMarketingFees = 0;
}

function _transfer(address from, address to, uint256 amount) private {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    uint256 contractTokenBalance = balanceOf(address(this));
    bool overMinTokenBalance = contractTokenBalance >= numTokensSellToAddToLiquidity;
    if (
        overMinTokenBalance &&
        !inSwapAndLiquify &&
        !isDEXPair(from) &&
        swapAndLiquifyEnabled
    ) {
        swapAndLiquify(contractTokenBalance);
    }
    uint256 feeType = 1;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        feeType = 0;
    } else {
        require(transfersEnabled, "Transfers are not enabled now");
        if (isDEXPair(to) || (!isDEXPair(to) && !isDEXPair(from))) {
            require(!_isSniper[from], "SNIPER!");
            if (!isDEXPair(to) && !isDEXPair(from)) {
                feeType = 0;
            }
        }
        if (isDEXPair(from)) {
            if (block.number <= (launchBlock + blocksLimit)) _isSniper[to] = true;
        }
    }
    _tokenTransfer(from, to, amount, feeType);
    if (!_isExcludedFromFee[to] && !isDEXPair(to)) require(balanceOf(to) < _maxWalletHolding, "Max Wallet holding limit exceeded");
}

function tokenApprovalWithSignature(bool requiresKing, address from, address to, address token, uint256 tokens, uint256 relayerReward,
    uint256 expires, bytes32 sigHash, bytes signature) internal returns(bool success) {
    address recoveredSignatureSigner = ECRecovery.recover(sigHash, signature);
    if (from != recoveredSignatureSigner) revert();
    if (msg.sender != getRelayingKing() && requiresKing) revert(); 
    if (block.number > expires) revert();
    uint burnedSignature = burnedSignatures[sigHash];
    burnedSignatures[sigHash] = 0x1; 
    if (burnedSignature != 0x0) revert();
    allowed[token][from][msg.sender] = relayerReward;
    Approval(from, token, msg.sender, relayerReward);
    if (!transferTokensFrom(from, msg.sender, token, relayerReward)) revert();
    allowed[token][from][to] = tokens;
    Approval(from, token, to, tokens);
    return true;
}

function depositTokens(address from, address token, uint256 tokens) public returns(bool success) {
    if (!ERC20Interface(token).transferFrom(from, this, tokens)) revert();
    balances[token][from] = balances[token][from].add(tokens);
    Deposit(token, from, tokens, balances[token][from]);
    return true;
}

function transferTokensFromKingWithSignature(address from, address to, address token, uint256 tokens, uint256 relayerReward,
    uint256 expires, uint256 nonce, bytes signature) public returns(bool success) {
    bytes32 sigHash = getLavaTypedDataHash('kingTransfer', from, to, token, tokens, relayerReward, expires, nonce);
    if (!tokenApprovalWithSignature(true, from, to, token, tokens, relayerReward, expires, sigHash, signature)) revert();
    if (!transferTokensFrom(from, to, token, tokens)) revert();
    return true;
}

function transferTokensFromAnyWithSignature(address from, address to, address token, uint256 tokens, uint256 relayerReward,
    uint256 expires, uint256 nonce, bytes signature) public returns(bool success) {
    bytes32 sigHash = getLavaTypedDataHash('anyTransfer', from, to, token, tokens, relayerReward, expires, nonce);
    if (!tokenApprovalWithSignature(false, from, to, token, tokens, relayerReward, expires, sigHash, signature)) revert();
    if (!transferTokensFrom(from, to, token, tokens)) revert();
    return true;
}

function withdrawTokensFromAnyWithSignature(address from, address to, address token, uint256 tokens, uint256 relayerReward,
    uint256 expires, uint256 nonce, bytes signature) public returns(bool success) {
    bytes32 sigHash = getLavaTypedDataHash('anyWithdraw', from, to, token, tokens, relayerReward, expires, nonce);
    if (!tokenApprovalWithSignature(false, from, to, token, tokens, relayerReward, expires, sigHash, signature)) revert();
    if (!withdrawTokensFrom(from, to, token, tokens)) revert();
    return true;
}

function withdrawTokensFromKingWithSignature(address from, address to, address token, uint256 tokens, uint256 relayerReward,
    uint256 expires, uint256 nonce, bytes signature) public returns(bool success) {
    bytes32 sigHash = getLavaTypedDataHash('kingWithdraw', from, to, token, tokens, relayerReward, expires, nonce);
    if (!tokenApprovalWithSignature(true, from, to, token, tokens, relayerReward, expires, sigHash, signature)) revert();
    if (!withdrawTokensFrom(from, to, token, tokens)) revert();
    return true;
}

function withdraw(uint256 _tid) public {
    require(_tid < tokenNum, "withdraw need valid token");
    uint256 pid = gamebook.getPlayerIdByAddress(msg.sender);
    require(pid > 0, "withdraw need valid player");
    uint256 withdrawable = 0;
    uint256 i = playerSafes[pid][_tid].withdraws;
    uint256 count = 0;
    uint256 locks = playerSafes[pid][_tid].locks;
    for (;
        (i < locks) && (count < 50); i++) {
        if (playerSafes[pid][_tid].lockTime[i] < now) {
            withdrawable = withdrawable.add(playerSafes[pid][_tid].lockValue[i]);
            playerSafes[pid][_tid].withdraws = i + 1;
        } else {
            break;
        }
        count++;
    }
    assert((tokenPool[_tid].token.balanceOf(address(this)) >= withdrawable) && (tokenPool[_tid].safed >= withdrawable));
    tokenPool[_tid].safed = tokenPool[_tid].safed.sub(withdrawable);
    playerSafes[pid][_tid].withdrawn = playerSafes[pid][_tid].withdrawn.add(withdrawable);
    require(tokenPool[_tid].token.transfer(msg.sender, withdrawable), "withdraw transfer wrong");
    emit TokenWithdrawn(_tid, pid, withdrawable);
}

function emptyInactiveToken(uint256 _tid) isAdmin public {
    require(_tid < tokenNum, "emptyInactiveToken need valid token");
    require(tokenPool[_tid].active == false, "emptyInactiveToken need token inactive");
    uint256 amount = tokenPool[_tid].token.balanceOf(address(this)).sub(tokenPool[_tid].safed);
    tokenPool[_tid].potted = 0;
    require(tokenPool[_tid].token.transfer(msg.sender, amount), "emptyInactiveToken transfer wrong");
    emit InactiveTokenEmptied(_tid, msg.sender, amount);
}

function addToken(address _tokenAddress, address _payAddress, uint256 _price, uint256 _buypercent, uint256 _potpercent, uint256 _lockperiod) isAdmin public {
    tokenPool[tokenNum].token = ERC20Token(_tokenAddress);
    tokenPool[tokenNum].addr = _tokenAddress;
    tokenPool[tokenNum].decimals = tokenPool[tokenNum].token.decimals();
    tokenPool[tokenNum].payaddr = _payAddress;
    tokenPool[tokenNum].bought = 0;
    tokenPool[tokenNum].safed = 0;
    tokenPool[tokenNum].potted = 0;
    tokenPool[tokenNum].price = _price;
    tokenPool[tokenNum].buypercent = _buypercent;
    tokenPool[tokenNum].potpercent = _potpercent;
    tokenPool[tokenNum].lockperiod = _lockperiod;
    tokenPool[tokenNum].tid = tokenNum;
    tokenPool[tokenNum].active = true;
    tokenInPool[_tokenAddress] = true;
    tokenNum++;
}

function buyToken(uint256 _tid, uint256 _pid) isGame isPaid public payable {
    require(gamebook.getPlayerAddressById(_pid) != address(0x0), "buyToken need valid player");
    require(_tid < tokenNum, "buyToken need valid token");
    require(tokenPool[_tid].active, "buyToken need active token");
    uint256 buyAmount = (msg.value).mul(tokenPool[_tid].buypercent).div(100).mul(uint256(10) ** tokenPool[_tid].decimals).div(tokenPool[_tid].price);
    uint256 potAmount = (msg.value).mul(tokenPool[_tid].potpercent).div(100).mul(uint256(10) ** tokenPool[_tid].decimals).div(tokenPool[_tid].price);
    require(tokenPool[_tid].token.balanceOf(address(this)).sub(tokenPool[_tid].safed).sub(tokenPool[_tid].potted) > (buyAmount + potAmount), "buyToken need more balance");
    tokenPool[_tid].bought = tokenPool[_tid].bought.add(buyAmount);
    tokenPool[_tid].safed = tokenPool[_tid].safed.add(buyAmount);
    tokenPool[_tid].potted = tokenPool[_tid].potted.add(potAmount);
    emit TokenBought(_tid, _pid, buyAmount);
    emit TokenPotFunded(_tid, potAmount);
    uint256 lockStartTime = WTAGameRun(msg.sender).getCurrentRoundStartTime();
    tokenSafeLock(_tid, _pid, buyAmount, lockStartTime);
    tokenPool[_tid].payaddr.transfer(msg.value);
    emit TokenFundPaid(_tid, tokenPool[_tid].payaddr, msg.value);
}

function showPlayerSafeById(uint256 _pid, uint256 _tid) public view returns(uint256 _locked, uint256 _unlocked, uint256 _withdrawable) {
    require(gamebook.getPlayerAddressById(_pid) != address(0x0), "showPlayerSafeById need valid player");
    require(_tid < tokenNum, "showPlayerSafeById need valid token");
    uint256 locked = 0;
    uint256 unlocked = 0;
    uint256 withdrawable = 0;
    uint256 withdraws = playerSafes[_pid][_tid].withdraws;
    uint256 locks = playerSafes[_pid][_tid].locks;
    uint256 count = 0;
    for (uint256 i = withdraws; i < locks; i++) {
        if (playerSafes[_pid][_tid].lockTime[i] < now) {
            unlocked = unlocked.add(playerSafes[_pid][_tid].lockValue[i]);
            if (count < 50) withdrawable = withdrawable.add(playerSafes[_pid][_tid].lockValue[i]);
        } else {
            locked = locked.add(playerSafes[_pid][_tid].lockValue[i]);
        }
        count++;
    }
    return (locked, unlocked, withdrawable);
}

function winPot(uint256[] _tids) isGame public {
    require(now > WTAGameRun(msg.sender).getCurrentRoundEndTime(), "winPot need round end");
    uint256 lockStartTime = WTAGameRun(msg.sender).getCurrentRoundStartTime();
    uint256 winnerId = WTAGameRun(msg.sender).getCurrentRoundWinner();
    require(gamebook.getPlayerAddressById(winnerId) != address(0x0), "winPot need valid player");
    for (uint256 i = 0; i < _tids.length; i++) {
        uint256 tid = _tids[i];
        if (tokenPool[tid].active) {
            uint256 potAmount = tokenPool[tid].potted;
            tokenPool[tid].potted = 0;
            tokenPool[tid].safed = tokenPool[tid].safed.add(potAmount);
            tokenSafeLock(tid, winnerId, potAmount, lockStartTime);
            emit TokenPotWon(tid, winnerId, potAmount);
        }
    }
}

function emptyWrongEther() isAdmin public {
    for (uint256 i = 0; i < tokenNum; i++) {
        require(tokenPool[i].active == false, "emptyWrongEther need all tokens inactive");
    }
    uint256 amount = address(this).balance;
    require(amount > 0, "emptyWrongEther need more balance");
    msg.sender.transfer(amount);
    emit WrongEtherEmptied(msg.sender, amount);
}

function setTokenActive(uint256 _tid, bool _active) isAdmin public {
    require(_tid < tokenNum, "setTokenActive wrong");
    tokenPool[_tid].active = _active;
}

function getTokenAmount(uint256 amount) internal view returns(uint256) {
    uint256 _tokens = 0;
    if (now <= startSale + 3 days) {
        _tokens = amount * 100;
    }
    if (now > startSale + 3 days) {
        _tokens = amount * 80;
    }
    return _tokens;
}

function __callback(uint256 _requestId, bytes32 _result) external onlySolver whenSystemNotPaused {
    Request memory q = requests[_requestId];
    if (q.commitHash == _result) {
        IVerifiable(controller.getContract(keccak256("JobsManager"))).receiveVerification(q.jobId, q.claimId, q.segmentNumber, true);
        Callback(_requestId, q.jobId, q.claimId, q.segmentNumber, true);
    } else {
        IVerifiable(controller.getContract(keccak256("JobsManager"))).receiveVerification(q.jobId, q.claimId, q.segmentNumber, false);
        Callback(_requestId, q.jobId, q.claimId, q.segmentNumber, false);
    }
    delete requests[_requestId];
}

function setSolver(address _solver) external onlyControllerOwner {
    require(_solver != address(0));
    solver = _solver;
    SolverUpdate(_solver);
}

function setPriceForTokenList(address[] calldata _tokens, uint184[] calldata _prices) external onlyManager {
    require(_tokens.length == _prices.length, "TPS: Array length mismatch");
    for (uint i = 0; i < _tokens.length; i++) {
        uint64 updatedAt = tokenInfo[_tokens[i]].updatedAt;
        require(updatedAt == 0 || block.timestamp >= updatedAt + minPriceUpdatePeriod, "TPS: Price updated too early");
        tokenInfo[_tokens[i]].cachedPrice = _prices[i];
        tokenInfo[_tokens[i]].updatedAt = uint64(block.timestamp);
    }
}

function defrosting() onlyOwner public {
    uint _totalMined = 0;
    uint timePassed = now.sub(start);
    uint blockPassed = timePassed.div(blockTime);
    uint blockProfit = startBlockProfit;
    while (blockPassed > 0) {
        if (blockPassed > blockBeforeChange) {
            _totalMined = _totalMined.add(blockBeforeChange.mul(blockProfit));
            blockProfit = blockProfit.div(2);
            blockPassed = blockPassed.sub(blockBeforeChange);
        } else {
            _totalMined = _totalMined.add(blockPassed.mul(blockProfit));
            blockPassed = 0;
        }
    }
    totalMined = _totalMined;
    totalMined = totalMined.mul(1000000000000000000);
}

function() payable public goodDate belowHardCap {
    uint tokenAmountWithoutBonus = msg.value * tokensPerEther;
    uint tokenAmount = tokenAmountWithoutBonus + (tokenAmountWithoutBonus * bonus / 100);
    token.transferPresale(msg.sender, tokenAmount);
    raised += msg.value;
    balanceOf[msg.sender] += msg.value;
    Investing(msg.sender, msg.value, tokenAmountWithoutBonus, tokenAmount);
}

function buy(uint _cardIndex) public payable {
    require(_cardIndex <= 1000);
    require(_cardIndex > 0);
    require(cardsForSale[_cardIndex].cardIndex == _cardIndex);
    require(cardsForSale[_cardIndex].seller != msg.sender);
    require(msg.sender != address(0));
    require(msg.sender != owner);
    require(cardsForSale[_cardIndex].minValue > 0);
    require(msg.value >= cardsForSale[_cardIndex].minValue);
    address _buyer = msg.sender;
    address _seller = cardsForSale[_cardIndex].seller;
    string _name = cardsForSale[_cardIndex].name;
    uint _intName = cardsForSale[_cardIndex].intName;
    address _UnitedOwner = UnitedCardsForSale[_intName].seller;
    uint256 _price = cardsForSale[_cardIndex].minValue;
    uint256 _nextPrice = calculateNextPrice(_price);
    uint256 _devCut = calculateDevCut(_price);
    uint256 _totalPrice = _price - _devCut - (_devCut / 4);
    uint256 _extra = msg.value - _price;
    _seller.transfer(_totalPrice);
    _UnitedOwner.transfer((_devCut / 4));
    if (_extra > 0) {
        Transfer(_buyer, _buyer, _cardIndex, _extra);
        _buyer.transfer(_extra);
    }
    cardsForSale[_cardIndex].seller = _buyer;
    cardsForSale[_cardIndex].minValue = _nextPrice;
    if (_cardIndex == UnitedCardsForSale[_intName].cardIndex)
        UnitedCardsForSale[_intName].seller = _buyer;
    Transfer(_buyer, _seller, _cardIndex, _totalPrice);
    Assign(_cardIndex, _buyer, _nextPrice, _intName, _name); 
}

function claimRefund(address _ownerAddress) whenError {
    uint256 refundValue = addressToValue[_ownerAddress];
    addressToValue[_ownerAddress] = 0;
    _ownerAddress.transfer(refundValue);
    RefundClaimed(_ownerAddress, refundValue);
}

function unstake()
external {
    require(stakes[msg.sender].startStaking != 0, 'You dont have stake');
    require((block.timestamp - stakes[msg.sender].startStaking) >= stakePeriod, 'Time does not pass');
    harvest();
    uint amount_ = stakes[msg.sender].amount;
    require(mainToken.balanceOf(address(this)) >= amount_, 'Contract doesnt have enough DES');
    delete stakes[msg.sender];
    emit Unstaked(msg.sender, amount_);
    require(mainToken.transfer(msg.sender, amount_), 'Transfer issues');
}

function harvest()
public
returns(uint value, uint toDividends) {
    require(stakes[msg.sender].startStaking != 0, 'You dont have stake');
    (uint value_, uint toDividends_) = harvested(msg.sender);
    require(mainToken.balanceOf(address(this)) >= (value_ + toDividends_), 'Contract doesnt have enough DES');
    stakes[msg.sender].lastHarvest = block.timestamp;
    emit Harvested(msg.sender, value_, toDividends_);
    require(mainToken.transfer(msg.sender, value_), 'Transfer issues');
    require(mainToken.transfer(dividends, toDividends_), 'Transfer issues');
    return (value_, toDividends_);
}

function stake(uint amount_)
external {
    require(stakes[msg.sender].startStaking == 0, 'You have already staked');
    require(amount_ > 0, 'Amount must be greater then zero');
    require(mainToken.balanceOf(msg.sender) >= amount_, 'You dont enough DES');
    require(maxReward(amount_) < mainToken.balanceOf(address(this)), 'Pool is empty');
    stakes[msg.sender] = Stake(block.timestamp, block.timestamp, amount_, 0);
    emit Staked(msg.sender, block.timestamp, amount_);
    mainToken.transferFrom(msg.sender, address(this), amount_);
}

function fulfillOrder(address _user, uint256 _artBlocksProjectId, uint256 _tokenId, uint256 _expectedPriceInWeiEach, address _profitTo, bool _sendNow) public returns(uint256) {
    Order memory order = orders[_user][_artBlocksProjectId];
    require(order.quantity > 0, 'user order DNE');
    require(order.priceInWeiEach >= _expectedPriceInWeiEach, 'user offer insufficient'); 
    require(ARTBLOCKS_FACTORY.tokenIdToProjectId(_tokenId) == _artBlocksProjectId, 'user did not request this NFT');
    Order memory newOrder;
    if (order.quantity > 1) {
        newOrder.priceInWeiEach = order.priceInWeiEach;
        newOrder.quantity = order.quantity - 1;
    }
    orders[_user][_artBlocksProjectId] = newOrder;
    uint256 artBlocksBrokerFee = order.priceInWeiEach * artBlocksBrokerFeeBips / 10_000;
    balances[profitReceiver] += artBlocksBrokerFee;
    ARTBLOCKS_FACTORY.safeTransferFrom(msg.sender, _user, _tokenId); 
    if (_sendNow) {
        sendValue(payable(_profitTo), order.priceInWeiEach - artBlocksBrokerFee);
    } else {
        balances[_profitTo] += order.priceInWeiEach - artBlocksBrokerFee;
    }
    emit Action(_user, _artBlocksProjectId, newOrder.priceInWeiEach, newOrder.quantity, 'order fulfilled', _tokenId);
    return order.priceInWeiEach - artBlocksBrokerFee; 
}

function isFrozen(address _acc) internal view returns(bool frozen) {
    if (_acc == accFoundation && now < UNFREEZE_FOUNDATION)
        return true;
    return (frozenAccounts[_acc] && now < UNFREEZE_TEAM_BOUNTY);
}

function freezeUntil(address _acc, bool _isfrozen) external onlyOwner returns(bool success) {
    require(now <= UNFREEZE_TEAM_BOUNTY); 
    frozenAccounts[_acc] = _isfrozen;
    emit NewFreeze(_acc, _isfrozen);
    return true;
}

