function refund() public whenNotPaused {
    require(state == SaleState.REFUND);
    require(registry.getContributionETH(msg.sender) > 0);
    require(!hasRefunded[msg.sender]);
    uint ethContributed = registry.getContributionETH(msg.sender);
    if (!msg.sender.send(ethContributed)) {
        ErrorSendingETH(msg.sender, ethContributed);
    } else {
        hasRefunded[msg.sender] = true;
        Refunded(msg.sender, ethContributed);
    }
}

function processTransaction(address _contributor, uint _amount) internal {
    require(msg.value >= minimalContribution);
    uint maxContribution = calculateMaxContributionUsd();
    uint contributionAmountUsd = _amount.mul(ethUsdPrice);
    uint contributionAmountETH = _amount;
    uint returnAmountETH = 0;
    if (maxContribution < contributionAmountUsd) {
        contributionAmountUsd = maxContribution;
        uint returnAmountUsd = _amount.mul(ethUsdPrice) - maxContribution;
        returnAmountETH = contributionAmountETH - returnAmountUsd.div(ethUsdPrice);
        contributionAmountETH = contributionAmountETH.sub(returnAmountETH);
    }
    if (usdRaised + contributionAmountUsd >= softCap && softCap > usdRaised) {
        SoftCapReached(block.number);
    }
    uint tokens = contributionAmountUsd.div(tokenUSDRate);
    if (totalTokens + tokens > hardCapToken) {
        _contributor.transfer(_amount);
    } else {
        if (tokens > 0) {
            registry.addContribution(_contributor, contributionAmountETH, contributionAmountUsd, tokens, ethUsdPrice);
            ethRaised += contributionAmountETH;
            totalTokens += tokens;
            usdRaised += contributionAmountUsd;
            ContributionAdded(_contributor, contributionAmountETH, contributionAmountUsd, tokens, ethUsdPrice);
        }
    }
    if (returnAmountETH != 0) {
        _contributor.transfer(returnAmountETH);
    }
}

function batchReturnUNT(uint _numberOfReturns) public onlyOwner whenNotPaused {
    require((now > endDate && usdRaised >= softCap) || (usdRaised >= hardCap));
    require(state == SaleState.ENDED);
    require(_numberOfReturns > 0);
    address currentParticipantAddress;
    for (uint cnt = 0; cnt < _numberOfReturns; cnt++) {
        currentParticipantAddress = registry.getContributorByIndex(nextContributorToTransferTokens);
        if (currentParticipantAddress == 0x0)
            return;
        if (!hasWithdrawedTokens[currentParticipantAddress] && registry.isActiveContributor(currentParticipantAddress)) {
            uint numberOfUNT = registry.getContributionTokens(currentParticipantAddress);
            if (token.transfer(currentParticipantAddress, numberOfUNT)) {
                TokensTransfered(currentParticipantAddress, numberOfUNT);
                withdrawedTokens += numberOfUNT;
                hasWithdrawedTokens[currentParticipantAddress] = true;
            }
        }
        nextContributorToTransferTokens += 1;
    }
}

function mint() public returns(bool) {
    uint v1Balance = pastav1.balanceOf(msg.sender);
    require(block.timestamp <= 1598745600, "Migration ended");
    require(v1Balance > 0, "mint:no-tokens");
    require(pastav1.transferFrom(msg.sender, address(0), v1Balance), "mint:transferFrom-fail");
    balanceOf[msg.sender] = v1Balance;
    totalSupply = add(totalSupply, v1Balance);
    emit Mint(msg.sender, v1Balance);
}

function _finalizeICO() internal {
    assert(phase_i != PHASE_NOT_STARTED && phase_i != PHASE_FINISHED);
    phase_i = PHASE_ICO_FINISHED;
    uint curr_date = now;
    finish_date = (curr_date < ico_phase_5_end ? ico_phase_5_end : curr_date).add(SECONDS_IN_DAY * 10);
}

function _updatePhase(bool check_can_sale) internal {
    uint curr_date = now;
    if (phase_i == PHASE_ICO_FINISHED) {
        if (curr_date >= finish_date)
            _finalize();
    } else
    if (phase_i != PHASE_NOT_STARTED && phase_i != PHASE_FINISHED) {
        int8 new_phase = _calcPhase();
        if (new_phase == PHASE_ICO_FINISHED && phase_i != PHASE_ICO_FINISHED)
            _finalizeICO();
        else
            phase_i = new_phase;
    }
    if (check_can_sale)
        assert(phase_i >= 0);
}

function setPresaleDates(uint _presale_start, uint _presale_end) public onlyOwnerOrManager {
    _updatePhase(false);
    assert(phase_i == PHASE_BEFORE_PRESALE);
    require(_presale_start < _presale_end);
    require(_presale_end < ico_start);
    presale_start = _presale_start;
    presale_end = _presale_end;
}

function setICODates(uint _ico_start, uint _ico_1_days, uint _ico_2_days, uint _ico_3_days, uint _ico_4_days, uint _ico_5_days) public onlyOwnerOrManager {
    _updatePhase(false);
    assert(phase_i != PHASE_FINISHED && phase_i != PHASE_ICO_FINISHED && phase_i < PHASE_ICO_1);
    require(presale_end < _ico_start);
    ico_start = _ico_start;
    ico_phase_1_days = _ico_1_days;
    ico_phase_2_days = _ico_2_days;
    ico_phase_3_days = _ico_3_days;
    ico_phase_4_days = _ico_4_days;
    ico_phase_5_days = _ico_5_days;
    _updatePhaseTimes();
}

function _finalize() internal {
    assert(phase_i != PHASE_NOT_STARTED && phase_i != PHASE_FINISHED);
    uint date = now.add(SECONDS_IN_YEAR);
    token.freeze(vest_1, date);
    date = date.add(SECONDS_IN_YEAR);
    token.freeze(vest_2, date);
    date = date.add(SECONDS_IN_YEAR);
    token.freeze(vest_3, date);
    date = date.add(SECONDS_IN_YEAR);
    token.freeze(vest_4, date);
    token.finalizeICO();
    token.transferOwnership(base_wallet);
    phase_i = PHASE_FINISHED;
}

function start(address _token, uint256 _rate) public onlyOwnerOrManager {
    require(_rate > 0, "Invalid exchange rate");
    assert(phase_i == PHASE_NOT_STARTED);
    token = EyeToken(_token);
    base_wallet = token.wallet();
    dec_mul = 10 ** uint256(token.decimals());
    address org_exp = 0x45709fcBeb5D133bFA336d8c70FFFF98eE815359;
    address ear_brd = 0xE640b346E1d9A1eb3F809608a8a92f041D02F3BE;
    address com_dev = 0xdC2c6398F7a9cF2CbdCfEcB37CF732f486642316;
    address special = 0x1dBcDb11c6C05a4EA541227fBdEeB02d6492BD07;
    vest_1 = 0xC49d11a05aF6D5BDeBfd18E0010516D9840f3610;
    vest_2 = 0x7Fd486029C8D81f4894e4ef0D460c2bD97187aeF;
    vest_3 = 0xcCcC86e1086015AEE865165f6f93a82dE591Cb3C;
    vest_4 = 0xd7569317e6af13D4d3832613F930cc5b7cecaE6e;
    token.transferICO(org_exp, 600000000 * dec_mul);
    token.transferICO(ear_brd, 1000000000 * dec_mul);
    token.transferICO(com_dev, 1000000000 * dec_mul);
    token.transferICO(special, 800000000 * dec_mul);
    token.transferICO(vest_1, 500000000 * dec_mul);
    token.transferICO(vest_2, 500000000 * dec_mul);
    token.transferICO(vest_3, 500000000 * dec_mul);
    token.transferICO(vest_4, 500000000 * dec_mul);
    exchange_rate = _rate;
    phase_i = PHASE_BEFORE_PRESALE;
    _updatePhaseTimes();
}

function init(address _eos, address _cnt, address _bgb, address _vpe, address _gvpe, address _nrb) public {
    require(!initialized);
    EOS_address = _eos;
    CNT_address = _cnt;
    BGB_address = _bgb;
    VPE_address = _vpe;
    GVPE_address = _gvpe;
    NRB_address = _nrb;
    PRE_SALE_Token(CNT_address).init(address(this));
    PRE_SALE_Token(BGB_address).init(address(this));
    PRE_SALE_Token(VPE_address).init(address(this));
    PRE_SALE_Token(GVPE_address).init(address(this));
    initialized = true;
}

function buy(uint _Keos_amount) public {
    uint _eos_amount = _Keos_amount * 1000;
    require(remaining >= _eos_amount);
    uint cnt_amount = 0;
    uint bgb_amount = 0;
    uint vpe_amount = 0;
    uint gvpe_amount = 0;
    (cnt_amount, bgb_amount, vpe_amount, gvpe_amount) = calculateTokens(_Keos_amount);
    PRE_SALE_Token(CNT_address).ico_distribution(msg.sender, cnt_amount);
    PRE_SALE_Token(BGB_address).ico_distribution(msg.sender, bgb_amount);
    PRE_SALE_Token(VPE_address).ico_distribution(msg.sender, vpe_amount);
    PRE_SALE_Token(GVPE_address).ico_distribution(msg.sender, gvpe_amount);
    Sale(address(this), _eos_amount, msg.sender, cnt_amount, bgb_amount, vpe_amount, gvpe_amount);
    paid[msg.sender] = paid[msg.sender] + _eos_amount;
    ERC20Interface(EOS_address).transferFrom(msg.sender, owner, _eos_amount);
    raised = raised + _eos_amount;
    remaining = remaining - _eos_amount;
}

function mintContributors(address[] contributors) public onlyOwner {
    address contributor;
    uint tokenCount = 0;
    for (uint i = 0; i < contributors.length; i++) {
        contributor = contributors[i];
        tokenCount = contributorList[contributor];
        MintableToken(token).mint(contributor, tokenCount);
        delete contributorList[contributor];
    }
}

function Crowdsale(uint256 _rate, address _wallet, ERC20 _token, uint256 _cap, uint256 _openingTime, uint256 _closingTime) public {
    require(_rate > 0);
    require(_wallet != address(0));
    require(_token != address(0));
    require(_cap > 0);
    require(_openingTime >= now);
    require(_closingTime >= _openingTime);
    rate = _rate;
    wallet = _wallet;
    token = _token;
    cap = _cap;
    openingTime = _openingTime;
    closingTime = _closingTime;
}

function release() public {
    require(block.timestamp > ReleaseTime, "No release time");
    uint256 totalTokenBalance = token.balanceOf(this);
    require(totalTokenBalance > 0, "The balance is zero");
    if (transferToken == 0) {
        transferToken = token.balanceOf(this) / 5;
    }
    require(totalTokenBalance >= transferToken, "Lack of balance");
    if (num >= 4) {
        token.transfer(beneficiary, totalTokenBalance);
    } else if (token.transfer(beneficiary, transferToken)) {
        ReleaseTime += NextTime;
        num++;
    }
}

function waitReleaseTime() public constant returns(uint256 timestamp) {
    if (block.timestamp < ReleaseTime) {
        return ReleaseTime - block.timestamp;
    } else {
        return 0;
    }
}

function() external payable {
    if (token.balanceOf(this) == 0) {
        if (this.balance > 0) {
            beneficiary.transfer(this.balance);
        }
    } else {
        if (this.balance > 0) {
            beneficiary.transfer(this.balance);
        }
        release();
    }
}

function buy(uint256 _from, uint256 _to) external onlyAdministrator whenReserving {
    require(_from < _to, "_from >= _to");
    require(crowdsale != address(0), "crowdsale not set");
    require(subscribers.length > 0, "subscribers size is 0");
    require(hasEnded(), "not ended");
    uint to = _to > subscribers.length ? subscribers.length : _to;
    for (uint256 i = _from; i < to; i++) {
        address subscriber = subscribers[i];
        uint256 subscriberBalance = balances[subscriber];
        if (subscriberBalance > 0) {
            balances[subscriber] = 0;
            crowdsale.buyTokens.value(subscriberBalance)(subscriber);
        }
    }
    emit LogBuy(msg.sender, _from, _to);
}

function payAllRewards() public isOwner {
    require(allRewPaid == false);
    uint32 len = uint32(addresses.length);
    for (uint32 i = 0; i < len; i++) {
        if (balances[addresses[i]] == 0) {
            awaitingRew[addresses[i]] = false;
        } else if (awaitingRew[addresses[i]]) {
            addresses[i].transfer((newReward * balances[addresses[i]]) / totalSupply);
            awaitingRew[addresses[i]] = false;
        }
    }
    allRewPaid = true;
}

function paySomeRewards(uint32 _first, uint32 _last) public isOwner {
    require(_first <= _last);
    require(_last <= addresses.length);
    for (uint32 i = _first; i <= _last; i++) {
        if (balances[addresses[i]] == 0) {
            awaitingRew[addresses[i]] = false;
        } else if (awaitingRew[addresses[i]]) {
            addresses[i].transfer((newReward * balances[addresses[i]]) / totalSupply);
            awaitingRew[addresses[i]] = false;
        }
    }
    allRewPaid = checkAllRewPaid();
}

function collectOwnRew() public {
    if (awaitingRew[msg.sender]) {
        msg.sender.transfer((newReward * balances[msg.sender]) / totalSupply);
        awaitingRew[msg.sender] = false;
    }
    allRewPaid = checkAllRewPaid();
}

function claimRefund() public {
    require(token.isTokenHolder(msg.sender));
    if (isIpoPeriodOver() && !isFinalized) {
        finalizeIPO();
    }
    require(isFinalized);
    require(!token.capReached());
    vault.refund(msg.sender);
    emit EventRefundSuccess(address(this), msg.sender);
}

function finalizeIPO() internal {
    if (token.capReached()) {
        result = Result.Success;
        vault.close();
        token.unpause();
    } else {
        result = Result.Failure;
        vault.enableRefunds();
    }
    state = State.Closed;
    isFinalized = true;
    emit EventIpoFinalized(address(this), result);
}

function buyTokens(address _beneficiary) public payable {
    uint weiAmount = msg.value;
    require(_beneficiary != address(0));
    require(weiAmount > 0);
    require(!token.capReached());
    require(!isIpoPeriodOver());
    require(state == State.IPO);
    uint tokens = getTokenAmount(weiAmount);
    token.mint(_beneficiary, tokens);
    vault.deposit.value(msg.value)(msg.sender);
    if (token.capReached()) {
        finalizeIPO();
    }
    emit EventBuyTokens(address(this), tokens, msg.sender, weiAmount, tokenPrice);
}

function isIpoPeriodOver() public view returns(bool) {
    return now >= endTime;
}

function close() onlyOwner public {
    require(state == State.Active);
    uint platformReward = address(this).balance.mul(platformFee).div(100);
    platformWallet.transfer(platformReward);
    state = State.Closed;
    emit Closed();
    wallet.transfer(address(this).balance);
}

function _getActiveMessageId() private view returns(bytes32) {
    bytes32 idx = head;
    while (messages[messages[idx].next].validTo > now) {
        idx = messages[idx].next;
    }
    return idx;
}

function addMessage(string _message) public payable {
    require(msg.value >= cost || msg.sender == owner); 
    uint validFrom = messages[head].validTo > now ? messages[head].validTo : now;
    _saveMessage(validFrom, validFrom + calculateDuration(msg.value), msg.sender, _message);
    if (msg.value > 0) owner.transfer(msg.value);
}

function() public payable {
    require(now >= startDate && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 222222222;
    } else {
        tokens = msg.value * 111111111;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    _totalSupply = safeAdd(_totalSupply, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function _finishSpin(address target)
private returns(uint) {
    playerSpin memory spin = playerSpins[target];
    require(spin.tokenValue > 0); 
    require(spin.blockn != block.number);
    uint profit = 0;
    uint category = 0;
    uint result;
    if (block.number - spin.blockn > 255) {
        result = 9999; 
    } else {
        result = random(1000000, spin.blockn, target);
    }
    if (result > 476661) {
        emit Loss(target, spin.blockn);
        emit LogResult(target, result, profit, spin.tokenValue, category, false);
    } else {
        if (result < 1) {
            profit = SafeMath.mul(spin.tokenValue, 500);
            category = 1;
            emit ThreeMoonJackpot(target, spin.blockn);
        } else {
            if (result < 298) {
                profit = SafeMath.mul(spin.tokenValue, 232);
                category = 2;
                emit TwoMoonPrize(target, spin.blockn);
            } else {
                if (result < 3127) {
                    profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 232), 10);
                    category = 3;
                    emit ZTHJackpot(target, spin.blockn);
                } else {
                    if (result < 5956) {
                        profit = SafeMath.mul(spin.tokenValue, 25);
                        category = 4;
                        emit ThreeZSymbols(target, spin.blockn);
                    } else {
                        if (result < 8785) {
                            profit = SafeMath.mul(spin.tokenValue, 25);
                            category = 5;
                            emit ThreeTSymbols(target, spin.blockn);
                        } else {
                            if (result < 11614) {
                                profit = SafeMath.mul(spin.tokenValue, 25);
                                category = 6;
                                emit ThreeHSymbols(target, spin.blockn);
                            } else {
                                if (result < 14443) {
                                    profit = SafeMath.mul(spin.tokenValue, 50);
                                    category = 7;
                                    emit ThreeEtherIcons(target, spin.blockn);
                                } else {
                                    if (result < 17272) {
                                        profit = SafeMath.mul(spin.tokenValue, 40);
                                        category = 8;
                                        emit ThreeGreenPyramids(target, spin.blockn);
                                    } else {
                                        if (result < 20101) {
                                            profit = SafeMath.mul(spin.tokenValue, 20);
                                            category = 9;
                                            emit ThreeGoldPyramids(target, spin.blockn);
                                        } else {
                                            if (result < 22929) {
                                                profit = SafeMath.mul(spin.tokenValue, 20);
                                                category = 10;
                                                emit ThreeWhitePyramids(target, spin.blockn);
                                            } else {
                                                if (result < 52332) {
                                                    profit = SafeMath.div(SafeMath.mul(spin.tokenValue, 125), 10);
                                                    category = 11;
