}

function _rewardCalculation(address user, uint256 stakedAmount, uint256 interval, address stakedToken, uint256 totalStake) internal {
    uint256 rewardsEarned;
    uint256 noOfDays;
    noOfDays = interval.div(DAYS);
    rewardsEarned = noOfDays.mul(
        getOneDayReward(
            stakedAmount,
            stakedToken,
            stakedToken,
            totalStake
        )
    );
    sendToken(
        user,
        stakedToken,
        stakedToken,
        rewardsEarned
    );
    uint8 i = 1;
    while (i < intervalLength) {
        if (noOfDays >= intervalDays[i]) {
            uint256 balDays = noOfDays.sub((intervalDays[i].sub(1)));
            address rewardToken = UniV1.tokensSequenceList(stakedToken, i);
            if (rewardToken != stakedToken &&
                UniV1.tokenBlockedStatus(stakedToken, rewardToken) == false) {
                rewardsEarned = balDays.mul(
                    getOneDayReward(
                        stakedAmount,
                        stakedToken,
                        rewardToken,
                        totalStake
                    )
                );
                sendToken(
                    user,
                    stakedToken,
                    rewardToken,
                    rewardsEarned
                );
            }
            i = i + 1;
        } else {
            break;
        }
    }
}

function sendToken(address user, address stakedToken, address tokenAddress, uint256 amount) internal {
    if (tokenAddress != address(0)) {
        require(IERC20(tokenAddress).balanceOf(address(this)) >= amount, "SEND: Insufficient Balance in Contract");
        IERC20(tokenAddress).transfer(user, amount);
        emit Claim(
            user,
            stakedToken,
            tokenAddress,
            amount,
            block.timestamp
        );
    }
}

function claimRewards(address user, uint256 stakeTime, uint256 stakedAmount, address stakedToken, uint256 totalStake) internal {
    uint256 interval;
    interval = stakeTime.add(stakeDuration);
    if (interval > block.timestamp) {
        uint256 endOfProfit = block.timestamp;
        interval = endOfProfit.sub(stakeTime);
    } else {
        uint256 endOfProfit = stakeTime.add(stakeDuration);
        interval = endOfProfit.sub(stakeTime);
    }
    if (interval >= DAYS)
        _rewardCalculation(user, stakedAmount, interval, stakedToken, totalStake);
}

function unStake(address user, uint256 stakeId) external {
    require(msg.sender == user || msg.sender == owner(), "UNSTAKE: Invalid User Entry");
    (address[] memory tokenAddress, bool[] memory activeStatus, ,
        uint256[] memory stakedAmount, uint256[] memory startTime) = (UniV1.viewStakingDetails(user));
    uint totalStaking = UniV1.totalStaking(tokenAddress[stakeId]);
    if (unstakeStatus[user][stakeId] == false && activeStatus[stakeId] == true)
        unstakeStatus[user][stakeId] = true;
    else
        revert("UNSTAKE : Unstaked Already");
    if (contractAStatus == true) {
        if ((block.timestamp.sub(startTime[stakeId])).div(DAYS) <= 35)
            revert("UNSTAKE : Access denied in this Contract");
    }
    require(
        IERC20(tokenAddress[stakeId]).balanceOf(
            address(this)
        ) >= stakedAmount[stakeId],
        "UNSTAKE : Insufficient Balance"
    );
    uint totalUnstake = totalUnStakingB[tokenAddress[stakeId]].add(totalUnStakingA[tokenAddress[stakeId]]);
    totalUnStakingB[tokenAddress[stakeId]] = totalUnStakingB[tokenAddress[stakeId]].add(stakedAmount[stakeId]);
    IERC20(tokenAddress[stakeId]).transfer(user, stakedAmount[stakeId]);
    claimRewards(user, startTime[stakeId], stakedAmount[stakeId], tokenAddress[stakeId], totalStaking.sub(totalUnstake));
    emit UnStake(
        user,
        tokenAddress[stakeId],
        stakeId,
        stakedAmount[stakeId],
        block.timestamp
    );
}

function emergencyUnstake(uint256 stakeId, address userAddress, address[] memory rewardtokens, uint256[] memory amount) external onlyOwner {
    (address[] memory tokenAddress, bool[] memory activeStatus, ,
        uint256[] memory stakedAmount, ) = (UniV1.viewStakingDetails(userAddress));
    if (unstakeStatus[userAddress][stakeId] == false && activeStatus[stakeId] == true)
        unstakeStatus[userAddress][stakeId] = true;
    else
        revert("EMERGENCY: Unstaked Already");
    require(
        IERC20(tokenAddress[stakeId]).balanceOf(
            address(this)
        ) >= stakedAmount[stakeId],
        "EMERGENCY : Insufficient Balance"
    );
    unstakeStatus[userAddress][stakeId] = true;
    IERC20(tokenAddress[stakeId]).transfer(userAddress, stakedAmount[stakeId]);
    for (uint i; i < rewardtokens.length; i++) {
        require(IERC20(rewardtokens[i]).balanceOf(
                address(this)
            ) >= amount[i],
            "EMERGENCY : Insufficient Reward Balance"
        );
        IERC20(rewardtokens[i]).transfer(userAddress, amount[i]);
    }
    totalUnStakingB[tokenAddress[stakeId]] = totalUnStakingB[tokenAddress[stakeId]].add(stakedAmount[stakeId]);
    emit UnStake(
        userAddress,
        tokenAddress[stakeId],
        stakeId,
        stakedAmount[stakeId],
        block.timestamp
    );
}

function buyHLPMT() external {
    uint256 _currentTime = now;
    uint256 _allowed = token.allowance(msg.sender, address(this));
    uint256 _currentPrice = getPrice(_currentTime);
    require(_allowed >= _currentPrice);
    uint256 _hlpmtAmount = _allowed.div(_currentPrice);
    _allowed = _hlpmtAmount.mul(_currentPrice);
    require(token.transferFrom(msg.sender, fund, _allowed));
    for (uint256 i = 0; i < _hlpmtAmount; i++) {
        uint256 _id = miningToken.totalSupply();
        miningToken.mint(msg.sender, _id);
        lastGettingReward[_id] = numOfMiningTimes;
    }
}

function getPrice(uint256 _timestamp) public view returns(uint256) {
    uint256 _raising = _timestamp.sub(startTime).div(30 days);
    _raising = _raising.mul(stepForPrice);
    if (_raising > maxHLPMTMarkup) _raising = maxHLPMTMarkup;
    return (startPriceForHLPMT + _raising) * 10 ** 18;
}

function mining() external {
    uint256 _currentTime = now;
    require(_currentTime > _getEndOfLastMiningDay());
    uint256 _missedDays = (_currentTime - lastMiningTime) / (1 days);
    updateLastMiningTime(_currentTime);
    for (uint256 i = 0; i < _missedDays; i++) {
        uint256 _dailyTokens = token.getMaxTotalSupply().sub(token.totalSupply()).div(1000);
        uint256 _tokensToDao = _dailyTokens.mul(3).div(10); 
        token.mint(dao, _tokensToDao);
        uint256 _tokensToFund = _dailyTokens.mul(3).div(10); 
        token.mint(fund, _tokensToFund);
        uint256 _miningTokenSupply = miningToken.totalSupply();
        uint256 _tokensToMiners = _dailyTokens.mul(4).div(10); 
        uint256 _tokensPerMiningToken = _tokensToMiners.div(_miningTokenSupply);
        miningReward[++numOfMiningTimes] = _tokensPerMiningToken;
        token.mint(address(this), _tokensToMiners);
    }
}

function withdrawPayments() public {
    address payee = msg.sender;
    uint256 payment = payments[payee];
    uint256 timestamp = paymentsTimestamps[payee];
    require(payment != 0);
    require(now >= timestamp);
    payments[payee] = 0;
    require(token.transfer(msg.sender, payment));
}

function getReward(uint256[] tokensForReward) external {
    uint256 _rewardAmount = 0;
    for (uint256 i = 0; i < tokensForReward.length; i++) {
        if (
            msg.sender == miningToken.ownerOf(tokensForReward[i]) &&
            numOfMiningTimes > getLastRewardTime(tokensForReward[i])
        ) {
            _rewardAmount += _calculateReward(tokensForReward[i]);
            setLastRewardTime(tokensForReward[i], numOfMiningTimes);
        }
    }
    require(_rewardAmount > 0);
    token.transfer(msg.sender, _rewardAmount);
}

function sendReward(uint256[] tokensForReward) public onlyOwner {
    for (uint256 i = 0; i < tokensForReward.length; i++) {
        if (numOfMiningTimes > getLastRewardTime(tokensForReward[i])) {
            uint256 reward = _calculateReward(tokensForReward[i]);
            setLastRewardTime(tokensForReward[i], numOfMiningTimes);
            token.transfer(miningToken.ownerOf(tokensForReward[i]), reward);
        }
    }
}

function() payable public {
    require(now < ExerciseEndTime);
    require(topTotalSupply > totalSupply);
    bool firstCallReward = false;
    uint epochNow = whichEpoch(block.number);
    if (epochNow != epochLast) {
        lastEpochBlock = safeAdd(lastEpochBlock, ((block.number - lastEpochBlock) / initBlockEpoch + 1) * initBlockEpoch);
        doReward();
        eachPUSTprice = calcpustprice(epochNow, epochLast);
        epochLast = epochNow;
        firstCallReward = true;
        lastEpochTX = 0;
    }
    uint _value = msg.value;
    uint _PUST = _value / eachPUSTprice;
    require(_PUST > 0);
    if (safeAdd(totalSupply, _PUST) > topTotalSupply) {
        _PUST = safeSub(topTotalSupply, totalSupply);
    }
    uint _refound = _value - safeMul(_PUST, eachPUSTprice);
    if (_refound > 0) {
        msg.sender.transfer(_refound);
    }
    officialAddress.transfer(safeMul(_PUST, eachPUSTprice));
    balances[msg.sender] = safeAdd(balances[msg.sender], _PUST);
    totalSupply = safeAdd(totalSupply, _PUST);
    emit Transfer(address(this), msg.sender, _PUST);
    if (lastCallAddress == address(0) && epochLast == 0) {
        firstCallReward = true;
    }
    if (firstCallReward) {
        uint _firstReward = 0;
        _firstReward = (_PUST - 1) * 2 / 10 + 1;
        if (safeAdd(totalSupply, _firstReward) > topTotalSupply) {
            _firstReward = safeSub(topTotalSupply, totalSupply);
        }
        balances[msg.sender] = safeAdd(balances[msg.sender], _firstReward);
        totalSupply = safeAdd(totalSupply, _firstReward);
        emit Reward(address(this), msg.sender, _firstReward);
    }
    lastEpochTX += 1;
    lastCallAddress = msg.sender;
    lastCallPUST = _PUST;
    lastEpochBlock = safeAdd(lastEpochBlock, eachUserWeight);
}

function exerciseOption(uint _pustBalance) public returns(bool) {
    require(now < ExerciseEndTime);
