}

function burn(uint128 wad) public auth stoppable note {
    assert(owner == msg.sender);
    _balances[msg.sender] = sub(_balances[msg.sender], wad);
    _supply = sub(_supply, wad);
}

function collectTokens() public onlyOwner {
    uint256 balance = miniMeToken.balanceOf(address(this));
    uint256 total = collectedTokens.add(balance);
    uint256 finalizedTime = crowdsale.finalizedTime();
    require(finalizedTime > 0 && getTime() > finalizedTime.add(months(2)));
    uint256 canExtract = 0;
    if (getTime() <= finalizedTime.add(months(3))) {
        require(collectedTokens < total.percent(20));
        canExtract = total.percent(20);
    } else if (getTime() > finalizedTime.add(months(3)) && getTime() <= finalizedTime.add(months(4))) {
        require(collectedTokens < total.percent(40));
        canExtract = total.percent(40);
    } else if (getTime() > finalizedTime.add(months(4)) && getTime() <= finalizedTime.add(months(5))) {
        require(collectedTokens < total.percent(60));
        canExtract = total.percent(60);
    } else if (getTime() > finalizedTime.add(months(5)) && getTime() <= finalizedTime.add(months(6))) {
        require(collectedTokens < total.percent(80));
        canExtract = total.percent(80);
    } else {
        canExtract = total;
    }
    canExtract = canExtract.sub(collectedTokens);
    if (canExtract > balance) {
        canExtract = balance;
    }
    collectedTokens = collectedTokens.add(canExtract);
    miniMeToken.transfer(owner, canExtract);
    TokensWithdrawn(owner, canExtract);
}

function stake(uint256 _amount) public payable {
    require(paused == false, "E09");
    require(block.timestamp >= stakingStart, "E07");
    require(block.timestamp <= stakingClosed, "E08");
    require(currentStakers < maximumStakers, "E09");
    require(_amount % minimumStake == 0, 'E10');
    StakerInfo storage user = stakerInfo[msg.sender];
    require(user.amount.add(_amount) >= minimumStake, "E01");
    require(dnxcToken.transferFrom(msg.sender, address(this), _amount), "E02");
    uint256 count = _amount.div(minimumStake);
    require(msg.value >= stakingFee.mul(count), "E04");
    currentStakers = currentStakers.add(count);
    if (user.amount == 0) {
        user.startStakeTime = block.timestamp;
    }
    user.amount = user.amount.add(_amount);
    user.count = user.count.add(count);
    user.amounts.push(user.amount);
    user.times.push(block.timestamp);
}

function unstake() public {
    require(emergencyUnstake || block.timestamp >= stakingEnd || block.timestamp <= stakingClosed, "E08");
    StakerInfo storage user = stakerInfo[msg.sender];
    dnxcToken.transfer(
        msg.sender,
        user.amount
    );
    currentStakers = currentStakers.sub(user.count);
    user.amount = 0;
    user.count = 0;
}

