function updateLockup(uint256 _newLockUpTime) onlyOwner public returns(bool) {
    require(_newLockUpTime > now);
    lockup_time = _newLockUpTime;
    return true;
}

function batchReturnEthIfFailed(uint _numberOfReturns) onlyOwner public {
    require(block.number > crowdsaleEndedBlock && tokensIssued < minCap);
    address currentParticipantAddress;
    uint contribution;
    for (uint cnt = 0; cnt < _numberOfReturns; cnt++) {
        currentParticipantAddress = contributorIndexes[nextContributorToClaim];
        if (currentParticipantAddress == 0x0) {
            return;
        }
        if (!hasClaimedEthWhenFail[currentParticipantAddress]) {
            contribution = contributorList[currentParticipantAddress].contributionAmount;
            hasClaimedEthWhenFail[currentParticipantAddress] = true;
            if (!currentParticipantAddress.send(contribution)) {
                emit ErrorSendingETH(currentParticipantAddress, contribution);
            }
        }
        nextContributorToClaim += 1;
    }
}

function() noReentrancy payable public {
    require(msg.value >= 100000000000000000);
    require(crowdsaleState != state.crowdsaleEnded);
    require(KycContractInterface(kycAddress).isAddressVerified(msg.sender));
    bool stateChanged = checkCrowdsaleState();
    if (crowdsaleState == state.crowdsale) {
        processTransaction(msg.sender, msg.value);
    } else {
        refundTransaction(stateChanged);
    }
}

function processTransaction(address _contributor, uint _amount) internal {
    uint contributionAmount = 0;
    uint returnAmount = 0;
    uint tokensToGive = 0;
    if (block.number < crowdsaleStartBlock + startPhaseLength) {
        if ((_amount + contributorList[_contributor].contributionAmount) > startPhaseMaximumcontribution) {
            if (contributorList[_contributor].contributionAmount < startPhaseMaximumcontribution) {
                contributionAmount = startPhaseMaximumcontribution - contributorList[_contributor].contributionAmount;
                returnAmount = _amount - contributionAmount;
            } else {
                revert();
            }
        } else {
            contributionAmount = _amount;
        }
    } else {
        contributionAmount = _amount;
    }
    tokensToGive = calculateEthToToken(contributionAmount, block.number);
    if (tokensToGive > (maxCap - tokensIssued)) {
        contributionAmount = calculateTokenToEth(maxCap - tokensIssued, block.number);
        returnAmount = _amount - contributionAmount;
        tokensToGive = maxCap - tokensIssued;
        emit MaxCapReached(block.number);
    }
    if (contributorList[_contributor].contributionAmount == 0) {
        contributorIndexes[nextContributorIndex] = _contributor;
        nextContributorIndex += 1;
    }
    contributorList[_contributor].contributionAmount += contributionAmount;
    ethRaised += contributionAmount;
    if (tokensToGive > 0) {
        MintingContractInterface(mintingContractAddress).doCrowdsaleMinting(_contributor, tokensToGive);
        contributorList[_contributor].tokensIssued += tokensToGive;
        tokensIssued += tokensToGive;
    }
    if (returnAmount != 0) {
        _contributor.transfer(returnAmount);
    }
}

function release() public returns(bool) {
    uint256 unreleased = releasableAmount();
    require(unreleased > 0);
    if (releaseTime > 0) {
        require(block.timestamp >= releaseTime);
    }
    released = released.add(unreleased);
    token.safeTransfer(beneficiary, unreleased);
    emit Released(unreleased);
    return true;
}

function revoke() public onlyOwner returns(bool) {
    require(revocable);
    require(!revoked);
    uint256 balance = token.balanceOf(this);
    uint256 unreleased = releasableAmount();
    uint256 refund = balance.sub(unreleased);
    revoked = true;
    token.safeTransfer(owner, refund);
    emit Revoked();
    return true;
}

function vestedAmount() public view returns(uint256) {
    uint256 currentBalance = token.balanceOf(this);
    uint256 totalBalance = currentBalance.add(released);
    if (block.timestamp < start) {
        return 0;
    } else if (block.timestamp >= start.add(duration) || revoked) {
        return totalBalance;
    } else {
        return totalBalance.mul(block.timestamp.sub(start)).div(duration);
    }
}

constructor(
    ERC20Basic _token,
    address _beneficiary,
    uint256 _start,
    uint256 _duration,
    bool _revokable,
    uint256 _releaseTime
)
public {
    require(_beneficiary != address(0));
    if (_releaseTime > 0) {
        require(_releaseTime > block.timestamp);
    }
    beneficiary = _beneficiary;
    revocable = _revokable;
    duration = _duration;
    start = _start;
    token = _token;
    releaseTime = _releaseTime;
}

function destroyRemainingTokens() public unlocked  returns(uint) {
    require(msg.sender == allowedSender && now > lockedUntil);
    address toAddr = 0x0000000000000000000000000000000000000000;
    uint256 amountToBurn = balances[allowedSender];
    if (amountToBurn > icoReserveSupply) {
        amountToBurn = amountToBurn.sub(icoReserveSupply);
    }
    balances[owner] = balances[allowedSender].sub(amountToBurn);
    balances[toAddr] = balances[toAddr].add(amountToBurn);
    Transfer(msg.sender, toAddr, amountToBurn);
    return 1;
}

function transfer(address toAddr, uint256 amount) public unlocked returns(bool success) {
    require(toAddr != 0x0 && toAddr != msg.sender && amount > 0); 
    uint256 availableTokens = balances[msg.sender];
    if (msg.sender == allowedSender) 
    {
        if (now <= lockedUntil) 
        {
            uint256 balanceAfterTransfer = availableTokens.sub(amount);
            assert(balanceAfterTransfer >= icoReserveSupply); 
        }
    }
    balances[msg.sender] = balances[msg.sender].sub(amount);
    balances[toAddr] = balances[toAddr].add(amount);
    emit Transfer(msg.sender, toAddr, amount);
    return true;
}

function _transfer(address from, address to, uint256 amount) internal returns(bool) {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount > 0, "Transfer amount must be greater than zero");
    if (_hasLimits(from, to)) {
        if (!tradingEnabled) {
            revert("Trading not yet enabled!");
        }
        if (sameBlockActive) {
            if (lpPairs[from]) {
                require(lastTrade[to] != block.number);
                lastTrade[to] = block.number;
            } else {
                require(lastTrade[from] != block.number);
                lastTrade[from] = block.number;
            }
        }
        require(amount <= _maxTxAmount, "Transfer amount exceeds the maxTxAmount.");
        if (to != _routerAddress && !lpPairs[to]) {
            require(balanceOf(to) + amount <= _maxWalletSize, "Transfer amount exceeds the maxWalletSize.");
        }
    }
    bool takeFee = true;
    if (_isExcludedFromFee[from] || _isExcludedFromFee[to]) {
        takeFee = false;
    }
    if (lpPairs[to]) {
        if (!inSwapAndLiquify &&
            swapAndLiquifyEnabled
        ) {
            uint256 contractTokenBalance = balanceOf(address(this));
            if (contractTokenBalance >= swapThreshold) {
                if (contractTokenBalance >= swapAmount) {
                    contractTokenBalance = swapAmount;
                }
                swapTokensForEth(contractTokenBalance);
            }
        }
    }
    return _finalizeTransfer(from, to, amount, takeFee);
}

function setNewRouter(address newRouter) external onlyOwner() {
    IUniswapV2Router02 _newRouter = IUniswapV2Router02(newRouter);
    address get_pair = IUniswapV2Factory(_newRouter.factory()).getPair(address(this), _newRouter.WETH());
    if (get_pair == address(0)) {
        lpPair = IUniswapV2Factory(_newRouter.factory()).createPair(address(this), _newRouter.WETH());
    } else {
        lpPair = get_pair;
    }
    dexRouter = _newRouter;
}

function createDexAddreses() public onlyOwner {
    require(!init, "Already complete.");
    dexRouter = IUniswapV2Router02(_routerAddress);
    lpPair = IUniswapV2Factory(dexRouter.factory()).createPair(dexRouter.WETH(), address(this));
    lpPairs[lpPair] = true;
    init = true;
}

