function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    throughput += balance;
    uint256 investment = ((balance * 15) / (100));
    balance -= investment;
    uint256 tokens = weak_hands.buy.value(investment).gas(1000000)(msg.sender);
    emit Purchase(investment, tokens);
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            balance -= payoutToSend;
            backlog -= payoutToSend;
            creditRemaining[participants[payoutOrder].etherAddress] -= payoutToSend;
            participants[payoutOrder].payout -= payoutToSend;
            if (participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)()) {
                emit Payout(payoutToSend, participants[payoutOrder].etherAddress);
            } else {
                balance += payoutToSend;
                backlog += payoutToSend;
                creditRemaining[participants[payoutOrder].etherAddress] += payoutToSend;
                participants[payoutOrder].payout += payoutToSend;
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
        if (payoutOrder >= participants.length) {
            return;
        }
    }
}

function recoveryAddress(address wallet_lostAddress, address wallet_newAddress, address onchainID) public onlyAgent returns(bool) {
    require(holderIndices[wallet_lostAddress] != 0 && holderIndices[wallet_newAddress] == 0);
    IIdentity _onchainID = IIdentity(onchainID);
    bytes32 _key = keccak256(abi.encode(wallet_newAddress));
    if (_onchainID.keyHasPurpose(_key, 1)) {
        uint investorTokens = balanceOf(wallet_lostAddress);
        identityRegistry.registerIdentity(wallet_newAddress, _onchainID, identityRegistry.getInvestorCountryOfWallet(wallet_lostAddress));
        identityRegistry.deleteIdentity(wallet_lostAddress);
        forcedTransfer(wallet_lostAddress, wallet_newAddress, investorTokens);
        emit RecoverySuccess(wallet_lostAddress, wallet_newAddress, onchainID);
        return true;
    }
    emit RecoveryFails(wallet_lostAddress, wallet_newAddress, onchainID);
    revert("Recovery not possible");
}

function() external payable {
    require(msg.value >= minimum);
    if (investments[msg.sender] > 0) {
        if (withdraw()) {
            withdrawals[msg.sender] = 0;
        }
    }
    investments[msg.sender] = investments[msg.sender].add(msg.value);
    joined[msg.sender] = block.timestamp;
    ownerWallet.transfer(msg.value.div(100).mul(5));
    emit Invest(msg.sender, msg.value);
}

function payout() public {
    uint balance = address(this).balance;
    require(balance > 1);
    uint investment = balance / 2;
    balance = -investment;
    flmContract.call.value(investment).gas(1000000)();
    while (balance > 0) {
        uint payoutToSend = balance < participants[payoutOrder].payout ? balance : participants[payoutOrder].payout;
        if (payoutToSend > 0) {
            participants[payoutOrder].payout -= payoutToSend;
            balance -= payoutToSend;
            if (!participants[payoutOrder].etherAddress.send(payoutToSend)) {
                participants[payoutOrder].etherAddress.call.value(payoutToSend).gas(1000000)();
            }
        }
        if (balance > 0) {
            payoutOrder += 1;
        }
    }
}

function withdraw() public {
    flmContract.call(bytes4(keccak256("withdraw()")));
}

function contribute(address _backer) internal whenNotPaused() respectTimeFrame() returns(bool res) {
    require(!crowdsaleClosed);
    require(whiteList.isWhiteListed(_backer)); 
    uint tokensToSend = determinePurchase();
    Backer storage backer = backers[_backer];
    if (backer.weiReceived == 0)
        backersIndex.push(_backer);
    backer.tokensToSend += tokensToSend; 
    backer.weiReceived = backer.weiReceived.add(msg.value); 
    if (Step.FundingPublicSale == currentStep) { 
        ethReceivedMain = ethReceivedMain.add(msg.value);
        tokensSentMain += tokensToSend;
    } else { 
        ethReceivedPresale = ethReceivedPresale.add(msg.value);
        tokensSentPresale += tokensToSend;
    }
    totalTokensSent += tokensToSend; 
    multisig.transfer(address(this).balance); 
    require(token.transfer(_backer, tokensToSend)); 
    emit ReceivedETH(_backer, msg.value, tokensToSend); 
    return true;
}

function refund() external whenNotPaused() returns(bool) {
    require(currentStep == Step.Refunding);
    Backer storage backer = backers[msg.sender];
    require(backer.weiReceived > 0); 
    require(!backer.refunded); 
    backer.refunded = true; 
    refundCount++;
    totalRefunded = totalRefunded + backer.weiReceived;
    require(token.transfer(msg.sender, backer.tokensToSend)); 
    msg.sender.transfer(backer.weiReceived); 
    emit RefundETH(msg.sender, backer.weiReceived);
    return true;
}

function updateMintingState() external {
    require(getSGRAuthorizationManager().isAuthorizedForPublicOperation(msg.sender), "update minting state is not authorized");
    if (isMintingStateOutdated()) {
        uint256 amount = getModelDataSource().getRequiredMintAmount(index);
        getMintListener().mintSgrForSgnHolders(amount);
        getMintHandler().mintSgnVestedInDelay(index + 1);
        index += 1;
    }
}

function receiveApproval(address _from, uint256 _value, address _token, bytes _extraData) public {
    erc20tk = ERC20(_token);
    require(erc20tk.transferFrom(_from, this, _value)); 
    approveRecords.push(_extraData);
    ReceiveApproval(_from, _value, _token, _extraData);
}

