function bid(uint256 _tokenId)
external
payable
whenNotPaused {
    uint256 lastIndex = latestAction[_tokenId];
    require(lastIndex > 0);
    Auction storage order = auctionArray[lastIndex];
    uint64 tmNow = uint64(block.timestamp);
    require(order.tmStart + auctionDuration > tmNow);
    require(order.tmSell == 0);
    address realOwner = tokenContract.ownerOf(_tokenId);
    require(realOwner == order.seller);
    require(realOwner != msg.sender);
    uint256 price = order.price * 1000000000;
    require(msg.value == price);
    order.tmSell = tmNow;
    auctionSumGwei += order.price;
    uint256 sellerProceeds = price.mul(9).div(10);
    uint256 devCut = price.sub(sellerProceeds);
    tokenContract.safeTransferByContract(_tokenId, msg.sender);
    _shareDevCut(devCut);
    realOwner.transfer(sellerProceeds);
    AuctionSold(lastIndex, realOwner, msg.sender, _tokenId, price);
}

function _shareDevCut(uint256 val) internal {
    uint256 shareVal = val.mul(6).div(10);
    uint256 leftVal = val.sub(shareVal);
    uint256 devVal = leftVal.div(2);
    accumulateFee = accumulateFee.add(shareVal);
    addrFinance.transfer(devVal);
    if (poolContract != address(0)) {
        poolContract.transfer(leftVal.sub(devVal));
    } else {
        accumulateFee = accumulateFee.add(leftVal.sub(devVal));
    }
}

function changePrice(uint256 _tokenId, uint64 _priceGwei) external whenNotPaused {
    require(tokenContract.ownerOf(_tokenId) == msg.sender);
    uint256 lastIndex = latestAction[_tokenId];
    require(lastIndex > 0);
    Auction storage order = auctionArray[lastIndex];
    require(order.seller == msg.sender);
    require(order.tmSell == 0);
    uint64 tmNow = uint64(block.timestamp);
    require(order.tmStart + auctionDuration > tmNow);
    require(_priceGwei >= 1000000 && _priceGwei <= 999000000000);
    order.price = _priceGwei;
    AuctionPriceChange(lastIndex, msg.sender, _tokenId, _priceGwei);
}

function updateShares()
external
{
    uint256 currentFee = accumulateFee;
    var (addrArray, amountArray, soldAmount) = eostContract.getShareholders();
    require(soldAmount > 0);
    uint256 avg = currentFee.div(soldAmount);
    uint256 shareVal;
    address addrZero = address(0);
    address addrHolder;
    for (uint64 i = 0; i < 100; ++i) {
        addrHolder = addrArray[i];
        if (addrHolder == addrZero) {
            break;
        }
        shareVal = avg.mul(amountArray[i]);
        uint256 oldBalance = shareBalances[addrHolder];
        shareBalances[addrHolder] = oldBalance.add(shareVal);
        currentFee = currentFee.sub(shareVal);
    }
    assert(currentFee <= 100);
    accumulateFee = currentFee;
}

function cancelAuction(uint256 _tokenId) external whenNotPaused {
    require(tokenContract.ownerOf(_tokenId) == msg.sender);
    uint256 lastIndex = latestAction[_tokenId];
    require(lastIndex > 0);
    Auction storage order = auctionArray[lastIndex];
    require(order.seller == msg.sender);
    require(order.tmSell == 0);
    order.tmSell = 1;
    AuctionCancel(lastIndex, msg.sender, _tokenId);
}

function newAuction(uint256 _tokenId, uint64 _priceGwei)
external
whenNotPaused {
    require(tokenContract.ownerOf(_tokenId) == msg.sender);
    require(!equipContract.isEquiped(msg.sender, _tokenId));
    require(_priceGwei >= 1000000 && _priceGwei <= 999000000000);
    uint16[12] memory fashion = tokenContract.getFashion(_tokenId);
    require(fashion[1] > 1);
    uint64 tmNow = uint64(block.timestamp);
    uint256 lastIndex = latestAction[_tokenId];
    if (lastIndex > 0) {
        Auction storage oldOrder = auctionArray[lastIndex];
        require((oldOrder.tmStart + auctionDuration) <= tmNow || oldOrder.tmSell > 0);
    }
    if (address(platAuction) != address(0)) {
        require(!platAuction.isOnSale(_tokenId));
    }
    uint256 newAuctionIndex = auctionArray.length;
    auctionArray.length += 1;
    Auction storage order = auctionArray[newAuctionIndex];
    order.seller = msg.sender;
    order.tokenId = uint64(_tokenId);
    order.price = _priceGwei;
    uint64 lastActionStart = auctionArray[newAuctionIndex - 1].tmStart;
    if (tmNow >= lastActionStart) {
        order.tmStart = tmNow;
    } else {
        order.tmStart = lastActionStart;
    }
    latestAction[_tokenId] = newAuctionIndex;
    AuctionCreate(newAuctionIndex, msg.sender, _tokenId);
}

function checkCorrectPurchase() view internal {
    require(startTime < now && now < endTime);
    require(msg.value >= minDepositAmount);
    require(msg.value < maxDepositAmount);
    require(totalEtherRaised + msg.value < hardCapEther);
}

function cancelVesting() external onlyOwner {
    require(startTime > block.timestamp, "VESTING_ALREADY_STARTED");
    token.transfer(owner(), token.balanceOf(address(this)));
    startTime = ~uint256(0);
    releaseInterval = 0;
    totalReleaseCount = 0;
    paidAmount = 0;
    recipient = address(0);
}

function nextReleaseTimestamp() public view returns(uint256) {
    if (totalReleaseCount == 0 || releaseInterval == 0) {
        return 0;
    }
    if (startTime > block.timestamp) {
        return startTime.add(releaseInterval);
    }
    uint256 elapsedTime = block.timestamp.sub(startTime);
    uint256 pastReleaseCount = elapsedTime.div(releaseInterval);
    if (pastReleaseCount > totalReleaseCount) {
        return 0;
    }
    return startTime.add(releaseInterval.mul(pastReleaseCount + 1));
}

function claimRewards(
    address user,
    uint256 stakeId,
    uint256 totalStaking
) internal {
    (
        address[] memory referrerAddress,
        address[] memory tokenAddress, , , ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (uniV3.viewStakingDetails(user));
    uint256 interval;
    uint256 endOfProfit;
    interval = poolStartTime.add(uniV3.stakeDuration());
    if (interval > block.timestamp) endOfProfit = block.timestamp;
    else endOfProfit = poolStartTime.add(uniV3.stakeDuration());
    interval = endOfProfit.sub(startTime[stakeId]);
    if (interval >= HOURS)
        _rewardCalculation(
            user,
            referrerAddress[stakeId],
            tokenAddress[stakeId],
            stakedAmount[stakeId],
            interval,
            totalStaking
        );
}

function unStake(address user, uint256 stakeId) external whenNotPaused {
    require(
        msg.sender == user || msg.sender == _owner,
        "UNSTAKE: Invalid User Entry"
    );
    (,
        address[] memory tokenAddress,
        bool[] memory activeStatus, , ,
        uint256[] memory stakedAmount,
        uint256[] memory startTime
    ) = (uniV3.viewStakingDetails(user));
    bool isAlreadyUnstaked = uniV3Proxy.unstakeStatus(user, stakeId);
    require(
        u3UpgradeLockableDetails[tokenAddress[stakeId]].lockableDays <=
        block.timestamp,
        "Token Locked"
    );
    if (
        u3UpgradeLockableDetails[tokenAddress[stakeId]].optionableStatus ==
        true
    ) {
        require(
            poolStartTime.add(uniV3.stakeDuration()) <= block.timestamp,
            "Locked in optional lock"
        );
    }
    if (
        u3UnstakeStatus[user][stakeId] == false &&
        isAlreadyUnstaked == false &&
        activeStatus[stakeId] == true
    ) u3UnstakeStatus[user][stakeId] = true;
    else revert("UNSTAKE : Unstaked Already");
    (address stakedToken, uint256 totalStaking) = swapPaidToken(
        tokenAddress[stakeId]
    );
    u3UpgradeTotalUnStaking[stakedToken] = u3UpgradeTotalUnStaking[
        stakedToken
    ].add(stakedAmount[stakeId]);
    require(
        IERC20(stakedToken).balanceOf(address(this)) >=
        stakedAmount[stakeId],
        "UNSTAKE : Insufficient Balance"
    );
    IERC20(stakedToken).transfer(user, stakedAmount[stakeId]);
    if (startTime[stakeId] < poolStartTime.add(uniV3.stakeDuration())) {
        claimRewards(user, stakeId, totalStaking);
    }
    emit UnStake(
        user,
        stakedToken,
        stakedAmount[stakeId],
        block.timestamp,
        stakeId
    );
}

