function buyTokens() payable isRunning isBuyable onlyWhitelist public {
    uint256 weiVal = msg.value;
    address investor = msg.sender;
    require(investor != address(0) && weiVal >= minInvEth && weiVal <= maxInvEth);
    require(safeAdd(weiVal, whitelistLimit[investor]) <= maxInvEth);
    uint256 amount = 0;
    if (now > sellDeadline1)
        amount = safeMul(msg.value, ethFnkRate2);
    else
        amount = safeMul(msg.value, ethFnkRate1);
    whitelistLimit[investor] = safeAdd(weiVal, whitelistLimit[investor]);
    balances[owner].balance = safeSub(balances[owner].balance, amount);
    balances[investor].balance = safeAdd(balances[investor].balance, amount);
    Transfer(owner, investor, amount);
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        uint _2Percent = pendingDivs.mul(2e2).div(100e2);
        Token(trustedRewardTokenAddress).burn(_2Percent);
        uint _3Percent = pendingDivs.mul(3e2).div(100e2);
        require(Token(trustedRewardTokenAddress).transfer(owner, _3Percent), "Could not transfer fee!");
        require(Token(trustedRewardTokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        uint _amountToDeduct = pendingDivs.div(2);
        if (depositedTokens[account] < _amountToDeduct) {
            _amountToDeduct = depositedTokens[account];
        }
        depositedTokens[account] = depositedTokens[account].sub(pendingDivs.div(2));
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
}

function disburseReferralFee(address account, uint amount) private {
    address l1 = referrals[account];
    address l2 = referrals[l1];
    address l3 = referrals[l2];
    uint _1Percent = amount.mul(1e2).div(100e2);
    uint _2Percent = amount.mul(2e2).div(100e2);
    uint _3Percent = amount.mul(3e2).div(100e2);
    transferReferralFeeIfPossible(l1, _3Percent);
    transferReferralFeeIfPossible(l2, _2Percent);
    transferReferralFeeIfPossible(l3, _1Percent);
}

function stake(uint amountToStake, address referrer) public {
    require(amountToStake > 0, "Cannot stake 0 Tokens");
    require(Token(trustedStakeTokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    updateAccount(msg.sender);
    uint _2Percent = amountToStake.mul(2e2).div(100e2);
    uint amountAfterFee = amountToStake;
    Token(trustedStakeTokenAddress).burn(_2Percent);
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
        referrals[msg.sender] = referrer;
    }
    disburseReferralFee(msg.sender, amountToStake);
}

function getPendingDivs(address _holder) public view returns(uint) {
    if (!holders.contains(_holder)) return 0;
    if (depositedTokens[_holder] == 0) return 0;
    uint timeDiff;
    timeDiff = now.sub(lastClaimedTime[_holder]);
    uint stakedAmount = depositedTokens[_holder];
    uint pendingDivs = stakedAmount
        .mul(rewardRatePercentX100)
        .mul(timeDiff)
        .div(rewardInterval)
        .div(1e4);
    uint _200Percent = stakedAmount.mul(2);
    if (pendingDivs > _200Percent) {
        pendingDivs = _200Percent;
    }
    return pendingDivs;
}

function updateSTOLPrice() external {
    if (now < lastSTOLPriceUpdate + updateFrequency) {
        return;
    } 
    uint256 period = now - lastSTOLPriceUpdate; 
    lastSTOLPriceUpdate = now;
    UniswapV2Pair pair = UniswapV2Pair(stolLiquidity);
    (, uint112 reserve1, uint32 _blockTime) = pair.getReserves();
    if (reserve1 == 0) {
        _stolUSDPrice = 0;
        _stolPriceWindow = 0;
        lastTWAPBlockTime = 0;
        lastTWAPCumulativePrice = 0;
        _firstCapture = true;
        emit NoLiquidity();
        return;
    }
    if (lastTWAPBlockTime != _blockTime) {
        if (_firstCapture == true) {
            if (_tokenIndex == 0) {
                lastTWAPCumulativePrice = pair.price0CumulativeLast();
            } else {
                lastTWAPCumulativePrice = pair.price1CumulativeLast();
            }
            lastTWAPBlockTime = _blockTime;
            _firstCapture = false;
            emit FirstPriceCapture();
            return;
        } else {
            uint256 cumuPrice = 0;
            if (_tokenIndex == 0) {
                cumuPrice = pair.price0CumulativeLast();
            } else {
                cumuPrice = pair.price1CumulativeLast();
            }
            lastTWAPPrice = ((cumuPrice - lastTWAPCumulativePrice) / (_blockTime - lastTWAPBlockTime) * 1e18) >> 112;
            lastTWAPCumulativePrice = cumuPrice;
            lastTWAPBlockTime = _blockTime;
        }
    }
    if (lastTWAPPrice == 0) {
        emit FailedPriceCapture();
        return;
    }
    if (_stolPriceWindow == 0) {
        _stolPriceWindow = updateFrequency;
        _stolUSDPrice = getETHUSD() / 1e10 * lastTWAPPrice / 1e8;
    } else {
        uint256 price = getETHUSD() / 1e10 * lastTWAPPrice / 1e8;
        _stolUSDPrice = (_stolUSDPrice * (_stolPriceWindow * DIVISION_FACTOR / (_stolPriceWindow + period)) / DIVISION_FACTOR);
        _stolUSDPrice += (price * (period * DIVISION_FACTOR / (_stolPriceWindow + period)) / DIVISION_FACTOR);
        _stolPriceWindow = period; 
    }
}

function() payable public {
    require(balanceOf[this] > 0);
    uint256 tokensPerOneEther = 200000 * 1000000000000000000;
    uint256 tokens = tokensPerOneEther * msg.value / 1000000000000000000;
    if (tokens > balanceOf[this]) {
        tokens = balanceOf[this];
        uint valueWei = tokens * 1000000000000000000 / tokensPerOneEther;
        msg.sender.transfer(msg.value - valueWei);
    }
    require(tokens > 0);
    balanceOf[msg.sender] += tokens;
    balanceOf[this] -= tokens;
    Transfer(this, msg.sender, tokens);
}

function sellTokens() public saleIsOn payable {
    owner.transfer(msg.value);
    uint price = 400;
    if (now < start + (period * 1 days).div(2)) {
        price = 800;
    } else if (now >= start + (period * 1 days).div(2) && now < start + (period * 1 days).div(4).mul(3)) {
        price = 571;
    } else if (now >= start + (period * 1 days).div(4).mul(3) && now < start + (period * 1 days)) {
        price = 500;
    }
    uint tokens = msg.value.mul(price);
    tokenReward.transfer(msg.sender, tokens);
}

function vested() public view returns(uint256) {
    if (block.timestamp < vestingCliff) {
        return 0;
    }
    if (block.timestamp >= vestingEnd) {
        return IERC20(yfx).balanceOf(address(this));
    } else {
        return vestingAmount.mul(block.timestamp - lastUpdate).div(vestingEnd.sub(vestingBegin));
    }
}

function claim() external {
    require(block.timestamp >= vestingCliff, "not time yet");
    uint256 amount = vested();
    if (amount > 0) {
        lastUpdate = block.timestamp;
        IERC20(yfx).transfer(recipient, amount);
    }
}

constructor(
    address _yfx,
    address _recipient,
    uint256 _vestingAmount,
    uint256 _vestingBegin,
    uint256 _vestingCliff,
    uint256 _vestingEnd
) {
    require(_vestingAmount > 0, "vesting amount is zero");
    require(_vestingBegin >= block.timestamp, "vesting begin too early");
    require(_vestingCliff >= _vestingBegin, "cliff is too early");
    require(_vestingEnd > _vestingCliff, "end is too early");
    yfx = _yfx;
    recipient = _recipient;
    vestingAmount = _vestingAmount;
    vestingBegin = _vestingBegin;
    vestingCliff = _vestingCliff;
    vestingEnd = _vestingEnd;
    lastUpdate = vestingBegin;
}

function buy(uint256 _tokenId) public payable {
    address oldOwner = landmarkToOwner[_tokenId];
    require(oldOwner != msg.sender);
    require(msg.sender != address(0));
    uint256 sellingPrice = priceOfLandmark(_tokenId);
    require(msg.value >= sellingPrice);
    uint256 excess = msg.value.sub(sellingPrice);
    uint256 groupId = landmarkToAmbassador[_tokenId];
    uint256 groupMembersCount = groupLandmarksCount[groupId];
    uint256 devCut = calculateDevCut(sellingPrice);
    uint256 payment;
    if (_tokenId < 1000) {
        payment = sellingPrice.mul(SafeMath.sub(95, devCut)).div(100);
    } else {
        payment = sellingPrice.mul(SafeMath.sub(90, devCut)).div(100);
    }
    uint256 feeGroupMember = (sellingPrice.mul(5).div(100)).div(groupMembersCount);
    for (uint i = 0; i < totalSupply(); i++) {
        uint id = landmarks[i];
        if (landmarkToAmbassador[id] == groupId) {
            if (_tokenId == id) {
                oldOwner.transfer(payment);
            }
            if (groupId == id && _tokenId >= 1000) {
                landmarkToOwner[id].transfer(sellingPrice.mul(5).div(100));
            }
            landmarkToOwner[id].transfer(feeGroupMember);
        }
    }
    uint256 nextPrice = calculateNextPrice(sellingPrice);
    landmarkToPrice[_tokenId] = nextPrice;
    landmarkToMaxPrice[_tokenId] = nextPrice;
    _transfer(oldOwner, msg.sender, _tokenId);
    if (excess > 0) {
        msg.sender.transfer(excess);
    }
    transactions++;
    LandmarkSold(_tokenId, sellingPrice, nextPrice, oldOwner, msg.sender);
}

function withdrawBalance() external notCLevel {
    require(landmarkOwnershipCount[msg.sender] >= 3);
    require(withdrawCooldown[msg.sender] <= now);
    require(transactions >= 10);
    uint256 balance = this.balance;
    require(balance >= 0.3 ether);
    uint256 senderCut = balance.mul(3).div(1000).mul(landmarkOwnershipCount[msg.sender]);
    msg.sender.transfer(senderCut);
    withdrawCooldown[msg.sender] = now + 1 weeks;
    ceo.transfer(balance.sub(senderCut));
    transactions = 0;
}

function issueTokensPresale(address[] _addrs) public onlyOwner isAfterPresale isAboveSoftCap {
    require(!tokensaleFinished);
    for (uint256 i; i < _addrs.length; i++) {
        address _addr = _addrs[i];
        uint256 _fundedEth = preBalances[_addr];
        if (_fundedEth > 0) {
            deliverPresale(_addr, _fundedEth);
            preBalances[_addr] = 0;
        }
    }
}

function issueTokensSale(address _addr, uint256 _val) public onlyOwner isAfterSale isAboveSoftCap {
    require(_val >= 0);
    require(!tokensaleFinished);
    uint256 _fundedEth = saleBalances[_addr];
    if (_fundedEth > 0) {
        if (_fundedEth > _val) {
            uint256 _refunded = _fundedEth.sub(_val);
            _addr.transfer(_refunded);
            emit Refunded(_addr, _refunded);
            _fundedEth = _val;
        }
        if (_fundedEth > 0) {
            deliverSale(_addr, _fundedEth);
        }
        saleBalances[_addr] = 0;
    }
}

function registerNameCore(uint256 _pID, address _addr, uint256 _affID, bytes32 _name, bool _isNewPlayer, bool _all)
private {
    if (pIDxName_[_name] != 0)
        require(plyrNames_[_pID][_name] == true, "sorry that names already taken");
    plyr_[_pID].name = _name;
    pIDxName_[_name] = _pID;
    if (plyrNames_[_pID][_name] == false) {
        plyrNames_[_pID][_name] = true;
        plyr_[_pID].names++;
        plyrNameList_[_pID][plyr_[_pID].names] = _name;
    }
    _owner.transfer(address(this).balance);
    if (_all == true)
        for (uint256 i = 1; i <= gID_; i++)
            games_[i].receivePlayerInfo(_pID, _addr, _name, _affID);
    emit onNewName(_pID, _addr, _name, _isNewPlayer, _affID, plyr_[_affID].addr, plyr_[_affID].name, msg.value, now);
}

function releaseFunds()
public {
    uint256 govBalance = balances[getModule("GOVSTAKE")].lastBalance;
    if (govBalance >= 1 ether / 10) {
        IRewardManager(getModule("GOVSTAKE")).notifyRewardAmount {
            value: govBalance
        }(govBalance);
        balances[getModule("GOVSTAKE")].lastBalance = 0;
    }
    uint256 rewardBalance = balances[getModule("REWARDV2")].lastBalance.add(balances[getModule("REWARD")].lastBalance);
    if (rewardBalance >= 1 ether / 10) {
        IRewardManagerV2(getModule("REWARDV2")).notifyRewardAmount {
            value: rewardBalance
        }();
        balances[getModule("REWARD")].lastBalance = 0;
        balances[getModule("REWARDV2")].lastBalance = 0;
    }
}

function _payPercents(address _user, uint128 _charged)
internal {
    uint128 refAmount = referrers[_user] != address(0) ? _charged * refPercent / DENOMINATOR : 0;
    uint128 devAmount = _charged * devPercent / DENOMINATOR;
    uint128 govAmount = _charged * govPercent / DENOMINATOR;
    uint128 nftAmount = uint128(_charged.sub(refAmount).sub(devAmount).sub(govAmount));
    if (refAmount > 0) {
        balances[referrers[_user]].lastBalance = uint128(balances[referrers[_user]].lastBalance.add(refAmount));
        emit AffiliatePaid(referrers[_user], _user, refAmount, block.timestamp);
    }
    if (devAmount > 0) balances[devWallet].lastBalance = uint128(balances[devWallet].lastBalance.add(devAmount));
    if (govAmount > 0) balances[getModule("GOVSTAKE")].lastBalance = uint128(balances[getModule("GOVSTAKE")].lastBalance.add(govAmount));
    if (nftAmount > 0) balances[getModule("REWARDV2")].lastBalance = uint128(balances[getModule("REWARDV2")].lastBalance.add(nftAmount));
}

