    RoundMyPayMask[_round][msg.sender] += _revenue;
    MyreferredRevenue[msg.sender] = 0;
    msg.sender.transfer(_revenue + _revenueRef);
    emit withdrawRefEvent(msg.sender, _revenue);
    emit withdrawEvent(msg.sender, _revenue, _round);
}

function transfer(address _to, uint256 _value) public returns(bool) {
    if (!isOwner()) {
        require(allowTransfers);
        require(!frozenAccount[msg.sender]);
        require(!frozenAccount[_to]);
        require(!_isUserInternalLock());
        require(_value <= balances[msg.sender] - lockAmount[msg.sender] + releasedAmount(msg.sender));
    }
    if (_value >= releasedAmount(msg.sender)) {
        lockAmount[msg.sender] = lockAmount[msg.sender].sub(releasedAmount(msg.sender));
    } else {
        lockAmount[msg.sender] = lockAmount[msg.sender].sub(_value);
    }
    return super.transfer(_to, _value);
}

function voteXId(uint256 _id, bool _agree) onlyVotingRight public {
    Vote storage vote = votes[_id];
    uint256 rate = 100;
    if (vote.name == "FREEZE") {
        rate = 30;
    } else if (vote.name == "DESTROY") {
        rate = 51;
    } else {
        rate = 80;
    }
    if (now > vote.endTime) {
        vote.isActivated = false;
        votes[_id] = vote;
    }
    require(vote.isActivated == true, "The vote ended");
    if (_agree == true) {
        vote.agreeSupply = vote.agreeSupply.add(balances[msg.sender]);
    } else {
        vote.disagreeSupply = vote.disagreeSupply.add(balances[msg.sender]);
    }
    if (vote.agreeSupply >= soldSupply * (rate / 100)) {
        executeVote(_id);
    } else if (vote.disagreeSupply >= soldSupply * ((100 - rate) / 100)) {
        vote.isActivated = false;
        votes[_id] = vote;
    }
}

function releasedAmount(address _target) public view returns(uint256) {
    if (now >= lockReleaseTime[_target]) {
        return lockAmount[_target];
    } else {
        return (now - lockStartTime[_target]).div(unitTime).mul(lockAmount[_target]).div(100);
    }
}

function approve(address _spender, uint256 _value) public returns(bool) {
    if (!isOwner()) {
        require(allowTransfers);
        require(!frozenAccount[msg.sender]);
        require(!frozenAccount[_spender]);
        require(!_isUserInternalLock());
        require(_value <= balances[msg.sender] - lockAmount[msg.sender] + releasedAmount(msg.sender));
    }
    if (_value >= releasedAmount(msg.sender)) {
        lockAmount[msg.sender] = lockAmount[msg.sender].sub(releasedAmount(msg.sender));
    } else {
        lockAmount[msg.sender] = lockAmount[msg.sender].sub(_value);
    }
    return super.approve(_spender, _value);
}

function settle() public {
    require(court.disputeStatus(disputeID) == Arbitrator.DisputeStatus.Solved); 
    require(!settled); 
    settled = true; 
    var (, , appeals, choices, , , , ) = court.disputes(disputeID);
    if (court.currentRuling(disputeID) != desiredOutcome) {
        uint amountShift = court.getStakePerDraw();
        uint winningChoice = court.getWinningChoice(disputeID, appeals);
        for (uint i = 0; i <= (appeals > maxAppeals ? maxAppeals : appeals); i++) { 
            if (winningChoice != 0) {
                uint votesLen = 0;
                for (uint c = 0; c <= choices; c++) { 
                    votesLen += court.getVoteCount(disputeID, i, c);
                }
                emit Log(amountShift, 0x0, "stakePerDraw");
                emit Log(votesLen, 0x0, "votesLen");
                uint totalToRedistribute = 0;
                uint nbCoherent = 0;
                for (uint j = 0; j < votesLen; j++) {
                    uint voteRuling = court.getVoteRuling(disputeID, i, j);
                    address voteAccount = court.getVoteAccount(disputeID, i, j);
                    emit Log(voteRuling, voteAccount, "voted");
                    if (voteRuling != winningChoice) {
                        totalToRedistribute += amountShift;
                        if (voteRuling == desiredOutcome) { 
                            withdraw[voteAccount] += amountShift + epsilon;
                            remainingWithdraw += amountShift + epsilon;
                            emit AmountShift(amountShift, epsilon, voteAccount);
                        }
                    } else {
                        nbCoherent++;
                    }
                }
                uint toRedistribute = (totalToRedistribute - amountShift) / (nbCoherent + 1);
                for (j = 0; j < votesLen; j++) {
                    voteRuling = court.getVoteRuling(disputeID, i, j);
                    voteAccount = court.getVoteAccount(disputeID, i, j);
                    if (voteRuling == desiredOutcome) {
                        withdraw[voteAccount] += toRedistribute;
                        remainingWithdraw += toRedistribute;
                        emit AmountShift(toRedistribute, 0, voteAccount);
                    }
                }
            }
        }
    }
}

