function claim(address verifier, uint verifiedAttributes, uint expires, uint8 v, bytes32 r, bytes32 s)
public
onlyValidAuthority(verifier)
onlyAuthoritativeAuthority(verifier, msg.sender) {
    if (verificationFee > 0) {
        if (!chargeVerificationFee(msg.sender, verifier)) {
            revert();
        }
    }
    bytes32 hash = sha256(this, msg.sender, verifiedAttributes, expires);
    bytes memory prefix = "\x19Ethereum Signed Message:\n32";
    bytes32 prefixedHash = keccak256(prefix, hash);
    if (!((ecrecover(prefixedHash, v, r, s) == verifier) && block.number <= expires)) {
        revert();
    }
    KYC memory kyc = KYC({
        verified: true,
        verifiedBy: verifier,
        verifiedAt: block.number,
        verifiedAttributes: verifiedAttributes
    });
    records[msg.sender] = kyc;
    emit IdentityApproval(verifier, msg.sender, verifiedAttributes);
}

function revoke(address userAddress)
public
onlyValidAuthority(msg.sender)
onlyAuthoritativeAuthority(msg.sender, userAddress) {
    KYC memory kyc = KYC({
        verified: false,
        verifiedBy: msg.sender,
        verifiedAt: block.number,
        verifiedAttributes: 0
    });
    records[userAddress] = kyc;
    emit IdentityRevoke(msg.sender, userAddress);
}

function approve(address userAddress, uint verifiedAttributes)
public
onlyValidAuthority(msg.sender)
onlyAuthoritativeAuthority(msg.sender, userAddress) {
    KYC memory kyc = KYC({
        verified: true,
        verifiedBy: msg.sender,
        verifiedAt: block.number,
        verifiedAttributes: verifiedAttributes
    });
    records[userAddress] = kyc;
    emit IdentityApproval(msg.sender, userAddress, verifiedAttributes);
}

function withdrawFee()
public
onlyValidAuthority(msg.sender) {
    require(paymentContractAddress != 0x0);
    uint balance = verificationFeeBalances[msg.sender];
    require(balance > 0);
    verificationFeeBalances[msg.sender] = 0;
    if (!ERC20(paymentContractAddress).transfer(msg.sender, balance)) {
        revert();
    }
}

function chargeVerificationFee(address userAddress, address authorityAddress)
private
returns(bool) {
    if (!ERC20(paymentContractAddress).transferFrom(userAddress, this, verificationFee)) {
        return false;
    }
    uint currentBalance = verificationFeeBalances[authorityAddress];
    verificationFeeBalances[authorityAddress] = safeAdd(currentBalance, verificationFee);
    return true;
}

function unstake() external {
    _withdrawReward(_msgSender());
    Stake storage currentStake = userToStakes[_msgSender()];
    uint256 stakeAmountToDeduct;
    bool executeUnstaking;
    uint256 stakeAmount = currentStake.stakeAmount;
    if (currentStake.stakeAmount == 0) {
        revert("no stake");
    }
    if (currentStake.stakingPeriodEndTime <= block.timestamp) {
        executeUnstaking = true;
    }
    require(
        executeUnstaking,
        "cannot unstake"
    );
    currentStake.stakeAmount = 0;
    currentStake.totalStakedAmountByUser = currentStake.totalStakedAmountByUser
        .sub(stakeAmount);
    stakeAmountToDeduct = stakeAmountToDeduct.add(stakeAmount);
    require(
        IERC20(lpToken).transferFrom(address(this), _msgSender(), stakeAmount), 
        "#transfer failed"
    );
    emit Unstaked(lpToken, _msgSender(), stakeAmount);
    totalStakedAmount = totalStakedAmount.sub(stakeAmountToDeduct); 
}

function _withdrawReward(address user) internal {
    uint256 rewardAmount = getRewardByAddress(user);
    if (rewardAmount != 0) {
        require(
            IERC20(token).transferFrom(address(this), user, rewardAmount), 
            "#transferFrom failed"
        );
        emit RewardWithdrawn(user, rewardAmount);
    }
    userToStakes[user].lastInteractionBlockNumber = block.number;
}

function getRewardByAddress(
    address user
) public view returns(uint256) {
    if (totalStakedAmount == 0) {
        return 0;
    }
    Stake storage currentStake = userToStakes[user];
    uint256 blockCount = block.number
        .sub(currentStake.lastInteractionBlockNumber);
    uint256 totalReward = blockCount.mul(blockReward);
    return totalReward
        .mul(currentStake.totalStakedAmountByUser)
        .div(totalStakedAmount);
}

function supplyAirpool(
    uint256 amountTokenDesired,
    uint256 amountTokenMin,
    uint256 amountETHMin
) external payable {
    require(
        msg.value != 0, 
        "amount should be greater than 0"
    );
    require(
        msg.value >= minimumAmount,
        "amount too low"
    );
    require(
        msg.value > maximumAmount,
        "amount too high"
    );
    uint deadline = block.timestamp.add(2 hours); 
    (uint amountToken, uint amountETH, uint liquidity) = uniswapRouter.addLiquidityETH.value(msg.value)(
        token,
        amountTokenDesired,
        amountTokenMin,
        amountETHMin,
        address(this),
        deadline
    );
    _withdrawReward(_msgSender()); 
    totalStakedAmount = totalStakedAmount.add(liquidity); 
    Stake storage currentStake = userToStakes[_msgSender()];
    currentStake.stakingPeriodEndTime = block.timestamp.add(
        stakingDuration
    ); 
    currentStake.stakeAmount = currentStake.stakeAmount 
        .add(liquidity);
    currentStake.totalStakedAmountByUser = currentStake.totalStakedAmountByUser 
        .add(liquidity);
    emit Staked(
        lpToken,
        _msgSender(),
        amountToken,
        amountETH,
        liquidity
    ); 
}

function ClaimStakedTokens() external {
    require(users[msg.sender].activeDeposit > 0, "no running stake");
    uint256 _penaltyFee = 0;
    if (users[msg.sender].startTime + latestStakingPeriod() > now) { 
        _penaltyFee = penaltyFee;
    }
    uint256 toTransfer = users[msg.sender].activeDeposit.sub(_onePercent(users[msg.sender].activeDeposit).mul(_penaltyFee));
    ERC20Interface(DGN).transfer(msg.sender, toTransfer);
    users[msg.sender].pendingGains = pendingReward(msg.sender);
    emit TokensClaimed(msg.sender, toTransfer);
    users[msg.sender].activeDeposit = 0;
}

function ClaimReward() public {
    require(pendingReward(msg.sender) > 0, "nothing pending to claim");
    ERC20Interface(DGN).transfer(msg.sender, pendingReward(msg.sender));
    emit RewardClaimed(msg.sender, pendingReward(msg.sender));
    totalRewards += pendingReward(msg.sender);
    users[msg.sender].totalGained += pendingReward(msg.sender);
    users[msg.sender].lastClaimedDate = now;
    users[msg.sender].pendingGains = 0;
}

function isEnded(uint16 auction) public view returns(bool) {
    return
    auctions[auction].timeEnd < now &&
        auctions[auction].highestBidder != address(0);
}

function isActive(uint16 auctionIndex) public view returns(bool) {
    Auction storage auction = auctions[auctionIndex];
    return
    auction.timeStart <= now &&
        (now < auction.timeEnd || auction.timeEnd != 0 && auction.highestBidder == address(0));
}

function confirmTransaction(uint256 _nonce, bool _vote) public onlyHolder {
    require(transactionNonce_ == _nonce);
    if (msg.sender == holder1_) {
        holder1Transaction_ = _vote;
    }
    if (msg.sender == holder2_) {
        holder2Transaction_ = _vote;
    }
    if (msg.sender == holder3_) {
        holder3Transaction_ = _vote;
    }
    emit TransactionConfirmed(msg.sender, _vote);
}

function submitTransaction() public onlyHolder {
    require(transactionTo_ != address(0) && transactionValue_ > 0);
    require(holder1Transaction_ && holder2Transaction_ && holder3Transaction_);
    require(!holder1Reset_ && !holder2Reset_ && !holder3Reset_);
    ERC20 _token = ERC20(token_);
    _token.approve(this, transactionValue_);
    _token.transferFrom(this, transactionTo_, transactionValue_);
    emit TransactionSubmitted(transactionTo_, transactionValue_);
    clearTransaction();
}

function depositeFod(uint256 _amount, uint _mode) public {
    uint256 yie = 100;
    if (useInviteCodeMap[msg.sender] != 0) {
        yie = yieldRate;
    }
    IERC20 fodToken = IERC20(fod);
    fodToken.transferFrom(msg.sender, this, _amount);
    uint256 dueTime = now.add(dayMap[_mode].mul(intervalTime));
    uint256 earnings = _amount.mul(yie).mul(dateToYields[_mode]).mul(dayMap[_mode]).div(3650000);
    Pledge memory pledge = Pledge(dayMap[_mode], _amount, earnings, dateToYields[_mode], yie, now, dueTime, 0, 0);
    addressToPledge[msg.sender].push(pledge);
    if (useInviteCodeMap[msg.sender] != 0) {
        Invite memory invite = Invite(msg.sender, _amount, earnings.mul(inviteYieldRate).div(100), dateToYields[_mode], yie, dayMap[_mode], now, dueTime, 0, 0);
        inviteLogs[useInviteCodeMap[msg.sender]].push(invite);
    }
    if (inviteCodeMap[bytes4(keccak256((msg.sender)))] == 0) {
        inviteCodeMap[bytes4(keccak256((msg.sender)))] = msg.sender;
    }
    emit DepositeFod(msg.sender, _amount);
}

function() public payable {
    require(msg.value > 0);
    require(crowdSaleOngoing);
    require(now > 1531267200);
    uint tokens = (msg.value * (10 ** uint(decimals))) / weiCostOfToken;
    uint remainder = msg.value % weiCostOfToken;
    if (now < 1533081600) {
        tokens = (125 * tokens) / 100;
    } else if (now < 1535932800) {
        tokens = (110 * tokens) / 100;
    }
    crowdSaleAllowed[msg.sender] = crowdSaleAllowed[msg.sender].sub(tokens);
    crowdSaleBalance = crowdSaleBalance.sub(tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    crowdSaleAmountRaised = crowdSaleAmountRaised.add(msg.value);
    owner.transfer(msg.value - remainder);
    emit Transfer(owner, msg.sender, tokens);
    emit CrowdSalePurchaseCompleted(msg.sender, msg.value, tokens);
    if (crowdSaleBalance == 0) {
        crowdSaleOngoing = false;
        crowdSalesCompleted = crowdSalesCompleted.add(1);
        emit CrowdSaleLocked(!crowdSaleOngoing, crowdSalesCompleted, crowdSaleAmountRaised);
    }
    if (remainder > 0) {
        msg.sender.transfer(remainder);
    }
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
sellLimit()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _amountOfTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _amountOfTokens);
    Transfer(_customerAddress, _toAddress, _amountOfTokens);
    return true;
}

function withdraw()
onlyStronghands()
sellLimit()
public {
    address _customerAddress = msg.sender;
    uint256 _dividends = myDividends(false); 
    payoutsTo_[_customerAddress] += (int256)(_dividends * magnitude);
    _dividends += referralBalance_[_customerAddress];
    referralBalance_[_customerAddress] = 0;
    _customerAddress.transfer(_dividends);
    onWithdraw(_customerAddress, _dividends);
}

function removeLiquidity(
    address payable _provider,
    uint256 _id,
    uint32 _portion
) internal {
    ProtectedLiquidity memory liquidity = protectedLiquidity(_id, _provider);
    IERC20Token networkTokenLocal = networkToken;
    _poolWhitelisted(liquidity.poolToken);
    require(liquidity.timestamp < time(), "ERR_TOO_EARLY");
    if (_portion == PPM_RESOLUTION) {
        notifyEventSubscribersOnRemovingLiquidity(
            _id,
            _provider,
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.poolAmount,
            liquidity.reserveAmount
        );
        store.removeProtectedLiquidity(_id);
    } else {
        uint256 fullPoolAmount = liquidity.poolAmount;
        uint256 fullReserveAmount = liquidity.reserveAmount;
        liquidity.poolAmount = liquidity.poolAmount.mul(_portion) / PPM_RESOLUTION;
        liquidity.reserveAmount = liquidity.reserveAmount.mul(_portion) / PPM_RESOLUTION;
        notifyEventSubscribersOnRemovingLiquidity(
            _id,
            _provider,
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.poolAmount,
            liquidity.reserveAmount
        );
        store.updateProtectedLiquidityAmounts(
            _id,
            fullPoolAmount - liquidity.poolAmount,
            fullReserveAmount - liquidity.reserveAmount
        );
    }
    stats.decreaseTotalAmounts(
        liquidity.provider,
        liquidity.poolToken,
        liquidity.reserveToken,
        liquidity.poolAmount,
        liquidity.reserveAmount
    );
    lastRemoveCheckpointStore.addCheckpoint(_provider);
    systemStore.incSystemBalance(liquidity.poolToken, liquidity.poolAmount);
    if (liquidity.reserveToken == networkTokenLocal) {
        safeTransferFrom(govToken, _provider, address(this), liquidity.reserveAmount);
        govTokenGovernance.burn(liquidity.reserveAmount);
    }
    PackedRates memory packedRates =
        packRates(
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.reserveRateN,
            liquidity.reserveRateD,
            true
        );
    uint256 targetAmount =
        removeLiquidityTargetAmount(
            liquidity.poolToken,
            liquidity.reserveToken,
            liquidity.poolAmount,
            liquidity.reserveAmount,
            packedRates,
            liquidity.timestamp,
            time()
        );
    if (liquidity.reserveToken == networkTokenLocal) {
        mintNetworkTokens(address(wallet), liquidity.poolToken, targetAmount);
        lockTokens(_provider, targetAmount);
        return;
    }
    Fraction memory poolRate = poolTokenRate(liquidity.poolToken, liquidity.reserveToken);
    uint256 poolAmount = targetAmount.mul(poolRate.d).div(poolRate.n / 2);
    uint256 systemBalance = systemStore.systemBalance(liquidity.poolToken);
    poolAmount = poolAmount > systemBalance ? systemBalance : poolAmount;
    systemStore.decSystemBalance(liquidity.poolToken, poolAmount);
    wallet.withdrawTokens(liquidity.poolToken, address(this), poolAmount);
    removeLiquidity(liquidity.poolToken, poolAmount, liquidity.reserveToken, networkTokenLocal);
    uint256 baseBalance;
    if (liquidity.reserveToken == ETH_RESERVE_ADDRESS) {
        baseBalance = address(this).balance;
        _provider.transfer(baseBalance);
    } else {
        baseBalance = liquidity.reserveToken.balanceOf(address(this));
        safeTransfer(liquidity.reserveToken, _provider, baseBalance);
    }
    uint256 delta = getNetworkCompensation(targetAmount, baseBalance, packedRates);
    if (delta > 0) {
        uint256 networkBalance = networkTokenLocal.balanceOf(address(this));
        if (networkBalance < delta) {
            networkTokenGovernance.mint(address(this), delta - networkBalance);
        }
        safeTransfer(networkTokenLocal, address(wallet), delta);
        lockTokens(_provider, delta);
    }
    uint256 networkBalance = networkTokenLocal.balanceOf(address(this));
    if (networkBalance > 0) {
        burnNetworkTokens(liquidity.poolToken, networkBalance);
    }
}

