function getCurrentRate() public view returns(uint256) {
    if (now <= openingTime.add(2 days)) return rate.add(rate / 4); 
    if (now > openingTime.add(2 days) && now <= openingTime.add(4 days)) return rate.add(rate / 5); 
    if (now > openingTime.add(4 days) && now <= openingTime.add(6 days)) return rate.add(rate * 3 / 20); 
    if (now > openingTime.add(6 days) && now <= openingTime.add(8 days)) return rate.add(rate / 10); 
    if (now > openingTime.add(8 days) && now <= openingTime.add(10 days)) return rate.add(rate / 20); 
}

