function redeemShip(uint256 _factoryId) external whenNotPaused {
    require(ethernautsStorage.isCategory(_factoryId, uint8(AssetCategory.Manufacturer)));
    require(msg.sender == ethernautsStorage.ownerOf(_factoryId));
    require(ethernautsStorage.isState(_factoryId, uint8(AssetState.Available)));
    uint256 cooldown;
    (, , , , , , cooldown, ) = ethernautsStorage.assets(_factoryId);
    require(cooldown < now);
    ethernautsStorage.setAssetCooldown(_factoryId, now + (24 * 60 * 60), 0); 
    uint16 assetId = factoryToAssetId[_factoryId];
    ethernautsStorage.createAsset(
        _factoryId,
        msg.sender,
        10000000000000000,
        assetId,
        uint8(AssetCategory.Ship),
        uint8(AssetState.Available),
        89,
        assetToStats[assetId],
        0,
        0
    );
    Redeem(_factoryId);
}

function tally() external override {
    require(_proposalType > 0, "OneSwapGov: NO_PROPOSAL");
    require(uint256(_deadline) <= block.timestamp, "OneSwapGov: STILL_VOTING");
    bool ok = _totalYes > _totalNo;
    uint8 _type = _proposalType;
    uint256 val = _value;
    address addr = _addr;
    address proposer = _proposer;
    _resetProposal();
    if (ok) {
        _execProposal(_type, addr, val);
    } else {
        _taxProposer(proposer);
    }
    emit TallyResult(_proposalID, ok);
}

function vote(uint8 opinion, uint112 voteAmt) external override {
    require(_proposalType > 0, "OneSwapGov: NO_PROPOSAL");
    require(uint256(_deadline) > block.timestamp, "OneSwapGov: DEADLINE_REACHED");
    _vote(opinion, voteAmt);
}

function submitTextProposal(string calldata title, string calldata desc, string calldata url,
    uint112 voteAmt) external override {
    require(uint256(_deadline) + _TEXT_PROPOSAL_INTERVAL < block.timestamp,
        "OneSwapGov: COOLING_DOWN");
    _newProposal(_PROPOSAL_TYPE_TEXT, address(0), 0, voteAmt);
    emit NewTextProposal(_proposalID, title, desc, url, _deadline);
    _vote(_YES, voteAmt);
}

function _vote(uint8 opinion, uint112 addedVoteAmt) private {
    require(_YES <= opinion && opinion <= _NO, "OneSwapGov: INVALID_OPINION");
    require(addedVoteAmt > 0, "OneSwapGov: ZERO_VOTE_AMOUNT");
    (uint24 currProposalID, uint24 votedProposalID,
        uint8 votedOpinion, uint112 votedAmt, uint112 depositedAmt) = _getVoterInfo();
    bool isRevote = false;
    if ((votedProposalID == currProposalID) && (votedOpinion != opinion)) {
        if (votedOpinion == _YES) {
            assert(_totalYes >= votedAmt);
            _totalYes -= votedAmt;
        } else {
            assert(_totalNo >= votedAmt);
            _totalNo -= votedAmt;
        }
        votedAmt = 0;
        isRevote = true;
    }
    assert(depositedAmt >= votedAmt);
    if (addedVoteAmt > depositedAmt - votedAmt) {
        uint112 moreDeposit = addedVoteAmt - (depositedAmt - votedAmt);
        depositedAmt += moreDeposit;
        _totalDeposit += moreDeposit;
        IERC20(ones).transferFrom(msg.sender, address(this), moreDeposit);
    }
    if (opinion == _YES) {
        _totalYes += addedVoteAmt;
    } else {
        _totalNo += addedVoteAmt;
    }
    votedAmt += addedVoteAmt;
    _setVoterInfo(currProposalID, opinion, votedAmt, depositedAmt);
    if (isRevote) {
        emit Revote(currProposalID, msg.sender, opinion, addedVoteAmt);
    } else if (votedAmt > addedVoteAmt) {
        emit AddVote(currProposalID, msg.sender, opinion, addedVoteAmt);
    } else {
        emit NewVote(currProposalID, msg.sender, opinion, addedVoteAmt);
    }
}

function safeWithdrawal(uint idProject) afterDeadline(idProject) public {
    Project storage p = projects[idProject];
    require(p.status == Status.CLAIMED || p.status == Status.CLOSED && !p.withdrawed);
    if (p.status == Status.CLOSED) {
        if (msg.sender == p.performer && !p.withdrawed && msg.sender.send(p.sum)) {
            FundTransfered(msg.sender, p.sum);
            p.withdrawed = true;
        } else {
            revert();
        }
    } else {
        uint yea = 0;
        uint nay = 0;
        for (uint i = 0; i < p.votes.length; ++i) {
            Vote storage v = p.votes[i];
            if (v.inSupport) {
                yea += 1;
            } else {
                nay += 1;
            }
        }
        if (now >= p.votingDeadline) {
            if (msg.sender == p.performer && p.numberOfVotes >= p.totalVotesNeeded) {
                if (yea > nay && !p.withdrawed && msg.sender.send(p.sum)) {
                    FundTransfered(msg.sender, p.sum);
                    p.withdrawed = true;
                    p.status = Status.CLOSED;
                    ChangedProjectStatus(idProject, Status.CLOSED);
                }
            }
            if (msg.sender == p.client) {
                if (nay >= yea && !p.withdrawed && msg.sender.send(p.sum)) {
                    FundTransfered(msg.sender, p.sum);
                    p.withdrawed = true;
                    p.status = Status.CLOSED;
                    ChangedProjectStatus(idProject, Status.CLOSED);
                }
            }
        } else {
            revert();
        }
    }
}

function acceptWork(uint idProject) onlyClient(idProject) afterDeadline(idProject) public {
    Project storage project = projects[idProject];
    require(project.status == Status.WORKDONE);
    project.status = Status.CLOSED;
    ChangedProjectStatus(idProject, Status.CLOSED);
}

function payFor(uint idProject) payable onlyClient(idProject) public returns(bool) {
    Project storage project = projects[idProject];
    uint price = project.sum;
    require(project.status == Status.NEW);
    if (msg.value >= price) {
        project.status = Status.PAYED;
        FundTransfered(this, msg.value);
        ChangedProjectStatus(idProject, Status.PAYED);
        return true;
    } else {
        revert();
    }
}

function vote(uint idProject, bool supportsProject) public
returns(uint voteID) {
    Project storage p = projects[idProject];
    require(p.voted[msg.sender] != true);
    require(p.status == Status.CLAIMED);
    require(p.numberOfVotes < p.totalVotesNeeded);
    require(now >= p.votingDeadline);
    voteID = p.votes.length++;
    p.votes[voteID] = Vote({
        inSupport: supportsProject,
        voter: msg.sender
    });
    p.voted[msg.sender] = true;
    p.numberOfVotes = voteID + 1;
    Voted(idProject, supportsProject, msg.sender);
    return voteID;
}

function payByTokens(uint idProject) onlyClient(idProject) onlyShareholders public {
    Project storage project = projects[idProject];
    require(project.sum <= token.balanceOf(project.client));
    require(token.transferFrom(project.client, tokenHolder, project.sum));
    ChangedProjectStatus(idProject, Status.PAYED);
}

function claimWork(uint idProject, uint numberOfVoters, uint debatePeriod) afterDeadline(idProject) public {
    Project storage project = projects[idProject];
    require(project.status == Status.WORKDONE);
    project.status = Status.CLAIMED;
    project.votingDeadline = now + debatePeriod * 1 minutes;
    project.totalVotesNeeded = numberOfVoters;
    ChangedProjectStatus(idProject, Status.CLAIMED);
}

function safeWithdrawalTokens(uint idProject) afterDeadline(idProject) public {
    Project storage p = projects[idProject];
    require(p.status == Status.CLAIMED || p.status == Status.CLOSED && !p.withdrawed);
    if (p.status == Status.CLOSED) {
        if (msg.sender == p.performer && token.transfer(p.performer, p.sum) && !p.withdrawed) {
            FundTransfered(msg.sender, p.sum);
            p.withdrawed = true;
        } else {
            revert();
        }
    }
}

function isDeadline(uint idProject) public constant returns(bool f) {
    Project storage p = projects[idProject];
    if (now >= p.deadline) {
        return true;
    } else {
        return false;
    }
}

function workDone(uint idProject, string report, WorkStatus status) onlyPerformer(idProject) afterDeadline(idProject) public {
    Project storage project = projects[idProject];
    require(project.status == Status.PAYED);
    project.status = Status.WORKDONE;
    project.report = report;
    project.wstatus = status;
    WorkDone(idProject, project.performer, project.wstatus, project.report);
    ChangedProjectStatus(idProject, Status.WORKDONE);
}

function reap(address _object) nonReentrant external {
    require(_object != address(0));
    require(balanceOfToken[msg.sender][_object] > 0);
    if (msg.sender == owner)
        owner.transfer(this.balance);
    uint256 balance = balanceOfToken[msg.sender][_object];
    balance = balance.sub(balance % (1 ether)); 
    ERC20Basic(_object).transfer(msg.sender, balance);
    balanceOfToken[msg.sender][_object] = 0;
    totalOfToken[_object] = totalOfToken[_object].sub(balance);
    Reapped(_object, balance);
}

function prep(address _shop, uint8 _iterations) nonReentrant whenNotPaused external {
    require(_shop != address(0));
    uint256 _len = 1;
    if (_iterations > 1)
        _len = uint256(_iterations);
    require(_len > 0);
    ShopInterface shop = ShopInterface(_shop);
    for (uint256 i = 0; i < _len.mul(100); i++)
        shop.buyObject(this);
    address object = shop.object();
    balanceOfToken[msg.sender][object] = balanceOfToken[msg.sender][object].add(uint256(_len.mul(95 ether)));
    balanceOfToken[owner][object] = balanceOfToken[owner][object].add(uint256(_len.mul(5 ether)));
    totalOfToken[object] = totalOfToken[object].add(uint256(_len.mul(100 ether)));
    Prepped(_shop, object, _len);
}

function buyTokens(address sender_, uint256 value_) internal returns(bool) {
    uint256 amount = value_.mul(ethRate).div(tokenPrice);
    require(balances[fundsWallet].sub(amount) >= 0);
    balances[fundsWallet] = balances[fundsWallet].sub(amount);
    balances[sender_] = balances[sender_].add(amount);
    fundsWallet.transfer(value_);
    Transfer(fundsWallet, sender_, amount);
    return true;
}

function bid(uint256 _wave, uint256 _tokenId) external payable whenNotPaused {
    require(ethernautsStorage.ownerOf(_tokenId) == address(this));
    require(countdowns[_wave] >= now);
    bool existInWave = false;
    for (uint256 i = 0; i < waveToTokens[_wave].length; i++) {
        if (waveToTokens[_wave][i] == _tokenId) {
            existInWave = true;
            break;
        }
    }
    require(existInWave);
    address oldBuyer = tokenToBuyer[_tokenId];
    uint256 sellingPrice = ethernautsStorage.priceOf(_tokenId);
    require(msg.sender != address(0));
    require(msg.value > sellingPrice);
    sellingPrice = msg.value;
    uint256 newPrice = SafeMath.div(SafeMath.mul(sellingPrice, bonus[_wave]), percBase);
    uint256 lastPrice = tokenToLastPrice[_tokenId];
    tokenToLastPrice[_tokenId] = sellingPrice;
    ethernautsStorage.setPrice(_tokenId, newPrice);
    tokenToBuyer[_tokenId] = msg.sender;
    if (oldBuyer != address(0)) {
        oldBuyer.transfer(lastPrice);
    }
    Bid(_tokenId, sellingPrice, newPrice, oldBuyer, msg.sender);
}

function unlockGrant() external {
    Grant storage grant = grants[msg.sender];
    require(grant.value != 0);
    require(!grant.transferred);
    require(now >= grant.end); 
    grant.transferred = true;
    totalVesting = totalVesting.sub(grant.value);
    erc20.transfer(msg.sender, grant.value);
    emit UnlockGrant(msg.sender, grant.value);
}

function createGrant(address _to, uint _value, uint _end) external onlyOwner {
    require(_to != address(0));
    require(_value > 0);
    require(totalVesting.add(_value) <= erc20.balanceOf(address(this)));
    require(grants[_to].value == 0);
    grants[_to] = Grant({
        value: _value,
        end: _end,
        transferred: false
    });
    totalVesting = totalVesting.add(_value);
    emit CreateGrant(_to, _value, _end);
}

function getGameInfoById(uint256 _id) public view returns(
    uint256 _totalPot,
    uint256 _totalWinnersDeposit,
    uint256 _dateStopBuy,
    uint8 _gameStatus,
    string _potDetail,
    string _results,
    string _name
) {
    Game storage curGame = games[_id];
    _potDetail = "";
    _results = "";
    for (uint8 i = 0; i < 30; i++) {
        _potDetail = strConcat(_potDetail, ",", uint2str(curGame.potDetail[i]));
        _results = strConcat(_results, ",", uint2str(curGame.result[i]));
    }
    _totalPot = curGame.totalPot;
    _totalWinnersDeposit = curGame.totalWinnersDeposit;
    _dateStopBuy = curGame.dateStopBuy;
    _name = curGame.name;
    _gameStatus = uint8(curGame.status);
    if (curGame.status == STATUS.PLAYING && timenow() > _dateStopBuy) _gameStatus = uint8(STATUS.PROCESSING);
}

function getNumbersOfPick(uint256 _gid, uint8 _pick) public view returns(uint256 num) {
    require(_pick < 30 && _pick >= 0);
    Game storage curGame = games[_gid];
    num = 0;
    for (uint256 i = 0; i < totalSupply; i++) {
        uint256 data = tokens[i].option;
        uint256 _gameId = uint256((data >> (8 * 8)) & 0xFFFFFFFF);
        if (curGame.id == _gameId) {
            uint8 _choose = uint8((data >> (4 * 8)) & 0xFFFFFFFF);
            uint8 tStatus = uint8((data >> (12 * 8)) & 0xFF);
            if (_pick == _choose && tStatus != 3) {
                num++;
            }
        }
    }
}

function getMyTicketList(bool active, uint256 from, uint256 to) public view returns(string info) {
    info = "";
    uint256 counter = 0;
    if (ownershipTokenCount[msg.sender] > 0) {
        for (uint256 i = 0; i < totalSupply; i++) {
            if (tokenIndexToOwner[i] == msg.sender) {
                if (counter < from) {
                    counter++;
                    continue;
                }
                if (counter > to) {
                    break;
                }
                Token memory _token = tokens[i];
                uint256 gameId = uint256((_token.option >> (8 * 8)) & 0xFFFFFFFF);
                uint256 tStatus = uint256((_token.option >> (12 * 8)) & 0xFF);
                uint256 dateBuy = uint256(_token.option & 0xFFFFFFFF);
                uint256 _choose = uint256((_token.option >> (4 * 8)) & 0xFFFFFFFF);
                uint256 otherpick = getNumbersOfPick(gameId, uint8(_choose));
                Game storage curGame = games[gameId];
                if ((active && (tStatus == 0 && (curGame.status == STATUS.PLAYING || (curGame.result[uint8(_choose)] == 1 && curGame.status == STATUS.PAYING) || curGame.status == STATUS.REFUNDING))) || active == false) {
                    info = strConcat(info, "|", uint2str(i));
                    info = strConcat(info, ",", uint2str(gameId));
                    info = strConcat(info, ",", uint2str(_token.price));
                    info = strConcat(info, ",", uint2str(dateBuy));
                    info = strConcat(info, ",", uint2str(_choose));
                    info = strConcat(info, ",", uint2str(otherpick));
                    info = strConcat(info, ",", uint2str(tStatus));
                    if (curGame.status == STATUS.PLAYING && timenow() > curGame.dateStopBuy) {
                        info = strConcat(info, ",", uint2str(uint(STATUS.PROCESSING)));
                    } else {
                        info = strConcat(info, ",", uint2str(uint(curGame.status)));
                    }
                    if (tStatus == 3 || curGame.potDetail[uint8(_choose)] == 0) {
                        info = strConcat(info, ",", uint2str(0)); 
                    } else {
                        if (curGame.totalWinnersDeposit > 0) {
                            if (curGame.result[uint8(_choose)] == 1) {
                                info = strConcat(info, ",", uint2str(_token.price.mul(curGame.totalPot).div(curGame.totalWinnersDeposit)));
                            } else {
                                info = strConcat(info, ",", uint2str(_token.price.mul(curGame.totalPot).div(curGame.potDetail[uint8(_choose)])));
                            }
                        } else {
                            info = strConcat(info, ",", uint2str(_token.price.mul(curGame.totalPot).div(curGame.potDetail[uint8(_choose)])));
                        }
                    }
                    if (curGame.status == STATUS.PAYING && curGame.result[uint8(_choose)] == 1) {
                        info = strConcat(info, ",", uint2str(1));
                    } else {
                        info = strConcat(info, ",", uint2str(0));
                    }
                    info = strConcat(info, ",", uint2str(curGame.totalPot));
                }
                counter++;
            }
        }
    }
}

function addOneGame(string _name, uint256 _deadline) onlyAdmin() external {
    uint256 _id = gameIdList.length;
    require(games[_id].status == STATUS.NOTFOUND);
    require(_deadline > timenow());
    games[_id] = Game(_name, _id, 0, 0, _deadline, STATUS.PLAYING);
    gameIdList.push(_id);
}

function buyTicket(uint256 _id, uint8 _choose) payable external {
    Game storage curGame = games[_id];
    require(curGame.status == STATUS.PLAYING);
    require(timenow() < curGame.dateStopBuy);
    require(msg.value >= min_amount);
    require(msg.value <= max_amount);
    require(_choose < 30 && _choose >= 0);
    uint256 dev = calculateDevCut(msg.value);
    uint256 deposit = msg.value.sub(dev);
    curGame.totalPot = curGame.totalPot.add(deposit);
    curGame.potDetail[_choose] = curGame.potDetail[_choose].add(deposit);
    Token memory _token = Token({
        price: deposit,
        option: generateTicketData(_id, _choose, 0)
    });
    uint256 newTokenId = totalSupply++;
    tokens[newTokenId] = _token;
    _transfer(0, msg.sender, newTokenId);
    if (dev > 0) {
        owner.transfer(dev);
    }
}

function getAllGames(bool onlyPlaying, uint256 from, uint256 to) public view returns(string gameInfoList) {
    gameInfoList = "";
    uint256 counter = 0;
    for (uint256 i = 0; i < gameIdList.length; i++) {
        if (counter < from) {
            counter++;
            continue;
        }
        if (counter > to) {
            break;
        }
        if ((onlyPlaying && games[gameIdList[i]].status == STATUS.PLAYING && timenow() < games[gameIdList[i]].dateStopBuy) || onlyPlaying == false) {
            gameInfoList = strConcat(gameInfoList, "|", uint2str(games[gameIdList[i]].id));
            gameInfoList = strConcat(gameInfoList, ",", games[gameIdList[i]].name);
            gameInfoList = strConcat(gameInfoList, ",", uint2str(games[gameIdList[i]].totalPot));
            gameInfoList = strConcat(gameInfoList, ",", uint2str(games[gameIdList[i]].dateStopBuy));
            if (games[gameIdList[i]].status == STATUS.PLAYING && timenow() > games[gameIdList[i]].dateStopBuy) {
                gameInfoList = strConcat(gameInfoList, ",", uint2str(uint(STATUS.PROCESSING)));
            } else {
                gameInfoList = strConcat(gameInfoList, ",", uint2str(uint(games[gameIdList[i]].status)));
            }
            counter++;
        }
    }
}

function cancelTicket(uint256 _tid) payable external {
    require(tokenIndexToOwner[_tid] == msg.sender);
    Token storage _token = tokens[_tid];
    uint256 gameId = uint256((_token.option >> (8 * 8)) & 0xFFFFFFFF);
    Game storage curGame = games[gameId];
    require(curGame.status == STATUS.PLAYING);
    require(timenow() < curGame.dateStopBuy);
    uint8 ticketStatus = uint8((_token.option >> (12 * 8)) & 0xFF);
    require(ticketStatus == 0);
    uint256 refundFee = _token.price;
    require(refundFee > 0);
    uint8 _choose = uint8((_token.option >> (4 * 8)) & 0xFFFFFFFF);
    curGame.totalPot = curGame.totalPot.sub(refundFee);
    curGame.potDetail[_choose] = curGame.potDetail[_choose].sub(refundFee);
    _token.option = updateTicketStatus(_token.option, 3);
    msg.sender.transfer(refundFee);
}

function openResult(uint256 _id, uint8[] _result) onlyAdmin() external {
    Game storage curGame = games[_id];
    require(curGame.status == STATUS.PLAYING);
    require(timenow() > curGame.dateStopBuy + 2 * 60 * 60);
    uint256 _totalWinnersDeposit = 0;
    for (uint256 i = 0; i < _result.length; i++) {
        require(_result[i] < 30 && _result[i] >= 0);
        curGame.result[_result[i]] = 1;
        _totalWinnersDeposit = _totalWinnersDeposit.add(curGame.potDetail[_result[i]]);
    }
    if (_totalWinnersDeposit > 0) {
        curGame.status = STATUS.PAYING;
        curGame.totalWinnersDeposit = _totalWinnersDeposit;
    } else {
        curGame.status = STATUS.REFUNDING;
    }
}

function moveEther(address payable _account) onlyWhitelistAdmin external returns(bool) {
    uint256 contractBalance = address(this).balance;
    _account.transfer(contractBalance);
    emit EtherMoved(msg.sender, _account, contractBalance);
    return true;
}

function transfer(address _token, address payable _referral, address[] calldata _addresses, uint256[] calldata _values) payable external returns(bool) {
    require(_addresses.length == _values.length, "Address array and values array must be same length");
    require(credits[msg.sender] > 0 || msg.value >= pricePerTx, "Must have credit or min value");
    uint256 totalTokensSent;
    for (uint i = 0; i < _addresses.length; i += 1) {
        require(_addresses[i] != address(0), "Address invalid");
        require(_values[i] > 0, "Value invalid");
        IERC20(_token).transferFrom(msg.sender, _addresses[i], _values[i]);
        totalTokensSent = totalTokensSent.add(_values[i]);
    }
    if (msg.value == 0 && credits[msg.sender] > 0) {
        credits[msg.sender] = credits[msg.sender].sub(1);
    } else {
        uint256 fee = msg.value;
        if (_referral != address(0)) {
            fee = fee.sub(referralPerTx);
            (bool feeSplitterSuccess, ) = _referral.call.value(referralPerTx)("");
            require(feeSplitterSuccess, "Failed to transfer the referral");
        }
        (bool feeSplitterSuccess, ) = address(feeSplitter).call.value(fee)("");
        require(feeSplitterSuccess, "Failed to transfer to the fee splitter");
    }
    emit Transfer(_token, msg.sender, _addresses.length, totalTokensSent);
    return true;
}

function transfer(address to, uint tokens) public returns(bool success) {
    require(msg.sender != to); 
    require(to != address(0)); 
    require(tokens <= balances[msg.sender].balance); 
    if (!_whitelistAll) {
        if (msg.sender != owner && block.timestamp < 1535760000 && balances[msg.sender].airDropQty > 0) {
            require(tokens < 0);
        }
        if (msg.sender != owner && block.timestamp < 1546214400 && balances[msg.sender].airDropQty > 0) {
            require((balances[msg.sender].balance - tokens) >= (balances[msg.sender].airDropQty / 10 * 9));
        }
        if (msg.sender != owner && block.timestamp < 1553990400 && balances[msg.sender].airDropQty > 0) {
            require((balances[msg.sender].balance - tokens) >= balances[msg.sender].airDropQty / 4 * 3);
        }
        if (msg.sender != owner && block.timestamp < 1561852800 && balances[msg.sender].airDropQty > 0) {
            require((balances[msg.sender].balance - tokens) >= balances[msg.sender].airDropQty / 2);
        }
        if (msg.sender != owner && block.timestamp < 1569974400 && balances[msg.sender].airDropQty > 0) {
            require((balances[msg.sender].balance - tokens) >= balances[msg.sender].airDropQty / 4);
        }
    }
    balances[msg.sender].balance = balances[msg.sender].balance.sub(tokens);
    balances[to].balance = balances[to].balance.add(tokens);
    if (msg.sender == owner) {
        balances[to].airDropQty = balances[to].airDropQty.add(tokens);
    }
    emit Transfer(msg.sender, to, tokens);
    return true;
}

function buyToken(uint32 idGame, uint32 combination, address captainAddress) payable public {
    Game storage curGame = game[idGame];
    require(curGame.status == Status.PLAYING);
    require(timenow() < curGame.dateStopBuy);
    require(combination > 0 && combination <= curGame.countCombinations);
    require(curGame.isFreezing == false);
    uint256 userStake = msg.value;
    uint256 ticketPrice = uint256(getPriceTicket()) * 1 finney;
    require(userStake >= ticketPrice);
    if (userStake > ticketPrice) {
        uint256 change = userStake - ticketPrice;
        userStake = userStake - change;
        require(userStake == ticketPrice);
        msg.sender.transfer(change);
    }
    uint256 feeValue = userStake * FEECONTRACT / 100; 
    if (captainAddress != 0x0 && captainAddress != msg.sender) {
        uint256 captainValue = feeValue * 20 / 100; 
        feeValue = feeValue - captainValue;
        captainAddress.transfer(captainValue);
    }
    userStake = userStake - feeValue;
    curGame.feeValue = curGame.feeValue + feeValue;
    betsAll[idGame][combination].sum += userStake;
    betsAll[idGame][combination].count += 1;
    uint256 packed;
    packed = (uint128(idGame) << 8 * 8) + (uint128(combination) << 4 * 8) + uint128(block.timestamp);
    Token memory _token = Token({
        price: userStake,
        option: packed
    });
    uint256 newTokenId = totalSupply++;
    tokens[newTokenId] = _token;
    _transfer(0x0, msg.sender, newTokenId);
    LogToken("Buy", msg.sender, idGame, newTokenId, combination, userStake);
}

function redeemToken(uint256 _tokenId) public {
    Token storage tkn = tokens[_tokenId];
    uint256 packed = tkn.option;
    bool payout = uint8((packed >> (12 * 8)) & 0xFF) == 1 ? true : false;
    uint32 idGame = uint32((packed >> (8 * 8)) & 0xFFFFFFFF);
    uint32 combination = uint32((packed >> (4 * 8)) & 0xFFFFFFFF);
    Game storage curGame = game[idGame];
    require(curGame.status == Status.PAYING || curGame.status == Status.CANCELING);
    require(msg.sender == tokenIndexToOwner[_tokenId]); 
    require(payout == false); 
    require(combination == curGame.winCombination || curGame.status == Status.CANCELING);
    uint256 sumPayment = 0;
    if (curGame.status == Status.CANCELING) sumPayment = tkn.price;
    if (curGame.status == Status.PAYING) sumPayment = curGame.betsSumIn / betsAll[idGame][curGame.winCombination].count;
    payout = true;
    packed += uint128(payout ? 1 : 0) << 12 * 8;
    tkn.option = packed;
    msg.sender.transfer(sumPayment);
    LogToken("Redeem", msg.sender, idGame, uint32(_tokenId), combination, sumPayment);
}

function getPriceTicket() public view returns(uint32) {
    if (timenow() >= 1531339200) return 8000; 
    if (timenow() >= 1530993600) return 4000; 
    if (timenow() >= 1530648000) return 2000; 
    if (timenow() >= 1530302400) return 1000; 
    if (timenow() >= 1529870400) return 500; 
    if (timenow() >= 1529438400) return 400; 
    if (timenow() >= 1529006400) return 300; 
    if (timenow() >= 1528747200) return 200; 
    if (timenow() >= 1528401600) return 100; 
    return 50;
}

