    for (uint256 i = 0; i < totalSupply; i++) {
        if (user == tokenIndexToOwner[i]) {
            uint256 packed = tokens[i].option;
            uint32 idGameToken = uint32((packed >> (8 * 8)) & 0xFFFFFFFF);
