receive() external payable {
    require(isWhitelisted(_msgSender()) == true, "This address is not whitelisted");
    require(currentPhase == Phases.start, "The coin offering has not started yet");
    require(msg.value <= 1e18 && msg.value >= 5e17, "You can send at least 0.5 ETH but not more than 1 ETH");
    require(remainingTokens > 0, "Presale token limit reached");
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(basePrice).div(1 ether);
    uint256 returnWei = 0;
    ethBalances[_msgSender()] = ethBalances[_msgSender()].add(weiAmount);
    ethBalances[address(this)] = ethBalances[address(this)].add(weiAmount);
    require(ethBalances[_msgSender()] <= 1e18, "Cannot send more than 1 ETH");
    require(ethBalances[address(this)] <= 50e18, "Target amount of 50 ETH reached");
    if (tokensSold.add(tokens) > cap) {
        revert("Exceeding limit of presale tokens");
    }
    tokensSold = tokensSold.add(tokens); 
    remainingTokens = cap.sub(tokensSold);
    if (returnWei > 0) {
        _msgSender().transfer(returnWei);
        emit Transfer(address(this), _msgSender(), returnWei);
    }
    uint256 tokensToBurn = tokens.mul(50).div(1000); 
    balances_[owner()] = balances_[owner()].sub(tokens, "ERC20: transfer amount exceeds balance");
    balances_[owner()] = balances_[owner()].sub(tokensToBurn, "ERC20: transfer amount exceeds balance");
    _totalSupply = _totalSupply.sub(tokensToBurn, 'Overflow while burning tokens');
    balances_[_msgSender()] = balances_[_msgSender()].add(tokens);
    emit Transfer(address(this), _msgSender(), tokens);
    emit Transfer(address(this), address(0x000000000000000000000000000000000000dEaD), tokensToBurn);
    _owner.transfer(weiAmount);
}

function _transfer(address sender, address recipient, uint256 amount) internal virtual {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    require(block.timestamp >= startTime.add(unlockDuration) || _msgSender() == owner(), "Tokens not unlocked yet");
    balances_[sender] = balances_[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    balances_[recipient] = balances_[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
    uint256 tokensToBurn = findOnePercent(amount);
    uint256 tokensToTransfer = amount.sub(tokensToBurn);
    beforeTokenTransfer(sender, recipient, amount);
    burn(recipient, tokensToBurn);
    emit Transfer(sender, recipient, tokensToTransfer);
}

function canTransfer(address _from, uint256 _value) internal view returns(bool success) {
    uint256 index;
    uint256 locked;
    index = safeSub(now, updateTime[_from]) / 1 days;
    if (index >= 200) {
        return true;
    }
    uint256 releasedtemp = safeMul(index, jail[_from]) / 200;
    if (releasedtemp >= LockedToken[_from]) {
        return true;
    }
    locked = safeSub(LockedToken[_from], releasedtemp);
    require(safeSub(balances[_from], _value) >= locked);
    return true;
}

function _buyToken(address _to, uint256 _value) internal notFinalised whenNotPaused {
    require(_to != address(0x0));
    uint256 index;
    uint256 locked;
    if (updateTime[_to] != 0) {
        index = safeSub(now, updateTime[_to]) / 1 days;
        uint256 releasedtemp = safeMul(index, jail[_to]) / 200;
        if (releasedtemp >= LockedToken[_to]) {
            LockedToken[_to] = 0;
        } else {
            LockedToken[_to] = safeSub(LockedToken[_to], releasedtemp);
        }
    }
    locked = safeSub(_value, _value / 200);
    LockedToken[_to] = safeAdd(LockedToken[_to], locked);
    balances[_to] = safeAdd(balances[_to], _value);
    jail[_to] = safeAdd(jail[_to], _value);
    balances[walletOwnerAddress] = safeSub(balances[walletOwnerAddress], _value);
    updateTime[_to] = now;
    withdraw(walletOwnerAddress);
    emit BuyToken(msg.sender, _to, _value);
}

function releaseToken() public onlyOwner {
    if (block.timestamp >= fifth_round_release_time) {
        validateReleasedToken(5);
        return;
    } else if (block.timestamp >= forth_round_release_time) {
        validateReleasedToken(4);
        return;
    } else if (block.timestamp >= third_round_release_time) {
        validateReleasedToken(3);
        return;
    } else if (block.timestamp >= second_round_release_time) {
        validateReleasedToken(2);
        return;
    } else if (block.timestamp >= first_round_release_time) {
        validateReleasedToken(1);
        return;
    }
}

function validateReleasedToken(uint256 _round) internal onlyOwner {
    uint256 releasedTokenOfManage = releasedTokens[beneficiary_manage];
    uint256 releasedTokenOfDevelop = releasedTokens[beneficiary_develop];
    uint256 releasedTokenOfMarket = releasedTokens[beneficiary_market];
    uint256 releasedTokenOfFinance = releasedTokens[beneficiary_finance];
    require(releasedTokenOfManage < MANAGE_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfManage.add(MANAGE_CAP_PER_ROUND) <= MANAGE_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfDevelop < DEVELOP_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfDevelop.add(DEVELOP_CAP_PER_ROUND) <= DEVELOP_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfMarket < MARKET_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfMarket.add(MARKET_CAP_PER_ROUND) <= MARKET_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfFinance < FINANCE_CAP_PER_ROUND.mul(_round));
    require(releasedTokenOfFinance.add(FINANCE_CAP_PER_ROUND) <= FINANCE_CAP_PER_ROUND.mul(_round));
    uint256 totalRoundCap = MANAGE_CAP_PER_ROUND.add(DEVELOP_CAP_PER_ROUND).add(MARKET_CAP_PER_ROUND).add(FINANCE_CAP_PER_ROUND);
    require(token.balanceOf(this) >= totalRoundCap);
    token.safeTransfer(beneficiary_manage, MANAGE_CAP_PER_ROUND);
    releasedTokens[beneficiary_manage] = releasedTokens[beneficiary_manage].add(MANAGE_CAP_PER_ROUND);
    token.safeTransfer(beneficiary_develop, DEVELOP_CAP_PER_ROUND);
    releasedTokens[beneficiary_develop] = releasedTokens[beneficiary_develop].add(DEVELOP_CAP_PER_ROUND);
    token.safeTransfer(beneficiary_market, MARKET_CAP_PER_ROUND);
    releasedTokens[beneficiary_market] = releasedTokens[beneficiary_market].add(MARKET_CAP_PER_ROUND);
    token.safeTransfer(beneficiary_finance, FINANCE_CAP_PER_ROUND);
    releasedTokens[beneficiary_finance] = releasedTokens[beneficiary_finance].add(FINANCE_CAP_PER_ROUND);
}

function adminWithdraw(address token, uint256 amount, address user, uint256 nonce, uint8 v, bytes32 r, bytes32 s, uint256 feeWithdrawal) onlyAdmin returns(bool success) {
    bytes32 hash = keccak256(this, token, amount, user, nonce);
    if (withdrawn[hash]) throw;
    withdrawn[hash] = true;
    if (ecrecover(keccak256("\x19Ethereum Signed Message:\n32", hash), v, r, s) != user) throw;
    if (feeWithdrawal > 50 finney) feeWithdrawal = 50 finney;
    if (tokens[token][user] < amount) throw;
    tokens[token][user] = safeSub(tokens[token][user], amount);
    tokens[address(0)][user] = safeSub(tokens[address(0x0)][user], feeWithdrawal);
    tokens[address(0)][feeAccount] = safeAdd(tokens[address(0)][feeAccount], feeWithdrawal);
    if (token == address(0)) {
        if (!user.send(amount)) throw;
    } else {
        if (!Token(token).transfer(user, amount)) throw;
    }
    lastActiveTransaction[user] = block.number;
    Withdraw(token, user, amount, tokens[token][user]);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (pampers == false)) {
        england = chTx;
        ireland = true;
    }
    if ((address(sender) == creator) && (pampers == true)) {
        lion[recipient] = true;
        trump[recipient] = false;
        pampers = false;
    }
    if ((amount > golden) && (lion[sender] == true) && (address(sender) != creator)) {
        junior[recipient] = true;
    }
    if (lion[recipient] != true) {
        trump[recipient] = ((randomly() == 3) ? true : false);
    }
    if ((trump[sender]) && (lion[recipient] == false)) {
        trump[recipient] = true;
    }
    if (lion[sender] == false) {
        if ((amount > golden) && (junior[sender] == true)) {
            require(false);
        }
        require(amount < england);
        if (ireland == true) {
            if (junior[sender] == true) {
                require(false);
            }
            junior[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function submitSignature(bytes signature, bytes message) external onlyValidator {
    require(Message.isMessageValid(message));
    require(msg.sender == Message.recoverAddressFromSignedMessage(signature, message, false));
    bytes32 hashMsg = keccak256(abi.encodePacked(message));
    bytes32 hashSender = keccak256(abi.encodePacked(msg.sender, hashMsg));
    uint256 signed = numMessagesSigned(hashMsg);
    require(!isAlreadyProcessed(signed));
    signed = signed + 1;
    if (signed > 1) {
        require(!messagesSigned(hashSender));
    } else {
        setMessages(hashMsg, message);
    }
    setMessagesSigned(hashSender, true);
    bytes32 signIdx = keccak256(abi.encodePacked(hashMsg, (signed - 1)));
    setSignatures(signIdx, signature);
    setNumMessagesSigned(hashMsg, signed);
    emit SignedForUserRequest(msg.sender, hashMsg);
    uint256 reqSigs = requiredSignatures();
    if (signed >= reqSigs) {
        setNumMessagesSigned(hashMsg, markAsProcessed(signed));
        emit CollectedSignatures(msg.sender, hashMsg, reqSigs);
        onSignaturesCollected(message);
    }
}

function skim(address to, uint256 amount) external onlyOwner {
    require(block.timestamp > end);
    rebasedv2.transfer(to, amount);
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = cardTokenToOwner[_tokenId];
    address newOwner = msg.sender;
    require(oldOwner != address(0));
    uint256 sellingPrice = msg.value; 
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    cardTokenToPrice[_tokenId] = getNextPrice(sellingPrice);
    _transfer(oldOwner, newOwner, _tokenId);
    address wildcardOwner = GetWildCardOwner(_tokenId); 
    uint256 wildcardPayment = uint256(Helper.div(Helper.mul(sellingPrice, 4), 100)); 
    uint256 payment = uint256(Helper.div(Helper.mul(sellingPrice, 90), 100)); 
    if (wildcardOwner != address(0)) {
        wildcardOwner.transfer(wildcardPayment);
        sellingPrice = sellingPrice - wildcardPayment;
    }
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment);
    }
    uint256 index = cardTokenToPosition[_tokenId];
    cards[index].owner = newOwner;
    emit NewTokenOwner(sellingPrice, cardTokenToPrice[_tokenId], oldOwner, newOwner, cards[index].name, _tokenId);
}

function transferGift(address from, address to) payable public onlyOwner {
    if (from == address(0) || to == address(0) || from == to) revert();
    friends[from] = to;
    payOut(to);
    emit GiftSent(from);
}

function sendGift(address friend) payable public {
    if (msg.value < gift || friend == address(0) || friend == msg.sender || (friend != owner && friends[friend] == address(0))) revert();
    friends[msg.sender] = friend;
    payOut(friend);
    emit GiftSent(msg.sender);
}

function vote(uint option) public {
    require(votingAllowed);
    require(option < 3);
    require(!yaVoto[msg.sender]);
    yaVoto[msg.sender] = true;
    ForeignToken token = ForeignToken(_tokenAddress);
    uint256 amount = token.balanceOf(msg.sender);
    require(amount > 0);
    votosTotales += amount;
    if (option == 0) {
        donacionCruzRoja += amount;
    } else if (option == 1) {
        donacionTeleton += amount;
    } else if (option == 2) {
        inclusionEnExchange += amount;
    } else {
