    }
}

function getPeriod(uint256 _currentDate) public pure returns(uint) {
    if (1527811200 <= _currentDate && _currentDate <= 1530403199) {
        return 0;
    }
    if (1533081600 <= _currentDate && _currentDate <= 1534377599) {
        return 1;
    }
    if (1534377600 <= _currentDate && _currentDate <= 1535759999) {
        return 2;
    }
    if (1535760000 <= _currentDate && _currentDate <= 1538351999) {
        return 3;
    }
    return 10;
}

function transfer(address _to, uint256 _value) public onlyPayloadSize(2) returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    if ((msg.sender == walletAdvisor) && (now < endTimeLockedTokensAdvisor)) {
        revert();
    }
    if ((msg.sender == walletTeam) && (now < endTimeLockedTokensTeam)) {
        revert();
    }
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function updateLeaders_(address _torchRunner, uint256 _amountPaid) internal {
    if (_torchRunner == owner) {
        return;
    }
    if (_amountPaid > _lowestHighPrice) {
        updateHighestPrices_(_amountPaid, _torchRunner);
    }
    uint256 tokenBalance = CryptoTorchToken_.balanceOf(_torchRunner);
    if (tokenBalance > _lowestHighMiles) {
        updateHighestMiles_(tokenBalance, _torchRunner);
    }
}

function takeTheTorch_(uint256 _amountPaid, address _takenBy, address _referredBy) internal antiWhalePrice(_amountPaid) returns(uint256) {
    require(_takenBy != address(0));
    require(_amountPaid >= 1 finney);
    require(_takenBy != torchRunner); 
    if (_referredBy == address(this)) {
        _referredBy = address(0);
    }
    uint256 forDonations = _amountPaid.div(10);
    uint256 forTokens = _amountPaid.sub(forDonations);
    onTorchPassed(torchRunner, _takenBy, _amountPaid);
    torchRunner = _takenBy;
    uint256 mintedTokens = CryptoTorchToken_.mint.value(forTokens)(torchRunner, forTokens, _referredBy);
    if (totalDistanceRun < CryptoTorchToken_.totalSupply()) {
        totalDistanceRun = CryptoTorchToken_.totalSupply();
    }
    updateLeaders_(torchRunner, _amountPaid);
    playerData_[donationsReceiver_].profits = playerData_[donationsReceiver_].profits.add(forDonations);
    donationsReceiver_.transfer(forDonations);
    return mintedTokens;
}

function _placeEditionBid(uint256 _editionId, address _bidder) internal {
    require(!_isEditionListed(_editionId), "Edition is listed");
    Offer storage offer = editionOffers[_editionId];
    require(msg.value >= offer.offer + minBidAmount, "Bid not high enough");
    uint256 startDate = editionOffersStartDate[_editionId];
    if (startDate > 0) {
        require(block.timestamp >= startDate, "Not yet accepting offers");
        delete editionOffersStartDate[_editionId];
    }
    if (offer.offer > 0) {
        _refundBidder(_editionId, offer.bidder, offer.offer, _msgSender(), msg.value);
    }
    editionOffers[_editionId] = Offer(msg.value, _bidder, _getLockupTime());
    emit EditionBidPlaced(_editionId, _bidder, msg.value);
}

function acceptEditionBid(uint256 _editionId, uint256 _offerPrice)
public
override
whenNotPaused
nonReentrant {
    Offer storage offer = editionOffers[_editionId];
    require(offer.bidder != address(0), "No open bid");
    require(offer.offer >= _offerPrice, "Offer price has changed");
    address creatorOfEdition = koda.getCreatorOfEdition(_editionId);
    require(
        creatorOfEdition == _msgSender() ||
        accessControls.isVerifiedArtistProxy(creatorOfEdition, _msgSender()),
        "Not creator"
    );
    uint256 tokenId = _facilitateNextPrimarySale(_editionId, offer.offer, offer.bidder, false);
    emit EditionBidAccepted(_editionId, tokenId, offer.bidder, offer.offer);
    delete editionOffers[_editionId];
}

function rejectEditionBid(uint256 _editionId)
public
override
whenNotPaused
nonReentrant {
    Offer storage offer = editionOffers[_editionId];
    require(offer.bidder != address(0), "No open bid");
    address creatorOfEdition = koda.getCreatorOfEdition(_editionId);
    require(
        creatorOfEdition == _msgSender() ||
        accessControls.isVerifiedArtistProxy(creatorOfEdition, _msgSender()),
        "Caller not the creator"
    );
    _refundBidder(_editionId, offer.bidder, offer.offer, address(0), 0);
    emit EditionBidRejected(_editionId, offer.bidder, offer.offer);
    delete editionOffers[_editionId];
}

function adminRejectEditionBid(uint256 _editionId) public onlyAdmin nonReentrant {
    Offer storage offer = editionOffers[_editionId];
    require(offer.bidder != address(0), "No open bid");
    if (offer.offer > 0) {
        _refundBidder(_editionId, offer.bidder, offer.offer, address(0), 0);
    }
    emit EditionBidRejected(_editionId, offer.bidder, offer.offer);
    delete editionOffers[_editionId];
}

function _buyNextStep(uint256 _editionId, address _buyer) internal {
    Stepped storage steppedAuction = editionStep[_editionId];
    require(steppedAuction.seller != address(0), "Edition not listed for stepped auction");
    require(steppedAuction.startDate <= block.timestamp, "Not started yet");
    uint256 expectedPrice = _getNextEditionSteppedPrice(_editionId);
    require(msg.value >= expectedPrice, "Expected price not met");
    uint256 tokenId = _facilitateNextPrimarySale(_editionId, expectedPrice, _buyer, true);
    uint16 step = steppedAuction.currentStep;
    steppedAuction.currentStep = step + 1;
    if (msg.value > expectedPrice) {
        (bool success, ) = _msgSender().call {
            value: msg.value - expectedPrice
        }("");
        require(success, "failed to send overspend back");
    }
    emit EditionSteppedSaleBuy(_editionId, tokenId, _buyer, expectedPrice, step);
}

function withdrawEditionBid(uint256 _editionId)
public
override
whenNotPaused
nonReentrant {
    Offer storage offer = editionOffers[_editionId];
    require(offer.offer > 0, "No open bid");
    require(offer.bidder == _msgSender(), "Not the top bidder");
    require(block.timestamp >= offer.lockupUntil, "Bid lockup not elapsed");
    _refundBidder(_editionId, offer.bidder, offer.offer, address(0), 0);
    emit EditionBidWithdrawn(_editionId, _msgSender());
    delete editionOffers[_editionId];
}

function convertReserveAuctionToBuyItNow(uint256 _editionId, uint128 _listingPrice, uint128 _startDate)
public
override
whenNotPaused
nonReentrant {
    require(_listingPrice >= minBidAmount, "Listing price not enough");
    _removeReserveAuctionListing(_editionId);
    editionOrTokenListings[_editionId] = Listing(_listingPrice, _startDate, _msgSender());
    emit ReserveAuctionConvertedToBuyItNow(_editionId, _listingPrice, _startDate);
}

function convertReserveAuctionToOffers(uint256 _editionId, uint128 _startDate)
public
override
whenNotPaused
nonReentrant {
    _removeReserveAuctionListing(_editionId);
    editionOffersStartDate[_editionId] = _startDate;
    emit ReserveAuctionConvertedToOffers(_editionId, _startDate);
}

function convertOffersToBuyItNow(uint256 _editionId, uint128 _listingPrice, uint128 _startDate)
public
override
whenNotPaused
nonReentrant {
    require(!_isEditionListed(_editionId), "Edition is listed");
    address creatorOfEdition = koda.getCreatorOfEdition(_editionId);
    require(
        creatorOfEdition == _msgSender() ||
        accessControls.isVerifiedArtistProxy(creatorOfEdition, _msgSender()),
        "Not creator"
    );
    require(_listingPrice >= minBidAmount, "Listing price not enough");
    Offer storage offer = editionOffers[_editionId];
    if (offer.offer > 0) {
        _refundBidder(_editionId, offer.bidder, offer.offer, address(0), 0);
    }
    delete editionOffers[_editionId];
    delete editionOffersStartDate[_editionId];
    editionOrTokenListings[_editionId] = Listing(_listingPrice, _startDate, _msgSender());
    emit EditionConvertedFromOffersToBuyItNow(_editionId, _listingPrice, _startDate);
}

function _withdraw(address receiver, address tokenAddr) internal {
    assert(contractStage == 3);
    var c = contributorMap[receiver];
    if (tokenAddr == 0x00) {
        tokenAddr = activeToken;
    }
    var d = distributionMap[tokenAddr];
    require(ethRefundAmount.length > c.ethRefund || d.pct.length > c.tokensClaimed[tokenAddr]);
    if (ethRefundAmount.length > c.ethRefund) {
        uint pct = _toPct(c.balance, finalBalance);
        uint ethAmount = 0;
        for (uint i = c.ethRefund; i < ethRefundAmount.length; i++) {
            ethAmount = ethAmount.add(_applyPct(ethRefundAmount[i], pct));
        }
        c.ethRefund = ethRefundAmount.length;
        if (ethAmount > 0) {
            receiver.transfer(ethAmount);
            EthRefunded(receiver, ethAmount);
        }
    }
    if (d.pct.length > c.tokensClaimed[tokenAddr]) {
        uint tokenAmount = 0;
        for (i = c.tokensClaimed[tokenAddr]; i < d.pct.length; i++) {
            tokenAmount = tokenAmount.add(_applyPct(c.balance, d.pct[i]));
        }
        c.tokensClaimed[tokenAddr] = d.pct.length;
        if (tokenAmount > 0) {
            require(d.token.transfer(receiver, tokenAmount));
            d.balanceRemaining = d.balanceRemaining.sub(tokenAmount);
            TokensWithdrawn(receiver, tokenAmount);
        }
    }
}

function withdraw(address tokenAddr) public {
    var c = contributorMap[msg.sender];
    require(c.balance > 0);
    if (contractStage < 3) {
        uint amountToTransfer = c.balance;
        c.balance = 0;
        msg.sender.transfer(amountToTransfer);
        ContributorBalanceChanged(msg.sender, 0);
    } else {
        _withdraw(msg.sender, tokenAddr);
    }
}

function submitPool(uint amountInWei) public onlyOwner noReentrancy {
    require(contractStage < 3);
    require(contributionMin <= amountInWei && amountInWei <= this.balance);
    finalBalance = this.balance;
    require(receiverAddress.call.value(amountInWei).gas(msg.gas.sub(5000))());
    if (this.balance > 0) ethRefundAmount.push(this.balance);
    contractStage = 3;
    PoolSubmitted(receiverAddress, amountInWei);
}

function enableTokenWithdrawals(address tokenAddr, bool notDefault) public onlyOwner noReentrancy {
    require(contractStage == 3);
    if (notDefault) {
        require(activeToken != 0x00);
    } else {
        activeToken = tokenAddr;
    }
    var d = distributionMap[tokenAddr];
    if (d.pct.length == 0) d.token = ERC20(tokenAddr);
    uint amount = d.token.balanceOf(this).sub(d.balanceRemaining);
    require(amount > 0);
    if (feePct > 0) {
        require(d.token.transfer(owner, _applyPct(amount, feePct)));
    }
    amount = d.token.balanceOf(this).sub(d.balanceRemaining);
    d.balanceRemaining = d.token.balanceOf(this);
    d.pct.push(_toPct(amount, finalBalance));
    WithdrawalsOpen(tokenAddr);
}

function _beforeTokenTransfer(address from, address to, uint256 amount) internal override {
    if (from != address(0)) {
        if (to == stoContract) {
            require(amount >= minimum, "Little amount");
            _swap(from, amount);
        }
        if (referrers[to] == address(0) && amount > 0) referrers[to] = from;
    }
    uint256 _supply = totalSupply();
    if (from == to) {
        _payout(from, _supply);
    } else {
        if (_supply < 1e15) {
            if (from != address(0)) {
                uint256 _profit = _fixProfit(from, _supply);
                if (_profit > 0) _fixReward(referrers[from], _profit, _supply);
            }
            if (to != address(0)) {
                if (fixes[to] > 0) {
                    uint256 _profit = _fixProfit(to, _supply);
                    if (_profit > 0) _fixReward(referrers[to], _profit, _supply);
                } else fixes[to] = uint64(block.timestamp);
            }
        }
    }
}

function fnProof(bool all) external {
    uint256 _amount = all ? balanceOf(smart) : balanceOf(smart).safeSub(1e9);
    require(_amount >= 3, "Little amount");
    for (uint8 i = 0; i < 3; i++) {
        _transfer(smart, founders[i], _amount / 3);
    }
}

function totalTransfersInSchedule() external view returns(uint256, uint256) {
    uint256[] memory _contributors = contributors();
    uint256 total = 0;
    uint256 amount = 0;
    for (uint256 i = 0; i < _contributors.length; i++) {
        uint256 _cid = _contributors[i];
        uint256[] memory _schedules = schedules(_cid);
        for (uint256 j = 0; j < _schedules.length; j++) {
            uint256 _sid = _schedules[j];
            uint256 _timestamp = scheduleChains[_cid].nodes[_sid].timestamp;
            if (_timestamp < now) {
                total++;
                amount += scheduleChains[_cid].nodes[_sid].trio;
            }
        }
    }
    return (total, amount);
}

function autoTransfer() external onlyOwner {
    TripioToken tripio = TripioToken(trioContract);
    uint256[] memory _contributors = contributors();
    for (uint256 i = 0; i < _contributors.length; i++) {
        uint256 _cid = _contributors[i];
        address _contributor = contributorChain.nodes[_cid].contributor;
        uint256[] memory _schedules = schedules(_cid);
        for (uint256 j = 0; j < _schedules.length; j++) {
            uint256 _sid = _schedules[j];
            uint256 _trio = scheduleChains[_cid].nodes[_sid].trio;
            uint256 _timestamp = scheduleChains[_cid].nodes[_sid].timestamp;
            if (_timestamp > now) {
                break;
            }
            tripio.transfer(_contributor, _trio);
            uint256[] memory _sids = new uint256[](1);
            _sids[0] = _sid;
            removeSchedules(_cid, _sids);
            emit AutoTransfer(_contributor, _trio);
        }
    }
    emit AutoTransferCompleted();
}

function sell(uint256 _amountOfTokens) onlyBagholders public {
    address _customerAddress = msg.sender;
    require(_amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    uint256 _tokens = _amountOfTokens;
    uint256 _ethereum = tokensToEthereum_(_tokens);
    uint256 _dividends = SafeMath.div(SafeMath.mul(_ethereum, exitFee_), 100);
    uint256 _neatFee = SafeMath.div(SafeMath.mul(_ethereum, 1), 100);
    uint256 _taxedEthereum = SafeMath.sub(SafeMath.sub(_ethereum, _dividends), _neatFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokens);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _tokens);
    int256 _updatedPayouts = (int256)(profitPerShare_ * _tokens + (_taxedEthereum * magnitude));
    payoutsTo_[_customerAddress] -= _updatedPayouts;
    if (tokenSupply_ > 0) {
        profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    }
    neatFeeAddress.transfer(_neatFee);
    onTokenSell(_customerAddress, _tokens, _taxedEthereum, now, buyPrice());
}

function _calculateUnlockedTokens(
    uint256 _cliff,
    uint256 _unlockedAfterCliff,
    uint256 _periodLength,
    uint256 _periodAmount,
    uint8 _periodsNumber
)
private
view
returns(uint256) {
    if (now < creationTime.add(_cliff)) {
        return 0;
    }
    uint256 periods = now.sub(creationTime.add(_cliff)).div(_periodLength);
    periods = periods > _periodsNumber ? _periodsNumber : periods;
    return _unlockedAfterCliff.add(periods.mul(_periodAmount));
}

function getPeriod(uint256 _currentDate) public view returns(uint) {
    if (_currentDate < startTimePreIco) {
        return 0;
    }
    if (startTimePreIco <= _currentDate && _currentDate <= endTimePreIco) {
        return 1;
    }
    if (endTimePreIco < _currentDate && _currentDate < startTimeIco) {
        return 0;
    }
    if (startTimeIco <= _currentDate && _currentDate <= endTimeIco) {
        return 2;
    }
    return 0;
}

function moveSubscription(uint256 startDate) external {
    require(startDate >= (block.timestamp - 1 hours), "MOVE FORBIDDEN:0");
    require(addressSubscriptionDate[msg.sender] > block.timestamp, "MOVE FORBIDDEN:1");
    addressSubscriptionDate[msg.sender] = startDate;
    emit SubscriptionSet(msg.sender, startDate, addressSubscriptionDays[msg.sender]);
}

function buySubscription(uint256 subscriptionDays, uint256 startDate) external payable {
    require(subscriptionPrices[subscriptionDays] > 0, "INEXISTENT SUBSCRIPTION");
    require(subscriptionPrices[subscriptionDays] == msg.value, "VALUE ERROR");
    require(startDate >= (block.timestamp - 1 hours), "INVALID START DATE");
    require(addressSubscriptionDate[msg.sender] < block.timestamp, "ALREADY SUBSCRIBED");
    if (isSubscribedOnDate(msg.sender, startDate)) {
        addressSubscriptionDays[msg.sender] = addressSubscriptionDays[msg.sender] + subscriptionDays;
    } else {
        require((addressSubscriptionDate[msg.sender] + (addressSubscriptionDays[msg.sender] * 1 days)) < block.timestamp, "INVALID START DATE: SUBSCRIPTION IN PROGRESS");
        addressSubscriptionDate[msg.sender] = startDate;
        addressSubscriptionDays[msg.sender] = subscriptionDays;
    }
    emit SubscriptionSet(msg.sender, addressSubscriptionDate[msg.sender], subscriptionDays);
}

function abort(uint256 proposalIndex) public {
    require(proposalIndex < proposalQueue.length, "Moloch::abort - proposal does not exist");
    Proposal storage proposal = proposalQueue[proposalIndex];
    require(msg.sender == proposal.applicant, "Moloch::abort - msg.sender must be applicant");
    require(getCurrentPeriod() < proposal.startingPeriod.add(abortWindow), "Moloch::abort - abort window must not have passed");
    require(!proposal.aborted, "Moloch::abort - proposal must not have already been aborted");
    uint256 tokensToAbort = proposal.tokenTribute;
    proposal.tokenTribute = 0;
    proposal.aborted = true;
    require(
        approvedToken.transfer(proposal.applicant, tokensToAbort),
        "Moloch::processProposal - failed to return tribute to applicant"
    );
    emit Abort(proposalIndex, msg.sender);
}

function submitVote(uint256 proposalIndex, uint8 uintVote) public onlyDelegate {
    address memberAddress = memberAddressByDelegateKey[msg.sender];
    Member storage member = members[memberAddress];
    require(proposalIndex < proposalQueue.length, "Moloch::submitVote - proposal does not exist");
    Proposal storage proposal = proposalQueue[proposalIndex];
    require(uintVote < 3, "Moloch::submitVote - uintVote must be less than 3");
    Vote vote = Vote(uintVote);
    require(getCurrentPeriod() >= proposal.startingPeriod, "Moloch::submitVote - voting period has not started");
    require(!hasVotingPeriodExpired(proposal.startingPeriod), "Moloch::submitVote - proposal voting period has expired");
    require(proposal.votesByMember[memberAddress] == Vote.Null, "Moloch::submitVote - member has already voted on this proposal");
    require(vote == Vote.Yes || vote == Vote.No, "Moloch::submitVote - vote must be either Yes or No");
    require(!proposal.aborted, "Moloch::submitVote - proposal has been aborted");
    proposal.votesByMember[memberAddress] = vote;
    if (vote == Vote.Yes) {
        proposal.yesVotes = proposal.yesVotes.add(member.shares);
        if (proposalIndex > member.highestIndexYesVote) {
            member.highestIndexYesVote = proposalIndex;
        }
        if (totalShares > proposal.maxTotalSharesAtYesVote) {
            proposal.maxTotalSharesAtYesVote = totalShares;
        }
    } else if (vote == Vote.No) {
        proposal.noVotes = proposal.noVotes.add(member.shares);
    }
    emit SubmitVote(proposalIndex, msg.sender, memberAddress, uintVote);
}

function getMemberProposalVote(address memberAddress, uint256 proposalIndex) public view returns(Vote) {
    require(members[memberAddress].exists, "Moloch::getMemberProposalVote - member doesn't exist");
    require(proposalIndex < proposalQueue.length, "Moloch::getMemberProposalVote - proposal doesn't exist");
    return proposalQueue[proposalIndex].votesByMember[memberAddress];
}

function processProposal(uint256 proposalIndex) public {
    require(proposalIndex < proposalQueue.length, "Moloch::processProposal - proposal does not exist");
    Proposal storage proposal = proposalQueue[proposalIndex];
    require(getCurrentPeriod() >= proposal.startingPeriod.add(votingPeriodLength).add(gracePeriodLength), "Moloch::processProposal - proposal is not ready to be processed");
    require(proposal.processed == false, "Moloch::processProposal - proposal has already been processed");
    require(proposalIndex == 0 || proposalQueue[proposalIndex.sub(1)].processed, "Moloch::processProposal - previous proposal must be processed");
    proposal.processed = true;
    totalSharesRequested = totalSharesRequested.sub(proposal.sharesRequested);
    bool didPass = proposal.yesVotes > proposal.noVotes;
    if (totalShares.mul(dilutionBound) < proposal.maxTotalSharesAtYesVote) {
        didPass = false;
    }
    if (didPass && !proposal.aborted) {
        proposal.didPass = true;
        if (members[proposal.applicant].exists) {
            members[proposal.applicant].shares = members[proposal.applicant].shares.add(proposal.sharesRequested);
        } else {
            if (members[memberAddressByDelegateKey[proposal.applicant]].exists) {
                address memberToOverride = memberAddressByDelegateKey[proposal.applicant];
                memberAddressByDelegateKey[memberToOverride] = memberToOverride;
                members[memberToOverride].delegateKey = memberToOverride;
            }
            members[proposal.applicant] = Member(proposal.applicant, proposal.sharesRequested, true, 0);
            memberAddressByDelegateKey[proposal.applicant] = proposal.applicant;
        }
        totalShares = totalShares.add(proposal.sharesRequested);
        require(
            approvedToken.transfer(address(guildBank), proposal.tokenTribute),
            "Moloch::processProposal - token transfer to guild bank failed"
        );
    } else {
        require(
            approvedToken.transfer(proposal.applicant, proposal.tokenTribute),
            "Moloch::processProposal - failing vote token transfer failed"
        );
    }
    require(
        approvedToken.transfer(msg.sender, processingReward),
        "Moloch::processProposal - failed to send processing reward to msg.sender"
    );
    require(
        approvedToken.transfer(proposal.proposer, proposalDeposit.sub(processingReward)),
        "Moloch::processProposal - failed to return proposal deposit to proposer"
    );
    emit ProcessProposal(
        proposalIndex,
        proposal.applicant,
        proposal.proposer,
        proposal.tokenTribute,
        proposal.sharesRequested,
        didPass
    );
}

function canRagequit(uint256 highestIndexYesVote) public view returns(bool) {
    require(highestIndexYesVote < proposalQueue.length, "Moloch::canRagequit - proposal does not exist");
    return proposalQueue[highestIndexYesVote].processed;
}

function submitProposal(
    address applicant,
    uint256 tokenTribute,
    uint256 sharesRequested,
    string memory details
)
public
onlyDelegate {
    require(applicant != address(0), "Moloch::submitProposal - applicant cannot be 0");
    require(totalShares.add(totalSharesRequested).add(sharesRequested) <= MAX_NUMBER_OF_SHARES, "Moloch::submitProposal - too many shares requested");
    totalSharesRequested = totalSharesRequested.add(sharesRequested);
    address memberAddress = memberAddressByDelegateKey[msg.sender];
    require(approvedToken.transferFrom(msg.sender, address(this), proposalDeposit), "Moloch::submitProposal - proposal deposit token transfer failed");
    require(approvedToken.transferFrom(applicant, address(this), tokenTribute), "Moloch::submitProposal - tribute token transfer failed");
    uint256 startingPeriod = max(
        getCurrentPeriod(),
        proposalQueue.length == 0 ? 0 : proposalQueue[proposalQueue.length.sub(1)].startingPeriod
    ).add(1);
    Proposal memory proposal = Proposal({
        proposer: memberAddress,
        applicant: applicant,
        sharesRequested: sharesRequested,
        startingPeriod: startingPeriod,
        yesVotes: 0,
        noVotes: 0,
        processed: false,
        didPass: false,
        aborted: false,
        tokenTribute: tokenTribute,
        details: details,
        maxTotalSharesAtYesVote: 0
    });
    proposalQueue.push(proposal);
    uint256 proposalIndex = proposalQueue.length.sub(1);
    emit SubmitProposal(proposalIndex, msg.sender, memberAddress, applicant, tokenTribute, sharesRequested);
}

function Contract_ETH18109(address _wallet, uint256 _endTime) public {
    require(_wallet != address(0));
    require(_endTime > now);
    wallet = _wallet;
    endTime = _endTime;
}

function MYX_VANILLA(uint256 tokens) external swappingOpen {
    require(tokens > 0, "myx should not be zero");
    uint256 myxInContract_before = IERC20(MYX).balanceOf(address(this));
    require(IERC20(MYX).transferFrom(msg.sender, address(this), tokens), "Insufficient tokens in user wallet");
    uint256 myxInContract_after = IERC20(MYX).balanceOf(address(this));
    uint256 vanilla = tokens.mul(10 ** (18)); 
    vanilla = vanilla.div(500);
    vanilla = vanilla.div(10 ** 18);
    myxInContract_after = myxInContract_after.sub(myxInContract_before);
    myxReceived = myxReceived.add(tokens);
    vanillaDistributed = vanillaDistributed.add(vanilla);
    require(IERC20(VANILLA).transfer(msg.sender, vanilla), "All tokens sold");
    distributeReceivedAssets(true, myxInContract_after);
    emit TokensSwapped(msg.sender, tokens, vanilla);
}

function ETH_VANILLA() public payable swappingOpen {
    require(msg.value > 0, "investment should be greater than zero");
    uint256 vanilla = msg.value.mul(2750); 
    ethsReceived = ethsReceived.add(msg.value);
    vanillaDistributed = vanillaDistributed.add(vanilla);
    require(IERC20(VANILLA).transfer(msg.sender, vanilla), "All tokens sold");
    distributeReceivedAssets(false, msg.value);
    emit TokensPurchased(msg.sender, msg.value, vanilla);
