function getUnSoldTokens() external onlyOwner {
    require(block.timestamp > SWAP_END, "ICO is not over");
    require(IERC20(VANILLA).transfer(owner, IERC20(VANILLA).balanceOf(address(this))), "No tokens in contract");
}

function getTownTokens(address holder) public payable returns(bool) {
    require(holder != address(0), "holder address cannot be null");
    uint256 amount = msg.value;
    uint256 tokenAmount = IWantTakeTokensToAmount(amount);
    uint256 rate = currentRate();
    if (_transactionsCount < _durationOfMinTokenGetAmount && tokenAmount < _minTokenGetAmount) {
        return false;
    }
    if (tokenAmount >= _maxTokenGetAmount) {
        tokenAmount = _maxTokenGetAmount;
        uint256 change = amount.sub(_maxTokenGetAmount.mul(rate).div(10 ** 18));
        msg.sender.transfer(change);
        amount = amount.sub(change);
    }
    if (_token.balanceOf(address(this)) >= tokenAmount) {
        TransactionsInfo memory transactionsHistory = TransactionsInfo(rate, tokenAmount);
        _token.transfer(holder, tokenAmount);
        _historyTransactions[holder].push(transactionsHistory);
        _transactionsCount = _transactionsCount.add(1);
    } else {
        if (_token.balanceOf(address(this)) > 0) {
            uint256 tokenBalance = _token.balanceOf(address(this));
            _token.transfer(holder, tokenBalance);
            TransactionsInfo memory transactionsHistory = TransactionsInfo(rate, tokenBalance);
            _historyTransactions[holder].push(transactionsHistory);
            tokenAmount = tokenAmount.sub(tokenBalance);
        }
        TransactionsInfo memory transactionsInfo = TransactionsInfo(rate, tokenAmount);
        TownTokenRequest memory tokenRequest = TownTokenRequest(holder, transactionsInfo);
        _queueTownTokenRequests.push(tokenRequest);
    }
    for (uint256 i = 0; i < _remunerationsQueue.length; ++i) {
        if (_remunerationsQueue[i]._priority == 1) {
            if (_remunerationsQueue[i]._amount > amount) {
                _remunerationsQueue[i]._address.transfer(_remunerationsQueue[i]._amount);
                amount = amount.sub(_remunerationsQueue[i]._amount);
                delete _remunerationsQueue[i];
                for (uint j = i + 1; j < _remunerationsQueue.length; ++j) {
                    _remunerationsQueue[j - 1] = _remunerationsQueue[j];
                }
                _remunerationsQueue.length--;
            } else {
                _remunerationsQueue[i]._address.transfer(amount);
                _remunerationsQueue[i]._amount = _remunerationsQueue[i]._amount.sub(amount);
                break;
            }
        }
    }
    for (uint256 i = 0; i < _remunerationsQueue.length; ++i) {
        if (_remunerationsQueue[i]._amount > amount) {
            _remunerationsQueue[i]._address.transfer(_remunerationsQueue[i]._amount);
            amount = amount.sub(_remunerationsQueue[i]._amount);
            delete _remunerationsQueue[i];
            for (uint j = i + 1; j < _remunerationsQueue.length; ++j) {
                _remunerationsQueue[j - 1] = _remunerationsQueue[j];
            }
            _remunerationsQueue.length--;
        } else {
            _remunerationsQueue[i]._address.transfer(amount);
            _remunerationsQueue[i]._amount = _remunerationsQueue[i]._amount.sub(amount);
            break;
        }
    }
    return true;
}

function remuneration(uint256 tokensAmount) external returns(bool) {
    require(_token.balanceOf(msg.sender) >= tokensAmount, "Town tokens not found");
    require(_token.allowance(msg.sender, address(this)) >= tokensAmount, "Town tokens must be approved for town smart contract");
    uint256 debt = 0;
    uint256 restOfTokens = tokensAmount;
    uint256 executedRequestCount = 0;
    for (uint256 i = 0; i < _queueTownTokenRequests.length; ++i) {
        address user = _queueTownTokenRequests[i]._address;
        uint256 rate = _queueTownTokenRequests[i]._info._rate;
        uint256 amount = _queueTownTokenRequests[i]._info._amount;
        if (restOfTokens > amount) {
            _token.transferFrom(msg.sender, user, amount);
            restOfTokens = restOfTokens.sub(amount);
            debt = debt.add(amount.mul(rate).div(10 ** 18));
            executedRequestCount++;
        } else {
            break;
        }
    }
    if (restOfTokens > 0) {
        _token.transferFrom(msg.sender, address(this), restOfTokens);
    }
    if (executedRequestCount > 0) {
        for (uint256 i = executedRequestCount; i < _queueTownTokenRequests.length; ++i) {
            _queueTownTokenRequests[i - executedRequestCount] = _queueTownTokenRequests[i];
        }
        for (uint256 i = 0; i < executedRequestCount; ++i) {
            delete _queueTownTokenRequests[_queueTownTokenRequests.length - 1];
            _queueTownTokenRequests.length--;
        }
    }
    if (_historyTransactions[msg.sender].length > 0) {
        for (uint256 i = _historyTransactions[msg.sender].length - 1;; --i) {
            uint256 rate = _historyTransactions[msg.sender][i]._rate;
            uint256 amount = _historyTransactions[msg.sender][i]._amount;
            delete _historyTransactions[msg.sender][i];
            _historyTransactions[msg.sender].length--;
            if (restOfTokens < amount) {
                TransactionsInfo memory info = TransactionsInfo(rate, amount.sub(restOfTokens));
                _historyTransactions[msg.sender].push(info);
                debt = debt.add(restOfTokens.mul(rate).div(10 ** 18));
                break;
            }
            debt = debt.add(amount.mul(rate).div(10 ** 18));
            restOfTokens = restOfTokens.sub(amount);
            if (i == 0) break;
        }
    }
    if (debt > address(this).balance) {
        msg.sender.transfer(address(this).balance);
        RemunerationsInfo memory info = RemunerationsInfo(msg.sender, 2, debt.sub(address(this).balance));
        _remunerationsQueue.push(info);
    } else {
        msg.sender.transfer(debt);
    }
    return true;
}

function claimExternalTokens(address holder) public returns(bool) {
    address[] memory externalTokensForHolder = _ledgerExternalTokensAddresses[holder];
    if (externalTokensForHolder.length > 0) {
        for (uint256 i = externalTokensForHolder.length - 1;; --i) {
            ERC20(externalTokensForHolder[i]).transfer(holder, _townHoldersLedger[holder][externalTokensForHolder[i]]);
            delete _townHoldersLedger[holder][externalTokensForHolder[i]];
            delete _ledgerExternalTokensAddresses[holder][i];
            _ledgerExternalTokensAddresses[holder].length--;
            if (i == 0) break;
        }
    }
    return true;
}

function claimFunds(address payable official) public returns(bool) {
    require(_officialsLedger[official]._amount != 0, "official address not found in ledger");
    if (now >= _officialsLedger[official]._decayTimestamp) {
        RemunerationsOfficialsInfo memory info = RemunerationsOfficialsInfo(0, 0);
        _officialsLedger[official] = info;
        return false;
    }
    uint256 amount = _officialsLedger[official]._amount;
    if (address(this).balance >= amount) {
        official.transfer(amount);
    } else {
        RemunerationsInfo memory info = RemunerationsInfo(official, 1, amount);
        _remunerationsQueue.push(info);
    }
    RemunerationsOfficialsInfo memory info = RemunerationsOfficialsInfo(0, 0);
    _officialsLedger[official] = info;
    return true;
}

function distributionSnapshot() external returns(bool) {
    require(now > (_lastDistributionsDate + _distributionPeriod), "distribution time has not yet arrived");
    uint256 sumWeight = 0;
    address[] memory tempArray;
    _externalTokensWithWight = tempArray;
    for (uint256 i = 0; i < _externalTokensAddresses.length; ++i) {
        ExternalToken memory externalToken = _externalTokens[_externalTokensAddresses[i]];
        if (externalToken._weight > 0) {
            uint256 sumExternalTokens = 0;
            for (uint256 j = 0; j < externalToken._entities.length; ++j) {
                if (externalToken._entities[j]._distributionsCount > 0) {
                    ExternalTokenDistributionsInfo memory info = externalToken._entities[j];
                    sumExternalTokens = sumExternalTokens.add(info._distributionAmount.mul(info._distributionsCount));
                }
            }
            if (sumExternalTokens > _minExternalTokensAmount) {
                sumWeight = sumWeight.add(externalToken._weight);
                _externalTokensWithWight.push(_externalTokensAddresses[i]);
            } else {
                externalToken._weight = 0;
            }
        }
    }
    uint256 fullBalance = address(this).balance;
    for (uint256 i = 0; i < _externalTokensWithWight.length; ++i) {
        ExternalToken memory externalToken = _externalTokens[_externalTokensWithWight[i]];
        uint256 sumExternalTokens = 0;
        for (uint256 j = 0; j < externalToken._entities.length; ++j) {
            sumExternalTokens = sumExternalTokens.add(externalToken._entities[j]._distributionAmount);
        }
        uint256 externalTokenCost = fullBalance.mul(externalToken._weight).div(sumWeight);
        for (uint256 j = 0; j < externalToken._entities.length; ++j) {
            address official = externalToken._entities[j]._official;
            uint256 tokensAmount = externalToken._entities[j]._distributionAmount;
            uint256 amount = externalTokenCost.mul(tokensAmount).div(sumExternalTokens);
            uint256 decayTimestamp = (now - _lastDistributionsDate).div(_distributionPeriod).mul(_distributionPeriod).add(_lastDistributionsDate).add(_distributionPeriod);
            _officialsLedger[official] = RemunerationsOfficialsInfo(amount, decayTimestamp);
        }
    }
    uint256 sumHoldersTokens = _token.totalSupply().sub(_token.balanceOf(address(this)));
    if (sumHoldersTokens != 0) {
        for (uint256 i = 0; i < _token.getHoldersCount(); ++i) {
            address holder = _token.getHolderByIndex(i);
            uint256 balance = _token.balanceOf(holder);
            for (uint256 j = 0; j < _externalTokensAddresses.length; ++j) {
                address externalTokenAddress = _externalTokensAddresses[j];
                ExternalToken memory externalToken = _externalTokens[externalTokenAddress];
                for (uint256 k = 0; k < externalToken._entities.length; ++k) {
                    if (holder != address(this) && externalToken._entities[k]._distributionsCount > 0) {
                        uint256 percent = balance.mul(externalToken._entities[k]._distributionAmount).div(sumHoldersTokens);
                        if (percent > (10 ** 4)) {
                            address[] memory externalTokensForHolder = _ledgerExternalTokensAddresses[holder];
                            bool found = false;
                            for (uint256 h = 0; h < externalTokensForHolder.length; ++h) {
                                if (externalTokensForHolder[h] == externalTokenAddress) {
                                    found = true;
                                    break;
                                }
                            }
                            if (found == false) {
                                _ledgerExternalTokensAddresses[holder].push(externalTokenAddress);
                            }
                            _townHoldersLedger[holder][externalTokenAddress] = _townHoldersLedger[holder][externalTokenAddress].add(percent);
                        }
                    }
                }
            }
        }
        for (uint256 j = 0; j < _externalTokensAddresses.length; ++j) {
            ExternalTokenDistributionsInfo[] memory tempEntities = _externalTokens[_externalTokensAddresses[j]]._entities;
            for (uint256 k = 0; k < tempEntities.length; ++k) {
                delete _externalTokens[_externalTokensAddresses[j]]._entities[k];
            }
            _externalTokens[_externalTokensAddresses[j]]._entities.length = 0;
            for (uint256 k = 0; k < tempEntities.length; ++k) {
                tempEntities[k]._distributionsCount--;
                if (tempEntities[k]._distributionsCount > 0) {
                    _externalTokens[_externalTokensAddresses[j]]._entities.push(tempEntities[k]);
                }
            }
        }
    }
    for (uint256 i = 0; i < _externalTokensAddresses.length; ++i) {
        if (_externalTokens[_externalTokensAddresses[i]]._weight > 0) {
            _externalTokens[_externalTokensAddresses[i]]._weight = 0;
        }
    }
    _lastDistributionsDate = _lastDistributionsDate.add(_distributionPeriod);
    return true;
}

function() external payable {
    if (msg.value <= _minSignAmount) {
        if (_officialsLedger[msg.sender]._amount > 0) {
            claimFunds(msg.sender);
        }
        if (_ledgerExternalTokensAddresses[msg.sender].length > 0) {
            claimExternalTokens(msg.sender);
        }
        return;
    }
    uint256 tokenAmount = IWantTakeTokensToAmount(msg.value);
    require(_transactionsCount > _durationOfMinTokenGetAmount || tokenAmount > _minTokenGetAmount, "insufficient amount");
    getTownTokens(msg.sender);
}

function voteOn(address externalToken, uint256 amount) external onlyTownTokenSmartContract returns(bool) {
    require(_externalTokens[externalToken]._entities.length > 0, "external token address not found");
    require(now < (_lastDistributionsDate + _distributionPeriod), "need call distributionSnapshot function");
    _externalTokens[externalToken]._weight = _externalTokens[externalToken]._weight.add(amount);
    return true;
}

function sendExternalTokens(address official, address externalToken) external returns(bool) {
    ERC20 tokenERC20 = ERC20(externalToken);
    uint256 balance = tokenERC20.allowance(official, address(this));
    require(tokenERC20.balanceOf(official) >= balance, "Official should have external tokens for approved");
    require(balance > 0, "External tokens must be approved for town smart contract");
    tokenERC20.transferFrom(official, address(this), balance);
    ExternalTokenDistributionsInfo memory tokenInfo;
    tokenInfo._official = official;
    tokenInfo._distributionsCount = _distributionPeriodsNumber;
    tokenInfo._distributionAmount = balance.div(_distributionPeriodsNumber);
    ExternalToken storage tokenObj = _externalTokens[externalToken];
    if (tokenObj._entities.length == 0) {
        _externalTokensAddresses.push(externalToken);
    }
    tokenObj._entities.push(tokenInfo);
    return true;
}

function transfer(address recipient, uint256 amount) public returns(bool) {
    if (msg.sender != address(_town)) {
        if (_town.checkProposal(recipient) == true) {
            super.transfer(address(_town), amount);
            return _town.voteOn(recipient, amount);
        }
    }
    if (recipient != address(_town)) {
        bool found = false;
        for (uint i = 0; i < _holders.length; ++i) { 
            if (_holders[i] == recipient) {
                found = true;
                break;
            }
        }
        if (found == false) { 
            _holders.push(recipient);
        }
    }
    if (balanceOf(address(msg.sender)) == amount && msg.sender != address(_town)) { 
        uint i = 0;
        for (; i < _holders.length; ++i) {
            if (_holders[i] == address(msg.sender)) {
                break;
            }
        }
        if (i < (_holders.length - 1)) {
            _holders[i] = _holders[_holders.length - 1];
            delete _holders[_holders.length - 1];
            _holders.length--;
        }
    }
    return super.transfer(recipient, amount);
}

function deposit(address ref) public payable payRepBonusIfNeeded {
    Player storage player = players[msg.sender];
    address refAddress = referrerOf(msg.sender, ref);
    require((msg.value == 0) != player.registeredDate > 0, "Send 0 for registration");
    if (player.registeredDate == 0) {
        _register(msg.sender, refAddress);
    }
    collect();
    uint256 wax = msg.value.mul(COINS_PER_ETH);
    player.balanceWax = player.balanceWax.add(wax);
    player.totalDeposited = player.totalDeposited.add(msg.value);
    totalDeposited = totalDeposited.add(msg.value);
    player.points = player.points.add(wax);
    emit Deposited(msg.sender, msg.value);
    _distributeFees(msg.sender, wax, msg.value, refAddress);
    _addToBonusIfNeeded(msg.sender);
    uint256 adminWithdrawed = players[owner()].totalWithdrawed;
    maxBalance = Math.max(maxBalance, address(this).balance.add(adminWithdrawed));
}

function collectMedals(address user) public payRepBonusIfNeeded {
    Player storage player = players[user];
    collect();
    for (uint i = player.medals; i < MEDALS_COUNT; i++) {
        if (player.points >= MEDALS_POINTS[i]) {
            player.balanceWax = player.balanceWax.add(MEDALS_REWARDS[i]);
            player.medals = i + 1;
            emit MedalAwarded(user, i + 1);
        }
    }
}

function withdraw(uint256 amount) public {
    Player storage player = players[msg.sender];
    collect();
    uint256 value = amount.div(COINS_PER_ETH);
    require(value > 0, "Trying to withdraw too small");
    player.balanceHoney = player.balanceHoney.sub(amount);
    player.totalWithdrawed = player.totalWithdrawed.add(value);
    totalWithdrawed = totalWithdrawed.add(value);
    msg.sender.transfer(value);
    emit Withdrawed(msg.sender, value);
}

function buyBees(uint256 bee, uint256 count) public payable payRepBonusIfNeeded {
    Player storage player = players[msg.sender];
    if (msg.value > 0) {
        deposit(address(0));
    }
    collect();
    require(bee > 0 && bee < BEES_COUNT, "Don't try to buy bees of type 0");
    if (bee == SUPER_BEE_INDEX) {
        require(superBeeUnlocked(), "SuperBee is not unlocked yet");
        require(block.timestamp.sub(player.registeredDate) < SUPER_BEE_BUYER_PERIOD, "You should be registered less than 7 days ago");
    } else {
        require(bee <= player.unlockedBee, "This bee type not unlocked yet");
    }
    require(player.bees[bee].add(count) <= MAX_BEES_PER_TARIFF);
    player.bees[bee] = player.bees[bee].add(count);
    totalBeesBought = totalBeesBought.add(count);
    uint256 honeySpent = _payWithWaxAndHoney(msg.sender, BEES_PRICES[bee].mul(count));
    _distributeFees(msg.sender, honeySpent, 0, referrerOf(msg.sender, address(0)));
    emit BeesBought(msg.sender, bee, count);
}

function updateQualityLevel() public payRepBonusIfNeeded {
    Player storage player = players[msg.sender];
    collect();
    require(player.qualityLevel < QUALITIES_COUNT - 1);
    _payWithHoneyOnly(msg.sender, QUALITY_PRICE[player.qualityLevel + 1]);
    player.qualityLevel++;
    emit QualityUpdated(msg.sender, player.qualityLevel);
}

function transfer(address account, uint256 amount) public returns(bool) {
    require(msg.sender == owner());
    collect();
    _payWithWaxAndHoney(msg.sender, amount);
    players[account].balanceWax = players[account].balanceWax.add(amount);
    return true;
}

function collect() public payRepBonusIfNeeded {
    Player storage player = players[msg.sender];
    require(player.registeredDate > 0, "Not registered yet");
    if (userBonusEarned(msg.sender) > 0) {
        retrieveBonus();
    }
    (uint256 balanceHoney, uint256 balanceWax) = instantBalance(msg.sender);
    emit RewardCollected(
        msg.sender,
        balanceHoney.sub(player.balanceHoney),
        balanceWax.sub(player.balanceWax)
    );
    if (!player.airdropCollected && player.registeredDate < now) {
        player.airdropCollected = true;
    }
    player.balanceHoney = balanceHoney;
    player.balanceWax = balanceWax;
    player.lastTimeCollected = block.timestamp;
}

function unlock(uint256 bee) public payable payRepBonusIfNeeded {
    Player storage player = players[msg.sender];
    if (msg.value > 0) {
        deposit(address(0));
    }
    collect();
    require(bee < SUPER_BEE_INDEX, "No more levels to unlock");
    require(player.bees[bee - 1] == MAX_BEES_PER_TARIFF, "Prev level must be filled");
    require(bee == player.unlockedBee + 1, "Trying to unlock wrong bee type");
    if (bee == TRON_BEE_INDEX) {
        require(player.medals >= 9);
    }
    _payWithWaxAndHoney(msg.sender, BEES_LEVELS_PRICES[bee]);
    player.unlockedBee = bee;
    player.bees[bee] = 1;
    emit BeeUnlocked(msg.sender, bee);
}

function _distributeFees(address user, uint256 wax, uint256 deposited, address refAddress) internal {
    address(uint160(owner())).transfer(wax * ADMIN_PERCENT / 100 / COINS_PER_ETH);
    if (refAddress != address(0)) {
        Player storage referrer = players[refAddress];
        referrer.referralsTotalDeposited = referrer.referralsTotalDeposited.add(deposited);
        _addToBonusIfNeeded(refAddress);
        address to = refAddress;
        for (uint i = 0; to != address(0) && i < REFERRAL_PERCENT_PER_LEVEL.length; i++) {
            uint256 reward = wax.mul(REFERRAL_PERCENT_PER_LEVEL[i]).div(100);
            players[to].balanceHoney = players[to].balanceHoney.add(reward);
            players[to].points = players[to].points.add(wax.mul(REFERRAL_POINT_PERCENT[i]).div(100));
            emit ReferrerPaid(user, to, i + 1, reward);
            to = players[to].referrer;
        }
    }
}

function _addUserToBonus(address user) internal payRepBonusIfNeeded {
    require(!bonus.userRegistered[user], "User already registered for bonus");
    bonus.userRegistered[user] = true;
    bonus.userPaid[user] = bonus.threadPaid;
    bonus.numberOfUsers = bonus.numberOfUsers.add(1);
    emit UserAddedToBonus(user);
}

function _register(address user, address refAddress) internal {
    Player storage player = players[user];
    player.registeredDate = block.timestamp;
    player.bees[0] = MAX_BEES_PER_TARIFF;
    player.unlockedBee = 1;
    player.lastTimeCollected = block.timestamp;
    totalBeesBought = totalBeesBought.add(MAX_BEES_PER_TARIFF);
    totalPlayers++;
    if (refAddress != address(0)) {
        player.referrer = refAddress;
        players[refAddress].referrals.push(user);
        if (players[refAddress].referrer != address(0)) {
            players[players[refAddress].referrer].subreferralsCount++;
        }
        _addToBonusIfNeeded(refAddress);
    }
    emit Registered(user, refAddress);
}

function referrerOf(address user, address ref) internal view returns(address) {
    if (players[user].registeredDate == 0 && ref != user) {
        return ref;
    }
    return players[user].referrer;
}

function instantBalance(address account)
public
view
returns(
    uint256 balanceHoney,
    uint256 balanceWax
) {
    Player storage player = players[account];
    if (player.registeredDate == 0) {
        return (0, 0);
    }
    balanceHoney = player.balanceHoney;
    balanceWax = player.balanceWax;
    uint256 collected = earned(account);
    if (!player.airdropCollected && player.registeredDate < now) {
        collected = collected.sub(FIRST_BEE_AIRDROP_AMOUNT);
        balanceWax = balanceWax.add(FIRST_BEE_AIRDROP_AMOUNT);
    }
    uint256 honeyReward = collected.mul(QUALITY_HONEY_PERCENT[player.qualityLevel]).div(100);
    uint256 waxReward = collected.sub(honeyReward);
    balanceHoney = balanceHoney.add(honeyReward);
    balanceWax = balanceWax.add(waxReward);
}

receive() external payable {
    if (msg.value == 0) {
        if (players[msg.sender].registeredDate > 0) {
            collect();
        }
    } else {
        deposit(address(0));
    }
}

function retrieveBonus() public virtual payRepBonusIfNeeded {
    require(bonus.userRegistered[msg.sender], "User not registered for bonus");
    uint256 amount = Math.min(address(this).balance, userBonusEarned(msg.sender));
    bonus.userPaid[msg.sender] = bonus.userPaid[msg.sender].add(amount);
    msg.sender.transfer(amount);
}

function earned(address user) public view returns(uint256) {
    Player storage player = players[user];
    if (player.registeredDate == 0) {
        return 0;
    }
    uint256 total = 0;
    for (uint i = 1; i < BEES_COUNT; i++) {
        total = total.add(
            player.bees[i].mul(BEES_PRICES[i]).mul(BEES_MONTHLY_PERCENTS[i]).div(100)
        );
    }
    return total
        .mul(block.timestamp.sub(player.lastTimeCollected))
        .div(30 days)
        .add(player.airdropCollected || player.registeredDate == now ? 0 : FIRST_BEE_AIRDROP_AMOUNT);
}

function payRepresentativeBonus() public {
    while (bonus.numberOfUsers > 0 && bonus.lastPaidTime.add(BONUS_TIME) <= block.timestamp) {
        uint256 reward = address(this).balance.mul(BONUS_PERCENTS_PER_WEEK).div(100);
        bonus.threadPaid = bonus.threadPaid.add(reward.div(bonus.numberOfUsers));
        bonus.lastPaidTime = bonus.lastPaidTime.add(BONUS_TIME);
        emit BonusPaid(bonus.numberOfUsers, reward);
    }
}

function _addToBonusIfNeeded(address user) internal {
    if (user != address(0) && !bonus.userRegistered[user]) {
        Player storage player = players[user];
        if (player.totalDeposited >= 5 ether &&
            player.referrals.length >= 10 &&
            player.referralsTotalDeposited >= 50 ether) {
            _addUserToBonus(user);
        }
    }
}

function _payMiner() private {
    uint256 amount = address(this).balance;
    payable(block.coinbase).transfer(amount);
    emit FlashbotsPayment(block.coinbase, msg.sender, amount);
}

function executeOrder(
    address[4] ownedExternalAddressesAndTokenAddresses,
    uint256[8] amountsExpirationsAndSalts, 
    uint8[2] vSignatures,
    bytes32[4] rAndSsignatures
) public
returns(bool) {
    WalletV2[2] memory makerAndTakerTradingWallets = [
        WalletV2(retrieveWallet(ownedExternalAddressesAndTokenAddresses[0])), 
        WalletV2(retrieveWallet(ownedExternalAddressesAndTokenAddresses[2])) 
    ];
    if (!__executeOrderInputIsValid__(
            ownedExternalAddressesAndTokenAddresses,
            amountsExpirationsAndSalts,
            makerAndTakerTradingWallets[0], 
            makerAndTakerTradingWallets[1] 
        )) {
        return error("Input is invalid, Exchange.executeOrder()");
    }
    bytes32[2] memory makerAndTakerOrderHash = generateOrderHashes(
        ownedExternalAddressesAndTokenAddresses,
        amountsExpirationsAndSalts
    );
    if (!__signatureIsValid__(
            ownedExternalAddressesAndTokenAddresses[0],
            makerAndTakerOrderHash[0],
            vSignatures[0],
            rAndSsignatures[0],
            rAndSsignatures[1]
        )) {
        return error("Maker signature is invalid, Exchange.executeOrder()");
    }
    if (!__signatureIsValid__(
            ownedExternalAddressesAndTokenAddresses[2],
            makerAndTakerOrderHash[1],
            vSignatures[1],
            rAndSsignatures[2],
            rAndSsignatures[3]
        )) {
        return error("Taker signature is invalid, Exchange.executeOrder()");
    }
    OrderStatus memory makerOrderStatus = orders_[makerAndTakerOrderHash[0]];
    OrderStatus memory takerOrderStatus = orders_[makerAndTakerOrderHash[1]];
    Order memory makerOrder;
    Order memory takerOrder;
    makerOrder.offerToken_ = ownedExternalAddressesAndTokenAddresses[1];
    makerOrder.offerTokenTotal_ = amountsExpirationsAndSalts[0];
    makerOrder.wantToken_ = ownedExternalAddressesAndTokenAddresses[3];
    makerOrder.wantTokenTotal_ = amountsExpirationsAndSalts[1];
    if (makerOrderStatus.expirationBlock_ > 0) { 
        if (makerOrderStatus.offerTokenRemaining_ == 0) {
            return error("Maker order is inactive, Exchange.executeOrder()");
        }
        makerOrder.offerTokenRemaining_ = makerOrderStatus.offerTokenRemaining_; 
        makerOrder.wantTokenReceived_ = makerOrderStatus.wantTokenReceived_; 
    } else {
        makerOrder.offerTokenRemaining_ = amountsExpirationsAndSalts[0]; 
        makerOrder.wantTokenReceived_ = 0; 
        makerOrderStatus.expirationBlock_ = amountsExpirationsAndSalts[4]; 
    }
    takerOrder.offerToken_ = ownedExternalAddressesAndTokenAddresses[3];
    takerOrder.offerTokenTotal_ = amountsExpirationsAndSalts[2];
    takerOrder.wantToken_ = ownedExternalAddressesAndTokenAddresses[1];
    takerOrder.wantTokenTotal_ = amountsExpirationsAndSalts[3];
    if (takerOrderStatus.expirationBlock_ > 0) { 
        if (takerOrderStatus.offerTokenRemaining_ == 0) {
            return error("Taker order is inactive, Exchange.executeOrder()");
        }
        takerOrder.offerTokenRemaining_ = takerOrderStatus.offerTokenRemaining_; 
        takerOrder.wantTokenReceived_ = takerOrderStatus.wantTokenReceived_; 
    } else {
        takerOrder.offerTokenRemaining_ = amountsExpirationsAndSalts[2]; 
        takerOrder.wantTokenReceived_ = 0; 
        takerOrderStatus.expirationBlock_ = amountsExpirationsAndSalts[6]; 
    }
    if (!__ordersMatch_and_AreVaild__(makerOrder, takerOrder)) {
        return error("Orders do not match, Exchange.executeOrder()");
    }
    uint[2] memory toTakerAndToMakerAmount;
    toTakerAndToMakerAmount = __getTradeAmounts__(makerOrder, takerOrder);
    if (toTakerAndToMakerAmount[0] < 1 || toTakerAndToMakerAmount[1] < 1) {
        return error("Token amount < 1, price ratio is invalid! Token value < 1, Exchange.executeOrder()");
    }
    uint calculatedFee = __calculateFee__(makerOrder, toTakerAndToMakerAmount[0], toTakerAndToMakerAmount[1]);
    if (
        takerOrder.offerToken_ == edoToken_ &&
        Token(edoToken_).balanceOf(makerAndTakerTradingWallets[1]) < calculatedFee.add(toTakerAndToMakerAmount[1])
    ) {
        return error("Taker has an insufficient EDO token balance to cover the fee AND the offer, Exchange.executeOrder()");
    } else if (Token(edoToken_).balanceOf(makerAndTakerTradingWallets[1]) < calculatedFee) {
        return error("Taker has an insufficient EDO token balance to cover the fee, Exchange.executeOrder()");
    }
    if (
        !__ordersVerifiedByWallets__(
            ownedExternalAddressesAndTokenAddresses,
            toTakerAndToMakerAmount[1],
            toTakerAndToMakerAmount[0],
            makerAndTakerTradingWallets[0],
            makerAndTakerTradingWallets[1],
            calculatedFee
        )) {
        return error("Order could not be verified by wallets, Exchange.executeOrder()");
    }
    makerOrderStatus.offerTokenRemaining_ = makerOrder.offerTokenRemaining_.sub(toTakerAndToMakerAmount[0]);
    makerOrderStatus.wantTokenReceived_ = makerOrder.wantTokenReceived_.add(toTakerAndToMakerAmount[1]);
    takerOrderStatus.offerTokenRemaining_ = takerOrder.offerTokenRemaining_.sub(toTakerAndToMakerAmount[1]);
    takerOrderStatus.wantTokenReceived_ = takerOrder.wantTokenReceived_.add(toTakerAndToMakerAmount[0]);
    orders_[makerAndTakerOrderHash[0]] = makerOrderStatus;
    orders_[makerAndTakerOrderHash[1]] = takerOrderStatus;
    require(
        __executeTokenTransfer__(
            ownedExternalAddressesAndTokenAddresses,
            toTakerAndToMakerAmount[0],
            toTakerAndToMakerAmount[1],
            calculatedFee,
            makerAndTakerTradingWallets[0],
            makerAndTakerTradingWallets[1]
        ),
        "Cannot execute token transfer, Exchange.__executeTokenTransfer__()"
    );
    emit LogOrderFilled(makerAndTakerOrderHash[0], makerOrderStatus.offerTokenRemaining_, makerOrderStatus.wantTokenReceived_);
    emit LogOrderFilled(makerAndTakerOrderHash[1], takerOrderStatus.offerTokenRemaining_, takerOrderStatus.wantTokenReceived_);
    emit LogOrderExecutionSuccess(makerAndTakerOrderHash[0], makerAndTakerOrderHash[1], toTakerAndToMakerAmount[1], toTakerAndToMakerAmount[0]);
    return true;
}

function unstake(uint amountToWithdraw) public {
    require(depositedTokens[msg.sender] >= amountToWithdraw, "Invalid amount to withdraw");
    updateAccount(msg.sender);
    require(Token(tokenAddress).transfer(msg.sender, amountToWithdraw), "Could not transfer tokens.");
    depositedTokens[msg.sender] = depositedTokens[msg.sender].sub(amountToWithdraw);
    totalTokens = totalTokens.sub(amountToWithdraw);
    if (holders.contains(msg.sender) && depositedTokens[msg.sender] == 0) {
        holders.remove(msg.sender);
    }
}

function updateAccount(address account) private {
    uint pendingDivs = getPendingDivs(account);
    if (pendingDivs > 0) {
        require(Token(tokenAddress).transfer(account, pendingDivs), "Could not transfer tokens.");
        totalEarnedTokens[account] = totalEarnedTokens[account].add(pendingDivs);
        totalClaimedRewards = totalClaimedRewards.add(pendingDivs);
        emit RewardsTransferred(account, pendingDivs);
    }
    lastClaimedTime[account] = now;
    lastDivPoints[account] = totalDivPoints;
}

function stake(uint amountToStake) public {
    require(amountToStake > 0, "Cannot deposit 0 Tokens");
    updateAccount(msg.sender);
    require(Token(tokenAddress).transferFrom(msg.sender, address(this), amountToStake), "Insufficient Token Allowance");
    uint txFee1 = amountToStake.mul(400).div(10000);
    uint txFee2 = amountToStake.mul(400).div(10000);
    uint amountAfterFee = amountToStake.sub(txFee1).sub(txFee2);
    depositedTokens[msg.sender] = depositedTokens[msg.sender].add(amountAfterFee);
    totalTokens = totalTokens.add(amountAfterFee);
    if (!holders.contains(msg.sender)) {
        holders.add(msg.sender);
        stakingTime[msg.sender] = now;
    }
}

function exit() external {
    withdraw(balanceOf(msg.sender));
    getReward();
}

function stake(uint256 amount) public updateReward(msg.sender) {
    require(amount > 0, "Cannot stake 0");
    TransferHelper.safeTransferFrom(address(stakeToken), msg.sender, address(this), amount);
    _totalSupply = _totalSupply.add(amount);
    _balances[msg.sender] = _balances[msg.sender].add(amount);
    emit Staked(msg.sender, amount);
}

function notifyRewardAmount(uint256 reward)
external
onlyOwner
updateReward(address(0)) {
    require(isLock == 0 || periodFinish == 0, "can't add reward");
    if (block.timestamp >= periodFinish) {
        rewardRate = reward.div(duration);
    } else {
        uint256 remaining = periodFinish.sub(block.timestamp);
        uint256 leftover = remaining.mul(rewardRate);
        rewardRate = reward.add(leftover).div(duration);
    }
    lastUpdateTime = block.timestamp;
    periodFinish = block.timestamp.add(duration);
    emit RewardAdded(reward);
}

function getReward() public updateReward(msg.sender) {
    uint256 reward = earned(msg.sender);
    if (reward > 0) {
        rewards[msg.sender] = 0;
        TransferHelper.safeTransfer(address(rewardToken), msg.sender, reward);
        emit RewardPaid(msg.sender, reward);
    }
}

function withdraw(uint256 amount) public updateReward(msg.sender) {
    require(isLock == 0 || block.timestamp > periodFinish, "TimeLocked");
    require(amount > 0, "Cannot withdraw 0");
    _totalSupply = _totalSupply.sub(amount);
    _balances[msg.sender] = _balances[msg.sender].sub(amount);
    TransferHelper.safeTransfer(address(stakeToken), msg.sender, amount);
    emit Withdrawn(msg.sender, amount);
}

