function claimToken(address _tokenAddr, address _payee) public {
    require(balances[_payee] > 0);
    require(isTokenTracked[_tokenAddr]);
    uint payment = getUnclaimedTokenAmount(_tokenAddr, _payee);
    if (payment == 0) {
        return;
    }
    ERC20 Token = ERC20(_tokenAddr);
    require(Token.balanceOf(address(this)) >= payment);
    tokensReleased[address(Token)][_payee] = tokensReleased[address(Token)][_payee].add(payment);
    totalTokensReleased[address(Token)] = totalTokensReleased[address(Token)].add(payment);
    Token.transfer(_payee, payment);
}

function unTrackToken(address _addr, uint16 _position) onlyAdmin public {
    require(isTokenTracked[_addr]);
    require(trackedTokens[_position] == _addr);
    ERC20(_addr).transfer(_addr, ERC20(_addr).balanceOf(address(this)));
    trackedTokens[_position] = trackedTokens[trackedTokens.length - 1];
    delete trackedTokens[trackedTokens.length - 1];
    trackedTokens.length--;
}

function depositTokens(address from, address token, uint256 tokens) public returns(bool success) {
    if (!ERC20Interface(token).transferFrom(from, this, tokens)) revert();
    balances[token][from] = balances[token][from].add(tokens);
    depositedTokens[token] = depositedTokens[token].add(tokens);
    Deposit(token, from, tokens, balances[token][from]);
    return true;
}

function claim(
    uint256 index,
    uint256 balance,
    uint256 bonusAmount,
    uint256 expiry,
    uint256 expireAfter,
    MigrationType migrationType,
    bytes32[] calldata merkleProof
) external {
    require(!isClaimed(index), "FlashV2Migration: Already claimed.");
    address user = msg.sender;
    require(
        MerkleProof.verify(
            merkleProof,
            MERKLE_ROOT,
            keccak256(
                abi.encodePacked(index, user, balance, bonusAmount, expiry, expireAfter, uint256(migrationType))
            )
        ),
        "FlashV2Migration: Invalid proof."
    );
    uint256 flashV2Mint = balance;
    if (migrationType == MigrationType.V1_UNCLAIMED) {
        require(block.timestamp <= V1_UNCLAIMED_DEADLINE, "FlashV2Migration: V1 claim time expired.");
    } else if (migrationType == MigrationType.HOLDER) {
        flashV2Mint = _getMigratableAmountAndTransferV1(user, balance);
    } else if (migrationType == MigrationType.STAKER) {
        if (expireAfter > block.timestamp) {
            uint256 burnAmount = balance.mul(expireAfter.sub(block.timestamp)).mul(75e16).div(expiry.mul(1e18));
            flashV2Mint = balance.sub(burnAmount);
        }
    } else {
        revert("FlashV2Migration: Invalid migration type");
    }
    _setClaimed(index);
    IFlashToken(FLASH_TOKEN_V2).mint(user, flashV2Mint.add(bonusAmount));
    emit Claimed(index, user, flashV2Mint);
}

function buy(
    ITradeable tradeable,
    uint volume,
    bytes ordersData,
    address destinationAddr,
    address affiliate
) external payable {
    require(tradingEnabled);
    trade(
        false,
        tradeable,
        volume,
        ordersData,
        affiliate
    );
    uint volumeEffective = tradeable.balanceOf(this);
    require(volumeEffective > 0);
    uint volumeEthEffective = SafeMath.safeSub(msg.value, address(this).balance);
    require(
        SafeMath.safeDiv(volumeEthEffective, volumeEffective) <=
        SafeMath.safeDiv(msg.value, volume)
    );
    if (address(this).balance > 0) {
        destinationAddr.transfer(address(this).balance);
    }
    transferTradeable(tradeable, destinationAddr, volumeEffective);
    emit Buy(msg.sender, destinationAddr, tradeable, volume, msg.value, volumeEffective, volumeEthEffective);
}

function sell(
    ITradeable tradeable,
    uint volume,
    uint volumeEth,
    bytes ordersData,
    address destinationAddr,
    address affiliate
) external {
    require(tradingEnabled);
    require(tradeable.transferFrom(msg.sender, this, volume));
    trade(
        true,
        tradeable,
        volume,
        ordersData,
        affiliate
    );
    uint volumeEffective = SafeMath.safeSub(volume, tradeable.balanceOf(this));
    require(volumeEffective > 0);
    uint volumeEthEffective = collectSellFee();
    require(
        SafeMath.safeDiv(volumeEthEffective, volumeEffective) >=
        SafeMath.safeDiv(volumeEth, volume)
    );
    if (volumeEffective < volume) {
        transferTradeable(tradeable, destinationAddr, SafeMath.safeSub(volume, volumeEffective));
    }
    destinationAddr.transfer(volumeEthEffective);
    emit Sell(msg.sender, destinationAddr, tradeable, volume, volumeEth, volumeEffective, volumeEthEffective);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[_from]);
    require(_value <= allowed[_from][msg.sender]);
    if (_from == fundsWallet) {
        require(_value <= balances[_from]);
    }
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        bytes memory _data = new bytes(1);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[_from] = SafeMath.sub(balances[_from], _value);
    balances[_to] = SafeMath.add(balances[_to], _value);
    allowed[_from][msg.sender] = SafeMath.sub(allowed[_from][msg.sender], _value);
    allowed[_from][msg.sender] = SafeMath.sub(allowed[_from][msg.sender], _value);
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint256 _value) public returns(bool) {
    require(_to != address(0));
    require(_value <= balances[msg.sender]);
    if (isContract(_to)) {
        ERC223ReceivingContract receiver = ERC223ReceivingContract(_to);
        bytes memory _data = new bytes(1);
        receiver.tokenFallback(msg.sender, _value, _data);
    }
    balances[msg.sender] = SafeMath.sub(balances[msg.sender], _value);
    balances[_to] = SafeMath.add(balances[_to], _value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function transferMultiple(address[] _tos, uint256[] _values, uint count) payable public returns(bool) {
    uint256 total = 0;
    uint256 total_prev = 0;
    uint i = 0;
    for (i = 0; i < count; i++) {
        require(_tos[i] != address(0) && !isContract(_tos[i])); 
        if (isContract(_tos[i])) {
            ERC223ReceivingContract receiver = ERC223ReceivingContract(_tos[i]);
            bytes memory _data = new bytes(1);
            receiver.tokenFallback(msg.sender, _values[i], _data);
        }
        total_prev = total;
        total = SafeMath.add(total, _values[i]);
        require(total >= total_prev);
    }
    require(total <= balances[msg.sender]);
    for (i = 0; i < count; i++) {
        balances[msg.sender] = SafeMath.sub(balances[msg.sender], _values[i]);
        balances[_tos[i]] = SafeMath.add(balances[_tos[i]], _values[i]);
        Transfer(msg.sender, _tos[i], _values[i]);
    }
    return true;
}

function lockBalance(uint256 duration, uint256 amount) public {
    address _owner = msg.sender;
    require(address(0) != _owner && amount > 0 && duration > 0 && balanceOf(_owner) >= amount);
    require(addressFrozenFund[_owner].release <= now && addressFrozenFund[_owner].amount == 0);
    addressFrozenFund[_owner].start = now;
    addressFrozenFund[_owner].duration = duration;
    addressFrozenFund[_owner].release = addressFrozenFund[_owner].start + duration;
    addressFrozenFund[_owner].amount = amount;
    burnToken(_owner, amount);
    _lockedSupply = SafeMath.add(_lockedSupply, lockedBalanceOf(_owner));
    LockBalance(_owner, addressFrozenFund[_owner].release, amount);
}

function releaseLockedBalance() public {
    address _owner = msg.sender;
    require(address(0) != _owner && lockedBalanceOf(_owner) > 0 && releaseTimeOf(_owner) <= now);
    mintToken(_owner, lockedBalanceOf(_owner));
    _lockedSupply = SafeMath.sub(_lockedSupply, lockedBalanceOf(_owner));
    UnlockBalance(_owner, addressFrozenFund[_owner].release, lockedBalanceOf(_owner));
    delete addressFrozenFund[_owner];
}

