function _transfer(address from, address to, uint256 amount) internal {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    if (to == uniswapV2Pair && from != owner()) {
        if (block.timestamp - lastSell[from] < 1 days) {
            require(amount <= daySellLimit);
            require(amount + tokensSold[from] <= daySellLimit, "Can only sell 2,000,000 every 24 hours");
            lastSell[from] = block.timestamp;
            tokensSold[from] = tokensSold[from].add(amount);
        } else { 
            tokensSold[from] = 0;
            require(amount <= daySellLimit, "Can only sell 2,000,000 every 24 hours");
            tokensSold[from] = amount;
            lastSell[from] = block.timestamp;
        }
    }
    _balances[from] = _balances[from].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[to] = _balances[to].add(amount);
    emit Transfer(from, to, amount);
}

function doTrade(
    ERC20 srcToken,
    uint srcAmount,
    ERC20 destToken,
    address destAddress,
    uint conversionRate,
    bool validate
)
internal
returns(bool) {
    uint actualDestAmount;
    require((ETH_TOKEN_ADDRESS == srcToken) || (ETH_TOKEN_ADDRESS == destToken));
    require((tradeToken == srcToken) || (tradeToken == destToken));
    if (validate) {
        require(conversionRate > 0);
        if (srcToken == ETH_TOKEN_ADDRESS)
            require(msg.value == srcAmount);
        else
            require(msg.value == 0);
    }
    uint destAmount = getDestQty(srcToken, destToken, srcAmount, conversionRate);
    require(destAmount > 0);
    if (srcToken == ETH_TOKEN_ADDRESS) {
        actualDestAmount = oasisDirect.sellAllAmountPayEth.value(msg.value)(otc, wethToken, destToken, destAmount);
        require(actualDestAmount >= destAmount);
        require(destToken.transfer(destAddress, destAmount));
    } else {
        require(srcToken.transferFrom(msg.sender, this, srcAmount));
        if (srcToken.allowance(this, oasisDirect) < srcAmount) {
            srcToken.approve(oasisDirect, uint(-1));
        }
        actualDestAmount = oasisDirect.sellAllAmountBuyEth(otc, srcToken, srcAmount, wethToken, destAmount);
        require(actualDestAmount >= destAmount);
        destAddress.transfer(destAmount);
    }
    TradeExecute(msg.sender, srcToken, srcAmount, destToken, destAmount, destAddress);
    return true;
}

function createRegulatorProxy(address regulatorImplementation) public {
    address proxy = address(new RegulatorProxy(regulatorImplementation));
    Regulator newRegulator = Regulator(proxy);
    newRegulator.addValidator(msg.sender);
    addAllPermissions(newRegulator);
    RegulatorProxy(proxy).transferOwnership(msg.sender);
    regulators.push(proxy);
    emit CreatedRegulatorProxy(proxy, getCount() - 1);
}

