    uint256 _nonVestedAmount,
    bytes32[] calldata _merkleProof
) external {
    require(!claimed[_msgSender()], "claimed");
    require(
        verifyClaim(
            _msgSender(),
            _vestedAmount,
            _nonVestedAmount,
            _merkleProof
        ),
        "not eligible for a claim"
    );
    claimed[_msgSender()] = true;
    PlatformToken(platformToken).autoAirdrop(
