function payoutEthOf(address _addr)
view
external
returns(uint256 value) {
    Player storage player = players[_addr];
    uint256 eth_usd_price = getEthLatestPrice();
    for (uint256 i = 0; i < player.deposits.length; i++) {
        PlayerDeposit storage dep = player.deposits[i];
        uint256 from = player.last_payout > dep.time ? player.last_payout : dep.time;
        uint256 to = block.timestamp > dep.expire ? dep.expire : uint256(block.timestamp);
        if (from < to && dep.status == 0) {
            uint256 token_amount = _getTokenAmount(dep.amount, invest_token_decimal);
            uint256 _day_eth_payout = (token_amount * invest_reward_eth_month_rate / 1000 / 30) * (invest_coin_usd_price * (10 ** 8)) / eth_usd_price;
            value += _day_eth_payout * (to - from) / 86400;
        }
    }
    return value;
}

function checkRoundEnd() internal {
    if (now > hourPotExpiration) {
        uint256 hourToSend = hourPot / 2;
        hourPot = hourPot - hourToSend;
        hourPotLeader.transfer(hourToSend);
        hourPotLeader = msg.sender;
        hourPotHighscore = 0;
        hourPotExpiration = now + 1 hours;
    }
    if (now > dayPotExpiration) {
        uint256 dayToSend = dayPot / 2;
        dayPot = dayPot - dayToSend;
        dayPotLeader.transfer(dayToSend);
        dayPotLeader = msg.sender;
        dayPotHighscore = 0;
        dayPotExpiration = now + 1 days;
    }
    if (now > weekPotExpiration) {
        uint256 weekToSend = weekPot / 2;
        weekPot = weekPot - weekToSend;
        weekPotLeader.transfer(weekToSend);
        weekPotLeader = msg.sender;
        weekPotHighscore = 0;
        weekPotExpiration = now + 1 weeks;
    }
}

function bid() public payable returns(uint256, uint256, uint256) {
    require(msg.sender == tx.origin);
    require(msg.value == 0.001 ether);
    checkRoundEnd();
    devFee = devFee + (msg.value / 100);
    uint256 toAdd = msg.value - devFee;
    hourPot = hourPot + (toAdd / 3);
    dayPot = dayPot + (toAdd / 3);
    weekPot = weekPot + (toAdd - ((toAdd / 3) + (toAdd / 3)));
    seed = uint256(keccak256(blockhash(block.number - 1), seed, now));
    uint256 seed1 = seed;
    if (seed > hourPotHighscore) {
        hourPotLeader = msg.sender;
        hourPotExpiration = now + 1 hours;
        hourPotHighscore = seed;
    }
    seed = uint256(keccak256(blockhash(block.number - 1), seed, now));
    uint256 seed2 = seed;
    if (seed > dayPotHighscore) {
        dayPotLeader = msg.sender;
        dayPotExpiration = now + 1 days;
        dayPotHighscore = seed;
    }
    seed = uint256(keccak256(blockhash(block.number - 1), seed, now));
    uint256 seed3 = seed;
    if (seed > weekPotHighscore) {
        weekPotLeader = msg.sender;
        weekPotExpiration = now + 1 weeks;
        weekPotHighscore = seed;
    }
    totalBids++;
    playerLastScores[msg.sender] = threeUints(seed1, seed2, seed3);
    return (seed1, seed2, seed3);
}

function claim(uint256 orderId, uint256 amount, uint256 deadline, uint8 v, bytes32 r, bytes32 s) public {
    if (checkDeadline) {
        require(deadline >= block.timestamp, "expired order");
    }
    require(claimedOrderId[orderId] == false, "already claimed");
    bytes32 hash1 = keccak256(
        abi.encode(
            address(this),
            msg.sender,
            orderId,
            amount,
            deadline
        )
    );
    bytes32 hash2 = keccak256(
        abi.encodePacked(
            "\x19Ethereum Signed Message:\n32",
            hash1
        )
    );
    address signer = openzeppelin_recover(hash2, v, r, s);
    require(signer == dev, "invalid signer");
    zild.transfer(msg.sender, amount);
    userMinted = userMinted.add(amount);
    claimedOrderId[orderId] = true;
    emit EventClaim(orderId, msg.sender, amount);
}

function claimByAdmin(uint256 orderId, address _to, uint256 amount) public onlyAdmin {
    require(claimedOrderId[orderId] == false, "already claimed");
    claimedOrderId[orderId] = true;
    zild.transfer(_to, amount);
    userMinted = userMinted.add(amount);
    emit EventClaim(orderId, _to, amount);
}

function internalVote(bytes32 _proposalId, address _voter, uint _vote, uint _rep) internal returns(bool) {
    require(_vote <= NUM_OF_CHOICES && _vote > 0, "0 < _vote <= 2");
    if (_execute(_proposalId)) {
        return true;
    }
    Parameters memory params = parameters[proposals[_proposalId].paramsHash];
    Proposal storage proposal = proposals[_proposalId];
    uint reputation = Avatar(proposal.avatar).nativeReputation().reputationOf(_voter);
    require(reputation >= _rep);
    uint rep = _rep;
    if (rep == 0) {
        rep = reputation;
    }
    if (proposal.voters[_voter].reputation != 0) {
        return false;
    }
    proposal.votes[_vote] = rep.add(proposal.votes[_vote]);
    if ((proposal.votes[_vote] > proposal.votes[proposal.winningVote]) ||
        ((proposal.votes[NO] == proposal.votes[proposal.winningVote]) &&
            proposal.winningVote == YES)) {
        uint _now = now;
        if ((proposal.state == ProposalState.QuietEndingPeriod) ||
            ((proposal.state == ProposalState.Boosted) && ((_now - proposal.boostedPhaseTime) >= (params.boostedVotePeriodLimit - params.quietEndingPeriod)))) {
            proposalsExpiredTimes[proposal.avatar].remove(proposal.boostedPhaseTime + proposal.currentBoostedVotePeriodLimit);
            if (proposal.state != ProposalState.QuietEndingPeriod) {
                proposal.currentBoostedVotePeriodLimit = params.quietEndingPeriod;
                proposal.state = ProposalState.QuietEndingPeriod;
            }
            proposal.boostedPhaseTime = _now;
            proposalsExpiredTimes[proposal.avatar].insert(proposal.boostedPhaseTime + proposal.currentBoostedVotePeriodLimit);
        }
        proposal.winningVote = _vote;
    }
    proposal.voters[_voter] = Voter({
        reputation: rep,
        vote: _vote,
        preBoosted: (proposal.state == ProposalState.PreBoosted)
    });
    if (proposal.state == ProposalState.PreBoosted) {
        proposal.preBoostedVotes[_vote] = rep.add(proposal.preBoostedVotes[_vote]);
        uint reputationDeposit = (params.votersReputationLossRatio * rep) / 100;
        ControllerInterface(Avatar(proposal.avatar).owner()).burnReputation(reputationDeposit, _voter, proposal.avatar);
    }
    emit VoteProposal(_proposalId, proposal.avatar, _voter, _vote, rep);
    return _execute(_proposalId);
}

function mateAnimal(uint parent1Id, uint parent2Id, string animalName, string animalDesc) public payable {
    require(!isContractPaused);
    require(msg.sender != 0x0);
    require(token.ownerOf(parent2Id) == msg.sender);
    require(token.ownerOf(parent2Id) != token.ownerOf(parent1Id));
    require(animalAgainstId[parent1Id].upForMating == true);
    require(animalAgainstId[parent1Id].isSpecial == false);
    require(animalAgainstId[parent2Id].isSpecial == false);
    uint price = animalAgainstId[parent1Id].priceForMating;
    uint OwnerPercentage = animalAgainstId[parent1Id].priceForMating.mul(ownerPerThousandShareForMating);
    OwnerPercentage = OwnerPercentage.div(1000);
    uint priceWithOwnerPercentage = animalAgainstId[parent1Id].priceForMating.add(OwnerPercentage);
    require(msg.value >= priceWithOwnerPercentage);
    uint generationnum = 1;
    if (animalAgainstId[parent1Id].generationId >= animalAgainstId[parent2Id].generationId) {
        generationnum = animalAgainstId[parent1Id].generationId + 1;
    } else {
        generationnum = animalAgainstId[parent2Id].generationId + 1;
    }
    uniqueAnimalId++;
    animalObject = AnimalProperties({
        id: uniqueAnimalId,
        name: animalName,
        desc: animalDesc,
        upForSale: false,
        priceForSale: 0,
        upForMating: false,
        eggPhase: true,
        priceForMating: 0,
        isBornByMating: true,
        parentId1: parent1Id,
        parentId2: parent2Id,
        birthdate: now,
        costumeId: 0,
        generationId: generationnum,
        isSpecial: false
    });
    token.sendToken(msg.sender, uniqueAnimalId, animalName);
    animalAgainstId[uniqueAnimalId] = animalObject;
    eggPhaseAnimalIds.push(uniqueAnimalId);
    childrenIdAgainstAnimalId[parent1Id].push(uniqueAnimalId);
    childrenIdAgainstAnimalId[parent2Id].push(uniqueAnimalId);
    for (uint i = 0; i < upForMatingList.length; i++) {
        if (upForMatingList[i] == parent1Id)
            delete upForMatingList[i];
    }
    animalAgainstId[parent1Id].upForMating = false;
    animalAgainstId[parent1Id].priceForMating = 0;
    token.ownerOf(parent1Id).transfer(price);
    owner.transfer(OwnerPercentage);
    if (msg.value > priceWithOwnerPercentage) {
        msg.sender.transfer(msg.value.sub(priceWithOwnerPercentage));
    }
}

