function click() nonReentrant external payable {
    require(msg.sender != owner);
    if (getIsRoundOver(RoundId)) {
        advanceRound();
    }
    Round storage round = Rounds[RoundId];
    require(msg.sender != round.activePlayer);
    require(msg.value >= round.price);
    if (msg.value > round.price) {
        sendPayment(msg.sender, msg.value.sub(round.price));
    }
    if (round.activePlayer != address(0)) {
        uint playerPayout = getPlayerPayout(round.previousPrice);
        sendPayment(round.activePlayer, playerPayout);
        LogPlayerPayout(round.activePlayer, playerPayout);
        sendPayment(owner, getOwnerFee(round.previousPrice));
        round.totalBonus = round.totalBonus.add(getBonusFee(round.previousPrice));
    }
    round.activePlayer = msg.sender;
    round.playerClickCounts[msg.sender] = round.playerClickCounts[msg.sender].add(1);
    round.clickCount = round.clickCount.add(1);
    round.previousPrice = round.price;
    round.price = getNextPrice(round.price);
    round.endTime = now.add(ROUND_DURATION);
    LogClick(
        round.id,
        round.price,
        round.previousPrice,
        round.endTime,
        round.clickCount,
        round.totalBonus,
        msg.sender,
        round.playerClickCounts[msg.sender],
        Rounds[RoundId.sub(1)].totalBonus
    );
}

function claimBonus() nonReentrant external {
    uint roundId = getIsRoundOver(RoundId) ? RoundId.add(1) : RoundId;
    uint previousRoundId = roundId.sub(1);
    bool isBonusClaimed = getIsBonusClaimed(previousRoundId, msg.sender);
    if (isBonusClaimed) {
        return;
    }
    bool isBonusUnlockExempt = getIsBonusUnlockExempt(previousRoundId, msg.sender);
    bool isBonusUnlocked = getPlayerClickCount(roundId, msg.sender) > 0;
    if (!isBonusUnlockExempt && !isBonusUnlocked) {
        return;
    }
    Round storage previousRound = Rounds[previousRoundId];
    uint playerClickCount = previousRound.playerClickCounts[msg.sender];
    uint roundClickCount = previousRound.clickCount;
    uint bonus = previousRound.totalBonus.mul(playerClickCount).div(roundClickCount);
    if (previousRound.activePlayer == msg.sender) {
        bonus = bonus.add(INITIAL_PRICE);
    }
    previousRound.bonusClaimedList[msg.sender] = true;
    previousRound.claimedBonus = previousRound.claimedBonus.add(bonus);
    sendPayment(msg.sender, bonus);
    LogClaimBonus(msg.sender, bonus);
}

function sendPayment(address recipient, uint amount) private returns(bool) {
    assert(recipient != address(0));
    assert(amount > 0);
    bool result = recipient.send(amount);
    if (!result) {
        LogSendPaymentFailure(recipient, amount);
    }
    return result;
}

function getIsRoundOver(uint roundId) private view returns(bool) {
    return now > Rounds[roundId].endTime;
}

function purchase(uint256 _tokenId) public payable {
    address oldOwner = regionIndexToOwner[_tokenId];
    address newOwner = msg.sender;
    uint256 sellingPrice = regionIndexToPrice[_tokenId];
    require(oldOwner != newOwner);
    require(_addressNotNull(newOwner));
    require(msg.value >= sellingPrice);
    uint256 payment = uint256(SafeMath.div(SafeMath.mul(sellingPrice, 94), 100));
    uint256 purchaseExcess = SafeMath.sub(msg.value, sellingPrice);
    if (sellingPrice < firstStepLimit) {
        regionIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 200), 94);
    } else if (sellingPrice < secondStepLimit) {
        regionIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 120), 94);
    } else {
        regionIndexToPrice[_tokenId] = SafeMath.div(SafeMath.mul(sellingPrice, 115), 94);
    }
    _transfer(oldOwner, newOwner, _tokenId);
    if (oldOwner != address(this)) {
        oldOwner.transfer(payment); 
    }
    TokenSold(_tokenId, sellingPrice, regionIndexToPrice[_tokenId], oldOwner, newOwner, regions[_tokenId].name);
    msg.sender.transfer(purchaseExcess);
}

function deposit() public payable {
    require(msg.value >= minLimit && !isFinished);
    owner.transfer(msg.value);
    balanceOf[msg.sender] += msg.value;
    totalRaised += msg.value;
    emit Deposit(msg.sender, msg.value);
}

constructor(ERC20 _token, address _beneficiary, uint256 _releaseTime) public {
    require(_releaseTime > block.timestamp, "Release time must be in future");
    require(_releaseTime < block.timestamp + 3 * 365 days, "Release time must not exceed 3 years");
    token = _token;
    beneficiary = _beneficiary;
    releaseTime = _releaseTime;
}

function release() public {
    require(block.timestamp >= releaseTime, "Release time must pass");
    uint256 amount = token.balanceOf(address(this));
    require(amount > 0, "Contract must hold any tokens");
    require(token.transfer(beneficiary, amount), "Transfer must succeed");
}

function _bid(
    address _nftAddress,
    uint256 _tokenId,
    uint256 _bidAmount
)
internal
returns(uint256) {
    Auction storage _auction = auctions[_nftAddress][_tokenId];
    require(_isOnAuction(_auction));
    uint256 _price = _getCurrentPrice(_auction);
    require(_bidAmount >= _price);
    address _seller = _auction.seller;
    _removeAuction(_nftAddress, _tokenId);
    if (_price > 0) {
        uint256 _auctioneerCut = _computeCut(_price);
        uint256 _sellerProceeds = _price - _auctioneerCut;
        _seller.transfer(_sellerProceeds);
    }
    if (_bidAmount > _price) {
        uint256 _bidExcess = _bidAmount - _price;
        msg.sender.transfer(_bidExcess);
    }
    AuctionSuccessful(_nftAddress, _tokenId, _price, msg.sender);
    return _price;
}

function _addAuction(
    address _nftAddress,
    uint256 _tokenId,
    Auction _auction,
    address _seller
) internal {
    require(_auction.duration >= 1 minutes);
    auctions[_nftAddress][_tokenId] = _auction;
    AuctionCreated(
        _nftAddress,
        _tokenId,
        uint256(_auction.startingPrice),
        uint256(_auction.endingPrice),
        uint256(_auction.duration),
        _seller
    );
}

function createAuction(
    address _nftAddress,
    uint256 _tokenId,
    uint256 _startingPrice,
    uint256 _endingPrice,
    uint256 _duration
)
external
whenNotPaused
canBeStoredWith128Bits(_startingPrice)
canBeStoredWith128Bits(_endingPrice)
canBeStoredWith64Bits(_duration) {
    address _seller = msg.sender;
    require(_owns(_nftAddress, _seller, _tokenId));
    _escrow(_nftAddress, _seller, _tokenId);
    Auction memory _auction = Auction(
        _seller,
        uint128(_startingPrice),
        uint128(_endingPrice),
        uint64(_duration),
        uint64(now)
    );
    _addAuction(_nftAddress, _tokenId, _auction, _seller);
}

function transferFrom(address _from, address _to, uint256 _value) public returns(bool success) {
    require(true &&
        _to != address(0) &&
        _value > 0 &&
        balances[_from] >= _value &&
        allowance[_from][msg.sender] >= _value &&
        frozenAccount[_from] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[_from] &&
        now > unlockUnixTime[_to]);
    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    allowance[_from][msg.sender] = allowance[_from][msg.sender].sub(_value);
    Transfer(_from, _to, _value);
    return true;
}

function transfer(address _to, uint _value, bytes _data, string _custom_fallback) public returns(bool success) {
    require(true &&
        _value > 0 &&
        frozenAccount[msg.sender] == false &&
        frozenAccount[_to] == false &&
        now > unlockUnixTime[msg.sender] &&
        now > unlockUnixTime[_to]
    );
    if (isContract(_to)) {
        if (balanceOf(msg.sender) < _value) {
            revert();
        }
        balances[msg.sender] = SafeMath.sub(balanceOf(msg.sender), _value);
        balances[_to] = SafeMath.add(balanceOf(_to), _value);
        assert(_to.call.value(0)(bytes4(keccak256(_custom_fallback)), msg.sender, _value, _data));
        Transfer(msg.sender, _to, _value, _data);
        Transfer(msg.sender, _to, _value);
        return true;
    } else {
        return transferToAddress(_to, _value, _data);
    }
}

