function setUpgradeAgent(address agent) external onlyOwner {
    require(agent != 0x0 && msg.sender == upgradeMaster);
    upgradeAgent = UpgradeAgent(agent);
    require(upgradeAgent.isUpgradeAgent());
    upgradeAgentStatus = true;
    upgradeAgent.setOriginalSupply();
    UpgradeAgentSet(upgradeAgent);
}

function upgrade(uint256 value) external {
    require(upgradeAgentStatus); 
    require(value > 0 && upgradeAgent.owner() != 0x0);
    require(value <= balances[msg.sender]);
    balances[msg.sender] = safeSub(balances[msg.sender], value);
    totalSupply = safeSub(totalSupply, value);
    totalUpgraded = safeAdd(totalUpgraded, value);
    upgradeAgent.upgradeFrom(msg.sender, value);
    Upgrade(msg.sender, upgradeAgent, value);
}

function finalizeCrowdSale() external {
    require(!isCrowdSaleFinalized);
    require(multisig != 0 && vault != 0 && now > end);
    require(safeAdd(totalSupply, 250000000 ether) <= maxTokenSupply);
    assignTokens(multisig, 250000000 ether);
    require(safeAdd(totalSupply, 150000000 ether) <= maxTokenSupply);
    assignTokens(vault, 150000000 ether);
    isCrowdSaleFinalized = true;
    require(multisig.send(address(this).balance));
}

function() payable stopIfHalted external {
    require(now <= end && now >= preFundingStart);
    require(msg.value >= minInvest);
    require(safeAdd(investment[msg.sender], msg.value) <= maxInvest);
    uint256 createdTokens;
    if (now < start) {
        createdTokens = safeMul(msg.value, preFundingtokens);
        require(safeAdd(totalSupply, createdTokens) <= maxTokenForPreSale);
    } else {
        createdTokens = safeMul(msg.value, fundingTokens);
        require(safeAdd(totalSupply, createdTokens) <= maxTokenSale);
    }
    investment[msg.sender] = safeAdd(investment[msg.sender], msg.value);
    assignTokens(msg.sender, createdTokens);
    Deposit(msg.sender, createdTokens);
}

function cashInvestment(address _investor, uint256 _tokens) onlyOwner stopIfHalted external {
    require(_investor != 0);
    require(_tokens > 0);
    require(now >= preFundingStart && now <= end);
    if (now < start && now >= preFundingStart) {
        require(safeAdd(totalSupply, _tokens) <= maxTokenForPreSale);
    } else {
        require(safeAdd(totalSupply, _tokens) <= maxTokenSale);
    }
    assignTokens(_investor, _tokens);
}

function transfer(address _to, uint _value) public returns(bool ok) {
    require(isTransferEnable);
    require(_to != 0 && _value > 0);
    uint256 senderBalance = balances[msg.sender];
    require(senderBalance >= _value);
    senderBalance = safeSub(senderBalance, _value);
    balances[msg.sender] = senderBalance;
    balances[_to] = safeAdd(balances[_to], _value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function withdraw() external onlyOwner {
    require(now <= end && multisig != address(0));
    require(!isReleasedOnce);
    require(address(this).balance >= 200 ether);
    isReleasedOnce = true;
    assert(multisig.send(200 ether));
}

function burnFrom(address _from, uint _value) public returns(bool ok) {
    require(now >= end);
    require(_from != 0 && _value > 0);
    require(allowedToBurn[_from][msg.sender] >= _value && balances[_from] >= _value);
    balances[_from] = safeSub(balances[_from], _value);
    totalSupply = safeSub(totalSupply, _value);
    allowedToBurn[_from][msg.sender] = safeSub(allowedToBurn[_from][msg.sender], _value);
    BurnFrom(_from, _value);
    return true;
}

function burn(uint _value) public returns(bool ok) {
    require(now >= end);
    require(_value > 0);
    uint256 senderBalance = balances[msg.sender];
    require(senderBalance >= _value);
    senderBalance = safeSub(senderBalance, _value);
    balances[msg.sender] = senderBalance;
    totalSupply = safeSub(totalSupply, _value);
    Burn(msg.sender, _value);
    return true;
}

function transferFrom(address _from, address _to, uint _value) public returns(bool ok) {
    require(isTransferEnable);
    require(_from != 0 && _to != 0 && _value > 0);
    require(allowed[_from][msg.sender] >= _value && balances[_from] >= _value);
    balances[_from] = safeSub(balances[_from], _value);
    balances[_to] = safeAdd(balances[_to], _value);
    allowed[_from][msg.sender] = safeSub(allowed[_from][msg.sender], _value);
    Transfer(_from, _to, _value);
    return true;
}

function buyTokens(address beneficiary, address referrer) payable {
    require(beneficiary != 0x0);
    require(validPurchase());
    uint256 weiAmount = msg.value;
    uint256 tokens = weiAmount.mul(price);
    uint256 bonusTokens = tokens.mul(bonusPercent) / 100;
    uint256 referralBonusTokens = tokens.mul(referralBonusPercent) / 100;
    weiRaised = weiRaised.add(weiAmount);
    tokenReward.transfer(beneficiary, tokens);
    tokensSold = tokensSold.add(tokens);
    bonuses[beneficiary] = bonuses[beneficiary].add(bonusTokens);
    bonusUnlockTime[beneficiary] = now.add(6 * 30 days);
    tokensSold = tokensSold.add(bonusTokens);
    if (referrer != 0x0) {
        bonuses[referrer] = bonuses[referrer].add(referralBonusTokens);
        bonusUnlockTime[referrer] = now.add(6 * 30 days);
        tokensSold = tokensSold.add(referralBonusTokens);
    }
    TokenPurchase(msg.sender, beneficiary, weiAmount, tokens);
    forwardFunds();
}

function getBonus() {
    address sender = msg.sender;
    require(bonuses[sender] > 0);
    require(bonusUnlockTime[sender] != 0 &&
        now > bonusUnlockTime[sender]);
    tokenReward.transfer(sender, bonuses[sender]);
    bonuses[sender] = 0;
}

function BuyItem(uint256 id, string quote) public payable {
    require(id < next_item_index);
    var UsedItem = Items[id];
    if (UsedItem.owner != address(0) && block.timestamp > (add(UsedItem.timestamp, UsedItem.timer))) {
        Payout(id);
        if (msg.value > 0) {
            msg.sender.transfer(msg.value);
        }
        return;
    }
    require(msg.value >= UsedItem.price);
    require(msg.sender != owner);
    require(msg.sender != UsedItem.owner);
    uint256 devFee_used = mul(UsedItem.price, devFee) / 10000;
    uint256 creatorFee_used = mul(UsedItem.price, UsedItem.creatorFee) / 10000;
    uint256 prevFee_used;
    if (UsedItem.owner == address(0)) {
        prevFee_used = 0;
        devFee_used = 0;
        creatorFee_used = 0;
    } else {
        prevFee_used = (mul(UsedItem.price, UsedItem.previousFee)) / 10000;
        UsedItem.owner.transfer(prevFee_used);
    }
    if (creatorFee_used != 0) {
        UsedItem.creator.transfer(creatorFee_used);
    }
    if (devFee_used != 0) {
        owner.transfer(devFee_used);
    }
    if (msg.value > UsedItem.price) {
        msg.sender.transfer(sub(msg.value, UsedItem.price));
    }
    uint256 potFee_used = sub(sub(sub(UsedItem.price, devFee_used), creatorFee_used), prevFee_used);
    UsedItem.amount = add(UsedItem.amount, potFee_used);
    UsedItem.timestamp = block.timestamp;
    UsedItem.owner = msg.sender;
    UsedItem.quote = quote;
    UsedItem.price = (UsedItem.price * (add(10000, UsedItem.priceIncrease))) / 10000;
    emit ItemBought(id);
}

function AddItem(uint32 timer, uint16 priceIncrease, uint256 minPrice, uint16 creatorFee, uint16 potFee, string name) public payable {
    require(timer >= 300);
    require(timer < 31622400);
    require(priceIncrease <= 20000);
    require(minPrice >= (1 szabo) && minPrice <= (1 ether));
    require(creatorFee <= 2500);
    require(potFee <= 10000);
    require(add(add(creatorFee, potFee), devFee) <= 10000);
    if (msg.sender == owner) {
        require(creatorFee == 0);
        if (msg.value > 0) {
            owner.transfer(msg.value);
        }
    } else {
        uint256 left = 0;
        if (msg.value > ItemCreatePrice) {
            left = sub(msg.value, ItemCreatePrice);
            msg.sender.transfer(left);
        } else {
            if (msg.value < ItemCreatePrice) {
                revert();
            }
        }
        owner.transfer(sub(msg.value, left));
    }
    require(devFee + potFee + creatorFee <= 10000);
    uint16 previousFee = 10000 - devFee - potFee - creatorFee;
    var NewItem = Item(timer, 0, priceIncrease, minPrice, 0, minPrice, creatorFee, previousFee, potFee, msg.sender, address(0), "", name);
    Items[next_item_index] = NewItem;
    emit ItemCreated(next_item_index);
    next_item_index = add(next_item_index, 1);
}

function Payout(uint256 id) internal {
    var UsedItem = Items[id];
    uint256 Paid = UsedItem.amount;
    UsedItem.amount = 0;
    UsedItem.owner.transfer(Paid);
    UsedItem.owner = address(0);
    UsedItem.price = UsedItem.minPrice;
    UsedItem.timestamp = 0;
    emit ItemWon(id);
}

function TakePrize(uint256 id) public {
    require(id < next_item_index);
    var UsedItem = Items[id];
    require(UsedItem.owner != address(0));
    uint256 TimingTarget = add(UsedItem.timer, UsedItem.timestamp);
    if (block.timestamp > TimingTarget) {
        Payout(id);
        return;
    } else {
        revert();
    }
}

function validPurchase() internal view returns(bool) {
    bool withinLimit = weiContributions[msg.sender] <= weiLimits[msg.sender];
    bool atleastMinimumContribution = weiContributions[msg.sender] >= minimumContribution;
    return atleastMinimumContribution && withinLimit && super.validPurchase();
}

function buyTokens(address _beneficiary) public payable {
    require(_beneficiary != address(0x0));
    if (state == STATE.PREPREICO) {
        require(now >= prePreIcoStartAt && now <= prePreIcoEndAt);
        require(msg.value <= 10 ether);
    } else if (state == STATE.PREICO) {
        require(now >= preIcoStartAt && now <= preIcoEndAt);
        require(msg.value <= 15 ether);
    } else if (state == STATE.POSTICO) {
        require(now >= icoStartAt && now <= icoEndAt);
        require(msg.value <= 20 ether);
    }
    uint256 weiAmount = msg.value;
    uint256 tokens = _getTokenAmount(weiAmount);
    if (state == STATE.PREPREICO) { 
        tokens = tokens.add(tokens.mul(30).div(100));
    } else if (state == STATE.PREICO) {
        tokens = tokens.add(tokens.mul(25).div(100));
    } else if (state == STATE.POSTICO) {
        tokens = tokens.add(tokens.mul(20).div(100));
    }
    totalSupply_ = totalSupply_.add(tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    emit Transfer(address(0), msg.sender, tokens);
    weiRaised = weiRaised.add(weiAmount);
    emit TokenPurchase(msg.sender, _beneficiary, weiAmount, tokens);
    _forwardFunds();
}

function donate(address payable charityAddress) public validateTransferAmount() payable {
    uint256 taxAmount = msg.value * taxPercent / 100;
    uint256 donationAmount = msg.value - taxAmount;
    charityAddress.transfer(donationAmount);
    taxCollectAddress.transfer(taxAmount);
    emit Donation(msg.sender, donationAmount);
    totalDonationsAmount += donationAmount;
    if (donationAmount > highestDonation) {
        highestDonation = donationAmount;
        highestDonor = msg.sender;
    }
}

