function getRandomNumber(uint maxNumber) private returns(uint) {
    require(maxNumber > 0);
    randNonce += 1;
    return uint(keccak256(now, randNonce, block.blockhash(block.number - 1), block.coinbase)) % maxNumber;
}

function attackMonster(uint monsterId) public {
    require(!listedEtherMonster[monsterId].defeated); 
    require(address(this).balance >= listedEtherMonster[monsterId].balance); 
    require(mapUserLastAttackMonsterTimestamp[msg.sender].add(userAttackMonsterCDSeconds) < now);
    require(listedEtherMonster[monsterId].produceTime.add(etherMonsterHuntSeconds) > now);
    require(mapUserHasHunterLicence[msg.sender]); 
    require(mapUserCurrentMartialId[msg.sender] == listedEtherMonster[monsterId].martialId);
    uint monsterCurrentBlood = listedEtherMonster[monsterId].currentBlood;
    uint monsterTotalBlood = listedEtherMonster[monsterId].blood;
    mapUserLastAttackMonsterTimestamp[msg.sender] = now;
    if (mapUserPower[msg.sender] >= monsterCurrentBlood) {
        listedEtherMonster[monsterId].defeated = true;
        listedEtherMonster[monsterId].winner = msg.sender;
        _sendMonsterPrize(monsterId, msg.sender);
    } else {
        uint randomNumber = getRandomNumber(monsterTotalBlood);
        if (randomNumber < mapUserPower[msg.sender]) {
            listedEtherMonster[monsterId].defeated = true;
            listedEtherMonster[monsterId].winner = msg.sender;
            _sendMonsterPrize(monsterId, msg.sender);
        } else {
            listedEtherMonster[monsterId].currentBlood = monsterCurrentBlood.sub(mapUserPower[msg.sender]);
        }
    }
}

function _tryCreateEtherMonster(uint price_a, uint price_b) private {
    uint priceTimes = price_b.div(0.5 ether);
    if (price_a < priceTimes * 0.5 ether && price_b >= priceTimes * 0.5 ether) {
        uint martialId = getRandomNumber(listedMartials.length);
        EtherMonster memory monster = EtherMonster(listedEtherMonster.length, martialId, 0.2 ether, maxUserPower.mul(smallMonsterPowerFactor), now, maxUserPower.mul(smallMonsterPowerFactor), false, address(0));
        listedEtherMonster.push(monster);
    }
    priceTimes = price_b.div(5 ether);
    if (price_a < priceTimes * 5 ether && price_b >= priceTimes * 5 ether) {
        uint bigMartialId = (getRandomNumber(listedEtherMonster.length).add(10007)) % listedMartials.length;
        EtherMonster memory bigMonster = EtherMonster(listedEtherMonster.length, bigMartialId, 1 ether, maxUserPower.mul(bigMonsterPowerFactor), now, maxUserPower.mul(bigMonsterPowerFactor), false, address(0));
        listedEtherMonster.push(bigMonster);
    }
}

function getMartialListInfo() public view returns(uint[]) {
    uint[] memory result = new uint[](listedMartials.length.mul(5) + 1);
    uint index = 1;
    result[0] = listedMartials.length;
    for (uint i = 0; i < listedMartials.length; i++) {
        Martial memory martial = listedMartials[i];
        result[index] = martial.rareNumber;
        result[index + 1] = martial.epicNumber;
        result[index + 2] = martial.mythNumber;
        result[index + 3] = mapUserPower[martial.owner];
        result[index + 4] = mapMartialUserCount[i];
        index += 5;
    }
    return result;
}

function tokensOf(address _owner) public view returns(uint[]) {
    uint[] memory result = new uint[](balanceOf(_owner));
    uint256 itemCounter = 0;
    for (uint256 i = 0; i < listedCard.length; i++) {
        if (ownerOf(i) == _owner) {
            result[itemCounter] = listedCard[i].cardId;
            itemCounter += 1;
        }
    }
    return result;
}

function _sendMonsterPrize(uint monsterId, address winner) private {
    uint totalPrize = listedEtherMonster[monsterId].balance;
    uint martialOwnerCut = 0;
    if (listedMartials[listedEtherMonster[monsterId].martialId].owner != address(0)) {
        martialOwnerCut = totalPrize.mul(10).div(100);
    }
    winner.transfer(totalPrize.sub(martialOwnerCut));
    listedMartials[listedEtherMonster[monsterId].martialId].owner.transfer(martialOwnerCut);
}

function _getTravelPrice(address userAddress, uint martialId) private view returns(uint) {
    Martial storage currentMartial = listedMartials[mapUserCurrentMartialId[userAddress]];
    Martial storage nextMartial = listedMartials[martialId];
    require(currentMartial.martialId != nextMartial.martialId); 
    uint stepNumber = absSub(currentMartial.x, nextMartial.x).add(absSub(currentMartial.y, nextMartial.y));
    uint travelPrice = stepNumber.mul(stepPrice).add(nextMartial.enterPrice);
    if (mapUserHasSmartSpeed[userAddress]) {
        travelPrice = travelPrice.div(2);
    }
    return travelPrice;
}

function getMartialCardTypeIdList(uint martialId) public view returns(uint[]) {
    require(martialId < listedMartials.length);
    return listedMartials[martialId].cardTypeList;
}

function getMartialInfo(uint martialId) public view returns(uint, uint, address, uint, uint, uint, uint, uint, uint, uint[]) {
    require(martialId < listedMartials.length);
    Martial memory martial = listedMartials[martialId];
    return (martial.x, martial.y, martial.owner, martial.lastProduceTime, martial.martialId, martial.rareNumber, martial.epicNumber, martial.mythNumber, martial.enterPrice, martial.cardTypeList);
}

function mergeCard(uint a, uint b) public {
    require(a < listedCard.length);
    require(b < listedCard.length);
    require(listedCard[a].typeId == listedCard[b].typeId);
    require(listedCard[a].level == listedCard[b].level);
    require(listedCard[a].level <= 2); 
    require(!listedCard[a].onSell);
    require(!listedCard[b].onSell);
    require(mapOwnerOfCard[a] == msg.sender);
    require(mapOwnerOfCard[b] == msg.sender);
    Card memory card = Card(listedCard.length, listedCard[a].typeId, listedCard[a].level.add(1), false, 0, msg.sender);
    mapOwnerOfCard[a] = address(0);
    mapOwnerOfCard[b] = address(0);
    listedCard[a].owner = address(0);
    listedCard[b].owner = address(0);
    mapOwnerOfCard[listedCard.length] = msg.sender;
    listedCard.push(card);
    mapUserPower[msg.sender] = mapUserPower[msg.sender].add(getCardPower(listedCard[a].typeId, listedCard[a].level.add(1)).sub(getCardPower(listedCard[a].typeId, listedCard[a].level).mul(2)));
    if (mapUserPower[msg.sender] > maxUserPower) {
        maxUserPower = mapUserPower[msg.sender];
        maxPowerUserAddress = msg.sender;
    }
}

function getMartialOwner() public view returns(address[]) {
    address[] memory result = new address[](listedMartials.length);
    for (uint i = 0; i < listedMartials.length; i++) {
        result[i] = listedMartials[i].owner;
    }
    return result;
}

function getCardPower(uint cardTypeId, uint cardLevel) public view returns(uint) {
    require(cardLevel <= 3);
    require(cardTypeId < listedCardType.length);
    CardType memory cardType = listedCardType[cardTypeId];
    if (cardLevel == 0) {
        return cardType.initPower;
    } else if (cardLevel == 1) {
        return cardType.initPower.mul(cardType.growthFactor);
    } else if (cardLevel == 2) {
        return cardType.initPower.mul(cardType.growthFactor).mul(cardType.growthFactor);
    } else if (cardLevel == 3) {
        return cardType.initPower.mul(cardType.growthFactor).mul(cardType.growthFactor).mul(cardType.growthFactor);
    }
}

function balanceOf(address _owner) public view returns(uint256 _balance) {
    uint counter = 0;
    for (uint i = 0; i < listedCard.length; i++) {
        if (ownerOf(listedCard[i].cardId) == _owner) {
            counter++;
        }
    }
    return counter;
}

function beatMartialOwner() public returns(bool) {
    uint myMartialId = mapUserCurrentMartialId[msg.sender];
    address martialOwner = listedMartials[myMartialId].owner;
    require(msg.sender != martialOwner);
    require(!mapUesrAlreadyMartialOwner[msg.sender]);
    if (martialOwner == address(0)) {
        listedMartials[myMartialId].owner = msg.sender;
        mapUesrAlreadyMartialOwner[msg.sender] = true;
        mapUesrAlreadyMartialOwner[martialOwner] = false;
        return true;
    } else {
        if (mapUserPower[msg.sender] > mapUserPower[martialOwner]) {
            listedMartials[myMartialId].owner = msg.sender;
            mapUesrAlreadyMartialOwner[msg.sender] = true;
            mapUesrAlreadyMartialOwner[martialOwner] = false;
            return true;
        } else {
            return false;
        }
    }
}

function sendEthTweet(uint256 _amount, bool _isERC20, string _symbol, bool _payFromMsg, string _followerTwitterHandle, string _influencerTwitterHandle, string _tweet) private {
    require(
        (!_isERC20 && _payFromMsg && msg.value == _amount) ||
        (!_isERC20 && !_payFromMsg && _amount <= address(this).balance) ||
        _isERC20
    );
    ERC20Basic erc20;
    if (_isERC20) {
        require(tokens[_symbol] != 0x0);
        erc20 = ERC20Basic(tokens[_symbol]);
        require(erc20.balanceOf(address(this)) >= _amount);
    }
    Influencer memory influencer = influencers[_influencerTwitterHandle];
    require(influencer.influencerAddress != 0x0);
    uint256[] memory payouts = new uint256[](4); 
    payouts[3] = 100;
    if (influencer.charityPercentage == 0) {
        payouts[0] = _amount.mul(payouts[3].sub(feePercentage)).div(payouts[3]);
        payouts[2] = _amount.sub(payouts[0]);
    } else {
        payouts[1] = _amount.mul(influencer.charityPercentage).div(payouts[3]);
        payouts[0] = _amount.sub(payouts[1]).mul(payouts[3].sub(feePercentage)).div(payouts[3]);
        payouts[2] = _amount.sub(payouts[1]).sub(payouts[0]);
    }
    require(payouts[0].add(payouts[1]).add(payouts[2]) == _amount);
    ethTweets.push(EthTweet(_followerTwitterHandle, _influencerTwitterHandle, _tweet, _amount, _symbol));
    emit EthTweetSent(
        _followerTwitterHandle,
        _influencerTwitterHandle,
        _amount,
        _symbol,
        ethTweets.length - 1
    );
    if (payouts[0] > 0) {
        if (!_isERC20) {
            influencer.influencerAddress.transfer(payouts[0]);
        } else {
            erc20.transfer(influencer.influencerAddress, payouts[0]);
        }
        emit Payment(influencer.influencerAddress, payouts[0], _symbol);
    }
    if (payouts[1] > 0) {
        if (!_isERC20) {
            influencer.charityAddress.transfer(payouts[1]);
        } else {
            erc20.transfer(influencer.charityAddress, payouts[1]);
        }
        emit Payment(influencer.charityAddress, payouts[1], _symbol);
    }
    if (payouts[2] > 0) {
        if (!_isERC20) {
            if (webappAddress.balance < webappMinBalance) {
                webappAddress.transfer(payouts[2].div(5));
                payouts[2] = payouts[2].sub(payouts[2].div(5));
                emit Payment(webappAddress, payouts[2].div(5), _symbol);
            }
            feePayoutAddress.transfer(payouts[2]);
        } else {
            erc20.transfer(feePayoutAddress, payouts[2]);
        }
        emit Payment(feePayoutAddress, payouts[2], _symbol);
    }
}

function exchangeTokens()
public
returns(bool) {
    uint tokens = uint(
        ERC20Interface(preSaleContract)
        .allowance(msg.sender, this));
    require(tokens > 0 &&
        ERC20Interface(preSaleContract)
        .balanceOf(msg.sender) == tokens);
    ERC20Interface(preSaleContract)
        .transferFrom(msg.sender, address(0), tokens);
    balances[owner] = balances[owner].sub(tokens);
    balances[msg.sender] = balances[msg.sender].add(tokens);
    Transfer(owner, msg.sender, tokens);
    return true;
}

function buyGana(address buyer) public onlyWhitelisted payable {
    require(!hasEnded());
    require(afterStart());
    require(buyer != address(0));
    require(buyer == msg.sender);
    require(msg.value >= minCap);
    uint256 weiAmount = msg.value;
    uint256 preCalWeiRaised = weiRaised.add(weiAmount);
    uint256 ganaAmount;
    if (preCalWeiRaised <= hardCap) {
        ganaAmount = weiAmount.mul(rate);
        gana.saleTransfer(buyer, ganaAmount);
        weiRaised = preCalWeiRaised;
        TokenPurchase(msg.sender, buyer, weiAmount, ganaAmount);
    } else {
        uint256 refundWeiAmount = preCalWeiRaised.sub(hardCap);
        uint256 fundWeiAmount = weiAmount.sub(refundWeiAmount);
        ganaAmount = fundWeiAmount.mul(rate);
        gana.saleTransfer(buyer, ganaAmount);
        weiRaised = weiRaised.add(fundWeiAmount);
        TokenPurchase(msg.sender, buyer, fundWeiAmount, ganaAmount);
        buyer.transfer(refundWeiAmount);
        Refund(buyer, refundWeiAmount);
    }
}

function unstakeMany(address token, address owner, uint256[] calldata ids) external {
    _onlyPortal();
    for (uint256 i = 0; i < ids.length; i++) {
        if (token == orcs) delete orcOwner[ids[i]];
        if (token == allies) delete allyOwner[ids[i]];
        ERC721Like(token).transfer(owner, ids[i]);
    }
}

function _stake(address token, uint256 id, address owner) internal {
    require((token == orcs ? orcOwner[id] : allyOwner[id]) == address(0), "already staked");
    require(msg.sender == token, "not orcs contract");
    require(ERC721Like(token).ownerOf(id) == address(this), "orc not transferred");
    if (token == orcs) orcOwner[id] = owner;
    if (token == allies) allyOwner[id] = owner;
}

function transferPreSigned(
    address _to,
    uint256 _value,
    uint256 _fee,
    uint256 _nonce,
    uint8 _version,
    bytes _sig
)
public
onlyNotFrozenAddress(msg.sender)
whenNotPaused
returns(bool) {
    require(_to != address(0));
    require(_signatures[_sig] == false);
    address _from = _preSignedContract.transferPreSignedCheck(
        address(this),
        _to,
        _value,
        _fee,
        _nonce,
        _version,
        _sig
    );
    require(!frozenAddress[_from]);
    uint256 _burden = _value.add(_fee);
    require(_burden <= balances[_from]);
    balances[_from] = balances[_from].sub(_burden);
    balances[_to] = balances[_to].add(_value);
    balances[msg.sender] = balances[msg.sender].add(_fee);
    emit Transfer(_from, _to, _value);
    emit Transfer(_from, msg.sender, _fee);
    _signatures[_sig] = true;
    emit TransferPreSigned(_from, _to, msg.sender, _value, _fee);
    return true;
}

function increaseApprovalPreSigned(
    address _to,
    uint256 _value,
    uint256 _fee,
    uint256 _nonce,
    uint8 _version,
    bytes _sig
)
public
onlyNotFrozenAddress(msg.sender)
whenNotPaused
returns(bool) {
    require(_signatures[_sig] == false);
    address _from = _preSignedContract.increaseApprovalPreSignedCheck(
        address(this),
        _to,
        _value,
        _fee,
        _nonce,
        _version,
        _sig
    );
    require(!frozenAddress[_from]);
    require(_fee <= balances[_from]);
    allowed[_from][_to] = allowed[_from][_to].add(_value);
    emit Approval(_from, _to, allowed[_from][_to]);
    if (_fee > 0) {
        balances[_from] = balances[_from].sub(_fee);
        balances[msg.sender] = balances[msg.sender].add(_fee);
        emit Transfer(_from, msg.sender, _fee);
    }
    _signatures[_sig] = true;
    emit ApprovalPreSigned(_from, _to, msg.sender, allowed[_from][_to], _fee);
    return true;
}

function decreaseApprovalPreSigned(
    address _to,
    uint256 _value,
    uint256 _fee,
    uint256 _nonce,
    uint8 _version,
    bytes _sig
)
public
onlyNotFrozenAddress(msg.sender)
whenNotPaused
returns(bool) {
    require(_signatures[_sig] == false);
    address _from = _preSignedContract.decreaseApprovalPreSignedCheck(
        address(this),
        _to,
        _value,
        _fee,
        _nonce,
        _version,
        _sig
    );
    require(!frozenAddress[_from]);
    require(_fee <= balances[_from]);
    uint256 oldValue = allowed[_from][_to];
    if (_value > oldValue) {
        oldValue = 0;
    } else {
        oldValue = oldValue.sub(_value);
    }
    allowed[_from][_to] = oldValue;
    emit Approval(_from, _to, oldValue);
    if (_fee > 0) {
        balances[_from] = balances[_from].sub(_fee);
        balances[msg.sender] = balances[msg.sender].add(_fee);
        emit Transfer(_from, msg.sender, _fee);
    }
    _signatures[_sig] = true;
    emit ApprovalPreSigned(_from, _to, msg.sender, oldValue, _fee);
    return true;
}

function approvePreSigned(
    address _to,
    uint256 _value,
    uint256 _fee,
    uint256 _nonce,
    uint8 _version,
    bytes _sig
)
public
onlyNotFrozenAddress(msg.sender)
whenNotPaused
returns(bool) {
    require(_signatures[_sig] == false);
    address _from = _preSignedContract.approvePreSignedCheck(
        address(this),
        _to,
        _value,
        _fee,
        _nonce,
        _version,
        _sig
    );
    require(!frozenAddress[_from]);
    require(_fee <= balances[_from]);
    allowed[_from][_to] = _value;
    emit Approval(_from, _to, _value);
    if (_fee > 0) {
        balances[_from] = balances[_from].sub(_fee);
        balances[msg.sender] = balances[msg.sender].add(_fee);
        emit Transfer(_from, msg.sender, _fee);
    }
    _signatures[_sig] = true;
    emit ApprovalPreSigned(_from, _to, msg.sender, _value, _fee);
    return true;
}

function multiValueTokenAirdrop(address _addressOfToken, address[] memory _recipients, uint256[] memory _values, string memory _afCode) public payable returns(bool) {
    ERCInterface token = ERCInterface(_addressOfToken);
    require(_recipients.length == _values.length, "Total number of recipients and values are not equal");
    uint256 price = _recipients.length.mul(dropUnitPrice);
    require(
        msg.value >= price || tokenHasFreeTrial(_addressOfToken) || isPremiumMember[msg.sender],
        "Not enough ETH sent with transaction!"
    );
    giveChange(price);
    _afCode = processAffiliateCode(_afCode);
    for (uint i = 0; i < _recipients.length; i++) {
        if (_recipients[i] != address(0) && _values[i] > 0) {
            token.transferFrom(msg.sender, _recipients[i], _values[i]);
        }
    }
    if (tokenHasFreeTrial(_addressOfToken)) {
        tokenTrialDrops[_addressOfToken] = tokenTrialDrops[_addressOfToken].add(_recipients.length);
    } else {
        if (!isPremiumMember[msg.sender]) {
            distributeCommission(_recipients.length, _afCode);
        }
    }
    emit TokenAirdrop(msg.sender, _addressOfToken, _recipients.length);
    return true;
}

