function withdraw(InvestInfo storage uInfo)
internal {
    (uint256 avaiCRFI, uint256 nextTime, uint256 totalNums) = calcNowAvaiCRFI(uInfo);
    if (avaiCRFI == 0) {
        return;
    }
    uInfo.restCRFI = uInfo.restCRFI.sub(avaiCRFI);
    uInfo.nextTime = nextTime;
    uInfo.totalNums = totalNums;
    CRFI.transfer(uInfo.Addr, avaiCRFI);
}

function calcNowAvaiCRFI(InvestInfo storage uInfo)
internal
view
returns(uint256 avaiCRFI, uint256 nextTime, uint256 totalNums) {
    if (block.timestamp < uInfo.nextTime || uInfo.restCRFI == 0 || uInfo.totalNums == 0) {
        return (0, uInfo.nextTime, uInfo.totalNums);
    }
    uint256 times = block.timestamp.sub(uInfo.nextTime) / uInfo.duration;
    times++;
    if (times > uInfo.totalNums) {
        times = uInfo.totalNums;
    }
    avaiCRFI = times.mul(uInfo.perTimeCRFI);
    nextTime = uInfo.nextTime.add(uInfo.duration.mul(times));
    totalNums = uInfo.totalNums.sub(times);
    if (totalNums == 0) {
        avaiCRFI = uInfo.restCRFI;
    }
    return (avaiCRFI, nextTime, totalNums);
}

function Charge(address to,
    uint256 totalCRFI,
    uint256 nextTime,
    uint256 duration,
    uint256 totalNums)
public
nonReentrant() {
    uint256 uID = getUID(to);
    InvestInfo storage uInfo = Invests[uID];
    withdraw(uInfo);
    require(uInfo.restCRFI == 0, "have rest crfi");
    require(to != address(0x0), "user must not zero addr");
    require(totalCRFI > 0, "totalCRFI must > 0");
    require(duration > 0, "duration must > 0");
    require(totalNums > 0, "totalNums must > 0");
    require(totalCRFI > totalNums, "totalCRFI must > totalNums");
    CRFI.transferFrom(msg.sender, address(this), totalCRFI);
    uInfo.restCRFI = totalCRFI;
    uInfo.perTimeCRFI = totalCRFI / totalNums;
    uInfo.nextTime = nextTime;
    uInfo.duration = duration;
    uInfo.totalNums = totalNums;
}

function decreaseSoldAmount(uint256 id, uint256 amountToBuy, uint256 bid) external {
    require(contractEnabled == 1, "DebtAuctionHouse/contract-not-enabled");
    require(bids[id].highBidder != address(0), "DebtAuctionHouse/high-bidder-not-set");
    require(bids[id].bidExpiry > now || bids[id].bidExpiry == 0, "DebtAuctionHouse/bid-already-expired");
    require(bids[id].auctionDeadline > now, "DebtAuctionHouse/auction-already-expired");
    require(bid == bids[id].bidAmount, "DebtAuctionHouse/not-matching-bid");
    require(amountToBuy < bids[id].amountToSell, "DebtAuctionHouse/amount-bought-not-lower");
    require(multiply(bidDecrease, amountToBuy) <= multiply(bids[id].amountToSell, ONE), "DebtAuctionHouse/insufficient-decrease");
    safeEngine.transferInternalCoins(msg.sender, bids[id].highBidder, bid);
    if (bids[id].bidExpiry == 0) {
        uint256 totalOnAuctionDebt = AccountingEngineLike_1(bids[id].highBidder).totalOnAuctionDebt();
        AccountingEngineLike_1(bids[id].highBidder).cancelAuctionedDebtWithSurplus(minimum(bid, totalOnAuctionDebt));
    }
    bids[id].highBidder = msg.sender;
    bids[id].amountToSell = amountToBuy;
    bids[id].bidExpiry = addUint48(uint48(now), bidDuration);
    emit DecreaseSoldAmount(id, msg.sender, amountToBuy, bid, bids[id].bidExpiry);
}

