function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(!_isBlacklisted[from] && !_isBlacklisted[to], "To or From address is blacklisted.");
    if (!isTradingEnabled) {
        require(_isExcluded[to] || _isExcluded[from], "Trading is not yet enabled. Be patient!");
    } else if (block.timestamp - startTime < 900) {
        require(amount <= 10 ** 9 * (10 ** 18), "Over the max tx amount.");
    }
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee) {
        uint256 fees;
        if (from == uniswapV2Pair) {
            fees = amount.mul(buyFee).div(1000);
        } else if (to == uniswapV2Pair) {
            fees = amount.mul(sellFee).div(1000);
        }
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function vest() public onlyOwner {
    for (uint16 i = 0; i < index; i++) {
        Grant storage grant = grants[indexedGrants[i]];
        if (grant.value == 0) continue;
        uint256 vested = calculateVestedTokens(grant, now);
        if (vested == 0) {
            continue;
        }
        uint256 transferable = vested.sub(grant.transferred);
        if (transferable == 0) {
            continue;
        }
        grant.transferred = grant.transferred.add(transferable);
        totalVesting = totalVesting.sub(transferable);
        token.mintTokens(indexedGrants[i], transferable);
        emit UnlockGrant(msg.sender, transferable);
    }
}

function unlockVestedTokens() public {
    Grant storage grant = grants[msg.sender];
    require(grant.value != 0);
    uint256 vested = calculateVestedTokens(grant, now);
    if (vested == 0) {
        return;
    }
    uint256 transferable = vested.sub(grant.transferred);
    if (transferable == 0) {
        return;
    }
    grant.transferred = grant.transferred.add(transferable);
    totalVesting = totalVesting.sub(transferable);
    token.mintTokens(msg.sender, transferable);
    emit UnlockGrant(msg.sender, transferable);
}

function revoke(address _grant) public onlyOwner {
    Grant storage grant = grants[_grant];
    require(grant.revocable);
    uint256 refund = grant.value.sub(grant.transferred);
    delete grants[_grant];
    totalVesting = totalVesting.sub(refund);
    token.mintTokens(msg.sender, refund);
    emit RevokeGrant(_grant, refund);
}

function calculateVestedTokens(Grant _grant, uint256 _time) private pure returns(uint256) {
    if (_time < _grant.cliff) {
        return 0;
    }
    if (_time >= _grant.duration) {
        return _grant.value;
    }
    return _grant.value.mul(_time.sub(_grant.start)).div(_grant.duration.sub(_grant.start));
}

