function proposeToRemoveScheme(Avatar _avatar, address _scheme)
public
returns(bytes32) {
    bytes32 paramsHash = getParametersFromController(_avatar);
    Parameters memory params = parameters[paramsHash];
    IntVoteInterface intVote = params.intVote;
    bytes32 proposalId = intVote.propose(2, params.voteRemoveParams, _avatar, ExecutableInterface(this), msg.sender);
    organizationsProposals[_avatar][proposalId].proposalType = 2;
    organizationsProposals[_avatar][proposalId].scheme = _scheme;
    emit RemoveSchemeProposal(_avatar, proposalId, intVote, _scheme);
    intVote.ownerVote(proposalId, 1, msg.sender); 
    return proposalId;
}

function proposeScheme(
    Avatar _avatar,
    address _scheme,
    bytes32 _parametersHash,
    bytes4 _permissions
)
public
returns(bytes32) {
    require(_scheme != address(0));
    Parameters memory controllerParams = parameters[getParametersFromController(_avatar)];
    bytes32 proposalId = controllerParams.intVote.propose(
        2,
        controllerParams.voteRegisterParams,
        _avatar,
        ExecutableInterface(this),
        msg.sender
    );
    SchemeProposal memory proposal = SchemeProposal({
        scheme: _scheme,
        parametersHash: _parametersHash,
        proposalType: 1,
        permissions: _permissions
    });
    emit NewSchemeProposal(
        _avatar,
        proposalId,
        controllerParams.intVote,
        _scheme, _parametersHash,
        _permissions
    );
    organizationsProposals[_avatar][proposalId] = proposal;
    controllerParams.intVote.ownerVote(proposalId, 1, msg.sender); 
    return proposalId;
}

function execute(bytes32 _proposalId, address _avatar, int _param) external returns(bool) {
    require(parameters[getParametersFromController(Avatar(_avatar))].intVote == msg.sender);
    SchemeProposal memory proposal = organizationsProposals[_avatar][_proposalId];
    require(proposal.scheme != address(0));
    delete organizationsProposals[_avatar][_proposalId];
    emit ProposalDeleted(_avatar, _proposalId);
    if (_param == 1) {
        ControllerInterface controller = ControllerInterface(Avatar(_avatar).owner());
        if (proposal.proposalType == 1) {
            require(controller.registerScheme(proposal.scheme, proposal.parametersHash, proposal.permissions, _avatar));
        }
        if (proposal.proposalType == 2) {
            require(controller.unregisterScheme(proposal.scheme, _avatar));
        }
    }
    emit ProposalExecuted(_avatar, _proposalId, _param);
    return true;
}

function waitReleaseTime() public constant returns(uint256 timestamp) {
    if (block.timestamp < releaseTime) {
        return releaseTime - block.timestamp;
    } else {
        return 0;
    }
}

function release() public {
    require(block.timestamp > releaseTime, "No release time");
    uint256 totalTokenBalance = token.balanceOf(this);
    require(totalTokenBalance > 0, "The balance is zero");
    token.transfer(beneficiary, totalTokenBalance);
}

function revoke(address userAddress)
public
onlyValidAuthority(msg.sender)
onlyAuthoritativeAuthority(msg.sender, userAddress) {
    KYC memory kyc = KYC({
        verified: false,
        verifiedBy: msg.sender,
        verifiedAt: block.number,
        verifiedAttributes: 0
    });
    records[userAddress] = kyc;
}

function approve(address userAddress, uint verifiedAttributes)
public
onlyValidAuthority(msg.sender)
onlyAuthoritativeAuthority(msg.sender, userAddress) {
    KYC memory kyc = KYC({
        verified: true,
        verifiedBy: msg.sender,
        verifiedAt: block.number,
        verifiedAttributes: verifiedAttributes
    });
    records[userAddress] = kyc;
}

function claim(address verifier, uint verifiedAttributes, uint expires, uint8 v, bytes32 r, bytes32 s)
public
onlyValidAuthority(verifier)
onlyAuthoritativeAuthority(verifier, msg.sender) {
    if (verificationFee > 0) {
        if (!chargeVerificationFee(msg.sender, verifier)) {
            revert();
        }
    }
    bytes32 hash = sha256(this, msg.sender, verifiedAttributes, expires);
    bytes memory prefix = "\x19Ethereum Signed Message:\n32";
    bytes32 prefixedHash = keccak256(prefix, hash);
    if (!((ecrecover(prefixedHash, v, r, s) == verifier) && block.number <= expires)) {
        revert();
    }
    KYC memory kyc = KYC({
        verified: true,
        verifiedBy: verifier,
        verifiedAt: block.number,
        verifiedAttributes: verifiedAttributes
    });
    records[msg.sender] = kyc;
}

function isFeeClaimAllowed(Info memory self) internal view {
    require(self.allowFeeClaim, "ULL::FEE_CLAIM_NOT_ALLOWED");
    require((self.start + self.cliff) < block.timestamp, "ULL::CLIFF_NOT_ENDED");
}

function isPositionValid(Info memory self) internal view {
    require(self.owner != address(0), "ULL::OWNER_ZERO_ADDRESS");
    require(self.duration >= self.cliff, "ULL::CLIFF_GT_DURATION");
    require(self.duration > 0, "ULL::INVALID_DURATION");
    require((self.start + self.duration) > block.timestamp, "ULL::INVALID_ENDING_TIME");
}

function isTokenUnlocked(Info memory self) internal view {
    require((self.start + self.duration) < block.timestamp, "ULL::NOT_UNLOCKED");
}

function unlockToken(uint256 tokenId) external {
    Position.Info memory llPosition = lockedLiquidityPositions[tokenId];
    llPosition.isTokenIdValid(tokenId);
    llPosition.isTokenUnlocked();
    _uniswapNFPositionManager.transferFrom(address(this), llPosition.owner, tokenId);
    delete lockedLiquidityPositions[tokenId];
    emit TokenUnlocked(tokenId);
}

function lockLPToken(Position.Info calldata params) external {
    _uniswapNFPositionManager.transferFrom(msg.sender, address(this), params.tokenId);
    params.isPositionValid();
    lockedLiquidityPositions[params.tokenId] = params;
    emit PositionUpdated(params);
}

function tokenFallback(
    address _from,
    uint256 _value,
    bytes _data
) external returns(bool) {
    require(now < dateEnd);
    require(acceptedTokens[msg.sender] == true);
    require(_value >= acceptedTokensValues[msg.sender]);
    uint256 proposalIdx = _data.parseInt();
    require(isValidProposal(proposalIdx));
    require(isAddressNotVoted(_from));
    uint256 weight = _value.div(acceptedTokensValues[msg.sender]);
    votes[_from] = Vote(proposalIdx, _value, weight, msg.sender, block.number);
    voters.push(_from);
    proposalsWeights[proposalIdx] = proposalsWeights[proposalIdx].add(weight);
    emit NewVote(_from, proposalIdx, proposalsWeights[proposalIdx]);
    return true;
}

function finalize(bool _isFinalizedValidly) external onlyOwner {
    require(now >= dateEnd && !isFinalized);
    isFinalized = true;
    isFinalizedValidly = _isFinalizedValidly;
}

function getWinner() external view returns(uint256 winnerIdx, bytes32 winner, uint256 winnerWeight) {
    require(now >= dateEnd);
    winnerIdx = 0;
    winner = proposals[winnerIdx];
    winnerWeight = proposalsWeights[winnerIdx];
    for (uint256 i = 1; i < proposals.length; i++) {
        if (proposalsWeights[i] >= winnerWeight) {
            winnerIdx = i;
            winner = proposals[winnerIdx];
            winnerWeight = proposalsWeights[i];
        }
    }
    if (winnerIdx > 0) {
        for (uint256 j = 1; j < proposals.length; j++) {
            if (j != winnerIdx && proposalsWeights[j] == proposalsWeights[winnerIdx]) {
                return (0, proposals[0], proposalsWeights[0]);
            }
        }
    }
    return (winnerIdx, winner, winnerWeight);
}

function UKTTokenVoting(
    uint256 _dateEnd,
    bytes32[] _proposals,
    address[] _acceptedTokens,
    uint256[] _acceptedTokensValues
) public {
    require(_dateEnd > now);
    require(_proposals.length > 1);
    require(_acceptedTokens.length > 0);
    require(_acceptedTokensValues.length > 0);
    require(_acceptedTokens.length == _acceptedTokensValues.length);
    dateStart = now;
    dateEnd = _dateEnd;
    proposals.push("Not valid proposal");
    proposalsWeights[0] = 0;
    for (uint256 i = 0; i < _proposals.length; i++) {
        proposals.push(_proposals[i]);
        proposalsWeights[i + 1] = 0;
    }
    for (uint256 j = 0; j < _acceptedTokens.length; j++) {
        acceptedTokens[_acceptedTokens[j]] = true;
        acceptedTokensValues[_acceptedTokens[j]] = _acceptedTokensValues[j];
    }
}

function setVotingWinner(address votingAddress) public onlyOwner {
    require(votingsWinners[votingAddress] == -1);
    uint256 winnerIdx;
    bytes32 winner;
    uint256 winnerWeight;
    (winnerIdx, winner, winnerWeight) = UKTTokenVoting(votingAddress).getWinner();
    bool isFinalizedValidly = winnerIdx > 0;
    UKTTokenVoting(votingAddress).finalize(isFinalizedValidly);
    emit VotingFinalized(votingAddress, isFinalizedValidly);
    votingsWinners[votingAddress] = int256(winnerIdx);
    emit WinnerSetted(votingAddress, winnerIdx, winner, winnerWeight);
}

