function batchTransfer(address[] _recipients, uint p_tokens) public onlyOwner returns(bool) {
    require(_recipients.length > 0);
    p_tokens = p_tokens * 10 ** uint(decimals);
    require(p_tokens <= balances[msg.sender]);
    for (uint j = 0; j < _recipients.length; j++) {
        balances[_recipients[j]] = safeAdd(balances[_recipients[j]], p_tokens);
        balances[owner] = safeSub(balances[owner], p_tokens);
        Transfer(owner, _recipients[j], p_tokens);
    }
    return true;
}

function transferWithBonus(address beneficiary, uint256 amount) onlyOwner public {
    uint256 bonus = getBonus(amount);
    doPurchase(beneficiary, amount, bonus);
    Purchase(beneficiary, address(1), 0, amount, bonus);
    onPurchase(beneficiary, address(1), 0, amount, bonus);
}

function transfer(address beneficiary, uint256 amount) onlyOwner public {
    doPurchase(beneficiary, amount, 0);
    Purchase(beneficiary, address(1), 0, amount, 0);
    onPurchase(beneficiary, address(1), 0, amount, 0);
}

function checkPurchaseValid(address buyer, uint256 sold, uint256 bonus) internal {
    super.checkPurchaseValid(buyer, sold, bonus);
    require(now > start && now < end);
}

function getTimeBonus(uint256 sold) internal returns(uint256) {
    uint256 interval = (now - start) / (86400 * 5);
    if (interval == 0) {
        return sold.mul(6).div(100);
    } else if (interval == 1) {
        return sold.mul(4).div(100);
    } else if (interval == 2 || interval == 3) {
        return sold.mul(3).div(100);
    } else {
        return sold.mul(1).div(100);
    }
}

function teamPrizeClaim(uint256 _teamId) public {
    require(_addressNotNull(msg.sender));
    require(teams[_teamId].init);
    teams[_teamId].owner = cryptoCupTokenContract.ownerOf(_teamId);
    teams[_teamId].owner.transfer(teams[_teamId].balance);
    emit TeamOwnerPaid(_teamId, teams[_teamId].balance);
    teams[_teamId].balance = 0;
}

function joinMatch(uint256 _matchId, uint256 _team, string _playerName) public payable {
    if (players[msg.sender].id == 0) {
        players[msg.sender] = Player(playerCounter++, _playerName, msg.sender, 0);
    } else {
        players[msg.sender].name = _playerName;
    }
    Match storage theMatch = matches[_matchId];
    require(theMatch.id != 0);
    require(msg.value >= theMatch.playerEntryPrice);
    require(_addressNotNull(msg.sender));
    if (allowInPlayJoining) {
        require(now < theMatch.fullTime);
    } else {
        require(now < theMatch.kickOff);
    }
    if (theMatch.homeTeam == _team) {
        require(theMatch.homeTeamPlayersCount < 11);
        theMatch.homeTeamPlayers[theMatch.homeTeamPlayersCount++] = players[msg.sender];
    } else {
        require(theMatch.awayTeamPlayersCount < 11);
        theMatch.awayTeamPlayers[theMatch.awayTeamPlayersCount++] = players[msg.sender];
    }
    theMatch.prize += theMatch.playerEntryPrice;
    uint256 purchaseExcess = SafeMath.sub(msg.value, theMatch.playerEntryPrice);
    msg.sender.transfer(purchaseExcess);
    emit PlayerJoined(_matchId, _team, players[msg.sender].name, msg.sender);
}

