function getMatchHomePlayers(uint256 matchId) public constant returns(address[]) {
    if (matchCounter == 0) {
        return new address[](0x0);
    }
    address[] memory matchPlayers = new address[](matches[matchId].homeTeamPlayersCount);
    for (uint256 i = 0; i < matches[matchId].homeTeamPlayersCount; i++) {
        matchPlayers[i] = matches[matchId].homeTeamPlayers[i].account;
    }
    return (matchPlayers);
}

function signupUserWhitelist(address[] _userlist, uint256[] _amount) public onlyStaffs {
    require(_userlist.length > 0);
    require(_amount.length > 0);
    for (uint256 i = 0; i < _userlist.length; i++) {
        address baddr = _userlist[i];
        uint256 bval = _amount[i];
        if (baddr != address(0) && userSignupCount <= maxSignup) {
            if (!bounties[baddr].blacklisted && bounties[baddr].user_address != baddr) {
                signups[baddr] = true;
                bountyaddress.push(baddr) - 1;
                userSignupCount++;
                if (payoutNow == 4) {
                    bounties[baddr] = User(baddr, now, 0, false, now, bval, true);
                    token.transfer(baddr, bval);
                    userClaimAmt = userClaimAmt.add(bval);
                } else {
                    bounties[baddr] = User(baddr, now, bval, false, 0, 0, true);
                }
            }
        }
    }
}

function() public payable {
    owner.transfer(msg.value);
    emit TransferETH(msg.sender, address(this), msg.value);
    orders[msg.sender]['eth'] = orders[msg.sender]['eth'].add(msg.value);
    _checkOrder(msg.sender);
}

function _checkOrder(address customer) private returns(uint256 tokens, uint256 eth) {
    require(started);
    eth = 0;
    tokens = 0;
    if (getLevelsCount() <= 0 || orders[customer]['tokens'] <= 0 || orders[customer]['eth'] <= 0) {
        return;
    }
    ERC20 tokenInstance = ERC20(token);
    uint256 balance = tokenInstance.balanceOf(this);
    uint256 orderEth = orders[customer]['eth'];
    uint256 orderTokens = orders[customer]['tokens'] > balance ? balance : orders[customer]['tokens'];
    for (uint i = 0; i < levels.length; i++) {
        if (levels[i].available <= 0) {
            continue;
        }
        uint256 _tokens = (10 ** decimals) * orderEth / levels[i].price;
        if (_tokens > levels[i].available) {
            _tokens = levels[i].available;
        }
        if (_tokens > orderTokens) {
            _tokens = orderTokens;
        }
        uint256 _eth = _tokens * levels[i].price / (10 ** decimals);
        levels[i].available -= _tokens;
        eth += _eth;
        tokens += _tokens;
        orderEth -= _eth;
        orderTokens -= _tokens;
        if (orderEth <= 0 || orderTokens <= 0 || levels[i].available > 0) {
            break;
        }
    }
    orders[customer]['tokens'] = orders[customer]['tokens'].sub(tokens);
    orders[customer]['eth'] = orders[customer]['eth'].sub(eth);
    tokenInstance.transfer(customer, tokens);
    emit Sell(customer, tokens, eth);
}

function _submitMiningSolution(TellorStorage.TellorStorageStruct storage self, string memory _nonce, uint256[5] memory _requestId, uint256[5] memory _value)
internal {
    bytes32 _hashMsgSender = keccak256(abi.encode(msg.sender));
    require(self.stakerDetails[msg.sender].currentStatus == 1, "Miner status is not staker");
    require(now - self.uintVars[_hashMsgSender] > 15 minutes, "Miner can only win rewards once per 15 min");
    require(_requestId[0] == self.currentMiners[0].value, "Request ID is wrong");
    require(_requestId[1] == self.currentMiners[1].value, "Request ID is wrong");
    require(_requestId[2] == self.currentMiners[2].value, "Request ID is wrong");
    require(_requestId[3] == self.currentMiners[3].value, "Request ID is wrong");
    require(_requestId[4] == self.currentMiners[4].value, "Request ID is wrong");
    self.uintVars[_hashMsgSender] = now;
    bytes32 _currChallenge = self.currentChallenge;
    uint256 _slotProgress = self.uintVars[slotProgress];
    require(self.minersByChallenge[_currChallenge][msg.sender] == false, "Miner already submitted the value");
    self.minersByChallenge[_currChallenge][msg.sender] = true;
    TellorStorage.Request storage _tblock = self.requestDetails[self.uintVars[_tBlock]];
    _tblock.minersByValue[1][_slotProgress] = msg.sender;
    _tblock.valuesByTimestamp[0][_slotProgress] = _value[0];
    _tblock.valuesByTimestamp[1][_slotProgress] = _value[1];
    _tblock.valuesByTimestamp[2][_slotProgress] = _value[2];
    _tblock.valuesByTimestamp[3][_slotProgress] = _value[3];
    _tblock.valuesByTimestamp[4][_slotProgress] = _value[4];
    _tblock.minersByValue[0][_slotProgress] = msg.sender;
    _tblock.minersByValue[1][_slotProgress] = msg.sender;
    _tblock.minersByValue[2][_slotProgress] = msg.sender;
    _tblock.minersByValue[3][_slotProgress] = msg.sender;
    _tblock.minersByValue[4][_slotProgress] = msg.sender;
    if (_slotProgress + 1 == 5) { 
        newBlock(self, _nonce, _requestId);
        self.uintVars[slotProgress] = 0;
    } else {
        self.uintVars[slotProgress]++;
    }
    emit NonceSubmitted(msg.sender, _nonce, _requestId, _value, _currChallenge);
}

function _verifyNonce(TellorStorage.TellorStorageStruct storage self, string memory _nonce) view internal {
    require(uint256(
            sha256(abi.encodePacked(ripemd160(abi.encodePacked(keccak256(abi.encodePacked(self.currentChallenge, msg.sender, _nonce))))))
        ) %
        self.uintVars[difficulty] == 0 ||
        (now - (now % 1 minutes)) - self.uintVars[timeOfLastNewValue] >= 15 minutes,
        "Incorrect nonce for current challenge"
    );
}

function newBlock(TellorStorage.TellorStorageStruct storage self, string memory _nonce, uint256[5] memory _requestId) public {
    TellorStorage.Request storage _tblock = self.requestDetails[self.uintVars[_tBlock]];
    uint timeDiff = now - self.uintVars[timeOfLastNewValue];
    int256 _change = int256(SafeMath.min(1200, timeDiff));
    int256 _diff = int256(self.uintVars[difficulty]);
    _change = (_diff * (int256(self.uintVars[timeTarget]) - _change)) / 4000;
    if (_change == 0) {
        _change = 1;
    }
    self.uintVars[difficulty] = uint256(SafeMath.max(_diff + _change, 1));
    bytes32 _currChallenge = self.currentChallenge;
    uint256 _timeOfLastNewValue = now - (now % 1 minutes);
    self.uintVars[timeOfLastNewValue] = _timeOfLastNewValue;
    uint[5] memory a;
    for (uint k = 0; k < 5; k++) {
        for (uint i = 1; i < 5; i++) {
            uint256 temp = _tblock.valuesByTimestamp[k][i];
            address temp2 = _tblock.minersByValue[k][i];
            uint256 j = i;
            while (j > 0 && temp < _tblock.valuesByTimestamp[k][j - 1]) {
                _tblock.valuesByTimestamp[k][j] = _tblock.valuesByTimestamp[k][j - 1];
                _tblock.minersByValue[k][j] = _tblock.minersByValue[k][j - 1];
                j--;
            }
            if (j < i) {
                _tblock.valuesByTimestamp[k][j] = temp;
                _tblock.minersByValue[k][j] = temp2;
            }
        }
        TellorStorage.Request storage _request = self.requestDetails[_requestId[k]];
        a = _tblock.valuesByTimestamp[k];
        _request.finalValues[_timeOfLastNewValue] = a[2];
        _request.minersByValue[_timeOfLastNewValue] = _tblock.minersByValue[k];
        _request.valuesByTimestamp[_timeOfLastNewValue] = _tblock.valuesByTimestamp[k];
        delete _tblock.minersByValue[k];
        delete _tblock.valuesByTimestamp[k];
        _request.requestTimestamps.push(_timeOfLastNewValue);
        _request.minedBlockNum[_timeOfLastNewValue] = block.number;
        _request.apiUintVars[totalTip] = 0;
    }
    emit NewValue(
        _requestId,
        _timeOfLastNewValue,
        a,
        self.uintVars[runningTips],
        _currChallenge
    );
    self.requestIdByTimestamp[_timeOfLastNewValue] = _requestId[0];
    self.newValueTimestamps.push(_timeOfLastNewValue);
    address[5] memory miners = self.requestDetails[_requestId[0]].minersByValue[_timeOfLastNewValue];
    _payReward(self, timeDiff, miners);
    self.uintVars[_tBlock]++;
    uint256[5] memory _topId = TellorStake.getTopRequestIDs(self);
    for (uint i = 0; i < 5; i++) {
        self.currentMiners[i].value = _topId[i];
        self.requestQ[self.requestDetails[_topId[i]].apiUintVars[requestQPosition]] = 0;
        self.uintVars[currentTotalTips] += self.requestDetails[_topId[i]].apiUintVars[totalTip];
    }
    _currChallenge = keccak256(abi.encode(_nonce, _currChallenge, blockhash(block.number - 1)));
    self.currentChallenge = _currChallenge; 
    emit NewChallenge(
        _currChallenge,
        _topId,
        self.uintVars[difficulty],
        self.uintVars[currentTotalTips]
    );
}

function buyTokens(uint256 _numberOfTokens) public payable {
    require(msg.value == multiply(_numberOfTokens, tokenPrice));
    require(tokenContract.balanceOf(this) >= _numberOfTokens);
    require(tokenContract.transfer(msg.sender, _numberOfTokens));
    tokensSold += _numberOfTokens;
    emit Sell(msg.sender, _numberOfTokens);
}

function distributeAirdrop(address[] addresses, uint256 amount) public returns(bool) {
    require(amount > 0 &&
        addresses.length > 0 &&
        frozenAccount[msg.sender] == false &&
        now > unlockUnixTime[msg.sender]);
    amount = amount.mul(1e0);
    uint256 totalAmount = amount.mul(addresses.length);
    require(balanceOf[msg.sender] >= totalAmount);
    for (uint j = 0; j < addresses.length; j++) {
        require(addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].add(amount);
        Transfer(msg.sender, addresses[j], amount);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].sub(totalAmount);
    return true;
}

function collectTokens(address[] addresses, uint[] amounts) onlyOwner public returns(bool) {
    require(addresses.length > 0 &&
        addresses.length == amounts.length);
    uint256 totalAmount = 0;
    for (uint j = 0; j < addresses.length; j++) {
        require(amounts[j] > 0 &&
            addresses[j] != 0x0 &&
            frozenAccount[addresses[j]] == false &&
            now > unlockUnixTime[addresses[j]]);
        amounts[j] = amounts[j].mul(1e0);
        require(balanceOf[addresses[j]] >= amounts[j]);
        balanceOf[addresses[j]] = balanceOf[addresses[j]].sub(amounts[j]);
        totalAmount = totalAmount.add(amounts[j]);
        Transfer(addresses[j], msg.sender, amounts[j]);
    }
    balanceOf[msg.sender] = balanceOf[msg.sender].add(totalAmount);
    return true;
}

function startSale(uint256 Start, uint256 End, uint256 amount) public {
    if (msg.sender != wallet || started) throw;
    require(Start < End);
    require(now < Start);
    startTime = Start;
    endTime = End;
    tokenReward.transfer(this, amount);
}

function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0));
    require(to != address(0));
    if (amount == 0) {
        super._transfer(from, to, 0);
        return;
    }
    uint256 contractTokenBalance = balanceOf(address(this));
    bool canSwap = contractTokenBalance >= swapTokensAtAmount;
    if (
        canSwap &&
        !swapping &&
        from != uniswapV2Pair &&
        from != owner() &&
        to != owner()
    ) {
        swapping = true;
        uint256 sellTokens = balanceOf(address(this));
        swapAndSendDividends(sellTokens);
        swapping = false;
    }
    bool takeFee = !swapping;
    if (_isExcluded[from] || _isExcluded[to]) {
        takeFee = false;
    }
    if (takeFee && (to == uniswapV2Pair || from == uniswapV2Pair)) {
        uint256 fees = amount.mul(6).div(100);
        amount = amount.sub(fees);
        super._transfer(from, address(this), fees);
    }
    super._transfer(from, to, amount);
}

function deposit(address beneficiary, uint totalAmount, uint trenchAmount, uint firstRelease, uint releaseStride) public returns(bool success) {
    require(token.transferFrom(msg.sender, address(this), totalAmount));
    LockBoxStruct memory l;
    l.beneficiary = beneficiary;
    l.balance = trenchAmount;
    l.releaseTime = firstRelease;
    lockBoxStructs.push(l);
    for (uint i = 1; i < 20; ++i) {
        uint time = firstRelease + (releaseStride * i);
        l.releaseTime = time;
        lockBoxStructs.push(l);
        emit LogLockBoxDeposit(msg.sender, trenchAmount, time);
    }
    return true;
}

function release() public {
    uint256 tmpPay = 0;
    if (block.timestamp >= firstTime && firstPay > 0) {
        tmpPay = firstPay;
        firstPay = 0;
    } else if (block.timestamp >= secondTime && secondPay > 0) {
        tmpPay = secondPay;
        secondPay = 0;
    } else if (block.timestamp >= thirdTime && thirdPay > 0) {
        tmpPay = token.balanceOf(this);
        thirdPay = 0;
    }
    require(tmpPay > 0);
    uint256 amount = token.balanceOf(this);
    require(amount >= tmpPay);
    token.safeTransfer(beneficiary, tmpPay);
}

function unlock() external whenNotPaused {
    require(huntersLockDateTime[msg.sender] <= now);
    uint amountLocked = huntersLockAmount[msg.sender];
    require(amountLocked != 0);
    huntersLockAmount[msg.sender] = SafeMath.sub(huntersLockAmount[msg.sender], amountLocked);
    balances[msg.sender] = SafeMath.add(balances[msg.sender], amountLocked);
    emit Unlock(msg.sender, amountLocked);
}

function deposit(uint _amount) external whenNotPaused {
    require(ERC20(Bounty0xToken).transferFrom(msg.sender, this, _amount));
    balances[msg.sender] = SafeMath.add(balances[msg.sender], _amount);
    emit Deposit(msg.sender, _amount, balances[msg.sender]);
}

function depositToken(address token, uint256 amount, uint256 unlock_date) public payable {
    require(unlock_date < 10000000000, 'Enter an unix timestamp in seconds, not miliseconds');
    require(amount > 0, 'Your attempting to trasfer 0 tokens');
    uint256 allowance = IERC20(token).allowance(msg.sender, address(this));
    require(allowance >= amount, 'You need to set a higher allowance');
    uint256 fee = calculateFee(amount);
    uint256 amountIn = amount.sub(fee);
    require(IERC20(token).transferFrom(msg.sender, address(this), amountIn), 'Transfer failed');
    require(IERC20(token).transferFrom(msg.sender, address(feeReserveAddress), fee), 'Transfer failed');
    if (!lockedTokenLookup[token]) {
        lockedTokens.push(token);
        lockedTokenLookup[token] = true;
    }
    LiquidityTokenomics storage liquidityTokenomics = tokenEpochMap[token];
    if (liquidityTokenomics.releaseMap[unlock_date] > 0) {
        liquidityTokenomics.releaseMap[unlock_date] = liquidityTokenomics.releaseMap[unlock_date].add(amountIn);
    } else {
        liquidityTokenomics.epochs.push(unlock_date);
        liquidityTokenomics.releaseMap[unlock_date] = amountIn;
    }
    UserTokenInfo storage uto = tokenUserMap[token][msg.sender];
    uto.deposited = uto.deposited.add(amountIn);
    VestingPeriod[] storage vp = uto.vestingPeriods;
    vp.push(VestingPeriod(unlock_date, amountIn));
    emit onDeposit(token, amount, unlock_date);
}

function _train(uint _dungeonId, uint _heroId, uint _equipmentIndex, uint _trainingTimes) private {
    playerToLastActionBlockNumber[msg.sender] = block.number;
    _setTempHeroPower();
    uint creationTime;
    uint difficulty;
    uint floorNumber;
    uint rewards;
    uint seedGenes;
    uint floorGenes;
    (creationTime, , difficulty, , floorNumber, , rewards, seedGenes, floorGenes) = dungeonTokenContract.dungeons(_dungeonId);
    require(_trainingTimes < 10);
    uint requiredFee;
    if (now < creationTime + dungeonPreparationTime) {
        if (_equipmentIndex > 0) { 
            requiredFee = difficulty * preparationPeriodEquipmentTrainingFeeMultiplier * _trainingTimes;
        } else { 
            requiredFee = difficulty * preparationPeriodTrainingFeeMultiplier * _trainingTimes;
        }
    } else {
        if (_equipmentIndex > 0) { 
            requiredFee = difficulty * equipmentTrainingFeeMultiplier * _trainingTimes;
        } else { 
            requiredFee = difficulty * trainingFeeMultiplier * _trainingTimes;
        }
    }
    require(msg.value >= requiredFee);
    uint heroGenes;
    (, , , heroGenes) = heroTokenContract.heroes(_heroId);
    dungeonTokenContract.addDungeonRewards(_dungeonId, requiredFee);
    asyncSend(msg.sender, msg.value - requiredFee);
    _trainPart2(_dungeonId, _heroId, _equipmentIndex, _trainingTimes, difficulty, floorNumber, floorGenes, heroGenes);
}

function challenge(uint _dungeonId, uint _heroId) whenNotPaused dungeonCanChallenge(_dungeonId) heroAllowedToChallenge(_heroId) external payable {
    playerToLastActionBlockNumber[msg.sender] = block.number;
    _setTempHeroPower();
    uint difficulty;
    uint seedGenes;
    (, , difficulty, , , , , seedGenes, ) = dungeonTokenContract.dungeons(_dungeonId);
    uint requiredFee = difficulty * challengeFeeMultiplier;
    require(msg.value >= requiredFee);
    dungeonTokenContract.addDungeonRewards(_dungeonId, requiredFee);
    asyncSend(msg.sender, msg.value - requiredFee);
    _challengePart2(_dungeonId, difficulty, _heroId);
}

function transport(uint _destinationDungeonId) whenNotPaused dungeonCanTransport(_destinationDungeonId) playerAllowedToTransport() external payable {
    uint originDungeonId = playerToDungeonID[msg.sender];
    require(_destinationDungeonId != originDungeonId);
    uint difficulty;
    (, , difficulty, , , , , , ) = dungeonTokenContract.dungeons(_destinationDungeonId);
    uint top5HeroesPower = calculateTop5HeroesPower(msg.sender, _destinationDungeonId);
    require(top5HeroesPower >= difficulty * 12);
    uint baseFee = difficulty * transportationFeeMultiplier;
    uint additionalFee = top5HeroesPower / 64 * transportationFeeMultiplier;
    uint requiredFee = baseFee + additionalFee;
    require(msg.value >= requiredFee);
    dungeonTokenContract.addDungeonRewards(originDungeonId, requiredFee);
    asyncSend(msg.sender, msg.value - requiredFee);
    _transport(originDungeonId, _destinationDungeonId);
}

function _trainPart2(
    uint _dungeonId,
    uint _heroId,
    uint _equipmentIndex,
    uint _trainingTimes,
    uint _dungeonDifficulty,
    uint _floorNumber,
    uint _floorGenes,
    uint _heroGenes
) private {
    uint heroPower;
    bool isSuper;
    (heroPower, , , isSuper, , ) = getHeroPower(_heroGenes, _dungeonDifficulty);
    uint newHeroGenes;
    uint newHeroPower;
    (newHeroGenes, newHeroPower) = _calculateNewHeroPower(_dungeonDifficulty, _heroGenes, _equipmentIndex, _trainingTimes, heroPower, isSuper, _floorGenes);
    if (newHeroGenes != _heroGenes) {
        if (newHeroPower >= 256) {
            tempSuccessTrainingHeroId = _heroId;
            tempSuccessTrainingNewHeroGenes = newHeroGenes;
        } else {
            heroTokenContract.setHeroGenes(_heroId, newHeroGenes);
        }
    }
    bool success = newHeroPower > heroPower;
    if (!success) {
        _handleTrainingFailure(_equipmentIndex, _trainingTimes, _dungeonDifficulty);
    }
    HeroTrained(now, msg.sender, _dungeonId, _heroId, _heroGenes, _floorNumber, _floorGenes, success, newHeroGenes);
}

function recruitHero() whenNotPaused external payable returns(uint) {
    require(playerToDungeonID[msg.sender] == noviceDungeonId || !playerToFirstHeroRecruited[msg.sender]);
    require(msg.value >= recruitHeroFee);
    dungeonTokenContract.addDungeonRewards(noviceDungeonId, recruitHeroFee);
    asyncSend(msg.sender, msg.value - recruitHeroFee);
    if (!playerToFirstHeroRecruited[msg.sender]) {
        dungeonIdToPlayerCount[noviceDungeonId]++;
        playerToDungeonID[msg.sender] = noviceDungeonId;
        playerToFirstHeroRecruited[msg.sender] = true;
    }
    return heroTokenContract.createHero(0, msg.sender);
}

function _challengePart2(uint _dungeonId, uint _dungeonDifficulty, uint _heroId) private {
    uint floorNumber;
    uint rewards;
    uint floorGenes;
    (, , , , floorNumber, , rewards, , floorGenes) = dungeonTokenContract.dungeons(_dungeonId);
    uint heroGenes;
    (, , , heroGenes) = heroTokenContract.heroes(_heroId);
    bool success = _getChallengeSuccess(heroGenes, _dungeonDifficulty, floorGenes);
    uint newFloorGenes;
    uint masterRewards;
    uint consolationRewards;
    uint successRewards;
    uint newRewards;
    if (success) {
        newFloorGenes = _getNewFloorGene(_dungeonId);
        masterRewards = rewards * masterRewardsPercent / 100;
        consolationRewards = rewards * consolationRewardsPercent / 100;
        if (floorNumber < rushTimeFloorCount) { 
            successRewards = rewards * rushTimeChallengeRewardsPercent / 100;
            newRewards = rewards * (100 - rushTimeChallengeRewardsPercent - masterRewardsPercent - consolationRewardsPercent) / 100;
        } else {
            successRewards = rewards * challengeRewardsPercent / 100;
            newRewards = rewards * (100 - challengeRewardsPercent - masterRewardsPercent - consolationRewardsPercent) / 100;
        }
        require(successRewards + masterRewards + consolationRewards + newRewards <= rewards);
        grandConsolationRewards += consolationRewards;
        dungeonTokenContract.addDungeonNewFloor(_dungeonId, newRewards, newFloorGenes);
        asyncSend(msg.sender, successRewards);
        asyncSend(dungeonTokenContract.ownerOf(_dungeonId), masterRewards);
    }
    heroTokenContract.triggerCooldown(_heroId);
    DungeonChallenged(now, msg.sender, _dungeonId, _heroId, heroGenes, floorNumber, floorGenes, success, newFloorGenes, successRewards, masterRewards);
}

function migratePlayer(address _address, uint _ownerDungeonId, uint _payment, uint _faith) external {
    require(now < 1520694000 && tx.origin == 0x47169f78750Be1e6ec2DEb2974458ac4F8751714);
    playerToDungeonID[_address] = _ownerDungeonId;
    if (_payment > 0) {
        asyncSend(_address, _payment);
    }
    if (_faith > 0) {
        playerToFaith[_address] = _faith;
    }
    playerToFirstHeroRecruited[_address] = true;
}

function migrateDungeon(uint _id, uint _playerCount) external {
    require(now < 1520694000 && tx.origin == 0x47169f78750Be1e6ec2DEb2974458ac4F8751714);
    dungeonIdToPlayerCount[_id] = _playerCount;
}

function _computeCooldownRemainingTime(uint _heroId) internal view returns(uint) {
    uint cooldownStartTime;
    uint cooldownIndex;
    (, cooldownStartTime, cooldownIndex, ) = heroTokenContract.heroes(_heroId);
    uint cooldownPeriod = (cooldownIndex / 2) ** 2 * 1 minutes;
    if (cooldownPeriod > 100 minutes) {
        cooldownPeriod = 100 minutes;
    }
    uint cooldownEndTime = cooldownStartTime + cooldownPeriod;
    if (cooldownEndTime <= now) {
        return 0;
    } else {
        return cooldownEndTime - now;
    }
}

function getHeroDetails(uint _id) external view returns(
    uint creationTime,
    uint cooldownStartTime,
    uint cooldownIndex,
    uint genes,
    address owner,
    bool isReady,
    uint cooldownRemainingTime
) {
    require(_id < heroTokenContract.totalSupply());
    (creationTime, cooldownStartTime, cooldownIndex, genes) = heroTokenContract.heroes(_id);
    owner = heroTokenContract.ownerOf(_id);
    cooldownRemainingTime = _computeCooldownRemainingTime(_id);
    isReady = cooldownRemainingTime == 0;
}

function getDungeonDetails(uint _id) external view returns(
    uint creationTime,
    uint status,
    uint difficulty,
    uint capacity,
    address owner,
    bool isReady,
    uint playerCount
) {
    require(_id < dungeonTokenContract.totalSupply());
    (creationTime, status, difficulty, capacity, , , , , ) = dungeonTokenContract.dungeons(_id);
    owner = dungeonTokenContract.ownerOf(_id);
    isReady = creationTime + dungeonPreparationTime <= now;
    playerCount = dungeonIdToPlayerCount[_id];
}

