function directRelease() private {
    if (block.timestamp > walletsLocking[msg.sender].cliff) {
        walletsLocking[msg.sender].lockedTokens = 0;
    } else if (block.timestamp > walletsLocking[msg.sender].cliff2) {
        walletsLocking[msg.sender].lockedTokens2 = 0;
    }
}

function checkTime() private {
    if (block.timestamp > walletsLocking[msg.sender].cliff) {
        if (msg.sender == MARKETING_FUNDS && walletsLocking[msg.sender].lastVisit == 1599004800) {
            walletsLocking[msg.sender].lockedTokens = walletsLocking[msg.sender].lockedTokens.sub(2234786e17); 
        }
        uint256 timeSpanned = (now.sub(walletsLocking[msg.sender].lastVisit)).div(walletsLocking[msg.sender].releasePeriod);
        if (timeSpanned >= 1) {
            uint256 released = timeSpanned.mul(walletsLocking[msg.sender].releasePercentage);
            if (released > walletsLocking[msg.sender].lockedTokens) {
                released = walletsLocking[msg.sender].lockedTokens;
            }
            walletsLocking[msg.sender].lastVisit = now;
            walletsLocking[msg.sender].lockedTokens = walletsLocking[msg.sender].lockedTokens.sub(released);
        }
    }
}

function createProduct(bytes32 _size, string delivery, bytes32 _userName, bytes32 _userEmail) public payable returns(bool success) {
    require(msg.sender != 0);
    require(startPrice != 0);
    require(msg.value >= startPrice);
    require(productList.length <= 100);
    bytes32 userId = bytes32(msg.sender);
    uint productCount = productList.length + 1;
    productId = bytes32(productCount);
    if (!isUser(userId)) {
        require(_userName != 0);
        require(_userEmail != 0);
        createUser(_userName, _userEmail);
    }
    require(isUser(userId));
    require(!isProduct(productId));
    productStructs[productId].productListPointer = productList.push(productId) - 1;
    productStructs[productId].userKey = userId;
    productStructs[productId].size = _size;
    productStructs[productId].productPrice = startPrice;
    productStructs[productId].delivery = delivery;
    productStructs[productId].inSale = false;
    productStructs[productId].historyUser.push(msg.sender);
    productStructs[productId].historyDate.push(now);
    productStructs[productId].historyPrice.push(startPrice);
    userStructs[userId].productKeyPointers[productId] = userStructs[userId].productKeys.push(productId) - 1;
    emit LogNewProduct(msg.sender, productId, userId);
    uint oddMoney = msg.value - startPrice;
    address(this).transfer(startPrice);
    uint countProduct = getProductCount();
    startPrice = ((countProduct * fixPrice) + fixPrice) * 10 ** decimals;
    msg.sender.transfer(oddMoney);
    return true;
}

function ownerSetStakeCommence(uint timestamp) public onlyOwner {
    require((stakeCommence <= 0) && (timestamp >= chainStartTime));
    stakeCommence = timestamp;
}

function getPoSReward(address _address) internal view returns(uint) {
    require((block.timestamp >= stakeCommence) && (stakeCommence > 0));
    uint _now = block.timestamp;
    uint _coinAge = getCoinAge(_address, _now);
    if (_coinAge <= 0) return 0;
    uint interest = maxMintPoS;
    if ((_now.sub(stakeCommence)).div(365 days) == 0) {
        interest = (770 * maxMintPoS).div(100);
    } else if ((_now.sub(stakeCommence)).div(365 days) == 1) {
        interest = (435 * maxMintPoS).div(100);
    }
    return (_coinAge * interest).div(365 * (10 ** decimals));
}

function annualInterest() public view returns(uint interest) {
    uint _now = block.timestamp;
    interest = maxMintPoS;
    if ((_now.sub(stakeCommence)).div(365 days) == 0) {
        interest = (770 * maxMintPoS).div(100);
    } else if ((_now.sub(stakeCommence)).div(365 days) == 1) {
        interest = (435 * maxMintPoS).div(100);
    }
}

