function() public payable {
    require(now >= startDate && now <= endDate && totalSupply_ >= startCrowdsale && totalSupply_ < endCrowdsale);
    uint tokens;
    if (now <= bonusEnds) {
        tokens = msg.value * 8400;
    } else {
        tokens = msg.value * 7350;
    }
    balances[msg.sender] = safeAdd(balances[msg.sender], tokens);
    totalSupply_ = safeAdd(totalSupply_, tokens);
    Transfer(address(0), msg.sender, tokens);
    owner.transfer(msg.value);
}

function initialize(
    uint256 _requiredSignatures,
    address[] _initialValidators,
    address[] _initialRewards,
    address _owner
) external onlyRelevantSender returns(bool) {
    require(!isInitialized());
    _setOwner(_owner);
    require(_requiredSignatures != 0);
    require(_initialValidators.length >= _requiredSignatures);
    require(_initialValidators.length == _initialRewards.length);
    for (uint256 i = 0; i < _initialValidators.length; i++) {
        require(_initialValidators[i] != address(0) && _initialValidators[i] != F_ADDR);
        require(_initialRewards[i] != address(0));
        require(!isValidator(_initialValidators[i]));
        if (i == 0) {
            setNextValidator(F_ADDR, _initialValidators[i]);
            if (_initialValidators.length == 1) {
                setNextValidator(_initialValidators[i], F_ADDR);
            }
        } else if (i == _initialValidators.length - 1) {
            setNextValidator(_initialValidators[i - 1], _initialValidators[i]);
            setNextValidator(_initialValidators[i], F_ADDR);
        } else {
            setNextValidator(_initialValidators[i - 1], _initialValidators[i]);
        }
        setValidatorRewardAddress(_initialValidators[i], _initialRewards[i]);
        emit ValidatorAdded(_initialValidators[i]);
    }
    setValidatorCount(_initialValidators.length);
    uintStorage[REQUIRED_SIGNATURES] = _requiredSignatures;
    uintStorage[DEPLOYED_AT_BLOCK] = block.number;
    setInitialize();
    emit RequiredSignaturesChanged(_requiredSignatures);
    return isInitialized();
}

receive() payable external {
    require(startDate > 0 && now.sub(startDate) <= 7 days);
    require(availableOBR() > 0);
    require(msg.value >= 1 ether && msg.value <= 50 ether);
    uint256 amount;
    if (now.sub(startDate) <= 1 days) {
        uint256 rate = (uint256(2000000000000000000));
        amount = (msg.value.mul(rate)) / 10 ** 18;
    } else if (now.sub(startDate) > 1 days && now.sub(startDate) <= 2 days) {
        uint256 rate = (uint256(1940000000000000000));
        amount = (msg.value.mul(rate)) / 10 ** 18;
    } else if (now.sub(startDate) > 2 days && now.sub(startDate) <= 3 days) {
        uint256 rate = (uint256(1880000000000000000));
        amount = (msg.value.mul(rate)) / 10 ** 18;
    } else if (now.sub(startDate) > 3 days && now.sub(startDate) <= 4 days) {
        uint256 rate = (uint256(1830000000000000000));
        amount = (msg.value.mul(rate)) / 10 ** 18;
    } else if (now.sub(startDate) > 4 days && now.sub(startDate) <= 5 days) {
        uint256 rate = (uint256(1780000000000000000));
        amount = (msg.value.mul(rate)) / 10 ** 18;
    } else if (now.sub(startDate) > 5 days && now.sub(startDate) <= 6 days) {
        uint256 rate = (uint256(1730000000000000000));
        amount = (msg.value.mul(rate)) / 10 ** 18;
    } else if (now.sub(startDate) > 6 days && now.sub(startDate) <= 7 days) {
        uint256 rate = (uint256(1690000000000000000));
        amount = (msg.value.mul(rate)) / 10 ** 18;
    } else {
        amount = 0;
    }
    require(amount <= availableOBR());
    totalSold = totalSold.add(amount);
    collectedETH = collectedETH.add(msg.value);
    Token.transfer(msg.sender, amount);
}

