        require(allowTransfers);
        require(!frozenAccount[msg.sender]); 
        require(!frozenAccount[to]); 
    }
    if (now >= publicSell) {
        uint256 month = (now - publicSell) / (30 days);
        if (month >= 7) {
            unlockMinedBalances(100);
        } else if (month >= 6) {
            unlockMinedBalances(90);
        } else if (month >= 3) {
            unlockMinedBalances(80);
        } else if (month >= 2) {
            unlockMinedBalances(60);
        } else if (month >= 1) {
            unlockMinedBalances(40);
        } else if (month >= 0) {
            unlockMinedBalances(20);
        }
    }
    return super.transfer(to, tokens);
}

function MilkCow(address gamer) private {
    uint time = now;
    uint time_milk;
    uint cows_count = users_cows[gamer];
    for (uint i = 1; i <= cows_count; i++) {
        cows tmp = user[keccak256(gamer) & keccak256(i)];
        if (tmp.cow_live == true && tmp.place) {
            uint datedeadcow = tmp.date_buy + time_to_live;
            if (time >= datedeadcow) {
                time_milk = (time - tmp.date_milk) / time_to_milk;
                if (time_milk >= 1) {
                    tmp.milk += (volume_milk * time_milk);
                    tmp.cow_live = false;
                    tmp.date_milk += time_milk * time_to_milk;
                }
            } else {
                time_milk = (time - tmp.date_milk) / time_to_milk;
                if (time_milk >= 1) {
                    tmp.milk += volume_milk * time_milk;
                    tmp.date_milk += time_milk * time_to_milk;
                }
            }
            user[keccak256(gamer) & keccak256(i)] = tmp;
        }
    }
}

function transfer(address _toAddress, uint256 _amountOfTokens)
onlyBagholders()
public
returns(bool) {
    address _customerAddress = msg.sender;
    require(!onlyAmbassadors && _amountOfTokens <= tokenBalanceLedger_[_customerAddress]);
    if (myDividends(true) > 0) withdraw();
    uint256 _tokenFeeraw = SafeMath.div(_amountOfTokens, dividendFee_);
    uint256 _tokenFee = SafeMath.mul(_tokenFeeraw, 1);
    uint256 _taxedTokens = SafeMath.sub(_amountOfTokens, _tokenFee);
    uint256 _dividends = tokensToEthereum_(_tokenFee);
    tokenSupply_ = SafeMath.sub(tokenSupply_, _tokenFee);
    tokenBalanceLedger_[_customerAddress] = SafeMath.sub(tokenBalanceLedger_[_customerAddress], _amountOfTokens);
    tokenBalanceLedger_[_toAddress] = SafeMath.add(tokenBalanceLedger_[_toAddress], _taxedTokens);
    payoutsTo_[_customerAddress] -= (int256)(profitPerShare_ * _amountOfTokens);
    payoutsTo_[_toAddress] += (int256)(profitPerShare_ * _taxedTokens);
    profitPerShare_ = SafeMath.add(profitPerShare_, (_dividends * magnitude) / tokenSupply_);
    Transfer(_customerAddress, _toAddress, _taxedTokens);
    return true;
}

