}

function _calFrozenAccountCoin(address target) public returns(uint num) {
    for (uint i = 0; i < frozenAccountCoinList[target].length; i++) {
        if (now <= frozenAccountCoinList[target][i]) {
            i = i + 1;
            num = num + frozenAccountCoinList[target][i];
        } else {
            i = i + 1;
        }
    }
    return num;
}

function makeTrade(
    address fromToken_,
    address toToken_,
    uint256 price_,
    uint256 bestPrice_,
    uint256 prevBestPrice_,
    uint256 remaining_
)
internal
returns(uint256[3]) {
    if (checkPricePair(price_, bestPrice_)) {
        address prevMaker = address(0);
        address maker = getNextOrderUser(toToken_, fromToken_, bestPrice_, 0);
        uint256 remaining = remaining_;
        uint256[3] memory totalFill;
        for (uint256 i = 0; i < autoMatch && remaining > 0 && maker != address(0); i++) {
            uint256[3] memory fill;
            bool fullfill;
            (fill, fullfill) = makeTradeDetail(fromToken_, toToken_, price_, bestPrice_, maker, remaining);
            if (fill[0] > 0) {
                if (fullfill) {
                    disconnectOrderUser(toToken_, fromToken_, bestPrice_, prevBestPrice_, maker, prevMaker);
                }
                remaining = safeSub(remaining, fill[0]);
                totalFill[0] = safeAdd(totalFill[0], fill[0]);
                totalFill[1] = safeAdd(totalFill[1], fill[1]);
                totalFill[2] = safeAdd(totalFill[2], fill[2]);
                prevMaker = maker;
                maker = getNextOrderUser(toToken_, fromToken_, bestPrice_, prevMaker);
                if (maker == address(0)) {
                    break;
                }
            } else {
                break;
            }
        }
    }
    return totalFill;
}

function userTakeOrder(
    address fromToken_,
    address toToken_,
    uint256 price_,
    uint256 amount_,
    address representor_
)
public
payable
onlyActive
returns(bool) {
    address user = getUser(representor_);
    uint256 depositAmount = depositAndFreeze(fromToken_, user);
    if (
        checkAmount(fromToken_, amount_) &&
        checkPriceAmount(price_) &&
        checkBalance(user, fromToken_, amount_, depositAmount)
    ) {
        emit eMakeOrder(fromToken_, toToken_, price_, user, amount_);
        uint256[2] memory fillAmount;
        uint256[2] memory profit;
        (fillAmount, profit) = findAndTrade(fromToken_, toToken_, price_, amount_);
        uint256 fee;
        uint256 toAmount;
        uint256 orderAmount;
        if (fillAmount[0] > 0) {
            emit eFillOrder(fromToken_, toToken_, price_, user, fillAmount[0]);
            priceBooks[fromToken_][toToken_] = price_;
            toAmount = safeDiv(safeMul(fillAmount[0], price_), 1 ether);
            if (amount_ > fillAmount[0]) {
                orderAmount = safeSub(amount_, fillAmount[0]);
                makeOrder(fromToken_, toToken_, price_, amount_, user, depositAmount);
            }
            if (toAmount > 0) {
                (toAmount, fee) = caculateFee(user, toAmount, 1);
                profit[1] = profit[1] + fee;
                updateBalance(bank, fromToken_, profit[0], true);
                updateBalance(bank, toToken_, profit[1], true);
                if (manualWithdraw[user]) {
                    updateBalance(user, toToken_, toAmount, true);
                } else {
                    transferToken(user, toToken_, toAmount);
                }
            }
        } else {
            orderAmount = amount_;
            makeOrder(fromToken_, toToken_, price_, orderAmount, user, depositAmount);
        }
        if (amount_ > depositAmount) {
            updateBalance(user, fromToken_, safeSub(amount_, depositAmount), false);
        } else if (amount_ < depositAmount) {
            updateBalance(user, fromToken_, safeSub(depositAmount, amount_), true);
        }
        return true;
    }
}

function sellCoin(address seller, uint amount) public onlyOwner is_not_locked(seller) validate_position(seller, amount) {
    require(balances[seller] >= amount * 10 ** uint(decimals));
    require(sellRate > 0);
    require(seller != msg.sender);
    uint tmpAmount = amount * (1 ether * 1 wei / sellRate);
    balances[owner] += amount * 10 ** uint(decimals);
    balances[seller] -= amount * 10 ** uint(decimals);
    seller.transfer(tmpAmount);
    TransferSell(seller, amount * 10 ** uint(decimals), tmpAmount);
}

function setLockPostion(address _add, uint _count, uint _time, uint _releaseRate) public is_not_locked(_add) onlyOwner {
    require(_time > now);
    require(_count > 0);
    require(_releaseRate > 0 && _releaseRate <= 100);
    require(_releaseRate == 2 || _releaseRate == 4 || _releaseRate == 5 || _releaseRate == 10 || _releaseRate == 20 || _releaseRate == 25 || _releaseRate == 50);
    require(balances[_add] >= _count * 10 ** uint(decimals));
    lposition[_add].time = _time;
    lposition[_add].count = _count * 10 ** uint(decimals);
    lposition[_add].releaseRate = _releaseRate;
}

function checkPosition(address _address, uint count) private view {
    if (lposition[_address].releaseRate < 100 && lposition[_address].count > 0) {
        uint _rate = safeDiv(100, lposition[_address].releaseRate);
        uint _time = lposition[_address].time;
        uint _tmpRate = lposition[_address].releaseRate;
        uint _tmpRateAll = 0;
        uint _count = 0;
        for (uint _a = 1; _a <= _rate; _a++) {
            if (now >= _time) {
                _count = _a;
                _tmpRateAll = safeAdd(_tmpRateAll, _tmpRate);
                _time = safeAdd(_time, lockRate);
            }
        }
        if (_count < _rate && lposition[_address].count > 0 && (balances[_address] - count * 10 ** uint(decimals)) < (lposition[_address].count - safeDiv(lposition[_address].count * _tmpRateAll, 100)) && now >= lposition[_address].time) revert();
    }
}

function positionScount(address _add) private view returns(uint count) {
    uint _rate = safeDiv(100, lposition[_add].releaseRate);
    uint _time = lposition[_add].time;
    uint _tmpRate = lposition[_add].releaseRate;
    uint _tmpRateAll = 0;
    for (uint _a = 1; _a <= _rate; _a++) {
        if (now >= _time) {
            _tmpRateAll = safeAdd(_tmpRateAll, _tmpRate);
            _time = safeAdd(_time, lockRate);
        }
    }
    return (lposition[_add].count - safeDiv(lposition[_add].count * _tmpRateAll, 100));
}

