function depositEth() external payable {
    require(_lgeOngoing == true);
    uint amount = msg.value;
    if (block.number >= 12550000) {
        uint phase = _phase;
        if (phase > 0) {
            _ETHDeposited += uint88(amount);
        }
        if (block.number >= phase + 12550000) {
            _phase = uint88(phase + 10000);
            _createLiquidity(phase);
        }
    }
    uint deployerShare = amount / 100;
    amount -= deployerShare;
    _deployer.transfer(deployerShare); 
    contributions[msg.sender] += amount;
}

function _createLiquidity(uint phase) internal {
    address WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address token = 0xdff92dCc99150Df99D54BC3291bD7e5522bB1Edd; 
    address staking = _staking;
    address factory = 0x5C69bEe701ef814a2B6a3EDD4B1652CB9cc5aA6f;
    address tknETHLP = I(factory).getPair(token, WETH);
    if (phase == 0) {
        _ETHDeposited = uint88(address(this).balance);
        if (tknETHLP == address(0)) {
            tknETHLP = I(factory).createPair(token, WETH);
            require(tknETHLP != address(0));
        }
    }
    uint ETHDeposited = _ETHDeposited;
    uint ethToDeposit = ETHDeposited * 3 / 5;
    uint tokenToDeposit = 1e23;
    if (phase == 90000) {
        ethToDeposit = address(this).balance;
        I(staking).init(ETHDeposited, tknETHLP);
        delete _staking;
        delete _lgeOngoing;
        delete _ETHDeposited;
        delete _phase;
        delete _deployer;
    }
    I(WETH).deposit {
        value: ethToDeposit
    }();
    I(token).transfer(tknETHLP, tokenToDeposit);
    I(WETH).transfer(tknETHLP, ethToDeposit);
    I(tknETHLP).mint(staking);
}

function pump() public returns(uint haul) {
    require(pumpers[msg.sender], "NOT YOU"); 
    require((now - lastPumpTime) > interval, "TOO SOON"); 
    lastPumpTime = now;
    haul = erc20.balanceOf(address(this)) / flowGuage * flowRate;
    erc20.transfer(msg.sender, haul);
}

function safeWithdrawal(uint amount) external onlyOwner {
    require(this.balance >= amount);
    require(!isICOActive());
    if (owner.send(amount)) {
        FundTransfer(address(this), msg.sender, amount);
    }
}

function processPayment(address backerAddress, uint amount) internal {
    require(isICOActive());
    assert(msg.value > 0 finney);
    FundTransfer(backerAddress, address(this), amount);
    uint tokensPerEth = 10000;
    uint tokenAmount = amount * tokensPerEth;
    uint remainingTokenBalance = token.balanceOf(saleWalletAddress);
    if (remainingTokenBalance <= tokenAmount) {
        tokenAmount = remainingTokenBalance;
        goalReached = true;
    }
    uint acceptedAmount = tokenAmount / tokensPerEth;
    totalCollected += acceptedAmount;
    token.transferFrom(saleWalletAddress, backerAddress, tokenAmount);
    TokenSale(backerAddress, amount, tokenAmount, tokensPerEth);
    uint change = amount - acceptedAmount;
    if (change > 0) {
        if (backerAddress.send(change)) {
            FundTransfer(address(this), backerAddress, change);
        } else revert();
    }
}

function closeMainSaleICO() external onlyOwner {
    require(!isICOActive());
    require(generalSaleStartDate < now);
    var amountToMove = token.balanceOf(generalSaleWallet.addr);
    token.transferFrom(generalSaleWallet.addr, playersReserve, amountToMove);
    generalSaleEndDate = now;
}

function isICOActive() public constant returns(bool active) {
    active = ((generalSaleStartDate <= now) && (now < generalSaleEndDate) && (!goalReached));
    return active;
}

function kill() external onlyOwner {
    require(!isICOActive());
    if (now < generalSaleStartDate) {
        selfdestruct(owner);
    } else if (token.balanceOf(generalSaleWallet.addr) == 0) {
        FundTransfer(address(this), msg.sender, this.balance);
        selfdestruct(owner);
    } else {
        revert();
    }
}

function sell(
    Order calldata order,
    Sig calldata sig,
    Sig calldata buyerFeeSig,
    uint256 royaltyFee,
    address payable royaltyReceipt,
    bool isStore,
    mintParams memory storeParams
) external payable {
    require((block.timestamp <= order.expiryTime), "Signature expired");
    require(order.orderType == 1, "Invalid order type");
    require(order.key.owner != msg.sender, "Invalid owner");
    validateOrderSignature(order, sig);
    validateBuyerFeeSig(order, royaltyFee, royaltyReceipt, buyerFeeSig);
    transferSellFee(order, royaltyReceipt, royaltyFee, msg.sender);
    setCompleted(order, true);
    transferToken(order, msg.sender, isStore, storeParams);
    emitMatchOrder(order, msg.sender);
}

function buy(
    Order calldata order,
    Sig calldata sig,
    Sig calldata buyerFeeSig,
    uint256 royaltyFee,
    address payable royaltyReceipt,
    bool isStore,
    mintParams memory storeParams
) external {
    require((block.timestamp <= order.expiryTime), "Signature expired");
    require(order.orderType == 2, "Invalid order");
    require(order.key.owner != msg.sender, "Invalid owner");
    validateOrderSignature(order, sig);
    validateBuyerFeeSig(order, royaltyFee, royaltyReceipt, buyerFeeSig);
    transferBuyFee(order, royaltyReceipt, royaltyFee, msg.sender);
    setCompleted(order, true);
    transferToken(order, msg.sender, isStore, storeParams);
    emitMatchOrder(order, msg.sender);
}

function bid(
    Order calldata order,
    Sig calldata sig,
    Sig calldata buyerSig,
    Sig calldata buyerFeeSig,
    address buyer,
    uint256 buyingAmount,
    uint256 royaltyFee,
    address payable royaltyReceipt,
    bool isStore,
    mintParams memory storeParams
) external {
    require((block.timestamp <= order.expiryTime), "Signature expired");
    require(buyingAmount >= order.buying, "BuyingAmount invalid");
    require(order.orderType == 3, "Invalid order");
    require(order.key.owner == msg.sender, "Not owner");
    validateOrderSignature(order, sig);
    validateBidOrderSignature(order, buyerSig, buyer, buyingAmount);
    validateBuyerFeeSig(order, royaltyFee, royaltyReceipt, buyerFeeSig);
    setCompleted(order, true);
    setCompletedBidOrder(order, true, buyer, buyingAmount);
    transferBidFee(
        order.key.buyAsset.token,
        order.key.owner,
        buyingAmount,
        royaltyReceipt,
        royaltyFee,
        buyer
    );
    transferToken(order, buyer, isStore, storeParams);
    emitMatchOrder(order, buyer);
}

