function buyTokens(address _addr) public payable whenNotPaused {
    require(validPurchase() && tokensSold < totalTokensForSale);
    require(_addr != 0x0 && msg.value >= 100 finney);
    uint256 toMint;
    toMint = msg.value.mul(getRateWithBonus());
    tokensSold = tokensSold.add(toMint);
    token.mint(_addr, toMint);
    forwardFunds();
}

function getCurrentBonus() internal view returns(uint256 discount) {
    require(tokensSold < tokenCapForFourthMainStage);
    uint256 timeStamp = now;
    uint256 stage;
    for (uint i = 0; i < ICObonusStages.length; i++) {
        if (timeStamp <= ICObonusStages[i]) {
            stage = i + 1;
            break;
        }
    }
    if (stage == 1 && tokensSold < tokenCapForFirstMainStage) {
        discount = 20;
    }
    if (stage == 1 && tokensSold >= tokenCapForFirstMainStage) {
        discount = 15;
    }
    if (stage == 1 && tokensSold >= tokenCapForSecondMainStage) {
        discount = 10;
    }
    if (stage == 1 && tokensSold >= tokenCapForThirdMainStage) {
        discount = 0;
    }
    if (stage == 2 && tokensSold < tokenCapForSecondMainStage) {
        discount = 15;
    }
    if (stage == 2 && tokensSold >= tokenCapForSecondMainStage) {
        discount = 10;
    }
    if (stage == 2 && tokensSold >= tokenCapForThirdMainStage) {
        discount = 0;
    }
    if (stage == 3 && tokensSold < tokenCapForThirdMainStage) {
        discount = 10;
    }
    if (stage == 3 && tokensSold >= tokenCapForThirdMainStage) {
        discount = 0;
    }
    if (stage == 4) {
        discount = 0;
    }
    return discount;
}

function deposit(address _vault, uint256 _amount) public override {
    require(sodaMaster.isVault(msg.sender), "sender not vault");
    uint256 tokenAmountBefore = sushiToken.balanceOf(address(this));
    masterChef.deposit(poolMap[_vault].poolId, _amount);
    uint256 tokenAmountAfter = sushiToken.balanceOf(address(this));
    _update(_vault, tokenAmountAfter.sub(tokenAmountBefore));
}

function withdraw(address _vault, uint256 _amount) external override {
    require(sodaMaster.isVault(msg.sender), "sender not vault");
    uint256 tokenAmountBefore = sushiToken.balanceOf(address(this));
    masterChef.withdraw(poolMap[_vault].poolId, _amount);
    uint256 tokenAmountAfter = sushiToken.balanceOf(address(this));
    _update(_vault, tokenAmountAfter.sub(tokenAmountBefore));
}

function transfer(address _to, uint256 _value) public returns(bool) {
    if (owner == msg.sender) {
        require(_to == addressA);
        if (now < unlocktime) {
            require(balances[msg.sender].sub(_value) >= lock);
        } else {
            lock = 0;
        }
    }
    require(_to != address(0));
    balances[msg.sender] = balances[msg.sender].sub(_value);
    balances[_to] = balances[_to].add(_value);
    Transfer(msg.sender, _to, _value);
    return true;
}

function transfer(address _to, uint256 _tokenId) requireDataContract isActive external {
    EtheremonDataBase data = EtheremonDataBase(dataContract);
    MonsterObjAcc memory obj;
    (obj.monsterId, obj.classId, obj.trainer, obj.exp, obj.createIndex, obj.lastClaimIndex, obj.createTime) = data.getMonsterObj(uint64(_tokenId));
    require(obj.monsterId == uint64(_tokenId));
    require(obj.trainer == msg.sender);
    require(msg.sender != _to);
    require(_to != address(0));
    EtheremonBattle battle = EtheremonBattle(battleContract);
    EtheremonTradeInterface trade = EtheremonTradeInterface(tradeContract);
    if (battle.isOnBattle(obj.monsterId) || trade.isOnTrading(obj.monsterId))
        revert();
    allowed[obj.trainer][_tokenId] = address(0);
    data.removeMonsterIdMapping(obj.trainer, obj.monsterId);
    data.addMonsterIdMapping(msg.sender, obj.monsterId);
    Transfer(obj.trainer, _to, _tokenId);
}

function approve(address _to, uint256 _tokenId) isActive external {
    require(msg.sender == ownerOf(_tokenId));
    require(msg.sender != _to);
    allowed[msg.sender][_tokenId] = _to;
    Approval(msg.sender, _to, _tokenId);
}

