function buyBag(uint256 _bagIndex) external payable {
    require(_bagIndex < bags.length);
    Bag storage bag = bags[_bagIndex];
    BagType storage bagType = bagTypes[bag.bagTypeIndex];
    require(now >= bag.availableTimestamp);
    require(msg.value >= bag.price);
    uint256 refund = msg.value - bag.price;
    address previousOwner = bag.owner;
    bag.owner = msg.sender;
    uint256 previousPrice = bag.price * 1000000 / bagType.priceMultiplierPerBuy;
    uint256 nextPrice = bag.price * bagType.priceMultiplierPerBuy / 1000000;
    uint256 previousOwnerReward;
    if (bag.amountOfBuys == 0) {
        previousOwnerReward = bag.price;
    }
    else {
        previousOwnerReward = bag.price * bag.commission / 1000000;
    }
    bag.price = nextPrice;
    bag.amountOfBuys++;
    if (bag.amountOfBuys > 1) {
        if (bag.commission < bagType.maximumCommission) {
            uint256 newCommission = bag.commission + bagType.commissionIncrementPerBuy;
            if (newCommission >= bagType.maximumCommission) {
                bag.commission = bagType.maximumCommission;
            } else {
                bag.commission = newCommission;
            }
        }
    }
    if (addressToTotalPurchasesMade[msg.sender] == 0) {
        allParticipants.push(msg.sender);
    }
    addressToTotalEtherSpent[msg.sender] += msg.value;
    addressToTotalPurchasesMade[msg.sender]++;
    if (previousOwner != address(this)) {
        previousOwner.transfer(previousOwnerReward);
    }
    if (refund > 0) {
        msg.sender.transfer(refund);
    }
}

function approve(address _to, uint256 _bagIndex) external {
    require(_bagIndex < bags.length);
    require(msg.sender == bags[_bagIndex].owner);
    ownerToAddressToBagIndexAllowed[msg.sender][_to][_bagIndex] = true;
}

function ownerOf(uint256 _bagIndex) external view returns(address) {
    require(_bagIndex < bags.length);
    return bags[_bagIndex].owner;
}

function _transferBag(address _from, address _to, uint256 _bagIndex) internal {
    require(_bagIndex < bags.length);
    require(bags[_bagIndex].amountOfBuys >= BAG_TRANSFER_MINIMUM_AMOUNT_OF_BUYS);
    require(bags[_bagIndex].owner == _from);
    bags[_bagIndex].owner = _to;
    ownerToBagIndices[_from].remove(_bagIndex);
    ownerToBagIndices[_to].add(_bagIndex);
    Transfer(_from, _to, _bagIndex);
}

function takeOwnership(uint256 _bagIndex) external {
    require(_bagIndex < bags.length);
    address previousOwner = bags[_bagIndex].owner;
    require(ownerToAddressToBagIndexAllowed[previousOwner][msg.sender][_bagIndex] == true);
    ownerToAddressToBagIndexAllowed[previousOwner][msg.sender][_bagIndex] = false;
    _transferBag(previousOwner, msg.sender, _bagIndex);
}

function checkCurrentStage() internal {
    if (campaignStages[uint8(currentStage)].planEndDate <= now) {
        if (currentStage == StageName.PreSale &&
            (weiRaised + msg.value) < softCap
        ) {
            currentStage = StageName.Refund;
            return;
        }
        currentStage = StageName.Pause;
    }
    if (currentStage == StageName.Sale &&
        (weiRaised + msg.value) >= hardCap
    ) {
        currentStage = StageName.Ended;
    }
}

function refund(address investor) external {
    require(currentStage == StageName.Refund);
    require(investor != address(0));
    assert(msg.data.length >= 32 + 4); 
    uint256 depositedValue = deposited[investor];
    deposited[investor] = 0;
    investor.transfer(depositedValue);
    emit Refunded(investor, depositedValue);
}

function exchangeEtherOnTokens(address beneficiary) public payable {
    emit Income(msg.sender, msg.value, uint64(now));
    require(currentStage == StageName.PreSale || currentStage == StageName.Sale);
    uint256 weiAmount = msg.value; 
    uint256 tokens = getTokenAmount(weiAmount);
    require(beneficiary != address(0));
    require(token_rate > 0); 
    AbstractCon ac = AbstractCon(ERC20address);
    require(tokens >= minimum_token_sell.mul(10 ** uint256(ac.decimals())));
    require(ac.transferFrom(campaignStages[uint8(currentStage)].tokenKeeper, beneficiary, tokens));
    checkCurrentStage();
    weiRaised = weiRaised.add(weiAmount);
    deposited[beneficiary] = deposited[beneficiary].add(weiAmount);
    emit TokenPurchase(msg.sender, beneficiary, msg.value, tokens);
    if (weiRaised >= softCap)
        withdrawETH();
}

function setERC20address(address newERC20contract) external onlyOwner {
    require(address(newERC20contract) != 0);
    AbstractCon ac = AbstractCon(newERC20contract);
    require(ac.allowance(campaignStages[uint8(currentStage)].tokenKeeper, address(this)) > 0);
    ERC20address = newERC20contract;
}

function buyRaffleTicket(uint256 amount) external {
    require(raffleEndTime >= block.timestamp);
    require(amount > 0);
    uint256 ticketsCost = SafeMath.mul(RAFFLE_TICKET_BASE_GOO_PRICE, amount);
    goo.transferFrom(msg.sender, this, ticketsCost);
    goo.transfer(address(0), (ticketsCost * 95) / 100);
    TicketPurchases storage purchases = ticketsBoughtByPlayer[msg.sender];
    if (purchases.raffleId != raffleId) {
        purchases.numPurchases = 0;
        purchases.raffleId = raffleId;
        rafflePlayers[raffleId].push(msg.sender); 
    }
    if (purchases.numPurchases == purchases.ticketsBought.length) {
        purchases.ticketsBought.length += 1;
    }
    purchases.ticketsBought[purchases.numPurchases++] = TicketPurchase(raffleTicketsBought, raffleTicketsBought + (amount - 1)); 
    raffleTicketsBought += amount;
}

function awardRafflePrize(address checkWinner, uint256 checkIndex) external {
    require(raffleEndTime < block.timestamp);
    require(raffleWinner == 0);
    if (!raffleWinningTicketSelected) {
        drawRandomWinner(); 
    }
    if (checkWinner != 0) {
        TicketPurchases storage tickets = ticketsBoughtByPlayer[checkWinner];
        if (tickets.numPurchases > 0 && checkIndex < tickets.numPurchases && tickets.raffleId == raffleId) {
            TicketPurchase storage checkTicket = tickets.ticketsBought[checkIndex];
            if (raffleTicketThatWon >= checkTicket.startId && raffleTicketThatWon <= checkTicket.endId) {
                assignRaffleWinner(checkWinner); 
                return;
            }
        }
    }
    for (uint256 i = 0; i < rafflePlayers[raffleId].length; i++) {
        address player = rafflePlayers[raffleId][i];
        TicketPurchases storage playersTickets = ticketsBoughtByPlayer[player];
        uint256 endIndex = playersTickets.numPurchases - 1;
        if (raffleTicketThatWon >= playersTickets.ticketsBought[0].startId && raffleTicketThatWon <= playersTickets.ticketsBought[endIndex].endId) {
            for (uint256 j = 0; j < playersTickets.numPurchases; j++) {
                TicketPurchase storage playerTicket = playersTickets.ticketsBought[j];
                if (raffleTicketThatWon >= playerTicket.startId && raffleTicketThatWon <= playerTicket.endId) {
                    assignRaffleWinner(player); 
                    return;
                }
            }
        }
    }
}

function startTokenRaffle(uint256 endTime, address tokenContract, uint256 id, bool hasItemAlready) external {
    require(msg.sender == owner);
    require(block.timestamp < endTime);
    if (raffleId != 0) { 
        require(raffleWinner != 0);
    }
    raffleWinningTicketSelected = false;
    raffleTicketThatWon = 0;
    raffleWinner = 0;
    raffleTicketsBought = 0;
    raffleEndTime = endTime;
    raffleId++;
}

function drawRandomWinner() public {
    require(msg.sender == owner);
    require(raffleEndTime < block.timestamp);
    require(!raffleWinningTicketSelected);
    uint256 seed = raffleTicketsBought + block.timestamp;
    raffleTicketThatWon = addmod(uint256(block.blockhash(block.number - 1)), seed, (raffleTicketsBought + 1));
    raffleWinningTicketSelected = true;
}

