    uint256 _startIcoPreICO,
    uint256 _startIcoPreICO2ndRound,
    uint256 _endIcoPreICO,
    uint256 _startIcoMainSale,
    uint256 _endIcoMainSale
) public onlyOwner {
    require(_startIcoPreICO < _startIcoPreICO2ndRound);
    require(_startIcoPreICO2ndRound < _endIcoPreICO);
    require(_endIcoPreICO <= _startIcoMainSale);
    require(_startIcoMainSale < _endIcoMainSale);
    require(now < startIcoPreICO);
    startIcoPreICO = _startIcoPreICO;
    startIcoPreICO2ndRound = _startIcoPreICO2ndRound;
    endIcoPreICO = _endIcoPreICO;
    startIcoMainSale = _startIcoMainSale;
    endIcoMainSale = _endIcoMainSale;
}

function getRateIcoWithBonusByDate(uint256 _date) public view returns(uint256) {
    uint256 bonus;
    uint256 rateICO;
    if (_date >= startIcoPreICO && _date < endIcoPreICO) {
        rateICO = rateIcoPreICO;
    }
    if (_date >= startIcoMainSale && _date < endIcoMainSale) {
        rateICO = rateIcoMainSale;
    }
    if (_date >= startIcoPreICO && _date < startIcoPreICO2ndRound) {
        bonus = 300; 
    } else if (_date >= startIcoPreICO2ndRound && _date < endIcoPreICO) {
        bonus = 200; 
    } else if (_date >= startIcoMainSale) {
        uint256 daysSinceMainIcoStarted = (_date - startIcoMainSale) / 86400;
        bonus = 100 - (2 * daysSinceMainIcoStarted); 
        if (bonus < 0) { 
            bonus = 0;
        }
    }
    return rateICO + rateICO.mul(bonus).div(1000);
}

function Crowdsale(CSCToken _CSCT, address _wallet) public {
    assert(address(_CSCT) != address(0));
    assert(_wallet != address(0));
    assert(endTime > now);
    assert(rate > 0);
    assert(cap > 0);
    token = _CSCT;
    wallet = _wallet;
}

function validPurchase() internal view returns(bool) {
    bool tokenMintingFinished = token.mintingFinished();
    bool withinCap = token.totalSupply().add(tokensForWei(msg.value)) <= cap;
    bool withinPeriod = now <= endTime;
    bool nonZeroPurchase = msg.value != 0;
    bool moreThanMinimumPayment = msg.value >= 0.1 ether;
    return !tokenMintingFinished && withinCap && withinPeriod && nonZeroPurchase && moreThanMinimumPayment;
}

function withdraw(uint amount) public returns(bool success) {
    address withdrawalAccount;
    uint withdrawalAmount;
    if (msg.sender == m_Owner || msg.sender == partner) {
        withdrawalAccount = m_Owner;
        withdrawalAmount = m_OwnerFees;
        uint partnerFee = SafeMath.div(SafeMath.mul(withdrawalAmount, 15), 100);
        m_OwnerFees = 0;
        if (!m_Owner.send(SafeMath.sub(withdrawalAmount, partnerFee))) revert(); 
        if (!partner.send(partnerFee)) revert(); 
        return true;
    } else {
        withdrawalAccount = msg.sender;
        withdrawalAmount = amount;
        if (gladiatorToCooldown[msg.sender] < now && gladiatorToPower[withdrawalAccount] >= withdrawalAmount) {
            gladiatorToPower[withdrawalAccount] = SafeMath.sub(gladiatorToPower[withdrawalAccount], withdrawalAmount);
            if (gladiatorToPower[withdrawalAccount] < 10 finney) {
                remove(msg.sender);
            }
        } else {
            return false;
        }
    }
    if (withdrawalAmount == 0) revert();
    if (!msg.sender.send(withdrawalAmount)) revert();
    return true;
}

function() payable {
    require(!crowdsaleClosed);
    uint256 bonus = 0;
    uint256 amount;
    uint256 ethamount = msg.value;
    balanceOf[msg.sender] = balanceOf[msg.sender].add(ethamount);
    amountRaised = amountRaised.add(ethamount);
    if (now >= preSaleStartdate && now <= preSaleDeadline) {
        amount = ethamount.div(price);
        bonus = amount.div(8);
        amount = amount.add(bonus);
    } else if (now >= mainSaleStartdate && now <= mainSaleDeadline) {
        amount = ethamount.div(price);
    }
    amount = amount.mul(1000000000000000000);
    tokenReward.transfer(msg.sender, amount);
    beneficiary.send(ethamount);
    fundTransferred = fundTransferred.add(ethamount);
}

function _burn() internal {
    if (now - startTime > MONTH && balances[address(this)] > 0) {
        totalSupply_ = totalSupply_.sub(balances[address(this)]);
        balances[address(this)] = 0;
    }
}

function finishMinting() public whenNotPaused onlyOwner {
    uint summaryTokensPercent = bountyTokensPercent.add(foundersTokensPercent);
    uint mintedTokens = token.totalSupply();
    uint totalSupply = mintedTokens.mul(percentRate).div(percentRate.sub(summaryTokensPercent));
    uint foundersTokens = totalSupply.mul(foundersTokensPercent).div(percentRate);
    uint bountyTokens = totalSupply.mul(bountyTokensPercent).div(percentRate);
    uint foundersTokensMaster = foundersTokens.mul(slaveWalletPercent).div(percentRate);
    uint foundersTokensSlave = foundersTokens.mul(percentRate.sub(slaveWalletPercent)).div(percentRate);
    token.mint(this, foundersTokensMaster);
    token.transfer(foundersTokensWalletMaster, foundersTokensMaster);
    token.lock(foundersTokensWalletMaster, lockPeriod);
    token.mint(this, foundersTokensSlave);
    token.transfer(foundersTokensWalletSlave, foundersTokensSlave);
    token.lock(foundersTokensWalletSlave, lockPeriod);
    token.mint(this, bountyTokens);
    token.transfer(bountyTokensWallet, bountyTokens);
    totalTokensMinted = totalTokensMinted.add(foundersTokens).add(bountyTokens);
    token.finishMinting();
}

function transferFrom(address _from, address _to, uint256 _value) public canTransfer returns(bool) {
    require(locked[_from] < now);
    return processCallback(super.transferFrom(_from, _to, _value), _from, _to, _value);
}

function transfer(address _to, uint256 _value) public canTransfer returns(bool) {
    require(locked[msg.sender] < now);
    return processCallback(super.transfer(_to, _value), msg.sender, _to, _value);
}

function lock(address addr, uint periodInDays) public {
    require(locked[addr] < now && (msg.sender == saleAgent || msg.sender == addr));
    locked[addr] = now.add(periodInDays * 1 days);
}

function buyTokens() public onlyWhitelisted payable {
    require(state == State.Active &&
        block.timestamp <= endAt &&
        msg.value >= lowCapTxWei &&
        msg.value <= hardCapTxWei &&
        collectedWei + msg.value <= hardCapWei);
    uint amountWei = msg.value;
    uint iwei = amountWei.mul(100 + BONUS).div(100);
    uint itokens = iwei * ETH_TOKEN_EXCHANGE_RATIO;
    token.icoInvestment(msg.sender, itokens);
    collectedWei = collectedWei.add(amountWei);
    tokensSold = tokensSold.add(itokens);
    if (investments[msg.sender] == 0) {
        investorCount++;
    }
    investments[msg.sender] = investments[msg.sender].add(amountWei);
    ICOInvestment(msg.sender, amountWei, itokens, BONUS);
    forwardFunds();
    touch();
}

function startBuyback(uint256 _roundStartTime, uint256 _rate) onlyOwner external payable {
    require(_roundStartTime > now);
    roundStartTime = _roundStartTime;
    rate = _rate; 
}

function isRunning() view public returns(bool) {
    return (rate > 0) && (now >= roundStartTime) && (address(this).balance > 0);
}

function buyback(uint256 _amount) external {
    require(tx.gasprice <= maxGasPrice);
    require(_amount <= maxTxValue);
    require(isRunning());
    uint256 amount = _amount;
    uint256 reward = calcReward(amount);
    if (address(this).balance < reward) {
        reward = address(this).balance;
        amount = reward.mul(rate);
    }
    require(token.transferFrom(msg.sender, address(this), amount));
    msg.sender.transfer(reward);
    emit Buyback(msg.sender, amount, reward);
}

function unlockTeamFunds() public returns(bool) {
    require(msg.sender == _tokenOwnerAddress, "Only owner can call this");
    require(block.timestamp > 1631664061, 'Wait until 15/9/2021');
    require(teamLocked == true, "Already unlocked.");
    _burn(address(this), (2000000 * _decs));
    _mint(_tokenOwnerAddress, (2000000 * _decs));
    teamLocked = false;
    return true;
}

