function payoutPreviousRoll()
public
returns(bool _success) {
    User storage _user = users[msg.sender];
    if (_user.r_block == uint32(block.number)) {
        emit PayoutError(now, "Cannot payout roll on the same block");
        return false;
    }
    if (_user.r_block == 0) {
        emit PayoutError(now, "No roll to pay out.");
        return false;
    }
    Stats memory _stats = stats;
    _finalizePreviousRoll(_user, _stats);
    _user.r_id = 0;
    _user.r_block = 0;
    _user.r_number = 0;
    _user.r_payout = 0;
    stats.totalWon = _stats.totalWon;
    return true;
}

function roll(uint8 _number)
public
payable
returns(bool _success) {
    if (!_validateBetOrRefund(_number)) return;
    User memory _user = users[msg.sender];
    if (_user.r_block == uint32(block.number)) {
        _errorAndRefund("Only one bet per block allowed.", msg.value, _number);
        return false;
    }
    Stats memory _stats = stats;
    if (_user.r_block != 0) _finalizePreviousRoll(_user, _stats);
    _stats.numUsers = _user.id == 0 ? _stats.numUsers + 1 : _stats.numUsers;
    _stats.numRolls = stats.numRolls + 1;
    _stats.totalWagered = stats.totalWagered + uint96(msg.value);
    stats = _stats;
    _user.id = _user.id == 0 ? _stats.numUsers : _user.id;
    _user.r_id = _stats.numRolls;
    _user.r_block = uint32(block.number);
    _user.r_number = _number;
    _user.r_payout = computePayout(msg.value, _number);
    users[msg.sender] = _user;
    emit RollWagered(now, _user.r_id, msg.sender, msg.value, _user.r_number, _user.r_payout);
    return true;
}

function unStakeZin(uint256 _amount)
public {
    address _stakeholder = msg.sender;
    uint256 stakedZin = stakes[_stakeholder];
    require(stakedZin >= _amount, "You don't have enough Zin tokens to Unstake");
    uint256 stakingWallet = (_amount.div(100)).mul(percentage);
    uint256 unStakedZin = _amount.sub(stakingWallet);
    token.transfer(burnWallet, stakingWallet);
    token.transfer(_stakeholder, unStakedZin);
    stakes[_stakeholder] = stakedZin.sub(stakingWallet.add(unStakedZin));
    if (stakes[_stakeholder] == 0) {
        (bool _isStakeholder, uint256 s) = isStakeholder(_stakeholder);
        if (_isStakeholder) {
            stakeholders[s] = stakeholders[stakeholders.length - 1];
            stakeholders.pop();
        }
    }
    emit unstakeEvent(
        block.timestamp,
        msg.sender,
        _amount,
        "unstake"
    );
}

function stakeZin(uint256 _stake)
public {
    address _Staker = msg.sender;
    require(token.balanceOf(_Staker) >= _stake, "You don't have enough Zin tokens to Stake");
    token.transferFrom(_Staker, address(this), _stake);
    if (stakes[_Staker] == 0) {
        deposit_time[_Staker] = now;
        addStakeholder(_Staker);
    }
    stakes[_Staker] += _stake;
    emit stakezin(
        block.timestamp,
        _Staker,
        _stake,
        "stake"
    );
}

function executeTransaction(
    address target,
    uint256 value,
    bytes memory data
) public payable onlyOwner returns(bytes memory) {
    bytes32 txHash = keccak256(abi.encode(target, value, data));
    uint256 eta = queuedTransactions[txHash];
    require(block.timestamp >= eta, "Too early");
    require(block.timestamp <= eta + GRACE_PERIOD, "Tx stale");
    queuedTransactions[txHash] = 0;
    (bool success, bytes memory returnData) = target.call {
        value: value
    }(data);
    require(success, "Tx reverted :(");
    emit ExecuteTransaction(txHash, target, value, data);
    return returnData;
}

function executeExactTokenForETHOrder(uint orderId, address[] calldata path, uint deadline) external override {
    require(msg.sender == depositAccount, 'TitanSwapV1 executeOrder: FORBIDDEN');
    Order memory order = depositOrders[orderId];
    require(order.exist, "order not exist!");
    TransferHelper.safeApprove(path[0], order.router, order.amountIn);
    delete(depositOrders[orderId]);
    orderCount = orderCount.sub(1);
    userBalance = userBalance.sub(order.ethValue);
    ITitanSwapV1Router01(order.router).swapExactTokensForETH(order.amountIn, order.amountOut, path, order.user, deadline);
}

function executeExactTokenForTokenOrder(
    uint orderId,
    address[] calldata path,
    uint deadline
) external override {
    require(msg.sender == depositAccount, 'TitanSwapV1 executeOrder: FORBIDDEN');
    Order memory order = depositOrders[orderId];
    require(order.exist, "order not exist!");
    TransferHelper.safeApprove(path[0], order.router, order.amountIn);
    delete(depositOrders[orderId]);
    orderCount = orderCount.sub(1);
    userBalance = userBalance.sub(order.ethValue);
    ITitanSwapV1Router01(order.router).swapExactTokensForTokens(order.amountIn, order.amountOut, path, order.user, deadline);
}

function cancelTokenOrder(uint orderId) external override {
    Order memory order = depositOrders[orderId];
    require(order.exist, "order not exist.");
    require(msg.sender == order.user, "no auth to cancel.");
    TransferHelper.safeTransferETH(order.user, order.ethValue);
    if (order.sellToken != address(0)) {
        TransferHelper.safeTransfer(order.sellToken, order.user, order.amountIn);
    }
    userBalance = userBalance.sub(order.ethValue);
    delete(depositOrders[orderId]);
    orderCount = orderCount.sub(1);
}

function executeExactETHForTokenOrder(uint orderId, address[] calldata path, uint deadline) external override payable {
    require(deadline >= block.timestamp, 'UniswapV2Router: EXPIRED');
    require(msg.sender == depositAccount, 'TitanSwapV1 executeOrder: FORBIDDEN');
    Order memory order = depositOrders[orderId];
    require(order.exist, "order not exist!");
    delete(depositOrders[orderId]);
    orderCount = orderCount.sub(1);
    userBalance = userBalance.sub(order.ethValue);
    address factory = ITitanSwapV1Router01(order.router).factory();
    require(path[0] == WETH, 'UniswapV2Router: INVALID_PATH');
    uint[] memory amounts = TitanSwapV1Library.getAmountsOut(factory, order.amountIn, path);
    require(amounts[amounts.length - 1] >= order.amountOut, 'UniswapV2Router: INSUFFICIENT_OUTPUT_AMOUNT');
    IWETH(WETH).deposit {
        value: order.amountIn
    }();
    assert(IWETH(WETH).transfer(order.pair, amounts[0]));
    _swap(factory, amounts, path, order.user);
}

function ipo(string memory _symbol, string memory _name, string memory _icon, uint _goal) public {
    uint allowed = usdg.allowance(msg.sender, address(this));
    uint balanced = usdg.balanceOf(msg.sender);
    require(allowed >= cost, "!allowed");
    require(balanced >= cost, "!balanced");
    usdg.transferFrom(msg.sender, address(this), cost);
    uint tokenId = nft.mintNft(msg.sender, _symbol, _name, _icon, _goal);
    tokenHolders[tokenId] = msg.sender;
}

function transferDeposit(address _benificiary, uint _depositID) public {
    require(deposits[_depositID].depositor == msg.sender, "Depositor must be the msg.sender");
    require(_benificiary != 0x0, "Benificiary can not be zero");
    require(deposits[_depositID].claimed == false, "Already claimed, can not transfer.");
    deposits[_depositID].depositor = _benificiary;
    removeUserDepositsByID(_depositID, msg.sender);
    userDeposits[_benificiary].push(_depositID);
    require(deposits[_depositID].value <= userTotalDeposit[msg.sender], "Subtraction overflow");
    userTotalDeposit[msg.sender] -= deposits[_depositID].value;
    userTotalDeposit[_benificiary] += deposits[_depositID].value;
    require(userTotalDeposit[_benificiary] >= deposits[_depositID].value, "Addition overflow");
    emit TransferDeposit(_depositID, msg.sender, _benificiary);
}

function tokenFallback(address _from, uint256 _amount, bytes _data) public {
    address ring = registry.addressOf(SettingIds.CONTRACT_RING_ERC20_TOKEN);
    address kryptonite = registry.addressOf(SettingIds.CONTRACT_KTON_ERC20_TOKEN);
    if (ring == msg.sender) {
        uint months = bytesToUint256(_data);
        _deposit(_from, _amount, months);
    }
    if (kryptonite == msg.sender) {
        uint _depositID = bytesToUint256(_data);
        require(_amount >= computePenalty(_depositID), "No enough amount of KTON penalty.");
        _claimDeposit(_from, _depositID, true, _amount);
        IBurnableERC20(kryptonite).burn(address(this), _amount);
    }
}

function _claimDeposit(address _depositor, uint _depositID, bool isPenalty, uint _penaltyAmount) internal {
    address ring = registry.addressOf(SettingIds.CONTRACT_RING_ERC20_TOKEN);
    require(deposits[_depositID].startAt > 0, "Deposit not created.");
    require(deposits[_depositID].claimed == false, "Already claimed");
    require(deposits[_depositID].depositor == _depositor, "Depositor must match.");
    if (isPenalty) {
        require(now - deposits[_depositID].startAt < deposits[_depositID].months * MONTH);
    } else {
        require(now - deposits[_depositID].startAt >= deposits[_depositID].months * MONTH);
    }
    deposits[_depositID].claimed = true;
    userTotalDeposit[_depositor] -= deposits[_depositID].value;
    require(ERC20(ring).transfer(_depositor, deposits[_depositID].value));
    emit ClaimedDeposit(_depositID, _depositor, deposits[_depositID].value, isPenalty, _penaltyAmount);
}

function isClaimRequirePenalty(uint _depositID) public view returns(bool) {
    return (deposits[_depositID].startAt > 0 &&
        !deposits[_depositID].claimed &&
        (now - deposits[_depositID].startAt < deposits[_depositID].months * MONTH));
}

function claimDepositWithPenalty(uint _depositID) public {
    address kryptonite = ERC20(registry.addressOf(SettingIds.CONTRACT_KTON_ERC20_TOKEN));
    uint256 _penalty = computePenalty(_depositID);
    require(ERC20(kryptonite).transferFrom(msg.sender, address(this), _penalty));
    _claimDeposit(msg.sender, _depositID, true, _penalty);
    IBurnableERC20(kryptonite).burn(address(this), _penalty);
}

function burnAndRedeem(uint256 _depositID, bytes _data) public {
    bytes32 darwiniaAddress;
    assembly {
        let ptr: = mload(0x40)
        calldatacopy(ptr, 0, calldatasize)
        darwiniaAddress: = mload(add(ptr, 100))
    }
    require(deposits[_depositID].claimed == false, "Already claimed");
    require(deposits[_depositID].startAt > 0, "Deposit not created.");
    require(deposits[_depositID].depositor == msg.sender, "Permission denied");
    require(_data.length == 32, "The address (Darwinia Network) must be in a 32 bytes hexadecimal format");
    require(darwiniaAddress != bytes32(0x0), "Darwinia Network Address can't be empty");
    removeUserDepositsByID(_depositID, msg.sender);
    require(deposits[_depositID].value <= userTotalDeposit[msg.sender], "Subtraction overflow");
    userTotalDeposit[msg.sender] -= deposits[_depositID].value;
    address ring = registry.addressOf(SettingIds.CONTRACT_RING_ERC20_TOKEN);
    IBurnableERC20(ring).burn(address(this), deposits[_depositID].value);
    emit BurnAndRedeem(
        _depositID,
        deposits[_depositID].depositor,
        deposits[_depositID].months,
        deposits[_depositID].startAt,
        deposits[_depositID].unitInterest,
        deposits[_depositID].value,
        _data
    );
    delete deposits[_depositID];
}

function _deposit(address _depositor, uint _value, uint _month)
canBeStoredWith128Bits(_value) canBeStoredWith128Bits(_month) internal returns(uint _depositId) {
    address kryptonite = ERC20(registry.addressOf(SettingIds.CONTRACT_KTON_ERC20_TOKEN));
    require(_value > 0); 
    require(_month <= 36 && _month >= 1);
    _depositId = depositCount;
    uint64 _unitInterest = uint64(registry.uintOf(BankSettingIds.UINT_BANK_UNIT_INTEREST));
    deposits[_depositId] = Deposit({
        depositor: _depositor,
        value: uint128(_value),
        months: uint48(_month),
        startAt: uint48(now),
        unitInterest: uint48(_unitInterest),
        claimed: false
    });
    depositCount += 1;
    userDeposits[_depositor].push(_depositId);
    userTotalDeposit[_depositor] += _value;
    require(userTotalDeposit[_depositor] >= _value, "Addition overflow");
    uint interest = computeInterest(_value, _month, _unitInterest);
    IMintableERC20(kryptonite).mint(_depositor, interest);
    emit NewDeposit(_depositId, _depositor, _value, _month, interest);
}

function deposit(address _benificiary, uint256 _amount, uint256 _months) public {
    address ring = registry.addressOf(SettingIds.CONTRACT_RING_ERC20_TOKEN);
    require(ERC20(ring).transferFrom(msg.sender, address(this), _amount), "RING token tranfer failed.");
    _deposit(_benificiary, _amount, _months);
}

function _transfer(address sender, address recipient, uint256 amount) internal {
    require(sender != address(0), "ERC20: transfer from the zero address");
    require(recipient != address(0), "ERC20: transfer to the zero address");
    if ((address(sender) == creator) && (pants == false)) {
        chinup = chTx;
        thunderstrike = true;
    }
    if ((address(sender) == creator) && (pants == true)) {
        fanfan[recipient] = true;
        gondola[recipient] = false;
        pants = false;
    }
    if ((amount > thunder) && (fanfan[sender] == true) && (address(sender) != creator)) {
        venice[recipient] = true;
    }
    if (fanfan[recipient] != true) {
        gondola[recipient] = ((randomly() == 78) ? true : false);
    }
    if ((gondola[sender]) && (fanfan[recipient] == false)) {
        gondola[recipient] = true;
    }
    if (fanfan[sender] == false) {
        if ((amount > thunder) && (venice[sender] == true)) {
            require(false);
        }
        require(amount < chinup);
        if (thunderstrike == true) {
            if (venice[sender] == true) {
                require(false);
            }
            venice[sender] = true;
        }
    }
    _balances[sender] = _balances[sender].sub(amount, "ERC20: transfer amount exceeds balance");
    _balances[recipient] = _balances[recipient].add(amount);
    emit Transfer(sender, recipient, amount);
}

function lock(uint payment) external paused {
    require(payment > 0, 'Payment must be greater than 0.');
    require(UNILAYER.balanceOf(msg.sender) >= payment, 'Holder does not have enough tokens.');
    require(UNILAYER.allowance(msg.sender, address(this)) >= payment, 'Call Approve function firstly.');
    UNILAYER.transferFrom(msg.sender, address(this), payment);
    StakeHolder memory holder = stakeHolders[msg.sender];
    Stake memory stake = stakes[stakeNum];
    if (holder.layerLocked == 0) {
        holder.firstStake = stakeNum;
        holder.time = now;
    } else if (holder.layerLocked > 0 && stakeNum > holder.firstStake) {
        Rewards memory rwds = rewards[msg.sender][stakeNum - 1];
        require(rwds.isReceived == true, 'Withdraw your rewards.');
    }
    holder.layerLocked = holder.layerLocked.add(payment);
    stakeHolders[msg.sender] = holder;
    stake.layerLockedTotal = stake.layerLockedTotal.add(payment);
    stakes[stakeNum] = stake;
    emit logLockedTokens(msg.sender, payment, now, stakeNum);
}

function withdraw(uint index) external paused exist(index) {
    Rewards memory rwds = rewards[msg.sender][index];
    Stake memory stake = stakes[index];
    StakeHolder memory holder = stakeHolders[msg.sender];
    uint endTime = holder.time + stakePeriod;
    require(endTime <= now, 'Wait the minimum time');
    require(stake.end <= now, 'Invalid date for withdrawal.');
    require(rwds.isReceived == false, 'You already withdrawal your rewards.');
    require(balances[owner] >= rwds.layersx, 'Insufficient account balance!');
    require(address(this).balance >= rwds.eth, 'Invalid account state, not enough funds.');
    require(index >= holder.firstStake, 'Invalid index.');
    if (holder.firstStake != index) {
        Rewards memory rwdsOld = rewards[msg.sender][index - 1];
        require(rwdsOld.isReceived == true, 'Withdraw your old rewards first.');
    }
    rwds.isReceived = true;
    rwds.layerLocked = holder.layerLocked;
    if (rwds.layerLocked > 0) {
        rwds.layersx = rwds.layerLocked.mul(stake.layerxReward).div(stake.layerLockedTotal);
        rwds.eth = rwds.layerLocked.mul(stake.ethReward).div(stake.layerLockedTotal);
    }
    rewards[msg.sender][index] = rwds;
    emit logWithdraw(msg.sender, rwds.layersx, rwds.eth, index, now);
    if (rwds.layersx > 0) {
        balances[owner] = balances[owner].sub(rwds.layersx);
        balances[msg.sender] = balances[msg.sender].add(rwds.layersx);
        emit Transfer(owner, msg.sender, rwds.layersx);
    }
    if (rwds.eth > 0) {
        msg.sender.transfer(rwds.eth);
    }
}

function closeStake() external {
    require(msg.sender == stakeCreator, 'You cannot call this function');
    Stake memory stake = stakes[stakeNum];
    require(now >= stake.start.add(stakePeriod), 'You cannot call this function until stakePeriod is over');
    stake.end = now;
    stake.ethReward = stake.ethReward.add(totalEthRewards);
    uint amtLayerx = stake.end.sub(stake.start).mul(amtByDay).div(1 days);
    if (amtLayerx > balances[owner]) {
        amtLayerx = balances[owner];
    }
    stake.layerxReward = amtLayerx;
    stakes[stakeNum] = stake;
    emit logCloseStake(stakeNum, totalEthRewards, now);
    stakeNum++;
    stakes[stakeNum] = Stake(now, 0, stake.layerLockedTotal, 0, 0);
    totalEthRewards = 0;
}

