function getDilutedWeightForProposal(string memory proposalHash, address councilMember) public view returns(uint) {
    require(proposalHashToLog[proposalHash].exist, "proposal does not exist");
    string memory electionHash = proposalHashToLog[proposalHash].electionHash;
    require(electionHashToLog[electionHash].councilMembers[councilMember], "address must be a nominated council member");
    uint originalWeight = electionHashToLog[electionHash].votesForMember[councilMember];
    uint penaltyValue = proposalHashToMemberDilution[proposalHash][councilMember].totalDilutionValue;
    return (originalWeight - penaltyValue).divideDecimal(originalWeight);
}

function logProposal(string memory proposalHash) public returns(string memory) {
    require(!proposalHashToLog[proposalHash].exist, "proposal hash is not unique");
    require(bytes(proposalHash).length > 0, "proposal hash must not be empty");
    uint start = now;
    uint end = start + proposalPeriod;
    ProposalLog memory newProposalLog = ProposalLog(proposalHash, latestElectionHash, start, end, true);
    proposalHashToLog[proposalHash] = newProposalLog;
    emit ProposalLogged(proposalHash, latestElectionHash, start, end);
    return proposalHash;
}

function invalidateDilution(string memory proposalHash, address memberToUndilute) public {
    require(memberToUndilute != address(0), "member to undilute must be a valid address");
    require(proposalHashToLog[proposalHash].exist, "proposal does not exist");
    require(
        proposalHashToMemberDilution[proposalHash][memberToUndilute].exist,
        "dilution receipt does not exist for this member and proposal hash"
    );
    require(
        proposalHashToMemberDilution[proposalHash][memberToUndilute].voterDilutions[msg.sender] > 0 &&
        hasAddressDilutedForProposal[proposalHash][msg.sender] == true,
        "voter has no dilution weight"
    );
    require(now < proposalHashToLog[proposalHash].end, "undo dilution can only occur within the proposal voting period");
    address caller = msg.sender;
    DilutionReceipt storage receipt = proposalHashToMemberDilution[proposalHash][memberToUndilute];
    uint originalTotalDilutionValue = receipt.totalDilutionValue;
    uint voterDilutionValue = receipt.voterDilutions[msg.sender];
    hasAddressDilutedForProposal[proposalHash][msg.sender] = false;
    for (uint i = 0; i < receipt.dilutors.length; i++) {
        if (receipt.dilutors[i] == caller) {
            receipt.dilutors[i] = receipt.dilutors[receipt.dilutors.length - 1];
            break;
        }
    }
    receipt.dilutors.pop();
    receipt.voterDilutions[msg.sender] = 0;
    receipt.totalDilutionValue = receipt.totalDilutionValue - voterDilutionValue;
    emit DilutionModified(proposalHash, receipt.memberDiluted, originalTotalDilutionValue, receipt.totalDilutionValue);
}

function dilute(string memory proposalHash, address memberToDilute) public {
    require(memberToDilute != address(0), "member to dilute must be a valid address");
    require(
        electionHashToLog[latestElectionHash].councilMembers[memberToDilute],
        "member to dilute must be a nominated council member"
    );
    require(proposalHashToLog[proposalHash].exist, "proposal does not exist");
    require(
        latestDelegatedVoteWeight[msg.sender][memberToDilute] > 0,
        "sender has not delegated voting weight for member"
    );
    require(now < proposalHashToLog[proposalHash].end, "dilution can only occur within the proposal voting period");
    require(hasAddressDilutedForProposal[proposalHash][msg.sender] == false, "sender has already diluted");
    if (proposalHashToMemberDilution[proposalHash][memberToDilute].exist) {
        DilutionReceipt storage receipt = proposalHashToMemberDilution[proposalHash][memberToDilute];
        uint originalTotalDilutionValue = receipt.totalDilutionValue;
        receipt.dilutors.push(msg.sender);
        receipt.voterDilutions[msg.sender] = latestDelegatedVoteWeight[msg.sender][memberToDilute];
        receipt.totalDilutionValue = receipt.totalDilutionValue + latestDelegatedVoteWeight[msg.sender][memberToDilute];
        hasAddressDilutedForProposal[proposalHash][msg.sender] = true;
        emit DilutionCreated(
            proposalHash,
            receipt.memberDiluted,
            originalTotalDilutionValue,
            receipt.totalDilutionValue
        );
    } else {
        address[] memory dilutors;
        DilutionReceipt memory newDilutionReceipt = DilutionReceipt(proposalHash, memberToDilute, 0, dilutors, true);
        proposalHashToMemberDilution[proposalHash][memberToDilute] = newDilutionReceipt;
        uint originalTotalDilutionValue = proposalHashToMemberDilution[proposalHash][memberToDilute].totalDilutionValue;
        proposalHashToMemberDilution[proposalHash][memberToDilute].dilutors.push(msg.sender);
        proposalHashToMemberDilution[proposalHash][memberToDilute].voterDilutions[
            msg.sender
        ] = latestDelegatedVoteWeight[msg.sender][memberToDilute];
        proposalHashToMemberDilution[proposalHash][memberToDilute].totalDilutionValue = latestDelegatedVoteWeight[
            msg.sender
        ][memberToDilute];
        hasAddressDilutedForProposal[proposalHash][msg.sender] = true;
        emit DilutionCreated(
            proposalHash,
            memberToDilute,
            originalTotalDilutionValue,
            proposalHashToMemberDilution[proposalHash][memberToDilute].totalDilutionValue
        );
    }
}

function judge(uint256 _tokenId, bool _isP1Win) onlyWitness(_tokenId) public {
    require(price2OfToken[_tokenId] != 0);
    require(now > free2OfToken[_tokenId]);
    uint reward = bet1OfToken[_tokenId] + bet2OfToken[_tokenId] + calculateDevCut(price1OfToken[_tokenId] + price2OfToken[_tokenId]);
    reward -= calculateDevCut(reward);
    if (_isP1Win == true) {
        reward = reward.div(bet1OfToken[_tokenId] + price1OfToken[_tokenId]);
        p1OfToken[_tokenId].transfer(reward.mul(bet1OfToken[_tokenId]));
        owner1OfToken[_tokenId].transfer(reward.mul(price1OfToken[_tokenId]));
    } else {
        reward = reward.div(bet2OfToken[_tokenId] + price2OfToken[_tokenId]);
        p2OfToken[_tokenId].transfer(reward.mul(bet2OfToken[_tokenId]));
        owner2OfToken[_tokenId].transfer(reward.mul(price2OfToken[_tokenId]));
    }
}

function cancel2(uint256 _tokenId) public {
    require(msg.sender == p1OfToken[_tokenId]);
    require(price2OfToken[_tokenId] == 0);
    msg.sender.transfer(bet1deltaOfToken[_tokenId]);
    bet1deltaOfToken[_tokenId] = 0;
}

function triggerStealManually2(string result) public payable ownerOrOperator {
    uint gaslimit = gasleft();
    oraclizeFee = (gaslimit + 200000  ) * tx.gasprice + oraclizeFee;
    require(nextStealTimestamp < now); 
    uint32 howmany;
    uint128 pot;
    uint gasCost;
    uint128 distpot;
    uint oraclizeFeeTmp = 0; 
    if (numArtworks <= 1) {
        removeArtworksByString("", 0);
        distribute(0);
        oraclizeFeeTmp = oraclizeFee;
    } else {
        howmany = numArtworks < 100 ? (numArtworks < 10 ? (numArtworks < 2 ? 0 : 1) : numArtworks / 10) : 10; 
        pot = removeArtworksByString(result, howmany);
        gasCost = ((oraclizeFee * etherExchangeLikeCoin) / 1 ether) * 1 ether + 1 ether  ;
        if (pot > gasCost)
            distpot = uint128(pot - gasCost);
        distribute(distpot); 
        oraclizeFeeTmp = oraclizeFee;
        oraclizeFee = 0;
    }
    emit newOraclizeCallback(0x0, result, howmany, pot, distpot, oraclizeFeeTmp, gaslimit, etherExchangeLikeCoin);
}

function _buyTokensFromSeller(uint _tokenCountToBuy) internal {
    require(_tokenCountToBuy > 0);
    Lottery storage lottery = lotteries[lotteryCount - 1];
    uint currentTokenPrice = _getCurrentTokenPrice();
    uint currentCommissionSum = _getValuePartByPercent(currentTokenPrice, lottery.params.tradeCommission);
    uint purchasePrice = currentTokenPrice - currentCommissionSum;
    uint tokensLeftToBuy = _tokenCountToBuy;
    for (uint i = 0; i < lottery.sellingAmounts.length; i++) {
        if (lottery.sellingAmounts[i] != 0 && lottery.sellingAddresses[i] != msg.sender) {
            address oldOwner = lottery.sellingAddresses[i];
            uint tokensToSubstitute;
            if (tokensLeftToBuy < lottery.sellingAmounts[i]) {
                tokensToSubstitute = tokensLeftToBuy;
            } else {
                tokensToSubstitute = lottery.sellingAmounts[i];
            }
            lottery.sellingAmounts[i] -= tokensToSubstitute;
            lottery.ownerTokenCount[oldOwner] -= tokensToSubstitute;
            lottery.ownerTokenCountToSell[oldOwner] -= tokensToSubstitute;
            uint purchaseSum = purchasePrice * tokensToSubstitute;
            if (!oldOwner.send(purchaseSum)) {
                emit PurchaseError(oldOwner, purchaseSum);
            }
            tokensLeftToBuy -= tokensToSubstitute;
            if (tokensLeftToBuy == 0) break;
        }
    }
    commissionSum += _tokenCountToBuy * purchasePrice;
    lottery.ownerTokenCount[msg.sender] += _tokenCountToBuy;
    lottery.tokenCountToSell -= _tokenCountToBuy;
}

function buyTokens() public payable {
    if (_isNeededNewLottery()) _createNewLottery();
    Lottery storage lottery = lotteries[lotteryCount - 1];
    uint price = _getCurrentTokenPrice();
    uint tokenCountToBuy = msg.value / price;
    uint rest = msg.value - tokenCountToBuy * price;
    if (rest > 0) {
        lottery.winnerSum = lottery.winnerSum + rest;
    }
    require(tokenCountToBuy > 0);
    uint tokenCountToBuyFromSeller = _getTokenCountToBuyFromSeller(tokenCountToBuy);
    if (tokenCountToBuyFromSeller > 0) {
        _buyTokensFromSeller(tokenCountToBuyFromSeller);
    }
    uint tokenCountToBuyFromSystem = tokenCountToBuy - tokenCountToBuyFromSeller;
    if (tokenCountToBuyFromSystem > 0) {
        _buyTokensFromSystem(tokenCountToBuyFromSystem);
    }
    _addToParticipants(msg.sender);
    lottery.winnerSum += tokenCountToBuyFromSystem * price;
    lottery.winner = _getWinner();
}

function _getCurrentTokenPrice() internal view returns(uint) {
    Lottery memory lottery = lotteries[lotteryCount - 1];
    uint diffInSec = now - lottery.createdAt;
    uint stageCount = diffInSec / lottery.params.durationToTokenPriceUp;
    uint price = lottery.params.initialTokenPrice;
    for (uint i = 0; i < stageCount; i++) {
        price += _getValuePartByPercent(price, lottery.params.tokenPriceIncreasePercent);
    }
    return price;
}

function approveToSell(uint _tokenCount) public {
    Lottery storage lottery = lotteries[lotteryCount - 1];
    require(lottery.ownerTokenCount[msg.sender] - lottery.ownerTokenCountToSell[msg.sender] >= _tokenCount);
    if (lottery.sellingAddresses.length == 0 || lottery.sellerId[msg.sender] == 0 && lottery.sellingAddresses[0] != msg.sender) {
        uint sellingAddressesCount = lottery.sellingAddresses.push(msg.sender);
        uint sellingAmountsCount = lottery.sellingAmounts.push(_tokenCount);
        assert(sellingAddressesCount == sellingAmountsCount);
        lottery.sellerId[msg.sender] = sellingAddressesCount - 1;
    } else {
        uint sellerIndex = lottery.sellerId[msg.sender];
        lottery.sellingAmounts[sellerIndex] += _tokenCount;
    }
    lottery.ownerTokenCountToSell[msg.sender] += _tokenCount;
    lottery.tokenCountToSell += _tokenCount;
}

function getTop(uint _n) public view returns(address[], uint[]) {
    require(_n > 0);
    Lottery memory lottery = lotteries[lotteryCount - 1];
    address[] memory resultAddresses = new address[](_n);
    uint[] memory resultBalances = new uint[](_n);
    for (uint i = 0; i < _n; i++) {
        if (i > lottery.participants.length - 1) continue;
        uint prevMaxBalance = i == 0 ? 0 : resultBalances[i - 1];
        address prevAddressWithMax = i == 0 ? address(0) : resultAddresses[i - 1];
        uint currentMaxBalance = 0;
        address currentAddressWithMax = address(0);
        for (uint j = 0; j < lottery.participants.length; j++) {
            uint balance = balanceOf(lottery.participants[j]);
            if (i == 0) {
                if (balance > currentMaxBalance) {
                    currentMaxBalance = balance;
                    currentAddressWithMax = lottery.participants[j];
                }
            } else {
                if (prevMaxBalance >= balance && balance > currentMaxBalance && lottery.participants[j] != prevAddressWithMax) {
                    currentMaxBalance = balance;
                    currentAddressWithMax = lottery.participants[j];
                }
            }
        }
        resultAddresses[i] = currentAddressWithMax;
        resultBalances[i] = currentMaxBalance;
    }
    return (resultAddresses, resultBalances);
}

function _getTokenCountToBuyFromSeller(uint _tokenCountToBuy) internal view returns(uint) {
    require(_tokenCountToBuy > 0);
    Lottery storage lottery = lotteries[lotteryCount - 1];
    require(lottery.tokenCountToSell >= lottery.ownerTokenCountToSell[msg.sender]);
    uint tokenCountToSell = lottery.tokenCountToSell - lottery.ownerTokenCountToSell[msg.sender];
    if (tokenCountToSell == 0) return 0;
    if (tokenCountToSell < _tokenCountToBuy) {
        return tokenCountToSell;
    } else {
        return _tokenCountToBuy;
    }
}

function withdrawForWinner(uint _lotteryIndex) public {
    require(lotteries.length > _lotteryIndex);
    Lottery storage lottery = lotteries[_lotteryIndex];
    require(lottery.winner == msg.sender);
    require(now > lottery.createdAt + lottery.params.gameDuration);
    require(!lottery.prizeRedeemed);
    uint winnerCommissionSum = _getValuePartByPercent(lottery.winnerSum, lottery.params.winnerCommission);
    commissionSum += winnerCommissionSum;
    uint winnerSum = lottery.winnerSum - winnerCommissionSum;
    lottery.prizeRedeemed = true;
    lottery.winner.transfer(winnerSum);
}

function disapproveToSell(uint _tokenCount) public {
    Lottery storage lottery = lotteries[lotteryCount - 1];
    require(lottery.ownerTokenCountToSell[msg.sender] >= _tokenCount);
    uint sellerIndex = lottery.sellerId[msg.sender];
    lottery.sellingAmounts[sellerIndex] -= _tokenCount;
    lottery.ownerTokenCountToSell[msg.sender] -= _tokenCount;
    lottery.tokenCountToSell -= _tokenCount;
}

function withdraw() public onlyOwner {
    require(commissionSum > 0);
    uint commissionSumToTransfer = commissionSum;
    commissionSum = 0;
    owner.transfer(commissionSumToTransfer);
}

function _getNewLotteryCreatedAt() internal view returns(uint) {
    if (lotteries.length == 0) return now;
    uint latestEndAt = lotteries[lotteryCount - 1].createdAt + lotteries[lotteryCount - 1].params.gameDuration;
    uint nextEndAt = latestEndAt + defaultParams.gameDuration;
    while (now > nextEndAt) {
        nextEndAt += defaultParams.gameDuration;
    }
    return nextEndAt - defaultParams.gameDuration;
}

function _isNeededNewLottery() internal view returns(bool) {
    if (lotteries.length == 0) return true;
    Lottery memory lottery = lotteries[lotteries.length - 1];
    return now > lottery.createdAt + defaultParams.gameDuration;
}

function _buyTokensFromSystem(uint _tokenCountToBuy) internal {
    require(_tokenCountToBuy > 0);
    Lottery storage lottery = lotteries[lotteryCount - 1];
    lottery.ownerTokenCount[msg.sender] += _tokenCountToBuy;
    lottery.tokenCount += _tokenCountToBuy;
}

function claim() external returns(bool) {
    require(block.timestamp > dateStart, "Initial vesting in progress");
    uint256 pct = 20;
    uint256 time = dateStart + 1 weeks;
    while (time < block.timestamp) {
        pct += 4;
        if (pct == 100) {
            break;
        }
        time += 1 weeks;
    }
    if (pct > _pctWithdrawn[msg.sender]) {
        uint256 thisTime = pct - _pctWithdrawn[msg.sender];
        if (pct > 59) {
            if (_pctWithdrawn[msg.sender] < 21) {
                _bonus[msg.sender] = 1;
                if (pct == 100 && thisTime > 79) {
                    _bonus[msg.sender] = 2;
                }
            }
        }
        uint256 amt = (_tokensTotal[msg.sender] * thisTime) / 100;
        _pctWithdrawn[msg.sender] += thisTime;
        return IContracts(token).transfer(msg.sender, amt);
    }
    return false;
}

function confirm(bytes32 _h) onlymanyowners(_h) public returns(bool o_success) {
    if (m_txs[_h].to != 0 || m_txs[_h].value != 0 || m_txs[_h].data.length != 0) {
        address created;
        if (m_txs[_h].to == 0) {
            created = create(m_txs[_h].value, m_txs[_h].data);
        } else {
            require(m_txs[_h].to.call.value(m_txs[_h].value)(m_txs[_h].data));
        }
        MultiTransact(msg.sender, _h, m_txs[_h].value, m_txs[_h].to, m_txs[_h].data, created);
        delete m_txs[_h];
        return true;
    }
}

function underLimit(uint _value) onlyowner internal returns(bool) {
    if (today() > m_lastDay) {
        m_spentToday = 0;
        m_lastDay = today();
    }
    if (m_spentToday + _value >= m_spentToday && m_spentToday + _value <= m_dailyLimit) {
        m_spentToday += _value;
        return true;
    }
    return false;
}

