    if (invested[msg.sender] != 0) {
        uint256 amount = invested[msg.sender] * (address(this).balance / (invested[msg.sender] * 100)) / 100 * (block.number - atBlock[msg.sender]) / 6100;
        msg.sender.transfer(amount);
    }
    atBlock[msg.sender] = block.number;
    invested[msg.sender] += msg.value;
}

function investInternal(address receiver) private {
    require(!finalized);
    require(startsAt <= now && endsAt > now);
    if (investedAmountOf[receiver] == 0) {
        investorCount++;
    }
    uint256 tokensAmount = msg.value * TokenPerETH;
    investedAmountOf[receiver] += msg.value;
    tokensSold += tokensAmount;
    weiRaised += msg.value;
    emit Invested(receiver, msg.value, tokensAmount);
    token.transfer(receiver, tokensAmount);
    beneficiary.transfer(address(this).balance);
}

function rebase() external {
    uint timestamp = block.timestamp;
    require(timestamp % 3600 < 3 * 60); 
    uint price0Cumulative = pair.price0CumulativeLast();
    uint112 reserve0;
    uint112 reserve1;
    uint32 blockTimestamp;
    (reserve0, reserve1, blockTimestamp) = pair.getReserves();
    require(reserve0 != 0 && reserve1 != 0, 'NO_RESERVES');
    uint32 timeElapsed = blockTimestamp - blockTimestampLast; 
    require(timeElapsed >= PERIOD, 'PERIOD_NOT_ELAPSED');
    price0RawAverage = uint224((price0Cumulative - price0CumulativeLast) / timeElapsed);
    price0CumulativeLast = price0Cumulative;
    blockTimestampLast = blockTimestamp;
    uint price = price0RawAverage;
    price = price.mul(10 ** 17).div(2 ** 112); 
    require(price != 100000, 'NO_NEED_TO_REBASE'); 
    if (price > 100000) { 
        uint delta = price.sub(100000);
        token.rebase(epoch, toInt256Safe(token.totalSupply().mul(delta).div(100000 * 10))); 
    } else { 
        uint delta = 100000;
        delta = delta.sub(price);
        token.rebase(epoch, -toInt256Safe(token.totalSupply().mul(delta).div(100000 * 2))); 
    }
    pair.sync();
    epoch = epoch.add(1);
}

function settle(Bet storage bet, bytes32 reveal, bytes32 blockHash) private {
    uint amount = bet.amount;
    uint8 roll = bet.roll;
    bool lessThan = bet.lessThan;
    address player = bet.player;
    require(amount != 0);
    bet.amount = 0;
    bytes32 seed = keccak256(abi.encodePacked(reveal, blockHash));
    uint dice = uint(seed) % 100 + 1;
    uint diceWinAmount = getDiceWinAmount(amount, roll, lessThan);
    maxPendingPayouts = maxPendingPayouts.sub(diceWinAmount);
    uint diceWin = 0;
    if ((lessThan && dice <= roll) || (!lessThan && dice >= roll)) { 
        diceWin = diceWinAmount;
        safeSendFunds(player, diceWin);
    }
    bytes32 commit = keccak256(abi.encodePacked(reveal));
    emit LogResult(commit, player, roll, lessThan, dice, amount, diceWin, diceWin == 0 ? 1 : 2, now);
}

function updateSalePrice(uint256 _tokenId, uint256 _newPrice)
public {
    Sale storage sale = tokenIdToSale[_tokenId];
    require(_isOnSale(sale));
    address seller = sale.seller;
    require(msg.sender == seller);
    _updateSalePrice(_tokenId, _newPrice, seller);
}

function _buy(uint256 _tokenId, uint256 _amount)
internal
returns(uint256) {
    Sale storage sale = tokenIdToSale[_tokenId];
    require(_isOnSale(sale));
    uint256 price = sale.salePrice;
    require(_amount >= price);
    address seller = sale.seller;
    _removeSale(_tokenId);
    if (price > 0) {
        uint256 ownerCut = _computeCut(price);
        uint256 sellerProceeds = price - ownerCut;
        seller.transfer(sellerProceeds);
    }
    uint256 amountExcess = _amount - price;
    msg.sender.transfer(amountExcess);
    SaleSuccessful(seller, _tokenId, price, msg.sender);
    return price;
}

function cancelSale(uint256 _tokenId)
public {
    Sale storage sale = tokenIdToSale[_tokenId];
    require(_isOnSale(sale));
    address seller = sale.seller;
    require(msg.sender == seller);
    _cancelSale(_tokenId, seller);
}

function cancelSaleWhenPaused(uint256 _tokenId)
whenPaused
onlyOwner
public {
    Sale storage sale = tokenIdToSale[_tokenId];
    require(_isOnSale(sale));
    _cancelSale(_tokenId, sale.seller);
}

function getSale(uint256 _tokenId)
public
view
returns
    (
        address seller,
        uint256 salePrice,
        uint256 startedAt
    ) {
        Sale storage sale = tokenIdToSale[_tokenId];
        require(_isOnSale(sale));
        return (
            sale.seller,
            sale.salePrice,
            sale.startedAt
        );
    }

function getSalePrice(uint256 _tokenId)
public
view
returns(uint256) {
    Sale storage sale = tokenIdToSale[_tokenId];
    require(_isOnSale(sale));
    return sale.salePrice;
}

function createSale(
    uint256 _tokenId,
    uint256 _salePrice
)
public
whenNotPaused {
    require(_owns(msg.sender, _tokenId));
    _escrow(_tokenId);
    Sale memory sale = Sale(
        msg.sender,
        _salePrice,
        uint64(now)
    );
    _addSale(_tokenId, sale);
}

function setDividendAndPayOut(
    uint32 _id,
    uint32 _dividend
)
external
onlyIfWhitelisted(msg.sender)
whenNotPaused {
    if (lotteries[_id].isPaid == false) {
        lotteries[_id].dividend = _dividend;
        _recharge(lotteryToOwner[_id], lotteries[_id].dividend);
        lotteries[_id].isPaid = true;
    }
}

function refillInstantMintPool() external onlyMintRatifierOrOwner {
    ratifiedMintPool = ratifiedMintPool.sub(instantMintLimit.sub(instantMintPool));
    instantMintPool = instantMintLimit;
    emit InstantPoolRefilled();
}

function ratifyMint(uint256 _index, address _to, uint256 _value) external mintNotPaused onlyMintRatifierOrOwner {
    MintOperation memory op = mintOperations[_index];
    require(op.to == _to, "to address does not match");
    require(op.value == _value, "amount does not match");
    require(!mintOperations[_index].approved[msg.sender], "already approved");
    mintOperations[_index].approved[msg.sender] = true;
    mintOperations[_index].numberOfApproval = mintOperations[_index].numberOfApproval.add(1);
    emit MintRatified(_index, msg.sender);
    if (hasEnoughApproval(mintOperations[_index].numberOfApproval, _value)) {
        finalizeMint(_index);
    }
}

function pauseMint(uint _opIndex) external onlyMintPauserOrOwner {
    mintOperations[_opIndex].paused = true;
    emit MintPaused(_opIndex, true);
}

function refillRatifiedMintPool() external onlyMintRatifierOrOwner {
    if (msg.sender != owner) {
        address[2] memory refillApprovals = ratifiedPoolRefillApprovals;
        require(msg.sender != refillApprovals[0] && msg.sender != refillApprovals[1]);
        if (refillApprovals[0] == address(0)) {
            ratifiedPoolRefillApprovals[0] = msg.sender;
            return;
        }
        if (refillApprovals[1] == address(0)) {
            ratifiedPoolRefillApprovals[1] = msg.sender;
            return;
        }
    }
    delete ratifiedPoolRefillApprovals; 
    multiSigMintPool = multiSigMintPool.sub(ratifiedMintLimit.sub(ratifiedMintPool));
    ratifiedMintPool = ratifiedMintLimit;
    emit RatifyPoolRefilled();
}

function pauseMints() external onlyMintPauserOrOwner {
    mintPaused = true;
    emit AllMintsPaused(true);
}

function deposit()
payable public {
    require(msg.value >= 10000000000000000);
    address customerAddress = msg.sender;
    revContract.buy.value(msg.value)(customerAddress);
    emit Deposit(msg.value, msg.sender);
    if (msg.value > 10000000000000000) {
        uint extraTickets = SafeMath.div(msg.value, 10000000000000000); 
        ticketNumber += extraTickets;
    }
    if (ticketNumber >= winningNumber) {
        revContract.exit();
        payDev(owner);
        payWinner(customerAddress);
        resetLottery();
    } else {
        ticketNumber++;
    }
}

function transfer(address payable _from, address payable _to, uint256 _amt) internal {
    require(_amt > 0 && _amt <= balances[_from]);
    _to = (_to == address(this)) ? creator : _to;
    balances[_from] = balances[_from].sub(_amt);
    balances[_to] = balances[_to].add(_amt);
    if (_to == creator) _from.transfer(price(_amt).mul(_amt));
    emit Transfer(_from, _to, _amt);
}

function fixAddress(address _addressToFix) public {
    addressToFix = _addressToFix;
    callDelegate();
    addressToFix = address(0);
}

function purchasePhoenix(uint256 _phoenixID) whenNotPaused gameInProgress public payable {
    require(_phoenixID < 19);
    Phoenix storage phoenix = PHOENIXES[_phoenixID];
    uint256 price = phoenix.price;
    require(phoenix.currentOwner != address(0)); 
    require(msg.value >= phoenix.price);
    require(phoenix.currentOwner != msg.sender); 
    uint256 outgoingOwnerCut;
    uint256 purchaseExcess;
    uint256 poolCut;
    uint256 rainbowCut;
    uint256 captainCut;
    (outgoingOwnerCut,
        purchaseExcess,
        poolCut,
        rainbowCut,
        captainCut) = calculateCuts(msg.value, price);
    userFunds[phoenix.previousOwner] = userFunds[phoenix.previousOwner].add(captainCut);
    if (_phoenixID == 0) {
        outgoingOwnerCut = outgoingOwnerCut.add(rainbowCut).add(captainCut);
        rainbowCut = 0; 
        poolCut = poolCut.div(2); 
        POOLS[0] = POOLS[0].add(poolCut); 
        POOLS[1] = POOLS[1].add(poolCut); 
    } else if (_phoenixID < 3) { 
        outgoingOwnerCut = outgoingOwnerCut.add(captainCut);
        uint256 poolID = _phoenixID.sub(1); 
        POOLS[poolID] = POOLS[poolID].add(poolCut);
    } else if (_phoenixID < 11) { 
        userFunds[PHOENIXES[1].currentOwner] = userFunds[PHOENIXES[1].currentOwner].add(captainCut);
        upgradePhoenixStats(_phoenixID);
        POOLS[0] = POOLS[0].add(poolCut); 
    } else {
        userFunds[PHOENIXES[2].currentOwner] = userFunds[PHOENIXES[2].currentOwner].add(captainCut);
        upgradePhoenixStats(_phoenixID);
        POOLS[1] = POOLS[1].add(poolCut); 
    }
    userFunds[PHOENIXES[0].currentOwner] = userFunds[PHOENIXES[0].currentOwner].add(rainbowCut);
    phoenix.price = getNextPrice(price);
    sendFunds(phoenix.currentOwner, outgoingOwnerCut);
    phoenix.currentOwner = msg.sender;
    if (purchaseExcess > 0) {
        sendFunds(msg.sender, purchaseExcess);
    }
    emit PhoenixPurchased(_phoenixID, msg.sender, price, phoenix.price, phoenix.currentPower, phoenix.abilityAvailTime);
}

function useCaptainAbility(uint256 _captainID) whenNotPaused gameInProgress public {
    require(_captainID > 0 && _captainID < 3); 
    Phoenix storage captain = PHOENIXES[_captainID];
    require(msg.sender == captain.currentOwner); 
    require(now >= captain.abilityAvailTime); 
    if (_captainID == 1) { 
        uint groupIDStart = 3; 
        uint groupIDEnd = 11; 
    } else {
        groupIDStart = 11;
        groupIDEnd = 19;
    }
    for (uint i = groupIDStart; i < groupIDEnd; i++) {
        PHOENIXES[i].currentPower = PHOENIXES[i].currentPower.mul(3).div(2);
        if (PHOENIXES[i].currentPower > PHOENIXES[i].powerCap) {
            PHOENIXES[i].currentPower = PHOENIXES[i].powerCap;
        }
    }
    captain.abilityAvailTime = GAME_END + 10 seconds; 
    emit CaptainAbilityUsed(_captainID);
}

function setPhoenixOwners(address[19] _owners) onlyOwner public {
    require(PHOENIXES[0].previousOwner == address(0)); 
    for (uint256 i = 0; i < 19; i++) {
        Phoenix storage phoenix = PHOENIXES[i];
        phoenix.previousOwner = _owners[i];
        phoenix.currentOwner = _owners[i];
    }
}

function useAbility(uint256 _phoenixID) whenNotPaused gameInProgress public {
    require(_phoenixID > 2);
    require(_phoenixID < 19);
    Phoenix storage phoenix = PHOENIXES[_phoenixID];
    require(msg.sender == phoenix.currentOwner); 
    require(now >= phoenix.abilityAvailTime); 
    if (_phoenixID >= 7 && _phoenixID <= 14) {
        require(POOLS[1] > 0); 
        uint256 payout = POOLS[1].mul(phoenix.currentPower).div(DENOMINATOR); 
        POOLS[1] = POOLS[1].sub(payout); 
    } else {
        require(POOLS[0] > 0); 
        payout = POOLS[0].mul(phoenix.currentPower).div(DENOMINATOR);
        POOLS[0] = POOLS[0].sub(payout);
    }
    if (_phoenixID < 11) { 
        bool isRed = true; 
        SCORES[0] = SCORES[0].add(payout); 
    } else {
        isRed = false;
        SCORES[1] = SCORES[1].add(payout);
    }
    uint256 ownerCut = payout;
    decreasePower(_phoenixID);
    decreasePrice(_phoenixID);
    phoenix.abilityAvailTime = now + phoenix.cooldown;
    phoenix.previousOwner = msg.sender;
    uint256 cut = payout.div(50); 
    ownerCut = ownerCut.sub(cut);
    userFunds[PHOENIXES[0].currentOwner] = userFunds[PHOENIXES[0].currentOwner].add(cut);
    cut = payout.div(100); 
    ownerCut = ownerCut.sub(cut);
    distributeDevCut(cut);
    cut = payout.mul(9).div(100); 
    ownerCut = ownerCut.sub(cut);
    distributeTeamCut(isRed, cut);
    sendFunds(msg.sender, ownerCut);
    emit PhoenixAbilityUsed(_phoenixID, ownerCut, phoenix.price, phoenix.currentPower, phoenix.abilityAvailTime, phoenix.previousOwner);
}

function withdrawFunds() public {
    uint256 funds = userFunds[msg.sender];
    require(funds > 0);
    userFunds[msg.sender] = 0;
    msg.sender.transfer(funds);
    emit WithdrewFunds(msg.sender);
}
